INSERT INTO public.recipes (
  title, slug, description, ingredients, cleaned_ingredients,
  instructions, total_time_mins, cuisine, diet, source_url,
  image_url, image_status, image_source, data_source, servings, review_count, is_featured
) VALUES
  ('Thayir Semiya Recipe (Curd Semiya)', 'thayir-semiya-recipe-curd-semiya', 'Thayir Semiya or Curd Vermicelli is a quick dish which you can make for lunch. If you are bored of eating curd rice everyday, you can always make this Thayir semiya or curd semiya for a change. In South India, people consume curd everyday.', '["1/2 cup Semiya (Vermicelli) , roasted", "1 cup Curd (Dahi / Yogurt)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon White Urad Dal (Split)", "pinch Asafoetida (hing)", "1 sprig Curry leaves", "2 teaspoon Oil", "Raw Peanuts (Moongphali)", "1 sprig Curry leaves", "2 teaspoon Oil", "5 to 6 Cashew nuts , for garnishing"]'::jsonb, ARRAY['cashew nuts', 'asafoetida (hing)', 'mustard seeds', 'curd', 'white urad dal (split)', 'semiya (vermicelli)', 'curry leaves', 'peanuts (moongphali)', 'sunflower oil']::text[], '["To begin making the Thayir Semiya recipe, firstly boil the vermicelli in 2 cups water.", "Drain it and spread on a colander.Pass cold water through it.", "This ensures that the vermicelli does not become sticky.", "Keep it aside and let it cool down.Heat a kadai/wok and add oil.", "Add the peanuts and roast till it turns brownish.", "Remove and keep it aside.In the same kadai, add more oil if needed and add the mustard seeds and after it splutters add the other ingredients meant for tempering.Add the boiled vermicelli and mix everything.", "Add salt to taste and mix.Finally just before serving add curd and mix well.", "Serve Thayir Semiya on its own for a light and healthy lunch or dinner."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Thayir_Curd_Semiya_recipe_Yogurt_Vermicelli_South_indian_Lunch_recipe-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1.Thayir_Curd_Semiya_recipe_Yogurt_Vermicelli_South_indian_Lunch_recipe-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Style Kara Kuzhambu Recipe with Potato and Brinjal', 'chettinad-style-kara-kuzhambu-recipe-with-potato-and-brinjal', 'Chettinad Style Kara Kuzhambu Recipe with Potato and Brinjal is a finger licking good recipe made the Chettinad way.', '["1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "2 teaspoons Coriander (Dhania) Seeds", "1 teaspoon Fennel seeds (Saunf)", "2 Dry Red Chillies", "1/4 cup Fresh coconut , grated", "1/2 cup Pearl onions (Sambar Onions) , quartered", "5 cloves Garlic , finely chopped", "2 Tomatoes , finely chopped", "2 Potatoes (Aloo) , cut into medium sized pieces", "2 Brinjal (Baingan / Eggplant) , cut into wedges", "1 tablespoon Jaggery", "1 cup Tamarind Water", "1 teaspoon Sambar Powder", "1 teaspoon Gingelly oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 sprig Curry leaves"]'::jsonb, ARRAY['methi seeds', 'fenugreek seeds', 's coriander', 'dhania', 'fennel seeds', 'saunf', 'dry red chillies', 'fresh coconut', 'pearl onions', 'sambar onions', 's garlic', 'tomatoes', 'potatoes', 'aloo', 'brinjal', 'baingan / eggplant', 'jaggery', 'tamarind water', 'sambar powder', 'gingelly oil', 'mustard seeds', 'rai/ kadugu', 'curry leaves']::text[], '["To begin making the Chettinad Style Kara Kuzhambu Recipe, we will first make the masala.", "Heat a small pan on medium heat; add fenugreek seeds, coriander seeds, fennel seeds, red chillies.", "Roast these spices until the aroma wafts in the air.", "Stir in the freshly grated coconut and roast for another 2 to 3 minutes.", "Turn off the heat and allow the spices to cool.", "Transfer the spices into a mixer jar, add 1/2 cup warm water and grind to make a smooth paste.To cook the kara kuzhambu, heat oil in a pressure cooker over medium heat; add the onion, garlic and saute for a few minutes until the onion softens.", "Add the chopped tomatoes and saute until the tomatoes are mushy.Stir in the potatoes, brinjal, jaggery, tamarind water, sambar powder and salt.", "Pressure cook for 3 to whistles and turn off the heat and allow the pressure to release naturally.In the meantime, make the seasoning; heat oil in a tadka pan; add the mustard seeds and curry leaves and allow it to crackle.", "Turn off the heat and keep aside.", "Once the pressure releases, stir in the coconut mixture, the seasoning mixture and give the Chetinnad Kara Kuzhambu a brisk boil for 3 to 4 minutes.", "Check the salt and adjust according to taste.Serve hot Chettinadu Style Potato Kaarakozhambu along with\u00a0Steamed Rice,\u00a0Beetroot Thoran\u00a0and\u00a0Elai Vadam\u00a0for a weekday meal."]'::jsonb, 75, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/mkavya87-gmail.com/Chettinad_Style_Kara_Kuzhambu_Recipe_with_Potato_and_Brinjal_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/2.Chettinad_Style_Kara_Kuzhambu_Recipe_with_Potato_and_Brinjal_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Chana Ros Recipe (White Peas Curry)', 'goan-chana-ros-recipe-white-peas-curry', 'Goan Chana Ros is a vegetarian dish from Goan cuisine made with dried white peas (safed vatana). In Ros recipes, we add freshly grated coconut, instead of roasted coconut which is used for many other Goan dishes. Simply roast the spices and grind along with freshly grated coconut and add to the boiled white peas to prepare this recipe. Serve Goan Chana Ros recipe with steamed rice, Kelyachyo Fodi (banana) to have a nice Goan vegetarian meal. You can also serve chana Ros with bread and rotis, but we prefer to have it as a side dish with rice.', '["1/2 cup Dried Green Peas (Vatana) , soaked overnight", "1/2 Onion , chopped", "3 tablespoon Fresh coconut , grated", "4 Dry Red Chillies", "1-1/2 teaspoon Coriander (Dhania) Seeds", "3 Cloves (Laung)", "1 inch Tamarind", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'dried green peas (vatana)', 'coconut', 'dry red chillies', 'onion', 'coriander (dhania) seeds', 'tamarind', 'turmeric powder', 'cloves (laung)']::text[], '["To prepare Goan Chana Ros recipe, soak the white peas in water for 8 hours or overnight.Pressure cook the white peas along with chopped onions by adding 1 cup water for 4-5 whistles or till boiled.", "Let the pressure from pressure cooker get released on its own.Dry roast coriander seeds, dry red chilies and cloves together, till nice aroma gets emitted from coriander seeds.", "Let it cool down.Take a Mixer and add grated coconut, tamarind and dry roasted spices.", "Add 1/2 to 3/4 cup water and grind this into a smooth paste.Now take a Kadai and add the ground gravy to it.", "Switch on the gas and keep it on low flame.After 5 minutes, add the boiled white peas along with onion to the gravy and mix well.", "If the gravy is thick, add remaining water from the pressure cooker and mix.Add salt to taste and simmer for 10 minutes before switching off the gas.Serve Goan Chana Ros recipe with\u00a0hot rice,\u00a0Kelyachyo Fodi (banana)."]'::jsonb, 30, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Goan_Chana_Ross.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/3.Goan_Chana_Ross.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Minced Meat And Egg Croquettes Recipe', 'minced-meat-and-egg-croquettes-recipe', 'The croquette is usually cigar shaped or cylindrical. A fried cylindrical roll that has one of following stuffing minced meat, boiled eggs, fish, vegetables. Today I am sharing a croquette recipe that used minced meat as the main ingredient instead of potato and whole boiled eggs used for stuffing. Its one of those delicious appetisers that you would be happy to serve to your guests. It’s so good and easy to make. Since I used minced mutton I cooked the meat first with spices and then shaped it into cylindrical with boiled eggs as stuffing, rolled in floor, eggs wash and bread crumbs then deep fried it.', '["500 grams Mutton , minced", "4 Whole Eggs , boiled and peeled", "1 Onion , finely chopped", "1 teaspoon Ginger Garlic Paste", "1 tablespoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera)", "1-1/2 teaspoon Coriander Powder (Dhania)", "Salt , Salt to taste", "1 tablespoon Oil", "Water , if required", "2 tablespoon All Purpose Flour (Maida)", "2 Whole Eggs , beaten", "1/4 cup Whole Wheat Bread crumbs", "Oil , for deep frying"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'red chilli powder', 'water', 'flour (maida)', 'ginger garlic paste', 'onion', 'mutton', 'coriander powder', 'eggs', 'turmeric powder', 'wheat bread crumbs', 'sunflower oil']::text[], '["To begin making the Minced Meat And Egg Croquettes recipe, heat oil in a heavy bottomed pan.", "Add finely chopped onion saut\u00e9 until onions turn translucent.Add ginger garlic paste and cook till the raw smell of the paste goes off.", "Add the spice powders and salt mix well.Add minced mutton and cook for 5 minutes.", "Mutton will release its juices.", "I cooked the meat in its own juices without adding any water.Took about 30 minutes to get it fully cooked.", "Remove from stove and cool completely.Heat oil for deep frying in a deep fry pan.", "Divide the minced mutton mixture into 4 equal portions.Take one portion and place it in your palm, press and try to get it together.Slightly flatten it and place one full boiled egg in the middle and gather the meat to cover the egg fully.", "Try to shape it into cylindrical shape.If you find it too hard to handle the meat to shape it, try adding 1 or 2 teaspoon of beaten egg and work with the meat.Roll the croquettes in flour first, then dip it in egg and then roll with bread crumbs.Repeat this for all the meat.", "Deep fry the croquettes until golden brown in oil.", "Remove of kitchen paper.Serve Minced Meat And Egg Croquettes hot with\u00a0Tomato Garlic Chutney\u00a0or any dipping sauce of your choice."]'::jsonb, 55, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Minced_Meat_and_Egg_Croquettes.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/4.Minced_Meat_and_Egg_Croquettes.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thekera Tenga Recipe', 'thekera-tenga-recipe', 'Thekera Tenga is a Sour curry from Assamese cuisine. Thekera is a fruit that is dried and used as a souring agent in Assamese dishes. Few pieces of thekera are soaked in warm water and are used in the dishes. However, lemon and tomatoes are also used as souring agents. The tenga ( sour curry) is usually served at the end of a meal. Usually fish is fried and used in the dish, but in this vegetarian version, I have roasted potato slices and added it to the tenga. Simple, rustic and delicious Thekera Tenga can be served along with steaming hot rice or rotis.', '["4 Potatoes (Aloo) , thinly sliced", "1 tablespoon Mustard oil", "1/4 teaspoon Turmeric powder (Haldi)", "1 tablespoon Rice flour , or 1 mashed potato", "2 teaspoons Lemon juice , or 3-4 thekera pieces soaked in 1/4 cup of water", "Salt , to taste", "1 teaspoon Mustard oil", "1 teaspoon Panch Phoran Masala", "4 Green Chillies , roughly chopped", "4 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['salt', 'lemon thekera water', 'mustard oil', 'coriander (dhania) leaves', 'rice flour potato', 'panch phoran masala', 'potato (aloo)', 'turmeric powder', 'green chillies']::text[], '["To begin making the Thekera Tenga recipe, Heat a wide pan with oil and shallow fry the potato pieces and set them aside.Heat oil and temper with ingredients given ''for tempering''.Add 1-2 cups of water, salt and turmeric powder .Mix rice flour with one tablespoon of water (or 1 mashed potato) and add it to the water mixture.", "When the mixture starts to thicken, add lemon juice ( or thekera water ) and\u00a0 the roasted potatoes.Cook over low flame for another 4-5 minutes and switch off.", "Garnish with cilantro leaves and serve it along with flatbreads or rice.", "Serve Thekera Tenga along with\u00a0Steamed Rice\u00a0for a weekday dinner."]'::jsonb, 30, 'Assamese', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/umar/Thekera_Tenga.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/5.Thekera_Tenga.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Cabbage Rice Recipe (South Indian Style Mutta Kose Sadham Recipe)', 'spicy-cabbage-rice-recipe-south-indian-style-mutta-kose-sadham-recipe', 'Spicy Cabbage Rice takes very few ingredients to make and takes hardly 20 minutes to get prepared. This is a perfect recipe if you want to use your leftover rice and can be packed in your lunch box too. Serve Spicy Cabbage Rice Recipe with raita of your choice.', '["2 cups Cooked rice", "Ghee , or oil as required", "1 teaspoon Cumin seeds (Jeera)", "1 Onion , thinly sliced", "1 cup Cabbage (Patta Gobi/ Muttaikose) , shredded", "2 Green Chillies , finely chopped", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Sambar Powder", "Coriander (Dhania) Leaves , few, finely chopped", "Salt , to taste"]'::jsonb, ARRAY['salt', 'rice', 'sambar powder', 'coriander (dhania) leaves', 'red chilli powder', 'onion', 'cumin seeds (jeera)', 'ghee', 'oil', 'turmeric powder', 'green chillies', 'cabbage (patta gobi muttaikose)']::text[], '["To prepare Spicy Cabbage Rice recipe, firstly heat oil in a kadai.", "Add cumin seeds, green chillies and let it cook for 15 seconds.Next, add in the sliced onions and cook till they become soft and translucent.Add in the shredded cabbage, salt and turmeric powder.", "Cook till the cabbage becomes soft.Once it is done, add in the cooked rice, red chilli powder and the sambar powder.", "Mix everything well.Cover for 2 minutes.", "Open the lid, give it a stir and garnish with fresh coriander leaves.Serve\u00a0Spicy Cabbage Rice recipe\u00a0with raita of your choice."]'::jsonb, 65, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Spicy_Cabbage_Rice.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/6.Spicy_Cabbage_Rice.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mullangi Poriyal Recipe', 'mullangi-poriyal-recipe', 'Radish is called ''Mullangi'' in Tamil. A juicy root vegetable , radish is filled with nutrients, vitamins and minerals. It is high in fibre and is most beneficial for weight loss. Radish is very effective in relieving one from constipation, respiratory disorders and blood pressure. Radish oil, leaves and seeds are used even for many medicinal preparations too. It is wise to include this vegetable in our daily diet. This Mullangi Curry recipe is a simple South Indian Style Stir fry that can be prepared with just a handful of ingredients.', '["2 Mooli/ Mullangi (Radish) , (cleaned, peeled & chopped)", "1/8 teaspoon Turmeric powder (Haldi)", "2 teaspoons Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "1 tablespoon Sesame (Gingelly) Oil", "1 teaspoon Chana dal (Bengal Gram Dal)", "1 teaspoon Black Urad Dal (Split)", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves"]'::jsonb, ARRAY['mooli/ mullangi', 'radish', 'turmeric powder', 'haldi', 's red chilli powder', 'coriander powder', 'dhania', 'salt', 'sesame', 'gingelly', 'chana dal', 'bengal gram dal', 'black urad dal', 'split', 'cumin seeds', 'jeera', 'curry leaves']::text[], '["To prepare Mullangi Curry(South Indian Style Radish Stir Fry) Recipe, heat a pan with oil over low flame.Temper with all the tempering ingredients in the order given.Once tempered, add the radish and stir to mix.Add the turmeric powder, chilli powder, coriander powder and salt.Mix well, add half cup of water and cook covered till the radish cooks and becomes soft.Keep stirring occasionally for uniform cooking.Once the radish is soft, open the lid and cook on high, stirring continuously for 30-40 seconds and switch off.Your South Indian Style Mullangi Curry is ready to be served as a side dish with rasam\u00a0and steamed rice."]'::jsonb, 40, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Uma_Raghuraman/Mullangi_Curry__South_Indian_Style_Raddish_Stir_Fry_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/7.Mullangi_Curry__South_Indian_Style_Raddish_Stir_Fry_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karwar Style Surana Bhaji Recipe - Hot and Sour Yam Dry Curry', 'karwar-style-surana-bhaji-recipe-hot-and-sour-yam-dry-curry', 'Karwar Style Surana Bhaji Recipe - Hot and Sour Yam Dry Curry is a wonderful way to prepare yam in Karwar style. It has all the flavors like sweet, tangy and spicy that will tingle the taste buds of your tongue. The yam is pressure cooked so that it will be slow cooked with all the spices which will bring out more flavors.', '["500 grams Elephant yam (Suran/Senai/Ratalu) , peeled and cut very small", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "10 Dry Red Chillies", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "pinch Asafoetida (hing)", "1/2 teaspoon Turmeric powder (Haldi)", "1 cup Tamarind Paste", "1 teaspoon Jaggery , pound", "Salt , to taste", "Oil , for cooking"]'::jsonb, ARRAY['salt', 'elephant yam (suransenairatalu)', 'asafoetida (hing)', 'mustard seeds', 'jaggery pound', 'dry red chillies', 'methi seeds (fenugreek seeds)', 'tamarind paste', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the\u00a0Karwar Style Surana Bhaji Recipe - Hot and Sour Yam Dry Curry by heating a skillet with oil.", "Splutter the mustard seeds for few seconds.Then add asafoetida, turmeric powder, dry red chillies and fenugreek seeds.", "Roast them for few seconds and grind it into a smooth mixture using a mixer grinder.Heat the pressure cooker, add little oil and fry the yam pieces, add the ground spice mixture, then add the tamarind pulp and jaggery.", "Toss it well and coat it evenly.", "Check for seasoning as well.Pressure cook the yam for 4 whistles, let the pressure get released naturally.", "Pour it into a serving dish.Serve the\u00a0Karwar Style Surana Bhaji Recipe - Hot and Sour Yam Dry Curry\u00a0as a side dish along with\u00a0Karwar Style Varan Kadhi Recipe\u00a0and\u00a0Steamed Rice\u00a0for your everyday meals."]'::jsonb, 30, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Karwar_Style_Surana_Bhaji_Recipe__Hot_and_Sour_Yam_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/8.Karwar_Style_Surana_Bhaji_Recipe__Hot_and_Sour_Yam_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Malvani Fish Curry Recipe - Delicious And Spicy Fish Curry', 'malvani-fish-curry-recipe-delicious-and-spicy-fish-curry', 'Malvani Style Fish Curry Recipe is a special dish that is originated western coastal region of India. Malvani cuisine has got its influence from both Maharashtra and Goa.  They are typically non-vegetarian eater mainly seafood because of their close proximity to the ocean. As the fisherman’s catch their fresh fishes that becomes a part of their everyday meal.', '["1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "1 Onion , finely chopped", "2 Tomato , finely chopped", "1/2 cup Coconut milk", "1/4 cup Tamarind Water", "1 sprig Curry leaves", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Mustard oil", "Salt , to taste", "To Marinade", "2 King fish , cut into flat fillet", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "1 Lemon juice", "Salt , to taste", "1 teaspoon Coriander (Dhania) Seeds", "1/2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Fennel seeds (Saunf)", "1 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "1 Bay leaf (tej patta)", "1 pinch Nutmeg", "1/2 teaspoon Whole Black Peppercorns", "4 Dry Red Chillies", "1 Star anise"]'::jsonb, ARRAY['tomato', 'cumin powder (jeera)', 'nutmeg', 'cloves garlic', 'black peppercorns', 'curry leaves', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'salt', 'mustard oil', 'dry red chillies', 'star anise', 'tamarind water', 'mustard seeds', 'red chilli powder', 'lemon', 'coconut milk', 'ginger', 'bay leaf (tej patta)', 'fennel seeds (saunf)', 'king fish flat fillet', 'cinnamon stick (dalchini)', 'coriander powder', 'cloves (laung)']::text[], '["To begin making the Malvani Fish Curry Recipe, we will first wash the king fish well with water, drain the water completely.", "Add in red chilli powder, turmeric, cumin powder, coriander powder, salt to taste and lemon juice.", "Give it a mix and marinate the fish for at least 30 minutes."]'::jsonb, 40, 'Malvani', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Malvani_Fish_Curry_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/9.Malvani_Fish_Curry_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Urulai Kizhangu Masiyal Recipe (Potatoes in a Tangy lemon and Ginger Gravy)', 'urulai-kizhangu-masiyal-recipe-potatoes-in-a-tangy-lemon-and-ginger-gravy', 'Urulai Kizhangu Masiyal Recipe (Potatoes in a Tangy lemon and Ginger Gravy) is a very classic tamil brahmin dish that is eaten along with puri''s or chapatti. As a child I would not eat any potatoes apart from my favorite urulai kizhangu roast (potato roast), but now that I am all grown up and eaten things as bland as a leaf, I just love this dish. I love this dish for it tangy lemon and ginger flavors that get so well absorbed by the potatoes. The dish is made healthy using less oil, spiced just right to get the best flavors from the potatoes and the curry. Serve the Urulai Kizhangu Masiyal Recipe (Potatoes in a Tangy lemon and Ginger Gravy) along with Phulkas for a wholesome weeknight dinner.', '["3 Potatoes (Aloo) , boiled and cut into cubes", "2 Green Chillies , finely chopped", "1 inch Ginger , grated", "5-6 Curry leaves , finely chopped", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Oil", "1 Coriander (Dhania) Leaves , small bunch, finely chopped"]'::jsonb, ARRAY['potatoes', 'aloo', 'reen chillies', 'ginger', 'curry leaves', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'turmeric powder', 'haldi', 'oil', 'coriander', 'dhania']::text[], '["To begin making the Urulai Kizhangu Masiyal Recipe (Potatoes in a Tangy lemon and Ginger Gravy), we will first cook the potatoes until soft.", "Once soft, peel the potatoes and cut them into dices.", "Watch Video Recipe of How to Cook Potatoes in Pressure CookerThe next step is to spice up the potatoes to make the Masiyal.Heat a teaspoon of oil in a heavy bottom pan on medium heat; add the mustard seeds and the halved urad dal; allow them to crackle and the\u00a0dal\u00a0to turn light golden brown.Stir in the ginger, curry leaves, \u00a0turmeric powder, greenStir in the ginger, curry leaves, \u00a0turmeric powder, green chillies, boiled potatoes, salt along with 1 cup of water.", "Turn the heat to low and simmer the Urulai Kizhangu\u00a0for about 10 minutes.", "The mixture will look like a\u00a0mish mash\u00a0of potatoes.Finally stir in the lemon juice and freshly chopped coriander leaves.", "Check the salt and spice levels and adjust to suit your taste.Serve the Urulai Kizhangu Masiyal Recipe (Potatoes in a Tangy lemon and Ginger Gravy) along with\u00a0Phulkas\u00a0for a wholesome weeknight dinner."]'::jsonb, 60, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Urulai_Kizhangu_Masiyal_Recipe_Potatoes_in_a_Tangy_lemon_and_Ginger_Gravy-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/10.Urulai_Kizhangu_Masiyal_Recipe_Potatoes_in_a_Tangy_lemon_and_Ginger_Gravy-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mini Onion Vada With Vengaya Sambar Recipe - Pan Fried Fritters in Tangy Lentil Curry', 'mini-onion-vada-with-vengaya-sambar-recipe-pan-fried-fritters-in-tangy-lentil-curry', 'The Onion Vada Sambar Recipe is a simple healthy and nutritious recipe of the urad dal vada that is pan fried in a paniyaram pan.  In this recipe, I have made the Vada’s healthy by using the Kuzhi Paniyaram pan as opposed to the traditional method of deep frying the vada''s.', '["Ingredients to make the Onion Medu Vada", "1 cup White Urad Dal (Whole) , (soaked for 3 hours)", "1 inch Ginger", "1 Green Chillies , chopped", "Salt , to taste", "2 Onions , finely chopped", "1/4 Coriander (Dhania) Leaves , finely chopped", "Oil , for pan frying", "Ingredients for Vengaya Sambar", "1 cup Arhar dal (Split Toor Dal)", "1/2 cup Pearl onions (Sambar Onions)", "1 Mooli/ Mullangi (Radish) , chopped", "1 Carrot (Gajjar) , chopped", "1-1/2 cups Tamarind Water", "2 teaspoons Sambar Powder", "Salt , to taste", "Coriander (Dhania) Leaves , a small bunch chopped", "1 teaspoon Gingelly oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies", "1 sprig Curry leaves", "1/4 teaspoon Asafoetida (hing)"]'::jsonb, ARRAY['salt', 'coriander (dhania)', 'ginger', 'arhar dal (split toor dal)', 'tamarind water', 'coriander (dhania) leaves', 'sambar powder', 'mustard seeds', 'asafoetida (hing)', 'carrot', 'pearl onion (sambar onion)', 'curry leaves', 'dry red chillies', 'onion', 'gingelly oil', 'mooli mullangi (radish)', 'green chillies', 'sunflower oil pan', 'white urad dal']::text[], '["To begin making the Onion Vada Sambar Recipe; \u00a0we will first soak the dal for about 3 hours.Using a strainer, strain all the excess water from the\u00a0urad\u00a0dal.", "We need to use very little water to grind the\u00a0urad\u00a0dal,\u00a0so that you can shape them well if you are deep frying.Next we will grind the dal, along with ginger and green chillies using a food processor or a mixer grinder into a very smooth batter.", "Make sure add very little water while grinding the dal to make a smooth batter.", "Transfer the batter to a bowl.", "Add in the chopped onions, coriander leaves into the batter.", "Stir well to combine the ingredients well into the vada batter.Next we will preheat the\u00a0Kuzhi\u00a0Paniyaram\u00a0Pan and add in a little oil into each cavity; once the pan is\u00a0well heated\u00a0spoon the mini onion vada mixture into each of the cavities.", "Cover the pan and allow it to steam until you notice that the top looks cooked.", "After a couple minutes of steaming of\u00a0notice\u00a0the top part of the mini onion vada\u00a0looks cooked.", "At this\u00a0point\u00a0you could add a little more oil and then flip the\u00a0vada\u00a0so it can get cooked and crisp from both sides.", "This time, allow it to cook without the cover.", "Transfer the Mini Onion Vadas\u00a0to a platter and continue the same process with the remaining batter.To make the Vengaya Sambar recipe, pressure cook the toor dal along with 2 cups of water for 3 to 4 whistles and turn off the heat.", "Once the pressure releases naturally, open the cooking and mash the toor dal until soft.", "Keep aside.Into a pressure cooker; add the tamarind water, onions, radish, carrot, sambar powder and salt.", "Pressure cook for 2 whistles and turn off the heat.Add the cooker toor dal into the sambar water and bring to a brisk boil.", "Adjust the consistency by adding a little water if required.In a small tadka pan, heat oil over medium heat.", "Add mustard seeds and red chillies and allow it to crackle.", "Stir in the asafoetida and curry leaves.", "Pour this over the simmering vengaya sambar.", "Check the salt and spices of the vengaya sambar and adjust to suit your taste.", "Once done, turn off the heat , stir in the chopped coriander leaves and serve.", "To serve the Onion Vada Sambar, place the\u00a0vadas\u00a0in a bowl or a platter, pour in some Vengaya Sambar\u00a0and sprinkle some chopped onions and serve hot."]'::jsonb, 230, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breakfast_Tiffins/Preethi_Kitchen_Appliances_Mini_Vada_Sambar_Recipe_-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/11.Preethi_Kitchen_Appliances_Mini_Vada_Sambar_Recipe_-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Delicious Dal Makhani Recipe Without Onion and Garlic (Jain)', 'delicious-dal-makhani-recipe-without-onion-and-garlic-jain', 'Dal Makhani or dal makhni is a popular dish originating from the Punjab region of the Indian Subcontinent. The primary ingredients in dal makhani are whole black lentil with red kidney beans, butter and cream. Traditionally the Dal Makhani is made using garlic and onion but during some specific occasion dal makhani is made without using onions and garlic.', '["1 cup Black Urad Dal (Whole)", "1/2 cup Rajma (Large Kidney Beans)", "1 teaspoon Cumin seeds (Jeera)", "1-1/2 cup Homemade tomato puree", "1 teaspoon Kashmiri Red Chilli Powder", "2 tablespoons Fresh cream", "2 tablespoons Butter (Salted)", "1 cup Milk", "2 teaspoon Garam masala powder", "1/2 teaspoon Cardamom Powder (Elaichi)", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)"]'::jsonb, ARRAY['tomato', 'kashmiri red chilli powder', 'milk', 'cumin seeds (jeera)', 'cardamom powder (elaichi)', 'rajma (large kidney beans)', 'black urad dal', 'kasuri methi (dried fenugreek leaves)', 'butter', 'garam masala powder']::text[], '["To begin making the Dal Makhani Recipe without Onion and garlic, soak black lentil and rajma overnight in water or at least 8 hours.Take a pressure cooker, put in it the soaked dal then add 1 cup milk, 2 cups water, and garam masala, cardamom powder, salt, chili powder.", "Allow it to cook for 5 to 6 whistles.", "After 5 to 6 whistles, turn the heat to low and allow it to cook on low heat for another 20 to 25 minutes.", "After about 25 minutes, turn off the heat.Allow the pressure to release naturally.", "In a heavy bottomed pan, heat 2 tablespoons butter over medium heat, add the cumin seeds and allow it to crackle.", "Pour the tomato puree in the next step, when tomato is well cooked, add the cooked dal makhani into this mixture.", "Check the salt and spices and adjust to suit your taste.Stir the No onion no garlic dal makhani well, until it forms a creamy mixture.", "You can also lightly mash it.", "Finally stir in the cream and simmer on low heat for another 5 minutes and turn off the heat.", "Serve the\u00a0Delicious Dal Makhani Recipe without Onion and Garlic along with Naan,\u00a0Tandoori Paneer Tikka Masala Recipe\u00a0and a\u00a0Raita\u00a0for a delectable weekend lunch or dinner."]'::jsonb, 55, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Riya/Delicious_Dal_Makhani_Recipe_without_Onion_and_garlic_-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/12.Delicious_Dal_Makhani_Recipe_without_Onion_and_garlic_-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vadyancho Ross Recipe (Ash Gourd Chips Curry)', 'vadyancho-ross-recipe-ash-gourd-chips-curry', 'As a Goan, this recipe is very close to my heart. Vadyo are sun dried chips prepared out of Ash Gourd. My aunt used to prepare them, store them and use in different curries and vegetables. They just enhance the flavors of your food. In today''s ross or curry, I have used them. This curry is without any onions or garlic. It is very easy to make and goes really well with rice.', '["15 Ash Gourd Chips", "1 teaspoon Coconut Oil", "1/4 Cup Fresh coconut , grated", "3 Whole Black Peppercorns", "1 teaspoon Coriander (Dhania) Seeds", "1/2 teaspoon Turmeric powder (Haldi)", "2 Dry Red Chillies", "Tamarind , Marble size ball"]'::jsonb, ARRAY['coconut', 'black peppercorns', 'tamarind marble', 'coriander (dhania) seeds', 'dry red chillies', 'turmeric powder', 'coconut oil', 'ash gourd chips']::text[], '["To begin making the Vadyancho Ross recipe, On a medium high heat, fry the ash gourd chips on a frying pan using a teaspoon of oil.Once they are nice and crisp on both the sides, remove them out on a plate and keep aside.Grind together grated coconut, peppercorns, coriander seeds, turmeric powder, dry red chilies and tamarind using very little water.Take the ground paste in a saucepan kept on medium heat and allow to boil.", "Once it boils, add the fried ash gourd chips and mix.", "Allow the mixture to boil for 2-3 more minutes.Finally add salt, mix and remove from heat.", "Serve hot.Serve\u00a0Vadyancho Ross along with\u00a0Steamed Rice\u00a0and\u00a0Suran Fodi\u00a0for a weekday meal."]'::jsonb, 20, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/Vadyancho_Ross__Ash_gourd_Chips_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/13.Vadyancho_Ross__Ash_gourd_Chips_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Carrots & Sweet Potato Stuffed Paratha Recipe', 'carrots-sweet-potato-stuffed-paratha-recipe', 'Carrots and Sweet Potato Stuffed Parathas are a whole wheat Indian flat bread stuffed with finely grated carrots and boiled sweet potatoes are spiced up with green chillies, coriander leaves and cumin powder, makes this paratha healthy and delicious. This is a favorite lunch box for my children, they love to have it along with honey. And not to miss it is wholesome and nutritious too.', '["Ingredients for dough", "2 cups Whole Wheat Flour", "1/2 teaspoon Salt", "1 teaspoon Oil", "Ingredients for stuffing", "1 cup Carrots (Gajjar) , finely grated", "1/2 cup Sweet Potatoes , boiled and mashed", "1 teaspoon Cumin powder (Jeera) , (roasted)", "1 Green Chillies , chopped (adjust)", "1/4 cup Coriander (Dhania) Leaves , chopped", "Salt , to taste"]'::jsonb, ARRAY['salt', 'wheat flour', 'cumin powder (jeera)', 'coriander (dhania) leaves', 'carrot', 'green chillies', 'sweet potatoes', 'sunflower oil']::text[], '["To begin making the sweet potato parathas, we will first make the dough.", "Add flour and salt in a large bowl, adding little water at a time to make soft, pliable dough.Knead dough until it is smooth and elastic.", "Add oil to coat the dough and knead little more.", "The dough will be soft and nonsticky.", "Allow the dough to rest for about 15 minutes, covered.Knead dough until it is smooth and elastic.", "Add oil to coat the dough and knead little more.", "The dough will be soft and nonsticky.", "Allow the dough to rest for about 15 minutes, covered.Divide the dough into lemon sized balls and roll them out thin to approximately 3 inches in diameter.", "Note tossing the dough in dry flour while rolling will prevent it from getting sticky when rolling them out.In another bowl, combine all the ingredients for the filling together.", "Check the salt and spices and adjust to suit your taste.Add 1 tablespoon of the stuffing in the center.", "Gather the sides and bring them together.", "Remove the little excess dough which popped out when you brought them together.Press the stuffed dough down.", "Toss it in some flour and roll it gently applying just even pressure to roll.", "Roll it to desired thickness and your comfort level in rolling.Place the stuffed sweet potato carrot parathas on the hot griddle/skillet.", "Cook on medium heat adding a little oil or ghee to cook the parathas until you notice it gets brown spots on both the sides and has lightly crisp outer crust.Serve\u00a0Carrots & Sweet Potato Stuffed Paratha Recipe\u00a0along with\u00a0Boondi Raita Recipe Spiced With Black Salt,\u00a0Instant Gor Kairi Lonche Recipe - Sweet Raw Mango Pickle\u00a0and\u00a0Apple, Kiwi, Pineapple Juice Recipe\u00a0for a complete breakfast."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Carrot__Sweet_Potato_Paratha_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/14.Carrot__Sweet_Potato_Paratha_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mint Vegetables Moilee Recipe (Mixed Vegetables Cooked In Minty Coconut Milk)', 'mint-vegetables-moilee-recipe-mixed-vegetables-cooked-in-minty-coconut-milk', 'Moilee is a very traditional Kerala dish where the fish or vegetables are cooked in mildly spiced coconut milk. Mint Vegetables Moilee is a twisted recipe, using mint flavour to further enhance the dish making it even more refreshing.', '["1-1/2 cups Mixed vegetables , (potatoes, carrot, beans, peas), cut into cubes", "1 Onion , thinly sliced", "1 Tomato , roughly chopped", "1 Green Chilli , slit", "1 inch Ginger , thinly sliced", "2 Garlic , sliced", "1 sprig Curry leaves", "1 cup Coconut milk , thin", "1 cup Coconut milk , thick", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Black pepper powder", "2 teaspoon Oil", "1 teaspoon Coconut Oil", "1 teaspoon Lemon juice", "2 sprig Mint Leaves (Pudina) , made to paste", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'green chilli', 'mustard seeds', 'curry leaves', 'onion', 'garlic', 'lemon', 'mint leaves (pudina) paste', 'black pepper powder', 'coconut milk', 'coconut oil', 'mixed vegetables (potatoes', 'sunflower oil']::text[], '["To begin making the Mint Vegetables Moilee recipe, scrape the coconut and extract the thick and thin coconut milk and keep aside.Heat oil in a wok/kadhai, once heated add the mustard seeds and let it splutter.Add the curry leaves and the thinly sliced onions and saut\u00e9 till it gets translucent.Add the ginger and the sliced garlic pods and cook until the raw smell evaporates.Add the cubes vegetables, pepper powder and turmeric powder, and saut\u00e9 for a minute.Add the thin coconut milk and let the vegetables cook with the lid on.", "This will take 5 to 6 minutes.Add the chopped tomatoes and let it cook for a minute.Once the vegetables are cooked, add the thick coconut milk and the mint paste and heat it for 2 minutes.Make sure you don''t bring this mix to a boil at this stage else the coconut milk the curdle.Switch off the flame, season with salt and add the lemon juice.Serve the Mint Vegetables Moilee Recipe with\u00a0Appams\u00a0or\u00a0Idiyappams\u00a0or Steamed Rice for Sunday brunch."]'::jsonb, 35, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Mint_Vegetables_Moilee_Mixed_Vegetables_Cooked_In_Minty_Coconut_Milk.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/15.Mint_Vegetables_Moilee_Mixed_Vegetables_Cooked_In_Minty_Coconut_Milk.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('No Onion No Garlic Aloo Makhana Sabzi Recipe', 'no-onion-no-garlic-aloo-makhana-sabzi-recipe', 'Be it Navratri or Shravan maas, many practice fasting during these months, which means onion, garlic is a big no no for many. Fasting practices are different from region to region. I believe “There are no rules in fasting. Some fast on Mondays, some on Tuesdays and Fridays, while others fast only on certain religious days”.', '["1 cup Baby Potatoes", "1 cup Phool Makhana (Lotus Seeds)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Fennel seeds (Saunf)", "2 Green Chillies , finely chopped", "1-1/2 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste (kala namak is using for a fast)", "2 tablespoons Oil"]'::jsonb, ARRAY['salt (kala namak using fast)', 'fennel seeds (saunf)', 'red chilli powder', 'phool makhana (lotus seeds)', 'cumin seeds (jeera)', 'baby potatoes', 'coriander powder', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the No Onion No Garlic Aloo Makhana Sabzi recipe, boil baby potatoes along with its skin until well cooked.", "Remove from heat, peel the skin and keep aside.Heat 1 tablespoon oil in a heavy bottomed pan.", "Add makhana and roast them on medium to low heat until it is crisp.", "Once done, remove from pan keep aside.Add remaining oil into the same pan.", "Add cumin seeds and let it splutter.", "Add fennel seeds and chopped green chilies and saut\u00e9 for about 20 seconds.Add all the spice powders including red chilli powder, turmeric powder, coriander powder, salt/black salt and immediately give it a mix.", "Add boiled potatoes into the pan and toss well.Once all the potatoes are coated well with the spice mix, add roasted makhana and toss again.", "Lower the flame and keep tossing and cook for 3 to 4 minutes.Remove from flame, garnish with coriander leaves and serve hot.Serve\u00a0No Onion No Garlic Aloo Makhani Sabzi\u00a0with Sattu Ka Paratha for fasting or you can also serve it with\u00a0Phulka\u00a0or\u00a0Pudina Tawa Paratha\u00a0and\u00a0Palak Raita\u00a0for an everyday meal."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Aloo_Makhana_Sabzi_no_onion_no_garlic.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/16.Aloo_Makhana_Sabzi_no_onion_no_garlic.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bhaat Na Rasawala Muthia Dhokla Recipe | Gujarati Rasiya Dhokla', 'bhaat-na-rasawala-muthia-dhokla-recipe-gujarati-rasiya-dhokla', 'If you love Kadhi Chawal, then you will absolutely love this one dish meal bowl which is a classic and traditional kathiyawadi dish called Bhaat Na Rasawala Muthia Dhokla made from rice dumplings simmered in a delicious kadhi.', '["1-1/2 cups Cooked rice", "1/2 cup Gram flour (besan)", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Salt", "2 tablespoons Gram flour (besan)", "1 cup Curd (Dahi / Yogurt)", "3-1/2 cups Water", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "Salt , to taste", "1 Green Chilli , slit", "1 inch Ginger , finely chopped", "1 Bay leaf (tej patta) , torn", "1 inch Cinnamon Stick (Dalchini) , broken", "1 tablespoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "1 inch Cinnamon Stick (Dalchini) , broken", "1 sprig Curry leaves , torn"]'::jsonb, ARRAY['salt', 'ginger', 'green chilli', 'rice', 'bay leaf (tej patta)', 'ghee', 'cinnamon stick', 'red chilli powder', 'water', 'gram flour (besan)', 'curd', 'curry leaves', 'cumin seeds (jeera)', 'turmeric powder']::text[], '["To make Bhaat Na Rasawala Muthia Dhokla, prep all the ingredients and keep them ready.Into a large mixing bowl, combine all the muthia dhokla ingredients and mash the rice well until it forms a dough like consistency.Grease your palms, shape into small ovals (muthias) and keep aside.For kadhi, into a sauce pan combine the dahi, besan, turmeric powder, salt and red chilli powder and mix well to combine until there are no lumps.Add the 3 cups of water and bring to a brisk boil.", "Keep whisking the Kadhi as it continues to boil, as this makes it smooth and creamy, thus giving it a perfect texture.Once the kadhi has come together into a smooth and creamy mixture while it is boiling, turn the heat to low, add the ginger garlic, green chillies, cinnamon stick and simmer kadhi while we add the muthias.Add the muthia into the kadhi.", "Simmer for at least 5 minutes and you will notice the muthia\u2018s rising to the top and floating.", "Once it begins to float to the top, simmer the Bhaat Na Rasawala Muthia Dhokla for another 2 minutes.The final step is to prepare the tadka.", "Heat ghee in a saucepan on medium heat; add the cumin seeds and allow them to crackle.", "Stir in the curry leaves, cinnamon and give it a stir.", "Gradually, add the seasoning mixture to the above Rasiya Dhokla/Bhaat Na Rasawala Muthia Dhokla and allow the mixture to come to a brisk boil and turn off the heat.Serve the\u00a0Bhaat Na Rasawala Muthia Dhokla as a one dish meal for any weeknight dinner when you are looking for a comforting meal."]'::jsonb, 40, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/bhaat_na_rasawala_muthia_recipe__Gujarati_rasiya_muthia_Dhokla_recipe__7_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/17.bhaat_na_rasawala_muthia_recipe__Gujarati_rasiya_muthia_Dhokla_recipe__7_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sindhi Style Wadi Aloo Ki Sabzi Recipe - Spicy Wadi And Potato Curry', 'sindhi-style-wadi-aloo-ki-sabzi-recipe-spicy-wadi-and-potato-curry', 'Sindhi Style Wadi Aloo Ki Sabzi is an authentic Sindhi dish which is made with sundried dal spiced dumplings called Wadis, that are cooked along with potatoes and brinjals in an onion tomato gravy.', '["1 tablespoon Oil", "1 Badi (wadi) , urad dal spiced dumpling", "2 Onions , finely chopped", "2 Tomatoes", "1 inch Ginger", "1 Potato (Aloo) , cut into wedges", "1 Brinjal (Baingan / Eggplant) , cut into wedges", "1-1/2 teaspoon Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste"]'::jsonb, ARRAY['oil', 'badi', 'wadi', 'onions', 'tomatoes', 'ginger', 'potato', 'aloo', 'brinjal', 'baingan / eggplant', 'red chilli powder', 'cumin powder', 'jeera', 'garam masala powder', 'coriander powder', 'dhania', 'salt']::text[], '["To begin making the Sindhi Style Wadi Aloo Ki Sabzi\u00a0Recipe, in a pressure cooker heat oil on medium flame.Add chopped onions and saute for 3-4 minutes, until it turns into golden brown in colour.To this add wadi/ urad dal dumpling and saut\u00e9 for 3-4 minutes or until the wadi turns red.Close the pressure cooker and cook for 3 whistles.", "Turn off the heat and let the pressure release naturally.", "Once the pressure has released, remove only the wadis and place it in a bowl.", "Combine tomatoes and ginger in a mixer jar and bring to a pur\u00e9e, transfer to a bowl and set aside.", "Heat the same pressure cooker with the onions on medium heat,\u00a0add the potato and brinjal wedges and continue to cook for another 5 minutes.", "At this stage add, red chilli powder, garam masala powder, cumin powder, coriander powder and salt.", "Give it a good stir.", "Now that the onions, potatoes and brinjal are well coated with the masala, add the tomato ginger pur\u00e9e, saut\u00e9 for 3 minutes.", "Add the pre cooked wadi and close the pressure cooker.", "Pressure cook for 3 whistles, reduce the heat and continue to cook for 5 more minutes.", "Turn off the heat and allow the pressure to release naturally.Serve\u00a0Sindhi Style Wadi Aloo Ki Sabzi\u00a0Recipe\u00a0along with\u00a0Phulka\u00a0and\u00a0Palak Raita\u00a0for your everyday vegetarian Lunch or Dinner."]'::jsonb, 30, 'Sindhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/varshajchhabria-gmail.com/Sindhi_Style_WAdi_Aloo_ki_sabzi__1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/18.Sindhi_Style_WAdi_Aloo_ki_sabzi__1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kuvale Sasam Recipe - Konkani Ash Gourd Curry', 'kuvale-sasam-recipe-konkani-ash-gourd-curry', 'Kuvale Sasam Recipe is essentially a Konkani Style Ash Gourd Curry made with a curry of coconut, red chillies and mustard seeds that adds sharpness to the dish.', '["1/2 cup Fresh coconut , grated", "4 Dry Red Chillies", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Turmeric powder (Haldi)", "20 grams Tamarind", "Salt , to taste", "1/3 cup Water", "Other Ingredients", "300 grams Vellai Poosanikai (Ash gourd/White Pumpkin) , cut into medium sized cubes", "1/2 cup Water", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies", "2 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'mustard seeds', 'coconut', 'vellai poosanikai (ash gourdwhite pumpkin)', 'water', 'curry leaves', 'dry red chillies', 'tamarind', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Kuvale Sasam Recipe, we will first grind the masala which is the base for the dish.\u00a0*To make the freshly ground masalaIn a mixer jar combine, the\u00a0coconut,\u00a0red chillies,\u00a0mustard seeds,\u00a0turmeric powder, tamarind, water and\u00a0salt to taste.", "Grind to a coarse paste.", "Transfer to a bowl and set aside.", "Next, heat a pressure cooker on medium heat, add the ash gourd cubes, salt, turmeric powder and 1/2 cup of water and pressure cook for 1 whistle.", "Turn off the heat and allow the pressure to release naturally.", "Open the pressure cooker once the pressure has been released, and return the cooker to flame, add in the\u00a0freshly ground coconut masala, and cook on medium heat, until it comes to a rolling boil.", "Adjust the consistency of the\u00a0Kuvale Sasam by adding water to your liking.", "Check the salt and seasonings and adjust according to taste.", "Once done, turn off the heat.Transfer the Kuvale Sasam to a serving bowl and set aside.\u00a0*For the tadka of\u00a0Kuvale SasamIn a tadka pan, heat oil on medium heat, add the mustard seeds and allow it to splutter, next add the red chillies and roast for a few seconds.", "Finally add in the curry leaves and allow them to crackle.", "Turn off the flame, and pour this tadka over the piping hot Kuvale Sasam and serve hot.Serve\u00a0Kuvale Sasam Recipe\u00a0along with\u00a0Steamed Rice,\u00a0Beetroot Poriyal Recipe (Stir Fried Beetroot)\u00a0and\u00a0Curry Leaves Buttermilk Recipe - Curry Patta Chaas Recipe\u00a0for your everyday meal."]'::jsonb, 35, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/kuvale_sasam_recipe_konkani_ashgourd_curry_recipe-5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/19.kuvale_sasam_recipe_konkani_ashgourd_curry_recipe-5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hyderabadi Bagara Baingan Recipe - Brinjal In Spicy Peanut Curry', 'hyderabadi-bagara-baingan-recipe-brinjal-in-spicy-peanut-curry', 'Hyderabadi Bagara Baingan is a delicious preparation that is made from roasted brinjal/eggplant/ baingan. The base curry of the Bagara Baingan recipe is made from tamarind, peanuts and sesame seeds.', '["12 Small Brinjal (Baingan / Eggplant)", "1 Onion , roughly chopped", "2 Green Chillies , chopped", "12 cloves Garlic", "1 inch Ginger", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Bay leaf (tej patta)", "1 inch Cinnamon Stick (Dalchini)", "3 Cloves (Laung)", "1 teaspoon Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1 cup Tamarind Water", "Oil , for cooking", "Salt , to taste", "1/4 cup Fresh coconut , grated", "3 tablespoons Sesame seeds (Til seeds)", "3 tablespoons Roasted Peanuts (Moongphali)", "Coriander (Dhania) Leaves , for garnish"]'::jsonb, ARRAY['small brinjal', 'baingan / eggplant', 'onion', 'reen chillies', 's garlic', 'ginger', 'mustard seeds', 'rai/ kadugu', 'bay leaf', 'tej patta', 'cinnamon stick', 'dalchini', 'laung', 'red chilli powder', 'cumin powder', 'jeera', 'coriander powder', 'dhania', 'turmeric powder', 'haldi', 'tamarind water', 'oil', 'salt', 'fresh coconut', 's sesame seeds', 'til seeds', 's roasted peanuts', 'moongphali', 'coriander']::text[], '["To begin making the Hyderabadi Bagara Baingan Recipe, into a heavy bottomed pan, add the sesame seeds, peanuts and roast for a minute till the sesame seeds start popping.", "Turn off the heat and let it cool.Add the roasted peanuts, sesame seeds along with coconut and 1/2 cup warm water into a mixer grinder and blend it to make a\u00a0smooth paste.", "Keep it aside.Next, add onion, garlic, ginger and green chillies into a mixer grinder and grind it well to make a smooth paste.", "Keep it aside.Heat 2 tablespoons of oil in a heavy bottomed pan; add mustard seeds and allow it to crackle.", "Once done add the bay leaf, cinnamon stick, cloves and saute for a few seconds till the aromas from the spices come through.", "Once done, stir in the onion paste and saute for about 2 minutes till the paste is cooked a bit and starts to change the colour.After 2 minutes, add in all the spice powders including turmeric powder, red chilli powder, coriander powder along with tamarind water.", "Add in peanut sesame paste, salt to taste and some water to adjust the consistency.Give the Bagara Baingan gravy a brisk boil for 3 to 4 minutes.", "Turn off the heat and keep aside.Slit the eggplants into quarters without removing the stem.", "If using large eggplants, cut them lengthwise of one-inch thickness and about 2 inches in length.Heat 2 tablespoons oil in a pan and shallow roast the eggplants with a little salt until tender, cooked and browned.", "You can optionally cover the eggplant and pan roast it.", "Covering helps the steam get trapped inside and cook faster.Add the saut\u00e9ed baingan into the\u00a0Bagara Baingan gravy and boil till the gravy reaches the desired consistency.", "Once done, turn off the heat and transfer the\u00a0Bagara Baingan to a serving bowl, garnish with coriander leaves and serve hot.Serve\u00a0Hyderabadi\u00a0Bagara Baingan Recipe\u00a0along with\u00a0Hyderabadi Vegetable Biryani\u00a0and\u00a0Tomato Onion Cucumber Raita\u00a0to make a delicious meal for your festival."]'::jsonb, 55, 'Hyderabadi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Bagara_Baingan_Video_Recipe_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/20.Bagara_Baingan_Video_Recipe_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Vegetarian Biryani with Soya Chunks Recipe', 'andhra-style-vegetarian-biryani-with-soya-chunks-recipe', 'Andhra Style Vegetarian Biryani with Soya Chunks Recipe is very different from the Hyderabadi Biryani. The rice is completely tossed with the spicy masala rather than layering the rice with Biryani masala. The chopped tomatoes and ground spice mix will adds in the extra flavor to the rice. Andhra recipes are quite spicy when compared to dishes from other states. The flavors also change from region to region.', '["2 cup Basmati rice", "1 cup Soy Chunks (Nuggets)", "4 Onions , sliced", "2 Tomatoes , chopped", "4 Green Chilli , slit", "1 teaspoon Ginger Garlic Paste", "1 teaspoon Turmeric powder (Haldi)", "Oil , or ghee for cooking", "Whole Spice Used", "1 Bay leaf (tej patta)", "2 Cardamom (Elaichi) Pods/Seeds", "2 Cloves (Laung)", "1/2 inch Cinnamon Stick (Dalchini)", "1 Star anise", "1 Mace (Javitri)", "Biryani Masala to grind", "3 Cardamom (Elaichi) Pods/Seeds", "1 teaspoon Whole Black Peppercorns", "4 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 teaspoon Fennel seeds (Saunf)"]'::jsonb, ARRAY['tomato', 'basmati rice', 'green chilli', 'sunflower oil ghee', 'bay leaf (tej patta)', 'cardamom (elaichi) podsseeds', 'fennel seeds (saunf)', 'black peppercorns', 'ginger garlic paste', 'onion', 'cinnamon stick (dalchini)', 'mace (javitri)', 'soy (nuggets)', 'turmeric powder', 'cloves (laung)', 'star anise']::text[], '["To begin making the Andhra Style Vegetarian Biryani, soak the soy chunks in 1/4 cup water and keep it aside.Soak the basmati rice also in water and keep it aside.", "Ground all the spice mix mentioned in the biryani spice mix to a coarse powder.Heat a pressure cooker with oil.", "Add bay leaf, cardamom, cinnamon stick, cloves, star anise and mace.", "Fry the spice for 10 seconds until the aroma is released.Add the chopped onions, ginger garlic paste and green chili.", "Saut\u00e9 until the onions become light brown.Add the chopped tomatoes and little bit of salt so that the tomatoes will get cooked faster and become mushy.Add the powdered spice mix, turmeric powder and give it a mix.Wash the soaked rice several times and add only the rice into the saut\u00e9ed gravy.", "Add the soaked soya chunks as well.", "Mix well till the masala is mixed.Add 4 cups of water, check for salt and pressure cook for 2 whistle and switch off the heat.", "Allow the pressure to release by itself and open the lid and mix the rice well with the masala and serve.Serve the Andhra Style Vegetarian Biryani with\u00a0Tomato Onion Cucumber Raita\u00a0and\u00a0Mirchi Ka Salan Recipe\u00a0by the side."]'::jsonb, 75, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Andhra_Style_Vegetarian_Biryani_with_Soya_Chunks_Recipe_is_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/21.Andhra_Style_Vegetarian_Biryani_with_Soya_Chunks_Recipe_is_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Doddapatre Soppina Chitranna Recipe (Spiced Indian Thyme Rice)', 'doddapatre-soppina-chitranna-recipe-spiced-indian-thyme-rice', 'Doddapatre Soppina Chitranna (Indian Thyme Rice) Recipe is a one pot meal made with Thyme leaves as one of the main ingredients. Thyme leaves are called Doddapatre Soppu in Kannada. Its specialty lies in its health benefits and the ease of cooking. Doddapatre is a herb with medicinal properties well known for curing skin allergies, rashes and helpful in fighting dry cough.', '["1-1/2 cups Cooked rice", "2 tablespoons Oil", "10 Indian borage (Doddapatre) , cleaned washed and separated", "3/4 teaspoon Cumin seeds (Jeera)", "1 teaspoon Chana dal (Bengal Gram Dal)", "1 teaspoon White Urad Dal (Split)", "1/2 cup Dessicated Coconut , chopped", "3 Byadagi Dried Chillies", "3 Guntur Dried Chillies", "Coriander (Dhania) Leaves , a few sprigs finely chopped for garnish", "Ingredients for Tempering", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Chana dal (Bengal Gram Dal)", "1/2 teaspoon White Urad Dal (Split)", "1/4 teaspoon Asafoetida (hing)", "1 tablespoon Raw Peanuts (Moongphali)", "1 sprig Curry leaves", "Salt , to taste"]'::jsonb, ARRAY['salt', 'guntur dried chillies', 'coriander (dhania) leaves', 'indian borage (doddapatre) separated', 'rice', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'curry leaves', 'white urad dal (split)', 'byadagi dried chillies', 'cumin seeds (jeera)', 'peanuts (moongphali)', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To start preparing Doddapatre Soppina Chitranna (Indian Thyme Rice) Recipe, get all the ingredients handy first.Heat a teaspoon of oil in wide bottomed kadai and add urad dal, channa dal, cumin and roast them on medium flame until the dals turn golden.", "Transfer the seasoning to a mixie/ food processor.Add red chillies to the kadai and roast them on low flame until the pungent odour is slightly reduced (takes about 1-2 minutes).", "Add desiccated coconut and fry for a minute until the pleasant aroma rises.", "Cool this and add to the mixie along with other ingredients.Fry doddapatre leaves in kadai for a minute or two till the leaves wilt.", "Transfer the leaves to the mixie.Now grind all the ingredients into a smooth paste using little water.Heat oil in wide bottomed pan and add mustard, once it starts spluttering add the channa and urad dal, groundnuts, curry leaves and hing.", "Fry till the dals turns golden and the groundnuts are done (the skin starts to peel).Now add the ground paste and fry for a minute.", "Mix in the cooked rice, sprinkle some salt and mix until everything is well incorporated.", "Doddapatre Soppina Chitranna (Indian Thyme Rice) Recipe is now ready with some chopped coriander leaves to garnish."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sindhu_bharadwaj/doddapatre-soppina-chitranna-thyme-rice.JPG', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/22.doddapatre-soppina-chitranna-thyme-rice.JPG', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bhindi And Paneer Masala Recipe', 'bhindi-and-paneer-masala-recipe', 'Bhindi and Paneer Masala Recipe is a simple side dish which is made with sautéed bhindi and soft paneer in a tomato based gravy without any addition of cashew nuts, poppy seeds or cream. The flavors are simple and the whole spices are ground along with tomato so that it is more flavourful.', '["150 grams Bhindi (Lady Finger/Okra) , chopped to inch", "1 cup Paneer (Homemade Cottage Cheese) , cubed", "1 Onion , chopped", "1 Bay leaf (tej patta)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoon Coriander Powder (Dhania)", "1 teaspoon Sugar", "Salt , to taste", "Oil , for cooking", "Ingredients to grind", "2 Tomatoes , chopped", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 Cardamom (Elaichi) Pods/Seeds", "4 cloves Garlic", "1 inch Ginger", "1 tablespoon Hung Curd (Greek Yogurt)"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'hung curd (greek yogurt)', 'bay leaf (tej patta)', 'paneer', 'cardamom (elaichi) podsseeds', 'red chilli powder', 'cloves garlic', 'sugar', 'onion', 'cinnamon stick (dalchini)', 'bhindi (lady fingerokra)', 'coriander powder', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Bhindi and Paneer Masala Recipe, grind the tomatoes along with cinnamon, cardamom, clove, garlic, ginger and yogurt to a smooth paste.Heat a kadai with oil, add the chopped ladies finger and fry them till it is soft and crispy.", "Sprinkle little salt also and fry them.", "Keep it aside.In the same kadai, add little more oil, add bay leaf, chopped onions and saute till it becomes translucent.Add the ground paste along with turmeric powder, red chilli powder, coriander powder, sugar and salt.", "Mix well and saute till the raw smell of the tomato goes away.Add the chopped ladies finger and paneer and mix well.", "Check for salt and cover it with a lid and cook\u00a0Bhindi and Paneer Masala for 2 minutes.", "Serve hot.Serve the\u00a0Bhindi and Paneer Masala Recipe\u00a0along with\u00a0Tawa Paratha,\u00a0Palak Dal\u00a0and\u00a0Lauki Raita\u00a0to make your dinner meals simple and healthy."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Bhindi_and_Paneer_Masala_Gravy_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/23.Bhindi_and_Paneer_Masala_Gravy_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Style Mushroom Vindaloo Recipe', 'goan-style-mushroom-vindaloo-recipe', 'Goan Style Mushroom Vindaloo Recipe is a variation of the classic Goan Pork Vindaloo recipe. This traditional dish was introduced by the Portuguese in Goa. In this recipe, the mushroom is cooked in a vinegar based curry infused with Indian spices.', '["250 grams Button mushrooms , cut into quarters", "1 Onion , finely chopped", "3 cloves Garlic", "2 inch Ginger", "1 teaspoon Turmeric powder (Haldi)", "Oil , for cooking", "Salt , to taste", "To Be Ground To Paste", "3 Dry Red Chillies", "1 teaspoon Coriander (Dhania) Seeds", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Whole Black Peppercorns", "2 Cardamom (Elaichi) Pods/Seeds", "3 Cloves (Laung)"]'::jsonb, ARRAY['salt', 'ginger', 'cardamom (elaichi) podsseeds', 'cloves garlic', 'black peppercorns', 'dry red chillies', 'onion', 'coriander (dhania) seeds', 'cumin seeds (jeera)', 'button mushrooms', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Goan Style Mushroom Vindaloo, first prep all the ingredients, and get all the spices together.The next step is to roast the masala for the vindaloo.Heat a small skillet over medium heat; add all the ingredients to be ground into a paste and roast them for a few minutes until you get a roasted aroma and the red chilies are lightly crisp.Turn off the heat, allow it to cool a bit and grind into a fine powder.Pound the ginger and garlic in a pestle and motor and keep aside.Heat oil in a pan; add the ginger garlic paste and saute for a few seconds.", "Add the chopped onions and saute until the onions are tender.Add the turmeric powder, the ground spice powder, the mushrooms.", "Add the salt, cover the pan and simmer for 10 minutes until the mushrooms are cooked.Once done, open the pan, and allow the vindaloo masala to thicken, but evaporating any excess liquid.", "Turn off the heat and serve warm.Serve the Goan Style Mushroom Vindaloo along with steamed rice or even lachha paratha for lunch."]'::jsonb, 50, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/sept-26/Goan_Style_Mushroom_Vindaloo_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/24.Goan_Style_Mushroom_Vindaloo_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Coorg Style Kaad Manga Curry Recipe -Sweet & Spicy Mango Curry', 'coorg-style-kaad-manga-curry-recipe-sweet-spicy-mango-curry', 'Coorg Style Kaad Manga Curry Recipe which is a Sweet & Spicy curry made with tiny wild mangoes available locally in and around Coorg & Madikeri. Though it is a very very simple dish with just a few ingredients, the mango curry tastes absolutely delicious and has both the flavours of sweetness and tanginess flared with just a bit of spice.', '["4 Mango (Ripe) , small variety", "5 Green Chillies , crushed (adjust to taste)", "1/4 cup Jaggery", "Salt , to taste", "Ingredients To Temper", "1 tablespoon Coconut Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Dry Red Chilli , broken", "1 pinch Asafoetida (hing) , (a generous pinch)", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'mustard seeds', 'jaggery', 'mango (ripe) variety', 'dry red chilli', 'curry leaves', 'asafoetida (hing) (generous )', 'coconut oil', 'green chillies']::text[], '["To begin making Coorg Style Kaad Manga Curry Recipe, first wash the ripe mangoes.Using a knife to remove their tip and lightly make 2-3 vertical cuts on each mango to help cook better.Take a sauce pan, cook the mangoes with sufficient water, until they are soft and cooked thoroughly on a medium high heat.When the color of the mango peel appears soft, you know they are cooked.", "It might take 10 minutes depending on the heat.", "Switch off once done and drain water into a bowl (reserve for later) and keep the whole mangoes in the pan and allow the mangoes to cool till handleable.You can also keep the saucepan in a plate filled with cold water to fasten this process.Once the mangoes cool, peel them.", "You will be able to peel the mangoes easily using your fingers.Put the mango peels into the bowl with the reserved water and extract any more remaining pulp by squeezing with hand.", "Discard peel once done and reserve the water as you do.Now squeeze cooked mangoes with hands to make the curry pulpy, using a masher is difficult with fibrous pulp on the seed of mango.Do not discard the stone within, since the fibrous pulp attached to the stone is slurpy to try, while having the curry and you will love this experience for sure.Keep saucepan back on a medium heat, add crushed green chilli, salt and jaggery to the pan with mango pulp and seed/stone and mix well.Adjust taste and consistency of the\u00a0Kaad Manga Curry Recipe by adding water if required.", "Let it simmer for a few minutes and switch off heat.In a tadka pan, heat a little coconut oil and splutter mustard seeds.", "Once the mustard seeds splutter, add hing, broken red chilli and curry leaves.", "Turn off the heat after the curry leaves crackle.", "Pour the tadka on Kaad Manga Curry Recipe and give it a quick stir.", "Close the lid of the pan and allow the Kaad Manga Curry to sit for about 10 minutes before serving.", "Serve this lip smacking good Coorg Style Kaad Manga Curry along with steamed rice or Mangalorean Neer Dosa Recipe\u00a0or\u00a0Coorg Style Kadumbuttu/Kadambuttu Recipe\u00a0and\u00a0Sabudana Sandige Recipe."]'::jsonb, 30, 'Coorg', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/__Coorg__Kaad_Manga_Curry_tiny_mangoes__sweet_and_spicy.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/25.__Coorg__Kaad_Manga_Curry_tiny_mangoes__sweet_and_spicy.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Phalguni Dal Recipe - Bengali Style Red Lentils With Fresh Green Peas', 'phalguni-dal-recipe-bengali-style-red-lentils-with-fresh-green-peas', 'Phalguni Dal Recipe is a must try recipe when green peas are in season during winters. Phalguni Dal Recipe is a rich and creamy Bengali style dal prepared with the combination of masoor dal and green peas. This is a vegan, gluten free and protein rich accompaniment to your meals.', '["1/4 cup Masoor Dal (Whole) , washed and drained", "1/4 cup Green peas (Matar)", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1/2 inch Ginger , grated", "2 cloves Garlic , grated", "2 Green Chillies , chopped in pieces", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Ingredients for seasoning", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Fennel seeds (Saunf)", "1/4 teaspoon Kalonji (Onion Nigella Seeds)", "1 teaspoon Garam masala powder", "2 teaspoon Mustard oil", "Asafoetida (hing) , a pinch"]'::jsonb, ARRAY['tomato', 'green chillies', 'salt', 'ginger', 'kalonji (onion nigella seeds)', 'mustard oil', 'mustard seeds', 'fennel seeds (saunf)', 'asafoetida (hing)', 'green peas (matar)', 'cloves garlic', 'onion', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'turmeric powder', 'masoor dal', 'garam masala powder']::text[], '["To begin making Phalguni Dal Recipe, place a Pressure Cooker pan on medium heat.", "Add the washed and drained masoor dal.", "Add the chopped tomatoes and chopped onions.", "Grate ginger and garlic to the dal mixture.", "Add 1-1/2 cup water to it.Place the lid on the pressure cooker pan with its weight placed on it and allow it to cook until you hear three whistles.Turn off the heat.", "Wait til the pressure is released completely.", "Now open the lid and mash the dal with a ladle and keep it aside.We will now proceed to prepare the seasoning.To prepare the seasoning, Place a Kadai (Wok)/ Stir Fry Pan on medium heat.", "Add 2 teaspoon mustard oil to it.", "Add mustard seeds, fenugreek seeds, fennel seeds, cumin seeds and kalonji seeds one after the other and allow the seeds to crackle.Once done add the green chilies and saute for 1-2 minutes.", "Add asafoetida and turmeric powder followed by fresh green peas.", "Cook the green peas covered on medium heat for 2 minutes.After two minutes add the mashed masoor dal, garam masala and salt to taste.", "Mix well.", "Add some water depending on how thick or thin you want your dal to be.", "Let it simmer on low heat for 3-4 minutes and then turn off the heat.Garnish\u00a0Phalguni Dal Recipe with freshly chopped coriander leaves and serve.Serve\u00a0Phalguni Dal Recipe\u00a0for your lunch or dinner with\u00a0steamed rice\u00a0or\u00a0laccha paratha\u00a0and\u00a0Carrot Cucumber Tomato Salad with Lemon and Coriander."]'::jsonb, 30, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Preeti_Tamilarasan/Phalguni_Dal_Recipe_original_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/26.Phalguni_Dal_Recipe_original_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mangalorean Chana Gassi Recipe', 'mangalorean-chana-gassi-recipe', 'Mangalorean Chana Gassi Recipe is an authentic dish of Mangalorean cuisine, which is prepared with ground spices and coconut. Kori gassi is the most popular curry which is prepared with Chicken and served with roti. One can prepare gassi with chickpeas, kala chana, soya chunks or even with mushrooms with the same spice paste. This gassi is luscious and drool worthy. Gassi served with any Indian salad and roti/parotta is a perfect lunch. Serve Mangalorean Chana Gassi Recipe with Malabari Parotta Without Egg Recipe (Kerala Parotta) or Magalorean Neer Dosa Recipe (Savory Rice & Coconut Crepe) for lunch.', '["1 cup Kabuli Chana (White Chickpeas) , soaked overnight", "Salt , to taste", "8 Dry Red Chillies", "4 cloves Garlic", "4 tablespoon Coriander (Dhania) Seeds", "1 cup Fresh coconut , grated", "1 teaspoon Tamarind Paste", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Water , as needed", "1 tablespoon Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1 pinch Asafoetida (hing)", "Curry leaves , a handful"]'::jsonb, ARRAY['salt', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'cloves garlic', 'water', 'curry leaves', 'kabuli chana (white chickpeas)', 'dry red chillies', 'coriander (dhania) seeds', 'coconut oil', 'methi seeds (fenugreek seeds)', 'tamarind paste', 'turmeric powder']::text[], '["To begin making Mangalorean Chana Gassi Recipe, soak Chickpeas overnight and pressure cook with water and salt for about 3 whistles.", "Prep with other ingredients as well.Drain the excess water and keep the cooked chickpeas aside.", "In the meanwhile, prepare the masala.To prepare masala, in a kadai, dry roast coriander seeds until the aroma rises from it.", "Keep aside.", "In the same pan, dry roast red chillies until crisp for about a minute.", "Let it cool.Once cooled, add turmeric powder, coconut, garlic, about 1/2 cup water and tamarind paste to it and grind using a mixer to a fine ground paste.Now, in a Kadai, add the ground masala and saute it for about a minute.Add the cooked chickpeas and a cup of water.", "Cook until the raw smell of the grounded paste goes off.", "Adjust the amount of water according to your desired consistency.", "Add a few tablespoon of water to thin out the curry.", "Season it with salt.In a tadka pan, heat coconut oil.", "Once the oil is hot, add asafetida, mustard seeds, curry leaves and fenugreek seeds.", "Let them splutter.", "Pour the tempering over the curry.Let it rest until it is served.", "Give a quick stir and\u00a0Serve\u00a0Mangalorean Chana Gassi Recipe with\u00a0Malabari Parotta Without Egg Recipe (Kerala Parotta)\u00a0or\u00a0Mangalorean Neer Dosa Recipe (Savory Rice & Coconut Crepe)\u00a0for lunch."]'::jsonb, 35, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/KarthikaKrishnan/Mangalorean_Channa_gassi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/27.Mangalorean_Channa_gassi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Achari Amla Mirchi Ki Sabzi Recipe - Gooseberry & Green Chilli Sabzi', 'achari-amla-mirchi-ki-sabzi-recipe-gooseberry-green-chilli-sabzi', 'Achari Amla Mirchi Ki Sabzi Recipe also called as Gooseberry & Green Chilli Sabzi, a dry curry that has the right amount of sourness and spiciness in the dish. Amla is a powerhouse of Vitamin C and is great for hair and skin. It is also rich in antioxidants and fiber, thus it is also diabetic friendly dish. Therefore adding amla into your everyday diet will help you in a lot of ways.', '["10 Amla (Nellikai/ Gooseberry) , cut into bite sized cubes", "3 Green Chilli , cut into 1 inch", "1 tablespoon Achari masala", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoons Jaggery", "Salt , to taste", "To temper", "1 teaspoon Fennel seeds (Saunf)", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "Oil", "1 pinch Asafoetida (hing)"]'::jsonb, ARRAY['amla', 'nellikai/ gooseberry', 'reen chilli', 'achari masala', 'red chilli powder', 'turmeric powder', 'haldi', 's jaggery', 'salt', 'to temper', 'fennel seeds', 'saunf', 'methi seeds', 'fenugreek seeds', 'mustard seeds', 'rai/ kadugu', 'oil', 'asafoetida', 'hing']::text[], '["To begin making the Achari Amla Mirchi Ki Sabzi Recipe, heat a pressure cooker with oil, add amla and green chilli along with all the masala including achari masala, red chilli powder, turmeric powder, salt except the jaggery.Add about 1/4 cup of water and pressure cook for 2 whistle and switch it off.", "Allow the pressure to release naturally.Open the lid and keep the pressure cooker back on the stove.", "Add jaggery and keep cooking until\u00a0Amla Mirchi Ki Sabzi dries up.", "Once done turn off the heat.Keep it aside, heat a tadka pan with oil, add fennel seeds, fenugreek seeds and mustard seeds allow them to crackle.Add pinch of hing and then pour it over the sabzi, give Achari Amla Mirchi Ki Sabzia mix and serve hot.Serve the\u00a0Achari Amla Mirchi Ki Sabzi Recipe\u00a0along with\u00a0Roti\u00a0and\u00a0Traditional Punjabi Kadhi With Methi\u00a0for a weekday meal."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Amla_Mirchi_Ka_Achari_Subzi_Recipe_Gooseberry__Green_Chilli_Subzi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/28.Amla_Mirchi_Ka_Achari_Subzi_Recipe_Gooseberry__Green_Chilli_Subzi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kongunadu Style Vetrilai Sadam Recipe - Betel Leaves Rice', 'kongunadu-style-vetrilai-sadam-recipe-betel-leaves-rice', 'Vetrilai Sadam or Betel Leaves Sadam is a traditional Kongunadu special variety of rice. It is healthy, flavorful, and tasty that gets a peppery flavor from the betel nut leaves. Preparing this rice requires grounded masala that adds flavor to it. Betel leaves have many health benefits, it is rich in calcium and aids in digestion. This rice has unique flavors of betel leaves and garlic.', '["5 Betel leaves (paan)", "2 cups Cooked rice", "10 cloves Garlic , crushed", "2 teaspoons Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Chana dal (Bengal Gram Dal)", "1/2 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "1/4 cup Roasted Peanuts (Moongphali)", "10 Cashew nuts", "4 Fresh Red chillies , chopped", "Salt , as required", "1 tablespoon Cumin seeds (Jeera)", "1 tablespoon Fennel seeds (Saunf)", "1 teaspoon Whole Black Peppercorns", "2 tablespoons Sesame seeds (Til seeds)", "1 sprig Curry leaves"]'::jsonb, ARRAY['betel leaves', 'paan', 's cooked rice', 's garlic', 's oil', 'mustard seeds', 'rai/ kadugu', 'chana dal', 'bengal gram dal', 'white urad dal', 'split', 'curry leaves', 'roasted peanuts', 'moongphali', 'cashew nuts', 'fresh red chillies', 'salt', 'cumin seeds', 'jeera', 'fennel seeds', 'saunf', 'whole black peppercorns', 's sesame seeds', 'til seeds']::text[], '["To begin making\u00a0Kongunadu Style Vetrilai Sadam Recipe, wash and cook rice adding just sufficient water so that the rice is not sticky and the grains are cooked yet separate.", "You can also use leftover rice for preparing this.Next, we will prepare the masala for the rice.Dry roast Cumin seeds, Fennel seeds, Pepper seeds, and Sesame seeds until golden.", "Add the curry leaves and roast for another minute.", "Allow it to cool completely and grind into a coarse powder.", "Heat a Kadai with oil, add mustard seeds, chana dal, and Urad dal.", "Once the dals turn golden brown add curry leaves, chopped red chillies, peanuts, and cashews.Saute until the cashews and peanuts turn a golden color.", "Add crushed garlic and saute until the raw smell goes away.", "Tear the betel leaves roughly and add them to the pan and saute until the leaves shrink.", "Now add the ground masala powder and stir all ingredients well for a minute.", "Turn off the heat and add cooked rice along with the required salt.", "Toss and mix well until everything is combined.", "Check for salt and serve\u00a0Kongunadu Style Vetrilai Sadam hot.Serve\u00a0Vetrilai Sadam or Betel Leaves Sadam along with\u00a0Tomato Cucumber Raita\u00a0and\u00a0Masala Vadai\u00a0for a wonderful Sunday lunch."]'::jsonb, 25, 'Kongunadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swathynandhini/Vethalai_Sadam_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/29.Vethalai_Sadam_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Style Mushroom Shagoti Recipe', 'goan-style-mushroom-shagoti-recipe', 'A medley of freshly roasted whole spices combined with coconut, this Mushroom Shagoti is an authentic Goan curry that is bursting with flavours. With a hint of sourness from the tamarind and richness from the poppy seeds and mushroom as a star ingredient, this Indian recipe is something different from the usual and worth a try.', '["20 Button mushrooms , cut into quarters", "6 Whole Black Peppercorns", "2 Cloves (Laung)", "1/2 teaspoon Ajwain (Carom seeds)", "1/2 teaspoon Fennel seeds (Saunf)", "1 teaspoon Cumin seeds (Jeera)", "1-1/2 tablespoon Coriander (Dhania) Seeds", "1 inch Cinnamon Stick (Dalchini)", "4 Dry Red Chilli", "1-1/2 tablespoons Poppy seeds", "1/4 cup Fresh coconut , grated", "2 tablespoons Oil", "2 Onions , sliced", "8 Garlic , pods", "Salt , to taste", "1 tablespoon Tamarind Paste"]'::jsonb, ARRAY['salt', 'coconut', 'fennel seeds (saunf)', 'ajwain (carom seeds)', 'garlic pods', 'black peppercorns', 'dry red chilli', 'coriander (dhania) seeds', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'poppy seeds', 'onion', 'tamarind paste', 'button mushrooms', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Mushroom Shagoti Recipe, in a pan dry roast the whole spices on low-medium heat which includes cloves, peppercorns, carom seeds, fennel seeds, cumin seeds, coriander seeds, cinnamon, star anise, red chillies and poppy seeds till fragrant.Add coconut and roast for a couple of more minutes or till the coconut is lightly browned.", "Allow to cool.Grind the roasted ingredients with garlic and a little water to a fine paste in a mixer grinder jar.", "Keep it aside.", "In another pan, heat oil, add onions and saut\u00e9 for 5 minutes.", "When the onions are well browned, add chopped mushrooms, salt and stir.Add the ground masala paste and mix well.", "Add one cup of water, tamarind pulp and simmer until the mushrooms are cooked and the Mushroom Shagoti comes to your desired gravy consistency.", "Turn off the heat and your Mushroom Shagoti is ready to be served.", "Serve Mushroom Shagoti with\u00a0Goan Style Sana Recipe (Soft Steamed Rice Cakes)\u00a0oror\u00a0Steamed Rice\u00a0or pav."]'::jsonb, 35, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sneha-archanaskitchen.com/Mushroom_Shagoti_Recipe__1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/30.Mushroom_Shagoti_Recipe__1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vegetable Rava Upma Recipe  - Sooji Upma Recipe', 'vegetable-rava-upma-recipe-sooji-upma-recipe', 'Vegetable Rava Upma is a traditional south Indian breakfast dish that is made from semolina and cooked along with vegetables and seasonings. This dish is popularly called as Khara Bath in Karnataka. At home we love to serve it along with a hot cup of freshly brewed filter coffee to make a complete breakfast with some fresh fruits on the side.', '["1 cup Sooji (Semolina/ Rava)", "1 Onion , finely chopped", "1 inch Ginger , finely chopped", "2 Green Chillies , finely chopped", "1 sprig Curry leaves , finely chopped", "1 Carrot (Gajjar) , finely chopped", "1/2 cup Green beans (French Beans) , finely chopped", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Oil , for cooking", "3 tablespoons Ghee", "1 Lemon , juice extracted", "1/2 teaspoon Sugar", "Salt , to taste"]'::jsonb, ARRAY['sooji', 'semolina/ rava', 'onion', 'ginger', 'reen chillies', 'curry leaves', 'carrot', 'gajjar', 'green beans', 'french beans', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'asafoetida', 'hing', 'oil', 's ghee', 'lemon', 'sugar', 'salt']::text[], '["To begin making the Vegetable Rava Upma Recipe/ Sooji Upma, prep all the ingredients and keep aside.In a saucepan; boil 3 cups of water along with salt and a dash of sugar and set aside.", "Add the vegetables to this water and cook it until the sooji/rava gets roasted.Heat oil in heavy bottomed pan on medium heat; add mustard seeds, half urad dal seeds and allow it to crackle and the dal to turn golden brown and crisp.Stir in the onions, ginger, asafoetida, curry leaves and green chilies and saut\u00e9 until onions are tender.Stir in the semolina and roast along with the onion mixture until you get the light roasted aroma.Gradually pour the hot water into the above mixture and continue to stir in the process.", "Turn the heat to low, cover the pan and allow the Rava Upma to cook and steam in the heat.Keep stirring occasionally to avoid lumps.", "This will take about 10 minutes.Finally stir in the ghee and lemon juice and saut\u00e9 for a couple of minutes on low heat until all the ingredients are well combined.", "The ghee enhances the flavour of the Rava Upma/ Sooji Upma.Serve Vegetable Rava Upma Recipe along with\u00a0Coconut Chutney\u00a0and\u00a0South Indian Filter Coffee Recipe With Filter Coffee Powder\u00a0for a complete south Indian Breakfast."]'::jsonb, 35, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Vegetable_Rava_Upma_Sooji_Upma_Recipe_Video_6_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/31.Vegetable_Rava_Upma_Sooji_Upma_Recipe_Video_6_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Peanut Curry Recipe', 'peanut-curry-recipe', 'Peanut Curry or Shengdanachi Amti is a Maharashtrian curry made especially during fasting days. This curry is usually served with varicha bhaat which is made using samo seeds. This Varicha bhaat and shengdanyachi amti is usually made during the holy month of Shravan when most people fast. Peanuts are high in protein and fibre and helps to improve satiety and aids in weight loss. They are rich in vitamin B6 and vitamin E and lots of minerals like magnesium, zinc, iron, magnesium, etc. Peanuts also help in anti-aging.', '["2 cups Raw Peanuts (Moongphali)", "4 tablespoon Fresh coconut , grated", "3 Green Chillies", "1 teaspoon Red Chilli powder", "3 tablespoons Jaggery , grated", "2 Cloves (Laung)", "4 Kokum (Malabar Tamarind)", "1 sprig Curry leaves", "2 tablespoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "Water , as needed", "Salt , to taste"]'::jsonb, ARRAY['salt', 'coconut', 'kokum (malabar tamarind)', 'ghee', 'jaggery', 'red chilli powder', 'water', 'curry leaves', 'cumin seeds (jeera)', 'peanuts (moongphali)', 'cloves (laung)', 'green chillies']::text[], '["To begin making the Peanut Curry recipe, heat a wok/kadai and dry roast the peanuts till they turn crispy and brownish.After cooling, peel them by rubbing them against each other between palms.Grind the peeled roasted peanuts, grated coconut, cloves and green chillies to a fine paste by adding 1/2 cup water in a mixer grinder.", "Keep it aside.Heat a kadai/wok.", "Add ghee and once it gets heated, add cumin seeds and let them flutter.Add curry leaves and fry for few seconds.", "Now pour the peanut curry into the kadai and mix well.", "Add 1/2 cup water if needed.Let it come to a boil.", "Then add jaggery and mix well.", "Simmer for 5 minutes.Add kokum petals, mix and again simmer for 5 minutes.", "Add salt to taste, mix and serve hot.Serve Peanut Curry along with Varicha Bhaat during fasting days or you can even serve it with other fasting items such as\u00a0Sabudana Khichdi."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Peanut_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/32.Peanut_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Raw Papaya Red Bell Peppers Stuffed Paratha', 'raw-papaya-red-bell-peppers-stuffed-paratha', 'Raw Papaya and Red Bell Peppers Stuffed Paratha is a nice way to add in raw papaya to your meal. Raw papaya are rich in nutrients and minerals like potassium, magnesium and vitamins like A, B, C and E. So it helps in boosting the immune system and helps in treating constipation problems.', '["Ingredients for the stuffing", "1 teaspoon Oil", "1-1/2 cups Raw papaya , peeled & grated small", "1 Red Bell pepper (Capsicum) , finely chopped", "1 inch Ginger , finely chopped", "1 Onion , finely chopped", "2 Green Chillies , finely chopped", "1 tablespoon Amchur (Dry Mango Powder)", "1 teaspoon Garam masala powder", "1/2 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "Salt , to taste", "1/4 cup Mint Leaves (Pudina)", "1 teaspoon Ghee", "Ingredients for the dough", "2 cups Whole Wheat Flour", "1 teaspoon Oil", "Salt , to taste"]'::jsonb, ARRAY['ingredients for the stuffing', 'oil', 's raw papaya', 'red bell pepper', 'capsicum', 'ginger', 'onion', 'reen chillies', 'amchur', 'dry mango powder', 'garam masala powder', 'red chilli powder', 'salt', 'mint leaves', 'pudina', 'ghee', 'ingredients for the dough', 's whole wheat flour']::text[], '["To begin making the Raw Papaya and Red Bell Peppers Stuffed Paratha, heat 1 tsp oil in a pan, add the red capsicum and onions; saute until the onion turns lightly golden.", "Once the onions turn golden, add the raw papaya and saute the papaya until slightly softened for about 3 to 4 minutes.", "Once the papaya is slightly softened, add the green chillies, amchur powder, red chilli powder, garam masala powder and salt to taste.", "Give it a stir until well combined and turn off the heat.Allow the raw papaya and red capsicum mixture to cool completely.Once cooled, stir in the mint leaves.To make the dough for the paratha, into a large mixing bowl add whole wheat flour, ragi flour and salt to taste.", "Stir to combine the dry ingredientsAdd a little water at a time and knead to make a smooth firm dough.", "Drizzle 1 tsp oil over the dough and knead again until the dough is smooth.Divide the dough into 6 large lemon size portions (check this number)Dust the dough in flour and roll into a 3 inch diameter circlePlace a large tablespoon of raw papaya and capsicum filling into the center and bring the edges of the dough to the centre.", "Pinch the excess dough out.Flatten the stuffed paratha and dust again some flourGently roll the stuffed paratha into a 4 to 5 inch diameter circle or as per your prefered thickness.Place the paratha onto a preheated pan.", "Cook the paratha on both sides without any ghee for a few seconds until the rawness has gone away.Once lightly cooked through, smear a little ghee and cook the paratha on medium heat until golden brown and crisp on both sides.Serve the Raw Papaya Red Bell Peppers Stuffed Paratha along with\u00a0Makhana Ka Raita Recipe\u00a0and\u00a0Palak And Moong Dal Pakodas Recipe\u00a0to enjoy meal."]'::jsonb, 70, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Raw_Papaya_and_Red_Bell_Peppers_Stuffed_Paratha.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/33.Raw_Papaya_and_Red_Bell_Peppers_Stuffed_Paratha.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rajma and Horse Gram Stuffed Paratha Recipe', 'rajma-and-horse-gram-stuffed-paratha-recipe', 'Rajma and Horse gram Stuffed Paratha Recipe is a diabetic friendly dish for all those who are seeking to eat a healthy stuffed paratha. Both the lentils are a key ingredient to be a part in one’s diet as it contains good amount of nutrients like proteins, carbs and fiber. They are soaked and cooked together and then mixed with some Indian spice and stuffed into a whole wheat paratha. This paratha will fill you just like that without any other accompaniments except for a bowl of curd.', '["1 cup Rajma (Large Kidney Beans) , soaked for 8 hours", "1/2 cup Horse Gram Dal (Kollu/ Kulith) , soaked for 8 hours", "1 Onion , finely chopped", "1 Green Chilli , finely chopped", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "2 teaspoon Red Chilli powder", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Garam masala powder", "1 teaspoon Black pepper powder", "Salt , to taste", "1 cup Whole Wheat Flour", "2 tablespoon Oil", "Water , to knead"]'::jsonb, ARRAY['salt', 'wheat flour', 'water knead', 'green chilli', 'amchur (dry mango powder)', 'red chilli powder', 'onion', 'cumin seeds (jeera)', 'rajma (large kidney beans)', 'black pepper powder', 'horse gram dal (kollu kulith)', 'coriander powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Rajma and Horse gram Stuffed Paratha Recipe into a bowl add the wheat flour, cooking oil and add water slowly and knead it into a firm and non-sticky dough.", "Cover and\u00a0 keep aside.Pressure cook the soaked lentils in the pressure cooker with 1 cup water for about 4 whistle.", "After 4 whistles reduce the heat and cook for 5 more minute and switch it off.", "Release the pressure naturally and the drain all the water.Allow the lentils to cool\u00a0 down and then grind the cooked lentils into a coarse mixture and keep it aside.Now to make the stuffing, heat a sauce pan, crackle the cumin seeds and\u00a0saut\u00e9 the onions till translucent.", "Once done add the coarsely ground lentils along with spice powders and mix well.", "Cook for another 10 minutes.Now to begin making the paratha, keep some flour aside for dusting.", "Divide the dough into large lemon side balls.Dust the dough portions in flour, flatten it and roll it into a 3 inch diameter circle.Now add the Rajma and horsegram stuffing, add about a tablespoon in the center.", "Close the paratha by folding it from all the side like a dumpling and seal it properly.", "Dust the stuffed paratha ball in flour and roll into 5 inch diameter parathas.", "Take care, the filling can ooze out if the dough is rolled out too thin.Now to cook Rajma and Horse gram Stuffed Paratha, first preheat the\u00a0skillet\u00a0on medium heat.", "Place the rolled paratha on top and allow it to cook on one side.", "After about 30 seconds, flip the paratha.At this stage, smear some oil or ghee to cook the paratha.", "Cook the paratha by flipping over a couple of times until you see golden brown spots on both sides.Proceed the same way with the remaining dough portions and serve the parathas hot.Serve the Rajma and Horse gram Stuffed Paratha Recipe along with a cup of\u00a0Tomato Onion Cucumber Raita Recipe\u00a0and\u00a0Masala Chai Recipe - Indian Spiced Tea\u00a0to make it a complete meal for your Sunday breakfast."]'::jsonb, 50, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Rajma_and_Horse_gram_Stuffed_Paratha_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/34.Rajma_and_Horse_gram_Stuffed_Paratha_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bendekayi Koddel/Bolu Huli Recipe - Mangalorean Style Bhindi Sambar Recipe', 'bendekayi-koddel-bolu-huli-recipe-mangalorean-style-bhindi-sambar-recipe', 'Bendekayi Koddel/Bolu Huli Recipe is a Mangalorean Style Bhindi Sambar Recipe that is made without coconut. Bolu Huli can be prepared from various vegetables like chayote, mangalorean cucumber, ridge gourd and more. To make bendekayi koddel, you should saute the bhindi until the sliminess is evaporated. This bolu huli has a typical coconut oil tempering with cumin seeds and hing. So what are you waiting for? Make this delicious Sambar for your next weekday lunch.', '["25 Bhindi (Lady Finger/Okra) , cut to about an inch", "1 cup Arhar dal (Split Toor Dal) , cooked till soft", "1/4 teaspoon Turmeric powder (Haldi)", "2 Green Chillies , slit (adjust)", "Tamarind , gooseberry sized", "2 teaspoon Jaggery", "2 teaspoons Rasam Powder", "Salt , to taste", "1-1/2 tablespoons Coconut Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1 pinch Asafoetida (hing)", "Curry leaves , a few"]'::jsonb, ARRAY['salt', 'bhindi (lady fingerokra) an', 'mustard seeds', 'asafoetida (hing)', 'tamarind gooseberry', 'jaggery', 'curry leaves', 'coconut oil', 'rasam powder', 'cumin seeds (jeera)', 'arhar dal (split toor dal) till soft', 'turmeric powder', 'green chillies']::text[], '["To begin making the Bendekayi Koddel/Bolu Huli or Mangalorean Style Bhindi Sambar Recipe, firstly keep everything ready with all the ingredients required.In a heavy bottomed pan, heat a tablespoon coconut oil and roast the bhindi till all the sliminess disappears and the pieces appear crisp.In a saucepan, add tamarind water, slit green chillies and haldi.", "Add the roasted bhindi/bendekayi to it.", "Boil them till lady finger are cooked well.Once the mixture seethed and bhindi are tender, add cooked toor dal, salt, jaggery, rasam powder and adequate water to it.", "Boil well on low flame.The next step is to temper the dal.", "Heat a tadka pan with coconut oil.", "Add mustard seeds and allow it to crackle.Add cumin and cook it for about 10 seconds.", "After 10 seconds, add hing, curry leaves and saute on low flame for about 30 seconds.", "Make sure that you dont burn them.", "Once it is ready, pour it over the sambar and give it a mix.", "It is ready to be served.Serve\u00a0Bendekayi Koddel along with\u00a0Steamed Rice\u00a0and\u00a0Sweet Corn Poriyal\u00a0for a weekday lunch with your family or pack it in their lunch box."]'::jsonb, 30, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/BENDEKAYI_BOL_KODDEL__BENDEKAYI_BOLUHULI_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/35.BENDEKAYI_BOL_KODDEL__BENDEKAYI_BOLUHULI_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kodava Mudi Chekke Barthad Recipe - Raw Jackfruit & Black Chickpea Stir Fry', 'kodava-mudi-chekke-barthad-recipe-raw-jackfruit-black-chickpea-stir-fry', 'Kodava Mudi Chekke Barthad Recipe-Raw Jackfruit & Black Chickpea Stir Fry is a classic combination in kodagu district. The jackfruit seeds are widely in most of the South Indian cooking.', '["10 Jackfruit Seeds (Kathal)", "1 cup Kala Chana (Brown Chickpeas) , soaked overnight", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves", "1 Tomato , chopped", "1/2 cup Tamarind Water", "1 teaspoon Turmeric powder (Haldi)", "4 Dry Red Chillies", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Coriander (Dhania) Seeds", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1/2 cup Fresh coconut", "1 inch Ginger", "4 cloves Garlic"]'::jsonb, ARRAY['jackfruit seeds', 'kathal', 'kala chana', 'brown chickpeas', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'curry leaves', 'tomato', 'tamarind water', 'turmeric powder', 'haldi', 'dry red chillies', 'coriander', 'dhania', 'laung', 'cinnamon stick', 'dalchini', 'fresh coconut', 'ginger', 's garlic']::text[], '["To begin making the Kodava Mudi Chekke Barthad Recipe, soak the chickpeas overnight and pressure cook them in 2 cups of water, salt to taste and cook for 6 to 8 whistles for about 20 to 25 minutes.Once done allow the pressure to release naturally.", "Drain the water out from the chickpeas.", "Into the same cooker add the jackfruit seeds and 1 cup of water and pressure cook for at least 3 whistles.Release the pressure, drain any excess water and leave the seeds to dry, once it has cool down, peel off the skin and chop them into small pieces.Grind, dry red chillies, cumin seeds, coriander seeds, cloves, cinnamon, coconut, ginger and garlic to a coarse paste, you can add little water if needed.", "Keep it aside.Heat a kadai with oil, add mustard seeds, cumin seeds and splutter for few seconds.", "Add curry leaves and allow it to crackle for few seconds.Add in chopped tomatoes and saute till the tomatoes become slightly mushy.", "Add in the ground coconut masala.", "Sprinkle turmeric powder and salt and give it a mix.Cook for 5 minutes and add in the boiled chickpeas and chopped jackfruit.", "Pour in the tamarind water and sprinkle salt for seasonings and mix well.Cook the\u00a0Mudi Chekke Barthad for another 2 minutes until all the masala has been absorbed.", "Check the salt and spices and adjust to taste accordingly.", "Once done turn off the heat and transfer the\u00a0Mudi Chekke Barthad to a serving bowl.Serve the\u00a0Kodava Mudi Chekke Barthad Recipe\u00a0along with\u00a0Palak Tovve or Palak Dal\u00a0 and\u00a0Jolada Roti\u00a0and Raita to have it for your every Lunch Meals."]'::jsonb, 55, 'Coorg', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/July-25/Mudi_Chekke_Barthad_Recipe_Raw_Jackfruit_Seeds_and_Black_Chickpea_Sabzi-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/36.Mudi_Chekke_Barthad_Recipe_Raw_Jackfruit_Seeds_and_Black_Chickpea_Sabzi-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Udupi Style Ash Gourd Coconut Curry Recipe', 'udupi-style-ash-gourd-coconut-curry-recipe', 'Udupi Style Ash Gourd Coconut Curry Recipe is a quick coconut based curry made from Ash gourd. Coconut being the main ingredient used in most of their cooking in Udupi, the curry has a strong flavor of coconut as well the roasted spices which gives out a wonderful flavor and aroma.', '["500 grams Vellai Poosanikai (Ash gourd/White Pumpkin)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Oil , for cooking", "To be roasted and ground to paste", "4 Dry Red Chillies", "1/2 cup Fresh coconut , grated", "30 grams Tamarind Water", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1/2 teaspoon Cumin seeds (Jeera)", "2 teaspoons Coriander (Dhania) Seeds", "2 teaspoons Sesame seeds (Til seeds)", "3 tablespoons Jaggery", "1 cup Tamarind Water", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 sprig Curry leaves , roughly torn", "1 Dry Red Chillies"]'::jsonb, ARRAY['salt', 'tamarind water', 'coconut', 'mustard seeds', 'jaggery', 'vellai poosanikai (ash gourdwhite pumpkin)', 'curry leaves', 'dry red chillies', 'coriander (dhania) seeds', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'turmeric powder', 'sesame seeds (til seeds)', 'sunflower oil']::text[], '["To begin making the Udupi Style Ash Gourd Coconut Curry Recipe\u00a0 cook the ash gourd in the pressure cooker with little water, turmeric powder and salt for just 1 whistle.", "Release the pressure naturally.Soak the tamarind ball in hot water for about 15 minutes, and squeeze and keep the water.Then dry roast the spices and other ingredients for the ground paste in a pan except the coconut.", "Then grind it along with coconut to a smooth paste.In same pressure cooker which has the ash gourd add the paste and little water and give it stir.", "Keep\u00a0the Udupi Ash Gourd Coconut Curry on the medium heat, Adjust the seasoning and texture if required.", "Once done transfer it in a bowl.For the seasoning, heat oil in a small skillet and add mustard seeds and let it crackle.", "After the mustard seeds have crackled add the curry leaves and red chillies.", "Tun off the heat after the red chillies have darkened and add it on top of the Udupi Style Ash Gourd Coconut Curry and serve.", "Serve the Udupi Style Ash Gourd Coconut Curry Recipe along with steamed rice,\u00a0Elai Vadam \u00a0and\u00a0Pisarna Manga for lunch."]'::jsonb, 40, 'Udupi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Udupi_Style_Ash_Gourd_Coconut_Curry_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/37.Udupi_Style_Ash_Gourd_Coconut_Curry_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Urulaikizhangu Puli Thokku Recipe (South Indian Style Potatoes with Tamarind)', 'urulaikizhangu-puli-thokku-recipe-south-indian-style-potatoes-with-tamarind', 'Urulaikizhangu Puli Thokku Recipe (South Indian Style Potatoes with Tamarind) is a quick and easy to make. It is different from the other regular potato roast recipes. The addition of tamarind renders a beautiful flavour and taste to the potato dish. It is spicy and tangy, also it has no onion or garlic in it. Serve the Urulaikizhangu Puli Thokku Recipe along with the steamed rice, Thakkali Vengayam Sambar recipe, Beets, Garlic, Lemon rasam, Carrots and Beans Poriyal and Papads as a part of your elaborate weekend brunch menu.', '[]'::jsonb, '{}'::text[], '["To begin making Urulaikizhangu Puli Thokku Recipe, wash and boil the potatoes using a pressure cooker for 2 whistles.", "The potatoes should be cooked yet firm.Once cooked, peel the skin of the potatoes, cut it into cubes and keep aside.Heat oil in a saucepan on medium heat, add the mustard seeds and chana dal and let it crackle.Add the asafoetida, curry leaves and dried red chilli and let it splutter.Add the tamarind paste and the spice powders - red chilli, coriander and sambar powder.Add a 1/4 cup of water and let the mixture boil for a few minutes until the raw smell of the tamarind goes away.Once it comes to a paste consistency, add the boiled potatoes, season with salt and toss the potatoes well in the tamarind spice mix.Let the potato mix simmer for 10 minutes until it becomes a little dry and switch off the flame.Serve the Urulaikizhangu Puli Thokku Recipe along with steamed rice,\u00a0Thakkali Vengayam Sambar recipe,\u00a0Beets, Garlic, Lemon rasam,\u00a0Carrots and Beans Poriyal\u00a0and Papads as a part of your elaborate weekend brunch menu."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Urulaikizhangu_Puli_Thokku_Recipe_South_Indian_Style_Potatoes_with_Tamarind.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/38.Urulaikizhangu_Puli_Thokku_Recipe_South_Indian_Style_Potatoes_with_Tamarind.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Konkani Style Kotte Saaru/Halasina Bijada Saru Recipe-Jackfruit Seed Rasam', 'konkani-style-kotte-saaru-halasina-bijada-saru-recipe-jackfruit-seed-rasam', 'Konkani Style Kotte Saaru or Halasina Bijada Saru Recipe is essentially Jackfruit Seed Rasam.', '["Ingredients to grind", "10 Jackfruit Seeds (Kathal)", "2 Green Chillies", "4 cloves Garlic", "18 grams Tamarind", "2 tablespoon Rasam Powder", "1 Onion , chopped", "2 cloves Garlic , pound", "1 teaspoon Turmeric powder (Haldi)", "2 tablespoon Oil", "1 teaspoon Turmeric powder (Haldi)", "2 sprig Curry leaves"]'::jsonb, ARRAY['ingredients to grind', 'jackfruit seeds', 'kathal', 'reen chillies', 's garlic', 's tamarind', 'rasam powder', 'onion', 'turmeric powder', 'haldi', 'oil', 'curry leaves']::text[], '["We begin making the Konkani Style Kotte Saaru/Halasina Bijada Saru Recipe\u00a0by making the base for the rasam.Heat a saucepan on medium flame, combine the jackfruit seeds along with 2 cups of water, green chillies, garlic and tamarind and allow to boil till the seeds are cooked, this will take about 30 minutes.Once boiled, strain the water and keep aside, as that is the base of the rasam.Peel off the skin from the seeds and set aside.", "Cut the seeds into small pieces and transfer it to a mixer-jar along with the tamarind, green chillies, garlic cloves and grind them into a fine paste.", "Keep it aside.Heat a pan on medium flame, add oil, once the oil is hot, add in the chopped onions, garlic and saute till translucent.Then add in the strained water, the ground masala, rasam powder, turmeric powder and bring it to a boil.Adjust the seasoning and leave it to boil for 15 more minutes.In a tadka pan, heat oil on medium flame, add the mustard seeds and curry leaves, allow it to splutter, turn off the flame and pour it over the rasam.Serve the\u00a0Konkani Style Kotte Saaru/Halasina Bijada Saru Recipe along with some\u00a0Steamed rice\u00a0and\u00a0Gorikayi Palya Recipe\u00a0and end it with\u00a0Semiya Payasam With Coconut Milk Recipe."]'::jsonb, 50, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Konkani_Style_Kotte_SaaruHalasina_Bijada_Saru_Recipe_Jackfruit_Seed_Rasam.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/39.Konkani_Style_Kotte_SaaruHalasina_Bijada_Saru_Recipe_Jackfruit_Seed_Rasam.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Taroo Root Curry Recipe (Colacasia)', 'kerala-style-taroo-root-curry-recipe-colacasia', 'Kerala Style Taro Root Curry uses Arbi  which is widely used across India in various ways. This Kerala style Taro Root curry is made using fresh coconut and is classically served with steamed rice. Malabar tamarind is traditionally used as a souring agent, which also helps in destroying the allergens, if any, from the starchy tuber. Though it has a distinct smoky flavor, you can substitute the Malabar tamarind with dried Kokum skin or the regular tamarind.', '["250 grams Colocasia root (Arbi) , washed thoroughly and peeled", "1 Tamarind , malabar", "Salt , to taste", "1/4 cup Fresh coconut , scrapped", "1 teaspoon Red Chilli powder", "2 Onions , peeled", "1 tablespoon Coconut Oil", "2 Onions , peeled and chopped", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chilli , broken", "7 Curry leaves"]'::jsonb, ARRAY['s colocasia root', 'arbi', 'tamarind', 'salt', 'fresh coconut', 'red chilli powder', 'onions', 'coconut oil', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'dry red chilli', 'curry leaves']::text[], '["To begin making the Kerala style Taro root curry, first thoroughly wash and scrub theboiled Taro roots. (You can soak them for 20-30 minutes in water, so that the dirt comes off easily)Apply some coconut (or any other) oil to your hands and peel them.", "Be sure to remove the green layer under the skin too.Cut the Taro root into bite sized pieces.In a sauce pan/Kadai or a seasoned earthen pot add the Taro root, tamarind piece(s), salt and some water.", "Cook on low flame till it is well cooked.Meanwhile, in a mixer blend together the coconut, chilli powder and small onions.Add this mixture to the cooked Taro roots, add salt if required and cook for 5-6 minutes more.Heat oil in a small pan and add the mustard seeds.", "Once they splutter add the cumin seeds.Add the onions, curry leaves and saut\u00e9 for a minute.Add the red chillies, saut\u00e9 for a few seconds and add this tempering to the Taro root curry.Mix well and cook for 1-2 minutes.Your Kerala Style Taroo Root Curry Recipe Is ready, serve with hot rice or phulkas."]'::jsonb, 40, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Kerala_style_Taro_root_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/40.Kerala_style_Taro_root_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('तुरई चना सब्ज़ी - Ridge Gourd With Black Gram Dal (Recipe In Hindi)', 'ridge-gourd-with-black-gram-dal-recipe-in-hindi', 'तुरई चना सब्ज़ी एक बहुत ही सरल सब्ज़ी है जिसे उत्तर प्रदेश में बहुत बनाया जाता है. यह सब्ज़ी आप रोज के खाने के लिए बना सकते है. इस रेसिपी को आप दिन के काने के लिए पंचमेल दाल और लच्छा पराठा के साथ गरमा गरम परोसे।', '["1 \u0915\u092a \u0915\u093e\u0932\u093e \u091a\u0928\u093e", "2 \u0924\u0941\u0930\u0908", "2 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u0938\u0930\u0938\u094b \u0915\u093e \u0924\u0947\u0932", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u092e\u0947\u0925\u0940 \u0915\u0947 \u0926\u093e\u0928\u0947", "\u0939\u0940\u0902\u0917 , \u091a\u0941\u091f\u0915\u0940 \u092d\u0930", "2 \u092a\u094d\u092f\u093e\u091c , \u0915\u093e\u091f\u0947 \u0939\u0941\u090f", "6 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928 , \u0915\u093e\u091f\u093e \u0939\u0941\u0906", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0915\u093e\u091f\u093e \u0939\u0941\u0906", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0905\u092e\u091a\u0942\u0930 \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947 \u0915\u0947 \u0932\u093f\u090f"]'::jsonb, ARRAY['कप काला चना', 'तुरई', 'बड़ा चमच्च सरसो का तेल', 'छोटा चमच्च मेथी के दाने', 'हींग', 'प्याज', 'कली लहसुन', 'हरी मिर्च', 'छोटा चमच्च हल्दी पाउडर', 'छोटा चमच्च धनिया पाउडर', 'छोटा चमच्च जीरा पाउडर', 'छोटा चमच्च लाल मिर्च पाउडर', 'छोटा चमच्च गरम मसाला पाउडर', 'छोटा चमच्च अमचूर पाउडर', 'नमक', 'हरा धनिया']::text[], '["\u0924\u0941\u0930\u0908 \u091a\u0928\u093e \u0938\u092c\u094d\u095b\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f, \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0915\u093e\u0932\u0947 \u091a\u0928\u0947 \u0915\u094b 6 \u0938\u0947 8 \u0918\u0902\u091f\u094b \u0915\u0947 \u0932\u093f\u090f \u092d\u093f\u0917\u094b \u0915\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u0924\u0941\u0930\u0908 \u0915\u093e \u091b\u093f\u0932\u0915\u093e \u091b\u093f\u0932\u0915\u0947 \u0909\u0938\u0947 \u0915\u093e\u091f \u0932\u0947. \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902 \u0914\u0930 \u0909\u0938\u092e\u0947 \u092e\u0947\u0925\u0940 \u0915\u0947 \u092c\u0940\u091c \u0914\u0930 \u0939\u0940\u0902\u0917 \u0921\u093e\u0932\u0947\u0964\u00a010 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u092c\u093e\u0926 \u0909\u0938\u092e\u0947 \u092a\u094d\u092f\u093e\u091c, \u0932\u0939\u0938\u0941\u0928 \u0914\u0930 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947\u0964 \u0924\u092c \u0924\u0915 \u092a\u0915\u093e\u090f\u00a0\u091c\u092c \u0924\u0915 \u092a\u094d\u092f\u093e\u091c \u0928\u0930\u092e \u0928 \u0939\u094b \u091c\u093e\u092f\u0947\u0964\u00a0\u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930 \u0914\u0930 \u0928\u092e\u0915 \u0921\u093e\u0932\u0947\u0964 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u092e\u093f\u0932\u093e\u090f \u0914\u0930 3 \u0938\u0947 5 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u0928\u0947 \u0926\u0947.\u00a0\u0909\u0938\u0915\u0947 \u092c\u093e\u0926 \u0915\u0932\u093e \u091a\u0928\u093e \u0914\u0930 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 10 \u0938\u0947 12 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u0928\u0947 \u0926\u0947.\u00a0.10 \u0938\u0947 12 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0924\u0941\u0930\u0908 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. \u0906\u0916\u093f\u0930 \u092e\u0947\u0902 \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930, \u0905\u092e\u091a\u0942\u0930 \u0914\u0930 \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947\u0964 \u0938\u092c \u0915\u094b \u092e\u093f\u0932\u093e \u0932\u0947 \u0914\u0930 2 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0914\u0930 \u092a\u0915\u093e\u090f\u0964 \u0905\u092c \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u0938\u093e\u0925 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0907\u0938 \u0930\u0947\u0938\u093f\u092a\u0940 \u0915\u094b \u0906\u092a \u0926\u093f\u0928 \u0915\u0947 \u0915\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0902\u091a\u092e\u0947\u0932 \u0926\u093e\u0932 \u0914\u0930 \u0932\u091a\u094d\u091b\u093e \u092a\u0930\u093e\u0920\u093e \u0915\u0947 \u0938\u093e\u0925 \u0917\u0930\u092e\u093e \u0917\u0930\u092e \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/_NenuaChana_Sabzi_Gravy__Ridge_Gourd_with_black_gram_dal_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/41._NenuaChana_Sabzi_Gravy__Ridge_Gourd_with_black_gram_dal_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Cherupayar Curry Recipe (Green Moong and Yellow Moong Dal Recipe)', 'kerala-cherupayar-curry-recipe-green-moong-and-yellow-moong-dal-recipe', 'Kerala Cherupayar Curry Recipe (Green Moong and Yellow Moong Dal Recipe) is a comforting dal made from a blend of green mung bean and yellow mung bean lentil. Cherupayar refers to the green moong lentil in Malayalam. The curry is made with simple flavors and the addition of coconut oil in the dal lifts the whole flavor of the dish. Mung Beans are a high source of fiber, protein and antioxidants. As it has the high nutrient intensity it will be really helpful for fighting diseases like diabetes and obesity.', '["1 cup Green Moong Dal (Whole)", "1/2 cup Yellow Moong Dal (Split)", "10 Pearl onions (Sambar Onions)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "2 Dry Red Chilli", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Coconut Oil , for cooking", "Ingredients to grind", "1/2 cup Fresh coconut", "2 Green Chilli", "1 teaspoon Cumin seeds (Jeera)"]'::jsonb, ARRAY['salt', 'yellow moong dal (split)', 'green chilli', 'mustard seeds', 'coconut', 'dry red chilli', 'pearl onion (sambar onion)', 'curry leaves', 'coconut oil', 'cumin seeds (jeera)', 'green moong dal', 'turmeric powder']::text[], '["To begin making the Kerala Cherupayar Curry Recipe, soak the green mung bean in water for at least 2 hours.Pressure cook the green mung bean with water for about 4 whistle till it is just cooked.", "Once the pressure has released naturally, take them out and pressure cook the yellow moong dal now by adding some water, turmeric powder and pressure cook for 4 whistle.Wait for the pressure to release naturally and mash the dal to a smooth paste.Heat a kadai with oil, add mustard seeds and allow it splutter for few seconds and add curry leaves and be careful as it will splutter quickly.Add the whole shallots and saute until they soften.", "Add mashed yellow moong dal along with cooked green moong dal and mix well.", "Cook in simmer.Meanwhile grind the coconut, green chilli, cumin seeds in a mixer and grind it into a smooth paste by adding little water.", "Add this ground paste into the boiling dal, adjust your salt levels and boil for another 10 minutes and serve hot.", "Serve the Kerala Cherupayar Curry Recipe along with\u00a0puttu\u00a0or\u00a0steamed rice.", "It can also be paired with\u00a0phulka\u00a0for a lunch box."]'::jsonb, 90, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Kerala_Cherupayar_Curry_Recipe_Green_Moong_and_Yellow_Moong_Dal_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/42.Kerala_Cherupayar_Curry_Recipe_Green_Moong_and_Yellow_Moong_Dal_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Buckwheat Vegetable Khichdi Recipe', 'buckwheat-vegetable-khichdi-recipe', 'Eating whole grain and ancient grains is helping me keep fit and healthy. There was a time when I kept away from the grains not knowing it’s benefits. But once I learnt about the benefits of whole grains I started including it in my diet. Initially, I have been experimenting with the grain by making dishes out of it and ate it all by my own. Now, I started giving it to my family and kids too. Buckwheat is actually not a grain; it’s a grain like fruit seeds, a super food. Buckwheat may be one of the super foods you are not eating. Not only is it healthy, but tasty too. And it’s a great substitution for rice! Make every day khichdi, pulav or even other variety rice dishes with buckwheat. This vegetable khichdi using buckwheat is the simplest dish just like any other khichdi and the taste is amazing too.', '["1 cup Buckwheat Flour (Kuttu Ka Atta)", "1/4 cup Yellow Moong Dal (Split)", "2 Carrots (Gajjar) , finely chopped", "8 Green beans (French Beans) , finely chopped", "2 Potatoes (Aloo) , cut into cubes", "1/4 cup Green peas (Matar)", "2 teaspoon Ajwain (Carom seeds)", "3 Green Chillies , slit", "2 cloves Cloves (Laung) , 2 cloves", "8 Whole Black Peppercorns", "Salt , to taste", "Water , as required", "2 tablespoons Oil", "2 tablespoons Ghee", "1/2 Onion , sliced", "4 to 5 cloves Garlic , sliced"]'::jsonb, ARRAY['salt', 'yellow moong dal (split)', 'green beans (french beans)', 'ghee', 'cloves cloves (laung) cloves', 'ajwain (carom seeds)', 'green peas (matar)', 'black peppercorns', 'carrot', 'water', 'cloves garlic', 'onion', 'buckwheat flour (kuttu ka atta)', 'potato (aloo)', 'green chillies', 'sunflower oil']::text[], '["To begin making the Buckwheat Vegetable Khichdi recipe, firstly rinse the buckwheat in water.", "Soak it for atleast 2 hours.Soak the moong dal for about half an hour.Next, in a pressure cooker add oil and ghee.", "Once oil and ghee turns hot add shahi jeera and wait till it turns golden brown.Add slit green chilies, pepper corns and cloves, cook for 30 seconds.Add chopped vegetables and cook on medium heat for about 5 minutes.Drain buckwheat and moong dal from water and add it into the cooker.", "Saute for 2 to 3 minutes, stirring continuously.Add 5 cups hot water into the cooker, along with salt to taste and mix well.Cover the lid of pressure cooker and cook for 2 whistles.Once pressure settles down, open the cooker lid and mix khichdi well.In a tadka pan, heat 1 teaspoon ghee.", "Fry some sliced garlic and onion slices until golden brown.", "Pour it over the khichdi.Serve Buckwheat Vegetable Khichdi along with\u00a0Tomato Onion Cucumber Raita,\u00a0Tadka Raita\u00a0or any other Raita of your choice for a light and healthy dinner."]'::jsonb, 150, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Buckwheat_Vegetable_Khichdi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/43.Buckwheat_Vegetable_Khichdi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Eggplant In Mustard Poppy Seed Yogurt Gravy Recipe-Begun Doi Sorse Posto bata Jhol', 'eggplant-in-mustard-poppy-seed-yogurt-gravy-recipe-begun-doi-sorse-posto-bata-jhol', 'Begun Doi Sorse Posto bata Jhol or Eggplant in Mustard Poppy Seed Yogurt Gravy is a Bengali vegetarian dish. The eggplant is its main ingredient which is first marinated in chilli powder, turmeric powder and salt. It is then shallow fried till golden and then simmer in a gravy of  mustard-poppy seed paste and curd. Panch Phoran masala adds a signature Bengali flavor to the Eggplant gravy.', '["1 Brinjal (Baingan / Eggplant) , cut into 1/2 inch discs", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 1/2 tablespoons Mustard seeds (Rai/ Kadugu)", "1 tablespoon Poppy seeds", "Mustard oil , as required", "1 teaspoon Panch Phoran Masala", "4 Green Chillies", "1/2 cup Curd (Dahi / Yogurt)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard oil', 'mustard seeds', 'brinjal (baingan eggsplant)', 'red chilli powder', 'curd', 'poppy seeds', 'panch phoran masala', 'turmeric powder', 'green chillies']::text[], '["To begin making\u00a0Eggplant In Mustard Poppy Seed Yogurt Gravy Recipe - Begun Doi Sorse Posto bata Jhol, soak the mustard seeds and poppy seeds in a little amount of water for about 10 minutes.Drain and add the soaked mustard and poppy seeds in a mixer grinder, along with the green chilies.", "Add about quarter cup water and grind it into a smooth paste.", "Keep the mustard poppy seed paste aside.Rub eggplant discs on both the sides with half of turmeric, red chili powder and salt.In a pan, add a little oil and when the oil is hot, lower the heat and shallow fry the brinjal rounds on each side\u00a0 for 2-3 minutes or till the round is light golden brown on both the sides.Once cooked properly, place the fried brinjal rounds on an oil absorbent paper.Heat one tablespoon mustard oil in a pan.", "When the oil is hot, add a teaspoon of panch phoran masala.", "Saut\u00e9 on low heat for a few seconds till the seeds crackle.Once done add the mustard poppy seed paste, remaining turmeric, red chili powder, and salt.", "Stir well to combine.Whisk the curd and add to the masala.", "Stir and cook for a couple of minutes.Add half a cup of water, salt to taste and bring the curry to a boil on medium heat.", "Lower the heat and add the fried brinjal rounds.", "Continue simmering on low heat for another 7-8 minutes and turn off the heat.Transfer\u00a0Eggplant In Mustard Poppy Seed Yogurt Gravy into a serving bowl and serve.Serve Eggplant In Mustard Poppy Seed Yogurt Gravy Recipe\u00a0with\u00a0Steamed Rice Recipe\u00a0or\u00a0Phulka Recipe\u00a0for lunch or dinner."]'::jsonb, 45, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Antara_Navin/Eggplant_in_Mustard_Poppy_Seed_Yogurt_Gravy.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/44.Eggplant_in_Mustard_Poppy_Seed_Yogurt_Gravy.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mangalorean Style Ambe Upkari Recipe - Ripe Mango Curry', 'mangalorean-style-ambe-upkari-recipe-ripe-mango-curry', 'Mangalorean Style Ambe Upkari Recipe is a spicy, tangy - sweet curry made with ripe mangoes, along with some jaggery, and the addition of simple South Indian spices, and finished off with a classic tadka that instantly lifts up the dish.', '["6 Mango (Ripe) , (fibrous smaller variety suits best)", "1/2 cup Jaggery , powdered (adjust to sweetness of mangoes)", "2 Green Chillies , (adjust to taste)", "1 teaspoon Ghee , or coconut oil", "2 Dry Red Chillies", "1/2 teaspoon White Urad Dal (Split)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 pinch Asafoetida (hing)"]'::jsonb, ARRAY['mustard seeds', 'asafoetida (hing)', 'white urad dal (split)', 'dry red chillies', 'ghee coconut oil', 'green chillies', 'jaggery ( sweetness mangoes)', 'mango (ripe) (fibrous smer variety suits best)']::text[], '["To begin making Mangalorean Style Ambe Upkari Recipe, wash mangoes well.", "Peel the skin with your hands.", "Some mango pulp will be adhering to the skin; that is ok; it will not go waste.Place the peeled mango in a saucepan and the peels in a bowl.Add water, about 1/4 cup to the bowl with the mango peels, just enough that they are dipped in water.Keep squeezing the peels well in the bowl with your hands to remove the pulp still sticking to it as much as possible.Transfer this water to the saucepan containing the peeled ripe mangoes.", "Keep repeating (adding more water) until the water is almost clear.Add slit green chillies to the mangoes in the saucepan.", "Heat on medium heat and bring to a boil.Once it comes to a boil, reduce the heat and simmer for about 10 to 15 minutes until the mangoes are cooked well and become soft; about 15 to 20 minutes.Add jaggery to taste along with some salt; adjust to suit your taste; mix well.Simmer for about 5 minutes or more until you get a good consistency.We love our mango curry a bit diluted; but if you want a thicker gravy, you can add a slurry of rice flour in water (about 2 to 3 teaspoons of rice flour in \u00bc cup of water) to the boiling curry and boil until thick.Now, it is time to season or temper the curry.In a small saucepan, heat ghee.", "Once the ghee is hot, add mustard seeds and when they start to splutter and crackle, add the dry red chillies and hing.Immediately add to the curry and give it a good stir.Sweet, tangy and exotic Konkani style mango curry is ready.Mangalorean Style Ambe Upkari Recipe is usually served as a side dish with a South Indian Meal of Steamed rice,\u00a0Mangalorean Style Sajjige Rotti, steamed rice,\u00a0Sprouted Moong Dal Curry\u00a0and\u00a0Mangalorean Style Sonay Sukka Recipe (Dry Chickpea Stir Fry Recipe)."]'::jsonb, 40, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Curryandvanilla/Ambe_Upkari.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/45.Ambe_Upkari.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Peshawari Kala Chana Recipe', 'peshawari-kala-chana-recipe', 'Peshawar, a popular city in Pakistan in known for its rich art and culture. It is also known for its delicious cuisine which is rich and has a prominent use of flavorful and tangy spices. Most of our Punjabi cuisine in India is influenced by the Peshawar style of cooking. Peshawari Kala Chana Recipe is simple to make, yet flavorful with nutritional benefits of sprouted black chickpeas or kala chana.', '["2 cups Kala Chana (Brown Chickpeas) , sprouted", "1 Onion , sliced", "1 cup Tomatoes , finely chopped", "1 tablespoon Ginger , paste", "2 Green Chillies , finely chopped", "1 inch Cinnamon Stick (Dalchini)", "2 Black cardamom (Badi Elaichi)", "1 tablespoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "2 tablespoons Chana Masala Powder", "1 tablespoon Anardana Powder (Pomegranate Seed Powder) , dried", "2-3 teaspoon Coriander (Dhania) Leaves , finely chopped for garnish", "2 tablespoons Ghee", "Salt , to taste"]'::jsonb, ARRAY['kala chana (brown chickpeas) sprouted', 'tomato', 'black cardamom (badi elaichi)', 'salt', 'coriander powder', 'anardana powder (pomegranate seed powder) dried', 'ghee', 'chana masala powder', 'coriander (dhania) leaves', 'red chilli powder', 'onion', 'cinnamon stick (dalchini)', 'ginger paste', 'green chillies']::text[], '["To begin making the Peshawari Kala Chana, wash and pressure cook the sprouted kala chana for two whistles in a pressure cooker and keep aside.Heat ghee in a wok on medium flame, add the whole spices - black cardamom and cinnamon stick and let it release its aroma into the ghee.Add the sliced onions and fry until it turns brown, this will take around 10 minutes.Now, add the tomatoes, ginger paste and finely chopped green chillies and saute until tomatoes become soft.Add the spice powders - coriander, red chilli, chole masala and dried pomegranate powder and saute until the ghee leaves the sides.Now, add the boiled spouted kala chana and enough water to your desired consistency.Season with salt and simmer for 10 minutes.Garnish with coriander leaves and serve the Peshawari Kala Chana along with \u00a0lachha parathas\u00a0or steamed rice and green salads for a weeknight dinner."]'::jsonb, 60, 'Pakistani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Peshawari_Kala_Chana_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/46.Peshawari_Kala_Chana_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Pakora Curry Recipe', 'chettinad-pakora-curry-recipe', 'Chettinad Pakora Curry Recipe is a delicious lentil pakodas cooked in a spicy chettinad gravy. Chettinad recipes have a predominant flavour of fennel, cinnamon, garlic and red chillies making it very delectable. Though, this recipe is a bit spicy, you can alter the spiciness to your desired level. It is a semi gravy that goes very well as a side dish to indian meal. Serve the Chettinad Pakora Curry Recipe along with Tawa Parathas or Roti''s, Steamed Rice, Poondu Rasam and Papad for a weeknight dinner.', '["To make the pakodas", "1/2 cup Chana dal (Bengal Gram Dal) , soaked for 20 minutes", "2 Dry Red Chillies", "1 teaspoon Fennel seeds (Saunf)", "Salt , to taste", "Oil , for frying the pakodas", "To make the gravy", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1 Green Chillies , finely chopped", "7 cloves Garlic , finely chopped", "2 teaspoons Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1 Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta)", "2 Cardamom (Elaichi) Pods/Seeds", "1 teaspoon Fennel seeds (Saunf)", "1 sprig Curry leaves", "2 teaspoons Coriander (Dhania) Leaves , finely chopped for garnish", "1 tablespoon Oil", "Salt , to taste", "To make the paste", "2 tablespoons Fresh coconut", "1 teaspoon Poppy seeds", "1 teaspoon Fennel seeds (Saunf)", "5 Cashew nuts", "2 tablespoons Roasted Gram Dal (Pottukadalai)"]'::jsonb, ARRAY['tomato', 'cloves garlic', 'curry leaves', 'onion', 'green chillies', 'chana dal (bengal gram dal)', 'sunflower oil', 'salt', 'cardamom (elaichi) podsseeds', 'dry red chillies', 'coconut', 'coriander (dhania) leaves', 'red chilli powder', 'cashew nuts', 'sunflower oil the pakodas', 'bay leaf (tej patta)', 'fennel seeds (saunf)', 'gram dal (pottukadalai)', 'cinnamon stick (dalchini)', 'poppy seeds', 'coriander powder']::text[], '["To begin making\u00a0Chettinad Pakoda Curry Recipe, we first prepare making the batter for the pakodas.Soak the channa dal along with red chillies for 20 minutes and then grind it with fennel seeds, salt using a mixer grinder to a coarse paste with very little water.Now, heat oil in a pan, and drop a spoon full of the pakoda mix into the oil and fry until golden brown in medium heat.Remove it on a kitchen towel and keep aside.Like wise, prepare the next batch of the pakodas with the remaining batter and keep aside.Now, grind the ingredients mentioned in the ''to grind'' table to a smooth paste using a mixer grinder and keep aside.To prepare the gravy, heat oil in a pan, add the bay leaf, cinnamon stick, cardamom and let it release its aroma into the oil.Add the fennel seeds, curry leaves and let it splutter.Add the garlic and fry until golden brown.Add the finely chopped onions and saute until transparent.Add the tomatoes, green chillies, a pinch of saute and saute until the tomatoes are mushy.Add the coriander and red chilli powder and saute for a minute.Now, add the ground paste, 1.5 cups of water, salt and simmer until the masala paste is cooked well and the gravy comes together.Add in the prepared pakodas and simmer for another 5 minutes.The gravy will eventually be watery, but the pakodas will soak up the water and thicken the gravy.Switch off the flame and garnish with coriander leaves.Serve the\u00a0Chettinad Pakoda Curry Recipe along with Tawa Parathas\u00a0or Roti''s,\u00a0Steamed Rice,\u00a0Poondu Rasam\u00a0and Papad."]'::jsonb, 50, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Chettinad_Pakoda_Curry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/47.Chettinad_Pakoda_Curry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tandoori Chicken Curry Recipe', 'tandoori-chicken-curry-recipe', 'Tandoori Chicken Curry Recipe is a simple and tasty chicken curry recipe that is made, by adding the tandoori masala to the chicken. Tandoori masala spice mix does wonders by enhancing the flavor and taste. You can say its almost like a one post dish which can be put together is almost no time.', '["750 Kg Chicken", "1 tablespoons Oil", "1 Tomatoes , finely chopped", "1 Onion , finely chopped", "2 Green Chillies , chopped", "1/2 Tablespoon Ginger Garlic Paste", "Coriander (Dhania) Leaves , small bunch, finely chopped", "1 Tablespoon Curd (Dahi / Yogurt)", "1 Tablespoon Fresh cream , (Optional just to give thickness to gravy)", "3/4 Cup Water", "Salt , to taste", "3 Cloves (Laung)", "3 Whole Black Peppercorns", "1 Bay leaves (tej patta)", "1 inch Cinnamon Stick (Dalchini)", "1/2 teaspoon Fennel seeds (Saunf)", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "1 Tablespoons Kashmiri Red Chilli Powder", "1 teaspoon Turmeric powder (Haldi)", "1/2 Tablespoon Tandoori masala", "1/2 Tablespoon Onion powder"]'::jsonb, ARRAY['tomato', 'coriander (dhania)', 'salt', 'kashmiri red chilli powder', 'bay leaves (tej patta)', 'fennel seeds (saunf)', 'tandoori masala', 'onion powder', 'water', 'black peppercorns', 'ginger garlic paste', 'curd', 'onion', 'chicken', 'cinnamon stick (dalchini)', 'kasuri methi (dried fenugreek leaves)', 'cloves (laung)', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making Tandoori Chicken Curry Recipe,wash and clean the chicken pieces thoroughly.", "Cut them in to medium curry cut pieces.", "Heat a kadai, on medium flame, add oil, once the oil is hot add in all the whole spices - cloves,\u00a0black pepper corns, bay leaves, cinnamon stick, and fennel seeds\u00a0until fragrant.", "This will take a couple of minutes.", "Next add in the chopped onions, sprinkle some salt over this and saute until the onions are nicely browned.", "This will take 5-6 minutes on medium high heat.At this stage add ginger garlic paste and saute till raw smell goes away, for a couple of minutes, on low heat.Add chopped green chillies and tomatoes, mix, cover and let them cook till soft and mushy.Once the tomatoes are mushy, add yogurt, chicken, and water.", "Mix, cover and cook on medium high heat for 5 minutes.Sprinkle all the powdered spices-\u00a0red chili powder, turmeric powder and tandoori masala and mix well.", "Cover and cook on medium high heat until the chicken is well cooked .Open the lid and sprinkle some salt and kasuri methi.", "Simmer on low heat for another 10 minutes.", "Switch off the heat once done.Add milk cream and garnish with chopped coriander leaves to serve.Serve\u00a0Tandoori Chicken Curry Recipe with\u00a0Butter Garlic Naan Recipe (Garlic Flavoured Flat Bread),\u00a0Indian Vegetable Salad Recipe,\u00a0and\u00a0Burani Raita Recipe (Garlic Based Yogurt)\u00a0for a complete meal."]'::jsonb, 55, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/Simple_Tasty_Tandoori_Chicken_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/48.Simple_Tasty_Tandoori_Chicken_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Tomato Cauliflower Koora Recipe', 'andhra-style-tomato-cauliflower-koora-recipe', 'Andhra Style Tomato Cauliflower Koora is a simple recipe made with a tomato and onion gravy that is spiced up with simple masala garam masala powder and red chilli powder.', '["1 Cauliflower (gobi) , cut into small florets", "2 Potatoes (Aloo) , cut into medium sized pieces", "1 Onion , chopped", "2 Tomatoes , chopped", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "4 cloves Garlic , chopped", "2 Green Chillies , slit", "1 tablespoon Red Chilli powder", "2 tablespoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste"]'::jsonb, ARRAY['cauliflower', 'gobi', 'potatoes', 'aloo', 'onion', 'tomatoes', 'mustard seeds', 'rai/ kadugu', 'curry leaves', 's garlic', 'reen chillies', 'red chilli powder', 'garam masala powder', 'coriander powder', 'dhania', 'turmeric powder', 'haldi', 'salt']::text[], '["To begin making the Andhra Style Tomato Cauliflower Koora Recipe, firstly pressure cook the cauliflower and potato with 1 cup water, salt in a pressure cooker for 1 whistle and switch it off.Leave it aside to release the pressure by itself.", "Heat a kadai with oil, add mustard seeds and allow it to splutter for few seconds.Add the curry leaves and crackle them for 10 more seconds.", "Next, add chopped onions, green chilli and garlic.", "Saute the onions till the onion turn translucent.Once the onions are soft and translucent, add tomatoes, a pinch of salt and saute until the tomatoes become mushy and the raw smell goes away.", "Add the cooked cauliflower and potato into the kadai.Add the spice powder like the garam masala, red chilli powder, coriander powder, turmeric powder and mix everything well.", "Cover it with a lid and cook for 2 more minutes.Open the lid check for salt and season it according to your palate.", "Serve the\u00a0Andhra Style Tomato Cauliflower Koora\u00a0along with\u00a0Tawa Paratha,\u00a0Dal Palak Recipe\u00a0and\u00a0Raita\u00a0of your choice to enjoy your everyday meals."]'::jsonb, 40, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Andhra_Style_Tomato_Cauliflower_Koora_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/49.Andhra_Style_Tomato_Cauliflower_Koora_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Amritsari Fish Gravy Recipe', 'amritsari-fish-gravy-recipe', 'Amritsari fish fries are extremely popular in Amritsar and all over India, but have you tried to make gravy along with it? Here instead of frying after dipping in batter we have shallow fried the marinated fish with gram flour. Yes the spices tempered with are little different but definitely a dish to give a try. Cook for a mid week Punjabi dinner and surprise your whole family.', '["300 gram Fish , cutlets", "1/4 teaspoon Ajwain (Carom seeds)", "1 tablespoon Gram flour (besan)", "1 teaspoon Kashmiri Red Chilli Powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Ginger Garlic Paste", "1 teaspoon Lemon juice", "Salt , to taste", "2 teaspoon Oil", "1/4 cup Curd (Dahi / Yogurt) , beaten", "1/3 cup Water", "1/2 teaspoon Ajwain (Carom seeds)", "2 Cinnamon Stick (Dalchini)", "2 Green Chillies", "1 Fresh Red chillies", "1/2 teaspoon Turmeric powder (Haldi)", "1/4 cup Cashew nuts", "1 tablespoon Homemade tomato puree", "1 Onion , chopped", "Coriander (Dhania) Leaves , chopped, for garnish", "2 teaspoon Ghee", "Salt , to taste"]'::jsonb, ARRAY['cashew nuts', 'salt', 'tomato', 'kashmiri red chilli powder', 'red chillies', 'coriander (dhania) leaves', 'ghee', 'ajwain (carom seeds)', 'water', 'gram flour (besan)', 'ginger garlic paste', 'curd', 'cinnamon stick (dalchini)', 'lemon', 'onion', 'gram fish cutlets', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making\u00a0Amritsari Fish Gravy Recipe, first clean and wash the pieces of fish, rub salt keep for aside for five minutes.In a mixing bowl, add ginger and garlic paste, lime juice, carom seeds, gram flour, red chilli powder and turmeric powder.", "Mix well and add the fish pieces in this paste.", "Marinate the fish pieces in the mixture for at least 30 minutes.", "Place a skillet on medium heat and add some oil on top.", "Place the pieces of marinated fish on to the skillet and cook till crispy red.", "Turn the pieces of fish until they are cooked.\u00a0*To make the gravySoak cashews in water, once soft grind it to a paste with little water.", "In a large mixing bowl, add the beaten curd, cashew paste, tomato paste, chilli powder, turmeric powder and water.", "Place a heavy bottomed pan on low flame and add some ghee and add carom seeds.", "Fry for a minute and add in the chopped onions.", "Saute until translucent.", "Add ginger paste and fry for a few more minutes until the raw smell goes away.", "Pour the mixture of curd and cashew paste along with chopped green chillies and red chillies.", "Add salt according to your tasteAdd the fish pieces on serving dish and the gravy on sides.", "Garnish with chopped coriander leaves.Serve Amritsari Fish Gravy Recipe along with\u00a0Whole Wheat Onion Stuffed Kulcha Recipe\u00a0or\u00a0Jeera Rice\u00a0Or\u00a0Steamed Rice\u00a0for a delicious Sunday Meal."]'::jsonb, 45, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/ruby_pathak-yahoo.com/Amritsari_Fish_Gravy.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/50.Amritsari_Fish_Gravy.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Roasted Eggplant And Chickpea Curry Flavored With Curry Leaves And Mustard Seeds', 'roasted-eggplant-and-chickpea-curry-flavored-with-curry-leaves-and-mustard-seeds', 'Roasted Eggplant and Chickpea Curry Recipe is a flavorful dish made in a coconut milk curry. The distinct flavors of curry leaf, turmeric, coriander along with garam masala leave a delectable taste to the palate. Serve Roasted Eggplant And Chickpea Curry Flavored With Curry Leaves And Mustard Seeds along with Indian Breads and rice for lunch/dinner.', '["1 cup Kabuli Chana (White Chickpeas) , soaked overnight and cooked", "1 Brinjal (Baingan / Eggplant) , cut into wedges", "100 ml Coconut milk", "2 Tomatoes , quartered", "1 Onion , finely chopped", "2 Dry Red Chillies", "5 Curry leaves , roughly torn", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 Red Chilli powder", "3 teaspoons Oil", "Salt , to taste"]'::jsonb, ARRAY['kabuli chana', 'white chickpeas', 'brinjal', 'baingan / eggplant', 'coconut milk', 'tomatoes', 'onion', 'dry red chillies', 'curry leaves', 'turmeric powder', 'haldi', 'garam masala powder', 'coriander powder', 'dhania', 'red chilli powder', 's oil', 'salt']::text[], '["To prepare Roasted Eggplant And Chickpea Curry Flavored With Curry Leaves And Mustard Seeds, heat a tablespoon of oil in a heavy bottomed pan; add in cut eggplant wedges, with a little salt and roast on medium heat until the eggplant is tender.", "Transfer the roasted eggplant from the pan to a bowl.In the same pan add\u00a0in\u00a0a teaspoon of oil.", "Once the oil is heated up; add in the mustard seeds and curry leaves.", "Allow it to crackle.", "Next stir in the chopped onions, dry red\u00a0chillies\u00a0and saut\u00e9 until the onions are soft and tender.Add\u00a0in\u00a0the turmeric powder, salt, coriander powder, garam masala powder and very little of the coconut milk and saut\u00e9 until all the ingredients\u00a0are come together.At this stage add in the cooked chickpeas and tomatoes and simmer for about 10 minutes.", "Finally\u00a0stir in the coconut milk and the roasted eggplant and simmer for another 5 minutes until you see a rich color come through the chickpeas.Turn off the heat and serve Roasted Eggplant And Chickpea Curry Flavored With Curry Leaves And Mustard Seeds\u00a0with hot steamed rice or Indian Breads."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Archana_Doshi/roasted-eggplant-and-chickpea-curry-flavored-with-curry-leaves-and-mustard-seeds.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/51.roasted-eggplant-and-chickpea-curry-flavored-with-curry-leaves-and-mustard-seeds.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Bhindi Recipe Flavored With Mustard And Poppy Seeds', 'aloo-bhindi-recipe-flavored-with-mustard-and-poppy-seeds', 'The Aloo Bhindi recipe is a twist to the original where it is flavored with mustard and poppy seeds. Completely inspired from the Bengali Cuisine, this spicy and intence Aloo Bhindi sabzi is a must try and can be served along with kadhi or along with a Bengali dal and puri.', '["300 grams Bhindi (Lady Finger/Okra) , cut into 1 inch pieces", "3 Potatoes (Aloo) , cut into 1 inch wedges", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "Salt , to taste", "Mustard oil , for cooking", "To Be Ground To Paste", "1 teaspoons Poppy seeds", "1 teaspoon Mustard seeds (Rai/ Kadugu)"]'::jsonb, ARRAY['salt', 'mustard oil', 'mustard seeds', 'red chilli powder', 'poppy seeds', 'bhindi (lady fingerokra)', 'potato (aloo)', 'turmeric powder']::text[], '["To begin making the\u00a0Aloo Bhindi Recipe first prep all the vegetables and keep aside.Make a powder of the mustard and poppy seeds and keep aside.We will roast the aloo and bhindi separately and then finally mix it all together.Heat a teaspoon of oil in a Heavy Bottomed Pan, add the potatoes, sprinkle some salt and stir fry on medium heat until the potatoes are half way cooked.", "Keep the pan covered in the cooking process so the steam helps it cook faster.", "Once the potatoes/ aloo are half way cooked, stir in the turmeric powder and chili powder and saute for a few minutes.", "Cook the potatoes until completely done.", "Once done, transfer to a bowl and keep aside.In the same pan, heat another teaspoon of oil.", "Add the bhini, sprinkle salt and cook until soft and tender.", "Cover and keep the lid of the pan slightly ajar.", "Keeping the lid slightly ajar helps the steam circulate in the pan, plus prevents the bhindi from getting sticky.Once the bhindi is cooked, add the poppy and mustard seed powder, the roasted potatoes and any more salt to taste.", "Stir fry the Aloo Bhindi sabzi for another 4 to 5 minutes until all the flavors are incorporated.Once done, turn off the heat and keep aside.Serve the Aloo Bhindi Recipe along with Cholar Dal Recipe (Bengali Style Chana Dal) and Bengali Luchi Recipe  for a cozy sunday lunch."]'::jsonb, 60, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/1-Archana/Bengali_Style_Aloo_Bhindi_Spiced_with_Mustard_and_Poppy_Seeds_Recipe-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/52.Bengali_Style_Aloo_Bhindi_Spiced_with_Mustard_and_Poppy_Seeds_Recipe-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gutti Vankaya Recipe - Andhra Style Stuffed Brinjal', 'gutti-vankaya-recipe-andhra-style-stuffed-brinjal', 'This Gutti Vankaya Recipe is an Andhra and Telangana speciality of making stuffed eggplant. Eggplant or brinjals are cooked with a spicy peanut based stuffing and gravy base.', '["8-10 Brinjal (Baingan / Eggplant)", "1 Tamarind Paste , big lemon size", "1 cup Onions , sliced thin+ 1/2 cup, chopped finely", "Ingredients to Roast & Grind", "4-5 Fresh Red Chilli , dry, roast and ground", "4 tablespoons Raw Peanuts (Moongphali)", "2 tablespoons Sesame seeds (Til seeds)", "3 tablespoons Fresh coconut , or dessicated coconut", "1 1/2 tablespoons Coriander (Dhania) Seeds", "1 teaspoon Cumin seeds (Jeera)", "2 Cardamom (Elaichi) Pods/Seeds", "6 Garlic", "1 tablespoon Chana dal (Bengal Gram Dal)", "Ingredients for Tadka", "Oil , as required", "2 Bay leaf (tej patta)", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves"]'::jsonb, ARRAY['chana dal (bengal gram dal)', 'cardamom (elaichi) podsseeds', 'brinjal (baingan eggsplant)', 'tamarind paste lemon', 'bay leaf (tej patta)', 'onion thin+', 'curry leaves', 'coriander (dhania) seeds', 'garlic', 'cocunut', 'peanuts (moongphali)', 'cumin seeds (jeera)', 'red chilli dry', 'sesame seeds (til seeds)', 'sunflower oil']::text[], '["To prepare Gutti Vankaya Recipe (Andhra Style Stuffed Brinjal), get small brinjals since the smaller ones will be easy to have with phulkas or Rotis.", "Slit them twice diagonally 3/4 th long such that you do not disturb their stalk/ crown.", "You should have perfectly slit brinjals ready for filling from all 4 sides when you do this.On a medium flame in a deep pan, bring tamarind extract and salt in sufficient water to boil.", "Switch off flame and drop the brinjals in and close the lid.", "Let it sit for 10 minutes.Meanwhile, on a pan with little oil, shallow fry onions till soft.", "Wet grind with a little tamarind-salt water that is used to half boil the brinjals and keep aside.Take a kadai to dry roast all the ingredients mentioned under roast and grind over medium flame.", "Take off the kadai when aromatic and let it cool a bit.", "Use a mixer grinder to make semi fine powder.", "Mix haldi/ turmeric and salt as required to this powder.Mix this powder with wet grinded sauteed onions.", "Add a small amount of tamarind- salt water to make very thick gravy and fill inside the brinjals.", "Keep aside.Prepare tadka with oil.", "Add in jeera, bay leaves, curry leaves.", "When they splutter, add stuffed brinjals and fry for 2-3 minutes.Mix remaining gravy and more of water/ mix of tamarind and salt water and add to kadai.", "Bring it to boil over low flame.", "Saut\u00e9 carefully such that the gravy doesn\u2019t come out of the brinjals.", "Switch off the flame when gravy thickens and brinjals appear cooked.Serve Gutti Vankaya with either hot rice, biryanis, chapatis, phulkas or akki rotti to make it a main course meal."]'::jsonb, 55, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/uma_ganguly/gutti_vankaya_stuffed_eggplant_recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/53.gutti_vankaya_stuffed_eggplant_recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rajasthani Style Sukhe Gatte Capsicum Ki Sabzi Recipe', 'rajasthani-style-sukhe-gatte-capsicum-ki-sabzi-recipe', 'Rajasthani Style Sukhe Gatte Capsicum Ki Sabzi Recipe is a popular dish that is famous in Rajasthan. Gatte are cylindrical or oval shaped mixture that are made from besan flour and is spiced up with chilli powder, coriander and cumin. They are used in various form in many of the Rajasthan dishes. In this recipe we have sautéed it along with capsicum with no onion and no garlic option. The masala added to the sabzi are simple and provides a wonderful taste.', '["Ingredients for the gatte (gram flour dumplings)", "1 cup Gram flour (besan)", "1/2 teaspoon Ajwain (Carom seeds)", "1/4 teaspoon Red Chilli powder", "2 tablespoons Curd (Dahi / Yogurt)", "1 tablespoon Oil", "Salt , to taste", "Ingredients for the Sabzi", "1 Green Bell Pepper (Capsicum) , cut into cubes", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Red Chilli powder", "2 teaspoon Garam masala powder", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "4 sprig Coriander (Dhania) Leaves , chopped", "Oil"]'::jsonb, ARRAY['ingredients for the gatte', 'gram flour dumplings', 'gram flour', 'besan', 'ajwain', 'carom seeds', 'red chilli powder', 's curd', 'dahi / yogurt', 'oil', 'salt', 'ingredients for the sabzi', 'reen bell pepper', 'capsicum', 'cumin seeds', 'jeera', 'asafoetida', 'hing', 'turmeric powder', 'haldi', 'garam masala powder', 'amchur', 'dry mango powder', 'coriander powder', 'dhania', 'coriander']::text[], '["To begin making the Sukhe Gatte Capsicum Ki Sabzi Recipe we will first make the gatte.In a large mixing bowl, combine all the ingredients for the gatta.", "Add a few teaspoons of water at a time and knead to make a firm dough.Knead well for about 5 minutes to make a very soft melt in the mouth gatta.", "If you add more water and it does not shape into a dough, then you will have to add more gram flour and knead it well.Roll the dough into a long cylinder and cut them into 1 inch discs.", "The next step is to cook the gattas in boiling water.In a large saucepan boil water.", "Once the water comes to a brisk boil, add the gattas into the water and boil until they comes floating to the top.", "Once they come floating to the top, boil for another 3 to 4 minutes.", "Drain the gattas and keep it aside.To make the Sabzi, in a sauce pan add oil, add cumin seeds and asafoetida, allow the cumin seeds to crackle for few seconds.Once that is done, you can add chopped bell peppers (Capsicum) and saute until the capsicum become slightly soft.Turn the heat to low, add red chili powder, turmeric powder, garam masala, coriander powder, amchoor and salt.Add the cooked gattas at this stage, mix well to combine and sprinkle some water and cook until the raw smell of spice goes away.Saute for another 10 minutes and switch off the heat and garnish with coriander leaves and serve hot.Serve the Sukhe Gatte Capsicum Ki Sabzi Recipe along with\u00a0Kadhi Pakoras\u00a0,\u00a0Mooli Paratha\u00a0and\u00a0Kadai Paneer Recipe\u00a0to make it a rich meal for your Sunday lunch."]'::jsonb, 40, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Rajasthani_Style_Sukhe_Gatte_Capsicum_Ki_Sabzi_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/54.Rajasthani_Style_Sukhe_Gatte_Capsicum_Ki_Sabzi_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Palak Tovve Recipe - South Indian Dal Palak With Coconut', 'palak-tovve-recipe-south-indian-dal-palak-with-coconut', 'Palak Dal is a tasty and nutritious Karnataka style curry, also known as Palak Tovve, is quick to make and tastes delicious. Palak Dal is a nutritious combination of spinach and lentils, together they create one wholesome curry. Serve it with rotis for a simple weeknight dinner or traditional delicacies like majjige huli on the special festive occasions.', '["Spinach Leaves (Palak) , 2 bunches, washed and chopped", "2 cups Arhar dal (Split Toor Dal)", "1 cup Fresh coconut , grated", "5 Green Chillies", "Coriander (Dhania) Leaves", "Salt , to taste", "Ingredients for the seasoning", "1 tablespoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "5 Curry leaves"]'::jsonb, ARRAY['spinach leaves', 'palak', 's arhar dal', 'split toor dal', 'fresh coconut', 'reen chillies', 'coriander', 'dhania', 'salt', 'ingredients for the seasoning', 'ghee', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'asafoetida', 'hing', 'curry leaves']::text[], '["To start making Palak Dal, start by cooking the toor dal with 3 cups of water and turmeric powder until it becomes very soft.", "See how to cook lentils (Dals/Pulses)Next, steam or blanch the chopped spinach.", "Keep it aside until required.", "See how to steam vegetablesNow, grind the grated coconut, coriander leaves, green chillies, salt with just enough water in a mixer to blend into a smooth paste.", "Transfer the paste to a bowl and keep aside.In a saucepan pour in the cooked dal and mash it well until it becomes a smooth paste like.", "You can use a potato masher, a wooden whisk or a hand blender to do this.", "Stir in the cooked spinach and the coconut paste into the dal.", "Stir to combine.", "Adjust the consistency of the curry by adding a little water.For the seasoning, heat ghee in a small pan over medium heat, add the mustard seeds, cumin seeds and allow them to crackle.", "Now add curry leaves, asafoetida, and fry for a minute or so.", "Turn off the heat.Pour this seasoning over the Palak Dal.", "Simmer the dal over medium heat for few minutes.", "Turn off the heat.Palak\u00a0Tovve\u00a0or Palak Dal is now ready.", "Serve hot with Stuffed Aubergines."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Dal_Palak_Recipe_Healthy_Spinach_Lentil_Curry-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/55.Dal_Palak_Recipe_Healthy_Spinach_Lentil_Curry-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Assamese Style Walking Catfish In Curry Leaf Gravy Recipe', 'assamese-style-walking-catfish-in-curry-leaf-gravy-recipe', 'Assamese Style Walking Catfish In Curry Leaf Gravy Recipe is a recipe prepared from Walking Catfish (Clarias batrachus) (or Magur mach in Assamese) is known for its nutritional and medicinal value. This recipe is traditionally cooked with juice extracted from curry leaves that also makes it good for people suffering with weakness due to ill health generally, and people suffering from anemia. It can be given to kids for good health. Though is a bland, soup type curry but it tastes great because of the unique flavour of curry leaves.', '["5 Walking Catfish , thoroughly cleaned", "4 cloves Garlic , crushed", "2 Green Chillies , slit", "1/4 teaspoon Turmeric powder (Haldi)", "Mustard oil , to cook", "Salt , to taste", "1/2 teaspoon Black pepper powder", "2 cups Curry leaves", "1 cup Hot water"]'::jsonb, ARRAY['salt', 'mustard oil', 'walking catfish tho', 'cloves garlic', 'water', 'curry leaves', 'black pepper powder', 'turmeric powder', 'green chillies']::text[], '["To begin making Assamese Style Walking Catfish In Curry Leaf Gravy Recipe, prep all the ingredients.", "Grind the fresh and young curry leaves and extract the juice and pass through a strainer and keep aside.Heat the mustard oil is a karahi/kadai and add the crushed garlic cloves when the oil is hot enough.Add in the fresh chillies, saute for a few seconds, add turmeric powder and salt.Add the fishes and cook for about 5 minutes or till partially cooked.Add the hot water and bring to a boil and cover it.", "Cook further on medium heat for about 7 minutes or till the fish is completely cookedAdd the black pepper powder and curry leaf juice and cook for 3 minutes for the curry leaf juice to infuse with the curry in fish in it.", "Switch off once cooked well.Serve Assamese Style Walking Catfish In Curry Leaf Gravy Recipe with Steamed Rice, Assamese Amitar Khar Recipe and end on a sweet note with Narikol Pitha Recipe for an Assamese inspired weekend lunch with family."]'::jsonb, 40, 'Assamese', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/taanishi-yahoo.com/assamese-style-walking-catfish-in-curry-leaf-gravy-recipe2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/56.assamese-style-walking-catfish-in-curry-leaf-gravy-recipe2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Style Patol Bhaji Recipe- Green peas Curry Recipe', 'goan-style-patol-bhaji-recipe-green-peas-curry-recipe', 'Goan Style Patol Bhaji Recipe is a popular dish available in most of the tea stalls. The bhaji is usually had with Pav for breakfast.', '["1/2 cup Dried Green Peas (Vatana) , soaked overnight", "2 teaspoon Jaggery", "1 cup Tamarind Water", "Salt , to taste", "Oil", "Ingredients to roast & Grind", "1 Onion , chopped", "3 tablespoon Fresh coconut , grated", "4 Dry Red Chillies", "1-1/2 teaspoon Coriander (Dhania) Seeds", "3 Cloves (Laung)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Fennel seeds (Saunf)", "1 inch Cinnamon Stick (Dalchini)", "1 teaspoon Sichuan peppercorns", "4 cloves Garlic", "1 inch Ginger , chopped", "1/4 teaspoon Nutmeg", "1 Star anise", "1/4 teaspoon Turmeric powder (Haldi)"]'::jsonb, ARRAY['salt', 'dried green peas (vatana)', 'ginger', 'nutmeg', 'tamarind water', 'coconut', 'fennel seeds (saunf)', 'jaggery', 'cloves garlic', 'dry red chillies', 'onion', 'coriander (dhania) seeds', 'cumin seeds (jeera)', 'cinnamon stick (dalchini)', 'turmeric powder', 'cloves (laung)', 'sichuan peppercorns', 'star anise', 'sunflower oil']::text[], '["To begin making the Goan Style Patol Bhaji Recipe, wash and soak the green peas in water overnight.", "Heat a pan with oil on medium flame, add coriander seeds, dry red chilies, cinnamon, peppercorns, cloves, Star anise, fennel seeds and cumin seeds.", "Fry until the aroma is released for about 10 seconds.Add the chopped onions, ginger, garlic and saut\u00e9 until the onion turn translucent.", "Add freshly grated coconut and saut\u00e9 until the mixture turns golden brown.", "Switch off the heat, allow the mixture to cool down.", "Add the saut\u00e9ed mixture in a mixer jar with water to a smooth paste.Heat a pressure cooker, add the freshly ground paste, soaked legumes, turmeric powder, jaggery, tamarind water and salt and mix well.Add about 1/2 cup of water and pressure cook the\u00a0Patol Bhaji for about 3 whistle.", "Allow the pressure to release naturally.", "Open the pressure cooker, transfer to a serving bowl and serve piping hot.", "Serve the Goan Style Patol Bhaji Recipe along with\u00a0sukhi bhaji\u00a0and\u00a0Homemade Whole Wheat Pav Recipe / Ladi Pav\u00a0by the side to enjoy your morning breakfast."]'::jsonb, 90, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Goan_Style_Patol_Bhaji_Recipe_Green_peas_Curry_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/57.Goan_Style_Patol_Bhaji_Recipe_Green_peas_Curry_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mutton Dum Biryani Recipe', 'mutton-dum-biryani-recipe', 'The Mutton Dum Biryani Recipe is a lip smacking biryani that is packed with flavours from the spices, caramelized onions and saffron. It is a hearty dish that is made during festivals like Id and or when there are special occasions in the family. The dum cooking technique which we have used in this recipe, brings in the deep flavours from the mutton masala to get combined with the Basmati Rice.', '["8 Onions , thinly sliced", "1/4 cup Ginger , chopped", "1/4 cup Garlic , cloves", "7 Green Chillies", "1 Bay leaves (tej patta) , torn", "2 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "3 Cloves (Laung)", "2 cups Basmati rice , washed and soaked for 30 minutes", "Salt , to taste", "Ingredients to marinate", "500 grams Mutton , curry cut", "1 cup Hung Curd (Greek Yogurt)", "1 tablespoon Ginger Garlic Paste", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "Salt , to taste", "Other Ingredients", "2 Bay leaves (tej patta)", "2 inch Cinnamon Stick (Dalchini)", "4 Cloves (Laung)", "1 Mace (Javitri)", "4 Dagad phool (/pathar phool/black stone flower)", "1 teaspoon Red Chilli powder", "1/4 teaspoon Garam masala powder", "2 Tomatoes , finely chopped", "1/2 cup Mint Leaves (Pudina) , chopped", "Salt , to taste", "1/2 cup Milk", "Saffron strands , a few", "4 tablespoons Oil", "4 Ghee", "2 cups Whole Wheat Flour , for sealing the vessel"]'::jsonb, ARRAY['tomato', 'basmati rice', 'dagad phool (pathar phoolblack st flower)', 'onion', 'wheat flour sealing the vessel', 'turmeric powder', 'green chillies', 'sunflower oil', 'salt', 'cardamom (elaichi) podsseeds', 'mace (javitri)', 'mint leaves (pudina)', 'garam masala powder', 'garlic cloves', 'red chilli powder', 'mutton curry', 'ginger', 'hung curd (greek yogurt)', 'bay leaves (tej patta)', 'ghee', 'cinnamon stick', 'milk', 'saffron strands', 'ginger garlic paste', 'cinnamon stick (dalchini)', 'cloves (laung)']::text[], '["To begin making the Mutton Dum Biryani Recipe, first we will make a paste of the ginger, garlic and green chillies.Into a mixer grinder add the chopped ginger, garlic cloves and green chillies.", "Blend to make a paste and keep aside.Next step is to\u00a0marinate the mutton for the Mutton Dum Biryani.Wash mutton thoroughly.", "Add the washed mutton into a mixing bowl and add the yogurt, 1 tablespoon of the ginger garlic and chilli paste, red chilli powder, turmeric powder, garam masala and salt to taste.", "Cover and place the\u00a0 mutton in the refrigerator and marinate it for at least 4 hours.Once we are ready, the next step is to caramelize the onions.Into a preheated pan add oil and the sliced onions.", "Saute the onions on low to medium heat until caramelized.", "This process takes time so be patient so as to get the perfect golden brown caramelized onions.If you brown the onions on high heat then the onions will not caramelize evenly.Once done keep 1/2 the portion of the caramelized onions for the biryani masala and 1/2 portion for garnishing the Mutton Dum Biryani.The next step is to cook the rice until it is 3/4th done.", "Into a saucepan add 4 cups of water, the bay leaf, cardamom pods, cinnamon stick, cloves, salt to taste and the washed basmati rice.", "Allow the rice to boil in the water for 3 to 4 minutes.Power cook the rice until 3/4th done.", "Once done drain the water from the rice, add a tablespoon of ghee to the rice and mix gently.", "Cover & keep aside.Next to make the saffron milk; dissolve the saffron strands in warm milk and keep aside.Next is to make the dough to seal the bowl for dum cooking.", "Into a bowl add the wheat flour and add water to make a firm dough.", "Cover and keep aside."]'::jsonb, 90, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Hyderabadi_Mutton_Biryani_Video_Recipe_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/58.Hyderabadi_Mutton_Biryani_Video_Recipe_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Palak Makhana Recipe (Navratri Fasting/Vrat Recipe)', 'palak-makhana-recipe-navratri-fasting-vrat-recipe', 'Palak Makhana is a North Indian gravy made with with roasted makhana blended in a creamy palak gravy. This is a dish that is famous during the festival of Navratri where people fast according to their tradition. Since there are no onion and no garlic added it makes a perfect dish to be eaten while fasting.', '["300 grams Spinach Leaves (Palak)", "2 Tomatoes , diced", "1 cup Phool Makhana (Lotus Seeds)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Garam masala powder", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 Cinnamon Stick (Dalchini)", "2 tablespoon Milk", "1 tablespoon Ghee", "Salt , to taste"]'::jsonb, ARRAY['s spinach leaves', 'palak', 'tomatoes', 'phool makhana', 'lotus seeds', 'cumin seeds', 'jeera', 'garam masala powder', 'red chilli powder', 'turmeric powder', 'haldi', 'cinnamon stick', 'dalchini', 'milk', 'ghee', 'salt']::text[], '["We begin the Palak Makhana by washing the spinach thoroughly under running water.", "Drain the spinach and cook it in a pressure cooker with little bit of turmeric powder, cumin seeds and green chillies for 2 whistle.Once the whistle is done let it cool down till the pressure comes out naturally.", "Blend it into paste and keep it aside.Roast the makhana with ghee on a flat bottomed non-stick pan.", "Remove the makhana and in the same pan add little bit of oil and temper the cumin seeds and add the tomatoes.Cook until they loose all the liquids and add all the spice powders.Add little water and simmer it for 2 minutes.", "Add the blended spinach mixture along with milk and simmer it for 3 minutes again.Finally, add the makhana and bring it to a boil.You can serve your creamy Palak makhana with\u00a0Ajwain puri\u00a0or\u00a0Jeera pulao\u00a0to make a complete wholesome meal."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/sept-19/Paneer_Makhana_Ki_Sabzi_Recipe_Lotus_Seeds_in_Paneer_Masala-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/59.Paneer_Makhana_Ki_Sabzi_Recipe_Lotus_Seeds_in_Paneer_Masala-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Bimbla Uddamethi Recipe', 'goan-bimbla-uddamethi-recipe', 'Bimbla Uddamethi or Bilimbi curry is a vegetarian Goan Curry prepared by cooking sour Bimba fruits in Coconut gravy.', '["5-6 Bimbla (Bilimbi)", "1 Cup Fresh coconut , grated", "1 teaspoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "20 Grams Jaggery , adjust according to your taste", "1 Tablespoon Oil", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon White Urad Dal (Split)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "10-12 Curry leaves", "Asafoetida (hing) , a pinch", "Salt , to taste"]'::jsonb, ARRAY['salt', 'sunflower oil', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'red chilli powder', 'curry leaves', 'white urad dal (split)', 'grams jaggery', 'methi seeds (fenugreek seeds)', 'turmeric powder', 'bimbla (bilimbi)']::text[], '["To begin making Goan Bimbla Uddamethi Recipe, wash Bimbla 3-4 times.", "Cut them into very small cubes.In a heavy bottomed pan, bring a cup of water to a boil and add the chopped Bimbla.", "Let the bimbla sit in the boiling water until they soften.", "Meanwhile, grind grated coconut along with red chili powder and turmeric powder using a spoon of water .Add the coconut paste in the boiled bimbla.", "Add jaggery to the pan as well.Add some water just to thin it out and allow this mixture to boil.While curry is boiling, prepare the tempering.In a pan heat oil on medium heat.", "Add Fenugreek seeds, Urad dal, mustard seeds and Curry leaves.", "Cover and let the seeds crackle on low heat.", "Once the mustard seeds have crackled, add asafoetida and remove from heat.Pour this tempering over the boiling curry.Add salt as per your taste.", "Stir the mixture until everything combines.", "Remove from heat and Bimbla Uddamethi is readyServe Bimbla Uddamethi with Steamed Rice and\u00a0Mixed Vegetables Ajethna Recipe (Mangalorean Style Mixed Vegetables Sabzi) for a complete meal."]'::jsonb, 20, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/GOAN_BIMBLA_UDDAMETHIBILIMBI_CURRY_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/60.GOAN_BIMBLA_UDDAMETHIBILIMBI_CURRY_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sarson Ka Saag Recipe - Classic North Indian Saag Recipe', 'sarson-ka-saag-recipe-classic-north-indian-saag-recipe', 'Sarson Ka Saag Recipe is a very traditional winter recipe from North India made from a mix of greens like mustard leaves, spinach leaves and bathua. The most important greens for this recipe is the sarson, also known as mustard. I sometimes combine it along with spinach and methi as well or sometimes just spinach, based on the availability of the greens.', '["500 grams Mustard greens , washed and roughly chopped", "250 grams Spinach Leaves (Palak) , washed and roughly chopped", "250 grams Bathua leaves , washed and roughly chopped", "1 teaspoon Makki Ka Atta (Yellow Corn Meal Flour)", "2 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "1 Onion , thinly sliced", "3 Green Chillies , slit into half", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "4 tablespoons Ghee"]'::jsonb, ARRAY['green chillies', 'salt', 'ginger', 'bathua leaves', 'makki ka atta (yellow corn meal flour)', 'ghee', 'red chilli powder', 'cloves garlic', 'onion', 'mustard greens', 'coriander powder', 'spinach leaves (palak)', 'garam masala powder']::text[], '["To begin making the Sarson Ka Saag Recipe, we will first steam the leaves together along with a little salt until soft and yet green.", "For this, you can use a steamer or a pressure cooker.Place all the leaves in the pressure cooker, add a little salt and 3 tablespoons of water.", "Cover the pressure cooker and cook until you hear one whistle.", "After the first whistle turn off the heat.Place the cooker under running water and release the pressure immediately and add the Makki ka atta.", "This process of releasing the pressure immediately will help keep the greens green.Allow it to cool.", "You can either puree the saag or use a masher and mish mash the greens to make it soft and mushy.", "The way you like to present it is purely your choice.Heat a teaspoon of ghee in a heavy bottomed pan; add the ginger, garlic, onions and green chillies.", "Saute all the ingredients together on low heat until the onions are completely tender and soft and lightly browned.You can optionally cover the pan partly to create steam to cook the onions.", "This process of cooking consumes less oil.Once the onions are well softened, stir in the steamed sarson ka saag, red chilli powder, garam masala powder and coriander powder.", "Turn the heat to high and give the mixture a quick boil for a couple of minutes, so that the greens get the flavours from the spices and onions.", "Turn off the heat, check the salt and adjust to taste accordingly.", "Transfer the Sarson Ka Saag to a serving bowl and serve hot.Serve the Sarson Ka Saag along with\u00a0Makki Ki Roti\u00a0with a dollop of white butter and jaggery and end it with a\u00a0Masala Chaas."]'::jsonb, 55, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Sarson_Ka_Saag_Recipe_North_Indian_Saag_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/61.Sarson_Ka_Saag_Recipe_North_Indian_Saag_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Vankaya Kothimeera Karam Koora Recipe', 'andhra-style-vankaya-kothimeera-karam-koora-recipe', 'Brinjal cooked in coriander paste tastes heavenly in this Andhra Style Vankaya Kothimeera Karam Koora Recipe. Very easy to make, this curry goes well for a traditional Andhra lunch. T', '["15 Small Brinjal (Baingan / Eggplant)", "1 cup Coriander (Dhania) Leaves , chopped", "3 Green Chillies , chopped", "Salt , to taste", "2 tablespoons Oil"]'::jsonb, ARRAY['small brinjal', 'baingan / eggplant', 'coriander', 'dhania', 'reen chillies', 'salt', 's oil']::text[], '["To begin making Andhra Style Vankaya Kothimeera Karam Koora Recipe, roughly chop coriander and chillies.", "Add very little water, salt and make into a fine paste in mixer grinder.", "Add salt and keep ready.Slit brinjals in such a way that you see an X at the base.", "Be careful not to slit open them completely.", "Immerse them in salt water for 5 minutes.Now, carefully stuff the coriander paste into the brinjals without breaking them.Heat oil in a wide frying pan, put the brinjals side by side.", "Cover the pan and cook covered on low heat until brinjals turn soft.Turn the brinjals gently using a fork and and a spoon.", "Do not use a ladle as it may break the brinjals.If there is any left over coriander paste, add it to the brinjals after they are about 90% cooked and mix well.Serve Andhra Style Vankaya Kothimeera Karam Koora Recipe along with Chapati, Steamed Rice, Dosakaya Pappu Recipe for a simple complete meal."]'::jsonb, 30, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/anu.mallajosyula-gmail.com/Andhra_Style_Vankaya_Kottimeera_Karam_Koora_edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/62.Andhra_Style_Vankaya_Kottimeera_Karam_Koora_edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Broccoli Paratha Recipe', 'broccoli-paratha-recipe', 'Broccoli has many health benefits. It reduces cholesterol, improves heart health and it is a powerful antioxidant. The high fiber content in this vegetable aids in digestion, prevents constipation, maintains low blood sugar, and curbs overeating. Make this paratha and you can pack in your kids lunch box also.', '["500 grams Broccoli", "1 Onion", "1 tablespoon Coriander Powder (Dhania)", "Salt , as per taste", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Oil", "2 cups Whole Wheat Flour", "Salt , to taste", "Water , as required", "Oil , or ghee for frying paratha"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'wheat flour', 'red chilli powder', 'water', 'sunflower oil ghee paratha', 'onion', 'broccoli', 'coriander powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Broccoli Paratha recipe, mix wheat flour, salt and water to form a soft non sticky dough, cover and let it rest for at least 30 minutesCut broccoli into small pieces and put them in hot water for 5 minutes.Remove and pat dry the florets.", "Grate the broccoli florets and keep them aside.", "If you are using a blender, use small jar.", "Add small quantity of florets and pulse grind.", "Don''t grind too much as broccoli loses water.", "In a heavy pan, add oil and fry onions.", "Add grated broccoli and fry for 3 to 4 minutes.", "Broccoli cooks very fast.", "So keep stirring continuously so that it does not stick to the pan.", "After broccoli mixture is dry and is well cooked, add salt, red chilli, coriander powder, jeera powder, garam masala and mix well.", "Cool the mixture completely before making the parathas.In the mean while, knead the wheat dough well, make equal size balls.", "Flaten the dough ball with hand and thin out the edges.", "Make a cup and put the broccoli stuffing in the middle, close the edges.Donot pinch off the excess dough.", "Instead fold it and seal the stuffed dough with it.Dust the ball with flour and roll gently.", "Do not apply much pressure.", "Place the rolled paratha on a hot tawa and cook till brown spots appear.", "Apply oil, cook from both the sides and they are ready to eat.Serve\u00a0Broccoli Paratha along with\u00a0Dhaniya Pudina Chutney\u00a0and\u00a0Boondi Raita\u00a0for your weekday meal."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Affiliate-Articles/Broccoli_Paratha_original.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/63.Broccoli_Paratha_original.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dhania Murgh Makhani Recipe', 'dhania-murgh-makhani-recipe', 'Dhania Murgh Makhani Recipe is a creamy Indian curry that is made with fresh coriander leaves in a thick spicy yogurt curry.  All you need is some freshly bought coriander leaves that is ground with green chilies, ginger and garlic. The recipe can be made in one pot and is that simple and easy to make. The flavors blend really well into the chicken and is a perfect side dish or a main course for your Sunday meal. Sometimes we often use the day old coriander leaves to make of a quick chutney but this recipe helps you create a wonderful meal for your day.', '["300 grams Chicken drumstick , cut into small pieces", "2 Potatoes (Aloo) , skin peeled and cubed", "1 Cardamom (Elaichi) Pods/Seeds", "2 inch Cinnamon Stick (Dalchini)", "1 teaspoon Cumin seeds (Jeera)", "1 Onion , sliced", "1 teaspoon Turmeric powder (Haldi)", "1 Lemon juice", "1 tablespoon Garam masala powder", "1 teaspoon Amchur (Dry Mango Powder)", "1 cup Curd (Dahi / Yogurt)", "Salt , to taste", "To grind", "2 Onions , sliced", "1 Tomato , chopped", "1/2 cup Coriander (Dhania) Leaves", "1 inch Ginger , chopped", "4 cloves Garlic", "2 Green Chilli , chopped"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'green chilli', 'amchur (dry mango powder)', 'cardamom (elaichi) podsseeds', 'coriander (dhania) leaves', 'potato (aloo) skin', 'cloves garlic', 'curd', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'onion', 'lemon', 'turmeric powder', 'garam masala powder', 'chicken drumstick']::text[], '["To begin making the Dhania Murgh Makhani Recipe, we will wash the chicken pieces thoroughly and marinate with turmeric powder, salt and lemon juice in a bowl.Heat pan with oil, add sliced onions and saute until it softens, add tomatoes and saute them as well until it is thoroughly mashed.Switch off the heat once done and allow it cool down.", "Grind the saut\u00e9ed onions and tomatoes along with coriander leaves, green chilli, garlic and ginger into a fine paste by adding some water.Heat a pressure cooker with oil, add whole spice like cinnamon and cardamom pods and add a teaspoon of cumin seeds and allow it to crackle for few seconds.Add sliced onions and saute until it softens.", "Add chopped potatoes, chicken, ground masala paste along with all the spice powders.", "Check for salt.Saute for about 5 minutes until the masala is coated well.", "Add curd and give one last stir.", "If the water is not enough for the chicken to cook, add about 1 cup water and pressure cook it for 4 whistle until done.Serve the Dhania Murgh Makhani along with\u00a0garlic naan, steamed rice and a\u00a0vegetarian subzi\u00a0to go along with curry for your Sunday meal."]'::jsonb, 45, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Dhania_Murgh_Makhani_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/64.Dhania_Murgh_Makhani_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Coorg Koli Curry Recipe - Coorgi Chicken Curry', 'coorg-koli-curry-recipe-coorgi-chicken-curry', 'Coorg Koli Curry Recipe is a flavour packed chicken curry from South India. They make their food flavouresoem and spicy, which makes it likeable by all.', '["1/2 kg Chicken", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander (Dhania) Seeds", "1 teaspoon Cumin seeds (Jeera)", "2 inch Cinnamon Stick (Dalchini)", "4 Cloves (Laung)", "1 teaspoon Poppy seeds , roasted", "1 teaspoon Garlic , minced", "1 teaspoon Ginger , minced", "4 Green Chillies", "Salt , to taste", "1 tablespoon Oil", "1 cup Onion , chopped", "1 cup Fresh coconut , grated", "1 teaspoon Tamarind Paste", "Coriander (Dhania) Leaves , for garnish"]'::jsonb, ARRAY['green chillies', 'salt', 'ginger', 'coconut', 'coriander (dhania) leaves', 'red chilli powder', 'coriander (dhania) seeds', 'cinnamon stick (dalchini)', 'chicken', 'cumin seeds (jeera)', 'poppy seeds', 'garlic', 'onion', 'tamarind paste', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making Coorg Koli Curry Recipe, marinate the chicken in red chilli powder and turmeric powder and let it sit in the fridge for 30 minutes minimum.Take a \u00a0mixer jar and add coriander seeds, cumin seeds, cinnamon, cloves ginger, garlic, green chillies and roasted poppy seeds.", "Grind them all together, add some water to it.", "Once done, take a large pan and heat cooking oil on medium flame.", "Once the oil is hot enough, add the chopped onions and fry till golden brown, on a medium heat.Now turn the heat to low, and add the masala paste which you ground earlier into the pan, stir till the raw smell disappears.Now add the chicken pieces into it, and required salt to taste and cook for about 7-8 minutes on low heat.", "Once the chicken looks well coated with spices, then add some water.", "Cover it with a lid and cook the chicken on a low heat for about 15 to 20 minutes or till it gets tender.Once the chicken is cooked, add tamarind extract and cook for 5 more minutes.", "Switch off and serve it hot.Serve\u00a0Coorg Koli Curry Recipe Coorgi Akki Roti or\u00a0Ari Pathiri Recipe\u00a0for a complete comforting meal."]'::jsonb, 60, 'Coorg', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/garimasgautam-gmail.com/Coorg_Koli_Curry_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/65.Coorg_Koli_Curry_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Konkani Style Karate Batate Puddi Sagle Recipe - Bitter Gourd & Potato Curry', 'konkani-style-karate-batate-puddi-sagle-recipe-bitter-gourd-potato-curry', 'Karate Batate Puddi Sagle is a simple and delicious konkani style bitter gourd side dish. Konkani cuisine predominantly uses coconut in its recipes. Bitter gourd is one of the vegetables not preferred by many. However, the freshly prepared spice mix along with grated coconut adds a wonderful flavour to the otherwise boring bitter gourd.', '["300 grams Karela (Bitter Gourd/ Pavakkai) , cut into small cubes", "2 Potatoes (Aloo) , cut into small cubes", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 cup Fresh coconut , grated", "1 tablespoon Coriander (Dhania) Seeds", "2 teaspoon White Urad Dal (Split)", "3 Dry Red Chilli", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Tamarind Water", "Salt , to taste"]'::jsonb, ARRAY['salt', 'tamarind water', 'mustard seeds', 'coconut', 'karela (bitter gourd pavakkai)', 'dry red chilli', 'white urad dal (split)', 'coriander (dhania) seeds', 'methi seeds (fenugreek seeds)', 'potato (aloo)']::text[], '["To begin making\u00a0Karate Batate Puddi Sagle, wash and cut the bitter gourds into small cubes, add a little salt, mix and leave it aside for 10 minutes.", "This will help in reducing the bitterness.Similarly, wash, deskin and cut the potatoes into cubes, put it into a bowl of water and set aside.Heat a heavy bottomed pan and dry roast the urad dal, red chillies, coriander seeds and fenugreek seeds till it turns aromatic.Now, grind the dry roasted spices along with the grated coconut and tamarind extract to a course mix using a hand blender.Heat oil in the same pan on medium flame, add the mustard seeds and let it splutter.Squeeze the water out of the bitter gourd and add it to the pan.", "Also add the potatoes and saute on medium heat until its done.", "This will take around 10 minutes.Add the ground spice mix to the pan, season with salt and mix well.", "Simmer for 5 minutes and switch off the flame.Serve the\u00a0Karate Batate Puddi Sagle\u00a0along with\u00a0Steamed Rice\u00a0and\u00a0Kollu Rasam Recipe (Nourishing HorseGram Stew)\u00a0with a cup of curd for a weeknight dinner."]'::jsonb, 40, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/13-_april/Konkani_style_bitter_gourd_and_potato_subzi_recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/66.Konkani_style_bitter_gourd_and_potato_subzi_recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kathirikai Pitlai Recipe - South Indian Tangy & Spicy Brinjal Curry', 'kathirikai-pitlai-recipe-south-indian-tangy-spicy-brinjal-curry', 'Kathirikai Pitlai Recipe is a traditional South Indian made with eggplant/brinjal. The the pitlai curry is made with freshly roasted and ground condiments and made tangy with tamarind. The toor dal adds to the protein, making this dish wholesome and nutritious.', '["6 Small Brinjal (Baingan / Eggplant)", "1/2 cup Arhar dal (Split Toor Dal)", "1 tablespoon Tamarind Water", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "5 Curry leaves , finely chopped", "Salt , to taste", "1 teaspoon Sesame (Gingelly) Oil", "Ingredients for Pitlai Podi", "2 tablespoons Chana dal (Bengal Gram Dal)", "1 tablespoon White Urad Dal (Split)", "3 tablespoons Coriander (Dhania) Seeds", "1 teaspoon Whole Black Peppercorns , 1 teaspoon whole black pepper", "3 Dry Red Chillies , (adjust)", "Fresh coconut , grated", "1/2 teaspoon Asafoetida (hing)"]'::jsonb, ARRAY['small brinjal', 'baingan / eggplant', 'arhar dal', 'split toor dal', 'tamarind water', 'turmeric powder', 'haldi', 'mustard seeds', 'rai/ kadugu', 'curry leaves', 'salt', 'sesame', 'gingelly', 'ingredients for pitlai podi', 's chana dal', 'bengal gram dal', 'white urad dal', 'split', 's coriander', 'dhania', 'whole black peppercorns', 'dry red chillies', 'fresh coconut', 'asafoetida', 'hing']::text[], '["To begin making the\u00a0Kathirikai Pitlai Recipe, the first step is to make the Pitlai Podi.To begin making the pitali podi, we will first have to dry roast all the ingredients in the same order of ingredients given.", "The ingredients have to be roasted until they are well browned, but not burnt.Allow the mixture to cool a bit and then grind into a powder, in a mixer grinder.Note: The powder will have a coarse texture, and not a fine powder."]'::jsonb, 60, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Kathirikai_Pitlai_South_Indian_Puli_Sambar_with_Brinjal_Recipe-7.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/67.Kathirikai_Pitlai_South_Indian_Puli_Sambar_with_Brinjal_Recipe-7.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chana Dal Pulao Recipe', 'chana-dal-pulao-recipe', 'Chana Dal Pulao is a traditional Punjabi Cuisine recipe specially prepared on festive occasions like Lohri and Dusshera.', '["1 cup Basmati rice", "1/2 cup Chana dal (Bengal Gram Dal)", "3 Onions , thinly sliced", "2 Tomatoes , finely chopped", "2 Dry Red Chillies", "2 Green Chillies , finely chopped", "1/2 teaspoon Garam masala powder , (or pulao masala)", "1 teaspoon Turmeric powder (Haldi)", "2 teaspoon Lemon juice", "1 teaspoon Cumin seeds (Jeera)", "1 tablespoon Oil", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'basmati rice', 'green chillies', 'garam masala powder (or pulao masala)', 'salt', 'dry red chillies', 'onion', 'lemon', 'cumin seeds (jeera)', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making the Chana Dal Pulao, first wash and soak rice for 30 minutes or so before cooking.", "Similarly clean, wash and soak bengal gram in water for at least\u00a01 hour.Next heat oil in pressure cooker over medium heat.", "Add cumin seeds and saute for few seconds till they turn brown in color.Add the dry red chilies, green chilies and saute for a minute or so.", "Add the sliced onions and saute till they turn golden brown in color.Once the onion is sauteed, add the chopped tomatoes, saute till tomato turn soft and mushy.", "Add salt, turmeric powder and biryani pulao masala, saute once again for few seconds.Now drain the soaked rice and Bengal gram dal.", "Add the rice and lentil in the pressure cooker along with 2 cups of water.Stir to combine.", "Close the lid of the pressure cooker, put the weight on and let pulao cook over medium heat for one or two whistle.Turn off the heat and let the steam escape naturally from the pressure cooker.", "Open the lid of the pressure cooker, add the lemon juice and combine with a spoon.", "Serve\u00a0Chana Dal Pulao Recipe\u00a0along with\u00a0Tomato Onion Raita\u00a0and\u00a0Satvik Carrot Sprout Salad\u00a0for the wholesome lunch."]'::jsonb, 65, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Monika_Manchanda/Chana_Dal_Pulao_Biryani_Recipe_Indian_Rice_Dinner_Lunch-10_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/68.Chana_Dal_Pulao_Biryani_Recipe_Indian_Rice_Dinner_Lunch-10_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Patta Gobi Sabzi Recipe - Cabbage Tomato Sabzi', 'patta-gobi-sabzi-recipe-cabbage-tomato-sabzi', 'The Patta Gobi ki Sabji Recipe is a super quick made from fresh sliced cabbage and sauteed along with tomatoes and subtle flavours from the green chillies and coriander powder. It is cooked all in a single pot making it super simple and easy to make in less than 15 minutes.', '["300 grams Cabbage (Patta Gobi/ Muttaikose) , thinly sliced or diced", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Cumin seeds (Jeera)", "2 Green Chillies , slit", "2 Tomatoes , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder , to taste", "Salt , to taste", "1/2 teaspoon Oil", "4 sprig Coriander (Dhania) Leaves , chopped for garnishing"]'::jsonb, ARRAY['tomato', 'salt', 'mustard seeds', 'cabbage (patta gobi muttaikose)or', 'red chilli powder', 'coriander (dhania) leaves', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Patta Gobi Sabzi Recipe prepare all the ingredients and keep them ready.Heat oil in the pressure cooker; add in the mustard seeds and cumin seeds and allow them to crackle.", "Once they crackle, add in green chillies, the tomatoes and saute the tomato until slightly softened.Once the tomatoes are slightly softened, add in the turmeric powder, salt, coriander powder, red chilli powder and give it a stir.", "Stir in the cabbage and add a tablespoon of water into the cooker.Cover the pressure cooker cook for 3 to 4 whistles and turn off the heat.Release the pressure immediately by running it under cold water or releasing it with a fork placed under the whistle.", "Once the pressure is released, stir in the chopped coriander leaves, check the salt, the spice levels and the\u00a0Patta Gobi Sabzi is ready to be served.If you are using a saucepan method to cook, then keep the pan covered and cook until the\u00a0Patta Gobi Sabzi is soft and you have the texture that you desire.Serve the Patta Gobi Sabzi along with\u00a0Thepla\u00a0and\u00a0Gujarati Dal\u00a0to make a wholesome meal."]'::jsonb, 25, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Patta_Gobhi_Sabzi_Recipe_Cabbage_Tomato_Sabzi_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/69.Patta_Gobhi_Sabzi_Recipe_Cabbage_Tomato_Sabzi_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Poosanikai Rasavangi Recipe - Ash Gourd Curry With Dal', 'poosanikai-rasavangi-recipe-ash-gourd-curry-with-dal', 'Poosanikai Or Ash gourd Rasavangi is an authentic recipe from tamilnadu. In a Rasavangi, Ash Gourd is cooked with moong dal, chana dal , tamarind and fresh ground spices.', '["1 1/2 cups Vellai Poosanikai (Ash gourd/White Pumpkin) , diced into cubes", "1/4 cup Yellow Moong Dal (Split)", "2 tablespoons Chana dal (Bengal Gram Dal)", "20 grams Tamarind , lemon sized", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "2 teaspoon Oil", "Salt , as per your taste", "1/2 tablespoon White Urad Dal (Split)", "1/2 tablespoon Chana dal (Bengal Gram Dal)", "1 1/2 tablespoon Coriander (Dhania) Seeds", "5 Dry Red Chillies", "1/4 cup Fresh coconut , grated"]'::jsonb, ARRAY['s vellai poosanikai', 'ash gourd/white pumpkin', 'yellow moong dal', 'split', 's chana dal', 'bengal gram dal', 's tamarind', 'turmeric powder', 'haldi', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'curry leaves', 'oil', 'salt', 'chana dal', 'coriander', 'dhania', 'dry red chillies', 'fresh coconut']::text[], '["To begin making Poosanikai / Ash Gourd Rasavangi recipe, make sure to soak tamarind in some hot water.", "After 15 minutes, extract pulp from the soaked tamarind - keep aside.", "In a pressure cooker, add rinsed chana dal, moong dal, chopped ash gourd pieces, tamarind extract, salt, turmeric powder and water.", "You can add 2 cups of water or enough water to make sure that all ingredients are submerged in the water.", "Pressure cook it for 3 whistles and release the pressure naturally.", "In a pan, add 1 teaspoon of oil and allow it to warmOnce the oil is warm, add chana dal, urad dal, dry red chillies, coriander seeds and roast until the spices turn aromatic and brownFinally add the grated coconut and roast until golden brown.", "Turn off the flame and allow it to cool.", "Once the coconut and spices have cool, grind them into a fine powder in a mixer.", "Once the pressure cooker has release the pressure, open the lid and give it a good stir.Add the ground spices & coconut to cooked ash gourd and dal mixture - Stir well.In a tadka pan, heat 1 teaspoon of oil.", "Once the oil is hot, add mustard seeds and allow it to sputter.", "When mustard seeds crackles, add urad dal and curry leaves.", "Saute it until urad dal turns golden brown.Finally pour this tempering over the Ash Gourd Rasavangi and it is ready to be served.Serve Poosanikai Rasavangi along with Steamed Rice, Carrot and Beans Poriyal and Elai Vadam for a complete South Indian Style lunch."]'::jsonb, 40, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/aishchitra-gmail.com/Poosanikai_rasavangi__Ash_gourd_rasavangi_Ash_gourd_curry_with_dal_and_ground_spices.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/70.Poosanikai_rasavangi__Ash_gourd_rasavangi_Ash_gourd_curry_with_dal_and_ground_spices.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Raw Mango Puliyogare Gojju Recipe With Peanuts', 'raw-mango-puliyogare-gojju-recipe-with-peanuts', 'Puliyogare Gojju is a famous recipe from the southern india. Traditionally, tamarind is used to add to the tartness. However, with the summer fruit Raw Mango found in abundance at the moment, we have prepared the same using it.', '["1 Mango (Raw) , paste", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 teaspoon Chana dal (Bengal Gram Dal)", "2 sprig Curry leaves", "2 tablespoons Raw Peanuts (Moongphali)", "1 tablespoon Jaggery", "1/4 teaspoon Asafoetida (hing)", "2 tablespoons Oil", "Ingredients for the masala", "2 tablespoons Black sesame seeds", "8 Dry Red Chillies", "2 tablespoons Coriander (Dhania) Seeds", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "2 teaspoons Cumin seeds (Jeera)", "1 teaspoon Whole Black Peppercorns"]'::jsonb, ARRAY['mustard seeds', 'asafoetida (hing)', 'black sesame seeds', 'jaggery', 'black peppercorns', 'curry leaves', 'mango paste', 'white urad dal (split)', 'dry red chillies', 'coriander (dhania) seeds', 'peanuts (moongphali)', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making Raw Mango Puliyogare Gojju Recipe, wash and peel the raw mango.", "Chop it into small cubes and make a fine paste using a mixer grinder.", "Keep aside.Heat a pan and dry roast the -\u00a0black sesame seeds,\u00a0dry red chillies,\u00a0coriander seeds,\u00a0mustard seeds,\u00a0fenugreek seeds,\u00a0cumin seeds, and whole black pepper corns\u00a0one by one, make a fine powder when cooled using a blender and keep aside.Now, heat a teaspoon of oil in the same pan, add the ground raw mango paste and cook for 5 minutes until the raw smell goes away.Add the ground masala gojju masala mix, 1/2 cup water, season with salt and mix well.Let the mixture simmer for 10 minutes till it leaves the ends of the pan.If, the mixture is too thick, you can add water at this stage and let the\u00a0Raw Mango Puliyogare Gojju simmer till it becomes a thick paste.In a small tadka pan, heat oil, add the mustard, urad dal and chana dal and let it crackle.Add the asafoetida, peanuts and fry for a few minutes.", "Add the curry leaves and let it splutter.Add this tadka to the bubbling Raw Mango Puliyogare Gojju.", "Add the jaggery powder, mix well, simmer for another 5 minutes and switch off the flame.Serve the Raw Mango Puliyogare Gojju Recipe, mixed along with\u00a0Steamed Rice\u00a0and\u00a0Elai Vadam\u00a0for a light yet yummy weekday lunch."]'::jsonb, 35, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Raw_Mango_Puliogare_Gojju_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/71.Raw_Mango_Puliogare_Gojju_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Nadan Tomato Curry Recipe (Kerala Style Tomato Curry)', 'nadan-tomato-curry-recipe-kerala-style-tomato-curry', 'Kerala, the land of spices, is known for it''s lip smacking coastal malabari cuisines, World famous onam sadya and many more delicious dishes. Nadan Tomato Curry is a flavourful, simple and delicious side dish from Kerala Cuisine. Fresh and juicy tomatoes are cooked along with green chillies in a coconut cumin paste. The tempering of coconut oil and mustard adds to the flavour of this dish. This dish can be made within ten minutes and can be served along with rice, appams or dosas. A must try!', '["5 Tomatoes , finely chopped", "2 Green Chillies , chopped", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "Salt , to taste", "1 teaspoon Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1/4 cup Fresh coconut , chopped", "1 teaspoon Cumin seeds (Jeera)", "5 Pearl onions (Sambar Onions) , halved"]'::jsonb, ARRAY['tomato', 'salt', 'mustard seeds', 'coconut', 'red chilli powder', 'curry leaves', 'pearl onion (sambar onion)', 'coconut oil', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies']::text[], '["To begin making the Nadan Tomato Curry recipe, heat a pan with oil and temper with mustard seeds and curry leaves.Add the green chillies, tomatoes, turmeric powder, chilli powder and salt.Let the tomatoes cook over low flame, till they become soft and mushy.While the tomatoes cook, grind the ingredients given under ''ground mixture'' along with 1/2 cup water .Once the tomatoes are soft, add the ground mixture and cook over low flame for another 3 to 4 minutes and switch off.Serve Nadan Tomato Curry along with Steamed Rice for light dinner or\u00a0Mangalorean Neer Dosa\u00a0for breakfast."]'::jsonb, 30, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/umar/Nadan_Tomato_Curry__Kerala_Style_Tomato_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/72.Nadan_Tomato_Curry__Kerala_Style_Tomato_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Raw Mango Puliyogare Gojju Recipe With Peanuts', 'raw-mango-puliyogare-gojju-recipe-with-peanuts-2', 'Puliyogare Gojju is a famous recipe from the southern india. Traditionally, tamarind is used to add to the tartness. However, with the summer fruit Raw Mango found in abundance at the moment, we have prepared the same using it.', '["1 Mango (Raw) , paste", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 teaspoon Chana dal (Bengal Gram Dal)", "2 sprig Curry leaves", "2 tablespoons Raw Peanuts (Moongphali)", "1 tablespoon Jaggery", "1/4 teaspoon Asafoetida (hing)", "2 tablespoons Oil", "Ingredients for the masala", "2 tablespoons Black sesame seeds", "8 Dry Red Chillies", "2 tablespoons Coriander (Dhania) Seeds", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "2 teaspoons Cumin seeds (Jeera)", "1 teaspoon Whole Black Peppercorns"]'::jsonb, ARRAY['mustard seeds', 'asafoetida (hing)', 'black sesame seeds', 'jaggery', 'black peppercorns', 'curry leaves', 'mango paste', 'white urad dal (split)', 'dry red chillies', 'coriander (dhania) seeds', 'peanuts (moongphali)', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making Raw Mango Puliyogare Gojju Recipe, wash and peel the raw mango.", "Chop it into small cubes and make a fine paste using a mixer grinder.", "Keep aside.Heat a pan and dry roast the -\u00a0black sesame seeds,\u00a0dry red chillies,\u00a0coriander seeds,\u00a0mustard seeds,\u00a0fenugreek seeds,\u00a0cumin seeds, and whole black pepper corns\u00a0one by one, make a fine powder when cooled using a blender and keep aside.Now, heat a teaspoon of oil in the same pan, add the ground raw mango paste and cook for 5 minutes until the raw smell goes away.Add the ground masala gojju masala mix, 1/2 cup water, season with salt and mix well.Let the mixture simmer for 10 minutes till it leaves the ends of the pan.If, the mixture is too thick, you can add water at this stage and let the\u00a0Raw Mango Puliyogare Gojju simmer till it becomes a thick paste.In a small tadka pan, heat oil, add the mustard, urad dal and chana dal and let it crackle.Add the asafoetida, peanuts and fry for a few minutes.", "Add the curry leaves and let it splutter.Add this tadka to the bubbling Raw Mango Puliyogare Gojju.", "Add the jaggery powder, mix well, simmer for another 5 minutes and switch off the flame.Serve the Raw Mango Puliyogare Gojju Recipe, mixed along with\u00a0Steamed Rice\u00a0and\u00a0Elai Vadam\u00a0for a light yet yummy weekday lunch."]'::jsonb, 35, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Raw_Mango_Puliogare_Gojju_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/73.Raw_Mango_Puliogare_Gojju_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Nadan Tomato Curry Recipe (Kerala Style Tomato Curry)', 'nadan-tomato-curry-recipe-kerala-style-tomato-curry-2', 'Kerala, the land of spices, is known for it''s lip smacking coastal malabari cuisines, World famous onam sadya and many more delicious dishes. Nadan Tomato Curry is a flavourful, simple and delicious side dish from Kerala Cuisine. Fresh and juicy tomatoes are cooked along with green chillies in a coconut cumin paste. The tempering of coconut oil and mustard adds to the flavour of this dish. This dish can be made within ten minutes and can be served along with rice, appams or dosas. A must try!', '["5 Tomatoes , finely chopped", "2 Green Chillies , chopped", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "Salt , to taste", "1 teaspoon Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1/4 cup Fresh coconut , chopped", "1 teaspoon Cumin seeds (Jeera)", "5 Pearl onions (Sambar Onions) , halved"]'::jsonb, ARRAY['tomato', 'salt', 'mustard seeds', 'coconut', 'red chilli powder', 'curry leaves', 'pearl onion (sambar onion)', 'coconut oil', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies']::text[], '["To begin making the Nadan Tomato Curry recipe, heat a pan with oil and temper with mustard seeds and curry leaves.Add the green chillies, tomatoes, turmeric powder, chilli powder and salt.Let the tomatoes cook over low flame, till they become soft and mushy.While the tomatoes cook, grind the ingredients given under ''ground mixture'' along with 1/2 cup water .Once the tomatoes are soft, add the ground mixture and cook over low flame for another 3 to 4 minutes and switch off.Serve Nadan Tomato Curry along with Steamed Rice for light dinner or\u00a0Mangalorean Neer Dosa\u00a0for breakfast."]'::jsonb, 30, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/umar/Nadan_Tomato_Curry__Kerala_Style_Tomato_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/74.Nadan_Tomato_Curry__Kerala_Style_Tomato_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ridge Gourd Tambli Recipe - Spicy Ridge Gourd in Coconut Curry', 'ridge-gourd-tambli-recipe-spicy-ridge-gourd-in-coconut-curry', 'Ridge Gourd Tambli combines the traditional preparation of tambli, a cold curry made with curd (or buttermilk) with ground spices and coconut, with the humble ridge gourd. Many mistake this to be a tasteless, fibrous vegetable, but it has innumerable health benefits. By combining it with a cold curry, best had with hot rice and a dollop of ghee, it makes a comforting and wholesome main component of any South Indian meal. Serve the Ridge Gourd Tambli along with hot steamed rice for lunch or a quick weeknight dinner.', '["1 Ridge Gourd (Turai/ Peerkangai) , peeled and chopped into small pieces (check notes at the end)", "1-1/2 teaspoons Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "4 Green Chillies , slit", "1/2 cup Fresh coconut , grated", "Asafoetida (hing) , a pinch", "1 cup Curd (Dahi / Yogurt) , (preferably a day old and slightly sour)", "Salt , as required", "Water , as needed"]'::jsonb, ARRAY['salt', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'curd (preferably day old sour)', 'water', 'curry leaves', 'green chillies', 'ridge gourd (turai peerkangai) (check notes the end)']::text[], '["To begin making the Ridge Gourd Tambli, first lightly peel the ridge gourd, slice it into discs and chop each disc into 3-4 pieces.", "Set this aside.In a wide pan, warm a teaspoon of ghee.", "Add in the mustard seeds and curry leaves to it and allow them to sputter.Next, add in the chopped ridge gourd, and toss the pieces around on a low heat, until they are slightly softened.", "Sprinkle a little salt to taste and cook further.", "This will make the ridge gourd release a little water.", "Cover and cook on a low flame for 3-4 minutes until the ridge gourd is completely cooked.Once cooked through, you should be left with mushy, cooked vegetable.", "Set this aside to cool, while you prepare the coconut curry for the tambli.In a bowl, add the sour yogurt, a dash of water and whisk till smooth and no lumps remain.", "Add the coconut to the smallest mixer jar, and top with 2-3 tablespoons of the whisked yogurt.In a tadka pan, warm a teaspoon of ghee, drop the slit green chillies and asafoetida into it.", "Saute till the chillies are bruised and fragrant.", "Add them over the coconut in the mixie.", "Grind the whole mixture to a smooth paste, adding little water if required.Add the ground coconut mixture to the whisked curd and mix it all together.", "Lastly, add the ground to the cooked ridge gourd, adjust salt if required and stir well.Serve the Ridge Gourd Tambli along with\u00a0hot steamed rice\u00a0for lunch or a quick weeknight dinner."]'::jsonb, 35, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Revati_Upadhya/Ridge_Gourd_Tambli_Recipe_Spicy_Ridge_Gourd_in_Coconut_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/75.Ridge_Gourd_Tambli_Recipe_Spicy_Ridge_Gourd_in_Coconut_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kela Matar ki Sabzi Recipe - Raw Banana Green Peas Stir Fry', 'kela-matar-ki-sabzi-recipe-raw-banana-green-peas-stir-fry', 'Kela Matar Ki Sabzi is a Jain Style no onion, no garlic recipe. It is a simple recipe which is made with boiled raw bananas and stir frying them them with boiled green peas and cumin seeds and dry spice powders of cumin and coriander seeds.', '["2 Raw Banana", "1/2 cup Green peas (Matar) , boiled", "1/2 teaspoon Cumin seeds (Jeera)", "2 Green Chilli , slit", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Amchur (Dry Mango Powder)", "2 teaspoons Lemon", "1 teaspoon Garam masala powder", "1 tablespoon Oil", "2 sprig Coriander (Dhania) Leaves , chopped", "Salt , to taste"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'green chilli', 'amchur (dry mango powder)', 'green peas (matar)', 'coriander (dhania) leaves', 'cumin seeds (jeera)', 'lemon', 'coriander powder', 'turmeric powder', 'banana', 'garam masala powder', 'sunflower oil']::text[], '["To begin making\u00a0Kela Matar ki Sabzi first cut the raw bananas into half and pressure cook the bananas with 1/4 cup of water for 2 to 3 whistles.", "Turn off the heat and allow the pressure to release naturally.", "Once the pressure has released, peel the skin from the raw banana and slice them into roundels.", "Heat oil in a kadai over medium heat.", "Once the oil is hot, add cumin seeds, when they begin to sizzle, add green chilies.Add salt, coriander powder, cumin powder, amchur powder, garam masala powder and turmeric powder and mix well.", "Next add the boiled peas and cooked raw banana slices\u00a0 and mix well.Sprinkle some water, cover and cook the Kela Matar ki Sabzi until all the masalas get well coated - for about 4 to 5 minutes.Check the salt and spices and adjust to taste accordingly.", "Finally add the juice from the lemon and stir in the chopped coriander leaves and serve.Serve this nutritious and tasty and simple to prepare\u00a0Kela Matar ki Sabzi with\u00a0Dal Tadka Recipe Flavored with Lemon and Coriander,\u00a0Phulka Recipe (Roti/Chapati),\u00a0Cauliflower & Cucumber Raita\u00a0and Steamed Rice.A diabetic friendly dish, serve this\u00a0Kela Matar ki Sabzi along with\u00a0Ragi Tawa Paratha,\u00a0Lahsuni Palak Dal Recipe (Spinach & Lentil Curry with Garlic)\u00a0and\u00a0Beetroot Raita Recipe (Cold Beet & Yogurt Soup/Salad)\u00a0for a Diabetic Friendly Meal."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Affiliate-Articles/Kela_Matar_Sabzi_No_Onion_No_Garlic_Vegetable-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/76.Kela_Matar_Sabzi_No_Onion_No_Garlic_Vegetable-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Nepalese Style Dhal Bhat Recipe', 'nepalese-style-dhal-bhat-recipe', 'Nepalese Style Dhal Bhat Recipe a very classical combination of dal and rice that is usually served side by side as lunch meal. It is very similar to the Dal – Chawal that is famous in north India. But the dal that is prepared in Nepal is quite different. They usually add freshly ground Indian spice and is fried for few minutes and later on it is mixed along with cooked moong dal. The flavor of whole spice like, cardamom, cinnamon, and cloves will help in adding a nice warm and soothing aroma to the dal. It is a tradition that the dal bhat is served along with “vegetable tarkari or torkari”  to make it a complete and rich meal.', '["2 cups Yellow Moong Dal (Split)", "1 Onion , chopped", "1/4 teaspoon Turmeric powder (Haldi)", "2 sprig Coriander (Dhania) Leaves , chopped", "Salt , to taste", "Masala to Grind", "1 inch Cinnamon Stick (Dalchini)", "2 Cardamom Powder (Elaichi)", "4 Cloves (Laung)", "2 Dry Red Chillies", "1 teaspoon Whole Black Peppercorns", "1 teaspoon Cumin seeds (Jeera)"]'::jsonb, ARRAY['salt', 'yellow moong dal (split)', 'black peppercorns', 'coriander (dhania) leaves', 'dry red chillies', 'onion', 'cinnamon stick (dalchini)', 'cardamom powder (elaichi)', 'cumin seeds (jeera)', 'turmeric powder', 'cloves (laung)']::text[], '["To begin making the Nepalese Style Dhal Bhat Recipe, we will first boil the dal with water, turmeric powder and salt for about 4 whistles until it is soft and mushy.Next grind all the whole spices (ingredients in masala to grind) in a mixer to a smooth powder, you can also add a little water if the little quantity does not grind well in a mixer.Heat a kadai with oil, add onion that are chopped and saute well till they turn translucent.Add in ground spices and cook for some time.", "Once done add boiled dal and salt keep stirring.You can start mashing the dal and cook in low heat until the raw smell goes away.Serve the Nepalese Style Dhal Bhat Recipe along with\u00a0cauliflower and aloo subzi\u00a0or\u00a0baby corn and carrot subzi\u00a0by the side to make it enriched meal."]'::jsonb, 40, 'Nepalese', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Nepalese_Style_Dhal_Bhat_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/77.Nepalese_Style_Dhal_Bhat_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Radhaballabhi Recipe (Bengali Stuffed Poori With Spiced Urad Dal)', 'radhaballabhi-recipe-bengali-stuffed-poori-with-spiced-urad-dal', 'Radhaballabhi is a famous Bengali Recipe commonly prepared for Breakfast. Radhaballabhi is usually prepared with urad dal and spices for festive occasion like Krishna Janmashtami. It is a slightly sweeter poori in taste than kachoris. When I was searching for some crispy breakfast, I stumbled upon this stuffed puris. Prepare this Radhaballabhi and pair it with Aloo Dum for a fulfilling breakfast.', '["2 cups All Purpose Flour (Maida)", "Water , water", "1/2 cup Black Urad Dal (Whole)", "1-1/2 teaspoon Cumin seeds (Jeera)", "1-1/2 teaspoon Fennel seeds (Saunf)", "2 Kashmiri Red Chilli Powder", "1 teaspoon Garam masala powder", "1 teaspoon Ginger", "1/2 teaspoon Sugar", "1/2 teaspoon Salt", "Oil , for deep frying"]'::jsonb, ARRAY['salt', 'kashmiri red chilli powder', 'ginger', 'fennel seeds (saunf)', 'water', 'sugar', 'cumin seeds (jeera)', 'flour (maida)', 'black urad dal', 'garam masala powder', 'sunflower oil']::text[], '["To prepare Radhaballabhi Recipe, get prep with all the ingredients first.", "Soak clean urad dal for 4 hours.", "Wet grind urad dal in keep aside.In a bowl, add maida and water little by little and knead the flour into the pliable dough.", "Set it aside for poori dough.In a Frying pan, dry roast Kashmiri chili, 1/2 teaspoon of cumin seeds and 1/2 teaspoon of fennel seeds until they turn light brownish and fresh aroma emanates from it.Allow it to cool down and grind them into a coarse powder.", "This is known as bhaja masala.In a Blender, added washed dal, green chili, ginger, and salt.", "Grind them coarsely.In the same frying pan, add oil.", "Once the oil is hot, add remaining cumin seeds and fennel seeds.", "Fry them for few seconds until they turn brownish and sizzle.Now, add the urad dal paste to the seeds and combine well.Stir in the bhaja masala, garam masala, sugar and salt.Cook until the spice powders are combined well with the urad dal paste till the paste is golden brown, switch off the flame.Allow it to cool and make small balls out of the urad dal paste.For the stuffing, take a lemon sized dough and smoothen the cracks and make a ball.", "Roll the dough and spoon about a tablespoon of urad dal filling, smoothen the edges, cover the stuffing with dough and roll the dough such that the filling doesn\u2019t come out of poori.In a Kadai, heat enough oil to deep fry one Radhaballabhi poori at a time, till both sides are browned and cooked.", "Flip only once, such that they puff evenly.Drain the excess oil from the puffed puris with a paper towel.Serve warm Radhaballabhi with spicy Dum Aloo."]'::jsonb, 80, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Radhaballabhi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/78.Radhaballabhi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mooga Gathi (Sprouted Moong In Coconut Paste) Recipe', 'mooga-gathi-sprouted-moong-in-coconut-paste-recipe', 'Mooga Gathi or Mooghache Gathi is a traditional Goan dish usually served in temples. This dish is made using green gram or moong sprouts in a delicious coconut gravy which is tempered with mustard leaves and curry leaves. This is a pure veg dish made without using onion and garlic. Yet, this dish tastes so delicious that you will want to eat more. This dish is also made on special occasions like religious functions and festivals where we eat pure veg food. It tastes best with pooris, but some people love to eat it with rice.', '["1/2 cup Green Moong Sprouts", "6 tablespoon Fresh coconut , grated", "5 Whole Black Peppercorns", "3 Dry Red Chillies", "1 teaspoon Coriander (Dhania) Seeds", "1 teaspoon Turmeric powder (Haldi)", "1 Tamarind , marble sized ball", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "8-10 Curry leaves", "Asafoetida (hing)", "1 teaspoon Jaggery , grated", "2 teaspoon Oil"]'::jsonb, ARRAY['coconut', 'mustard seeds', 'asafoetida (hing)', 'green moong sprouts', 'jaggery', 'black peppercorns', 'curry leaves', 'tamarind marble', 'dry red chillies', 'coriander (dhania) seeds', 'turmeric powder', 'sunflower oil']::text[], '["To begin with Mooga Gathi, sprout the green gram by soaking them in water.", "Next day drain the water and keep it covered in a big strainer or muslin cloth.", "On next day, sprouts will start appearing.", "You can remove the peel of sprouted green gram by rubbing it against each other with your hands.Pressure cook the sprouted green gram by adding 2 cups water.", "Drain and retain the water.", "This water can be later added to the gravy.Grind the grated coconut, coriander powder, turmeric powder, red chilies, tamarind and peppercorns to a paste.Heat a kadhai and pour the gravy in it.", "To this add the sprouted green gram.", "Add 3/4th cup water specially the one retained after pressure cooking the green gram to make the gravy thin.Add grated jaggery and stir well.", "Simmer for 10 Minutes and switch off the gas.In a tempering pan, add a teaspoon oil.", "When oil gets heated add mustard seeds.", "When mustard seeds flutter add asafoetida and curry leaves.", "Add this tempering to the sprouted green gram curry and cover the kadai.", "Let it cook for 5-8 minutes and the switch off the heat.Serve Mooga Gathi with\u00a0Puri\u00a0or steamed rice for a perfect meal."]'::jsonb, 30, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Mooga_Gathi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/79.Mooga_Gathi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kelyachi Bhaji Recipe (Raw Banana Stir Fry)', 'kelyachi-bhaji-recipe-raw-banana-stir-fry', 'Kelyachi Bhaji also known as the Kacche Kele Ki Subzi or Raw Banana Stir Fry is a simple yet healthy and delicious recipe that you can make for a quick dinner or even pack into your lunch box. The addition of coconut and onions gives this recipe a twist to the regular raw banana recipes we eat. Serve the Kelyachi Bhaji (Raw Banana Stir Fry) as a side dish for your lunches and dinners. Serve it along with your favorite Sambar along with rice and ghee to make the meal complete.', '["2 Raw Banana", "1 Onion , finely chopped", "2 tablespoons Fresh coconut , grated", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1/4 teaspoon Asafoetida (hing)", "Salt , to taste", "Oil , as needed"]'::jsonb, ARRAY['salt', 'coconut', 'asafoetida (hing)', 'red chilli powder', 'onion', 'turmeric powder', 'banana', 'sunflower oil']::text[], '["To begin making the Kelyachi Bhaji Recipe (Raw Banana Stir Fry), first wash the raw banana, apply little oil to your hands and peel the banana using a peeler and cut the banana into dices.", "By applying oil in your hands, the stickiness from the raw banana will not come onto your hands.Heat a tablespoon of oil in a heavy bottomed wok/ kadai on medium heat.", "Add the onions and cook them until soft.", "Once the onions have softened, add the raw banana, sprinkle some salt and water.", "Cover the pan and cook on low to medium heat until the bananas have cooked through.", "Once the bananas have cooked through, add the turmeric powder, chilli powder, asafoetida powder and the grated coconut.", "Stir well for another 3 to 4 minutes until all the ingredients get well incorporated into the sabzi.Once done, turn off the heat and transfer to a serving bowl.Serve the\u00a0Kelyachi Bhaji (Raw Banana Stir Fry) as a side dish for your lunches and dinners.", "Serve it along with your favorite Sambar along with rice and ghee to make the meal complete."]'::jsonb, 30, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Kelyachi_Bhaji__Raw_Banana_Stir_Fry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/80.Kelyachi_Bhaji__Raw_Banana_Stir_Fry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mangalorean Style Sonay Sukka Recipe - Dry Chickpea Stir Fry', 'mangalorean-style-sonay-sukka-recipe-dry-chickpea-stir-fry', 'Mangalorean Style Sonay Sukhe is a very important dish for every Mangalorean meal plate. The preparation starts by tempering the mustard seeds, curry leaves, onion and garlic which is called as “Sukka”. It is used in most of the south Indian language in regions like Konkani, Karnataka and Mangalore.  You can as well use the same method in this recipe for many other legumes such as black channa, black eyed peas etc.', '["1 cup Kabuli Chana (White Chickpeas) , soaked in water overnight and boile", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "4 Cloves (Laung) , finely chopped", "1 Onion , chopped", "1/4 cup Fresh coconut , grated", "1/4 cup Tamarind Water", "Oil , for cooking", "Salt , to taste", "Bafat Powder (Roast & Grind)", "3 Byadagi Dried Chillies", "1 tablespoon Coriander (Dhania) Seeds", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Whole Black Peppercorns", "1 teaspoon Turmeric powder (Haldi)"]'::jsonb, ARRAY['salt', 'tamarind water', 'mustard seeds', 'coconut', 'black peppercorns', 'curry leaves', 'byadagi dried chillies', 'kabuli chana (white chickpeas) boile', 'onion', 'coriander (dhania) seeds', 'cumin seeds (jeera)', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Mangalorean Style Sonay Sukhe, soak the chickpeas in water for at least 8 hours or overnight.", "Pressure cook the chickpeas with water so that it is fully immersed and cook till done.", "This will take about 25 minutes.", "Once done switch off the heat and leave it to rest, the pressure will be released by itself.", "Drain the water away and keep the chickpeas aside.In a small pan; roast the ingredients for the Bafat powder including byadagi red chillies, coriander seeds, cumin seeds, whole black peppercorns, turmeric powder until you get a good roasted aroma from the coriander seeds.", "Turn off the heat, cool and grind into a fine powder.Heat a kadai with oil, add mustard seeds and allow it to crackle, add curry leaves and wait for 5 seconds.Add the chopped onions, grated coconut and garlic, saut\u00e9 till the onions are brown.", "Add\u00a0bafat powder mix to the saut\u00e9ed onions and mix well.Once the spice powder is added, add the cooked chickpea along with the tamarind water and keep saut\u00e9ing till the water is evaporated and you will get a dry dish.", "Check the salt and seasonings and adjust to suit your taste.Serve the Mangalorean Style Sonay Sukhe along with\u00a0Kori Gassi\u00a0and\u00a0Neer Dosa\u00a0as\u00a0your sunday meal for your family."]'::jsonb, 55, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Mangalorean_Style_Sonay_SukheSukka_Recipe_Dry_Chickpea_Stir_Fry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/81.Mangalorean_Style_Sonay_SukheSukka_Recipe_Dry_Chickpea_Stir_Fry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Konkani Style Vengaya Sagle Recipe - Eggplant Drumstick Curry', 'konkani-style-vengaya-sagle-recipe-eggplant-drumstick-curry', 'Konkani Style Vengaya Sagle Recipe is a very famous dish among the Konkani. “Sagle” in konkan means anything that is made with ground masala like coconut, coriander seeds and urad dal.  It has a very spicy and sweet flavor to it.  You can add any choice of your vegetable to this dish, keeping the ground masala constant.', '["1 Drumstick , cut into 2 inch long", "4 Brinjal (Baingan / Eggplant)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Urad Dal Flour", "Salt , to taste", "Oil", "To grind", "4 tablespoon Fresh coconut", "4 Dry Red Chillies", "1 tablespoon Coriander (Dhania) Seeds", "1 tablespoon White Urad Dal (Split)", "18 grams Tamarind", "1 tablespoon Jaggery"]'::jsonb, ARRAY['salt', 'urad dal flour', 'mustard seeds', 'brinjal (baingan eggsplant)', 'coconut', 'jaggery', 'drumstick', 'white urad dal (split)', 'dry red chillies', 'coriander (dhania) seeds', 'tamarind', 'sunflower oil']::text[], '["To begin making the Konkani Style Vengaya Sagle Recipe, firstly\u00a0pressure cook the drumstick in about 1/4 cup water, salt and little turmeric powder for about 2 whistle.", "Allow the pressure to release naturally and set aside.", "Then heat a skillet, roast the coriander seeds and urad dal till it is golden brown.", "Once they have roasted well and allow it to cool down.In a mixer add in the roasted ingredients and the rest of the ingredients (fresh coconut, dry red chillies, tamarind & Jaggery).", "Add a little water and grind it into a smooth paste.Heat the same skillet, add oil, and splutter the mustard seeds and urad dal on low heat.", "Then add in the ground paste saute for about 2 minutes.Add chopped brinjal and sprinkle with salt and saute for at least 5 more minutes until they soften.", "Add in the boiled drumstick and give it good mix.", "Check for seasoning and garnish with some coriander leaves and serve warm.", "Serve the Konkani Style Vengaya Sagle Recipe along with\u00a0Goan Chana Ros Recipe (White Peas Curry)\u00a0and Neer Dosa to make it a complete meal."]'::jsonb, 35, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Konkani_Style_Vengaya_Sagle_Recipe_Eggplant_and_Drumstick_Curry_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/82.Konkani_Style_Vengaya_Sagle_Recipe_Eggplant_and_Drumstick_Curry_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Matar Millet Pulao Recipe - Peas Pulao Recipe', 'matar-millet-pulao-recipe-peas-pulao-recipe', 'Matar Millet Pulao Recipe (Peas Pulao Recipe) is a healthy way of including millet into your everyday diet. The pear millet commonly called as Bajra in the local Indian Language is rich in protein, fiber, magnesium and Iron. Adding peas to the preparation will create a better flavor and texture to the whole dish. It is quick and easy to make at any time of the day.', '["1 cup Bajra Flour ( Pearl Millet) , soaked in water for 30 minutes", "1 cup Green peas (Matar)", "2 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta)", "2 teaspoons Cumin seeds (Jeera)", "Salt , to taste", "Ghee , for cooking"]'::jsonb, ARRAY['salt', 'bay leaf (tej patta)', 'cardamom (elaichi) podsseeds', 'ghee', 'green peas (matar)', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'bajra flour ( pearl millet)']::text[], '["To begin making the Matar Millet Pulao Recipe (Peas Pulao Recipe), pressure cook the millet with 1-1/2 cups of water in a pressure cooker for about 2 whistles till they are just cooked.Heat a heavy bottomed pan with ghee.", "Once the ghee is hot, add the whole spice like cardamom pods, cinnamon sticks, bay leaf, cumin seeds and allow them to splutter.Once done, add the cooked millets and mix everything properly.", "After a minute, add salt, mix it again and switch off the heat.", "Next, heat a saucepan with enough water for the peas to blanch.", "Once the water starts to boil, add the peas and cook for 30 seconds and drain the water.Sprinkle peas over the tossed millet, give it a stir and serve hot.Serve the\u00a0Matar Millet Pulao Recipe (Peas Pulao Recipe)\u00a0along with\u00a0Boondi Raita\u00a0and a roasted papad for a weekday dinner and you are sorted."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Matar_Millet_Paulo_Recipe_Peas_Paulo_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/83.Matar_Millet_Paulo_Recipe_Peas_Paulo_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tamil Nadu Style Potato Masiyal Recipe (South Indian Style Aloo Masala)', 'tamil-nadu-style-potato-masiyal-recipe-south-indian-style-aloo-masala', 'Potato Masal and Poori/Puri (puffed Indian flatbread) are match made in heaven. It is one of the most popular and favourite tiffin combination especially in the South. The potatoes are soft boiled and then simmered in an open pan/kadai along with the South Indian Masalas. Potatoes are delicious and are universally loved by children and adults.', '["4 Potatoes (Aloo) , boiled, peeled and roughly crumbled", "1 Onion , thinly sliced", "4 Green Chillies , finely chopped", "1/2 inch Ginger , grated", "2 cloves Garlic , grated", "5-6 Cashew nuts , roughly chopped", "1 teaspoon Gram flour (besan)", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Few sprig Coriander (Dhania) Leaves , finely chopped", "2 teaspoons Sesame (Gingelly) Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Chana dal (Bengal Gram Dal)", "1 sprig Curry leaves"]'::jsonb, ARRAY['cashew nuts', 'salt', 'ginger', 'chana dal (bengal gram dal)', 'mustard seeds', 'sesame (gingelly) oil', 'cloves garlic', 'gram flour (besan)', 'curry leaves', 'coriander (dhania) leaves', 'onion', 'potato (aloo)', 'turmeric powder', 'green chillies']::text[], '["To begin making the Tamil Nadu Style Potato Masal recipe, first heat a kadai/wok over low flame with oil.When the oil is hot, temper with mustard seeds, channa dal and curry leaves.Add the ginger, garlic, green chillies, cashew nuts and mix well over low flame.Immediately, add the thinly sliced onions, turmeric powder, pinch of salt and cook till they turn transparent.Meanwhile, mix besan/gram flour with 1/4 cup water in a mixing bowl.", "Add 1/2 cup water to the kadai and adjust salt.Now add the besan mixture.", "Let the mixture cook for 5 minutes over low flame.Add the crumbled potatoes and allow it to cook over low flame for another 7-8 minutes, stirring occasionally.Switch off, garnish with coriander leaves and it is ready to be served.You can include Tamil Nadu Style Potato Masal with hot\u00a0Puri\u00a0in your special weekend menu or pack them for your office/school lunch box.", "Either ways, they are tempting and yummy!."]'::jsonb, 70, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Uma_Raghuraman/Tamilnadu_Style_Poori_Masal__South_Indian_Aloo_Masala_for_Poori_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/84.Tamilnadu_Style_Poori_Masal__South_Indian_Aloo_Masala_for_Poori_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gajar Methi Sabzi Recipe (Carrot Fenugreek Leaves Stir Fry)', 'gajar-methi-sabzi-recipe-carrot-fenugreek-leaves-stir-fry', 'Indian Stir fry vegetables are not just easy to make but they are packed with loads of flavour and makes a delicious and healthy side dish for roti or rice. This sabzi is a unique side dish which has a perfect blend of spice, sweet (from the carrots), and a tad bitter (from methi leaves). The secret to making a delicious sabzi is use of fresh ingredients. Fresh carrots, and fresh methi leaves (fenugreek leaves) does the trick to this sabzi as well.', '["2 Carrots (Gajjar)", "1 cup Methi Leaves (Fenugreek Leaves) , tightly packed", "1 Onion , finely chopped", "1 teaspoon Cumin seeds (Jeera)", "Asafoetida (hing) , A pinch", "1 teaspoon Red Chilli powder", "1-1/2 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Amchur (Dry Mango Powder)", "Salt , to taste", "2 tablespoons Oil"]'::jsonb, ARRAY['salt', 'amchur (dry mango powder)', 'asafoetida (hing)', 'methi leaves (fenugreek leaves)', 'red chilli powder', 'carrot', 'onion', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Gajar Methi Sabzi recipe, firstly peel, wash and chop the carrots into small pieces.Pick the methi leaves from stem and wash the leaves well.", "Chop the methi leaves fine.Heat oil in a wok/kadai.", "Add cumin seeds to hot oil and wait till it turns brown.", "Add asafoetida, mix.Add finely chopped onions and saut\u00e9 till onions turn soft and translucent.Add coriander powder, red chilli powder, turmeric powder, salt to taste and give it good mix.Now add chopped carrots, mix and cook until for 5 minutes on medium flame.Add1/4 cup water and continue to cook the carrots.", "When carrots are half done, add finely chopped methi leaves.Cook until all vegetables are cooked, keep stirring in between.When all water evaporates and carrots turn tender, sprinkle amchur powder and 1 more teaspoon oil over the vegetables and stir well.Cook for 2 minutes on low flame, remove the pan from stove and serve hot.", "Serve Gajar Methi Sabzi with\u00a0Curd Rice\u00a0or\u00a0Phulkas\u00a0and\u00a0Panchmel Dal\u00a0for a percent weekday lunch or dinner."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Carrot_Methi_Sabzi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/85.Carrot_Methi_Sabzi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bendekayi Puli Koddel Recipe - Lady Finger In Coconut Tamarind Curry', 'bendekayi-puli-koddel-recipe-lady-finger-in-coconut-tamarind-curry', 'Bendekayi Puli Koddel Recipe is a simple yet delectable lady''s finger curry cooked in freshly made coconut masala. It is spicy, sweet and tangy which makes it a perfect accompaniment with Steamed Rice. It is usually prepared using Ash Gourd or Pumpkin, however here we will be cooking with Okras/Bhindi/Lady Finger to give it a crunchy texture.', '["200 grams Bhindi (Lady Finger/Okra) , cut into 1 inch", "Salt , to taste", "2 teaspoons Oil", "Ingredients for the masala", "1/2 cup Fresh coconut , grated", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Cumin seeds (Jeera)", "6 Dry Red Chillies", "2 teaspoon Coriander (Dhania) Seeds", "2 tablespoons Sesame seeds (Til seeds)", "2 teaspoons Rice", "4 cloves Garlic", "30 grams Tamarind Water", "1/4 teaspoon Turmeric powder (Haldi)", "2 tablespoons Jaggery", "1/2 cup Water", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon SSP Asafoetida (Hing)", "2 Dry Red Chillies", "2 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'rice', 'coconut', 'tamarind water', 'mustard seeds', 'cumin (jeera) seeds', 'jaggery', 'asafoetida (hing)', 'cloves garlic', 'water', 'curry leaves', 'dry red chillies', 'coriander (dhania) seeds', 'methi seeds (fenugreek seeds)', 'bhindi (lady fingerokra)', 'turmeric powder', 'sesame seeds (til seeds)', 'sunflower oil']::text[], '["To begin making the Bendekayi Puli Koddel Recipe, into a preheated pan, add oil and okra or Bendekayi.", "Sprinkle salt to taste and stir well.", "Cover and cook the okras till soft and roasted.", "Stir occasionally to ensure even cooking of the\u00a0Okra.Now we will roast the masalas for the\u00a0Bendekayi Puli Koddel.Into a preheated pan, add fenugreek seeds, cumin seeds, coriander seeds, sesame seeds, rice grains, dry red chillies, garlic and stir for 3 to 4 minutes until well roasted.Once done, add the coconut and roast for another 2 minutes.", "Turn off the heat after the coconut is light golden in color and allow it to cool.", "Once the coconut cools down, add the roasted masala to a mixer grinder along with tamarind, jaggery, water and blend to make a smooth paste and keep it aside.Add the ground masala into the pan with the roasted lady''s finger.", "Add about 1/2 cup of water, salt to taste and bring the\u00a0Bendekayi Puli Koddel to a brisk boil.", "Boil for 4 to 5 minutes until the curry has thickened and reached the desired consistency.", "Once done, switch off the gas.*For the seasoning:Heat oil in a tadka pan.", "Add mustard seeds and allow it to crackle.", "Once the mustard seeds have crackled, add asafoetida, dry red chillies and curry leaves.", "Turn off the heat after few seconds and pour the seasoning over the\u00a0Bendekayi Puli Koddel.", "Give it a mix.Transfer the\u00a0Bendekayi Puli Koddel into a serving bowl and serve.Serve the\u00a0Bendekayi Puli Koddel Recipe along with\u00a0Steamed Rice,\u00a0Mangalorean Padengi Gassi\u00a0and\u00a0Elai Vadam\u00a0for a comforting lunch."]'::jsonb, 30, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Bendekayi_Puli_Koddel_-_Ladys_Finger_In_Coconut_Tamarind_Curry_8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/86.Bendekayi_Puli_Koddel_-_Ladys_Finger_In_Coconut_Tamarind_Curry_8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tomato Kurma Recipe - Thakkali Kurma For Biryani & Parotta', 'tomato-kurma-recipe-thakkali-kurma-for-biryani-parotta', 'Tomato Kurma Recipe is a delicious gravy recipe that is prepared with ingredients that are found in every South Indian Kitchen. A ground masala of coconut, fried gram dal, green chillies and fennel are added to a flavourful tomato onion gravy and garnished with chopped coriander leaves.', '["2 Onions , finely chopped", "4 Tomatoes , finely chopped", "1 inch Cinnamon Stick (Dalchini)", "1 teaspoon Cumin seeds (Jeera)", "2 Star anise", "2 tablespoons Sambar Powder", "Salt , as per your taste", "2 teaspoons Ghee", "To grind", "2 tablespoons Roasted Gram Dal (Pottukadalai)", "3 tablespoons Fresh coconut , grated", "3 Green Chillies", "1 tablespoon Fennel seeds (Saunf)", "1 tablespoon Water"]'::jsonb, ARRAY['tomato', 'salt', 'green chillies', 'ghee', 'coconut', 'fennel seeds (saunf)', 'gram dal (pottukadalai)', 'water', 'onion', 'cumin seeds (jeera)', 'cinnamon stick (dalchini)', 'sambar powder', 'star anise']::text[], '["To begin making\u00a0Tomato Kurma Recipe, we will first grind all the ingredients needs for the Kurma paste.In a mixer combine, add roasted gram dal, fresh grated coconut, green chillies, fennel seeds and a tablespoon of water.", "Grind the ingredients until you get a smooth paste.", "Keep aside for later.Next, place a heavy bottomed pan on medium heat and add 2 teaspoons of ghee.", "Once the ghee is warm, add cumin seeds and allow it to sizzle.When the cumin seeds are sizzling, add the star anise, cinnamon and saute it for about 30 to 35 seconds.Add the chopped onions and stir until they are caramelized.", "Next, add the chopped tomatoes along with sambar powder and saute until the tomatoes are soft and mushy.", "Once the tomatoes are mushy, add the ground kurma paste, salt to taste and simmer the flame to low.", "Add 1/4 cup water, stir and close the lid of the pan.", "Let the tomato kurma simmer for 5 minutes.", "After 5 minutes, open the lid of the pan, give it a good stir and turn off the flame.", "Garnish it with coriander leaves and it is ready to be served.Serve Tomato Kurma Recipe along with Vegetable Biryani and Tomato Onion Cucumber Raita.", "You can also serve Tomato Kurma along with Kerala Style Parotta for a weeknight dinner."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Tomato_Kurma_Recipe_-_Thakkali_Kurma_Perfect_For_Biryani_and_Parotta-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/87.Tomato_Kurma_Recipe_-_Thakkali_Kurma_Perfect_For_Biryani_and_Parotta-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karwar NKGSB style Vataane Ananasaa Shaak Recipe- Pineapple & Whites Peas Sabzi', 'karwar-nkgsb-style-vataane-ananasaa-shaak-recipe-pineapple-whites-peas-sabzi', 'Karwar NKGSB style Vataane Ananasaa Shaak Recipe- Pineapple & Whites Peas Sabzi is a delicious gravy from the NKGSB cuisine is the, Vataane Ananasaa Shaak Recipe, which is a Sweet And Sour White Peas And Pineapple Sabzi. Safed Vataane refer to dried white peas and ananas means pineapple.', '["3 cups Pineapple , Chopped into chunks after discarding the middle portion and the tiny thorns that appear on the sides.", "1/2 cup Dried Yellow/White Peas (Vatana)", "1 Onion , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 1/2 tablespoons Jaggery", "Salt , to taste", "1 tablespoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)", "1 1/2 tablespoons Coriander (Dhania) Seeds", "4 Dry Red Chillies", "1/2 teaspoon Oil", "3/4 cup Fresh coconut , grated"]'::jsonb, ARRAY['s pineapple', 'dried yellow/white peas', 'vatana', 'onion', 'turmeric powder', 'haldi', 's jaggery', 'salt', 'oil', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing', 's coriander', 'dhania', 'dry red chillies', 'fresh coconut']::text[], '["To make Vataane Ananasaa Shaak Recipe, we need to\u00a0first wash and soak the white peas overnight.", "Next morning wash them thoroughly and keep aside.", "In a pressure cooker add the drained white peas along with 1/2 cup of water, pressure cook for 3 whistles and then reduce the flame and cook for about 2-3 minutes.", "Turn off the flame.", "Drain the white peas and set aside."]'::jsonb, 55, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/panditp253-gmail.com/Vataane_Ananasaa_Shaak.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/88.Vataane_Ananasaa_Shaak.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mutta Salna Recipe (South Indian Style Egg Drop Gravy)', 'mutta-salna-recipe-south-indian-style-egg-drop-gravy', 'Mutta Salna is a South Indian gravy that is served for parotta or chapathi. I always like the salna given for parotta in small Street side shops. It is very tasty and goes well for idli, dosa, idiyappam, chapathi or parotta. Make this and we are sure you will make it again and again.', '["5 Whole Eggs", "1 Onion", "1 Tomato", "1 tablespoon Ginger Garlic Paste", "1 teaspoon Cumin seeds (Jeera)", "Turmeric powder (Haldi) , a pinch", "1/2 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "Salt , as required", "2 teaspoons Oil", "1 Bay leaf (tej patta)", "1 Onion", "6 cloves Garlic", "Mint Leaves (Pudina) , handful", "1/4 cup Fresh coconut", "1 teaspoon Coriander (Dhania) Seeds", "1/2 inch Cinnamon Stick (Dalchini)", "5 Cloves (Laung)", "1/2 teaspoon Fennel seeds (Saunf)", "1/2 teaspoon Whole Black Peppercorns", "2 Star anise", "2 teaspoons Oil"]'::jsonb, ARRAY['whole eggs', 'onion', 'tomato', 'ginger garlic paste', 'cumin seeds', 'jeera', 'turmeric powder', 'haldi', 'red chilli powder', 'coriander powder', 'dhania', 'garam masala powder', 'salt', 's oil', 'bay leaf', 'tej patta', 's garlic', 'mint leaves', 'pudina', 'fresh coconut', 'coriander', 'cinnamon stick', 'dalchini', 'laung', 'fennel seeds', 'saunf', 'whole black peppercorns', 'star anise']::text[], '["To begin making the Mutta Salna recipe, let us first make the masala.", "Heat oil in a heavy bottomed pan, add fennel seeds, pepper, cinnamon, cloves and star anise.", "Let it cook for a minute.Add garlic and saute until it changes color.", "Add onion and saute until it turns translucent.", "Switch off and add mint leaves.Saute and allow it to cool.", "Once cooled, transfer everything to a mixie jar.", "Add coconut and coriander seeds to it.", "Add little water and grind into paste.", "Keep aside.Heat oil in a heavy bottomed pan, add bay leaves and cumin seeds.", "Then add chopped onion and saute well.Add ginger garlic paste and saute until the raw smell goes.", "Add tomato and saute until it turns mushy.Now add the ground masala along with required water for the gravy.", "Mix and cook in a medium flame.Add turmeric powder, chilli powder, coriander powder, garam masala powder and required salt.Mix well and cook until the oil separates.", "Now add the eggs and mix well.", "You can also add eggs that are\u00a0 beaten in a separate bowl.Cover and cook in low flame for few minutes until the eggs gets cooked and the gravy becomes thick.", "The mutta salna is ready.", "Serve\u00a0Mutta Salna along with\u00a0Kerala Parotta\u00a0and\u00a0Carrot Methi Pachadi\u00a0for your weekday lunch."]'::jsonb, 35, 'South Indian', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swathynandhini/MUTTA_SALNA_RECIPE_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/89.MUTTA_SALNA_RECIPE_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer Gassi Recipe', 'paneer-gassi-recipe', 'Paneer Gassi Recipe is a delicious coconut and red chilli based curry from the coastal region of Mangalore. Traditionally the curry is made with chicken. This curry has a lovely blend of different fragrant spices, which is quite unique to Mangalore''s cultural heritage. Mangalore cuisine is mostly influenced by Tulu speaking Bunts, the Kannada speaking Brahmins, Konkani speaking Catholics and Goud Saraswat Brahmins to name a few.', '["1 Onion , roughly chopped", "10 cloves Garlic", "12 Byadagi Dried Chillies , or you can use 6 to 8 kashmiri chillies and 6 small red chillies)", "1 tablespoon Coriander (Dhania) Seeds", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "15 Whole Black Peppercorns", "Tamarind , lemon sized", "1 cup Fresh coconut , grated", "1 tablespoon Ghee", "500 grams Paneer (Homemade Cottage Cheese) , cut into cubes", "1 Onion , finely sliced", "Salt , to taste", "1/2 teaspoon Turmeric powder (Haldi)", "1 cup Coconut milk , thick", "1 cup Coconut milk , thin", "1 tablespoon Ghee", "1 inch Cinnamon Stick (Dalchini)", "3 Cloves (Laung)", "2 Cardamom (Elaichi) Pods/Seeds", "2 Curry leaves"]'::jsonb, ARRAY['byadagi dried chillies you can kashmiri chillies red chillies)', 'salt', 'coconut', 'ghee', 'paneer', 'cardamom (elaichi) podsseeds', 'cloves garlic', 'black peppercorns', 'curry leaves', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'cinnamon stick (dalchini)', 'coconut milk', 'turmeric powder', 'cloves (laung)', 'tamarind lemon']::text[], '["To begin making the\u00a0Paneer Gassi Recipe, soak the ball of tamarind in hot water for 10 minutes.In a heavy bottomed pan add 1 teaspoon ghee.", "Roast coriander seeds, cumin seeds, fenugreek seeds, dried red chillies, pepper corns one by one until fragrant.", "Be careful to roast on a low flame so as not to burn the spices.", "Once roasted remove from pan and set aside to cool.In the same pan, add sliced onions, garlic and roast until onions start to turn brown.", "Now add freshly grated coconut and continue to roast until coconut starts to turn golden brown.", "Remove from pan and set it aside.Squeeze out the water from the tamarind and throw away the seeds.", "Once all the roasted spices and the onion-coconut mix has cooled, add them all to a blender and blend into a smooth paste along with the tamarind water.Now add remaining ghee/ coconut oil to the pan.", "Add cinnamon, cardamoms, cloves and saute until fragrant.", "Add sliced onions and saut\u00e9 for a minute.", "Add curry leaves, mix well.Add the ground masala paste along with turmeric and cook until oil/ghee separates from the sides of the pan.Afte a minute, add the ground masala paste along with turmeric and cook until oil/ghee separates from the sides of the pan.Add the paneer pieces and give it a good mix so that the paneer is coated uniformly with the masala.", "Continue stirring for 5 minutes.", "Now add thin coconut milk and salt to taste, bring it to boil.Reduce flame to medium, cover and cook until well done.", "Once the chicken is cooked well, add thick coconut milk, reduce to simmer.", "Cook for a minute or two and turn off the flame.", "Do not let the curry come to boil as the milk might curdle.Serve the\u00a0Paneer Gassi Recipe along with\u00a0neer dosa,\u00a0Tomato Onion Chutney\u00a0to create a delicious breakfast meal."]'::jsonb, 45, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Paneer_Gassi_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/90.Paneer_Gassi_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Satsaagi Recipe - Sindhi Seven Vegetable Sabzi No Onion No Garlic', 'satsaagi-recipe-sindhi-seven-vegetable-sabzi-no-onion-no-garlic', 'Satsaagi Recipe is a super nutritious sabzi that is made in almost all Sindhi households.', '["2 Carrot (Gajjar) , diced", "10 Green beans (French Beans) , cut into 1 inch", "10 Colocasia root (Arbi) , small ones", "1/4 cup Green peas (Matar)", "2 Potatoes (Aloo) , diced", "1/3 cup Bottle gourd (lauki) , diced", "1/4 cup Green Bell Pepper (Capsicum) , diced", "Oil , to fry", "1 tablespoon Ghee", "1/2 teaspoon Cumin seeds (Jeera)", "1 Asafoetida (hing) , a pinch", "2 Green Chillies , slit", "2 teaspoons Ginger , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Garam masala powder", "1 teaspoon Coriander (Dhania) Leaves", "1/4 cup Homemade tomato puree", "2 sprig Coriander (Dhania) Leaves , finely chopped", "2 sprig Mint Leaves (Pudina) , finely chopped"]'::jsonb, ARRAY['tomato', 'cumin powder (jeera)', 'asafoetida (hing)', 'coriander (dhania) leaves', 'carrot', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies', 'sunflower oil', 'garam masala powder', 'green beans (french beans)', 'mint leaves (pudina)', 'red chilli powder', 'ginger', 'amchur (dry mango powder)', 'ghee', 'green peas (matar)', 'coriander (dhania) leaves', 'colocasia root (arbi)', 'bottle gourd (lauki)', 'green bell pepper (capsicum)', 'potato (aloo)']::text[], '["To begin making the Satsaagi Recipe we need to cook the vegetables.", "In a pressure cooker combine the peas, carrot, beans and lauki with some salt and 1/4 cup of water and pressure cook for one whistle.", "Turn off the flame and immediately release the pressure.", "Transfer the vegetables into a strainer and drain off the excess water.", "Set aside to cool.", "In the same pressure cooker yet add the washed whole arbi, add some water and pressure cook for about 4 whistles.", "Turn off the flame and allow the pressure to release naturally.", "Once the pressure has released, open the lid, drain off the excess water.", "Peel the arbi and set aside.", "Heat a kadai with oil, to deep fry the rest of the vegetables.", "Firstly, deep fry the potatoes, until they turn into a light brown colour.", "This will take about 3-5 minutes.", "Once cooked place the potatoes on an absorbent paper to drain off the excess oil.", "Next, deep fry the boil arbi,\u00a0until they turn into a light brown colour.", "This will take about 3-5 minutes.", "Once cooked place the arbi on an absorbent paper to drain off the excess oil.Finally, deep fry the capsicum until crunchy.", "This will take about 2-4 minutes.", "Once cooked place the capsicum on an absorbent paper to drain off the excess oil.Getting ahead to bring the Satsaagi together.", "Heat a skillet with ghee on medium flame, to this add the cumin seeds, asafoetida, ginger and green chilli and mix well.", "Now add the salt and turmeric powder and allow it to cook for about 30 seconds.", "To this add, the potatoes, arbi, capsicum, and mix.", "At this stage add the boiled veggies, carrot, beans, peas, and lauki.", "Now sprinkle some\u00a0red chilli powder, cumin powder,\u00a0amchur powder,\u00a0garam masala,\u00a0coriander powder\u00a0 and mix well until the vegetables are evenly coated with the masala.", "Finally top this satsaagi sabzi with tomato puree, mix and cover and cook for 2 minutes.Open the lid, turn off the flame, add the chopped mint and coriander leaves and transfer the satsagi into a serving platter.", "Serve\u00a0Satsaagi Recipe along with\u00a0Phulka,\u00a0Sindhi Dal,\u00a0Aam Ka Achaar, for a comforting complete lunch meal."]'::jsonb, 50, 'Sindhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Articles/Sindhi_Satsagi_Recipe_Mixed_Sabzi_With_7_Vegetables_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/91.Sindhi_Satsagi_Recipe_Mixed_Sabzi_With_7_Vegetables_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mulakushyam Recipe - A Mixed Vegetable Lentil Curry', 'mulakushyam-recipe-a-mixed-vegetable-lentil-curry', 'Mulakushyam is an easy recipe from the Palakkad Cuisine. It is a dish comprising of the combination of lentils, essentially Moong Dal cooked along with vegetables with a drizzle of coconut oil to add a Palakad touch to the recipe.', '["1/2 cup Yellow Moong Dal (Split)", "1 Chayote , peeled and diced", "1 Potato (Aloo) , peeled and diced", "2 Carrot (Gajjar) , peeled and diced", "1/4 cup Green peas (Matar)", "2 Green Chillies , slit", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Curry leaves , a sprig", "1/4 teaspoon Black pepper powder", "1 tablespoon Coconut Oil"]'::jsonb, ARRAY['salt', 'yellow moong dal (split)', 'chayote', 'potato (aloo)', 'green peas (matar)', 'carrot', 'curry leaves', 'coconut oil', 'black pepper powder', 'turmeric powder', 'green chillies']::text[], '["To begin making the\u00a0Mulakushyam Recipe - A Mixed Vegetable Lentil Curry, first prepare the vegetables by peeling and cutting them.", "Wash the dal and keep aside.We will now cook everything a single pot, by either using a pressure cooker or using a sauce pan method.", "If using the sauce pan method, follow the same instructions as below and cook until the dal is soft and cooked through.Place the washed dal, the chopped vegetable, slit green chillies into the pressure cooker.", "Add the turmeric,salt and about 2 cups of water.", "Place the weight on and pressure cook until you hear two whistles.", "After 2 whistles, turn the heat to low and simmer for a couple of minutes and turn off the heat.Allow the pressure to release naturally.", "Once the pressure has released, add the curry leaves, the coconut oil, salt and pepper to taste.", "Stir and give the Mulakushyama brisk boil.", "Turn off the heat and transfer to a serving bowl.Serve the\u00a0Mulakushyam along with\u00a0Steamed Rice\u00a0,\u00a0Elai Vadam\u00a0and\u00a0Pisarna Manga Recipe\u00a0for a quick and wholesome weeknight dinner."]'::jsonb, 48, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Sandhya_Hariharan/Molagooshyam__A_Mixed_Vegetable_Lentil_Curry1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/92.Molagooshyam__A_Mixed_Vegetable_Lentil_Curry1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Nutty Aloo Paratha Recipe', 'nutty-aloo-paratha-recipe', 'Nutty Aloo Paratha Recipe is a wonderful twist to the regular aloo paratha recipe and is a sure-shot crowd pleaser. This recipe includes chopped nuts and raisins along with the classic spiced aloo filling.', '["1 cup Whole Wheat Flour", "1 cup Spinach Leaves (Palak) , pureed", "Water , as required to make pliable dough", "3 Potatoes (Aloo) , boiled and mashed", "1/2 cup Paneer (Homemade Cottage Cheese) , crumbled/grated", "1 tablespoon Coriander (Dhania) Leaves", "1/2 teaspoon Garam masala powder", "Salt , to taste", "1/2 teaspoon Cumin powder (Jeera)", "1 teaspoon Red Chilli powder , or 2 chopped green chillies", "1-1/2 tablespoon Mixed nuts , chopped", "1 tablespoon Sultana Raisins", "Ghee , to smear"]'::jsonb, ARRAY['salt', 'wheat flour', 'cumin powder (jeera)', 'coriander (dhania) leaves', 'paneer', 'ghee', 'raisins', 'water make pliable dough', 'red chilli powder green chillies', 'potato (aloo)', 'spinach leaves (palak)', 'garam masala powder', 'mixed nuts']::text[], '["To begin making Nutty Aloo Paratha Recipe,first knead the dough and keep it aside.In a Mixing bowl, bring together wheat flour, water, and spinach puree (if using) to a soft pliable dough by kneading well.", "Few drops of ghee or oil can be added if required."]'::jsonb, 55, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/6-march/Nutty_Aloo_Stuffed_Palak_Paratha_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/93.Nutty_Aloo_Stuffed_Palak_Paratha_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Kadala Curry Recipe - Spicy Chickpeas in Coconut Curry', 'kerala-kadala-curry-recipe-spicy-chickpeas-in-coconut-curry', 'Kerala Kadala Curry Recipe is a delectable recipe that is a popular dish from the Kerala Cuisine. Kadala in this dish means chickpeas and most popularly the kala chana or the brown chickpea is used to make this dish. The coconut is ground along with fennel and coriander seeds and then cooked along in a gravy that has flavours coming from baby onions, green chillies and curry leaves along with the addition of cooking it in coconut oil.', '["Ingredients for the Curry", "1 cup Kala Chana (Brown Chickpeas) , soaked overnight and cooked", "1 tablespoon Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 sprig Curry leaves , finely chopped", "2 Green Chillies , slit", "15 Pearl onions (Sambar Onions) , finely chopped", "5 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "1/2 cup Homemade tomato puree", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "Salt , to taste", "Ingredients to be ground to paste", "1 cup Fresh coconut", "2 tablespoons Coriander (Dhania) Seeds", "1 teaspoon Fennel seeds (Saunf)"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'mustard seeds', 'coconut', 'fennel seeds (saunf)', 'red chilli powder', 'cloves garlic', 'curry leaves', 'pearl onion (sambar onion)', 'coriander (dhania) seeds', 'turmeric powder', 'coconut oil', 'green chillies', 'kala chana (brown chickpeas)']::text[], '["To begin making the Kerala Kadala Curry Recipe, soak chickpeas overnight or for at least 8 hours.Place the soaked chickpeas in the pressure cooker along with a little salt and 2-1/2 cups of water and cook until for 4 to 5 whistles.", "After 5 whistles, turn the heat to low and simmer for 20 minutes and turn the off the heat.Allow the pressure to release naturally.", "Ensure the kadal is completely cooked and has a soft bite.", "If not cook it for a longer time.", "Next to make the coconut paste, into a mixer grinder jar, add the coconut, fennel seeds and coriander seeds.", "Add 1/2 cup of warm water and blend to make a smooth paste.", "Heat oil in a heavy bottomed pan over medium heat.Add the mustard seeds and allow it to crackle.", "Once it crackles, add the onion, garlic, ginger and green chillies and saute until the onion is soft and translucent.", "Add the curry leaves and saute for a few seconds.", "Stir in the tomato puree, turmeric powder, red chilli powder and the coconut puree and give the curry mixture a stir.Finally add the cooked chickpeas, a little salt to taste and bring the Kadala Curry to a boil.Add a cup of water, give the Kadala Curry a stir and turn the heat to low.", "Simmer the Kadala Curry for a good 15 minutes until all the masala is well absorbed to make a delicious taste Kadala Curry.Give it a taste and adjust the salt and chilli accordingly.", "Turn off the heat and transfer the Kerala Kadala Curry to a serving bowl and serve hot.Serve the Kerala Kadala Curry along with\u00a0Puttu\u00a0for a delicious breakfast, lunch or dinner or even make it for the festival of Onam."]'::jsonb, 30, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Kerala_Kadala_Curry_recipe_Chickpea_in_Coconut_Curry_Vegetarian_healthy_recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/94.Kerala_Kadala_Curry_recipe_Chickpea_in_Coconut_Curry_Vegetarian_healthy_recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paya Curry Recipe | Lamb Trotters', 'paya-curry-recipe-lamb-trotters', 'Paya Curry is a recipe made of lamb trotters. South India is known for its spicy twist of Non vegetarian dishes, using almost every part of the animal to cook a meal. If you are a true blue foodie, you would have either dined or heard of traditional military hotels or a food mess serving some authentic, regional dishes that one cannot find in most of the commercial restaurants. These places do not offer an ambiance, you need to be an early riser to enjoy their menu and they are great on taste plus value for money.', '["12 Lamb trotters , well roasted & rinsed- lamb trotters", "1 teaspoon Turmeric powder (Haldi)", "1 tablespoon Coriander Powder (Dhania)", "1-1/2 tablespoons Red Chilli powder , (adjust as per your preference)", "1 tablespoon Rice flour", "Salt , to taste", "To be ground to paste", "1 Onion , chopped", "2 teaspoons Oil", "5 sprig Coriander (Dhania) Leaves", "1 inch Ginger", "6 cloves Garlic", "1 inch Cinnamon Stick (Dalchini)", "4 Cloves (Laung)"]'::jsonb, ARRAY['salt', 'ginger', 'red chilli powder ( per preference)', 'cloves garlic', 'lamb trotters lamb trotters', 'coriander (dhania) leaves', 'onion', 'cinnamon stick (dalchini)', 'coriander powder', 'rice flour', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making Paya Curry Recipe | Lamb Trotters, in a large pressure cooker, add the lamb trotters, and enough water to completely submerge the trotters and cook on a low flame for 20-30 minutes.Once you are done pressure cooking, transfer all of it\u00a0including the mutton broth into a large vessel and add the dry spice powders(turmeric, coriander, and red chilli powder) and salt.", "Cook on a medium flame with a closed lid on for atleast 10 minutes or more.", "This will help the trotters to absorb the basic flavours.Meanwhile, in a kadai, heat a bit of cooking oil, once it is hot, add the chopped onions and saute on medium high heat until the onions caramelize and are browned a bit.Add this caramelized onions in a mixer grinder along with coriander leaves, ginger, garlic, cinnamon, and cloves, and with the help of a little water, grind it into a fine paste.Add the ground masala to the pan where the paya is cooking and add rice flour - stir well to coat all the pieces.", "You may add more water to set the\u00a0consistency based on your preference.", "Check for spices and salt level to adjust accordingly.", "Cook on a low flame for 15 -20 minutes, with intermediate stirring with a closed lid, until the masala is cooked and any residual raw smell disappears.Serve\u00a0Paya Curry Recipe | Lamb Trotters\u00a0with\u00a0Steamed Rice,\u00a0Tawa Paratha,\u00a0Kerala Style Appam Recipe (Fermented Rice Pancakes With Coconut)\u00a0or\u00a0Butter Garlic Naan Recipe."]'::jsonb, 110, 'South Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/FlavorFlameFusion/Paya_Curry__Lamb_Trotters_recipe_edited1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/95.Paya_Curry__Lamb_Trotters_recipe_edited1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mangalore Cucumber Chana Dal Subzi Recipe', 'mangalore-cucumber-chana-dal-subzi-recipe', 'Mangalore Cucumber Chana Dal Sabzi Recipe is a nutritious recipe that combined the Bottle Gourd and lentils making it a perfect dish for a wholesome lunch or dinner. This curry is made with mangalore cucumber which is a widely used vegetable in many parts of Mangalore which is in south India. Pulses are an essential part of ingredient in most of the Indian meals. They are low glycemic index. That helps you to keep your sugar levels in control. Mangalore cucumber on the other hand is a good source of potassium and sodium which controls the blood pressure levels.', '["1 Mangalorean cucumber , cut into bite sized pieces.", "1 cup Chana dal (Bengal Gram Dal)", "1 teaspoon Cumin seeds (Jeera)", "1 Bay leaf (tej patta)", "1 teaspoon Ginger , grated", "1 Tomato , finely chopped", "1 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder , adjust according to taste", "1 teaspoon Sugar", "1 Coriander (Dhania) Leaves , small bunch, chopped", "Ingredients for Seasoning", "1 teaspoon Oil", "1 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'coriander (dhania)', 'salt', 'ginger', 'bay leaf (tej patta)', 'red chilli powder', 'sugar', 'dry red chillies', 'cumin seeds (jeera)', 'turmeric powder', 'coriander powder', 'mangalorean cucumber', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making the Mangalore Cucumber Chana Dal Sabzi, soak the channa Dal in 2-1/2 cups of water for half an hour.While the Chana dal is soaking we will cook the \u00a0mangalore cucumber in the pressure cooker.", "Place the cut mangalore cucumber in the pressure cook, with 1/4 cup of water, sprinkle some salt and a pinch of turmeric powder.", "Pressure cook for 2 whistles and turn off the heat.", "Once the pressure releases, transfer to a bowl and keep aside.Next we will cook the chana dal in the same pressure cooker.", "Place the channa dal along with the soaked water and the remaining ingredients.", "Cover the pressure cooker, place the weight on and pressure cook for a couple of whistles.After the two whistles, turn the heat to low and simmer for another 3 to 4 minutes and turn off the heat.", "Allow the pressure to release naturally.", "You can see the Video Recipe of How to cook lentils in a pressure cooker.Once the pressure is released, open the cooker and stir in the cooked mangalore cucumber.", "Check the salt and spices and adjust to suit your taste.The next step is to make the seasoning for the Mangalore cucumber channa dal.", "Heat a small pan with a teaspoon of oil; add the cumin seeds, a pinch of red chili powder and red chilies.", "Roast for a couple seconds and turn off the heat.Pour the seasoning into the mangalore cucumber Chana Dal, stir in the chopped coriander leaves and serve warm.Serve the Mangalore Cucumber Chana Dal Sabzi Recipe along with\u00a0phulka, raita and\u00a0jeera rice\u00a0to make it a complete meal."]'::jsonb, 40, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Mangalore_Cucumber_Chana_Dal_Subzi_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/96.Mangalore_Cucumber_Chana_Dal_Subzi_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chole Capsicum Masala Recipe', 'chole-capsicum-masala-recipe', 'Chole Capsicum Masala is a north Indian style chickpea preparation with capsicum. This cuisine is popular all over India. The chole / kabuli-chana and capsicum (here I have used the green capsicum) are cooked deliciously in a cashew-based curry. The unique flavour of capsicum lends itself really well in this masala curry. Often I made this as a side dish for roti / paratha / any pulao. So why to wait? Let’s go by detailed instructions mentioned below in order to make this delicious chole capsicum masala.', '["1 cup Kabuli Chana (White Chickpeas) , soaked and cooked until soft", "Green Bell Pepper (Capsicum) , diced", "2 Onions , finely chopped", "2 teaspoons Ginger Garlic Paste", "2 teaspoons Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "1/2 cup Cashew nuts", "1 cup Homemade tomato puree", "Oil , for cooking", "Salt , to taste"]'::jsonb, ARRAY['cashew nuts', 'tomato', 'cumin powder (jeera)', 'salt', 'red chilli powder', 'ginger garlic paste', 'kabuli chana (white chickpeas)', 'onion', 'green bell pepper (capsicum)', 'coriander powder', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'sunflower oil']::text[], '["To begin making the Chole Capsicum Masala recipe, soak cashew nuts in warm water for 12 to 15 minutes.Heat oil in a wok/kadai.", "Add sliced onions and cook until golden brown.Add garlic paste and saute for 1 minute.", "Next add the cubed capsicum pieces and saute for 2 to 3 minutes.Then add cumin powder, coriander powder, turmeric powder and chilli powder.", "Fry for a minute, taking care not to burn.Now add the tomato sauce/puree and boiled chickpeas along with 2 cups of water.Let this mixture come to boil and then simmer for 5 minutes until the flavours mix together.Meanwhile, make a paste of soaked cashew nuts.Add the cashew paste to the curry along with salt.", "Simmer for 4 to 5 minutes.Add kasoori methi, remove from flame and serve hot.Serve Chole Capsicum Masala along with\u00a0Kachumber Salad, Steamed Rice and\u00a0Phulkas\u00a0for a weekday meal."]'::jsonb, 70, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Sasmita/Chole_Capsicum_Masala.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/97.Chole_Capsicum_Masala.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karwar Style Valval Recipe (Mixed Vegetables In Coconut Milk)', 'karwar-style-valval-recipe-mixed-vegetables-in-coconut-milk', 'Karwar Style Valval Recipe (Mixed Vegetables In Coconut Milk) is a delicious creamy mixed vegetables curry cooked in coconut oil. It''s basically a no onion no garlic dish and is one of the comfort food in Karwar region. This simple dish with mild spice and lots of flavour will surely spice up your everyday food. It is easy to make and takes very few every day ingredients to prepare.', '["1 cup Green beans (French Beans) , Chopped", "1 Carrot (Gajjar) , chopped into small cubes", "1/2 Green peas (Matar) , chopped into small cubes", "1 Potato (Aloo) , chopped into small cubes", "1/2 Mangalorean cucumber , chopped into small cubes", "1 cup Pointed gourd (Parval) , slit", "5 Green Chillies , slit", "3 cups Coconut milk", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1-1/2 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chilli", "1 tablespoon Coconut Oil", "6 Curry leaves"]'::jsonb, ARRAY['green peas (matar) cubes', 'green beans (french beans)', 'mustard seeds', 'dry red chilli', 'mangalorean cucumber cubes', 'carrot cubes', 'curry leaves', 'cumin seeds (jeera)', 'coconut milk', 'coconut oil', 'green chillies', 'pointed gourd (parval)', 'potato (aloo) cubes']::text[], '["To begin making the Karwar Style Valval Recipe (Mixed Vegetables In Coconut Milk), boil all the vegetables - beans, carrot, peas, potato, mangalore cucumber, parval and green chilies in water.", "They should be done but not mushy, so don''t pressure cook.Add the coconut milk, salt and cook for another 5 to 6 minutes.", "Take off the heat.The next step is to prepare the tempering.", "Heat little coconut oil in a heavy bottomed pan.Add mustard and cumin seeds.", "When they start popping, add the red chilies and curry leaves.Pour the seasoning in the gravy and mix.", "Serve hot.", "Serve\u00a0Karwar Style Valval Recipe\u00a0(Mixed Vegetables In Coconut Milk)\u00a0along with\u00a0Whole Wheat Lachha Paratha\u00a0and\u00a0Beetroot Pachadi\u00a0for a weekday meal."]'::jsonb, 35, 'Coastal Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/Karwar_Style_Valval_Mixed_vegetables_in_coconut_milk.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/98.Karwar_Style_Valval_Mixed_vegetables_in_coconut_milk.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Senai Kizhangu Poriyal Recipe-Yam Poriyal Recipe', 'senai-kizhangu-poriyal-recipe-yam-poriyal-recipe', 'Senai Kizhangu Poriyal Recipe is a simple stir fry made South Indian style. A homemade curry powder made up of chana dal, split urad dal, coriander seeds, dry red chillies and tamarind is added to give this Yam Poriyal a delicious taste.', '["500 grams Elephant yam (Suran/Senai/Ratalu) , cut into thin 1/2 inch slices", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 teaspoon White Urad Dal (Split)", "2 Dry Red Chillies", "1/4 teaspoon Asafoetida (hing)", "2 sprig Curry leaves , torn", "1/2 teaspoon Turmeric powder (Haldi)", "3 tablespoons Coconut Oil", "1 tablespoon Chana dal (Bengal Gram Dal)", "1 tablespoon White Urad Dal (Split)", "2 tablespoons Coriander (Dhania) Seeds", "3 Dry Red Chillies , broken", "30 grams Tamarind"]'::jsonb, ARRAY['s elephant yam', 'suran/senai/ratalu', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'dry red chillies', 'asafoetida', 'hing', 'curry leaves', 'turmeric powder', 'haldi', 's coconut oil', 'chana dal', 'bengal gram dal', 's coriander', 'dhania', 's tamarind']::text[], '["To begin making Senai Kizhangu Poriyal Recipe first make the Curry Powder.Into a preheated pan on medium heat add chana dal, split white urad dal and roast the dals till they turn golden brown and crisp.", "Once done add coriander seeds, dry red chillies and roast for a minute.", "Finally add tamarind and saute for another few seconds and turn off the heat.Allow the mixture to cool.", "Once all the ingredients are cooled add them to a small jar of the mixer grinder and blend to make a coarse powder.", "Keep aside.Heat coconut oil in wok or a pan; once the oil is hot add mustard seeds and urad dal.", "Saute till the dal turn golden brown.Once done add broken red chillies, asafoetida and the curry leaves.", "Stir for a few seconds and add in the yam.Add the turmeric powder,the ground masala and salt to taste.", "Stir well to combine.Sprinkle a little\u00a0 water,\u00a0 cover the pan and cook the Senai Kizhangu Poriyal on medium heat till the yam is cooked completely.This will take about 10 minutes.", "Ensure that your stir the Senai Kizhangu Poriyal once or twice to cook all the yam evenly.", "Sprinkle more water if required.Once cooked give the\u00a0Senai Kizhangu Poriyal a final stir and transfer it to a serving bowl and serve hot.Serve Senai Kizhangu Poriyal Recipe with\u00a0Kollu Rasam\u00a0,\u00a0Rice With Quinoa\u00a0and\u00a0Elai Vadam\u00a0for a nourishing and tasty diabetic meal."]'::jsonb, 25, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Senai_Chenai_Kizhangu_Poriyal_Recipe_Video_5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/99.Senai_Chenai_Kizhangu_Poriyal_Recipe_Video_5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Uttarkhand Style Mixed Bhaddu Dal Recipe', 'uttarkhand-style-mixed-bhaddu-dal-recipe', 'Uttarakhand is my favourite summertime holiday spot, and we never miss it. Apart from being a popular tourist destination it similarly shares a popular vegan cuisine. A high protein vegan recipe is a must make for every family which is simply cooked and it helps in digestion especially when you are travelling. Bhaddu is actually an alloy pot they use to soak and cook the lentils for long hours. Hence the name and the local addition of selective ingredients and exploring on making tasty protein meal is highly praised by all.', '["1/4 cup Rajma (Large Kidney Beans)", "1/4 cup White Urad Dal (Split)", "3 teaspoon Oil", "1 teaspoon Ginger Garlic Paste", "2 Cardamom (Elaichi) Pods/Seeds", "1 Bay leaf (tej patta)", "1/4 teaspoon Whole Black Peppercorns", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1/4 teaspoon Coriander (Dhania) Seeds", "1/2 cup Homemade tomato puree", "1/4 teaspoon Cumin seeds (Jeera)", "2 teaspoon Fresh cream", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'cardamom (elaichi) podsseeds', 'bay leaf (tej patta)', 'black peppercorns', 'ginger garlic paste', 'white urad dal (split)', 'coriander (dhania) seeds', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'rajma (large kidney beans)', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Uttarkhand Style Mixed Bhaddu Dal recipe, firstly soak the urad dal and rajma seperately overnight or for minimum 5 hours.Heat a pressure cooker with water, cinnamon stick, cardamom and lentils, cover it and let it cook till the cooker releases 4 whistles.", "Take a medium wok, heat 2 teaspoons of oil, add bay leaf, cloves, whole black pepper, turmeric powder and red chilli powder.", "Let it cook for about a minute.", "Pour tomato puree and let it cook for another 3 minutes.", "After 3 minutes, add in the ginger garlic paste.", "Let it cook till the raw smell vanishes.Next, add the boiled dal to wok and simmer for 8 minutes then add the cream.Meanwhile heat a spoonful of oil in a tadka pan, add coriander seeds, cumin seeds and let it cook for about 15 seconds.", "Pour it over the dal, mix and serve hot.Serve\u00a0Uttarkhand Style Mixed Bhaddu Dal along with\u00a0Bharwa Bhindi\u00a0and\u00a0Tawa Paratha\u00a0for your weekly meal plan."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/ruby_pathak-yahoo.com/Uttarkhand_Style_Mixed_Bhaddu_Dal.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/100.Uttarkhand_Style_Mixed_Bhaddu_Dal.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thouthe Kodel Recipe (Mangalore Southekayi Curry)', 'thouthe-kodel-recipe-mangalore-southekayi-curry', 'Thouthe Kodel Recipe is a very traditional Mangalorean recipe that is made from a special cucumber that is available in Karnataka. The Thouthe Kodel is supposed to have a rich red color that it gets from the dry byadgi red chillies, but you can use regular dry red chillies as well, like I did. By using the regular red chillies, the color of the curry will not be rich red. The curry also gets its full-bodied flavor from the roasted condiments like fenugreek, coriander, cumin that is ground along with garlic and coconut making the Thouthe Kodel rich, flavorful and delicious.', '["1 Mangalorean cucumber , deseeded, cut into wedges with skin", "2-1/2 cups Tamarind Water", "1/2 cup Arhar dal (Split Toor Dal)", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Oil , for cooking", "Ingredients to be ground to paste", "1 tablespoon Coriander (Dhania) Seeds", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon White Urad Dal (Split)", "1/2 teaspoon Whole Black Peppercorns", "1 cup Fresh coconut , grated", "3 Dry Red Chillies , (byadagi", "2 cloves Garlic", "Ingredients for seasoning", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "2 Dry Red Chillies", "2 cloves Garlic", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'arhar dal (split toor dal)', 'dry red chillies (byadagi', 'tamarind water', 'coconut', 'mustard seeds', 'black peppercorns', 'cloves garlic', 'curry leaves', 'white urad dal (split)', 'coriander (dhania) seeds', 'mangalorean cucumber', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'dry red chillies', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Thouthe Kodel Recipe (Mangalore Cucumber Curry); we will first cook the toor dal in the pressure cooker until soft and mushy.", "Place the toor dal in the pressure cooker along with 1-1/2 cups of water, turmeric powder and salt.Cover the pan, pressure cook until you hear one whistle.", "After the first whistle, turn the heat to low and simmer the dal for about 3 to 4 minutes.", "After 3 to 4 minutes, turn off the heat.", "Allow the pressure to release naturally, as the dal will continue to cook in the pressure cooker under pressure.", "Once done, whisk the dal until smooth and keep aside.The next step is to cook the Mangalore Cucumber (Touthe) along with the tamarind water.", "Place the cut Mangalore Cucumber (Touthe) and the tamarind water in the pressure cooker.Add salt and cover the pressure cooker with its weight on.", "Allow it to pressure cook until you heat 2 to three whistles.", "After the whistles, turn off the heat.", "Place the pressure cooker under cold running water to release the pressure immediately.", "Cucumber cooks very fast, so its important to release the pressure immediately, so it does not become mushy.The next step is to make the Masala for the Mangalore Cucumber Curry (Touthe).", "In small pan; dry roast the coriander seeds, cumin seeds, urad dal, fenugreek seeds, pepper corns and red chillies until you can smell the roasted aromas coming through.Place the roasted ingredients along with the coconut and garlic into a food processor and blend to make a smooth paste.The final step is to combine all the ingredients.", "In a large sauce pan; add in the cooked and whisked dal, the cucumber tamarind curry and the masala paste.", "Stir well to combine all the ingredients.", "Place the sauce pan on medium heat and give the Thouthe Kodel a boil.", "Once it begins to boil, turn the heat to low and simmer until we get the seasoning ready.To prepare the seasoning for the Thouthe Kodel; heat oil in a small pan; add all the seasoning ingredients.", "Allow the seeds to crackle and roast.", "Stir for a couple of seconds until you can smell the aromas coming through.Add the seasoning to the simmering Thouthe Kodel and give it a stir.", "Transfer the Thouthe Kodel (Mangalore Cucumber Curry) to a serving bowl and serve it along with warm steamed rice or Neer Dosa."]'::jsonb, 70, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Mangalorean_Thouthe_Kodel_Cucumber_Curry_Recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/101.Mangalorean_Thouthe_Kodel_Cucumber_Curry_Recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Murg Badami Recipe - Chicken In Almond Gravy', 'murg-badami-recipe-chicken-in-almond-gravy', 'Murg Badami is an almond based gravy dish which is made with almond and poppy seeds paste, flavored with cardamom powder and whole spice powder. This is an easy but creamy and spicy gravy based chicken recipe.', '["1 kg Chicken", "30 Whole Almonds (Badam) , blanched", "2 Onions , chopped roughly & made to paste (4 tablespoons needed)", "1-1/2 tablespoons Ginger Garlic Paste", "2 teaspoons Red Chilli powder", "4 Dry Red Chillies", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "4 tablespoon Poppy seeds , soaked", "2 Cinnamon Stick (Dalchini)", "6 Cloves (Laung)", "1 Bay leaf (tej patta)", "1 tablespoon Cardamom Powder (Elaichi)", "1 teaspoon White pepper powder", "1/4 teaspoon Cumin seeds (Jeera)", "1 cup Curd (Dahi / Yogurt)", "4 tablespoons Ghee", "1 tablespoon Fresh cream , (optional)", "Coriander (Dhania) Leaves , for garnishing"]'::jsonb, ARRAY['salt', 'white pepper powder', 'bay leaf (tej patta)', 'ghee', 'coriander (dhania) leaves', 'red chilli powder', 'ginger garlic paste', 'curd', 'dry red chillies', 'badam (almond)', 'chicken', 'poppy seeds', 'onion paste ( needed)', 'cinnamon stick (dalchini)', 'cardamom powder (elaichi)', 'cumin seeds (jeera)', 'turmeric powder', 'cloves (laung)']::text[], '["To prepare Murg Badami Recipe, get prep with all the ingredients needed.Put the cleaned chicken into a large bowl, add curd, ginger, garlic paste, half of the red chili powder, salt and turmeric powder.", "Mix well and keep aside for 1/2 \u00a0hour to marinate.Peel the blanched almonds.", "Finely slice 5 almonds & reserve them to garnish.In a wide thick bottomed pan, dry roast cloves, white peppercorns, red chillies, cinnamon, cumin seeds, cool and grind to a fine powder.In a mixer, grind together soaked poppy seeds and blanched almonds, make a smooth, fine paste.Heat ghee in a heavy bottom pan and add onion paste.", "Saute till lightly browned and the raw smell disappears.Add bay leaf and marinated chicken, remaining red chili powder and ground powder, mix well, turn the heat to simmer, cover and cook for 5 minutes.Add ground almond mixture and a glass of water, cover and cook for 10 minutes.Add cream, mix well, switch off the gas.", "Garnish with almonds slivers and coriander.Serve\u00a0Murg Badami Recipe with\u00a0Lachha Paratha Recipe, and\u00a0Kachumber Salad Recipe With Cucumber, Onion & Tomatoes\u00a0for a complete meal."]'::jsonb, 95, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/hema/Murg_Badami_original1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/102.Murg_Badami_original1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Poosanikai Haddu Sweet Curry Recipe - Pumpkin Sweet Curry', 'poosanikai-haddu-sweet-curry-recipe-pumpkin-sweet-curry', 'Pumpkin Sweet Curry Recipe is a South Indian Vegetarian Curry recipe prepared with yellow pumpkin also known as Haddu or Poosanikai.', '["250 grams Kaddu (Parangikai/ Pumpkin) , diced", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 teaspoon White Urad Dal (Split)", "2 Dry Red Chillies", "1 sprig Curry leaves", "1 tablespoon Jaggery", "1/4 cup Fresh coconut , grated", "2 teaspoons Oil", "Salt , to taste", "Water , as needed"]'::jsonb, ARRAY['s kaddu', 'parangikai/ pumpkin', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'dry red chillies', 'curry leaves', 'jaggery', 'fresh coconut', 's oil', 'salt', 'water']::text[], '["To begin making the\u00a0Pumpkin Sweet Curry Recipe, we need to first prepare all the ingredients.", "In a heavy bottomed pan, add 2 teaspoons of oil.", "Once the oil is hot, add mustard seeds.", "When it crackles add urad dal, tear in the red chillies and curry leaves.", "Saute it till urad dal turns golden brown.Next add the diced pumpkin/haddu, salt and enough water to coat the bottom of the pan.", "This will ensure that the bottom does not burn and the pumpkin gets cooked.", "Cover the pan with a lid and cook for 5 to 10 minutes in a medium flame.", "Keep stirring in between so that you can check for doneness and check the level of water.", "Once the poosanikai/haddu is cooked, add 1 tablespoon of jaggery.", "Stir all the ingredients well until the jagger melts.", "Finally add grated coconut and mix it well.", "Turn off the heat and Pumpkin Sweet Curry is ready to be served.", "Serve Pumpkin Sweet Curry Recipe along with Steamed Rice and Mixed Vegetable Sambar Recipe for a complete South Indian meal."]'::jsonb, 30, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/aishchitra-gmail.com/Parangikkai__inipu__curry___Yellow_pumpkin_sweet_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/103.Parangikkai__inipu__curry___Yellow_pumpkin_sweet_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kathirikai UrulaiKizhanghu Pachidi Recipe (Brinjals And Potatoes With Moong Dal)', 'kathirikai-urulaikizhanghu-pachidi-recipe-brinjals-and-potatoes-with-moong-dal', 'Kathirikkai Urulaikizhanghu is a Chettinad delicacy prepared by cooking tender Brinjals and Potatoes with moong dal. It can be served as an accompaniment with idli, dosa, and chapatti. It is a versatile dish which can be served over plain rice. The dish is mildly spicy with only green chilies added and can be prepared with the common pantry items, thus making it as favourite for people of all ages and taste.', '["1/2 cup Yellow Moong Dal (Split)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 cup Shallots , finely chopped", "1 Tomato , finely chopped", "1/2 cup Brinjal (Baingan / Eggplant) , cubed (use smaller brinjals for elevated taste)", "1/2 cup Potatoes (Aloo) , cubed", "3 Green Chillies , finely chopped", "1/2 teaspoon Salt", "Coriander (Dhania) Leaves , Handful for garnish", "2 tablespoons Oil", "Curry leaves , Handful", "2 Dry Red Chillies", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)"]'::jsonb, ARRAY['tomato', 'salt', 'yellow moong dal (split)', 'coriander (dhania) leaves', 'mustard seeds', 'brinjal (baingan eggsplant) (use smer brinjals elevated )', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'potato (aloo)', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Kathirikai UrulaiKizhanghu Pachidi recipe, firstly soak moong dal for 15 minutes.Wash them with water and pressure cook the dal with 1/4 teaspoon of turmeric powder in a pressure cooker and 2 cups of water for 3 whistles.Allow the pressure to settle down and mash them into a paste with a ladle.", "Set aside.In a medium sized saucepan/pot, add oil and heat over medium flame.When the oil is hot, add the tempering ingredients and fry until the mustard seeds splutter.", "Fry until urad dal is golden.Gently add onions and cook until they become translucent.", "Add tomatoes, green chilies and turmeric powder.", "Saute till the tomatoes become mushy.Now, add potatoes, brinjals and stir the well.", "Cook over reduced flame until the brinjals and potatoes become tender.Add dal and combine well so that they are blended together.Add 1-2 cups of water and mix well.", "Add water according to your required consistency.Season it with salt.", "When the mixture is about to boil, simmer the flame and cook for about 5 minutes.Switch off the flame and add coriander leaves for garnish.", "Prepare this Kathirikai UrulaiKizhanghu Pachidi and serve with rice along with authentic sambar for a delicious meal."]'::jsonb, 45, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Kathirikai_UrulaiKizhanghu_Pachidi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/104.Kathirikai_UrulaiKizhanghu_Pachidi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Jowar Bajra Garlic Roti Recipe', 'jowar-bajra-garlic-roti-recipe', 'Jowar Bajra Garlic Roti is a healthy breakfast or lunch recipe made with Jowar flour also known as Sorghum flour, Bajra flour and garlic powder for flavouring (you can also use finely minced garlic). This roti is a Diabetic friendly recipe as it contains millet flours are known to be made of complex carbohydrates - which means the release of sugar to the system will be slow which aids in managing diabetes.', '["1/2 cup Jowar Flour (Sorghum)", "1/2 cup Bajra Flour ( Pearl Millet)", "4 cloves Garlic , finely chopped", "2 teaspoons Black pepper powder", "Salt , as per your taste", "Water , for kneading the dough"]'::jsonb, ARRAY['salt', 'water the dough', 'jowar flour (sorghum)', 'cloves garlic', 'black pepper powder', 'bajra flour ( pearl millet)']::text[], '["To begin making\u00a0Jowar Bajra Garlic Roti, in a bowl mix jowar flour and bajra flour.Add garlic, pepper powder and salt to it.", "Mix all the ingredients well.Add water little by little and knead into soft dough.Divide into small balls and roll it flat with a rolling pin dusting some flour if required.Heat a roti tawa and place the rolled out Jowar Bajra Garlic Roti.Cook the Jowar Bajra Garlic Roti on a medium flame turning both the sides until brown spots appear.", "Take it off the griddle, add a teaspoon of ghee on top of the roti.", "Finish the rest of the rotis and your Jowar Garlic Roti is ready to be served.", "Serve\u00a0Jowar Bajra Garlic Roti Recipe along with Mixed Vegetable Kurma\u00a0for breakfast.You can even serve the\u00a0Jowar Bajra Garlic Roti for a Healthy\u00a0lunch along with Horsegram Dal Recipe - Kulith/Kollu Dal and Raw Jackfruit & Peanut Masala Poriyal Recipe With Sambar Powder for a healthy Diabetic friendly meal."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swathynandhini/JOWAR_BAJRA_GARLIC_ROTI_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/105.JOWAR_BAJRA_GARLIC_ROTI_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Coorg Style Kumbala Curry Recipe (Pumpkin Sabzi)', 'coorg-style-kumbala-curry-recipe-pumpkin-sabzi', 'Coorg Kumbala Curry Recipe (Pumpkin Sabzi) is an authentic dish from Coorg where in diced pumpkins are simmered in a coconut base resulting in a creamy, mildly spicy, tasty curry. The mild flavor of Cumin seeds and garlic enhances the flavor of the curry. Serve Coorg Kumbala Curry Recipe (Pumpkin Sabzi) with Akki Rotti Recipe (Spicy Gluten Free Rice Flour Flat Breads ) and steamed rice.', '["250 gram Kaddu (Parangikai/ Pumpkin)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "To grind", "1/4 cup Fresh coconut , grated", "1/2 teaspoon Cumin seeds (Jeera)", "3 Green Chillies", "1 tablespoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "8 Curry leaves", "2 Dry Red Chillies , broken", "2 Dry Red Chillies , broken"]'::jsonb, ARRAY['salt', 'coconut', 'mustard seeds', 'gram parangikai pumpkin', 'curry leaves', 'dry red chillies', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making Coorg Kumbala Curry Recipe (Pumpkin Sabzi), Scoop out the seeds from the pumpkin and dice it into cubes.", "Retain the skin\u00a0Add turmeric,salt and Place the pumpkin in a pan and pour around 2 cups of water, to immerse pumpkins completely.", "Cook on a medium heat, covered.Meanwhile in a grinder, grind the ingredients mentioned to be ground- to a smooth paste.", "Add a little water to grind along.Once pumpkin in the pan is almost cooked, add the ground masala and mix.", "Simmer for another 3 mins.", "Remove from heat.Prepare the tempering by heating oil in a small pan.", "Once the oil is hot, add the mustard seeds on a medium heat.When they splutter, add the curry leaves, dried red chilies and garlic, stir till garlic is done, and pour the tadka over the pumpkin curry.Serve\u00a0Coorg Kumbala Curry Recipe (Pumpkin Sabzi) with\u00a0Akki Rotti Recipe (Spicy Gluten Free Rice Flour Flat Breads )\u00a0and steamed rice."]'::jsonb, 30, 'Coorg', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/Coorgi_Pumpkin_Curry_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/106.Coorgi_Pumpkin_Curry_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Burnt Garlic Veg Fried Rice Recipe', 'burnt-garlic-veg-fried-rice-recipe', 'Burnt Garlic Veg Fried Rice Recipe has a very distinct, slightly bitter and nutty flavor. It blends itself very well with the Chinese sauces and Vegetables. This burnt garlic Vegetarian fried rice will become a favorite at home. So easy to put together and ready in under 30 minutes, this dish is perfect for weekday dinners in itself or served with a light Chinese gravy. You can add any assortment of vegetables into the rice to keep it healthy and nutritious.', '["1 cup Cooked rice", "2 Carrot (Gajjar) , diced", "1 Green bell peppers , diced", "1 Red Bell pepper (Capsicum) , diced", "1 Onion , chopped", "1 inch Ginger , chopped", "4 cloves Garlic , chopped", "2 tablespoons Red Chilli sauce", "2 tablespoons Green Chilli Sauce", "1/2 teaspoon Chilli vinegar", "1/2 teaspoon Whole Black Peppercorns , crushed", "Salt , to taste", "3 sprig Spring Onion Greens , for garnish", "Oil", "9 cloves Garlic , diced", "1 teaspoon Oil"]'::jsonb, ARRAY['salt', 'green bell peppers', 'red bell pepper (capsicum)', 'ginger', 'rice', 'spring onion greens', 'cloves garlic', 'carrot', 'green chilli sauce', 'chilli vinegar', 'black peppercorns', 'onion', 'red chilli sauce', 'sunflower oil']::text[], '["To begin making the Burnt Garlic Veg Fried Rice Recipe, pressure cook the rice in a pressure cooker with\u00a0 2 cups of water for about 2 whistle and switch it off.Heat a wok with oil, add garlic, ginger and allow it to soften.", "Add onions and saute till they turn translucent.Add carrot and cook for about 10 minutes till the carrot soften.", "Add all the bell peppers and saute till they become soft.Add all the Chinese sauces along with salt and pepper.", "Mix well, add your cooked rice into the wok and stir fry them till the rice is well coated.Check for salt and sprinkle with spring onions and give one last toss.In a small pan, heat the oil and add the diced garlic.", "Fry till they turn deep brown in color.", "Pour half the burnt garlic in the rice and mix well.Just before serving, garnish with the rest of burnt garlic and spring onions.Serve the Burnt Garlic Veg Fried Rice Recipe along\u00a0Chinese chicken Manchurian\u00a0and\u00a0salad\u00a0to enjoy your Sunday lunch."]'::jsonb, 40, 'Indo Chinese', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Burnt_Garlic_Veg_Fried_Rice_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/107.Burnt_Garlic_Veg_Fried_Rice_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karwar NKGSB Style Bharli Vangi Recipe - Brinjal Curry', 'karwar-nkgsb-style-bharli-vangi-recipe-brinjal-curry', 'Karwar NKGSB Style Bharli Vangi Recipe - Brinjal Curry is what stuffed brinjals vegetable is called in Konkani language and in Hindi it’s called Bharwa Baingan. Vangi or Brinjals are of different types like the small black ones, or the surati vangi, or white vangi or the ones I have used here i.e. Kateri Vangi. The Kateri vangi are a little big in size with a slightly purplish colour like stripes and are sweet in taste. These are generally used to make the Bharli Vangi.', '["6 Brinjal (Baingan / Eggplant)", "2 Potato (Aloo)", "1-1/2 Onion , finely chopped", "1 cup Fresh coconut , grated", "1/2 teaspoon Turmeric powder (Haldi)", "3/4 teaspoon Tamarind", "3 cloves Garlic", "1/2 inch Ginger", "2 tablespoons Jaggery", "1 teaspoon Gram flour (besan)", "1/4 cup Coriander (Dhania) Leaves , chopped", "Salt , to taste", "Whole spices to be roasted", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 Cardamom (Elaichi) Pods/Seeds", "2 Whole Black Peppercorns", "3 Byadagi Dried Chillies", "1 tablespoon Oil", "1 Onion , thinly sliced", "1 cup Fresh coconut , grated", "1 tablespoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)", "1 sprig Curry leaves"]'::jsonb, ARRAY['coriander (dhania) leaves', 'brinjal (baingan eggsplant)', 'asafoetida (hing)', 'jaggery', 'cloves garlic', 'black peppercorns', 'curry leaves', 'onion', 'turmeric powder', 'sunflower oil', 'salt', 'cardamom (elaichi) podsseeds', 'tamarind', 'coconut', 'mustard seeds', 'ginger', 'potato (aloo)', 'gram flour (besan)', 'byadagi dried chillies', 'cinnamon stick (dalchini)', 'cloves (laung)']::text[], '["To begin making the Karwar NKGSB Style Bharli Vangi Recipe - Brinjal Curry, firstly wash the brinjals thoroughly with water.Cut off the stem and make two semi slits in it from the top to get a + sign.", "This is for stuffing the masala.", "Immerse in sufficient water till use.", "Cut the potatoes into thick wedges or large chunks and immerse in sufficient water.Next, heat a small kadhai and add the oil.", "Add to it the mentioned whole spices including cloves, cardamom, cinnamon stick, whole black peppercorns, byadgi red chillies and roast a little till they splutter.", "Remove from heat and set aside to cool.Heat some oil in the same pan, add sliced onions and saute till they turn soft and transparent.Now add the coconut and roast for a while.", "As soon as the coconut browns a little, switch off the flame and set aside to cool.Grind together the roasted onion coconut mixture, the roasted whole spices, ginger, garlic, tamarind and jaggery in the end using sufficient water to get a thick paste.Mix the besan in the above mixture.", "It helps in thickening the gravy.Add the turmeric powder, chopped onions and salt as well, to the above mixture.", "Add some chilli powder if desired.Stuff the vaangi (baingan) with this masala and keep them aside.Heat a pressure cooker and add the oil to it.", "Add the mustard seeds.", "When they splutter add the asafoetida and the curry leaves.After 20 seconds, add the stuffed brinjals, potatoes and the remaining masala.", "Stir a little.Add water almost upto the level of the vegetable.", "Close lid and cook for 3 whistles on high flame or if cooking in a saucepan, cook adding hot water as required.When the brinjals and potatoes are well cooked and the gravy has thickened, transfer to a serving bowl and garnish with chopped coriander.Serve\u00a0Karwar NKGSB Style Bharli Vangi Recipe - Brinjal Curry along with\u00a0Vali Bhaji Ambat\u00a0and\u00a0Steamed Rice\u00a0for a weekday meal with your family."]'::jsonb, 75, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/panditp253-gmail.com/Bharli_Vangi_Recipe-_Karwar_NKGSB_Style_Brinjal_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/108.Bharli_Vangi_Recipe-_Karwar_NKGSB_Style_Brinjal_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dal Bukhara Recipe (Punjabi Style Black Urad Dal)', 'dal-bukhara-recipe-punjabi-style-black-urad-dal', 'Dal Bukhara is a classic Punjabi style curry made from whole black urad dal which is creamy and melts in the mouth. This Dal Bukhara tastes awesome with rice or roti. Simmer this dal on a slow flame for a long time till you get the creamy texture which is the key to this dal Bukhara.', '["1 cup Black Urad Dal (Whole) , soaked overnight", "1 Onion , finely chopped", "3 Tomatoes , pureed", "1 Ginger Garlic Paste", "2 Green Chillies", "2 tablespoon Butter (Salted)", "1 teaspoon Cumin seeds (Jeera)", "1 Kasuri Methi (Dried Fenugreek Leaves)", "Salt , to taste", "1 teaspoon Red Chilli powder", "1 teaspoon Chaat Masala Powder", "1 teaspoon Garam masala powder", "1 teaspoon Cumin powder (Jeera)", "1/4 cup Fresh cream"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'chaat masala powder', 'red chilli powder', 'ginger garlic paste', 'onion', 'cumin seeds (jeera)', 'kasuri methi (dried fenugreek leaves)', 'black urad dal', 'green chillies', 'butter', 'garam masala powder']::text[], '["To begin making the Dal Bukhara recipe, pressure cook the black grams with required cups water till done.", "Remove and mash the dal mixture.Heat butter in a heavy bottomed\u00a0pan.", "Splutter cumin and bay leaf.", "Add onions, green chilli, ginger garlic paste and saute till light brown.Add tomato puree and salt.", "Mix everything well and cook for about 3 to 5 minutes.After 3 to 5 minutes, add all the spice powder including\u00a0Kasuri methi, red chilli powder, chaat masala, cumin powder, turmeric powder and cook for two minutes.After 2 minutes, add the dal mixture, required the amount of water and let it simmer for few minutes.Finally, add garam masala powder and cream and cook for 2 to 3 minutes.", "Serve hot.Serve\u00a0Dal Bukhara along with\u00a0Bharma Baingan\u00a0and\u00a0Phulka\u00a0for a weekday meal."]'::jsonb, 80, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/Dal_bukhara_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/109.Dal_bukhara_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karwar Style Dali Ambat Ani Maska Sang Recipe-Toor Dal & Drumsticks Pod Curry', 'karwar-style-dali-ambat-ani-maska-sang-recipe-toor-dal-drumsticks-pod-curry', 'Karwar Style Dali Ambat Ani Maska Sang Recipe-Toor Dal and Drumsticks Pod Curry  is a staple dish made with drumstick pods cooked in a creamy dal curry. The dal is pressure cooked and then simmered with spices and the drumstick pods.', '["1/2 cup Arhar dal (Split Toor Dal)", "1 teaspoon Coriander (Dhania) Seeds", "2 Dry Red Chilli", "1 cup Fresh coconut , grated", "1 Drumstick , cut into 1-inch pieces", "1 teaspoon Jaggery , grated", "3 Kokum (Malabar Tamarind)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'arhar dal (split toor dal)', 'coconut', 'kokum (malabar tamarind)', 'jaggery', 'drumstick', 'dry red chilli', 'coriander (dhania) seeds']::text[], '["To begin making the Karwar Style Dali Ambat Ani Maska Sang Recipe-Toor Dal and Drumsticks Pod Curry\u00a0by pressure cooking the toor dal in a pressure cooker with 1 1/2 cup of water for about 4 whistles.", "Release the pressure naturally.Dry roast the coriander seeds and dry chillies in a small skillet without oil till it becomes brown, once done set aside to cool.", "Now in a mixer, grind the roasted coriander seeds, dry red chillies along with coconut to a smooth paste and set aside.", "We will also mash the dal into a smooth paste, add 1 cup water and drumstick pods, cook till the pods are soft.This will take about 10 minutes.", "Transfer the coconut mixture to the dal and simmer it for 10 more minutes.", "Add kokum rind and jaggery and cook it again till it combines and Dali Ambat comes together.", "Serve the\u00a0Karwar Style Dali Ambat Ani Maska Sang Recipe-Toor Dal and Drumsticks Pod Curry\u00a0along with\u00a0steam rice\u00a0and\u00a0Manga Rasam Recipe\u00a0to enjoy a\u00a0weekend Meal."]'::jsonb, 45, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Karwar_Style_Dali_Ambat_Ani_Maska_Sang_Recipe_Toor_Dal_and_Drumsticks_Pod_Curry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/110.Karwar_Style_Dali_Ambat_Ani_Maska_Sang_Recipe_Toor_Dal_and_Drumsticks_Pod_Curry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Amrood Ni Kari Recipe (Parsi Style Dry Guava Curry Recipe)', 'amrood-ni-kari-recipe-parsi-style-dry-guava-curry-recipe', 'Amrood Ni kari ( Parsi Style Dry Guava Curry) is a twist to the normal Indian subzis that use vegetables. In this recipe, we have incorporated spice into the guava fruit by making it as a curry. The guavas are pressure cooked so that we get soft but still a firm texture.', '["2 Guava , ripe and diced", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Asafoetida (hing)", "1 tablespoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Turmeric powder (Haldi)", "1 tablespoon Jaggery , powdered", "Salt , to taste", "Oil , for cooking"]'::jsonb, ARRAY['uava', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing', 'red chilli powder', 'coriander powder', 'dhania', 'turmeric powder', 'haldi', 'jaggery', 'salt', 'oil']::text[], '["We begin making the Amrood Ni Kari Recipe (Parsi Style Dry Spiced Guava Curry Recipe) by heating a pressure cooker with oil, temper the mustard seeds and asafoetida.Let the seeds splutter for some time.Later add the cut guava and shallow fry them, add the remaining spice and 1 cup of water.", "Adjust salt and check for seasoning .Cover and let it cook till the guava\u2019s are soft.You can cook the guava''s in the pressure cooker for about 3 whistles.", "Once done let the pressure release naturally.Serve your sweet and spicy Guava Ni Kari Recipe (Parsi Style Spiced Guava Curry Recipe) along with hot  lunch meal."]'::jsonb, 45, 'Parsi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/oct-17/Amrood_Ni_kari_Recipe_Parsi_Style_Dry_Guava_Curry_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/111.Amrood_Ni_kari_Recipe_Parsi_Style_Dry_Guava_Curry_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pepe Ghonto Recipe -Bengali Style Raw Papaya Sabzi', 'pepe-ghonto-recipe-bengali-style-raw-papaya-sabzi', 'Pepe Ghonto Recipe is the Bengali Style Raw Papaya Sabzi made with grated green and raw papaya and cubed potato. With added roasted peanuts, raisins and a dash of spices. This is an easy sabzi that can be included in a weeknight dinner or for lunch boxes.', '["1 Raw papaya , grated", "1 Potato (Aloo) , cubed", "10 Moong bori (dried lentil dumplings)", "1 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Coriander Powder (Dhania)", "2 Dry Red Chillies , (adjust to spice and taste preference)", "2 Bay leaves (tej patta)", "1 Cardamom (Elaichi) Pods/Seeds", "1 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1/2 tablespoon Roasted Peanuts (Moongphali)", "1/2 tablespoon Sultana Raisins", "3 tablespoons Mustard oil", "1/2 tablespoon Ghee", "1/2 teaspoon Garam masala powder", "1 teaspoon Sugar", "Salt , to taste"]'::jsonb, ARRAY['raw papaya', 'potato', 'aloo', 'moong bori', 'dried lentil dumplings', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'dry red chillies', 'bay leaves', 'tej patta', 'cardamom', 'elaichi', 'laung', 'cinnamon stick', 'dalchini', 'roasted peanuts', 'moongphali', 'sultana raisins', 's mustard oil', 'ghee', 'garam masala powder', 'sugar', 'salt']::text[], '["To begin making Pepe Ghonto Recipe -Bengali Style Raw Papaya Potato Sabzi, soak the raisins in a bowl with little water and keep aside .Dissolve the turmeric powder and coriander powder in a little water to form a paste.Heat 1 tbsp oil in a kadai/deep frying pan, fry the peanuts, keep aside on an oil absorbent paper.In the same add a dash of oil if required, fry the boris until golden in color.", "Remove from the oil, keep aside on an absorbent towel to drain the excess oil.In the same oil, fry the potatoes until golden brown in color.", "Remove from the oil, keep aside on an absorbent towel.Add the remaining oil, add\u00a0 the bay leaves, dry red chillies, crushed cinnamon, cardamom and cloves.", "When the spices start releasing their aroma, add in the turmeric-coriander paste and saute for 3-4 minutes.Now add in the grated papaya and salt to taste, cover and cook over a medium flame.", "The papaya shall release a lot of water, so no need to add in any water.Stir occasionally, add a splash of water only in case it is becoming too dry and the papaya is sticking to the bottom of the kadai.When papaya is about 75% cooked, add the potatoes, raisins and peanuts.Continue to cook over a medium flame till the papaya and potatoes are perfectly cooked, adding a splash of water whenever needed. (Take care that the papaya is just cooked and doesn''t become mushy.)Add the sugar, fried boris and adjust the seasonings.Mix well to combine, cook for a further 5 minutes.Finish with a dollop of ghee and a sprinkle of garam masala powder mix well and switch off.Serve Pepe Ghonto Recipe along with\u00a0phulka,\u00a0Bengali Style Cholar Dal Recipe\u00a0and\u00a0Kachumber Salad Recipe With Cucumber, Onion & Tomatoes\u00a0for a weekday lunch or dinner."]'::jsonb, 45, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/maumita.paulghosh-gmail.com/Pepe_Ghonto_Raw_Papaya_Dry_Curry_Bengali_Style.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/112.Pepe_Ghonto_Raw_Papaya_Dry_Curry_Bengali_Style.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gawar Ki Sabzi Recipe - Cluster Beans Curry', 'gawar-ki-sabzi-recipe-cluster-beans-curry', 'Gawar ki Sabji is a simple side dish which goes well with Rice or Roti. The addition of ajwain and combining it along with tomatoes and simple spices makes this dish stand out. This recipe uses a pressure cooker to make the Gawar Ki Sabzi, as a one pot dish - pressure cooking reduces the cooking time and gets done in 15 minutes from start to finish.', '["300 grams Gawar Phali (Kothavarangai / Cluster beans) , cleaned and cut into 1 inch pieces", "1 tablespoon Oil", "1 teaspoon Ajwain (Carom seeds)", "1 Onion , finely chopped", "2 Tomatoes , finely chopped", "3 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "2 teaspoon Coriander Powder (Dhania)", "1-1/2 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "4 sprig Coriander (Dhania) Leaves , as required, chopped for garnishing"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'ajwain (carom seeds)', 'red chilli powder', 'cloves garlic', 'coriander (dhania) leaves', 'gawar phali (kothavarangai cluster beans)', 'onion', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Gawar ki Sabzi, first heat oil in a pressure cooker\u00a0over medium heat.Add the ajwain seeds and allow it to crackle.Once it crackles, add the onion, ginger and garlic and saute until the onions become tender and pinkish brown.At this stage, add the tomatoes, turmeric powder, red chilli powder, coriander powder and saute until the tomatoes become mushy.Once the tomatoes become mushy, add the cut guar/ cluster beans, salt to taste and 1/4 cup of water.Pressure cook for 3 to 4 whistles and turn off the heat.", "Release the pressure immediately to retain the bright green colour of the gawar ki sabzi.Once opened, give the Gawar Ki Sabzi\u00a0 a stir and check the salt and spices and adjust accordingly.Transfer the\u00a0Gawar Ki Sabzi to a serving bowl and serve hot.Serve Gawar Ki Sabzi along with\u00a0Panchmel Dal,\u00a0Boondi Raita\u00a0and\u00a0Phulkas\u00a0for a weekday meal."]'::jsonb, 30, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Gavar_Ki_Sabji_Recipe_Cluster_Beans_Sabzi__2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/113.Gavar_Ki_Sabji_Recipe_Cluster_Beans_Sabzi__2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kori Gassi Recipe - Mangalorean Traditional Chicken Curry With Coconut Milk', 'kori-gassi-recipe-mangalorean-traditional-chicken-curry-with-coconut-milk', 'Kori Gassi Recipe  is a traditional Mangalorean chicken curry made with coconut milk. The delicious curry has a base of coconut and red chilli, an absolute classic from the coastal region of Mangalore. In Tulu language, Chicken is called Kori and Gassi is known as curry. This curry has a lovely blend of different fragrant spices, which is quite unique to Mangalorean cultural and heritage.', '["1 Onion , roughly chopped", "10 cloves Garlic , 10 cloves garlic", "12 Byadagi Dried Chillies , You can use 6 to 8 kashmiri chillies and 6 small red chillies)", "1 tablespoon Coriander (Dhania) Seeds", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "15 Whole Black Peppercorns", "Tamarind , lemon sized", "1 cup Fresh coconut , grated", "1 tablespoon Ghee", "1 kg Chicken , cut into medium curry cut pieces", "1 Onion , finely sliced", "Salt , to taste", "1/2 teaspoon Turmeric powder (Haldi)", "1 cup Coconut milk , thick", "1 cup Coconut milk , thin", "1 tablespoon Ghee", "1 inch Cinnamon Stick (Dalchini)", "3 Cloves (Laung)", "2 Cardamom (Elaichi) Pods/Seeds", "2 Curry leaves"]'::jsonb, ARRAY['byadagi dried chillies you can kashmiri chillies red chillies)', 'salt', 'chicken curry', 'coconut', 'ghee', 'cardamom (elaichi) podsseeds', 'black peppercorns', 'curry leaves', 'cloves garlic cloves garlic', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'cinnamon stick (dalchini)', 'coconut milk', 'turmeric powder', 'cloves (laung)', 'tamarind lemon']::text[], '["To begin making the Kori Gassi Recipe, \u00a0wash and cleanthe chicken pieces well.In a mixing bowl, combine the chicken pieces along with salt , mix well and set aside for 15 minutes.Soak the tamarind ball in a bowl of hot water for 10 minutes.In a heavy bottom pan, add 1 teaspoon ghee on low flame.", "Roast coriander seeds, cumin seeds, fenugreek seeds, dried red chillies, pepper corns one by one until fragrant.", "Be careful to roast on a low flame so as not to burn the spices.", "Once roasted turn off the flame,remove from the pan and set aside to cool.In the same pan, add sliced onions, garlic and roast until onions start to turn brown.", "Now add freshly grated coconut and continue to roast until coconut starts to turn golden brown.", "Remove from pan and set it aside.Squeeze out the water from the tamarind and discard the seeds.", "Once all the roasted spices and the onion-coconut mix has cooled, add them all to a blender and blend into a smooth paste along with the tamarind water.Now add remaining ghee/ coconut oil to the pan on medium-low flame, add the cinnamon, cardamoms, cloves and saute until fragrant.", "Add sliced onions and saut\u00e9 for a minute.Next add curry leaves, mix well.At this stage add\u00a0 Kori Gassi Masala along with turmeric and cook until oil separates from the sides of the pan.finally add the chicken pieces and give it a good mix so that the chicken is coated uniformly with the masala.", "Continue stirring for 5 minutes.", "Now add thin coconut milk and salt to taste, bring it to boil.Reduce flame to medium, cover and cook until chicken well done.", "Once the chicken is cooked well, add thick coconut milk, reduce to simmer.", "Cook for a minute or two and turn off the flame.", "Do not let the curry come to boil as the coconut milk might curdle.Traditionally it is served with Kori Rotti, a traditional and unique crispy flatbread made from rice flour.Serve Kori Gassi Recipe\u00a0along with Neer Dosa and Beetroot Pachadi for your weekday dinner."]'::jsonb, 60, 'Mangalorean', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/alaka_jena/Kori_Gassi_Mangalorean_Chicken_Curry_with_Coconut_milk_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/114.Kori_Gassi_Mangalorean_Chicken_Curry_with_Coconut_milk_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Sorakaya Kura Recipe - Bottle Gourd And Toor Dal Recipe', 'andhra-style-sorakaya-kura-recipe-bottle-gourd-and-toor-dal-recipe', 'Andhra Style Sorakaya Kura Recipe (Bottle gourd and Toor Dal Recipe) is a one pot dish that can be made in a pressure cooker. The bottle gourd and toor dal is a wonderful combination to make a rich and comforting gravy.”Koora” in Andhra Pradesh refers to any gravy dish that has a vegetable accompanied by a dal.', '["2 cups Bottle gourd (lauki) , cut into small pieces", "1 cup Arhar dal (Split Toor Dal) , soaked for 30 minutes", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1 pinch Asafoetida (hing)", "1 teaspoon Cumin seeds (Jeera)", "2 Tomatoes , chopped", "2 Green Chilli , chopped", "1 teaspoon Black pepper powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder"]'::jsonb, ARRAY['tomato', 'arhar dal (split toor dal)', 'green chilli', 'asafoetida (hing)', 'mustard seeds', 'red chilli powder', 'curry leaves', 'bottle gourd (lauki)', 'cumin seeds (jeera)', 'black pepper powder', 'turmeric powder']::text[], '["To begin making the Sorakaya Kura Recipe we will keep a pressure cooker on medium heat, add oil and leave it get hot.", "Add mustard seeds and cumin seeds and allow it splutter for 10 seconds.Add curry leaves, hing, and leave the curry leaves to crackle for 10 seconds.", "Add in the chopped tomatoes and saute well till it becomes mushy.Add the turmeric powder, red chilli powder, pepper powder, salt, green chilli, chopped bottle gourd and soaked toor dal.", "Give the ingredients a stir and add 2 cups of water.", "Cook it for 4 whistle.Allow the pressure to release by itself and open the lid, give it a stir and check for salt and serve.Serve the Sorakaya Kura Recipe along with\u00a0Tawa Paratha\u00a0,or\u00a0Phulka\u00a0along with a\u00a0Carrot And Beans Thoran\u00a0to go along with your meal."]'::jsonb, 35, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Andhra_Style_Sorakaya_Kura_Recipe_Bottle_gourd_and_Toor_Dal_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/115.Andhra_Style_Sorakaya_Kura_Recipe_Bottle_gourd_and_Toor_Dal_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Fish Tandoori Recipe', 'fish-tandoori-recipe', 'Have you ever tried out fish tandoori? Trust me, it is equally as delicious as chicken tandoori. Normally, tandoori is prepared in tandoor oven, but I normally prepare it in my convection oven. The fish choice is completely upto you. Same recipe can be used for fillets too. I normally use pompano or kingfish for this recipe.', '["1 Fish , nicely washed with bones on (I used Pompano)", "2 tablespoons Curd (Dahi / Yogurt)", "1/4 cup Onions , finely chopped", "2 Green Chillies , chopped", "1 tablespoon Tandoori masala", "1 teaspoon Ginger Garlic Paste", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Cumin powder (Jeera)", "1 tablespoon Coriander (Dhania) Leaves , finely chopped", "1 tablespoon Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'coriander (dhania) leaves', 'tandoori masala', 'red chilli powder', 'ginger garlic paste', 'curd', 'onion', 'fish nicely bs on pompano)', 'coriander powder', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Fish Tandoori recipe, keep the head and tail on and remove the fins and insides of the fish.Make as many horizontal slits as possible to the fish on both the sides for marinade to go deep inside.", "Wash it really well and apply salt on both the sides .Keep for about 10 minutes.", "In a bowl, mix together all the marination ingredients together really well including curd, onions, green chiliies, tandoori masala, ginger garlic paste, red chilli powder, garam masala powder, cumin powder, coriander leaves, salt and apply it to the fish on both the sides, pressing the mixture inside the slits really well .Keep it covered for about 40 to 50 minutes for marination.", "The longer is better.Preheat you oven to 400 degree Fahrenheit.", "Lightly brush the grill with oil and place the fish over the grill.Place your grill on the baking tray and bake for about 20 minutes.To check the fish whether baked well, insert a toothpick and check if it feel soft and light.", "If it does, remove the stick out and serve hot.Serve Fish Tandoori\u00a0Recipe as an appetiser or as a side dish with\u00a0Posto Chicken\u00a0and\u00a0Steamed Rice\u00a0for your weekday dinner."]'::jsonb, 80, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/Fish_Tandoori.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/116.Fish_Tandoori.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thatta Payaru Sambar Recipe - Black Eyed Beans Sambar', 'thatta-payaru-sambar-recipe-black-eyed-beans-sambar', 'Thatta Payaru Sambar is an authentic vegetarian curry in which beans are cooked along with spices in a creamy dal base. This dish is the best way to include plant-based proteins in your diet.', '["1 cup Black Eyed Beans (Lobia)", "1/4 cup Arhar dal (Split Toor Dal)", "1 Onion , finely chopped", "1 Tomato , finely chopped", "2 teaspoon Sambar Powder", "1 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi) , + 1/4 teaspoon", "1 teaspoon Salt", "2 cloves Garlic", "1/4 cup Coriander (Dhania) Leaves , finely chopped", "2 tablespoons Oil", "1/8 teaspoon Asafoetida (hing)", "2 Dry Red Chilli", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)"]'::jsonb, ARRAY['black eyed beans', 'lobia', 'arhar dal', 'split toor dal', 'onion', 'tomato', 'sambar powder', 'red chilli powder', 'turmeric powder', 'haldi', 'salt', 's garlic', 'coriander', 'dhania', 's oil', 'asafoetida', 'hing', 'dry red chilli', 'methi seeds', 'fenugreek seeds', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split']::text[], '["To begin making the Thatta Payaru Sambar recipe, wash the toor dal with water twice and drain the excess water from the dal.Add 1/4 teaspoon of turmeric to the toor dal and cook the dal in pressure cooker for three whistles.", "Set the cooked dal aside until the pressure releases.In a large pot, add about 3 cups of water and bring it to boil over high heat.", "Add black eyed beans and 1/4 teaspoon of turmeric powder to the boiling water.Cook the beans with lid uncovered until the beans become soft and tender.", "Drain the excess water from the beans and set aside.Heat a medium sized pan on the stove over medium heat.", "Add oil to the pan.", "Once the oil is hot, add the ingredients mentioned under tempering which includes asafoetida, dry red chilli, fenugreek seeds, mustard seeds and white urad dal.", "Fry them for few seconds, till the mustard seeds splutter and urad dal turns golden.Add chopped onions, tomatoes and saute till the onions are soft and translucent.", "Once the onions are soft,\u00a0add sambar powder, red chili powder, and salt.", "Stir well.To the spice blend, add cooked dal and 2 cups of water.Bring the mixture in the pan to boil.", "Once the mixture starts boiling, add cooked beans and combine them well.Cook until the raw smell of spice powders goes off.", "At the end, add minced garlic and give them a stir.", "Simmer the curry for 2 to 3 minutes.Switch off the stove and add freshly chopped coriander leaves to Sambar.", "Leave it undisturbed till serving time.Serve Thatta Payaru Sambar with\u00a0Steamed Rice,\u00a0Carrot and Beans Thoran\u00a0and\u00a0Elai Vadam.", "Add a spoon of ghee to the sambar rice to make it more delicious."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Thatta_Payaru_Sambar.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/117.Thatta_Payaru_Sambar.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karwar Style Kairichi Udid Methi Recipe (Raw Mango Methi Curry)', 'karwar-style-kairichi-udid-methi-recipe-raw-mango-methi-curry', 'Karwar Style Kairichi Udid Methi Recipe (Raw Mango Methi Curry) is a Konkani style raw mango curry. Its tangy, spicy, little sweetish with a hint of bitterness acquired from methi seeds in it. Its one of the must dish in Konkani festivals. Served with steamed rice, they taste absolute finger licking.', '["2 Mango (Raw) , peeled and chopped", "1 cup Fresh coconut , grated", "1 tablespoon White Urad Dal (Split)", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 tablespoon Basmati rice", "5 Dry Red Chillies", "1/2 teaspoon Turmeric powder (Haldi)", "Curry leaves , few", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "Asafoetida (hing) , a pinch", "2 tablespoons Jaggery , adjustable", "Salt , to taste", "Coconut Oil , as required"]'::jsonb, ARRAY['basmati rice', 'salt', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'jaggery', 'curry leaves', 'mango', 'white urad dal (split)', 'dry red chillies', 'methi seeds (fenugreek seeds)', 'coconut oil', 'turmeric powder']::text[], '["To begin making the Karwar Style Kairichi Udid Methi Recipe (Raw Mango Methi Curry), chop raw mango into bite sized pieces.", "Into the pressure cooker, add\u00a0 turmeric powder, salt and 1/4 cup of water and pressure cook for 3 whistles.Meanwhile, in a small pan, roast the urad dal, fenugreek seeds, rice and red chillies till crisp.", "Grind this along with coconut adding little water and make a smooth paste.When the raw mangoes are cooked add the ground masala to it.", "Add salt, jaggery and few curry leaves.", "Mix everything well and bring the Kairichi Udid Methi Curry to boil.", "Add some water to get the desired consistencyThe next step is to prepare the tempering.", "Add oil in a small tadka pan and when its hot add mustard seeds, hing and few curry leaves.", "Pour into Kairichi Udid Methi and it is ready to be served.Serve\u00a0Karwar Style Kairichi Udid Methi Recipe (Raw Mango Methi Curry) along with\u00a0Punjabi Style Tinda Sabji,\u00a0Palak Raita\u00a0and\u00a0Phulka\u00a0for your everyday meal."]'::jsonb, 30, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/Udid_Meti_Karwar_Style_Green_Mango_Curry_With_Methi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/118.Udid_Meti_Karwar_Style_Green_Mango_Curry_With_Methi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Cauliflower And Soya Chunks Sabzi Recipe', 'cauliflower-and-soya-chunks-sabzi-recipe', 'Cauliflower is a versatile vegetable. We can make rice, gravies, curries, fries and kurma with cauliflower. Here in this recipe. Cauliflower and Soya Chunks are combined to make a High Protein and Vitamin rich curry.', '["1 Cauliflower (gobi) , cut into florets", "1 cup Soy Chunks (Nuggets) , soaked in warm water", "1 Onion , finely chopped", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1/4 cup Fresh coconut , grated", "1 Green Chillies , finely chopped or slit", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1/2 teaspoon Turmeric powder (Haldi)", "Coriander (Dhania) Leaves , finely chopped", "1 sprig Curry leaves", "1 teaspoon Oil", "Salt , as per your taste", "Water , as needed", "2 teaspoons Lemon juice , optional"]'::jsonb, ARRAY['salt', 'mustard seeds', 'coconut', 'coriander (dhania) leaves', 'cauliflower (gobi)', 'soy (nuggets) water', 'red chilli powder', 'water', 'green chilliesor', 'curry leaves', 'onion', 'cumin seeds (jeera)', 'lemon', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the\u00a0Cauliflower And Soya Chunks Curry Recipe, add\u00a0water in a large saucepan and add salt, 1/4 teaspoon turmeric powder and bring it to a boil.Add cauliflower florets to the boiled water and simmer for 5 to 6 minutes and turn off the heat.", "Drain water from the cauliflower florets and set them aside.", "This process will remove any worms from the cauliflower and lightly steam cook it as well.", "Meanwhile, in an another pan add water and bring it to a boil.", "Add the soya chunks and let it soak for 10 minutes.", "After 10 minutes, squeeze the water from the soya granules and run it under cold tap water.", "This helps in removing the smell from the soya chunks.", "Again squeeze it to remove the water.Meanwhile, add grated coconut, green chillies to a mixer and grind it to a smooth paste using 1/4 cup of warm water.", "Keep this aside.Heat oil in a heavy bottomed pan over medium heat; add mustard seeds, cumin seeds and allow it to crackle.", "Once they crackle, add the chopped onion and saute it till it turns translucent.", "Add curry leaves, red chilli powder, turmeric powder, garam masala and salt.", "Saute it for few seconds.Now, add the ground coconut and green chillies paste to the kadhai.", "Stir well for a few seconds.At this stage add partially steamed cauliflower florets and soya chunks.", "Stir the\u00a0Cauliflower And Soya Chunks Sabzi well so that masalas get coated well on the cauliflower florets and soya chunks.Cover the kadai/pan and cook the\u00a0Cauliflower And Soya Chunks Sabzi for 10 minutes until the cauliflower and the soy chucks get cooked and also well coated in the masala.", "Stir in regular intervals so as to ensure the vegetables do no stick to the bottom.", "Turn off the heat and finally garnish with finely chopped coriander leaves.", "Add the lemon juice on top to make the Cauliflower And Soya Chunks Curry Recipe a little tangy.Serve\u00a0Cauliflower And Soya Chunks Curry\u00a0along with\u00a0Steamed Rice\u00a0and\u00a0Palak Dal\u00a0for a\u00a0simple weeknight dinner.", "In addition, you can add a fewer chillies to this recipe and make a frankie roll using a\u00a0Roti\u00a0and pack it for your\u00a0kid''s lunch box\u00a0as well."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/aishchitra-gmail.com/Cauliflower__and_soya_chunks_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/119.Cauliflower__and_soya_chunks_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Veg Chilli Milli Recipe', 'veg-chilli-milli-recipe', 'Veg Chilli Milli is a North Indian dish with cashew and tomato based gravy. It is made with different vegetables and is spiced with Indian masalas. As the name suggested this dish is a little spicy but you can adjust the spice levels to suit your taste.', '["1 cup Cabbage (Patta Gobi/ Muttaikose) , shredded", "1 Carrot (Gajjar) , cut into thin strips", "1 Green Bell Pepper (Capsicum) , thinly sliced", "4 Tomatoes", "1/2 cup Green peas (Matar)", "3 tablespoons Cashew nuts", "2 tablespoon Oil", "1 Bay leaf (tej patta)", "2 Cardamom (Elaichi) Pods/Seeds", "1 Black cardamom (Badi Elaichi)", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 Onion , finely chopped", "1 tablespoon Ginger Garlic Paste", "1/2 tablespoon Turmeric powder (Haldi)", "1 tablespoon Kashmiri Red Chilli Powder", "1 tablespoon Coriander Powder (Dhania)", "3 to 4 Green Chillies , slit", "1-1/2 cup Water", "1/4 tablespoon Garam masala powder", "Coriander (Dhania) Leaves , a small bunch finely chopped", "1/4 tablespoon Sugar", "3 tablespoons Fresh cream", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'kashmiri red chilli powder', 'carrot', 'onion', 'turmeric powder', 'green chillies', 'sunflower oil', 'black cardamom (badi elaichi)', 'coriander (dhania)', 'salt', 'cardamom (elaichi) podsseeds', 'garam masala powder', 'water', 'sugar', 'cashew nuts', 'bay leaf (tej patta)', 'green peas (matar)', 'ginger garlic paste', 'cinnamon stick (dalchini)', 'green bell pepper (capsicum)', 'coriander powder', 'cloves (laung)', 'cabbage (patta gobi muttaikose)']::text[], '["To begin making the Veg Chilli Milli Recipe, soak cashew in 1/4 cup hot water for 20 to 25 minutes.After 25 minutes, drain water and add cashews to\u00a0 mixer grinder along with ginger and\u00a0 tomatoes and grind them. to a smooth paste and keep aside.Now we will make the gravy.Heat a wok/kadai and add oil.", "Add bay leaf, green cardamoms, black cardamoms, cloves, cinnamon and saute till all spices release a nice aroma.Once the spices release a nice aroma add chopped onion and ginger garlic paste, saute on medium flame till ginger garlic aroma goes away and onion turns little brown in colour.Now add tomatoes cashew paste, green chillies,\u00a0turmeric powder, kashmiri red chilli powder, coriander powder and mix well and\u00a0saute it on medium flame till the oil separates from masala.Once done add the shredded cabbage, carrots, capsicum and green peas.", "Mix all vegetables with masala and saute for 5 to 6 minutes.Once the vegetables are half done add water and salt to taste.", "Mix well and cover the lid.Cook Veg Chilli Milli on medium flame for 10 minutes till vegetables are cooked properly.Add more water if needed but make sure gravy should not be thin.Once vegetables are cooked then add garam masala, fenugreek leaves and sugar.", "Mix everything well.Bring the Veg Chilli Milli to a brisk boil and add cream, garnish with coriander leaves and turn off the heat.Transfer Veg Chilli Milli to a serving bowl and serve hot.Serve Veg Chilli Milli along with\u00a0Boondi Raita\u00a0and\u00a0Pudina Tawa Paratha\u00a0for a weekday lunch or dinner."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Veg_Chilli_Milli.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/120.Veg_Chilli_Milli.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Carrot Methi Pachadi Recipe', 'carrot-methi-pachadi-recipe', 'Carrot Methi Pachadi is very flavourful and simple recipe. It is usually made in South Indian as a side dish along with their meal. It is very easy to make and takes very less time to get prepared. This is a simple recipe that is a bit runny.', '["100 grams Methi Leaves (Fenugreek Leaves)", "1 Carrot (Gajjar) , grated", "1 tablespoon Tamarind Paste", "2 Green Chillies , finely chopped (adjustable)", "1/2 tablespoon Jaggery", "1/4 tablespoon Turmeric powder (Haldi)", "Salt , to taste", "2 Dry Red Chillies", "1 tablespoon Oil", "2 tablespoons White Urad Dal (Split)", "1/4 tablespoon Mustard seeds (Rai/ Kadugu)", "1 tablespoon Cumin seeds (Jeera)"]'::jsonb, ARRAY['salt', 'mustard seeds', 'methi leaves (fenugreek leaves)', 'jaggery', 'carrot', 'white urad dal (split)', 'dry red chillies', 'cumin seeds (jeera)', 'tamarind paste', 'turmeric powder', 'green chillies()', 'sunflower oil']::text[], '["To begin making the Carrot Methi Pachadi recipe, heat oil in a tadka pan.Once the cooking oil is hot, add urad dal, cumin seeds and mustard seeds in the pan.", "Once the mustard seeds starts to crackle, add in the dry red chillies and saute a bit.", "Switch off after few seconds.In a kadai, add a bit of oil, once hot, add\u00a0the green chillies, fresh methi and grated carrot.", "Let it cook for about a minute till the methi wilts a bit.Add tamarind paste and mix it well.", "Turn off the heat and let the mixture cool down.Once it cools down, transfer the mixture into blender.", "Add in the jaggery and the required salt.", "Blend it into a coarse paste but with the help of a bit of water such that the pachadi is not very thick.", "Pour the tadka over pachadi and serve.Serve Carrot Methi Pachadi along with\u00a0Beetroot Sambar Recipe\u00a0and\u00a0Ghee Rice Recipe\u00a0for a weekday meal."]'::jsonb, 20, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/22-march/carrot_methi_raitha_recipe-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/121.carrot_methi_raitha_recipe-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karwar Style Muga Ambat Recipe (Moong Sprouts in Coconut Curry)', 'karwar-style-muga-ambat-recipe-moong-sprouts-in-coconut-curry', 'Karwar Style Muga Ambat Recipe (Moong Sprouts in Coconut Curry) is a curry recipe made from ''Muga'' - which refers to the green gram which is mostly sprouted and used in recipes.The sprouted green gram is full of nutrients and is rich in fiber. Even during special occasions like marriages, the green gram curry is served as a side dish to be enjoyed along with rice.', '["1 cup Green Moong Sprouts", "1 tablespoon Tamarind Paste", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Sugar", "Salt , to taste", "To be roast and ground into smooth paste (with water)", "1/2 cup Fresh coconut , grated", "2 Dry Red Chillies", "1 teaspoon Coriander (Dhania) Seeds", "1 teaspoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "Asafoetida (hing) , a pinch", "3-4 Curry leaves , torn"]'::jsonb, ARRAY['salt', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'green moong sprouts', 'curry leaves', 'sugar', 'dry red chillies', 'coriander (dhania) seeds', 'tamarind paste', 'turmeric powder', 'sunflower oil']::text[], '["To prepare Karwar Style Muga Ambat Recipe (Moong Sprouts in Coconut Curry), remove the skin of the green gram/moong sprouts by soaking them in water for 20 minutes and then rubbing off with hands.One the moong sprouts are ready, heat a kadai/wok with oil and temper with mustard and curry leaves.Add the onions, sugar and a pinch of salt and keep stirring over low heat till the onions turn brown.Now add the sprouted green gram, tamarind pulp, turmeric powder and mix well and cook them covered over low flame for 5 minutes.Open the lid and add 1 cup of water to the mixture.In a mixer grinder, combine the coconut along with the coriander seeds, salt and red chillies and grind\u00a0 this along with some water to make a thick coconut paste.", "Adjust salt and stir in the thick coconut paste into the curry.", "Mix Muga Ambat well and allow them to cook for another 3-4 minutes and switch off.Serve Karwar Style Muga Ambat\u00a0(Moong Sprouts in Coconut Curry) with Steamed rice or poori and poriyal\u00a0to enjoy your everyday meal."]'::jsonb, 25, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/4-may/Karwar_Style_Muga_Ambat_Recipe_green_moong_lentil_coocnut_curry-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/122.Karwar_Style_Muga_Ambat_Recipe_green_moong_lentil_coocnut_curry-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lemon Rice Recipe - Elumichai Sadam/Chitranna', 'lemon-rice-recipe-elumichai-sadam-chitranna', 'The Lemon Rice Recipe also known as Elumichai Sadam in Tamil or Chitranna in Karnataka is a rice that is packed with flavors from lemon, green chillies and curry leaves. Different flavored rice is a very popular way of reusing leftover rice from the previous day. Making use of leftover rice, makes it easy to pack your lunch box for work or school.', '["2 cups Cooked rice , in grainy form", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1/4 cup Raw Peanuts (Moongphali)", "1 sprig Curry leaves , roughly chopped", "1 inch Ginger , grated", "2 Green Chillies , finely chopped", "1 teaspoon Turmeric powder (Haldi)", "Salt , taste", "1 tablespoon Sesame (Gingelly) Oil", "Coriander (Dhania) Leaves , a small bunch finely chopped"]'::jsonb, ARRAY['s cooked rice', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'raw peanuts', 'moongphali', 'curry leaves', 'ginger', 'reen chillies', 'turmeric powder', 'haldi', 'salt', 'sesame', 'gingelly', 'coriander', 'dhania']::text[], '["To begin making the\u00a0Lemon Rice Recipe (Elumichai Sadam/Chitranna), make sure you have some cooked rice ready.", "It helps using a day old rice as the grains will be separated out well.Keep the remaining ingredients handy, as this recipe will be made in a jiffy.Heat oil in a heavy bottomed pan or kadai, add the mustard seeds, the urad dal and peanuts.", "Allow them to crackle and the dal and the peanuts to get roasted well until it gets a golden brown color.", "Do this on low to medium heat else they will get brown faster than you want them to and the peanuts will remain raw.Once the dal is golden brown and roasted, add the curry leaves, ginger, green chillies, turmeric powder and stir for a few seconds.Add the cooked rice, sprinkle some salt and give it a good stir until all the ingredients have combined well and the rice gets well coated.", "Turn the heat to low, cover the pan and allow the lemon rice to steam along with the seasonings for a couple of minutes.After a couple of minutes, squeeze the lemon juice and give the rice a good stir.", "Check the salt and spice levels and adjust to suit your taste.Turn off the heat and stir in the chopped coriander leaves and serve.Serve the\u00a0Lemon Rice (Elumichai Sadam/Chitranna) along with papad and\u00a0tomato onion raita, or plain yogurt."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Elumichai_Sadam_Lemon_Rice_Recipe_Nimbehannu_Chitraanna_Nimbu_Baath-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/123.Elumichai_Sadam_Lemon_Rice_Recipe_Nimbehannu_Chitraanna_Nimbu_Baath-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Togari Bele Tovve Recipe  - Toor Dal Rasam', 'togari-bele-tovve-recipe-toor-dal-rasam', 'Tovve is native to South India and it is called by different names according to the region and the people. While Tamilians call as Rasam, it is labelled as Tovve in Karnataka. Tovve is basically a mild lentil dish cooked with ghee in a tamarind based gravy without any exotic spices. It is also known as Kattu Saaru, where Kattu refers to dal in Kannada. Tovve is a versatile recipe and can be prepared with any kind of dals and vegetable. Togari Bele Tovve is prepared using red gram dal. This simple comforting dish doesn’t call for any spices, doesn’t involve any complex cooking techniques and moreover, they can be prepared within few minutes.', '["1 cup Arhar dal (Split Toor Dal)", "5 cups Water", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Ginger , finely grated", "5 Green Chillies , slit (adjust)", "30 grams Tamarind", "1/2 Lemon juice", "1 tablespoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)", "Curry leaves , Handful", "Coriander (Dhania) Leaves , Handful"]'::jsonb, ARRAY['arhar dal', 'split toor dal', 's water', 'turmeric powder', 'haldi', 'ginger', 'reen chillies', 's tamarind', 'lemon juice', 'ghee', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing', 'curry leaves', 'coriander', 'dhania']::text[], '["To begin making the Togari Bele Tovve recipe, soak dal in water for about 30 minutes.Wash the dals thoroughly with water.", "In a pressure cooker, add soaked dal, 1/2 teaspoon turmeric powder, 2 cups of water and pressure cook for 3 whistles.", "Turn off the flame and allow the pressure to release naturally.", "Soak Tamarind in a bowl of hot water and extract tamarind Juice.", "We need 1-1/2 cup of tamarind juice for tovve.Once the dal is cooked, gently mash the dal with the back of the ladle.In a wok/kadai, add ghee and gently heat over medium flame.Once the ghee melts, add mustard seeds followed by curry leaves, ginger, and green chilies.Cook until the aroma of ginger fades out and chilies are lightly fried.Add tamarind water to the pan and bring it to boil.", "Add the remaining turmeric powderLet it boil.", "Once the raw smell of tamarind goes off, add cooked dal and required amount of salt.Cook until froth forms on top of the tovve.", "Ensure not to boil it again.Season with hing and give a stir.", "Switch off the flame.", "Add lemon juice and combine it well.Garnish with coriander leaves and serve with steam rice or idlisTovve can be prepared with Moong dal by following the same procedure.", "One can adjust the amount of Tamarind or completely avoid the same according to their desires.", "In such cases, add the juice of a lemon.Serve this humble Togari Bele Tovve with hot steaming rice and\u00a0Beetroot Thoran\u00a0or with Spongy Idlis and\u00a0Mysore Chutney\u00a0to please your tummy as well as your taste buds."]'::jsonb, 35, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Togaribele_Tovve.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/124.Togaribele_Tovve.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chicken Xacuti Recipe - Goan Chicken Gravy', 'chicken-xacuti-recipe-goan-chicken-gravy', 'Chicken Xacuti Recipe is essentially a Goan style chicken curry packed with flavours.  Xacuti is actually pronounced as ‘shakuti’ derived from the Portuguese word ‘chacuti’.', '["500 grams Chicken , curry cut pieces", "1/2 cup Tamarind Water", "Salt , Salt to taste", "2 tablespoons Oil", "1 Onion , finely chopped", "1-1/2 inch Ginger , finely chopped", "8 cloves Garlic , finely chopped", "8 Kashmiri dry red chilli", "1/2 cup Fresh coconut", "2 tablespoon Poppy seeds", "4 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "15 Black pepper corns", "1-1/2 teaspoons Cumin seeds (Jeera)", "1-1/2 tablespoon Coriander (Dhania) Seeds", "1 tablespoon Fennel seeds (Saunf)", "1 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Sesame seeds (Til seeds)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1/2 teaspoon Oil"]'::jsonb, ARRAY['salt', 'ginger', 'chicken curry', 'tamarind water', 'kashmiri dry red chilli', 'coconut', 'black pepper corns', 'cinnamon stick', 'fennel seeds (saunf)', 'cloves garlic', 'onion', 'poppy seeds', 'cumin seeds (jeera)', 'sesame seeds (til seeds)', 'methi seeds (fenugreek seeds)', 'turmeric powder', 'coriander seeds', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Chicken Xacuti recipe, firstly wash the chicken well.", "Marinate the chicken with salt and keep aside.Heat 1/2 teaspoon of oil in a pan.", "Add chopped onions, garlic and ginger and saut\u00e9 till onions turns translucent and lightly golden.Add grated coconut to the above onions and saut\u00e9 till coconut turns golden brown.", "Remove the mixture from stove and set aside to cool.Into the same pan add Kashmiri red chilies,\u00a0poppy seeds,\u00a0cloves,\u00a0cinnamon stick, peppercorns,\u00a0cumin seeds,\u00a0coriander seeds,\u00a0fennel seeds,\u00a0turmeric powder,\u00a0sesame seeds, fenugreek seeds and roast them for about 3- 5 minutes on low flame.Roast the spices until they release nice aroma and just begin to turn brown.", "Turn of the heat and set aside to cool.Grind the roasted spices and onion-coconut mix and grind into a smooth paste by adding little water.Now heat 2 tablespoons of oil in a deep bottomed pan.", "Add the ground masala paste and cook for 5 minutes.", "Add chicken pieces and cook for 5 minutes with constant stirring.Now add water and bring it to boil.", "Continue to cook until chicken is well cooked.", "Add tamarind water and continue to cook for another 5 to 7 minutes on low flame.Remove from stove, garnish with fresh coriander leaves and serve hot.Serve Chicken Xacuti with\u00a0Steamed Rice\u00a0or\u00a0Ladi Pav\u00a0for a comforting weekend brunch."]'::jsonb, 55, 'Goan', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Chicken_Xacuti.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/125.Chicken_Xacuti.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Style Chaman Recipe-Qaliya Cottage Cheese Curry', 'kashmiri-style-chaman-recipe-qaliya-cottage-cheese-curry', 'Chaman Qaliya is a creamy cottage cheese curry scented with fennel and cardamom that belongs to Kashmiri Cuisine. An aromatic curry that is cooked in milk and flavoured with Kashmiri spices is a perfect vegetarian side dish commonly served on special occasions in the valley.', '["500 grams Paneer (Homemade Cottage Cheese) , cut into 1", "Mustard oil , or refined oil as required", "2 to 3 Saffron strands", "1 Bay leaf (tej patta)", "1 Cinnamon Stick (Dalchini)", "4 Cloves (Laung)", "1 cup Milk", "6 cups Water", "2 tablespoons Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera)", "3 tablespoons Fennel Powder", "Salt , to taste", "1 teaspoon Cardamom Powder (Elaichi)", "Coriander (Dhania) Leaves , for garnish"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'bay leaf (tej patta)', 'paneer', 'coriander (dhania) leaves', 'saffron strands', 'milk', 'water', 'fennel powder', 'cinnamon stick (dalchini)', 'cardamom powder (elaichi)', 'turmeric powder', 'cloves (laung)', 'mustard oil refined oil']::text[], '["To begin making the Kashmiri Style Chaman Recipe, firstly heat oil in a wok/kadai and add bay leaf, cinnamon and cloves.Add water to the wok and as it comes to boil, add turmeric powder, cinnamon powder, salt and fennel powder and mix.Let the gravy boil and reduced a little.", "Now add paneer pieces and cook till paneer turns soft and the curry starts to thicken.Add 1 cup of whole fat milk and saffron, stir well and cook till required consistency.Now add cardamom powder and turn off the gas.Garnish\u00a0Kashmiri Style Chaman with fresh chopped coriander and it is ready to be served.Serve\u00a0Kashmiri Style Chaman Recipe\u00a0with\u00a0Kashmiri Kesar Pulao\u00a0or\u00a0Homemade Butter Naan\u00a0for a nice lunch."]'::jsonb, 45, 'Kashmiri', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shaheen_Ali/CHAMAN_QALIYA.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/126.CHAMAN_QALIYA.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Murgh Palak Recipe - Chicken In Spinach Gravy', 'murgh-palak-recipe-chicken-in-spinach-gravy', 'Murgh Palak Gravy Recipe is a classic North Indian gravy made with marinated chicken, pureed spinach and whole spices. The end result is a tasty and nutritious dish which is very easy to make and is also perfect for your weekday meals.', '["Ingredients For Palak Puree", "250 grams Spinach Leaves (Palak) , cleaned", "Salt , a pinch", "4 cloves Garlic", "2 Green Chillies", "Ingredients For Chicken Marinade", "500 grams Chicken , curry cut", "2 tablespoons Curd (Dahi / Yogurt)", "1 teaspoon Kashmiri Red Chilli Powder", "1 teaspoon Garam masala powder", "1 teaspoon Coriander (Dhania) Powder", "1 tablespoon Salt", "Ingredients For Murgh Masala", "1 tablespoon Ghee , chopped", "1 Bay leaf (tej patta)", "3 Cardamom (Elaichi) Pods/Seeds , chopped", "1 inch Cinnamon Stick (Dalchini)", "1 Onion , Finely Chopped", "1 inch Ginger", "3 cloves Garlic , to taste", "1 tablespoon Butter (Salted)", "1/4 cup Fresh cream", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)"]'::jsonb, ARRAY['ingredients for palak puree', 's spinach leaves', 'palak', 'salt', 's garlic', 'reen chillies', 'ingredients for chicken marinade', 's chicken', 's curd', 'dahi / yogurt', 'kashmiri red chilli powder', 'garam masala powder', 'coriander', 'dhania', 'ingredients for murgh masala', 'ghee', 'bay leaf', 'tej patta', 'cardamom', 'elaichi', 'cinnamon stick', 'dalchini', 'onion', 'ginger', 'butter', 'salted', 'fresh cream', 'kasuri methi', 'dried fenugreek leaves']::text[], '["MethodTo begin making\u00a0Murgh Palak Recipe, we have to first marinate the chicken.", "In a bowl, add curd, chicken pieces, salt, kashmiri red chilli powder, garam masala , coriander powder mix well and keep it aside for at least 30 minutes.", "Add the chopped palak leaves to a pressure cooker, garlic, and green chillies with a teaspoon of water and salt.", "Pressure cook for 1 whistle and release the pressure immediately by running the pressure cooker under tap water or by lifting the weight using a fork.", "Open the cooker and allow the palak mixture to cool.Once cooled, add the cooked palak mixture to a blender and make a smooth puree.", "Keep aside.For the Murgh Masala, add the onion, ginger and garlic to a small jar of the mixer grinder and blend to make a paste.Preheat a kadai over medium heat, add 1 tablespoon of ghee.", "Stir in bay leaf, cardamom, cinnamon and saute for a few seconds until you can smell the aromas coming through.", "Add onions, ginger, garlic paste and saute until the raw smell goes away and onions turn light brown.Once the onions are done, add the marinated chicken along with \u00bd cup of water Cover the pan and cook the chicken until done, for about 10 to 15 minutes.Once cooked and the chicken forms a thick gravy, stir in the pureed spinach, fresh cream, kasuri methi and give it a brisk boil.", "Check the salt and spices and adjust accordingly.", "Turn off the heat.Transfer the Murg Palak to a serving bowl and serve hotServe Murgh Palak along with\u00a0Burani Raita,\u00a0Garlic Naan,\u00a0Mutton Biryani\u00a0and\u00a0Kachumber Salad\u00a0for a weekend meal along with your family."]'::jsonb, 75, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2022/Murgh_Palak_Recipe_Chicken_In_Spinach_Gravy_123_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/127.Murgh_Palak_Recipe_Chicken_In_Spinach_Gravy_123_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Doodh Jhinge Curry Recipe-Ridge Gourd Cooked In Milk', 'doodh-jhinge-curry-recipe-ridge-gourd-cooked-in-milk', 'Doodh Jhinge Curry Recipe is the Ridge Gourds Cooked In Milk and tempered with mustard seeds, flavoured with ginger and spiked with spicy green chillies. Ridge gourd peel that is not used in this recipe can later be used to prepare Ridge Gourd Peel Chutney instead of discarding it.', '["500 grams Ridge Gourd (Turai/ Peerkangai) , peeled & finely chopped", "200 ml Milk", "2 inch Ginger , grated", "4 Green Chillies , slit", "2 Dry Red Chillies", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 teaspoons Mustard oil", "1 teaspoon Ghee", "2 teaspoon Sugar", "Salt , to taste"]'::jsonb, ARRAY['salt', 'ginger', 'mustard oil', 'mustard seeds', 'ghee', 'milk', 'ridge gourd (turai peerkangai)', 'sugar', 'dry red chillies', 'green chillies']::text[], '["To begin making Doodh Jhinge Curry Recipe (Ridge Gourd Cooked In Milk), peel the ridge gourds, cut into half, and then chop well.In a kadai, heat oil, once the oil is hot, add mustard seeds and allow them to crackle.Immediately add the whole dry red chillies and saute for a few more seconds.Add in the chopped ridge gourd.", "Mix well to combine.Now add sugar and mix - this helps in retaining the color of the vegetable.Add salt and ginger paste.", "Saute for a minute and cover and cook on a medium heat till the vegetable is cooked and the moisture is all dried up.", "You can stir\u00a0 the vegetables a couple of times to help it cook evenly.Meanwhile, add a pinch of besan to the bowl of milk and stir well.", "This helps in keeping the milk from curdling.Once the ridge gourd is cooked, add green chillies to the kadai and slowly add milk. stir well to combine and bring the\u00a0Doodh Jhinge Curry to a brisk boil.Reduce the flame and continue to cook for about 5-7 minutes to allow the curry to thicken to the desired consistency.", "Check that the sugar and salt and adjust to suit your taste, add a dollop of ghee and turn off the heat.Transfer\u00a0Doodh Jhinge Curry to a bowl and serve.Serve Doodh Jhinge Curry Recipe (Ridge Gourd Cooked In Milk) with Gehun Bhajra Thepla Recipe or Phulkas along with Dry Chole Recipe (Dry Masala Chickpeas) for dinner or pack away for lunch box."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/maumita.paulghosh-gmail.com/Doodh_jhinge__Ridge_gourd_cooked_in_milk_recipe_edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/128.Doodh_jhinge__Ridge_gourd_cooked_in_milk_recipe_edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Phulka Recipe (Roti/Chapati) - Puffed Indian Bread', 'phulka-recipe-roti-chapati-puffed-indian-bread', 'Phulkas also known as Roti or Chapati in some regions are a whole wheat soft and thin puffed flat bread. The phulka is a daily bread for many regional Indian cuisines. It is not only rich in the nutrients and fibers, that whole wheat brings along with it, but also low in fat and very light on the stomach.', '["1 cup Whole Wheat Flour", "1/2 teaspoon Salt , optional", "1 teaspoon Oil", "Ghee , for serving"]'::jsonb, ARRAY['whole wheat flour', 'salt', 'oil', 'ghee']::text[], '["To begin making the Phulka (roti/ chapati) recipe, first bring all the ingredients together and we will make the dough.In a large bowl combine the flour and salt; add a little water at a time to make firm dough.", "Add a teaspoon of oil to coat the dough and knead for a few more minutes until smooth.Set the dough aside to rest covered for 15 minutes.", "Knead once again and divide the dough into 8 portions.Preheat the iron skillet on medium high heat.", "Roll the portions of phulka (roti) dough into balls; flatten these balls with the palm of your hand.Take a portion of the phulka dough, toss it on the flour and roll out into thin circles to approximately 6 inches in diameter.", "As you roll them out, you can keep tossing the dough in dry flour while rolling; this will prevent it from getting sticky when rolling them out.Cook the rolled dough as indicated in the steps below.", "Continue the process of rolling with the remaining portions of the dough.Tip: It is a good idea to roll out a batch of dough so it gets easier to cook the entire batch.", "Although Gujarati ladies are very quick in rolling and cooking them simultaneously; this comes with practice of rolling and understanding the heat of your skillet."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breads/Phulka_Roti_Chapati_Puffed_indian_Flat_Bread_Recipe-1-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/129.Phulka_Roti_Chapati_Puffed_indian_Flat_Bread_Recipe-1-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Padipe Saasmi Recipe - Udupi Style Amaranth Leaves Curry With Coconut & Tamarind', 'padipe-saasmi-recipe-udupi-style-amaranth-leaves-curry-with-coconut-tamarind', 'Cuisine of our country is amazing and the variety of spinach we get is even better. Variety of spinach used in different kind of dishes and in all the cuisines of India makes our culinary culture rich and amazing.', '["12 sprig Red Amaranth Leaves , You can use spinach also", "1 cup Fresh coconut , grated", "4 Dry Red Chillies", "2 Green Chillies", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1 Tamarind , marble sized", "Salt , to taste", "1-1/2 teaspoon Oil", "1 teaspoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'mustard seeds', 'coconut', 'red amaranth leaves you can spinach also', 'tamarind marble', 'white urad dal (split)', 'dry red chillies', 'curry leaves', 'cumin seeds (jeera)', 'green chillies', 'sunflower oil']::text[], '["To begin making the Padipe Saasmi Recipe, pluck the amaranth leaves, include some of the tender stem as well.", "Wash the leaves and stem well in water.", "Drain the leaves from water.", "Chop them finely.", "Soak tamarind in 1/2 cup water for about 30 minutes.Grind together coconut, dry red chilies, green chillies, mustard seeds and cumin seeds into a thick and smooth paste.Heat oil in a heavy bottomed pan.", "Add the ground paste and cook until the raw smell is gone.Add chopped spinach/amaranth leaves and saute for about 5 to 7 minutes.", "Add salt to taste and tamarind extract or juice to the curry.Heat oil in a tadka pan.", "Add mustard seeds and allow it to splutter.", "Add dry red chilies, urad dal and curry leaves.", "Once urad dal begin to turn golden brown remove the pan from heat and pour it into the spinach curry.", "Turn off flame and serve hot.Serve Padipe Saasmi along with\u00a0Mixed Vegetable Sambar\u00a0and\u00a0Steamed Rice\u00a0for a weekday meal."]'::jsonb, 35, 'Udupi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/Padipe_Saasmi_Udupi_Style_Amaranth_Leaves_Curry_with_coconut__Tamarind.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/130.Padipe_Saasmi_Udupi_Style_Amaranth_Leaves_Curry_with_coconut__Tamarind.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('High Protein Broccoli and Dill Stuffed Paratha Recipe', 'high-protein-broccoli-and-dill-stuffed-paratha-recipe', 'High Protein Broccoli and Dill Stuffed Paratha Recipe, an innovative way to add a besan mixture filled with broccoli and dill leaves into your paratha. The broccoli is power house of Vitamin C and dill leaves will give good amount of protein content. All put together in besan flour which has High protein content. It is best for kid’s lunch as it can be packed easily and at the same time provides your children rich with nutrients.', '["1 cup Whole Wheat Flour", "1 teaspoon Salt", "Water , as required", "1/2 cup Gram flour (besan)", "1 cup Broccoli , florets blitzed into small pieces", "1/2 cup Dill leaves , chopped", "1 Red Bell pepper (Capsicum) , chopped", "1 Onion , chopped", "1 inch Ginger , chopped", "4 cloves Garlic , chopped", "1 teaspoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Oil"]'::jsonb, ARRAY['salt', 'wheat flour', 'red bell pepper (capsicum)', 'dill leaves', 'ginger', 'red chilli powder', 'water', 'cloves garlic', 'gram flour (besan)', 'onion', 'broccoli florets blitzed', 'turmeric powder', 'sunflower oil']::text[], '["We begin making the High Protein Broccoli and Dill Stuffed Paratha Recipe by mixing for the dough, add all the ingredients and add water slowly and knead it into a firm and non-sticky dough.", "Keep it aside covered.Now to make the stuffing, heat a sauce pan, crackle the cumin seeds and asafetida.", "Add in the chopped vegetables and saute till it is cooked.In a separate bowl add the red chilli powder, salt Besan flour and water, mix well, keep it aside.", "Then add it to the saut\u00e9ing vegetables.Mix well and cook till it is cooked.", "Check for seasoning and saute well.", "Leave it to cool down.Now to begin making the paratha, keep some flour aside for dusting.", "Divide the dough into large lemon side balls.Dust the dough portions in flour, flatten it and roll it into a 3 inch diameter circle.Now add the Broccoli and Bell peppers Mixture, add about a tablespoon in the center.", "Close the paratha by folding it from all the side like a dumpling and seal it properly and flatten it.", "Take care, the filling can ooze out if the dough is rolled out too thin.Now to cook the Protein Broccoli and Dill Paratha, first preheat the\u00a0skillet\u00a0on medium heat.", "Place the rolled paratha on top and allow it to cook on one side.", "After about 10 to 15 seconds, flip the paratha.At this stage, smear some oil or ghee to cook the paratha.", "Cook the paratha by flipping over a couple of times until you see golden brown spots on both sides.Proceed the same way with the remaining dough portions and serve the parathas hot.Serve the High Protein Broccoli and Dill Stuffed Paratha Recipe as a Lunch meal for your\u00a0kids lunch box\u00a0or have it during lunch on Sunday."]'::jsonb, 55, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/High_Protein_Broccoli_and_Dill_Stuffed_Paratha_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/131.High_Protein_Broccoli_and_Dill_Stuffed_Paratha_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Konkani Style Mooga Ghushi Recipe-Sprouted Whole Green Gram In Tangy Coconut Gravy', 'konkani-style-mooga-ghushi-recipe-sprouted-whole-green-gram-in-tangy-coconut-gravy', '‘Mooga Ghushi’ is a sprouted green gram-coconut based tangy gravy, another traditional delicacy of the Konkani community of Mangalore in the southern part of India. ‘Moogu’ in Konkani is green gram and ‘Ghushi’ is a standard coconut masala of this Konkani cuisine; a blend of coconut, tamarind and roasted red chillies with a seasoning of mustard seeds and curry leaves or crushed garlic.', '["1/2 cup Green Moong Dal (Whole)", "1/2 cup Fresh coconut , grated", "2 Dry Red Chilli , lightly roasted", "1/4 teaspoon Tamarind Paste , or 1 small gooseberry sized tamarind (remove seeds and fibre if any)", "2 teaspoons Coconut Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "Salt , to taste"]'::jsonb, ARRAY['salt', 'coconut', 'mustard seeds', 'dry red chilli', 'curry leaves', 'green moong dal', 'coconut oil', 'tamarind paste gooseberry tamarind (remove seeds fibre any)']::text[], '["To begin making the Mooga Ghushi recipe, firstly soak the green gram overnight and drain all the water.Cover with a wet towel and keep in a warm place to germinate.", "In about another day, they would have sprouted.", "Soak again in water for a couple of hours.", "Drain, wash and try to remove as much skin as possible.In a pressure cooker, place the sprouted beans with some water and cook for about one whistle till soft and still holds its shape.Meanwhile grind coconut, roasted red chillies and tamarind with a little water to a fine paste in a mixer grinder.Transfer this coconut paste to the cooked green gram, add salt to taste and mix gently.", "Bring to a boil.The next step is to season the gravy.", "Heat the oil in a tadka pan and add the mustard seeds.Once it starts spluttering, add the curry leaves and pour this seasoning into the moong-coconut gravy and mix.Serve Mooga Ghushi with hot steamed rice or\u00a0phulkas\u00a0with a\u00a0Carrot and Beans Thoran (Subzi Recipe)\u00a0by the side\u00a0for a perfect weekday meal."]'::jsonb, 30, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/19-april/Mooga_Ghushi_Recipe_sprouted_green_mong_in_coocnut_curry-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/132.Mooga_Ghushi_Recipe_sprouted_green_mong_in_coocnut_curry-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mangalorean Kadle Manoli Recipe  - Tindora Kala Chana Sabzi', 'mangalorean-kadle-manoli-recipe-tindora-kala-chana-sabzi', 'Mangalorean Kadle Manoli Recipe is a divine combination of black chickpeas and Ivy Gourd also known as tindora or dondakkai that is tossed with lots of coconut and homemade spice blend.', '["1 cup Kala Chana (Brown Chickpeas) , soaked for 4 hours", "300 grams Tindora (Dondakaya/ Kovakkai) , cut length wise", "4 cloves Garlic", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1 Onion , chopped", "1/4 cup Fresh coconut , grated", "1 tablespoon Jaggery", "Oil , for cooking", "Salt , to taste", "Kundapura Taal Masala Powder", "3 Dry Red Chillies", "1 tablespoon Coriander (Dhania) Seeds", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1/2 teaspoon Whole Black Peppercorns", "1 teaspoon Cumin seeds (Jeera)", "4 cloves Garlic"]'::jsonb, ARRAY['salt', 'mustard seeds', 'coconut', 'jaggery', 'cloves garlic', 'black peppercorns', 'tindora (dondakaya kovakkai)', 'curry leaves', 'dry red chillies', 'onion', 'coriander (dhania) seeds', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'kala chana (brown chickpeas)', 'sunflower oil']::text[], '["To begin making the Mangalorean Bunt Style Kadle Manoli recipe, we will first make the Kundapura Taal Masala powder.Into a small pan; add the dry red chillies, coriander seeds, cumin seeds, black pepper corns, methi seeds, turmeric powder and garlic.", "Roast all of them over medium heat until the garlic gets a golden brown roasted colour.", "Let it cool.Once cooled add this roasted\u00a0Kundapura Taal Masala ingredients into the mixer grinder and blend to make a coarse powder.", "Keep this\u00a0Kundapura\u00a0Taal Masala powder aside.Add the soaked kala chana into the pressure cooker and cook along with 2 cups of water, salt and pressure cook it for 20 minutes until the chickpeas are done.Once done, allow the pressure to release naturally.", "Drain the excess water from the Kadle and keep aside.", "You can use the water to make rasam or soups later.", "The next step is to cook the Manoli/ TindoraAdd the tindora into the pressure cooker, add 3 tablespoons water and pressure cook for 2 whistle.", "Release the pressure immediately to avoid over cooking.Heat a sauce pan with oil, add mustard seeds and allow it to crackle.", "Add the curry leaves, garlic and onions and saute until the onions soften.Once the onions soften, add the grated coconut and saute well so that they turn light brown.", "Once that is done, add the ground spice mixture, the steamed Manoli and the cooked Kadle.", "Add salt and adjust according to taste.", "Stir well to combine and cover the pan and allow the\u00a0Kadle Manoli to absorb all the spices by cooking it for 4 to 5 minutes.", "Once done, turn off the heat and serve the Kadle\u00a0Manoli hot.Add the cooked chickpeas and check for salt, adjust it according to your palate and saute for 5 more minutes and turn off the heat.Serve the Mangalorean Kadle Manoli Recipe along with\u00a0Kori Gassi\u00a0and\u00a0Neer Dosa\u00a0to make a satisfying meal for your loved ones."]'::jsonb, 165, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Mangalorean_Kadle_Manoli_Recipe_-_Tindora_and_Kala_Chana_Dry_Sabzi_-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/133.Mangalorean_Kadle_Manoli_Recipe_-_Tindora_and_Kala_Chana_Dry_Sabzi_-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Panasa Pottu Pappu Koora Recipe - Jackfruit & Dal Curry', 'panasa-pottu-pappu-koora-recipe-jackfruit-dal-curry', 'This wholesome, Panasa Pottu Pappu Koora Recipe is an Andhra style dry sabzi made using raw jackfruit and moong dal.', '["300 grams Jackfruit Raw (Kathal) , shredded", "1/2 cup Yellow Moong Dal (Split)", "1 teaspoon Oil", "1 teaspoon Black Urad Dal (Split)", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies", "1/4 teaspoon Asafoetida (hing)", "1 sprig Curry leaves", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste"]'::jsonb, ARRAY['s jackfruit raw', 'kathal', 'yellow moong dal', 'split', 'oil', 'black urad dal', 'cumin seeds', 'jeera', 'mustard seeds', 'rai/ kadugu', 'dry red chillies', 'asafoetida', 'hing', 'curry leaves', 'turmeric powder', 'haldi', 'salt']::text[], '["To begin making the\u00a0Panasa Pottu Pappu Koora Recipe,\u00a0wash and soak the moong dal in water and set aside.", "Next let us cut the raw jackfruit.", "In order to do that we have to first, grease our hands and the knife that we are going to use, with some oil.This important tip ensures that the hands don''t get sticky from the natural fruit latex/sap present in the fruit does not get onto your hands and makes the cutting process hassle-free.", "Keep a bowl of water mixed with some salt, ready to put the cut raw jackfruit pieces to avoid discolouration of the fruit.Now that your hands and knife are well greased, cut the the jackfruit in half, discard the skin and start making 1 inch pieces and soak them in the salted water.Place the jackfruit in a pressure cooker with 1/4 cup of water and pressure cook for 3 whistles and turn off the heat.Allow the pressure to release naturally.", "Drain any water from the jackfruit.", "Shred the jackfruit pieces lengthwise\u00a0and set aside.The next step is to cook the moong dal.", "Into the pressure cooker,add the soaked moong dal along with 1/2 cup of water.", "Add some salt and turmeric powder to the moong dal and pressure cook for 3 whistles and turn off the heat.", "The moong dal should be be cooked yet separated.For the tempering of the\u00a0Panasa Pottu Pappu Koora Recipe , heat oil in a pan,on medium flame, add the split urad dal until it turns into a golden brown colour.Next, add cumin seeds, mustard seeds and allow them to crackle.", "This will take about 30 seconds.Once they crackle, add the red chillies, asafoetida, curry leaves and fry till you get nice aroma.", "Turn off the heat.", "In a kadai, add the cooked and shredded jackfruit, moong dal and mix everything well.", "Add salt, cover and cook for 2 to 3 minutes on low fame.", "After 2-3 minutes, turn off the heat and add the prepared tempering.", "Stir well to combine it into the koora.", "Check the salt and spices and adjust accordingly.Once done, turn off the heat and transfer the\u00a0Panasa Pottu Pappu Koora to a serving bowl and serve hot.Serve this\u00a0Panasa Pottu Pappu Koora\u00a0along with\u00a0Steamed Rice\u00a0and\u00a0Andhra Style Pappu Urumindi Recipe\u00a0or\u00a0Aava Pettina Majjiga Pulusu Recipe\u00a0for a complete meal.", "For an Indian Diabetic meal, serve this\u00a0Panasa Pottu Pappu Koora Recipe\u00a0along with\u00a0Brown Rice in Pressure Cooker Method\u00a0and\u00a0Andhra Style Palakura Pappu Recipe\u00a0and\u00a0Mooli Raita Recipe\u00a0for a complete meal."]'::jsonb, 70, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/anu.mallajosyula-gmail.com/Panasapottu_pappu_kura_Raw_Jackfruit_and_Moong_dal_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/134.Panasapottu_pappu_kura_Raw_Jackfruit_and_Moong_dal_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tofu Bhurji Recipe - Spicy Scrambled Tofu', 'tofu-bhurji-recipe-spicy-scrambled-tofu', 'Tofu Bhurji Recipe is a vegan version of egg bhurji that you can try at home. Tofu is crumbled and the added to the sautéed bell peppers, onions and tomatoes.', '["300 grams Tofu , crumbled", "1 Onion , chopped", "1 Red Bell pepper (Capsicum)", "1 Tomato , chopped", "1 Green Chilli , chopped", "1 teaspoon Cumin seeds (Jeera)", "2 teaspoon Red Chilli powder", "1 teaspoon Black pepper powder", "1 teaspoon Turmeric powder (Haldi)", "4 sprig Coriander (Dhania) Leaves , chopped", "Salt , to taste", "Oil"]'::jsonb, ARRAY['tomato', 'salt', 'red bell pepper (capsicum)', 'green chilli', 'red chilli powder', 'coriander (dhania) leaves', 'onion', 'cumin seeds (jeera)', 'black pepper powder', 'tofu', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Tofu Bhurji Recipe, firstly crumble the tofu and keep it aside.Heat a tablespoon of butter in a heavy bottomed pan; add the cumin seeds, onion, capsicum, green chillies and ginger.", "Saute the onions and capsicum on low to medium heat until they are soft and tender.Once the onions and capsicum are soft, add the tomatoes, turmeric powder, red chilli powder and give it a good stir.Finally, stir in the crumbled tofu and salt to taste.", "Stir well, check the salt and spice levels and adjust to suit your taste.Serve the\u00a0Tofu Bhurji Recipe\u00a0along with a\u00a0Toasted Bread\u00a0or just plain Indian bread like\u00a0Phulka\u00a0and a Dal of your choice like\u00a0Panchmel Dal,\u00a0Palak Dal\u00a0etc to enjoy your dinner."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Tofu_Bhurji_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/135.Tofu_Bhurji_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Saagwala Chicken  Recipe - Palak Chicken Curry', 'saagwala-chicken-recipe-palak-chicken-curry', 'Saagwala Chicken recipe is one of the finest and healthiest of all the chicken recipes. Saagwala Chicken which is packed with flavour and taste from the fresh spinach along with a perfect blend of spices. Serve it along with Jeera Pulao or Butter Naan for a delicious dinner.', '["350 grams Chicken", "300 grams Spinach , roughly chopped", "1 teaspoon Ajwain (Carom seeds)", "2 tablespoons Ghee", "6 cloves Garlic", "2 Cardamom (Elaichi) Pods/Seeds", "2 inch Cinnamon Stick (Dalchini)", "3 Cloves (Laung)", "2 inch Ginger", "2 Green Chillies", "2 Onion , thinly sliced", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "2 tablespoons Fresh cream", "Salt , to taste"]'::jsonb, ARRAY['green chillies', 'salt', 'ginger', 'spinach', 'ghee', 'cardamom (elaichi) podsseeds', 'ajwain (carom seeds)', 'red chilli powder', 'cloves garlic', 'cinnamon stick (dalchini)', 'chicken', 'onion', 'cloves (laung)', 'garam masala powder']::text[], '["To begin making the Saagwala Chicken\u00a0recipe, firstly clean, wash the chicken breast and cut into small to medium sized pieces and keep the legs if you are using it.", "Into a pressure cooker,\u00a0add the chopped spinach leaves, green chillies, along with 2 tablespoons water and pressure cook for 1 whistle and turn off the heat.Release the pressure immediately by running it under cold water.", "Open the cooker and allow the spinach to cool.", "It''s important to open the spinach immediately, so the spinach remains green.Once the spinach cools, place it in a mixer grinder and make a puree.", "Keep the palak puree/ spinach puree aside.Heat a heavy bottomed pan with ghee, add ajwain, cloves, cinnamon, cardamom and saute it for about 10 seconds.Add the ginger, garlic and onions and saute until the onions turn translucent.", "Add the chicken, salt and red chilli powder, garam masala powder and stir to combine.Cover the pan and cook the chicken on low heat until it gets cooked completely.", "Sprinkle a little water if required and cook the chicken until it is done.Finally, pour the spinach puree and cream.", "Mix everything well and let the Palak Chicken / Saagwala Chicken simmer for 4 to 5 minutes until the gravy chickens.Once the Saagwala Chicken is done, check the taste and adjust the salt accordingly.Serve Saagwala Chicken\u00a0Recipe\u00a0along with\u00a0Burani Raita\u00a0and\u00a0Butter Garlic Naan Recipe\u00a0for a weekend dinner along with your family.", "You can also serve\u00a0Kachumber Salad\u00a0with this meal."]'::jsonb, 70, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/palak-or-spinach-chicken-or-murg-saagwala_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/136.palak-or-spinach-chicken-or-murg-saagwala_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rajasthani Chawle Wale Dhokle Recipe', 'rajasthani-chawle-wale-dhokle-recipe', 'Maize Flour is widely eaten in Rajasthan during winters. One of the popular dish which is made out of Maize flour is Rajasthani Chawle Wale Dhokle. Usually made in Marwar side of Rajasthan, you can use different lentils as a base to make this steamed dumplings.', '["15 cloves Garlic", "6 Green Chillies", "6 sprig Coriander (Dhania) Leaves , finely chopped", "2 cups Makki Ka Atta (Yellow Corn Meal Flour)", "1 teaspoon Baking soda", "Salt , as required", "Water , as required", "1/2 cup Black Eyed Beans (Lobia)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)"]'::jsonb, ARRAY['s garlic', 'reen chillies', 'coriander', 'dhania', 's makki ka atta', 'yellow corn meal flour', 'baking soda', 'salt', 'water', 'black eyed beans', 'lobia', 'turmeric powder', 'haldi', 'coriander powder']::text[], '["To begin making the Rajasthani Chawle Wale Dhokle recipe, Add the black eyed beans in 3 cups water in a pressure cooker.", "Now add turmeric powder, coriander powder and the required salt.", "Let it cook till the cooker releases 3 to 4 whistles.", "Let it release the pressure normally.Meanwhile we will make the dhoklas, add garlic, coriander and green chillies in mortal pestle and crush them together to make a coarse paste.Next, add baking soda, half of the garlic, coriander and green chilli mixture, required salt and maize flour in a mixing bowl.Open the pressure cooker and put the green chilli, garlic and coriander mixture in it and mix it with the black eyed beans.Now, knead the dough properly with the required water and knead until the dough becomes really soft.", "Make small Dhokla out of it just like we make the south indian wadas.Put the cooker on gas again and add some water.", "Once it comes to boil, add the uncooked dhokla in the boiling water.Don\u2019t close the lid of the cooker.", "Just cover it and let it cooker for 40 to 45 minutes on low flame.", "Once it reaches the right consistency and the dhoklas are cooked switch off the gas.", "To know if the dhoklas are cooker, insert a fort in the dhokla and if it comes out clean, it means your dhokla is cooked.Once it is cooked, garnish it with coriander leaves and pour some hot ghee on it to serve.Serve Rajasthani Chawle Wale Dhokle on its own with\u00a0Kachumber Salad\u00a0 for a wweknight dinner."]'::jsonb, 40, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pooja/Rajasthani_Chawle_Wale_Dhokle_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/137.Rajasthani_Chawle_Wale_Dhokle_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Murgh Aur Masoor Dal Recipe-Bombay Style Chicken with Dal', 'murgh-aur-masoor-dal-recipe-bombay-style-chicken-with-dal', 'Murghi Aur Masoor Dal Recipe is a Bombay Style Chicken dal, essentially a rich and delicious curry made from a blend of chicken and whole masoor dal. This dish has a whole lot of flavor captured in just one pot. The addition spices has created complex flavors in the dish.', '["300 grams Chicken , with bone", "1 cup Masoor Dal (Whole)", "2 Onions , sliced", "1 Green Chilli , slit", "1 inch Ginger , chopped", "5 cloves Garlic , chopped", "1 teaspoon Turmeric powder (Haldi)", "2 teaspoon Cumin powder (Jeera)", "1 teaspoon Red Chilli powder", "2 teaspoon Garam masala powder", "1 Lemon juice", "Salt , to taste", "Oil"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'ginger', 'green chilli', 'red chilli powder', 'cloves garlic', 'onion', 'chicken', 'lemon', 'turmeric powder', 'masoor dal', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Murgh Aur Masoor Dal Recipe, wash and soak the whole masoor dal for 3-4 hours.", "Heat up a pressure cooker over medium heat with oil.Add ginger, garlic and saute until the raw smell goes away.", "Add half of the onions and saute till they turn translucent.Add turmeric powder, cumin powder, salt, masoor dal and 2 cups of water and pressure cook for about 5 whistle until the dal is done.Once the pressure has released naturally, open the cooker and use a masher to mash the dal.", "Transfer to aa bowl and set aside.", "Heat the same pressure cooker with oil on medium heat, add remaining onions and saute until they turn translucent.Add the mashed dal and give it a good stir.", "Add remaining spice powders - garam masala, red chilli powder and mix well.Now add the add the cleaned and washed chicken pieces, adjust the seasoning, add about 1 1/2 cups of water and pressure cook for about 2 whistle until the chicken is cooked.", "Turn off thee flame.", "Allow the pressure to release naturally.", "Serve hot.Serve the\u00a0Murgh Aur Masoor Dal Recipe\u00a0along with\u00a0steamed rice\u00a0or\u00a0phulka,\u00a0Carrot, Radish & Peanut Salad with Lemon Recipe\u00a0and\u00a0Onion Raita Recipe - Pyaz Ka Raita Recipe\u00a0to make your complete\u00a0 meal rich and flavorful."]'::jsonb, 55, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/_Murghi_Aur_Masoor_Dal_Recipe_Bombay_Style_Chicken_with_Red_Lentils_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/138._Murghi_Aur_Masoor_Dal_Recipe_Bombay_Style_Chicken_with_Red_Lentils_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gongura Chicken Curry Recipe - Andhra Style Gongura Chicken', 'gongura-chicken-curry-recipe-andhra-style-gongura-chicken', 'Gongura Chicken Curry is Andhra Style Chicken Curry which is a popular in Andhra Pradesh. The Chicken curry is cooked and simmer along with the Gongura masala base which is packed with flavours from simple masala powders which are readily available in your pantry. The addition of roasted methi, coriander seeds and red chillies heightens the flavours of this Gongura Chicken Curry.', '["500 gram Chicken", "2 Onion , finely chopped", "1 Tomato , finely chopped", "4 Green Chillies , slit", "1 inch Ginger , finely chopped", "6 cloves Garlic , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "2 tablespoon Sesame (Gingelly) Oil", "Salt , to taste", "To be roasted", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1 tablespoon Coriander (Dhania) Seeds", "4 Dry Red Chillies", "1 teaspoon Fennel seeds (Saunf)", "1 teaspoon Sesame (Gingelly) Oil", "4 cloves Garlic", "2 cups Sorrel Leaves (Gongura) , picked and chopped", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'sorrel leaves (gongura)', 'fennel seeds (saunf)', 'sesame (gingelly) oil', 'cloves garlic', 'coriander (dhania) seeds', 'onion', 'chicken', 'methi seeds (fenugreek seeds)', 'dry red chillies', 'turmeric powder', 'green chillies', 'garam masala powder']::text[], '["To begin making\u00a0Gongura Chicken Curry Recipe first prep all the ingredients and keep them aside.In a small pan, dry roast the methi seeds, coriander seeds, fennel seeds and red chillies for about 3 to 4 minutes on medium heat, until you notice the seeds crackling.", "Once done, turn off the heat and allow it to cool a bit and blend it into a smooth powder.Heat oil in a pressure cooker over medium heat; add the chopped onions, ginger, garlic and green chillies and saute until the onions are lightly browned and tender.Add the tomatoes, and saute until the tomatoes become soft and mushy.", "Once done add the chicken, the garam masala and turmeric powder.", "Add 1/4 cup of water and pressure cook the chicken for 3 to 4 whistles and turn off the heat.Once done, allow the pressure to release naturally.Make sure there are no stems when you pick the gongura leaves.", "Wash and chop the gongura leaves and keep aside.In another pan,add some oil along garlic and saute the chopped gongura leaves along with a little salt and the ground masala.", "The gongura leaves will wilt almost instantly.", "Saute the gongura in the masala for about 3 to 4 minutes until it becomes like a mushy paste.Once done, add the cooked chicken curry into the Gongura masala and saute on high heat for another 2 minutes and turn off the heat.Check the salt and spices and adjust according to taste.", "Transfer the\u00a0Gongura Chicken Curry to a serving bowl and serve hot.Serve Gongura Chicken Curry with\u00a0Ghee Rice Recipe | Neychoru\u00a0,\u00a0Tomato Onion Cucumber Raita Recipe\u00a0and a\u00a0Semiya Payasam\u00a0for a delicious weekend lunch."]'::jsonb, 45, 'Andhra', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Ghongura_Chicken_Curry_Recipe-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/139.Ghongura_Chicken_Curry_Recipe-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sali Par Eedu Recipe - Parsi Breakfast Eggs On Fried Potato', 'sali-par-eedu-recipe-parsi-breakfast-eggs-on-fried-potato', 'Sali Par Eedu is a traditional Parsi breakfast recipe made with eggs on fried potato straws. A common dish prepared at Parsi homes is now also available at street side stalls and restaurants serving Parsi food.', '["3 cups Potato (Aloo) , julienned to straws", "2 Whole Egg", "1 Tomato , finely chopped", "2 tablespoons Coriander (Dhania) Leaves , chopped", "Salt , as needed", "1 teaspoon Black pepper powder , freshly crushed", "1 tablespoon Ghee"]'::jsonb, ARRAY['tomato', 'salt', 'eggs', 'coriander (dhania) leaves', 'ghee', 'potato (aloo) straws', 'black pepper powder']::text[], '["To begin making Sali Par Eedu Recipe - Parsi Breakfast Eggs On Fried Potato, in a kadai, deep fry the potato straws till they are crisp and golden.", "Strain on a kitchen towel and keep aside.", "You can also air fry them in an air fryer alternatively, for a healthier option.Heat ghee in a pan and add chopped tomatoes and the potato straws and spread to make a thick bed.", "Press gently with a spatula to get a thick even layer.Sprinkle some chopped coriander and break two eggs over the potatoes.", "Sprinkle salt and pepper on the eggs and close with a lid.Cook on low flame till the eggs whites are fully cooked or you can keep the eggs runny also, depending on your preference.", "Once done turn off heat and serve.Serve\u00a0Sali Par Eedu Recipe\u00a0with\u00a0Homemade Whole Wheat Pav Recipe / Ladi Pav\u00a0and a cup of hot\u00a0Masala Chai Recipe\u00a0for weekend brunch."]'::jsonb, 25, 'Parsi', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/shaheen_ali/Parsi_Sali_Par_Eedu_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/140.Parsi_Sali_Par_Eedu_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mangalorean Style Bendekayi Huli Koddel Recipe - Ladies finger Dal without Coconut Recipe', 'mangalorean-style-bendekayi-huli-koddel-recipe-ladies-finger-dal-without-coconut-recipe', 'Mangalorean Style Bendekayi Huli Koddel Recipe  is a variation to the authentic recipe made in the households of Mangalore. Usually in most of the Mangalorean dishes, the addition of coconut is always a must but in this recipe we have cut down coconut and created a dal which has Bendekayi otherwise called as ladies finger.', '["2 cups Bhindi (Lady Finger/Okra)", "1 cup Yellow Moong Dal (Split)", "1 cup Tamarind Water", "1 tablespoon Jaggery", "1 teaspoon Turmeric powder (Haldi)", "1 Green Chilli , chopped", "1 tablespoon Red Chilli powder", "Salt , to taste", "Oil , as needed", "1 teaspoon White Urad Dal (Split)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1 inch Cinnamon Stick (Dalchini)", "4 Dry Red Chillies", "1 tablespoon Coriander (Dhania) Seeds", "1 pinch Asafoetida (hing)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "1 Dry Red Chilli", "1 pinch Asafoetida (hing)", "1 tablespoon Oil", "1 sprig Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['salt', 'yellow moong dal (split)', 'green chilli', 'tamarind water', 'mustard seeds', 'asafoetida (hing)', 'jaggery', 'red chilli powder', 'dry red chilli', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'coriander (dhania) seeds', 'bhindi (lady fingerokra)', 'coriander (dhania) leaves', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Mangalorean Style Bendekayi Huli Koddel Recipe - Ladies finger Dal without Coconut Recipe boil the dal in a pressure cooker with water 1 cup water, green chilli and turmeric powder for about 3 whistle.Release the pressure naturally and keep it aside.In the mean while dry roast the ingredients that are mentioned in the sambar powder list.", "Into a preheated pan first add the urad dal, saute the dal on medium heat till it turn light brown in colour.", "Once done add the mustard seeds, cumin seeds, cinnamon stick, dry red chillies, coriander seeds and\u00a0asafoetida.", "Roast till the aromas come out.", "Turn off the heatOnce done cool it down and grind it into a coarse mixture and keep it aside.Heat a shallow frying Skillet, add tamarind water, jaggery and ladies finger and boil till the stickiness of the vegetable goes away.Add the cooked dal and ground spice mixture.", "Bring it to a boil.", "Check for salt and adjust.For the tempering, heat a small tempering kadai and splutter the mustard seeds,cumin seeds, urad dal, dry red chilli, hing and curry leaf.", "Pour it over the Mangalorean Style Bendekayi Huli Koddel and add the chopped coriander leaves for garnish.", "Serve the Mangalorean Style Bendekayi Huli Koddel Recipe along with\u00a0steam rice\u00a0or\u00a0Phulka\u00a0for lunch or dinner."]'::jsonb, 40, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Mangalorean_Style_Bendekayi_Huli_Koddel_Recipe_Ladies_finger_Dal_without_Coconut_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/141.Mangalorean_Style_Bendekayi_Huli_Koddel_Recipe_Ladies_finger_Dal_without_Coconut_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Nadan Kozhi Recipe | Kerala Chicken Curry | Nadan Chicken Curry', 'nadan-kozhi-recipe-kerala-chicken-curry-nadan-chicken-curry', 'Nadan Kozhi is a lip smacking Kerala Chicken Curry which gets its intense flavour from roasted coconut and whole spices.', '["500 grams Chicken , curry cut", "3 Onions , sliced", "4 Tomatoes , finely chopped", "1 inch Ginger , minced", "10 cloves Garlic , minced", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "2 teaspoon Chicken masala , (you can use other too but I prefer eastern masalas for kerala style preparations)", "1 cup Fresh coconut , grated", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "Curry leaves , Handful", "2 tablespoons Coconut Oil"]'::jsonb, ARRAY['s chicken', 'onions', 'tomatoes', 'ginger', 's garlic', 'red chilli powder', 'turmeric powder', 'haldi', 'chicken masala', 'fresh coconut', 'laung', 'cinnamon stick', 'dalchini', 'curry leaves', 's coconut oil']::text[], '["To begin making the Nadan Kozhi/ Kerala Chicken Curry recipe, prep all the ingredients and keep aside.Heat oil in a large heavy bottom pan heat oil on medium flame.", "Add onions, ginger, and garlic and saut\u00e9 till the onion is deep brown and well cooked.", "While the onions are getting cooked, in a separate pan, on low heat dry roast the grated coconut to a golden brown colour.Add the whole spices - cloves and cinnamon to the coconut , mix well and turn off the heat.", "Keep aside to cool.", "This is will also help in dry spices infusing some of their flavour in the roasted coconut.", "Once cool, grind the spices and coconut to a smooth paste using very little water.Once the onions have turned deep brown, add the chicken masala, turmeric powder, chilli powder, salt and saut\u00e9 for another minute.", "Add tomatoes and fry till the oil separates and the tomato turns mushy and soft.Add the coconut and spice paste along with chicken pieces, mix and saut\u00e9 till the chicken is well coated with spices.Add about 1 cup water and cook covered on low flame for about 15 to 20 mins or the Nadan Chicken Curry/ Kerala chicken is are cooked thoroughly.Garnish it with curry leaves on top and check the salt and spices and adjust taste and turn off the heat.Transfer the\u00a0Nadan Kozhi/ Kerala Chicken Curry to a serving bowl and serve hot.Serve Nadan Kozhi/ Kerala Chicken Curry as a Sunday brunch along with\u00a0appam\u00a0or\u00a0Kerala Style Whole Wheat Parotta Recipe\u00a0and\u00a0Seer Fish Fry Recipe\u00a0by the side to enjoy your meal."]'::jsonb, 50, 'Kerala', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Monika_Manchanda/Nandan_Kozhi__Kerala_Style_Chicken_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/142.Nandan_Kozhi__Kerala_Style_Chicken_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Chicken Recipe | Pepper Chicken Dry | South Indian', 'chettinad-chicken-recipe-pepper-chicken-dry-south-indian', 'Chettinad Dry Pepper Chicken Recipe is very easy to make and tastes delicious.', '["To Marinate Chicken", "500 grams Chicken , (chicken with bones gives better taste)", "10 cloves Garlic", "2 inch Ginger", "1/2 teaspoon Turmeric powder (Haldi)", "1 Lemon , juice extracted", "2 Onion , finely chopped", "5 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "1 Tomato , finely chopped", "2 sprig Curry leaves , roughly torn", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera) , roasted", "1 teaspoon Fennel Powder , roasted", "1 tablespoon Coriander Powder (Dhania) , roasted", "2-1/2 tablespoon Black pepper powder", "Salt , to taste", "Oil , as required", "Water , as required", "Coriander (Dhania) Leaves , for garnish"]'::jsonb, ARRAY['to marinate chicken', 's chicken', 's garlic', 'ginger', 'turmeric powder', 'haldi', 'lemon', 'onion', 'tomato', 'curry leaves', 'cumin powder', 'jeera', 'fennel powder', 'coriander powder', 'dhania', 'black pepper powder', 'salt', 'oil', 'water', 'coriander']::text[], '["To begin making the Chettinad Dry Pepper Chicken Recipe, clean the chicken thoroughly and wash it well.First step is to marinate the chicken.", "Make a paste of the ginger and garlic by grinding in a mixer grinder or a pestle and mortar.", "Into a large mixing now, add the chicken pieces along with bones, turmeric powder, ginger garlic paste, lemon juice and salt.", "Mix well to combine.", "Cover the pan, place it in the refrigerator and marinate the chicken for 30 minutes.Heat oil in a kadai/wok\u00a0on medium flame, add the chopped onions, ginger and garlic and saut\u00e9 till onions turn soft and lightly brown.Add curry leaves and stir well for a few seconds.At this stage add finely chopped tomatoes and cook till tomatoes turn soft and mushy.", "This will take about 3-4 minutes.", "Now add the marinated Chettinad Chicken and let it cook for 3-5 minutes.", "Add all the spice powders -\u00a0cumin powder,\u00a0fennel seeds powder,\u00a0coriander powder,\u00a0crushed pepper or pepper powder and salt.Cover the pan and sprinkle a little water and cook the Chettinad Chicken until the chicken is tender.Once done, check the salt and pepper and adjust accordingly and cook the Chettinad Pepper Chicken in the open for another couple of minutes to evaporate excess moisture.Once done, turn off the heat and stir in the chopped coriander leaves.", "Transfer the Chettinad Pepper Chicken to a serving bowl and serve hot.Serve\u00a0Chettinad Dry Pepper Chicken Recipe\u00a0with\u00a0Pickled onions\u00a0as an appetizer.", "Or you could also serve it as a side dish to a meal along wit\u00a0Steamed rice\u00a0and\u00a0Milagu Rasam Recipe for lunch or dinner."]'::jsonb, 40, 'Chettinad', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Chettinad_Pepper_Chicken_Dry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/143.Chettinad_Pepper_Chicken_Dry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mint Flavoured Mixed Vegetable Pulao Recipe', 'mint-flavoured-mixed-vegetable-pulao-recipe', 'Mint Flavoured Mixed Vegetable Pulao Recipe is a rice recipe which would be an all time heart stealer on your feast table. A hint of mint takes your regular pulao a notch higher. This is an easy to prepare weeknight pulao recipe because of its ease to be prepared.', '["1/4 cup Basmati rice , cooked", "1/4 cup Green peas (Matar)", "1/2 cup Carrot (Gajjar) , chopped", "1/2 cup Green beans (French Beans) , chopped", "1 Onion , chopped", "Salt , to taste", "1 tablespoon Coriander (Dhania) Leaves , chopped", "3 tablespoons Mint Leaves (Pudina) , chopped/or dried pudina, crushed", "Oil , to cook", "1 teaspoon Garlic , crushed", "3 Green Chillies , chopped", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Bay leaf (tej patta)", "3 Cloves (Laung)"]'::jsonb, ARRAY['basmati rice', 'green beans (french beans)', 'salt', 'mint leaves (pudina) dried pudina', 'coriander (dhania) leaves', 'mustard seeds', 'bay leaf (tej patta)', 'green peas (matar)', 'carrot', 'onion', 'garlic', 'cumin seeds (jeera)', 'cloves (laung)', 'green chillies', 'sunflower oil']::text[], '["To begin making Mint Flavoured Mixed Vegetable Pulao Recipe, prep all the ingredients and veggies needed.", "Chop carrots, beans and coriander leaves and also pudina leaves if you are using fresh ones.", "If you use dried pudina leaves, crush them between your palms and keep ready.Also soak basmati rice in a pressure cooker for 20 minutes and cook for 2 whistles and wait till the pressure releases.", "Once done, fluff it up and keep ready.Heat oil in pan or kadai and once the oil is hot, add mustard seeds and allow them to splutter.Once the mustard seeds splutter, throw in the cumin seeds and allow them to sizzle.Once they sizzle, immediately add the bay leaf, clove, and saute a bit.", "Add the onions and saute till translucent.", "Once done, add the crushed garlic and saute till the are cooked.", "Now, add the chopped chillies, chopped carrots, beans, peas and saut\u00e9 for about 2 minutes.", "At this stage, add the chopped mint leaves if you are using fresh leaves, and saute till the leaves wilt a bit and the veggies are cooked al dente.Add cooked basmati rice and mix carefully with a spatula, so that the rice is not broken or made mushy.At this point, season the pulao \u00a0with dried and crushed mint leaves if using the dried leaves and stir until it coats all the rice well.", "Remember to keep flame high and toss well on high heat and switch off.", "Sprinkle coriander leaves.", "Serve hot.Mint Flavoured Mixed Vegetable Pulao Recipe can be served with a\u00a0Dangar Pachadi With Grated Carrots Recipe (Urad Dal Raita)\u00a0and a\u00a0Tindora Ka Salan Recipe\u00a0for a weeknight dinner."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/gricha874-gmail.com/Mint_Flavoured_Mixed_Vegetable_Pulao_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/144.Mint_Flavoured_Mixed_Vegetable_Pulao_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mint Flavoured Mixed Vegetable Pulao Recipe', 'mint-flavoured-mixed-vegetable-pulao-recipe-2', 'Mint Flavoured Mixed Vegetable Pulao Recipe is a rice recipe which would be an all time heart stealer on your feast table. A hint of mint takes your regular pulao a notch higher. This is an easy to prepare weeknight pulao recipe because of its ease to be prepared.', '["1/4 cup Basmati rice , cooked", "1/4 cup Green peas (Matar)", "1/2 cup Carrot (Gajjar) , chopped", "1/2 cup Green beans (French Beans) , chopped", "1 Onion , chopped", "Salt , to taste", "1 tablespoon Coriander (Dhania) Leaves , chopped", "3 tablespoons Mint Leaves (Pudina) , chopped/or dried pudina, crushed", "Oil , to cook", "1 teaspoon Garlic , crushed", "3 Green Chillies , chopped", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Bay leaf (tej patta)", "3 Cloves (Laung)"]'::jsonb, ARRAY['basmati rice', 'green beans (french beans)', 'salt', 'mint leaves (pudina) dried pudina', 'coriander (dhania) leaves', 'mustard seeds', 'bay leaf (tej patta)', 'green peas (matar)', 'carrot', 'onion', 'garlic', 'cumin seeds (jeera)', 'cloves (laung)', 'green chillies', 'sunflower oil']::text[], '["To begin making Mint Flavoured Mixed Vegetable Pulao Recipe, prep all the ingredients and veggies needed.", "Chop carrots, beans and coriander leaves and also pudina leaves if you are using fresh ones.", "If you use dried pudina leaves, crush them between your palms and keep ready.Also soak basmati rice in a pressure cooker for 20 minutes and cook for 2 whistles and wait till the pressure releases.", "Once done, fluff it up and keep ready.Heat oil in pan or kadai and once the oil is hot, add mustard seeds and allow them to splutter.Once the mustard seeds splutter, throw in the cumin seeds and allow them to sizzle.Once they sizzle, immediately add the bay leaf, clove, and saute a bit.", "Add the onions and saute till translucent.", "Once done, add the crushed garlic and saute till the are cooked.", "Now, add the chopped chillies, chopped carrots, beans, peas and saut\u00e9 for about 2 minutes.", "At this stage, add the chopped mint leaves if you are using fresh leaves, and saute till the leaves wilt a bit and the veggies are cooked al dente.Add cooked basmati rice and mix carefully with a spatula, so that the rice is not broken or made mushy.At this point, season the pulao \u00a0with dried and crushed mint leaves if using the dried leaves and stir until it coats all the rice well.", "Remember to keep flame high and toss well on high heat and switch off.", "Sprinkle coriander leaves.", "Serve hot.Mint Flavoured Mixed Vegetable Pulao Recipe can be served with a\u00a0Dangar Pachadi With Grated Carrots Recipe (Urad Dal Raita)\u00a0and a\u00a0Tindora Ka Salan Recipe\u00a0for a weeknight dinner."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/gricha874-gmail.com/Mint_Flavoured_Mixed_Vegetable_Pulao_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/145.Mint_Flavoured_Mixed_Vegetable_Pulao_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mixed Vegetable Koora Recipe - Mixed Vegetable Poriyal', 'mixed-vegetable-koora-recipe-mixed-vegetable-poriyal', 'Kalle Koora also known as the Mixed Vegetable Koora Recipe is a mixed winter vegetable curry or poriyal specially made during Sankranti festival using the freshly harvested winter vegetables like Sweet potato, Potato, Broad beans, Carrots and Fenugreek leaves.', '["1 Sweet Potato , peeled and diced", "2 Potatoes (Aloo) , peeled and diced", "1 Carrot (Gajjar) , peeled and diced", "2 cups Avarekai (Broad Beans) , chopped", "2 cups Methi Leaves (Fenugreek Leaves) , chopped", "8 Green Chillies", "1/4 cup Water", "3 tablespoons Sesame seeds (Til seeds)", "1/4 cup Fresh coconut", "1 tablespoon Jaggery", "Salt , to taste", "1/4 teaspoon Turmeric powder (Haldi)", "2 tablespoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'coconut', 'mustard seeds', 'methi leaves (fenugreek leaves)', 'jaggery', 'water', 'carrot', 'curry leaves', 'sesame seeds (til seeds)', 'cumin seeds (jeera)', 'avarekai (broad beans)', 'potato (aloo)', 'turmeric powder', 'green chillies', 'sweet potato', 'sunflower oil']::text[], '["To begin making Kalle Koora/Mixed Vegetable Koora Recipe, roast the sesame seeds on low heat until they are golden.Cool them to room temperature and grind into a coarse powder along with grated coconut and Jaggery.", "Set aside until needed.", "In a mixer, add the green chillies along with turmeric powder.", "Keep aside.Pressure cook the vegetables in 1/4 cup of water for 3 to 4 whistles and turn off the heat.", "Release the pressure immediately.Place a heavy bottomed pan on medium flame and add a 1 tablespoon of oil.", "Once the oil is hot add the mustard seeds, cumin seeds and curry leaves.", "Allow then to crackle.", "Add in the coconut jaggery sesame mixture and the ground green chilli paste and saute for a minute or two until raw flavour of the green chillies disappears.", "Next add in the chopped vegetables, stir the Kalle Koora/Mixed Vegetable Koora well and saute for couple of minutes\u00a0until moisture released from the jaggery evaporates.", "Turn off the heat, check the salt and spices and adjust accordingly.", "Transfter the\u00a0Kalle Koora/Mixed Vegetable Koora to a serving bowl and serve hot.Serve Kalle Koora/Mixed Vegetable Koora recipe along with Steamed Rice,\u00a0Moong Dal Rasam/Pesara Pappu Charu Recipe\u00a0and\u00a0Nuggekai Kharbyaali Recipe (North Karnataka Spiced Drumstick Sambar)\u00a0for a truly complete and wholesome lunch."]'::jsonb, 35, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swapna_sunil/Kalle_koora_-_Mixed_winter_vegetable_curry_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/146.Kalle_koora_-_Mixed_winter_vegetable_curry_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kothamalli Karuveppilai Sadam Recipe - Coriander And Curry Leaves Rice', 'kothamalli-karuveppilai-sadam-recipe-coriander-and-curry-leaves-rice', 'Kothamalli Karuveppilai Sadam Recipe is a simple South Indian Style Coriander and Curry Leaves Rice which can be prepared for your Lunch Box. As it is easy to make and gets ready in no time, it is perfect for your busy days and can be eaten for your weeknight dinner too.', '["2 cups Cooked rice", "Salt , to taste", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "1/2 teaspoon Turmeric powder (Haldi)", "1/4 cup Roasted Peanuts (Moongphali)", "2 teaspoons Sambar Powder", "1 tablespoon Gingelly oil , for cooking", "To be ground", "1/4 cup Fresh coconut", "1 cup Coriander (Dhania) Leaves", "1/2 cup Curry leaves", "Ghee , for flavour"]'::jsonb, ARRAY['salt', 'rice', 'mustard seeds', 'coconut', 'coriander (dhania) leaves', 'curry leaves', 'curry leaves', 'white urad dal (split)', 'gingelly oil', 'peanuts (moongphali)', 'turmeric powder', 'sambar powder', 'ghee flavour']::text[], '["To begin making the Kothamalli Karuveppilai Sadam Recipe, get all the ingredients and keep them ready.Add the coriander leaves, curry leaves along with the coconut into a mixer grinder and blend to make a coarse mixture.", "Don\u2019t add any water.", "The mixture needs to be dry.", "Ensure you have some cooked rice ready; using a day old rice will help.", "If you are cooking fresh rice, allow the rice to cool completely and toss it in a little oil, so it does not stick together.The next step is to make the Kothamalli Karuveppilai Sadam.", "Heat oil over medium heat in a heavy bottomed pan or a Kadhai.", "Add the mustard seeds, urad dal amd cook till the dal turns golden brown in colour.Once done, stir in the curry leaves and let it splutter.", "Next. and in the ground Kothamalli Karuveppilai mixture and mix everything.", "Once done, add turmeric powder, sambar powder and saute for a few seconds.", "Finally, add the cooled cooked rice, salt and stir to combine all the ingredients well to make the Kothamalli Karuveppilai sadam.Finally stir in the roasted peanuts, a little ghee or oil and stir to combine.Serve the\u00a0Kothamalli Karuveppilai Sadam Recipe\u00a0along with a\u00a0Tomato Onion Cucumber Raita\u00a0and\u00a0Elai Vadam\u00a0for lunch or even pack it into your lunch box."]'::jsonb, 45, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sandhya-archanaskitchen.com/Kothamalli_Karuveppilai_Sadam_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/147.Kothamalli_Karuveppilai_Sadam_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karwar Style Dali Thoy Recipe - Toor dal Curry', 'karwar-style-dali-thoy-recipe-toor-dal-curry', 'The Karwar Style Dali Thoy Recipe (Toor dal Curry) is a quintessential of Konkani dish which is popular among Mangaloreans from Kongunadu. It is a spiced toor dal stew dish which is a simple dish. When you crave for something very light, comforting yet delicious you can rely on this simple curry.', '["1 cup Arhar dal (Split Toor Dal)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1/2 tablespoon Ghee", "3 Dry Red Chillies", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 pinch Asafoetida (hing)", "1 sprig Curry leaves", "Coriander (Dhania) Leaves , few, for garnish"]'::jsonb, ARRAY['salt', 'arhar dal (split toor dal)', 'ghee', 'mustard seeds', 'asafoetida (hing)', 'coriander (dhania) leaves', 'curry leaves', 'dry red chillies', 'turmeric powder']::text[], '["To prepare Karwar Style Dali Thoy Recipe (Toor dal Curry), rinse toor dal in water and then pressure cook with 1 cup water and turmeric powder for about 2 whistles.turn off the flame an allow the pressure to release naturally.", "In a pan heat ghee on medium flame.", "Add mustard seeds and let it splutter.Then add dried red chilies, hing, and curry leaves.", "Saute till curry leaves splutter and turn off the heat.Mash the cooked dal well, add salt to taste.", "Add the tempering and fresh coriander leaves.", "Mix well.Serve the\u00a0Karwar Style Dali Thoy Recipe (Toor dal Curry)\u00a0with\u00a0steamed rice\u00a0to make a simple satisfying meal."]'::jsonb, 25, 'Coastal Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/Dali_Thoy_Karwar_Toor_dal_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/148.Dali_Thoy_Karwar_Toor_dal_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kathirikai Gothsu / Gotsu Recipe - South Indian Style Spicy and Tangy Eggplant Curry', 'kathirikai-gothsu-gotsu-recipe-south-indian-style-spicy-and-tangy-eggplant-curry', 'Kathirikai Gothsu Recipe is a tangy gravy preparation of brinjal/eggplant that is cooked soft with the least amount of spices. Sambar powder is added which makes this recipe mouthwatering.', '["1 Brinjal (Baingan / Eggplant) , diced", "10 Pearl onions (Sambar Onions) , quatered", "2 Tomatoes , quartered", "1 inch Ginger , finely chopped", "1/2 cup Tamarind Water", "1 teaspoon Sambar Powder", "1/4 teaspoon SSP Asafoetida (Hing)", "1/2 teaspoon Turmeric powder (Haldi)", "1 tablespoon Jaggery", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1 tablespoon Gingelly oil", "Salt , to taste", "Coriander (Dhania) Leaves , for garnish"]'::jsonb, ARRAY['brinjal', 'baingan / eggplant', 'pearl onions', 'sambar onions', 'tomatoes', 'ginger', 'tamarind water', 'sambar powder', 'ssp asafoetida', 'hing', 'turmeric powder', 'haldi', 'jaggery', 'mustard seeds', 'rai/ kadugu', 'curry leaves', 'gingelly oil', 'salt', 'coriander', 'dhania']::text[], '["To begin making Kathirikai Gothsu Recipe, into a preheated pressure cooker add gingelly oil.Once the oil is hot, add mustard seeds and allow it to crackle.After the mustard seeds crackle, add the asafoetida, curry leaves, sambar onions and ginger and saute till onions soften a little.Once done add in the diced eggplant, tomatoes, tamarind water, turmeric powder, a pinch of asafoetida, sambar powder, salt to taste, jaggery and quarter cup of water.", "Stir to combine all the ingredients.Close the pressure cooker with its lid and pressure cook for 3 to 4 whistles.", "After 4 whistles turn off the heat and let the pressure release naturally.", "After the pressure has released, open the lid and stir in the freshly chopped coriander leaves.Transfer the\u00a0Kathirikai Gothsu to a serving bowl and serve hot.Serve\u00a0Kathirikai\u00a0Gothsu Recipe along with\u00a0Ven Pongal\u00a0and\u00a0South Indian Filter Coffee\u00a0for a delicious South Indian breakfast."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/kathirikai_gothsu_recipe_tangy_and_spicy_brinjal_curry_7_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/149.kathirikai_gothsu_recipe_tangy_and_spicy_brinjal_curry_7_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kasuri Methi Paneer Sabzi Recipe', 'kasuri-methi-paneer-sabzi-recipe', 'Kasuri Methi Paneer Sabzi Recipe is a delicious combination of creamy cottage cheese tossed with dried fenugreek leaves or methi leaves. The addition of onion and tomatoes to the fenugreek leaves imparts a unique aroma to the recipe.  Toss in a few basic ingredients in your kitchen with paneer and tomato and enjoy a delicious weeknight dinner with Kasuri Methi Paneer Sabzi Recipe.', '["1 cup Paneer (Homemade Cottage Cheese) , cubed", "2 Onions , finely chopped", "2 Tomatoes , finely chopped", "1 teaspoon Ginger , finely chopped", "1 teaspoon Garlic , finely chopped", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin seeds (Jeera)", "2 teaspoon Red Chilli powder", "2-1/2 teaspoon Garam masala powder", "2 tablespoons Kasuri Methi (Dried Fenugreek Leaves)", "Salt , to taste", "Oil , as required"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'paneer', 'red chilli powder', 'garlic', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making\u00a0 Kasuri Methi Paneer Sabzi Recipe, in a non-stick stir fry pan, add cooking oil and heat it over medium heat.Once the oil is hot, add cumin seeds and let them sizzle.Then add finely chopped onion and saute till\u00a0\u00a0they become transparent; Add tomatoes and cook until they become soft and mushy.Add the masala powders, red chilli powder, garam masala and saute for a minute.Crush methi leaves with your hand and stir them well into the pan .Add required amount of salt.Add the paneer pieces to the spicy mixture in the pan.Combine\u00a0Kasuri Methi Paneer Sabzi them well and simmer for about 3 - 4 minutes.", "Do not saute often after adding paneer, as the paneer pieces may break and crumble.Switch off the flame and add garnish Kasuri Methi Paneer Sabzi with chopped coriander leaves.Serve\u00a0Kasuri Methi Paneer Sabzi with\u00a0Roti/Phulka\u00a0or\u00a0Chapati/Tawa Paratha.", "You can even serve it as an starter to your party meal made of\u00a0Peshawari Chole Recipe\u00a0and\u00a0Sindhi Pulao Recipe."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Ketaki/Kasuri_Methi_Paneer_Sabzi_Recipe1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/150.Kasuri_Methi_Paneer_Sabzi_Recipe1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Badanekaayi Gojju (Brinjal Curry) Recipe', 'badanekaayi-gojju-brinjal-curry-recipe', 'Badanekaayi Gojju or Brinjal curry is one lip-smacking curry. A creamy, spicy, tangy curry that can be served with roti or rice. If you are bored of the usual Brinjal sabzi, you can give this recipe a try and it will surely be loved by your family members.', '["10 Small Brinjal (Baingan / Eggplant)", "2 Onion , finely chopped", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "Salt , to taste", "4 tablespoons Oil", "Coriander (Dhania) Leaves , for garnishing", "Roasted Peanuts (Moongphali) , for garnishing", "1/4 cup Fresh coconut , freshly grated", "2 tablespoons Raw Peanuts (Moongphali)", "2 tablespoons Tamarind Paste", "2 Dry Red Chillies", "2 tablespoons Cumin seeds (Jeera)", "1 tablespoon Red Chilli powder", "1 tablespoon Turmeric powder (Haldi)", "1 tablespoon Salt"]'::jsonb, ARRAY['small brinjal', 'baingan / eggplant', 'onion', 'mustard seeds', 'rai/ kadugu', 'salt', 's oil', 'coriander', 'dhania', 'roasted peanuts', 'moongphali', 'fresh coconut', 's raw peanuts', 's tamarind paste', 'dry red chillies', 's cumin seeds', 'jeera', 'red chilli powder', 'turmeric powder', 'haldi']::text[], '["To begin with Badanekaayi Gojju, firstly wash the brinjals and slit them cross wise.Mix all the ingredients mentioned under \u2018For filling\u2019 in a mixing bowl and fill it into the brinjals.Let them sit for some time, till you get everything else ready.", "Blend all the ingredients listed under \u2018For the paste\u2019 to make a smooth paste, using enough water.In a wide pan, heat the oil.", "Add mustard seeds and let it crackle.When it crackles, add the chopped onions and saut\u00e9 till it turns pink.", "Add brinjal and the remaining filling into the pan and saut\u00e9.Cover and cook till the brinjal is 3/4th cooked.", "Add the ground paste and 1 cup water.Add salt and jaggery, cover and cook.", "Cook till the gravy thickens and the brinjal is cooked well.Garnish is with some coarsely crushed peanuts and coriander leaves.Serve Badanekaayi Gojju with\u00a0Whole Wheat Lachha Paratha\u00a0and\u00a0Lauki raita\u00a0for a perfect weekday lunch."]'::jsonb, 75, 'South Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuri_Aggarwal/Badanekaayi_Gojju__Brinjal_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/151.Badanekaayi_Gojju__Brinjal_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Capsicum In Coconut And Peanut Gravy Recipe', 'capsicum-in-coconut-and-peanut-gravy-recipe', 'Capsicum In Coconut And Peanut Gravy is a delicious gravy recipe which you can make for your everyday food. Flavours of Capsicum come out very well along with peanuts. Addition of coconut makes the gravy rich and nourishing. You can also pack this for your lunch box with parathas and your choice of raita.', '["3 Green Bell Pepper (Capsicum) , or any other colour of your choice", "1 Onion", "2 Tomatoes", "1 teaspoon Garam masala powder", "Turmeric powder (Haldi) , a pinch", "1 teaspoon Ginger Garlic Paste", "1/2 cup Water", "Salt , to taste", "1/2 teaspoon Cumin seeds (Jeera)", "1 tablespoon Red Chilli powder", "1 tablespoon Oil", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "4 tablespoons Raw Peanuts (Moongphali)", "1 teaspoon Sesame seeds (Til seeds)", "1 tablespoon Coriander (Dhania) Seeds", "3 tablespoons Fresh coconut"]'::jsonb, ARRAY['reen bell pepper', 'capsicum', 'onion', 'tomatoes', 'garam masala powder', 'turmeric powder', 'haldi', 'ginger garlic paste', 'water', 'salt', 'cumin seeds', 'jeera', 'red chilli powder', 'oil', 'kasuri methi', 'dried fenugreek leaves', 's raw peanuts', 'moongphali', 'sesame seeds', 'til seeds', 'coriander', 'dhania', 's fresh coconut']::text[], '["To begin making the Capsicum In Coconut And Peanut Gravy Recipe, firstly dry roast peanuts, sesame seeds, coriander seeds for about 20 seconds.", "Cool completely and make a fine paste along with coconut and keep aside.Heat oil in a heavy bottomed pan, temper with cumin seeds and add ginger garlic paste.", "Fry till raw smell goes off and add onions.When the onions turn translucent, add tomatoes, turmeric powder, salt, mix well and cook covered until tomatoes turn mushy.", "This will take about 3 to 4 minutes.When the tomatoes are mushy, mash them well using the back of the spoon and fry until the water evaporates and onion tomato mixture looks like a paste.Now, add coconut peanut paste and cook for about 3 to 4 minutes.", "Add red chilli powder, garam masala, water and bring to boil.Now, add\u00a0capsicum\u00a0and cook covered for 5 to 10 minutes.", "After 5 to 10 minutes, add Kasuri Methi, mix well and serve.Serve\u00a0Capsicum In Coconut And Peanut Gravy\u00a0Recipe along with\u00a0Tawa Paratha\u00a0and\u00a0Palak Raita\u00a0for your everyday meal."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/anu.mallajosyula-gmail.com/Capsicum_in_Coconut_and_peanut_gravy.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/152.Capsicum_in_Coconut_and_peanut_gravy.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Singhara Pulao Recipe - Water Chestnut Mixed Rice', 'singhara-pulao-recipe-water-chestnut-mixed-rice', 'Singhara Pulao Recipe (Water Chestnut Mixed Rice Recipe) is a fasting recipe that can be often prepared during the Navratri season. As during that time of the year people usually avoid dishes that contains onion, garlic and any root vegetables. Singhara is often consumed in many ways, even the flour is used to make thalipeeth and khichdi.', '["300 grams Singhade (water chestnut) , pressure cooked and skin peeled", "2 cups Cooked rice", "1 Bay leaf (tej patta)", "1 Star anise", "2 Cloves (Laung)", "2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "2 teaspoon Black pepper powder", "Oil", "2 sprig Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['salt', 'rice', 'bay leaf (tej patta)', 'singhade (water chestnut) pressure skin', 'coriander (dhania) leaves', 'cumin seeds (jeera)', 'black pepper powder', 'turmeric powder', 'cloves (laung)', 'star anise', 'sunflower oil']::text[], '["To begin making the Singhara Pulao Recipe (Water Chestnut Rice Recipe), keep the cooked rice ready.Pressure cook the water chestnuts with water for at least 8 whistles and allow it to rest for few seconds until it releases pressure naturally.Once done, take the water chestnuts out and peel off the black skin and keep the see aside.", "Chop them into half.In a kadai, heat some oil, add cumin seeds, bay leaf, cloves and star anise and allow it to sizzle.Add in cooked water chestnuts, salt to taste, turmeric powder and pepper powder.", "Saute until they are well combined.", "This will take about 2 minutes.After 2 minutes, add the cooked rice and toss it over gently until the rice is coated evenly and serve hot by sprinkle some chopped coriander leaves on top.Serve the\u00a0Singhara Pulao Recipe along with a\u00a0Palak Makhana Recipe\u00a0and\u00a0Makhana Moongphali Ki Kadhi\u00a0to make it a complete meal."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Singhara_Pulao_Recipe_Water_Chestnut_Rice_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/153.Singhara_Pulao_Recipe_Water_Chestnut_Rice_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mulakootal (Vegetables In Coconut Gravy) Recipe', 'mulakootal-vegetables-in-coconut-gravy-recipe', 'Mulakootal is essentially a home style south Indian curry made with a medley of vegetables, lentils and coconut. A part of many routine lunches and often made with whatever vegetables handy at home. Mulakootal is also said to be the inspiration behind the famous "Mulligatawny Soup". The curry is healthy and spells comfort of a home meal in every bite, helps that it is super easy to make.', '["2 cups Mixed vegetables", "1/2 cup Arhar dal (Split Toor Dal)", "1 teaspoon Turmeric powder (Haldi)", "To be ground in a paste", "1/2 cup Fresh coconut , grated", "2 tablespoons White Urad Dal (Split)", "2 teaspoon Mustard seeds (Rai/ Kadugu)", "3 Dry Red Chillies", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies", "Curry leaves , handful"]'::jsonb, ARRAY['arhar dal (split toor dal)', 'coconut', 'mustard seeds', 'mixed vegetables', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'cumin seeds (jeera)', 'coconut oil', 'turmeric powder']::text[], '["To begin making the Mulakootal recipe, firstly wash, peel and dice all vegetables.", "You can use any vegetables you have at home.", "I like to use vegetables like carrot, lauki, drumstick, beans, potato, white pumpkin and cauliflower.In a large pot (use an earthen pot if you have, the flavour is lovely)or in a pressure cooker, boil all the vegetables with little water with salt and turmeric.In an another pressure cooker, boil the toor dal and keep it aside.Dry roast all the ingredients for the paste apart from coconut for 2-3 minutes till fragrant and slight brown.Grind together coconut and the roasted spices to a smooth paste adding little water if required.Add the toor dal and coconut paste to the boiled vegetables and let it simmer further for 5 minutes till the flavours have blended and the raw smell of coconut has gone.In a small tadka pan, heat coconut oil and add mustard seeds, red chilly and curry leaves and saut\u00e9 for 2 minutes.Pour this over the curry and it is ready to be served.", "Serve Mulakootal with hot steamed rice for a perfect summer lunch."]'::jsonb, 45, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Monika_Manchanda/Mulakootal_Vegetables_in_Coconut_Gravy.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/154.Mulakootal_Vegetables_in_Coconut_Gravy.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Olya Kaju Chi Amti Recipe - Malvani Cashew Nut Curry', 'olya-kaju-chi-amti-recipe-malvani-cashew-nut-curry', 'Olya Kaju Chi Amti Recipe is a simple dish packed with flavours. A recipe from the Malvani cuisine, a combination of toor dal and masoor dal are cooked together, and given a tadka of freshly ground masala and not to forget the star of the dish the cashew nuts.', '["1/4 cup Cashew nuts", "1/2 cup Arhar dal (Split Toor Dal) , washed", "1/2 cup Masoor Dal (Whole) , washed", "Salt , to taste", "1/2 teaspoon Turmeric powder (Haldi)", "1 tablespoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Asafoetida (hing)", "2 Dry Red Chillies", "1 teaspoon Jaggery", "1/4 cup Fresh coconut , grated", "1 teaspoon Cumin seeds (Jeera)", "1 Dry Red Chilli", "6 cloves Garlic"]'::jsonb, ARRAY['cashew nuts', 'salt', 'arhar dal (split toor dal)', 'ghee', 'mustard seeds', 'asafoetida (hing)', 'coconut', 'jaggery', 'cloves garlic', 'dry red chilli', 'dry red chillies', 'cumin seeds (jeera)', 'turmeric powder', 'masoor dal']::text[], '["To begin making the Olya Kaju Chi Amti Recipe, in a pressure cooker, combine the washed toor dal and masoor dal along with a cup of water, some turmeric powder, salt and close the pressure cooker.", "Pressure cook the dal for 3-4 whistles and turn off the flame.", "Allow the pressure to release naturally.", "In a small skillet, dry roast the freshly grated coconut, cumin seeds, dry red chilli and garlic cloves, until the coconut starts turning into a light brown colour.", "After about 4-5 minutes, turn off the flame and allow it cool.", "Transfer the coconut mixture into a mixer-jar and grind into a coarse mixture.", "Set aside.", "Heat a saucepan with 1/2 a cup of water, bring it to a rolling boil.", "To this add the cashew nuts and turn off the flame.", "Allow the cashew nuts to sit in the water for about 15 minutes.", "After 15 minutes, drain the water and set aside.", "Heat a kadai with ghee on medium heat; once the ghee is hot, add in the cumin seeds and mustard seeds, allowing it to splutter.", "Next add the dry red chilli, asafoetida, and the cashew nuts, Saute for a couple of minutes, until the cashew start turning into a light brown colour.", "Next, add the freshly ground coconut masala and give it a good mix.", "Finally add in the boiled dal and bring the Olya Kaju Chi Amti to a single boil.", "Adjust the consistency of the Olya Kaju Chi Amti to your liking.", "Turn off the heat and transfer the\u00a0Olya Kaju Chi Amti to a serving bowl and serve hot.Serve\u00a0Olya Kaju Chi Amti along with\u00a0Steamed Rice,\u00a0Malvani Kurkuri Bhindi Recipe - Moongphali Bhindi Sabzi, a bowl of fresh dahi for a simple weekday meal."]'::jsonb, 40, 'Malvani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Olya_Kaju_Chi_Amti_Recipe_-_Malvani_Style_Cashew_Nut_Curry_With_Dal-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/155.Olya_Kaju_Chi_Amti_Recipe_-_Malvani_Style_Cashew_Nut_Curry_With_Dal-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('अरबी मसाला कसूरी मेथी के साथ - Arbi Masala (Recipe In Hindi)', 'arbi-masala-recipe-in-hindi', 'यह स्वादिष्ट और पौष्टिक अरबी की सब्जी कसूरी मेथी के साथ बनाई गई है। मसालो और कसूरी मेथी के जायके से भरी मसालेदार यह सब्जी आप कभी भी बना सकते है। आप इस सब्जी को अपने लंच बॉक्स में भी पैक कर सकते है.', '["250 \u0917\u094d\u0930\u093e\u092e \u0905\u0930\u092c\u0940 , \u0909\u092c\u0932\u0940 \u0914\u0930 \u0917\u094b\u0932\u093e\u0915\u093e\u0930 \u0915\u093e\u091f\u0940 \u0939\u0941\u0908", "1/4 \u0915\u092a \u091f\u092e\u093e\u091f\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0905\u0926\u0930\u0915 , \u092a\u0947\u0938\u094d\u091f", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0932\u0939\u0938\u0941\u0928 , \u092a\u0947\u0938\u094d\u091f", "1/4 \u092a\u094d\u092f\u093e\u091c , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f\u093e \u0939\u0941\u0906", "1 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u092c\u093e\u0930\u0940\u0915 \u0915\u091f\u0940 \u0939\u0941\u0908", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0905\u092e\u091a\u0942\u0930 \u092a\u093e\u0909\u0921\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0905\u091c\u0935\u093e\u0907\u0928 , \u0925\u094b\u095c\u0940", "\u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u0925\u094b\u095c\u093e (\u0915\u091f\u093e \u0939\u0941\u0906)", "\u0939\u0940\u0902\u0917 , \u091a\u0941\u091f\u0915\u0940 \u092d\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0915\u0938\u0942\u0930\u0940 \u092e\u0947\u0925\u0940", "2 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u0924\u0947\u0932"]'::jsonb, ARRAY['ग्राम अरबी', 'कप टमाटर', 'छोटा चमच्च अदरक', 'छोटा चमच्च लहसुन', 'प्याज', 'हरी मिर्च', 'छोटा चमच्च अमचूर पाउडर', 'छोटा चमच्च धनिया पाउडर', 'छोटा चमच्च लाल मिर्च पाउडर', 'छोटा चमच्च गरम मसाला पाउडर', 'नमक', 'अजवाइन', 'हरा धनिया', 'हींग', 'छोटा चमच्च कसूरी मेथी', 'बड़ा चमच्च तेल']::text[], '["\u0905\u0930\u092c\u0940 \u092e\u0938\u093e\u0932\u093e \u0915\u0938\u0942\u0930\u0940 \u092e\u0947\u0925\u0940 \u0915\u0947 \u0938\u093e\u0925 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u0922\u093e\u0908 \u092e\u0947 \u0924\u0947\u0932 \u0921\u093e\u0932\u0947, \u0905\u091c\u0935\u093e\u0907\u0928 \u0914\u0930 \u0939\u0940\u0902\u0917 \u0915\u093e \u0924\u0921\u0915\u093e \u0926\u0947\u096410 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u092c\u093e\u0926 \u0905\u0926\u0930\u0915 \u0914\u0930 \u0932\u0939\u0938\u0941\u0928 \u0915\u0940 \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0915\u0930 \u092d\u0942\u0928\u0947\u0964 1 \u092e\u093f\u0928\u091f \u092c\u093e\u0926 \u0932\u093e\u0932\u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0915\u0930 \u092e\u093f\u0932\u093e\u090f\u0964\u092a\u094d\u092f\u093e\u091c \u0914\u0930 \u0939\u0930\u0940\u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0915\u0930 \u092d\u0942\u0928\u0947 \u0964\u0927\u094d\u092f\u093e\u0928 \u0930\u0916\u0947 \u0924\u0932\u0947 \u092a\u0930 \u092e\u0938\u093e\u0932\u093e \u091c\u0932\u0947 \u0928\u093e\u0964 \u092e\u0940\u0921\u093f\u092f\u092e \u0906\u0901\u091a \u092a\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u094b \u0939\u0932\u094d\u0915\u093e \u092c\u094d\u0930\u093e\u0909\u0928 \u0939\u094b\u0928\u0947 \u0924\u0915 \u092d\u0942\u0928\u0947\u0964\u092b\u093f\u0930 \u091f\u092e\u093e\u091f\u0930 \u0921\u093e\u0932\u0915\u0930 \u091f\u092e\u093e\u091f\u0930 \u0917\u0932\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e\u090f\u0964 \u00a0\u0924\u0947\u0932 \u0915\u0922\u093e\u0908 \u091b\u094b\u0921\u0928\u0947 \u0932\u0917\u0947 \u0924\u092c \u0905\u092e\u091a\u0942\u0930 \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915, \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930, \u0914\u0930 \u0915\u0938\u0942\u0930\u0940 \u092e\u0947\u0925\u0940 \u0939\u0925\u0947\u0932\u0940 \u0938\u0947 \u0930\u0917\u0921\u093c\u0915\u0930 \u0921\u093e\u0932\u0947\u0964 \u00a0\u0905\u0930\u092c\u0940 \u0921\u093e\u0932\u0915\u0930 \u092e\u093f\u0932\u093e\u090f\u09642 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0927\u0940\u092e\u0940 \u0906\u0901\u091a \u092a\u0930 \u092a\u0915\u0928\u0947 \u0926\u0947. \u0917\u0947\u0938 \u0911\u092b \u0915\u0930 \u092e\u0938\u093e\u0932\u0947\u0926\u093e\u0930 \u0915\u0938\u0942\u0930\u0940 \u0905\u0930\u092c\u0940 \u0915\u094b \u0938\u0930\u094d\u0935\u093f\u0917 \u092a\u094d\u0932\u0947\u091f \u092e\u0947 \u0928\u093f\u0915\u093e\u0932 \u0915\u0930 \u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u0947 \u0938\u0947 \u0938\u091c\u093e\u0915\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u0905\u0930\u092c\u0940 \u092e\u0938\u093e\u0932\u093e \u0915\u0938\u0942\u0930\u0940 \u092e\u0947\u0925\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0915\u094b\u00a0\u0932\u0939\u0938\u0941\u0928\u093f \u0926\u093e\u0932, \u092c\u0942\u0902\u0926\u0940 \u0930\u093e\u092f\u0924\u093e \u0914\u0930 \u0924\u0935\u093e \u092a\u0930\u093e\u0920\u093e \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Affiliate-Articles/arbi_masala_kasuri.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/156.arbi_masala_kasuri.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tamil Nadu Style Ulundhu Kuzhambu Recipe - Black Lentil Curry', 'tamil-nadu-style-ulundhu-kuzhambu-recipe-black-lentil-curry', 'Ulundhu Kuzhambu Recipe is one of the best curries that my mother makes so dearly. It is protein and fibre-rich recipe. The nutritious black gram dal and urad dal has high levels of protein and minerals. They also help reduce cholesterol levels to improve cardiovascular health.My mother uses sesame oil for cooking because of the believed cooling effect that it provides us.', '["150 grams Black Urad Dal (Split)", "1 Brinjal (Baingan / Eggplant) , slit lengthwise", "1 Drumstick , chopped into 2-3 inch pieces", "Tamarind , gooseberry sized, soaked in 1/4 cup of water for 15 minutes", "3 cloves Garlic , peeled", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "2 tablespoons Sesame (Gingelly) Oil , refined oil can be used too", "1 pinch Asafoetida (hing)", "Salt , to taste", "Water , to cook", "1/4 cup Fresh coconut , chopped", "1/4 teaspoon Cumin seeds (Jeera)", "5 Shallots", "Ingredients for Tempering", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Shallots , finely chopped", "1 Dry Red Chilli", "1 Curry leaves , finely chopped"]'::jsonb, ARRAY['s black urad dal', 'split', 'brinjal', 'baingan / eggplant', 'drumstick', 'tamarind', 's garlic', 'turmeric powder', 'haldi', 'red chilli powder', 'coriander powder', 'dhania', 's sesame', 'gingelly', 'asafoetida', 'hing', 'salt', 'water', 'fresh coconut', 'cumin seeds', 'jeera', 'shallots', 'ingredients for tempering', 'mustard seeds', 'rai/ kadugu', 'dry red chilli', 'curry leaves']::text[], '["To begin with making Ulundu Kuzhambu Recipe, we start with grinding the enlisted \u201cIngredients to Grind\u201d like coconut, cumin seeds and shallots with water to a smooth paste and set aside.", "Roast black gram in a pan with a teaspoon of oil for about 5 minutes until a pleasant aroma arises.Pressure cook urad dal, garlic and hing with 2 cups of water until cooked soft (It takes 2 whistles for me)."]'::jsonb, 60, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/punitha_josephine/Ulunthangulambu_Black_Lentil_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/157.Ulunthangulambu_Black_Lentil_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Nimki Aloo Anardana Curry Recipe - Potato And Nimki Curry', 'nimki-aloo-anardana-curry-recipe-potato-and-nimki-curry', 'Nimki Aloo Anardana Curry Recipe is a combination of all my favorites: potato, crunchy nimki with sweet spicy and chatpata flavours in a gravy form. Its one of the delicious and lip smacking potato based recipe.', '["To make the Nimki", "1 cup All Purpose Flour (Maida)", "1 tablespoon Ajwain (Carom seeds)", "1 tablespoon Sooji (Semolina/ Rava)", "1 tablespoon Ghee", "Salt , to taste", "Water , as required for dough mixing", "Oil , as required, for frying", "5 Potatoes (Aloo) , peeled and diced", "1 Onion , finely chopped", "1 tablespoon Ginger Garlic Paste", "1/2 cup Homemade tomato puree", "2 tablespoons Oil", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1 tablespoon Anardana Powder (Pomegranate Seed Powder)", "1 teaspoon Fennel seeds (Saunf) , powdered", "1 teaspoon Sugar", "1/2 teaspoon Garam masala powder", "Salt , to taste", "1/2 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "Coriander (Dhania) Leaves , chopped", "Fresh Pomegranate Fruit Kernels , as required", "Lemon wedges , as required", "Onion , finely chopped"]'::jsonb, ARRAY['tomato', 'coriander (dhania) leaves', 'anardana powder (pomegranate seed powder)', 'ajwain (carom seeds)', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'sunflower oil', 'salt', 'lemon', 'pomegranate fruit kernels', 'flour (maida)', 'garam masala powder', 'red chilli powder', 'sugar', 'water dough mixing', 'sooji (semolina rava)', 'kasuri methi (dried fenugreek leaves)', 'ghee', 'fennel seeds (saunf)', 'ginger garlic paste', 'coriander powder', 'potato (aloo)']::text[], '["To begin making the\u00a0Nimki Aloo Anardana Curry recipe, we will first start by making the Nimki.In a bowl add maida, salt, semolina, ghee & mix well.To this gradually add water and start kneading to form a stiff dough.", "Set aside for 15-20 minutes and knead again to form a smooth dough.Now take a ball sized dough and start rolling it like a roti and cut it into diamond shapes with a knife.Heat the required oil in a pan for deep frying and add the nimkis one by one.", "Fry them over a medium low heat till they turn golden colour from all the sides.Remove from oil and place them over a tissue paper to absorb the excess oil from the nimki.", "Set it aside.Note: you can also use readymade Nimki to make this\u00a0Nimki Aloo Anardana Curry RecipeThe next step is to make the Aloo/ Potato curry in the pressure cooker.", "Heat oil in a pressure cooker over medium heat; add\u00a0cumin seeds, ginger garlic paste and cook till the raw smell is gone.", "This will take about a minute or two.After a minute or two, add finely chopped onions and let it cook till the onions turn soft and translucent.Next, add all the dry spices including garam masala powder, turmeric powder, red chilli powder, fennel powder, coriander powder, anardana powder and light roast for a minute.After a minute, add tomato puree and the diced potatoes and let it simmer for 2 minutes.", "Add salt to taste, 1 cup of water and cover the pressure cooker and cook for 4 to 5 whistles.Once done, turn off the heat and allow the pressure to release naturally.Once the pressure releases, add the kasuri methi and check the salt and spices and adjust accordingly.", "Transfer to a serving bowl.Lastly, garnish it with pomegranate seeds, coriander leaves, nimki, lemon wedges and onions and serve hot.Serve\u00a0Nimki Aloo Anardana Curry\u00a0along with\u00a0Palak Raita,\u00a0Kachumber Salad\u00a0and\u00a0Tawa Paratha\u00a0for a weekday meal with your family."]'::jsonb, 105, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/anki.s19-gmail.com/Nimki_Aloo_Anardana_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/158.Nimki_Aloo_Anardana_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mixed Sprouts In Chettinad Masala Recipe', 'mixed-sprouts-in-chettinad-masala-recipe', 'Mixed Sprouts In Chettinad Masala Recipe is a delicious sprouts dish cooked in an aromatic chettinad masala.', '["2 cups Mixed Sprouts , boiled", "1 Onion , thinly sliced", "2 Tomatoes , thinly sliced", "2 Green Chillies , slit", "1 inch Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta)", "2 Cardamom (Elaichi) Pods/Seeds", "3 Cloves (Laung)", "1 teaspoon Fennel seeds (Saunf)", "1 teaspoon Garam masala powder", "2 sprig Curry leaves", "1 tablespoon Sesame (Gingelly) Oil", "Salt , to taste", "Ingredients to roast and grind", "2 teaspoons Whole Black Peppercorns", "1 teaspoon Cumin seeds (Jeera)", "2 teaspoons Fennel seeds (Saunf)", "1 tablespoon Coriander (Dhania) Seeds", "10 cloves Garlic", "2 inch Ginger", "1/4 cup Fresh coconut , grated", "2 teaspoons Oil"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'bay leaf (tej patta)', 'cardamom (elaichi) podsseeds', 'fennel seeds (saunf)', 'coconut', 'sesame (gingelly) oil', 'black peppercorns', 'cloves garlic', 'curry leaves', 'coriander (dhania) seeds', 'mixed sprouts', 'onion', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'cloves (laung)', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To begin making\u00a0Mixed Sprouts In Chettinad Masala Recipe, wash and pressure cook the mixed sprouts for 2 whistles using a pressure cooker and keep aside.Turn off the heat after two whistles and allow the pressure to release naturally.", "We have used the mixed sprouts containing green gram, horse gram, black chickpeas and cow peas.", "You can add any whole lentils of your choice.", "Next, to prepare the chettinad masala heat oil in a small pan, add the black pepper corns, cumin, fennel and coriander seeds, saute until it gets roasted and turns aromatic.Add the ginger, garlic and cook until the garlic turns a bit brown.Add in the grated coconut and saute until the whole mixture turns brown and aromatic.", "Cool and grind it into a smooth paste using a mixer grinder and keep aside.Heat sesame oil in a heavy bottomed pan on medium flame, add the cloves, green cardamom, bay leaf, cinnamon stick, fennel seeds and let it become fragrant.Add in the sliced onions, a pinch of salt and saute until it turns golden brown.", "Add the slit green chilies, curry leaves and saute for a minute.Add the chopped tomatoes and cook until it turns soft.", "Now, add in the prepared chettinad masala and saute until the whole mixture comes together and oil leaves the sides of the pan.Add the boiled sprouts, garam masala, season with salt and let it simmer for 10 minutes.", "Occasionally stir in between.", "Once the whole curry becomes a little thick, switch off the heat and serve hot.Serve the\u00a0Mixed Sprouts In Chettinad Masala Recipe along with\u00a0Steamed Rice\u00a0and\u00a0Chow Chow Thoran\u00a0for a delicious and comforting weeknight dinner."]'::jsonb, 40, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Mixed_Sprouts_In_Chettinad_Masala_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/159.Mixed_Sprouts_In_Chettinad_Masala_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Sorak Curry Recipe', 'goan-sorak-curry-recipe', 'Goan Sorak Curry Recipe is a sweet, spicy, tangy and delicious curry made with a freshly ground coconut masala which has a perfect blend of coconut, onion, garlic and red chillies. It is a flavourful curry with sweet notes from the addition of jaggery, tangy notes from fresh kokum, and heat from the red and green chillies.', '["1 tablespoon Oil", "3 Kokum (Malabar Tamarind)", "2 Green Chillies , slit", "1 tablespoon Jaggery", "Salt , to taste", "4 sprig Coriander (Dhania) Leaves , finely chopped", "1 cup Fresh coconut , grated", "1 Onion , roughly chopped", "4 cloves Garlic", "1 teaspoon Cumin seeds (Jeera)", "2 teaspoons Coriander (Dhania) Seeds", "8 Dry Red Chillies", "1/2 teaspoon Turmeric powder (Haldi)"]'::jsonb, ARRAY['salt', 'kashmiri dry red chilli', 'coconut', 'kokum (malabar tamarind)', 'coriander (dhania) leaves', 'jaggery', 'cloves garlic', 'water', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Goan Sorak Curry Recipe, we will first grind the sorak curry masala.", "In a mixer jar, combine the onion, garlic, cumin seeds, coriander seeds, dry red chillies, coconut and turmeric.", "Add 1/2 cup of warm water and blend to make a smooth paste.", "Heat oil in a heavy bottom pan over medium heat; add the green chilli and the freshly ground goan sorak curry masala.", "Saute for 2 minutes or until the raw smell of the masala disappears.", "Next add in the salt, jaggery, kokum, one cup of water and bring the\u00a0goan sorak curry to a brisk boil.", "Adjust the salt and seasoning according to your taste.", "Turn off the heat and garnish the\u00a0goan sorak curry with coriander leaves and serve.", "Serve the\u00a0Goan Sorak Curry along with\u00a0Ghee Rice\u00a0or even\u00a0Goan Poee\u00a0for lunch or dinner."]'::jsonb, 30, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/Goan_Sorak_Curry_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/160.Goan_Sorak_Curry_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Raswala Sabzi Recipe', 'aloo-raswala-sabzi-recipe', 'Aloo Raswala Sabzi Recipe is a tangy, and spicy potato curry and served best along with puris. Soft boiled potatoes simmered in a tomato-onion base, thinned down to a gravy - called ''ras''.', '["1 tablespoon Oil", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1/2 teaspoon Cumin seeds (Jeera)", "1 pinch Asafoetida (hing)", "1 Onion , finely chopped", "4 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "1 Green Chillies , chopped", "2 Tomatoes , chopped", "4 Potatoes (Aloo)", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder , (Or kitchen king masala)", "Red Chilli powder", "Salt , to taste", "Coriander (Dhania) Leaves , to garnish"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'asafoetida (hing)', 'coriander (dhania) leaves', 'red chilli powder', 'cloves garlic', 'onion', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'garam masala powder (or kitchen king masala)', 'potato (aloo)', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the\u00a0Aloo Raswala Sabzi Recipe, we will first boil the potatoes.", "Place the potatoes in a pressure cooker along with some water and pressure cook for about 5-6 whistles.", "Turn off the pressure cooker and allow the pressure to release naturally.", "Remove the potatoes from the cooker, peel and cut them into medium sized cubes and set aside.", "Heat oil in a pan on medium flame, add cumin seeds and methi seeds.", "Once the seeds begin to sizzle, add in the onion, ginger and garlic and saute until the onions become soft and tender.Stir in green chillies, asafoetida and stir fry for a few seconds.", "Once the onions have softened, add in the tomatoes and mix well.Add turmeric powder and red chilli powder.", "Continue to cook until the tomatoes are mushy and softened.Sprinkle garam masala powder, add cooked potatoes, salt to taste and just enough water to the consistency of your choice and bring to the\u00a0Aloo Raswala Sabzi to a brisk boil.", "Adjust water such that the consistency is neither too thick or too thin.", "Reduce heat and simmer the\u00a0Aloo Raswala Sabzi for about 10 minutes till it form a masaledar gravy.", "Once done, check the salt and spices and adjust to suit your taste and turn off the heat.Transfer the\u00a0Aloo Raswala Sabzi to a serving bowl and serve hot.Serve Aloo Raswala Sabzi Recipe along with\u00a0Chunni Ki Puri Recipe- Moong Dal And Besan Fried Puri Recipe\u00a0and\u00a0Sago Kheer Recipe - Tapioca Milk Pudding\u00a0for a simple Sunday brunch."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Curryandvanilla/Aloo_Raswala_Sabzi_Recipe_-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/161.Aloo_Raswala_Sabzi_Recipe_-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mangalorean Style Kuvalyacho Pollav Recipe (Yellow Pumpkin Curry Recipe)', 'mangalorean-style-kuvalyacho-pollav-recipe-yellow-pumpkin-curry-recipe', 'Mangalorean Style Kuvalyacho Pollav Recipe (Yellow Pumpkin Curry Recipe) is a simple traditional Mangalore curry which uses coconut as its base to make the gravy. Usually the onions and coconut used in this recipe are sun dried and then ground along with other spices into a course paste.  But as the lifestyle changed people starting making it on the pan itself. But whatever it is the true flavor of the old traditional flavors will always remain divine.', '["250 grams Kaddu (Parangikai/ Pumpkin)", "1 Onion , sliced", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "Water , as required", "1 Onion , sliced", "1/4 cup Fresh coconut , grated", "1 tablespoon Ajwain (Carom seeds)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 tablespoon Coriander (Dhania) Seeds", "18 grams Tamarind", "3 Dry Red Chillies"]'::jsonb, ARRAY['salt', 'parangikai pumpkin', 'coconut', 'mustard seeds', 'ajwain (carom seeds)', 'water', 'coriander (dhania) seeds', 'onion', 'dry red chillies', 'coriander powder', 'tamarind', 'turmeric powder']::text[], '["We begin making the Mangalorean Style\u00a0Kuvalyacho Pollav Recipe (Yellow Pumpkin Curry Recipe) by crackling the mustard seeds, jeera seeds, coriander seeds and then add the sauteed onions.", "Saute till it is translucent and then add the grated coconut.Saute till it is golden brown.", "Leave it to cool down and then grind it into a coarse mixture by adding some water if required.Heat a pressure cooker, add some oil, saute the sliced onions and add the chopped pumpkin and finally add in the ground paste.", "Add some extra water around 1 cup and mix well.Add in the spice powder and check for salt.", "Once that is done, pressure cook for about 4 whistle and release the pressure naturally and serve.", "Serve the Mangalorean Style\u00a0Kuvalyacho Pollav Recipe (Yellow Pumpkin Curry Recipe) along with some\u00a0steamed rice\u00a0or\u00a0phulka."]'::jsonb, 40, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Mangalorean_Style_Kuvalyacho_Pollav_Recipe_Yellow_Pumpkin_Curry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/162.Mangalorean_Style_Kuvalyacho_Pollav_Recipe_Yellow_Pumpkin_Curry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Sabsige Soppu Akki Rotti (Dill leaves and flattened Rice Bread Recipe)', 'karnataka-style-sabsige-soppu-akki-rotti-dill-leaves-and-flattened-rice-bread-recipe', 'Karnataka Style Sabsige Soppu Akki Rotti (Dill leaves and flattened Rice Bread Recipe) is a variation to Akki Rotti which is a very famous Karnataka’s breakfast dish. Dill leaves are very important in their cuisine as it is locally available. The leaves have a very strong fragrant and pungent taste and is best used for savory purposes. It is added to the rice flour and flattened rice dough and patted on a cloth and then cooked over a flat tawa.', '["1 cup Rice flour", "1 cup Poha (Flattened rice)", "1 cup Dill leaves , chopped", "2 Green Chilli , chopped", "1 teaspoon Cumin seeds (Jeera)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'dill leaves', 'green chilli', 'poha (flattened rice)', 'cumin seeds (jeera)', 'rice flour']::text[], '["We begin making the Karnataka Style Sabsige Soppu Akki Rotti (Dill leaves and flattened Rice Bread Recipe) by soaking the flattened rice with 1/2 cup water for about 30 minutes.Then mash it, till it becomes a soft dough and add the remaining ingredients and bind it using 1/4 cup luke warm water.", "Knead it to a wet dough but not sticky.Cover with a damp cloth and rest for about 10 minutes.Now to prepare the roti, place a non stick tawa/skillet on the heat.", "Spread out a large piece of plastic, or parchment paper on your work surface.Grease your palms with oil.", "Pinch a big ball of dough place it in the centre of the parchment or plastic.", "Then gently flatten it out to form a hand-patted disc, similar to Thalipeeth.Lift the paper, along with the rotti on it and turning it over, place it on the skillet with the rotti down on the hot skillet.", "Carefully supporting the rotti peel off the paper.", "Drizzle a little bit of oil along the edges of the roti and in the centre, into the hole made on the roti and allow it to sizzle and crisp up.When it seems half cooked, flip the roti over with a spatula to cook the other side.Cook well till you have brown patches on both sides.", "Then, take the roti off the skillet, add a dollop of butter or ghee, and serve immediately.", "Serve the Karnataka Style Sabsige Soppu Akki Rotti (Dill leaves and flattened Rice Bread Recipe) can be serve along with\u00a0Karuveppilai Chutney Recipe (A Healthy Curry Leaves Chutney)."]'::jsonb, 40, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Karnataka_Style_Sabsige_Soppu_Akki_Rotti_Dill_leaves_and_flattened_Rice_Bread_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/163.Karnataka_Style_Sabsige_Soppu_Akki_Rotti_Dill_leaves_and_flattened_Rice_Bread_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Badanekayi Palya Recipe - Long Brinjal In Spicy Coconut Recipe', 'karnataka-style-badanekayi-palya-recipe-long-brinjal-in-spicy-coconut-recipe', 'Karnataka Style Badanekayi Palya Recipe is a side dish prepared by sauteing the long brinjal with spicy ground coconut mixture. The red color in the dish is mainly obtained from the use of Byadgi Dried Chillies which is a type dried red chili famous in Karnataka.', '["6 Long Green Brinjal , cut into 1 inch pieces", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1 teaspoon Turmeric powder (Haldi)", "1 tablespoon Sambar Powder", "2 tablespoons Jaggery", "1 teaspoon Salt , and more to taste", "2 tablespoons Gingelly oil", "To Roast & Grind", "1/4 cup Sesame seeds (Til seeds)", "1/2 cup Roasted Peanuts (Moongphali)"]'::jsonb, ARRAY['salt', 'mustard seeds', 'asafoetida (hing)', 'coconut', 'sesame (gingelly) oil', 'curry leaves', 'byadagi dried chillies', 'coriander (dhania) seeds', 'cinnamon stick (dalchini)', 'green brinjal', 'turmeric powder', 'chana dal (bengal gram dal)']::text[], '["To begin making the Karnataka Style Badanekayi Palya Recipe,\u00a0first prep all the ingredients and keep them ready.Place the cut brinjal in a bowl of water to prevent discolouration.", "In a small pan, add the peanuts and sesame seeds and roast them for about a minute.", "If you are using roasted peanuts, then just wait for the sesame seeds to crackle and turn off the heat.Set aside to cool.", "Once cooled, add this to a small jar of the mixer grinder and blend to make a coarse powder.", "Heat oil in a large stir fry pan over medium heat; add the mustard seeds and allow it to crackle.", "Add the chopped onion and curry leaves and saute until the onions soften and turn translucent.", "Once done, add the tomatoes and saute until it becomes slightly soft.", "Stir in the turmeric powder.", "Drain water from the cut brinjal and add it into the tomato onion mixture.", "Sprinkle salt and give it a gentle stir.Cover the pan and cook the brinjal until it turns soft.", "This will take about 4 to 5 minutes.", "Ensure you stir it a couple of times in between.Towards the end of the cooking process, stir in the sambar powder and the crusted peanuts and sesame seeds.", "Check salt and add more to taste.", "Stir fry the brinjal in the open pan for another couple of minutes until the masala gets well combined into the brinjal.", "Once done, turn off the heat and transfer to a serving bowl and serve hot.", "Serve the\u00a0Karnataka Style Badanekayi Palya Recipe\u00a0as a side dish along with some\u00a0Thakkali Rasam\u00a0and\u00a0Steamed Rice\u00a0to make it a complete meal."]'::jsonb, 40, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Karnataka_Style_Badanekayi_Palya_Recipe_-_Green_Brinjal_Poriyal_Sabzi_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/164.Karnataka_Style_Badanekayi_Palya_Recipe_-_Green_Brinjal_Poriyal_Sabzi_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('No Onion No Garlic Aloo Gajar Ki Sabzi Recipe', 'no-onion-no-garlic-aloo-gajar-ki-sabzi-recipe', 'Aloo Gajar ki Sabzi recipe is an effortless dry sabzi prepared with Potatoes and Carrots. The recipe doesn’t call for onion or garlic and thus making it perfect for a fasting day. This is such a versatile one as it can be stuffed inside chapatti or simply served with dal-rice. The colors of Potato and Carrot are complementary and loaded with the required carbohydrates for a day. At the end of the day, who wouldn’t love potatoes?', '["2 Potatoes (Aloo) , boiled and diced", "2 Carrots (Gajjar) , diced and steamed", "1 teaspoon Oil", "1 teaspoon Cumin seeds (Jeera)", "1 inch Ginger , grated finely", "3 Green Chillies , slit or finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Coriander Powder (Dhania)", "1 teaspoon Lemon juice", "Salt , to taste or kala namak (for fasting)", "Coriander (Dhania) Leaves , handful for garnish, chopped"]'::jsonb, ARRAY['ginger', 'coriander (dhania) leaves', 'red chilli powder', 'carrot', 'cumin seeds (jeera)', 'lemon', 'salt (for fasting)', 'coriander powder', 'potato (aloo)', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the\u00a0Aloo Gajar Ki Sabzi Recipe, first prep all the ingredients.", "Cook the potatoes in a pressure cooker, peel the skin and cut into cubes.Steam the carrots either in the pressure cooker or in a steamer and keep aside.Heat oil in a heavy bottomed pan over medium heat, add the cumin seeds and allow it to crackle.", "Once it crackles, add the ginger and saute for a few seconds.", "Add the potatoes, carrots, and the remaining masalas and toss well.", "Add the salt, cover the pan and allow the carrots and aloo to get cooked along with the masalas.Once done, check the salt and spices and adjust to suit your taste.", "Finally add a squeeze of lemon and stir in the coriander leaves and serve.Serve the\u00a0Aloo Gajar ki Sabzi along with\u00a0Phulkas\u00a0and\u00a0Rajasthani Kadhi\u00a0for a light weeknight dinner."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Aloo_Gajar_Ki_Sabzi_Recipe_-_No_onion_No_garlic-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/165.Aloo_Gajar_Ki_Sabzi_Recipe_-_No_onion_No_garlic-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Cabbage And Carrot Thoran Recipe', 'cabbage-and-carrot-thoran-recipe', 'Cabbage and Carrot Thoran Recipe is a simple Kerala cuisine preparation commonly done in all houses and served as an accompaniment for rice. Cabbage and carrot are grated finely, mixed with spices, cooked in medium flame without the addition of water and grated coconut is generously added to the thoran. The recipe can be prepared easily in a few minutes and can also be packed as part of lunch. Prepare this simple thoran than usual poriyal, and serve with hot boiled rice, Cheriya ulli sambar and fried papad.', '["3 Carrots (Gajjar) , grated", "1/2 Cabbage (Patta Gobi/ Muttaikose) , finely chopped", "1 Onion , finely chopped", "4 Green Chillies , slit", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera)", "1 tablespoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 cup Fresh coconut , grated", "6 Curry leaves", "Salt , as required"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'mustard seeds', 'coconut', 'carrot', 'curry leaves', 'onion', 'turmeric powder', 'green chillies', 'cabbage (patta gobi muttaikose)', 'sunflower oil']::text[], '["To prepare this easy Cabbage And Carrot Thoran Recipe, wash and prepare carrots and cabbage first.In a bowl, add grated carrots and chopped cabbage.", "Add onions, green chilies, cumin powder, turmeric powder and required salt to the vegetable mixture.Toss them well so that they are mixed well together.In a kadai, add oil and heat over a medium flame.Add mustard seeds once the oil is hot.Once the mustards splutter, add curry leaves and the vegetable mixture.Cook the mixture over the medium flame with the lid covered.", "This may take 10-12 minutes.Once the vegetables become tender and cooked, add grated coconut to the mixture.Combine them well and cook with the lid open for about 3 minutes till the dish is cooked.Switch off the flame.", "Serve the carrot and cabbage thoran with hot boiled rice,\u00a0Cheriya ulli sambar\u00a0and fried papad\u00a0for a perfect meal."]'::jsonb, 40, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Cabbage_and_Carrot_Thoran.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/166.Cabbage_and_Carrot_Thoran.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Moolyacho Ross Recipe (Goan Radish Curry)', 'goan-moolyacho-ross-recipe-goan-radish-curry', 'Goan Moolyacho Ross is a traditional Goan preparation. Ross means Goan curry and moolo means radish. This curry is similar to Goan drumstick curry or sangacho ross, but to this curry mom does not add black pepper seeds. You can have this curry with steamed rice, rava fried vegetable, stir fry or bhaji, kokum kadi, papad and salad to have a simple Goan veg lunch. This curry may appear simple, but it is nutritious as radish is loaded with fibre, vitamin B6 and folic acid which are very good for health. Also radish controls blood pressure and if good for diabetics. Dal is rich in protein and folic acid.', '["2 Mooli/ Mullangi (Radish) , peeled", "1/2 cup Arhar dal (Split Toor Dal)", "1/2 Onion , finely chopped", "6 tablespoons Fresh coconut , grated", "1 Green Chilli , slit", "4 Dry Red Chillies", "1 teaspoon Coriander (Dhania) Seeds", "Tamarind , lemon sized", "1/2 teaspoon Jaggery , grated", "Salt , to taste"]'::jsonb, ARRAY['salt', 'arhar dal (split toor dal)', 'green chilli', 'coconut', 'jaggery', 'dry red chillies', 'onion', 'coriander (dhania) seeds', 'mooli mullangi (radish)', 'tamarind lemon']::text[], '["To begin making the Goan Moolyacho Ross recipe, cut the peeled radish into 1 and 1/2 inch long finger shaped pieces.Add dal, radish and chopped onion along with 1 cup water in pressure cooker and pressure cook till 4 whistles.Grind grated coconut, dry red chilies, coriander seeds, tamarind and turmeric powder by adding 1/2 cup water into a thin gravy using a blender.Mix the coconut gravy with the dal in\u00a0pressure cooker.", "Add grated jaggery and mix well.Simmer the gravy for 10 minutes.", "Add salt to taste, mix and serve hot.", "Serve Goan Moolyacho Ross along with Steamed Rice and\u00a0Cauliflower Thoran\u00a0for a perfect weekday meal."]'::jsonb, 50, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Goan_Moolyacho_Ross__Goan_Radish_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/167.Goan_Moolyacho_Ross__Goan_Radish_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Orange Rasam Recipe', 'orange-rasam-recipe', 'Orange Rasam Recipe is with a unique twist of adding orange juice to the regular rasam. This rasam has a refreshing fruity flavour to please your taste buds.', '["1 tablespoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 teaspoon Cumin seeds (Jeera)", "5 Curry leaves", "1/4 teaspoon Asafoetida (hing)", "4 cloves Garlic , crushed", "5 Tomatoes , chopped & pureed", "2 cups Fresh orange juice", "Lemon , juice from half", "1/2 teaspoon Turmeric powder (Haldi)", "1 Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Black pepper powder", "Salt , to taste", "Coriander (Dhania) Leaves , freshly chopped, as required", "1/4 cup Arhar dal (Split Toor Dal) , cooked (optional)"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'arhar dal (split toor dal)', 'mustard seeds', 'asafoetida (hing)', 'ghee', 'coriander (dhania) leaves', 'red chilli powder', 'cloves garlic', 'curry leaves', 'orange juice', 'cumin seeds (jeera)', 'black pepper powder', 'coriander powder', 'turmeric powder', 'lemon from']::text[], '["To begin making Orange Rasam Recipe, place a saucepan on medium heat, add 2 cups of water, chopped tomatoes, turmeric powder, hing, salt and orange zest.", "Allow this mixture to boil for 10 to 15 minutes.Meanwhile to make the rasam masala powder, heat a pan on medium heat.", "Dry roast\u00a0black pepper,\u00a0cumin seeds, curry leaves,\u00a0red chilli,\u00a0toor\u00a0dal,\u00a0for 2-3 minutes.", "Let the spices cool.", "Once cooled, grind them to a coarse mixture.Once the tomatoes are softened and mixture is boiled for 10-15 minutes, add the cooked toor dal.", "Click here to know How To Cook Lentils In A pressure Cooker.Add the freshly ground rasam masala.", "Let the rasam mixture boil for 4-5 minutes.", "Adjust the consistency of the rasam.After 4-5 minutes, turn off the heat.", "Add orange juice, lemon juice and mix well.", "At this stage, proceed to make the seasoning for the rasam.", "To prepare the seasoning, heat a tadka pan on medium heat.", "Add ghee to it.Once the ghee is hot, add mustard seeds and allow them to crackle.", "Add the curry leaves.Add the seasoning to rasam mixture.", "Garnish the rassam with coriander leaves.Serve Orange Rasam Recipe with Steamed Rice and Cabbage Thoran (Poriyal) Recipe as a perfect accompaniment to south indian meal."]'::jsonb, 35, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Orange_Rasam_Recipe-7.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/168.Orange_Rasam_Recipe-7.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dhaba Style Chana Masala From Deserts of Jaisalmer', 'dhaba-style-chana-masala-from-deserts-of-jaisalmer', 'The Dhaba Style Chana Masala recipe is a lip smacking recipe from the deserts if Jaisalmer Rajasthan. I learnt this from the chef of the desert camp we stayed in. I love this chana masala so much and when I requested for the recipe, the chef who made this, came in and explained to me in detail on how to make it. Cooked in ghee and whole spices is what makes this chana masala stand out from the crowd.', '["2 cups Kabuli Chana (White Chickpeas) , soaked for 8 hours", "2 tablespoons Ghee , for cooking", "2 Onions , thinly sliced", "4 cloves Garlic , finely chopped", "2 inch Ginger , finely chopped", "2 inch Cinnamon Stick (Dalchini)", "4 Cloves (Laung)", "2 Bay leaves (tej patta) , torn", "2 Brown cardamom (Badi Elaichi)", "2 Tomatoes , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Coriander (Dhania) Powder", "1/2 teaspoon Garam masala powder", "1 tablespoon Chana Masala Powder", "Salt , to taste", "5 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['s kabuli chana', 'white chickpeas', 's ghee', 'onions', 's garlic', 'ginger', 'cinnamon stick', 'dalchini', 'laung', 'bay leaves', 'tej patta', 'brown cardamom', 'badi elaichi', 'tomatoes', 'turmeric powder', 'haldi', 'red chilli powder', 'coriander', 'dhania', 'garam masala powder', 'chana masala powder', 'salt']::text[], '["To begin making the\u00a0Dhaba Style Chana Masala recipe, prep all the ingredients and keep them ready.", "Ensure the kabuli chana is soaked for at least 8 hours in water.Pressure cook the soaked kabuli chana along with little salt and water (at least 2 inches above the chana) for about 45 minutes.Once you turn off the heat after 45 minutes, allow the pressure to release naturally.", "The chana should feel very soft, that when you press it between your fingers it will mash easily.", "Keep this cooked chana aside.Heat ghee in a large pan; add the onion, ginger and garlic.Saute until the onions become soft and lightly brown.", "Add the whole spices at this stage - the cinnamon, cloves, badi elaichi, bay leaves and saute for a few seconds till you can smell the aromas coming through.", "Add the tomatoes, turmeric powder, red chilli powder, garam masala powder, coriander powder and chana masala powder.", "Saute until the tomatoes become mushy and soft.Once the tomatoes turn mushy, add the cooked kabuli chana.", "Stir well, check the salt and add more if required.", "Cover the pan and simmer the\u00a0Dhaba Style Chana Masala for 35 to 40 minutes so the flavours seep deeply into the chana.", "Add a little water to adjust the consistency of the chana masala.", "Once done, turn off the heat and stir in the coriander leaves into the\u00a0Dhaba Style Chana Masala.Transfer the\u00a0Dhaba Style Chana Masala\u00a0into a serving bowl and serve hot.", "Serve the\u00a0Dhaba Style Chana Masala\u00a0along with\u00a0Puri,\u00a0Kesar Elaichi Lassi\u00a0and some onions for a perfect weekend meal."]'::jsonb, 30, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Dhaba_Style_Chana_Masala_From_Desserts_of_Jaisalmer_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/169.Dhaba_Style_Chana_Masala_From_Desserts_of_Jaisalmer_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Malwani Pumpkin And Raw Mango Curry Recipe', 'malwani-pumpkin-and-raw-mango-curry-recipe', 'The Pumpkin Raw Mango Curry Recipe is beautifully spiced and cooked sabzi that is made with very little oil, it’s healthy and very delicious. A perfect balance of spice, sweet, sour and a hint of bitter in the curry makes it all right! Try this lip smacking curry today and enjoy.', '["1 Mango (Raw) , peeled and diced", "1 Kaddu (Parangikai/ Pumpkin) , yellow one", "3 Green Chillies", "1/2 teaspoon Ginger , grated", "2 Dry Red Chillies", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Fennel seeds (Saunf)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1/2 teaspoon Whole Black Peppercorns", "1/2 teaspoon Coriander (Dhania) Seeds", "2 tablespoons Fresh coconut , grated", "1 tablespoon Oil"]'::jsonb, ARRAY['ginger', 'coconut', 'fennel seeds (saunf)', 'black peppercorns', 'mango', 'parangikai pumpkin yellow', 'dry red chillies', 'coriander (dhania) seeds', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'green chillies', 'sunflower oil']::text[], '["To begin making the Malwani Pumpkin And Raw Mango Curry Recipe, lightly dry roast each of these spices separately \u2013 dried red chilies, cumin seeds, fennel seeds, fenugreek seeds, black pepper corn, coriander seeds.", "Let it cool and then grind into fine powder.Heat oil in a heavy bottomed pan.", "Add slit green chilies, grated ginger and saute for a minute.", "Then add the ground powder and saute for a minute.Add raw mango cubes into the pan along with salt along with little water cook until mango is 3/4 cooked.Add the pumpkin cubes and cook until pumpkin is well done.", "Add little water if required during cooking.", "The Malwani Pumpkin And Raw Mango Curry should be semi dry.Finally add grated coconut and turn off the flame.", "Serve hot.", "Serve Malwani Pumpkin And Raw Mango Curry along with\u00a0Cauliflower Thoran\u00a0and\u00a0Steamed Rice\u00a0for a weekday lunch or dinner."]'::jsonb, 40, 'Malvani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/Malwani_Pumpkin__Raw_Mango_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/170.Malwani_Pumpkin__Raw_Mango_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vankaya Gasagasala Kura | Andhra Style Eggplant Poppy Seeds Curry Recipe', 'vankaya-gasagasala-kura-andhra-style-eggplant-poppy-seeds-curry-recipe', 'This unique flavoured Andhra Style Eggplant Poppy Seeds Curry is a must try recipe. The main difference between this curry and others is that there is no coconut at all in it. The masala base is mainly prepared with poppy seeds, which gives a nutty flavour and texture to the curry. For all curry lovers, this fantastic dish is a must try dish.', '["To be Ground To paste", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "3 tablespoons Poppy seeds", "Main Ingredients", "8 Brinjal (Baingan / Eggplant)", "2 tablespoons Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "4 cloves Garlic , finely chopped", "1 tablespoon Red Chilli powder", "1 tablespoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "30 grams Tamarind , soaked and pulp extracted", "1 tablespoon Jaggery", "Salt , to taste"]'::jsonb, ARRAY['salt', 'tamarind pulp', 'mustard seeds', 'brinjal (baingan eggsplant)', 'jaggery', 'red chilli powder', 'cloves garlic', 'poppy seeds', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Andhra Style Eggplant Poppy Seeds Curry recipe/ Vankaya Gasagasala Kura, dry roast poppy seeds until it starts to change the colour.", "Remove from pan immediately and let it cool.", "Dry roast methi seeds too and remove from flame.Into a blender add poppy seeds, methi seeds with 1/4 cup water and blend into a paste.Wash and pat dry the brinjals.", "Remove the stem and make a cross incision.", "Fry it in oil for about 4 to 5 minutes until it is roasted and cooked.", "Remove the fried brinjal and keep aside.Into the same pan, add little more oil if the pan turns dry, add the mustard seeds, cumin seeds and allow it to crackle.Then add the poppy seed masala paste, turmeric powder, red chilli powder and coriander powder.", "Saute cook for 5 to 6 minutes.", "Pour tamarind juice and 1/2 cup water, salt to taste and jaggery, bring the\u00a0Gasagasala Kura mixture to boil.Let it continue to simmer on medium flame for 5 to 7 minutes.", "After 5 minutes add fried brinjal and cook for 5 to 8 minutes.", "Check the salt and seasonings and adjust to taste according.", "Turn off the heat and transfer the\u00a0Vankaya Gasagasala Kura to a serving bowlServe Andhra Style Eggplant Poppy Seeds Curry recipe/\u00a0Vankaya Gasagasala Kura\u00a0 along with\u00a0Andhra Style Palakaru Vepadu\u00a0and\u00a0Tawa Paratha\u00a0for a weekday meal."]'::jsonb, 45, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/Andhra_Style_Eggplant_Poppy_Seeds_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/171.Andhra_Style_Eggplant_Poppy_Seeds_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Barnyard Millet and Ragi Khichdi Recipe', 'barnyard-millet-and-ragi-khichdi-recipe', 'Barnyard Millet and Ragi Khichdi Recipe is a wholesome twist to a traditional Khichdi where we make a mish mash of millets or millets and lentils with an optional addition of vegetables. Every family has a favorite way to make a Khichdi. Some make it in a dry form and a few other make the Gadelu (semi gravy like). At home we often serve the Khichdi along with Kadhi and a Batata Nu Shaak.', '["1/2 cup Barnyard Millet", "1/4 cup Yellow Moong Dal (Split)", "1/4 cup Ragi Seeds", "1 inch Ginger , grated", "1 teaspoon Turmeric powder (Haldi)", "1 inch Cinnamon Stick (Dalchini)", "Ingredients for the seasoning", "1 tablespoon Ghee", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Whole Black Peppercorns , crushed", "1 teaspoon Cumin seeds (Jeera)"]'::jsonb, ARRAY['yellow moong dal (split)', 'ginger', 'ragi seeds', 'ghee', 'asafoetida (hing)', 'black peppercorns', 'cinnamon stick (dalchini)', 'barnyard millet', 'cumin seeds (jeera)', 'turmeric powder']::text[], '["Note: The method below will result in a mushy texture of the Khichdi; you can adjust the consistency of the water to be cooked to the texture you like.To begin making the Barnyard Millet and Ragi Khichdi Recipe, soak the barnyard millet, the ragi and the dal together in water for at least 4 hours.", "Soaking the Ragi makes it cook faster.Once soaked, \u00a0place it in a pressure cooker.", "Add 3-1/2 cups of water, turmeric powder, ginger, salt and cinnamon and cook until you hear three to four whistles.", "Turn off the heat and allow the pressure to release naturally.Once the pressure releases, open the cooker and stir the Khichdi to combine all the ingredients and we will proceed to make the tadka.If you are planning to cook the Khichdi in a saucepan , then place the millet and dal in the saucepan, add the water, turmeric powder, ginger, salt and cinnamon and cook until the\u00a0Khichdi\u00a0is mushy.", "Once done, check the salt and adjust to suit your taste.For the seasoning of the Barnyard Millet and Ragi Khichdi, heat ghee a small tadka pan.", "Add the cumin seeds, crushed peppercorns and asafoetida.", "Stir for a few seconds and add it to the khichdi.Serve the Barnyard Millet and Ragi Khichdi\u00a0along with\u00a0Batata Nu Shaak (Aloo Tamatar Sabzi)\u00a0for a warm wholesome weeknight dinner."]'::jsonb, 65, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Barnyard_Millet_Ragi_Khichdi_Recipe_Archanas_Kitchen_Vegetarian_Food-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/172.Barnyard_Millet_Ragi_Khichdi_Recipe_Archanas_Kitchen_Vegetarian_Food-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Red Capsicum Poriyal Recipe - Red Bell Pepper Stir Fry', 'red-capsicum-poriyal-recipe-red-bell-pepper-stir-fry', 'Red Capsicum Poriyal is a delicious South Indian style red bell pepper stir fry with coconut. It is spiced with ginger, chilli and coconut mix to add a beautiful flavour to the dish. The ginger amalgamates very well with the crunchy red bell peppers.', '["3 Red Bell pepper (Capsicum) , cut into small cubes", "1 teaspoon Chana dal (Bengal Gram Dal)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "3 tablespoons Fresh coconut , grated", "Asafoetida (hing) , a pinch", "1 tablespoon Ginger , grated", "2 Green Chillies", "2 teaspoons Oil", "Salt , to taste"]'::jsonb, ARRAY['green chillies', 'red bell pepper (capsicum)', 'ginger', 'salt', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'curry leaves', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making the Red Capsicum Poriyal (Red Bell Peppers Stir Fry with Ginger Spiced Coconut), wash, deseed the red bell peppers and chop them into small cubes and keep aside.Heat oil in a wok, add the mustard seeds and let it splutter.", "Add the chana dal, asafoetida, curry leaves and let it splutter.To this add the cubed red bell peppers, season with salt and cook until they are crunchy yet cooked to 3/4th.Make a coarse mix of the grated coconut, ginger, green chillies using a mixer grinder without adding any water.Add this ginger spiced coconut mix to the cooked red peppers, mix well and switch off the heat.Serve the\u00a0Red Capsicum Poriyal\u00a0(Red Bell Peppers Stir Fry with Ginger Spiced Coconut), along with\u00a0Phulka,\u00a0Dal Palak\u00a0and\u00a0Kachumber Salad\u00a0for a nutritious weekday lunch."]'::jsonb, 20, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Red_Capsicum_Poriyal_Red_Bell_Peppers_Stir_Fry_with_Ginger_Spiced_Coconut.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/173.Red_Capsicum_Poriyal_Red_Bell_Peppers_Stir_Fry_with_Ginger_Spiced_Coconut.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sweet Corn Poriyal Recipe', 'sweet-corn-poriyal-recipe', 'Sweet Corn Poriyal Recipe is a delicious combination of sweet corn and coconut. You can serve this recipe with meals or as a salad. This is a very easy recipe that you can pack for your lunch box too.', '["300 grams Sweet corn , steamed", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Chana dal (Bengal Gram Dal)", "1 Dry Red Chilli", "1 sprig Curry leaves", "3 tablespoons Fresh coconut , grated", "3 sprig Coriander (Dhania) Leaves , roughly chopped", "Asafoetida (hing) , A pinch", "1 Green Chilli", "2 teaspoons Oil", "Salt , to taste"]'::jsonb, ARRAY['s sweet corn', 'mustard seeds', 'rai/ kadugu', 'chana dal', 'bengal gram dal', 'dry red chilli', 'curry leaves', 's fresh coconut', 'coriander', 'dhania', 'asafoetida', 'hing', 'reen chilli', 's oil', 'salt']::text[], '["To begin making the Sweet Corn Poriyal Recipe, firstly pressure cook the sweet corn with some salt till they become soft and tender.", "Take them out of the cooker and keep them aside.", "Add coconut, coriander leaves, green chilli in a mixer grinder and grind it.", "Keep it aside.", "Heat oil in a heavy bottomed pan.", "Add chana dal, mustard seeds and let it cook for about 10 seconds.", "After 10 seconds add in the asafoetida, dry red chilli and curry leaves.After 30 seconds, add in the steamed corn and mix.", "Cook for 2 minutes and then add the coconut paste.", "Mix well and serve hot.Serve\u00a0Sweet Corn Poriyal\u00a0along with\u00a0Mixed Vegetable Sambar\u00a0and\u00a0Steamed Rice\u00a0for your everyday lunch.", "Serve a\u00a0Pyaaz Curry Leaves Chaas\u00a0after your meal."]'::jsonb, 15, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Sweet_Corn_Poriyal_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/174.Sweet_Corn_Poriyal_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Arbi Dahi Wali Sabzi Recipe', 'arbi-dahi-wali-sabzi-recipe', 'Arbi dahi wali sabzi is a delicious light curry made of yogurt. Arbi can be used in dry or curry recipes. The dish made with arbi is delicious and is a favorite of many people .It is a no onion, no garlic recipe and an excellent choice for people fasting. This arbi dali wali sabzi is cooked in thick masala gravy made of Indian spices and yogurt. Serve it with hot rotis, pulkas, puris for a delicious combination.', '["250 grams Colocasia root (Arbi)", "1 cup Curd (Dahi / Yogurt)", "1/2 teaspoon Ajwain (Carom seeds)", "1 1/2 teaspoon Kashmiri Red Chilli Powder", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "2 tablespoon Coriander (Dhania) Leaves , chopped", "Salt , to taste", "Oil , to cook", "1 cup Water , adjustable"]'::jsonb, ARRAY['s colocasia root', 'arbi', 'curd', 'dahi / yogurt', 'ajwain', 'carom seeds', 'kashmiri red chilli powder', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'garam masala powder', 'coriander', 'salt', 'oil', 'water']::text[], '["To start preparing Arbi Dahi Wali Sabzi, scrub arbi to get rid of mud and dirt.", "Wash it twice at least.", "Pressure cook arbi with little water and a pinch of salt for 1 whistle (do not overcook).", "Arbi has to be cooked, but firm.Peel the skin off and cut them into half, lengthwise.Whisk yogurt or dahi well, keep aside.Heat oil in a pan.", "Add ajwain and saut\u00e9 for 10 seconds.Add red chili powder, turmeric powder, coriander powder and give it a mix.Add arbi and cook in oil and spices for about 10 to 12 minutes on medium flame with constant stirring.Add 1/2 cup water and bring it to boil.", "Let it boil for 5 to 7 minutes.Add the whisked curd and with constant stirring, cook until the gravy just begins to come to a boil.Add garam masala powder, chopped coriander leaves, stir well and turn off flame.Serve\u00a0Arbi Dahi Wali Sabzi along with\u00a0Pudina Tawa Paratha,\u00a0Mixed Sprouts Sabzi Recipe\u00a0and\u00a0Kachumber Salad\u00a0for a perfect meal."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Arbi_Dahi_Wali_Sabzi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/175.Arbi_Dahi_Wali_Sabzi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Menthi Vankaya Recipe - Andhra Style Fenugreek Spiced Baingan', 'menthi-vankaya-recipe-andhra-style-fenugreek-spiced-baingan', 'Menthi Vankaya is a South Indian Style Baingan Sabzi which is very popular among the Andhra Cuisine. No special occasion is complete without serving this scrumptious curry along with the entire meal. Baby brinjals are cooked with tamarind, cooled, stuffed with spice powder and fried.', '["10 Small Brinjal (Baingan / Eggplant)", "2 tablespoons Tamarind Paste , thick", "1/4 cup Water", "Salt , to taste", "4 tablespoons Oil", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "2 tablespoons Coriander (Dhania) Seeds", "1 tablespoon Chana dal (Bengal Gram Dal)", "1 tablespoon White Urad Dal (Split)", "1 tablespoon Sesame seeds (Til seeds)", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "3 Dry Red Chillies , adjustable", "2 tablespoons Raw Peanuts (Moongphali) , optional"]'::jsonb, ARRAY['salt', 'brinjal (baingan eggsplant)', 'water', 'curry leaves', 'white urad dal (split)', 'coriander (dhania) seeds', 'sesame seeds (til seeds)', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'tamarind paste', 'dry red chillies', 'peanuts (moongphali)', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making the Menthi Vankaya recipe, in a pan, dry roast ingredients mentioned under methi karam/spice powder which includes coriander seeds, chana dal, urad dal, sesame seeds, cumin seeds, fenugreek seeds, dry red chillies and raw peanuts.", "This will take about 2 minutes.Once everything is roasted well, cool it completely and grind into fine powder using a mixer grinder.If you are adding peanuts, add them last after all the other spices are finely powdered.", "Otherwise, the powder becomes oily.", "Keep the powder aside to stuff in the brinjals.Next, wash and pat dry the small brinjals thoroughly.", "Slit brinjals in such a way that you see an X at the base.", "Be careful not to slit open them completely.In a bowl, add water with salt and immerse the brinjals in salt water for 5 minutes.In a heavy bottomed pan, add half of the water, required salt and gently drop brinjals when water starts to boil.", "Make sure there is only one layer of brinjals.", "Do not put one brinjal over the other.Cook covered until brinjals are 80% done.", "This will not take more than 6 to 10 minutes.", "Now, add tamarind paste.", "If there is not enough water left, add some more water.", "Mix and cook for another 2 or 3 minutes until brinjals absorb all the salt and tamarind flavours.", "Remove from pan, cool them completely.", "Drain the remaining water.In the meantime, take a regular sewing thread, measure the length equal to twice the diameter of brinjals and cut into 10 or 12 pieces.", "After the brinjals are cooled down, stuff them with spice powder and wrap the thread around them gently.", "This ensures the spice powder does not come out while frying.", "Heat oil in the same wide pan, fry urad dal until golden and add curry leaves.", "Fry until crisp and gently place stuffed and secured brinjals in the pan.", "Fry the brinjals until they are completely cooked.", "Sprinkle the remaining spice powder on the top.Turn the brinjals gently using a fork and and a spoon.", "Do not use a ladle as it may break the brinjals.Once the brinjals are soft and cooked properly, remove the thread carefully and serve hot.Serve\u00a0Menthi Vankaya along with\u00a0Mixed Vegetable Sambar,\u00a0Steamed Rice\u00a0and\u00a0Elai Vadam\u00a0for a satisfying South Indian lunch with your family."]'::jsonb, 20, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Affiliate-Articles/Menthi_Vankaya_Brinjal_cooked_with_Fenugreek_spice_powder.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/176.Menthi_Vankaya_Brinjal_cooked_with_Fenugreek_spice_powder.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Veg Mughlai Paratha Recipe', 'veg-mughlai-paratha-recipe', 'Veg Mughlai Paratha Recipe is a paratha where crumbled paneer tossed with veggies is cooked in ground spices and filled with eggs in Indian Flat Bread to shape a thick fat square packet and served with tangy mint and coriander chutney. Best for any festival or special occasions. The authentic dish is made with minced keema mutton but we have created with egg scramble and vegetables to try this delicious dish.', '["2 cups Whole Wheat Flour", "Salt , to taste", "1 teaspoon Oil", "1 teaspoon Oil", "1 Onion , finely chopped", "1 Red Bell pepper (Capsicum) , finely chopped", "1 Green Bell Pepper (Capsicum) , finely chopped", "1 Carrot (Gajjar) , grated", "5 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "2 Green Chillies , finely chopped", "2 cups Paneer (Homemade Cottage Cheese) , grated", "1/2 teaspoon Garam masala powder", "1 teaspoon Fennel seeds (Saunf) , crushed", "1 teaspoon Red Chilli powder", "1/4 cup Mint Leaves (Pudina) , finely chopped", "Salt , to taste", "1/4 cup Whole Wheat Flour", "2 tablespoons Water"]'::jsonb, ARRAY['salt', 'wheat flour', 'red bell pepper (capsicum)', 'ginger', 'paneer', 'fennel seeds (saunf)', 'red chilli powder', 'cloves garlic', 'carrot', 'water', 'onion', 'green bell pepper (capsicum)', 'mint leaves (pudina)', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Veg Mughlai Paratha Recipe, get all the ingredients ready and prepped up.For dough, in a large mixing bowl, add the flour, salt and mix well to combine.", "Add a little water at a time to make a smooth dough.", "Once the dough has come together, drizzle a little oil and knead again to make the dough smooth.To make the mughlai stuffing, heat oil in a preheated pan over medium heat.", "Add the onion, ginger, garlic, and bell peppers.Saute until the onion and bell pepper have softened.Add the grated carrot, green chilli, paneer, garam masala, crushed fennel seeds, red chilli powder, salt and mint leaves.", "Stir well to combine and turn off the heat.Check the salt and seasonings and adjust according to taste.", "In a small mixing bowl, combine the wheat flour and water and make a smooth paste without lumps.", "This is called the slurry mixture.", "Divide the dough into 4 large portions.", "Heat the skillet on medium heat; place the roti on it and cook it for a few seconds each side till you see light bubbles and not allow to cook completely.", "Proceed the similar way with the remaining roti\u2019s.Remove the partially cooked roti and place it on a clean surface.Spoon a large portion of the filling mixture in the center.", "Spread the slurry mixture around the edges of the roti.", "Carefully fold the roti in such a way to make a square.", "Seal the edges with more slurry if required.Place the stuffed roti on the preheated pan.", "Cook on both sides, using little oil or ghee till the parathas are golden brown.", "Make sure you cook on medium heat so the parathas get cooked evenly from inside out.Once done, serve hot.", "Serve Mughlai Keema Paratha along with\u00a0Dhaniya Pudina Chutney\u00a0and\u00a0Boondi Raita\u00a0for a weekend lunch or dinner."]'::jsonb, 40, 'Mughlai', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Veg_Mughlai_Paratha_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/177.Veg_Mughlai_Paratha_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Pulao Recipe - Pulao Spiced With Saffron, Whole Spices & Nuts', 'kashmiri-pulao-recipe-pulao-spiced-with-saffron-whole-spices-nuts', 'Kashmiri Pulao is delicious mildly sweet royal pulao flavoured with saffron, aromatic spices, fried nuts and garnished with fruits. This lip-smacking pulao loaded with richness from the saffron and nuts, and makes a perfect accompaniment for any festive occasion or parties.', '["3 cups Basmati rice , soaked for 45 minutes", "1 tablespoon Ginger , thinly sliced", "3/4 teaspoon Dry ginger powder", "1-1/2 teaspoon Fennel seeds (Saunf)", "1-2 Green Chillies , slit", "1/2 teaspoon Kashmiri Red Chilli Powder", "1 tablespoon Cashew nuts , roughly broken", "1 tablespoon Whole Almonds (Badam) , roughly chopped", "1 tablespoon Walnuts , roughly chopped", "1/2 tablespoon Sultana Raisins", "1 tablespoon Pistachios , roughly chopped", "Saffron strands , few strands soaked in warm milk", "2-1/2 cups Milk", "3 cups Water", "Salt , to taste", "3 tablespoon Ghee", "Whole Spices", "1 teaspoon Ajwain (Carom seeds)", "2 inch Cinnamon Stick (Dalchini)", "2 Black cardamom (Badi Elaichi)", "4-5 Cardamom (Elaichi) Pods/Seeds", "6 Cloves (Laung)", "2 Bay leaves (tej patta)", "1/4 cup Apples , diced small, for garnish", "1/4 cup Pineapple , diced small, for garnish", "1/4 cup Caramelized onions"]'::jsonb, ARRAY['basmati rice', 'kashmiri red chilli powder', 'pistachios', 'ajwain (carom seeds)', 'onion', 'green chillies', 'salt', 'black cardamom (badi elaichi)', 'pineapple', 'cardamom (elaichi) podsseeds', 'raisins', 'walnuts', 'saffron strands strands milk', 'apples', 'water', 'cashew nuts', 'ginger', 'bay leaves (tej patta)', 'ghee', 'fennel seeds (saunf)', 'milk', 'dry ginger powder', 'badam (almond)', 'cinnamon stick (dalchini)', 'cloves (laung)']::text[], '["To begin making the Kashmiri Pulao Recipe, first wash and soak the rice for about 45 minutes.", "After 45 minutes, drain the water and keep aside.In a heavy bottom sauce pan, heat 2 tablespoons of ghee.Add bay leaf, shahjeera, black cardamom, cloves, green cardamom, cinnamon sticks and fry them for few seconds until they release a roasted aroma.Add a tablespoon of broken cashews and fry for another minute until the cashews are roasted golden.Add ginger juliennes, ginger powder, fennel powder, Kashmiri chili powder, salt and the soaked rice and fry for few seconds.", "Add milk, saffron milk, water and bring the pulao to a brisk boil.", "Once it comes to a boil, turn the heat to low, cover the pan and allow the rice to cook, until all the liquid has be absorbed.", "Meanwhile, heat another tablespoon of oil in the pan and roast the dry fruits until light golden brown.", "Take it off the heat and keep aside.Once the rice is done, add roasted nuts to the rice and gently fluff up the rice with the fork.", "Transfer the rice to a serving platter, garnish it with fried onions and diced fresh fruits.Serve the Kashmiri Pulao\u00a0Recipe along with\u00a0Paneer Tikka Masala,\u00a0Butter Naan\u00a0and\u00a0Mint Raita\u00a0to make a complete dinner."]'::jsonb, 65, 'Kashmiri', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Farrukh_Aziz_Ansari/Kashmiri_Pulao.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/178.Kashmiri_Pulao.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spring Onion Dosa Recipe', 'spring-onion-dosa-recipe', 'Spring Onion Dosa is an aromatic and tasty dosa which is made with the addition spring onions. They are mild in taste and mostly grown in mildly cool temperature. Spring Onions lack fully developed bulbs and the entire plant is used in making salads, soups and chutney', '["1 cup Spring Onion (Bulb & Greens) , chopped", "1 cup Spring Onion Greens , chopped", "2 cups Dosa rice", "1/2 cup Poha (Flattened rice)", "2 tablespoons White Urad Dal (Split)", "1 tablespoon Methi Seeds (Fenugreek Seeds)", "6 Dry Red Chillies", "1/4 cup Fresh coconut , grated", "2 tablespoon Jaggery , grated", "Water , as required for batter", "Oil , to prepare dosa", "Salt , to taste"]'::jsonb, ARRAY['salt', 'spring onion greens', 'coconut', 'poha (flattened rice)', 'jaggery', 'spring onion (bulb greens)', 'white urad dal (split)', 'dry red chillies', 'methi seeds (fenugreek seeds)', 'sunflower oil prepare dosa', 'water batter', 'dosa rice']::text[], '["To begin making the Spring Onion Dosa, clean dosa rice with water and soak in water for 4 hours.Soak urad dal and methi seeds separately in water for 4 hours.", "Clean thick poha with water and soak with little water for 15 mins.After 4 hours, take a mixer jar add half of soaked rice, urad dal, methi seeds and grind into fine paste.", "Pour this into a mixing vessel.Now add remaining rice, soaked poha, red chilies and grated fresh coconut in a mixer jar and grind into fine paste.Pour this ground paste into the batter bowl and mix everything properly.", "Add grated jaggery and mix well.", "Next add the finely chopped spring onion (both bulbs and greens), salt into the batter and mix well.", "Add water as required to prepare the medium thick batter.", "Heat a skillet and pour the Spring Onion dosa batter over the heated skillet.Sprinkle oil on the surface and close with a lid.", "Cook the dosa properly from both the sides.", "Serve hot with butter, ghee, and liquid jaggery.Serve Spring Onion Dosa along with\u00a0Dhaniya Pudina Chutney,\u00a0South Indian Coconut Chutney\u00a0or any other chutney of your choice."]'::jsonb, 30, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pavithrahr-gmail.com/Karnataka_Style_Spring_Onion_Dosa.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/179.Karnataka_Style_Spring_Onion_Dosa.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Matta Rice/ Chemba Rice Recipe-Pressure Cooker Method', 'matta-rice-chemba-rice-recipe-pressure-cooker-method', 'Traditionally Matta Rice is soaked and cooked in lots of water and then the excess water is drained. Traditional method can take a long time to cook and hence I have given this Pressure Cooker method which is much quicker.', '["1 cup Red matta rice", "3-1/2 cups Water", "Salt , (if required)"]'::jsonb, ARRAY['red matta rice', 's water', 'salt']::text[], '["To begin making the Matta Rice first wash the rice in a saucepan three times and soak the rice in water for half an hour.Drain the soaked rice and transfer it to a pressure cooker.", "Add 3 cups of water in the pan of the pressure cooker, cover and place the weight on.Cook the matta rice in the pressure cooker on medium high heat for 3 to 4 whistles; after the 3 to 4 whistles turn the heat to low.", "Pressure cook the rice for another 5 to 8 minutes and turn off the heat.Allow the pressure to release naturally.", "Wait for the pressure to release completely and then open the cooker.The Matta rice takes a little longer to cook than the traditional rice and hence the cooking time is much longer.", "Serve Matta rice with\u00a0Mixed Vegetable Sambar,\u00a0Cabbage Thoran/Poriyal\u00a0and\u00a0Spicy Lime Pickle\u00a0for a vegetarian option or you can serve it with\u00a0Kerala style Fish Curry\u00a0for a non vegetarian option."]'::jsonb, 70, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Cooked_Matta_Rice_Kerala_Rice_Recipe-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/180.Cooked_Matta_Rice_Kerala_Rice_Recipe-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aratikaya Tomato Koora Recipe - Andhra Style Plantains With Tomato', 'aratikaya-tomato-koora-recipe-andhra-style-plantains-with-tomato', 'Aratikaya Tomato Koora is a delicious Andhra style plantains cooked with tomatoes. Plantains are rich in Vitamin C, K, amino acids and dietary fibres as compared to the ripened bananas making it relatively good for health.', '["3 Plantain Stem , cut into small cubes", "1 Onion , finely chopped", "3 Tomatoes , finely chopped", "1 Green Chilli , finely chopped", "1 tablespoon Ginger , grated", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon White Urad Dal (Split)", "Asafoetida (hing) , a pinch", "1 sprig Curry leaves", "Oil , as required", "Salt , to taste"]'::jsonb, ARRAY['plantain stem', 'onion', 'tomatoes', 'reen chilli', 'ginger', 'red chilli powder', 'turmeric powder', 'haldi', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'white urad dal', 'split', 'asafoetida', 'hing', 'curry leaves', 'oil', 'salt']::text[], '["To begin making the Aratikaya Tomato Koora Recipe (Andhra Style Plantains Cooked with Tomato), peel the outer skin of the plantains, chop them into small cubes and place it in a bowl of water to avoid discolouration until cooking.Heat oil in a heavy bottomed pan, add the mustard seeds, cumin seeds, urad dal and let it crackle.Add the asafoetida, curry leaves and let it splutter.", "Add the chopped onion and saute until translucent.Add the grated ginger, green chilli, turmeric powder, red chilli powder and saute until the raw flavour of the ginger goes away.Now, drain the water from the plantains and add it to the pan.", "Season with salt, mix well and cover with a lid to cook for 10 minutes.Now, add the chopped tomatoes and mix well.", "Sprinkle a little water and leave it to cook further for another 5 minutes with the lid on.Once done, gently stir everything together and switch off the flame.Serve the\u00a0Aratikaya Tomato Koora Recipe\u00a0(Andhra Style Plantains Cooked with Tomato) along with\u00a0Phulkas\u00a0or\u00a0Steamed Rice\u00a0and\u00a0Andhra Style Pappu Charu\u00a0for the weeknight dinner."]'::jsonb, 30, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Aratikaya_Tomato_Koora_Recipe_Andhra_Style_Plantains_Cooked_with_Tomato.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/181.Aratikaya_Tomato_Koora_Recipe_Andhra_Style_Plantains_Cooked_with_Tomato.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Style Labra Recipe - Mix Vegetable Sabzi', 'bengali-style-labra-recipe-mix-vegetable-sabzi', 'A quintessential vegetarian dish typically made during Pujo and offered to the Goddess as Bhog along with Bhoger Khichuri, Bhaja and Khejur Chutney (Dates & Tomato Chutney). The term Labra came with the mushy texture given to the dish by adding pumpkin that also gives mild sweetness to the dish.The sabzi is loaded with vegetables that are very nutritious to have it on our everyday diet.', '["1 cup Potatoes (Aloo) , peeled and cut into cubes", "1 cup Kaddu (Parangikai/ Pumpkin) , peeled and diced", "1 cup Carrot (Gajjar) , peeled and diced", "1 cup Cauliflower (gobi) , cut into florets", "1 cup Brinjal (Baingan / Eggplant) , cut into pieces", "2 Drumstick , scraped and cut into 2 inch pieces", "1/2 cup Green peas (Matar)", "1 teaspoon Turmeric powder (Haldi)", "1/2 cup Fresh coconut , thinly sliced", "Salt , to taste", "1/2 teaspoon Sugar", "4 tablespoons Mustard oil , adjustable", "1 teaspoon Panch Phoran Masala", "2 Bay leaf (tej patta)", "2 tablespoon Coriander (Dhania) Leaves , for garnish (chopped)"]'::jsonb, ARRAY['salt', 'parangikai pumpkin', 'mustard oil', 'coconut', 'brinjal (baingan eggsplant)', 'bay leaf (tej patta)', 'cauliflower (gobi)', 'coriander (dhania) leaves', 'green peas (matar)', 'drumstick scraped', 'carrot', 'sugar', 'panch phoran masala', 'potato (aloo)', 'turmeric powder']::text[], '["To begin making the Labra Recipe, clean, wash and cut vegetables as mentioned and collect them in a large bowl.", "Add water in the bowl and keep aside.Heat oil in a large wok and add panch phoran masala, bay leaf and green chillies and wait till they splutter.", "Now drain the vegetables from water and add it into the wok keeping flames high.Mix well and add salt and turmeric powder and let the vegetables cook on high for a minute or two.", "Close the lid and lower the flames.", "Let the vegetables cook till they are soft and tender.", "Once the vegetables are soft and mushy, sprinkle sugar and fresh coconut slices and give a quick mix again and turn off the flames.", "Garnish the\u00a0Labra with fresh chopped coriander and serve warm.Serve Labra along with\u00a0Bengali Bhog Khichuri\u00a0and\u00a0Kachumber Salad\u00a0for a weekday meal."]'::jsonb, 40, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/shaheen_ali/Labra__Bengali_Mix_Vegetable_Offered_In_Bhog_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/182.Labra__Bengali_Mix_Vegetable_Offered_In_Bhog_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tok Dal Recipe (Bengali Style Masoor Dal)', 'tok-dal-recipe-bengali-style-masoor-dal', 'Tok Dal or Aam Dal is a lip smacking Bengali curry made using Raw mango. It is easy and can be served as a side dish with your Indian meal.', '["1 Mango (Raw) , tender and medium sized", "1 cup Masoor Dal (Whole)", "1 teaspoon Turmeric powder (Haldi)", "2 to 4 Green Chillies", "Salt , to taste", "1 tablespoon Mustard oil", "1 Bay leaf (tej patta)", "2 Dry Red Chilli", "1 teaspoon Panch Phoran Masala"]'::jsonb, ARRAY['salt', 'mustard oil', 'bay leaf (tej patta)', 'dry red chilli', 'masoor dal', 'mango tender', 'panch phoran masala', 'turmeric powder', 'green chillies']::text[], '["To begin making the Tok Dal recipe, peel and slice the mangoes, along with the seed if possible.", "Wash and soak masoor dal for half an hour.Pressure cook mango, dal, turmeric and slit green chillies together till the dal is cooked.", "Mangoes should still hold the shape and not be overcooked.Once the cooker is cooled, open the lid and mash just the dal a little.In a heavy bottomed pan, heat the mustard oil.", "Add bay leaf, paanch phoran and red chilly to it.", "Let it crackle.Add the cooked dal and 1/2 cup water to the tempering.Add salt to taste and boil till the dal thickens.Once it is done, switch off the stove an it is ready to be served.Tangy, creamy and light, Tok dal goes best with steamed rice and a dollop of ghee."]'::jsonb, 55, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuri_Aggarwal/Tok_Dal.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/183.Tok_Dal.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Fish Tikka Masala Gravy Recipe', 'fish-tikka-masala-gravy-recipe', 'Fish Tikka Masala Gravy Recipe is a delicious curry that you can try at home as your Sunday special. The curry is made using basa fillet which is cooked in a creamy tomato gravy flavored with tikka masala. The tikka curry is known for its rich creamy texture.', '["2 Basa fish , cut into small size pieces", "1 Lemon juice", "1/4 teaspoon Turmeric powder (Haldi)", "Salt and Pepper , a pinch", "1 Cardamom (Elaichi) Pods/Seeds", "1 Bay leaf (tej patta)", "1 teaspoon Cumin powder (Jeera)", "1-1/2 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Ginger Garlic Paste", "1/2 teaspoon Red Chilli powder", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "1 cup Lukewarm Water", "2 tablespoon Fresh cream", "Salt , to taste", "1 Onion , chopped", "1/2 Tomato , chopped", "5 Cashew nuts", "2 Cloves (Laung)", "1/4 teaspoon Cinnamon Powder (Dalchini)"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'cashew nuts', 'cardamom (elaichi) podsseeds', 'bay leaf (tej patta)', 'red chilli powder', 'water', 'ginger garlic paste', 'basa fish', 'lemon', 'onion', 'pepper', 'coriander powder', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'cloves (laung)', 'cinnamon powder (dalchini)']::text[], '["To begin making the Fish Tikka Masala Gravy Recipe, marinate the fish with lemon juice, salt, pepper and turmeric powder and rest it aside for 30 minutes.Pressure cook the onion, tomatoes, cloves, cinnamon powder, cashew nuts with little water.Once done, allow the pressure to release naturally, grind it along with its juice to a smooth paste.Heat a kadai with oil, add cardamom pod, bay leaf and allow it to sizzle.Add in ground tomato paste, sprinkle little salt and cook till the raw smell goes away.Add in all the spice powders mentioned above including cumin powder, coriander powder, turmeric powder, red chilli powder and stir well, cover it with the lid and cook again for another 5 minutes.Add cream, marinated fish pieces, salt to taste, you can add 1 cup of water and cook till the masala comes together.At the end sprinkle little kasuri methi and give it a stir.Serve the Fish Tikka Masala Gravy Recipe along with\u00a0Naan,\u00a0Pickled Onions\u00a0and\u00a0Beetroot Raita\u00a0by the side to complete your meal."]'::jsonb, 40, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Fish_Tikka_Masala_Gravy_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/184.Fish_Tikka_Masala_Gravy_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Moong Dal With Radish Greens Recipe', 'moong-dal-with-radish-greens-recipe', 'Moong Dal with Radish Greens Recipe is a quick and easy nutritious vegetable that you can make in a jiffy for a quick and easy weeknight dinner. Fresh radish leaves not only add crunch to the dal but also increase its iron quotient of this sabzi. Radish Greens are high in fibre and make an excellent ingredient to cook with when catering to a diabetic person in the family. Serve this Moong Dal with Radish Greens for dinner or lunch as it is an excellent accompaniment for salad.', '["1 cup Yellow Moong Dal (Split)", "Mooli Ke Patte (Radish Greens) , a bunch, finely chopped", "Salt , to taste", "3 cloves Garlic , finely chopped", "1 inch Ginger , grated", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Amchur (Dry Mango Powder)", "2 tablespoons Oil", "Ingredients for tempering", "1 tablespoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies"]'::jsonb, ARRAY['salt', 'yellow moong dal (split)', 'ginger', 'amchur (dry mango powder)', 'ghee', 'red chilli powder', 'cloves garlic', 'mooli ke patte (radish greens) bunch', 'dry red chillies', 'cumin seeds (jeera)', 'turmeric powder', 'sunflower oil']::text[], '["To prepare the Moong Dal With Radish Greens recipe, begin by cleaning and washing the moong dal.", "Soak it in water for 10-15 minutes.Meanwhile wash the radish greens well and chop them finely.Next, in a pressure cooker heat a teaspoon of cooking oil over medium heat.", "Once oil is hot enough add the chopped garlic and grated ginger.", "Stir fry on low heat till garlic turns light brown in color.Add the soaked moong dal along with turmeric powder, red chili powder, mango powder and 2 cups of water and stir to combine.", "Close the lid of the pressure cooker and let the moong dal cook over medium heat for 2 to 3 whistles.", "Turn off the heat.", "Allow the pressure to release naturally.While the dal is cooking in the pressure cooker, in a pan heat a teaspoon of oil over medium heat.", "Add the chopped radish greens and cook until the greens are wilted and cooked through.", "Turn off the heat and keep aside.Once the pressure has released, open the lid of the pressure cooker and gently mash the dal with the back of the spoon.", "This will help thicken the moong dal.", "Add the cooked radish greens and stir to combine.", "Check the salt and spice levels and adjust to suit your taste.The last step is to temper the dal.", "In a tadka pan, heat some ghee on medium heat.", "When it is warm, add the cumin seeds.", "Once they crackle, add the red chilli, roast the chillies for a few seconds and turn off the heat.Pour the tadka over the dal and stir to combine.", "Serve Moong Dal With Radish Greens hot along with phulkas, rice and salad."]'::jsonb, 51, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Hina_Gujral/Moong_Dal_Recipe_with_Radish_Greens.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/185.Moong_Dal_Recipe_with_Radish_Greens.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vegan Curried Rice with Chickpeas Recipe', 'vegan-curried-rice-with-chickpeas-recipe', 'Vegan Curried Rice with Chickpeas Recipe is a one pot meal that can be made in a jiffy. It is a comforting meal that you would want to try for a cozy dinner or lunch. The recipe is simple all you have to be to soak the chickpeas a day in advance and cook them and keep it ready. The rice is mixed with mild flavors of curry powder and tossed in with chickpeas. The dish is also vegan so the best main course to be served for all the vegan eaters.', '["1 cup Brown Rice , soaked for 30 minutes and washed", "1/2 cup Kabuli Chana (White Chickpeas) , soaked overnight and boiled", "2 cloves Garlic , chopped", "1 inch Ginger , chopped", "1 teaspoon Fennel seeds (Saunf)", "2 1/2 cup Vegetable stock , you can even use the drained water of chickpeas", "3 tablespoon Curry powder", "Salt , to taste", "4 sprigs Coriander (Dhania) Leaves , Chopped"]'::jsonb, ARRAY['salt', 'brown rice', 'ginger', 'vegetable stock you can even the water chickpeas', 'fennel seeds (saunf)', 'cloves garlic', 'kabuli chana (white chickpeas)', 'coriander (dhania) leaves', 'curry powder']::text[], '["To begin making the Vegan Curried Rice with Chickpeas Recipe, heat a pressure cooker with oil.", "Add the ginger garlic and fry till soften.", "Add the fennel seeds as well.", "Saute for 10 more secondsAdd the soaked and washed rice, curry powder salt and stock pressure cook for 4 whistle till the rice is done.Remove and mix well add the chickpeas as well and check for salt.", "Add chopped coriander leaves and serve.Serve the Vegan Curried Rice with Raisins and Chickpeas Recipe along with\u00a0salads\u00a0or\u00a0Tomato Onion Cucumber Raita Recipe\u00a0by the side."]'::jsonb, 55, 'Asian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Vegan_Curried_Rice_with_Chickpeas_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/186.Vegan_Curried_Rice_with_Chickpeas_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Brinjal Curry Recipe | Spicy Eggplant Curry in Coconut Milk', 'kerala-style-brinjal-curry-recipe-spicy-eggplant-curry-in-coconut-milk', 'Kerala Style Brinjal Curry Recipe is a very simple dish which is just perfect for a cold rainy day. It warms you up with all the spices and the richness from the coconut milk and flavours from green chillies and curry leaves.', '["8 Baby brinjals , washed and cut into wedges", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "2 tablespoons Coconut Oil , to shallow fry", "1 tablespoon Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Fennel seeds (Saunf)", "2 sprig Curry leaves , torn", "2 Green Chillies , slit", "1 cup Pearl onions (Sambar Onions) , quartered", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "2 Tomatoes , finely chopped", "1/2 cup Coconut milk", "Salt , to taste", "6 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['baby brinjals', 'turmeric powder', 'haldi', 'salt', 's coconut oil', 'coconut oil', 'mustard seeds', 'rai/ kadugu', 'fennel seeds', 'saunf', 'curry leaves', 'reen chillies', 'pearl onions', 'sambar onions', 'red chilli powder', 'tomatoes', 'coconut milk', 'coriander', 'dhania']::text[], '["To begin making the Kerala Style Brinjal Curry Recipe, we will first shallow fry the baby brinjals.", "Cut the brinjals into wedges, and place them in water as you cut them to prevent them getting discoloured.", "In oil a pan heat over medium heat; add the cut brinjal wedges, salt, turmeric powder and saute for a few minutes until they soften and get cooked.", "Cover the pan and cook the brinjal to fasten the cooking process.", "Once done, turn off the heat and keep aside.To make the curry, heat coconut oil in a heavy bottom pan over medium heat; add the mustard seeds, fennel seeds and curry leaves.", "Allow them to crackle.", "Next add the slit green chillies and onion and saute till the onions soften and turn transparent.", "Stir in the tomatoes, salt, turmeric powder and red chilli powder.", "Cover the pan and cook until the tomatoes turn mushy.", "This will take about two minutes.", "Once the whole onion- tomato gravy has come together, reduce the heat and add in the coconut milk and the sauteed brinjal.", "Give the\u00a0Kerala Style Brinjal Curry a brisk boil for 3 to 4 minutes so the flavours seep well to make a delicious tasting curry.", "Check the salt and adjust to suit your taste.", "Transfer the\u00a0Kerala Style Brinjal Curry to a serving bowl, stir in the chopped coriander leaves and serve hot.", "Serve\u00a0Kerala Style Eggplant Curry\u00a0with\u00a0Spiced Ghee Rice Recipe | Neychoru,\u00a0Kerala Parotta\u00a0and\u00a0Cabbage Thoran\u00a0for a simple weekday lunch."]'::jsonb, 50, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Donna_George/Kerala_Style_Brinjal_Curry_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/187.Kerala_Style_Brinjal_Curry_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Kappa Ishtoo Recipe -Tapioca Stew Recipe', 'kerala-style-kappa-ishtoo-recipe-tapioca-stew-recipe', 'Tapioca Stew or Kappa Ishtoo is a delicious tapioca curry, prepared using coconut milk, fresh tapioca root and flavored with whole crushed pepper, cinnamon, cardamom and cloves.  A very simple stew that is nutritious and rich in flavors, it has ingredients that are very minimal, yet which make great impact.', '["500 grams Tapioca root , or kappa, cleaned and diced into 1\u201dpieces", "1 Carrot (Gajjar) , cut diagonally", "1 Onion , sliced", "1 Cinnamon Stick (Dalchini)", "1 Cardamom (Elaichi) Pods/Seeds", "3 Cloves (Laung)", "1 teaspoon Whole Black Peppercorns , crushed", "200 ml Coconut milk", "1/2 inch Ginger , sliced thin", "2 Green Chillies , deseeded and slit in two", "2-3 sprig Curry leaves , roughly torn", "1 1/2 tablespoons Coconut Oil", "1 1/2 tablespoons Coconut Oil , for cooking", "Salt , to taste"]'::jsonb, ARRAY['s tapioca root', 'carrot', 'gajjar', 'onion', 'cinnamon stick', 'dalchini', 'cardamom', 'elaichi', 'laung', 'whole black peppercorns', 'coconut milk', 'ginger', 'reen chillies', 'curry leaves', 's coconut oil', 'salt']::text[], '["To begin making the Kerala Style Kappa Ishtoo Recipe (Tapioca Stew Recipe),\u00a0 start by adding the tapioca pieces in a cooker along with green chillies, ginger and salt.", "Add in about 2 cups of water, so that the tapioca is fully immersed and pressure-cook it on high until you hear 3 whistles.", "When done, switch of the gas and set the cooker down.Heat a kadai with coconut oil, crackle the mustard seeds and curry leaves and then add the cinnamon sticks, cloves and cardamom.", "Saute till the aromas are relapsed and then add in the sliced onions and carrot and saute for 2 minutes until the onions turn soft.Add the coconut milk along with the tapioca , give it a stir and keep the stew covered and simmering for 5 minutes.", "Turn off the heat and let the tapioca stew rest for a few minutes to allow the flavors to blend together.", "Check for seasoning and serve.Serve Kerala Style Kappa Ishtoo Recipe (Tapioca Stew Recipe) along with\u00a0Steamed Rice Recipe\u00a0and accompanied by sides of\u00a0Kerala Vendakka Thoran\u00a0(Okra Stir Fry) or\u00a0Cabbage Thoran."]'::jsonb, 40, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/22-feb/Tapioca_Stew_Kerala_Style-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/188.Tapioca_Stew_Kerala_Style-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Moolangi Tovve Recipe - Radish Curry', 'moolangi-tovve-recipe-radish-curry', 'Moolangi Tovve is a simple dal which is made with the combination of lentils and vegetables. Tovve is a Kannada term which means a simple, basic and humble dal, something that is not heavy and is light on the tummy.', '["3 Mooli/ Mullangi (Radish) , peeled and sliced (5mm thick)", "1/2 cup Yellow Moong Dal (Split)", "1 teaspoon Turmeric powder (Haldi)", "2 Green Chillies , finely chopped", "1 teaspoon Ginger , grated", "2 tablespoon Fresh coconut , freshly grated", "1 tablespoon Ghee", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies", "1 pinch Asafoetida (hing)", "Coriander (Dhania) Leaves , Few sprigs, finely chopped", "2 Lemon wedges"]'::jsonb, ARRAY['yellow moong dal (split)', 'ginger', 'mooli mullangi (radish) (mm )', 'coriander (dhania) leaves', 'coconut', 'ghee', 'mustard seeds', 'asafoetida (hing)', 'dry red chillies', 'lemon', 'turmeric powder', 'green chillies']::text[], '["To begin making\u00a0 Moolangi Tovve Recipe - Radish Curry, wash the moong dal couple of times with water and add it to the pressure cooker along with radish, turmeric powder, green chillies and 1.5 cups of water.Pressure cook for 3 whistles.", "After three whistles turn off the heat and let the pressure release naturally.", "Once done, open the lid and keep aside.", "Heat oil in a pan, add asafoetida, mustard and wait for the mustard to pop and then add red chillies and ginger and ler the red chillies crisp up.Now add the cooked dal mixture in the pan with salt to taste and 1.5 cups of water.", "Brisk boil till the dal gets slightly thick.Once it is done, add the chopped coriander and grated coconut in the Moolangi Tovve and give it a stir.", "Tun off the heat and transfer the\u00a0Moolangi Tovve to a serving bowl and serve.", "Serve\u00a0Moolangi Tovve Recipe - Radish Curry\u00a0with\u00a0Steamed Rice Recipe\u00a0and\u00a0Elai Vadam\u00a0for a comforting lunch."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuri_Aggarwal/Moolangi_Tovve__Raddish_Curry_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/189.Moolangi_Tovve__Raddish_Curry_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mulakootal Recipe (Vegetables In Coconut Gravy)', 'mulakootal-recipe-vegetables-in-coconut-gravy', 'Mulakootal Recipe is a very old, traditional Palakkad Brahmin recipe. It’s a curry made from a combination of lentils and vegetables and coconut gravy. It is a mildly spiced gravy that goes well with steamed rice and ghee. There are some variations of mulakootal, basically depending on the type of vegetable one uses in cooking it. There is keerai mulakootal made with lentils and spinach, there is pumpkin mulakootal made using pumpkin and vegetable mulakootal uses different types of vegetables. This curry comes very close to kootu which we make in Tamil Nadu.', '["1/2 cup Yellow Moong Dal (Split) , can use toor dal as well", "2 cups Mixed vegetables , I have used radish turnips, and brinjal", "1/2 teaspoon Turmeric powder (Haldi)", "1 cup Water", "Salt , to taste", "1/2 cup Fresh coconut , grated", "3 Dry Red Chillies", "1 teaspoon Oil", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'mixed vegetables have used radish turnips', 'coconut', 'mustard seeds', 'water', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'turmeric powder', 'yellow moong dal (split) can toor dal', 'sunflower oil']::text[], '["To begin with the Mulakootal Recipe first, in a blender grind fresh coconut and dried red chilies together to a coarse paste.Now in a pressure cooker wash the lentils and cook them completely.Take a\u00a0Kadai add the vegetables, cook the vegetables completely.", "After the vegetables are cooked add the dal to it and mix them well.Combine and cook the vegetables and dal for 5 minutes and then add coconut paste to the mixture.", "On low flame cook for another 5 minutes.", "You can add some water if you feel the consistency is thickNow in a small pan heat some oil and add mustard seeds, wait till they splutter and then add urad dal, curry leaves.Add this tempering to the mulakootal and serve it hot.Serve your Mulakootal with hot rice or roti with some curd."]'::jsonb, 70, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Mulakootal.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/190.Mulakootal.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Soya Keema Masala Recipe', 'spicy-soya-keema-masala-recipe', 'Keema is a South Asian meat dish that literally means minced meat in Turkish. Keema can be made with any meat but usually Keema is associated with mutton mince. Vegetarians Keemas usually involve peas or cauliflower. Most Keemas are minced meats that are mixed with aromatic spices that are either eaten by itself or added to rice or stuffed in breads.', '["2 Cups Soy Chunks (Nuggets)", "1 Onion , chopped", "2 Tomatoes , pureed", "3 Green Chillies , chopped", "1 Bay leaf (tej patta)", "1 Black cardamom (Badi Elaichi)", "2 Cloves (Laung)", "5 Whole Black Peppercorns", "1/2 inch Cinnamon Stick (Dalchini)", "1 teaspoon Ginger Garlic Paste", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1-1/2 Tablespoon Garam masala powder", "1 Tablespoon Lemon juice", "Salt , to taste", "Oil , as required"]'::jsonb, ARRAY['tomato', 'black cardamom (badi elaichi)', 'salt', 'bay leaf (tej patta)', 'red chilli powder', 'black peppercorns', 'ginger garlic paste', 'onion', 'cinnamon stick (dalchini)', 'lemon', 'soy (nuggets)', 'coriander powder', 'turmeric powder', 'green chillies', 'cloves (laung)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Soya Keema Masala Recipe, boil some water and soak the Soya Chunks into the hot water for 15 to 20 minutes.Once the chunks have fully absorbed the water, take them out and squeeze them to drain extra water.", "Mince all the soya chunks using a grinder but be careful not to over grind the chunks.Heat oil in a heavy bottomed pan and once the oil is ready, add cumin seeds into the pan.", "Once the seeds start to sputter, add bay leaf, black cardamom, cloves, peppercorns, cinnamon and saute it for 2 minutes.Now add the finely chopped onions into the pan and cook it for 5-7 minutes or till the time they are golden pink in colour.", "Next step is to add turmeric powder, coriander powder, red chilli powder and give it a good stir.", "Next add the ginger garlic paste, chopped green chili and let this mixture cook for 5 minutes or till the time oil gets separated from the spices.", "Next, add the tomato puree into the pan and cook on slow heat for about 5 minutes.Add minced soya, salt and garam masala powder, lime juice into the pan and give it a good stir.", "Cook it for 5 minutes and make sure that soya is not sticking to the bottom.Add 1/2 cup water, cover the pan and cook for 5 minutes on low heat.", "After 5 minutes, check if the raw taste of soya has gone, if it is still there add little bit more water and cook for another 5 minutes.", "Garnish it with fresh coriander leaves and serve it hot with some chapati or naan.Serve\u00a0Soya Keema Masala\u00a0Recipe along with\u00a0Whole Wheat Laccha Paratha\u00a0and\u00a0Tomato Onion Cucumber Raita\u00a0for a weekday meal."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/garimasgautam-gmail.com/Soya_Keema_Masala.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/191.Soya_Keema_Masala.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Style Black Chickpeas And Cucumber Masala Recipe (Taushem Tondak)', 'goan-style-black-chickpeas-and-cucumber-masala-recipe-taushem-tondak', 'The Taushem Tondak is a delicious Goan style Black Chickpeas and Cucumber Masala Curry that is made in a tangy and spicy coconut base. Taushem means cucumber and tondak means masala gravy. The addition of Kabuli chana or black chickpeas to this tondak to make it a bit unique and a twist I have given to the recipe. You can add any type of gram to this tondak to make it a high protein and wholesome dish.', '["2 cups Cucumber , peeled and cubed", "1/2 cup Kala Chana (Brown Chickpeas) , soaked in water", "1 cup Fresh coconut , grated", "4 Dry Red Chillies", "1 Tamarind , marble sized ball", "1 teaspoon Coriander (Dhania) Seeds", "1/2 teaspoon Turmeric powder (Haldi)", "5 Whole Black Peppercorns", "1/4 teaspoon Sugar", "Salt , to taste"]'::jsonb, ARRAY['salt', 'coconut', 'black peppercorns', 'tamarind marble', 'sugar', 'dry red chillies', 'coriander (dhania) seeds', 'cucumber', 'turmeric powder', 'kala chana (brown chickpeas)']::text[], '["To begin making the Black Chickpeas And Cucumber Masala Recipe, we will first soak the black chickpeas in water for at least 8 hours or overnight hours.", "Once soaked pressure-cook in a pressure cooker until it is cooked through and soft.", "Its takes about 30 minutes to cook the chickpeas and sometimes a little more time.", "Steam the cucumber in a steamer for about 5 minutes.", "Once cooked through, keep aside.Grind the ingredients meant for gravy by little water water to make a smooth paste.Into a large sauce pan, add the ground paste, the cooked chickpeas, sugar and salt to taste and the steamed cucumber.", "Stir well to combine all the ingredients.", "Check the salt and spices and adjust to suit your taste.", "You can also adjust the consistency of the Taushem Tondak by adding a little water to form a gravy.", "Bring the mixture to a brisk boil and simmer for about 5 minutes.", "Once done, turn off the heat and transfer to a serving bowl and serve warm.Serve the\u00a0Black Chickpeas And Cucumber Masala (Taushem Tondak) along with steamed rice for a wholesome lunch or weeknight dinner."]'::jsonb, 45, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Black_Chickpeas_And_Cucumber_Masala__Taushem_Tondak.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/192.Black_Chickpeas_And_Cucumber_Masala__Taushem_Tondak.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Savory Shrimps On Skillet Recipe', 'savory-shrimps-on-skillet-recipe', 'Savory Shrimps on skillet is a recipe where shrimps are shallow fried on a skillet using butter. This can be served as a party appetizers or whenever you are expecting some guests. They are easy to make and gets ready in no time. You can also serve it as a side dish along with your meal.', '["400 grams Shrimps , big one", "1 Tablespoon Butter (Salted) , or oil", "Orange color , optional", "1 teaspoon Soy sauce", "1 teaspoon Lemon juice", "2 tablespoons Honey", "1 tablespoon Tabasco Original - Hot Sauce", "1 teaspoon Black pepper powder", "1 teaspoon Garlic , minced or grated", "1/2 teaspoon Ginger , minced or grated", "Fresh Thyme leaves , or dry"]'::jsonb, ARRAY['ginger', 'tabasco original sauce', 'soy sauce', 'butter oil', 'lemon', 'garlic', 'black pepper powder', 'shrimps', 'orange color', 'tme leaves dry']::text[], '["To begin making the Savory Shrimps On Skillet recipe, Devein and de shell the shrimps.", "Keep the tail on if you want.In a small bowl, mix together ingredients mentioned for sauce.", "Add shrimps into the sauce and mix well and marinate for 20 minutes.Add 3-4 drops of orange food color into the marinated shrimps and mix well. (you can skip this step too)Next, heat a skillet.", "Add 1/2 tablespoon butter and once the butter is melted, remove the shrimps out from the marination sauce and place on top.", "Don''t overcrowd.Fry in two batches if there isn''t any room.", "Reserve the remaining sauce for later use.", "Fry on medium heat for about 2 minutes on one side and then flip them all.Fry on the other side similarly.", "Once they look all browned and fried nicely, remove them out on a plate and repeat for the next batch.Switch off the stove.Now, mix all the fried shrimps together in a same skillet and drizzle the reserved sauce over them.Mix well and serve.", "Serve\u00a0Savory Shrimps on skillet along with other starters such as\u00a0Egg Shoap\u00a0and\u00a0Mushrooms On Toast\u00a0to your guests."]'::jsonb, 28, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/Savory_Shrimps_On_Skillet.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/193.Savory_Shrimps_On_Skillet.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kondakadalai Vazhathandu Puli Thengai Kuzhambu Recipe (Banana Stem Curry with Black Chickpeas Recipe)', 'kondakadalai-vazhathandu-puli-thengai-kuzhambu-recipe-banana-stem-curry-with-black-chickpeas-recipe', 'Kondakadalai Vazhathandu Puli Thengai Kuzhambu Recipe (Banana Stem Curry with Black Chickpeas Recipe) is a healthy, whole hearted Tamil Nadu style curry made with ground coconut and other spices and tossed in a tangy gravy.', '["1 cup Kala Chana (Brown Chickpeas) , soaked in water overnight", "250 grams Banana Stem , skin peeled and cut into small pieces", "Salt , to taste", "1 teaspoon Turmeric powder (Haldi)", "To be ground to paste", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "2 teaspoon White Urad Dal (Split)", "3 Dry Red Chilli", "1 tablespoon Coriander (Dhania) Seeds", "1/2 cup Fresh coconut , grated", "1 cup Tamarind Water", "Seasoning", "1/2 teaspoon Sesame (Gingelly) Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 sprig Curry leaves , roughly torn"]'::jsonb, ARRAY['kala chana', 'brown chickpeas', 's banana stem', 'salt', 'turmeric powder', 'haldi', 'to be ground to paste', 'methi seeds', 'fenugreek seeds', 'white urad dal', 'split', 'dry red chilli', 'coriander', 'dhania', 'fresh coconut', 'tamarind water', 'seasoning', 'sesame', 'gingelly', 'mustard seeds', 'rai/ kadugu', 'curry leaves']::text[], '["We begin making the Kondakadalai Vazhathandu Puli Thengai Kuzhambu Recipe (Banana Stem Curry with Black Chickpeas Recipe) by pressure cooking the Kala channa with some water first in the pressure cooker for 4 whistle.", "Release the pressure naturally.Then empty the black chickpea into a bowl, then in the same pressure cooker, add the banana stem with little water, salt and cook it for 1 whistle and rest.Heat a heavy bottomed pan, add oil and crackle mustard seeds and curry leaves.", "Then add the ground paste and saut\u00e9 for few minutes, you can add little water.Finally add the cooked banana stem and chickpeas, season it well and add some water to make it little gravish.", "Serve the Kondakadalai Vazhathandu Puli Thengai Kuzhambu Recipe (Banana Stem Curry with Black Chickpeas Recipe) along with steam rice or\u00a0Hot Phulka\u00a0to enjoy your dinner meal."]'::jsonb, 30, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Kondakadalai_Vazhathandu_Puli_Thengai_Kuzhambu_Recipe_Banana_Stem_Curry_with_Black_Chickpeas_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/194.Kondakadalai_Vazhathandu_Puli_Thengai_Kuzhambu_Recipe_Banana_Stem_Curry_with_Black_Chickpeas_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Potol Posto Recipe (Aloo Parwal in Poppy Seed Masala Recipe)', 'aloo-potol-posto-recipe-aloo-parwal-in-poppy-seed-masala-recipe', 'Aloo Potol Posto Recipe (Aloo Parwal in Poppy Seed Masala Recipe) is a typical Bengali vegetarian dish made with "Potol"  also called as "Parwal" (Indian Gherkin) combined with potato. The masala is separately roasted and ground to give it an extra depth to the whole dish.', '["15 Pointed gourd (Parval) , cut into wedges", "3 to 4 Potatoes (Aloo) , skin peeled,cut into wedges and cut into wedges", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1/2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Fennel seeds (Saunf)", "3 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 Dry Red Chilli", "1/2 inch Ginger , finely chopped", "1/2 cup Fresh coconut , grated", "2 tablespoon Poppy seeds", "1 teaspoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "2 Green Chillies , finely chopped", "1 teaspoon Sugar", "Salt , to taste", "Mustard oil , as required for cooking"]'::jsonb, ARRAY['pointed gourd', 'parval', 'to 4 potatoes', 'aloo', 'methi seeds', 'fenugreek seeds', 'cumin seeds', 'jeera', 'fennel seeds', 'saunf', 'laung', 'cinnamon stick', 'dalchini', 'dry red chilli', 'ginger', 'fresh coconut', 'poppy seeds', 'red chilli powder', 'turmeric powder', 'haldi', 'reen chillies', 'sugar', 'salt', 'mustard oil']::text[], '["We begin making\u00a0Aloo Potol Posto Recipe (Aloo Parwal in Poppy Seed Masala Recipe) heat the pan with oil and roast by adding methi,cumin, fennel,cloves,cardamom, dry red chilli along with ginger, grated coconut and poppy seeds.", "Fry till the aroma comes out.Cool and transfer it into a blender.", "Blend it to a fine paste and keep it aside.Heat oil in a kadai and saute the parawal with turmeric powder till it turns brown and softens.Remove and keep it aside.", "Keep the potatoes boiled and ready as well.", "With the leftover oil temper green chilies and add the (coconut-poppy seed) masala paste.", "Sprinkle the spice powders and fry till the oil comes out from the masala.Finally add the vegetables.", "Add water and cook it for some more time for about 10 minutes .Serve your delicious and spicy\u00a0Aloo Potol Posto (Aloo Parwal in Poppy Seed Masala) with layered Lachaa Paratha."]'::jsonb, 60, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/sept-26/Bengali_Aloo_Potol_Posto_Recipe_Aloo_Parwal_In_Poppy_Seed_Masala-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/195.Bengali_Aloo_Potol_Posto_Recipe_Aloo_Parwal_In_Poppy_Seed_Masala-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Cauliflower In Coconut Milk Curry Recipe', 'cauliflower-in-coconut-milk-curry-recipe', 'The Cauliflower In Coconut Milk Curry is a perfect blend of pan roasted cauliflowers and bell peppers that are simmered in a delicate coconut milk curry flavored with coriander powder, curry leaves, chillies, cloves and cinnamon.', '["1 Cauliflower (gobi) , cut into florets", "1 Green Bell Pepper (Capsicum) , deseeded and cubed", "1 tablespoons Gram flour (besan)", "1 teaspoon Coriander Powder (Dhania) , freshly made with roasted coriander seeds", "1 cup Curd (Dahi / Yogurt)", "200 ml Coconut milk", "1/2 teaspoon Cumin seeds (Jeera)", "2 sprig Curry leaves", "3 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 inch Ginger", "Red Chilli powder , to taste", "Salt , to taste", "Oil , for cooking"]'::jsonb, ARRAY['cauliflower', 'gobi', 'reen bell pepper', 'capsicum', 's gram flour', 'besan', 'coriander powder', 'dhania', 'curd', 'dahi / yogurt', 'coconut milk', 'cumin seeds', 'jeera', 'curry leaves', 'laung', 'cinnamon stick', 'dalchini', 'ginger', 'red chilli powder', 'salt', 'oil']::text[], '["To begin making the Cauliflower In Coconut Milk Curry Recipe, in a large bowl whisk together, the yogurt, gram flour, coconut milk, ginger, coriander powder, salt and red chilli powder.", "Add in two cups of water, whisk it well and keep aside.Heat oil in a casserole pan; add the cumin, curry leaves, cloves, and cinnamon along with the bell peppers and cauliflower.", "Sprinkle some salt and water, cover the pan and roast the cauliflower on medium heat until lightly tender and cooked.", "Once tender and cooked, add in the coconut milk curry mixture and stir well.", "Keep stirring continuously with heat on medium high until the mixture thickens and begins to boil.If the mixture is too thick for your taste, adjust the consistency by adding a little water and boil just for a couple of minutes.", "Check the salt and spice levels and adjust to suit your taste.Serve the Cauliflower In Coconut Milk Curry for winters or parties along with steamed Foxtail Millet or Pearl Millets or Rice."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Cauliflower_In_Coconut_Milk_Curry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/196.Cauliflower_In_Coconut_Milk_Curry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sorekai Majjige Huli Recipe (Bottle Gourd In Coconut Yogurt Curry Recipe)', 'sorekai-majjige-huli-recipe-bottle-gourd-in-coconut-yogurt-curry-recipe', 'Sorekai Majjige Huli Recipe (Bottle Gourd In Coconut Yogurt Curry Recipe) is a traditional curry originated from Mysore which comes under Karnataka. The curry is a buttermilk based curry which is made by mixing in the pressure cooked bottle gourd which is then simmered with spicy coconut paste. There is a different style of the yogurt based bottle gourd curry made in the region of Mangalore or Udupi, the spices added to it differs which makes it less spicy.', '["1 Bottle gourd (lauki) , peeled and diced", "Salt , to taste", "1/2 teaspoon Turmeric powder (Haldi)", "1 cup Curd (Dahi / Yogurt)", "Salt , to taste", "To Be Groud To Paste", "1/4 cup Fresh coconut , grated", "1 tablespoon Chana dal (Bengal Gram Dal) , soaked in hot water for 10 minutes", "2 Green Chillies", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Asafoetida (hing)", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves , roughly torn", "2 Dry Red Chillies"]'::jsonb, ARRAY['salt', 'green chillies', 'coconut', 'asafoetida (hing)', 'mustard seeds', 'curd', 'curry leaves', 'dry red chillies', 'bottle gourd (lauki)', 'cumin seeds (jeera)', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["We begin making the Sorekai Majjige Huli Recipe (Bottle Gourd In Coconut Yogurt Curry Recipe) by pressure cooking the bottle gourd with 1/2 cup of water in a pressure cooker, you can also add a teaspoon of salt.", "Pressure cook for 1 whistle and set it aside to release the pressure naturally.Next step is to make the paste, In a blender add in all the ingredients and grind into a smooth paste, you can add water slowly while it is blending.In a sauce pan, add the bottle gourd and the ground paste and mix it evenly, let it cook for 2 minutes.", "Then reduce the heat to minimum.In a mixing bowl add the curd and add one cup water and beat it till it is smooth and turn into a buttermilk.", "Slowly add the buttermilk into the bottle gourd mixture and stir continuously.", "Check for seasonings.In a small-bottomed pan, heat oil and temper the mustard seeds, curry leaves and some torn dry red chilies.", "Pour in the Kadai onto the yogurt based curry.Serve the Sorekai Majjige Huli Recipe (Bottle Gourd In Coconut Yogurt Curry Recipe) with hot steamed rice and Elai Vadam Recipe (A Traditional South Indian Rice Papad)."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/oct-24/Sorakkai_Majjige_Huli_Bottle_Gourd_In_Coconut_Yogurt_Curry-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/197.Sorakkai_Majjige_Huli_Bottle_Gourd_In_Coconut_Yogurt_Curry-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Coimbatore Style Drumstick Sambar Recipe', 'coimbatore-style-drumstick-sambar-recipe', 'Coimbatore Style Sambar Recipe is a traditional recipe that is famous from Coimbatore, Tamil Nadu. This recipe has a strong flavour from spices like cumin seeds, fennel seeds, asafoetida, coriander and is laced with the texture of coconut with dal.', '["1 Onion , chopped", "1 Drumstick , chopped to 2 inch long", "1 Tomato", "1 cup Arhar dal (Split Toor Dal) , soaked for 10 minutes and cooked", "2 sprig Curry leaves", "1 tablespoon Coriander (Dhania) Seeds", "1/2 tablespoon Cumin seeds (Jeera)", "1/4 tablespoon Methi Seeds (Fenugreek Seeds)", "Salt , to taste", "1 tablespoon Tamarind Paste", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "4 Dry Red Chillies , soaked", "1/4 cup Fresh coconut , grated", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "Gingelly oil , for tadka", "2 teaspoons Ghee"]'::jsonb, ARRAY['tomato', 'salt', 'arhar dal (split toor dal)', 'coconut', 'mustard seeds', 'ghee', 'red chilli powder', 'drumstick', 'gingelly oil tadka', 'curry leaves', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'tamarind paste', 'dry red chillies', 'turmeric powder']::text[], '["To begin making the Coimbatore Style Sambar Recipe, prep all the ingredients first.", "Soak the arhar dal in required water for about 15 to 20 minutes.Once the lentils are soaked, drain the water, add the dal in a pressure with 2 cups water and pressure cook for about 4 whistle.", "Let the pressure release naturally.", "In a saucepan, add drumstick, onions, tomatoes with sufficient water on high heat for about 10 minutes or till cooked.", "Keep it aside.", "You can use a bit of vegetable stock for grinding masalas for the sambar.Heat a heavy bottomed pan with gingelly oil.", "Once the oil is hot, add cumin seeds, coriander seeds, fenugreek seeds, asafoetida, dry red chillies, coconut and roast for about a minute of till fragrant.", "Allow to cool to room temperature.", "You may spread this on a plate and leave on kitchen countertop for faster cooling.In a mixer grinder, grind the masalas with the help of a bit of water, or the stock of boiled veggies to a smooth paste.Add the ground masala back in the saucepan, add tamarind paste and start boiling the sambar with cooked dal, and about a glass more of water or to the required consistency.Add salt and stir well.While the sambar comes to boil, in the kadai, heat a bit of gingelly oil.", "Once it is hot, on medium heat add the mustard seeds and allow them to splutter.", "Add curry leaves and saute for a few seconds, on low heat.Once the sambar is boiled well for about 5-7 minutes, switch off heat, add the gingelly oil tadka, top it with some ghee and give it a stir.", "The Coimbatore sambar is ready to serve.Serve\u00a0Coimbatore Style Sambar Recipe with\u00a0Steamed Rice Recipe\u00a0and\u00a0Capsicum Usili Recipe\u00a0for a complete weekday meal."]'::jsonb, 45, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/suhagi2002-gmail.com/coimabtore_style_sambar_recipe_edited.JPG', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/198.coimabtore_style_sambar_recipe_edited.JPG', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sautéed Aubergine With Tamarind Recipe', 'saut-ed-aubergine-with-tamarind-recipe', 'Sautéed Aubergine With Tamarind Recipe is a perfect dish for dinners or lunches. Makes an elegant dish for the lent season as well. The flavor comes from the tangy tamarind juice or paste which leaves your taste buds tingling and wanting more. Sautéed Aubergine With Tamarind Recipe is a super simple and abundantly flavorful dish that is perfect as a side for rotis/chapathis or plain rice.', '["6 Small Green brinjal (green aubergine) , cut to bite size", "2 Onion , finely chopped", "2 Tomatoes , diced", "2 teaspoons Tamarind Paste , (adjust)", "1 to 2 teaspoon Red Chilli powder , (adjust)", "1/2 teaspoon Turmeric powder (Haldi)", "Coriander (Dhania) Leaves , a bunch, finely chopped", "1/2 teaspoon Jaggery , grated", "Salt , salt - to taste", "Oil , to cook"]'::jsonb, ARRAY['small green brinjal', 'green aubergine', 'onion', 'tomatoes', 's tamarind paste', 'to 2 teaspoon red chilli powder', 'turmeric powder', 'haldi', 'coriander', 'dhania', 'jaggery', 'salt', 'oil']::text[], '["To prepare Saut\u00e9ed Aubergine With Tamarind Recipe, slice each aubergine into 4 and then dice it into medium sized chunks.", "Keep aside.", "Once tamarind has soaked for a few hours in water, pulp out the extract, strain from its residues and keep aside.Heat oil in a pan and shallow fry the diced aubergines for a few minutes.", "Saute till the aubergines wilt a little or is soft and cooked till aldente.", "Once done, remove from pan and keep aside.Into the same pan, add some more oil and add finely sliced onions and saute until it turns translucent.", "Into this add the shallow fried aubergine pieces and combine well.Now add the diced tomatoes along with salt and mix well.", "Add a little water into the pan and cover and cook till tomato turns soft. (approx. 5 minutes)Now add in the chilli and turmeric powders and toss well.", "Add just a little more water and continue to cover and cook on low heat till the aubergine is cooked through.Once the aubergine is cooked well, remove the lid and add the tamarind juice or paste into it and combine well. (add tamarind paste/juice little by little and check for sourness to get the right balance of flavours)Cook without lid till the gravy has reduced and has a semi-thick consistency.", "Add powdered jaggery at this time and mix well.", "Garnish Saut\u00e9ed Aubergine With Tamarind Recipe with chopped coriander leaves and serve with rotis/chapathis\u00a0or plain rice."]'::jsonb, 80, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Donna_George/aubergine_in_tamarind_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/199.aubergine_in_tamarind_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Grated Beetroot Chilli Paratha Recipe', 'grated-beetroot-chilli-paratha-recipe', 'Grated Beetroot Chilli Paratha Recipe is quite healthy and can be a great addition to your breakfast ideas. This recipe is very simple and you can make this in no time. The lush red color is also eye pleasing and looks great in lunch boxes. This tasty and easy paratha recipe made from Beetroot is healthy owing to its high fiber, vitamins, minerals, and antioxidants. It is a kid friendly recipe and a kids lunch box option due to its rich color and grated beets which won’t be felt in chunks while chewing. Serve these Grated Beetroot Chilli Parathas Burani Raita or Mooli Raita or with homemade ghee.', '["1 Beetroot , grated", "2 cups Whole Wheat Flour", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Red Chilli powder", "3 Green Chillies", "1 teaspoon Ghee", "Salt , to taste", "Water , as needed"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'wheat flour', 'ghee', 'red chilli powder', 'water', 'beetroot', 'green chillies']::text[], '["To prepare Grated Beetroot Chilli Paratha Recipe, wash and peel the beetroot skin.", "Grate the vegetable finely.Take a mixing bowl and add the grated beetroot.", "Add cumin powder, salt, red chilli powder, and ghee.", "Mix all the ingredients except wheat flour.Add whole wheat flour into another mixing bowl and knead it to a smooth dough with enough water.Take a small portion of the wheat flour dough and flatten it using a rolling pin into a small circle big enough to hold the filling.Place 1-2 tablespoon of filling in the center.", "Bring the edges together with fingers and remove any excess dough after joining the ends.Using some dry flour to help it not be sticky to the rolling pin, roll the dough stuffed with filling using a rolling pin to get uniform & slightly thick paratha.Heat the Tawa to medium heat & add the paratha on the hot tawa.Roast it for about a minute & then flip and cook on the other side for a minute or till done.Apply butter or oil as needed to grease it while cooking.Grated Beetroot Chilli Paratha Recipe can be served with Burani Raita or Mooli Raita or with homemade ghee."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shobana_Vijay/grated-beetroot-chilli-paratha-recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/200.grated-beetroot-chilli-paratha-recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false);

INSERT INTO public.recipes (
  title, slug, description, ingredients, cleaned_ingredients,
  instructions, total_time_mins, cuisine, diet, source_url,
  image_url, image_status, image_source, data_source, servings, review_count, is_featured
) VALUES
  ('Doli Ki Roti Recipe | Classic Sourdough Bread Recipe from Multan', 'doli-ki-roti-recipe-classic-sourdough-bread-recipe-from-multan', 'Doli Ki Roti Recipe is a whole wheat fermented bread, activated with an age old and traditional recipe of homemade yeast. The ingredients which make the yeast, give a subtle but delectable flavor to the bread and take the taste of the bread to just another level.', '["12 Brown cardamom (Badi Elaichi)", "1/2 cup Fennel seeds (Saunf)", "1/2 cup Chana dal (Bengal Gram Dal)", "1/2 cup Poppy seeds", "1/2 cup Sugar", "500 ml Water", "3 teaspoons Whole Wheat Flour", "4 cups Whole Wheat Flour", "2 teaspoons Sugar", "1 teaspoon Salt", "Lukewarm Water , to knead", "Oil , to deep fry", "2 cups Chana dal (Bengal Gram Dal)", "Salt , to taste", "1 teaspoon Red Chilli powder , (adjust)", "2 teaspoons Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "1/4 teaspoon Turmeric powder (Haldi)", "2 inch Ginger , crushed", "1/4 cup Onion , finely chopped", "Water , as needed"]'::jsonb, ARRAY['salt', 'wheat flour', 'water knead', 'ginger', 'fennel seeds (saunf)', 'red chilli powder', 'water', 'sugar', 'poppy seeds', 'onion', 'brown cardamom (badi elaichi)', 'coriander powder', 'turmeric powder', 'chana dal (bengal gram dal)', 'garam masala powder', 'sunflower oil']::text[], '["To prepare\u00a0Doli Ki Roti Recipe, get prepped with all the ingredients required and prepare the homemade yeast water first.In a saucepan, add water (500 ml) and bring it to boil.", "Put all the ingredients listed in \"Yeast Water\", including cardamom, fennel seeds, chana dal, khus khus (or poppy seeds) and sugar.Cover and boil for 2 minutes until sugar dissolves and the chana dal softens a bit.", "Let it remain covered.", "Wrap this saucepan in a dry and warm cloth and keep in the warmest corner of your kitchen.", "Let it stay undisturbed for 24 hours exactly.To prepare yeast, take the frothy water after 24 hours (only if it is frothy, or you need to repeat the procedure) to prepare homemade yeast.", "Pass the water through a sieve and mix it with whole wheat flour (3 tablespoons).The batter should resemble a pancake batter, flowy.", "Cover it again with lid and wrap with a warm cloth and keep in a warm place for 3 more hours.After 3 hours exactly, the mixture should all be bubbly and frothy.", "Now you may proceed with making the dough.Take half of the homemade yeast mixture and add the ingredients under \"to make roti\" (flour, sugar, salt, water) and knead to make a smooth pliable dough.", "Use only warm water to knead the dough.", "Keep it covered like before, for 3 hours or just half hour more, to rise."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Recipesandyou/Doli_Ki_Roti_recipe_edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/201.Doli_Ki_Roti_recipe_edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengaluru Style Brinjal Gravy Recipe - For Biryani', 'bengaluru-style-brinjal-gravy-recipe-for-biryani', 'Brinjal Gravy For Biryani, as the name suggests is a side dish recipe that makes a delicious accompaniment for any Biryani. This style of side dish is prepared in Bangalore restaurants or at Weddings and served along with spicy biryanis. The tanginess and sweetness of the dish pairs well with any spicy Biryanis or Pulaos.', '["1 Brinjal (Baingan / Eggplant) , cut into big pieces", "4 Tomatoes", "2 Onions , roughly chopped", "1 tablespoon Ginger Garlic Paste", "20 grams Tamarind , soaked in hot water", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 tablespoon Whole Black Peppercorns", "1/2 tablespoon Jaggery , powdered", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Red Chilli powder", "2 teaspoons Oil", "Salt , as per your taste", "Coriander (Dhania) Leaves , for garnish"]'::jsonb, ARRAY['tomato', 'salt', 'mustard seeds', 'brinjal (baingan eggsplant)', 'coriander (dhania) leaves', 'jaggery', 'red chilli powder', 'black peppercorns', 'ginger garlic paste', 'onion', 'tamarind', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the\u00a0Brinjal Gravy For Biryani, first soak a lemon sized or 20 grams tamarind in hot water for 20 minutes.After 20 minutes extract the pulp of tamarind and keep aside.", "You will need 1/4 cup of tamarind pulp for this recipe.", "Add roughly chopped onions in a mixer and make an onion paste.", "Remove and keep it aside.", "In the same mixer, add the tomatoes and puree them.", "Keep aside.In a heavy bottomed pan,\u00a0add 1 teaspoon of cooking oil.", "Let it warm up.Once the oil is hot, add the chopped brinjal till the skin becomes slightly brown.", "Once they are browned, remove from the pan and keep it aside. (Browning indicates that it has cooked halfway)In the same pan, add one more teaspoon of oil and add mustard seeds and peppercorns and wait for them to splutter.", "Keep it on a low flame as the peppercorns might sputter everywhere the moment it touches heat.", "Next, add in the ground onion paste, ginger garlic paste and saute for a few minutes until the raw smell of onion, ginger and garlic go away.", "Next, add the tomato puree, tamarind extract and salt according to your taste.", "Cover the pan and cook on a low flame for about 15 minutes.", "Open the pan occasionally and stir so that the gravy does not stick to the bottom of the pan.", "After 15 minutes, add the powdered jaggery\u00a0in to the tamarind gravy and give it a good mix.", "Finally add the half cooked brinjals, 1/2 cup of water and cook till the brinjals are soft.", "Turn off the flame and garnish with coriander leaves.Serve\u00a0Brinjal Gravy For Biryani\u00a0with Hyderabadi Vegetable Biryani Recipe or Ambur Style Chicken BIryani along with a Tadka Raita for a delicious Sunday Lunch."]'::jsonb, 90, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/monisha.nair1-gmail.com/Brinjal_gravy_for_biryani_Bengaluru_style_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/202.Brinjal_gravy_for_biryani_Bengaluru_style_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Halli Style Mutton Saaru Recipe - South Indian Mutton Curry', 'halli-style-mutton-saaru-recipe-south-indian-mutton-curry', 'A classic South Indian Gowdru style curry, Halli Style Mutton Saru is a delightful South Indian curry/gravy with flavour notes from the curry leaves and coconut.', '["1/2 kg Mutton , cut into small pieces", "2 Onions , sliced", "2 tablespoons Oil", "2 sprig Curry leaves", "Ground paste for masala", "3 tablespoons Fresh coconut , grated", "4 Tomatoes , chopped", "1/2 cup Coriander (Dhania) Leaves", "3 Green Chillies", "3 Dry Red Chillies", "1 inch Ginger", "8 cloves Garlic", "2 teaspoons Poppy seeds", "1 tablespoon Roasted Gram Dal (Pottukadalai)", "1 tablespoon Sambar Powder", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'sambar powder', 'coconut', 'coriander (dhania) leaves', 'gram dal (pottukadalai)', 'cloves garlic', 'curry leaves', 'dry red chillies', 'onion', 'mutton', 'poppy seeds', 'green chillies', 'sunflower oil']::text[], '["To begin making the Halli Style Mutton Saru Recipe, thoroughly wash and clean the mutton pieces.In a mixer-jar combine coconut, tomatoes, coriander leaves, green chilies, red chillies, ginger, garlic, poppy seeds, roasted gram, dal salt and sambar powder.Grind this masala into a paste with some water.", "Transfer to a bowl and set aside.In a pressure cooker, heat oil on medium flame, add curry leaves and allow it to crackle, then add the sliced onions and fry till it turns brown in colour.Add the ground masala, and cook till the oil comes to the surface, now add the mutton piecesAnd mix well, add 1 \u00bd cups of water and close the pressure cooker.", "Pressure cook for 4-5 whistles and turn off the flame.", "Allow the pressure to release naturally.Serve\u00a0Halli Style Mutton Saru along with\u00a0Soft & Delicious Ragi Mudde Recipe - Karnataka Style Ragi Balls\u00a0or\u00a0Steamed Rice Recipe (Pressure Cooker & Sauce Pan Methods)\u00a0or\u00a0Homemade Crisp Ghee Roast Dosa Recipe\u00a0for a complete meal."]'::jsonb, 40, 'Karnataka', 'non-veg', 'https://www.archanaskitchen.com/images/Karnataka_Style_Mutton_Saaru_Recipe_Curry-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/203.Karnataka_Style_Mutton_Saaru_Recipe_Curry-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karwar Style Karatya Kismore Recipe - Sweet Tangy Bitter Gourd Sabzi', 'karwar-style-karatya-kismore-recipe-sweet-tangy-bitter-gourd-sabzi', 'Karwar Style Karatya Kismore Recipe - Sweet and Tangy Bitter Gourd Sabzi is made from a crunchy sliced bitter gourd, tossed with a tangy and sweet sauce that forms the authentic flavors of Karwar Cuisines.', '["2 Karela (Bitter Gourd/ Pavakkai) , sliced thinly", "1 Onion , finely chopped", "1/2 cup Fresh coconut , grated", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Tamarind Water", "1 teaspoon Jaggery , powdered", "1-1/2 teaspoons Ghee", "Salt , to taste"]'::jsonb, ARRAY['salt', 'tamarind water', 'coconut', 'karela (bitter gourd pavakkai)', 'ghee', 'jaggery', 'red chilli powder', 'onion']::text[], '["To begin making the\u00a0Karwar Style Karatya Kismore Recipe - Sweet and Tangy Bitter Gourd Sabzi by heating a flat skillet with oil, saute the bitter gourd till its brown and crispy.Next, soak the tamarind rind with 1 cup of hot water and squeeze in all the pulp and take out the residue.Blend the coconut, red chili powder to a coarse paste, add this into the crispy bitter gourd along with the tamarind pulp.", "Stir till it thickens.", "Season it with salt and add jaggery and stir well till it combines.Serve the Karwar Style Karatya Kismore Recipe - Sweet and Tangy Bitter Gourd Sabzi along with\u00a0Phulka\u00a0and\u00a0Peerkangai Pal Kuzhambu Recipe (Ridge Gourd in Milk Curry)\u00a0for an everyday meal."]'::jsonb, 40, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Karatya_Kismore_Recipe_Sweet_and_Tangy_Bitter_guard_Salad_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/204.Karatya_Kismore_Recipe_Sweet_and_Tangy_Bitter_guard_Salad_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maa Ki Dal Recipe - Punjabi Style Black Urad Dal Recipe', 'maa-ki-dal-recipe-punjabi-style-black-urad-dal-recipe', 'Maa Ki Dal Recipe which is a Punjabi style slow cooked Black Urad dal is similar to Dal Makhani in many ways, as it uses the same lentils — whole urad dal with skins and some rajma .', '["1 cup Black Urad Dal (Split)", "1 tablespoon Rajma (Large Kidney Beans)", "4 Tomatoes", "1 inch Ginger", "1 tablespoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Kashmiri dry red chillies", "1 tablespoon Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder"]'::jsonb, ARRAY['tomato', 'ginger', 'ghee', 'kashmiri dry red chillies', 'black urad dal (split)', 'cumin seeds (jeera)', 'rajma (large kidney beans)', 'coriander powder', 'garam masala powder']::text[], '["To begin making Maa Ki Dal Recipe, first wash the dal and rajma well about 2-3 times and then soak them together in water for at least 8 hours or overnight.The longer you soak the better it is for the texture of the dal.", "Traditionally, the dals are soaked for 24 hours, changing water every 8 hours.When you are ready to prepare the dal, after sufficient soaking time, take a heavy bottom pan (or a slow cooker) and bring 5 cups of water with a dash of salt, to boil in it.Add the pre soaked dal and rajma to it and let it simmer till it cooks and turns a little soft.", "This could take anywhere between 2-3 hours as the dal gets it flavours from the slow cooking process.", "However, if you are in a hurry you can use the pressure cooker to hasten the process.Next, add the tomato and ginger to the dal.", "Once the dal is cooked, mash the dal and tomatoes a little bit.", "Take care not to make it mushy, but just achieve a thick consistency.", "Cook the dal for more 3 to 4 minutes.In a small pan, warm some ghee, add the cumin seeds and saut\u00e9 till they turn slightly brown.", "Add dry red chillies, coriander powder, garam masala powder and roast on a low heat for 1 minute taking care not to burn them.Pour this tempering over the the dal and bring it to a boil.", "Simmer it for another 10-15 minutes and serve hot.Maa Ki Dal\u00a0can be served with\u00a0Baingan Ka Bharta,\u00a0Boondi Raita\u00a0and\u00a0Phulka\u00a0for a comforting Punjabi meal."]'::jsonb, 160, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Monika_Manchanda/Maa_Ki_Daal_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/205.Maa_Ki_Daal_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sweet Potato Thepla/Paratha Recipe', 'sweet-potato-thepla-paratha-recipe', 'Sweet Potato Paratha Recipe is simple quick to make and delicious to eat. These sweet potato thepla''s or parathas or flat bread, as you wish to call them, are made from sweet potatoes, combined with cumin, coriander leaves and whole wheat flour, makes a healthy kids lunch box or a breakfast.', '["1 cup Whole Wheat Flour", "1 cup Sweet Potato , pressure cooked till firm and mashed", "Salt , to taste", "Spinach Leaves (Palak) , or Coriander leaves, a bunch", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Turmeric powder (Haldi)", "Oil , or ghee to smear as needed"]'::jsonb, ARRAY['whole wheat flour', 'sweet potato', 'salt', 'spinach leaves', 'palak', 'cumin powder', 'jeera', 'turmeric powder', 'haldi', 'oil']::text[], '["To begin making the Sweet Potato Thepla''s, combine all the ingredients including whole wheat flour, sweet potato, salt, spinach leaves, cumin powder, turmeric powder into a large bowl and knead to make firm dough.", "Add little water if required to make the dough smooth, and lastly, add 1 teaspoon of oil over the dough to prevent it from making it sticky.Make lemon sized balls and roll them out thin to approximately 6 inches in diameter, as thin as you can roll them, taking care that the parathas does not tear apart.Note: Tossing the dough in dry flour while rolling will prevent it from getting sticky when rolling them out.Preheat a skillet on\u00a0a medium heat.", "Place the rolled out parathas on the preheated skillet.", "Cook for about 1/2 a minute, flip over and add 1 teaspoon of ghee in and around the paratha.", "Lightly press the parathas while on the skillet so the dough gets cooked.Flip and cook the other side for about 1/2 a minute.", "Cook until light golden spots appear on the both sides of the parathas.Serve\u00a0Sweet Potato Thepla/Paratha Recipe\u00a0along with\u00a0Aam Chunda Pickle Recipe\u00a0and a cup of\u00a0Masala Chai\u00a0for breakfast."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breads/Gujarati_Sweet_Potato_Thepla_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/206.Gujarati_Sweet_Potato_Thepla_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maavina Hannina Gojju (Karnataka Style Ripe Mango Curry Recipe)', 'maavina-hannina-gojju-karnataka-style-ripe-mango-curry-recipe', 'Mavina Hannina Gojju is a Karnataka Style Curry Recipe which is prepared from ripe mangoes. This curry is a cascade of spicy, tangy and sweetish taste. It requires fewer ingredients to make this finger licking Mangalore special maavina hannina gojju. The dish is traditionally made from fibrous mango variety (wild mangoes or kaadu maavu) which are sour and sweet and hence provide a unique flavor.', '["3-4 Mango (Ripe) , small and sour variety", "5 Green Chillies , crushed (adjust taste)", "Jaggery , lemon sized", "Salt , to taste", "Ingredients To Temper", "2 tablespoons Coconut Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Dry Red Chilli , broken", "1 pinch Asafoetida (hing) , large pinch", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'jaggery lemon', 'mustard seeds', 'mango (ripe)', 'dry red chilli', 'asafoetida (hing) large', 'curry leaves', 'coconut oil', 'green chillies']::text[], '["To make this Karnataka style ripe mango curry, wash the mangoes well under running water.", "Using a knife remove their tip and lightly make 2-3 vertical cuts on each mango.Take a\u00a0deep pan,\u00a0cook the mangoes using sufficient water, until they are soft and cooked thoroughly.", "When the color of the peel appears cooked, you know they are cooked.", "It might take 10 minutes on medium flame.", "Switch off.Drain water into a bowl and keep the whole mangoes in the pan.", "Once the mangoes cool, peel them.", "You\u2019ll be able to peel the mango easily using your fingers.Put the peels into the bowl with cooked water and extract any more remaining pulp.Discard peel and put the water back into the pan.Squeeze mango with hands (using a masher is difficult with fibrous pulp on the seed of mango).On a medium heat, add crushed green chili, salt and jaggery to the pan with mango pulp and kernel.", "Adjust taste and consistency by adding water if required.", "Switch off heat.In a tadka pan, heat a little coconut oil and splutter mustard seeds.", "Add hing, broken red chili and curry leaves.Pour the tadka on maavina hannina gojju and give it a quick stir.Close the lid of the pan and allow it to sit for 10 minutes.Relish this tangy-spicy-sweet Mavina Hannina Gojju (Karnataka Style Ripe Mango Curry Recipe) with cooked plain rice or Neer dosa\u00a0or Chapathi.", "Accompany the meal with Mustard Green Chilli Pickle and fritters like sabudana sandige or akki peni sandige."]'::jsonb, 45, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha_Kalluraya/RIPE_MANGO_CURRY__MAVINA_HANNINA_GOJJU_original.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/207.RIPE_MANGO_CURRY__MAVINA_HANNINA_GOJJU_original.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Creamy Dal Makhani Recipe', 'creamy-dal-makhani-recipe', 'Dal Makhani or Dal Makhni Dal Makhani is a popular North Indian dish (especially in delhi & punjab). The primary ingredients in dal makhani are whole black lentil with red kidney beans, cream and butter. In it whole black lentils and kidney beans are soaked in water overnight and then boiled and simmered in spices and cream. It has very rich and creamy texture because of lot of butter and cream.', '["1 cup Black Urad Dal (Whole)", "1/2 cup Rajma (Large Kidney Beans)", "3 tablespoons Fresh cream , full fat", "4 tablespoons Butter (Salted)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Cumin seeds (Jeera)", "4 cups Water", "1 Onion , finely chopped", "1/2 cup Homemade tomato puree", "1 teaspoon Ginger , grated", "1 teaspoon Garam masala powder", "1/8 teaspoon Asafoetida (hing)", "1 Black cardamom (Badi Elaichi)", "2 Cloves (Laung)", "2 Green Chillies , chopped", "1 teaspoon Coriander Powder (Dhania)", "Salt , as required"]'::jsonb, ARRAY['tomato', 'black cardamom (badi elaichi)', 'green chillies', 'ginger', 'salt', 'full fat', 'asafoetida (hing)', 'red chilli powder', 'water', 'onion', 'cumin seeds (jeera)', 'rajma (large kidney beans)', 'turmeric powder', 'coriander powder', 'black urad dal', 'cloves (laung)', 'butter', 'garam masala powder']::text[], '["To begin making the Creamy Dal Makhani recipe, wash and soak black lentil and kidney beans together in enough water for at least 8 hours or for overnight.Drain the water and wash thoroughly at least for 5 to 6 times.The best way to make sure that it is purely washed, is that you can see clear water after washing them.In a pressure cooker, add lentil, kidney beans, asafoetida , turmeric, salt, water, black cardamom and cloves and pressure cook for 2 to 3 whistle on high flame then lower the heat and let it cook for another 15 to 18 minutes.When the cooker cools down completely, open it and check the cooked lentils should be very soft to touch.You should be able to mash the both lentil and kidney beans with spoon if they are cooked completely.If they are not cooked thoroughly, then pressure cook for 2 whistle more and add warm water if required.Now heat a thick bottomed pan add 3 tablespoons butter in it.Add cumin seeds and fry them until you see them into golden brown colour.", "Once cumin seeds are golden brown, then add chopped onions.After 3 minutes or until onion turns in light golden colour add tomato puree, green chillies and grated ginger.After 1 minutes add chilli powder, coriander powder and (add spices to adjust your taste) cook till the oil starts separating from the mixture.Now add cooked lentils and simmer for 12 to 15 minutes.", "Add garam masala, cream and 1 tablespoon butter (if lentils will thicken after some time so make sure to add enough warm water for cooking).Cook for another 5 minutes.", "Now creamy Makhani daal is ready to serve.Garnish with fresh cream & butter and serve hot.", "Serve Creamy Dal Makhani with\u00a0Jeera Rice\u00a0and\u00a0Tawa Parathas\u00a0for a delicious meal."]'::jsonb, 65, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Roop/Dal_Makhani.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/208.Dal_Makhani.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mangalore Style Nurge Gashie Recipe-Spicy Drumstick Curry', 'mangalore-style-nurge-gashie-recipe-spicy-drumstick-curry', 'Mangalore Nurge Gashie is a spicy drumstick curry which is filled with coastal flavours. In this recipe, drumstick is cooked in thick tamarind gravy that is flavoured with coconut and whole spices. The coconut-tamarind spice paste gives a creamy texture and tangy taste to this dish. Weekend lunch can be made more exciting with the Nurge Gashie when served with steaming hot rice, rotis or parathas.', '["4 Drumstick , cut them into 1-1/2 inch pieces", "1 teaspoon Jaggery , powdered", "1 Onion , finely chopped", "Salt , to taste", "4 Fresh Red chillies , adjust according to taste", "3 tablespoons Coriander (Dhania) Seeds", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Black Urad Dal (Split)", "3/4 teaspoons Whole Black Peppercorns", "1 teaspoon Cumin seeds (Jeera)", "1 tablespoon Tamarind Paste", "4 Garlic", "1/4 teaspoon Turmeric powder (Haldi)", "1 tablespoon Fresh coconut , grated", "2 teaspoons Sesame (Gingelly) Oil", "2 tablespoons Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Black Urad Dal (Split)", "1 sprig Curry leaves", "Coriander (Dhania) Leaves , as required, finely chopped"]'::jsonb, ARRAY['salt', 'red chillies', 'coconut', 'mustard seeds', 'coriander (dhania) leaves', 'jaggery', 'sesame (gingelly) oil', 'black peppercorns', 'black urad dal (split)', 'curry leaves', 'coriander (dhania) seeds', 'onion', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'tamarind paste', 'garlic', 'turmeric powder', 'drumstick them', 'sunflower oil']::text[], '["To begin with Mangalore Nurge Gashie Recipe, pour 2 of cups water with salt in a deep pan and bring it to boil.", "Add the drumsticks and simmer it for 10 minutes till the drumsticks get tender.", "Set aside along with the water .Heat oil in a pan and dry fry the dry red chillies, coriander seeds, cumin, pepper, methi, urad dal, garlic and tamarind till the dal turns golden and chillies starts releasing its fragrance.Now put the fried spices in a mixer and grind them to a smooth consistency.", "Add 1/2 cup of water and grind it again.Now in a wide pan, heat oil and add all the ingredients given under the section \u2018tempering\u2019.", "By first adding mustard seeds into the pan.", "Once the mustard seeds splutter add cumin seeds, black urad dal and curry leaves and leave it to crackle for few seconds.", "Add the chopped onions and fry them till they change their colour to golden and becomes soft.Now add the boiled drumsticks along with the cooked water, spice paste, salt and jaggery in the pan.", "Let it simmer for 10 minutes on a low flame.Now switch off the heat and garnish your dish with chopped cilantros.Serve\u00a0Mangalore Nurge Gashie along with Steamed Rice as main course and\u00a0South Indian Kosambari Recipe With Raw Mango, Cucumber, Carrot And Beetroot\u00a0and\u00a0Malnad Special Appe Midi Uppinakayi\u00a0as accompanying condiments\u00a0for a lunch meal."]'::jsonb, 45, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Uma_Raghuraman/Mangalore_Nurge_Gashie__Spicy_Drumstick_Curry_from_Mangalore.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/209.Mangalore_Nurge_Gashie__Spicy_Drumstick_Curry_from_Mangalore.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Udupi Style Sambar Recipe - Masala Huli With Mixed Vegetables', 'udupi-style-sambar-recipe-masala-huli-with-mixed-vegetables', 'Sambar/Sambhar is a lentil based vegetable stew with a tamarind broth. It is popular in South Indian cuisine. It is a common dish served in the Udupi Style Restaurants along with Idli/Dosas.', '["1/2 cup Arhar dal (Split Toor Dal) , soaked for 90 minutes", "1/2 teaspoon Turmeric powder (Haldi)", "1 pinch Asafoetida (hing)", "3 tablespoons Fresh coconut , grated", "2 teaspoons Coriander (Dhania) Seeds", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Chana dal (Bengal Gram Dal)", "1 teaspoon White Urad Dal (Split)", "4 Byadagi Dried Chillies", "12 Curry leaves , or a few sprigs", "1 tablespoon Oil", "1 Onion , finely sliced", "1 Tomato , cubed", "2 Drumstick , first layer peeled and cut into 2 inch pieces", "100 grams Kaddu (Parangikai/ Pumpkin) , cubed", "1 tablespoon Tamarind Paste", "1 tablespoon Jaggery , or to taste", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder , (adjust)", "Salt , to taste", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1/2 teaspoon White Urad Dal (Split)", "2 Dry Red Chillies", "1 sprig Curry leaves", "2 pinch Asafoetida (hing)"]'::jsonb, ARRAY['tomato', 'parangikai pumpkin', 'asafoetida (hing)', 'jaggery', 'curry leaves', 'white urad dal (split)', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil', 'salt', 'arhar dal (split toor dal)', 'dry red chillies', 'drumstick first layer', 'tamarind paste', 'coconut', 'mustard seeds', 'red chilli powder', 'methi seeds (fenugreek seeds)', 'curry leaves', 'byadagi dried chillies']::text[], '["To begin making Udupi Style Sambar Recipe-Masala Huli With Mixed Vegetables, firstly soak the toor dal in sufficient water for about an hour and a half.At the time of cooking, wash the dal thoroughly and drain.", "Add dal, a pinch of asafoetida, turmeric powder and 1 1 1/2 cups water to the dal and pressure cook till done. (about 2 whistles will do), allow the pressure to release naturally.", "Heat about a teaspoon of oil in a heavy bottoemed pan and roast the ingredients given for the masala including coriander seeds, cumin seeds, fenugreek seeds, chana dal, white urad dal, bydagi red chillies, curry leaves except the coconut till they change little colour.", "This will take about a minute and keep it aside to cool.Grind them together with the coconut using sufficient water to get a smooth paste.Heat oil in a heavy bottomed pan and add mustard seeds, fenugreek seeds, urad dal, red chillies broken into pieces, asafoetida and curry leaves.", "Allow them to sizzle for few seconds.", "Add sliced onions and cook for a minute.", "Add the turmeric powder and saute.When onions turn translucent, add peeled drumsticks and add 1 cup water for them to cook by covering it with a lid for 15 minutes.", "Add the pumpkin pieces, red chilli powder and cook further 15 more minutes.", "When all vegetables are cooked, add the tomato cubes and cook for a while till tomatoes are cooked well.Meanwhile, mash the cooked dal in pressure cooker.", "Add tamarind paste, salt, jaggery and the ground masala to the cooked vegetables.", "Add the mashed dal and water if required to adjust the consistency.Mix well and bring\u00a0Masala Huli to a boil.", "Adjust salt and jaggery if needed.Reduce flame and simmer the Udupi sambar for few minutes for other ingredients to cook completely.", "Once done, switch off the stove and it is ready to be served.Serve Udupi Style Sambar Recipe - Masala Huli With Mixed Vegetables along with\u00a0Homemade Soft Idli Recipe\u00a0and\u00a0Red Chilli Coconut Chutney Recipe (South Indian Chutney)\u00a0for breakfast."]'::jsonb, 50, 'Udupi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/panditp253-gmail.com/UDUPI_SAMBAR.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/210.UDUPI_SAMBAR.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Konkani Style Vali Bendi Recipe-Malabar Spinach Curry', 'konkani-style-vali-bendi-recipe-malabar-spinach-curry', 'Konkani Style Vali Bendi Recipe-Malabar Spinach Curry, a simple authentic curry made from Malabar spinach or in other words called as vine spinach is cooked in ground fresh coconut, dry red chilies and tamarind paste. In Konkani, “Vali” refers to the Spinach that is used in the curry, the leaf is rich in  lot of nutrients. It reduces cholesterol and is highly fibrous. It is good for digestion also.', '["1 cup Spinach Leaves (Palak)", "4 cloves Garlic", "Salt , to taste", "To Grind", "1/2 cup Fresh coconut", "3 Dry Red Chillies", "18 grams Tamarind"]'::jsonb, ARRAY['salt', 'coconut', 'cloves garlic', 'dry red chillies', 'tamarind', 'spinach leaves (palak)']::text[], '["To begin making the Konkani Style Vali Bendi Recipe, we will heat a skillet to dry roast the dry red chillies.Once done grind it along with coconut and tamarind to a smooth paste by adding some water.Heat a pressure cooker with oil, add pound garlic and allow it to sizzle.", "Add chopped spinach leaves and saute for few seconds till it wilts.Add ground paste and about 1/2 cup water and salt.", "Pressure cook for around 2 whistle.", "Serve the Konkani Style Vali Bendi Recipe along with steamed rice with a dollop of ghee on top and\u00a0Konkani Style Mooga Ghushi Recipe\u00a0by the side to enjoy your everyday lunch."]'::jsonb, 30, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Konkani_Style_Vali_Bendi_Recipe_Malabar_Spinach_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/211.Konkani_Style_Vali_Bendi_Recipe_Malabar_Spinach_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Pressure Cooker Mutton Curry Recipe', 'spicy-pressure-cooker-mutton-curry-recipe', 'Spicy Pressure Cooker Mutton Curry Recipe is a quick mutton recipe that requires marinating the mutton and cooking it in a pressure cooker in an onion tomato gravy.', '["750 grams Mutton , on the bone", "Salt", "1 teaspoon Lemon juice", "1 teaspoon Turmeric powder (Haldi)", "1/2 cup Curd (Dahi / Yogurt)", "To be ground into a paste", "3 Onions , roughly chopped", "10 cloves Garlic", "2 inch Ginger", "2 tablespoons Ghee", "2 Cloves (Laung)", "1 Bay leaf (tej patta)", "2 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "1 teaspoon Fennel seeds (Saunf)", "3 Green Chillies", "Salt", "4 Tomatoes , pureed", "1 teaspoon Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Coriander (Dhania) Powder", "2 tablespoons Meat masala", "1 teaspoon Garam masala powder", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "4 sprig Coriander (Dhania) Leaves"]'::jsonb, ARRAY['s mutton', 'salt', 'lemon juice', 'turmeric powder', 'haldi', 'curd', 'dahi / yogurt', 'to be ground into a paste', 'onions', 's garlic', 'ginger', 's ghee', 'laung', 'bay leaf', 'tej patta', 'cardamom', 'elaichi', 'cinnamon stick', 'dalchini', 'fennel seeds', 'saunf', 'reen chillies', 'tomatoes', 'red chilli powder', 'cumin powder', 'jeera', 'coriander', 'dhania', 's meat masala', 'garam masala powder', 'kasuri methi', 'dried fenugreek leaves']::text[], '["To begin making Spicy Pressure Cooker Mutton Curry Recipe firstly marinate the mutton.", "To marinate the mutton, in a large mixing bowl, combine the washed and cleaned mutton, along with curd, salt, lemon juice and turmeric powder and mix well.", "Cover and set aside for at least an hour.", "Make a paste of the onion, ginger and garlic and keep aside.", "To make the curry, heat ghee in a\u00a0 pressure cooker over medium heat; add the whole spices, bay leaf, clove, cardamom, saunf, and cinnamon stick.", "When the whole spices begin to sizzle, add the green chillies.", "Saute for 30 seconds or until the raw smell goes away.", "Next, add in the onion ginger garlic paste and saute for about a minute.", "Stir in the red chilli powder, jeera powder, coriander powder and meat masala and continue to saute for another minute.", "Once this mutton curry masala mixture has come together, add the tomato puree, cover and cook for 2 minutes.", "When you feel the raw tomato small has gone, add in the mutton along with the marinade.", "Stir well, check for salt and spices and adjust seasoning according to your taste.", "Close the pressure cooker and pressure cook the mutton curry for about 5-6 whistles and turn off the heat.", "Allow the pressure to release naturally.", "Then open and stir in the kasuri methi.", "Garnish the mutton curry with coriander leaves and serve hot.", "Serve Spicy Pressure Cooker Mutton Curry Recipe\u00a0along with\u00a0Whole Wheat Lachha Paratha\u00a0and\u00a0Tomato Onion Cucumber Raita\u00a0for a weekend dinner."]'::jsonb, 60, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/FlavorFlameFusion/Spicy_Pressure_Cooker_Mutton_Curry_Recipe_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/212.Spicy_Pressure_Cooker_Mutton_Curry_Recipe_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Prawn Fritters Recipe (Shrimp Vadai)', 'prawn-fritters-recipe-shrimp-vadai', 'Weekend evenings always calls for some delicious food but when we are not well and still want to have some delicious food. Some easy and delicious recipes comes handy so this prawn Fritters is one such dish. Just grab all the ingredients grind it. Shape into patties and fry tada Prawn Vadai is ready is less time.', '["To Grind", "1/4 kg Prawns", "1/4 cup Fresh coconut , grated", "6 Shallots", "1/2 inch Ginger", "5 cloves Garlic", "2 Green Chilli", "1 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , as needed", "Other Ingredients", "1 Onion", "1 teaspoon Fennel seeds (Saunf)", "1/4 cup Coriander (Dhania) Leaves , tightly packed", "2 tablespoon Rice flour", "Oil , for deep frying", "Curry leaves , a spring"]'::jsonb, ARRAY['salt', 'ginger', 'green chilli', 'coconut', 'fennel seeds (saunf)', 'coriander (dhania) leaves', 'red chilli powder', 'cloves garlic', 'curry leaves spring', 'onion', 'rice flour', 'turmeric powder', 'prawns', 'sunflower oil']::text[], '["To begin making the Prawn Fritters recipe, clean and de-vein the prawn and set it ready.", "In a blender add in the prawns, coconut along with all the ingredients mentioned in the \u201cTo grind\u201d table.", "Now take the ground mix to a big bowl to this add in the Rice flour, Chopped onions, Coriander leaves, Curry Leaves and Fennel Seeds.", "Mix everything well so that all the ingredients are mixed evenly.", "Divide the dough into equal sized small shaped balls and flatten it.", "Heat oil for deep frying.", "Once the oil is hot drop in 4-5 Vada\u2019s per batch and start frying.", "Once the Vada\u2019s are cooked strain it and place in paper towels to absorb excess oil.", "Serve hot.Serve\u00a0Prawn Fritters along with some\u00a0Dhaniya Pudina Chutney\u00a0and\u00a0Date Tamarind Chutney\u00a0for your evening snacks or serve them for your party."]'::jsonb, 25, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/happytrioexplains-gmail.com/Prawn_Fritters__Shrimp_Vadai.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/213.Prawn_Fritters__Shrimp_Vadai.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Vengaya Kosu Recipe (Spicy Curry from Chettinad Cuisine)', 'chettinad-vengaya-kosu-recipe-spicy-curry-from-chettinad-cuisine', 'Chettinad Vengaya Kosu Recipe is a flavorful spicy gravy from Chettinad cuisine. This gravy is very simple and easy to make with just two basic ingredients, onion and tomato. Alternatively, you can add potatoes to prepare Chettinad Vengaya Kosu along with onions and tomatoes.', '["1 Onion , thinly sliced", "2 Tomatoes , finely chopped", "8-10 Curry leaves", "1/2 tablespoon Sesame (Gingelly) Oil", "1/2 teaspoon Fennel seeds (Saunf)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "5 to 6 Dry Red Chillies , adjust according to taste", "1/4 cup Fresh coconut , chopped", "2 sprig Coriander (Dhania) Leaves , finely chopped for garnishing"]'::jsonb, ARRAY['tomato', 'salt', 'coconut', 'fennel seeds (saunf)', 'sesame (gingelly) oil', 'curry leaves', 'coriander (dhania) leaves', 'dry red chillies', 'onion', 'turmeric powder']::text[], '["To begin making Chettinad Vengaya Kosu Recipe, first make the spice paste for the kosu.", "Heat a kadai on medium heat and dry roast red chillies and fennel seeds till they turn fragrant.", "Turn off the heat and let them cool.", "Once the red chilli and fennel seeds are cooled, grind them in a mixie jar along with coconut.", "Add a little water to make a smooth paste. keep the masala paste aside.", "You can proceed to make the tempering.To prepare the tempering, heat a kadai on medium heat.", "Add sesame oil and temper with fennel seeds and curry leaves.", "Add the sliced onions and tomatoes.", "Add turmeric powder and salt.Mix well and let them cook on low flame till the tomatoes become soft and pulpy.", "Add 1 cup of water to the mixture.", "Now add the ground masala and mix well.Let the gravy simmer for 3-4 minutes.After 3-4 minutes, turn off the heat.", "Transfer Chettinad Vengaya Kosu in a serving bowl.Garnish with chopped cilantro/mint leaves and serve hot with Biryani, Ven Pongal\u00a0or\u00a0Onion Rava Dosa Recipe for breakfast, lunch or weeknight dinner."]'::jsonb, 35, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Uma_Raghuraman/Chettinad_Vengaya_Kosu_Spicy_Curry_from_Chettinad_Cuisine.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/214.Chettinad_Vengaya_Kosu_Spicy_Curry_from_Chettinad_Cuisine.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Traditional Whole Gobi Musallam Recipe', 'traditional-whole-gobi-musallam-recipe', 'Traditional Whole Gobi Musallam Recipe is a roasted whole cauliflower dish and much popular dish in northern part of India. Gobi musallam is easy to prepare and eye appealing too. Mainly the whole cauliflower / gobi is first parboiled, a creamy sauce is whipped up, then parboiled gobi is well coated by sauce and roasted in oven. Finally the delicious dish is served in an exotic way. This is a very presentable dish and can make a centerpiece on serving table in any party. Serve Traditional Whole Gobi Musallam Recipe along with naans or phulkas.', '["1 Cauliflower (gobi) , whole", "10 Cashew nuts", "1 Onion , chopped", "2 Tomatoes , chopped", "4 cloves Garlic , chopped", "1/2 inch Ginger , chopped", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "2 teaspoons Kasuri Methi (Dried Fenugreek Leaves)", "1/2 teaspoon Turmeric powder (Haldi)", "Coriander (Dhania) Leaves , for garnishing", "Water , as needed", "Salt , as needed"]'::jsonb, ARRAY['cashew nuts', 'tomato', 'cumin powder (jeera)', 'ginger', 'salt', 'coriander (dhania) leaves', 'cauliflower (gobi)', 'red chilli powder', 'cloves garlic', 'water', 'onion', 'coriander powder', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'garam masala powder']::text[], '["To prepare Traditional Whole Gobi Musallam Recipe, remove any outer leaves from the cauliflower head.", "Then put the cauliflower on a plate facing the stem upwards.", "Using a knife, cut the extra stem in such a way that cauliflower can sit straight at base facing the florets upwards.Soak the cashews in water.Prep other veggies and ingredients as well.In a pan boil enough water along with salt and turmeric powder.", "Gently drop the whole head cauliflower (head facing upwards) in the boiling water and boil for 5 minutes.", "Then flip it (head facing downwards) and again boil for 5 minutes.", "Or alternatively, steam it till al dente.Strain the cauliflower and keep aside.In another pan, heat oil on medium heat.", "Add the coarsely chopped onion, garlic, ginger and saut\u00e9 for 5 minutes till onion turns transparent.Next add coarsely chopped tomato and all spice powder except kasoori methi.", "Cook until tomato turns soft.Turn off the heat and let the masala mixture cool completely.Then blend the cooled masala mixture along with soaked cashews until smooth paste in a blender.Pour this paste into the same pan and cook again on medium heat for 5-10 minutes.Add little water if the sauce gets too thick.", "Now add kasoori methi, stir well and cook for another 5 minutes.In the meanwhile, preheat oven to 200 deg C.Put the cauliflower (head facing upwards) in a baking dish and pour the masala over the cauliflower and ensure that the whole cauliflower is well coated.", "Bake for 30 minutes and by the time the cauliflower starts to brown.Garnish with coriander leaves, slice Traditional Whole Gobi Musallam Recipe and serve along with naans or phulkas."]'::jsonb, 65, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/firsttimercook/Gobi_Musallam__Cauliflower_Musallam.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/215.Gobi_Musallam__Cauliflower_Musallam.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Brahmin Style Vegetable Kurma Recipe', 'brahmin-style-vegetable-kurma-recipe', 'Brahmin Style Vegetable Kurma Recipe is a No Onion No Garlic curry which is made with loads of vegetables and cooked in a freshly ground coriander and coconut curry.', '["2 Carrots (Gajjar) , diced", "100 grams Green beans (French Beans) , chopped in small pieces", "2 Potatoes (Aloo) , skin peeled and diced", "1 Green Chilli , slit", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 inch Cinnamon Stick (Dalchini)", "Salt , to taste", "Oil", "To Grind", "1/2 cup Fresh coconut", "2 tablespoons Roasted Gram Dal (Pottukadalai)", "5 sprig Coriander (Dhania) Leaves", "1 teaspoon Kala jeera", "1 teaspoon Cumin seeds (Jeera)", "1 Green Chilli", "1 inch Ginger", "1 teaspoon Turmeric powder (Haldi)", "10 grams Tamarind"]'::jsonb, ARRAY['salt', 'green beans (french beans)', 'ginger', 'green chilli', 'mustard seeds', 'coconut', 'potato (aloo) skin', 'gram dal (pottukadalai)', 'carrot', 'coriander (dhania) leaves', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'turmeric powder', 'tamarind', 'kala jeera', 'sunflower oil']::text[], '["To begin making the Brahmin Style Vegetable Kurma Recipe, we will firstly wash, chop all the vegetables\u00a0 and keep it ready.Then put all the ingredients for grinding including coconut, gram dal, coriander leaves, kala jeera, cumin seeds, green chilli, ginger, turmeric powder, tamarind into a mixer and grind into a smooth paste by adding little water.Heat a pressure cooker with oil, add mustard seeds, cloves and cinnamon stick and wait till they splutter for few seconds.Add carrots, green beans, potatoes and saute them until they soften.", "Once the vegetables are half cooked you can add the ground paste.After 2 minutes, add water, salt and pressure cook for about 1 whistle.", "Release the pressure naturally, open the cooker, give it a mix and serve the Vegetable Kurma hot.Serve the\u00a0Brahmin Style Vegetable Kurma Recipe\u00a0along with\u00a0Tawa Paratha, along with a\u00a0Bhaji Vada Recipe (Lentil And Vegetable Fritters)\u00a0by the side to enjoy your everyday lunch.", "You can also serve it with\u00a0Steamed Rice\u00a0and\u00a0Carrot Methi Pachadi."]'::jsonb, 35, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Brahmin_Style_vegetable_Kurma_Recipe_No_onion_and_No_Garlic.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/216.Brahmin_Style_vegetable_Kurma_Recipe_No_onion_and_No_Garlic.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Stuffed Mooli Paratha Recipe With Radish Greens', 'stuffed-mooli-paratha-recipe-with-radish-greens', 'Stuffed Mooli Paratha Recipe (Indian Radish Stuffed Flatbread) is one of the most popular flat breads relished all across India. Grated white radish along with some spices is stuffed in a whole wheat flour dough along with radish greens to make these wholesome parathas. Comforting and satisfying these stuffed parathas are a great way to include radish in your diet. Stuffed Mooli paratha can be served for breakfast or any other meal, all throughout the year. They taste great when hot but are good when cold too, hence they make for a nutritious lunch box meal.', '["2 Mooli/ Mullangi (Radish) , finely grated", "2 teaspoon Oil", "2 teaspoons Cumin seeds (Jeera)", "1 teaspoon Ginger , grated", "2 teaspoons Ajwain (Carom seeds)", "1-1/2 tablespoons Gram flour (besan) , (optional)", "Coriander (Dhania) Leaves , a handful, chopped", "2 teaspoons Red Chilli powder , or green chilli paste", "Salt , to taste", "2-2 Whole Wheat Flour", "Mooli Ke Patte (Radish Greens) , a handful, chopped", "1 teaspoon Salt", "Oil , or ghee to smear while cooking"]'::jsonb, ARRAY['salt', 'wheat flour', 'ginger', 'sunflower oil ghee', 'coriander (dhania) leaves', 'ajwain (carom seeds)', 'mooli ke patte (radish greens)', 'gram flour (besan)', 'cumin seeds (jeera)', 'mooli mullangi (radish)', 'red chilli powder green chilli paste', 'sunflower oil']::text[], '["To begin making the Stuffed Mooli Paratha Recipe With Radish Greens, first make the stuffing."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/madhulia/Stuffed_Mooli_Paratha_Indian_Radish_stuffed_flatbread.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/217.Stuffed_Mooli_Paratha_Indian_Radish_stuffed_flatbread.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Palak And Kala Chana Sukhi Sabzi Recipe', 'palak-and-kala-chana-sukhi-sabzi-recipe', 'Palak & Kala Chana Sukhi Sabzi Recipe is a wonderful way to add in protein as well as Iron into the same dish. The combination is wonderful to have it along with your Phulkas or Tawa parathas.', '["1 cup Kala Chana (Brown Chickpeas) , soaked overnight", "1 cup Spinach Leaves (Palak) , washed and roughly chopped", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1 Green Chilli , slit", "1 inch Ginger , grated", "2 cloves Garlic , grated", "Salt , as per taste", "2 teaspoons Garam masala powder", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1 Bay leaves (tej patta)", "2 Cardamom (Elaichi) Pods/Seeds", "Oil , as required"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'garam masala powder', 'green chilli', 'bay leaves (tej patta)', 'cardamom (elaichi) podsseeds', 'red chilli powder', 'cloves garlic', 'onion', 'coriander powder', 'turmeric powder', 'spinach leaves (palak)', 'kala chana (brown chickpeas)', 'sunflower oil']::text[], '["To begin making the Palak Kala Chana Recipe first clean, wash and soak chickpeas in water overnight or at least 5 - 6 hours.First make puree of tomato and green chili using 2 - 3 tablespoons of water in blender.Heat a teaspoon of oil in a pan; add in the chopped spinach and saute until the spinach is soft and tender.", "Keep this aside.Note: We cook the spinach separately from the chola, as the cooking times for the chickpeas and spinach are very different.", "Spinach takes a couple of minutes, while the chola/ chickpeas take 20 to 30 minutes.In a pressure cooker heat oil over medium heat, once oil is heated add in the bay leaf and cardamom pods; saute for 1 minute or until spices start releasing aroma.Now add in chopped onion, ginger and garlic and saute over medium heat until onion turn light brown in color.Once onion is ready add tomato puree, salt, turmeric powder, garam masala, and coriander powder, red chili powder until you see the mixture coming together and thickening a little bit.Add the chickpeas along with the water it was soaked in into the masala and stir well.", "Add in additional water so that the water level is atleast 2 inches above the soaked Kala Chana.Give it a good stir and cover the pressure cooker and place its weight on.", "Cook the kala Chana in the pressure cooker until you hear 4 to 5 whistles.", "After 4 to 5 whistles, turn the heat to low and simmer the chana for another 15 minutes and then turn off the heat.Allow the pressure to release naturally.", "This will take another 15 minutes.", "Once the pressure releases naturally, open the cooker, add in the sauteed spinach and give it a good stir.Check the salt and spice levels and adjust to suit your taste.", "Gently mash the chickpeas little bit with the back of the ladle to thicken the gravy little bit and the Palak Kala Chana Sukhi Recipe is ready to be served.Serve the\u00a0Palak & Kala Chana Sukhi Sabzi Recipe\u00a0along with\u00a0Dal Tadka,\u00a0Dill Cucumber Raita,\u00a0Jeera Rice\u00a0and\u00a0Phulka\u00a0for a delicious weekday meal."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Palak__Kala_Channa_Sukhi_Subzi_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/218.Palak__Kala_Channa_Sukhi_Subzi_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dondakkai / Kovakkai Poriyal Recipe - Tindora Poriyal', 'dondakkai-kovakkai-poriyal-recipe-tindora-poriyal', 'The Kovakkai Poriyal Recipe is a classic South Indian vegetable that you can serve for your everyday meals. Kovakkai is also known as Dondakkai or Tinda or Tindora or Tendley. At home we simply love the taste and flavors of this vegetable when it is just steamed and then tossed in a seasoning that has only mustard, curry leaves, salt and coconut.', '["500 grams Tindora (Dondakaya/ Kovakkai) , (dondakkai), cut to rounds or slices", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves , finely chopped", "1 pinch Asafoetida (hing)", "1/4 cup Fresh coconut , grated", "Salt , to taste"]'::jsonb, ARRAY['s tindora', 'dondakaya/ kovakkai', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'curry leaves', 'asafoetida', 'hing', 'fresh coconut', 'salt']::text[], '["To begin making the Dondakkai / Kovakkai Poriyal Recipe, we will first cut the\u00a0Dondakkai / Kovakkai into the desired shape.Place the cut\u00a0Dondakkai / Kovakkai into a steamer, sprinkle some salt and steam on high heat until the vegetable is cooked through.", "At home, we personally like the vegetables to have a slightly firm texture as opposed to something too soft and mushy.Once the\u00a0Kovakkai is steamed, turn off the heat and remove it from the steamer container and keep aside.The next step is to season the vegetable.", "Heat a teaspoon of oil in a heavy bottomed pan\u00a0on medium heat.", "Add the mustard seeds and the halved urad dal.", "Allow them to crackle and roast the urad dal until it is crisp and golden.", "Once the dal is roasted, sprinkle the asafoetida, add the curry leaves and the steamed\u00a0Kovakkai.", "Stir well to combine the\u00a0Kovakkai Poriyal.", "Check the salt and adjust to suit your taste.", "Finally, stir in the grated coconut and give it a mix.Turn off the heat and transfer the\u00a0Dondakkai / Kovakkai Poriyal into a serving bowlServe the\u00a0Kovakkai Poriyal\u00a0along with\u00a0Jeera Rasam,\u00a0Mixed Vegetable Sambar,\u00a0Beetroot Pachadi,\u00a0Steamed Rice\u00a0and\u00a0Elai Vadam\u00a0for a delicious weekend South Indian meal."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Dondakkai_Kovakkai_Gherkins_Tinda_Tindora_Poriyal_Recipe_South_Indian_Curry-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/219.Dondakkai_Kovakkai_Gherkins_Tinda_Tindora_Poriyal_Recipe_South_Indian_Curry-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Cauliflower Curry With Bell Peppers And Carrots In Spiced Milk Gravy', 'cauliflower-curry-with-bell-peppers-and-carrots-in-spiced-milk-gravy', 'Cauliflower Curry with Bell Peppers and Carrots is simmered in a in spiced milk gravy is simple and quick to make for those busy weeknight dinners. Spices like saffron (optional) and cardamom along with cumin with the crunchy florets make it delicious. Serve itCauliflower Curry with Bell Peppers and Carrots in spiced milk gravy along with plain parathas or phulkas or even a pita bread toasted with butter.', '["2 cups Cauliflower (gobi) , steamed florets", "1 cup Carrots (Gajjar) , diced and steamed", "1 cup Green Bell Pepper (Capsicum) , diced", "1 Onion , cut", "1 cup Homemade tomato puree", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Red Chilli powder", "1 cup Milk , mixed with 1 teaspoon corn flour", "4 Cardamom (Elaichi) Pods/Seeds , whole", "Salt , to taste", "1 teaspoon Oil", "Coriander (Dhania) Leaves , small bunch, chopped"]'::jsonb, ARRAY['s cauliflower', 'gobi', 'carrots', 'gajjar', 'green bell pepper', 'capsicum', 'onion', 'homemade tomato puree', 'cumin seeds', 'jeera', 'turmeric powder', 'haldi', 'cumin powder', 'garam masala powder', 'red chilli powder', 'milk', 'cardamom', 'elaichi', 'salt', 'oil', 'coriander', 'dhania']::text[], '["To prepare Cauliflower Curry with Bell Peppers and Carrots in Spiced Milk Gravy, heat oil in a heavy bottomed pan; add in the cumin seeds and allow it to crackle.", "Once it does, add in the bell peppers and onions, saute until tender.Once tender, stir in the cardamom pods, tomato puree, turmeric powder, cumin powder, garam masala powder, red chilli powder.", "Saute until the tomatoes starts to bubble.", "Stir in the milk mixture and the steamed vegetables.", "Turn the heat to low, cover the pan and simmer for a about 5 minutes.Turn off the heat, stir in the chopped coriander leaves and serve Cauliflower Curry with Bell Peppers and Carrots in Spiced Milk Gravy\u00a0hot with phulkas."]'::jsonb, 70, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/cauliflower-curry-with-bell-peppers-and-carrots-in-spiced-milk-gravy.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/220.cauliflower-curry-with-bell-peppers-and-carrots-in-spiced-milk-gravy.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lahsuni Paneer Recipe - Paneer Flavoured With Garlic', 'lahsuni-paneer-recipe-paneer-flavoured-with-garlic', 'Garlic as an ingredient gives an extra kick to any dish it gets added to. The pungency of garlic goes away with a little bit of cooking and it retains a wonderful taste and flavours any dish beautifully. In this dish, we have used cottage cheese or paneer which is sauteed in a mild garlic and red chilli sauce.  Garlic paneer is a tasty appetizer recipe that can be prepared in less than 15 minutes.', '["200 grams Paneer (Homemade Cottage Cheese)", "10 cloves Garlic", "4 Dry Red Chillies", "1 teaspoon Vinegar", "1 teaspoon Sugar", "Salt , as required", "1 Onion", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Oil", "Coriander (Dhania) Leaves , for garnish"]'::jsonb, ARRAY['salt', 'coriander (dhania) leaves', 'paneer', 'cloves garlic', 'sugar', 'dry red chillies', 'onion', 'vinegar', 'cumin seeds (jeera)', 'sunflower oil']::text[], '["To begin making the Lahsuni Paneer Recipe, thaw the paneer to room temperature.", "Cut into small cubes and keep aside.", "Follow\u00a0Homemade Paneer Recipe\u00a0to make paneer at home.To a mixer, add garlic pods, sugar, vinegar, salt and dry red chilli (removing seeds inside) and grind everything into smooth paste in a mixer grinder adding very little water.In a heavy bottomed pan, heat some oil (or butter).", "Add cumin seeds and once it splutters, add chopped onion and saute until translucent.", "Now add the grounded garlic chilli paste to it and saute well until raw smell goes.Once everything is combined and the oil starts separating, add the paneer cubes.", "Saute for 2-3 minutes in medium flame until paneer gets coated with masala.Garnish\u00a0Lahsuni Paneer with coriander leaves and remove from flame.", "Serve hot.Serve freshly prepared Lahsuni Paneer\u00a0for a weekend meal along with Parathas, Punjabi Dal Tadka and Red Cabbage Carrot, Sprout and Onion Salad\u00a0for a complete meal."]'::jsonb, 25, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swathynandhini/GARLIC_PANEER_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/221.GARLIC_PANEER_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pudina Tambuli Recipe', 'pudina-tambuli-recipe', 'Pudina Tambuli/Tambli is a very traditional Karnataka dish which our grannys have been making from many years. Its basically a uncooked yoghurt based dish served along with rice. One can make thambli using different herbs/seeds/peels/ingredients. Today we have Pudina Tambli / mint leaves thambli. The heavenly aroma that comes out of your kitchen when you are roasting these leaves along with some cumin and pepper seeds is so awesome.', '["1/2 cup Mint Leaves (Pudina)", "1 teaspoon Cumin seeds (Jeera)", "3 Whole Black Peppercorns", "1 Green Chilli", "1/4 cup Fresh coconut , grated", "1-1/2 cup Buttermilk", "1 teaspoon Ghee", "Salt , to taste", "1 teaspoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "6 Curry leaves", "1 Dry Red Chilli , broken"]'::jsonb, ARRAY['salt', 'green chilli', 'coconut', 'ghee', 'mustard seeds', 'black peppercorns', 'curry leaves', 'dry red chilli', 'cumin seeds (jeera)', 'buttermilk', 'mint leaves (pudina)']::text[], '["To begin making the Pudina Tambuli recipe, clean and\u00a0 wash mint leaves .In a pan add few drops of ghee and roast jeera, pepper and green chilli.", "Fry for a minute.Add the pudina leaves and saut\u00e9 for 2-3 minutes or till the leaves turn soft and change their colour.Remove from the flame and keep aside to cool.", "Grind leaves, spice mix, coconut and salt to a very smooth paste in a mixer by adding little water.Pour the mixture to a bowl and add buttermilk/curd.", "Mix well.Adjust the consistency as required.", "The consistency should be thin .Heat the remaining ghee in a small pan.", "Add mustard seeds and jeera ,when it splutters add curry leaves.", "Pour the tempering on the thambli.Serve Pudina Tambli in room temperature with hot steaming rice and\u00a0Keerai Sambar\u00a0or relish as such as a drink."]'::jsonb, 15, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/PUDINA_THAMBLI.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/222.PUDINA_THAMBLI.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Special Steamed Lentil Dumplings Gravy - Kola Urundai Kuzhambu', 'chettinad-special-steamed-lentil-dumplings-gravy-kola-urundai-kuzhambu', 'Chettinad Special Steamed Lentil Dumplings Gravy - Kola Urundai Kuzhambu is a traditional chettinad dish served for lunch during weddings, celebrations and festival times. Kola Urundai Kuzhambu is a traditional curry from the chettinad region of the Tamil Nadu. Chettinad cuisine is believed to be one the spiciest cuisines in India. The preparation is fairly simple, but has a perfect mix of flavors.', '["Ingredients for Grinding (To Make Lentil Dumplings)", "1 cup Arhar dal (Split Toor Dal)", "4 Dry Red Chilli", "1 teaspoon Fennel seeds (Saunf)", "1/2 inch Cinnamon Stick (Dalchini)", "1 inch Ginger , peeled and finely chopped", "5 Garlic , finely chopped", "2 Shallots , finely chopped", "1 cup Fresh coconut , grated", "Salt , as per taste", "Ingredients for Tadka", "2 teaspoons Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 teaspoon Fennel seeds (Saunf)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1 sprig Curry leaves", "1 Bay leaf (tej patta)", "Ingredients for Kuzhambu/ Gravy", "5 Tomatoes , chopped", "2 Shallots , chopped", "5 Garlic , chopped", "2 teaspoon Red Chilli powder , adjustable", "2 teaspoons Coriander Powder (Dhania)", "1 teaspoon Turmeric powder (Haldi)", "Salt , as per taste", "Tamarind Paste , extract from lemon sized ball", "1/2 teaspoon Garam masala powder"]'::jsonb, ARRAY['ingredients for grinding', 'to make lentil dumplings', 'arhar dal', 'split toor dal', 'dry red chilli', 'fennel seeds', 'saunf', 'cinnamon stick', 'dalchini', 'ginger', 'arlic', 'shallots', 'fresh coconut', 'salt', 'ingredients for tadka', 's oil', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'methi seeds', 'fenugreek seeds', 'curry leaves', 'bay leaf', 'tej patta', 'ingredients for kuzhambu/ gravy', 'tomatoes', 'red chilli powder', 's coriander powder', 'dhania', 'turmeric powder', 'haldi', 'tamarind paste', 'garam masala powder']::text[], '["To begin making Chettinad Special Steamed Lentil Dumplings Gravy - Kola Urundai Kuzhambu we will first make the lentil dumplings."]'::jsonb, 60, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/chettinad_special_steamed_lentil_dumplings_gravy_kola_urundai_kuzhambu.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/223.chettinad_special_steamed_lentil_dumplings_gravy_kola_urundai_kuzhambu.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Nagori Puri Recipe (Semolina Puri)', 'nagori-puri-recipe-semolina-puri', 'Nagori Puri is a traditional North Indian spicy, small sized, puffy poori prepared with semolina and ghee. This can be served with simple potato curry, vegetable kurma or paneer masala. You can also serve this poori with sooji halwa or kesari. This is very easy to make and can be prepared in very little time. So give your usual puri a twist with this Nagori Ki Puri.', '["1 cup Sooji (Semolina/ Rava)", "1/2 cup Whole Wheat Flour", "1 teaspoon Cumin seeds (Jeera)", "2 tablespoons Ghee", "Water , as required", "Salt , to taste", "Oil , as required, for deep frying"]'::jsonb, ARRAY['salt', 'wheat flour', 'ghee', 'water', 'cumin seeds (jeera)', 'sooji (semolina rava)', 'sunflower oil']::text[], '["To begin making the Nagori Puri Recipe, firstly sift wheat flour to a mixing bowl.", "Add rava, salt, cumin seeds and melted ghee to it.Mix and rub everything together to make it crumbly.", "Add water little by little and start kneading to make stiff dough.Divide the dough into small sized balls.", "Take the balls and roll it flat into thin circles using a rolling pin.Heat oil for deep frying, once hot drop the puri and fry in medium flame until puffed up and slightly changes brown on both the sides.Remove from oil and drain excess oil in kitchen tissues.", "Fry the puris one by one and serve hot.", "Serve\u00a0Nagori Puri along with\u00a0Gujarati Lasaniya Batata\u00a0and\u00a0Palak Raita\u00a0for a weekend lunch with your family."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swathynandhini/NAGORI_PURI_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/224.NAGORI_PURI_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lilve Ki Sabzi Recipe (Green Chickpea Curry)', 'lilve-ki-sabzi-recipe-green-chickpea-curry', 'People from Rajasthan make different types of dishes using green chickpeas but Lilve Ki Sabzi is quite popular in almost all the households which is usually served with chapatis.', '["Oil , as required", "1 cup Fresh green chickpeas", "1 Potato (Aloo) , cubed", "1 Bay leaf (tej patta)", "1 Black cardamom (Badi Elaichi)", "1 tablespoon Ginger Garlic Paste", "1 Onion , finely chopped", "1 Onion , paste", "2 tablespoons Curd (Dahi / Yogurt)", "1 teaspoon Red Chilli powder", "3/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "Salt , as required", "Water , as required", "2 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['black cardamom (badi elaichi)', 'salt', 'bay leaf (tej patta)', 'potato (aloo)', 'red chilli powder', 'water', 'ginger garlic paste', 'onion paste', 'curd', 'coriander (dhania) leaves', 'green chickpeas', 'onion', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Lilve Ki Sabzi recipe, firstly heat oil in a heavy bottomed pan and add bay leaf, cloves and elaichi.Saute them for about 15 seconds and add the finely chopped onions.", "Cook them till they turns soft and translucent.Add the cubed potatoes and cook for another 5 minutes or until they become soft.Next, add in the ginger garlic paste and onion paste.", "Cook it for 2 to 3 minutes and then add all the masalas including red chilli powder, turmeric powder and coriander powder.Cook it for 2 minutes.", "Next add curd and the required salt.", "When the gravy starts leaving the oil from the sides, add the green chickpeas.After 5 minutes, add the required water, mix properly and cover the lid.Let it cook till the gravy thickens and the green chickpeas are cooked.Once it is done, garnish with coriander leaves and serve hot.Serve Lilve Ki Sabzi with hot steamed rice and rotis for a weekend meal."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Lilve_Ki_Sabzi_Green_Chickpea_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/225.Lilve_Ki_Sabzi_Green_Chickpea_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bihari Style Kadhi Badi Recipe', 'bihari-style-kadhi-badi-recipe', 'Bihari Style Kadhi Badi Recipe is one of the most loved dish in Bihar. Any auspicious occasion is incomplete without feasting on Kadhi Badi. It is a soothing sour curd base recipe with chickpea flour dumplings called badi in it (besan).', '["1 cup Curd (Dahi / Yogurt) , (sour)", "2 tablespoons Gram flour (besan)", "1/2 teaspoon Turmeric powder (Haldi)", "Red Chilli powder , to taste", "Salt , to taste", "1 cup Gram flour (besan)", "1 teaspoon Ajwain (Carom seeds)", "1/2 teaspoon Kalonji (Onion Nigella Seeds)", "1/2 teaspoon Turmeric powder (Haldi)", "2 tablespoons Onion , chopped", "Salt , to taste", "Red Chilli powder , to taste", "Oil , to deep fry", "1/2 cup Water", "1 teaspoon Cumin seeds (Jeera)", "3 Dry Red Chillies", "Curry leaves , few", "1 teaspoon Ginger Garlic Paste", "2 teaspoon Oil", "2 teaspoon Oil"]'::jsonb, ARRAY['salt', 'kalonji (onion nigella seeds)', 'ajwain (carom seeds)', 'red chilli powder', 'water', 'gram flour (besan)', 'curd', 'curry leaves', 'dry red chillies', 'onion', 'cumin seeds (jeera)', 'ginger garlic paste', 'turmeric powder', 'sunflower oil']::text[], '["To begin making Bihari Style Kadhi Badi Recipe, take a bowl and mix all the badi ingredients together including gram flour, ajwain, kalonji, turmeric powder, onion, salt, red chilli powder, salt and make a thick paste with water.", "Keep it aside for 15 minutes.Meanwhile for Kadhi, mix together yogurt and chickpea flour, salt, turmeric powder, red chilli powder and about 2 cups of water.Beat well so that no lumps remain and is smooth.", "You can add more water if you prefer thin gravy.For tempering, heat oil in a heavy bottomed pan.", "Add cumin seeds and let it splutter.", "Add whole red chillies and saut\u00e9 till they release an aroma.Add curry leaves and ginger-garlic paste.", "Let it cook for about 2 minutes.", "Now add the kadhi mix and let it simmer on low flame for 15 minutes.In the meanwhile, Heat a kuzhi paniyaram pan with enough oil and add a tablespoon of the badi\u00a0dough into the hollow holes and fry them on either side till it is golden brown.", "Put the badi in the kadhi gravy that is simmering away, you can add it immediately as the badi will soak up in enough gravy.", "Cover and cook for 5 more minutes.", "Serve hot.Serve\u00a0Bihari Style Kadhi Badi Recipe\u00a0with\u00a0Jeera Rice,\u00a0Kachumber Salad\u00a0and\u00a0Masala Khichia\u00a0for an everyday meal."]'::jsonb, 75, 'Bihari', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/30-march/Bihari_Style_Kadhi_Badi_Recipe_yogurt_curry-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/226.Bihari_Style_Kadhi_Badi_Recipe_yogurt_curry-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Chena Mezhukkupuratty Recipe - Yam Stir Fry', 'kerala-style-chena-mezhukkupuratty-recipe-yam-stir-fry', 'Kerala Style Chena Mezhukkupuratty Recipe is a rich and healthy stir fry made for yam. The masalas added into this makes it a lovely dish to be had anytime of the day. Then onions and garlic is ground and mixed with simple Indian spices to bring in the rich texture flavor to the whole dish. Yam is a type of root vegetable which is rich in potassium and vitamins.', '["2 cups Elephant yam (Suran/Senai/Ratalu) , chopped into small cubes", "1 tablespoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "1 tablespoon Fennel seeds (Saunf) , pound", "1 teaspoon Black pepper powder", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1 tablespoon Coconut Oil", "To Grind", "1 cup Pearl onions (Sambar Onions)", "6 cloves Garlic"]'::jsonb, ARRAY['mustard seeds', 'fennel seeds (saunf) pound', 'red chilli powder', 'cloves garlic', 'elephant yam (suransenairatalu) cubes', 'curry leaves', 'pearl onion (sambar onion)', 'coconut oil', 'black pepper powder', 'turmeric powder']::text[], '["To begin making the Kerala Style Chena Mezhukkupuratty Recipe, firstly\u00a0boil the yam in a pressure cooker with water, salt and turmeric for about 3 whistle.", "Do not boil it till it becomes mushy.", "Strain the water and keep it aside.In a mixer, add in the onions and garlic and grind it into a coarse paste.Heat a kadai with oil, splutter the mustard seeds, curry leaves and then add in the ground onions and garlic.", "Add in the spice powders including red chilli powder, turmeric powder, fennel seeds, black pepper powder and fry till the raw smell goes away.Once done add in the boiled yam and coat the mixture well into the yam.", "Stir fry till it crisps up and check for seasoning by adding salt.", "Serve the\u00a0Kerala Style Chena Mezhukkupuratty Recipe\u00a0along with\u00a0Thandu Keerai Sambar,\u00a0Steamed Rice\u00a0and\u00a0Elai Vadam\u00a0for your everyday meals."]'::jsonb, 45, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Kerala_Style_Chena_Mezhukkupuratty_Recipe_Yam_Stir_Fry_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/227.Kerala_Style_Chena_Mezhukkupuratty_Recipe_Yam_Stir_Fry_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thakkali Gotsu Recipe | Thakkali Curry | Spicy & Tangy Tomato Gravy', 'thakkali-gotsu-recipe-thakkali-curry-spicy-tangy-tomato-gravy', 'Tomato Gotsu Recipe also known as the Thakkali Curry is a quick and easy to make, spicy and tangy tomato gravy you can prepare for a change as a breakfast accompaniment or even as a side dish along with Ven Pongal, Khichdi, Paratha or Dosa.', '["1 tablespoon Sesame (Gingelly) Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves , roughly torn", "2 cloves Garlic , pounded/ chopped", "1 cup Pearl onions (Sambar Onions) , quartered", "4 Tomatoes", "15 grams Tamarind , soaked in warm water", "2 teaspoons Sambar Powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Salt", "1 tablespoon Jaggery"]'::jsonb, ARRAY['tomato', 'salt', 'tamarind water', 'mustard seeds', 'jaggery', 'sesame (gingelly) oil', 'cloves garlic', 'curry leaves', 'pearl onion (sambar onion)', 'turmeric powder', 'sambar powder']::text[], '["To begin making Tomato Gotsu Recipe/ Thakkali Curry Recipe, prepare all the ingredients and keep them ready.Soak the tamarind in hot water for 20 minutes.", "Extract the water from the tamarind to get about 1/2 cup of thick tamarind.Roughly chop the tomatoes and pulse the chopped tomatoes in a mixer grinder.", "You want a chunky sauce and not a fine puree.", "This will help add texture to the Tomato Gotsu.Heat oil in a pressure cooker on medium heat, add the mustard seeds and allow it to crackle.", "Add the curry leaves, garlic and onions and saute until the onions turn tender and translucent.", "Now, add the crushed\u00a0 tomatoes, tamarind water, turmeric powder, sambar powder,\u00a0 salt and jaggery.", "Stir the Tomato Gotsu and pressure cook for 2 whistles.Turn off the heat and allow the pressure to release naturally.", "Once the pressure releases, open the cooker and give the\u00a0Tomato Gotsu/ Thakkali Curry a stir.", "Check the salt and spices and adjust to taste accordingly.", "Transfer the Tomato Gotsu/ Thakkali Curry\u00a0to a serving bowl and serve hot.Serve\u00a0Tomato Gotsu / Thakkali Curry\u00a0with\u00a0Ven Pongal\u00a0and\u00a0\u00a0South Indian Filter Coffee\u00a0for breakfast."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Tomato_Gotsu_recipe_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/228.Tomato_Gotsu_recipe_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mint Coriander Spice Pulao Recipe', 'mint-coriander-spice-pulao-recipe', 'Mint Coriander Spice Pulao Recipe is delicious pulao recipe, flavoured with whole spices like bay leaf, cinnamon stick, and star anise. these whole spices are tempered in ghee, that lends a beautiful flavour to the pulao.  Needless to say that a generous amount of fresh mint leaves and coriander leaves, added to the pulao add great taste and flavour to it.', '["1-1/2 cups Rice , washed and soaked", "1/3 cup Coriander (Dhania) Leaves , finely chopped", "1 tablespoon Ghee", "1/3 cup Mint Leaves (Pudina) , finely chopped", "1 Star anise", "1/2 teaspoon Fennel seeds (Saunf)", "2 Bay leaves (tej patta)", "1 inch Cinnamon Stick (Dalchini)"]'::jsonb, ARRAY['rice', 'ghee', 'coriander (dhania) leaves', 'fennel seeds (saunf)', 'bay leaves (tej patta)', 'cinnamon stick (dalchini)', 'mint leaves (pudina)', 'star anise']::text[], '["To begin making the Mint Coriander Spice Pulao Recipe, heat ghee in a pressure cooker on medium flame, to the hot ghee add, star\u00a0anise,\u00a0fennel seeds,\u00a0bay leaves and\u00a0cinnamon stick.", "Once these whole spices begin to sizzle, add the coriander and mint leaves, and give it a quick stir.", "Finally add in the washed and drained rice, 3 cups of water, salt and close the pressure cooker.", "Pressure cook the Mint Coriander Spice Pulao for 2-3 whistles and turn off the flame.", "Allow the pressure to release naturally and then open the pressure cooker.", "Give the\u00a0Mint Coriander Spice Pulao a gentle stir and transfer to a serving bowl.Serve\u00a0Mint Coriander Spice Pulao Recipe along with\u00a0\u00a0Spinach Mushroom Chickpea Curry Recipe\u00a0or\u00a0Rajasthani Style Mutton Banjara Recipe,\u00a0Pickled Onions\u00a0followed by a dessert of\u00a0Shahi Tukda Gajar Halwa Shots With Rabri Recipe."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Mint_Coriander_Spice_Pulao_Recipe-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/229.Mint_Coriander_Spice_Pulao_Recipe-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Keerai Karamani Kuzhambu- Palak Lobia Curry Recipe', 'keerai-karamani-kuzhambu-palak-lobia-curry-recipe', 'If you are looking for a calcium rich recipe then you must make this tasty Palak Lobia Curry Recipe/ Keerai Karamani Kuzhambu. Cooked lobia or black eyed beans is simmered in a gravy made with dry roasted spices, coconut and tamarind paste. This curry tastes great with roti and rice.', '["1 tablespoon Coriander (Dhania) Seeds", "4 Dry Red Chillies", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Black pepper corns", "1/2 cup Fresh coconut", "30 grams Tamarind , soaked in water", "1 cup Black Eyed Beans (Lobia) , soaked for 4 hours", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coconut Oil", "1/4 cup Pearl onions (Sambar Onions) , quartered", "Salt , to taste", "100 grams Spinach Leaves (Palak) , roughly chopped", "1 teaspoon Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chilli", "2 sprig Curry leaves", "2 cloves Garlic , sliced"]'::jsonb, ARRAY['salt', 'coconut', 'mustard seeds', 'black pepper corns', 'spinach leaves (palak)', 'cloves garlic', 'dry red chilli', 'pearl onion (sambar onion)', 'curry leaves', 'dry red chillies', 'coriander (dhania) seeds', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'coconut oil', 'tamarind', 'turmeric powder', 'black eyed beans (lobia)']::text[], '["To begin making Palak Lobia Curry Recipe/\u00a0Keerai Karamani Kuzhambu prep all the ingredients and keep them ready.", "Soak lobia/ black eyed beans for 4 hours.", "Wash the palak and roughly chop them.Add lobia/ black eyed beans in a pressure cooker with two cups water and salt and turmeric, close the pressure cooker lid and pressure cook lobia/ black eyed beans for 5 whistles / 20 minutes until cooked completely.Roast all the ingredients - coriander seeds, cumin seeds, methi seeds, red chillies, black peppercorns in a pan till a nice aroma is released for about a minute.Add the coconut and roast for a few seconds.", "Turn off the heat and allow it to cool a bit.Once the coconut mixture is cooled add to a mixer grinder, along with the soaked tamarind and add just a little water and blend to make a smooth paste.", "Keep aside.Heat coconut oil in saucepan over medium heat; add the onion and saute for a minute until the onions soften. add the curry leaves and stir for a few more seconds.Add the coconut masala and the cooked black eyed beans and salt to taste.", "Add a little water and give the\u00a0Keerai Karamani Kuzhambu a brisk boil for about 3 to 4 minutes.", "Once done, check the salt and adjust to taste accordingly.", "Finally for the tadka, heat coconut in a pan over medium heat.", "Add the mustard seeds, curry leaves, red chillies and garlic.", "Allow the mustard seeds to crackle and the garlic to turn golden brown and turn off the heat.Transfer the\u00a0Palak Lobia Curry Recipe/\u00a0Keerai Karamani Kuzhambu to as sering bowl and pour the tadka over the kuzhambu and serve hot.Serve the Palak Lobia Curry Recipe/\u00a0Keerai Karamani Kuzhambu\u00a0with\u00a0Pavakkai Poriyal,\u00a0Drumstick Leaves Ragi Roti\u00a0and\u00a0Burani Raita\u00a0for a wholesome high protein diabetic friendly meal."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/palak_lobia_curry/Palak_Lobia_Curry_Recipe_Spinach_Blackeyed_Beans_Curry_11_1600_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/230.Palak_Lobia_Curry_Recipe_Spinach_Blackeyed_Beans_Curry_11_1600_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mushroom Caldine Recipe | Vegetarian Goan Mushroom Curry', 'mushroom-caldine-recipe-vegetarian-goan-mushroom-curry', 'Mushroom Caldine is delicious vegetarian coconut curry where the mushroom is cooked in coconut milk and tamarind with freshly ground masala. It makes a perfect light meal anytime with some buttered pav buns or goan pav on the side.', '["400 grams Button mushrooms", "1 cup Coconut milk", "1 Onion , finely chopped", "2 Green Chillies , slit", "5 Garlic , finely chopped", "1 inch Ginger , finely chopped", "1 teaspoon Salt , or to taste", "1 teaspoon Oil , for cooking", "1/2 cup Fresh coconut", "20 grams Tamarind", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Coriander (Dhania) Seeds", "4 Dry Red Chillies", "1/2 teaspoon Turmeric powder (Haldi)", "1/4 cup Water"]'::jsonb, ARRAY['salt', 'ginger', 'coconut', 'cumin (jeera) seeds', 'button mushrooms', 'water', 'coriander (dhania) seeds', 'garlic', 'onion', 'dry red chillies', 'coconut milk', 'tamarind', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Mushroom Caldine recipe, first prep and measure all the ingredients and keep them ready.", "In a small jar of the mixer grinder, add the coconut, red chillies, tamarind, coriander seeds, cumin seeds and turmeric powder.", "Add 1/4 cup of warm water and blend to make a smooth paste.Cut the mushrooms either into slices or halfs or you can leave them as whole.", "Its a personal choice of how you like your mushrooms.", "I like them sliced lengthwise.", "Heat oil in a pan; add the onion, garlic, ginger and green chillies.", "Saute until the onions are tender and lightly browned.Once the onions are lightly brown, add the tomatoes and saute for about a minute until it turns soft and mushy.", "Cover the pan to fasten the cooking process of the tomatoes.Once the tomatoes have softened, add the mushrooms and saute until the mushrooms are almost cooked.They will shrink in size and release water.", "At this stage, add the caldine masala paste, coconut milk and salt to taste.Give the mushroom caldine a brisk boil for about 3 minutes and turn off the heat.", "Check the taste and adjust the salt accordingly.Stir in chopped coriander leaves and transfer the\u00a0mushroom caldine\u00a0to a serving bowl and serve hot.Serve\u00a0Mushroom Caldine along with Toasted Buttered Pav Buns\u00a0or\u00a0Whole Wheat Laccha Paratha\u00a0for a quick simple delicious meal together."]'::jsonb, 25, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Mushroom_Caldine_Recipe___Vegetarian_Goan_Mushroom_Curry_11_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/231.Mushroom_Caldine_Recipe___Vegetarian_Goan_Mushroom_Curry_11_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Saag Tofu Recipe (Tofu Simmered in Spiced Mustard & Spinach Leaves)', 'saag-tofu-recipe-tofu-simmered-in-spiced-mustard-spinach-leaves', 'The Saag Tofu Recipe is a twist to the traditional Saag Paneer. Saag, is a spiced North Indian dish that is made from fresh greens, like mustard leaves and spinach leaves. The addition of garlic, and ginger along with garam masala brings out the flavors of the delicious and classic recipe.', '["250 grams Tofu , cut into cubes", "300 grams Spinach Leaves (Palak)", "300 grams Mustard greens", "2 inch Ginger", "4 Green Chillies , chopped", "1/4 cup Homemade tomato puree", "8 Garlic , minced", "1 teaspoon Cumin seeds (Jeera)", "Asafoetida (hing) , a pinch", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "Salt , to taste", "2 tablespoon Makki Ka Atta (Yellow Corn Meal Flour)", "3 Dry Red Chillies", "1 teaspoon Oil", "1 teaspoon Ghee", "Water , as required"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'makki ka atta (yellow corn meal flour)', 'asafoetida (hing)', 'ghee', 'spinach leaves (palak)', 'water', 'dry red chillies', 'garlic', 'mustard greens', 'cumin seeds (jeera)', 'tofu', 'turmeric powder', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the\u00a0Saag Tofu Recipe, we will first wash the green well in water.", "Chop both the greens and steam them in a steamer for 4 to 5 minutes or pressure cook them for a couple of whistles.", "If you plan to pressure cook in a pressure cooker, to make sure you turn off the heat after a couple of whistles and run the cooker under cold water to release the pressure immediately.", "Releasing the pressure immediately, helps retain the green color of the greens.", "Once the saag (mustard and spinach leaves) are cooked, cool them for a bit.", "Once cooled puree the cooked spinach and mustard (saag) in blender and set aside.Heat a teaspoon of oil in heavy bottomed pan over medium heat.", "Add the diced tofu and pan fry it until it turns golden brown in color.", "Once done, remove from the pan and keep it aside in a bowl.In the same pan, add a teaspoon of ghee and heat over medium heat.", "Add the red chilies, cumin and allow them to roast and crackle.", "Once they crackle, add in the asafoetida, garlic, green chiles and stir for a few seconds.Add the in the tomato puree, turmeric powder, \u00a0garam masala powder and bring the saag masala mixture to a brisk boil.", "Once it comes to a boil, add in the cooked and pureed saag. the corn meal and the pan fried tofu.", "Add the salt and stir.", "Simmer for about 5 minutes until the Saag Tofu thickens and absorbs all the spices.", "Check the salt and spices and adjust to suit your taste.Turn off the heat, transfer to a serving bowl and serve.", "Serve the Saag Tofu along with pickle onions and Tawa Paratha or Makki Roti for lunch or dinner."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Sapana_Behl/Vegan_Saag.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/232.Vegan_Saag.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Pachi Pulusu Recipe -Raw Tamarind Rasam', 'andhra-style-pachi-pulusu-recipe-raw-tamarind-rasam', 'Andhra Style Pachi Pulusu Recipe (Raw Tamarind Rasam Recipe) is a different way of creating a rasam that has been followed by the people from Andhra Pradesh and Telangana. This rasam is not heated and rather prepared directly with squeezed tamarind water, sliced onions, roasted green chilli, fresh coriander leaves. The rasam is a specialty in those places and it is made very spicy, and thin. Sometimes when there is a huge production of raw mango during the summer, the tamarind pulp is replaced by the stewed raw mango.', '["2 cups Tamarind Water", "1 Onions , sliced", "2 Green Chilli , smoked", "1 sprig Coriander (Dhania) Leaves", "1 teaspoon Jaggery", "Salt , to taste", "To temper", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves", "1 pinch Asafoetida (hing)", "2 Dry Red Chilli", "4 cloves Garlic , crushed", "Oil"]'::jsonb, ARRAY['s tamarind water', 'onions', 'reen chilli', 'coriander', 'dhania', 'jaggery', 'salt', 'to temper', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'curry leaves', 'asafoetida', 'hing', 'dry red chilli', 's garlic', 'oil']::text[], '["To begin making the Pachi Pulusu, we will first roast the chilies in a pan till it is completely roasted.", "Chop the chillies very finely and transfer it to a bowl.", "Add the tamarind water, coriander leaves, jaggery, onions and check for salt.", "Balance out the flavor by adding little jaggery if it is too tangy.Heat a small tempering pan with oil, add mustard seeds and cumin seeds and allow it splutter for 10 seconds.Add curry leaves, hing, red chillies, and crushed garlic and leave the curry leaves to crackle for 10 seconds.Pour this over the pulusu and serve.Serve the Pachi Pulusu Recipe along with\u00a0hot steamed rice,\u00a0palya, and\u00a0Gor Keri Recipe\u00a0by the side to relish your lunch meals."]'::jsonb, 15, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Andhra_Style_Pachi_Pulusu_Recipe_Raw_Tamarind_Rasam_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/233.Andhra_Style_Pachi_Pulusu_Recipe_Raw_Tamarind_Rasam_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bangalore Restaurant Style Sambar Recipe - For Idlis', 'bangalore-restaurant-style-sambar-recipe-for-idlis', 'This Sambar Recipe for Idlis is a Bangalore Restaurant Style Sambar that is usually served in restaurants along with Idli and Dosa. Like many dishes have various versions across geographical boundaries, the humble idli-sambhar is no different.', '["1/2 Cumin seeds (Jeera)", "2 teaspoons Coriander (Dhania) Seeds", "4 Byadagi Dried Chillies", "3 Guntur Dried Chillies", "1/3 cup Fresh coconut , grated", "1/2 cup Arhar dal (Split Toor Dal) , rinsed", "150 grams Shallots , chopped", "1 Onion , chopped", "2 Tomatoes , finely chopped", "8 Curry leaves", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Asafoetida (hing)", "2 teaspoons Coriander (Dhania) Seeds", "1 cup Tamarind Water , (lemon size tamarind soaked and extracted)", "1 tablespoon Jaggery , grated", "Salt , to taste", "Oil , as needed", "4 tablespoons Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['tomato', 'salt', 'guntur dried chillies', 'arhar dal (split toor dal)', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'coriander (dhania) leaves', 'jaggery', 'curry leaves', 'byadagi dried chillies', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'tamarind water (lemon tamarind cted)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making Bangalore Restaurant Style Sambar Recipe For Idlis, rinse the lentils and add it to the pressure cooker along with chopped onion, turmeric powder, 1 teaspoon of oil and enough water and pressure cook until the dal is completely soft. (mine took 2 whistles)Mash the onion and the dal with a masher and set this mixture aside.In a kadai, add a teaspoon of oil and roast lightly the cumin seeds, coriander seeds and both varieties of dry red chillies until fragrant.", "Be careful to do this on low flame since these can burn easily.Transfer this to a mixer jar along with the fresh coconut and grind this to a smooth paste using a little water.Heat some oil in a heavy bottoemd pan, add the mustard seeds and let them crackle.", "Add asafoetida, curry leaves and shallots.", "Saute the shallots until they start to pop and turn transparent, need not brown them.Add the ground paste and saute this mixture until for 2-3 minutes along with the onions.", "Tip in the chopped tomatoes and cook for 2-3 minutes. (They need to be mushy)Add the cooked dal mixture, salt, tamarind extract (reserve some and add depending on the sourness from tomatoes) and jaggery and bring it to a boil with 1-2 cups of water.", "Cook this for 8-10 minutes while stirring occassionally and adjust the seasoning if needed or till completely cooked and flavours even.Turn of the heat, add the coriander leaves and give it a mix.", "It is ready to be served.Serve\u00a0Bangalore Restaurant Style Sambar Recipe For Idlis with\u00a0Homemade Soft Idli Recipe,\u00a0Medu Vada Recipe\u00a0and\u00a0Coconut Chutney\u00a0for an indulging and nutritious breakfast."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/gauravi/Bangalore_Hotel_style_Sambhar.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/234.Bangalore_Hotel_style_Sambhar.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kathiyawadi Stuffed Onion Recipe', 'kathiyawadi-stuffed-onion-recipe', 'Kathiyawadi Stuffed Onion Recipe is a simple to make but at the same time pretty spicy and delicious. Kathiyawad is a region in Gujarat and its cuisine is pretty hot and spicy as compared to the Gujarati cuisine.', '["300 grams Pearl onions (Sambar Onions)", "3/4 cup Roasted Peanuts (Moongphali)", "10 cloves Garlic", "2 tablespoons Coriander Powder (Dhania)", "2 tablespoons Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Turmeric powder (Haldi)", "4 tablespoons Coriander (Dhania) Leaves , finely chopped", "2 teaspoons Oil , for the stuffing, and more to slow cook", "Salt , to taste"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'coriander (dhania) leaves', 'red chilli powder', 'cloves garlic', 'pearl onion (sambar onion)', 'peanuts (moongphali)', 'coriander powder', 'turmeric powder', 'sunflower oil the stuffing']::text[], '["To begin making\u00a0Kathiyawadi Stuffed Onion Recipe, peel the baby onions, keeping the base intact make 4 slits in the shape of a cross to help us fill the stuffing.", "Keep aside.For the stuffing, make a coarse dry mix of the roasted peanuts, garlic cloves, coriander powder, red chilli powder, cumin, turmeric and salt using a mixer grinder and transfer into a bowl.Now add the chopped coriander, about 2 teaspoons oil to the filling mixture and mix well till the mixture turns crumbly.Take the baby onions and carefully fill in the ground mixture into the slits of each one of them.Heat oil in a non stick pan on medium flame, place the stuffed onions on the surface of the pan and let it cook on low heat for 5 minutes.Add about 1/4 cup of water, add the remaining stuffing mix, close it with a lid and let the onions cook in the steam.", "This will take about 10 minutes.Saute sparingly if required in between.", "Make sure the onions are cooked well while still retaining its shape.Once the onions are cooked, switch off the heat and garnish\u00a0Kathiyawadi Stuffed Onion with coriander leaves.Serve the\u00a0Kathiyawadi Stuffed Onion Recipe along with\u00a0Methi Jowar Roti Recipe\u00a0and\u00a0Gujarati Dal Recipe\u00a0for a delightful weeknight dinner."]'::jsonb, 30, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/dec/Kathiyawadi_Stuffed_Onion_Recipe-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/235.Kathiyawadi_Stuffed_Onion_Recipe-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Authentic Punjabi Mango Pickle (With Mustard Oil) - No Sun Required Aam Ka Achar', 'authentic-punjabi-mango-pickle-with-mustard-oil-no-sun-required-aam-ka-achar', 'Here is an authentic Punjabi Mango Pickle recipe also known as Aam Ka Achaar is simple recipe of a spicy raw mango pickle made from homemade pickle masala. Pickle-making process can be a very easy task, if you have the right guidance and the perfect recipe.', '["2 kg Mango (Raw) , approx 7 cups", "1/2 cup Salt , approx 130 grams", "3 tablespoons Turmeric powder (Haldi) , 30 grams approx", "1/2 cup Kashmiri Red Chilli Powder , 40 grams approx", "1/4 cup Methi Seeds (Fenugreek Seeds) , 40 grams approx", "1/4 cup Mustard seeds (Rai/ Kadugu) , 40 grams approx", "3 tablespoons Red Chilli powder , (adjust)", "1/4 cup Kalonji (Onion Nigella Seeds) , 35 grams approx", "1/4 cup Fennel seeds (Saunf) , 35 grams approx", "1/4 cup Coriander (Dhania) Seeds , 25 grams approx", "3 cups Mustard oil"]'::jsonb, ARRAY['mango', 'raw', 'salt', 's turmeric powder', 'haldi', 'kashmiri red chilli powder', 'methi seeds', 'fenugreek seeds', 'mustard seeds', 'rai/ kadugu', 's red chilli powder', 'kalonji', 'onion nigella seeds', 'fennel seeds', 'saunf', 'coriander', 'dhania', 's mustard oil']::text[], '["To begin making the\u00a0 Punjabi Mango Pickle recipe (Aam Ka Achaar Recipe), wash the mangoes and dry them completely making sure there is no moisture or dust.Make sure your knife and the platform you use for cutting the mangoes is clean and moisture free.", "Cut the mangoes in half, deseed and further cut them into one inch cubes.", "You can leave the skin on provided they are tender and smooth.", "In a large steel bowl, combine the salt, turmeric powder and cut mangoes.", "Cover, the bowl and allow it to marinate for 1 hour.Heat a small pan on medium heat, and roast the coriander seeds until you start smelling the aroma.", "Turn off heat and allow it to cool.", "Once cooled, using a pestle and mortar to coarsely crush the coriander seeds to half.Blend the mustard seeds and fenugreek seeds into a coarse powder.", "There is no need to roast the seeds.To the marinated mangoes, add the powdered mustard and fenugreek seeds, red chilli powder, fennel seeds, kalonji seeds, and coriander seeds.", "Stir well to combine.Add 1 cup of mustard oil and stir well again.", "You don''t need to heat the mustard oil.", "Check the salt at this stage.", "It should feel extra salt.", "If it is not extra salty, add a few tablespoon of salt until you get that extra salty taste.", "Salt and oil are the two most important preservatives in pickling.", "Cover the steel bowl with a muslin cloth and tie it tightly around the rim.", "This will absorb any residual moisture.", "Place a steel lid over the covered bowl and set aside.After 24 hours, open and give it a stir.", "Cover again with cloth wrapped tightly and a lid and set it to rest for another day.", "The third day you will notice the mangoes have softened.", "At this stage add the remaining 2 cups of mustard oil.", "Give it a stir.", "Once again cover tightly with muslin cloth and a steel lid.", "Keep it aside for 2 more days.", "Give it a stir.By the end of 5th day the pickle will be ready to eat.", "The mangoes would have softened but might still have a firm texture.", "The mangoes will keep marinating and softening when it is stored in bottles and will age with time.", "Moisture is the biggest killer for pickles.", "Clean and sterilize the bottles and the lids that you will be using for storage.", "I typically like to store them in multiple small 500 gram glass bottles, so I only open the bottle when i am ready to use it.Transfer the Punjabi Mango Pickle into the clean and dry bottles.", "Add a tablespoon of mustard oil on the top once filled and seal the bottle tight and enjoy.Use a clean dry spoon so that there is no moisture when you take the pickle out of the bottle.Serve Punjabi Mango Pickle\u00a0 with\u00a0Pyaz Ka Paratha Recipe\u00a0or\u00a0Aloo Methi Paratha Recipe\u00a0for a\u00a0 complete breakfast."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2022/Authentic_Punjabi_Mango_Picke_In_Mustard_Oil_No_Sun_Method_7_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/236.Authentic_Punjabi_Mango_Picke_In_Mustard_Oil_No_Sun_Method_7_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mooli Ka Saag & Moong Dal Ki Sabzi (Dry) - Radish Leaves & Lentil Stir fry', 'mooli-ka-saag-moong-dal-ki-sabzi-dry-radish-leaves-lentil-stir-fry', 'The Mooli Ka Saag & Moong Dal Ki Sabzi is a nutritious and healthy stir fry vegetable that is made with the greens of radish together with moong dal. The dish is cooked with less oil and has a perfect blend of spices and can be served as side dish along with hot steamed rice or even roti.', '["150 grams Mooli Ke Patte (Radish Greens) , finely chopped", "1/4 cup Yellow Moong Dal (Split)", "1 teaspoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "3 cloves Garlic , finely chopped", "1 Green Chilli , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "2 tablespoons Fresh coconut , grated", "1/2 teaspoon Sugar"]'::jsonb, ARRAY['s mooli ke patte', 'radish greens', 'yellow moong dal', 'split', 'oil', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 's garlic', 'reen chilli', 'turmeric powder', 'haldi', 'salt', 's fresh coconut', 'sugar']::text[], '["To begin making the\u00a0Mooli Ka Saag & Moong Dal Ki Sabzi, first prep the ingredients according to the instructions and keep aside.Soak the moong dal for about half an hour in warm water.", "Once soaked, drain the water and keep aside.Heat oil in a heavy bottomed pan or a kadai\u00a0on medium heat.", "Add the mustard and cumin and allow it to crackle,Once they crackle, add the chopped garlic and green chilies.", "Stir fry for a few seconds until you smell the aromas coming through.", "After a few seconds, add the chopped mooli ka saag (radish leaves), soaked dal, salt, sugar and turmeric powder.", "Stir all the ingredients well.", "Sprinkle just a little water, cover the pan and cook the radish leaves and the dal until well done.", "Keep stirring in between to make sure they get cooked evenly.", "Once done, turn off the heat, check the salt and spice levels and adjust to suit your taste.", "Finally stir in the the grated coconut and serve.Serve the\u00a0Mooli Ka Saag & Moong Dal Ki Sabzi along with\u00a0Phulka,\u00a0Aloo Tuk\u00a0and\u00a0Carrot Tomato Salad\u00a0for a wholesome weeknight dinner."]'::jsonb, 70, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Babitha_Costa/Radish_Leaves_Stir_fry__Radish_leavesmoongdal_stir_fry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/237.Radish_Leaves_Stir_fry__Radish_leavesmoongdal_stir_fry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Orange Peels Curry Recipe', 'karnataka-style-orange-peels-curry-recipe', 'Did you know that we can make a yummy curry out of Orange Peels? It is tangy, sweetish, spicy, slightly bitter and bursting with flavors. It is an unique recipe. So next time you have some guests at home, make this recipe and impress your friends and family. It is filled with flavours and tastes delicious with almost everything. Next time you eat an orange, don''t throw the peels, make a curry out of it.', '["2 Orange", "Tamarind , big lemon size", "3 tablespoon Jaggery , adjustable", "1 teaspoon Rasam Powder", "1 teaspoon Red Chilli powder", "1 tablespoon Rice flour", "Salt , to taste", "1 tablespoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon White Urad Dal (Split)", "1 Dry Red Chilli , broken", "1 Green Chilli , slit", "Asafoetida (hing) , a pinch", "1/4 teaspoon Turmeric powder (Haldi)"]'::jsonb, ARRAY['salt', 'orange', 'sunflower oil', 'green chilli', 'mustard seeds', 'asafoetida (hing)', 'jaggery', 'red chilli powder', 'dry red chilli', 'white urad dal (split)', 'cumin seeds (jeera)', 'rasam powder', 'methi seeds (fenugreek seeds)', 'rice flour', 'turmeric powder', 'tamarind lemon']::text[], '["To begin making the Karnataka Style Orange Peels Curry recipe, Peel out 2 oranges.", "Gently scrape the white region from the orange peel using a spoon.", "Remove as much as possible as this will reduce the bitterness .Chop the orange peels finely.Soak tamarind in water.", "After it''s soaked well, squeeze out tamarind water and keep aside.Heat oil in a heavy bottomed pan and temper with mustard seeds, urad dal, cumin seeds & fenugreek seeds.", "When it splutters add curry leaves, red chilli powder, green chilli, hing and turmeric powder.", "Mix and add chopped orange peel.", "Fry for 4-5 minutes.Later add tamarind water, salt, jaggery, red chilli powder and rasam powder.", "Add some water and close the lid.", "Keep the flame on low medium and allow the peel to cook well.", "Mix in between.Meanwhile\u00a0 in a mixing bowl, mix rice flour in water such that no lumps are formed.When orange peels are cooked well, add the rice flour mix to the curry and allow it to boil for 1-2 minutes.", "Adding rice flour gives nice thickness to the gravy.", "If the desired consistency is attained, switch off.Serve\u00a0Karnataka Style Orange Peels Curry along with\u00a0Cabbage Thoran\u00a0and\u00a0Whole Wheat Lachha Paratha\u00a0for your weekday meal.", "It even tastes great with\u00a0Steamed Rice."]'::jsonb, 30, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/Karnataka_style_Orange_Peels_Curry_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/238.Karnataka_style_Orange_Peels_Curry_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ayala Fish Fry Recipe', 'ayala-fish-fry-recipe', 'Ayala also called as bangada is one of the tastiest fish of the whole lot. The buttery flesh makes it a great fish to fry it. Not that the curry made of this fish is less delicious, no matter how you cook this fish, it’s super delicious.', '["4 Fish , ayala (bangada fish)", "1-1/2 tablespoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Fennel Powder", "1 teaspoon Black pepper powder", "1 teaspoon Ginger Garlic Paste", "1 teaspoon Lemon juice", "Salt , to taste", "Oil , for shallow fry"]'::jsonb, ARRAY['salt', 'fish ayala (bangada fish)', 'red chilli powder', 'ginger garlic paste', 'fennel powder', 'lemon', 'black pepper powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Ayala Fish Fry Recipe, wash and clean fish well.", "Leave it whole.", "Score the fish on it\u2019s skin on both sides.In a bowl squeeze lime juice.", "Add red chilli powder, turmeric powder, fennel powder, black pepper powder, ginger-garlic paste, salt and mix well.", "Make a thick paste.Rub the spice paste all over the fish including the slit areas on both the sides.Cover and let the fish marinate in the fridge for 15 minutes.Heat few tablespoons oil in a pan.", "Shallow fry the whole fish\u00a0on medium flame\u00a0until golden brown\u00a0on both sides.Serve hot with lime wedges and onion carrot slices if preferred.Serve\u00a0Ayala Fish Fry with\u00a0Mixed Vegetable Sambar,\u00a0Steamed Rice\u00a0and\u00a0Elai Vadam\u00a0for a weekday lunch or dinner."]'::jsonb, 35, 'South Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/Ayala_Fish_Fry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/239.Ayala_Fish_Fry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kongunadu Style Senai Kilangu Masala Recipe - Yam in Spicy Gravy', 'kongunadu-style-senai-kilangu-masala-recipe-yam-in-spicy-gravy', 'Kongunadu Style Senai Kilangu Masala Recipe (Yam in Spicy Gravy) is a recipe that is from Tamil Nadu. Kongunadu is a part of Tamil Nadu cuisine which is famous for its spicy flavor. In this recipe we have used different spice mixtures that are roasted well and ground into a spicy paste and cooked along with yam.', '["300 grams Elephant yam (Suran/Senai/Ratalu) , sking peeled and sliced thin", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "Salt , to taste", "Oil , for cooking", "1 inch Cinnamon Stick (Dalchini)", "4 cloves Garlic", "1 inch Ginger , chopped", "2 tablespoon Poppy seeds", "2 tablespoon Coconut Oil", "2 Dry Red Chillies", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'ginger', 'mustard seeds', 'elephant yam (suransenairatalu) sking', 'cloves garlic', 'curry leaves', 'dry red chillies', 'cinnamon stick (dalchini)', 'poppy seeds', 'coconut oil', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Kongunadu Style Senai Kilangu Masala Recipe, we will first pressure cook the yam with water, turmeric powder, salt for about 2 whistle.Release the pressure naturally, and drain the excess water and keep the cooked yam aside.Heat a flat skillet with oil, add curry leaves and allow it splutter for few seconds, add cinnamon stick, cloves and let it saute for few seconds.Add dry red chillies, garlic, and ginger and saute until it softens.", "Later add poppy seeds and grated coconut and saute until they turn light brown.Switch off the heat and allow it to cool down.", "Transfer it to a mixing jar and add little water and grind it into a smooth paste.Heat the same pan again with oil, add mustard seeds and curry leaves and allow it splutter and crackle for few seconds.Add your ground paste and give it a stir.", "Finally add cooked yam and mix the masalas well.", "Cook until the masala has reduced and you get a dry mixture.Check for salt and adjust the seasoning according to your palate and serve hot.Serve the\u00a0Kongunadu Style Senai Kilangu Masala Recipe\u00a0along with\u00a0Tawa Paratha,\u00a0Palak Dal\u00a0and\u00a0Steamed rice\u00a0to enjoy your everyday lunch."]'::jsonb, 40, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Kongunadu_Style_Senai_Kilangu_Masala_Recipe_Yam_in_Spicy_Gravy.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/240.Kongunadu_Style_Senai_Kilangu_Masala_Recipe_Yam_in_Spicy_Gravy.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Shahi Egg Curry Recipe In Tomato & Cashew Gravy', 'shahi-egg-curry-recipe-in-tomato-cashew-gravy', 'The taste of Dhaba food is phenomenal and we usually find these dhabas on highways. They cook some amazing dishes in traditional style which enhances the flavour of the dish. Dhaba Style Egg Curry is one such recipes which is spicy, tasty and full of flavours.', '["4 Whole Eggs", "1-1/2 cups Homemade tomato puree", "2 Onions , finely chopped", "6 cloves Garlic", "1 inch Ginger", "1 Bay leaf (tej patta)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "1/4 cup Cashew nuts , ground into paste", "Extra Virgin Olive Oil , for cooking", "2 Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'bay leaf (tej patta)', 'red chilli powder', 'cloves garlic', 'figaro pure olive oil', 'cashew nuts ground paste', 'onion', 'eggs', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'garam masala powder']::text[], '["To begin making the Shahi Egg Curry Recipe, prep all the ingredients and keep them ready, hard boil the eggs, prepare the make the tomato puree.", "Follow - How To Make Tomato PureeInto a pestle and mortar, add the ginger and garlic and pound to make a coarse mixture.Into a pan, add in the olive oil, add the onions, pounded ginger and garlic and saute for a few seconds until the onions have softened.", "Take care not to caramelize the onions.", "Once the onions have softened, add in the tomato puree, bay leaf, turmeric powder, red chili powder and garam masala powder.Stir in the cashew nut paste and the boiled eggs.", "Cover the pan and simmer for about 5 to 10 minutes until the masalas come together to make a delicious egg curry.Once done, stir in the kasuri methi into the Shahi Egg Curry and serve.Serve this\u00a0Shahi Egg Curry Recipe\u00a0along with\u00a0Hyderabadi Vegetable Biryani\u00a0or\u00a0Pudina Lahsun Laccha Paratha\u00a0and\u00a0Burani Raita\u00a0for your weekend meal."]'::jsonb, 90, 'North Indian', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/0-Archana/3-Egg_Curry_Recipe_Figaro_Pure_Olive_Oil-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/241.3-Egg_Curry_Recipe_Figaro_Pure_Olive_Oil-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kaju Butter Masala Recipe', 'kaju-butter-masala-recipe', 'Paneer Butter Masala or Chicken Butter Masala are the dishes we usually prepare for any special occasions. Kaju Butter Masala is an amazing twist to the Butter Masala recipe, where the roasted whole cashews are added.', '["1 cup Cashew nuts", "4 Tomatoes", "1 tablespoon Ginger Garlic Paste", "1 Green Chilli , slit", "1 teaspoon Kashmiri Red Chilli Powder", "1 teaspoon Garam masala powder", "1 Bay leaf (tej patta)", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves) , crushed for garnish", "3 tablespoons Fresh cream", "1 tablespoon Butter (Salted)", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'kashmiri red chilli powder', 'green chilli', 'bay leaf (tej patta)', 'ginger garlic paste', 'cashews', 'kasuri methi (dried fenugreek leaves)', 'butter', 'garam masala powder']::text[], '["To begin making Kaju Butter Masala Recipe, wash and blanch the tomatoes in enough water, once cool, remove the skin and make a smooth paste along with 8 cashews using a mixer grinder.", "Keep aside.Heat butter in a heavy bottomed pan, add the whole cashews and fry until they turn golden and remove them into a plate.", "Keep aside until further use.To the same pan add the bay leaf, ginger garlic paste and saute for a minute.", "Add the tomato cashew puree, green chilli and cook for 2 minutes.Add the red chilli powder, 2 cups water, season with salt and let it simmer for 5 minutes until the gravy becomes thick and comes together.Add the fried cashews, garam masala powder and simmer for 5 minutes so that the cashews become a little soft.Add the cream and mix well.", "Simmer for another 2 minutes and switch off the heat.Slightly crush the kasuri methi between your palms and add it as a garnish over the prepared Kaju Butter Masala.Serve the\u00a0Kaju Butter Masala Recipe, along with\u00a0Butter Naan,\u00a0Tandoori Aloo, Salad for a delicious Weekend Lunch."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Kaju_Butter_Masala.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/242.Kaju_Butter_Masala.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chenakayi Erissery Recipe - Yam Erissery', 'chenakayi-erissery-recipe-yam-erissery', 'Erissery is one of the famous dish from Kerala cuisine and an integral part of any Onam Sadya. The base of the erissery is a blend with fresh coconut, cumin, pepper, and chillies.', '["2 cups Elephant yam (Suran/Senai/Ratalu) , scraped well and cubed to bite size", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 cup Fresh coconut , grated", "3 Green Chillies , (adjust)", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Whole Black Peppercorns", "1 teaspoons Coconut Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'coconut', 'mustard seeds', 'black peppercorns', 'curry leaves', 'cumin seeds (jeera)', 'coconut oil', 'elephant yam (suransenairatalu) scraped', 'turmeric powder', 'green chillies']::text[], '["To begin making the Chenakayi Erissery Recipe, prepare all the ingredients required to make this dish.Take a heavy bottomed pan, add yam along with little water, turmeric and salt.", "Cover the pan and cook till it becomes soft.Meanwhile, prepare the masala.", "Take half of the coconut mentioned along with cumin, pepper, green chilli and grind to a coarse paste adding 2-3 tablespoon of water.", "Keep it aside.When the yam pieces are cooked well, mash them lightly using the back of the ladle.To the semi-mashed yam pieces, add the ground masala, salt and sprinkle a\u00a0little water (if the water added initially has dried out).", "Mix everything well.", "Keep the flame on low and cover and cook for 4-5 minutes so that all the flavors are infused.", "Meanwhile, heat another pan and toast the coconut on low flame until golden brown.", "Keep aside.", "Next, Prepare the tempering.", "Add coconut oil.", "When it is hot, add mustard seeds.", "Once they splutter, add curry leaves and switch off.", "Finally, mix both the roasted coconut and tempering to the Yam erissery and gently give a stir.", "Reserve a little amount of roasted coconut for garnish.Garnish with roasted coconut and serve\u00a0Chenakayi Erissery Recipe along with\u00a0Steamed Rice,\u00a0Malabari Parotta\u00a0and\u00a0Kerala Kadala Curry Recipe."]'::jsonb, 30, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha_Kalluraya/Chenakayi_Erissery_Yam_Erissery.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/243.Chenakayi_Erissery_Yam_Erissery.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lauki Wadi Tarkari Recipe - Bengali Style Moong Dal Dumplings & Bottle Gourd Sabzi', 'lauki-wadi-tarkari-recipe-bengali-style-moong-dal-dumplings-bottle-gourd-sabzi', 'Lauki Wadi Tarkari Recipe is the Bengali Style Moong Dal Dumplings & Bottle Gourd Sabzi that is cooked as a side dish to pair with rice or Indian flat breads. I have used the homemade sun dried badi made with moong dal to prepare this sabzi, and then deep fried them before making the tarkari.', '["1 cup Yellow Moong Dal (Split) , soaked for at least 4 hours or overnight", "1 teaspoon Ginger , grated", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Red Chilli powder", "1 pinch Asafoetida (hing)", "Salt , to taste", "Other Ingredients", "1 Bottle gourd (lauki) , cut in cubes", "1 Tomato , chopped", "1 Onion , chopped", "2 Green Chillies , chopped", "1 teaspoon Ginger , grated", "1 teaspoon Panch Phoran Masala", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "1 teaspoon Sugar", "1 tablespoon Mustard oil", "2 tablespoons Oil , to fry wadis", "Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'mustard oil', 'asafoetida (hing)', 'sunflower oil wadis', 'coriander (dhania) leaves', 'red chilli powder', 'sugar', 'onion', 'cumin seeds (jeera)', 'bottle gourd (lauki)', 'panch phoran masala', 'coriander powder', 'turmeric powder', 'green chillies', 'yellow moong dal (split) least']::text[], '["To begin making Lauki Wadi Tarkari Recipe\u00a0, prepare wadis first.", "Wash and soak moong dal in enough water for about 3-4 hours or overnight.Drain excess water and pulse it a couple of times to make a fine paste in a food processor.Add the remaining ingredients listed under wadi like the ginger, cumin seeds, dry red chillies, hing, salt to taste and whisk to combine.", "Arrange a baking tray with aluminium foil or lined with a parchment paper.Using a piping bag or zip lock bag, drop out small roundels.Dry them under the sunlight for 3-4 days or until they are completely dried.", "Store in an airtight container and use them when needed.", "This can be stored up to 6 months.*For Lauki Wadi/Badi TarkariOnce you have the homemade or store bought wadis, heat oil for frying in a pan and saute the wadis.", "Drain on a kitchen towel to absorb excess oil.", "Keep them aside.Heat oil in a pan and add panch phoran masala on a low heat.", "Saute for few seconds and then add ginger and onions.", "Stir until the onions are light brown.Now add green chillies and tomatoes, stir and add turmeric powder, salt and sugar.", "Stir well on a medium heat to cook tomatoes.Once the tomatoes are soft and mushy, add in lauki and cook covered until lauki is soft.", "Mine took about 10 minutes.Add crushed or whole wadis,stir to combine and cook for few minutes more.Remove\u00a0Lauki Wadi Tarkari from heat and put it into a serving bowl, garnish with chopped coriander leaves.", "Serve hot.Serve\u00a0Lauki Wadi Tarkari Recipe\u00a0along with\u00a0Pudina Lahsun Laccha Paratha\u00a0and\u00a0Mooli Raita Recipe\u00a0for your everyday meals."]'::jsonb, 35, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sapanabehl/Bari_Lau_Tarkari.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/244.Bari_Lau_Tarkari.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Sandige Huli Recipe (Toor dal dumplings in Gravy Recipe)', 'karnataka-style-sandige-huli-recipe-toor-dal-dumplings-in-gravy-recipe', 'Karnataka Style Sandige Huli Recipe (Toor dal dumplings in Gravy Recipe) is a high rich protein dish. It is a dal curry made with toor dal without any vegetables. The toor dal is ground and mixed with fresh coconut and coriander leaves, which is shaped into balls and simmered with the same toor dal curry. This dish is famous among the “Madhwa Brahmin” community and is prepared traditionally on “Devara samaradhane” gathering.', '["1 cup Arhar dal (Split Toor Dal)", "2 Green Chilli , chopped", "2 tablespoon Fresh coconut , grated", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Jaggery", "1/2 cup Tamarind Water", "1 teaspoon Asafoetida (hing)", "Salt , to taste", "To temper", "1 teaspoon White Urad Dal (Split)", "2 cloves Garlic , chopped", "1 sprig Curry leaves", "1 tablespoon Ghee"]'::jsonb, ARRAY['salt', 'arhar dal (split toor dal)', 'green chilli', 'tamarind water', 'coconut', 'asafoetida (hing)', 'ghee', 'jaggery', 'cloves garlic', 'curry leaves', 'white urad dal (split)', 'turmeric powder']::text[], '["To begin preparing Karnataka Style Sandige Huli Recipe, soak the dal in water for at least 3 hours and keep it.", "In a grinder add the dal without water and green chili to a coarse paste.", "Take more than half of the mixture and keep it aside in a bowl.Add some more water into the mixer and grind the mixture to a smooth paste and reserve for later use.To the coarsely ground dal mixture, add coconut grated, chopped coriander leaves hing, turmeric and mix well.Heat a kadai with oil, add mustard seeds allow it splutter for 10 seconds.", "Add the mixed toor dal mixture and keep saut\u00e9ing for 2 minutes.", "Switch off the heat, allow it to rest for some time and start shaping them into balls.Heat a sauce pan with ghee, add mustard seeds and allow it to splutter for 10 seconds.Add the smoothly ground dal mixture, with chopped coriander, jaggery, tamarind water, salt and turmeric powder.You can add some more water to make the consistency thin.", "Check for salt and add the dumplings into the dal mixture.", "Allow it to boil for 10 minutes and switch off the heat.To temper, heat a small tempering kadai with oil and add the urad dal, garlic and saute until they become light brown.", "Add curry leaves and let it splutter and immediately pour it over the dal and serve.", "Serve the Sandige Huli Recipe along with hot steamed rice,\u00a0palya\u00a0and\u00a0Crispy Palak Pakora Recipe\u00a0to complete your rich meal."]'::jsonb, 230, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Karnataka_Style_Sandige_Huli_Recipe_Toor_dal_dumplings_in_Gravy_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/245.Karnataka_Style_Sandige_Huli_Recipe_Toor_dal_dumplings_in_Gravy_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Avarekalu Pulao Recipe - Avarekalu Pulao', 'karnataka-style-avarekalu-pulao-recipe-avarekalu-pulao', 'Avarekalu Pulao Recipe is a spicy Karnataka Style Pulao made using the fresh avarekalu or hyacinth beans. Hyacinth Beans are called the Avarekalu in Kannada. Avarekalu are seasonal beans, available in the winter months and many dishes are made using it.', '["1-1/2 cups Basmati rice , soaked for 10 minutes", "3/4 cup Avarekalu / Lilva Beans", "1 Onion , thinly sliced", "1 Tomato , finely chopped", "2 teaspoons Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 Bay leaf (tej patta)", "1 Cinnamon Stick (Dalchini)", "2 Green Chillies , slit", "1 tablespoon Ghee", "Salt , to taste", "2 sprig Mint Leaves (Pudina) , for garnish", "Ingredients for the masala paste", "1 Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "1 Cardamom (Elaichi) Pods/Seeds", "8 cloves Garlic", "2 inch Ginger", "1 Green Chilli", "1/2 cup Mint Leaves (Pudina)", "1/4 cup Coriander (Dhania) Leaves"]'::jsonb, ARRAY['s basmati rice', 'avarekalu / lilva beans', 'onion', 'tomato', 's coriander powder', 'dhania', 'red chilli powder', 'garam masala powder', 'bay leaf', 'tej patta', 'cinnamon stick', 'dalchini', 'reen chillies', 'ghee', 'salt', 'mint leaves', 'pudina', 'ingredients for the masala paste', 'laung', 'cardamom', 'elaichi', 's garlic', 'ginger', 'reen chilli', 'coriander']::text[], '["To begin making\u00a0Avarekalu Pulao Recipe-Hyacinth Beans Pulao, wash and soak the basmati rice in enough water for 10 minutes.Now, add all the ingredients mentioned for making the masala paste including cinnamon stick, clove, cardamom, garlic, ginger, green chilli, mint leaves, coriander leaves, and grind it into a smooth paste adding little water using a mixer grinder.", "Keep it aside.Heat ghee in a pressure pan, add the bay leaf, cinnamon stick and let the ghee become aromatic.Add the sliced onion and saute until it turns slightly brown.Add the slit green chillies, tomatoes and saute until the tomatoes turn a little soft.Add the ground masala paste, saute until the raw smell goes away.", "This will take about 3 to 4 minutes.After 3 to 4 minutes, add the coriander powder, red chilli powder, garam masala powder and saute until the ghee separates out.", "This will again take some 3 to 4 minutes.Now, add the fresh avarekalu or hyacinth beans, saute for 2 minutes.", "Drain the water from the rice, add it to the pan and mix well.Add 3 cups of water, season with salt and bring the\u00a0Avarekalu Pulao to a rolling boil.Now, close the\u00a0Avarekalu Pulao\u00a0with the lid, and pressure cook for one whistle on medium heat, switch off the heat and let the pressure release on its own.Once the pressure is fully released, open the lid, add the chopped mint leaves, fluff up the Avarekalu Pulao gently using a fork and it is ready to be served.Serve\u00a0Avarekalu Pulao Recipe\u00a0along with\u00a0Tomato Onion Cucumber Raita,\u00a0Satvik Carrot Sprout Salad\u00a0and a roasted\u00a0Papad\u00a0for a weekday dinner.", "You can also pack this easy Pulao Recipe in your Lunch Box."]'::jsonb, 30, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Avarekalu_Pulao_Recipe_Karnataka_Style_Hyacinth_Beans_Pulao.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/246.Avarekalu_Pulao_Recipe_Karnataka_Style_Hyacinth_Beans_Pulao.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tofu Green Pulao Recipe', 'tofu-green-pulao-recipe', 'Tofu Green Pulao Recipe is a nutritious dish with green leafy vegetables and goodness of tofu. The pulao gets a new flavor with the richness of tofu and makes it even more tastier with spinach in it.', '["1 cup Spinach Leaves (Palak) , finely chopped", "1 cup Methi Leaves (Fenugreek Leaves) , finely chopped", "1/2 cup Coriander (Dhania) Leaves , finely chopped", "1/2 cup Mint Leaves (Pudina) , finely chopped", "1/2 cup Spring Onion Greens , finely chopped", "1/2 cup Green peas (Matar)", "12 Green Bell Pepper (Capsicum) , finely chopped", "1/2 cup Green beans (French Beans) , finely chopped", "1/2 cup Tofu , cut into cubes", "4 Green Chillies , finely chopped", "1/4 teaspoon Cumin seeds (Jeera)", "1 tablespoon Ghee", "Oil , as required", "2 inch Cinnamon Stick (Dalchini)", "2 Black cardamom (Badi Elaichi)", "4 Cardamom (Elaichi) Pods/Seeds", "6 Cloves (Laung)", "2 Bay leaves (tej patta)", "1 tablespoon Cashew nuts , halved", "1 cup Basmati rice", "Salt , to taste"]'::jsonb, ARRAY['basmati rice', 'spring onion greens', 'coriander (dhania) leaves', 'cumin seeds (jeera)', 'green chillies', 'spinach leaves (palak)', 'sunflower oil', 'black cardamom (badi elaichi)', 'salt', 'cardamom (elaichi) podsseeds', 'tofu', 'mint leaves (pudina)', 'green beans (french beans)', 'cashew nuts', 'bay leaves (tej patta)', 'ghee', 'methi leaves (fenugreek leaves)', 'green peas (matar)', 'cinnamon stick (dalchini)', 'green bell pepper (capsicum)', 'cloves (laung)']::text[], '["To begin with the Tofu Green Pulao Recipe, first wash and soak basmati rice for 30 minutes and then strain the water using muslin cloth and keep it aside.Meanwhile in a blender combine spinach leaves, methi leaves, coriander leaves, green chillies and blend till it forms a smooth puree.Add oil and ghee in a\u00a0pressure cooker, once hot; add cumin seeds, bay leaves, black cardamom, cloves, green cardamom, cinnamon stick.After they begin to roast, add tofu cubes, cashew and fry for about 20 seconds.Now add capsicum, green peas, french beans, finely chopped spring onions and soaked double beans.", "After a while add in the basmati rice and stir fry for a minute.Add the prepared green puree and let it cook for a minute.", "Add 2 to 3 cups of water and mix everything well.Close the cooker with a lid and let it cook till the cooker release 2 to 3 whistles.", "Once done, let the pressure release normally.Open the lid, servie it in a bowl and garnish it with chopped coriander leaves.This\u00a0Tofu Green Pulao\u00a0can be served with\u00a0Burani Raita\u00a0or any other raita of your choice for your weekday lunch or dinner."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jamuna_Devi/Tofu_Green_Pulao_One_Dish_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/247.Tofu_Green_Pulao_One_Dish_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kurkuri Bhindi With Spicy Tomato Yogurt Gravy Recipe', 'kurkuri-bhindi-with-spicy-tomato-yogurt-gravy-recipe', 'Kurkuri Bhindi With Spicy Tomato Yogurt Gravy is a lip smacking side dish which can be served with any dal or kadhi for a wholesome meal. It is spicy, tangy and the crispy bhindi in it adds to the taste and flavour.', '["250 grams Bhindi (Lady Finger/Okra)", "Oil , for deep frying", "2 tablespoons Gram flour (besan)", "Salt , as needed", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Chaat Masala Powder", "1 tablespoon Water", "Oil , as required", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "1 tablespoon Ginger Garlic Paste", "1 to 2 Green Chillies , finely chopped", "1 Onion , thinly sliced", "1/2 cup Curd (Dahi / Yogurt) , whisked", "1 Tomato , finely chopped", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)"]'::jsonb, ARRAY['tomato', 'salt', 'mustard seeds', 'asafoetida (hing)', 'chaat masala powder', 'red chilli powder', 'water', 'gram flour (besan)', 'ginger garlic paste', 'curd', 'onion', 'cumin seeds (jeera)', 'bhindi (lady fingerokra)', 'coriander powder', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Kurkuri Bhindi With Spicy Tomato Yogurt Gravy, firstly we will make the crispy bhindi.Wash the bhindi, make a cut, take out the seeds and then thinly slice all of the bhindis.Take a mixing bowl, add the bhindi and all the ingredients mentioned under \u2018for the crispy bhindi\u2019.Heat oil in a deep frying pan, and deep fry the bhindi till they become crisp.", "Take them out on a absorbent paper to absorb the excess oil.Once done, keep them aside.Next heat oil in a heavy bottomed pan and add mustard seeds, cumin seeds, hing and ginger garlic paste.After 30 seconds, add the green chillies and onions.", "Cook till the onions becomes soft and translucent.Next, add the tomatoes and cook for about 3 minutes or till the tomatoes gets mushy.Add all the dry masalas including red chilli powder, turmeric powder, salt and coriander powder.Cook for about 5 to 6 minutes and then add curd in it.", "Stir continuously for about a minute.", "Add water if required.Let it cook for about 5 minutes more and when it is cooked properly, add the chopped coriander leaves.Now mix the crispy bhindi on the gravy, give a stir and serve hot.", "Serve Kurkuri Bhindi With Spicy Tomato Yogurt Gravy along with\u00a0Panchmel Dal,\u00a0Phulkas\u00a0and Rice for a perfect weekday meal."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Kurkuri_Bhindi_With_Spicy_Tomato_Yogurt_Gravy_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/248.Kurkuri_Bhindi_With_Spicy_Tomato_Yogurt_Gravy_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karwar Style Khatkhate Recipe (Mixed Vegetable Curry With Toor Dal & Coconut)', 'karwar-style-khatkhate-recipe-mixed-vegetable-curry-with-toor-dal-coconut', 'Karwar Style Khatkhate Recipe (Mixed Vegetable Curry With Toor Dal & Coconut) is basically a konkani mixed vegetable curry with toor dal and coconut. This dish is common in almost all konkani houses.', '["1/2 cup Arhar dal (Split Toor Dal)", "2 cups Mixed vegetables , (beans, carrot, potato, peas, drumstick, radish, taro root)", "1/2 teaspoon Turmeric powder (Haldi)", "2 tablespoons Jaggery , adjustable", "5 Kokum (Malabar Tamarind) , soak in hot water and extract juice", "Salt , to taste", "1/2 Fresh coconut , grated", "4 Dry Red Chillies", "1/2 teaspoon Coriander Powder (Dhania)", "8 Sichuan peppercorns", "2 teaspoons Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "Curry leaves , few"]'::jsonb, ARRAY['salt', 'arhar dal (split toor dal)', 'sunflower oil', 'coconut', 'mixed vegetables (beans', 'mustard seeds', 'jaggery', 'curry leaves', 'dry red chillies', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'kokum (malabar tamarind) soak water juice', 'sichuan peppercorns']::text[], '["To begin making the Karwar Style Khatkhate Recipe, wash and pressure cook toor dal with a pinch of turmeric for 2-3 whistles.", "Once cooked, mash it well and keep aside.", "Dice the vegetables and cook them with enough water in a pressure cooker for one whistle.", "Turn off the flame and immediately release the pressure.", "They should just be cooked. make sure you don''t overcook them.Meanwhile, grind coconut, red chillies, coriander powder\u00a0 and turmeric powder with little water to a smooth paste.", "Add sichuan pepper and grind the paste again for few more seconds.When the vegetables are almost done, add ground coconut paste and mashed toor dal.", "Add salt, kokam and jaggery.", "Mix everything well and bring to boil .Finally prepare the tempering for the curry.", "Heat oil in a kadhai.", "Add mustard seeds, cumin seeds and curry leaves.", "Cook for about a minute and then pour it on Khatkhate.", "Serve Karwar Style Khatkhate Recipe (Mixed Vegetable Curry With Toor Dal & Coconut) along with\u00a0Karwar Style Lasani Kadhi\u00a0and\u00a0Steamed Rice\u00a0for a weekday meal."]'::jsonb, 30, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/Khatkhate_Karwar_Style_Mixed_Vegetable_Curry_with_Toor_Dal__Coconut.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/249.Khatkhate_Karwar_Style_Mixed_Vegetable_Curry_with_Toor_Dal__Coconut.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Majjige Saaru/Salla Charu Recipe (Spicy Yogurt Curry Recipe)', 'andhra-style-majjige-saaru-salla-charu-recipe-spicy-yogurt-curry-recipe', 'Andhra Style Majjige Saaru/Salla Charu Recipe (Spicy Yogurt Curry Recipe) is a quick curry made with creamy yogurt that is mixed with caramelized soft onions and curry leaves. This is the best curry during the summer season when you feel like eating something light and refreshing to be served along with steamed rice.', '["1 cup Hung Curd (Greek Yogurt)", "1 Onion , sliced", "1 teaspoon Cumin seeds (Jeera)", "1 pinch Asafoetida (hing)", "1 sprig Curry leaves", "1 inch Ginger , sliced", "1 Green Chilli", "1 teaspoon Turmeric powder (Haldi)", "Oil", "Salt , to taste"]'::jsonb, ARRAY['hung curd', 'greek yogurt', 'onion', 'cumin seeds', 'jeera', 'asafoetida', 'hing', 'curry leaves', 'ginger', 'reen chilli', 'turmeric powder', 'haldi', 'oil', 'salt']::text[], '["To begin making the Majjige Saaru/Salla Charu, heat a flat skillet with oil, add cumin seeds and allow it splutter for 10 seconds.Add curry leaves, hing and leave the curry leaves to crackle for 10 seconds.Add in the chopped onions, ginger and green chilli, saute until the onions turn translucent.", "Once done switch off the heat.", "And allow the onions to cool down completely.In a bowl take curd and mix it with little water to create a flowing consistency but not too thin.", "Add the saut\u00e9ed onions and mix well and serve.Serve the Majjige Saaru/Salla Charu along with\u00a0steamed rice,\u00a0Andhra Style Davva Aava koora Recipe\u00a0,Radish Greens Poriyal Recipe\u00a0to go along with it for a comforting lunch meal."]'::jsonb, 25, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Andhra_Style_Majjige_SarruSalla_Charu_Recipe_Spicy_Yogurt_Curry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/250.Andhra_Style_Majjige_SarruSalla_Charu_Recipe_Spicy_Yogurt_Curry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Masala Vada Curry Recipe - Chana Dal Vada Curry Recipe', 'masala-vada-curry-recipe-chana-dal-vada-curry-recipe', 'Masala Vada Curry Recipe also known as the Chana Dal Vada curry is a delicious South Indian curry made from masala vada cooked in a tomato onion gravy.', '["To make the base for the curry", "1/2 cup Chana dal (Bengal Gram Dal)", "1 Dry Red Chilli", "5 Curry leaves", "1/2 teaspoon Fennel seeds (Saunf)", "To make the curry", "2 teaspoons Oil", "1 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "3 Cardamom (Elaichi) Pods/Seeds", "2 Whole Black Pepper Corns", "1 Bay leaf (tej patta)", "1 Green Chilli , slit", "1 sprig Curry leaves", "1 Onion , finely chopped", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "1/2 cup Homemade tomato puree , chopped", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "4 sprig Mint Leaves (Pudina) , or coriander leaves as required"]'::jsonb, ARRAY['tomato', 'cloves garlic', 'curry leaves', 'onion', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil', 'salt', 'green chilli', 'cardamom (elaichi) podsseeds', 'black pepper corns', 'red chilli powder', 'dry red chilli', 'mint leaves (pudina) coriander leaves', 'ginger', 'bay leaf (tej patta)', 'fennel seeds (saunf)', 'cinnamon stick', 'curry leaves', 'coriander powder', 'cloves (laung)']::text[], '["To begin making the Masala Vada Curry Recipe/ Chana Dal Vada Curry recipe, thoroughly wash and soak chana dal for 2 hours.Once the dal is soaked, coarse grind chana dal with the ingredients for making the base -dry red chili, curry leaves, fennel seeds and salt.", "Just sprinkle water while grinding, the masala vada batter should be thick.Spoon the masala vada batter on a Idli plates and steam it exactly like how we steam Idli.", "Or you can pan fry the Vada batter in a paniyaram pan with a little oil until it browned and crisp.", "The later gives a delicious taste to the Masala Vada Curry.Ensure you drizzle oil while pan frying the vada in the paniyaram pan.Meantime, we can start making the curry.", "Heat oil in a heavy bottomed pan on medium flame, add whole black pepper, cloves, cinnamon, bay leaf, slit green chili, curry leaves, ginger, garlic and onions.", "Make sure to remove few seeds from green chili if you want to make it less spicy.Once the onion turns golden, add the tomato puree and all\u00a0the masala powders - turmeric powder, red chili powder, coriander powder, chili powder and salt.", "Let it cook for 2 to 3 minutes until the masala curry comes to a brisk boil.Add required water and let the curry masala cook for a few minutes.", "Once the masala is cooked, drop in the masala vada into the curry mixture.Cover it with a lid and cook the Masala Vada Curry on a medium flame.", "The masala vada curry will absorb all the water and become thick.", "This will take around 5 to 7 minutes.Finally add chopped mint leaves and give the Masala Vada Curry a stir and serve.Serve Masala Vada Curry along with\u00a0Tawa Paratha,\u00a0Palak Raita\u00a0and\u00a0Satvik Carrot Sprout Salad\u00a0for a weekday meal.", "You can also serve this curry along with\u00a0Ghee Roast Dosa\u00a0or a\u00a0Karnataka Style Set Dosa Recipe."]'::jsonb, 60, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Masala_Vada_Curry_Recipe-13_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/251.Masala_Vada_Curry_Recipe-13_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kohlrabi Recipe (Knol Khol Poriyal)', 'kohlrabi-recipe-knol-khol-poriyal', 'Kohlrabi is commonly called as German kohl most popular in german speaking countries. It is also most commonly used in eastern parts of India like West Bengal and also in Bangladesh where it is called as ‘ol kopi’ and also in north india (kashmir) popularly called as ‘Nol Kohl’. It is also called as summer secret wonder vegetable rich in Vitamin C and Potassium. It is very easy to make and requires day to day ingredients to prepare them.', '["3 cups Kohl rabi , peeled and sliced", "1 Onion", "1 Tomato , diced", "1/4 cup Green peas (Matar)", "2 Dry Red Chillies", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Black Urad Dal (Split)", "Curry leaves , few", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 tablespoon Coriander Powder (Dhania)", "2 tablespoons Dessicated Coconut", "Salt , for taste"]'::jsonb, ARRAY['kohl rabi', 'tomato', 'salt', 'mustard seeds', 'coconut', 'green peas (matar)', 'red chilli powder', 'black urad dal (split)', 'curry leaves', 'dry red chillies', 'onion', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder']::text[], '["To begin making the Kohlrabi recipe, take kohlrabi and peel the outer fibrous part and cut into small squares.Heat oil in a heavy bottomed pan.", "When heated, add cumin seeds and mustard seeds.", "When they splutter, add a teaspoon of black urad dal.Saute until the dal tuurns brown.", "Now add in curry leaves, dry red chillies and turmeric powder.", "After 1 minute, add sliced onions and fry till the onion becomes soft.Add tomato slices and cook till they become little soft.", "Add fresh peas followed by kohlrabi slices and mix everything.Now close the lid and cook for some more time mixing at regular intervalsAdd spices - coriander powder, red chilli powder and salt as per taste.Add dry dessicated coconut, mix everything and cook for few minutes by closing lid.Cook till kohlrabi slices become soft.", "Turn off the heat and garnish with coriander leaves.", "Serve Kohlrabi along with\u00a0Dal Tadka\u00a0and\u00a0Steamed Rice\u00a0for a weekday meal with your family."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/neetha2687-gmail.com/kohl_rabiNol_khol_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/252.kohl_rabiNol_khol_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer Stuffed Bhindi Masala Recipe', 'paneer-stuffed-bhindi-masala-recipe', 'Paneer Stuffed Bhindi Masala Recipe is a delicious dish made by stuffing lady''s finger also called as bhindi with a spicy crumbled paneer. You can prepare this dish in both a gravy form by adding a tomato base to the stuffed bhindi recipe.', '["250 grams Bhindi (Lady Finger/Okra)", "2 tablespoons Oil", "1 Onion , thinly sliced", "1 Tomato , finely chopped", "1 teaspoon Ginger , finely chopped", "2 cloves Garlic , finely chopped", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "Salt , to taste", "Ingredients for paneer stuffing", "1 cup Paneer (Homemade Cottage Cheese) , crumbled", "1/2 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Amchur (Dry Mango Powder)", "1/4 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste"]'::jsonb, ARRAY['s bhindi', 'lady finger/okra', 's oil', 'onion', 'tomato', 'ginger', 's garlic', 'cumin seeds', 'jeera', 'asafoetida', 'hing', 'salt', 'ingredients for paneer stuffing', 'paneer', 'homemade cottage cheese', 'coriander powder', 'dhania', 'amchur', 'dry mango powder', 'red chilli powder', 'turmeric powder', 'haldi']::text[], '["To begin making Paneer Stuffed Bhindi Masala Recipe wash okra, pat them with a dry\u00a0cloth and cut off the stems.", "Make a vertical cut in okra, making sure they don\u2019t become two separate halves.To prepare the paneer stuffing, combine all the ingredients for the stuffing in a mixing bowl.Fill 1/2 teaspoon of mixture in each okra through the slits.", "Once all the okras are stuffed with the mixture, keep them aside.Heat oil in a deep\u00a0pan and add cumin seeds along with the asafoetida.", "Once it crackles, add chopped onion, ginger, garlic and saute until the onions are tender.Add the stuffed okra and saute.", "Cover and cook on low heat for 5 minutes.", "Once the bhindi is nearly cooked\u00a0add the tomatoes and cook for a couple\u00a0of minutes on medium heat.Stir in the remaining paneer (if extra) stuffing at this point of time to add more flavors.Cover the pan and simmer the Paneer Stuffed Bhindi Masala over\u00a0medium heat until the bhindi is soft and cooked.Check the salt and adjust according to taste.", "Transfer the\u00a0Paneer Stuffed Bhindi Masala to a serving bowl and serve hot.Serve the Paneer Stuffed Bhindi Masala along with\u00a0Phulka''s,\u00a0Gujarati Kadhi\u00a0and\u00a0Badam Ki Kheer Recipe \u00a0for a weekday dinner."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/dry_vegetables/Paneer_Stuffed_Bhindi_Masala_Recipe_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/253.Paneer_Stuffed_Bhindi_Masala_Recipe_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Style Rajma Gogji Recipe - Kidney Beans & Turnip Curry', 'kashmiri-style-rajma-gogji-recipe-kidney-beans-turnip-curry', 'Kashmiri cuisine is characterised by the pungent flavour due to the use of mustard oil and whole garam masalas. It is rich and flavourful without including much spices. Although it mainly consists of meat dishes, it has a handful of vegetarian dishes which are cooked with unique spices.', '["2 cups Kashmiri Rajma , washed and soaked overnight", "1 Onion , slices", "1 Tomato , finely chopped", "3 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "3 Turnips , cut into cubes", "1 teaspoon Dry ginger powder", "1 teaspoon Kashmiri Red Chilli Powder", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Fennel Powder", "1/4 teaspoon Kashmiri masala powder , (vaer)", "2 tablespoons Mustard oil", "2 Onion , slices, to garnish", "Salt , to taste"]'::jsonb, ARRAY['s kashmiri rajma', 'onion', 'tomato', 's garlic', 'ginger', 'turnips', 'dry ginger powder', 'kashmiri red chilli powder', 'turmeric powder', 'haldi', 'fennel powder', 'kashmiri masala powder', 's mustard oil', 'salt']::text[], '["To begin making\u00a0Kashmiri Rajma Gogji Recipe, wash and soak the kashmiri rajma in warm water overnight.Heat a tablespoon of mustard oil in a pressure cooker pan and smoke it, add the onions and saute until it turns golden brown.Add the ginger and garlic and fry until it turns brown in colour.Add the tomatoes and saute until it becomes soft.Now, add the turmeric, red chilli, dry ginger and fennel powder and saute for a minute.Add the drained rajma into the pressure pan along with 4 cups of water.Add the vaer masala, season with salt, close the pressure cooker pan and cook until 4 whistles in low flame.Now, simmer for 40 minutes on low flame, and then switch off the flame and let the pressure release on its own.In the mean, smoke the remaining 1 tablespoon of mustard oil in a pan on medium heat and fry the cubes turnips until it turns golden and keep aside.Once, the rajma is cooked, put the pressure cooker back on the medium flame, add the fried turnip cubes and simmer for another 10 minutes before serving.Garnish with sliced onions and serve the\u00a0Kashmiri Rajma Gogji Recipe along with steamed rice for a lazy weekend brunch along with salad.", "You can also serve it with\u00a0Missi Roti Recipe\u00a0and\u00a0Lauki Raita Recipe."]'::jsonb, 90, 'Kashmiri', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Kashmiri_Rajma_Gogji_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/254.Kashmiri_Rajma_Gogji_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Vankaya Fry Recipe With Peanuts - Brinjal Peanut Sabzi', 'andhra-vankaya-fry-recipe-with-peanuts-brinjal-peanut-sabzi', 'Andhra Vankaya Fry With Peanuts Recipe is a quick and tasty dish made from small brinjal which has the nutty crunch from the peanuts and spice flavours from authentic sambar masala made in the household of Andhra. Easy to make, you can even pack it in your Lunch Box.', '["6 Small Green brinjal (green aubergine) , diced", "1/2 cup Raw Peanuts (Moongphali) , crushed", "3 Green Chillies , sliced", "1 pinch Asafoetida (hing)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "2 sprig Curry leaves", "1 inch Ginger , chopped", "4 cloves Garlic , pound", "2 tablespoon Sambar Powder"]'::jsonb, ARRAY['ginger', 'sambar powder', 'mustard seeds', 'asafoetida (hing)', 'curry leaves', 'cloves garlic pound', 'cumin seeds (jeera)', 'peanuts (moongphali)', 'green chillies', 'green brinjal (green aubergine)']::text[], '["To begin making the Andhra Vankaya Fry With Peanuts Recipe, firstly\u00a0heat a kadai, add oil and splutter mustard seeds, jeera seeds, hing and curry leaves.Once that is done, add the chopped ginger, garlic, green chillies, brinjal and fry them till the brinjal reduces in its size and lightly roasted.Once the brinjal is half way cooked,\u00a0add the crushed peanuts and sambar powder, saute for a minute till all the spices coat the brinjals.", "Season the Vankaya Fry well with salt.Sprinkle a little water and cook till the brinjals are soft if required.", "Close it with the lid and let the\u00a0Vankaya cook and soften completely.", "Once done, turn off the heat, check the salt and other spices and adjust accordingly.Serve the Andhra Vankaya Fry Recipe\u00a0along with\u00a0Puliyodharai / Puliyogare Recipe,\u00a0Andhra Style Pappu Charu,\u00a0Steamed Rice\u00a0and\u00a0Homemade Curd\u00a0for a comforting lunch or dinner."]'::jsonb, 40, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Vankaya_Vepudu_With_Peanut_Masala_Recipe-4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/255.Vankaya_Vepudu_With_Peanut_Masala_Recipe-4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Style Kosha Mangsho Recipe- Spicy Mutton Curry', 'bengali-style-kosha-mangsho-recipe-spicy-mutton-curry', 'Kosha Mangsho is a spicy and delicious Mutton curry from Bengal. It is one of the most popular recipes in Bengali cuisine and is known for its great flavour and taste. Here I am sharing the recipe of Kosha Mangsho that can be cooked at home in a pressure cooker., which makes the dish even more easy.', '["250 grams Mutton , cut into pieces", "2 tablespoons Mustard oil", "1 Cardamom (Elaichi) Pods/Seeds", "1 Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "1/2 teaspoon Cumin seeds (Jeera)", "1 Onion , finely chopped", "2 teaspoons Ginger Garlic Paste", "1 teaspoon Red Chilli powder", "Salt , to taste", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 cup Curd (Dahi / Yogurt)", "Coriander (Dhania) Leaves , Few sprigs, chopped"]'::jsonb, ARRAY['salt', 'coriander (dhania) leaves', 'mustard oil', 'cardamom (elaichi) podsseeds', 'red chilli powder', 'ginger garlic paste', 'curd', 'cinnamon stick (dalchini)', 'mutton', 'cumin seeds (jeera)', 'onion', 'turmeric powder', 'cloves (laung)']::text[], '["To begin making the Kosha Mangsho recipe, heat mustard oil in a pressure cooker, add cumin seeds and allow it to sputter.Then add cardamom, cloves and cinnamon along with onions and saute till the onions turn soft.Next add ginger garlic paste and saut\u00e9 till the raw smell goes.Add red chilli powder, salt and turmeric powder and mix well.Add the mutton pieces and stir well with the masalas.", "Next add the curd and gently mix.Now add 1 cup water and close the lid.", "Pressure cook for 10 minutes or 4 whistles.Check whether the mutton is cooked and soft.", "Pressure cook for some more time if not.Remove the lid of the cooker and cook the gravy in a low flame while stirring for about 5 minutes till most of the water has evaporated and you get a nice thick gravy.Transfer the gravy to a bowl, and garnish with coriander leaves and cumin seeds.Serve Kosha Mangsho with\u00a0Bengali Luchi\u00a0for a perfect weekend lunch or dinner."]'::jsonb, 30, 'Bengali', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Amina_K/BENGALI_MUTTON_CURRY_KOSHA_MANGSHO_IN_A_PRESSURE_COOKER.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/256.BENGALI_MUTTON_CURRY_KOSHA_MANGSHO_IN_A_PRESSURE_COOKER.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Menthe / Fenugreek Seeds Tambli Recipe (Karnataka Recipes)', 'menthe-fenugreek-seeds-tambli-recipe-karnataka-recipes', 'Here''s a bowlful of simple, healthy and comforting side dish, that''s great to cool your body naturally. Tambli is a very traditional Karnataka dish which our grannys have been making from many years . Thambli is mild, medicinal and soothing dish that makes a meal wholesome. For better understanding we can call term tambli as medicated buttermilk / a type of raita / cold soup .You can prepare tambli with anything and most of them takes just 10 mins.Today it is " Menthe Tambli ( Tambuli ) / Fenugreek Seeds Tambli ". This fenugreek tambli is a great diabetic friendly dish too .', '["2 teaspoons Methi Seeds (Fenugreek Seeds)", "3 Dry Red Chillies", "1/4 cup Fresh coconut , grated", "1-1/2 cup Curd (Dahi / Yogurt)", "1/2 teaspoon Ghee", "Salt , to taste", "1 teaspoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Curry leaves , few"]'::jsonb, ARRAY['salt', 'ghee', 'coconut', 'mustard seeds', 'curry leaves', 'curd', 'dry red chillies', 'methi seeds (fenugreek seeds)']::text[], '["To begin making the Menthe/Fenugreek Seeds Tambli Recipe, heat ghee in a kadai or a heavy bottomed pan.", "Add methi seeds and dry red chillies to it.", "Roast them until methi seeds and red chilies turn brownish and aromatic.", "Once done transfer to a plate .In a mixer grinder, blend the methi seeds along with grated coconut, salt and little yogurt to make a smooth paste.", "You can add a little water to the mixture.Transfer the methe and coconut mixture to a serving bowl.", "Add the remaining yogurt and stir well.", "Add salt and check the taste.", "The final step is to make the seasoning.", "Heat ghee in the small tadka pan over medium heat.Once hot add mustard seeds and allow it to crackle.", "When they splutter add curry leaves and turn off the heat.", "Pour this seasoning on the Menthe Tambli and give a gentle stir.", "The Menthe Tambli is ready to be served.Serve the\u00a0Menthe / Fenugreek Seeds Tambli as a side dish along with your main course meal for lunch or dinner."]'::jsonb, 30, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha_Kalluraya/Menthe_Fenugreek_Seeds_Tambli_Recipe_Karnataka_Recipes-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/257.Menthe_Fenugreek_Seeds_Tambli_Recipe_Karnataka_Recipes-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paruppu Keerai Masiyal Recipe - Red Amaranth With Toor Dal', 'paruppu-keerai-masiyal-recipe-red-amaranth-with-toor-dal', 'Paruppu Keerai Masiyal Recipe which is also called as Red Amaranth with Toor Dal is a healthy side dish that you must try it along with your everyday meals.', '["1/2 cup Arhar dal (Split Toor Dal)", "2 cups Red Amaranth Leaves , chopped", "1 Onion , chopped", "3 cloves Garlic , crushed", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1/4 teaspoon Turmeric powder (Haldi)", "1 Dry Red Chilli", "3 tablespoons Fresh coconut , grated", "Salt , to taste", "1 sprig Curry leaves", "Oil"]'::jsonb, ARRAY['arhar dal', 'split toor dal', 's red amaranth leaves', 'onion', 's garlic', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'turmeric powder', 'haldi', 'dry red chilli', 's fresh coconut', 'salt', 'curry leaves', 'oil']::text[], '["To begin making the Paruppu Keerai Masiyal Recipe, cook the toor dal in pressure cooker with 2 cups water, turmeric powder and salt for 2 whistle.", "Once done, switch off the heat and keep it aside to release the pressure naturally.Heat a skillet with oil, add mustard seeds, urad dal and allow it splutter for few seconds.Add chopped curry leaves, dry red chillies and leave it to crackle.", "Once it crackles, add garlic and saute until it softens.Once that is done, add onions and saute till they turn translucent.", "Add chopped red amaranth leaves and sprinkle enough salt and saute till the leaves wilt.Add cooked dal and grated coconut and give one last stir till it all combines.", "Check for salt and serve hot.Serve the\u00a0Paruppu Keerai Masiyal Recipe\u00a0along with\u00a0Rasam,\u00a0Steamed Rice\u00a0and\u00a0Carrot Poriyal Recipe (Steamed Carrot Stir Fry)\u00a0or just plain with Phulka to enjoy your healthy lunch."]'::jsonb, 30, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Parappu_Keerai_Masiyal_Recipe_Red_Amaranth_with_Toor_Dal.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/258.Parappu_Keerai_Masiyal_Recipe_Red_Amaranth_with_Toor_Dal.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Broccoli Egg Bhurji Recipe', 'broccoli-egg-bhurji-recipe', 'When we love to cook, we often experiment different dishes in our kitchen. Egg is one such versatile food which can be paired with any vegetable and a delicious recipe can be prepared. Broccoli Egg Bhurji is one such recipe, which is a combination of scrambled eggs and broccoli. This recipe is perfect for the days when you are tired after a busy day and don’t want to eat outside.', '["3 Whole Egg", "1 cup Broccoli , florets, chopped into small pieces", "2 Onion , finely chopped", "2 Tomatoes , finely chopped", "6 Garlic , cloves, finely chopped", "1 teaspoon Turmeric powder (Haldi)", "2 teaspoon Red Chilli powder", "2 tablespoon Coriander (Dhania) Leaves , finely chopped", "Salt , to taste", "2 tablespoon Oil"]'::jsonb, ARRAY['tomato', 'garlic cloves', 'salt', 'eggs', 'coriander (dhania) leaves', 'red chilli powder', 'onion', 'broccoli florets', 'turmeric powder', 'sunflower oil']::text[], '["To begin making Broccoli Egg Bhurji, heat oil in a frying pan or skillet and add finely chopped onions.When onion turns pinkish, add chopped garlic and saut\u00e9 till the raw smell of garlic goes away.Once it is done, add the chopped tomatoes and saut\u00e9 till it turns mushy.Add broccoli florets and cook them for 10 minutes.", "After 10 minutes, add turmeric powder, red chilil powder, salt and mix everything well.One by one break the eggs directly into the skillet.", "Mix well and wait for the eggs to cook.Once you see the eggs getting cooked, take a spatula and scramble it in the skillet.Scramble continuously till the eggs are finely minced and mixed well with the onion-tomato-broccoli mixture.Adjust salt according to your taste and garnish with chopped coriander leaves and again mix well.", "Switch off the gas and serve hot.Serve Broccoli Egg Bhurji with\u00a0Whole Wheat Lachha Parathas\u00a0and\u00a0Lauki Raita\u00a0for weekday lunch or you can have it with toast for breakfast."]'::jsonb, 30, 'Indian', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Broccoli_And_Egg_Burji.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/259.Broccoli_And_Egg_Burji.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tawa Paratha Recipe - Plain Paratha', 'tawa-paratha-recipe-plain-paratha', 'Plain Parathas also known as Tawa Paratha are crisper and flakier version of phulka''s and are traditionally cooked in ghee on an iron skillet. Being relatively quick to make; the Parathas are a good substitute for Naans or Tandoori Rotis.', '["1 cup Whole Wheat Flour", "1/2 teaspoon Salt", "Oil , for kneading", "Ghee , or oil for cooking (as required)"]'::jsonb, ARRAY['ghee', 'oil', 'salt', 'wheat flour', 'sunflower oil']::text[], '["To begin making the Tawa Paratha, in a large bowl combine the flour, salt, a tablespoon of oil and knead adding little water at a time to make firm and smooth dough.Add one tablespoon of oil to coat the dough and knead again.", "Cover and set aside for 15 minutes.Knead once again and divide the dough into 8 portions.", "Preheat the iron skillet on medium heat.Roll the dough portions into balls and flatten them with the palm of your hand.", "Toss them in flour and roll them out into circles of approximately 3 inches in diameter.", "Put 1/4 teaspoon oil and spread it on the rolled dough.We need to get a triangle shape, to do so, first fold into a semi-circle, then fold the semi-circle into half again.", "You get a mini triangle shape.Tossing the triangle in a little flour, roll it out gently into a larger triangle.", "Continue the same process of rolling with the remaining dough portions.With skillet on medium high heat, place one rolled out paratha on the skillet.", "After a few seconds you will notice an air pockets popping out.At this point flip the plain paratha and smear about 1/2 a teaspoon of ghee.", "Using a flat spatula do a light pressing and turning motion to cook\u00a0 the paratha.Flip to the other side and press and turn the paratha in a similar way.", "You will notice brown spots around the parathas and it will be slightly crisp.", "Remove from heat and place on a platter or serve hot.Continue the similar process with the remaining rolled portions and stack the cooked paratha one above the other.Serve the Plain or\u00a0Tawa Paratha\u00a0for dinner along with\u00a0Batata Nu Shaak\u00a0or\u00a0Baingan Bharta\u00a0and\u00a0Palak Dal\u00a0for a weekday meal."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/Extras/Tawa_Paratha_Recipe-7956.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/260.Tawa_Paratha_Recipe-7956.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kathirikai Rasavangi Recipe - Eggplant is a Tangy Coconut Gravy', 'kathirikai-rasavangi-recipe-eggplant-is-a-tangy-coconut-gravy', 'Kathirikai Rasavangi Recipe - Eggplant is a Tangy Coconut Gravy is a very traditional recipe from the households of Tamil Brahmins. The freshness of the dish comes from adding the freshly ground spice paste to brinjal/ eggplant. It has a very distinct flavour with the addition of coriander seeds and peppercorns.', '["1 Brinjal (Baingan / Eggplant) , cubed", "1/4 cup Arhar dal (Split Toor Dal)", "1/2 teaspoon Turmeric powder (Haldi)", "1 cup Tamarind Water", "1 teaspoon Jaggery , powdered (optional)", "Salt , to taste", "Ingredients to Dry Roast and Grind", "1/2 tablespoon Chana dal (Bengal Gram Dal)", "1 tablespoon Coriander (Dhania) Seeds", "1 Dry Red Chilli", "10-15 Whole Black Peppercorns", "1/2 cup Fresh coconut , grated", "Ingredients for Seasoning", "1 tablespoon Sesame (Gingelly) Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'arhar dal (split toor dal)', 'tamarind water', 'coconut', 'brinjal (baingan eggsplant)', 'mustard seeds', 'jaggery', 'sesame (gingelly) oil', 'black peppercorns', 'dry red chilli', 'curry leaves', 'coriander (dhania) seeds', 'turmeric powder', 'chana dal (bengal gram dal)']::text[], '["To prepare Kathirikai Rasavangi Recipe - Eggplant is a Tangy Coconut Gravy, pressure cook the toor dal with 1 cup of water for 4 to 5 whistles.Turn off the heat and allow the pressure to release naturally.", "Once the dal is cooked, whisk the dal well and keep it aside.In the meantime, heat a small pan on medium heat and dry roast chana dal, coriander seeds, red chilly and peppercorns till it gets aromatic and turns golden brown.Once roasted, add the grated coconut to this and keep stirring till it turns brown.", "Turn off the heat, cool and grind to a smooth mixture by adding a 1/4 cup of water.", "Keep this aside.Heat oil in a preheat pan; add the mustard seeds and allow it to crackle.", "Add the curry leaves and brinjal, sprinkle salt and give it a stir.", "Cover the pan and cook the brinjal until roasted and soft.", "To the cooked brinjal, add the tamarind water, turmeric powder, jaggery, cooked dal, coconut mixture and salt to taste.Simmer the\u00a0Kathirikai Rasavangi\u00a0 for a good 5 minutes until the raw smell of tamarind goes away and the rasavangi has good taste and flavours.Check the salt and adjust to taste accordingly.", "Once done, turn off the heat and transfer the\u00a0Kathirikai Rasavangi to a serving bowl and serve hot.Serve\u00a0the Kathirikai Rasavangi Recipe with Steamed Rice, Keerai Masiyal,\u00a0Potato Curry to make this recipe a complete south indian meal."]'::jsonb, 35, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Traditional_Kathrikai_Rasavangi_recipe_Brinjal_Recipe_south_indian_style_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/261.Traditional_Kathrikai_Rasavangi_recipe_Brinjal_Recipe_south_indian_style_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Potato Korma Recipe', 'andhra-style-potato-korma-recipe', 'Andhra Style Potato Korma Recipe have flavors that are sensational. The whole spice used are stone flower, star anise, cinnamon and cardamom. The potato is cooked in coconut and poppy seeds based gravy and simmered till the flavors are developed.', '["4 Potatoes (Aloo) , cut into small cubes", "1 Stone flower", "1 Star anise", "1 inch Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "1 teaspoon Fennel seeds (Saunf)", "1 Onion , sliced", "1 Tomato , chopped", "2 cloves Garlic , chopped", "1 inch Ginger , chopped", "4 sprig Coriander (Dhania) Leaves , chopped", "4 sprig Mint Leaves (Pudina) , chopped", "1 Green Chilli , chopped", "1 teaspoon Red Chilli powder", "1 tablespoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "Salt , to taste", "Ingredients to grind", "1/2 cup Fresh coconut , grated", "5 tablespoons Poppy seeds , roasted"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'garam masala powder', 'green chilli', 'cardamom (elaichi) podsseeds', 'fennel seeds (saunf)', 'coconut', 'mint leaves (pudina)', 'red chilli powder', 'cloves garlic', 'st flower', 'coriander (dhania) leaves', 'cinnamon stick (dalchini)', 'onion', 'poppy seeds', 'coriander powder', 'potato (aloo)', 'turmeric powder', 'star anise']::text[], '["To begin making Andhra Style Potato Korma the Recipe grind the roasted poppy seeds and coconut with water to a smooth paste and keep it aside.Heat a pressure cooker with oil, add fennel seeds, stone flower, star anise, cinnamon and cardamom and fry for 10 seconds.Add sliced onions, ginger, garlic and green chilli and fry for about 5 minutes till the onions turn translucent.Add tomatoes and salt and saute until it becomes soft and mushy.", "Add in the chopped herbs and give it a stir.Add the ground paste along with spice powders (red chilli powder, turmeric, garam masala, coriander powder) and salt.", "Mix well.Saute for 5 more minutes, add potatoes and 1 cup of water and pressure cook for 3 whistle.Switch off the heat and allow the pressure to release by itself and serve hot.Serve the Andhra Style Potato Korma along with\u00a0Tawa Paratha\u00a0or\u00a0Hibiscus (Chembaruthi) Neer Dosa\u00a0to enjoy your evening meal."]'::jsonb, 40, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Andhra_Style_Potato_Korma_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/262.Andhra_Style_Potato_Korma_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gawarphali Ki Sabzi Recipe -Cluster Beans Sabzi', 'gawarphali-ki-sabzi-recipe-cluster-beans-sabzi', 'Gawarphali Ki Sabzi is a traditional North Indian dish that is served with paratha or rice. This is simple to make and requires only minimal household ingredients. It gets ready in no time and therefore you can also pack this in your lunch box.', '["250 grams Gawar Phali (Kothavarangai / Cluster beans)", "1 Green Chilli", "4 cloves Garlic", "1 tablespoon Gram flour (besan)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "Asafoetida (hing) , a pinch", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Amchur (Dry Mango Powder)", "Salt , to taste", "1 teaspoon Oil"]'::jsonb, ARRAY['salt', 'green chilli', 'amchur (dry mango powder)', 'mustard seeds', 'asafoetida (hing)', 'cloves garlic', 'gram flour (besan)', 'gawar phali (kothavarangai cluster beans)', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Gawarphali Ki Sabzi recipe, first wash and cut cluster beans into one inch size.", "Add it to pressure cooker along with required water and cook for 2 whistles.Once the pressure releases, open the lid of cooker.", "Drain excess water and keep aside the cooked cluster beans.Heat a heavy bottomed pan with oil, add mustard seeds and cumin seeds.", "Once the cumin seeds splutters, add asafoetida, crushed garlic and green chilli.", "Saute well for a minute.After a minute, add besan flour to it and mix well on low flame.", "Let it cook for about 2 to 3 minutes.Now add the cooked cluster beans along with required salt, turmeric powder, coriander powder and amchoor powder.", "Mix well and saute for a minute.Sprinkle little water\u00a0and cook\u00a0Gawarphali Ki Sabzi on medium flame until it thickens and the cluster beans are cooked properly along with besan.", "Serve\u00a0Gawarphali Ki Sabzi hot.Serve\u00a0Gawarphali Ki Sabzi along with\u00a0Panchmel Dal,\u00a0Boondi Raita\u00a0and\u00a0Phulka\u00a0for a weekday lunch."]'::jsonb, 25, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swathynandhini/GAWAR_PHALI_KI_SABZI__CLUSTER_BEANS_CURRY_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/263.GAWAR_PHALI_KI_SABZI__CLUSTER_BEANS_CURRY_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Niramish Aloo Dum Recipe', 'niramish-aloo-dum-recipe', 'This Niramish Aloo Dum recipe is perfect for festivals as it is made without onion and garlic, still is loaded with lots of flavor. This is usually served with Radhaballavi or Stuffed Chana Daal Poori and is undoubtedly the favorite breakfast of a typical Bengali Household. This mouth watering delicacy found its way to the heart of many people just like me who despite not being a Bengali love this lip smacking aloo dum. You will find this combo mainly made during Pujas and other functions in many Bengali households.', '["6 Potatoes (Aloo)", "1 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies", "1 teaspoon Dry ginger powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Garam masala powder", "1 teaspoon Asafoetida (hing)", "Few Coriander (Dhania) Leaves , for garnishing"]'::jsonb, ARRAY['asafoetida (hing)', 'coriander (dhania) leaves', 'red chilli powder', 'dry ginger powder', 'dry red chillies', 'cumin seeds (jeera)', 'potato (aloo)', 'turmeric powder', 'garam masala powder']::text[], '["To begin making the Niramish Aloo Dum, wash, boil, peel and coarsely mash the potatoes so that large chunks remain intact.Make a paste of the dry ginger powder, turmeric powder, red chili powder, garam masala powder with the help of a little water.Heat oil in a wok/kadhai.", "Add dry red chilli and cumin seeds.", "Once it starts to splutter add the hing and turn off the gas.Add the masala paste and stir well and now turn on the gas and add the mashed potato along with salt to it.Saute for 1 minute and then add water as require for the gravy.Let it boil.", "Cover and cook on simmer for 5 to 6 minutes or till the desired consistency of the gravy have reached.Serve Niramish Aloo Dum along with\u00a0Bengali Luchi\u00a0for a weekend lunch."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Alaka_Jena/Niramish_Aloo_Dum.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/264.Niramish_Aloo_Dum.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mirchi Ke Tipore Recipe - Green Chilli Stir Fry', 'mirchi-ke-tipore-recipe-green-chilli-stir-fry', 'Mirchi Ke Tipore Recipe is a signature dish of Rajasthani cuisine. An authentic Rajasthani meal can not be completed without Mirch Ke Tipore. It is a quick recipe and can be kept in fridge for 3 to 4 days in an airtight container.', '["200 grams Green Chillies , (big one), chopped", "3 tablespoons Mustard oil", "1 tablespoon Mustard seeds (Rai/ Kadugu)", "2 pinch Asafoetida (hing)", "1 tablespoon Cumin seeds (Jeera)", "2 tablespoon Fennel seeds (Saunf)", "1-1/2 tablespoon Coriander Powder (Dhania)", "1/4 tablespoon Red Chilli powder", "1/2 tablespoon Turmeric powder (Haldi)", "1 tablespoon Amchur (Dry Mango Powder)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard oil', 'asafoetida (hing)', 'mustard seeds', 'fennel seeds (saunf)', 'amchur (dry mango powder)', 'red chilli powder', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'green chillies']::text[], '["To begin making the Mirchi Ke Tipore Recipe, firstly heat oil in a heavy bottomed pan.Once the oil is heated, add asafoetida, mustard seeds, cumin seeds and fennel seeds.", "Cook them for about 10 to 15 seconds.After 10 to 15 seconds, add the chopped green chillies (big one).", "Cook them for about 3 minutes or till the green chillies becomes soft.Once they become soft, add all the masalas including turmeric powder, red chilli powder, dry mango powder and salt.Mix everything properly and cook it for more 3 minutes.", "Once the masala is cooked and well coated with the mirchi, switch off the gas and serve hot.Serve Mirchi Ke Tipore along with\u00a0Panchmel Dal,\u00a0Mooli And Wadi Ki Sabzi\u00a0and\u00a0Phulkas\u00a0for a weekday meal with your friends and family."]'::jsonb, 18, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pooja/Mirchi_ke_Tipore.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/265.Mirchi_ke_Tipore.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tomato Sheer Recipe -Tomato And Coconut Curry Recipe', 'tomato-sheer-recipe-tomato-and-coconut-curry-recipe', 'Tomato Sheer is a mild curry made with coconut milk and tomatoes. This soothing curry is apt during hot days. Besan is mixed with coconut milk to make the gravy thick and creamy. Make this on a rushed morning to be packed into our kids lunch box with steamed rice or phulkas.', '["4 Tomatoes , chopped fine", "1 Onion , chopped fine", "1/2 teaspoon Yellow Fenugreek Seeds", "1/4 teaspoon Asafoetida (hing)", "1 tablespoon Oil", "1 tablespoon Gram flour (besan)", "180 ml Coconut milk", "Salt , salt to taste", "1/2 teaspoon Sugar", "1 teaspoon Red Chilli powder", "Oil"]'::jsonb, ARRAY['tomatoes', 'onion', 'yellow fenugreek seeds', 'asafoetida', 'hing', 'oil', 'gram flour', 'besan', 'coconut milk', 'salt', 'sugar', 'red chilli powder']::text[], '["To begin making Tomato Sheer Recipe, in a pan, heat the oil, add asafoetida and the fenugreek seeds.Allow the fenugreek seeds to roast for a few seconds.Add in the chopped onion and saut\u00e9 until the onions turn transparent and soft.Once the onions have softened, add the chopped tomatoes and cook till the onion and tomatoes combine to form a thick paste.", "This will take 8 to 10 minutes until the tomatoes cook through completely.In the meanwhile, dissolve the besan in a few tablespoons of coconut milk.", "Add in the salt, chilli powder and sugar and mix well.", "Stir in the rest of the coconut milk and stir until well combined.", "The sugar is only intended to take the edge off the acidity of the tomatoes and should not overpower or sweeten the taste of this curry.Add this coconut milk mixture to the pan with onion and tomato paste.Whisk to combine it together.", "Simmer the\u00a0Tomato Sheer low heat until lightly bubbly, about 5 to 8 minutes.", "Add a little water if required to adjust the consistency of the\u00a0Tomato Sheer / Tomato Coconut Curry.Check the salt and spices and adjust the taste accordingly.", "Once done, turn off the heat and transfer the\u00a0Tomato Sheer Recipe to a serving bowl.Serve\u00a0Tomato Sheer/ Tomato Coconut Milk Curry with\u00a0Manathakkali Kootu,\u00a0Steamed Rice\u00a0and\u00a0Elai Vadam\u00a0for a comforting lunch."]'::jsonb, 55, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Tomato_Coconut_Milk_Curry_Recipe_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/266.Tomato_Coconut_Milk_Curry_Recipe_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Masala Roti Recipe-Soft and Spicy Indian Flat Bread', 'masala-roti-recipe-soft-and-spicy-indian-flat-bread', 'Soft and Spicy Masala Roti Recipe is a delicious Indian flat bread with the goodness of pearl millet or bajra, finger millet or ragi, maize or makai, oatmeal and whole wheat flour. This Soft and Spicy Indian Flat Bread has the right mix of various millets and spices making it a nutritious wholesome food.', '["1 cup Whole Wheat Flour", "1 cup Corn flour", "1/2 cup Oats Flour", "1/4 cup Bajra Flour ( Pearl Millet)", "1/4 cup Ragi Flour (Finger Millet/ Nagli)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Flax seed powder (flax meal)", "1 teaspoon Ajwain (Carom seeds) , crushed between palms", "2 teaspoons Kasuri Methi (Dried Fenugreek Leaves)", "Lukewarm Water , to knead the dough", "Ghee , or oil to cook", "Salt , to taste"]'::jsonb, ARRAY['salt', 'wheat flour', 'corn flour', 'coriander powder', 'red chilli powder', 'ragi flour (finger millet nagli)', 'ghee', 'oil', 'water knead the dough', 'bajra flour ( pearl millet)', 'ajwain (carom seeds) between palms', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'flax seed powder (flax meal)', 'oats flour']::text[], '["To begin making Masala Roti Recipe, combine all the ingredients, except the oil or ghee,\u00a0 in a large Mixing bowl.", "Add a little lukewarm water at a time and knead to make a smooth dough.Drizzle a teaspoon of oil over the dough and knead for a couple of minutes until smooth and firm.", "Divide the roti dough into 10 portions.Preheat the tawa on medium heat.Roll each portion of the dough, by dusting in flour into a thin circle.", "The thickness of the masala roti will be based on how thin you can roll it.Once rolled, place the masala roti on the tawa and allow it to cook for a few seconds on medium heat.Once you see air bubbles popping, flip and turn.", "Smear ghee or oil over the roti and cook on both sides until browned and lightly crisp.Once done, transfer the Mixed Millets Masala Roti from the tawa onto a plate.", "Make masala rotis similarly with remaining portions of the dough.Serve\u00a0Masala Roti along with\u00a0Amla Methi Sukhi Sabzi\u00a0and\u00a0Cauliflower Moong Dal\u00a0for lunch or\u00a0along with\u00a0Jeera Aloo/Baingan Ka Bharta\u00a0for a wholesome breakfast."]'::jsonb, 50, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/soft-and-spicy-masala-roti.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/267.soft-and-spicy-masala-roti.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pachai Payaru Poriyal Recipe - Green Moong Sprout Poriyal', 'pachai-payaru-poriyal-recipe-green-moong-sprout-poriyal', 'Pachai Payaru Poriyal Recipe is essentially sprouted green moong, that is sprouted and then stir fried along with mustard seeds and curry leaves. It is made sattvic style with no usage of onion and garlic, making it apt for your Fasting Days too.', '["1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies", "2 sprig Curry leaves", "1-1/2 cup Green Moong Sprouts", "Salt , to taste", "1 teaspoon Black pepper powder", "1 teaspoon Lemon juice", "2 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['oil', 'mustard seeds', 'rai/ kadugu', 'dry red chillies', 'curry leaves', 'green moong sprouts', 'salt', 'black pepper powder', 'lemon juice', 'coriander', 'dhania']::text[], '["To begin making the Pachai Payaru Poriyal Recipe, we need to keep the green moong sprouts ready.", "You can either use store bought green moong sprouts or make them at home.", "Learn How to make Sprouts at Home Next in a pan heat oil on medium flame, add the mustard seeds and allow them to splutter, next add the dry red chillies and curry leaves.", "Allow the curry leaves to crackle.", "At this stage add the green moong sprouts, salt and steam cook it by covering the pan, and cook for about a minute and a half.", "You can optionally sprinkle a little water and cook, if you like to make the\u00a0Pachai Payaru Poriyal a little soft.Open the lid, turn off the flame, add the black pepper powder, lemon juice and coriander leaves.", "Give the\u00a0Pachai Payaru Poriyal a taste and adjust the salt and pepper according to taste and give it a good mix.", "Once done, transfer the\u00a0Pachai Payaru Poriyal to a serving bowl and serve warm or under room temperature as well.", "Serve Pachai Payaru Poriyal along with\u00a0Mysore Rasam Recipe,\u00a0Steamed Rice\u00a0\u00a0and\u00a0Curd Rice Recipe With Mint Flavour\u00a0for a simple healthy meal."]'::jsonb, 20, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/Pacha_Payaru_paruppu_poriyal_sprouted_green_moong_poriyal_recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/268.Pacha_Payaru_paruppu_poriyal_sprouted_green_moong_poriyal_recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Creamy and Delicious Fruit Custard Recipe', 'creamy-and-delicious-fruit-custard-recipe', 'Fruits Custard is a very healthy and delicious dessert. It has bunch of healthy fruits with creamy custard. This is very easy to make and healthy to eat dish. Custard is always liked by kids and adults as well.', '["750 ml Milk", "3 tablespoons Custard powder", "1/2 cup Sugar", "Fruits", "1 Apple , cut into small cubes", "3 Ripe Bananas , (small) cut into small cubes", "1/2 cup Green Grapes , cut into half", "1 Orange , peeled and cut", "1/4 cup Fresh Pomegranate Fruit Kernels"]'::jsonb, ARRAY['orange', 'bananas', 'milk', 'apple', 'sugar', 'green seedless grapes', 'pomegranate fruit kernels', 'custard powder']::text[], '["To begin making the Fruit Custard will first mix the custard powder with a little milk to form a smooth mixture with no lumps.", "Add the remaining milk and stir well.Place the custard milk in a saucepan and cook over medium heat and keep stirring continuously until you begin to see the custard thicken.", "It is important to keep stirring it continuously, else the custard mixture will form lumps and will not have a smooth texture.Once the custard thicken, add the sugar and stir well for another 3 to 4 minutes.", "Give it a taste, the custard should not feel raw, instead should be cooked well and taste creamy.Once the custard is cooked, allow the custard to cool completely.", "Once the custard is cooled, add in the chopped seasonal fruits and give it a stir.Serve the Fruit Custard recipe as an easy indian dessert for your parties or even for a simple sunday lunch."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/15-june/Recipe_For_Beginners_Fruit_Custard_Recipe_With_Custard_Powder-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/269.Recipe_For_Beginners_Fruit_Custard_Recipe_With_Custard_Powder-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharastrian Style Bharli Bhindi Recipe - Stuffed Bhindi With Coconut', 'maharastrian-style-bharli-bhindi-recipe-stuffed-bhindi-with-coconut', 'Maharashtrian Style Bharli Bhindi Recipe is a simple stuffed ladies finger with freshly ground Goda masala spices along with fresh coconut and coriander. The ladies finger is stuffed with this mixture and then sautéed on a flat tawa till it is soft and cooked. You can also pack it in your Lunch Box along with a Tawa Paratha.', '["500 grams Bhindi (Lady Finger/Okra)", "Salt , to taste", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Turmeric powder (Haldi)", "Ingredients to grind", "2 tablespoon Roasted Peanuts (Moongphali)", "8 sprig Coriander (Dhania) Leaves , chopped", "4 cloves Garlic", "1 Green Chilli", "Other ingredients for the stuffing", "4 tablespoon Fresh coconut", "1 tablespoon Maharashtrian Goda Masala , or garam masala", "1 teaspoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "1/2 Lemon juice", "1/2 teaspoon Sugar"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'maharashtrian goda masala garam masala', 'green chilli', 'mustard seeds', 'coconut', 'red chilli powder', 'cloves garlic', 'coriander (dhania) leaves', 'sugar', 'lemon', 'peanuts (moongphali)', 'bhindi (lady fingerokra)', 'coriander powder', 'turmeric powder']::text[], '["To begin making the Maharastrian Style Bharli Bhindi Recipe, wash the ladies finger and slit them in the middle, cut off the top head of the ladies finger and keep it aside.For the stuffing, grind the ingredients for the masala which includes roasted peanuts, green chili, cloves, coriander leaves in a mixer to a coarse paste.Combine this paste with the rest of the other ingredients like the coconut, turmeric powder, red chilli powder, coriander powder, cumin powder, goda masala (Garam masala), lemon juice and sugar.", "Check for salt and mix well.Start stuffing the ladies finger with this filling and keep aside the left over stuffing for later use.Heat a sauce pan, add oil, add mustard seeds and allow it to splutter for 2 seconds.Once it splutters, add the turmeric powder and stuffed bhindis.Saute well, and cover them for 2 minutes.", "Open the lid and sprinkle some salt and water and add the remaining stuffing and saute them for 2 more minutes.", "Cover and cook at low heat for 2 more minutes till the Bhindis are soft and properly cooked.Serve the\u00a0Maharashtrian Style Bharli Bhindi Recipe\u00a0along with\u00a0Tawa paratha,\u00a0Smoked Dal Makhani Dhaba Style Recipe\u00a0and\u00a0Boondi Raita\u00a0to enjoy your everyday dinner."]'::jsonb, 40, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Maharastrian_Style_Bharli_Bhendi_Recipe_Stuffed_Bhindi_with_Coconut_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/270.Maharastrian_Style_Bharli_Bhendi_Recipe_Stuffed_Bhindi_with_Coconut_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Matar Ajwain Ki Puri Recipe', 'matar-ajwain-ki-puri-recipe', 'Matar Ajwain Ki Puri is a simple and easy dish being very versatile as it can be had any time of the day, be it breakfast, lunch or dinner. It has the added goodness of peas and does not take too much time to prepare.', '["2 cups Whole Wheat Flour", "1 cup Green peas (Matar)", "5 to 6 Green Chillies", "1/4 cup Coriander (Dhania) Leaves , chopped", "1 teaspoon Ajwain (Carom seeds)", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Water , as needed", "Oil , to deep fry"]'::jsonb, ARRAY['s whole wheat flour', 'green peas', 'matar', 'to 6 green chillies', 'coriander', 'dhania', 'ajwain', 'carom seeds', 'cumin seeds', 'jeera', 'turmeric powder', 'haldi', 'salt', 'water', 'oil']::text[], '["To begin making the Matar Ajwain Ki Puri, first grind the peas along with green chillies and keep aside.In a bowl add wheat flour, turmeric, salt, chopped coriander, carom seeds, cumin seeds and mix them well.Now add the ground paste of peas & green chillies to the flour and mix well adding water little by little to knead it into a slightly stiff dough.Keep covered and set aside for 10 mins.Now make small golf sized portions, roll out into discs, dust dry flour as we make regular puris.Now deep fry them on medium-high heat until puffed up and slightly golden.Serve the\u00a0Matar Ajwain Ki Puri hot with some yogurt."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Swapna/Green_Peas_Poori_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/271.Green_Peas_Poori_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bajra Kaddu Ki Roti Recipe - Bajra Pumpkin Roti Recipe', 'bajra-kaddu-ki-roti-recipe-bajra-pumpkin-roti-recipe', 'Bajra Kaddu Ki Roti Recipe is a fiber rich roti made with millet flour, wheat flour and red pumpkin. Ginger, green chilies, ajwain and fresh coriander are added to the Bajra Kaddu Ki Roti for some added flavour. Making plain bajra rotis only with bajra flour are difficult to roll out and make hence addition of little whole wheat flour helps in rolling the rotis.', '["1/2 cup Bajra Flour ( Pearl Millet)", "1/2 cup Whole Wheat Flour", "1 cup Kaddu (Parangikai/ Pumpkin) , grated", "1/2 teaspoon Ginger , crushed", "1/2 teaspoon Green Chillies , crushed", "1/4 teaspoon Ajwain (Carom seeds)", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Lemon juice", "2 tablespoons Coriander (Dhania) Leaves , chopped", "Ghee , as required"]'::jsonb, ARRAY['bajra flour', 'pearl millet', 'whole wheat flour', 'kaddu', 'parangikai/ pumpkin', 'ginger', 'green chillies', 'ajwain', 'carom seeds', 'turmeric powder', 'haldi', 'asafoetida', 'hing', 'lemon juice', 's coriander', 'dhania', 'ghee']::text[], '["To begin making\u00a0Bajra Kaddu Ki Roti Recipe first take a mixing bowl and add all the ingredients listed except ghee and knead with water into a soft dough.Let the\u00a0Bajra Kaddu Ki Roti dough rest for 10 minutes.Divide the dough into 8 equal portions.", "Sprinkle little dry flour on table top, take a portion of dough and roll into a roti of 5 to 6 inch diameter.", "You can adjust the thickness of the roti based on your preference.", "Preheat the roti tawa and cook the Bajra Kaddu Ki Roti on medium heat for a few seconds until you see the rawness going away.", "Once you notice the\u00a0Bajra Kaddu Ki Roti getting small bubbles, smear ghee over the roti and cook on both sides on medium heat until golden brown and cooked on both sides.Proceed to cook the remaining\u00a0Bajra Kaddu Ki Roti the similar way and serve hot.Serve the\u00a0Bajra Kaddu Ki Roti Recipe with\u00a0Baingan Bharta,\u00a0Spicy Paneer Pulao With Vegetables,\u00a0Punjabi Methi Kadhi Recipe\u00a0and\u00a0Urad Dal Raita\u00a0for a wholesome and healthy indian lunch or dinner."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Affiliate-Articles/Bajra_Kaddu_Ki_Roti_Recipe_No_Onion_No_Garlic_Recipe-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/272.Bajra_Kaddu_Ki_Roti_Recipe_No_Onion_No_Garlic_Recipe-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Doddapatre Tambuli Recipe (Karpooravalli Thayir Pachadi)', 'doddapatre-tambuli-recipe-karpooravalli-thayir-pachadi', 'Doddapatre Tambuli Recipe is a popular healing, nourishing cold yoghurt curry from Karnataka. Doddapatre, also known as Big Thyme in English, Ajwain leaves in Hindi, Karpooravalli in Tamil, Owa in Marathi and Pani Koorka in Malayalam - is known to have a lot of medicinal values. It has a very distinct smell and flavour to it, which resembles camphor and is known to improve digestion, relieve chest congestion and have overall good health benefits. It also reduces skin related issues when crushed and the juice applied on sensitive areas. Tambuli is a cold yoghurt curry made by grinding a herb, vegetable or spice with coconut and a handful of spices. Sometimes it is also given a tempering which enhances the flavours. Serve this Doddapatre Tambuli along with hot Steamed Rice and ghee as the first course during a South Indian lunch or dinner.', '["4 cups Indian borage (Doddapatre) , cleaned and washed", "1/2 cup Curd (Dahi / Yogurt)", "1 tablespoon Cumin seeds (Jeera)", "1/2 teaspoon Whole Black Peppercorns", "1/4 cup Dessicated Coconut", "Salt , to taste", "2 tablespoons Ghee"]'::jsonb, ARRAY['salt', 'coconut', 'ghee', 'black peppercorns', 'indian borage (doddapatre)', 'curd', 'cumin seeds (jeera)']::text[], '["To begin making the Doddapatre Tambuli, first thoroughly wash the doddapatre leaves and wipe them dry between kitchen towels.Then place a kadai on the heat.", "Heat a tablespoon of ghee in it, and add the doddapatre leaves to the ghee.", "Sauce them gently on a medium heat until they change colour and sweat. continue to saute until all the water they release has evaporated.", "The leaves will change colour and reduce to half the quantity.Take them out of the kadai and transfer them into a mixer and set the jar aside.In the same kadai, dry roast jeera and black pepper corns till the jeera turns dark in colour and aromatic.", "Add these roasted spices also into the mixer jar.Add coconut, salt to the mixer too and grind it using half the quantity of yogurt, until it is a smooth paste.Transfer the paste into a serving bowl.", "Top it up with the remaining yogurt and whisk until it is smoothly combined.Place a tadka ladle on the heat and melt some ghee in it.", "When the ghee is warm, add the cumin seeds, allow them crackle, and pour the tempering over the tambuli.Mix well and serve child along with\u00a0Steamed Rice."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Raitas/Doddapatre_Tambuli_Recipe_Karuveppilai_Thayir_Pachadi-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/273.Doddapatre_Tambuli_Recipe_Karuveppilai_Thayir_Pachadi-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tamatari Chole Recipe', 'tamatari-chole-recipe', 'Tamatari Chole Recipe is recipe that you must give it a try as you will love it to have them with hot phulkas or butter flavored Naan. The chickpeas are soaked up in a tangy spicy flavored curry.', '["1 Cup Kabuli Chana (White Chickpeas)", "1 Onion , finely chopped", "1 Tomato , cut into wedges", "1 inch Ginger , grated", "2 cloves Garlic , mashed", "1 inch Cinnamon Stick (Dalchini)", "1 Cardamom (Elaichi) Pods/Seeds", "1 Bay leaf (tej patta)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "2 tablespoon Oil", "Salt , to taste", "4 sprig Coriander (Dhania) Leaves , roughly chopped for garnish", "Ingredients to Grind", "1 Onion , chopped", "2 Tomatoes , chopped", "1 Green Chilli"]'::jsonb, ARRAY['kabuli chana', 'white chickpeas', 'onion', 'tomato', 'ginger', 's garlic', 'cinnamon stick', 'dalchini', 'cardamom', 'elaichi', 'bay leaf', 'tej patta', 'turmeric powder', 'haldi', 'red chilli powder', 'garam masala powder', 'coriander powder', 'dhania', 'oil', 'salt', 'coriander', 'ingredients to grind', 'tomatoes', 'reen chilli']::text[], '["To begin making the Tamatari Chole Recipe, first wash and soak the chickpeas for 6 hours or overnight in 2 cups of water.Transfer chickpeas to Pressure Cooker with 2-1/2 cups of water and cook until for 6 to 7 whistles, turn the heat to low and cook for another 15 minutes until done.Grind all the ingredients mentioned in the list to form a smooth paste, you can add a little water and transfer it to a bowl.Heat oil in a saucepan over medium heat, add the grated ginger, onion and garlic and saute for few seconds.Stir in the ground paste, turmeric powder, coriander powder, garam masala, chilli powder and salt.", "Cook the mixture until the tomatoes and onions are well cooked and there is no raw smell.", "The mixture will thicken and come together.At this time add in the cooked chickpeas and tomatoes wedges, pour about 1 cup water.", "Stir to combine.", "Allow the mixture to come to a boil over medium heat.Once the mixture begins to boil, turn the heat to low and simmer the mixture for 20 to 30 minutes.", "Adjust the consistency and taste of the dish according to your taste, by adding water and spices.Serve the Tamatari Chole Recipe along with\u00a0Garlic Naan,\u00a0Burani Raita,\u00a0Carrot Cucumber Tomato Salad with Lemon and Coriander\u00a0by the side to make your dinner special."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Tamatari_Chole_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/274.Tamatari_Chole_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Delicious Methi Chicken Curry - Murgh Methi Curry Recipe', 'delicious-methi-chicken-curry-murgh-methi-curry-recipe', 'The Methi Chicken Curry Recipe is a delicious curry where the chicken is cooked along with methi/ fenugreek leaves with a spicy ginger garlic gravy. The addition of the tadka along with the fresh spices highlights the flavors of the methi chicken curry recipe.', '["300 grams Boneless chicken , cut into pieces", "1 cup Methi Leaves (Fenugreek Leaves) , roughly chopped", "3 Onions , finely sliced", "2 Tomatoes , finely chopped", "1 cup Curd (Dahi / Yogurt)", "10 cloves Garlic", "2 inch Ginger", "2 Green Chillies", "1/4 cup Coriander (Dhania) Leaves", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoons Garam masala powder , adjustable", "2 teaspoons Coriander Powder (Dhania)", "2 teaspoons Kasuri Methi (Dried Fenugreek Leaves)", "1 tablespoon Oil , to fry the onions", "1 teaspoon Oil", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "1 teaspoon Whole Black Peppercorns", "1 Bay leaves (tej patta)", "Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['tomato', 'boneless chicken', 'ginger', 'bay leaves (tej patta)', 'coriander (dhania) leaves', 'cardamom (elaichi) podsseeds', 'methi leaves (fenugreek leaves)', 'red chilli powder', 'cloves garlic', 'black peppercorns', 'curd', 'onion', 'kasuri methi (dried fenugreek leaves)', 'cinnamon stick (dalchini)', 'cloves (laung)', 'coriander powder', 'turmeric powder', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To begin making Methi Chicken Curry\u00a0recipe, firstly clean the chicken and wash thoroughly in sufficient water.", "Drain the water from chicken and cut into medium sized pieces.", "Keep them aside.Add garlic, ginger, green chillies and the coriander leaves into a mixer grinder and grind them into a paste using very little water.", "Keep it aside.Take a bowl and add curd, half of the green paste that we made above and half of the turmeric powder.", "Mix it well.", "Next add the chicken pieces into the bowl and coat the chicken with this coriander, ginger and garlic mixture.", "Once it is done, keep the chicken aside to marinate for about an hour.", "The next step is to make the gravy for the methi chicken curry.Heat oil in a heavy bottomed pan over medium heat.Once the oil is hot, add the sliced onions and saute adding a pinch salt to speed up the caramelization (browning).", "Keep stirring on low to medium heat constantly till the onions are lightly browned.The caramelised onions impart a delicious flavour to the Methi Chicken Curry.Turn off the heat and keep these onions aside to cool down a bit.", "When cooled down, grind to a fine paste in a mixer grinder.Heat oil into the same pan over medium heat.", "Add the whole spices mentioned for tempering which includes cloves, cinnamon stick, cardamom, black peppercorn and bay leaves.", "Saute until the aromas of the spices wafts in the air.", "Next add the remaining green coriander paste, the caramelized\u00a0onion paste and stir for a couple of minutes.", "Now add the remaining turmeric powder and the chopped tomatoes.", "Saute and cover the pan with a lid and cook until the tomatoes turn soft.Once the tomatoes are soft, add the red chilli powder, coriander powder, garam masala powder and mix well.", "Add the chopped methi leaves and saute till the leaves become soft.At this stage, add the marinated chicken with the entire marinade and saute on high flame for 2 to 3 minutes.When the chicken changes colour, add a cup of water and bring the mixture to a boil.", "Add salt to taste.", "Cover and cook the Methi Chicken Curry on medium heat stirring occasionally.", "It will take about 20 minutes to cook the chicken to perfection.When the chicken is fully cooked, add the kasuri methi and check seasoning.", "Adjust salt and other spices if desired.", "Cook uncovered on high flame for a few more minutes to thicken the Methi Chicken gravy.Once the gravy thickens, turn off the heat, transfer to a serving bowl and garnish it with coriander leaves.Serve\u00a0Methi Chicken Curry Recipe along with\u00a0Tawa Paratha,\u00a0Tomato Onion and Cucumber Raita\u00a0and\u00a0Jeera Rice\u00a0for a weekend dinner along with your friends and family."]'::jsonb, 100, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/panditp253-gmail.com/METHI_MURG__1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/275.METHI_MURG__1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Keerai Mandi Recipe With Amaranth Greens', 'chettinad-keerai-mandi-recipe-with-amaranth-greens', 'Chettinad cuisine is usually associated with its aromatic and spicy recipes. However, there are a few interesting recipes that are simple and flavourful, cooked in the Chettinad household''s every day. Chettinad Keerai Mandi Recipe With Amaranth Greens is one of those simple dishes cooked on a regular basis. Mandi means the leftover water after washing the rice in Tamil. The recipe uses very basic ingredients found in the kitchen, yet turns out to be pretty flavourful. The use of coconut milk is optional in the dish, however, the addition will make it even more richer. Keerai Mandi can be prepared using any greens of your choice. Here, we have used the Amaranth leaves. Serve the Chettinad Keerai Mandi Recipe along with Steamed Rice, Paruppu Urundai Kuzhambu and Beans Poriyal to make it a complete Chettinad style lunch over the weekend.', '["2 cups Green Amaranth Leaves , cleaned and finely chopped", "8 Shallots , finely chopped", "1 Green Chilli , finely chopped", "2 Dry Red Chillies", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon White Urad Dal (Split)", "1 cup Mandi , (leftover water from washing rice)", "1/4 cup Coconut milk , (optional but recommended)", "2 teaspoon Sesame (Gingelly) Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'green chilli', 'mustard seeds', 'sesame (gingelly) oil', 'white urad dal (split)', 'dry red chillies', 'mandi (leftover water from ing rice)', 'green amaranth leaves', 'coconut milk']::text[], '["To begin making Chettinad Keerai Mandi Recipe, clean, wash and finely chop the amaranth leaves or any greens of your choice and keep aside.Collect one cup of mandi water by washing the raw rice and keep aside.Heat oil in a pan on medium flame, add the mustard seeds, urad dal and let it crackle.Add the dried red chillies and let it splutter.Add the shallots, green chilly and saute until the onions turn translucent.Add the amaranth greens, season with salt and saute until the greens wilts.Add the mandi water and simmer for 2 minutes.Now, add the coconut milk, bring it to a rolling boil and switch off the flame.Serve the Chettinad Keerai Mandi Recipe along with Steamed Rice, Paruppu Urundai Kuzhambu and Beans Poriyal to make it a complete Chettinad style lunch over the weekend."]'::jsonb, 30, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Chettinad_Keerai_Mandi_Recipe_Chettinad_Style_Amaranth_Greens_Stew.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/276.Chettinad_Keerai_Mandi_Recipe_Chettinad_Style_Amaranth_Greens_Stew.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Simple Mutton Curry With Coconut Recipe', 'simple-mutton-curry-with-coconut-recipe', 'Goat curry or Mutton is one of the spicy, sizzling gravy prepared using tender goat meat cooked in lot of Indian Spices and coconut paste which is best if served with Indian bread. While preparing any goat curry, make sure that the goat meat is fresh. The more tender the goat meat, more easier it is to cook and tastes good. Whenever I prepare goat curry, I always reserve a little for me to eat after 3rd or 4th day. Try it all the taste of meat goes into the curry the more you keep it, but do not forget to refrigerate.', '["400 grams Mutton", "1 Onion , chopped", "1 tablespoon Ginger Garlic Paste", "1 cup Tomatoes , chopped", "8 Cloves (Laung)", "6 Whole Black Peppercorns", "1 inch Cinnamon Stick (Dalchini)", "1 teaspoon Fennel seeds (Saunf)", "2 Black cardamom (Badi Elaichi)", "2 Bay leaves (tej patta)", "6 Green Chillies , chopped", "1 tablespoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "4 sprig Curry leaves", "3 tablespoons Extra Virgin Olive Oil , adjustable", "Water , as required", "2 tablespoons Curd (Dahi / Yogurt)", "1 tablespoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1/2 cup Fresh coconut , grated (or dry)", "1/2 inch Ginger", "4 cloves Garlic", "Water , as required"]'::jsonb, ARRAY['tomato', 'black peppercorns', 'virgin olive oil', 'cloves garlic', 'curry leaves', 'onion', 'turmeric powder', 'green chillies', 'coconut (or dry)', 'black cardamom (badi elaichi)', 'salt', 'red chilli powder', 'water', 'curd', 'ginger', 'bay leaves (tej patta)', 'fennel seeds (saunf)', 'ginger garlic paste', 'cinnamon stick (dalchini)', 'mutton', 'cloves (laung)']::text[], '["To begin making the Simple Mutton Curry With Coconut recipe, make coconut paste using the ingredients mentioned under \u2018Coconut paste\u2019, in the grinder and keep aside.Wash goat pieces 3-4 times with water, drain well, add in all the ingredients mentioned under \u2018for marination\u2019 and mix properly.", "Set it aside for 30 minutes.Heat oil in a medium saucepan kept on medium heat and fry whole masala like cloves, pepper corns, cinnamon, fennel seeds, bay leaves and cardamom along with curry leaves and green chillies.Add onions and fry on medium high till translucent.", "Add chopped tomatoes and fry till mushy.Add ginger garlic paste and fry till raw smell goes away.", "Add red chilli powder, turmeric powder and salt.Mix and add little water.", "Add the marinated goat pieces, cover cook medium high till the pieces turn soft.Mix in between.", "Add water if required.", "Add coconut paste, mix and let it simmer on medium heat for 5 more minutes.Remove from heat and serve hot.", "Serve Simple Mutton Curry With Coconut along with\u00a0Whole Wheat Laccha Paratha\u00a0and\u00a0Burani Raita\u00a0for a weekend dinner."]'::jsonb, 80, 'South Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/simple_mutton_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/277.simple_mutton_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Broccoli, Carrot And Capsicum Sabzi Recipe', 'broccoli-carrot-and-capsicum-sabzi-recipe', 'Broccoli, Carrot and Capsicum Sabzi Recipe is a great combination different texture of vegetables in one dish. This dish won’t take much of your time and easy to carry it for your lunch box along with Phulka, Dal or even just some tossed Rice and Raita.', '["1 cup Broccoli , cut into medium heads", "2 Carrots (Gajjar) , sliced", "1 Green Bell Pepper (Capsicum) , chopped", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1 pinch Asafoetida (hing)", "1 teaspoon Black pepper powder", "1 Onion , chopped", "1 Tomatoes , chopped", "1 inch Ginger , chopped", "4 cloves Garlic , chopped", "1 Green Chilli , slit", "Salt , to taste", "Oil"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'green chilli', 'mustard seeds', 'asafoetida (hing)', 'cloves garlic', 'carrot', 'curry leaves', 'onion', 'black pepper powder', 'green bell pepper (capsicum)', 'broccolis', 'sunflower oil']::text[], '["To begin making the Broccoli, Carrot and Capsicum Sabzi Recipe, heat a kadai with oil, add mustard seeds, hing and allow the mustard seeds to splutter.Once the mustard seeds have crackled add curry leaves and allow it to crackle for few seconds.", "Add ginger and garlic and saute until it softens.After the ginger and garlic have softened add the chopped onions, and saute until the onions turn translucent.", "Once the onions have turned translucent add chopped tomatoes and sprinkle with little salt and cook till it becomes mushy.Once done add the chopped carrot, capsicum and sprinkle and cook it covered on low heat for about 5 minutes until the carrots become soft and cooked.Once done add broccoli, sprinkle some salt and pepper and cook it covered again for another 5 minutes.Serve the\u00a0Broccoli, Carrot and Capsicum Sabzi Recipe\u00a0along with\u00a0Phulka,\u00a0Dal Banjara\u00a0and\u00a0Lauki Raita\u00a0for your everyday meal."]'::jsonb, 35, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Broccoli_Carrot_and_Capsicum_Subzi_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/278.Broccoli_Carrot_and_Capsicum_Subzi_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Style Nadru Yakhni Recipe-Lotus Stem in Yogurt Sauce', 'kashmiri-style-nadru-yakhni-recipe-lotus-stem-in-yogurt-sauce', 'Nadru Yakhni Recipe is the Kashmiri Style Lotus Stem in Yogurt Sauce. Lotus roots/stem is very popular in Kashmiri cuisine. They are also called as Nandru or kamal kakdi. Lotus stem is used as an alternative for meat in most vegetarian cuisines.', '["1 cup Lotus Stem", "2 cups Curd (Dahi / Yogurt)", "1 tablespoon Gram flour (besan)", "1 teaspoon Dry ginger powder", "1 teaspoon Fennel seeds (Saunf) , powdered", "2 teaspoon Ajwain (Carom seeds)", "1 inch Cinnamon Stick (Dalchini)", "2 Black cardamom (Badi Elaichi)", "2 Cardamom (Elaichi) Pods/Seeds", "2 Cloves (Laung)", "1 Bay leaf (tej patta)", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Garam masala powder", "3 to 4 tablespoon Ghee", "Salt , to taste"]'::jsonb, ARRAY['black cardamom (badi elaichi)', 'salt', 'cardamom (elaichi) podsseeds', 'fennel seeds (saunf)', 'bay leaf (tej patta)', 'ajwain (carom seeds)', 'asafoetida (hing)', 'ghee', 'gram flour (besan)', 'curd', 'dry ginger powder', 'cinnamon stick (dalchini)', 'lotus stem', 'cloves (laung)', 'garam masala powder']::text[], '["To prepare Kashmiri Style Nadru Yakhni Recipe-Lotus Stem in Yogurt Sauce, peel the skin on lotus stem and slice them thin.", "Rinse well in water.", "Cook lotus stem in a Saucepan until tender.", "Do not overcook or mash it.In a bowl whisk together curd, water (about 3/4 cup) and besan well.Heat 3 tablespoon ghee in a Pan.", "Add cumin seeds fry for a minute.Pour in the whisked yogurt mix, simmer and bring to boil.", "Let it simmer for about 10 minutes.Now add the cooked lotus stem, sprinkle garam masala, saunf powder, and continue to cook on low flame for about 5 minutes.In another pan melt remaining ghee.", "Add cumin seeds and stir for 10-15 seconds.", "Next add cinnamon, cloves and cardamom, bay leaves and fry until aromatic.", "Sprinkle asafoetida on Kashmiri Style Lotus Stem in Yogurt Sauce and turn off flame.Pour this into the yogurt gravy, stir well.", "Turn off flame and serve immediately.", "You can garnish Nandru Yakhni Recipe with some dried mint before serving.Serve\u00a0Nadru Yakhni Recipe with\u00a0naan\u00a0for lunch or dinner."]'::jsonb, 60, 'Kashmiri', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Nandru_Yakhni__Kashmiri_Style_Lotus_Stem_in_Yogurt_Sauce.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/279.Nandru_Yakhni__Kashmiri_Style_Lotus_Stem_in_Yogurt_Sauce.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sprouted Horse Gram Thoran Recipe - No Onion No Garlic', 'sprouted-horse-gram-thoran-recipe-no-onion-no-garlic', 'Sprouted Horse gram Thoran Recipe is made without any onion and garlic making it a healthy sattvik recipe. Made with sprouted horse gram and cooked in a coconut, ginger and green chillies mixture it tastes amazingly good.', '["250 grams Horse Gram Dal (Kollu/ Kulith) , Sprouted", "1/2 cup Fresh coconut , grated", "1 Green Chilli", "1 teaspoon Cumin seeds (Jeera)", "1/2 inch Ginger", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "Salt , to taste", "1 Tomato , chopped - optional"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'green chilli', 'coconut', 'horse gram dal (kollu kulith) sprouted', 'red chilli powder', 'cumin seeds (jeera)', 'turmeric powder']::text[], '["To begin making Sprouted Horse Gram Thoran Recipe first sprout the horsegram if you are not buying store bought sprouts.Follow\u00a0How to make SproutsAdd the horse gram sprouts into the pressure cooker, sprinkle some salt, and 3 tablespoons of water.", "Pressure cook it for 3 to 4 whistles and turn off the heat.", "Allow the pressure to release naturally.", "Grind coconut, green chilli, cumin seeds, ginger to a course paste with little water in a mixer grinder.", "Heat oil in pan, add the tomato and add the ground paste and mix.", "Stir in the turmeric powder and red chilli powder and saute for a minute.Add the sprouted horse gram dal and salt to taste and stir fry for a about a minute.", "Check the salt and adjust to taste accordingly.Transfer the\u00a0Sprouted Horse Gram Thoran to a serving bowl and serve hot.Serve Sprouted Horse gram Thoran along with a\u00a0Kerala Avial,\u00a0Rasam, Rice\u00a0and\u00a0Homemade Yogurt\u00a0for a nice sattvik meal."]'::jsonb, 25, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/basic_recipes/Sprouted_Horsegram_Thoran_Recipe_No_Onion_No_Garlic_10_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/280.Sprouted_Horsegram_Thoran_Recipe_No_Onion_No_Garlic_10_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sauteed Spicy Prawns Recipe', 'sauteed-spicy-prawns-recipe', 'If you happen to quickly fix your lunch or dinner, these sauted prawns is one of the best option. Prawns are cooked in lots of sauteed garlic to give it a nice aroma. You can serve it with bread, add some noodles or even can be served as an appetizer.', '["400 grams Prawns", "5 cloves Garlic , grated", "1 Onion , finely chopped", "4 Spring Onion Greens , finely chopped", "3 sprig Coriander (Dhania) Leaves , chopped", "2 teaspoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "1 tablespoon Nando''s Peri Peri Chicken Sauce", "4 Tablespoons Extra Virgin Olive Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'spring onion greens', 'red chilli powder', 'cloves garlic', 'nando''peri peri chicken sauce', 'virgin olive oil', 'coriander (dhania) leaves', 'onion', 'turmeric powder', 'prawns']::text[], '["To begin making the Sauteed Spicy Prawns recipe, Deshell, devein the shrimps.", "Wash them well.Apply a teaspoon each of red chili powder, turmeric powder and salt.", "Mix well and marinate for about 10 minutes.Chop coriander leaves and keep aside.", "In a medium saucepan, heat oil.", "Fry onions on medium heat, till translucent.Add grated garlic and fry on low heat for few seconds.", "Add few scallions.Saute for a minute and add marinated shrimps.", "Mix well, cover and cook for about 10 minutes on medium heat.", "Remove cover.Add chopped coriander leaves, mix well, cover and cook for a minute.", "Remove the cover and add Peri peri sauce or hot sauce and mix.Remember, peri peri sauce already has salt, so I did not add extra salt in this recipe.", "Let it simmer on low heat for 5 more minutes.Switch off the flame.", "Remove on a serving plate and garnish with scallion greens.Serve Sauteed Spicy Prawns along with Shorshe Maach and Steamed Rice for a weekday meal."]'::jsonb, 35, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Affiliate-Articles/_Sauteed_Spicy_Prawns.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/281._Sauteed_Spicy_Prawns.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mangalorean Padengi Gassi Recipe - Green Moong Dal Curry', 'mangalorean-padengi-gassi-recipe-green-moong-dal-curry', 'The Mangalorean Padengi Gassi Recipe is a wholesome curry that is made from Sprouted Green Moong Dal.', '["1 cup Green Moong Dal (Whole) , sprouted", "1 Onion , finely chopped", "2 Tomatoes , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 cup Tamarind Water", "1 cup Fresh coconut , grated", "4 Dry Red Chillies", "2 teaspoons Coriander (Dhania) Seeds", "1/2 teaspoon Cumin seeds (Jeera)", "Ingredients for Seasoning", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "4 cloves Garlic", "2 Dry Red Chillies", "1 sprig Curry leaves"]'::jsonb, ARRAY['tomato', 'salt', 'tamarind water', 'coconut', 'mustard seeds', 'green moong dal sprouted', 'cloves garlic', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'onion', 'coriander (dhania) seeds', 'cumin seeds (jeera)', 'turmeric powder']::text[], '["To begin making the Mangalorean Padengi Gassi Recipe; do make sure you have some sprouts ready.", "Click to see how to make sprouts at home.Add the green moong sprouts, chopped onions and tomatoes into the pressure cooker.", "Add the turmeric powder, salt, and 2-1/2 cups of water and mix everything well.Cover the pressure cooker, place the weight on and cook until two whistles.", "After two whistles, turn the heat to low and simmer the green moong for about 5 minutes.", "Turn off the heat.Allow the cooker to release its pressure naturally.", "The Moong will continue to cook, as long as there is pressure in the cooker.*Method to make the Gassi MasalaWhile the pressure is releasing; we will go ahead and make the gassi curry paste.Place a small pan on medium heat; dry roast the red chilies, coriander seeds and cumin seeds until you smell the aromas coming out.", "You don\u2019t have to brown them too much.", "Once done, switch off the gas and let it cool down.Add the roasted condiments, along with the coconut to the blender.", "Add 1/4 cup of warm water and blend into a smooth gassi paste.*Making the Padengi GassiOnce the pressure is released from the pressure cooker; add the ground gassi masala to the cooked Sprouted Moong dal.", "Stir well to combine.", "Check the salt and spice levels and adjust to suit your taste.Place the pressure cooker on medium heat and start simmering the Padengi Gassi.While the Padengi Gassi is simmering, we will make the seasoning.In the same small pan where you dry roasted the chiles; heat a tablespoon of oil on medium heat.", "Add the mustard seeds, urad dal, red chilies and allow them to roast and crackle.", "Allow the dal to turn golden brown.Once it''s ready; add the garlic cloves and curry leaves.", "Stir-fry for a few seconds until you can smell the aromas of garlic and pour the seasoning into the simmering Padengi Gassi (Green Moong Dal Gassi)Serve the\u00a0Mangalorean Padengi Gassi Recipe/ Green Moong Dal Gassi along with\u00a0Kadalai Manoli,\u00a0Ghee Rice\u00a0and\u00a0Butter Milk\u00a0to make a delicious\u00a0lunch or dinner for your family."]'::jsonb, 55, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Mangalorean_Padengi_Gassi_Recipe_-_Sprouted_Green_Moong_Curry_-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/282.Mangalorean_Padengi_Gassi_Recipe_-_Sprouted_Green_Moong_Curry_-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chana Kanghou Recipe - Manipuri Style Kala Chana Sabzi', 'chana-kanghou-recipe-manipuri-style-kala-chana-sabzi', 'Manipuri Style Chana Kanghou Recipe is a dry sabzi made from black chickpeas. The cooking method in Manipuri is very simple and they use minimal spices to create a simple and humble dish. Manipur being one of the seven sister states, the cuisine hailing from Manipur is little different from the rest of north eastern areas. Their dishes usually prefer to use chilli peppers thus the result of it their dishes are very spicy.', '["1 cup Kala Chana (Brown Chickpeas)", "1 Onion , chopped", "1 Tomato , chopped", "2 Green Chilli , chopped", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "Salt and Pepper , to taste", "1 sprig Coriander (Dhania) Leaves", "Mustard oil , for cooking"]'::jsonb, ARRAY['tomato', 'salt', 'green chilli', 'mustard oil', 'red chilli powder', 'coriander (dhania) leaves', 'onion', 'cumin seeds (jeera)', 'pepper', 'coriander powder', 'kala chana (brown chickpeas)']::text[], '["To begin making the Manipuri Style Chana Kanghou Recipe, soak the chickpeas in water for about 4 hours or overnight.After soaking pressure cook the chickpeas in a pressure cooker with water and salt for about 5 whistle.", "After 5 whistles turn off the heat and let the pressure release naturally.Once the pressure has released open the pressure cooker and then strain the water from the chickpeas.", "Keep aside.Now heat a skillet with oil, add the cumin seeds and let them splutter.Once the cumin seeds have spluttered add the onions and green chillies.", "Saute the onions and green chilli till the onions become golden brown.Once done, add in the tomatoes and saute them well, you can add a little more salt to help cook the tomatoes faster.After the tomatoes have softened add in the red chilli powder, coriander powder and saute for a minute.Once done, add your cooked chickpea to the masala, 1/4 cup of water and keep mixing till the water evaporates and becomes little dry.Once done turn off the heat and transfer the Manipuri Style Chana Kanghou\u00a0 to a serving bowl.", "Garnish with coriander leaves and serve.Serve the\u00a0Manipuri Style Chana Kanghou Recipe\u00a0along with a\u00a0Palak Dal\u00a0and\u00a0Tawa Paratha\u00a0to make it a meal."]'::jsonb, 30, 'North East India', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Manipuri_Style_Chana_Kanghou_Recipe_Kala_Channa_Dry_Subzi_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/283.Manipuri_Style_Chana_Kanghou_Recipe_Kala_Channa_Dry_Subzi_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karwar Style Ambade Udid Methi Recipe - Hog Plum Curry', 'karwar-style-ambade-udid-methi-recipe-hog-plum-curry', 'Karwar Style Ambade Udid Methi Recipe (Hog Plum Curry) is a vegetarian curry from the Karwari Goud Saraswat Brahmin cuisine. Karwar, which is a city in Karnataka lies at the mouth of the river Kali. Coconut, Jaggery, Coriander Seeds and Red Dry Chillies form the base of most of the gravy dishes in the Karwari GSB cuisine. One such gravy made commonly in all homes there is udid methi which can be made using raw mangoes too instead of Ambade.', '["5 Hog Plum (Amtekai) , (Ambade)", "3/4 cup Fresh coconut , grated", "1/4 teaspoon Turmeric powder (Haldi)", "1 tablespoon Coriander (Dhania) Seeds", "1 teaspoon Black Urad Dal (Split)", "1 teaspoon Rice , (raw rice)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "6 Whole Black Peppercorns", "4 Dry Red Chilli", "2 tablespoons Jaggery", "1 pinch Asafoetida (hing)", "1 Karela (Bitter Gourd/ Pavakkai) , (Small)", "Salt , to taste", "2 teaspoons Oil", "2 teaspoons Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 pinch Asafoetida (hing)"]'::jsonb, ARRAY['salt', 'coconut', 'asafoetida (hing)', 'karela (bitter gourd pavakkai)', 'hog plum (amtekai) (ambade)', 'rice (raw rice)', 'jaggery', 'black peppercorns', 'black urad dal (split)', 'dry red chilli', 'mustard seeds', 'coriander (dhania) seeds', 'methi seeds (fenugreek seeds)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Karwar Style Ambade Udid Methi Recipe (Hog Plum Curry), firstly, scrape away the outer layer of the bitter gourd, clean it from inside and cut it into thin rings.", "Apply a bit of salt to it (I used 1/4 teaspoon), toss well to coat and keep aside for about an hour to do away with the bitterness of bitter gourd.", "After an hour, wash the chopped bitter gourd thoroughly and keep aside to drain.", "Use a little oil and roast the bitter gourd rings on low heat in a kadai till crisp.", "Peel and clean the Ambade meanwhile when the bitter gourd is roasting on low heat.", "Heat a little oil in a kadai (a few drops each time) and lightly roast the coriander seeds, urad dal, methi seeds, rice grains, peppercorns, asafoetida piece and dry red chillies separately on low heat.As soon as each ingredient changes its colour, remove from flame and keep aside to cool.Once cooled, grind all these ingredients in a mixer grinder along with the grated coconut, using required water to form a smooth paste.", "Add to this paste to a cup of water and mix well to form a semi-thick gravy and pour in the kadai.Now, add turmeric powder, ambade/hog plum/amtekai, jaggery, roasted bitter gourd rings, salt to taste and keep on a high heat stirring occasionally till it reaches boiling point.", "Once it starts boiling, lower the heat and simmer for about 8-10 minutes or till the ambade are cooked and soft.", "If you feel that the gravy has thickened too much by now, just add some water to bring back a medium consistency which is desirable.Check for seasoning and adjust salt and jaggery if required.", "In a tadka pan, heat a bit of oil for tempering and when the oil is hot, add mustard seeds and asafoetida.", "Pour this over the prepared udid methi.Serve Karwar Style Ambade Udid Methi Recipe (Hog Plum Curry) along with\u00a0Steamed Rice\u00a0and\u00a0Sol Kadhi\u00a0for a South Indian meal."]'::jsonb, 50, 'Coastal Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/panditp253-gmail.com/AMBADE_UDID_METHI_Recipe_edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/284.AMBADE_UDID_METHI_Recipe_edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Konkan Style Vali Bhajji Ambat Recipe-Spiced Malabar Spinach Dal', 'konkan-style-vali-bhajji-ambat-recipe-spiced-malabar-spinach-dal', 'Vali Bhajji Ambat Recipe is a dish that originates from North Kanara (Canara) which forms the part of Konkan Coast. The dish is a dal made from the green which is locally known as Malabar spinach.', '["2 cups Spinach Leaves (Palak) , Malabar, Chopped", "1/2 cup Arhar dal (Split Toor Dal)", "1 Onion , finely chopped", "1 Tomato , chopped", "30 grams Tamarind , mixed with water", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Jaggery , powdered", "Salt , to taste", "To grind", "1/2 cup Fresh coconut , grated", "1 tablespoon Coriander (Dhania) Seeds , roasted", "4-5 Dry Red Chillies", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "4 cloves Garlic , pound", "Oil , for cooking"]'::jsonb, ARRAY['tomato', 'salt', 'arhar dal (split toor dal)', 'coconut', 'mustard seeds', 'jaggery', 'tamarind mixed water', 'coriander (dhania) seeds', 'onion', 'dry red chillies', 'spinach leaves (palak) malabar', 'cloves garlic pound', 'turmeric powder', 'sunflower oil']::text[], '["We begin making the Vali Bhajji Ambat Recipe by heating a nonstick pan and roasting the coriander seeds, dry red chilies, and coconut.", "Keep it aside to cool down.", "Then grind it in a blender to a coarse paste.Clean the spinach leaves and chop them along with the stem.", "In a pressure cooker, saute the onions and add the tamarind water and the\u00a0tur dal along with spinach and tomato till it is done for about 3 whistles.", "Once done release the pressure naturally.Once done, using a muddler, muddle the dal and other ingredients\u00a0to a coarse curry.", "You can add some water in order to adjust seasoning.Heat a thick bottomed pan, add the ground paste and the dal \u00a0mixture.", "Adjust the consistency again and check for the seasoning.", "Add the jaggery to the dal once it starts boiling.In order to do the tempering take a small skillet and add oil, once it is heated then add the mustard seeds and garlic, then pour it onto the dal\u00a0mixture.Serve your\u00a0Vali Bhajji Ambat Recipe\u00a0with some steamed rice or\u00a0Phulka\u00a0and end it with\u00a0Paal Payasam Recipe\u00a0to make your meal complete."]'::jsonb, 55, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/oct-17/Vali_Bhajji_Ambat_Recipe_Konkan_Style_Spiced_Malabar_Spinach_Dal_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/285.Vali_Bhajji_Ambat_Recipe_Konkan_Style_Spiced_Malabar_Spinach_Dal_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Konir Dom Recipe (Assamese Egg & Potato Curry)', 'aloo-konir-dom-recipe-assamese-egg-potato-curry', 'Aloo Konir Dom is Assamese Egg and Potato Curry which is amazingly flavourful and also a bit spicy. Typically eaten with plain steamed rice and is an integral part of the daily meal. Usually the curry is made medium spicy but when served during special occasions, the curry look fiery red and hot.', '["4 Whole Eggs , boiled and peeled", "5 Potatoes (Aloo) , peeled & quartered", "2 Onion , chopped or grounded", "2 tablespoon Ginger Garlic Paste", "2 Tomatoes , ripe, sliced", "3 Green Chillies , slit", "Salt , Salt to taste", "2 tablespoon Oil , preferable Mustard oil (adjustable)", "1/2 cup Coriander (Dhania) Leaves , chopped", "Spices", "2 Bay leaf (tej patta)", "3 Dry Red Chilli", "1 teaspoon Cumin seeds (Jeera)", "2 Cardamom (Elaichi) Pods/Seeds", "4 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera)", "1 tablespoon Coriander Powder (Dhania)"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'coriander (dhania) leaves', 'bay leaf (tej patta)', 'cardamom (elaichi) podsseeds', 'sunflower oil preferable mustard oil', 'tomato ripe', 'ginger garlic paste', 'dry red chilli', 'onion', 'cumin seeds (jeera)', 'cinnamon stick (dalchini)', 'potato (aloo)', 'cloves (laung)', 'coriander powder', 'eggs', 'turmeric powder', 'green chillies']::text[], '["To begin making the Aloo Konir Dom recipe, take potato pieces and boiled eggs in a bowl, sprinkle around 1 teaspoon of turmeric and 1-2 pinch of salt and coat the potatoes and eggs.", "Keep aside.Heat oil in a wok/ pan till smoking hot.", "Add damped potatoes and fry them till golden in colour.Now add eggs in the oil and gently fry till golden.", "Transfer the potatoes and eggs in a plate and set aside.In the remaining oil add bay leaf and all other whole spices along with dry red chilies.", "Wait till they crackle, and then add chopped onions and saute them till golden in colour.Add ginger garlic paste and slit green chilies and fry them with onion until brown in colour.Now add in the chopped tomatoes along with cumin powder, coriander powder, turmeric powder and garam masala powder.", "Stir well and fry till oil starts leaving sides.Add little water if you see the masala sticking for bottom.Once the masala is fried nicely and the oil has oozed out from the sides, add fried potatoes and mix well.Fry for another 2 mins and add water as per required consistency.Adjust salt as needed and drop in the eggs in the curry.Let the curry come to a boil, then simmer the flames and cover the lid.", "Let the curry cook till potatoes are tender and soft.Remove from stove, and garnish with plenty of chopped coriander and serve hot with plain steamed rice.Serve Aloo Konir Dom along with\u00a0Whole Wheat Lachha Paratha,\u00a0Boondi Raita\u00a0and\u00a0Kachumber Salad\u00a0for a weekday lunch or dinner."]'::jsonb, 45, 'Assamese', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/shaheen_ali/Aloo_Konir_Dom__Assamese_Egg__Potato_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/286.Aloo_Konir_Dom__Assamese_Egg__Potato_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hyderabadi Shahi Mixed Vegetable Curry Recipe', 'hyderabadi-shahi-mixed-vegetable-curry-recipe', 'The Hyderabadi Shahi Mixed Vegetable Curry Recipe is a rich gravy dish that has a creamy texture, lots of vegetables, has a spicy taste and is packed with flavors. The addition of almond paste into the recipe adds great flavors and the richness to the Shahi Mixed Vegetable Curry.', '["12 Baby Potatoes , boiled peeled and cubed", "1/4 cup Green peas (Matar)", "2 Carrots (Gajjar) , diced", "10 Green beans (French Beans) , cut into 2 inch pieces", "1 Red Bell pepper (Capsicum) , diced", "1 Yellow Bell Pepper (Capsicum) , diced", "2 tablespoons Sultana Raisins", "1/4 cup Tomato , puree", "1 Onion , finely chopped", "3 cloves Garlic", "1 inch Ginger", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Cumin powder (Jeera)", "1 Bay leaves (tej patta)", "3 tablespoons Cashew nuts", "3 tablespoons Fresh cream", "2 sprig Coriander (Dhania) Leaves , finely chopped", "Salt , as per taste", "Oil , for cooking"]'::jsonb, ARRAY['yellow bell pepper (capsicum)', 'tomato', 'cumin powder (jeera)', 'cloves garlic', 'carrot', 'onion', 'turmeric powder', 'sunflower oil', 'salt', 'red bell pepper (capsicum)', 'raisins', 'baby potatoes', 'garam masala powder', 'green beans (french beans)', 'red chilli powder', 'cashew nuts', 'ginger', 'bay leaves (tej patta)', 'green peas (matar)', 'coriander (dhania) leaves', 'coriander powder']::text[], '["To begin making the Hyderabadi Shahi Mixed Vegetable Curry Recipe, we will first prepare the vegetables for the curry.", "Boil the potatoes, either in water or in the pressure cooker\u00a0for about 3 whistles until just about cooked.", "Once cooked allow the potatoes to cool a bit, peel the skin and dice the baby potatoes.", "Keep this aside.Steam the remaining vegetables in a\u00a0steamer until just about cooked through.", "Take care to not over cook them.", "The steamer takes just about 5 minutes to cook the vegetables on high heat.", "Once cooked keep aside.Heat couple of teaspoons of oil in a heavy bottomed pan, add the onions, ginger and garlic and saute until soft and lightly browned and the raw smell has gone away.", "Turn off the heat and allow it cool.", "Once cooled, make a paste of the onion ginger and garlic - keep this aside.Make the tomato puree according to the recipe on the link and keep aside.Make a paste of the cashew nuts adding little water to make a smooth cream like paste.", "Keep this cashew nut paste aside.The next step is to begin cooking the Shahi Vegetable Curry.In the same heavy bottomed pan we cooked the onion, add a teaspoon of oil.", "Add the red and yellow bell peppers and stir fry them until they are softened and well roasted.Add the onion garlic paste, bay leaf and turmeric powder.", "Saute the onion mixture until the paste is cooked and comes together and leaves oil around the edges.Next, add tomato puree along with red chili powder, bay leaf, coriander powder, cumin powder, salt and garam masala.", "Stir until everything is completely combined.Give the Shahi Curry mixture a brisk boil and add in the cooked potatoes and steamed vegetables.", "Turn the heat to low, add a little water, cover the pan and simmer the\u00a0Hyderabadi Shahi Mixed Vegetable Curry for about 5 minutes until all the vegetables get the flavors of the masala.Finally stir in the cashew nut cream and the fresh cream into the Shahi Curry and simmer for another 3 to 4 minutes.", "Turn off the heat.", "Check the salt and spice levels and adjust to suit your taste.Stir in the chopped coriander leaves and serve.Serve the\u00a0Shahi Mixed Vegetable Curry\u00a0along with\u00a0Whole Wheat Lachha Paratha Recipe,\u00a0Palak Raita\u00a0and Pickle for a weeknight dinner or even as a main course for a party."]'::jsonb, 70, 'Hyderabadi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Lubna_Karim/Hyderababi_Shahi_Mixed_Vegetable_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/287.Hyderababi_Shahi_Mixed_Vegetable_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sepu Vadi Recipe (Himachali Split Urad Dal Dumplings In Spinach Gravy)', 'sepu-vadi-recipe-himachali-split-urad-dal-dumplings-in-spinach-gravy', 'Sepu Vadi Recipe (Split Urad Dal Dumplings In Spinach Gravy) is a specialty from Himachal Pradesh. Split Black Urad Dal dumplings are first steamed and then fried. They are then added to the Spinach-Curd gravy, that is flavoured with basic spices powders and whole spices. Addition of dill leaves and saunf powder makes this recipe different from the usual palak gravy dishes. Traditionally the recipe is cooked in mustard oil, but you can use any cooking oil.Serve Sepu Vadi Recipe (Split Urad Dal Dumplings In Spinach Gravy) with Papad Parathas Recipe, Pudina Tawa Paratha (Mint Leaf Skillet Flat Bread) or steamed rice.', '["1/2 cup Black Urad Dal (Split) , soaked overnight", "1-2 Green Chillies , chopped", "1 inch Ginger", "Salt , to taste", "1 pinch Enos Fruit Salt , or soda", "1/4 teaspoon Lemon juice", "1/4 teaspoon Oil , \u00bc and more for frying vadis", "200 grams Spinach", "1 cup Curd (Dahi / Yogurt)", "1 tablespoon Mustard oil", "1 Dry Red Chilli , deseeded", "2 Cloves (Laung)", "1 Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds , pounded", "1 Bay leaf (tej patta)", "1/2 teaspoon Cumin seeds (Jeera)", "1 Green Chilli , finely chopped", "1 pinch Asafoetida (hing)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Fennel Powder", "1/4 teaspoon Black pepper powder , freshly crushed", "1 teaspoon Dill leaves", "Salt , to taste"]'::jsonb, ARRAY['cumin powder (jeera)', 'dill leaves', 'asafoetida (hing)', 'cumin seeds (jeera)', 'black pepper powder', 'green chillies', 'salt', 'green chilli', 'spinach', 'mustard oil', 'cardamom (elaichi) podsseeds', 'red chilli powder', 'dry red chilli', 'curd', 'fennel powder', 'lemon', 'enos fruit salt soda', 'ginger', 'bay leaf (tej patta)', 'black urad dal (split)', 'cinnamon stick (dalchini)', 'coriander powder', 'sunflower oil vadis', 'cloves (laung)']::text[], '["To make Sepu Vadi Recipe (Himachali Split Urad Dal Dumplings In Spinach Gravy), make the dumplings by washing and soaking urad dal (split black gram) in about 1.5-2 cups water overnight.Drain and wash the dal.Heat water in a steamer and let it boil.In a blender/grinder jar, combine washed and drained urad dal, ginger, green chilli and grind to make a smooth paste adding about \u00bc cup water gradually, so that the mixture is very thick and forms a paste.Take the paste in a bowl and add salt.", "Whisk it well till it becomes light and fluffy.Add eno and lemon juice and immediately transfer the mixture to a greased plate and steam for about 15-20 minutes.Remove from steamer and insert a toothpick to check whether it is done.", "If toothpick comes out clean, our vadi is ready.", "If it doesn\u2019t come out clean, steam for another few minutes more.Meanwhile heat enough oil in a deep frying pan to fry the vadis.Cut the steamed vadis into square pieces.Deep fry the vadi pieces in hot oil till they are crisp and golden in colour.For the Palak PureeSoak Palak leaves in a bowl of water and pinch of salt for about 5 minutes.Remove the stems from the leaves.", "Roughly chop the leaves.Add water in a wide pan and bring to a boil.", "Then add spinach leaves and cook for 2 minutes.Immediately remove and soak the leaves in a bowl of ice cold water for a minute.", "Drain all the excess water.In a mixer/blender jar, add blanched palak leaves, dill leaves and about 1-2 tablespoons water and blend till you get a smooth puree.Keep the spinach puree aside."]'::jsonb, 55, 'Himachal', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Bela-Dholakia/Sepu_Vadi_Split_Urad_Dal_Dumplings_in_Spinach_Gravy_recipe_edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/288.Sepu_Vadi_Split_Urad_Dal_Dumplings_in_Spinach_Gravy_recipe_edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kadai Mushroom Recipe', 'kadai-mushroom-recipe', 'The Kadai Mushroom recipe is a simple, healthy and delicious recipe that is packed with flavours from the spices like badi elaichi. The roasting the the vegetables along with onions, capsicum and mushrooms brings out the flavours of the dish.', '["250 grams Button mushrooms , quartered", "1 teaspoon Cumin seeds (Jeera)", "1 Onion , cut into chunks", "4 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "1 Green Bell Pepper (Capsicum) , diced", "1 Red Bell pepper (Capsicum) , diced", "1 Carrot (Gajjar) , sliced into rounds", "2 Tomato , pureed", "2 Brown cardamom (Badi Elaichi)", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "1 teaspoon Ghee", "Salt , to taste", "1 teaspoon Honey"]'::jsonb, ARRAY['tomato', 'turmeric powder', 'salt', 'ginger', 'black peppers', 'capsicum (green)', 'coriander (dhania) leaves take cumin seeds', 'cinnamon', 'red chilli powder', 'water', 'fenugreek seeds', 'onion', 'garlic', 'coriander powder', 'bay leaves', 'button mushroom', 'oil', 'green chillies']::text[], '["To begin making the Kadai Mushroom recipe, first prep all the ingredients and keep them ready.Preheat ghee in a wok or a kadai over medium heat.", "Add the cumin seeds and allow it to crackle.", "Add the ginger, garlic and saute for a few seconds.Next add the onions, bell peppers and carrots and saute until the vegetables are well roasted and cooked.", "It should have a firm bite.Once the vegetables are well roasted, add the mushrooms, tomato puree, badi elaichi, turmeric powder, red chilli powder, coriander powder, cumin powder, garam masala powder salt, kasuri methi and honey.", "Give it a stir, cover the pan and simmer until the mushroom are cooked.", "This will take about 3 to 4 minutes over medium heat.", "Once done, check the salt and spices of the Kadai Mushroom Sabzi and adjust according to taste.Once done, turn off the heat and transfer the Kadai Mushroom to a serving bowl and serve hot along with phulka or jeera rice."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Kadai_Mushroom_Recipe_7_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/289.Kadai_Mushroom_Recipe_7_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Uttarakhand Aloo Ke Gutke Recipe', 'uttarakhand-aloo-ke-gutke-recipe', 'Let us learn a very easy potato recipe of Uttaranchali dishes. A traditional vegan recipe Aloo Ke Gutke which is simply prepared with mustard oil and spice powder mix. Serve with rice and dal or just simply with roti. It is very easy to make, takes less time to prepare and thus you can pack it for your lunch box also.', '["3 Potatoes (Aloo)", "2 teaspoon Mustard oil", "1/4 teaspoon Red Chilli powder", "1/8 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Turmeric powder (Haldi)", "2 Dry Red Chilli", "2 pinch Asafoetida (hing)", "Salt , to taste", "Coriander (Dhania) Leaves , few for garnish (chopped)"]'::jsonb, ARRAY['salt', 'mustard oil', 'asafoetida (hing)', 'coriander (dhania) leaves', 'red chilli powder', 'dry red chilli', 'cumin seeds (jeera)', 'coriander powder', 'potato (aloo)', 'turmeric powder']::text[], '["To begin making the Uttarakhand Aloo Ke Gutke Recipes, firstly boil the potatoes with little salt to begin making Aloo Ke Gutke recipe.", "Add potatoes with required water in a pressure cooker and salt and close it with a lid.Pressure cook it for 5 whistles and let the pressure release naturally.", "Once done, open the cooker, peel the potatoes and them cut into cubes.Take a small bowl and mix coriander powder, red chilli powder and turmeric powder with 2 teaspoons water.Heat a frying pan with oil, add cumin seeds, asafoetida and red chilli.", "Let it cook for about 15 seconds.", "After 15 seconds, add the mixed masala and salt.", "After 30 seconds add the potatoes and coat well with the masala.", "Let it cook for about 5 minutes.Once it is done, switch off the gas stove and garnish with coriander leaves.", "Serve\u00a0Uttarakhand Aloo Ke Gutke along with\u00a0Navrang Dal\u00a0and\u00a0Mooli Paratha\u00a0for a weekday lunch.", "You can also pack it in your Lunch Box."]'::jsonb, 40, 'Uttar Pradesh', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/ruby_pathak-yahoo.com/Uttarakhand__Aloo_Ke_Gutke.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/290.Uttarakhand__Aloo_Ke_Gutke.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Moong Bean Sprouts Upkari Recipe - Moong Beans Stir Fry', 'moong-bean-sprouts-upkari-recipe-moong-beans-stir-fry', 'A simple and highly nutritious quick dry curry made with Moong Bean sprouts cooked in simple but exotic Indian spices. This recipe is best to serve during your weekday lunch or dinner and you can even pack it for your lunch box or your kids lunch box.', '["2 cups Green Moong Sprouts", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "3 Dry Red Chillies , broken into 2 to 3 pieces", "1/2 teaspoon Asafoetida (hing) , optional", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "2 tablespoons Fresh coconut , grated", "2 teaspoons Coconut Oil"]'::jsonb, ARRAY['s green moong sprouts', 'cumin seeds', 'jeera', 'mustard seeds', 'rai/ kadugu', 'dry red chillies', 'asafoetida', 'hing', 'turmeric powder', 'haldi', 'salt', 's fresh coconut', 's coconut oil']::text[], '["To begin making the Moong Bean Sprouts Upkari Recipe, we will sprout the moong beans firstly.Take 1 cup of moong beans and wash thoroughly in water.", "Drain and soak in plenty of water for at least 6 to 8 hours or even overnight.Next day, drain the soaked beans thoroughly and place in a large bowl; make sure there is some moisture left in the beans.Close the bowl with a lid and keep in a warm place to allow the mung beans to sprout for about 8 to 12 hours, depending upon the weather.", "Mung beans start sprouting faster in warm weather.", "After you have got the desired length of sprouts, you can use it in any dish you like.To make the Moong Bean Sprouts Upkari Recipe, heat coconut oil in a heavy bottomed pan.Once the oil is hot, add mustard seeds and once they begin to crackle, stir in the cumin seeds, dry red chillies and hing.", "Saut\u00e9 for a few seconds.Immediately add 2 cups of bean sprouts, turmeric powder and salt to taste; give it a good stir.Sprinkle some water and close the pan with a tight lid.", "Let the sprouts cook in its own steam.As soon as the sprouts are cooked to the texture you like (some people prefer it soft and some with still a bite in it, like the way I do), stir in the grated coconut.Heat through for about a minute and remove from heat.", "Serve hot.Serve Moong Bean Sprouts Upkari Recipe along with\u00a0Methi Chaman\u00a0and\u00a0Phulkas\u00a0for a weekday meal with family."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Curryandvanilla/Mung_Bean_Sprouts_UpkariStir_Fry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/291.Mung_Bean_Sprouts_UpkariStir_Fry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Badami Paneer Masala Recipe -Paneer In Almond Gravy', 'badami-paneer-masala-recipe-paneer-in-almond-gravy', 'Badami Paneer Masala Recipe is a delicious and rich paneer recipe cooked in a rich almond based gravy. The almond renders an amazing nutty taste and the sweetness of almond is balanced with the other mild spices added to the recipe. Almonds and onions are made into a paste and then cooked along with tomato puree and spices. Then the fried paneer is added and served.', '["300 grams Paneer (Homemade Cottage Cheese) , cut into triangles", "1/2 cup Whole Almonds (Badam)", "2 Onions , roughly chopped", "4 Tomatoes , roughly chopped", "1 tablespoon Ginger , roughly chopped", "4 cloves Garlic", "3 Dry Red Chillies", "2 teaspoons Coriander Powder (Dhania)", "2 teaspoons Kashmiri Red Chilli Powder", "1 teaspoon Garam masala powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Sugar", "1 Bay leaf (tej patta)", "1 tablespoon Ghee , or oil", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'kashmiri red chilli powder', 'bay leaf (tej patta)', 'paneer', 'cloves garlic', 'sugar', 'dry red chillies', 'badam (almond)', 'onion', 'ghee', 'oil', 'coriander powder', 'turmeric powder', 'garam masala powder']::text[], '["To begin making\u00a0Badami Paneer Masala Recipe, soak the almonds in a bowl of hot water for about 10 minutes, de-skin and keep them aside (or you can blanch them in microwave oven)Marinate the paneer in turmeric and a teaspoon of kashmiri red chilli powder and marinate for about 5 minutes.Puree the raw chopped tomatoes using a mixer grinder and keep aside.Make a fine paste of 1/4 cup almonds, ginger, garlic, onions and red chillies using a mixer grinder and keep aside.Heat a tablespoon of ghee or oil in a pan and shallow fry the marinated paneer till they are cooked to about 3/4th and keep aside.In the same pan on a medium heat, add the remaining tablespoon of ghee, add in the bay leaf and let it flavour the ghee for about half a minute.Once done, add the ground almond and onion paste, saute until the raw smell of the masala goes away.Add in the tomato puree and saute until the rawness of tomato is completely gone away and the onion paste is cooked as well.Add the coriander powder, kashmiri red chilli powder, garam masala and mix well.Add 1.5 cups of water, season with salt and bring it to a rolling boil.Now, add the partially fried paneer triangles, and the remaining almonds, simmer for 10 minutes.Switch off the heat and garnish with onion rings.Serve the\u00a0Badami Paneer Masala Recipe along with\u00a0Butter Naan Recipe,\u00a0Bhindi Masala Recipe,\u00a0Mooli Raita Recipe,\u00a0and\u00a0Khatti Meethi Dal Chawal Recipe\u00a0for a Friday night dinner."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Badami_Paneer_Masala_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/292.Badami_Paneer_Masala_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thengai Paal Kurma Recipe - Mixed Vegetables In Coconut Gravy', 'thengai-paal-kurma-recipe-mixed-vegetables-in-coconut-gravy', 'Thengai Paal Kurma Recipe is often known as Vellai Kurma and is commonly known curry in chettinad area. Tender vegetables like cauliflower, potato and peas are cooked with green chillies and coconut milk. This can be prepared in few minutes and green chilies are enough for the spiciness. The addition of coconut milk adds a creamy texture and rich flavour to the gravy. Coconut milk is the only thickening agent in the curry. Potatoes also give this Thengai Paal Kurma a little volume.', '["2 Potato (Aloo)", "1/2 cup Green peas (Matar)", "1 cup Cauliflower (gobi) , florets", "1 Onion , chopped", "3 to 4 Green Chillies , slit vertically (adjust the number of chilies according to your spice level)", "1 inch Cinnamon Stick (Dalchini)", "3 Cardamom (Elaichi) Pods/Seeds", "3 Cloves (Laung)", "1 Bay leaf (tej patta)", "1 tablespoon Ghee , oil", "1 cup Coconut milk , thick", "Salt , as required"]'::jsonb, ARRAY['salt', 'cardamom (elaichi) podsseeds', 'bay leaf (tej patta)', 'potato (aloo)', 'green peas (matar)', 'onion', 'cinnamon stick (dalchini)', 'green chillies verticy ( the number chillies spice level)', 'ghee', 'oil', 'coconut milk', 'cloves (laung)', 'cauliflower (gobi) florets']::text[], '["To begin making the Thengai Paal Kurma Recipe, pressure cook the potatoes for two whistles and cut them into small cubes.Steam the cauliflower florets and peas and keep them aside.Heat ghee/oil in a kadai/wok and once the oil is hot add cinnamon, cardamom, cloves and bay leaf.", "Saute for a few seconds till the aromas are released.", "Once done add onion,chilies and cook until onions become transparent.After the onions have become transparent add the cooked potatoes, cauliflower florets and peas.Add salt and a cup of water.", "Once the water starts boiling, add thick coconut milk and cook over medium heat for about 5 minutes.Adjust coconut milk according to suit your taste.", "If the gravy is too watery you can mash a few pieces of potato in the gravy to make the gravy thicker.", "Once the gravy has reached the desired consistency turn off the heat and transfer the\u00a0Thengai Paal Kurma\u00a0 into a serving bowl and serve.Serve\u00a0Thengai Paal Kurma Recipe\u00a0with\u00a0\u00a0Appam\u00a0or\u00a0Idiyappam\u00a0or\u00a0Kerala Style Whole Wheat Parotta\u00a0for a perfect meal."]'::jsonb, 50, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Thengai_Paal_Kuruma.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/293.Thengai_Paal_Kuruma.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mavinakayi Menasinakai Curry Recipe  - Raw Mango Coconut Curry', 'mavinakayi-menasinakai-curry-recipe-raw-mango-coconut-curry', 'Mangalorean Mavinakayi Menasinakai Curry Recipe-Raw Mango Coconut Curry made with roasted and ground spices with fresh grated coconut. There is a distinguished aroma emanating from the curry due to sesame seeds added to the masala.', '["1 cup Mango (Raw) , diced", "2 tablespoons Jaggery", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 cup Tamarind Water", "Salt , to taste", "1 cup Fresh coconut , grated", "2 teaspoons White Urad Dal (Split)", "1 teaspoon Chana dal (Bengal Gram Dal)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1/2 teaspoon Cumin seeds (Jeera)", "2 teaspoons Sesame seeds (Til seeds)", "4 Dry Red Chillies , (adjust)", "2 teaspoons Coconut Oil", "1/4 teaspoon SSP Asafoetida (Hing)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "Curry leaves , a few"]'::jsonb, ARRAY['salt', 'tamarind water', 'coconut', 'asafoetida (hing)', 'mustard seeds', 'jaggery', 'curry leaves', 'mango', 'white urad dal (split)', 'dry red chillies', 'sesame seeds (til seeds)', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'coconut oil', 'turmeric powder', 'chana dal (bengal gram dal)']::text[], '["To begin making Mangalorean Mavinakayi Menasinakai Curry Recipe cut the peeled raw mango into bite sized pieces and discard the stone/seed.Into a pressure cooker add the raw mango, tamarind water, jaggery, turmeric powder, salt to taste and pressure cook for 2 whistles and turn off the heat.", "Allow the pressure to release naturally.Meanwhile we can make the ground coconut masala.Into a preheated pan add urad dal, chana dal, methi seeds, cumin seeds, sesame seeds and dry red chillies and roast on medium heat until the dal is golden brown and crisp.", "Keep aside to cool.Add the roasted dal into a mixer grinder along with coconut,1/2 cup warm water and blend into a smooth paste.Add the ground mixture into the mango curry and add more water to adjust the consistency.", "Bring\u00a0Mangalorean Mavinakayi Menasinakai Curry to a brisk boil."]'::jsonb, 35, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Raw_Mango_Coconut_Curry__Mavinakayi_Menasinakai_Curry_Recipe_11_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/294.Raw_Mango_Coconut_Curry__Mavinakayi_Menasinakai_Curry_Recipe_11_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Bassaru Palya Recipe - Toor Dal And Dill Leaves Stir Fry', 'karnataka-style-bassaru-palya-recipe-toor-dal-and-dill-leaves-stir-fry', 'Karnataka Style Bassaru Palya Recipe is a recipe that is obtained from the Bassaur which is prepared in most of the households in Karnataka. Bassauru is nothing but a Rasam made with the drained water of the Toor Dal and dill leaves, which is thus made into a playa.', '["1 cup Arhar dal (Split Toor Dal)", "1/2 cup Dill leaves", "1 Onion , chopped", "4 cloves Garlic , crushed", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies", "1 teaspoon White Urad Dal (Split)", "1 teaspoon Chana dal (Bengal Gram Dal)", "1 sprig Curry leaves", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'arhar dal (split toor dal)', 'dill leaves', 'mustard seeds', 'cloves garlic', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'onion', 'turmeric powder', 'chana dal (bengal gram dal)']::text[], '["To begin making the Karnataka Style Bassaru Palya Recipe, firstly pressure cook the toor dal with 2 cups of water in a pressure cooker, add a little salt as well.", "Cook for about 2 whistle.Then once done, add in the dill leaves, and add about 1/2 cup of water and pressure cook again for about 1 whistle.Once done, drain all the water and keep the cooked dal and dill leaves.Heat a kadai with oil, and crackle the mustard seeds, urad dal, chana dal, dry red chilli and curry leaves.Add in onions and garlic and saute till it translucent.", "Then add in the cooked dal mixture and give it stir, season it with salt and turmeric powder.", "Mix well and serve.", "Serve the\u00a0Karnataka Style Bassaru Palya Recipe\u00a0along with\u00a0Keerai Sambar\u00a0and\u00a0Steamed Rice\u00a0for your everyday meals or serve it along with\u00a0Tawa Paratha\u00a0and\u00a0Boondi Raita."]'::jsonb, 25, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Karantaka_Style_Bassaur_Palya_Recipe_Toor_dal_and_dill_leaves_stir_fry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/295.Karantaka_Style_Bassaur_Palya_Recipe_Toor_dal_and_dill_leaves_stir_fry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pesara Pappu Pulusu Recipe', 'pesara-pappu-pulusu-recipe', 'Pesara Pappu Pulusu Recipe is a simple comfort food, made using yellow moong dal. The addition of tamarind and a lovely tadka over it, packs it with all the flavours.', '["1/2 cup Yellow Moong Dal (Split)", "Water , as needed", "2 tablespoons Tamarind Paste , (adjust)", "2 Tomatoes", "1 Green Chilli , slit", "1 sprig Curry leaves", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 Dry Red Chilli", "1/4 teaspoon Asafoetida (hing)", "1 pinch Turmeric powder (Haldi)", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'yellow moong dal (split)', 'green chilli', 'mustard seeds', 'asafoetida (hing)', 'water', 'dry red chilli', 'curry leaves', 'cumin seeds (jeera)', 'tamarind paste', 'turmeric powder', 'sunflower oil']::text[], '["To begin making Pesara Pappu Pulusu Recipe, pressure cook moong dal with a cup of water till cooked, for about 2 whistles.Once the pressure releases, mash the dal with a potato masher, add salt and turmeric and a cup of water.", "Keep aside.", "In a heavy bottomed pan, heat some oil add in chopped tomatoes, curry leaves and green chillies and saute for two minutes.", "Once the tomatoes are mushy, add the dal to this mixture.", "Stir until all the ingredients combine.", "Add tamarind puree and mix well.", "Cover the pan and simmer for about 5 minutes.In a tadka pan, heat oil on low flame, mustard seeds, cumin seeds and red chilli.", "When the seeds start to splutter turn off heart, add hing and pour this tempering to the dal mixture.", "Serve\u00a0Pesara Pappu Pulusu Recipe with\u00a0Steamed Rice,\u00a0Andhra Gongura Pachadi,\u00a0Kakarakaya Vepudu Recipe,\u00a0Andhra Style Nalla Karam Podi Recipe."]'::jsonb, 25, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/anu.mallajosyula-gmail.com/Pesarapappu_Pulusu_Recipe_edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/296.Pesarapappu_Pulusu_Recipe_edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mushroom and Prawn Malai Curry Recipe', 'mushroom-and-prawn-malai-curry-recipe', 'Mushroom and Prawn Malai Curry is my variation to the famous Bengali recipe ‘Chingri Macher Malai Curry’ which is prawn in coconut milk curry. I must say mushrooms and prawns together are a great hit! Both being so distinct in its flavour yet complimenting each other so well in this mouth watering delicacy.', '["250 grams Prawns", "250 grams Button mushrooms", "1 Tomato , paste", "1 Onion , paste", "1 inch Ginger , paste", "5 cloves Garlic , paste", "1 Green Chillies , paste", "1 tablespoon Curd (Dahi / Yogurt)", "1/2 cup Coconut milk", "3 Cardamom (Elaichi) Pods/Seeds", "5 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "2 Bay leaf (tej patta)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Cumin seeds (Jeera)", "Salt , as per taste", "Red Chilli powder , as per taste", "Sugar , as per taste", "2 tablespoons Mustard oil , for frying", "3 tablespoons Mustard oil , for gravy", "1 tablespoon Ghee , for gravy"]'::jsonb, ARRAY['cumin seeds (jeera)', 'green chillies paste', 'turmeric powder', 'mustard oil gravy', 'salt', 'mustard oil', 'cardamom (elaichi) podsseeds', 'prawns', 'tomato paste', 'red chilli powder', 'onion paste', 'cloves garlic paste', 'curd', 'sugar', 'coconut milk', 'button mushrooms', 'bay leaf (tej patta)', 'ghee gravy', 'cinnamon stick (dalchini)', 'ginger paste', 'cloves (laung)']::text[], '["To begin making the Mushroom and Prawn Malai Curry recipe, firstly clean the prawns and marinate with turmeric and salt for 1/2 to 1 hour.Heat oil in kadai and lightly fry prawns till they turn golden.Clean the mushroom, cut them lengthwise, stir fry them for 2-3 minutes.To the wok/kadai, add mustard oil and ghee, to this add cardamom, clove, cinnamon stick, jeera and bay leaves.As soon as the fragrance of the masalas rises, add onion paste.Once the onion starts browning, add ginger paste, garlic paste followed by tomato and chilly paste.Add sugar, salt, turmeric and jeera powder and curd.", "Keep stirring till the oil separates from the masala.Then add coconut milk and simmer it covered for about 10 minutes.In between check if the mixture dries up, add little water or coconut milk.Mix the prawns and mushrooms and simmer for five more minutes.Turn of the stove, sprinkle some garam masala powder and keep it covered for 10 to 15 minutes in the kadhai.Serve Mushroom and Prawn Malai Curry with hot steamed rice for a delicious meal."]'::jsonb, 50, 'Bengali', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/priyanjali/Mushroom_and_Prawn_Malai_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/297.Mushroom_and_Prawn_Malai_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Baby Corn Capsicum Masala Recipe', 'baby-corn-capsicum-masala-recipe', 'Baby Corn Capsicum Masala is a delicious dish that goes perfect with Phulka, making a weeknight dinner quick and simple. The addition of fennel seeds, along with other spices and the flavors of capsicum, the crunchiness of the baby corns provide a great combination making this dish delectable to the palate.', '["300 grams Baby corn , 300 grams baby corn, sliced thin diagonally", "1 Green Bell Pepper (Capsicum) , diced", "1 Red Bell pepper (Capsicum) , diced", "1 Onion , finely chopped", "1 inch Ginger , grated", "2 cloves Garlic , grated", "1 Green Chilli , slit", "3 Tomatoes , finely chopped", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Fennel seeds (Saunf)", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Cardamom Powder (Elaichi)", "1/2 Red Chilli powder , adjust to taste", "Salt , to taste", "Coriander (Dhania) Leaves , few sprigs, chopped", "Oil , to cook"]'::jsonb, ARRAY['s baby corn', 'reen bell pepper', 'capsicum', 'red bell pepper', 'onion', 'ginger', 's garlic', 'reen chilli', 'tomatoes', 'cumin seeds', 'jeera', 'fennel seeds', 'saunf', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'cardamom powder', 'elaichi', 'red chilli powder', 'salt', 'coriander', 'oil']::text[], '["To begin making the Baby Corn Capsicum Masala Recipe, get all the ingredients prepared and ready.Heat oil in a heavy bottomed pan on medium flame; add the cumin and fennel seeds and allow it to sizzle.", "Stir in the onions, bell peppers, baby corn, ginger and garlic and saute for a good 6-8 minutes.", "Now that the baby corn has cooked through, stir in the chopped tomatoes, now add the\u00a0turmeric powder,\u00a0coriander powder,\u00a0cardamom powder,\u00a0red chilli powder, and\u00a0salt to taste.", "Turn the heat to low, cover the pan, and allow the tomatoes to soften and form a nice curry like coating over the baby corn and peppers.Check the salt and spice levels and adjust to suit your taste.", "Stir in the chopped coriander leaves and serve.Serve the\u00a0Baby Corn Capsicum Masala for a quick weeknight dinner along\u00a0with Phulka,\u00a0\u00a0Punjabi Dal Tadka Recipe - Punjabi Toor Dal Recipe,\u00a0Boondi Raita Recipe\u00a0followed\u00a0 by a simple dessert of\u00a0Beetroot and Carrot Halwa Recipe."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Kadai_Baby_Corn_Capsicum_Masala_Recipe-6.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/298.Kadai_Baby_Corn_Capsicum_Masala_Recipe-6.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Baked Whole Wheat Masala Baati Recipe (Healthy Rajasthani Spiced Wheat Dumplings)', 'baked-whole-wheat-masala-baati-recipe-healthy-rajasthani-spiced-wheat-dumplings', 'Baked Whole Wheat Masala Baati is a traditional Rajasthani recipe for a crusty baked dumpling-shaped cookie made of whole wheat kneaded together with spices. It has a fascinating origin, dating back to the ancient days when soldiers ate it as a staple war-time sustenance. During those days grains like wheat, jowar, bajra were a part of everyday meal. So soldiers would bury the prepared dough into smaller chunks and place it underground. The blistering heat of Rajasthan, with the sun beating down on the earth would cook the dumplings, and by the time the soldiers returned after a long dar’s war, they would have perfectly earth-baked abates ready for a meal.', '["1 cup Whole Wheat Flour", "1/2 cup Sooji (Semolina/ Rava)", "1/2 cup Ghee", "Salt , to taste", "2 tablespoon Curd (Dahi / Yogurt)", "1 cup Green peas (Matar)", "1 Onion", "2 Green Chillies", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Ginger Garlic Paste", "1 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "3/4 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "Salt , to taste", "1-1/2 teaspoon Oil"]'::jsonb, ARRAY['salt', 'wheat flour', 'cumin powder (jeera)', 'coriander powder', 'ghee', 'green peas (matar)', 'red chilli powder', 'ginger garlic paste', 'curd', 'onion', 'cumin seeds (jeera)', 'sooji (semolina rava)', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Whole Wheat Masala Baati, first mix all ingredients mentioned under the \u2018For baatis\u2019 in a large mixing bowl.Knead them all together to form a soft dough that is pliable, but not sticky.", "If the dough turns out a touch hard to stiff, add a little milk and knead it till soft to touch.Divide the dough into equal sized portions, place them in a platter or tray.", "Cover the dough with a damp cloth and let it rest for half an hour.Meanwhile proceed to prepare the masala filling.", "For this, place a pan on the heat.", "Add some oil to it and allow it to get warm.", "Then add cumin seeds, onions and green chilies to the oil and saut\u00e9 until onions turn light pink.Next, add ginger garlic paste, red chilli powder, turmeric powder, coriander powder, roasted cumin powder and salt to the onions and toss it together.", "Stir continuously as it cooks, until the raw smell of the spices goes away.Then add peas and cook for 3 minutes until all the ingredients have combined together.", "Add water to cook the peas, if required, but once they are cooked, cook it till the excess water has evaporated completely.Once peas is cooked and water is completely dry, turn off the heat and set the masala aside so it can cool completely.Now, to make the baatis.", "Take one portion at a time, and flatten it into a small disc about 2-3 inches in diameter, and keep it in your palm.", "Scoop some peas masala filling, place it in the center of the disc.", "Then, bring the ends together, encasing the filling in the centre, seal the opening by pinching the edges together.Press the ball slightly and make a small depression with your thumb, in the center of the ball.", "Repeat with all the portions of dough.Then, place a heavy bottomed pot on the heat with about 3 litres of water in it.", "Bring the water to a boil, turn the heat down and gently slide the baatis into the water.", "Allow them to cook on a low heat for 15 to 20 minutes until they cook and rise to the top.Meanwhile, pre-heat the oven at 200 degrees centigrade.When the baatis are cooked, drain them gently and place them in a platter to cool.Once cooled, place the battis on on a baking sheet lined with parchment paper and place the sheet in the oven.Bake the masala stuffed battis at 200 degrees for about 25 to 35 minutes, turning them over every 10 minutes to ensure an evenly baked through and golden brown in color.Once they\u2019re golden brown and crisp, remove the masala battis baking sheet from the oven and place it on a baking tray to cool slightly.Serve the Baked Whole Wheat Masala Baati while still hot, with\u00a0ghee.", "If you are calorie conscious, you can have it with\u00a0Panchmel Dal, with just a light drizzle of ghee as a meal, or as a light evening snack along with a cup of tea."]'::jsonb, 80, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Baked_Vivatta_Whole_Wheat_Masala_Baati.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/299.Baked_Vivatta_Whole_Wheat_Masala_Baati.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Konkani Style Alasande Randayi Recipe-Black Eyed Beans and Yam Gravy', 'konkani-style-alasande-randayi-recipe-black-eyed-beans-and-yam-gravy', 'Konkani Style Alasande Randayi Recipe-Black Eyed Beans and Yam Gravy is a perfect combination to make a coconut based gravy. The curry is made with freshly ground spice mixture that are usual in the Konkani cuisine. The curry is very tangy and sweet and yet rich and flavorsome because of the generous use of fresh coconut.', '["1 cup Black Eyed Beans (Lobia) , Soaked for 2 hours in water", "1 cup Elephant yam (Suran/Senai/Ratalu) , cut into small pieces", "1 teaspoon Turmeric powder (Haldi)", "1 tablespoon Jaggery", "Salt , to taste", "Ingredients to roast and grind", "1 tablespoon Coriander (Dhania) Seeds", "2 Dry Red Chilli", "18 grams Tamarind", "4 tablespoon Fresh coconut , grated", "To Temper", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1 pinch Asafoetida (hing)", "Oil , for cooking"]'::jsonb, ARRAY['salt', 'elephant yam (suransenairatalu)', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'jaggery', 'dry red chilli', 'curry leaves', 'coriander (dhania) seeds', 'tamarind', 'turmeric powder', 'black eyed beans (lobia)', 'sunflower oil']::text[], '["To begin making the Konkani Style Alasande Randayi Recipe,\u00a0soak the beans and keep it ready.Heat a small skillet, dry roast the coriander seeds and set aside in a mixer.", "Add the grated coconut, dry red chilies, and tamarind and grind it into a smooth mixture.Heat a pressure cooker with oil, add the mustard seeds and allow it to crackle for 2 seconds and then add the curry leaves and hing.Immediately add the paste that was ground, along with a teaspoon of turmeric powder and jaggery.", "Give it a saute for 2 minutes.Later add the chopped yam along with black eyed peas, add salt and check for seasoning.Close the lid and pressure cook for about 3 whistle until it is done.", "Switch off the heat and allow it to rest till all the pressure is released by itself.", "Serve the Konkani Style Alasande Randayi Recipe along with\u00a0Sukka\u00a0and steamed rice or\u00a0Homemade Crispy Ghee Roast Dosas."]'::jsonb, 180, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Konkani_Style_Alsande_Randayi_Recipe_Black_Eyed_Beans_and_Yam_Gravy.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/300.Konkani_Style_Alsande_Randayi_Recipe_Black_Eyed_Beans_and_Yam_Gravy.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bhindi Gosht Recipe-Okra With Meat In Coconut Gravy', 'bhindi-gosht-recipe-okra-with-meat-in-coconut-gravy', 'In this recipe, goat meat is cooked with coconut milk, spices and okra. This dish has its own unique flavor and textures you can serve it with boiled rice, naans and chapatis. It is an excellent way to sneak in vegetables. You can make this recipe for your friends and family during the weekend and let them see the creative side of yours.', '["1 kg Mutton", "500 grams Bhindi (Lady Finger/Okra)", "2 Onion , minced", "1 tablespoon Ginger Garlic Paste", "10 Curry leaves", "1 cup Coconut milk", "Salt , to taste", "1 tablespoon Red Chilli powder", "3/4 tablespoon Cumin powder (Jeera)", "1/2 tablespoon Coriander Powder (Dhania)", "1/2 cup Tamarind Paste", "Oil , as required", "1 teaspoon Turmeric powder (Haldi)"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'coriander powder', 'red chilli powder', 'curry leaves', 'ginger garlic paste', 'onion', 'mutton', 'bhindi (lady fingerokra)', 'tamarind paste', 'coconut milk', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Bhindi Gosht recipe, heat half oil in pressure cooker, add onion to it and saute it till the onion turns translucent.", "Add ginger garlic paste, add all the spices to it and cook for few minutes.Add the meat to the above mixture along with coconut milk and curry leaves cook till the meat is tender.", "Pressure cook till 15-20 minutes.In another pan, add oil and saut\u00e9 big chunks of okra till 3/4 is cooked.", "Drizzle some lemon juice on it and mix properly.", "When done keep it aside.Open the pressure cooker and add tamarind pulp and okra.", "Mix everything well and let it cook for another 5-10 minutes till okra is completely cooked.Serve\u00a0Bhindi Gosht along with\u00a0Tawa Paratha\u00a0and\u00a0Jeera Rice\u00a0for your weekday meal."]'::jsonb, 40, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Sadafabbasi79-yahoo.com/bhindi_gosht_recipe.JPG', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/301.bhindi_gosht_recipe.JPG', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Carrot Paruppu Usili Recipe - Steamed Lentils Crumbled With Carrots', 'carrot-paruppu-usili-recipe-steamed-lentils-crumbled-with-carrots', 'An extremely healthy dish, Paruppu Usili is a traditional South Indian dish which is made with a combination of steamed crumbled lentils and chopped vegetables. The most commonly prepared Paruppu Usili are with French Beans, Vazhaipoo (Banana Blossoms) and Vendhaya Keerai (Fenugreek Leaves). You can use your favourite vegetable in this recipe and make it according to your taste and preference.', '["1 cup Carrots (Gajjar) , cut into small cubes", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Dry Red Chilli", "1/2 teaspoon Asafoetida (hing)", "1 sprig Curry leaves", "3 teaspoons Oil", "Salt , to taste", "Ingredients to make the Paruppu Usili", "1 cup Arhar dal (Split Toor Dal)", "1 teaspoon Fennel seeds (Saunf)", "2 Dry Red Chillies", "Salt , to taste"]'::jsonb, ARRAY['salt', 'arhar dal (split toor dal)', 'asafoetida (hing)', 'mustard seeds', 'fennel seeds (saunf)', 'carrot', 'dry red chilli', 'curry leaves', 'dry red chillies', 'sunflower oil']::text[], '["To begin making the\u00a0Carrot Paruppu Usili Recipe, wash and soak toor dal for 30 minutes.After 30 minutes drain the water from dal.", "Combine the soaked toor dal along with fennel seeds, dried red chillies, and salt in a mixer jar and grind to a coarse mix using a mixer grinder.", "Transfer to a bowl.", "Heat an idli steamer on medium heat, with a cup of water.", "Grease the idli mould and keep it ready.", "Now make small lemon sized balls of the prepared toor dal mix, and place it in the idli mould.", "Cover and steam cook for 10 minutes, until the dal mixture is cooked. (Don''t make the ball of dals too tight as the lentils will not steam very well)In a wide pan, add oil and heat it on medium heat, add the mustard seeds, asafoetida and let it splutter.", "Add the dried red chilli, curry leaves and let it crackle.Add the cubed carrots, season with salt, mix well, cover and cook for 5-7 minutes until the carrots are cooked well.Meanwhile, remove the steamed toor dal balls, crumble it with your hands so that it resembles the sandy texture.Once the carrots are cooked well, add this crumbled toor dal mix to the pan and mix well.At this stage you can add a teaspoon or two of oil, if the mixture looks too dry.Saute for 2 minutes, until the dal crumbles are nice and crispy and switch off the heat.", "It is ready to be served.Serve Carrot Paruppu Usili Recipe along with\u00a0Steamed Rice,\u00a0Jeera Milagu Rasam,\u00a0Chow Chow Poricha Kootu\u00a0and Roasted Papad for a weekend lunch."]'::jsonb, 40, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Carrot_Paruppu_Usili_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/302.Carrot_Paruppu_Usili_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Beerakaya Tomato Koora Recipe (Andhra Style Ridge Gourd Curry)', 'beerakaya-tomato-koora-recipe-andhra-style-ridge-gourd-curry', 'Beerakaya Tomato Koora Recipe is a delectable Andhra style ridge gourd cooked in a tomato based gravy. It is spicy and colourful. Ridge gourd is low in saturated fat, cholesterol and calories that aids in weight loss. Ridge gourd juice is used to heal jaundice and to strengthen the immune system against any infection.', '["4 Ridge Gourd (Turai/ Peerkangai) , cut into cubes", "1 Onion , finely chopped", "3 Tomatoes , ripe, finely chopped", "5 cloves Garlic , roughly pounded in pester and mortar", "1 teaspoon Jaggery , powdered", "2 teaspoons Red Chilli powder", "2 teaspoons Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds) , roasted and powdered", "1 teaspoon Fennel seeds (Saunf) , powdered", "1 sprig Curry leaves", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "Asafoetida (hing) , A pinch", "5 sprig Coriander (Dhania) Leaves , finely chopped for garnish", "1 Dry Red Chilli", "2 teaspoons Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard seeds', 'fennel seeds (saunf)', 'asafoetida (hing)', 'jaggery', 'ridge gourd (turai peerkangai)', 'tomato ripe', 'red chilli powder', 'dry red chilli', 'curry leaves', 'coriander (dhania) leaves', 'onion', 'methi seeds (fenugreek seeds)', 'cloves garlic pester mortar', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making Beerakaya Tomato Koora Recipe, wash, scrape the outer hard skin of the ridge gourd and cut them into small cubes and keep aside.Heat oil in a pan on medium flame, add mustard seeds and let it crackle.Add the asafoetida powder, curry leaves and red chilli and let it splutter.Now roughly pound the garlic cloves using a pestle and mortar and add it to the pan and saute until the garlic turns golden.Add the finely chopped onion and saute until it turns translucent.Add the chopped tomatoes and saute well.To this add the red chilli, coriander, turmeric, season with salt and saute until the oil separates out.Now, add the cubed ridge gourds, mix well and let the ridge gourd cook in its own juices for 5 minutes.Once the ridge gourd is cooked, add the jaggery, fennel seeds and roasted fenugreek seeds powder and mix well.Let it simmer for another 5 minutes, once the gravy becomes thick switch off the flame.Garnish with coriander leaves.", "Serve the Beerakaya Tomato Koora Recipe along with Phulkas or Steamed Rice with\u00a0Elai Vadam\u00a0for a light weekday lunch."]'::jsonb, 25, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Beerakaya_Tomato_Koora_Recipe_Andhra_Style_Ridge_Gourd_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/303.Beerakaya_Tomato_Koora_Recipe_Andhra_Style_Ridge_Gourd_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chemmeen Muringakka Curry Recipe -Prawn Drumstick Curry', 'chemmeen-muringakka-curry-recipe-prawn-drumstick-curry', 'Chemmeen Muringakka Curry Recipe is a curry that is cooked with fresh whole prawns in a ground coconut masala. The curry is so comforting to be had for a nice Sunday brunch along with steamed rice. The masala is made using fresh coconut, coriander seeds, dry red chillies, onions and turmeric which is well roasted in the pan till it releases nice flavour and it is then ground to a smooth paste and then finally stewed along with prawns and drumsticks.', '["Ingredients to roast & grind", "1 Onion , chopped", "4 cloves Garlic , chopped", "2 tablespoon Coriander (Dhania) Seeds", "1 teaspoon Cumin seeds (Jeera)", "1/4 cup Fresh coconut , grated", "4 Dry Red Chillies", "1/2 teaspoon Turmeric powder (Haldi)", "300 grams Prawns , shells removed and deveined", "1 Drumstick , cut into 3 inch pieces", "1 Green Chilli , slit", "1 Onion , sliced", "1/2 teaspoon Red Chilli powder", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "Coconut Oil , for cooking", "Salt , to taste"]'::jsonb, ARRAY['salt', 'green chilli', 'coconut', 'mustard seeds', 'red chilli powder', 'cloves garlic', 'drumstick', 'curry leaves', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'dry red chillies', 'prawns shells deveined', 'coconut oil', 'turmeric powder']::text[], '["To begin making the\u00a0Chemmeen Muringakka Curry Recipe/\u00a0Prawn & Drumstick Curry, we will first pressure cook the drumstick in a pressure cooker, with 2 tablespoons of water and\u00a0 a pinch of salt for just 2 whistles.", "After 2 whistles turn off the heat and release the pressure immediately.", "Releasing the pressure immediately, will retain the fresh green color of the drumstick."]'::jsonb, 40, 'Kerala', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Kerala_Style_Prawn__Drumstick_Curry_Recipe__1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/304.Kerala_Style_Prawn__Drumstick_Curry_Recipe__1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vegan Chickpeas And Broccoli Curry Recipe', 'vegan-chickpeas-and-broccoli-curry-recipe', 'If you are particular about veganism, then chickpeas and broccoli curry would come as a saviour and sounds delicious. Chickpeas with its numerous health benefits help to manage weight, lowers the total amount of cholesterol in the blood and decreases the risk of heart disease. Broccoli being nutrition powerhouses supply loads of nutrients for little calories. The combination of chickpeas and broccoli supply essential nutrients needed for a person for a day and what’s more interesting is, it is vegan. You can prepare the curry without broccoli the previous night and add broccoli next day.', '["1 tablespoon Oil", "1 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "1 cup Kabuli Chana (White Chickpeas)", "1 cup Broccoli", "1 Onion , chopped", "1 Tomato , chopped", "1 teaspoon Ginger Garlic Paste", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Red Chilli powder", "Salt , as required", "1 cup Water", "Coriander (Dhania) Leaves , handful, chopped"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'coriander (dhania) leaves', 'red chilli powder', 'water', 'ginger garlic paste', 'kabuli chana (white chickpeas)', 'cinnamon stick (dalchini)', 'broccoli', 'onion', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Vegan Chickpeas And Broccoli Curry recipe, firstly soak chickpeas in water for about an hour.", "Pressure cook the chickpeas for about 3 whistles in a cooker.Take 1/4 cup of cooked chickpeas and ground them into a fine paste.In a small kadai/wok, add oil and heat over medium flame.", "Once the oil is hot, add cinnamon stick and cloves.Add onions and cook until it becomes translucent.", "Add ginger garlic to the onion and cook until raw smell goes off.Add chopped tomatoes and cook until it becomes mushy.", "Add chilli powder, cumin powder and salt.", "Stir them well.Add cooked chickpeas and mashed chickpeas to the pan.", "Add a cup of water and bring it to boil in high flame.Reduce the flame and cook until the gravy thickens.", "In a pot, bring water to boil.", "Add broccoli florets to the boiling water and let it be for two minutes.Drain the water and wash the florets with cold water.", "Drain the water completely and set aside.Add the blanched broccoli florets to the curry and stir them well.", "Alternatively, you can fry the broccoli florets in oil and add the fried florets to the curry.Cook for about two minutes, switch off the flame and garnish with coriander leaves.", "Serve Vegan Chickpeas And Broccoli Curry wrapped inside the tortillas or enjoy with plain white steamed rice."]'::jsonb, 65, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Vegan_Chickpeas_and_Broccoli_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/305.Vegan_Chickpeas_and_Broccoli_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Konkani Style Southe Koddel Recipe-Mangalore Cucumber in Coconut curry', 'konkani-style-southe-koddel-recipe-mangalore-cucumber-in-coconut-curry', 'Konkani Style Southe Koddel Recipe is an authentic recipe from the coastal region of Karnataka. It is a creamy and tangy curry simmered with Mangalore cucumber. The curry is then seasoned well with some crispy curry leaves and Crackled mustard seeds.', '["1 Mangalorean cucumber , skin can be kept also", "1 cup Tamarind Water", "1 tablespoon Jaggery", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Oil , for cooking", "To Grind", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 tablespoon White Urad Dal (Split)", "1 teaspoon Chana dal (Bengal Gram Dal)", "4 tablespoon Fresh coconut , grated", "1 teaspoon Cumin seeds (Jeera)", "3 Dry Red Chillies", "1 sprig Curry leaves", "2 cloves Garlic", "To temper", "1 tablespoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'tamarind water', 'coconut', 'mangalorean cucumber skin can be kept also', 'mustard seeds', 'jaggery', 'cloves garlic', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making the Konkani Style Southe Koddel Recipe by first pressure cooking the mangalore cucumber with a pinch of salt and 1/2 cup water in a pressure cooker for 1 whistle.Release the pressure naturally and then keep it aside.Now heat a frying pan, add oil and the,\u00a0fenugreek seeds,\u00a0urad dal,\u00a0chana dal,\u00a0coconut,\u00a0cumin seeds,\u00a0dry red chillies,\u00a0curry leaves,\u00a0garlic.Fry them for about 2 minutes till the aroma is released.Once done, cool it down and then grind it into a smooth creamy paste by adding water little, After grinding keep it aside.Now, heat a skillet and add oil, add the ground mixture along with the cooked Mangalore cucumber.", "Stir well.", "Add salt and turmeric powder and check for seasoning.", "Leave it to simmer for 10 minutes.In another kadai pan, heat oil and then crackle the mustard seeds and urad dal and immediately add the curry leaves and allow it to crackle and pour it over the curry and serve.", "Serve the Konkani Style Southe Koddel Recipe along with\u00a0Mangalorean Neer Dosa Recipe \u00a0and\u00a0Solkadhi Recipe (Konkani Style Kokum Kadhi)\u00a0as a refreshing drink at the end."]'::jsonb, 45, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Konkani_Style_Southe_Koddel_Recipe_Mangalore_Cucumber_in_Coconut_curry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/306.Konkani_Style_Southe_Koddel_Recipe_Mangalore_Cucumber_in_Coconut_curry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Fajeto Recipe - Gujarati Ripe Mango Curry Recipe', 'fajeto-recipe-gujarati-ripe-mango-curry-recipe', 'Fajeto is a yogurt and mango based curry that is tangy, hot, sweet and simply delicious. I sometimes wonder if delicious is enough to describe this dish.', '["1 cup Mango (Ripe) , pureed", "1 cup Curd (Dahi / Yogurt)", "3 tablespoons Gram flour (besan)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoons Jaggery", "1/4 teaspoon Asafoetida (hing)", "Salt , to taste", "Ingredients for seasoning", "1 tablespoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 inch Cinnamon Stick (Dalchini)", "1 Dry Red Chilli", "1 teaspoon Ginger , grated (omit ginger if jain)", "2 Green Chilli , slit", "6 Curry leaves , finely chopped", "1 tablespoon Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['salt', 'ginger', 'green chilli', 'asafoetida (hing)', 'mango (ripe)', 'ghee', 'mustard seeds', 'jaggery', 'red chilli powder', 'coriander (dhania) leaves', 'gram flour (besan)', 'curd', 'dry red chilli', 'curry leaves', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'turmeric powder']::text[], '["To begin making the Gujarati Fajeto (Mango Kadhi) recipe, into a saucepan combine all the main ingredients along with 2 cups of water and whisk them together until well combined.", "Bring the mixture to come to a boil whisking occasionally.", "Once the mixture begins to boil, turn the heat to low and simmer for 10 minutes.", "To make the seasoning for the Fajeto Mango Kadhi; Heat ghee in a large saucepan on medium heat; add mustard seeds and cumin seeds allow them to crackle.Add the cinnamon, dry red chilli, curry leaves, ginger and green chillies and stir for a few seconds.", "Check the salt and spice levels and adjust to suit your taste.Pour the seasoning over the simmering Fajeto Kadhi.", "Turn off the heat and garnish the Kadhi with chopped coriander leaves.Serve the Fajeto (Gujarati Mango Kadhi) along with Phulka''s, Stuffed Bhindi and Steamed Rice\u00a0for a weekend lunch."]'::jsonb, 50, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Fajeto_Gujarati_Mango_Yogurt_Kadhi_Recipe-1-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/307.Fajeto_Gujarati_Mango_Yogurt_Kadhi_Recipe-1-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mangalorean Style Lobia Gassi Recipe - Black Eyed Peas In Coconut Curry', 'mangalorean-style-lobia-gassi-recipe-black-eyed-peas-in-coconut-curry', 'Mangalorean Style Lobia Gassi Recipe will be the favourite among all the vegetarians who would love to try a “Gassi”, which is a Mangalorean speciality. This curry is traditionally from Mangalore cuisine and is made with chicken.', '["To Grind", "1 cup Shallots", "2 Cloves (Laung) , garlic", "1/2 cup Fresh coconut , grated", "4 Dry Red Chillies", "1 tablespoon Coriander (Dhania) Seeds", "1 tablespoon Cumin seeds (Jeera)", "1 tablespoon Methi Seeds (Fenugreek Seeds)", "1 tablespoon Whole Black Peppercorns", "2 sprig Curry leaves", "18 grams Tamarind", "Other Ingredients", "1 cup Black Eyed Beans (Lobia) , soaked in water for 2 hours", "1 cup Coconut milk", "1 teaspoon Turmeric powder (Haldi)", "To Temper", "1 Cinnamon Stick (Dalchini)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 cloves Garlic , crushed", "1 Dry Red Chilli", "1 teaspoon Asafoetida (hing)", "Oil , for cooking", "Salt , to taste"]'::jsonb, ARRAY['salt', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'black peppercorns', 'cloves garlic', 'dry red chilli', 'curry leaves', 'cloves (laung) garlic', 'dry red chillies', 'coriander (dhania) seeds', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'cinnamon stick (dalchini)', 'coconut milk', 'tamarind', 'turmeric powder', 'black eyed beans (lobia)', 'sunflower oil']::text[], '["To begin making the Mangalorean Style Lobia Gassi Recipe,\u00a0in a Kadai/Pan, add 1 teaspoon ghee.", "Roast coriander seeds, cumin seeds, dried red chilies, peppercorns one by one until fragrant.", "Once roasted remove from pan and set aside to cool.Into the same pan, add sliced onions, garlic, and roast until onions start to turn brown.Add fresh grated coconut, tamarind ball, and continue to roast until coconut start to turn golden brown.", "Remove from the pan and set it aside.After roasting all the, and the spices and onion-coconut mix has cooled, add them all to a blender and blend into smooth paste by adding little water.Heat a pressure cooker with oil, add the ground masala paste and cook until oil/ghee separates from the sides of the pan.Add in your soaked lobia, turmeric powder and salt, add about 1/2 water and cook the lobia for 3 whistle.Remove and add the coconut milk and stir well, check for salt and adjust according to your palate.To temper, heat a kadai, add mustard seeds, hing, curry leaves, garlic and dry red chilies and let it crackle for few minutes and pour it over the gassi and serve.", "Serve the\u00a0Mangalorean Style Lobia Gassi Recipe\u00a0along with\u00a0Mangalorean Neer Dosa Recipe (Savory Rice & Coconut Crepe)\u00a0to make a good meal for your Sunday lunch."]'::jsonb, 195, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Mangalorean_Style_Lobia_Gazzi_Recipe_Black_eyed_peas_in_Coconut_Curry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/308.Mangalorean_Style_Lobia_Gazzi_Recipe_Black_eyed_peas_in_Coconut_Curry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Style Pulao With Coconut Milk Recipe', 'kashmiri-style-pulao-with-coconut-milk-recipe', 'Kashmiri Pulao is a treat to the eyes as well as to the taste buds. This traditional rice recipe of Kashmir is full of flavor with the added goodness of dry fruits and fresh fruits.', '["1-1/2 cups Basmati rice", "3 cups Coconut milk", "Ghee , to cook", "Oil , to cook, as needed", "2 tablespoons Cashew nuts", "2 tablespoons Whole Almonds (Badam) , sliced", "1 tablespoon Pistachios", "2 tablespoons Sultana Raisins", "1 Onion , julienned", "2 Carrots (Gajjar) , diced", "1/2 cup Green peas (Matar)", "1 tablespoon Ginger , julienned", "1 Green Chilli , slit", "1/2 cup Pineapple , diced", "1/2 cup Fresh Pomegranate Fruit Kernels", "1 Apple , diced", "4 Cloves (Laung)", "2 Cardamom (Elaichi) Pods/Seeds", "2 inch Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta)", "1/2 teaspoon Fennel seeds (Saunf)", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Rose Essence", "1 tablespoon Water", "Salt , to taste", "2 tablespoons Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['s basmati rice', 's coconut milk', 'ghee', 'oil', 's cashew nuts', 's whole almonds', 'badam', 'pistachios', 's sultana raisins', 'onion', 'carrots', 'gajjar', 'green peas', 'matar', 'ginger', 'reen chilli', 'pineapple', 'fresh pomegranate fruit kernels', 'apple', 'laung', 'cardamom', 'elaichi', 'cinnamon stick', 'dalchini', 'bay leaf', 'tej patta', 'fennel seeds', 'saunf', 'turmeric powder', 'haldi', 'rose essence', 'water', 'salt', 's coriander', 'dhania']::text[], '["To begin making Kashmiri Style Pulao With Coconut Milk Recipe, wash the rice and allow to drain.Heat half of ghee and oil taken in a biryani pan.Add in three fourth of the onions taken (reserving a little to be used while cooking the rice).Let it fry nicely until it turns golden brown.", "Remove from flame and keep it aside.To the same pan, add the raisins, cashew nuts, pistachios and almonds.", "Fry until they become golden brown in color.Next to the same pan add in 1 tbsp each of ghee and oil.Now add the cloves, cinnamon, cardamom, and bay leaf.And saute for a minute or till they turn fragrant.Add in rest of the sliced onions, ginger, green chillies and crushed fennel seeds.", "Saute well.To this add the washed and drained rice.", "Mix well.", "Saute until the rice is fried well and turns crisp.Now add the coconut milk, turmeric powder and salt. (If adding saffron, add at this stage).", "Mix and cook covered in low flame until cooked completely.In the meanwhile, heat the remaining ghee and oil in another pan.Saute the carrots and peas with salt.", "Cook covered for 5-10 minutes.", "Once done, switch the heat off.When the rice is cooked, add the fried onions, dry fruits, pineapple, apple, pomegranate, coriander leaves and the cooked carrots and peas.Add the rose essence in 1 tablespoon water and sprinkle on top of the rice.", "Mix well and cook covered for 1 minute.Serve Kashmiri Style Pulao With Coconut Milk Recipe along with Boondi Raita Recipe Spiced With Black Salt and Kashmiri Style Bharit Marchavangun Recipe(Stuffed Chillies Recipe)."]'::jsonb, 50, 'Kashmiri', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/feminasherif-yahoo.com/Kashmiri_Pulao_with_Coconut_Milk.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/309.Kashmiri_Pulao_with_Coconut_Milk.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Cheesy Mushroom Masala Dosa Recipe', 'cheesy-mushroom-masala-dosa-recipe', 'Cheesy Mushroom Masala Dosa Recipe is a wholesome dish which will become a family favourite. The batter used to make this Dosa is Ragi Batter, which is very nutritious and diabetic friendly.', '["1 cup Idli Rice", "2 cups Ragi Seeds", "1 cup Barley (seeds)", "2 cups White Urad Dal (Whole)", "2 teaspoons Methi Seeds (Fenugreek Seeds)", "Water , for soaking", "3 Onions , thinly sliced", "6 cloves Garlic , finely chopped", "2 Green Chillies , finely chopped", "4 Tomatoes , finely chopped", "400 grams Button mushrooms , finely chopped", "1/4 teaspoon Red Chilli powder", "1 teaspoon Pav bhaji masala", "1/2 teaspoon Chaat Masala Powder", "1 cup Paneer (Homemade Cottage Cheese) , grated", "Mint Leaves (Pudina) , small bunch, finely chopped", "200 grams Britannia Cheese Block , grated"]'::jsonb, ARRAY['tomato', 'pav bhaji masala', 'ragi seeds', 'britannia cheese block', 'barley (seeds)', 'paneer', 'mint leaves (pudina)', 'idli rice', 'chaat masala powder', 'red chilli powder', 'cloves garlic', 'water soaking', 'methi seeds (fenugreek seeds)', 'onion', 'button mushrooms', 'green chillies', 'white urad dal']::text[], '["To begin making the Cheesy Mushroom Masala Dosa Recipe, first make the ragi dosa batter and keep it handy.*To make the Ragi Dosa Batter:Soak the rice, ragi and barley together in water such that the all the ingredients are completely immersed in water.", "The level of water should be an inch above the rice in the bowl.", "Let it soak for about 6 hours or overnight.", "Soak the urad dal and fenugreek in water such that all of the dal is completely immersed in water.", "The level of water should be 2 inches above the dal in the bowl.", "Let it soak for about 6 hours.After the soaking period, first grind the urad dal into a fine smooth batter.", "While grinding add just enough water to make it into a very smooth batter.", "The batter will look fluffy.Grind the rice, ragi, barley into a smooth batter, adding just the required amount of water to grind into an almost smooth batter.", "Adding too much water will make the mixture too watery.", "If required grind a little at a time to get a\u00a0 smooth batter .Combine the urad and rice ragi batter, add salt to taste and set aside for at least 12 hours or overnight until the ragi idli dosa batter ferments.", "You will notice the batter would have risen in volume.Hence you should place the Homemade Ragi Idli & Dosa Batter in a large container so it has enough room to increase in its volume.*To make the Mushroom Filling:Into a preheated pan, heat oil in a heavy bottomed pan.", "Add the onions, garlic and green chillies and saute until the onions become soft and lightly caramelized.Once the onions have softened, add the tomatoes and saute until it becomes mushy.", "Add the chopped mushrooms, red chilli powder, pav bhaji masala, chaat masala and salt to taste.Saute until you get a thick mushroom masala and all the moisture from the mushroom masala evaporates - it will take 5 minutes.After about 5 to 7 minutes, once the masala has thickened, add the paneer, chopped mint leaves, give it a stir and turn off the heat.*To make the Cheese Mushroom Dosa:Spoon a ladle full of ragi dosa batter into a preheated dosa pan and spread it in circular motion to make the dosa.Drizzle a little ghee and allow the dosa to get cooked from the top.Spread the mushroom masala evenly all over the dosa.Next, add the grated the Britannia cheese block all around as well.", "Once the cheese melts fold the\u00a0Cheesy Mushroom Masala Dosa in half and transfer into a serving plate.Serve\u00a0Cheesy Mushroom Masala Dosa Recipe\u00a0with\u00a0Coconut Chutney,\u00a0Fresh Fruit Bowl\u00a0and\u00a0Kumbakonam Filter Coffee\u00a0for a tasty and satisfying breakfast."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Cheesy_Mushroom_Paneer_Masala_Dosa_Cheesy_Kitchen_Recipes_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/310.Cheesy_Mushroom_Paneer_Masala_Dosa_Cheesy_Kitchen_Recipes_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kodava Kummu Curry Recipe- Coorg Style Mushroom Curry', 'kodava-kummu-curry-recipe-coorg-style-mushroom-curry', 'Kodava Kummu Curry Recipe- Spicy Mushroom Gravy is an authentic recipe that hails from kodava district which is a part of Coorg. Mushrooms are locally known as kummu in their local language. The curry is made with ground coconut, jeera seeds and garlic that is simmered with sautéed onions and tomatoes.', '["500 grams Button mushrooms , chopped", "2 Green Chillies , chopped", "2 Dry Red Chillies", "1 teaspoon Whole Black Peppercorns , coarsely pounded", "2 Onion , thinly sliced", "2 Tomatoes , chopped", "1 sprig Curry leaves", "2 teaspoon Coriander (Dhania) Seeds", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Oil", "To Grind", "1/4 cup Fresh coconut , grated", "1 teaspoon Cumin seeds (Jeera)", "6 cloves Garlic"]'::jsonb, ARRAY['tomato', 'salt', 'coconut', 'black peppercorns', 'cloves garlic', 'curry leaves', 'dry red chillies', 'onion', 'coriander (dhania) seeds', 'cumin seeds (jeera)', 'button mushrooms', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Kodava Kummu Curry Recipe\u00a0chop all the ingredients and keep it ready.", "Grind fresh coconut, jeera seeds and garlic.", "Add little water and grind it into a smooth paste.", "Keep this aside.Heat a kadai with oil, add in curry leaves and allow it to sparkle for few seconds, add in dry red chillies and peppercorns and allow them to sizzle for few seconds.Add sliced onions and green chillies and saute till they soften.", "Add in chopped mushroom and keep saut\u00e9ing until it leaves out moisture.Add in the ground paste and saute till the paste is cooked well.", "Add chopped tomatoes and sprinkle all the spice powders like coriander powder, turmeric powder and salt to taste.Pour about 1/2 cup water and allow the\u00a0Kummu Curry/ Coorg Mushroom Curry to simmer for about 5 minutes.", "Once done, check the salt and seasonings and adjust according to taste.Turn off the heat and transfer the\u00a0Kodava Kummu Curry to a serving bowl and serve hot.Serve the\u00a0Kodava Kummu Curry Recipe- Spicy Mushroom Gravy\u00a0along with\u00a0Ghee Rice/ Neychoru,\u00a0Parotta\u00a0and a\u00a0Moong Sprouts Usal\u00a0for a wholesome weeknight lunch or dinner."]'::jsonb, 35, 'Coorg', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/June-22/Kodava_Style_Kummu_Curry_Recipe_Coorg_Mushroom_Curry-3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/311.Kodava_Style_Kummu_Curry_Recipe_Coorg_Mushroom_Curry-3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Konju Curry With Thengakothu Recipe (Kerala Style Prawn Curry)', 'kerala-style-konju-curry-with-thengakothu-recipe-kerala-style-prawn-curry', 'Cooking a magnificent dish with so few ingredients and all in one pot is a perfect busy weekday lunch or dinner. This recipe is not just quick and easy but constructed to maximise flavour. The Kerala Style Konju Curry With Thengakothu is a culinary delight and such a wonderful recipe for those who dislike being in the kitchen for long hours. Kerala Style Konju Curry With Thengakothu is a perfect dish for all those bachelors or single people out there trying their hand at cooking for the first time.', '["500 grams Prawns", "2 Onions , finely chopped", "1 inch Ginger , finely chopped", "6 cloves Garlic", "1 tablespoons Red Chilli powder", "3/4 tablespoon Coriander Powder (Dhania)", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 cup Fresh coconut , pieces", "1 Kokum (Malabar Tamarind) , soaked, for cleaning prawns", "2 Kokum (Malabar Tamarind) , soaked (for the curry)", "1 sprig Curry leaves", "Water , enough to cook the prawns", "Salt , to taste", "Ingredients for seasoning", "1 tablespoon Coconut Oil", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1 pinch Methi Powder (Fenugreek Powder)", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'ginger', 'coconut', 'kokum (malabar tamarind)', 'water enough the prawns', 'mustard seeds', 'methi powder (fenugreek powder)', 'red chilli powder', 'cloves garlic', 'curry leaves', 'onion', 'coconut oil', 'coriander powder', 'turmeric powder', 'prawns', 'kokum (malabar tamarind) (for the curry)']::text[], '["To begin making the Kerala Style Konju Curry With Thengakothu recipe, wash, clean and devein the prawns.Marinate it with 1 small piece of kudampuli and salt.", "Keep aside for 10 minutes.Throw away the kudampuli and wash the prawns under running water till cleaned well.", "Drain away all the water.Take a heavy bottomed pan and add the cleaned prawns into it.Into the prawns, add all the ingredients except the coconut oil.Mix well with hands (or with a wooden spoon) till masala has coated the prawns completely. [add just enough water to cover the prawns or a little lesser, because prawns releases it''s own juices while cooking]Cover and cook the prawns for 10 to 12 minutes approximately or till its done.", "The cooking time depends on the prawns.Do not over cook the prawns.", "Over cooked prawns turns rubbery and under cooked prawns can make you sick.", "So be careful while cooking it.If there is too much gravy, reduce it a little.", "Switch off the flame.Heat coconut oil in a small pan.", "Add the mustard and allow it to splutter.", "Now add the curry leaves and fenugreek powder. (optional) Switch off flame.Pour the seasoning into the curry, mix well and serve hot.", "Kerala Style Konju Curry With Thengakothu is best served with hot rice,\u00a0appams\u00a0or\u00a0neer dosa."]'::jsonb, 40, 'Kerala', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Donna_George/Prawn_Curry_In_A_Hurry__Kerala_Style_Konju_Curry_With_Thengakothu.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/312.Prawn_Curry_In_A_Hurry__Kerala_Style_Konju_Curry_With_Thengakothu.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Cabbage Poricha Kootu Recipe (Red Cabbage) - South Indian Cabbage Dal', 'cabbage-poricha-kootu-recipe-red-cabbage-south-indian-cabbage-dal', 'The Cabbage Poricha Kootu Recipe is a wholesome and delicious recipe where the moong dal is cooked and mixed along with steamed cabbage and a fresh coconut masala, finished off with a crunchy tadka.  You can use the regular cabbage or the red cabbage to make this south indian kootu recipe which is essentially a cabbage dal with coconut.', '["2 cups Cabbage (Patta Gobi/ Muttaikose) , (Red/ Green Cabbage) roughly chopped", "1 cup Yellow Moong Dal (Split)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "To Be Ground", "1/2 cup Fresh coconut , grated", "2 teaspoons Cumin seeds (Jeera)", "2 teaspoons Whole Black Pepper Corns", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "1 teaspoon Coconut Oil"]'::jsonb, ARRAY['salt', 'yellow moong dal (split)', 'coconut', 'mustard seeds', 'black pepper corns', 'curry leaves', 'cabbage (patta gobi muttaikose) (red green cabbage)', 'white urad dal (split)', 'cumin seeds (jeera)', 'coconut oil', 'turmeric powder']::text[], '["To begin making\u00a0Cabbage Poricha Kootu Recipe, into the pressure cooker, add the chopped cabbage (red cabbage or green cabbage) and 2 tablespoons of water, sprinkle some salt and turmeric powder and pressure cook for 1 whistle.Turn off the heat and release the pressure immediately by running it under cold water.", "This will prevent the cabbage from getting over cooked.", "Transfer to a bowl and keep this aside.In the same pressure cooker, add the washed the moong dal along with turmeric powder and 1 cup water.", "Pressure cook for 2 to 3 whistles.", "After 2 to 3 whistles, turn off the heat, release the pressure naturally and keep it aside.In a mixer grinder, add grated coconut, cumin seeds and black peppercorns along with 1/4 cup of warm water and grind to a smooth paste.", "Keep aside - this is the poricha kootu masala.", "Add the cabbage, coconut masala to the pressure cooked moong dal and give it a quick stir.", "Add salt to taste and give the\u00a0Cabbage Poricha Kootu a brisk boil and turn off the heat.", "Give it a taste and adjust the salt and seasonings accordingly.Transfer the\u00a0Cabbage Poricha Kootu to a serving bowl.Last step is to heat the oil in a small tadka pan, add the mustard, urad dal seeds and let it splutter.", "Allow the dal to turn golden brown.", "Stir in the curry leaves, cook for 10 seconds and turn off the heat.Add this tadka over the prepared\u00a0Cabbage Poricha\u00a0Kootu\u00a0and give it a stir.", "Serve hot.Serve the Cabbage Poricha Kootu\u00a0Recipe\u00a0 (Red Cabbage / Green Cabbage) along with\u00a0Phulkas/Steamed Rice,\u00a0Beetroot Thoran\u00a0and\u00a0Carrot Cucumber Tomato Salad\u00a0for a delicious and\u00a0simple weeknight dinner."]'::jsonb, 35, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Red_Cabbage_Poricha_Kootu_Muttaikose_Poricha_Kootu_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/313.Red_Cabbage_Poricha_Kootu_Muttaikose_Poricha_Kootu_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer Stuffed Ragi Paratha Recipe - High Protein Breakfast', 'paneer-stuffed-ragi-paratha-recipe-high-protein-breakfast', 'Paneer Stuffed Ragi Paratha Recipe, is a healthy recipe of a stuffed paratha that has a filling of protein rich paneer seasoned with simple spices, packed in a healthy dough made of whole wheat flour and ragi also known as Nachni. These parathas are cooked in ghee to give it a crisp outer layer and makes a great indian diabetic breakfast or lunch.', '["1 cup Ragi Flour (Finger Millet/ Nagli)", "1 cup Whole Wheat Flour", "1 teaspoon Salt", "1 tablespoon Oil", "1 cup Paneer (Homemade Cottage Cheese) , grated", "2 Green Chillies , finely chopped", "1/4 cup Mint Leaves (Pudina) , finely chopped", "1 teaspoon Cumin powder (Jeera)", "Salt , to taste", "Others", "Ghee , for cooking paratha"]'::jsonb, ARRAY['salt', 'wheat flour', 'cumin powder (jeera)', 'paneer', 'ragi flour (finger millet nagli)', 'mint leaves (pudina)', 'ghee paratha', 'green chillies', 'sunflower oil']::text[], '["To begin making the Paneer Stuffed Ragi Paratha Recipe, we will first make the paratha dough.For the dough, in a large bowl, add in the ragi flour, whole wheat flour and required salt.Use your fingers and stir in the salt into the flour.", "Add water a little at a time and knead to make soft, pliable paratha dough.Knead paratha dough for a couple of minutes until the paratha dough is smooth and elastic.", "Use the fold press and knead motion to make the dough smooth.Next add a teaspoon of oil to coat the paratha dough and knead a little more.", "You want a paratha dough that will be soft smooth and not sticky.", "Divide the dough into equal portions.Cover the ragi paratha dough and allow it to rest until you get the filling ready.", "The next step is to make the Paneer filling for the Ragi ParathaIn a mixing bowl, combine the grated paneer green chillies, freshly chopped mint leaves, salt to taste, cumin powder, Using your fingers again, mix all the ingredients well.Divide the filling into equal portions.This process of dividing and keeping the portions for paratha dough and filling ready, helps you gauge the number of parathas you can make and if you need more or less of the filling.The final step is to stuff the filling into the ragi paratha dough.Dust the ragi paratha dough in flour, flatten it with your finger and place it on a flat surface.", "Roll them out thin to approximately 3 inches in diameter.Take a portion of paneer filling and place it in the center.", "Next gather the sides of the paratha dough and bring them together.", "Remove the little excess dough which popped out when you brought them together.", "Press the filled ragi paneer paratha dough down.Dust the filled paneer paratha dough in some flour and roll it gently applying just a pressure.", "Roll it to desired thickness and proceed the similar way with the remaining portions of paratha dough and filling.Preheat skillet on medium heat and grease it with little oil.", "Place the filled ragi paneer paratha.", "Allow it to cook on medium heat for about 30 to 45 seconds and flip over.Spread a little oil over the paratha and keep pressing the ragi paneer stuffed parathas while on the skillet to cook the paratha evenly from inside out.Do the flipping over process a couple of times until both sides get cooked, browned and crisp evenly.", "Make sure you cook on medium heat as it allows the Paneer Stuffed Ragi Paratha Recipe to get a crisp on the outside and yet soft texture.Once the Paneer Stuffed Ragi Paratha Recipe is cooked transfer to a plate.", "Continue to the same process with the remaining parathas the same way.Serve this Paneer Stuffed Ragi Paratha Recipe\u00a0along with\u00a0Spring Onion and Peanut Raita Recipe\u00a0and\u00a0Amla Achaar Recipe\u00a0for a hearty and healthy\u00a0high protein breakfast\u00a0or an\u00a0indian diabetic breakfast or lunch."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Ragi_Paneer_Stuffed_Paratha_Recipe_Nutralite-5.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/314.Ragi_Paneer_Stuffed_Paratha_Recipe_Nutralite-5.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Vendakkai Saddam Recipe (Spicy Okra Rice)', 'chettinad-vendakkai-saddam-recipe-spicy-okra-rice', 'Chettinad Vendakkai Saddam or Bhindi Rice is a delicious South Indian Chettinad style preparation of the rice that is spicy, tangy and delicious. The rice is spiced with black pepper, small baby onions and gets its tanginess from the tamarind. The Chettinad Vendakkai Saddam makes a perfect one meal dish, that you can serve with raita for a weeknight dinner.', '["1-1/2 cups Cooked rice", "10 Bhindi (Lady Finger/Okra) , cut into small dices", "10 Shallots , cut into small pieces", "1 tablespoon Tamarind Paste", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Black pepper powder", "1 pinch Cinnamon Powder (Dalchini)", "1 teaspoon Chana dal (Bengal Gram Dal)", "10 Cashew nuts", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves , finely chopped", "1 tablespoon Oil", "Salt , to taste"]'::jsonb, ARRAY['s cooked rice', 'bhindi', 'lady finger/okra', 'shallots', 'tamarind paste', 'turmeric powder', 'haldi', 'black pepper powder', 'cinnamon powder', 'dalchini', 'chana dal', 'bengal gram dal', 'cashew nuts', 'mustard seeds', 'rai/ kadugu', 'curry leaves', 'oil', 'salt']::text[], '["To begin making the Chettinad Vendakkai Saddam Recipe (Spicy Okra Rice), we will first cook the okra along with the spices.Take a heavy bottomed pan and heat the spoonful of oil on medium heat.", "Add the onions and the Vendakkai and salt to taste.", "Stir fry on low to medium heat until the okra (Vendakkai) is well cooked and roasted.", "This will take about 10 minutes.Once the Vendakkai\u00a0is well cooked, add the turmeric powder, curry leaves, cinnamon powder, black pepper powder, salt, thick tamarind paste and saut\u00e9 the ladies fingers till it gets coated well with all the other ingredients.", "Now, in another tadka pan, heat a teaspoon of oil.", "Add in the mustard seeds, channa dal and cashews.", "Allow them to crackle and get roasted until lightly browned.", "Add this to the\u00a0Vendakkai mixture.Stir the seasoning well into the\u00a0Vendakkai mixture.", "At this stage add in the cooked rice.", "Stir together all the ingredients until well combined.", "Turn the heat to low, cover the pan and simmer for 3 to 4 minutes.", "Check the salt and spices and adjust to suit your taste.Finally, turn off the heat and transfer the\u00a0Chettinad Vendakkai Saddam to a serving bowl.Serve the delicious tangy and spicy Chettinad Vendakkai Saddam Recipe (Spicy Okra Rice)\u00a0hot along with a\u00a0tomato onion\u00a0raita."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Chettinad_Vendakkai_Saddam_Recipe_Spicy_Okra_Rice-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/315.Chettinad_Vendakkai_Saddam_Recipe_Spicy_Okra_Rice-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kurkuri Bhindi And Onion Masala Recipe', 'kurkuri-bhindi-and-onion-masala-recipe', 'Kurkuri Bhindi And Onion Masala is a go to recipe for your house parties. Simple yet something different, I am sure your guests will love it. Try this twist to your regular bhindi and you will make it again and again.', '["250 grams Bhindi (Lady Finger/Okra) , sliced in small round shape", "1-1/2 tablespoon Gram flour (besan)", "1-1/2 teaspoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "1-1/2 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Amchur (Dry Mango Powder)", "Salt , as required", "Water , as required", "Oil , as required", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)", "1 tablespoon Ginger Garlic Paste", "1 Green Chilli , finely chopped", "2 Onions , finely chopped", "Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['s bhindi', 'lady finger/okra', 'gram flour', 'besan', 'red chilli powder', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'amchur', 'dry mango powder', 'salt', 'water', 'oil', 'cumin seeds', 'jeera', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing', 'ginger garlic paste', 'reen chilli', 'onions', 'coriander']::text[], '["To begin making the Kurkuri Bhindi And Onion Masala recipe, Firstly we will make the kurkuri bhindi.", "Take a mixing bowl, add the sliced bhindi, besan, 1/2 teaspoon red chilli powder, 1/2 teaspoon turmeric powder, 1/2 teaspoon coriander powder, 1/2 teaspoon amchur powder, required salt and a little water.", "Mix everything properly.Once it is done, heat oil in a wok and fry the bhindis.", "Once done, take it out on the absorbent paper to absorb the extra oil.", "Keep it aside.Now heat oil in a different wok.", "Add cumin seeds, mustard seeds, hing and green chillies.After 10 to 15 seconds add in the ginger garlic paste.", "Saute it for a minute and then add the chopped onions.", "Cook till it becomes soft and translucent.Add in the remaining red chilli powder, turmeric powder, coriander powder and the required salt.", "Mix it, cover the kadai and let it cook for 3 to 4 minutes.Add in the fried bhindi and mix it properly.", "Cook for two more minutes, switch off the stove and garnish with chopped coriander leaves.Serve Kurkuri Bhindi And Onion Masala along with\u00a0Panchmel dal\u00a0and\u00a0Phulka\u00a0for a weekday meal."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Kurkuri_Bhindi_And_Onion_Masala.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/316.Kurkuri_Bhindi_And_Onion_Masala.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pulikuthi Upperi Recipe - Spicy & Tangy Palakkad Poriyal Recipe', 'pulikuthi-upperi-recipe-spicy-tangy-palakkad-poriyal-recipe', 'Pulikuthi Upperi Recipe is a traditional Palakkad style mixed vegetable sabzi/ poriyal cooked with tamarind and finished with a freshly prepared spice mix. The vegetables used in this recipe are preferably country vegetables like - white or yellow pumpkin, raw banana, lady finger, broad beans.', '["1 Raw Banana , peeled and cut into small cubes", "1 cup Kaddu (Parangikai/ Pumpkin) , cut into small cubes", "6 Bhindi (Lady Finger/Okra) , cut into 1 inch pieces", "20 grams Tamarind , lemon sized, soaked in warm water", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Jaggery", "To Be ground", "2 tablespoons Rice", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "7 Dry Red Chillies", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1/4 teaspoon Asafoetida (hing)", "Coconut Oil , for cooking", "Salt , to taste"]'::jsonb, ARRAY['salt', 'parangikai pumpkin', 'rice', 'mustard seeds', 'asafoetida (hing)', 'jaggery', 'curry leaves', 'dry red chillies', 'methi seeds (fenugreek seeds)', 'coconut oil', 'bhindi (lady fingerokra)', 'turmeric powder', 'banana', 'tamarind lemon']::text[], '["To begin making\u00a0Pulikuthi Upperi Recipe, soak the tamarind in 1/2 cup of hot water for 5 minutes, squeeze out the pulp and keep aside.Dry roast the raw rice, fenugreek seeds and dried red chilies in a small pan on low heat until it turns golden and aromatic.", "Grind it into a fine powder using a mixer grinder and keep aside.Since all the vegetables have different cooking times, we will cook each of them separately.Into a kadai, heat 1 teaspoon of oil add the raw banana, sprinkle some salt and stir fry until the raw banana is tender and cooked.", "You can can cover the pan and cook the raw banana until done.", "Keep this aside.Into the same kadai, add 1/2 teaspoon oil; add the pumpkin, sprinkle salt, the tamarind pulp, jaggery, turmeric powder and stir fry until the pumpkin is tender and cooked.", "You can can cover the pan and cook the pumpkin until done.", "Keep this aside.Lastly for the Pulikuthi Upperi, into a new kadai, add 1/2 teaspoon oil; add the mustard seeds and allow them to crackle.", "Add the hing and curry leaves and saute for a few seconds.Add the bhindi, sprinkle salt and\u00a0stir fry until the bhindi is tender and cooked.", "You can can cover the pan and cook the\u00a0bhindi until done.", "Add the cooked pumpkin, the raw banana and the ground spiced into the cooked bhindi and stir until well combined.", "Check the salt and chillies and adjust to suit your taste.", "Once done, turn off the heat and serve the\u00a0Pulikuthi Upperi hot.Serve the\u00a0Pulikuthi Upperi Recipe along with\u00a0Steamed Rice,\u00a0Thakkali Vengaya Sambar, Curd and Appalam for a delectable\u00a0weeknight dinner."]'::jsonb, 30, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Pulikuthi_Upperi_Recipe_Palakkad_Style_Country_Vegetables_Cooked_with_Tamarind.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/317.Pulikuthi_Upperi_Recipe_Palakkad_Style_Country_Vegetables_Cooked_with_Tamarind.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ambur Style Brinjal Curry Recipe', 'ambur-style-brinjal-curry-recipe', 'Brinjal Curry is prepared in different ways in different regions. Here, we have followed the style which is used in Ambur which is famous for its Brinjal Curry.', '["5 Brinjal (Baingan / Eggplant)", "1 Onion", "2 Tomatoes", "1 tablespoon Ginger Garlic Paste", "2 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Coriander Powder (Dhania)", "Salt , as needed", "20 grams Tamarind , size of a small gooseberry", "2 tablespoon Gingelly oil", "sprig Curry leaves", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "4 Whole Black Peppercorns", "2 tablespoons Roasted Peanuts (Moongphali)", "1 tablespoon Sesame seeds (Til seeds)", "1 tablespoon Fresh coconut"]'::jsonb, ARRAY['brinjal', 'baingan / eggplant', 'onion', 'tomatoes', 'ginger garlic paste', 'red chilli powder', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'salt', 's tamarind', 'gingelly oil', 'sprig curry leaves', 'mustard seeds', 'rai/ kadugu', 'whole black peppercorns', 's roasted peanuts', 'moongphali', 'sesame seeds', 'til seeds', 'fresh coconut']::text[], '["To begin making the Ambur Style Brinjal Curry Recipe, add oil in a heavy bottomed pan and wait till the oil heats up.Add in the mustard seeds, peppercorns, curry leaves and sliced onions, fry till onions become translucent.Then add in tomato and cook till it leaves oil on the side of the pan and then add in the ginger garlic paste saut\u00e9 it well till the raw smell goes away.", "Next add in the brinjals and mix well.Next add in the spice powders including red chilli powder, coriander powder, turmeric powder, salt and mix well.", "Soak the tamarind in water for about 20 minutes and squeeze out the water.Add in the tamarind water in the pan and cook till the brinjals become soft.Next dry roast the peanuts, sesame seeds and coconut in a pan and cool down then grind that into a coarse powder.", "Add the ground masala to the brinjal gravy and mix well.", "Allow it to simmer for two minutes and switch off the flame.", "Serve hot.Serve this\u00a0Ambur Style Brinjal Curry Recipe\u00a0along with\u00a0Ambur Star Chicken Biryani Recipe\u00a0and\u00a0Tomato Onion Tadka Raita\u00a0for your everyday meals."]'::jsonb, 20, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/happytrioexplains-gmail.com/Brinjal_curry_for_Biryani.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/318.Brinjal_curry_for_Biryani.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hirve Kaalvan Recipe (Fresh Coriander and Coconut Curry)', 'hirve-kaalvan-recipe-fresh-coriander-and-coconut-curry', 'Hirve Kaalvan or Fresh Coriander and Coconut Curry is a perfect dish that can be prepared especially when you are tired of the usual dal accompanying your meals. This is a versatile curry that goes with any meal, that is mild and creamy. The Hirve Kaalvan pairs beautifully hot steamed rice and makes great lunch for weekdays.', '["1/4 cup Coriander (Dhania) Leaves , chopped", "1/4 cup Fresh coconut , grated", "1 Green Chilli", "1 teaspoon Cumin seeds (Jeera)", "200 liter Coconut milk", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Rice flour", "Salt , to taste", "2 tablespoon Oil"]'::jsonb, ARRAY['coriander', 'dhania', 'fresh coconut', 'reen chilli', 'cumin seeds', 'jeera', 'liter coconut milk', 'turmeric powder', 'haldi', 'rice flour', 'salt', 'oil']::text[], '["To make Hirve Kaalvan, first wash coriander leaves in water to remove dirt and dust particles.", "Pat dry coriander leaves with a kitchen towel.", "Roughly chop them and transfer to a bowl.", "To make paste for the curry, in a blender or food processor add\u00a0grated coconut, chopped coriander leaves, green chilli, salt and cumin seeds using 1 - 2 tablespoon of water grind to make a smooth paste.", "Transfer the\u00a0paste to a bowl and keep aside until required.Now take a 2 tablespoon of the coconut milk and dissolve rice flour to it.", "Stir to make a lump free smooth mixture.", "Make sure rice flour is fully dissolved in coconut milk.", "Add this to the remaining \u00a0coconut milk and whisk it all together to form smooth lump free mixture.Next, heat oil in a saucepan over medium heat.", "Once the oil is heated add coconut and coriander paste made earlier to the pan.", "Stir the paste continuously to avoid sticking to the pan.", "If still paste sticks to the pan, reduce the flame to low.Pour coconut milk into the paste in the pan along with turmeric.", "Stir to combine and if you feel the curry seems too thick, you can adjust the consistency adding water.Allow the curry to simmer on a low flame for about 3 to 5 minutes and turn off the heat.", "Note: You can make the curry and keep it refrigerated and simmer only when you are ready to serve.", "This way we don''t overcook the curry and the nutrition is not lost.", "Serve the Hirve Kaalvan with steaming hot rice for a weeknight dinner or even lunch."]'::jsonb, 45, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Hina_Gujral/Hirve_Kaalvan_or_Fresh_Coriander_and_Coconut_Curry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/319.Hirve_Kaalvan_or_Fresh_Coriander_and_Coconut_Curry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tomato Rice With Basil Recipe', 'tomato-rice-with-basil-recipe', 'Tomato Rice With Basil is a delicious fusion recipe where rice is cooked with tomatoes with a twit of basil. The rich and delicious taste of this rice makes it a great dish to serve for house parties or weekend dinners.', '["1 cup Rice , or brown rice", "3 Tomatoes", "1 Green Chilli , finely chopped", "Basil leaves , Few, roughly torn", "7 cloves Garlic , crushed", "Extra Virgin Olive Oil , as required", "1 teaspoon Whole Black Peppercorns", "Salt , as required", "Water , as needed", "Coriander (Dhania) Leaves , or Basil leaves for garnish"]'::jsonb, ARRAY['tomato', 'salt', 'green chilli', 'cloves garlic', 'basil leaves', 'virgin olive oil', 'rice brown rice', 'black peppercorns', 'water', 'coriander (dhania) leaves basil leaves']::text[], '["To begin making the Tomato Rice With Basil recipe, firstly add tomatoes with required amount of water in a saucepan.", "Cook it till the skin of tomatoes start coming out.Peel the skin of the tomatoes and chop them very finely.", "Keep them aside.Heat olive oil in a wide pan and add garlic and green chillies.", "Cook it till the raw smell of garlic vanishes.Add chopped tomatoes and basil leaves into the pan and cook it for about 2 to 3 minutes.After 2 to 3 minutes, add rice, salt and black pepper and cook till the rice is cooked properly.Once it is done, garnish it with chopped coriander leaves or basil leaves.Serve Tomato Rice With Basil on its own or with an raita of your choice."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/tomato_basil_rice_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/320.tomato_basil_rice_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chana Turai/Nenua Chana Sabzi Recipe (Ridge Gourd with Black Chana Recipe)', 'chana-turai-nenua-chana-sabzi-recipe-ridge-gourd-with-black-chana-recipe', 'Chana Turai/Nenua Chana Sabzi Recipe (Ridge Gourd with Black Chana Recipe) is a most popular simple recipe made in the region of Uttar Pradesh. The dish has the classic but yet the rustic flavors which brings out the true flavor of the dish. It is usually prepared during the summer season of UP.', '["1 cup Kala Chana (Brown Chickpeas) , soaked overnight", "500 grams Ridge Gourd (Turai/ Peerkangai) , sliced", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 pinch Asafoetida (hing)", "2 Onions , sliced", "4 cloves Garlic", "2 Green Chilli , chopped", "2 teaspoon Cumin seeds (Jeera)", "2 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Amchur (Dry Mango Powder)", "1 tablespoon Mustard oil"]'::jsonb, ARRAY['green chilli', 'amchur (dry mango powder)', 'asafoetida (hing)', 'mustard seeds', 'mustard oil', 'ridge gourd (turai peerkangai)', 'red chilli powder', 'cloves garlic', 'onion', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'kala chana (brown chickpeas)']::text[], '["We begin making the Chana Turai/Nenua Chana Sabzi Recipe (Ridge Gourd with Black Chana Recipe) by soaking the chana overnight or for 8 hours in water.Heat a kadai with oil, splutter the mustard seeds, fenugreek seeds and hing.", "Add chopped onions and fry them till it is translucent.", "Add in the green chillies after few minutes and Give it a stir.Next add all the red chilli powder, turmeric powder and coriander powder and mix well.", "Now at this point add the soaked channa along with the water and mix.Boil it over for few seconds till the water is all evaporated.", "Then add the chopped ridge gourd and mix well.", "You can also \u00bd cup of water and close it and cook.Once you remove the lid add the mango powder and cumin powder and mix well.", "Saute till the water is all evaporated and serve hot.", "Serve the Chana Turai/Nenua Chana Sabzi Recipe (Ridge Gourd with Black Chana Recipe) along with\u00a0Hot Phulka\u00a0or steamed Rice as your\u00a0healthy Lunch."]'::jsonb, 30, 'Bihari', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Chana_TuraiNenua_Chana_Sabzi_Recipe_Ridge_Gourd_with_Black_Chana_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/321.Chana_TuraiNenua_Chana_Sabzi_Recipe_Ridge_Gourd_with_Black_Chana_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tomato pulao Recipe', 'tomato-pulao-recipe', 'This Tomato pulao is a Karnataka style recipe with tomatoes and rice cooked in a melange of spices ground to paste. This one pot wonder makes for a perfect relaxed spicy Sunday brunch.', '["1 cup Basmati rice", "3 Tomatoes , diced into large pieces", "1 Onion , sliced", "10 Mint Leaves (Pudina)", "1/2 teaspoon Cumin seeds (Jeera)", "1 Bay leaves (tej patta)", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Sugar", "1 teaspoon Lemon juice", "2 tablespoon Oil", "1 tablespoon Ghee", "To grind", "1 tablespoon Coriander (Dhania) Seeds", "2 teaspoons Poppy seeds", "1 teaspoon Cumin seeds (Jeera)", "7 to 8 Whole Black Peppercorns", "1 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "2 Green Chillies", "1-1/2 teaspoon Red Chilli powder", "6 Garlic", "1/2 Onion", "1/2 inch Ginger"]'::jsonb, ARRAY['basmati rice', 'green chillies', 'ginger', 'bay leaves (tej patta)', 'ghee', 'red chilli powder', 'black peppercorns', 'sugar', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'tomato large', 'lemon', 'poppy seeds', 'cinnamon stick (dalchini)', 'mint leaves (pudina)', 'garlic', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Tomato pulao recipe, soak basmati rice for 10 to 20 minutes.Chop tomatoes, slice onion and prepare all ingredients required.In a small mixer jar add coriander seeds, cumin seeds,poppy seeds, cinnamon stick, cloves and whole black peppercorn and grind to a powder.", "Now add the rest of the ingredients like the green chillies, ginger, garlic, red chilli powder, turmeric powder, onion and ginger with very little water and blend till smooth.In a large heavy bottomed pan heat oil and ghee, add jeera and let it crackle, now add bay leaf and then add sliced onions.Saute until the onions are golden and then add the ground paste and saute on a low flame.", "Keep stirring or else the masala will stick to the bottom of the pam.", "Cook for a couple of minutes until the raw smell disappears and the oil separates.Once done add tomatoes and mint leaves and cook for a minute till the tomatoes turn soft.After the tomatoes are soft add 1 cup of water, salt to taste, sugar and lemon juice.Bring it to a boil and add the rice and mix everything well until combined.Now add another 3/4 cup of water bring it to a boil.", "Lower the flame to simmer and cook covered for 15 minutes or until all the liquid is evaporated.Turn of the heat, let the Tomato Pulao sit for 10 minutes and then serve hot.Serve Tomato pulao with\u00a0Burani Raita\u00a0or any other raita of your choice for a delicious meal."]'::jsonb, 50, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Gauravi_Vinay/Tomato_pulav.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/322.Tomato_pulav.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vankaya Ulli Karam Recipe - Eggplant In Spicy Onion Gravy', 'vankaya-ulli-karam-recipe-eggplant-in-spicy-onion-gravy', 'Vankaya Ulli Karam Recipe (Eggplants In Spicy Onion Gravy) is a delicious version of eggplants that is made in Andhra households. This recipe is traditionally made from small eggplants that are locally available in Andhra and tastes so different from Gutti Vankaya Recipe of Andhra, which is a slightly trickier recipe than this. You can create same recipe with pointed gourd and ivy gourd too, instead of brinjals.', '["16 Small Brinjal (Baingan / Eggplant)", "2 Onions , chopped", "1 Tomato , chopped", "3 cloves Garlic , finely chopped", "1/2 inch Ginger , finely chopped", "3 Green Chillies , slit", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Coriander (Dhania) Seeds", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "Salt , to taste", "Oil , to cook", "Coriander (Dhania) Leaves , chopped, to garnish"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'coriander (dhania) leaves', 'brinjal (baingan eggsplant)', 'cloves garlic', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'green chillies', 'sunflower oil']::text[], '["To begin making Vankaya Ulli Karam Recipe (Eggplants In Spicy Onion Gravy), first slit them twice diagonally 3/4th long such that you do not disturb their stalk/ crown.", "Prep the rest of the ingredients as well.In a kadai/heavy bottomed pan, heat the required oil and add cumin seeds.Once the cumin sizzles, add coriander & fenugreek seeds, once they become fragrant, add the garlic & ginger.Fry for a minute and add the chopped onions.", "Cook until they turn slightly soft & pinkish.Add the tomatoes, chillies and fry for a couple of minutes.Add salt, mix it well & switch off the flame.Once it cools down, grind it into a paste.", "Now, fill the ground masala into the slit eggplants.Heat oil in the kadai and & add these eggplants to it.", "Add the remaining masala as well to it.Cover it & cook until the eggplants are soft & mushy.", "Keep stirring in between, but carefully so that the brinjal does not become mushy.Keep cooking it till the eggplants are cooked, and the mixture comes together and becomes brownish in colour.", "Make sure you don''t burn them.Once done, add lots of coriander to it and switch off heat.Serve Vankaya Ulli Karam Recipe along with Steamed Rice, and Moong Dal Rasam/Pesara Pappu Charu Recipe and Black Chickpea Salad Recipe for a complete meal."]'::jsonb, 35, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/anusha.pariti-gmail.com/Vankaya_Ulli_Karam__Eggplants_in_onion_gravy.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/323.Vankaya_Ulli_Karam__Eggplants_in_onion_gravy.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pudina Mushroom And Soya Biryani Recipe', 'pudina-mushroom-and-soya-biryani-recipe', 'Pudina Mushroom And Soya Biryani Recipe is a delicious one pot biryani recipe, made by putting together mushrooms along with soya chunks seasoned with whole spices and pudina leaves, along with rice, making it a delectable rice dish.', '["1-1/2 cups Basmati rice , parboiled with spices infused water (Spices include Cinnamon, One Mint branch, 2-3 Cloves and Cardamoms, 1 Bay leaf)", "1 cup Button mushrooms , cut into quarters", "1 cup Soy Chunks (Nuggets) , soaked in hot water", "1 cup Onion , sliced", "1 inch Ginger", "1/2 cup Curd (Dahi / Yogurt)", "2 tablespoons Biryani Masala", "3 cloves Garlic", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "2 teaspoon Red Chilli powder", "1/4 cup Mint Leaves (Pudina) , finely chopped", "Salt , to taste", "2 tablespoons Ghee", "1 Green Chillies , chopped", "1 teaspoon Ajwain (Carom seeds)", "1 Bay leaf (tej patta)", "1 Star anise", "1 Cardamom (Elaichi) Pods/Seeds", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)"]'::jsonb, ARRAY['ajwain (carom seeds)', 'cloves garlic', 'onion', 'soy (nuggets)', 'turmeric powder', 'green chillies', 'salt', 'cardamom (elaichi) podsseeds', 'mint leaves (pudina)', 'star anise', 'garam masala powder', 'red chilli powder', 'curd', 'button mushrooms', 'ginger', 'ghee', 'bay leaf (tej patta)', 'biryani masala', 'basmati rice spices infused water (spices include cinnamon', 'cinnamon stick (dalchini)', 'cloves (laung)']::text[], '["To begin making the Pudina Mushroom And Soya Biryani recipe, wash and soak the rice in water for 20 minutes.", "In a bowl, place the soya chunks, and pour boiling hot water over it and allow it to soak in it.", "In a pressure cooker, heat ghee on low flame, add the whole spices - cumin seeds, bay leaf, star anise, cardamom, cloves, cinnamon stick, once these begin to sizzle, add in the ginger, garlic, green chili, saute for a coulee of minutes.", "Next increase the heat to medium -low and add the sliced onions and cook until transparent, this will take about 2-3 minutes.", "At this stage, add the mushrooms, and the dry masalas - biryani masala, turmeric powder, red chili powder, garam masala, salt and give it a good mix.", "Now add the curd, drained soya chunks, pudina leaves, drained rice and 2 cups of water and close the pressure cooker.", "Allow the\u00a0Pudina Mushroom And Soya Biryani recipe to pressure cook for 2 whistles and turn off the flame.", "Allow the pressure to release naturally.", "Once released, open the pressure cooker and gently sluff up the\u00a0Pudina Mushroom And Soya Biryani recipe and transfer to a serving bowl and serve hot.Serve hot Pudina Mushroom And Soya Biryani along with\u00a0Boondi raita\u00a0and\u00a0Kachumber Salad\u00a0for a weeknight dinner."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/ishita74-hotmail.com/Pudina_Mushroom_Soya_Biryani_Recipe-6.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/324.Pudina_Mushroom_Soya_Biryani_Recipe-6.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Baby Corn and Green Peas Sabzi Recipe', 'baby-corn-and-green-peas-sabzi-recipe', 'Baby Corn and Green Peas Sabzi Recipe will be a quick stir fry with vegetables and some spices. Baby corn is diabetic friendly and helps to reduce cholesterol in the body.', '["10 Baby corn , chopped into pieces (if using fresh, boil them until tender)", "1 cup Green peas (Matar)", "1 Onion , finely chopped", "2 Green Chillies , slit", "1 inch Ginger , finely chopped", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 pinch Asafoetida (hing)", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin seeds (Jeera) , roasted and crushed", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Garam masala powder", "Salt , to taste", "Oil , as required", "2 sprig Curry leaves", "1 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['salt', 'ginger', 'mustard seeds', 'asafoetida (hing)', 'green peas (matar)', 'red chilli powder', 'curry leaves', 'coriander (dhania) leaves', 'onion', 'cumin seeds (jeera)', 'baby corn (if using', 'turmeric powder', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Baby Corn and Green Peas Sabzi Recipe, firstly\u00a0pressure cook the baby corn with salt and turmeric powder for about 3 whistle.", "Release the pressure naturally and strain the water.", "Heat oil in a heavy bottomed pan.", "Add the mustard seeds, hing and let the mustard seeds crackle.Once it crackles, add in the curry leaves and saute it for about 20 seconds.After 20 seconds, add the onions, ginger and green chillies and saute till the onions are golden brown.", "Add the Baby Corn, Peas along with salt, turmeric powder, red chilli powder, crushed cumin seeds, garam masala powder and salt.Stir fry till the raw smell goes away.", "This will take about 3 to 4 minutes.Once done, add in the chopped coriander leaves, give it a stir and it is ready to be served."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Baby_Corn_and_Green_Peas_Thoran_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/325.Baby_Corn_and_Green_Peas_Thoran_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Stuffed Ridge Gourd Recipe', 'stuffed-ridge-gourd-recipe', 'Stuffed Ridge Gourd Recipe is a must try vegetable curry. This dish is made by stuffing onion and tomato masala into the cylindrical shaped ridge gourd pieces and then sautéed until they turn soft and juicy. The stuffed ridge gourd is then cooked along with some more leftover masalas until it has observed all its flavors.', '["1 Ridge Gourd (Turai/ Peerkangai) , skin peeled and cut into 2 inch cylindrical.", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Onion , chopped", "1 Tomato , chopped", "2 tablespoon Roasted Peanuts (Moongphali)", "1 Green Chilli , chopped", "2 sprig Coriander (Dhania) Leaves", "4 cloves Garlic", "1 teaspoon Cumin seeds (Jeera)"]'::jsonb, ARRAY['tomato', 'green chilli', 'mustard seeds', 'cloves garlic', 'ridge gourd (turai peerkangai) skin cylindrical.', 'coriander (dhania) leaves', 'onion', 'cumin seeds (jeera)', 'peanuts (moongphali)']::text[], '["To begin making the Stuffed Ridge Gourd Recipe prep the ridge gourd and keep it ready.", "Slit each cylinder into 4.", "Do not cut too much.Grind all the ingredient\u2019s with little water to a smooth paste.", "Once that is ground, stuff in the filling into the cut the ridge gourd and keep it aside.Heat a sauce pan with oil, add mustard seeds and allow it to crackle for 10 seconds.Place the stuffed ridge gourd and cook them till for 5 minutes.", "Keep turning the ridge gourd so that it does not stick to the pan.Add the ground paste and little water and cook it covered with a lid, add salt and carefully mix.", "Cook until the masala reduces.Serve the Stuffed Ridge Gourd Recipe along with\u00a0Tawa Paratha,\u00a0Dal Palak Recipe\u00a0and\u00a0Spinach Rice\u00a0to make it a complete meal."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Stuffed_Ridge_Gourd_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/326.Stuffed_Ridge_Gourd_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Style Pepper Mushroom Recipe', 'chettinad-style-pepper-mushroom-recipe', 'Chettinad Style Pepper Mushroom Recipe is a spicy dish having the prominent pepper flavor. Mushrooms are a storehouse of nutrients. It is a rich source of calcium and Vitamin D, making it beneficial for bone health and overall immune system in the body. Chettinad Style Pepper Mushroom is a semi gravy dish, making a great accompaniment for roti''s and steamed rice for a healthy lunch or dinner.', '["1 cup Button mushrooms , cleaned and sliced", "1 Tomato , finely chopped", "1 Green Chilli , slit", "1 Bay leaf (tej patta)", "1/2 teaspoon Fennel seeds (Saunf)", "1 sprig Curry leaves", "Coriander (Dhania) Leaves , small bunch, finely chopped", "2 tablespoons Oil", "Salt , to taste", "Ingredients for The Aromatic Spice Mix", "4 teaspoons Fresh coconut , grated", "1 tablespoon Coriander (Dhania) Seeds", "1 teaspoon Whole Black Peppercorns", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Poppy seeds", "1 teaspoon Fennel seeds (Saunf)", "1 Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "4 Cloves (Laung)", "1 Star anise", "1 Mace (Javitri) , small flower", "1/4 teaspoon Nutmeg powder", "3 Dry Red Chilli", "2 teaspoons White Urad Dal (Split)", "Ingredients for The Wet Paste", "10 Shallots", "5 cloves Garlic , peeled", "2 inch Ginger", "1 sprig Curry leaves", "1/2 teaspoon Turmeric powder (Haldi)"]'::jsonb, ARRAY['tomato', 'mace (javitri) flower', 'black peppercorns', 'cloves garlic', 'curry leaves', 'white urad dal (split)', 'coriander (dhania) seeds', 'cumin seeds (jeera)', 'turmeric powder', 'sunflower oil', 'coriander (dhania)', 'salt', 'green chilli', 'cardamom (elaichi) podsseeds', 'star anise', 'nutmeg powder', 'coconut', 'dry red chilli', 'button mushrooms', 'ginger', 'bay leaf (tej patta)', 'fennel seeds (saunf)', 'poppy seeds', 'cinnamon stick (dalchini)', 'cloves (laung)']::text[], '["To begin making Chettinad Style Pepper Mushroom Recipe, start with making the aromatic spice mix.", "Take a pan and dry roast the ingredients listed in the spice mix till aromatic, grind it to a fine paste using a mixer and keep it aside.Now, make a paste of shallots, ginger, garlic, curry leaves and turmeric powder to fine paste and keep it aside.Heat a wide pan in low flame, pour oil, put the bay leaf, fennel seeds, and curry leaves and let it splutter.Now add the chopped tomato and the slit green chili and saut\u00e9 for five minutes.Add the onion, ginger garlic paste that was made earlier and cook till the raw smell of the ginger garlic goes away.Add the aromatic spice mixture, season with salt and add a little water and let it cook for ten minutes, keep stirring the gravy in between.Now add the cleaned, sliced mushrooms and cook it with the lid on for few more minutes.Once the mushrooms are cooked, switch off the flame and garnish with the finely chopped coriander leaves.Serve Chettinad Style Pepper Mushroom Recipe with rotis or steamed rice for lunch or dinner."]'::jsonb, 35, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Chettinad_Style_Pepper_Mushroom_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/327.Chettinad_Style_Pepper_Mushroom_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Omakka Curry Recipe - Kerala Style Papaya Curry', 'omakka-curry-recipe-kerala-style-papaya-curry', 'Omakka Curry is a simple Papaya based curry which is made in most of the Kerala households for lunch or dinner. it is mildly spicy and is eaten with Kerala Matta Rice. Full of flavour and taste, this curry is delicious and easy to make.', '["1/2 Raw papaya", "1 Green Chilli , adjustable", "1 cup Fresh coconut , grated", "3 Pearl onions (Sambar Onions) , thinly sliced", "2 sprig Curry leaves", "2 teaspoons Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies", "Tamarind , Gooseberry Sized", "Oil , as required", "Salt , to taste"]'::jsonb, ARRAY['salt', 'green chilli', 'coconut', 'mustard seeds', 'tamarind gooseberry', 'red chilli powder', 'pearl onion (sambar onion)', 'curry leaves', 'papaya', 'dry red chillies', 'cumin seeds (jeera)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Omakka Curry Recipe, cut the papaya into medium cubes and mix with red chilli powder, turmeric powder and salt with a little water.Add them into a pressure cooker and cook till it releases 1 whistle.", "After 1 whistle, simmer for 5 minutes on low heat.", "Switch off the heat and let the pressure release naturally.", "In the meantime, soak the tamarind in warm water.", "Take out the pulp after 15 minutes and keep it aside.In a mixie jar, take the grated coconut, green chillies, 1 sambar onion, and cumin seeds with a little water and proceed to make a fine paste.", "Keep it aside.Open the cooker, mash the cooked papaya into a soft pulp and mix with the coconut green chilli and onion paste.", "Switch on the heat again.", "Cook it on a very low flame.", "Water can be added at this stage if you need less consistency in your curry.", "Keep stirring for only a few seconds and then add the tamarind pulp to it.Cook this for 3 or 4 minutes on a low flame.", "Switch off the flame.Heat required oil in a tadka pan.", "Add mustard seeds and when they crackle, add thinly sliced sambar onions.When the onions turn brown, add the dry red chillies and curry leaves.", "Saute for about 15 seconds and turn off the gas.Pour this onto the papaya curry and give it a stir.", "Serve hot.Serve\u00a0Omakka Curry\u00a0along with Kerala Matta Rice/\u00a0Steamed Rice\u00a0for a weekday lunch.", "You can also serve it with\u00a0Phulka\u00a0and\u00a0Beetroot Raita\u00a0for your everyday meals."]'::jsonb, 30, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Affiliate-Articles/Ommakka_papaya_curry_Kerala_Style.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/328.Ommakka_papaya_curry_Kerala_Style.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Easy Creamy Chicken Curry Recipe', 'easy-creamy-chicken-curry-recipe', 'Easy Creamy Chicken Curry Recipe is a North Indian Style Chicken recipe which is flavoured with cream, black pepper and dried methi. It is an one pot chicken curry recipe which you can make for your everyday dinners or when you have sudden guests at home. This creamy chicken is a perfect recipe to satisfy your taste buds during the weekday. So give it a try and let us know how you liked it!', '["500 grams Chicken , with bones", "2 Cups Curd (Dahi / Yogurt)", "1 tablespoon Lemon juice", "Salt , to taste", "1 inch Ginger , minced", "8 cloves Garlic , minced", "1 teaspoon Black pepper powder", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "1/2 cup Fresh cream", "1 tablespoon Oil"]'::jsonb, ARRAY['salt', 'ginger', 'cloves garlic', 'curd', 'lemon', 'black pepper powder', 'chicken bs', 'kasuri methi (dried fenugreek leaves)', 'sunflower oil']::text[], '["To begin making the Easy Creamy Chicken Curry Recipe, we will firstly marinate the chicken.", "In a bowl, add lemon juice, salt and yogurt and mix well.Add chicken pieces, mix well so that the chicken is properly coated with the marination.", "Once done keep it aside for an hour.", "You can also keep it aside overnight.To make the curry, heat the required oil in a heavy bottomed pan.", "Once the oil is a little hot, add garlic, ginger, a little water and let it cook for 3 to 4 minutes.Next, add the chicken pieces one by one while shaking off the excess marinade.", "Without disturbing the chicken cook it on one side for about 5 minutes on high heat so that it browns a bit.", "This step will improve the look and the depth of flavour.Flip the chicken pieces and continue cooking undisturbed for a further 5 minutes.", "Pour over rest of the marinade on the chicken.", "Cook the creamy chicken curry covered for about 25 minutes on slow flame.After about 25 minutes, remove the lid and give the creamy chicken curry a good stir.", "If needed add more water.Once the chicken is cooked, add cream, black pepper powder and kasuri methi.", "Mix everything and let the creamy chicken curry come to a boil.", "Once it comes to a boil, turn off the heat and serve hot.Serve\u00a0Easy Creamy Chicken Curry\u00a0along with\u00a0Tawa Paratha,\u00a0Tomato Onion Cucumber Raita\u00a0and\u00a0Jeera Rice\u00a0for an everyday meal with your family."]'::jsonb, 42, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/foodcoworg-gmail.com/Easy_Creamy_Chicken_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/329.Easy_Creamy_Chicken_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kala Chana Pilaf Recipe', 'kala-chana-pilaf-recipe', 'Kala Chana Pilaf Recipe is adapted from the Pakistani Cuisine. Pilaf is a flavourful rice dish, usually cooked with the white or red meats in Pakistan. The addition of whole garam masala adds a beautiful flavour to the dish. We have substituted the white chana with the kala chana to make it more healthy. The cinnamon quill adds a mild sweetness to the pilaf. Serve the Kala Chana Pilaf Recipe along with Spicy Chicken Curry, Cauliflower & Cucumber Raita and Fresh Garden Salad Recipe for the weekend brunch.', '["1 cup Basmati rice", "1 cup Kala Chana (Brown Chickpeas) , soaked overnight and boiled", "1 Onion , finely sliced", "1 Tomato , sliced", "2 Green Chillies , slit", "1 tablespoon Ginger Garlic Paste", "1 Bay leaf (tej patta)", "1 Cinnamon Stick (Dalchini)", "2 Black cardamom (Badi Elaichi)", "4 Cloves (Laung)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 teaspoon Fennel Powder", "1/2 cup Curd (Dahi / Yogurt)", "2 cups Water , or leftover water of cooked chana", "1 tablespoon Ghee", "Mint Leaves (Pudina) , Few, for garnish", "1 pinch Sugar", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'basmati rice', 'black cardamom (badi elaichi)', 'salt', 'garam masala powder', 'bay leaf (tej patta)', 'ghee', 'red chilli powder', 'water', 'ginger garlic paste', 'curd', 'fennel powder', 'sugar', 'onion', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'cloves (laung)', 'mint leaves (pudina)', 'green chillies', 'kala chana (brown chickpeas)']::text[], '["To begin making Kala Chana Pilaf Recipe, wash and soak the kala chana overnight.", "Pressure cook with 2 cups of water with salt and keep aside.Wash and soak the basmati rice in enough water for 10 minutes.Heat ghee in a wide pan on medium heat, add the bayleaf, cinnamon quill, cloves, black cardamom and let it release its aroma into the ghee.Add the cumin seeds and let it splutter.Add the sliced onions, a pinch of sugar and saute until it turns golden brown.Add the slit green chilli, tomatoes and saute for 2 minutes.Now, whisk the curd to a smooth texture and add it into the pan and mix well.Add the red chilli powder and garam masala and let it cook for 2 minutes.Add the boiled kala chana, season with salt and mix well.Now add the soaked and drained basmati rice, 2 cups of the kala chana broth saved from cooking chana.Close it with a lid and let it simmer for 20 minutes.Once the pilaf is cooked, garnish with mint leaves and serve the the Kala Chana Pilaf Recipe along with with Spicy Chicken Curry, Cauliflower & Cucumber Raita and Fresh Garden Salad Recipe for the weekend brunch."]'::jsonb, 40, 'Pakistani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Kala_Chana_Pilaf_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/330.Kala_Chana_Pilaf_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Konkan Style Modachya Moongachi Amti Recipe-Sprouted Moong Bean Curry', 'konkan-style-modachya-moongachi-amti-recipe-sprouted-moong-bean-curry', 'Modachya Moongachi Amti Recipe is a Konkani Style Sprouted Moong Bean Curry. Sprouted Moong Beans are a packed with proteins and are much healthier as compared to other lentils. This sprouted mung bean curry is a part of the very unique Konkan Cuisine of the coastal Maharashtra. Konkan cuisine predominantly uses desiccated or fresh coconut and kokum in its cuisine. Hence, the curry has a right balance of spice and tanginess.', '["1 cup Green Moong Dal (Whole)", "2 teaspoons Oil , or ghee", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 pinch Asafoetida (hing)", "1 sprig Curry leaves", "Salt , to taste", "Ingredients for Masala Paste", "1 Onion", "2 tablespoons Dessicated Coconut", "3 Dry Red Chillies", "3 cloves Garlic", "1 inch Ginger", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 Kokum (Malabar Tamarind) , or tomato"]'::jsonb, ARRAY['green moong dal', 'whole', 's oil', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing', 'curry leaves', 'salt', 'ingredients for masala paste', 'onion', 's dessicated coconut', 'dry red chillies', 's garlic', 'ginger', 'cumin seeds', 'jeera', 'red chilli powder', 'turmeric powder', 'haldi', 'kokum', 'malabar tamarind']::text[], '["To begin making Modachya Moongachi Amti Recipe, first pressure cook the sprouted moong beans with a little salt and two cups of water for one whistle.", "Once cooked, keep them aside.In the meantime, prepare a masala paste of\u00a0onion,\u00a0coconut,\u00a0red chilies,\u00a0garlic,\u00a0ginger,\u00a0cumin seeds,\u00a0red chili powder,\u00a0turmeric powder and\u00a0kokum along with some\u00a0water, and grind to a paste consistency in a mixer or a hand blender.Heat a wok in medium flame, pour oil, add the mustard seeds and asafoetida.", "Add the curry leaves and let it splutter.Add the cooked sprouted moong beans and stir it.Now add the ground masala paste and enough water to your desired consistency and season with salt.Simmer for ten minutes and switch off the flame.Serve\u00a0Modachya Moongachi Amti recipe\u00a0with\u00a0phulkas\u00a0or steamed rice,\u00a0cucumber salad\u00a0and roasted papad for a filling weeknight dinner."]'::jsonb, 35, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Modachya_Moongachi_Amti_Konkan_Style_Sprouted_Moong_Bean_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/331.Modachya_Moongachi_Amti_Konkan_Style_Sprouted_Moong_Bean_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lentil Dal with Coconut Milk Recipe', 'lentil-dal-with-coconut-milk-recipe', 'Lentil Dal with Coconut Milk Recipe is a quick dal which gives a twist where the dal gets its flavors from coconut milk and a blend of five spices and fresh ginger and garlic. When garnished with coconut bits and a squeeze of lime juice, this dal recipe makes it rich, sumptuous and healthy.', '["1 cup Fresh Green Toor Dal (Pigeon Pea)", "1 cup Coconut milk", "1 Onion , finely chopped", "1 Tomato , finely chopped", "2 Green Chillies , finely chopped", "2 inch Ginger , grated", "3 cloves Garlic", "2 Dry Red Chillies", "1 teaspoon Ghee", "2 tablespoons Curry powder , (or garam masala powder)", "1 teaspoon Kashmiri Red Chilli Powder", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 tablespoon Panch Phoran Masala", "Fresh coconut , Coconut bits for garnish", "Lemon wedges , as required", "Coriander (Dhania) Leaves , chopped for garnish"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'kashmiri red chilli powder', 'ghee', 'coriander (dhania) leaves', 'green toor dal (pigeon pea)', 'cloves garlic', 'dry red chillies', 'onion', 'cocunut', 'lemon', 'curry powder (or garam masala powder)', 'panch phoran masala', 'coconut milk', 'turmeric powder', 'green chillies']::text[], '["To begin making the Lentil Dal with Coconut Milk Recipe, start by washing the lentils clean.Pressure cook the lentils for 5-6 whistles in water, salt and turmeric.", "Wait for the pressure to release naturally.", "Once done, open the lid and set it aside.", "Drain and reserve the water.Heat a tablespoon of ghee in a kadhai or deep cauldron/ dutch oven on medium heat.Once hot, add the panch phoran and wait till the seeds crackle.", "Add the dried red chilies broken in half to it and roast it for a few seconds.", "Finally stir in the \u00a0ginger, garlic, green chillies to it.Saute for 2 mins on medium flame ensuring it doesn''t burn.", "Add the chopped onion to it and all the masala powders, give it a stir for another 3-4 minutes till onions are soft and golden brown.Add the chopped up tomatoes and fry the masala till the tomatoes are mixed in for another 3 to 4 minutes.", "Add just a dash of water if it sticks to the bottom of the pan.Once the tomatoes soften, add the cooked lentils to the masala and give it a good stir.Add 1 cup of the reserved lentil water to it, and the coconut milk.", "Check the salt and accordingly.Allow the dal to come to a boil and turn off the heat.", "Stir in the chopped coriander leaves and add the juice from the lemon.Serve the Lentil Dal with Coconut Milk garnish of coconut bits\u00a0along with a steaming bowl of steamed rice, pickle and papad for an easy trip down to your granny\u2019s."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Swayampurna_Mishra/Lentil_in_coconut_milk_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/332.Lentil_in_coconut_milk_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sindhi Dharan Ji Kadhi Recipe - Besan Tikkis In Tomato Gravy', 'sindhi-dharan-ji-kadhi-recipe-besan-tikkis-in-tomato-gravy', 'Sindhi Cuisine derives much of its influence from nature and geographical factors. Sindh weather is such that for many months fresh vegetables are not available.', '["2 Onions , pureed", "3 Tomatoes , pureed", "1 teaspoon Ginger Garlic Paste", "2 Green Chillies , chopped", "2 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin seeds (Jeera)", "2 Cloves (Laung)", "2 tablespoons Oil", "Coriander (Dhania) Leaves , finely chopped", "2 cups Gram flour (besan)", "1 Onion , finely chopped", "3 tablespoons Curd (Dahi / Yogurt)", "1 tablespoon Khuskhus", "Salt , as per your taste", "1 teaspoon Dry Red Chilli", "3 cups Water"]'::jsonb, ARRAY['tomato', 'salt', 'khuskhus', 'coriander (dhania) leaves', 'water', 'ginger garlic paste', 'gram flour (besan)', 'curd', 'dry red chilli', 'onion', 'cumin seeds (jeera)', 'cloves (laung)', 'coriander powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the\u00a0Sindhi Dharan Ji Kadhi Recipe, we have to first make the dharan or the besan chickpea flour tikkis.", "In a bowl, mix the besan, salt, finely chopped onion, red chilli powder, khus khus and 2 tablespoons oil.", "Mix all the ingredients well and then add the curd.Mix well together and make a soft dough with his mixture.", "Make lemon sized balls with the dharan dough and press flat to make it into a cutlet shape.In a deep fry pan, add cooking oil and allow to heat up.", "Once the oil is hot, add the prepared dharan/besan tikkis in it and fry until they are golden brown.", "Drain the\u00a0dharan/ tikki in a kitchen napkin to absorb the excess oil and keep it aside.", "In a heavy bottomed pan, add 2 teaspoons oil.", "Once the oil is hot, add cumin seeds, cloves and let the spices sputter.", "Next add the onion puree and saute until the puree changes colour.", "Next add the ginger garlic paste and stir until the raw smell goes away.", "This will take about 2 minutes.Next, add the tomato puree and chopped chilies. and saute until, the gravy combines well.", "Finally add in the coriander powder and mix well until the kadhi gravy comes together.Simmer and add the besan tikkis into the gravy.", "Add 2 cups of water and cook the Dharan Ji Kadhi a low flame with the lid on.", "Let the Dharan Ji Kadhi simmer until the tikkis turn soft.", "Turn off the flameAdd finely chopped coriander leaves and serve your Dharan Ji Kadhi.Serve Dharan JI Kadhi along with Phulkas or Tawa Parathas along with a Carrot Salad for a simple dinner meal."]'::jsonb, 30, 'Sindhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/bhagnarianju-yahoo.com/Dharan_Ji_Kadhi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/333.Dharan_Ji_Kadhi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Amlechi Uddamethi Recipe - Goan Raw Mango Curry', 'amlechi-uddamethi-recipe-goan-raw-mango-curry', 'The Amlechi Uddamethi Recipe is essentially a Goan Raw Mango Curry packed with a punch. It has sweet and sour notes from the jaggery and raw mango that go very well together.', '["2 Mango (Raw) , peeled and diced", "2 tablespoons Jaggery", "1/2 cup Water", "Salt", "3/4 cup Fresh coconut , grated", "1 teaspoon Turmeric powder (Haldi)", "30 grams Tamarind", "1/2 teaspoon Whole Black Pepper Corns", "3 Dry Red Chillies", "Salt", "2 teaspoons Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon White Urad Dal (Split)", "1/4 teaspoon Asafoetida (hing)"]'::jsonb, ARRAY['tamarind water', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'jaggery', 'black peppercorns', 'mango', 'white urad dal (split)', 'dry red chillies', 'methi seeds (fenugreek seeds)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Amlechi Uddamethi Recipe, wash peel and cut the mangoes into wedges and keep it ready.", "Heat a saucepan with jaggery, 1/2 cup of water, salt and the raw mango wedges.", "Boil on medium heat until the mangoes soften.", "This will take about 5 minutes.", "Turn off the flame and set aside.", "To make the coconut curry paste, in a mixer jar, combine the grated coconut, dry red chillies, black peppercorns, turmeric powder, salt and the tamarind.", "Add about 1/2 to \u00be cup of warm water and grind this mixture to a fine paste.", "Set aside.", "Into a sauce pan, combine the cooked raw mangoes and the coconut curry paste and give it a brisk boil.", "Adjust the consistency of the curry by adding water if required.", "The Goan Amaechi Uddamethi typically has a thick gravy.", "Check the salt and adjust according to taste.", "The final step is to make the seasoning.", "Heat coconut oil in a tadka pan over medium heat , add the urad dal and methi seeds, when they begin to change colour add in the mustard seeds, and hing.", "Add this tadka to the Amlechi Uddamethi and give it a stir.", "Serve hotServe the Amlechi Uddamethi (Goan Raw Mango Curry) along with\u00a0steamed rice\u00a0as a comfort food for lunch or a weeknight dinner.", "The Goan Mango Curry also makes a great dish for parties."]'::jsonb, 40, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Amlechi_Uddamethi_Recipe_Goan_Raw_Mango_Curry_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/334.Amlechi_Uddamethi_Recipe_Goan_Raw_Mango_Curry_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chenai Kizhangu Masiyal-South Indian Style Yam Masiyal', 'chenai-kizhangu-masiyal-south-indian-style-yam-masiyal', 'Chenai Kizhangu Masiyal is a yam dish, where it is pressure cooked and mashed and made into a masiyal along with peanuts. Hing, mustard seeds, simple spices and curry leaves add great flavour and depth to this dish. This starchy yet fibrous vegetable when flavoured with such earthy simple spices, tastes absolutely delicious.', '["To cook the yam", "500 grams Elephant yam (Suran/Senai/Ratalu)", "1/4 cup Tamarind Water", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Other Ingredients", "1/2 cup Raw Peanuts (Moongphali)", "1 tablespoon Sesame (Gingelly) Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon White Urad Dal (Split)", "1/2 teaspoon SSP Asafoetida (Hing)", "2 sprig Curry leaves , torn", "2 Green Chillies , finely chopped", "Salt , to taste", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder"]'::jsonb, ARRAY['salt', 'elephant yam (suransenairatalu)', 'tamarind water', 'mustard seeds', 'asafoetida (hing)', 'sesame (gingelly) oil', 'red chilli powder', 'curry leaves', 'white urad dal (split)', 'peanuts (moongphali)', 'turmeric powder', 'green chillies']::text[], '["To begin making the Chenai Kizhangu Masiyal, wash and clean the yam, peel the skin and cut them into 1 inch cubes.", "Transfer these yam cubes into the pressure cooker along with tamarind water, turmeric powder and salt to taste.Close the lid and pressure cook for about 4 whistles.", "Turn off the heat and allow the pressure to release naturally.", "Once the pressure has released naturally open the cooker and mash the yam using a masher, leave a few yam chunks to add to the texture of the Chenai Masiyal.", "Next cook the raw peanuts.", "Add the raw peanuts into a pressure cooker along with 1/2 cup of water and salt to taste.Close the lid and pressure cook for 3 to 4 whistles.", "Allow the pressure to release naturally and keep aside.Now we will continue to make the\u00a0Chenai Kizhangu MasiyalHeat a pan on medium heat, add oil.", "Once the oil is hot, add the mustard seeds and urad dal.", "Allow the mustard seeds to crackle and the urad dal to turn golden brown.Once done add the hing, curry leaves, green chillies and saute for a few seconds.", "Now add the cooked and mashed yam, turmeric powder, red chillie powder, salt to taste and cooked peanuts.", "Saute for a few minutes until well combined.", "Turn off the heat and transfer the\u00a0Chenai Kizhangu Masiyal into a serving bowl and serve hot.Serve the Chenai Kizhangu Masiyal along with\u00a0Steamed Rice,\u00a0Chettinad Style Poondu Rasam Recipe\u00a0and\u00a0Sprouted Green Gram Kosambari Recipe- With Pomegranates\u00a0 for a complete meal."]'::jsonb, 25, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Chenai_Kizhangu_Masiyal_Recipe_12_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/335.Chenai_Kizhangu_Masiyal_Recipe_12_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Long Brinjal Poriyal Masala Recipe - Green Baingan Sabzi', 'long-brinjal-poriyal-masala-recipe-green-baingan-sabzi', 'The Long Brinjal Poriyal Masala Recipe is a delicious masala poriyal made with long brinjal that is pan fried along with tomatoes and spices making it perfect to go along with Phulkas and Kuzhambu. The addition of coriander seeds and sambar powder to the dish brings out a delicious flavor to this Brinjal Poriyal recipe.', '["300 grams Long Green Brinjal , sliced into half and cut into 1 inch pieces", "2 Tomatoes , finely chopped", "1 teaspoon Coriander (Dhania) Seeds , coarsely pounded", "1 sprig Curry leaves , roughly torn", "1 teaspoon Sambar Powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "Salt , to taste", "Oil"]'::jsonb, ARRAY['tomato', 'salt', 'red chilli powder', 'curry leaves', 'coriander (dhania) seeds', 'green brinjal', 'turmeric powder', 'sambar powder', 'sunflower oil']::text[], '["To begin making the\u00a0Long Brinjal Poriyal Masala Recipe, first prepare all the ingredients and keep them ready.", "Cut the green brinjal and soak it in salt water to prevent it from getting dark.Heat oil in a heavy bottomed pan over medium heat.", "Add the coriander seeds and allow it to crackle.Add the chopped tomatoes, curry leaves and saute until the tomatoes soften.", "Stir in the brinjal (draining the excess water), sprinkle some salt and stir fry for a few seconds.", "Cover the pan and cook the brinjal until it softens.Once the brinjal is cooked through, open the lid and add the sambar powder, turmeric powder, red chilli powder and any more salt to taste.Stir well until the brinjal poriyal absorbs all the masala and looks well done.", "Give it a taste and adjust the seasonings accordingly.", "Once done, turn off the heat and transfer to a serving bowl.Serve the\u00a0Brinjal Poriyal Masala along with\u00a0Kerala Style Pulissery (Moru Kuzhambu),\u00a0Steamed Rice,\u00a0Tomato Cucumber Raita\u00a0and Papad for lunch or dinner."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/0-Archana/Long_Brinjal_Sabzi_Poriyal_Recipe_Flavored_With_Coriander_Seeds-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/336.Long_Brinjal_Sabzi_Poriyal_Recipe_Flavored_With_Coriander_Seeds-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Senai Kizhangu Gotsu Recipe - Spicy & Tangy Yam Curry Recipe', 'senai-kizhangu-gotsu-recipe-spicy-tangy-yam-curry-recipe', 'Senai Kizhangu Ghostu Recipe (Spicy & Tangy Yam Curry Recipe) is a comforting recipe made with chopped yam that is pressure cooked with tangy and spicy curry. Yam is a wonderful root vegetable that will help as a cooling agent. It is the best vegetable to fight against any cold or flu.', '["1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves , roughly torn", "1/2 cup Pearl onions (Sambar Onions) , quartered", "2 Tomatoes , roughly chopped", "200 grams Elephant yam (Suran/Senai/Ratalu) , peeled and chopped", "1 cup Tamarind Water", "1 teaspoon Sambar Powder", "1 tablespoon Jaggery", "1 teaspoon Sesame (Gingelly) Oil", "Salt , to taste", "Oil , for cooking"]'::jsonb, ARRAY['tomato', 'salt', 'elephant yam (suransenairatalu)', 'tamarind water', 'mustard seeds', 'jaggery', 'sesame (gingelly) oil', 'curry leaves', 'pearl onion (sambar onion)', 'methi seeds (fenugreek seeds)', 'sambar powder', 'sunflower oil']::text[], '["To begin making the Senai Kizhangu Ghostu Recipe, prep all the ingredients and keep them ready.Heat oil in a pressure cooked over medium heat; add the mustard seeds, fenugreek seeds and allow it to crackle.Add the curry leaves and onions and saute until the onions are lightly tender.", "Once the onions are lightly cooked through, add the remaining ingredients and 1/2 cup of water.Cover the pressure cooker and cook for about 3 whistles and turn off the heat.", "Once the pressure has released naturally open the cooker and give it a stir.Check the salt and spices and adjust the taste accordingtly and serve warm.Serve the Senai Kizhangu Ghostu Recipe (Spicy & Tangy Yam Curry Recipe)\u00a0along with\u00a0Ven Pongal\u00a0for a wholesome dinner or a\u00a0Sunday lunch."]'::jsonb, 40, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Senai_Kizhangu_Ghostu_Recipe_Spicy__Tangy_Yam_Curry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/337.Senai_Kizhangu_Ghostu_Recipe_Spicy__Tangy_Yam_Curry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Style Haak T Thool Recipe - Greens Cooked With Eggs', 'kashmiri-style-haak-t-thool-recipe-greens-cooked-with-eggs', 'Haak T Thool is a Kashmiri dish cooked with collard greens and eggs together. Haal T Thool is most loved by the Kashmiri Pandits in parts of Kashmir and Jammu. Use of mustard oil is very extensive along with some asafoetida in Kashmiri cuisine.Haak which means ''saag'' that can be Spinach, Knol Khol greens etc. Hard boiled eggs are deep fried till golden and then cooked with saag. Haak t thool is an amazing side dish and also makes a place for itself in Wazwan.', '["4 Greens , (collard greens, spinach, knol khol greens etc)", "3 to 4 tablespoons Mustard oil", "2 Whole Eggs , hard boiled", "1 teaspoon Asafoetida (hing)", "2 Dry Red Chilli", "1 Green Chilli , optional", "Oil , as required, for deep frying the eggs"]'::jsonb, ARRAY['green chilli', 'mustard oil', 'asafoetida (hing)', 'dry red chilli', 'greens (collard greens', 'eggs', 'sunflower oil']::text[], '["To begin making the Kashmiri Haak T Thool Recipe, wash the greens nicely and pat dry them.", "Coarsely chop them and keep aside.Heat oil in a wok/kadhai and deep fry the boiled eggs till they are golden in color.Transfer the fried eggs in a bowl and keep aside.Take out the excess oil from the wok and leave around 3 to 4 tablespoons only and heat.Add broken red chili, green chili and asafoetida and saute for a second.Now add chopped greens and salt and cover the lid for few minutes.Once the greens turn soggy and watery, add in the fried eggs and let the greens cook till water starts drying up.Turn off the heat and serve hot.Serve Kashmiri Haak T Thool along with Steamed Rice and\u00a0Kachumber salad\u00a0for a weekday meal."]'::jsonb, 60, 'Kashmiri', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shaheen_Ali/Haak_t_Thool_Greens_cooked_with_Eggs__Kashmiri_Veg.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/338.Haak_t_Thool_Greens_cooked_with_Eggs__Kashmiri_Veg.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bharva Baingan Recipe (Stuffed Roasted Eggplant)', 'bharva-baingan-recipe-stuffed-roasted-eggplant', 'Bharva Baingan Recipe also known as Bharelu Ringna Nu Shaak in Gujarati is a delicious dish with small brinjals filled with delectable spices. This Bharva Baingan recipe is very meditative to cook. From the process of making the filling, slitting of the brinjal, to stuffing and finally cooking is long but yet calming. Tiny brinjals are filled with condiments like coriander, cumin, turmeric combining this with touch of sweetness imparts special flavors. Bharva Baingan is served with hot Phulkas/ Roti''s, Gujarati Dal or Gujarati Kadhi, Keri ka Ras and Papad.', '["8 Small Brinjal (Baingan / Eggplant)", "2 tablespoons Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "5 Curry leaves", "1/4 teaspoon Asafoetida (hing)", "2 teaspoons Coriander Powder (Dhania)", "2 teaspoons Cumin powder (Jeera)", "2 teaspoons Red Chilli powder", "2 teaspoons Garam masala powder", "Salt , to taste", "4 sprig Coriander (Dhania) Leaves , roughly chopped for garnish"]'::jsonb, ARRAY['small brinjal', 'baingan / eggplant', 's oil', 'mustard seeds', 'rai/ kadugu', 'curry leaves', 'asafoetida', 'hing', 's coriander powder', 'dhania', 's cumin powder', 'jeera', 's red chilli powder', 's garam masala powder', 'salt', 'coriander']::text[], '["To make Bhaingan Bharva, rinse the brinjals and make a slit at the bottom of the brinjal vertically towards the stem, making sure not to slice the brinjal in the half.", "We want the brinjals to be a single piece but\u00a0slit\u00a0three fourth\u00a0way\u00a0through.In a small bowl combine a teaspoon of coriander powder, cumin powder, chilli powder, garam masala and asafoetida together.", "Mix nicely.", "Now fill the slit brinjals with the filling mixture and keep aside while you heat the oil.", "Heat oil\u00a0at\u00a0medium high heat in a saut\u00e9 pan; add the mustard seeds and curry leaves.", "Allow them to crackle.", "Heat oil\u00a0over medium-high heat in a pan.", "Add the mustard seeds and curry leaves.", "Allow them to crackle.", "Gradually arrange the spice stuffed brinjals in the pan and stir gently to toss brinjals in the oil.", "Sprinkle the remaining spices and salt over the brinjals.", "Stir to combine.Sprinkle around 3 tablespoons of water on top of the brinjals.", "Turn the heat to low and simmer for 15 minutes, stirring occasionally until the brinjals are cooked and roasted on all sides.Turn off heat and transfer the roasted brinjals to a serving platter.", "Garnish with freshly chopped coriander leaves.Serve Bharva Baingan with\u00a0Phulkas/ Roti''s\u00a0or\u00a0Tawa Paratha,\u00a0Gujarati Dal or\u00a0Gujarati Kadhi, Keri ka Ras and Papad for wholesome weeknight meal."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Bharva_Baingan_Stuffed_Eggplants_Dry_Vegetable_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/339.Bharva_Baingan_Stuffed_Eggplants_Dry_Vegetable_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Baked Fish Crisps Recipe (Fish Fry In Oven)', 'baked-fish-crisps-recipe-fish-fry-in-oven', 'Fish fry is an awesome appetizer which is loved by all the seafood eaters. But at point everyone will have a gut feeling that is deep fried and we tend to restrict ourselves in spite of our taste buds inducing to taste even more. One healthy or tasty alternative is to do that in the oven.', '["10 Fish , pieces", "1 teaspoon Oil , optional", "To marinate", "5 teaspoon Red Chilli powder", "2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 tablespoon Water"]'::jsonb, ARRAY['fish', 'salt', 'red chilli powder', 'water', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Baked Fish Crisps Recipe, clean the fish and in a large vessel add in the ingredients mentioned in the \u201cTo Marinate\u201d table and make a fine paste and add the fish to it and mix well.Allow it to marinate for half an hour.", "Meanwhile line your baking tray with Parchment paper.", "Preheat the oven at 180 Deg c for about 10 mins.", "Arranged the marinated fish pieces in the lined baking tray and using grill mode grill it for 7 mins.", "After 7 mins flip the fish and then grill for another 7 mins.", "Now that the colour of the fish would have slightly turned dark.", "Flip the side of the fish once again and brush it with oil if required.", "And grill for another 5 mins.Once done flip the fish once again and brush with little oil or sprinkle little oil and grill for another 5 mins.Fish would have cooked by now and it is ready to be served.", "If you feel the fish is not yet cooked grill for another 4 mins by flipping the fish sides after 2 mins.", "Serve hot as an appetizer/starter.Serve\u00a0Baked Fish Crisps Recipe along with\u00a0Dhaniya Pudina chutney\u00a0or any other chutney of your choice."]'::jsonb, 40, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/happytrioexplains-gmail.com/Baked_Fish_Crisps__Fish_Fry_in_Oven_edited1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/340.Baked_Fish_Crisps__Fish_Fry_in_Oven_edited1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Arunachal Style Kharzi Rice Recipe', 'arunachal-style-kharzi-rice-recipe', 'Arunachal pradesh, the land of seven sister states is occupied by various tribes.They each have a unique method of cooking. Some tribes use fermented cheese in their cooking which is very common for monpa tribes of Arunachal. Kharzi Rice is a dish from the monpa tribes, which is very tasty.', '["2 cups Cooked rice", "3-4 Dry Red Chillies", "2 tablespoon Mozzarella cheese , or fermented cheese", "Ginger", "3-4 cloves Garlic", "1 Tomato", "Salt", "1/2 cup Spring Onion (Bulb & Greens)", "1/4 cup Green peas (Matar) , freshly boiled", "teaspoon Oil"]'::jsonb, ARRAY['s cooked rice', 'dry red chillies', 'mozzarella cheese', 'ginger', 's garlic', 'tomato', 'salt', 'spring onion', 'bulb & greens', 'green peas', 'matar', 'teaspoon oil']::text[], '["To begin the preparation of Arunachal Style Kharzi Rice, soak dry red chillies in hot water for 10 to 15 minutes before starting the procedure.Use leftover rice or cook rice and keep readyNow take one sliced tomato, 3-4 soaked red chillies,garlic cloves, little ginger in blender, add 2 tablespoon mozzarella cheese or fermented cheese, salt to it and blend to paste.Take a vessel and add just a teaspoon of oil and add this paste and saute on a very low flame to just leave the raw smell of ginger.Keep stirring continuously to prevent melted cheese from sticking to bottom.", "Add spring onions immediately and mix for few seconds.", "Do it on low flame.", "Switch off the stove.Add hot rice and boiled peas to the above paste and mix.Serve Kharzi hot with\u00a0Mooli Raita."]'::jsonb, 25, 'North East India', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/neetha2687-gmail.com/kharzi_rice_of_Arunachal_pradesh.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/341.kharzi_rice_of_Arunachal_pradesh.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rice With Quinoa Recipe- Pressure Cooker Method', 'rice-with-quinoa-recipe-pressure-cooker-method', 'Rice with Quinoa recipe is easy to make in a pressure cooker. Both the grains are mixed and washed and cooked together and so it saves you time. Addition of quinoa lifts your normal white rice to a whole other nutrition level.', '["1/2 cup Rice", "1/2 cup Quinoa", "2 cups Water", "Salt , (if required)"]'::jsonb, ARRAY['rice', 'quinoa', 's water', 'salt']::text[], '["To begin making Rice with Quinoa Recipe, first rinse the rice and quinoa together well under running water.Place rice and quinoa along with two cups of water in the pan of the pressure cooker.Keep the weight on, cover the pressure cooker.", "Cook the rice in the pressure cooker on medium high heat and after the first whistle turn the heat to low.Once you turn the heat to low, simmer the rice for 3 minutes.", "After 3 minutes, turn off the heat and allow the pressure to release naturally and then open the pressure.", "Serve Rice And Quinoa with\u00a0Masoor Dal Gassi,\u00a0Muttaikose Poriyal\u00a0and a bowl of\u00a0curd."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Rice_With_Quinoa_Recipe-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/342.Rice_With_Quinoa_Recipe-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aal Ke Kofte (Bottle Gourd Fritters In Spicy Gravy) Recipe', 'aal-ke-kofte-bottle-gourd-fritters-in-spicy-gravy-recipe', 'Aal Ke Kofte is a delicious combination of bottle gourd pakoras and spicy gravy. It is a perfect dish to make when you have guests at your home for dinner. Try this recipe and you will make it again and again.', '["1 tablespoon Ginger Garlic Paste", "1/2 cup Curd (Dahi / Yogurt)", "2 Onion , paste", "2 Bay leaf (tej patta)", "2 Black cardamom (Badi Elaichi)", "1/2 inch Cinnamon Stick (Dalchini)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "Salt , as required", "Oil , as required", "Water , as required", "2 sprig Coriander (Dhania) Leaves , finely chopped", "250 grams Bottle gourd (lauki) , grated", "1/2 cup Gram flour (besan)", "1 teaspoon Red Chilli powder", "2 Green Chillies , finely chopped", "Salt , as required", "Water , as required", "Oil , as required, for deep frying"]'::jsonb, ARRAY['black cardamom (badi elaichi)', 'salt', 'bay leaf (tej patta)', 'red chilli powder', 'water', 'onion paste', 'curd', 'ginger garlic paste', 'coriander (dhania) leaves', 'cinnamon stick (dalchini)', 'bottle gourd (lauki)', 'gram flour (besan)', 'coriander powder', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Aal Ke Kofte recipe, firstly we will begin with preparing the koftas.Mix all the ingredients mentioned under \u2018for koftas\u2019 in a mixing bowl.", "Mix them properly.", "Add a little water to bring the mixture together.Once it is done, make round shaped pakoras out of it and deep fry them in a deep frying pan.When they turn brown from both the sides, take them out to on a kitchen towel to absorb the extra oil.", "Follow the same process for the reaming mixture and keep them aside.Heat oil in a heavy bottomed pan and add cloves, badi elaichi, tej patta and dal chini.After a minute add the ginger garlic paste and cook it tell the raw smell goes from the mixture.Once it is done add the onion paste and let it cook for 5 to 8 minutes.After 5 to 8 minutes, add red chilli powder, turmeric powder, coriander powder and the required salt.", "Let it cook for 5 minutes.After 5 minutes, bring the flame to low and add the curd.Mix well and add the required amount of water.", "Mix well and let it cook till the gravy gets a little thick.Once it is done, add the fried kofta and let it cook for 2 to 3 minutes more.After 2 to 3 minutes, switch off the stove and garnish it with chopped coriander leaves.Serve Aal Ke Kofte with\u00a0Lauki Raita\u00a0and\u00a0Tawa Parathas\u00a0for a perfect weekday meal."]'::jsonb, 75, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/aal_ke_kofte_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/343.aal_ke_kofte_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bandhakopir Ghonto Recipe (Bengali Style Cabbage Fry)', 'bandhakopir-ghonto-recipe-bengali-style-cabbage-fry', 'Bandhakopir Ghonto is a simple yet flavourful stir fry dish from the Bengali Cuisine. Cabbage is a power house of so many nutrients. It is rich in Vitamin E that gives a glowing skin and healthy hair when consumed regularly. It is also high in Vitamin K that helps in improved  brain function and protects one from nerve damage. It is anti inflammatory and helps build a strong immune system to fight illness. So, it is most ideal to include this humble vegetable in our daily diet. You can make this stir fry within minutes and it is a great accompaniment to rice or rotis.', '["1 Cabbage (Patta Gobi/ Muttaikose) , shredded", "1 Potato (Aloo) , cubed", "1/4 cup Green peas (Matar) , shelled", "1 Tomato , finely chopped", "1 Green Chillies , cut lengthwise", "1/2 inch Ginger , grated", "2 teaspoons Mustard oil , to fry potato", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Garam masala powder", "1/2 teaspoon Sugar", "Salt , to taste", "2 teaspoons Mustard oil", "1/2 teaspoon Cumin seeds (Jeera)", "1 Bay leaf (tej patta)", "1 Dry Red Chilli , halved"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'garam masala powder', 'mustard oil', 'bay leaf (tej patta)', 'potato (aloo)', 'red chilli powder', 'green peas (matar) shelled', 'dry red chilli', 'sugar', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'green chillies', 'mustard oil potato', 'cabbage (patta gobi muttaikose)']::text[], '["To begin making the Bandhakopir Ghonto Recipe, heat a kadai/wok with mustard oil and when it starts to smoke add the potatoes, salt (to taste) and pinch of turmeric.Fry over medium flame till the potatoes are roasted well and transfer them to another container and set it aside.", "In the same wok add the shredded cabbage, remaining turmeric, salt (to taste) and 1/4 cup of water.", "Cover and cook the cabbage over low flame for 5 minutes.Open the lid and cook the cabbage over medium flame, till the excess water is absorbed .Transfer the cabbage into the container with potatoes and put the kadai back on low flame.Add the mustard oil for tempering in the kadai and temper with ingredients given under ''to temper''.", "Once tempered add the green chillies, ginger and the tomatoes.Add the chilli powder, coriander powder, garam masala, salt and cook the tomatoes, by stirring continuously till they become mushy .Now add the cooked cabbage and potatoes and mix well over low/medium heat for 2 minutes and switch off.", "Your delicious Bandhakopir Ghonto is ready.Serve Bandhakopir Ghonto along with\u00a0Bengali Luchi\u00a0and\u00a0Tomato Onion Cucumber Raita\u00a0for a weekday lunch or dinner."]'::jsonb, 30, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/umar/Bandhakopir__Ghonto.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/344.Bandhakopir__Ghonto.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kori Gassi Recipe - Mangalorean Chicken Curry', 'kori-gassi-recipe-mangalorean-chicken-curry', 'Kori gassi is a traditional Mangalorean Bunt’s dish with a coconut based red curry. Here Kori means chicken and Gassi means curry.', '["Ingredients For Kori Gassi", "500 grams Chicken , cut into pieces", "1 Onions , sliced thin", "1 cup Coconut milk , thin", "1/2 cup Coconut milk , thick", "2 Cloves (Laung)", "1 Bay leaf (tej patta)", "1 inch Cinnamon Stick (Dalchini)", "Salt , to taste", "1 sprig Curry leaves", "2 tablespoons Ghee", "Ingredients For Masala", "1 Onion , chopped", "10 cloves Garlic", "2 inch Ginger", "1 cup Fresh coconut , grated", "1-1/2 tablespoon Coriander (Dhania) Seeds", "8 Dry Red Chillies , or Kashmiri red chili variety", "1-1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1-1/2 teaspoon Whole Black Peppercorns", "1/2 teaspoon Turmeric powder (Haldi)", "20 grams Tamarind"]'::jsonb, ARRAY['ingredients for kori gassi', 's chicken', 'onions', 'coconut milk', 'laung', 'bay leaf', 'tej patta', 'cinnamon stick', 'dalchini', 'salt', 'curry leaves', 's ghee', 'ingredients for masala', 'onion', 's garlic', 'ginger', 'fresh coconut', 'coriander', 'dhania', 'dry red chillies', 'cumin seeds', 'jeera', 'methi seeds', 'fenugreek seeds', 'whole black peppercorns', 'turmeric powder', 'haldi', 's tamarind']::text[], '["To start preparing this Mangalorean Kori Gassi recipe, wash the chicken pieces well.", "Add 1 teaspoon salt, mix well.", "Cover and let it sit for 15 minutes.", "Meanwhile, get prep with all the other ingredients.In a Kadai/Pan add 1 teaspoon ghee.", "Roast coriander seeds, cumin seeds, dried red chilies, peppercorns one by one until fragrant.", "Once roasted remove from pan and set aside to cool.Once all spices are roasted, into the same pan, add sliced onions, garlic, and ginger and roast until onions start to turn brown.Now add fresh grated coconut tamarind ball, and continue to roast until coconut start to turn golden brown.", "Remove from pan and set it aside.Once all the roasted spices and onion-coconut mix has cooled, add them all to a blender and blend into smooth paste by adding little water.Now add remaining ghee and saute with the remaining slices till fragrant.dAd sliced onions and saut\u00e9 for a minute.", "Add curry leaves, mix well.Add the ground masala paste and cook until oil/ghee separates from the sides of the pan.Add the chicken pieces and give it a good mix to ensure all chicken is coated uniformly with the masala.", "Cook for 5 minutes with constant stirring.Now add thin coconut milk and salt to taste, bring it to boil Reduce flame to medium, cover and cook until chicken well done.Once chicken is cooked well, add thick coconut milk, reduce to simmer.", "Wait for a minute or two and turn off the flame.", "Do not let the curry come to boil again, once you add thick coconut milk, if you boil it the milk will curdle.Break some Kori rotti into a plate.", "Pour generous amount Kori Gassi (chicken curry) with some chicken pieces over the rotti.", "Let it soak for 5 to 7 minutes.", "Enjoy the soggy pieces of Kori rotti with the Kori Gassi like the way it is eaten traditionally!Serve\u00a0Kori Gassi Recipe as a Sunday meal along with Kori Rotti or\u00a0Mangalorean Neer Dosa Recipe, and\u00a0Chicken Ghee Roast Recipe - Chicken Dry Roast Recipe\u00a0by the side."]'::jsonb, 55, 'Mangalorean', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Kori_Gassi__Kori_Rotti.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/345.Kori_Gassi__Kori_Rotti.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kongunad Chicken Fry Recipe', 'kongunad-chicken-fry-recipe', 'Kongunad Chicken Fry is a finger licking good recipe of a chicken appetizer made South Indian style flavoured with whole spices and curry leaves.', '["2 inch Cinnamon Stick (Dalchini)", "1 teaspoon Black pepper powder", "3 tablespoon Coriander (Dhania) Seeds", "1/2 teaspoon Fennel seeds (Saunf)", "1/2 teaspoon Poppy seeds", "10 Red Chilli powder", "5 tablespoon Dry coconut (kopra)", "1 cup Chicken breasts", "2 tablespoon Oil", "1 Onion", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Curry leaves , Handful", "1/2 cup Coriander (Dhania) Leaves , chopped", "1 cup Water"]'::jsonb, ARRAY['salt', 'coriander (dhania) leaves', 'fennel seeds (saunf)', 'red chilli powder', 'dry coconut (kopra)', 'water', 'curry leaves', 'coriander (dhania) seeds', 'cinnamon stick (dalchini)', 'poppy seeds', 'onion', 'black pepper powder', 'chicken breasts', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Kongunad Chicken Fry recipe, wash and clean chicken breast pieces with turmeric.", "Drain the excess water and keep it aside.", "In a non-stickDrain the excess water and keep it aside.In a non-stick kadai, add the\u00a0cinnamon stick,\u00a0cloves,\u00a0pepper powder,\u00a0coriander seeds,\u00a0fennel seeds and\u00a0poppy seeds.", "Saute until the aroma come out of it.", "Once fried, add red chilli and coconut.", "Saute for a minute.", "Ensure not to over fry as it may burn the red chilli.Allow it to cool down and grind into a fine paste using water.", "In another kadai, add oil and heat it over medium flame.Once the oil is hot, add chopped onions and fry until they become translucent.", "Now, add turmeric, chicken, and salt.Cook until the chicken turns in colour, it becomes white after few seconds.Add the ground paste to the chicken and cook over medium flame until the chicken cooks completely and oil separates from the chicken.", "Simmer it for few minutes until the gravy becomes dry.", "Sprinkle curry leaves and coriander leaves over the chicken.", "Give it a stir and cook for few seconds.Remove from the flame.", "Prepare this simple yet delicious Kongunad Chicken Fry and serve with rice and hot\u00a0Jeera Rasam\u00a0for lunch."]'::jsonb, 40, 'South Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/KarthikaKrishnan/Kongunad_Chicken_Fry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/346.Kongunad_Chicken_Fry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharashtrian Narali Bhaat Recipe (Sweetened Coconut Rice)', 'maharashtrian-narali-bhaat-recipe-sweetened-coconut-rice', 'Narali Bhaat Recipe is a delicious sweetened coconut rice that is typically prepared in Maharashtra on the occasion of Narali Poornima - a full moon day during the auspicious month of Shravan, when coconuts are offered to the sea. This Coconut Rice is sweetened with jaggery, is made to celebrate the day that marks the end of the monsoon and the beginning of the fishing season once again.', '["1 cup Basmati rice", "3/4 cup Fresh coconut , grated", "3/4 cup Jaggery , grated", "1/2 teaspoon Saffron strands", "9-10 Cloves (Laung)", "4 tablespoons Ghee", "2 cups Water", "1/4 cup Mixed nuts , chopped (raisins, cashewnuts, almonds, chironji and any other nuts of your choice)"]'::jsonb, ARRAY['basmati rice', 'coconut', 'ghee', 'saffron strands', 'jaggery', 'water', 'mixed nuts (raisins', 'cloves (laung)']::text[], '["To begin making the Maharashtrian Narali Bhaat Recipe, first wash the rice thoroughly, drain the water and keep it aside for 45 minutes.In a small pan, warm 1 tablespoon ghee and saute the dry fruits and nuts for 2-3 minutes on low heat until they turn golden and are roasted.", "Remove the roasted nuts from hot ghee and set aside until later use.In a nonstick pan or heavy-bottomed pan melt 3 tablespoons of ghee on a low heat.", "Add the cloves and saute for 3-4 minutes.When they puff up and get aromatic, add the washed rice and toss it well until the grains are well coated with ghee.Next, pour in the water, the saffron strands and bring the rice to a brisk boil.", "Once the rice comes to a brisk boil, turn the heat to low and cover the pan.", "Cook the rice until all the water is absorbed.", "Meanwhile, add the jaggery and coconut to a small saucepan and place it on low to medium heat.", "Allow the jaggery to melt.", "Once the jaggery melts, pour the jaggery and coconut mixture to the cooked rice and mix thoroughly, taking care not to break the grains.", "You can use a fork and gently mix at this stage, to fluff up the grains.Cover the pan and cook once again on a low heat for 4-5 minutes more.", "Transfer the Narali Bhaat to a serving bowl and garnish it with the roasted nuts.The Maharashtrian Narali Bhaat\u00a0is now ready to be served as a festive dish."]'::jsonb, 50, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Narali_Bhaat_Sweet_Coconut_Rice.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/347.Narali_Bhaat_Sweet_Coconut_Rice.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pattani Kootu Recipe (Green Peas Curry)', 'pattani-kootu-recipe-green-peas-curry', 'Kootu is one of the simplest and delicious thick curries like recipe. Kootu goes well with steamed rice or roti or even dosa. Pattani kootu recipe is a delicious healthy dish made of green peas. This legume has a lots of nutrients. It’s sweet and starchy taste makes it a delicious side dish. This kootu is well paired with rotis, dosas, rice as side dish. It’s easy to make and is perfect for those busy weekdays. This pattani kootu can be made with fresh/frozen peas immediately or even with vatana or dried peas after soaking them up for overnight. Serve Pattani Kootu Recipe (Green Peas Curry) with Pudina Tawa Paratha Recipe (Mint Leaf Skillet Flat Bread), steamed rice, Varutharachu Sambar Recipe for a simple weeknight dinner.', '["1-1/2 Green peas (Matar)", "1 Onion , finely chopped", "1/2 cup Fresh coconut , grated", "4 Green Chillies", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves", "1 teaspoon Fennel seeds (Saunf)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "Salt , to taste", "1 teaspoon Oil"]'::jsonb, ARRAY['salt', 'coconut', 'fennel seeds (saunf)', 'mustard seeds', 'green peas (matar)', 'curry leaves', 'onion', 'cumin seeds (jeera)', 'green chillies', 'sunflower oil']::text[], '["To begin making Pattani Kootu Recipe (Green Peas Curry), in a mixer grinder, grind grated coconut, green chillies and cumin seeds into a thick paste.", "Keep aside till required.Heat oil in a kadai.", "Add mustard seeds and wait until they splutters.Add fennel seeds, curry leaves, and finely chopped onions and saute until the onions turn pinkish.Add the ground coconut masala reserved earlier and cook further until the coconut paste comes together from the sides of the pan.Add green peas and cook for about 3 minutes or till they are almost a bit soft and looks a little cooked.", "Add salt and stir.Now add about 1/2 cup water and cook covered until the green peas are well cooked, and are almost mashable.Adjust salt if required and cook until the dish is thick in consistency, now turn off heat.Serve\u00a0Pattani Kootu Recipe (Green Peas Curry) with\u00a0Pudina Tawa Paratha Recipe (Mint Leaf Skillet Flat Bread), steamed rice,\u00a0Varutharachu Sambar Recipe\u00a0for a simple weeknight dinner."]'::jsonb, 35, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/Kossamali_Pattani_Kootu.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/348.Kossamali_Pattani_Kootu.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Munakkada Masala Kura Recipe - Drumstick Dry Curry Recipe', 'andhra-style-munakkada-masala-kura-recipe-drumstick-dry-curry-recipe', 'Andhra Style Munakkada Masala Kura Recipe (Drumstick Dry Curry Recipe) is a dry gravy made with drumstick cooked in a rich gravy made with ground roasted peanuts, coriander seeds, cinnamon and cardamom pods. The Andhra cuisine is mostly spicy and rich. They prefer to use ground spice in most of their dishes.', '["1 Drumstick , cut into 1 inch pieces", "1 Onion , chopped", "1 tablespoon Ginger Garlic Paste", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Ingredients to Grind", "1/2 cup Roasted Peanuts (Moongphali)", "1 tablespoon Coriander (Dhania) Seeds", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 tablespoon Fresh coconut , grated", "1 Tomato , chopped"]'::jsonb, ARRAY['tomato', 'salt', 'coconut', 'red chilli powder', 'drumstick', 'ginger garlic paste', 'coriander (dhania) seeds', 'onion', 'cinnamon stick (dalchini)', 'peanuts (moongphali)', 'turmeric powder', 'cloves (laung)']::text[], '["To begin making the Andhra Style Munakkada Masala Kura Recipe,\u00a0heat a flat skillet.", "Roast the peanuts and coriander seeds for 20 seconds.Add the cloves, cinnamon sticks, and grated coconut and saute till it become light brown.", "Cool it down and add tomatoes and grind it into a smooth paste.Heat a sauce pan with oil, add ginger garlic paste and onions, fry till it is translucent.", "Add the ground paste and red chilli powder, turmeric powder and salt.", "Saute till the masala is cooked.After 10 minutes, add the chopped drumstick, little water and cover it with the lid and cook for about 10 more minutes.Cook until the oil is released from the masala.", "Check for salt and serve hot.Serve the\u00a0Andhra Style Munakkada Masala Kura Recipe\u00a0along with\u00a0Kollu Rasam Recipe (Nourishing HorseGram Stew),\u00a0Steamed Rice\u00a0and\u00a0Chow Chow Thoran\u00a0to enjoy weekday dinner."]'::jsonb, 55, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Andhra_Style_Munakkada_Masala_Kura_Recipe_Drumstick_Dry_Curry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/349.Andhra_Style_Munakkada_Masala_Kura_Recipe_Drumstick_Dry_Curry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Prawn Balchao Recipe', 'prawn-balchao-recipe', 'Goa is a total bliss when it comes to sea food lovers. Most restaurants get their fresh catch every day, which gets showcased right at their entrance. Customers are free to pick and choose from the display, that later gets served at their dinner table. One such dish which I always relish at my favourite restaurant in Goa is the Prawn Balchao. My colleagues love the prawn masala used in this one as the dish is a mixture of sweet, spice and sourness. The unique ingredient that makes the prawn even more delectable is the Goan Toddy Vinegar - one can get this in the Saturday Mapusa Market.', '["1 kg Prawns , de-veined", "2 Onions , finely chopped", "2 Tomatoes , ripe", "2 sprig Curry leaves", "2 tablespoons Ginger Garlic Paste", "15 Dry Red Chillies", "2 teaspoon Whole Black Peppercorns", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 inch Cinnamon Stick (Dalchini)", "6 Cloves (Laung)", "2 tablespoons Sugar", "1/2 Vinegar", "Salt , to taste", "Oil , as required"]'::jsonb, ARRAY['salt', 'mustard seeds', 'prawns deveined', 'tomato ripe', 'black peppercorns', 'ginger garlic paste', 'curry leaves', 'sugar', 'dry red chillies', 'onion', 'cumin seeds (jeera)', 'cinnamon stick (dalchini)', 'vinegar', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Prawn Balchao recipe, in a large bowl, clean the prawns under running water, strain it out.Add a pinch of salt and turmeric powder, mix well and set aside.", "This step will basically remove the typical sea food odour from the prawns.In a wok dry roast - chillies, pepper, cumin, mustard, cloves and cinnamon.Grind the roasted mix of spices along with ginger, garlic and the vinegar into a smooth paste.In another wok/kadhai heat some oil, add the chopped onions and cook till golden brown.Add the chopped tomatoes and curry leaves, cook till all the water evaporates and the mixture turns all mushy leaving oil at the sides.Add the spice mixture and cook till the raw smell disappears.Add the prawns along with the sugar, check for spice levels and adjust accordingly.Cook till the water left by the prawns evaporates and the mixture turns into a thick gravy like consistency.Serve hot Prawn Balchao with any roti or simple rice of your choice with a nice tall glass of chilled beer."]'::jsonb, 45, 'Goan', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/FlavorFlameFusion/Prawn_Balchao.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/350.Prawn_Balchao.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chilke Wali Mung Dal Curry Recipe', 'chilke-wali-mung-dal-curry-recipe', 'Split Mung bean dal cooked in aromatic Indian spices, onions and tomatoes; perfect with a bowl of hot steaming rice or any Indian flat bread. It is a perfect recipe to serve during your weekday lunch or dinner.', '["1/2 cup Green Moong Dal (Split)", "1 Onion , finely chopped", "2 cloves Garlic", "3 Cloves (Laung)", "1/2 teaspoon Cumin seeds (Jeera)", "2 Green Chillies", "1/4 teaspoon Turmeric powder (Haldi)", "1 Tomato , chopped", "1 teaspoon Garam masala powder", "Salt , to taste", "2 tablespoons Ghee , or oil", "Coriander (Dhania) Leaves , for garnishing"]'::jsonb, ARRAY['green moong dal', 'split', 'onion', 's garlic', 'laung', 'cumin seeds', 'jeera', 'reen chillies', 'turmeric powder', 'haldi', 'tomato', 'garam masala powder', 'salt', 's ghee', 'coriander', 'dhania']::text[], '["To begin making the Chilke Wali Mung Dal Curry recipe, wash and drain the split mung bean dhal.", "Place in a pressure cooker/pan, add about 1 to 1 \u00bd cups of water (up to 1 inch above the dhal).", "Close the pressure pan and cook on high.", "After one whistle, lower the heat and cook for about 10 minutes.", "You can cook the dhal in a saucepan with lots of water till soft and tender.Let the pressure drop on its own.", "Open the pressure pan and mash the dal.", "You may choose to make it into a fine paste or leave it a little coarse.In a deep kadai or saucepan, heat oil/ghee.", "Once the oil is hot, add cumin seeds and cloves; saut\u00e9 for a few seconds.Add the finely chopped onions along with garlic and green chillies; fry for a few minutes till the onions are slightly soft and translucent.Stir in tomatoes, turmeric powder and garam masala powder.Saute on medium low for a few minutes till the tomatoes are slightly cooked and soft.", "You will start to see the oil separating from the mixture.At this stage, add the cooked dal along with 1 to 1 \u00bd cups of water and salt to taste.", "Give it a good mix and taste for seasoning.", "Adjust accordingly.Bring to a boil on high and once it comes to a boil, reduce to medium low and simmer for about 3 to 4 minutes till the flavours have blended well and you get the consistency you want.Remove from heat, garnish with finely chopped coriander leaves and serve hot.Chilke Wali Mung Dal goes well with\u00a0steamed rice, any pulao or biryani and any Indian flat bread like roti,\u00a0paratha, naan, puri etc."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Curryandvanilla/Chilkewali_Mung_Dhal_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/351.Chilkewali_Mung_Dhal_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aratikaya Masala Pulusu Recipe - Raw Banana Stir Fry', 'aratikaya-masala-pulusu-recipe-raw-banana-stir-fry', 'Aratikaya Masala Pulusu Recipe (Raw Banana Stir Fry Recipe) is a simple dish that has the authentic flavors of Andhra. The raw banana is simply tossed with some ground paste of ginger, garlic and raw rice for the crunch and is then simmered with tamarind gravy which is then balanced with the right amount of spice.', '["1 Raw Banana , skin peeled and cut into small cubes", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1 tablespoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 cup Tamarind Water", "Ingredients to grind", "1 inch Ginger", "4 cloves Garlic", "1 tablespoon Rice"]'::jsonb, ARRAY['ginger', 'banana skin', 'tamarind water', 'mustard seeds', 'rice', 'red chilli powder', 'cloves garlic', 'curry leaves', 'turmeric powder']::text[], '["To begin making the Aratikaya Masala Pulusu Recipe, peel the skin off the raw banana and cut them into small pieces.", "Keep water over a saucepan and bring it to boil.Add the chopped raw banana, turmeric powder, salt and boil for about 10 minutes.Strain the water and keep the banana aside.", "Grind ginger, garlic and rice with little water to a coarse paste and keep it aside.Heat a kadai with oil, add the mustard seeds and allow it to splutter for few seconds.Add the curry leaves and let it crackle for 10 seconds and add cooked raw banana along with the ground paste.", "You can add red chilli powder and salt also and give it a stir.Once that is done, add the tamarind water and leave it simmer for 5 minutes until the water is all evaporated.Serve the\u00a0Aratikaya Masala Pulusu Recipe\u00a0with\u00a0Steamed Rice\u00a0and\u00a0Dosakaya Pappu Recipe\u00a0to create a satisfying meal."]'::jsonb, 35, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Aratikaaya_Masala_Pulusu_Recipe_Raw_Banana_Stir_Fry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/352.Aratikaaya_Masala_Pulusu_Recipe_Raw_Banana_Stir_Fry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sattu Ka Paratha Recipe (Stuffed Channa Dal Flour Paratha)', 'sattu-ka-paratha-recipe-stuffed-channa-dal-flour-paratha', 'Sattu Ka Paratha Recipe is made out of sattu which is essentially the roasted channa dal flour. It is one of the vegetarian sources of protein for people of Bihar and used in many authentic Bihari recipes. A most common way to use Sattu is in parathas. Sattu atta is spiced with herbs and stuffed into the whole wheat dough, cooked on tawa and served with curd and often baingan ka bharta for a delightful and healthy summer meal.', '["Ingredients for Dough", "3 cups Whole Wheat Flour", "1 cup Lukewarm Water", "Ingredients for Stuffing", "2 cups Roasted Gram Flour (Sattu Ka Atta)", "2 Onions , finely chopped", "3 Green Chillies , minced", "6 cloves Garlic , minced", "1 inch Ginger , finely chopped", "2 teaspoon Kala jeera", "3 tablespoon Coriander (Dhania) Leaves , chopped", "1 tablespoon Mustard oil", "2 tablespoon Mango pickle , mashed", "Ghee , or oil for frying the parathas"]'::jsonb, ARRAY['wheat flour', 'ginger', 'mustard oil', 'coriander (dhania) leaves', 'mango pickle', 'water', 'cloves garlic', 'gram flour (sattu ka atta)', 'onion', 'ghee', 'oil the parathas', 'green chillies', 'kala jeera']::text[], '["To prepare hot Sattu Ka Paratha Recipe (Stuffed Channa Dal Flour Paratha), bring all the ingredients together.", "Mix whole wheat flour and water together, knead in a mixing bowl to make a soft dough.", "A well kneaded soft dough leads to softer parathas.", "Keep aside covered with a wet muslin cloth till you prepare the stuffing.Mix together all the stuffing ingredients and if the mixture feels very dry, sprinkle a little warm water and mix well.Distribute the dough in 10 balls and roll each ball a little, spread a little ghee/oil on it and place 2 tablespoons of filling in the middle, cover from all sides and roll the paratha 1/2 inch thick.Heat a tawa/ griddle and cook each side of the paratha until golden brown, add a few drops of ghee/oil while on tawa.Repeat the process for the rest of the parathas.Serve these hot Sattu Ka Paratha with curd and pickle.", "When sided with baingan ka bharta, Sattu ka Paratha makes a wholesome weeknight dinner."]'::jsonb, 45, 'Bihari', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Monika_Manchanda/Sattu_Ka_Paratha.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/353.Sattu_Ka_Paratha.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aluchi Bhaji Recipe - Maharashtrian Style Colocasia Leaves Curry', 'aluchi-bhaji-recipe-maharashtrian-style-colocasia-leaves-curry', 'Aluchi Bhaji is a Maharashtrian curry made using nutritious Colocasia (Aloo,Arbi) leaves. This lip smacking, sweet-sour, no onion-garlic curry is a part of many festive fares across the state. The curry is pretty simple to make, the only precaution you need to take is while buying the leaves. The leaves may sometimes cause itching to the hands or throat. As far as possible buy the leaves from a known/reputed seller or you can easily grow your own leaves.', '["50 grams Colocasia Leaves (Arbi) , leaves along with tender stemscleaned and finely chopped", "1/4 cup Raw Peanuts (Moongphali) , soaked in hot water for 30 minutes", "2 tablespoons Chana dal (Bengal Gram Dal) , soaked in hot water for 30 minutes", "1 teaspoon Oil", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Asafoetida (hing)", "7 Dry coconut (kopra) , thinly sliced", "1 teaspoon Amchur (Dry Mango Powder)", "1/4 teaspoon Turmeric powder (Haldi)", "2 teaspoons Jaggery , grated", "2 Green Chillies , slit", "Salt , to taste"]'::jsonb, ARRAY['green chillies', 'salt', 'amchur (dry mango powder)', 'mustard seeds', 'asafoetida (hing)', 'jaggery', 'dry coconut (kopra)', 'cumin seeds (jeera)', 'peanuts (moongphali)', 'colocasia leaves (arbi) leaves a tender stems', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making the Aloochi Bhaji recipe, get all the ingredients ready and keep them aside.Soak the channa dal in water for about 1 hour.", "Add the chana dal and peanut along with a pinch of salt and 1/4 cup of water in the pressure cooker and cook until you hear 3 to 4 whistles.", "Turn off the heat.", "Keep aside.Add the mustard seeds and once they splutter add the cumin seeds.", "Add hing, turmeric powder, green chillies and the chopped aluchi leaves and\u00a0stems, amchur. jaggery, salt, coconut pieces and mix well.", "Saute until the colocasia leaves soften and get cooked well.", "Once cooked, add the cooked chana dal and the peanuts and give it a brisk boil.", "Once done, check the salt and adjust to taste and turn off the heat.Serve Aluchi Bhaji along with\u00a0Phulka,\u00a0Matki Chi Usal\u00a0and\u00a0Kanda Kairichi Chutney\u00a0for a delicious sunday lunch."]'::jsonb, 30, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/9-feb/Aluchi_Bhaji_Maharastrian_Colacasia_leaves_curry_with_peanuts-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/354.Aluchi_Bhaji_Maharastrian_Colacasia_leaves_curry_with_peanuts-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maheri Recipe', 'maheri-recipe', 'Maheri is an old recipe which is made in my villages for breakfast. My naani used to make this recipe when I would visit her place in childhood. Traditionally, it is made with fresh buttermilk and rice/broken wheat/millet on chulha, but I have made this recipe on gas stove. You can also add vegetables of your choice to make this recipe more healthy and tasty.', '["1 cup Barnyard Millet , washed and soaked for 30 minutes", "4 cup Buttermilk", "Salt , to taste", "1 teaspoon Cumin seeds (Jeera)", "pinch Asafoetida (hing)", "1/2 teaspoon Turmeric powder (Haldi)", "1 tablespoon Ghee"]'::jsonb, ARRAY['salt', 'asafoetida (hing)', 'ghee', 'barnyard millet', 'cumin seeds (jeera)', 'buttermilk', 'turmeric powder']::text[], '["To begin making Maheri, heat ghee or oil in a pressure cooker.", "Once the ghee is hot\u00a0add hing, cumin seeds and allow the seeds to crackle.", "Once they starts crackling, add turmeric powder.Add 2 cups of water and salt and bring it to boil.", "Once the water starts boiling add buttermilk and bring it to boil again.Now add the barnyard millet and mix well.", "Cover the pressure cooker and turn the heat to low.", "Pressure cook for 2 whistles.", "Let the pressure release naturally and then open the pressure cooker.Transfer the Maheri to a serving dish and serve.", "Serve Maheri as a healthy breakfast with\u00a0pickle\u00a0or\u00a0Green Chutney\u00a0for a comforting breakfast."]'::jsonb, 70, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/aarti/Maheri_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/355.Maheri_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gujarati Batata Pulao Recipe - Sweet And Spicy Pulao With Lentils And Potatoes', 'gujarati-batata-pulao-recipe-sweet-and-spicy-pulao-with-lentils-and-potatoes', 'In a traditional Gujarati meal, any form of lentil preparation is almost compulsory, it could be in the form of a lentil, legume or even combined with rice, hence making their meals wholesome.', '["1 cup Basmati rice", "1/2 cup Yellow Moong Dal (Split)", "2 Potatoes (Aloo) , peeled and diced", "1 Onion , thinly sliced", "1/2 cup Green peas (Matar) , steamed", "1/4 cup Fresh coconut , finely diced", "1 teaspoon Sugar", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta)", "3 Cardamom (Elaichi) Pods/Seeds", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Turmeric powder (Haldi)", "3 Green Chillies", "3 cloves Garlic", "1 inch Ginger , chopped", "3 tablespoons Ghee", "1 teaspoon Oil", "2 tablespoon Mint Leaves (Pudina) , chopped", "Salt , to taste"]'::jsonb, ARRAY['basmati rice', 'yellow moong dal (split)', 'green chillies', 'ginger', 'salt', 'coconut', 'bay leaf (tej patta)', 'cardamom (elaichi) podsseeds', 'ghee', 'green peas (matar)', 'cloves garlic', 'sugar', 'onion', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'mint leaves (pudina)', 'potato (aloo)', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Gujarati Batata Pulao Recipe, wash and soak rice and lentil in 3 cups of water for half an hour.Using the pestle and mortar, pound together the cinnamon, cloves and cardamom to a fine powder.Heat oil in a small pan; add the sliced onions and saut\u00e9 until tender and caramelized and keep aside.Make a paste of the ginger, garlic and green chillies in a mixer grinder and keep aside.Heat ghee in a large soup pot or handi\u00a0on medium heat; add the cumin seeds, ginger garlic paste, and saut\u00e9 until the raw smell from the ginger garlic paste turns to a roasted aroma and changes color.Stir in the pounded spice powder, bay leaf, potatoes, turmeric powder, sugar, coconut, salt and saut\u00e9 for a few seconds.", "Finally stir in the soaked rice and lentils along with the water.Allow the mixture to come to a boil and then turn the heat to low.Cover the pan and simmer for approximately 30 minutes until the rice has absorbed all the water and cooked to the desired texture.Once cooked, turn off the heat and allow the\u00a0Batata Pulao Recipe to rest for 15 minutes.", "Stir in the caramelized onions, peas, chopped mint and serve warm.", "Serve the\u00a0Gujarati Batata Pulao\u00a0as it is or along with a\u00a0Palak Raita\u00a0for a quick and easy weeknight dinner.", "You can also serve it with\u00a0Gujarati Kadhi\u00a0and a roasted\u00a0papad."]'::jsonb, 50, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Batata_Pulao_Recipe_Sweet_And_Spicy_Pulao_Made_With_Lentils_And_Potatoes-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/356.Batata_Pulao_Recipe_Sweet_And_Spicy_Pulao_Made_With_Lentils_And_Potatoes-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dappalam Recipe- Andhra Vegetable Stew Recipe', 'dappalam-recipe-andhra-vegetable-stew-recipe', 'If you are craving for something comforting, full of nutrition and which goes along with a rice meal then you must make Dappalam. This amazing mixed vegetable tangy stew is made with mixed vegetables like carrots, bottle gourd, sweet potato, tamarind and jaggery. Its is easy to make and every mouthful creates a party in your mouth.', '["1 cup Bottle gourd (lauki) , peeled and cut into 1/2 inch cubes", "1 Carrot (Gajjar) , chopped into 1/2 inch dices", "2 Sweet Potato , chopped into 1/2 inch dices", "2 Drumstick , cut into 1 inch pieces", "4 Green Chilli , slit", "1 cup Tamarind Water", "2 tablespoons Jaggery", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "2 teaspoons Rice flour", "1 tablespoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Yellow Fenugreek Seeds", "1/4 teaspoon Asafoetida (hing)", "2 sprig Curry leaves"]'::jsonb, ARRAY['carrot dices', 'green chilli', 'tamarind water', 'sweet potato dices', 'bottle gourd (lauki) cubes', 'mustard seeds', 'asafoetida (hing)', 'jaggery', 'red chilli powder', 'drumstick', 'curry leaves', 'yellow fenugreek seeds', 'rice flour', 'turmeric powder', 'sunflower oil']::text[], '["To begin making\u00a0Dappalam/ Andhra Style Vegetable Stew Recipe prep all the ingredient and keep them aside.Add all the vegetables and green chillies into a pressure cooker along with 1 cup of water, salt and turmeric powder and pressure cooker for 3 whistles and turn off the heat.Release the pressure immediately by lifting it with a fork or running cold water over the pressure cooker to release the pressure.In a mixing bowl combine the tamarind water along with rice flour, turmeric powder and red chilli powder and make a smooth mixture.Heat oil in a wok or a large saucepan over medium heat; once the oil has heated add the mustard seeds, fenugreek seeds and allow it to crackle.", "Stir in the hnig and curry leaves along with the tamarind mixture.Add jaggery, cooked vegetables and give the Dappalam a brisk bowl for about 5 to 6 minutes until the flavours are well incorporated into the stew.", "Check the salt and spices and adjust the taste of the\u00a0Dappalam accordingly.Turn off the heat and transfer the\u00a0Dappalam into a serving bowl and serve hot.", "Serve Dappalam along with\u00a0Steamed Rice,\u00a0Andhra Style Pappu Charu\u00a0and\u00a0\u00a0Zucchini Thogayal\u00a0for a delicious Andhra Meal."]'::jsonb, 29, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Affiliate-Articles/Dappalam_Recipe-_Andhra_Style_Vegetable_Stew_Recipe-8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/357.Dappalam_Recipe-_Andhra_Style_Vegetable_Stew_Recipe-8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pudina Tawa Paratha Recipe (Mint Leaf Skillet Flat Bread)', 'pudina-tawa-paratha-recipe-mint-leaf-skillet-flat-bread', 'Pudina Tawa Parathas is simple quick and super delicous recipe of the traditional plain tawa paratha. Parathas are traditionally cooked in ghee on an iron skillet. Being relatively quick to make; the Pudina Parathas are a good substitute for Naans or Tandoori Rotis. The Parathas can be made circular, triangular or square in shape and served with vegetable dish or eaten plain with pickle or honey. At home Pudina Tawa Paratha Recipe are served for dinner along with Vegetables in Gravy combination.', '["1 cup Whole Wheat Flour", "200 grams Mint Leaves (Pudina)", "2 Green Chillies , (add more if you like it spicy)", "1/2 teaspoon Salt", "Oil , for kneading", "Ghee , or oil for cooking"]'::jsonb, ARRAY['whole wheat flour', 's mint leaves', 'pudina', 'reen chillies', 'salt', 'oil', 'ghee']::text[], '["To begin making the Pudina Tawa Paratha Recipe, we will first roughly blend the pudina leaves along with the green chillies in a blender.In a large bowl combine the flour, salt, the ground pudhina leaves, a tablespoon of oil and knead adding little water at a time to make firm and smooth dough.", "Add one tablespoon of oil to coat the dough and knead again.", "Cover and set aside for 15 minutes.Knead once again and divide the dough into 8 portions.", "Preheat the iron skillet on medium heat.Roll the paratha dough portions into balls and flatten them with the palm of your hand.", "Toss them on flour and roll them out into circles of approximately 3 inches in diameter.", "Put 1/4 teaspoon oil and spread it on the rolled dough.We need to get a triangle shape, to do so, first fold into a semi-circle, then fold the semi-circle into half again.", "You get a mini triangle shape.", "Tossing the triangle on a little flour, roll it out gently into a larger triangle.", "Continue the same process of rolling with the remaining dough portions.With skillet on medium high heat, place one rolled out dough on the skillet.", "After a few seconds you will notice an air pockets popping out.", "At this point flip the plain paratha and smear about 1/2 a teaspoon of ghee.", "Using a flat spatula do a light pressing and turning motion to cook to the pudhina paratha.Flip to the other side and press and turn in a similar way.", "You will notice brown spots around the pudhina parathas and it will be slightly crisp.", "Remove from heat and place on a platter or serve hot.Continue the similar process with the remaining rolled portions and stack the cooked pudhina paratha one above the other and serve hot.Serve the Pudina Tawa Paratha recipe for dinner along with\u00a0Batata Nu Shaak\u00a0or\u00a0Baingan Bharta\u00a0or any other\u00a0Dry Vegetable\u00a0or\u00a0Vegetables in Gravy\u00a0combination."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breads/Pudina_Tawa_Paratha-1-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/358.Pudina_Tawa_Paratha-1-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mamsaam Chops Recipe (Lamb Chops in Black Pepper Gravy)', 'mamsaam-chops-recipe-lamb-chops-in-black-pepper-gravy', 'Andhra style Mamsaam Chops i.e Lamb Chops in Black Pepper Gravy is perfect for an evening drinks with friends or with steaming hot rice, dal and a dollop of ghee. The black pepper in the gravy gives the curry a fantastic flavour and depth.', '["500 grams Lamb , lamb chops", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "Salt , to taste", "Oil , as required", "2 tablespoons Ghee", "3 Cloves (Laung)", "2 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "1 Onion , finely chopped", "1 teaspoon Coriander Powder (Dhania)", "1 tablespoon Whole Black Peppercorns , roughy pounded", "To be ground in masala", "1 inch Ginger", "12 cloves Garlic", "2 Green Chillies", "4 Dry Red Chillies"]'::jsonb, ARRAY['salt', 'green chillies', 'ginger', 'ghee', 'cardamom (elaichi) podsseeds', 'lamb lamb chops', 'red chilli powder', 'black peppercorns y', 'cloves garlic', 'dry red chillies', 'cinnamon stick (dalchini)', 'onion', 'coriander powder', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Mamsaam Chops recipe, firstly wash and dry the mutton chops and half cook them using a pressure cooker along with 1/2 cup water, salt, turmeric and chilli powder.", "This should take about 3 to 4 whistles.Grind together all the ingredients of the masala to a smooth paste using a little water if required in a grinder.Heat oil in a heavy bottomed pan, once the oil is hot add all the dry masalas and fry for 2 minutes till fragrant.Add onions and fry till deep brown in colour.", "Stirring so that they don''t burn.", "Add the par boiled lamb chops along with water and cook for about 2-3 minutes.Now add the ground masala, coriander powder, black pepper and mix well.", "Let it simmer covered till the full is fully cooked and the gravy turns thick.Serve Mamsaam Chops as a side dish with hot Steamed Rice,\u00a0Phulka\u00a0and\u00a0Kerala Style Chicken Tomato Roast\u00a0for a delicious wholesome weekend lunch or dinner."]'::jsonb, 55, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Monika_Manchanda/Mamsaam_Chops_Lamb_Chops_in_Black_Pepper_Gravy.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/359.Mamsaam_Chops_Lamb_Chops_in_Black_Pepper_Gravy.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spiced Turnips with Spinach Recipe', 'spiced-turnips-with-spinach-recipe', 'Spiced Turnips with Spinach Recipe is a nutrient-packed spicy side for Indian bread like naan, chapati or parathas. My mom used to feed this with hot chapatis saying that they were actually potatoes since I never used to like the idea of turnips. But once I grew older enough to understand its nutritional benefits, I started liking turnips as well.', '["3 Turnips , peeled and diced into cubes", "1 Spinach Leaves (Palak) , bunch, chopped", "2 Tomatoes , chopped", "1 Onion , sliced", "Salt , to taste", "Red Chilli powder , to taste", "3/4 teaspoon Turmeric powder (Haldi)", "3/4 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Ginger , paste", "1 teaspoon Garlic , paste(optional)", "3/4 teaspoon Cumin seeds (Jeera)", "3 Green Chillies , slit", "Oil , to cook", "2 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['tomato', 'salt', 'spinach leaves (palak) bunch', 'ginger paste', 'sunflower oil', 'red chilli powder', 'coriander (dhania) leaves', 'onion', 'cumin seeds (jeera)', 'coriander powder', 'turnips', 'turmeric powder', 'green chillies', 'garlic paste']::text[], '["To start preparing Spiced Turnips with Spinach Recipe, get all the ingredients handy.", "In a pan, heat oil.", "Once the oil is hot, add in the cumin seeds and allow them to sizzle.Add sliced onions and saute it till it changes colour on a medium flame.Add ginger and garlic paste and saute it for a minute until the raw smell goes.Add chopped tomatoes, turmeric powder, red chilli powder, salt and coriander powder.", "Cover and cook for another 2 minutes till done.Add turnips, mix it well.", "Cover it and cook on a low flame till it 3/4th done, takes about 5-10 minutes.Add chopped spinach, green/red chillies and cilantro.", "Mix well, cover it and cook on a low flame till it changes the colour or looks roasted.Serve the prepared Spiced Turnips and Spinach Recipe hot with chapatis or naan."]'::jsonb, 75, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Aarti_Sharma/Turnips_with_Spinach.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/360.Turnips_with_Spinach.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Aloo Naan Recipe', 'spicy-aloo-naan-recipe', 'The Spicy Aloo Naan Recipe is a twist to a traditional naan where the addition of spiced potatoes and garlic gives a delicious taste.The Naan is super simple to make and you can even serve the Spicy Aloo Naan as an appetizer for your parties or along with Paneer Makhani for a weeknight dinner.', '["2 cups All Purpose Flour (Maida)", "2 teaspoons Active dry yeast", "1/4 cup Curd (Dahi / Yogurt)", "2 teaspoon Sugar", "2 teaspoons Oil", "Salt , to taste", "3 Potatoes (Aloo) , boiled and mashed", "1 Onion , finely chopped", "2 Green Chillies , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "Coriander (Dhania) Leaves , few, finely chopped", "1/2 teaspoon Amchur (Dry Mango Powder)", "Salt , to taste", "2 cloves Garlic , finely chopped"]'::jsonb, ARRAY['salt', 'amchur (dry mango powder)', 'coriander (dhania) leaves', 'cloves garlic', 'dry yeast', 'curd', 'sugar', 'onion', 'potato (aloo)', 'flour (maida)', 'turmeric powder', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Spicy Aloo Naan Recipe, in a large bowl add the cups of flour all the ingredients for the dough and adding little water at a time knead to make a firm and smooth dough.Grease the dough with a little oil on the top and allow it to rest covered in a warm place until it doubles in volume.Once the naan dough has doubled, punch down the dough, knead for a minute and divide into 5 to 6 portions.The next step is to make the spicy aloo masala for the naan.In a large mixing bowl, add the mashed potatoes and the remaining ingredients and stir well to combine.", "Check the salt and adjust to suit your taste.Take a portion of the naan dough, dust it in flour and roll it into a 2 inch diameter circle.", "Place a spoonful of the spicy aloo masala and cover the filling by pulling the dough over it.", "Dust it with flour and gently roll to make a bigger oval.", "Brush the stuffed aloo naan with oil and sprinkle garlic on the top.", "Place it on a greased baking sheet.", "Proceed the same way with the remaining portions of the dough and potato filling.Preheat the oven to 200 C for 15 minutes.", "Bake the Spicy Aloo Naan in the preheated oven for about 10 minutes until puffed up and golden in color.Once done, remove from the oven brush some butter on the top and serve.", "Serve the Spicy Aloo Naan as an appetizer for your parties or along with\u00a0Paneer Makhani\u00a0for a weeknight dinner."]'::jsonb, 80, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/roshni/spicy-aloo-naan-recipe-new.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/361.spicy-aloo-naan-recipe-new.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Palak Tambuli Recipe - Udupi Style Spinach Tambli', 'palak-tambuli-recipe-udupi-style-spinach-tambli', 'Palak Tambuli is a spinach based yogurt like curry recipe from Udupi, Karnataka. It is a simple, healthy and comforting side dish. Tambuli with green leafy vegetables are neither spicy nor oily.', '["1/2 cup Curd (Dahi / Yogurt) , whisked", "Salt , to taste", "1/4 cup Fresh coconut", "1 Green Chilli", "1 teaspoon Cumin seeds (Jeera)", "1./2 teaspoon Whole Black Pepper Corns", "1 cup Spinach Leaves (Palak) , finely chopped", "1 teaspoon Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "2 sprig Curry leaves", "1 Dry Red Chilli , broken"]'::jsonb, ARRAY['curd', 'dahi / yogurt', 'salt', 'fresh coconut', 'reen chilli', 'cumin seeds', 'jeera', 'whole black pepper corns', 'spinach leaves', 'palak', 'coconut oil', 'mustard seeds', 'rai/ kadugu', 'curry leaves', 'dry red chilli']::text[], '["To begin making Palak Tambuli Recipe,prep all the ingredients and keep readyTo cook the spinach; heat oil in a pan over medium heat; add the spinach along with a little salt and cook until it has wilted down.", "Once wilted, turn off the heat and allow the spinach to cool.To grind the coconut masala, in a mixer jar, combine the fresh coconut, cooked spinach, along with green chilli, cumin seeds and whole peppercorns.", "Add some water to make a smooth coconut masala, set aside.", "To make the Palak Tambuli, in a large bowl, combine the whisked curd and the freshly ground coconut-palak masala and season with salt.", "For the tadka, heat oil in a tadka pan over medium heat; add the mustard and cumin seeds, and allow it to crackle.", "Next add in the red chilli and curry leaves, mix and turn off the flame.", "Pour this tadka on the palak tambuli, and serve.", "Serve\u00a0Palak Tambuli Recipe along with\u00a0Steamed Rice\u00a0and\u00a0Udupi Style Bendekayi Palya Recipe\u00a0\u00a0fpor a simple comforting weekday lunch."]'::jsonb, 30, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha_Kalluraya/Palak_Tambuli_Recipe_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/362.Palak_Tambuli_Recipe_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mustard Vegetable Curry Recipe', 'mustard-vegetable-curry-recipe', 'The Mustard Vegetable Curry is made from a delicious blend of Dijon Mustard, mixed vegetables and a subtle set of ingredients like cumin, chilli, and coconut milk. The dijon mustard and the coconut milk make a delicious and unique combination for a curry, making it perfect to be served along with a crusted bread or even steamed rice or tawa paratha for dinner.', '["2 teaspoons Oil", "1 teaspoon Cumin seeds (Jeera)", "2 cloves Garlic , grated", "2 Onions , finely chopped", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "120 ml Coconut milk", "1 cup Vegetable stock", "2 tablespoons Dijon Mustard", "2 Carrots (Gajjar) , cut into rounds or lengthwise of 1 inch thickness", "5 to 6 Green beans (French Beans) , cut into 1 inch pieces, steamed", "1/4 cup Green peas (Matar) , steamed", "2 Potatoes (Aloo) , boiled and diced small", "Salt , to taste"]'::jsonb, ARRAY['salt', 'vegetable stock', 'green beans (french beans)', 'red chilli powder', 'cloves garlic', 'green peas (matar)', 'carrot ness', 'onion', 'cumin seeds (jeera)', 'potato (aloo)', 'coconut milk', 'dijon mustard', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Mustard Vegetable Curry Recipe, we will first have to steam the vegetables and keep them ready You can use a steamer or a pressure cooker to cook the vegetables.Potatoes take a longer time to cook, so I suggest you cook them separate from the beans, carrots and peas.To begin making the curry base; heat a teaspoon of oil in a pan on medium heat.", "Add in the cumin seeds, garlic and onion and saute on medium heat until the onion has turned light pink and translucent.Once the onions are ready; add in the turmeric powder, chilli powder and stir for a few seconds.", "Finally add in the coconut milk, the vegetable stock and the dijon mustard.Add in the salt and check the spice and salt levels.", "Adjust to suit your taste.Finally stir in the steamed vegetables; turn the heat to low, cover the pan and simmer the curry 3 to 4 minutes.", "Turn off the heat and the Mustard Vegetable Curry is ready to be served.Serve the Mustard Vegetable Curry hot with steamed rice or tawa paratha for dinner."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Chefs/Chef_Vikas_Khanna/Mustard_Vegetable_Curry_Vikas_Khanna_Recipe_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/363.Mustard_Vegetable_Curry_Vikas_Khanna_Recipe_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mangalorean Manoli Curry Recipe - Indian Gherkins Curry', 'mangalorean-manoli-curry-recipe-indian-gherkins-curry', 'The Mangalorean Manoli Curry Recipe is a traditional curry from the Mangalorean Cusine in Karnataka. Manoli is a vegetable that belongs to the cucumber family, also popularly known as Indian Gherkins, Dondaikkai, Kovaikkai or even Ivy Gourd.', '["500 grams Tindora (Dondakaya/ Kovakkai)", "1 Onion , chopped", "4 Dry Red Chilli", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 tablespoon Coriander (Dhania) Seeds", "1 teaspoon Cumin seeds (Jeera)", "1 tablespoon Whole Black Peppercorns", "1 Tamarind", "2 cups Fresh coconut , grated", "3 cloves Garlic", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Oil , for cooking"]'::jsonb, ARRAY['salt', 'coconut', 'black peppercorns', 'cloves garlic', 'dry red chilli', 'tindora (dondakaya kovakkai)', 'coriander (dhania) seeds', 'onion', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'tamarind', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the\u00a0Mangalorean Manoli Curry Recipe; we will first steam cook the Manoli.", "You can use a pressure cooker or a steamer to cook it.", "Precooking the Manoli (Indian Gherkins) makes the cooking process faster and more nutritious too.I like to use a pressure cooker for steaming the vegetables.", "To do this, place the cut Manoli (Indian Gherkins) along with a pinch of salt and 2 tablespoons of water into the pressure cooker.Cover the pan, place the weight on and allow the vegetable to cook in the pressure cooker until you hear two whistles.", "After a whistle, turn off the heat and you can place the pressure cooker under running water to release the pressure immediately.", "Releasing the pressure immediately, helps retain the fresh green color of the Gherkins and also gives it a perfectly cooked texture.Click here to watch the video of how to cook vegetables in a pressure cooker.Our next step is to make the Manoli Curry Masala.", "In a small pan; roast the dry red chillies, fenugreek, coriander, cumin and black pepper until you can smell the roasted aromas.", "Add these to a small blender jar, along with the coconut, tamarind and turmeric powder.Grind the spices adding very little water to make a smooth curry paste.", "The Manoli curry paste is now ready.", "Keep aside.In the next step; heat a teaspoon of oil in a pan; add the chopped onions, and saute for a couple of minutes until the onions are soft and tender.", "Add the curry paste and saute for a couple of more minutes.Stir in the steamed gherkins, salt and add about 1-1/2 to 2 cups of water.", "You essentially want a thick gravy for the Manoli Curry; hence add water accordingly.", "Give all the ingredients a good stir.", "Check the salt levels and adjust to suit your taste.", "Give the mixture a quick boil only when you are ready to serve.", "Serve the\u00a0Mangalorean Manoli Curry Recipe\u00a0along with\u00a0Whole Wheat Lachha Paratha\u00a0and\u00a0Tomato Onion Cucumber Raita\u00a0for an everyday meal."]'::jsonb, 45, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Mangalorean_Manoli_Curry_Recipe_Indian_Gherkins_Tendley_Donadaikkai_Kovaikkai-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/364.Mangalorean_Manoli_Curry_Recipe_Indian_Gherkins_Tendley_Donadaikkai_Kovaikkai-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pata Gobi Aur Kele Kofta Curry Recipe - No onion No Garlic', 'pata-gobi-aur-kele-kofta-curry-recipe-no-onion-no-garlic', 'Pata Gobi Aur Kele Kofta Curry Recipe is a No onion No Garlic dish where pan fried koftas made from cabbage and raw bananas are dunk in a spicy and tangy tomato gravy. The dish promotes Ayurveda way cooking as it does not include any onion or garlic in it. Ayurveda cooking is mainly pure and natural.', '["1 Raw Banana , boiled and mashed", "1 cup Cabbage (Patta Gobi/ Muttaikose) , chopped", "1/2 cup Gram flour (besan)", "1 Green Chilli , chopped", "1 teaspoon Cumin seeds (Jeera)", "2 tablespoons Coriander (Dhania) Leaves , chopped", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Garam masala powder", "1 pinch Turmeric powder (Haldi)", "1/2 teaspoon Salt , to taste", "1 cup Oil , for deep frying", "3 Tomatoes , large tomatoes, pureed", "1 tablespoon Ginger , made into paste", "1 Green Chilli , slit", "1/2 cup Gram flour (besan)", "3 to 4 tablespoons Fresh cream", "2 tablespoons Curd (Dahi / Yogurt)", "1-1/2 tablespoons Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Garam masala powder", "1 to 2 Bay leaf (tej patta)", "1/2 teaspoon Cardamom (Elaichi) Pods/Seeds , freshly crushed", "Salt , to taste", "Oil , as required"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'ginger', 'garam masala powder', 'green chilli', 'coriander (dhania) leaves', 'bay leaf (tej patta)', 'cardamom (elaichi) podsseeds', 'red chilli powder', 'gram flour (besan)', 'tomato large tomato', 'curd', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'banana', 'cabbage (patta gobi muttaikose)', 'sunflower oil']::text[], '["To begin making the\u00a0Pata Gobi Aur Kele Kofta Curry Recipe, chop cabbage and press in batches to remove excess water.", "Collect the dry grated cabbage in a large mixing bowl.Cut the raw banana into half and pressure cook with water and salt till it is soft.", "Allow the pressure to release naturally and peel off the skin.", "Mash it completely and add it to the bowl with the cabbage.Into the cabbage and banana mash add besan, green chili, coriander, cumin powder, turmeric, garam masala, red chili powder and salt.", "Stir well to make a dry mix.Heat oil in a Kuzhi Paniyaram Pan and meanwhile make medium lemon sized kofta balls out of the mix and keep aside in a plate.Once the oil is hot, drop the kofta balls carefully into each cavities, fry till golden brown in color on all sides.", "Transfer the fried kofta balls on an oil absorbent paper to absorb excess oil.In a separate kadhai/wok, heat oil to make the curry.Add bay leaf and within few seconds add grated ginger and saute for few seconds till the aromas of the ginger release.", "Once done add besan and roast it for few seconds and immediately add the tomato puree in it and stir nicely for about a minute.After a minute add coriander powder, red chilli powder, turmeric powder, cumin powder and garam masala powder and saute the masala till oil starts leaving from sides.Now add 2 tablespoons of curd and saute for another minute or so.", "Once the masala starts smelling good, add fresh cream and mix nicely.Cook for another 2-3 mins and then add water to make the curry.", "The curry should be a little thick hence be careful while adding water.Adjust salt and let the curry come to a boil.", "Add freshly crushed cardamom, Mix well to combine and cover the pan.", "Simmer the curry for another 5 mins on low heat.After five minutes drop in the fried kofta balls and turn off the heat.Transfer the curry in a serving bowl and add a swirl of fresh cream to garnish along with some fresh coriander leaves and serve.Serve the Pata Gobi Aur Kele Kofta Curry Recipe along with\u00a0Phulka\u00a0or\u00a0Naan\u00a0with\u00a0Kachumber Salad Recipe With Cucumber, Onion & Tomatoes\u00a0by the side."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/9-oct/_Pata_Gobi_Aur_Kele_Kofta_Curry_Recipe_No_onion_No_Garlic-9305.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/365._Pata_Gobi_Aur_Kele_Kofta_Curry_Recipe_No_onion_No_Garlic-9305.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Capsicum Curry Recipe', 'capsicum-curry-recipe', 'Capsicum curry is a delicious, rich and creamy curry which is made with coloured bell peppers. One can give this delicious recipe a try if you want to make something different using bell peppers. This dish is a winner when served with hot phulkas or lachha parathas.', '["2-1/2 Red Yellow or Green Bell Pepper (Capsicum) , 1 green, 1 red and 1/2 yellow, cubed", "2 Onion , finely chopped", "2 Tomatoes , finely chopped", "2 Green Chillies , chopped", "5 Garlic , chopped", "1 Bay leaf (tej patta)", "1 teaspoon Coriander (Dhania) Seeds , coarsely pounded", "5 Whole Black Peppercorns", "1-1/2 tablespoon Cashew nuts , chopped", "1-1/2 tablespoon Peanut Butter , chopped", "1/2 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)"]'::jsonb, ARRAY['tomato', 'cashew nuts', 'peanut butter', 'bay leaf (tej patta)', 'red chilli powder', 'black peppercorns', 'coriander (dhania) seeds', 'garlic', 'onion', 'red yellow green bell pepper (capsicum) green', 'kasuri methi (dried fenugreek leaves)', 'green chillies', 'garam masala powder']::text[], '["To begin making Capsicum Curry, firstly add 2 tablespoon oil in a pan and saute the cubed capsicum for a few minutes.", "Do not over-fry the capsicum and let it be a bit crispy.", "Remove them from the pan and keep aside into a separate plate.In the same pan, roast the cashew-nuts and peanuts for about 2 minutes.", "Switch off the gas and let the nuts cool down.", "After cooling, powder the roasted nuts by adding them to a grinder.", "Remove and keep it aside in a separate bowl.Heat a kadhai and add 1 tablespoon oil.", "After the oil gets heated, add bay leaf and coriander seeds and fry them for 1 minute.Add chopped onions and fry them till onions turns pinkish.", "Now add chopped garlic and fry till the raw smell of garlic goes away.Add chopped green chilies and tomatoes and fry them till the tomatoes turn mushy.", "Switch off the gas.After cooling, add the onion-tomato mixture to the grinder and make a thick gravy by adding 1/4 cup water.Now again, heat the kadhai and add 1 teaspoon oil.", "Then pour the gravy and saute it for about 5 minutes.Mix the powdered nuts into the gravy and mix it properly.", "Once it is done, add the garam masala and red chilli powder.Add the fried capsicum and stir well.", "If the gravy is very thick, add 1/2 cup water and simmer it for about 10-15 minutes.Add salt according to your taste and garnish it with kasuri methi and chopped capsicum.Serve Capsicum Curry with Phulkas or Whole Wheat Lachha Paratha and Burani Raita."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Capsicum_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/366.Capsicum_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vazha Thandu Poriyal Recipe - Tamil Nadu Style Dry Banana Stem Fry', 'vazha-thandu-poriyal-recipe-tamil-nadu-style-dry-banana-stem-fry', 'Vazha Thandu Poriyal Recipe is a simple and quick Tamil Nadu recipe made with fibrous banana stem tossed in simple spice powders and seasonings. Poriyal is generally from Tamil Nadu.', '["300 grams Banana Stem , cut into small dices and soaked in buttermilk", "1/4 cup Pearl onions (Sambar Onions) , finely chopped", "2 Green Chillies , finely chopped", "1 sprig Curry leaves , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 tablespoons Fresh coconut , grated", "Oil , for cooking", "Salt , to taste"]'::jsonb, ARRAY['salt', 'banana stem dices buttermilk', 'mustard seeds', 'coconut', 'pearl onion (sambar onion)', 'curry leaves', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Vazha Thandu Poriyal Recipe, firstly pressure cook the banana stem along with the buttermilk, salt and turmeric powder for about 1 whistle.", "Release the pressure naturally and drain the water out.Heat a skillet with oil.", "Add mustard seeds, curry leaves and let the mustard seeds crackle.Once done, add the cooked Banana stem and mix everything properly.After a minute, add in the green chili, salt to taste and give it a mix.", "Let it cook for about 2 minutes.", "After 2 minutes, add in the grated coconut and give it stir fry for about 5 minutes.", "After 5 minutes, switch off the stove and it is ready to be served.Serve the\u00a0Vazha Thandu Poriyal Recipe\u00a0along with\u00a0Steamed Rice,\u00a0Parappu Rasam\u00a0and\u00a0Elai Vadam\u00a0to enjoy your\u00a0Lunch meal."]'::jsonb, 40, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Tamil_Nadu_Style_Vazha_Thandu_Poriyal_Recipe__Dry_Banana_Stem_Fry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/367.Tamil_Nadu_Style_Vazha_Thandu_Poriyal_Recipe__Dry_Banana_Stem_Fry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Garlic Dal Recipe', 'garlic-dal-recipe', 'Garlic Dal is one of the simplest but the yummiest dal to prepare. If you love garlic then this will surely go into your list of favorites. This creamy dal is filled with the garlic punch along with it being spicy and tangy. Garlic dal is best served with hot lachha paratha or steamed rice or ragi mudde along with a dollop of ghee.', '["1 cup Arhar dal (Split Toor Dal) , or moong dal", "1/4 cup Tamarind Paste", "5 Green Chillies , adjustable", "10 cloves Garlic", "Salt , to taste", "1 tablespoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "10 Curry leaves", "Coriander (Dhania) Leaves , as required for garnishing"]'::jsonb, ARRAY['coriander (dhania) leaves', 'salt', 'arhar dal moong dal', 'cloves garlic', 'mustard', 'curry leaves', 'oil', 'tamarind paste', 'green chillies']::text[], '["To start the preparation of Garlic Dal, pressure cook the dal well and let it cool.Dry roast the green chillies.Blend the cooked dal, roasted green chillies, garlic, tamarind paste, salt in a mixer till the dal turns smooth.Heat oil in a pan.", "Add mustard seeds and curry leaves.", "Let the curry leaves crackle.", "Add the blended dal and immediately switch off the flame.", "Do not heat the dal.", "If the dal cooks then it will lose the raw garlic flavour.", "Garnish with coriander leaves.Serve the Garlic Dal hot with\u00a0lachha paratha\u00a0or steamed rice or ragi mudde along with a dollop of ghee."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuri_Aggarwal/Garlic_Dal.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/368.Garlic_Dal.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spiced Onion Pulao Recipe - Pyaz Pulao Recipe', 'spiced-onion-pulao-recipe-pyaz-pulao-recipe', 'Spiced Onion Pulao Recipe is a super simple flavoured rice recipe that is roasted and then pressure cooked with some whole spices.', '["1 cup Rice", "2 tablespoons Ghee", "2 Bay leaves (tej patta)", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "3 Green Chillies , slit", "2 Onions , thinly sliced", "2 inch Ginger , finely chopped", "6 cloves Garlic , finely chopped", "1 Tomato , finely chopped", "Salt , to taste", "1/4 cup Mint Leaves (Pudina) , loosely packed & finely chopped"]'::jsonb, ARRAY['rice', 's ghee', 'bay leaves', 'tej patta', 'laung', 'cinnamon stick', 'dalchini', 'reen chillies', 'onions', 'ginger', 's garlic', 'tomato', 'salt', 'mint leaves', 'pudina']::text[], '["To begin making the Spiced Onion Pulao Recipe, wash the rice thoroughly, and drain off all the excess water using a strainer.", "Now pat dry the rice on an absorbent paper.", "Heat a kadai, on medium-low flame, and dry roast the rice for about 3-4 minutes, stirring continuously.", "We are not looking for any colour here.", "Turn off the flame and set aside.", "Heat a pressure cooker with ghee on medium flame, into the cooker add the whole spices - bay leaves, cloves and cinnamon and allow them to sizzle.", "Once the spices sizzle, add the onions, ginger and garlic and saute until the onions have softenedNow add the slit green chillies, chopped tomatoes and saute until the tomatoes are soft and mushy.Once soft, mash the tomatoes slightly with the back of the ladle.", "Finally add in the dry roasted rice, 2 cups of water, salt to taste and close the pressure cooker.", "Pressure cook for 2-3 whistles and turn off the heat.", "Wait for the cooker to depressurise and then open the lid.", "Once done, gently fluff with the Spiced Onion Pulao and transfer to a serving bowl.Serve\u00a0 Spiced Onion Pulao Recipe along with\u00a0Smoked Dhaba Dal Recipe\u00a0or\u00a0Bhune Pyaz Ka Gosht Recipe,\u00a0Onion Raita Recipe\u00a0and finish the meal with a dessert of\u00a0Oats Apple Phirni Recipe."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Articles/Spiced_Onion_Pulao_Pyaz_Pulao_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/369.Spiced_Onion_Pulao_Pyaz_Pulao_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gahat Rasmi Badi Recipe (Uttaranchal Kulith Koftas In Tomato Onion Gravy)', 'gahat-rasmi-badi-recipe-uttaranchal-kulith-koftas-in-tomato-onion-gravy', 'Gahat Rasmi Badi Recipe is an authentic curry from the regions of Uttaranchal. Steamed koftas are prepared using Gahat (kulith/Horse Gram) dal and later cooked with tomato onion based curry. The curry tastes better with a dollop ghee and hot steamed rice. This curry is such a simple delicious way to sneak in such a healthy pulse in our daily routine. Prepare Gahat Rasmi Badi Recipe (Uttaranchal Kulith Koftas In Tomato Onion Gravy) and serve with hot steamed rice and kulcha for a healthy nutritious lunch.', '["1 Cup Horse Gram Dal (Kollu/ Kulith) , soaked overnight", "1/4 teaspoon Turmeric powder (Haldi)", "2 Green Chillies , chopped finely", "1 tablespoon Oil", "1 Onion , chopped finely", "1 Tomato , chopped finely", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Ginger Garlic Paste", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Garam masala powder", "1/4 teaspoon Cinnamon Powder (Dalchini)", "1/2 cup Water", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'cinnamon powder (dalchini)', 'red chilli powder', 'water', 'ginger garlic paste', 'onion', 'cumin seeds (jeera)', 'horse gram dal (kollu kulith)', 'turmeric powder', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To prepare Gahat Rasmi Badi Recipe (Uttaranchal Kulith Koftas In Tomato Onion Gravy), soak Gahat dal in water overnight.", "Drain the excess water and grind them into a coarse paste with turmeric, chopped green chilies and a little salt.Scoop a tablespoon of grounded paste and roll into small round balls.", "Ensure that the batter is firm to do koftas and is not watery.Steam the balls in a steamer or in an idly cooker for about 10 minutes until they are cooked completely.", "Remove the koftas once it is cooked and keep it aside.Heat a medium sized non-stick pan.", "Add oil to the pan.Once the oil is hot, add cumin seeds and let it splutter.Stir in the chopped onions and cook until they become transparent.Add ginger garlic paste and saute until the raw smell goes off.Add chopped tomatoes and cook until they become mushy.Add spice powders and combine them well.Now, add water to the onion-tomato mixture and cook until they are completely cookedSeason it with salt.", "Now add steamed gahat balls to the curry.Cook with the lid covered over medium flame for about 5 minutes until the balls are blended completely with the curry.Serve Gahat Rasmi Badi Recipe (Uttaranchal Kulith Koftas In Tomato Onion Gravy) with hot steamed rice and kulcha."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/KarthikaKrishnan/Gahat_Rasmi_Bade.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/370.Gahat_Rasmi_Bade.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Nellikai Pachadi Recipe (Amla/ Gooseberry Raita)', 'nellikai-pachadi-recipe-amla-gooseberry-raita', 'The Nellikai Pachadi Recipe also known as the Raita in Hindi, is a wholesome and nutritious raita. Nellikai / gooseberry is rich in vitamin-c & antioxidants. When combined in yogurt and seasoned with coconut and mustard, it brings out delicious flavors. The Nellikai (Amla) Raita goes well with Dosas and even Parathas. Serve with your choice of Pulao recipe to a wonderful meal.', '["2 cups Curd (Dahi / Yogurt) , whisked", "4 Amla (Nellikai/ Gooseberry) , (Alma/Nellikai) grated", "1/4 cup Fresh coconut , grated", "1 Cucumber , peeled and grated", "2 Green Chillies , chopped finely", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "Salt , to taste", "1 teaspoon Oil"]'::jsonb, ARRAY['s curd', 'dahi / yogurt', 'amla', 'nellikai/ gooseberry', 'fresh coconut', 'cucumber', 'reen chillies', 'mustard seeds', 'rai/ kadugu', 'salt', 'oil']::text[], '["To begin making the Nellikai Pachadi Recipe, into a blender grind the raw gooseberries,\u00a0grated coconut, green\u00a0chilli\u00a0and salt into a coarse mixture.", "Keep aside.In a bowl whisk the yogurt well until smooth.", "Stir in the ground gooseberry mixture and grated cucumber.", "Check the salt and spice levels and adjust to suit your taste.Transfer the Nellikai (Amla) Raita into a serving bowl.The next step is to make the seasoning for the Nellikai Pachadi.", "Heat oil in a small pan; add the mustard seeds and curry leaves.", "Allow them to crackle.Pour the seasoning over the Nellikai Pachadi (Amla Raita) and stir it in and serve with your choice of Pulao recipe to a wonderful meal."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Raitas/Nellikai_Pachadi_Recipe_Amla_Gooseberry_Raita-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/371.Nellikai_Pachadi_Recipe_Amla_Gooseberry_Raita-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Cauliflower Paneer Kofta Curry Recipe', 'cauliflower-paneer-kofta-curry-recipe', 'Cauliflower Paneer Kofta Curry Recipe is another variant of the much loved range of kofta curries. I love kofta curry! Who doesn’t, right?', '["1 Cauliflower (gobi)", "1/2 cup Paneer (Homemade Cottage Cheese) , grated", "4 Potatoes (Aloo) , cooked and mashed", "3 tablespoons Corn flour", "1 tablespoon Red Chilli powder", "1 tablespoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera) , roasted", "1 teaspoon Garam masala powder", "Salt , to taste", "2 Onions , finely chopped", "4 Tomatoes , pureed", "1 teaspoon Ajwain (Carom seeds)", "1 1/2 tablespoon Kashmiri Red Chilli Powder", "1 tablespoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "Salt , to taste", "1 tablespoon Butter (Salted) , or oil", "1 tablespoon Fresh cream , reserve 2 teaspoons for garnish", "Water , as required", "Coriander (Dhania) Leaves , as required for garnish"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'corn flour', 'kashmiri red chilli powder', 'coriander (dhania) leaves', 'paneer', 'cauliflower (gobi)', 'ajwain (carom seeds)', 'red chilli powder', 'water', 'reserve', 'onion', 'butter oil', 'coriander powder', 'potato (aloo)', 'garam masala powder']::text[], '["To begin making Cauliflower Paneer Kofta Curry Recipe place big pot on the heat.", "Add 1 liter of water into the pot and bring it to a boil.", "Add 1 teaspoon of salt to the boiling water and turn off the heat.Next, to chop up the cauliflower, first remove the stem and leafy parts of the cauliflower and immerse it into the just-boiled, hot water.", "Allow the cauliflower sit for about 3 to 4 minutes.", "Then remove it from hot water, and place it on a kitchen towel.", "Pat it dry completely.Now grate the cauliflower completely and set it aside for a while.", "After about 10 minutes, cauliflower would have released a lot of water, squeeze it out and discard the water.Next, heat a pan and dry roast the grated cauliflower until it feels completely dry and contains no more moisture.", "While roasting it, take care not to cook it too much.", "It should not change to brown, so it is best to roast it on a low flame.Once the cauliflower is completely dry, take it off the heat, transfer it into a cool dish and allow it to come down to room temperature.Add the grated paneer to the cooled cauliflower.", "Add in the mashed potatoes, and all the spices along with corn flour.", "Knead well until everything is mixed.", "Make small lemon sized balls of the mix and arrange them on a plate.", "Set them aside till further use.Next, we need to fry the koftas.", "Warm some oil in a pan, when oil is hot enough, deep fry the koftas until evenly golden brown.", "For an oil-free version, you could also bake them in a pre-heated\u00a0oven, or use a kuzhi-paniyaram pan to pan-fry them.", "Either way, lay the golden brown koftas onto kitchen paper once they are browned on all sides.To prepare the curry, first warm some oil or butter in a pan.", "Add the shahi jeera and fry for a minute.", "Next add the finely chopped onions and fry them till translucent.", "Add the tomato puree and cook it together until the puree thickens and begins to leave the sides of the pan.At this stage, add all the spice powders and mix well.", "Then add water as required and bring the curry to boil.Turn the heat down, add the cream, mix well and finally add the fried kofta balls.", "Simmer on low heat for about 3 to 4 minutes.Turn off the heat, garnish the curry with the reserved cream and fresh coriander leaves.Serve\u00a0Cauliflower Paneer Kofta Curry\u00a0 with\u00a0Phulkas,\u00a0Dal Tadka\u00a0and\u00a0Chana Dal Pulao\u00a0along with a\u00a0Urad Dal Raita\u00a0for a comforting, yet special homely meal."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Cauliflower_Paneer_Kofta_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/372.Cauliflower_Paneer_Kofta_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer Makhani Recipe-Restaurant Style Recipe', 'paneer-makhani-recipe-restaurant-style-recipe', 'The Paneer Makhani Recipe is an all time favorite north Indian dish that is cooked in a rich tomato based gravy. The subtle blend of spices like cardamom, dried fenugreek leaves and the cream adds to the richness and flavor to the Makhani recipe.', '["250 grams Paneer (Homemade Cottage Cheese)", "2 cups Homemade tomato puree", "1/4 cup Fresh cream", "1 Onion , roughly chopped", "1 inch Ginger", "3 cloves Garlic", "1 teaspoon Cardamom Powder (Elaichi)", "1 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Red Chilli powder", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "2 teaspoons Honey", "Salt , to taste", "Oil , for cooking"]'::jsonb, ARRAY['s paneer', 'homemade cottage cheese', 's homemade tomato puree', 'fresh cream', 'onion', 'ginger', 's garlic', 'cardamom powder', 'elaichi', 'turmeric powder', 'haldi', 'cumin powder', 'jeera', 'garam masala powder', 'red chilli powder', 'kasuri methi', 'dried fenugreek leaves', 's honey', 'salt', 'oil']::text[], '["To begin making the\u00a0Paneer Makhani Recipe, make sure you have the\u00a0Home Made Paneer\u00a0and the\u00a0Tomato Puree\u00a0ready.", "Keep them aside.In the next step, make a smooth paste of the onion, ginger and garlic in a food grinder.", "Heat oil in a heavy bottomed pan, add a teaspoon of oil.", "Add the onion paste mixture and saute it on medium heat until the raw smell goes away.", "This would take about 4 minutes approximately.Next add the turmeric powder, cumin powder, cardamom powder, garam masala powder and stir-fry it along with the masala for about 2 minutes.", "This process of sauteing the masala helps the onions loose its raw smell faster.Once, well sauteed, add the\u00a0tomato puree and simmer until the tomato puree begins to start bubbling and boiling.Once it does, stir in the cream, chilli powder, salt, kasuri methi and paneer.", "Give the paneer makhani a good stir and simmer for another 3 to 4 minutes.After about 3 minutes of simmering, check the salt and spice levels and adjust to suit your taste.", "Turn off the heat and transfer the paneer makhani to a serving bowl.Serve the Paneer Makhani with an\u00a0Indian bread\u00a0of your choice for a cozy and quick weeknight dinner."]'::jsonb, 60, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Paneer_Makhani_Recipe-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/373.Paneer_Makhani_Recipe-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('One Pot Mixed Vegetable Curry Recipe Using Preethi Electric Pressure Cooker', 'one-pot-mixed-vegetable-curry-recipe-using-preethi-electric-pressure-cooker', 'The One Pot Mixed Vegetable Curry is a super simple dish which is made from fresh seasonal vegetables, cooked along with paneer and coconut milk all in a single pressure cooker. The Preethi electric pressure cooker is like an insta post which, helps in making cooking real easy and simple especially for working professionals who are hard pressed for time.', '["1 tablespoon Butter (Salted)", "2 Onions , thinly sliced or chopped", "1 inch Ginger , finely chopped", "6 cloves Garlic , finely chopped", "3 Cinnamon Stick (Dalchini)", "1 cup Homemade tomato puree", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "Salt , to taste", "1/2 cup Coconut milk", "1 Carrot (Gajjar) , peeled and sliced", "1 Potato (Aloo) , peeled and diced", "1 Green zucchini , peeled and diced", "1 cup Cauliflower (gobi) , cut into florets", "1/2 cup Green peas (Matar)", "1 cup Paneer (Homemade Cottage Cheese) , cut into cubes", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "1 cup Paneer (Homemade Cottage Cheese) , cut into cubes", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)"]'::jsonb, ARRAY['butter', 'salted', 'onions', 'ginger', 's garlic', 'cinnamon stick', 'dalchini', 'homemade tomato puree', 'turmeric powder', 'haldi', 'red chilli powder', 'garam masala powder', 'salt', 'coconut milk', 'carrot', 'gajjar', 'potato', 'aloo', 'reen zucchini', 'cauliflower', 'gobi', 'green peas', 'matar', 'paneer', 'homemade cottage cheese', 'kasuri methi', 'dried fenugreek leaves']::text[], '["To begin making the\u00a0One Pot Mixed Vegetable Curry Recipe in the Electric Pressure Cooker, first prep all the ingredients and keep them ready.Change the mode of the electric pressure cooker to saute mode and allow the pan to heat up for a couple of minutes.", "Once the pan is heated, add the oil/ ghee.Add the onion, ginger and garlic and saute until the onion softens.", "Once the onions soften, add spices, tomato puree, turmeric powder, garam masala powder and red chilli powder.Give it a stir, add the coconut milk, salt and all the vegetables along with the paneer and stir well again to combine.", "Cover the electric pressure cooker, and click on menu again and change the mode to the gravy mode.", "Turn the pressure nozzle to the pressure mode and allow the pressure cooker to do its work of cooking the mixed vegetable curryThe cooker will go into keep warm mode once it done.", "You can open the cooker once the pressure has released and check the salt and seasonings in the One Pot Mixed Vegetable Curry.Once done, transfer the\u00a0One Pot Mixed Vegetable Curry to a serving bowl and serve hot.Serve the\u00a0One Pot Mixed Vegetable Curry Recipe\u00a0along with\u00a0Jeera Pulao,\u00a0Phulka\u00a0and\u00a0Palak Raita Recipe (Spinach Yogurt Salad)\u00a0for a quick weeknight dinner."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/One_Pot_Mixed_Vegetable_Curry_Recipe_in_Electric_Pressure_Cooker_Insta_Pot-4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/374.One_Pot_Mixed_Vegetable_Curry_Recipe_in_Electric_Pressure_Cooker_Insta_Pot-4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kosamalli Recipe (Chettinad Style Brinjal and Potato Mash)', 'kosamalli-recipe-chettinad-style-brinjal-and-potato-mash', 'Kosamalli Recipe is a very popular dish from the Chettinad region of Tamil Nadu. It is usually served with hot idiyappam or string hoppers. It is prepared using minimal spices, hence it is lighter on the tummy. Serve Kosamalli (Chettinad Style Brinjal and Potato Mash) with string hoppers/Idiyappam or idli or dosas for an interesting weekend breakfast.', '["4 Brinjal (Baingan / Eggplant)", "2 Potatoes (Aloo)", "15 Shallots , finely chopped", "2 Tomatoes , finely chopped", "4 Green Chillies , finely chopped", "2 teaspoons Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Red Chilli powder", "1 tablespoon Tamarind , pulp", "1 sprig Curry leaves", "Few sprig Coriander (Dhania) Leaves , finely chopped", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'tamarind pulp', 'mustard seeds', 'brinjal (baingan eggsplant)', 'red chilli powder', 'curry leaves', 'coriander (dhania) leaves', 'potato (aloo)', 'green chillies', 'sunflower oil']::text[], '["To begin making Kosamalli Recipe (Chettinad Style Brinjal and Potato Mash),\u00a0pressure cook\u00a0the brinjals and potatoes for two whistles.", "D-skin the vegetables and mash it to a pulpy consistency and keep it aside.Take a big wok, heat oil in medium flame, add the mustard seeds and let it crackle.", "To this add the curry leaves and let it splutter.Add the finely chopped shallots and saut\u00e9 till it is cooked firmly.Now add the chopped tomatoes and green chilies and saut\u00e9 for five minutes.Add the red chili powder and stir it.To this add the brinjal and potato mash, enough water to bring it to a sambar like consistency.Season with salt, add the tamarind pulp and bring it to a rolling boil.Add the finely chopped coriander leaves and switch off the flame.Serve the Kosamalli Recipe (Chettinad Style Brinjal and Potato Mash) with idiyappam or idli/dosas for a weekday breakfast."]'::jsonb, 35, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Kosamalli_Chettinad_Style_Brinjal_and_Potato_Mash.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/375.Kosamalli_Chettinad_Style_Brinjal_and_Potato_Mash.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lauki and Whole Green Moong Dal Cheela Recipe', 'lauki-and-whole-green-moong-dal-cheela-recipe', 'Lauki And Whole Green Moong Dal Cheela Recipe is a healthy and protein rich Cheela / Dosa recipe. It is gluten free and vegan. Nutritious bottle gourd combined with high protein whole green moong dal makes a protein rich and high fiber much-needed breakfast for vegetarians.', '["1 cup Green Moong Dal (Whole)", "1 tablespoon Rice flour", "1/2 cup Bottle gourd (lauki) , grated", "2 Green Chillies , chopped", "1 inch Ginger , chopped", "1 tablespoon Coriander (Dhania) Leaves , finely chopped", "Asafoetida (hing) , a pinch", "Salt", "2 teaspoons Oil", "Water , as required"]'::jsonb, ARRAY['salt', 'ginger', 'rice flour', 'coriander (dhania) leaves', 'asafoetida (hing)', 'water', 'bottle gourd (lauki)', 'green moong dal', 'green chillies', 'sunflower oil']::text[], '["To begin making Lauki And Whole Green Moong Dal Cheela Recipe, soak whole green gram for 5 hours.", "Wash and drain green gram.", "You can now proceed to prepare the batter for the cheela.To prepare the cheela batter, blend soaked green gram, ginger and chilies in a mixer to a smooth batter adding enough water.The batter should have a consistency thicker than a dosa batter as the addition off lauki will in turn add more water to the batter.", "Transfer the batter to a mixing bowl.At this stage, grate the lauki and add to the batter.", "Add chopped coriander leaves, salt, rice flour and hing.", "Add water if needed and prepare batter just like that of a dosa batter consistency.Heat a Tava or frying pan.", "Take a ladle full of batter and pour over the Tava.", "Spread the batter in circular motion from inside out.", "Pour a teaspoon of oil / ghee all over the sides of cheela and cook till it turns golden brown on both the sides.", "Similarly, prepare rest of the cheelas.Serve\u00a0Lauki and Whole Green Moong Dal Cheela Recipe\u00a0with\u00a0Red Chilli Coconut Chutney Recipe (South Indian Chutney), or\u00a0Sweet and Spicy Tomato Chutney Recipe\u00a0for breakfast.", "You can also serve a cup of\u00a0Masala Chai\u00a0with it."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Preeti_Tamilarasan/Lauki_Cheela_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/376.Lauki_Cheela_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Beetroot Tambuli Recipe', 'beetroot-tambuli-recipe', 'Beetroot Tambuli Recipe is a beetroot-yogurt based curry made Karnataka style. Cooling during summers, this coconut based curry with a simple tempering of mustard seeds, curry leaves and dry red chillies.', '["1 Beetroot , grated", "1/2 cup Curd (Dahi / Yogurt) , whisked", "Salt , to taste", "1/4 cup Fresh coconut , grated", "1 Green Chilli", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Whole Black Pepper Corns", "1 teaspoon Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon White Urad Dal (Split)", "1 Dry Red Chilli , broken", "2 sprig Curry leaves"]'::jsonb, ARRAY['beetroot', 'curd', 'dahi / yogurt', 'salt', 'fresh coconut', 'reen chilli', 'cumin seeds', 'jeera', 'whole black pepper corns', 'coconut oil', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'dry red chilli', 'curry leaves']::text[], '["To begin making Beetroot Tambuli Recipe,prep all the ingredients and keep readyTo cook the beetroot; heat oil in a pan over medium heat; add the beetroot along with a little salt and cook\u00a0 for a few minutes until soft.", "Once soft, turn off the heat and allow the beetroot to cool.To grind the coconut masala, in a mixer jar, combine the fresh coconut, cooked beetroot, along with green chilli, cumin seeds and whole peppercorns.", "Add \u00bd cup of warm to make a smooth coconut masala, set aside.", "To make the Beetroot Tambuli, in a large bowl, combine the whisked curd and the freshly ground coconut-beetroot masala and season with salt.", "For the tadka, heat oil in a tadka pan over medium heat; add the mustard, cumin seeds and split urad, and allow it to crackle and the dal to turn golden brown and crisp.", "Next add in the red chilli and curry leaves and roast for a few seconds and turn off the heat.", "Pour this tadka on the beetroot tambuli, and serve.", "Serve\u00a0Beetroot Tambuli Recipe along with Steamed Rice and\u00a0Padpe Uppukari - Harive Soppu Palya Recipe\u00a0for a simple South Indian lunch."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Gauravi_Vinay/Beetroot_Tambuli_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/377.Beetroot_Tambuli_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Quick Paneer Masala Recipe - 15 Minute Paneer Gravy', 'quick-paneer-masala-recipe-15-minute-paneer-gravy', 'The Quick Paneer Masala Recipe is simmered in honey tomato gravy with subtle spices is sure to make your dinners light and nutritious. This dish will be a reason for you to start cooking your dinners, as they can get as simple as this recipe.', '["1 teaspoon Ghee", "1 Onion , finely chopped", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "6 Tomatoes , made into a puree", "2 tablespoons Fresh cream", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 tablespoon Jaggery", "250 grams Paneer (Homemade Cottage Cheese) , cubed", "Salt , to taste", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)"]'::jsonb, ARRAY['ghee', 'onion', 'ginger', 's garlic', 'tomatoes', 's fresh cream', 'garam masala powder', 'coriander powder', 'dhania', 'turmeric powder', 'haldi', 'red chilli powder', 'jaggery', 's paneer', 'homemade cottage cheese', 'salt', 'kasuri methi', 'dried fenugreek leaves']::text[], '["To prepare Home Made Paneer simmered in honey tomato gravy, if it is a store bought paneer; soak in hot salt water for about 10 minutes.", "This process makes the paneer soft and tasty.Cut the tomatoes and puree it in a blender and keep aside.", "Heat oil in a pan; add the onion,\u00a0ginger and garlic and saute it until the onions soften and turn lightly golden.Once golden, add the tomato puree, turmeric powder, red chilli powder, coriander powder, garam masala powder, salt, paneer, jaggery and cream.Give all the ingredients a quick stir.Cover the pan and turn the heat to medium and allow the paneer masala gravy to come to a brisk boil - allow it to simmer and cook for 10 minutes.", "Once done, give it a stir, check the salt and spices and adjust according to taste.Turn off the heat and transfer the Quick Paneer Masala Gravy into a serving bowl, stir in the kasuri methi and serve hot.Serve the\u00a0Quick Paneer Masala Gravy with\u00a0phulkas\u00a0for a super quick and healthy weeknight dinner."]'::jsonb, 65, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Quick_Paneer_Masala_Recipe_Video_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/378.Quick_Paneer_Masala_Recipe_Video_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Methi Jowar Ragi Thalipeeth Recipe - Healthy Diabetic Friendly Recipe', 'methi-jowar-ragi-thalipeeth-recipe-healthy-diabetic-friendly-recipe', 'The Methi Ragi Jowar Thalipeeth Recipe is a wholesome and healthy recipe, that is made from a combination of ragi and jowar flour combined along with methi leaves,green chillies and ginger. It makes a delicious Indian diabetic breakfast recipe.', '["1 cup Methi Leaves (Fenugreek Leaves) , tighly packed", "1 Onion , finely chopped", "2 Green Chillies , finely chopped", "1/2 cup Jowar Flour (Sorghum)", "1/2 cup Ragi Flour (Finger Millet/ Nagli)", "1/2 cup Gram flour (besan)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "Oil , to smear", "Salt , to taste"]'::jsonb, ARRAY['methi leaves (fenugreek leaves) tighly packed', 'salt', 'cumin powder (jeera)', 'jowar flour (sorghum)', 'red chilli powder', 'gram flour (besan)', 'ragi flour (finger millet nagli)', 'onion', 'coriander powder', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making Methi Jowar Ragi Thalipeeth Recipe, clean, wash and finely chop the fenugreek leaves and keep aside.Into a mixing bowl, add the jowar flour, ragi flour, besan, turmeric, red chilli powder, coriander powder, cumin powder, salt and mix well.", "Add the chopped fenugreek/ methi leaves, green chilli and onions.Now make a firm Methi Jowar Ragi Thalipeeth dough using lukewarm water.", "Add water slowly bit by bit, to make a tight thalipeeth dough.", "This dough is gluten free and will not have a binding like wheat flour.Divide the dough into equal parts (I made 8 thalipeeth from the dough).Preheat the flat skillet on medium heat, while you proceed to make the Methi Jowar Ragi Thalipeeth.Now, to make the thalipeeth grease the butter paper with little oil.Place a portion of small Methi Jowar Ragi Thalipeeth dough in the centre and start patting it using the fingers to a small disc size.", "Make three small holes, so the thalipeeth cooks evenly.Transfer the patted thalipeeth on the preheated skillet and carefully peel off the butter paper.Pour a teaspoon of oil around and let the Methi Jowar Ragi Thalipeeth cook on the base for about 4 minutes.Flip over the thalipeeth and cook on the other side.Likewise, prepare the rest of the Methi Jowar Ragi Thalipeeth .Serve the\u00a0nutritious\u00a0Methi Ragi Jowar Thalipeeth Recipe along with chilled\u00a0Yogurt\u00a0,\u00a0Red Chilli Thecha\u00a0and\u00a0Ginger Cardamom Chai Recipe\u00a0for healthy indian breakfast or a healthy\u00a0diabetic breakfast, lunch or dinner."]'::jsonb, 45, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Methi_Thalipeeth_Recipe_Maharashtrian_Style_Mixed_Flour_Flatbread_with_Fenugreek_Leaves.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/379.Methi_Thalipeeth_Recipe_Maharashtrian_Style_Mixed_Flour_Flatbread_with_Fenugreek_Leaves.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spinach Thalipeeth Recipe', 'spinach-thalipeeth-recipe', 'Spinach Thalipeeth Recipe is a wonderful breakfast dish that has the goodness of spinach leaves mixed along with whole wheat flour, rice flour and gram flour to create a thin flat bread which is popularly called as thalipeeth. The thin bread is obtained by flattening the dough on a working sheet and slowly placing it over a hot flat tawa and cooking them till they lightly crisp up.', '["1 cup Whole Wheat Flour", "1/4 cup Rice flour", "1/4 cup Gram flour (besan)", "1 cup Spinach Leaves (Palak) , chopped", "1 Onion , finely chopped", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "Salt , to taste", "Oil , to smear"]'::jsonb, ARRAY['salt', 'wheat flour', 'cumin powder (jeera)', 'red chilli powder', 'gram flour (besan)', 'onion', 'cumin seeds (jeera)', 'rice flour', 'turmeric powder', 'spinach leaves (palak)', 'sunflower oil']::text[], '["To begin making the Spinach Thalipeeth Recipe, add all the ingredients into a bowl and slowly star mixing by adding lukewarm water.", "Knead it to a wet dough but not sticky.Cover with a damp cloth and rest for about 10 minutes.Now to prepare the Thalipeeth, place a non stick tawa/skillet on the heat.", "Spread out a large piece of plastic, or parchment paper on your work surface.Grease your palms with oil.", "Pinch a big ball of dough place it in the centre of the parchment or plastic.", "Then gently flatten it out to form a hand-patted disc.Lift the paper, along with the roti on it and turning it over, place it on the skillet with the rotti down on the hot skillet.Carefully supporting the rotti peel off the paper.", "Drizzle a little bit of oil along the edges of the roti and in the centre, into the hole made on the roti and allow it to sizzle and crisp up.When it seems half cooked, flip the roti over with a spatula to cook the other side.Cook well till you have brown patches on both sides.", "Then, take the thalipeeth off the skillet, add a dollop of butter or ghee, and serve immediately.Serve the Spinach Thalipeeth Recipe along with\u00a0Nellikai Pachadi Recipe\u00a0,\u00a0Lahsun ki Chutney | A Spicy Garlic Chutney\u00a0or just a pickle by the side for your morning breakfast."]'::jsonb, 35, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Spinach_Thalipeeth_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/380.Spinach_Thalipeeth_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Onion Thepla Recipe', 'onion-thepla-recipe', 'Onion Thepla Recipe is an easy and quick flatbread that is delicious and can be had along with your everyday subzi. Caramelized onions with Indian spice powders is added into the atta or the wheat flour and then kneaded to form a dough. The dough is then rolled thin to form a round shape which is cooked on tawa on either side till there are brown spots on either side. This is one of the way to add in an extra crunch and flavor to your everyday paratha.', '["2 cups Whole Wheat Flour", "2 Onion , finely chopped", "1 Green Chilli , finely chopped", "1 inch Ginger , finely chopped", "3 cloves Garlic , finely chopped", "2 teaspoon Garam masala powder", "2 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Black pepper powder", "Salt , to taste", "1 tablespoon Oil , for the dough", "Ghee , or oil for making the Theplas"]'::jsonb, ARRAY['ghee', 'oil making the theplas', 'salt', 'wheat flour', 'ginger', 'green chilli', 'amchur (dry mango powder)', 'sunflower oil the dough', 'cloves garlic', 'onion', 'black pepper powder', 'turmeric powder', 'garam masala powder']::text[], '["To begin making the Onion Thepla Recipe, we will first heat a kadai with oil, add cumin seeds and allow it crackle for few seconds.Add in ginger and garlic and saute till they turn soft, add chopped onions and cook until they turn golden brown.Once done add green chilies and all the spice powders like the garam masala powder, amchur powder, turmeric powder, pepper powder and salt to taste and mix well, cook for another few minutes till well combined and cooked and turn off the heat.Allow it to cool down and add this saut\u00e9ed onions into a bowl with the wheat flour and oil.", "Add water little by little and form a firm dough which is not sticky.Rest for at least 10 minutes and shape them into medium sized balls.Dust it with wheat flour and roll it gently to make a Thepla.", "The diameter of the thepla depends on how thin or thick you want it to be.", "Repeat the same process with the remaining dough portions.Preheat the skillet on medium flame.", "Place the rolled thepla gently on it and cook on both sides, using oil or ghee till the thepla have brown spots on either side.", "Serve the Onion Thepla Recipe along with\u00a0Yellow Pumpkin Dal\u00a0,\u00a0Bihari Karela and Aloo Ki Subzi\u00a0and raita to make it a complete meal for your everyday lunch."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Onion_Thepla_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/381.Onion_Thepla_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Matar Korma Recipe In White Gravy', 'aloo-matar-korma-recipe-in-white-gravy', 'Aloo and Matar happens to be everyones favourite, make it dry or into a spicy gravy, it is loved by all age groups. However, we will cook Aloo Matar Korma Recipe In White Gravy, which is an inseparable combination of Aloo and Matar in a rich white gravy.', '["500 grams Baby Potatoes , boiled", "1 cup Green peas (Matar) , boiled", "1 Bay leaf (tej patta)", "2 Cardamom (Elaichi) Pods/Seeds", "4 Cloves (Laung)", "1 teaspoon Garam masala powder", "2 tablespoons Curd (Dahi / Yogurt)", "1/4 cup Fresh cream", "1 tablespoon Ghee", "Salt , to taste", "To grind into a smooth paste", "1 Onion , roughly chopped", "2 tablespoons Cashew nuts", "2 Green Chillies", "1 inch Ginger"]'::jsonb, ARRAY['cashew nuts', 'salt', 'green chillies', 'ginger', 'cardamom (elaichi) podsseeds', 'bay leaf (tej patta)', 'ghee', 'green peas (matar)', 'curd', 'onion', 'baby potatoes', 'cloves (laung)', 'garam masala powder']::text[], '["To begin making the Aloo Matar Korma Recipe In White Gravy, wash and pressure cook the baby potatoes to 2 whistles.", "Peel and keep aside.Similarly, steam or boil the green peas and keep them aside.Make a smooth paste of the ingredients mentioned under ''grind into a smooth paste'' which includes onion, cashew nuts, green chillies and ginger using a mixer grinder.", "Keep it aside.Now, heat ghee in a heavy bottomed pan, add the bayleaf, cardamoms, cloves and let it release its aroma into the ghee.", "This will take about 10 to 15 seconds.Add the ground onion ginger cashew mixture into the pan and saute for 3 minutes.Gently whisk the curd and garam masala into the cream to a smooth texture and add it to the pan.Add a cup of water, season with salt and let it simmer for 2 to 3 minutes.Add the boiled baby potatoes and green peas, simmer for another 2 minutes and switch off the flame.Serve this delicious\u00a0Aloo Matar Korma Recipe In White Gravy\u00a0along with\u00a0Tawa Paratha\u00a0and\u00a0Palak Raita\u00a0for a weekday meal."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Aloo_Matar_Korma_Recipe_In_White_Gravy.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/382.Aloo_Matar_Korma_Recipe_In_White_Gravy.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Stuffed Karela With Aloo Recipe', 'stuffed-karela-with-aloo-recipe', 'Stuffed Bitter Gourd With Potatoes, also called as Stuffed Karela With Aloo Recipe makes a great accompaniment to rice and dal. There is no bitterness, also no odd taste. This Stuffed Karela With Aloo Recipe is a great way to make bitter karela taste their best.', '["5 Karela (Bitter Gourd/ Pavakkai)", "2 Potatoes (Aloo) , boiled", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 teaspoon Chaat Masala Powder", "Salt , as needed", "Oil , as required"]'::jsonb, ARRAY['salt', 'karela (bitter gourd pavakkai)', 'chaat masala powder', 'red chilli powder', 'potato (aloo)', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To prepare Stuffed Karela With Aloo Recipe, first clean the karelas/bitter gourd.", "Rinse off with salt and turmeric to remove the bitterness.", "Let it rest for 20-25 minutes.Now make a vertical slit on each karela.", "Scoop out and discard seeds and pulp to fill the potato masala.Then prepare the potato masala.", "In a mixing bowl, smash the boiled potatoes.", "Add turmeric powder, red chili powder, chat masala, garam masala and salt.", "Mix everything to be incorporated well.Now fill the karelas with potato masala filling tightly.Heat oil in a Shallow frying pan, shallow fry stuffed karelas lightly for a minute, such that the stuffing doesn\u2019t fall off.", "Then cover and cook on a low-medium heat till stuffed karelas are well cooked.Once the karelas are nice and soft, switch off the heat and it is ready to be served.", "Serve\u00a0Stuffed Karela With Aloo\u00a0along with\u00a0Moong Dal Tadka,\u00a0Palak Raita\u00a0and\u00a0Phulka\u00a0for an everyday meal with your family."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Sasmita/Stuffed_karela_with_aloo.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/383.Stuffed_karela_with_aloo.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chawli Ki Phali & Aloo Sabzi Recipe', 'chawli-ki-phali-aloo-sabzi-recipe', 'Chawli Ki Phali & Aloo Sabzi Recipe is a dry sabzi made by stir frying yard beans with Indian spices like coriander powder, red chilli powder, amchur powder to create a spicy side dish. It is made North Indian Style with fennel seeds which goes really well as a sukhi sabzi with phulka and tawa paratha.', '["300 grams Green Chawli Beans (Yard long beans/Karamani/Barbati) , cut into 2 inch long", "2 Potatoes (Aloo) , peeled cut into 2 inch long", "1 teaspoon Fennel seeds (Saunf)", "21/2 teaspoon Coriander Powder (Dhania)", "2 teaspoons Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Amchur (Dry Mango Powder)", "3 teaspoons Gram flour (besan)", "Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'amchur (dry mango powder)', 'fennel seeds (saunf)', 'red chilli powder', 'gram flour (besan)', 'green chawli beans (yard beanskaramanibarbati)', 'coriander powder', 'potato (aloo)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Chawli Ki Phali & Aloo Sabzi Recipe, pressure cook the yard beans with little bit of water and salt for about 1 whistle and keep it aside.Allow the pressure to release naturally and strain the water.", "Heat a skillet with oil, add fennel seeds and allow it to crackle.Add potatoes and saute them till they crisp up and is cooked.", "You can cover it with the lid and cook for about 5 minutes.Add cooked yard beans along with all the spice powders and give it a mix keep cooking till the masala loses the raw smell.Add besan and salt and mix\u00a0Chawli Ki Phali & Aloo Sabzi well, saute for another 5 minutes and switch off the heat.Serve the Chawli Ki Phali & Aloo Sabzi Recipe along with\u00a0Phulka\u00a0or tawa paratha,\u00a0kadhi\u00a0to make a complete meal."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Chawli_Ki_Phali__Aloo_Subzi_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/384.Chawli_Ki_Phali__Aloo_Subzi_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Broccoli and Paneer Paratha Recipe', 'broccoli-and-paneer-paratha-recipe', 'Broccoli and Paneer paratha is a simple and easy to make the recipe that is perfect for a breakfast or for kids a lunch box.', '["Ingredients for the dough", "2 cups Whole Wheat Flour", "1 teaspoon Salt", "2 teaspoon Oil", "Ingredients for the filling", "1-1/2 cups Broccoli , grated (approximately 1 large head)", "1 Potato (Aloo) , boiled and mashed", "1/2 cup Paneer (Homemade Cottage Cheese) , crumbled", "1 Green Chillies , finely chopped", "Salt , to taste", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Chaat Masala Powder", "Ghee , or oil for cooking the paratha"]'::jsonb, ARRAY['ingredients for the dough', 's whole wheat flour', 'salt', 'oil', 'ingredients for the filling', 's broccoli', 'potato', 'aloo', 'paneer', 'homemade cottage cheese', 'reen chillies', 'cumin powder', 'jeera', 'chaat masala powder', 'ghee']::text[], '["To begin making Broccoli Paratha recipe, we will first make the dough for the paratha.To make the dough, combine the flour and salt for the dough in a large bowl.", "Add a little water at a time and knead to make a smooth dough.", "Drizzle a little oil on the top and continue to knead until the dough is smooth and not sticky.", "Cover the dough and allow it to rest until we prepare the filling for the parathas .To make the filling, combine all the ingredients for the filling in a large bowl.", "Check for the salt and spice levels in the filling and adjust to suit your taste.Now that we have both the dough and the filling ready, we will begin the process of making the stuffed\u00a0Broccoli Paratha.Divide the dough into 6-8 equal portions.", "Take one portion and dust in dry flour.", "Roll the dough to make a 3-4 inch diameter circle.", "Place 2 tablespoons of the filling in the center on the circle and bring the dough edges together towards the center.", "Seal the edges of the dough and pinch out any excess dough from the stuffed paratha.Flatten the paratha with your fingers, dust it in flour once again and roll the paratha applying very gentle pressure to make a 5 to 6 inch diameter circle.Proceed the same way with the remaining dough portions and stuff with the filling and roll into a paratha.Our next step is to cook the paratha; for this preheat a skillet (roti tawa) (preferably iron skillet).When the skillet is hot; place the stuffed rolled our paratha on the skillet and cook for a minute on both sides until you notice a few brown spots appear.When you notice the brown spots, smear some ghee or oil on both sides and cook until the paratha has turned golden brown and lightly crisp on both sides.", "Cook on medium and not high heat as you want the paratha to get cooked evenly.", "Once the paratha is done, place it on a platter and proceed to cook the remaining parathas.Serve\u00a0Broccoli and Paneer paratha with\u00a0pickle\u00a0of your choice and\u00a0Tomato Onion Cucumber Raita Recipe\u00a0and a hot cup of\u00a0Adrak Chai\u00a0."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Neha_Mathur/Broccoli_paneer_paratha_recipe_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/385.Broccoli_paneer_paratha_recipe_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Pacha Mango Avial Recipe', 'kerala-style-pacha-mango-avial-recipe', 'Avial is a staple Kerala dish which has loads of vegetables in it, and Pacha Mango Avial Recipe is a beautiful twist to the traditional recipe.', '["1 Carrot (Gajjar) , finely chopped", "1 Brinjal (Baingan / Eggplant) , finely chopped", "1 Potato (Aloo) , finely diced", "1 Elephant yam (Suran/Senai/Ratalu) , finely diced", "6 Green beans (French Beans) , cut into 1 inch pieces", "1 Mango (Raw) , cut into 1 inch lengthwise, stoned discarded", "1/4 teaspoon Turmeric powder (Haldi)", "1 cup Fresh coconut , grated", "1 tablespoon Ginger , juliennes", "6 Green Chillies", "1/2 teaspoon Cumin seeds (Jeera)", "1 cup Pearl onions (Sambar Onions)", "2 sprig Curry leaves", "1 tablespoon Coconut Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'green beans (french beans)', 'elephant yam (suransenairatalu)', 'coconut', 'brinjal (baingan eggsplant)', 'ginger juliennes', 'potato (aloo)', 'carrot', 'mango', 'pearl onion (sambar onion)', 'curry leaves', 'cumin seeds (jeera)', 'coconut oil', 'turmeric powder', 'green chillies']::text[], '["To begin making Kerala Style Pacha Mango Avial Recipe, in a mixer grinder, coarsely grind fresh grated coconut, green chillies (reserve a few for later), cumin seeds and shallots with a little water.", "Keep aside in a bowl.Place a kadai on a medium heat, cook the vegetables with just enough water so that the water should get dried up when the veggies are cooked al dente. (about 70% cooked)Add turmeric powder, give it a quick mix, and cook further.When the vegetables are cooked till firm (do not over cook), add the raw mango pieces and cook for another 7 minutes.Add the coconut mixture and salt to taste stirring carefully.Cook for 2 minutes till dry on a low heat. (If you prefer to make it little gravy type, add few teaspoons of yogurt and mix well, turn off flame immediately)Finally add curry leaves and coconut oil (optional) and switch off.Serve\u00a0Kerala Style Pacha Mango Avial Recipe\u00a0with\u00a0Steamed Rice,\u00a0Pachai Sundakkai Puli Kuzhambu Recipe (Turkey Berry Tamarind Based Gravy),\u00a0Cabbage Thoran (Poriyal) Recipe\u00a0to make a complete lunch meal."]'::jsonb, 40, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/Pacha_Mango_Aviyal.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/386.Pacha_Mango_Aviyal.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Perum Payaru Theeyal Recipe (Kerala Style Black Eyed Bean Curry)', 'perum-payaru-theeyal-recipe-kerala-style-black-eyed-bean-curry', 'Perum Payaru Theeyal Recipe is an aromatic Kerala style coconut based curry using cowpeas or black eyed beans. It is simple to prepare and makes use of few ingredients in hand. Black eyed beans are a wonderful source of soluble fiber, which helps in preventing type 2 diabetes by keeping blood sugar balanced. We will be using the red cow peas for this recipe.', '["1.5 cups Red Black Eyed Beans (Azuki)", "1/2 cup Fresh coconut , grated", "3 tablespoons Coriander (Dhania) Seeds", "4 Dry Red Chillies", "2 tablespoons Tamarind Paste", "Coriander (Dhania) Leaves , few sprigs, for garnish", "1 tablespoon Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'red black eyed beans (azuki)', 'coriander (dhania) leaves', 'coconut', 'dry red chillies', 'coriander (dhania) seeds', 'tamarind paste', 'sunflower oil']::text[], '["To begin the preparation of Perum Payaru Theeyal, dry roast the cow peas in a wok in medium heat till fragrant.", "This will take around 10 minutes.Now, cook the dry roasted red cow peas with 2 cups of water using a pressure cooker for 3 whistles and keep aside.Heat oil in small pan, add the dry chillies and coriander seeds and roast till fragrant.Add the grated coconut and roast until it turns light brown.Once the roasted mixture is cooled, grind it to a smooth paste with little water using a mixer grinder.Now bring the pressure cooker back on heat in which the red cow peas were cooked.Add the ground coconut paste, tamarind paste and mix well.", "Season with salt, simmer for 5 minutes and switch off the flame.Garnish with chopped coriander on top and serve the\u00a0Perum Payaru Theeyal along with steamed rice and beetroot thoran for a weekday lunch."]'::jsonb, 25, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Peru_Payaru_Theeyal_Recipe_Kerala_Style_Cow_Peas_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/387.Peru_Payaru_Theeyal_Recipe_Kerala_Style_Cow_Peas_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Beans Karam Recipe (Beans Curry)', 'beans-karam-recipe-beans-curry', 'Beans Karam is a side dish that uses beans and simple south indian spices to make a spicy gravy with notes of sour and sweet in it. Include this simple yet delectable recipe in your working week and also pack it into lunch boxes with chapathis.', '["500 grams Green beans (French Beans)", "2 Onions , chopped", "1 tablespoon Coriander (Dhania) Seeds", "1/2 teaspoon Cumin seeds (Jeera)", "4 Dry Red Chillies", "2 Byadagi Dried Chillies", "1 cup Fresh coconut , grated", "2 tablespoons Dessicated Coconut", "1 tablespoon Poppy seeds", "1 Tamarind , lemon ball sized", "2 tablespoons Jaggery", "1 tablespoon Turmeric powder (Haldi)", "Salt , to taste", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "10 Curry leaves", "1/4 teaspoon Asafoetida (hing)"]'::jsonb, ARRAY['salt', 'green beans (french beans)', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'jaggery', 'curry leaves', 'byadagi dried chillies', 'dry red chillies', 'onion', 'cumin seeds (jeera)', 'coriander (dhania) seeds', 'poppy seeds', 'turmeric powder', 'tamarind lemon']::text[], '["To begin making the Beans Karam recipe, roast coriander seeds, cumin seeds, chillies, dry coconut, poppy seeds and fresh coconut in a pan with little oil.Grind this mixture with tamarind extract, jaggery, 1/2 an onion and salt into a paste in a mixer grinder.Cook the beans till tender in a pan with some water.", "Heat oil in a heavy bottomed pan, add mustard seeds and let them crackle.Next, add hing, curry leaves, 1-1/2 onions with a pinch of salt and let it cook until transparent.Add turmeric powder, beans and saute for a minute.", "Add the ground masala paste to the pan and cook for 5 to 6 minutes while stirring in between.Add a cup of water and bring this to a boil.", "Adjust the seasoning and serve hot.Serve Beans Karam Recipe along with\u00a0Phulkas,\u00a0Steamed Rice and\u00a0Puli Manga Kuzhambu Recipe\u00a0for a complete meal."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Gauravi_Vinay/Beans_Karam.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/388.Beans_Karam.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Brinjal Mor Kuzhambu Recipe', 'brinjal-mor-kuzhambu-recipe', 'Brinjal Mor Kuzhambu Recipe, a variation to the regular Mor Kuzhambu. This one uses brinjals, in the curd based curry, with a tadka of mustard seeds, curry leaves and asafoetida that lend a lovely flavour to the dish.', '["3 Brinjal (Baingan / Eggplant) , cubed", "1 cup Tamarind Water", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "2 teaspoons Chana dal (Bengal Gram Dal)", "2 teaspoons Arhar dal (Split Toor Dal)", "2 teaspoons Rice", "2 cup Curd (Dahi / Yogurt)", "2 tablespoon Fresh coconut , pieces (adjust quantity according to taste)", "2 teaspoons Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Black Urad Dal (Split)", "3/4 teaspoons Methi Seeds (Fenugreek Seeds)", "8-10 Curry leaves", "5 Dry Red Chillies", "1 pinch Asafoetida (hing)"]'::jsonb, ARRAY['salt', 'arhar dal (split toor dal)', 'tamarind water', 'rice', 'brinjal (baingan eggsplant)', 'mustard seeds', 'asafoetida (hing)', 'black urad dal (split)', 'coconut ( quantity )', 'curd', 'curry leaves', 'dry red chillies', 'methi seeds (fenugreek seeds)', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making the Brinjal Mor Kuzhambu Recipe, soak the the dals -\u00a0chana dal, toor and rice in lukewarm water and rest it for at least 30 minutes.Once done grind the dals and rice with little water to a smooth paste and add coconut and curd and grind it again in the same mixer to a smooth paste and keep it aside.Heat a kadai with oil, add chopped brinjal, sprinkle with salt and turmeric and cook till it becomes soft.Pour in the tamarind water and allow it to cook for at least 15 minutes until the brinjal becomes quite mushy.Mix in the curd and the freshly ground dal-rice paste into the kadai and stir well, sprinkle salt and pour in some more water to adjust the consistency.Allow it to boil for at least 10 minutes until the raw smell of the rice and dal goes away.", "Switch off the heat and keep it aside.Heat a tempering pan with oil, add mustard seeds , urad dal and fenugreek seeds and allow it to sizzle.Add curry leaves and dry red chillies and allow it to crackle for few seconds.Sprinkle a pinch of hing at the end and pour this over the mor kuzhambu and serve hot.Serve the Brinjal Mor Kuzhambu Recipe along with steamed rice,\u00a0Beetroot Poriyal Recipe\u00a0or a\u00a0Chow Chow Thoran (Poriyal) Recipe\u00a0to make it a complete meal."]'::jsonb, 55, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Brinjal_Mor_Kuzhambu_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/389.Brinjal_Mor_Kuzhambu_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thor Chal Recipe - Banana Stem Pulao Recipe', 'thor-chal-recipe-banana-stem-pulao-recipe', 'Thor Chal or Banana Stem Pulao is a delicious dish that you can make for your everyday meals. Slightly sweet in taste, addition of banana stem into this pulao makes it even more healthy. Banana stem has lot of health benefits including healing acidity and gastric problems, managing cholesterol and blood pressure, treating kidney stones and UTI and many more.', '["1-1/2 cups Basmati rice , soaked in water for 15 minutes and drain the water", "Salt , to taste", "1/2 cup Banana Stem , finely chopped and boiled", "2 Bay leaf (tej patta)", "1 teaspoon Cinnamon Powder (Dalchini)", "2 tablespoons Ghee", "8 Cashew nuts", "8 Sultana Raisins", "Oil , as required", "1/4 cup Sugar , adjust according to your taste"]'::jsonb, ARRAY['cashew nuts', 'salt', 'sunflower oil', 'bay leaf (tej patta)', 'ghee', 'banana stemand', 'raisins', 'sugar', 'basmati rice drain the water', 'cinnamon powder (dalchini)']::text[], '["To begin making the Thor Chal recipe,\u00a0cook the banana stem along with a little salt in the pressure cooker with 2 tablespoons water for 2 to 3 whistles.", "Once cooked, turn off the heat and keep aside.Heat ghee in a heavy bottomed pan.", "Once it is slightly hot, add cooked banana stem and stir fry for a few minutes until it gets the flavors from ghee.", "Keep aside.Next, heat 1 tablespoon ghee in the same pan and add cashews.", "Saute the cashews till they become golden brown in colour.", "Ensure you roast on medium heat, so the cashews get roasted evenly.", "Once done, stir in the raisins and cinnamon powder, saute until it puffs up and turn off the heat.", "Into a pressure cooker, heat the remaining ghee over medium heat.Stir in the bay leaf, rice,\u00a0banana stem, salt, sugar and mix everything well.", "Add 2 cups water, cover the pressure cooker and let it cook till for 2 to 3 whistles and turn off the heat.", "Allow the pressure to release naturally.Once the Thor Chal is cooked, fluff up the rice and garnish it with raisins, cashews and cinnamon powder.", "Serve\u00a0Banana Stem Pulao\u00a0along with\u00a0Bengali Style Cholar Dal,\u00a0Chaal Kopi\u00a0and\u00a0Phulka\u00a0for your everyday meals."]'::jsonb, 60, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Affiliate-Articles/Banana_Stem_Pulao__Thor_Chal_original.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/390.Banana_Stem_Pulao__Thor_Chal_original.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kottambari Tambuli Recipe - Udupi Style Raw Coriander Kadhi', 'kottambari-tambuli-recipe-udupi-style-raw-coriander-kadhi', 'Tambuli''s are a summer coolers from the Udupi region of Karnataka and Kottambari Tambuli Recipe (Udupi Style Raw Coriander Kadhi) is a delicious variant. Usually, greens are sauteed with spices and ground to a smooth paste, and then added to thin buttermilk.', '["1 cup Curd (Dahi / Yogurt)", "1 cup Coriander (Dhania) Leaves , tightly packed, roughly chopped", "4 tablespoons Fresh coconut , grated", "1 Green Chilli", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon White Urad Dal (Split)", "1 Dry Red Chilli", "1 teaspoon Asafoetida (hing)", "2 teaspoons Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'green chilli', 'coconut', 'coriander (dhania) leaves', 'mustard seeds', 'asafoetida (hing)', 'dry red chilli', 'curd', 'white urad dal (split)', 'cumin seeds (jeera)', 'sunflower oil']::text[], '["To begin making\u00a0Kottambari Tambuli Recipe, whisk the yogurt to smooth consistency in a big bowl.", "Add about 3 cups of water, mix well and keep aside.Heat a teaspoon of oil in a small kadai, add the cumin seeds and let it splutter.Once they splutter, add the green chilli, coriander leaves and fry for a minute.Once cool, grind it to a smooth paste along with the grated coconut using a mixer grinder adding little water.Add this ground coriander mixture to the yogurt mixture and mix well.", "Add water to your desired consistency and season with salt.Now, to prepare the tadka, in a small tadka pan, heat the remaining oil, and add the mustard seeds once the oil is hot.Once they splutter, add the urad dal and stir a bit.", "Once they are golden in color and are fried, add the hing, dry red chilli, and stir.Once the hing seizes sizzling, switch off heat and pour this tadka over the Kottambari Tambuli.", "Serve the\u00a0Kottambari Tambuli Recipe\u00a0(Udupi Style Raw Coriander Kadhi) along with\u00a0Steamed Rice,\u00a0Udupi Style Bende Kayi Palya Recipe\u00a0or\u00a0Spicy Potato Roast Recipe\u00a0and\u00a0Karnataka Style Aralu Sandige Recipe\u00a0for a simple summer weekday lunch."]'::jsonb, 15, 'Udupi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Kottambari_Tambuli_Recipe_Udupi_Style_Raw_Coriander_Kadhi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/391.Kottambari_Tambuli_Recipe_Udupi_Style_Raw_Coriander_Kadhi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Narangi Pulao Recipe  - Orange Flavoured Rice', 'narangi-pulao-recipe-orange-flavoured-rice', 'Narangi Pulao Recipe is a refreshing citrusy pulao made with orange juice that has been freshly squeezed. The rice is further flavoured with whole spices like fennel seeds, cinnamon, star anise, cardamom.  The saffron added to the narangi pulao, gives it a lovely colour and rich flavour as well.', '["1 cup Rice", "1 tablespoon Ghee", "1 Star anise", "1 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung) , 2 cloves", "1 Cardamom (Elaichi) Pods/Seeds", "1/2 teaspoon Fennel seeds (Saunf)", "2 cups Fresh orange juice", "Saffron strands , a few", "1 tablespoon Milk", "Salt , to taste", "2 tablespoons Sugar"]'::jsonb, ARRAY['salt', 'cloves (laung) cloves', 'rice', 'ghee', 'cardamom (elaichi) podsseeds', 'fennel seeds (saunf)', 'saffron strands', 'milk', 'orange juice', 'sugar', 'cinnamon stick (dalchini)', 'star anise']::text[], '["To begin making Narangi Pulao Recipe wash the rice, and soak it in water.", "In a bowl, combine the saffron strands along with the milk and microwave for 1 minute.", "Remove and set aside.", "Heat a pressure cooker, with ghee on medium flame, add the whole spices -\u00a0star anise,\u00a0cinnamon stick,\u00a0cloves,\u00a0cardamom,\u00a0fennel seeds.", "Next add the washed and drained rice, freshly squeezed orange juice, saffron along with the milk, and salt.", "Close the pressure cooker and pressure cook for 2 whistles.", "Turn off the flame, and allow the pressure to release naturally.", "Open the cooker once the pressure has released, fluff the Narangi Pulao with a fork and mix in the sugar whilst its hot.", "Once done, transfer the\u00a0Narangi Pulao to a serving bowl and serve hot.Serve\u00a0Narangi Pulao along with\u00a0Awadhi Khaas Nihari Recipe\u00a0or\u00a0Awadhi Style Dal Masoor Musallam Recipe,\u00a0Boondi Raita Recipe, Pickled Onions, followed by a dessert of\u00a0Mango Sago Kheer Recipe - Sabudana Kheer With Mangoes."]'::jsonb, 35, 'Awadhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Narangi_Pulao_Recipe_Orange_Juice_Pulao-7_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/392.Narangi_Pulao_Recipe_Orange_Juice_Pulao-7_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharashtrain Amti Recipe', 'maharashtrain-amti-recipe', 'Maharashtrian Amti Recipe is one of the most simple yet flavourful recipes from the region. It is a traditional recipe and every Maharastrian family has their own way of making amti. A staple at mealtimes, amti is rather simple yet tasteful preparation of lentils (dal) that emerged from the Vidharbha region. It gets its distinct taste from being a gentle blend of spicy, a little sweet and a little tangy flavours. Amti-bhaat-bhaji (translated as lentil/dal, rice and vegetables) is served as a meal. A special masala called amti masala, quite similar to goda masala is used in making this amti. This recipe uses goda masala for convenience. Amti is best served with fresh steamed rice and a dollop of ghee.', '["1 cup Arhar dal (Split Toor Dal)", "1/2 teaspoon Turmeric powder (Haldi)", "3/4 cup Water", "2 teaspoon Maharashtrian Goda Masala", "20 grams Tamarind , in 2 tablespoon of water", "1/2 teaspoon Jaggery", "Salt , to taste", "Coriander (Dhania) Leaves , for garnish", "1 teaspoon Oil", "1 teaspoon Ghee", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Asafoetida (hing)", "1 sprig Curry leaves", "2 Green Chillies"]'::jsonb, ARRAY['arhar dal', 'split toor dal', 'turmeric powder', 'haldi', 'water', 'maharashtrian goda masala', 's tamarind', 'jaggery', 'salt', 'coriander', 'dhania', 'oil', 'ghee', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'asafoetida', 'hing', 'curry leaves', 'reen chillies']::text[], '["To begin making the Maharashtrian Amti recipe, first rinse dal in water thoroughly.", "Add \u00be cup water, turmeric powder and place it in pressure cooker to cook on a high heat.", "When you hear a whistle, turn the heat down and allow 2 more whistles to happen.", "Turn the heat off now and allow the pressure from the cooker to release gradually on its own.When you are able to uncover the cooker with ease, you will know the pressure has released fully.", "Mash the dal with the back of a ladle and mix it well to make a uniform, well cooked texture.", "Set it aside for use later.Place a kadai on the heat, add the mashed cooked dal to it and allow it to simmer on a low heat.", "At this stage, if the dal is too thick, add water to get the desired consistency.", "Once dal starts to boil, add goda masala, jaggery and tamarind juice.", "Stir well and let it cook on low heat for 10 minutes or until it is uniformly cooked.In a small tadka pan heat oil and ghee together.", "Add mustard seeds and allow them to crackle.", "Add cumin seeds, asafoetida, curry leaves, green chilies and saut\u00e9 for a minute.Add the tempering to the dal and switch off the flame.", "Garnish with fresh chopped coriander leaves and serve hot with fresh\u00a0steamed rice\u00a0and a dollop of ghee."]'::jsonb, 55, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Maharashtrain_Aamti.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/393.Maharashtrain_Aamti.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paplet Hooman Recipe - Goan Pomfret Curry', 'paplet-hooman-recipe-goan-pomfret-curry', 'We call Pomfret as Paplet in Goa and If you love Goan food, then Paplet Hooman/Pomfret Curry is a must to try out. This curry is coconut based curry where you prepare coconut paste by grinding together freshly grated coconut along with spices. It goes well with hot and steamy rice.', '["8 Pomfret fish , can substitute with any fish except shellfish and mackerels)", "1/2 cup Onion , finely chopped", "2 teaspoons Coconut Oil", "Salt , to taste", "3/4 cup Fresh coconut , freshly grated", "6 Dry Red Chillies , preferably byadgi", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander (Dhania) Seeds", "3 Whole Black Peppercorns", "Tamarind , lemon size"]'::jsonb, ARRAY['pomfret fish can substitute fish except shellfish mackerels)', 'salt', 'coconut', 'black peppercorns', 'dry red chillies preferably byadgi', 'coriander (dhania) seeds', 'onion', 'turmeric powder', 'coconut oil', 'tamarind lemon']::text[], '["To begin making the Paplet Hooman Recipe, wash Pomfret pieces well with water 3-4 times and add some salt.Mix and keep it aside for about 15-20 minutes.", "Grind together, ingredients mentioned for paste including fresh coconut, dry red chillies, turmeric powder, coriander powder, whole black peppercorns, tamarind using 1 cup water, to fine paste.In a medium saucepan kept on medium high heat, add coconut oil and fry onions till they are nicely darkened.You can substitute with olive oil or any oil, but try to use coconut oil for lovely aroma.Pour in the prepared coconut paste in browned onions, and also add slit chilies.Add some water to make it little runny.", "We prefer little thicker curry rather than runny.Let it come to complete boil and add pompano pieces.", "Mix gently.Cover and cook on medium heat for about 6 to 7 minutes.", "Remove cover and add salt.Gently mix and simmer on low heat for 5 more minutes.", "Check the fish if cooked properly using toothpick.They should feel soft.", "Do not overcook, otherwise, fish pieces will break and release bones in the curry.", "Serve hot.Serve\u00a0Paplet Hooman Recipe\u00a0along with\u00a0Steamed Rice\u00a0and\u00a0Rava Fried Prawns\u00a0for a weekday meal."]'::jsonb, 40, 'South Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/pompfret_fish_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/394.pompfret_fish_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Masoor Dal Gassi Recipe - Lentils in Tangy Coconut Curry', 'masoor-dal-gassi-recipe-lentils-in-tangy-coconut-curry', 'The Masoor Dal Gassi Recipe is a spicy, tangy gravy made with whole masoor dal with the skins on, is a typical Mangalorean specialty. Gassi is a staple curry in the Mangalore and Malnad areas of Karnataka that is essentially made of fresh spices ground down with coconut to form the base of the gravy.', '["3/4 cup Masoor Dal (Whole)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Ingredients to be ground to paste", "1/3 Fresh coconut , grated", "20 grams Tamarind", "3 Dry Red Chillies", "2 teaspoons Coriander (Dhania) Seeds", "Ingredients for Seasoning", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "3 cloves Garlic"]'::jsonb, ARRAY['salt', 'coconut', 'mustard seeds', 'cloves garlic', 'dry red chillies', 'coriander (dhania) seeds', 'tamarind', 'turmeric powder', 'masoor dal']::text[], '["To begin making the Masoor Dal Gassi Recipe, we will first cook the dal in the pressure cooker.", "Place the dal in the pressure cooker, add salt, turmeric powder and 2-1/2 cups of water.", "Cover the cooker, place the weight on and pressure cook for a couple of whistles.After a couple of whistles, turn the heat to low and simmer for about 4 minutes and turn off the heat.", "Allow the pressure cooker to rest until the pressure releases naturally.", "After the dal is cooked keep it aside.Our next step is to make the masala for the gassi.", "In a small frying pan, dry roast the coriander seeds and red chillies until fragrant.", "Once roasted, allow it to cool.Once cooled, place the roasted coriander, red chillies, coconut, tamarind and garlic into a blender.", "Add a little warm water and grind to make a smooth gassi masala paste.Add this masala, to the cooked dal mixture and bring the dal to a brisk boil for about 3 to 4 minutes.", "Adjust the consistency of the Moong Dal gassi, but adding a little water, as the mixture can thicken when the masala is added.", "The gassi is traditional is not in a liquid form but, if of a thick gravy consistency.Check the salt and spice levels and adjust to suit your taste.", "Transfer the Masoor Dal gassi to a serving bowl.The final step is to prepare the seasoning for the Masoor Dal gassi.", "Heat a small tadka pan on medium heat; add the mustard seeds and allow it to crackle.", "Add the garlic, red chillies and curry leaves and roast for a couple of minutes.Pour the seasoning over the Masoor Dal gassi and serve.Serve the Masoor Dal Gassi along with\u00a0Steamed Rice\u00a0topped with ghee,Kadalai Manoli\u00a0and\u00a0Dhangar Pachadi."]'::jsonb, 50, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Masoor_Dal_Ghassi_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/395.Masoor_Dal_Ghassi_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bihari Makhana Aur Matar Sabzi Recipe', 'bihari-makhana-aur-matar-sabzi-recipe', 'Makhana also known as Fox Nuts or Lotus Seeds, are a fasting food. They are largely grown in the state of Bihar in India, and used widely in its cuisine. Makhana are very nutritious with high amount of dietary fibres and proteins, hence it is good to include in our diets. Bihari Makhna Aur Matar Sabzi Recipe is a delicious side dish made with makhana and green peas. The panch phoran adds a beautiful flavour to the dish.', '["1 cup Phool Makhana (Lotus Seeds)", "1-1/2 cups Green peas (Matar) , blanched", "1 Onion , finely chopped", "5 Cloves (Laung) , roughly pounded", "1 Tomato , finely chopped", "1 Green Chilli , finely chopped", "1/2 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Fennel seeds (Saunf)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1/4 teaspoon Kalonji (Onion Nigella Seeds)", "2 teaspoon Coriander (Dhania) Leaves , finely chopped for garnish", "2 teaspoon Oil , or as required", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'kalonji (onion nigella seeds)', 'green chilli', 'mustard seeds', 'fennel seeds (saunf)', 'coriander (dhania) leaves', 'green peas (matar)', 'red chilli powder', 'onion', 'phool makhana (lotus seeds)', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'coriander powder', 'cloves (laung)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Bihari Makhna Aur Matar Sabzi Recipe, blanch the green peas in hot water and keep aside.Dry roast the makhana on medium heat for 5 minutes and keep aside.Heat oil in the same pan, add the pan poran masala, cumin, mustard, fenugreek, fennel and nigella seeds and saute till the spices become fragrant.Add the onions and saute until it turns translucent.Roughly pound the garlic cloves using a mortar and pestle and add it to the pan.", "Saute till the raw smell of the garlic goes away.Add the tomatoes, a pinch of salt and saute until the tomatoes turn mushy.", "Once the tomatoes are mushy add\u00a0 the red chilli powder, coriander powder and garam masala and mix well.Now add the blanched green peas, season with salt and cook for 3 minutes.", "Add the roasted makhana and mix well.Cook Bihari Makhna Aur Matar Sabzi for another 3 minutes, switch off the heat.", "Remove Bihari Makhna Aur Matar Sabzi into a serving bowl and garnish with the coriander leaves.Serve the\u00a0Bihari Makhna Aur Matar Sabzi Recipe along with\u00a0Phulkas\u00a0and\u00a0Kadhi Bari\u00a0for a delicious weeknight dinner."]'::jsonb, 17, 'Bihari', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Bihari_Makhana_Aur_Matar_Sabzi_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/396.Bihari_Makhana_Aur_Matar_Sabzi_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Palak Kichdi Recipe', 'palak-kichdi-recipe', 'Palak Kichdi is an one pot meal which is a delicious mix of vegetables, dal and rice with a twist. High in protein great for growing kids and easiest way to include your servings of greens for the day. Alternately you can even use quinoa or millets in place of rice to make it even more healthier.', '["1/2 cup Rice", "1/2 cup Pink Masoor Dal (Split)", "1 cup Spinach Leaves (Palak) , tightly packed and cleaned", "1 tablespoon Garlic , finely chopped", "1 Onion , finely chopped", "1/4 cup Green peas (Matar)", "1/3 cup Broccoli , florets cleaned", "50 grams Tofu , diced", "1 inch Cinnamon Stick (Dalchini)", "1/2 teaspoon Cumin seeds (Jeera)", "1 Bay leaf (tej patta)", "2 Green Chillies , slit", "3 cloves Garlic , cut into strips", "1/4 teaspoon Turmeric powder (Haldi)", "2 pinch Asafoetida (hing)", "1/2 teaspoon Garam masala powder , (optional)", "1/2 Tomato , sliced", "Ghee , or oil as required"]'::jsonb, ARRAY['rice', 'pink masoor dal', 'split', 'spinach leaves', 'palak', 'garlic', 'onion', 'green peas', 'matar', 'broccoli', 's tofu', 'cinnamon stick', 'dalchini', 'cumin seeds', 'jeera', 'bay leaf', 'tej patta', 'reen chillies', 's garlic', 'turmeric powder', 'haldi', 'asafoetida', 'hing', 'garam masala powder', 'tomato', 'ghee']::text[], '["To begin making the Palak Kichdi recipe, In a pressure cooker add rice, dal, broccoli, peas, turmeric, one pinch of hing, little oil and 2 -1/2 cups of water and pressure cook.In a saucepan, bring water to a boil and add the cleaned spinach leaves and let it sit for a minute in the pot while the flame is still on.", "Now drain it in a colander and transfer it into a bowl of cold water.", "Once its cool grind it to a paste in a mixer grinder and set aside.In a wide pan, heat some oil and add bay leaf, jeera, chopped garlic, pinch of hing, green chillies, chopped onions and saute it until the onions have started to change colour to this mixture.Once it is done, add the pureed spinach and mix everything properly.Lower the flame, add the cool dal and rice mixture into the pot and mix until combined with the palak mixture, add the chopped tofu, some water if necessary and season with salt.Also add the garam masala if using at this stage.", "Cook for 2-3 minutes and turn of the flame.In a tadka pan, add some ghee/oil add sliced garlic and cook till its starts to brown, pour this onto the khichdi.Garnish with sliced tomatoes and it is ready to be served.", "Serve Palak Kichdi with\u00a0Lauki Raita,\u00a0Avocado Raita\u00a0or any other raita of your choice for a comforting weekday meal."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Gauravi_Vinay/Palak_Kichdi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/397.Palak_Kichdi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Corn Pulao Recipe', 'corn-pulao-recipe', 'Corn Pulao is a simple and flavorful dish which is very easy to prepare. The herbs and spices make it a very aromatic dish, with the added goodness of corn.', '["1 cup Basmati rice", "2 cup Water", "2 Cardamom (Elaichi) Pods/Seeds", "1 Bay leaves (tej patta)", "2 Whole Black Peppercorns", "2 tablespoon Ghee", "1 tablespoon Oil", "1 tablespoon Cumin seeds (Jeera)", "1 Onion", "1/2 tablespoon Ginger , paste", "1/2 tablespoon Garlic , paste", "1 cup Sweet corn , boiled", "6-7 Baby corn , sliced", "1/4 tablespoon Coriander Powder (Dhania)", "1/4 Cumin powder (Jeera)", "1/2 tablespoon Turmeric powder (Haldi)", "1 tablespoon Red Chilli powder", "1 tablespoon Garam masala powder", "1/2 cup Homemade tomato puree", "4 sprig Coriander (Dhania) Leaves , chopped", "Salt , taste", "3-4 tablespoon Fresh cream"]'::jsonb, ARRAY['basmati rice', 'water', 'cardamom', 'elaichi', 'bay leaves', 'tej patta', 'whole black peppercorns', 'ghee', 'oil', 'cumin seeds', 'jeera', 'onion', 'ginger', 'garlic', 'sweet corn', 'baby corn', 'coriander powder', 'dhania', 'cumin powder', 'turmeric powder', 'haldi', 'red chilli powder', 'garam masala powder', 'homemade tomato puree', 'coriander', 'salt', 'fresh cream']::text[], '["To begin making the Corn Pulao Recipe, take rice cooker or sauce pan, add rice and water.Then, add 1 tablespoon ghee, cloves, cinnamon, cardamom, bay leaf, peppercorn, salt and\u00a0boil till the rice is cooked fully.", "Drain if there is any excess water remaining after boiling.", "Keep the rice aside.Heat oil in a heavy bottomed pan.", "Add cumin seeds to the oil and\u00a0when cumin seeds start to splutter, add the onion and\u00a0saute it till it turns golden brown.", "Now, add ginger-garlic paste,\u00a0boiled corn, baby corn and salt.", "Let it cook for 2 minutes.Now, add the dry spices, start with cumin seeds powder, coriander powder, red chilli powder, turmeric powder and garam masala powder.", "Let it cook for about 2 minutes.Mix it well and add tomato puree,\u00a0cook it for another 2-3 minutes then add cream\u00a0and turn off the flame.Take a baking dish, layer the vegetables first and then the rice.", "Sprinkle one tablespoon ghee on top and fresh coriander.Cover it with aluminium foil and keep it in a preheated oven at 180 degree for about 10 minutes.", "Once done, take it out and it is ready to be served.The\u00a0Corn Pulao\u00a0can be served with\u00a0Paneer Butter Masala,\u00a0Butter Naan\u00a0and\u00a0Lauki Raita\u00a0to make a complete dinner meal.", "It is also a convenient dish to prepare when you have a lot of guests at home."]'::jsonb, 55, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Corn_Pulao.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/398.Corn_Pulao.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kasuri Methi Mach Recipe - Dry Fenugreek Flavoured Fish Curry', 'kasuri-methi-mach-recipe-dry-fenugreek-flavoured-fish-curry', 'This fish dish, we try when we are in hurry and have to cook an elaborate meal for all. This fish dish needs very little time to cook and can be prepared with very few ingredients. All you need is fresh carp (rohu or katla) as fish pieces are not fried before cooking.', '["8 Rohu fish , or Katla or Any Carp", "100 grams Curd (Dahi / Yogurt)", "2 tablespoons Kasuri Methi (Dried Fenugreek Leaves)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Ginger , paste", "1/2 teaspoon Garlic , paste", "1/4 teaspoon Garam masala powder", "1/2 teaspoon Sugar", "2 teaspoons Mustard oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard oil', 'curd', 'sugar', 'ginger paste', 'rohu fish katla carp', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'garam masala powder', 'garlic paste']::text[], '["To begin making the\u00a0Kasuri Methi Mach recipe, firstly wash and marinate the fish pieces with turmeric, lemon juice and salt for 15-20 minutes.", "This is our first marination.Drain out the excess marination.", "Beat the yogurt very well adding salt and sugar.", "Now add garlic paste, ginger paste and fish pieces.", "Marinate again for another 15 minutes.Heat oil in a kadai or a heavy bottomed pan.", "Now add half of kasuri methi.", "Make a quick stir.Now add the marinated fish with all marination.", "Cover and cook till the fish pieces are done.", "It will take around 8-10 minutes.Sprinkle garam masala powder.", "Mix well.", "Crush the rest of the kasuri methi between your palms and sprinkle on the cooked fish curry.", "Remove from fire and let it rest for another 5 minutes.Serve\u00a0Kasuri Methi Mach along with\u00a0Steamed Rice\u00a0and\u00a0Bengali Style Sheem Poshto\u00a0for a weekday meal."]'::jsonb, 45, 'Bengali', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pal.rini1-gmail.com/Kasuri_Methi_Mach_Dry_Fenugreek_Flavoured_Fish_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/399.Kasuri_Methi_Mach_Dry_Fenugreek_Flavoured_Fish_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Restaurant Style Green Peas Masala Recipe', 'restaurant-style-green-peas-masala-recipe', 'Restaurant Style Green Peas Masala is a delicious side dish which can be paired with any kind of Indian bread as well as jeera rice or ghee rice. This is a very simple recipe, though the list of ingredient is a little long but most of the ingredients are easily available in our kitchen.', '["1 cup Green peas (Matar)", "3 Onions , ground into a paste", "5 cloves Garlic , finely chopped", "2 Green Chillies", "1-1/2 teaspoon Ginger , finely chopped", "2 Tomatoes , pureed", "1/2 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "Salt , to taste", "1/2 teaspoon Sugar", "Coriander (Dhania) Leaves , finely chopped", "6 Cashew nuts", "2 tablespoons Curd (Dahi / Yogurt)", "1/2 inch Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "2 Cloves (Laung)", "1 Bay leaf (tej patta)", "2 tablespoons Oil", "1 tablespoon Butter (Salted)"]'::jsonb, ARRAY['tomato', 'cumin powder (jeera)', 'coriander (dhania) leaves', 'cloves garlic', 'onion', 'turmeric powder', 'green chillies', 'sunflower oil', 'salt', 'cardamom (elaichi) podsseeds', 'garam masala powder', 'red chilli powder', 'curd', 'sugar', 'butter', 'cashew nuts', 'ginger', 'bay leaf (tej patta)', 'green peas (matar)', 'cinnamon stick (dalchini)', 'coriander powder', 'cloves (laung)']::text[], '["To begin making Restaurant Style Green Peas Masala, we have to first cook the peas.", "Pressure cook the green peas along with 2 tablespoons water for 1 whistle.", "Release the pressure of the cooker immediately.", "Keep the cooked peas aside.", "Meanwhile, soak cashew nuts in warm water for 15 minutes.", "Once the cashews have softened, add them to a mixer and grind them along with curd to make a smooth paste.In a heavy bottomed pan, heat oil on medium flame.", "Once the oil is hot, reduce it to a low flame, add bay leaf, cinnamon stick, cardamom and cloves.Once the aroma of the spices start wafting in the air, add chopped garlic & ginger and saut\u00e9 until the raw smell goes away.", "This will take about a minute or two.Next, add onion paste, tomato puree and saute until the raw smell of onions goes away.", "This will take about 5 minutes.", "Then add all the dry spice powders including turmeric powder, cumin powder, coriander powder, garam masala powder, red chilli powder and salt to taste.Mix them well and add 2 tablespoons of water to the mixture to avoid burning of the spices.Once the spices are well cooked, add required water to get the required consistency of your choice.", "Boil for 3 to 4 minutes.Next, add the cashew-curd mixture (paste) and stir continuously for the proper mixing of ingredients.Now ,add the cooked peas and let the Green Peas Masala cook on a low flame for 5 minutes.Finally, switch off the gas and add a dollop of butter and chopped coriander leaves on top.Serve\u00a0Restaurant Style Green Peas Masala with Phulkas or Tawa Paratha along with a Cauliflower and Cucumber Raita\u00a0for your everyday meals."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jhumu.here-gmail.com/Restaurant_style_Green_Peas_Masala.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/400.Restaurant_style_Green_Peas_Masala.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false);

INSERT INTO public.recipes (
  title, slug, description, ingredients, cleaned_ingredients,
  instructions, total_time_mins, cuisine, diet, source_url,
  image_url, image_status, image_source, data_source, servings, review_count, is_featured
) VALUES
  ('Karnataka Style Chicken Saaru Recipe', 'karnataka-style-chicken-saaru-recipe', 'Karnataka Style Chicken Saaru Recipe is a spicy thick gravy that is cooked in a pressure cooker. Saaru refers to any gravy dish in Karnataka. This is the best to be had along with Ragi Mudde or just with Plain dosa. The saaru consists of roasted spices and onions which are ground into to a smooth paste and then cooked along with chicken pieces.', '["300 grams Chicken , with Bone", "1 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Oil", "2 Onions , roughly chopped", "2 tablespoons Fresh coconut , grated", "4 cloves Garlic", "1 inch Ginger , chopped", "1 inch Cinnamon Stick (Dalchini)", "4 Cloves (Laung)", "4 Dry Red Chilli", "1 tablespoon Poppy seeds"]'::jsonb, ARRAY['salt', 'ginger', 'coconut', 'red chilli powder', 'cloves garlic', 'dry red chilli', 'onion', 'chicken', 'cinnamon stick (dalchini)', 'poppy seeds', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Karnataka Style Chicken Saaru Recipe, we will first make the masala for the saaru.", "Heat a small skillet on medium-low flame, add the poppy seeds and dry roast them.", "Once the poppy seeds are roasted, add in the cloves, cinnamon and dry red chilli and roast them well.", "Turn off the flame and keep it aside.Heat another pan on medium flame, add a tablespoon of oil, add ginger, garlic, onions and saute until the onions turn translucent.Add grated coconut and saute well till they turn light brown.", "Turn off the flame.In a mixer-jar, combine the dry roasted spices along with ginger-garlic-onion mixture, grind to a smooth paste along with some water.", "Transfer to a bowl and set aside.", "Heat oil in the pressure cooker over medium heat, add the chicken, turmeric powder,salt and red chilli powder.", "Roast the chicken in the pan for about 5 minutes until the chicken begins to get a roasted texture and is getting partially cooked.", "After 5 minutes of roasting the chicken, add the ground saaru masala (onion coconut & spices paste) and give it a stir.", "Check for salt and add 1 cup of water and pressure cook for about 3 to 4 whistles until the chicken is cooked and turn off the heat.Allow the pressure to release naturally.", "Open the cooker and check for spices and salt and adjust accordingly.Serve the Karnataka Style Chicken Saaru Recipe along with\u00a0Ragi Mudde,\u00a0Akki Roti\u00a0or\u00a0Jolada Rotti\u00a0to enjoy it for your lunch."]'::jsonb, 55, 'Karnataka', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Karnataka_Style_Chicken_Saaru_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/401.Karnataka_Style_Chicken_Saaru_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Davva Aava koora Recipe (Sweet and Spicy Banana Stem Peanut Curry Recipe)', 'andhra-style-davva-aava-koora-recipe-sweet-and-spicy-banana-stem-peanut-curry-recipe', 'Andhra Style Davva Aava koora Recipe (Sweet and Spicy Banana Stem Peanut Curry Recipe) is an Indian curry made from Banana stem and crunchy peanuts tossed in sweet and spicy Andhra style gravy. Banana Stem Banana Stem is a local ingredient in Tamil Nadu which is prepared in most of their house hold. Banana Stem is very fibrous and diabetic friendly ingredient. It helps to solve any gastric problems in the body.', '["300 grams Banana Stem , cut into small diced and soaked in butter milk", "1 cup Raw Peanuts (Moongphali)", "1/2 cup Pearl onions (Sambar Onions) , finely chopped", "3 cloves Garlic , smashed", "1 cup Tomato , cut into small pieces", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Sambar Powder", "1 teaspoon Sugar", "1 Bay leaf (tej patta) , torn", "1 sprig Curry leaves , roughly torn", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Oil", "Salt , to taste", "1 teaspoon White Urad Dal (Split)", "1 teaspoon Chana dal (Bengal Gram Dal)", "1 Dry Red Chilli", "2 sprig Coriander (Dhania) Leaves"]'::jsonb, ARRAY['tomato', 'salt', 'banana stem butter milk', 'chana dal (bengal gram dal)', 'bay leaf (tej patta)', 'mustard seeds', 'red chilli powder', 'cloves garlic', 'dry red chilli', 'pearl onion (sambar onion)', 'sugar', 'curry leaves', 'white urad dal (split)', 'methi seeds (fenugreek seeds)', 'peanuts (moongphali)', 'coriander (dhania) leaves', 'turmeric powder', 'sambar powder', 'sunflower oil']::text[], '["We begin making the Andhra Style Davva Aava koora Recipe (Sweet and Spicy Banana Stem Peanut Curry Recipe) by heating the pressure cooker with oil, roast the bay leaf and splutter the mustard seeds and fenugreek seeds.Then add the curry leaves, add in the smashed garlic, add the small onions and saute till it is translucent.Once done you can add the chopped tomatoes and saute till it is smashed.", "Add all the spice powders and sugar give it a toss.Finally add the banana stem and peanuts inside the pressure cooker with 1 cup water for about 2 whistle.", "Release the pressure naturally.In order to temper, heat a small skillet and splutter urad dal, channa dal and dry red chilli and add it to the gravy and give it a stir.", "Serve the Andhra Style Davva Aava koora Recipe (Sweet and Spicy Banana Stem Peanut Curry Recipe) with steam rice or with\u00a0Chapathi\u00a0to enjoy your\u00a0Lunch meal."]'::jsonb, 45, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Andhra_Style_Davva_Aava_koora_Recipe_Sweet_and_Spicy_Banana_Stem_Peanut_Curry_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/402.Andhra_Style_Davva_Aava_koora_Recipe_Sweet_and_Spicy_Banana_Stem_Peanut_Curry_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Crispy Crab Rangoons Recipe', 'crispy-crab-rangoons-recipe', 'Crab Rangoons or crab wontons are crispy American Chinese snack prepared by wrapping chinese wontons with crab meat, scallions, cream cheese, with some ginger or garlic and then deep fried. This makes a perfect starter for your house parties and can be served with dip of your choice. So next time, you having a house party, surprise your friends and family with these delicious and mouth watering wontons.', '["20 Wonton wraps , (3\u2033 Square)", "Oil , for deep frying", "1/4 cup Crab meat", "1/4 teaspoon Ginger , grated", "1 tablespoon Onion , finely chopped", "1/2 teaspoon Carrot (Gajjar) , grated", "1/4 cup Britannia Cream Cheese , softened", "1/2 teaspoon Sugar", "1/4 teaspoon Soy sauce"]'::jsonb, ARRAY['cheese', 'ginger', 'britannia', 'soy sauce', 'carrot', 'crab meat', 'sugar', 'onion', 'wonton wraps (″ square)', 'sunflower oil']::text[], '["To begin making the Crispy Crab Rangoons, mix all ingredients mentioned under ''for filling'' until they are well combined in a bowl.", "Cover and refrigerate at least for 1 hour, up to overnight.Take one of the wonton wraps and put a teaspoon full of this filing in the center.", "Using some water, moisten the center of each side.Bring together the adjacent sides and then all together into the middle.Heat oil in a pan to boiling temperature.", "Fry each of these rangoons both the sides, till crispy.Lay then down on a paper towel to drain excess heat and serve immediately.Serve\u00a0Crispy Crab Rangoons along with other starters like\u00a0Rajma Malai Cutlet\u00a0and\u00a0Congress Buns\u00a0for your house party."]'::jsonb, 80, 'Indo Chinese', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/Crispy_Crab_Rangoons.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/403.Crispy_Crab_Rangoons.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer Butter Masala Biryani Recipe', 'paneer-butter-masala-biryani-recipe', 'Paneer Butter Masala Biryani Recipe, is a delicious vegetarian biryani, made making a creamy paneer butter masala and cooking it in a single pot. Serve this to your guests at your house parties, or make it for a Sunday brunch for your family.', '["3 tablespoons Butter (Unsalted)", "2 inch Ginger , finely chopped", "8 cloves Garlic , finely chopped", "2 Onions , thinly sliced", "3 Brown cardamom (Badi Elaichi)", "1 cup Homemade tomato puree", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Kashmiri Red Chilli Powder", "1 teaspoon Garam masala powder", "1 teaspoon Coriander (Dhania) Powder", "Salt , to taste", "1 teaspoon Jaggery", "1/4 cup Fresh cream", "200 grams Paneer (Homemade Cottage Cheese) , cut into cubes", "1/4 cup Mint Leaves (Pudina) , chopped", "1-1/4 cups Water"]'::jsonb, ARRAY['s butter', 'unsalted', 'ginger', 's garlic', 'onions', 'brown cardamom', 'badi elaichi', 'homemade tomato puree', 'turmeric powder', 'haldi', 'kashmiri red chilli powder', 'garam masala powder', 'coriander', 'dhania', 'salt', 'jaggery', 'fresh cream', 's paneer', 'homemade cottage cheese', 'mint leaves', 'pudina', 's water']::text[], '["To begin making the\u00a0 Paneer Butter Masala Biryani Recipe, prep all the ingredients and keep ready.In a large biryani pot or a cooking pan, heat butter medium heat, add the ginger, garlic and onions.", "Allow the onions turn soft and golden brown.Stir in the badi elaichi, tomato puree, turmeric powder, red chilli powder, coriander powder,\u00a0garam masala powder, jaggery and salt.", "Mix well and bring the tomato gravy to a brisk boil.", "When the gravy begins to boil, add in the paneer pieces and fresh cream.", "Mix well, and ensure that you are left with a thick semi coating masala on the paneer.Stir in a handful of mint leaves that is roughly chopped,\u00a01-1/2 cups washed basmati rice and stir well to combineAdd 1-1/4 cups of water and allow the Paneer Butter Masala Biryani to come to a boil.", "Once it comes to a boil, turn the heat to low,\u00a0cover the pan cook until all the water is absorbed.Once all the water is absorbed, turn off the heat and allow the biryani to rest for 10 minutes before giving it a stir.", "Gently stir more pudina leaves and serve the Paneer Butter Masala Biryani warm along with raita.Serve Paneer Butter Masala Biryani Recipe,\u00a0along with\u00a0Onion Raita\u00a0for a simple meal.", "Finish this simple yet delicious meal with\u00a0Kesar Shahi Tukda With Rabri Recipe (Saffron Bread Pudding With Spiced Milk Custard)."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Paneer_Butter_Masala_Biryani_Recipe_6_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/404.Paneer_Butter_Masala_Biryani_Recipe_6_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Fish Molee Recipe - Kerala Style Fish Curry', 'fish-molee-recipe-kerala-style-fish-curry', 'Fish Molee is one traditional Kerala Cuisine based Fish Stew recipe. The addition of coconut milk and exotic spices gives a nice aromatic and light sense to it. Kerala Style Fish Molee goes perfectly with Steamed Rce to enjoy a weekday meal.', '["300 gram Fish", "3 teaspoon Oil", "1/2 teaspoon Cumin seeds (Jeera)", "1 Onion , chopped", "1 teaspoon Ginger , paste", "2 Tomatoes , chopped", "3 cloves Garlic , finely chopped", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Vinegar", "1/4 Lemon juice", "50 ml Coconut milk", "Salt , to taste"]'::jsonb, ARRAY['gram fish', 'tomato', 'coconut milk', 'salt', 'red chilli powder', 'cloves garlic', 'onion', 'cumin seeds (jeera)', 'vinegar', 'lemon', 'ginger paste', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Fish Molee Recipe, firstly wash the fish cutlet pieces and season with salt.", "In a heavy bottomed pan, heat some oil on medium flame.", "Add cumin seeds and let it crackle.", "Add chopped onion and saute until the onions are translucent.", "Add garlic, ginger paste and saute until the raw smell of garlic and ginger goes away.Add in the chopped tomatoes and saute until the tomatoes are mushy and oil starts to leave from the sides.", "This will take 3 to 4 minutes.After 3 to4 minutes add in turmeric powder and red chili powder, mix well and pour a cup of water into the pan.", "Once the water reaches the boiling point, lower the flame, add coconut milk and the fish pieces.When the fish is fully cooked, add lime juice and vinegar.", "Add appropriate amount of salt and give the curry a good stir.", "Turn off the flame.Serve\u00a0Fish Molee\u00a0along\u00a0with\u00a0Appams\u00a0or\u00a0Steamed Rice\u00a0for a simple weekday Lunch.", "You can also make it for your weekend Lunch with other Kerala recipes."]'::jsonb, 35, 'Kerala', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/ruby_pathak-yahoo.com/Fish_Molee.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/405.Fish_Molee.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gulkand Seviyan Kheer Recipe', 'gulkand-seviyan-kheer-recipe', 'Gulkand Seviyan Kheer Recipe is a lip smacking kheer recipe with prominent flavours of rose. The fragrant kheer, is a creamy rich preparation, with hidden notes of cardamom and a little crunch from the pistachios added to it.', '["1-1/2 liter Milk , full fat", "70 grams Thin Semiya (Seviyan)", "1/2 teaspoon Cardamom Powder (Elaichi)", "1/3 cup Gulkand", "Saffron strands , a few", "6 Pistachios , chopped", "Rose water , as required", "Dried rose petals , for garnish"]'::jsonb, ARRAY['pistachios', 'saffron strands', 'rose water', 'dried rose', 'gulkand', 'semiya (seviyan)', 'milk full fat', 'cardamom powder (elaichi)']::text[], '["To begin making the Gulkand Seviyan Kheer Recipe\u00a0in a saucepan bring the milk to a rolling boil.", "Once the milk has boiled, reduce the flame, and allow the milk to simmer on low flame, until it reduces to half its quantity.", "This process will take a good 20 minutes.", "Ensure the milk is stirred occasionally to prevent the bottom of the pan burning the milk.", "It is also always a good idea to keep a ladle inside the milk container.", "Once the milk is reduced, add the cardamom powder, and a few strands of saffron.", "Next, to this add the gulkand and mix vigorously until it melts and comes together along with the milk.", "Adjust the sweetness of the gulkand kheer, based on the sweetness of the gulkand, if required add sugar to suit your taste.", "Since the gulkand is already packed with the rose flavour, depending on how strong or mild you prefer, add the rose water, according to how aromatic you like the gulkand kheer to be.", "Finally, add in the thin seviyan and wait until the\u00a0seviyan wilts down and becomes soft.", "Turn off the heat, transfer the\u00a0Gulkand kheer to a serving bowl and garnish with some crushed pistachios and dry rose petals.", "Serve\u00a0Gulkand Seviyan Kheer as dessert or part of a meal that consists of\u00a0Ajwain Puri Recipe, and\u00a0Aloo Tamatari Recipe\u00a0for a lovely comforting Sunday brunch."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/sevian_gulkand_kheer_recipe_8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/406.sevian_gulkand_kheer_recipe_8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pumpkin Peas Palya Recipe', 'pumpkin-peas-palya-recipe', 'Pumpkin Peas Palya is easy and simple. Also called as Pumpkin Peas Curry, it is slightly sweet, tangy and spicy. It’s a delicious treat for all the pumpkin lovers. We have used coconut oil and grated coconut to give an authentic flavour of coastal Karnataka.', '["1-1/2 cup Kaddu (Parangikai/ Pumpkin) , cubed", "1/2 cup Green peas (Matar) , cooked", "2 tablespoon Fresh coconut , grated", "2 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Garam masala powder", "2 teaspoons Red Chilli powder", "1 tablespoon Coconut Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Chana dal (Bengal Gram Dal)", "5 Curry leaves", "2 cups Water", "Salt , as per taste"]'::jsonb, ARRAY['salt', 'parangikai pumpkin', 'amchur (dry mango powder)', 'coconut', 'mustard seeds', 'green peas (matar)', 'red chilli powder', 'water', 'curry leaves', 'coconut oil', 'chana dal (bengal gram dal)', 'garam masala powder']::text[], '["To begin making Pumpkin Peas Palya Recipe, take a vessel and boil water.", "Now add pumpkin cubes and cook for 5 to 10 minutes or until they are half cooked.", "Strain water and keep this aside.Heat a heavy wok, add oil.", "Now add mustard seeds and saute well until it splutters.Now add chana dal, fry until they turn golden.", "Add curry leaves, fry for few seconds.Now add the cooked pumpkin cubes and cooked peas.", "Add amchur powder, garam masala and red chili powder, mix well.", "Let it cook for about a minute.Now add salt, grated coconut, and mix.", "Close and cook for 3-5 minutes.", "Serve\u00a0Pumpkin Peas Palya\u00a0along with\u00a0Tomato Onion Sambar\u00a0and\u00a0Steamed Rice\u00a0for a weekday meal.", "You can also serve\u00a0Curry Leaves Buttermilk\u00a0with this meal."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pavithrahr-gmail.com/Pumpkin_Peas_Palya_or_Dry_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/407.Pumpkin_Peas_Palya_or_Dry_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Kathirikai Chops Recipe - Brinjal Curry for Biryani', 'chettinad-kathirikai-chops-recipe-brinjal-curry-for-biryani', 'A lip smacking robust spicy dish, the Chettinad Kathirikai Chops gets its aroma from the freshly roasted and ground spices. Although it can be served with Chapatis or Jeera Rice, the brinjal chops served with biryani is a match made in heaven.', '["5 Small Brinjal (Baingan / Eggplant)", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoons Garam masala powder", "2 teaspoons Red Chilli powder", "2 teaspoons Jaggery", "1 tablespoon Tamarind Paste", "2 Tomatoes , finely chopped", "Salt , to taste", "To be ground into a paste", "2 tablespoons Black sesame seeds", "2 tablespoons Raw Peanuts (Moongphali)", "2 teaspoon Cumin seeds (Jeera)", "1 inch Ginger", "6 cloves Garlic", "2 Onions , sliced", "2 Green Chillies", "To Temper", "1 tablespoon Gingelly oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 pinch Asafoetida (hing)", "2 sprig Curry leaves"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'mustard seeds', 'brinjal (baingan eggsplant)', 'black sesame seeds', 'asafoetida (hing)', 'jaggery', 'red chilli powder', 'cloves garlic', 'curry leaves', 'onion', 'cumin seeds (jeera)', 'peanuts (moongphali)', 'tamarind paste', 'gingelly oil', 'turmeric powder', 'green chillies', 'garam masala powder']::text[], '["To begin making the Chettinad Kathirikai Chops, wash and cut the brinjals into wedges and soak it a bowl of salted water.", "In a small pan on medium flame, dry roast the cumin seeds, black sesame seeds and peanuts until fragrant.", "Turn off the flame and allow it to cool.In a mixer jar, grind the roasted cumin seeds, sesame seeds, peanuts, ginger, garlic, green chilies and onions into a fine paste using little water.", "Set aside.Moving ahead, in a heavy bottomed pan, heat oil on medium flame, add the mustard seeds and let them crackleAdd asafoetida, and curry leaves.", "Saute for a few minutes until the curry leaves stop crackling.", "Add the ground masala, turmeric powder, garam masala powder, red chilli powder and salt.", "Mix well.", "Add the drained brinjal wedges, tomatoes, cover and cook on low flame for 2 minutes.Open the lid, add the jaggery, tamarind pulp, half a cup of water and bring to a boil.", "Adjust water to the required consistency.", "Cover and cook on low flame for 12-15 minutes, until the Brinjals are completely cooked and begin to become mushy.", "Turn off the flame.", "Serve Chettinad Kathirikai Chops along with\u00a0Hyderabadi Biryani With Basmati Rice (Mutton & Chicken)\u00a0or\u00a0Ambur Star Chicken Biryani Recipe\u00a0and\u00a0Sweet & Spicy Coriander Tadka Raita\u00a0for a complete Biryani meal."]'::jsonb, 40, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sneha-archanaskitchen.com/Chettinad_Kathirikai_Chops_Recipe_Brinjal_Chops__1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/408.Chettinad_Kathirikai_Chops_Recipe_Brinjal_Chops__1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kabuli Chana Rasam Recipe', 'kabuli-chana-rasam-recipe', 'Channa Rasam is a lip smacking rasam which is made with the goodness of channa water, which is the water obtained in the process of boiling chickpeas.', '["2 Tomatoes", "1 tablespoon Kabuli Chana (White Chickpeas) , boiled", "1 cup Chana stock , (water in which channa was boiled)", "1-1/2 teaspoons Lemon juice", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , as per required", "1/4 teaspoon Asafoetida (hing)", "2 teaspoons Coriander (Dhania) Leaves , finely chopped", "1 teaspoon Ghee", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 clove Garlic , finely chopped", "5-6 Curry leaves", "5-6 Curry leaves", "1/2 teaspoon Whole Black Pepper Corns", "1-1/2 Cumin seeds (Jeera)", "2 Dry Red Chillies"]'::jsonb, ARRAY['tomato', 'salt per', 'asafoetida (hing)', 'coriander (dhania) leaves', 'ghee', 'mustard seeds', 'black pepper corns', 'cloves garlic', 'curry leaves', 'kabuli chana (white chickpeas)', 'dry red chillies', 'lemon', 'cumin seeds (jeera)', 'turmeric powder', 'chana stock (water which channa was )']::text[], '["To begin with Kabuli Chana Rasam, grind tomatoes to a paste and dilute it with 2 cups of water.Add turmeric powder, hing and salt to this, transfer to a saucepan and bring to a rolling boiling till the raw smell vanishes.To make the fresh rasam masala, in a mixer-jar combine black peppercorns, cumin seeds, curry leaves and dried red chillies.", "Grind to a coarse masala.", "Mash coarsely the boiled chana and add the freshly ground rasam masala, boiled chana and the 1 cup of chana stock and boil until the rasam froths up.", "Heat one teaspoon of ghee in a tadka pan, add mustard seeds and allow it to splutter.", "Once it splutters, add finely chopped garlic pieces and curry leaves.", "Pour this tempering over the boiling rasam.", "Turn off the flame.", "Serve Channa Rasam with steamed rice with a dollop of ghee and\u00a0Elai\u00a0Vadam,\u00a0Chow Chow Pasiparuppu Poriyal Recipe (Chayote Squash And Moong Stir Fry)\u00a0and\u00a0Pudina Buttermilk Recipe."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Sowpernica/Channa_Rasam_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/409.Channa_Rasam_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('North Indian Chawli ki Sabzi Recipe | Yard Long Beans | Barbati | Karamani', 'north-indian-chawli-ki-sabzi-recipe-yard-long-beans-barbati-karamani', 'North Indian  Chawli ki Sabzi Recipe is a dish that is eaten a lot by the people in North India. The long beans is type of legume that is used a lot in North India. They typically use the pod as well which is called the black eyed beans to make a sabzi out of it. The recipe is quick simple, all you need is to chop the beans and pressure cook and toss it along with simple masala to make this delicious tasting sabzi.', '["300 grams Green Chawli Beans (Yard long beans/Karamani/Barbati) , finely chopped", "1 Ajwain (Carom seeds)", "4 cloves Garlic , finely chopped", "2 Tomatoes , finely chopped", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Garam masala powder", "2 teaspoons Coriander Powder (Dhania)", "1 teaspoon Amchur (Dry Mango Powder)", "1 tablespoon Jaggery", "Salt , to taste", "Mustard oil"]'::jsonb, ARRAY['tomato', 'salt', 'amchur (dry mango powder)', 'mustard oil', 'ajwain (carom seeds)', 'jaggery', 'red chilli powder', 'cloves garlic', 'green chawli beans (yard beanskaramanibarbati)', 'coriander powder', 'turmeric powder', 'garam masala powder']::text[], '["To begin making the North Indian Chawli ki Sabzi Recipe,\u00a0Chop the beans and pressure cook along with a little salt and 2 tablespoons water for two whistles and turn off the heat.", "Release the pressure immediately to maintain the fresh green colours of the beans.Heat oil in a kadai/ wok; add the ajwain and allow it to crackle.", "Add the garlic and saute for a few seconds.Add the tomatoes, turmeric, red chilli, coriander, amchur powders and saute until the tomatoes become mushy.", "Finally add the cooked green Chawli, jaggery add more salt if required and stir well to combine for 3 to 4 minutes.Once done, check the taste and adjust seasonings accordingly and transfer the\u00a0Chawli ki Sabzi to a serving bowl.Serve the North Indian Chawli ki Sabzi Recipe along with\u00a0Phulka,\u00a0\u00a0Dhaba Style Dal Fry\u00a0and\u00a0Yogurt\u00a0to make a healthy lunch or dinner."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/North_Indian_Chawli_ki_Sabzi_Recipe___Yard_Long_Beans___Barbati___Karamani_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/410.North_Indian_Chawli_ki_Sabzi_Recipe___Yard_Long_Beans___Barbati___Karamani_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bell Pepper Sabji Recipe-No Onion No Garlic', 'bell-pepper-sabji-recipe-no-onion-no-garlic', 'Including a variety of coloured fruits and vegetables in our daily diet is not only eye pleasing but also helps to increase the intake of a variety of nutrients. Coloured peppers (capsicum) are easily available at most vegetable vendors and hence are easier to include in the regular diet.', '["1 Yellow Bell Pepper (Capsicum) , diced", "1 Red Bell pepper (Capsicum) , diced", "1 tablespoon Groundnut powder", "2 teaspoons Sesame powder", "1/2 teaspoon Maharashtrian Goda Masala , optional", "1/2 teaspoon Red Chilli powder", "1/4 Turmeric powder (Haldi)", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Tamarind Paste", "1-1/2 teaspoon Jaggery , grated", "2 teaspoons Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "Coriander (Dhania) Leaves , as required for garnishing"]'::jsonb, ARRAY['yellow bell pepper (capsicum)', 'red bell pepper (capsicum)', 'asafoetida (hing)', 'mustard seeds', 'coriander (dhania) leaves', 'jaggery', 'red chilli powder', 'sesame powder', 'cumin seeds (jeera)', 'maharashtrian goda masala', 'tamarind paste', 'groundnut powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Bell Pepper Sabji Recipe, keep all the ingredients prepped and ready.", "First heat oil in a kadhai/wok.Add the mustard seeds and once they splutter add the cumin seeds.Add in the colored bell peppers and saute till it softens.", "Add hing, turmeric powder, red chilli powder and Goda masala (if using) and mix well.Add salt and cook covered for 1 to 2 minutes.", "Add the tamarind paste, jaggery, groundnut powder, sesame powder and a little water (about 3-4 tablespoon).Cook uncovered for 1 to 2 minutes more, stir once or twice.Garnish with coriander leaves and serve immediately.", "Serve\u00a0Bell Pepper Sabji Recipe along with\u00a0Gujarati Dal\u00a0and\u00a0Phulkas\u00a0for a weekday lunch or dinner."]'::jsonb, 20, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Sweet_Pepper_sabji_Nooniongarlic_colred_peppers_sabji.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/411.Sweet_Pepper_sabji_Nooniongarlic_colred_peppers_sabji.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vazhakkai Poriyal Recipe - Raw banana Roast With Pepper', 'vazhakkai-poriyal-recipe-raw-banana-roast-with-pepper', 'Vazhakkai Poriyal Recipe is a classic tamil nadu style poriyal which is also made ayurvedic without the addition of red chillies, onion and garlic. This poriyal made from raw banana tossed in asafoetida and black pepper makes it super delicious and tasty. The dish is very quick and easy to prepare and kids will love to try this recipe as it is flavorful and tasty. Raw banana is equally nutritious vegetable as it is diabetic friendly and has lots minerals, vitamins and a good source of fiber.', '["2 tablespoons Sesame (Gingelly) Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves , roughly chopped", "2 Raw Banana", "1 teaspoon Black pepper powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Asafoetida (hing)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard seeds', 'asafoetida (hing)', 'sesame (gingelly) oil', 'curry leaves', 'white urad dal (split)', 'black pepper powder', 'turmeric powder', 'banana']::text[], '["We begin making the Vazhakkai Poriyal Recipe, cut the raw banana into half along with the skin and 1/2 cup of water and pressure cook for 4 to 5 whistles.Turn off the heat and allow the pressure to release naturally.", "Once the pressure releases, peel the skin off the slice/ dice the cooked raw banana into small pieces.", "Heat oil in a\u00a0heavy bottomed pan over medium heat; add the mustard seeds, urad dal, and curry leaves and allow them to crackle and the dal to turn golden and crisp.Add the asafoetida, cooked raw banana, turmeric powder, black pepper powder and salt to taste.Roast the\u00a0Vazhakkai Poriyal until it gets well combined and has a light crispy texture.", "Once done, turn off the heat, check the salt and spices and adjust accordingly.Transfer the\u00a0Vazhakkai Poriyal / Raw Banana Roast into a serving bowl.Serve the Vazhakkai Poriyal Recipe - Raw banana Roast as side dish along with\u00a0Steamed Rice\u00a0and\u00a0Sambar\u00a0for a delicious weekend lunch."]'::jsonb, 35, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/raw_banana_poriyal_vazhakkai_roast_recipe_12_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/412.raw_banana_poriyal_vazhakkai_roast_recipe_12_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Butter Chicken With Tandoori Mayo Recipe', 'butter-chicken-with-tandoori-mayo-recipe', 'Butter Chicken or Chicken Makhani is a creamy and delicious preparation of chicken in rich tomato gravy. Butter Chicken With Tandoori Mayo Recipe is a variant of the Mughlai Chicken Makhani.', '["400 grams Boneless chicken , cubed to bite size (2-inches)", "Butter (Salted) , as required", "Oil , as required", "2 tablespoon Del Monte Tandoori Mayo", "1 tablespoon Cumin powder (Jeera)", "1 tablespoon Coriander Powder (Dhania)", "1 tablespoon Red Chilli powder", "1/2 tablespoon Turmeric powder (Haldi)", "3/4 tablespoon Ginger , grated", "3/4 tablespoon Garlic , grated", "1 tablespoon Lemon juice", "2 tablespoon Curd (Dahi / Yogurt)", "1 teaspoon Salt", "2 Onion , chopped", "5 Tomatoes , chopped", "1 cup Water", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Cumin powder (Jeera)", "1/2 inch Ginger , peeled and finely chopped", "1 Green Chilli , finely chopped", "2 tablespoon Butter (Salted)", "1/2 teaspoon Sugar", "1 tablespoon Del Monte Tandoori Mayo", "4 tablespoon Fresh cream", "1 teaspoon Oil", "Coriander (Dhania) Leaves", "1 teaspoon Fresh cream", "1 tablespoon Butter (Salted)"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'ginger', 'green chilli', 'coriander (dhania) leaves', 'red chilli powder', 'water', 'del monte tandoori mayo', 'curd', 'sugar', 'garlic', 'lemon', 'boneless chicken (es)', 'onion', 'coriander powder', 'turmeric powder', 'butter', 'sunflower oil']::text[], '["To prepare Butter Chicken With Tandoori Mayo Recipe, first marinate the chicken.", "In a mixing bowl, add the chicken pieces and all the ingredients mentioned in \"For Marination\" list.Combine all the ingredients together and mix well by applying the marinade to the chicken pieces.Close this bowl and leave it in the refrigerator for at least 2 hours.After the chicken gets marinated and when it is time to make the gravy, keep the marinated chicken out from the freezer.Now to prepare the pan fried chicken tikkas/kebabs, heat a kadai/wok with 2 teaspoon oil.", "Once the oil is heated, add 2 tablespoon butter and wait for it to melt.After butter gets melted, add the marinated chicken pieces and fry in batches till they are cooked.", "Add more butter if needed while frying.After frying remove the chicken kebabs/tikka and keep aside.To prepare tomato gravy for the butter chicken, boil the tomatoes for 10 minutes in a cup of water and switch off the gas.After cooling, add this to a mixer along with chopped onion and grind to a thin puree.In the pan, add a teaspoon of oil and 2 tablespoons butter.", "After the butter melts, add ginger and green chillies and saute for 2 minutes.Add the spice powders (turmeric powder, red chili powder, cumin powder and coriander powder) one by one and saute till they mix well and are aromatic.Now pour the tomato and onion puree and mix well with spices.Simmer on low flame till oil rises to the surface of the gravy and the color of the gravy changes.Add the chicken tikka pieces and mix well.", "Add 1/2 teaspoon sugar and mix well.Simmer the gravy for 10 minutes.", "Adjust salt.", "Now add fresh cream and Delmonte tandoori mayo, mix and simmer for 5 minutes.Garnish with cream, a knob of butter and coriander leaves.", "Serve with steamed Basmati rice, Naan\u00a0or\u00a0Pudina Tawa Paratha."]'::jsonb, 180, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Butter_Chicken_Recipe_With_Tandoori_Mayo-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/413.Butter_Chicken_Recipe_With_Tandoori_Mayo-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vegetable Yakhni Pulao Recipe', 'vegetable-yakhni-pulao-recipe', 'The origins of Yakhni Pulao lies back to Persia and was introduced to Indians by the Mughal rulers. Aromatic spices are the essence of this pulao or pilaf. Yogurt is another ingredient which is the key to bringing all these flavours together and giving this pulao its unique flavor.', '["Spices to be powdered", "1 teaspoon Ajwain (Carom seeds)", "1 tablespoon Coriander (Dhania) Seeds", "1 teaspoon Fennel seeds (Saunf)", "3 Cloves (Laung)", "4 Cardamom (Elaichi) Pods/Seeds", "2 inch Cinnamon Stick (Dalchini)", "2 to 3 Whole Black Peppercorns", "2 cups Vegetable stock , or water", "2 cups Basmati rice", "1 Onion , finely chopped", "1 inch Ginger , grated", "4 cloves Garlic , grated", "2 Green Chillies , slit", "1 Bay leaf (tej patta)", "1 Carrot (Gajjar) , thinly sliced", "1 cup Cauliflower (gobi) , cut into florets", "1/2 cup Green beans (French Beans) , thinly sliced", "1/2 cup Green peas (Matar)", "1 cup Curd (Dahi / Yogurt) , whisked", "1/2 cup Mint Leaves (Pudina) , finely chopped", "Salt , to taste", "4 tablespoon Ghee", "1/4 cup Caramelized onions", "Mint Leaves (Pudina) , for garnish", "1 teaspoon Ghee", "1 tablespoon Cashew nuts", "1 tablespoon Sultana Raisins"]'::jsonb, ARRAY['basmati rice', 'vegetable stock water', 'ajwain (carom seeds)', 'black peppercorns', 'cloves garlic', 'carrot', 'coriander (dhania) seeds', 'onion', 'green chillies', 'salt', 'cardamom (elaichi) podsseeds', 'raisins', 'mint leaves (pudina)', 'green beans (french beans)', 'cauliflower (gobi)', 'curd', 'cashew nuts', 'ginger', 'bay leaf (tej patta)', 'fennel seeds (saunf)', 'ghee', 'green peas (matar)', 'cinnamon stick (dalchini)', 'cloves (laung)']::text[], '["To begin making the\u00a0Vegetable Yakhni Pulao Recipe, first roast all the spices including shahi jeera, coriander seeds, fennel seeds, cloves, cardamom, cinnamon stick and whole black peppercorns in a small pan over medium heat.", "This will take about 4 to 5 minutes.Once roasted, make a coarse powder and keep aside.Prepare the caramelized onions for garnish.", "Heat a pan with some oil.", "Add the thinly sliced onions and cook till it turns brown in colour.", "Keep it aside.In another small pan, add a tablespoon of ghee and roast the cashewnuts over medium heat until golden brown and crisp.", "Once golden brown, add the raisins and saute for a few minutes and turn off the heat.", "Keep this aside for garnish.The final step is to cook the rice with the stock and vegetables.In a large sauce pan over medium heat, add 3 tablespoons of ghee.", "Add the onions, ginger, garlic, green chilies, bay leaf and saute until the onions soften and you get good aromas.Add the spice powder mix, the chopped vegetables and the rice.", "Stir for a few minutes until you can see the rice is well coated with the spices.After a few minutes, add the vegetable stock/water and the yogurt.", "Add the salt and the chopped mint leaves.", "Stir well to combine.", "Bring the Yakhni Pulao to a brisk boil.Once it comes to a brisk boil, turn the heat to low, cover the pan and cook the pulao until all the rice is absorbed.", "The rice should be of grainy texture.Once all the water is absorbed, turn off the heat.", "Allow the Yakhni Pulao to rest for 10 minutes before you can stir.After 10 minutes, open, add the chopped coriander leaves and give it a stir with a large fork and fluff up the rice.Transfer to a serving dish, garnish with the caramelised onions, cashew nuts and mint leaves.Serve the\u00a0Yakhni Pulao\u00a0Recipe along with\u00a0Paneer Tikka Masala,\u00a0Punjabi Dal Tadka\u00a0and\u00a0Phulka\u00a0for a special weekend dinner."]'::jsonb, 65, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Vegetable_Yakhni_Pulao_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/414.Vegetable_Yakhni_Pulao_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rajma Saagwala (Dry Kidney Beans And Spinach Stir Fry) Recipe', 'rajma-saagwala-dry-kidney-beans-and-spinach-stir-fry-recipe', 'Rajma Saagwala is a power packed, protein enriched dish prepared by stir frying red kidney beans and spinach in minimal spices. As we all know, Spinach is a super food loaded with tons of nutrients, this dish makes for a very healthy side dish for phulkas or paratha to be packed in lunchbox for kids.', '["1 cup Rajma (Large Kidney Beans) , boiled", "2 cups Spinach Leaves (Palak) , roughly chopped", "Oil , as required", "1 teaspoon Cumin seeds (Jeera)", "1 Onion , finely chopped", "5 Garlic , cloves, finely chopped", "1 Green Chilli , finely chopped", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "Asafoetida (hing) , A pinch", "Salt , to taste"]'::jsonb, ARRAY['garlic cloves', 'salt', 'green chilli', 'asafoetida (hing)', 'onion', 'cumin seeds (jeera)', 'rajma (large kidney beans)', 'turmeric powder', 'spinach leaves (palak)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making Rajma Saagwala recipe, pressure cook the overnight soaked rajma for two whistles in a pressure cooker and keep it aside.Now heat a wok in medium flame, pour oil, add the cumin seeds and a pinch of asafoetida and let it crackle.Add the finely chopped garlic and saut\u00e9 till aromatic.Add the finely chopped onion and green chilli and cook till the onions become translucent.Add the roughly chopped spinach and cooked rajma and give it a stir.Now add the turmeric, garam masala powder and season with salt and mix well.Let the vegetable cook in medium flame for 10 minutes, occasionally keep stirring in between.Once done, switch off the flame and it is ready to be served.", "Serve Rajma Saagwala as a side dish with\u00a0Rabodi Ki Sabji\u00a0and\u00a0Whole Wheat Lachha Parathas\u00a0for a delicious weekday meal."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Rajma_Saagwala_Dry_Kidney_Beans_and_Spinach_Stir_Fry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/415.Rajma_Saagwala_Dry_Kidney_Beans_and_Spinach_Stir_Fry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dum Ke Baingan Recipe', 'dum-ke-baingan-recipe', 'Dum Ke Baingan Recipe is a delicious side dish made with whole baby brinjal that is slit in the middle and sautéed until it becomes soft in the side and charred on the outside.', '["6 Small Green brinjal (green aubergine) , slit into four", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 Lemon juice", "Oil", "2 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "1 tablespoon Black pepper powder", "3 Cloves (Laung)", "1 Bay leaf (tej patta)", "1 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies", "2 Onion , chopped", "1 inch Ginger , chopped", "4 cloves Garlic"]'::jsonb, ARRAY['salt', 'ginger', 'green brinjal (green aubergine) four', 'cardamom (elaichi) podsseeds', 'bay leaf (tej patta)', 'cloves garlic', 'dry red chillies', 'cinnamon stick (dalchini)', 'lemon', 'cumin seeds (jeera)', 'onion', 'black pepper powder', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Dum Ke Baingan Recipe, we will grind all the masala that are mentioned in the list, cardamom, cinnamon stick, black pepper powder, cloves, bay leaf, cumin seeds, dry red chillies, onion, ginger, garlic to a coarse paste by adding some water.Heat a pan with oil, add whole brinjal that are slit and saute them for 10 minutes.", "Sprinkle some salt over it and cook it covered so that it gets cooked faster.Once the brinjal becomes soft and turns dark brown then it is cooked.", "You can take them out and keep it aside until you make the gravy.Add little more oil in the same pan , and add the ground masala into the pan and keep cooking until the gravy is cooked.The gravy will slowly turn thick now add the\u00a0 roasted brinjal and drizzle lemon juice.Combine the\u00a0Dum Ke Baingan\u00a0 well\u00a0 and check for salt.", "Cover it and cook for at least 2 minutes and serve hot.Serve the Dum Ke Baingan Recipe along with\u00a0Tawa Paratha,\u00a0Kadhi Pakora,\u00a0Sweet Potato & Green Bean Salad\u00a0by the side to pack it for your everyday lunch box or just have it at home."]'::jsonb, 40, 'Hyderabadi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Dum_Ke_Baingan_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/416.Dum_Ke_Baingan_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hariyali Chicken Tikka Masala Recipe', 'hariyali-chicken-tikka-masala-recipe', 'Hariyali Chicken Tikka Masala Recipe, it has the same ingredients as that of a Hariyali Chicken Tikka but we have added some garvy to this dish so that you can have it along with hot Phulkas and Tawa Parathas.', '["300 grams Chicken breasts , cut into small pieces", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoons Garam masala powder", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Cumin powder (Jeera)", "1/4 cup Curd (Dahi / Yogurt)", "1/4 cup Fresh cream", "Salt , to taste", "To grind", "1 cup Coriander (Dhania) Leaves", "1 cup Mint Leaves (Pudina)", "1 Green Chilli"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'green chilli', 'amchur (dry mango powder)', 'coriander (dhania) leaves', 'red chilli powder', 'curd', 'mint leaves (pudina)', 'chicken breasts', 'turmeric powder', 'garam masala powder']::text[], '["To begin making the Hariyali Chicken Tikka Masala Recipe, we will first grind the coriander leaves, mint leaves and green chilli to a smooth paste in a mixer grinder.Add this ground paste along with turmeric powder, garam masala powder, amchur powder, cumin powder and curd into a bowl.", "Mix everything well.Add chicken pieces to this marination and salt to taste.", "Mix well and keep it aside for about 1 hour.After an hour, heat a heavy bottomed pan with oil and add only the chicken pieces into the kadai to fry.Fry until the chicken pieces are cooked and they crisp up.", "Take them out and keep it aside.In the same kadai, add the remaining marination gravy that is left out, and cook till the gravy has reduced.", "This will take about 3 to 4 minutes.Check for salt and seasoning, if required you can add them.", "Add cream at the end and little bit of water to adjust consistency.Cook for 2 minutes and add cooked chicken pieces into the gravy and serve hot.Serve the\u00a0Hariyali Chicken Tikka Masala\u00a0Recipe along with\u00a0Tawa Paratha\u00a0or\u00a0Garlic Naan\u00a0and\u00a0Burani Raita\u00a0with\u00a0Saunf Aloo & Dal Kebab Recipe\u00a0by the side to make it a complete meal."]'::jsonb, 110, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/10-oct/Hariyali_Chicken_Tikka_Masala_Recipe-9391.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/417.Hariyali_Chicken_Tikka_Masala_Recipe-9391.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Roat Recipe | Uttarakhand Style Sweetened Flatbread', 'roat-recipe-uttarakhand-style-sweetened-flatbread', 'Roat is an authentic dish from Uttarakhand usually made during marriages or other religious functions. Basically Roat Recipe | Uttarakhand Style Sweetened Flatbread is a sweet flatbread made of wheat flour and cooked till crisp using generous amount of ghee. Fennel seeds and cardamom adds a tempting flavor to roat . Crispy and flaky they are very tasty. Serve hot Roat Recipe | Uttarakhand Style Sweetened Flatbread with a dollop of ghee, along side Makki Ki Roti, Chole Pindi, Ghee Rice and raita.', '["1 cup Whole Wheat Flour", "1/4 cup Milk , cold", "3 tablespoons Ghee , more to smear", "1/2 teaspoon Cardamom Powder (Elaichi)", "1 teaspoon Fennel seeds (Saunf)", "1 cup Jaggery"]'::jsonb, ARRAY['wheat flour', 'ghee', 'fennel seeds (saunf)', 'milk cold', 'jaggery', 'cardamom powder (elaichi)']::text[], '["To prepare Roat Recipe | Uttarakhand Style Sweetened Flatbread, In a bowl mix together wheat flour, 3 tablespoon ghee, fennel seeds and cardamom powder.In another pan mix together grated jaggery and very little water.Once the jaggery is dissolved, strain it to remove impurities.And allow to cool .Add cold milk to the flour, jaggery syrup and mix.Make a soft dough .Divide into equal portions.", "Roll each ball into a thick roti.Heat a tawa and cook the roat on both sides until tiny brown spots appear.", "Smear ghee generously while cooking.", "Cook both sides till it''s crisp.Serve Roat Recipe | Uttarakhand Style Sweetened Flatbread hot with a dollop of ghee as a dessert along with meals of Makki Ki Roti, Chole Pindi, Ghee Rice and raita."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/ROAT.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/418.ROAT.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Himachal Style Panchkuti Khichdi Recipe', 'himachal-style-panchkuti-khichdi-recipe', 'Himachal Style Panchkuti Khichdi Recipe is a millet preparation with five different kinds of dal cooked in one pot. Khichdi is a preparation that is famous in North India that usually cooked either with a rice and any kind of dal. The Panchkuti has a goodness of all the dals that will benefit you in one dish. The whole spices are tempered with ghee and then poured over the khichdi which gives a distinct aroma and helps to lift up the flavor of the dish.', '["1 cup Bajra (seeds)", "1/4 cup Chana dal (Bengal Gram Dal)", "1/4 cup Arhar dal (Split Toor Dal)", "1/4 cup Green Moong Dal (Split)", "1/4 cup Yellow Moong Dal (Split)", "1/4 cup Masoor Dal (Whole)", "To temper", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Whole Black Peppercorns", "2 Dry Red Chillies", "1 inch Cinnamon Stick (Dalchini)", "3 Cloves (Laung)"]'::jsonb, ARRAY['yellow moong dal (split)', 'arhar dal (split toor dal)', 'mustard seeds', 'black peppercorns', 'masoor dal', 'dry red chillies', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'green moong dal (split)', 'cloves (laung)', 'bajra (seeds)', 'chana dal (bengal gram dal)']::text[], '["To begin making the Himachal Style Panchkuti Khichdi Recipe, soak the dal and millet in water for about 30 minutes.Pressure cook the dals along with millet in about 3 cups of water, add turmeric powder and salt as well and cook for about 5 whistle.", "If there is more liquid, it is fine you can keep the khichdi a little wet.Heat another tempering pan, add ghee, and slowly add cumin seeds and mustard seeds allow it to splutter for few seconds.Add in the remaining ingredients and fry the spice in oil for 10 seconds and pour it over the khichdi and serve.Serve the Himachal Style Panchkuti Khichdi Recipe along with\u00a0Gujarati kadhi\u00a0or\u00a0Palak Raita Recipe (Spinach Yogurt Salad)\u00a0for your morning breakfast."]'::jsonb, 50, 'Himachal', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Himachal_Style_Panchkuti_Khichdi_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/419.Himachal_Style_Panchkuti_Khichdi_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Green Peas Nimona Recipe', 'green-peas-nimona-recipe', 'Green Peas Nimona is a traditional side dish recipe of North India. It is generally made in winters because peas is easily available in the market. This dish is famous in Lucknow and Kanpur and is an amazing recipe if you want to try something different with peas.', '["250 grams Green peas (Matar)", "1 cup Badi (wadi) , urad dal vadi", "2 tablespoon Onion , paste", "2 tablespoon Ginger Garlic Paste", "2 Tomatoes", "Salt , to taste", "2 teaspoon Red Chilli powder", "1 tablespoon Turmeric powder (Haldi)", "1-1/2 tablespoon Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Asafoetida (hing)", "1 tablespoon Ghee", "1 + 2 tablespoon Oil", "1 teaspoon Green Chillies , finely chopped", "1 teaspoon Ginger , grated", "2 teaspoon Cumin seeds (Jeera)", "3 sprig Coriander (Dhania) Leaves , for garnishing"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'sunflower oil', 'asafoetida (hing)', 'ghee', 'green peas (matar)', 'red chilli powder', 'onion paste', 'ginger garlic paste', 'coriander (dhania) leaves', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'green chillies', 'garam masala powder', 'badi (wadi) urad dal vadi']::text[], '["To begin with Green Peas Nimona, coarsely grind the peas in a blender using a little water and keep it aside.Heat the ghee in a pan and saute 1 teaspoon cumin seeds, asafoetida, ginger and green chillies.", "Add peas in the pan and let it cook on a low flame till the puree becomes lightly golden.", "Once it is done, switch off the heat.Now heat 1 tablespoon oil in an another pan and golden fry the dal vadis,Heat the remaining oil in a broth pan and add 1 teaspoon cumin seeds, clove and cook it for about a minute.", "Add ginger, garlic paste and onion paste, saute it on medium flame till the paste becomes golden.Now add turmeric powder, red chili powder, salt and coriander powder.", "Mix everything well and cook the spices for 2-3 minutes.Once it is done, add tomatoes and cook it until the oil separates from the gravy.Once the oil separates from the gravy, add green fried peas puree, vadis and stir for 2-3 minutes till the mixture leaves the sides of the pan.Add 1-1/2 cup water and let it cook or 5 to 8 minutes.", "After 5-8 minutes, switch off the gas and sprinkle the garam masala and chopped coriander leaves.Serve Green Peas Nimona with\u00a0Jeera Rice\u00a0and\u00a0Lauki Raita\u00a0for a weekday lunch."]'::jsonb, 60, 'Awadhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/hem_lata_srivastava/green_peas_nimona.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/420.green_peas_nimona.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Whole Wheat Palak Naan Recipe', 'whole-wheat-palak-naan-recipe', 'Whole Wheat Palak Naan Recipe is made quire frequently in my home. It’s because naans come together pretty quickly and they’re easy to make on the stovetop too. There are several variants of naans, so I decided to try a palak naan. Though not commonly made, the use of whole wheat and palak really makes this a healthy naan compared to what you might get in a restaurant. I made this naan without yeast eliminating the need to wait for the dough to rise. It’s as easy as mixing all the ingredients together, giving the dough a short rest and it’s ready to cook. Serve this Whole Wheat Palak Naan along with Mushroom Pasanda or Green Moong Dal Makhani for a wholesome meal.', '["2 cups Whole Wheat Flour", "1/2 cup Spinach Leaves (Palak) , finely chopped (tightly packed)", "1 teaspoon Baking soda", "1-1/2 teaspoon Salt , (adjust to taste)", "1/2 teaspoon Sugar", "1 tablespoon Oil", "1 cup Curd (Dahi / Yogurt)", "Ghee , for smearing on naan", "Kalonji (Onion Nigella Seeds) , or sesame seeds to sprinkle"]'::jsonb, ARRAY['salt', 'wheat flour', 'kalonji (onion nigella seeds) sesame seeds', 'ghee on naan', 'baking soda', 'curd', 'sugar', 'spinach leaves (palak)', 'sunflower oil']::text[], '["To begin making the Whole Wheat Palak Naan, first add the flour, palak, salt, sugar, baking soda, oil into a mixing bowl and combine.Make a well in the center and all curd and begin to knead the dough together.", "Work it until it is a smooth dough dough.", "Add water if needed so make it a soft and slightly sticky dough.", "Do not be tempted to add more flour, the dough needs to be on the wetter/stickier side.", "Rub oil all over the dough, cover and let it rest for about 30 minutes.When ready to make the naans, divide the dough into 6-8 equal parts.Taking each portion at a time, dust a little flour if needed to roll and using a rolling pin or fingers, press the portion out into a thick, flat disc shaped like a naan.Rub water over the rolled out naan and sprinkle sesame seeds, kalonji seeds, and finely chopped palak leaves.Place a skillet on the heat and when it is warm enough, place the rolled naan over a hot tawa with the side sprinkled with kalonji facing the top.", "Cover and cook for about a minute on medium low flame.Now lift the tawa off the heat and flip the naan over, directly on to the heat.", "This ensures you get a charred smoky flavor to the naan, mimicking the tandoori flavour.Once done, take the naan off the heat/tawa and rub with ghee.Repeat with rest of the dough and serve hot naans\u00a0with\u00a0Mushroom Pasanda\u00a0or\u00a0Green Moong Dal Makhani."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Whole_Wheat_Palak_Naan.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/421.Whole_Wheat_Palak_Naan.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kaigari Pirattal Recipe (Chettinad Style Mixed Vegetables)', 'kaigari-pirattal-recipe-chettinad-style-mixed-vegetables', 'Kaigari Pirattal in Tamil means stir fried vegetables. This unique mixed vegetable stir fry uses aromatic Chettinad spices. Chettinad cuisine makes use of fennel in various forms in its recipes. The Kaigari Pirattal Recipe is mildly flavored with fennel seeds and is a great accompaniment with steamed rice and Manathakkali Kai Vathal Kuzhambu.', '["1/2 cup Cauliflower (gobi) , broken into small florets", "1/4 cup Green beans (French Beans) , cut into one-inch pieces", "1/4 cup Carrots (Gajjar) , cut into inch long pieces", "2 Potatoes (Aloo) , cut into cubes", "1 Onion , sliced", "2 teaspoons Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "To grind to coarse mixture", "1/2 cup Fresh coconut , grated", "2 Dry Red Chillies", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Fennel seeds (Saunf)"]'::jsonb, ARRAY['green beans (french beans)', 'mustard seeds', 'coconut', 'fennel seeds (saunf)', 'carrot', 'curry leaves', 'dry red chillies', 'onion', 'cumin seeds (jeera)', 'potato (aloo)', 'cauliflower (gobi) florets', 'sunflower oil']::text[], '["To begin making Kaigari Pirattal (Chettinad Style Mixed Vegetables) Recipe, heat a wok in medium flame and pour oil in it.", "Now, put the mustard seeds, curry leaves and let it splutter.Now, add all the cut vegetables into the tempering and give it a stir.", "Sprinkle some water over it and cook with the lid on for five more minutes.Keep stirring in between till the vegetables are fully cooked.Now make a coarse mixture of grated coconut, red chilies, cumin and fennel seeds using a mixer grinder.Add this spice mix to the vegetables, season with salt, and give it a good stir and switch off the flame.Serve this Kaigari Pirattal (Chettinad Style Mixed Vegetables) with steamed rice and spicy Manathakkali Kai Vathal Kuzhambu."]'::jsonb, 35, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Kaigari_Pirattal_Chettinad_Style_Mixed_Vegetables.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/422.Kaigari_Pirattal_Chettinad_Style_Mixed_Vegetables.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dosakaya Pappu Recipe-Andhra Style Yellow Cucumber Dal', 'dosakaya-pappu-recipe-andhra-style-yellow-cucumber-dal', 'Dosakaya Pappu Recipe-Andhra Style Yellow Cucumber Dal is one of the most comforting and flavourful dal delicacy in Andhra cuisine. Dosakaya Pappu Recipe tastes very different and can be made very quickly with minimal ingredients. As the Yellow Cucumber/Dosakaya is somewhat bland in taste, it adapts the taste of all the seasonings you add to the dal, becomes flavourful and also gets cooked in no time.', '["1 cup Arhar dal (Split Toor Dal)", "1/4 teaspoon Turmeric powder (Haldi)", "1 Onion , chopped to big chunks", "3 Green Chillies , slit or broken", "2 cups Tamarind Water", "1 teaspoon Red Chilli powder", "3 Tomatoes , finely chopped", "1 Mangalorean cucumber , peeled and diced", "2 teaspoons Ghee", "4 cloves Garlic , crushed", "2 Dry Red Chillies", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "Asafoetida (hing) , a pinch", "1 sprig Curry leaves", "Salt , as needed", "Coriander (Dhania) Leaves , small bunch, finely chopped"]'::jsonb, ARRAY['tomato', 'salt', 'coriander (dhania)', 'arhar dal (split toor dal)', 'tamarind water', 'ghee', 'mustard seeds', 'asafoetida (hing)', 'red chilli powder', 'cloves garlic', 'curry leaves', 'dry red chillies', 'onion', 'mangalorean cucumber', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies']::text[], '["To begin making the Dosakaya Pappu Recipe, first get all the ingredients ready.", "Wash the dal in water and place it in the Pressure cooker.", "Add the turmeric powder, salt,\u00a0chopped onions, green chillies,\u00a0chopped tomatoes, diced Yellow cucumber/Dosakaya,\u00a0tamarind water and red chilli powder.Add two cups of water, cover the pressure cooker and cook until you hear two whistles.", "After the couple of whistles, turn the heat to low and simmer for 3 minutes and turn off the heat.", "Allow the pressure to release naturally.Once the pressure has released, open the cooker and give the\u00a0Dosakaya Pappu a good stir slightly mashing the Dosakaya into the dal.", "Check the salt and spices and adjust according to taste.Add water if you wish to adjust the consistency of the dal and transfer the\u00a0Dosakaya\u00a0Pappu to a serving bowl and stir in the chopped coriander leaves.", "For the seasoning: Crush or chop garlic pods.", "Heat ghee in a small tadka pan over medium heat and add the garlic.", "Once garlic starts to turn light brown add red chillies, mustard seeds and cumin seeds.", "When mustard seeds splutter, add a pinch of asafoetida.", "Now turn off the heat and add curry leaves.", "Pour the seasoning to the Dosakaya\u00a0Pappu and mix well.Serve the\u00a0Dosakaya\u00a0Pappu with\u00a0hot\u00a0Steamed Rice\u00a0along with a drizzle of ghee.", "It pairs perfectly with a\u00a0Spicy Potato Roast Recipe (Urulaikizhangu Poriyal)\u00a0and a crunchy papad."]'::jsonb, 40, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Padma_Veeranki/Yellow_Cucumber_Dal__Dosakaya_Pappu.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/423.Yellow_Cucumber_Dal__Dosakaya_Pappu.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Khaja Recipe (Layered Fritters Dunked In Sugar Syrup)', 'khaja-recipe-layered-fritters-dunked-in-sugar-syrup', 'Khaja recipe is a traditional coastal recipe that is served as a part of “Sukhila Prasad” in India’s Puri Jagannath temple. This is a sweet dish recipe, prepared from fewer ingredients, is essentially the layered fritters dunked in sugar syrup.', '["Ingredients For Layered Fritters", "4 cups All Purpose Flour (Maida) , + 2 tablespoon", "2 Ghee , + 2 tablespoon, melted", "2 teaspoons Cardamom Powder (Elaichi)", "2 teaspoons Black pepper powder , freshly powdered (optional)", "1 teaspoon Cinnamon Powder (Dalchini) , optional", "Oil , to cook", "Chilled water", "Ingredients for Syrup", "2 cups Sugar", "1 cup Water"]'::jsonb, ARRAY['sunflower oil', 'ghee', 'water', 'sugar', 'cardamom powder (elaichi)', 'black pepper powder', 'flour (maida)', 'cinnamon powder (dalchini)']::text[], '["To prepare Khaja recipe, in a bowl, add the flour, melted ghee and mix well.", "Add cold water to make a smooth yet firm dough.", "Cover the dough and keep aside for at least 15 to 20 minutes.Make a paste mixing 2 tablespoons clarified butter (ghee) and 2 tablespoons all-purpose flour to make a flour paste.Divide the dough into eight equal parts.", "Take a ball and roll into rectangular shape sheet.", "Roll another one similarly.Smear the prepared flour paste on one sheet and place another on top of it.", "Spread the flour paste on top of the second sheet and roll both the sheets together tightly to resemble a log.Cut this flour log into equal sized pieces of 1 inch each.", "Roll each piece vertically.Heat enough oil in Deep fry pan, fry them in batches, on a medium flame until they turn golden brown on both sides.", "Cool them completely.In the meantime, prepare sugar syrup adding 2 cups sugar in 1 cup water in a Saucepan.Bring to a boil and cook till it becomes sticky.Add cardamom powder, black pepper and cinnamon powders to it.", "This addition of spices is purely optional.", "Switch off flame.Grease a large plate with some butter or ghee.Dip the fried khaja into the syrup hence prepared, when the syrup is still warm.", "Immediately take the well-coated khajas onto the greased plate.Serve Khaja at room temperature.", "You could also serve them when still warm.", "This Khaja recipe can be stored in an air-tight container up to 2 weeks at room temperature."]'::jsonb, 70, 'Bihari', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Sai_Priya/Khaja_original_edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/424.Khaja_original_edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bhindi Masala Curry Recipe', 'bhindi-masala-curry-recipe', 'Bhindi Masala Curry Recipe is a common curry which is prepared at everyone’s home. The Bhindi''s are roasted well on the pan and it is mixed along with sauteed onions and tomatoes. The Roasted bhindi is then mixed along with simple spice powders like red chilli powder, turmeric powder and sambar powder that gives in a complete flavour to the dish.', '["250 grams Bhindi (Lady Finger/Okra)", "4 tablespoon Sambar Powder", "1 teaspoon Turmeric powder (Haldi)", "2 teaspoon Kashmiri Red Chilli Powder", "1 teaspoon Red Chilli powder", "Salt , to taste", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Cumin seeds (Jeera)", "1 teaspoon Garlic , chopped", "1 Onion , thinly sliced", "1 Tomato , cut into big cubes", "1 teaspoon Sugar", "Oil , as required", "Sesame seeds (Til seeds) , for garnishing"]'::jsonb, ARRAY['salt', 'kashmiri red chilli powder', 'mustard seeds', 'red chilli powder', 'tomato cubes', 'sugar', 'garlic', 'cumin seeds (jeera)', 'onion', 'bhindi (lady fingerokra)', 'sesame seeds (til seeds)', 'turmeric powder', 'sambar powder', 'sunflower oil']::text[], '["To begin with the Bhindi Masala Curry, wash the bhindi and dry them properly or you might face the problem of stickiness.", "Cut the ends of the Bhindi and and chop them into half.", "Heat a non stick pan and drizzle some oil,\u00a0 Add\u00a0the bhindi, then sprinkle some salt andsaut\u00e9 them for 20 minutes on medium flame.Once done you can take them out and keep it aside.", "Meanwhile in the same frying pan, add a tablespoon oil.", "Add mustard seeds and cumin seeds, when it start splutter add chopped garlic and saut\u00e9 them.Now add sliced onion and add 1 teaspoon sugar and a pinch of salt.", "The caramelization takes place as the sugar is added and the salt helps the onions to cook fast.Add the chopped tomatoes and saut\u00e9 them for a minute until the tomatoes have softened.Turn the heat to low and cook and add the cooked bhindi and stir well until the Bhindi''s are mixed well into the sauteed mixture.", "Add all the spice powder - red chilli powder, turmeric, sambar powder, salt and stir well.Check the salt and spices and adjust to suit your taste.Once done, turn off the heat and serve.Serve the Bhindi Masala Curry along with\u00a0Tawa Paratha,\u00a0Methi Kadhi\u00a0and\u00a0Palak Raita\u00a0to make your meal complete or you can pack for your lunch box as well."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/May-2/Bhindi_Masala_Sabzi_recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/425.Bhindi_Masala_Sabzi_recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Matar Paneer Kachori Korma Recipe - Green Peas And Paneer Kachori Curry', 'matar-paneer-kachori-korma-recipe-green-peas-and-paneer-kachori-curry', 'Matar Paneer Kachori Korma Recipe is a Green Peas And Paneer Kachori Curry which has a unique taste. In this recipe, mini kachoris that are stuffed with peas and paneer are added as an ingredient to a rich tomato, onion and cashew gravy.', '["1 cup All Purpose Flour (Maida)", "2 tablespoons Oil", "1/2 teaspoons Ajwain (Carom seeds)", "Salt , to taste", "Oil , as required for frying", "1 cup Green peas (Matar)", "1 cup Paneer (Homemade Cottage Cheese) , crumbled", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1 teaspoon Amchur (Dry Mango Powder)", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoons Oil", "Salt and Pepper , to taste", "1 cup Onion , chopped", "1 cup Homemade tomato puree", "1 teaspoon Ginger Garlic Paste", "12 Cashew nuts", "1/2 cup Curd (Dahi / Yogurt)", "2 Cloves (Laung)", "1 Mace (Javitri)", "2 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Garam masala powder", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "1/2 teaspoon Sugar", "Salt , to taste", "Coriander (Dhania) Leaves , as required, chopped for garnishing", "Fresh cream , as required for garnishing", "2 tablespoons Oil"]'::jsonb, ARRAY['tomato', 'coriander (dhania) leaves', 'ajwain (carom seeds)', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'sunflower oil', 'salt', 'cardamom (elaichi) podsseeds', 'mace (javitri)', 'cashews', 'flour (maida)', 'garam masala powder', 'red chilli powder', 'curd', 'sugar', 'pepper', 'kasuri methi (dried fenugreek leaves)', 'amchur (dry mango powder)', 'paneer', 'green peas (matar)', 'ginger garlic paste', 'cinnamon stick (dalchini)', 'coriander powder', 'cloves (laung)']::text[], '["To begin making the Matar Paneer Kachori Korma Recipe, we will firstly make the dough for kachori."]'::jsonb, 80, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/anki.s19-gmail.com/Mutter_paneer_kachori_korma.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/426.Mutter_paneer_kachori_korma.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Methi Kumro Recipe - Bengali Style Fenugreek Leaves and Pumpkin Stir Fry', 'methi-kumro-recipe-bengali-style-fenugreek-leaves-and-pumpkin-stir-fry', 'Methi Kumro Recipe is a delicious bengali style fresh fenugreek leaves stir fry with pumpkin. It gets done within no time and makes use of very few easy to available ingredients from the pantry. The simple tempering of panch phoron adds a great flavour to the dish.', '["2 cups Kaddu (Parangikai/ Pumpkin) , cut into cubes", "1.5 cups Methi Leaves (Fenugreek Leaves) , roughly chopped", "2 Green Chillies , finely chopped", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera)", "1 Dry Red Chilli", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Kalonji (Onion Nigella Seeds)", "1/4 teaspoon Fennel seeds (Saunf)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1 tablespoon Mustard oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'kalonji (onion nigella seeds)', 'parangikai pumpkin', 'mustard oil', 'mustard seeds', 'fennel seeds (saunf)', 'methi leaves (fenugreek leaves)', 'dry red chilli', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'turmeric powder', 'green chillies']::text[], '["To begin making the Methi Kumro Recipe (Bengali Style Fenugreek Leaves and Pumpkin Stir Fry), clean, deseed the yellow pumpkin and cut them into bite sized cubes and keep aside.Likewise, clean the fenugreek leaves, roughly chop them and keep aside.Heat mustard oil in a pan, and bring it to the smoking point.To this add the dried red chilli and panch phoron spices - mustard, cumin, fennel, fenugreek and onion seeds.", "Let it crackle.Add the pumpkin cubes and saute for 2 minutes.", "Add in the turmeric, cumin powder, season with salt and mix well.Add in the fenugreek leaves and mix well.", "Close it with a lid and let the pumpkin cubes cook till soft yet retaining its shape.Pumpkin will release a lot of water, so once the cubes are cooked well, increase the heat, saute until the water from the dish totally evaporates and you have a dry sabzi.Once the veggies are dry and well coated with spices, switch off the heat.Serve Methi Kumro Recipe (Bengali Style Fenugreek Leaves and Pumpkin Stir Fry) along with\u00a0Cholar Dal Recipe, and\u00a0Steamed Rice\u00a0for a simplified Bengali themed weekday lunch."]'::jsonb, 25, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Methi_Kumro_Recipe_Bengali_Style_Fenugreek_Leaves_and_Pumpkin_Stir_Fry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/427.Methi_Kumro_Recipe_Bengali_Style_Fenugreek_Leaves_and_Pumpkin_Stir_Fry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kalyana Veetu Senai Curry Recipe - South Indian Spicy Roasted Yam', 'kalyana-veetu-senai-curry-recipe-south-indian-spicy-roasted-yam', 'Kalyana Veetu Senai Curry also called as Senai Kizhangu, is a yam recipe where cooked yam is roasted with coconut and everyday South Indian masalas like sambar powder, red chilli powder and coriander powder. Yam is cooked in different styles during special occasions, but this one is specially cooked during weddings in Tamil Nadu.', '["250 grams Elephant yam (Suran/Senai/Ratalu) , cut into 1 inch thin pieces", "1/2 cup Fresh coconut , grated", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "Curry leaves , few", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Turmeric powder (Haldi)", "2 teaspoon Sambar Powder", "Salt , to taste", "Oil , as required for frying"]'::jsonb, ARRAY['salt', 'elephant yam (suransenairatalu)', 'mustard seeds', 'asafoetida (hing)', 'coconut', 'red chilli powder', 'curry leaves', 'coriander powder', 'turmeric powder', 'sambar powder', 'sunflower oil']::text[], '["To begin making the Kalyana Veetu Senai Curry\u00a0Recipe, add the cut yam pieces into a pressure cooker with 1/4 cup of water, 1/2 turmeric powder and salt and pressure cook the yam for one whistle and keep aside.Preheat oil in a pan over medium heat; add the mustard seeds and allow it to splutter.Once the mustard seeds crackle, stir in the hing and curry leaves and saute for few seconds.After a few seconds, add the grated coconut and roast for about minute until it turns golden in colour and releases an aroma.", "At this stage, add the red chilli powder, turmeric powder, coriander powder, sambar powder and saute for a few seconds and add the cooked yam.", "Stir well until all the masalas coat the yam - about a minute.The yam, tends to get a little dry, as it combines with the masala; you could add a little more oil to help give the yam a little more crispy texture and also help the masalas to get absorbed well into the\u00a0Senai Curry.Once you notice the masalas are well coated and the Kalyana Veetu Senai Curry has a slightly roasted texture, check the salt and spices and adjust to suit your taste.Once done, turn off the heat and transfer the\u00a0Kalyana Veetu Senai Curry to a serving bowl and serve hot.Serve Kalyana Veetu Senai Curry along with\u00a0Keerai Sambar\u00a0and\u00a0Steamed Rice\u00a0for a weekday lunch.", "You can also pack it in your Lunch Box along with\u00a0Palak Raita\u00a0and\u00a0Tawa Paratha."]'::jsonb, 60, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/_Kalyana_Veetu_Senai_Curry_Recipe_-_South_Indian_Style_Roasted_Yam__1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/428._Kalyana_Veetu_Senai_Curry_Recipe_-_South_Indian_Style_Roasted_Yam__1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kadhai Tofu Sabji Recipe', 'kadhai-tofu-sabji-recipe', 'Kadhai Tofu Sabji is made by stir frying Tofu in a Kadhai/wok, with a few vegetables and spices. It is a quick, simple recipe made using easily available ingredients. You can make ahead a stock of the spice mix and use as required. The spices flavour the bland Tofu pieces and it is sure to win over even those who dislike Tofu.', '["250 grams Tofu , firm, cubed", "1 Green Bell Pepper (Capsicum) , diced", "1 Onion , diced", "1 teaspoon Garlic , paste", "1 teaspoon Ginger , paste", "2 Tomatoes , blanched, skin removed and finely chopped or pureed", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves) , crushed, optional", "1 tablespoon Oil", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Sugar", "Salt , to taste", "Coriander (Dhania) Leaves , as required, chopped for garnish", "2 teaspoon Coriander (Dhania) Seeds", "5 to 6 Whole Black Peppercorns", "1 teaspoon Fennel seeds (Saunf)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoons Anardana Powder (Pomegranate Seed Powder)", "3 to 4 Dry Red Chilli", "1 Bay leaf (tej patta)", "1 Black cardamom (Badi Elaichi)", "1/2 teaspoon Amchur (Dry Mango Powder)"]'::jsonb, ARRAY['tomato', 'coriander (dhania) leaves', 'anardana powder (pomegranate seed powder)', 'black peppercorns', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'sunflower oil', 'salt', 'black cardamom (badi elaichi)', 'dry red chilli', 'sugar', 'kasuri methi (dried fenugreek leaves)', 'garlic paste', 'tofu firm', 'amchur (dry mango powder)', 'bay leaf (tej patta)', 'fennel seeds (saunf)', 'green bell pepper (capsicum)', 'ginger paste']::text[], '["To begin making the Kadai Tofu Sabji, first make the dry masala.In a small pan, dry roast the coriander seeds, peppercorns, fennel seeds, cumin seeds, red chillies, tejpatta and black cardamom.", "Cool and coarsely grind it in a blender along with the Anardana and dry mango powder.Now we will make the\u00a0Kadai Tofu SabjiIn a kadai/wok, heat the oil.", "Add the cumin seeds and let it splutter.Once done add\u00a0 the onion and the\u00a0\u00a0ginger and garlic paste and saut\u00e9 for a few seconds till the onion becomes translucent.Once the onions have turned translucent add\u00a0 the turmeric powder, tomato puree and cook for 1 to 2 minutes.Add 2 to 3 teaspoons of the freshly ground masala and kasuri methi, mix well to combine.Once done add the capsicum and stir fry for a few seconds.", "Add the Tofu cubes, sprinkle salt and sugar.Mix nicely so that the masala coats the Tofu cubes.", "Cook for another minute.Garnish with coriander leaves and transfer Kadai Tofu Sabji to a serving bowl,it is ready to be served.Serve\u00a0Kadhai Tofu Sabji\u00a0with\u00a0Pudina Lehsun Laccha Paratha,\u00a0Dal Palak\u00a0and\u00a0Red Cabbage Carrot, Sprout And Onion Salad\u00a0for a wholesome lunch."]'::jsonb, 25, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Kadhai_Tofu_Sabji.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/429.Kadhai_Tofu_Sabji.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Beetroot Poriyal Recipe - Stir Fried Beetroot', 'beetroot-poriyal-recipe-stir-fried-beetroot', 'The Beetroot Poriyal Recipe also known as Beetroot Curry is a delicious and healthy preparation of the beetroot vegetable. In this recipe, the beetroot is steamed and seasoned with mustard leaves, curry leaves, asafoetida and coconut.', '["2 Beetroot , diced small", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 teaspoon White Urad Dal (Split)", "4 to 5 Curry leaves , roughly torn", "1/4 teaspoon Asafoetida (hing)", "1/4 teaspoon Turmeric powder (Haldi)", "1 tablespoon Fresh coconut , grated", "Oil , as required", "Salt , to taste", "Optional ingredients", "1/2 cup Pearl onions (Sambar Onions) , finely chopped", "2 Green Chillies , finely chopped"]'::jsonb, ARRAY['beetroot', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'white urad dal', 'split', 'to 5 curry leaves', 'asafoetida', 'hing', 'turmeric powder', 'haldi', 'fresh coconut', 'oil', 'salt', 'optional ingredients', 'pearl onions', 'sambar onions', 'reen chillies']::text[], '["To begin making the Beetroot Poriyal Recipe, we will first steam the beetroot.", "I personally like to use a pressure cooker, but you can use a steamer or directly cook on the wok.", "To begin pressure cooking the beetroot, place the chopped beetroot into the cooker, sprinkle some salt and add 2 to 3 tablespoons of water.Cover the pressure cooker, place the weight and cook until you hear 2 whistles.", "After 2 whistles turn off the heat.", "Place the pressure cooker under cold running water to release the pressure immediately.Beetroot cooks quickly and hence we are releasing the pressure immediately.", "Once the pressure is released, open the cooker and keep the beetroot aside.Our next step is to season the beetroot.Heat a teaspoon of oil in a heavy bottomed pan; add the mustard seeds, cumin seeds, urad dal and curry leaves.Allow the urad dal to roast until lightly brown.", "If you are adding the onions and green chillies, add it at this stage and saute until soft and the raw smell goes away.Next add the asafoetida, turmeric powder, steamed beetroot and salt and stir fry for about a minutes until well combined.", "Check the salt levels and adjust to suit your taste.Finally\u00a0garnish with\u00a0fresh\u00a0grated coconut and transfer it to a serving bowl.Serve\u00a0Beetroot Poriyal Recipe\u00a0along with\u00a0Mixed Vegetable Sambar,\u00a0Steamed Rice\u00a0and\u00a0Elai Vadam\u00a0for a delicious weekday lunch."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Beetroot_Poriyal_recipe_no_onion_no_garlic_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/430.Beetroot_Poriyal_recipe_no_onion_no_garlic_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Punjabi Style Spicy Arbi Sabji Recipe', 'punjabi-style-spicy-arbi-sabji-recipe', 'Many foodies from North India feel that this Punjabi Style Spicy Arbi Sabji is their favourite way to eat Arbi/ colocasia. It is also an easy recipe to make. Crispy and spicy, it goes really well with hot and flaky paranthas or soft phulkas with a touch of ghee and Spiced Rajma Pulao to make a scrumptious weekday meal.', '["500 grams Colocasia root (Arbi)", "1 Onion , sliced", "3 Green Chillies , slit length-wise", "2 teaspoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "Salt , to taste", "1 teaspoon Red Chilli powder", "1/4 teaspoon Garam masala powder", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Turmeric powder (Haldi)", "Coriander (Dhania) Leaves , as required for garnish"]'::jsonb, ARRAY['salt', 'amchur (dry mango powder)', 'ghee', 'coriander (dhania) leaves', 'red chilli powder', 'colocasia root (arbi)', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies', 'garam masala powder']::text[], '["Prep up with all ingredients to prepare Punjabi Style Spicy Arbi Sabji and Peel and cut arbi in thin long stripes, somewhat like French fries.", "Be use you either grease your hands well with oil or wear gloves because arbi has a tendency to leave your hands itching.Heat oil in a heavy bottom kadhai, when hot add jeera seeds and saut\u00e9 until lightly brown.Add the green chillies and saut\u00e9 for a minute, so that the chilly leaves it spice in the oil.Add onions and saut\u00e9 till they are translucent.", "Add arbi and fry on high heat for about 3-4 minutes, stirring often.Add all the dry spices apart from amchoor powder and garam masala and lower the heat.", "Continue saut\u00e9ing once in a while till arbi is cooked well.Once the arbi is cooked, add amchoor and garam masala and saut\u00e9 for a minute.", "Turn off the heat.Garnish Punjabi Style Spicy Arbi Sabji with coriander leaves and serve hot with rotis, paranthas or soft phulkas with a touch of ghee and Spiced Rajma Pulao to make it a complete meal."]'::jsonb, 55, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Monika_Manchanda/Punjabi_Style_Spicy_Arbi_Sabji.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/431.Punjabi_Style_Spicy_Arbi_Sabji.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Matar Sabzi Recipe - Potatoes Peas In Tomato Gravy', 'aloo-matar-sabzi-recipe-potatoes-peas-in-tomato-gravy', 'Aloo Matar Sabzi Recipe is a very traditional Punjabi dish that is made with potatoes and peas, simmered in light and tangy tomato gravy. The recipe has a delicate addition of spices , it is simmered to perfection brings out the essence of this flavorful dish.', '["3 Potatoes (Aloo) , peeled and diced", "1/2 cup Green peas (Matar) , steamed", "1 Onion , finely chopped", "1 inch Ginger , finely chopped", "3 Tomatoes , pureed (1 cup puree)", "1/2 teaspoon Cumin seeds (Jeera)", "2 Green Chillies , slit", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "4 sprigs Coriander (Dhania) Leaves , finely chopped", "Salt , to taste", "1/2 teaspoon Sugar , to taste", "1 tablespoon Ghee , or oil for cooking"]'::jsonb, ARRAY['potatoes', 'aloo', 'green peas', 'matar', 'onion', 'ginger', 'tomatoes', 'cumin seeds', 'jeera', 'reen chillies', 'garam masala powder', 'turmeric powder', 'haldi', 'red chilli powder', 's coriander', 'dhania', 'salt', 'sugar', 'ghee']::text[], '["To begin making the Aloo Matar Sabzi Recipe, prep all the ingredients and keep aside.Heat a tablespoon of ghee or oil in a pressure cooker; add in the cumin seeds and allow it to crackle.", "Once the cumin seeds crackle add\u00a0in\u00a0the onions and ginger and saute on low heat until the onions soften.Once the onions soften, add the\u00a0tomato puree, green chillies and cook the tomatoes for two to three minutes.Once the tomatoes have softened add turmeric powder, garam masala powder, salt and chilli powder and stir well.", "Add the chopped and peeled potatoes into the pressure cooker.", "Add 1/2 a cup of water.Cover the pressure cooker and allow the Aloo Matar Sabzi to cook for 3 to 4 whistles and turn off the heat.Allow the pressure to release naturally, as the potatoes will continue to cook as long as there is pressure inside the cooker.Once the pressure has released, open the cooker and give the Aloo Matar Sabzi a stir.", "Adjust the consistency of the sabzi, by adding little water if required and post that check the salt and spices and adjust according to taste.Finally stir in the green peas and give the Aloo Matar Sabzi a brisk boil and turn off the heat.Transfer the Aloo Matar Sabzi to a serving bowl , stir in the chopped coriander leaves and serve hot.Serve the Aloo Mutter Sabzi along with steamed rice,\u00a0parathas,\u00a0phulka''s\u00a0or\u00a0naan''s\u00a0for a perfect weeknight dinner."]'::jsonb, 44, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Aloo_Matar_Ki_Sabzi_Garlic_Tawa_Paratha-12_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/432.Aloo_Matar_Ki_Sabzi_Garlic_Tawa_Paratha-12_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Monj Haakh Recipe - Knol Khol Flavored With Asafoetida', 'kashmiri-monj-haakh-recipe-knol-khol-flavored-with-asafoetida', 'Knol Khol also known as Ganth Gobhi is most widely used vegetable in Kashmiri cuisine after Lotus Stem. Monj Haak is a popular Kashmiri vegetarian recipe made with knol khol and greens and typically flavored with asafoetida.', '["1/2 kg Knol Khol (Ganth Gobi/kadam)", "2 Stalks Knol khol Leaves (Ganth Gobi leaves)", "2 pinch Asafoetida (hing)", "2 Dry Red Chillies", "1 pinch Baking soda", "1 teaspoon Kashmiri masala powder", "2-3 tablespoon Mustard oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard oil', 'asafoetida (hing)', 'stalks knol khol leaves (ganth gobi leaves)', 'baking soda', 'dry red chillies', 'knol khol (ganth gobikadam)', 'kashmiri masala powder']::text[], '["To prepare Kashmiri Monj Haakh Recipe, wash and peel the Ganth Gobhi/ knol khol (bulb) and cut into fine slices.Chop the green leafs into two halves.", "Wash nicely to remove dirt and collect in a colander and keep aside.In a broad base Pan, heat oil, and add asafoetida.Now add the chopped Knol Khol and the Knol Khol leaves along with dry red chilies and salt.Saute for a while and now add the Kashmiri spice mix/garam masala and stir.Add water and baking soda.", "Stir and close the lid.Let the vegetable cook in low flame till soft and tender.", "Don''t overcook the greens, try to retain the green color.Turn off the gas and serve Kashmiri Monj\u00a0Haakh Recipe hot with plain steamed rice and Kashmiri Chaman Qaliya or Kashmiri Rogan Josh for lunch."]'::jsonb, 50, 'Kashmiri', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shaheen_Ali/MUNJ_HAAKH__KNOL_KHOL_FLAVORED_WITH_ASAFOETIDA_KASHMIRI_VEG.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/433.MUNJ_HAAKH__KNOL_KHOL_FLAVORED_WITH_ASAFOETIDA_KASHMIRI_VEG.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tamarind Chilli Potato Recipe', 'tamarind-chilli-potato-recipe', 'Tamarind Chili Potato Recipe is a tasty appetizer that can be served before a weekend dinner. The potato is given a spicy and tangy taste which is delicious. These crispy potatoes will be a hit at your table and everyone would enjoy it.', '["3 Potatoes (Aloo) , boiled and cubed", "1 Onion , chopped", "3 tablespoon Tamarind Paste", "1 tablespoon Sugar", "4 cloves Garlic , chopped", "2 tablespoon Cashew nuts , chopped", "2 sprig Curry leaves", "Salt , to taste", "1 tablespoon Coriander (Dhania) Leaves , chopped", "Oil , as required", "1 tablespoon Ajwain (Carom seeds)", "2 Fresh Red chillies"]'::jsonb, ARRAY['cashew nuts', 'salt', 'red chillies', 'coriander (dhania) leaves', 'ajwain (carom seeds)', 'cloves garlic', 'curry leaves', 'sugar', 'onion', 'tamarind paste', 'potato (aloo)', 'sunflower oil']::text[], '["To begin with the Tamarind Chilli Potato, first lets boil the potatoes and keep them aside.In a pan add some oil and potatoes once the oil is hot.", "Saute them till they turn into golden brown.Take the potatoes from the pan and keep it aside.In the same pan add some more oil and add carom seeds once the oil is hot.Now add cashew nuts and saute till it becomes golden brown, now add garlic and onions and saute till they are transparent.It is time to add the red chillis and curry leaves leave it for a minute so the spice is induced in the onions.", "After this add tamarind paste and some sugar, combine the entire mixture and add salt as per your taste.As the tamarind paste cooks well you can add the potatoes and allow it to cook for 2 \u2013 3 minutes.Put of the flame and add the coriander leaves a last and taste them and add some salt if needed as per your taste.Your Tamarind Chilli Potato is ready, transfer it to a serving plate and serve them.You can serve the Tamarind Chili Potato as a starter or even as a subji for roti, phulka and naan."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Tamrind_Chilli_Potato.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/434.Tamrind_Chilli_Potato.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kolkata Chicken Chaap Recipe  - Slow Cooked Chicken Legs', 'kolkata-chicken-chaap-recipe-slow-cooked-chicken-legs', 'Kolkata Chicken Chaap Recipe is a lip-smacking recipe of slow cooked marinated chicken legs with bone. Chicken chaap is an adopted Nawabi dish which is renowned in Calcutta/Kolkata due to historical reign of Bengal Nawabs. There are many restaurants in Kolkata with their own famous recipe for a chicken chaap, and here is my version of this favourite dish. Biryani is locally served with a Royal Chicken chaap for sides, without which the biryani is believed to be incomplete.', '["2 Chicken legs", "1 cup Hung Curd (Greek Yogurt)", "1 Dry Red Chilli", "2 Bay leaves (tej patta)", "1 inch Cinnamon Stick (Dalchini)", "1 Onion , ground to paste", "2 inch Ginger , grated or paste", "5 cloves Garlic , minced", "2 teaspoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "1-1/2 tablespoon Cashew nuts , ground to paste", "3 tablespoons Poppy seeds , soaked in warm water for 20 minutes", "Kewra Water , a few drops", "Ghee , or butter as required for cooking", "Salt , to taste", "1 pinch Sugar"]'::jsonb, ARRAY['salt', 'hung curd (greek yogurt)', 'bay leaves (tej patta)', 'kewra water drops', 'red chilli powder', 'cloves garlic', 'dry red chilli', 'cashew nuts ground paste', 'poppy seeds water', 'sugar', 'cinnamon stick (dalchini)', 'onion', 'ghee butter', 'ginger paste', 'turmeric powder', 'garam masala powder', 'chicken legs']::text[], '["To begin making Kolkata Chicken Chaap Recipe , first soak poppy seeds into warm water for 20 minutes.Meanwhile prepare the fresh Garam masala quickly.", "You may also use the stored garam masala but the freshly made garam masala is\u00a0 more flavourful.Clean the chicken, wash well, pat them dry and with a fork, prick all over the chicken till the bone in several places.In a blender, take the soaked poppy seeds and cashewnut together to make a smooth paste, by adding a little water.", "Take it out in a bowl.", "With the help of a little water, grind coarsely chopped onions, ginger and garlic cloves in a fine paste.In a big mixing bowl, add curd, ground onion-ginger-garlic paste, red chilli powder, garam masala powder, a little salt and a pinch of sugar and whisk with a hand whisk or a fork till evenly combined.Pour this marinade all over the chicken, mix well.", "Add a spoonful of ghee on it and coat the chicken, this will keep the chicken soft and juicy after being cooked.", "Cover and put the chicken in refrigerator for a minimum of 5 hours.", "You can marinate chicken overnight to get best results when the recipe is done.Once done, take the marinated chicken out from the refrigerator and let them thaw to almost room temperature before cooking.In a wide kadai or handi add about 2 tablespoons of ghee on medium heat.", "Once the ghee is hot, temper with bay leaf, whole red chili and cinnamon stick and stir for a little while.After the aroma of cinnamon rises, shake off the marinade from the chicken legs and put them in hot ghee.", "Turn the heat to medium and slow cook for about 15- 20 minutes flipping the legs from time to time.Once the leg is almost cooked, add the remaining marinade and cook for about 10 more minutes for all the raw smell of onion ginger garlic to disappear.Now add cashew and poppy seed paste.", "Cook for another 20-30 minutes and till the spices are dried and the dish comes together and smells divine.", "Add 1 or 2 drops of kewra water, stir and switch off.Serve Kolkata Chicken Chaap Recipe (Slow Cooked Marinated Chicken Legs) with\u00a0Mutton Biryani Recipe\u00a0and\u00a0Tomato Onion Cucumber Raita Recipe\u00a0for a complete meal."]'::jsonb, 100, 'Bengali', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/usashis-gmail.com/Chicken_ChaapChaanpMarinated_chicken_legs_slow_cooked_in_Kolkata_style_original.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/435.Chicken_ChaapChaanpMarinated_chicken_legs_slow_cooked_in_Kolkata_style_original.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Drumstick Leaves Kadhi Pakora Recipe - Moringa Kadhi Pakora', 'drumstick-leaves-kadhi-pakora-recipe-moringa-kadhi-pakora', 'The Moringa Kadhi Pakora comforting spicy yogurt based curry cooked with pakora that is cooked  along with drumstick leaves and tempered with cumin seeds and green chilli.', '["1 cup Drumstick Leaves (Moringa/Murungai Keerai)", "3/4 cup Gram flour (besan)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/4 Enos Fruit Salt , or baking powder", "1 teaspoon Ajwain (Carom seeds)", "1/4 teaspoon Asafoetida (hing) , Asafoetida", "Oil , for frying", "1 cup Curd (Dahi / Yogurt)", "1/4 cup Gram flour (besan)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , as required", "1 teaspoon Ghee", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Fresh Red Chilli", "2 inch Cinnamon Stick (Dalchini)", "1 sprig Curry leaves", "Coriander (Dhania) Leaves , for garnish"]'::jsonb, ARRAY['salt', 'drumstick leaves (moringamurungai keerai)', 'ghee', 'mustard seeds', 'coriander (dhania) leaves', 'enos fruit salt baking powder', 'ajwain (carom seeds)', 'red chilli powder', 'gram flour (besan)', 'curd', 'curry leaves', 'cinnamon stick (dalchini)', 'red chilli', 'asafoetida (hing) asafoetida', 'turmeric powder', 'sunflower oil']::text[], '["To begin making Drumstick Leaves Kadhi Pakoda Recipe, the drumstick leaves pakoda should be prepared.First wash the drumstick leaves and chop the leaves.", "Take a large bowl and mix all the ingredients for the pakoras - Gram Flour, Red Chili powder, Drumstick leaves, Turmeric powder, Enos Fruits salt, Asafoetida, Salt and Carom seeds.To this mixture, add the water a few drops at a time.", "The final mixture should neither dry or soggy.", "Divide the mixture into 8-10 pakora balls.", "Into a paniyaram pan, add a few drops of oil into the cavities and add the pakora into the cavities and pan fry them until it is\u00a0 brown and crisp on all sides.Once the moringa pakoras are done, keep them aside.The next step is to make the KadhiIn a saucepan add the curd, gram flour, turmeric powder and salt.", "Add 2 cups of water and mix the kadhi mixture well.", "Turn the heat to high and keep whisking the kadhi until it becomes smooth and slightly thick.", "Once the kadhi begins to thicken, turn the heat low and allow the kadhi to simmer for 10 minutes.", "While the kadhi is simmering, heat ghee in a tadka pan; Add the mustard seeds, cumin seeds, cinnamon stick, red chillies and curry leaves.", "Allow them to crackle.Add this to the kadhi mixture and also drop in the moringa pakoras.", "Give the Morinka Kadhi Pakora a brisk boil and turn off the heat.", "Once done, give the\u00a0Drumstick Leaves Kadhi Pakoda\u00a0 a taste and adjust the salt and spices accordingly.", "Once done, serve hot.Serve\u00a0Drumstick Leaves Kadhi Pakoda Recipe along with\u00a0Green Moong Dal Khichdi\u00a0for a delicious weeknight dinner."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/ruby_pathak-yahoo.com/Drumstick_Leaves__Kadhi_Pakoda.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/436.Drumstick_Leaves__Kadhi_Pakoda.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bajra Aloo Paratha Recipe', 'bajra-aloo-paratha-recipe', 'Bajra is known to provide heat to the body and so the consumption of this grain in any form is usually done in winters. Bajra Aloo Paratha is one such delicacy which is very delicious and healthy and is made using millet flour which is flavoured with potato and seasoned with spices to enhance more of the flavours. It is an easy-to-cook recipe and can be served on its own or with any chutney of your choice. Bajra Aloo Paratha makes a perfect healthy breakfast for winters and an ideal meal to be carried in a lunch box.', '["2 cups Bajra Flour ( Pearl Millet)", "1/2 cup Whole Wheat Flour", "1 cup Potatoes (Aloo) , boiled and mashed", "1 cup Methi Leaves (Fenugreek Leaves) , chopped finely", "1 teaspoon Green Chilli , coarsely crushed", "1 teaspoon Ginger , grated", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Ajwain (Carom seeds)", "1/2 teaspoon Chaat Masala Powder", "Salt , to taste", "Lukewarm Water , as required", "Oil , for smearing"]'::jsonb, ARRAY['s bajra flour', 'pearl millet', 'whole wheat flour', 'potatoes', 'aloo', 'methi leaves', 'fenugreek leaves', 'green chilli', 'ginger', 'red chilli powder', 'turmeric powder', 'haldi', 'cumin seeds', 'jeera', 'ajwain', 'carom seeds', 'chaat masala powder', 'salt', 'lukewarm water', 'oil']::text[], '["To begin with Bajra Aloo Paratha, firstly add all the ingredients in a large bowl and mix everything well.Gradually, add warm water little at a time and start kneading the dough.", "Knead well to form a soft dough.Divide the dough into equal sized balls depending upon the size of the paratha you prefer to make.Dust the ball well and roll out into a paratha depending upon the thickness you prefer.If you find it difficult to roll it with rolling pin, use your hands and pat the dusted ball uniformly to make parathas.Heat the griddle well.", "Gently place the rolled paratha on the griddle and cook until brown spots appear.", "Flip and cook.Apply oil and fry on both the sides until they are cooked well.Serve Bajra Aloo Paratha with\u00a0Tomato Onion and Cucumber Raita\u00a0and\u00a0Dhaniya Pudina Chutney."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Farrukh_Aziz_Ansari/Bajra_Aloo_Paratha.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/437.Bajra_Aloo_Paratha.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Malvani Kurkuri Bhindi Recipe - Moongphali Bhindi Sabzi', 'malvani-kurkuri-bhindi-recipe-moongphali-bhindi-sabzi', 'Malvani Kurkuri Bhindi Recipe is a delicious lady finger recipe using the aromatic malvani masala from the coastal region of Maharashtra. The malvani masala is pungent and quite aromatic as compared to the regular garam masala.', '["500 grams Bhindi (Lady Finger/Okra) , washed and cut into small pieces", "1/4 cup Roasted Peanuts (Moongphali) , roasted and crushed", "2 tablespoons Oil", "Ingredients to prepare malvani masala", "1 tablespoon Coriander (Dhania) Seeds", "2 Dry Red Chilli", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Fennel seeds (Saunf)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Ajwain (Carom seeds)", "1/4 teaspoon Whole Black Peppercorns", "1/4 teaspoon Nutmeg powder", "1/4 teaspoon Nagkesar/cassia buds", "1/4 teaspoon Asafoetida (hing)", "1 Cinnamon Stick (Dalchini)", "3 Cloves (Laung)", "1 Star anise", "1 Stone flower", "1 Black cardamom (Badi Elaichi)"]'::jsonb, ARRAY['s bhindi', 'lady finger/okra', 'roasted peanuts', 'moongphali', 's oil', 'ingredients to prepare malvani masala', 'coriander', 'dhania', 'dry red chilli', 'cumin seeds', 'jeera', 'fennel seeds', 'saunf', 'mustard seeds', 'rai/ kadugu', 'ajwain', 'carom seeds', 'whole black peppercorns', 'nutmeg powder', 'nagkesar/cassia buds', 'asafoetida', 'hing', 'cinnamon stick', 'dalchini', 'laung', 'star anise', 'stone flower', 'black cardamom', 'badi elaichi']::text[], '["To begin making the Malvani Kurkuri Bhindi Recipe, we first prepare the malvani masala.Heat a small pan and dry roast the ingredients mentioned in the malvani masala table in low heat.", "Once\u00a0 cool, grind it to a fine powder using a hand blender and keep aside.In the same pan dry roast the de skinned peanuts in low heat and once its cool, roughly pound the peanuts using a mortar and pestle and keep aside.Now, heat oil in a wide pan on medium flame.", "Add the cut bhindi to the oil and saute until it is half cooked and becomes non sticky.", "This will take around 10 minutes.Now, add the freshly prepared malvani masala, season with salt and saute until the bhindi is fully cooked and turns crispy.Switch off the flame, add the crushed roasted peanuts and mix well.Serve the Malvani Kurkuri Bhindi Recipe along with Steamed Rice and\u00a0Dal Tadka\u00a0for a simple yet yummy weeknight dinner."]'::jsonb, 30, 'Malvani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Malvani_Bhindi_Masala_Recipe_Moongphali_Bhindi_Sabzi-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/438.Malvani_Bhindi_Masala_Recipe_Moongphali_Bhindi_Sabzi-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Arbi Shimla Mirch Sabzi Recipe – Colocasia Capsicum Sabzi', 'arbi-shimla-mirch-sabzi-recipe-colocasia-capsicum-sabzi', 'Arbi Shimla Mirch Sabzi Recipe is a variation to the aloo capsicum dry sabzi that is made often at our households.', '["300 grams Colocasia root (Arbi)", "1 Green Bell Pepper (Capsicum) , diced", "1 Tomato , chopped", "1 inch Ginger , grated", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "Salt , according to taste", "Oil , for cooking"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'red chilli powder', 'colocasia root (arbi)', 'green bell pepper (capsicum)', 'coriander powder', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Arbi Shimla Mirch Sabzi Recipe, first we will cook the arbi in a pressure cooker.Into the pressure cooker, add arbi and 1/2 cup water and pressure cook for 4 to 5 whistles and turn off the heat.Allow the pressure to release naturally.", "Once the pressure has released, peel and dice the arbi and keep aside.", "Allow it to cool completely and firm up.The next step in making the Arbi Shimla Mirch Sabzi Recipe, heat about a tablespoon of oil in a heavy bottomed pan; add the ginger and capsicum.Saute for a few minutes until the capsicum is tender and begin to start changing color.", "The capsicum would be lightly browned around the edges and softened too.Once the capsicum has softened, add in tomatoes and sprinkle some salt and keep sauteing until the tomatoes become mushy.", "At this point, stir in the boiled arbi, turmeric powder, coriander powder and garam masala powder, red chilli powder and salt.Stir the Arbi Shimla Mirch Sabzi along with the spices until well coated.", "Check the salt and adjust accordingly.Cover the pan; turn the heat to low and simmer the Arbi Shimla Mirch Sabzi Recipe for about 5 minutes, stirring occasionally.Once done, turn off the heat, stir in the freshly chopped coriander leaves and transfer the Arbi Shimla Mirch Sabzi to a serving platter and serve hot.Serve\u00a0Arbi Shimla Mirch Sabzi\u00a0Recipe\u00a0with\u00a0Punjabi Dal Tadka,\u00a0Missi Roti,\u00a0Beetroot, Carrot & Cucumber Salad with Peanuts\u00a0and Rice for a delicious weekday lunch or dinner with your family."]'::jsonb, 55, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Simla_Mirchi_Arbi_Sabzi_Recipe__Capsicum__Colocasia_Dry_Curry_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/439.Simla_Mirchi_Arbi_Sabzi_Recipe__Capsicum__Colocasia_Dry_Curry_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chicken Sholay Kebab Recipe', 'chicken-sholay-kebab-recipe', 'Chicken Sholay Kebab Recipe is a finger licking good kebab made with boneless chicken, that is popular in South India. In this recipe, Chicken is coated in a spicy purpose flour, gram flour and rice flour batter which is flavored with some spices and then deep fried in hot oil.', '["300 grams Boneless chicken , cut into chunks", "4 sprig Curry leaves", "2 inch Ginger", "6 cloves Garlic", "2 Green Chillies", "1 tablespoon Rice flour", "3 tablespoons All Purpose Flour (Maida)", "1 tablespoon Gram flour (besan)", "2 tablespoons Kashmiri Red Chilli Powder", "Salt , to taste", "1 teaspoon Sambar Powder", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "Oil , as required, for deep frying"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'ginger', 'boneless chicken', 'kashmiri red chilli powder', 'sambar powder', 'flour (maida)', 'cloves garlic', 'gram flour (besan)', 'curry leaves', 'coriander powder', 'rice flour', 'green chillies', 'sunflower oil']::text[], '["To begin making the Chicken Sholay Kebab Recipe, keep the boneless chicken cubes, washed and cleaned.\u00a0*To make the Ginger Garlic Green Chilli Paste:In a mixer jar, combine the ginger, garlic and green chilli with about 2 tablespoons of water and grind it to a smooth mixture.\u00a0*To make the batter for the Chicken Sholay Kebab:In a mixing bowl, combine the besan and rice flour along with the maida.", "Into this bowl, add the\u00a0kashmiri red chilli powder,\u00a0salt to taste,\u00a0sambar powder, coriander powder, cumin powder and ginger-garlic green chilli paste.", "Add just enough water to make a thick batter of coating consistency.Meanwhile, heat oil in a deep frying pan on medium-high heat.", "Once the oil is well heated, reduce the flame to medium-low.", "Now dunk the boneless chicken chunks into the batter and gradually lower the well coated chicken into the hot oil.", "Deep fry on medium heat, until the Chicken Sholay Kebab are crisp and deep brown in colour.", "Drain the Chicken Sholay Kebab on an absorbent paper, so that it soaks up the excess oil.In the same hot kadai, fry the curry leaves until crisp and drain\u00a0on an absorbent paper.Top the Chicken Sholay Kebab with the crispy fried curry leaves and serve hot.Serve\u00a0Chicken Sholay Kebab as an appetizer or as part of a meal, along with\u00a0Steamed Rice, and\u00a0Chettinad Style Poondu Rasam Recipe\u00a0for a perfect Sunday afternoon lunch."]'::jsonb, 30, 'South Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/Chicken_Sholay_Kebab_Recipe_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/440.Chicken_Sholay_Kebab_Recipe_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Beetroot Paneer Curry Recipe In Coconut Milk', 'beetroot-paneer-curry-recipe-in-coconut-milk', 'Beetroot and Paneer Curry in Coconut milk is a delicious combination of steamed beetroot and paneer. It makes a perfect curry to be served along with rice or even phulka''s. The flavors of the vegetable have lovely South Indian notes, with the addition of curry leaves and ginger along with baby onions.', '["200 grams Paneer (Homemade Cottage Cheese) , cubed", "2 Beetroot , peeled and diced", "1 Onion , finely chopped", "2 Green Chillies , slit", "1 inch Ginger , grated", "2 cloves Garlic , finely chopped", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "200 ml Coconut milk", "2 teaspoons Oil , for cooking", "Salt , to taste", "Red Chilli powder , to taste"]'::jsonb, ARRAY['s paneer', 'homemade cottage cheese', 'beetroot', 'onion', 'reen chillies', 'ginger', 's garlic', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'garam masala powder', 'coconut milk', 's oil', 'salt', 'red chilli powder']::text[], '["To begin making the Beetroot and Paneer Curry Recipe in Coconut Milk, we will first cook the vegetables together in a pressure cooker.Place the beetroot, onions, ginger, garlic and green chillies into a pressure cooker adding half a cup of water, turmeric powder and salt.", "Cook for about 2 whistles.", "After two whistles, turn the heat to low and simmer for 3 to 4 minutes.Turn off the heat and allow the pressure to release naturally.Once the pressure releases from the cooker, open the cooker, stir in the coconut milk, paneer,\u00a0coriander powder, garam masala powder and bring the beetroot curry to a brisk boil.Turn off the heat and transfer the beetroot and paneer curry to a serving bowl.Serve Beetroot And Paneer Curry along with\u00a0Chilli Cheese Stuffed Kulcha Recipe\u00a0or\u00a0Peas Pulao Recipe - North Indian Matar Pulao\u00a0and\u00a0Coriander Tadka Raita Recipe\u00a0for a complete meal."]'::jsonb, 55, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Beetroot_and_Paneer_Curry_Recipe_in_Coconut_Milk-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/441.Beetroot_and_Paneer_Curry_Recipe_in_Coconut_Milk-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sankara Meen Kuzhambu Recipe', 'sankara-meen-kuzhambu-recipe', 'Red Snapper is widely available fish and named after its snapping teeth. It’s fine texture and delicate flavor makes it unique. The fish can be broiled, grilled, pan-fried, steamed or can prepared curry. Sankara Meen Kuzhambu is prepared by simmering fish pieces with grounded masalas. The curry tastes delicious with plain white rice. This low-calorie fish is a great source of lean protein, potassium, and omega -3 fatty acids.', '["1 Red snapper fish , cut into pieces", "1 cup Shallots", "1 Tomato , cubed", "1 Kokum (Malabar Tamarind) , lemon sized", "3 tablespoons Gingelly oil", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Dagad phool (/pathar phool/black stone flower)", "1/4 teaspoon Fennel seeds (Saunf)", "1/2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Ginger Garlic Paste", "1/4 teaspoon Turmeric powder (Haldi)", "2 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste"]'::jsonb, ARRAY['red snapper fish', 'shallots', 'tomato', 'kokum', 'malabar tamarind', 's gingelly oil', 'mustard seeds', 'rai/ kadugu', 'dagad phool', '/pathar phool/black stone flower', 'fennel seeds', 'saunf', 'cumin seeds', 'jeera', 'ginger garlic paste', 'turmeric powder', 'haldi', 'red chilli powder', 'coriander powder', 'dhania', 'salt']::text[], '["To begin making the Sankara Meen Kuzhambu recipe, wash and clean the fish pieces twice or thrice.", "Soak fish pieces in water with turmeric for about 30 minutes.In a non-stick kadai/wok, add oil.", "Once the oil is hot, add mustard seeds and black stone flower.", "Let it splutter.Add shallots and cook until they become translucent.", "Add ginger garlic paste and saute until the raw smell goes off.Slide in the chopped tomatoes and cook until they become mushy.", "Now, add all spice powders and saute them until raw smell goes off.Soak KoKum tamarind in hot water for about an hour and extract juice.", "It\u2019s hard to extract juice from kodum puli.", "I soaked tamarind water for about an hour, grounded them into a fine paste and added them into the wok.Add tamarind juice and a cup of water.", "Cook with the lid covered.", "Season it with a required amount of salt.Once the curry starts boiling, add fish pieces and cook over low flame until the fish pieces are cooked well and oil separates from the curry.Serve Sankara Meen Kuzhambu Recipe with plain rice and Beetroot Thoran for your weekday lunch."]'::jsonb, 50, 'Tamil Nadu', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/KarthikaKrishnan/Sankara_Meen_Kuzhambhu.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/442.Sankara_Meen_Kuzhambhu.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dim Posto Recipe - Bengali Egg Curry With Poppy Seeds', 'dim-posto-recipe-bengali-egg-curry-with-poppy-seeds', 'Dim Posto is a delicious Bengali Style Egg Curry which has a spicy poppy seed masala and simmered in spices. It is an easy to make and delicious dish that is usually served along with Steamed Rice.', '["4 Whole Eggs", "2 Potatoes (Aloo) , peeled and diced", "1/4 cup Poppy seeds , made into paste", "1/4 cup Homemade tomato puree", "1 teaspoon Panch Phoran Masala", "1/2 teaspoon Turmeric powder (Haldi)", "1 Onion , roughly chopped", "1 inch Ginger , finely chopped", "4 cloves Garlic", "2 Green Chilli , chopped", "1/2 cup Mustard oil", "1 Dry Red Chilli", "1 Bay leaf (tej patta)", "1 teaspoon Sugar , optional", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'green chilli', 'mustard oil', 'bay leaf (tej patta)', 'cloves garlic', 'dry red chilli', 'sugar', 'poppy seeds', 'onion', 'panch phoran masala', 'potato (aloo)', 'eggs', 'turmeric powder']::text[], '["To begin making Dim Posto Recipe - Bengali Egg Curry, first we need to hard boil the eggs.", "Add salt or baking soda while boiling the egg it will prevent egg from breaking.", "This will take 10 to 15 minutes.Make a paste of the onions, ginger, garlic, green chillies and keep aside.Make the paste of the poppy seeds by adding a little water and keep aside.After its done, put the eggs in cold water and cool down.", "Peel those eggs and rub some salt over it.", "Also rub some salt on the peeled and sliced potatoes.Heat 2 tablespoons oil in a heavy bottomed pan.", "Add eggs and fry till it turns light brown in colour.", "Take out and drain in a kitchen towel.In same oil, add diced potatoes, sprinkle some salt and fry them until golden brown and crisp on low heat.", "Take the potatoes out and keep aside.Add some more oil into the same pan, add dry red chili and bay leaf.", "Cook for about 15 seconds.", "After 15 seconds, add the onion ginger garlic green chilli paste.", "Let it cook for 2 to 3 minutes until the raw smell from the onions go away.", "Stir in the turmeric powder and panch phoran into the onion paste and saute for a couple of more minutes.After 2 to 3 minutes, tomato puree, salt and sugar.", "Saute for a couple of minutes and then add the poppy seed paste and the fried eggs.", "Simmer the\u00a0Dim Posto Recipe for a good 4 to 5 minutes until it forms a good masala.", "Adjust the consistency of the Dim Poshto by adding 1/2 cup of water or more.", "Check the salt and spices and adjust according to taste.", "Once done, turn off the heat and transfer the\u00a0Dim Posto Recipe into a serving bowl and serve hot.Serve Dim Posto Recipe - Bengali Egg Curry\u00a0along with\u00a0Steamed Rice\u00a0and\u00a0Satvik Carrot Sprout Salad\u00a0for an everyday meal."]'::jsonb, 65, 'Bengali', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/usashis-gmail.com/Hasher_Dim_Posto__Duck_egg_curry_with_poppy_seed_paste.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/443.Hasher_Dim_Posto__Duck_egg_curry_with_poppy_seed_paste.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Panasa Pottu Aava Koora Recipe - Andhra Style Mustard Flavoured Raw Jackfruit Curry', 'panasa-pottu-aava-koora-recipe-andhra-style-mustard-flavoured-raw-jackfruit-curry', 'Panasa Pottu Ava Koora Recipe is shredded Raw Jackfruit cooked in a flavoursome mustard coconut masala, that is essentially Andhra Style.', '["1 cup Jackfruit Raw (Kathal) , chopped finely", "1 tablespoons Tamarind Paste", "3 Green Chillies , slit", "1 tablespoon Oil", "1/4 cup Water", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 teaspoon Chana dal (Bengal Gram Dal)", "1 Dry Red Chilli", "1/4 teaspoon Asafoetida (hing)", "1 sprig Curry leaves", "Salt , to taste", "8 to 10 Cashew nuts , optional", "1/4 teaspoon Turmeric powder (Haldi)", "1 tablespoons Mustard seeds (Rai/ Kadugu)", "1 tablespoon Sesame seeds (Til seeds)", "1 Dry Red Chilli"]'::jsonb, ARRAY['jackfruit raw', 'kathal', 's tamarind paste', 'reen chillies', 'oil', 'water', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'chana dal', 'bengal gram dal', 'dry red chilli', 'asafoetida', 'hing', 'curry leaves', 'salt', 'to 10 cashew nuts', 'turmeric powder', 'haldi', 's mustard seeds', 'sesame seeds', 'til seeds']::text[], '["To begin making the\u00a0Panasa Pottu Aava Koora, let us first make the Aava Paste.\u00a0*For the\u00a0Aava Paste:In a small bowl, soak mustard seeds, sesame seeds, and red chili in hot water for 15 minutes.", "After 15 minutes, drain the water and transfer the\u00a0mustard seeds, sesame seeds, and red chili into a mixer-jar and grind to a smooth paste, using a little water if required.", "Transfer to a bowl and set aside.\u00a0*For the Jackfruit\u00a0Let us now cut the jackfruit, to do that we have to first, grease our hands and the knife that we are going to use, with some oil.This important tip ensures that the hands don''t get sticky from the natural fruit latex/sap present in the fruit does not get onto your hands and makes the cutting process hassle-free.", "Keep a bowl of water mixed with some salt, ready to put the cut raw jackfruit pieces to avoid discolouration of the fruit.Now that your hands and knife are well greased, cut the the jackfruit in half, discard the skin and start making 1 inch pieces and soak them in the salted water.Place the jackfruit\u00a0in a pressure cooker with 1/4 cup of water, tamarind paste\u00a0,turmeric powder, & pressure\u00a0cook for 3 whistles and turn off the flame.Allow the pressure to release naturally.", "Drain any water from the jackfruit.Finely chop the jackfruit and set aside.\u00a0*For the Panasa Pottu Aava Koora preparation:In a pan, heat oil\u00a0on medium flame, add the mustard seeds and allow it to crackle, next add\u00a0in the asafoetida, chana dal and urad dal and allow them to turn into a light brown colour.", "Once the dals have turned brown, add curry leaves and green chilies.Finally, add in the\u00a0finely chopped raw jackfruit that was cooked earlier and\u00a0add the prepared aava paste and give a quick mix.", "Cook covered for low flame for not more than 5 minutes.Add fried cashew nuts, mix everything well.", "Serve this\u00a0Panasa Pottu Aava Koora\u00a0Recipe\u00a0along with\u00a0Steamed Rice\u00a0and\u00a0Arachuvitta Sambar Recipe\u00a0and\u00a0Elai Vadam Recipe\u00a0for a complete South Indian lunch.", "For an\u00a0Indian Diabetic\u00a0meal, serve\u00a0Panasa Pottu Aava Koora\u00a0Recipe\u00a0along with\u00a0Foxtail Millet Lemon Rice Recipe\u00a0and\u00a0Palak Raita Recipe\u00a0for a weekday lunch."]'::jsonb, 20, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/anu.mallajosyula-gmail.com/Panasapottu_Aavakura.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/444.Panasapottu_Aavakura.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mixed Vegetable Pulao Recipe', 'mixed-vegetable-pulao-recipe', 'The Mixed Vegetable Pulao Recipe is a simple and quick to cook dish for the busy weeknights. Pack the pulao with lots of steamed vegetables as it gives you the required nutrition for the day. You can also pack this for your Lunch Box in the morning.', '["1 cup Brown Rice", "2 tablespoons Ghee", "2 cloves Garlic , grated", "2 Green Chillies , slit", "2 Cloves (Laung)", "2 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta)", "Salt , to taste", "1 Mint Leaves (Pudina) , small bunch, chopped", "10 Green beans (French Beans) , diced small", "2 cups Cauliflower (gobi) , florets", "1 Carrots (Gajjar) , diced small"]'::jsonb, ARRAY['green chillies', 'brown rice', 'salt', 'green beans (french beans)', 'ghee', 'cardamom (elaichi) podsseeds', 'bay leaf (tej patta)', 'cloves garlic', 'carrot', 'cinnamon stick (dalchini)', 'mint leaves (pudina)', 'cloves (laung)', 'cauliflower (gobi) florets']::text[], '["To begin making the Mixed Vegetable Pulao Recipe, we will first wash and soak rice in 2 cups of water for half an hour.While the rice is soaking, steam the vegetables with a bit of salt and keep aside.Make a powder of all the spices (cloves, cardamom and cinnamon) using a pestle and mortar.", "Keep aside.After half an hour, into a large saucepan heat 2 tablespoons of ghee.", "Add the grated garlic and the powdered spices.", "Stir-fry for a few seconds.Next add in the rice, salt , green chillies and the bay leaves along with the water it was soaked in.", "Turn the heat to high and allow the rice mixture to come to a boil.Once it comes to a boil, turn the heat to low, cover the pan and simmer the rice until the rice absorbs all the water.Once the water is absorbed, check if the pulao is cooked completely, to suit your taste.", "If it needs to be softer, you can add in a little more water and cook for a bit more time.Turn off the heat and allow the pulao to rest for at least 10 minutes, this will help the rice to become a little stiff and remain as grains.Finally stir in the steamed vegetables and chopped mint leaves and check the salt and adjust to suit your taste.Transfer the Vegetable Pulao to a serving bowl and serve hot.", "Serve\u00a0Mixed Vegetable Pulao\u00a0along with\u00a0Boondi Raita,\u00a0Tomato Onion Cucumber Raita\u00a0or any other raita of your choice and a roasted papad for everyday meals."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Mixed_Vegetable_Pulav_Recipe-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/445.Mixed_Vegetable_Pulav_Recipe-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Kokur T Nadir Recipe-Chicken and Lotus Stem Curry', 'kashmiri-kokur-t-nadir-recipe-chicken-and-lotus-stem-curry', 'Kashmiri Kokur T Nadir is an authentic Chicken curry with lotus stem that belongs to Kashmiri Cuisine. It''s a kind of yakhni that is made with chicken and nadru/lotus stem. Ideally enjoyed with rice and roti, this chicken curry is aromatic and full of Kashmiri flavours.', '["2 cups Lotus Stem , (nadru or kamal kakdi) peeled & sliced", "750 grams Chicken , cut into medium pieces", "2 cups Water", "1 Bay leaf (tej patta)", "1/4 teaspoon Fennel seeds (Saunf)", "2 Black cardamom (Badi Elaichi)", "4 Cloves (Laung)", "1 inch Ginger , chopped", "3 tablespoon Mustard oil", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "1-1/2 cups Curd (Dahi / Yogurt) , whisked", "2 teaspoon Kashmiri Red Chilli Powder", "2 teaspoon Fennel Powder", "1 teaspoon Dry ginger powder", "Salt , to taste", "1/2 teaspoon Mint powder (Pudina)", "1 teaspoon Ajwain (Carom seeds)", "3 sprig Coriander (Dhania) Leaves , chopped for garnish"]'::jsonb, ARRAY['black cardamom (badi elaichi)', 'salt', 'ginger', 'kashmiri red chilli powder', 'mustard oil', 'bay leaf (tej patta)', 'fennel seeds (saunf)', 'asafoetida (hing)', 'ajwain (carom seeds)', 'lotus stem (nadru kamal kakdi)', 'water', 'curd', 'fennel powder', 'dry ginger powder', 'coriander (dhania) leaves', 'chicken', 'cumin seeds (jeera)', 'cloves (laung)', 'mint powder (pudina)']::text[], '["To begin making the Kashmiri Kokur T Nadir recipe, wash and clean the chicken.Mix the chicken with kashmiri red chilli powder, fennel powder and dry ginger powder in a bowl and keep it for marination for about 30 minutes.Put the sliced lotus stem in warm water for few minutes to remove inside dirt and impurities.Strain Lotus stem slices and pressure cook them along with 2 cups of water, bay leaf, fennel seeds, black cardamom, cloves, ginger slices and salt as per taste.", "Cook till the cooker releases 2 to 3 whistles.", "Leave it aside for pressure to settle down.Heat mustard oil in a heavy bottomed pan.", "Add cumin seeds and asafoetida powder into it, mix it well and cook it for 8 to 10 seconds.Add the above marinated chicken along with the curd mix and cook in medium to low flames till yogurt starts to thicken and oil starts leaving from sides.Now add the boiled and strained Lotus stem into the gravy and cook it on low flame for five minutes, stirring occasionally. (you can add the spices as well)\u00a0Now put caraway seeds into a Mortar and Pestle and crush them to form a powder.", "Also crush dry Mint leaves between your hand and add into the gravy.", "Adjust salt as needed and cook till the curry starts to thicken.", "Once it is done, switch off the stove and garnish with some fresh coriander leaves.", "Serve hot.Serve Kashmiri Kokur T Nadir along with\u00a0Kashmiri Dum Monji,\u00a0Steamed Rice\u00a0and\u00a0Phulkas\u00a0for a weekday meal with your family."]'::jsonb, 70, 'Kashmiri', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/shaheen_ali/Kashmiri_Kokur_t_Nadir__Chicken_and_Lotus_Steam_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/446.Kashmiri_Kokur_t_Nadir__Chicken_and_Lotus_Steam_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Punjabi Style Lobia Masala Recipe (Black Eyed Peas Masala)', 'punjabi-style-lobia-masala-recipe-black-eyed-peas-masala', 'Punjabi Style Lobia Masala is a very simple and quick recipe which can be made in a jiffy on the weekdays. This recipe is tasty and high in protein and can be served even when you have guests at your home for a sudden dinner.', '["2 cups Black Eyed Beans (Lobia) , boiled", "2 tablespoons Oil", "1 tablespoon Cumin seeds (Jeera)", "1 tablespoon Fennel seeds (Saunf)", "1 inch Cinnamon Stick (Dalchini)", "1 Onion , finely chopped", "2 Green Chillies , slit in between", "1 tablespoon Ginger Garlic Paste", "1 tablespoon Red Chilli powder", "1 tablespoon Turmeric powder (Haldi)", "1 tablespoon Salt", "1 tablespoon Coriander Powder (Dhania)", "1 tablespoon Garam masala powder", "1/2 tablespoon Cumin powder (Jeera)", "1/2 tablespoon Sugar", "1/2 tablespoon Tamarind Paste", "1/2 cup Homemade tomato puree", "1/2 cup Milk"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'fennel seeds (saunf)', 'milk', 'red chilli powder', 'ginger garlic paste', 'sugar', 'green chillies between', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'onion', 'tamarind paste', 'coriander powder', 'turmeric powder', 'black eyed beans (lobia)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Punjabi Style Lobia Masala recipe, heat oil in a wok/kadai.Add cumin seeds, fennel seeds, cinnamon and saute for a minute.", "Add onion and green chillies.Add ginger garlic paste and saute them till onion turn golden in colour.Add all dry spices including turmeric powder, red chilli powder, garam masala, coriander powder, cumin powder, sugar, salt and tamarind paste.", "Mix it well and add tomato puree.Cook mixture till oil separates from it.", "Add cooked black eyed peas(lobia) and mix well.", "Cook for 2-3 minutes.Add milk and mix well.", "Cook on slow heat for 5 minutes.", "Lobiya is ready to serve.Serve Punjabi Style Lobia Masala along with\u00a0Phulka\u00a0and\u00a0Kachumber Salad\u00a0for a weekday lunch or dinner."]'::jsonb, 165, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Punjabi_style_lobia_masalaBlack_eyed_Peas_Masala_in_Punjabi_Style.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/447.Punjabi_style_lobia_masalaBlack_eyed_Peas_Masala_in_Punjabi_Style.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Cabbage & Buttermilk Curry Recipe', 'cabbage-buttermilk-curry-recipe', 'Cabbage & Buttermilk Curry Recipe is one of my mother’s creation adapted from Gujarati kadi recipe. To prepare the curry, spicy buttermilk is mixed with seasoned shredded cabbage.This easy and healthy buttermilk curry is great when had with hot chapati, phulka or plain cooked rice.', '["1 Cabbage (Patta Gobi/ Muttaikose) , medium sized, shredded", "4 Green Chillies , slit", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "Asafoetida (hing) , a pinch", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Oil , for tadka", "Ingredients For Buttermilk Curry", "1 cup Curd (Dahi / Yogurt)", "3 tablespoons Gram flour (besan)", "1/2 cup Water", "Salt , to taste"]'::jsonb, ARRAY['salt', 'sunflower oil tadka', 'asafoetida (hing)', 'mustard seeds', 'water', 'gram flour (besan)', 'curd', 'turmeric powder', 'green chillies', 'cabbage (patta gobi muttaikose)']::text[], '["To prepare Cabbage & Buttermilk Curry Recipe, prep up with all the ingredients needed.Heat oil in a Kadai on a medium flame and add mustard seeds.Once mustard seeds splutter, add asafoetida, salt, and turmeric.Add chopped cabbage and saute for 2 minutes.Blend all the ingredients of Buttermilk curry well with a wire whisk, transfer them to a pan.Let the buttermilk mixture boil and once done, mix it with cabbage curry and switch off the\u00a0flame.Garnish with coriander and Cabbage & Buttermilk Curry Recipe goes well with hot\u00a0chapati,\u00a0phulka\u00a0or plain cooked rice."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Chatori_Ladki/Cabbage__Buttermilk_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/448.Cabbage__Buttermilk_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Baby Potatoes Recipe', 'spicy-baby-potatoes-recipe', 'Who doesn''t like potatoes? I love potatoes in all forms. This is one such humble root that mixes with everything and adapt it''s flavor. Those days when you have nothing in your fridge, there comes the potato as rescue.', '["12 Baby Potatoes", "Oil , as required", "1 Dry Red Chilli", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves , optional", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 teaspoon Amchur (Dry Mango Powder)", "Salt , to taste", "1 teaspoon Lemon juice", "3 tablespoons Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'amchur (dry mango powder)', 'coriander (dhania) leaves', 'red chilli powder', 'dry red chilli', 'curry leaves', 'cumin seeds (jeera)', 'lemon', 'baby potatoes', 'coriander powder', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Spicy Baby Potatoes\u00a0recipe, pressure cook the baby potatoes and keep aside to cool.", "Peel off the skin and collect the boiled potatoes in a bowl.Heat oil in a wok/kadhai and add dry red chilies, curry leaves, cumin and let them crackle.Now add all the spices (coriander powder, red chili powder, amchur, cumin powder, garam masala powder and turmeric).", "Saute it for few seconds, don''t burn it.Add the baby potatoes and mix well with the spice mix.", "Fry for 6-7 minutes in medium flames till everything incorporates well and the flavors gets along with the potatoes.Adjust salt as per your taste and add some lemon juice and mix again.Turn off the heat, add lot of chopped coriander and give a quick stir.", "Serve Spicy Baby Potatoes along with\u00a0Phulkas\u00a0and\u00a0Panchmel Dal\u00a0for a weekday lunch or dinner."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shaheen_Ali/SPICY_BABY_POTATOES.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/449.SPICY_BABY_POTATOES.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Konkani Style Maskasangi Magge Koddel Recipe-Drumstick and Mangalore Cucumber Curry', 'konkani-style-maskasangi-magge-koddel-recipe-drumstick-and-mangalore-cucumber-curry', 'Maskasangi Magge Koddel Recipe-Drumstick and Mangalore Cucumber Curry, Koddel one of the traditional curry made by people in the Konkan region. Koddel is basically a coconut and dry red chilli gravy that seasoned with good amount of garlic. The vegetable that is being added into the curry may vary depending on the seasonal produce. It is usually the mangalore cucumber that are locally available and it is accompanied with lentils like horse gram or black eyed peas.', '["1 Drumstick , cut into 1 inch", "1 Mangalorean cucumber , cut into small pieces with the skin", "1 cup Tamarind Water", "1 teaspoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "1 tablespoon Jaggery", "4 cloves Garlic , roughly chopped", "Salt , to taste", "Masala To roast and grind", "5 Dry Red Chillies", "1 tablespoon Coriander (Dhania) Seeds", "1/2 cup Fresh coconut"]'::jsonb, ARRAY['salt', 'tamarind water', 'coconut', 'jaggery', 'red chilli powder', 'cloves garlic', 'drumstick', 'mangalorean cucumber the skin', 'dry red chillies', 'coriander (dhania) seeds', 'turmeric powder']::text[], '["To begin making the Maskasangi Magge Koddel Recipe, prep all the ingredients and keep them aside.We will first begin to roast the ingredients to be ground into a masala \u00a0in \"Masala To roast and grind\"In a small skillet, roast red chillies and coriander seeds until well roasted.", "Grind it along with coconut, add a little water to make a smooth paste.Heat a pressure cooker with oil, add some crushed garlic and saute for 10 seconds.", "Add the mangalore cucumber and drumsticks and the tamarind water.Add in the ground masala mixture, jaggery, chilli powder and salt and about 1/2 cup of water.", "Cover the pressure cooker and cook for 2 to 3 whistles.Once done, turn off the heat and allow the pressure to release naturally.", "Check the salt and seasonings and adjust to suit your taste and serve warm.Serve the Maskasangi Magge Koddel Recipe with steamed rice or\u00a0Mangalorean Neer Dosa\u00a0and\u00a0Chettinad Pepper Chicken Dry Recipe."]'::jsonb, 50, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Maskasangi_Magge_Kodel_Recipe_Drumstick_and_Mangalore_Cucumber_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/450.Maskasangi_Magge_Kodel_Recipe_Drumstick_and_Mangalore_Cucumber_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Beetroot Palya Recipe', 'karnataka-style-beetroot-palya-recipe', 'Karnataka Style Beetroot Palya Recipe is a simple beetroot stir fry with aromatic sambar masala. It is also mildly flavoured with garlic cloves pounded with freshly grated coconut.', '["500 grams Beetroot , cut into long strips", "4 tablespoons Fresh coconut , grated", "4 cloves Garlic", "1 Onion , finely chopped", "1-1/2 teaspoons Sambar Powder", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "Asafoetida (hing) , a pinch", "1 Dry Red Chilli", "1 sprig Curry leaves", "2 teaspoons Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'cloves garlic', 'dry red chilli', 'curry leaves', 'onion', 'beetroot', 'sambar powder', 'sunflower oil']::text[], '["To begin making the\u00a0Karnataka Style Beetroot Palya Recipe, peel the outer skin of the beetroot, cut it into long thin strips and keep aside.Heat oil in a heavy bottomed pan, add the mustard seeds, and let it crackle.", "Add the asafoetida, red chilli, curry leaves and let it splutter.Add the onions and saute until it turns translucent.Once the onions are translucent, add in the beetroot, season with salt, mix well and cook until the beetroot is half cooked.Add in the sambar masala and, toss well and let the beetroot cook well.Once the beetroot is cooked, pound the grated coconut and garlic cloves using a pestle and mortar, and add it to the pan.Mix well and cook for another 2 minutes and switch off the heat.Serve the delicious\u00a0Karnataka Style Beetroot Palya Recipe\u00a0along with\u00a0Steamed Rice,\u00a0Keerai Sambar\u00a0and\u00a0Elai Vadam\u00a0for a simple weekday lunch."]'::jsonb, 20, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Karnataka_Style_Beetroot_Palya_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/451.Karnataka_Style_Beetroot_Palya_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Whole Wheat Lachha Paratha Recipe-Multilayered Layered Indian Flat Bread', 'whole-wheat-lachha-paratha-recipe-multilayered-layered-indian-flat-bread', 'The Whole Wheat Lachha Paratha Recipe is a classic Indian Layered Flat bread that is most often made with maida or all purpose flour. This recipe of Lachha Paratha is healthy and is made from pure whole wheat chakki atta . Different regions of Indian call it by different names, from lachha paratha to kerala paratha. The layers in the paratha, gives it a crisp touch and also makes it a great bread to serve with any gravy dishes.', '["2 cups Whole Wheat Flour", "1 teaspoon Salt", "Ghee , to layer and cooking parathas"]'::jsonb, ARRAY['s whole wheat flour', 'salt', 'ghee']::text[], '["To begin making the\u00a0Whole Wheat Lachha Paratha Recipe we will first knead to make the dough.In a large mixing bowl, add the whole wheat flour and salt.", "Mix well.", "Add a tablespoon of oil and rub it into the flour until you see coarse crumbs.", "Add a little water at a time and knead well to make a smooth and soft paratha dough.", "Cover the dough and allow it to rest for 10 minutes.After 10 minutes, knead for a minutes again until the paratha dough is soft and pliable.", "Divide the dough into 10 equal portions.", "Preheat a skillet on medium heat.", "If you are using a cast iron skillet, then grease the skillet well and allow it to preheat.Keep some flour aside for dusting while rolling the dough.", "Shape each dough portion into a round ball, press it between the palm of your hands.Dust the dough in flour and roll it into a 6 inch diameter circle.", "Smear some ghee or oil on this rolled out dough.", "Dust some flour over the ghee.", "This flour and ghee will help the lachha paratha split itself into layers.Fold the lachha paratha dough like an accordion, similar to a saree pleat.", "Start from one end of the dough and reach the end.", "The dough is essentially made into a pleat.", "Once you have stacked up all the pleats one over the other, roll the dough into a swiss roll.", "Flatten the pleated swiss roll between the palm of your hands, dust in flour and roll into a 4 to 5 inch diameter circle.", "You will be able to see the layers very clearly.Place the rolled layered Lachha Paratha on the preheated skillet.", "Cook on medium heat on both sides for a few seconds, then smear ghee and cook until golden brown and cooked through completely.Proceed the same way with the remaining portions of the paratha dough.Serve the\u00a0Whole Wheat Lachha Paratha along with\u00a0Matar Paneer\u00a0\u00a0or\u00a0Smoked Dal Makhani Dhaba Style\u00a0\u00a0and\u00a0Carrot Cucumber Tomato Salad with Lemon and Coriander\u00a0for a weeknight dinner or even for breakfast along with\u00a0Kesar Elaichi Aam Chunda Pickle\u00a0and\u00a0Homemade Yogurt\u00a0."]'::jsonb, 70, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breads/Whole_Wheat_Laccha_Paratha_Layered_North_Indian_Flat_Bread_Recipe_Healthy_Vegetarian-5.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/452.Whole_Wheat_Laccha_Paratha_Layered_North_Indian_Flat_Bread_Recipe_Healthy_Vegetarian-5.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Baked Amritsari Kulcha Recipe (Without Yeast)', 'baked-amritsari-kulcha-recipe-without-yeast', 'Kulcha is a type of mildly leavened flatbread that originated in the Indian subcontinent. It is a variation of Naan. Kulcha is a essentially a Punjabi dish, invented as a local version of the naan which was brought into Punjab. Here I''m making baked kulcha without yeast and that turned out really delicious trust me! Serve it hot in your dinner with Punjabi Chole!', '["1-1/2 cup All Purpose Flour (Maida)", "1 teaspoon Salt", "1 teaspoon Sugar", "1 teaspoon Baking powder", "1/4 teaspoon Baking soda", "1 tablespoon Oil", "3 tablespoons Curd (Dahi / Yogurt)", "Water , as required", "Black sesame seeds , as required", "Sesame seeds (Til seeds) , as required", "Coriander (Dhania) Leaves , chopped", "Butter (Salted) , as required"]'::jsonb, ARRAY['salt', 'baking powder', 'coriander (dhania) leaves', 'black sesame seeds', 'water', 'baking soda', 'curd', 'sugar', 'flour (maida)', 'sesame seeds (til seeds)', 'butter', 'sunflower oil']::text[], '["To begin making the Baked Amritsari Kulcha recipe, in a medium sized bowl, add all the dry ingredients and mix it well.Gradually add water and then knead the dough.", "Make a soft dough and cover it and place it into warm place of your kitchen for 2 hours to ferment.After 2 hours, when dough is rising double in size, knead it again with some oil and device it into equal portions.Take one portion and apply sesame seeds and chopped coriander leaves on top and roll it into oval shape.", "Prepare all the kulcha in same manner.Take microwave safe plate, brush it with oil and place kulchas on it and rest them for 30 minutes.", "Preheat microwave at 180 degrees and bake kulchas for 10 minutes.", "Apply butter on top.Your delicious Amritsari Kulcha are ready to serve.", "Serve\u00a0Baked Amritsari Kulcha along with\u00a0Pindi Chole\u00a0and\u00a0Aam Ka Achaar\u00a0for your weekend dinner."]'::jsonb, 20, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/Baked_Amritsari_Kulcha_Recipe_Without_Yeast-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/453.Baked_Amritsari_Kulcha_Recipe_Without_Yeast-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lobia Masala Recipe (Black Eyed Bean Curry) - Roz Ka Khana With Figaro Olive Oil', 'lobia-masala-recipe-black-eyed-bean-curry-roz-ka-khana-with-figaro-olive-oil', 'Lobia Masala is also known as Chora nu Shaak in Gujarati, is a favorite family dish. Black-eyed bean is a versatile pulse that beautiful absorbs the spices added to it making it succulent and tasty. This bean is packed with proteins and micronutrients, is low in saturated fat and is a good source of dietary fiber.', '["1 cup Black Eyed Beans (Lobia)", "1/2 cup Homemade tomato puree", "1 Onion , finely chopped", "1 teaspoon Cumin seeds (Jeera)", "1 inch Ginger , peeled and grated", "3 cloves Garlic , finely chopped", "2 Green Chilli , finely chopped", "1 inch Cinnamon Stick (Dalchini)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 teaspoon Jaggery", "1 teaspoon Lemon juice", "Salt , to taste", "1 teaspoon Extra Virgin Olive Oil", "Coriander (Dhania) Leaves , chopped to garnish"]'::jsonb, ARRAY['black eyed beans', 'lobia', 'homemade tomato puree', 'onion', 'cumin seeds', 'jeera', 'ginger', 's garlic', 'reen chilli', 'cinnamon stick', 'dalchini', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'red chilli powder', 'garam masala powder', 'jaggery', 'lemon juice', 'salt', 'extra virgin olive oil', 'coriander']::text[], '["To begin making the Lobia Masala, wash beans and soak in water for 2 hours.", "Pressure cook the beans with along with the water it was soaked in plus an addition of 2 cups of water\u00a0till\u00a0soft and tender making sure it does not become mushy.", "See cooking instructions on how to cook lentils/dals.", "Once beans are cooked transfer to a bowl.", "Keep aside until required.Heat oil in a saucepan\u00a0over medium heat; add the cumin seeds, cinnamon stick allow to\u00a0crackle.", "Add grated ginger, garlic, onion and green chillies and fry for few seconds.", "Stir in the tomatoes puree and saut\u00e9 over medium heat until oil starts separating from the masala.Add the turmeric powder, coriander powder, garam masala powder, red chilli powder jaggery and the cooked beans with little.", "Stir to combine.Reduce the flame to low and let Lobia Masala cook for 15 minutes.", "Adjust the consistency of the dish according to your taste, by adding more or less water.", "After 15-minutes\u00a0turn off the heat and stir in the lemon juice. and the chopped coriander leaves.", "Serve hot.", "Garnish with the chopped coriander leaves.", "Serve hot with Paratha."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/0-Archana/11-long-format-Punjabi_Lobia_Masala_Figaro_Olive_Oil-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/454.11-long-format-Punjabi_Lobia_Masala_Figaro_Olive_Oil-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('One Pot Aloo Gobi Sabzi Recipe Using Preethi Electric Pressure Cooker', 'one-pot-aloo-gobi-sabzi-recipe-using-preethi-electric-pressure-cooker', 'The One Pot Aloo Gobi Sabzi Recipe is made in less than 20 minutes using Electric Pressure Cooker. The Aloo Gobi Sabzi is a classic North Indian dish that is perfectly blended with simple spices like turmeric, cumin and garam masala. The milk spices cooked along with tomatoes, gobi and aloo make this sabzi recipe an absolute delicacy.', '["2 Potatoes (Aloo) , peeled and cubed", "1 Cauliflower (gobi) , washed and cut into florets", "1 inch Ginger , grated", "2 Tomatoes , pureed", "1/2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "2 Cardamom (Elaichi) Pods/Seeds", "1/4 teaspoon Red Chilli powder", "2 sprig Coriander (Dhania) Leaves , finely chopped", "Oil , as required", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'cardamom (elaichi) podsseeds', 'cauliflower (gobi)', 'red chilli powder', 'coriander (dhania) leaves', 'cumin seeds (jeera)', 'potato (aloo)', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the One Pot Aloo Gobi Ki Sabzi Recipe in the Preethi Electric Pressure Cooker, heat oil in pan and make the setting to the gravy mode; add cumin seeds, ginger, cardamom pods.", "Allow the cumin seeds to crackle.Once the cumin seeds crackle for a few seconds, add the tomatoes, aloo, gobi, salt, chilli powder, turmeric powder, garam masala and 1/4 cup of water.Stir to combine all the aloo gobi ingredients.", "Lock the lid in place.", "Set the timer for 20 minutes and allow it to cook until you hear the beep sound.Once the aloo gobi sabzi is done, allow the pressure to release naturally.", "Check the salt and pepper to taste and transfer Aloo Gobi sabzi to serving dish and serve warm.Serve the One Pot Aloo Gobi Sabzi along with Traditional Punjabi Kadhi with Methi  and Chawal for a quick weeknight dinner."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Preethi_Electric_Pressure_Cooker_One_Dish_One_Pot_Aloo_Gobi_Recipe_Video-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/455.Preethi_Electric_Pressure_Cooker_One_Dish_One_Pot_Aloo_Gobi_Recipe_Video-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Szechuan Vegetarian Fried Rice', 'szechuan-vegetarian-fried-rice', 'Szechuan Style Vegetarian Fried Rice Recipe is one of the staple meal found in the region of Sichuan (China). The rice is traditionally tossed with the local vegetables available and then mixed with the authentic Sichuan chili oil which is made from Sichuan peppers.The dish also consists of Sichuan chili sauce. So the dish as a whole itself is very spicy thus representing the flavor of that region.', '["1 cup Rice , boiled", "1/4 cup Green beans (French Beans) , finely chopped", "1 Carrot (Gajjar) , finely chopped", "1 Green Bell Pepper (Capsicum) , finely chopped", "2 Dry Red Chilli , sliced", "2 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "2 teaspoon Red Chilli sauce , (or Birds Eye Chili sauce)", "2 teaspoon Soy sauce", "1 teaspoon Vinegar", "Salt , to taste", "Black pepper powder , to taste"]'::jsonb, ARRAY['salt', 'green beans (french beans)', 'ginger', 'red chilli sauce (or birds eye chilli sauce)', 'rice', 'cloves garlic', 'carrot', 'dry red chilli', 'soy sauce', 'vinegar', 'black pepper powder', 'green bell pepper (capsicum)']::text[], '["We begin making the Szechuan Vegetable Fried Rice Recipe by prepping all the ingredients needed for the recipe.Boil the rice with 2 cups of water in a pressure cooker for 3 whistles depending on the rice.", "Once the pressure is released , keep it aside.", "Allow the rice to cool completely.", "Using a day old rice also helps.Heat a heavy bottomed pan with oil, add ginger , garlic, and red chillies.", "Then you can add the vegetable and saute till the vegetables are cooked.Once done add the sauces along with the cooked rice.", "Toss the rice and season it according to your taste.Serve your Szechuan Vegetable Fried Rice hot accompanied by\u00a0lunch meal."]'::jsonb, 50, 'Sichuan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/oct-7/Vegetarian_Sichuan_Fried_Rice-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/456.Vegetarian_Sichuan_Fried_Rice-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Kosha Mangsho Recipe-Slow Cooked Mutton Curry', 'bengali-kosha-mangsho-recipe-slow-cooked-mutton-curry', 'Bengali Kosha Mangsho Recipe-Slow Cooked Mutton Curry Recipe is a flavor packed Indian curry made with mutton pieces in a pressure cooker. The spices used in this dish, very well combine and go along with the mutton flavor.', '["3 Potatoes (Aloo) , halved (optional)", "3 Cloves (Laung)", "8 cloves Garlic", "1 inch Ginger", "4 Onions , chopped", "3 Tomato , chopped", "Spice powders", "1 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "2 teaspoon Lemon juice", "Salt , to taste", "To marinate the mutton", "750 grams Mutton", "1 inch Ginger , grated", "5 cloves Garlic , grated", "1 teaspoon Red Chilli powder", "2 teaspoons Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "4 tablespoon Curd (Dahi / Yogurt)", "To temper", "2 teaspoon Whole Black Peppercorns", "2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "1 Bay leaves (tej patta) , torn", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'ginger', 'bay leaves (tej patta)', 'mustard seeds', 'cardamom (elaichi) podsseeds', 'red chilli powder', 'cloves garlic', 'black peppercorns', 'curd', 'onion', 'lemon', 'mutton', 'cinnamon stick (dalchini)', 'coriander powder', 'potato (aloo)', 'turmeric powder', 'cloves (laung)', 'garam masala powder']::text[], '["We begin making Bengali Kosha Mangsho Recipe-Slow Cooked Mutton Curry Recipe by marinating the mutton with ground ginger and garlic paste.", "Then add the yogurt and the rest of the spice powders and mix it thoroughly till it is evenly coated.Rest it for 2 hours.Then heat \u00a0the pan with mustard oil, saute onion and tomato till it is well done.", "Add all the spice powders once done keep it aside to cool and blend it into a smooth paste using a blender.Heat the pressure cooker, add oil, temper it with black pepper, cinnamon stick,bay leaves cardamom and sugar.", "Add in the onion and tomato paste with all the masala powders, fry about 5 minutes.Now add the marinated mutton and the potatoes coat it with the gravy.Cook at a low heat, add 1 cup of water and cook the mutton covered for 5 whistles.", "Once the pressure has been released naturally garnish with some chopped coriander leaves.Serve your spicy flavorful \u00a0Bengali Kosha Mangsho-Slow Cooked Mutton Curry with\u00a0Lachha Paratha."]'::jsonb, 185, 'Bengali', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/sept-26/Bengali_Kosha_Mangsho_Mutton_Curry_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/457.Bengali_Kosha_Mangsho_Mutton_Curry_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Curd Oats Recipe', 'curd-oats-recipe', 'Curd Oats Recipe is a delicious and creamy oatmeal dish cooked and mixed with cold silken curd and tempered with simple south indian spices. It is similar to curd rice with less calories.', '["3 tablespoons Instant Oats (Oatmeal)", "1 cup Water", "1-1/2 cup Curd (Dahi / Yogurt) , beaten to a smooth consistency", "1 inch Ginger , finely chopped", "1 Green Chilli , finely chopped", "Salt , to taste", "Ingredients for tempering", "1 teaspoon Oil", "1/2 teaspoon Chana dal (Bengal Gram Dal)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "pinch Asafoetida (hing)"]'::jsonb, ARRAY['salt', 'ginger', 'green chilli', 'mustard seeds', 'asafoetida (hing)', 'water', 'curry leaves', 'curd smooth consistency', 'chana dal (bengal gram dal)', 'instant oats (oatmeal)', 'sunflower oil']::text[], '["To begin making the Curd Oats Recipe, we first need to cook the oats in plain water.Bring a cup of water to a rolling boil in a saucepan, add the oats and season with salt, mix and simmer for 3 minutes until the oats is cooked.", "Turn off the heat and keep aside to cool.Take a bowl, add curd and beat the thick curd to the silky smooth texture.To the curd add the finely chopped ginger and green chilli and the cooled oats.", "Mix well to combine.", "If the curd oats is too thick, add a little milk or water to bring it to the desired consistency.To prepare the tadka, heat oil in a tadka pan on low heat, add the chana dal and mustard seeds and let it splutter.Once the mustard seeds have spluttered add the curry leaves and asafoetida and once the curry leaves crackle turn off the heat.Add this tadka over the prepared curd oats and mix well.", "Season with salt if required and serve.Serve this delicious Curd Oats Recipe for a light lunch or early supper along with\u00a0Kachumber salad\u00a0and\u00a0Pisarna Manga Recipe -Instant Raw Mango Pickle to make it a complete meal."]'::jsonb, 20, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Curd_Oats_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/458.Curd_Oats_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Baked Modak and Karanji/Gujiya Recipe', 'baked-modak-and-karanji-gujiya-recipe', 'Since Ganesh Chaturthi is coming closer, few of the health freaks like me must be wondering, how to prepare some healthy snacks. So here is the tried and tested recipe of baked modak and karanji. These are healthy and tasty at the same time. So this festival try these snacks and we are sure you will love it.', '["Ingredients for dough", "1-1/2 cup All Purpose Flour (Maida)", "2 tablespoons Ghee", "Salt , Pinch", "Water , as required", "1 cup Dessicated Coconut", "1/3 cup Sugar , powdered", "1/4 cup Sooji (Semolina/ Rava)", "1/4 cup Cashew nuts , cut into small pieces", "2 tablespoons Ghee", "1 teaspoon Cardamom Powder (Elaichi)"]'::jsonb, ARRAY['ingredients for dough', 'all purpose flour', 'maida', 's ghee', 'salt', 'water', 'dessicated coconut', 'sugar', 'sooji', 'semolina/ rava', 'cashew nuts', 'cardamom powder', 'elaichi']::text[], '["To begin making the Baked Modak and Karanji recipe, first make the dough by mixing together maida, ghee and pinch of salt.Add water little at a time, till you get nice dough like chapati dough.", "Knead it well, cover it with wet cloth and keep it covered for 10 minutes.", "The next step is to make the stuffing.", "On a skillet, melt ghee and fry sooji until fragrant.", "Add coconut and fry for around a minute or until it slightly changes its colour.Add sugar, mix and cook on low flame for around a minute.", "Add dry fruits and cardamom powder.", "Mix everything well and cook for another minute and switch off the stove.", "Keep the mixture for cooling.Now let\u2019s make karanji and modak.", "First make small balls out of dough.", "Size of a golf ball.Roll them one by one with rolling pin to make thin discs.Keep these discs covered with moist cloth or moist kitchen paper towel to keep them moist.For karanji, place a spoon full of the filling at the centre of each disc and fold the circle in a half-moon shape and with the help of fork, press the folded side to make nice design.For making modak, the same process but hold the disc on your left palm in the shape of a bowl and just place the filling in the centre of the disc and merge all the sides of the disc to make in the shape of a fresh fig.After you make all the karanjis and modaks ready, lets bake them.Place them on the baking trays lined with greased aluminium foil (Greased with little ghee).", "Brush each karanji and modak with ghee to give them a nice glaze after they are baked.Bake them at 350 degree Fahrenheit preheated oven for 20 minutes.After every 10 minutes, flip them and bake on the other side.", "After 20 minutes, remove and keep on the cooling rack.Once cooled down completely, store in the air tight container.", "Serve Baked Modak and Karanji along with some snacks such as\u00a0Moong Dal Mini Samosas\u00a0and\u00a0Chana Chaat\u00a0to your guests or family members."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Nadkarni/Baked_Modak_and_Karanji_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/459.Baked_Modak_and_Karanji_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Alugadde Batani Gasi Recipe - Potatoes And Peas Gassi', 'alugadde-batani-gasi-recipe-potatoes-and-peas-gassi', 'Alugadde Batani Gasi Recipe is a delicious Udupi style coconut based potatoes and green peas curry. Udupi cuisine uses a lot of coconut, and the curries are flavoured with the freshly ground masalas which gives it a distinctive flavour.', '["1 cup Fresh coconut", "1 teaspoon White Urad Dal (Split)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Coriander (Dhania) Seeds", "6 Dry Red Chillies", "15 grams Tamarind", "1/2 teaspoon Turmeric powder (Haldi)", "1 tablespoon Jaggery", "1 tablespoon Oil", "2 sprig Curry leaves", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies , broken", "1 cup Green peas (Matar)", "2 Potatoes (Aloo)", "Salt , to taste"]'::jsonb, ARRAY['fresh coconut', 'white urad dal', 'split', 'cumin seeds', 'jeera', 'coriander', 'dhania', 'dry red chillies', 's tamarind', 'turmeric powder', 'haldi', 'jaggery', 'oil', 'curry leaves', 'mustard seeds', 'rai/ kadugu', 'green peas', 'matar', 'potatoes', 'aloo', 'salt']::text[], '["To begin making the Alugadde Batani Gasi Recipe - Potatoes And Peas Gassi , prep all the ingredients and keep aside.Into a pressure cooker, add the green peas along with a little salt and \u00bc cup of water.", "Pressure cook for 2 whistles and turn off the heat.", "Release the pressure immediately to retain the fresh green colours of the peas.", "Keep aside.To cook the potatoes, cut the potatoes into half and add it into the pressure cooker.", "Add half cup of water and pressure cook for 3 to 4 whistles and turn off the heat.", "Allow the pressure to release naturally.", "Once pressure has released and the potatoes have cooled peel the potatoes and cut into cubes.", "Keep aside.To make the freshly ground coconut masala, heat a pan over medium heat.", "Add the urad dal and dry roast until it becomes golden brown.", "Add the cumin seeds, coriander seeds and dry red chillies and roast them for a few seconds until the seeds start crackling.Turn off the heat and allow the roasted ingredients to cool.Add the roasted dal, cumin seeds, coriander seeds, red chillies, along with the coconut, tamarind, turmeric powder, jaggery and half cup of warm water.", "Blend to make a smooth paste.", "Keep aside.Heat oil in a pan; add the mustard seeds, dry red chillies and allow the seeds to crackle.", "Stir in the curry leaves and give it a stir.Add the ground coconut masala, the cooked peas and potatoes along with 1/2 cup of water and stir well to combine.", "The gasi is usually thick, so you could adjust the consistency by adding more water if you like.", "Give the gasi a brisk boil for 3 to 4 minutes and turn off the heat.", "Check salt and adjust according to taste and serve hot.", "Serve\u00a0Batani Gassi Recipe (Udupi Style Potatoes and Peas Curry) with Steamed Rice,\u00a0Udupi Style Southekayi Palya Recipe\u00a0for a complete meal."]'::jsonb, 40, 'Udupi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Alugadde_Batani_Gasi_Recipe_Potatoes_And_Peas_Gassi_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/460.Alugadde_Batani_Gasi_Recipe_Potatoes_And_Peas_Gassi_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lauki Chana Dal Recipe | Dudhi Chana Dal |  High Protein Bottle Gourd Lentil Curry', 'lauki-chana-dal-recipe-dudhi-chana-dal-high-protein-bottle-gourd-lentil-curry', 'Lauki Chana Dal is a nutritious recipe that combined the Bottle Gourd and lentils making it a perfect dish for a wholesome lunch or dinner. Lauki is also known as Doodhi or Giya and one of my favorite dishes while growing up.', '["1 cup Chana dal (Bengal Gram Dal) , soaked in water for 2 hours", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Salt", "Water , as needed for cooking", "1 teaspoon Ghee", "1 teaspoon Ginger , grated", "1 Green Chilli , chopped", "1 Bay leaf (tej patta)", "1 Tomato , finely chopped", "1 Bottle gourd (lauki) , peeled and cut into chunks", "1 teaspoon Garam masala powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder , adjust according to taste", "1 teaspoon Jaggery", "1 Coriander (Dhania) Leaves , small bunch, chopped", "Salt , to taste", "Ingredients for Seasoning", "1 teaspoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies"]'::jsonb, ARRAY['chana dal', 'bengal gram dal', 'turmeric powder', 'haldi', 'salt', 'water', 'ghee', 'ginger', 'reen chilli', 'bay leaf', 'tej patta', 'tomato', 'bottle gourd', 'lauki', 'garam masala powder', 'red chilli powder', 'jaggery', 'coriander', 'dhania', 'ingredients for seasoning', 'cumin seeds', 'jeera', 'dry red chillies']::text[], '["To begin making the Lauki Chana\u00a0Dal Sabzi Recipe, soak the chana Dal in 2-1/2 cups of water for 3 to 4 hours.First cook the channa in the pressure cooker.", "Place the soaked chana dal in the pressure cooker along with enough water such that the water is at least 2 inches above the dal.Sprinkle some salt and a pinch of turmeric powder.", "Pressure cook for 3 to 4 whistles about 15 minutes and turn off the heat and allow the pressure to release naturally.Next step is to cook the lauki in the pressure cooker.", "Heat a little ghee over medium heat, add the bay leaf, ginger, green chilli, tomato, turmeric powder, red chilli powder, garam masala powder, salt, jaggery and give it a stir.Saute until the tomatoes soften.", "Add the peeled and chopped lauki/ bottle gourd along with 1/4 cup of water and give it a stir.", "Pressure cook the lauki for about 2 whistles and turn off the heat.", "Allow the pressure to release naturally.Add the cooked chana dal to the cooked lauki and give it a brisk boil.", "Check the salt and spices in the Lauki Chana Dal and adjust to suit your taste.The next step is to make the seasoning for the lauki chana dal.", "Heat a small pan\u00a0with ghee; add the cumin seeds and red chilies.", "Roast for a couple seconds and turn off the heat.Pour the seasoning into the Lauki Chana Dal / Dudhi Chana Dal, stir in the chopped coriander leaves and serve warm.Serve\u00a0Lauki Chana Dal\u00a0along with\u00a0Aloo Simla Mirch Ki Sabzi,\u00a0Bhakri\u00a0and\u00a0Palak Raita\u00a0for a weekday lunch or dinner."]'::jsonb, 60, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Lauki_Chana_Dal_recipe_North_indian_high_protein_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/461.Lauki_Chana_Dal_recipe_North_indian_high_protein_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thakkali Vengaya Sambar Recipe - Tomato Onion Sambar', 'thakkali-vengaya-sambar-recipe-tomato-onion-sambar', 'Thakkali Vengaya Sambar which is also called as Tomato Onion Sambar is a light sweet, spicy and tangy dish made from tomato, small sambar onions and the homemade sambar powder.', '["1 cup Arhar dal (Split Toor Dal)", "1 cup Pearl onions (Sambar Onions) , peeled", "2 Tomatoes , diced", "1 cup Tamarind Water , freshly squeezed", "1 tablespoon Sambar Powder", "Salt , to taste", "Ingredients for Seasoning", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)", "1 sprig Curry leaves", "2 Dry Red Chillies", "1 tablespoon Sesame (Gingelly) Oil", "To garnish", "4 sprig Coriander (Dhania) Leaves , roughly chopped"]'::jsonb, ARRAY['arhar dal', 'split toor dal', 'pearl onions', 'sambar onions', 'tomatoes', 'tamarind water', 'sambar powder', 'salt', 'ingredients for seasoning', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing', 'curry leaves', 'dry red chillies', 'sesame', 'gingelly', 'to garnish', 'coriander', 'dhania']::text[], '["To begin making the Thakkali Vengaya Sambar Recipe, wash toor dal and soak in water for 10 minutes.", "Transfer soaked toor dal to a pressure cooker, add 2 cups of water.Pressure cook the dal for 3-4 whistles and let the pressure release naturally.Open the lid, scoop out the cooked dal into a bowl.", "With the help of a potato masher mash the dal and keep aside.", "In a same pressure cooker, add the onions and tomatoes along with tamarind extract, sambar powder, salt and 1/4 cup of water.", "Close the lid and pressure for two whistles over the medium heat.", "After two whistles turn off the heat.", "Allow the steam to release naturally from the pressure cooker.", "Open the lid once the steam is released.If you are not using the pressure cooker method - Heat oil in a\u00a0saucepan, saute the smalls onions until tender and the sweet aroma is released.Add the tomatoes, the sambar powder, tamarind extract and 1/4 cup of water and simmer until the tomatoes are tender for about 10 minutes.", "Now mix the cooked toor dal with the onion tamarind sambar curry.", "Stir to combine and transfer to a large\u00a0saucepan.Meanwhile, to temper the Tomato Onion Sambar, heat oil in a small pan, add mustard seeds.Once mustard seeds start crackling add\u00a0asafoetida powder, curry leaves and red chilli.", "Saute till the curry leaves turn crips.", "Turn off the heat and pour the seasoning into the sambar.Place the Tomato Onion Sambar over medium-high heat and bring the sambar to a boil.", "Turn the heat to low and allow the sambar to simmer for about 5 minutes, stirring in between.", "If the Tomato Onion Sambar is too thick, add a little water to get the right consistency and simmer.", "Taste the seasoning and adjust to suit your taste.Garnish the Tomato Onion Sambar with chopped coriander leaves and serve hot.", "Serve Tomato Onion Sambar along with\u00a0Beetroot Thoran\u00a0and\u00a0Steamed Rice\u00a0for a weekday lunch or dinner."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/south_indian/Thakkali_Vengayam_Sambar_Tomato_Onion_Recipe_South_Indian-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/462.Thakkali_Vengayam_Sambar_Tomato_Onion_Recipe_South_Indian-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Sura Meen Kuzhambu Recipe (Shark Fish Curry)', 'chettinad-sura-meen-kuzhambu-recipe-shark-fish-curry', 'Chettinad Sura Meen Kuzhambu aka Shark Fish Curry is a quintessential curry dish from the South Indian Cuisine that goes with Chettinad spices hence it''s hot and spicy with the flavours. Typically eaten with plain steamed rice, Shark fish curry is a popular curry dish in entire South India specially Tamil Nadu and Kerala. Shark fish is great in taste and it''s believed to be good for breastfeeding mothers as it increases milk supply for the new born. But shark fish also increase body heat, so its suggested to consume in wisely.', '["500 grams Shark fish , (with skin, cut into medium pieces)", "15 Shallots , chopped", "5 cloves Garlic , chopped", "2 teaspoons Red Chilli powder", "3 tablespoons Coriander Powder (Dhania)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Fennel Powder", "1 teaspoon Cumin powder (Jeera) , roasted", "Salt , as required", "Oil , as required", "1/2 teaspoon Fennel seeds (Saunf)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1-1/2 cups Water", "1/4 cup Tamarind Water", "1 sprig Curry leaves", "3 Dry Red Chillies"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'tamarind water', 'mustard seeds', 'fennel seeds (saunf)', 'red chilli powder', 'cloves garlic', 'water', 'curry leaves', 'fennel powder', 'dry red chillies', 'cumin seeds (jeera)', 'shark fish (with skin', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Chettinad Sura Meen Kuzhambu recipe, clean and wash the fish pieces and marinate with turmeric and keep aside.Heat oil in a wok/kadai and when the oil is hot add fennel seeds, curry leaves, dry red chilli, cumin and mustard seeds and wait till they splutter.Now add chopped shallots and chopped garlic cloves.", "Saute until onions are transparent and pale.Mix red chilli powder, coriander powder, cumin powder and fennel powder to the tamarind water and stir well until smooth.", "Add this to the wok and mix well.Add 1-1/2 cups of water, season with salt and bring the curry to boil.When the curry starts boiling, cover with lid and simmer curry for 5 to 6 minutes.Now add the shark fish pieces to the curry and stir gently and cook for another 5 minutes or until fish pieces are tender and oil floats on top of gravy.Turn off the heat and serve hot.", "Serve Chettinad Sura Meen Kuzhambu along with Steamed Rice and\u00a0Kachumber Salad\u00a0for a weekday meal."]'::jsonb, 60, 'Chettinad', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shaheen_Ali/CHETTINAD_SURA_MEEN_KUZHAMBU__SHARK_FISH_CURRY.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/463.CHETTINAD_SURA_MEEN_KUZHAMBU__SHARK_FISH_CURRY.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharashtrian Gopalkala Recipe (Curd Poha With Fruits)', 'maharashtrian-gopalkala-recipe-curd-poha-with-fruits', 'Gopalkala is a beaten rice recipe mixed with curd, pomegranate and cucumber. Gopalkala is a prashad recipe that is specially made on Krishna Janmashtami. In Maharashtrian households, mothers make gopalkala with seasonal fruits to feed it to kids. This bean rice poha with fruits in curd, can be served for breakfast or as an afterschool snack.', '["1 cup Poha (Flattened rice)", "1/2 cup Curd (Dahi / Yogurt)", "1/4 cup Cucumber , finely chopped", "1/4 cup Fresh coconut , scraped", "1/4 cup Anardana Powder (Pomegranate Seed Powder)", "1 teaspoon Sugar", "2 teaspoon Raw Peanuts (Moongphali)", "2 Green Chillies , finely chopped", "1 teaspoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "5 Curry leaves , finely chopped", "Salt , to taste"]'::jsonb, ARRAY['salt', 'ghee', 'poha (flattened rice)', 'anardana powder (pomegranate seed powder)', 'curry leaves', 'curd', 'sugar', 'cumin seeds (jeera)', 'peanuts (moongphali)', 'cucumber', 'coconut scraped', 'green chillies']::text[], '["To prepare Gopalkala Recipe (Curd Poha With Fruits), wash the Poha under running water and allow to drain in a colander. (You can keep the colander on a fitting vessel.In a big mixing bowl, take this drained Poha and mix with chopped cucumber, grated Coconut, pomegranate seeds, curd, salt and sugar.Heat a tadka pan on medium heat and melt the ghee.Add cumin seeds, curry leaves, peanuts and chopped green chilies.Stir fry for a minute and pour this tempering over the Poha and mix well.Served Gopalkala Recipe for breakfast or as an afterschool snack for kids or for breakfast."]'::jsonb, 12, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/19-Jan/Maharashtrian_Gopalkala_Recipe_Curd_Poha_With_Fruits-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/464.Maharashtrian_Gopalkala_Recipe_Curd_Poha_With_Fruits-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bhaat Na Muthiya Dhokla Recipe | Gujarati Farsan | Snack', 'bhaat-na-muthiya-dhokla-recipe-gujarati-farsan-snack', 'Bhaat na Muthiya Dhokla Recipe is a staple dish of every Gujarati kitchen home and every home has ways to invent dishes that can be made from leftover rice. Muthiya a common staple in every Gujarati home is made by steaming dumplings of mashed rice combined with vegetables and spices.', '["Main Ingredients", "2 cups Cooked rice , (leftover rice can be used)", "1/2 cup Gram flour (besan)", "1 teaspoon Ginger , finely grated", "1/2 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Asafoetida (hing)", "1/2 teaspoon Red Chilli powder", "Coriander (Dhania) Leaves , small bunch, finely chopped", "1 cup Bottle gourd (lauki) , grated", "1 tablespoon Oil", "Salt , to taste", "Ingredients for seasoning", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Sesame seeds (Til seeds)", "2 tablespoons Fresh coconut , grated", "6 Curry leaves , finely chopped", "1 tablespoon Coriander (Dhania) Leaves , finely chopped", "1 teaspoon Oil"]'::jsonb, ARRAY['main ingredients', 's cooked rice', 'gram flour', 'besan', 'ginger', 'turmeric powder', 'haldi', 'asafoetida', 'hing', 'red chilli powder', 'coriander', 'dhania', 'bottle gourd', 'lauki', 'oil', 'salt', 'ingredients for seasoning', 'mustard seeds', 'rai/ kadugu', 'sesame seeds', 'til seeds', 's fresh coconut', 'curry leaves']::text[], '["To make the Bhaat Na Muthiya Dhokla Recipe, we will first prepare the steamer by filling it with water and grease the steamer plates.Using a large wide bowl combine the\u00a0cooked rice,\u00a0gram flour, grated ginger,\u00a0turmeric powder,\u00a0asafoetida powder,\u00a0red chilli powder,\u00a0coriander leaves, bottle gourd and\u00a0oil\u00a0for the muthias and mash well using a masher or with your hands.", "The mixture will look like a firm ball of dough.Divide the above mixture into 15-20 equal portions and shape them into ovals.", "Or you can shape them into longer logs and cut them into rounds after they are steamed.Place the portions of the dumplings 1 inch apart on the greased plates and steam on high heat for 15 minutes.", "Turn off heat and allow the Muthia to rest for 5 minutes with the steamer lid opened.", "Transfer the steamed bhaat na muthia portions onto a serving platter.Next we will make the seasoning for the Bhaat na Muthiya.", "Heat oil in a small pan on medium heat; add the mustard seeds, sesame seeds, curry leaves and allow them to crackle.Drizzle the seasoning on top of the Muthiya and garnish with the grated coconut and coriander leaves and serve.Serve these Bhaat Ka Muthiya Dhokla along with\u00a0Dhaniya Pudina Chutney\u00a0and a glass of cold\u00a0Chaas\u00a0as a tea time snack or as a quick weeknight dinner."]'::jsonb, 40, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Bhaat_Na_Muthia_Dhokla_recipe_4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/465.Bhaat_Na_Muthia_Dhokla_recipe_4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Udupi Style Huli Podi Recipe (Sambar Powder)', 'udupi-style-huli-podi-recipe-sambar-powder', 'Udupi Style Huli Pudi Recipe (Sambar mix Recipe) is an authentic recipe that is been followed by the people in the regions of Karnataka. This pudi mix is very famous among udupi, Mangalore and Malnad cuisine. The mix consists of right proportion of chana dal, urad dal, coriander seeds, fenugreek seeds, dry red chilli and curry leaves.', '["6 teaspoon White Urad Dal (Split)", "3 teaspoon Chana dal (Bengal Gram Dal)", "8 teaspoon Coriander (Dhania) Seeds", "2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "2 sprig Curry leaves", "20 Dry Red Chillies", "1 teaspoon Asafoetida (hing)", "2 tablespoons Oil"]'::jsonb, ARRAY['asafoetida (hing)', 'curry leaves', 'white urad dal (split)', 'coriander (dhania) seeds', 'dry red chillies', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making the Udupi Style Huli Pudi Recipe, heat oil in a sauce pan over a medium heat.Add the chana dal first and roast them for 10 seconds.", "Then you can go ahead and add the urad dal and roast it for 5 more seconds.Add the coriander seeds, cumin seeds, fenugreek seeds and roast for 5 seconds till the aroma is released.Go ahead and add the dry red chillies, hing and curry leaves and roast these for another 10 seconds.", "Serve the Udupi Style Huli Pudi in\u00a0Udupi sambar\u00a0and enjoy your meal with some steamed rice."]'::jsonb, 15, 'Udupi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Udupi_Style_Huli_Pudi_Recipe_Sambar_mix_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/466.Udupi_Style_Huli_Pudi_Recipe_Sambar_mix_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharastrian Kairichi Amti Recipe - Raw Mango Curry Recipe', 'maharastrian-kairichi-amti-recipe-raw-mango-curry-recipe', 'Maharashtrian Kairichi Amti Recipe (Gravied Green Mango) is a wonderful curry made with tangy raw mango that stewed in some spicy coconut curry.', '["1/2 cup Fresh coconut , grated", "2 Dry Red Chillies", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Coriander (Dhania) Seeds", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1 inch Ginger", "5 cloves Garlic", "Other Ingredients", "1 tablespoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 sprig Curry leaves", "1/2 teaspoon Turmeric powder (Haldi)", "1 Mango (Raw) , peeled and diced", "1 teaspoon Jaggery", "Salt , to taste"]'::jsonb, ARRAY['salt', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'jaggery', 'dry red chilli', 'mango', 'white urad dal (split)', 'coriander (dhania) seeds', 'dry red chillies', 'methi seeds (fenugreek seeds)', 'turmeric powder']::text[], '["To begin Maharashtrian Kairichi Amti Recipe, we will first prep all the ingredients and keep ready.To grind the fresh coconut masala; in a mixer jar, combine the grated coconut along with the dry red chillies, cumin seeds, coriander seeds, garlic, ginger, and methi seeds.", "Grind this mixture into a fine paste adding 1/2 cup of warm water.", "Set aside.", "To make the Maharashtrian Kairichi Amti Recipe, heat a pan with oil on medium heat.", "Add the mustard seeds and allow it to crackle.Stir in the curry leaves, the raw mango and a pinch of salt.", "Add \u00bc cup of water and cover the pan.", "Cook the mangoes in the water until soft.", "This will take about 4 to 5 minutes.Once the mangoes are cooked, stir in the coconut masala and simmer for another 5 minutes until the amti has come together and is well cooked.", "Check the salt and adjust to taste accordingly.", "Turn off the heat and serve hot.Serve the Maharashtrian Kairichi Amti Recipe along with steamed rice,\u00a0gajarachi koshimbir\u00a0and\u00a0Dal Palak Recipe\u00a0to enjoy your everyday meal."]'::jsonb, 40, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Maharastrian_Kairichi_Amti_Recipe_Raw_Mango_Curry_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/467.Maharastrian_Kairichi_Amti_Recipe_Raw_Mango_Curry_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Beetroot, Aloo & Amaranth Leaves Sabzi Recipe', 'beetroot-aloo-amaranth-leaves-sabzi-recipe', 'Beetroot, Aloo & Amaranth Leaves Sabzi Recipe, has all the good ingredients in one dish. The sabzi is simply tossed with hing, tempered cumin seeds and flavoured with red chilli powder, coriander powder and garam masala powder.', '["2 Beetroot , grated", "10 Baby Potatoes", "1 cup Green Amaranth Leaves , chopped", "1 Onion , sliced", "3 cloves Garlic , finely chopped", "2 Green Chillies , slit", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1 pinch SSP Asafoetida (Hing)", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "2 teaspoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "Salt , to taste", "2 teaspoon Mustard oil"]'::jsonb, ARRAY['salt', 'mustard oil', 'mustard seeds', 'asafoetida (hing)', 'red chilli powder', 'cloves garlic', 'onion', 'cumin seeds (jeera)', 'baby potatoes', 'green amaranth leaves', 'coriander powder', 'beetroot', 'turmeric powder', 'green chillies', 'garam masala powder']::text[], '["To begin making the Beetroot, Aloo & Amaranth Leaves Sabzi Recipe, pressure cook the baby potatoes in water for\u00a0 2 whistle.", "Let the pressure release naturally and then open the lid and peel the potatoes.", "Keep aside.Heat a kadai and add some oil.", "Once the oil is hot add mustard seeds, hing, cumin seeds and allow it to splutter for few seconds.", "After the seeds have spluttered add the garlic, green chillies and onions and saute till onions are soft.Once the onions have softened add the baby potatoes and roast for two minutes.Now add the masalas, haldi, coriander powder, chilli powder and stir well to combine.", "Once the masalas are well combined into the potatoes add the grated beetroot, salt to taste and stir.", "Add in the Amaranth leaves and combine everything well.", "Close the pan with a lid and cook till the leaves and beetroot are nearly done.", "Open the lid and stir in the garam masala and cook till the beetroot and amaranth leaves are cooked.Turn off the heat and transfer the\u00a0Beetroot, Aloo & Amaranth Leaves Sabzi into a serving owl.Serve the Beetroot, Aloo & Amaranth Leaves Sabzi Recipe along with\u00a0phulka,\u00a0Green Moong Dal Makhani\u00a0and\u00a0Sweet Potato & Green Bean Salad\u00a0by the side to make it a rich and delicious meal."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Beetroot_Aloo_Amarath_Leaves_Sabzi_recipe_6-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/468.Beetroot_Aloo_Amarath_Leaves_Sabzi_recipe_6-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Rasam Powder Recipe', 'chettinad-rasam-powder-recipe', 'The Chettinad Rasam Powder Recipe is a classic and traditional recipe of the powder that is used in south indian homes. ''Rasam'' or Charu/ Saaru is a flavourful South Indian Soup made from the juice of tamarind, tomatoes along with or without the Lentil broth. It can be sipped and enjoyed like a soup or mixed with rice. It is a great appetiser and has medicinal properties too. The Chettinad Rasam powder can be prepared in bigger batches and you can store them in an airtight container. It stays good for 3 to 6 months.', '["1 cup Dry Red Chillies", "1/2 cup Coriander (Dhania) Seeds", "1/4 cup Arhar dal (Split Toor Dal)", "1 tablespoon Cumin seeds (Jeera)", "1 tablespoon Whole Black Peppercorns", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 tablespoon Sesame (Gingelly) Oil"]'::jsonb, ARRAY['arhar dal (split toor dal)', 'sesame (gingelly) oil', 'black peppercorns', 'dry red chillies', 'coriander (dhania) seeds', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)']::text[], '["To begin making the Chettinad Rasam Powder Recipe, heat a medium size pan and dry roast the coriander seeds,fenugreek seeds and pigeon peas all separately.", "Roast them until they are crisp and the dals turn pinkish brown.Once roasted, set them aside to cool.In the same pan, heat 1/2 tablespoon oil in low heat and fry chillies for about 2 to 3 minutes and set it aside to cool.Heat the another 1/2 tablespoon of oil over low heat and fry cumin seeds and peppercorns separately till fragrant and set aside to cool.Combine all the above roasted chettinad rasam powder ingredients and grind them to a coarse powder and store the Chettinad Rasam powder in an airtight container.", "If you plan to use it occasionally, then place the bottle in the freezer and it will remain fresh for a long time."]'::jsonb, 35, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Uma_Raghuraman/Chettinad_Rasam_Powder.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/469.Chettinad_Rasam_Powder.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dal Palak Recipe With Moong & Masoor Dal', 'dal-palak-recipe-with-moong-masoor-dal', 'Dal Palak Recipe is a nutritious and wholesome dish that is rich in proteins and minerals. This recipe is made from fresh steamed spinach that is mixed along with cooked lentils and spices to make a delectable combination. The addition of a ghee tadka (seasoning) along with cumin and red chillies adds to flavour of the Dal Palak Recipe.', '["1/2 cup Yellow Moong Dal (Split)", "1/2 cup Masoor Dal (Whole)", "250 grams Spinach Leaves (Palak) , chopped and steamed", "1 Tomato , finely chopped", "1 inch Ginger , grated", "1 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Garam masala powder", "Salt , to taste", "Ingredients for seasoning", "1 tablespoon Ghee", "1/2 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies"]'::jsonb, ARRAY['tomato', 'salt', 'yellow moong dal (split)', 'ginger', 'cumin powder (jeera)', 'ghee', 'masoor dal', 'dry red chillies', 'cumin seeds (jeera)', 'turmeric powder', 'spinach leaves (palak)', 'garam masala powder']::text[], '["To begin making the Dal Palak recipe we will first cook the lentils (dal) using a pressure cooker using 3 cups of water.", "See video recipe of how to cook lentils using pressure cooker.Next we will cook the spinach with the spices.", "There are two ways you can do it - in a sauce pan by sauteeing it or in a pressure cooker.Below you will find the recipe of how you cook the spinach in a pressure cooker, as the method is really fast.", "If you are using a saucepan method, then follow the same procedure, but just cover the pan and cook until the spinach is soft.Into a pressure cooker, add a teaspoon of oil; add the ginger, green chillies, tomatoes, turmeric powder, cumin powder, garam masala powder, salt and spinach.", "Stir all the ingredients together just to combine them.", "Once combined, cover the pressure cooker, place the weight on.", "Pressure cook until you hear one whistle.", "After the first whistle, turn off the heat.", "We will now place the pressure cooker under cold running water to release the pressure immediately.", "This way, we will release the pressure quickly and the spinach does not get over-cooked and remain fresh and green.Now that you have the spinach and lentils ready, if your cooker is large enough, add the cooked dal into the spinach and give it a stir.", "Bring the Dal Palak to a quick boil.", "Our next step is to proceed to make the seasoning.", "Into a small saucepan, heat a tablespoon of ghee.", "Add in the cumin seeds and dry red chillies.", "Roast them until they crackle and sizzle.Add this seasoning to the Dal Palak and give it a stir.", "Serve the Dal Palak for a simple and healthy weeknight dinner along with steamed rice or\u00a0Paneer Pulav\u00a0or traditional\u00a0Tawa Parathas.", "Also, do make sure to slice up some onions, squeeze in some lemon and toss it along with salt and serve it with the Dal Palak.", "The combination is delicious."]'::jsonb, 55, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Dal_Palak_Recipe_Healthy_Spinach_Lentil_Curry-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/470.Dal_Palak_Recipe_Healthy_Spinach_Lentil_Curry-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Stuffed Mooli Paratha Recipe (Radish Flat Bread)', 'stuffed-mooli-paratha-recipe-radish-flat-bread', 'Stuffed Mooli Paratha Recipe is simple, wholesome healthy recipe that is made from grated white radish along with some spices is stuffed in a whole wheat flour dough. Stuffed Mooli paratha can be served for breakfast or any other meal, all throughout the year.', '["3 Mooli/ Mullangi (Radish) , finely grated", "2 teaspoon Extra Virgin Olive Oil", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Ginger , grated", "1-1/2 tablespoons Gram flour (besan) , (optional)", "Coriander (Dhania) Leaves , a handful, chopped", "2 Green Chillies , finely chopped", "Salt , to taste", "2 cups Whole Wheat Flour", "1 teaspoon Salt", "Extra Virgin Olive Oil , or ghee to smear while cooking", "1 teaspoon Salt", "Oil , or ghee to smear while cooking"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'ginger', 'wheat flour', 'figaro pure olive oil ghee', 'sunflower oil ghee', 'coriander (dhania) leaves', 'figaro pure olive oil', 'gram flour (besan)', 'mooli mullangi (radish)', 'green chillies']::text[], '["To begin making the Stuffed Mooli Paratha heat olive oil in a wide pan.Add the radish, salt and saute on high heat till all the moisture from radish evaporates.Turn off the heat and add the remaining ingredients for the stuffing and stir well to combine.Allow the stuffing mixture to cool down.Mix all the ingredients for the dough in a mixing bowl, add little water at a time and knead to make a smooth dough.", "Divide the dough into 8 portions.Dust a flat working surface with some flour.", "Roll a portion into a ball and flatten it using your fingers and roll it out into a 3 inch diameter circle.Place about 2 tablespoons of the stuffing in the center, gather the edge and seal it.", "Carefully roll it out into a circle about 6-7 inches in diameter.Heat a skillet over medium heat and cook the mooli paratha in olive oil until cooked through, and has golden brown spots on both sides.Repeat with the remaining portions of the dough and the mooli paratha filling.Serve Stuffed Mooli parathas on its own or with a\u00a0chutney,\u00a0raita\u00a0or\u00a0pickle\u00a0of choice."]'::jsonb, 65, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/0-Archana/7_short_format_Stuffed_mooli_Paratha_Video_Figaro_Olive_Oil_recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/471.7_short_format_Stuffed_mooli_Paratha_Video_Figaro_Olive_Oil_recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer Tikka Pulao Recipe', 'paneer-tikka-pulao-recipe', 'Paneer Tikka Pulao is a simple one pot meal that is prepared by cooking marinated and pan roasted Paneer tikka along with rice and spices in a pressure cooker.', '["1-1/2 cups Basmati rice", "1 Onion", "1 Green Chilli", "1 teaspoon Cumin seeds (Jeera)", "1 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "1 Bay leaf (tej patta)", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Garam masala powder", "2 teaspoon Oil", "Salt , as required", "200 grams Paneer (Homemade Cottage Cheese) , cubed into 1 inch thick pieces", "2 tablespoons Curd (Dahi / Yogurt)", "3 teaspoons Gram flour (besan)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "1 tablespoon Ginger Garlic Paste", "Coconut Oil , as required"]'::jsonb, ARRAY['basmati rice', 'salt', 'green chilli', 'cardamom (elaichi) podsseeds', 'bay leaf (tej patta)', 'paneer', 'red chilli powder', 'gram flour (besan)', 'curd', 'ginger garlic paste', 'onion', 'cumin seeds (jeera)', 'cinnamon stick (dalchini)', 'kasuri methi (dried fenugreek leaves)', 'coconut oil', 'turmeric powder', 'cloves (laung)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making Paneer Tikka Pulao, we will wash and soak basmati rice in water for 30 minutes.", "The next step is to make the marinade for the paneer.", "In a large bowl, combine curd, gram flour, ginger garlic paste, red chilli powder, garam masala powder and little salt.Mix everything together into thick paste.", "Add paneer cubes to the paste and mix well so that the paste is well coated on each paneer cube.", "Cover and refrigerate for 30 minutes.Heat a griddle and add two teaspoons cooking oil, place the paneer cubes and fry until slightly golden on all sides.", "Remove from tawa and keep aside.The next step is to make the pulao.", "Heat a teaspoon of oil in a pressure cooker and add cumin seeds, cinnamon, cloves, cardamom and bay leaf.", "Saute for a minute.Add chopped onion and slitted green chilli.", "Saute until the onions turn soft and translucent.Once the onions turn soft, add the paneer tikkas, turmeric powder, garam masala powder and mix lightly without breaking the paneer cubes.", "Drain the soaked basmati rice from water and add to the pressure cooker.", "Saute for a minute until the masalas coat on to the rice.Add 3 cups of water along with required amount of salt.", "Mix well and bring the water to a boil.Close the cooker and pressure cook for a whistle.", "Once the pressure releases naturally, gently fluff the rice with a fork.", "Garnish with coriander leaves.Serve Paneer Tikka Pulao along with Tomato Onion Raita or Tadka Raita for a simple sunday lunch or pack it for lunch box on a weekday."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swathynandhini/PANEER_TIKKA_PULAO_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/472.PANEER_TIKKA_PULAO_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bharwa Karela Makhani  Recipe - Stuffed Karela Masala Gravy', 'bharwa-karela-makhani-recipe-stuffed-karela-masala-gravy', 'Bharwa Karela Makhani Recipe is a delicious karela gravy recipe that can be relished by diabetics.', '["3 Karela (Bitter Gourd/ Pavakkai)", "1/2 cup Paneer (Homemade Cottage Cheese) , grated", "2 Potatoes (Aloo) , boiled and mashed", "Salt , to taste", "1/2 teaspoon Black pepper powder", "1 sprig Coriander (Dhania) Leaves , chopped", "1 sprig Mint Leaves (Pudina) , chopped", "1 teaspoon Oil", "1 teaspoon Oil", "2 Onions , finely chopped", "1 cup Homemade tomato puree", "1 inch Ginger , chopped", "4 cloves Garlic , chopped", "1 Green Chilli , chopped", "1/2 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Garam masala powder", "1 pinch Sugar", "2 tablespoons Fresh cream", "Salt , to taste"]'::jsonb, ARRAY['karela', 'bitter gourd/ pavakkai', 'paneer', 'homemade cottage cheese', 'potatoes', 'aloo', 'salt', 'black pepper powder', 'coriander', 'dhania', 'mint leaves', 'pudina', 'oil', 'onions', 'homemade tomato puree', 'ginger', 's garlic', 'reen chilli', 'red chilli powder', 'coriander powder', 'cumin powder', 'jeera', 'garam masala powder', 'sugar', 's fresh cream']::text[], '["To begin making the\u00a0Bharwa Karela Makhani Recipe, wash the karela well, and very lightly peel of the skin, allow the green of the karela to be there, as its important for health.Cut the karela into three pieces, horizontally.", "Gently scoop out the flesh and seeds from inside the karela, in a way that you should be left with hollow cylinders of the karela pieces.", "In a pressure cooker, add the karela pieces and two tablespoons of water and pressure cook for one whistle.", "Turn off the heat and allow the pressure to release naturally.", "Drain the water if any and transfer the karela into a bowl and set aside.\u00a0*For the Bharwa Karela StuffingIn a mixing bowl, combine the grated paneer, mashed potatoes, salt and pepper, chopped coriander and mint leaves.", "Mix well.", "Stuff\u00a0Karela Stuffing mixture generously into the karela cylinders.", "Heat a pan with oil on medium flame, place the\u00a0Bharwa Karela in it and cook until slightly roasted turning them around from time to time.", "This will take about 5-7 minutes.", "Once the Bharwa Karela have got a nice brown colour, turn off thee flame and set aside.\u00a0*For the Bharwa Karela Makhani gravyIn a saucepan heat oil on medium flame, add the chopped ginger garlic and saute for a couple of minutes.", "Next add in the onions and saute till they turn into a light brown colour.", "This will take about 6-8 minutes.", "Once the onion-ginger-garlic is well cooked, add in the green chilies and tomato puree, cover and cook for 5 minutes.", "After 5 minutes, open the lid and add in all the dry masalas-\u00a0red chilli powder, coriander powder,\u00a0\u00a0jeera powder,\u00a0\u00a0garam masala powder, sugar and salt.", "Bring the\u00a0Bharwa Karela Makhani gravy to a single boil.", "Turn down the flame, mix in the cream.", "Once the cream is well combined, turn off the flame.", "In a serving plate arrange the Bharwa Karela and then pour the Makhani gravy over it.", "Serve the Bharwa Karela Makhani hot.Serve\u00a0Bharwa Karela Makhani Recipe\u00a0along with\u00a0Ragi Tawa Paratha,\u00a0Beetroot Raita Recipe,\u00a0Kala Chana Salad Recipe With Carrots, Cucumber & Tomatoes\u00a0for a simple Diabetic Friendly meal."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sneha-archanaskitchen.com/Bharwa_Karela_Masala_Recipe__Stuffed_Karela_In_Gravy_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/473.Bharwa_Karela_Masala_Recipe__Stuffed_Karela_In_Gravy_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Urulaizhilangu Podimas (South Indian Style Potato Mash)', 'urulaizhilangu-podimas-south-indian-style-potato-mash', 'Urulaizhilangu Podimas is a very popular recipe from Tamil Nadu. It is also a simple recipe to cook and serve in no time. It is mildly spiced and is a perfect dish to be had along with Plain Rice and Rasam on a rainy day. It uses very little oil and spice making it a healthier choice to even pack it in kids lunch box. Serve this amazing Urulaizhilangu Podimas with Steamed Rice and Tomato Rasam or Sambar for the weeknight dinner along with some roasted papads.', '["1/2 kg Potatoes (Aloo) , boiled", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon White Urad Dal (Split)", "2 Dry Red Chillies", "1 sprig Curry leaves", "Asafoetida (hing) , A pinch", "Salt , to taste", "To grind to coarse mix", "2 tablespoons Fresh coconut , grated", "1 Dry Red Chilli"]'::jsonb, ARRAY['potatoes', 'aloo', 'oil', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'dry red chillies', 'curry leaves', 'asafoetida', 'hing', 'salt', 'to grind to coarse mix', 's fresh coconut', 'dry red chilli']::text[], '["To begin making Urulaizhilangu Podimas (South Indian Style Potato Mash) Recipe, wash and pressure cook the potatoes for two whistles.", "Once cooked release the steam, peel the skin of the potatoes, roughly mash it with your hands and keep it aside.Next, prepare the coconut and dry red chilli coarse mix using a mixer grinder and keep aside.Now, heat oil in a pan in medium heat, add mustard seeds and urad dal, and let it splutter.Add the pinch of asafoetida, dry red chillies and a sprig of curry leaves and let the curry leaves splutter.Now, add the roughly mashed boiled potatoes and give it a good stir.season with salt, mix and cook in medium heat for a few minutes.switch off the flame, add the coarse coconut and red chilli mix to the potatoes and mix it evenly.Serve the Urulaizhilangu Podimas with Steamed Rice and Tomato Rasam or Sambar along with some roasted papad for a weeknight dinner."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/urulaizhilangu_Podimas_South_Indian_Style_Potato_Mash.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/474.urulaizhilangu_Podimas_South_Indian_Style_Potato_Mash.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mullangi Mor Pachadi Recipe (Radish in spicy tempered Yogurt Gravy Recipe)', 'mullangi-mor-pachadi-recipe-radish-in-spicy-tempered-yogurt-gravy-recipe', 'Mullangi Mor Pachadi Recipe (Radish in spicy tempered Curd Gravy Recipe) is a wonderful way to add radish in curd to make a spicy curry. The sourness from the curd complements well with the flavor of the radish. Radish is a diabetic friendly vegetable as it is considered as one of the nutritional root vegetable. It is rich in Vitamin C and minerals such as iron and magnesium.', '["1 cup Mooli/ Mullangi (Radish) , grated", "1 cup Hung Curd (Greek Yogurt)", "Salt , to taste", "1 tablespoon Oil", "2 Green Chillies , slit", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "1 teaspoon Asafoetida (hing)"]'::jsonb, ARRAY['salt', 'hung curd (greek yogurt)', 'mustard seeds', 'asafoetida (hing)', 'curry leaves', 'white urad dal (split)', 'mooli mullangi (radish)', 'green chillies', 'sunflower oil']::text[], '["We begin making the Mullangi Mor Pachadi Recipe (Radish in spicy tempered Yogurt Curry Recipe) by heating the kadai with oil, splutter mustard seeds and urad dal along with curry leaves and hing.Add in the green chilies and grated radish.", "Saute till the radish is cooked and make do not roast them or brown them.", "You can add little water and cover it with a lid and let it cook.Once done leave it to cool down.In a bowl, whisk in the curd with salt and little water according to your consistency, add in the sauteed radish and mix well and serve.Serve the Mullangi Mor Pachadi Recipe (Radish in spicy tempered Curd Gravy Recipe) with just\u00a0hot steam rice\u00a0or can be had with any\u00a0stuffed paratha."]'::jsonb, 15, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Mullangi_Mor_Pachadi_Recipe_Radish_in_spicy_tempered_Curd_Gravy_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/475.Mullangi_Mor_Pachadi_Recipe_Radish_in_spicy_tempered_Curd_Gravy_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Raw Banana and Banana Stem Stuffed Paratha Recipe', 'raw-banana-and-banana-stem-stuffed-paratha-recipe', 'Raw Banana and Banana Stem Stuffed Paratha Recipe is a super healthy stuffed Indian bread that contains two ingredients that have a good nutritional value. Parathas are a staple breakfast for most of the North Indian people. It is usually made with Aloo, onion or paneer as a stuffing. But it is very rare to use raw banana and raw stem in a stuffed paratha, here in this recipe we have put them together in one dish that is made super delicious and can be had without any guilt as your morning breakfast.', '["1 Banana Stem , cut into small pieces", "2 Raw Banana , boiled and mashed", "1 Onion , chopped", "4 cloves Garlic , chopped", "1 inch Ginger , chopped", "1 Green Chilli , chopped", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "1 teaspoon Black pepper powder", "1 teaspoon Amchur (Dry Mango Powder)", "Salt , to taste", "1 cup Whole Wheat Flour"]'::jsonb, ARRAY['salt', 'wheat flour', 'ginger', 'green chilli', 'amchur (dry mango powder)', 'banana stem', 'red chilli powder', 'cloves garlic', 'onion', 'cumin seeds (jeera)', 'black pepper powder', 'turmeric powder', 'banana', 'garam masala powder']::text[], '["To begin making the by boiling the raw banana in the pressure cooker.", "Cut the banana into two pieces, remove the edges, boil it with water and salt for about 4 whistle.Once done, release the pressure naturally, remove the skin and mash it into a fine mixture.Heat a saucepan with oil, add cumin seeds and allow it splutter for 10 seconds.", "Add chopped onions, garlic, ginger and saute until it softens.Add the chopped banana stem along with \u00bd cup water and cover it with a lid and cook for about 15 minutes until the banana stem is cooked.To this add all the spice powder like turmeric powder, red chilli powder, garma masala, amchur powder, salt and pepper powder and also add the mashed raw banana.Mix well and cook the mixture for about 10 more minutes on low heat and switch it off.In order to make the dough, knead all the ingredients well into a soft dough .Now to begin making the paratha, keep some flour aside for dusting.", "Divide the dough into large lemon side balls.Dust the dough portions in flour, flatten it and roll it into a 3 inch diameter circle.", "Place the filling on half side of the circle and close the paratha by folding it from all sides.", "Yes it\u2019s as simple as that.You will have a big dumpling.Press it slightly and gently use the rolling pin to flatten it.", "Take care, the filling can ooze out if the dough is rolled out too thin.Now to cook the Paratha, first preheat the skillet on medium heat.", "Place the rolled paratha on top and allow it to cook on one side.", "After about 10 to 15 seconds, flip the paratha.At this stage, smear some oil or ghee to cook the paratha.", "Cook the paratha by flipping over a couple of times until you see golden brown spots on both sides.Serve the Raw Banana and Banana Stem Stuffed Paratha along with fresh cup of\u00a0curd\u00a0by the side or\u00a0Aam Ka Chunda Recipe\u00a0to go along with your paratha."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Raw_Banana_and_Banana_Stem_Stuffed_Paratha_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/476.Raw_Banana_and_Banana_Stem_Stuffed_Paratha_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chicken Kappa Biryani Recipe', 'chicken-kappa-biryani-recipe', 'Chicken Kappa Biryani Recipe is an authentic Kerala recipe to which we have added a twist by using chicken instead of beef. Most of us are aware of Biryani made with any type of rice but in Kerala since tapioca is consumed a lot.', '["500 grams Tapioca root , skin peeled and chopped into small cubes", "250 grams Chicken , minced", "1 Onion , sliced", "5 cloves Garlic , chopped", "1 inch Ginger , chopped", "1 sprig Curry leaves", "1 Green Chilli , sliced", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "2 teaspoons Garam masala powder", "1 teaspoon Black pepper powder", "3 tablespoons Fresh coconut , grated", "Salt , to taste", "Coconut Oil , for cooking"]'::jsonb, ARRAY['salt', 'ginger', 'green chilli', 'coconut', 'red chilli powder', 'cloves garlic', 'curry leaves', 'onion', 'chicken', 'coconut oil', 'black pepper powder', 'turmeric powder', 'tapioca root', 'garam masala powder']::text[], '["To begin making the Chicken Kappa Biryani Recipe, we will first pressure cook the tapioca in pressure cooker with salt to 6 whistles.The tapioca must be boiled enough so that it is easy for you to mash it.", "Once done allow the pressure cooker to release the pressure naturally.Drain the water, transfer the tapioca in a bowl and mash it well, leaving it a bit chunky as well.", "Set aside.", "Heat a kadai with coconut oil, add curry leaves and allow it splutter.", "Add ginger, garlic and saute for a few minutes.", "Add sliced onions and saute till they turn translucent.", "Now add all the spice powders-\u00a0\u00a0turmeric powder, red chilli powder,\u00a0garam masala powder and\u00a0pepper powder,\u00a0give it a good stir.Add minced chicken and cook until the chicken is done.", "This will take about 18-20 minutes.", "Add the cooked and mashed tapioca, mix them well.By using a masher try to mash the tapioca a little more and also keep few chunks as well for a good texture.Serve the Chicken Kappa Biryani Recipe along with\u00a0potato theeyal\u00a0or\u00a0Tomato Onion Cucumber Raita\u00a0to enjoy your Sunday lunch."]'::jsonb, 55, 'Kerala', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Chicken_Kappa_Biryani_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/477.Chicken_Kappa_Biryani_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Stuffed Gilka Recipe (Maharashtrian Style Stuffed Silk Squash)', 'stuffed-gilka-recipe-maharashtrian-style-stuffed-silk-squash', 'Stuffed Gilka is a spicy, flavourful side dish that takes the humble Gilka (silk squash) to another level. The spiced filling mixture is versatile and can be used to stuff other vegetables like brinjals, potatoes, okra etc.', '["6 Gilka (sponge/silk squash) , cut into about 3 inch pieces", "1 teaspoon Cumin seeds (Jeera)", "1 tablespoon Oil", "Coriander (Dhania) Leaves , as required for garnish (chopped)", "2 Onions , finely chopped", "7 cloves Garlic , crushed", "3 tablespoon Groundnut powder", "2 tablespoon Sesame powder , roasted", "2 teaspoons Red Chilli powder", "2 teaspoon Maharashtrian Goda Masala", "1 teaspoon Jaggery , grated", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Asafoetida (hing)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'coriander (dhania) leaves', 'asafoetida (hing)', 'jaggery', 'red chilli powder', 'gilka (spongesilk squash)', 'cloves garlic', 'sesame powder', 'onion', 'cumin seeds (jeera)', 'maharashtrian goda masala', 'groundnut powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Stuffed Gilka, we will first make the stuffing.In a bowl mix all ingredients mentioned under stuffing.", "Mix everything properly and keep it aside.Next, make a slit length wise in each gilka piece without cutting through.", "Carefully stuff about a tablespoon of the filling inside the cut.Heat oil in a flat non-stick pan.", "Add the cumin seeds and the place the stuffed gilka in the pan, cut side up.Cover and cook for 3-4 minutes on low flame.", "Carefully turn over the pieces and cook on the other side till soft but the pieces are still intact.", "Use 1-2 tablespoon water if required for cooking.", "Garnish with coriander leaves and serve.Serve Stuffed Gilka with\u00a0Dal Tadka,\u00a0Kachumber Salad\u00a0and\u00a0Tawa Paratha\u00a0for a spicy, flavourful meal."]'::jsonb, 30, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/madhulia/Stuffed_Gilka_Maharashtrian_style_stuffed_Silk_Squash.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/478.Stuffed_Gilka_Maharashtrian_style_stuffed_Silk_Squash.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chocolate Rava Ladoo Recipe', 'chocolate-rava-ladoo-recipe', 'Chocolate Rava Ladoo Recipe, sounds interesting, isn''t it? Chocolate, all time favourite of kids and these ladoo are a superb snack for them and even the adults who enjoy it as much as the kids. These ladoos are easy to make, and are full of nuts. The rava is roasted and mixed along with almond powder, roasted raisins and cashews and cocoa powder. They are wholesome and a great snack to have to give you the right boost of energy.', '["1 1/2 cup Sooji (Semolina/ Rava)", "1/4 cup Ghee", "2 tablespoons Cocoa Powder", "1/2 cup Sugar", "1/4 cup Whole Almonds (Badam) , finely powdered", "1/2 teaspoon Cardamom Powder (Elaichi)", "1/4 cup Sultana Raisins", "1/4 cup Cashew nuts", "1/4 cup Dessicated Coconut"]'::jsonb, ARRAY['cashew nuts', 'ghee', 'coconut', 'raisins', 'sugar', 'badam (almond)', 'cardamom powder (elaichi)', 'cocoa powder', 'sooji (semolina rava)']::text[], '["To begin making the Chocolate Rava Ladoo Recipe,\u00a0 first, melt a teaspoon of ghee in a small pan on low heat; roast the cashew nuts until lightly golden and crisp.", "Once roasted add in the raisins and saut\u00e9 for a few seconds.", "Turn off the heat and keep this aside.Heat 1/4 cup of ghee in a pan; add in the rava / semolina to the pan.", "Roast the rava until you get a roasted aroma and it is turning slightly golden in color.", "It is important to roast the rava, stirring continuously on very low heat.", "High heat can cause the rava to brown.Once roasted add in the almond powder, roasted cashews and raisins, cardamom powder and sugar.Saute for just a few more seconds until the mixture is well combined.", "Allow it to cool slightly.", "Once cooled, add the cocoa powder and shape the chocolate rava ladoo mixture into 15 equal size balls.If you are unable to hold the mixture and shape it into a ball; add in a tablespoon of milk or ghee or both to help it come together.The Rava Ladoos are now ready to be served.", "Store them in an airtight container for about 2 weeks and serve it for the festivals or simply as a dessert after your meal.Serve\u00a0Chocolate Rava Ladoo Recipe\u00a0during festivals or special occasions to your guests with some tea time snacks like\u00a0Cheese Crackers\u00a0and\u00a0Baked Banana Chips."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Chocolate_Rava_Ladoo_Recipe_17_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/479.Chocolate_Rava_Ladoo_Recipe_17_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dubki Wale Aloo Recipe - Potatoes In A Spicy North Indian Gravy', 'dubki-wale-aloo-recipe-potatoes-in-a-spicy-north-indian-gravy', 'Dubki Wale Aloo Recipe as it is called in Mathura, Uttar Pradesh, is a spicy gravy of potatoes is famously eaten along with puris. It is a no-onion-no-garlic recipe which makes it perfect for fasting too. Popularly eaten at breakfast time along with puris, it also makes a delicious side dish for lunch with Parathas and a Pumpkin Dal with Garlic Tadka. Serve it either for lunch or dinner, or even as part of an Indian style weekend brunch, or festival meal.', '["6 Potatoes (Aloo) , boiled", "1 Tomato , pureed", "2 teaspoons Coriander (Dhania) Seeds , roasted and crushed coarsely", "2 teaspoons Red Chilli powder", "1/2 teaspoons Turmeric powder (Haldi)", "1 teaspoon Amchur (Dry Mango Powder)", "2 teaspoon Ginger , grated", "1/2 teaspoon Methi Seeds (Fenugreek Seeds) , slightly crushed", "1 teaspoon Cumin seeds (Jeera)", "4 Dry Red Chillies , broken into 2", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "Asafoetida (hing) , A pinch"]'::jsonb, ARRAY['tomato', 'ginger', 'amchur (dry mango powder)', 'asafoetida (hing)', 'red chilli powder', 'coriander (dhania) seeds', 'dry red chillies', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'potato (aloo)', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)']::text[], '["To begin making Dubki Wale Aloo Recipe, first roughly break the boiled potatoes into small pieces.", "Take care not to mash it too fine.", "Make sure the potatoes remain chunky.Then, place a kadhai or a handi on the heat.", "Warm some mustard oil until smoky.", "Then reduce the heat to very low, add cumin seeds and broken chilies and allow them to sputter.Next, add the crushed methi seeds and asafoetida followed by the grated ginger.", "Toss it all for a few seconds until aromatic.Once done add the tomatoes and saute on a high heat for 3-4 minutes.Once the tomatoes are soft add the roasted crushed coriander, red chilli powder, turmeric and mix well to combine.After the masalas are all mixed with the tomatoes add in the potatoes and gently mix so they get coated with the spices.Once done add water depending upon the consistency you require.", "This recipe calls for 3 cups of water, which gives a runny gravy.Bring the dubki Wale Aloo to a boil and then reduce the heat.", "Allow it to simmer for 5-6 minutes.Lastly, sprinkle the kasuri methi and cook for another minute.", "Turn the heat off.Transfer the Dubki Wale Aloo Recipe into a serving bowl and garnish with\u00a0coriander leaves and serve.", "Serve hot with Bedmi Puris,\u00a0Whole Wheat Puris\u00a0or\u00a0Bedmi Poori\u00a0or\u00a0Parathas\u00a0of your choice for breakfast."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Farrukh_Aziz_Ansari/Dubki_Wale_Aloo.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/480.Dubki_Wale_Aloo.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Masaledar Moongphali Til Wale Aloo Recipe', 'masaledar-moongphali-til-wale-aloo-recipe', 'Masaledar Moongphali Tilwale Aloo, is a dry side dish made using baby potatoes cooked along with the skin, where the potatoes are first boiled and then pan fried with some ginger garlic and everyday masalas, finished with a squeeze of fresh lemon juice.', '["2 teaspoons Sesame seeds (Til seeds)", "3 tablespoons Raw Peanuts (Moongphali)", "15 Baby Potatoes", "Salt , to taste", "1-1/2 tablespoons Oil", "1 teaspoon Cumin seeds (Jeera)", "1 Green Chillies , slit", "1 inch Ginger , chopped", "4 cloves Garlic , finely chopped", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "2 teaspoons Lemon juice", "1 tablespoon Coriander (Dhania) Leaves , chopped", "1 tablespoon Mint Leaves (Pudina) , chopped", "1 teaspoon Chaat Masala Powder"]'::jsonb, ARRAY['salt', 'green chillies', 'ginger', 'cumin powder (jeera)', 'coriander (dhania) leaves', 'chaat masala powder', 'red chilli powder', 'cloves garlic', 'cumin seeds (jeera)', 'peanuts (moongphali)', 'baby potatoes', 'lemon', 'mint leaves (pudina)', 'sesame seeds (til seeds)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Masaledar Moongphali Tilwale Aloo Recipe, wash the baby potatoes and pressure cook them for 1 whistle and release the pressure.", "Drain and set aside.In a pan, heat oil on medium heat, add the cumin seeds, green chillies and ginger.", "When the seeds begin to change colour, add the garlic paste and saut\u00e9 for two or three minutes.Now add the peanuts and boiled potatoes along with the skin and pan fry till the peanuts and potatoes are well roasted.", "Once the potatoes get a nice crispy skin, add the sesame seeds, cumin powder, chilli powder, garam masala powder and salt.", "Continue to cook for five minutes, tossing continuously.", "Finally stir in the lemon juice, coriander and mint leaves and turn off the heat.Your Masaledar Moongphali Tilwale Aloo is ready to be served.Serve this\u00a0Masaledar Moongphali Tilwale Aloo, with\u00a0Dal Banjara Recipe (Langar Wali Dal)\u00a0and\u00a0Pudina Tawa Paratha Recipe (Mint Leaf Skillet Flat Bread)\u00a0for a weekday meal."]'::jsonb, 20, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/Khatte_Moongphali_Aloo_Masala_Recipe_Spicy_And_Tangy_Peanut_And_Potato_Roast-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/481.Khatte_Moongphali_Aloo_Masala_Recipe_Spicy_And_Tangy_Peanut_And_Potato_Roast-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Green Moong Dal Paratha Recipe - Stuffed Lentil Flatbread', 'green-moong-dal-paratha-recipe-stuffed-lentil-flatbread', 'The Green Moong Dal Paratha recipe a healthy and delicious flat bread that is stuffed with a flavourful cooked green moong dal, onion, green chillies, ginger and coriander leaves filling. It is minimally spiced with cumin powder and coriander powder which lends a great taste to the moong dal stuffing .The Moong Dal Paratha is a perfect way to add the proteins to your diet. Have it for dinner or a sunday brunch and enjoy the goodness of the lentils with your family.', '["Ingredients for the filling of the Moong Dal Paratha", "1 cup Green Moong Dal (Split)", "2 inch Ginger , finely chopped", "2 Green Chillies , finely chopped", "1 Onion , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera)", "2 tablespoons Coriander (Dhania) Leaves , finely chopped", "Salt , to taste", "Ingredients for the dough", "2 cups Whole Wheat Flour", "1/4 teaspoon Salt", "Water , as needed", "Ghee , or oil for cooking"]'::jsonb, ARRAY['ingredients for the filling of the moong dal paratha', 'green moong dal', 'split', 'ginger', 'reen chillies', 'onion', 'turmeric powder', 'haldi', 'cumin powder', 'jeera', 's coriander', 'dhania', 'salt', 'ingredients for the dough', 's whole wheat flour', 'water', 'ghee']::text[], '["To begin making the\u00a0Green Moong Dal Paratha Recipe soak the moong dal in 1-1/2 cups for 30 minutes and cook using the pressure cooker method or a saucepan method cook until soft.", "Drain any excess water after it is cooked.", "You can use this water to make a soup.In a large bowl; coarsely mash the green moong dal and add in the remaining ingredients like the onions,green chillies, ginger, coriander leaves, turmeric powder, cumin powder coriander powder and salt to taste.", "Stir well to combine and divide the filling into 10 to 12 portions.In another bowl; combine the whole wheat flour and salt for the dough.", "Add a little water at a time and knead to make a soft and smooth dough.", "Cover the dough and allow it to rest for about 10 minutes.", "Divide the dough into 10 to 12 portions.This process of dividing and keeping the portions of dough and filling ready, helps you gauge the number of parathas you can make and if you need more or less of the filling.Take a dough portion dust it in flour and flatten it on the rolling board by pressing it down.", "Roll the dough out into approximately 3 inch diameter circles dusting with flour in between to prevent the dough from sticking to the surface.", "Place this rolled dough to the side.Take another dough portion, dust it with flour again and roll into approximately 3 inch diameter circle.Now place a portion of the green moong dal filling in the circle and spread it evenly around.Next, take the other rolled portion of the dough and place it over the filling.Press and fold the edges so that the filling does not come out while cooking the paratha.", "Once sealed press down the paratha with your palms to release any air pockets.", "And give it a gentle roll with the pin to even it out.", "Proceed the same way with the remaining dough and filling portions.Now we will get into the final steps of cooking the moong dal paratha, preheat a skillet on medium heat and place the filled dough.Allow it to cook on medium heat for about 30 to 45 seconds and flip over.", "Add this stage add a teaspoon of ghee or oil and spread it around.Flip again, so the oiled side can cook on the skillet.", "Spread a little more ghee and keep pressing the parathas while on the skillet to cook the paratha evenly from inside out.Do the flipping over process a couple of times until both sides get cooked, browned and crisp evenly.", "Make sure you cook on medium heat as it allows the parathas to get a crisp and soft texture.Once the paratha is cooked transfer to a plate.", "Continue to the remaining dough portions the same way and serve Moong dal parthas hot.Serve\u00a0Green Moong Dal Paratha\u00a0along with\u00a0Lauki Raita\u00a0and make it a complete meal."]'::jsonb, 120, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breads/Moong_Dal_Paratha_Stuffed_Lentil_Flat_Bread-1-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/482.Moong_Dal_Paratha_Stuffed_Lentil_Flat_Bread-1-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lagan Ki Machli Recipe - Delicious Pomfret Curry', 'lagan-ki-machli-recipe-delicious-pomfret-curry', 'Lagan Ki Machli Recipe is a lovely fish curry made with a fresh pomfret fish.', '["2 Pomfret fish", "1 tablespoon Ginger , paste", "1 tablespoon Garlic , paste", "Salt , to taste", "1 tablespoon Lemon juice", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 tablespoon Oil", "1 teaspoon Cumin seeds (Jeera)", "1 Star anise", "1/2 inch Cinnamon Stick (Dalchini)", "2 Dry Red Chillies", "2 Onions , sliced", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "Salt , to taste", "1/3 cup Homemade tomato puree", "1/3 cup Curd (Dahi / Yogurt)", "2 sprig Coriander (Dhania) Leaves"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'pomfret fish', 'sunflower oil', 'garam masala powder', 'coriander powder', 'red chilli powder', 'curd', 'coriander (dhania) leaves', 'dry red chillies', 'cinnamon stick (dalchini)', 'lemon', 'cumin seeds (jeera)', 'onion', 'ginger paste', 'turmeric powder', 'star anise', 'garlic paste']::text[], '["To begin making the Lagan Ki Machli Recipe we will first mariante the pomfret fish."]'::jsonb, 55, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Lagan_Ki_Machli_Recipe_With_Pan_Fried_Pomfret-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/483.Lagan_Ki_Machli_Recipe_With_Pan_Fried_Pomfret-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tamatar Wali Arbi Sabzi Recipe', 'tamatar-wali-arbi-sabzi-recipe', 'Tamatar Wali Arbi Sabzi Recipe is a delicious dry sabzi recipe made with Colocasia. The par boiled colocasia is shallow fried and tossed in a garlic and tomatoes gravy flavoured with panch phoran masala. The panch phoran lends a beautiful flavour and texture to the dish.', '["500 grams Colocasia Leaves (Arbi) , boiled", "1 Onion , finely chopped", "4 Tomatoes , finely chopped", "7 cloves Garlic , thinly sliced", "1 Tamarind , lemon sized", "2 teaspoons Kashmiri Red Chilli Powder", "3 teaspoons Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "2 teaspoon Panch Phoran Masala", "2 tablespoons Oil", "2 sprig Coriander (Dhania) Leaves , finely chopped for garnish", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'colocasia leaves (arbi)', 'salt', 'kashmiri red chilli powder', 'sunflower oil', 'cloves garlic', 'coriander (dhania) leaves', 'onion', 'panch phoran masala', 'coriander powder', 'turmeric powder', 'garam masala powder', 'tamarind lemon']::text[], '["To begin making the Tamatar Wali Arbi Sabzi Recipe, wash the colocasia under running water to get rid of the mud.Soak the tamarind in one cup of water for fifteen minutes.Pressure cook with 2 cups of water, tamarind water for 2 whistles.", "Let the pressure release naturally and open the pressure cooker.", "Remove the peels of the arbi/colocasia and\u00a0 cut them into roundels and keep aside.Heat a tablespoon of oil in a heavy bottomed pan, add the colocasia roundels and shallow fry until they turn golden brown and keep aside.Add the remaining oil to the pan, add in the panch phoran and let the seeds splutter.", "Add the onions and garlic, saute until it turns golden brown.Add the tomatoes and saute until it turns soft and mushy.", "Add the turmeric, kashmiri red chilli, coriander powder and mix well.Now, add the shallow fried colocasia roundels, season with salt and mix well.Let the colocasia roundels absorb the tomato gravy into it and turn a bit soft.", "Keep stirring Occasionally.Once done, switch off the heat, garnish Tamatar Wali Arbi Sabzi\u00a0with coriander leaves and serve.Serve the\u00a0Tamatar Wali Arbi Sabzi Recipe along with\u00a0Tawa Paratha,\u00a0Dal Tadka\u00a0and\u00a0Kachumber Salad\u00a0for a simple yet delicious weeknight dinner."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Tamatar_Wali_Arbi_Sabzi_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/484.Tamatar_Wali_Arbi_Sabzi_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Style Prawn Biryani Recipe', 'chettinad-style-prawn-biryani-recipe', 'Chettinad Style Prawn Biryani Recipe is a South Indian version that is cooked with assorted spices and given the authentic Chettinad flavors by a wide usage of shallots, black pepper and coconut. Chettinad of cooking is an integral part of South Indian Cuisine, the rustic flavors of South India brings and amazing texture, flavor, and aroma to the food preparations. Chettinad spices are used both in vegetarian and nonvegetarian cooking and leave an equal impact on both versions. Typically served with raita, Chettinad style Prawn Biryani is a complete and a wholesome meal in itself.', '["200 grams Shrimps , or prawns", "1-1/2 cups Basmati rice", "4-5 Shallots", "1 tablespoon Ginger , paste", "1 tablespoon Garlic , paste", "3 tablespoons Fresh coconut , grated", "1 teaspoon Green Chilli , paste", "1/2 cup Hung Curd (Greek Yogurt)", "2 sprig Curry leaves", "1 cup Oil", "2 tablespoons Ghee", "Spice Mix", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "5-6 Whole Black Peppercorns", "4 Cardamom (Elaichi) Pods/Seeds", "2 Black cardamom (Badi Elaichi)", "1 inch Cinnamon Stick (Dalchini)", "2 Bay leaves (tej patta)", "2-3 Dry Red Chilli", "1/2 teaspoon Cumin seeds (Jeera)"]'::jsonb, ARRAY['basmati rice', 'black peppercorns', 'curry leaves', 'cumin seeds (jeera)', 'turmeric powder', 'green chilli paste', 'sunflower oil', 'black cardamom (badi elaichi)', 'ginger paste', 'cardamom (elaichi) podsseeds', 'garam masala powder', 'coconut', 'red chilli powder', 'dry red chilli', 'garlic paste', 'hung curd (greek yogurt)', 'bay leaves (tej patta)', 'ghee', 'shrimps prawns', 'cinnamon stick (dalchini)', 'coriander powder']::text[], '["To prepare Chettinad Style Prawn Biryani Recipe, wash and clean prawns well, collect in a bowl and add ginger garlic paste, red chili powder, turmeric, few drops of lemon juice and 2-3 pinch salt.", "Mix well and marinate for 15-20 minutes.Wash and soak rice in water for a minimum 30 minutes before cooking.Heat oil in a large and thick bottomed handi and add the whole spices and wait till they splutter.Now add shallots and saute them till they are pale in color.Add green chili paste, grated coconut and marinated prawns and mix well.Fry for 4-5 minutes and then slowly add curd and carefully mix everything to avoid breaking the prawns.Keep the flames high and let the water from curd dry up completely.Season with coriander powder, garam masala powder and salt.", "Fry till it is cooked and deeper in color.Now add the soaked rice and again stir well such that everything incorporates well with each other.Add warm water (double the quantity of rice), check salt and add a dollop of ghee and mix well.Allow the rice to come to a boil, close the lid and let the rice cook at low heat.Keep the lid covered till the rice is done.", "Gently mix the rice and collect in a serving bowl.Garnish with chopped coriander and chopped curry leaves.Serve the Chettinad Style Prawn Biryani hot with\u00a0raita\u00a0for a\u00a0wholesome meal."]'::jsonb, 55, 'Chettinad', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shaheen_Ali/CHETTINAD_STYLE_PRAWN_BIRYANI.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/485.CHETTINAD_STYLE_PRAWN_BIRYANI.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Layered Vegetable Tricolor Biryani Recipe', 'layered-vegetable-tricolor-biryani-recipe', 'The Layered Tricolour Biryani recipe is a combination of colors of the made with natural vegetable ingredients.', '["Main ingredients", "2 cups Rice", "Salt , to taste", "3 tablespoons Ghee", "Ingredients for orange layer", "1/2 cup Green beans (French Beans) , chopped and steamed", "1/2 cup Carrot (Gajjar) , chopped and steamed", "2 tablespoons Garlic , paste", "2 tablespoons Ginger , paste", "1 cup Onions , chopped", "1 cup Tomatoes , chopped", "2 tablespoons Green Chillies , paste", "2 cloves Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "1 Bay leaves (tej patta)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1/2 cup Curd (Dahi / Yogurt)", "1/2 cup Mint Leaves (Pudina) , chopped", "2 tablespoons Oil", "Ingredients for white layer", "1 cup Potato (Aloo) , boiled and cubed", "2 teaspoons Green Chillies , chopped", "1 tablespoon Onions , caramelised", "1/2 teaspoon Oil", "Ingredients for green layer", "1 cup Spinach Leaves (Palak) , blanched and finely chopped", "1/2 cup Mint Leaves (Pudina) , finely chopped", "1 teaspoon Cumin powder (Jeera) , roasted", "1 inch Cinnamon Stick (Dalchini)", "Salt , to taste", "1/2 teaspoon Oil"]'::jsonb, ARRAY['main ingredients', 's rice', 'salt', 's ghee', 'ingredients for orange layer', 'green beans', 'french beans', 'carrot', 'gajjar', 's garlic', 's ginger', 'onions', 'tomatoes', 's green chillies', 's cloves', 'laung', 'cinnamon stick', 'dalchini', 'cardamom', 'elaichi', 'bay leaves', 'tej patta', 'turmeric powder', 'haldi', 'red chilli powder', 'curd', 'dahi / yogurt', 'mint leaves', 'pudina', 's oil', 'ingredients for white layer', 'potato', 'aloo', 'oil', 'ingredients for green layer', 'spinach leaves', 'palak', 'cumin powder', 'jeera']::text[], '["Cook the rice with 4 cups of water, salt and 3 tablespoons of ghee.", "Set aside to cool.", "Once cooled fluff up with fork to release it from getting sticky and divide the rice into three equal portions."]'::jsonb, 90, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Tri_Color_Biryani_Recipe_For_Indian_Independance_Day_Carrot_Palak_and_Coconut_Rice-14_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/486.Tri_Color_Biryani_Recipe_For_Indian_Independance_Day_Carrot_Palak_and_Coconut_Rice-14_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chicken Wings With Bhuna Masala Recipe', 'chicken-wings-with-bhuna-masala-recipe', 'Chicken Wings With Bhuna Masala Recipe is a Indian take on the crispy chicken wings. We have spiced it up with some Bhuna masala which is usually a base to all the curries. The masala contains almost all the spice flavor that you have from India. It has perfectly roasted onions and tomatoes mixed along with some flavor packed garam masala powder. The chicken wings are then baked in the hot oven till they crisp up over the top and soft and succulent on the inside.', '["8 Chicken Wings", "1 Onion , chopped", "1 Tomato , chopped", "1 inch Ginger , chopped", "3 cloves Garlic , chopped", "1 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1 tablespoon Garam masala powder", "1 tablespoon Cumin powder (Jeera)", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'ginger', 'chicken wings', 'cloves garlic', 'red chilli powder', 'onion', 'turmeric powder', 'garam masala powder']::text[], '["To begin making the Chicken Wings With Bhuna Masala Recipe, we will first boil the chicken wings in a sauce pot with some water.Boil the wings for about 20 minutes till it''s half done.", "This parboiling method will help the wings to absorb less oil once you fry them.", "Drain the water and keep the wings in a bowl.Pre heat the oven to 180 degree Celsius and keep it ready until you move on to make the Bhuna masala.Heat a saucepan with oil, add onions, garlic and ginger and saute until for 3-5 minutes.", "Add tomatoes and sprinkle some salt and cook until the tomatoes are mashed well.", "Now add in the dry masala powders-\u00a0 red chilli powder, turmeric powder,\u00a0garam masala powder,\u00a0cumin powder and salt.", "Mix well and turn off the flame.", "Allow it to cool.", "Transfer into a mixer-jar and blitz it into a smooth paste.", "Place the bhuna masala in a mixing bowl add the chicken wings to this and coat it well.", "Place the wings on a baking tray.", "Drizzle some oil and bake it in the grill mode for 15 minutes and then flip it over and bake it again for another 15 minutes.Serve the\u00a0Chicken Wings With Bhuna Masala Recipe\u00a0along with some\u00a0Greek Yogurt Dip\u00a0or\u00a0Pudina Dahi Chutney\u00a0as a delicious appetizer."]'::jsonb, 40, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Chicken_Wings_With_Bhuna_Masala_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/487.Chicken_Wings_With_Bhuna_Masala_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kadai Beans And Carrot Pulao Recipe', 'kadai-beans-and-carrot-pulao-recipe', 'The Kadai Beans and Carrot Pulao Recipe is a simple pulao that you can make in just about 30 minutes. All you need is some cooked rice and vegetables. Stir fry the vegetables along with the cooked rice in a Kadai and your Kadai Vegetable Pulao will be ready for a weeknight dinner.', '["1 cup Basmati rice , Brown", "2 Cloves (Laung)", "1 Bay leaf (tej patta)", "2 Cardamom (Elaichi) Pods/Seeds", "Ingredients for Kadai Vegetable", "10 Green beans (French Beans) , cut into 1 inch pieces", "2 Carrots (Gajjar) , cut lengthwise into 1 inch pieces", "1 teaspoon Cumin seeds (Jeera)", "2 Green Chillies , slit", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "2 tablespoons Ghee", "1 Mint Leaves (Pudina) , finely chopped", "Salt , to taste"]'::jsonb, ARRAY['basmati rice', 'laung', 'bay leaf', 'tej patta', 'cardamom', 'elaichi', 'ingredients for kadai vegetable', 'reen beans', 'french beans', 'carrots', 'gajjar', 'cumin seeds', 'jeera', 'reen chillies', 'turmeric powder', 'haldi', 'garam masala powder', 's ghee', 'mint leaves', 'pudina', 'salt']::text[], '["To begin making the Kadai Beans and Carrot Pulao Recipe\u00a0Pulav, we will first wash and soak the brown basmati rice\u00a0in 1-1/2 cups of water for half an hour.", "After half an hour, into a large saucepan; add the rice along with the water it was soaking in, oil, cloves, cardamom, bay leaves and salt.", "We will now cook the rice with the spices until soft.", "Turn the heat to high and bring the rice to a brisk boil.Once the rice comes to a boil, turn the heat to low, cover the pan and cook the rice until all the water is absorbed.", "Once all the water is absorbed, turn off the heat and allow the rice to rest for about 10 minutes before you can fork it to separate the grains.Our next step is to make the kadai vegetable masala for the rice.Heat a Kadai or a heavy bottomed pan, add the ghee, cumin seeds, green chillies, green beans, carrots and sprinkle some salt.", "Stir fry the vegetables on medium heat until cooked through.Cover the pan to cook the vegetables, and stir occasionally.", "Once the vegetables are cooked through, add the turmeric powder, garam masala powder, the mint leaves and stir well.Finally, add the cooked rice and toss the rice gently toss over the Kadai Vegetables.", "Cover the pan and simmer the rice with the vegetables for a few minutes and turn off the heat, so the rice gets all the flavors from the Kadai Vegetable Masala.Once done, transfer the Kadai Beans and Carrot Pulao\u00a0to a serving bowl and serve it hot.Serve\u00a0Kadai Beans and Carrot Pulao Recipe\u00a0along with\u00a0Rajasthani Kadhi\u00a0and\u00a0Kachumber Salad\u00a0for a weekday meal."]'::jsonb, 65, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Kadai_Beans_and_Carrot_Pulao_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/488.Kadai_Beans_and_Carrot_Pulao_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tripura Style Kosoi Bwtwi Recipe - Sauteed Tofu & Green Beans Stir Fry With Garlic', 'tripura-style-kosoi-bwtwi-recipe-sauteed-tofu-green-beans-stir-fry-with-garlic', 'Tripura Style Kosoi Bwtwi Recipe is a recipe from North East. Tripura Style Kosoi Bwtwi Recipe is a vegetarian delicacy with simple spices but protein rich tofu in it. The people from Tripura also use Shrimp sauce instead, that manages the protein content in the meal.', '["2 cups Green beans (French Beans) , chopped to 1-inch & parboiled", "1/4 cup Onion , chopped", "1 cloves Garlic , chopped", "2 Green Chillies , slit vertically", "100 grams Tofu , cubed", "2 teaspoons Oil", "Salt , to taste", "Black pepper powder , to taste"]'::jsonb, ARRAY['salt', 'cloves garlic', 'green chillies verticy', 'onion', 'black pepper powder', 'tofu', 'green beans (french beans)', 'sunflower oil']::text[], '["To begin making the Tripura Style Kosoi Bwtwi Recipe, parboil the green beans in a steamer.Meanwhile cut the tofu and stir fry them on a shallow frying pan with a few drops of cooking oil for about a minute on each side.Once you take out the tofu, in the same shallow frying pan, heat the oil (I have used olive oil to make the recipe more healthy and interesting) and saute onions, garlic cloves, chopped green chillies and saute till the raw smell goes away.Once the raw smell goes away and the veggies are tender, add green beans along with sauteed tofu and stir fry for a few minutes.Add salt and pepper as per taste, mix everything well and serve\u00a0hot.Serve\u00a0Tripura Style Kosoi Bwtwi Recipe\u00a0as a side dish along with a meal of\u00a0Steamed Rice,\u00a0Assamese Bilahi Boror Tenga Recipe (Sour Curry With Red Lentil Fritters)\u00a0and\u00a0Garlic Dal."]'::jsonb, 30, 'North East India', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/28-march/Tripura_Style_Kosoi_Bwtwi_Recipe_Green_Beans_and_Tofu_stir_fry-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/489.Tripura_Style_Kosoi_Bwtwi_Recipe_Green_Beans_and_Tofu_stir_fry-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmir Style Bom Chount/Wangan Recipe-Spicy Apple Brinjal Curry', 'kashmir-style-bom-chount-wangan-recipe-spicy-apple-brinjal-curry', 'Bom chount–Wangan recipe has a great importance in Kashmiri cuisine. It is prepared on festivals, ceremonies and other occasions. It is believed to be a rare combination and hence offered as a bhog to ancestors.', '["1 Brinjal (Baingan / Eggplant)", "1 Apple", "2 teaspoon Red Chilli powder", "2 teaspoon Fennel Powder", "1 teaspoon Salt", "1 teaspoon Garam masala powder", "1 teaspoon Cumin seeds (Jeera)", "Oil , as required"]'::jsonb, ARRAY['salt', 'brinjal (baingan eggsplant)', 'red chilli powder', 'apple', 'fennel powder', 'cumin seeds (jeera)', 'garam masala powder', 'sunflower oil']::text[], '["To prepare Kashmir Style Bom Chount-Wangan Recipe, cut the apple and brinjal to wedges .Fry the apple and brinjal in a pan and keep it aside aside.", "You can fry them separately as well till it is golden brown.", "In the same\u00a0pan, add cumin with the left over hot oil.Then add red chilli powder, fennel seed powder and stir with 1/4 th cup water till the water evaporates.Add the fried apples and brinjal into the pan and mix well.Add garam masala and salt \u00a0and keep it in on low flame for 5 minutes and take off heat.Serve Kashmir Style Bom Chount - Wangan Recipe with Spiced carrot pulao recipe\u00a0or plain rice and\u00a0Nadru ke kabab."]'::jsonb, 40, 'Kashmiri', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/2-feb/Bom_Chount_-_Wangan_Recipe_Kashmiri_Apple_Brinjal_Curry-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/490.Bom_Chount_-_Wangan_Recipe_Kashmiri_Apple_Brinjal_Curry-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Vegetable Stew Recipe with Coconut Milk', 'kerala-style-vegetable-stew-recipe-with-coconut-milk', 'The Kerala Style Vegetable Stew is a quick and simple recipe that is a staple dish from Kerala. The stew is very quick to make and loaded with lots of vegetables making it healthy and nutritious. The Vegetable Stew recipe is made with a combination of vegetables like boiled potatoes, carrots, beans, cauliflower peas etc. The combination of vegetables is purely your choice. This recipe is a mild stew that is delicately spiced with green chillies, flavored with curry leaves and coconut milk. The stew is also a dish that is served during the Onam Sadya meal of the Onam Festival and along with the famous Kerala Appams.', '["2 Potatoes (Aloo) , peeled and cubed", "1 Carrot (Gajjar) , diced", "10 Green beans (French Beans) , cut length wise", "2 to 3 Green Chillies , slit lengthwise", "250 ml Coconut milk", "Salt , to taste", "3 Cloves (Laung)", "1 teaspoon Whole Black Peppercorns , coarsely pounded", "1 teaspoon Sugar", "1 sprig Curry leaves", "2 teaspoon Coconut Oil"]'::jsonb, ARRAY['potatoes', 'aloo', 'carrot', 'gajjar', 'reen beans', 'french beans', 'to 3 green chillies', 'coconut milk', 'salt', 'laung', 'whole black peppercorns', 'sugar', 'curry leaves', 'coconut oil']::text[], '["To begin making the Kerala Style Vegetable Stew, we need to cut the vegetables in desired shapes, steam them and keep them ready.Steam the potatoes, beans and carrots or any other vegetable of your choice and keep them aside.", "See How To Cook Vegetables in a pressure cookerIn a heavy bottomed\u00a0sauce pan; add in the cooked vegetables, the\u00a0coconut\u00a0milk, curry leaves, cloves, black pepper and green chillies.", "Stir well and bring the mixture to a brisk boil.", "Add in the salt and sugar and adjust to suit your taste.Adjust gravy to get the right consistency by adding a little water if you want to make it little thinner.", "Make sure the gravy is not too watery.", "Finally\u00a0add in the coconut oil and simmer for a few more minutes.Turn off the heat, cover the pan and allow the Vegetable Stew to rest for about 10 minutes.", "This brings out the flavors from the curry leaves, green chillies and coconut milk.", "Transfer the Vegetable Stew to a serving bowl.", "Serve the delicious flavorful Kerala Style Vegetable Stew along with\u00a0Kerala Appams."]'::jsonb, 60, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Kerala_Style_Mixed_Vegetable_Stew_Recipe-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/491.Kerala_Style_Mixed_Vegetable_Stew_Recipe-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rajasthani Dal Muthiya Recipe', 'rajasthani-dal-muthiya-recipe', 'Rajasthani Dal Muthiya is a perfect and delicious combination of simple yellow mogar dal and fried whole wheat flour dumplings. This recipe is very similar to the Rajasthani dal baat but it has a different taste and flavour which makes it different from others.', '["1 cup Yellow Moong Dal (Split)", "1/2 teaspoon Turmeric powder (Haldi)", "1 Green Chillies , finely chopped", "Salt , as required", "Water , as required", "Ghee , as required", "1/2 teaspoon Asafoetida (hing)", "1 teaspoon Red Chilli powder", "2 Dry Red Chillies", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "Coriander (Dhania) Leaves , Few sprigs, finely chopped", "2 cups Whole Wheat Flour", "3 tablespoons Oil , hot", "Salt , as required", "Water , as required", "1 teaspoon Ajwain (Carom seeds)"]'::jsonb, ARRAY['yellow moong dal', 'split', 'turmeric powder', 'haldi', 'reen chillies', 'salt', 'water', 'ghee', 'asafoetida', 'hing', 'red chilli powder', 'dry red chillies', 'mustard seeds', 'rai/ kadugu', 'coriander', 'dhania', 's whole wheat flour', 's oil', 'ajwain', 'carom seeds']::text[], '["To begin making the Rajasthani Dal Muthiya recipe, firstly we will begin with the dal.", "Add mogar dal, green chillies, salt and turmeric powder in a pressure cooker with required amount of water.Cook it till the cooker releases 3 whistles.", "Open the lid and mix it properly using a spoon. (if you want the dal watery, you can add hot water according to your preference)The next step is to temper the dal.", "Heat ghee in a tadka pan and add mustard seeds, red chili powder, asafoetida, dry red chillies and salt. (You have already added salt while boiling the dal, so make sure that you add extra according to your taste).Pout the tadka on the dal and garnish it with chopped coriander leaves.To make muthiya, add flour, ajwain, salt in a large mixing bowl.", "Mix it well.Slowly add the oil and water to make a dough out of it.", "Once it is done, cover it with a cloth and keep aside for 15 minutes.After 15 minutes, make medium sized balls out of the dough and keep it aside.Meanwhile, heat oil in a frying pan.", "Once the oil is hot, turn the heat to low.Take the flour ball and press it between your hand using your fingers.", "Once it is done, drop the muthiya into the hot oil and fry it from both sides till it becomes light brown in colour.", "It will take some time to cook, so don\u2019t be in a hurry to take it out.Take it out on a tissue paper to remove the extra oil.Follow the same process for the remaining dough and serve it hot with the dal.Serve Rajasthani Dal Muthiya on its own with fried chillies and\u00a0Masala Chaas\u00a0for a delicious weekend lunch."]'::jsonb, 30, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/daal_mutiye_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/492.daal_mutiye_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dahi Methi Puri Recipe - Fenugreek Leaves Puri With Yogurt', 'dahi-methi-puri-recipe-fenugreek-leaves-puri-with-yogurt', 'Dahi Methi Puri Recipe is a crispy puri recipe. Here the puri dough is made by combining methi leaves with whole wheat flour.', '["1-1/2 cups Whole Wheat Flour", "3/4 cup Methi Leaves (Fenugreek Leaves) , washed and finely chopped", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Ajwain (Carom seeds)", "Salt , to taste", "3/4 cup Curd (Dahi / Yogurt)"]'::jsonb, ARRAY['s whole wheat flour', 'methi leaves', 'fenugreek leaves', 'cumin seeds', 'jeera', 'ajwain', 'carom seeds', 'salt', 'curd', 'dahi / yogurt']::text[], '["To begin making Dahi Methi Puri Recipe, we will first make the dough.", "In a mixing bowl, combine the whole wheat flour along with methi leaves, salt, cumin seeds, ajwain and mix well to combine.Next bring the dough together with the curd to make a smooth and soft dough.", "If required, use a little water, if the curd is not enough to make a soft dough.", "Sprinkle a few drops of oil and smoothen out the dough.", "Make equal portions of the dough, similar to the size of a lemon.", "Dust each portion of the dough in flour and flatten using a rolling pin to a 3 inch diameter of medium thickness.", "Preheat oil in a kadai on medium heat, gently slide the flattened\u00a0Dahi Methi Puri into the kadai, and gently fry the puri with a slotted spatula, continuously yet gently pouring oil onto the puri, allowing it to puff up.", "Flip and cook on the other side for about 30-40 seconds.", "Remove from the kadai and place on an absorbent paper, to drain off the excess oil.", "Serve\u00a0Dahi Methi Puris hot.", "Serve\u00a0Dahi Methi Puri along with\u00a0Sukhi Aloo Sabzi Recipe\u00a0or\u00a0Peshawari Chole Recipe\u00a0alongside some\u00a0Rava Kesari Bhath\u00a0and a glass of\u00a0Kesar Pista Lassi Recipe\u00a0for a Sunday brunch."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Donna_George/Dahi_Methi_Poori_Recipe-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/493.Dahi_Methi_Poori_Recipe-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer Jalfrezi Recipe', 'paneer-jalfrezi-recipe', 'Paneer Jalfrezi is a simple and quick to cook vegetable where the vegetables are stir-fried and tossed along with tomatoes and spices. The addition of homemade tomato puree, when combined with the homemade garam masala powder, and the fresh coriander leaves, brings out the fresh flavors of the Paneer Jalfrezi. Serve the Paneer Jalfrezi along with Raita for a weeknight dinner.', '["250 grams Paneer (Homemade Cottage Cheese)", "1 Onion , diced", "1 Red Bell pepper (Capsicum) , diced", "1 Green Bell Pepper (Capsicum) , diced", "2 Carrots (Gajjar) , diced thin", "1 inch Ginger , grated", "2 cloves Garlic , grated", "1 Tomato , diced", "1 cup Homemade tomato puree", "1 teaspoon Honey", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "1 Stalk Coriander (Dhania) Leaves , finely chopped", "1 tablespoon Butter (Salted) , softened"]'::jsonb, ARRAY['tomato', 'red bell pepper (capsicum)', 'ginger', 'stalk coriander (dhania) leaves', 'paneer', 'cloves garlic', 'carrot', 'onion', 'green bell pepper (capsicum)', 'coriander powder', 'turmeric powder', 'butter', 'garam masala powder']::text[], '["To begin making the Paneer Jalfrezi Recipe, first make your\u00a0\u00a0Paneer, Tomato Puree\u00a0and the remaining vegetables cut and ready.Heat oil in a cooking vessel.", "Once hot, add cumin seeds and allow them to splutter.", "Add sliced onions and saute for 5 minutes.Heat oil in a heavy bottomed cooking pan or a Kadai, heat a teaspoon of oil.", "Add the onions, ginger, garlic, bell peppers and carrots and stir fry on medium heat until they are lightly softened.Next add the tomatoes, the tomato puree, turmeric powder, garam masala powder, coriander powder, salt, red chili powder.", "Stir-fry the paneer jalfrezi for 4 to 5 minutes, until you notice a thick gravy has formed and all the spices have been absorbed well into the vegetables.", "Finally add the honey, the paneer and stir it in the masala.", "Check the salt and spice levels of the Paneer Jalfrezi and adjust to suit your taste.", "Give the Jalfrezi a simmer for 3 to 4 minutes and turn off the heat.Transfer to a serving bowl and serve the Paneer Jalfrezi along with\u00a0Raita\u00a0for a weeknight dinner."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Paneer_Jalfrezi_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/494.Paneer_Jalfrezi_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Peshwari Naan Recipe - Naan Stuffed With Sweet Dry Fruits', 'peshwari-naan-recipe-naan-stuffed-with-sweet-dry-fruits', 'Naan is an Indian flat bread that can be made very easily at home and that too on stove top. The result – soft, pillowy, delicious naans! Peshawari naan is a close cousin of Kashmiri naan.', '["2-1/4 cups All Purpose Flour (Maida) , extra for dusting", "1-1/2 teaspoons Active dry yeast", "1 teaspoon Sugar", "100 grams Curd (Dahi / Yogurt)", "150 ml Lukewarm Water", "2 teaspoon Salt", "2 tablespoon Oil", "Ghee , or butter as needed", "1/4 cup Whole Almonds (Badam)", "100 grams Sultana Raisins", "1/2 cup Fresh coconut , optional", "Kalonji (Onion Nigella Seeds) , for sprinkling"]'::jsonb, ARRAY['s all purpose flour', 'maida', 's active dry yeast', 'sugar', 's curd', 'dahi / yogurt', 'lukewarm water', 'salt', 'oil', 'ghee', 'whole almonds', 'badam', 's sultana raisins', 'fresh coconut', 'kalonji', 'onion nigella seeds']::text[], '["To begin the preparation of Peshawari Naan, take yeast and sugar in a bowl and pour luke warm water and let it sit for 5 minutes until the yeast starts bubbling.", "If the yeast doesn\u2019t react discard it and start another batch.In another bowl, add flour, salt, oil and mix with your fingers, make a well in the center and pour in the frothy yeast mixture and yogurt.", "Mix well.", "We just want all the dry flour to be wet.", "The dough will be sticky.Thoroughly clean the counter surface, rub your fingers with little flour, transfer the dough onto the counter and start kneading.", "Initially it will be sticky.", "Knead until smooth, soft and shiny.The kneading should be \u201cstretch, fold back\u201d movements.", "Do not add too much flour while kneading.", "We need flour just to rub your fingers with in case dough is very difficult to handle.", "If you add more flour, the naan might not turn soft.Place the dough into a bowl rub oil all over the dough, and cover it with a damp cloth.", "Set it aside for 1 \u2013 1.5 hours, for the dough to prove.", "After 1-1.5 hours the dough would have risen and it would be double the size.In a mixer grinder, coarsely blend the almonds and the raisins and keep aside.", "Optionally add the coconut as well.", "Once the dough is proven, knock it down (punch it with your fist), this is done to release all the air that would have collected.", "Gently knead for another 2 minutes.Divide the dough into equal parts (I made 3 large balls).", "Dust a little flour if needed to roll and press the dough.Sprinkle the dry fruits in the center.", "Now bring the edges of the peshwari naan to the center sealing the stuffing in the center.", "Now roll the peshwari naan into any desired shape making sure not to break the stuffing out of the naan.Sprinkle some kalonji over the\u00a0peshwari naan and may be few almond flakes on top as well.Heat a tawa.", "Grease it well with ghee.", "Place the rolled peshwari naan and cook covered on low flame.", "You will see the naan bubbling up.Turn the peshwari naan the other side and rub ghee generously and cook.Keep turning peshwari naan once in 30 seconds to 1 minute on both sides until all edges are cooked and naan is browned on both sides.Remove the\u00a0peshwari naan from tawa and again rub ghee generously on top.", "Repeat the process for the remaining dough.Serve the Peshwari naan hot with butter chicken\u00a0and\u00a0dal\u00a0or\u00a0or\u00a0Peshawari Chole Recipe\u00a0for a complete meal."]'::jsonb, 120, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Peshwari_Naan.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/495.Peshwari_Naan.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karamani Poriyal Recipe - Yard Long Beans Stir Fry | Chawli | Barbati Sabzi', 'karamani-poriyal-recipe-yard-long-beans-stir-fry-chawli-barbati-sabzi', 'Karamani Poriyal is a very traditional South Indian style stir fry, that is very healthy, nutritious and quick to make. Karamani also known as Yard Long Beans, is a very nutritious vegetable having the lowest amount of calories and highest amount of soluble and insoluble fibers making it a perfect food for weight watchers. Addition of red chilli during making the tadka is completely optional.', '["300 grams Green Chawli Beans (Yard long beans/Karamani/Barbati) , chopped", "1 teaspoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1/2 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Asafoetida (hing)", "1 sprig Curry leaves", "2 tablespoons Fresh coconut , grated", "2 Dry Red Chillies", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard seeds', 'asafoetida (hing)', 'coconut', 'curry leaves', 'white urad dal (split)', 'green chawli beans (yard beanskaramanibarbati)', 'dry red chillies', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Karamani Poriyal (South Indian Style Yard Long Beans Stir Fry) recipe, first chop the yard long beans finely.Grind the grated coconut along with the red chillies in a mixer to a dry mix and keep it aside.Place the beans in a pressure cooker, add salt and 2 tablespoons water and pressure cook for two whistles.", "After two whistles, turn off the heat and release the pressure immediately.", "Heat oil in a pan/ kadai over medium heat.", "Add the mustard seeds and urad dal and allow them to crackle and the dal to turn golden brown and crisp.Add the curry leaves, asafoetida and fry for few seconds.", "Now add the yard long beans and the ground coconut.", "Stir-fry the Karamani Poriyal for a few seconds on high heat and then turn off the heat.", "Check the salt and adjust to taste accordingly.Serve the Karamani Poriyal with Steamed Rice and\u00a0Sambar/Rasam\u00a0for the weeknight meal."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Karamani_Poriyal_South_Indian_Style_Yard_Long_Beans_Stir_Fry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/496.Karamani_Poriyal_South_Indian_Style_Yard_Long_Beans_Stir_Fry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Milagai Bajji Stuffed with Masala Chicken Recipe', 'milagai-bajji-stuffed-with-masala-chicken-recipe', 'Milagai Bajji Stuffed with Masala Chicken Recipe is an innovative recipe created with South Indian spices.', '["6 Badi hari mirch (Large Green Chilli)", "Oil", "300 grams Chicken breasts , minced", "1 Onion , chopped", "1/2 cup Homemade tomato puree", "1 inch Ginger , chopped", "4 cloves Garlic , chopped", "Salt , to taste", "1 teaspoon Ajwain (Carom seeds)", "1 teaspoon Fennel seeds (Saunf)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Coriander (Dhania) Seeds", "1/2 teaspoon Whole Black Peppercorns", "4 Dry Red Chillies", "3 tablespoon Fresh coconut"]'::jsonb, ARRAY['tomato', 'salt', 'chicken breasts', 'ginger', 'coconut', 'fennel seeds (saunf)', 'ajwain (carom seeds)', 'cloves garlic', 'black peppercorns', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'dry red chillies', 'badi hari mirch (large green chilli)', 'sunflower oil']::text[], '["To begin making the Milagai Bajji Stuffed with Masala Chicken Recipe, we will first dry roast the spices."]'::jsonb, 70, 'Tamil Nadu', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Milagai_Bajji_Stuffed_with_Masala_Chicken_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/497.Milagai_Bajji_Stuffed_with_Masala_Chicken_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mixed Vegetable Handi Recipe', 'mixed-vegetable-handi-recipe', 'If you feel like eating something exotic, something like restaurant style then this recipe is perfect for you. Easy to make and it tastes exactly like the mixed vegetable sabzi we eat in restaurants. Vegetable Handi is easy to cook and good for health too as it has a lots of vegetable in it. The goodness of vegetables and the flavour from the spices makes it a delectable dish to eat. You can also make it for your weekend house parties or can pack it for your pot luck .', '["2 tablespoons Oil", "1 tablespoon Cumin seeds (Jeera)", "2 Bay leaves (tej patta)", "1 Onion , 1/2 diced and 1/2 thinly sliced", "1 teaspoon Ginger , finely chopped", "1 teaspoon Garlic , finely chopped", "1 teaspoon Green Chilli , finely chopped", "4 Tomatoes", "7 Cashew nuts", "1 tablespoon Kashmiri Red Chilli Powder", "1 tablespoon Turmeric powder (Haldi)", "1/2 tablespoon Garam masala powder", "1/2 tablespoon Coriander Powder (Dhania)", "1 tablespoon Butter (Salted)", "Salt , to taste", "1/2 cup Carrots (Gajjar) , diced", "1/4 cup Sweet corn", "1/4 cup Green peas (Matar)", "1/4 cup Green beans (French Beans) , chopped", "1/2 cup Green Bell Pepper (Capsicum) , chopped", "1/2 cup Cauliflower (gobi) , chopped", "1/2 cup Button mushrooms , chopped", "1/2 cup Paneer (Homemade Cottage Cheese) , cubed", "1 cup Water", "1 tablespoon Curd (Dahi / Yogurt)", "1 tablespoon Fresh cream", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "1 tablespoon Coriander (Dhania) Leaves , chopped", "1 tablespoon Mint Leaves (Pudina) , chopped", "1/2 Lemon , juice"]'::jsonb, ARRAY['tomato', 'kashmiri red chilli powder', 'coriander (dhania) leaves', 'carrot', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'sunflower oil', 'salt', 'green chilli', 'mint leaves (pudina)', 'garam masala powder', 'green beans (french beans)', 'cauliflower (gobi)', 'water', 'curd', 'garlic', 'lemon', 'button mushrooms', 'kasuri methi (dried fenugreek leaves)', 'butter', 'cashew nuts', 'ginger', 'bay leaves (tej patta)', 'paneer', 'green peas (matar)', 'sweet corn', 'green bell pepper (capsicum)', 'coriander powder']::text[], '["To begin making the Mixed Vegetable Handi recipe, add tomatoes and cashews in a mixer grinder, puree them and keep it aside.Next, heat oil in a heavy bottomed pan.", "Add bay leaves, cumin seeds and cook for 15 seconds.After 15 seconds, add sliced onions, green chilli, ginger, garlic and saute for about a minute.After a minute, add finely sliced onions and cook till the onion turns golden brown in colour.Next, add tomato puree and cook for about 3 to 5 minutes.", "After 5 minutes, add turmeric powder, red chilli powder, coriander powder and garam masala powder.Add butter and mix everything well, let it cook for about a minute.", "After a minute, add the diced onion, diced carrot, corn, peas, french beans, capsicum, cauliflower, button mushrooms and paneer.", "Give it a toss and add water.Add salt and cover the lid.", "Let it cook for 10 to 12 minutes on medium flame, keep checking and stirring in between if the vegetables are cooked properly or not.Meanwhile, take a small bowl, add cream and curd together.", "Mix it well and see that no lumps are formed.", "Once the vegetables are soft, add the cream curd mixture and mix it with the vegetables.", "Cook\u00a0Mixed Vegetable Handi on low flame for 1-2 minutes, sprinkle kauri methi, add lemon juice and mix everything nicely.Once it is done, garnish Mixed Vegetable Handi with chopped coriander and mint leaves.", "Mixed Vegetable Handi is ready to serve.Serve Mixed Vegetable Handi along with\u00a0Tawa Parathas\u00a0and\u00a0Boondi Raita\u00a0for a weekday meal."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pooja/Veg_Handi_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/498.Veg_Handi_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pumpkin Curry With Chicken Recipe', 'pumpkin-curry-with-chicken-recipe', 'Pumpkin Curry With Chicken Recipe has a unique taste that is quick to make and has rich flavours. Pumpkin is cooked and made into a puree and then tomato puree, chicken and spices are added to make a delicious and flavourful curry.', '["400 grams Chicken breasts , cut into small pieces", "500 grams Kaddu (Parangikai/ Pumpkin)", "1 inch Ginger , roughly chopped", "1 Onion , roughly chopped", "3 cloves Garlic , chopped", "2 Green Chilli , finely chopped", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Red Chilli powder", "3/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "1/2 cup Homemade tomato puree", "Salt , as required", "Coriander (Dhania) Leaves , A small bunch, finely chopped", "Oil"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'ginger', 'coriander (dhania)', 'parangikai pumpkin', 'green chilli', 'red chilli powder', 'cloves garlic', 'onion', 'coriander powder', 'chicken breasts', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Pumpkin Curry With Chicken, heat oil in a heavy bottomed pan.Add the garlic, onion, ginger, green chillies and chopped pumpkin.", "Sprinkle some salt and stir them for about a minute, cover the pan and simmer until the pumpkin has softened.", "This will take about 6-8 minutes on medium heat.", "Using a hand blender, blend the pumpkin into a puree while it is in the pan.", "Add the tomato puree, and\u00a0 the spices like the cumin powder,\u00a0red chilli powder,\u00a0turmeric powder,\u00a0coriander powder and\u00a0garam masala.", "Give it a good mix and saute for about 2 minutes.", "After 2 minutes add the chicken pieces.along with\u00a0a cup of water, cover the pan, turn the heat to low and cook until the chicken is cooked completely .Adjust the consistency of the curry by adding more water and also adjust the spices to suit your taste.Once done, turn off the heat.", "Stir in the chopped coriander leaves, Transfer the\u00a0Pumpkin Curry With Chicken into a serving bowl and serve.Serve Pumpkin Curry With Chicken along with\u00a0Pudina Tawa Paratha\u00a0and\u00a0Kachumber Salad."]'::jsonb, 70, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Saffola_FitFoodie/6-Pumpkin_Curry_With_Chicken_recipe_Saffola_Oats_Fit_Foodie-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/499.6-Pumpkin_Curry_With_Chicken_recipe_Saffola_Oats_Fit_Foodie-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Mushroom Xacuti Recipe', 'goan-mushroom-xacuti-recipe', 'Goan Mushroom Xacuti is an authentic Goan traditional dish which tastes the best when cooked using wild or forest mushrooms, which are available during the rainy season. On the other hand Xacuti is a Goan Masala with certain blend of spices which is extremely popular across India and is used to prepare gravy based recipes.', '["1 tablespoon Oil", "400 grams Button mushrooms , sliced", "1/2 teaspoon Turmeric powder (Haldi) , finely chopped", "Salt , to taste", "2 Onions , finely chopped", "2 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "6 sprig Coriander (Dhania) Leaves , finely chopped", "4 Dry Red Chillies", "1 tablespoon Poppy seeds", "3 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 tablespoon Whole Black Pepper Corns", "1 teaspoon Cumin seeds (Jeera)", "1 tablespoon Coriander (Dhania) Seeds", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "30 grams Tamarind"]'::jsonb, ARRAY['tomato', 'tamarind marble bal', 'salt', 'coconut', 'black peppercorns', 'coriander (dhania) leaves', 'dry red chillies', 'onion', 'coriander (dhania) seeds', 'button mushrooms', 'turmeric powder', 'cloves (laung)', 'garam masala powder', 'sunflower oil']::text[], '["To begin with Goan Mushroom Xacuti, prep all the ingredients and keep ready.Into a pan; add red chilies, poppy seeds, cloves, cinnamon sticks, peppercorns, cumin seeds, coriander seeds, fennel seeds, fenugreek seeds and roast them for about 3- 5 minutes on low flame until you can notice the spices popping and the aromas coming through.Turn off the heat and set aside to cool.Heat oil in a pan over medium heat.", "Add chopped onions, garlic and ginger and saut\u00e9 till onions turn translucent and lightly golden.Add grated coconut to the above onion and saut\u00e9 till coconut turns golden brown.", "Remove the mixture from the heat and set aside to cool.Add the roasted spices, tamarind and onion-coconut mixture into the small jar of the Mixer Grinder and blend to make a smooth paste by adding little water.", "The next step is to make the Xacuti masala.", "Heat oil in a flat bottomed pan.", "Add the ground masala paste and saute for a few minutes.", "Add mushroom pieces, turmeric powder, salt to taste and give it a stir for a few seconds.", "Add just a little water to give the\u00a0Goan Mushroom Xacuti a gravy like consistency and cover the pan.Simmer the\u00a0Goan Mushroom Xacuti Masala for 3 to 4 minutes and turn off the heat.", "Mushrooms get cooked very quickly and also release a lot of water.Once done, turn off the heat and stir in the coriander leaves - it brings in a freshness to the Goan Mushroom Xacuti.", "Serve the\u00a0Goan Mushroom Xacuti along with buttered pav puns or even a matar pulao for lunch or dinner."]'::jsonb, 30, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Mushroom_Xacuti_recipe_Mushroom_Shaguti_Goan_recipe_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/500.Mushroom_Xacuti_recipe_Mushroom_Shaguti_Goan_recipe_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mango Pulusu Recipe - Mamidi Pandu Pulusu Recipe', 'mango-pulusu-recipe-mamidi-pandu-pulusu-recipe', 'Mamidi Pandu Pulusu is a spicy and tangy andhra style ripe mango curry that is packed with flavors from methi and hing cooked in a tamarind gravy. This Pulusu can be also made with raw mango ( Totapuri ) as well.', '["3 Mango (Ripe)", "3 Green Chillies , slit", "1 teaspoon Red Chilli powder", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "Asafoetida (hing) , A pinch", "10 Curry leaves", "1 tablespoon Oil", "Salt , to taste", "1 teaspoon Tamarind Paste", "2 sprig Coriander (Dhania) Leaves , to garnish"]'::jsonb, ARRAY['salt', 'mustard seeds', 'mango (ripe)', 'asafoetida (hing)', 'red chilli powder', 'curry leaves', 'coriander (dhania) leaves', 'methi seeds (fenugreek seeds)', 'tamarind paste', 'green chillies', 'sunflower oil']::text[], '["To begin making the Mamidi Pandu Pulusu, firstly peel the ripe mangoes and keep aside.In a pan, place oil and add mustard seeds and let them crackle.Once it crackles, add asafoetida, curry leaves and green chillies and saute it for a minute.After a minute, add the peeled mangoes and saut\u00e9 till its a little until it becomes a little soft.Add red chilly powder and a cup of water, tamarind paste, salt and cover it until it comes to a boil.Once the water starts evaporating, add another cup of water and boil again.", "At the end of it, you should be left with nice thick Mamidi Pandu Pulusu.After 2-3 minutes, switch off the gas and the\u00a0Mamidi Pandu Pulusu/ Mango\u00a0Pulusu is ready to be served.Serve the\u00a0Mango Pulusu Recipe along with steamed rice,\u00a0Spicy Potato Roast Recipe\u00a0and a\u00a0Rajma and Corn Salad Recipe."]'::jsonb, 45, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuri_Aggarwal/Mamida_Pandu_Pulusu__Mango_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/501.Mamida_Pandu_Pulusu__Mango_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kadai Chole Recipe- Dry Chickpeas Masala with Capsicum', 'kadai-chole-recipe-dry-chickpeas-masala-with-capsicum', 'Kadai Chole Recipe is a delicious Recipe made with dry spice powders and crunchy onions and capsicum. Kadai chole goes well with Puri and Parathas. You can pack these for your kids and your Lunch box as well.', '["1 cup Kabuli Chana (White Chickpeas) , Soaked Overnight", "2 Onions , diced in chunks", "1 Green Bell Pepper (Capsicum) , diced in chunks", "4 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "2 Green Chilli , Slit", "1 Tomato , Pureed", "1 Cinnamon Stick (Dalchini)", "3 Cloves (Laung)", "1 Bay leaf (tej patta)", "1 Black cardamom (Badi Elaichi)", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Cumin powder (Jeera)", "1 teaspoon Kashmiri Red Chilli Powder", "1/2 teaspoon Amchur (Dry Mango Powder)", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Ajwain (Carom seeds)", "2 tablespoons Ghee", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'black cardamom (badi elaichi)', 'cumin powder (jeera)', 'ginger', 'kashmiri red chilli powder', 'green chilli', 'amchur (dry mango powder)', 'bay leaf (tej patta)', 'ghee', 'salt', 'ajwain (carom seeds)', 'cloves garlic', 'kabuli chana (white chickpeas)', 'onion', 'cinnamon stick (dalchini)', 'green bell pepper (capsicum)', 'coriander powder', 'cloves (laung)', 'garam masala powder']::text[], '["To begin making Kadai Chole Recipe, first wash and soak the chickpeas for 6 hours or overnight in water.Cook the chana in the pressure cooker along with salt and 3 cups water for about 30 minutes until soft.", "Heat ghee in a large kadai on medium heat; add the ajwain, onions, ginger, garlic, green chilli, cinnamon, cloves, cardamom, bay leaves and saute until the onions softened.Add the capsicum and stir fry the capsicum on high heat until the capsicum is just about soft.", "It should retain its green colour.Stir in the tomatoes,and all the dry masalas -\u00a0Coriander Powder, Red chili powder, cumin powder, garam masala powder, amchur powder and salt.Give it a stir and finally add the cooked chana masala into the kadai.", "Add a little more ghee at this stage and cook the Kadai Chole along with the masalas until it gets well coated with the spices.Keep heat on low and cover the pan and cook the Kadai Chole for about 5 minutes minutes till all the flavors blend well with each other and turn off the heat.Check the taste and adjust the salt and spices accordingly.", "Once done, transfer the Kadai Chole to a s serving bowl and serve hot.Serve Kadai Chole with\u00a0Mixed Vegetable Handi,\u00a0Pudina Tawa Paratha\u00a0and\u00a0Mooli Raita Recipe\u00a0for a perfect weekend dinner.", "You can also add a\u00a0Gobi Biryani,\u00a0Dal Makhani\u00a0and a\u00a0Moong Dal Halwa\u00a0and make a perfect north indian menu for parties."]'::jsonb, 55, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Kadai_Chole_Recipe_Kadai_Chana_Masala-14_1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/502.Kadai_Chole_Recipe_Kadai_Chana_Masala-14_1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Navrang Dal Recipe ( Spicy Mixed Lentils)', 'navrang-dal-recipe-spicy-mixed-lentils', 'Navrang Dal is a mix of nine different types of lentils cooked together in a medley of aromatic Indian spices. Dal is a staple food in Indian homes and is served every day. It is as creamy as Dal Makhni without the use of cream in it. It is a healthy dish that provides a good amount of protein to your body.', '["2 tablespoons Green Moong Dal (Whole)", "2 tablespoons White Urad Dal (Split)", "2 tablespoons Black Urad Dal (Whole)", "2 tablespoons Pink Masoor Dal (Split)", "2 tablespoons Masoor Dal (Whole)", "2 tablespoons Rajma (Large Kidney Beans)", "2 tablespoons Kabuli Chana (White Chickpeas)", "1/4 cup Yellow Moong Dal (Split) , (soak for 20 minutes)", "1 tablespoon Arhar dal (Split Toor Dal) , (soak for 20 minutes)", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1 tablespoon Ginger Garlic Paste", "1 Green Chilli , slit", "2 teaspoons Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "2 teaspoons Garam masala powder", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "1 inch Ginger , cut to julienned for garnish", "2 tablespoons Ghee", "1 Cinnamon Stick (Dalchini)", "1 teaspoon Cumin seeds (Jeera)", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'kabuli chana (white chickpeas)', 'white urad dal (split)', 'onion', 'cumin seeds (jeera)', 'rajma (large kidney beans)', 'salt', 'arhar dal (split toor dal)', 'green chilli', 'black urad dal', 'garam masala powder', 'red chilli powder', 'pink masoor dal (split)', 'green moong dal', 'kasuri methi (dried fenugreek leaves)', 'yellow moong dal (split)', 'ginger', 'ghee', 'ginger garlic paste', 'cinnamon stick (dalchini)', 'coriander powder', 'masoor dal']::text[], '["To begin making Navrang Dal (spicy Mixed Lentils) Recipe soak all the dals except split moong and toor dal overnight.", "In the morning pressure cook everything together till it''s cooked.", "Mash the cooked dal gently and keep it aside.Heat a big wok on medium flame, pour oil or ghee, a stick of cinnamon and cumin seeds and let it splutter.To this add the onions and saut\u00e9 till it turns light brown.Add the ginger garlic paste and cook until the raw smell of the paste goes away.Now add the chopped tomatoes and slit green chilli and cook until the tomatoes are half done.Add the coriander, red chilli, and garam masala powder and give it a mix and cook until the ghee or oil separates out.Now add the cooked mashed dal to this, season with salt, add the required amount of water and let it simmer for ten minutes.Now gently crush the kasuri methi between your palms and put it over the dal.Bring it to a boil, switch off the flame and garnish with the ginger julienned.Your Navang Dal is ready to be served, serve it with Laccha Paratha or Peas Pulao for a weeknight dinner."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Navrang_Dal_spicy_Mixed_Lentils_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/503.Navrang_Dal_spicy_Mixed_Lentils_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chicken Keema Paratha Recipe - Minced Chicken Flat Bread', 'chicken-keema-paratha-recipe-minced-chicken-flat-bread', 'Chicken Keema Paratha Recipe is a delicious high protein paratha where the chicken keema is delicately spices with garam masala and then stuffed into atta to make a crispy flaky paratha. The addition of cooking the paratha with ghee gives a delicious crispy and flaky crust as well.', '["1 teaspoon Oil", "4 cloves Garlic , finely chopped", "1 Onion , finely chopped", "1 Tomato , finely chopped", "2 Green Chillies , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "1/2 teaspoon Amchur (Dry Mango Powder)", "Salt , to taste", "1 Chicken breasts , roughly chopped", "1/4 cup Mint Leaves (Pudina) , chopped", "2 cups Whole Wheat Flour", "1 teaspoon Salt", "1 tablespoon Oil", "Ghee , for cooking"]'::jsonb, ARRAY['tomato', 'salt', 'wheat flour', 'amchur (dry mango powder)', 'mint leaves (pudina)', 'ghee', 'red chilli powder', 'cloves garlic', 'onion', 'coriander powder', 'chicken breasts', 'turmeric powder', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the\u00a0Chicken Keema Paratha Recipe, first prep all the ingredients and keep them ready.Place the chicken into the Zodiac Master Chef jar with the chopper blade and mince the chicken.", "It takes just a couple of seconds to mince the chicken in the food processor.The next step is to cook the Chicken to make the Chicken Keema Masala for the paratha stuffing.Preheat a pan with a teaspoon of oil.", "Add onion, garlic and saute until the onions soften.Add the tomatoes and saute for a few seconds and add the turmeric powder, garam masala powder, red chilli powder, coriander powder, amchur powder, salt and the minced chicken.Saute the chicken keema along with the spices and tomatoes.", "The juice from the tomatoes will keep the chicken keema soft.It takes less than 5 minutes to cook the chicken, so ensure not to over cook it as the chicken keema will become rubbery.Once done, turn off the heat and add in the chopped mint leaves and stir.", "Check the salt and spices and adjust accordingly.The next step is to make the dough for the Chicken Keema Paratha.Into a bowl, add the flour, salt and add little water at a time and knead to make a soft and supple dough.", "Drizzle some oil and knead again.", "Once done, make 6 to 8 portions of the dough and filling.Dust the paratha dough in flour, flatten it with your finger and place it on a flat surface.", "Roll them out thin to approximately 3 inches in diameter circle.Take a portion of chicken keema filling and place it in the center.", "Next Gather the sides of the paratha dough and bring them together.", "Remove the little excess dough which popped out when you brought them together.", "Press the filled aloo paratha dough down.Dust the filled chicken keema paratha dough in some flour and roll it gently applying just a pressure.", "Roll it to desired thickness and proceed the similar way with the remaining portions of paratha dough and filling.Preheat a skillet on medium heat and place the filled chicken keema paratha.", "Allow it to cook on medium heat for about 30 to 45 seconds and flip over.Add this stage add a teaspoon of ghee or oil and spread it around.", "Flip again, so the oiled side can cook on the skillet.", "Spread a little more ghee and keep pressing the keema parathas while on the skillet to cook the paratha evenly from inside out.Do the flipping over process a couple of times until both sides get cooked, browned and crisp evenly.", "Make sure you cook on medium heat as it allows the aloo parathas to get a crisp on the outside and yet soft texture.Once the Chicken Keema paratha is cooked transfer to a plate.", "Continue to the same process with the remaining parathas the same way.Serve the Chicken Keema Paratha as a wholesome one dish meal for lunch or dinner, along with\u00a0Shalgam Gajar Aur Gobhi Ka Achar\u00a0and\u00a0Kesar Pista Lassi Recipe."]'::jsonb, 50, 'Mughlai', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Chicken_Keema_Paratha_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/504.Chicken_Keema_Paratha_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Palak Kadhi Recipe - Spinach Kadhi', 'palak-kadhi-recipe-spinach-kadhi', 'Palak Kadhi Recipe (Spinach Yogurt Curry) is a comforting curry made with fresh spinach leaves that is cooked first to remove the rawness and then pureed, it is then boiled along with a yogurt and curd based gravy.', '["1 cup Curd (Dahi / Yogurt)", "2 teaspoon Gram flour (besan)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Ingredients to grind", "1 cup Spinach", "1 Green Chilli", "1 inch Ginger", "1 teaspoon Cumin seeds (Jeera)", "To temper", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 pinch Asafoetida (hing)", "1 sprig Curry leaves", "2 Dry Red Chilli", "Oil"]'::jsonb, ARRAY['salt', 'ginger', 'green chilli', 'spinach', 'mustard seeds', 'asafoetida (hing)', 'gram flour (besan)', 'curd', 'curry leaves', 'dry red chilli', 'cumin seeds (jeera)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Palak Kadhi Recipe (Spinach Yogurt Curry), we will first pressure cook the spinach, green chillies, ginger and cumin in a pressure cooker with little water for about 1 whistle.", "Let the pressure release naturally.Once the pressure is released, add the cooked ingredients into a blender and grind to form a smooth paste.", "Keep it aside.In a sauce pan mix curd, besan, turmeric powder together and whisk well till it combines.", "Keep the sauce pan on medium heat and add about 1/2 cup of water and pureed spinach paste.Whisk well and bring it to a boil.", "When it comes to boil, add salt to taste and switch off the heat.The next step is to temper the kadhi.", "Heat a small tadka pan with oil, add cumin seeds, mustard seeds and allow it to splutter for few seconds.After few seconds, add curry leaves, asafoetida, dry red chillies and saute for few seconds.", "Add this tadka to the kadhi and give it a mix.", "Serve the\u00a0Palak Kadhi\u00a0along with\u00a0Phulka,\u00a0Aloo and Capsicum Sabzi\u00a0and\u00a0Aamras\u00a0for your everyday meals."]'::jsonb, 30, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Palak_Kadhi_Recipe_Spinach_Yogurt_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/505.Palak_Kadhi_Recipe_Spinach_Yogurt_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Raw Banana and Yam Thoran Recipe', 'raw-banana-and-yam-thoran-recipe', 'The Raw Banana and Yam Thoran Recipe is a typical Kerala vegetable dish made with yam, plantain and loaded with the goodness of coconut. It also consists of brown chickpeas to add in the extra texture to the whole dish.', '["1 Raw Banana , chopped", "1300 grams Elephant yam (Suran/Senai/Ratalu) , chopped", "1/2 cup Kala Chana (Brown Chickpeas) , soaked overnight", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "Salt , to taste", "To grind", "1 cup Fresh coconut , grated", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Whole Black Peppercorns", "3 cloves Garlic", "1 Green Chilli", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Dry Red Chilli", "1 sprig Curry leaves"]'::jsonb, ARRAY['raw banana', 's elephant yam', 'suran/senai/ratalu', 'kala chana', 'brown chickpeas', 'turmeric powder', 'haldi', 'red chilli powder', 'salt', 'to grind', 'fresh coconut', 'cumin seeds', 'jeera', 'whole black peppercorns', 's garlic', 'reen chilli', 'oil', 'mustard seeds', 'rai/ kadugu', 'dry red chilli', 'curry leaves']::text[], '["To begin the preparation of Raw Banana and Yam Thoran Recipe, remove the skin of the raw banana, yam and chop them into small pieces.Cook it with 1/4 cup water along with 1/4 teaspoon turmeric powder and little salt in the pressure cooker for 3 whistles.", "Turn off the heat and allow the pressure to release naturally.Soak chana overnight and pressure cook til it is soft along with a little salt.Blend the coconut, cumin seeds, green chillies, pepper to a coarse mixture and keep aside.Heat oil in a tadka pan, add mustard seeds, dry red chilli powder, curry leaves and let it splutter.Add cooked vegetables along with black channa, add the coconut paste, check for salt and adjust accordingly and sprinkle little water.", "Saute till raw smell of coconut leaves.", "Once done, turn off the heat and serve hot.Serve the Kerala Plantain Kootu Curry hot, with phulka or Kerala parotta!."]'::jsonb, 30, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/23-feb/Raw_banana_and_Yam_Kerala_Style_Thoran_Recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/506.Raw_banana_and_Yam_Kerala_Style_Thoran_Recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Parsi Salli Murgh Recipe - Salli Marghi', 'parsi-salli-murgh-recipe-salli-marghi', 'Parsi Salli Murgh is a spicy chicken curry that is typically served with potato straws as a garnish, hence the name, salli murgh.', '["750 grams Boneless chicken , medium pieces", "4 Onions , Fine Chopped", "1 cup Homemade tomato puree", "2 tablespoons Ginger , Paste", "2 tablespoons Garlic , Paste", "2 tablespoons Green Chilli , Paste", "1 teaspoon Kashmiri Red Chilli Powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "1 pinch Nutmeg powder", "1 pinch Cardamom (Elaichi) Pods/Seeds , crushed", "4 Cloves (Laung)", "2 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "2 Bay leaves (tej patta)", "Oil , for cooking", "Potato straws , a handful, Salli- straw like potato wafers/chips", "2 Bay leaves (tej patta)", "Oil , for cooking", "2 cups Potatoes (Aloo) , made into crispy fries", "Coriander (Dhania) Leaves , a small bunch, finely chopped"]'::jsonb, ARRAY['s boneless chicken', 'onions', 'homemade tomato puree', 's ginger', 's garlic', 's green chilli', 'kashmiri red chilli powder', 'turmeric powder', 'haldi', 'garam masala powder', 'nutmeg powder', 'cardamom', 'elaichi', 'laung', 'cinnamon stick', 'dalchini', 'bay leaves', 'tej patta', 'oil', 'potato straws', 's potatoes', 'aloo', 'coriander', 'dhania']::text[], '["To begin the preparation of Parsi Salli Murgh, wash and clean chicken nicely under running water and keep aside.Heat oil in a pressure cooker on medium heat, add the bay leaf, cloves, cardamom, cinnamon, allow it to sizzle, next add the chopped onions and saute till they attain a deep brown colour.", "This will take about 5-7 minutes.", "Now add the tomato puree and completely cook, until the mixture comes together.", "Now add the dry spice powders- chicken, turmeric powder, garam masala powder, red chilli powder, salt and mix well.", "At this stage, add the nutmeg and cardamom powder, add 1 cup of water and close the pressure cooker.", "Pressure cook for 2 whistles and turn off the flame.", "Allow the pressure to release naturally.", "Once the pressure has released, open the cooker and transfer\u00a0the Parsi Salli Murgh into the serving bowl.", "Serve with a handful of store bought potato straw known as Salli, hence the name of this dish.", "Serve this\u00a0Parsi Salli Murgh along with Iranian Berry pulao, and finish off with a traditional,\u00a0Parsi Lagan Nu Custard Recipe."]'::jsonb, 65, 'Parsi', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/shaheen_ali/Parsi_Sali_Marghi_Recipe_Parsi_Chicken_Curry_Recipe-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/507.Parsi_Sali_Marghi_Recipe_Parsi_Chicken_Curry_Recipe-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chunni Ki Puri Recipe - Moong Dal And Besan Fried Puri Recipe', 'chunni-ki-puri-recipe-moong-dal-and-besan-fried-puri-recipe', 'Puris are a classic comfort food and is a dish that can have variations with the addition of various vegetables or dal to the puri dough. In this recipe of Chunni Ki Puri, we are adding cooked yellow moong dal into the dough making a little more heavier and a bit healthier.', '["1/4 cup Yellow Moong Dal (Split) , washed, soaked and drained", "1/2 cup Gram flour (besan)", "2 cups Whole Wheat Flour", "Salt , to taste", "1/4 teaspoon Asafoetida (hing)", "1 tablespoon Oil", "Oil , for deep frying"]'::jsonb, ARRAY['yellow moong dal', 'split', 'gram flour', 'besan', 's whole wheat flour', 'salt', 'asafoetida', 'hing', 'oil']::text[], '["To begin making the Chunni ki Puri\u00a0/ Dal & Besan Puri Recipe, wash and soak the moong dal for 20 minutes.In a pressure cooker, add the dal along with 1/2 cup of water and pressure cook for 2 whistles and turn off the heat.", "Allow the pressure to release naturally.Once the pressure has released, mash dal with a whisk or churner, and allow it to cool.", "There will be very little water remaining which you can use to make the poori dough.In a large mixing bowl, add whole wheat flour, besan, salt, hing and\u00a0the mashed dal.", "Add a little water if required and knead into a firm dough.", "Add a teaspoon of oil on the top and knead for a few more minutes until smooth.", "Cover with a muslin cloth and set aside.In a heavy bottomed pan, add required amount of oil for frying the Dal & Besan Puri.Divide the\u00a0Dal & Besan Puri dough into equal portions, and dust the surface with whole wheat flour and flatten the dough balls with the rolling pin.", "Roll them out into a 2-1/2 to 3 inch diameter circle.Once the oil is heated, gently slice in the\u00a0Dal & Besan Puri.Using a slotted spoon, keep pouring oil over the puri and gently press the puri, so that the chunni ki puri puffs up.", "At this point, turn the puri to the other side and fry till it turns golden brown.Drain the Dal & Besan Puri on a kitchen towel to absorb the extra oil and serve hot.", "Serve\u00a0Chunni ki Puri/Dal & Besan Puri along with\u00a0Jodhpuri Aloo Recipe\u00a0or\u00a0Rawal Pindi Style Chole Recipe\u00a0and\u00a0Boondi Raita\u00a0for a weekday meal."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sneha-archanaskitchen.com/Chunni_ki_Puri_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/508.Chunni_ki_Puri_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Seppakizhangu Roast (South Indian Style Arbi Fry) Recipe', 'seppakizhangu-roast-south-indian-style-arbi-fry-recipe', 'Seppakizhangu Roast Recipe is a much loved South Indian Style Arbi fry. This is made from Colocasia or Taro as the main ingredient, spiced in a South Indian style. It is crisp and makes a complete meal with simple south Indian meal of Rice and Rasam, or Phulkas and Parathas.', '["500 grams Colocasia root (Arbi)", "2 teaspoon Gram flour (besan)", "2 teaspoon Rice flour", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Turmeric powder (Haldi)", "Oil , to cook", "Salt , to taste"]'::jsonb, ARRAY['s colocasia root', 'arbi', 'gram flour', 'besan', 'rice flour', 'red chilli powder', 'coriander powder', 'dhania', 'turmeric powder', 'haldi', 'oil', 'salt']::text[], '["To begin making Seppakizhangu Roast (South Indian Style Arbi Fry) Recipe, take the arbi and pressure cook them with enough water for 1 whistle.", "Switch off the heat and release the pressure, this will avoid the overcooking of arbi.", "Now peel the skin of the arbi, cut each one of them into 2-3 pieces and keep it aside.Take a big bowl, add all the dry ingredients except oil and mix well.Now add the arbi mix it lightly to coat all the vegetable with spices.", "Marinate the arbi/\u00a0colocasia in this mix for 20 minutes.Heat oil in a pan on medium heat, add the marinated arbi and give it a gentle stir.Let the arbi cook and get roasted in medium heat, occasionally give it a gentle stir.Serve the Seppakizhangu Roast (South Indian Style Arbi Fry) Recipe with Steamed Rice and Rasam.", "This also makes a great combination with hot Phulkas or Chapatis."]'::jsonb, 55, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Seppakizhangu_Roast_South_Indian_Style_Arbi_Fry_1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/509.Seppakizhangu_Roast_South_Indian_Style_Arbi_Fry_1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Methi Masoor Dal Recipe With Whole Masoor', 'methi-masoor-dal-recipe-with-whole-masoor', 'Methi Masoor Dal Recipe is a delicious lentil curry made with whole Masoor dal and fresh fenugreek leaves. This recipe is a healthy choice for the intake of everyday protein and is also packed with vitamins and minerals.', '["1 cup Masoor Dal (Whole)", "200 grams Methi Leaves (Fenugreek Leaves) , cleaned chopped", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Cumin seeds (Jeera)", "1 Onion , thinly sliced", "1 Tomato , chopped", "1 Green Chilli , slit", "2 teaspoons Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "Salt , to taste", "1 tablespoon Ghee"]'::jsonb, ARRAY['tomato', 'salt', 'green chilli', 'asafoetida (hing)', 'ghee', 'methi leaves (fenugreek leaves)', 'red chilli powder', 'onion', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'masoor dal']::text[], '["To prepare the Methi Masoor Dal Recipe, first wash and soak the masoor dal in 3 cups of water for at least 30 minutes.", "While the dal is soaked clean, wash and pat dry the fenugreek leaves.Next, finely chop the methi leaves.", "Heat a teaspoon of oil in a wok or a kadai and add the chopped methi leaves into the wok.Saute the methi leaves, until it gets softened.", "Methi leaves cooks very quickly and this will take less than a minute to cook.", "Once the leaves have softened, turn off the heat.", "Keep it aside.In the next step, we will cook the masoor dal with the spices.", "Heat ghee in a pressure cooker over medium heat.", "Add asafoetida and cumin seeds and allow it to crackle.Next add onion and saute till they turn soft.", "Once the onions have softened, add the chopped tomato, green chilli along with coriander powder, turmeric powder, red chilli powder and saute for a minute or so over medium heat.Add soaked masoor dal along with the soaked water to the onion tomato mixture.", "Close the lid of the pressure cooker and put the weight on.Cook masoor dal for 3 whistles.", "After a couple of whistles, turn the heat to low and simmer the dal for about 5 minutes.", "After 5 minutes, turn off the heat.", "Allow the pressure to release naturally from the pressure cooker.Once the pressure has released, open the cooker and lightly mash the masoor dal with the back of a spoon.", "Stir in the saut\u00e9ed methi leaves and serve.Serve the\u00a0Methi Masoor Dal Recipe along with\u00a0Tawa Paratha Recipe,\u00a0Baby corn and Carrot Sabzi Recipe\u00a0to make it a wholesome Indian diabetic friendly dinner."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Methi_Masoor_Dal_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/510.Methi_Masoor_Dal_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Stuffed Kathal Recipe', 'stuffed-kathal-recipe', 'Stuffed Kathal is a dish with fiery onion-tomato masala with a twist of cheese.', '["250 grams Jackfruit Raw (Kathal)", "Mustard oil , for frying", "3 Onions", "2 Tomatoes , boiled and pureed", "5 cloves Garlic", "1/2 inch Ginger", "1 tablespoon Garam masala powder", "1 tablespoon Coriander (Dhania) Seeds", "4 Cloves (Laung)", "1 tablespoon Kashmiri Red Chilli Powder", "1 teaspoon Turmeric powder (Haldi)", "2 tablespoon Curd (Dahi / Yogurt)", "Salt , to taste", "1 Onion , finely chopped", "1 teaspoon Fennel seeds (Saunf)", "1 teaspoon Mustard oil", "1 teaspoon Garlic Butter", "50 grams Paneer (Homemade Cottage Cheese) , finely chopped", "Black pepper powder , to taste", "Salt , to taste", "1/2 cup Mozzarella cheese , grated"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'kashmiri red chilli powder', 'mustard oil', 'fennel seeds (saunf)', 'garlic butter', 'paneer', 'mozzarella cheese', 'cloves garlic', 'curd', 'coriander (dhania) seeds', 'onion', 'black pepper powder', 'jackfruit (kathal)', 'turmeric powder', 'cloves (laung)', 'garam masala powder']::text[], '["To begin making the Stuffed Kathal,\u00a0\u00a0let us first cut the raw jackfruit.", "In order to do that we have to first, grease our hands and the knife that we are going to use, with some oil.This important tip ensures that the hands don''t get sticky from the natural fruit latex/sap present in the fruit does not get onto your hands and makes the cutting process hassle-free.", "Keep a bowl of water mixed with some salt, ready to put the cut raw jackfruit pieces to avoid discolouration of the fruit.Now that your hands and knife are well greased, cut the the jackfruit in half, discard the skin and start making 1 inch pieces and soak them in the salted water.Place the jackfruit in a pressure cooker with 1/4 cup of water and pressure cook for 1 whistle and turn off the heat.Allow the pressure to release naturally.", "Drain any water from the jackfruit and set aside.Heat mustard oil in a pan on medium heat, shallow fry until crisp.", "This will take about 5-7 minutes.", "Drain on an absorbent paper and set aside.", "In a pan, heat garlic butter on low heat, add fennel seeds and allow it to sizzle, next add the onions and fry till soft, for about 3 minutes.", "Next add paneer and fry well.", "Turn off the flame.", "Stuffing for the stuffed kathal\u00a0is ready.Take Kathal pieces and stuff the jackfruits with the onion-paneer stuffing.", "Sprinkle salt and pepper over the stuffed kathal, give it a quick mix and let it rest for an hour while the flavours infuse.", "Meanwhile, to prepare the gravy.Heat oil in a pan, on medium heat, add onions and saute for a couple of minutes.", "Once thee onions are transparent, add tomatoes and give it a good mix, cover and cook until mushy, this will take about 3-4 minutes. turn off the flame.", "Once the onion-tomato cools down, grind it in a mixer\u00a0to a coarse paste.", "Heat a kadai on medium flame, transfer the coarse tomato-onion mixture and add chilli powder, garam masala and turmeric powder, curd and saute till the masala is cooked well and comes together.Adjust spices and salt according to your taste.Once done, pour this thick masala in an Oven Safe Bowl.", "Put in the stuffed Kathal/jackfruit.Sprinkle grated mozzarella and bake in the preheated oven at 180 degrees Celsius for 10-15 minutes.Garnish with spring onions and serve\u00a0Stuffed\u00a0Kathal\u00a0\u00a0with hot\u00a0Laccha paratha/tawa paratha recipe\u00a0for a weeknight dinner."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Kriti_Singhal/Stuffed_Jackfruit_Kathal_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/511.Stuffed_Jackfruit_Kathal_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Doi Ilish Recipe - Bengali Style Hilsa In Yogurt Gravy Recipe', 'doi-ilish-recipe-bengali-style-hilsa-in-yogurt-gravy-recipe', 'Doi Ilish Recipe is a Bengali fish recipe in which fish is cooked in a yogurt gravy. Just a throw of kalonji, some wicked green chillies and a luxuriant drizzle of mustard oil, makes this dish delicious and mouth watering. It is easy to make and therefore it is perfect to be served for everyday lunch or dinner.', '["5 Fish , Ilish", "1 cup Curd (Dahi / Yogurt) , whipped", "2 teaspoons Kasundi mustard sauce", "1 teaspoon Kalonji (Onion Nigella Seeds)", "2 teaspoons Turmeric powder (Haldi)", "2 teaspoons Red Chilli powder", "4 Green Chillies , slit (adjustable)", "3 tablespoons Mustard oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'kasundi mustard sauce', 'curd whipped', 'kalonji (onion nigella seeds)', 'mustard oil', 'red chilli powder', 'turmeric powder', 'green chillies', 'fish ilish']::text[], '["To begin making the Doi Ilish Recipe, firstly marinate the fish with turmeric and salt.", "Keep it aside.Heat oil in a heavy bottomed pan.", "Once the oil is mildly hot, add the fish and shallow fry them.", "Once done, take it out of the pan and keep it aside to cool it down.Once done, add the fried fish pieces in a mixing bowl along with turmeric powder, red chilli powder, whipped curd and just a pinch of salt.", "Mix everything properly and keep it aside for 10 minutes.To the same pan, add the rest of the oil, when smoking hot, throw in the nigella seeds and green chillies.", "When they stop spluttering, turn the heat to low and gently slide in the fish along with the marinade.Cook for a couple of minutes till the curd starts to release oil.", "Now add a little warm water to the mustard paste and add it to the yogurt mixture.", "Add this micxture to the pan and simmer for 4-5 minutes.", "Adjust the salt, give it a mix and serve hot.Serve\u00a0Doi Ilish Recipe\u00a0along with\u00a0Steamed Rice\u00a0and\u00a0Kachumber Salad\u00a0for a weekday meal.", "You can also make this delicious Bengali Style Fish Gravy for your house parties with other Bengali dishes."]'::jsonb, 25, 'Bengali', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/maumita.paulghosh-gmail.com/Doi_Ilish_Hilsa_in_Yogurt.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/512.Doi_Ilish_Hilsa_in_Yogurt.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Beetroot Greens Rice Recipe', 'beetroot-greens-rice-recipe', 'Beetroot Greens Rice Recipe is a rice dish which is made with the combination of rice and beetroot greens. Next time when you buy a bunch of beetroot with leafy greens, do not throw away those gorgeous leaves, as you can include them in your day to day meals like salads, stir fries etc.', '["1 cup Cooked rice", "200 grams Beetroot Greens , finely chopped", "1 Onion , finely chipped", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "1/2 tablespoon Red Chilli powder", "1/2 tablespoon Coriander Powder (Dhania)", "1 tablespoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves", "1/2 teaspoon Salt"]'::jsonb, ARRAY['salt', 'ginger', 'rice', 'mustard seeds', 'beetroot greens', 'red chilli powder', 'cloves garlic', 'curry leaves', 'cumin seeds (jeera)', 'onion chipped', 'coriander powder', 'sunflower oil']::text[], '["To begin making the Beetroot Greens Rice Recipe, firstly remove the beetroot green leaves from beetroot.Wash them thoroughly by rinsing in cold water for at least 4-5 times.", "Chop the onion and leaves along with its tender pink stem finely.Separate the pink stem from the greens and keep them aside.Heat oil in a\u00a0pan and add mustard seeds & cumin seeds.", "Once they crackle, add onion, ginger and garlic.", "Saute them till the onion becomes translucent.Once it is done, add the chopped pink stem and sprinkle some water on it.", "They take around 5 minutes to get cooked.", "Then add the greens and cook it for 1-2 minutes.Add chilli powder and coriander powder and saute it for about 3 minutes.", "After 3 minutes, add the cooked rice with the mixture and mix it well.When the rice is properly mixed with the masala, cover the pan with a lid and let it cook for 5 minutes on low flame.Adjust salt according to your taste and turn off the heat.", "Transfer the beetroot greens rice into a serving plate and serve.", "Serve\u00a0Beetroot Greens Rice Recipe\u00a0with\u00a0Tomato Onion Cucumber Raita Recipe\u00a0for lunch."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Rekha_Shivakumar/BeetRoot_Greens_Rice.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/513.BeetRoot_Greens_Rice.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Moongachi Usali (Goan Style Sprouted Green Gram Stir Fry)', 'moongachi-usali-goan-style-sprouted-green-gram-stir-fry', 'Moongachi Usali is a traditional Goan Style preparation of sprouted green gram. This dish is packed with nutrition and is so easy to prepare. it requires very little oil, and is made without onion or garlic, making it suitable for festival days too. What is unique about this dish is the addition of a little jaggery which adds an unexpected flavour to it. This dish used to be served in "Baal-wadis" or pre-schools for children, as a nutritious snack. Serve this dish with Steamed Rice and Amlechi Uddamethi, or with Chapati and Rava Fried Raw Banana.', '["2 cups Green Moong Sprouts", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1 pinch Asafoetida (hing)", "1 teaspoon Jaggery , grated", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "2 Green Chillies , chopped", "2 tablespoon Fresh coconut , grated", "1 tablespoon Oil"]'::jsonb, ARRAY['s green moong sprouts', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'asafoetida', 'hing', 'jaggery', 'turmeric powder', 'haldi', 'red chilli powder', 'reen chillies', 'fresh coconut', 'oil']::text[], '["To begin making the Moongachi Usali first pressure cook the sprouted green gram.", "To do this, add the sprouted green gram into a pressure cooker.", "Add enough water to submerge the sprouts and place it on the heat with the lid and whistle on.Allow it to cook till you hear 3 whistles, after which you can switch it off.", "Let the pressure get released on its own, naturally.Drain the pressure cooked sprouted green gram, retain the water as it is very nutritious and can be used in making roti dough or added to dals and curries.Place a kadai/wok on the heat, add some oil and add mustard seeds to it.When mustard seeds crackle, add cumin seeds and asafoetida and let it sputter.Then after few seconds, add chopped green chilies and fry for few more seconds.Add turmeric and red chili powder and stir together.Now add the pressure cooked sprouted green gram to the kadai and mix well so all the flavours are well combined.At the very end, sprinkle the grated coconut and jaggery and toss to combine once again.Finally add salt to taste and serve along with\u00a0Steamed Rice\u00a0and\u00a0Maharashtrain Amti, or with\u00a0Chapati."]'::jsonb, 40, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Moogachi_oosali__Goan_Style_Sprouted_Green_Gram_Stir_Fry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/514.Moogachi_oosali__Goan_Style_Sprouted_Green_Gram_Stir_Fry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pumpkin Chapati Recipe', 'pumpkin-chapati-recipe', 'Pumpkin Chapathi Recipe is one that you need to try for your everyday meal. It is a simple Indian bread by made by mixing it along with a vegetable to increase the nutrient content. Pumpkin is really good for heart. The vegetable is also rich in Vitamin C, fiber and Potassium. By adding pumpkin into the dough, it will create a very soft bread. You can pack this for your everyday lunch box or even for your kids lunch box too.', '["1 cup Whole Wheat Flour", "200 grams Kaddu (Parangikai/ Pumpkin) , boiled and mashed", "1/2 teaspoon Salt", "Oil , for kneading", "Ghee , or oil for cooking"]'::jsonb, ARRAY['salt', 'wheat flour', 'parangikai pumpkin', 'ghee', 'oil', 'sunflower oil']::text[], '["To begin making the Pumpkin Tawa Paratha Recipe, we will first pressure cook the pumpkin till it is completely cooked, this will take about 4 to 5 whistle and Once down allow the pressure to release by itself and mash them well.In a large bowl combine the flour, salt, mashed pumpkin, a tablespoon of oil and knead adding little water at a time to make firm and smooth dough.", "Add one tablespoon of oil to coat the dough and knead again.", "Cover and set aside for 15 minutes.Knead once again and divide the dough into 8 portions.", "Preheat the iron skillet on medium heat.Roll the paratha dough portions into balls and flatten them with the palm of your hand.", "Toss them on flour and roll them out into circles of approximately 3 inches in diameter.", "Put 1/4 teaspoon oil and spread it on the rolled dough.We need to get a triangle shape, to do so, first fold into a semi-circle, then fold the semi-circle into half again.", "You get a mini triangle shape.", "Tossing the triangle on a little flour, roll it out gently into a larger triangle.", "Continue the same process of rolling with the remaining dough portions.With skillet on medium high heat, place one rolled out dough on the skillet.", "After a few seconds you will notice an air pockets popping out.", "At this point flip the plain paratha and smear about 1/2 a teaspoon of ghee.", "Using a flat spatula do a light pressing and turning motion to cook to the pumpkin paratha.Flip to the other side and press and turn in a similar way.", "You will notice brown spots around the pumpkin parathas and it will be slightly crisp.", "Remove from heat and place on a platter or serve hot.Continue the similar process with the remaining rolled portions and stack the cooked pumpkin paratha one above the other and serve hot.Serve the Pumpkin Chapathi Recipe along with\u00a0Dahi Bhindi Recipe\u00a0or\u00a0Carrot and Beans Thoran (Subzi Recipe)\u00a0for your everyday lunch ideas."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Pumpkin_Chapati_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/515.Pumpkin_Chapati_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Steamed Rice Recipe - Pressure Cooker & Sauce Pan Methods', 'steamed-rice-recipe-pressure-cooker-sauce-pan-methods', 'Rice can be cooked in a variety of ways. Personally I find the pressure cooker method quick and effective, that can produce rice grains of different textures - from soft to grainy. There are a number of different types of rice grains available and you might choose the variety that your family has been eating for generations or you might want to try another new variety.', '["1 cup Rice", "Salt , if required", "2 cups Water"]'::jsonb, ARRAY['rice', 'salt', 's water']::text[], '["*Method to Cook Rice in Pressure Cooker MethodRinse the rice well under running water.", "Place one cup of washed rice along with two cups of water in the pan of the pressure cooker.Keep the weight on, cover the pressure cooker.", "Cook the rice in the pressure cooker on medium high heat and after the first whistle turn the heat to low.", "Once you turn the heat to low, simmer the rice for 3 minutes.", "After 3 minutes, turn off the heat and allow the pressure to release naturally.", "Rice takes a longer time to cook, hence wait for the pressure to release completely and then open the cooker and use as desired.*Method to Cook Rice in Saucepan\u00a0MethodRinse the rice well under running water and optionally soak for about 15 minutes.", "In a heavy-bottomed saucepan with a light-fitting lid, combine 2 cups water, washed rice and salt (optional).Bring the mixture to a boil over high heat.", "As water begins to boil turn the heat to low, cover the pan with a lid and simmer the rice mixture for about 12 to 15 minutes or until it''s cooked and all the water is absorbed.Turn off the heat and allow the rice to rest covered in the pan for at least another 10 minutes.", "Before serving, fluff the rice with a fork and serve."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/BasicRecipes_HOW_TO/Cooked_Rice_In_Pressure_cooker_Sauce_Pot-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/516.Cooked_Rice_In_Pressure_cooker_Sauce_Pot-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bharwa Karela With Sweet Potato Filling Recipe', 'bharwa-karela-with-sweet-potato-filling-recipe', 'Bharwa Karela with Sweet Potato Filling Recipe, is stuffed with sweet potato and is cooked until it becomes soft. Stuffed with tangy and spicy sweet potato dry masalas, this makes a great accompaniment to Dal, Rice and Roti.', '["5 Karela (Bitter Gourd/ Pavakkai)", "2 Sweet Potatoes , boiled", "2 Tomatoes , finely chopped", "1 inch Ginger , finely chopped", "3 Green Chillies , finely chopped", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 teaspoon Chaat Masala Powder", "Salt , as needed", "2 tablespoons Mustard oil , or more to cook"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'karela (bitter gourd pavakkai)', 'chaat masala powder', 'red chilli powder', 'turmeric powder', 'green chillies', 'sweet potatoes', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Bharwa Karela with Sweet Potato Filling Recipe, prep all the ingredients and keep ready.Lightly peel the skin karelas/bitter gourd , cut into 1 inch cylinders and Scoop out and discard seeds and pulp to fill the sweet potato masala.", "Sprinkle salt and turmeric to remove the bitterness.", "Let it rest for 20-25 minutes.To prepare the sweet potato masala.", "Pressure cook the peeled sweet potato in a pressure cooker with 1 cup of water and cook for 3 whistles.", "Allow the pressure to release naturally.", "Once cooled, peel the skin and either grate or mash the potato.Heat a skillet with oil over medium heat; add ginger and allow it to soften for few seconds.", "Add chopped tomatoes and green chilies and sprinkle with salt.", "Allow the tomatoes turn mushy.Add turmeric powder, red chili powder, chat masala, garam masala and salt.", "Mix everything to be incorporated well.Cook for at least 2 minutes until the flavours come through.", "Check the salt and spices and adjust to suit your taste.", "Now fill the karelas with potato masala filling tightly.Heat a wide pan with the oil; place the Bharwa Karela with Sweet Potato Filling and pan fry the karela until it is cooked and has brown spots.Cover the pan and cook, so the steam helps it cook faster.", "Once done, you can sprinkle a little more chaat masala and serve hot.Serve the\u00a0Bharwa Karela with Sweet Potato Filling Recipe\u00a0along with\u00a0Panchmel Dal\u00a0and\u00a0Phulka\u00a0for an everyday meal."]'::jsonb, 55, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Bharwa_Karela_with_Sweet_Potato_Filling_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/517.Bharwa_Karela_with_Sweet_Potato_Filling_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Subz Noor E Chashm Recipe (Nawabi Curry Recipe )', 'subz-noor-e-chashm-recipe-nawabi-curry-recipe', 'Subz Noor E Chashm Recipe (Nawabi Curry Recipe) is a rich and creamy curry filled with assorted vegetables which go well with Indian bread. The curry was originally from Awadhi cuisine, which was a feast for all the royal families. Thus the gravy consists of almonds and cashew nuts to give it a rich and luscious consistency.', '["1 Cauliflower (gobi) , cut into small florets and blanched", "1/2 cup Green peas (Matar)", "1 Carrot (Gajjar) , cubed and blanched", "1 Bay leaves (tej patta)", "3 Cloves (Laung) , 3 cloves", "1/2 teaspoon Cumin seeds (Jeera)", "3 cloves Garlic , chopped", "1 inch Ginger , chopped", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "2 teaspoons Garam masala powder", "1 teaspoon Cumin seeds (Jeera)", "2 Onions , chopped", "2 Tomatoes , chopped", "2 tablespoons Cashew nuts", "2 tablespoons Whole Almonds (Badam) , blanched", "1/2 cup Curd (Dahi / Yogurt)", "Salt , taste", "Oil , for cooking", "1 sprig Coriander (Dhania) Leaves , for garnish"]'::jsonb, ARRAY['tomato', 'cashew nuts', 'salt', 'ginger', 'bay leaves (tej patta)', 'cloves (laung) cloves', 'cauliflower (gobi)', 'green peas (matar)', 'cloves garlic', 'carrot', 'red chilli powder', 'curd', 'coriander (dhania) leaves', 'onion', 'cumin seeds (jeera)', 'badam (almond)', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["We begin making the Subz Noor E Chashm Recipe (Nawabi Curry Recipe ) by making the paste for the curry, heat a non stick pan and crackle the cumin seeds.", "Add onions and saute till it is translucent and golden brown.Later on add the chopped tomatoes, cook till it becomes mushy and soft.", "Add in the nuts and saute for 2 more minutes.", "Remove it from the flame and let it cool so you can blend it into a smooth paste using a blender.Once it is done mix it with curd and combine it evenly.Next is to make the curry, heat a flat bottomed pan and pour some oil, add in the cumin seeds, ginger and garlic.", "Saute till it is brown.", "Add all the vegetables and saute for about 10 minutes.Once the vegetables are cooked little,add the ground paste and coat it evenly.", "Add the spice powders that are listed and cook again for 4 more minutes.You can adjust the consistency by adding some water and bring it to a boil.", "Check for seasoning, according to your taste.Serve the\u00a0Subz\u00a0Noor E\u00a0Chashm\u00a0Recipe (Nawabi Curry Recipe ) along with\u00a0whole wheat Lachha Paratha\u00a0to enjoy the Awadhi Meal."]'::jsonb, 50, 'Awadhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/Nov-2/Subz_Noor_E_Chasham_Recipe_Nawabi_Curry_Awadh_Cuisine-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/518.Subz_Noor_E_Chasham_Recipe_Nawabi_Curry_Awadh_Cuisine-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tandoori Style Soya Chaap Curry Recipe', 'tandoori-style-soya-chaap-curry-recipe', 'Soya Chaap is a dish from South Asia and it is especially popular in India and Pakistan. Soya Chaap is basically made of soya bean and it mimics the texture of meat amazingly thus it a delicious treat not just for vegetarians but meat lovers too. Tandoori Style Soya Chaap Curry is a spicy dish where tandoori style marination plays the key role and make the chaap even more tender packed with flavors.', '["6 Soya Chaap", "1 Tablespoon Ginger Garlic Paste", "1/2 cup Curd (Dahi / Yogurt)", "1 Red Bell pepper (Capsicum)", "1/4 cup Cheese , grated", "4 Green Chillies", "1 teaspoon Garam masala powder", "1 teaspoon Tandoori masala", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Kashmiri Red Chilli Powder", "Coriander (Dhania) Leaves , Fresh (chopped)", "Salt , to taste", "Oil , as required"]'::jsonb, ARRAY['cheese', 'salt', 'red bell pepper (capsicum)', 'kashmiri red chilli powder', 'coriander (dhania) leaves', 'tandoori masala', 'red chilli powder', 'ginger garlic paste', 'curd', 'soya chaap', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Tandoori Style Soya Chaap Curry recipe, first remove the sticks from Soya chaap and dice them small circular pieces.Next, take a bowl and add diced soya chaap, ginger garlic paste, and salt together.", "Use your hands to rub the mixture on soya chaap.", "Let it marinate for 15 minutes.Meanwhile, take the red pepper and keep it directly on gas (fire) for roasting.", "Roast till it gets charred from all the sides.", "Let it cool down for few minutes.", "Use your hands to remove the burnt skin from the pepper.", "Grind the roasted pepper & green chillies together.Now take the marinated soya chaaps and add red pepper paste, whisked yogurt, grated cheese and all the spices into it.", "Give it a good stir so that soya chunks are properly coated.", "Cover the bowl with a cling film & leave it for another 15 minutes of marination.", "Once marinated, then heat up oil in pan and first add the soya chunks in order to fry them.", "Cook them for 7-8 minutes and then add the left over marinade into the pan.", "Cook on low heat till the gravy starts thickening.Adjust salt as per your taste and turn off the heat.", "Garnish it with some fresh coriander leaves and serve hot.Serve\u00a0Tandoori Style Soya Chaap Curry along with\u00a0Tomato Onion Cucumber Raita\u00a0and\u00a0Whole Wheat Lachha Paratha\u00a0for a weekday meal."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/garimasgautam-gmail.com/Tandoori_Style_Soya_Chaap_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/519.Tandoori_Style_Soya_Chaap_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mirch Ki Sabzi Recipe With Roasted Peanuts', 'mirch-ki-sabzi-recipe-with-roasted-peanuts', 'The Mirch Ki Sabzi Recipe with Roasted Peanuts is simple and easy side dish made with whole green chilli also known as the Bajji Chilli that is tossed with masala, a touch of  amchoor powder for the tanginess and some roasted and crushed peanuts to add to the delicious taste. It makes a perfect side dish when served along with panchmel dal, phulka and kadai paneer.', '["10 Badi hari mirch (Large Green Chilli) , also known as Bajji Chilli", "1 tablespoon Mustard oil", "1/2 teaspoon Ajwain (Carom seeds)", "2 tablespoons Gram flour (besan)", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Amchur (Dry Mango Powder)", "2 teaspoons Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "1 teaspoon Lemon juice", "1/4 cup Raw Peanuts (Moongphali) , crushed", "1 tablespoon Jaggery", "Salt , as required", "6 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['badi hari mirch', 'large green chilli', 'mustard oil', 'ajwain', 'carom seeds', 's gram flour', 'besan', 'red chilli powder', 'turmeric powder', 'haldi', 'amchur', 'dry mango powder', 's coriander powder', 'dhania', 'garam masala powder', 'lemon juice', 'raw peanuts', 'moongphali', 'jaggery', 'salt', 'coriander']::text[], '["To begin making the Mirch Ki Sabzi Recipe, prep all the ingredients and keep them ready.Split the chillies in half and remove the seeds and cut into 1-1/2 inch piecesHeat oil in a wok/kadai and once the oil is hot add ajwain and allow it to crackle for a few seconds.", "Stir in the green chillies and sprinkle a little salt and give it a stir.Turn the heat to low, cover the pan and simmer for a couple of minutes until the chilli begins to sweat a little bit and starts releasing moisture.", "Once the chillies is releasing moisture, add the masalas -\u00a0 red chilli powder, turmeric powder, amchoor, garam masala, coriander, besan and salt.", "Give it a stir.Cover the pan again and occasionally keep stirring the Mirch Ki Sabzi until it is cooked.", "Once the green chillies are cooked, Add pound peanuts, a little jaggery and optionally lemon juice to give the\u00a0Mirch Ki Sabzi that extra tanginess and mix well.Once the Mirch Ki Sabzi well tossed in the masala, turn off the heat.Transfer the\u00a0Mirch Ki Sabzi into a serving bowl.", "Stir in the chopped coriander leaves and serve hot.Serve the Mirch Ki Sabzi Recipe along with\u00a0Thepla,\u00a0Lauki Raita Recipe\u00a0and\u00a0Panchmel Dal\u00a0by the side for lunch or dinner."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Katti_Mitti_Mirchi_Ki_Sabzi_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/520.Katti_Mitti_Mirchi_Ki_Sabzi_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Style Raw Jackfruit Curry Recipe - Enchor’er Dalana', 'bengali-style-raw-jackfruit-curry-recipe-enchor-er-dalana', 'Bengali Style Raw Jackfruit Curry Recipe called Enchor’er Dalana is a delicious curry made with green tender jackfruit.  Although the fruit is more native to Karnataka as the cultivation is majority from the region of Western Ghats. But in places like Bengal they also use in their day to day cooking to make curries, pickles or even cutlets.', '["500 grams Jackfruit Raw (Kathal)", "2 Black cardamom (Badi Elaichi)", "1 inch Cinnamon Stick (Dalchini)", "1 Onion , sliced", "3 tablespoon Ginger Garlic Paste", "2 Green Chillies , chopped", "1/2 Hung Curd (Greek Yogurt)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Garam masala powder", "Salt , to taste", "Sugar , to taste", "2 sprig Bay leaves (tej patta)", "1 tablespoon Ghee", "2 tablespoons Mustard oil"]'::jsonb, ARRAY['black cardamom (badi elaichi)', 'cumin powder (jeera)', 'hung curd (greek yogurt)', 'salt', 'mustard oil', 'ghee', 'bay leaves (tej patta)', 'red chilli powder', 'ginger garlic paste', 'sugar', 'cinnamon stick (dalchini)', 'onion', 'jackfruit (kathal)', 'turmeric powder', 'green chillies', 'garam masala powder']::text[], '["We begin making the Bengali Style Raw Jackfruit Curry Recipe,\u00a0let us first cut the raw jackfruit.", "In order to do that we have to first, grease our hands and the knife that we are going to use, with some oil.This important tip ensures that the hands don''t get sticky from the natural fruit latex/sap present in the fruit does not get onto your hands and makes the cutting process hassle-free.", "In a bowl, whisk together curd along with water to make the buttermilk.", "Keep a bowl of buttermilk aside to drop in the chopped jackfruit\u00a0Now that your hands and knife are well greased, cut the the jackfruit in half, discard the skin and start making 1 inch pieces and soak them in the buttermilk.", "Drain and transfer the raw jackfruit into a bowl.", "To marinate the jackfruit,\u00a0to the jackfruit bowl, add turmeric powder and mustard oil and give it a good mix.", "Marinate it for about 20 minutes.Heat oil in a pan on medium heat, add the cinnamon sticks, bay leaf and cardamom.Once it begins to sizzle,\u00a0add\u00a0 half of the sliced onions along with ginger and garlic, fry till it becomes translucent.", "Once done cool it down and grind it into a smooth paste and keep it aside.Heat a pressure cooker on medium heat, add oil and fry the rest of the onions till it is golden brown.", "Then add the marinated jackfruit and fry it for 5 minutes.Add the onion paste, all the spices-turmeric powder, red chilli powder, cumin powder and\u00a0garam masala\u00a0along with sugar and salt.", "Keep cooking the jackfruit in the masala till the oil comes to the surface.Add about 1/2 cup of water and mix well.", "Close the pressure cooker and pressure cook the Raw Jackfruit Curry\u00a0 for 2 whistle till it becomes tender.Allow the pressure to release naturally and check for seasoning.", "Serve the\u00a0Bengali Style Raw Jack fruit Curry Recipe\u00a0along with\u00a0Ragi Tawa Paratha\u00a0and\u00a0Kala Chana Salad Recipe With Carrots, Cucumber & Tomatoes\u00a0 and\u00a0Beetroot Carrot Raita Recipe\u00a0for a completely healthy meal.", "This meal is also\u00a0Diabetic Friendly ."]'::jsonb, 50, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Bengali_Style_Raw_Jackfruit_Curry_Recipe_Enchorer_Dalana_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/521.Bengali_Style_Raw_Jackfruit_Curry_Recipe_Enchorer_Dalana_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Butter Garlic Naan Recipe - Garlic Flavoured Flatbread', 'butter-garlic-naan-recipe-garlic-flavoured-flatbread', 'Butter Garlic Naan is one of the most popular flatbreads which is served in most of the Indian restaurants. Traditionally baked in a hot Tandoor oven, this soft, smoky, leavened bread can be easily made at home using a hot iron griddle, on the stove top with almost similar result.', '["3 cups All Purpose Flour (Maida)", "1-1/2 teaspoons Active dry yeast", "1/4 cup Curd (Dahi / Yogurt) , whisked", "Salt , as required", "1/2 teaspoon Sugar", "8 cloves Garlic , ground", "2 tablespoon Butter (Salted) , softened", "Lukewarm Water , as required", "6 cloves Garlic , finely minced", "2 teaspoons Coriander (Dhania) Leaves , chopped", "1 teaspoon Mint Leaves (Pudina) , chopped", "2 tablespoon Butter (Salted) , melted"]'::jsonb, ARRAY['salt', 'cloves garlic ground', 'coriander (dhania) leaves', 'water', 'dry yeast', 'cloves garlic', 'curd', 'sugar', 'mint leaves (pudina)', 'flour (maida)', 'butter']::text[], '["To begin making the Butter Garlic Naan, prep all the ingredients and keep them ready.In a large mixing bowl, add the flour, salt, sugar and yeast and stir to combine.", "Add the curd, butter, garlic paste and mix well.", "Gradually add the lukewarm water and knead it into a soft pliable dough.Knead for about 8-10 minutes on a flat, lightly floured surface. (Use the hook attachment for kneading, if using a stand mixer)Place the dough in a well oiled bowl and cover with a damp kitchen towel.", "Let the dough rest for 2 hours, till it doubles in size.Punch down the dough, once doubled and knead for a minute or two.Divide the dough into 6-7 equal portions and shape them into a ball.", "Pat or Roll out each ball to a 7-8 inch elongated, tear shape. (Keep the other dough balls covered while your roll out one.) Sprinkle some chopped garlic over the Naan and press well.Turn it over and brush this side with some water.Preheat an iron griddle over medium heatPlace the water brushed side on the hot iron griddle.Invert the griddle exposing the garlic side directly to the flame, without directly touching the flame.Move the griddle slowly so that the Naan cooks evenly.In about a minute, the Naan starts browning and you can see a few bubbles.Using a pair of tongs, take off the Naan from the griddle and cook the other side directly on the flame.", "Keep moving the naan for even cooking.Mix the coriander and mint with the melted butter.", "Brush the Garlic Naan with this herbed butter and serve\u00a0Butter Garlic Naan with\u00a0Punjabi Sabut Moong Ki Dal\u00a0and\u00a0Dry Methi Malai Matar, along with Beetroot Raita for a satisfying meal."]'::jsonb, 270, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Butter_Garlic_Naan_Garlic_flavoured_leavened_Flat_bread_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/522.Butter_Garlic_Naan_Garlic_flavoured_leavened_Flat_bread_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Huli Soppu Saaru Recipe - Karnataka Style Mixed Greens Sambar', 'huli-soppu-saaru-recipe-karnataka-style-mixed-greens-sambar', 'Huli Soppu Saaru Recipe is a traditional Karnataka Style Sambar made using a mix of greens. We have used fresh spinach, fenugreek leaves and amaranth for this recipe. The freshly ground sambar masala adds a rustic flavour to the dish. Huli Soppu Saaru Recipe is also known as Ulsoppu in many regions of the state of Karnataka. It is a perfect accompaniment for the Mudde (Ragi Balls) as well as steamed rice.', '["1 cup Arhar dal (Split Toor Dal)", "1 teaspoon Turmeric powder (Haldi)", "100 grams Red Amaranth Leaves , finely chopped", "100 grams Spinach Leaves (Palak) , finely chopped", "100 grams Methi Leaves (Fenugreek Leaves) , finely chopped", "30 grams Tamarind , soaked in warm water", "1 cup Pearl onions (Sambar Onions) , halved", "1 teaspoon Jaggery , grated/powder", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 tablespoon Chana dal (Bengal Gram Dal)", "1 tablespoon White Urad Dal (Split)", "2 tablespoons Coriander (Dhania) Seeds", "1 tablespoon Cumin seeds (Jeera)", "1 tablespoon Whole Black Peppercorns", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "4 Dry Red Chillies", "1/2 cup Fresh coconut , grated", "1 teaspoon Gingelly oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chilli", "1 sprig Curry leaves", "1/4 teaspoon Asafoetida (hing)"]'::jsonb, ARRAY['salt', 'mixed greens', 'arhar dal (split toor dal)', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'jaggery', 'black peppercorns', 'dry red chilli', 'curry leaves', 'cloves (laung) garlic', 'coriander (dhania) seeds', 'onion', 'tamarind water pulp', 'white urad dal (split)', 'methi seeds (fenugreek seeds)', 'dry red chillies', 'cumin seeds (jeera)', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making Huli Soppu Saaru Recipe\u00a0first prep all the ingredients and keep them ready.", "First step, wash the toor dal and add it into the pressure cooker along with 2-\u00bd cups of water and turmeric powder.", "Cover the cooker and pressure cook for 2 whistles.After 2 whistles turn the heat to low and simmer for 3 to 4 minutes and turn off the heat.", "Allow the pressure to release naturally.", "Once the pressure releases,\u00a0 open the cooker and mash the dal lightly until smooth.Next, Soak the tamarind in hot water for 15 minutes.", "After 15 minutes, using your fingers, mash the tamarind well into the water until it feels completely soft.This process helps to extract the juice and sourness from the tamarind.", "Do this process another couple of times by adding 1/4 cup of water at a time.", "Combine all the tamarind water into a single bowl and set aside.For the masala, preheat a pan over medium heat; add the chana dal and urad dal and roast until the dals turn golden and lightly crisp.", "At this stage, add the coriander seeds, cumin seeds, methi seeds and dry red chillies.Stir for another minute or two until you notice the seeds start crackling and you can smell the aromas coming through.Finally add the coconut and stir it for 30-40 seconds and turn off the heat.", "Allow the mixture to cool.", "Once cooled, blend to make a fine powder.", "Keep aside.To cook the sambar add the tamarind water, chopped greens, onions, ground sambar powder, turmeric powder and salt.", "Add 1/4 cup of water and pressure cook for 2 whistles turn off the heat and release the pressure immediately.", "Release the pressure immediately by lifting the weight off with a fork.", "Releasing the pressure immediately ensures the greens retain its bright colours.", "Keep aside.Finally to put the saaru together, heat oil in a large saucepan over medium heat; add the mustard seeds, cumin and red chillies and allow the seeds to crackle.", "Add the curry leaves and asafoetida.Stir in the cooked dal and the cooked soppu saaru into the seasoning.", "Give the\u00a0Huli Soppu Saaru\u00a0a stir and bring the Huli Soppu Saaru to a brisk boil for 2 to 3 minutes and turn off the heat.", "Check the salt and adjust according to your taste.", "Transfer the Huli Soppu Saaru to a serving bowl.", "Serve Huli Soppu Saaru Recipe along with Steamed Rice, Udupi Tomato Rasam Recipe, Aralu Sandige Recipe (Puffed Paddy Fryums) and Karnataka Style Beetroot Palya Recipe for a delicious South Indian meal."]'::jsonb, 30, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Huli_Soppu_Saaru_Recipe_Karnataka_Keerai_Sambar_3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/523.Huli_Soppu_Saaru_Recipe_Karnataka_Keerai_Sambar_3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dry Palak Dal Sabzi Recipe', 'dry-palak-dal-sabzi-recipe', 'Dry Palak Dal Sabzi is a perfect side dish for rotis and steamed rice along with a gravy dish. This side dish is very popular in Andhra households and we call this as podi pappu. Half cooked Toor dal and spinach is added to this dal, you can also cook this with moong dal.', '["250 grams Spinach Leaves (Palak)", "1/2 cup Arhar dal (Split Toor Dal)", "1 Onion , finely chopped", "4 Garlic , finely chopped", "2 Fresh Red chillies , chopped", "Salt , as required", "1/2 teaspoon Red Chilli powder", "Oil , as required", "1/4 teaspoon Cumin seeds (Jeera)"]'::jsonb, ARRAY['salt', 'arhar dal (split toor dal)', 'red chillies', 'red chilli powder', 'onion', 'garlic', 'cumin seeds (jeera)', 'spinach leaves (palak)', 'sunflower oil']::text[], '["To begin making the Dry Palak Dal Sabzi, wash and finely chop the spinach and keep it aside.Cook toor dal with half cup of water and make sure water should be in 1:1 ratio and make sure that it is half cooked and not mushy.Heat a wok/kadhai and add oil, cumin seeds, red chillies and garlic cloves.Let the cumin seeds splutter and then add chopped onion and stir for a while.Add spinach, turmeric powder and stir well.", "Add salt and stir again for 5 to 6 minutes.When spinach gets cooked, add toor dal and stir well for 5 minutes.After 5 minutes, add red chilli powder and stir well.", "When dal gets cooked, add garam masala and stir for few minutes and switch off the flame.Serve Dry Palak Dal Sabzi with Steamed Rice,\u00a0Phulka\u00a0or\u00a0Whole Wheat Lachha Paratha."]'::jsonb, 40, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/SHAILAJA_SEN/Palak_sookhi_dal_ki_subji.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/524.Palak_sookhi_dal_ki_subji.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Style Basanti Pulao Recipe', 'bengali-style-basanti-pulao-recipe', 'Bengali Style Basanti Pulao Recipe is made from a heady fragrance of Gobindobhog that is soaked in turmeric to a get a golden touch. An overload of cashews, raisins and a hint of perfume of whole spices makes this a heaven for rice lovers. Rice is been a comfort food for generations and this is a nice and lovely recipe that you will want to indulge in, time and again.', '["2 cups Govind Bhog Rice , cleaned, washed", "20 Cashew nuts", "20 Sultana Raisins", "2 inch Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "2 Cloves (Laung)", "2 Bay leaves (tej patta)", "2 teaspoons Turmeric powder (Haldi)", "2 teaspoons Ginger , grated", "1 tablespoon Sugar", "2 tablespoons Ghee", "1 tablespoon Oil"]'::jsonb, ARRAY['cashew nuts', 'ginger', 'bay leaves (tej patta)', 'cardamom (elaichi) podsseeds', 'ghee', 'raisins', 'sugar', 'cinnamon stick (dalchini)', 'govind bhog rice', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making Bengali Style Basanti Pulao Recipe, smear the gobindobhog rice with turmeric and keep aside for 20 minutes for the rice to absorb the gorgeous yellow.Heat a tablespoon each of ghee and vegetable oil in deep fry pan.", "On low heat, fry the cashewnuts and raisins till they turn golden brown, keep aside.In the same oil, on low medium heat, add the bay leaves, crushed cinnamon, green cardamom, cloves, saute till the spices start to release their aroma.Add the ginger paste and saute for a minute or two; just about till the raw smell of ginger vanishes.Now add the rice and give a gentle stir, taking care not to break the grains.", "Saute gently for 3-5 minutes over a medium flame.Add 4 cups of warm water (golden rule - rice and water should always be in a 1:2 ratio), add sugar and salt to taste.Throw in the fried cashew nuts and raisins.", "Cover and cook till almost all the water has been absorbed, by time the rice should be almost done.Switch off the flame, add the remaining ghee, cover and allow to rest for a further 10-12 minutes.", "The Basanti Pulao is ready.Serve\u00a0Bengali Style Basanti Pulao Recipe along with\u00a0Lauki Raita Recipe\u00a0and\u00a0Kumro Patai Ilish Paturi Recipe.", "To end the meal on a sweet note serve it with\u00a0Rasgulla Recipe."]'::jsonb, 50, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/maumita.paulghosh-gmail.com/Basanti_Pulao_Pulao_Bengali_style.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/525.Basanti_Pulao_Pulao_Bengali_style.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kollu Puli Kuzhambu Recipe - Horsegram In A Tangy Gravy', 'kollu-puli-kuzhambu-recipe-horsegram-in-a-tangy-gravy', 'Kollu Puli Kuzhambu, is a horse gram recipe which is traditionally made in an earthenware pot. Shallots added to the gravy gives a unique flavour and makes it a great dish that can be eaten with a variety of other  dishes.', '["100 grams Horse Gram Dal (Kollu/ Kulith)", "200 grams Shallots , 100 grams for chutney + 100 for the Kuzhambu", "1 Tomato", "1/2 cup Fresh coconut , grated", "2 tablespoons Coriander (Dhania) Seeds", "10 Dry Red Chillies , 5 for the chutney + 5 for the Kuzhambu", "5 cloves Garlic", "2 sprig Curry leaves", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Whole Black Peppercorns", "Salt , according to your taste", "1/2 teaspoon Asafoetida (hing)", "1/2 teaspoon Turmeric powder (Haldi)", "2 cups Tamarind Water", "3 teaspoons Gingelly oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)"]'::jsonb, ARRAY['tomato', 'salt', 'tamarind water', 'coconut', 'asafoetida (hing)', 'mustard seeds', 'dry red chillies the chutney the kuzhambu', 'cloves garlic', 'black peppercorns', 'curry leaves', 'ssfor chutney the kuzhambu', 'coriander (dhania) seeds', 'gingelly oil', 'cumin seeds (jeera)', 'horse gram dal (kollu kulith)', 'turmeric powder']::text[], '["To begin making the Kollu Puli Kuzhambu, soak horse gram dal in a sufficient amount of water for a couple of hours.", "After 2 hours, pressure cook horse gram along with 1 chopped tomato, salt and the required water.Pressure cook for 4 whistles, turn the heat to low and simmer for 20 minutes.", "Turn off the heat, allow the pressure to release naturally.", "Once the pressure has released naturally, open the pressure cooker and drain the horse gram and set aside.", "Reserve the water for the gravy.", "Place a heavy bottomed pan on low heat and add 1 teaspoon oil.", "Once the oil is hot, add peppercorns, cumin seeds, coriander seeds and 5 dry red chillies.", "Roast all the ingredients for 4 to 6 minutes, until you can smell the aroma of the spices.", "Once they are roasted, add few curry leaves, peeled shallots, grated coconut, garlic and continue to saute till the onions become soft.", "Add in the cooked horse gram with tomato.", "Stir all the ingredients well and turn off the flame.", "Allow the ingredients to cool and grind to chutney consistency with adequate salt.Kollu chutney or horse gram chutney is ready.", "The process of making this to a puli kuzhambu starts from here.", "This chutney is the base for the\u00a0Puli Kuzhambu.", "To make the Puli Kuzhambu, in a bowl, add the prepared tamarind water, the ground kollu tomato chutney along with the water it was cooked in.", "The kuzhambu should be thin.Slice the remaining shallots and break the remaining chillies into pieces.", "In an earthenware pot, add 2 teaspoon of oil and add the shallots, broken red chillies, turmeric powder and asafoetida.Alternatively if you do not have an earthenware pot, use can make it in a saucepan.", "Once the onion turns pink, add the tamarind horse gram kuzhambu mixture and simmer for 15 minutes till the gravy thickens and raw smell of tamarind goes.", "Meanwhile in a tadka or tempering pan, add a teaspoon of oil.", "Once the oil is hot, add mustard seeds.", "Add 2 finely chopped shallots and fry till they are golden brown.", "Now add the curry leaves and turn off the tadka pan.Pour the tempering over the Kollu Puli Kuzhambu and turn off the heat.", "Your tangy Kollu Puli Kuzhambu is ready to be served.", "Serve\u00a0Kollu Puli Kuzhambu\u00a0along with hot\u00a0Steamed Rice,\u00a0Carrot Poriyal\u00a0and\u00a0Elai Vadam\u00a0for a comforting weekday lunch.You can also serve Kollu Puli Kuzhambu along with Ragi Mudde for a super healthy lunch for Diabetics."]'::jsonb, 80, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/subadiab-gmail.com/Kollu_puli_kuzhambu_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/526.Kollu_puli_kuzhambu_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Murungai Keerai Adai Recipe - Drumstick Leaves Adai | Lentil Crepes', 'murungai-keerai-adai-recipe-drumstick-leaves-adai-lentil-crepes', 'Murungai Keerai Drumstick Leaves Adai is a crepe that is made from the combination of at least two lentils and rice. Traditionally considered as a tiffin dish can be had for breakfast or dinner. A variety of vegetables can be added like chopped cabbage, grated carrots, spinach. But the most favorite combination is the adai made from drumstick leaves also called as the Murungai Keerai.', '["1/2 cup Rice", "1/4 cup Green Moong Dal (Whole)", "1/2 cup Arhar dal (Split Toor Dal)", "1/2 cup Chana dal (Bengal Gram Dal)", "6 Dry Red Chillies", "2 cups Drumstick Leaves (Moringa/Murungai Keerai) , roughly chopped", "1 sprig Curry leaves , finely chopped", "1/2 teaspoon Asafoetida (hing)", "1 cup Pearl onions (Sambar Onions) , finely chopped", "Salt , to taste", "Oil"]'::jsonb, ARRAY['rice', 'green moong dal', 'whole', 'arhar dal', 'split toor dal', 'chana dal', 'bengal gram dal', 'dry red chillies', 's drumstick leaves', 'moringa/murungai keerai', 'curry leaves', 'asafoetida', 'hing', 'pearl onions', 'sambar onions', 'salt', 'oil']::text[], '["To begin making the Murungai Keerai Adai Recipe (Drumstick Leaves Adai), soak the rice and lentils dal together in enough water such that they get well immersed; for about 5 hours.Grind the soaked rice and dal along with red chillies and curry leaves into a batter; adding only little water at a time when grinding to make a thick batter.", "The batter should not be too watery and once ground the batter will have a coarse texture.Once the batter is ready, add the chopped\u00a0Drumstick Leaves onions, salt and asafoetida and stir to combine well.", "For making the adai; heat the skillet on medium heat.", "Pour a ladleful of adai batter over the skillet and spread the batter evenly using a spiral motion from inside out.Pour a teaspoon of oil or ghee around the edges of the adai.", "Increase the heat and cook for couple of minutes until the bottom of the adai starts to turn golden brown.", "Flip on to the other side to cook for a few seconds.The Adai is thicker than dosa or cheela.", "If you like it thinner, you could add a little water and thin in down a bit and spread.After both sides are cooked remove from skillet and serve hot with butter and jaggery.", "You can also serve the\u00a0Murungai Keerai Adai\u00a0along with Kerala Style Aviall and Puli Inji."]'::jsonb, 220, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breakfast_Tiffins/Murungai_Keerai_Drum_Stick_Leaves_Adai_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/527.Murungai_Keerai_Drum_Stick_Leaves_Adai_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mughlai Style Chicken Haleem Recipe', 'mughlai-style-chicken-haleem-recipe', 'Haleem is a Mughlai recipe popular in Hyderabad. Haleem is usually made from lamb/mutton with chana dal and broken wheat. This recipe of the Mughlai Style Chicken Haleem Recipe has chicken as the main ingredient along with chana dal. you can also try the same one pot dish recipe with various dals like toor dal or masoor dal and with added oats.', '["300 grams Boneless chicken", "3 tablespoon Chana dal (Bengal Gram Dal)", "1 tablespoon Rice", "3 tablespoon Broken Wheat (Dalia/ Godumai Rava)", "1 Bay leaf (tej patta)", "4 Onions , sliced", "1 teaspoon Ginger Garlic Paste", "3 Green Chillies", "2-1/2 tablespoons Red Chilli powder", "Salt , to taste", "2 tablespoon Mint Leaves (Pudina) , chopped", "2 tablespoon Coriander (Dhania) Leaves , chopped", "1 tablespoon Oil", "3 tablespoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Ajwain (Carom seeds)", "1 tablespoon Whole Black Peppercorns", "1 inch Cinnamon Stick (Dalchini)", "3 Cardamom (Elaichi) Pods/Seeds", "2 Black cardamom (Badi Elaichi)"]'::jsonb, ARRAY['green chillies', 'wheat (dalia godumai rava)', 'boneless chicken', 'salt', 'black cardamom (badi elaichi)', 'rice', 'bay leaf (tej patta)', 'coriander (dhania) leaves', 'ghee', 'ajwain (carom seeds)', 'cardamom (elaichi) podsseeds', 'red chilli powder', 'black peppercorns', 'ginger garlic paste', 'onion', 'cumin seeds (jeera)', 'cinnamon stick (dalchini)', 'mint leaves (pudina)', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To prepare Mughlai Style Chicken Haleem Recipe, dry roast all the spices mentioned under masala list.", "Grind it into fine powder.", "Keep aside.Soak chana dal, broken wheat, rice separately.In a saucepot add oil.", "Add sliced onions, ginger garlic paste, green chilies saut\u00e9 until onions turn brown.", "Remove from stove and keep aside.Add 3 cups water into the same pan.", "Add chicken pieces, salt and red chili powder.", "Cover and bring it to rolling\u00a0boil.Once chicken changes color, add the soaked dal, broken wheat and rice.", "Cover and cook.", "Once the\u00a0chicken is cooked, remove the bay leaf.Start mashing the chicken and dal once chicken gets cooked.", "Continue mashing and cooking until all the chicken is fully mashed along with dal.", "Keep adding a\u00a0little water as and when required.Now add the sauteed onion-ginger garlic-green chilies mix along with roasted spices.", "Add salt to taste and continue to cook and mash.Once the haleem turns thick and all ingredients are well mashed, add ghee and mix again.Transfer the Mughlai Style Chicken Haleem Recipe to serving bowl, garnish with caramelized onions, fresh coriander leaves and some ghee on top.", "Serve Mughlai Style Chicken Haleem Recipe topped with caramelized onions and serve as a main course meal with\u00a0Mutton Keema Samosa Recipe."]'::jsonb, 50, 'Mughlai', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/mughlai-style-chicken-haleem-recipe-edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/528.mughlai-style-chicken-haleem-recipe-edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mughlai Style Chicken Haleem Recipe', 'mughlai-style-chicken-haleem-recipe-2', 'Haleem is a Mughlai recipe popular in Hyderabad. Haleem is usually made from lamb/mutton with chana dal and broken wheat. This recipe of the Mughlai Style Chicken Haleem Recipe has chicken as the main ingredient along with chana dal. you can also try the same one pot dish recipe with various dals like toor dal or masoor dal and with added oats.', '["300 grams Boneless chicken", "3 tablespoon Chana dal (Bengal Gram Dal)", "1 tablespoon Rice", "3 tablespoon Broken Wheat (Dalia/ Godumai Rava)", "1 Bay leaf (tej patta)", "4 Onions , sliced", "1 teaspoon Ginger Garlic Paste", "3 Green Chillies", "2-1/2 tablespoons Red Chilli powder", "Salt , to taste", "2 tablespoon Mint Leaves (Pudina) , chopped", "2 tablespoon Coriander (Dhania) Leaves , chopped", "1 tablespoon Oil", "3 tablespoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Ajwain (Carom seeds)", "1 tablespoon Whole Black Peppercorns", "1 inch Cinnamon Stick (Dalchini)", "3 Cardamom (Elaichi) Pods/Seeds", "2 Black cardamom (Badi Elaichi)"]'::jsonb, ARRAY['green chillies', 'wheat (dalia godumai rava)', 'boneless chicken', 'salt', 'black cardamom (badi elaichi)', 'rice', 'bay leaf (tej patta)', 'coriander (dhania) leaves', 'ghee', 'ajwain (carom seeds)', 'cardamom (elaichi) podsseeds', 'red chilli powder', 'black peppercorns', 'ginger garlic paste', 'onion', 'cumin seeds (jeera)', 'cinnamon stick (dalchini)', 'mint leaves (pudina)', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To prepare Mughlai Style Chicken Haleem Recipe, dry roast all the spices mentioned under masala list.", "Grind it into fine powder.", "Keep aside.Soak chana dal, broken wheat, rice separately.In a saucepot add oil.", "Add sliced onions, ginger garlic paste, green chilies saut\u00e9 until onions turn brown.", "Remove from stove and keep aside.Add 3 cups water into the same pan.", "Add chicken pieces, salt and red chili powder.", "Cover and bring it to rolling\u00a0boil.Once chicken changes color, add the soaked dal, broken wheat and rice.", "Cover and cook.", "Once the\u00a0chicken is cooked, remove the bay leaf.Start mashing the chicken and dal once chicken gets cooked.", "Continue mashing and cooking until all the chicken is fully mashed along with dal.", "Keep adding a\u00a0little water as and when required.Now add the sauteed onion-ginger garlic-green chilies mix along with roasted spices.", "Add salt to taste and continue to cook and mash.Once the haleem turns thick and all ingredients are well mashed, add ghee and mix again.Transfer the Mughlai Style Chicken Haleem Recipe to serving bowl, garnish with caramelized onions, fresh coriander leaves and some ghee on top.", "Serve Mughlai Style Chicken Haleem Recipe topped with caramelized onions and serve as a main course meal with\u00a0Mutton Keema Samosa Recipe."]'::jsonb, 50, 'Mughlai', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/mughlai-style-chicken-haleem-recipe-edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/529.mughlai-style-chicken-haleem-recipe-edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Style Kanch kolar Kofta Curry Recipe (Green Plantain Kofta Curry Recipe)', 'bengali-style-kanch-kolar-kofta-curry-recipe-green-plantain-kofta-curry-recipe', 'Bengali Style Kanch kolar Kofta Curry Recipe (Green Plantain Kofta Curry Recipe) is all time favorite Bengali dish made with soft and crispy Koftas dipped in thin and tangy based curry. The Raw banana is rich source of vitamins, minerals, and fiber.  The starch content present in raw banana will help in controlling blood sugar level and manage cholesterol.', '["1 Raw Banana", "2 Potatoes (Aloo) , boiled", "1 teaspoon Turmeric powder (Haldi)", "2 teaspoon Panch Phoran Masala", "2 teaspoon Red Chilli powder", "1 Tomato", "1 inch Ginger , grated", "2 Green Chillies , finely chopped", "2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Sugar", "1 teaspoon Turmeric powder (Haldi)", "2 teaspoon Cumin powder (Jeera)", "1 teaspoon Garam masala powder", "1/2 teaspoon Red Chilli powder", "2 Bay leaf (tej patta)", "2 sprig Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['tomato', 'green chillies', 'cumin powder (jeera)', 'ginger', 'bay leaf (tej patta)', 'red chilli powder', 'sugar', 'coriander (dhania) leaves', 'cumin seeds (jeera)', 'panch phoran masala', 'potato (aloo)', 'turmeric powder', 'banana', 'garam masala powder']::text[], '["We begin making the Bengali Style Kanch kolar Kofta Curry Recipe (Green Plantain Kofta Curry Recipe) by boiling the peeled raw banana and potatoes in a pressure cooker for 4 whistles and release the pressure naturally.In the mean while heat the pan with oil and saut\u00e9 the tomatoes till it is soft and mushy.", "Add salt and sprinkle little sugar to reduce the tanginess.", "Then let it cool down and grind the tomato into a puree consistency.Once the potatoes and raw bananas are cooked, smash it along with the all the masala powders and make it into a ball.", "Pan Fry them on the Kuzi Paniyaram Pan till it is brown evenly.", "Keep it aside.Heat a kadai with oil, add bay leaf and crackle cumin seeds, then add the tomato puree, add in all the spice powders mentioned in the gravy list.", "Add 1 cup of water and let it boil for about 15 minutes.Once it thickens slightly add in the koftas and sprinkle with chopped coriander seeds.", "Serve the Bengali Style\u00a0Kanch\u00a0kolar\u00a0Kofta Curry Recipe (Green Plantain Kofta Curry Recipe) with hot\u00a0Phulkas\u00a0and steam rice."]'::jsonb, 40, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Bengali_Style_Kanch_kolar_Kofta_Curry_Recipe_Green_Plantain_Kofta_Curry_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/530.Bengali_Style_Kanch_kolar_Kofta_Curry_Recipe_Green_Plantain_Kofta_Curry_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Style French Beans Foogath Recipe', 'goan-style-french-beans-foogath-recipe', 'Today’s post ''French Beans Foogath Recipe'' is one comforting dish made from steamed french beans and lentils, that is very popular in Goa. This mildly spiced french beans curry tastes perfect with roti/hot rice accompanied with some Dal. Do try this easy and healthy dish and we are sure you will like it.', '["250 grams Green beans (French Beans) , cut into 1/2 inch pieces, or as desired", "1 Onion , sliced", "2 Green Chillies , slit", "3 tablespoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "8 Curry leaves", "2 Kashmiri dry red chillies , broken", "3 tablespoon Fresh coconut , grated", "1 teaspoon Salt", "Sugar , a pinch"]'::jsonb, ARRAY['salt', 'green beans (french beans)', 'mustard seeds', 'coconut', 'kashmiri dry red chillies', 'curry leaves', 'sugar', 'onion', 'cumin seeds (jeera)', 'green chillies', 'sunflower oil']::text[], '["To begin making the Goan Style French Beans Foogath Recipe, wash the french beans, remove the string and chop them into 1/2 inch piece.Heat oil in a heavy bottomed pan.", "Add mustard seeds, cumin seeds, curry leaves, dry red chillies and green chillies.", "Saute for about 1 to 2 minutes.After 1 to 2 minutes, add onions.", "Saute for 3 to 4 minutes till onion turns translucent.", "Then add beans, salt and a pinch of sugar.", "Saute.Add around 1/4 cup of water, cover and cook for 8 to 10 minutes.", "Don''t over cook to maintain the crunchiness.When beans is cooked, finally add grated coconut, toss and switch off.", "Goan Style French beans foogath is ready to relish.Serve\u00a0Goan Style French Beans Foogath\u00a0Recipe along with\u00a0Tomato Onion Sambar\u00a0and\u00a0Steamed Rice\u00a0with a dollop of ghee."]'::jsonb, 25, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/Goan_Style_French_beans_foogath_recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/531.Goan_Style_French_beans_foogath_recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Besan Arbi Roast Recipe - Spicy Colocasia Stir Fry', 'besan-arbi-roast-recipe-spicy-colocasia-stir-fry', 'Arbi is Colocasia or Taro Root. It’s a root vegetable which is gluten free and is rich in antioxidants, dietary fiber, minerals, vitamins. You can make it into a curry or in a stir fry. The arbi curry tastes delicious with rotis and puris. Arbi fry/roast makes a very good appetizer or starter, or can even be served as side dish for rajma chawal, dal-chawal or rasam rice.', '["250 grams Colocasia root (Arbi)", "2 tablespoon Gram flour (besan)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Amchur (Dry Mango Powder)", "3/4 teaspoon Cumin powder (Jeera)", "Salt , to taste", "1/4 teaspoon Asafoetida (hing)", "3 tablespoons Oil", "1 teaspoon Oil", "1/2 teaspoon Ajwain (Carom seeds)", "1/4 teaspoon Cumin seeds (Jeera)", "1 Green Chilli , finely chopped", "2 teaspoons Lemon juice", "1 sprig Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'green chilli', 'amchur (dry mango powder)', 'asafoetida (hing)', 'ajwain (carom seeds)', 'red chilli powder', 'gram flour (besan)', 'coriander (dhania) leaves', 'colocasia root (arbi)', 'cumin seeds (jeera)', 'lemon', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Besan Arbi Roast Recipe, scrub the arbi to get rid of mud and dirt.", "Pressure cook the arbi with little water and a pinch of salt for 1 whistle (do not over cook).", "After the first whistle, turn off the heat.", "Once the pressure releases, open the cooker.", "Peel the skin off and cut them into half lengthwise and place it in a large mixing bowl.In a wide plate mix besan, red chili powder, coriander powder, salt, turmeric powder, amchur powder, roasted cumin powder.Add this spice powder like the turmeric powder, coriander powder, red chilli powder, amchur powder and cumin powder to the cut\u00a0arbi and toss to coat well.", "Heat 2 tablespoons of oil in a heavy bottomed pan, add the besan arbi in small batches and roast until golden brown in color on all sides.", "Do this in 2 to 3 batches, add oil as the pan gets dry.", "Drain the roasted arbi on kitchen towel and place it in a serving platter.In another pan add 1 teaspoon of oil.", "Add cumin seeds, carom seeds and finely chopped green chilies and saute for 10 seconds.", "Add this to the Besan Arbi and toss gently.", "Sprinkle some coriander leaves and lemon juice on top of the besan arbi and serve.Serve\u00a0Besan Arbi Roast Recipe\u00a0with\u00a0Dal Palak Recipe\u00a0and\u00a0Steamed Rice Recipe - Pressure Cooker & Sauce Pan Methods\u00a0for lunch."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Besan_Arbi_Fry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/532.Besan_Arbi_Fry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Stuffed Mooli Paneer Paratha Recipe', 'stuffed-mooli-paneer-paratha-recipe', 'A delicious paratha recipe,  Stuffed Mooli Paneer Paratha, has a stuffing of radish and cottage cheese seasoned with salt and cumin powder. The addition of ginger-garlic-green chilli in the filling gives the paratha a lovely flavour.', '["2 Mooli/ Mullangi (Radish) , washed and grated", "200 grams Paneer (Homemade Cottage Cheese) , grated", "1 Green Chilli , finely chopped", "4 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "1 teaspoon Cumin powder (Jeera)", "2 teaspoon Oil", "Salt , to taste", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera)", "1 cup Whole Wheat Flour", "Ghee , to cook the parathas"]'::jsonb, ARRAY['mooli/ mullangi', 'radish', 's paneer', 'homemade cottage cheese', 'reen chilli', 's garlic', 'ginger', 'cumin powder', 'jeera', 'oil', 'salt', 'turmeric powder', 'haldi', 'whole wheat flour', 'ghee']::text[], '["To begin making the Stuffed Mooli Paneer Paratha Recipe, grate the paneer and radish and set aside.\u00a0*To make the Mooli Paneer Filling\u00a0Heat a skillet on medium flame, add 1 teaspoon oil, now add the cumin seeds, chopped ginger and garlic, saute for 30 seconds, now add the radish, salt and continue to saute on high heat till all the moisture from radish evaporates.Turn off the flame.", "Transfer the mixture into a mixing bowl.", "Into that mixing bowl, add grated paneer, green chili, cumin powder and mix well.", "The stuffing of the\u00a0Mooli Paneer Paratha is ready.\u00a0*To make the\u00a0Stuffed Mooli Paneer ParathaIn a mixing bowl, add the whole wheat flour to amke the dough by adding little water at a time and knead well to make a smooth dough.", "Divide the dough into equal portions.Dust a flat working surface with some flour.", "Roll a portion into a ball and flatten it using your fingers and roll it out into a 3 inch diameter circle.Place about 2 tablespoons of the\u00a0Mooli Paneer stuffing in the center, gather the edge and seal it.", "Carefully roll it out into a circle about 6-7 inches in diameter.Heat a skillet over medium heat and cook the stuffed mooli paneer paratha with ghee until cooked through, and has golden brown spots on both sides.Repeat with the remaining portions of the dough.", "Serve this\u00a0Stuffed Mooli Paneer Paratha\u00a0along with\u00a0Lehsuni Pudina Chutney Recipe\u00a0or\u00a0Instant Gor Kairi Lonche Recipe\u00a0or\u00a0Carrot Tadka Raita Recipe\u00a0and\u00a0Adrak Chai Recipe - Indian Style Ginger Tea\u00a0for a simple weekday breakfast."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sneha-archanaskitchen.com/Stuffed_Mooli_Paneer_Paratha__1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/533.Stuffed_Mooli_Paneer_Paratha__1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ullikadala Pulusu Recipe | Spring Onion Curry', 'ullikadala-pulusu-recipe-spring-onion-curry', 'Ullikadala Pulusu Recipe is a spring onion curry that comes from the Telugu region. This is a very easy to prepare side dish recipe and can even be made on any weekday or for special occasions. Make this south Indian style Ullikadala Pulusu Recipe | Spring Onion Curry on a winter day and serve with hot steamed rice and ghee, along with Andhra Gongura Pachadi Recipe, and Andhra Style Kakarakaya Vepudu Recipe (Bitter Gourd Stir Fry).', '["150 grams Spring Onion (Bulb & Greens) , chopped", "3/4 cup Tamarind Water", "1 tablespoon Gram flour (besan)", "2 teaspoons Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies", "1 pinch Asafoetida (hing)", "1 pinch Turmeric powder (Haldi)", "Salt , to atste", "2 teaspoons Coriander (Dhania) Seeds", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "2 cups Water"]'::jsonb, ARRAY['salt', 'tamarind water', 'mustard seeds', 'asafoetida (hing)', 'water', 'gram flour (besan)', 'spring onion (bulb greens)', 'dry red chillies', 'coriander (dhania) seeds', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making Ullikadala Pulusu Recipe | Spring Onion Curry, in a pan, dry roast coriander seeds, mustard seeds, cumin seeds, fenugreek seeds separately and grind into a fine powder.", "Keep aside once they are roasted till aromatic.In the same pan, add oil, once it is hot on medium low heat, temper with mustard seeds.", "Once they splutter, add cumin seeds, red chillies, hing and add spring onions (white part+green part) cut into small pieces.", "Fry until they turn soft and reduce in size on a low heat.Add about 2 cups of water and bring to boil.", "Add salt, turmeric, tamarind puree and let it boil for about 2 minutes.", "In a bowl, mix gramflour and a tablespoon of prepared powder with little water without lumps and add to the boiling mixture.", "Let it boil for another 2 to 3 minutes and serve.", "Serve Ullikadala Pulusu Recipe | Spring Onion Curry on a winter day and serve with hot steamed rice and ghee, along with\u00a0Andhra Gongura Pachadi Recipe, and\u00a0Andhra Style Kakarakaya Vepudu Recipe (Bitter Gourd Stir Fry)."]'::jsonb, 15, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/anu.mallajosyula-gmail.com/Ullikadala_Pulusu_Spring_Onion_pulusu.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/534.Ullikadala_Pulusu_Spring_Onion_pulusu.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharashtrian Takatla Palak Recipe - Spinach Peanut Buttermilk Curry', 'maharashtrian-takatla-palak-recipe-spinach-peanut-buttermilk-curry', 'Takatla Palak Recipe is a delicious Maharashtrian recipe where spinach (palak) is cooked in a buttermilk gravy along with peanuts and chana dal lending to a delicious taste. This simple, slightly tangy curry served with rice is comforting not only in the hot summer months but all year round. Adjust the consistency of the curry to your liking. If it is served with rice, it usually has a thin soup like consistency or can be made thicker when it is to be served with chapati.', '["200 grams Spinach Leaves (Palak) , finely chopped", "3 tablespoons Chana dal (Bengal Gram Dal) , soaked in hot water for 15 minutes", "1/4 cup Raw Peanuts (Moongphali)", "1/2 cup Curd (Dahi / Yogurt)", "2 tablespoons Gram flour (besan)", "1 teaspoon Ghee", "3 cloves Garlic , crushed", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoons Cumin seeds (Jeera)", "3 Green Chillies , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Asafoetida (hing)", "1/2 teaspoon Jaggery", "Salt , to taste"]'::jsonb, ARRAY['s spinach leaves', 'palak', 's chana dal', 'bengal gram dal', 'raw peanuts', 'moongphali', 'curd', 'dahi / yogurt', 's gram flour', 'besan', 'ghee', 's garlic', 'mustard seeds', 'rai/ kadugu', 's cumin seeds', 'jeera', 'reen chillies', 'turmeric powder', 'haldi', 'asafoetida', 'hing', 'jaggery', 'salt']::text[], '["To begin making the\u00a0Maharashtrian Takatla Palak Recipe, first prep all the ingredients and keep ready.In a mixing bowl, whisk together the yogurt, gram flour and 1/2 cup of water.", "Keep aside.Soak the chana dal in hot water for 15 minutes.Into the pressure cooker, add the chopped spinach leaves and cook for one whistle and turn off the heat.", "Release the pressure immediately, so the spinach remains green.", "Keep aside.Pressure cook the soaked chana dal and raw peanuts with 1/2 cup of water for about 3 to 4 whistles and turn off the heat.", "Allow the pressure to release naturally.", "Heat ghee in a pan over medium heat.", "Add the mustard seeds and cumin seeds and allow it to crackle.", "Stir in the garlic, asafoetida, turmeric, chillies and stir for a few seconds.Stir in the cooked spinach, the chana dal, the peanuts and the yogurt gram flour mixture.", "Add salt and little jaggery to taste and give the Takatla Palak\u00a0a brisk boil, until it thickens a bit.", "Once done, check the salt and seasonings and adjust to suit your taste.Turn off the heat, transfer the Takatla Palak Recipe to a serving bowl and serve hot.Serve the\u00a0Takatla Palak Recipe along with hot\u00a0Steamed Rice,\u00a0Maharashtrian Batatyacha Kees Recipe\u00a0and\u00a0Kosambari Salad\u00a0for a weeknight dinner or a sunday lunch."]'::jsonb, 50, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Maharashtrian_Style_Takatla_Palak_Recipe_Palak_Khadi_with_Peanuts_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/535.Maharashtrian_Style_Takatla_Palak_Recipe_Palak_Khadi_with_Peanuts_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bhogichi Bhaji Recipe - Maharashtrian Mixed Vegetable Sabzi', 'bhogichi-bhaji-recipe-maharashtrian-mixed-vegetable-sabzi', 'Bhogichi Bhaji Recipe is a Maharashtrian delicacy where mixed vegetables are simmered and cooked in goda masala and peanut sesame powder. Has a rich and yet nutty taste perfect to go along with a Takalaka Palak, hot Bhakri and steamed rice topped with ghee.', '["2 Carrots (Gajjar) , red, peeled and diced", "1 Potato (Aloo) , peeled and diced", "3 Brinjal (Baingan / Eggplant) , stalks removed and diced", "1/2 cup Green peas (Matar) , or fresh green chana", "10 Avarekai (Broad Beans) , strings removed and cut.", "5 Ber , washed and stems removed (optional)", "2 Green Chillies , finely chopped", "1 tablespoon Oil", "1 teaspoon Maharashtrian Goda Masala", "1/2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1/4 cup Roasted Peanuts (Moongphali)", "1/4 cup Sesame seeds (Til seeds)", "Ingredients for garnishing", "Coriander (Dhania) Leaves , Handful, finely chopped", "1 teaspoon Lemon juice"]'::jsonb, ARRAY['carrots', 'gajjar', 'potato', 'aloo', 'brinjal', 'baingan / eggplant', 'green peas', 'matar', 'avarekai', 'broad beans', 'ber', 'reen chillies', 'oil', 'maharashtrian goda masala', 'cumin seeds', 'jeera', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing', 'turmeric powder', 'haldi', 'salt', 'roasted peanuts', 'moongphali', 'sesame seeds', 'til seeds', 'ingredients for garnishing', 'coriander', 'dhania', 'lemon juice']::text[], '["To begin making Bhogichi Bhaji, prep all the ingredients and keep them ready.In a small pan; add the peanuts and roast until it is golden and crisp.", "Keep aside.", "In the same pan; roast the sesame seeds until it starts to crackle and keep aside.", "Once the peanuts and sesame have cooled, blend to make a powder and keep aside.", "Heat a tablespoon of oil in a wok over medium heat.", "Add the mustard and cumin seeds and allow them to crackle.Once they crackle, add the green chilies, hing, goda masala and turmeric powder.", "Allow the spices to roast for about a few seconds.", "Be careful not to burn the spices.Add the potatoes, brinjals, carrots and chopped flat beans.", "Saute the vegetables and let them blend with the spices and masala.", "Add salt to taste, sprinkle some water, mix and cook covered for 10-12 minutes, till the vegetables are half almost cooked.Add the fresh green peas and cook covered till the vegetables are completely cooked through.", "Add 1-2 tablespoon water if required, so that the vegetables do not burn the bottom of the pan.", "The water creates steam that will help the Bhogichi Bhaji to cook faster.When the vegetables are almost done add the Ber, sesame and peanut powder and stir well to combine.", "Cook the Bhogichi Bhaji uncovered for a couple of more minutes.", "Check the salt and spice at this stage and adjust to suit your taste.Finally, garnish the\u00a0Bhogichi Bhaji with fresh chopped coriander leaves and lime juice and transfer to a serving bowl.Serve Bhogichi Bhaji\u00a0with\u00a0Multigrain Bhakri\u00a0or\u00a0Bajra Til Bhakri\u00a0with a dollop of fresh homemade ghee or butter on top.", "Plan your lunch or dinner menu with this recipe and enjoy the goodness of the seasonal produce."]'::jsonb, 50, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Bhogichi_Bhaji_Recipe_Maharashtrian_Mixed_Vegetable_Stir_Fry_Bhogichi_Bhaji_Recipe_Maharashtrian_Mixed_Vegetable_Stir_Fry__2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/536.Bhogichi_Bhaji_Recipe_Maharashtrian_Mixed_Vegetable_Stir_Fry_Bhogichi_Bhaji_Recipe_Maharashtrian_Mixed_Vegetable_Stir_Fry__2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vazhakkai Podimas Recipe (Ayurvedic Recipe With No Onion No Garlic)', 'vazhakkai-podimas-recipe-ayurvedic-recipe-with-no-onion-no-garlic', 'The Vazhakkai Podimas Recipe is a very simple and wholesome Ayurvedic recipe made from raw bananas. This recipe use less oil and has subtle flavors from the asafoetida, roasted urad dal and curry leaves. The addition of lemon is very important to bring out the flavors of the dish.', '["3 Raw Banana", "1 tablespoon Sesame (Gingelly) Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1/2 teaspoon Asafoetida (hing)", "1/2 teaspoon Turmeric powder (Haldi)", "2 sprig Curry leaves", "Salt , to taste", "1/2 teaspoon Lemon juice"]'::jsonb, ARRAY['salt', 'asafoetida (hing)', 'mustard seeds', 'sesame (gingelly) oil', 'curry leaves', 'white urad dal (split)', 'lemon', 'turmeric powder', 'banana']::text[], '["To begin making the Ayurvedic Style Vazhakai Podimas Recipe, first cut the raw banana into half and place it in the pressure cooker.", "Add 1/2 cup water and pressure cook for 3 to 4 whistles.", "Turn off the heat and allow the pressure to release naturally.Once the pressure has released, remove the skin from the banana.Place the peeled Vazhakai (raw banana) in a bowl and using a fork, lightly mash it - it should not be a smooth mash, but should have a few small chunks to add to the texture.", "Keep this aside.", "Ensure you mash it when it is warm.You can also optionally cut it into small pieces.", "In the same pressure cooker, add the raw peanuts, a pinch of salt 1/4 cup of water and pressure cooker for 3 whistles and turn off the heat.", "Allow the pressure to release naturally.Once it is done, take it out in a bowl and keep it aside.", "The final step is to add the tadka.Heat oil in a pan over medium heat; add the mustard seeds and urad dal.", "Allow it to crackle and allow the dal to brown until golden in color.Once the urad dal is browned, add the asafoetida and the curry leaves.After the curry leaves crackle, add in the turmeric powder, the cooked raw banana, peanuts and the salt.", "Stir fry the Vazhakai Podimas over medium heat for 2 to 3 minutes until all the ingredients are well combined.Once done, turn off the heat and stir in the lemon juice.", "Check the salt and adjust to suit your taste.", "Transfer to a serving bowl and serve hot.Serve the Ayurvedic Style Vazhakai Podimas Recipe along with\u00a0Tomato Rasam,\u00a0Steamed Rice\u00a0and\u00a0Kosambari\u00a0for a whole some Ayurvedic lunch."]'::jsonb, 35, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/admin/Vazhakkai_Podimas_Recipe_Ayurvedic_Recipe_With_No_onion_No_Garlic.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/537.Vazhakkai_Podimas_Recipe_Ayurvedic_Recipe_With_No_onion_No_Garlic.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Foxtail and Jowar Millet Paniyaram Recipe', 'foxtail-and-jowar-millet-paniyaram-recipe', 'Foxtail Millet and Jowar Paniyaram Recipe is a healthy way to start your morning. The paniyaram is tasty and delicious as well. The recipe is not too complicated and all you have to do is just keep the batter ready so that you can quickly whip up a breakfast that will be loved by everyone in your family. The batter has an equal proportion of foxtail and jowar grains that is soaked a day ahead and ground. Foxtail millet is the best option for diabetic friendly and jowar millet on the hand contains high in fiber. Both put together helps to create wonders for a healthy start.', '["1/2 cup Foxtail Millet", "1/2 cup Jowar Seeds", "1/4 cup White Urad Dal (Whole)", "2 tablespoons Methi Seeds (Fenugreek Seeds)", "1 Onion , chopped", "1 Green Chilli", "1 inch Ginger , chopped", "5 cloves Garlic , chopped", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves , chopped", "1 sprig Coriander (Dhania) Leaves , chopped", "2 tablespoons Fresh coconut , grated", "Salt , to taste"]'::jsonb, ARRAY['foxtail millet', 'jowar seeds', 'white urad dal', 'whole', 's methi seeds', 'fenugreek seeds', 'onion', 'reen chilli', 'ginger', 's garlic', 'mustard seeds', 'rai/ kadugu', 'split', 'curry leaves', 'coriander', 'dhania', 's fresh coconut', 'salt']::text[], '["To begin making the foxtail and Jowar millet Paniyaram Recipe, soak the grains in water for atleast 8 hours.", "Grind it into a smooth paste by adding little water.", "The batter should not be too thin as well.", "Add a teaspoon of soda and salt and keep it aside.Heat a flat skillet with oil, add mustard seeds and urad dal and allow it splutter for few seconds.Add chopped curry leaves and leave it to crackle, add ginger, garlic and saute until it softens.Once that is done, add onions and saute till they turn translucent.", "Switch off the heat and add coriander leaves and coconut and give it a stir.Add the sauted onion mixture into the batter and mix well and check salt and keep kuzhi paniyaram pan ready to start cooking.Heat Paniyaram pan on low-medium heat.", "Pour 1 teaspoon ghee into each cavity of the pan.", "Spoon the Millet and Jowar Paniyaram batter into the cavities.", "Don''t fill it to the brim, but only 3/4th full.Cover the pan with a lid and cook on low to medium heat for about 3 to 4 minutes until the top of the paniyaram is steamed.", "Once the top looks steamed, flip the Paniyarams over the cook on the other side (without closing the lid) until golden brown.Once each Paniyaram is cooked, remove from the pan and pour another batch of batter and proceed the similar way.Serve the Foxtail and Jowar Millet Paniyaram Recipe along with\u00a0coconut chutney\u00a0or\u00a0tomato and onion chutney\u00a0for breakfast."]'::jsonb, 50, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Millet_and_Jowar_Paniyaram_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/538.Millet_and_Jowar_Paniyaram_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Matar Masala Tofu Recipe', 'matar-masala-tofu-recipe', 'This is a low-fat vegan recipe, extremely delicious to taste for those who have already introduced tofu in their daily diet. For others who already know the important nutritional values of tofu but still thinking how to introduce in the main course then this recipe will help them find a way to balance with native Indian taste.', '["200 grams Tofu", "3/4 cups Homemade tomato puree", "1/4 cup Green peas (Matar)", "1/2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Ginger , paste", "1/8 teaspoon Garam masala powder", "Green peas (Matar) , A handful", "Curry leaves , a few", "1 1/2 cups Water", "3 teaspoon Oil", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'ginger paste', 'red chilli powder', 'green peas (matar)', 'water', 'curry leaves', 'cumin seeds (jeera)', 'tofu', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Matar Masala Tofu Recipe, firstly cut the tofu in cubes.Take a bowl and mix all the dry masala including red chilli powder, turmeric powder, garam masala powder with 1/4th cup of water.", "Keep it aside.Heat a frying pan with 1 teaspoon oil and fry the tofu cubes, then keep it aside.Add rest of the oil in the same pan, temper with cumin seeds, curry leaves,\u00a0ginger and masala paste.", "Fry for a minute.Add the tomato puree, salt and peas, cook for 5 minutes.", "As it starts to thicken add salt and tofu cook for few more minutes.", "Garnish Matar Masala Tofu Recipe with garam masala powder and fresh curry leaves and it is ready to be served.", "Serve\u00a0Matar Masala Tofu Recipe along with\u00a0Whole Wheat Lachha Paratha\u00a0and\u00a0Palak Raita\u00a0for a delicious lunch."]'::jsonb, 20, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/ruby_pathak-yahoo.com/Matar__Masala_Tofu_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/539.Matar__Masala_Tofu_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bharwa Karela Masala Recipe', 'bharwa-karela-masala-recipe', 'Bharwa Karela Masala is a stuffed recipe in which bitter gourd is stuffed with spices and peanuts roasted in oil. The Bharwa karela itself is a dry dish but when coupled with spicy gravy, it makes a delicious accompaniment for rice or akki roti. Bitter gourd is known for its health benefits but the bitter taste which it carries makes it difficult to be eaten by kids and even many adults.', '["2 Karela (Bitter Gourd/ Pavakkai)", "1/2 teaspoon Salt , adjust to taste", "Ingredients For stuffing & gravy", "1/2 cup Raw Peanuts (Moongphali)", "1/2 cup Fresh coconut , grated and roasted", "6 cloves Garlic", "2 teaspoon Cumin seeds (Jeera)", "2 teaspoon Jaggery", "1 teaspoon Turmeric powder (Haldi)", "2 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Cumin powder (Jeera)", "1 tablespoon Tamarind Paste", "1 teaspoon Salt , adjust to taste", "3 teaspoon Oil"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'coconut', 'karela (bitter gourd pavakkai)', 'jaggery', 'red chilli powder', 'cloves garlic', 'cumin seeds (jeera)', 'peanuts (moongphali)', 'tamarind paste', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Bharwa Karela Masala Recipe, wash karela and grate their outer surface with a knife or grater and remove seeds inside.", "Cut them 2 inches long, add salt and leave aside for 10 minutes.You would see that the vegetable would have given some water.", "Squeeze the excess water and wash them completely.", "Doing so will reduce bitterness to a considerate level.", "Slice the gourds half way through so as to facilitate filling inside them.", "Keep aside.In a saucepan, add water and bring it to a boil.", "Cook pieces of karela in boiling water just until the skin becomes tender.", "Avoid overcooking since they need to retain their shape.", "Drain the hot water and allow it to cool down enough to handle.Dry roast peanuts until it turns slightly brown.", "Half of it for is to be used for stuffing and the other half, for gravy.In a kadai, add oil and once the oil is hot, add cumin seeds.", "Fry them until they turn brownish.Add garlic pods and fry them until they turn brownish.In a mixer, add the roasted peanut, roasted coconut, garlic pods, jeera, jaggery, red chili powder, coriander powder, cumin powder, salt and grind them coarsely.", "Do not add waterAdd a teaspoon of oil to the grounded powder and mix them wellStuff half of the spice powders inside the bitter gourd and keep the remaining half to the gravy.In a medium sized frying pan.", "Add remaining oil and heat them over medium heatPlace the stuffed karelas in the pan and roasted until the outer skin turns brownish.In another medium sized pan, add a half teaspoon of oil.", "Once the oil is hot, add the remaining masala\u00a0and saute it for a few minutes.", "Add 1-1/2 cups of water and cook until the gravy thickens a little.Add a little more tamarind paste if you like it to be a little more sour.Cook with lid covered over medium flame until the gravy is reduced and grounded powders are absorbed completely.", "Adjust salt and switch off the flame.", "Pour the gravy over the karelas and serve hot.Serve\u00a0Bharwa Karela Masala\u00a0along with\u00a0Dhaba Style Dal Fry,\u00a0Phulka\u00a0and\u00a0Masala Khichia\u00a0for an everyday meal."]'::jsonb, 70, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Bharva_Karela_Masala.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/540.Bharva_Karela_Masala.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Soft & Delicious Ragi Mudde Recipe - Karnataka Style Ragi Balls', 'soft-delicious-ragi-mudde-recipe-karnataka-style-ragi-balls', 'Ragi Mudde Recipe is an authentic dish of Karnataka. It is most of the staple food for farmers who live in the rural parts of Karnataka. It is always an art to make this at everyone’s house as you need to get the proportion right and even the technique followed by each family will be different.', '["2-1/2 cups Hot water", "1 cup Ragi Flour (Finger Millet/ Nagli)", "2 tablespoons Ghee", "Salt , to taste"]'::jsonb, ARRAY['ragi flour (finger millet nagli)', 'salt', 'water', 'ghee']::text[], '["To begin making the Ragi Mudde Recipe, heat 2-1/2 cups of water in a saucepan and add salt to it.Once it starts to boil, reduce the flame and add 3 tablespoons of ragi flour and whisk till there are no lumps formed and it slowly starts to thicken.Now, add the remaining ragi flour spoon by spoon and keep stirring so that there are no lumps.Make sure the heat is on low and ensure you keep stirring until it thickens completely.", "If you are making a larger quantity, then cover with a lid and leave the ragi aside to cook for about 5 minutes, until you notice it has thickened.Once you notice the ragi has thickened, continue stirring and add 2 tablespoons of ghee and keep stirring until you see the ragi has got a shine on it.", "It takes a good 10 minutes to make ragi mudde from 1 cup of ragi flour.Give the ragi mudde a taste and it should not feel raw.In order to shape ragi mudde to balls, grease a bowl with oil or ghee.", "Place 2 large tablespoons of ragi mudde and\u00a0start twirling it around till it forms a nice smooth ball.", "Once done, the ragi mudde can be served hot.", "Note that the ragi mudde needs to be shaped into a ball while it is hot.", "Using a small bowl, helps in shaping the ragi mudde.Serve the\u00a0Ragi Mudde Recipe\u00a0along with\u00a0Chicken Saaru, or\u00a0Huli Soppu Saaru Recipe\u00a0and\u00a0Sabbasige palya\u00a0to enjoy your lunch.The Ragi Mudde Recipe can also be served for an Indian Diabetic Lunch or dinner along with a\u00a0Sabbasige palya\u00a0and Raita."]'::jsonb, 55, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Ragi_Mudde_Recipe_Video_Karnataka_Style_Finger_Millet_Dumplings_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/541.Ragi_Mudde_Recipe_Video_Karnataka_Style_Finger_Millet_Dumplings_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hyderabadi Bagare Tamatar (Spiced, Tossed Tomato Curry)', 'hyderabadi-bagare-tamatar-spiced-tossed-tomato-curry', 'Hyderabadi Bagare Tamatar is a delicate dish of spiced, tomato tossed together into a silky curry. It is extremely popular and served at Hyderabadi Muslim weddings, as a side dish to the Biryani. It makes a great accompaniment for a Hyderabadi meal, and can also be served with Lachha Parathas or Naans.', '["6 Tomatoes", "2 Onions , finely sliced", "2 teaspoon Khoya (Mawa)", "2 teaspoon Sesame seeds (Til seeds)", "2 teaspoon Raw Peanuts (Moongphali)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Kashmiri Red Chilli Powder", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania) , roasted", "1/2 teaspoon Cumin powder (Jeera) , roasted", "3 Cloves (Laung)", "1 Cinnamon Stick (Dalchini)", "4 cloves Garlic", "1/4 cup Tamarind Paste", "4 tablespoons Oil", "Salt , to taste", "3 Whole Eggs , hard boiled and cut into half"]'::jsonb, ARRAY['tomatoes', 'onions', 'khoya', 'mawa', 'sesame seeds', 'til seeds', 'raw peanuts', 'moongphali', 'red chilli powder', 'kashmiri red chilli powder', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'cumin powder', 'jeera', 'laung', 'cinnamon stick', 'dalchini', 's garlic', 'tamarind paste', 's oil', 'salt', 'whole eggs']::text[], '["To begin making the Hyderabadi Bagare Tamatar first, wash and pat dry the tomatoes.", "Remove the eye off the tomatoes and make X shaped slits at the top.", "Set them aside for later use.Place a heavy bottom pan on the heat.", "When it is warm, dry roast sesame seeds, cloves, cinnamon and peanuts, in separate batches.", "Take them out fo the pan and set them aside to cool.Now in the same pan, add oil and when it gets warm, add sliced onions and saute them till they turn deep golden brown.", "Drain them form the oil using a slotted spoon and set them aside for later use.In the oil that remains in the pan, very gently and carefully toss baby tomatoes on a medium low until the skin of baby tomatoes get scarred and wilted.", "Take them out of the pan and set aside.Now start making masala for the recipe, by grinding roasted peanuts, sesame seeds, cloves and cinnamon stick to fine powder.", "Add 1 tbsp. of water if required, to allow easy grinding.To this add fried onion slices and garlic cloves.", "Grind to smooth paste.In the pan that the tomatoes were tossed, add a little oil if required and pour in the ground masala above.On low flame, toss it.", "Add red chili powder, turmeric powder, salt, roasted coriander powder, roasted cumin powder and Kashmiri red chili powder.Increase the heat to medium and fry till all the ingredients come together.", "Now add mawa to this and fry till oil starts to release from the sides.Now gently drop in above sauteed tomatoes and stir until they get nicely coated with the masala.Reduce the flame and add tamarind juice along with 1\u00bd cups of water.", "Check for salt and allow the curry to simmer until it reaches thick consistency or as desired.If you are using boiled eggs, then drop them now.", "Turn off the flame and leave it covered for 15 minutes.Serve warm as a side dish the\u00a0Biryani\u00a0or\u00a0with\u00a0Lachha Parathas\u00a0or\u00a0Naans."]'::jsonb, 55, 'Hyderabadi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Lubna_Karim/Hyderabadi_Bagare_Tamatar_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/542.Hyderabadi_Bagare_Tamatar_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Classic Andhra Style Chicken Curry Recipe', 'classic-andhra-style-chicken-curry-recipe', 'Classic Andhra Style Chicken Curry Recipe is a delectable recipe that is a speciality from Andhra.', '["To marinate", "600 grams Chicken , cleaned and cut to required size", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Salt", "To grind", "1 inch Ginger", "6 cloves Garlic", "1 inch Cinnamon Stick (Dalchini)", "4 Cloves (Laung)", "1 Cardamom (Elaichi) Pods/Seeds", "2 teaspoon Poppy seeds", "2 tablespoons Dry coconut (kopra)", "1/4 cup Hot water , for grinding", "To season", "2 tablespoons Oil", "1/2 inch Cinnamon Stick (Dalchini)", "3 Cloves (Laung)", "1 Cardamom (Elaichi) Pods/Seeds", "1 Bay leaf (tej patta)", "Other ingredients", "1 Onion , finely chopped", "2 Green Chillies , finely chopped", "1 sprig Curry leaves", "1 teaspoons Red Chilli powder , (Adjust to suit your spice levels)", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , as required", "1/2 teaspoon Garam masala powder", "1/2 cup Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['salt', 'green chillies', 'ginger', 'garam masala powder', 'cardamom (elaichi) podsseeds', 'bay leaf (tej patta)', 'coriander (dhania) leaves', 'red chilli powder', 'cloves garlic', 'dry coconut (kopra)', 'curry leaves', 'cinnamon stick (dalchini)', 'chicken', 'poppy seeds', 'onion', 'turmeric powder', 'cloves (laung)', 'water grinding', 'red chilli powder ( suit spice levels)', 'sunflower oil']::text[], '["To begin making the Classic Andhra Style Chicken Curry recipe, we will first marinate the chickenIn a mixing bowl, combine the chicken along with\u00a0red chilli powder,\u00a0turmeric powder,\u00a0salt\u00a0and set it aside for about 20 minutes.", "In the meantime grind ingredients for the masala.", "In a mixer jar, combine\u00a0the ginger,\u00a0garlic,\u00a0cinnamon stick,\u00a0cloves, cardamom,\u00a0poppy seeds,\u00a0desiccated coconut and grind to a fine paste using water.", "Heat oil in a heavy bottomed pan over medium heat.", "Add in the\u00a0cinnamon stick, cloves,\u00a0cardamom and the bay leaf and allow them to sizzle.", "Now add chopped onions, green chillies and saut\u00e9 till they are slightly brown in colour.", "Add curry leaves.", "Continue to saute for 4-6 minutes until nicely done.", "Add marinated chicken and saut\u00e9 for 2 minutes.", "Next, add the freshly ground masala paste, remaining chilli powder and turmeric powder.", "Now add the required water till the chicken immerses and adjust salt.", "You can adjust the consistency of the gravy to suit your requirement.Close the lid of the pan and cook over medium heat for 10 to 15 minutes with frequent stirring and then simmer for 5 minutes till the chicken is done and oil separates.", "Turn off the heat.This can also be cooked in a pressure cooker for about 3 whistles following the same process.Finally sprinkle garam masala powder and garnish with coriander.", "Serve Classic Andhra Style Chicken Curry along with\u00a0Dhaba Style Spicy Ghee Rice Recipe Made From Whole Spices, and\u00a0Andhra Style Chepa Vepudu Recipe - Andhra Fish Fry Recipe\u00a0for a delectable weekend\u00a0meal."]'::jsonb, 70, 'Andhra', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Padma_Veeranki/Classic_Andhra_Style_Chicken_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/543.Classic_Andhra_Style_Chicken_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Style Nattu Kozhi Varuval Recipe', 'chettinad-style-nattu-kozhi-varuval-recipe', 'Chettinad chicken recipes are very popular in almost all the restaurants here in South India and this Chettinad Style Nattu Kozhi Varuval Recipe is a famous one among them, that is made with Nattu Kozhi (country chicken). Chettinad cuisine originates in Chettinad region of Tamil Nadu state in South India. Chettinad cuisine is one of the spiciest and the most aromatic flavours that one can find in India. The cuisine is famous for its use of a variety of spices used in preparing mainly non-vegetarian food. Chettinad Style Nattu Kozhi Varuval Recipe is a fantastic dish with a wonderful blend of aromatic spices. Usually, country chicken (nattu kozhi ) is used in Chettinad Kozhi preparation. These days broiler chicken is easy available than country chicken, so one can use broiler chicken instead of country chicken also.', '["500 grams Chicken , (chicken with bones gives better taste)", "1 cup Shallots , chopped", "2 Tomatoes , chopped", "2 sprig Curry leaves", "1 tablespoon Ginger Garlic Paste", "1/2 teaspoon Turmeric powder (Haldi) , + 1/2 teaspoon extra", "1 teaspoon Cumin powder (Jeera) , roasted", "1 teaspoon Fennel Powder , roasted", "1 tablespoon Coriander Powder (Dhania)", "2 tablespoon Red Chilli powder", "1 teaspoon Black pepper powder", "Salt , to taste", "3 tablespoon Oil", "Water , as required", "Coriander (Dhania) Leaves , as required for garnish"]'::jsonb, ARRAY['s chicken', 'shallots', 'tomatoes', 'curry leaves', 'ginger garlic paste', 'turmeric powder', 'haldi', 'cumin powder', 'jeera', 'fennel powder', 'coriander powder', 'dhania', 'red chilli powder', 'black pepper powder', 'salt', 'oil', 'water', 'coriander']::text[], '["To prepare Chettinad Style Nattu Kozhi Varuval Recipe, clean the chicken thoroughly and wash the chicken breasts in water for 3-4 times.", "Then add about 1/2 teaspoon of turmeric powder and water until chicken in fully immersed and let it sit for 10 minutes.", "Then drain the turmeric water and marinate with a little salt.", "This step of washing chicken in turmeric water will reduce the smell in the chicken.In a Kadai\u00a0add oil.", "On medium heat, firstly add finely chopped shallots and saut\u00e9 till onions turn soft.Then add ginger garlic paste and cook till the raw smell of the paste is gone.", "Add curry leaves and mix well.Add finely chopped tomatoes and cook till tomatoes turn soft and mushy.Now add the marinated chicken and let it cook for 3-5 minutes.Add all the spice powders, mix well.", "Cook for another 5 minutes.Now add salt and about 1/2 cup water.", "Cover and cook till the chicken is fully cooked and all water is evaporated.Hot, spicy, flavorful Chettinad Style Nattu Kozhi Varuval Recipe is ready.Serve Chettinad Style Nattu Kozhi Varuval with sambar\u00a0recipe."]'::jsonb, 45, 'Chettinad', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Chettinadu_Kozhi_Varuval.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/544.Chettinadu_Kozhi_Varuval.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Kaju Curry Recipe (Spicy Goan Cashew Nut Curry)', 'goan-kaju-curry-recipe-spicy-goan-cashew-nut-curry', 'Goan Kaju Curry is yet another delicious dish from the western coast of India or the Konkan region. Goan Kaju Curry is normally made using the best quality goan cashew nuts and served as a vegetarian delicacy in goan weddings and parties. The Goan Kaju curry is made by following the traditional style of goan cooking which consists of roasting grated coconut along with onion, garlic and spices and addition of tamarind. Tamarind is used as a souring agent in most of the Goan dishes.', '["1 cup Cashew nuts , halved", "1 Tomato , finely chopped", "1 Green Bell Pepper (Capsicum) , diced", "1/2 teaspoon Turmeric powder (Haldi)", "Oil , for cooking", "1 tablespoon Coriander (Dhania) Leaves , chopped, for garnishing", "Salt , to taste", "Ingredients to be ground to paste", "1 cup Fresh coconut , grated", "2 Onion , finely chopped", "5 Garlic , chopped", "1 teaspoon Coriander (Dhania) Seeds", "3 Byadagi Dried Chillies", "5 Whole Black Peppercorns", "1 teaspoon Cumin seeds (Jeera)", "2 Cloves (Laung)", "1/2 Tamarind , marble sized ball"]'::jsonb, ARRAY['cashew nuts', 'tomato', 'salt', 'coriander (dhania) leaves', 'coconut', 'black peppercorns', 'tamarind marble', 'byadagi dried chillies', 'coriander (dhania) seeds', 'onion', 'garlic', 'cumin seeds (jeera)', 'green bell pepper (capsicum)', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To Begin making the Goan Kaju Curry recipe, soak the cashew nuts into hot water for minimum 30 minutes.", "Meanwhile proceed for making the curry/gravy.", "Dry roast the coriander seeds, cumin seeds, peppercorns, cloves and dry red chilies until you get a roasted aroma.", "Add the coconut and roast it along with the spices until you can smell the aromas of the coconut.", "Add the tamarind ball and saute for a few seconds and turn off the heat.For making the gravy, place a kadai on medium heat and add a teaspoon of oil.", "Add the finely chopped onion and garlic and saute until the onion is translucent.", "Once cooled, grind the above mentioned grated coconut and spice mixture along with the onions to make a smooth paste, by adding a little water.", "In the same pan where you sauteed the onions, heat a teaspoon of oil on medium heat.", "Add the chopped tomatoes, turmeric powder and saute them until it softens.", "Add the capsicum and saute for a couple of minutes until it softens and cooks through.", "Add the masala curry paste to the above tomato capsicum mixture and the soaked\u00a0cashew nuts\u00a0and stir fry for 3-4 minutes.", "Add a little water to adjust the consistency of the Kaju Curry.", "Stir and simmer the Goan Kaju Curry for about 10 Minutes.", "Once done, check the salt and spice levels and adjust to suit your taste.", "Finally stir in the\u00a0chopped coriander leaves and serve.Serve this Goan Kaju Curry for parties along with\u00a0Phulkas,\u00a0Jeera Riceand a Salad for a weeknight dinner or a special Sunday lunch."]'::jsonb, 55, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Goan_Cashew_nut_curry_or_Kaju_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/545.Goan_Cashew_nut_curry_or_Kaju_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mutton Keema Recipe', 'mutton-keema-recipe', 'Mutton Keema is a very popular dish in North India and is loved and cherished by all the non vegetarians. This dish is made with minced mutton and spice powders.', '["2 cup Mutton , minced", "Oil , as required", "1 teaspoon Cumin seeds (Jeera)", "2 Bay leaves (tej patta)", "1 teaspoon Whole Black Peppercorns", "5 Cardamom (Elaichi) Pods/Seeds", "3 Onion , finely chopped", "2 tablespoons Ginger Garlic Paste", "2 Green Chillies , finely chopped", "3 Tomatoes , finely chopped", "1-1/2 teaspoon Coriander Powder (Dhania) , chopped", "1 tablespoon Kashmiri Red Chilli Powder", "1/2 teaspoon Cumin powder (Jeera)", "Salt , as required", "1/2 teaspoon Garam masala powder", "Mint Leaves (Pudina) , chopped"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'kashmiri red chilli powder', 'bay leaves (tej patta)', 'cardamom (elaichi) podsseeds', 'mint leaves (pudina)', 'black peppercorns', 'ginger garlic paste', 'onion', 'mutton', 'cumin seeds (jeera)', 'coriander powder', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Mutton Keema recipe, Heat oil in a wide pan and add cumin seeds, bay leaves, peppercorns and cardamoms.Add the chopped onions and saute them till they turn brown in colour.Add garlic and ginger paste, green chillies, tomato puree and mix everything well.Let it cook for about 5 minutes on medium flame.", "Once it is done, add coriander powder, red chilli powder, cumin powder and salt.Cook for about 5-8 minutes on low flame.", "After 5-8 minutes, add the minced mutton and salute it for about 2-3 minutes.", "Add required water and cook till it gets dry.Once the mutton is cooked, switch off the stove and add garam masala.", "Mix well and garnish it with mint leaves.In Maharashtra, this Mutton Keema is served with pav.", "You can also serve it with Phulkas or\u00a0Pakki Mutton Biryani."]'::jsonb, 40, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Mutton_Keema_paav_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/546.Mutton_Keema_paav_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bendekaayi Gojju (Lady Finger In Coconut Curry) Recipe', 'bendekaayi-gojju-lady-finger-in-coconut-curry-recipe', 'Bendekaayi Gojju is also known as Saasive Gojju (Mustard seeds curry) as it uses raw mustard seeds. This creamy gojju is a tangy, sweet and spicy curry that goes well with roti and rice. You can serve it for a weekday lunch or dinner.', '["1/2 kg Bhindi (Lady Finger/Okra) , sliced", "3 Dry Red Chillies", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 cup Fresh coconut , grated", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Green Chillies , chopped", "3 sprig Coriander (Dhania) Leaves , chopped", "1 tablespoon Chana dal (Bengal Gram Dal) , roasted", "1 tablespoon Tamarind Paste", "1 tablespoon Jaggery"]'::jsonb, ARRAY['chana dal (bengal gram dal)', 'coconut', 'mustard seeds', 'jaggery', 'coriander (dhania) leaves', 'dry red chillies', 'bhindi (lady fingerokra)', 'tamarind paste', 'green chillies']::text[], '["To begin making the Bendekaayi Gojju recipe, grind all the ingredients listed under \u2018For paste'', into a smooth paste in a mixer grinder.Heat oil in a wide pan, add mustard seeds and let it crackle.", "Add curry leaves and dry red chilly and let them crisp up.Add the sliced ladies finger and roast till the sliminess is gone and the ladies finger starts to turn brown at the edges.Add the ground paste and add a cup of water and let it boil.", "It will thicken really quick.", "Once it thickens, add salt and one more cup of water and let it boil again till it thickens.Serve Bendekaayi Gojju with\u00a0phulka\u00a0or steamed rice for a healthy and satisfying weekday meal."]'::jsonb, 45, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuri_Aggarwal/Bendekaayi_Gojju.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/547.Bendekaayi_Gojju.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Petha Wadi Sabzi Recipe', 'petha-wadi-sabzi-recipe', 'One of the very tempting sabzi is this Petha wadi sabzi. Wadi is made of  moong dal. It is sundried balls made of yellow lentils both split or whole ones with green skin on it. It’s usually made from sprouted moong, hence wadi it’s very nutritious with loads of vitamins and minerals in it.', '["2 cups Badi (wadi)", "1 cup Kaddu (Parangikai/ Pumpkin)", "2 Onions , finely chopped", "2 Tomatoes , finely chopped", "1/2 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "4 Green Chillies , slit", "1 teaspoon Cumin seeds (Jeera)", "1 tablespoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Turmeric powder (Haldi)", "1 tablespoon Oil", "Salt , to taste", "Coriander (Dhania) Leaves , a few, to garnish"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'parangikai pumpkin', 'coriander (dhania) leaves', 'red chilli powder', 'cloves garlic', 'onion', 'badi (wadi)', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making Petha Wadi Sabzi Recipe, in a pan heat oil.", "Add cumin seeds to hot oil and allow it to crackle.Once the cumin seeds have crackled add finely chopped onions and saute until translucent.", "Add\u00a0 ginger, garlic and saute for a few seconds till the aromas come through.Once done add finely chopped tomatoes and cook until tomatoes turn mushy.After the tomatoes are mushy and cooked add the spice powders, red chilli powder, coriander powder, turmeric powder along with salt, mix well to combine.Add diced pumpkin, wadis and mix.", "Saute for 3 to 5 minutes.Add 1/2 to 3/4 cup water to the Petha Wadi Sabzi, cover and cook until pumpkin is cooked.", "Let the water evaporate and the sabzi come together.Turn off stove and transfer the sabzi to serving bowl.", "Garnish\u00a0Petha Wadi Sabzi with coriander leaves.Serve Petha Wadi Sabzi Recipe with\u00a0Homemade Butter Naan,\u00a0Kashmiri Style Paneer Masala\u00a0and\u00a0Kachumber Salad Recipe With Cucumber, Onion & Tomatoes\u00a0for dinner."]'::jsonb, 65, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/Petha_Wadi_Sabzi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/548.Petha_Wadi_Sabzi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Raw Jackfruit & Peanut Masala Poriyal Recipe With Sambar Powder', 'raw-jackfruit-peanut-masala-poriyal-recipe-with-sambar-powder', 'The Raw Jackfruit and Peanut Masala Poriyal Recipe, is a simple South Indian style stir fry of Raw Jackfruit that makes a great indian diabetic recipe.', '["1 Jackfruit Raw (Kathal) , cut into cubes", "1/4 cup Raw Peanuts (Moongphali)", "1 teaspoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 sprig Curry leaves", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoons Sambar Powder", "1 teaspoon Lemon juice", "Salt , to taste"]'::jsonb, ARRAY['jackfruit raw', 'kathal', 'raw peanuts', 'moongphali', 'oil', 'mustard seeds', 'rai/ kadugu', 'curry leaves', 'turmeric powder', 'haldi', 's sambar powder', 'lemon juice', 'salt']::text[], '["To begin making the Raw Jackfruit and Peanut Masala Poriyal , let us first cut the raw jackfruit.", "In order to do that we have to first grease our hands and the knife that is going to be used with oil.This important tip ensures that the hands don''t get sticky from the natural fruit latex/sap present in the fruit, does not get onto your hands and makes the cutting process hassle-free.Keep a bowl of water mixed with some salt, ready to put the cut raw jackfruit pieces to avoid discolouration of the fruit.Now that your hands and knife are well greased, cut the the jackfruit in half, discard the skin and start making 1 inch pieces and then soak them in the salted water.To start cooking the Raw Jackfruit, place the cut pieces of raw jackfruit in a pressure cooker with 1/4 cup of water and pressure cook for 6 whistles, reduce the heat and continue to cook for 10 minutes.", "Turn off the flame.Allow the pressure to release naturally.", "Drain the raw jackfruit pieces and set aside.In a heavy bottomed pan, heat oil on medium heat, add the mustard seeds and curry leaves.", "Allow the mustard seeds to crackle.Add the peanuts and pan fry till the peanuts are well roasted.", "Do this over medium heat, so the peanuts get roasted well from the inside.Once the peanuts are roasted well, add in the boiled raw jackfruit, sambar powder, turmeric powder and salt.", "Stir well for a few minutes until all the spices are well combined into the\u00a0Raw Jackfruit and Peanut Masala Poriyal.", "After a few minutes, stir in the lemon juice and turn off the heat.", "Check the salt and spices and adjust accordingly.", "Serve hot as a side dish for indian diabetic meal.Serve this\u00a0Raw Jackfruit and Peanut Masala Poriyal Recipe\u00a0along with\u00a0Chettinad Style Poondu Rasam Recipe (Garlic Rasam Recipe ),\u00a0Steamed Rice Recipe\u00a0and\u00a0Elai Vadam\u00a0for a complete\u00a0South Indian meal\u00a0as well as a side dish for a\u00a0indian diabetic meal."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/South_Indian_Raw_Jacfruit_Peanut_Masala_Fry-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/549.South_Indian_Raw_Jacfruit_Peanut_Masala_Fry-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dhaba Style Green Moong Dal Makhani Recipe', 'dhaba-style-green-moong-dal-makhani-recipe', 'Green Moong Dal Makhani is a wholesome lentil curry that is made in the similar way to the Dhaba Dal of Punjab. Made with Green Moong, flavoured with subtle Indian spices and simmered optionally with cream and butter for as long as 15 minutes makes this dal rich, nutritious and delicious.', '["1-1/2 cups Green Moong Dal (Whole)", "1 Tomato , chopped", "1 Onion , finely chopped", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "1 Bay leaf (tej patta)", "1 inch Cinnamon Stick (Dalchini)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1 teaspoon Oil", "2 tablespoons Fresh cream , optional", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "Salt , to taste"]'::jsonb, ARRAY['s green moong dal', 'whole', 'tomato', 'onion', 'ginger', 's garlic', 'bay leaf', 'tej patta', 'cinnamon stick', 'dalchini', 'turmeric powder', 'haldi', 'garam masala powder', 'coriander powder', 'dhania', 'red chilli powder', 'oil', 's fresh cream', 'kasuri methi', 'dried fenugreek leaves', 'salt']::text[], '["To begin making the Dhaba Style\u00a0Green Moong Dal Makhani Recipe, soak the green moong dal in 3 cups of water for about 2 hours.Into the pressure cooker, add a teaspoon of oil.", "Add the onion, ginger and garlic and saute until the onions soften.Once the onions have softened, add the chopped tomato and saute until the tomatoes soften.", "Once the tomatoes have softened, add the bay leaf, cinnamon stick, turmeric powder, coriander powder, red chilli powder, garam masala powder and salt to taste.", "Stir to combine the masalas.", "After a minute, add the soaked green moong dal along with 3 cups of water and pressure cook the Dhaba style Green Moong for 6 to 8 whistles.Turn off the heat and allow the pressure to release naturally.Once the pressure is released, open the cooker and you will find the dal to be well cooked and mushy.", "That''s the consistency we want for the dal.", "Check the salt and spices and adjust accordingly.You can optionally add cream if you want to make the green moong dal makhani creamy and delicious.", "Once done, stir in the Kasuri methi leaves.Transfer the\u00a0Dhaba Style\u00a0Green Moong Dal Makhani to a serving bowl and serve hot.Serve the Dhaba Style\u00a0Green Moong Dal Makhani\u00a0along with\u00a0Missi Roti\u00a0and\u00a0Lauki Raita\u00a0and it would make a perfect dinner or lunch."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Dhaba_Style_Green_Moong_Dal_Makhani_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/550.Dhaba_Style_Green_Moong_Dal_Makhani_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Nendra Pazham Pulissery Recipe - Ayurvedic Recipe', 'nendra-pazham-pulissery-recipe-ayurvedic-recipe', 'Nendra Pazham Pulissery Recipe is a wonderful twist on a traditional pulissery that we all know. It is usually has vegetables like ash gourd that is added into the curry but here in this recipe we have created a twist by adding ripened banana that compliments well with the flavor of ground coconut mixture and curd. It is also considered to be a part of baby food that you can make it with less spices.', '["1 teaspoon Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves", "2 Nendra Pazham Banana (Ripe) , peeled and sliced into rounds", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 cup Curd (Dahi / Yogurt)", "To Grind", "1 cup Fresh coconut , grated", "2 Green Chillies", "1 sprig Curry leaves", "1 teaspoon Cumin seeds (Jeera)", "1/2 cup Lukewarm Water", "Oil , for tempering"]'::jsonb, ARRAY['salt', 'green chilli', 'coconut', 'mustard seeds', 'curd', 'curry leaves', 'white urad dal (split)', 'coconut oil', 'cumin seeds (jeera)', 'nendra pazham banana (ripe)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Nendra Pazham Pulissery Recipe, prepare all the ingredients and keep ready.Preheat oil in heavy bottomed pan over medium heat; add the mustard seeds, cumin seeds and allow them to crackle.Add the turmeric powder and the\u00a0Nendra Pazham along with the salt.Stir fry and cook the\u00a0Nendra Pazham until it is soft and cooked through.", "This will not take more than a couple of minutes.", "Turn off the heat.", "Into a mixer grinder, add the coconut, green chillies, cumin seeds, curry leaves along with 1/2 cup warm water and blend to make a smooth mixture.Add this coconut mixture along with the yogurt to the cooked\u00a0Nendra Pazham.When you are ready to serve your meal,\u00a0bring Nendra Pazham Pulissery to a brisk boil for a couple of minutes and turn off the heat.Check salt and adjust according to taste.", "Transfer the Nendra Pazham Pulissery\u00a0to a serving bowl and serve hot.Serve the\u00a0Nendra Pazham Pulissery Recipe\u00a0along with\u00a0Steamed Rice,\u00a0Pavakkai Poriyal Recipe\u00a0and\u00a0Elai Vadam\u00a0for a wholesome lunch or dinner."]'::jsonb, 25, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Nendra_Pazham_Pulissery_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/551.Nendra_Pazham_Pulissery_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hyderabadi Khadi Masoor Dal Recipe - Hyderabadi Style Lentil Curry', 'hyderabadi-khadi-masoor-dal-recipe-hyderabadi-style-lentil-curry', 'Hyderabadi Khadi Masoor Dal Recipe is a highly nutritious dal recipe made with simple ingredients found in our kitchen.', '["1 cup Pink Masoor Dal (Split) , whole", "1 tablespoon Ghee", "4 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "2 Green Chillies , slit", "1 Onion , thinly sliced", "1 Tomato , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "Salt", "6 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['pink masoor dal', 'split', 'ghee', 's garlic', 'ginger', 'reen chillies', 'onion', 'tomato', 'turmeric powder', 'haldi', 'red chilli powder', 'salt', 'coriander', 'dhania']::text[], '["To begin making the Hyderabadi Khadi Masoor Dal Recipe, wash the masoor dal and set aside.", "Heat ghee in a pressure cooker over medium heat.", "To this pan add the chopped ginger, garlic paste, green chillies and sliced onions.", "Saut\u00e9 the onions until they turn translucent and lightly golden brownNext add the chopped tomatoes, salt, red chilli powder and turmeric powder and cook for about a minute until the tomatoes turn mushyFinally add the washed and drained masoor dal and 1-1/2 cups of water.", "Pressure cook the\u00a0Hyderabadi Khadi Masoor dal for 2 whistles.", "After 2 whistles, turn the heat to low and simmer for 3 to 4 minutes and turn off the heat.Allow the pressure to release naturally.", "Once done, open the pressure cooker and check salt and adjust to taste of the\u00a0Hyderabadi Khadi Masoor Dal.", "Stir in chopped coriander leaves and and transfer the\u00a0Hyderabadi Khadi Masoor Dal to a serving bowl and serve hot.Serve\u00a0Hyderabadi Khadi Masoor Dal Recipe along with\u00a0Bharwa Bhindi Recipe,\u00a0Homemade Butter Naan ,\u00a0Dhaba Style Spicy Ghee Rice\u00a0and\u00a0Spring Onion and Peanut Raita\u00a0for a complete meal."]'::jsonb, 30, 'Hyderabadi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Hyderabadi_Khadi_Masoor_Ki_Dal_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/552.Hyderabadi_Khadi_Masoor_Ki_Dal_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mixed Vegetable Akki Roti Recipe', 'mixed-vegetable-akki-roti-recipe', 'Mixed Vegetable Akki Roti is a famous recipe from Karnataka. The recipe in this article is a mix of all vegetables and greens which are slightly different from the regular akki roti. This dish cannot be mixed in advance or kept in the fridge since it tends to leave water. Hence you may cut the vegetables and  keep them ready and mix it with rice flour and oils as and when needed. For kids, just omit the chili and the rest can be still the same. Mixed Vegetable Akki Roti is ideal for those who are following gluten-free diet.', '["300 grams Rice flour", "1 Carrot (Gajjar) , grated", "1/4 cup Chayote , grated", "1/4 cup Cucumber , grated", "1/2 Green Bell Pepper (Capsicum) , finely chopped", "2 sprig Curry leaves", "1 Tomato , small, deseeded and finely chopped", "Green Amaranth Leaves , small bunch finely chopped", "2 teaspoons Cumin seeds (Jeera) , Cumin seeds \u2013 4 tsp", "5 Green Chilli , finely chopped (adjust)", "Salt , to taste", "Oil , as needed"]'::jsonb, ARRAY['cucumber', 'tomato', 'salt', 'green chilli', 'cumin seeds (jeera) cumin seeds – tsp', 'chayote', 'carrot', 'curry leaves', 'green bell pepper (capsicum)', 'green amaranth', 'rice flour', 'sunflower oil']::text[], '["To prepare Mixed Vegetable Akki Roti Recipe, grate or chop all the vegetables required finely.Mix Rice flour, a little oil, vegetables and cumin seeds.", "No water is needed unless that dough doesn''t come\u00a0together.Knead well until the dough is formed.Oil your hands, pinch out a big lemon sized ball, take a butter paper or thick sheet like a\u00a0zip lock and apply oil before you place the ball of dough on it.Start making the akki roti by patting with your hands to make a roti flatbread as thin as possible.Heat a roti tawa.", "Once hot, add a teaspoon of oil to it.Take the akki roti with the butter paper sheet and put it on the pan and leave for a few seconds and gradually lift off the butter paper and removing the roti from it, such that it is transferred to the tawa.", "This may sound complicated but is easy once you do it.Wait\u00a0till the mixed vegetable akki roti is done on one side, which takes about a minute on medium high flame.", "Meanwhile, drizzle a few drops of oil evenly on the exposed side.Flip the mixed vegetable akki roti and let it get cooked for a minute or more.", "Flip again and wait till done and crisp.You can also place a lid on tawa while the roti is cooking if you want softer roti and not crisper ones.", "Serve Mixed vegetable Akki roti recipe with a dollop of ghee or butter, or with\u00a0podis."]'::jsonb, 85, 'North Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/neerusrikanth/Mix_Vegetable_Akki_Roti.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/553.Mix_Vegetable_Akki_Roti.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Matar Aur Chilke Ka Sabzi (Peas & Peel Stir Fry Recipe)', 'matar-aur-chilke-ka-sabzi-peas-peel-stir-fry-recipe', 'Matar Aur Chilke Ka Sabzi is a green Peas & Peel Stir Fry Recipe. Instead of discarding all the peel of the peas, you can stir in an interesting recipe from it, when combined with spring onions and spicing with panch phoron masala. Only trick is to remove the thick fibrous vein of the chilka/peapod. Serve Matar Aur Chilke Ka Sabzi (Peas & Peel Stir Fry Recipe) hot as a side-dish with paratha or phulkas.', '["300 grams Green peas (Matar) , with pod, fresh & firm", "5 Spring Onion (Bulb & Greens) , chopped", "1/2 teaspoon Panch Phoran Masala", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "2 Green Chillies , slit/finely chopped", "Salt , as needed", "1 tablespoon Oil"]'::jsonb, ARRAY['s green peas', 'matar', 'spring onion', 'bulb & greens', 'panch phoran masala', 'turmeric powder', 'haldi', 'red chilli powder', 'reen chillies', 'salt', 'oil']::text[], '["To prepare Matar Aur Chilke Ka Sabzi (Peas & Peel Stir Fry Recipe), Wash the green pea pods.", "Take out the peas from the pods in a bowl and keep aside.Take half of the peels of peas. (discard the rest).", "Break the tip and the bottom of each pod peel and discard the long fibrous membrane in them.", "Chop each pea pod in the middle, to bite size.Chop the white part of spring onion lengthwise and the green part into 1-2 inch\u00a0pieces.Heat the oil in a kadai and add panch phoron.", "When the seeds begin to splutter add chopped white part of the spring onion.", "Stir fry a bit.", "Then add chopped peels of green pea pods, spring onion greens and half of the green peas extracted from the\u00a0pods.", "Stir again.Add in turmeric powder, chopped green chilies and salt.", "Cook covered on low-medium heat till vegetables are just tender.Remove from heat and serve Matar Aur Chilke Ka Sabzi (Peas & Peel Stir Fry Recipe) hot as a side-dish with paratha or phulkas."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/firsttimercook/Matar_ke_Chilke_ka_Sabzi__Green_Peas_Peel_Stir_Fry_with_Spring_Onion.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/554.Matar_ke_Chilke_ka_Sabzi__Green_Peas_Peel_Stir_Fry_with_Spring_Onion.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vankaya Pakodi Koora Recipe - Andhra Style Brinjal Pakora Curry', 'vankaya-pakodi-koora-recipe-andhra-style-brinjal-pakora-curry', 'Vankaya Pakodi Koora Recipe is essentially a Brinjal Pakora Curry tossed in an onion - tomato base flavoured with sambar masala. This delicious Andhra style vegetable is has pakoras which are crispy on the outside and soft on the inside made healthy in the paniyaram pan.', '["8 Small Brinjal (Baingan / Eggplant) , cut into wedges", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 tablespoons Oil", "1 Onion , finely chopped", "2 Green Chillies , finely chopped", "6 cloves Garlic , finely chopped", "2 sprig Curry leaves , roughly torn", "3 Tomatoes , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Sambar Powder", "Salt , to taste", "6 sprig Coriander (Dhania) Leaves", "1 cup Gram flour (besan)", "2 tablespoon Rice flour", "Salt , to taste", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "2 cloves Garlic , finely chopped", "1 Green Chilli , finely chopped", "1 Onion , finely chopped", "Oil , to fry"]'::jsonb, ARRAY['small brinjal', 'baingan / eggplant', 'mustard seeds', 'rai/ kadugu', 's oil', 'onion', 'reen chillies', 's garlic', 'curry leaves', 'tomatoes', 'turmeric powder', 'haldi', 'red chilli powder', 'sambar powder', 'salt', 'coriander', 'dhania', 'gram flour', 'besan', 'rice flour', 'reen chilli', 'oil']::text[], '["To begin making the Vankaya Pakodi Koora Recipe, prep all the ingredients and keep them ready.Cut the brinjal into wedges and place it in water to prevent discolouration.First step is to make the pakora; into a mixing bowl add the gram flour, rice flour, turmeric powder, red chilli powder, green chillies, garlic, onion and salt.", "Add little water at a time to make a thick batter.Heat oil in a paniyaram pan over medium heat; add a tablespoon of the pakoda batter into the cavities of the paniyaram pan and pan fry on both sides until golden brown and crisp.You can drizzle additional oil into the cavities in case it is needed to make the pakoras crisp.Once the pakoras are pan fried, keep them to the side.Next step is to cook the brinjal/ venkaya.Heat 2 tablespoons of oil in a pan over medium heat; add the mustard seeds and allow it to crackle.", "Add the onion, garlic and green chillies and saute until the onions softens and turns light brown.Add the cut brinjal (drain out the water), sprinkle salt and a little turmeric powder and roast the brinjal on low medium heat until it is cooked through.", "Stir in the curry leaves, chopped tomatoes, turmeric powder, red chilli powder, sambar powder and saute until the tomatoes are mushy and soft.", "Add 1/4 cup of water and stir to combine to make a semi thick mixture.Stir in the pakoras to the above\u00a0Vankaya tomato onion mixture.", "Cover the pan and simmer the Vankaya Pakodi Koora for about 3 to 4 minutes until the eggplant and the pakora are well coated with the masala.Check the salt and spices and adjust to suit your taste.", "Once done, turn off the heat, stir in the chopped coriander leaves and transfer the Vankaya Pakodi Koora to as serving bowl and serve hot.Serve\u00a0Vankaya Pakodi Koora Recipe along with piping hot\u00a0steamed rice\u00a0and\u00a0Jeera Milagu Rasam Recipe\u00a0for a simple meal."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Gauravi_Vinay/Andhra_Style_Vankaya_pakodi_koora_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/555.Andhra_Style_Vankaya_pakodi_koora_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gujarati Trevti Dal Recipe (Creamy Lentils Cooked In Mild Spices)', 'gujarati-trevti-dal-recipe-creamy-lentils-cooked-in-mild-spices', 'Trevti Dal is a classic gujarati recipe which is cooked using three different lentils. The lentils are tempered with mild spices making Gujarati Style Creamy Lentils simple yet delectable. The mashed chana dal renders a nice creamy texture to the dal. Serve the Gujarati Trevti Dal Recipe (Creamy Lentils Cooked In Mild Spices) along with Phulkas and Batata nu Shaak (Aloo Tamatar Ki Sabzi) Recipe or with Steamed Rice and Crispy Crunchy Roti Ke Papad Recipe for a comforting weeknight dinner.', '["1/4 cup Yellow Moong Dal (Split) , soaked for 30 minutes", "1/4 cup Chana dal (Bengal Gram Dal) , soaked for 30 minutes", "1/4 cup Arhar dal (Split Toor Dal) , soaked for 30 minutes", "1 inch Ginger , grated", "4 cloves Garlic , minced", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1 Green Chilli , finely chopped", "2 Dry Red Chillies", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Cumin seeds (Jeera)", "1/2 Lemon , juiced", "Coriander (Dhania) Leaves , few sprigs, finely chopped for garnish", "1 tablespoon Oil", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'yellow moong dal (split)', 'ginger', 'arhar dal (split toor dal)', 'green chilli', 'coriander (dhania) leaves', 'red chilli powder', 'cloves garlic', 'lemon', 'dry red chillies', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making Gujarati Trevti Dal Recipe (Creamy Lentils Cooked In Mild Spices), wash and soak the dal in water for half an hour and then pressure cook along with turmeric and salt for 3 whistles, mash and keep aside.", "Prep with all the other ingredients in the meanwhile.Now heat oil in a kadai on medium heat, add the cumin seeds, dried red chillies and let it crackle.Add the onion and saute until it turns translucent.Once the onion is translucent, add the grated ginger and minced garlic cloves and cook until the raw smell goes away.Now add the chillies and tomatoes, saute occasionally and cook until the tomatoes turns soft and mushy.Once the tomatoes are mushy, add in the red chilli powder and saute for a minute.Now, add the mashed dals, about 2 cups of water, season with salt and let it simmer for 10 minutes.", "After 10 minutes, check for salt and adjustGarnish with lemon juice, coriander leaves, mix and switch off the flame.Serve the\u00a0Gujarati Trevti Dal Recipe (Creamy Lentils Cooked In Mild Spices)\u00a0along with\u00a0Phulkas\u00a0and\u00a0Batata nu Shaak (Aloo Tamatar Ki Sabzi) Recipe\u00a0or with Steamed Rice and\u00a0Crispy Crunchy Roti Ke Papad Recipe\u00a0for a comforting weeknight dinner."]'::jsonb, 25, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Trevti_Daal_Gujarati_Style_Creamy_Lentils_Cooked_in_Mild_Spices.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/556.Trevti_Daal_Gujarati_Style_Creamy_Lentils_Cooked_in_Mild_Spices.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Methi Bajra Poori Recipe', 'methi-bajra-poori-recipe', 'Methi Bajra Poori as the name suggests, is deep fried, puffed bread made using fresh Methi (fenugreek) leaves and Bajra (millet) flour. The fresh Methi leaves add an amazing flavour and a characteristic bitter taste to the pooris. Bajra adds an earthy taste and makes the puris slightly crunchy. Use fresh Bajra flour for best results. The next time you need a ‘deep fried drip’, make these flavourful Methi Bajra Pooris.', '["1 cup Bajra Flour ( Pearl Millet)", "1/2 cup Whole Wheat Flour", "1 cup Methi Leaves (Fenugreek Leaves) , cleaned, washed and chopped", "1 teaspoon Garlic , paste", "1 teaspoon Red Chilli powder , or green chilli paste", "2 teaspoon Sesame seeds (Til seeds)", "2 teaspoon Fennel seeds (Saunf)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Amchur (Dry Mango Powder)", "2 teaspoon Oil , hot", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Oil , for deep frying"]'::jsonb, ARRAY['salt', 'wheat flour', 'cumin powder (jeera)', 'sunflower oil', 'coriander powder', 'amchur (dry mango powder)', 'fennel seeds (saunf)', 'methi leaves (fenugreek leaves)', 'bajra flour ( pearl millet)', 'turmeric powder', 'sesame seeds (til seeds)', 'red chilli powder green chilli paste', 'garlic paste']::text[], '["To begin making the Methi Bajra Poori, firstly mix all the ingredients except the oil for deep frying, in a mixing bowl or in the bowl of a food processor.Gradually add water and knead it into a firm yet pliable dough.", "Cover the dough and let it rest for 30 minutes.Make small balls from the dough.", "Roll them out into small round discs.", "Keep them covered till they are ready to be fried.Heat oil in a Kadhai/Wok.", "Gently slide in the rolled poori or 2-3 pooris (depending on the size of your wok).Deep fry on medium high heat until they puff and turn golden brown on both sides.Take out the pooris using a slotted spoon and place on absorbent paper.", "Serve hot.Serve Methi Bajra Poori on its own as a snack or it can be teamed up with\u00a0Aloo Dum\u00a0or any other curry for an indulgent meal."]'::jsonb, 70, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Methi_Bajra_Poori.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/557.Methi_Bajra_Poori.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hyderabadi Khatti Dal Recipe (Hyderabadi Tangy Lentil Curry)', 'hyderabadi-khatti-dal-recipe-hyderabadi-tangy-lentil-curry', 'Hyderabadi Khatti Dal is a delicious tangy dal preparation tempered with curry leaves, mustard seeds, cumin, dry red chilies and garlic having balanced flavour of sourness and spiciness. Hyderabadi khatti dal couples up beautifully with steamed rice, pickle, side with any dry veggie preparation. Although we have used Toor dal, you can use even Masoor dal (red lentils) for making this Khatti dal. Traditionally for sourness, tamarind pulp is used but you can substitute it with lemon juice too. But, the sourness that elevates this dal''s flavour is best with tamarind making it the best khatti dal ever.', '["1 cup Arhar dal (Split Toor Dal)", "1 Tomato , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Garlic , crushed", "1/2 teaspoon Ginger , grated", "3/4 teaspoon Green Chillies , chopped", "2-1/2 Tamarind Water", "Ingredients for Seasoning", "1 teaspoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies", "1 sprig Curry leaves", "3 cloves Garlic , sliced", "Coriander (Dhania) Leaves , few, for garnish"]'::jsonb, ARRAY['tomato', 'arhar dal (split toor dal)', 'ginger', 'tamarind water', 'mustard seeds', 'coriander (dhania) leaves', 'red chilli powder', 'cloves garlic', 'curry leaves', 'dry red chillies', 'garlic', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Hyderabadi Khatti Dal Recipe, first clean and wash the dal well under running water.", "In a pressure cooker, add washed dal, garlic, ginger, turmeric, red chili powder, green chili, tomatoes salt and 2 cups of water.", "Cover the pressure cooker and cook until you hear a couple of whistles.", "After a couple of whistles, turn the heat to low and cook for 3 minutes approximately and turn off the heat.", "Allow the pressure in the cooker release naturally.", "Once the pressure has released, open the cooker.", "When the dal is done, whisk the dal well to make it smooth.", "Add tamarind water to the dal and bring the Khatti dal to a brisk boil.", "Once it comes to a boil, turn the heat to low and set the dal to simmer.Next we will prepare the seasoning.In a small tadka pan\u00a0heat oil in medium heat.", "Add the mustard seeds, cumin seeds and allow it to crackle.", "Once it\u00a0Add garlic and fry until it starts getting golden brown.", "Add curry leaves and red chilies, fry for another few seconds.Pour the tadka over the dal and simmer for 4 to 5 minutes.", "Once done, turn off the heat and the\u00a0Hyderabadi Khatti Dal recipe is ready.", "Check the salt and adjust to suit your taste.", "Pour the dal into a serving bowl and garnish with chopped coriander leaves and serve warm.Serve the\u00a0Hyderabadi Khatti Dal along with\u00a0Steamed Rice,\u00a0Kathirikai Roast\u00a0(brinjal roast) and papad."]'::jsonb, 60, 'Hyderabadi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Farrukh_Aziz_Ansari/Hyderabadi_Khatti_Dal.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/558.Hyderabadi_Khatti_Dal.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spiced Cabbage Rice Recipe', 'spiced-cabbage-rice-recipe', 'Spiced Cabbage Rice Recipe is a healthy recipe of mixed rice that is made with sautéed cabbage and flavoured with curry leaves and coriander. Cabbage is one for those few vegetables that give nutty flavour and subtle sweetness to the rice making it delicious. The cabbage rice can also be combined along with soy granules or paneer to give it an extra texture to your tossed rice. The chopped onions, ginger, curry leaves, a hint of garlic and loads of chopped coriander leaves makes it delectable for a lunch box as well.', '["2 cups Cooked rice", "2 cups Cabbage (Patta Gobi/ Muttaikose) , finely sliced", "1/2 cup Soy granules , soaked in water until soft or paneer (Optional)", "1 teaspoon Cumin seeds (Jeera)", "2 Bay leaves (tej patta)", "1 inch Cinnamon Stick (Dalchini)", "1 Mace (Javitri)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Black pepper powder", "1 Onion , finely chopped", "1 inch Ginger , grated", "1 clove Garlic , finely chopped", "2 Green Chillies , finely chopped", "4 sprig Coriander (Dhania) Leaves , chopped", "1 tablespoon Ghee", "Oil , required for cooking", "Salt , to taste"]'::jsonb, ARRAY['s cooked rice', 's cabbage', 'patta gobi/ muttaikose', 'soy granules', 'cumin seeds', 'jeera', 'bay leaves', 'tej patta', 'cinnamon stick', 'dalchini', 'mace', 'javitri', 'turmeric powder', 'haldi', 'red chilli powder', 'black pepper powder', 'onion', 'ginger', 'garlic', 'reen chillies', 'coriander', 'dhania', 'ghee', 'oil', 'salt']::text[], '["Heat a teaspoon of in a heavy bottomed pan on medium heat; add cumin seeds, bay leaf, cinnamon stick and maze, let the aroma fill your kitchen for few seconds.", "Now add the onions, green chillies, ginger and garlic and saut\u00e9 until onion is tender and golden.In the mean while, pressure cook the rice with water in a pressure cooker and keep it aside.", "Add cabbage and soy granules (optional) and saut\u00e9 with the pan covered until the cabbage is soft, tender and cooked.", "You will find the cabbage has a nutty smell to it.", "At this point add all the spice powders and give it a toss well.", "Stir in the cooked rice, chopped coriander leaves, salt and ghee and simmer for a couple of more minutes to get the flavours into the rice.Serve the Cabbage Rice with Soy Granules along with a\u00a0Vegetable Raita\u00a0of your choice for your lunch and dinner."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/15-march/Cabbage_stir_fried_rice_recipe_thoran-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/559.Cabbage_stir_fried_rice_recipe_thoran-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Raw Banana Sabzi Recipe', 'goan-raw-banana-sabzi-recipe', 'Goan Raw Banana Sabzi Recipe is a simple goan stir fry with plantains. Plantains are a great source of potassium, which helps in regulating the blood pressure. They are also great source to boost the immune system, making it healthy enough to include in our diet.', '["3 Raw Banana , chopped to cubes", "1 Onion , finely chopped", "4 tablespoons Fresh coconut , grated", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Dry Red Chilli", "1 sprig Curry leaves", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoons Oil", "Salt , to taste"]'::jsonb, ARRAY['banana cubes', 'salt', 'mustard seeds', 'coconut', 'dry red chilli', 'curry leaves', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making Goan Raw Banana Sabzi Recipe, peel the skin of the plantains, chop them into cubes and keep it immersed in cold water in a bowl until further cooking.Heat oil in a pan, once the oil is hot, add the mustard seeds and let it splutter.Add the red chilli, curry leaves and let it crackle.", "Add the onions and saute until it turns translucent.Drain the plantains and add it to the pan.", "Saute.Add turmeric powder, salt, mix well and let the plantains cook with the lid closed for 5 minutes.", "The plantains cook really fast.Now, pound the cumin and grated coconut using a pestle and mortar to a course mix and add it to the cooked plantains.Mix well and saute for another 5 minutes and switch off the heat.Serve the Goan Raw Banana Sabzi Recipe along with Phulka, Steamed Rice and Feijoada Recipe (Spicy Goan Black Eyed Peas Stew) for a rainy weeknight dinner."]'::jsonb, 20, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Goan_Raw_Banana_Sabzi_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/560.Goan_Raw_Banana_Sabzi_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Jhinga Gawar Recipe -Shrimps & Cluster Beans Sabzi', 'jhinga-gawar-recipe-shrimps-cluster-beans-sabzi', 'Jhinga Gawar Recipe -Shrimps & Cluster Beans Sabzi is an easy to prepare recipe that gets done in about 30 minutes. Cooked cluster beans and shrimps go very well together. Kids who like shrimps can also be fed with healthy gawar alongside in this sabzi. You can prepare this recipe for a buy weeknight dinner as well. You can also serve it with simple coconut rice and raita.', '["500 grams Gawar Phali (Kothavarangai / Cluster beans) , bite sized", "300 grams Shrimps", "1 Onion , chopped", "2 Tomatoes , chopped", "3 Green Chillies , slit", "1 tablespoon Oil", "1 teaspoon Cumin powder (Jeera)", "1 tablespoon Ginger Garlic Paste", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Red Chilli powder", "1 Lemon , juiced"]'::jsonb, ARRAY['s gawar phali', 'kothavarangai / cluster beans', 's shrimps', 'onion', 'tomatoes', 'reen chillies', 'oil', 'cumin powder', 'jeera', 'ginger garlic paste', 'cumin seeds', 'red chilli powder', 'lemon']::text[], '["To begin making Jhinga Gawar Recipe -Shrimps & Cluster Beans Sabzi, prep with all the ingredients first and cut the gawar to bite sized.Heat oil in a kadai and add cumin seeds and let it crackle.Once they crackle, add slit green chillies and finely sliced onions.", "Saute them till they are translucent.Then add ginger garlic paste and saute for a few seconds.Once the ginger garlic is cooked, add the chopped tomatoes and cook till the tomatoes are mushy.Once done, add the cumin powder, and the gawar.", "Saute for half a minute and add about half a cup of water and cover the pan to cook in medium heat.Check after 10 minutes and saute in between if required.", "Once the gawar phali is almost cooked, add the shrimps into the sabzi and cook further till done.", "Let the water evaporate to make it a dry sabziServe Jhinga Gawar Recipe -Shrimps & Cluster Beans Sabzi along with\u00a0Lauki Chana Dal\u00a0\u00a0and\u00a0Phulka Recipe\u00a0or\u00a0Makki Ki Roti\u00a0\u00a0or\u00a0Steamed Rice\u00a0and pair a\u00a0Dangar Pachadi With Grated Carrots Recipe\u00a0to make the lunch meal plate complete."]'::jsonb, 50, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Sadafabbasi79-yahoo.com/Jhinga_gawar_Shrimps_gawar_sabzi_recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/561.Jhinga_gawar_Shrimps_gawar_sabzi_recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goat Curry In Yogurt Gravy Recipe', 'goat-curry-in-yogurt-gravy-recipe', 'For this delicious recipe of Goat curry, no tomatoes used and even no coconut is being used, and of course, no need to marinate.The secret ingredient is garam masala, which I prepared at home and not store bought because the store bought ones doesn''t give that kick to the food.', '["800 grams Mutton , cut into about 1 inch size pieces", "1 Onion , sliced vertically", "2 Tablespoons Ghee", "1 Cup Curd (Dahi / Yogurt) , whisked", "1 Tablespoon Garlic , grated", "Coriander (Dhania) Leaves , few chopped (for garnishing)", "4 Whole Black Peppercorns", "4 Cloves (Laung)", "1 Cinnamon Stick (Dalchini)", "2 Bay leaves (tej patta)", "1 Tablespoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "2 Tablespoons Garam masala powder"]'::jsonb, ARRAY['s mutton', 'onion', 's ghee', 'curd', 'dahi / yogurt', 'garlic', 'coriander', 'dhania', 'whole black peppercorns', 'laung', 'cinnamon stick', 'dalchini', 'bay leaves', 'tej patta', 'red chilli powder', 'turmeric powder', 'haldi', 's garam masala powder']::text[], '["To begin making the Goat Curry In Yogurt Gravy recipe, firstly wash goat meat well and keep it aside.Slice onions vertically into very thin slices.Add ghee or oil in a big saucepan kept on medium high heat, and whole spices along with sliced onions.", "Sprinkle some salt over them (Salt makes moisture from onions evaporate).Saute the onions till they turn brown.", "Now add goat meat and mix well.Fry for 5 minutes, stirring occasionally.", "Add yogurt, red chili powder, turmeric and salt.", "Mix, cover and cook on medium high heat for 40 minutes.Check in between.", "If the mixture looks dry, add some water and continue cooking.", "Add garam masala and grated garlic.Again cover and cook until meat is soft when checked using toothpick.For me, it took 50 minutes total time to cook my goat meat, but it can vary depending upon how tender your goat meat is.Sprinkle some chopped coriander leaves.", "Mix well and remove from heat\u00a0and serve.Serve\u00a0Goat Curry In Yogurt Gravy along with\u00a0Jeera Pulao\u00a0and Some sliced onions for your weekday meal."]'::jsonb, 75, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/Goat_Curry_in_Yogurt_Gravy_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/562.Goat_Curry_in_Yogurt_Gravy_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Crab Masala Recipe', 'spicy-crab-masala-recipe', 'Spicy Crab Masala Recipe is made with a thick gravy of coconut, onions, ginger, and other spices. Monsoon in India has added to the craving for hot & absolutely spicy food. Also, crabs are one of the home remedies for bad cold. Remember to choose smaller freshwater crabs while making this recipe since the smaller ones are more tender, juicier and tastier. Here is a spicy version of crab masala to side up with steamed rice and rotis with Dal tadka and Carrot Ribbon Salad With Asian Sesame Dressing.', '["4 Crabs", "6 Fresh coconut , chunks", "5 sprig Coriander (Dhania) Leaves", "1 inch Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta)", "2 inch Ginger", "4 cloves Garlic", "3/4 cup Onion , fried", "1 Onion , chopped", "2 Tomato , finely chopped", "2 teaspoons Kashmiri Red Chilli Powder , adjustable", "1 teaspoons Red Chilli powder , adjustable", "1 tablespoon Coriander Powder (Dhania)", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Oil , as required"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'kashmiri red chilli powder', 'bay leaf (tej patta)', 'coconut', 'red chilli powder', 'cloves garlic', 'coriander (dhania) leaves', 'cinnamon stick (dalchini)', 'onion', 'turmeric powder', 'coriander powder', 'crabs', 'sunflower oil']::text[], '["To prepare Spicy Masala Crab Recipe, get all the ingredients handy and grind the masala ingredients fried onion, coconut, cinnamon, bay leaf, ginger, garlic & coriander leaves - to a fine paste.In a kadai/wok, heat some oil and saute the onion.Add the crabs and saut\u00e9 to coat them with oil.After the crab changes it color to deeper in 10 minutes on a medium heat, start adding the dry spice powders - turmeric powder, coriander powder, Kashmiri red chilli, red chilli powder and salt as per taste.", "Stir in all the spices to ensure that the crab is coated well with spices.Add the chopped tomato, stir them into the crab mixture.", "Add 1/2 cup of water, since crab cooks in its own moisture in meat as well.Cover with a lid and cook on simmered flame for 5-6 minutes, until the water from the meat starts oozing out.Remove the lid and check for the spice levels, and adjust.Pour in the ground masala and cook on a low flame with lid closed, for another 15-20 minutes.You may continue cooking to adjust the consistency of the gravy as desired.Once done- Serve Spicy Masala Crab Recipe hot with\u00a0steamed rice\u00a0and\u00a0rotis\u00a0with\u00a0Dal tadka\u00a0and\u00a0Carrot Ribbon Salad With Asian Sesame Dressing."]'::jsonb, 80, 'Kerala', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/FlavorFlameFusion/shutterstock_444716848.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/563.shutterstock_444716848.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Beetroot & Sesame Thepla Recipe', 'beetroot-sesame-thepla-recipe', 'Beetroot & Sesame Thepla Recipe is a must try Indian bread that you would relish it when you have it along with some subzi. The Indian bread is made by adding grated beetroot into the wheat flour and spiced up with some Indian masala like garam masala, amchur powder and coriander powder. At the end it is rolled flat and cooked on a griddle with sesame seeds on top.', '["1 Beetroot , grated", "2 cups Whole Wheat Flour", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Garam masala powder", "1 teaspoon Red Chilli powder", "3 Green Chillies", "1 teaspoon Ghee", "3 teaspoon Sesame seeds (Til seeds)", "Salt , to taste", "Chilled water , as needed"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'wheat flour', 'amchur (dry mango powder)', 'ghee', 'red chilli powder', 'water', 'sesame seeds (til seeds)', 'beetroot', 'green chillies', 'garam masala powder']::text[], '["To begin making the Beetroot & Sesame Thepla Recipe, wash and peel the beetroot skin.", "Grate the vegetable finely.Take a mixing bowl and add the grated beetroot.", "Add all the masala powder, salt and ghee.", "Mix all the ingredients.Add whole wheat flour into the mixing bowl and knead it to a smooth dough with enough water.Take a small portion of the wheat flour dough and flatten it using a rolling pin into form a flat round dough.Heat the Tawa to medium heat & add the thepla on the hot tawa.Cook the beetroot thepla for about a minute & then flip and cook on the other side for a minute or till done.Apply butter or oil as needed to grease it while cooking.Serve the Beetroot & Sesame Thepla Recipe along with a\u00a0Besan Kela Subzi,\u00a0Gujarati Dal, and salad by the side to make it a nutritious meal."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Beetroot__Sesame_Thepla_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/564.Beetroot__Sesame_Thepla_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Cauliflower Kurma (Tamil Nadu Restaurant Style Cauliflower Chops) Recipe', 'cauliflower-kurma-tamil-nadu-restaurant-style-cauliflower-chops-recipe', 'When you visit a good veg restaurant in Chennai for dinner you will find it difficult to miss the sight and smell of a favourite dinner tiffin of the Chennai people, the ''Parotta-Chops'' or in other words Paratha with yellow coloured kurma. This Kurma or Chops is typically made with Cauliflower as its key ingredient with almost a burji texture.', '["1 Cauliflower (gobi) , roughly chopped into smaller pieces", "1 Tomato , finely chopped", "15 to 20 Shallots , finely chopped", "3 to 4 Green Chillies , cut lengthwise", "4 cloves Garlic , grated", "1 inch Ginger , grated", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Cumin powder (Jeera)", "Salt , to taste", "4 teaspoons Fresh coconut , finely chopped", "1 teaspoon Fennel seeds (Saunf)", "1 teaspoon Cashew nuts , approximately 6-8", "1 teaspoon Poppy seeds", "1/2 teaspoon Coriander (Dhania) Seeds", "1 teaspoon Roasted Gram Dal (Pottukadalai)", "2 Dry Red Chillies", "1 tablespoon Coconut Oil", "1 Cloves (Laung)", "1 Cardamom (Elaichi) Pods/Seeds", "1 Star anise", "1 Bay leaf (tej patta)", "1 sprig Curry leaves"]'::jsonb, ARRAY['tomato', 'cumin powder (jeera)', 'cloves garlic', 'curry leaves', 'coriander (dhania) seeds', 'coconut oil', 'turmeric powder', 'green chillies', 'salt', 'cardamom (elaichi) podsseeds', 'dry red chillies', 'star anise', 'coconut', 'cauliflower (gobi) smer', 'ginger', 'bay leaf (tej patta)', 'fennel seeds (saunf)', 'gram dal (pottukadalai)', 'poppy seeds', 'cashew nuts approximately', 'cloves (laung)']::text[], '["To begin making the Cauliflower Kurma recipe, soak the ingredients given under ''masala paste'' in 1/4 cup of warm water for 20 minutes and then grind them to a fine paste using little water in a grinder.Bring 3 cups of water to a boil.", "Add the chopped cauliflower and cook them for 5 minutes and switch off the stove.Drain the water and set aside the cauliflower.Heat a wide pan or wok over low flame with coconut oil.", "Add all the ingredients mentioned under \u2018for tempering\u2019.Now add the grated ginger, garlic, chopped shallots, tomatoes and a pinch of salt.Keep stirring till the onions turn transparent and the tomatoes mushy.Add turmeric powder, cumin powder and mix well.", "Add 1/2 cup of water and let it simmer for 3-4 minutes.Now, add the boiled cauliflower and allow it to simmer for 5 minutes.When the cauliflower is completely soft boiled, add the ground masala paste and salt.Mix well and cook over low flame for another 5 minutes only.Switch off and garnish.", "Cauliflower Kurma is a tasty, healthy and popular side dish served along with appam,\u00a0idiyappam,\u00a0phulka\u00a0or malabar paratha."]'::jsonb, 80, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Uma_Raghuraman/Cauliflower_Kurma__Tamilnadu_Restaurant_Style_Cauliflower_Chops.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/565.Cauliflower_Kurma__Tamilnadu_Restaurant_Style_Cauliflower_Chops.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Murungai Keerai Thanni Saaru Recipe-Drumstick Leaves Soup', 'murungai-keerai-thanni-saaru-recipe-drumstick-leaves-soup', 'Murungai Keerai Thanni Saaru is a healthy and very light South Indian soup that is very nutritious. This saaru has many health benefits and very soothing to throat and reliefs cold. The drumstick leaves and coconut milk also makes this soup tasty.', '["1 1/2 cups Drumstick Leaves (Moringa/Murungai Keerai)", "2 cups Rice Water", "6 Pearl onions (Sambar Onions) , chopped", "1 Tomato , chopped", "2 Green Chillies , slit", "1 cup Coconut milk", "1 teaspoon Cumin seeds (Jeera) , crushed", "1/2 teaspoon Whole Black Peppercorns , crushed", "Salt , as required", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves", "2 teaspoons Oil", "2 Dry Red Chillies"]'::jsonb, ARRAY['tomato', 'salt', 'drumstick leaves (moringamurungai keerai)', 'rice water', 'black peppercorns', 'pearl onion (sambar onion)', 'curry leaves', 'dry red chillies', 'cumin seeds (jeera)', 'coconut milk', 'green chillies', 'sunflower oil']::text[], '["To begin making Murungai Keerai Thanni Saaru Recipe-Drumstick Leaves Soup, in a pan add the rice water and bring it to a boil.", "Once it is boiled, add the cleaned drumstick leaves, slit green chillies, chopped onions and tomato.Mix well and boil in medium flame until leaves are cooked.", "Meanwhile extract coconut milk and keep aside.", "Check our recipe on how to\u00a0Homemade Coconut Milk Recipe.", "With a mortar and pestle, crush cumin seeds and peppercorns and keep aside.", "Once the drumstick leaves are cooked soft, add coconut milk, crushed Cumin Pepper mixture and required salt.", "Simmer for 2 minutes and turn off the flame.", "In a tadka pan, heat a tablespoon of oil.", "Add Cumin seeds and once it sputters, add curry leaves and red chilli.", "Switch off and add it to the soup.", "Mix well and remove from flame.", "Check for salt and serve hot.Serve Murungai Keerai Thanni Saaru as a soup for nursing your family members who have a cold or even serve it along with\u00a0Steamed Rice\u00a0and\u00a0Cabbage Poriyal\u00a0along with\u00a0Ghee\u00a0for a delicious Sunday Lunch."]'::jsonb, 25, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swathynandhini/MURUNGAI_KEERAI_THANI_SAARU__DRUMSTICK_LEAVES_SOUP_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/566.MURUNGAI_KEERAI_THANI_SAARU__DRUMSTICK_LEAVES_SOUP_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Masala Puri Recipe', 'aloo-masala-puri-recipe', 'A perfect combination to enjoy this crispy, and delicious flavour of puffed Puris with any pickle or sabji. Aloo Masala Puri is a very popular Indian breakfast dish. They are more delicious when they are served hot, it''s easy to make and they are tummy filling breakfast.', '["1 Potato (Aloo) , boiled and mashed", "1 cup Whole Wheat Flour", "1/4 teaspoon Asafoetida (hing)", "1/4 teaspoon Ajwain (Carom seeds)", "1/4 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Red Chilli powder", "1/4 teaspoon Fennel seeds (Saunf)", "1/4 teaspoon Sesame seeds (Til seeds)", "1 tablespoon Oil", "Salt , to taste", "1 tablespoon Coriander (Dhania) Leaves , finely chopped", "Oil , for deep frying"]'::jsonb, ARRAY['salt', 'wheat flour', 'asafoetida (hing)', 'fennel seeds (saunf)', 'coriander (dhania) leaves', 'potato (aloo)', 'ajwain (carom seeds)', 'red chilli powder', 'coriander powder', 'turmeric powder', 'sesame seeds (til seeds)', 'sunflower oil']::text[], '["To begin making the Aloo Masala Puri recipe, firstly add wheat flour to mashed potato along with red chili powder, coriander powder, asafoetida, turmeric powder, carom seeds, fennel seeds, sesame seeds, coriander leaves, salt and oil.Mix them well and add water so as to form a dough.", "Keep it aside for few minutes.Make small round balls of this dough and roll them in the form of a Puri.Apply oil on the rolling pin and rolling board and carefully roll them in to Puri.Fry them in a deep fry pan and it is ready to be served.Serve Aloo Masala Puri with\u00a0Aam Ka Achaar\u00a0and\u00a0Lauki Raita\u00a0for breakfast or lunch."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Waagmi_Soni/aloo_masala_puri.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/567.aloo_masala_puri.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mushroom Thoran Recipe - Kerala Style Mushroom Sabzi', 'mushroom-thoran-recipe-kerala-style-mushroom-sabzi', 'Mushroom Thoran Recipe is a South Indian Kerala style stir fry od button mushrooms tossed in a  freshly ground coconut masala.  The coarse coconut masala apart from coconut contains whole black pepper corns, curry leaves and cumin seeds.', '["1/4 cup Fresh coconut", "1/2 teaspoon Whole Black Pepper Corns", "1 sprig Curry leaves", "1 teaspoon Cumin seeds (Jeera)", "1 tablespoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 Dry Red Chilli", "5 Pearl onions (Sambar Onions) , finely chopped", "3 cloves Garlic , finely chopped", "1 Green Chilli , finely chopped", "2 sprig Curry leaves , torn", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "300 grams Button mushrooms , cut into quarters"]'::jsonb, ARRAY['fresh coconut', 'whole black pepper corns', 'curry leaves', 'cumin seeds', 'jeera', 'oil', 'mustard seeds', 'rai/ kadugu', 'dry red chilli', 'pearl onions', 'sambar onions', 's garlic', 'reen chilli', 'turmeric powder', 'haldi', 'salt', 's button mushrooms']::text[], '["To begin making the Mushroom Thoran Recipe, prep all the ingredients and keep ready.To grind the coconut masala, in a mixer jar, combine the fresh coconut, peppercorns, curry leaves and cumin seeds.", "Grind this to a coarse masala without adding any water and set aside.", "To make the mushroom thoran; heat oil over medium flame.", "Add mustard seeds, cumin seeds, and dry red chilli and allow it to crackle.Stir in the curry leaves, pearl onions, garlic, green chilli and saute until the onions soften and turn lightly golden.Next, add in the mushrooms, salt and turmeric.", "Saute for 2-3 minutes.", "At this stage add the freshly ground coconut masala and continue to cook the Mushroom Thoran.", "When the mushrooms have cooked through completely, check the salt and adjust to taste accordingly and turn off the heat and serve.", "Serve Mushroom Thoran Recipe-Kerala Style Mushroom Sabzi with\u00a0\u00a0Steamed Rice\u00a0and\u00a0Cheriya Ulli Sambar\u00a0and\u00a0Elai Vadam Recipe\u00a0for a satisfying lunch."]'::jsonb, 40, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/13_-_Mushroom_Thoran_Recipe_Kerala_Style_Mushroom_Sabzi_1-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/568.13_-_Mushroom_Thoran_Recipe_Kerala_Style_Mushroom_Sabzi_1-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dhingri Dolma Recipe -Awadhi Style Mushroom Paneer Masala', 'dhingri-dolma-recipe-awadhi-style-mushroom-paneer-masala', 'Dhingri Dolma is an Awadhi style masala curry made using mushrooms and paneer. A rich onion-tomato gravy is flavoured with spices to make this scrumptious side dish. Shahjeera adds a royal aroma to the gravy, you can add cumin if you do not have this on hand. As a variation you can also add blanched green peas to the curry if you like. Dhingri Dolma is a perfect accompaniment for naan, tandoori roti or chapatis and can be served during a weekday dinner or lunch.', '["200 grams Button mushrooms , cleaned and cut into quarters", "100 grams Paneer (Homemade Cottage Cheese) , half of it cubed and the rest crumbled", "1 teaspoon Ajwain (Carom seeds)", "3 tablespoon Ghee", "1 Onion , finely chopped", "2 Tomatoes , finely chopped", "2 teaspoon Ginger Garlic Paste", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "2 tablespoon Cashew nuts , ground into paste with a little water", "Salt , to taste", "Sugar , a pinch", "Coriander (Dhania) Leaves , chopped for garnish"]'::jsonb, ARRAY['s button mushrooms', 's paneer', 'homemade cottage cheese', 'ajwain', 'carom seeds', 'ghee', 'onion', 'tomatoes', 'ginger garlic paste', 'cumin powder', 'jeera', 'coriander powder', 'dhania', 'garam masala powder', 'turmeric powder', 'haldi', 'red chilli powder', 'cashew nuts', 'salt', 'sugar', 'coriander']::text[], '["To begin making Dhingri Dolma first heat ghee in a pan.Add the shahjeera and once it sizzles, add the ginger-garlic paste and onion.Saute till the onion slightly turns brown.Add the tomatoes and cook till they turn soft.Add all the spices and mix well.Add mushrooms and cook for 1-2 minutes till they sweat.Add paneer cubes as well as the crumbled paneer.Add salt and sugar.Add cashew nut paste and add some water to make a thick gravy.Cook for 1-2 minutes, check the salt and spices and adjust accordingly.", "Once done turn off the heat and serve.Serve\u00a0Dhingri Dolma with\u00a0Butter Garlic Naan\u00a0and\u00a0Cauliflower & Cucumber Raita\u00a0for a delicious dinner."]'::jsonb, 45, 'Awadhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/DingriDhingri_Dolma_Awadhi_style_Mushroom_Paneer_masala.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/569.DingriDhingri_Dolma_Awadhi_style_Mushroom_Paneer_masala.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dahi Bhindi Recipe - Okra in Yogurt Curry with Caramelized Onions', 'dahi-bhindi-recipe-okra-in-yogurt-curry-with-caramelized-onions', 'Dahi Bhindi Recipe is a simple and delicious dish that is made from fresh yogurt, combined with gram flour, spices, and roasted bhindi, also known as okra. The addition of caramelized onions and roasted bhindi in spiced yogurt is a delight to the palate.', '["200 grams Bhindi (Lady Finger/Okra) , cut into 1 inch pieces", "1 Onion , finely chopped", "1 inch Ginger , grated", "1 cup Curd (Dahi / Yogurt)", "2 tablespoons Gram flour (besan)", "1 teaspoon Garam masala powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "Salt , to taste", "1 tablespoon Caramelized onions", "Oil , for cooking", "Ingredients for Seasoning", "2 tablespoons Ghee", "1 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies", "Coriander (Dhania) Leaves , a small bunch finely chopped"]'::jsonb, ARRAY['salt', 'coriander (dhania)', 'ginger', 'ghee', 'red chilli powder', 'gram flour (besan)', 'curd', 'dry red chillies', 'onion', 'cumin seeds (jeera)', 'bhindi (lady fingerokra)', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Dahi Bhindi Recipe, we will first roast the Bhindi .Heat 2 tablespoons of oil in a Wok or a Kadai; add the chopped onions and the bhindi (okra).", "Sprinkle some salt and saut\u00e9 the bhindi and the onions on low heat.", "Keep the pan covered for the few minutes so the bhindi gets cooked.When covered the bhindi releases moisture, but this moisture helps it to cook and soften as well.Once you notice that it has released a little moisture and the bhindi is slightly softened, open the pan and stir fry the bhindi until it is well roasted.", "Make sure you roast it on medium heat.", "Roast the Bhindi until you notice it has begun to shrink and has browned.", "It should not become sticky, slimy and gooey.", "If it has turned this way, add a little more oil and sprinkle some gram flour/besan and stir it gently.", "This will absorb the sliminess.The bhindi is a tricky vegetable to cook, so it takes some practice to not making it gooey.Once the bhindi is cooked and well roasted, keep it aside till we prepare the yogurt gravy.To make the Yogurt Curry, add the yogurt into a saucepan; add the gram flour, grated ginger, garam masala powder,\u00a0 turmeric powder and chili powder.", "Whisk until smooth.", "Add in 1/4 cup of water and whisk again until well combined.Place the saucepan on\u00a0a medium heat and allow the yogurt mixture to come to a brisk boil.", "Allow it to boil for a couple of minutes and then turn the heat to low.", "Simmer the mixture until the yogurt becomes thick and creamy.", "Once thick and creamy, add in the roasted bhindi and stir.", "Simmer for a few more minutes.", "Check the salt and spice levels and adjust to suit your taste.Turn off the heat and transfer the Dahi Bhindi a serving bowl.", "The final step is to make the seasoning.", "Heat a tablespoon of ghee in a Tadka Pan.", "Add the cumin seeds, dry red chilies and roast them until lightly browned.Pour this seasoning and the caramelized onions into the Dahi Bhindi.", "Stir to mix gently and finally stir in the chopped coriander leaves.Serve the Dahi Bhindi along with\u00a0Phulka Recipe\u00a0\u00a0or\u00a0Steamed Rice\u00a0and\u00a0\u00a0Green Moong Sprout Salad\u00a0for a simple weeknight dinner or even a weekend lunch."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Dahi_Bhindi_Sabzi_Okra_Yogurt_Curry_Recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/570.Dahi_Bhindi_Sabzi_Okra_Yogurt_Curry_Recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Shahjahani Khichdi Recipe - Spiced Green Moong Dal Khichdi', 'shahjahani-khichdi-recipe-spiced-green-moong-dal-khichdi', 'Shahjahani Khichdi Recipe which is a wholesome dish from the mughlai cuisine, where the green moong dal is cooked along with rice and tossed along with whole spices and cashew nuts.', '["1 cup Green Moong Dal (Whole)", "1 cup Rice", "1 Onion , chopped", "1/2 cup Fresh coconut , freshly grated", "Salt , to taste", "1 Cardamom (Elaichi) Pods/Seeds", "4 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 teaspoon Cumin seeds (Jeera)", "10 Cashew nuts", "3 tablespoons Ghee"]'::jsonb, ARRAY['green moong dal', 'whole', 'rice', 'onion', 'fresh coconut', 'salt', 'cardamom', 'elaichi', 'laung', 'cinnamon stick', 'dalchini', 'cumin seeds', 'jeera', 'cashew nuts', 's ghee']::text[], '["To begin making the Shahjahani Khichdi Recipe\u00a0we will soak the green moong dal and rice in water for 30 minutes in 4-1/2 cups of water and keep it aside.", "Heat a pressure cooker with ghee, add cumin seeds, cinnamon stick, cardamom pods and cloves and stir fry till they splutter.Add onions and saute till they turn translucent.Once the onions lightly lightly browned, add the rice and green moong along with the water into the pressure cooker.", "Sprinkle enough salt and give it a stir, cover and cook the Shahjahani Khichdi for around 5 to 6 whistles and turn off the heat.", "Allow the pressure to release naturally from the\u00a0Shahjahani Khichdi.Meanwhile heat a saucepan, add a tablespoon of ghee and toast the cashew nuts till they turn lightly golden brown.", "Stir in the cumin seeds and allow it to crackle.Once done turn off the heat.Once the pressure is released from the\u00a0Shahjahani Khichdi, open the lid and mix it up with some grated coconut & toasted cashew nuts tadka.", "Transfer the\u00a0Shahjahani Khichdi to a serving bowl and serve hot.Serve the\u00a0Shahjahani Khichdi Recipe\u00a0along with crispy\u00a0Aam Papad\u00a0,\u00a0Kela Anar Raita Recipe\u00a0for a wholesome lunch or dinner."]'::jsonb, 60, 'Mughlai', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Shahjahani_Khichdi_Recipe_Green_Moong_Dal_Rice.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/571.Shahjahani_Khichdi_Recipe_Green_Moong_Dal_Rice.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Assamese Narasingh Masor Jhol Recipe (Fish In Curry Leaves Gravy)', 'assamese-narasingh-masor-jhol-recipe-fish-in-curry-leaves-gravy', 'Assamese Narasingh Masor Jhol Recipe (Fish In Curry Leaves Gravy) is an authentic fish recipe from Assam in North East India. It consists of small whole river fishes or halved sardines or carps are cooked in a gravy made from curry leaves. Curry leaves is called as "Noro-singho" in Assamese. The fish curries in Assam do not use a lot of spices (unlike Bengali curries) and hence retains the natural flavour of the fish.', '["4 Sardine fish , or carps, cleaned & halved", "Curry leaves , 1 bunch", "4 Garlic", "2 Green Chillies , (adjust)", "1 tablespoon Whole Black Peppercorns , ground roughly", "1 teaspoon Turmeric powder (Haldi)", "3 Dry Red Chilli , (adjust)", "1 tablespoon Mustard oil", "Lukewarm Water , as needed"]'::jsonb, ARRAY['mustard oil', 'black peppercorns ground', 'sardine fish carps', 'water', 'dry red chilli', 'garlic', 'curry', 'turmeric powder', 'green chillies']::text[], '["To begin making Assamese Narasingh Masor Jhol Recipe (Fish In Curry Leaves Gravy), clean the fishes, their stomach and remove gills.", "Halve them if you have selected a little bigger fish like sardine.Marinate the sardines in turmeric and salt. (or any fish you have selected)Smear the mustard oil on a shallow fry pan and heat, on a medium heat till it is close to its smoking point (till the fumes arise from oil). (Do not allow the oil to come to smoking point if you are using cooking oil other than mustard oil)Make sure the pan is uniformly greased with oil,\u00a0Otherwise the fishes will stick to the frying pan.", "You can also use a lid to close the pan and hence retain the moisture within the pan, but you should keep checking and sauteing as required, just to be sure.Shallow fry the fishes on pan and one they are all cooked and tender, switch off heat.In a mixer grinder, grind curry leaves, pepper and a green chilli till a smooth paste, by adding a little water.In a kadai, heat a little mustard oil and once the oil is hot, add dry red chillies and crushed garlic.Add the curry leaves paste and saute.", "See at all times that the gravy does not get burnt.Add a pinch of turmeric powder and salt to taste.", "After mixing thoroughly, check for spices and adjust.Add 1/2 cup of warm water and cover cook for 2 to 3 minutes on medium flame.When the spices gets very well mixed together, add the fishes and simmer for 5 minutes in the gravy on a low heat, untill the spices get seeped inside the fishes.Serve\u00a0Assamese Narasingh Masor Jhol Recipe (Fish In Curry Leaves Gravy) along with steamed rice,\u00a0Egg Shoap Recipe | Assamese Appetizer\u00a0and\u00a0Nolen Gurer Payesh Recipe\u00a0for a complete meal."]'::jsonb, 20, 'Assamese', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/indranisen2003-gmail.com/Assamese_Narasingh_Masor_Jhol_Recipe_Fish_In_Curry_Leaves_Gravy-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/572.Assamese_Narasingh_Masor_Jhol_Recipe_Fish_In_Curry_Leaves_Gravy-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharashtrian Tomato Saar Recipe', 'maharashtrian-tomato-saar-recipe', 'Maharashtrian Tomato Saar Recipe is a simple and mildly spiced tomato broth made regularly in a Maharashtrian households. Serve the Maharashtrian Tomato Saar Recipe along with Steamed Rice and Papad for a light weeknight dinner.', '["4 Tomatoes , blanched", "4 cloves Garlic", "4 tablespoons Fresh coconut , grated", "1 teaspoon Cumin seeds (Jeera)", "3 Dry Red Chillies", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 pinch Asafoetida (hing)", "1 sprig Curry leaves", "2 teaspoons Oil", "Salt , to taste"]'::jsonb, ARRAY['tomatoes', 's garlic', 's fresh coconut', 'cumin seeds', 'jeera', 'dry red chillies', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing', 'curry leaves', 's oil', 'salt']::text[], '["To begin making\u00a0Maharashtrian Tomato Saar Recipe, take a saucepan and blanch the tomatoes in boiling water for 10 minutes, remove and place it in cold water while retaining the water in which it was boiling.When cool, peel the outer skin of the tomatoes and blend it to a smooth puree using a blending jar and keep aside.Now, grind the grated coconut, garlic, cumin seeds and 2 red chillies to a smooth seeds and keep aside.Heat oil in a pan, add the mustard seeds and let it splutter.Add the red chilli, asafoetida and curry leaves and let it crackle.Add the ground coconut mix and saute for 2 minutes, until the raw smell of the garlic goes away.Now, add the tomato puree and simmer for 2 minutes.Add 3 cups of water left over from blanching the tomatoes, season with salt and let it simmer for 10 minutes.Switch off the flame and serve the\u00a0the\u00a0Maharashtrian Tomato Saar Recipe along with Steamed Rice and Papad for a light weeknight dinner."]'::jsonb, 25, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Maharashtrian_Tomato_Saar_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/573.Maharashtrian_Tomato_Saar_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Style Tonak Alsanyache Recipe (Black eyed beans cooked in Tonak Masala Recipe)', 'goan-style-tonak-alsanyache-recipe-black-eyed-beans-cooked-in-tonak-masala-recipe', 'Goan Style Tonak Alsanyache Recipe (Black eyed beans cooked in Tonak Masala Recipe) is a typical Goan dish that is made from a legume and potatoes. The gravy is traditionally made from a red cow peas but the masala that is used in this gravy can be used for any legumes or vegetables.', '["1 cup Black Eyed Beans (Lobia)", "2 Potatoes (Aloo) , peeled and cut into medium pieces", "1/2 cup Tamarind Water", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Ingredients to roast and Grind", "2 Onion , sliced", "1/4 cup Fresh coconut , grated", "2 Green Chilli , slit", "4 cloves Garlic", "Tonak Masala", "1 tablespoon Coriander (Dhania) Seeds", "2 Cardamom (Elaichi) Pods/Seeds", "2 inch Cinnamon Stick (Dalchini)", "3 Dry Red Chillies", "2 teaspoon Whole Black Peppercorns", "5 Cloves (Laung)", "1 teaspoon Cumin seeds (Jeera)"]'::jsonb, ARRAY['salt', 'green chilli', 'tamarind water', 'coconut', 'cardamom (elaichi) podsseeds', 'cloves garlic', 'black peppercorns', 'coriander (dhania) seeds', 'onion', 'cinnamon stick (dalchini)', 'dry red chillies', 'cumin seeds (jeera)', 'cloves (laung)', 'potato (aloo)', 'turmeric powder', 'black eyed beans (lobia)']::text[], '["To begin making the Goan Style Tonak\u00a0 Alsanyache Recipe\u00a0 soak the black eyed peas in water for at least 2 hours.Heat a saut\u00e9ing pan with oil, add coriander seeds, dry red chillies, cinnamon, cardamom, peppercorns, cloves and cumin seeds.", "Fry until the aroma is released for about 10 seconds.Add the chopped onions, garlic, green chilies and saut\u00e9 until the onion turn translucent.", "Add freshly grated coconut and saut\u00e9 until the mixture turns golden brown.Switch off the heat, allow the mixture to rest.", "Add the saut\u00e9ed mixture in a mixer with water to a smooth paste.Heat a pressure cooker, add the ground paste, soaked legumes, turmeric powder, and salt and mix well.Add about 1/2 cup water and pressure cook the curry for about 3 whistle.", "Allow the pressure to release naturally and serve.Serve the Goan Style Tonak Alsanyache Recipe along with hot Pavs or\u00a0Phulka\u00a0along with a\u00a0goan fish fry\u00a0to enjoy your Sunday meal."]'::jsonb, 105, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Goan_Style_Tonak__Alsanyache_Recipe_Black_eyed_beans_cooked_in_Tonak_Masala_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/574.Goan_Style_Tonak__Alsanyache_Recipe_Black_eyed_beans_cooked_in_Tonak_Masala_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Khatti Meethi Tindora Sabzi Recipe - Gujarati Tindora Nu Shaak', 'khatti-meethi-tindora-sabzi-recipe-gujarati-tindora-nu-shaak', 'Tindora Nu Shaak or Khatti Meethi Tindora Recipe is a very simple and quick dish that is very native to India. Each region of India calls is by names like Dondaikkai, Kovakkai, Tinda, Tendly or Tindora.', '["500 grams Tindora (Dondakaya/ Kovakkai) , cut into rounds or thin slices lengthwise", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "SSP Asafoetida (Hing) , a few pinches", "1-1/2 teaspoon Amchur (Dry Mango Powder)", "Salt , to taste", "1 tablespoon Jaggery", "4 Curry leaves , roughly torn", "2 tablespoons Oil", "4 sprig Coriander (Dhania) Leaves , a small bunch (chopped)", "Raw Peanuts (Moongphali) , a handful of roasted peanuts, halved or pounded coarsely"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'amchur (dry mango powder)', 'mustard seeds', 'asafoetida (hing)', 'peanuts (moongphali) peanuts', 'jaggery', 'red chilli powder', 'tindora (dondakaya kovakkai)', 'curry leaves', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'coriander (dhania)', 'sunflower oil']::text[], '["To begin making the Khatti Meethi Tindora Recipe, we will first steam the vegetable in a steamer or a pressure cooker.", "If you are using a pressure cooker, cut the tinda into the desired shape, either into rounds or into think slices.", "Place the cut vegetable into the pressure cooker, sprinkle some salt and 2 tablespoons of water.Cover the pressure cooker, place the weight on and cook the tinda until you hear two whistles.", "After two whistles, turn off the heat.We will now release the pressure immediately, by running the pressure cooker under cold water.", "By doing this, we are making sure we don''t over cook the vegetable and at the same time retain the nutrition content.Open the pressure cooker once the pressure is released and keep it aside.Our next step is to season the vegetable with spices.", "Heat the oil in a large wok or a heavy bottomed pan.", "Once the oil is heated; add the mustard seeds and cumin seeds.", "Allow them to crackle.", "Next add in the curry leaves, the steamed vegetable and the remaining ingredients except the roasted peanuts and the chopped coriander.Saut\u00e9 the tindora sabzi until all the spices get well coated and combined onto the vegetable.The tindora sabzi will have a soft and juicy texture to it.", "Check the salt and spice levels and adjust to suit your taste.", "Turn off the heat once you achieve this consistency (about 3 to 4 minutes of stir frying).Finally stir in the peanuts and the chopped coriander leaves.", "Transfer the Tindora nu shaak to a serving bowl.Serve\u00a0Khatti Meethi Tindora Sabzi Recipe\u00a0along with\u00a0Gujarati Kadhi,\u00a0Methi Thepla\u00a0and\u00a0Steamed Rice\u00a0for a weekday dinner."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Khatti_Meethi_Tindora_Recipe_Gujarati_6_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/575.Khatti_Meethi_Tindora_Recipe_Gujarati_6_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hyderabadi Laziz Lamb Handi Recipe', 'hyderabadi-laziz-lamb-handi-recipe', 'A royal Hyderabadi lamb dish, Laziz Lamb Handi is an extremely rich and delicious prepared with assorted spices, cream, tomatoes, onion, ghee and chillies. Here the fun is to make this recipe in a handi, that definitely adds up the extra flavor with slow cooking. The succulent lamb pieces melt in your mouth exploring the aromatic spices and fresh onion tomato gravy paste blended in ghee. Add extra hot chillies to make it spicier. The roasted meat brings out the flavor of fat and that contributes to the satisfy along with Tawa Paratha or Jeera Rice for a weekend lunch or dinner.', '["700 grams Lamb ribs", "3 teaspoon Ghee", "5 teaspoon Curd (Dahi / Yogurt)", "4 teaspoon Kashmiri Red Chilli Powder", "5 teaspoon Ginger , paste", "10 Garlic", "Salt , to taste", "2 tablespoon Oil", "6 Onion , sliced", "1 teaspoon Garam masala powder", "2 teaspoon Tomato , paste", "3 Tomatoes", "3 teaspoon Fresh cream", "1 teaspoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "1 teaspoon Lemon juice", "11/2 cup Water", "Coriander (Dhania) Leaves , Few, chopped"]'::jsonb, ARRAY['tomato', 'salt', 'tomato paste', 'kashmiri red chilli powder', 'cumin powder (jeera)', 'coriander powder', 'ghee', 'lamb ribs', 'coriander (dhania) leaves', 'red chilli powder', 'water', 'curd', 'garlic', 'onion', 'lemon', 'ginger paste', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To make Hyderabadi Laziz Lamb Handi, first marinate the lamb ribs with salt, kashmiri, chilli powder, half ginger paste, curd and keep for 30 minutes.Heat a copper Handi with ghee and garlic for 1 minute.", "Add the meat and cook it for\u00a0about 5 minutes on high flame.", "Keep it aside.Add onion, ginger paste, bay leaf, whole garam masala, and fry till half caramelized.Now add red chilli powder, turmeric powder, cumin powder, coriander powder, salt, tomato, tomato paste and cook for about 10 minutes.After 10 minutes, add the lamb meat and water.", "Cover and cook until the meat\u00a0is fully cooked.Extra dry the gravy water if more than one-fourth water is left.", "Check for salt.Add garam masala powder, lime juice, cream and coriander leaves for garnish.", "The roasted meat brings out the flavor of fat and that contributes to the satisfy along with\u00a0Tawa Paratha\u00a0or\u00a0Jeera Rice\u00a0for a weekend lunch or dinner."]'::jsonb, 75, 'Punjabi', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/ruby_pathak-yahoo.com/Laziz_Lamb_Handi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/576.Laziz_Lamb_Handi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Marghi Na Farcha Recipe - Parsi Crispy Fried Chicken', 'marghi-na-farcha-recipe-parsi-crispy-fried-chicken', 'A Parsi version of fried chicken is Marghi na Farcha. Who can say no to fried chicken? Though I stay away from fried stuff most of the time, I do love to indulge in fried food once in a while and fried chicken is one of them. With delicate flavors, perfectly fried crispy chicken pieces – these are too good if you are love fried chicken.', '["300 grams Chicken thighs , preferable with bones", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1-1/2 inch Ginger", "6 cloves Garlic", "4 Green Chillies", "Salt , to taste", "1 Onion , chopped", "1 tablespoon Coriander (Dhania) Leaves , chopped", "1 teaspoon Cumin seeds (Jeera)", "1 inch Cinnamon Stick (Dalchini)", "1/2 cup Whole Wheat Bread crumbs , for coating", "Oil , required for deep frying"]'::jsonb, ARRAY['salt', 'ginger', 'coriander (dhania) leaves', 'chicken thighs preferable bs', 'red chilli powder', 'cloves garlic', 'onion', 'cumin seeds (jeera)', 'cinnamon stick (dalchini)', 'wheat bread crumbs', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Marghi Na Farcha recipe, pound cloves and cinnamon into powder in a mortar pestle.Into a blender add onions, green chilies, ginger, garlic cloves, cumin seeds, fresh coriander leaves and make a paste by adding very little water.Wash chicken well.", "Add red chili powder, turmeric powder, masala paste, cloves and cinnamon powder along with salt.", "Mix well.", "Leave the chicken pieces to marinate in the masala for 4 to 6 hours in the refrigerator.Heat oil in a deep bottom pan for frying.", "Coat the marinated chicken pieces in bread crumbs.Add the pieces to hot oil and fry until golden brown on all sides and chicken in cooked well.Remove from oil, and drain it on kitchen towel.", "Serve hot.Serve Marghi Na Farcha along with\u00a0Tomato Garlic Chutney\u00a0or\u00a0Mint Chutney\u00a0as party appetisers."]'::jsonb, 45, 'Parsi', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/Marghi_na_Farcha__Parsi_Crispy_Fried_Chicken.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/577.Marghi_na_Farcha__Parsi_Crispy_Fried_Chicken.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Style Chicken Pulao Recipe', 'kashmiri-style-chicken-pulao-recipe', 'Kashmiri Chicken Pulao Recipe is an aromatic rice recipe that is tossed with whole spices and chicken. The rice is made in a pressure cooker by roasting some whole spices and then adding curd mixed spice powders. By adding curd, it will help the rice to have a nice soft texture. The garnish of cashew nuts and almonds add richness to the pulao.', '["1 cup Rice , washed and soaked in water", "300 grams Chicken breasts , cut into small pieces", "1 Mace (Javitri)", "1 inch Cinnamon Stick (Dalchini)", "3 Cloves (Laung)", "1 Mace (Javitri)", "1 inch Ginger", "4 cloves Garlic , chopped", "1 Onion , sliced", "1 cup Curd (Dahi / Yogurt)", "1 tablespoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Black pepper powder", "1 tablespoon Cashew nuts", "5 Whole Almonds (Badam) , crushed", "Salt , to taste", "Oil"]'::jsonb, ARRAY['cashew nuts', 'salt', 'ginger', 'rice', 'red chilli powder', 'cloves garlic', 'curd', 'cinnamon stick (dalchini)', 'mace (javitri)', 'onion', 'badam (almond)', 'black pepper powder', 'coriander powder', 'chicken breasts', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Kashmiri Chicken Pulao Recipe, heat a pressure cooker with oil on medium flame, once the oil is hot add mace, cloves, cinnamon stick and let it sizzle.Once it sizzles, Aad ginger, garlic and saute for a couple of minutes.", "Add onions and saute them well till they turn translucent.In a mixing bowl, combine the curd along with red chilli powder, turmeric powder, coriander powder and pepper powder and whisk well.Turn down the heat and add this whisked curd into the saut\u00e9ed onions and mix well.", "Add chicken pieces and saute till the chicken is half cooked.", "This will take about 6 to 8 minutes.After 6 to 8 minutes, add in soaked and washed rice along with 1-1/2 cups of water.", "Sprinkle salt accordingly and stir well.", "Close the lid of the cooker and pressure cook for 2 whistles.After 2 whistes, switch off the gas and allow the pressure to release naturally.", "Open the cooker and fluff up the rice and mix it evenly with the masala.Garnish with cashew nuts and crushed almonds and serve hot.Serve the Kashmiri Chicken Pulao Recipe along with\u00a0Tomato Onion Cucumber Raita\u00a0,Carrot Cucumber Tomato Salad with Lemon and Coriander\u00a0by the side so it will make a complete meal."]'::jsonb, 40, 'Kashmiri', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Kashmiri_Chicken_Pulao_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/578.Kashmiri_Chicken_Pulao_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('No Onion And No Garlic Aloo Gajar Matar Ki Sabzi Recipe', 'no-onion-and-no-garlic-aloo-gajar-matar-ki-sabzi-recipe', 'Today’s recipe is Aloo Gajar Matar Ki Sabzi without onion and without garlic. This sabzi turns delicious and can be eaten on fasting days too. Now, the holy month of Shravan is going on and many people try pure veg dishes. Try this recipe and I am sure everyone at home will love it. You can pack this sabzi with rotis in tiffin too. The Aloo Gajar Matar Ki Sabzi is highly nutritious as carrots contain vitamin A, potatoes are rich in vitamin B6, vitamin C and Fibre.', '["2 Potatoes (Aloo) , peeled and cubed", "1 Carrot (Gajjar) , peeled and cubed", "1/2 cup Green peas (Matar)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1/4 teaspoon Asafoetida (hing)", "1 Green Chilli , slit", "Salt , to taste (kala namak if using for a fast)", "2 teaspoons Oil", "Coriander (Dhania) Leaves , as required for garnish"]'::jsonb, ARRAY['salt (kala namak using fast)', 'green chilli', 'mustard seeds', 'asafoetida (hing)', 'coriander (dhania) leaves', 'green peas (matar)', 'red chilli powder', 'carrot', 'curry leaves', 'cumin seeds (jeera)', 'potato (aloo)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the No Onion And No Garlic Aloo Gajar Matar Ki Sabzi recipe, Heat oil in a kadhai/wok.", "When oil gets heated add mustard seeds.After mustard seeds flutter, add cumin seeds.", "After cumin seeds flutter, add asafoetida and mix.Add curry leaves and fry for 2 minutes.", "Add the slit green chillies.Now add the cubed potatoes, cubed carrots and green peas.", "Add 1 cup water and simmer on low flame with closed lid till carrots and potatoes get boiled.", "This would take around 10-15 minutes.Open the lid and add turmeric powder and red chilli powder and mix well.", "Add salt to taste and garnish with chopped coriander leaves.Serve No Onion And No Garlic Aloo Gajar Matar Ki Sabzi with\u00a0Panchmel Dal\u00a0and\u00a0Phulka\u00a0for a weekday lunch or dinner."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Aloo_Gajar_Matar_ki_Sabzi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/579.Aloo_Gajar_Matar_ki_Sabzi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Special Huli Tovve Recipe', 'karnataka-special-huli-tovve-recipe', 'Huli Tovve is a speciality from Karnataka and is a must have curry in a traditional wedding meal. Huli Tovve is a kind of sambar made using ground masala with a lot of mixed vegetables.', '["1 cup Mixed vegetables , (french beans, carrot, pumpkin, potatoes)", "1/4 cup Raw Peanuts (Moongphali)", "1/2 cup Arhar dal (Split Toor Dal)", "Salt , to taste", "1 tablespoon Jaggery", "1/4 cup Fresh coconut , grated", "6 Dry Red Chillies", "1 tablespoon Chana dal (Bengal Gram Dal)", "1 tablespoon White Urad Dal (Split)", "1 inch Cinnamon Stick (Dalchini)", "1 tablespoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "Asafoetida (hing) , A pinch", "Curry leaves , as required"]'::jsonb, ARRAY['salt', 'arhar dal (split toor dal)', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'jaggery', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'cinnamon stick (dalchini)', 'peanuts (moongphali)', 'chana dal (bengal gram dal)', 'mixed vegetables (french beans', 'sunflower oil']::text[], '["To begin with Huli Tovve, wash and soak the toor dal till you prepare your vegetables.Wash and cut the vegetables.", "Pressure cook Toor dal, mixed vegetables and peanuts till they the cooker releases 3-4 whistles.The next step is to prepare the paste.", "Dry roast urad dal, chana dal, cinnamon and red chilli separately till they turn light gold.", "Add coconut to this and grind all of this into a smooth paste.Remove the lid after the cooker cools down.", "Add the ground paste to this and 2 cups of water, salt and jaggery and boil.", "Boil till the hulitovve thickens on high flame.For tempering, heat the oil in a tadka pan.", "Add mustard seeds and let it crackle.", "Add red chilly and curry leaves.", "Once they crisp up, add it to the hulitovve.Serve Huli Tovve with hot steamed rice and\u00a0Elai\u00a0Vadam."]'::jsonb, 40, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuri_Aggarwal/HuliTovve.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/580.HuliTovve.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kathal Biryani Recipe- Raw Jackfruit Biryani Topped with Caramelised Onions', 'kathal-biryani-recipe-raw-jackfruit-biryani-topped-with-caramelised-onions', 'Kathal Biryani is the most amazing one pot meal for the vegetarians who always wanted to know what a biryani means. Though it cannot be compared to the non veg version but still it somewhere reaches to the original flavor in it''s unique vegetarian version.', '["2 cups Basmati rice", "500 grams Jackfruit Raw (Kathal)", "2 tablespoons Ghee", "2 Onions , thinly sliced", "2 inch Ginger , finely chopped", "6 cloves Garlic , finely chopped", "2 Green Chillies , slit", "2 Bay leaves (tej patta)", "2 Cardamom (Elaichi) Pods/Seeds", "2 Brown cardamom (Badi Elaichi)", "4 Cloves (Laung)", "1 teaspoon Whole Black Peppercorns", "1 inch Cinnamon Stick (Dalchini)", "2 Star anise", "1 teaspoon Mace (Javitri)", "1/4 teaspoon Nutmeg powder", "1-1/2 teaspoons Red Chilli powder", "1 tablespoon Coriander Powder (Dhania)", "1 cup Curd (Dahi / Yogurt)", "Salt , to taste", "1/4 cup Mint Leaves (Pudina)", "Few Saffron strands , soaked in 1/2 cup milk", "1 cup Whole Wheat Flour", "2 tablespoons Oil", "3 Onions", "1 tablespoon Ghee", "1/4 cup Cashew nuts", "1/4 cup Sultana Raisins", "1/4 cup Mint Leaves (Pudina) , chopped"]'::jsonb, ARRAY['lemon', 'basmati rice', 'cloves (laung) cloves', 'coriander (dhania) leaves', 'cloves garlic', 'black peppercorns', 'onion', 'green chillies', 'black cardamom (badi elaichi)', 'salt', 'cardamom (elaichi) podsseeds', 'raisins', 'mace (javitri)', 'mint leaves (pudina)', 'star anise', 'nutmeg powder', 'red chilli powder', 'curd', 'jackfruit (kathal)', 'cashew nuts', 'ginger', 'saffron strands milk', 'bay leaves (tej patta)', 'ghee', 'cinnamon stick (dalchini)', 'coriander powder']::text[], '["To begin making the Kathal Biryani Recipe (Raw Jackfruit Biryani), first prep all the ingredients and keep ready/To cut raw jackfruit. grease hands and the knife that we are going to use to cut, with\u00a0 oil.", "This important tip ensures that the hands don''t get sticky from the natural fruit latex/sap present in the fruit does not get onto your hands and makes the cutting process hassle-free.", "Keep a bowl of water mixed with some salt to put the cut raw jackfruit pieces to avoid discolouration of the fruit.Dissolve the saffron in milk and keep aside.Into a large mixing bowl, add the flour and little water at a time to make a firm dough and keep aside.", "We will use this dough to seal the vessel to dum cook the biryani.Cut the the jackfruit in half, discard the skin and start making 1 inch pieces and soak them in the salted water.", "Keep asideTo make rice for the\u00a0Kathal Biryani\u00a0/ Jackfruit Biryani, wash and soak rice in water for 30 mins before you start cooking.In a heavy bottomed pan, heat water-twice the quantity of the rice.", "Add a tablespoon of ghee, salt and star anise into it.As soon as the water starts boiling, add rice and cook till 50% done.Once the rice is halved cooked to 50%, pass it through a strainer and collect the rice in a large tray and spread well so that they don''t stick to each other.To make Kathal ki yakhni, heat ghee in a large pan in which you plan to cook the\u00a0Kathal Biryani;\u00a0add the onion, ginger and garlic and saute until the onions turn slightly caramelised.Now add all the whole spices along with bay leaf in the remaining ghee.", "Allow them to sizzle.Once the onions are cooked, add the kathal pieces and yogurt, coriander powder, red chilli powder, nutmeg powder and and mix everything nicely so that the curd mixes well with the kathal.", "Give it one brisk boil and stir in the mint leaves and salt to taste.Pour the partially cooked rice over the jackfruit masala and level the rice evenly - do not stir the rice into the masala yet.", "Pour the saffron milk over the rice and place a lid over the pan.", "Now it''s time to seal the ends of the vessel with the dough for dum cooking.Elongate the dough into a large log and seal the Kathal Biryani Pan and the lid with the dough so, the flavours get contained in the pan and the steam does not escape as well.", "This helps to bring in the delicious flavours to the biryani.Turn the heat to low and cook the Kathal Biryani for about 20 minutes.", "You will begin to start getting the delicious aromas after about 10 - 12 minutes of cooking the biryani.After 20 minutes of dum cooking the Kathal Biryani, turn off the heat and allow the biryani to rest.Open the pan after 5 minutes of the resting period and give the Kathal Biryani a gentle stir, to combine all the masala and jackfruit into the rice.To caramelise the onions; heat oil in a pan over medium heat; add the sliced onions and keeps sauteing on low to medium heat until the onions get caramelised and crisp.", "Transfer to a bowl and keep asideFor Garnish,\u00a0heat ghee in the same pan; add the cashew nuts and roast them on medium heat until golden and crisp.", "Towards the end add the raisins and stir for a few seconds.", "Gently stir the caramelised onions and mint leaves into the Kathal Biryani and garnish with roasted cashews and serve hot.Serve the\u00a0Kathal Biryani\u00a0as a one dish meal for a weeknight dinner or as a party food along with\u00a0Sweet & Spicy Coriander Tadka Raita\u00a0and\u00a0Mirchi Ka Salan Recipe\u00a0for a sumptuous meal."]'::jsonb, 90, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shaheen_Ali/Kathal_Biryani__Raw_Jackfruit_Pilaf.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/581.Kathal_Biryani__Raw_Jackfruit_Pilaf.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hariyali Chicken Tikka Recipe', 'hariyali-chicken-tikka-recipe', 'Hariyali Chicken Tikka Recipe is a lip-smacking appetizer made with green masala thus the name “Hariyali”.', '["2 Chicken breasts , cut into cubes", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoon Garam masala powder", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Cumin powder (Jeera)", "1/4 cup Curd (Dahi / Yogurt)", "Salt , to taste", "To grind", "1 cup Coriander (Dhania) Leaves", "1 cup Mint Leaves (Pudina)", "1 Green Chilli"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'green chilli', 'amchur (dry mango powder)', 'coriander (dhania) leaves', 'red chilli powder', 'curd', 'mint leaves (pudina)', 'chicken breasts', 'turmeric powder', 'garam masala powder']::text[], '["To begin making the Hariyali Chicken Tikka Recipe, thoroughly wash and clean the chicken.", "Cut them into 1 inch cubes and set aside.", "In a mixer-jar combine the coriander leaves, mint leaves, green chilli and grind to a smooth paste, adding very little water.", "Transfer the green masala into a mixing bowl and add the yoghurt and the rest of the maslas which include-\u00a0red chilli powder,\u00a0\u00a0turmeric powder,\u00a0garam masala powder,\u00a0\u00a0amchur powder,\u00a0cumin powder and salt.", "Mix well and add the chicken pieces to this hariyali masala.", "Keep it aside for about 1 hour.Heat a grill pan, drizzle some oil, place the marinated chicken pieces and grill evenly on either side till you gets nicely charred.", "The chicken will take about 10 minutes to cook.Serve hot with sliced onions and lemon wedges.Serve the\u00a0Hariyali Chicken Tikka Recipe\u00a0along withlemon wedges,\u00a0Pudina Dahi Chutney Recipe\u00a0and serve other non-veg appetizers like\u00a0Kalmi Kabab Recipe\u00a0or\u00a0Chettinad Style Chicken Roast Recipe\u00a0at your dinner parties."]'::jsonb, 110, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/10-oct/Hariyali_Chicken_Tikka_Recipe-9373.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/582.Hariyali_Chicken_Tikka_Recipe-9373.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Traditional Bihari Litti Chokha Recipe', 'traditional-bihari-litti-chokha-recipe', 'Litti is a snack food found in India''s Bihar  and Nepalese state of Madhesh. It consists of wheat and sattu combined along with spiced and stuffed into maida balls and deep fried in ghee or baked in the oven.', '["Ingredients For Litti", "3-1/2 cups Whole Wheat Flour", "3/4 cup Ghee", "1/3 teaspoon Baking soda", "2 tablespoons Curd (Dahi / Yogurt)", "1/2 teaspoon Ajwain (Carom seeds)", "1 teaspoon Salt , to taste", "Lukewarm Water , to knead the flour", "Ingredients for Filling (Pitti)", "1-1/2 cups Roasted Gram Flour (Sattu Ka Atta)", "1 inch Ginger , grated", "2 cloves Garlic , grated", "2 Green Chillies , finely chopped", "Coriander (Dhania) Leaves , a small bunch finely chopped", "1/2 teaspoon Ajwain (Carom seeds)", "1/2 teaspoon Kalonji (Onion Nigella Seeds)", "1/2 teaspoon Fennel seeds (Saunf) , pounded", "1 tablespoon Mustard oil", "Salt , to taste", "1 teaspoon Lemon juice"]'::jsonb, ARRAY['salt', 'wheat flour', 'ginger', 'green chillies', 'coriander (dhania)', 'kalonji (onion nigella seeds)', 'ghee', 'fennel seeds (saunf)', 'mustard oil', 'ajwain (carom seeds)', 'cloves garlic', 'baking soda', 'curd', 'gram flour (sattu ka atta)', 'lemon', 'water knead the flour']::text[], '["To begin making the\u00a0Traditional Bihari Litti Chokha Recipe, we will first get all the ingredients ready and keep it by the aside.", "In a large mixing bowl, sieve flour, salt and baking soda in a large bowl.", "Add ajwain and ghee and mix everything well until you get coarse crumbs.", "Add warm water little at a time and knead to make a firm dough and smooth dough.", "Cover the dough in a wet muslin cloth and keep aside for 20 minutes.While the dough is resting, we will prepare the filling (pitti)In a large mixing bowl, mix sattu, ajwain, kalonji, fennel seeds, mustard oil, grated ginger, garlic, green chilies, coriander, salt and lemon juice.", "Stir well to combine all the ingredients.", "Check the salt and spices and adjust to suit your taste.", "If you find the mixture too dry, add a little water to make a lumpy mix (which is still dry and not completely wet).Keep this pitti mixture aside.The final step is to make the Litti.", "Place the rested dough on a flat counter and knead again for 5 minutes.", "Make small lemon sized balls from the dough and roll it like pooris.", "Hold the poori between your palm and fill 1 large tablespoon of pitti-sattu filling mixture into the dough.Gather the sides of the poori and bring them together on top and seal the ball.", "Press the ball gently to flatten it.Proceed to make Litti balls the similar way and arrange them on a greased baking sheet.", "Brush the litti with ghee, so the tops get crisp while baking.Preheat the oven to 180 C.", "Once the oven is preheated, place\u00a0place the litti tray on the middle rack and bake the littis till golden in color.", "Different ovens have different heating times - it an take anywhere between 20 to 30 minutes to bake and turn golden completely.Once baked, remove the Litti from the oven and allow them to cool a bit before serving.", "Serve the Litti Chokha along with\u00a0Aloo Choka\u00a0and\u00a0Baingan (Choka) Bharta, Yogurt & Pickled Green Chilies for lunch or dinner."]'::jsonb, 105, 'Bihari', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shaheen_Ali/Traditional_Bihari_Litti_Chokha_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/583.Traditional_Bihari_Litti_Chokha_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Shakarkand Beans Subzi Recipe (Spicy Sweet Potato Beans Stir fry)', 'shakarkand-beans-subzi-recipe-spicy-sweet-potato-beans-stir-fry', 'Shakarkand Beans Sabzi Recipe is a delicious preparation of boiled sweet potatoes sauteed along with steamed beans. The potatoes and beans are tossed in coriander powder and turmeric powder and seasoned with mustard and cumin. I like to add a dash of tanginess to the dish by adding juice from one lemon. The shakarkand beans sabzi goes well along with Punjabi Dal Tadka, Phulkas and Steamed Rice.', '["4 Sweet Potatoes , boiled, peeled and cubed.", "250 grams Green beans (French Beans) , cut into 1 inch length and steamed", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder , (adjust to suit your taste)", "Salt , to taste", "1 teaspoon Lemon juice"]'::jsonb, ARRAY['sweet potatoes', 's green beans', 'french beans', 'oil', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'coriander powder', 'dhania', 'turmeric powder', 'haldi', 'red chilli powder', 'salt', 'lemon juice']::text[], '["To begin making the Shakarkand Beans Sabzi Recipe, we will first cook the potatoes.", "See Video Recipe of How to Cook Potatoes in Pressure CookerNext cut the beans into desired shape, place it in the pressure cooker, add 2 tablespoons of water.", "Cover the cooker, place the weight on and pressure cook until you hear two whistles.", "After two whistles turn off the heat.", "Place the pressure cooker until cold running water to release the pressure immediately.", "We release the pressure immediately, so the green remain green and fresh.Our next step is to stir fry all the ingredients.", "Heat oil in a heavy bottomed pan; add in the mustard and cumin seeds and allow them to crackle.", "With\u00a0heat\u00a0on low, add in the coriander powder, turmeric powder and saute for a few seconds.Add in the sweet potato, the steamed beans, salt and red chilli\u00a0powder.", "Stir to combine well, sprinkle just a little water so the masala coats the vegetables well.", "Cover the pan and simmer for 5 minutes.After 5 minutes, turn off the heat, squeeze the lemon and stir.", "Transfer the\u00a0Shakarkand Beans Sabzi into a serving bowl.Serve the Shakarkand Beans Sabzi\u00a0along with\u00a0Punjabi Dal\u00a0Tadka,\u00a0Phulkas\u00a0and Steamed Rice."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Shakarkand_Beans_Sabzi_Recipe_Spicy_Sweet_Potato_Beans_Stirfry-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/584.Shakarkand_Beans_Sabzi_Recipe_Spicy_Sweet_Potato_Beans_Stirfry-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hunase Gojju Recipe', 'hunase-gojju-recipe', 'Hunase Gojju, tamarind curry is one of the most lip-smacking dish. Hunase gojju acts as a side dish. It gives you tangy flavour from tamarind and the spice touch through the chillies that are used. It is a thick gravy consistency dish which can be mixed with rice and had.', '["1 cup Tamarind Paste", "1/2 cup Jaggery", "1 teaspoon Rasam Powder , or red chilli powder", "Salt , to taste", "1 tablespoon Oil", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "10 Curry leaves", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 pinch Asafoetida (hing)", "4 to 5 Green Chilli , slit"]'::jsonb, ARRAY['salt', 'green chilli', 'rasam powder red chilli powder', 'mustard seeds', 'asafoetida (hing)', 'jaggery', 'curry leaves', 'methi seeds (fenugreek seeds)', 'tamarind paste', 'sunflower oil']::text[], '["To begin with, the Hunase Gojju Recipe, take deep pan and heat oil in it.", "As the oil heats up add mustard seeds, fenugreek, curry leaves, hing and chillies.", "Saute them thoroughly.Add the tamarind pulp, jaggery and rasam powder to the pan and let it cook for 2 minutes.", "Now\u00a0add 2 cups of water to the mixture and let it boil for about 15 minutes so that all the flavours are combined.", "And salt and taste according to your taste.", "The gojju will have a tangy, spicy and sweet taste, Serve it with rice and potato curry."]'::jsonb, 40, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuri_Aggarwal/Hunasee_Gojju.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/585.Hunasee_Gojju.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Style Chokh Vangun Recipe - Baingan Masala', 'kashmiri-style-chokh-vangun-recipe-baingan-masala', 'Chokh Vangun Recipe is a very popular eggplants dish from the Kashmiri Cuisine. The baby eggplants are first fried in mustard oil and then cooked in a spicy tart tamarind based gravy.', '["500 grams Small Brinjal (Baingan / Eggplant)", "4 Onions , sliced", "1 Tomato , thinly sliced", "1 Cinnamon Stick (Dalchini)", "3 Cardamom (Elaichi) Pods/Seeds", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoon Kashmiri Red Chilli Powder", "2 teaspoon Coriander Powder (Dhania)", "1 tablespoon Dry ginger powder", "2 teaspoons Fennel Powder", "2 tablespoons Tamarind Paste", "2 teaspoons Coriander (Dhania) Leaves , finely chopped for garnish", "3 tablespoons Mustard oil", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'kashmiri red chilli powder', 'mustard oil', 'cardamom (elaichi) podsseeds', 'brinjal (baingan eggsplant)', 'asafoetida (hing)', 'coriander (dhania) leaves', 'dry ginger powder', 'fennel powder', 'onion', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'tamarind paste', 'coriander powder', 'turmeric powder']::text[], '["To begin making the Chokh Vangun Recipe, wash, slit the baby eggplants into 4 from the bottom keeping the stack intact.", "Keep it immersed in a bowl of water until further use.Heat a tablespoon of mustard oil, let it smoke, drain the eggplants from water, pat it dry using a kitchen towel and add it to the pan.Fry until they a partly turned golden on the outside.", "Remove them in a plate and keep aside.Add another tablespoon of mustard oil in the same pan, bring it to a smoking level, add in the sliced onions and fry until they are turned nice golden and brown.Once cool, grind them into a smooth paste using a mixer grinder and keep aside.Heat the remaining tablespoon of mustard oil in a pan, let it smoke, add in the cinnamon stick, green cardamom and cumin seeds.Make a paste of the asafoetida, turmeric powder, coriander powder, kashmiri red chilli powder using little water and add it to the pan and cook until the oil separates.Add in the ground onion paste, dry ginger powder, tamarind extract and mix well.Let this mixture cook until the raw smell of the tamarind goes away.", "Now, add in the fried baby eggplants, sliced tomatoes, season with salt and mix well.Simmer this mixture until the tomatoes turns mushy and egg plants are cooked well.", "Add in the fennel powder and mix well.Simmer for another 5 minutes.", "Switch off the heat and garnish with coriander leaves.Serve the\u00a0Chokh Vangun Recipe along with\u00a0Lahsuni Dal,\u00a0Phulkas\u00a0and\u00a0Kachumber Salad\u00a0for a delightful weeknight dinner."]'::jsonb, 45, 'Kashmiri', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Chokh_Vangun_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/586.Chokh_Vangun_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rajasthani Style Mutton Banjara Recipe', 'rajasthani-style-mutton-banjara-recipe', 'The easiest Mutton Curry made with simple ingredients along with a simple recipe. No marination, no slow cooking, this recipe is apt for all who are in a rush to complete their dinner preparations. As the name says, Mutton Banjara, where Banjara means Gypsies. Hence the dish that is made in jiffy with the simplest ingredients in Mutton Banjara.', '["750 grams Mutton", "2 tablespoons Mustard oil", "2 Onion , thinly sliced", "10 cloves Garlic , finely chopped", "2 inch Ginger , finely chopped", "2 tablespoons Kashmiri Red Chilli Powder", "2 tablespoons Coriander Powder (Dhania)", "1 teaspoon Turmeric powder (Haldi)", "2 Bay leaf (tej patta)", "4 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "4 Cardamom (Elaichi) Pods/Seeds", "4 Whole Black Peppercorns , crushed", "4 Dry Red Chilli", "1/2 cup Curd (Dahi / Yogurt)", "Salt , to taste", "1 teaspoon Coriander (Dhania) Seeds , roasted and crushed", "6 sprigs Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['salt', 'sunflower oil', 'coriander powder', 'bay leaf (tej patta)', 'red chilli powder', 'black peppercorns', 'onion paste', 'curd', 'dry red chilli', 'coriander (dhania) seeds', 'cinnamon stick (dalchini)', 'mutton', 'ginger paste', 'turmeric powder', 'cloves (laung)', 'garlic paste']::text[], '["To begin making the Rajasthani Mutton Banjara recipe, prep all the ingredients and keep ready.Heat oil in a pressure cooker over medium heat; add the bay leaf, pepper, cloves, cinnamon, cardamom and dry red chilies and saut\u00e9 for a minute.", "Add the onion, ginger and garlic and saute until the onions soften and turns slightly brown.Add mutton along with curd and mix well and saute on high heat for 3 to 4 minutes.Now add coriander powder, red chilli powder, turmeric and salt and mix well.", "Add about 1/2 to 1 cup of water based on the gravy you would like.", "Pressure cook the Mutton Banjara for about 3 whistles.", "After 3 whistles turn the heat low and simmer for 10 minutes and turn off the heat.", "Allow the pressure to release immediately.Once done, stir in the crushed coriander seeds and chopped coriander leaves and serve hot.Serve Rajasthani Mutton Banjara along with Jeera Rice Recipe , Whole Wheat Onion Stuffed Kulcha and Mooli Raita For a delicious weekend meal."]'::jsonb, 50, 'Rajasthani', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/shaheen_ali/Mutton_Banjara_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/587.Mutton_Banjara_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Healthy Lauki Kofta Curry Recipe | Non Fried Bottle Gourd Kofta Curry | Dhoodi Kofta', 'healthy-lauki-kofta-curry-recipe-non-fried-bottle-gourd-kofta-curry-dhoodi-kofta', 'The Lauki/ Doodhi Kofta is a simple, healthy recipe where the koftas are not fried. Traditionally Kofta''s are fried and loose it nutritive value. But in this Lauki Kofta I have pan fried them in a Non-Stick Kuzhi Paniyaram Pan and simmer the kofta''s in a quick and simple spiced tomato gravy.', '["1 Bottle gourd (lauki) , peeled and grated (about 3 cups)", "1/4 cup Gram flour (besan)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Coriander (Dhania) Powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "Salt , to taste", "Oil , for cooking", "4 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "1 Green Chilli , split", "1 Onion , finely chopped", "1 inch Cinnamon Stick (Dalchini) , broken", "1 Bay leaf (tej patta) , torn", "2 Brown cardamom (Badi Elaichi)", "1 tablespoon Stone flower", "8 Tomatoes , cut into chuncks and pureed", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Garam masala powder", "1 tablespoon Honey", "8 sprig Coriander (Dhania) Leaves , chopped", "Salt , to taste", "1 tablespoons Ghee"]'::jsonb, ARRAY['bottle gourd', 'lauki', 'gram flour', 'besan', 'red chilli powder', 'coriander', 'dhania', 'turmeric powder', 'haldi', 'garam masala powder', 'salt', 'oil', 's garlic', 'ginger', 'reen chilli', 'onion', 'cinnamon stick', 'dalchini', 'bay leaf', 'tej patta', 'brown cardamom', 'badi elaichi', 'stone flower', 'tomatoes', 'coriander powder', 'honey', 's ghee']::text[], '["To begin making the Lauki Kofta Recipe, first prep all the ingredients and keep them ready.Peel and grate the bottle gourd and squeeze out the excess water from the grated bottle gourd and keep it aside.", "Mix all the ingredients for the kofta and divide into 12 to 15 portions.", "Into a large mixing bowl, add the grated lauki, turmeric, red chilli, coriander powder, garam masala, gram flour and salt to taste.", "Mix everything well.Preheat a Kuzhi Paniyaram and drizzle a little oil in each of the cavities; then place the kofta balls in the pan''s cavities; drizzle the kofta with a little oil and pan fry them until golden brown on both sides.", "You will have to flip the kofta balls so they fry on all sides evenly.", "Once done, keep the lauki kofta balls aside and we will use them only when we are ready to serve.For the kofta curry, add the cut tomatoes into the mixer grinder and puree it.", "Keep aside.Heat ghee in a heavy bottomed pan; add the ginger, garlic, green chilli and onion and saute until the onions soften.", "This will take 3 to 4 minutes.Once the onions have softened and turned lightly golden brown add the spices; cinnamon, bay leaves, badi elaichi and stone flour.", "Stir for a few seconds until you can smell the aromas coming through.Add the tomato puree, turmeric powder, garam masala powder, chilli powder, coriander powder, salt honey and simmer the kofta gravy for about 5 to 7 minutes until the raw smell from the tomatoes goes away.Once done, give the lauki kofta curry a taste and check the salt and spices and adjust accordingly.Once you are ready to serve, transfer the lauki kofta curry to a serving bowl.", "Place the pan fried lauki kofta and sprinkle fresh coriander leaves and serve hot.Serve the\u00a0Lauki Kofta Curry\u00a0along with\u00a0Palak Dal,\u00a0Phulka\u00a0and a\u00a0Paneer Pulav\u00a0for a delicious dinner along with laccha pyaz and lassi."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Healthy_Lauki_Kofta_Recipe_Non_Fried_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/588.Healthy_Lauki_Kofta_Recipe_Non_Fried_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Nawabi Mixed Vegetable Gravy Recipe', 'nawabi-mixed-vegetable-gravy-recipe', 'Nawabi Mixed Vegetables Recipe is a mildly spiced and rich dish without the use of cream in it. It is quite flavourful and simple to cook. It is easy to prepare and has a very royal taste to it.', '["1/2 cup Cauliflower (gobi)", "1/4 cup Green beans (French Beans) , cut in one inch pieces", "1/4 cup Carrots (Gajjar) , cubed", "1/4 cup Green peas (Matar)", "1 Bay leaf (tej patta)", "2 to 3 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 Onion , sliced", "1 Tomato , roughly chopped", "1 Green Chilli , slit", "2 teaspoons Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "Coriander (Dhania) Leaves , finely chopped for garnish", "2 tablespoons Ghee", "To grind to a smooth paste", "8 to 10 Cashew nuts , blanched", "1 Onion , blanched", "1 Tomato", "2 to 3 Garlic", "2 inch Ginger", "1/2 teaspoon Cumin seeds (Jeera)"]'::jsonb, ARRAY['tomato', 'cashew nuts', 'green beans (french beans)', 'ginger', 'green chilli', 'bay leaf (tej patta)', 'ghee', 'coriander (dhania) leaves', 'cauliflower (gobi)', 'green peas (matar)', 'red chilli powder', 'carrot', 'cinnamon stick (dalchini)', 'onion', 'garlic', 'cumin seeds (jeera)', 'coriander powder', 'cloves (laung)', 'garam masala powder']::text[], '["To begin making the Nawabi Mixed Vegetable Gravy, blanch the cashew nuts and onion in hot water for 2 minutes and drain it.Grind the blanched cashew nuts and onion along with chopped tomatoes, ginger, garlic and cumin seeds to a smooth paste using very little water in a mixer grinder and keep aside.Heat ghee in a wok/kadhai, add the whole spices including bay leaf, cloves and the cinnamon stick and let its flavour release into the ghee.Add the sliced onion and saut\u00e9 till it becomes golden brown.Add the chopped tomato and slit green chilli and stir for a few minutes.Now add the cut vegetables and mix well.", "Add the dry spice powders including coriander, chilli and garam masala powders and mix well.Season with a little salt, add 1/2 cup of water and let the vegetables cook with the lid closed.Once the vegetables are firmly cooked add the ground spice paste into the pan and stir well.Check for the salt seasoning and simmer for 10 minutes until the vegetables incorporates well along into the gravy.Switch off the flame and garnish with finely chopped coriander leaves.", "Serve Nawabi Mixed Vegetable Gravy at one of your house parties lunch menu along with\u00a0rotis,\u00a0Pudina tawa paratha\u00a0or\u00a0jeera rice."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Nawabi_Mixed_Vegetables_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/589.Nawabi_Mixed_Vegetables_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer Kofta Curry Recipe -Non Fried', 'paneer-kofta-curry-recipe-non-fried', 'The Paneer Kofta Curry Recipe is a delicious preparation paneer (homemade cottage cheese) that is simmered in a spiced tomato gravy. Kofta''s are traditionally deep fried vegetable or cheese balls that are dipped in a spicy curry. This recipe of kofta is healthy as the kofta''s are not deep fried but instead made in a kuzhi paniyaram pan. If you do not have this pan, then you can bake it in the oven too and you will get the same result. The gravy is something that I make all the time is mild and sattvic without the addition of onion and garlic. The result is an absolutely delicious curry!', '["Ingredients for Paneer Kofta", "250 grams Paneer (Homemade Cottage Cheese)", "3 tablespoons All Purpose Flour (Maida)", "1 pinch Salt", "Coriander (Dhania) Leaves , small bunch, finely chopped", "1 teaspoon Cumin powder (Jeera)", "Ingredients for Gravy", "1 Ginger , grated", "1 tablespoon Honey", "2 cups Homemade tomato puree", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 cup Hung Curd (Greek Yogurt) , (or cream)", "Kasuri Methi (Dried Fenugreek Leaves) , for garnishing", "Salt , to taste", "Oil , for cooking"]'::jsonb, ARRAY['ingredients for paneer kofta', 's paneer', 'homemade cottage cheese', 's all purpose flour', 'maida', 'salt', 'coriander', 'dhania', 'cumin powder', 'jeera', 'ingredients for gravy', 'inger', 'honey', 's homemade tomato puree', 'coriander powder', 'garam masala powder', 'turmeric powder', 'haldi', 'hung curd', 'greek yogurt', 'kasuri methi', 'dried fenugreek leaves', 'oil']::text[], '["Combine all the ingredients for the koftas in a bowl and knead well until you can get dough of the paneer.", "The dough will be firm and yet soft enough to shape into balls.", "Our next step is to bake them or pan fry them in the kuzhi paniyaram pan."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Paneer_Kofta_Curry_Recipe_Using_Non_Sweetened_Rasgulla_Balls-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/590.Paneer_Kofta_Curry_Recipe_Using_Non_Sweetened_Rasgulla_Balls-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Parshe Macher Jhal Recipe - Mullet In Mustard Sauce', 'parshe-macher-jhal-recipe-mullet-in-mustard-sauce', 'In Parshe Macher Jhal, Mullet is cooked whole in a hot mustard sauce and flavoured with goodness of coriander leaves. It is easy to make and mustard sauce adds an extra flavour to it.', '["8 Parshe , (mullet fish)", "5 tablespoons Kasundi mustard sauce", "2 Tomatoes , puree", "5 Green Chillies , slit", "2 teaspoon Turmeric powder (Haldi)", "2 teaspoon Red Chilli powder", "2 teaspoon Kalonji (Onion Nigella Seeds)", "5 tablespoons Mustard oil", "1/2 cup Coriander (Dhania) Leaves , chopped", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'kasundi mustard sauce', 'kalonji (onion nigella seeds)', 'mustard oil', 'coriander (dhania) leaves', 'red chilli powder', 'parshe (mullet fish)', 'turmeric powder', 'green chillies']::text[], '["To begin making the Parshe Macher Jhal Recipe, firstly marinate the fish with turmeric powder and salt.", "Keep it aside for 5 minutes.Next, heat mustard oil in frying pan and fry the fish till it turns light brown on both the sides.", "Keep the fish aside.Reheat the same oil, add the kalonji seeds and green chillies.", "When the seeds start to crackle, add the tomato puree, remaining turmeric powder, red chilli powder and salt.Cook on a moderate flame till oil has been released from the masala paste.At this stage, add about 1-1/2 cups of warm water, give it a nice stir and bring the curry to a boil.Adjust the salt, add the fried fish, mustard paste and cook for a further 3 to 4 minutes.", "Add the coriander leaves and serve hot.Serve Parshe Macher Jhal along with\u00a0Steamed Rice\u00a0and\u00a0Bengali Style Cholar Dal\u00a0for your weekday meal."]'::jsonb, 35, 'Bengali', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/maumita.paulghosh-gmail.com/Parshe_Maacher_Jhal_Mullet_in_Mustard_Sauce.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/591.Parshe_Maacher_Jhal_Mullet_in_Mustard_Sauce.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dondakkai Puli Curry Recipe - South Indian Style Tindora Curry', 'dondakkai-puli-curry-recipe-south-indian-style-tindora-curry', 'Dondakkai Puli Curry is one of those traditional recipes that has been passed down to me through generations. This is a healthy recipe to prepare and also does not take too much time or effort. As it is very easy to make and requires very few ingredients, you can also pack it for your Lunch Box.', '["150 grams Tindora (Dondakaya/ Kovakkai)", "3 tablespoons Black Urad Dal (Split)", "5 Dry Red Chillies", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Turmeric powder (Haldi)", "2 teaspoon Tamarind Paste , (adjust)", "Salt , to taste", "1 teaspoon Oil", "2 teaspoons Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)"]'::jsonb, ARRAY['s tindora', 'dondakaya/ kovakkai', 's black urad dal', 'split', 'dry red chillies', 'cumin seeds', 'jeera', 'turmeric powder', 'haldi', 'tamarind paste', 'salt', 'oil', 's oil', 'mustard seeds', 'rai/ kadugu']::text[], '["To begin making the Dondakkai Puli Curry Recipe, first wash and cut the dondakkai\u00a0into small pieces, I prefer dividing it into four sections and chopping it into fine triangles.Clean and soak the tamarind in enough water for at least 10 minutes.Boil the chopped dondakkai/tindora in enough water until its tender but not mushy, we need a bite to it, so say until 90 percent done.", "Later, drain the water and set aside until use.Heat up a small Saucepan\u00a0with a teaspoon of oil and once hot add the cumin seeds, garlic cloves and red chillies, fry them for a minute, Later add the urad dal and saute until the dal turns golden in color.Next turn off the heat and allow them to cool at room temperature.In a mixer grinder, add the roasted, soaked tamarind, turmeric, salt and grind it into a smooth paste adding the water in which the tamarind was soaked, if required.Now in a bowl, add the boiled dondakkai, ground paste and give it a good stir until combined well.Now for the tempering, in a small sauce pan add the remaining tablespoon of oil and heat it, add the mustard and cumin seeds, allow them to pop and add it to the dondakkai\u00a0mixture.", "Mix and serve hot.Serve\u00a0Dondakkai Puli Curry Recipe\u00a0along with\u00a0Keerai Sambar,\u00a0Steamed Rice\u00a0and\u00a0Elai Vadam\u00a0for your everyday meals."]'::jsonb, 45, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Swapna/Dondakaya__small_gourd_Pachhadi__original.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/592.Dondakaya__small_gourd_Pachhadi__original.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rase Wale Aloo Recipe (Boiled Potato in Tangy Tomato Sauce)', 'rase-wale-aloo-recipe-boiled-potato-in-tangy-tomato-sauce', 'I think this is one of the easiest and most tasty preparation of boiled potatoes. I love the tanginess of the sauce and it just goes so well with puri. This is an easy recipe which can be made for lunch or dinner and can also be served when you have guests at home.', '["6 Potatoes (Aloo) , freshly boiled (roughly chopped)", "4 Tomatoes , pureed", "Oil , as required", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "Salt , as per taste", "Red Chilli powder , as per taste", "1 teaspoon Sugar", "1/4 Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera) , roasted", "1/4 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'asafoetida (hing)', 'red chilli powder', 'sugar', 'cumin seeds (jeera)', 'coriander powder', 'potato (aloo)', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Rase Wale Aloo recipe, in a heavy bottomed pan heat oil and temper the jeera and hing.Add tomato puree and cook till all the moisture reduces.", "Add all the masalas and sugar.", "Cook for another 30 seconds.Add the potatoes and add 1 glass water (250ml) and let it cook and reduce further to a thick consistency.Mash some of the potatoes in the gravy to get that typical rase wale aloo.", "Serve Rase Wale Aloo along with\u00a0Puri\u00a0or\u00a0Pudina Tawa Paratha\u00a0for lunch or dinner."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Avin_Kohli/rase_wale_alooo_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/593.rase_wale_alooo_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mamidikaya Pappu Recipe - Andhra Raw Mango Dal', 'mamidikaya-pappu-recipe-andhra-raw-mango-dal', 'Mamidikaya Pappu Recipe is an easy dal recipe and the inclusion of raw mango gives a perfect twist to our regular dal dish. This Dal is full of flavour owing to the tanginess of the raw mango and with the addition of toor dal it gives a creamy texture to the dal made. This dal also goes by name of Pachi Mamidikaya Pappu or Mango Pappu Charu', '["2 Green Chillies , slit", "1 cup Arhar dal (Split Toor Dal)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 Mango (Raw) , peeled and diced", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1/2 cup Water", "Salt , to taste", "1 teaspoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 cloves Garlic , cfushed", "2 Dry Red Chillies", "2 sprig Curry leaves", "6 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['reen chillies', 'arhar dal', 'split toor dal', 'turmeric powder', 'haldi', 'salt', 'mango', 'raw', 'red chilli powder', 'water', 'ghee', 'mustard seeds', 'rai/ kadugu', 's garlic', 'dry red chillies', 'curry leaves', 'coriander', 'dhania']::text[], '["To begin making the Mamidikaya Pappu Recipe, prep all the ingredients and keep them ready.In a pressure cooker, combine the toor dal along with 2 cups of water, salt, turmeric powder and green chillies.", "Close the lid and pressure cook for 4 whistles.", "Turn off the heat and allow the pressure cooker to release the pressure naturally.", "Once the pressure has released, open the cooker, and mash the dal with the back of the ladle and set aside.", "To cook the mangoes, into a pressure cooker add the mangoes, a little salt, turmeric powder, red chilli powder and 1/2 cup of water.", "Pressure cook for 2 whistles and turn off the heat.", "Allow the pressure to release naturally.Heat ghee in a saucepan over medium flame; add the mustard seeds, red chillies and allow it to crackle.Next, add the garlic and saute until the garlic lightly changes colour.", "Do not darken it to brownOnce done, stir in the curry leaves, cooked raw mangoes and cooked toor dal.", "Adjust the consistency by adding a little water.", "Check the salt and adjust to taste as well.Give Mamidikaya Pappu a brisk boil for about 3 to 4 minutes and turn off the heat.", "Garnish with coriander leaves and serve hot.Serve\u00a0Mamidikaya Pappu Recipe (Raw Mango Dal) with\u00a0Panasa Pottu Aava Koora Recipe- Andhra style Mustard Flavoured Raw Jackfruit Curry\u00a0and steamed rice with\u00a0Andhra Style Paruppu Podi Recipe (Dal Podi)\u00a0to make it a complete Andhra style meal."]'::jsonb, 40, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pooja/Mamidikaya_Pappu_Recipe_Andhra_Raw__Mango_Dal_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/594.Mamidikaya_Pappu_Recipe_Andhra_Raw__Mango_Dal_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer Biryani Recipe', 'paneer-biryani-recipe', 'Paneer Biryani is a family favorite at home. Short grain jeera samba rice is cooked in a classic onion-tomato masala along with whole spices like cardamom, cinnamon, cloves and bay leaves that lend robust flavour to the biryani.', '["2 cups Seeraga (Jeeraga) Samba rice", "250 grams Paneer (Homemade Cottage Cheese) , cut into medium sized cubes", "2 Onions , thinly sliced", "4 Tomatoes , finely chopped", "2 inch Ginger , finely chopped", "6 cloves Garlic , finely chopped", "2 Green Chillies , slit", "3 Cloves (Laung)", "2 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "2 Bay leaves (tej patta)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander (Dhania) Powder", "120 ml Coconut milk", "1/2 cup Mint Leaves (Pudina) , finely chopped", "2 tablespoons Ghee", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'turmeric powder', 'salt', 'ginger', 'rice', 'ghee', 'cinnamon', 'red chilli powder', 'mint', 'onion', 'garlic', 'coriander powder', 'cottage cheese', 'cardamom', 'bay leaves', 'oil', 'green chillies', 'pepper']::text[], '["To begin making the Paneer Biryani Recipe, prepare all the ingredients and keep them ready for cooking.Wash and rinse the rice in water and keep aside.Heat ghee in the pressure cooker over medium heat; add the onion, ginger and garlic and saute until the onions have softened and turned slightly brown.", "Stir in the spices - cardamom, cloves, cinnamon and bay leaves and saute for a couple of minutes.Stir in chopped tomatoes along with turmeric powder, chili powder and coriander powder.", "Saute until the tomatoes become mushy and soft.To put the paneer biryani together, add the paneer, rice, coconut milk and salt.", "Stir well to combine.", "Add 1-\u00bd cups of water and over the pressure cooker.Pressure cook for 2 whistles.", "After 2 whistles, turn the heat to low and simmer for 3 to 4 minutes and turn off the heat.Allow the pressure to release naturally.", "Once the pressure is released, open the cooker, wait for a few minutes and then add the chopped pudina leaves and stir to combine the Paneer Biryani.", "Serve hot Paneer Biryani along with\u00a0Onion Raita Recipe - Pyaz Ka Raita Recipe\u00a0for a simple soulful meal."]'::jsonb, 55, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Priya__Suresh/Paneer_Biryani_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/595.Paneer_Biryani_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Pattani Kurma Recipe - Chettinad Peas Curry', 'chettinad-pattani-kurma-recipe-chettinad-peas-curry', 'Chettinad Pattani Kurma Recipe is a classic kurma recipe. Fragrant spices like cloves, cinnamom, cardamom all roasted and combined with coconut to make the base masala. Added steamed green peas and giving a crunch to this soulful kurma recipe is the curry leaf tadka.', '["1 teaspoon Oil", "1 tablespoon Roasted Gram Dal (Pottukadalai)", "1/2 teaspoon Poppy seeds", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Fennel seeds (Saunf)", "1 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "1 Cardamom (Elaichi) Pods/Seeds", "1/2 cup Fresh coconut", "5 cloves Garlic", "1 inch Ginger , roughly chopped", "2 Green Chillies , roughly chopped", "1/2 teaspoon Red Chilli powder", "Other Ingredients", "1 tablespoon Oil", "2 sprig Curry leaves", "1/2 cup Pearl onions (Sambar Onions) , finely chopped", "1 Tomato , finely chopped", "1/2 cup Tamarind Water", "1 cup Green peas (Matar)", "Salt , to taste", "1 sprig Curry leaves", "Salt , to taste"]'::jsonb, ARRAY['oil', 'roasted gram dal', 'pottukadalai', 'poppy seeds', 'cumin seeds', 'jeera', 'fennel seeds', 'saunf', 'cinnamon stick', 'dalchini', 'laung', 'cardamom', 'elaichi', 'fresh coconut', 's garlic', 'ginger', 'reen chillies', 'red chilli powder', 'other ingredients', 'curry leaves', 'pearl onions', 'sambar onions', 'tomato', 'tamarind water', 'green peas', 'matar', 'salt']::text[], '["To begin making the Chettinad Pattani Kurma Recipe, firstly we need to prep for the coconut masala.", "To make the coconut masala, heat oil in a pan on medium heat.", "Add the cumin seeds, pottu kadalai, poppy seeds, cloves, cinnamon, saunf, and cardamom.", "Roast for a few seconds until you notice the seeds are crackling and the aroma wafts the air.", "Add the ginger, garlic, green chillies and coconut and lightly roast until the coconut changes colour.", "Turn off the heat and allow the chettinad kurma masala to cool.", "Add all the ingredients into a medium jar of mixer grinder along with the chilli powder.", "Add a little warm water and blend to make a smooth paste.", "Turn off the flame and allow it to cool.", "After it has cooled transfer the coconut masala ingredients into a mixer jar and grind to a smooth paste using some water.", "Set aside this freshly ground coconut masala for the Chettinad Pattani Kurma.", "To make the Chettinad Pattani Kurma, place the peas in the pressure cooker, along with a little salt and half cup of water.", "Pressure cook for 3 whistles and turn off the heat.", "Release the pressure immediately to retain the fresh green colour of the peas.Heat oil in a pan, add the onion and saute until it softens and changes colour to pinkish brown.", "Stir in the curry leaves, tomato and saute until the tomatoes turn mushy.", "When this onion-tomato mixture comes together, add in the freshly ground coconut masala, cooked green peas and salt to taste.", "Add\u00a0 the tamarind water and additional water to adjust to the consistency of the kurma you prefer.", "Typically a kurma is a little thick.Give the Chettinad Pattani Kurma a brisk boil\u00a0 for 3 to 4 minutes and turn off the heat and serve hot.", "Serve\u00a0Chettinad Pattani Kurma along with\u00a0Malabar Parotta Recipe - Kerala Parotta Recipe\u00a0and\u00a0Cucumber Pineapple Raw Mango Salad Recipe\u00a0for a simple weekend dinner."]'::jsonb, 35, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Chettinad_Pattani_Kurma_Recipe_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/596.Chettinad_Pattani_Kurma_Recipe_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Konkani Style Sungta Ambat Aani Tallel Sungta Recipe- Fried Prawns & Curry', 'konkani-style-sungta-ambat-aani-tallel-sungta-recipe-fried-prawns-curry', 'Sungta Ambat Aani Tallel Sungta is what they call the prawn''s curry and fried prawns in the Konkani language. This is a recipe from the Karwari GSB cuisine. Karwar, a city in Karnataka, lies at the mouth of the river Kali. With the abundance of fish and coconuts in that area, the Karwari GSBs are thorough fish eaters and the gravies they cook are made using coconut.', '["20 Prawns", "1 cup Fresh coconut , grated", "2 teaspoons Coriander (Dhania) Seeds", "3 Whole Black Peppercorns", "4 Byadagi Dried Chillies , broken", "1 teaspoon Tamarind", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder , adjustable", "2 Onions , chopped", "1 Potato (Aloo) , peel and cut the potatoes", "2 tablespoons Oil , for the gravy", "Oil , for roasting the spices", "Salt , to taste", "10 Prawns", "2 teaspoons Lemon juice", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/4 cup Rice flour", "1/4 cup Sooji (Semolina/ Rava)", "Salt , to taste", "Oil , for frying"]'::jsonb, ARRAY['salt', 'sunflower oil the gravy', 'rice flour', 'coconut', 'red chilli powder', 'black peppercorns', 'byadagi dried chillies', 'coriander (dhania) seeds', 'onion', 'potato (aloo) the potatoes', 'lemon', 'sunflower oil roasting the spices', 'sooji (semolina rava)', 'coriander powder', 'tamarind', 'turmeric powder', 'prawns', 'sunflower oil']::text[], '["To begin making the Sungta Ambat Aani Tallel Sungta recipe, firstly we will prepare the curry.Devein the prawns and wash thoroughly.", "Apply a little turmeric powder and very tiny amount of salt to the curry prawns and keep it aside.", "Heat a little oil in a heavy bottomed pan and add coriander seeds and bydagi chillies.", "Cook for about a minute.Add this mixture along with\u00a0coconut, peppercorns, tamarind and almost 1/4 piece of the given onion using sufficient water in a mixer grinder.", "Grind it and keep it aside.", "Heat oil in a heavy bottomed pan.", "Once the oil is hot, add the chopped onions.", "Saute till they turn soft and transparent.", "Once the onion turns soft, add turmeric powder and mix well.", "After a minute add potatoes and red chilli powder.", "Mix, cook for a minute\u00a0and add enough water to almost cover the potatoes.", "Cover and cook.", "When the potatoes are half cooked, add the prawns and mix.", "Add salt.", "Cover and cook till both potatoes and the prawns are cooked.Now add the ground coconut paste to it, mix \u00a0and check if more water is required to bring the gravy to a medium consistency.", "Bring to a boil.", "Check seasoning.", "Simmer for few minutes for the coconut to be cooked.", "If the gravy thickens by now, add some water and adjust desired consistency.", "Cook for another 2 minutes and serve.The next step is to make the fried prawns.", "Add prawns,\u00a0lime juice, spice powders and salt in a mixing bowl.", "Mix everything well and keep aside to marinate.Mix together rice flour add semolina together in a bowl to get a grainy consistency.", "Coat the marinated prawns well with this flour mixture and shallow fry in hot oil on both sides on low flame.", "Serve Sungta Aambat Aani Tallel Sungta along with\u00a0Steamed Rice\u00a0and\u00a0Sol Kadhi\u00a0for a perfect and delicious Konkani Meal."]'::jsonb, 55, 'Konkan', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/panditp253-gmail.com/SUNGTA_AAMBAT_AANI_TALLEL_SUNGTA_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/597.SUNGTA_AAMBAT_AANI_TALLEL_SUNGTA_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Hurigadale Tambittu Recipe - Gram Flour Ladoo', 'karnataka-style-hurigadale-tambittu-recipe-gram-flour-ladoo', 'Karnataka Style Hurigadale Tambittu Recipe is a traditional dessert from Karnataka. The dessert is mainly prepared during the festival time as an offering to God. The laddu is made with simple ingredients and mixed together to form a soft and chewy texture which is then shaped into ladoos and served.The sweetness from the jaggery and the nuttiness from the gram flour is rightly paired and balanced with flakes of grated coconut.', '["3 cups Gram flour (besan)", "1 cup Ghee", "2 cups Jaggery , powdered", "1 cup Dessicated Coconut", "4 teaspoons Cardamom Powder (Elaichi)"]'::jsonb, ARRAY['s gram flour', 'besan', 'ghee', 's jaggery', 'dessicated coconut', 's cardamom powder', 'elaichi']::text[], '["To begin making the Karnataka Style Hurigadale Tambittu Recipe (Gram flour Ladoo Recipe), prep the ingredients and keep them ready.Heat a pan over medium heat ; add the gram flour (besan) and roast on medium heat until you get a roasted aroma.", "The raw smell needs to go away.", "This will take around 7 to 10 minutes on medium heat.", "Stir in the dry coconut into the besan and roast it for another minute.", "Once done, turn off the heat, transfer the besan and coconut into a large kitchen paper towel and keep aside to cool.Heat ghee in the same pan and allow it to melt.", "Once melted stir in the jaggery and allow it to melt as well.", "The jaggery will slowly start to bubble and combine with ghee.", "At this stage can add the cardamom powder and mix well.Gradually stir in the add the flour and dry coconut mixture slowly and simultaneously keep mix it so that there are no lumps formed.You will have a consistency of thick halwa, keep stirring for a couple of more minutes and turn it off the heat.Allow the\u00a0Hurigadale Tambittu mixture to cool little bit so that you can start making small ladoos.Smear a little ghee palm and fingers.", "Take out small portion of the\u00a0Hurigadale Tambittu mixture\u00a0and roll it into a small bite size ladoos.", "Proceed the same way with the remaining Hurigadale Tambittu mixture.Once ready, store the\u00a0Hurigadale Tambittu in airtight boxes and it will last for 3 to 4 weeks when kept refrigerated.", "Serve the\u00a0Karnataka Hurigadale Tambittu\u00a0as a high protein sweet after lunch or dinner."]'::jsonb, 45, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Karanatak_Style_Hurigadle_Tambittu_Recipe_Gram_flour_Laddoo_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/598.Karanatak_Style_Hurigadle_Tambittu_Recipe_Gram_flour_Laddoo_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Aloo Jhinge Posto Curry Recipe (Potato and Ridge Gourd Curry)', 'bengali-aloo-jhinge-posto-curry-recipe-potato-and-ridge-gourd-curry', 'The Aloo Jhinge Posto Curry Recipe is a classic dish from the Bengali Cuisine, that is made from potaoes and ridge gourd, simmered in a poppy seeds curry. The addition of poppy seeds and green chilies makes it a very quintessential Bengali dish adding to the texture and pungent taste.', '["1 Ridge Gourd (Turai/ Peerkangai) , peeled and diced", "2 Potatoes (Aloo) , boiled and diced", "1 teaspoon Kalonji (Onion Nigella Seeds)", "1 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Sugar", "Salt , to taste", "Mustard oil , for cooking", "To Be Ground To Paste", "2 tablespoon Poppy seeds", "1 Dry Red Chilli", "2 Green Chillies"]'::jsonb, ARRAY['salt', 'kalonji (onion nigella seeds)', 'mustard oil', 'ridge gourd (turai peerkangai)', 'dry red chilli', 'sugar', 'poppy seeds', 'potato (aloo)', 'turmeric powder', 'green chillies']::text[], '["To begin making the\u00a0Bengali Aloo Jhinge Posto Curry Recipe (Potato and Ridge Gourd Curry), first prep all the ingredients and keep aside.", "Boil the potatoes, peel the skin and cut them into diced.", "Similarly cut the Jhinge (ridge gourd into dices).Grind the poppy seeds, dry red chilies and green chilies into a smooth paste, adding 2 to 3 tablespoons of water.", "Keep this aside.In a Kadai/ Heavy Bottomed Pan, add the kalonji seeds and allow it to crackle.", "Add the ridge gourd, sprinkle some salt and allow it to cook until done.", "This takes about 4 to 5 minutes.", "Keep the pan covered while cooking the gourd.Once the gourd is cooked, add the potatoes, the ground poppy seed paste, the salt, sugar, turmeric powder and just a little water.", "Ridge gourd also released water when it is getting cooked.", "Simmer and cook the jhinge aloo posto until all the flavors are well incorporated into the curry.Check the salt and spices and adjust to suit your taste accordingly.", "You can adjust the consistency of the curry to be like a gravy or like a thick sabzi.Once done, serve the Jhinge Aloo Sabzi along with Tawa Paratha and a salad for a quick weeknight dinner."]'::jsonb, 45, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/1-Archana/Bengali_Aloo_Jhinge_Posto_Curry_Recipe-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/599.Bengali_Aloo_Jhinge_Posto_Curry_Recipe-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Assamese Bilahi Boror Tenga Recipe (Sour Curry With Red Lentil Fritters)', 'assamese-bilahi-boror-tenga-recipe-sour-curry-with-red-lentil-fritters', 'Assamese Bilahi Boror Tenga Recipe (Sour Curry With Red Lentil Fritters) is a North Eastern recipe belongs to Assamese cuisine. Usually, fried fish is added to the curry. But being a pure vegetarian, in this recipe I have added red lentil (masoor dal) fritters in a light sour curry and sour curry is made with the kokum and tomatoes. Serve Assamese Bilahi Boror Tenga Recipe (Sour Curry With Red Lentil Fritters) with Spicy Yogurt Chapati Recipe, Assamese Amitar Khar Recipe and Egg Shoap Recipe (appetizer).', '["1/2 cup Pink Masoor Dal (Split) , soaked for 1 hour", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "4 Kokum (Malabar Tamarind) , soaked in 1/2 cup water for 15 minutes", "Oil , to pan fry masoor dal fritters", "1 pinch Sugar", "1 Bay leaf (tej patta)", "1/3 teaspoon Panch Phoran Masala", "1 Dry Red Chilli", "1 tablespoon Mustard oil", "1 Whole Wheat Flour", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1/3 teaspoon Red Chilli powder"]'::jsonb, ARRAY['tomato', 'salt', 'wheat flour', 'mustard oil', 'bay leaf (tej patta)', 'kokum (malabar tamarind)', 'pink masoor dal (split) hour', 'red chilli powder', 'dry red chilli', 'sugar', 'onion', 'canola oil pan masoor dal fritters', 'panch phoran masala', 'turmeric powder']::text[], '["To begin making Assamese Bilahi Boror Tenga Recipe (Sour Curry With Red Lentil Fritters), drain water from the masoor dal and grind it into a coarse paste by adding little water.Transfer the paste into a bowl and add salt and turmeric powder.", "Mix well.Heat a kuzhi paniyaram pan and drop a spoonful of batter into each cavity.", "Drop a few drops of oil in each cavity.", "Flip when the bottom portion is browned well.", "Brown both sides evenly.", "You can do this on shallow frying pan too, but the shapes will be dissimilar.When the edges turn golden, flip them over and fry on the other side till both the sides are golden and crisp.Transfer them on an absorbent paper.In another pan, heat mustard oil and add panch phoran, bay leaf and whole dried red chilli.", "When the seeds begin to splutter, add the onions and kokum pieces and saute until onions becomes translucent.Add chopped tomato, red chilli powder, salt.", "Mix well and cook for 2-3 minutes.Now add the kokum water (in which kokum has been soaked) and some more water, sugar.", "Let it simmer for a minute.Mix flour in 2 tbsp water and make a paste.", "Add it into the pan.", "Stir it well to avoid lumps.Add fritters into the pan and let it simmer for 2 more minutes.Serve Assamese Bilahi Boror Tenga Recipe (Sour Curry With Red Lentil Fritters) immediately with Spicy Yogurt Chapati Recipe, Assamese Amitar Khar Recipe and Egg Shoap Recipe (appetizer)."]'::jsonb, 70, 'Assamese', 'veg', 'https://www.archanaskitchen.com/images/Assamese_Bilahi_Boror_Tenga_Recipe_Sour_curry_with_red_lentil_pakodas_original1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/600.Assamese_Bilahi_Boror_Tenga_Recipe_Sour_curry_with_red_lentil_pakodas_original1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false);

INSERT INTO public.recipes (
  title, slug, description, ingredients, cleaned_ingredients,
  instructions, total_time_mins, cuisine, diet, source_url,
  image_url, image_status, image_source, data_source, servings, review_count, is_featured
) VALUES
  ('Kerala Mutton Roast Recipe - Kerala Mutton Masala', 'kerala-mutton-roast-recipe-kerala-mutton-masala', 'Kerala is a land of many tastes and cuisines. You will find both ardent vegetarians and non vegetarians in this God''s Own Country. Since Kerala has a majority of its state along the Arabian Sea coast, the non vegetarians primarily consume a lot of fish and beef but mutton comes to a close second in terms of choice of meat. As with the case, mutton is prepared with locally available ingredients, mostly with the inclusion of coconut.', '["500 grams Mutton , with bone (adds flavour)", "1/2 teaspoon Black pepper powder", "Salt , as per your taste", "1/4 teaspoon Turmeric powder (Haldi)", "3 tablespoons Coconut Oil", "1 Onion , finely chopped", "1 Tomato , finely chopped", "2 inch Ginger , finely chopped", "6 cloves Garlic , finely chopped", "3/4 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Fennel seeds (Saunf)", "2 sprig Curry leaves", "Salt , as per your taste"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'fennel seeds (saunf)', 'red chilli powder', 'cloves garlic', 'curry leaves', 'onion', 'mutton (s flavour)', 'black pepper powder', 'turmeric powder', 'coriander powder', 'coconut oil', 'garam masala powder']::text[], '["To begin making\u00a0Kerala Mutton Roast Recipe, wash and clean the mutton pieces well.", "In a pressure cooker, combine the mutton pieces, pepper powder, salt, turmeric powder and mix well.Add 1 cup of water.", "Close the pressure cooker and place on high flame.Once the first whistle blows, reduce the flame to low and then let it continue to be on low flame for another 30 minutes.", "After 30 minutes, turn off the heat and allow the pressure to release naturally.", "Transfer the mutton pieces in a bowl and keep the stock aside.", "The stock will be utilized later.", "In a deep pan or wok add coconut oil on medium heat.", "Once the oil is hot, add sliced onion and saute for about 3-4 minutes until the onions become soft and translucent.Now add fennel seeds, ginger, garlic and curry leaves and let it cook for 2 minutes.", "To the onion mix, add red chilli powder, turmeric powder, coriander powder, garam masala powder salt and stir well.", "Saute for a couple of minutes until the Kerala\u00a0Mutton Roast masala comes together.Once the raw smell of the masala is gone, add the chopped tomatoes and cook until soft and mushy.", "This will take about 2 to 3 minutes.At this stage add the mutton stock and the mutton pieces into this Mutton Roast masala.", "Let this cook on medium to high flame until the Kerala Mutton Roast becomes semi dry.Once the\u00a0Kerala Mutton Roast Recipe is done, turn off the heat, check the salt and spice levels and adjust to suit your taste.Serve Kerala Mutton Roast along with Kerala Style Pulissery Recipe (Mor Kuzhambu) and Steamed rice\u00a0for a complete meal or can be eaten along with\u00a0Rotis, Ghee Roast Dosa or Kerala Style Appams."]'::jsonb, 65, 'Kerala', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nadira912-gmail.com/Kerala_Mutton_Roast_Recipe_13_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/601.Kerala_Mutton_Roast_Recipe_13_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Moringa Masoor Dal Recipe - Drumstick Leaves Dal', 'moringa-masoor-dal-recipe-drumstick-leaves-dal', 'Moringa Masoor Dal Recipe is a delicious lentil curry made with whole Masoor dal and fresh drumstick leaves making it a wholesome diabetic friendly dal. This recipe is a healthy choice for the intake of everyday protein and is also packed with vitamins and minerals.', '["1 cup Pink Masoor Dal (Split)", "200 grams Drumstick Leaves (Moringa/Murungai Keerai) , cleaned chopped", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Cumin seeds (Jeera)", "1 inch Ginger , finely chopped", "1 Dry Red Chilli", "1 Tomato , chopped", "1 Green Chilli , slit", "2 teaspoons Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "Salt , to taste", "1 tablespoon Ghee", "1 Lemon , juice extracted"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'green chilli', 'drumstick leaves (moringamurungai keerai)', 'asafoetida (hing)', 'ghee', 'red chilli powder', 'dry red chilli', 'pink masoor dal (split)', 'cumin seeds (jeera)', 'lemon', 'coriander powder', 'turmeric powder']::text[], '["To prepare the Methi Masoor Dal Recipe, first wash and soak the masoor dal in 3 cups of water for at least 30 minutes.", "While the dal is soaked clean, wash and pat dry the drumstick leaves.Next, finely chop the drumstick leaves.", "Heat a teaspoon of oil in a wok or a kadai and add the chopped drumstick leaves into the wok.", "Sprinkle some salt, cover the pan and cook the Moringa leaves until soft and tender.It takes about 2 to 3 minutes and not more than that.", "Once done, turn off the heat and keep the cooked moringa leaves aside.In the next step, cook the masoor dal with the spices.", "Heat ghee in a pressure cooker over medium heat.", "Add asafoetida and cumin seeds and allow it to crackle.Add the chopped tomato, ginger, green chilli along with coriander powder, turmeric powder, red chilli powder and saute for a minute or so over medium heat.Add soaked masoor dal along with the soaked water to the onion tomato mixture.", "Close the lid of the pressure cooker and put the weight on.Cook masoor dal for 3 whistles.", "After a couple of whistles, turn the heat to low and simmer the dal for about 5 minutes.", "After 5 minutes, turn off the heat.", "Allow the pressure to release naturally from the pressure cooker.Once the pressure has released, open the cooker and stir in the saut\u00e9ed moringa leaves, squeeze juice from one lemon and serve.", "Serve the\u00a0Moringa Masoor Dal Recipe along with Steamed Rice,\u00a0Kaddu Simla Mirch Sabzi\u00a0,\u00a0Phulka\u00a0to make it a wholesome Indian diabetic friendly dinner."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Moringa_Masoor_Dal_Recipe_Drumstick_Leaves_Masoor_Dal_Recipe_No_Onion_No_Garlic-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/602.Moringa_Masoor_Dal_Recipe_Drumstick_Leaves_Masoor_Dal_Recipe_No_Onion_No_Garlic-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Vegetable Biryani Recipe', 'chettinad-vegetable-biryani-recipe', 'Chettinad Vegetable Biryani Recipe is a spicy one pot Biryani that is simple to make and delicious to eat. My father used to love eating this biryani and every other Sunday we used to step outside just to eat this biryani. It took me years to make this exact recipe and now I would like to share this recipe with all of you. Most often biryani is cooked with biryani rice, but at home, I find it really easy to make biryani with Ponni rice or Sona Masuri rice, as it is always available at home and my children love it like that as well. This biryani is a one pot meal and can be prepared in less than 45 minutes.', '["To roast and grind", "2 Cloves (Laung)", "2 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "1 teaspoon Whole Black Peppercorns", "1 teaspoon Fennel seeds (Saunf)", "1 Star anise", "2 Stone flower , small", "1 cup Rice", "1 Carrot (Gajjar) , diced", "1/2 cup Green beans (French Beans) , cut lengthwise", "1 Potato (Aloo) , diced", "1/4 cup Green peas (Matar)", "12 Pearl onions (Sambar Onions) , finely chopped", "2 Tomatoes , roughly chopped", "4 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "1 Bay leaf (tej patta) , roughly torn", "1/4 cup Mint Leaves (Pudina) , roughly chopped", "1 teaspoon Red Chilli powder", "1 tablespoon Coriander Powder (Dhania)", "1 tablespoon Ghee", "Salt , to taste", "1 tablespoon Ghee", "1/4 cup Cashew nuts , broken"]'::jsonb, ARRAY['tomato', 'black peppercorns', 'carrot', 'cloves garlic', 'st flower', 'salt', 'cardamom (elaichi) podsseeds', 'mint leaves (pudina)', 'star anise', 'green beans (french beans)', 'rice', 'red chilli powder', 'cashew nuts', 'ginger', 'bay leaf (tej patta)', 'fennel seeds (saunf)', 'ghee', 'potato (aloo)', 'green peas (matar)', 'pearl onion (sambar onion)', 'cinnamon stick (dalchini)', 'coriander powder', 'cloves (laung)']::text[], '["To begin making the Chettinad Vegetable Biryani Recipe, get all the ingredients ready and keep them aside.The first step is to roast all the spices.", "In to a pan, add the cloves, cardamom, pepper, fennel seeds, cinnamon, star anise and stone flower.", "Roast for about a minute until you get a roasted aroma.Once roasted, grind to make a fine powder of the spices.", "This will be our Biryani Masala.The next step is to make the Chettinad Veg Biryani.", "Heat ghee or oil into the pressure cooker over medium heat.Add the onion, ginger, garlic and saute until the onions soften.", "Once the onions are softened, add the tomatoes, and cook until the tomatoes soften.Finally add the vegetables, the Biryani Masala, coriander powder, red chilli powder, rice and saute for a few minutes until the rice is coated with the masalas.", "Stir in the mint leaves and salt.Add 2 cups water and pressure cook the biryani for 2 whistles.", "After 2 whistles, turn the heat to low and simmer for 3 minutes and turn off the heat.", "Allow the pressure to release naturally.Once the pressure releases, open the cooker and allow the Chettinad Veg Biryani\u00a0to rest for about a minute before you stir.In the meanwhile, heat ghee over medium heat.", "Add the cashew nuts and roast until golden and crisp.Stir in the roasted cashew nuts into the Chettinad Veg Biryani and transfer to a bowl.Serve Chettinadu Vegetables Biryani along with\u00a0Tomato Onion Raita\u00a0and\u00a0Paneer Kurma\u00a0for a delicious sunday lunch."]'::jsonb, 55, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sandhya-archanaskitchen.com/Chettinad_Vegetable_Biryani_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/603.Chettinad_Vegetable_Biryani_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karuveppilai Chutney Podi Recipe - Curry Leaves Chutney Podi', 'karuveppilai-chutney-podi-recipe-curry-leaves-chutney-podi', 'Karuveppilai also known as Curry Leaves makes a delicious chutney podi, is very popular in the south indian homes. Curry leaves are also very rich in nutrients and said to have many medicinal benefits.', '["2 cups Curry leaves , (the fresher the better)", "3 tablespoons Chana dal (Bengal Gram Dal)", "2 tablespoons Black pepper powder", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 tablespoon Cumin seeds (Jeera)", "30 grams Tamarind", "Salt , to taste", "1 teaspoon Asafoetida (hing)"]'::jsonb, ARRAY['salt', 'curry leaves (the er the better)', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'black pepper powder', 'tamarind', 'chana dal (bengal gram dal)']::text[], '["To make the Karuveppilai Chutney Podi recipe, heat oil in a pan on medium heat; roast the chana dal, black pepper, fenugreek seeds,\u00a0cumin seeds.", "Once well roasted, stir in the curry leaves and saute for a few seconds.Cool the chutney mixture\u00a0completely and grind the Karuveppilai Chutney\u00a0into a coarse powder along with tamarind, salt, hind in the food processor.", "The tamarind adds a tangy taste to the powder and tastes delicious with rice.Serve Karuveppilai Chutney Podi recipe along with hot\u00a0steamed rice\u00a0and sesame oil and\u00a0Milagu rasam\u00a0to savor this delicious chutney podi.For the Chutney to stay a little longer:\u00a0store it in the refrigerator for a couple of months."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Chutneys/Karuveppilai_Chutney_Recipe_A_Healthy_Curry_Leaves_Chutney-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/604.Karuveppilai_Chutney_Recipe_A_Healthy_Curry_Leaves_Chutney-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Homemade Butter Naan Recipe - Soft Yogurt Bread', 'homemade-butter-naan-recipe-soft-yogurt-bread', 'The Homemade Butter Naan recipe is simple to make in your own kitchen. Naan is an Indian bread which is on every restaurant menu. It is a rich Indian bread that goes well with most Indian gravies. Everyone loves the soft texture of a good Butter naan. It is a hit among everyone.', '["3 cups All Purpose Flour (Maida)", "1/2 cup Butter (Unsalted) , softened", "1 cup Curd (Dahi / Yogurt)", "3 tablespoons Lukewarm Water", "1 tablespoon Sugar", "2 teaspoons Active dry yeast", "1-1/2 teaspoons Salt", "Others", "2 teaspoons Chaat Masala Powder", "1 tablespoon Butter (Salted) , softened"]'::jsonb, ARRAY['salt', 'chaat masala powder', 'water', 'dry yeast', 'curd', 'sugar', 'flour (maida)', 'butter']::text[], '["To begin making the Butter Naan recipe, in a large bowl add the 3 cups of flour and butter.", "With your hands, blend the butter into the flour until it forms coarse crumbs.", "You can do this in a blender as well, but the dough when worked with hands gives a better texture to the dough.Stir together the warm water, yeast \u00a0and sugar until yeast is completely dissolved.", "Now make a well in the center of the flour mixture and add the yogurt, salt and yeast mixture.Knead into the flour and until the whole dough collects into a mass.", "Add a little more water if required to bring the dough together.", "The dough will be wet and sticky.", "Wipe your hands clean and oil them.", "Now knead the naan dough with the oiled hands until smooth , for about 10 minutes; oil your hands more if the dough is sticky.", "The dough after 10 minutes of kneading will still be soft and pliable.", "Place the dough in a greased bowl, cover the bowl and \u00a0allow the dough to rest for 3 to 4 hours until the dough has doubled in volume.", "Once the naan dough has doubled, punch down the dough, knead for a minute and divide into 12 to 15 equal portions.With a rolling pin, quickly roll out each ball into a 5 inch oval.", "With your fingers, stretch each round into a 5-7 inch oval.", "The next step is to cook the naans.", "Follow either of the below methods."]'::jsonb, 90, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/1-Archana/Homemade_Butter_Naan_Recipe_Soft_Yogurt_Bread-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/605.Homemade_Butter_Naan_Recipe_Soft_Yogurt_Bread-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Kandi Pachadi Recipe (Masoor Dal Chutney Recipe)', 'andhra-style-kandi-pachadi-recipe-masoor-dal-chutney-recipe', 'Andhra Style Kandi Pachadi Recipe (Masoor Dal Chutney Recipe) is a delicacy from Andhra. The chutney is made from roasted masoor dal, urad dal and dry red chillies and ground along with roasted gram and tamarind to make a coarse chutney. Then the chutney is tempered with mustard seeds and curry leaves.', '["To Roast", "1 cup Masoor Dal (Whole)", "3 Dry Red Chillies", "Other Ingredients", "1/2 cup Roasted Gram Dal (Pottukadalai)", "1 teaspoon Cumin seeds (Jeera)", "18 grams Tamarind", "4 cloves Garlic", "Salt , to taste", "To temper", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "2 Dry Red Chillies", "1 sprig Curry leaves", "1 pinch Asafoetida (hing)", "Oil"]'::jsonb, ARRAY['salt', 'mustard seeds', 'asafoetida (hing)', 'gram dal (pottukadalai)', 'cloves garlic', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'cumin seeds (jeera)', 'tamarind', 'masoor dal', 'sunflower oil']::text[], '["To begin making the Andhra Style Kandi Pachadi Recipe, heat a flat skillet with oil, add the masoor dal and cumin seeds and roast until they become light brown.Add the urad dal and dry red chilli at the end and fry until the chillies crisp up.Once done, cool it down and grind it along with tamarind, garlic into a smooth paste by adding water.To temper, heat a small tempering pan and add mustard seeds and urad dal and allow it splutter for 10 seconds.Add curry leaves, dry red chilies, hing and leave the curry leaves to crackle for 10 seconds.Pour this tempered oil over the chutney and serve.", "Serve the Andhra Style Kandi Pachadi Recipe with\u00a0Homemade Crispy Ghee Roast Dosas\u00a0and\u00a0Spicy Crunchy Masala Idli Recipe\u00a0to enjoy your morning breakfast."]'::jsonb, 20, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Andhra_Style_Kandi_Pachadi_Recipe_Masoor_Dal_Chutney_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/606.Andhra_Style_Kandi_Pachadi_Recipe_Masoor_Dal_Chutney_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer Kulcha Recipe-Cottage Cheese Stuffed Leavened Flatbread', 'paneer-kulcha-recipe-cottage-cheese-stuffed-leavened-flatbread', 'Paneer Kulcha Recipe is a popular variety of leavened flat bread stuffed with cottage cheese and seasoned with spices. Popular in North India, especially during winters, it is usually made in a earthen oven or tandoor, over hot coals.', '["2 cups All Purpose Flour (Maida)", "1 tablespoon Sooji (Semolina/ Rava)", "1/2 cup Curd (Dahi / Yogurt)", "1 tablespoon Oil", "1/2 teaspoon Baking soda", "1 teaspoon Sugar", "1 teaspoon Salt", "Kalonji (Onion Nigella Seeds) , for sprinkling", "Butter (Salted) , melted, to brush", "1/2 teaspoon Oil", "1 Green Chilli , chopped", "1/4 cup Onions , chopped", "1 cup Paneer (Homemade Cottage Cheese)", "1/4 teaspoon Cumin powder (Jeera)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'green chilli', 'paneer', 'baking soda', 'curd', 'sugar', 'onion', 'sooji (semolina rava)', 'flour (maida)', 'kalonji (onion nigella seeds) sprinkling', 'butter', 'sunflower oil']::text[], '["To begin making the Paneer Kulcha recipe, first mix together the sooji and yogurt in a large mixing bowl and set aside for ten minutes.Once the sooji has soaked in the yogurt, add maida, oil, baking soda, sugar and salt to it and knead together into a smooth dough.", "The dough should be firm and hold together, but supple and soft to touch.Cover the dough with a lid and let it refrigerate for two hours to leaven.Meanwhile, prepare the stuffing.", "Place a pan on the heat and warm some oil in it.", "Add the chopped onions to it and saute along with the green chilies until the onions are softened and translucent.Next, add the paneer, turmeric powder and salt to the softened onions and cook for two minutes more.", "Turn the heat off and set the filling aside to cool.Once the dough has been in the refrigerator for two hours, take it out to start making the kulchas.Portion out the dough into golf ball sized pieces.Working with one portion at a time, roll out the dough into small circle about 2.5-3 inches in diameter.", "Take the rolled circle in your palm, place a spoonful of the paneer filling in the center, while cupping it in your palm.Bring all the edges of the circle together to seal the filling inside, like a tight pouch.", "Make sure there are no air pockets within.Gently press the stuffed ball out without adding too much flour, roll the kulcha out to a thick disc.Next, sprinkle water on the kulcha, sprinkle kalonji and press down so they stick.Do not apply too much pressure at one place else the kulcha will tear and stuffing will come out.", "Kulchas are usually thicker than parathas.Place the kulcha on the pan and cook until bubbles begin to appear on the surface.", "Apply a little oil on the top and flip the kulcha over to brown on the other side.Repeat, applying ghee, butter or oil and cooking the kulcha until it attains a nice even brown hue with some brown spots.Serve\u00a0Paneer Kulcha \u00a0with\u00a0Tandoori Cauliflower & Chickpea Curry\u00a0or\u00a0Dhabewali Dal\u00a0and\u00a0Carrot Cucumber Tomato Salad with Lemon and Coriander\u00a0\u00a0for lunch or dinner."]'::jsonb, 170, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Richa_Gupta/Paneer_Kulcha.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/607.Paneer_Kulcha.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aavryachi Bhaji-Avarakkai Poriyal Recipe-Broad Beans Stir Fry', 'aavryachi-bhaji-avarakkai-poriyal-recipe-broad-beans-stir-fry', 'Aavryachi Bhaji or Avarakkai Poriyal is a simple simple stir-fry of field/broad beans. Popularly cooked in Karnataka, field beans are a seasonal delicacy and this bhaji/sabji is a simple way to cook it in a flavourful way to retain maximum nutrition.', '["3 cups Avarekai (Broad Beans) , chopped", "1 Onion , chopped", "2 tablespoons Fresh coconut , grated", "1 Green Chilli , finely chopped", "1 teaspoon Jaggery , grated", "1 pinch Asafoetida (hing)", "1 teaspoon Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'green chilli', 'coconut', 'asafoetida (hing)', 'jaggery', 'onion', 'avarekai (broad beans)', 'sunflower oil']::text[], '["To begin making the\u00a0Aavryachi Bhaji/ Avarakkai Poriyal, we will first steam the beans in a steamer.", "Place the cut beans in the\u00a0steamer and cook until it is cooked, about 5 minutes.The next step is to stir fry the beans.Heat oil in a kadai or a heavy bottomed pan.", "Add onion and saut\u00e9 till onion turns pinkish and translucent.Once the onions have softened, add the green chilies, steamed beans, the coconut, jaggery, salt and asafoetida.", "Stir well until all the ingredients come together for just about 2 minutes and turn off the heat.", "Check the salt and adjust to suit your taste.Serve\u00a0Aavryachi Bhaji or Avarakkai Poriyal simple stir-fry with\u00a0Mixed Vegetable Sambar\u00a0and\u00a0Rice\u00a0along with a dollop of ghee, for a wholesome lunch or dinner."]'::jsonb, 40, 'North Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Aavryachi_Bhaji__Broad_Beans_Stir_Fry__Avarakkai_Subzi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/608.Aavryachi_Bhaji__Broad_Beans_Stir_Fry__Avarakkai_Subzi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Masala Akki Roti With Spinach Recipe - sarvapindi', 'masala-akki-roti-with-spinach-recipe-sarvapindi', 'Sarvapindi also known as Akki roti in some areas, is a Telangana dish ( a state of India ) a famous snack or breakfast dish. It is traditionally made in two varieties either using green chilli paste or red chilli powder. They taste great either ways but might differ in appearance. These Masala Akki Roti with Spinach are filling and healthy, and can be served with chutney or yogurt.', '["3 cups Rice flour", "2 cups Water", "1 cup Spring Onion Greens , finely chopped (optional)", "1 cup Spinach Leaves (Palak) , chopped", "1/2 cup Coriander (Dhania) Leaves , chopped", "Curry leaves , few, chopped", "10 Green Chillies , minced", "2 tablespoon Sesame seeds (Til seeds)", "Salt , to taste", "Oil , for pan frying"]'::jsonb, ARRAY['green chillies', 'spring onion greens', 'salt', 'coriander (dhania) leaves', 'water', 'curry leaves', 'sesame seeds (til seeds)', 'rice flour', 'spinach leaves (palak)', 'sunflower oil pan']::text[], '["To begin preparing the Masala Akki Roti with Spinach, in a deep pot add 2 cups of water and bring this to a soft boil and stir in the rice flour and mix well.Turn off the heat and transfer the batter into a mixing bowl.Cool this for few minutes at room temperature.Next add the chopped spinach, scallions, coriander, curry leaves, green chillies, salt, sesame seeds and little water if required, knead this into a soft dough.Cover and rest the dough for 10 minutes.Later, divide the dough into 12 equal portions.Now press the dough ball onto a greased pan with the thickness of a roti and drizzle few drops of oil around the corners.Fry this on medium heat on both the sides until cooked and golden brown spots appear.The Masala Akki Roti with Spinach are filling and healthy, and can be served with\u00a0chutney\u00a0or yogurt."]'::jsonb, 100, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Swapna/Greens_Sarvapindi_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/609.Greens_Sarvapindi_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bharva Bhindi Recipe - Pan Fried Stuffed Okra With Spices & Peanuts', 'bharva-bhindi-recipe-pan-fried-stuffed-okra-with-spices-peanuts', 'Bharva Bhindi Recipe is a delicious recipe of stuffed lady fingers that are pan fried. This recipe is one of the many ways which Gujarati’s make their Bhindi. It is made during special occasions, or when you have guests over for lunch or when you wish to have one of those elaborate Sunday lunches.', '["Ingredients for Bharva Bhindi", "10 Bhindi (Lady Finger/Okra)", "1 tablespoon Oil", "1/2 teaspoon Cumin seeds (Jeera)", "1 inch Ginger , grated", "1 tablespoon Fresh coconut , grated", "4 sprig Coriander (Dhania) Leaves , chopped", "Ingredients of the Stuffing", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Garam masala powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Amchur (Dry Mango Powder)", "1 tablespoon Gram flour (besan)", "1 teaspoon Oil", "2 tablespoons Raw Peanuts (Moongphali) , coarsely powdered", "1 teaspoon Sesame seeds (Til seeds)", "Salt , to taste"]'::jsonb, ARRAY['ingredients for bharva bhindi', 'bhindi', 'lady finger/okra', 'oil', 'cumin seeds', 'jeera', 'ginger', 'fresh coconut', 'coriander', 'dhania', 'ingredients of the stuffing', 'coriander powder', 'cumin powder', 'garam masala powder', 'turmeric powder', 'haldi', 'red chilli powder', 'amchur', 'dry mango powder', 'gram flour', 'besan', 's raw peanuts', 'moongphali', 'sesame seeds', 'til seeds', 'salt']::text[], '["To begin making the Bharva Bhindi Recipe, in a small bowl combine all the ingredients for the filling to make the bhindi masala including coriander powder, red chilli powder, cumin powder, garam masala powder, turmeric powder, amchur, gram flour, oil, raw peanuts, sesame seeds, salt and keep aside.Mix everything well and the masala for your Bharva Bhindi is ready.", "Keep it aside.Wash the bhindi and dry them completely with a clean kitchen towel.Split them lengthwise in such a way that the ends don\u2019t separate and don\u2019t become two halves.", "Fill a small amount of the filling mixture into the slit portion of the bhindi.Once filled close the sides by\u00a0bring\u00a0them together.", "You could leave them as whole filled fingers or cut the filled fingers into\u00a0half\u00a0from the center.Heat oil in a heavy bottomed pan\u00a0on\u00a0medium heat; add cumin seeds, grated ginger and allow them to crackle.", "Gently stir in the filled bhindi.", "Turn the heat to low and simmer with the pan covered for about two minutes.After about a couple of minutes, uncover the pan; give a gentle stir to the\u00a0lady\u00a0fingers turning them around and allowing them to cook in the open until they become tender.You will notice the color changes from green to a pale green with roasted brown spots and the bhindi would have also shrunk in size; this indicates that it is cooked.", "Check the salt and spice levels and adjust to suit your taste.Once\u00a0bharva\u00a0bhindi is done, turn off\u00a0heat\u00a0and transfer the bhindi to a serving platter.", "Garnish with grated coconut and chopped coriander leaves.Bharva Bhindi Recipe\u00a0served along with\u00a0Gujarati Dal\u00a0and\u00a0Roti''s\u00a0makes a perfect Sunday lunch.", "In addition, to make a festive menu you could serve it along with\u00a0Khandvi,\u00a0Chora Nu Shaak, Pakka Kela Nu Raita, Achar and\u00a0Mohanthal."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Bharva_Bhindi_Recipe_Pan_Fried_Stuffed_Okra_with_Spices_Peanuts-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/610.Bharva_Bhindi_Recipe_Pan_Fried_Stuffed_Okra_with_Spices_Peanuts-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Style Khatkhatem Recipe (Mixed Vegetable Gravy)', 'goan-style-khatkhatem-recipe-mixed-vegetable-gravy', 'Goan Style Khatkhatem Recipe (Mixed Vegetable Gravy) is a divine vegetable stew made from a mix of seasonal vegetables. The dish mainly prepared in Hindu household. The gravy will contain mostly vegetables like pumpkin, raw banana, raw jackfruit, yam and radish. The gravy is simmered in a coconut curry with moong dal and flavored with chilli powder and turmeric.', '["1 cup Kaddu (Parangikai/ Pumpkin) , skin peeled and chopped", "1 Raw Banana , skin peeled and chopped", "1/2 Green peas (Matar)", "1/4 cup Yellow Moong Dal (Split)", "Salt , to taste", "1 cup Tamarind Water", "To Grind", "1 cup Fresh coconut", "1 teaspoon Turmeric powder (Haldi)", "3 Dry Red Chilli"]'::jsonb, ARRAY['salt', 'yellow moong dal (split)', 'banana skin', 'tamarind water', 'coconut', 'green peas (matar)', 'dry red chilli', 'parangikai pumpkin skin', 'turmeric powder']::text[], '["To begin making the Goan Style Khatkhatem Recipe pressure cook the dal along with all the vegetables (except green peas) with water in a pressure cooker for 1 whistle.", "Allow the pressure to release naturally by itself.Meanwhile, grind the coconut along with turmeric powder dry red chilli into a smooth paste and keep it aside.Keep the pressure cooker back on the heat and add the ground coconut paste with 1/2 cup water.", "Check for salt, add the green peas and tamarind water.Leave it on the simmer for 5 minutes until the gravy thickens.", "Check for salt again and serve.Serve the Goan Style Khatkhatem Recipe along with\u00a0Pav\u00a0or\u00a0tawa parathas\u00a0to enjoy your everyday lunch in a healthy way."]'::jsonb, 45, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Goan_Style_Khatkhatem_Recipe_Mixed_Vegetable_Gravy_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/611.Goan_Style_Khatkhatem_Recipe_Mixed_Vegetable_Gravy_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ukad Recipe - Maharashtrian Rice Flour Porridge', 'ukad-recipe-maharashtrian-rice-flour-porridge', 'Ukad Recipe is a classic Maharashtrian breakfast recipe. A lovely tadka of cumin and mustard seeds flavoured with ginger and green chillies. Such simple ingredients yet such complex flavours.', '["1 tablespoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "2 sprig Curry leaves , torn", "1/2 inch Ginger , finely chopped", "1 Green Chilli , finely chopped", "Salt , to taste", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 cup Rice flour", "1 cup Water", "2 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['oil', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'asafoetida', 'hing', 'curry leaves', 'ginger', 'reen chilli', 'salt', 'turmeric powder', 'haldi', 'rice flour', 'water', 'coriander', 'dhania']::text[], '["To begin making the Ukad Recipe, prep all the ingredientsHeat oil in a pan on medium heat; add the mustard seeds, cumin seeds, hing and curry leaves.", "Allow the seeds to crackle.", "Next add the ginger, green chilli, salt and turmeric powder.", "Saute this for thirty seconds.", "Now that that tadka for the ukad is ready, reduce the heat and add in the water, right after, quickly add in the rice flour.", "As soon as the rice flour is added, keep stirring it in with a ladle, to ensure there are so lumps.", "The rice flour mixture will begin to thicken and form a porridge style consistency.", "Once the ukad has come together with the tadka, mix well once more and cover the pan, turn the heat to low and simmer for 5 minutes minutes until you see a shiny texture of the ukad (rice flour porridge).", "This is to ensure the rice flour is well cooked.", "Once done, give it a taste and check the salt and adjust accordingly.", "Turn off the heat and garnish with chopped coriander leaves and serve.Serve\u00a0Ukad Recipe along with\u00a0Adrak Chai Recipe - Indian Style Ginger Tea\u00a0for breakfast."]'::jsonb, 10, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sonawala.devaki-gmail.com/10_-_Ukad_Recipe_Maharashtrian_Rice_Flour_Porridge_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/612.10_-_Ukad_Recipe_Maharashtrian_Rice_Flour_Porridge_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pakistani Bhuna Gosht Recipe', 'pakistani-bhuna-gosht-recipe', 'Pakistani Bhuna Gosht is a mutton preparation that is very popular in Pakistan. Mutton pieces slow cooked in whole spices, chopped onion and ginger garlic is later fried (bhuna) with lots of ghee and garnished with coriander. The mutton pieces when cooked slowly with whole spices, leaves an aromatic flavour and extremely juicy mutton that makes you crave for more.', '["750 grams Mutton , cut into medium pieces", "6 Onions , sliced", "1/2 cup Garlic", "4 inch Ginger , sliced", "3/4 cup Curd (Dahi / Yogurt)", "2-1/2 tablespoons Coriander Powder (Dhania)", "2 teaspoons Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , as required", "1/2 cup Oil", "4 tablespoons Ghee", "2 tablespoons Coriander (Dhania) Leaves , chopped", "6 Dry Red Chillies", "2 Bay leaf (tej patta)", "1-1/2 inch Cinnamon Stick (Dalchini)", "1 teaspoon Mace (Javitri)", "1 teaspoon Ajwain (Carom seeds)", "5 Cloves (Laung)", "5 Whole Black Peppercorns", "5 Cardamom (Elaichi) Pods/Seeds", "2 Black cardamom (Badi Elaichi)", "1/2 teaspoon Nutmeg , crushed"]'::jsonb, ARRAY['s mutton', 'onions', 'garlic', 'ginger', 'curd', 'dahi / yogurt', 's coriander powder', 'dhania', 's red chilli powder', 'turmeric powder', 'haldi', 'salt', 'oil', 's ghee', 's coriander', 'dry red chillies', 'bay leaf', 'tej patta', 'cinnamon stick', 'dalchini', 'mace', 'javitri', 'ajwain', 'carom seeds', 'laung', 'whole black peppercorns', 'cardamom', 'elaichi', 'black cardamom', 'badi elaichi', 'nutmeg']::text[], '["To begin making the Pakistani Bhuna Gosht recipe, wash mutton nicely and keep it aside.Heat oil in a heavy bottomed pan and add whole spices and let them crackle.Now add whole garlic pods and ginger slices and saute them till golden.Add sliced onions and fry till they are soft and translucent.", "Once the onions are soft, add washed mutton and mix well.Next add thick curd and salt and let it cook on high flame till the curd starts leaving water from sides.As soon as the water starts appearing from sides, close the lid, simmer the gas and let it cook till mutton is soft and tender.When the mutton is cooked, add coriander powder, turmeric, red chilli powder and mix together.Turn the flames high and start frying everything till oil starts leaving from sides.", "Keep adding ghee while frying.Once the ghee/oil starts oozing out from the sides, check salt again and adjust if required.Slowly the mutton will start to thicken and turn deep brown in colour.", "Turn off the gas and garnish the Bhuna Gosht with lots of coriander.Pakistani Bhuna Gosht\u00a0is one such succulent dish that is best enjoyed with\u00a0Rumali Roti\u00a0or\u00a0Homemade Butter Naan."]'::jsonb, 70, 'Pakistani', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shaheen_Ali/PAKISTANI_BHUNA_GOSHT.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/613.PAKISTANI_BHUNA_GOSHT.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pumpkin Sabzi Recipe with Panch Phoron Masala', 'pumpkin-sabzi-recipe-with-panch-phoron-masala', 'The Pumpkin Sabji with Panch Phoron Masala recipe is simple to make dish that requires no prior planning and gets done in no time at all. The addition of mustard oil along with the panch-phoron masala brings out the intense flavor of this Pumpkin Sabzi. Serve the Pumpkin Sabzi Recipe with Panch Phoron Masala along with Tawa Paratha and Punjabi Kadhi Pakora for a wholesome weeknight dinner or even pack it into your lunch box.', '["500 grams Kaddu (Parangikai/ Pumpkin) , peeled and cut into cubes", "2 sprig Curry leaves", "2 Dry Red Chillies", "2 teaspoons Panch Phoran Masala", "1/4 teaspoon Turmeric powder (Haldi)", "Salt", "Mustard oil"]'::jsonb, ARRAY['s kaddu', 'parangikai/ pumpkin', 'curry leaves', 'dry red chillies', 's panch phoran masala', 'turmeric powder', 'haldi', 'salt', 'mustard oil']::text[], '["To begin making the Pumpkin Sabzi Recipe with Panch Phoron Masala,\u00a0first begin by prepping the pumpkin and chopping it into half inch cubes.In a heavy bottomed wok or kadai, warm a teaspoon of mustard oil.Keeping the flame on medium, bring it up to smoking point and add in the panch-phoron masala.", "When it sizzles, add turmeric, curry leaves and the dry red chillies and toss until the red chillies are roasted.Once the chilies are roasted, add the chopped pumpkin, sprinkle salt to taste and toss on a low flame for a couple of minutes.", "Sprinkle some water over the pumpkin and turn the heat to low.", "Cover the pan, allowing the pumpkin to cook in its own steam until soft and tender.", "Check the salt and spice levels at this stage and adjust to suit your taste.When the pumpkin is fully cooked, take the lid off and dry out the excess moisture.", "Stir in the freshly chopped coriander leaves and serve warm.Serve the\u00a0Pumpkin Sabzi Recipe with Panch Phoron Masala along with Tawa Paratha and Punjabi Kadhi Pakora for a wholesome weeknight dinner or even pack it into your lunch box."]'::jsonb, 25, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Pumpkin_Sabzi_with_Panch_Phoron_Masala-1-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/614.Pumpkin_Sabzi_with_Panch_Phoron_Masala-1-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Beans & Cauliflower Poriyal Recipe (South Indian Stir Fry)', 'chettinad-beans-cauliflower-poriyal-recipe-south-indian-stir-fry', 'The Chettinad Beans & Cauliflower Poriyal Recipe is a healthy stir fry with a subtle blend of south indian condiments. The steamed fresh vegetables are simply tossed in a seasoning and served as a side dish along with sambar or a kuzhambu and rice. The Chettinad Beans & Cauliflower Poriyal is a healthy recipe that you can have as a salad with a bowl of yogurt for a light dinner.', '["1 Cauliflower (gobi) , cut into florets", "200 grams Green beans (French Beans) , finely chopped", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 tablespoon Sesame (Gingelly) Oil"]'::jsonb, ARRAY['salt', 'green beans (french beans)', 'mustard seeds', 'cauliflower (gobi)', 'red chilli powder', 'sesame (gingelly) oil', 'curry leaves', 'white urad dal (split)', 'turmeric powder']::text[], '["To begin making the\u00a0Chettinad Beans & Cauliflower Poriyal Recipe, first prepare the vegetables by cutting them in appropriate sizes.Steam the cauliflower and beans along with a little salt in a steamer and cook until just about soft.", "Dont over steam and overcook the vegetables.Heat a heavy bottomed pan, heat the oil over medium heat; add the mustard seeds, urad dal and allow it to crackle.", "Wait for the dal to brown until golden.Stir in the curry leaves, chili powder, turmeric powder, and the steamed cauliflower and beans.", "Toss well until all the ingredients are well combined.", "Once combined, saute for a couple of more minute, check the salt and spices and serve.Serve the\u00a0Chettinad Beans & Cauliflower Poriyal along with\u00a0Drumstick Sambar, Steamed Rice and Appalam for a lunch or dinner."]'::jsonb, 40, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Chettinad_Beans_Cauliflower_Poriyal_Curry_Recipe-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/615.Chettinad_Beans_Cauliflower_Poriyal_Curry_Recipe-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Besan Burji Recipe-Chickpea Flour Scramble Recipe', 'besan-burji-recipe-chickpea-flour-scramble-recipe', 'Besan Burji Recipe is a delight for all the vegans. Usually people have notion that Bhurjis are made with egg but here we have come up with a slight variation by adding besan as the main ingredient. The Bhurji is tossed with sautéed vegetables. You can add any vegetable of your choice.', '["1 cup Gram flour (besan)", "1 tablespoon Flax seed powder (flax meal)", "2 tablespoons Curd (Dahi / Yogurt)", "1 teaspoon Cumin seeds (Jeera)", "1 Onion , finely chopped", "1 Red Bell pepper (Capsicum) , finely chopped", "1 cup Button mushrooms , sliced", "2 Green Chillies , finely chopped", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "Salt , to taste", "2 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['salt', 'red bell pepper (capsicum)', 'cumin powder (jeera)', 'red chilli powder', 'gram flour (besan)', 'curd', 'coriander (dhania) leaves', 'onion', 'cumin seeds (jeera)', 'button mushrooms', 'turmeric powder', 'green chillies', 'flax seed powder (flax meal)']::text[], '["To begin making the Besan Burji Recipe we will make the batter and keep it ready.For the batter add gram flour, flax seed powder and curd into a large mixing bowl and keep aside.Heat a flat skillet, add oil and splutter the cumin seeds and fry the onions till it is translucent, once done add in the capsicum, mushrooms, green chilies and saute till the water from the mushrooms evaporate and the vegetables are cooked.Once the vegetables are cooked add in all the spice powders, turmeric powder, cumin powder and red chilli powder.", "Stir well to combine.", "Spread the vegetables evenly in the pan, then slowly pour in the mixed batter and cover all the vegetables.Cook on low heat for about 5 minutes.", "The batter gets slowly cooked at the edges.", "Now start mixing it slowly, making sure it does not become mushy.Keep stir frying till it becomes brown and takes in the texture of bhurji, add salt and coriander leaves at this point.", "Serve the Besan Burji Recipe along with a\u00a0Banana Almond & Prunes Smoothie Recipe\u00a0as a healthy\u00a0breakfast."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Besan_Burji_Recipe__Chickpea_Flour_Scramble_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/616.Besan_Burji_Recipe__Chickpea_Flour_Scramble_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Whole Wheat Soya Keema Kulchas', 'whole-wheat-soya-keema-kulchas', 'Kulchas are delicious soft leavened bread which can be plain or even favoured and stuffed. Plain Kuchas are generally relished with any curry preparations but stuffed kulchas are usually served with curd and pickle. Stuffings are never restricted to only potato or paneer but many more things can be used for its stuffing. Also, usually kulchas are made using maida but here I am making Kulchas using healthy Vivatta chakki atta with very healthy stuffing of spicy soya keema. These Whole Wheat Soya Keema Kulchas make a perfect breakfast that is not only packed with protein but full of flavours too.', '["3-1/2 cups Whole Wheat Flour", "1/2 cup Curd (Dahi / Yogurt)", "1 cup Milk , warm", "1 teaspoon Ajwain (Carom seeds)", "1 teaspoon Baking soda", "1 teaspoon Sugar", "3 tablespoon Oil", "Lukewarm Water , as required", "1-1/2 cup Soy granules , (for keema)", "1/3 cup Onions , finely chopped", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Garlic , finely chopped", "1 teaspoon Ginger , grated", "1 tablespoon Oil", "2 teaspoon Lemon juice", "Salt , to taste", "1/2 cup Coriander (Dhania) Leaves , finely chopped", "2 Green Chillies , finely chopped", "2 tablespoons Mint Leaves (Pudina) , finely chopped", "Ghee , or butter or oil for frying kulchas"]'::jsonb, ARRAY['s whole wheat flour', 'curd', 'dahi / yogurt', 'milk', 'ajwain', 'carom seeds', 'baking soda', 'sugar', 'oil', 'lukewarm water', 'soy granules', 'onions', 'cumin seeds', 'jeera', 'red chilli powder', 'turmeric powder', 'haldi', 'garam masala powder', 'coriander powder', 'dhania', 'garlic', 'ginger', 'lemon juice', 'salt', 'coriander', 'reen chillies', 's mint leaves', 'pudina', 'ghee']::text[], '["To begin making the\u00a0Whole Wheat Soya Keema Kulchas, in a large bowl, combine all the ingredients mentioned under the \u201cFor the dough\u201d ingredients except water.", "Start mixing the dough.Gradually add warm water and knead it to a soft dough.", "Cover with clean damp cloth and keep it aside for 2 to 3 hours.", "For stuffing, boil the soya granules as per the packet instruction and cook until soft.", "Once done, drain the water.In a heavy bottomed pan, heat 1 tablespoon of oil; add cumin seeds and allow it to crackle.Add onions, garlic and ginger and saute until the onions are soft.", "Add red chili powder, turmeric powder, coriander powder and mix.", "Sprinkle few drops of water and cook the masala for few seconds.Add soya keema, garam masala, salt and toss well.", "Soya keema should be combined well with the masalas.", "Sprinkle lemon juice and cook for half a minute.", "Mixture should be dry, make sure that no water remains and you have a delicious mixture of the soy kheema.", "Check the salt and spices and adjust to suit your taste.Once done, turn off the heat and allow the soya kheema to cool down completely.Once the mixture is cooled, add green chilies, mint leaves and coriander leaves.", "Mix well.To prepare Kulchas,\u00a0knead the rested dough once again.Divide the dough into equal dough balls depending on the size of the kulcha you need.", "Also divide the mixture in equal portions as many as the dough balls.Take one ball of the dough.", "Roll it out into a small circle.", "Take the rolled circle in your palmPlace the keema mixture in the centre of the rolled small circle.", "Bring all the edges of the circle together to seal the mixture.On floured surface, gently press the stuffed ball, roll out into a uniform kulcha.", "Do not apply too much pressure at one place else the kulcha will tear and stuffing will come out.Place the Kheema Kulcha on the hot iron skillet\u00a0and allow it to get brown spots on the lower side.", "Flip it and repeat for the other side.", "Apply ghee, butter or oil and fry till you get nice brown spots and kulcha is cooked well.", "Once done, remove from the pan and serve.", "Proceed to make the remaining Kheema Kulchas the similar way.Serve the Whole Wheat Soya Keema Kulchas along with a\u00a0Boondi Raita,\u00a0Tomato Garlic Chutney, Achar and your dinner will be ready in a giffy."]'::jsonb, 220, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Farrukh_Aziz_Ansari/Whole_Wheat_Soya_Keema_Kulchas.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/617.Whole_Wheat_Soya_Keema_Kulchas.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Murgh Malai Kebab Recipe - Chicken Malai Kebab', 'murgh-malai-kebab-recipe-chicken-malai-kebab', 'Murgh Malai Kebab Recipe is a rich creamy kebab recipe from the Mughlai cuisine.  These melt in mouth Murgh Malai Kebab is dunked in a white margination of fresh cream, hung yogurt and cheese spread, with the addition of ginger- garlic-green chilli paste, further seasoned with some spice powders like nutmeg and cardamom lending their earthy notes to this royal dish.', '["400 grams Boneless chicken , cut into two inch cubes", "To be ground into paste", "2 inch Ginger", "8 cloves Garlic", "2 Green Chillies", "2 tablespoons Fresh cream", "2 tablespoons Britannia Cheese Spread - Asli Pepper", "2 tablespoons Hung Curd (Greek Yogurt)", "1/2 teaspoon Cardamom (Elaichi) Pods/Seeds", "1 teaspoon Garam masala powder", "1/2 teaspoon Nutmeg powder", "1/4 teaspoon White pepper powder", "1 tablespoon Lemon juice", "1 tablespoon Corn flour", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "Salt , to taste", "Butter (Salted) , for basting"]'::jsonb, ARRAY['s boneless chicken', 'to be ground into paste', 'ginger', 's garlic', 'reen chillies', 's fresh cream', 's britannia cheese spread - asli pepper', 's hung curd', 'greek yogurt', 'cardamom', 'elaichi', 'garam masala powder', 'nutmeg powder', 'white pepper powder', 'lemon juice', 'corn flour', 'kasuri methi', 'dried fenugreek leaves', 'salt', 'butter', 'salted']::text[], '["To begin making the Murgh Malai Kebab Recipe, prep all the ingredients for the marinade and keep it ready.", "Wash and pat dry the chicken too and set aside.", "Make a paste of the ginger, garlic and green chillies.", "You could optionally add 2 tablespoons of water to blend into a paste.To marinate the chicken, in a large mixing bowl, combine the fresh cream, hung curd, cream cheese, salt, ginger garlic and green chilli paste, garam masala powder, cardamom powder, nutmeg powder, white pepper powder, lemon juice, corn flour and kasuri methi.", "Mix well.", "Add in the boneless chicken cubes and mix well until the chicken is evenly coated.", "Cover the bowl and set aside the Murgh Malai Kebab to marinate for a minimum of 3 hours.", "You can also refrigerate it for a longer time.", "To bake in the oven, preheat the oven to 200 degree celsius for 10 minutes.", "Line a baking tray with aluminium foil, grease generously with oil.", "Arrange the Murgh Malai Kebab in skewers, place them on the baking tray and bake for 10 minutes.", "After 10 minutes, baste the Murgh Malai Kebab with butter and remaining marinade if any.", "Flip and bake for another 10-15 minutes or until done.", "Remove from the oven when almost done.", "Turn on the flame on your gas stove, hold the skewers over the flame, for a slightly roasted and smoked flavour and colour.", "Serve hot\u00a0Murgh Malai Kebab Recipe as an appetizer along with\u00a0Pudina Dahi Chutney Recipe Dip\u00a0and\u00a0Lacha Pyaz Recipe."]'::jsonb, 170, 'Mughlai', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Murgh_Malai_Kebab_Recipe_Chicken_Malai_Kebab_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/618.Murgh_Malai_Kebab_Recipe_Chicken_Malai_Kebab_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Broccoli Paneer And Peanut Masala Recipe', 'broccoli-paneer-and-peanut-masala-recipe', 'Broccoli is an all-star food with many health benefits. It is low in calories and rich in essential vitamins, minerals and fibre. It is also rich in anti-oxidants and has anti-cancer properties.', '["2 cups Broccoli , florets, heaped", "1 cup Paneer (Homemade Cottage Cheese) , cubes", "1 cup Raw Peanuts (Moongphali)", "4 Green Chillies", "4 Onions , chopped", "4 Tomatoes , chopped", "2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Whole Black Peppercorns", "1 teaspoon Kashmiri Red Chilli Powder", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Biryani Masala", "1/4 teaspoon Turmeric powder (Haldi)", "2 teaspoons Butter (Salted)", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'kashmiri red chilli powder', 'biryani masala', 'black peppercorns', 'onion', 'cumin seeds (jeera)', 'peanuts (moongphali)', 'kasuri methi (dried fenugreek leaves)', 'broccoli florets', 'turmeric powder', 'green chillies', 'butter', 'garam masala powder', 'paneer cubes']::text[], '["To begin with Broccoli Paneer And Peanut Masala, heat a teaspoon of oil in a wok.", "Add pepper corns and 1 teaspoon Jeera/ Cumin.Once it splutters, add the chopped onions and chillies.", "Roast till the onions turn slightly brown.Add the peanuts and roast for 3-4 minutes on medium flame.After 3-4 minutes, add the chopped tomatoes and mix well.", "Once the tomatoes turn mushy switch off the flame and allow it to cool.Once it reaches the room temperature, blend it into a fine paste in a blender.", "Keep the paste aside.Heat a teaspoon of oil in the same wok.", "Add jeera/cumin, chili powder and turmeric/ haldi.", "Add broccoli and saut\u00e9 on medium flame for 8 to 10 minutes.Add paneer, garam masala and biryani masala.", "Mix well and ensure it does not burn.", "Add the onion-tomato paste and mix well.Add salt, butter and let it simmer on medium flame for 5 to 8 minutes.", "Lastly, add kasuri methi and mix well.", "Switch off the flame after 5 minutes and it is ready to be served.Serve Broccoli Paneer And Peanut Masala with\u00a0phulka\u00a0or\u00a0whole wheat Lachha parathas\u00a0and\u00a0Beetroot Raita\u00a0for a delicious meal."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Preethi_Prasad/Broccoli_Paneer_and_Peanut_Masala.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/619.Broccoli_Paneer_and_Peanut_Masala.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Eerulli Palya Recipe - Vengaya Poriyal Recipe', 'eerulli-palya-recipe-vengaya-poriyal-recipe', 'Eerulli Palya Recipe is a simple and quick south indian onion poriyal or a stir fry that is slow cooked to get a perfectly soft texture and spiced along with green chillies and flavoured with mint and curry leaves to get that perfect taste.', '["4 Onions , thinly sliced", "1 Tomato , chopped", "2 Green Chillies , slit", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "2 sprig Curry leaves", "2 Dry Red Chillies", "1/4 teaspoon Asafoetida (hing)", "Salt , to taste", "1 teaspoon Oil", "Mint Leaves (Pudina) , small bunch chopped"]'::jsonb, ARRAY['onions', 'tomato', 'reen chillies', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'curry leaves', 'dry red chillies', 'asafoetida', 'hing', 'salt', 'oil', 'mint leaves', 'pudina']::text[], '["To begin making Eerulli Palya Recipe-Onion Poriyal Sabzi Recipe prep all the ingredients and keep them ready.Preheat oil in a pan over medium heat;\u00a0add the mustard seeds and allow it to crackle.Once it crackles, add the cumin seeds and red chillies and roast for a few seconds.", "After a few seconds, stir in the curry leaves and the sliced onions and green chillies.Saute the onions on low to medium heat until it becomes slightly soft and tender and browned as well.", "Once the onions have that light golden brown texture, add the tomatoes and allow it to cook until it softens.Once the tomatoes softe, add the turmeric powder, red chilli powder and stir well to combine.", "Cover the Eerulli Palya and cook for few more minutes until you get a masaledar texture and taste.", "Adjust the salt and chilli accordingly at this stageOnce done, you can optionally stir in chopped mint leaves and coriander leaves and transfer the\u00a0Eerulli Palya to a serving bowl and serve hot.Serve\u00a0Eerulli Palya Recipe with hot steamed rice, Jolada Roti,\u00a0Beetroot Poriyal Recipe,\u00a0\u00a0Pasi Paruppu Masiyal\u00a0and\u00a0Vellarikka Kosumalli\u00a0\u00a0for a South Indian lunch or dinner."]'::jsonb, 20, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Eerulli_palya_recipe_Onion_Poriyal_Sabzi_recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/620.Eerulli_palya_recipe_Onion_Poriyal_Sabzi_recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Barnyard Millet Mushroom Biryani Recipe', 'barnyard-millet-mushroom-biryani-recipe', 'Barnyard Millet Mushroom Biryani Recipe is a flavorful one pot preparation made with barnyard millet which is popularly called as samvat, Kuthiraivali, Udalu and oodalu in other regional languages. It is considered to be a valuable ingredient during the season of fasting.', '["1-1/2 cup Barnyard Millet , washed and soaked in water", "2 tablespoon Oil", "1 Bay leaf (tej patta)", "1 Cardamom (Elaichi) Pods/Seeds", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 Star anise", "2 sprig Curry leaves", "2 Green Chillies , slit", "6 cloves Garlic , finely chopped", "2 inch Ginger , finely chopped", "2 Onions , sliced", "300 grams Button mushrooms , cut into halves", "Salt , to taste", "1 teaspoon Coriander (Dhania) Powder", "1 teaspoon Black pepper powder", "1 teaspoon Garam masala powder", "1/2 cup Curd (Dahi / Yogurt)", "1/4 cup Coriander (Dhania) Leaves , finely chopped", "1/4 cup Mint Leaves (Pudina) , finely chopped"]'::jsonb, ARRAY['tomato', 'cloves garlic', 'curry leaves', 'st flower', 'onion', 'turmeric powder', 'salt', 'green chilli', 'cardamom (elaichi) podsseeds', 'barnyard millet', 'star anise', 'garam masala powder', 'mint leaves (pudina)', 'red chilli powder', 'button mushrooms', 'ginger', 'bay leaves (tej patta)', 'coriander (dhania) leaves', 'cinnamon stick (dalchini)', 'coriander powder', 'cloves (laung)']::text[], '["To begin making the Barnyard Millet Mushroom Biryani Recipe, prep all the ingredients and keep them ready.Heat a pressure cooker with oil on medium heat.", "Once hot, add all the whole spices, bay leaf, cardamom, cloves, cinnamon and star anise.", "When these spices begin to sizzle, add in the curry leaves, ginger, garlic, onion and slit green chillies.", "Saute until the onions on medium low heat until the onions turn slightly caramelised.Next add in the quartered mushrooms, salt, black pepper powder, garam masala powder.", "Saute for about a minute.Reduce the heat; add in the curd, chopped coriander and mint leaves and the drained barnyard millet along with 1-1/2 cups of water.Pressure cook for 2 to 3 whistles, turn the heat to low and simmer for 2 minutes and turn off the heat.", "Allow the pressure to release naturally.Once the pressure has released, fluff the Barnyard Millet Mushroom Biryani with a fork and serve.", "Serve the Barnyard Millet Mushroom Biryani Recipe along with a\u00a0spinach Raita\u00a0to go along with your meal."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Barnyard_Millet_Mushroom_Biryani_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/621.Barnyard_Millet_Mushroom_Biryani_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Matar Butter Masala Recipe', 'matar-butter-masala-recipe', 'Matar Butter Masala Recipe is a delicious and creamy green peas gravy dish. Boiled green peas dunked in a rich tomato onion gravy, while the spices give it a brilliant flavour, while the cashew paste, gives it a rich and creamy texture.', '["10 Cashew nuts , soaked in 1/2 cup hot water", "To be ground into a fine paste", "2 Onions , roughly chopped", "1 inch Ginger", "8 cloves Garlic", "1 Green Chilli", "Other ingredients", "200 grams Green peas (Matar)", "2 tablespoons Butter (Salted)", "1 Bay leaf (tej patta)", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoons Kashmiri Red Chilli Powder", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "5 Tomatoes , pureed", "1 teaspoon Sugar", "1 teaspoon Garam masala powder", "2 tablespoons Fresh cream", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "6 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['tomato', 'cashew nuts', 'salt', 'ginger', 'kashmiri red chilli powder', 'green chilli', 'bay leaves (tej patta)', 'green peas (matar)', 'cloves garlic', 'sugar', 'coriander powder', 'kasuri methi (dried fenugreek leaves)', 'butter']::text[], '["To begin making the Matar Butter Masala Recipe, firstly boil the peas in a pressure cooker.", "Place the fresh or frozen green peas in a pressure cooker with 1/2 cup of water and some salt.", "Pressure cook for one whistle and turn off the heat.", "Immediately release the pressure to prevent the peas from getting over cooked at the same time retaining its fresh green colours.", "Set aside.", "To make the cashew paste, ensure the cashews are soaked in hot water for 15-20 minutes.", "Transfer the water and cashews into a mixer jar and blend to make a smooth paste.", "Set aside.", "To make the onion paste, in a mixer jar, combine the onions, ginger, garlic, green chilli and grind into a fine paste.", "Set aside.", "Roughly chop the tomatoes and blend to make a puree in a mixer grinder.", "Keep aside.Finally to make the Matar Butter Masala; heat butter in a heavy bottom pan over medium heat; add the bay leaf and the onion paste and saute for a good 2-3 minutes stirring continuously for about 2 minutes.After couple of minutes, stir in the salt, turmeric powder, coriander powder and red chilli powder.", "Saute for 30 to 40 seconds.", "This sauteeing along with spices helps the raw smell go away faster and uses less oil too.", "Next add the tomato puree, cover and cook for about 5 minutes or until the tomatoes get a bright red colour and are cooked completely.Stir in the boiled peas along with the water and adjust the consistency of the gravy to your preference by adding more water if required.Finally add in the sugar, kasuri methi and fresh cream, bring the Matar Butter Masala to a brisk boil and turn off the heat.", "Adjust the salt and seasoning according to your taste, stir in the freshly chopped coriander leaves and transfer the Matar Butter Masala to a serving bowl.Serve the hot Matar Butter Masala along with\u00a0Garlic Naan Without Yeast Recipe\u00a0and\u00a0Jeera Rice Recipe\u00a0and\u00a0Mint Pomegranate Raita Recipe\u00a0for a weekend lunch."]'::jsonb, 25, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Matar_Butter_Masala_Recipe_Peas_Masala_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/622.Matar_Butter_Masala_Recipe_Peas_Masala_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rajma Kofta In Milk And Poppy Seed Gravy Recipe', 'rajma-kofta-in-milk-and-poppy-seed-gravy-recipe', 'Koftas are traditional Indian recipes mostly well done by the vegetarians. A peculiar variation is the key for making interesting koftas and this Rajma Kofta In Milk And Poppy Seed Gravy Recipe uses cooked rajma paste instead of regular besan, lentils etc as the basic ingredient to make the yummy kofta balls for shallow frying in paniyaram pan. Once fried those can be served as an appetizer but I have cooked a special gravy with milk and poppy seeds paste to make this recipe a delightful vegetarian side dish which can be served with various flatbreads or rice recipes.', '["1/2 cup Rajma (Large Kidney Beans)", "1/4 cup Cashew nuts", "2 tablespoons Sultana Raisins", "1/4 teaspoon Asafoetida (hing)", "1/4 teaspoon Cumin seeds (Jeera)", "2 tablespoons Gram flour (besan)", "1/4 teaspoon Red Chilli powder", "2 teaspoons Coriander (Dhania) Leaves , chopped", "2 teaspoons Ghee", "3 teaspoons Poppy seeds , ground to paste", "1 teaspoons Fresh cream", "1/2 cup Milk", "1/2 teaspoon Garam masala powder", "Water , as required", "Salt , to taste", "Saffron strands , a few to garnish"]'::jsonb, ARRAY['cashew nuts', 'salt', 'asafoetida (hing)', 'coriander (dhania) leaves', 'ghee', 'milk', 'saffron strands', 'raisins', 'red chilli powder', 'water', 'gram flour (besan)', 'cumin seeds (jeera)', 'poppy seeds ground paste', 'rajma (large kidney beans)', 'garam masala powder']::text[], '["To begin making Rajma Kofta In Milk And Poppy Seed Gravy Recipe, prepare the koftas first.", "Remember to first soak the rajma overnight and pressure cook with salt until the rajma is cooked and softened.Blend the boiled rajma, besan, cashew, raisins, chilli powder, hing, coriander leaves and salt in a food processor.", "Check for seasoning and adjust.", "Spread this mashed spiced rajma on a thali or a large plate.", "Make small round balls of rajma kofta with your palm.Heat a frying pan with half ghee and fry the kofta balls for about 10 minutes.", "Set aside.What you can also do is, heat a kuzhi paniyaram pan, drop in a few drops of oil into each cavity and put in these balls into each cavity.", "Once browned on the bottom, you can rotate the kofta balls and brown them evenly from the other side as well.", "This is a healthier way to prepare koftas instead of deep frying them in traditional way.Take a kadai and heat ghee, add cumin and allow to sizzle.Once sizzling, add in milk, cream, poppy seed paste and garam masala powder.", "Add salt and stir.", "Add water only if needed.Cook till the mixture comes to one boil and add the koftas and Switch off heat after half a minute.", "Serve with your favourite garnish like saffron or coriander leaves.Serve Rajma Kofta In Milk And Poppy Seed Gravy Recipe along with Saffron Pilaf Recipe (Kesar Pulao) and Pudina Tawa Paratha Recipe for lunch or dinner with Green Moong Sprout Salad With Capsicum And Carrots to complete the meal."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/ruby_pathak-yahoo.com/Rajma_Kofta_in_Milk_and_Poppy_Seed_Gravy.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/623.Rajma_Kofta_in_Milk_and_Poppy_Seed_Gravy.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Avarekalu Chitranna Recipe (Field Beans Tossed With Lemon Rice)', 'karnataka-style-avarekalu-chitranna-recipe-field-beans-tossed-with-lemon-rice', 'Karnataka Style Avarekalu Chitranna Recipe (Field Beans Tossed With Lemon Rice) is a special breakfast made in most of the Karnataka Style households. Bengaluru is the only place where they celebrate “Avarekalu Mela” during the month of January. The mela consists of series of stalls selling out dishes that are made from these field beans or avarekalu beans.', '["1 cup Avarekalu / Lilva Beans", "2 cups Rice , boiled", "1 pinch Turmeric powder (Haldi)", "1 pinch Asafoetida (hing)", "5 Green Chillies , slit", "5 Curry leaves", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon White Urad Dal (Split)", "1 Lemon juice", "3 sprig Coriander (Dhania) Leaves", "2 Onion , chopped", "Ghee , or oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'rice', 'asafoetida (hing)', 'mustard seeds', 'curry leaves', 'white urad dal (split)', 'coriander (dhania) leaves', 'onion', 'lemon', 'ghee', 'oil', 'avarekalu lilva beans', 'turmeric powder', 'green chillies']::text[], '["We begin making the Karnataka Style Avarekalu Chitranna Recipe by cooking the rice separately in a pressure cooker.", "Release the pressure naturally, once that is done add some oil and mix it well.", "Keep it aside.Cook the avarekalu in a sauce pan with water separately till is soft.", "Then strain the water and keep it aside.Then heat a kadai with some oil, temper the mustard seeds, urad dal, hing and curry leaves.Once that is done, add the onions and green chilies and saut\u00e9 till it is golden brown, and add the boiled avarekalu and saute.Now you can add the boiled rice, switch off the heat, sprinkle the lemon juice, chopped coriander and give it a stir.", "Check for salt according to your taste.Serve the Karnataka Style Avarekalu Chitranna Recipe (Field Beans Tossed With Lemon Rice) as a delicious\u00a0Breakfast recipe\u00a0along with some Mango Pickle."]'::jsonb, 40, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Karnataka_Style_Avarekalu_Chitranna_Recipe_Field_Beans_Tossed_With_Lemon_Rice.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/624.Karnataka_Style_Avarekalu_Chitranna_Recipe_Field_Beans_Tossed_With_Lemon_Rice.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Cauliflower Pepper Fry Recipe - Chettinad Poo Kosu Poriyal', 'chettinad-cauliflower-pepper-fry-recipe-chettinad-poo-kosu-poriyal', 'Chettinad Poo Kosu Poriyal also known as Chettinad Milagu Pirattal Poriyal is a classic dish from Chettinad (Tamil Nadu). Chettinad Cuisine is very popular for its recipes to use, small onions, black pepper and lots of spices. The addition of black pepper in this cauliflower recipe along with sauteed onions, brings out great taste.', '["1 Cauliflower (gobi) , cut into florets", "12 Pearl onions (Sambar Onions) , finely chopped", "4 cloves Garlic , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Black pepper powder", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Cinnamon Powder (Dalchini)", "2 Cloves (Laung)", "1/2 teaspoon Coriander Powder (Dhania)", "1 teaspoon Salt , or to taste", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "2 sprig Curry leaves", "1 tablespoon Oil , for cooking"]'::jsonb, ARRAY['cauliflower', 'gobi', 'pearl onions', 'sambar onions', 's garlic', 'turmeric powder', 'haldi', 'black pepper powder', 'red chilli powder', 'cinnamon powder', 'dalchini', 'laung', 'coriander powder', 'dhania', 'salt', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'curry leaves', 'oil']::text[], '["To begin making the\u00a0Chettinad Cauliflower Pepper Fry Recipe (Milagu Pirattal Poriyal), first get all the ingredient ready and keep it by the side.", "It always helps to have things ready so the cooking process can be faster and quicker.We will steam the cauliflower in the steamer until it is firm and yet cooked.", "Steaming, retains the nutrition of the vegetable and helps the cooking process of the\u00a0Chettinad Cauliflower Pepper Fry Recipe faster.", "This should not take more than 3 to 4 minutes on high heat.Heat a tablespoon of oil in\u00a0heavy bottomed pan or a kadai\u00a0on medium heat.", "Add the mustard seeds and allow it to crackle.", "Add the chopped onion and garlic and saute on low to medium heat until the onions have turned lightly golden brown.Take care not to burn the onion and garlic.", "Next add the curry leaves, cloves, turmeric powder, red chilli powder, black pepper, cinnamon and coriander powder.", "Give it a stir and add the steamed cauliflower florets.Sprinkle some salt and stir all the ingredients carefully until the spices coat the cauliflower well.", "Turn the heat to low, cover the pan and simmer for about 3 to 4 minutes until the\u00a0Chettinad Cauliflower is well coated with the masala.", "Check the salt and spices and adjust to suit your taste.Serve the\u00a0Chettinad Cauliflower Pepper Fry along with Vendakkai Sambar and Steamed Rice for weekend lunch or weeknight dinner."]'::jsonb, 35, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Chettinad_Cauliflower_Curry_Milagu_Pirattal_Poriyal_Recipe-9.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/625.Chettinad_Cauliflower_Curry_Milagu_Pirattal_Poriyal_Recipe-9.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Huggi (Rice and Moong dal Savory Porridge)', 'karnataka-style-huggi-rice-and-moong-dal-savory-porridge', 'Karnataka Style Huggi (Rice and Moong dal Savory Porridge)  Recipe is a traditional khichdi prepared in Karnataka. During the famous festival Sri Krishna Matt that is celebrated in parts of Udupi.  It is nothing but similar to “kara Pongal” that is prepared in Tamil Nadu. Huggi is usually accompanied along with tamarind gojju. Where the tanginess of the gravy goes along with the subtle but rich flavor of the lentil and rice.', '["1 cup Rice", "1 Yellow Moong Dal (Split)", "1 teaspoon Turmeric powder (Haldi)", "1 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "1 tablespoon Ghee", "1 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)"]'::jsonb, ARRAY['rice', 'yellow moong dal', 'split', 'turmeric powder', 'haldi', 'cardamom', 'elaichi', 'cinnamon stick', 'dalchini', 'ghee']::text[], '["We begin making the Karnataka Style Huggi Recipe by pressure cooking the rice and moong dal with 3 cups of water and salt for about 3 whistle.Then open the cooker once the pressure is released, add in turmeric powder, spices like cardamom, clove and cinnamon.", "Keep cooking till the rice and moong dal are fully cooked.Check for seasoning and switch off the flame.", "Heat a small kadai, melt the ghee and add the spice to crackle and pour it over the rice and serve.Serve the Karnataka Style Huggi Recipe along with Karnataka Style\u00a0Tamarind Gojju Recipe\u00a0along with\u00a0Dry Palak Dal Sabzi Recipe\u00a0to make it a complete meal."]'::jsonb, 30, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Karnataka_Style_Huggi_Rice_and_Moong_dal_Savory_Porridge.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/626.Karnataka_Style_Huggi_Rice_and_Moong_dal_Savory_Porridge.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kodava Pacche Baale Barthad- Raw Banana Stir Fry', 'kodava-pacche-baale-barthad-raw-banana-stir-fry', 'Kodava Pacche Baale Barthad- Raw Banana Stir Fry a simple stir fry of raw banana that is toasted well on the pan and mixed along with ground masala. The flavour from ginger, garlic, green chillies, pepper corns and curry leaves goes really well with the raw banana. Tamarind adds in a slight bit of sourness and helps balance the whole flavour of the dish. In kodava cuisine, anything that is stir fried with ground masala is called as “Barthad”.', '["2 Raw Banana , boiled and skin peeled, cut into cubes", "1 tablespoon Coconut Oil , for cooking", "Salt , to taste", "To Grind", "4 cloves Garlic , chopped", "1 inch Ginger , chopped", "2 Green Chillies", "2 sprig Curry leaves", "1 teaspoon Black pepper corns", "10 grams Tamarind"]'::jsonb, ARRAY['raw banana', 'coconut oil', 'salt', 'to grind', 's garlic', 'ginger', 'reen chillies', 'curry leaves', 'black pepper corns', 's tamarind']::text[], '["To begin making the Kodava Pacche Baale Barthad- Raw Banana Stir Fry, peel the skin of the raw banana and chop the raw banana into small cubes.Grind the garlic, ginger, green chillies and pepper into a coarse paste.Heat a kadai over medium heat with coconut oil, add curry leaves and allow it to crackle for few seconds, once done take the curry leaves out and keep aside.Add in the cooked raw banana and saute till it crisps up slightly.", "You can sprinkle some salt and turmeric powder and saute so that the raw banana gets cooked faster.", "Once that is done add ground paste, sprinkle some more salt to taste, crush the curry leaves and saute well.", "Cook the\u00a0Pacche Baale Barthad until the ground masala is cooked and tossed well with raw banana and switch off the heat.Check the salt and spices and adjust to suit your taste.", "Once done, transfer the\u00a0Pacche Baale Barthad to a serving bowl.Serve the\u00a0Kodava Pacche Baale Barthad- Raw Banana Stir Fry\u00a0along with\u00a0Kerala Kadala Curry Recipe,\u00a0Jowar Atta Roti\u00a0and\u00a0Raw Mango Raita\u00a0for your everyday dinner meal."]'::jsonb, 25, 'Coorg', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/June-22/Raw_Banana_Fry_-_Coorg_Style_Recipe-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/627.Raw_Banana_Fry_-_Coorg_Style_Recipe-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Drumstick Leaves Ragi Roti Recipe - Moringa Millet Flat Bread', 'drumstick-leaves-ragi-roti-recipe-moringa-millet-flat-bread', 'The Drumstick Leaves Ragi Roti Recipe is a healthy roti recipe that is made from ragi flour, packed with the goodness of  drumstick leaves and flavored with green chillies and ginger.', '["2 cups Ragi Flour (Finger Millet/ Nagli)", "1 cup Whole Wheat Flour", "2 Green Chillies , finely chopped", "1 inch Ginger , grated", "100 grams Drumstick Leaves (Moringa/Murungai Keerai) , finely chopped", "1/2 teaspoon Black pepper powder", "Salt , to taste", "Ghee , for smearing rotis"]'::jsonb, ARRAY['salt', 'wheat flour', 'ginger', 'ghee rotis', 'drumstick leaves (moringamurungai keerai)', 'ragi flour (finger millet nagli)', 'black pepper powder', 'green chillies']::text[], '["To begin making the Drumstick Leaves Ragi Roti Recipe, combine all the ingredients like the ragi flour, whole wheat flour, green chillies, ginger, drumstick leaves, black pepper powder and salt in a large mixing bowl.Add little water at a time and knead the Drumstick Leaves Ragi Roti dough for about 3 to 4 minutes until soft and smooth.", "Cover the Ragi Roti dough and allow it to rest for about 10 minutes.The next step is to cook the Drumstick Leaves Ragi Roti, make sure you have set the table out to serve your family and friends; as this Ragi Roti has to be served hot from the stove to plate.Preheat and grease a skillet with oil.Place a portion of the Drumstick Leaves Ragi Roti on the surface, dust it with flour and roll to make a roti.", "Once you have rolled it out, place it on the preheated tawa.Add ghee or oil along the sides of the\u00a0Drumstick Leaves Ragi Roti and cook on both sides on a medium heat until the roti is cooked and lightly crisp.Once done, remove from heat and serve the hot Drumstick Leaves Ragi Roti.", "Proceed the same way with the remaining dough portions.Serve the\u00a0Drumstick Leaves Ragi Roti Recipe, along with\u00a0Mango Chutney\u00a0and\u00a0Homemade Yogurt\u00a0for a wholesome Breakfast or serve with\u00a0Dal Kabila\u00a0or\u00a0\u00a0Bharwa Karela Makhani\u00a0for a diabetic friendly meal."]'::jsonb, 50, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breakfast_Tiffins/Ragi_Roti_Paratha_Recipe_Mangalore_Karnataka_Cuisine_Breakfast-13.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/628.Ragi_Roti_Paratha_Recipe_Mangalore_Karnataka_Cuisine_Breakfast-13.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Beans And Carrot Masala Pulav With Black Eyed Beans Recipe', 'beans-and-carrot-masala-pulav-with-black-eyed-beans-recipe', 'The Beans and Carrot Masala Pulav with Black Eyed Beans, is a wholesome and delicious combination of rice along with spices. Combining black eyed beans (known as Lobia, or Kara Mani or Chora in various Indian languages) along with rice, spices and nuts was one of the best dishes I have savored in my lifetime of marriage into the Gujarati food. Black-eyed beans are one of the few beans that easily absorb the spices thrown into it and it dresses the Pulav deliciously.', '["1/4 cup Black Eyed Beans (Lobia)", "1 cup Rice", "2 Carrots (Gajjar) , finely chopped", "5 to 6 Green beans (French Beans) , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "2 Tomatoes , finely chopped", "1 Bay leaves (tej patta)", "1 inch Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "1/2 teaspoon Cumin seeds (Jeera)", "2 Green Chillies , slit", "1 tablespoon Mint Leaves (Pudina) , chopped", "1 tablespoon Ghee", "Salt , to taste"]'::jsonb, ARRAY['black eyed beans', 'lobia', 'rice', 'carrots', 'gajjar', 'to 6 green beans', 'french beans', 'turmeric powder', 'haldi', 'tomatoes', 'bay leaves', 'tej patta', 'cinnamon stick', 'dalchini', 'cardamom', 'elaichi', 'cumin seeds', 'jeera', 'reen chillies', 'mint leaves', 'pudina', 'ghee', 'salt']::text[], '["To begin making the Beans and Carrot Masala Pulav with Black Eyed Beans, we will first cook the black eyed beans along with salt in 1 cup of water until soft and tender in a pressure cooker.Place the beans, salt and water in a pressure cooker, cover the cooker, place the weight on and pressure cooker for 2 to 3 whistles.After the 3 whistles, turn the heat to low and simmer the beans for about 5 minutes and then turn off the heat.Next step is to steam the vegetables.", "Place the vegetables in a steamer, sprinkle some salt and steam for 4 to 7 minutes, until the vegetables are power cooked (not too soft and not to firm).Strain the excess water and set aside the cooked beans.", "Wash and soak the rice in 2 cups of water for 1 hour.", "Using a pestle and motor pound the cardamom, cinnamon and cloves to a fine powder and set aside.In the next step we will be cooking the beans and rice along with spices to make the Masala Pulao.Heat ghee in a large\u00a0sauce pan\u00a0on medium heat; add the cumin seeds and allow them to crackle.", "Stir in the pounded spice powder, bay leaf, turmeric powder, green chillies and chopped tomatoes.", "Saut\u00e9 the above mixture until the tomatoes become tender and soft.Stir in the rice and salt along with the water that it was soaked in.", "Allow the mixture to come to a boil and then turn the heat to low.", "Cover the pan and simmer to cook the rice.", "Once 10 minutes of the cooking process has passed stir in the black eyed beans and the chopped mint leaves.Simmer to cook the rice further for 15 or more minutes until the rice has been fully cooked and all the water has been absorbed.", "Turn off the heat and let the rice rest for 10 minutes before you can open to stir.", "Gently stir in the steamed green peas and serve warm.Simmer to cook the rice further for 15 or more minutes until the rice has been fully cooked and all the water has been absorbed.Turn off the heat and let the rice rest for 10 minutes before you can open to stir.", "Check the salt and spice levels and adjust to suit your taste.", "Gently stir in the steamed vegetables and serve warm.Beans And Carrot Masala Pulav With Black Eyed Beans\u00a0serves as a great wholesome one dish meal along with\u00a0Gujarati Kadhi\u00a0and\u00a0Strawberry Raita\u00a0accompanied along with crispy Masala Papad."]'::jsonb, 55, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Beans_and_Carrot_Masala_Pulav_with_Black_Eyed_Beans-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/629.Beans_and_Carrot_Masala_Pulav_with_Black_Eyed_Beans-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mysore Style Avarekalu Rasam Recipe', 'mysore-style-avarekalu-rasam-recipe', 'Mysore Style Avarekalu Rasam Recipe is a delicious rasam made from the Avarekalu which is a part of broad bean category. The beans are famous in Karnataka which they use to make various dishes. Avarekalu are hyacinth beans which are rich in calcium and iron. The beans are steamed and then ground along with Mysore Style Rasam powder.Since Avarekalu season starts from December to January, in many parts of Karnataka, people love to prepare a homemade dishes using this.', '["1 cup Avarekalu / Lilva Beans", "1 cup Tamarind Water", "2 Tomatoes , chopped", "2 teaspoons Fresh coconut", "1 teaspoon Jaggery", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 teaspoon Coriander (Dhania) Seeds", "2 Dry Red Chillies", "1 Byadagi Dried Chillies", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Whole Black Peppercorns", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 sprig Curry leaves", "Ghee , for cooking"]'::jsonb, ARRAY['tomato', 'salt', 'tamarind water', 'coconut', 'mustard seeds', 'ghee', 'jaggery', 'black peppercorns', 'curry leaves', 'byadagi dried chillies', 'coriander (dhania) seeds', 'dry red chillies', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'avarekalu lilva beans', 'turmeric powder']::text[], '["To begin making the Mysore Style Avarekalu Rasam Recipe, we will pressure cook the Avarekalu with 1 cup water and a pinch of salt for about 1 whistle.", "Turn off the flame and allow to release the pressure naturally and then open the lid.Next to make the rasam masala,\u00a0 in a small skillet, heat some ghee on low flame and roast the spices -coriander seeds, dry red chillies, byadgi dried Chillies, cumin seeds, whole black peppercorns, mustard seeds, fenugreek seedsRoast them until you get a nice aroma for about 10 minutes.", "Once done, cool the mixture and blitz it to a smooth powder using a mixer grinder.Add fresh coconut, boiled avarekalu and give it a blitz.", "Grind it into a coarse paste.Heat a saucepan with tamarind water, tomato, green chilli and turmeric powder allow it to boil for 10 minutes.Add this ground paste into the\u00a0Avarekalu Rasam\u00a0 that is being boiled, add salt, jaggery and adjust according to your palate.To temper, heat a small amount of oil, add mustard seeds and allow it to crackle and then add curry leaves, hing and leave it for 10 seconds and pour it over the boiling rasam and serve hot.Serve the Mysore Style Avarekalu Rasam Recipe along with\u00a0steamed rice,\u00a0Cabbage Palya Recipe, and\u00a0curd rice\u00a0to finish it off with."]'::jsonb, 40, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Mysore_Style_Avarekalu_Rasam_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/630.Mysore_Style_Avarekalu_Rasam_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Vendakka Pachadi Recipe - Roasted Bhindi Coconut Raita', 'kerala-style-vendakka-pachadi-recipe-roasted-bhindi-coconut-raita', 'Kerala Style Vendakka Pachadi Recipe is an essential side dish at any Kerala Sadya, a popular feast.', '["150 grams Bhindi (Lady Finger/Okra) , cut into rounds", "Salt , to taste", "Oil", "2 Green Chillies", "1 teaspoon Cumin seeds (Jeera)", "1/4 cup Fresh coconut", "2 cups Curd (Dahi / Yogurt) , whisked", "Salt , to taste", "1 teaspoon Coconut Oil", "1 teaspoon White Urad Dal (Split)", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves"]'::jsonb, ARRAY['s bhindi', 'lady finger/okra', 'salt', 'oil', 'reen chillies', 'cumin seeds', 'jeera', 'fresh coconut', 's curd', 'dahi / yogurt', 'coconut oil', 'white urad dal', 'split', 'mustard seeds', 'rai/ kadugu', 'curry leaves']::text[], '["To begin making the Kerala Style Vendakka Pachadi Recipe, wash the vendakkai well and pat dry them on a kitchen towel.", "Once dry, slice them thin rounds, lightly salt them and keep it ready.", "Heat oil in a pan on medium heat, and shallow fry the vendakkai till well cooked and crispy.", "Make sure not to burn them, since they are thinly sliced into rounds they will tend to brown quickly.Once crispy, using a slotted spoon remove the roasted Vendakka from the pan and place it on a plate lined with kitchen paper towel.", "To make the coconut paste , into a mixer jar add the coconut, cumin seeds and green chilli and blend along with 1/4 cup of warm water to make a smooth paste.", "Keep this asideIn a mixing bowl, combine the finely ground coconut paste, curd and salt and whisk well and set aside.", "To make the tadka for the Vendakka Pachadi, heat oil on medium heat in a tadka pan; add the mustard seeds and split urad dal and let allow the seeds to crackle and the dal to turn slightly golden brown and crisp.", "Stir in the curry leaves and turn off the heat.Stir in the tadka to the coconut curd pachadi mixture and finally stir in the vendakka to make the delicious Vendakka Pachadi.", "Refrigerate the Vendakka Pachadi and serve chilled along with a meal.Serve Kerala Style Vendakka Pachadi with hot\u00a0Steamed rice,\u00a0Thakkali Rasam\u00a0and\u00a0Beetroot thoran\u00a0for a healthy lunch or dinner."]'::jsonb, 30, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Donna_George/Kerala_Style_Vendakkai_Pchadi_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/631.Kerala_Style_Vendakkai_Pchadi_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Nargisi Kofta Curry Recipe - Spicy Scotched Egg Curry', 'nargisi-kofta-curry-recipe-spicy-scotched-egg-curry', 'Mughlai cuisine consisted a list of dishes developed in Medieval India at the time of Mughal empire. Mughlai cooking dishes are array of recipes from Central Asia and North India. Mughlai food is known for its richness, exotic taste and spiciness.', '["4 Whole Egg , hard boiled and peeled", "500 grams Mutton , keema", "2 tablespoons Ginger , paste", "2 tablespoons Garlic , paste", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Turmeric powder (Haldi)", "1/2 tablespoon Kashmiri Red Chilli Powder", "1 teaspoon Garam masala powder", "1 tablespoon Corn flour", "2 tablespoon Mustard oil", "Salt , to taste", "1 cup Curd (Dahi / Yogurt)", "1 Onion , chopped", "1 teaspoon Turmeric powder (Haldi)", "1 tablespoon Green Chilli Paste", "1 teaspoon Red Chilli powder", "1 teaspoon Garlic , paste", "1 teaspoon Ginger , paste", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Garam masala powder", "1 tablespoon Homemade tomato puree", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "1 Bay leaf (tej patta)", "2 Dry Red Chilli", "Salt , for seasoning", "Oil , as required"]'::jsonb, ARRAY['tomato', 'cumin powder (jeera)', 'kashmiri red chilli powder', 'onion', 'turmeric powder', 'green chilli paste', 'sunflower oil', 'salt', 'corn flour', 'ginger paste', 'eggs', 'mustard oil', 'garam masala powder', 'red chilli powder', 'dry red chilli', 'curd', 'kasuri methi (dried fenugreek leaves)', 'garlic paste', 'bay leaf (tej patta)', 'mutton keema', 'coriander powder']::text[], '["To begin making the Nargisi Kofta Curry recipe, hard boil the eggs in a saucepan with some water.", "Peel the outer shelf and keep it aside.In a food processor blend mutton keema very well to make it soft and tender.Transfer it in a bowl, add turmeric powder, red chilli powder, coriander powder, salt, ginger garlic paste, oil, garam masala powder and corn flour.", "Mix it very nicely using hands.Divide the mixture into four parts.", "Put some oil in your palm and take one portion of keema mixture and pat it to form like a chapati.Place a hard boiled egg in between the flatten keema mixture and cover the egg with it.", "Do the same to all eggs.", "Keep aside.The next step is to prepare the gravy.", "Heat oil in a big pan or kadai.Add dry red chilli and bay leaf.", "Roast the chilies for a minute then add chopped onions.", "Fry the onions until light brown.Add ginger garlic paste, green chilli paste and fry a little bit.", "Add tomato puree, coriander, cumin, red chilli and turmeric powder.", "Fry until the oil separates.Whisk yogurt with salt and add in the masala mixture.", "Mix well and add one cup of warm water.", "Let it boil.After it starts bubbling slowly add keema wrapped egg on the gravy.", "Let it cook for 30 to 35 minutes.After 30-35 minutes check the seasoning add garam masala powder and sprinkle some kasuri methi.", "Serve hot.Serve Nargisi Kofta Curry along with\u00a0Boondi Raita,\u00a0Whole Wheat Lachha Paratha\u00a0and\u00a0Kachumber Salad\u00a0for a weeknight dinner."]'::jsonb, 75, 'Mughlai', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/usashis-gmail.com/Nargisi_Kofta_CurrySpicy_scotched_egg_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/632.Nargisi_Kofta_CurrySpicy_scotched_egg_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dhaba Style Dal Fry Recipe | Mixed Dal Tadka', 'dhaba-style-dal-fry-recipe-mixed-dal-tadka', 'Dhaba Style Dal Fry is a perfect dal when you want to have something spicy yet simple. The creamy dal fry consists of  different kind of dals like Toor Dal, Urad Dal, Masoor Dal and Chana Dal and also a little rajma and Kala chana ti give it that added texture and taste.', '["1/4 cup Arhar dal (Split Toor Dal)", "2 tablespoons Chana dal (Bengal Gram Dal)", "2 tablespoons Masoor Dal (Whole)", "2 tablespoons White Urad Dal (Split)", "2 tablespoons Kashmiri Rajma", "2 tablespoons Kala Chana (Brown Chickpeas)", "2 tablespoons Ghee", "1 teaspoon Cumin seeds (Jeera)", "1 Onion , finely chopped", "2 inch Ginger , finely chopped", "2 Green Chillies , finely chopped", "2 inch Cinnamon Stick (Dalchini) , broken", "2 Cardamom (Elaichi) Pods/Seeds", "2 Bay leaves (tej patta) , torn", "2 Tomatoes , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Garam masala powder", "Salt , to taste", "1 Lemon , juice extracted", "6 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['arhar dal', 'split toor dal', 's chana dal', 'bengal gram dal', 's masoor dal', 'whole', 's white urad dal', 'split', 's kashmiri rajma', 's kala chana', 'brown chickpeas', 's ghee', 'cumin seeds', 'jeera', 'onion', 'ginger', 'reen chillies', 'cinnamon stick', 'dalchini', 'cardamom', 'elaichi', 'bay leaves', 'tej patta', 'tomatoes', 'turmeric powder', 'haldi', 'red chilli powder', 'garam masala powder', 'salt', 'lemon', 'coriander', 'dhania']::text[], '["To begin making the\u00a0Dhaba Style Dal Fry Recipe | Mixed Dal Tadka,\u00a0prep all the ingredients and keep them ready.Soak all the dal''s together in a large bowl along with enough water for 6 to 8 hours.", "The next step is to make the dal and for this we will cook it in a single pot in the pressure cooker.Heat ghee in the pressure cooker over medium heat; add the onion, ginger and saute until the onions soften.Add the spices - cinnamon, cloves and cardamom and saute for a few seconds.", "Stir in the tomatoes, turmeric powder, red chilli powder and garam masala powder.Saute until the tomatoes turn mushy and soft.", "Add the salt, soaked dals and enough water such that there is at least 2 inches of water above the dals.Cover the pressure cooker and cook the Dhaba Style Dal Fry for 4 to 5 whistles.", "After 4 to 5 whistles, turn the heat to low.", "Simmer the dal for at least 30 minutes and turn off the heat.Allow the pressure to release naturally.", "Once the pressure has released, give the dal a good stir.", "Mash it gently to suit your taste.Check the salt and adjust to suit your taste.", "Finally stir in the lemon juice and coriander leaves and turn off the heat.Transfer the\u00a0Dhaba Style Dal Fry to a serving bowl and serve hot.Serve\u00a0Dhaba Style Dal Fry\u00a0along with\u00a0Paneer Butter Masala,\u00a0Vegetable Yakhni Pulao\u00a0and\u00a0Homemade Naan\u00a0for a delicious meal."]'::jsonb, 160, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Dhaba_Style_Dal_Fry_Mixed_Dal_Tadka_recipe_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/633.Dhaba_Style_Dal_Fry_Mixed_Dal_Tadka_recipe_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Niramish Shobji Chapor Jhol - Bengali Style Vegetable Curry with Lentil Patties', 'niramish-shobji-chapor-jhol-bengali-style-vegetable-curry-with-lentil-patties', 'The Niramish Shobji Chapor Jhol is a delicious Bengali style vegetable curry made from fresh seasonal vegetables with potatoes, brinjal, pumpkin, carrots or any other vegetable in season. It is packed with flavours from the mustard oil in which is is cooked and the special bengali 5 spice powder the Panch Phoran and simmer. The addition of pan fried lentil patties makes this Niramish Shobji Chapor Jhol absolutely wholesome, rich in protein and delicious too.', '["1 tablespoon Mustard oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Bay leaves (tej patta)", "2 Green Chillies , finely chopped", "2 Potato (Aloo) , peeled and diced", "4 Brinjal (Baingan / Eggplant) , cut into wedges", "1 Carrot (Gajjar) , peeled and diced", "1/2 teaspoon Turmeric powder (Haldi)", "1 tablespoon Panch Phoran Masala", "1 teaspoon Salt , or to taste", "1 teaspoon Sugar , or to taste", "1/2 cup Yellow Moong Dal (Split)", "1/4 cup Chana dal (Bengal Gram Dal)", "2 Dry Red Chillies , broken", "1/4 teaspoon Turmeric powder (Haldi)", "1 tablespoon Mustard oil"]'::jsonb, ARRAY['mustard oil', 'mustard seeds', 'rai/ kadugu', 'bay leaves', 'tej patta', 'reen chillies', 'potato', 'aloo', 'brinjal', 'baingan / eggplant', 'carrot', 'gajjar', 'turmeric powder', 'haldi', 'panch phoran masala', 'salt', 'sugar', 'yellow moong dal', 'split', 'chana dal', 'bengal gram dal', 'dry red chillies']::text[], '["To begin making the Niramish Shobji Chapor Jhol, prep all the ingredients and keep readyTo make the chapor, soak the lentils for 2 hours.", "Once soaked drain the excess water and just keep about 2 tablespoons.Add the soaked dals along with red chilli, ginger, turmeric powder and salt to a jar of a mixer grinder.", "Blend to make an almost smooth thick paste.", "Try not adding adding more water as we want this to be a thick batter.Next step is to shallow fry the dal mixture to make Chapor''s also called as lentil patties.You can either make small patties or make one large one in the pan by adding all the batter and then cutting it to add into vegetables to make the Shobji with Jhol.Heat mustard oil in a heavy bottomed skillet.", "When the oil is smoking hot add the lentil paste and flatten it with your fingers to spread it evenly onto the pan.", "These chapor/ lentil patties will not have any definite shape.Cover the pan and allow the lentil patties to cook on the top.", "Once you can notice that the top is cooked, open the pan and flip over to cook on the other side.", "These ''Chapor''/ lentil patties are done, when you notice light brown spots and they are cooked.The next step is to cook the vegetables.", "Heat mustard oil in a pressure cooker, add the mustard seeds and allow it to crackle, stir in the add panch phoran masala or bengali five spice mix, green chilies, bay leaves.As the spices release nice aroma add the all the cut vegetables with little salt and turmeric powder, and about 1/2 cup of water.", "Pressure cook for 3 to 4 whistles and turn off the heat.", "Allow the pressure to release naturally.Once the pressure has released from the pressure cooker, break the chapor or the lentil patties and add into the vegetables.", "Add salt and sugar to taste and adjust the consistency by adding little more water and if you like your dish to be spicy add green more chopped chilies.Give the Niramish Shobji Chapor Jhol a brisk boil for a couple of minutes and turn off the heat.Garnish with coriander leaves and transfer the\u00a0Niramish Shobji Chapor Jhol to a serving bowl and serve hot.Serve Niramish Shobji Chapor Jhol with Steamed Rice and Aloo Parwal Sabzi for weekday lunch or dinner."]'::jsonb, 60, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Sobji_Diye_Chapor_Jhol___Bengali_Moong_Patties_with_Vegetables_Niramish_Sobji_Jhol_Recipe_8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/634.Sobji_Diye_Chapor_Jhol___Bengali_Moong_Patties_with_Vegetables_Niramish_Sobji_Jhol_Recipe_8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chapor Ghonto Recipe - Bengali Mix Vegetable With Lentils Patties', 'chapor-ghonto-recipe-bengali-mix-vegetable-with-lentils-patties', 'Chapor Ghonto, a vegetable mishmash gets an elevation by addition of lentil patties. Ghonto refers to any vegetable mish-mash. Why the name ''chapor''? The lentil patties added in this dish are purposely irregular in shape and pressed with hand while shallow frying.', '["1 tablespoon Mustard oil", "1 tablespoon Mustard seeds (Rai/ Kadugu)", "2 Bay leaves (tej patta)", "2 Green Chillies , finely chopped", "2 Potato (Aloo) , peeled and diced", "1 cup Kaddu (Parangikai/ Pumpkin) , peeled and diced", "4 Small Brinjal (Baingan / Eggplant) , cut into wedges", "1 Carrot (Gajjar) , peeled and diced", "1/2 teaspoon Turmeric powder (Haldi)", "1 tablespoon Panch Phoran Masala", "Salt , to taste", "1 teaspoon Sugar , to taste", "2 tablespoons Fresh coconut , grated as required to garnish (optional)", "1/2 cup Yellow Moong Dal (Split)", "1/4 cup Chana dal (Bengal Gram Dal)", "1 inch Ginger , grated", "2 Dry Red Chillies , broken", "1/4 teaspoon Turmeric powder (Haldi)", "1 tablespoon Mustard oil"]'::jsonb, ARRAY['mustard oil', 'mustard seeds', 'rai/ kadugu', 'bay leaves', 'tej patta', 'reen chillies', 'potato', 'aloo', 'kaddu', 'parangikai/ pumpkin', 'small brinjal', 'baingan / eggplant', 'carrot', 'gajjar', 'turmeric powder', 'haldi', 'panch phoran masala', 'salt', 'sugar', 's fresh coconut', 'yellow moong dal', 'split', 'chana dal', 'bengal gram dal', 'ginger', 'dry red chillies']::text[], '["To begin making the Chapor Ghonto recipe, prep all the ingredients and keep readyTo make the chapo, soak the lentils for 2 hours.", "Once soaked drain the excess water and just keep about 2 tablespoons.Add the soaked dals along with red chilli, ginger, turmeric powder and salt to a jar of a mixer grinder.", "Blend to make an almost smooth thick paste.", "Try not adding adding more water as we want this to be a thick batter.Next step is to shallow fry the dal mixture to make Chapor''s also called as lentil patties.", "You can either make small patties or make one large one in the pan by adding all the batter and then cutting it to add into vegetables to make teh Chapor Ghonto.Heat mustard oil in a heavy bottomed skillet.", "When the oil is smoking hot add the lentil paste and flatten it with your fingers to spread it evenly onto the pan.", "These chapor/ lentil patties will not have\u00a0any definite shape.Cover the pan and allow the lentil patties to cook on the top.", "Once you can notice that the top is cooked, open the pan and flip over to cook on the other side.", "These ''Chapor''/ lentil patties are done, when you notice light brown spots and they are cooked.", "The next step is to cook the vegetables.", "Heat mustard oil in a deep pan or kadhai, when the oil is hot add the eggplant pieces, sprinkle a little salt and saute till brown, keep aside.In the same pan add more oil if needed, when the oil is hot add panch phoran masala or bengali five spice mix, green chilies, bay leaves.", "As the spices release nice aroma add the potato with little salt and turmeric powder, cover and cook.", "After 10 minutes, add other vegetables and the grated ginger cover and cook it till the vegetables are done.Once the vegetables are soft, stir in the roasted brinjal, break the chapor or the lentil patties and add into the vegetables.", "Add salt and sugar to taste.", "If you like your dish to be spicy add green more chopped chilies.", "Give it a stir and turn off the heat.Garnish with grated coconut and transfer the Chapor Ghonto recipe to a serving bowl and serve hot.", "Serve Chapor Ghonto along with\u00a0Steamed Rice\u00a0and\u00a0Dal Chenchki\u00a0for weekday lunch or dinner.", "You can also serve\u00a0Chaler Payesh\u00a0after your meal as a dessert."]'::jsonb, 60, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Affiliate-Articles/chapor-ghonto.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/635.chapor-ghonto.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Parwal Sabzi Recipe - A Classic Bengali Dish', 'aloo-parwal-sabzi-recipe-a-classic-bengali-dish', 'Aloo Parwal Ki Sabzi is a typical dish from Bengal. Parwal also known as Potol in Bengal and Orissa is very popular among the Bengali Cuisine. It is super nutritious vegetable and is rich in minerals and vitamins. The vegetable looks like tiny cucumbers, with tapering ends and it has faint, lighter green lines along its length. The skin is much harder than cucumber and is fat and stout like the thumb.', '["500 grams Pointed gourd (Parval) , peeled and sliced into wedges", "Potatoes (Aloo) , peeled sliced in wedges", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Amchur (Dry Mango Powder)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Salt , or to taste", "2 tablespoons Mustard oil , for cooking"]'::jsonb, ARRAY['s pointed gourd', 'parval', 'potatoes', 'aloo', 'turmeric powder', 'haldi', 'red chilli powder', 'coriander powder', 'dhania', 'amchur', 'dry mango powder', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'salt', 's mustard oil']::text[], '["To begin making the Aloo Parwal Sabzi Recipe, we will cook the vegetables in two stages.To begin with; heat a tablespoon of oil in a heavy bottomed pan; add in the mustard seeds and allow it to crackle.Once the mustard seeds crackle, we will add in the parwal into the pan.", "Sprinkle some salt, stir to combine the salt in and cover the pan.Allow the parwal to cook on low to medium heat until the parwal is cooked.", "In the final stage of the cooking process, add a 1/2 teaspoon of turmeric powder and red chilli powder.", "Give it a stir and keep aside.The next step is to cook the potatoes; heat oil in a pan; add cumin seeds and allow it to crackle.", "Add the potatoes and sprinkle a little\u00a0 salt, stir and cover the pan.", "Cook the aloo/potato until it feels roasted and cooked through.In the final stage of the cooking process, stir in the turmeric powder, red chilli powder, coriander powder, amchur powder and give it a stir for a couple of minutesStir in the cooked parwal into the aloo sabzi and stir fry until all the masala is well coated to form a delicious tasting Aloo Parwal Sabzi.", "Check the salt and adjust to suit your taste.Once done, turn off the heat and transfer the\u00a0Aloo Parwal Sabzi to a serving bowl and serve hot.Serve the\u00a0Aloo Parwal Ki Sabzi along with\u00a0Cholar Dal\u00a0or\u00a0Makhana Moongphali Ki Kadhi\u00a0and a bowl of steamed rice or\u00a0Phulka."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Aloo_Parwal_Sabzi_Recipe_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/636.Aloo_Parwal_Sabzi_Recipe_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Homemade Kashmiri Garam Masala Recipe', 'homemade-kashmiri-garam-masala-recipe', 'Kashmiri Spice Mix or Kashmiri Masala is a special spice powder used in many recipes that originate from Kashmiri Cuisine. This is a variation to garam masala recipe. This recipe yields close to a cup of spice mix. Make this spice powder and store in advance to cook Kashmiri recipes and to add Kashmiri twist to the regular home cooked recipes. Store away in an airtight container.', '["1 tablespoon Cumin seeds (Jeera)", "3 Cardamom (Elaichi) Pods/Seeds", "6 Cloves (Laung)", "2 inch Cinnamon Stick (Dalchini) , broken", "2 tablespoons Coriander (Dhania) Seeds", "2 tablespoons Whole Black Peppercorns", "1 tablespoon Fennel seeds (Saunf)", "2 Bay leaves (tej patta)", "2 Mace (Javitri)", "1/4 teaspoon Nutmeg powder"]'::jsonb, ARRAY['cumin seeds', 'jeera', 'cardamom', 'elaichi', 'laung', 'cinnamon stick', 'dalchini', 's coriander', 'dhania', 's whole black peppercorns', 'fennel seeds', 'saunf', 'bay leaves', 'tej patta', 'mace', 'javitri', 'nutmeg powder']::text[], '["To make Homemade Kashmiri Garam Masala Masala Powder, prep with all the ingredients and keep them ready.Preheat a skillet on medium heat and roast all the ingredients together (except the nutmeg powder) on low to medium heat until you can smell the aromas coming through.Make sure you keep stirring continuously with preferably a wooden spoon while dry roasting.Once the spices have cooled down, dry grind them along with nutmeg powder to make a fine Kashmiri Garam Masala powder.Store Homemade Kashmiri Garam Masala powder in an airtight container and use as required.", "You can also freeze the masala for longer shelf life."]'::jsonb, 10, 'Kashmiri', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/BasicRecipes_Spice_Powders/Kashmiri_spice_mix_Masala_Powder.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/637.Kashmiri_spice_mix_Masala_Powder.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Peerkangai Thogayal Recipe | Ridge Gourd Peel Chutney | Beerakaya Pachadi', 'peerkangai-thogayal-recipe-ridge-gourd-peel-chutney-beerakaya-pachadi', 'Peerkangai Thogayal Recipe also known as Beerakaya Pachadi is a delicacy in almost every South Indian home. The thogayal recipe is made with roasted ingredients like urad dal, red chilies, and curry leaves when ground along with tamarind into a paste along with the peels of ridge gourd it gives a fresh aroma which makes it simply delicious.', '["2 cups Ridge Gourd Skin (Turai/ Peerkangai)", "2 teaspoons White Urad Dal (Split)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "3 Dry Red Chillies", "2 sprig Curry leaves", "30 grams Tamarind", "1/2 teaspoon Salt , to taste", "Ingredients for Seasoning", "1 teaspoon Gingelly oil", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "2 Dry Red Chillies", "1 sprig Curry leaves"]'::jsonb, ARRAY['s ridge gourd skin', 'turai/ peerkangai', 's white urad dal', 'split', 'methi seeds', 'fenugreek seeds', 'dry red chillies', 'curry leaves', 's tamarind', 'salt', 'ingredients for seasoning', 'gingelly oil', 'mustard seeds', 'rai/ kadugu', 'white urad dal']::text[], '["To begin making the Peerkangai Thogayal Recipe/ Beerakaya Pachadi, prep all the ingredients and keep ready.Heat a teaspoon oil in a heavy bottomed pan; add the cut peels of the Ridge Gourd, along with a little salt and saute until soft and tender.", "Turn off heat and allow it to cool.", "The peels will not get completely soft, so its ok as long as they have cooked through.In another small pan; roast the fenugreek seeds, dry red chillies and urad dal until it releases a roasted aroma and slightly browned.Now grind the roasted ingredients, the cooked ridge gourd peels, the tamarind and curry leaves together until it forms a smooth paste.", "Check the salt in the Peerkangai Thogayal Recipe\u00a0and adjust to suit your taste.Heat a little oil in a pan; add mustard seeds, urad dal, dry red chillies and curry leaves.", "Allow it to crackle and the red chillies to roast and the dal to get golden brown.", "Once done turn off the heat and add it to the Peerkangai Thogayal / Beerakaya Pachadi.Transfer the\u00a0Peerkangai Thogayal / Beerakaya Pachadi to a serving bowl and serve immediately or refrigerate for 3 to 4 days and serve as needed.Serve the Peerkangai Thogayal / Beerakaya Pachadi along with a hot bowl of Steamed Rice and Ghee."]'::jsonb, 25, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Chutneys/Ridge_Gourd_Peel_Chutney_Thogayal_Peerkangai_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/638.Ridge_Gourd_Peel_Chutney_Thogayal_Peerkangai_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chamadumpa Vepudu Recipe - Andhra Style Colocasia Stir Fry | Arbi Sabzi', 'chamadumpa-vepudu-recipe-andhra-style-colocasia-stir-fry-arbi-sabzi', 'Andhra Chamadumpa Vepudu Recipe (Colocasia Stir Fry Recipe) is a quick stir fry of colocasia roots in other words called as Arbi or Cheppankizhangu.', '["500 grams Colocasia root (Arbi)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Coriander (Dhania) Powder", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Salt , or to taste", "2 tablespoons Gingelly oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "2 Dry Red Chilli , broken", "1 sprig Curry leaves , torn"]'::jsonb, ARRAY['s colocasia root', 'arbi', 'red chilli powder', 'turmeric powder', 'haldi', 'amchur', 'dry mango powder', 'coriander', 'dhania', 'asafoetida', 'hing', 'salt', 's gingelly oil', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'dry red chilli', 'curry leaves']::text[], '["To begin making the Andhra Chamadumpa Vepudu Recipe,\u00a0place the colocasia roots in the pressure cooker along with 1/2 cup of water.Pressure cook for 4 to 5 whistles and turn off the heat.", "Allow the pressure to release naturally.", "Allow the pressure to release by itself, drain the water and cut them into half.Heat a kadai with oil, add mustard seeds, urad dal and allow it to splutter for 10 seconds.After 10 seconds, add curry leaves, dry red chilies and leave the curry leaves to crackle for 10 seconds.Add the cooked colocasia roots along with all the spice powders including red chilli powder, turmeric powder, salt and amchur powder.Give Chamadumpa Vepudu a toss and stir fry the roots till it is coated well and becomes crisp.", "Check for salt and add if required.Serve the Chamadumpa Vepudu Recipe along with\u00a0Andhra Style Pappu Charu Recipe\u00a0and\u00a0Steamed Rice\u00a0to enjoy your meal with your loved ones."]'::jsonb, 35, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Andhra_Colacassia_Roast_Recipe_Chamadumpa_Vepudu_Recipe_5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/639.Andhra_Colacassia_Roast_Recipe_Chamadumpa_Vepudu_Recipe_5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bendakaya Pulusu Recipe - Andhra Style Tangy Ladies Finger Curry', 'bendakaya-pulusu-recipe-andhra-style-tangy-ladies-finger-curry', 'Bendakaya Pulusu Recipe is an Andhra Style tangy and spicy tamarind based gravy prepared with ladies finger/okra/bhindi . The tanginess from the tamarind, the spice from the sambar powder and sweetness from the jaggery makes for a perfect balance of flavours. Pulusu is similar to Tamil Nadu Kuzhambu which is also prepared with a tamarind and jaggery gravy.', '["250 grams Bhindi (Lady Finger/Okra) , cut into 1 inch pieces", "1/2 cup Pearl onions (Sambar Onions) , quartered", "2 Tomatoes , finely chopped", "30 grams Tamarind , soaked in hot water", "2 sprig Curry leaves , torn", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Sambar Powder", "1 tablespoon Jaggery", "2 teaspoons Gingelly oil", "1 teaspoon Salt , or to taste"]'::jsonb, ARRAY['s bhindi', 'lady finger/okra', 'pearl onions', 'sambar onions', 'tomatoes', 's tamarind', 'curry leaves', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'methi seeds', 'fenugreek seeds', 'turmeric powder', 'haldi', 'red chilli powder', 'sambar powder', 'jaggery', 's gingelly oil', 'salt']::text[], '["To begin making Andhra Style Bendakaya Pulusu, prep all the ingredients and keep ready/soak tamarind in hot water for 20 minutes and extract the pulp and keep aside.", "You can add water two times to extract the water from the pulp.", "To cook the Bendakaya Pulusu, preheat oil in a pressure cooker over medium heat; add mustard seeds, cumin seeds, fenugreek seeds and allow then to crackle.", "Add in quartered onion and curry leaves and saute until the onions turn soft and translucent.", "Next add the tomatoes, give it a stir for a minute.", "Stir in the cut\u00a0Ladies Finger/Okra/Bendakaya\u00a0along with the tamarind water, turmeric powder, jaggery, sambar powder and salt.", "Add 1/4 cup water and pressure cook the Bendakaya Pulusu for 2 whistles and turn off the heat.Allow the pressure to release naturally and open the cooker.", "Give the Bendakaya Pulusu a taste and adjust the salt and seasoning accordingly.", "Transfer the\u00a0Bendakaya Pulusu to a serving bowl and serve hot.Serve Andhra Style Bendakaya Pulusu along with Steamed Rice,\u00a0Andhra Style Palakura Vepudu, Moong Sprouts Salad with Grated Carrots and Cucumber and Curd for a complete Andhra Style meal."]'::jsonb, 30, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Andhra_Bendakaya_Pulusu_Recipe_Okra_Bhindi_Curry_16_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/640.Andhra_Bendakaya_Pulusu_Recipe_Okra_Bhindi_Curry_16_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hesarukalu Bele Kosambari Recipe | Tangy Sprouted Green Moong Dal Salad', 'hesarukalu-bele-kosambari-recipe-tangy-sprouted-green-moong-dal-salad', 'Kosambari is a high protein, diabetic friendly salad variety from Karnataka. It is usually made during special occasions like weddings and festivals.', '["2 cups Green Moong Dal (Whole) , sprouted", "1 Carrot (Gajjar) , grated", "1/4 cup Fresh coconut , grated", "1 Cucumber , finely chopped", "1 Tomato , finely chopped", "2 Green Chillies , finely chopped", "1 Lemon , juice extracted", "6 sprig Coriander (Dhania) Leaves , finely chopped", "1 teaspoon Salt , or to taste", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves , finely chopped", "1 teaspoons Coconut Oil"]'::jsonb, ARRAY['s green moong dal', 'whole', 'carrot', 'gajjar', 'fresh coconut', 'cucumber', 'tomato', 'reen chillies', 'lemon', 'coriander', 'dhania', 'salt', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'curry leaves', 's coconut oil']::text[], '["To begin making Hesarukalu Bele Kosambari\u00a0Recipe, prep all the ingredients and keep ready.You can either get store bought sprouts or make the sprouts at home from this link -\u00a0\u00a0How To Make Sprouts At Home.Now that you have the sprouts ready with you, in a mixing bowl, combine the sprouted green gram, grated carrots, grated coconut, finely chopped cucumbers, tomatoes, lemon, salt, coriander leaves and green chilies.", "Adjust the amount of green chilies as per your palate.", "Mix all the ingredients well.Heat oil in a small pan; add mustard seeds and urad dal and allow the seeds to crackle and dal to turn golden brown and crisp.", "Once done, turn off the heat and stir in the curry leaves.Add the Curry leaves to the above\u00a0Hesarukalu Bele Kosambari (moong sprout salad) and stir well to combine.Check the taste and adjust salt accordingly.", "Transfer the\u00a0Hesarukalu Bele Kosambari to a serving bowl and serve immediately or chilled.Serve Hesarukalu Bele Kosambari Recipe with Steamed Rice and Beetroot Garlic Lemon Rasam for a complete south indian meal.", "You can also have it as a midday snack."]'::jsonb, 15, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Hesarukalu_Bele_Kosambari_Recipe-Sprouted_Green_Moong_With_Tadka_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/641.Hesarukalu_Bele_Kosambari_Recipe-Sprouted_Green_Moong_With_Tadka_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Moongphali Bhindi Sabzi Recipe - Lady''s Finger Peanut Stir Fry', 'moongphali-bhindi-sabzi-recipe-lady-s-finger-peanut-stir-fry', 'Moongphali Bhindi Sabzi Recipe is a quick and easy recipe with the crunch of peanuts and spices. The addition of peanuts, coriander powder, dry mango powder and chillies along with the bhindi works like a charm and creates one delicious dish out of the simple ingredients.', '["500 grams Bhindi (Lady Finger/Okra) , cut into rounds", "2 tablespoons Oil", "1 teaspoon Ajwain (Carom seeds)", "2 sprig Curry leaves , torn", "1/4 cup Roasted Peanuts (Moongphali) , coarsely pounded", "1 teaspoons Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Amchur (Dry Mango Powder)", "Salt , to taste"]'::jsonb, ARRAY['s bhindi', 'lady finger/okra', 's oil', 'ajwain', 'carom seeds', 'curry leaves', 'roasted peanuts', 'moongphali', 's coriander powder', 'dhania', 'turmeric powder', 'haldi', 'red chilli powder', 'amchur', 'dry mango powder', 'salt']::text[], '["To make Moongphali Bhindi Sabzi Recipe, first wash and pat dry bhindi and cut the bhindi into roundsHeat oil in a heavy-bottomed pan over medium heat. add the ajwain and curry leaves and saute for a few seconds.", "Stir in the chopped bhindi and sprinkle a little salt.", "Cover the pan with the lid slightly ajar and cook the bhindi until it is soft and almost cooked.", "Keep stirring in between to ensure the bhindi gets cooked evenly.", "Keeping the lid ajar will prevent excess moisture to get trapped and also prevent the bhindi from getting soggy.", "Once the bhindi is cooked, add the turmeric powder, red chilli powder, coriander powder, amchur powder and roasted crushed peanuts.", "Give it a stir and allow the\u00a0Moongphali Bhindi Sabzi to simmer for another 3 to 4 minutes and turn off the heat.Check the salt and spices and adjust to suit your taste.Transfer the\u00a0Moongphali Bhindi Sabzi\u00a0to a serving bowl and serve hot.Serve Moongphali Bhindi Sabzi along with\u00a0Punjabi Kadhi Pakora\u00a0or\u00a0Kerala Olan\u00a0and serve it along with hot steamed rice or even millet phulka."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Moongphali_Bhindi_recipe_Okra_Ladys_finger_with_peanuts_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/642.Moongphali_Bhindi_recipe_Okra_Ladys_finger_with_peanuts_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Punjabi Bhindi Kadhi Recipe - Roasted Okra In Yogurt Curry', 'punjabi-bhindi-kadhi-recipe-roasted-okra-in-yogurt-curry', 'The Traditional Punjabi Bhindi Kadhi Recipe, is a yogurt based tangy and spicy curry that is a staple dish in North India.', '["Main Kadhi Ingredients", "15 Bhindi (Lady Finger/Okra) , de-stemmed and cut into half", "2 tablespoons Oil , for cooking the bhindi", "1 cup Curd (Dahi / Yogurt)", "2 tablespoons Gram flour (besan)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Red Chilli powder", "Salt , to taste", "Ingredients for seasoning", "1/4 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies", "1 inch Cinnamon Stick (Dalchini)", "1-1/2 tablespoon Ghee"]'::jsonb, ARRAY['salt', 'ghee', 'sunflower oil the bhindi', 'red chilli powder', 'gram flour (besan)', 'curd', 'dry red chillies', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'coriander powder', 'bhindi (lady fingerokra) destemmed', 'turmeric powder']::text[], '["To begin making the Punjabi Bhindi Kadhi Recipe, we will first start by combining all the main ingredients including curd, gram flour, turmeric powder, coriander powder, red chilli powder and salt in a large saucepan.Add 2 cups of water and whisk it all together, until it forms a smooth paste without lumps.", "Place the saucepan on medium heat and bring the Kadhi mixture to a boil.While the Kadhi is boiling, keep whisking it continuously, so it becomes smooth.", "Continue to whisk it until you notice it has begun to thicken and the Kadhi is smooth.Turn the heat to low at this stage and allow the Kadhi to simmer while we get the remaining ingredients ready.", "Next, heat\u00a02 tablespoons of oil in a wok; add in the cut bhindi (okra), sprinkle some salt and stir fry on medium heat until the bhindi is cooked through and has a slightly crispy texture.You might want to add a little more oil if required to get the right texture of the bhindi.", "Once ready, keep it aside.Heat ghee in a saucepan over medium\u00a0heat and add in the cumin seeds, cinnamon stick, and dry red chilies and allow them to crackle.", "Stir until the red chilies are roasted well.", "Turn off the heat.Add the roasted Bhindi into the Kadhi and give it stir.", "Next pour the seasoning (only after the Kadhi has boiled for about 5 to 7 minutes) over the in the boiling Kadhi mixture.", "Mix everything well and your kadhi is ready to be served.", "Serve\u00a0Punjabi Bhindi Kadhi Recipe\u00a0along with\u00a0Bharwa Besan Mirch,\u00a0Phulka\u00a0and\u00a0Jeera Rice\u00a0for a weekday meal."]'::jsonb, 45, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Bhindi_Kadhi_Recipe_Punjabi_Cuisine-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/643.Bhindi_Kadhi_Recipe_Punjabi_Cuisine-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Babru Recipe (Himachali Black Gram Stuffed Bread)', 'babru-recipe-himachali-black-gram-stuffed-bread', 'Babru is a famous black gram stuffed kachoris or puris. The black gram or the whole urad dal is soaked overnight and is ground to a course mix, before stuffing it into the kachoris and deep fried in oil. It makes for a delicious weekend breakfast with any Indian sabzi.', '["2 cups Whole Wheat Flour", "1 cup Black Urad Dal (Whole)", "Water , to knead the dough", "Oil , for frying (as required)", "Salt , to taste"]'::jsonb, ARRAY['s whole wheat flour', 'black urad dal', 'whole', 'water', 'oil', 'salt']::text[], '["To begin making\u00a0Babru Recipe (Himachali Black Gram Stuffed Bread), wash the whole black gram and soak in enough water overnight.", "Drain the water in the morning and grind it to a coarse mix using a mixer grinder and keep aside.Now, make a stiff dough of the whole wheat flour and salt, adding little water at a time as your would do for making the puris.Divide the dough into 20 equal lemon sized balls, before proceeding further.Now, take each wheat flour dough, fill it with a spoon full of the black gram mixture, seal it from all the sides and roll it gently into a small puri''s and keep aside.Like wise, stuff and roll out the rest of the babru''s.Heat oil in a pan, once it is hot enough, fry each prepared babru until it turns light golden brown on each side and drain it into a kitch towel.", "Fry the rest of the babru''s.Serve the\u00a0Babru Recipe (Himachali Black Gram Stuffed Bread), along with\u00a0Chana Madra\u00a0and\u00a0Boondi Raita\u00a0for a delicious weekend breakfast."]'::jsonb, 30, 'Himachal', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Babru_Recipe_Himachali_Black_Gram_Stuffed_Bread.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/644.Babru_Recipe_Himachali_Black_Gram_Stuffed_Bread.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Arabian Chicken Mandi Recipe -Yemeni Style Rice & Chicken', 'arabian-chicken-mandi-recipe-yemeni-style-rice-chicken', 'Arabian Chicken Mandi is a traditional Yemeni dish and it’s very popular among all the Arab countries.', '["500 grams Chicken , with bones", "1 Onion , finely chopped", "1 Tomato", "3 Green Chillies", "1 tablespoon Ginger Garlic Paste", "3 Bay leaves (tej patta)", "1 teaspoon Ghee", "2 Cardamom (Elaichi) Pods/Seeds", "2 Cloves (Laung)", "2 inch Cinnamon Stick (Dalchini)", "1 teaspoon Whole Black Peppercorns", "2 tablespoons Extra Virgin Olive Oil", "2 tablespoons Butter (Salted) , softened", "Salt , to taste", "2 cups Basmati rice", "4 cups Water", "1 tablespoon Cardamom (Elaichi) Pods/Seeds", "1 tablespoon Cloves (Laung)", "1/2 tablespoon Whole Black Peppercorns", "1/2 teaspoon Nutmeg powder", "1/2 tablespoon Dry ginger powder", "2 Bay leaves (tej patta)"]'::jsonb, ARRAY['tomato', 'salt', 'basmati rice', 'bay leaves (tej patta)', 'ghee', 'cardamom (elaichi) podsseeds', 'nutmeg powder', 'black peppercorns', 'virgin olive oil', 'ginger garlic paste', 'water', 'dry ginger powder', 'onion', 'cinnamon stick (dalchini)', 'cloves (laung)', 'chicken bs', 'green chillies', 'butter']::text[], '["To begin making the Arabian Chicken Mandi recipe, firstly we will prepare the Mandi spice powder."]'::jsonb, 120, 'Middle Eastern', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shaharban/Arabian_Chicken_Mandhi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/645.Arabian_Chicken_Mandhi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rajasthani Laal Maas Recipe-Mutton In Red Spicy Gravy', 'rajasthani-laal-maas-recipe-mutton-in-red-spicy-gravy', 'Laal Maas is a very popular non-veg recipe in Rajasthan. It is a fiery meat curry which is made with the combination of Kashmiri red chillies and other popular spices of Rajasthan. It is made in many ways but the authentic one is made with the use of dry red chillies.', '["10 Kashmiri dry red chillies , soaked in water for atleast 20 minutes", "500 grams Mutton , cut into 1 inch pieces", "1/2 cup Curd (Dahi / Yogurt)", "1 teaspoon Cumin seeds (Jeera)", "2 teaspoons Cumin powder (Jeera)", "2 teaspoons Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "2 tablespoons Ginger Garlic Paste", "Ghee , as required", "2 Brown cardamom (Badi Elaichi)", "3 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "3 Cloves (Laung)", "1 Bay leaf (tej patta)", "3 Onions , finely chopped", "1/2 teaspoon Garam masala powder", "Salt , to taste", "Coriander (Dhania) Leaves , Few sprigs, chopped for garnish", "3 Charcoal , pieces"]'::jsonb, ARRAY['charcoal', 'salt', 'cumin powder (jeera)', 'coriander (dhania) leaves', 'kashmiri dry red chillies atleast', 'ghee', 'cardamom (elaichi) podsseeds', 'bay leaf (tej patta)', 'ginger garlic paste', 'curd', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'mutton', 'brown cardamom (badi elaichi)', 'onion', 'coriander powder', 'turmeric powder', 'cloves (laung)', 'garam masala powder']::text[], '["To begin making the Rajasthani Laal Maas recipe, add water in a heavy bottomed pan.", "Add the soaked kashmiri red chillies and all the dry spices including cumin seeds, black cardamoms, green cardamoms, cinnamon stick, cloves, bay leaf into the water.Let it boil and switch off the flame once the dry red chillies becomes soft.Let it cool a bit, retain the water and then grind the spices into a fine paste in a mixer grinder.In a large mixing bowl, add mutton, yogurt, cumin powder, coriander powder, turmeric powder, one tablespoon ginger garlic paste and the dry red chilli paste which we prepared in the beginning.Mix everything well and set aside to marinate in the refrigerator for an hour.Heat ghee in a heavy bottomed pan.", "Add onions and saut\u00e9 till they turn light brown in colour.Add the remaining ginger garlic paste and saut\u00e9 for a minute.Add the marinated mutton to the onions and saut\u00e9 on high heat for two to three minutes.Add the required salt and water (which we retained from boiling the dry red chillies) into the pan.Cover the pan with a lid and let it cook for 20 to 25 minutes.", "You can add more water if you want watery consistency.Once the mutton is cooked, light the piece of charcoal, place it in a small metal bowl and place the bowl in the centre of the pan.Add two to three cloves to the coal, pour some ghee and quickly cover the pan with a lid and set aside for two to three minutes.Remove the charcoal bowl,put the curry back on heat, add garam masala and give a quick stir before removing from heat.Transfer to a serving bowl and garnish it with coriander leaves.Serve Rajasthani Laal Maas with hot\u00a0Phulkas, steamed rice or Baati.", "It is usually made during special occasions and festivals in Rajasthan."]'::jsonb, 50, 'Rajasthani', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Rajasthani_Lal_Maas_Recipe__1-2N_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/646.Rajasthani_Lal_Maas_Recipe__1-2N_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Badam Elaichi Kulfi Recipe', 'badam-elaichi-kulfi-recipe', 'Badam Elaichi Kulfi is the best choice to beat the summer heat. Reducing the milk to make a thick rabdi and combining along with almond milk, cardamon powder and saffron milk gives a delicious falvour and taste.Chopped pistachios added at the end adds a nice nuttiness and crunchiness to the kulfi.', '["2 liter Milk , full fat+ 1 cup", "1 cup Whole Almonds (Badam) , soaked", "1 cup Sugar", "1/4 Saffron strands", "1 tablespoon Cardamom Powder (Elaichi)", "1/2 cup Pistachios , chopped"]'::jsonb, ARRAY['liter milk', 'whole almonds', 'badam', 'sugar', 'saffron strands', 'cardamom powder', 'elaichi', 'pistachios']::text[], '["To begin making the Badam Elaichi Kulfi, we will first make an almond paste.", "Remove the skin of the soaked almonds and add them to a blender along with 1 cup of milk and blend to a smooth paste.", "Keep aside.Next in a heavy bottomed pan, add milk and bring it to a boil.", "Reduce the heat once the milk boils and then simmer the milk on medium heat till the milk in the pan reduces to half its original quantity.", "Stir occasionally and scrape the sides to avoid the milk from burning and sticking to the pan.", "This process of reducing the milk will take a good 20-25 minutes.Once the milk has reduced, add the saffron strands and the cardamom powder.", "Add the ground Almond milk and the sugar and mix till all the sugar has dissolved.", "Once done turn off the flame and allow the badam elaichi kulfi mixture to cool down completely.Once it is cooled spoon the Badam Elaichi Kulfi mixture into kulfi molds along with some chopped pistachios.", "Close the lid and freeze for 8 hours until the kulfi is set.Serve\u00a0Badam Elaichi Kulfi along with a party meal of\u00a0Homemade Butter Naan,\u00a0Paneer Makhani\u00a0and\u00a0Tomato Onion Cucumber Raita Recipe."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Badam_Elaichi_Kulfi_Recipe_With_Condensed_Milk-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/647.Badam_Elaichi_Kulfi_Recipe_With_Condensed_Milk-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sorakkai Paruppu Kuzhambu Recipe - Tamil Nadu Style Lauki Curry', 'sorakkai-paruppu-kuzhambu-recipe-tamil-nadu-style-lauki-curry', 'Sorakkai Paruppu Kuzhambu Recipe is a side dish recipe to prepare that can be done in about 20 minutes and hence is a great recipe for a busy weeknight dinner. Made with nutritious summer vegetable-bottle gourd, the curry is full of nutrients and is a coolant to the body as well.', '["1 cup Bottle gourd (lauki) , cut into medium sized pieces", "1 cup Yellow Moong Dal (Split) , washed and soaked", "1 teaspoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves , torn", "2 Dry Red Chillies , broken", "10 Pearl onions (Sambar Onions) , quartered", "1 Tomato , finely chopped", "1/2 cup Tamarind Water", "1/4 teaspoon Turmeric powder (Haldi)", "1 tablespoon Sambar Powder", "Salt", "6 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['tomato', 'salt', 'mustard seeds', 'yellow moong dal (split) masoor dal', 'ghee', 'dry red chillies', 'onion', 'bottle gourd (lauki)', 'cumin seeds (jeera)', 'turmeric powder', 'sambar powder', 'sunflower oil']::text[], '["To begin making Sorakkai Paruppu Kuzhambu Recipe, into the pressure cooker combine the bottle gourd, yellow moong dal, tomatoes, salt, turmeric powder and half a cup of water.Pressure cook this for two whistles and turn off the heat.", "Allow the cooker to release the pressure naturally.", "Keep aside.Heat ghee over medium heat in a heavy bottom pan; add the mustard seeds and cumin seeds, and allow them to crackle.", "Next add the curry leaves, dry red chillies and onions and saute for about a minute or until the onions turn transparent and golden brown.Once the onions have turned golden, add the tamarind water, sambar powder and allow it to come to a brisk boil for 3 to 4 minutes till the raw taste from the tamarind goes away.Finally add in the bottle-gourd dal mixture and bring the Sorakkai Paruppu Kuzhambu to a brisk boil.", "Once done, turn check the salt and adjust to taste accordingly.", "Stir in chopped coriander leaves to the Sorakkai Paruppu Kuzhambu and serve hot.Serve hot\u00a0Sorakkai Paruppu Kuzhambu Recipe\u00a0along with\u00a0Steamed Rice,\u00a0Carrot and Beans Poriyal Recipe,\u00a0Phulka\u00a0and\u00a0Kathirikai Pitlai Recipe\u00a0to make it a complete meal."]'::jsonb, 25, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swathynandhini/Sorakkai_Paruppu_Kuzhambu_Recipe_-_Bottle_Gorud_Dal_South_Indian_Style_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/648.Sorakkai_Paruppu_Kuzhambu_Recipe_-_Bottle_Gorud_Dal_South_Indian_Style_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Soya Methi Sabzi Recipe | Made from Soya Chunks', 'soya-methi-sabzi-recipe-made-from-soya-chunks', 'Soya Methi Sabzi Recipe is a simple sabzi where methi and soya chunks are cooked with the everyday masalas. It is easy to make and thus you can pack it in your lunch box too.', '["1 cup Methi Leaves (Fenugreek Leaves) , washed and finely chopped", "1 cup Soya Chunks , soaked in one cup of hot water", "1 tablespoon Mustard oil", "1/2 teaspoon Cumin seeds (Jeera)", "2 Onions , thinly sliced", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "1 Bay leaf (tej patta)", "1 inch Cinnamon Stick (Dalchini)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Coriander (Dhania) Powder", "1/4 teaspoon Red Chilli powder", "1 teaspoon Amchur (Dry Mango Powder)", "1 tablespoon Jaggery", "Salt"]'::jsonb, ARRAY['methi leaves', 'fenugreek leaves', 'soya chunks', 'mustard oil', 'cumin seeds', 'jeera', 'onions', 'ginger', 's garlic', 'bay leaf', 'tej patta', 'cinnamon stick', 'dalchini', 'turmeric powder', 'haldi', 'garam masala powder', 'coriander', 'dhania', 'red chilli powder', 'amchur', 'dry mango powder', 'jaggery', 'salt']::text[], '["To begin making the Soya Methi Sabzi Recipe , first\u00a0pressure cook the soya chunks for 2 whistles in the water that it is soaked in.", "Allow the pressure to release naturally.", "Drain off the excess water and keep the soya chunks aside.", "Heat oil in a pan on medium heat; add the cinnamon stick and cumin seeds and allow it to crackle.", "Next add in the finely chopped ginger, garlic and onions.", "Saut\u00e9 for about a minute until the onions turn transparent and soft.Once the onions, ginger and garlic have cooked through, add the methi leaves and saut\u00e9 for two to three minutes or until the Methi leaves have completely wilted down.", "To this add the salt, turmeric powder, Garam masala powder, coriander powder, red chilli powder and amchur powder and jaggery along with the cooked soya chunks.Give it a good stir until the masala has well coated into the Soya Methi Sabzi.", "Cover the the pan and simmer for 2 to 4 minutes until the masalas are well absorbed.Give the\u00a0Soya Methi Sabzi a taste and adjust salt and seasoning accordingly.", "Once done, turn off the heat, transfer the Soya Methi Sabzi to a serving bowl and serve hot.Serve this Soya Methi Sabzi\u00a0along with\u00a0Dhaba Style Dal Fry\u00a0and\u00a0Jowar Atta Roti\u00a0and\u00a0Mooli Raita\u00a0for a healthy and diabetic friendly meal."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/kritikakallimani-gmail.com/Soya_Methi_Sabzi_Recipe_Made_from_Soya_Chunks_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/649.Soya_Methi_Sabzi_Recipe_Made_from_Soya_Chunks_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Varutharacha Mutta Curry Recipe', 'kerala-style-varutharacha-mutta-curry-recipe', 'Varutharacha Mutta Curry Recipe is a popular Kerala egg curry recipe.  The eggs are hard boiled and is added to a spicy coconut based gravy. This flavourful and easy to prepare egg curry can be served at home for a weekend brunch.', '["1/2 teaspoon Fennel seeds (Saunf)", "1 tablespoon Coriander (Dhania) Seeds", "1 tablespoon Whole Black Pepper Corns", "5 Byadagi Dried Chillies", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "Fresh coconut , grated", "4 Whole Eggs , boiled", "2 tablespoons Coconut Oil", "1/4 cup Pearl onions (Sambar Onions) , cut into quarters", "2 sprig Curry leaves , roughly torn", "1 inch Ginger , finely chopped", "5 cloves Garlic , finely chopped", "2 Green Chillies , finely chopped", "2 Tomatoes , finely chopped", "1 Tomatoes , finely chopped"]'::jsonb, ARRAY['fennel seeds', 'saunf', 'coriander', 'dhania', 'whole black pepper corns', 'byadagi dried chillies', 'laung', 'cinnamon stick', 'dalchini', 'cardamom', 'elaichi', 'fresh coconut', 'whole eggs', 's coconut oil', 'pearl onions', 'sambar onions', 'curry leaves', 'ginger', 's garlic', 'reen chillies', 'tomatoes']::text[], '["To begin making the Varutharacha Mutta Curry Recipe, we will first boil the eggs in water for about 10 to 12 minutes.", "Allow it to cool.", "Once cooled peel them and set them aside.Here''s How To Boil Eggs At Home - Boiled Eggs RecipeTo make the roasted coconut spice mix, heat a pan over medium heat; add the fennel seeds, coriander seeds, whole black peppercorns, dry red chillies, clove, cinnamon stick and cardamom.", "Allow the spices to sizzle for about a minute.", "Add the grated coconut and roast along with the spices until the coconut starts releasing an aroma.", "Stir the mixture every few minutes, to ensure it roasts evenly.", "Once the coconut turns into a lovely brown colour, turn off the heat and allow the roasted spices to cool down.", "Once cooled transfer the coconut spice mix into a mixer jar and grind into a fine paste adding 1/4 cup of water.To make the gravy, heat a kadai with coconut oil on medium heat.", "Once the oil is hot add the onion, ginger, garlic and curry leaves and saute until the onions are translucent and golden brown in colour.Once the onions are roasted, add the chopped tomatoes, sprinkle some salt and water, cover and cook until tomatoes turn mushy.", "Once the onion-tomato mixture has come together, add in the roasted and ground spice paste to the pan and allow it to cook for about a minute.", "To this add the boiled eggs, one cup of water and give the Varutharacha Mutta Curry a brisk boil.", "Check the salt and spices and adjust the seasoning according to taste.", "Garnish the Varutharacha Mutta Curry with Coriander leaves and serve hot.Serve\u00a0Varutharacha Mutta Curry Recipe along with\u00a0No Yeast Kerala Style Appam Recipe,\u00a0 for breakfast.", "Or serve\u00a0Varutharacha Mutta Curry Recipe along with\u00a0Kerala parotta\u00a0and\u00a0Spiced Ghee Rice Recipe | Neychoru\u00a0for simple dinner."]'::jsonb, 40, 'Kerala', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/kitchennandoos/Varutharacha_Mutta_Curry_Recipe_-_Kerala_Style_Egg_Curry_in_Gravy_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/650.Varutharacha_Mutta_Curry_Recipe_-_Kerala_Style_Egg_Curry_in_Gravy_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bathua Raita Recipe', 'bathua-raita-recipe', 'Bathua Raita Recipe is a raita made out of a green leafy vegetable called ''Bathua''. Although this a winter green, it is now pretty much available all through the year.', '["1-1/2 cups Bathua leaves , washed", "1-1/2 cups Curd (Dahi / Yogurt)", "2 Green Chillies , finely chopped", "1/2 Ginger , finely chopped", "1/2 teaspoon Black Salt (Kala Namak)", "1/2 teaspoon Cumin powder (Jeera) , roasted", "1/4 teaspoon Black pepper powder", "1/2 teaspoon Oil"]'::jsonb, ARRAY['s bathua leaves', 's curd', 'dahi / yogurt', 'reen chillies', 'inger', 'black salt', 'kala namak', 'cumin powder', 'jeera', 'black pepper powder', 'oil']::text[], '["To begin making the Bathua Raita Recipe, first wash and chop the bathua leaves and place them in a bowl.", "Heat oil in a pan over medium heat and saut\u00e9 the bathua leaves until soft and tender and allow it to cool.", "You could either blend the bathua to a coarse paste or add the cooked bathua leaves directly to the bowl of yogurt.In this recipe I have blended the bathua leaves in a blender once it cooled down.Into a mixing bowl, add the yogurt, chopped green chillies, ginger, black salt, cumin powder and black pepper powder.", "Whisk well to combine until mixed evenly.", "Finally add the chopped bathua or pureed bathua and give it a stir.", "Check salt and adjust the taste of\u00a0Bathua Raita accordinglyServe the chilled Bathua Raita Recipe along with\u00a0Masala Lachha Paratha ,\u00a0Aloo Gobi Sabzi,\u00a0Peas Pulao\u00a0and\u00a0Gajar Ka Halwa Recipe and make a delicious weekend meal."]'::jsonb, 15, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Bathua_Raita_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/651.Bathua_Raita_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vegan Kofta Curry Recipe', 'vegan-kofta-curry-recipe', 'A popular Indian main course dish, this Vegan Kofta Curry is made with absolutely no cream, yogurt or ghee.', '["1 Carrot (Gajjar) , peeled and grated", "100 grams Bottle gourd (lauki) , peeled and grated", "2 Potatoes (Aloo) , boiled and mashed", "1/4 cup Green peas (Matar) , steamed and mashed", "1/2 Green capsicum , finely chopped", "3 tablespoons Gram flour (besan)", "1 Green Chilli , finely chopped", "2 teaspoons Cumin powder (Jeera) , roasted", "Salt , to taste", "1 teaspoon Amchur (Dry Mango Powder)", "1/4 cup Cashew nuts , soaked in hot water", "1/2 teaspoon Cumin seeds (Jeera)", "1 tablespoon Oil", "1 inch Ginger , finely chopped", "6 cloves Garlic , finely chopped", "2 Onions , finely chopped", "1 inch Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "1 tablespoon Jaggery , crushed", "2 Cloves (Laung)", "6 Tomatoes , made into puree", "1/4 teaspoon Turmeric powder (Haldi)", "2 teaspoons Red Chilli powder", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'cumin powder (jeera)', 'asafoetida (hing)', 'coriander (dhania) leaves', 'carrot', 'onion', 'cumin seeds (jeera)', 'multigrain flour besan', 'green chilli paste', 'sunflower oil', 'salt', 'tofu', 'green zucchini', 'beetroot', 'garam masala powder', 'red chilli powder', 'sugar', 'rice flour', 'amchur (dry mango powder)', 'ginger garlic paste', 'cashew nuts water', 'bottle gourd (lauki)', 'coriander powder', 'cabbage (patta gobi muttaikose)']::text[], '["To begin making the Vegan Kofta Curry, we will start by making the Koftas.", "For the koftas, prep all the ingredients and keep them ready.Into a large mixing bowl, add the grated carrots, grated bottle gourd, mashed potatoes, steamed peas and finely chopped capsicum, green chilli, besan, salt, jeera powder and amchur powder and salt to taste.", "Combine all the ingredients well and ensure you get a mashed texture.", "A little bit of coarseness is ok.Heat a paniyaram pan on medium heat, and add a few drops of oil in each cavity.", "Make lemon sized balls of the vegan koftas, and pan fry them in the paniyaram pan until well cooked and golden on all sides.", "Set aside.", "For the kofta gravy, make a smooth paste of the cashew nuts along with 1/4 cup of water and keep aside.Heat oil in a pan on medium heat; add cumin seeds, garlic, ginger, onions, cinnamon stick, green cardamom and cloves.", "Saute this mixture for about 4-6 minutes, or until the onions turn into a light brown colour.", "Next add in the tomato puree, turmeric powder, red chilli powder, jaggery and salt.", "Cover and cook until the tomatoes for about 5 minutes.", "Stir in the cashew paste and mix well to combine.", "Now adjust the consistency of the Vegan Kofta Curry by adding a little water and adjust the seasoning by adding salt or spices according to suit your taste.Finally stir in the kasuri methi and turn off the heat.When you are ready to serve the Vegan Kofta Curry, add the kofta balls into the gravy and give the curry a brisk boil for a couple of minutesGarnish the\u00a0Vegan Kofta Curry with fresh chopped coriander leaves and serve hot.Serve Vegan Kofta Curry along with\u00a0Phulka Recipe,\u00a0Dhaba Style Spicy Ghee Rice Recipe,\u00a0Satvik Carrot Sprouts Salad Recipe\u00a0and\u00a0Boondi Raita Recipe.", "End the meal with a delicious\u00a0Sabudana Kheer Recipe\u00a0for dessert."]'::jsonb, 75, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Vegan_Kofta_Curruy_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/652.Vegan_Kofta_Curruy_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharashtrian Kakdi Thalipeeth Recipe - Spiced Cucumber Flat Bread', 'maharashtrian-kakdi-thalipeeth-recipe-spiced-cucumber-flat-bread', 'The Maharashtrian Kakdi Thalipeeth Recipe is a wholesome dish that is made from cucumbers, whole wheat flour and spices. The addition of coriander and green chilies make this Thalipeeth a perfect addition for breakfast or even for dinner when you serve it along with a sabzi.', '["1/2 cup Gram flour (besan)", "1/2 cup Whole Wheat Flour", "1/4 cup Rice flour", "1 Cucumber , peeled and grated", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "2 Green Chillies , finely chopped", "1/2 cup Coriander (Dhania) Leaves , chopped", "5 cloves Garlic , finely chopped", "Salt , to taste", "Ghee , for smearing on thalipeeth"]'::jsonb, ARRAY['salt', 'wheat flour', 'cumin powder (jeera)', 'ghee on thalipeeth', 'coriander (dhania) leaves', 'red chilli powder', 'cloves garlic', 'gram flour (besan)', 'cucumber', 'coriander powder', 'rice flour', 'turmeric powder', 'green chillies']::text[], '["To begin making the Maharashtrian Kakdi Thalipeeth Recipe, in a large mixing bowl add all the 3 flours together and mix them.", "Add all the remaining ingredients like the grated cucumber, turmeric powder, cumin powder, coriander powder, red chili powder, green chillies, coriander leaves, garlic and salt to taste.Mix everything well and add a little water at a time to make a smooth and firm dough of the Kakdi\u00a0Thalipeeth.", "The cucumber will release water when it gets combined with salt, so take care to add little water at a time.", "The dough will be slightly sticky to handle.", "Allow the dough to rest for 5 minutes.", "Divide the dough into 4 portions.", "Preheat the\u00a0skillet on medium heat.", "Keep water in a separate bowl to wet fingers and to wet a muslin cloth.Spread a wet muslin cloth on a smooth counter top.", "Take a portion of the Kakdi Thalipeeth mixture and pat it on the wet cloth to about 4 inches in diameter.", "Try not to make it too thin as it can break while flipping it on the skillet.Carefully lift the cloth along with the patted mixture and flip the Thalipeeth over on the skillet.", "Drizzle a teaspoon of oil or ghee around the Thalipeeth\u00a0and cook on medium heat.After about 3 minutes, you will be able to flip the\u00a0Kakdi Thalipeeth over to the other side.", "Allow each side to cook on medium heat for about 3-4 minutes, until the\u00a0Thalipeeth\u00a0are slightly crisp and browned.", "Remove from heat and place on a serving platter.Continue the same procedure with the other portions of the\u00a0Kakdi Thalipeeth dough.Serve the Maharashtrian Kakdi Thalipeeth along with\u00a0Homemade Yogurt\u00a0or\u00a0lahsun chutney\u00a0for breakfast."]'::jsonb, 60, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Cucumber_Thalipeeth.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/653.Cucumber_Thalipeeth.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mangalorean Manoli Bheeja Upkari Recipe - Ivy Gourd & Cashew Sabzi', 'mangalorean-manoli-bheeja-upkari-recipe-ivy-gourd-cashew-sabzi', 'Mangalorean Manoli Bheeja Upkari Recipe is the Konkani style Ivy Gourd & Cashew Sabzi. A customary side dish, in any function or festival in Konkani cuisine. Fresh, tender cashews are sauteed along with tender ivy gourd to make this tasty and simple stir fry.', '["300 grams Tindora (Dondakaya/ Kovakkai) , (Manoli)", "1/2 cup Cashew nuts , (tender ones), soaked in warm water and salt for 15 minutes", "3 tablespoons Fresh coconut , grated", "1 teaspoon Sugar", "Salt , to taste", "To temper", "2 teaspoons Coconut Oil", "1 teaspoon White Urad Dal (Split)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "3 Dry Red Chillies , broken (adjust to taste)", "1/4 teaspoon Turmeric powder (Haldi)", "Curry leaves , a few"]'::jsonb, ARRAY['salt', 'coconut', 'mustard seeds', 'curry leaves', 'sugar', 'white urad dal (split)', 'dry red chillies', 'cashew nuts (tender s)', 'turmeric powder', 'tindora (dondakaya kovakkai) (manoli)', 'coconut oil']::text[], '["To begin making Mangalorean Manoli Bheeja Upkari Recipe (Ivy Gourd & Cashew Sabzi), soak the cashews in warm water and a little salt for about 10 minutes.", "Wash the Ivy gourd and cut off the ends.", "Slit them lengthwise in quarters.Heat oil in a heavy bottomed pan.", "Once the oil is hot, add mustard seeds and let them splutter.As the mustard splutters, add split black gram and fry till them till it turns golden brown.Break in the dry red chillies into half into the kadai and add curry leaves along.After a few seconds of frying them, add the cashew nuts, slit manoli or ivy gourd and turmeric.", "Toss the veggies and cashews to mix with the tempering.", "Keep sauteing for a couple of minutes on medium heat.Add salt , sugar \u00a0and about 1/2 cup of water and mix everything well.", "Now cover and cook in low heat for 15 to 20 minutes or until the ivy gourds are tender.", "Make sure not to overcook the Tindora though.", "Both the Tindora and cashew nuts should be soft but slightly crunchy.Add grated coconut and allow all the water to dry up with stirring.", "Check for salt and adjust spices if needed, allow to sit for a minute and switch off.Serve\u00a0Mangalorean Manoli Bheeja Upkari Recipe\u00a0(Ivy Gourd & Cashew Sabzi) with\u00a0Steamed Rice,\u00a0Bendekayi Koddel/Bolu Huli Recipe\u00a0and\u00a0Aralu Sandige Recipe\u00a0for lunch."]'::jsonb, 30, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/Mangalorean_Manoli_Bheeja_Upkari_Sukka__Ivy_Gourd__Cashew_Dry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/654.Mangalorean_Manoli_Bheeja_Upkari_Sukka__Ivy_Gourd__Cashew_Dry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Cauliflower And Red Bell Pepper Stir Fry Recipe', 'cauliflower-and-red-bell-pepper-stir-fry-recipe', 'Cauliflower and Red Bell Pepper Stir Fry is a quick and easy to make recipe, filled with nutrients and pretty colourful at the same time. Red bell peppers have the highest amount of Vitamin C, which boosts up the immune system and gives you a youthful skin. This quick stir fry with minimal oil and spices makes for a wonderful dish to accompany with Phulkas or parathas for kids lunch box. Serve the Cauliflower and Red Bell Pepper Stir Fry Recipe with  Dhaniya Pudina Chutney for a quick weeknight dinner or kids school lunch box.', '["1 cup Cauliflower (gobi) , cut into small florets", "1 Red Bell pepper (Capsicum) , cut into strips", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves) , crushed", "2 teaspoon Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'red bell pepper (capsicum)', 'cauliflower (gobi)', 'red chilli powder', 'coriander powder', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making Cauliflower and Red Bell Pepper Stir Fry Recipe, blanch the cauliflower florets in hot water along with little bit of salt and turmeric powder, this helps to deworm.", "Keep the blanched florets aside.Heat oil in a Wide pan on a medium heat, add all the spice powders along with salt and stir for 30 seconds.Now, add the blanched cauliflower florets and mix well.", "Let it cook for 5-6 minutes.Once the cauliflower is firmly cooked, add the red bell pepper strips and give it a good stir.", "Stir fry this mix for another 5 minutes and switch off the flame.Add the crushed kasuri methi and mix well.Serve the Cauliflower and Red Bell Pepper Stir Fry Recipe along with \u00a0Dhaniya Pudina Chutney\u00a0for a quick weeknight dinner or kids school lunch box."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Cauliflower_And_Red_Bell_Pepper_Stir_Fry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/655.Cauliflower_And_Red_Bell_Pepper_Stir_Fry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Manathakkali Thayir Pachadi Recipe', 'manathakkali-thayir-pachadi-recipe', 'Manathakkali or Black night shade has a myriad of health benefits. In general, only vathal kulambu is made of this berry, however this recipe is slight unusual but very tasty. In Manathakkali Thayir Pachadi Recipe, Manathakkali is combined with Mor milagai and mixed with thick yogurt & salt. Manathakkali is a seasonal berry which mostly is available in January season in India.', '["1 cup Manathakkali Kai Vathal", "Salt , to taste", "1 Mor Milagai (Dried Green Chillies)", "Coriander (Dhania) Leaves , small bunch, finely chopped", "1 teaspoon Oil", "1/3 teaspoon Mustard seeds (Rai/ Kadugu)", "Asafoetida (hing) , a pinch", "Water , as needed", "1 cup Curd (Dahi / Yogurt)"]'::jsonb, ARRAY['salt', 'coriander (dhania)', 'mustard seeds', 'asafoetida (hing)', 'water', 'curd', 'mor milagai (dried green chillies)', 'manathakkali kai vathal', 'sunflower oil']::text[], '["To prepare Manathakkali Thayir Pachadi Recipe, heat a pan and add oil.Once the oil is hot, add mustard and hing.Tear the mor milagai into smaller pieces and add them to the oil.Add the manathakkali kai vathal and fry them.Add salt and mix well.The\u00a0manathakkali berry would start to burst out after few minutes.", "Hence close with a lid and keep stirring at regular intervals.Once cooked, add coriander leaves and switch off and allow it to cool.Add Yogurt and dilute with water to make it a raita consistency.Mix well.", "Let this marinate for 1 hour (Minimum) in fridge or at room temperature.Serve Manathakkali Thayir Pachadi Recipe chilled, or at room temperature, along with Maharashtrian Multigrain Thalipeeth or\u00a0Chettinad Vegetable Pulao Recipe."]'::jsonb, 15, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/neerusrikanth/Manathakkali_Thayir_Pachadi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/656.Manathakkali_Thayir_Pachadi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tamil Nadu Style Poo Kosu Poriyal - Pepper Garlic Cauliflower Poriyal Recipe', 'tamil-nadu-style-poo-kosu-poriyal-pepper-garlic-cauliflower-poriyal-recipe', 'Poondu Poo Kosu Recipe is a delicious and nutritious side dish made from cauliflower tossed along with garlic and onions and spiked up with chilli and pepper.', '["1 Cauliflower (gobi) , chopped into small florets", "1 Onion , sliced", "5 cloves Garlic , crushed or finely chopped", "1 teaspoon Black pepper powder", "1/2 teaspoon Red Chilli powder", "Coriander (Dhania) Leaves , required for garnish", "Salt , to taste", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1 teaspoon Black Urad Dal (Split)", "2 Dry Red Chilli , torn into 2 pieces", "2 tablespoons Oil", "2 tablespoons Oil"]'::jsonb, ARRAY['cauliflower', 'gobi', 'onion', 's garlic', 'black pepper powder', 'red chilli powder', 'coriander', 'dhania', 'salt', 'mustard seeds', 'rai/ kadugu', 'curry leaves', 'black urad dal', 'split', 'dry red chilli', 's oil']::text[], '["To begin making the Poondu Poo Kosu/ Pepper Garlic Cauliflower recipe, prepare all the ingredients and keep ready.Steam the cauliflower either using a steamer for 5 to 6 minutes on high heat or in a pressure cooker without the weight on.The cauliflower should retain crispiness and should not be over cooked.", "Preheat oil in. a\u00a0kadai/wok on medium heat; add the mustard seeds, urad dal and dry red chillies.", "Allow the seeds to crackle and dal to turn golden brown and crisp.Once the dal turns brown and crisp, stir in the curry leaves, onion and garlic and saute until the onion softens and turns lightly golden.", "Once done, stir in the steamed cauliflower florets, salt, black pepper powder and red chilli powder.", "Saute for 3 to 4 minutes until the cauliflower gets well coated.", "Once done, check the salt and adjust according to taste.Turn off the heat and transfer the\u00a0Poondu Poo Kosu to a serving bowl and serve hot.Serve\u00a0Poondu Poo Kosu\u00a0\u00a0along with\u00a0Beetroot Sambar Recipe, Rice and\u00a0Phulkas\u00a0for a perfect weekday meal."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Pepper_Cauliflower.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/657.Pepper_Cauliflower.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Oriya Style Ambila Recipe - Sweet & Spicy Mixed Vegetable Sabzi', 'oriya-style-ambila-recipe-sweet-spicy-mixed-vegetable-sabzi', 'Sweet & Spicy Ambila Recipe is a recipe from Orissa cuisine, which can also be termed as ''Oriya Mixed Veg Sabzi'' that is packed with delicious medley of vegetables cooked in a sweet and sour yogurt and tomato based gravy and seasoned with panch phoran.', '["1 teaspoon Mustard oil", "3 cloves Garlic , finely chopped", "2 Green Chillies , finely chopped", "2 Tomatoes , finely chopped", "1 tablespoon Gram flour (besan)", "1/4 cup Curd (Dahi / Yogurt)", "1 teaspoon Panch Phoran Masala", "15 grams Tamarind , soaked in water", "1/4 cup Kaddu (Parangikai/ Pumpkin) , cut into cubes", "1/4 cup Mooli/ Mullangi (Radish) , cut into cubes", "1/4 cup Colocasia root (Arbi) , cut into cubes", "1/4 cup Brinjal (Baingan / Eggplant) , cut into cubes", "1 Carrot (Gajjar) , cut into cubes", "2 Bhindi (Lady Finger/Okra) , cut into small pieces", "1 Drumstick , cut into 1 inch pieces", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "Salt , as per your taste", "Oil , as required"]'::jsonb, ARRAY['mustard oil', 's garlic', 'reen chillies', 'tomatoes', 'gram flour', 'besan', 'curd', 'dahi / yogurt', 'panch phoran masala', 's tamarind', 'kaddu', 'parangikai/ pumpkin', 'mooli/ mullangi', 'radish', 'colocasia root', 'arbi', 'brinjal', 'baingan / eggplant', 'carrot', 'gajjar', 'bhindi', 'lady finger/okra', 'drumstick', 'turmeric powder', 'haldi', 'red chilli powder', 'salt', 'oil']::text[], '["To begin making Ambila Recipe, prepare all the ingredients and keep them ready.Soak the tamarind in hot water for 15 minutes and extract the tamarind water from the pulp.", "You will get approximately 1/2 cup of tamarind water.", "Keep aside.In a bowl, add curd/dahi, besan and 1/4 cup water and stir to combine well until there are no lumps.", "Keep aside.", "Heat mustard oil in a pressure cooker over medium heat.", "Add the garlic and green chillies along with the tomatoes.", "Saute the tomatoes until it becomes soft and mushy.", "Add the panch phoran masala, turmeric powder and red chilli powder.Saute for a few seconds.", "Add the tamarind water, stir in the salt and the cut vegetables.", "Cover the pressure cooker and pressure cook the Oriya Ambila for 2 to 3 whistles and turn off the heat.", "Once done allow the pressure to release naturally.Once the pressure releases, gently give the Oriya Ambila a stir.", "Stir in the yogurt mixture and give the Oriya Ambila a brisk boil for 3 to 4 minutes until the besan gets well combined to form a delicious Ambila - mixed vegetables gravy.", "Check the salt and adjust to suit your taste.", "Once done, turn off the heat and transfer the\u00a0Oriya Ambila to a serving bowl and serve hot.Serve Oriya Style\u00a0Ambila along with Steamed Rice and a dollop of Ghee for a perfect weekday lunch."]'::jsonb, 40, 'Oriya', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Oriya_Style_Ambila_Recipe-Sweet__Spicy_Mixed_Vegetable_Sabzi_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/658.Oriya_Style_Ambila_Recipe-Sweet__Spicy_Mixed_Vegetable_Sabzi_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mini Bajra Uttapam Recipe', 'mini-bajra-uttapam-recipe', 'Mini Bajra Uttapam Recipe is essentially a millet based Uttapam batter that is made by combining bajra or pearl millets with urad dal and rice.', '["1/2 cup Bajra (seeds)", "1/2 cup Idli Rice", "1 cup White Urad Dal (Whole)", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 tablespoon Salt", "1 Onion , finely chopped", "1 Green Bell Pepper (Capsicum) , finely chopped", "1 Green Chilli , finely chopped", "Salt , to taste", "6 sprig Mint Leaves (Pudina) , finely chopped", "1 teaspoon Cumin powder (Jeera)", "Ghee , to cook the uttapam"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'green chilli', 'idli rice', 'mint leaves (pudina)', 'ghee the uttapam', 'onion', 'methi seeds (fenugreek seeds)', 'green bell pepper (capsicum)', 'bajra (seeds)', 'white urad dal']::text[], '["To begin making the Mini Bajra Uttapam Recipe, we will first make the batter.\u00a0*To make the Bajra Uttapam Batter:Firstly, wash the urad dal and methi seeds together and soak it together in a bowl, immersed in water.", "Next combine the idli rice and bajra seeds, wash them well and soak them in a bowl, immersed in water.", "Keep them all soaked for about 6 hours.", "Next, add the soaked and drained urad dal and methi seeds, into a mixer jar along with some water and grind to make a smooth batter.", "Transfer the urad dal batter to a large bowl and set aside.", "Add the soaked and drained rice and bajra mixture into the mixer jar along with some water and grind it to make a smooth batter.", "Combine this idli-bajra batter, along with the urad dal batter and mix well.", "To this bajra uttapam batter add salt, mix well to combine, and allow it to ferment overnight.", "Once it has fermented overnight it, you can make Idli the first day and even dosa and uttapams with this batter.The next step is to make the topping for the Bajra uttapam:In a mixing bowl, combine the onions, capsicum, green chilli, mint leaves salt and cumin powder and mix well.", "Preheat a tawa on medium-high heat; once hot, gently spread 1 ladleful of the bajra uttapam batter, in a circular motion, ensuring the uthappam is thick like a pancake.Spread a tablespoon of the onion-capsicum topping over the mini Bajra Uttapam and lightly press, embedding it onto the uttapam.", "Drizzle a little ghee around the\u00a0Uttapam and after a couple of minutes, flip the bajra uttapam, to cook on the other side.", "Once you''ve achieved a lovely golden brown colour on both sides, remove the Bajra Uttapam from the tawa and serve.", "Similarly make the Bajra Uttapam using the rest of the batter.", "You can store this batter in an airtight container in the refrigerator for about 4 days.Serve\u00a0Mini Bajra Uttapam Recipe along with\u00a0Raw Mango Coconut Chutney Recipe,\u00a0Idli Dosa Milagai Podi Recipe\u00a0and finish with a cup of\u00a0Kumbakonam Filter Coffee Recipe\u00a0for a lip smacking breakfast."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/Bajra_Onion_Uttapam_Recipe_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/659.Bajra_Onion_Uttapam_Recipe_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kadalai Puli Kuzhambu With Mangalore Cucumber & Drumstick Recipe', 'kadalai-puli-kuzhambu-with-mangalore-cucumber-drumstick-recipe', 'The Kadalai Puli Kuzhambu is delicious tangy curry that is packed with a perfect blend of spices and simmered in a coconut gravy. When combined along with Mangalore cucumber and drumstick it adds a variety to the curry making it rich and delicious.', '["2 cups Kala Chana (Brown Chickpeas) , soaked for 8 hours", "1 Mangalorean cucumber , cut into dices", "1 Drumstick , cut into 2 inch pieces", "1 cup Tamarind Water", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 cup Homemade tomato puree", "1 cup Pearl onions (Sambar Onions) , quartered", "Salt , to taste", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1 tablespoon Sesame (Gingelly) Oil", "To Be Ground", "1/2 cup Fresh coconut , grated", "1 tablespoon Coriander (Dhania) Seeds", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon White Urad Dal (Split)", "4 Dry Red Chillies"]'::jsonb, ARRAY['s kala chana', 'brown chickpeas', 'mangalorean cucumber', 'drumstick', 'tamarind water', 'turmeric powder', 'haldi', 'homemade tomato puree', 'pearl onions', 'sambar onions', 'salt', 'mustard seeds', 'rai/ kadugu', 'curry leaves', 'sesame', 'gingelly', 'to be ground', 'fresh coconut', 'coriander', 'dhania', 'methi seeds', 'fenugreek seeds', 'white urad dal', 'split', 'dry red chillies']::text[], '["To begin making the\u00a0Kadalai Puli Kuzhambu Recipe first prep all the ingredients and keep them ready.Ensure the kadalai (kala chana) is soaked well, as we will be cooking the kuzhambu in the pressure cooker.We will begin by roasting the ingredients for the masala.", "In a small skillet, roast the coriander seeds, methi seeds, red chillies until lightly browned.", "Once roasted, blend it along with the coconut into a smooth paste by adding a little water.Into a pressure cooker, heat a tablespoon of sesame oil.", "Add the mustard seeds, curry leaves and allow it to crackle.", "Stir in the onions and saute until the onions become tender.Once the onions become tender, add the tomato puree, the soaked\u00a0kadala (kala chana), the mangalore cucumber, drumstick, ground coconut masala, turmeric powder, salt and tamarind water.Cover the pressure cooker, place the weight on and pressure cook the puli kuzhambu for 8 to 10 whistles or until the kadalai is cooked through completely.", "It takes about 20 minutes of pressure cooking.Once done, turn off the heat and allow the pressure to release naturally.Open the cooker, check the seasonings and adjust according to taste.", "Transfer to a bowl and serve warm.Serve the\u00a0Kadalai Puli Kuzhambu\u00a0along with a hot bowl of\u00a0steamed rice,\u00a0Spicy Potato Roast (Urulaikizhangu Poriyal)\u00a0and a bowl of yogurt for lunch or dinner."]'::jsonb, 165, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/0-Archana/Prestige_Clip_On_Aluminium_Pressure_Cooker_Desi_Kala_Chana_Drumstick_Mangalore_Cucumber_Kuzhambu_Curry_Recipe-6.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/660.Prestige_Clip_On_Aluminium_Pressure_Cooker_Desi_Kala_Chana_Drumstick_Mangalore_Cucumber_Kuzhambu_Curry_Recipe-6.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer Butter Masala Recipe', 'paneer-butter-masala-recipe', 'Paneer Butter Masala is a classic all time favorite dish of the North Indian Cuisine. In this recipe the Paneer, the Indian Cottage cheese is simmer in creamy tomato based gravy. Paneer Butter Masala is one of the most popular vegetarian dish in the menu of restaurants in the Northern province.', '["200 gram Paneer (Homemade Cottage Cheese) , cut into cubes", "3 Tomatoes , pureed", "1 teaspoon Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Garam masala powder", "1/4 cup Fresh cream", "2 tablespoons Butter (Salted)", "Salt , to taste", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "Ingredients to be ground into paste", "1 Onion", "1 inch Ginger , peeled", "6 cloves Garlic", "2 tablespoon Cashew nuts"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'ginger', 'cashew nuts', 'red chilli powder', 'cloves garlic', 'gram paneer', 'onion', 'kasuri methi (dried fenugreek leaves)', 'butter', 'garam masala powder']::text[], '["To begin making the Paneer Butter Masala, in a mixer grind the ingredients mentioned under ''to be ground into paste'' like the onion, ginger, garlic and cashew nuts in to a smooth consistency using little water.", "Transfer to a bowl and set aside till required.", "Heat the butter in a \u00a0pan over medium heat.", "Add the onion paste and saute over medium heat till it is light brown in color and the oil starts separating from the masala.", "Add the red chili powder and tomato puree, saute once again few more minutes over medium heat.", "As the masala gets roasted it will change color to bright red.Once the masala gets well roasted, add the cumin powder, garam masala along with 1 cup of water.", "Stir to combine and let the butter masala gravy simmer for 10 to 15 minutes over medium heat or till it thickens.", "Once the butter masala thickens add the cream, salt and paneer to it.", "Stir to combine and simmer for next 5 - 10 minutes and allow the paneer to absorb the flavor of the gravy.", "If the Paneer Butter Masala still seems little bit runny let it simmer for few more minutes.", "Turn off the heat.", "Sprinkle crushed kasuri methi over the Paneer Butter Masala and stir to combine.", "Serve Paneer Butter Masala hot with Naan, Kulchas or Tawa Paratha for the Punjabi style dinner."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Paneer_Butter_Masala_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/661.Paneer_Butter_Masala_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chilli Cheese Paratha Recipe', 'chilli-cheese-paratha-recipe', 'The Chilli Cheese Paratha Recipe is something that I make when I am short of vegetables at home.', '["200 grams Britannia Cheese Block , grated", "6 Green Chillies , finely chopped", "2 Onions , finely chopped", "1/2 cup Mint Leaves (Pudina)", "2 teaspoon Cumin powder (Jeera)", "2 cups Whole Wheat Flour", "2 teaspoon Kalonji (Onion Nigella Seeds)", "Salt , to taste", "Ghee , to smear while cooking"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'wheat flour', 'kalonji (onion nigella seeds)', 'mint leaves (pudina)', 'ghee', 'onion', 'britannia cheese block', 'green chillies']::text[], '["To begin making Chilli Cheese Paratha Recipe, into a mixing bowl add the grated cheese, green chillies, onions, mint leaves, cumin powder and mix well to combine.", "Keep aside.To make the dough, into a mixing bowl add the wheat flour, kalonji seeds, salt to taste and add little water at a time and knead to make a smooth dough.Divide the dough into large lemon size portions and keep aside.", "Take a portion of the dough in flour and roll into a 3 inch diameter circle.", "Place a large tablespoon of the stuffing in the center of the circle.Bring the edges together and seal the dough.", "Dust the stuffed ball in flour and roll into a flat paratha.", "To cook the\u00a0Chilli Cheese Paratha, place the rolled out cheese paratha on a preheated pan.Warm the paratha for a few seconds on both sides.", "Drizzle half a teaspoon of ghee on one side and then flip and spread ghee again on the other side.Press down the paratha and cook till crisp and brown spots appear on both sides of the\u00a0Chilli Cheese Paratha.Once done transfer the\u00a0Chilli Cheese Paratha onto a serving plate and serve hot.", "Serve Chilli Cheese Paratha Recipe with\u00a0Aam Ka Achaar\u00a0\u00a0or\u00a0Garlic Chutney\u00a0and\u00a0a bowl of homemade yogurt\u00a0for a special weekend breakfast."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Chilli_Cheese_Paratha_recipe_Britannia_Chessy_Kitchen_Video_Recipe_9_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/662.Chilli_Cheese_Paratha_recipe_Britannia_Chessy_Kitchen_Video_Recipe_9_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chickpea Coconut Milk Curry Recipe', 'chickpea-coconut-milk-curry-recipe', 'Chickpea Coconut Milk Curry Recipe is simple and delicious. Cooked Kabuli Chana is simmered and cooked along with tomatoes, spices and coconut milk making this curry absolutely flavourful.', '["1 cup Kabuli Chana (White Chickpeas) , soaked for 8 hours", "1 Onion , finely chopped", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "1/2 cup Homemade tomato puree", "1/4 cup Coconut milk", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "1 teaspoon Chaat Masala Powder", "1 tablespoon Ghee", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'ginger', 'coriander powder', 'ghee', 'chaat masala powder', 'red chilli powder', 'cloves garlic', 'kabuli chana (white chickpeas)', 'onion', 'coconut milk', 'turmeric powder', 'garam masala powder']::text[], '["To begin making Chickpea Coconut Milk Curry Recipe, first soak 1 cup of chickpeas overnight in required water.Next day, transfer the chole along with 3 cups of water into a pressure cooker with some salt, close the pressure cooker.", "Pressure cook for 6-8 whistles and turn off the flame.", "Allow the pressure to release naturally before you open the pressure cooker.Now to make Chickpea Coconut Milk Curry; heat ghee in a heavy bottom pan.", "Add the ginger, garlic and onions and saute till onions become tender.", "This will take about three minutes.", "Next add the tomato puree and bring it to a brisk boil.", "Add the coconut milk and all the dry spice powders including turmeric powder, red chilli powder, cumin powder, coriander powder, garam masala, chaat masala, salt to taste and stir.", "Add the cooked Kabuli chana to the tomato coconut milk gravy and combine well.", "Cover and simmer Chickpea Coconut Milk Curry for 4 to 5 minutes and turn off the heat.", "Check the salt and spices and adjust according to your taste.Transfer the Chickpea Coconut Milk Curry into a serving bowl and serve hot.Serve\u00a0Chickpea Coconut Milk Curry Recipe\u00a0along with\u00a0Steamed Rice\u00a0and\u00a0Mint And Pomegranate Raita\u00a0for a comforting lunch."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Chickpea_Curry_Recipe_in_Tomato_Coconut_Milk_Gravy_24_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/663.Chickpea_Curry_Recipe_in_Tomato_Coconut_Milk_Gravy_24_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Avarekalu Akki Rotti Recipe', 'karnataka-style-avarekalu-akki-rotti-recipe', 'Karnataka Style Avarekaalu Rotti Recipe is a regional recipe from the region Bengaluru, where they celebrated “Avarekaalu Mela” during the month of January. The mela consists of series of stalls selling out dishes that are made from these field beans or avarekalu beans.', '["2 cups Rice flour", "1 cup Avarekalu / Lilva Beans", "1 Onion , finely chopped", "3 tablespoon Fresh coconut , shredded", "3 Green Chillies , chopped fine", "1/4 cup Curd (Dahi / Yogurt)", "1/2 teaspoon Cumin powder (Jeera)", "1 sprig Coriander (Dhania) Leaves , chopped", "1 pinch Asafoetida (hing)", "Salt , to taste", "Water , to knead dough"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'coconut', 'asafoetida (hing)', 'curd', 'coriander (dhania) leaves', 'water knead dough', 'onion', 'avarekalu lilva beans', 'rice flour', 'green chillies']::text[], '["We begin making the Karnataka Style Avarekaalu Rotti Recipe by adding all the ingredients in a bowl.", "Add about half cup of Luke warm water and knead it into a soft dough.", "It will be little sticky dough.Divide the dough into small equal balls.", "Heat a nonstick tawa, and grease it with oil and keep it ready.You can either do it on the tawa directly or take a plastic paper and add some oil and start pressing it on the paper.", "Flatten it evenly into a round shape.Then carefully take out the flattened rotti and add it on the tawa.", "Drizzle some oil and cook on either side till it is golden brown.", "Repeat the process for other dough.Serve the Avarekaalu Rotti Recipe along with\u00a0Tomato Chutney\u00a0or\u00a0Coconut Chutney\u00a0to relish your Breakfast."]'::jsonb, 45, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Karnataka_Style_Avarekalu_Rotti_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/664.Karnataka_Style_Avarekalu_Rotti_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rajasthani Sweet & Spicy Ker Sangri Sabzi Recipe', 'rajasthani-sweet-spicy-ker-sangri-sabzi-recipe', 'The Ker Sangri Recipe is a traditional Rajasthani dish that is made from with a combination of dried beans and berries that are grown locally in Rajasthan. It is often made into a spicy dry vegetable, but, I have added a little bit of sweetness to the spice and the taste was delectable. If you plan to make it , do first try it without the jaggery and then add jaggery to find the difference. The addition if raisins to the sabzi adds to the richness of Ker Sangri. At home I served it along with a Kadhi, Phulkas and Steamed Rice and not to forget the ghee that I had along with.', '["3/4 cup Sangri", "2 tablespoons Ker", "2 Dry Red Chillies , broken into pieces", "1/2 teaspoon Ajwain (Carom seeds)", "1/4 teaspoon Asafoetida (hing)", "1/2 teaspoon Turmeric powder (Haldi)", "1-1/2 teaspoons Red Chilli powder", "1 teaspoon Amchur (Dry Mango Powder)", "2 teaspoons Coriander Powder (Dhania)", "1 tablespoon Jaggery , optional", "1/4 cup Sultana Raisins", "4 sprig Coriander (Dhania) Leaves", "Oil , for cooking"]'::jsonb, ARRAY['amchur (dry mango powder)', 'asafoetida (hing)', 'ajwain (carom seeds)', 'jaggery', 'red chilli powder', 'raisins', 'coriander (dhania) leaves', 'dry red chillies', 'sangri', 'coriander powder', 'turmeric powder', 'ker', 'sunflower oil']::text[], '["To begin making the Ker Sangri Sabzi Recipe, soak the ker and sangri immersed in lot of water for at least 8 hours or overnight.", "After 8 hours, drain the water and rinse the ker sangri in water a couple of more times, to remove residual dust and dirt.In the next step, we will cook the soaked ker sangri in the pressure cooker.", "Place the soaked Ker Sangri in the pressure cooker, add 1 cup of water and cook the ker sangri until you hear 3 to 4 whistles.After 3 to 4 whistles, turn off the heat and allow the pressure to release naturally.", "The next step is to combine it with spices and make the Ker Sangri SabziHeat a tablespoon of oil in a heavy bottomed pan over medium heat.", "Add the ajwain, the red chillies and allow it to roast a little.", "Add the cooked raisins, the turmeric powder, asafoetida powder, coriander, amchur powder and finally the\u00a0Ker Sangri and give all the ingredients a good stir.Stir fry until all the ingredients are combined and allow it to cook for another 5 minutes.", "Once done, turn off the heat and the Ker Sangri Sabzi is ready to be served.Serve the Ker Sangri Sabzi along with\u00a0Kadhi,\u00a0Phulkas\u00a0and\u00a0Steamed Rice\u00a0and not to forget the ghee along with."]'::jsonb, 55, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Rajasthani_Vegetarian_Ker_Sangri_Sabzi_Recipe_Archanas_Kitchen-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/665.Rajasthani_Vegetarian_Ker_Sangri_Sabzi_Recipe_Archanas_Kitchen-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Sorakaya Palya Recipe - Karnataka Style Bottle Gourd Sabzi', 'karnataka-style-sorakaya-palya-recipe-karnataka-style-bottle-gourd-sabzi', 'Sorakaya Palya is a classic karnataka dish made from bottle gourd which is packed with simple from the very versatile sambar powder. Did you know bottle gourd is very low in saturated fats and cholesterol. In addition, it contains all the essential nutrients like Vitamin C, Vitamin B, Vitamin K, Vitamin A, Vitamin E, Iron, Folate, Magnesium, and Potassium which are required for healthy growth and functioning of our body.', '["1 Bottle gourd (lauki) , peeled and chopped", "2 Tomatoes , finely chopped", "1/2 teaspoon Cumin seeds (Jeera)", "2 tablespoons Sambar Powder", "1 sprig Curry leaves", "Salt , to taste", "1 teaspoon Gingelly oil , for cooking", "6 sprig Coriander (Dhania) Leaves , finely chopped", "Oil"]'::jsonb, ARRAY['bottle gourd', 'lauki', 'tomatoes', 'cumin seeds', 'jeera', 's sambar powder', 'curry leaves', 'salt', 'gingelly oil', 'coriander', 'dhania', 'oil']::text[], '["We begin making the\u00a0Karnataka Style Sorakaya\u00a0Palya Recipe\u00a0, prepare all the ingredients and keep ready.Heat oil in the pressure cooker over medium heat; add the cumin seeds and allow it to crackle.Stir in the curry leaves, chopped tomatoes and sambar powder.", "Saute the tomatoes until they become soft and mushyOnce mushy, add the diced bottle gourd, salt to taste and 2 tablespoons of water.", "Cover the pressure cooker and cook for 2 to 3 whistles and turn off the heat.Allow the pressure to release naturally.", "Once the pressure releases, open the cooker, give the Sorakaya\u00a0Palya a stir and check taste and adjust salt according to taste.Finally stir in the chopped coriander leaves and transfer the\u00a0Sorakaya\u00a0Palya to a serving bowl.Serve\u00a0Karnataka Style Sorakaya\u00a0Palya Recipe\u00a0along with\u00a0Mixed Vegetable Sambar\u00a0and\u00a0Steamed Rice\u00a0for wholesome lunch or dinner."]'::jsonb, 25, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Sorakkai_Poriyal_Recipe_Bottle_gourd_Palya_South_indian_sabzi_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/666.Sorakkai_Poriyal_Recipe_Bottle_gourd_Palya_South_indian_sabzi_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Palak Paneer Recipe | Cottage Cheese In Spinach Gravy', 'palak-paneer-recipe-cottage-cheese-in-spinach-gravy', 'Palak Paneer Recipe (Cottage Cheese In Spinach Gravy) is a preparation of spinach that is steamed, pureed and simmered along with subtle spices and cottage cheese (paneer) .', '["200 grams Paneer (Homemade Cottage Cheese) , cut into cubes", "500 grams Spinach Leaves (Palak) , washed and chopped", "1 tablespoon Ghee", "2 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "1 Tomato , chopped", "2 Green Chillies , slit", "1 teaspoon Cumin powder (Jeera)", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "Salt , to taste", "1/2 teaspoon Cumin seeds (Jeera)", "1 Bay leaf (tej patta)", "1 inch Cinnamon Stick (Dalchini)", "2 tablespoons Fresh cream", "1 tablespoon Butter (Salted)"]'::jsonb, ARRAY['s paneer', 'homemade cottage cheese', 's spinach leaves', 'palak', 'ghee', 's garlic', 'ginger', 'tomato', 'reen chillies', 'cumin powder', 'jeera', 'turmeric powder', 'haldi', 'garam masala powder', 'salt', 'cumin seeds', 'bay leaf', 'tej patta', 'cinnamon stick', 'dalchini', 's fresh cream', 'butter', 'salted']::text[], '["To begin making the Palak Paneer Recipe, first pick the palak leaves and wash them thrice.", "Chop the washed leaves and keep them aside.Heat ghee Into the pressure cooker over medium heat; add the ginger, garlic, tomatoes, green chillies, cumin powder, turmeric powder, garam masala powder.", "Saute for a few seconds until the tomatoes turn slightly soft.Add the chopped spinach, salt to taste - give it a stir and add one tablespoon of water.", "Cover the pressure cooker and cook the palak for just one whistle.", "After one whistle, turn off the heat and release the pressure immediately by using a fork and lifting the weight or by placing the cooker under cold running water.We release the pressure immediately, so that we retain the fresh green colour of palak.", "Open the cooker and allow the palak to cool completelyOnce cooled, pulse the palak in the blender to make a smooth pure.", "You can also choose to mash the spinach with a masher to give it a different texture as well.", "Melt the butter in a frying pan on medium heat; add cumin seeds, cinnamon stick and bay leaf.", "Saute the ingredients for a few seconds.", "Next stir in the palak, cream and the diced paneer.", "Check the salt and adjust accordingly to taste.When you are ready to serve, give the palak paneer a brisk boil for 3 to 4 minutes and turn off the heat.", "Transfer the Palak Paneer\u00a0 to a serving dish and serve hot.Serve the Palak Paneer Recipe along with hot\u00a0Phulkas,\u00a0Jeera pulao\u00a0and\u00a0Dal Makhani\u00a0for a delicious lunch or dinner."]'::jsonb, 60, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Palak_Paneer_Recipe_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/667.Palak_Paneer_Recipe_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Puran Poli Recipe | Gujarati & Maharastrian | Sweet Spiced Stuffed Paratha With Jaggery', 'puran-poli-recipe-gujarati-maharastrian-sweet-spiced-stuffed-paratha-with-jaggery', 'Puran Poli is also called as Vedhmi in Gujarat; Puran Poli is one of the favorites with my family. Come every special occasion or a festival Puran Poli features in the menu along another family favorite Undhiyu. Though puran poli is sweet dish; many Gujarati families have them along with the vegetables as an alternative to other flat breads.', '["Ingredients for the dough", "2 cups Whole Wheat Flour", "1/4 teaspoon Salt", "2 tablespoons Oil", "Ghee , for cooking/ serving", "Ingredients for the filling", "1 cup Arhar dal (Split Toor Dal)", "3/4 cup Jaggery", "10 Saffron strands", "1 teaspoon Cardamom Powder (Elaichi)", "1/2 teaspoon Nutmeg powder", "2 tablespoons Gram flour (besan) , or more if required"]'::jsonb, ARRAY['salt', 'wheat flour', 'arhar dal (split toor dal)', 'nutmeg powder', 'ghee', 'saffron strands', 'jaggery', 'gram flour (besan)', 'cardamom powder (elaichi)', 'sunflower oil']::text[], '["To begin making the Gujarati Puran Poli Recipe, we will first make the dough.", "Add whole wheat flour into a large bowl; add salt and combine it with little water at a time and knead until the dough gathers together to form a firm dough yet soft dough.", "Add the 2 tablespoons of oil to coat the dough and knead for a couple of more minutes until smooth and firm.", "Cover and let the dough sit in a cool place until we get the puran filling ready.", "Divide the dough into 6 portions.Soak the dal for 15 to 20 minutes in water.Add the soaked dal with 1-1/4 cups of water (includes the soaked water) into the pressure cooker and pressure cook for 4 to 5 whistles and turn off the heat.", "Allow the pressure to release naturally.", "Once the pressure releases, give the dal a quick mash.The next step is the make the puran filling.", "Into a heavy bottomed pan, add the cooked dal, and jaggery.Keep stirring until the jaggery dissolves completely.Stir in the saffron, cardamom and nutmeg to the jaggery mixture until well combined to make the puran poli filling.", "Add the besan at this point and mix it into the dal mixture and ensure it blends well without any lumps.Continue stirring the puran poli mixture until the dal mixture begins to thicken and leaves the sides of the pan.At this point turn off the heat and allow the puran poli mixture to cool completely.", "Divide the dough and puran mixture into 6 portions.Keeping a little flour for dusting handy on a plate; roll out the puran poli dough into 3 inch diameter circles.Place a portion of the puran poli mixture into the center of the circle.Bring edges of the circle towards the center and fold over to cover the entire filling; making sure the edges are all sealed well by pinching them together if there is any opening.Flatten the stuffed dough; dust over a little flour and roll gently into a 4 to 6 inch diameter circle taking care not to put too much pressure as the puran can come out of the dough.Preheat a skillet on medium high; place the rolled puran poli onto the skillet to cook until golden brown on both sides.", "At this point you can cook it along with ghee to make the puran poli crisp and delicious.", "Or you can make a dry puran poli and serve it along with ghee.Repeat the above process for all the remaining dough and puran portions.Serve the Gujarati Puran Poli hot with ghee smeared on the top as it is or along with Undhiyu and Gujarati Kadhi to make a delicious meal."]'::jsonb, 80, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Gujarati_Maharastrian_Puran_Poli_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/668.Gujarati_Maharastrian_Puran_Poli_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Cholar Dal Recipe', 'bengali-cholar-dal-recipe', 'Bengali Style Cholar Dal is a delicious lentil dish cooked with Bengal gram or chana dal. This dish of dal is flavored with coconut, ghee and an assortment of whole spices. Bengali Style Cholar Dal tastes mildly spicy and packed with nutrition. Once the Bengal Gram is cooked in the pressure cooker it only takes a few minutes to prepare the whole dish.', '["1 cup Chana dal (Bengal Gram Dal) , soaked for an hour", "1/2 cup Dry coconut (kopra) , cut into 1 inch pieces", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Ingredients for the seasoning", "2 teaspoons Mustard oil", "1/2 teaspoon Cumin seeds (Jeera)", "2 Green Chillies , slit into halves lengthwise", "1 inch Ginger , peeled and grated", "3 Dry Red Chillies", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta)"]'::jsonb, ARRAY['chana dal', 'bengal gram dal', 'dry coconut', 'kopra', 'turmeric powder', 'haldi', 'salt', 'ingredients for the seasoning', 's mustard oil', 'cumin seeds', 'jeera', 'reen chillies', 'ginger', 'dry red chillies', 'laung', 'cinnamon stick', 'dalchini', 'bay leaf', 'tej patta']::text[], '["To begin making the Bengali Cholar dal, first prep all the ingredients and keep them ready.", "Soak the chana dal for about an hour in water.", "Add the soaked dal with 2-1/2 Cups of water , turmeric powder, salt to taste in a pressure cooker for 3 to 4 whistles.After 3 to 4 whistles, turn the heat to low and simmer for 5 minutes and turn off the heat.", "Allow the pressure to release naturally.", "In a teaspoon mustard oil over medium heat in a saucepan; add the dry coconut pieces and fry until they turn golden brown.", "Once done transfer the fried coconut pieces to a bow and keep aside.In the same pan heat a teaspoon of mustard oil; add cumin seeds,\u00a0 dry red chilies, cloves, bay leaf, cinnamon stick, green chilies and ginger.Saute for a few seconds until the seeds crackle and the green chilli gets a lightly roasted texture.", "Once done, stir in the cooked Bengali Cholar dal and the roasted coconut slices.Stir well to combine and check the salt and adjust to suit your taste.", "Give the Bengali Cholar dal a brisk boil for a couple of minutes and turn off the heat.Transfer the Bengali Cholar dal to a serving bowl and serve hot.Serve the Bengali Cholar Dal with\u00a0Begun Bhaja\u00a0and\u00a0steamed rice\u00a0for a wholesome lunch or dinner."]'::jsonb, 40, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Bengali_Cholar_Dal_Recipe_5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/669.Bengali_Cholar_Dal_Recipe_5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Valor Muthia Nu Shaak Recipe - Flat Beans Stir Fry With Dumplings', 'valor-muthia-nu-shaak-recipe-flat-beans-stir-fry-with-dumplings', 'The Valor Muthia nu Shaak Recipe is a recipe made from flat beans and brinjal that is cooked in tomatoes and spices and tossed with fenugreek dumplings. If you don''t find Valor or a particular kind of flat beans used in Gujarat, you can use any locally available flat beans as well.', '["300 grams Flat Green Beans , cut into 1/2 inch pieces", "4 Small Brinjal (Baingan / Eggplant) , sliced into wedges", "1/2 teaspoon Ajwain (Carom seeds)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 inch Ginger , grated", "4 cloves Garlic , finely chopped", "2 Tomatoes , finely chopped", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Jaggery", "1 tablespoon Oil", "Salt , to taste", "Ingredients for Methia Muthia (Fenugreek Dumplings)", "50 grams Methi Leaves (Fenugreek Leaves) , finely chopped", "1/4 cup Gram flour (besan)", "2 tablespoons Whole Wheat Flour", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Jaggery", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Enos Fruit Salt", "1 teaspoon Lemon juice", "1 tablespoon Oil", "Salt , to taste"]'::jsonb, ARRAY['s flat green beans', 'small brinjal', 'baingan / eggplant', 'ajwain', 'carom seeds', 'mustard seeds', 'rai/ kadugu', 'ginger', 's garlic', 'tomatoes', 'asafoetida', 'hing', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'cumin powder', 'jeera', 'red chilli powder', 'jaggery', 'oil', 'salt', 'ingredients for methia muthia', 'fenugreek dumplings', 's methi leaves', 'fenugreek leaves', 'gram flour', 'besan', 's whole wheat flour', 'enos fruit salt', 'lemon juice']::text[], '["To begin making the\u00a0\u00a0Valor Muthia Nu Shaak, prepare all the ingredients and keep ready.For the Methi Muthia, in a small bowl combine the chopped methi leaves, gram flour, wheat flour, turmeric powder, sugar, asafoetida powder, eno fruit salt, lemon juice, oil and salt to taste to make the muthia.", "Add very little water to make firm dough.", "Divide the dough into 15 small portions.", "Shape them in ovals and lightly press them down.You can choose to steam the muthia\u2019s in a steamer on high heat for 10 minutes or pan fry in a paniyaram Pan.", "Add little oil into each of the cavities of the paniyaram pan on medium heat.Place the muthias in the cavity and pan fry them until golden brown and lightly crisp on all sides.Once done, remove from the pan and proceed making the remaining muthia.", "Keep aside.", "The next step is to make the Valor Muthia nu Shaak.", "Heat a teaspoon of oil in the pressure cooker medium heat; add the ajwain seeds, mustard seeds and asafoetida.When the seeds crackle, add the ginger and garlic and saute for a few seconds.", "Add the chopped tomatoes, turmeric powder, coriander powder, cumin powder, chilli powder, jaggery and salt and saut\u00e9 for a few seconds.Stir in the brinjal, the cut flat beans and 1/4 cup of water.", "Cover the pressure cooker, place the weight on and pressure cook until you hear a couple of whistles.", "After a couple of whistles, turn off the heat.", "Release the pressure immediately by placing the cooker under cold running water or lifting the weight with a fork.", "This process helps to release the pressure immediately and also stops the cooking process of the Valor Muthia nu Shaak.", "By stopping the cooking process, the beans and the eggplant retain its rich color.", "Open the cooker, and you will notice a semi gravy like consistency of the Valor Muthia nu Shaak.", "Check the salt and adjust to taste accordingly.", "At this stage, add the methi muthia.", "Turn the heat back on and simmer until the dumplings absorb the juices.", "Once done, turn off the heat, transfer the Valor Muthia nu Shaak to a serving bowl, garnish with chopped coriander leaves and serve hot.Serve the Valor Muthia nu Shaak along with Gujarati Kadhi and Ragi Phulkas for a delicious meal."]'::jsonb, 40, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/walor_muthia_nu_shaak_ringan_papdi_nu_shaak_Baingan_Papdi_6_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/670.walor_muthia_nu_shaak_ringan_papdi_nu_shaak_Baingan_Papdi_6_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pineapple Gojju Recipe (Karnataka Style Tangy And Spicy Pineapple Curry)', 'pineapple-gojju-recipe-karnataka-style-tangy-and-spicy-pineapple-curry', 'Pineapple Gojju Recipe is a sweet and spicy, tangy curry made using pineapples, typical to Karnataka. It is a festive dish and served during weddings and other celebrations when a traditional meal is served on a banana lead. It is rich in flavour, thanks to the pineapple and freshly ground spices that are used. It is best served with hot Steamed Rice, but can also be served with Chapatis.', '["1-1/2 cup Pineapple , chopped", "1/4 cup Fresh coconut", "2 tablespoons White Urad Dal (Split)", "1 tablespoon Tamarind Paste", "5 Dry Red Chillies", "2 tablespoons Jaggery", "Salt , to taste", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "12 Curry leaves", "2 tablespoons Oil"]'::jsonb, ARRAY['pineapple', 'salt', 'coconut', 'mustard seeds', 'jaggery', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'tamarind paste', 'sunflower oil']::text[], '["To begin making the Pineapple Gojju Recipe first place a pan on the heat.", "On a medium heat dry roast urad dal and set aside.Then dry roast the coconut till it turn slightly brown and toasted.", "Make sure not to burn it.", "Remove it and set it aside.Roast the red chillies with just a drop of oil, in the same pan.When the above roasted ingredients have cooled, put them in a mixer jar and grind into a paste along with tamarind paste, using water as much as it is required.Then, place a deep pan on the heat and add some oil to it.", "When it is warm, add mustard seeds and let it crackle.", "Add curry leaves and when they crisp up add in the pineapple chunks.Saute them by tossing on a medium heat until they soften and the edges start browning.", "At this point add the ground paste followed by 2 cups of water and allow the curry to simmer.Add salt and jaggery, mix well and bring it to a boil.", "Simmer for 10 mins more on a low heat, till the gravy turns thick.Serve it hot with steaming hot\u00a0Steamed Rice\u00a0and ghee or\u00a0with\u00a0Chapatis.", "You can also store the gojju in an airtight container in the refrigerator for a few days."]'::jsonb, 45, 'North Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuri_Aggarwal/Pineapple_Gojju_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/671.Pineapple_Gojju_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Egg Biryani Recipe with Figaro Olive Oil', 'spicy-egg-biryani-recipe-with-figaro-olive-oil', 'Spicy Egg Biryani is made with the combination of rice, eggs and a lot of spices. This is a perfect dish when you have guests at your home or if you are planning to organize a house party.', '["1 1/2 cup Basmati rice", "2 Onions , thinly sliced", "1 Onion , sliced and caramelized", "2 Tomatoes , pureed", "3 Whole Eggs , hard boiled", "3 Green Chillies , chopped", "2 inch Ginger", "6 cloves Garlic", "1/4 cup Mint Leaves (Pudina) , chopped", "1/2 cup Curd (Dahi / Yogurt)", "Saffron strands , a few strands soaked in milk", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "2 Bay leaves (tej patta)", "2 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "Salt , to taste", "1 tablespoon Extra Virgin Olive Oil", "2 Onions , sliced and caramelized", "Coriander (Dhania) Leaves , Few sprigs chopped", "1/4 cup Cashew nuts , roasted in ghee until browned", "Coriander (Dhania) Leaves , Few sprigs chopped", "1/4 cup Cashew nuts , roasted in ghee until browned"]'::jsonb, ARRAY['tomato', 'basmati rice', 'salt', 'ginger', 'garam masala powder', 'coriander (dhania) leaves', 'bay leaves (tej patta)', 'red chilli powder', 'cloves garlic', 'figaro pure olive oil', 'curd', 'cashew nuts ghee ed', 'onion', 'cinnamon stick (dalchini)', 'cloves (laung)', 'mint leaves (pudina)', 'eggs', 'turmeric powder', 'green chillies', 'saffron strands strands milk']::text[], '["To begin making the Spicy Egg Biryani, wash and soak rice in 1 cup of water for about 20 minutes.Grind the ginger, garlic and green chillies in a pestle and mortar.Heat olive oil in the pressure cooker on medium heat, add the sliced onions and cook them till they caramelize.", "This will take about 5-7 minutes.", "Add the ginger garlic paste and add whole spices.", "Saute until you can smell the delicious aromas.Add the pureed tomatoes, the turmeric powder, red chilli powder and garam masala powder, and mix well.When the masala is mixed properly, add the boiled eggs.", "Next add the rice, saffron milk, yogurt, salt and mint.Add 3 cups water and cook for three whistles and turn off the heat.Once done, turn off the heat and allow the egg biryani to rest for a few minutes.Garnish with caramelized onions, coriander leaves and cashew nuts.", "Serve Spicy Egg Biryani along with\u00a0Onion Raita\u00a0and\u00a0Mirchi Ka Salan\u00a0for a delicious weekend meal."]'::jsonb, 100, 'Indian', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/0-Archana/10-long-format-Spicy_Egg_Biryani_Recipe_Figaro_Olive_Oil_Video_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/672.10-long-format-Spicy_Egg_Biryani_Recipe_Figaro_Olive_Oil_Video_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hara Chana Masala Recipe', 'hara-chana-masala-recipe', 'Hara Chana or popularly known as Choliya or Green Chickpeas is a winter speciality of the Northern India. The fresh green chickpeas are tender, sweet and a delight to munch on. It has ample amounts of dietary fibres making it a super food to include in our diets. This recipe however, makes use of the dried green chickpeas variety. It is cooked with mild aromatic spices, making it a perfect accompaniment with roti''s or steamed rice on a rainy evening.', '["200 grams Hara Chana , soaked overnight", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1 Cinnamon Stick (Dalchini)", "2 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "2 tablespoon Ghee", "2 teaspoons Coriander (Dhania) Leaves , finely chopped", "Salt , to taste", "To grind to a smooth paste", "2 inch Ginger", "5 cloves Garlic", "1 Green Chilli", "1 inch Cinnamon Stick (Dalchini)", "3 Cloves (Laung)"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'green chilli', 'ghee', 'coriander (dhania) leaves', 'hara chana', 'red chilli powder', 'cloves garlic', 'onion', 'cinnamon stick (dalchini)', 'coriander powder', 'cloves (laung)', 'garam masala powder']::text[], '["To begin making the Hara Chana Masala Recipe, soak the dried green chickpeas overnight and in the morning cook it along with salt for 3 whistles in a pressure cooker and keep aside.Now, grind the ingredients mentioned in the ''to grind to a smooth paste'' table using a hand mixer or blender adding little water and keep aside.Heat green in a heavy bottom pan on low heat, add the cinnamon stick and finely chopped onions and saut\u00e9 till it becomes translucent.Add the ground spice paste and saute until the raw smell of the ginger-garlic goes away.Add the finely chopped tomatoes and cook until it turns soft and mushy.Now add the spice powders - coriander, chilli and garam masala powder and cook until the whole mix comes together and oil separates out.Add the boiled green chickpeas, two cups of water and season with salt and simmer for 10 minutes.Garnish with coriander leaves and switch off the flame.", "Serve the warm Hara Chana Masala Recipe along with\u00a0roti''s\u00a0or steamed rice on a rainy evening."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Hara_Chana_Masala_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/673.Hara_Chana_Masala_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Menthi Aaku Badeela Koora Recipe - Besan Muthia Cooked With Methi Leaves', 'menthi-aaku-badeela-koora-recipe-besan-muthia-cooked-with-methi-leaves', 'Badeela Koora is a traditional dry curry recipe of Telangana household made using just a handful ingredients where Fenugreek leaves and Chickpea flour are the main ingredients.', '["4 cups Methi Leaves (Fenugreek Leaves)", "1-1/2 cups Gram flour (besan)", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "1 teaspoon Garam masala powder", "2 teaspoons Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1/4 cup Water", "Oil , as needed", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "2 Dry Red Chillies"]'::jsonb, ARRAY['salt', 'ginger', 'mustard seeds', 'methi leaves (fenugreek leaves)', 'red chilli powder', 'cloves garlic', 'water', 'gram flour (besan)', 'curry leaves', 'dry red chillies', 'cumin seeds (jeera)', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making Menthi Aaku Badeela Koora Recipe, wash and chop the fenugreek/methi leaves and keep aside.To a bowl, add the chickpea/besan flour, red chilli powder, salt, ginger garlic paste, garam masala powder and turmeric powder.Add enough water and knead them to a stiff dough.", "When the dough is coming together, in the end\u00a0add a teaspoon of oil and knead it again.Next step is to divide the dough into small portions.", "Apply a little amount of oil onto your palms and roll out small pebble sized balls out of each dough portions.\u00a0(These are called badeela).", "Set them ready on a greased plate.To a heavy bottomed pan, heat 2 tablespoons of oil.", "Once the oil is hot, add the cumin seeds, mustard seeds, curry leaves and dry red chillies.", "Let it cook for about 30 seconds.", "Add the rolled badeela (Chickpea flour balls) and give it a good stir.", "Cover and cook for\u00a0badeela for 10 minutes stirring in intervals to check the Badeela Koora for the doneness.", "The badeela will take a good 10 -12 minutes to cook.", "Give the Badeela a bite and it should not taste raw.", "Once the badeela koora is cooked properly, stir in the methi leaves and saute for about 3 to 4 minutes until the methi leaves is cooked and wilts down.Once the Menthi Aaku Badeela Koora done turn off the heat and serve hot.Serve\u00a0Menthi Aaku Badeela Koora\u00a0along with\u00a0Andhra Style Ingavu Chaaru Recipe\u00a0and\u00a0Steamed Rice\u00a0for an\u00a0Andhra Style Sunday Lunch and a\u00a0indian diabetic meal."]'::jsonb, 40, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swapna_sunil/Menthi_Aaku_Badeela_koora.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/674.Menthi_Aaku_Badeela_koora.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gavar Pumpkin Sabji Recipe', 'gavar-pumpkin-sabji-recipe', 'Gavar (Gaur or Cluster beans) and Pumpkin (Kaddu/Lal Bhopla) sabji is a simple and healthy accompaniment for rotis or rice. The sweetness of the Pumpkin balances the slight bitterness of the Gavar beans and both these vegetables pair up well in this humble sabji. There are various ways to prepare the sabji, this recipe uses basic spices, easily available in the pantry.', '["1 cup Gawar Phali (Kothavarangai / Cluster beans) , washed strings removed and cut", "1 cup Kaddu (Parangikai/ Pumpkin) , peeled and chopped", "1 Onion , chopped", "5 Garlic , crushed", "4 Dry Red Chillies , chopped (or 1 teaspoon red chilli powder)", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1/2 teaspoon Asafoetida (hing)", "1 teaspoon Fennel seeds (Saunf) , toasted and crushed", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Amchur (Dry Mango Powder)", "2 teaspoons Roasted Peanuts (Moongphali) , powdered (optional)", "1/2 teaspoon Turmeric powder (Haldi)", "Oil , as required", "Salt , to taste", "Coriander (Dhania) Leaves , for garnishing, finely chopped"]'::jsonb, ARRAY['salt', 'parangikai pumpkin', 'amchur (dry mango powder)', 'asafoetida (hing)', 'fennel seeds (saunf)', 'mustard seeds', 'coriander (dhania) leaves', 'dry red chillies (or red chilli powder)', 'garlic', 'onion', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'peanuts (moongphali)', 'coriander powder', 'turmeric powder', 'gawar phali (kothavarangai cluster beans) st', 'sunflower oil']::text[], '["To begin making the Gavar Pumpkin sabji, first heat a small wok.Add the fennel seeds.", "Toast them lightly and cool.", "Crush them coarsely using a mortar pestle or a rolling pin.Heat oil in a pressure pan or wok.", "Add the mustard seeds and once they splutter add the cumin seeds.Add the methi seeds, red chillies, hing and turmeric.", "Add the crushed garlic and onion and saute for a minute.Add the gavar beans and pumpkin pieces.", "Add the other spices including crushed fennel, coriander powder, amchur powder (or tamarind pulp) and mix well.Season with salt and add 1/2 cup (or more) water.", "Pressure cook for 1 whistle and 5 minutes on low heat or till the beans and pumpkin just become soft.You can alternatively cook covered in a wok till the vegetables just become soft.Adjust the water quantity (depending on whether you want a dry sabji or wet), sprinkle peanut powder (if using).", "Mix well and cook for 1-2 minutes.Serve hot garnished with coriander leaves.", "Serve Gavar Pumpkin Sabji as a side dish with\u00a0Panchmel Dal\u00a0and hot\u00a0Phulkas."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Gavar_cluster_beans_Pumpkin_Sabji.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/675.Gavar_cluster_beans_Pumpkin_Sabji.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Marwadi Gatte Ki Kadhi Recipe - Gram Flour Dumpling In Yogurt Curry', 'marwadi-gatte-ki-kadhi-recipe-gram-flour-dumpling-in-yogurt-curry', 'Marwadi Gatte Ki Kadhi Recipe (Gram Flour Dumpling In Yogurt Curry Recipe) is an authentic Rajasthani Khadi made by simmering the yogurt based curry with spicy gram flour dumpling. This curry compliments very well Phulka and Steamed rice and is served with a dollop of ghee.', '["1/2 cup Gram flour (besan)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Ajwain (Carom seeds)", "1 tablespoon Curd (Dahi / Yogurt)", "Salt , to taste", "2 tablespoon Gram flour (besan)", "1 cup Curd (Dahi / Yogurt)", "4 cloves Garlic", "2 Green Chillies", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 sprig Coriander (Dhania) Leaves , finely chopped", "Ingredients for tadka", "1 teaspoon Ghee", "1/2 teaspoon Cumin seeds (Jeera)", "1 Dry Red Chilli", "1 inch Cinnamon Stick (Dalchini)"]'::jsonb, ARRAY['salt', 'ghee', 'ajwain (carom seeds)', 'red chilli powder', 'cloves garlic', 'gram flour (besan)', 'curd', 'coriander (dhania) leaves', 'dry red chilli', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies']::text[], '["To begin making the Marwadi Gatte Ki Kadhi Recipe (Gram Flour Dumpling In Yogurt Curry Recipe), we will first make the gatte.In a mixing bowl, combine all the ingredients for the gatte including gram flour, red chilli powder, ajwain, curd, salt and knead to make a stiff dough.", "Add a little water if required.Divide the gatte mixture into 8 to 10 small portions, and shape into a small cylindrical roll.", "Keep it aside.The next step is to cook the gatte.Heat water in the saucepan and bring it to a roaring boil.", "Place the gatte in the boiling water and allow it to cook for about 7 to 8 minutes.You will notice the gatte rising to the top.", "After 7 to 8 minutes, drain the gatte from the water and keep aside.In a small pestle and motor, pound the garlic and green chilies to make a coarse paste.The next step is to make the kadhi.", "In a large saucepan, whisk the yogurt along with the gram flour in a mixing bowl.", "Add 2 cups of water to make a smooth batter.", "Add the coarse paste and turmeric powder.Place the saucepan over high heat, add the kadhi mixture into it and bring the kadhi to a boil.", "Keep whisking while the kadhi boils to bring the mixture to a homogeneous consistency.Once the kadhi thickens, turn the heat to low, add the gatte and allow it to simmer for another 5 minutes.While the Gatte ki Kadhi is simmering, we will proceed to make the tadka.", "Heat ghee over medium heat in a tadka pan, add the cumin seeds, red chili, and cinnamon and saute for a few seconds.Add the tadka to the Gatte ki Kadhi, stir in the coriander leaves and serve.Serve the\u00a0Gatte Ki Kadhi Recipe\u00a0along with\u00a0Gehun Ki Bikaneri Khichdi,\u00a0Bajri Ki Roti\u00a0and\u00a0Bharwa Bhindi\u00a0for a weekday meal."]'::jsonb, 55, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/oct-5/Marwadi_Gatte_Ki_Kadhi_Recipe-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/676.Marwadi_Gatte_Ki_Kadhi_Recipe-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bhindi With Cashews & Coconut Sabzi Recipe', 'bhindi-with-cashews-coconut-sabzi-recipe', 'Bhindi with Cashews & Coconut Sabzi Recipe is a nice way to cook bhindi as a side dish. This sabzi recipe is apt when you have guests at home, since it''s easy and impressive side dish. This recipe of Bhindi with cashews and coconut sabzi goes well with rasam.', '["1/2 kg Bhindi (Lady Finger/Okra) , cut to bite size", "4 Garlic", "8 Cashew nuts", "1-1/2 tablespoon Fresh coconut , grated", "Curry leaves , few", "2 teaspoon Red Chilli powder", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Chana dal (Bengal Gram Dal)", "1 Dry Red Chilli", "1-1/2 tablespoon Oil"]'::jsonb, ARRAY['bhindi', 'lady finger/okra', 'arlic', 'cashew nuts', 'fresh coconut', 'curry leaves', 'red chilli powder', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'chana dal', 'bengal gram dal', 'dry red chilli', 'oil']::text[], '["To make Bhindi with Cashews & Coconut Sabzi Recipe, cut ladies finger into small pieces.", "Get prep with the other ingredients as well.Take a pan/kadai, add oil, mustard, cumin seeds, channa dhal, dry red chili and garlic.", "Let it get fried.Add cashew nuts and cook until they are lightly browned, this would take about 1 -2 minutes only.", "Do not make it completely brown.Add bhindi, turmeric, chili powder, salt & curry leaves.Keep mixing and cook until okra/bhindi are fried well.At this stage, add fresh coconut, mix well and immediately switch off gas.Serve Bhindi with Cashews & Coconut Sabzi Recipe with\u00a0rasam."]'::jsonb, 35, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Neeru_Srikanth/Ladies_finger_with_Cashews__Coconut.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/677.Ladies_finger_with_Cashews__Coconut.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hari Dhania Ki Sabzi ( Fresh Coriander leaves Dry Curry) Recipe', 'hari-dhania-ki-sabzi-fresh-coriander-leaves-dry-curry-recipe', 'Hari Dhania Ki Sabzi is a dry Indian curry made from fresh coriander leaves. Typically the leaves are used as a garnish for many Indian dishes. But in this recipe, the coriander is cooked along with gram/besan flour which bring the dish together.', '["6 sprig Coriander (Dhania) Leaves , washed and finely chopped", "2 tablespoons Gram flour (besan)", "1 Potato (Aloo) , boiled and mashed", "1/8 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "To Temper", "2 teaspoons Sesame (Gingelly) Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1-2 Green Chillies , finely chopped", "1/2 teaspoon Cumin seeds (Jeera)", "Asafoetida (hing) , a pinch"]'::jsonb, ARRAY['salt', 'mustard seeds', 'asafoetida (hing)', 'potato (aloo)', 'sesame (gingelly) oil', 'gram flour (besan)', 'coriander (dhania) leaves', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies']::text[], '["To begin making the\u00a0Hari Dhania Ki Sabzi ( Fresh Coriander leaves Dry Curry) firstheat a medium sized pan with 2 teaspoon of sesame oil and temper the mustard seeds, green chillies, cumin seeds and asafoetida.Add the gram/besan flour, turmeric powder and roast it over low heat for 5 minutes till it turns fragrant.Add the chopped coriander leaves and potatoes, salt for taste , then cover and cook for another 4-5 minutes.Sprinkle a little water while cooking so the besan and the potatoes get cooked and get a crumbly texture.", "Once done, check the taste and adjust the salt and spices accordingly.", "A very simple and refreshing Hari Dhania Ki sabzi is ready to be served.Hari Dhania Ki Sabzi ( Fresh Coriander leaves Dry Curry)\u00a0can be served with\u00a0Phulka, or steamed rice for a weekday meal."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Uma_Raghuraman/Hari_Dhania_Ki_Sabzi__Fresh_Coriander_leaves_Dry_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/678.Hari_Dhania_Ki_Sabzi__Fresh_Coriander_leaves_Dry_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Plain Dalia Recipe- How To Cook Broken Wheat In Pressure Cooker', 'plain-dalia-recipe-how-to-cook-broken-wheat-in-pressure-cooker', 'Plain Dalia/ broken wheat is a high fiber, full of nutrition tasty carbohydrate. It can be easily made in a pressure cooker. Broken wheat is great to be included in your diet. There are lots of recipes that you can make with broken wheat. They can all easily be cooked in a pressure cooker but if you like you can cook the broken wheat in a saucepan as well. When cooking in a saucepan ensure that you put enough water. Remove any excess water in the pan after the broken wheat/ dalia is cooked.', '["1 cup Broken Wheat (Dalia/ Godumai Rava)", "2 cups Water"]'::jsonb, ARRAY['broken wheat', 'dalia/ godumai rava', 's water']::text[], '["To begin making\u00a0Plain Dalia Recipe in a Pressure cooker first wash the broken wheat a couple of times and soak the dalia/broken wheat for half an hour.", "Add the broken wheat/ dalia into a pressure cooker and close the lid.Keep the pressure cooker on heat and pressure cook for one whistles.", "Reduce the heat after one whistle to medium and cook for another two whistles.", "Turn off the heat.Let the pressure release naturally and then open the lid of the pressure cooker.", "Take a fork or spoon and fluff up the dalia/ broken wheat and remove into a serving bowl.", "Serve Dalia/ Broken Wheat along with\u00a0Palak Tovve or Palak Dal,\u00a0Masalewali Turai Sabzi\u00a0and\u00a0Tomato Onion Cucumber Raita\u00a0for a wholesome lunch."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/cooked_broken_wheat_recipe_dalia_1-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/679.cooked_broken_wheat_recipe_dalia_1-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kongunadu Urulai Kurma Recipe (Curried Potatoes from Kongunadu)', 'kongunadu-urulai-kurma-recipe-curried-potatoes-from-kongunadu', 'Kongunadu, the areas around Coimbatore and Erode is a fertile region. Every home in the village has their own garden and the people are passionate about growing their own fruits and vegetables. In the Kongunadu Cuisine lots of coconut and tomatoes are used as they are widely grown in these areas. Of course the taste of tomatoes grown there cannot be matched with the ones available in cities. The masalas are mildly spicy, tangy and tasty. Their dishes can be made quickly with simple ingredients in your pantry with very less effort. Potatoes are cooked in a tangy tomato-onion gravy .', '["2 Potato (Aloo) , boiled and cubed", "1 cup Homemade tomato puree", "1 Onion , finely chopped", "1 inch Ginger , grated", "3 Garlic , grated", "1/4 teaspoon Turmeric powder (Haldi)", "1 tablespoon Oil , or ghee", "Salt , to taste", "4 sprig Coriander (Dhania) Leaves , finely chopped", "To roast and grind", "2 teaspoon Chana dal (Bengal Gram Dal) , roasted", "3 Dry Red Chillies , adjust according to tasted", "1/2 teaspoon Fennel seeds (Saunf)", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Whole Black Peppercorns", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta)", "1/2 cup Fresh coconut , grated"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'sunflower oil ghee', 'bay leaf (tej patta)', 'fennel seeds (saunf)', 'coconut', 'potato (aloo)', 'black peppercorns', 'coriander (dhania) leaves', 'dry red chillies', 'onion', 'garlic', 'cumin seeds (jeera)', 'cinnamon stick (dalchini)', 'cloves (laung)', 'turmeric powder', 'chana dal (bengal gram dal)']::text[], '["To begin making the Kongunadu Urulai Kurma Recipe, in a small pan, lightly dry roast all the ingredients given under \u2018to roast and grind\u2019 till they turn fragrant.", "Once roasted, allow it to cool a little and grind into a smooth paste adding a little warm water.Keep the paste aside.Heat a wide pan or kadai with ghee.", "Add the grated ginger and garlic and saute them for a few seconds.", "Add the\u00a0chopped onions, little salt and keep stirring over low flame for one minute or till the time the onions turn glossy and lightly brown.Once the onions are done, add the tomato puree, turmeric powder, the ground masala and the boiled potatoes.", "Turn the heat to low, cover the pan and simmer the Kurma for about 5 minutes until the spices come through into the potatoes.", "After 5 minutes, once done, check the salt and adjust to suit your taste and turn off the heat.", "Garnish with chopped coriander leaves and serve hot.Serve Kongunadu Urulai Kurma along with\u00a0Dosas\u00a0for a quick weeknight dinner or even for parties."]'::jsonb, 55, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Uma_Raghuraman/Kongunadu_Urulai_Kurma__Curried_Potatoes_from_Kongunadu.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/680.Kongunadu_Urulai_Kurma__Curried_Potatoes_from_Kongunadu.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hara Dhania Paratha Recipe - Coriander Paratha', 'hara-dhania-paratha-recipe-coriander-paratha', 'The Hara Dhania Paratha also known as the Coriander Paratha is a simple and healthy paratha that is extremely rich in fiber and nutrition. This paratha is a refreshing change from the regular roti and phulkas and can be had as snack or packed into your kids lunch box.', '["1-1/2 cups Whole Wheat Flour", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Turmeric powder (Haldi)", "Coriander (Dhania) Leaves , small bunch, finely chopped", "2 Green Chillies , finely chopped", "1 inch Ginger , grated", "Salt and Pepper , to taste", "Oil , or ghee for cooking"]'::jsonb, ARRAY['s whole wheat flour', 'cumin powder', 'jeera', 'turmeric powder', 'haldi', 'coriander', 'dhania', 'reen chillies', 'ginger', 'salt and pepper', 'oil']::text[], '["To begin making the Hara Dhania Paratha Recipe, combine\u00a0 the wheat flour, cumin powder, turmeric powder, coriander leaves, green chillies, ginger, salt and pepper into a large mixing bowl.", "Add a little water at a time and knead to make a firm and smooth dough.", "Drizzle a teaspoon of oil over the dough and knead for a couple of minutes until the dough is smooth and soft.Keep the dough covered in a bowl for at least 10 minutes before you can start making the paratha.Divide the dough into 10 to 12 portions.", "Take each paratha ball, dust in flour and\u00a0 roll it out into a round circle of about 8 inch diameter.", "Now, heat the flat iron skillet on medium heat for a few minutes.Place the rolled paratha dough on the heated skillet and cook the paratha on medium heat until you notice spots appear on the top.", "At this point flip and cook\u00a0 the dhania paratha the other side. smear some oil or ghee and flip again.", "Cook on both sides, until you notice that the parathas have golden brown spots on both sides and is cooked.Continue the same process of cooking the remaining hara dhania parathas and stack them one over the other.Serve these delicious Hara Dhania Paratha or Coriander Parathas along with\u00a0Aam Ka Achaar Recipe\u00a0and\u00a0\u00a0Boondi Raita Recipe Spiced With Black Salt."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breads/Coriander_Paratha_Dhania_Roti_Chapati_Recipe-7.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/681.Coriander_Paratha_Dhania_Roti_Chapati_Recipe-7.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Manipuri Style Mangal Ooti Recipe - Yellow Peas Curry Recipe', 'manipuri-style-mangal-ooti-recipe-yellow-peas-curry-recipe', 'Manipuri Mangal Ooti is a Manipuri side dish served  during Kang festival in their region. A simple peas dish that is very popular  as a breakfast or dinner option. It is cooked in soda and mustard oil tadka and makes for a delicious accompaniment along with any Indian Bread.', '["1 cup Dried Yellow/White Peas (Vatana) , overnight soaked", "1/2 teaspoon Cooking soda", "Salt , to taste", "2 tablespoons Mustard oil", "1 teaspoon Cumin seeds (Jeera)", "1 Bay leaf (tej patta)", "1 tablespoon Ginger , grated", "2 Onion , chopped", "1 Tomato , chopped", "2 Green Chilli , chopped", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste"]'::jsonb, ARRAY['dried yellow/white peas', 'vatana', 'cooking soda', 'salt', 's mustard oil', 'cumin seeds', 'jeera', 'bay leaf', 'tej patta', 'ginger', 'onion', 'tomato', 'reen chilli', 'turmeric powder', 'haldi']::text[], '["To begin the preparation of Manipuri Mangal Ooti, at first take the overnight soaked peas in a pressure cooker with little water by adding salt and cooking soda and pressure cook on medium heat up to 2 whistle. \u00a0.Turn off the flame and place the cooker under running cold water.", "Open the cooker lid and keep aside.Take a pan, heat the mustard oil in it add bay leaf and cumin seeds & fry for 30 seconds.", "Now add the chopped onions to the pan and some salt, fry till the onions becomes soft and light brown.Now add the chopped tomatoes, turmeric powder and grated ginger fry for a minutes till oil oozes from the mixture \u00a0.Now add the boiled peas and toss with masala mixture.", "Add 1/2 cup of warm water to the pan and let the curry boil for 5 minutes and cover on low heat.After 5 minutes of boiling the curry, give it a nice stir.", "Turn off the flame and let the curry stand for 10 minutes.Garnished with onion ring and tomato flower if you like.", "Serve\u00a0Manipuri Style Mangal Ooti Recipe (Yellow Dried Peas Curry Recipe) along with with\u00a0phulka\u00a0or\u00a0Homemade Butter Naan Recipe (Soft Yogurt Bread)\u00a0fora wonderful lunch."]'::jsonb, 25, 'North East India', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/28-march/Manipuri_style_Mangal_Ooti_Recipe_Yellow_dried_peas_curry-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/682.Manipuri_style_Mangal_Ooti_Recipe_Yellow_dried_peas_curry-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Style Recheado Bangdo Recipe | Stuffed Mackerel', 'goan-style-recheado-bangdo-recipe-stuffed-mackerel', 'Recheado or reshad Bangdo is one of the Goan Speciality where Bangdo or Mackerel is stuffed with Goan Recheado spice masala. This spice or masala can be prepared and stored in the refrigerator and be used whenever required. In Recheado Mackerel, the masala is stuffed inside the Mackerels and pan fried using cooking oil. For more better taste, it is always good to stuff these Mackerels and refrigerate overnight which helps in marination and the flavours also be absorbed better.', '["6 Mackerel fish , cleaned and slit", "1/2 Cup Goan recheado masala", "1 Cup Sooji (Semolina/ Rava)", "Extra Virgin Olive Oil , to shallow fry", "Salt , to taste"]'::jsonb, ARRAY['salt', 'goan recheado masala', 'virgin olive oil', 'mackerel fish', 'sooji (semolina rava)']::text[], '["To begin making Goan Style Recheado Bangdo Recipe | Stuffed Mackerel, remove the head and tail of the mackerels.Slit them in the center all the way from head to tail.", "If possible, remove the bone or else leave it on.", "Wash them well for 3-4 times.Apply salt and keep them for 5 minutes.Now stuff in Recheado paste properly inside the Mackerels.Rub a little of the spice paste on the outside of the fish too, on both the sides of the Mackerels.Let them marinade for at least an hour.", "You can keep them refrigerated overnight to get even more delicious recipe when done.Coat them with semolina on both the sides.Heat a skillet, add a tablespoon of oil.Place these mackerels on top of the oil and let them cook on medium high heat for about 5 minutes.Flip and let them cook on the other side too, till done.Remove when they look all crispy brown on both the sides.Serve\u00a0Goan Style Recheado Bangdo Recipe | Stuffed Mackerel as a complete meal when paired along with\u00a0Steamed Rice,\u00a0Moryechi Xacuti Recipe (Goan Style Shark Curry)\u00a0or a\u00a0Goan Mackerel Curry (Bangdyache Hooman) Recipe\u00a0and enjoy!."]'::jsonb, 75, 'Goan', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/reachado_bangdo_recipe_goan_style.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/683.reachado_bangdo_recipe_goan_style.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karlyachi Ambat Goad Bhaji Recipe - Maharashtrian Sweet & Sour Karela Sabzi', 'karlyachi-ambat-goad-bhaji-recipe-maharashtrian-sweet-sour-karela-sabzi', 'Kaarlyachi Aambat Goad Bhaaji is a Maharashtrian Bitter Gourd Sweet And Sour Curry that is extremely healthy and simple to make.', '["500 grams Karela (Bitter Gourd/ Pavakkai)", "2 Onions , chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Kashmiri Red Chilli Powder", "3 teaspoons Jaggery", "1 teaspoon Tamarind Paste", "Salt , to taste", "1 tablespoon Oil", "1 Onion , sliced", "1 cup Fresh coconut , grated", "1 teaspoon Oil", "2 teaspoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)"]'::jsonb, ARRAY['s karela', 'bitter gourd/ pavakkai', 'onions', 'turmeric powder', 'haldi', 'red chilli powder', 'kashmiri red chilli powder', 's jaggery', 'tamarind paste', 'salt', 'oil', 'onion', 'fresh coconut', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing']::text[], '["To begin making the Kaarlyaachi Aambat Goad Bhaaji, first wash the bitter gourds, deseed the bitter gourds and cut into roundels.", "Transfer to a mixing bowl.", "Heat a kadai on medium heat,add the oil, once the oil is hot add the sliced onions and saute for a couple of minutes.", "When the onions turn translucent add the freshly grated coconut and saute on low heat till it becomes light brown in colour.", "Turn off the heat and set aside to cool.Transfer the\u00a0 onions and coconut into a mixer-jar and grind this along with the tamarind, using sufficient water to get a smooth paste.", "Heat a pan on medium heat, add oil to saute the bitter gourd roundels.", "Saute on low-medium heat stirring constantly to prevent the roundels from burning.When the bitter gourd roundels turn dark in colour and are nice and crispy, turn off the heat and set aside.Now for the tempering, heat a saucepan with oil on medium heat,add mustard seeds, once they splutter, add the asafoetida and mix well.", "Now add the chopped onions and saute till translucent, this will take about 2 minutes.", "Once done add the turmeric and red chilli powders and stir well to combine.Now add the crispy bitter gourd roundels, jaggery, the ground coconut paste and salt to taste.", "Add some water as required to get a thick gravy.", "Bring Kaarlyachi Aambat Goad Bhaaji to a rolling boil and then simmer on low heat for a couple of minutes and turn off the heat.Transfer\u00a0 Kaarlyachi Aambat Goad Bhaaji to a serving bowl and serve.Serve this\u00a0Kaarlyachi Aambat Goad Bhaaji\u00a0along with\u00a0Rice Flour Bhakri Recipe\u00a0\u00a0and\u00a0Maharashtrian Ambat Goda Dal Recipe\u00a0and\u00a0Steamed Rice\u00a0for a simple maharashtrian meal for a weeknight dinner.", "For an\u00a0Indian Diabetic Meal, serve this\u00a0Kaarlyachi Aambat Goad Bhaaji\u00a0along with\u00a0Bajri Ki Roti Recipe\u00a0and\u00a0Methi Moong Dal Palak Recipe\u00a0for a completely healthy meal."]'::jsonb, 90, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/karela-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/684.karela-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Vegetable Curry Recipe', 'goan-vegetable-curry-recipe', 'Goan Vegetable Curry Recipe is a classic dish from Goa. It is a part of day to day meal. It is made with mixed vegetables. This dish is simple and easy to make.You can add vegetables according to your taste and preference. Its creamy and coconut based and will spice up your everyday meal.', '["4 cups Mixed vegetables , French beans, carrots, peas, potatoes, cauliflower, squash)", "1 Onion", "Salt , to taste", "1/2 teaspoon Turmeric powder (Haldi)", "1 Green Chilli", "1 teaspoon Coconut Oil", "100 grams Fresh coconut , grated", "4 Kashmiri dry red chillies", "1/2 teaspoon Whole Black Peppercorns", "1/2 Onion , sliced", "4 cloves Garlic", "1 tablespoon Coriander (Dhania) Seeds", "1 teaspoon Cumin seeds (Jeera)", "1 Tamarind , lemon size"]'::jsonb, ARRAY['salt', 'green chilli', 'coconut', 'kashmiri dry red chillies', 'black peppercorns', 'cloves garlic', 'coriander (dhania) seeds', 'onion', 'coconut oil', 'cumin seeds (jeera)', 'turmeric powder', 'mixed vegetables french beans', 'tamarind lemon']::text[], '["To begin making the Goan Vegetable Curry Recipe, clean and chop the vegetables into cubes.", "Add oil in a heavy bottomed pan and add onions.", "Cook till the onions becomes translucent.Add remaining vegetables, turmeric powder, green chillies and required amount of water.", "Cook on medium flame till it is done.Meanwhile, grind all the ingredients mentioned under masala including coconut, kashmiri dry red chillies, whole black peppercorns, onion, garlic, coriander seeds, cumin seeds, tamarind to a smooth paste.", "Add the masala paste and salt to the cooked vegetables.", "Cook on sim till the raw smell from curry goes and keep stirring in between.", "This will take about 5 to 7 minutes.Switch off when the curry is cooked properly.", "Serve hot.Serve\u00a0Goan Vegetable Curry Recipe along with\u00a0Beetroot Raita\u00a0and\u00a0Whole Wheat Lachha Paratha\u00a0for a weekday meal."]'::jsonb, 35, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/Goan_vegetable_curry_recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/685.Goan_vegetable_curry_recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pacha Manga Pachadi Recipe - Raw Mango Pachadi', 'pacha-manga-pachadi-recipe-raw-mango-pachadi', 'The Pacha Manga Pachadi Recipe is a tangy and sweet chunky mango chutney that is packed with taste and flavours from raw mango, jaggery and a delicious seasoning.', '["2 Mango (Raw) , peeled and cut into small chunks", "1/2 cup Jaggery , powdered", "1/4 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Salt , or to taste", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves , torn", "2 Dry Red Chillies , broken into half", "1 tablespoon Gingelly oil"]'::jsonb, ARRAY['salt', 'tamarind water', 'mustard seeds', 'asafoetida (hing)', 'jaggery', 'mango the skin', 'curry leaves', 'dry red chillies', 'turmeric powder', 'sambar powder', 'sunflower oil']::text[], '["To begin making the Pacha Manga Pachadi Recipe, prepare all the ingredients and keep ready.Lightly peel the skin off the raw mango and cut into small chunks.Add the raw mango into the pressure cooker, along with jaggery, salt, turmeric powder and red chilli powder.", "Add 1/2 cup of water and pressure cook for 3 whistles and turn off the heat.", "Allow the pressure to release naturally.", "Once it does, open the cooker and you will notice the Manga Pachadi having a jam like consistency.Give it a stir and taste.", "Add more salt if required.The last step is to season the Manga Pachadi.", "Heat oil in a pan over medium heat; add the mustard seeds, cumin seeds and red chillies.", "Stir until the seeds crackle.Add the curry leaves and finally stir in the cooked Raw Mango Pachadi.", "Bring it to one brisk boil and turn off the heat.", "Transfer the Raw Mango Pachadi/Manga Pachadi to a serving bowl or store in an airtight container.", "The\u00a0Raw Mango Pachadi/Manga Pachadi\u00a0will stay for at least one week when refrigerated.Serve the Pacha Manga Pachadi along with steamed rice,\u00a0Mixed Vegetable Sambar Recipe\u00a0and\u00a0Kurukku Kaalan Recipe\u00a0for south indian lunch or dinner."]'::jsonb, 20, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2021/Raw_Mango_Pachadi_Recipe_8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/686.Raw_Mango_Pachadi_Recipe_8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Baingan Methi Ka Bharta Recipe with Pomegranates', 'baingan-methi-ka-bharta-recipe-with-pomegranates', 'Baingan Methi Ka Bharta Recipe with Pomegranates is a twist to the classic Punjabi Recipe that is made from smoked and chargrilled brinjals then mish-mashed and cooked along with a combination of spices. Along with the main ingredients that flavor, this recipe also has methi leaves, that are sauteed and added to the Bharta to pack it with flavors. And to add color and subtle sweetness to this dish, when serving the Baingan Methi Ka Bharta, I sprinkled it with Pomegranate seeds and served it along with Phulkas and Punjabi Kadhi Pakora.', '["150 grams Methi Leaves (Fenugreek Leaves) , finely chopped", "1 Brinjal (Baingan / Eggplant)", "2 inch Ginger , peeled and grated", "1 Onion , finely chopped", "1 Tomato , grated", "2 Green Chillies , finely chopped", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "1 tablespoon Butter (Salted)", "1 teaspoon Red Chilli powder", "Salt , to taste", "1 tablespoon Oil", "1/4 cup Anardana Powder (Pomegranate Seed Powder)"]'::jsonb, ARRAY['s methi leaves', 'fenugreek leaves', 'brinjal', 'baingan / eggplant', 'ginger', 'onion', 'tomato', 'reen chillies', 'turmeric powder', 'haldi', 'garam masala powder', 'coriander powder', 'dhania', 'butter', 'salted', 'red chilli powder', 'salt', 'oil', 'anardana powder', 'pomegranate seed powder']::text[], '["To begin making this recipe, we will first saute the chopped methi leaves.", "Heat a teaspoon of oil in a pan, add the chopped methi leaves and stir fry it on medium heat until you notice the leaves shrink and soften.", "The methi leaves will also give out a lot of water.", "Evaporate most of the moisture by turn the heat to high for a few minutes.", "Once most of the water is evaporated, turn off the heat and keep the methi aside.The next step is to make the Baingan\u00a0Bharta.", "For this, the \u00a0brinjal can be roasted in two ways; in the oven or on the gas flame.Method using the oven for roasting :\u00a0Preheat the oven to 180 C.Place the brinjal on a baking sheet and place in the preheated oven for about 30 minutes or until the brinjal has started to soften and the outer skin is charred.When you prick inside with a knife, you can feel that the brinjal has become\u00a0tender,\u00a0if not continue to roast until done.Method using the flame for roasting:\u00a0Place the brinjal on the stove top flame, with continuous monitoring, using tongs to turn the brinjal around while it is roasting.After about 10\u00a0minutes\u00a0you will notice that the brinjal\u2019s skin begins to char and the inside begins to get tender.", "To test, when you insert a knife you will feel it is soft and not hard.", "If hard continue to roast until done.Once brinjal is roasted allow the brinjal to cool down.", "Peel the charred skin of the cooled brinjal and discard the skin.", "Coarsely mash the pulp using a fork or mince finely using a knife.Heat oil in a pan over medium high\u00a0heat.", "Add the cumin seeds and allow seeds to crackle.", "Add the grated ginger and chopped onions, saut\u00e9 over medium heat until the onions are tender.Then add the grated tomatoes, turmeric powder, green chillies, coriander powder, garam masala powder and chilli powder.", "Stir to combine and saut\u00e9 until all the ingredients come together for about couple of minutes.Stir in the roasted brinjal, butter and salt.", "Turn the heat to low and simmer the brinjal for about 10 minutes or so until it gets well combined with the tomatoes and spices.", "Turn off the heat and stir in the sauteed methi leaves.", "Check the salt and spices and adjust to suit your taste.To add color and subtle sweetness to this Baingan Methi Bharta, sprinkle it with Pomegranate seeds and served it along with\u00a0Phulkas\u00a0and\u00a0Punjabi Kadhi Pakora."]'::jsonb, 50, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Baingan_Bharta_with_Methi_Sabzi_Recipe_Roasted_Eggplant_with_Fenugreek_Leaves-9.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/687.Baingan_Bharta_with_Methi_Sabzi_Recipe_Roasted_Eggplant_with_Fenugreek_Leaves-9.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vendakkai Vengayam Sambar Recipe (Okra in Tangy Lentil Curry)', 'vendakkai-vengayam-sambar-recipe-okra-in-tangy-lentil-curry', 'The Vendakkai Vengayam Sambar Recipe is a simple and quick method of making sambar that is packed with flavors from the okra (bhindi) and the most important ingredient, the homemade sambar powder.  The Vendakkai (okra) when cooked along with the tamarind water and sambar powder, absorbs the spices so well, that it imparts a delicious taste to the sambar. Serve the Vendakkai Vengayam Sambar along with Steamed Rice, topped with Ghee and Potato Roast', '["1 cup Arhar dal (Split Toor Dal)", "1 cup Tamarind , freshly squeezed", "1 cup Shallot , peeled", "10 Bhindi (Lady Finger/Okra) , cut into 1 inch pieces", "2 Tomatoes , quartered", "1 tablespoon Sambar Powder", "Salt , to taste", "Ingredients for the Seasoning", "1 teaspoon Sesame (Gingelly) Oil , or vegetable oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies", "1/4 teaspoon Asafoetida (hing)", "6 Curry leaves", "3 sprig Coriander (Dhania) Leaves"]'::jsonb, ARRAY['tomato', 'salt', 'tamarind squeezed', 'arhar dal (split toor dal)', 'mustard seeds', 'asafoetida (hing)', 'curry leaves', 'coriander (dhania) leaves', 'dry red chillies', 'bhindi (lady fingerokra)', 'sesame (gingelly) oil vegetable oil', 'sambar powder']::text[], '["To begin making the Vendakkai Vengayam Sambar Recipe, first cook the toor dal along with 2 cups of water and keep aside.", "Click to see how to cook dal in a pressure cooker.", "Once the dal is cooked, whisk the dal well and keep it aside.The next step is to cook the tangy sambar curry.", "Into the pressure cooker, add the tamarind water, a tablespoon of sambar powder, 10 to 12 pearl onions, the Vendakkai and tomatoes.Finally add salt to taste.", "Close the pressure cooker, place the weight on and allow it to cook until you hear two whistles.", "After the two whistles allow the pressure to release naturally.While the pressure is getting released we will prepare the seasoning for the sambar.In a small pan; add a teaspoon of sesame oil and allow it to heat.", "Once the oil is heated up, add the mustard seeds, the dry red chilies and allow it to roast until lightly browned.", "Add the asafoetida powder, stir it in and turn off the heat.Once the pressure is released completely, open the cooker.", "Add in the cooked lentils and stir well until it gets well combined into the tamarind vegetable curry.", "Next add in the prepared seasoning to the Vendakkai sambar and stir.Turn the heat on to high and bring the sambar to a boil.", "Allow it to boil for 3 to 4 minutes.", "Finally, stir in the chopped coriander leaves and stir.", "Turn off the heat.Serve the\u00a0Vendakkai Vengayam Sambar along with\u00a0Steamed Rice, topped with\u00a0Ghee\u00a0and\u00a0Potato Roast."]'::jsonb, 55, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Vendakkai_Vengayam_Sambar_Recipe_Okra_Lentil_Tangy_Curry-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/688.Vendakkai_Vengayam_Sambar_Recipe_Okra_Lentil_Tangy_Curry-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Patoli Recipe (Dal Usli/ Crumbled Dal Recipe)', 'andhra-style-patoli-recipe-dal-usli-crumbled-dal-recipe', 'Andhra Style Patoli Recipe (Dal Usli/ Crumbled Dal Recipe) is a dish made from chana dal that is ground to a paste and stir fried with crispy onions and fresh coriander leaves. You can also add extra vegetables like capsicums, carrot to add up to your crunch. The dish very tasty as it is and can also accompanied with rotis of phulkas.', '["To Grind", "1 cup Chana dal (Bengal Gram Dal) , soaked in hot water for 30 minutes", "1 Green Chilli", "To Temper", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves", "1 pinch Asafoetida (hing)", "1 Onion , chopped", "1 teaspoon Ginger Garlic Paste", "1 tablespoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Oil , for cooking"]'::jsonb, ARRAY['salt', 'green chilli', 'mustard seeds', 'asafoetida (hing)', 'red chilli powder', 'ginger garlic paste', 'curry leaves', 'white urad dal (split)', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making the Andhra Style Patoli Recipe grind the soaked chana dal with green chilli in a mixer, add little water and grind it to a thick paste.Heat a kadai with oil, add mustard seeds, cumin seeds, urad dal and splutter for few seconds.", "Add curry leaves and leave it to crackle for 2 seconds.Add the chopped onions, ginger garlic paste and saute till the onions turn translucent.Add the ground chana paste and keep mixing it.", "Add turmeric powder and red chilli powder and by using a wooden spatula try to separate the dal and create a crumbly texture.", "Add salt and check for seasoning.Serve the Andhra Style Patoli Recipe with\u00a0Mamsaam Chops Recipe, phulka and\u00a0Steamed rice\u00a0by the side."]'::jsonb, 90, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Andhra_Style_Patoli_Recipe_Dal_Usli_Crumbled_Dal_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/689.Andhra_Style_Patoli_Recipe_Dal_Usli_Crumbled_Dal_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karatyacho Fodi Recipe - Pan Fried Bitter Gourd', 'karatyacho-fodi-recipe-pan-fried-bitter-gourd', 'Shallow fried bitter gourd, also called as Karatyachyo Fodi in Goa is one of the most easy and healthy recipe. These are prepared by shallow frying the bitter gourd pieces using spices until they are nice and crisp and served with any vegetarian Thali.', '["2 Karela (Bitter Gourd/ Pavakkai)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "2 Tablespoons Sooji (Semolina/ Rava)", "Salt , to taste", "2 Tablespoons Extra Virgin Olive Oil , or any cooking oil"]'::jsonb, ARRAY['salt', 'karela (bitter gourd pavakkai)', 'red chilli powder', 'sooji (semolina rava)', 'turmeric powder', 'virgin olive oil oil']::text[], '["To begin making the Karatyacho Fodi recipe, wash bitter gourd well using water and scrape away the top bumpy skin with a peeler.", "Make them really smooth.If bitter gourds are big then cut them horizontally into 3 pieces otherwise cut them into 2.", "Cut each piece vertically into 2 pieces and give slits to each piece as shown below .Sprinkle some salt over these pieces, about 1/2 tablespoon.", "Massage well and keep them aside for about 20 minutes, and after 20 minutes, drain out all the bitter juice.In a plate, mix together red chili powder, turmeric powder and semolina.Heat a skillet and drizzle some oil (about 1 to 2 tablespoons).", "Nicely coat each Karela piece with this mixture and place them over heated skillet.Drizzle little more oil over the pieces and let them fry on medium heat till they are nice and crisp on one side.", "Flip them over and fry on the other side till crisp.Once they are well fried and look dark brown and crisp, remove them out and enjoy with Indian vegetarian Thali.Serve\u00a0Karatyacho Fodi along with\u00a0Goan Style Mushroom Vindaloo\u00a0and\u00a0Steamed Rice\u00a0for a weekday meal."]'::jsonb, 35, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/Karatyacho_Fodi_Pan_Fried_Bitter_Gourd_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/690.Karatyacho_Fodi_Pan_Fried_Bitter_Gourd_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ringan Methi Nu Shaak Recipe - Gujarati Style Eggplant & Fenugreek Leaves Sabzi', 'ringan-methi-nu-shaak-recipe-gujarati-style-eggplant-fenugreek-leaves-sabzi', 'Ringan Methi Nu Shaak Recipe is a Gujarati style eggplants cooked with fresh fenugreek leaves. Here the eggplants along with fenugreek leaves are mildly flavoured with the regular spices - red chilli, turmeric, coriander, cumin powder and finished with a bit of jaggery and amchur, which lends the dish a slight sweetness and tanginess. The subzi is spicy, sweet and tangy making it perfect to be had with hot phulkas.', '["15 Small Brinjal (Baingan / Eggplant) , cut into long strips", "2 cups Methi Leaves (Fenugreek Leaves) , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "2 teaspoons Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "2 teaspoons Jaggery , powdered", "2 teaspoon Amchur (Dry Mango Powder)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 tablespoon Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'amchur (dry mango powder)', 'mustard seeds', 'brinjal (baingan eggsplant)', 'methi leaves (fenugreek leaves)', 'jaggery', 'red chilli powder', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Ringan Methi Nu Shaak Recipe (Gujarati Style Eggplant and Fenugreek Leaves Sabzi), wash and cut the brinjals into long strips and keep them immersed in a bowl of salted water to avoid discolouration.Heat oil in a heavy bottomed pan on medium flame, add in the mustard seeds, cumin seeds and let it crackle.Drain the eggplants from water and add it to the pan.Season with little salt, mix well and let the eggplants cook in its own water until its half cooked.", "This will take around 5 minutes.", "Now, add in the fenugreek leaves and saute for a minute.Cover the pan and allow the brinjal and methi to completely cook through.", "Add the turmeric, cumin, coriander, red chilli powder and mix well.", "Saute the vegetables occasionally and let the water dry out completely.Add the jaggery, amchur powder to\u00a0Ringan Methi Nu Shaak and mix well.", "Once the vegetables comes together, switch off the heat.Serve this\u00a0Ringan Methi Nu Shaak Recipe (Gujarati Style Eggplant and Fenugreek Leaves Sabzi) along with\u00a0Phulkas,\u00a0Gujarati Dal\u00a0and\u00a0Kachumber Salad\u00a0for a delicious weekday lunch."]'::jsonb, 25, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Ringan_Methi_Nu_Shaak_Recipe_Gujarati_Style_Eggplant_and_Fenugreek_Leaves_Sabzi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/691.Ringan_Methi_Nu_Shaak_Recipe_Gujarati_Style_Eggplant_and_Fenugreek_Leaves_Sabzi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mudaliar Style Omelette Curry Recipe', 'mudaliar-style-omelette-curry-recipe', 'Mudaliar Style Omelette Curry Recipe is recipe that has been originated from vellara Christian community which is one of the cuisines of Tamil Nadu. The usual egg curry is made by adding the whole boiled egg in the curry and simmered. But in this recipe, we use the egg as an omelette which is made separately to a thin layer and then simmered in a thick and luscious curry which consists of three different base.', '["2 Whole Eggs", "1 Onion , finely chopped", "1 Green Chilli , finely chopped", "1 sprig Coriander (Dhania) Leaves", "Salt , to taste", "1 Onion , chopped", "2 Green Chillies", "1 tablespoon Coriander (Dhania) Seeds", "2 tablespoon Whole Black Peppercorns", "1 inch Ginger", "4 cloves Garlic", "5 sprig Coriander (Dhania) Leaves", "2 sprig Mint Leaves (Pudina)", "1 Tomato", "2 tablespoon Fresh coconut , grated", "1 tablespoon Poppy seeds", "1/2 cup Hung Curd (Greek Yogurt)", "1 tablespoon Turmeric powder (Haldi)", "Salt , as per taste", "2 tablespoon Oil", "1 Cinnamon Stick (Dalchini)", "1 Cardamom (Elaichi) Pods/Seeds", "2 sprig Curry leaves", "1 Onion , chopped", "1 sprig Coriander (Dhania) Leaves , for garnish"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'hung curd (greek yogurt)', 'green chilli', 'coconut', 'cardamom (elaichi) podsseeds', 'mint leaves (pudina)', 'black peppercorns', 'cloves garlic', 'curry leaves', 'coriander (dhania) leaves', 'coriander (dhania) seeds', 'onion', 'poppy seeds', 'cinnamon stick (dalchini)', 'eggs', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["We begin making the Mudaliar Style Omelette Curry Recipe by breaking the eggs and whisking it with onions, coriander leaves, green chillies and salt.Heat an omellete pan with oil and pour the egg mixture when it is hot, flip it over and cook on the other side as well.", "Fold the omelette and cut them into strips.Now grind the ingredients for onion paste into a smooth paste and keep it aside.Next grind the coconut and poppy seeds into a smooth paste and keep it aside as well.Heat a kadai with oil, temper the cloves, cinnamon stick, cardamom and curry leaves till the aroma is released.Next add the onions and fry for few minutes till it turns golden brown.", "Now slowly add in your onion paste mixture and fry them till the raw smell of the masala goes away.Once done add in the coconut mixture and fry again for about 20 minutes.Next you can add in the yogurt whipped with turmeric powder and salt and slow add and mix well.", "You can add some water at this stage and leave it to boil.", "Boil for another 20 minutes.Pour the curry over the omelette and garnish with few coriander leaves.", "Serve the Mudaliar Style Omelette Curry Recipe with\u00a0whole wheat Malabar parotta\u00a0or simply with\u00a0Phulka Recipe (Roti/Chapati) - Puffed Indian Bread\u00a0and\u00a0Carrot and Beans Thoran (Subzi Recipe)\u00a0to complete your Sunday meal."]'::jsonb, 60, 'Tamil Nadu', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Mudaliar_Style_Omelette_Curry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/692.Mudaliar_Style_Omelette_Curry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Mutton Pepper Fry Recipe', 'kerala-style-mutton-pepper-fry-recipe', 'A simple delicious fry recipe with mutton that goes beautifully with rotis, rice and dal, or even dosas is this kerala mutton pepper fry. The pungency from black pepper corns goes very well with meat dishes especially mutton. Indian food is known for its spice levels and Kerala been the land of spices uses a lot of peppercorns in their dishes. Coconut oil is highly recommended for this dish.', '["400 grams Mutton", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Salt", "2 teaspoon Lemon juice", "1 Onion , finely chopped", "5 cloves Garlic , finely chopped", "1 inch Ginger , thin slices", "10 Curry leaves", "4 tablespoon Black pepper powder", "2 teaspoon Fresh coconut , (1/2 inch size)", "3/4 teaspoon Salt", "1/4 cup Water", "2 tablespoons Coconut Oil"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'ginger', 'red chilli powder', 'cloves garlic', 'water', 'curry leaves', 'onion', 'mutton', 'lemon', 'coconut ( size)', 'black pepper powder', 'coconut oil', 'coriander powder', 'turmeric powder']::text[], '["To begin making the Kerala Style Mutton Pepper Fry recipe, wash mutton pieces well and marinate it with all the spices mentioned in the list.Heat coconut oil in a pan.", "Add garlic and ginger pieces.", "Fry for 1 minute.Add finely chopped onions and curry leaves.", "Cook till onions turn soft.Add marinated mutton and 3/4 teaspoon salt.Add pepper powder, coconut pieces, mix well.", "Continue to cook for 4 minutes.Add 2 cups water and mix well.", "Cover and let it cook until mutton gets cooked well and water is fully evaporated.", "Kerala style mutton sukka/fry is ready.Kerala Style Mutton Pepper Fry as a side dish along with\u00a0Kerala Varutharacha Mutton Curry\u00a0and\u00a0Steamed Rice\u00a0for a weekday dinner with family."]'::jsonb, 70, 'Kerala', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/Kerala_Mutton_Pepper_Fry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/693.Kerala_Mutton_Pepper_Fry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karwar Style Bibya Usal Recipe (Spiced Cashew Nut Sabzi)', 'karwar-style-bibya-usal-recipe-spiced-cashew-nut-sabzi', 'Karwar Style Bibya Usal Recipe (Spiced Cashew Nut Sabzi) is the Konkan and Karwar style cashew sabzi. A customary side dish, in any function or festival in Konkani cuisine. Fresh, tender cashews are sautéed along with few spices to make this tasty and simple stir fry.', '["1/2 cup Cashew nuts , soaked in warm water and salt for 15 minutes", "3 tablespoons Fresh coconut , grated", "1 teaspoon Sugar", "Salt , to taste", "2 teaspoons Coconut Oil", "1 teaspoon White Urad Dal (Split)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "3 Dry Red Chillies , broken (adjust to taste)", "4 cloves Garlic , crushed", "1/4 teaspoon Turmeric powder (Haldi)", "Curry leaves , a few"]'::jsonb, ARRAY['salt', 'cashew nuts water salt', 'coconut', 'mustard seeds', 'cloves garlic', 'curry leaves', 'sugar', 'white urad dal (split)', 'dry red chillies', 'turmeric powder', 'coconut oil']::text[], '["To begin making the Karwar Style Bibya Usal Recipe (Spiced Cashew Nut Sabzi), soak the cashews in warm water and a little salt for about 10 minutes.Heat oil in a heavy bottomed pan.", "Once the oil is hot, add the mustard seeds and let them splutter.As the mustard splutters, add split black gram and fry till them till it turns golden brown.Break in the dry red chillies into half into the kadai and add curry leaves along with crushed garlicAfter a few seconds of frying them, add the cashew nuts and turmeric.", "Toss cashews to mix with the tempering.", "Keep saut\u00e9ing for a couple of minutes on medium heat.Add salt, sugar and about 1/4 cup of water and mix everything well.", "Now cover and cook in low heat for 5 to 10 minutes.", "Cashew nuts should be soft but slightly crunchy.Add grated coconut and allow all the water to dry up with stirring.", "Check for salt and adjust spices if needed, allow to sit for a minute and switch off.Serve\u00a0Karwar Style Bibya Usal Recipe (Spiced Cashew Nut Sabzi) along with\u00a0Karwar Style Muga Ambat\u00a0and\u00a0Phulkas\u00a0for a weekday meal."]'::jsonb, 15, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/Bibya_Usal_Karwar_Spiced_Cashew_nut_Sabzi_dry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/694.Bibya_Usal_Karwar_Spiced_Cashew_nut_Sabzi_dry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Masala Couscous Pulao Recipe', 'masala-couscous-pulao-recipe', 'Couscous is a staple of North African cuisine and is a dish of steamed balls of semolina usually served with stew on top. Traditional couscous is prepared with semolina, but in recent days, it is prepared with wheat and barley. Coarsely ground wheat is moistened, rolled into small balls and dusted off with wheat flour.', '["400 grams Couscous", "1 Onion , thinly sliced", "1 tablespoon Ginger Garlic Paste", "1/2 cup Carrots (Gajjar) , chopped", "1/2 cup Green peas (Matar)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "Mint Leaves (Pudina) , few", "1 Bay leaf (tej patta)", "3 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "Oil , as required", "Salt , to taste", "Coriander (Dhania) Leaves , few to garnish, chopped"]'::jsonb, ARRAY['salt', 'mint leaves (pudina)', 'bay leaf (tej patta)', 'coriander (dhania) leaves', 'green peas (matar)', 'red chilli powder', 'carrot', 'ginger garlic paste', 'onion', 'cinnamon stick (dalchini)', 'coriander powder', 'couscous', 'cloves (laung)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Masala Couscous Pulao recipe, firstly heat oil in a heavy bottomed pan.", "Add cinnamon stick, cloves and bay leaf and saute for atleast 30 seconds.Add sliced onions and cook until they become soft and transparent.Add ginger garlic paste and saute for 2 minutes.", "Add vegetables, red chili powder, coriander powder, garam masala powder, salt and saute for 5 minutes more.Add 4 cups of water and allow the mixture to boil.", "One the water starts boiling, add mint leaves and couscous.Simmer the flame and cook until the water is completely absorbed\u00a0If couscous is not yet cooked, add a cup of hot water.Garnish with chopped coriander and it is ready to be served.Serve\u00a0Masala Couscous Pulao\u00a0with\u00a0Beetroot Raita,\u00a0Lauki Raita\u00a0or any other raita of your choice.", "A roasted papad will add a crunch to this meal."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Masala_Couscous_Pulao.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/695.Masala_Couscous_Pulao.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Puli Keerai Recipe (Tamarind Spinach Curry)', 'puli-keerai-recipe-tamarind-spinach-curry', 'Puli Keerai is a traditional South Indian Recipe that serves a main course. It is more like a sambar or rasam that goes well with rice. Puli Keerai is a simple recipe that doesn’t need any special ingredient. The spinach that is used gives good amount of iron to the body. This can be packed even for lunch. Puli Keerai is a quick dish that can be prepared in minimum time on a busy day.', '["200 grams Spinach Leaves (Palak)", "Tamarind , half lemon size", "Sugar , a pinch", "4 Green Chillies", "Salt , as required", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Chana dal (Bengal Gram Dal)", "2 sprig Curry leaves", "2 Dry Red Chillies"]'::jsonb, ARRAY['salt', 'sunflower oil', 'chana dal (bengal gram dal)', 'mustard seeds', 'spinach leaves (palak)', 'curry leaves', 'sugar', 'dry red chillies', 'green chillies', 'tamarind lemon']::text[], '["To begin with the Puli Keerai Recipe first, separate the spinach leaves from the stem and clean them in cold running water.Now place the pressure cooker on medium flame and add the clean spinach, chilies, salt as per your taste and a pinch of sugar and give it a stir.Now add tamarind and some water.", "Don''t add so much water as spinach tend to loose water as they get cooked.Leave them to cook for about 10 minutes.", "After the spinach is cooked remove it from the cooker and keep it aside.Take a blender and pour the spinach mixture and blend it to a smooth paste.Transfer it to a bowl once done.Now in another kadai add some oil and let it heat, now add mustard seeds and wait till they splutter.After mustard seeds splutter add chana dal and wait till it is roasted and turns brown.Now add the mustard seeds and chana dal to the spinach mixture and give it a stir.Taste the Puli Keerai and check for the salt and spice and adjust it according to your taste.Your Puli Keerai recipe ready to be served and you can serve them with white rice and Vendakkai Poriyal."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Puli_Keerai.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/696.Puli_Keerai.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Methi Malai Paneer Recipe', 'methi-malai-paneer-recipe', 'Methi Malai Paneer Recipe is a famous North Indian dish that is very common in restaurants, parties, and get-togethers. It is a very tasty, aromatic yet easy to make recipe. Bursting with flavors of fresh methi leaves this creamy gravy tastes just awesome. This recipe will win everybody''s heart at the dining table and we are sure you will make it again and again.', '["1 cup Methi Leaves (Fenugreek Leaves) , chopped", "100 grams Paneer (Homemade Cottage Cheese) , diced", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "1/2 cup Milk", "2 tablespoon Fresh cream", "1 tablespoon Butter (Salted) , or ghee/oil", "1/2 teaspoon Cumin seeds (Jeera)", "1 Bay leaf (tej patta)", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "1/2 teaspoon Garam masala powder", "2 Onions , sliced", "4 cloves Garlic", "2 Tomatoes", "2 Green Chillies", "10 Cashew nuts , soaked in water"]'::jsonb, ARRAY['methi leaves', 'fenugreek leaves', 's paneer', 'homemade cottage cheese', 'kasuri methi', 'dried fenugreek leaves', 'milk', 'fresh cream', 'butter', 'salted', 'cumin seeds', 'jeera', 'bay leaf', 'tej patta', 'red chilli powder', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'salt', 'garam masala powder', 'onions', 's garlic', 'tomatoes', 'reen chillies', 'cashew nuts']::text[], '["To begin making the Methi Malai Paneer Recipe, soak cashews in warm water for 15 to 20 minutes.", "Keep it aside.Heat oil in a heavy bottomed pan.", "Add fenugreek leaves with little salt and cook till the raw smell evaporates.", "To the same heavy bottomed pan, add 1 teaspoon of oil and add sliced onion, ginger, garlic and green chillies.", "Saute till raw smell goes.", "Add diced tomatoes and salt.", "Saute till tomatoes are mushy.", "Once onion\u00a0tomato mixture has cooled, grind it very smooth along with soaked cashews.", "Our masala for methi malai paneer is ready.Add remaining oil in a heavy bottomed pan.", "Add bay leaf, cumin seeds and let it cook\u00a0for about 15 seconds.After 15 seconds, add ground onion tomato paste and cook for about 2 to 4 minutes.Add turmeric powder, red chilli powder, coriander powder, kasuri methi and salt.", "Saute well.", "Add sauteed methi leaves, diced paneer, milk and required water to get the desired consistency.", "Mix everything well and keep it covered.", "Stir in between.", "When the curry is boiling well, add malai and garam masala powder and let it cook for another 1 minute.", "Mix Methi Malai Paneer and switch off.Serve\u00a0Methi Malai Paneer Recipe along with\u00a0Whole Wheat Lachha Paratha,\u00a0Burani Raita\u00a0and\u00a0Kachumber Salad\u00a0for a weekday meal."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/Methi_Malai_Paneer_recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/697.Methi_Malai_Paneer_recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Batata Saragva Nu Shaak Recipe-Spicy Aloo & Drumstick Vegetable', 'batata-saragva-nu-shaak-recipe-spicy-aloo-drumstick-vegetable', 'Batata Saragva Nu Shaak is made with a combination of fried potatoes and steamed drumsticks cooked in an onion and tomato gravy.This one was one of my childhood favorite dishes and I especially love it for french fried potatoes that make it special and tempting for everyone in the family.', '["3 Potatoes (Aloo) , chopped", "3 Drumstick , cut into 1 inch size pieces", "1 inch Ginger , grated", "3 Tomatoes , finely choppe", "1 inch Cinnamon Stick (Dalchini)", "2 Bay leaves (tej patta)", "1/4 teaspoon Asafoetida (hing)", "1/2 teaspoon Red Chilli powder , adjustable", "2 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Coriander (Dhania) Leaves , required for garnishing"]'::jsonb, ARRAY['potatoes', 'aloo', 'drumstick', 'ginger', 'tomatoes', 'cinnamon stick', 'dalchini', 'bay leaves', 'tej patta', 'asafoetida', 'hing', 'red chilli powder', 'coriander powder', 'dhania', 'turmeric powder', 'haldi', 'salt', 'coriander']::text[], '["To make Batata Saragva Nu Shaak, you will have to first boil your potatoes and steam the drumsticks and keep aside.", "Cut them into the desired sizes.Place the halved potatoes and drumsticks into a pressure cooker, add 1/4 cup of water.", "Cover the cooker, place the weight on and pressure cook until you heat three whistles.", "After three whistles turn off the heat.", "Allow the pressure to release naturally.", "Once the pressure has released, open the cooker, peel the skin of the potatoes and dice them.", "Once you have the potatoes and drumsticks cooked, the next step is to make the masala.Heat a teaspoon of oil in a heavy bottomed pan; add the ginger, cinnamon and bay leaves.", "Stir fry for a few seconds.", "Add the tomatoes, turmeric powder, coriander powder, red chilli powder and asafoetida and saute until the tomatoes get cooked through and soft.", "Once the tomatoes have cooked through, add the boiled potatoes and drumsticks into the masala.", "Add the salt and stir well to combine.", "Turn the heat to low and simmer the Batata Sargvo Nu Shaak for about 3 to 4 minutes so the vegetables absorb all the masala.Once done, check the salt and spice levels and adjust to suit your taste.", "Stir in the chopped coriander leaves and serve.Serve the Batata\u00a0Saragva\u00a0Nu Shaak along with an."]'::jsonb, 55, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Gujarati_Batata_Sargvo_Nu_Shaak_Potato_Drumstick_Sabzi-14.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/698.Gujarati_Batata_Sargvo_Nu_Shaak_Potato_Drumstick_Sabzi-14.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Jain Style Dal Makhani Recipe', 'jain-style-dal-makhani-recipe', 'Dal Makhani is a very popular recipe, which everyone loves. Its rich, creamy, spicy and delicious. Here, we have a Jain version of it, without the use of onion and garlic. Its simple to cook and the addition of dry ginger powder gives it a beautiful flavour. This is an ideal recipe that you can make during the fasting days.', '["3/4 cup Black Urad Dal (Whole)", "1/4 cup Rajma (Large Kidney Beans)", "1 teaspoon Cumin seeds (Jeera)", "1 inch Cinnamon Stick (Dalchini)", "3 Cloves (Laung)", "2 Black cardamom (Badi Elaichi)", "2 Tomatoes , pureed", "1 Green Chilli , finely chopped", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "2 teaspoon Dry ginger powder", "2 tablespoons Ghee", "1 cup Milk , low fat (optional)", "Salt , to taste", "To garnish", "1 inch Ginger , cut to julienne (optional)", "2 tablespoons Fresh cream"]'::jsonb, ARRAY['tomato', 'black cardamom (badi elaichi)', 'salt', 'green chilli', 'ghee', 'milk', 'red chilli powder', 'dry ginger powder', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'rajma (large kidney beans)', 'ginger julienne', 'black urad dal', 'cloves (laung)', 'garam masala powder']::text[], '["To begin making the Jain Style Dal Makhani Recipe, wash and soak the whole urad dal and rajma overnight.Pressure cook the soaked dals in 2 to 3 cups of water for 4 to 5 whistles and simmer for 10 minutes; slightly mash the dals and keep aside.In the meantime, puree the tomatoes using a mixer grinder and keep aside.Heat ghee in a wok/kadhai on medium flame, add the cinnamon stick, cloves, black cardamom and let it release its aroma into the ghee.Add the cumin seeds and let it crackle.Once the cumin seeds have crackled add the tomato puree, green chillies and cook for 2 minutes.Once the tomatoes have cooked add the spice powders including red chilli, garam masala, dry ginger powder and cook until the ghee floats on top.Now, add the cooked dals, season with salt, add water to your desired consistency and simmer for 10 to 15 minutes.At this stage you can even add the milk and let the dal boil.Once the Dal Makhani reaches your desired consistency, switch off the flame.", "Transfer\u00a0Dal Makhani to a serving bowl and garnish with ginger julienne and cream.", "Serve the Jain Style Dal Makhani recipe along with\u00a0tawa parathas\u00a0and\u00a0kachumber salad\u00a0for the weeknight dinner."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/27-june/Jain_Style_Dal_Makhini_Recipe_no_onion_and_no_garlic-7215.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/699.Jain_Style_Dal_Makhini_Recipe_no_onion_and_no_garlic-7215.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rava Fried Prawns Recipe', 'rava-fried-prawns-recipe', 'Rava Fried Prawns is a traditional Goan dish. In Goa, we make different kinds of rava fried dishes to have as an accompaniment with rice and fish curry. No Goan thali is complete without rava fried delicacies. Prawns are a good source of protein and calcium and is a good source of vitamin A and E. They also contain zinc which maintains the immune system. However, anything in excess is not good. Rava fried prawns or tiger prawns tastes yum and can be served as starters for parties.', '["20 Prawns", "1 teaspoon Turmeric powder (Haldi)", "1 tablespoon Red Chilli powder", "Salt , to taste", "1/2 cup Sooji (Semolina/ Rava)", "1/4 cup Rice flour", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Red Chilli powder", "Salt , a pinch", "4 tablespoons Oil"]'::jsonb, ARRAY['salt', 'red chilli powder', 'sooji (semolina rava)', 'rice flour', 'turmeric powder', 'prawns', 'sunflower oil']::text[], '["To begin making the Rava Fried Prawns Recipe, de-shell the prawns, remove the vein and wash properly.Marinate the prawns for 30 minutes with\u00a0 salt, turmeric powder and chili powder.Take a plate and add the rice flour, rawa, pinch of salt, 1/4 teaspoon of turmeric powder and chili powder.", "Mix well to combine.Coat the marinated prawns in the rava and rice flour mix.", "Ensure that it is fully coated.Heat a\u00a0pan and spread 1 tablespoon oil.", "Add more if required.Place the rava coated prawns on the pan and fry on low flame.", "After 10 minutes turn them to the other side.Fry them for 20 minutes.You know they are done when they turn golden brown on the outside.Always fry prawns on low heat and do not cover it while frying.", "Once done transfer the Rava Fried Prawns onto a serving plate and serve.Serve\u00a0Rava Fried Prawns Recipe\u00a0with\u00a0Goan Bimbla Uddamethi Recipe\u00a0and\u00a0Steamed Rice Recipe\u00a0for a perfect Goan meal."]'::jsonb, 30, 'Goan', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Rava_Fried_Prawns.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/700.Rava_Fried_Prawns.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chicken Chops Recipe', 'chicken-chops-recipe', 'Chicken Chops belong to cutlet family. This chicken chops recipe is the simplest chicken recipe. These chops are perfect finger food for parties.', '["300 grams Chicken , minced", "1 Onion , finely chopped", "2 Green Chillies , finely chopped", "1 Whole Eggs", "1 teaspoon Ginger Garlic Paste", "2 tablespoon Coriander (Dhania) Leaves , finely chopped", "1 tablespoon Mint Leaves (Pudina) , finely chopped", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "1 teaspoon Lemon juice", "Oil , for deep frying", "Whole Wheat Bread crumbs , for coating"]'::jsonb, ARRAY['salt', 'coriander powder', 'coriander (dhania) leaves', 'red chilli powder', 'ginger garlic paste', 'onion', 'chicken', 'lemon', 'wheat bread crumbs', 'mint leaves (pudina)', 'eggs', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Chicken Chops recipe,In a mixing bowl, combine\u00a0minced chicken,\u00a0onion,\u00a0green chilies,\u00a0egg,\u00a0ginger garlic paste,\u00a0coriander and mint leaves, red chili powder,\u00a0turmeric powder,\u00a0coriander powder, salt\u00a0 and\u00a0lemon juice, use your hands and bring the entire mixture together.", "Keep the chicken chop mixture covered for about 15 minutes in fridge.Meanwhile, heat oil in a deep fry pan for deep frying the chicken chops.", "Make small lemon sized balls from the minced chicken chop mixture and shape them into oblong or cylindrical shapes.Next, carefully roll the Chicken Chops in bread crumbs.When the oil turns piping hot, reduce the flame to medium and carefully transfer the coated chops into oil.", "Deep fry the chicken chops for about a minute or until all the sides turn golden brown.Drain the chicken chops on kitchen towel and repeat the same process for the remaining mix.Serve these delicious crunchy outside, soft inside\u00a0Chicken Chops Recipe\u00a0immediately with\u00a0Raw Mango and Spring Onion dip\u00a0as a party appetizers or enjoy it while watching a movie."]'::jsonb, 35, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Chicken_Chops.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/701.Chicken_Chops.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Shimla Mirchi Panchamrut Recipe | Konkani Capsicum Cashew Peanut Sabzi', 'shimla-mirchi-panchamrut-recipe-konkani-capsicum-cashew-peanut-sabzi', 'Shimla Mirchi Panchamrut is a Konkani dish which is made from pan roasted capsicum, along with cashew nuts and steamed peanuts that is cooked along with freshly roasted and ground spices along with tamarind and jaggery. It has a spicy, sweet and nutty taste and flavour making it a refreshing dish.', '["2 Green Bell Pepper (Capsicum) , diced small", "1/2 cup Raw Peanuts (Moongphali)", "1/4 cup Cashew nuts , broken", "1 tablespoon Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1/4 teaspoon Asafoetida (hing)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Jaggery", "4 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini) , broken", "1 tablespoon Coriander (Dhania) Seeds", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Whole Black Pepper Corns", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1/4 cup Fresh coconut", "2 tablespoons Roasted Peanuts (Moongphali) , shelled", "20 grams Tamarind"]'::jsonb, ARRAY['cashew nuts', 'mustard seeds', 'asafoetida (hing)', 'black pepper corns', 'coconut', 'jaggery', 'red chilli powder', 'peanuts (moongphali) shelled', 'coriander (dhania) seeds', 'cinnamon stick (dalchini)', 'methi seeds (fenugreek seeds)', 'peanuts (moongphali)', 'cumin seeds (jeera)', 'green bell pepper (capsicum)', 'tamarind', 'coconut oil', 'cloves (laung)', 'turmeric powder']::text[], '["To begin making Shimla Mirchi Panchamrut Recipe, first prep all the ingredients and keep them ready.The first step is to make the masala.Heat a small pan over medium heat; add the cloves, cinnamon, black pepper, coriander seeds, cumin seeds, methi seeds and roast for a minute until the aromas of the spices come through.Once roasted, add the grated coconut and roast for a minute more and turn off the heat.", "Allow the mixture to cool a bit.Add the roasted masala into a small jar of the mixer grinder along with the peanuts and tamarind.Blend to make a powder without adding any water.", "This fresh masala will go over the cooked capsicum mixture.", "Keep this aside.Into a pressure cooked, add the raw peanuts along with 1/4 cup of water and pressure cook for 2 whistles.", "After 2 whistles turn the heat to low and simmer for 3 to 4 minutes and turn off the heat.Allow the pressure to release naturally.", "Once released, open the cooker and keep the cooked peanuts aside.", "Heat coconut oil in a pan; add the mustard seeds and methi seeds and allow it to crackle.Once it crackles, add the asafoetida and give it a stir.Next add the cashew nuts and capsicum and sprinkle a little salt and turmeric powder.", "Give the mixture a stir.Cover the pan and cook the capsicum until it is just about cooked.", "Take care not to overcook the capsicum and ensure it has a firm texture and is also cooked with a good bite.Once the capsicum has reached that stage, stir in the freshly roasted and ground masala, jaggery and the cooked peanuts into the cashew and capsicum mixture.Give it a stir until all the ingredients are well combined.", "Check the taste and add more salt if required and stir.Cover the pan and simmer the\u00a0Shimla Mirchi Panchamrut for another 3 to 4 minutes so the masalas get well absorbed making the sabzi flavourful and tasty.Once done, turn off the heat and transfer the\u00a0Shimla Mirchi Panchamrut to a serving bowl and serve hot.Serve the delicious\u00a0Shimla Mirchi Panchamrut\u00a0with\u00a0Muga Ambat Recipe\u00a0, hot rice and phulka for a wholesome meal."]'::jsonb, 40, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Shimla_Mirchi_Panchamrut_Recipe_Konkan_Capsicum_Cashewnut_Sabzi_With_Peanuts__5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/702.Shimla_Mirchi_Panchamrut_Recipe_Konkan_Capsicum_Cashewnut_Sabzi_With_Peanuts__5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dahi Achari Bhindi Recipe', 'dahi-achari-bhindi-recipe', 'Dahi Achari Bhindi Recipe a delicious combination of Bhindi with Achari flavors cooked in yogurt curry, makes for a excellent combination. The bhindi is sautéed till it is crispy and then tossed along with caramelized onions, freshly ground achari masala and then slowly cooked in thick yogurt.', '["500 grams Bhindi (Lady Finger/Okra) , cut small", "1 Onion , chopped", "1 Tomato , chopped", "1 inch Ginger , chopped", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 cup Curd (Dahi / Yogurt)", "1 tablespoon Gram flour (besan)", "Achari Masala", "1 teaspoon Fennel seeds (Saunf)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Kalonji (Onion Nigella Seeds)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Ajwain (Carom seeds)"]'::jsonb, ARRAY['tomato', 'ginger', 'kalonji (onion nigella seeds)', 'mustard seeds', 'fennel seeds (saunf)', 'ajwain (carom seeds)', 'red chilli powder', 'gram flour (besan)', 'curd', 'onion', 'cumin seeds (jeera)', 'bhindi (lady fingerokra)', 'coriander powder', 'turmeric powder']::text[], '["To begin making the Dahi Achari Bhindi Recipe, we will first make the achari masala.To prepare the marinade for Achari masala, in a pan add mustard seeds, cumin seeds, fennel seeds, kalonji seeds, carom seeds, fenugreek seeds and dry red chilies.Dry roast the spices and chilies over medium heat till fragrant and slightly browned.", "Turn off the heat.", "Transfer spices to the jar of mixer and grind into a coarse powder.", "Keep the achari powder aside.Wash and clean the Bhindi.", "Wipe the bhindi with a paper towel or a kitchen towel until bhindi is dry.", "This is done in order to ensure bhindi does not get mushy while cooking.", "Chop them into small pieces and keep aside.", "Heat oil in a wok and add the chopped bhindi and sprinkle a little salt and saute till they become soft and charred on the outside.Take the Bhindi out and keep it separate.", "Into the same wok add a teaspoon of oil and add chopped onions and saute till raw smell goes off.", "Now add chopped ginger and fry well till golden.Add tomatoes and sprinkle salt so that they can turn a little mushy.Now add turmeric powder, coriander powder, red chili powder and the achari masala.", "Saute until the tomatoes soften.\u00a0whisk curd and besan together.", "Add to the pan and cook until the curd is mixed well and it thickens.Add saut\u00e9ed ladies finger and salt as per your taste and slow cook the bhindi on low flame with lid closed.Once the Dahi Achari Bhindi has absorbed all the flavor, turn off the heat and garnish with freshly chopped coriander.Serve the\u00a0Dahi Achari Bhindi Recipe\u00a0along with\u00a0Phulka\u00a0or\u00a0Methi Lacha Paratha\u00a0and\u00a0Boondi Raita\u00a0by the side for a weekday meal."]'::jsonb, 55, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanskitchen.com/Dahi_Achari_Bhindi_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/703.Dahi_Achari_Bhindi_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('No Onion No Garlic Rajasthani Gatte Ki Kadhi Recipe', 'no-onion-no-garlic-rajasthani-gatte-ki-kadhi-recipe', 'The Rajasthani Gatte Ki Kadhi Recipe is a traditional yogurt based curry that is simmered along with a spiced gram flour dumplings. It''s most often had along with millet based rotis or along with steamed rice, Kachumber Salad and Boondi Raita.', '["Ingredients for the gatte (gram flour dumplings)", "1 cup Gram flour (besan)", "1/2 teaspoon Ajwain (Carom seeds)", "1/4 teaspoon Red Chilli powder", "2 tablespoons Curd (Dahi / Yogurt)", "1 tablespoon Oil", "Salt , to taste", "Ingredients for the kadhi (yogurt curry)", "2 tablespoons Gram flour (besan)", "2 cups Curd (Dahi / Yogurt)", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Red Chilli powder", "1 Bay leaf (tej patta) , torn", "1 inch Cinnamon Stick (Dalchini)", "Salt , to taste", "4 sprig Coriander (Dhania) Leaves , chopped", "Ingredients for the tadka", "1 tablespoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'asafoetida (hing)', 'bay leaf (tej patta)', 'ghee', 'ajwain (carom seeds)', 'mustard seeds', 'red chilli powder', 'gram flour (besan)', 'curd', 'coriander (dhania) leaves', 'curry leaves', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the\u00a0Rajasthani Gatte Ki Kadhi Recipe we will first make the gatte.In a large mixing bowl, combine all the ingredients for the gatta.", "Add a few teaspoons of water at a time and knead to make a firm dough.", "Knead well for about 5 minutes to make a very soft melt in the mouth gatta.If you add more water and it does not shape into a dough, then you will have to add more gram flour and knead it well.Roll the dough into a long cylinder and cut them into 1 inch discs.", "The next step is to cook the gattas in boiling water.In a large saucepan boil water until it comes to a brisk boil.", "Once the water comes to a brisk boil, add the gattas into the water and boil until they comes floating to the top.", "Once they come floating to the top, boil for another 3 to 4 minutes.", "Drain the gattas and keep it aside, till we get the Kadhi ready.To make the kadhi, in a saucepan, combine the yogurt, gram flour until it becomes a smooth paste.", "Add 2-1/2 cups of water, asafoetida, turmeric powder and salt.", "Stir well.Bring the kadhi mixture to a boil.", "While the kadhi is coming to a boil, keep whisking it until you get a very smooth kadhi.You will notice that the yogurt will stop curdling when you keep whisking.", "Turn the heat to low, add the bay leaves, cinnamon, red chili powder and simmer the kadhi for about 10 minutes until the kadhi turns slightly thick.", "Add the cooked\u00a0gattas at this stage and boil for a few more minutes.", "While the Gatte Ki kadhi is boiling, we will proceed to make the tadka for the kadhi.Heat oil in a tadka pan, add the ghee and the remaining ingredients and allow them to crackle.", "Once they crackle, turn off the heat and add the seasoning to the Gatte Ki Kadhi.Serve the\u00a0Gatte Ki Kadhi along with\u00a0millet based rotis or along with steamed rice,\u00a0Kachumber Salad\u00a0and\u00a0Boondi Raita."]'::jsonb, 70, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Rajasthani_Gatte_Ki_Sabji_Recipe_Vegetarian_Archanas_Kitchen-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/704.Rajasthani_Gatte_Ki_Sabji_Recipe_Vegetarian_Archanas_Kitchen-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pahari Style Phanu Recipe - Delicious Mixed Dal', 'pahari-style-phanu-recipe-delicious-mixed-dal', 'Pahari Style Phanu Recipe is a delicious blend of two different dals. The creaminess in the dal is wonderfully complimented with the subtle flavours from the whole spice. A simple tadka with mustard oil, cumin seeds and green chillies are poured on top before serving.', '["1 cup Arhar dal (Split Toor Dal) , soaked in water for 2 hours", "1/2 cup White Urad Dal (Split) , soaked in water for 2 hours", "1 Tomato , finely chopped", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "1 teaspoon Turmeric powder (Haldi)", "1 pinch Asafoetida (hing)", "1/2 inch Ginger , finely chopped", "2 cloves Garlic , finely chopped", "1 teaspoon Cumin seeds (Jeera)", "1 Green Chilli , slit", "1 teaspoon Mustard oil , for tadka"]'::jsonb, ARRAY['tomato', 'ginger', 'arhar dal (split toor dal)', 'green chilli', 'asafoetida (hing)', 'mustard oil tadka', 'cloves garlic', 'white urad dal (split)', 'cumin seeds (jeera)', 'turmeric powder']::text[], '["To begin making the Pahari Style Phanu Recipe-Toor Dal & Urad Dal, soak the dals for a couple of hours and keep it ready.Add the soaked dal them into the pressure cooker along with chopped tomatoes, ginger, garlic, turmeric powder and salt.Pressure cook the dal for at least 6 whistles, allow the pressure to release naturally and open the lid.Keep the dal back on the stove, add a pinch of hing, adjust the salt if required and also adjust the consistency of the Phanu by adding little more water.", "Mish mash it little bit to get a good creamy consistency of the\u00a0Phanu recipe.To make the tadka for the Phanu recipe, heat mustard oil over a tadka pan, once it is hot, add cumin seeds, green chilli, ginger and garlic and allow it to sizzle for few seconds.Pour the tadka over the Phanu\u00a0and mix well and serve hot.Serve the\u00a0Pahari Style Phanu Recipe\u00a0along with\u00a0phulka,\u00a0Aloo Baingan Ki Sabzi\u00a0,\u00a0Mooli Raita Recipe\u00a0by the side."]'::jsonb, 155, 'Uttarakhand-North Kumaon', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Pahari_Style_Phanu_Recipe_Toor_Dal__Urad_Dal_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/705.Pahari_Style_Phanu_Recipe_Toor_Dal__Urad_Dal_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Soya Chunks Masala in Coconut Milk Recipe', 'soya-chunks-masala-in-coconut-milk-recipe', 'Soya Chunks Masala in Coconut Milk is a spicy preparation of protein rich soya chunks in coconut milk which has its own list of benefits. This gravy pairs up perfect so well not only with hot steamed rice but also with wheat phulkas. The spiciness of the gravy can be adjusted according to the palate. The preparation of the soya chunk masala is an effortless affair with subtle flavours of spices and coconut milk, hence can be a top option of a lazy weekend menu.', '["2 cups Soy Chunks (Nuggets) , boiled and squeezed well", "2 Tomatoes , finely sliced", "1 Onion , finely chopped", "3 Green Chillies , slit", "3 cloves Garlic , grated", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Curry powder", "100 ml Coconut milk", "Oil , for cooking", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'coconut milk', 'salt', 'coriander powder', 'red chilli powder', 'cloves garlic', 'curry leaves', 'onion', 'cumin seeds (jeera)', 'curry powder', 'soy (nuggets) squeezed', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the\u00a0Soya Chunks Masala in Coconut Milk Recipe, get all the ingredients ready.Heat water in a saucepan and bring it to a brisk boil.", "Add the soy chunks into the water and allow it to boil for a couple of minutes until the soy chunks soak in a lot of water and become soft.", "This will take about 5 minutes. once the soy chunks have soaked in the water and become soft, drain out the water and keep the soy chunks aside.The next step is to make the masala.Heat a teaspoon of oil in a heavy bottomed pan.", "Add the cumin, curry leaves and green chilies and saute them for a few seconds.", "Add the onions, ginger, garlic and saute until the onions become soft and translucent.Add sliced tomatoes and saute for 2 minutes on high heat until the tomatoes soften.", "Once the tomatoes soften, add the coriander powder, red chilli powder and turmeric powder, mix well.", "Cook for half a minute.Add soya chunks and saute in the masala for 2 to 3 minutes.", "Finally add coconut milk and about a cup of water, salt and curry powder.", "Mix well and simmer the Soy Chunks Masala for about 5 minutes until the gravy thickens.", "Once done, check the salt and spice levels and adjust to suit your taste.", "Transfer the Soy Chunks Masala into a serving bowl and stir in the\u00a0chopped green coriander leaves and serve.", "Serve the\u00a0Soya Chunks Masala in Coconut Milk \u00a0along with\u00a0Lachha Paratha, \u00a0Orange and Pomegranate Salad\u00a0& Steamed Rice."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Farrukh_Aziz_Ansari/Soya_Chunks_Masala_in_Coconut_Milk_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/706.Soya_Chunks_Masala_in_Coconut_Milk_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Khatti Arbi Ki Sabzi Recipe - Colocasia In Yoghurt Curry', 'khatti-arbi-ki-sabzi-recipe-colocasia-in-yoghurt-curry', 'Khatti Arbi Ki Sabzi Recipe (Colocasia In Yoghurt Curry) a dry yogurt based arbi dish that has mild spice which is well balanced with the sourness from the yogurt. The flavors from the fenugreek seeds, peppercorns, cumin seeds and coconut when ground and added to the curry along with yogurt creates a delicious dish.', '["500 grams Colocasia root (Arbi) , skin peeled and boiled", "1/2 cup Curd (Dahi / Yogurt)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Turmeric powder (Haldi)", "2 Dry Red Chillies", "2 sprig Curry leaves", "Salt , to taste", "Oil", "To Grind", "1 teaspoon Black pepper powder", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "4 tablespoon Fresh coconut , grated"]'::jsonb, ARRAY['s colocasia root', 'arbi', 'curd', 'dahi / yogurt', 'mustard seeds', 'rai/ kadugu', 'turmeric powder', 'haldi', 'dry red chillies', 'curry leaves', 'salt', 'oil', 'to grind', 'black pepper powder', 'cumin seeds', 'jeera', 'methi seeds', 'fenugreek seeds', 'fresh coconut']::text[], '["To begin making the Khatti Arbi Ki Sabzi Recipe, we will first pressure cook the arbi in a cooker with water and little salt for at least 4 whistles.Once it is done, allow the pressure to release naturally and drain all the water and set aside to cool.", "It will be now easy to peel off the skin, cut the arbi into half.In a mixer, add all the ingredients like black pepper powder, cumin seeds, fenugreek seeds and fresh coconut, add little water and grind into a coarse paste.Heat oil in a kadai, add mustard seeds and allow it to splutter for few seconds.", "Add in curry leaves and leave it to crackle.Drop in some dry red chillies and saute for few seconds.", "Add in cooked arbi, salt, turmeric powder and saute well till the arbi is roasted well.Once the arbi is saut\u00e9ed, you can now add the ground coconut paste and mix well.Also add the curd, toss around so that the masala is coated well.", "Check for salt, and cook Khatti Arbi Ki Sabzi until the moisture from the curry is evaporated and the dish becomes little dry.", "Once the Khatti Arbi Ki Sabzi is done you can turn the heat off and serve it in a bowl.", "Serve the\u00a0Khatti Arbi Ki Sabzi Recipe\u00a0along with\u00a0Gujarati Methi Thepla\u00a0and\u00a0Matar Paneer\u00a0to make it a complete meal."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Arbi_Ki_khatta_Subzi_Recipe_Colocasia_Cooked_Dry_Yogurt_Curry_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/707.Arbi_Ki_khatta_Subzi_Recipe_Colocasia_Cooked_Dry_Yogurt_Curry_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kolambi Bhaath Recipe (Maharashtrian Prawn Rice)', 'kolambi-bhaath-recipe-maharashtrian-prawn-rice', 'Kolambi Bhaath is a marathi style rice preparation with Prawns. To my mind it closely resembles tomato rice with added prawns. Cooked rice is mixed with prawns stir fried with onion and tomatoes along with some dry spices to make a delightful and yet easy lunch/dinner.', '["200 grams Prawns , deveined & shelled", "2 cups Rice , cooked", "3 Tomatoes , finely chopped", "1 Onion , finely chopped", "5 to 6 cloves Garlic", "1 inch Ginger", "3 to 4 Green Chillies", "1 sprig Curry leaves", "1 teaspoon Kashmiri Red Chilli Powder", "Salt , to taste", "1/4 teaspoon Turmeric powder (Haldi)", "2 Cloves (Laung)", "1/2 inch Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "2 Bay leaves (tej patta)", "pinch Sugar", "1 teaspoon Maharashtrian Goda Masala", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Cumin seeds (Jeera)", "Oil , as required"]'::jsonb, ARRAY['s prawns', 's rice', 'tomatoes', 'onion', 'to 6 cloves garlic', 'ginger', 'to 4 green chillies', 'curry leaves', 'kashmiri red chilli powder', 'salt', 'turmeric powder', 'haldi', 'laung', 'cinnamon stick', 'dalchini', 'cardamom', 'elaichi', 'bay leaves', 'tej patta', 'pinch sugar', 'maharashtrian goda masala', 'asafoetida', 'hing', 'cumin seeds', 'jeera', 'oil']::text[], '["To begin making the Kolambi Bhaath, In a heavy bottom wok/kadhai, heat oil and add hing to it till it sizzles.Next, add jeera and saut\u00e9 till golden brown.", "Add all the dry masalas including cloves, cardamom, cinnamon and bay leaves.", "Fry till they are fragrant.Add onion, curry leaves, garlic and ginger and saut\u00e9 further till the onions turn translucent.Add tomatoes and fry till they are mushy and oil separates.Add turmeric powder, chilli powder and then add the prawns.Fry for about 3 to 4 minutes till the prawns are cooked.Mix it with boiled rice delicately.", "Serve hot garnished with fresh coriander leaves.Serve Kolambi Bhaath with\u00a0Burani Raita,\u00a0Tomato Onion Cucumber Raita\u00a0or any other Raita of your choice for a perfect weekday lunch or dinner."]'::jsonb, 50, 'Maharashtrian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Monika_Manchanda/Kolambi_Bhaath.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/708.Kolambi_Bhaath.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Methi Turai Ki Sabzi (Fenugreek Leaves And Ridge Gourd Stir Fry)', 'methi-turai-ki-sabzi-fenugreek-leaves-and-ridge-gourd-stir-fry', 'Methi Turai Ki Sabzi is a dry vegetable preparation of fenugreek leaves and ridge gourd stir fried together with some spices. This healthy combination makes a delicious quick comforting addition to a homely lunch or dinner. Enjoy the combined goodness of both these vegetables packed into one delicious dish. Serve Methi Turai Ki Sabzi along with hot salad.', '["500 grams Ridge Gourd (Turai/ Peerkangai) , cut into 1 inch cubes", "2 cups Methi Leaves (Fenugreek Leaves) , roughly chopped", "1 Onion , finely sliced", "1 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies , broken into halves", "4 cloves Garlic , coarsely crushed", "2 Green Chillies , coarsely crushed", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 Lemon , juiced", "1/2 teaspoon Garam masala powder", "2 tablespoons Oil"]'::jsonb, ARRAY['green chillies', 'methi leaves (fenugreek leaves)', 'cloves garlic', 'lemon', 'dry red chillies', 'onion', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'ridge gourd (turai peerkangai) cubes', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Methi Turai Ki Sabzi, warm the oil in a heavy bottom pan or kadhai.", "Add the cumin seeds and broken red chilies to it and allow them to crackle.Next, add the finely sliced onions and saute them until pink, soft, almost translucent.Then, add coarsely crushed garlic, green chilies, turmeric powder and coriander powder and saute it all together for a minute or two.To this, add the cubed ridge gourd and toss on high heat for 3-4 minutes.", "The ridge gourd will release water, cover and cook for 3-4 minutes more on medium heat, till it is soft and cooked through.When done, uncover the kadhai, add the methi leaves, garam masala powder, lemon juice, salt and mix well once again.Cook this together for 3-4 minutes again on a high heat until all the water released by methi and ridge gourd dries up.At this stage, leave the sabzi uncovered, so that the vegetables can dry up completely leaving you with a dry sabzi.", "Check the salt and spices in the end and adjust to suit your taste.", "Turn off the heat, transfer to a serving bowl and serve warm.Serve Methi Turai Ki Sabzi along with hot\u00a0salad\u00a0for a quick lunch or a weeknight dinner."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Farrukh_Aziz_Ansari/MethiTurai_Ki_Sabzi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/709.MethiTurai_Ki_Sabzi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ambur Star Chicken Biryani Recipe', 'ambur-star-chicken-biryani-recipe', 'Ambur Star Chicken Biryani is a delicious South Indian Biryani Recipe, in which the flavour of the chicken is predominant and the spices are rather mild. With tender pieces of meat on the bone, simple whole spices and the short grain rice-Seeraga Samba, this non-vegetarian recipe is an absolute winner.  Serve it as main course at your parties or on a Sunday afternoon for lunch.', '["500 grams Seeraga (Jeeraga) Samba rice , washed and soaked", "1 tablespoon Ghee", "1 Bay leaf (tej patta)", "1 Star anise", "1 Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "1 clove Cloves (Laung)", "500 grams Chicken , cleaned and washed", "4 tablespoons Oil", "2 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "3 Onions , sliced", "2 Tomatoes , chopped", "3 teaspoons Red Chilli powder", "Salt , to taste", "2 teaspoons Coriander Powder (Dhania)", "3 tablespoons Curd (Dahi / Yogurt)", "1/4 cup Mint Leaves (Pudina) , roughly torn"]'::jsonb, ARRAY['tomato', 'salt', 'clove cloves (laung)', 'ginger', 'bay leaf (tej patta)', 'ghee', 'cardamom (elaichi) podsseeds', 'mint leaves (pudina)', 'red chilli powder', 'cloves garlic', 'curd', 'cinnamon stick (dalchini)', 'chicken', 'onion', 'seeraga (jeeraga) samba rice', 'coriander powder', 'star anise', 'sunflower oil']::text[], '["To begin making the Ambur Star Chicken Biryani, thoroughly wash and clean the chicken and set aside.", "Soak the Seeraga samba rice, for a minimum of 30 minutes.In an open pan, add ghee, bay leaf, star anise, cinnamon, cloves, cardamom.", "To this add 2 cups of water and bring to a single boil.", "Add the washed and drained rice and cook until the rice is about 70% cooked. \u00a0(The rice grain should be undercooked in the center) Set aside.In a deep kadai, on medium flame, heat 4 tablespoons of oil, add the sliced onions and cook till transparent for about 5-7 minutes.At this stage mix in the ginger paste, garlic paste and salt.", "Saute for a couple of minutes.Mix in the chopped tomatoes and cook until they are soft.", "At this stage add in the red chilli powder and coriander seeds powder.Once the onion-tomato mixture comes together, slightly tilt the kadai, and remove the excess oil, spoon by spoon into a small cup/katori.Now that the excess oil has been drained out, add the yogurt/curd and chicken and mix well.", "Allow the chicken to cook until almost done to about 80%.", "Mix in the mint leavesTo assemble to biryani, while the chicken continues to be in the kadai, add the 70% cooked seeraga samba rice on top of the chicken pieces and pour the excess flavoured oil over the rice and cover the kadai with a plate.", "Turn the flame to the lowest heat possible.", "In a saucepan, boil water and turn off the flame and place this hot pan on the lid of the kadai.", "This process is done in order to seal the kadai in which the biryani is cooking.", "The heat from the hot water in the saucepan provides heat from the top, while there is heat from the bottom as well creating the effect of \"Dum\".", "Let the biryani sit on this \"Dum\" for a good 20 minutes.", "After 20 minutes open the lid and lightly fluff up the biryani with a fork and serve piping hot.Serve the\u00a0Ambur Star Chicken Biryani\u00a0\u00a0along with\u00a0Tadka Raita Recipe (Spiced Curd With Onions)\u00a0and\u00a0Chettinad Kathirikai Chops Recipe\u00a0for Sunday Lunch."]'::jsonb, 55, 'Tamil Nadu', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sneha-archanaskitchen.com/Ambur_Star_Chicken_Biryani_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/710.Ambur_Star_Chicken_Biryani_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dum Pukht Gosht Recipe - Slow Cooked Mutton Curry', 'dum-pukht-gosht-recipe-slow-cooked-mutton-curry', 'Dum Pukht is a slow cooking technique where food is cooked in a sealed vessel. Dum means "to breathe" and Pukht means "to cook". Lucknowi Nawabs used this technique of cooking and the Lucknowi dum cooked recipes like their biryani is quite popular.', '["500 grams Mutton", "1-1/2 cups Curd (Dahi / Yogurt)", "2 Cardamom (Elaichi) Pods/Seeds", "1 Brown cardamom (Badi Elaichi)", "1 teaspoon Black pepper corns", "4 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 teaspoon Cumin seeds (Jeera)", "1 Onion , sliced", "8 cloves Garlic", "1 inch Ginger", "4 Green Chillies", "1-1/2 teaspoons Coriander (Dhania) Powder", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "1/4 cup Coriander (Dhania) Leaves", "Ghee , for cooking", "To seal the vessel", "2 cups Whole Wheat Flour", "Water , for kneading"]'::jsonb, ARRAY['green chillies', 'wheat flour', 'ginger', 'cardamom (elaichi) podsseeds', 'coriander (dhania) leaves', 'black pepper corns', 'cinnamon stick', 'ghee', 'red chilli powder', 'cloves garlic', 'water', 'curd', 'onion', 'mutton', 'coriander (dhania) powder', 'brown cardamom (badi elaichi)', 'turmeric powder', 'cloves (laung)', 'garam masala powder', 'cumin (jeera) seeds']::text[], '["To begin making\u00a0Dum Pukht Gosht we will first prepare the ingredients required for marinating the mutton.", "Heat ghee in a preheated pan; add the onions and saute until the onion turn golden brown.Once the onions have started to turn golden brown add all the whole spices, black cardamom, green cardamom, cloves, cinnamon stick, peppercorn and saute till the spices release a nice aroma.", "Turn off the heat and let it cool.Once cooled add the caramelized onions and the whole spices to a mixer grinder.", "Add the garlic, ginger, green chillies and half the curd and grind to a smooth paste.", "Marinate the mutton with the above ground spice curd and onion mixture.", "Add the remaining curd, chilli powder, turmeric powder, coriander powder,garam masala powder, salt to taste to the above mutton and marinate it in the refrigerator for two hours or overnight.You can marinate the meat longer to get maximum flavour in the dish.", "While the mutton is marinating knead the dough that you need to seal the vessel in which you are going to cook the gosht in.", "The dough should be a bit stiff, like how you knead for puris.*To make the\u00a0Dum Pukht GoshtOnce the mutton has marinated, preheat a heavy bottomed vessel or handi and add some ghee.Add the marinated mutton in the handi and saute for a few minutes till the marinated mutton leaves oil on the sides.", "This will take about 10 minutes.", "Add one glass of water and bring the Mutton gosht to a boil.Cover the handi with a lid and seal it with the wheat dough and leave the Mutton\u00a0gosht cook on low heat for about 50 minutes.", "This process of covering and sealing the lid with the dough is called \"Dum Cooking\" - a very slow cooking process that brings in flavours to the dish.After about one hour turn off the heat and remove the dough on the lid with the help of a kitchen knife.You will notice the\u00a0Dum Pukht Gosht has a rich colour and taste with all the natural oils from the the mutton released into the dish.", "Give it a stir and adjust the salt accordingly.", "Transfer the Dum Pukht Gosht into a serving dish and garnish with coriander leaves and serve hot.Serve Dum Pukht Gosht with hot with\u00a0Mande Roti\u00a0or\u00a0Butter Garlic Naan\u00a0and\u00a0Tomato Onion Cucumber Raita\u00a0for a weekend lunch or dinner. you can even serve it at your next dinner party."]'::jsonb, 75, 'Lucknowi', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/dum_pukht_gosht_recipe_9_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/711.dum_pukht_gosht_recipe_9_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sindhi Pakwan Recipe - Crisp Delicious Puri', 'sindhi-pakwan-recipe-crisp-delicious-puri', 'Sindhi Pawan is a classic in Sindhi Crisp Puri recipe that is served along with Sindhi Chana Dal. Together the Dal Pakwan is considered to be a royal breakfast garnished with chutney and chopped onion. Pakwan is crispy fried pooris made with a mix of both wheat flour and all purpose flour. As the pakwan is fried and teamed up with chana dal, it becomes rich and heavy to digest. Hence a teaspoon of ajwain is mixed with the flour while making pakwan that consist amazing digestive properties and prevents you from feeling bloated.', '["1 cup Whole Wheat Flour", "1 cup All Purpose Flour (Maida)", "1 teaspoon Ajwain (Carom seeds)", "1 teaspoon Cumin seeds (Jeera)", "2 tablespoons Ghee", "Salt , as needed", "Oil , for deep frying"]'::jsonb, ARRAY['salt', 'wheat flour', 'ghee', 'ajwain (carom seeds)', 'cumin seeds (jeera)', 'flour (maida)', 'sunflower oil']::text[], '["To begin making the Sindhi Pakwan, sift both the flours together.", "Add ajwain, cumin, salt and ghee and mix all together into the flour.", "Knead the flour into a smooth dough adding water little at a time.Preheat the oil for deep frying.Divide the Pakwan dough into equal lemon size portions.Dust the surface with flour and roll the pakwan dough into a small disc.Use a fork and\u00a0mark impressions on the rolled pakwan.", "Pierce from both sides, this will prevent the pakwan from puffing up.Place the pakwans into the preheated oil and deep fry on low to medium heat until golden brown and crisp on both sides.", "Transfer the fried pakwan on a kitchen paper towels to drain the excess oil.Serve the Sindhi Pakwan hot along with Sindhi Chana Dal for a wholesome breakfast or dinner."]'::jsonb, 45, 'Sindhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Sindhi_Pakwan_Recipe_Served_With_Sindhi_Dal_Dal_Pakwan-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/712.Sindhi_Pakwan_Recipe_Served_With_Sindhi_Dal_Dal_Pakwan-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style duck curry with Coconut Milk Recipe', 'kerala-style-duck-curry-with-coconut-milk-recipe', 'Kerala Style duck curry with Coconut Milk Recipe, is very dear to my heart and has an influence from Kerala cuisine. This is one of the famous dishes in Alappuzha district of kerala. There is something mystical about this duck curry as the aromas awakens your senses which in turn fires the appetite and it is hard for the taste buds to resist the temptation of this mouth watering duck curry. The sharpness of spices and pepper is well balanced with the richness of the coconut milk.', '["1 kg Duck , with skin cut into small pieces", "2 teaspoon Whole Black Peppercorns , Crushed", "2 teaspoon Vinegar", "3/4 teaspoon Turmeric powder (Haldi)", "3 tablespoon Coconut Oil", "3 Green Chillies , finely chopped", "Salt , to taste", "1/4 cup Shallots , finely sliced", "3 Dry Red Chillies , broken into two pieces", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "3 sprig Curry leaves", "2 Green Chillies , slit lengthwise", "2 tablespoon Coconut Oil", "1 tablespoon Ghee", "1 Onion , finely, sliced", "1 Tomato , sliced", "1 inch Ginger , chopped", "2 cloves Garlic , chopped", "2 cups Coconut milk , Semi Thick (2nd extract)", "1 cup Coconut milk , Thick (1st extract)", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "3 teaspoon Garam masala powder", "1 teaspoon Fennel Powder", "1 Cardamom (Elaichi) Pods/Seeds"]'::jsonb, ARRAY['duck', 'whole black peppercorns', 'vinegar', 'turmeric powder', 'haldi', 'coconut oil', 'reen chillies', 'salt', 'shallots', 'dry red chillies', 'mustard seeds', 'rai/ kadugu', 'methi seeds', 'fenugreek seeds', 'curry leaves', 'ghee', 'onion', 'tomato', 'ginger', 's garlic', 's coconut milk', 'coconut milk', 'coriander powder', 'dhania', 'red chilli powder', 'garam masala powder', 'fennel powder', 'cardamom', 'elaichi']::text[], '["We begin making the Kerala Style duck curry with Coconut Milk Recipe by cleaning the duck and cutting them into small curry size pieces.", "Then add all the marination ingredients.", "Marinate the duck for 30 minutes and keep it aside.After 30 minutes, add oil , ghee and 1 cup of the \u00a02nd extract of coconut milk, 2 cups of water and cook the marinated duck in a pressure cooker for about 5-6 whistles in high heat.Heat another pan, pour coconut oil and ghee.", "Add mustard seeds and when it starts to splutter, add fenugreek seeds, sliced shallots, curry leaves, dried red chilly,chopped ginger,garlic and saute for couple of minutes.Add chopped onions, green chillies, tomatoes; saute till onions turn translucent and light brown color.Now add in coriander and red chilli powder and combine well.", "Then pour the remaining 1 cup of the 2nd extract of coconut milkNow add the cooked duck along with the stock(cooked water of the duck).", "Combine well, then add garam masala powder, cardamom pods.", "Close with a lid and cook for 5 minutes.", "Finally add the first extract \u00a0of the thick coconut milk and check for salt, keep the flame on very low and cook it for another 5 minutes and serve.", "Serve the\u00a0Kerala Style duck curry with Coconut Milk Recipe along with\u00a0Steamed Rice Recipe (Pressure Cooker & Sauce Pan Methods)\u00a0 and\u00a0Kerala Style Appam Recipe (Fermented Rice Pancakes With Coconut)."]'::jsonb, 75, 'Kerala', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Akshay-Nair-P.R/Duck_curry_with_coconut_milk.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/713.Duck_curry_with_coconut_milk.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('South Indian Paniyaram Recipe - 3 types - Classic, Carrot & Spinach', 'south-indian-paniyaram-recipe-3-types-classic-carrot-spinach', 'Paniyaram can be a handy recipe when you want to use the leftover idli-dosa batter when the batter starts to become sour. Whenever you are in a hurry then you can just add salt, few vegetables like grated carrots and spinach make a nutritious paniyaram and serve it along with idli podi or chutney.', '["3 cups Idli Dosa Batter", "2 cups Carrots (Gajjar) , grated", "2 cups Spinach , finely chopped", "Salt , to taste", "Classic Paniyaram Masala", "2 teaspoons Mustard seeds (Rai/ Kadugu)", "4 Green Chillies , finely chopped", "2 cups Pearl onions (Sambar Onions) , finely chopped", "1/4 cup Coriander (Dhania) Leaves , finely chopped", "Oil , for shallow frying"]'::jsonb, ARRAY['s idli dosa batter', 's carrots', 'gajjar', 's spinach', 'salt', 'classic paniyaram masala', 's mustard seeds', 'rai/ kadugu', 'reen chillies', 's pearl onions', 'sambar onions', 'coriander', 'dhania', 'oil']::text[], '["To begin making Paniyaram With Idli/Dosa Batter Recipe, prep all the ingredients and keep them ready.Have the dosa batter ready - it''s the classic dosa batter from idli rice and urad dal, soaked ground and fermented.", "My next step is to prep all 3 variants and add to the batter and make paniyarams in a paniyaram pan.", "First to cook the carrots, heat oil in over medium heat in a pan; add the carrots and saute until the carrots turn soft.", "Turn off the heat and allow the carrots to cool.", "Don''t add any salt as yet, as the dosa batter has a little salt.Next cook the spinach; heat oil over medium heat in a pan; add the spinach and saute until the spinach wilts completely and once done, turn off the heat and keep aside to cool.Once cooled, add the carrots to the Mixer Grinder along with 1 cup of the dosa batter, pinch of salt and blend to make a smooth batter.", "The reason I am blending with the batter is, I don\u2019t have to add any additional water to the batter for grinding.Next for the spinach, add the spinach to the Mixer Grinder along with 1 cup of the dosa batter, pinch of salt and blend to make a smooth batter.", "Keep both batters aside.The next step is to make spicy masala which will go into all three batters.", "Heat oil in a pan, add the mustard seeds and allow it to crackle.", "Add the curry leaves, green chillies and chopped onion.", "Saute until the onion softens and turns lightly golden brown.Once done, turn off the heat.Divide this into 3 portions and add into the 3 batters (plain, carrot and spinach).", "Check the salt if required and add to taste.The final step is to cook the paniyarams.Add oil into each of the cavities.", "Spoon the batters into the cavity.", "Cover with a lid and steam until the top gets cooked.Once the top is steamed, open the lid and flip the paniyam and cook on the other side until golden and lightly crisp.", "Transfer the paniyaram to a serving bow and serve it along with chutney for a hearty breakfast or even a snack.And this chutney is super simple to make - fresh grated coconut, along with a handful of almonds, a couple of green chillies, an inch piece ginger, salt and lemon.", "Blend using the Mixer Grinder and voila your chutney is ready in two minutes.And one small tip, if your coconut is cold or frozen, use warm water for grinding this chutney, you get the perfect texture.Serve\u00a0Masala Paniyaram With Idli/Dosa Batter Recipe with\u00a0Coconut Chutney\u00a0and\u00a0Filter Coffee\u00a0as a tea time snack."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Tri_Color_Kuzhipaniyaram_Recipe_Indepandance_day_special_2-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/714.Tri_Color_Kuzhipaniyaram_Recipe_Indepandance_day_special_2-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gutti Dondakaya Vepudu Recipe - Stuffed Ivy Gourds | Stuffed Tendli | Kovakkai', 'gutti-dondakaya-vepudu-recipe-stuffed-ivy-gourds-stuffed-tendli-kovakkai', 'Gutti Dondakaya Vepudu Recipe is a spicy and delicious preparation of ivy gourd or tendli in an Andhra style. Andhra cuisine is classified under the most spiciest ones, yet this recipe is a mix of amazing flavours and textures.', '["500 grams Tindora (Dondakaya/ Kovakkai) , slit length wise", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies", "1/4 teaspoon Asafoetida (hing) , a pinch", "1 sprig Curry leaves", "2 tablespoons Oil", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "To roast and ground to a course mix", "2 tablespoons White Urad Dal (Split)", "4 tablespoons Chana dal (Bengal Gram Dal)", "2 tablespoons Coriander (Dhania) Seeds", "1 teaspoon Cumin seeds (Jeera)", "2 tablespoons Sesame seeds (Til seeds)", "4 Dry Red Chillies", "1/4 cup Fresh coconut , grated"]'::jsonb, ARRAY['s tindora', 'dondakaya/ kovakkai', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'dry red chillies', 'asafoetida', 'hing', 'curry leaves', 's oil', 'turmeric powder', 'haldi', 'salt', 'to roast and ground to a course mix', 's white urad dal', 'split', 's chana dal', 'bengal gram dal', 's coriander', 'dhania', 's sesame seeds', 'til seeds', 'fresh coconut']::text[], '["To begin making\u00a0Gutti Dondakaya Vepudu Recipe, wash, drain and wipe the Ivy Gourds dry with a kitchen towel.Now make a long cross slit on each Dondakaya/ Kovakkai/ Tendli length wise, keeping the base and shape of each vegetable intact and keep aside.Next step is to make the Dondakaya Vepudu for which we have to grind the fresh masala.", "Heat a pan over medium heat, add the chana dal and urad dal and roast until golden brown and crisp.Stir in the coriander seeds, sesame seeds, cumin seeds, red chillies until the coriander and sesame start popping and releasing a roasted aroma.Finally stir in the coconut and roast until it turns lightly golden.", "Turn off the heat and allow the masala to cool.", "Into the small jar of the mixer grinder add the roasted masala, along with a little salt and grind into a coarse powder.", "Transfer masala into a bowl and set aside.", "Now, fill the slit\u00a0Dondakaya/ Kovakkai/ Tendli with the roasted masala and keep aside.Heat oil in a wide pan on medium heat; add the mustard seeds cumin seeds, and allow it to crackle.", "Add the asafoetida, curry leaves and red chillies and roast for a few seconds.", "Add the stuffed Dondakaya/ Kovakkai/ Tendli to the pan, stir in the same, turmeric powder, gently stir, add 1/4 cup of water and cover the pan.", "Turn the heat to low and cook until the dondakaya vepudu is done.", "You can also alternatively, place the whole mixture into the pressure cooker with 2 tablespoons of water and pressure cook for 3 to 4 whistles and turn off the heat.", "Release the pressure immediately and then stir fry in the open until all the masala comes together.", "Once done, turn off the heat and transfer the\u00a0Gutti Dondakaya Vepudu to serving bowl and serve hot.Serve the\u00a0Gutti Dondakaya Vepudu Recipe along with Steamed Rice\u00a0and\u00a0Andhra Style Pappu Charu Recipe\u00a0for the weeknight dinner."]'::jsonb, 35, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Doddakaya_Vepudu_Andhra_recipe_Kovaikai_Tendli_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/715.Doddakaya_Vepudu_Andhra_recipe_Kovaikai_Tendli_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Milagu Rasam Recipe - Miriyala Charu | Pepper Rasam With Fresh Ground Rasam Powder', 'milagu-rasam-recipe-miriyala-charu-pepper-rasam-with-fresh-ground-rasam-powder', 'Milagu Rasam also known as the Miriyala Charu is a rasam that made from freshly roasted and ground spices simmered in a tamarind and tomato gravy. It makes a perfect dish to have as a soup or along with a south indian meal.', '["1/4 cup Arhar dal (Split Toor Dal)", "1 cup Tamarind Water", "2 Tomatoes , quartered", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Jaggery", "Salt , to taste", "6 sprig Coriander (Dhania) Leaves , chopped for garnish", "2 teaspoons Whole Black Peppercorns", "1 teaspoon Cumin seeds (Jeera)", "1 tablespoon Coriander (Dhania) Seeds", "1 teaspoon Arhar dal (Split Toor Dal)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1 tablespoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Asafoetida (hing)", "1 sprig Curry leaves"]'::jsonb, ARRAY['arhar dal', 'split toor dal', 'tamarind water', 'tomatoes', 'turmeric powder', 'haldi', 'jaggery', 'salt', 'coriander', 'dhania', 's whole black peppercorns', 'cumin seeds', 'jeera', 'methi seeds', 'fenugreek seeds', 'ghee', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing', 'curry leaves']::text[], '["To begin with Milagu Rasam/ Miriyala Charu, prepare all the ingredients and keep ready.Cook the toor dal in 1 cup of water in the pressure cooker for 3 to 4 whistles and simmer for couple of minutes and turn off the heat.", "Allow the pressure to release naturally and once done, mash the dal well and keep aside.First step is to make the fresh rasam powder.", "Heat a pan over medium heat; add the toor dal and roast on medium heat until golden.", "Add the coriander seeds, cumin seeds, methi seeds and black pepper.", "Roast for about a minute until the seeds start crackling and start releasing an aroma.Once done, turn off the heat and allow it to cool.Into the small jar of the mixer grinder add the roasted ingredients and grind into a coarse powder.", "The next step is to make the Pepper Rasam/ Miriyala Charu.", "Into a deep dish, add 3 cups of water, chopped tomatoes, tamarind extract, salt, turmeric powder, salt and jaggery and bring to a boil.", "Continue to boil for 4 to 5 minutes until the tomatoes soften.", "Once the tomatoes soften, add the ground fresh rasam powder and mashed dal and boil for another 5 minutes until you notice the water begins to froth.", "The final step is the seasoning.", "Heat ghee in a pan over medium heat; add mustard and cumin seeds and allow it crackle.", "Add the asafoetida and curry leaves and give it a stir.Pour the seasoning over the Milagu Rasam/ Miriyala Charu and give it a brisk boil for a couple of minutes.", "Turn off the heat and stir in the chopped coriander leaves.Serve the\u00a0Milagu Rasam/ Miriyala Charu\u00a0along with\u00a0steamed rice,\u00a0dondakaya vepudu\u00a0and\u00a0Elai Vadam\u00a0or you can also have serve it as a soup."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Andhra_Charu_Pepper_Rasam_Recipe_Video_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/716.Andhra_Charu_Pepper_Rasam_Recipe_Video_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('South Indian Poli Recipe - Boli | Obbattu | Bobbatlu | Holige', 'south-indian-poli-recipe-boli-obbattu-bobbatlu-holige', 'The South Indian Poli Recipe is a very traditional recipe that is made with a combination of lentils, spices and coconut. The addition of coconut along with cardamon in the filling gives the poli a rich and delicious taste.', '["Ingredients for the dough", "1-/2 cups Whole Wheat Flour", "1/4 teaspoon Turmeric powder (Haldi)", "1 tablespoon Oil", "Ghee , for serving", "Ingredients for the filling", "1 cup Arhar dal (Split Toor Dal) , or chana dal", "1-1/2 cups Jaggery", "1/2 cup Fresh coconut , optional", "1 teaspoon Cardamom Powder (Elaichi)"]'::jsonb, ARRAY['ingredients for the dough', 's whole wheat flour', 'turmeric powder', 'haldi', 'oil', 'ghee', 'ingredients for the filling', 'arhar dal', 'split toor dal', 's jaggery', 'fresh coconut', 'cardamom powder', 'elaichi']::text[], '["To begin making South Indian Poli / Obbattu / Holige\u00a0recipe, we will first make the dough for the poli.Add flour and turmeric powder into a large bowl; combine it with little water at a time and knead until the dough gathers together to form a firm dough mixture.Add the 1 tablespoon of oil to coat the dough and knead for a couple of more minutes until smooth and firm.", "Cover and let the dough sit in a cool place until we get the lentil filling ready.Cook chana dal or toor dal with 1 to 1-1/4 cups of water until soft and is well cooked.", "Drain any excess water from the dal and keep aside.Heat ghee in a pan on medium heat, add the jaggery and stir until the jaggery dissolves completely.Stir in the cooked lentils, coconut and cardamom to the jaggery mixture until well combined.Continue stirring the mixture until the filling mixture begins to thicken and leaves the sides of the pan.", "At this point turn off the heat and allow the filling mixture (puran) to cool completely.Divide the dough and puran mixture into 12 portions.Keeping a little flour for dusting handy on a plate; roll out the dough into 3 inch diameter circles.", "Place a portion of the Poli/ Holige/\u00a0Obbattu filling (puran\u00a0mixture) into the center of the circle.Bring edges of the circle towards the center and fold over to cover the entire filling; making sure the edges are all sealed well by pinching them together if there is any opening.Flatten the stuffed dough; dust the dough over a little flour and roll gently into a\u00a0 6 to 8 inch diameter circle taking care not to put too much pressure as the filling can come out of the dough.Preheat an iron skillet on medium high; place the rolled Poli/ Holige/\u00a0Obbattu onto the skillet to cook until golden brown on both sides.", "You can cook the Poli/ Holige/\u00a0Obbattu with ghee to give it a richer taste and flavor.Repeat the above process for all the remaining dough and puran portions.Serve South Indian Puran Poli/ Holige/\u00a0Obbattu\u00a0hot with ghee smeared on the top during festivals and special occasions in your family."]'::jsonb, 120, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Aashirvaad_Whole_Wheat_Holige_recipe_10_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/717.Aashirvaad_Whole_Wheat_Holige_recipe_10_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ajwaini Tamatar Bhindi Recipe', 'ajwaini-tamatar-bhindi-recipe', 'Ajwaini Tamatar Bhindi is a delicious version of bhindi which is gravy cooked in tomato gravy with a twist of ajwain flavour and can be served in lunch or dinner for your special guests.', '["500 grams Bhindi (Lady Finger/Okra)", "2 teaspoons Ajwain (Carom seeds)", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Red Chilli powder", "1 cup Homemade tomato puree", "1 teaspoon Sugar", "2 tablespoons Cashew nuts , soaked and ground to paste", "Salt , to taste"]'::jsonb, ARRAY['s bhindi', 'lady finger/okra', 's ajwain', 'carom seeds', 'asafoetida', 'hing', 'red chilli powder', 'homemade tomato puree', 'sugar', 's cashew nuts', 'salt']::text[], '["To begin making the Ajwaini Tamatar Bhindi recipe, cut bhindi into half.", "Make sure bhindi should not be wet, dry them properly.Heat oil in a heavy bottomed pan, add bhindi and stir them for a couple of minutes.", "Cook them on medium flame.Cover the lid and let it cook until done, keep stirring it in between.Once it is done, take it out from the wok.Heat oil in the same heavy bottomed pan again for the gravy.Once the oil is hot, add ajwain seeds and asafoetida powder.After a minute, add pureed tomatoes and the required red chilli powder.Let it cook on medium flame until the puree gets done.", "Add sugar, salt to taste and let it cook for some more time.Finally add the cashew paste, add salt, pre cooked bhindi and mix everything properly.", "Let the ajwaini tamatar bhindi cook for 5 more minutes and then serve hot.Serve Ajwaini Tamatar Bhindi with\u00a0Butter Garlic Naan\u00a0and\u00a0Boondi Raita\u00a0for a perfect weekday lunch."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Ajwaini_tamatar_Bhindi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/718.Ajwaini_tamatar_Bhindi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kumror/Kaddu Posto Recipe (Spiced Pumpkin with Poppy Seeds and Tomatoes )', 'kumror-kaddu-posto-recipe-spiced-pumpkin-with-poppy-seeds-and-tomatoes', 'Kumror/Kaddu Posto Recipe is a simple, quick twist to a traditional Bengali recipe of Aloo Posto. In my endeavour to experiment with vegetables and spices, this posto recipe came by chance and I must say we loved it, even my vegetable loving children ate it with delight. The subtle hint of garlic, along with lots of coriander and garam masala, makes this Kumror/Kaddu Posto a vegetarian delight.', '["500 grams Kaddu (Parangikai/ Pumpkin) , cubed", "2 Tomatoes , chopped", "2 teaspoons Poppy seeds", "2 cloves Garlic , grated", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "4 sprig Coriander (Dhania) Leaves , finely chopped", "Salt , to taste", "Red Chilli powder , to taste"]'::jsonb, ARRAY['s kaddu', 'parangikai/ pumpkin', 'tomatoes', 's poppy seeds', 's garlic', 'turmeric powder', 'haldi', 'garam masala powder', 'coriander powder', 'dhania', 'coriander', 'salt', 'red chilli powder']::text[], '["To begin making the\u00a0Kumror/Kaddu Posto Recipe, we will begin by heating a tablespoon of oil in a heavy bottomed sauce pan.", "Add in the poppy seeds and saute for a few seconds on medium heat until you get a roasted aroma.Next add in the grated garlic and saute for a few seconds.", "Then add in the spices - turmeric powder, coriander powder and garam masala powder.", "Stir for a few seconds and then finally stir in the tomatoes and the\u00a0Kumror/Kaddu.", "Finally add in the salt and red chilli powder and stir all the ingredients well until well combined and the\u00a0Kumror/Kaddu gets well coated with the masala.", "Turn the heat to low, cover the pan and cook the\u00a0Kumror/Kaddu Posto until it s soft and tender.", "You can optionally sprinkle a tablespoon of water if it becomes dry.", "The pumpkin and tomatoes release water, so most often there will not be any additional need to add water when you cook on low heat.", "Keep stirring occasionally and cook until soft.Once the\u00a0Kumror/Kaddu Posto is ready, check the salt and masala levels and adjust according to suit your taste.", "Finally stir in the chopped coriander leaves and transfer to a serving dish.Serve\u00a0Kumror/Kaddu Posto along with\u00a0Bengali luchi\u00a0and\u00a0Boondi raita\u00a0for a weekday lunch or dinner."]'::jsonb, 40, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Kumror_Kaddu_Posto_Sabzi_Recipe_Bengali_Food_with_Poppy_Seeds-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/719.Kumror_Kaddu_Posto_Sabzi_Recipe_Bengali_Food_with_Poppy_Seeds-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chow Chow Sambar Recipe (Chayote Squash Sambar)', 'chow-chow-sambar-recipe-chayote-squash-sambar', 'Sambar is a very versatile dish in the South Indian Cuisine. It pairs very well with the breakfast dishes like idli/dosa and one can also have it for lunch along with the steamed rice. Chow Chow Sambar (Chayote Squash Sambar), is one of the kinds of sambar usually had along with the steamed rice. Chow Chow, also known as chayote squash belongs to the gourd family and has a good amount of folates, making it a healthy choice for cooking.', '["1 cup Arhar dal (Split Toor Dal)", "2 cups Chow chow (chayote squash) , cut into cubes", "30 grams Tamarind , soaked in 1 cup of water", "1 Onion , sliced", "2 Tomatoes , chopped", "1 tablespoon Sambar Powder", "1/4 teaspoon Turmeric powder (Haldi)", "4 sprig Coriander (Dhania) Leaves , roughly chopped", "Oil , as required", "Salt , as required", "Ingredients for tempering", "1 teaspoon Sesame (Gingelly) Oil , or vegetable oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)", "1 Dry Red Chillies", "1 sprig Curry leaves , roughly torn"]'::jsonb, ARRAY['tomato', 'salt', 'arhar dal (split toor dal)', 'chow chow (chayote squash)', 'tamarind water', 'mustard seeds', 'asafoetida (hing)', 'curry leaves', 'coriander (dhania) leaves', 'dry red chillies', 'onion', 'sesame (gingelly) oil vegetable oil', 'turmeric powder', 'sambar powder', 'sunflower oil']::text[], '["To begin making the Chow Chow Sambar recipe, first pressure cook the toor dal along with turmeric and 2 cups of water for 2 whistles.", "Let the pressure release naturally.", "Once the dal is cooked, whisk the dal well and keep it aside.Add a teaspoon of oil in a heavy bottoemd pan and heat it on a medium flame, add the sliced onion and saute for 2 minutes till the onions turns soft and translucent.Add tomatoes, chow chow and cook till the chow chow is cooked 3/4th, stirring occasionally.Once it is done, add the tamarind extract, sambar powder, salt to taste and let it simmer until the raw smell of the tamarind goes away and the chow chow is perfectly cooked.Add the cooked toor dal, adjust the seasoning, add the roughly chopped coriander leaves and let it simmer for another 2 or 3 minutes and switch off.In another small tadka pan, add a teaspoon of sesame oil and allow it to heat.", "Once the oil is heated up, add the mustard seeds, the dry red chilies and allow it to roast until lightly browned.Add the asafoetida powder and curry leaves, stir it in and turn off the heat.Pour this tempering over the cooked sambar and it is ready to be served.", "Serve Chow-Chow Sambar with\u00a0Homemade Soft Idli\u00a0or\u00a0Masala Dosa.", "You can even serve it with Steamed Rice and Cauliflower Thoran for your vegetarian lunch or dinner."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/ChowChow_Sambar_Chayote_Squash_Sambar.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/720.ChowChow_Sambar_Chayote_Squash_Sambar.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Padpe Uppukari -  Harive Soppu Palya Recipe', 'padpe-uppukari-harive-soppu-palya-recipe', 'Padpe Uppukari Harive Soppu Palya Recipe is a lovely South Indian Style Spinach stir fry. The flavours are simple and well balanced that is made Mangalorean style with added goodness of coconut.', '["300 grams Spinach , washed and finely chopped", "1/4 cup Fresh coconut , grated", "1 Onion , finely chopped", "4 cloves Garlic , finely chopped", "2 Dry Red Chillies", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "1 pinch SSP Asafoetida (Hing)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'spinach', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'cloves garlic', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'onion']::text[], '["To begin making the Padpe Uppukari Harive Soppu Palya Recipe, heat a kadai with oil on medium flame, add the mustard seeds and allow it to splutter, next add the urad dal, a pinch of hing, dry red chillies and curry leaves as well.", "Allow the curry leaves to crackle.", "To this add chopped garlic and onions, saute till it the onions turn translucent.Finally, add the chopped spinach leaves and cook the\u00a0Harive Soppu Palya.Saute well till the spinach leaves wilts down.", "Once done, stir in the grated coconut, salt to taste and mix Harive Soppu Palya well.", "Check the taste and adjust the seasonings accordingly.", "Turn off the heat.Transfer the\u00a0Harive Soppu Palya to a serving bowl and serve warm.Serve the Padpe Uppukari Harive Soppu Palya Recipe along with\u00a0Steamed Rice, \u00a0Dali Thoy Recipe (Karwar Style Toor dal Curry)\u00a0and\u00a0Cabbage Palya Recipe\u00a0for a complete meal."]'::jsonb, 30, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Padpe_Uppukari_Harive_Soppu_Palya_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/721.Padpe_Uppukari_Harive_Soppu_Palya_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gujarati Vaghareli Mag Recipe - Whole Green Moong Dal Sabzi Recipe', 'gujarati-vaghareli-mag-recipe-whole-green-moong-dal-sabzi-recipe', 'Jain Style Whole Green Moong Dal Sabzi Recipe is a dry moong dal dish which uses absolutely no onion and no garlic, making it a Jain dish as the name suggests.', '["1 cup Green Moong Dal (Whole) , soaked overnight", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves , torn", "2 inch Ginger , finely chopped", "1 Green Chillies , finely chopped or slit", "1/2 teaspoon Turmeric powder (Haldi)", "1 Lemon , juice extracted", "6 sprig Coriander (Dhania) Leaves , finely chopped", "1 teaspoon Oil", "1 teaspoon Salt , or to taste"]'::jsonb, ARRAY['salt', 'ginger', 'green chilliesor', 'curry leaves', 'coriander (dhania) leaves', 'cumin seeds (jeera)', 'lemon', 'green moong dal', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Jain Style Whole Green Moong Dal Sabzi or Vagharela Mag, soak the moong dal overnight for about 6-7 hours.Once soaked, cook the moong dal along with salt and with 1 of water including the water that it was soaked in.", "Pressure cook for 3-4 whistles and turn off the heat.", "Allow the pressure to release naturally, ensuring the moong dal is soft, tender and still remains grainy but not mushy.", "Heat oil in a pan on medium heat; add the cumin seeds and allow them to crackle.", "Stir in the green chillies, curry leaves ginger and turmeric powder, saut\u00e9 for a few seconds.", "Add the cooked moong dal and stir gently to combine all the ingredients.Taste and adjust the salt to suit your taste.Cover Whole Green Moong Dal Sabzi / Vagharela Mag with a light fitting lid and simmer for 4 to 5 minutes until tender and all the ingredients are well combined.Finally squeeze the lemon juice, add the coriander leaves and give the Vagharela Mag a gentle stir.", "Turn off the heat and serve warm.Serve\u00a0Jain Style Whole Green Moong Dal Sabzi Recipe / Vagharela Mag with hot\u00a0Tawa Parathas\u00a0make a rich, wholesome and nutritious breakfast.", "Serve Jain Style Whole Green Moong Dal Sabzi for lunch along with\u00a0Pudina Lahsun Laccha Paratha,\u00a0Gujarati Wadi Pulao Recipe,\u00a0Boondi Raita."]'::jsonb, 30, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Gujarati_Vagharela_Mag_Recipe_Video_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/722.Gujarati_Vagharela_Mag_Recipe_Video_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mughlai Aloo Matar Gobi Recipe', 'mughlai-aloo-matar-gobi-recipe', 'Mughlai Aloo Matar Gobi as the name suggests is a typical Indian side dish higher on spicy side with the flavors of Ghee, Curd and fried onion. If you are planning Indian menu for the party than this dish would fit in well and compliments almost all kinds of dals, curries. During winter cauliflower and green peas are abundantly available in market so this recipe could be tried during the season with the best of local produce.', '["500 gram Cauliflower (gobi)", "2 Potatoes (Aloo)", "1/3 cup Green peas (Matar) , steamed", "2 Onions , thinly sliced", "2 tablespoon Curd (Dahi / Yogurt)", "2 tablespoons Ghee , plus more for shallow frying", "Salt , as per taste", "1 teaspoon Turmeric powder (Haldi)", "Ingredients to be ground into paste", "1 tablespoon Coriander (Dhania) Seeds", "1 inch Ginger", "4 cloves Garlic", "4 Cloves (Laung)", "3 Kashmiri dry red chillies", "3 Cardamom (Elaichi) Pods/Seeds , peeled with only seeds"]'::jsonb, ARRAY['cauliflower', 'gobi', 'potatoes', 'aloo', 'green peas', 'matar', 'onions', 'curd', 'dahi / yogurt', 's ghee', 'salt', 'turmeric powder', 'haldi', 'ingredients to be ground into paste', 'coriander', 'dhania', 'ginger', 's garlic', 'laung', 'kashmiri dry red chillies', 'cardamom', 'elaichi']::text[], '["To begin making the Mughlai Aloo Matar Gobi Recipe , we will first clean, wash and cut the cauliflower and potatoes in big pieces.", "Keep all the remaining ingredients handy and ready.Steam the green peas along with a little salt and a dash of sugar and keep aside.Heat 1 tablespoon of ghee; add in the sliced onions and saute until deep brown in color.", "Once done, turn off the heat and allow it to cool.", "Once it cools, make smooth paste of the onions and keep aside.Make paste of all the ingredients mentioned under \"To be ground into paste\" using 1 - 3 tablespoon of water.", "Keep the chilli paste aside.Once again in the heavy bottomed pan; add in 1 tablespoon of ghee.", "Add in the onion paste and the chilli paste and saute for about 3 to 4 minutes until you notice the aromas coming out.", "Make sure to keep the heat in low to medium heat as this can burn the spices.Once the onion and chilli paste as a good aroma, stir in the yogurt, salt and turmeric powder.", "Saute until you notice the masala has thickened.Finally add in the cut potatoes and cauliflower florets and stir into the masala until the masala get well coated onto the vegetables.", "Add in 1/2 cup of water, turn the heat to low and cover the pan.", "Allow the vegetables to cook in the Mughlai Masala for about 15 to 20 minutes or until the vegetables are softened and cooked, but not mushy.Once done, stir in the steamed green peas and finely chopped coriander leaves.", "Check the salt and spice levels and adjust to suit your taste.Serve the\u00a0Mughlai Aloo Matar Gobi along with Phulka''s or Butter Naan''s as a delicious side dish for parties or even a weeknight dinner."]'::jsonb, 35, 'Mughlai', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Hina_Gujral/Mughlai_Aloo_Matar_Gobi_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/723.Mughlai_Aloo_Matar_Gobi_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Shahi Dal Recipe', 'shahi-dal-recipe', 'Shahi Dal Recipe is a creamy and rich dal made from whole urad dal. The dal also has soaked almonds for the crunch and is then topped with sautéed onions, tomatoes, cumin seeds and red chili powder on top.  The dal is so easy to make and can be served along with any Indian breads like phulka, thepla and tawa paratha to enjoy your lunch meals. It is so comforting as well and can had with a just a steamed rice topped with some ghee.', '["1 cup White Urad Dal (Whole) , soaked for atleast 8 hours", "15 Whole Almonds (Badam) , soaked and skin peeled", "1/2 cup Milk", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "To Temper", "1 Onion , chopped", "1 Tomatoes , chopped", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Red Chilli powder", "1 Green Chilli , chopped", "Oil"]'::jsonb, ARRAY['tomato', 'salt', 'green chilli', 'milk', 'red chilli powder', 'badam (almond) skin', 'onion', 'cumin seeds (jeera)', 'white urad dal atleast', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Shahi Dal Recipe, we will first pressure cook the soaked urad dal, almonds, turmeric powder and salt.", "Pressure cook for at least 4 whistles.Heat a sauce pan with oil, add cumin seeds and allow it to splutter for few seconds.", "Add onions and saute till it is translucent.Add tomatoes and sprinkle little salt and cook until it becomes mushy.", "Add chilli powder and give it a toss for at least 2 minutes.Once the dal is cooked open the lid and add a cup of milk and put the pressure cooker back on heat and cook for another 2 minutes.Add salt and season well.", "Add the tempered onion and tomato over the top and serve hot.Serve the Shahi Dal Recipe along with\u00a0phulka,\u00a0Manipuri Style Chana Kanghou\u00a0and\u00a0Palak Raita\u00a0by the side to create a delicious lunch meal."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Shahi_Dal_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/724.Shahi_Dal_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Potato And Peas Curry Recipe In Coconut Milk Gravy', 'potato-and-peas-curry-recipe-in-coconut-milk-gravy', 'Potato And Peas In Coconut Milk Curry Recipe is a delicious and mildly spiced curry cooked in coconut milk. Potatoes and Peas are perfect match and a crowd pleaser.', '["To Make Coconut Milk", "2 cups Fresh coconut , chopped or grated", "1 cup Lukewarm Water", "3 Potatoes (Aloo) , peeled and diced", "1 cup Green peas (Matar) , steamed", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "2 Cloves (Laung)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Whole Black Peppercorns , coarsely pounded", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "1-1/2 cups Coconut milk", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'coconut milk', 'cumin powder (jeera)', 'ginger', 'salt', 'coconut', 'green peas (matar)', 'water', 'cloves garlic', 'black peppercorns', 'onion', 'coriander powder', 'potato (aloo)', 'turmeric powder', 'cloves (laung)', 'garam masala powder']::text[], '["To begin making the Potato And Peas In Coconut Milk Curry Recipe, peel, wash and cut the potatoes into cubes and keep it immersed in water to avoid discolouration.Into the zodiac mixer grinder with the super extraction blade, add the coconut and the warm water and extract the coconut milk.", "Keep the coconut milk aside.Heat oil in a pressure cooker; add the onions, ginger, garlic and saute until the onions are softened.Add the cloves, cumin powder, black peppercorns, turmeric powder and garam masala powder.", "Saute for a few seconds.Add the potato and 1/4 cup of water, salt and pressure cook the potatoes for 3 whistles.", "Once the potatoes are cooked turn off the heat and allow the pressure to release naturally.", "Once the pressure has released, open the cooker, stir in the coconut milk and steamed green peas.", "Give the potato and peas curry in coconut milk a brisk boil.", "Check the salt to taste and adjust accordingly.Serve the Potato And Peas Curry Recipe In Coconut Milk Gravy along with Phulkas\u00a0for a weeknight dinner along with\u00a0Carrot Cucumber Tomato Salad."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Potato_And_Peas_Curry_Recipe_In_Coconut_Milk_Gravy-1-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/725.Potato_And_Peas_Curry_Recipe_In_Coconut_Milk_Gravy-1-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Arbi Jhol Recipe -Uttar Pradesh Style Colocasia & Lotus Seeds Sabzi', 'arbi-jhol-recipe-uttar-pradesh-style-colocasia-lotus-seeds-sabzi', 'Arbi Jhol Recipe is Uttar Pradesh Style Colocasia & Lotus Seeds Sabzi prepared without onion and garlic. But at the same time, this sabzi is so flavourful that you will make this recipe often. Everyday spices and kasuri methi makes this gravy recipe packed with flavours.', '["10 Colocasia root (Arbi) , chopped into discs", "15 Phool Makhana (Lotus Seeds)", "2 Tomato , chopped", "2 Green Chillies , chopped", "1 inch Ginger , garted", "Oil , to cook", "1 teaspoon Cumin seeds (Jeera)", "1 pinch Asafoetida (hing)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "Salt , to taste", "Coriander (Dhania) Leaves , chopped, to garnish"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'asafoetida (hing)', 'ginger garted', 'coriander (dhania) leaves', 'red chilli powder', 'colocasia root (arbi)', 'phool makhana (lotus seeds)', 'cumin seeds (jeera)', 'kasuri methi (dried fenugreek leaves)', 'coriander powder', 'turmeric powder', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To begin making Arbi Jhol Recipe - Colocasia & Lotus Seeds Sabzi, wash, peel and cut colocasia roots into discs of uniform thickness (uniformity will help in even cooking).Take a shallow frying pan and shallow fry colocasia pieces with a little oil till they are a little crisp.", "Keep aside.In the same pan, roast lotus seeds till crisp.", "Keep asideIn a mixer, grind tomato, green chilli and ginger and take out in a bowl.Heat a kadai with a little ghee/oil.", "Once the oil is hot, add cumin seeds and let it sizzle.", "Add hing to the oil and once the hing releases its aromas add the\u00a0tomato puree with chilli and ginger.Add salt and saute till you feel that the puree is cooked well and it starts coming together.Next, add dry roasted colocasia, salt to taste, and about a cup of water.", "Mix well, simmer and close the lid and cook for 5-6 minutes.When you feel that the colocasia/arbi is almost cooked, add roasted lotus seeds.", "Simmer and bring to boil for 2-3 minutes such that the taste is seeped in well into both arbi and lotus seeds.Finally add garam masala, and crushed kasoori methi to the Arbi Jhol.", "Mix well and switch off.", "Garnish Arbi Jhol with chopped coriander leaves and serve.Serve Arbi Jhol Recipe - Uttar Pradesh Style Colocasia & Lotus Seeds Sabzi with Pudina Tawa Paratha, Baingan Ka Chokha Recipe, steamed rice and Dal Tadka Recipe Flavored with Lemon and Coriander."]'::jsonb, 30, 'Uttar Pradesh', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/_Arbi_Jhol_UP_Style_Colocasia_Sabzi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/726._Arbi_Jhol_UP_Style_Colocasia_Sabzi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Fansi Muthia Nu Shaak Recipe - Green Beans With Gram Flour Dumplings', 'fansi-muthia-nu-shaak-recipe-green-beans-with-gram-flour-dumplings', 'Fansi Muthia Nu Shaak Recipe is a very famous Gujarati Recipe that has a stir fried green beans and muthia that are made from roasted gram flour. Muthias are nothing but dumplings that add a different texture to the dish when added.', '["400 grams Green beans (French Beans) , cut into 1 inch pieces", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Ajwain (Carom seeds)", "1/4 teaspoon SSP Asafoetida (Hing)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Jaggery", "Salt , to taste", "1 teaspoon Oil", "1/2 cup Gram flour (besan)", "2 tablespoons Kasuri Methi (Dried Fenugreek Leaves)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Sugar", "1/4 teaspoon SSP Asafoetida (Hing)", "1/2 teaspoon Enos Fruit Salt", "1 tablespoon Lemon juice", "1 tablespoon Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'green beans (french beans)', 'enos fruit salt', 'amchur (dry mango powder)', 'asafoetida (hing)', 'mustard seeds', 'ajwain (carom seeds)', 'jaggery', 'red chilli powder', 'gram flour (besan)', 'sugar', 'lemon', 'coriander powder', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'sunflower oil']::text[], '["To begin making the Fansi Muthia Nu Shaak Recipe, add\u00a0the green beans into a pressure cooker, with 1/4 cup of water, salt to taste and pressure cook for 2 whistles.", "Turn off the heat and release the pressure immediately to retain the bright green color of the beans.", "Open the pressure cooker and keep aside.*To make the Muthia:In a small bowl combine the ingredients for the muthia -\u00a0Gram flour,\u00a0kasuri methi, turmeric powder, sugar, asafoetida, enos fruit salt, lemon juice, cooking oil and salt.", "Combine to make a firm dough by adding little water.", "Divide the dough into equal small portions.", "Shape them in ovals and lightly press them down.", "Preheat a paniyaram pan and add little oil into each cavity.", "Place the muthia in each cavity and pan fry until golden and crisp on all sides.", "Once done remove and keep aside.*The next step is to make the Fansi Muthia Nu Shaak:Heat a teaspoon of oil in a heavy bottomed pan over medium heat; add the ajwain seeds,\u00a0 mustard seeds and allow them to crackle.After the seeds crackle, add asafoetida\u00a0and the cooked green beans.After a minute, add the coriander powder, red chilli powder, amchur powder, turmeric powder, jaggery, muthia and saute until well combine.", "Cover and allow it to steam cook for two minutes and turn off the heat.", "Transfer Fansi Muthia Nu Shaak into a serving bowl and serve.Serve the\u00a0Fansi Muthia Nu Shaak Recipe\u00a0along with\u00a0Gujarati Kadhi,\u00a0Phulka\u00a0and\u00a0Steamed Rice\u00a0to enjoy your everyday simple lunch."]'::jsonb, 40, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Fansi_Muthia_Nu_Shaak_Video_Recipe_Gujarati_Beans_Muthia_Sabzi_12_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/727.Fansi_Muthia_Nu_Shaak_Video_Recipe_Gujarati_Beans_Muthia_Sabzi_12_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Masoor Dal Makhni Recipe', 'masoor-dal-makhni-recipe', 'Masoor Dal Makhni is a delicious, creamy and healthy lentil recipe. Masoor Dal is considered to be very healthy as compared to other lentils. It is a mildly spiced nutrients enriched dish which is perfect to serve for a weeknight dinner.', '["1 cup Masoor Dal (Whole)", "1 Onion , finely chopped", "1 Tomato", "6 cloves Garlic", "2 inch Ginger", "1 Bay leaf (tej patta)", "2 Cloves (Laung)", "1 teaspoon Cumin seeds (Jeera)", "1 Cinnamon Stick (Dalchini)", "2 teaspoon Garam masala powder", "1 teaspoon Red Chilli powder", "2 teaspoon Coriander Powder (Dhania)", "2 tablespoons Ghee", "2 teaspoon Fresh cream", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'bay leaf (tej patta)', 'ghee', 'red chilli powder', 'cloves garlic', 'onion', 'cumin seeds (jeera)', 'cinnamon stick (dalchini)', 'cloves (laung)', 'coriander powder', 'masoor dal', 'garam masala powder']::text[], '["To begin making the Masoor Dal Makhni Recipe, wash the whole masoor dal in running tap water until the water turns clear.Soak the washed masoor dal in lukewarm water for about 30 minutes.Heat ghee in a pressure cooker, add the whole spices, cinnamon, cloves, cinnamon, cumin seeds and let it sputter.Add the finely chopped onion and saut\u00e9 till it turns brown.Now gently crush the ginger and garlic pods in a mortar and pestle and add the mix into the pressure pan.", "Saut\u00e9 till the raw aroma of ginger and garlic goes away.Add the chopped tomatoes and the dry spices coriander powder, red chilli and garam masala and cook until the tomatoes get mushy and the ghee starts to leave the sides.To this add the soaked who masoor dal, enough water to cook and salt to taste.Pressure cook this for 4-5 whistles in low flame.", "Switch off and let the pressure subside.Open the lid gently and add the cream to make it richer.Masoor Dal Makhni is best served along with rice or paratha''s and green salad."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Masoor_Dal_Makhni_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/728.Masoor_Dal_Makhni_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('No Onion No Garlic Cabbage Kofta Curry Recipe', 'no-onion-no-garlic-cabbage-kofta-curry-recipe', 'The festivals are arriving and this is the time when some particular religious communities quit eating Onion and Garlic. As India is a multi cultural country, hence their are certain casts who never intake onion garlic, such as Jainism. In Jain community the intake of Onion and Garlic is strictly prohibited, or anything that grows beneath the soil is not acceptable to eat. Thankfully our food culture is so vast that for every ingredient we have some substitutes ready. Hence making a No Onion No Garlic Cabbage Kofta Curry was over all a great experience. Grated cabbage mixed with Indian spices and bind with gram flour is later shaped into balls and deep fried. The curry has a great use of tomato, gram flour and fresh cream to give texture, colour and flavour to the gravy.', '["2 cups Cabbage (Patta Gobi/ Muttaikose) , grated", "1/2 cup Gram flour (besan)", "1 Green Chilli , chopped", "2 tablespoons Coriander (Dhania) Leaves , chopped", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Garam masala powder", "1 pinch Turmeric powder (Haldi)", "1/2 teaspoon Salt , to taste", "1 cup Oil , for deep frying", "3 Tomatoes , large tomatoes, pureed", "1 tablespoon Ginger , made into paste", "1/2 cup Gram flour (besan)", "3 to 4 tablespoons Fresh cream", "2 tablespoons Curd (Dahi / Yogurt) , optional", "1-1/2 tablespoons Coriander Powder (Dhania)", "1 tablespoons Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Garam masala powder", "1 to 2 Bay leaf (tej patta)", "1/2 teaspoon Cardamom (Elaichi) Pods/Seeds , freshly crushed", "Salt , to taste", "Oil , as required", "1 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'ginger', 'garam masala powder', 'green chilli', 'coriander (dhania) leaves', 'bay leaf (tej patta)', 'cardamom (elaichi) podsseeds', 'red chilli powder', 'gram flour (besan)', 'tomato large tomato', 'curd', 'coriander (dhania) leaves', 'coriander powder', 'turmeric powder', 'cabbage (patta gobi muttaikose)', 'sunflower oil']::text[], '["To begin making the No Onion No Garlic Cabbage Kofta Curry recipe, grate cabbage and press in batches to remove excess water.Collect the dry grated cabbage in a large mixing bowl.Add besan, green chili, coriander, cumin powder, turmeric, garam masala, red chili powder and salt.", "Stir well to make a dry mix.Heat oil in a kadhai/wok and meanwhile make medium lemon sized kofta balls out of the mix and keep aside in a plate.Once the oil is hot, drop the kofta balls carefully in the wok.", "Do not crowd the wok, add 4-5 at a time and fry till golden in colour.Collect the fried kofta balls on a kitchen towel to absorb excess oil.In a separate kadhai/wok, heat oil to make the curry.Add bay leaf and within few seconds add grated ginger and saute.Now add besan and roast it for few seconds and immediately add the tomato puree in it and stir nicely.Add coriander powder, red chilli powder, turmeric powder, cumin powder and garam masala powder and fry the masala till oil starts leaving from sides.Now add 2 tablespoons of curd (you can skip this step if you want) and fry for another minute or so.Once the masala starts smelling good, add fresh cream and mix nicely.Cook for another 2-3 mins and then add water to make the curry.", "The curry is thick hence be careful while adding water.Adjust salt and let the curry come to a boil.Simmer the gas, add freshly crushed cardamom and cook the curry for another 5 mins in low flame with lid closed.Once the curry is done, drop in the fried kofta balls and turn off the gas.Transfer the curry in a serving bowl and add a swirl of fresh cream to garnish along with some fresh coriander.Serve No Onion No Garlic Cabbage Kofta Curry with\u00a0Pudina Tawa Paratha\u00a0and\u00a0Tomato Onion Cucumber Raita\u00a0for your delicious weekday meal."]'::jsonb, 65, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shaheen_Ali/Cabbage_Kofta_Curry_No_OnionNo_Garlic.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/729.Cabbage_Kofta_Curry_No_OnionNo_Garlic.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tadkewali Masoor Dal Recipe - High Protein Masoor Dal Recipe', 'tadkewali-masoor-dal-recipe-high-protein-masoor-dal-recipe', 'Tadkewali Masoor Dal Recipe is a simple recipe made in a pressure cooker with the most basic ingredients. The masoor dal is soaked for a couple of hour and then pressure cooked along with the ginger garlic onions and simple masalas and given a hing and red chilli tadka.', '["1 tablespoon Ghee", "1/4 teaspoon Asafoetida (hing)", "1 Onion , finely chopped", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "2 Green Chillies , finely chopped", "2 Tomatoes , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Garam masala powder", "Salt , to taste", "1 cup Masoor Dal (Whole)", "2-1/2 cups Water", "Coriander (Dhania) Leaves , small bunch, chopped", "1 tablespoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "1/4 teaspoon Red Chilli powder"]'::jsonb, ARRAY['ghee', 'asafoetida', 'hing', 'onion', 'ginger', 's garlic', 'reen chillies', 'tomatoes', 'turmeric powder', 'haldi', 'red chilli powder', 'garam masala powder', 'salt', 'masoor dal', 'whole', 's water', 'coriander', 'dhania', 'cumin seeds', 'jeera']::text[], '["To begin making the Tadkewali Masoor Dal recipe, wash masoor dal well and soak for 3 to 4 hours.", "Heat ghee in the pressure cooker over medium heat.", "Add the asafoetida into the ghee, along with it add the ginger, garlic, onion and saute until the onions soften a bit.Once the onions soften, add the chopped tomatoes, turmeric powder, red chilli powder and garam masala powder.", "Stir for a few seconds and add the soaked masoor dal, salt to taste along with 2-1/2 cups of water.", "Cover the pressure cooker and cook for 3 to 4 whistles.", "After 3 to 4 whistles, turn the heat to low and simmer for another 5 minutes and then turn off the heat.Allow the pressure to release naturally.", "Once the pressure releases, open the cooker and stir in the coriander leaves.", "Check the salt and spices and adjust to taste accordingly.", "Transfer the Masoor Dal to a serving bowl.For the tadka, heat ghee in a pan over medium heat.", "Add the cumin seeds, asafoetida and red chilli powder.", "Stir for a few seconds and pour the tadka over the Masoor Dal.Serve Tadkewali Masoor Dal along with\u00a0Kachumber Salad,\u00a0Palak Raita\u00a0and\u00a0Phulkas\u00a0for a weekday meal."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Recipe_For_Beginners_One_Pot_Tadkewali_Masoor_Dal_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/730.Recipe_For_Beginners_One_Pot_Tadkewali_Masoor_Dal_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Cheesy Aloo Paratha Recipe', 'cheesy-aloo-paratha-recipe', 'Aloo parathas are Indian Potato Flatbread made from whole wheat flour and stuffed with a spicy mixture of onions and potatoes. These Parathas are a bit different from the usual aloo parathas. They are stuffed with a combination of potatoes, onions and cheese. You will love this twist to the routine aloo parathas.', '["1 cup Whole Wheat Flour", "1 teaspoon Oil", "1/4 teaspoon Salt", "Water , required for kneading", "2 Potato (Aloo) , boiled, peeled and mashed", "1 teaspoon Oil", "1 Dry Red Chilli , broken and deseeded", "1/2 teaspoon Cumin seeds (Jeera)", "Asafoetida (hing) , a pinch", "1 Green Chillies , finely chopped", "1 inch Ginger , grated", "1 Onion , finely chopped", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Chaat Masala Powder", "1/4 cup Cheese , processed and grated", "4 sprig Coriander (Dhania) Leaves , finely chopped", "Salt , to taste"]'::jsonb, ARRAY['salt', 'wheat flour', 'ginger', 'cumin powder (jeera)', 'cheese processed', 'asafoetida (hing)', 'potato (aloo)', 'chaat masala powder', 'water', 'dry red chilli', 'coriander (dhania) leaves', 'onion', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["In a wide bowl, add wheat flour, salt, oil, needed water and prepare a soft and smooth dough.", "Cover and keep it aside for 15-20 minutes.", "Dough should not be too hard.The next step is to prepare the stuffing.", "Pressure cook potatoes for 3 whistles or until soft.", "Peel the skin and mash them well.Heat oil in a non-stick pan.", "Add dry red chili and cumin seeds.Once it splutters, add hing/asafoetida, finely chopped onions, green chillies, ginger and pinch of salt and saute until onions turn transparent.", "Adding salt while cooking onions, prevents it from sticking and getting burnt.Then add the mashed potatoes, turmeric powder, coriander powder, cumin powder, kitchen king masala powder/ garam masala powder, chaat masala and salt and saute for 3-4 minutes till everything gets blended well.Be careful while adding salt at this stage, as we have added a pinch of salt to onions.", "Plus we are using chaat masala and cheese, so the stuffing will require less salt than usual.", "Check the salt level and add salt accordingly.Lastly, add 1/4 cup grated cheese and finely chopped coriander leaves, mix well and leave it to cool.Before starting to make parathas, knead the dough well.", "If needed, use 1/2 teaspoon oil and knead till it becomes smooth and soft.Divide the dough and stuffing into equal parts and make balls out of it.", "This will make 4 parathas.Dust a little flour and roll out the dough into a small circle.Keep stuffing in the center, gather all the corners and seal the dough with the stuffing inside.", "Press it down gently to flatten it.Dust a little four and roll it again very gently, so that stuffing doesn\u2019t come out.Heat a tawa/non stick pan and place the paratha.Cook the paratha using little oil/butter/ghee till golden brown spots appears on both sides.", "Repeat the same steps to make more parathas.Serve Cheesy Aloo Paratha along with\u00a0Boondi Raita\u00a0and\u00a0Dhaniya Pudina Chutney\u00a0for a filling breakfast or serve it for weekday dinner."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/6-march/Cheesy_Aloo_Stuffed_Paratha_Recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/731.Cheesy_Aloo_Stuffed_Paratha_Recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pui Shaager Chorchori Recipe - Mixed Vegetable Curry With Malabar Spinach', 'pui-shaager-chorchori-recipe-mixed-vegetable-curry-with-malabar-spinach', 'Pui Shaager Chorchori Recipe is a traditional Bengali vegetable side dish that can be made for your everyday meals. In Bengali Chorchori means a combination of vegetables.', '["3-4 cups Malabar Spinach Leaves , as well as stalks chopped into big pieces", "1 cup Kaddu (Parangikai/ Pumpkin) , cut into big pieces", "1/2 cup Mooli/ Mullangi (Radish) , cut into small pieces", "1/2 cup Potato (Aloo) , cut into small pieces", "1 cup Brinjal (Baingan / Eggplant) , cut into big pieces", "1/2 teaspoon Panch Phoran Masala", "2-3 Dry Red Chillies", "2 tablespoons Mustard oil , or vegetable oil", "1 teaspoon Cumin powder (Jeera)", "Salt , to taste", "1 teaspoon Sugar , optional", "1/2 teaspoon Turmeric powder (Haldi)"]'::jsonb, ARRAY['s malabar spinach leaves', 'kaddu', 'parangikai/ pumpkin', 'mooli/ mullangi', 'radish', 'potato', 'aloo', 'brinjal', 'baingan / eggplant', 'panch phoran masala', 'dry red chillies', 's mustard oil', 'cumin powder', 'jeera', 'salt', 'sugar', 'turmeric powder', 'haldi']::text[], '["To begin making the Pui Shaager Chorchori Recipe, firstly we will wash the vegetables and the leaves well in water.", "Keep them aside.", "Heat mustard oil in a heavy bottomed pan on low heat.", "Once hot, add 1/2 teaspoon of panch phoran masala, followed by red chillies.After 30 seconds, add the pieces of pumpkin, radish, potato, eggplant and saute them well.", "Now add the spinach leaves to the vegetables and sprinkle some water for the vegetables to cook.You can also cook the pumpkin and potatoes in pressure cooker first for one whistle.Simultaneously, cook the rest of the vegetables in a kadai with water, add the spinach and cooked pumpkin and potato to this once done.", "To this add salt, turmeric powder and cumin powder.", "Cover and cook for 15 to 20 minutes till the vegetables are tender.", "The vegetables should be well cooked and tender.", "Stir the vegetables well and add a teaspoon of sugar (optional) and mix well.Break 2-3 whole green chillies and add to the Pui Shaager to spice up the dish a little.If the vegetable feels dry, add some water and cook.", "Once done, switch off the gas and serve hot.Serve\u00a0Pui Shaager Chorchori\u00a0along with\u00a0Bengali Style Cholar Dal\u00a0and\u00a0Steamed Rice\u00a0for your everyday meals.", "You can also serve\u00a0Begun Bhaja\u00a0along with this meal."]'::jsonb, 25, 'North East India', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/28-march/Pui_Shaager_Chorchori_Recipe_Malabar_Spinach_pumpkin_ridge_gourd_potato_Sabzi-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/732.Pui_Shaager_Chorchori_Recipe_Malabar_Spinach_pumpkin_ridge_gourd_potato_Sabzi-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vazhakkai Milagu Kootu Recipe - Plantains Pepper Curry', 'vazhakkai-milagu-kootu-recipe-plantains-pepper-curry', 'Vazhakkai Milagu Kootu is a delicious recipe of plantain stem,cooked in a curry made from freshly roasted masala, that adds great flavours to the curry.', '["2 Plantain Stem , cut into cubes", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 Dry Red Chilli", "Salt , to taste", "2 teaspoon Oil", "Ingredients for the pepper masala", "3 tablespoons Fresh coconut , grated", "2 teaspoons Chana dal (Bengal Gram Dal)", "2 teaspoons Whole Black Peppercorns", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "1 Dry Red Chilli", "1 teaspoon Oil"]'::jsonb, ARRAY['salt', 'mustard seeds', 'coconut', 'asafoetida (hing)', 'plantain stem', 'black peppercorns', 'dry red chilli', 'white urad dal (split)', 'cumin seeds (jeera)', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making the Vazhakkai Milagu Kootu , make cuts on the layer of banana stem and then discard the outer covering.", "Slice the banana stem and as you do, you will find the fibre coming out every time you slice into stem, keep taking them out while proceeding.", "Once sliced, take each slice and chop them to about 1 cm pieces and then keep it immersed in a bowl of water until further use to avoid discolouration.To make the pepper masala, heat oil in a small tadka pan, add the chana dal, pepper corns, asafoetida, red chilli and roast till the dal becomes golden brown.Add this to the mixer jar, add the grated coconut, cumin seeds and make a smooth paste adding little water at a time.", "Keep aside.Drain the cut plantains from water and add it to a saucepan, add a cup of water, season with salt and cook until soft.", "This will take around 10 minutes.To this add the prepared pepper masala, mix well and let it simmer for 5 minutes.Now, make a tadka by heating oil in a small todka pan, add the mustard seeds, urad dal, red chilli, curry leaves.Once it splutters, add this to the simmering\u00a0Vazhakkai Milagu Kootu, mix well and switch off the heat and serve hot.", "Serve this\u00a0Vazhakkai Milagu Kootu, along with\u00a0Steamed Rice\u00a0and\u00a0Jeera Rasam\u00a0for a simple meal for a weekday lunch."]'::jsonb, 20, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Vazhakkai_Milagu_Kootu_Plantains_Pepper_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/733.Vazhakkai_Milagu_Kootu_Plantains_Pepper_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan style Caril De Camarao Recipe (Prawn Curry Recipe)', 'goan-style-caril-de-camarao-recipe-prawn-curry-recipe', 'Goan style Caril De Camarao Recipe (Prawn Curry Recipe) is a simple prawn curry that can be made quickly with few ingredients. The curry has a coconut base which is spicy and as well as tangy by the use of tamarind pulp. Traditionally ground coconut are used to make this rich curry but we have changed and added coconut milk to suit the busy home cooks keeping the flavors also intact. Fresh prawns are the best to add more flavor to this dish. The goan cuisine is famous for its seafood and spicy flavor that are ground with whole spices. The cuisine also has slight influence with Portuguese as well.', '["300 grams Prawns , shelled and deveined", "1 Onion , chopped", "1 cup Coconut milk", "1 teaspoon Turmeric powder (Haldi)", "2 teaspoon Red Chilli powder", "3 teaspoon Coriander Powder (Dhania)", "1 tablespoon Tamarind Paste", "1 Lemon juice", "Salt , to taste", "Oil"]'::jsonb, ARRAY['salt', 'coriander powder', 'red chilli powder', 'onion', 'lemon', 'tamarind paste', 'coconut milk', 'turmeric powder', 'prawns', 'sunflower oil']::text[], '["To begin making the Goan style Caril De Camarao Recipe, we will heat a skillet with oil, add onions and saute until it is light brown.Add all the spice powders along with fresh prawns and saute until the prawns curl up.Add coconut milk, tamarind paste, lemon juice and check for salt.", "Stir well, cook in simmer for about 10 minutes.", "Switch off the heat and serve hot.Serve the Goan style Caril De Camarao Recipe along with\u00a0parotta\u00a0or just\u00a0steamed rice\u00a0with rava fry to go along with to make it a complete meal."]'::jsonb, 25, 'Goan', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Goan_style_Caril_De_Camarao_Recipe_Prawn_Curry_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/734.Goan_style_Caril_De_Camarao_Recipe_Prawn_Curry_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sindhi Karela Bhaji Recipe - Sindhi Style Bitter Gourd Sabzi', 'sindhi-karela-bhaji-recipe-sindhi-style-bitter-gourd-sabzi', 'Sindhi Karela Bhaji Recipe is a delectable bitter gourd side dish cooked in Sindhi style. Though bitter gourds are bitter, here it is cooked in a tangy onion, tomato and yogurt based curry, which makes its taste much palatable.', '["2 Karela (Bitter Gourd/ Pavakkai) , cut into roundels", "2 Onions , thinly sliced", "2 Tomatoes , finely chopped", "1/4 cup Curd (Dahi / Yogurt)", "2 Green Chillies , finely chopped", "1 inch Ginger , finely chopped", "5 cloves Garlic , finely chopped", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Kashmiri Red Chilli Powder", "2 teaspoons Coriander Powder (Dhania)", "1/2 teaspoon Cardamom Powder (Elaichi)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Anardana Powder (Pomegranate Seed Powder)", "Coriander (Dhania) Leaves , finely chopped, for garnish", "1 tablespoon Oil", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'kashmiri red chilli powder', 'karela (bitter gourd pavakkai)', 'coriander (dhania) leaves', 'anardana powder (pomegranate seed powder)', 'cloves garlic', 'curd', 'onion', 'cumin seeds (jeera)', 'cardamom powder (elaichi)', 'coriander powder', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Sindhi Karela Bhaji Recipe, in a pressure cooker, add the karela along with 2 tablespoons water and salt.", "Pressure cook for two whistles and turn off the heat.Release the pressure immediately by running cold water over the pressure cooker.", "Releasing the pressure immediately prevent the karela from getting over cooked.", "Keep aside.Heat oil in a kadai on medium flame, add the cumin seeds and allow it to sizzle.", "Once the seeds have sizzled add the ginger and garlic, green chillies and saute for about 30 seconds.", "Now add onions and saute until it softens and turns golden brown.", "Once the onions have turned slightly brown; add the chopped tomatoes, mix well and cook until the tomatoes are mushy.Once the tomatoes are cooked, add the turmeric powder, kashmiri red chilli powder, coriander powder, cardamom powder, anardana, salt and mix well to combine.", "Cook for about 2 to 3 minutes until the masala comes together for the Karela bhaji.After the masala is cooked through add the yogurt and cook for a few minutes.Finally add the\u00a0pre cooked\u00a0Karela\u00a0into the pan.", "Sprinkle some water and cover and let the Sindhi Karela\u00a0Bhaji\u00a0simmer for 5 minutes.", "Once done, check the salt and spices and adjust accordingly.", "Turn off the heat and stir in the coriander leaves.", "Transfer Karela Bhaji into a serving bowl and serve.", "Serve the\u00a0Sindhi Karela Jo Bhaji Recipe\u00a0along with\u00a0Sindhi Tidali Dal Recipe\u00a0and\u00a0Jowar Jo Dodo Recipe - Sindhi Sorghum Roti\u00a0for a simple Sindhi meal."]'::jsonb, 40, 'Sindhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Sindhi_Karela_Bhaji_Recipe_27_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/735.Sindhi_Karela_Bhaji_Recipe_27_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Lady Fish Curry Recipe - Muddoshi Hooman', 'goan-lady-fish-curry-recipe-muddoshi-hooman', 'No coastal cuisine is complete without fish curries. In Goa, fish curry will be cooked almost everyday for lunch. Since various types of fish are available in Goa, various types of fish curries can be made and the recipe differs according to the type of fish used.', '["2 Lady fish", "1/2 cup Fresh coconut , grated", "20 grams Tamarind", "1 teaspoon Turmeric powder (Haldi)", "1 Mooli/ Mullangi (Radish)", "4 Dry Red Chillies", "3 Whole Black Peppercorns", "1/2 teaspoon Coriander (Dhania) Seeds", "1/2 cup Onion , chopped", "1 teaspoon Oil", "1 tablespoon Turmeric powder (Haldi)", "1/2 tablespoon Red Chilli powder", "1 teaspoon Salt"]'::jsonb, ARRAY['salt', 'coconut', 'lady fish', 'red chilli powder', 'black peppercorns', 'dry red chillies', 'mooli mullangi (radish)', 'coriander (dhania) seeds', 'onion', 'tamarind', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Goan Lady Fish Curry Recipe, clean and cut the fish into 2-3 pieces.", "Wash and keep aside.Marinate by applying turmeric powder, red chilli powder, salt and keep it aside for a minimum of 30 minutes.Separately cut the radish into 2 inch long fingers and boil them separately.The next step is to make the gravy.", "Grind, grated coconut, turmeric powder, tamarind, peppercorns, coriander and red chillies by adding 1/2 cup water to make a thin gravy in a mixer grinder.In a heavy bottomed pan, add oil and fry the chopped onions till they turn brownish.Add the fish and cook on medium flame for about 2 minutes.", "Pour the gravy and stir.", "Add 1/2 cup of water in the same.Add the radish and boil for 10 minutes more by covering the utensil.", "Serve hot.Serve\u00a0Goan Lady Fish Curry\u00a0either for lunch or dinner with\u00a0Steamed Rice,\u00a0Rava Fried Prawns, Salad and pickle and enjoy a delicious Goan meal."]'::jsonb, 40, 'Goan', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Goan_Lady_Fish_Curry__Muddoshi_Hooman.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/736.Goan_Lady_Fish_Curry__Muddoshi_Hooman.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Chicken Roast Recipe | Chicken Ghee Roast Recipe', 'chettinad-chicken-roast-recipe-chicken-ghee-roast-recipe', 'This Chettinad Chicken Roast Recipe is a semi gravy recipe that you can either serve as a starter or a side dish with your meal. This Chicken recipe is flavoured with whole spices, gets its zing from the tamarind and sweet from the jaggery. Above all, the flavour of ghee takes this recipe to a different level altogether.', '["500 grams Chicken , with legs and bones", "1/4 cup Hung Curd (Greek Yogurt)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 teaspoon Oil", "1 Onion , sliced", "8 cloves Garlic", "1 inch Ginger", "2 tablespoon Fresh coconut , grated", "2 teaspoon Cumin seeds (Jeera)", "2 teaspoons Coriander (Dhania) Seeds", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1/4 teaspoon Kalonji (Onion Nigella Seeds)", "1 teaspoon Whole Black Peppercorns", "2 Dry Red Chillies", "1 teaspoon Fennel seeds (Saunf)", "1/2 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "1 Cardamom (Elaichi) Pods/Seeds", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "Other ingredients for Chettinad Chicken Masala", "1 teaspoon Tamarind Paste", "1 teaspoon Jaggery", "3 teaspoons Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "6 cloves Garlic , crushed", "4 cloves Garlic"]'::jsonb, ARRAY['s chicken', 'hung curd', 'greek yogurt', 'turmeric powder', 'haldi', 'salt', 'oil', 'onion', 's garlic', 'ginger', 'fresh coconut', 'cumin seeds', 'jeera', 's coriander', 'dhania', 'methi seeds', 'fenugreek seeds', 'kalonji', 'onion nigella seeds', 'whole black peppercorns', 'dry red chillies', 'fennel seeds', 'saunf', 'cinnamon stick', 'dalchini', 'laung', 'cardamom', 'elaichi', 'mustard seeds', 'rai/ kadugu', 'other ingredients for chettinad chicken masala', 'tamarind paste', 'jaggery', 's ghee', 'curry leaves']::text[], '["To begin making the Chettinad Style Chicken Roast Recipe, thoroughly wash and clean the chicken leg.", "Keep it aside.", "Heat oil in a heavy bottomed pan, on medium flame.", "Add onions, ginger and garlic and cook till the onions become soft.", "Once the onions turn soft add the coconut and allow it to turn light brown in colour.Turn off the heat and grind the onion, garlic, ginger and coconut mixture to a coarse paste in mixer grinder.The next step is to marinate the chicken.", "In a mixing bowl, add the onion coconut paste, yogurt, turmeric powder and chicken legs.Mix everything well and ensure that the chicken is well coated with the masala.", "Keep it aside for 30 minutes.*For the Chettinad Spice MixHeat a heavy bottomed pan, add chettinad spice mix ingredients -\u00a0 cumin seeds, coriander seeds, fenugreek seeds, kalonji, black peppercorn, dry red chillies, fennel seeds, cinnamon stick, cloves, cardamom and mustard seeds.Dry roast them for about 2 minutes until you can smell the aromas coming though.", "Once done, let it cool.Once the chettinad spice mix is cooled, add it to the mixer grinder and blend to make a powder.Heat ghee in the same pan over medium heat.", "Add the mustard seeds, curry leaves and allow the seeds to crackle.", "Add the crushed garlic and saute for a few seconds.After 30 seconds, add the Marinated chicken along with all the marinade masala.Mix everything well, add the tamarind paste, jaggery and 1/4 cup of water.", "Cover the pan and cook for about 8 to 10 minutes or till the chicken is cooked through.Once the chicken is cooked, it will have a gravy like consistency.", "You can make it a thick gravy by opening the lid and cooking it for another couple of minutes until a little moisture evaporates and you have the right consistency for the Chettinad Chicken.Once done, check the taste and adjust salt and spices and turn off the heat.Transfer the Chettinad Chicken / Chicken Ghee Roast to a serving bowl and serve hot.", "You can optionally add more garlic tadka over the chicken to enhance the taste.Serve this\u00a0Chettinad Chicken Recipe/ Chicken Ghee Roast\u00a0on its own as a party starter or\u00a0with\u00a0Kerala Style Appam Recipe\u00a0or\u00a0Mangalorean Neer Dosa Recipe\u00a0for a complete meal."]'::jsonb, 35, 'Chettinad', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sneha-archanaskitchen.com/Chettinad_Style_Chicken_Roast_Recipe_semigravy_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/737.Chettinad_Style_Chicken_Roast_Recipe_semigravy_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Pepper Chicken Recipe - Dry Restaurant Style Pepper Chicken', 'andhra-pepper-chicken-recipe-dry-restaurant-style-pepper-chicken', 'Andhra Pepper Chicken Recipe is a delicious chicken recipe famous across most Andhra Non Veg Restaurants. which you can serve either as a starter or as a side dish along with your meal. The', '["500 grams Chicken , chopped to cubes with bone", "10 cloves Garlic", "2 inch Ginger", "1 Lemon , juice extracted", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Salt", "2 Onion , thinly sliced", "4 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "2 Green Chillies , slit", "Salt , to taste", "3 sprig Curry leaves , roughly torn", "2-1/2 tablespoons Whole Black Peppercorns , coarsely pounded", "2 teaspoons Coriander Powder (Dhania)", "4 tablespoons Oil , to cook", "To Garnish", "6 sprig Coriander (Dhania) Leaves , chopped for garnish", "1 teaspoon Whole Black Pepper Corns , coarsely pounded", "1 teaspoon Lemon juice"]'::jsonb, ARRAY['s chicken', 's garlic', 'ginger', 'lemon', 'turmeric powder', 'haldi', 'salt', 'onion', 'reen chillies', 'curry leaves', 's whole black peppercorns', 's coriander powder', 'dhania', 's oil', 'to garnish', 'coriander', 'whole black pepper corns', 'lemon juice']::text[], '["To begin making Andhra Pepper Chicken Recipe, prep all the ingredients and keep ready.", "For the marination, make the paste of the ginger and garlic.", "You can use the mixer grinder or a pestle and mortar to make the paste.", "Into a large mixing now, add the chicken pieces along with bones, turmeric powder, ginger garlic paste, lemon juice and salt.", "Mix well to combine.", "Cover the pan, place it in the refrigerator and marinate the chicken for 30 minutes.To make the Andhra Pepper Chicken, in a large wok or a kadai or a deep pan preheat the oil over medium heat.Add the sliced onion, sliced green chillies, chopped ginger and chopped garlic and saute until the onion softens and turns slightly brown.", "Stir in the curry leaves\u00a0Once the onions start to brown, add the marinated chicken and saute for about 2 minutes with the onion ginger garlic masala.", "After couple of minutes, add the coriander powder and crushed pepper.", "Stir well, cover the pan and cook on low heat until the Andhra Pepper Chicken comes together from sides of the pan.Keep stirring intermittently and sprinkle water as and when required to cook the chicken.Cook until the Andhra Pepper Chicken until it is tender and cooked.", "Once the chicken is soft cooked, open the lid and stir on medium heat until the moisture evaporated to make it dry.Just before you are ready to serve add another 1 teaspoon crushed pepper, 1 teaspoon lemon juice and chopped coriander leaves and give it a stir.Serve\u00a0Andhra Pepper Chicken Recipe along with\u00a0Steamed rice\u00a0and\u00a0Andhra Style Pappu Charu Recipe\u00a0for a delicious lunch or dinner."]'::jsonb, 40, 'Andhra', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Andhra_Pepper_Chicken_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/738.Andhra_Pepper_Chicken_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Methi Murgh Recipe - Chicken with Fenugreek Leaves', 'methi-murgh-recipe-chicken-with-fenugreek-leaves', 'Methi Murgh Recipe also known as Chicken with Fenugreek Leaves Recipe is a classic combination of chicken and fenugreek leaves. The chicken is cooked in fresh methi leaves that compliments really well with the tender chicken.', '["200 grams Chicken , with bones", "1 cup Methi Leaves (Fenugreek Leaves) , washed", "2 Onions , sliced", "2 Tomatoes , chopped", "2 cloves Garlic , crushed", "1 inch Ginger , chopped", "1 teaspoon Fennel seeds (Saunf)", "1 inch Cinnamon Stick (Dalchini)", "1 teaspoon Whole Black Peppercorns", "2 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoon Garam masala powder", "1 teaspoon Cumin powder (Jeera)", "Salt , to taste", "Oil , as required"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'ginger', 'fennel seeds (saunf)', 'methi leaves (fenugreek leaves)', 'red chilli powder', 'cloves garlic', 'black peppercorns', 'onion', 'cinnamon stick (dalchini)', 'turmeric powder', 'chicken bs', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Methi Murgh Recipe, we will first heat oil in a heavy bottomed pan.Add cinnamon stick, shahi jeera and peppercorns, allow it to splutter for few seconds.", "Add in ginger and garlic and cook until it softens.", "This will take about 2 minutes.Add chopped onions and saute till they turn golden brown.", "Add tomatoes and sprinkle with little salt and cook till they turn mushy.Add washed and cleaned chicken pieces, turmeric powder, garam masala powder, cumin powder, red chilli powder and let it cook for about 8 to 10 minutes.Add cleaned fenugreek leaves and add about 1/2 cup of water, cover it with the lid and allow the chicken to cook for some more time.Open the lid and keep cooking until the water has evaporated and you are left with a thick gravy.Serve the\u00a0Methi Murgh Recipe\u00a0along with\u00a0Tawa Paratha\u00a0and\u00a0Burani Raita\u00a0to make a delicious meal for your dinner."]'::jsonb, 55, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Methi_Murgh_Recipe_Chicken_with_Fenugreek_Leaves_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/739.Methi_Murgh_Recipe_Chicken_with_Fenugreek_Leaves_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bhopli Mirchi Chi Peeth Perun Bhaji Recipe', 'bhopli-mirchi-chi-peeth-perun-bhaji-recipe', 'Bhopli Mirchi Chi Peeth Perun Bhaji is basically Maharashtra style green Capsicum besan sabzi. When you are mixing besan into the sabzi, you need to add it little by little with constant stirring. Also remember that you can add plain water instead of about 2 tablespoons of oil to make sabzi not too dry.', '["2 Green Bell Pepper (Capsicum) , chopped", "3 tablespoons Gram flour (besan)", "1 Onion , finely chopped", "2 Green Chillies , slit", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "Salt , to taste", "1/2 teaspoon Amchur (Dry Mango Powder)", "2 teaspoons Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Garam masala powder", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "Curry leaves , a few", "1 pinch Asafoetida (hing)", "1 Dry Red Chilli", "2 tablespoons Oil"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'amchur (dry mango powder)', 'mustard seeds', 'asafoetida (hing)', 'red chilli powder', 'gram flour (besan)', 'curry leaves', 'dry red chilli', 'onion', 'cumin seeds (jeera)', 'green bell pepper (capsicum)', 'coriander powder', 'turmeric powder', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the\u00a0Bhopli Mirchi Chi Peeth Perun Bhaji Recipe, prep up all the ingredients required.", "Dry roast besan till aromatic, on low medium heat.", "Transfer to a bowl and keep aside.In a pan/kadai, heat oil.", "Add mustard seeds, cumin seeds and let them crackle.When they splutter, add hing, curry leaves and red chilli.", "Later add green chillies and onion.", "Fry till they turn translucent.Next add capsicum.", "Cook uncovered for about 5-6 minutes stirring at intervals.When capsicum is crispy but a bit cooked, add turmeric powder, salt, red chilli powder, amchoor powder, coriander powder and cumin powder.", "Mix well.After a few minutes, sprinkle besan little by little, 1 tablespoon at a time such that it does not get lumpy.", "Combine well so that no lumps are formed.Then gradually sprinkle the rest of the gram flour while mixing the sabzi well.", "After you have mixed in all 3 tablespoons of besan, add 1-2 tablespoons of oil and garam masala powder.", "Mix well.Cook on medium high heat for another 3-4 minutes so that all masala is coated well to capsicum and besan. you can sprinkle a little water to bring everything together, instead of oil and it works the same though.Bhopli Mirchi Chi Peeth Perun Bhaji\u00a0is an easy recipe that can be done within 30 minutes and be served as a side dish with\u00a0Phulka\u00a0and\u00a0Panchmel Dal\u00a0for your everyday meals.", "You can pack them away for lunch or roll it in the\u00a0Tawa Paratha\u00a0to make rolls."]'::jsonb, 30, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/Bhopli_Mirchi_Chi_Peeth_Perun_Bhaji_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/740.Bhopli_Mirchi_Chi_Peeth_Perun_Bhaji_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gujarati Style Bhakri Recipe-A Multigrain Flat Bread', 'gujarati-style-bhakri-recipe-a-multigrain-flat-bread', 'Bhakri recipe is a delicious flatbread that is made from a combination of flours. Bhakri''s are prepared differently in every Gujarati home. It has varied textures, thickness and most often a made from a mixture of flours. Almost every Gujarati and Marathi home makes them with either wheat flour or jowar flour or both. Bhakri has a crispy outer layer and soft inside.', '["1 cup Whole Wheat Flour", "1 cup Jowar Flour (Sorghum)", "4 tablespoons Ghee", "2 teaspoons Ajwain (Carom seeds) , or sesame seeds", "1 teaspoon Whole Black Peppercorns , coarsely pounded", "1/2 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Dry ginger powder", "Salt , to taste"]'::jsonb, ARRAY['salt', 'wheat flour', 'ghee', 'jowar flour (sorghum)', 'black peppercorns', 'dry ginger powder', 'turmeric powder', 'ajwain (carom seeds) sesame seeds']::text[], '["To begin making the Bhakri''s, in a wide bowl, combine the flours, ghee, cumin seeds, ginger, red chilli powder and salt.", "Add water a little at a time and knead into very firm dough.", "Cover and set aside for 15 minutes.Preheat an iron skillet on medium heat.", "Divide the dough into 10 equal portions.", "Roll out each portion into a 4 inch diameter circle.", "Place the rolled dough on the heated skillet on medium heat.Cook each rolled portion of the bhakri dough on both sides until golden brown, putting light pressure using a wooden press, so the insides cook evenly.You will notice brown spots coming on very quickly if you your heat is very high.", "So take care and cook it evenly on medium heat.", "Optionally, many families cook the Bhakri\u2019s in ghee to make it flakier.Bhakri also travels well, so if you have a long distance journey this would be an ideal bread to dip into your\u00a0Masala Chai.", "Serve the Bhakri along with\u00a0Lauki Channa Dal\u00a0and a bowl of yogurt for dinner or a packed lunch."]'::jsonb, 50, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breads/Gujarati_Bhakri_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/741.Gujarati_Bhakri_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hyderabadi Vegetable Biryani Recipe | Vegetable Dum Biryani', 'hyderabadi-vegetable-biryani-recipe-vegetable-dum-biryani', 'Hyderabadi Biryani is a traditional celebration meal made using meat and rice and is a staple of Hyderabadi cuisine. This recipe was shared to me by a Muslim friend who makes the most awesome Biryani that I have tasted. The recipe of Hyderabadi Biryani has a few stages to making it. I make it in many different ways and the one mentioned below is one of the methods to make it super delicious.', '["1/2 cup Green beans (French Beans) , cut into 1 inch pieces", "1/2 cup Carrots (Gajjar) , diced", "2 Potatoes (Aloo) , peeled and cubed", "To be ground into paste (Grind the below ingredients to a paste and keep aside)", "6 cloves Garlic", "2 inch Ginger", "2 Green Chillies", "Main ingredients for biryani", "3 tablespoons Oil , required for cooking", "3 Onions , thinly sliced", "2 cups Seeraga (Jeeraga) Samba rice , rinsed", "2 Tomatoes , finely chopped", "1/2 cup Curd (Dahi / Yogurt)", "1 inch Cinnamon Stick (Dalchini)", "4 Cardamom (Elaichi) Pods/Seeds", "2 Bay leaves (tej patta)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "Salt , to taste", "1/4 cup Mint Leaves (Pudina) , freshly chopped", "12 Saffron strands", "1 cup Whole Wheat Flour"]'::jsonb, ARRAY['green beans', 'french beans', 'carrots', 'gajjar', 'potatoes', 'aloo', 'to be ground into paste', 'grind the below ingredients to a paste and keep aside', 's garlic', 'ginger', 'reen chillies', 'main ingredients for biryani', 's oil', 'onions', 's seeraga', 'jeeraga', 'tomatoes', 'curd', 'dahi / yogurt', 'cinnamon stick', 'dalchini', 'cardamom', 'elaichi', 'bay leaves', 'tej patta', 'turmeric powder', 'haldi', 'red chilli powder', 'coriander powder', 'dhania', 'garam masala powder', 'salt', 'mint leaves', 'pudina', 'saffron strands', 'whole wheat flour']::text[], '["To begin making the Vegetable Hyderabadi Biryani, prep all the ingredients and keep them ready.Prepare the dough for dum cooking.", "Into a large mixing bowl, add the flour and little water at a time to make a firm dough and keep aside.", "We will use this dough to seal the vessel to dum cook the biryani.Into a saucepan, add the rice with 2 cups of water along with salt and bring it to a brisk boil for 4 to 5 minutes and turn off the heat.", "This rice will be only half cooked as we are adding only half the amount of water to cook the rice.The rice will then get cooked further along with the masala below.Make a paste of the ginger garlic and green chillies either in a mixer grinder or in a pestle and mortar.", "Keep aside.Into a large pan where you plan to cook the Hyderabadi Vegetable Biryani, add the oil and preheat it over medium heat.Add the onion, ginger garlic green chilli paste, cinnamon, cloves, bay leaf and cardamom.", "Saute until the onions turn brown and caramelised.", "Ensure you do it on low heat so the onion caramelises evenly.Add the finely chopped tomatoes.", "Saut\u00e9 the tomatoes for about 5 minutes until mushy.", "Add the\u00a0turmeric powder, chilli powder, coriander powder and garam masala powder.Add the yogurt at this point, the potatoes and the remaining vegetables and simmer for another 2 minutes until it is bubbling and gets a good aroma.Finally add in the mint leaves potatoes, half cooked rice, any additional salt that is required.", "Give the Hyderabadi vegetable biryani a taste, to make sure the overall salt and spice levels are good to go.Add about 1-1/2 cups of water and cover the pan.", "Now it''s time to seal the ends of the vessel with the dough for dum cooking.", "Elongate the dough into a large log and seal the Biryani Pan and the lid with the dough so, the flavours get contained in the pan and the steam does not escape as well.", "This helps to bring in the delicious flavours to the biryani.Turn the heat to low and cook the Hyderabadi Vegetable Biryani for about 20 minutes.", "You will begin to start getting the delicious aromas after about 10 - 12 minutes of cooking the biryani.", "After 20 minutes of dum cooking the\u00a0Hyderabadi Vegetable Biryani, turn off the heat and allow the biryani to rest.Open the pan after 5 minutes of the resting period and give the Hyderabadi Vegetable Biryani a gentle stir, to combine all the masala and vegetables into the rice.", "Serve\u00a0Hyderabadi Vegetable Biryani Recipe along with\u00a0Hyderabadi Bagara Baingan,\u00a0Onion Tomato Cucumber Raita\u00a0for a delicious sunday lunch."]'::jsonb, 80, 'Hyderabadi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Hyderabadi_Vegetable_Biryani_Recipe_7_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/742.Hyderabadi_Vegetable_Biryani_Recipe_7_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hariyali Machali Recipe - Carp Fish In Green Spinach And Coriander Gravy', 'hariyali-machali-recipe-carp-fish-in-green-spinach-and-coriander-gravy', 'A very healthy version of cooking fish in green gravy is explained in this recipe. Hariyali Machli/Fish cooked in spinach puree with mouth watering green chilly, coriander and lime is very common in Indian cuisine especially in Punjabi kitchen.', '["200 gram Carp fish", "1 teaspoon Ginger , paste", "2 cloves Garlic", "1 Onion , chopped", "1 Tomato , chopped", "2 Dry Red Chilli", "1/4 teaspoon Kashmiri Red Chilli Powder", "Garam masala powder , a pinch", "1/4 teaspoon Cumin seeds (Jeera)", "2 teaspoon Mustard oil", "2 cups Spinach , chopped", "1/4 cup Coriander (Dhania) Leaves , chopped", "1 Green Chilli", "1/4 teaspoon Black pepper powder", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'kashmiri red chilli powder', 'green chilli', 'mustard oil', 'spinach', 'coriander (dhania) leaves', 'cloves garlic', 'gram carp fish', 'dry red chilli', 'onion', 'cumin seeds (jeera)', 'black pepper powder', 'ginger paste', 'garam masala powder']::text[], '["To begin making the Hariyali Machli recipe, firstly clean the fish and dry it.", "Season with salt and pepper for about 5 minutes.Grind together spinach, coriander, green chillies, lemon juice and a little water.Heat a frying pan with oil and fry the fish for 5 another five minutes till cooked.", "Remove the fish.Once you remove the fish, add cumin seeds and red chillies.", "After 30 seconds add in\u00a0garlic, ginger, onion and cook for about 5 minutes.", "Add kashmiri red chilli powder and garam masala powder.Pour the spinach puree and fry for few minutes.", "Check the seasoning of salt.", "Add the fried fish and coat it for 2 minutes.", "Serve immediately.", "Serve\u00a0Hariyali Machali along with\u00a0Whole Wheat Lachha Paratha\u00a0or\u00a0Steamed Rice\u00a0for a weekday meal.", "You can also serve\u00a0Kachumber Salad\u00a0along with the meal."]'::jsonb, 30, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/ruby_pathak-yahoo.com/Carp_Fish_In_Green_Spinach_and_Coriander_GravyHariyali_Machli.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/743.Carp_Fish_In_Green_Spinach_and_Coriander_GravyHariyali_Machli.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Himachal Style Pahari Sidu Recipe -Stuffed Bread Recipe', 'himachal-style-pahari-sidu-recipe-stuffed-bread-recipe', 'Himachal Style Pahari Sidu Recipe (Stuffed Bread Recipe) is a traditional stuffed bread made with whole wheat flour dough. The filling is a mixture of green peas and nuts.', '["1 cup Whole Wheat Flour", "1 teaspoon Active dry yeast", "1 teaspoon Sugar", "Water , for kneading", "2 tablespoons Roasted Peanuts (Moongphali)", "2 tablespoons Walnuts , roasted", "1 cup Green peas (Matar)", "1 cup Paneer (Homemade Cottage Cheese)", "1 inch Ginger", "2 cloves Garlic", "1 Green Chilli", "Salt , to taste"]'::jsonb, ARRAY['whole wheat flour', 'active dry yeast', 'sugar', 'water', 's roasted peanuts', 'moongphali', 's walnuts', 'green peas', 'matar', 'paneer', 'homemade cottage cheese', 'ginger', 's garlic', 'reen chilli', 'salt']::text[], '["To begin making the Himachal Style Pahari Sidu Recipe, we will first make the dough.", "Add yeast, whole wheat flour and sugar into a bowl and add water little at a time and knead well to form a soft and non-sticky dough.Cover the dough with a lid and rest it in a warm place till it rises.Grind the nuts along with green peas, ginger, garlic, green chillies and salt for the stuffing to a coarse mixture.", "Add crumbled paneer to the green peas mixture and keep it aside.After an hour, divide the rested dough equally into small balls and flatten them using a roller.The thickness must be about 1 centimeter.", "Add the stuffing to one side of the circle and fold in from the other side to form a semi-circle.Pinch the edges and score it in the center.", "Heat a pan with 2 tablespoon oil and carefully place the stuffed roti on the heated pan toast on either side till it is cooked and becomes brown.Serve the Himachal Style Pahari Sidu Recipe along with\u00a0green chutney\u00a0and\u00a0dal\u00a0for a Sunday brunch."]'::jsonb, 105, 'Himachal', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Himachal_Style_Pahari_Sidu_Recipe_Stuffed_Bread_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/744.Himachal_Style_Pahari_Sidu_Recipe_Stuffed_Bread_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Beetroot Pachadi Recipe', 'kerala-style-beetroot-pachadi-recipe', 'Beetroot pachadi recipe is very good accompaniment for rice and it is usually prepared by people in Kerala during Onam feast. The beetroot pachadi has light sweetness, sourness and spiciness. This pachadi has a pleasing pink colour and prepared by adding curd to the cooked beetroot. Serve this Kerala Style Beetroot Pachadi Recipe during a meal along with steamed rice, Vendakkai Uppadan and Jack Fruit Seeds Stir Fry Recipe.', '["2 Beetroot", "1/2 cup Curd (Dahi / Yogurt)", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1/3 cup Fresh coconut , grated", "3 Dry Red Chilli", "1 inch Ginger", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "5 Curry leaves", "1 Dry Red Chilli"]'::jsonb, ARRAY['salt', 'ginger', 'coconut', 'mustard seeds', 'dry red chilli', 'curd', 'curry leaves', 'cumin seeds (jeera)', 'beetroot', 'turmeric powder', 'sunflower oil']::text[], '["To prepare Kerala Style Beetroot Pachadi Recipe, wash, peel the skin and grate the beetroot.", "Cook beetroot covered with little water, in a Pressure cooker.Ina Mixer, grind all the ingredients under \u201cfor grinding\u201d into paste adding very little water.Once the beetroot gets cooked, then add the grounded paste and turmeric powder.Stir well, add salt and cook for few minutes until the raw smell of paste vanishes.Let it cool, then whisk curd well and add it to the beetroot.", "Mix well.Now heat oil in Tadka pan, add mustard seeds, red chilli and curry leaves.", "Once it splutters add to the pachadi and stir until combined.Enjoy the Kerala Style Beetroot Pachadi Recipe with steamed rice, Vendakkai Uppadan and Jack Fruit Seeds Stir Fry Recipe."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Swathy_Nandhini_/BEETROOT_PACHADI.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/745.BEETROOT_PACHADI.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('How to Make Homemade Jalebi Recipe', 'how-to-make-homemade-jalebi-recipe', 'The Homemade Jalebi Recipe is a delicious mithai dish that you can make right in your own kitchen. The Jalebi is a traditional sweet dish that is made on every festival, special occasions and monsoons. And so much so even homes make this dish to celebrate the occasion. This homemade Jalebi recipe is actually very easy to prepare and tastes absolutely delicious. Festivals like Holi and Diwali are incomplete without the preparation of this class Indian dessert - Jalebi.', '["1 cup All Purpose Flour (Maida)", "2 tablespoon Corn flour", "3/4 cup Curd (Dahi / Yogurt) , Sour", "1/2 teaspoon Baking powder", "2 tablespoon Ghee", "1 teaspoon Turmeric powder (Haldi) , for colour", "2 tablespoons Oil , plus more oil for deep frying", "Ingredients for the sugar syrup", "1 cup Sugar", "1 cup Water", "1 Saffron strands"]'::jsonb, ARRAY['all purpose flour', 'maida', 'corn flour', 'curd', 'dahi / yogurt', 'baking powder', 'ghee', 'turmeric powder', 'haldi', 's oil', 'ingredients for the sugar syrup', 'sugar', 'water', 'saffron strands']::text[], '["To begin making the Jalebi Recipe, we will first begin the preparation by mixing the maida, corn flour, baking soda, ghee and turmeric powder in a medium bowl.", "Combine all the dry ingredients well, until well combined.Add yogurt to the dry ingredients and blend them all together to make a thick batter by adding very little water.", "The consistency of the batter should be thick and not watery, similar to the butter cream batter.", "You should be able to make a shape when piped in a piping bag.When done, cover the jalebi batter and place it in a warm place for 24 hours or overnight, till it is fermented (the batter will rise on fermentation).", "Once the batter is fermented stir the batter in a cut and fold motion to combine it once again.Dont over stir you want the air pockets in the batter to remain.", "This will help in the jalebi being crisp and also in turn help it absorb the sugar syrup.To make the sugar syrup, boil the sugar with water and saffron powder in a small bowl on medium heat until the sugar dissolves.", "When the sugar becomes thick and stringy of one string consistency.Turn off the heat and keep aside.Now to make the jalebis, preheat the oil for deep frying.", "Once the oil is hot enough, you will know this, when you add a drop of batter in and it will come rising to the top almost immediately.Once you have filled the piping bag, pipe spirals of the batter onto the medium hot oil, until you get at least 3 concentric circles.", "Fry the jalebi on medium heat until golden brown in colour and crisp.", "Once the jalebi is crisp and browned, drain the excess oil out and immediately dip the jalebi into the hot sugar syrup.Piping the jalebis into the medium hot oil takes a little experience, the more you pipe the more practice you will get and the better you get at it.", "The Jalebis should rest in the sugar syrup for at least a minute, after which they can be drained out of the excess syrup and then served.Enjoy these crisp, sweet Homemade Jalebis as a wonderful dessert or a sweet option for your guests.Serve the\u00a0Homemade Jalebi Recipe as a Indian Party Dessert\u00a0for the festival of Holi or Diwali.Note:Ensure the batter is thick and firm, or else they won\u2019t retain the shape of the jalebis.", "The oil for frying should be medium hot.", "If it is too hot, the jalebis will end up burnt.Also make sure you keep the heat on low when you pipe the jalebis into the oil, this will ensure you can see the circles you are piping and also the jalebis will rise up slowly."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Homemade_Jalebi_Recipe-1-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/746.Homemade_Jalebi_Recipe-1-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sorakkai Kozhukattai Paal Kuzhambu Recipe - Bottle Gourd Curry', 'sorakkai-kozhukattai-paal-kuzhambu-recipe-bottle-gourd-curry', 'Sorakkai Kozhukattai Paal Kuzhambu is an authentic recipe from Tamil Nadu. It is a mildly spiced curry with coconut and tiny rice dumplings (kozhukattai) that are cooked along with bottle gourd. Sugar is added to give a little sweet taste .Tiny rice dumplings and chopped bottle gourd gives nice texture to the curry. As it is mildly spiced we can pair it up with any tangy and spicy gravies like puli kuzhambu for lunch.', '["1 Bottle gourd (lauki) , cut into small pieces", "1/4 cup Rice flour", "2 tablespoons Chana dal (Bengal Gram Dal)", "1/2 cup Fresh coconut , grated", "1/4 cup Milk", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "4 Dry Red Chillies", "2 tablespoons Sugar", "2 teaspoon Oil", "Salt , as per your taste", "Water , as needed"]'::jsonb, ARRAY['salt', 'coconut', 'mustard seeds', 'milk', 'water', 'white urad dal (split)', 'dry red chillies', 'sugar', 'bottle gourd (lauki)', 'rice flour', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making\u00a0Sorakkai Kozhukattai Paal Kuzhambu, first keep the chana dal soaked in warm water for 30 minutes."]'::jsonb, 50, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/aishchitra-gmail.com/Sorakai_kozhukatai_pal__kootu__coconut_and_rice_dumpling_based_bottlegourd__curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/747.Sorakai_kozhukatai_pal__kootu__coconut_and_rice_dumpling_based_bottlegourd__curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Bhindi Masala Gravy Recipe', 'aloo-bhindi-masala-gravy-recipe', 'Aloo Bhindi Masala Gravy Recipe is an everyday gravy sabzi that is cooked along with spices in a tomato and onion gravy. It is simple to make and uses everyday masalas to make the gravy flavourful. It makes a delicious side dish to be served along with phulkas and a dal tadka for lunch or dinner.', '["250 grams Bhindi (Lady Finger/Okra) , cut into 1-1/2 inch pieces", "1/2 teaspoon SSP Asafoetida (Hing)", "1 teaspoon Mustard oil", "Salt , to taste", "2 Potato (Aloo) , peeled and cut into wedges", "1/4 teaspoon Asafoetida (hing) , a pinch", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 tablespoon Mustard oil", "1 Onion , finely chopped", "6 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "1 cup Tomatoes , puree", "1 inch Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "Water , as required", "Salt , to taste", "Oil , as required", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "Coriander (Dhania) Leaves , a few, chopped, for garnish"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'sunflower oil', 'mustard oil', 'asafoetida (hing)', 'bay leaf (tej patta)', 'coriander (dhania) leaves', 'potato (aloo)', 'cinnamon stick', 'red chilli powder', 'cloves garlic', 'water', 'onion', 'bhindi (lady fingerokra)', 'coriander powder', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'cumin (jeera) seeds']::text[], '["To begin making the Aloo Bhindi Masala Gravy Recipe, first we will pan fry the bhindi.Into a preheated pan add oil.", "Once the oil is hot add the asafoetida, bhindi and salt to taste.", "Saute for a minute and the cover the pan.", "Keep your ladle in the pan to keep the lid ajar a little.", "This will help the bhindis to cook well but not get soggy at the same time.Cook the bhindi until they are completely done.", "Stir occasionally to cook them evenly.", "Once done keep the bhindi aside.", "Next we will roast the potatoes.", "Into a preheated pan add mustard oil, cumin seeds, asafoetida, turmeric powder, potatoes and salt to taste.Saute for a minute and then cover the pan.Cook the potatoes until cooked through.", "Once done turn off the heat and keep aside.", "We will finally make the gravy for the Aloo Bhindi Masala.Into\u00a0 preheated pan add oil, onions, garlic, ginger and saute until the onions soften and turn golden brown in color.", "Once done add the cinnamon, bay leaf, tomato puree, turmeric powder, red chili powder, coriander powder and salt to taste.Bring the masala to a brisk boil for 3 to 4 minutes.After 4 minutes add the roasted potatoes and bhindi in to the masala.Stir well to combine and simmer the aloo bhindi masala for 3 to 4 minutes.Finally stir in the kasuri methi.", "Cook for a minute and turn off the heat.", "Transfer the Aloo bhindi masala gravy into a serving bowl.", "Garnish it with some chopped coriander leaves and serve.Serve this simple and tasty\u00a0Aloo Bhindi Masala Gravy Recipe\u00a0along with\u00a0Lasooni Dal,\u00a0Tomato Onion Cucumber Raita\u00a0and\u00a0Phulka\u00a0for an everyday meal."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Aloo_Bhindi_Masala_Curry_Recipe_Video_North_Indian_Gravy_Dish_10_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/748.Aloo_Bhindi_Masala_Curry_Recipe_Video_North_Indian_Gravy_Dish_10_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mushroom Tikka Masala Recipe (Mushroom & Bell Peppers In Spicy Tomato Gravy)', 'mushroom-tikka-masala-recipe-mushroom-bell-peppers-in-spicy-tomato-gravy', 'Mushroom Tikka Masala Recipe is a perfectly roasted chunks of marinated mushrooms and bell pepper in a fragrant and spicy tomato based gravy. Skillful to make and a crowd pleaser for sure. Mushroom Tikka Masala Recipe can be served for lunch or dinner along with Pudina Tawa Paratha or Butter Garlic Naan Recipe and Bharma Baingan Aur Pyaaz Ki Sabzi Recipe (Spicy Stuffed Brinjals With Onions).', '["1/4 cup Curd (Dahi / Yogurt) , or greek yogurt (hung yogurt)", "1 teaspoon Kashmiri Red Chilli Powder", "1 teaspoon Garam masala powder , or kitchen king masala", "1 teaspoon Ginger Garlic Paste", "1/8 teaspoon Turmeric powder (Haldi)", "1 tablespoon Gram flour (besan)", "1 teaspoon Lemon juice", "1/2 teaspoon Chaat Masala Powder", "2 cups Button mushrooms , cut into 2", "2 teaspoons Oil", "1/2 cup Green Bell Pepper (Capsicum) , cubed", "1/2 teaspoon Cumin seeds (Jeera)", "2 Cloves (Laung)", "1/2 inch Cinnamon Powder (Dalchini)", "1 Cardamom (Elaichi) Pods/Seeds", "1 clove Garlic", "1 inch Ginger", "1/2 cup Onion , chopped", "3 Green Chillies , or jalapenos", "8 Cashew nuts", "1 Tomato", "1 Bay leaf (tej patta)", "1 teaspoon Garam masala powder", "1 tablespoon Oil , or ghee", "Salt , to taste", "1 tablespoon Oil , or ghee", "Kasuri Methi (Dried Fenugreek Leaves) , to garnish"]'::jsonb, ARRAY['tomato', 'kashmiri red chilli powder', 'chaat masala powder', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'garam masala powder kitchen king masala', 'sunflower oil', 'salt', 'sunflower oil ghee', 'cardamom (elaichi) podsseeds', 'cloves garlic', 'garam masala powder', 'cinnamon powder (dalchini)', 'curd greek yogurt (hung yogurt)', 'lemon', 'green chillies jalapenos', 'button mushrooms', 'kasuri methi (dried fenugreek leaves)', 'cashew nuts', 'ginger', 'bay leaf (tej patta)', 'ginger garlic paste', 'gram flour (besan)', 'green bell pepper (capsicum)', 'cloves (laung)']::text[], '["To begin making Mushroom Tikka Masala Recipe (Mushroom & Bell Peppers In Spicy Tomato Gravy), prep up with all the ingredients and start with marinating the mushrooms.In a large mixing bowl, add all the marinade ingredients, except mushrooms.Mix well, do a taste test and adjust spices and salt according to your taste.Add in the cut mushrooms and toss well to coat the mushrooms with the marinade evenly.Cover with a cling wrap or plate and keep in the refrigerator for about 30 minutes to an hour."]'::jsonb, 65, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Curryandvanilla/Mushroom_Tikka_Masala.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/749.Mushroom_Tikka_Masala.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Khatte Chole Recipe - A Delicious North Indian Chana Masala', 'khatte-chole-recipe-a-delicious-north-indian-chana-masala', 'Khatte Chole Recipe is a very popular Delhi style street food. It is spicy and tart making for a perfect accompaniment with Gehu Bajra Thepla or even a Kulcha for those special monsoon days. The tartness comes from the addition of dried mango powder or amchoor and the ginger in the recipe makes it flavourful and delicious.', '["1-1/2 cups Kabuli Chana (White Chickpeas) , soaked overnight and boiled", "1 Onion , thinly sliced", "1 Tomato , thinly sliced", "1 Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "1 inch Ginger , grated", "1 teaspoon Ajwain (Carom seeds)", "1 teaspoons Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "2 teaspoons Amchur (Dry Mango Powder)", "2 teaspoons Ghee", "Salt , to taste", "To garnish", "1 Onion , thinly sliced", "1 Green Chilli , finely chopped"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'green chilli', 'amchur (dry mango powder)', 'ghee', 'ajwain (carom seeds)', 'red chilli powder', 'kabuli chana (white chickpeas)', 'onion', 'cinnamon stick (dalchini)', 'coriander powder', 'cloves (laung)', 'garam masala powder']::text[], '["To begin making Khatte Chole Recipe, soak the white chickpea or kabuli chana overnight and in the morning boil it with enough water using a pressure cooker for 8 to 10 whistles - about 30 minutes and keep aside.Heat ghee in a large saucepan on medium heat, add ajwain, cinnamon stick and the cloves and let its aroma get released in the ghee.Add the slices onions and ginger and saut\u00e9 until they are slightly soft.", "This will take around 3 to 4 minutes.Add sliced tomatoes, cook until the tomatoes turns mushy.Once the tomatoes have softened add the spice powders -\u00a0red chilli powder, garam masala,\u00a0coriander, and amchur, and cook until the ghee leaves the sides.Add the boiled kabuli chana, season with salt and let it simmer for 20 minutes until the Khatte Chole gets well coated with the masala.", "Once done, check the salt and spices and adjust to suit your taste.Serve the Khatte Chole Recipe along with\u00a0Gehu Bajra Thepla\u00a0or\u00a0Bhatura Recipe\u00a0along with the fresh onion salad and\u00a0Masala Chaas Recipe\u00a0for the weekend brunch."]'::jsonb, 90, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Khatte_Chole_Recipe_-_North_Indian_Chana_Masala_16_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/750.Khatte_Chole_Recipe_-_North_Indian_Chana_Masala_16_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sookha Aloo Matar Methi Sabzi Recipe', 'sookha-aloo-matar-methi-sabzi-recipe', 'Sookha Aloo Matar Methi Sabzi Recipe is a delicious easy to make sabzi recipe. It has the goodness of the fresh fenugreek leaves, potatoes and green peas combined with mild spices. It makes for a great accompaniment for phulkas or parathas. If you have all the ingredients ready, it is the quickest recipe to cook for the rushed mornings.', '["4 Potatoes (Aloo) , boiled", "3/4 cup Green peas (Matar)", "1 cup Methi Leaves (Fenugreek Leaves) , roughly chopped", "1 Onion , finely chopped", "1 teaspoon Red Chilli powder", "2 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "2 teaspoon Oil", "Salt , to taste"]'::jsonb, ARRAY['potatoes', 'aloo', 'green peas', 'matar', 'methi leaves', 'fenugreek leaves', 'onion', 'red chilli powder', 'coriander powder', 'dhania', 'turmeric powder', 'haldi', 'garam masala powder', 'oil', 'salt']::text[], '["To begin making\u00a0Sookha Aloo Matar Methi Sabzi Recipe, pressure cook the potatoes using a pressure cooker for 2 whistles.", "After the pressure releases naturally open the pressure cooker.", "Peel the skin of the potatoes and chop into big cubes and keep aside.Likewise, steam the peas and keep aside.Heat oil in a heavy bottomed pan, add the onions and saute until it turns translucent.After the onions have turned translucent add in methi leaves and saute for 2 minutes till the methi leaves wilt a little and releases a nice aroma.Add the red chilli powder, turmeric, coriander powder and saute until the raw smell goes away.Add the peas and boiled potatoes cubes, season with salt and mix well.", "Saute\u00a0Sookha Aloo Matar Methi Sabzi until all the ingredients come together.Add the garam masala to\u00a0Sookha Aloo Matar Methi Sabzi and\u00a0 stir well.", "Switch off the flame.Serve the\u00a0Sookha Aloo Matar Methi Sabzi Recipe along with\u00a0Phulka\u00a0or\u00a0Paratha\u00a0and\u00a0Homemade Yogurt (Curd)\u00a0for kids lunch box or with\u00a0Phulka,\u00a0Dal Tadka\u00a0and Salad for weeknight lunch."]'::jsonb, 25, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Sookha_Aloo_Matar_Methi_Sabzi_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/751.Sookha_Aloo_Matar_Methi_Sabzi_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chicken Cooked in Banana Leaves Recipe', 'chicken-cooked-in-banana-leaves-recipe', 'Long marination makes the chicken tender and succulent in this Chicken Cooked in Banana Leaves Recipe.', '["500 grams Boneless chicken , 2 inch cubes", "1 Lemon", "2 Green Chillies", "10 sprig Coriander (Dhania) Leaves", "2 tablespoons Ginger Garlic Paste", "10 Whole Black Peppercorns", "3 Star anise", "5 Cloves (Laung)", "1 teaspoon Red Chilli powder", "Salt , to taste", "1/2 teaspoon Turmeric powder (Haldi)", "2 Banana leaf", "Cotton threads , as required", "Oil , as required"]'::jsonb, ARRAY['salt', 'cotton threads', 'red chilli powder', 'black peppercorns', 'ginger garlic paste', 'banana leaf', 'coriander (dhania) leaves', 'lemon', 'boneless chicken cubes', 'cloves (laung)', 'turmeric powder', 'green chillies', 'star anise', 'sunflower oil']::text[], '["To begin making the Chicken Cooked in Banana Leaves, in a mixer-jar, combine the green chillies, coriander sprigs (stem as well), ginger garlic paste, cloves, peppercorns, star anise and grind to a coarse mixture.", "In a mixing bowl, add the chicken, the freshly ground mixture,\u00a0lime juice, red chili powder, turmeric powder, salt.", "Make sure the chicken pieces are completely coated with the mixture.", "Let the chicken pieces marinate for two hours.Once the chicken is marinated, cut the banana leaves into squares of 4 inch squares, so that you can make parcels.", "Now put the one chicken piece in one banana leaf piece.Fold the leaf to make a parcel and tie it using a thread.Heat oil in a pan, add the parcels into the pan and make sure you are not crowding the pan.", "Cover the pan and cook the parcels from both sides for at-least 15-20 minutes.Open the parcels and serve hot.", "Serve Chicken Cooked in Banana Leaves as an appetizer along with other appetizers such as Mushroom Poha Cutlets Recipe and Easy Sabudana Vada With Arrowroot Powder."]'::jsonb, 95, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/garimasgautam-gmail.com/Chicken_Cooked_in_Banana_Leaves_original1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/752.Chicken_Cooked_in_Banana_Leaves_original1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Style Dum Oluv Recipe - Dum Aloo Recipe', 'kashmiri-style-dum-oluv-recipe-dum-aloo-recipe', 'Kashmiri Style Dum Oluv Recipe -Dum Aloo Recipes is a traditional recipe from the region of Kashmir. The spices that they use is a blend of cloves, cinnamon, bay leaf, cardamom, fennel and cumin seeds. The gravy is yogurt and chilli flavored curry which is simmered in roasted baby potatoes.', '["10 Baby Potatoes , boiled and shallow fried", "Water , for boiling", "Salt , to taste", "Oil", "Ingredients for the gravy", "1 Bay leaf (tej patta)", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 Cardamom (Elaichi) Pods/Seeds", "3 teaspoon Kashmiri Red Chilli Powder , mixed with 3 tablespoon water", "1 teaspoon Fennel seeds (Saunf) , powdered", "1 inch Dry ginger powder", "1 Black cardamom (Badi Elaichi) , powdered", "1 teaspoon Cumin seeds (Jeera)", "1 1/2 cup Hung Curd (Greek Yogurt) , low fat and whisked till it is smooth"]'::jsonb, ARRAY['salt', 'black cardamom (badi elaichi)', 'hung curd (greek yogurt) till smooth', 'bay leaf (tej patta)', 'cardamom (elaichi) podsseeds', 'kashmiri red chilli powder mixed water', 'fennel seeds (saunf)', 'dry ginger powder', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'water boiling', 'baby potatoes', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Dum Oluv Recipe, we will start by boiling the potatoes along with their skin in a pressure cooker with required water for about 3 whistle.", "Release the pressure naturally.Open the pressure cooker, drain all the water, peel the skin of the potatoes and keep it aside.Heat a heavy bottomed pan with 2 tablespoons oil.", "Once the oil is slightly hot, add the peeled potatoes and roast them till it is light brown.", "Take out the potatoes and keep the aside.In the same pan, add a teaspoon of oil and fry the spices (cinnamon, bay leaf, cloves, green cardamom pods) and then add the red chilli powder mixed with water.", "Add the fennel powder, ginger powder and mix well.It might splutter for few seconds, be careful while stirring.", "In the meal while whisk the curd till it becomes a smooth paste, reduce the flame and slowly add in the roasted potatoes and curd mixture.", "Make sure the flame is low.Simmer the (Aloo) potatoes in the curd gravy for about 25 minutes.", "And then finally add the cumin seeds and cardamom powder, mix well and serve.", "Serve the\u00a0Dum Oluv Recipe\u00a0along with\u00a0Steamed Rice\u00a0or\u00a0Whole Wheat Naan\u00a0and\u00a0Aamras\u00a0to enjoy your meal."]'::jsonb, 35, 'Kashmiri', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Kashmiri_Style_Dum_Oluv_Recipe_Whole_Spicy_Baby_Potatoes_Recipes.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/753.Kashmiri_Style_Dum_Oluv_Recipe_Whole_Spicy_Baby_Potatoes_Recipes.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Raw Mango Dal Fry Recipe', 'raw-mango-dal-fry-recipe', 'Raw Mango Dal Fry Recipe is a wonderful and tangy twist to the regular dal fry recipe, with addition of raw mangoes. Grated raw mangoes are added to the arhar dal and other basic spices to prepare this side dish.', '["1 Cup Arhar dal (Split Toor Dal)", "2 Tablespoon Mango (Raw) , Grated", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 Tomato , chopped", "2 Green Chillies , Slit", "1 sprig Curry leaves , Curry Leaves", "1 Onion , chopped", "2 Dry Red Chillies", "4 cloves Garlic , minced", "Salt , to taste", "1 teaspoon Ghee , for tadka"]'::jsonb, ARRAY['tomato', 'salt', 'mango grated', 'arhar dal (split toor dal)', 'ghee tadka', 'red chilli powder', 'cloves garlic', 'dry red chillies', 'curry leaves curry leaves', 'onion', 'turmeric powder', 'green chillies']::text[], '["To begin making Raw Mango Dal Fry Recipe, prep all the ingredients first.Into the pressure cooker, add the dal, salt red chilli powder, turmeric powder, slit green chilli, tomato and grated raw mango into the cooker.", "Add 2 cups of water and pressure cook for 3 to 4 whistles until the dal is cooked.Once done, allow the pressure to release naturally.Open the cooker and use a wooden ladle to make the Raw Mango Dal Fry mushy.", "Keep it aside.Heat ghee in a kadai/wok and add whole red chillies into it.", "Add the diced onions and cook them till they become translucent in colour.Once onions are ready then add minced garlic and curry leaves and saute them for at least 1 minute.Now add the cooked Raw Mango Dal Fry into the pan and let it cook for 5-7 minutes.", "Add more water if you feel that dal has become too thick.", "Adjust salt as per your taste.Serve\u00a0Raw Mango Dal Fry Recipe along with\u00a0Curried Tofu Kebab Recipe,\u00a0Aloo Bhindi Ki Sabzi Recipe (Spicy Potatoes and Lady''s Finger Stir Fry),\u00a0Phulka, and\u00a0steamed rice."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/garimasgautam-gmail.com/Mango_Dal_Fry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/754.Mango_Dal_Fry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bihari Aloo Bhujiya Recipe', 'bihari-aloo-bhujiya-recipe', 'Bihari Aloo Bhujiya is a simple and humble recipe prepared in the households of Bihar. It requires the common ingredients available in the kitchen pantry and doesn’t involve much complex cooking techniques. It can be served as breakfast with parathas or as lunch with rice and curry.', '["2 Potatoes (Aloo) , peeled and cut lengthwise", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin seeds (Jeera)", "2 Green Chillies , slit into halves", "1-1/2 tablespoon Mustard oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard oil', 'cumin seeds (jeera)', 'potato (aloo)', 'turmeric powder', 'green chillies']::text[], '["To begin making the Bihari Aloo Bhujiya Recipe, wash potatoes with water.Cut them into lengthy pieces similar to the one for finger chips.", "If you don\u2019t prefer to use the skin, peel it and then chop them into piecesIn a non-stick wok, add oil.", "Once the oil is hot, add cumin seeds and allow it to splutter.Now, add green chilies and saute it.", "Stir in the chopped potatoes and turmeric powder.", "Season it with salt.Reduce the flame.", "Cook until the potatoes are cooked completely.", "Towards the end, when the potatoes have almost cooked, open the lid and allow it to become crispy.At this stage you can optionally add more mustard oil and then sprinkle some more salt.", "Ensure you keep stirring occasionally so it gets cooked from all the sides.Once done, turn off the heat and transfer to as serving bowl.Serve the Bihari Aloo Bhujiya\u00a0along with Pudina Paratha, Punjabi Methi Kadhi Recipe\u00a0for a wholesome weeknight dinner."]'::jsonb, 30, 'Bihari', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/KarthikaKrishnan/Bihari_Aloo_Ki_Bhujiya.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/755.Bihari_Aloo_Ki_Bhujiya.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Arbi Ka Saag Recipe', 'arbi-ka-saag-recipe', 'Arbi Ka Saag is a spicy and delicious curd based gravy which is very famous among the Rajasthani households. Due to its unique taste, it can also be served during weekend dinner or lunch parties.', '["250 grams Colocasia root (Arbi) , boiled and peeled", "Oil , as required", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)", "1 Green Chilli , finely chopped", "1 tablespoon Ginger Garlic Paste", "1 Onion , finely chopped", "1/2 cup Curd (Dahi / Yogurt)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "Salt , as required", "Water , as required", "Coriander (Dhania) Leaves , Few sprigs, finely chopped"]'::jsonb, ARRAY['salt', 'coriander (dhania) leaves', 'green chilli', 'mustard seeds', 'asafoetida (hing)', 'red chilli powder', 'water', 'ginger garlic paste', 'curd', 'colocasia root (arbi)', 'onion', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Arbi Ka Saag recipe, firstly cut the boiled arbi into round shape.", "Keep it aside.Heat oil in a wok/kadhai.", "Add mustard seeds and asafoetida into the pan.", "Let it cook till the mustard seeds crackle.Once it crackles, add the ginger garlic paste, green chillies and let it cook for about 2 to 3 minutes.After 2 to 3 minutes, add in the finely chopped onions.", "Let it cook till the onion becomes soft and translucent.", "Add all the masala including red chilis powder, turmeric powder, coriander powder and salt into the pan.", "Let it cook for 4 to 5 minutes.Meanwhile, add water into the curd and whisk well.", "Add the boiled Karbi and mix everything properly.Turn the flame low, pour the curd into the pan and stir continuously.", "Cover the lid and let it cook for about 8 to 10 minutes.After 8 to 10 minutes, switch off the flame and garnish it with the chopped coriander.Serve Arbi Ka Saag with Boondi Raita and\u00a0Phulkas\u00a0or Steamed rice for a weekday lunch or dinner."]'::jsonb, 20, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Arbi_ki_sabji_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/756.Arbi_ki_sabji_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gajar Pulao Recipe - Spiced Carrot Rice', 'gajar-pulao-recipe-spiced-carrot-rice', 'Carroty Flashed Rice as I like to call this Gajar Pulao is packed with nutrients, along with the Basmati Rice is pleasantly aromatic for your weekday lunch and dinner. Simple to make and delicious to eat, you should definitely give this recipe a try.', '["3 Carrots (Gajjar) , long thinly sliced and steamed", "2 Onions , grind into paste", "2 Tomatoes , grind to a puree", "6 cloves Garlic , paste", "2 Green Chillies , grind into paste", "1/4 teaspoon Kashmiri Red Chilli Powder", "2 cups Rice", "4 tablespoons Oil", "1/4 cup Coriander (Dhania) Leaves , fnely chopped", "Salt , to taste"]'::jsonb, ARRAY['carrots', 'gajjar', 'onions', 'tomatoes', 's garlic', 'reen chillies', 'kashmiri red chilli powder', 's rice', 's oil', 'coriander', 'dhania', 'salt']::text[], '["To begin making the Gajar Pulao Recipe, firstly wash and rinse the rice thoroughly in water (about 2 times).", "Soak for at least 10-15 minutes in a large bowl.", "Drain as much water as possible.Fill about half a large deep pan with water & bring it to boil.Add the washed rice followed by 1 tablespoon of vegetable oil.", "Cook for about 7 minutes on medium flame.", "Add 1 teaspoon of salt half-way through the cooking process.Keep stirring the rice gently, cook till it\u2019s still a little firm.", "Once done, discard the liquid from the rice and set it aside.In a non-stick\u00a0sauce pan, heat 3 tablespoons of oil and add onion paste.", "Saute the onion paste on medium heat, till\u00a0its\u00a0dry and the raw smell goes away.", "This will take about 2 to 3 minutes.Add the\u00a0garlic paste, green\u00a0chilli paste and stir for about a minute.", "Pour in tomato puree along with red\u00a0kashmiri\u00a0chilli\u00a0powder stir for another 5-6 minutes.Add the carrots, the\u00a0par cooked\u00a0rice into the above gravy.", "Turn the heat to low and simmer for about 15 minutes.", "Turn off the heatGently fluff the rice with the fork without breaking the grains of rice.", "Garnish it with coriander and serve hot.Serve\u00a0Gajar Pulao\u00a0along with\u00a0Tomato Onion Cucumber Raita\u00a0or any other raita of your choice and a roasted\u00a0Papad\u00a0for a delicious weekday meal."]'::jsonb, 55, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Spiced_Carrot_Pulao_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/757.Spiced_Carrot_Pulao_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gehu Bajra Thepla Recipe - Bajra Masala Paratha', 'gehu-bajra-thepla-recipe-bajra-masala-paratha', 'Gehu Bajra Thepla Recipe is a healthy preparation of the Gujarati Indian Flat Bread known as theplas. The addition of ginger, green chillies, black pepper gives the thepla and additional punch, giving the millet thepla a good taste.', '["1 cup Bajra Flour ( Pearl Millet)", "1/2 cup Whole Wheat Flour", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Black pepper powder", "1 inch Ginger , grated", "1 Green Chilli , finely chopped", "4 sprig Coriander (Dhania) Leaves , finely chopped", "Oil , as required"]'::jsonb, ARRAY['bajra flour', 'pearl millet', 'whole wheat flour', 'turmeric powder', 'haldi', 'black pepper powder', 'ginger', 'reen chilli', 'coriander', 'dhania', 'oil']::text[], '["To begin making the\u00a0Gehu Bajra Thepla Recipe, combine the\u00a0bajra flour,\u00a0whole wheat flour,\u00a0turmeric powder,\u00a0black pepper powder,\u00a0ginger,\u00a0green chilli,\u00a0and\u00a0coriander leaves,\u00a0in a large mixing bowl.", "Add little water at a time and knead to make a smooth and firm dough.", "Drizzle some oil on the top and knead for a few more minutes until smooth.", "Cover the thepla dough and allow it to rest for half an hour.Preheat the iron skillet on medium heat.", "Divide the dough into 6 to 8 portions.Roll the thepla portions into balls; flatten them with the palm of your hand.", "Toss the thepla dough on flour and roll them out into thin circles to approximately 6 inches in diameter.As you roll them out, you can keep tossing the dough in dry flour to prevent sticking when rolling them out.Continue the same process of rolling the thepla dough out with the remaining balls.", "It is ideal when you can roll out the all portions of dough before you can start cooking them."]'::jsonb, 45, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Gehu_Bajra_Thepla_Recipe_-_Bajra_Masala_Paratha_6_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/758.Gehu_Bajra_Thepla_Recipe_-_Bajra_Masala_Paratha_6_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Narthangai Curry | Sweet and Sour Citron fruit Curry', 'narthangai-curry-sweet-and-sour-citron-fruit-curry', 'Narthangai Curry in the South Indian cuisine, especially tamil cuisine, citron is widely used in pickles and preserves. Here is delicious sweet and sour recipe of this fruit that can be had with steamed rice, dosa''s or even along with phulka''s.', '["2 Citron (Narthangai)", "2 Green Chillies", "2 cups Tamarind Water", "1 teaspoon Turmeric powder (Haldi)", "1 tablespoon Jaggery , grated", "1 teaspoon Methi Powder (Fenugreek Powder)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 tablespoon Gingelly oil", "Salt , to taste"]'::jsonb, ARRAY['citron', 'narthangai', 'reen chillies', 's tamarind water', 'turmeric powder', 'haldi', 'jaggery', 'methi powder', 'fenugreek powder', 'mustard seeds', 'rai/ kadugu', 'gingelly oil', 'salt']::text[], '["To prepare Narthangai Curry | Sweet and Sour Citron fruit Curry, cut the citron / narthangai to desired size after taking the juice from it.", "Keep this narthangai juice\u00a0aside.Heat gingelly oil in a pan on medium flame, add mustard seeds.", "When the mustard seeds splutter, add turmeric powder and fenugreek powder to it.", "Add green chillies and the cut narthangai to it, saut\u00e9 them for a minute after adding salt.Now add the tamarind water to this and let this mixture boil for 2 minutes on a medium flame.", "Add the grated jaggery now and let it boil for another minute.", "Turn\u00a0off the flame and allow it to cool.", "At this stage add in the narthangai juice and stir well.", "Store it in an airtight container.Serve the delicious Narthangai Curry | Sweet and Sour Citron fruit Curry\u00a0along with dosa''s\u00a0or curd rice."]'::jsonb, 55, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Narthangai_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/759.Narthangai_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Style Kaddu Lobia ki Sabzi with Panch Phoran Masala', 'bengali-style-kaddu-lobia-ki-sabzi-with-panch-phoran-masala', 'The Bengali Style Kaddu Lobia ki Sabzi is a delectable dish that is wholesome, packed with nutrients, proteins and the special Panch Phoran, that is a classic Indian five-spice powder. The addition of the freshly roasted spices, along with ginger, onions and tomatoes roasted along with the kaddu brings our the perfect blend of taste and texture.', '["1 cup Black Eyed Beans (Lobia) , soaked for 2 hours", "500 grams Kaddu (Parangikai/ Pumpkin)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Onion , finely chopped", "1 inch Ginger , grated", "2 Tomatoes , finely chopped", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Red Chilli powder", "Salt , to taste", "Oil , for cooking", "Panch Phoran (Bengali Five Spice Powder)", "1 tablespoon Cumin seeds (Jeera)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Fennel seeds (Saunf)", "1 teaspoon Kalonji (Onion Nigella Seeds)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)"]'::jsonb, ARRAY['black eyed beans', 'lobia', 's kaddu', 'parangikai/ pumpkin', 'mustard seeds', 'rai/ kadugu', 'onion', 'ginger', 'tomatoes', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'red chilli powder', 'salt', 'oil', 'panch phoran', 'bengali five spice powder', 'cumin seeds', 'jeera', 'fennel seeds', 'saunf', 'kalonji', 'onion nigella seeds', 'methi seeds', 'fenugreek seeds']::text[], '["To begin making the Bengali Style Kaddu Lobia ki Sabzi, Soak the black eyed beans in 2-1/2 cups of water for about 2 hours.", "Once soaked, place the soaked black-eyed beans along with its water and salt in the pressure cooker and cook until soft.", "Check video of how to cook beans and legumes in a pressure cooker.", "Once the beans is cooked, keep it aside.", "The next step we will make the Panch Phoran\u00a0Spice Powder.Preheat a small pan on medium heat; dry roast all the Panch Phoran\u00a0ingredients until well roasted and you start smelling the aromas of the roasted ingredients.", "Once roasted, turn off the heat and allow the seeds to cool.", "Once cooled, powder the Panch Phoran Masala in a grinder.The next step is to cook the Kaddu (Pumpkin).", "Heat a teaspoon of oil in a heavy bottomed wok, add the mustard seeds and allow it to crackle.", "Add the onions and ginger and saute until the onions are tender on medium heat.Once the onions have softened a little, add the tomatoes, the turmeric powder and finally the cut pumpkin (kaddu).", "Sprinkle some salt, stir the ingredients well, cover the pan and cook the kaddu on low to medium heat, stirring the vegetable occasionally\u00a0so it gets evenly cooked.Once the pumpkin is more than half way cooked, (you will know this when you press it with a spoon, it will cut through easily) add the cooked black eyed beans, the\u00a0panch phoran spice powder, the chilli powder and give the sabzi a good stir.Check the salt and spice levels and adjust to suit your taste.", "Simmer the\u00a0Bengali Style Kaddu\u00a0Lobia\u00a0ki Sabzi for another 3 to 4 minutes and turn off the heat.Transfer the\u00a0Bengali Style Kaddu\u00a0Lobia\u00a0ki Sabzi to a serving bowl and serve it along with Methi Palak Paratha and Bengali Cholar Dal."]'::jsonb, 55, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Bengali_Kaddu_Kumro_ki_Sabzi_with_panch__phroran_masala_recipe_pumpkin_with_black_eyed_beans-17.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/760.Bengali_Kaddu_Kumro_ki_Sabzi_with_panch__phroran_masala_recipe_pumpkin_with_black_eyed_beans-17.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lauki Badi Ki Sabzi Recipe', 'lauki-badi-ki-sabzi-recipe', 'Lauki Badi Ki Sabzi is a perfect recipe for the days when you want to make something in jiffy but tasty. This is very popularly made in Rajasthani households and usually served with roti and parathas. It is easy and takes very few basic ingredients to prepare this recipe.', '["1/2 Bottle gourd (lauki) , peel the skin and chopped", "1/2 cup Badi (wadi)", "Oil , as required", "1 sprig Curry leaves", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "Asafoetida (hing) , a pinch", "1 Green Chilli , finely chopped", "1 inch Ginger , grated", "3 cloves Garlic , grated", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Garam masala powder", "2 tablespoons Milk , or more if required"]'::jsonb, ARRAY['bottle gourd (lauki) the skin', 'ginger', 'green chilli', 'mustard seeds', 'asafoetida (hing)', 'milk', 'red chilli powder', 'cloves garlic', 'curry leaves', 'cumin seeds (jeera)', 'badi (wadi)', 'coriander powder', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Lauki Badi Ki Sabzi recipe, firstly roast the badi in a pan until it turns brown.", "Take it out and keep it aside to cool down.Now heat oil or ghee in a wok/kadhai and add cumin seeds, mustard seeds and asafoetida.Once the mustard seeds splutter, add in the green chillies, asafoetida and ginger garlic paste.Add in the chopped lauki and cook till it becomes soft and tender.", "Once it is done add in the roasted badi and give it a stir.Add in the masalas including red chilli powder, turmeric powder, coriander powder, garam masala and the required salt.Add in the required milk.", "Don''t add too much milk because the bad becomes soft very fast.", "Cook till the badi becomes soft.", "Stir in the coriander leaves and transfer the Lauki Badi ki Sabzi to as serving bowl and serve hot.Serve Lauki Badi Ki Sabzi along with\u00a0Panchmel Dal\u00a0and\u00a0Pudina Tawa Paratha\u00a0for a weekday lunch or dinner."]'::jsonb, 30, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pooja/Lauki_Badi_Ki_Sabzi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/761.Lauki_Badi_Ki_Sabzi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pakistani Chickpeas Pulao Recipe With Sweet Hot Date Onion Chutney', 'pakistani-chickpeas-pulao-recipe-with-sweet-hot-date-onion-chutney', 'Chickpeas Pulao is one of the common dishes that is often prepared in Pakistan. Pakistani Chickpeas Pulao Recipe is slightly saucy with the mixture of rice and chickpeas and is packed with spices. This is surely a warm and comforting food.', '["2 cups Basmati rice", "1 cup Kabuli Chana (White Chickpeas)", "2 tablespoon Oil", "1 Tomato", "1 Onion , thinly sliced", "2 Cardamom (Elaichi) Pods/Seeds", "1 Bay leaf (tej patta)", "1 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "1 tablespoon Ginger Garlic Paste", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "Salt , as required", "Coriander (Dhania) Leaves , for garnish, chopped", "1 Onion , thinly sliced", "1 teaspoon Oil", "1 teaspoon Sesame (Gingelly) Oil", "1/2 cup Dates , pitted", "4 Fresh Red Chilli", "Salt , as required"]'::jsonb, ARRAY['tomato', 'basmati rice', 'cumin powder (jeera)', 'salt', 'cardamom (elaichi) podsseeds', 'bay leaf (tej patta)', 'coriander (dhania) leaves', 'red chilli powder', 'sesame (gingelly) oil', 'ginger garlic paste', 'kabuli chana (white chickpeas)', 'onion', 'cinnamon stick (dalchini)', 'red chilli', 'coriander powder', 'dates', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin with Pakistani Chickpeas Pulao With Sweet Hot Date Onion Chutney, firstly soak chick peas for an hour.", "Cook chickpeas in a pressure cooker with water for 3 whistles.", "Drain the water from the cooked chickpeas, mix salt and keep it aside.On the other hand, soak the basmati rice for 30 minutes.In a medium pan/pressure cooker, heat oil over medium heat.", "Add onions, cinnamon, cloves, cardamom, bay leaf and onion.", "Saut\u00e9 onion until they become soft and transparent.Once the onions are cooked, add ginger garlic paste and mix well.", "Add cooked chickpeas, red chilli powder, turmeric powder, coriander powder, cumin powder and mix everything properly.", "Cook for about a minute.After a minute, add soaked basmati rice and required amount of water.", "Cover and cook until the water is drained and rice is cooked well.", "In case of using pressure cooker, cook over medium heat for 2 whistles.", "Garnish it with coriander.The next step is to make the Sweet Hot Date Onion Chutney.", "Firstly, soak the red chilies in a cup of hot water for 10 minutes and keep it aside.Meanwhile, heat oil in a frying pan and add onions.", "Add required amount of salt.Saut\u00e9 until the onions become slightly brown.", "Once browned, remove from the stovetop and keep them aside.Chop dates finely.", "It\u2019s good to soak dates in water for 10 minutes so that it can be chopped easily.Drain water from chilies.", "Grind chopped dates and chilies in a mixer for about 5 minutes.", "Add the onion mixture and grind to a fine smooth paste in a mixer grinder and the chutney is ready to be served.Serve the\u00a0Pakistani Chickpeas Pulao\u00a0With Sweet Hot Date Onion Chutney,\u00a0Burani Raita\u00a0and a roasted\u00a0Papad\u00a0for a delicious meal."]'::jsonb, 75, 'Pakistani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Pakistani_Chickpeas_Pulao_with_Sweet_Hot_Date_Onion_Chutney.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/762.Pakistani_Chickpeas_Pulao_with_Sweet_Hot_Date_Onion_Chutney.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Palak Gobi Sabzi Recipe (Indian Style Cauliflower with Spinach)', 'palak-gobi-sabzi-recipe-indian-style-cauliflower-with-spinach', 'Palak Gobi Sabzi is a simple and healthy recipe that can be made for a quick weeknight meal. It is very similar to the Aloo Gobi Sabzi, the only addition is the spinach that adds more nutrition, colour and taste to the vegetable. Adding just a few spices into the vegetable brings out the best flavors from it. Serve Palak Gobi Sabzi with hot Phulkas or Tawa Paratha.', '["2 cups Spinach Leaves (Palak) , finely chopped", "1 Cauliflower (gobi) , cut into small florets", "2 Tomatoes , freshly pureed", "1 inch Ginger , peeled and grated", "1/2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Turmeric powder (Haldi)", "1-1/2 teaspoon Garam masala powder", "Salt , to taste", "1 tablespoon Oil", "4 sprig Coriander (Dhania) Leaves , roughly chopped to garnish"]'::jsonb, ARRAY['s spinach leaves', 'palak', 'cauliflower', 'gobi', 'tomatoes', 'ginger', 'cumin seeds', 'jeera', 'turmeric powder', 'haldi', 'garam masala powder', 'salt', 'oil', 'coriander', 'dhania']::text[], '["To make Palak Gobi Sabzi, first chop the spinach and cauliflower.", "Keep aside in different bowls until required.Heat oil in a pan over medium heat.", "Add the chopped spinach along with a little salt and saute on medium heat until the spinach is cooked and softened.", "Turn off the heat and transfer the spinach to another bowl to stop the cooking process.", "The more the spinach remains in contact with it, the more the colour tends to fade to dull green.Again heat a tablespoon of oil in a heavy bottomed pan.", "Add the grated ginger and cumin seeds.", "Saute them for a few seconds.", "Add the pureed tomatoes, turmeric powder, garam masala powder, salt and stir to combine.Finally, add the cauliflower florets.", "Add a little water to cook the cauliflower, cover the pan with the lid, turn the heat to low, cook the cauliflower for few minutes till it is tender.The\u00a0cauliflower\u00a0will be soft, yet firm and delicious to taste.", "At last, stir in the sauteed spinach, stir to combine.", "Turn off the heat.", "Garnish with chopped coriander leaves.", "Serve the Palak Gobi Sabzi\u00a0with\u00a0Hot Phulka\u00a0or\u00a0Tawa Parathas\u00a0along with a bowl of\u00a0Punjabi Kadhi."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Palak_Gobi_Sabzi_Recipe_Indian_Style_Cauliflower_with_Spinach-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/763.Palak_Gobi_Sabzi_Recipe_Indian_Style_Cauliflower_with_Spinach-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Parangikkai Keerai Kuzhambu Recipe (Pumpkin Spinach Curry)', 'parangikkai-keerai-kuzhambu-recipe-pumpkin-spinach-curry', 'Parangikkai Keerai Kuzhambu is a yellow pumpkin curry combined with spinach to make a delicious weeknight dinner. This is a favorite preparation where the combination of green chillies and coconut along with coriander seeds and jaggery adds a touch of spice and sweetness. We love the pumpkin spinach curry (Parangikkai Keerai Kuzhambu) at home and typically savor it with steamed rice or broken wheat.', '["3 cups Kaddu (Parangikai/ Pumpkin) , cut to 1-inch cubes (or butternut squash)", "1 inch Ginger", "1 teaspoon Chana dal (Bengal Gram Dal)", "2 cups Spinach Leaves (Palak) , tightly packed", "1 teaspoon White Urad Dal (Split)", "1/2 cup Tamarind Water", "1 tablespoon Jaggery", "1/2 cup Fresh coconut , grated", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies , long", "5 Curry leaves", "Ingredient for curry paste", "1 teaspoon Coriander (Dhania) Seeds", "2 Green Chillies", "1 tablespoon Oil"]'::jsonb, ARRAY['s kaddu', 'parangikai/ pumpkin', 'ginger', 'chana dal', 'bengal gram dal', 's spinach leaves', 'palak', 'white urad dal', 'split', 'tamarind water', 'jaggery', 'fresh coconut', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'dry red chillies', 'curry leaves', 'ingredient for curry paste', 'coriander', 'dhania', 'reen chillies', 'oil']::text[], '["To begin making the Parangikkai Keerai Kuzhambu Recipe, in a small fry pan; roast the channa dal and urad dal until brown.", "Roast on medium heat as you want the dals to gete roasted well and not feel raw.Grind the above roasted dal along with the ingredients in the curry paste into a smooth paste in a mixer.", "You can use a 1/4 cup of hot water if required for grinding.", "This will help if you are using frozen coconut and help grind into a smooth paste."]'::jsonb, 45, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Archana_Doshi/Parangikai_Keerai_Kuzhambu_Recipe_Amaranth_Pumpkin_Coconut_Curry_South_indian-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/764.Parangikai_Keerai_Kuzhambu_Recipe_Amaranth_Pumpkin_Coconut_Curry_South_indian-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Missi Roti Recipe (Spiced Gram Flour Flat Bread)', 'missi-roti-recipe-spiced-gram-flour-flat-bread', 'Missi Roti is delectable flatbread from Rajasthan that is made from gram flour and spiced with green chilies and flavored with black salt and ginger. The Missi roti tends to get dry, so it good to serve it hot along with butter and jaggery, accompanied with Sev usal or Palak Makhana Recipe.', '["1-1/2 cups Gram flour (besan)", "1/2 Whole Wheat Flour", "2 Green Chillies , finely chopped", "1 Onion , finely chopped", "1 inch Ginger , grated", "1 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Whole Black Peppercorns , coarsely pounded", "1/2 teaspoon Black Salt (Kala Namak)", "Salt , to taste", "Oil , or ghee for smearing"]'::jsonb, ARRAY['s gram flour', 'besan', 'whole wheat flour', 'reen chillies', 'onion', 'ginger', 'turmeric powder', 'haldi', 'whole black peppercorns', 'black salt', 'kala namak', 'salt', 'oil']::text[], '["To begin making the Missi Roti Recipe, combine all the ingredients together in a large bowl.", "Add a little water at a time and knead to make a firm and smooth dough.Once the dough has come together, drizzle a little oil over the dough and knead to make it smooth and soft.Cover the dough and allow it to rest for at least 15 minutes.Divide the dough into 10 equal portions and shape into balls.", "Dust in a little flour and roll out each portion of dough into a 4-inch diameter circle.Place the missi roti dough on a preheated iron skillet and cook on both sides using a little oil or ghee.", "Cook until lightly browned and cooked through.", "The missi roti will be little crisp from the outside and yet soft inside.Proceed the same way with the remaining dough portions.Serve the Missi Roti along with butter and your favorite Palak Makhana Recipe."]'::jsonb, 60, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breads/Missi_Roti_Spiced_Gram_Flour_High_Protien_Flat_Bread-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/765.Missi_Roti_Spiced_Gram_Flour_High_Protien_Flat_Bread-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Paruppu Urundai Kuzhambu (Steamed Lentil Balls Cooked in a Tangy Curry) Recipe', 'chettinad-paruppu-urundai-kuzhambu-steamed-lentil-balls-cooked-in-a-tangy-curry-recipe', 'Chettinad Paruppu Urundai Kuzhambu (Steamed Lentil Balls Cooked in a Tangy Curry) is a traditional curry from the chettinad region of the Tamil Nadu. Chettinad cuisine is believed to be one the spiciest cuisines in India. The preparation is fairly simple, but has a perfect mix of flavors. Paruppu Urundai Kuzhambu, means steamed lentil balls dunked in a spicy, tangy curry in tamil.', '["Ingredients for the Paruppu Urundai (Lentil Balls)", "1 cup Chana dal (Bengal Gram Dal)", "1/4 cup Arhar dal (Split Toor Dal)", "1 Onion , finely chopped", "1 Dry Red Chilli", "1 teaspoon Fennel seeds (Saunf)", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Asafoetida (hing)", "4 sprig Coriander (Dhania) Leaves , finely chopped", "2-3 Curry leaves , finely chopped", "Salt , to taste", "Ingredients to be ground to paste", "1/2 cup Fresh coconut", "1 teaspoon White Urad Dal (Split)", "1 teaspoon Fennel seeds (Saunf)", "3 Dry Red Chillies", "Ingredients for the Gravy", "1 Onion , finely chopped", "6 cloves Garlic , roughly chopped", "2 Tomatoes , finely chopped", "1/2 cup Tamarind Water", "2 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "4 sprig Coriander (Dhania) Leaves , finely chopped", "Ingredients for seasoning", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Fennel seeds (Saunf)", "1/4 teaspoon Asafoetida (hing)", "2 tablespoon Sesame (Gingelly) Oil", "1 sprig Curry leaves", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'asafoetida (hing)', 'sesame (gingelly) oil', 'cloves garlic', 'curry leaves', 'white urad dal (split)', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'chana dal (bengal gram dal)', 'salt', 'arhar dal (split toor dal)', 'dry red chillies', 'tamarind water', 'coconut', 'mustard seeds', 'dry red chilli', 'fennel seeds (saunf)', 'curry leaves', 'coriander (dhania) leaves', 'coriander powder']::text[], '["To begin making Chettinad Paruppu Urundai Kuzhambu (Steamed Lentil Balls Cooked in a Tangy Curry) Recipe, first prepare making the lentil balls.", "Soak the channa and toor dal along with dry red chilli and fennel seeds for an hour.Grind the soaked dals along with the fennel seeds, cumin seeds and asafoetida to a smooth mix.", "Now take the ground lentil mix in a bowl and add the finely chopped onion, coriander and curry leaves, season with salt and mix it well.Make small lemon sized balls of this mix and steam it for 10 minutes.", "Once done let it cool and keep it aside.The next step is to is to make the coconut paste.", "In a small pan, roast the fenugreek seeds, urad dal and the red chilies until browned and crisp over medium heat.", "You will find the aromas coming through.", "Once you can smell the aromas, add the coconut and roast for about a minute and turn off the heat and allow it to cool for a few minutes.Blend the coconut mixture into a smooth paste in a blender by adding very little warm water and keep aside.Now heat oil in big wok\u00a0on medium heat.", "Add the mustard seeds and allow it to crackle.", "Add the fennel seeds, curry leaves, and let it splutter.", "Add the asafoetida and stir for a few seconds.Add the finely chopped onions and chopped garlic and saut\u00e9 till the onions turn transparent.Now add the finely chopped tomatoes and cook until its mashed.Add the tamarind water, coriander powder and turmeric powder and let it simmer until the raw smell of the tamarind water goes away.At this stage add the coconut paste and bring it to a rolling boil.Add the steamed lentil balls to this gravy and simmer for another 10 minutes and switch it off.", "Check the salt and spices and adjust to suit your taste.", "Adjust the consistency of the Kuzhambu by adding water if required.Your\u00a0Chettinad Paruppu Urundai Kuzhambu is ready to be served.", "Transfer the Kuzhambu to a serving bowl and garnish with coriander leaves on top.", "Serve the Chettinad Paruppu Urundai Kuzhambu (Steamed Lentil Balls Cooked in a Tangy Curry) with Steamed Rice, Kootu, Poriyal and Appalam."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Chettinad_Paruppu_Urundai_Kuzhambu_Steamed_Lentil_Balls_Cooked_in_a_Tangy_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/766.Chettinad_Paruppu_Urundai_Kuzhambu_Steamed_Lentil_Balls_Cooked_in_a_Tangy_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Healthy Methi Matar Malai (No Cream) Recipe', 'healthy-methi-matar-malai-no-cream-recipe', 'Light & Healthy Methi Matar Ki Sabzi is a classic dish that is most often made with a lot of cream and cashew nuts, making it heavy. This recipe is light and nutritious and made with ingredients like hung curd and almonds to neutralize the bitterness of the fenugreek leaves. You can serve the Methi Matar Malai along with Tawa Paratha for a weeknight dinner.', '["250 grams Methi Leaves (Fenugreek Leaves) , finely chopped", "100 grams Green peas (Matar) , steamed", "Salt , to taste", "1/2 teaspoon Cumin seeds (Jeera)", "1 Tomato , pureed", "1/2 cup Hung Curd (Greek Yogurt)", "1/2 teaspoon Sugar", "1 teaspoon Garam masala powder", "1 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Black pepper powder", "Masala Ingredients - Grind to make a smooth paste", "1 Onion , roughly chopped", "2 Green Chillies", "1 inch Ginger", "2 cloves Garlic", "6 Whole Almonds (Badam)", "1 teaspoon Poppy seeds"]'::jsonb, ARRAY['s methi leaves', 'fenugreek leaves', 's green peas', 'matar', 'salt', 'cumin seeds', 'jeera', 'tomato', 'hung curd', 'greek yogurt', 'sugar', 'garam masala powder', 'turmeric powder', 'haldi', 'black pepper powder', 'masala ingredients - grind to make a smooth paste', 'onion', 'reen chillies', 'ginger', 's garlic', 'whole almonds', 'badam', 'poppy seeds']::text[], '["To begin making the Healthy Methi Mutter Malai (No Cream), we will first make a smooth paste of the masala ingredient.", "Next, heat a teaspoon of oil in a heavy bottomed pan; add the methi leaves and salt.", "Saute the methi leaves until softened.", "Once softened, remove from the pan, place it in another bowl and keep aside.", "Remember if you overcook the leaves, it will lose its nutritive value.In the same pan, add a teaspoon of oil.", "Stir in the ground masala paste and saute until the raw smell from the onions go away.", "This will take about 4 to 5 minutes on low to medium heat.Once done, stir in the turmeric powder, garam masala powder, pepper powder and the tomatoes.", "Stir to combine well.", "Add in the hung curd, and give it a stir.", "Finally, stir in the cooked leaves and the steamed peas.", "Turn the heat to low and simmer for a few minutes until all the flavours come together.Check the salt and spice levels and the Methi Matar Malai would be ready to be served along with Tawa Paratha."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Methi_Matar_Malai_Sabzi_Recipe-14.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/767.Methi_Matar_Malai_Sabzi_Recipe-14.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Parsi Style Vegetable Dhansak Recipe- Parsi Vegetable Dal', 'parsi-style-vegetable-dhansak-recipe-parsi-vegetable-dal', 'Parsi Cuisine is one of the traditional cuisine of the Parsis of India. Parsis are known for their love for good food, good music. Parsi cuisine has a West Indian cuisine influence. They also retain their food flavors and techniques from ancient Persian cuisine. One of the most popular Parsi foods is Dhansak. It’s traditionally meat and vegetables cooked in lentils. A very flavorful special masala called the dhansak masala makes this dish special and unique. Though Parsis are enthusiastic non-vegetarians, they have some delicious vegetarian recipes too.', '["1/2 cup Arhar dal (Split Toor Dal)", "1/2 cup Yellow Moong Dal (Split)", "1/2 cup Chana dal (Bengal Gram Dal)", "50 grams Methi Leaves (Fenugreek Leaves) , roughly chopped", "20 Mint Leaves (Pudina) , roughly chopped", "2 Green Chillies , finely chopped", "2 Small Brinjal (Baingan / Eggplant) , diced", "1 cup Kaddu (Parangikai/ Pumpkin) , diced", "2 Turnips , diced", "1 Onions , thinly sliced", "1 teaspoon Turmeric powder (Haldi)", "1 Onion , thinly sliced", "2 Tomatoes , roughly chopped", "2 teaspoon Oil , or ghee", "1 tablespoon Lemon juice", "Salt , to taste", "Water , as required", "3 cloves Garlic", "2 inch Ginger", "2 Green Chillies", "1-1/2 teaspoon Whole Black Peppercorns", "1-1/2 teaspoon Cumin seeds (Jeera)", "5 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 tablespoon Coriander (Dhania) Seeds"]'::jsonb, ARRAY['tomato', 'parangikai pumpkin', 'brinjal (baingan eggsplant)', 'cloves garlic', 'black peppercorns', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies', 'chana dal (bengal gram dal)', 'salt', 'arhar dal (split toor dal)', 'sunflower oil ghee', 'mint leaves (pudina)', 'water', 'lemon', 'yellow moong dal (split)', 'ginger', 'methi leaves (fenugreek leaves)', 'cinnamon stick (dalchini)', 'turnips', 'cloves (laung)']::text[], '["To begin making the Vegetable Dhansak Recipe, we will first get all the ingredients ready and then proceed to make the Dhansak Masala.", "To make dhansak masala, grind all the ingredients mentioned under the list adding very little water to make a smooth paste.", "Keep the masala aside.", "Wash and roughly chop all the vegetables.", "Pick fenugreek leaves, mint leaves, \u00a0wash and chop them.", "Keep these aside.Soak all the 3 dals separately for about 30 minutes.Once soaked, place all three dals, vegetables, fenugreek leaves and mint leaves along with 1 thinly sliced onion, green chili and a teaspoon of turmeric powder in a pressure cooker.", "Add salt, and 3 cups of water.", "Cover the pressure cooker and cook until you hear 2 whistles.", "After 2 whistles turn the heat to low and simmer for another 3 to 4 minutes and turn off the heat.Allow the pressure to release naturally from the cooker.", "Once the pressure settles down, open the lid of the pressure cooker and mash all the ingredients using a potato masher until all the dals and vegetables get a smooth texture.", "In a heavy bottom pan, heat oil or ghee.", "Add the other thinly sliced onions and saut\u00e9 until it turns soft.", "Next add chopped tomatoes and cook till tomatoes turns soft and releases its juices.", "Stir in the dhansak masala paste and cook until the raw smell of the paste is gone.", "This would take about 4 to 5 minutes.Pour the dal vegetable mashed mixture into this masala and cook on low heat for about 10 to 20 minutes.Once well simmered, turn of the heat and squeeze in the lemon juice and add in the chopped coriander leaves.", "Stir well and the Vegetable Dhansak is ready.", "Serve the Vegetable Dhansak along with brown rice or a Homemade Butter Naan for a wholesome weeknight dinner."]'::jsonb, 75, 'Parsi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Vegetable_Dhansak.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/768.Vegetable_Dhansak.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sesame Peanut Potato Mix Recipe', 'sesame-peanut-potato-mix-recipe', 'Sesame Peanut Potato Mix is a delicious combination of potatoes and peanut. It is spicy and tangy in taste and can be served as a side dish with your meals.', '["Oil , as required", "10 Curry leaves", "2 tablespoons Sesame seeds (Til seeds)", "3 Green Chillies , finely chopped (adjust according to your taste)", "2 tablespoon Raw Peanuts (Moongphali) , crushed and fried or roasted", "3 Potatoes (Aloo) , boiled and diced", "1 tablespoon Amchur (Dry Mango Powder)", "1 tablespoon Cumin powder (Jeera)", "1 tablespoon Black pepper powder", "6 sprig Coriander (Dhania) Leaves , finely chopped", "Salt , Salt as required"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'amchur (dry mango powder)', 'curry leaves', 'coriander (dhania) leaves', 'sesame seeds (til seeds)', 'peanuts (moongphali)', 'black pepper powder', 'potato (aloo)', 'green chillies', 'sunflower oil']::text[], '["To begin making the Sesame Peanut Potato Mix, heat oil in a wok/kadhai and add curry leaves, white sesame seeds, green chillies and saute for 2 minute on low flame. (Make sure that you do not burn them)After 2 minutes, add the diced potatoes and saute for about 5 to 6 minutes.Once it is done, add the crushed peanuts, cumin powder, black pepper powder, amchur powder, salt as required and saute for one more minute.After a minute, garnish Sesame Peanut Potato Mix with chopped coriander and it is ready to be served.Serve Sesame Peanut Potato Mix with\u00a0Phulkas\u00a0or\u00a0Whole Wheat Lachha Parathas.", "You can also have it on its own with a cup of hot tea as a tea time snack."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Sesame_peanut_potato_mix.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/769.Sesame_peanut_potato_mix.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pandu Mirapakaya Pachadi  - Andhra Red Chilli Chutney Recipe', 'pandu-mirapakaya-pachadi-andhra-red-chilli-chutney-recipe', 'Andhra Ripe Red Chilli Chutney also known as the Pandu Mirapakaya Pachadi is a simple South Indian chutney which is made with fresh red chillies. This chutney is easy to make and requires very few ingredients. This is a perfect chutney to serve along with Dosa, Idli and Uttapam for your breakfast.', '["100 grams Fresh Red chillies", "1 tablespoon Tamarind Paste", "2 tablespoons Gingelly oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Asafoetida (hing)", "1/2 teaspoon Methi Powder (Fenugreek Powder)", "Salt , to taste"]'::jsonb, ARRAY['s fresh red chillies', 'tamarind paste', 's gingelly oil', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing', 'methi powder', 'fenugreek powder', 'salt']::text[], '["To begin making the Andhra Ripe Red Chilli Chutney Recipe/\u00a0Pandu Mirapakaya Pachadi, remove the stalks of the chillies and thoroughly wash and pat dry them.Heat a little oil in a heavy bottomed pan.", "Add the fresh red chillies and fry them on medium heat for 2 minutes.", "Once done, remove and set them aside.", "Let the chillies cool down a bit.Once the chillies come to room temperature, grind the chillies with tamarind paste into smooth texture or as per your required consistency.Keep scraping the sides of the\u00a0Pandu Mirapakaya Pachadi and do not add much water while grinding.Heat 2 tablespoons oil in a pan.", "Add mustard seeds and once it crackles add asafoetida.After 10 seconds, add in the red chilli tamarind paste and let it cook for about a minute.", "Turn off the flame, allow the Pandu Mirapakaya Pachadi to cool and store it in an airtight container in the refrigerator.Serve\u00a0Andhra Ripe Red Chilli Chutney/\u00a0Pandu Mirapakaya Pachadi\u00a0along with\u00a0Ghee Roast Dosa\u00a0and\u00a0Keerai Sambar\u00a0for a weekday breakfast."]'::jsonb, 20, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Affiliate-Articles/ANDHRA_RIPE_RED_CHILLI_CHUTNEY_original.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/770.ANDHRA_RIPE_RED_CHILLI_CHUTNEY_original.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Fruit Pachadi Recipe', 'fruit-pachadi-recipe', 'A sweet, juicy and tasty fruits and yogurt delicacy with lots of coconut and green chilies makes Fruit Pachadi Recipe. This is a South Indian style fruit raita where fruits are cooked and then mixed with yogurt and tempered with chilli and mustard. The pachadi tastes heavenly when served with lunch or dinner and of course, it suits to play the role of mock role of dessert as well. Serve Fruit Pachadi Recipe with Fried Samvat Rice recipe or with Amritsari Ajwaini Paneer Recipe with hot Phulkas.', '["2 cups Mixed fruits , cubed to bite size (I used pineapple, mango, kiwi, apple, pear, & whole grapes]", "1 1/2 cup Curd (Dahi / Yogurt) , whisked", "1/4 teaspoon Turmeric powder (Haldi)", "2 teaspoon Jaggery", "Salt , to taste", "Water , as required", "1/4 cup Fresh coconut , grated", "2 Green Chillies , roughly chopped", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chilli , broken", "1 teaspoon Oil", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'mixed fruits pineapple', 'coconut', 'mustard seeds', 'jaggery', 'water', 'dry red chilli', 'curd', 'curry leaves', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To prepare Fruit Pachadi recipe, take a paste of coconut, green chillies and mustard seeds in a blender using a little water.", "Keep it aside.Heat a pan and add chopped fruits and two tablespoons of water.", "Cook on simmer for about 5 minutes or until fruits are softened.Add turmeric powder, salt and sugar or jaggery.", "Stir and add the coconut paste.Cook for a few minutes more until the water is absorbed.", "Remove fruit pachadi from heat and add whisked yogurt.Heat oil in a pan and add mustard seeds, dry red chillies and curry leaves.", "Saute for a minute.", "Pour the tempering over the fruit pachadi.", "Mix to combine.", "Refrigerate until served.Serve Fruit Pachadi Recipe with Fried Samvat Rice recipe or with Amritsari Ajwaini Paneer Recipe with hot Phulkas."]'::jsonb, 20, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sapanabehl/Fruit_Pachadi_edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/771.Fruit_Pachadi_edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chingiri Paturi Recipe', 'chingiri-paturi-recipe', 'Chingiri Paturi or Prawn Paturi is a famous traditional dish from Bengal cuisine that also belongs to the coastal region of West Bengal. Prawns cooked with minimum ingredients are parceled in banana leaf and then steamed is a delicious recipe that comes from my mother''s diary. The dish is typically enjoyed with plain hot rice with a tinge of lemon on it.', '["500 grams Prawns , medium size", "1/2 cup Poppy seeds", "1/3 cup Mustard seeds (Rai/ Kadugu)", "1/2 cup Fresh coconut , grated", "4 Green Chillies", "1/2 teaspoon Salt , adjustable", "3 tablespoon Mustard oil", "1 teaspoon Lemon juice", "1 Banana leaf , big (cut into 4 halves)"]'::jsonb, ARRAY['salt', 'mustard oil', 'coconut', 'mustard seeds', 'banana leaf', 'poppy seeds', 'lemon', 'green chillies', 'prawns']::text[], '["To begin with the Chingiri Paturi Recipe start by soaking khus khus for minimum 3 to 4 hours or overnight.Wash and clean prawns nicely in salt water to remove that fishy smell.In a grinder jar, take soaked khuskhus, mustard seeds, green chilies and grated coconut.", "Grind to make a thick & smooth paste.Add salt as per taste and mustard oil in the paste.", "Mix well and keep aside.Heat 2 cups of water in a pan and add few drops of lemon juice and 2 pinch of salt.As soon as the water starts boiling, add prawns and turn off the gas and remove pan from the stove and keep aside for few minutes.The prawns will blanch and also get properly cleaned.", "After a while, drain water and collect the prawns and keep aside.Heat mustard oil in a non stick pan and saute the prawns for 2-3 mins.", "Divide the prawns in four equal portions and keep aside.For making leaf parcels, first take a banana leaf and heat on stove top very carefully from both sides.", "Keep the leaf high from flames to avoid getting burnt.", "By doing this the leaf will soften and get easily folded like a fabric without tearing apart.", "Do this for all for pieces of leaf and keep aside.Now take a banana leaf piece and place around of khuskhus paste in the center.Now add one portion of sauteed prawns on the paste.", "Gently mix such that the paste coats all over the prawns.Add some more paste over the prawns and around mustard oil on top.Carefully fold the two opposite sides of the leaf inwards and then the next two sides inwards to make parcels.Tie the packet cris-cros with thread and put a knot.", "Make other parcels following the same method and keep aside.Heat a non stick pan that has a lid.", "Brush some mustard oil all over.Place the parcels on the pan and cover the lid.Steam the parcels in low flames for 10 mins or till you find the color of leaf changing.Carefully flip the parcel and steam from the other side as well.", "This might take 15-20 mins in total.Turn of the gas and carefully transfer the parcels on the serving plate and serve hot with plain steamed rice.Do not open the parcel before serving, they shall be opened by the one who is about to relish this delicacy.Enjoy the\u00a0Chingiri Paturi Recipe with some hot rice and samar for amazing lunch."]'::jsonb, 45, 'Bengali', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shaheen_Ali/CHINGIRI_PATURI__PRAWN_PATURI.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/772.CHINGIRI_PATURI__PRAWN_PATURI.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Green Chilli Vegetable Recipe', 'green-chilli-vegetable-recipe', 'Green Chilli Vegetable is a quick and easy recipe which can be served with paratha or roti. It is best served as a side dish along with your Rajasthani or Gujarati meal. The spiciness and the sweetness of this dish makes the entire meal more tasty and flavourful.', '["200 grams Green Chillies", "1 tablespoon Oil", "1 tablespoon Mustard seeds (Rai/ Kadugu)", "1/2 tablespoon Salt", "1/2 tablespoon Turmeric powder (Haldi)", "1/4 tablespoon Red Chilli powder", "1/2 tablespoon Fennel Powder", "1/2 tablespoon Coriander Powder (Dhania)", "1 tablespoon Lemon juice", "1/2 teaspoon Sugar"]'::jsonb, ARRAY['salt', 'mustard seeds', 'red chilli powder', 'fennel powder', 'sugar', 'lemon', 'coriander powder', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Green Chilli Vegetable recipe, take green chillies and cut into small pieces.Heat oil in a heavy bottomed pan and add mustard seeds.", "Once the mustard seeds starts to crackle, add green chillies.Add turmeric powder, salt, chilli powder, fennel powder, coriander powder.", "Mix it well and let it cook for 3 to 4 minutes.Once it is cooked, then add lime juice and sugar.", "Mix well and cook for another one minute.Serve Green Chilli Vegetable along with\u00a0Panchmel Dal\u00a0and\u00a0Hot Phulkas\u00a0for a simple and delicious weekday lunch or dinner."]'::jsonb, 20, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Green_Chilli_Vegetable.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/773.Green_Chilli_Vegetable.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hariyali Tawa Fish Fry Recipe', 'hariyali-tawa-fish-fry-recipe', 'Hariyali Tawa Fish Fry Recipe is a lip smacking non vegetarian fish recipe where the fish is marinated with a hint of traditional spices like garam masala powder, lemon, coriander leaves and also mint leaves and then pan fried.', '["500 gram Fish , (rohu fish is used here)", "1/2 tablespoon Turmeric powder (Haldi)", "2 teaspoons Garam masala powder", "1 Tablespoon Red Chilli powder", "2 Tablespoon Coriander (Dhania) Leaves , chopped", "1-1/2 tablespoons Mint Leaves (Pudina) , chopped", "2 teaspoons Lemon juice", "2 Green Chillies", "3 cloves Garlic", "1/2 Onion", "1 Tablespoon Curd (Dahi / Yogurt)", "1 teaspoon Gram flour (besan)", "Oil , to shallow fry", "Salt , to taste"]'::jsonb, ARRAY['salt', 'coriander (dhania) leaves', 'red chilli powder', 'cloves garlic', 'gram fish (rohu fish used here)', 'gram flour (besan)', 'curd', 'onion', 'lemon', 'mint leaves (pudina)', 'turmeric powder', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To begin making Hariyali Tawa Fish Fry Recipe, get prep with all the ingredients first.", "You can clean the fish fillets.In a blender, blend coriander leaves, onions, mint leaves, green chillies, garlic cloves & gram flour together with a little water to make a thick paste.Now take all the fish pieces in a wide mixing bowl.", "Add the ground masala paste, yogurt, lemon juice, salt, garam masala powder, turmeric powder, red chilli powder and mix everything well.Make sure that fish pieces are coated properly with this mixture.", "Let it marinate for 10 minutes.Once the fish is marinated, heat up some mustard oil on a shallow frying pan and place the marinated fish on it along with the masala.", "Fry it until it is cooked from both sides.Serve\u00a0Hariyali Tawa Fish Fry Recipe and\u00a0Dhaniya Pudina Chutney Recipe (Green Chutney)\u00a0with\u00a0Butter Garlic Naan Recipe (Garlic Flavoured Flat Bread), &\u00a0Creamy Butter Chicken Recipe\u00a0or\u00a0Dal Palak Recipe (Spinach And Lentil Curry)\u00a0for a complete meal."]'::jsonb, 30, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/garimasgautam-gmail.com/Haryiali_Tawa_Fish_Fry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/774.Haryiali_Tawa_Fish_Fry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Gobi Matar Ki Sabzi Recipe', 'aloo-gobi-matar-ki-sabzi-recipe', 'Aloo Gobhi Matar Ki Sabzi Recipe is made of potatoes, cauliflower and green peas mixed with spices. This is a wholesome dish that is perfect when served with hot Chapatis, pooris, or dal rice for lunch or dinner. The veggie Aloo Gobhi Matar Ki Sabzi Recipe is very simple to make and requires very basic ingredients. This sabzi is great also for kids lunch boxes with plain parathas since potatoes, cauliflower and green peas is a good combination.', '["1/2 kg Cauliflower (gobi) , floret", "2 Potato (Aloo)", "1 cup Green peas (Matar)", "2 teaspoon Red Chilli powder", "1 tablespoon Coriander Powder (Dhania)", "1 tablespoon Turmeric powder (Haldi)", "2 tablespoon Onion , finely chopped", "1 teaspoon Ginger , finely chopped", "1 teaspoon Methi Leaves (Fenugreek Leaves)", "1 sprig Coriander (Dhania) Leaves , for garnishing", "Oil , as required", "Salt , to taste"]'::jsonb, ARRAY['cauliflower', 'gobi', 'potato', 'aloo', 'green peas', 'matar', 'red chilli powder', 'coriander powder', 'dhania', 'turmeric powder', 'haldi', 'onion', 'ginger', 'methi leaves', 'fenugreek leaves', 'coriander', 'oil', 'salt']::text[], '["To prepare Aloo Gobhi Matar Ki Sabzi Recipe, put the florets in a large bowl and cover with hot water.", "Add a teaspoon of salt and mix well.", "Keep aside for 10 minutes.Peel wash and cut the potato into small pieces and put potatoes in cold water.Heat the oil in a kadai or a non-stick pan.", "Add fenugreek seeds, when they splutter, saut\u00e9 ginger and onion.Now add the cauliflower florets, peas, potatoes and fry for few minutes stirring occasionally.Cover and cook for 2-3 minutes.Now add turmeric, red chili powder, coriander powder and salt stir and mix well all the spices and veggies together.", "Adjust salt.Cover with a tight-fitting lid and cook on low flame for 5 to 6 minutes.", "Turn off the heat.Garnish with coriander, serve Aloo Gobhi Matar Ki Sabzi Recipe hot with chapati or poori."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/hem_lata_srivastava/Aloo_gobhi_aur_matar_ki_sabji.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/775.Aloo_gobhi_aur_matar_ki_sabji.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gobi and Soya Keema Recipe', 'gobi-and-soya-keema-recipe', 'Keema is a South Asian meat dish that literally means minced meat in Turkish. Keema can be made with any meat but usually Keema is associated with mutton mince. Most Keemas are minced meats that are mixed with aromatic spices that are either eaten by itself or added to rice or stuffed in breads.', '["500 grams Cauliflower (gobi) , grated", "1 cup Soy Chunks (Nuggets)", "6 Baby Potatoes , peeled and cut into half", "1/2 cup Green peas (Matar) , steamed", "1 Onion , roughly chopped", "1 Green Chilli , chopped", "1 inch Ginger", "2 cloves Garlic", "Salt , as per taste", "2 tablespoon Ghee", "1 teaspoon Red Chilli powder", "2 teaspoon Garam masala powder", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 Bay leaf (tej patta)", "Ingredients for garnish", "5 sprig Coriander (Dhania) Leaves , roughly chopped", "1 teaspoon Lemon juice"]'::jsonb, ARRAY['s cauliflower', 'gobi', 'soy chunks', 'nuggets', 'baby potatoes', 'green peas', 'matar', 'onion', 'reen chilli', 'ginger', 's garlic', 'salt', 'ghee', 'red chilli powder', 'garam masala powder', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'bay leaf', 'tej patta', 'ingredients for garnish', 'coriander', 'lemon juice']::text[], '["To prepare for Gobi and Soya Keema Recipe, first clean, wash and pat dry cauliflower.", "Remove the green stem with knife and cut cauliflower into three parts.", "Small size pieces make grating much easier.For grating cauliflower either you can use hand held vegetable grater or food processor to get fine evenly grated cauliflower.", "Meanwhile in a pan boil one cup of water, once water comes to boil add the soya granules.", "Let it boil in water for 1 - 2 minutes.", "Switch off the flame and drain in a colander.", "Keep aside until required.In a heavy bottomed saucepan heat ghee over medium heat.", "Now add bay leaf, once the aroma of bay leaf starts releasing, add the chopped onions.", "Saute over medium heat until the onions turn light brown in color.", "Once onion turn brown in color, add chopped green chilies and ginger garlic paste with 1/4 Cup water to avoid masala sticking to the pan.", "Saute over medium heat for 2 to 3 minutes.", "After 2 to 3 minutes add baby potatoes, peas, salt, turmeric powder, red chili powder, coriander powder and give it a nice stir.", "Saute for 5 minutes over medium heat.", "Now add grated cauliflower, boiled soya granules and garam masala.", "Give it a nice mix, reduce the flame to low, cover the pan with a lid and let it cook over low heat for 10 - 15 minutes or until vegetables are cooked through especially the potatoes.", "Just before serving drizzle lemon juice on top and garnish with chopped coriander.", "Serve\u00a0Gobi and Soya Keema\u00a0along with\u00a0Panchmel Dal\u00a0and\u00a0Phulka\u00a0for a weekday dinner with your family."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Hina_Gujral/Gobi_and_Soya_Keema_recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/776.Gobi_and_Soya_Keema_recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tamil Nadu Style Kothamali Aval Upma Recipe - Coriander Poha Recipe', 'tamil-nadu-style-kothamali-aval-upma-recipe-coriander-poha-recipe', 'Tamil Nadu Style Kothamalli Aval Upma Recipe is an easy recipe made with flattened rice flakes (poha) that is tossed with fresh and aromatic coriander paste. Toasted peanuts are also added to this poha to give it an extra crunch while eating. In many states, this type of preparation is common and called different names such as poha in North India and Upma in the South part of India.', '["2 cups Poha (Flattened rice)", "1/4 teaspoon Turmeric powder (Haldi)", "Salt and Pepper , to taste", "To be Ground to Paste", "1/4 cup Fresh coconut", "1/4 cup Coriander (Dhania) Leaves , roughly chopped", "2 Green Chillies", "1 tablespoon Jaggery", "1 tablespoon Lemon juice", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "2 sprig Curry leaves , roughly torn"]'::jsonb, ARRAY['salt', 'coconut', 'poha (flattened rice)', 'coriander (dhania) leaves', 'mustard seeds', 'jaggery', 'curry leaves', 'white urad dal (split)', 'lemon', 'pepper', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["We begin making the Tamil Nadu Style Kothamalli Aval Upma Recipe by washing the flattened rice in cold running water using a strainer and keep it aside, for the water to drain.", "Using a mixer, combine the\u00a0fresh coconut, coriander leaves,\u00a0green chillies,\u00a0jaggery, lime juice.", "Grind to a coarse mixture, making sure you do not make it smooth.", "Transfer to a bowla and set aside.", "Heat a flat skillet with oil on medium flame, add the mustard seeds, urad dal, curry leaves and allow it to splutter.Add the ground coconut coriander mixture to the skillet, finally add the soaked and drained flattened rice and give it a toss.", "Check for seasoning if required.", "Serve the Tamil Nadu Style Kothamali Aval Upma Recipe along with a\u00a0 cuppa hot\u00a0Masala chai."]'::jsonb, 25, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Tamil_Nadu_Style_Kothamali_Aval_Upma_Recipe_Coriander_Poha_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/777.Tamil_Nadu_Style_Kothamali_Aval_Upma_Recipe_Coriander_Poha_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Style Rista Recipe - Mutton Kofta Curry', 'kashmiri-style-rista-recipe-mutton-kofta-curry', 'Kashmiri Style Rista Recipe -Mutton Kofta Curry is a recipe that a take a lot of efforts and time to create a wonderful dish. The meatballs are made from a finely minced mutton mixed along with pound spice mix and caramelized onions. It is then fried in oil till it is crispy and brown outside. The meatballs are cooked in a tomato and onion gravy. The gravy is simple and light but it will soak up the meatballs completely.', '["150 grams Mutton Kheema", "1 Onion , sliced", "1 Green Chilli", "4 cloves Garlic", "1 inch Ginger", "1 Cardamom Powder (Elaichi)", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 teaspoon Fennel seeds (Saunf)", "Salt , to taste", "1 Onion , sliced", "1 Tomato , chopped", "1 teaspoon Cumin seeds (Jeera)", "3 cloves Garlic", "1 inch Ginger", "1 Green Chilli", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste"]'::jsonb, ARRAY['mutton kheema', 'salt', 'tomato', 'ginger', 'green chilli', 'fennel seeds (saunf)', 'red chilli powder', 'cloves garlic', 'onion', 'cinnamon stick (dalchini)', 'cardamom powder (elaichi)', 'cumin seeds (jeera)', 'turmeric powder', 'cloves (laung)']::text[], '["To begin making the Kashmiri Style Rista Recipe, saute sliced onions for the meatball.", "Fry till they turn brown and keep it aside in a bowl.In a mixer add green chillies, garlic, ginger, cardamom seeds, cloves, cinnamon and fennel seeds and grind first to a coarse mixture.Later add kheema and grind to form a smoother paste of the kheema, add this ground kheema mixture into the saut\u00e9ed onions, sprinkle salt and mix well.Shape them into a medium sized balls and keep it aside.", "Heat a kuzhi Paniyaram Pan with oil, add meatballs in each cavity and cook evenly till it turns lightly brown.To make the curry, grind garlic, ginger, cumin seeds, tomatoes, green chilli to a smooth paste.Heat a kadai with oil, add onions and saute till they turn light brown.", "Add tomato mixture and saute till the raw smell goes away.Add salt, red chilli powder and turmeric powder cook for about 10 minutes.", "Add water and allow it to boil.Add cooked meatballs into the curry and simmer for 15 minutes.", "Let the meatball soak up some of the gravy and serve hot.Serve the Kashmiri Style Rista Recipe along with\u00a0Kulcha,\u00a0jeera pulao\u00a0to enjoy the dish as a complete meal for your Sunday."]'::jsonb, 70, 'Kashmiri', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/10-oct/_Kashmiri_Style_Rista_Recipe_Mutton_Kofta_Curry-9469.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/778._Kashmiri_Style_Rista_Recipe_Mutton_Kofta_Curry-9469.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Milagu Keerai Poricha Kootu Recipe - Palak And Moong Dal Kootu', 'milagu-keerai-poricha-kootu-recipe-palak-and-moong-dal-kootu', 'The Milagu Keerai Poricha Kootu Recipe is a wholesome dish from Tamil Nadu which is packed with flavors from the roasted urad dal, black pepper which is ground along with coconut. Kootu is essentially a dal and vegetable combination which is coked with some everyday masalas.', '["300 grams Red Amaranth Leaves , washed and finely chopped", "1 cup Yellow Moong Dal (Split)", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Ingredients for Kootu Masala", "1 teaspoon Cumin seeds (Jeera)", "1 tablespoon Whole Black Peppercorns", "1/2 cup Fresh coconut , grated", "Ingredients for Seasoning", "1 teaspoon Coconut Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves , roughly torn"]'::jsonb, ARRAY['salt', 'yellow moong dal (split)', 'coconut', 'mustard seeds', 'red amaranth leaves', 'black peppercorns', 'curry leaves', 'white urad dal (split)', 'coconut oil', 'turmeric powder', 'cumin (jeera) seeds']::text[], '["To begin making the Milagu Keerai Poricha Kootu Recipe, into a pressure cooker, add the amaranth, a pinch of salt along with 2 tablespoons of water.", "Cover the cooker and pressure cook for about a whistle and turn off the heat.Place the cooker under running water to release the pressure immediately.", "This process is important to not over cook the amaranth and keep its colour.", "Open the lid of the cooker and keep aside.The next step is to make the dal.", "Add the moong dal to the pressure cooker along with,\u00a0turmeric powder, salt and 2 cups of water,.", "Cover the cooker and pressure cook the moong dal for 4 whistles and turn off the heat.Allow the pressure to release naturally.", "Once the pressure gets released, open the cooker and give a stir or a light whisk.Now, we will proceed to make the Keerai Poricha Kootu recipe.Into the mixer jar, add the\u00a0cumin seeds and black pepper corn\u00a0and the freshly grated coconut.", "Add 1/4 cup of water and blend to make a coarse paste.Stir in the cooked\u00a0keerai/amaranth into the cooked dal.", "Add the ground kootu masala into the moong dal and keerai mixture and stir well.", "Check the salt and adjust taste accordingly and bring to a brisk boil.", "The final step is to make the tadka or the seasoning.", "Heat the oil in a pan over medium heat.", "Add the mustard seeds, cumin seeds and urad dal.Allow them to crackle and the dal to turn golden brown.", "Finally add the curry leaves and turn off the heat.Add the seasoning mixture to the Keerai Kootu and stir well.", "Place the Keerai Kootu, which is still in the pressure cooker and give it a brisk boil.", "You can optionally add a tablespoon of ghee or butter to enhance the taste.Once done, transfer the\u00a0Milagu Keerai Poricha Kootu to a serving bowl and serve hot.Serve Milagu Keerai Poricha Kootu\u00a0for your South Indian lunch along with steamed rice or\u00a0Brown Rice,\u00a0Thakkali Rasam Recipe\u00a0\u00a0and\u00a0Urulaikizhangu Roast.", "You can also make this for an Indian dinner and serve it along with\u00a0Phulkas\u00a0and\u00a0Boondi Raita."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/admin/Keerai_Poricha_Kootu_Recipe_13_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/779.Keerai_Poricha_Kootu_Recipe_13_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Methi & Pudina Aloo Sabzi Recipe', 'methi-pudina-aloo-sabzi-recipe', 'Methi & Pudina Aloo Sabzi Recipe a quick, simple and nutritious vegetables that is packed with flavors from the sautéed pudina leaves and methi leaves also known as fenugreek leaves. The Aloo Methi & Pudina Sabzi when combined with the sautéed caramelized onions and mild spices, makes this dish simple and yet delectable to the palate. Pudina gives it a different flavor as well as it helps in stomach indigestion. Methi is a healthy herb that is good for hair and skin.', '["3 Potatoes (Aloo) , peeled and cubed", "250 grams Methi Leaves (Fenugreek Leaves) , washed and chopped", "250 grams Mint Leaves (Pudina) , washed and chopped", "1 Onion , thinly sliced", "1 Tomato , pureed", "1 inch Ginger , grated", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "Red Chilli powder , to taste", "1 teaspoon Cumin seeds (Jeera)", "Oil , for cooking"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'coriander powder', 'methi leaves (fenugreek leaves)', 'red chilli powder', 'onion', 'cumin seeds (jeera)', 'mint leaves (pudina)', 'potato (aloo)', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Aloo Methi & Pudina Sabzi Recipe in two stage process.", "We will first roast the potatoes and keep them aside.", "We will roast the onions, tomatoes, pudina and methi leaves and then add it to the roasted potatoes.In our first step; heat a tablespoon of oil in a heavy bottomed pan; add in the cumin seeds and the boiled cubed potatoes.", "Sprinkle some salt and a pinch of turmeric powder and saut\u00e9 on medium heat until you notice that the potatoes have started to turn golden brown in colour.Set the potatoes aside until you saute the onions and leaves.", "Heat a teaspoon of oil in a small pan or skillet; add in the onions and ginger.", "Saute on low to medium heat until you notice that the onions have become tender and turned lightly browned.Add chopped tomatoes, sprinkle little salt and saute until the tomatoes turn mushy.", "After few minutes add in all the spice powders like red chilli powder, turmeric, garam masala powder and coriander powder and mix well.Once the tomatoes are softened and browned with the masala; add in the fenugreek leaves and pudina and saute until the leaves have wilted down and softened.", "Do not saute too much, as the leaves will lose its green colour.Add roasted potatoes and stir fry on medium high until all the ingredients are well combined with the potato.", "At this stage turn off the heat.", "Keep the roasted potato aside in the same pan.", "Transfer the aloo methi & pudina sabzi to a serving dish.Serve the Methi & Pudina Aloo Sabzi Recipe along with with\u00a0Tawa Paratha\u00a0and\u00a0Punjabi Kadhi Pakora\u00a0for a quick weeknight dinner."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Methi__Pudina_Aloo_Sabzi_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/780.Methi__Pudina_Aloo_Sabzi_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ajwain Puri Recipe - Puri Flavoured With Carom Seeds', 'ajwain-puri-recipe-puri-flavoured-with-carom-seeds', 'Ajwain Puri Recipe is a very simple Indian bread which is made from wheat flour and flavoured with a pinch of turmeric and some toasted Ajwain seeds.', '["250 grams Whole Wheat Flour", "1 teaspoon Ajwain (Carom seeds)", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Oil"]'::jsonb, ARRAY['salt', 'wheat flour', 'ajwain (carom seeds)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making Ajwain puri Recipe by mixing all the ingredients includinh whole wheat flour, carom seeds, turmeric powder, salt with enough water in a bowl.Add sufficient water and knead in order to get a consistency of a stiff dough.", "At the end add 2 tablespoon of oil to bind.Make equal small balls and roll them on to a board using a rolling pin.The thickness of the dough must not be too thin.Heat the oil in a Kadai with enough oil to fry the puris.After 5 to 10 minutes you can add a tiny bit of the dough into the oil to check if it is done.", "If the dough rises up quickly then it is done.Now gently and carefully slide the puris into the oil.", "Once it comes on top, with your ladel press the puri down so that it helps in puffing up.", "Then later turn the puri and cook on both the side till you get a golden brown colour.Once done, take out on a kitchen towel to absorb the excess oil.", "Serve your delicious puffed up\u00a0Ajwain Puris\u00a0with\u00a0Amritsari Aloo\u00a0or\u00a0Palak Makhana\u00a0and\u00a0Boondi Raita\u00a0to make it a complete meal."]'::jsonb, 55, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/sept-19/Ajwain_Puri_Recipe_Puffed_Indian_Bread-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/781.Ajwain_Puri_Recipe_Puffed_Indian_Bread-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chutney Podi Sadam Recipe - Rice Flavoured With Chutney Podi', 'chutney-podi-sadam-recipe-rice-flavoured-with-chutney-podi', 'Chutney Podi Sadam Recipe, is a South Indian Rice recipe which is a quick mixed rice recipe made with ghee and chutney podi. Make it with your leftover white rice or make fresh rice and try this recipe. Serve it either for South Indian lunch or dinner.', '["1-1/2 cups Cooked rice", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 teaspoon Chana dal (Bengal Gram Dal)", "1/4 cup Raw Peanuts (Moongphali)", "2 sprig Curry leaves , roughly chopped", "2 Green Chillies , slit", "1 teaspoon Turmeric powder (Haldi)", "1 Onion , finely chopped", "Salt , to taste", "2 tablespoon Ghee", "1 tablespoon Lemon juice", "5 tablespoons Idli Dosa Podi (Milagai Powder)", "Coriander (Dhania) Leaves , a small bunch finely chopped"]'::jsonb, ARRAY['green chillies', 'salt', 'coriander (dhania)', 'rice', 'mustard seeds', 'ghee', 'curry leaves', 'white urad dal (split)', 'onion', 'lemon', 'peanuts (moongphali)', 'idli dosa podi (milagai powder)', 'turmeric powder', 'chana dal (bengal gram dal)']::text[], '["To begin making the Chutney Podi Rice Pot Recipe, make sure you have cooked rice a few hours earlier or the previous day as the grains will be separated out well.", "You can also make the\u00a0Idli Dosa Milagai Podi Recipe - South Indian Chilli Chutney Powder\u00a0and keep it ready.", "Heat ghee in a kadai, add the mustard seeds, the urad dal, chana dal and peanuts.Allow the mustard seeds to crackle; the dal and peanuts to get roasted well until it gets a golden brown color.Do this on low to medium heat else they will get brown faster than you want them to and the peanuts will remain raw.Once the dal is golden brown and roasted, add the curry leaves, slit green chillies, turmeric powder and stir for a few seconds.Now add the fine chopped onions.", "Once the onions have turned transparent, add in the\u00a0Idli Dosa Milagai Podi Recipe - South Indian Chilli Chutney Powder \u00a0Add the cooked rice, sprinkle some salt and give it a good stir until all the ingredients have combined well and the rice gets well coated.Turn the heat to low, sprinkle some water and cover the pan and allow the rice to steam along with the seasoning for a couple of minutes.Turn off the heat.", "After a couple of minutes, squeeze the lemon juice and give the rice a good stir.", "Check the salt and spice levels and adjust to suit your taste.Garnish with chopped coriander leaves and it is ready to be served.Serve this\u00a0Chutney Podi Sadam Recipe, with\u00a0Nellikai Pachadi Recipe (Amla/ Gooseberry Raita)\u00a0and\u00a0Ambode Recipe (Karnataka Style Masala Vada)\u00a0for a weekday meal."]'::jsonb, 30, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sneha-archanaskitchen.com/Chutney_Podi_Sadam_Recipe__1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/782.Chutney_Podi_Sadam_Recipe__1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chana Methi Dal Recipe - Fenugreek & Split Bengal Gram Curry', 'chana-methi-dal-recipe-fenugreek-split-bengal-gram-curry', 'Chana Methi Dal is a delicious lentil curry made with split Bengal Gram lentil and fresh fenugreek leaves. This recipe is a healthy menu choice for the intake of everyday protein and is also packed with vitamins and minerals. Chana Methi Dal is a fantastic way to sneak in greens in your kids diet as well. Serve Chana Methi Dal along with Phulka and Raita for a wholesome weekday lunch.', '["1 cup Chana dal (Bengal Gram Dal)", "1 cup Methi Leaves (Fenugreek Leaves) , a bunch, cleaned chopped", "1/4 teaspoon Asafoetida (hing)", "1 Onion , thinly sliced", "1 Tomato , chopped", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "Salt , to taste", "1 tablespoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies"]'::jsonb, ARRAY['tomato', 'salt', 'asafoetida (hing)', 'ghee', 'red chilli powder', 'dry red chillies', 'onion', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'chana dal (bengal gram dal)', 'methi leaves (fenugreek leaves) bunch']::text[], '["To prepare the Chana Methi Dal, first wash and soak the chana dal in 3 cups of water for at least 30 minutes.", "While the dal is soaked clean, wash and pat dry the fenugreek leaves.Next, finely chop the methi leaves.", "Heat a teaspoon of oil in a wok or a kadai and add the chopped methi\u00a0leaves into the wok.", "Saute the methi leaves, until it gets softened.", "Methi leaves cooks very quickly and this will take less than 3 minutes to cook.", "Once the leaves have softened, turn off the heat.", "Keep it aside.In the next step, we will cook the Chana dal with the spices.", "Heat a teaspoon of oil in a pressure cooker over medium heat.", "Add asafoetida and saute for few seconds.", "Next add onion and saute till they turn soft.Once the onions have softened, add the chopped tomato along with coriander powder, turmeric powder, red chili powder and saute for a minute or so over medium heat.Add soaked chana dal along with the soaked water to the onion tomato mixture.", "Close the lid of the pressure cooker and put the weight on.", "Cook chana dal for 5 to 8 whistles and turn off the heat.", "Allow the pressure to release naturally\u00a0from the pressure cooker.Once the pressure has released, open the cooker and lightly mash the dal with the back of a spoon.", "Stir in the saut\u00e9ed methi leaves.", "Transfer the\u00a0Chana Methi Dal to a serving bowl.Heat ghee in a tadka pan over medium heat; add the cumin seeds and the red chillies.", "Allow the chillies to roast for a few seconds and pour the tadka for the\u00a0Chana Methi Dal and serve hot.Serve Chana Methi Dal along with Raita for a wholesome weekday lunch."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Methi_Chana_Dal_Recipe-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/783.Methi_Chana_Dal_Recipe-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pan Fried Brussel Sprouts Recipe', 'pan-fried-brussel-sprouts-recipe', 'Brussels Sprouts resemble mini cabbages and are an excellent source of Vitamin C and K. Brussels Sprouts contain the highest amount of glucosinolate, which helps in fighting cancer. It also has the highest amount of omega-3 fatty acids, good for lowering high cholesterol and aiding in weight loss. Pan Fried Brussels Sprouts Recipe is a quick stir fry using brussel sprouts. The garlic adds a nice flavour to the dish.', '["300 grams Brussel sprouts", "3 cloves Garlic , finely chopped", "1/2 teaspoon Black pepper powder", "1/2 teaspoon Mixed Herbs (Dried)", "1/2 teaspoon Garlic Salt", "2 teaspoon Extra Virgin Olive Oil"]'::jsonb, ARRAY['garlic salt', 'mixed herbs (dried)', 'cloves garlic', 'brussel sprouts', 'virgin olive oil', 'black pepper powder']::text[], '["To begin making Pan Fried Brussels Sprouts Recipe, clean the brussels sprouts and cut them into halves and keep aside.Heat olive oil in a skillet, add the finely chopped garlic cloves and saute until the oil becomes fragrant.Add in the brussels sprouts and let it char on one side, this will take around 5 minutes.Now, flip over and let the other side char the similar way.Add in the pepper powder, mixed herbs, season with garlic salt and mix well.Saute for another 5 minutes on medium heat and switch off the flame.Serve the Pan Fried Brussels Sprouts Recipe for a light dinner along with a hearty\u00a0Tomato Noodle soup."]'::jsonb, 20, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Pan_Fried_Brussels_Sprouts_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/784.Pan_Fried_Brussels_Sprouts_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mulyachi Bhaji Recipe - Goan Style Mooli Ki Sabzi', 'mulyachi-bhaji-recipe-goan-style-mooli-ki-sabzi', 'Mulyachi Bhaji is a dry sabzi prepared using mooli, popular in Maharashtra and Goa served for lunch or dinner.', '["2 Mooli/ Mullangi (Radish) , including greens", "1/4 cup Yellow Moong Dal (Split)", "1/2 cup Water", "2 Green Chillies , split vertically", "1/2 cup Fresh coconut , grated", "15 grams Jaggery , adjustable", "Salt , to taste"]'::jsonb, ARRAY['mooli mullangi (radish) including greens', 'yellow moong dal (split)', 'salt', 'coconut', 'jaggery', 'water', 'green chillies split verticy']::text[], '["To begin making the Mulyachi Bhaji recipe, wash and chop radish and radish greens finely and keep aside.", "Wash and soak the moong dal for half and hour.", "Heat a saucepan and add radish, required salt and the washed moong dal.", "Add required water, cover and cook on medium heat till dal and vegetable becomes soft.Once dal and vegetables becomes soft, add green chilies along with coconut and jaggery.Mix\u00a0Mulyachi Bhaji\u00a0 cover and simmer on low heat for about 10 minutes.", "Remove from heat , transfer Mulyachi Bhaji into a serving bowl and serve it for lunch.Serve\u00a0Mulyachi Bhaji along with\u00a0Khandeshi Dal,\u00a0Phulka\u00a0and\u00a0Palak Raita\u00a0for a weekday meal."]'::jsonb, 40, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/Mulyachi_Bhaji_Goan_Style_Radish_Vegetable_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/785.Mulyachi_Bhaji_Goan_Style_Radish_Vegetable_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gulab Phirni Recipe - Rose Flavoured Rice Pudding Shots', 'gulab-phirni-recipe-rose-flavoured-rice-pudding-shots', 'Gulab Phirni Recipe is a freshing rice pudding packed with flavours from gulab jal and saffron and sweetened along with dates. It''s easy to make, looks beautiful when served in small shot glasses, ensuring you are having the right portions and will light up your festive meals instantly. Make and serve Gulab Phirni at your next house party and wow your guests.', '["1/4 cup Rice", "2 tablespoons Milk", "700 ml Milk", "Few Saffron strands", "2 tablespoons Rose water", "Mixed nuts , pistachio and almonds for garnishing", "1 cup Dates", "1/2 cup Milk , hot"]'::jsonb, ARRAY['rice', 's milk', 'milk', 'few saffron strands', 's rose water', 'mixed nuts', 'dates']::text[], '["To begin making the Gulab Phirni Recipe, soak the rice in water for half an hour.Chop the dates and soak the dates in about 1/2 cup of hot milk for about 30 minutesDrain water and pulse along with 2 tablespoons of milk in a mixer grinder till you get a grainy consistency.", "The grains should feel coarse between your fingers.Bring the milk to a brisk boil in a large saucepan, add the rice and saffron while whisking continuously.", "Turn the heat to low and keep stirring to avoid lumps.Keep stirring the mixture every couple of minutes.After about 20 minutes the mixture will start to thicken.", "Simmer the phirni mixture for another 20 to 25 minutes till it thickens considerably and the rice is completely cooked.Stir Occasionally to avoid the Phirni from sticking to the bottom of the pan and forming lumps.Once done and the Gulab Phirni is creamy, add the chopped and soaked dates and simmer for another 3 to 4 minutes.", "Finally add the gulab jal and stir it in.Turn off the heat and allow the Phirni\u00a0mixture cool.", "Spoon the\u00a0Gulab Phirni into small shot glasses.", "Garnish with chopped pistachios or sliced almonds.Cool the Gulab Phirni in the refrigerator for at least 3 hours or overnight and serve chilled.Serve Gulab Phirni Recipe along with\u00a0Samosas\u00a0and\u00a0Mawa Gujiya With Badam and Pista Recipe\u00a0to guests during festive occasions."]'::jsonb, 65, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Morphy_Richards_Gulab_Phirni_Video_recipe_8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/786.Morphy_Richards_Gulab_Phirni_Video_recipe_8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy & Masaledar Aloo Gobi & Beans Tawa Sabzi Recipe', 'spicy-masaledar-aloo-gobi-beans-tawa-sabzi-recipe', 'Spicy & Masaledar Aloo Gobi & Beans Tawa Sabzi Recipe uses a blend of Indian spices and is tossed in a tawa to give it a roasted flavor. It is a semi dry dish that is cooked with lots of onions, ginger and garlic which adds to the extra flavors of the dish.', '["2 Potatoes (Aloo) , peeled and diced", "1 Cauliflower (gobi) , cut into florets", "1 cup Green beans (French Beans) , cut into 1 inch pieces", "2 Tomatoes , finely chopped", "1 inch Ginger , chopped", "4 cloves Garlic , chopped", "1 Green Chilli , slit", "1 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "2 teaspoons Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Garam masala powder", "1 teaspoon Amchur (Dry Mango Powder)", "Salt , to taste", "Oil", "3 sprig Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['tomato', 'salt', 'green beans (french beans)', 'ginger', 'cumin powder (jeera)', 'green chilli', 'amchur (dry mango powder)', 'cauliflower (gobi)', 'red chilli powder', 'cloves garlic', 'coriander (dhania) leaves', 'coriander powder', 'potato (aloo)', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Spicy & Masaledar Aloo Gobi & Beans Tawa Sabzi Recipe, heat a kadai with oil over medium heat.Add ginger and garlic, allow it to soften.", "Once done add chopped onions and cook till they turn translucent.Add chopped tomatoes and sprinkle with little salt and cook until the tomatoes become mushy and soft.", "Once the tomatoes soften, add all the spice powders and saute well.", "Stir in the potatoes, cauliflower and green beans along with salt to taste.", "Sprinkle 1/4 cup of water and cook until the vegetables are cooked through.", "Check for salt and add if required.Cook until the Aloo Gobi & Beans Tawa Sabzi \u00a0becomes semi dry.", "Once done, turn off the heat and\u00a0stir in the chopped coriander leaves and mix well.Serve the\u00a0Masaledar Aloo Gobi & Beans Tawa Sabzi along with\u00a0Tawa paratha,\u00a0Punjabi Kadhi Pakora\u00a0and\u00a0Curd rice\u00a0to make it a complete meal."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Aloo_Gobi_And_Beans_Tawa_Sabzi-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/787.Aloo_Gobi_And_Beans_Tawa_Sabzi-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chamadumpa Sabzi Recipe - Andhra Style Dry Baked Masala Arbi', 'chamadumpa-sabzi-recipe-andhra-style-dry-baked-masala-arbi', 'A delicious dry style Arbi made Andhra style, this Chamadumpa Sabzi is made a bit healthier as in this recipe we have baked the Arbi', '["250 grams Colocasia root (Arbi)", "1/2 cup Water", "Salt , to taste", "2 teaspoons Red Chilli powder", "2 teaspoons Coriander Powder (Dhania)", "2 tablespoons Oil", "1/2 cup Roasted Gram Dal (Pottukadalai)", "2 teaspoons Cumin powder (Jeera)", "3 Garlic", "Salt , to taste"]'::jsonb, ARRAY['s colocasia root', 'arbi', 'water', 'salt', 's red chilli powder', 's coriander powder', 'dhania', 's oil', 'roasted gram dal', 'pottukadalai', 's cumin powder', 'jeera', 'arlic']::text[], '["To begin making the\u00a0Chamadumpa Sabzi Recipe - Andhra Style Dry Baked Masala Arbi,\u00a0we will first boil the Arbi/Chamadumpa.In a pressure cooker, add arbi along with water and salt.", "Pressure cook for 4 whistles.", "Turn off the flame.Allow the pressure to release naturally.", "Drain the water and set the arbi aside.", "Peel the skin off the\u00a0Arbi/Chamadumpa and cut them into thick slices.", "Set aside.", "In a mixing bowl, combine coriander powder and red chilli powder, arbi pieces and toss well until the masala is well coated Let it rest for 15 to 30 minutes.Preheat the oven to 180 degree celsius.In a mixie jar, combine the roasted chana dal, cumin seeds and garlic and grind into a masala.", "Our freshly ground masala is ready.", "Next, roll each piece of arbi, in the prepared freshly ground and place it on baking tray greased with oil.", "Arrange the pieces leaving some space between them.", "Brush the\u00a0Arbi/Chamadumpa pieces with little oil and bake for 20 to 30 minutes.", "Keep turning the pieces every 8-10 minutes.Once it appears cooked and the arbi sizzles.", "Remove from the oven and serve.Serve hot with steamed rice and rasam for a weekend meal.", "You can also serve it as a tea time snackServe this\u00a0Chamadumpa Sabzi,\u00a0along with\u00a0Dosakaya Pappu Recipe\u00a0and\u00a0Steamed Rice\u00a0and\u00a0Menthi Aaku Badeela Koora Recipe\u00a0for a complete Andhra style meal."]'::jsonb, 35, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/anu.mallajosyula-gmail.com/Baked_ArbiChamadumpa_Fry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/788.Baked_ArbiChamadumpa_Fry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ilish Macher Korma Recipe - Hilsa Fish Curry In Rich Gravy', 'ilish-macher-korma-recipe-hilsa-fish-curry-in-rich-gravy', 'Ilish Macher Korma Recipe is one of the authentic and traditional recipes of Bengal, especially during the days of Durga Puja. Bengalis have a culture of celebrating festivals intertwined with delicious food, like most part of India does. Delightful fish recipes are just a part of the menu. Here is a Ilish Macher Korma Recipe which is cooked in a gravy of onion, garlic, ginger and more.', '["300 grams Hilsa Fish , fillets", "4 tablespoons Onion , ground to paste", "1 teaspoon Ginger , grated", "1/2 teaspoon Garlic , minced", "3 Green Chillies , slit", "3 tablespoons Cashew nuts , ground to paste", "2 tablespoons Sultana Raisins", "1/2 cup Hung Curd (Greek Yogurt)", "1 inch Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta)", "4 Cardamom (Elaichi) Pods/Seeds", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "1 tablespoon Sugar", "Salt , to taste", "1-1/2 teaspoons Red Chilli powder", "1 tablespoon Ghee", "Mustard oil , to cook"]'::jsonb, ARRAY['hilsa fish fillets', 'salt', 'ginger', 'hung curd (greek yogurt)', 'mustard oil', 'bay leaf (tej patta)', 'cardamom (elaichi) podsseeds', 'ghee', 'raisins', 'red chilli powder', 'cashew nuts ground paste', 'sugar', 'onion', 'garlic', 'cinnamon stick (dalchini)', 'turmeric powder', 'green chillies', 'garam masala powder']::text[], '["To begin making Ilish Macher Korma Recipe, wash the Ilish fish and rub some turmeric powder and salt to the fish pieces and leave for 15 minutes to marinate.Heat a bit of mustard oil in a wok and lightly fry Ilish mach (hardly 30 - 45 seconds on each side on medium heat) and strain from the oil.Temper the oil with whole cinnamon, bayleaf and \u00a0green cardamom and saute for a few seconds until the spices release a nice aroma.To this, add the ginger garlic paste and fry for a minute.Then add the brown onion paste along with 2 or 3 slit green chillies and cook till the mixture comes together from the sides of the kadai.Add little water in the case you see that the mixture getting any dry.Now add the curd and mix thoroughly and cook in medium flame till the recipe come together well.Add salt and sugar to the mixture and mix.Add cashewnuts paste and whole raisin and cook till the nutty aroma goes off completely from the mixture.At this point, add milk along with 1-1/2 cup of water and bring it to boil \u00a0.Add fried Ilish mach \u00a0and cook for 8 - 10 minutes or till the gravy thickness considerably and looks done.Add ghee and Garam masala powder and mix it well.", "Serve\u00a0Ilish Macher Korma Recipe along with\u00a0Jeera Rice (Pulao) Recipe (Cumin & Ghee Flavored Rice),\u00a0Bengali Potol Bhaja Recipe (Bengali Style Parwal Sabzi),\u00a0Phulka\u00a0and end your meal with\u00a0Rasgulla Recipe\u00a0for a traditional meal."]'::jsonb, 30, 'Bengali', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Uma/Ilish_Korma_recipe_edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/789.Ilish_Korma_recipe_edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bhindi Masala Recipe - Bhindi Tamatar Ki Sabzi', 'bhindi-masala-recipe-bhindi-tamatar-ki-sabzi', 'The Bhindi Masala Recipe is a simple and quick recipe that you can make in a jiffy for a weeknight dinner. All you need is Bhindi (Okra/lady''s finger), tomatoes and onions and a few basic spices.', '["400 grams Bhindi (Lady Finger/Okra)", "1 Onion , thinly sliced", "2 Tomatoes , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "Salt , to taste"]'::jsonb, ARRAY['s bhindi', 'lady finger/okra', 'onion', 'tomatoes', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'red chilli powder', 'salt']::text[], '["To begin making the Bhindi Masala\u00a0Recipe, first cut the bhindi tops and tails and slice them into 1 inch pieces.Heat 3 tablespoons of oil in a heavy bottomed pan on a medium heat.Add in the chopped onions and saut\u00e9 until tender.", "Once tender, add in the bhindi and salt to taste.Cover the pan with its lid slightly ajar and cook in its steam until the bhindi is tender.", "Do make sure to keep stirring it occasionally.", "This process takes a good 10 minutes.Once tender, add in the tomatoes.", "Cook the bhindi masala along with the tomatoes with the lid slightly ajar.As the tomatoes will release its liquids and this will cause the bhindi to turn mushy; hence we keep its lid open so the excess moisture evaporates.Once you notice the tomatoes have also turned soft; add in the turmeric powder, red chilli powder, coriander powder and if required more salt to taste.Stir well until all the ingredients are well combined and saut\u00e9 for another 3 to 4 minutes with its lid open.", "Turn off the heat and transfer the Bhindi Tamatar Ki Sabzi to a serving dish.Serve the\u00a0Bhindi Masala Recipe along with\u00a0Phulka\u00a0and\u00a0Lauki Chana Dal\u00a0for a weekday meal.", "You can also pack it in your Lunch Box along with\u00a0Tawa Paratha."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Bhindi__Masala_Recipe_Bhindi_Tamatar_Sabzi_North_Indian_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/790.Bhindi__Masala_Recipe_Bhindi_Tamatar_Sabzi_North_Indian_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bhindi Masala Recipe - Bhindi Tamatar Ki Sabzi', 'bhindi-masala-recipe-bhindi-tamatar-ki-sabzi-2', 'The Bhindi Masala Recipe is a simple and quick recipe that you can make in a jiffy for a weeknight dinner. All you need is Bhindi (Okra/lady''s finger), tomatoes and onions and a few basic spices.', '["400 grams Bhindi (Lady Finger/Okra)", "1 Onion , thinly sliced", "2 Tomatoes , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "Salt , to taste"]'::jsonb, ARRAY['s bhindi', 'lady finger/okra', 'onion', 'tomatoes', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'red chilli powder', 'salt']::text[], '["To begin making the Bhindi Masala\u00a0Recipe, first cut the bhindi tops and tails and slice them into 1 inch pieces.Heat 3 tablespoons of oil in a heavy bottomed pan on a medium heat.Add in the chopped onions and saut\u00e9 until tender.", "Once tender, add in the bhindi and salt to taste.Cover the pan with its lid slightly ajar and cook in its steam until the bhindi is tender.", "Do make sure to keep stirring it occasionally.", "This process takes a good 10 minutes.Once tender, add in the tomatoes.", "Cook the bhindi masala along with the tomatoes with the lid slightly ajar.As the tomatoes will release its liquids and this will cause the bhindi to turn mushy; hence we keep its lid open so the excess moisture evaporates.Once you notice the tomatoes have also turned soft; add in the turmeric powder, red chilli powder, coriander powder and if required more salt to taste.Stir well until all the ingredients are well combined and saut\u00e9 for another 3 to 4 minutes with its lid open.", "Turn off the heat and transfer the Bhindi Tamatar Ki Sabzi to a serving dish.Serve the\u00a0Bhindi Masala Recipe along with\u00a0Phulka\u00a0and\u00a0Lauki Chana Dal\u00a0for a weekday meal.", "You can also pack it in your Lunch Box along with\u00a0Tawa Paratha."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Bhindi__Masala_Recipe_Bhindi_Tamatar_Sabzi_North_Indian_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/791.Bhindi__Masala_Recipe_Bhindi_Tamatar_Sabzi_North_Indian_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aar Macher Jhol Recipe - Bengali Style Fish In Tomato Gravy', 'aar-macher-jhol-recipe-bengali-style-fish-in-tomato-gravy', 'Aar Macher Jhol Recipe is a Bengali Fish curry prepared with Aar/ Katla/ Rohu fish. Aar fish also known as the Giant River Catfish is a delicious fish that is commonly found in freshwater and brackish water.', '["600 grams Aar Maach (fish) , rohu/ katla fish (cut into thick steaks)", "1 Tomato , finely chopped", "2 Bay leaves (tej patta)", "1-1/2 tablespoons Ginger , paste", "4 Green Chillies , coarsely crushed", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Turmeric powder (Haldi)", "2 Green Chillies , slit lengthwise", "Mustard oil , as required", "1-1/4 cups Water , add 2 cups if you like a loose gravy", "Sugar , a pinch (optional)", "1 tablespoon Coriander (Dhania) Leaves , optional"]'::jsonb, ARRAY['s aar maach', 'fish', 'tomato', 'bay leaves', 'tej patta', 's ginger', 'reen chillies', 'cumin powder', 'jeera', 'coriander powder', 'dhania', 'salt', 'cumin seeds', 'turmeric powder', 'haldi', 'mustard oil', 's water', 'sugar', 'coriander']::text[], '["To begin making the Aar Macher Jhol Recipe, firstly marinate the fish with salt and turmeric powder.Heat oil in a wok and shallow fry the fish on both sides till they turn crispy and golden.", "Remove and keep aside.Into the same wok, add bay leaves and cumin seeds.", "Fry these for 1 minute and add the chopped tomatoes.Saut\u00e9 well.", "Into this Bengali Style Fish Gravy, add turmeric powder, cumin powder, coriander powder and enough salt and saut\u00e9 till tomatoes soften.", "Add the ginger paste and coarsely crushed green chilies.", "Saut\u00e9 till raw smell goes away and oil floats.Now add the water and allow the Fish gravy to come to a boil.", "Once the gravy starts boiling, add the fried fish and cook covered till fish has cooked through. [This should take about 6 to 8 minutes approximately]Once the fish has cooked through, add the slit green chilies, adjust salt if necessary and add sugar to taste.", "Allow it to cook for 5 minutes.Garnish this Bengali Fish Curry with coriander leaves and serve hot.", "Serve piping hot\u00a0Aar Macher Jhol \u2013 Fish In Spicy Tomato Gravy\u00a0along with\u00a0Steamed Rice\u00a0and\u00a0Begun Bhaja\u00a0for a weekday lunch or dinner.", "Enjoy!."]'::jsonb, 20, 'Bengali', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/donna_george/Aar_Macher_Jhol__Bengali_Style_Fish_In_Spicy_Tomato_Gravy_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/792.Aar_Macher_Jhol__Bengali_Style_Fish_In_Spicy_Tomato_Gravy_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Badusha Recipe | Balushahi Recipe - Sweet Indian Doughnut', 'badusha-recipe-balushahi-recipe-sweet-indian-doughnut', 'Badusha or Balushahi is a recipe for a crunchy sweetened Indian doughnut-like dessert. A favorite during Diwali among other special occasions, this is a labor of love. My mother never failed to make this recipe and I have kept up with her tradition and make in my home for Diwali every year too. After years of experimenting, I have arrived at the perfect method for making this sweet and hope you enjoy making it as well.', '["1 cup All Purpose Flour (Maida)", "1/4 teaspoon Baking soda", "1/4 teaspoon Salt", "1/4 cup Ghee", "1/4 cup Curd (Dahi / Yogurt) , chilled", "Oil , for deep frying", "Ingredients for Garnish", "1/4 cup Pistachios , roughly chopped", "Ingredients for sugar syrup", "1 cup Sugar", "1/4 cup Water", "1 teaspoon Cardamom Powder (Elaichi)"]'::jsonb, ARRAY['salt', 'ghee', 'pistachios', 'water', 'baking soda', 'curd', 'sugar', 'cardamom powder (elaichi)', 'flour (maida)', 'sunflower oil']::text[], '["To begin making the Balushahi (Badusha) recipe, we have to follow a two stage cooking process.", "First is to make the fried dough and second the sugar syrup.", "To make the dough In a large bowl add in the flour, the salt and a 1/4 teaspoon of soda.", "Stir to combine the dry ingredients.", "Next add in the ghee to the flour mixture.", "Using your fingers combine the flour and ghee to make coarse crumbs.", "Its takes a good one minute to get this texture.", "Once you get the coarse crumbs texture, add in the yogurt. knead just enough until all the ingredients come together.Cover the dough with a wet muslin cloth and allow it to rest for about 30 minutesAfter 30 minutes of resting the dough we will divide the dough into equal portions of large lemon size, making a dent in the center with the thumb.", "Take care not to press too much while shaping them as this can cause cracks in them.Cover the dough portions with a wet cloth and allow them to rest for another 15 minutes.Next, preheat the oil for deep frying.", "Start adding a few balls at a time into the oil and fry them on medium heat.", "The medium heat helps the balushahi to cook evenly from the inside.Once you notice that the dough balls come floating up to the surface flip over and fry until the bottom half is darker golden brown.", "Remember it is important to fry them on medium heat and not high heat so it gets evenly cooked from the inside.Once both sides are browned well, drain and continue the same with the remaining dough portions and keep them aside.Now let''s get the ingredients needed for the sugar syrup.", "In a sauce pan add in 1/4 cup of water, 1 cup of sugar and a teaspoon of cardamom powder.", "With heat on medium, stir the mixture well until the sugar dissolves and the mixture comes to a boil.Once the mixture comes to a boil, add in the cardamom powder, turn the heat to low and allow the mixture to simmer until you get a single thread consistency.You will know that it has reached the single thread when you touch the sugar syrup between your fingers, you will find it sticky.", "And when the syrup drips from the spoon it will look a longer drop.We will now dip each of the fried doughs one at a time in the sugar syrup until it gets coated all around and arrange then on a platter.", "Continue the same with the remaining fried dough.Garnish the Balushahi (Badusha) with pistachios and allow them to rest until the sugar hardens.", "Make these delicious flaky Balushahi for Diwali and share it with friends and family who come visiting you.Serve these Balushahi as a perfect Sweet for any festive occasion."]'::jsonb, 70, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/GRB_Ghee_Badusha_recipe_video_Balushahi_1-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/793.GRB_Ghee_Badusha_recipe_video_Balushahi_1-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tofu Fried Rice Recipe', 'tofu-fried-rice-recipe', 'Tofu Fried Rice is a delicious Indo Chinese preparation of rice with vegetables and tofu. This one pot meal is easy to make and turns delicious. Tofu looks like paneer, but it is made from soya bean curd and is healthier than paneer. It is added to most of the Indo Chinese dishes.', '["1 cup Basmati rice", "200 grams Tofu , cubed", "1 Bay leaf (tej patta)", "1 teaspoon Cinnamon Powder (Dalchini)", "2 Onions , finely chopped", "4 Spring Onion (Bulb & Greens) , finely chopped", "4 tablespoon Spring Onion Greens , finely chopped", "1/2 Red Yellow or Green Bell Pepper (Capsicum) , julienned", "1 Carrot (Gajjar) , peeled and julienned", "8 Button mushrooms , chopped", "5 cloves Garlic , finely chopped", "1 tablespoon Ginger Garlic Paste", "1 tablespoon Green Chilli Sauce", "1 teaspoon Soy sauce", "Oil , as required", "Salt , to taste"]'::jsonb, ARRAY['basmati rice', 'spring onion greens', 'salt', 'sunflower oil', 'bay leaf (tej patta)', 'button mushrooms', 'cloves garlic', 'carrot', 'spring onion (bulb greens)', 'ginger garlic paste', 'green chilli sauce', 'soy sauce', 'onion', 'red yellow green bell pepper (capsicum)', 'tofu', 'cinnamon powder (dalchini)']::text[], '["To begin making the Tofu Fried Rice, wash the rice and keep aside for 15 minutes.Par boil the rice by adding the bay leaf and 1/4 teaspoon salt to it.", "Drain and spread it on a colander.", "Sprinkle cinnamon powder on it and let it dry.Meanwhile in a kadai/wok, add the required oil and shallow fry the tofu cubes till they turn brownish from both the sides.", "Remove and keep it aside.In the same kadai, add oil if needed.", "When oil gets heated add chopped garlic and saute for a few seconds.", "Then add chopped spring onion and onion and saute till onion become soft.Once done add ginger garlic paste and mix well.", "Next add capsicum, carrot and mushroom.", "Saute till the vegetables and mushrooms get cooked.Once the vegetables are cooked add the green chilli sauce and soy sauce and mix well to combine.", "Add salt to taste, remember that salt had already been added to rice too while cooking.Add the fried tofu cubes and gently mix everything well.", "Finally add the rice, toss and stir it for 2 to 3 minutes.After 2 to 3 minutes, garnish with chopped spring onion greens and turn off the heat.Transfer the\u00a0Tofu Fried Rice into a serving bowl and serve hot.Serve\u00a0Tofu Fried Rice\u00a0for a weekend dinner along with\u00a0Indo Chinese Mixed Vegetable Recipe In Szechuan sauce\u00a0and\u00a0Chinese Darsaan Recipe With Ice Cream."]'::jsonb, 80, 'Chinese', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Tofu_Fried_Rice.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/794.Tofu_Fried_Rice.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('नुव्वुला पचड़ी रेसिपी - Nuvvula Pachadi Recipe', 'nuvvula-pachadi-recipe', 'नुव्वुला पचड़ी रेसिपी एक स्वादिष्ट चटनी है जिसमे सफ़ेद तिल का प्रयोग किया जाता है. इसे बनाने में बहुत कम समय लगता है और आप इसे अपने डोसा, इडली, वड़ा या उत्तपम के साथ परोस सकते है.', '["1 \u0915\u092a \u0924\u093f\u0932 (\u0938\u095e\u0947\u0926)", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930 , adjust according to your preference", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u093e\u0928\u0940", "1-1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0926\u0939\u0940", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0928\u093f\u092e\u094d\u092c\u0942 \u0915\u093e \u0930\u0938", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0930\u093e\u0907", "\u0939\u0940\u0902\u0917 , \u091a\u0941\u091f\u0915\u0940 \u092d\u0930"]'::jsonb, ARRAY['कप तिल', 'सफ़ेद', 'छोटा चमच्च लाल मिर्च पाउडर', 'छोटा चमच्च इमली का पानी', 'छोटा चमच्च दही', 'छोटा चमच्च निम्बू का रस', 'नमक', 'तेल', 'छोटा चमच्च राइ', 'हींग']::text[], '["\u0928\u0941\u0935\u094d\u0935\u0941\u0932\u093e \u092a\u091a\u095c\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0915\u095d\u093e\u0908 \u0915\u094b \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0924\u093f\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0939\u0932\u094d\u0915\u093e \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u0907\u0938\u0938\u0947 \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947\u0964 \u0907\u0938\u092e\u0947\u0902 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u093e\u0928\u0940, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092a\u0940\u0938 \u0932\u0947. \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0928\u093f\u0915\u093e\u0932 \u0932\u0947.\u0907\u0938\u092e\u0947\u0902 \u0926\u0939\u0940 \u0914\u0930 \u0928\u093f\u092e\u094d\u092c\u0942 \u0915\u093e \u0930\u0938 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939\u00a0\u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f, \u090f\u0915 \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0925\u094b\u095c\u093e \u0938\u093e \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u0939\u0940\u0902\u0917 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947.\u00a0\u092e\u093f\u0932\u093e \u0932\u0947 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0928\u0941\u0935\u094d\u0935\u0941\u0932\u093e \u092a\u091a\u095c\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u0938\u0941\u092c\u0939 \u0915\u0947 \u0928\u093e\u0936\u094d\u0924\u0947 \u0915\u0947 \u0932\u093f\u090f \u0918\u0940 \u0930\u094b\u0938\u094d\u091f \u0921\u094b\u0938\u093e \u092f\u093e \u0935\u095c\u093e \u0915\u0947 \u0938\u093e\u0925 \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 15, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/18-april/Nuvvula_Pachadi_Recipe_Sesame_Seeds_Chutney-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/795.Nuvvula_Pachadi_Recipe_Sesame_Seeds_Chutney-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Kandagadda Vepudu Recipe - Yam Stir Fry Recipe', 'andhra-style-kandagadda-vepudu-recipe-yam-stir-fry-recipe', 'Andhra Style Kandagadda Vepudu Recipe (Yam Stir Fry Recipe) is a typical Andhra style of cooking a dish. The word “Vepadu” literally translates to stir fry in Andhra. So therefore any ingredient that has been tossed and fried with Indian masala can be called as vepadu in Andhra cuisine.', '["250 grams Elephant yam (Suran/Senai/Ratalu) , cut into small florets", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 sprig Curry leaves", "1 Green Chilli , chopped", "1 inch Ginger , chopped", "4 cloves Garlic , chopped", "1 teaspoon Turmeric powder (Haldi)", "2 tablespoon Red Chilli powder", "1 teaspoon Black pepper powder", "Salt , to taste"]'::jsonb, ARRAY['salt', 'elephant yam (suransenairatalu)', 'ginger', 'green chilli', 'mustard seeds', 'red chilli powder', 'cloves garlic', 'curry leaves', 'black pepper powder', 'turmeric powder']::text[], '["To begin making the Andhra Style Kandagadda Vepudu Recipe, firstly we will\u00a0pressure cook the chopped yam.", "Add the Yam in a pressure cooker with 1 cup water and salt.", "Close the lid and cook till the cooker releases 2 whistles.Switch off the heat and allow it to rest so that it releases the pressure by itself.Heat a kadai with oil.", "Once the oil is hot, add mustard seeds and allow it to splutter for few seconds.", "Add the curry leaves and crackle them for 10 more seconds.Add the ginger and garlic, chopped green chilli and cooked yam.", "Add the spice powders also (red chilli powder, turmeric powder, pepper powder and salt) and mix everything well.Mix until the masalas are evenly coated and saute until the dish becomes dry (This will take about 2 to 3 minutes).", "Check for salt and serve.", "Serve the\u00a0Andhra Style Kandagadda Vepudu\u00a0along with\u00a0Steamed Rice,\u00a0Palak Tovve or Palak Dal Recipe\u00a0and\u00a0Palya\u00a0for an everyday Lunch or Dinner."]'::jsonb, 40, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Andhra_Style_Kandagadda_Vepadu_Recipe_Yam_Stir_Fry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/796.Andhra_Style_Kandagadda_Vepadu_Recipe_Yam_Stir_Fry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Radish Leaves Pachadi Recipe', 'radish-leaves-pachadi-recipe', 'Radish Leaves Pachadi Recipe is a healthy South Indian side dish recipe which is diabetic friendly too. Radish greens are a source of wholesome health and a low-calorie food. Serve Radish Leaves Pachadi Recipe as a side dish with dosa, steamed rice, or chapati.', '["2 Cups Mooli Ke Patte (Radish Greens) , chopped", "1 Tomato , chopped", "10 Dry Red Chillies , (adjust)", "2 Green Chillies , split", "Salt , to taste", "1 teaspoon Turmeric powder (Haldi)", "2 Tablespoon Oil", "1 Tablespoon Mustard seeds (Rai/ Kadugu)", "1 Tablespoon White Urad Dal (Split)", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Asafoetida (hing)", "5 Curry leaves", "3 cloves Garlic", "2 inch Tamarind"]'::jsonb, ARRAY['tomato', 'salt', 'mustard seeds', 'asafoetida (hing)', 'green chillies split', 'mooli ke patte (radish greens)', 'cloves garlic', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'methi seeds (fenugreek seeds)', 'tamarind', 'turmeric powder', 'sunflower oil']::text[], '["To prepare Radish Leaves Pachadi Recipe, prep up with all the ingredients required.Heat oil in a pan, add half of mustard seeds, urad dal,\u00a0and fenugreek seeds.", "When they start spluttering, add hing.Add in green chillies, red chillies,\u00a0and fry for a few seconds.Add chopped tomatoes and radish greens, garlic and cook them till the raw smell goes off, or the tomatoes turn mushy.", "Allow to cool.Meanwhile again heat the pan and prepare tadka.Meanwhile, again heat another pan and prepare tadka by heating a little oil and adding remaining mustard seeds, black gram, fenugreek seeds, one red chilli and curry leaves.When they start spluttering, switch off the flame and keep it aside.", "By now the above radish leaves and tomato mixture might have cooled.", "Add them to a blender jar, add salt, turmeric powder, and tamarind.", "Grind it to make a coarse chutney, add water if necessary.Pour tadka to the chutney and give it a quick stir just before serving, since the crunch of urad dal is great when the tadka is freshly added.Serve healthy\u00a0Radish Leaves Pachadi Recipe as a side dish with dosa, or chapati."]'::jsonb, 35, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sailajaangara-gmail.com/radish-leaves-pachadi-recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/797.radish-leaves-pachadi-recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Style Paneer Masala Recipe', 'kashmiri-style-paneer-masala-recipe', 'Kashmiri Style Paneer Masala Recipe is a made with toasted paneer cubes soaked in tomato and yogurt gravy flavored with whole some spice. Kashmir Cuisine uses a lot of whole spices in their gravy and prefer to have a rich gravy texture.The gravy is usually had along with Kashmir Style Mudor Pulao which makes it a perfect lunch meal.', '["350 grams Paneer (Homemade Cottage Cheese) , diced in cubes", "1 pinch Asafoetida (hing)", "2 inch Cinnamon Stick (Dalchini)", "2 Bay leaves (tej patta)", "6 Cardamom (Elaichi) Pods/Seeds", "1/2 teaspoon Ajwain (Carom seeds)", "3 teaspoon Homemade tomato puree", "1/2 teaspoon Kashmiri Red Chilli Powder", "1/2 teaspoon Dry ginger powder", "1/4 cup Curd (Dahi / Yogurt)", "1 teaspoon Fennel seeds (Saunf) , powdered", "1 pinch Saffron strands", "1 pinch Garam masala powder", "Salt , to taste", "2 sprig Coriander (Dhania) Leaves , to garnish"]'::jsonb, ARRAY['tomato', 'salt', 'kashmiri red chilli powder', 'bay leaves (tej patta)', 'cardamom (elaichi) podsseeds', 'paneer', 'asafoetida (hing)', 'ajwain (carom seeds)', 'fennel seeds (saunf)', 'saffron strands', 'curd', 'dry ginger powder', 'coriander (dhania) leaves', 'cinnamon stick (dalchini)', 'garam masala powder']::text[], '["To begin making the Kashmiri Style Paneer Masala, firstly, have a bowl ready with 500 ml warm water.In a\u00a0Frying pan, heat a little oil and shallow fry the paneer cubes in batches, till they are golden brown.", "Use only medium flame such that paneer won\u2019t break/splutterDrain the fried paneer on a kitchen towel and add the fried paneer to the bowl of warm water.", "Let it soak, while we make the curry.", "The paneer will retain moisture and stay soft this way.to make the curry add a little oil to a heavy bottomed pan, and add hing.", "Let it sizzle for a few seconds.Add cinnamon stick, bay leaf and green cardamom.Fry the spices for a minute, as they begin to splutter and release their aroma in the oil.", "Care not to over fry them.", "Add shahi jeera and fry till it splutters.On a low heat, add tomato puree and stir to ensure that it does not stick to the bottom.", "Add red chilli powder, ginger powder and fennel powder.Stir and fry for a couple of minutes so that it blends well.Add required water (you can add the warm water in which the paneer are soaked) and continue to cook on a medium heat.Bring it to boil and simmer for 5-7 minutes without lid, till a thick consistency is achieved.Crush the saffron into the gravy and whisk in the yogurt.", "Simmer for few more minutes.", "When the gravy is done and cooked, add paneer cubes.", "Stir, making sure that the paneer does not break.Garnish Kashmiri Style Paneer Masala with coriander and a pinch of garam masala and switch off the flame.", "Serve Kashmiri Style Paneer Masala Recipe along with\u00a0Kashmiri Modur Pulao with pomegranate\u00a0to enjoy your Sunday Meal."]'::jsonb, 35, 'Kashmiri', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Kashmiri_Style_Paneer_Masala_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/798.Kashmiri_Style_Paneer_Masala_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Suran Kofta Curry Recipe - Yam Kofta Curry', 'suran-kofta-curry-recipe-yam-kofta-curry', 'This delicious Suran Kofta Curry Recipe, is a sattvic recipe as the kofta curry is made without the use of onion and garlic and cooked in a delicious and mildly spiced tomato curry. The koftas are cooked in a paniyaram pan using less oil, yet they are made crisp on the outside and soft inside.', '["2 cups Elephant yam (Suran/Senai/Ratalu) , washed, peeled and diced", "\u00bc cup Gram flour (besan)", "1 Green Chilli , finely chopped", "Salt , as per your taste", "1 inch Ginger , finely chopped", "3 Tomatoes , finely chopped", "1 inch Ginger , finely chopped", "1 Green Chilli , finely chopped", "\u00bc cup Mint Leaves (Pudina) , washed", "Salt , to taste", "1 teaspoon Garam masala powder", "2 teaspoons Cumin powder (Jeera)", "1 pinch Sugar"]'::jsonb, ARRAY['tomato', 'salt', 'elephant yam (suransenairatalu)', 'ginger', 'cumin powder (jeera)', 'green chilli', 'gram flour (besan)', 'sugar', 'mint leaves (pudina)', 'garam masala powder']::text[], '["To begin making the Suran Kofta Curry Recipe, prepare all the ingredients for the kofta and keep them aside.We will begin with making the curry for the Suran kofta."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sneha-archanaskitchen.com/Yam_Kofta_Suran_Kofta_Curry_Recipe__1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/799.Yam_Kofta_Suran_Kofta_Curry_Recipe__1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kanchipuram Idlis Recipe', 'kanchipuram-idlis-recipe', 'Kanchipuram Idlis Recipe is a variety of idly from Tamil Nadu - an Indian state known for its variety of breakfast options including Idli, sambar and chutney, dosa, vadas and so many more. Some particular South Indian towns have their own variations of idlis, and this one is from the town of Kanchipuram. You could call it the signature idli of the area. Prepared with assorted spices, these idlis are a mouthwatering treat and a lovely deviation from the regular idli. Traditionally, they are steamed in mandhari leaves but I have seen my mom make them in steel bowls and glasses, which always made a fun idli eating experience for us, as kids. Kanchipuram idlis can be made in regular idli plates too and can be served with Sambar, Kathirikai Gothsu, Chutney Podi, or Coconut Chutney.', '["1 cup Idli Rice", "1/2 cup Black Urad Dal (Whole)", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "Salt , to taste", "1 tablespoon Ghee", "2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Whole Black Peppercorns", "1 sprig Curry leaves", "1 inch Ginger , finely chopped", "1/4 teaspoon Asafoetida (hing)"]'::jsonb, ARRAY['salt', 'ginger', 'ghee', 'asafoetida (hing)', 'idli rice', 'black peppercorns', 'curry leaves', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'black urad dal']::text[], '["To make the Kanchipuram Idlis, first soak the rice, urad dal and fenugreek seeds in water for about 5 hours, or overnight.Rinse the soaked grains once or twice and grind into a slightly thick coarse batter with very little water.", "Add salt, mix well and place it in a steel vessel with enough space for it to rise as it ferments.Let it rest overnight.Place a pan on the heat and warm some oil/ghee.", "Add cumin seeds, pepper corns, curry leaves, finely chopped ginger, and saut\u00e9 for a minute.", "Add asafetida and mix again.", "Turn off heatAdd this prepared tempering to the fermented batter and mix well.Grease idli plates with oil, pour the batter into them and place them in a steamer.Add enough water into the steamer, shut the lid and allow it to steam it for 10 to 12 minutes until the Idli is cooked.If a spoon inserted inside the idli should come out clean, and the idli should be soft and fluffy.Remove the idli from steamer and cool it for 3 minutes.", "With the help of butter knife scrape out the idli from the moulds and serve hot\u00a0with\u00a0Sambar,\u00a0Kathirikai Gothsu,\u00a0Chutney Podi\u00a0or\u00a0Coconut Chutney."]'::jsonb, 75, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Kanchipuram_Idlis.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/800.Kanchipuram_Idlis.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false);

INSERT INTO public.recipes (
  title, slug, description, ingredients, cleaned_ingredients,
  instructions, total_time_mins, cuisine, diet, source_url,
  image_url, image_status, image_source, data_source, servings, review_count, is_featured
) VALUES
  ('Methi Lachha Paratha Recipe', 'methi-lachha-paratha-recipe', 'Methi Lachha Paratha Recipe is one of the Basic staple food from the North part of India. It comes under the category of thepla, but in this recipes, we have added a twist by folding it and rolling it so that it becomes flakier.', '["2 cups Whole Wheat Flour", "1 cup Methi Leaves (Fenugreek Leaves)", "2 Green Chillies , finely chopped", "2 cloves Garlic , finely chopped", "Salt , to taste", "Extra Virgin Olive Oil , as needed"]'::jsonb, ARRAY['salt', 'wheat flour', 'methi leaves (fenugreek leaves)', 'figaro pure olive oil', 'cloves garlic', 'green chillies']::text[], '["To begin making the Methi Lachha Paratha wash the methi leaves thoroughly and chop them finely.In a mixing bowl, add the all the ingredients like the chopped methi leaves, whole wheat flour, green chillies, garlic, salt\u00a0 and knead it into a soft dough.", "Rest it for 10 minutes.After 10 minutes, knead for a minute again until the paratha dough is soft and pliable.", "Divide the dough into 10 equal portions.", "Preheat a skillet over medium heat.", "If you are using a cast iron skillet, then grease the skillet well and allow it to preheat.Keep some flour aside for dusting while rolling the dough.", "Shape each dough portion into a round ball, press it between the palm of your hands.Dust the dough with flour and roll it into a 6-inch diameter circle.", "Smear some ghee or oil on this rolled out the dough.", "Dust some flour over the ghee.", "This flour and ghee will help the Methi lachha paratha split itself into layers.Begin folding the Methi lachha paratha dough like an accordion, similar to a saree pleat.", "Start from one end of the dough and reach the end.", "The dough is essentially made into a pleat.", "Once you have stacked up all the pleats one over the other, roll the dough into a swiss roll.Flatten the pleated swiss roll between the palm of your hands, dust in flour and roll into a 4 to 5-inch diameter circle.", "You will be able to see the layers very clearly.Place the rolled layered Methi Lachha Paratha on the preheated skillet.", "Cook on medium heat on both sides for a few seconds, then smear ghee and cook until golden brown and cooked through completely.Proceed the same way with the remaining portions of the paratha dough.Serve the Methi Lachha Paratha along with Mango Achar,\u00a0Paneer Butter Masala\u00a0or your favorite\u00a0Vegetarian Gravy\u00a0for a weeknight dinner or even for\u00a0breakfast\u00a0along with a chutney."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Methi_Lachha_Paratha_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/801.Methi_Lachha_Paratha_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ilish Pulao Recipe - Bengali Style Hilsa Fish Pilaf', 'ilish-pulao-recipe-bengali-style-hilsa-fish-pilaf', 'Ilish Pulao Recipe (Bengali Style Hilsa Fish Pilaf) is an extremely fragrant and delicious Bengali style Fish Pilaf cooked with Ilish mach or Hilsa. This flavoursome Bangladeshi delicacy is one of the traditional dishes of Bangladesh.', '["6 Hilsa Fish , (pieces)", "1/2 cup Onion , finely chopped", "2 Onions , ground to paste", "2 tablespoon Ginger Garlic Paste", "1 tablespoon Red Chilli powder", "4 tablespoon Green Chillies , (adjust)", "1/4 cup Mishti doi , whisked well", "1 cup Coconut milk", "3 tablespoons Ghee", "Salt , to taste", "2 cups Rice , Basmati or Gobindobhog, soaked for 20 minutes", "1 cup Coconut milk", "1 Green Chilli", "1 tablespoon Ghee", "Salt , to taste", "3 cups Lukewarm Water", "1 Bay leaf (tej patta)", "2 inch Cinnamon Stick (Dalchini)", "5 Cardamom (Elaichi) Pods/Seeds , crushed", "5 Cloves (Laung) , pounded"]'::jsonb, ARRAY['salt', 'green chilli', 'ghee', 'bay leaf (tej patta)', 'cardamom (elaichi) podsseeds', 'red chilli powder', 'water', 'ginger garlic paste', 'mishti doi', 'onion', 'cinnamon stick (dalchini)', 'cloves (laung)', 'coconut milk', 'green chillies', 'rice basmati gobindobhog', 'hilsa fish']::text[], '["To begin making the Ilish Pulao Recipe (Bengali Style Hilsa Fish Pilaf), firstly soak rice for 20 minutes.", "Meanwhile you can cook the hilsa fish.Heat 3 tablespoons ghee in deep bottomed kadai and fry chopped onions until onion turns translucent and pale golden in colour.Add in ginger, and garlic paste with red chilli powder and fry until the mixture comes together.", "Sprinkle water in between only if required.", "This is known as koshano in Bengali or bhuna in hindi.Once the masala is ready, add whisked mishti doi, salt and stir well to mix with the masala.Pour half of the coconut milk and stir quickly to incorporate everything.Add raw fish pieces into the gravy very carefully in a single layer without overlapping the fish, such that the fish is cooked evenly.Add green chili and cook for 4-5 minutes, depending on fish size.Flip ilish pieces gently as hilsa is extremely delicate and fragile.Add rest of the coconut milk and cook for 10 minutes with cover or until fish is cooked thoroughly.Once done keep the fish covered until needed.", "Otherwise the gravy will be dried out.Now prepare the rice pulao.", "Heat 1 tablespoon ghee in a cast iron biryani pot and add whole garam masala to the hot oil.Now add half of the gravy from hilsa along with luke warm water.", "Bring the mixture to a boil.Add previously soaked rice into the mixture and let it cook for 10-12 minutes or until rice is almost half cooked.Add coconut milk, salt and cook covered for another 10 minutes or till the rice is completely cooked.Now arrange the ilish pieces on bed of rice and pour the gravy on it.", "Add green chillies.", "Cover and cook for 5-7 minutes on simmer.Once done, remove from flame but keep the Ilish Pulao covered.", "Only remove the lid once ready to serve.Serve\u00a0Ilish Pulao Recipe (Bengali Style Hilsa Fish Pilaf),\u00a0Tadka Raita Recipe (Spiced Curd With Onions)\u00a0for lunch and end your meal with\u00a0Bengali Sita Bhog Recipe."]'::jsonb, 50, 'Bengali', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/rimli.dey-gmail.com/Ilish_Pulao_or_Hilsa_Pilaf_recipe_edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/802.Ilish_Pulao_or_Hilsa_Pilaf_recipe_edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Stuffed Palak Paneer Paratha', 'stuffed-palak-paneer-paratha', 'Stuffed Palak Paneer Paratha is a protein packed dish made using spinach/palak and paneer as main ingredients. The added flavors of spices just enrich the parathas even more. We have used freshly made paneer, tossed it in kasuri methi leaves and some spices giving it that delicate taste and flavour to these palak paneer parathas.', '["2 cups Whole Wheat Flour", "Water , as needed", "Salt , a pinch", "1 teaspoon Oil", "Ingredients for the filling", "1 cup Paneer (Homemade Cottage Cheese) , grated/crumbled", "2 cups Spinach Leaves (Palak) , finely chopped", "2 tablespoons Kasuri Methi (Dried Fenugreek Leaves) , crushed", "2 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Cumin powder (Jeera)", "Salt , to taste", "Nutralite Classic Spread , to cook parathas"]'::jsonb, ARRAY['salt', 'wheat flour', 'cumin powder (jeera)', 'amchur (dry mango powder)', 'paneer', 'red chilli powder', 'water', 'kasuri methi (dried fenugreek leaves)', 'nutralite classic parathas', 'turmeric powder', 'spinach leaves (palak)', 'sunflower oil']::text[], '["To begin making the Palak Paneer Paratha Recipe, knead a soft yet pliable dough using the ingredients listed in dough making and set aside for 20 minutes.Meanwhile, mix all the above ingredients mentioned in palak paneer filling section well.", "Give it a taste and adjust the salt and chilli accordingly.Next, divide the dough into equal portions and keep aside.", "Make the same portions of the palak paneer stuffing mixture and keep them aside.Roll out the paratha dough into a 3 inch diameter disc, place the palak paneer stuffing mixture in the centre and bring the edges of the paratha together and pinch to seal it.Dust the palak paneer paratha on dry flour and roll to make a large circle, ensuring that the filling does not come out.", "Stuff and roll the remaining portions of the paratha dough and palak paneer stuffing mixture the similar way.Once done, it''s time to cook them.", "Preheat a tawa on medium heat, melt the Nutralite spread and place these stuffed palak paneer parathas on the pan.", "Cook these palak paneer parathas on both sides until browned and crisp.Serve Stuffed Palak Paneer Paratha along with\u00a0Boondi Raita\u00a0and\u00a0Aam Ka Achaar\u00a0for breakfast or for dinner."]'::jsonb, 80, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/jan-10/Palak_and_Paneer_Stuffed_Paratha_Recipe-1022.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/803.Palak_and_Paneer_Stuffed_Paratha_Recipe-1022.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Muringakka Manga Mulakushyam - Mango & Drumstick Kootu Curry', 'muringakka-manga-mulakushyam-mango-drumstick-kootu-curry', 'Muringakka Manga Mulakushyam is a traditional Kerala recipe made up of Mangoes and drumstick cooked in toor dal and coconut paste. It is also called Moloshyam in Malayalam and Kootu in Tamil Nadu.', '["1 Drumstick , chopped to about 1.5 inch", "1 Mango (Raw) , peeled & chopped to bite-size", "1 Green Chilli", "1 cup Water", "Salt , to taste", "Ingredients For Parippu", "1/2 cup Arhar dal (Split Toor Dal) , soaked for 30 minutes", "1/4 teaspoon Turmeric powder (Haldi)", "2 cups Water", "Ingredients For Coconut Paste", "1/4 cup Fresh coconut , grated", "1 teaspoon Cumin seeds (Jeera)", "2 Green Chillies", "2-1/2 tablespoons Water", "Ingredients To Temper", "1-1/2 teaspoons Coconut Oil", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon White Urad Dal (Split)", "2 Dry Red Chillies", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'arhar dal (split toor dal)', 'green chilli', 'coconut', 'mustard seeds', 'water', 'drumstick', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'cumin seeds (jeera)', 'coconut oil', 'turmeric powder', 'mango bitesize', 'green chillies']::text[], '["To begin making the\u00a0Muringakka Manga Mulakushyam get all the ingredients ready, so it will be easy to get started.In a pressure cooker, add toor dal, drumstick, mango & 2 cups of water, salt & turmeric powder.", "Pressure cook dal for 3 to 4 whistles or till soft and mushy.", "Let the pressure release completely.In a mixer, add coconut, green chilies, jeera, water, and grind them into fine paste.Add the coconut to the dal, mango & drumstick mixture.", "Combine all the ingredients well.Simmer the flame and cook the Muringakka Manga Mulakushyam for about 3 to 4 minutes.", "Adjust the consistency of the\u00a0Mulakushyam, by adding a little water.", "Check the salt and adjust to suit your taste.In a tadka pan, add a little coconut oil.", "Once the oil is hot, add mustard seeds.", "As soon as oil splutters, add urad dhal, red chilies, and curry leaves.Pour the tadka over the curry and serve steaming Muringakka Manga Mulakushyam.Serve the\u00a0Muringakka Manga Mulakushyam along with\u00a0Dondakaya / Kovakkai Poriyal\u00a0and\u00a0Jowar Roti\u00a0for lunch."]'::jsonb, 45, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Mango_Mulakushyam.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/804.Mango_Mulakushyam.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Smoked Dhaba Dal Recipe', 'smoked-dhaba-dal-recipe', 'The Smoked Dhaba Dal Recipe is a classic recipe of lentils that are spiced together and given a smoked flavor. I absolutely love dal at the dhabas on the highways up north of India. The Dhaba dal when smoked from the burning coal, brings out delicious flavors and works magic on my palette. Through this recipe, I''ve tried to achieve similar flavor. Hope you all like it. Dals (Lentils) are a staple part of the Indian diet. From fritters to soups to desserts, I use lentils every single day!', '["1/2 cup Arhar dal (Split Toor Dal)", "1/2 cup Green Moong Dal (Whole)", "1 Onion , finely chopped", "2 Tomato , finely chopped", "2 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "1 Green Chilli , finely chopped", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Black Salt (Kala Namak)", "Salt , to taste", "Oil , as required", "Ingredients of Seasoning", "1 tablespoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies , broken", "2 cloves Garlic , slivered", "4 sprig Coriander (Dhania) Leaves , finely chopped", "1 Charcoal"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'arhar dal (split toor dal)', 'ginger', 'green chilli', 'black salt', 'ghee', 'charcoal', 'red chilli powder', 'cloves garlic', 'coriander (dhania) leaves', 'dry red chillies', 'onion', 'cumin seeds (jeera)', 'coriander powder', 'green moong dal', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Smoked Dhaba Dal Recipe; we will use the pressure cooker method to make the dal in one pot along with all the spices.Soak the tuvar dal and green moong dal for about an hour in water.", "Once you are through with the soaking time, get all the ingredients ready.Heat a teaspoon of oil in the pressure cooker; add the onions, ginger, garlic and green chillies and saute for a few minutes until the onions are lightly tender and softened.", "Add the tomatoes, and the remaining spices and saute until you smell the aromas coming through.Add the soaked dals, salt and add 3 cups of water.", "Cover the pressure cooker, place the weight on and cook until you hear 2 to 3 whistles.", "After two to three whistles, turn the heat to low and simmer the Dhaba Dal for about 5 to 8 minutes.", "Once done, turn off the heat and allow the pressure to release naturally.The dal continues to cook under the pressure, hence we allow it to rest until the pressure releases.Once the pressure releases; open the cooker and you will notice the dal cooked and mushy.", "That is how we want the Dhaba Dal to appear.", "Stir in the chopped coriander leaves and check the salt and spice levels.", "Adjust to suit your taste.", "Adjust the consistency of the dal, by adding water.Now the final step is to add the smoked flavor and to prepare the seasoning.To smoke the dal heat charcoal until red hot over the gas burner (direct flame).", "Once the coal is red hot, place it in a heatproof bowl.Place this bowl on top of the cooked lentils.", "Drizzle a teaspoon of ghee over the hot coal.", "The coal will begin to smoke almost instantly.", "At this stage, cover the dal pan and allow the smoke to circulate inside.", "This process of smoking a dal,\u00a0is called Dhungar or Coal Smoking Technique.After about a minute, open the dal pan and you will see the smoke effect has withered.", "Transfer the Smoked Dhaba Dal to a serving bowl.For the seasoning; heat a teaspoon of ghee in a small pan; add the cumin seeds, the slivered garlic, and red chillies.", "Allow the cumin to crackle for a few seconds and turn off the heat.", "Pour this seasoning over the Smoked Dhaba Dal.Serve\u00a0Smoked Dhaba Dal Recipe along with\u00a0Garlic Naan\u00a0and\u00a0Palak Raita\u00a0for a weekday meal."]'::jsonb, 50, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shyma_Menon/Smoked_Dhaba_Dal_Recipe_Green_moong_and_toor_dal-4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/805.Smoked_Dhaba_Dal_Recipe_Green_moong_and_toor_dal-4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Podi Potta Pachhai Kathirikai | Brinjal Stir Fry Recipe With Curry Powder', 'podi-potta-pachhai-kathirikai-brinjal-stir-fry-recipe-with-curry-powder', 'Podi Potta Pachhai Kathirikai is Brinjal Stir Fry Recipe With Curry Powder. This recipe is made with green brinjal. The long green brinjals are slit lengthwise and shallow fried with spice powders. Fresh ''curry podi'' is then sprinkled over it, before tossing the veggies so that they are evenly coated with the masala all over. It''s a traditional recipe that I learnt from my grandmother.', '["1 cup Coriander (Dhania) Seeds", "1 cup Chana dal (Bengal Gram Dal)", "1/2 cup White Urad Dal (Split)", "15 Dry Red Chillies", "1/2 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "Others ingredients", "1/2 kg Small Green brinjal (green aubergine)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)", "1 tablespoon Oil", "Tamarind , a small ball", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard seeds', 'asafoetida (hing)', 'white urad dal (split)', 'dry red chillies', 'coriander (dhania) seeds', 'green brinjal (green aubergine)', 'coriander powder', 'tamarind', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To prepare Podi Potta Pachhai Kathirikai | Brinjal Stir Fry Recipe With Curry Powder, prepare curry powder first.", "Meanwhile, soak the tamarind in 2 cups of water and set aside.Heat oil in a thick bottomed pan.", "Add the mustard seeds.Add the remaining ingredients and stir fry on low, until the dals turn golden in colour.Allow to cool completely.Grind into a coarse powder in a mixer and you can store in an airtight jar.For the Podi Potta Pachhai Kathirikai | Brinjal Stir Fry Recipe With Curry Powder,\u00a0Cut the brinjals lengthwise diagonally and then slice into bite sized pieces.Put the cut veggies in the tamarind water to avoid oxidization.Heat oil in a wide thick bottomed pan.", "Add the mustard seeds and hing.Drain the tamarind water and add the sliced brinjals once the mustard seeds splutter.Mix in the turmeric powder, coriander powder and salt.Cover with a lid and cook on a low to medium heat, stirring occasionally, for 10-15 minutes.Open cook for another 5 minutes once the veggies seem almost done.Add 2 tablespoons of the ''curry podi'' prepared.Carefully toss the veggies such that the podi coats their surface evenly.Turn off the heat andServe\u00a0Podi Potta Pachhai Kathirikai | Brinjal Stir Fry Recipe With Curry Powder along with\u00a0phulka\u00a0or steamed rice and\u00a0sambar\u00a0of your choice."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/akila_subramanian/Podi_Potta_Pachhai_Kathirikai___Green_Brinjal_Stir_Fry_with_Curry_Powder.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/806.Podi_Potta_Pachhai_Kathirikai___Green_Brinjal_Stir_Fry_with_Curry_Powder.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Cabbage & Dal Stuffed Paratha Recipe', 'cabbage-dal-stuffed-paratha-recipe', 'Cabbage & Dal Stuffed Paratha is a healthy breakfast option and is packed with nutrition. It is a perfect nutritional combination of cabbage and yellow moong dal. This recipe is also perfect to be served in your kids lunch box.', '["1 cup Whole Wheat Flour", "2 teaspoon Oil", "1/2 cup Water", "1/4 teaspoon Salt", "2 cups Cabbage (Patta Gobi/ Muttaikose) , finely chopped", "1/2 cup Yellow Moong Dal (Split)", "2 Green Chillies , finely chopped", "1/2 Onion , finely chopped", "5 Garlic , finely chopped", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "Ghee , or oil for smearing", "Salt , to taste"]'::jsonb, ARRAY['salt', 'wheat flour', 'yellow moong dal (split)', 'red chilli powder', 'water', 'onion', 'garlic', 'cumin seeds (jeera)', 'ghee', 'oil', 'turmeric powder', 'green chillies', 'cabbage (patta gobi muttaikose)', 'sunflower oil']::text[], '["To begin with Cabbage & Dal Stuffed Paratha firstly boil the dal by adding 3 cups of water.", "Once it is boiled, drain the water and keep the dal aside.", "The dal water can be used to make the dough.Heat 1 tablespoon oil in a kadhai.", "After the oil gets heated, add cumin seeds.When the cumin seeds crackle, add finely chopped onion and fry till onion turns pinkish.Once it is done, add the chopped garlic and green chilies and stir.", "Now add finely chopped cabbage, stir and close the lid of kadai, stirring in between.", "Let the cabbage get cooked for about 10-15 minutes.After the cabbage softens, add the dal and mix well.", "Take care not to add any water as the stuffing should be dry.Add turmeric and red chili powder and stir.", "Add salt according to your taste and mix well.Switch off the gas and let the mixture get cooled down.Mould wheat flour to make a firm dough.", "Add salt and oil to wheat flour and mix.", "Mould it into a soft yet firm dough by adding water little at a time.", "Cover the dough with muslin cloth for 30 minutes.Make small balls from the dough of equal size.", "The size should be a little bigger than the table tennis ball.Roll the dough ball into a little bit of dry wheat flour and roll it into small thick flat round shape.", "Place 2 tablespoon of the stuffing on it and close from all sides.Dust it in dry whole wheat flour and roll it into bigger round shapes, just like a chapati.If you see any air bubbles while rolling, simply pat it gently with your fingertips.Then apply 1 teaspoon ghee on the pan and place the paratha on it.After 2-3 minutes, apply 1 teaspoon ghee on the upper side and turn.", "Fry for another 2-3 minutes and your paratha is ready.Serve Cabbage & Dal Stuffed Paratha hot with Lauki Raita and Dhaniya Pudina Chutney."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Cabbage__Dal_Stuffed_Paratha.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/807.Cabbage__Dal_Stuffed_Paratha.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thengai Paal Sadam Recipe - Coconut Milk Pulao', 'thengai-paal-sadam-recipe-coconut-milk-pulao', 'Thengai Paal Sadam or Coconut Milk Pulao is a deliciously aromatic, mildly spiced one pot rice dish that is easy to prepare in a jiffy.', '["1 cup Golden Harvest Sona Masuri Rice", "1 Onion , thinly sliced", "2 Green Chillies , slit", "5 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "2 Cloves (Laung)", "1 teaspoon Fennel seeds (Saunf) , coarsely pounded", "2 Star anise", "1 Bay leaf (tej patta) , torn", "1 cup Coconut milk", "Mint Leaves (Pudina) , a few sprigs", "Salt , to taste", "Ghee , for cooking", "1 teaspoon Ghee", "2 tablespoons Cashew nuts"]'::jsonb, ARRAY['cashew nuts', 'salt', 'ginger', 'golden harvest sona masuri rice', 'bay leaf (tej patta)', 'fennel seeds (saunf)', 'ghee', 'cloves garlic', 'onion', 'cloves (laung)', 'coconut milk', 'green chillies', 'star anise', 'mint leaves (pudina)']::text[], '["To begin making the Thengai Paal Sadam Recipe, firstly get all the ingredients ready.We will cook the sadam or rice directly in a pressure cooker.", "Heat oil in the pressure cooker over medium heat; add the onions, ginger, garlic and green chillies.", "Saute until the onions soften and lightly turn brown.", "Once the onions soften; add the cloves, fennel seeds, star anise and bay leaf.", "Stir for a few seconds.Add the coconut milk, rice, salt and 1 cup of water.", "Cover the pressure cooker and allow the rice to cook for 2 whistles.", "After two whistles, turn the heat to low and cook for 3 minutes and turn off the heat.Allow the pressure to release naturally.", "The Thengai Paal Sadam will continue to cook inside while there is pressure.", "While the pressure is releasing, heat a pan with ghee over medium heat.", "Add the cashew nuts and roast until it turns golden brown and crisp.Open the cooker and gently stir in the roasted cashew nuts and mint leaves to the sadam.", "Transfer the Thengapal sadam to a bowl and serve hot.Serve\u00a0Thengai Paal Sadam\u00a0for your everyday meals along with\u00a0Navratan Korma,\u00a0Kerala Parotta\u00a0and\u00a0Palak Raita.", "You can also make this dish for a weekday dinner and serve it with your choice of raita."]'::jsonb, 55, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sandhya-archanaskitchen.com/Thengai_Paal_Sadam_Recipe_Coconut_Milk_Pulao.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/808.Thengai_Paal_Sadam_Recipe_Coconut_Milk_Pulao.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Udupi Style Alsande Kayi Saaru Recipe (Long Beans Gravy Recipe)', 'udupi-style-alsande-kayi-saaru-recipe-long-beans-gravy-recipe', 'Udupi Style Alsande Kayi Saaru Recipe (Long Beans Gravy Recipe) is a favorite among the locals in Udupi. It is a gravy that is made out of long beans. It is rich in Vitamin A which is one of the essential requirement for our body as it helps to improve our skin completion. The curry is made by grinding the roasted spices to provide the authentic flavor from the Udupi.', '["1 cup Long String Bean (chavli) , chopped", "1/2 cup Tamarind Water", "Salt , to taste", "Ingredients to Grind", "2 teaspoon Rice", "4 Dry Red Chilli", "2 tablespoon Coriander (Dhania) Seeds", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "To Temper", "4 cloves Garlic , crushed", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Dry Red Chilli"]'::jsonb, ARRAY['salt', 'rice', 'tamarind water', 'mustard seeds', 'string bean (chavli)', 'cloves garlic', 'dry red chilli', 'curry leaves', 'coriander (dhania) seeds', 'methi seeds (fenugreek seeds)']::text[], '["We begin making the Udupi Style Alsande Kayi Saaru Recipe (Long Beans Gravy Recipe) by pressure cooking the long beans in a pressure cooker with 1/2 cup water for about 1 whistle.In the meantime, dry roast the ingredients to be ground.", "Then Powder it finely using a mixer.Now open the cooker once all the pressure is released.", "Add the powdered masala, tamarind and salt to taste.Keep string till it thickens little.", "Then to make the tempering heat a kadai with oil, crackle the mustard seeds, garlic cloves, cumin seeds and curry leaves.Then add the dry red chilli also.", "Once aroma is released pour it over the curry and serve.", "Serve the Udupi Style Alsande Kayi Saaru Recipe (Long Beans Gravy Recipe) can be had along with steamed rice and\u00a0Yellow Pumpkin Dal Recipe\u00a0for a comforting Sunday lunch."]'::jsonb, 40, 'Udupi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Udupi_Style_Alsande_Kayi_Sarru_Recipe_Long_Beans_Gravy_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/809.Udupi_Style_Alsande_Kayi_Sarru_Recipe_Long_Beans_Gravy_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Style Brinjal Bharta Recipe', 'goan-style-brinjal-bharta-recipe', 'Traditionally Goan Brinjal Bharta Recipe is cooked by roasting brinjals on charcoal. But the brinjals also can be grilled on a grill or directly on the gas by keeping a wired mesh. I have roasted it on a wired mesh in this recipe.', '["1 Brinjal (Baingan / Eggplant)", "2 Onions , finely chopped", "2 Green Chillies , chopped", "1/2 cup Coriander (Dhania) Leaves , finely chopped", "1 tablespoon Tamarind Paste", "2 tablespoon Fresh coconut , grated", "1 Tamarind , marble sized ball", "Salt , to taste", "1 tablespoon Oil"]'::jsonb, ARRAY['salt', 'coriander (dhania) leaves', 'brinjal (baingan eggsplant)', 'coconut', 'tamarind marble', 'onion', 'tamarind paste', 'green chillies', 'sunflower oil']::text[], '["To begin making the Goan Style Brinjal Bharta Recipe, clean the brinjal and make 4 to 5 slits keeping the brinjal intact.Heat oil in a heavy bottomed pan.", "Switch off the pan and apply this oil to the brinjal.", "Once done, put the brinjal in the same pan and cover it with a lid.After 2 minutes, open the lid and\u00a0turn the brinjal carefully to the other side.", "Once it is slightly cooked from the other side, carefully insert the marble sized tamarind ball through one slit and again cover the lid.Keep on turning the brinjal till it gets cooked on all sides.", "This might take 25 to 35 minutes.Once cooked, it will turn brown and will release water.", "Let the brinjal remain covered until it cools down.After cooling, peel the brinjal and discard the peel.", "Mash the pulp and mix it with finely chopped onions and green chillies in a bowl.Add grated coconut, tamarind paste, salt to taste and mix everything well.", "Once done, add finely chopped coriander leaves, mix well and it is ready to be served.Serve\u00a0Goan Brinjal Bharta Recipe\u00a0along with\u00a0Steamed Rice,\u00a0Goan Moolyacho Ross\u00a0and\u00a0Amlechi Uddamethi Recipe\u00a0for a comforting and delicious lunch."]'::jsonb, 55, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Goan_Brinjal_Bharta_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/810.Goan_Brinjal_Bharta_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dry Navratan Korma Recipe', 'dry-navratan-korma-recipe', 'Dry Navratan Korma Recipe is a variation of the curry version of the same. Navratan Korma aka Nine- Gem-Curry gets its name after the nine ingredients 9 vegetables, fruits and nuts used in making a creamy, semi-sweet Mughlai Curry.', '["1 Cauliflower (gobi) , cut into florets", "2 Carrots (Gajjar) , diced to bite-size", "5 Green beans (French Beans) , cut to bite-size", "1/2 cup Green peas (Matar)", "1 Green Bell Pepper (Capsicum) , diced to bite-size", "2 Potatoes (Aloo) , diced to bite-size", "2 Onions , chopped", "1 inch Ginger , chopped", "4 cloves Garlic , chopped", "2 Green Chilli , chopped", "2 Tomatoes , pureed", "1-1/5 tablespoons Coriander Powder (Dhania)", "1/2 tablespoon Garam masala powder , (or Kitchen King Masala)", "1 teaspoon Red Chilli powder", "Salt , as needed", "Oil , as required", "2 Bay leaves (tej patta)", "1 Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "1 teaspoon Ajwain (Carom seeds)", "100 grams Paneer (Homemade Cottage Cheese) , cubed", "1 cup Fresh cream", "1/2 cup Cashew nuts , ground to paste", "1/2 cup Pineapple , cut to bite-size chunks", "1/2 cup Anardana Powder (Pomegranate Seed Powder)", "2 tablespoons Sultana Raisins", "Cashew nuts , split, handful", "Coriander (Dhania) Leaves , few for garnishing", "Coriander (Dhania) Leaves , few for garnishing"]'::jsonb, ARRAY['tomato', 'coriander (dhania) leaves', 'anardana powder (pomegranate seed powder)', 'ajwain (carom seeds)', 'cloves garlic', 'onion', 'pineapple bitesize', 'garam masala powder (or kitchen king masala)', 'sunflower oil', 'salt', 'green chilli', 'cardamom (elaichi) podsseeds', 'carrot bitesize', 'raisins', 'cashew nuts ground paste', 'cauliflower (gobi)', 'red chilli powder', 'cashew nuts split', 'ginger', 'bay leaves (tej patta)', 'paneer', 'green peas (matar)', 'green beans (french beans) bitesize', 'potato (aloo) bitesize', 'cinnamon stick (dalchini)', 'green bell pepper (capsicum) bitesize', 'coriander powder']::text[], '["To begin making Dry Navratan Korma Recipe, prepare and keep all the ingredients on the kitchen counter first.Heat a little oil in a shallow frying pan and shallow fry the paneer chunks on all sides till crisp and keep aside on a kitchen towel to drain any excess oil.Add more oil if required, add whole spices mentioned, and as soon as they crackle, add onions and saute till they soften and are translucent.Now add chopped ginger garlic and green chilies and fry till raw smell goes and\u00a0turns brownish in color.Now add tomato puree and saute till the raw smell disappears.Add all the chopped vegetables and peas excluding paneer, nuts, and fruits.Mix well and add coriander powder, red chili powder and kitchen king masala or garam masala and fry till cooked well.Add a little oil if you feel that the curry is too dry.", "Now add cashew paste and fresh cream.Mix well till everything incorporates well with each other.", "You may see the curry getting thicker, so add little water, around 1/2 cup and stir and allow the vegetables to cook on low flame.", "Keep the lid closed.This may take around 7-8 minutes.Once you see the vegetables softening, add raisins and split cashew nuts and mix well.Cook for another few minutes until cashews and raisins are incorporated with flavours.Let all the vegetables be cooked to el dente, and not soggy.Now add the pineapple chunks and half of the pomegranate, mix and turn off the gas flames.Add fried paneer pieces on the top and garnish with freshly chopped coriander, some split cashews, and pomegranate pearls.Serve\u00a0Dry Navratan Korma\u00a0along with\u00a0Dal Banjara Recipe\u00a0and\u00a0Phulkas\u00a0for an everyday meal.", "Goes well with\u00a0Kashmiri Pulao\u00a0or\u00a0Butter Naan, accompanied with some fresh green salad and\u00a0Cucumber and Green Chilli\u00a0Raita."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/shaheen_ali/Dry_Navratan_Korma__Nine_Gem_Dry_Curry_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/811.Dry_Navratan_Korma__Nine_Gem_Dry_Curry_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tirunelveli Mor Kuzhambu Recipe', 'tirunelveli-mor-kuzhambu-recipe', 'Tirunelveli Mor Kuzhambu recipe that has a perfect blend of spices and a curry simmered in yogurt gravy. The addition of red chillies, cumin seeds, methi seeds roasted and ground along with coconut makes this curry absolutely delicious. You can add a variety of vegetables into the mor kuzhambu like carrots, drumstick, chow chow and even green capsicum to make it nutritious and tasty.', '["250 grams Vellai Poosanikai (Ash gourd/White Pumpkin) , peeled and cubed", "1/2 cup Tamarind Water", "2 cups Curd (Dahi / Yogurt)", "Salt , to taste", "2 teaspoons White Urad Dal (Split)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "5 Dry Red Chillies", "1 teaspoon Cumin seeds (Jeera)", "1 cup Fresh coconut , grated", "1 teaspoon Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves"]'::jsonb, ARRAY['s vellai poosanikai', 'ash gourd/white pumpkin', 'tamarind water', 's curd', 'dahi / yogurt', 'salt', 's white urad dal', 'split', 'methi seeds', 'fenugreek seeds', 'dry red chillies', 'cumin seeds', 'jeera', 'fresh coconut', 'coconut oil', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'curry leaves']::text[], '["To begin making Tirunelveli Style Mor Kuzhambu recipe, prep all the ingredients and keep them aside.Fist step is to roast and make the coconut paste.", "Heat a small frying pan over medium heat; add the urad dal, cumin seeds, methi seeds and red chillies.", "Roast them for about a minute until you can see the seeds crackling.", "Ensure you don''t allow them to burn.", "Once roasted, add the coconut and saute for a few seconds and turn off the heat.Add the roasted ingredients into the blender, add 1/2 cup of warm water and blend to make a smooth paste.Keep this aside.Pressure cook the ash gourd along with a little salt, turmeric powder and 2 tablespoons of water.", "Pressure cook for two whistles and turn off the heat.", "Allow the pressure to release naturally.Into a sauce pan, add the yogurt, the tamarind water, cooked ash gourd, the coconut mixture, salt to taste and mix well to combine.", "Give it a brisk boil ONLY when you are ready to eat.To prepare the tadka, heat oil over medium heat in a tadka pan.", "Add the mustard seeds, urad dal and allow it to crackle and the dal to turn golden brown.", "Once golden, stir in the curry leaves and turn off the heat.Pour this seasoning over the Tirunelveli Mor Kuzhambu mixture.", "Once you are ready to have your meal, give this\u00a0Tirunelveli Mor Kuzhambu a brisk boil for about 2 minutes and turn off the heat.Transfer the\u00a0Tirunelveli Mor Kuzhambu to a serving bowl and serve hot.Serve the Tirunelveli Mor Kuzhambu along with\u00a0Steamed Rice,\u00a0Lemon Sevai\u00a0and a\u00a0Urulai Roast\u00a0for a delicious south Indian lunch."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Tirunelveli_Style_Mor_Kuzhambu_Recipe_Recipe_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/812.Tirunelveli_Style_Mor_Kuzhambu_Recipe_Recipe_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Badanekai Yennegai Gojju Recipe (Stuffed Brinjal Recipe)', 'karnataka-style-badanekai-yennegai-gojju-recipe-stuffed-brinjal-recipe', 'Karnataka Style Badanekai Yennegai Gojju Recipe (Stuffed Brinjal Recipe) being the signature dish of “North Karnataka” are stuffed with brinjal also called as eggplant and fried in oil. The dish has a whole lot of rich and ground masala flavor to the gravy itself. At Archana’s Kitchen we have made it by consuming less oil by sauteing well on the pan itself.', '["6 Small Brinjal (Baingan / Eggplant) , quatered", "1 Onion , sliced", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "Oil , Oil for cooking", "Salt , Salt to taste", "2 sprig Coriander (Dhania) Leaves", "1 cup Pearl onions (Sambar Onions)", "1 teaspoon Kala jeera", "3 cloves Ajwain (Carom seeds)", "3 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "4 Dry Red Chillies", "2 teaspoon Sesame seeds (Til seeds)", "2 teaspoon Coriander (Dhania) Seeds", "1 tablespoon Poppy seeds", "1 tablespoon Raw Peanuts (Moongphali)", "2 tablespoon Fresh coconut , grated", "18 grams Tamarind", "1 teaspoon Jaggery , powdered", "18 grams Tamarind"]'::jsonb, ARRAY['salt', 'mustard seeds', 'brinjal (baingan eggsplant) quatered', 'coconut', 'jaggery', 'sunflower oil oil', 'cloves ajwain (carom seeds)', 'pearl onion (sambar onion)', 'coriander (dhania) leaves', 'dry red chillies', 'onion', 'cinnamon stick (dalchini)', 'sesame seeds (til seeds)', 'coriander (dhania) seeds', 'poppy seeds', 'peanuts (moongphali)', 'tamarind', 'cloves (laung)', 'kala jeera']::text[], '["We begin making the Karnataka Style Badanekai Yennegai Gojju Recipe (Stuffed Brinjal Recipe) by dry roasting the ingredients like jeera seeds, coriander seeds, peanuts, dry red chillies, poppy seeds, cloves and cinnamon stick.Add all these roasted ingredients into a grinder along with coconut, pearl onions, tamarind and jaggery into a nice smooth paste.", "You can add little water while grinding but not a lot.Now Stuff the ground masala mixture into the brinjal and keep it aside.", "Keep the leftover masala also to add it into the gravy.Heat a pressure cooker with oil on a medium heat, crackle some mustard seeds and sliced onions and fry them till the onions become translucent.Then add these stuffed brinjals and fry them well till it becomes soft.", "Move them carefully without breaking them.", "You can cover and cook it as well.Once the brinjal is half cooked, add the remaining masala with 1/2 cup water and cook on a medium heat.", "Cook for about 2 whistle.", "Release the pressure naturally and then keep saut\u00e9ing till the masala thickens.", "Some of the oil oozes out from the side.", "Once done sprinkle with some chopped coriander leaves and serve.Serve the Karnataka Style Badanekai Yennegai Gojju Recipe (Stuffed Brinjal Recipe) along with\u00a0Jolada Roti Recipe (Jowar Bhakri)\u00a0and\u00a0Nuggekai Kharbyaali Recipe (North Karnataka Spiced Drumstick Sambar)\u00a0to go along with some steamed rice."]'::jsonb, 55, 'North Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Karnataka_Style_Badnekeyae_Yennagai_Gojju_Recipe_Stuffed_Brinjal_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/813.Karnataka_Style_Badnekeyae_Yennagai_Gojju_Recipe_Stuffed_Brinjal_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pohala Jhola Recipe (Pohala Fish Curry)', 'pohala-jhola-recipe-pohala-fish-curry', '‘Pohala’ fish is a common variety we get in local fish market. Usually small sizes are available through out the year. Few days back when I went to the biggest Fish Market in Bhubaneswar I managed to get some big sizes.This curry is a spicy fish curry which can be enjoyed with hot steam rice. Fish are fried first with a generous amount of Mustard Oil. You can use different cooking oil too.', '["300 grams Pohala fish", "1 teaspoon Turmeric powder (Haldi)", "2 Tomatoes", "2 Onions , red ones", "4 Green Chillies", "8 cloves Garlic", "1 teaspoon Cumin powder (Jeera)", "3 tablespoon Mustard oil", "3 cups Water", "Salt , as required"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'mustard oil', 'cloves garlic', 'onion red', 'water', 'turmeric powder', 'green chillies', 'pohala fish']::text[], '["To begin making the Pohala Jhola recipe, clean fish and give marks on it with knife.", "Add turmeric and salt and keep aside for 5 minutes.Make a paste of garlic, onion, green chili and grind the tomatoes coarsely.Heat oil in a cast iron pan and fry fish on both side until they are done.", "It will take 3 to 5 minute.Take them out, add onion masala paste in the same pan and fry for a minute.Add tomato paste, salt and fry for another 2 minutes until it''s done.", "Add water and let it boil for 2 minutes more.Add cumin powder and mix well.", "Immediately add fried fishes to it and cook for 2 minute at low flame.After 2 minutes, switch off the stove and it is ready to serve.Serve Pohala Jhola with hot steamed rice for a delicious weekday lunch or dinner."]'::jsonb, 50, 'Oriya', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Sai_Priya/Pohala_Jhola.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/814.Pohala_Jhola.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Panjiri Recipe - Healthy Punjabi Dry Fruit Snack', 'panjiri-recipe-healthy-punjabi-dry-fruit-snack', 'Panjiri Recipe is a popular Punjabi sweet that people snack on during winters.', '["1/2 cup Ghee", "1 cup Whole Wheat Flour", "1/4 cup Chiroti Rava", "1/2 cup Sugar , powdered", "2 tablespoons Gond (natural gum)", "1/3 cup Phool Makhana (Lotus Seeds)", "1/4 cup Whole Almonds (Badam)", "1/4 cup Cashew nuts", "1/4 cup Pistachios", "2 tablespoons Dry coconut (kopra) , slices", "1 tablespoon Melon seeds", "2 tablespoons Flax seeds", "1 tablespoon Poppy seeds", "1/2 teaspoon Dry ginger powder", "1/2 teaspoon Nutmeg powder", "1/2 teaspoon Cardamom Powder (Elaichi)"]'::jsonb, ARRAY['cashew nuts', 'wheat flour', 'nutmeg powder', 'ghee', 'pistachios', 'dry coconut (kopra)', 'chiroti rava', 'sugar', 'dry ginger powder', 'badam (almond)', 'phool makhana (lotus seeds)', 'flax seeds', 'poppy seeds', 'cardamom powder (elaichi)', 'gond (natural gum)', 'melon seeds']::text[], '["To begin making the Punjabi Panjiri Recipe, make sure all your ingredients are measured out and arranged neatly on the counter.", "Heat a kadai with a tablespoon of ghee on medium-low flame, and make sure the ghee is well heated.", "To this add the gondh crystals and stir them occasionally, until they puff up well.", "Once they have puffed up, turn off the flame and remove the puffed gondh in a plate and set aside.", "Next add a tablespoon ghee yet again on medium low flame and roast the makhana until well roasted.", "This will take about 2-3 minutes.", "Likewise use a tablespoon of ghee each and roast the almonds, cashew, pistachios, dry coconut slices, melon seeds, flax seeds, and the poppy seeds.Once each of these are roasted individually, and set them aside to cool.", "Combine the puffed gondh, roasted makhana,\u00a0almonds, cashew, pistachios, dry coconut slices, melon seeds, flax seeds, and the poppy seeds in a mixing bowl and transfer to a mixer jar and grind to a coarse mixture.", "Transfer the freshly ground coarse mixture, into a large mixing bowl.", "Heat the remaining ghee in the kadai on medium-low flame, add the rawa and the whole wheat flour and roast until the mixture turns into a light brown colour.", "To this add the dry ginger powder, nutmeg and cardamom powder, mix well and allow it to cool.", "Once cooled add in the sugar powder and adjust the sweetness according to your taste.", "Transfer this sweetened rawa-wheat flour mixture into the mixing bowl that contains the freshly ground dry fruit coarse mixture.", "Mix well until combined and store in an airtight container for 2-3 weeks.", "Serve\u00a0Panjiri Recipe along with a\u00a0Turmeric Milk Recipe - Haldi Doodh / Golden Milk\u00a0or\u00a0Badam Milk Recipe - Almond Milk\u00a0as a snack during the winter season."]'::jsonb, 35, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/panjiri_recipe-5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/815.panjiri_recipe-5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Peas Pulao Recipe -  North Indian Matar Pulao', 'peas-pulao-recipe-north-indian-matar-pulao', 'Peas Pulao Recipe is a lovely rice preparation made with green peas as the star ingredient. Long grain basmati combined with whole spices like bay leaf, cumin seeds, cardamom, cloves and star anise, tempered in ghee and cooked along with fresh green peas.', '["1-1/2 cup Basmati rice", "1 tablespoon Ghee", "1/2 teaspoon Cumin seeds (Jeera)", "1 Bay leaf (tej patta)", "1 Star anise", "2 Cardamom (Elaichi) Pods/Seeds", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "Salt , to taste", "1 Onion , sliced", "1/2 cup Green peas (Matar)"]'::jsonb, ARRAY['basmati rice', 'salt', 'bay leaf (tej patta)', 'ghee', 'cardamom (elaichi) podsseeds', 'green peas (matar)', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'onion', 'cloves (laung)', 'star anise']::text[], '["To begin making the\u00a0Peas Pulao Recipe, wash the rice and soak in water for about 20 minutes.", "Heat a pressure cooker with ghee on medium flame, to this add the whole spices - bay leaf, cumin seeds,\u00a0star anise,\u00a0cardamoms,\u00a0cloves and cinnamon stick.", "Once these spices begin to sizzle, add the sliced onions, and cook them only until they begin to sweat.", "This will take about a minute.", "To this add the salt, green peas and drained rice.", "Top the matar pulao with about 2-1/2 of water, depending on the age and quality of your rice and close the pressure cooker.", "Pressure cook for about 3 whistles and turn off the flame, allow the pressure to release naturally.", "Once done, open the pressure cooker give the Matar pulao a stir and fluff up the rice.Transfer the Matar Pulao to a serving bowl and serve hot.Serve\u00a0Peas Pulao Recipe along with\u00a0Smoked Dhaba Dal Recipe,\u00a0Masala Lachha Paratha Recipe,\u00a0Achari Paneer Masala Recipe\u00a0or\u00a0Easy Creamy Chicken Curry Recipe,\u00a0Pickled Onions\u00a0and finish the meal with a dessert of\u00a0Rose Gulkand Phirni Recipe."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Donna_George/Matar_Pulao_Peas_Pulao_Recipe-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/816.Matar_Pulao_Peas_Pulao_Recipe-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Rice Stuffed Paratha Recipe', 'spicy-rice-stuffed-paratha-recipe', 'Spicy Rice Stuffed Paratha is a perfect recipe, if you have leftover rice in your fridge. We are usually left with rice after our meal and we end up throwing them. From now, don’t throw them instead use them in making stuffed parathas for your filing breakfast.', '["1 cup Whole Wheat Flour", "1/2 cup Cooked rice , (leftover)", "1 Onion , finely chopped", "Coriander (Dhania) Leaves , small bunch, finely chopped", "2 Green Chillies", "1/2 teaspoon Cumin powder (Jeera)", "1 teaspoon Red Chilli powder", "1 teaspoon Chaat Masala Powder", "2 teaspoons Lemon juice", "Salt , to taste", "Oil , or ghee for cooking paratha", "Water , as required"]'::jsonb, ARRAY['rice (leftover)', 'coriander (dhania)', 'wheat flour', 'cumin powder (jeera)', 'salt', 'chaat masala powder', 'red chilli powder', 'water', 'onion', 'lemon', 'sunflower oil ghee paratha', 'green chillies']::text[], '["To begin making the Spicy Rice Stuffed Paratha, we will first make the dough.", "Add in the flour and a pinch of salt into a large bowl.", "Add a little water at a time and knead to make a firm yet smooth dough.Knead well for about 3 to 4 minutes, this will make the parathas soft.Drizzle a teaspoon of oil over the dough and knead for another couple of minutes.", "Cover and keep aside till we make the rice filling for the paratha.Next, we will combine the leftover rice, chopped onions, green chillies, coriander leaves, red chilli powder, chaat masala, cumin powder, lemon juice and salt.", "Stir to combine the ingredients well.Now to begin making the Spicy Rice Stuffed paratha, keep some flour aside for dusting.", "Divide the dough into large lemon side balls.Dust the dough portions in flour, flatten it and roll it into a 3 inch diameter circle.", "Place the rice filling on half side of the circle and close the paratha by folding it with the other half.", "Yes its as simple as that.", "We will have a semi circle oval shape.Press the sides of the paratha down to seal the edges and gently using the rolling pin to flatten it.", "Take care, the filling can ooze out if the dough is rolled out too thin.Now to cook the Spicy Rice Stuffed Paratha, first preheat the skillet on medium heat.", "Place the rolled paratha on top and allow it to cook on one side.", "After about 10 to 15 seconds, flip the paratha.At this stage, smear some oil or ghee to cook the paratha.", "Cook the paratha by flipping over a couple of times until you see golden brown spots on both sides.Proceed the same way with the remaining dough portions and it is ready to be served.", "Serve Spicy Rice Stuffed Paratha with\u00a0Dhaniya Pudina Chutney\u00a0and\u00a0Burani Raita\u00a0for a healthy breakfast."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/rice_stuffed_paranthe_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/817.rice_stuffed_paranthe_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vatanyacha Phadna Recipe - Sugar Snap Peas Stir Fry', 'vatanyacha-phadna-recipe-sugar-snap-peas-stir-fry', 'The Vatanyacha Phadna Recipe is a simple stir fry of the Sugar Snap Peas. Spring brings fresh sugar snap peas into the season and Vatanyacha Phadna is a simple and delicate dish that makes the most of these jade beauties.', '["400 grams Sugar snap peas", "1 tablespoon Fresh coconut , grated", "1 tablespoon Whole Black Peppercorns , crsuhed", "2 teaspoons Sesame seeds (Til seeds)", "Salt , to taste", "1 teaspoon Oil"]'::jsonb, ARRAY['s sugar snap peas', 'fresh coconut', 'whole black peppercorns', 's sesame seeds', 'til seeds', 'salt', 'oil']::text[], '["To begin making the Vatanyacha Phadna Recipe (Sugar Snap Peas Stir Fry), we will cook it in a single pot.", "The snap peas cooked really quickly, so simply stir frying in the pan works well.To begin, heat a teaspoon of oil in a stir fry pan and add the cracked pepper and sesame to the oil.", "Allow it to crackle for a few seconds.Add the sugar snap peas, season with salt, cover the pan and cook till the sugar snap peas are lightly caramelised and cooked.Check the salt and spice levels and adjust to suit your taste.", "Once the peas are cooked, turn off the heat and stir in the coconut.Transfer the\u00a0Peas Stir Fry to a serving dish.Serve\u00a0Vatanyacha Phadna with\u00a0Khandeshi Dal\u00a0and Phulkas for a weeknight dinner."]'::jsonb, 40, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Vatanyacha_Phadna_Recipe_Sugar_Snap_Peas_Stir_Fry-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/818.Vatanyacha_Phadna_Recipe_Sugar_Snap_Peas_Stir_Fry-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rajasthani Kachri Phali Ki Sabzi Recipe -Wild Cucumber And Beans Sabzi', 'rajasthani-kachri-phali-ki-sabzi-recipe-wild-cucumber-and-beans-sabzi', 'Kachri is a wild variety of cucumber that resembles a brown yellow small melon.They come in different shape and size. Kachri Phali Ki Sabzi Recipe (Wild Cucumber And Beans Sabzi) is famous recipe in Rajasthan. It is easy to make and can be made with few ingredients and hence can even be made on weekdays. Serve Kachri Phali Ki Sabzi Recipe (Wild Cucumber And Beans Sabzi) along with Phulka, and Smoked Dal Makhani Dhaba Style for a weekday lunch.', '["1 cup Gawar Phali (Kothavarangai / Cluster beans) , chopped", "9 Kachri (Wild cucumber) , chopped", "1 tablespoon Oil", "1 tablespoon Cumin seeds (Jeera)", "1 teaspoon Asafoetida (hing)", "1 tablespoon Turmeric powder (Haldi)", "1 tablespoon Red Chilli powder", "Salt , to taste", "3/4 tablespoon Coriander Powder (Dhania)", "1 tablespoon Amchur (Dry Mango Powder)"]'::jsonb, ARRAY['gawar phali', 'kothavarangai / cluster beans', 'kachri', 'wild cucumber', 'oil', 'cumin seeds', 'jeera', 'asafoetida', 'hing', 'turmeric powder', 'haldi', 'red chilli powder', 'salt', 'coriander powder', 'dhania', 'amchur', 'dry mango powder']::text[], '["To begin making Rajasthani Kachri Phali Ki Sabzi Recipe (Wild Cucumber And Beans Sabzi), peel and cut wild cucumber, make sure you taste them before adding with other ingredients as sometimes they can be bitter in taste.Take a pressure cooker.", "Add gawar phali and pressure cook them for one whistle and release pressure immedietly.Take a strainer and strain water and keep them aside.Heat oil in a pan or kadai on a medium heat, add cumin and asafoetida once the oil is hot.Let cumin crackle and add turmeric powder, red chilli powder, and coriander powder.", "Mix everything well for few seconds.Add chopped kachri and mix it with masala.", "Let it cook for about 5-7 minutes.Now add boiled gawar phali to cooked kachri.", "Let it cook for about 2 minutes on medium heat.", "Add salt to taste and amchoor powder.Serve\u00a0Kachri Phali Ki Sabzi Recipe (Wild Cucumber And Beans Sabzi) along with\u00a0Phulka, and\u00a0Smoked Dal Makhani Dhaba Style Recipe\u00a0for a weekday lunch."]'::jsonb, 30, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pooja/Kachri_Fali_ki_SubjiWild_cucumber_and_beans_subji_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/819.Kachri_Fali_ki_SubjiWild_cucumber_and_beans_subji_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pudina Moong Dal Recipe (Mint Moong Dal)', 'pudina-moong-dal-recipe-mint-moong-dal', 'Mint has many health benefits as it is good for digestion, detoxifies the body etc. This recipe is simply a moong dal just flavoured with mint leaves. Really an aromatic tasty dal it is and is perfect for your weekday meals.', '["1/2 cup Yellow Moong Dal (Split)", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Cumin seeds (Jeera)", "1 pinch Asafoetida (hing)", "1 tablespoon Ghee", "2 tablespoons Mint Leaves (Pudina) , chopped", "Water , as needed", "Salt , as needed"]'::jsonb, ARRAY['salt', 'yellow moong dal (split)', 'asafoetida (hing)', 'ghee', 'red chilli powder', 'water', 'cumin seeds (jeera)', 'mint leaves (pudina)', 'turmeric powder']::text[], '["To begin making the Pudina Moong Dal recipe, add 1 cup of water, turmeric powder and washed moong dal in a stainless steel vessel and cook till the dal turns soft.", "Alternatively, just pressure cook upto 2 whistles.Once the dal is cooked, add 1 and 1/2 cups of water, salt.", "Bring to a boil and then simmer.", "While the dal is simmering, prepare the tadka.Heat ghee/oil in a tadka pan.", "First fry the cumin seeds and then add asafoetida.Add mint leaves and fry for some seconds.", "Lastly add red chili powder.Immediately, pour this tempering/tadka mixture in the dal & stir well.", "Simmer the dal for 2 to 3 minutes.Serve Pudina Moong Dal along with\u00a0Capsicum Usili\u00a0and\u00a0Phulkas\u00a0for a weekday lunch or dinner."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Sasmita/Pudina_Moong_Dal__Mint_Moong_Dal__Mint_Dal__Pudina_Dal.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/820.Pudina_Moong_Dal__Mint_Moong_Dal__Mint_Dal__Pudina_Dal.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Awadh Style Bakarhani Roti Recipe ( Thick Spiced Flat-Bread Recipe )', 'awadh-style-bakarhani-roti-recipe-thick-spiced-flat-bread-recipe', 'Awadh Style Bakarhani Roti Recipe ( Thick Spiced Flat-Bread Recipe ) is soft flaky  bread which is seasoned with cardamom and also sweet on the palate. It is usually cooked in a tandoor which helps to give a charred and smoky flavour to the bread.', '["2 cups All Purpose Flour (Maida)", "1 cup Sooji (Semolina/ Rava)", "200 ml Milk", "50 ml Fresh cream", "2 teaspoons Active dry yeast", "2 teaspoons Poppy seeds", "1 teaspoon Cardamom Powder (Elaichi)", "2 teaspoons Sugar , 2 teaspoon sugar", "35 grams Cashew nuts , ground to paste", "Oil , to knead", "Ghee , for layering", "Salt , to taste"]'::jsonb, ARRAY['s all purpose flour', 'maida', 'sooji', 'semolina/ rava', 'milk', 'fresh cream', 's active dry yeast', 's poppy seeds', 'cardamom powder', 'elaichi', 's sugar', 's cashew nuts', 'oil', 'ghee', 'salt']::text[], '["We begin making the\u00a0Awadh Style Bakarhani Roti Recipe ( Thick Spiced Flat-Bread Recipe ) preheating the oven at 180-degree celsius for about 10 minutes.", "Mix all the ingredients in a large mixing bowl.", "Knead slowly to make a soft chapati\u00a0dough, you can knead for about 5 minutes in order to get the right consistency.", "Once done roll it into a small ball and cover the dough with a damp cloth and keep it in a warm place for about 2 hours.Once the dough is raised after two hours , divide the dough into small equal balls and roll it on a board about 1 cm thin.", "Apply ghee and sprinkle some dough on top and spread it evenly over the surface.Then\u00a0fold the dough in half and repeat the process of applying ghee and flour on the surface of the dough.", "Once done fold over to form a triangle.", "The again apply some more ghee.Roll the dough to 2 cm thin and then from one of the long sides of the triangle start rolling the dough tightly till you reach the other side.", "Pinch the open edges to secure it neatly.Once it is rolled you will get a conical shaped dough, \u00a0start pressing the dough from the wide part of the cone by placing the thin end of the cone onto your palm resulting in a circular\u00a0shape.When the circular shape is made you can use your hand to press the dough to form the desired thickness , about \u00a01/2 an inch.", "Once it flattened, you can poke holes on one side to make the dough cook quickly.Grease the pan on which you are placing the dough and cook the bread inside the oven for about 2 minutes on each side.", "Make sure you flip the bread after every 2 minutes.You can also cook the bread on a flat nonstick\u00a0tawa\u00a0on each side for about 4 minutes on each side.", "Serve the\u00a0Awadh Style Bakarhani Roti Recipe ( Thick Spiced Flat-Bread Recipe ) with Sultani dal to enjoy a rich Sunday lunch."]'::jsonb, 75, 'Awadhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/oct-26/Bakarkhani_Recipe_Awadh_Flat_Bread_naan_Sweet-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/821.Bakarkhani_Recipe_Awadh_Flat_Bread_naan_Sweet-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Manathakkali Kootu Recipe', 'manathakkali-kootu-recipe', 'The Manathakkali Kootu Recipe is a very classic South Indian recipe that is packed with proteins, vitamins and minerals. Kootu is a combination of dal and vegetable, with or without coconut. Manathakkali Kootu is a simple yet nutritious gravy that helps in controlling and treating acidity related problems.', '["1/2 cup Yellow Moong Dal (Split)", "1 Onion , finely chopped", "1 Tomato , finely chopped", "200 grams Manathakkali Keerai , roughly chopped", "4 cloves Garlic", "1/2 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Red Chilli powder", "Salt , to taste", "Ingredients for Seasoning", "1 teaspoons Sesame (Gingelly) Oil", "1 teaspoon White Urad Dal (Split)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Dry Red Chilli", "1/4 teaspoon Asafoetida (hing)"]'::jsonb, ARRAY['tomato', 'salt', 'yellow moong dal (split)', 'manathakkali keerai', 'mustard seeds', 'asafoetida (hing)', 'red chilli powder', 'cloves garlic', 'sesame (gingelly) oil', 'dry red chilli', 'white urad dal (split)', 'onion', 'turmeric powder']::text[], '["To begin making the\u00a0Manathakkali Kootu Recipe, we will first wash and clean the moong dal.Place the moong dal into the pressure cooker along with the onions, tomatoes, garlic, chilli powder, turmeric powder, salt and about 1 cup of water.", "Cover the pressure cooker, place the weight on and cook until you hear a couple of whistles.After a couple of whistles, turn the heat to low and simmer for 2 minutes and turn off the heat.", "Allow the pressure to release naturally.", "While the pressure is releasing, place the chopped\u00a0Manathakkali Keerai into a steamer.", "Steam until the keerai is cooked through.", "Turn off the heat and take the keerai out of the steamer, so the color remains green.Once the moong dal is cooked through completely, open the cooker and give the dal a quick whisk and take care not to mash the dal to much.", "Kootu is usually a thick gravy along with vegetables where you can feel the texture of the dal.Stir in the steamed\u00a0Manathakkali Keerai.", "Check the salt and spices and adjust to taste.", "The next step is to season the\u00a0Manathakkali Keerai Kootu.", "Heat oil in a tadka pan, add the mustard seeds, urad dal and red chillies.", "Allow them to roast and the dal to brown a little.Stir in the asafoetida powder and turn off the heat.", "Pour this seasoning to the\u00a0Manathakkali Keerai Kootu and serve.Serve the\u00a0Manathakkali Keerai Kootu along with Steamed Rice, Salad for a quick and healthy weeknight dinner or even for a quiet Sunday lunch with family."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Asha_Venugopal_/Manathakkali_Kootu.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/822.Manathakkali_Kootu.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paalkatti Chettinad Curry Recipe -Chettinad Style Paneer Kurma Recipe', 'paalkatti-chettinad-curry-recipe-chettinad-style-paneer-kurma-recipe', 'Paalkatti Chettinad Curry Recipe (Chettinad Style Paneer Kurma Recipe) is a recipe that has been originated from the traditional Chettinad style curry. The authentic Chettinad masala is prepared by roasting a blend of spices and blending it into a smooth paste and then adding it into the sauteed pearl onion and tomato to give it a rich and spicy flavor. The paneer is just simmered into the curry.', '["250 grams Paneer (Homemade Cottage Cheese) , cubed", "1/2 cup Pearl onions (Sambar Onions) , quartered", "1 Tomato , chopped", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 tablespoon Red Chilli powder", "Salt , to taste", "Oil , for cooking", "2 sprig Curry leaves", "2 tablespoon Coriander (Dhania) Seeds", "3 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 Cardamom (Elaichi) Pods/Seeds", "2 teaspoon Whole Black Peppercorns", "3 Kalpasi leaves", "2 Star anise", "6 Dry Red Chilli", "1 teaspoon Poppy seeds", "1/2 cup Fresh coconut , grated", "2 Green Chillies , slit", "1 sprig Curry leaves", "Coriander (Dhania) Leaves , a small bunch finely chopped"]'::jsonb, ARRAY['s paneer', 'homemade cottage cheese', 'pearl onions', 'sambar onions', 'tomato', 'mustard seeds', 'rai/ kadugu', 'red chilli powder', 'salt', 'oil', 'curry leaves', 'coriander', 'dhania', 'laung', 'cinnamon stick', 'dalchini', 'cardamom', 'elaichi', 'whole black peppercorns', 'kalpasi leaves', 'star anise', 'dry red chilli', 'poppy seeds', 'fresh coconut', 'reen chillies']::text[], '["To begin making Paalkatti Chettinad Curry Recipe (Chettinad Style Paneer Kurma Recipe) by roast the ingredients listed under Chettinad\u00a0paste.In a Preheated pan add all the ingredients, cinnamon, cloves, cardamom ,peppercorn, kalpasi leaves, star anise, poppy seeds dry red chillies and grated coconut.", "Saute and roast them until the coconut turns golden brown.", "Cool it down and blend it using a grinder to a nice smooth paste by adding a\u00a0little water.The next step is to heat a\u00a0nonstick\u00a0shallow pan and add oil, once it is heated up add mustard seeds and asafoetida (hing), let it splutter for few seconds.Then add garlic, onions saute till it is nice and brown.", "Add in the chopped tomatoes and fry till the raw smell goes away, you can add a little salt to make it cook faster.Once done add the paneer along with the paste and give it a stir.", "Add water and cover the pan cook it for some time,\u00a0like for about 3 minutes.Open the lid and add the chopped coriander to Paalkatti Chettinad Curry and give it a stir.Serve your spicy\u00a0Paalkatti\u00a0Chettinad Curry Recipe along with\u00a0Tawa Paratha\u00a0and\u00a0Carrot Cucumber Tomato Salad with Lemon and Coriander\u00a0\u00a0for a weekday dinner."]'::jsonb, 50, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/oct-19/Paal_katti_Chettiand_Curry_Recipe_Chettinad_Style_Paneer_Kurma_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/823.Paal_katti_Chettiand_Curry_Recipe_Chettinad_Style_Paneer_Kurma_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Soya Methi Palak Ki Sabzi Recipe', 'soya-methi-palak-ki-sabzi-recipe', 'Soya Methi Palak Ki Sabzi Recipe is made from soy protein chunks along with spiced and pureed spinach and fenugreek leaves. Adding soybean to makes this dish high in nutritional value, as soybean is fabulous source of protein. Full of goodness of the green leafy vegetables and the soya bean this is a great recipes that can be packed into your office lunch box as well.', '["2 cups Spinach Leaves (Palak) , roughly chopped", "100 grams Soy Chunks (Nuggets)", "1 cup Methi Leaves (Fenugreek Leaves) , roughly chopped", "1/2 cup Onion , chopped", "3/4 cup Homemade tomato puree", "2 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "2 Green Chillies , slit lengthwise", "Salt , as per taste", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Garam masala powder", "2 teaspoons Butter (Salted)", "2 Garlic , thinly sliced", "3 Dry Red Chillies", "1 tablespoon Oil"]'::jsonb, ARRAY['tomato', 'green chillies', 'salt', 'ginger', 'cumin powder (jeera)', 'methi leaves (fenugreek leaves)', 'cloves garlic', 'dry red chillies', 'onion', 'garlic', 'soy (nuggets)', 'spinach leaves (palak)', 'butter', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Soya Methi Palak Ki Sabzi Recipe, firstly soak the soya chunks in a bowl of hot boiling water.", "Transfer the soy chunks along with the water into a\u00a0 pressure cooker and pressure cook for one whistle.", "Turn off the flame.", "Allow the pressure to release naturally.", "Drain the water and set the soya chunks aside.", "Heat a pressure cooker with oil on medium flame, add ginger, green chillies, spinach along with 2 tablespoons of water and pressure cook for 2 whistles.", "Turn off the flame and allow the pressure to release naturally.", "Once cooled, transfer the\u00a0ginger, green chillies, spinach into a mixer jar and grind into a paste.", "Set aside.", "Heat butter in a pan on low flame, add chopped garlic and saute for about 30 seconds or until it turns light brown.", "Once done add finely chopped onions and saute till it turns transparent, this will take about 2-3 minutes.", "Once the onion-garlic is well cooked, add tomato puree and mix well.", "Cover and cook for 2 minutes.", "At this stage open the lid, and add the methi leaves, continue to cook, stirring occasionally.", "Once the methi leaves have cooked add in the spinach puree, cooked soya chunks, salt, cumin powder , garam masala and give it a good stir.", "Once\u00a0Soya Methi Palak Ki Sabzi is well combined bring to a boil and turn off the heat.Serve Soya Methi Palak Ki Sabzi Recipe along with\u00a0Jowar Atta Roti Recipe - Sorghum Wheat Phulka Recipe,\u00a0Pudina Pyaz Kachumber Salad Recipe\u00a0and\u00a0Beetroot Carrot Raita Recipe\u00a0for a complete diabetic meal."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/Soya_Methi_Palak_Ki_Sabzi_Recipe_-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/824.Soya_Methi_Palak_Ki_Sabzi_Recipe_-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Whole Wheat Methi Garlic Naan Recipe  | Oven Method with yeast', 'whole-wheat-methi-garlic-naan-recipe-oven-method-with-yeast', 'The Whole Wheat Methi Garlic Naan is packed with flavours of methi and garlic and fermented with yeast  and yogurt to bring out the delicious flavours. The addition of yeast and yogurt brings out the perfect softness in the naan.', '["2 cups Whole Wheat Flour", "2 teaspoons Active dry yeast", "1 teaspoon Salt", "1 teaspoon Sugar", "6 cloves Garlic , finely chopped", "100 grams Methi Leaves (Fenugreek Leaves) , finely chopped", "1/4 cup Curd (Dahi / Yogurt)", "1 tablespoon Oil", "Butter (Salted) , for greasing Naan"]'::jsonb, ARRAY['salt', 'wheat flour', 'butter greasing naan', 'methi leaves (fenugreek leaves)', 'cloves garlic', 'dry yeast', 'curd', 'sugar', 'sunflower oil']::text[], '["To begin making the Whole Wheat Methi Garlic Naan recipe, first prep all the ingredients and keep them ready.Into a large mixing bowl, add the flour, salt, sugar and yeast.", "Combine all the dry ingredients.Make a well in the center, add the Methi leaves, garlic, yogurt and little lukewarm water at a time and knead well to make smooth dough.Drizzle a little oil on the top and knead until the dough is smooth for about 3 to 4 minutes.Cover the dough with a lid or a kitchen towel and allow the dough to rise in room temperature for at least 2 hours until it has risen in size.Once the dough has risen, we will now prep for baking the Naan.Preheat the oven to 250 C for about 20 minutes.In this 20 minutes, we will roll the dough out into ovals and allow it to rest for 15 minutes.Divide the dough into 10 to 12 portions.", "Dust in flour and roll into an oval of 1/4 inch thickness.Place the rolled Whole Wheat Methi Garlic Naan into a greased and dusted baking sheet and continue the remaining process of the remaining dough.Cover the rolled dough with a kitchen towel.Allow the dough to rest for about 15 to 20 minutes in the baking sheet.Once rested and the oven is well preheated, place the Whole Wheat Methi Garlic Naan in the oven and bake on high heat for about 10 to 12 minutes until you notice the golden crust on the top.Once the\u00a0Whole Wheat Methi Garlic Naan has a golden crust, remove from the oven and smear it with butter and serve hot.Serve the Whole Wheat Methi Garlic Naan recipe along with\u00a0Matar Paneer\u00a0and\u00a0Dal Makhani\u00a0for a wholesome lunch or dinner."]'::jsonb, 140, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Whole_Wheat_Methi_Butter_Naan_Recipe_Baked_in_Oven_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/825.Whole_Wheat_Methi_Butter_Naan_Recipe_Baked_in_Oven_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Gongura Pulihora Recipe | Gongura Puliyodharai | Spicy Red Roselle Leaves Rice', 'andhra-gongura-pulihora-recipe-gongura-puliyodharai-spicy-red-roselle-leaves-rice', 'The Andhra  Gongura Puliyodharai Recipe is a delicious south indian rice dish that is made from Red Roselle Leaves also known as Gongura leaf. The Gongura leaf is widely used in Andhra Cuisine and many recipes are made using gongura leaves and this one is an absolute delicacy.', '["2 cups Rice", "300 grams Gongura Leaves (Red Roselle) , washed and finely chopped", "2 teaspoons Salt , to taste", "3 tablespoons Sesame (Gingelly) Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Asafoetida (hing)", "1 teaspoon White Urad Dal (Split)", "1 teaspoon Chana dal (Bengal Gram Dal)", "1/2 cup Roasted Peanuts (Moongphali)", "2 sprig Curry leaves , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 tablespoon Coriander (Dhania) Seeds", "2 tablespoon Sesame seeds (Til seeds)", "1 tablespoon Chana dal (Bengal Gram Dal)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "4 Dry Red Chillies"]'::jsonb, ARRAY['s rice', 's gongura leaves', 'red roselle', 's salt', 's sesame', 'gingelly', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing', 'white urad dal', 'split', 'chana dal', 'bengal gram dal', 'roasted peanuts', 'moongphali', 'curry leaves', 'turmeric powder', 'haldi', 'coriander', 'dhania', 'sesame seeds', 'til seeds', 'methi seeds', 'fenugreek seeds', 'dry red chillies']::text[], '["To begin making the Andhra Gongura Puliyodharai Recipe, prep all the ingredients and keep them ready.Wash the rice well and add it into a pressure cooker along with 4 cups of water.", "Cover the pressure cooker and cook the rice for 2 whistles.", "After 2 whistles, turn the heat to low and simmer the rice for 3 to 4 minutes and turn off the heat.Allow the pressure to release naturally.", "Once the pressure releases, open the cooker, transfer the rice to a wide place and drizzle a little sesame oil and toss the rice gently and keep aside to cool.", "We do this, so the rice remains grainy and not sticky.Wash the\u00a0Gongura\u00a0leaves, remove the stems and only use the leaves.", "Finely chop the Gongura leaves and keep this aside.In a skillet, dry roast the ingredients mentioned in the Puliyodharai masala until browned and crisp - chana dal, coriander seeds, sesame seeds, methi seeds and red chillies.Ensure to roast on low to medium heat so the aromas of the dal and coriander come through.", "Once well roasted, turn off the heat and allow it to cool.Once cooled add it to a small jar of the mixer grinder and blend into a smooth powder.", "Keep it aside.In a heavy bottomed pan, heat a few tablespoon of sesame oil over medium heat.", "Add the mustard seeds, urad dal, chana dal and raw peanuts.", "Allow the dals and peanuts to roast well until it is crisp and golden brown.", "Once done stir in the curry leaves, asafoetida and stir for a few seconds.", "Add the chopped Gongura leaves, salt, turmeric powder, salt and\u00a0for a few minutes.", "The Gongura leaves cook very quickly and will become soft in about a minute.Once the leaves become soft, add the ground masala and stir for another couple of minutes.", "Finally add the cooked rice to the Gongura Puliyodharai masala and stir well to combine until all the rice is well coated with the masala.", "Check the salt and adjust to suit your taste.Cover the pan and allow the flavors to get absorbed to make the\u00a0Gongura Puliyodharai get all its flavours - for about 4 to 5 minutes.Turn off the heat and transfer the Gongura\u00a0Puliyodharai to a serving bowl and serve hot.Serve the Andhra\u00a0Gongura Puliyodharai as it is for lunch or dinner along with a\u00a0tomato onion thayir pachadi\u00a0and enjoy a wholesome and delicious meal."]'::jsonb, 45, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Andhra_Style_Gongura_Pulihora_Recipe_-_Spicy_Red_Roselle_Leaves_Rice__2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/826.Andhra_Style_Gongura_Pulihora_Recipe_-_Spicy_Red_Roselle_Leaves_Rice__2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Chemmeen Moilee Recipe - Prawn Curry', 'kerala-style-chemmeen-moilee-recipe-prawn-curry', 'Kerala Style Chemmeen Moilee Recipe -Prawn Curry is a comfort curry made from shrimps cooked in rich coconut milk. The curry is so simple to make as it is made in a one pot. Moilee is a very common dish in Kerala and is usually made from a variety of fish but we can use different kind of seafood as well to create this wonderful delicacy. This curry does not use any tamarind but has strong flavors from the whole spices like the cardamom pods, cinnamon sticks and whole peppercorns.', '["500 grams Shrimps , cleaned and deveined", "1/2 cup Pearl onions (Sambar Onions)", "1 Tomato , chopped", "1 Green Chilli , slit", "1 inch Ginger", "4 cloves Garlic", "1 inch Cinnamon Stick (Dalchini)", "1 Cardamom (Elaichi) Pods/Seeds", "1 teaspoon Whole Black Peppercorns", "1 sprig Curry leaves", "1 cup Coconut milk", "1 teaspoon Turmeric powder (Haldi)", "1 Lemon juice", "1 teaspoon Sugar", "Salt , to taste", "Coconut Oil , for cooking"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'green chilli', 'cardamom (elaichi) podsseeds', 'cloves garlic', 'black peppercorns', 'pearl onion (sambar onion)', 'curry leaves', 'sugar', 'cinnamon stick (dalchini)', 'lemon', 'coconut oil', 'coconut milk', 'turmeric powder', 'shrimps deveined']::text[], '["To begin making the Kerala Style Chemmeen Moilee Recipe - Prawn Curry, marinate the shrimps with turmeric powder and lemon juice and keep it aside for at least 15 minutes.Heat a kadai with oil, add cinnamon, cardamom pods, pepper corns and allow it to sizzle.", "Add whole shallots and saute until they turn slightly brown.Once done add chopped ginger, garlic and saute until they soften.", "Now add the tomatoes and salt to taste.", "Do not mash them completely.", "Cook till the tomatoes just turn soft.Once done add coconut milk along with turmeric powder and salt and bring it to a boil.", "Stir in the sugar and slowly drop in the shrimps and cook in a medium heat for about 20 minutes till the shrimp are cooked.Once done turn off the heat and transfer the\u00a0Kerala Style Chemmeen Moilee to a serving bowl and serve hot.Serve the Kerala Style Chemmeen Moilee Recipe along with\u00a0Steamed Rice\u00a0or\u00a0kerala parotta\u00a0and\u00a0Cabbage Thoran."]'::jsonb, 30, 'Kerala', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Kerala_Style_Chemeen_Moilee_Recipe_Prawn_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/827.Kerala_Style_Chemeen_Moilee_Recipe_Prawn_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Almond and Cashew Nut Mushroom Curry Recipe', 'almond-and-cashew-nut-mushroom-curry-recipe', 'Almond and Cashew Nut Mushrooms Curry Recipe is delicious, very simple and delicious recipe that you can make for parties. It is a very Indian taste with flavors coming from the spices and herbs.', '["500 grams Button mushrooms , quartered or whole", "1 Onions , finely chopped", "4 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "2 Green Chillies , finely chopped", "1 tablespoon Sesame seeds (Til seeds)", "1 teaspoon Poppy seeds", "5 Whole Almonds (Badam)", "5 Cashew nuts", "1/2 teaspoon Black pepper powder", "Oil , or butter to cook", "1 teaspoon Garam masala powder", "1 Coriander (Dhania) Leaves", "Salt , to taste"]'::jsonb, ARRAY['cashew nuts', 'salt', 'ginger', 'coriander (dhania) leaves', 'cloves garlic', 'onion', 'sesame seeds (til seeds)', 'poppy seeds', 'badam (almond)', 'black pepper powder', 'sunflower oil butter', 'button mushrooms', 'green chillies', 'garam masala powder']::text[], '["To begin making the Almond and Cashew Nut Mushroom Curry Recipe, get all the ingredients ready and keep them aside, so things will be organized for cooking the dish.First, make a paste of onion, ginger, green chili and garlic in a food grinder and keep it aside.Next in the same food grinder, make a paste of the almonds, cashew nuts and poppy seeds by adding a little water to make a smooth paste.", "Keep this aside.In a\u00a0heavy-bottomed pan; add a teaspoon of butter and\u00a0the onion paste and\u00a0saut\u00e9 until the raw smells of the onions go away.", "Add the black pepper powder and garam masala powder an give it a good stir.", "Add the mushrooms, sprinkle some salt and stir fry the mushrooms until they are partially cooked.", "You will know this when it begins to start releasing its liquids.Add the almond cashew paste to the mushroom mixture.", "Add about 1/2 cup of water and give the Mushroom Curry a good stir.", "Check the salt and spice levels and adjust to suit your taste.Give the mixture a brisk boil and you will find the mixture thickens as you boil.", "You can adjust the consistency of the Almond Mushroom Curry by adding water.Once the curry comes to a brisk boil and starts to thicken, turn off the heat.", "Stir in the chopped coriander leaves and serve.Serve the\u00a0Almond and Cashew Nut Mushrooms Curry along with a\u00a0Broccoli Pepper Pulav, Papad for a weeknight dinner or even make them for your parties."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Almond_and_Cashewnut_Mushroom_Curry_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/828.Almond_and_Cashewnut_Mushroom_Curry_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Himachali Pahari Auriya Kaddu Recipe - Himachali Tangy Pumpkin Sabzi', 'himachali-pahari-auriya-kaddu-recipe-himachali-tangy-pumpkin-sabzi', 'Himachali Pahari Auriya Kaddu Recipe (Tangy Pumpkin Dry) is a delicious stir fry made with chunks of pumpkin, the recipe contains the flavours of panch phoron and tanginess from the amchur powder and ground mustard seeds.', '["500 grams Kaddu (Parangikai/ Pumpkin) , cut into small chunks", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "2 teaspoons Panch Phoran Masala", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "1 teaspoon Mustard oil", "To Grind", "2 teaspoon Rice", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Yellow mustard seeds"]'::jsonb, ARRAY['salt', 'ginger', 'parangikai pumpkin', 'amchur (dry mango powder)', 'asafoetida (hing)', 'mustard oil', 'rice', 'mustard seeds', 'cloves garlic', 'yellow mustard seeds', 'cumin seeds (jeera)', 'panch phoran masala', 'coriander powder']::text[], '["To begin making the Himachali Pahari Auriya Kaddu Recipe, soak the rice and mustard seeds in 1/4 cup water for about 15 minutes.Grind the soaked rice and mustard seeds into a coarse paste in the mixer and keep it aside.Heat a kadai with oil over medium heat; add cumin seeds, asafoetida and allow it crackle for few seconds.Stir in the garlic and ginger and saute for a few seconds.", "Add the pumpkin, sprinkle a little salt and give it a stir.Cover the pan and cook the pumpkin for about 10 minutes till it becomes soft.Once the pumpkin is cooked, add spice powders including panch phoran masala, amchur, coriander powder along with ground rice and mustard paste and stir fry till the masala is coated to give a delicious tasting\u00a0Pahari Auriya Kaddu.Once done, check the salt and adjust according to taste.", "Transfer the\u00a0Pahari Auriya Kaddu to a serving bowl and serve hot.Serve the\u00a0Pahari Auriya Kaddu Recipe\u00a0along with\u00a0Whole Wheat Onion Stuffed Kulcha\u00a0and\u00a0Tadka Dal\u00a0for your everyday meals."]'::jsonb, 45, 'Himachal', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Himachali_Style_Pahari_Auriya_Kaddoo_Recipe_Tangy_Pumpkin_Dry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/829.Himachali_Style_Pahari_Auriya_Kaddoo_Recipe_Tangy_Pumpkin_Dry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vazhaipoo Bajra Adai Recipe - Banana Flower & Pearl Millet Dosa', 'vazhaipoo-bajra-adai-recipe-banana-flower-pearl-millet-dosa', 'Vazhaipoo Bajra Adai Recipe (Banana Flower & Pearl Millet Crepe), a nutritious meal that is made with banana flower which is mixed along with 5 different kinds of dals like moong dal, toor dal, urad dal and channa dal. In order to keep it highly nutritious we have also added pearl millet which is rich in fiber and protein content. Banana flower is rich in protein content, it is also helpful in managing diabetics. The adai as a whole will give you a healthy start for your day.', '["1 Banana flower (Vazhaipoo) , cleaned and chopped", "1 Onion , chopped", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "To Grind", "1/4 cup White Urad Dal (Split)", "1/4 cup Arhar dal (Split Toor Dal)", "1/4 cup Chana dal (Bengal Gram Dal)", "1 cup Bajra (seeds)", "1 tablespoon Whole Black Pepper Corns", "3 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'arhar dal (split toor dal)', 'banana flower (vazhaipoo)', 'black pepper corns', 'curry leaves', 'white urad dal (split)', 'onion', 'bajra (seeds)', 'turmeric powder', 'chana dal (bengal gram dal)']::text[], '["To begin making the Vazhaipoo Bajra Adai Recipe, soak the dals and millet in water for at least 3 hours.Once the dals are soaked, grind them along with pepper and curry leaves to a coarse batter by adding little bit of water.The batter must be the same consistency of a dosa batter and not too runny.", "Once all of it is ground keep, stir in the salt and keep the Bajra adai batter aside aside.Move ahead to clean the banana flower, take out the petals first and you will notice small white florets at the bottom, pluck them out.Keep a container with buttermilk ready in order to add the used florets.", "From each banana floret, the stamen (kaalan) and the thin white colored cover portions must be removed and should be soaked in the buttermilk.Once u have done removing all the florets, drain the buttermilk and chop the florets into small pieces.Heat a kadai with oil, add onions and saute till they turn translucent.", "Add chopped florets, sprinkle with salt and turmeric and saute until the florets are cooked.Add these saut\u00e9ed Banana Flower into the Bajra Adai batter and mix well to combine.Heat a dosa tawa, once it becomes hot, use a ladle to take little batter and pour it in the center and spread it in concentric circles with the back ladle to form a thin Adai.Drizzle oil around the Banana Flower Bajra Adai cook until the Adai is crisp and golden brown on both sides.Serve the Vazhaipoo Bajra Adai Recipe along with\u00a0Coconut chutney\u00a0and\u00a0Sambar\u00a0to make it a wholesome high protein meal."]'::jsonb, 210, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/9-oct/_Vazhaipoo_Bajra_Adai_Recipe_Banana_Flower__Pear_Millet_Crepe-9313.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/830._Vazhaipoo_Bajra_Adai_Recipe_Banana_Flower__Pear_Millet_Crepe-9313.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lebu Lonka Murgi Recipe - Chicken With Gondhoraj Lebu & Green Chillies', 'lebu-lonka-murgi-recipe-chicken-with-gondhoraj-lebu-green-chillies', 'Lebu Lonka Murgi is a delicious recipe where succulent pieces of chicken is cooked in creamy yoghurt and tangy Gondhoraj lebu juice. Some lime leaves added in for a further burst of citrus and green chillies for their heat. A', '["500 grams Chicken", "2/3 cup Curd (Dahi / Yogurt)", "10 Kaffir lime leaves", "2 Gondhoraj lebu lemon , sliced", "1 tablespoon Gondhoraj lebu juice", "6 tablespoons Onion , puree", "1/2 tablespoon Ginger , juice", "2 teaspoon Green Chilli , paste", "2 tablespoon Ginger , cut into fine juliennes", "1 teaspoon Garlic , finely chopped", "4 Green Chilli , slit", "10 Whole Black Peppercorns", "1/2 tablespoon Black pepper powder", "3 tablespoons Mustard oil", "1 teaspoon Honey , optional", "Salt , to taste"]'::jsonb, ARRAY['s chicken', 'curd', 'dahi / yogurt', 'kaffir lime leaves', 'ondhoraj lebu lemon', 'gondhoraj lebu juice', 's onion', 'ginger', 'green chilli', 'garlic', 'reen chilli', 'whole black peppercorns', 'black pepper powder', 's mustard oil', 'honey', 'salt']::text[], '["To begin making the Lebu Lonka Murgi recipe, marinate the chicken pieces with a little salt, gondhoraj lebu lemon juice, onion juice, ginger juice, green chili paste and half of the yoghurt.", "Refrigerate for 1-2 odd hours.Heat oil in a heavy bottomed pan, once it is smoking hot, add in the black peppercorns and garlic.", "Saute till light brown.Add the marinated chicken and set the marinade aside.Stir the garlic over high heat till light brown.Add the ginger juliennes, black pepper powder, green chillies, remaining yogurt and the marinade, cook for 4-5 minutes.", "You could add a a touch of honey if needed to balance out the flavours.", "Add 1/2 a cup of warm water and the lime leaves, continue to cook till the chicken is tender.Adjust seasonings to suit your taste.", "Switch off the flame, add in the lemon slices, cover and allow to stand for 10 odd minutes.", "Serve hot.Serve\u00a0Lebu Lonka Murgi with\u00a0Steamed Rice\u00a0or\u00a0Whole Wheat Laccha Paratha\u00a0for a weekend meal."]'::jsonb, 35, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/maumita.paulghosh-gmail.com/Lebu_Lonka_Murgi_Chicken_with_Gondhoraj_Lebu_and_Green_Chillies.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/831.Lebu_Lonka_Murgi_Chicken_with_Gondhoraj_Lebu_and_Green_Chillies.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thayir Semiya Recipe (Curd Semiya)', 'thayir-semiya-recipe-curd-semiya-2', 'Thayir Semiya or Curd Vermicelli is a quick dish which you can make for lunch. If you are bored of eating curd rice everyday, you can always make this Thayir semiya or curd semiya for a change. In South India, people consume curd everyday.', '["1/2 cup Semiya (Vermicelli) , roasted", "1 cup Curd (Dahi / Yogurt)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon White Urad Dal (Split)", "pinch Asafoetida (hing)", "1 sprig Curry leaves", "2 teaspoon Oil", "Raw Peanuts (Moongphali)", "1 sprig Curry leaves", "2 teaspoon Oil", "5 to 6 Cashew nuts , for garnishing"]'::jsonb, ARRAY['cashew nuts', 'asafoetida (hing)', 'mustard seeds', 'curd', 'white urad dal (split)', 'semiya (vermicelli)', 'curry leaves', 'peanuts (moongphali)', 'sunflower oil']::text[], '["To begin making the Thayir Semiya recipe, firstly boil the vermicelli in 2 cups water.", "Drain it and spread on a colander.Pass cold water through it.", "This ensures that the vermicelli does not become sticky.", "Keep it aside and let it cool down.Heat a kadai/wok and add oil.", "Add the peanuts and roast till it turns brownish.", "Remove and keep it aside.In the same kadai, add more oil if needed and add the mustard seeds and after it splutters add the other ingredients meant for tempering.Add the boiled vermicelli and mix everything.", "Add salt to taste and mix.Finally just before serving add curd and mix well.", "Serve Thayir Semiya on its own for a light and healthy lunch or dinner."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Thayir_Curd_Semiya_recipe_Yogurt_Vermicelli_South_indian_Lunch_recipe-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/832.Thayir_Curd_Semiya_recipe_Yogurt_Vermicelli_South_indian_Lunch_recipe-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rajasthani Dal Recipe', 'rajasthani-dal-recipe', 'The Rajasthani Dal recipe is a dal that is packed with flavor and proteins. The addition of green moong dal, chana dal and mildly spiced with some garlic makes this rajasthani dal delectable. And finally not to miss the addition of ghee, green chillies and lemon juice that gives the perfect spice and tanginess needed to digest this dal.', '["1/2 cup Green Moong Dal (Whole)", "1/4 cup Chana dal (Bengal Gram Dal)", "1 teaspoon Cumin seeds (Jeera)", "1 Onion , roughly chopped", "4 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "2 Green Chillies", "1 inch Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta) , torn", "1 Tomato , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Asafoetida (hing)", "Salt , to taste", "6 sprig Coriander (Dhania) Leaves , for garnish", "1 Lemon , juice extraced", "1 tablespoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies , broken"]'::jsonb, ARRAY['tomato', 'green chillies', 'salt', 'ginger', 'lemon ced', 'bay leaf (tej patta)', 'asafoetida (hing)', 'ghee', 'red chilli powder', 'cloves garlic', 'coriander (dhania) leaves', 'dry red chillies', 'onion', 'cinnamon stick (dalchini)', 'green moong dal', 'turmeric powder', 'chana dal (bengal gram dal)', 'cumin (jeera) seeds']::text[], '["To begin making the Rajasthani Dal, we will first soak the moong dal and chana dal in 3 cups of water for about 3 hours.", "Heat ghee in a pressure cooker over medium heat; add the cumin seeds and allow it to crackle.", "Add the onion, green chillies, ginger and garlic and saute until the onion softends.Add the bay leaf and cinnamon stick and saute for a few seconds until you can smell the aromas coming through.Next add the tomatoes, turmeric powder, red chilli powder, hing and saute for about a minute until the tomatoes have slightly softened.Once the tomatoes have softened, add the soaked dals, salt to taste and add water if required such that the water is at least 2 inches above the level of dal.Cover the pressure cooker, and pressure cook the Rajasthani Dal for about 5 to 6 whistles - about 20 minutes until it is completely cooked through.Turn off the heat and allow the pressure to release naturally.", "Once the pressure has released, check if the dals are cooked well to perfection.", "Once pressed between fingers it should mash easily.Stir in the juice from the lemon and the coriander leaves and transfer the Rajasthani Dal to a serving bowl.The next is the tadka, heat ghee in a pan over medium heat.", "Add the cumin seeds and red chillies and allow it to roast for a few seconds.", "Turn off the heat and add this tadka to the Rajasthani Dal.Serve the Rajasthani Panchmel Dal along with\u00a0Bati\u00a0or eat it along\u00a0Spicy Paneer Pulao With Vegetables\u00a0followed by the mouth-watering\u00a0Traditional Rasmalai Recipe."]'::jsonb, 270, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Rajasthani_Dal_Recipe_7_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/833.Rajasthani_Dal_Recipe_7_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Broken Wheat And Green Moong Khichdi Recipe', 'broken-wheat-and-green-moong-khichdi-recipe', 'Broken Wheat And Green Moong Khichdi is a quick, healthy, one pot meal that is perfect for busy weeknights. Unlike the usual rice-lentil combination, this khichdi is made using wheat Dalia and lentils. This fiber-rich khichdi is also packed with fresh seasonal vegetables and is as comforting as it is nutritious. The Broken Wheat And Green Moong Khichdi is delicious on its own, but you can serve it with the usual accompaniments.', '["1 cup Broken Wheat (Dalia/ Godumai Rava) , lightly roasted, washed and drained", "1/2 cup Green Moong Dal (Whole) , lightly roasted and soaked in water for 30 minutes", "1 Onion , finely chopped", "4 Garlic", "1/4 cup Green beans (French Beans) , finely chopped", "1 Carrot (Gajjar) , finely chopped", "1 tablespoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "5-6 Curry leaves , torn with hands", "1/2 inch Ginger , grated", "1/2 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Asafoetida (hing)", "3-4 Green Chillies", "Mint Leaves (Pudina) , a few sprigs chopped", "1 teaspoon Lemon juice"]'::jsonb, ARRAY['wheat (dalia godumai rava)', 'green beans (french beans)', 'ginger', 'ghee', 'mustard seeds', 'asafoetida (hing)', 'carrot', 'onion', 'garlic', 'cumin seeds (jeera)', 'lemon', 'green moong dal', 'turmeric powder', 'green chillies', 'curry leaves hands', 'mint leaves (pudina)']::text[], '["To begin making the Broken Wheat And Green Moong Khichdi, first crush together the garlic cloves, cumin seeds and green chilies in a small mortar and pestle.", "Keep it aside.Heat oil or ghee in a pressure cooker and add mustards seeds.", "Once they crackle, add the crushed garlic-cumin-chillies paste and the curry leaves.Fry for a few seconds and then add the onion.", "Saute for a minute and then add turmeric powder, asafoetida and ginger.", "Mix it properly and add all the vegetables.Saute for another minute and then add the dalia and green moong.Add enough water (depending on the consistency required) and mix well.", "About 3 cups for a porridge like consistency.Sprinkle some salt and cook it till the cooker releases 2 whistles or till well cooked.Wait for the pressure to come down on its own.", "Garnish the khichdi with chopped mint and coriander, lime juice (if using) and serve immediately.Serve Broken Wheat And Green Moong Khichdi with\u00a0Mooli raita\u00a0or\u00a0Gujarati Kadhi\u00a0and papad."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Dalia_broken_wheat_and_Green_Moong_Khichdi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/834.Dalia_broken_wheat_and_Green_Moong_Khichdi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Matar Paneer Recipe - Paneer in Peas Gravy', 'matar-paneer-recipe-paneer-in-peas-gravy', 'Matar Paneer Recipe is an all time favorite North Indian dish. The combination of peas, tomatoes and paneer gives this dish a subtle sweetness which enhances the taste of this flavored dish. The recipe works perfectly well with frozen peas which is tossed in butter.', '["250 grams Paneer (Homemade Cottage Cheese) , cubed into small pieces", "1/2 cup Green peas (Matar) , frozen and thawed", "1 tablespoon Butter (Salted)", "1 tablespoon Ghee", "2 Brown cardamom (Badi Elaichi)", "4 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini) , broken", "1 teaspoon Whole Black Pepper Corns", "1 Onion , finely chopped", "4 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "5 Tomatoes , quartered", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Coriander (Dhania) Powder", "1/2 teaspoon Red Chilli powder", "1 teaspoon Salt , or to taste", "1 teaspoon Sugar", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "6 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['s paneer', 'homemade cottage cheese', 'green peas', 'matar', 'butter', 'salted', 'ghee', 'brown cardamom', 'badi elaichi', 'laung', 'cinnamon stick', 'dalchini', 'whole black pepper corns', 'onion', 's garlic', 'ginger', 'tomatoes', 'turmeric powder', 'haldi', 'cumin powder', 'jeera', 'garam masala powder', 'coriander', 'dhania', 'red chilli powder', 'salt', 'sugar', 'kasuri methi', 'dried fenugreek leaves']::text[], '["To begin making the\u00a0Matar Paneer Recipe, prep all the ingredients and keep them ready.Add the chopped tomatoes to a mixer grinder jar and blend to make a smooth puree.", "Keep this aside.Thaw the frozen green peas in the microwave along with a tablespoon of butter and keep aside.Heat ghee in a cooking pan/ wok/ kadai; add the whole spices from cloves, cinnamon, badi elaichi and pepper.", "Stir fry them for a few seconds till the aromas start whiffing through the room.Next, add the onion, ginger and garlic and saute until the onions become soft and tender and lightly golden brown.Stir in the masalas - turmeric powder, red chilli powder, coriander powder, cumin powder, and garam masala powder.", "Give it a stir.Add the tomato puree, salt and sugar and give the mixture a stir.", "Allow the tomato masala to come to a brisk boil.", "Once it comes to a brisk boil, stir in the kasuri methi, paneer and the buttered green peas.Cover the pan, and simmer the Matar Paneer for about 5 minutes and turn off the heat.", "Give the Matar Paneer a taste and adjust the salt and spices accordingly.", "Finally stir in the coriander leaves and transfer the Matar Paneer to a bowl and serve hot.Serve the\u00a0Matar Paneer\u00a0along with hot\u00a0Phulka\u00a0smeared with ghee along with\u00a0Indian Sliced Salad\u00a0and\u00a0Lacha Pyaz\u00a0for lunch or dinner."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Matar_Paneer_Recipe_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/835.Matar_Paneer_Recipe_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Dondakaya Ulli Kura Karam Recipe | Andhra Kovakkai Fry', 'andhra-dondakaya-ulli-kura-karam-recipe-andhra-kovakkai-fry', 'Andhra Dondakaya Ulli Kura Karam Recipe is a delicious dish made from ivy gourd also known as Kovakkai, Tindora or Tendli which is tossed along with freshly roasted and ground masala which makes this dish absolutely yummy. All it takes is 20 minutes to make this delicious dish which you can serve for lunch or dinner.', '["500 grams Tindora (Dondakaya/ Kovakkai) , cut lengthwise", "2 tablespoons Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Asafoetida (hing)", "Salt , to taste", "2 tablespoons Coriander (Dhania) Seeds", "1 tablespoon Chana dal (Bengal Gram Dal)", "1 tablespoon White Urad Dal (Split)", "1 tablespoon Sesame seeds (Til seeds)", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "3 Dry Red Chilli , (adjust)", "15 grams Tamarind , gooseberry size", "2 tablespoons Roasted Peanuts (Moongphali)"]'::jsonb, ARRAY['salt', 'mustard seeds', 'asafoetida (hing)', 'tindora (dondakaya kovakkai)', 'curry leaves', 'white urad dal (split)', 'coriander (dhania) seeds', 'sesame seeds (til seeds)', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'dry red chilli', 'peanuts (moongphali)', 'tamarind', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making Andhra Dondakaya Ulli Kura Karam Recipe, prep all the ingredients and keep them ready.Place the cut\u00a0Dondakaya in the pressure cooker, sprinkle salt and turmeric powder along with 2 tablespoons water and pressure cook for 2 whistles.", "Turn off the heat after 2 whistles and open the pressure cooker immediately by releasing the weight with the fork or placing the cooker under cold running water.This is to ensure we don''t overcook the\u00a0Dondakaya/ Tindora.", "Keep this aside.Next step is the roast and grind the masala.Heat a small pan over medium heat; add the chana dal and urad dal and roast until they change color.Once they are turning a little brown, add the methi seeds, coriander seeds, sesame seeds, cumin seeds, red chillies.", "Stir for about a minute until they begin to release the aromas.Once done, turn off the heat and allow the roasted masala to cool.Once cooled, add the masala, the roasted peanuts and tamarind to a small jar of the mixer grinder, add blend to make a powder.", "Grind this without any water.", "Keep this aside.The final step is to now put together everything for the\u00a0Andhra Dondakaya Ulli Kura Karam.Heat oil in a heavy bottomed pan, over medium heat; add the mustard seeds and allow it to crackle.Once done, stir in the asafoetida and curry leaves for a few seconds.Add the cooked\u00a0Dondakaya / Tendli/ Tindora and the ground roasted masala.", "Give it a stir to combine it well.Cover the pan and turn the heat to low and cook the\u00a0Dondakaya Ulli Kura Karam for about 3 to 4 minutes so that all the flavours get well absorbed to bring in a delicious taste.", "Check the salt and adjust according to taste.Once done, turn off the heat and transfer the\u00a0Andhra Dondakaya Ulli Kura Karam to a serving bowl and serve hot.Serve\u00a0Andhra Dondakaya Ulli Kura Karam Recipe\u00a0along with\u00a0Steamed Rice Recipe, and\u00a0Andhra Style Bendakaya Charu Recipe\u00a0for a delicious lunch or dinner."]'::jsonb, 35, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Andhra_Dondakaya_Menthi_Karam_Koora_Recipe_Tendli_Sabzi_Tindora__5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/836.Andhra_Dondakaya_Menthi_Karam_Koora_Recipe_Tendli_Sabzi_Tindora__5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Haryana Style Egg Curry Recipe', 'spicy-haryana-style-egg-curry-recipe', 'A drive in Haryana''s highways is never complete without a meal of spicy egg curry with fresh roti''s. The dhaba variant is spicy, oily and delicious and this home adaptation of the same curry is an attempt to bring the same flavours to your table in a healthier manner. One of the things that stand apart in the Haryana Style Egg Curry is the addition of peas and paneer to it making the already rich protein curry even more wholesome.', '["4 Whole Eggs , boiled, peeled and halved", "1 cup Green peas (Matar)", "200 grams Paneer (Homemade Cottage Cheese) , chopped", "1 Onion , finely chopped", "2 Tomatoes , pureed", "2 teaspoon Ginger Garlic Paste", "3 Green Chillies", "2 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Garam masala powder", "1/4 cup Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['tomato', 'coriander (dhania) leaves', 'paneer', 'green peas (matar)', 'red chilli powder', 'ginger garlic paste', 'onion', 'coriander powder', 'eggs', 'turmeric powder', 'green chillies', 'garam masala powder']::text[], '["To begin making the Spicy Haryana Style Egg Curry, firstly prepare all the ingredients required for the curry.In a pan, take a teaspoon of oil and saut\u00e9 paneer till lightly browned.", "Keep aside for cooling.In a heavy bottom Kadai, heat the rest of the oil and add chopped onions, green chilli to the same.", "Fry till golden brown in colour.Add ginger-garlic paste and fry for 2 minutes.", "Add the tomato puree and fry till it is very well cooked and nicely browned.Add all the dry spices including coriander powder, turmeric powder, red chilli powder apart from garam masala and mix well.Add 1.5 cups of warm water along with peas, bring to a boil and let it simmer for 10-12 minutes till the gravy looks cooked.Add paneer and boiled eggs and simmer further for 2-3 minutes.Add chopped coriander leaves, garam masala, mix,\u00a0turn off the gas and let it rest for 10 minutes so that it absorbs flavours.Serve Spicy Haryana Style Egg Curry with Whole Wheat Lachha Paratha/\u00a0Grated Beetroot Chilli Paratha/\u00a0Tawa Paratha to make a nice dinner/ lunch."]'::jsonb, 45, 'Haryana', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Monika_Manchanda/Spicy_Haryana_Style_Egg_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/837.Spicy_Haryana_Style_Egg_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Butter Chicken Recipe - The Classic Indian Chicken Gravy', 'butter-chicken-recipe-the-classic-indian-chicken-gravy', 'Butter Chicken Masala Recipe is a delicious,creamy delightful chicken dish which has simple flavours yet it tastes great.', '["To marinate", "300 grams Boneless chicken , cut into pieces", "1/2 cup Curd (Dahi / Yogurt)", "2 teaspoon Ginger Garlic Paste", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "1 teaspoon Kashmiri Red Chilli Powder", "1 teaspoon Salt", "1 tablespoon Butter (Salted)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "1 cup Homemade tomato puree", "1 teaspoon Honey", "1/4 cup Fresh cream", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "Salt , to taste", "1/4 cup Fresh cream", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'boneless chicken', 'kashmiri red chilli powder', 'red chilli powder', 'ginger garlic paste', 'curd', 'coriander powder', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'butter', 'garam masala powder']::text[], '["To begin making the Butter Chicken Recipe, wash the chicken thoroughly.In a mixing bowl, add curd, garam masala,ginger and garlic paste, salt, red chili powder, turmeric powder and chicken.", "Marinate the butter chicken for a minimum for 1 hour.", "Heat a teaspoon of butter over medium heat, add the marinated chicken along with the marinade and let the chicken cook in its own masala for 4 minutes.", "Into the same pan, add tomato puree, salt, coriander powder, red chilli powder and garam masala.", "Cover the butter chicken and cook for 5 minutes.", "Finally add fresh cream, honey and water (if required to adjust the consistency of the gravy) and simmer the Butter Chicken Masala\u00a0until the chicken is cooked completely.Stir in the Kasuri methi and serve the butter chicken hot.Serve\u00a0Butter Chicken Masala Recipe\u00a0with\u00a0Butter Naan\u00a0and\u00a0Smoked Dal Makhani Dhaba Style Recipe\u00a0and\u00a0Pickled onions\u00a0and\u00a0Boondi Raita Recipe Spiced With Black Salt\u00a0\u00a0for a delicious punjabi style dinner."]'::jsonb, 45, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Non_Veg_Recipes/Butter_chicken_recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/838.Butter_chicken_recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Poondu Rasam Recipe | Spicy Garlic Rasam', 'chettinad-poondu-rasam-recipe-spicy-garlic-rasam', 'The Chettinad Style Poondu Rasam Recipe is a lip smacking rasam recipe, that is packed with flavors from the fresh rasam powder that is added along with the garlic in a the ghee tadka.', '["1/4 cup Arhar dal (Split Toor Dal) , cooked", "20 grams Tamarind , soaked 1 cup of hot water", "3 Tomatoes , chopped and pureed", "1 tablespoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "6 cloves Garlic , peeled and crushed", "2 sprig Curry leaves , roughly chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Black pepper powder", "1/2 teaspoon Cumin powder (Jeera)", "1-1/2 teaspoons Coriander (Dhania) Powder", "1 teaspoon Red Chilli powder", "1 teaspoon Salt , or to taste", "1 teaspoon Sugar", "6 sprig Coriander (Dhania) Leaves , for garnish, finely chopped"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'arhar dal (split toor dal)', 'tamarind water', 'mustard seeds', 'ghee', 'asafoetida (hing)', 'red chilli powder', 'cloves garlic', 'curry leaves', 'sugar', 'coriander (dhania) leaves', 'cumin seeds (jeera)', 'coriander (dhania) powder', 'black pepper powder', 'turmeric powder']::text[], '["To begin making\u00a0Chettinad Poondu Rasam Recipe, prep all the ingredients and keep ready.Cook the toor dal along with 1 cup of water and pressure cooker for 3 to 4 whistles.", "Turn the heat to low and simmer for 3 to 4 minutes and turn off the heat.", "Allow the pressure to release naturally.", "Once the pressure releases, mash the dal well to make it smooth.Extract the pulp from the soaked tamarind such that you get about 1 cup of Tamarind water.", "Keep aside.Puree the chopped tomatoes in a mixer grinder and keep aside.Heat ghee in a saucepan over medium heat.", "Add the mustard seeds and cumin seeds.", "Allow them to crackle.Once it crackles, add the asafoetida, curry leaves, garlic and saute for a few seconds until the aromas of garlic start coming through.Add the tomato puree, tamarind water, turmeric powder, red chilli powder, black pepper powder, cumin powder, coriander powder, sugar and salt to taste.Give the Chettinad Poondu Rasam a stir.", "Add 1 cup of water or more if required to get a flowing consistency of the rasam.Turn the heat to medium high and allow the Chettinad Poondu Rasam to come to a brisk boil.", "Once it comes to a brisk boil, turn the heat to medium - low and simmer the rasam for 10 minutes.", "You will notice that the Chettinad Poondu Rasam begins to froth up around the edges.", "This is a good indication of the rasam which got all its flavours.", "At this point, check the salt and spices and adjust to taste accordingly and turn off the heat.Once done, stir in the chopped coriander leaves and transfer the Chettinad Poondu Rasam to a serving bowl and serve hot.Serve\u00a0Chettinad Poondu Rasam Recipe\u00a0with Steamed rice,\u00a0Muttaikose Poriyal Recipe\u00a0and\u00a0Elai Vadam\u00a0for a healthy and light dinner."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Chettinad_Thakkali_Poondu_rasam_Recipe_6_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/839.Chettinad_Thakkali_Poondu_rasam_Recipe_6_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sabudana Khichdi Recipe - Sabudana Upma With Peanuts | Indian Breakfast', 'sabudana-khichdi-recipe-sabudana-upma-with-peanuts-indian-breakfast', 'Sabudana Khichdi Recipe is a simple to cook and delicious to eat recipe. It is healthy and widely used as fasting food in many Indian homes. The recipe is extremely low in fat and full of starch or carbohydrates and hence is a great food for a quick boost of energy.', '["1 cup Sabudana (Tapioca Pearls) , soaked in 1 cup water", "1 tablespoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves , finely chopped", "1 Onion , finely chopped", "2 Green Chillies , finely chopped", "1 inch Ginger , finely chopped", "1 Potato (Aloo) , peeled and finely chopped", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 Lemon , juice extracted", "1/4 cup Roasted Peanuts (Moongphali) , coarsely pounded", "6 sprig Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['sabudana', 'tapioca pearls', 'oil', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'curry leaves', 'onion', 'reen chillies', 'ginger', 'potato', 'aloo', 'turmeric powder', 'haldi', 'salt', 'lemon', 'roasted peanuts', 'moongphali', 'coriander', 'dhania']::text[], '["To begin making the Sabudana Khichdi, wash and soak the sabudana in enough water for 4 to 5 hours or even overnight .Using a colander, drain the excess water.", "Drain the water completely as if the sabudana has more water then they will clump up while cooking.Heat oil in a large pan\u00a0on\u00a0medium heat; add mustard seeds, cumin seeds and allow them to crackle.Stir in the curry leaves, onion, green chillies, ginger, potatoes and turmeric powder.", "Cover the pan and cook the potatoes until it is soft and done.Note: You can optionally used boiled potatoes as well.Once the potatoes are cooked, stir in the salt and sabudana.", "Mix well to combine all the ingredients.Cover the pan with a lid and simmer on low heat for about 5 minutes or until the sabudana is cooked.Stir occasionally.", "You can optionally sprinkle water, if your sabudana does not get cooked.But take care when you add water, you should only sprinkle water.", "Most times, keeping them on low to medium heat cooks the sabudana.To check readiness, the Sabudana\u00a0 would have changed its colour from white to translucent and it should be soft and tender not mushy.Each Sabudana ball will be separate and not like a lump of mass.", "Once the Sabudana Khichdi is cooked; stir in the crushed peanuts, lemon juice and coriander leaves.Turn off the heat; cover the pan and allow the Sabudana Khichdi to rest for about 5 minutes and serve hot.Serve the\u00a0Sabudana Khichdi Recipe along withAdrak Chai\u00a0to enjoy a delicious breakfast or a snack."]'::jsonb, 100, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Sabudana_Khichdi_Recipe_With_Peanuts_and_Potatoes_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/840.Sabudana_Khichdi_Recipe_With_Peanuts_and_Potatoes_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Homemade Rice Puttu Recipe | Kerala Matta Rice or Basmati Rice', 'homemade-rice-puttu-recipe-kerala-matta-rice-or-basmati-rice', 'The Kerala Rice Puttu is a traditional South Indian breakfast dish from Kerala. The Puttus are fluffy steamed rice cakes of a crumbly texture which are steamed to perfection along with coconut. Even though this is traditionally served for breakfast, you can also serve the Kerala Rice Puttu for lunch or dinner too.', '["1 cup Red matta rice , or Basmati Rice", "1-1/2 cups Fresh coconut , grated", "1/2 teaspoon Salt"]'::jsonb, ARRAY['red matta rice', 's fresh coconut', 'salt']::text[], '["To begin making the Kerala Rice Puttu, wash and soak the rice overnight or for about 8 hours.", "Once the rice has soaked well drain the water and spread the rice on a kitchen towel and dry it out.Allow the rice to dry for about 20 minutes but ensure it retains a bit of the moisture, else the rice will not grind well in mixer-blender.Grind the rice till it is mildly coarse.", "Do not grind the rice too much as it may get lumpy.", "In a large mixing bowl, combine the powdered rice, salt and 1/2 cup of the grated coconut.", "Sprinkle 4 tablespoons of water on to the rice mixture and stir to combine well with your fingers.", "The puttu mixture will be crumbly.", "When you hold the puttu mixture tightly in the palm of your hands it will hold together like a ball, when you release it, it will break apart.", "That''s the consistency we want to make the Puttu.Keep the Puttu Rice Mix aside for 10-15 minutes.", "Take a Puttu mould and place a 3 or 4 tablespoons of the prepared Puttu mixture and a 1 or 2 tablespoons of coconut in the centre and a few more tablespoons of the Puttu mixture on the top.", "Lightly press it and cover the pan.Prepare the Puttu steamer with water at the bottom, and place the puttu mold and steam on high heat for about 10 minutes.", "You will notice that after 5 to 6 minutes the steam will start releasing from holes in the top of the mold.This is when you know that the puttu is getting steamed from the inside.", "Allow this steam to escape for at least 5 minutes.", "In total the Puttu is steaming for a good 10 minutes.Once done, turn off the heat. remove the mold from the steamer and open the lid, and using a spoon of a blunt knife, push the steamed Kerala Puttu of the mold into a plate.Continue the same process with the remaining Puttu Mixture.Serve\u00a0Kerala Rice Puttu\u00a0Kadala Curry\u00a0or with sugar & chopped bananas for a wholesome meal."]'::jsonb, 30, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Kerala_Puttu_recipe_Matta_rice_Puttu_Using_Puttu_Maker_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/841.Kerala_Puttu_recipe_Matta_rice_Puttu_Using_Puttu_Maker_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('No Onion No Garlic Black Eyed Beans Curry Recipe', 'no-onion-no-garlic-black-eyed-beans-curry-recipe', 'No Onion No Garlic Black Eyed Beans (Chawli/Lobia/Cow peas) Curry is a tasty side dish usually served with Roti or Rice. This simple, quick no-onion/garlic recipe is made by cooking the nutritious beans with some flavourful spices and hence can be served for religious festive fares too. Groundnut powder adds taste and helps to thicken the gravy.', '["1 cup Black Eyed Beans (Lobia) , soaked in water for 7 to 8 hours", "1 tablespoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Asafoetida (hing)", "1/2 teaspoon Turmeric powder (Haldi)", "1 tablespoon Fresh coconut", "1 tablespoon Groundnut powder", "3 Kokum (Malabar Tamarind) , or use 1/2-1 teaspoon tamarind pulp", "1 teaspoon Jaggery , grated", "1/2 teaspoon Maharashtrian Goda Masala", "1/2 teaspoon Red Chilli powder", "Salt , to taste"]'::jsonb, ARRAY['kokum (malabar tamarind) tamarind pulp', 'salt', 'mustard seeds', 'asafoetida (hing)', 'coconut', 'jaggery', 'red chilli powder', 'cumin seeds (jeera)', 'maharashtrian goda masala', 'groundnut powder', 'turmeric powder', 'black eyed beans (lobia)', 'sunflower oil']::text[], '["To begin making the No Onion No Garlic Black Eyed Beans Curry, first cook the beans with 2 cups of water, in a pressure cooker, for 1 whistle and 10 to 15 minutes on sim (or till the beans are soft but not mushy).Heat oil in a heavy bottomed pan.", "Add the mustard seeds and once they crackle add the cumin seeds.Add the hing, turmeric powder, red chilli powder, goda masala.", "Mix everything well.Add the black eyed beans along with the water used for cooking.Add the kokum skin, jaggery, groundnut powder, coconut and salt.", "Simmer for 3 to 4 minutes, stirring once or twice.Serve No Onion No Garlic Black Eyed Beans Curry with\u00a0Roti\u00a0or Rice and a\u00a0Kachumber salad\u00a0on the side for a wholesome weekday meal."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Black_eyed_beans_curry_No_oniongarlic_recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/842.Black_eyed_beans_curry_No_oniongarlic_recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chikkudukaya Vepudu Recipe-Broad Beans Masala Poriyal', 'chikkudukaya-vepudu-recipe-broad-beans-masala-poriyal', 'Chikkudukaya Vepudu Recipe is a delicious side dish recipe made with Chikkudukaya also known as Broad beans in English and Sem in Hindi. The Chikkudukaya Vepudu is made with simple and yet delicate flavours from the onion,ginger and garlic sauteed along with tomatoes and simple masala.', '["250 grams Avarekai (Broad Beans) , cut into 1 inch pieces", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "1 sprig Curry leaves", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "1 tablespoon Oil , for cooking"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'red chilli powder', 'cloves garlic', 'curry leaves', 'onion', 'avarekai (broad beans)', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making\u00a0Chikkudukaya Vepudu Recipe first wash and cut the beans 1 cm wide.", "Discard any strings which might be present in the broad beans.Pressure cook the\u00a0Chikkudukaya/\u00a0 Avarakkai/ Broad beans in the pressure cooker along with 2 tablespoons of water and salt for 1 whistle and turn off the heat.Release the pressure immediately to prevent the\u00a0Chikkudukaya from getting over cooked and also by releasing the pressure immediately, the broad beans will retain its bright green colours.Keep a kadai on medium heat and add oil.", "Then add curry leaves, onions, ginger and garlic and saute until the onions become translucent and soft.Add turmeric powder, chili powder, coriander powder and stir for a minute.", "Add the tomatoes and saute until tomatoes become soft and mushy.Once the tomatoes have become soft and mushy, add the steamed\u00a0Chikkudukaya/\u00a0 Avarakkai/ Broad beans and give it a stir for a couple of minutes until the masala gets well coated into the vegetable.Check the taste of the Chikkudukaya Vepudu and adjust the salt and spices accordingly.", "Once done, turn off the heat and transfer the\u00a0Chikkudukaya Vepudu to a serving bowl.Serve\u00a0Chikkudukaya Vepudu with\u00a0Keerai Sambar,\u00a0Rice\u00a0,\u00a0Vadu Mangai Pickle\u00a0and\u00a0Homemade Yogurt\u00a0for a wholesome lunch or dinner."]'::jsonb, 35, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Chikkudgaya_Vepedu_Broad_Beans_Poriyal_Curry-6_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/843.Chikkudgaya_Vepedu_Broad_Beans_Poriyal_Curry-6_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kumror Chokka Recipe - Kaddu Kala Chana Sabzi | Pumpkin Chickpea Curry', 'kumror-chokka-recipe-kaddu-kala-chana-sabzi-pumpkin-chickpea-curry', 'The Kumror Chokka Recipe is a classic Bengali dish which is packed with flavours from panch phoran masala and spices and cooked in mustard oil. Kumror means pumpkin in bengali and is a very commonly used vegetable in the Bengali Cuisine. Pumpkin is a very nutritious vegetable, that is low in calories, rich in Vitamin A, potassium, manganese and lots of other essential minerals.', '["2 tablespoons Mustard oil", "1/4 teaspoon Asafoetida (hing)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Kalonji (Onion Nigella Seeds)", "1 Bay leaf (tej patta)", "1 inch Ginger , finely chopped", "2 Green Chillies , slit", "2 Dry Red Chillies", "1/2 cup Kala Chana (Brown Chickpeas) , soaked overnight", "2 Potato (Aloo) , peeled and diced", "500 grams Kaddu (Parangikai/ Pumpkin) , peeled and diced", "1 Tomato , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoons Panch Phoran Masala", "1 teaspoon Salt , or to taste", "1 teaspoon Jaggery"]'::jsonb, ARRAY['tomato', 'salt', 'kalonji (onion nigella seeds)', 'ginger', 'parangikai pumpkin', 'mustard oil', 'mustard seeds', 'bay leaf (tej patta)', 'asafoetida (hing)', 'potato (aloo)', 'jaggery', 'dry red chillies', 'panch phoran masala', 'turmeric powder', 'green chillies', 'kala chana (brown chickpeas)']::text[], '["To begin making the Kumror Chokka Recipe, prep all the ingredients and keep ready.Cook the soaked kala chana/ chickpeas in the pressure cooker along with a little salt and water.", "Add water such that it is just about 1-1/2 inches above the chickpeas.", "Pressure cook for 4 whistles and turn the heat to low.", "Simmer for another 15 minutes and turn off the heat.", "Allow the pressure to release naturally.Once the pressure has released, drain the excess water if any and keep the chickpeas aside.Heat 1 tablespoon mustard oil in a heavy bottomed pan, add potato, sprinkle a little salt and roast on medium heat until it turns light brown.", "Cover the pan for a few minutes to fasten the cooking of the potatoes.Once cooked and roasted, transfer to a bowl and keep this aside.", "In the same pan; add the remaining mustard oil.", "Add the mustard seeds, kalonji, asafoetida, ginger, green chillies, bay leaf and red chillies.", "Stir fry for a few seconds.Add the pumpkin, tomatoes, panch phoran, turmeric powder and salt.", "Give it a stir and cover the pan.", "Cook the pumpkin until it is almost cooked.Towards the last part of the cooking process, stir in the roasted potatoes, chickpeas and jaggery to the pumpkin.Simmer for another 5 minutes so all the flavors get well incorporated into to make a delicious tasting\u00a0Kumror Chokka.Once done, check the taste and adjust the salt and flavours accordingly.", "Turn off the heat and transfer the\u00a0Kumror Chokka\u00a0to a serving bowl and serve hot.Serve Kumror Chokka along with\u00a0Bengali Style Cholar Dal\u00a0and\u00a0Bengali Luchi\u00a0for a wholesome lunch."]'::jsonb, 150, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Kumror_Chokka_Recipe_Pumpkin_Curry_With_Black_Chickpeas__2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/844.Kumror_Chokka_Recipe_Pumpkin_Curry_With_Black_Chickpeas__2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dahi Wale Tinda Ki Sabzi Recipe - Apple Gourd in Yogurt Curry', 'dahi-wale-tinda-ki-sabzi-recipe-apple-gourd-in-yogurt-curry', 'Dahi Wale Tinda Ki Sabzi Recipe is a light and delicious sabzi that takes only 20 minutes to make. It is packed with simple flavours and when cooked along with spices, yogurt and besan it makes it very refreshing and tasty.', '["500 grams Tinda (Apple Gourd) , peeled and diced", "1 tablespoon Mustard oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "2 Green Chillies , slit", "1/4 teaspoon Asafoetida (hing)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Salt , or to taste", "3/4 cup Curd (Dahi / Yogurt)", "1 tablespoon Gram flour (besan)", "1/2 teaspoon Coriander (Dhania) Powder", "1/4 teaspoon Garam masala powder", "1/2 teaspoon Red Chilli powder", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "6 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['tinda (apple gourd)', 'salt', 'mustard oil', 'mustard seeds', 'asafoetida (hing)', 'red chilli powder', 'gram flour (besan)', 'curd', 'coriander (dhania) leaves', 'kasuri methi (dried fenugreek leaves)', 'methi seeds (fenugreek seeds)', 'coriander (dhania) powder', 'turmeric powder', 'green chillies', 'garam masala powder']::text[], '["To begin making Dahi Wale Tinda Sabzi Recipe,\u00a0 prepare all the ingredients and keep them ready.In a heavy bottom pan or kadai, heat mustard oil over medium heat.Add cumin seeds, fenugreek seeds and allow it to crackle for a few seconds.Add the chopped Tinda (apple gourd), green chillies, asafoetida, sprinkle a little salt and turmeric powder and give it a stir.Turn the heat to medium and cover the pan.", "Allow the\u00a0Tinda (apple gourd) to cook until it has become soft.", "It will take about 5 minutes.Give it a stir halfway through and check doneness.", "In a small mixing bowl, add the yogurt, besan, chilli powder, coriander powder, kasuri methi and garam masala.", "Whisk well to combine.", "Add 1/4 cup of water if required and mix well\u00a0Pour the dahi mixture into the tinda\u00a0 and cook till the curry has thickened and dahi wale tinda sabzi has softened and has absorbed all the masalas.", "This will take another 3 to 5 minutes.Once done, check the taste and adjust the salt accordingly.", "Turn off the heat and stir in the coriander leaves and transfer the Dahi Wale Tinda Sabzi to a serving bowl.Serve the Dahi Wale Tinda Sabzi warm along with\u00a0Phulka\u00a0and\u00a0Pindi Chole\u00a0for a wholesome lunch or dinner."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Dahi_Walla_Tinda_Recipe_Indian_Round_gourd_or_Apple_Gourd_Curry__5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/845.Dahi_Walla_Tinda_Recipe_Indian_Round_gourd_or_Apple_Gourd_Curry__5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Ragi Ujju Rotti Recipe', 'karnataka-style-ragi-ujju-rotti-recipe', 'Karnataka Style Ragi Ujju Rotti Recipe is a simple and easy Indian flat bread recipe made with ragi, the super millet. Quick to make with pre-cooked dough and healthy, Ragi Ujju Rotti are a great breakfast and lunch box idea.', '["1 cup Ragi Flour (Finger Millet/ Nagli)", "1 cup Water", "Salt , to taste", "1 teaspoon Oil", "Ghee , roasting", "Rice flour , for dusting"]'::jsonb, ARRAY['salt', 'water', 'ragi flour (finger millet nagli)', 'ghee roasting', 'rice flour', 'sunflower oil']::text[], '["To begin making the Ragi Ujju Rotti Recipe, in a medium sized vessel, bring the water to a boil in a pan with salt and oil.Lower the flame and pour ragi flour into the boiling water from a cup, pour it in the center of the boiling water.Let it get cooked on a low to medium flame untouched for 8-10 minutes without lid.Turn off the flame, take a wooden stick or a wooden spatula, run it under a tap to wet it and then mix the flour and water mixture vigorously until combined.", "This step must be done quickly to avoid lumps.", "This takes about 2 minutes.Cover for a couple of minutes and let it cool until you can handle the mixture.Drop it on an oiled surface and knead well after wetting the hands with water.", "Moist and freshly washed hands are required since the dough is sticky.Knead for about 5-7 minutes to get rid of lumps if any and to smoothen the pre-cooked flour.Roll the mixture into a cylinder and divide them equally.", "This should give you about 4 equal sized balls.Keep them covered at all times.", "Knead each ball for 15-20 seconds and roll it out just like regular ujju rotis using rice flour to dust.", "Just make sure you do it slow and steady since the edges might crack.Roll out all the balls and stack the roti one on top of another on a plate first and then start roasting them.", "Use a little rice flour in-between each, to avoid getting stuck to one another.Heat a Tawa and cook the Ujju Roti just like a chapati by smearing oil /ghee on both sides.", "Cooking will take 1-1.5 minutes on each side.Serve Karnataka Style Ragi Ujju Roti with\u00a0Steamed Vegetable in Coconut and Lentil Curry\u00a0or your favorite chutney like\u00a0Heerekai Sippe Chutney\u00a0or\u00a0Kadale Chutney Recipe."]'::jsonb, 40, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Gauravi_Vinay/Ragi_Ujju_Rotti.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/846.Ragi_Ujju_Rotti.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bajri Ki Roti Recipe', 'bajri-ki-roti-recipe', 'Bajri Ki Roti Recipe is traditional Indian flatbread prepared with black millet flour. Bajra millet is grown certain parts of Northern India. Thickly rolled these rotis are cooked over charcoal in villages, smeared with plenty of freshly churned white butter and served with Lashun Ki Chutney and onions as a staple for farmers in the area. Extremely nutritious and very high on fibre, millets are a wholesome alternative to carbohydrates. You can serve Bajri Ki Roti with Bharva Baingan, Panchmel Dal and Mooli Raita to make a delicious lunch or dinner for the family.', '["2 cups Bajra Flour ( Pearl Millet)", "1/4 cup Whole Wheat Flour", "Salt , to taste", "1 tablespoon Ghee", "Lukewarm Water , to bind the dough"]'::jsonb, ARRAY['s bajra flour', 'pearl millet', 'whole wheat flour', 'salt', 'ghee', 'lukewarm water']::text[], '["To begin making the Bajri Ki Roti Recipe first sift the bajra flour, whole wheat flour and salt together in a deep mixing bowl.Knead the dough well 1/4 cup of lukewarm water at a time, until it comes together in a smooth ball.", "The dough will be similar to what we prepare for Makke Ki Roti.Grease the dough with ghee, cover with a muslin cloth and let rest for 15 minutes.Meanwhile heat a skillet or tava over medium heat.", "Dust your rolling surface with little whole wheat flour.Divide the dough into 6 - 8 equal portions and roll out a portion of the dough into a round and thick roti.", "You can shape the roti by pressing out a circle with your fingers as well.Place the roti over the pre-heated skillet and cook it for a few seconds on one side or till a few bubbles appear on top.Turn over the roti and cook the other side for a few more seconds.", "Lift the roti tongs and roast over the direct flame till brown spots appear on both the sides.Similarly, prepare the remaining Bajra Rotis.", "Serve Bajra Roti immediately smeared with white butter or ghee along with Lahsun Ki Chutney orBharva Baingan,\u00a0Panchmel Dal\u00a0and\u00a0Mooli Raita\u00a0to make a delicious lunch or dinner for the family."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Hina_Gujral/Bajri_Ki_Roti_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/847.Bajri_Ki_Roti_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Beet and Avocado Chapati Recipe', 'beet-and-avocado-chapati-recipe', 'Beet and Avocado Chapati Recipe is a step at bringing the antioxidant properties and minerals of beetroot and healthy smoothness of avocado together. Including Avocado makes these chapatis ultra soft and the fat in it reduces the oil needed for cooking. These super healthy Indian flatbreads are great to be packed for travels and tiffins. Even make them in advance and freeze them in zipping lock covers. Warm them up on a Tawa for 15-30 seconds, add your favorite fillings to wrap. This Beet-Avocado Chapati Recipe makes a great breakfast too.', '["1/2 cup Beetroot , grated", "1/2 Avocado , mashed", "1/4 cup Coriander (Dhania) Leaves , chopped", "1/4 cup Mint Leaves (Pudina) , finely chopped", "2 cups Whole Wheat Flour , more for dusting", "2 tablespoons Sesame seeds (Til seeds)", "1 teaspoon Cumin powder (Jeera)", "3 Green Chilli , ground to paste", "2 teaspoons Ginger , ground to paste", "Salt , to taste", "2 tablespoon Extra Virgin Olive Oil , more for cooking"]'::jsonb, ARRAY['salt', 'wheat flour', 'cumin powder (jeera)', 'coriander (dhania) leaves', 'virgin olive oil', 'green chilli ground paste', 'avocado', 'mint leaves (pudina)', 'beetroot', 'sesame seeds (til seeds)', 'ginger ground paste']::text[], '["To begin making\u00a0Beet and Avocado Chapati Recipe, into a mixing bowl, add Atta, cumin powder, sesame seeds, chili paste and ginger paste, coriander, mint, olive oil and salt,\u00a0grated beetroot and mashed avocado.", "Mix well to combine.", "Bring it all together using your fingers or you can even use a dough hook on your stand mixer on a slow speed.Add some water if necessary and knead to a soft dough.", "Rest the dough for 30 minutes.Knead the dough briefly and divide the dough into equal portions, you should be able to get around 14-16 medium sized chapati.Roll the portions into balls; flatten them with the palm of your hand.Dust the beetroot and avocado dough in flour and roll them out into thin circles to approximately 6 inches in diameter.", "As you roll them out, you can keep dusting the dough in dry flour to prevent sticking when rolling them out.Continue the same process of rolling the dough out with the remaining balls."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Gauravi_Vinay/BeetAvocado_chapathi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/848.BeetAvocado_chapathi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Foxtail Millet Idli Recipe - Healthy Indian Diabetic Idli Recipe', 'foxtail-millet-idli-recipe-healthy-indian-diabetic-idli-recipe', 'Foxtail Millet Idli Recipe is a healthier version of the idli, this recipe is made only with foxtail millets and urad dal.', '["1 cup Foxtail Millet", "1-1/2 cups White Urad Dal (Split)", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "Salt , to taste"]'::jsonb, ARRAY['foxtail millet', 'white urad dal (split)', 'salt', 'methi seeds (fenugreek seeds)']::text[], '["To begin making the Foxtail Millet Idli Recipe, we will wash and soak the millets in water in a separately bowl and urad dal along with methi seeds with enough water in another bowl overnight or keep soaked for at least 8 hours.", "Soak each of them separately.To make the batter, drain the excess water soaked millets and urad dal.Blend the urad dal along with just enough water to make a thick and very smooth batter.Transfer the batter to a large bowl in which we will set it aside for fermentation along with ground millet.Next blend the foxtail millet with just enough water to make a smooth batter.Add this to the urad dal batter, add 2 teaspoons of salt and stir well to combine.Ferment the batter for 5 to 6 hours or overnight.Once the batter is fermented, gently stir and be careful to not release the air pockets.You can make regular sized idlis or also use the mini idli stand.", "Grease the idli molds with a little oil and spoon the foxtail millet idli batter into the molds.Prepare the idli steamer with a little water in the bottom.Place the filled idli racks in the steamer.", "Place the steamer on high heat and steam the idli\u2019s for 10 minutes.After 10 minutes of steaming, turn off the heat.", "Open the steamer and insert a knife or a pick to test whether the idli''s are cooked.", "If nothing sticks then the idlis are perfectly steamed.Now you can remove the Foxtail millet idli from the steamer.", "Have a small bowl filled with water.Dip a spoon in the water and then scoop the ragi idli out starting from the edges.", "Dipping the spoon in water helps in the easy removal of idli from the plates.The wholesome homemade pillow-soft foxtail millet idli is now ready to be served.", "Serve the Foxtail Millet Mini Idli Recipe along with\u00a0Thakkali Vengayam Sambar,\u00a0chutney\u00a0to enjoy your morning breakfast.For an\u00a0Indian Diabetic Meal\u00a0serve this\u00a0Foxtail Millet Idli Recipe\u00a0along with\u00a0Murungakkai Vendhaya Keerai Sambar Recipe\u00a0and\u00a0Horsegram Sesame Chutney Recipe\u00a0for a healthy meal."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Foxtail_Millet_Mini_Idli_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/849.Foxtail_Millet_Mini_Idli_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Olan Recipe with Pumpkin and Black Eyed Beans - Coconut Milk Vegetable Stew', 'kerala-olan-recipe-with-pumpkin-and-black-eyed-beans-coconut-milk-vegetable-stew', 'Kerala Olan Recipe with Pumpkin and Black Eyed Beans is a staple and a simple delicious dish from Kerala that is healthy and nutritious. The Olan recipe is made with yellow pumpkin or the white pumpkin also known as the ash gourd. It’s a mild stew that is delicately spiced with green chillies, flavored with curry leaves and coconut milk. It is also a dish that is served during the Onam Sadya meal of the Onam festival.', '["1 cup Vellai Poosanikai (Ash gourd/White Pumpkin) , peeled and diced", "1 cup Kaddu (Parangikai/ Pumpkin) , peeled and diced", "1/2 cup Black Eyed Beans (Lobia) , soaked for 1 hour", "3 Green Chillies , slit lengthwise", "250 ml Coconut milk , store bought or homemade", "Salt , to taste", "2 sprig Curry leaves", "2 teaspoons Coconut Oil"]'::jsonb, ARRAY['vellai poosanikai', 'ash gourd/white pumpkin', 'kaddu', 'parangikai/ pumpkin', 'black eyed beans', 'lobia', 'reen chillies', 'coconut milk', 'salt', 'curry leaves', 's coconut oil']::text[], '["To begin making the Kerala Olan Recipe with Pumpkin and Black Eyed Beans, prep all the ingredients and keep ready.Soak the black eyed beans in water for one hour and pressure cook the bean along with a little salt for about 15 minutes.", "Once cooked, allow the pressure to release naturally and keep aside.", "Place the the ash gourd and the yellow pumpkin along with a little salt, 1/4 cup of water\u00a0 into the pressure cooker and cook for 2 whistles and turn off the heat.", "Release the pressure immediately, by lifting the weight with fork or running the pressure cooker under cold water.", "This is to ensure that the vegetables remain firm and don''t get over cooked.In a heavy bottomed saucepan; add in the cooked ash gourd, black eyed beans, coconut milk, curry leaves, cooked black eyed beans, green chillies along with salt to taste.Stir well to combine and simmer the Kerala Olan on medium heat for 3 to 4 minutes so the flavours from the curry leaves and green chillies along with the vegetables get well incorporated.", "Adjust gravy to get the right consistency of the Kerala Olan by adding a little water if you want to make it little thinner.", "Make sure the Kerala Olan is not too watery.In the last minute of simmering process, stir in the coconut oil into the Kerala Olan and simmer for a few another minute and turn off the heatTurn off the heat, cover the pan and allow it to rest for about 10 minutes.This brings out the flavors from the curry leaves, green chillies and coconut to become more prominent.Transfer the Kerala Olan with Pumpkin and Black Eyed Beans to a serving bowl.", "Serve the\u00a0Kerala Olan Recipe with Pumpkin and Black Eyed Beans along with\u00a0Steamed Rice, Urulai Kizhangu Roast,\u00a0Elai Vadam\u00a0for a wholesome lunch or dinner."]'::jsonb, 80, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Kerala_Style_Olan_Recipe_-_Black_Eyed_Bean_Pumpkin_Coconut_Milk_Curry_1-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/850.Kerala_Style_Olan_Recipe_-_Black_Eyed_Bean_Pumpkin_Coconut_Milk_Curry_1-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Meen Peera (Kerala Style Fish Recipe With Shredded Coconut)', 'meen-peera-kerala-style-fish-recipe-with-shredded-coconut', 'Meen Peera is a Kerala Style Fish Recipe with shredded coconut. I love Kerala-style fish cooked with coconut and if asked what I’d like for lunch, my first options will be either Kerala Style Fish Curry or this meen peera or meen pattichathu. You can use a variety of fish with bones for this recipe but it works especially well with sardines (also called mathi or chaala). Meen peera is a wonderfully light yet flavourful fish recipe from the God’s Own Country. Can’t wait for my next vacation in Kerala!', '["500 grams Sardine fish", "1 cup Fresh coconut , grated", "10 Shallots", "3 Green Chillies", "1/4 tablespoon Dry Red Chilli , crushed", "2 inch Ginger", "3 clove Garlic", "1/4 teaspoon Methi Powder (Fenugreek Powder)", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coconut Oil , adjustable", "1 sprig Curry leaves", "1 Kokum (Malabar Tamarind) , soaked, for cleaning fish", "2 Kokum (Malabar Tamarind) , for the curry", "Salt , to taste"]'::jsonb, ARRAY['salt', 'kokum (malabar tamarind) the curry', 'ginger', 'coconut', 'methi powder (fenugreek powder)', 'kokum (malabar tamarind)', 'cloves garlic', 'dry red chilli', 'curry leaves', 'coconut oil', 'turmeric powder', 'green chillies', 'sardine fish']::text[], '["To prepare Meen Peera (Kerala Style Fish Recipe with shredded coconut), wash and clean the sardines and marinate it with 1 small piece of kudampuli and salt.", "Keep aside for 10 minutes.Throw away the kudampuli and wash the fish under running water till cleaned well.", "Drain all the water.", "Cut each fish into 3 pieces for better incorporation of flavor.Add the cleaned sardines into a meen chatti (earthenware) or a pan.", "Keep aside.Crush or coarsely grind (if you are using a mixer grinder for this process, just pulse it 1 or 2 times till you get a coarsely crushed mixture) together coconut, ginger, garlic, green chilies, shallots, 2 to 3 curry leaves and crushed dry red chili.Add the coconut mix and 2 big pieces of kudampuli into the sardines and mix well. (I used my hands, but you could always use a wooden spoon to do this)Add salt, coconut oil, fenugreek powder, turmeric powder and the rest of the curry leaves and mix well.Now add a little water, just enough to cover the fish.Bring the mixture together with a wooden spoon and press down firmly.Cover with a lid and cook on a high flame.", "When the mixture is boiling, lower the flame and cook for about 5-6 minutes.Now continue to cook the fish with the lid slightly open.", "Saut\u00e9 occasionally and cook till water has reduced.Open the lid completely and continue to cook the fish a medium high flame until most of the liquid has dried up. (Take care not to burn the dish).Serve Meen Peera (Kerala Style Fish Recipe with shredded coconut) with\u00a0steamed rice\u00a0and\u00a0Whole wheat\u00a0lachha\u00a0paratha\u00a0for a wholesome lunch."]'::jsonb, 40, 'Kerala', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Donna_George/meen_peera_recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/851.meen_peera_recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gujarati Methi Thepla- Spiced Indian Flat Bread with Fenugreek Leaves', 'gujarati-methi-thepla-spiced-indian-flat-bread-with-fenugreek-leaves', 'Gujarati Methi Thepla recipe is one of the many comfort foods to Gujarati’s. If you are on a long distance train or even on a trekking trip and you spot a Gujarati, you will definitely find them with Theplas.', '["2 cups Whole Wheat Flour", "1/2 cup Methi Leaves (Fenugreek Leaves) , finely chopped", "1/4 cup Curd (Dahi / Yogurt)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder , (optional)", "1/4 teaspoon Asafoetida (hing)", "Oil , for cooking the thepla", "Salt , to taste"]'::jsonb, ARRAY['s whole wheat flour', 'methi leaves', 'fenugreek leaves', 'curd', 'dahi / yogurt', 'turmeric powder', 'haldi', 'red chilli powder', 'asafoetida', 'hing', 'oil', 'salt']::text[], '["To begin making the Gujarati Methi Thepla Recipe, in a large bowl combine the\u00a0whole wheat flour,\u00a0cumin seeds,\u00a0turmeric powder,\u00a0chilli powder, asafoetida powder, salt and\u00a0fenugreek leaves.Add the yogurt to the flour mixture and knead into a firm smooth dough adding little water only if required.", "Finally add\u00a0 two tablespoons of oil to coat the dough and knead until it is firm and smooth.Cover and allow the dough to rest for 15 minutes.", "Preheat the iron skillet on medium heat.", "Divide the thepla dough into equal portions.Roll the thepla portions into balls; flatten them with the palm of your hand.Dust the thepla dough in flour and roll them out into thin circles to approximately 6 inches in diameter.", "As you roll them out, you can keep dusting the dough in dry flour to prevent sticking when rolling them out.Continue the same process of rolling the thepla dough out with the remaining balls.", "It is ideal when you can roll out the all portions of thepla dough before you start cooking them."]'::jsonb, 45, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Methi_Thepla_Recipe_Soft_Gujarati_Thepla_11_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/852.Methi_Thepla_Recipe_Soft_Gujarati_Thepla_11_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mutton Kola Urundai Recipe - Chettinad Mutton Keema Balls', 'mutton-kola-urundai-recipe-chettinad-mutton-keema-balls', 'Mutton Kola Urundai Recipe is a traditional Chettinad recipe. Mutton keema is pre cooked and then mixed along with a kola masala. This kola masala is a spicy masala, made by grinding together whole spices along with fresh coriander and curry leaves and ginger-garlic and green chilli as well.', '["500 grams Mutton Kheema", "1/2 cup Roasted Gram Dal (Pottukadalai)", "6 cloves Garlic", "2 inch Ginger , roughly chopped", "1 Onion , roughly chopped", "2 sprig Curry leaves , roughly chopped", "2 Green Chillies , roughly chopped", "1/4 cup Fresh coconut , grated", "1 teaspoon Red Chilli powder", "1 inch Cinnamon Stick (Dalchini)", "1 teaspoon Coriander (Dhania) Seeds", "3 Cloves (Laung)", "3 Cardamom (Elaichi) Pods/Seeds", "1 tablespoon Poppy seeds", "1 teaspoon Fennel seeds (Saunf)", "1/4 cup Coriander (Dhania) Leaves , loosely packed", "Salt , to taste"]'::jsonb, ARRAY['s mutton kheema', 'roasted gram dal', 'pottukadalai', 's garlic', 'ginger', 'onion', 'curry leaves', 'reen chillies', 'fresh coconut', 'red chilli powder', 'cinnamon stick', 'dalchini', 'coriander', 'dhania', 'laung', 'cardamom', 'elaichi', 'poppy seeds', 'fennel seeds', 'saunf', 'salt']::text[], '["To begin making the Mutton Kola Urundai Recipe, in a mixer jar, add the roasted gram dal and grind it to a fine powder.", "Transfer to a bowl and set aside."]'::jsonb, 50, 'Chettinad', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Articles/Mutton_Kola_Urundai_Recipe_Chettinad_Mutton_Keema_Balls_5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/853.Mutton_Kola_Urundai_Recipe_Chettinad_Mutton_Keema_Balls_5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Puli Koozh Recipe - Rice Flour Porridge In Tamarind', 'puli-koozh-recipe-rice-flour-porridge-in-tamarind', 'Puli Koozh Recipe is traditional south indian recipe that can be served as breakfast or evening tiffin. It is nothing but the raw rice flour or batter cooked in spiced tamarind water. Puli Koozh Recipe (Rice Flour Porridge In Tamarind) is a delicious recipe that can be served as porridge while it is hot, and served as bits of fudge once cooled. Both ways will tastes heavenly.', '["1 cup Idli Rice", "1 tablespoon Tamarind", "3 tablespoons Sesame (Gingelly) Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 tablespoons Chana dal (Bengal Gram Dal)", "2 tablespoons White Urad Dal (Split)", "Curry leaves , a few", "3 Dry Red Chillies", "1 teaspoon Asafoetida (hing)", "1 teaspoon Turmeric powder (Haldi)", "3-1/2 cups Water"]'::jsonb, ARRAY['mustard seeds', 'asafoetida (hing)', 'idli rice', 'sesame (gingelly) oil', 'water', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'tamarind', 'turmeric powder', 'chana dal (bengal gram dal)']::text[], '["To prepare Puli Koozh Recipe (Rice Flour Porridge In Tamarind), wash and soak the rice in water for 5 to 6 hours.Then grind into a smooth paste by adding little water.", "Keep it aside for minimum 3 to 4 hours.Take the juice from tamarind by adding 1/2 cup of water.In a heavy bottomed pan preferably non stick, add oil and add mustard seeds and let it splutter.Then break and add the red chillies and fry for few seconds.", "Then add the channa dal and urad dal and let it roast for few minutes.", "Add curry leaves and saut\u00e9 for a bit.Once they are crisp, add the tamarind juice and water.Add the turmeric powder and salt.", "Mix well.Once the water comes to rolling boil, reduce heat and add the ground rice paste and mix well.Stir continuously to avoid sticking at the bottom and lump free.It will starts to thick.", "Check the salt and add more in necessary.After 8 to 10 minutes, it will form a thick mass and starts separating from the pan.Remove from heat and serve Puli Koozh Recipe (Rice Flour Porridge In Tamarind) hot like porridge.Or Grease a plate with oil and pour the prepared koozh and spread using a spatula and allow to cool like a savoury halwa.If spread on a plate, pour a teaspoon of sesame oil on the top and spread with a spoon to avoid drying on the top layer.", "Let it cool for 30 minutes and then cut in to pieces.Serve Puli Koozh Recipe (Rice Flour Porridge In Tamarind) for a morning breakfast or snack."]'::jsonb, 25, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/20-jan/Puli_Koozh_Recipe_Rice_Flour_Porridge_In_Tamarind-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/854.Puli_Koozh_Recipe_Rice_Flour_Porridge_In_Tamarind-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bihari Shakarkand Bhujiya Recipe - Spicy Sweet Potato Sabzi', 'bihari-shakarkand-bhujiya-recipe-spicy-sweet-potato-sabzi', 'Bihari Shakarkand Bhujiya Recipe is a simple delicious recipe prepared with sweet potatoes, regular potatoes or for that matter arbi as well. This sweet potato is tossed in a kadai with cumin and green chillies along with the touch of turmeric powder and salt. They typically make these Aloo Bhujia really crispy on the outer and soft on the inner, making it like an Indian French fry, which is not deep fried.', '["2 Sweet Potatoes , peeled and cut into thin strips", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin seeds (Jeera)", "2 Green Chillies , slit into halves", "1-1/2 tablespoon Mustard oil", "Salt , to taste"]'::jsonb, ARRAY['sweet potatoes', 'turmeric powder', 'haldi', 'cumin seeds', 'jeera', 'reen chillies', 'mustard oil', 'salt']::text[], '["To begin making the Bihari Shakarkand Bhujiya recipe, wash and peel sweet potatoes.And cut them into one inch long stick pieces similar to the one for finger chips.", "In a non-stick wok, add mustard oil; Once the oil is hot, add cumin seeds.", "Allow it to splutter.Now, add green chilies and saute it.", "Stir in the chopped potatoes and turmeric powder.", "Season it with salt.Reduce the flame.", "Cook until the sweet potatoes are cooked completely.", "Towards the end, when the sweet potatoes have almost cooked, open the lid and allow it to become crispy.At this stage you can optionally add more mustard oil and then sprinkle some more salt.", "Ensure you keep stirring occasionally so the\u00a0Bihari\u00a0Shakarkand Bhujiya gets cooked from all the sides.Once done, turn off the heat and transfer the Bihari\u00a0Shakarkand Bhujiya to serving bowl.Serve the Bihari\u00a0Shakarkand Bhujiya and serve with Whole Wheat Lachha parathas\u00a0and\u00a0Boondi raita\u00a0for a weekday meal."]'::jsonb, 20, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Bihari_Shakarkand_Bhujia_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/855.Bihari_Shakarkand_Bhujia_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kongunadu Style Arisi Paruppu Sadam Recipe', 'kongunadu-style-arisi-paruppu-sadam-recipe', 'Kongunadu Style Arisi Paruppu Sadam Recipe, a good combination of toor dal and rice flavoured with curry leaves, mustard seeds and most importantly sambar powder that gives it the extra flavour to the whole dish. This dish is considered as one of the signature recipe from Kongunadu region. Kongunadu is a part of Tamil Nadu Cuisine that is majorly covers the western part of the state. The rice is a good way to add in protein into your diet by combining dal and rice together.', '["1 cup Rice", "1 cup Arhar dal (Split Toor Dal)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Fennel seeds (Saunf)", "1 sprig Curry leaves", "2 Dry Red Chilli", "1 Onion , chopped", "1 Tomato , chopped", "4 cloves Garlic , pound", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoon Sambar Powder", "Salt , to taste", "Oil , or ghee", "2 sprig Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['rice', 'arhar dal', 'split toor dal', 'cumin seeds', 'jeera', 'fennel seeds', 'saunf', 'curry leaves', 'dry red chilli', 'onion', 'tomato', 's garlic', 'coriander powder', 'dhania', 'red chilli powder', 'turmeric powder', 'haldi', 'sambar powder', 'salt', 'oil', 'coriander']::text[], '["To begin making the Kongunadu Style Arisi Paruppu Sadam Recipe, wash the rice and dal together.", "Soak the dal in water for at least 30 minutes.Heat a pressure cooker, add ghee or oil lower the flame, add cumin seeds and fennel seeds.", "Allow it to sizzle for few seconds.Add curry leaves and allow it crackle for few seconds.", "Add dry red chillies and saute for few seconds.Add pound garlic and saute till they soften.", "Add onions and saut\u00e9 till they turn translucent.Once the onions are caramelized and add tomatoes and sprinkle little salt and cook till they turn mushy.Add all 4 spice powders, stir and mix it well.", "Add soaked rice and dal after draining the water.", "Mix the rice and dal until the masala coats evenly on it.", "Add about 5 cups of water and salt to taste and pressure cook for at least 3 whistles.Once the pressure releases, open the lid and give it a mix.", "Sprinkle some chopped coriander leaves on top and serve hot.Serve the Kongunadu Style Arisi Paruppu Sadam Recipe along with\u00a0Pavakkai Poriyal Recipe\u00a0and\u00a0Puli kuzhambu\u00a0by the side to make it a complete meal."]'::jsonb, 60, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanskitchen.com/Kongunadu_Style_Arisi_Paruppu_Sadam_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/856.Kongunadu_Style_Arisi_Paruppu_Sadam_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Jowar Atta Pyaz Thepla Recipe – Sorghum Wheat Onion Thepla', 'jowar-atta-pyaz-thepla-recipe-sorghum-wheat-onion-thepla', 'Jowar Atta Pyaz Thepla Recipe is a delicious and wholesome thepla that you can make at home. It is packed with the goodness of jowar flour and the onions adds to the taste of this thepla.', '["1 cup Whole Wheat Flour", "1-1/2 cup Jowar Flour (Sorghum)", "2 Onion , finely chopped", "1 Green Chilli , finely chopped", "1 teaspoon Coriander Powder (Dhania)", "2 teaspoon Garam masala powder", "2 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Oil"]'::jsonb, ARRAY['salt', 'wheat flour', 'green chilli', 'amchur (dry mango powder)', 'jowar flour (sorghum)', 'onion', 'coriander powder', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Jowar Atta Pyaz Thepla Recipe,\u00a0in a large mixing bowl add chopped onions, green chilli, coriander powder, garam masala, amchur and turmeric, salt, whole wheat flour and the jowar flour.Add water little at a time and form a firm dough which is not sticky.", "Knead it well to form a dough.", "Rest the thepla dough for at least 10 minutes and shape them into medium sized balls.Dust it with wheat flour and roll the Jowar Atta Pyaz Thepla dough gently to make a thin circular thepla.The diameter of the Jowar Atta Pyaz thepla depends on how thin or thick you want it to be.", "Repeat the same process with the remaining dough portions.Preheat the skillet on medium flame.", "Place the rolled Jowar Atta Pyaz thepla gently on the tawa and cook on both sides, drizzle oil or ghee and cook till the thepla have brown spots on either side.Once done, stack the theplas one over the other and serve hot.Serve the\u00a0Jowar Atta Pyaz Thepla Recipe\u00a0along with\u00a0Dal Palak,\u00a0Aloo Parwal Sabzi,\u00a0\u00a0Gor Keri Pickle\u00a0,\u00a0Palak Raita Recipe\u00a0for a wholesome lunch or dinner."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/April-18/Jowar_Atta_Pyaz_Thepla_Jowar_Onion_Paratha-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/857.Jowar_Atta_Pyaz_Thepla_Jowar_Onion_Paratha-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Potala Rasa Recipe (Oriya Style Parval Sabzi)', 'potala-rasa-recipe-oriya-style-parval-sabzi', 'Potala as you all know is the Odia name for Parwal or Pointed Gourd and Rasa means gravy. In this recipe, Parwal is cooked with coconut, poppy seed and cashew nut gravy and all spices to give the dish a rich feel. This curry is mainly made during religious festivals when the uses of onion and garlic food is prohibited. The stuffing makes it irresistible for kids to say no to this.', '["8 Pointed gourd (Parval)", "1 Bay leaf (tej patta)", "1/4 teaspoon Cumin seeds (Jeera) , for tempering", "1 cup Homemade tomato puree", "1/2 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Red Chilli powder", "15 Cashew nuts , soaked and ground to paste", "Salt , to taste", "Oil , for cooking", "To be ground to paste", "1 inch Ginger , finely chopped", "3 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "4 Cloves (Laung)", "2 Green Chillies , finely chopped", "1/4 cup Fresh coconut , grated", "2 teaspoons Poppy seeds", "1 cup Chenna (Homemade Cottage Cheese)", "1 tablespoon Coriander (Dhania) Leaves , finely chopped", "1 teaspoon Whole Black Peppercorns , freshly ground", "1 Green Chilli , finely chopped", "1 tablespoon Sultana Raisins , roughly chopped", "Salt , to taste", "Coriander (Dhania) Leaves , a bunch, chopped"]'::jsonb, ARRAY['tomato', 'coriander (dhania) leaves', 'black peppercorns ground', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies', 'chenna', 'sunflower oil', 'salt', 'coriander (dhania)', 'green chilli', 'cardamom (elaichi) podsseeds', 'raisins', 'cashew nuts ground paste', 'pointed gourd (parval)', 'coconut', 'red chilli powder', 'ginger', 'bay leaf (tej patta)', 'cinnamon stick (dalchini)', 'poppy seeds', 'cloves (laung)']::text[], '["To begin making the Potala Rasa recipe, prep all the ingredients and keep it ready for cooking.Blend the ingredients to be made into a paste in a mixer grinder.", "Add little water if required to make a paste.Wash and clean the parwals.", "Scrape the whole skin of the parwals with a knife.", "Cut one tip a little, right from the edge and the other tip a little bigger, so that we can scoop out the seeds from inside.", "Rub with a pinch of salt and keep aside for 5-10 minutes.Heat 1 tablespoon oil in a wok/kadhai, fry the parwals or potals until lightly brown from all sides, keep aside.Prepare the parwal stuffing by mixing together crumbled paneer, green chillies, raisins, black pepper powder, salt and coriander leaves and keep aside.When parwals are cooled, stuff each one with the prepared filling.", "Carefully fill the parwals and try not to break them apart.", "Keep aside.To prepare the gravy, in the same pan, add a little more oil and once hot, add the bay leaf and the cumin seeds and once it starts to splutter add the ground masala paste.", "Saute until the raw smell goes away.", "This will take about 4 to 5 minutes on medium heat.Add the turmeric powder, salt, chili powder and saute in the masala for a few more seconds.Stir in the tomato puree, cashew paste\u00a0and give is good stir to and a brisk boil.", "Add the about 1 cup of water to make it a gravy like consistency.", "Check the salt and spices and adjust to suit your taste.Place the stuffed parwal into the tomato gravy, turn the heat to low, cover the pan and simmer for a few minutes.Once done, turn off the heat, stir in the coriander leaves and serve.Serve Potala Rasa along with\u00a0Tawa Paratha,\u00a0Phulka\u00a0or Steamed Rice for a delicious weekday lunch or dinner."]'::jsonb, 80, 'Oriya', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Alaka_Jena/Potala_Rasa.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/858.Potala_Rasa.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Homemade Easy Gulab Jamun Recipe - Delicious & Tasty', 'homemade-easy-gulab-jamun-recipe-delicious-tasty', 'This Gulab Jamun Recipe is going to be a keeper with a Royal delicious taste. It is are packed with flavours from the light gulab jal and saffron giving it a royal touch.', '["250 grams Milk Powder", "120 grams All Purpose Flour (Maida)", "1/2 teaspoon Cardamom Powder (Elaichi)", "1/4 teaspoon Baking soda", "200 ml Fresh cream", "2 tablespoons Ghee", "Oil , for deep frying", "400 grams Sugar", "600 ml Water", "2 tablespoons Rose water", "1/4 teaspoon Saffron strands"]'::jsonb, ARRAY['ghee', 'saffron strands', 'rose water', 'water', 'baking soda', 'sugar', 'cardamom powder (elaichi)', 'flour (maida)', 'milk powder', 'sunflower oil']::text[], '["To begin making the Gulab Jamun\u00a0Recipe, get all the ingredients ready.Preheat the oil for deep frying.", "Into a large mixing bowl, add all the dry ingredients - milk powder, maida, sugar, soda and cardamom powder.", "Add the cream and mix well to combine until you get a dough like consistency.The Gulab Jamun mixture will be a little sticky and this is the nature of it, as the milk powder has sweet which will cause this.Grease your fingers with oil and start shaping the Gulab Jamuns into tiny balls little larger than an Indian gooseberry / amla.", "Once you have shaped all the Gulab Jamun dough, we will now begin to start deep frying.Slide the Gulab Jamuns into the pre heated oil and deep fry on medium heat until all the jamuns are fried until golden brown.", "It will take close to 5 minutes to fry a batch of jamuns over medium heat.Once fried strain them into kitchen paper towels and keep aside.Parallely, into a large wide bowl heat the water and sugar.", "Allow the sugar to dissolve completely.Once the sugar dissolves, add the rose water and a large pinch of saffron.", "Give the Gulab Jal water a brisk boil for about 2 to 3 minutes and turn off the heat.Add the fried Gulab Jamuns into the hot gulab jal water and allow it to soak for about 2 hours.", "The Gulab Jamuns will expand and soak in the water and fluff up.So ensure you keep some room in the gulab jal water bowl for this expansion.", "If required soak it in two bowls.Cover the pan while the gulab jamun us soaking so it becomes soft.", "Half way through the soaking process, turn the Gulab Jamuns around so all the sides get evenly soaked.Once soaked, the Gulab Jamuns are ready to be served.Serve the Gulab Jamuns hot or cold as a dessert after a delicious meal."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Milk_Powder_Gulab_Jamun_Recipe_Video_5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/859.Milk_Powder_Gulab_Jamun_Recipe_Video_5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gujarati Sev Khamani  Recipe - Amiri Khaman | Crumbled Khaman Dhokla', 'gujarati-sev-khamani-recipe-amiri-khaman-crumbled-khaman-dhokla', 'Sev Khamani also known as Amiri Khaman is a classic Gujarati dish that are traditionally made from lentil cakes that are steamed and crumbled. The Amiri Khaman can also be made from leftover dhokla and gujarati’s are known for their love for food and also know how to reuse the leftovers to make tasty dishes like this simple Khamani.', '["1 teaspoon Oil", "1 teaspoon Sesame seeds (Til seeds)", "15 Khaman dhokla , pieces", "1 sprig Curry leaves , roughly torn", "2 Green Chillies , thinly sliced", "1 Onion , finely chopped", "1/2 cup Sev", "1/4 cup Coriander (Dhania) Leaves , finely chopped", "1/4 cup Fresh coconut , grated", "Salt , to taste"]'::jsonb, ARRAY['oil', 'sesame seeds', 'til seeds', 'khaman dhokla', 'curry leaves', 'reen chillies', 'onion', 'sev', 'coriander', 'dhania', 'fresh coconut', 'salt']::text[], '["To begin making the Amiri Khaman Recipe, in a large bowl, crumble the Khaman Dhokla\u00a0into coarse crumbs using your fingers.", "Heat oil in a pan; add the\u00a0 sesame seeds and allow them to crackle.", "Stir in the curry leaves, green chillies and saut\u00e9 until tender and the green chillies are slightly soft.Stir in the crumbled\u00a0Khaman Dhokla, salt to the above seasoning and stir gently.Turn off the heat and stir in the grated coconut, chopped onions, chopped coriander leaves, sev and pomegranate and serve hot.", "Transfer the Amiri Khaman | Sev Khamani to a serving dish and serve immediately.", "Note:\u00a0Khaman Dhokla\u00a0will already have some salt in it; so use caution in adding salt to the Amiri KhamanServe\u00a0Amiri Khaman Recipe along with\u00a0Masala Chai Recipe - Indian Spiced Tea\u00a0for a wholesome breakfast."]'::jsonb, 50, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/sev_khamani_recipe_video_Amiri_Khaman_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/860.sev_khamani_recipe_video_Amiri_Khaman_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gujarati Sev Tameta Nu Shaak | Sev Tamatar Ki Sabzi Recipe', 'gujarati-sev-tameta-nu-shaak-sev-tamatar-ki-sabzi-recipe', 'Sev Tamatar Ki Sabzi also known Sev Tameta Nu Shaak in Gujarati is a delicious recipe made from sev cooked in a tangy tomato gravy. This sabzi is made popularly during the festival of paryushan parva when roots and other vegetables are not included in the diet.', '["6 Tomatoes , halved", "1 tablespoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves , finely chopped", "2 Green Chilli , slit", "1 inch Ginger , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 tablespoon Jaggery", "1/2 cup Sev", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'green chilli', 'sev', 'mustard seeds', 'ghee', 'jaggery', 'red chilli powder', 'curry leaves', 'cumin seeds (jeera)', 'turmeric powder']::text[], '["To begin making the Sev Tamatar Ki Sabzi Recipe / Sev Tameta Nu Shaak, prepare all the ingredients and keep ready.Place the tomatoes in the pressure cooker along with 2 tablespoons of water and pressure cook for 2 whistles and turn off the heat.", "Allow the pressure to release naturally.Once the pressure releases, transfer to a wide plate and allow the tomatoes to cool.", "Peel the skin off the tomatoes and finely chop them and keep aside.Heat oil in a\u00a0saucepan\u00a0on\u00a0medium heat; add the mustard seeds, cumin seeds, curry leaves, green chillies and ginger and allow them to crackle and saute for a few seconds.Add cooked tomatoes, turmeric powder, red chilli powder, jaggery and salt.", "Saut\u00e9 until all the ingredients are well combined.Give the Sev Tameta nu shaak a brisk boil for 3 to 4 minutes.", "Once done, add half of the sev, along with 1/4 cup of water and bring it to a boil and turn off the heat.Check the taste of the Sev Tameta Nu Shaak and adjust the salt and spices accordingly.Once done, stir in the chopped coriander leaves and serve hot.Serve the delicious Jain Style Sev Tameta Nu Shaak along with freshly made\u00a0Gujarati Thepla\u00a0for lunch or dinner."]'::jsonb, 25, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Gujarati_Sev_Tamatar_Nu_Shaak_Recipe_video_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/861.Gujarati_Sev_Tamatar_Nu_Shaak_Recipe_video_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bharwa Lauki Recipe - Stuffed Bottle Gourd', 'bharwa-lauki-recipe-stuffed-bottle-gourd', 'Bharwa Lauki is a stuffed gravy dish which is prepared with the combination of creamy gravy and stuffed paneer bhurji. You can give this recipe a try as it is an easy way to make your family eat a regular vegetable with a twist and this recipe will definitely change your view to Bottle gourd. Who knows it may beat any of your favourite recipes?', '["1 Bottle gourd (lauki)", "2 Onions , chopped", "2 Tomatoes , finely chopped", "1 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin seeds (Jeera)", "4 tablespoon Oil", "1 tablespoon Sugar", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "Salt , to taste", "3 sprig Coriander (Dhania) Leaves , finely chopped", "1 cup Paneer (Homemade Cottage Cheese) , crumbled", "1 teaspoon Cumin seeds (Jeera) , cumin seeds", "1 Onion , finely chopped", "1/2 Green Bell Pepper (Capsicum) , finely chopped", "1 Green Chilli , finely chopped", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli flakes", "Salt , to taste", "1 teaspoon Fresh cream"]'::jsonb, ARRAY['bottle gourd', 'lauki', 'onions', 'tomatoes', 'red chilli powder', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'cumin seeds', 'jeera', 'oil', 'sugar', 'kasuri methi', 'dried fenugreek leaves', 'salt', 'coriander', 'paneer', 'homemade cottage cheese', 'onion', 'reen bell pepper', 'capsicum', 'reen chilli', 'red chilli flakes', 'fresh cream']::text[], '["To begin making the Bharwa Lauki Recipe, we will first prepare the stuffing of Paneer Bhurji.In a deep pan, heat a tablespoon of oil and add cumin seeds and let it crackle.", "Now add the chopped onions and sauce it till they become soft and transparent.Once it is done, add the capsicum, crumbled paneer, salt, coriander powder, red chilly flakes and mix it properly.", "Cook it for 1-2 minutes more and set it aside to cool down.The next step is to make the stuffed Lauki.Firstly, peel the bottle gourd and boil it in a large vessel with a tablespoon of salt and let it boil till the gourd is properly cooked.", "The vessel should be big enough to hold the full gourd.Now let the gourd cool down.", "Once it is done, cut the ends of gourds to remove the pith inside it using a long spoon or a fork.", "Heat 2 tablespoon oil on a pan and place the hollow gourd on it.", "Cook it till the skins turns brown and it crisps up.", "Keep turning the gourd until it is golden brown from all the sides.Now fill the paneer bhurji in the bottle gourd and slice it into 1 inch thick slices.", "After cutting it into thick slices, place the slices back on the pan to cook.", "Cook them till the both the sides turn brown.The final step is to make the creamy gravy.Heat 1 tablespoon of oil in a pan and add cumin seeds.", "Once they crackle, add the chopped onion till they become soft.Now add the chopped tomatoes and sauce till they are properly cooked.", "Once it is done, add the turmeric powder, coriander powder, salt to taste, the leftover bhurji and the pith of the gourd that you \u00a0have kept aside.", "Cook them properly.Once their starts separating, use a hand blender and make a paste of the mixture in the pan itself.", "Now add 1 cup of water and let it cook for a couple of minutes.Add sugar, kasoori methi and slices of the gourd and boil it till the gravy thicken and garnish it with the chopped coriander leaves and cream.Serve the\u00a0Bharwa Lauki\u00a0along with\u00a0Lahsuni Palak Dal,\u00a0Palak Raita\u00a0and\u00a0Phulka\u00a0for an everyday meal."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuri_Aggarwal/Bharwa_Lauki__Stuffed_Bottle_Gourd.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/862.Bharwa_Lauki__Stuffed_Bottle_Gourd.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bhey Vangan Saag Recipe - Sindhi Style Lotus Stem Spinach Brinjal Sabzi', 'bhey-vangan-saag-recipe-sindhi-style-lotus-stem-spinach-brinjal-sabzi', 'The Bhey Vangan Saag is a traditional Sindhi dish with lotus stem as the star ingredient. The dish is a medley of vegetables that include Bhey (lotus stem), Vaangan (brinjal), Saag (palak) and Aloo (potatoes), and some Indian spices which makes it a very nutritious meal in itself.', '["1 cup Spinach Leaves (Palak) , washed and finely chopped", "2 Brinjal (Baingan / Eggplant) , cut into wedges", "1 Lotus Stem , sliced", "1 Potato (Aloo) , cut into wedges", "1 inch Ginger", "4 Tomatoes", "2 Green Chilli", "Salt , to taste", "2 teaspoons Red Chilli powder", "3 teaspoons Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "1 teaspoon Cumin powder (Jeera)", "1-1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "2 tablespoons Oil", "2 teaspoons Cumin seeds (Jeera)"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'ginger', 'green chilli', 'coriander powder', 'brinjal (baingan eggsplant)', 'potato (aloo)', 'red chilli powder', 'cumin seeds (jeera)', 'lotus stem', 'turmeric powder', 'spinach leaves (palak)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Bhey Vangan Saag, thoroughly wash the lotus stem and cut into slices.Pressure cook the lotus stem slices with required water for 7-8 whistles.", "Turn off the flame and allow the pressure to release naturally.", "Drain the water and set the lotus stems aside.In a mixer-jar, add tomatoes, ginger, green chilies and grind into a puree.Heat a pressure cooker on medium flame, add oil.", "Now add the cumin seeds, potato wedges, brinjals wedges and saute for about 5 minutes stirring continuously.Once the vegetables begin to soften, add in the dry masalas including red chilli powder, coriander powder, garam masala powder, cumin powder, turmeric powder and salt.", "Mix well.Once the masalas have coated the vegetables, mix in the tomato puree and continue to cook for about 5 minutes.Finally, add in the chopped spinach, 1/2 cup water and close the pressure cooker.Pressure cook for 4 whistles and turn off the heat.", "Allow the pressure to release naturally.Transfer the dish to a serving bowl and Bhey Vangan Saag is ready to be servedServe\u00a0Bheey Vangan Saag\u00a0along with\u00a0Phulka\u00a0and\u00a0Panchmel Dal\u00a0for a weekday meal.", "You can also pack it in your lunch box."]'::jsonb, 60, 'Sindhi', 'veg', 'https://www.archanaskitchen.com/images/Sindhi__Style_Bhey_Vangan_SAag_Recipe_Lotus_Stem_Spinach_Brinjal_POtato_Curry-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/863.Sindhi__Style_Bhey_Vangan_SAag_Recipe_Lotus_Stem_Spinach_Brinjal_POtato_Curry-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Cucumber Mor Kuzhambu Recipe (Cucumber Curry)', 'cucumber-mor-kuzhambu-recipe-cucumber-curry', 'Cucumber Mor Kuzhambu is a delectable curry usually served with steamed rice. Cucumber pieces are cooked till soft and then mixed with a coconut-mustard-curd gravy. This simple curry is very flavourful and uses ingredients easily available in the pantry. This is a great way to use up leftover cucumbers lurking in the refrigerator. You can alternatively use white pumpkin.', '["3 to 4 Cucumber , peeled and chopped", "1/2 cup Fresh coconut , scrapped", "1 inch Ginger , chopped", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "3 to 4 Green Chillies , chopped", "1/4 teaspoon Turmeric powder (Haldi)", "5 to 6 sprig Coriander (Dhania) Leaves", "2 to 3 tablespoons Hung Curd (Greek Yogurt)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'coconut scrapped', 'ginger', 'hung curd (greek yogurt)', 'mustard seeds', 'coriander (dhania) leaves', 'cucumber', 'turmeric powder', 'green chillies']::text[], '["To begin making the Cucumber Mor Kuzhambu recipe, firstly add the cucumber pieces along with 1/2 cup water and salt to a saucepan.", "Cook covered till the cucumber becomes just tender.Grind together the coconut, ginger, chillies, mustard, coriander, turmeric in a blender to a fine paste.", "Add little water if required to make a fine paste.Add this coconut paste to the cucumber.", "Cook on low heat for 2 to 3 minutes.", "Adjust water and salt if required.Add the curd and mix.Serve the Cucumber Mor Kuzhambu with steamed rice and\u00a0Keerai Sambar\u00a0for a comforting weekday meal."]'::jsonb, 35, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Cucumber_Morkolumb_Cucumber_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/864.Cucumber_Morkolumb_Cucumber_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Dahi Baingan Recipe', 'kashmiri-dahi-baingan-recipe', 'Kashmiri Dahi Baingan Recipe is a lip smacking dish where the eggplant is diced and cooked in a simple yogurt gravy, which ideally is the Kashmiri style of cooking.', '["500 grams Brinjal (Baingan / Eggplant) , cut into 1 inch pieces", "3 tablespoon Mustard oil", "2 cups Curd (Dahi / Yogurt) , whisked well until smooth", "2 teaspoons Dry ginger powder", "2 teaspoons Kashmiri Red Chilli Powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Fennel seeds (Saunf) , coarsely pounded", "4 Cardamom (Elaichi) Pods/Seeds", "1/4 teaspoon SSP Asafoetida (Hing)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'curd until smooth', 'kashmiri red chilli powder', 'mustard oil', 'cardamom (elaichi) podsseeds', 'brinjal (baingan eggsplant)', 'fennel seeds (saunf)', 'asafoetida (hing)', 'dry ginger powder', 'turmeric powder']::text[], '["To begin making the Kashmiri Dahi Baingan Recipe, place the cut eggplant/ brinjal pieces in a bowl of salted water for about 10 minutes.Add 1 tablespoon of mustard oil into a preheated pan.", "Drain the baingan from its water and add the drained baingan to the pan.Sprinkle salt after adding the baingan cubes, stir well to combine.", "Cover and cook the brinjal until soft and roasted.", "Once done turn off the heat and keep aside.Into a mixing bowl, add the curd, ginger powder, red chilli powder, turmeric powder, salt to taste and whisk well to make a smooth mixture.Now we will make the\u00a0Kashmiri Dahi Baingan:In a kadai, heat the rest of the mustard oil on medium heat.", "Once the oil is hot add the coarsely pounded fennel seeds, green cardamom, asafoetida and saute for a few seconds till the aromas are released.", "Add the\u00a0whisked curd and give it a brisk boil for 1 minute.", "Keep whisking to get a smooth dahi mixture.", "Add the roasted brinjal and boil for another 3-4 minutes and turn off the heat.", "Check the salt and adjust according to taste and transfer the Kashmiri Dahi Baingan to a serving bowl.Serve\u00a0Kashmiri Dahi Baingan Recipe\u00a0along with\u00a0Steamed Rice\u00a0or\u00a0Phulka  and a side of\u00a0Kashmiri Style Bharit Marchavangun Recipe-Stuffed Chillies\u00a0for a simple weekday meal."]'::jsonb, 25, 'Kashmiri', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Kashmiri_Dahi_Baingan_Video_Recipe_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/865.Kashmiri_Dahi_Baingan_Video_Recipe_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gujarati Dal Recipe - Sweet Tangy and Spicy Dal', 'gujarati-dal-recipe-sweet-tangy-and-spicy-dal', 'Gujarati Dal Recipe is a sweet, tangy and spicy staple dish of every Gujarati home that is made from pigeon pea lentils also known as toor dal. One of the ways we savor the Gujarati Dal at home is to have it over a hot bowl of rice topped with ghee and a green vegetable by the side.', '["1 cup Arhar dal (Split Toor Dal)", "2 tablespoons Raw Peanuts (Moongphali)", "2 tablespoons Jaggery", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves , torn", "1 inch Ginger , finely chopped", "1 Tomato , finely chopped", "1 inch Cinnamon Stick (Dalchini) , broken", "1 Bay leaf (tej patta) , torn", "2 Kokums", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 Lemon , juice extracted", "Salt , salt to taste", "1 tablespoon Ghee", "6 sprig Coriander (Dhania) Leaves"]'::jsonb, ARRAY['arhar dal', 'split toor dal', 's raw peanuts', 'moongphali', 's jaggery', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'curry leaves', 'ginger', 'tomato', 'cinnamon stick', 'dalchini', 'bay leaf', 'tej patta', 'kokums', 'turmeric powder', 'haldi', 'red chilli powder', 'lemon', 'salt', 'ghee', 'coriander', 'dhania']::text[], '["To begin making the Gujarati Dal Recipe, prepare all the ingredients and keep them ready.Cook the toor dal in 2-1/2 cups of water for about 3 whistles.", "After 3 whistles turn the heat to low and simmer for 5 to 7 minutes and turn off the heat.", "Allow the pressure to release naturally, as the dal continues to cook while the pressure is still present.While the toor dal is still hot whisk until it blends to a smooth paste with no lumps.", "You can use a hand blender or a potato masher to mash the dal well until smooth.Next step is to cook the peanuts.", "Add the raw peanuts to a pressure cooker along with 1/4 cup water and pressure cook for 3 whistles and turn off the heat.", "Allow the pressure to release naturally.To bring the gujarati dal together with all its flavours; into a preheated pan add ghee.Add the mustard and cumin seeds and allow them to crackle.Add the curry leaves, ginger, cinnamon stick, bay leaves, tomatoes, turmeric powder, red chilli powder and kokum.Saut\u00e9 until the tomatoes are soft and mushy.", "This will take a couple of minutes.", "Once the tomatoes are softened, add the whisked toor dal, salt, jaggery, lemon juice and cooked peanuts.Once the Gujarati Dal comes to a brisk boil, turn the heat to low and simmer for 5 to 10 minutes.", "Check the salt and spices and adjust to taste accordingly.The dal needs to be sweet spicy and tangy.", "Turn off the heat and stir in the chopped coriander leaves and serve hot.Serve\u00a0Gujarati Dal Recipe along with\u00a0Steamed Rice, with some ghee and a side of\u00a0Stuffed Bhindi\u00a0for a complete meal."]'::jsonb, 35, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Gujarati_Dal_Recipe_Video_5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/866.Gujarati_Dal_Recipe_Video_5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ringna No Olo Recipe - A Kathiyawadi Gujarati Style Roasted Eggplant', 'ringna-no-olo-recipe-a-kathiyawadi-gujarati-style-roasted-eggplant', 'Ringna No Olo Recipe is char roasted brinjal delicately flavored with ginger and spices. Ringna No Olo is a classic dish made from roasted brinjals and when combined with green chillies, ginger and spices they release flavors that are absolutely delectable. This dish known as Baingan Bharta in some regions of India, is prepared in a similar way with subtle variations.', '["2 Brinjal (Baingan / Eggplant) , yielding to 2 cups of roasted brinjal approximately", "2 Onion , finely chopped", "1 inch Ginger , grated", "3 Green Chilli , finely chopped", "4 cloves Garlic , finely chopped", "2 Tomato , finely chopped", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Kashmiri Red Chilli Powder", "1 teaspoon Coriander (Dhania) Powder", "1/4 teaspoon Cumin powder (Jeera)", "2 Bay leaves (tej patta) , torn", "1 inch Cinnamon Stick (Dalchini)", "2 tablespoons Ghee", "Salt , to taste", "2 tablespoons Curd (Dahi / Yogurt)", "6 sprig Coriander (Dhania) Powder , finely chopped"]'::jsonb, ARRAY['brinjal', 'baingan / eggplant', 'onion', 'ginger', 'reen chilli', 's garlic', 'tomato', 'turmeric powder', 'haldi', 'kashmiri red chilli powder', 'coriander', 'dhania', 'cumin powder', 'jeera', 'bay leaves', 'tej patta', 'cinnamon stick', 'dalchini', 's ghee', 'salt', 's curd', 'dahi / yogurt']::text[], '["To begin making the Ringna No Olo Recipe, we will first begin by roasting the eggplant.You can roast the brinjal in two ways; in the oven or on the gas flame.Using the oven for roasting, preheat the oven to 180 C.", "Place the brinjal on a baking sheet and into a preheated oven for about 30 minutes or until the brinjal has started to soften and the outer skin is charred.", "When you prick inside with a knife, you can feel that the brinjal has become tender, if not continue to bake until done.If you are using the flame for roasting, place the brinjal on the stove top flame, with continuous monitoring, using tongs to turn the brinjal around while it is roasting.", "After about 10 minutes you will notice that the brinjal\u2019s skin begins to char and the inside begins to get tender.", "To test, when you insert a knife you will feel it is soft and not hard.", "If hard continue to roast until done.Allow the brinjal to cool after roasting.", "Once the roasted brinjal cools down peel the charred skin and discard it.", "Coarsely mash the pulp using a fork or mince finely using a knife.Heat oil in a pan on medium-high heat; add cumin seeds and allow it to crackle.Add the ginger, garlic, green chillies, onion, bay leaf and cinnamon and saute until the onions soften.Once the onions are soft and golden, add the tomatoes, turmeric powder, chilli powder, coriander powder, cumin powder and saut\u00e9 until the tomatoes are soft and tender.Stir in the roasted brinjal.", "Add the yogurt at this stage and stir to combine well.", "Turn the heat to low and simmer the Ringna No Olo for 5 minutes until it gets well combined with the tomatoes and spices so you will get a delicious tasting ringna no olo.", "AtTurn off the heat and garnish ringna no olo with freshly chopped coriander leaves and stir.Serve the Ringna No Olo with Bajra Na Rotla, Gujarati Kadhi and a hot steamed rice."]'::jsonb, 65, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Ringna_Nu_Olo_Recipe_Video_Kathiawadi_recipe_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/867.Ringna_Nu_Olo_Recipe_Video_Kathiawadi_recipe_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rava Ladoo Recipe | Sooji Laddu Recipe', 'rava-ladoo-recipe-sooji-laddu-recipe', 'Rava Ladoo Recipe is a simple to make and delicious sweet that is made from slow-roasted semolina, cashew nuts and homemade ghee. This is a traditional sweet that usually made during many festivals like Diwali, Ganesh Chaturthi, weddings or even when there is a small occasion in the family.', '["1 tablespoon Ghee", "1/4 cup Sultana Raisins", "1/4 cup Cashew nuts , roughly halved", "1 tablespoon Ghee", "2 cups Sooji (Semolina/ Rava) , semolina, roasted & lightly pulsed to make a coarse powder in the blender", "1/2 cup Ghee , plus more if required", "1/4 cup Dessicated Coconut , (dry fine variery)", "3/4 cup Sugar , finely powdered", "2 teaspoons Cardamom Powder (Elaichi)"]'::jsonb, ARRAY['cashew nuts', 'ghee', 'raisins', 'ghee plus', 'sugar', 'coconut (dry variery)', 'cardamom powder (elaichi)', 'sooji (semolina rava) semolina']::text[], '["To begin making the Rava Ladoo Recipe, we will first heat a teaspoon of ghee in a small pan on low heat; roast the cashew nuts until lightly golden and crisp.", "Once roasted add in the raisins and saut\u00e9 for a few seconds.", "Turn off the heat and keep this aside.Preheat a pan over medium heat and roast the rava/sooji/ semolina for about 4 to 5 minutes until you get a roasted aroma.", "Ensure it does not brown and burn.", "Once the sooji is roasted, turn off the heat and keep aside.Into a mixer grinder,\u00a0add the sugar and blend to make a fine powder.Add the roasted sooji/rava, dessicated coconut, elaichi powder to the powdered sugar and blend to make a coarse powder of the entire sooji mixture.Powdering the rava/sooji will a little will give a better texture and good bite for the rava ladoo.", "Into a large mixing bowl, add the sugar, rava, coconut mixture, roasted cashew nuts and raisins.", "Give the mixture a stir.Add the melted ghee and combine it well together.", "Shape the rava ladoo mixture into 20 equal size balls.", "The entire mixture should be warm, if the rava mixture has cooled down, then it will not be able to hold firm into a ball.", "If you are unable to hold the mixture and shape it into a ball; add in a tablespoon of milk or ghee or both to help it come together.You have to ensure the you compress the rava ladoo mixture effectively with your fingers to bring it together.", "As you keep compressing the rava ladoo, it will get more and more firm and you will be able to shape it into a ball.", "Once you have shaped all the Rava Ladoos, they\u00a0are ready to be served.", "Store them in an airtight container for about 2 weeks.Serve the\u00a0Rava Ladoo\u00a0as a dessert after your everyday meal of\u00a0Punjabi Dal Tadka,\u00a0Arbi Shimla Mirch Sabzi\u00a0and\u00a0Phulka\u00a0with your family."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Rava_Ladoo_Recipe_Sooji_Laddu_Video_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/868.Rava_Ladoo_Recipe_Sooji_Laddu_Video_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gujarati Khatta Dhokla Recipe', 'gujarati-khatta-dhokla-recipe', 'Gujarati Khatta Dhokla is a healthy dal cake, made with a batter of rice and dals like - urad dal and chana dal, flavoured with ginger and green chilli which is steamed and seasoned with mustard and sesame seeds.', '["1 cup Rice", "1 cup White Urad Dal (Whole)", "1 cup Chana dal (Bengal Gram Dal)", "2 tablespoons Curd (Dahi / Yogurt)", "2 Green Chillies", "1 inch Ginger", "Red Chilli powder , for sprinkling", "1 tablespoon Oil", "Salt , to taste", "Ingredients for seasoning", "1 tablespoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Sesame seeds (Til seeds)", "1/4 teaspoon Asafoetida (hing)", "1 sprig Curry leaves , finely chopped", "Coriander (Dhania) Leaves , for garnishing"]'::jsonb, ARRAY['rice', 'white urad dal', 'whole', 'chana dal', 'bengal gram dal', 's curd', 'dahi / yogurt', 'reen chillies', 'ginger', 'red chilli powder', 'oil', 'salt', 'ingredients for seasoning', 'mustard seeds', 'rai/ kadugu', 'sesame seeds', 'til seeds', 'asafoetida', 'hing', 'curry leaves', 'coriander', 'dhania']::text[], '["To begin making the Gujarati Khatta Dhokla Recipe, soak the rice, and dals in 3 cups of water for 6 hours.Once soaked, drain the water from the rice and the dal.", "Transfer to a tall jar of the mixer grinder and grind\u00a0the soaked dal along with green chillies, ginger, yogurt adding little water at time to make a thick batter.The consistency of the batter should be such that when you use a ladle to pour, it should be of thick flowing consistency and not a thin batter.Transfer the dhokla batter into a large bowl, stir in the salt and allow the dholka batter to ferment for 8 hours or overnight.Once fermented you will notice the batter has risen.", "Gently stir in the oil into the batter taking care to keep the fluffy consistency.Generously grease the dhokla plates with oil all round the sides and the base.", "Pour in the batter into the plates until it is half full.", "Sprinkle a little red chilli powder around the top of the dough.Place the dhokla plates in a steamer and steam for about 10 minutes on high heat, until the dhokla is cooked.", "When a greased knife inserted into the center, it should come out clean.Allow the Khatta dhokla to rest for 5 minutes before serving them.Heat oil in a small pan on medium heat; add the mustard seeds, sesame seeds, asafoetida, curry leaves and allow them to crackle and turn off heat.Drizzle the seasoning over the Khatta Dhokla and garnish with coriander leaves.Serve the Khatta Dhokla\u00a0into desired shapes and serve with Green Chutney."]'::jsonb, 50, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Gujarati_Khatta_Dhokla_Recipe_video_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/869.Gujarati_Khatta_Dhokla_Recipe_video_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kaddu Simla Mirch Sabzi Recipe - Pumpkin Capsicum Sabzi', 'kaddu-simla-mirch-sabzi-recipe-pumpkin-capsicum-sabzi', 'Kaddu Simla Mirch Sabzi Recipe makes a simple and quick weeknight dinner when served along with phulka and kadhi/dal. It is a simple stir fry where capsicum and pumpkin are cooked in everyday masalas.', '["1 teaspoon Mustard oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1 Onion , diced", "1 Green Bell Pepper (Capsicum) , diced", "500 grams Kaddu (Parangikai/ Pumpkin) , diced", "2 Tomatoes , finely chopped", "2 sprig Curry leaves , torn", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Sambar Powder , or panch phoran", "1 teaspoon Jaggery", "Salt , to taste"]'::jsonb, ARRAY['mustard oil', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'methi seeds', 'fenugreek seeds', 'onion', 'reen bell pepper', 'capsicum', 's kaddu', 'parangikai/ pumpkin', 'tomatoes', 'curry leaves', 'turmeric powder', 'haldi', 'sambar powder', 'jaggery', 'salt']::text[], '["To begin making the Kaddu Simla Mirch Ki Sabzi, heat oil in a heavy bottomed pan,\u00a0add the mustard seeds, cumin seeds, fenugreek seeds and curry leaves and allow them to crackle.Once done stir in the green bell peppers and onions, saut\u00e9 for a few minutes, until the vegetables turn lightly soft and tender.", "At this stage add in the tomatoes and the pumpkin and mix well to combine.Now add the turmeric powder, sambar powder, jaggery and salt.", "Stir well to combine all the ingredients.Sprinkle a few drops of water, turn the heat to low and cover the pan.", "Simmer the Kaddu Simla Mirch Ki Sabzi until then pumpkin is soft and cooked, about 7 to 10 minutes.Do make sure you keep stirring the Kaddu Simla Mirch Ki Sabzi occasionally half way through the cooking process.Once the Kaddu Simla Mirch Ki Sabzi is cooked, turn off the heat, check the salt and spice levels and adjust to suit your taste.", "Transfer the Kaddu Simla Mirch Sabzi into a serving platter and serve hot.Serve\u00a0Kaddu Simla Mirch Sabzi\u00a0Recipe along with\u00a0Gujarati Kadhi,\u00a0Phulka\u00a0and\u00a0Satvik carrot Sprouts Salad\u00a0for a weekday meal."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Kaddu_Simla_Mirch_Sabzi_Recipe_Video_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/870.Kaddu_Simla_Mirch_Sabzi_Recipe_Video_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paruppu Urundai Rasam Recipe - Dal Dumpling Rasam', 'paruppu-urundai-rasam-recipe-dal-dumpling-rasam', 'Paruppu Urundai Rasam is a traditional recipe from tamil nadu where the rasam is simmered in a steamed dal dumplings called as Paruppu Urundai along with fresh spices and you will not need any rasam powder to make it, but simple ingredients in your kitchen.', '["1/2 cup Arhar dal (Split Toor Dal) , soaked in water for 1 hour", "3 Dry Red Chillies", "1/4 teaspoon Asafoetida (hing) , a pinch", "1/2 teaspoon Salt , to taste", "1 tablespoon Sesame (Gingelly) Oil", "1 tablespoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "2 sprig Curry leaves , torn", "1/4 teaspoon Asafoetida (hing)", "1 cup Tamarind Water", "1 Tomato , chopped and pureed", "1 teaspoon Cumin powder (Jeera)", "2 teaspoons Coriander (Dhania) Powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Black pepper powder", "1/2 teaspoon Red Chilli powder", "1 teaspoon Jaggery", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'tamarind water', 'asafoetida (hing)', 'ghee', 'mustard seeds', 'jaggery', 'sesame (gingelly) oil', 'red chilli powder', 'curry leaves', 'dry red chillies', 'cumin seeds (jeera)', 'coriander (dhania) powder', 'black pepper powder', 'arhar dal (split toor dal) hour', 'turmeric powder']::text[], '["To begin with Paruppu Urundai Rasam, prep all the ingredients and keep them ready.First step is to make the Paruppu Urundai.Soak the toor dal in water for about 30 minutes to an hour.Drain the excess water and add the soaked toor dal to the jar of the mixer grinder along with the red chillies, asafoetida and salt.", "Blend to make a smooth mixture without adding any water (at most just 1 tablespoon).Prepare a steamer with water at the bottom.", "Grease the idli plates with sesame oil.", "Roughly shape the Paruppu Urundai mixture and place it in the idli cavities.", "You will get about 8 urundai (dumplings)Steam on high heat heat for about 7 tp 10 minutes until cooked.", "You will notice a few crackles on the top to indicate that the Paruppu Urundai is cooked through.Turn off the heat and keep aside.The next step is the make the Rasam.Heat ghee in a saucepan over medium heat; add the mustard seeds and cumin seeds and allow it to crackle.", "Add the curry leaves and asafoetida and give it a stir.Add the tamarind water, tomato puree, turmeric powder, coriander powder, cumin powder, black pepper powder, red chilli powder, jaggery and salt.", "Add 2-1/2 cups of water or a little more.Bring the Rasam to a brisk boil and and allow it to boil until you see the rasam developing a froth.When you notice the froth around the rasam, add in the steamed Paruppu Urundai into the rasam and allow it to continue to boil for another 5 minutes.Once done, turn off the heat and give the Paruppu Urundai Rasam a taste and add salt or pepper if required.Transfer the\u00a0Paruppu Urundai Rasam to a serving bowl and serve hot.Serve Paruppu Urundai Rasam along with steamed rice, ghee,\u00a0carrot beans poriyal\u00a0for a delicious lunch or dinner."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Paruppu_Urandai_Rasam_Recipe_Video_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/871.Paruppu_Urandai_Rasam_Recipe_Video_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('The Oat and Green Moong Dal Pesarattu-Savory Lentil Crepe Recipe', 'the-oat-and-green-moong-dal-pesarattu-savory-lentil-crepe-recipe', 'The Oats Pesarattu recipe is inspired from the classic South Indian dish “Pesarattu”. Pesarattu is a crepe that is made from lentils and rice, but in this recipe I have used Saffola oats in the recipe, adding to the nutritive value. The addition of green chillies and ginger, along with finely chopped cabbage, makes this Pesarattu a favorite even with children.', '["50 grams Instant Oats (Oatmeal)", "50 grams Rice", "50 grams Green Moong Dal (Whole)", "1/2 teaspoon Asafoetida (hing)", "2 Green Chillies , finely chopped", "1 inch Ginger , grated", "100 grams Cabbage (Patta Gobi/ Muttaikose) , finely chopped", "Coriander (Dhania) Leaves , small bunch, finely chopped", "Salt , to taste", "Oil , for cooking"]'::jsonb, ARRAY['coriander (dhania)', 'salt', 'ginger', 'rice', 'asafoetida (hing)', 'cabbage (patta gobi muttaikose)', 'green moong dal', 'green chillies', 'instant oats (oatmeal)', 'sunflower oil']::text[], '["To begin making the Oats Pesarattu Recipe, we will first soak the rice, moong dal together in water for at least 3 hours.", "After 3 hours drain the water.Blend the dal, rice, green chillies and ginger adding little water at a time to make a smooth thick batter.", "Transfer the batter into a large bowl, add in the oats, salt, asafoetida, chopped cabbage and coriander leaves.", "Stir well to combine the oats Pesarattu batter well.", "Check the salt levels and adjust to suit your taste.Our next step is to make the Pesarattu.", "You will need a well-seasoned skillet.Preheat the skillet on medium heat; sprinkle some water to check on the pan; if it sizzles then you know the pan has the right amount of heat to spread the Pesarattu batter.", "Pour a ladle full of the Oats Pesarattu batter onto the pan and spread evenly inside out to make a circle.Drizzle some oil on the top and the sides of the Pesarattu and allow it to cook on low to medium heat.", "Once you notice the top of the Pesarattu getting steamed, flip it over to cook on the other side.Once you notice brown spots and the Pesarattu is cooked, remove from the pan and serve hot.", "Proceed the same way with the remaining Pesarattu batter.Serve the Oats Pesarattu along with jaggery and butter or along with Tomato Onion Chutney and Butter Milk."]'::jsonb, 60, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breakfast_Tiffins/Pesarattu_Dosa_Moong_Dal_Dosa_Chilla_Cheela_Recipe-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/872.Pesarattu_Dosa_Moong_Dal_Dosa_Chilla_Cheela_Recipe-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Konkani Style Vaingana Kaap Recipe - Shallow Fried Eggplant With Semolina', 'konkani-style-vaingana-kaap-recipe-shallow-fried-eggplant-with-semolina', 'Vaingana Kaap Recipe is a traditional Konkani shallow fried fritter made with aubergines or eggplants. For this recipe, the bigger variety of eggplant is used. The thick slices of eggplants are marinated with spices and tamarind, coated with the roasted semolina and then shallow fried in a skillet. It is spicy, crispy and makes for a wonderful side dish for a simple Dal and Rice lunch.', '["500 grams Brinjal (Baingan / Eggplant) , cut into thick slices", "1 tablespoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Tamarind Paste", "1/2 cup Sooji (Semolina/ Rava)", "Salt , to taste", "Oil , for shallow frying"]'::jsonb, ARRAY['salt', 'brinjal (baingan eggsplant)', 'red chilli powder', 'tamarind paste', 'sooji (semolina rava)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Vaingana Kaap Recipe, cut the eggplants into thick slices.", "In a bowl, mix the red chilli powder, turmeric powder, salt and tamarind pulp.Add the eggplant slices to the bowl and apply the mix evenly on both the sides of the eggplant slices.Leave it to marinate for 5 minutes, the excess water will also ooze out of the eggplants.", "Now, coat each eggplant slice with the semolina on both sides and keep aside.To roast the eggplant, heat a skillet, brush it with little oil, place a few eggplant slices and let it cook and roast on one side for 5 minutes.Brush a little oil on top, flip over and cook the other side of the eggplant slices for another 5 minutes until it is well cooked and roasted.Likewise, cook the rest of the eggplant slices.", "Enjoy the\u00a0Vaingana Kaap Recipe along with\u00a0Steamed Rice\u00a0and\u00a0Konkani Style Southe Koddel\u00a0for a simple yet delicious weekday lunch."]'::jsonb, 30, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Vaingana_Kaap_Recipe_Shallow_Fried_Eggplant_with_Semolina.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/873.Vaingana_Kaap_Recipe_Shallow_Fried_Eggplant_with_Semolina.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mugachi Usal Recipe -Spicy Moong Sprouted Sabzi', 'mugachi-usal-recipe-spicy-moong-sprouted-sabzi', 'Mugachi Usal Recipe is one staple food in a Maharashtrian home. This recipe is made from moong sprouts that are steamed and given a tadka with green chillies, ginger and coconut. Moong dal is high in protein and this recipe is a quick and simple recipe that you can make. Moong sprouts are also low in calories, have fiber and B vitamins, and deliver a boost of vitamins C and K.', '["1 cup Green Moong Sprouts", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 pinch Asafoetida (hing)", "1 Green Chilli , finely chopped", "1 inch Ginger , grated", "2 tablespoon Fresh coconut , grated", "1 Lemon juice", "Salt , to taste", "Water , as required", "1 sprig Curry leaves", "2 Dry Red Chillies"]'::jsonb, ARRAY['salt', 'ginger', 'green chilli', 'asafoetida (hing)', 'mustard seeds', 'coconut', 'green moong sprouts', 'water', 'curry leaves', 'dry red chillies', 'cumin seeds (jeera)', 'lemon', 'turmeric powder']::text[], '["To begin making the Mugachi Usal recipe heat a flat skillet with oil, splutter the mustard seeds and jeera.", "Then sprinkle a pinch of hing.Place the moong sprouts in the pressure cooker.", "Add the salt, turmeric powder, and salt and 1/4 cup of water and pressure cooker for 3 whistles and turn off the heat.Heat oil in a skillet pan over medium heat.", "Add the mustard and cumin and allow it to crackle.", "Stir in the curry leaves, green chillies, ginger, coconut and cooked moong sprouts.", "Stir well until combined.Once the mugachi usal is combined well, check the taste and adjust the salt accordingly and turn off the heat.Serve\u00a0Mugachi Usal along with\u00a0Phulkas,\u00a0Punjabi Bhindi Kadhi\u00a0and\u00a0\u00a0Kachumber Salad Recipe With Cucumber, Onion & Tomatoes\u00a0for a weekday lunch or dinner."]'::jsonb, 30, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/1-aug/Mugachi_Usal_Bhaaji_Recipe_Maharashtrian_Sprouts_Sabzi_-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/874.Mugachi_Usal_Bhaaji_Recipe_Maharashtrian_Sprouts_Sabzi_-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tawa Mushroom Recipe', 'tawa-mushroom-recipe', 'Tawa Mushroom Recipe uses pav bhaji masala that creates a strong Indian flavour and goes really well with mushroom. It is just a semi dry dish that is cooked with lots of onions and paired with wonderful mushroom.', '["500 grams Button mushrooms", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1 inch Ginger , chopped", "4 cloves Garlic , chopped", "1 Green Chilli , slit", "1 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "2 teaspoons Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Garam masala powder", "1 teaspoon Pav bhaji masala", "1 teaspoon Amchur (Dry Mango Powder)", "Salt , to taste", "Oil", "3 sprig Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['tomato', 'pav bhaji masala', 'cumin powder (jeera)', 'ginger', 'salt', 'green chilli', 'coriander powder', 'amchur (dry mango powder)', 'red chilli powder', 'cloves garlic', 'coriander (dhania) leaves', 'onion', 'button mushrooms', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Tawa Mushroom Recipe, heat a kadai with oil.", "Add ginger and garlic, allow it to soften.", "Once done, add chopped onions and cook till they turn translucent.Add chopped tomatoes and sprinkle with little salt so that the tomatoes become mushy and soft.At this point you can add all the spice powders including red chilli powder, turmeric powder, coriander powder, cumin powder, and saute well.", "Add chopped mushrooms and cook until the water is all evaporated.", "Check for salt and add if required.Cook until the mixture becomes semi dry.", "At the end add chopped coriander leaves and mix well.Serve the\u00a0Mushroom Do Pyaza Recipe\u00a0along with\u00a0Tawa Paratha\u00a0and\u00a0Panchmel Dal\u00a0or Phulka,\u00a0Curd Rice\u00a0to make it a complete meal."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Tawa_Mushroom_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/875.Tawa_Mushroom_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Allam Pachadi (Ginger Chutney Recipe)', 'andhra-style-allam-pachadi-ginger-chutney-recipe', 'Andhra Style Allam Pachadi (Ginger Chutney Recipe) is a classic chutney that is accompanied along with pesarattu, idli or dosa. The chutney is made by sautéing the dals, onions, and spice on to a kadai and then ground along freshly grated coconut, a hint of jaggery and some tamarind juice. The spice are well balanced and taste delicious as a side dish for any breakfast dishes.', '["1 tablespoon Chana dal (Bengal Gram Dal)", "1 tablespoon White Urad Dal (Split)", "2 Dry Red Chillies", "1 tablespoon Coriander (Dhania) Seeds", "3 inch Ginger , chopped", "1 Onion , chopped", "1 Tomato , chopped", "Salt , to taste", "To tamper", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1 pinch Asafoetida (hing)", "Oil , for cooking"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'mustard seeds', 'asafoetida (hing)', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'coriander (dhania) seeds', 'onion', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making the Andhra Style Allam Pachadi, heat a kadai with oil, add the dals and saute them till they are light brown.Add the dry red chillies, coriander seeds, onions, ginger and saute them till the onions are translucent.Once done, add the tomatoes and salt and saute till the tomato becomes mushy.", "Switch off the heat and grind it to a smooth paste.To make the tempering, heat a small kadai with oil, add mustard seeds and allow it to splutter.Add the curry leaves and hing, leave it for 10 seconds and pour it over the chutney.", "Serve the Andhra Style Allam Pachadi along with\u00a0pesarattu\u00a0or\u00a0idli\u00a0to enjoy your morning breakfast."]'::jsonb, 30, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Andhra_Style_Allam_Pachadi_Ginger_Chutney_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/876.Andhra_Style_Allam_Pachadi_Ginger_Chutney_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lemon Oats Recipe', 'lemon-oats-recipe', 'Lemon rice is very popular in every household. Think of quick, easy, less labor lunch/dinner options, lemon rice is definitely one of them in Indian households. Are you someone who loves the simplicity of a nice flavour packed lemon rice just like me? Then, I have a piece of good news for you. How about a dish just like lemon rice, but doesn’t even have to do the labor of cooking rice? How about a healthier option than rice? But without compromising on the flavors! How about using oats in place of rice to make Lemon oats? Do you like the idea? Yes, I thought so, cause I like the idea too, and trust me the preparation is much easier and there is no compromising on flavours. For those busy, lazy, last minute dinner ideas, this lemon oats dish fits in perfectly.', '["1 cup Instant Oats (Oatmeal)", "3/4 cup Water", "1 Onion", "1 sprig Curry leaves", "3 Green Chillies", "1 teaspoon Ginger , grated", "2 tablespoon Lemon juice", "1 tablespoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1-1/2 teaspoon White Urad Dal (Split)", "1 tablespoon Chana dal (Bengal Gram Dal)", "1/4 teaspoon Asafoetida (hing)", "3/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Coriander (Dhania) Leaves , for garnish", "Roasted Peanuts (Moongphali) , for garnish"]'::jsonb, ARRAY['salt', 'ginger', 'chana dal (bengal gram dal)', 'mustard seeds', 'asafoetida (hing)', 'coriander (dhania) leaves', 'water', 'curry leaves', 'white urad dal (split)', 'onion', 'lemon', 'cumin seeds (jeera)', 'peanuts (moongphali)', 'turmeric powder', 'green chillies', 'instant oats (oatmeal)', 'sunflower oil']::text[], '["To begin making the Lemon Oats, wash chana dal well and soak in enough water for about 10 minutes.Dry roast oats on low flame until nice fragrant smell from the oats is released.Heat oil in a wide pan.", "Add mustard seeds and wait until it crackles.", "Next, add urad dal and soaked channa dal and fry till golden in colour.Add finely chopped onions, green chilies, curry leaves, grated ginger and saute until onions turn translucent.Add turmeric powder, salt and mix everything well.", "Add water and bring to boil.Simmer the flame and add roasted oats.", "Mix well making sure no lumps is formed.", "Cover and cook for about 3 to 4 minutes.Now add lemon juice and mix well.", "Cook for another 3 minutes without covering.Garnish it with finely chopped coriander leaves, roasted peanuts and also some grated coconut.Serve Lemon Oats along with\u00a0Masala Chai\u00a0and a bowl of fruits for a healthy breakfast."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Lemon_Oats.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/877.Lemon_Oats.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Coriander Chicken Roast Recipe', 'coriander-chicken-roast-recipe', 'Coriander Chicken Roast is a simple starter that can be prepared with the minimal ingredients in no time. It is usually served with Steamed Rice and Rasam. The combo is just out of the world! Chicken along with the flavour of Coriander leaves is just awesome. Try this at your home and you will make it again and again.', '["500 grams Chicken", "1 tablespoon Red Chilli powder", "1 teaspoon Garam masala powder", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , as needed", "1 tablespoon Ginger Garlic Paste", "3/4 cup Coriander (Dhania) Leaves , finely chopped", "2 tablespoons Oil"]'::jsonb, ARRAY['salt', 'coriander (dhania) leaves', 'red chilli powder', 'ginger garlic paste', 'chicken', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Coriander Chicken Roast recipe, in a bowl take the finely washed and cleaned chicken.", "To this bowl, add the\u00a0red chilli powder,\u00a0\u00a0garam masala, turmeric powder, salt, ginger garlic paste,\u00a0coriander leaves.Mix everything well and allow it to marinate for 1 hour.", "Then heat a pan add in oil once it heats up add in the Marinated Chicken and start cooking in a low flame.Continue cooking and stir in intervals to prevent it from getting burnt in the bottom of the vessel.", "Switch off the flame once the chicken is cooked and serve hot.Serve Coriander Chicken Roast along with\u00a0Steamed rice\u00a0and\u00a0Jeera Rasam\u00a0for a weekday meal."]'::jsonb, 75, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/happytrioexplains-gmail.com/Coriander_Chicken_Roast_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/878.Coriander_Chicken_Roast_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Restaurant Style Chicken 555 Recipe', 'restaurant-style-chicken-555-recipe', 'Restaurant Style Chicken 555 Recipe is a mouthwatering appetizer inspired from the popular food in the restaurant menu. Chicken is marinated with spices, with added rice flour, and semolina. Then the chicken along the marinade are shallow fried till crisp. This recipe can be prepared very easily and in no time. This can also be served for the unexpected guests during evenings. This is a high protein option that is also yummy.', '["250 grams Chicken , chopped", "1 tablespoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "Salt , to taste", "1 teaspoon Rice flour", "1 tablespoon Sooji (Semolina/ Rava)", "2 tablespoons Oil , to cook", "Curry leaves , a few"]'::jsonb, ARRAY['salt', 'red chilli powder', 'curry leaves', 'chicken', 'sooji (semolina rava)', 'rice flour', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making Restaurant Style Chicken 555 Recipe, wash the chicken pieces in thoroughly under running water.In a mixing bowl, marinate the chicken with all the spices mentioned- red chilli powder, haldi, garam masala, rice flour, semolina and salt.", "Mix well to coat the chicken properly and allow it to rest for about 30 minutes under refrigeration.Once the marination is done, heat oil in a shallow frying pan.Once the oil is hot on medium heat, place the marinated chicken in the pan.", "Place only number of pieces which can fit into the pan in one layer with a little space between them.", "Do not overcrowd.", "Also pour the marinated mix in the pan.", "I made it in two batches and hence had to reserve half of the marinated mix for the next batch.", "You can fry according to the quantity.Once the chicken are crisp and done, add a few curry leaves and saut\u00e9 till leaves become crisp.Serve Restaurant Style Chicken 555 Recipe topped with the leftover masala in pan along with curry leaves over the pieces.Serve\u00a0Restaurant Style Chicken 555 Recipe along with a meal\u00a0Mughlai Style Chicken Changezi Recipe\u00a0and\u00a0Whole Wheat Onion Stuffed Kulcha Recipe\u00a0for a complete meal."]'::jsonb, 20, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/gricha874-gmail.com/RESTAURANT_STYLE_CHICKEN_555__NO_DEEP_FRY_NON_VEG_APPETIZER.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/879.RESTAURANT_STYLE_CHICKEN_555__NO_DEEP_FRY_NON_VEG_APPETIZER.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thandu Keerai Puli Kuzhambu Recipe - Amaranth Greens in Tangy Curry', 'thandu-keerai-puli-kuzhambu-recipe-amaranth-greens-in-tangy-curry', 'Thandu Keerai Puli Kuzhambu Recipe is a traditional Tamil Nadu Style tamarind based curry made with shallots or normal onion, sometimes with garlic and vegetables. It pairs well with the lentil based Kootus. Thandu Keerai Puli Kuzhambu Recipe is simple to make and therefore you can include them into your everyday meals.', '["1 cup Green Amaranth Leaves , roughly chopped", "20 grams Tamarind , soaked in hot water and pulp extracted", "1 Onion , finely chopped", "1 Tomato , roughly chopped", "10 cloves Garlic", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)", "1 sprig Curry leaves", "2 teaspoons Sambar Powder", "1 teaspoon Methi Powder (Fenugreek Powder)", "1 tablespoon Sesame (Gingelly) Oil", "Salt , to taste", "Salt , to taste"]'::jsonb, ARRAY['green amaranth leaves', 's tamarind', 'onion', 'tomato', 's garlic', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing', 'curry leaves', 's sambar powder', 'methi powder', 'fenugreek powder', 'sesame', 'gingelly', 'salt']::text[], '["To begin making\u00a0Thandu Keerai Puli Kuzhambu Recipe, soak\u00a0tamarind in hot water, squeeze the pulp out and keep aside.", "You will approximately 1-1/2 cups of tamarind water.Heat sesame oil in a heavy bottomed pan, add the mustard seeds, and let it crackle.Add the asafoetida, curry leaves and let it splutter.Add the whole garlic cloves, chopped onions and saute until the garlic turns slightly golden and onions become soft.Once the onions become soft, add chopped tomato and cook until it turns soft and mushy.Next add the chopped thandu keerai or amaranth leaves and saute until the greens become soft.After the Thandu Keerai/ Amaranth leaves turn soft, add the tamarind pulp, sambar powder, fenugreek powder and season with salt, mix well and let it simmer for 10 minutes on low heat.", "Add additional water if required to adjust the consistency of the kuzhambu.", "Simmer and cook until the\u00a0Thandu Keerai Puli Kuzhambu gets a little thicker.", "Once the Kuzhambu thickens, turn off the heat and serve hot.Serve Thandu Keerai Puli Kuzhambu along with\u00a0Steamed Rice,\u00a0Kathirikai Kootu,\u00a0Carrot and Beans Poriyal Recipe\u00a0and\u00a0Curd\u00a0for a weeknight dinner."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Thandu_Keerai_Puli_Kuzhambu_Recipe_Tamil_Nadu_Style_Foxtail_Amaranth_Cooked_in_Tamarind_Gravy.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/880.Thandu_Keerai_Puli_Kuzhambu_Recipe_Tamil_Nadu_Style_Foxtail_Amaranth_Cooked_in_Tamarind_Gravy.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Muttaikose Poriyal Recipe -  Purple Cabbage Poriyal | Red Cabbage Sabzi', 'muttaikose-poriyal-recipe-purple-cabbage-poriyal-red-cabbage-sabzi', 'The Purple Cabbage Poriyal/ Muttaikose Poriyal Recipe is a very traditional South Indian dry vegetable made from cabbage. The Cabbage that is also called as Muttaikose in tamil is power cooked with a very simple seasoning if mustard seeds, curry leaves, salt and freshly grated coconut.', '["To Cook Cabbage", "500 grams Purple cabbage , roughly chopped or sliced thin", "Salt , to taste", "2 tablespoons Water", "1 teaspoon Coconut Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 teaspoons White Urad Dal (Split)", "2 sprig Curry leaves , finely chopped", "1/4 teaspoon Asafoetida (hing)", "2 Green Chillies , slit", "1/4 cup Fresh coconut , grated"]'::jsonb, ARRAY['salt', 'mustard seeds', 'purple cabbage', 'asafoetida (hing)', 'coconut', 'water', 'curry leaves', 'white urad dal (split)', 'coconut oil', 'green chillies']::text[], '["To begin making the Muttaikose Poriyal Recipe/ Purple Cabbage Poriyal, get the cabbage chopped or sliced and the rest of the ingredients ready.Place the purple cabbage in pressure cooker, add 2 tablespoon of water and pressure cook for 1 whistle and turn off the heat.", "Release the pressure immediately, to avoid over cooking the cabbage.Heat a teaspoon of oil a heavy-bottomed pan on medium heat.Add the mustard seeds and urad dal.", "Allow them to crackle.", "Roast the urad dal until it gets lightly browned.Once the dal is golden brown and crisp, add the curry leaves, green chillies, purple cabbage and salt to taste.Give the Purple Cabbage Poriyal a stir and saute for a couple of minutes and turn off the heat.Once done, add the grated coconut, give the Purple Cabbage Poriyal a mix and check the salt and adjust to suit your taste.Add more coconut if required.", "Turn off the heat and serve the Muttaikose Poriyal / Purple Cabbage Poriyal warm.Serve the Muttaikose Poriyal Recipe/ Purple Cabbage Poriyal along with Tomato Rasam and Steamed Rice topped with ghee for lunch or dinner."]'::jsonb, 45, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Red_cabbage_Poriyal_Recipe_Purple_Cabbage_Sabzi_7_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/881.Red_cabbage_Poriyal_Recipe_Purple_Cabbage_Sabzi_7_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Nellor Kathirikai - Nellor Brinjal Fry Recipe', 'nellor-kathirikai-nellor-brinjal-fry-recipe', 'Nellore Brinjal Fry Recipe a rich and delicious brinjal curry made with roasted spices, onions and lots of other interesting ingredients that are ground into a smooth paste and mixed along with roasted brinjal. This dish is wonderful side dish that can go along with your tawa parathas or even a hot bowl of steamed rice. The curry has the right amount of spice levels that balances out the flavor and keeps you asking for more.', '["1 tablespoon Sesame (Gingelly) Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 sprig Curry leaves , torn", "10 Small Brinjal (Baingan / Eggplant) , quartered and soaked in salt water", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Salt", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 tablespoon Chana dal (Bengal Gram Dal)", "1 tablespoon Coriander (Dhania) Seeds", "4 Dry Red Chillies", "1 tablespoon Sesame (Gingelly) Oil", "2 Onion , thinly sliced", "1/4 cup Fresh coconut , grated", "1 teaspoon Sesame (Gingelly) Oil", "Salt , to taste", "1/2 cup Water"]'::jsonb, ARRAY['salt', 'mustard seeds', 'coconut', 'sesame (gingelly) oil', 'water', 'curry leaves', 'coriander (dhania) seeds', 'dry red chillies', 'onion', 'turmeric powder', 'chana dal (bengal gram dal)', 'brinjal (baingan eggsplant) salt water']::text[], '["To begin making the Nellor Brinjal Fry Recipe, prepare all the ingredients and keep them ready.Soak the cut brinjal in salt water to prevent it from turning dark.First step is to roast the brinjal.", "Heat oil in a pan over medium heat; add the mustard seeds and curry leaves and allow the mustard seeds to crackle.Drain the water from the brinjal and add the brinjal, turmeric powder and salt.", "Stir to combine and cover the pan and cook the brinjal until the brinjal is roasted and cooked.", "Keep this aside.To make the Nellor Masala, in a pan add the\u00a0chana dal, coriander seeds and red chillies.", "Roast them well until the dal has turned golden brown.", "Keep aside.In the same pan; add oil, the sliced onions and saute until the onions soften and turn slightly brown.Once the onions have browned, add the grated coconut and stir fry for another 3 to 4 minutes until you can smell the aromas of the coconut coming through.", "Once done turn off the heat.Add the roasted dal mixture and onion mixture to a small jar of the mixture grinder along with 1/4 cup of water and blend to make a smooth paste.Add this masala to the roasted brinjal along with 1/2 cup of water and mix well to combine the Nellor Brinjal fry.", "Cover the pan and simmer for 5 minutes and turn off the heat.Check the salt and chillies and adjust to taste accordingly.", "Once done, transfer the Nellor Brinjal Fry to a serving bowl and serve hot.Serve the\u00a0Nellor Brinjal Fry Recipe\u00a0along with some\u00a0Steamed Rice,\u00a0Palak Tovve or Palak Dal\u00a0or just with plain\u00a0Tawa Parathas."]'::jsonb, 45, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Nellore_Kathirikkai_Recipe_Nellore_Brinjal_Curry_2-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/882.Nellore_Kathirikkai_Recipe_Nellore_Brinjal_Curry_2-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Yeruvalli Kuzhambu Recipe | Iru Puli Kuzhambu | Tangy Coconut Curry', 'yeruvalli-kuzhambu-recipe-iru-puli-kuzhambu-tangy-coconut-curry', 'The Yeruvalli Kuzhambu Recipe also known as Iru Puli Kuzhambu is a very popular dish among the Tamil Brahmin and Kerala Tamil Brahmin community. This Kuzhambu recipe is made from freshly grated coconut, roasted fenugreek seeds, dried red chillies and cooked along with tamarind to make it a spicy curry.', '["1 Carrots (Gajjar) , peeled and diced", "1 Green Bell Pepper (Capsicum) , diced", "1 Drumstick , cut into 1 inch pieces", "1 cup Tamarind Water", "1 teaspoon Salt", "1 cup Fresh coconut , grated", "4 Dry Red Chillies", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1-1/2 teaspoons White Urad Dal (Split)", "Ingredients for the Seasoning", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1 teaspoon Coconut Oil"]'::jsonb, ARRAY['carrots', 'gajjar', 'reen bell pepper', 'capsicum', 'drumstick', 'tamarind water', 'salt', 'fresh coconut', 'dry red chillies', 'methi seeds', 'fenugreek seeds', 's white urad dal', 'split', 'ingredients for the seasoning', 'mustard seeds', 'rai/ kadugu', 'curry leaves', 'coconut oil']::text[], '["To begin making the Yeruvalli Kuzhambu/ Iru Puli Kuzhambu, the first step is to prep all the ingredients and keep them ready.Cook the vegetables along with the tamarind water in the pressure cooker.", "Place the diced vegetables, the tamarind water and salt into the pressure cooker.Place the weight on and pressure cook until you heat 2 to 3 whistles.", "Turn off the heat and allow the pressure to release naturally.While the pressure is getting released, we will make the curry paste for the Yeruvalli Kuzhambu/ Iru Puli Kuzhambu.In a small pan; add in the fenugreek seeds/ methi, urad dal and red chillies.", "Roast them until you notice the ingredients turning slightly brown and releases a roasted aroma.", "Add the roasted ingredients into a small blender jar, add the coconut and about 1/4 cup of warm water.", "Blend to make a smooth curry paste.", "Heat oil in a pan; add mustard seeds and curry leaves and allow it to crackle.", "Once it crackles, add the cooked vegetables along with the tamarind water, the coconut curry paste and give it a stir.", "Check the salt levels and adjust to suit your taste.", "Give the\u00a0Yeruvalli Kuzhambu a brisk boil and turn off the heat.", "Adjust the consistency of the Kuzhambu by adding 1/4 cup water of water if required.Transfer the kuzhambu to a serving bowl and serve hot.Serve the\u00a0Yeruvalli Kuzhambu / Iru Puli Kuzhambu\u00a0along with hot\u00a0steamed rice\u00a0for lunch and or even along with dosa\u2019s."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Yeruvalli_Kuzhambu_Iru_Puli_Kuzhambu_Recipe_Video_5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/883.Yeruvalli_Kuzhambu_Iru_Puli_Kuzhambu_Recipe_Video_5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Instant Khaman Dhokla Recipe', 'instant-khaman-dhokla-recipe', 'The Khaman Dhokla recipe is a popular farsan also known as a snack from the Gujarati Cuisine. This is a simple and instant recipe that takes only 20 minutes to make. The Dhokla is packed with flavours from gram flour, ginger and green chillies along with a sweet and tangy tadka.', '["2 Green Chillies , chopped", "1 inch Ginger , chopped", "1/4 cup Water", "1-1/2 cups Gram flour (besan)", "1/2 cup Water , or more if required", "1 teaspoon Salt , to taste", "1/4 teaspoon Cooking soda", "1 teaspoon Enos Fruit Salt", "1 teaspoon Sugar", "1/4 teaspoon Turmeric powder (Haldi)", "1 tablespoon Oil", "1 tablespoon Lemon juice", "1 teaspoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "4 Green Chillies , slit", "2 sprig Curry leaves", "2 tablespoons Sugar", "1/4 teaspoon Salt", "1/2 cup Water", "2 tablespoons Lemon juice", "1/4 cup Fresh coconut , grated", "6 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['salt', 'ginger', 'mustard seeds', 'coconut', 'cumin (jeera) seeds', 'water', 'gram flour (besan)', 'curry leaves', 'soda', 'sugar', 'coriander (dhania) leaves', 'lemon', 'turmeric powder', 'enos fruit salt', 'green chillies', 'sunflower oil']::text[], '["To begin preparing the Khaman Dhokla, prepare all the ingredients and keep them ready.Grease a 7 inch cake tin or a dhokla pan and keep aside.", "Prepare a steamer with water and keep it ready.", "First, make the green chilli ginger mixture.", "Into a small jar of mixer grinder, add the green chillies, ginger and water and blend to make a puree.", "Keep this aside.Into a large mixing bowl, add all the ingredients along with the above green chilli ginger paste and keep aside.Whisk well to combine, the addition of lemon juice and soda will make the Khaman Dhokla batter froth up.It is important you steam the batter immediately once it is well combined, so that the Khaman Dhokla remains fluffy when steamed.Pour the Khaman Dhokla batter into the greased pan and place it in the prepared steamer.", "Cover the steamer and turn on the heat to high and steam for 10 minutes until done.You will know when it is done, when you insert a knife in the centre and around the edges and it comes out clean.Remove the Khaman Dhokla from the steamer and allow it to cool completely.", "Do not cut it while it is warm or hot as it will crumble.The next step is to prepare the tadka along with the sugar lemon water.Preheat a pan with oil over medium heat; add the mustard seeds and cumin seeds and allow it to crackle.", "Once it crackles, add the green chillies and curry leaves and stir for about a minute.", "Once done, add the water, lemon juice, sugar and salt.", "Stir well until the sugar has dissolved and turn off the heat.", "Allow the tadka to cool a bit.", "Once the Khaman Dhokla has cooled completely, cut it into squares or diamonds.", "Spoon the tadka over the Khaman Dhokla so it gets soaked well.", "If there is more tadka water remaining, just keep it aside and pour it later when you feel it has become dry or you want it more juicy.Remove the Khaman Dhokla from the pan and place it on a serving platter.", "Sprinkle freshly grated coconut and chopped coriander leaves and serve.", "Serve it along with\u00a0Green Chutney\u00a0and\u00a0Adrak Chai as an evening snack."]'::jsonb, 30, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Instant_Khaman_Dhokla_Recipe_Video_Gujarati_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/884.Instant_Khaman_Dhokla_Recipe_Video_Gujarati_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rajgira Paneer Paratha Recipe (Navratri Fasting/Vrat Recipe)', 'rajgira-paneer-paratha-recipe-navratri-fasting-vrat-recipe', 'Rajgira Paneer Paratha Recipe (Navratri Fasting/Vrat Recipe) is an Indian flatbread made by mixing amaranth flour with paneer as the binding agent and flavoured with Indian spice and rolled out thin and toasted on a flat pan till it is crispy on both the sides.', '["1 cup Rajgira Flour (Amaranth Flour)", "2 Potato (Aloo) , boiled, mashed", "1 cup Paneer (Homemade Cottage Cheese) , grated", "2 Green Chillies , finely chopped", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera)", "2 sprig Coriander (Dhania) Leaves , finely chopped", "1/2 teaspoon Whole Black Peppercorns , ground", "Salt , or rock salt to taste", "Oil , or ghee for cooking"]'::jsonb, ARRAY['salt salt', 'cumin powder (jeera)', 'sunflower oil ghee', 'paneer', 'rajgira flour (amaranth flour)', 'potato (aloo)', 'black peppercorns ground', 'coriander (dhania) leaves', 'turmeric powder', 'green chillies']::text[], '["We begin making the\u00a0Rajgira Paneer Paratha Recipe (Navratri Fasting/Vrat Recipe) by Mixing all the ingredients together in a mixing bowl with enough water to a dough consistency.The rajgira flour is little hard to work with since it does not contain gluten so make sure to have enough flour to dust while rolling the dough.Divide the dough into equal portions and roll it onto a board.Heat a Flat bottomed pan and add the rolled paratha with some ghee and cook it on both the sides for about 2 minutes.Serve your crispy\u00a0Rajgira Paneer Paratha with No Onion No Garlic Tomato Chutney making it a delicious meal."]'::jsonb, 25, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/sept-21/Rajgira_Paneer_Aloo_Paratha_Recipe_Vrat_Fasting_Navratri-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/885.Rajgira_Paneer_Aloo_Paratha_Recipe_Vrat_Fasting_Navratri-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gajar Methi Poriyal Recipe - Carrot Fenugreek Stir Fry', 'gajar-methi-poriyal-recipe-carrot-fenugreek-stir-fry', 'Gajar Methi Ki Sabzi or Poriyal is a simple South Indian vegetarian Curry that you can make for your South Indian lunch or dinner along with a gravy dish and chapati. You can also serve it with your choice of sambar and rice.', '["2 Carrots (Gajjar)", "2 cups Methi Leaves (Fenugreek Leaves)", "1 Onion , chopped", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves", "3 Dry Red Chillies", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Coriander Powder (Dhania)", "Salt , as required", "1 teaspoon Coconut Oil", "Coriander (Dhania) Leaves , finely chopped (for garnish)"]'::jsonb, ARRAY['salt', 'coriander (dhania) leaves', 'methi leaves (fenugreek leaves)', 'carrot', 'curry leaves', 'dry red chillies', 'onion', 'cumin seeds (jeera)', 'coconut oil', 'coriander powder', 'turmeric powder']::text[], '["To begin making the\u00a0Gajar Methi Poriyal recipe, firstly wash the fenugreek leaves with clean water.", "Drain the water fully and chop the fenugreek leaves roughly.", "Keep it aside.Next, wash the carrots, peel them and grate it using a grater.", "Keep it aside.Heat a heavy bottomed pan with required coconut oil.", "Add cumin seeds, curry leaves, dry red chillies and saute them for about 30 seconds.After 30 seconds, add onions and cook them till they turn soft and translucent.", "Once the onion turns translucent, add the roughly chopped fenugreek leaves and cook till they also become soft.After the leaves become soft, add\u00a0grated carrots, turmeric powder, coriander powder and salt.", "Mix and cook them for about a minute.", "After a minute, add little water and cover the pan with a lid.", "Cook the Gajar Methi Poriyal covered for 2 to 3 minutes or until the water evaporates completely.When the poriyal is cooked, switch off the gas and garnish it with coriander leaves.", "Serve\u00a0Gajar Methi Poriyal\u00a0with\u00a0Jeera Milagu Rasam/Keerai Sambar\u00a0and Steamed Rice for your weekday lunch."]'::jsonb, 25, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swathynandhini/CARROT_METHI_SABZI_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/886.CARROT_METHI_SABZI_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sprouted Moong Dal Recipe - Spicy Sprouted Lentil Curry', 'sprouted-moong-dal-recipe-spicy-sprouted-lentil-curry', 'Sprouted moong (Green gram) dal is a popular, healthy and spicy lentil curry made across India in different ways depending on the region. It is made using spicy masala and is perfect for your week day lunch.', '["2 cups Green Moong Sprouts", "1 Onion , finely chopped", "3 cloves Garlic , crushed", "1 tablespoon Ghee , or oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Asafoetida (hing)", "1/4 teaspoon Maharashtrian Goda Masala", "1/4 teaspoon Red Chilli powder", "2 Kokum (Malabar Tamarind)", "1/2 teaspoon Jaggery , grated", "2 teaspoon Groundnut powder", "2 cups Water , or as required", "Salt , to taste", "Coriander (Dhania) Leaves , Chopped, for garnishing"]'::jsonb, ARRAY['salt', 'mustard seeds', 'asafoetida (hing)', 'kokum (malabar tamarind)', 'coriander (dhania) leaves', 'green moong sprouts', 'red chilli powder', 'cloves garlic', 'jaggery', 'water', 'onion', 'cumin seeds (jeera)', 'maharashtrian goda masala', 'ghee', 'oil', 'groundnut powder', 'turmeric powder']::text[], '["To begin making the Sprouted Moong Dal Recipe, heat ghee/oil in a pressure cooker.Add the mustard seeds and the cumin seeds and once they crackle add the\u00a0onion, garlic, asafoetida and saute it for 1-2 minutes till the onions turn translucent.After 1-2 minutes, add the turmeric powder, moong sprouts and saut\u00e9 it for about a minute.Next add the masala, chilli powder and mix well.", "Add water and then add the kokum, jaggery, salt, peanut powder and stir well to combine.Cover it with the lid and cook it till the cooker releases 1 whistle or till the sprouts are well cooked.", "Adjust the consistency of water if required.Once the Sprouted Moong Dal\u00a0 is done, garnish with fresh coriander leaves and serve hot.Serve\u00a0Sprouted Moong Dal Recipe\u00a0with hot with\u00a0phulkas\u00a0or hot\u00a0Steamed Rice\u00a0with a dollop of ghee for lunch or dinner."]'::jsonb, 25, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Sprouted_Moong_Dal_spicy_Sprouted_Lentil_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/887.Sprouted_Moong_Dal_spicy_Sprouted_Lentil_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Vendakaya Charu Recipe - Ladies Finger Rasam', 'andhra-style-vendakaya-charu-recipe-ladies-finger-rasam', 'Andhra Style Vendakaya Charu Recipe (Ladies Finger Rasam Recipe), anyone who is craving for a quick and comforting meal at home should try this Rasam recipe which will lift up your mood for the day. The rasam or charu is an authentic way of making a peppery flavored hot tamarind rasam. This rasam anhot rice is so comforting to be eaten as your lunch meal.', '["6 Bhindi (Lady Finger/Okra)", "2 Tomato , roughly chopped", "6 Pearl onions (Sambar Onions) , quartered", "4 Garlic", "1 cup Tamarind Water", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Sugar", "Salt , to taste", "Seasoning", "1 teaspoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1 sprig Curry leaves", "1 Dry Red Chilli , broken into half"]'::jsonb, ARRAY['bhindi', 'lady finger/okra', 'tomato', 'pearl onions', 'sambar onions', 'arlic', 'tamarind water', 'red chilli powder', 'turmeric powder', 'haldi', 'asafoetida', 'hing', 'coriander powder', 'dhania', 'sugar', 'salt', 'seasoning', 'ghee', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'methi seeds', 'fenugreek seeds', 'curry leaves', 'dry red chilli']::text[], '["We begin making the Andhra Style Vendakaya Charu Recipe (Ladies Finger Rasam Recipe) by placing\u00a0 a pressure cooker on medium flame with ghee and the mustard seeds and allow them to splutter, next add\u00a0 cumin seeds, fenugreek seeds, dry red chillies, curry leaves and allow them to crackle.", "Next add in the chopped onions, and garlic pods.", "Saute till it is translucent.", "Then add in the tamarind water,\u00a0 sugar, salt,\u00a0red chilli powder,\u00a0turmeric powder, asafoetida,\u00a0coriander powderand chopped tomatoes and okra.", "Stir well.Pressure cook the rasam for about 3 whistles, turn off the flame and allow the pressure to release naturally.", "Serve the Andhra Style Vendakaya Charu Recipe (Ladies Finger Rasam Recipe) with\u00a0\u00a0Chettinad Beans & Cauliflower Poriyal Recipe,\u00a0hot steamed rice\u00a0with a teaspoon of ghee to enrich the taste."]'::jsonb, 25, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Andhra_Style_Vendakaya_Charu_Recipe_Ladies_Finger_Rasam_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/888.Andhra_Style_Vendakaya_Charu_Recipe_Ladies_Finger_Rasam_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gujarati Methi Na Dhebra Recipe', 'gujarati-methi-na-dhebra-recipe', 'Gujarati Methi Na Dhebra recipe is perfect tea time snack from the state of Gujarat. You can use either fresh methi leaves (fenugreek) or dried methi or kasuri methi, to prepare this dish. I have used fresh methi in this recipe. This is a heirloom recipe that I have learned from my grandma.', '["1/2 cup Bajra Flour ( Pearl Millet)", "1/2 cup Jowar Flour (Sorghum)", "1/2 cup Whole Wheat Flour , More for dusting", "2 cups Methi Leaves (Fenugreek Leaves) , finely chopped", "2 inch Ginger , ground to paste", "3 Green Chillies , finely chopped", "1 tablespoon Sesame seeds (Til seeds)", "2 teaspoons Red Chilli powder", "2 teaspoons Turmeric powder (Haldi)", "1/4 teaspoon Asafoetida (hing)", "5 tablespoons Curd (Dahi / Yogurt)", "1 teaspoon Sugar , (optional)", "Salt , to taste", "1 tablespoon Oil"]'::jsonb, ARRAY['salt', 'wheat flour', 'jowar flour (sorghum)', 'asafoetida (hing)', 'methi leaves (fenugreek leaves)', 'red chilli powder', 'curd', 'sugar', 'sesame seeds (til seeds)', 'bajra flour ( pearl millet)', 'turmeric powder', 'green chillies', 'ginger ground paste', 'sunflower oil']::text[], '["To prepare Gujarati Methi Na Dhebra Recipe, get all the ingredients ready.In a large bowl, mix fenugreek leaves, ginger paste, green chilies, sesame seeds, chili powder, turmeric powder, asafoetida.", "Mix it well with a teaspoon of oil.", "Keep aside for 5 minutes to help fenugreek leaves soften a bit.Add millet flour, whole wheat flour, sugar and salt.Mix well using your finger so fenugreek mixture will incorporate well with flours.", "It will look crumbly texture.Add tablespoon yogurt at a time and knead to form soft dough.", "You will need 5 or 6 tablespoon of yogurt depends on your flour or depends on the consistency of your yogurt.", "So add little yogurt at a time so will come to know how much you need.", "Cover it and let it stand for 10-15 minutes.After 15 minutes, knead it again to make it smooth.Divide it into 10 equal portions.", "Roll each portion between your palm and press into a circle.Heat the tawa on medium heat.Dip the flattened ball into dry chapati flour and coat well.", "Roll it gently in to circle about 6 inch in diameter.Once hot placed rolled dhebra on the skillet.", "When you see bubbles on it flip it.", "After few seconds apply some oil on it and flip it again and press gently using spatula and cook until you see some brown spot on bottom side.Apply some oil again (optional) on other side and flip and cook on that side.When done, take it out from skillet/tawa proceed similarly till all the dough is used up.Serve Gujarati Methi Na Dhebra recipe dabbed with homemade ghee along with a cup of pounded jaggery, Naranga Achaar, yogurt and Sev Tamatar Ki Sabzi."]'::jsonb, 30, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Dhara/Gujarati_Methi_Na_Dhebra_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/889.Gujarati_Methi_Na_Dhebra_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Style Apple Tamatar Sabzi Recipe - No Onion No Garlic', 'kashmiri-style-apple-tamatar-sabzi-recipe-no-onion-no-garlic', 'Kashmiri Style Apple Tamatar Ki Sabzi is a semi-gravy made with cubed apple cooked in a cinnamon infused tomato based gravy. It rightly brings out the flavour in the dish. As apples goes well with the cinnamon,the gravy is a sweet and tangy taste.', '["2 Apples , peeled and cubed", "2 Tomatoes , pureed or grated", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Red Chilli powder", "1 Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta) , torn", "Salt , or black salt to taste", "2 sprig Coriander (Dhania) Leaves , finely chopped", "Oil , for cooking"]'::jsonb, ARRAY['tomato', 'bay leaf (tej patta)', 'apples', 'red chilli powder', 'coriander (dhania) leaves', 'cinnamon stick (dalchini)', 'salt black salt', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["We begin making the Apple Tamatar Ki Sabzi\u00a0 heating a kadai with a little bit of oil and add bay leaf and cinnamon.", "Saute till the aroma is released.Next, add the tomato puree and the other spice powders.", "Saute for about 10 minutes till the raw smell of the tomato goes away.Add the cubed apple and give it a stir.", "Cook for 10 more minutes till the apple becomes mush and imbibes a little bit of the gravy.Serve your sweet and tangy Apple Tamatar ki Sabzi with Singhare ka Cheela or Ajwain Puri\u00a0to make it a complete meal."]'::jsonb, 50, 'Kashmiri', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/sept-20/Seb_Ki_Sabzi_Apple_Tomato_Sabzi_Curry_Jain_Vrat_Fasting_Food-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/890.Seb_Ki_Sabzi_Apple_Tomato_Sabzi_Curry_Jain_Vrat_Fasting_Food-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Upvaas Thalipeeth Recipe', 'upvaas-thalipeeth-recipe', 'Upvaas Thalipeeth is a typical Maharashtrian pancake usually made during religious fasts. Flours of Barnyard millet (Sama, Bhagar), Amaranth (Rajgira), Sago (Sabudana), Singada (water chestnut) are mixed with grated potato and a few spices to make this delicious Thalipeeth. You can make this ahead of time and stock it in the refrigerator. This flavourful Upvaas Thalipeeth makes for a wholesome breakfast or meal not only for fasts but also on regular, non-fasting days.', '["1/2 cup Barnyard Millet (Bhagar Flour)", "1/2 cup Rajgira Flour (Amaranth Flour)", "1/2 cup Tapioca Flour (Sago)", "1/2 cup Singoda Flour (Water Chestnut)", "2 Potatoes (Aloo) , peeled and grated", "1 teaspoon Cumin seeds (Jeera)", "2 to 3 Green Chillies , crushed or finely chopped", "2 to 3 teaspoons Coriander (Dhania) Leaves", "2 tablespoons Groundnut powder", "Salt , to taste", "Ghee , as required for cooking and greasing"]'::jsonb, ARRAY['salt', 'singoda flour (water chestnut)', 'coriander (dhania) leaves', 'barnyard millet (bhagar flour)', 'rajgira flour (amaranth flour)', 'tapioca flour (sago)', 'cumin seeds (jeera)', 'ghee greasing', 'groundnut powder', 'potato (aloo)', 'green chillies']::text[], '["To begin making the Upvas thalipeeth, first mix all the flours in a mixing bowl.In a heavy bottom pan and on low heat, dry roast the flour mixture for 2 to 3 minutes till you get the typical aroma.", "Stir continuously.Cool and use as required.", "For the Thalipeeth, in a mixing bowl add all the ingredients except ghee.Mix and add water to make a soft dough.", "Divide the dough into 4 to 5 portions.Grease a non-stick griddle (pan) with some ghee.", "Place one portion of the dough in the pan and pat with your fingers to make a circle (4-5 inch).Make a hole at the centre and 4 more around it using the tip of your finger.Drizzle some ghee in these holes.", "Cook covered on low heat till the underside cooks and turns brown.Flip and cook on the other side for a minute.", "Repeat for the rest of the dough.", "You can use a plastic sheet/banana leaf to pat the dough.Serve Upvas Thalipeeth along with\u00a0Dhaniya Pudina Chutney\u00a0and\u00a0Boondi Raita\u00a0for a perfect light dinner or breakfast."]'::jsonb, 50, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Upvas_Thalipeeth.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/891.Upvas_Thalipeeth.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gujarati Undhiyu Recipe - Mixed Vegetable With Fenugreek Dumplings', 'gujarati-undhiyu-recipe-mixed-vegetable-with-fenugreek-dumplings', 'Gujarati Undhiyu is a very popular and important vegetable that is made during auspicious family occasions, festivals and more importantly during the kite festival in Gujarat known as Uttarayan.', '["Undhiyu Vegetables", "2 tablespoons Ghee", "1 tablespoon Ajwain (Carom seeds)", "1/4 teaspoon Asafoetida (hing)", "1/2 cup Flat Green Beans , cut into 1/2 inch size pieces (surti beans or snow peas_", "1/4 cup Sweet Potatoes , peeled and cubed", "1/4 cup Elephant yam (Suran/Senai/Ratalu) , peeled and cubed", "1/4 cup Purple yam , peeled and cubed", "1/4 cup Raw Banana , peeled and cubed", "Salt , to taste", "Vegetables to be stuffed", "5 Small Brinjal (Baingan / Eggplant) , with 4 slits on top", "5 Baby Potatoes , peeled, with 4 slits on top", "1 cup Fresh coconut , grated", "1/2 cup Coriander (Dhania) Leaves , chopped", "4 cloves Garlic", "1 inch Ginger", "1 Green Chillies", "3 teaspoons Sesame seeds (Til seeds)", "3 teaspoon Coriander (Dhania) Seeds , roasted and powdered", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 tablespoon Lemon juice", "2 teaspoons Sugar", "1 teaspoon Salt , to taste", "Ingredients for methia muthia", "1/4 cup Methi Leaves (Fenugreek Leaves) , finely chopped", "1 cup Gram flour (besan)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Asafoetida (hing)", "1/4 teaspoon Enos Fruit Salt", "2 teaspoons Sugar", "1 Lemon , juice extracted", "1 teaspoon Oil", "Salt , to taste"]'::jsonb, ARRAY['undhiyu vegetables', 's ghee', 'ajwain', 'carom seeds', 'asafoetida', 'hing', 'flat green beans', 'sweet potatoes', 'elephant yam', 'suran/senai/ratalu', 'purple yam', 'raw banana', 'salt', 'vegetables to be stuffed', 'small brinjal', 'baingan / eggplant', 'baby potatoes', 'fresh coconut', 'coriander', 'dhania', 's garlic', 'ginger', 'reen chillies', 's sesame seeds', 'til seeds', 'turmeric powder', 'haldi', 'red chilli powder', 'lemon juice', 's sugar', 'ingredients for methia muthia', 'methi leaves', 'fenugreek leaves', 'gram flour', 'besan', 'enos fruit salt', 'lemon', 'oil']::text[], '["To begin making the Gujarati Undhiyu Recipe - Mixed Vegetable With Fenugreek Dumplings, we will firstly make the muthiyas.*Method To Make Methi Muthia:In a small bowl combine all the ingredients for the\u00a0muthia\u00a0adding very little water to make\u00a0firm\u00a0dough.", "Divide the dough into 15 small portions.", "Shape them into ovals and lightly press them down.To pan fry the methi muthia in a paniyaram pan; preheat the pan add oil into the cavities of the pan.", "Place the muthia in the cavities and drizzle a little more oil on the top.", "Flip and turn to cook the muthia on all sides.", "Pan fry the muthia until browned on all sides.", "You can alternatively steam the Muthia''s - Prepare a steamer and place the\u00a0muthia\u00a0in the steamer\u2019s colander and allow it to steam for 10 minutes on\u00a0medium-high\u00a0heat.", "After 10 minutes you will notice the colour has changed to golden yellow.T urn off heat; take the colander filled with\u00a0muthia\u2019s out of the steamer and keep aside.\u00a0*Method To Make Undhiyu:Add all the ingredients for the Masala into a mixer grinder, add 1/4 to 1/2 cup of water and grind to make a smooth paste.", "Fill the slit brinjals and baby potatoes with above filling mixture and keep aside.", "Keep the remaining filling aside.There are two ways you can do the Undhiyu, one in a pressure cooker, which is much faster and also in a pan where we slow cook the\u00a0Undhiyu.Pressure Cooker MethodInto a pressure cooker ; add in two tablespoons of ghee, add the ajwain seeds and allow it to crackle.", "Add the\u00a0 stuffed brinjal and baby potatoes.Add the yam, sweet potatoes, raw bananas and beans and layer it with the coconut mixture.", "Add 1/4 to 1/2 cup of water and pressure cook for 4 to 5 whistles and turn off the heat.", "Allow the pressure to release naturallyOnce the pressure released, add the pan fried muthai''s.", "Cover the pan and simmer for another 10 minutes and add more water if required.", "Cook until you notice all the vegetables and the\u00a0muthias\u00a0are well coated with the masala.Heavy Bottomed Pan MethodIn a heavy bottomed Pan\u00a0; add in two tablespoons of ghee, add the ajwain seeds and allow it to crackle.", "Add the\u00a0 \u00a0stuffed brinjal and baby potatoes and shall fry until partially cooked.", "This process is done on low heat, so it consumes less oil and also cooked evenly from the inside.Add the yam, sweet potatoes, raw bananas and beans and layer it with the coconut mixture.", "Add 1/4 to 1/2 cup of water and cover the pan and cook until the vegetables are cooked and coated well with the\u00a0masala.", "This takes about half an hour.Once its\u00a0three-fourth\u00a0done, add the pan fried muthai''s.", "Cover the pan and simmer for another 10 minutes and more water if required.", "Cook until you notice all the vegetables and the\u00a0muthias\u00a0are well coated with the masala.Adjust the taste by adding\u00a0more or less\u00a0of\u00a0salt.", "Check the consistency of the dish to see if you need to add more or less water to suit your taste.", "Turn off the heat and transfer to a serving dish.Serve the Gujarati Undhiyu hot garnished with chopped coriander leaves and fresh coconut.", "Undhiyu\u00a0on a festive occasion can be served along with\u00a0Methi Thepla,\u00a0Khandvi,\u00a0Puran Poli,\u00a0Kadhi,\u00a0Masala Chora Pulav,\u00a0Paka Kela Raita\u00a0and\u00a0Mohanthal."]'::jsonb, 85, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Gujarati_Undhiyu_recipe_Surti_Undhiyu__1-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/892.Gujarati_Undhiyu_recipe_Surti_Undhiyu__1-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Saragva Nu Shaak Recipe-Drumstick Masala Sabzi', 'saragva-nu-shaak-recipe-drumstick-masala-sabzi', 'The Saragva Nu Shaak Recipe-Drumstick Masala Sabzi is a wholesome and delicious way to consume the healthy drumstick vegetable. We often wonder how can we use all the goodness from the drumsticks in a vegetable. And very often it either goes into a dal or into a kadhi or in a sambar.', '["4 Drumstick , cut into 1-1/2 inch size pieces", "1 teaspoon Kalonji (Onion Nigella Seeds)", "1 inch Ginger , finely chopped", "1 sprig Curry leaves , roughly torn", "2 Bay leaves (tej patta) , roughly torn", "1 inch Cinnamon Stick (Dalchini) , broken", "3 Tomatoes , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "Red Chilli powder , to taste", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Cumin powder (Jeera)", "1 tablespoon Jaggery", "Salt , to taste", "6 sprig Coriander (Dhania) Leaves , finely chopped", "1 teaspoon Oil"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'ginger', 'kalonji (onion nigella seeds)', 'bay leaves (tej patta)', 'jaggery', 'red chilli powder', 'drumstick', 'curry leaves', 'coriander (dhania) leaves', 'cinnamon stick (dalchini)', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To make the\u00a0Saragva\u00a0Nu Shaak Recipe, we will first cook the drumsticks in a pressure cooker or a steamer.Heat the oil in a pressure cooker over medium heat; add the kalonji seeds, ginger curry leaves, bay leaves and cinnamon stick.Saut\u00e9 for a few seconds and add the chopped tomatoes, turmeric powder, coriander powder, cumin powder, red chili powder, salt , jaggery and saute the tomatoes until they soften just a bit.Add the drumstick and 1/4 cup of water and cover the pressure cooker.Pressure cook the\u00a0Saragva\u00a0Nu Shaak for about 3 to 4 whistles and turn off the heat.", "Allow the pressure to release naturally.Once the pressure has released, open the cooker, give the Saragva\u00a0Nu Shaak a stir.", "Check the salt and spices and adjust to suit your taste.", "Stir in the chopped coriander leaves and transfer the\u00a0Saragva\u00a0nu Shaak to a serving bowl and serve hot.Serve the\u00a0Saragva\u00a0Nu Shaak along with\u00a0Gujarati Dal\u00a0or\u00a0Gujarati Kadhi\u00a0along with a hot\u00a0Phulkas\u00a0for lunch or dinner."]'::jsonb, 30, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Saragvo_Nu_Shaak_Drumstick_Sabzi_Recipe_2-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/893.Saragvo_Nu_Shaak_Drumstick_Sabzi_Recipe_2-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Aloo Dum Recipe', 'bengali-aloo-dum-recipe', 'The Bengali Aloo Dum Recipe is a delicious recipe of potatoes that are simmered in spicy tomato onion garlic and a yogurt gravy. The potato is simmered in the dum aloo masala for a good 30 minutes until all the flavors are absorbed. Aloo Dum also known as Dum Aloo is a delicious spicy and tangy recipe that is a favorite at home.', '["Ingredients to be ground into paste", "1 inch Ginger , chopped", "2 Green Chillies , chopped", "1 Onion , roughly chopped", "4 cloves Garlic", "To roast Baby potatoes", "300 grams Baby Potatoes , boiled and skin peeled", "1 tablespoon Mustard oil", "Salt , to taste", "1 tablespoon Mustard oil", "4 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "4 Cloves (Laung)", "2 Bay leaf (tej patta)", "1 teaspoons Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "1-1/2 cup Homemade tomato puree", "1/2 cup Curd (Dahi / Yogurt)", "1 tablespoon Honey", "Salt , to taste", "6 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'mustard oil', 'cardamom (elaichi) podsseeds', 'bay leaf (tej patta)', 'red chilli powder', 'cloves garlic', 'curd', 'coriander (dhania) leaves', 'onion', 'cinnamon stick (dalchini)', 'baby potatoes skin', 'cloves (laung)', 'coriander powder', 'turmeric powder', 'green chillies', 'garam masala powder']::text[], '["To begin making Bengali Aloo Dum Recipe, add the onions, ginger, green chillies and garlic into the blender and grind into a smooth paste.", "Transfer the onion paste to a bowl and keep aside.In our next step we will be pan roasting the potatoes.", "For this heat 2 tablespoons of oil in a frying pan, add the boiled potatoes, a pinch of turmeric powder, and salt.Saute the potatoes till they are light golden brown in color.", "This process of roasting the potatoes gives a added flavor to the dish making it healthier and skipped the traditional process of deep frying them in oil.Once golden brown and lightly crisp transfer the potatoes to a bowl and keep aside.*Method for Making the Masala for the Bengali Aloo Dum:In the same frying pan, add 2 tablespoons of oil.", "Add in the onion, ginger and garlic paste.", "Saute the onions mixture on low heat until the paste turns golden and the raw smell goes away.This process takes a good 5 minutes.", "And yes , don''t worry about the grains from the potatoes stuck on the pan, it will all get absorbed and cleaned up when we cook it along with the masala.After about 5 minutes of sauteing the onion paste we will add an inch piece of cinnamon, a few cardamom, a few cloves and a large bay leaf.", "Stir to combine the spices and roast them along with the onions for a couple of more minutes until your smell the aromas.Once you get a roasted aroma from the spices, add in pureed tomatoes, a teaspoon of turmeric powder, a teaspoon of coriander powder and and a teaspoon of garam masala powder.Stir the ingredients until they are well combined into the onions paste.", "You can also add a teaspoon of chilli powder if you like it more spicy.When the spices are well combined with the onion mixture, add in about half a cup of yogurt and stir again and mix well.", "Next add in the potatoes and a teaspoon of sugar.Check the salt levels and add a little salt if required.", "Cover the pan and we will now simmer the potatoes on low heat for about 20 minutes.", "Make sure you stir the Aloo Dum masala occasionally once or twice in between.Once you notice that the Aloo Dum Masala has thickened and has coated well onto the potatoes it indicates that the dum aloo is ready.", "At this stage turn off the heat.Transfer the Bengali Aloo Dum into a serving dish.", "Stir the coriander leaves well into the aloo dum.", "It gives added flavor and freshness to the dum aloo.Serve\u00a0Bengali Aloo Dum\u00a0along with\u00a0Bengali Luchi,\u00a0Cholar Dal\u00a0and\u00a0Lauki Raita\u00a0for a delicious meal with your family."]'::jsonb, 70, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Bengali_Aloo_Dum_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/894.Bengali_Aloo_Dum_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kali Mirch Singhare Ki Sabzi Recipe', 'kali-mirch-singhare-ki-sabzi-recipe', 'Kali Mirch Singhare Ki Sabzi Recipe is a simple stir fry of water chestnuts that is tossed with pepper powder, turmeric powder and hing. Curry leaves and mustard seeds will add in the extra flavor to the dish and elevates the flavor.', '["300 grams Singhade (water chestnut)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1 teaspoon Black pepper powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 pinch Asafoetida (hing)", "Salt , to taste", "Oil"]'::jsonb, ARRAY['s singhade', 'water chestnut', 'mustard seeds', 'rai/ kadugu', 'curry leaves', 'black pepper powder', 'turmeric powder', 'haldi', 'asafoetida', 'hing', 'salt', 'oil']::text[], '["To begin making the Kali Mirch Singhare Ki Sabzi Recipe, pressure cook the water chestnuts along with their outer layer.", "Add about 1 cup of water and pressure cook for at least 4 whistle.Once done, peel the skin out and chop them into small pieces.", "Heat a kadai with oil, add mustard seeds and allow it crackle.Add in curry leaves, hing and let the curry leaves splutter for few seconds.", "Add cooked water chestnuts and sprinkle with pepper powder, turmeric powder, salt and stir fry for at least 5 minutes and switch it off.Serve the Kali Mirch Singhare Ki Sabzi Recipe along with\u00a0Pineapple Rasam,\u00a0Steamed Rice\u00a0to make to a complete meal after fasting."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Kali_Mirchi_Singhade_ki_Subzi_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/895.Kali_Mirchi_Singhade_ki_Subzi_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chole Biryani Recipe - Spicy Chana Biryani  Recipe', 'chole-biryani-recipe-spicy-chana-biryani-recipe', 'This Chole Biryani Recipe is a biryani with a difference. Instead of the usual combination of vegetables and meat, this one is made with protein packed chickpeas. Packed with proteins and carbohydrates and aromatics, give this recipe a try in your kitchen.', '["1 cup Rice , washed and soaked", "1 Cardamom (Elaichi) Pods/Seeds", "1 clove Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta)", "1/2 cup Milk", "1 1/2 cup Water", "1 teaspoon Ghee", "Salt , Salt to taste", "1/2 cup Onions , sliced", "2 teaspoons Oil", "1 Potato (Aloo) , cut into cubes & soaked in salt water", "1/2 teaspoon Amchur (Dry Mango Powder)", "1/2 teaspoon Red Chilli powder", "1/2 Cumin powder (Jeera)", "To be mixed into the rice", "1/4 cup Coriander (Dhania) Leaves , chopped", "1/4 cup Mint Leaves (Pudina)", "1 cup Kabuli Chana (White Chickpeas) , washed and soaked overnight.", "6 cloves Garlic , chopped", "1 inch Ginger , chopped", "1 Green Chilli , finely chopped", "1 teaspoon Garam masala powder", "1 teaspoon Red Chilli powder", "1/4 cup Curd (Dahi / Yogurt) , whisked", "1/2 teaspoon Turmeric powder (Haldi)", "1 Tomatoes , finely chopped", "1 tablespoon Ghee", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'cumin powder (jeera)', 'coriander (dhania) leaves', 'cloves garlic', 'kabuli chana (white chickpeas)', 'onion', 'turmeric powder', 'potato (aloo) salt water', 'sunflower oil', 'salt', 'clove cloves (laung)', 'green chilli', 'cardamom (elaichi) podsseeds', 'mint leaves (pudina)', 'garam masala powder', 'rice', 'red chilli powder', 'water', 'curd', 'ginger', 'amchur (dry mango powder)', 'bay leaf (tej patta)', 'ghee', 'milk', 'cinnamon stick (dalchini)']::text[], '["To begin making the Chole Masala Biryani Recipe, let us keep each of the elements ready."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sneha-archanaskitchen.com/Chole_Masala_Biryani_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/896.Chole_Masala_Biryani_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Kesar Pulao - Saffron Fennel Rice Recipe', 'kashmiri-kesar-pulao-saffron-fennel-rice-recipe', 'Kashmiri Saffron Fennel Rice Recipe, is rice cooked with saffron strands, fennel seeds, along with cloves and cinnamon that make this dish absolutely lip smacking. This subtly flavoured rice goes with a lovely robust gravy.', '["1-1/2 cups Rice", "1/4 teaspoon Saffron strands", "2 tablespoons Milk", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Fennel seeds (Saunf)", "1 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "Salt , to taste", "2 tablespoons Ghee"]'::jsonb, ARRAY['salt', 'rice', 'ghee', 'fennel seeds (saunf)', 'saffron strands', 'milk', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'cloves (laung)']::text[], '["To begin making the Kashmiri Saffron Fennel Rice Recipe/ Kashmiri Kesar Pulao, wash and soak the rice, completely immersed in water for 15 minutes.", "After 15 minutes drain the water and proceed to make the pulao.Heat milk in a bowl in the microwave for about a minute, remove from the microwave, add the saffron strands and allow it to sit.", "This will allow the flavours from the kesar get mixed into the milk.In a pressure cooker, heat ghee on medium flame, once hot, add the\u00a0cumin seeds,\u00a0fennel seeds,\u00a0cinnamon stick and\u00a0cloves.", "Once they begin to sizzle, add in the drained rice along with 3 cups of water, salt to taste and the saffron strands along with the milk.", "Close the pressure cooker and pressure cook the\u00a0Kashmiri Kesar Pulao for 2-3 whistles and turn off the flame.", "Allow the pressure to release naturally, open the cooker and transfer the Kashmiri Kesar Pulao into a serving dish.", "Serve\u00a0Kashmiri Saffron Fennel Rice/\u00a0Kashmiri Kesar Pulao Recipe along with\u00a0Kashmiri Rogan Josh Recipe and a side of\u00a0Kashmiri Style Nadir Monjvor Recipe - Lotus Stem Cutlets\u00a0for a complete Kashmiri meal as a weekend lunch or dinner."]'::jsonb, 25, 'Kashmiri', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sneha-archanaskitchen.com/Saffron_Rice_Kesar_Pulao_Yellow_Rice_-5.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/897.Saffron_Rice_Kesar_Pulao_Yellow_Rice_-5.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Healthy Fulkopir Paturi Recipe (Bengali Style Cauliflower Dumplings)', 'healthy-fulkopir-paturi-recipe-bengali-style-cauliflower-dumplings', 'This Fulkopir Paturi recipe is a vegetarian twist to the traditional Bengali ‘Paturi’, which is typically made with fish. Fish are marinated with spices dominated by mustard and then steam cooked in a banana leaf. In this vegetarian Paturi recipe, ''Fulkopir'' or Cauliflower is grated and marinated in a spicy paste. Since this dish is steam cooked, there is very less use of oil. The flavours of the marinade remains intact after steaming.', '["1 cup Cauliflower (gobi) , grated", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Red Chilli powder", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Sugar", "1 teaspoon Mustard oil", "Salt , salt to taste", "To Be Ground For Marination", "1 teaspoon Mustard seeds (Rai/ Kadugu) , powder using mortar and pestle", "3/4 teaspoon Poppy seeds , powder using mortar and pestle", "2 Green Chillies , chopped", "1/4 cup Fresh coconut , grated", "4 Garlic , cloves", "1/2 Banana leaf , to line the steamer", "1/2 Banana leaf , lightly toss in heat and cut them into squares and remove the stem", "10 Toothpicks", "Oil , few drops for greasing"]'::jsonb, ARRAY['garlic cloves', 'salt', 'poppy seeds powder using mortar pestle', 'banana leaf line the steamer', 'mustard seeds powder using mortar pestle', 'mustard oil', 'coconut', 'cauliflower (gobi)', 'red chilli powder', 'sunflower oil drops greasing', 'sugar', 'cumin seeds (jeera)', 'banana leaf toss heat them squares remove the stem', 'toothpicks', 'turmeric powder', 'green chillies']::text[], '["To prepare Healthy Fulkopir Paturi Recipe, wash and grate cauliflower and soak in hot water for 2-3 minutes.Drain the water, squeeze the grated cauliflower, and set them aside in a wide bowl.Grind together all the ingredients given under ''To Be Ground For Marination'' using very little water to make a thick paste.Add the ground paste, salt, sugar, turmeric powder, chilli powder, mustard oil, and cumin seeds to the cauliflower.Mix them well using your hands, cover and set it aside for 45 minutes.Line a Steamer with banana leaf.Take small portions of the marinated vegetables and shape them into dumplings using your hand.Place the shaped portion in the center of the cut banana leaf squares, close with banana leaf and seal them using a toothpick.Repeat this method for the remaining marinated cauliflower dumplings.Steam for 12- 15 minutes.Serve\u00a0Healthy Fulkopir Paturi Recipe\u00a0along with\u00a0Phulka,\u00a0Chirer Pulao, and\u00a0Chaler Payesh.", "It can also be served with plain cooked rice."]'::jsonb, 85, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Uma_Raghuraman/Fulkopir_Paturi__Bengali_Style__Cauliflower_Dumplings.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/898.Fulkopir_Paturi__Bengali_Style__Cauliflower_Dumplings.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lauki Yakhni Recipe - Bottle Gourd In Yogurt Gravy', 'lauki-yakhni-recipe-bottle-gourd-in-yogurt-gravy', 'Lauki Yakhini Recipe is a yogurt based gravy. This gravy is different from other gravy as they don''t contain garlic or onion. Lauki Yakhini Recipe Kashmiri dish where yogurt serves as the main ingredient. The gravy gets its flavor through cardamom and cloves. The dish is not too spicy and has very mild flavors. You can also try Yakhini with bitter gourd and cauliflower.', '["1 Bottle gourd (lauki)", "1 inch Cinnamon Stick (Dalchini)", "2-3 Cardamom (Elaichi) Pods/Seeds", "3-4 Cloves (Laung)", "1/2 teaspoon Ajwain (Carom seeds)", "1/2 teaspoon Dry ginger powder", "1 teaspoon Fennel Powder", "1/4 teaspoon Asafoetida (hing)", "1 cup Curd (Dahi / Yogurt)", "1 1/2 tablespoon Mustard oil", "Salt , as required"]'::jsonb, ARRAY['salt', 'mustard oil', 'cardamom (elaichi) podsseeds', 'asafoetida (hing)', 'ajwain (carom seeds)', 'curd', 'dry ginger powder', 'fennel powder', 'cinnamon stick (dalchini)', 'bottle gourd (lauki)', 'cloves (laung)']::text[], '["To begin with the Lauki Yakhini Recipe, let''s first cut lauki\u00a0(bottle gourd) into small cubes.Heat half a tablespoon oil in a\u00a0tawa. place the lauki in the tawa and let them fry until they are tender and brown.", "Once done keep them aside.", "Add some more oil in the same pan and add cloves, cinnamon stick, carom\u00a0seeds and saute until nice aroma comes out of it.Now bring down the flame and add water, bring the water to boiling point.", "As the water boils add the lauki\u00a0pieces, dry ginger powder, fennel powder, asafoetida and combine them well.Now take the yogurt in a bowl and whisk them and add to the Lauki (bottle gourd)Cook in medium flame until the curry becomes thick saucy consistency.", "Add required amount of salt and simmer the curry for a minute.Taste the gravy and if you feel it needs some more salt add them.", "Switch off the flame and garnish with coriander leaves.Serve\u00a0Lauki Yakhni Recipe\u00a0along with\u00a0Aamras\u00a0and\u00a0Tawa Paratha\u00a0for an everyday meal.", "You can also pack this for your Lunch Box."]'::jsonb, 50, 'Awadhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Lauki_Yakhni.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/899.Lauki_Yakhni.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Malai Kofta Curry Recipe - Creamy and Healthy Paneer Aloo Kofta Curry', 'malai-kofta-curry-recipe-creamy-and-healthy-paneer-aloo-kofta-curry', 'The Malai Kofta recipe is a delicious preparation paneer and potato balls simmered in a spiced tomato gravy. This recipe of kofta is a healthy twist to the traditionally deep fried kofta recipes that you would make.', '["Ingredients for Malai Koftas", "3 Potatoes (Aloo) , boiled, peeled and mashed", "1-1/2 cups Paneer (Homemade Cottage Cheese) , crumbled", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Red Chilli powder", "2 tablespoons Gram flour (besan)", "1/4 cup Coriander (Dhania) Leaves , finely chopped", "1/2 cup Sultana Raisins , a handful, to stuff the kofta\u2019s", "Salt , to taste", "Oil , for cooking", "Ingredients for Gravy", "1 tablespoon Ghee , for cooking", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "1 Onion , finely chopped", "2 cups Homemade tomato puree", "2 teaspoons Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Cardamom Powder (Elaichi)", "1 tablespoon Honey", "1/4 cup Fresh cream", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves) , for garnishing", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'coriander (dhania) leaves', 'paneer', 'ghee', 'red chilli powder', 'raisins', 'cloves garlic', 'gram flour (besan)', 'onion', 'cardamom powder (elaichi)', 'coriander powder', 'potato (aloo)', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the\u00a0Malai Kofta Recipe, combine all the ingredients for the koftas in a bowl and divide them into lemon size balls.Flatten the balls in the palm of your hands and place a couple of raisins in the center.", "Close the kofta dough back into a ball and keep aside.The next step is to cook the Malai Koftas either in the\u00a0Kuzhi Paniyaram PanIf you plan to use the Kuzhi Paniyaram Pan; then place the kofta balls in the pan''s cavities; drizzle the koftas with a little oil and pan fry them until golden brown on both sides.", "You will have to flip the kofta balls so they fry on all sides evenly.", "The next step is to make the Kofta CurryHeat oil in a heavy bottomed pan; add in the grated ginger, garlic, onions and saut\u00e9 for a few seconds until the onions soften.Stir in the tomato puree, honey, turmeric powder, cardamom powder, garam masala powder, coriander powder, salt and chilli powder to taste.Bring the kofta curry to a boil and simmer for a couple of minutes till the tomatoes get cooked through.Finally add in the cream and the kasuri methi and stir it into the kofta curry.Adjust the consistency of the malai kofta curry by adding water if required.", "Do make sure to check the salt and spice levels and adjust according to your taste.", "When you are ready to serve, place the kofta curry in the serving bowl and add the warm malai kofta balls in the curry, garnish with coriander leaves and serve hot.Serve\u00a0Non Fried Malai Kofta Recipe with\u00a0Tawa parathas\u00a0and\u00a0Mixed Vegetable Pulao Recipe\u00a0and\u00a0Mooli Raita\u00a0for lunch or dinner.", "You can even serve the Malai Kofta for a indian dinner party menu."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Healthy_non_fried_Malai_Kofta_recipe_Paneer_Aloo_Kofta_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/900.Healthy_non_fried_Malai_Kofta_recipe_Paneer_Aloo_Kofta_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Raw Papitha No Sambharo Recipe', 'raw-papitha-no-sambharo-recipe', 'Raw Papitha No Sambharo Recipe is a hot papaya stir fry that is served along with Fafda and kadhi when you walk into the streets of Gujarat early in the morning. In this recipe the raw papaya is stir fried along with green chillies and salt making it absolutely refreshing and tasty for breakfast.', '["1 teaspoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Turmeric powder (Haldi)", "2 Green Chillies , slit", "250 gram Raw papaya , grated", "Salt , to taste"]'::jsonb, ARRAY['gram papaya', 'salt', 'mustard seeds', 'asafoetida (hing)', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Papitha No Sambharo, first prep all the ingredients and keep them ready.", "Grate the papaya and keep it aside.Heal oil in a pan over medium heat; add the mustard seeds and cumin seeds.", "Allow them to crackle.", "Add the hing, green chillies, turmeric powder and the raw grated papaya along with salt.Stir fry until the papaya softens just a bit.", "Once done, turn off the heat and transfer the papitha nu sambharo to a bowl and serve.Serve\u00a0Raw Papitha No Sambharo along with\u00a0Khaman Dhokla,\u00a0Fafda, and\u00a0Green Chutney\u00a0for a high protein breakfast."]'::jsonb, 30, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Raw_Papitha_No_Sambharo_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/901.Raw_Papitha_No_Sambharo_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Milagu Sadam Recipe (Instant Pepper Rice)', 'milagu-sadam-recipe-instant-pepper-rice', 'I consider the variety in rice dishes is a blessing! When you are in a hurry to cook up a meal or too lazy to make an elaborate meal, the variety of rice dishes come handy. Not just that, variety rice recipes works fantastic for left over rice. I can safely call it instant rice dish( all you need is left over rice to be ready in hand). Among all the variety rice recipes, Milagu Sadam or Instant pepper rice is the most simplest. It’s a straight forward dish which uses minimal, common ingredients from your pantry.', '["1 cup Basmati rice , cooked", "1 Onion , finely chopped", "2-1/2 tablespoons Whole Black Peppercorns , freshly ground", "2 sprig Curry leaves", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1-1/2 teaspoon White Urad Dal (Split)", "10 Cashew nuts", "2 teaspoons Oil", "Salt , to taste"]'::jsonb, ARRAY['cashew nuts', 'basmati rice', 'salt', 'mustard seeds', 'black peppercorns ground', 'curry leaves', 'white urad dal (split)', 'onion', 'sunflower oil']::text[], '["To begin making the Milagu Sadam, heat oil in a heavy bottomed pan.Add mustard seeds and wait till they crackle.", "Add urad dal and saut\u00e9 till dal begins to turn brown.Add finely chopped onions and curry leaves.", "Saute till the onions turn translucent.Once it is done, add the cashew nuts in the pan.Add freshly ground pepper powder and salt to taste.", "Mix well and let it cook for a minute or 2 minutes.Add cooked basmati rice and gently toss it to coat the rice well with the pepper-onion mix.", "Check for seasoning, add more salt if needed.Turn off flame and serve immediately.", "Serve Milagu Sadam with\u00a0Tomato Onion Cucumber Raita\u00a0or\u00a0Boondi Raita\u00a0for a light and delicious weekday meal."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Milagu_Sadam.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/902.Milagu_Sadam.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dill Leaves Toor Dal Recipe - Shepu/ Suva Dal recipe', 'dill-leaves-toor-dal-recipe-shepu-suva-dal-recipe', 'The Dill Leaves Toor Dal Recipe is a delicious dal that can be cooked every day for lunch. Dill leaves is also called as Suva in Hindi, Sabsige Soppu in Kannada, Shepu in Marathi.', '["1-1/2 cups Arhar dal (Split Toor Dal)", "1 cup Dill leaves , chopped", "1 tablespoon Ghee", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1 Bay leaf (tej patta)", "1 Onion , finely chopped", "4 cloves Garlic", "1 inch Ginger", "2 Tomatoes , finely chopped", "1 Green Chilli , finely chopped", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 Lemon , juice extracted"]'::jsonb, ARRAY['tomato', 'salt', 'arhar dal (split toor dal)', 'dill leaves', 'ginger', 'green chilli', 'mustard seeds', 'ghee', 'bay leaf (tej patta)', 'red chilli powder', 'cloves garlic', 'onion', 'cumin seeds (jeera)', 'lemon', 'turmeric powder']::text[], '["To begin making the Dill Leaves Toor Dal Recipe, wash the dill leaves and finely chop it and keep it ready.", "Prep all the ingredients as well.In a pressure cooker, add a teaspoon of ghee and place it on medium heat.", "Add the mustard seeds and cumin seeds.Allow it to crackle.", "Once it crackles, add the chopped onion, ginger and garlic.", "Saute until the onions soften.Once the onions soften, add the tomatoes, green chillies, turmeric powder, red chilli powder, salt, dill leaves, toor dal and 3 cups of water and pressure cook for at least 4 to 5 whistles and turn off the heat.Allow the pressure to release naturally.Once the pressure released, open the lid and mash the dal coarsely using a muddler and check for seasonings.Adjust at this stage and bring it to a boil for few minutes and serve the Dill leaves dal over a serving bowl.", "Add in the squeeze of lemon and any additional ghee over the top.", "Turn off the heat.Transfer the\u00a0Dill Leaves Toor Dal to a serving bowl and serve hot.Serve the\u00a0Dill Leaves Toor Dal Recipe\u00a0along with\u00a0Phulka Recipe\u00a0and\u00a0Ringna Batata Nu Shaak Recipe\u00a0to make a wholesome weekend or weeknight lunch or dinner."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/North_Indian_Style_Dill_Leaves__Toor_Dal_Recipe__1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/903.North_Indian_Style_Dill_Leaves__Toor_Dal_Recipe__1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Restaurant Style Chettinad Style Fish Curry Recipe', 'restaurant-style-chettinad-style-fish-curry-recipe', 'Chettinad Style Fish Curry Recipe is a Spicy South Indian Style Fish curry which is best paired with Idiyappam''s or plain rice, the taste is different than the fish curry''s we normally eat.', '["5-6 Fish fillet , surmai or pomphret variety", "1 teaspoon Turmeric powder (Haldi)", "2 teaspoon Oil", "2 teaspoon Cumin seeds (Jeera)", "6 Whole Black Peppercorns , (adjust)", "3 Cloves (Laung)", "1/2 inch Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "2 Dry Red Chilli", "1 sprig Curry leaves", "2 teaspoon Fresh coconut , grated", "10 cloves Garlic", "1 inch Ginger", "2 Onions , chopped", "8 Pearl onions (Sambar Onions)", "1 Tomato , chopped", "4 teaspoon Tamarind Water , (adjust)", "Salt , to taste", "Water , as needed", "Coriander (Dhania) Leaves , to garish"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'tamarind water', 'cardamom (elaichi) podsseeds', 'coconut', 'black peppercorns', 'cloves garlic', 'dry red chilli', 'curry leaves', 'pearl onion (sambar onion)', 'water', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'onion', 'fish fillet surmai pomphret variety', 'coriander (dhania) leaves garish', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Restaurant Style Chettinad Style Fish Curry Recipe, clean the fish fillets and apply salt & turmeric powder on it.", "Keep aside.In a shallow fry pan\u00a0add oil & fry onions until they turn brownish, keep aside to grind later.", "Add the shallots & fry for 2 minutes then add tomatoes.", "Switch off the gas & keep the cover the pot with a lid.In a grinder, make a fine powder of cumin seeds, peppercorns, cloves, cinnamon, cardamom & red chilli.", "Keep aside for later use.Add the fried onions, ginger, garlic, grated coconut & tamarind to the make a smooth paste.Add the dry masala powder & paste to the tomato-onion, add water as required to make gravy.When the gravy comes to a boil add the fish, add curry leaves.", "Cover the pot n let the fish cook properly.", "Garnish with freshly chopped coriander.Don''t make the gravy too thick or watery.", "Serve this delicious and full of flavour\u00a0Chettinad Style Fish Curry Recipe along\u00a0with\u00a0Idiyappam''s or\u00a0Steamed Rice\u00a0and\u00a0Elai Vadam\u00a0for an everyday meal."]'::jsonb, 55, 'Chettinad', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Soni_Khadilkar/Chettinad_style_Fish_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/904.Chettinad_style_Fish_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pumpkin Kofta Curry Recipe', 'pumpkin-kofta-curry-recipe', 'Pumpkin Kofta Curry Recipe is a lighter version of a creamy and rich kofta curry. The koftas are made from a roasted pumpkin that is mashed to form a pulp and mixed along with besan and corn meal to bind. Then these are fried on to a kuzhi paniyaram pan until it crisp up. The crispy koftas are then dunk in a yogurt based spice curry. Pumpkin is considered as squash that is rich in Vitamin C and potassium. It is also good for the heart and rich in antioxidants.', '["150 grams Kaddu (Parangikai/ Pumpkin) , chopped small", "2 Potato (Aloo) , skin peeled and boiled", "1 tablespoon Red Chilli powder", "1 teaspoon Fennel seeds (Saunf) , crushed", "1 teaspoon Coriander Powder (Dhania)", "1/4 cup Corn flour", "2 tablespoon Gram flour (besan)", "2 sprig Coriander (Dhania) Leaves", "2 Onions , sliced", "1 Tomato , chopped", "1 inch Ginger , chopped", "2 cloves Garlic , chopped", "1 Green Chilli", "1 teaspoon Turmeric powder (Haldi)", "1 tablespoon Garam masala powder", "1 teaspoon Amchur (Dry Mango Powder)", "1 Cardamom (Elaichi) Pods/Seeds", "2 Cloves (Laung)", "1/2 cup Curd (Dahi / Yogurt)"]'::jsonb, ARRAY['tomato', 'corn flour', 'ginger', 'parangikai pumpkin', 'potato (aloo) skin', 'green chilli', 'fennel seeds (saunf)', 'amchur (dry mango powder)', 'cardamom (elaichi) podsseeds', 'red chilli powder', 'cloves garlic', 'gram flour (besan)', 'curd', 'coriander (dhania) leaves', 'onion', 'coriander powder', 'turmeric powder', 'cloves (laung)', 'garam masala powder']::text[], '["To begin making the Pumpkin Kofta Curry Recipe, we will first pressure cook the pumpkin and potatoes with water and salt for about 4 whistles.Allow the pressure to release naturally and drain all the water out.", "Mash the pumpkin and potatoes well.Heat a sauce pan add the mashed pumpkin along with all the spice powders and keep saut\u00e9ing until all the water has evaporated from it.Make sure the mixture dries up.", "Add corn flour besan, Salt and coriander leaves to the mixture and bring all of it together.", "You will get a sticky dough.", "Switch off the heat, allow it to cool down for some time.Meanwhile go ahead to make the curry, for that heat a sauce pan with oil, add onions, garlic and ginger and saute until it softens.Add tomatoes and sprinkle little salt so that it will help to become mushy easily.", "After 5 minutes of saut\u00e9ing add green chili along with all the spice powders except whole spice.Saute until all the spice powders have mixed well.", "Switch it off and cool it down and blitz it in the mixer along with curd to a smooth paste.", "Keep it aside.Shape the kofta dough into bite-size lemon balls and keep them aside. (About 8 to 10).", "If you plan to use the Kuzhipaniyaram Pan; then place the kofta balls in the pan''s cavities; drizzle the kofta''s with a little oil and pan fry them until golden brown on both sides.", "You will have to flip the kofta balls so they fry on all sides evenly.Heat a tablespoon of oil in a heavy bottomed pan, add cardamom pods and cloves.", "Pour in the curry paste and add about 1/4 cup of water and bring it to a boil.", "Check for salt.Once the Pumpkin Kofta curry has thickened, add in the pan fried Pumpkin Kofta Balls and simmer for another couple of minutes.Transfer the Pumpkin Kofta Curry into a serving bowl, garnish by drizzling with fresh cream or just coriander leaves.Serve the Pumpkin Kofta Curry along with phulka, naan or\u00a0Tawa paratha\u00a0along with a\u00a0subzi\u00a0by the side."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Pumpkin_Kofta_Curry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/905.Pumpkin_Kofta_Curry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mavinakayi Chitranna Recipe - Spiced Raw Mango Tempered Rice', 'mavinakayi-chitranna-recipe-spiced-raw-mango-tempered-rice', 'Mavinakayi Chitranna Recipe is a delicious preparation of rice from the raw green mangoes that you get in the summers. The tartness of the mangoes along with the green chillies and the seasonings, brings out the flavors of this classic South Indian Rice recipe.', '["2 cups Cooked rice , (leftover works fine)", "1 Mango (Raw) , grated", "1/2 teaspoon Black Urad Dal (Split)", "1 teaspoon Chana dal (Bengal Gram Dal)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Green Chillies , slit", "2 sprig Curry leaves", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon SSP Asafoetida (Hing)", "Salt , to taste", "Coriander (Dhania) Leaves , a small bunch, finely chopped", "1 tablespoon Gingelly oil"]'::jsonb, ARRAY['green chillies', 'salt', 'coriander (dhania)', 'mustard seeds', 'asafoetida (hing)', 'black urad dal (split)', 'mango', 'curry leaves', 'gingelly oil', 'rice (leftover works fine)', 'turmeric powder', 'chana dal (bengal gram dal)']::text[], '["To begin making the Mavinakayi Chitranna Recipe, we will first prepare the rice.If you don''t have day-old rice, cook your rice till fluffy, spread it out in a wide plate and allow it to cool completely.", "This helps in ensuring the rice doesn''t get soggy, sticky and clumpy.", "Follow\u00a0Steamed Rice Recipe - Pressure Cooker & Saucepan Methods\u00a0to cook rice.Next, heat gingelly oil in a heavy bottomed wok or kadai.", "Add the mustard seeds, chana dal, split urad dal and roast the dals on medium flame until the dals turn golden brown in colour.", "Once the dal turns golden brown, add in the curry leaves, asafoetida, and slit green chillies, saute for a few seconds until the aromas of the asafoetida and curry leaves come through.Now we will add the grated raw mango, turmeric powder and saute until the mangoes become a bit tender.", "This will take about 2 minutes.", "Once the mangoes have softened, add the cooked rice, salt to taste and stir well to combine.", "After 2 to 3 minutes,\u00a0 stir in the chopped coriander leaves, mix it well and switch of the gas.Taste Mavinakayi Chitranna and adjust salt, add more raw mango if required if you like it to be more tart.Transfer\u00a0Mavinakayi Chitranna to a serving bowl and serve hot.Serve the\u00a0Mavinakayi Chitranna Recipe\u00a0along with a\u00a0Tomato Onion Cucumber Raita\u00a0or\u00a0High-Protein Peanut Chutney\u00a0and a roasted papad for lunch or even for dinner.", "The\u00a0Mavinakayi Chitranna makes a great picnic lunch too."]'::jsonb, 45, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Mango_Chitaranna_Recipe_SSP_13_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/906.Mango_Chitaranna_Recipe_SSP_13_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Baale Dindu Kadale Palya - Banana Stem Curry With Chickpeas Recipe', 'baale-dindu-kadale-palya-banana-stem-curry-with-chickpeas-recipe', 'Baale Dindu Kadale Palya is South Indian Style Banana Stem Curry With Chick Peas Recipe. Select a banana stem which has a thin rind. Usually, the thinner the rind of the stem, tender is the banana stem. This banana stem curry is a healthy recipe since banana stem prevents the formation of kidney stones and is naturally fibrous to promote digestion. Banana stem pairs well with chickpeas and the flavors are subtle in this curry with fewer spices. Pair Baale Dindu Kadale Palya (Banana Stem Curry With Chick Peas Recipe) with rasam recipe to make a complete lunch.', '["1 Banana Stem , cleaned and chopped (about 250 grams after cleaning)", "1 cup Kala Chana (Brown Chickpeas) , soaked overnight", "2 tablespoons Fresh coconut , grated", "2 teaspoons Cumin seeds (Jeera)", "2 teaspoons Coriander (Dhania) Seeds", "1-1/2 teaspoon Red Chilli powder , (adjust)", "2 Onions , chopped", "1 clove Garlic , peeled", "Curry leaves , few sprigs", "Salt , to taste", "Oil , as required", "Coriander (Dhania) Leaves , few sprigs", "1 Green Chilli , one small green chilli", "1 teaspoon Lemon juice"]'::jsonb, ARRAY['salt', 'coriander (dhania) leaves', 'coconut', 'red chilli powder', 'cloves garlic', 'curry leaves', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'green chilli green chilli', 'lemon', 'banana stem ( after ing)', 'kala chana (brown chickpeas)', 'sunflower oil']::text[], '["To prepare\u00a0Baale Dindu Kadale Palya (Banana Stem Curry With Chickpeas Recipe), cut the extra portion of the banana stem, trim its top and bottom lightly, and chop the stem finely.Take a Pressure cooker, add soaked chickpeasAdd sufficient water and cook for 1-2 whistles.Allow to release pressure by itself.", "Add the chopped banana stem required salt and cook further for 1 more whistle.", "The chickpeas should be firm and not mushy.Heat a Kadai and dry roast coriander seeds till fragrant.", "Set aside.In the same Kadai, and add a little oil.", "Once the oil is hot, splutter cumin, add in curry leaves and saute for a few seconds.Add chopped onions, garlic and saute till cooked.In a Mixer, dry grind coriander and add all the sauteed ingredients with grated coconut and wet grind\u00a0till smooth, with adding water if necessary.After the pressure in the cooker with chickpeas and banana stem releases, add the ground paste in a kadai along with the contents of the pressure cooker.Add chilli powder and allow the Baale Dindu Kadale Palya to come to a boil.", "Adjust salt and switch off flame.Add lemon juice to the recipe and mix.Garnish with coriander leaves, chopped green chilli, and serve\u00a0Baale Dindu Kadale Palya hot with\u00a0rasam recipe."]'::jsonb, 65, 'Coastal Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Baalekaayi_Dindina_Palya_Raw_Banana_Stem_Chana_Dal_Curry_In_Coconut-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/907.Baalekaayi_Dindina_Palya_Raw_Banana_Stem_Chana_Dal_Curry_In_Coconut-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Kadle Kaalu Saru Recipe (Black Chickpea Curry Recipe)', 'karnataka-style-kadle-kaalu-saru-recipe-black-chickpea-curry-recipe', 'Karnataka Style Kadle Kaalu Saru Recipe (Black Chickpea Curry) is a comforting Indian gravy made from black chickpeas that is simmered in a delicious ground masala curry with a hint of an authentic Sambar Powder masala from Karnataka. This is one of the recipe that every household in Karnataka love to prepare and is a very easy recipe.', '["1 cup Kala Chana (Brown Chickpeas)", "1 teaspoon Jaggery", "2 tablespoon Sambar Powder", "1 tablespoon Red Chilli powder", "Salt , to taste", "2 sprig Coriander (Dhania) Leaves , finely chopped", "To grind", "1 Onions , chopped", "4 cloves Garlic , finely chopped", "2 sprig Curry leaves", "1/2 cup Fresh coconut , grated", "2 Tomatoes , boiled", "1 Onion , chopped", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "2 sprig Curry leaves"]'::jsonb, ARRAY['tomato', 'salt', 'coconut', 'mustard seeds', 'jaggery', 'red chilli powder', 'cloves garlic', 'curry leaves', 'coriander (dhania) leaves', 'onion', 'cumin seeds (jeera)', 'sambar powder', 'kala chana (brown chickpeas)']::text[], '["We begin making the Karnatak Style Kadle Kaalu Saru Recipe (Black Chickpea Curry) by soaking the black chickpeas in water for about 8 hours.Next is to roast the ingredients, for that heat a pan, add oil, curry leaves and saut\u00e9 the onions and garlic.", "Finally add the coconut.", "Saut\u00e9 till it is light brown.Once done, let it cool down and then grind it along with tomatoes into a smooth paste using a blender and keep it aside.Once the chickpeas is soaked, it is then pressure cooked in the same water in a pressure cooker for about half an hour.", "Release the pressure naturally.Place the cooker again on the heat, into the chickpeas add the ground mixture and then all the masala powders, season it well and let it boil for 15 minutes.Temper the ingredients, by crackling the mustard seeds, cumin seeds, curry leaves and saut\u00e9 the onions, once done add the tempering on to the curry and mix.Serve the Karnataka Style Kadle Kaalu Saru Recipe (Black Chickpea Curry) with hot\u00a0Phulka\u00a0or just relish it with some steamed rice."]'::jsonb, 30, 'South Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Karnatak_Style_Kadle_Kaalu_Saru_Recipe_Black_Chickpea_Curry_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/908.Karnatak_Style_Kadle_Kaalu_Saru_Recipe_Black_Chickpea_Curry_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kashmiri Style Modur Pulao With Pomegranate Recipe', 'kashmiri-style-modur-pulao-with-pomegranate-recipe', 'Kashmiri Modur Pulao With Pomegranate Recipe is essentially the pulao from Kashmir cuisine served usually with Paneer masala curry recipe.', '["1 cup Basmati rice , soaked for 1/2 hour", "3 Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "1 Cardamom (Elaichi) Pods/Seeds", "3/4 cup Milk , (adjust)", "1-1/2 cup Water", "1 pinch Saffron strands", "1 teaspoon Cumin powder (Jeera) , roasted", "1 teaspoon Oil", "Salt , to taste", "Fresh Fruits / Dry fruits and nuts", "1/2 cup Anardana Powder (Pomegranate Seed Powder) , cleaned", "2 teaspoon Cashew nuts", "3 teaspoon Whole Almonds (Badam)", "2-5 teaspoon Sultana Raisins , optional", "4 Dates , pitted and sliced", "Ghee , as required"]'::jsonb, ARRAY['cashew nuts', 'salt', 'cumin powder (jeera)', 'cardamom (elaichi) podsseeds', 'ghee', 'anardana powder (pomegranate seed powder)', 'milk', 'saffron strands', 'raisins', 'water', 'cinnamon stick (dalchini)', 'badam (almond)', 'basmati rice hour', 'dates', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making Kashmiri Modur Pulao Recipe first Soak saffron in 2 teaspoons of warm milk for about 10 minutes and crush it well.Wash and soak Basmati rice for half an hour.Next in a Biryani pot or a pressure cooker, heat ghee, add cinnamon, cloves and cardamom and saute for a while till aromatic.Drain excess water from soaked Basmati rice, add rice to the pan and saute for about 3 minutes on medium flame.Add saffron milk mix to rice and add 1/2 cup milk and 1/2 cup water and salt to taste.", "Cook covered until the rice is cooked well.", "In the pressure cooker leave it for about 2 whistle.Once rice is cooked, switch off and fluff it up with a fork and set aside.Just before serving, in a pan, fry the dry fruits and nuts including cashew nuts, badam, dates and raisins in a little ghee till they are golden brown.", "Keep a few fried cashews aside for garnishing.On a medium flame, add fried dry fruits and nuts to the fluffed up rice in the pot and mix well and switch off heat.", "While it is still warm, add the pomegranate and stir.", "Finally, add the roasted jeera powder and give it a good mix.Serve the\u00a0Kashmiri Modur Pulao Recipe\u00a0along with\u00a0Paneer Masala\u00a0and\u00a0Boondi Raita\u00a0to relish your mid day meals."]'::jsonb, 160, 'Kashmiri', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/2-feb/Kashmiri_Modur_Pulao_With_Pomegranate_-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/909.Kashmiri_Modur_Pulao_With_Pomegranate_-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Amritsari Sookhi Dal Recipe', 'amritsari-sookhi-dal-recipe', 'Dal/ lentils is full of proteins. This Punjabi dal is made using the urad dal/husked and split black gram. Urad dal is rich in iron, calcium, magnesium, folic acid and specially beneficial for women. Punjabi Cuisine is popular for it''s spiciness and this dish is no different. Lots of green chillies is used in this Dal. This dal is a traditional dish where the urad dal is cooked along with onions, tomatoes and masalas into a dry sabji.  Cilantro leaves are used generously to flavour this dish. A flavourful and protein packed side dish.', '["1/2 cup Black Urad Dal (Split)", "2 Onions , thinly sliced lengthwise", "2 Tomatoes , finely chopped", "3 Green Chillies , finely chopped", "1/2 inch Ginger , grated", "1/2 cup Coriander (Dhania) Leaves , finely chopped", "Salt , to taste", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Turmeric powder (Haldi)", "1 tablespoon Oil", "1/2 teaspoon Ajwain (Carom seeds)", "1/2 teaspoon Cumin seeds (Jeera)", "Asafoetida (hing) , a pinch", "1/4 cup Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'coriander (dhania) leaves', 'asafoetida (hing)', 'ajwain (carom seeds)', 'red chilli powder', 'black urad dal (split)', 'onionlengthwise', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Amritsari Sookhi Dal recipe, firstly wash the urad dal thrice and soak them in water for 30 minutes.Heat a kadai/wok with oil and temper with ingredients given under ''For tempering''.Now add the green chillies, garlic and the onions.", "Add salt and cook the onions till they turn transparent.Now, add the tomatoes, spice powders and cook them over low flame till the tomatoes become mushy.Add the soaked urad dal along with the water used for soaking.Cover and cook the dal it is is cooked well and the excess water is drained.", "Switch off and garnish with finely chopped cilantro.", "Your nutritious Amritsari Sookhi Dal can be served along with\u00a0Boondi Raita\u00a0and\u00a0Phulkas\u00a0for a weekday lunch."]'::jsonb, 50, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/umar/Amritsari_Sookhi_Dal_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/910.Amritsari_Sookhi_Dal_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Agathi Keerai Recipe', 'agathi-keerai-recipe', 'Agathi Keerai Recipe is a delicious preparation of a South Indian dish, where the greens tend to be lightly bitter. The Agathi Keerai is rich in Vitamin, A, Iron and Calcium and helps building strong bones. The Agathi leaves can be consumed in the form of juice or a cooked vegetables to get the maximum benefit.', '["500 grams Agathi keerai , washed and coarsely chopped", "1/4 cup Yellow Moong Dal (Split) , soaked for 2 hours", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)", "1 tablespoon Jaggery", "2 Dry Red Chillies", "3 tablespoons Fresh coconut", "1 teaspoon Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'yellow moong dal (split)', 'asafoetida (hing)', 'mustard seeds', 'coconut', 'jaggery', 'dry red chillies', 'cumin seeds (jeera)', 'agathi keerai', 'sunflower oil']::text[], '["To begin making the Agathi Keerai Recipe, we will first cook the Agathi Keerai and the Moong Dal.I am assuming the Moong Dal has been soaking for a couple of hours.", "When we soak it, it will take less time to get cooked along with the greens.", "Once soaked, drain the excess water from the dal.Place the chopped Agathi Keerai and the soaked Moong Dal into the pressure cooker.", "Add 2 to 3 tablespoons of water, sprinkle some salt and cover the pressure cooker.", "Place the weight on and pressure cook the greens and the lentils until you hear a couple of whistles.", "Turn off the heat after the couple of whistles and allow the pressure to release naturally.", "Once the pressure has released naturally, our next step is to season the Agathi Keerai.Heat oil in a pan, add the mustard seeds, cumin seeds, red chillies, curry leaves and asafoetida.", "Allow them to crackle.Add the steamed Agathi keerai and moong dal, coconut, jaggery and salt to taste.", "Stir gently to combine the ingredients for a couple of minutes.", "Check the salt and spice levels and adjust to suit your taste.", "Turn off the heat and transfer to a serving bowl and serve.Agathi Keerai can be served with\u00a0Mixed Vegetable Sambar\u00a0and Steamed Rice for a weekday lunch."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Agathi_Keerai_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/911.Agathi_Keerai_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thotakura Pappu Recipe (Toor Dal with Amaranth Leaves)', 'thotakura-pappu-recipe-toor-dal-with-amaranth-leaves', 'Thotakura Pappu Recipe (Toor Dal with Amaranth Leaves) is a very delicious dal recipe that is comforting to have it with a nice steamed rice and poriyal by the side. Amarnath leaves is a powerhouse of Iron, minerals and vitamins. It is considered as one of the super food and Ayurvedic friendly as well. The dal is made in just one pot and cooked with toor dal along with onions, tomatoes which adds in extra flavor to the dish. In Andhra amaranth leaves are called as Thotakura and Pappu is called as dal.', '["1 cup Arhar dal (Split Toor Dal)", "1 cup Green Amaranth Leaves , chopped", "1 Onion , sliced", "1 Tomato , chopped", "4 cloves Garlic", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Ingredients for tempering", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 pinch Asafoetida (hing)", "1 sprig Curry leaves", "2 Dry Red Chillies", "Oil"]'::jsonb, ARRAY['tomato', 'salt', 'arhar dal (split toor dal)', 'mustard seeds', 'asafoetida (hing)', 'cloves garlic', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'onion', 'green amaranth leaves', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Thotakura Pappu Recipe, we will add all the ingridients like dal, chopped amaranth leaves,onion, tomato, turmeric powder and salt in a pressure cooker.Add about 2 cups of water and pressure cook for atleast 4 whistle.", "Once done allow the pressure to release naturally and open the lid.", "Mash the dal and mix well with the cooked leaves.To temper, heat oil in a small kadai, add mustard seeds, urad dal and sprinkle hing allow it to splutter for few seconds.Add curry leaves and dry red chillies and allow them to crackle for few seconds and pour this hot tadka over the dal and mix well.", "Check for salt and serve hot.Serve the Thotakura Pappu Recipe with\u00a0steamed rice,\u00a0Andhra Style Kakarakaya Vepudu Recipe\u00a0to make it a complete meal."]'::jsonb, 35, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/_Thotakura_Pappu_Recipe_Toor_Dal_with_Amarnath_Leaves.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/912._Thotakura_Pappu_Recipe_Toor_Dal_with_Amarnath_Leaves.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Stuffed Bharwa Tinda Recipe (Stuffed Apple Gourd)', 'stuffed-bharwa-tinda-recipe-stuffed-apple-gourd', 'Stuffed Bharwa Tinda Recipe (Stuffed Apple Gourd) is a wonderful Punjabi style side dish made from the tender apple gourd that is stuffed along with tomato and onion gravy and cooked in a pressure cooker till the gravy has cooked along with the vegetables. The recipe uses a tender apple gourd as it is easy to stuff in the mixture whereas the mature ones have more seeds to be removed.', '["4 Tinda (Apple Gourd)", "1 Onion , chopped", "2 Tomatoes , chopped", "4 cloves Garlic , chopped", "1 inch Ginger , chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "2 teaspoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Amchur (Dry Mango Powder)", "1 pinch Asafoetida (hing)", "Salt , to taste", "Oil", "2 sprig Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['tomato', 'tinda (apple gourd)', 'cumin powder (jeera)', 'ginger', 'salt', 'amchur (dry mango powder)', 'asafoetida (hing)', 'red chilli powder', 'cloves garlic', 'coriander (dhania) leaves', 'onion', 'coriander powder', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Stuffed Bharwa Tinda Recipe, heat a kadai with oil, add ginger and garlic and saute until it softens.Add chopped onions and saute until they turn golden brown, at this point you can add chopped tomatoes and a bit of salt and saute till the tomatoes soften.Add all the spice powders and keep saut\u00e9ing until the masala combines well.", "Switch off the heat.", "Allow the mixture to rest for some time..In the meanwhile, peel the tinda or the apple gourds, slit them on the top cross wise.", "Do the same for the rest of the tinda.Grind the mixture in the grinder to form a smooth paste and start stuffing the mixture into the cut tinda as much as possible.Heat a pressure cooker, drizzle some oil place the stuffed tinda inside the pressure cooker and gently cook them on low heat.", "Add the remaining stuffed mixture also and sprinkle some salt and add a cup of water.Pressure cook them for about 3 whistle and allow the pressure to release naturally and serve hot with chopped coriander leaves.Serve the Stuffed Bharwa Tinda Recipe along with\u00a0jeera rice,\u00a0phulka\u00a0and\u00a0Sweet & Spicy Raw Papaya Moongfali Ki Subzi\u00a0by the side."]'::jsonb, 45, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Stuffed_Bharwa_Tinda_Recipe_Stuffed_Apple_Gourd_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/913.Stuffed_Bharwa_Tinda_Recipe_Stuffed_Apple_Gourd_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Seafood Stew Casserole With Tomatoes And Lime Recipe', 'spicy-seafood-stew-casserole-with-tomatoes-and-lime-recipe', 'Looking for healthy, light, filling dinner/lunch recipes? I have just a perfect recipe for you. It’s Seafood stew with tomatoes and lime. It has potatoes and carrots for adding more nutrients to the dish. This dish uses minimal oil and has a perfect balance of spice and tang. So thinking of healthy dishes to include in your menu plan, then this dish is just apt. Go ahead add it to your menu plan, and enjoy the dish. I have used coconut milk and olive oil in the stew. Coconut milk and seafood are best friends; the flavor of the dish is just perfect.', '["250 grams Fish fillet , basa", "250 grams Prawns", "15 Clamps", "5 Baby Potatoes", "2 Carrots (Gajjar)", "1 Onion", "1 Tomato", "2 Fresh Red chillies", "5 cloves Garlic", "1 teaspoon Cumin powder (Jeera)", "2 teaspoon Paprika powder", "Salt , to taste", "1 tablespoon Lemon juice", "1 teaspoon Black pepper powder", "4 tablespoon Coriander (Dhania) Leaves", "1 tablespoon Extra Virgin Olive Oil", "1 cup Chicken stock", "1/4 cup Coconut milk"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'red chillies', 'fish fillet basa', 'paprika powder', 'coriander (dhania) leaves', 'chicken stock', 'cloves garlic', 'carrot', 'virgin olive oil', 'onion', 'lemon', 'baby potatoes', 'black pepper powder', 'coconut milk', 'clamps', 'prawns']::text[], '["To begin making the Spicy Seafood Stew Casserole With Tomatoes And Lime recipe, clean basa fish and cut into small pieces.", "Clean, wash and devein the prawns.", "Wash well.I could not get clamps so I did not use it in the recipe but I highly recommend you to use it.Now marinate seafood in lime juice, 1 teaspoon salt and pepper powder for about 30 minutes.", "Let it marinate in the fridge.While the seafood is marinating in fridge, we will prepare the stew.In a wide pan, heat olive oil.", "Add minced garlic and saut\u00e9 till garlic turns golden brown.", "Add finely chopped onions and finely chopped red chilies.", "Cook till onions turn soft.Add finely chopped tomatoes and cook until tomatoes turn mushy.Add cumin powder, paprika power and remaining salt to taste.", "Add peeled potatoes and chopped carrots and give it a mix.Add chicken stock and bring it to boil.", "Cook till potatoes and carrots are fully cooked.", "Check for seasoning.", "Boil the stew for 5 to 8 minutes more.", "Add more stock if needed.Now add the marinated seafood and cook in low flame for about 8 to 10 minutes.Once the seafood is cooked, add coconut milk and continue to cook for a minute or two.Turn off the stove, add fresh chopped coriander leaves and serve hot with toasted bread.Serve Spicy Seafood Stew Casserole With Tomatoes And Lime along with steamed rice for a weekend lunch or dinner."]'::jsonb, 65, 'South Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Spicy_Seafood_Stew_Casserole_with_Tomatoes_and_Lime.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/914.Spicy_Seafood_Stew_Casserole_with_Tomatoes_and_Lime.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Punjabi Black Chickpea Curry Recipe - Kale Chane Ki Sabzi', 'punjabi-black-chickpea-curry-recipe-kale-chane-ki-sabzi', 'Black Chickpeas or Kala Chana are rich and protein and thus provides energy to our body. These can be used to prepare curries, side dishes, stir fries, etc. Here, we have shared a flavourful and delicious recipe of Punjabi Black Chickpea Curry in which Black Chickpeas is cooked with the everyday masala.', '["1 cup Kala Chana (Brown Chickpeas)", "4 tablespoons Oil", "1 teaspoon Cumin seeds (Jeera)", "1 Onion , finely sliced", "1 tablespoon Ginger Garlic Paste", "3 Tomatoes , pureed", "1 teaspoon Red Chilli powder", "1 teaspoon Salt", "1 teaspoon Garam masala powder", "Coriander (Dhania) Leaves , Handful, chopped", "Water , as needed"]'::jsonb, ARRAY['tomato', 'salt', 'garam masala powder', 'coriander (dhania) leaves', 'red chilli powder', 'water', 'ginger garlic paste', 'onion', 'cumin seeds (jeera)', 'kala chana (brown chickpeas)', 'sunflower oil']::text[], '["To begin making the Punjabi Black Chickpea Curry recipe, firstly wash the chickpeas with water a couple of times and then soak it in drinking water for at least 8 hours or overnight.", "Close with a lid and set aside.Next, take the chickpeas along with the water used for soaking in a pressure cooker, add 1/2 teaspoon salt, some more water if required and close the cooker.", "Pressure cook for about 8 to 10 whistles, switch off the heat and let the pressure release naturally.Once it is done, open the cooker and strain the chickpeas.", "Also reserve the water in a bowl.Heat oil in the same pressure cooker.", "Make sure you have wiped off the water before adding oil into the cooker.Add cumin seeds and saute it for about 10 seconds.", "After 10 seconds, add onions and cook till the onions become soft and translucent.", "Next, add the ginger garlic paste and let it cook for about 2 minutes.Next, add\u00a0salt, red chilli powder, tomato puree and cook for a few minutes on medium flame, till oil starts separating.", "This will take about 3 to 4 minutes.After 3 to 4 minutes, add garam masala, coriander leaves and the cooked chickpeas.", "Mix well and then finally add some more water.Close the lid of the pressure cooker and pressure cook for 2 whistles.", "Once it is done, switch off the heat and serve hot.Serve\u00a0Punjabi Black Chickpea Curry\u00a0along with\u00a0Jeera Rice,\u00a0Kachumber Salad\u00a0and\u00a0Boondi Raita\u00a0for a weekday meal.", "You can also pack the same meal in your lunch box."]'::jsonb, 40, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/amina/Punjabi_Black_chickpea_curry_Kale_chane_ki_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/915.Punjabi_Black_chickpea_curry_Kale_chane_ki_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lal Mathachi Bhaji Recipe - Amaranth Leaves Moong Sprouts Sabzi', 'lal-mathachi-bhaji-recipe-amaranth-leaves-moong-sprouts-sabzi', 'Lal Mathachi Bhaji Recipe is a simple stir fry of red amaranth leaves and sprouted green moong dal. The stir fry has simple Indian Spices like red chilli powder, salt and turmeric. A slight sweetness with the use of jaggery is added to balance the whole flavour.', '["2 cups Red Amaranth Leaves , roughly chopped", "1 cup Green Moong Sprouts", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)", "1 Onion , chopped", "4 cloves Garlic", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Jaggery", "Salt , to taste"]'::jsonb, ARRAY['salt', 'asafoetida (hing)', 'mustard seeds', 'red amaranth leaves', 'green moong sprouts', 'red chilli powder', 'cloves garlic', 'jaggery', 'onion', 'turmeric powder']::text[], '["To begin making the Lal\u00a0Mathachi\u00a0Bhaji Recipe,\u00a0let''s start prepping the leaves -\u00a0Wash the\u00a0Mathachi\u00a0Bhaji over running water and drain all the water.Chop the leaves along with the tender stem and keep aside.Into a pressure cooked, add the chopped amaranth leaves, the moong sprouts, a pinch of salt and 3 tablespoons water.", "Pressure cook for 3 to 4 whistles and turn off the heat.Release the pressure immediately to prevent the discoloration of the leaves.Heat oil in saut\u00e9ing pan over medium heat; add mustard seeds and a pinch of hing and allow it to crackle.Once it crackles, add the chopped garlic, onions and cook until the onions turn translucent.Stir in red chilli powder, turmeric powder, jaggery and the steamed amaranth leaves and the moong sprouts.Stir the\u00a0Lal\u00a0Mathachi\u00a0Bhaji for about 2 minutes until all the ingredients are well combined.", "Check the salt and spices and adjust to taste accordingly.Once the\u00a0Lal\u00a0Mathachi\u00a0Bhaji is done, turn off the heat and transfer to a serving bowl.Serve the\u00a0Lal Mathachi Bhaji Recipe\u00a0along with\u00a0Multigrain Methi Thepla Recipe\u00a0and\u00a0Kela Anar Raita Recipe\u00a0for\u00a0 a simple and delicious diabetic friendly meal."]'::jsonb, 40, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/April-18/Matha_Chi_Bhaji_Recipe_Green_Moong_Sprouts_and_Amaranth_Sabzi-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/916.Matha_Chi_Bhaji_Recipe_Green_Moong_Sprouts_and_Amaranth_Sabzi-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Punjabi Garam Masala Powder Recipe', 'punjabi-garam-masala-powder-recipe', 'Punjabi Garam Masala Powder Recipe is a must have spice powder mix for most Indian dishes and it''s fairly simple to make if you have measured all the ingredients right and roasted them well. This recipe was given to me by a neighbor when I was 18 years old.', '["50 Grams Cumin seeds (Jeera)", "50 Grams Cardamom (Elaichi) Pods/Seeds", "30 Grams Coriander (Dhania) Seeds", "30 Grams Whole Black Peppercorns", "20 Grams Fennel seeds (Saunf)", "10 Grams Cinnamon Stick (Dalchini)", "10 Grams Cloves (Laung)", "10 Grams Bay leaves (tej patta)", "10 Grams Dry ginger powder", "2 Nutmeg , whole nutmeg"]'::jsonb, ARRAY['grams cinnamon stick (dalchini)', 'grams bay leaves (tej patta)', 'grams cumin seeds (jeera)', 'grams black peppercorns', 'grams fennel seeds (saunf)', 'grams cloves (laung)', 'grams dry ginger powder', 'grams coriander (dhania) seeds', 'grams cardamom (elaichi) podsseeds', 'nutmeg nutmeg']::text[], '["To begin making the\u00a0Punjabi Garam Masala Powder Recipe, we will first get all the ingredients together and ready.Preheat a skillet on medium heat and roast all the ingredients together except the ginger powder, on low to medium heat until you can smell the aromas coming through.Make sure you keep stirring continuously, so the spices don''t get burnt.", "Once the spices are roasted well (about 4 to 5 minutes), turn off the heat and allow it to cool.Once the spices are cooled down, using a Food Grinder, make a fine powder of the spices.", "The Punjabi Garam Masala Powder is now ready.", "Store the Garam Masala in an airtight glass jar and use as and when required.", "For longer shelf like, you can freeze the bottle and use it as desired."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/BasicRecipes_Spice_Powders/Indian_Garam_Masala_Powder_Recipe-new.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/917.Indian_Garam_Masala_Powder_Recipe-new.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Jackfruit Seed Korma Recipe', 'jackfruit-seed-korma-recipe', 'Jackfruit Seed Korma Recipe is a must try recipe at home. The flavors of this curry is sensational.The whole spice used here- stone flower, star anise, cinnamon and cardamom add great character to the dish.', '["10 Jackfruit Seeds (Kathal)", "1 Stone flower", "1 Star anise", "1 inch Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "1 Bay leaves (tej patta)", "1 teaspoon Fennel seeds (Saunf)", "1 Onion , sliced", "2 cloves Garlic , chopped", "1 inch Ginger , chopped", "1 Green Chilli , chopped", "1 teaspoon Red Chilli powder", "1 tablespoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "Salt , to taste", "Ingredients to grind", "1/2 cup Fresh coconut , grated", "5 tablespoons Poppy seeds , roasted"]'::jsonb, ARRAY['salt', 'jackfruit seeds (kathal)', 'ginger', 'garam masala powder', 'green chilli', 'bay leaves (tej patta)', 'cardamom (elaichi) podsseeds', 'fennel seeds (saunf)', 'coconut', 'red chilli powder', 'cloves garlic', 'st flower', 'cinnamon stick (dalchini)', 'onion', 'poppy seeds', 'coriander powder', 'turmeric powder', 'star anise']::text[], '["To begin making the Jackfruit Seed Korma Recipe grind the roasted poppy seeds and coconut with water to a smooth paste and keep it aside.", "This is the korma masala.", "Heat a sauce pan on medium heat,\u00a0bring the water to boil, put\u00a0 the jackfruit seeds and allow it to boil for 20 minutes.Drain the water and by using a knife peel off the outer part (white part) of the skin and cut into half.", "Keep it aside.Heat a pressure cooker on medium flame, add oil, fennel seeds, bay leaf, stone flower, star anise, cinnamon and cardamom and fry for 10 seconds.Add sliced onions, ginger, garlic and green chilli and fry for about 5 minutes till the onions turn translucent.Next add the korma masala, along with spice powders-red chilli powder, turmeric, garam masala, coriander powder and salt.", "Mix well.Saute for 5 more minutes, add the cooked seeds and 1 cup of water and pressure cook for 1 whistle.Switch off the heat and allow the pressure to release naturally and serve hot.Serve the Jackfruit Seed Korma with\u00a0Malabar parotta\u00a0or\u00a0tawa paratha\u00a0with a glass of\u00a0Pudina Buttermilk Recipe\u00a0for a simple weekday meal."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Jackfruit_Seed_Korma_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/918.Jackfruit_Seed_Korma_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Calicut Payyoli Chicken Fry Recipe', 'calicut-payyoli-chicken-fry-recipe', 'Payyoli is a small municipal town on the Malabar Coast in Kerala, popular for it''s tasty Payyoli Chicken fry. Payyoli chicken fry is a great starter or can also be served as a side dish with rice or rolled inside rotis. This authentic Kerala recipe requires only few ingredients.  The trick to a perfect Payyoli chicken is to marinate the chicken twice. Try this authentic Payyoli chicken fry in your kitchen. Enjoy the goodness of kerala cuisine.', '["500 grams Chicken , cleaned and cut into 1 inch cubes", "1 teaspoon Garlic , minced", "1 teaspoon Ginger , minced", "2 teaspoons Kashmiri Red Chilli Powder", "1/2 teaspoon Turmeric powder (Haldi)", "2 tablespoon Vinegar", "1 Green Chilli , slit lengthwise", "1 tablespoon Meat masala", "3 tablespoons Fresh coconut , grated", "Salt , to taste", "2 sprig Curry leaves", "3 tablespoons Coconut Oil", "100 ml Water"]'::jsonb, ARRAY['salt', 'ginger', 'kashmiri red chilli powder', 'green chilli', 'coconut', 'water', 'chicken cubes', 'curry leaves', 'garlic', 'vinegar', 'coconut oil', 'turmeric powder', 'meat masala']::text[], '["To begin making the Calicut Payyoli Chicken Fry recipe, in a mixing bowl, marinate the chicken pieces with minced ginger, minced garlic, 1 tablespoon vinegar, turmeric powder and salt.", "Keep it aside for 15 minutes.For the second marination, to the already marinated chicken, add half the kashmiri red chilli powder, meat masala powder, remaining vinegar and mix well.", "Keep aside for 1 hour.Take grated coconut in a small bowl, add remaining kashmiri red chilli powder and mix well.", "Keep aside.Heat coconut oil in a pan, add the marinated chicken pieces in oil along with slit green chilly.", "Fry well on low flame.Once the chicken pieces are half cooked, add the grated coconut mix, and curry leaves to it.", "Add 100 ml water to allow the chicken to cook well.", "Fry until the water is fully absorbed, and the chicken is well cooked.Serve\u00a0Calicut Payyoli Chicken Fry as a starter for your house parties.", "You can serve it as part of a meal that includes,\u00a0\u00a0South Indian Style Fish Curry Recipe\u00a0and\u00a0Steamed Rice."]'::jsonb, 35, 'Kerala', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/foodiemomskitchen-gmail.com/Calicut_Payyoli_Chicken.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/919.Calicut_Payyoli_Chicken.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sindhi Kadhi Recipe', 'sindhi-kadhi-recipe', 'Sindhi Kadhi Recipe is a smooth, silky curry with vegetables and it is made by gently roasting besan or chickpea flour and adding a mixture of dal and vegetables to it.', '["1 cup Arhar dal (Split Toor Dal)", "1 Tomato", "1 cup Bhindi (Lady Finger/Okra) , slit lengthwise", "2 tablespoons Oil", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies", "10 Curry leaves", "1 pinch Asafoetida (hing)", "2 tablespoons Gram flour (besan)", "1 teaspoon Red Chilli powder", "1 tablespoon Tamarind Paste", "1 teaspoon Turmeric powder (Haldi)", "1 tablespoon Jaggery , powdered", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'arhar dal (split toor dal)', 'mustard seeds', 'asafoetida (hing)', 'jaggery', 'red chilli powder', 'curry leaves', 'gram flour (besan)', 'dry red chillies', 'methi seeds (fenugreek seeds)', 'bhindi (lady fingerokra)', 'tamarind paste', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Sindhi Kadhi Recipe, first wash and soak the toor dal for 1/2 an hour.", "Then put it in a pressure cooker along with tomatoes with enough water to completely submerge the dal.Close the lid of the pressure cooker and keep the whistle on.", "Pressure cook the dal until done, About 4 whistles and turn off the heat.Allow the pressure to release from the cooker naturally, then open the lid and mash the dal into a smooth mix using a potato masher or hand blender into a smooth pur\u00e9e.Place a deep pan on the heat, add 1 tablespoon oil and warm it.", "Then, add the slit okras and saute them on a medium flame until they are cooked through and lose the slime that okra tends to have.", "After about 6-7 minutes they will begin to crisp up.Transfer these okra onto a plate and set aside to be used later.In the same pan heat the remaining oil and warm it.", "Add mustard seeds, fenugreek seeds, asafoetida, curry leaves and red chillies in quick succession and let them crackle and crisp up.Once done add the besan next and saute lightly till the besan gets well coated with the oil, and browns evenly.", "You will know when he besan is roasted when it loses it''s raw aroma and starts smelling toasted.To this gradually add a cup of water while continuously whisking, making sure that there are no lumps.Once the besan mixture has mixed well with the water, add the pur\u00e9ed dal to it and mix well.", "Allow it to simmer gently, while adding the tamarind paste, jaggery powder and mixing again.Bring the Sindhi kadhi to a boil and allow it to simmer for a couple of minutes.Lastly, add the cooked okra and simmer for another 5 minutes till the Sindhi kadhi reaches a silky, thick gravy consistency and all the flavours combine well.Serve\u00a0Sindhi Kadhi Recipe with\u00a0Steamed Rice\u00a0and\u00a0Sindhi Tuk Patata\u00a0for a lovely meal."]'::jsonb, 70, 'Sindhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuri_Aggarwal/Sindhi_Kadhi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/920.Sindhi_Kadhi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Oriya Style Ghanta Tarkari Recipe (Mixed Vegetables Curry)', 'oriya-style-ghanta-tarkari-recipe-mixed-vegetables-curry', 'Ghanta Tarkari is a signature Odia recipe where variety of vegetables are cooked with soaked pulses and legumes in huge quantities and distributed among neighbors. Due to the presence of so many vegetables, the nutrient content of this curry is also high. This mixed vegetable dish from Odisha is somewhat similar in the lines of Aviyal of Kerala or Undhyoo of Gujarat. Though this curry is made during festivals throughout the year, but the Ghanta which is prepared the next day on the occasion of Dwitbahana Puja is something to remember.', '["1 cup Kaddu (Parangikai/ Pumpkin) , cut into cubes", "2 Potatoes (Aloo) , cut into cubes", "Long String Bean (chavli) , cut into 1 inches or you can use 10-12 french beans", "1 Ripe Bananas , raw, peeled and cut into cubes", "1 Mooli/ Mullangi (Radish) , cut into cubes", "1 Sweet Potatoes , peeled and cut into cubes", "2 Colocasia root (Arbi) , peeled and cut into cubes", "1/2 cup Elephant yam (Suran/Senai/Ratalu) , peeled and cut into cubes", "1 Brinjal (Baingan / Eggplant) , cut into cubes", "1/2 cup Vellai Poosanikai (Ash gourd/White Pumpkin) , peeled and cut into cubes", "5-6 Lima Beans , cut into 1 inch pieces", "1/2 cup Tomato , or raw mango or elephant apple, peeled and cut into pieces", "1/2 cup Cucumber , ripe, peeled and cut into cubes", "3 Pointed gourd (Parval) , cut into cubes", "3 Spine Gourd (Kankoda) , cut into cubes", "1 Ridge Gourd (Turai/ Peerkangai) , peeled and cut into cubes", "Fresh coconut , Grated", "1/4 cup Fresh coconut , chopped", "1/4 cup Ginger , grated", "1 Bay leaf (tej patta)", "1/2 cup Kala Chana (Brown Chickpeas) , soaked", "1/2 cup Green Moong Sprouts", "1 teaspoon Turmeric powder (Haldi) , 1 teaspoon turmeric powder", "Salt , to taste", "1 tablespoon Jaggery , powdered", "2-3 Dry Red Chillies , for tempering", "1 teaspoon Cumin seeds (Jeera)", "1/2 tablespoon Cumin powder (Jeera) , roasted", "1/2 tablespoon Red Chilli powder", "1 tablespoon Ghee"]'::jsonb, ARRAY['kaddu', 'parangikai/ pumpkin', 'potatoes', 'aloo', 'long string bean', 'chavli', 'ripe bananas', 'mooli/ mullangi', 'radish', 'sweet potatoes', 'colocasia root', 'arbi', 'elephant yam', 'suran/senai/ratalu', 'brinjal', 'baingan / eggplant', 'vellai poosanikai', 'ash gourd/white pumpkin', 'lima beans', 'tomato', 'cucumber', 'pointed gourd', 'parval', 'spine gourd', 'kankoda', 'ridge gourd', 'turai/ peerkangai', 'fresh coconut', 'ginger', 'bay leaf', 'tej patta', 'kala chana', 'brown chickpeas', 'green moong sprouts', 'turmeric powder', 'haldi', 'salt', 'jaggery', 'dry red chillies', 'cumin seeds', 'jeera', 'cumin powder', 'red chilli powder', 'ghee']::text[], '["To begin the preparation of Oriya Style Ghanta Tarkari, soak the kala chana for 3 to 4 hours, preferably overnight.Wash the green moong beans and soak overnight in enough water.", "Drain the water and clean properly.", "Wet a clean cotton cloth and wring excess water from it.", "Tie the moong daal in the cloth and keep it covered in a container for a day.", "When you open it , you should be able to see sprouts coming from it.Dry roast 1 tablespoon cumin seeds and 4 to 5 dry red chilies, cool and grind to a fine powder and keep aside.Wash and cut the vegetables.", "In a heavy bottomed vessel, add the potatoes, yam, colocasia, pumpkin, sweet potato, radish, kala chana along with 1 cup water, turmeric powder, salt, bay leaf, grated ginger and cook.", "Since these vegetables take long time to cook, you need to cook them first.After 5 minutes, add the rest of the vegetables and the chopped coconut, cover and cook on medium heat.", "You do not have to add more water as many of the vegetables will start releasing their own water.Once the vegetables are half done, add the elephant apple and the powdered jaggery and cook till all the vegetables are cooked perfectly.", "If you do not have elephant apple, you can add raw mango or tomatoes also.", "Remove from heat.", "Add the sprouted moong to it.In a pan, heat the ghee and add the red chillies and cumin seeds, once it starts to splutter, add the roasted cumin and red chilli powder to it and immediately pour this over the cooked vegetables.", "Add the grated coconut, mix well and cook on low flame for 4 to 5 minutes.Serve the Oriya Style Ghanta Tarkari hot with\u00a0phulkas\u00a0or steamed rice."]'::jsonb, 65, 'Oriya', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Alaka_Jena/Ghanta_Tarkari__Mixed_vegetables_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/921.Ghanta_Tarkari__Mixed_vegetables_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mambazha Mor Kuzhambu Recipe - Ripe Mango Mor Kuzhambu', 'mambazha-mor-kuzhambu-recipe-ripe-mango-mor-kuzhambu', 'Mambazha Mor Kuzhambu is a delicious mango curry made from ripe mangoes simmered in a delicious coconut and yogurt based gravy. The Mor Kuzhambu is also popularly known as Pulissery in Kerala and is often made with a variety of vegetables like ripe bananas, ash gourd, capsicum, drumstick, lady''s finger and carrots used either just as one vegetable or as a combination of 2 vegetables.', '["1 Mango (Ripe) , peeled and chopped into big pieces", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 cup Fresh coconut", "1 teaspoon Cumin seeds (Jeera)", "1 Green Chilli , or fry red chilli", "1 cup Curd (Dahi / Yogurt)", "Salt , to taste", "1 teaspoon Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1 sprig Curry leaves , as required"]'::jsonb, ARRAY['green chilli red chilli', 'salt', 'coconut', 'mango (ripe)', 'mustard seeds', 'curd', 'curry leaves', 'cumin seeds (jeera)', 'coconut oil', 'methi seeds (fenugreek seeds)', 'turmeric powder']::text[], '["To begin making the Mambazha Mor Kuzhambu\u00a0recipe, prep all the ingredients and keep it ready.The first step is the make a paste of the coconut mixture.", "Into a mixer grinder, add the coconut, cumin seeds, green chillies, salt and grind it along with 1/2 cup of warm water into a smooth paste.Warm water helps to blend the coconut into a much smoother mixture.Into a sauce pan, add the mangoes, coconut mixture, turmeric powder and water.", "Adjust the consistency of the gravy such that you have a thick pouring consistency.Give the\u00a0Mambazha Mor Kuzhambu a brisk boil for about 3 to 3 minutes and turn off the heat.", "Check the salt and adjust to taste accordingly.", "For the tadka, preheat a tadka pan over medium heat; add the oil and allow it to get warm.", "Once the oil is warm, add the mustard seeds and fenugreek seeds allow it to crackle.", "Stir in the curry leaves and turn off the heat.Pour this seasoning over the\u00a0Mambazha Mor Kuzhambu and give it a stir.", "Transfer the\u00a0Mambazha Mor Kuzhambu\u00a0to a serving bowl and serve hot.Serve Mambazha Mor Kuzhambu\u00a0along with\u00a0Steamed Rice,\u00a0Chow Chow Thoran\u00a0and\u00a0Elai Vadam\u00a0for a weekday meal."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/ssarchana-gmail.com/mambazha_mor_kuzhambu_recipe_Ripe_Mango_Kuzhambu_recipe-8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/922.mambazha_mor_kuzhambu_recipe_Ripe_Mango_Kuzhambu_recipe-8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharashtrian Masale Baath Recipe - Spicy Vegetable Rice with Goda Masala', 'maharashtrian-masale-baath-recipe-spicy-vegetable-rice-with-goda-masala', 'Maharashtrian Masale Bhat Recipe is a rice preparation from Maharashtra which gets it unique taste from the addition of Goda masala. The conventional Goda Masala provides the spicy and tangy flavour to this rice preparation. Along with rice plenty of colorful seasonal vegetables are also added to the Masala Bhath.', '["1 cup Rice", "1 Carrot (Gajjar) , peeled and cut into cubes", "1/2 cup Green beans (French Beans) , cut small", "1/2 cup Cauliflower (gobi) , cut into florets", "1 Potato (Aloo) , peeled and cut into cubes", "1 Onion , thinly sliced", "2 tablespoons Curd (Dahi / Yogurt)", "1 Bay leaf (tej patta)", "3 teaspoon Maharashtrian Goda Masala", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "Oil , as needed", "1 Asafoetida (hing)", "Salt , to taste", "Ingredients for the garnish", "10 Cashew nuts", "1 teaspoon Ghee", "1 tablespoon Fresh coconut , grated", "10 Cashew nuts", "1 teaspoon Ghee"]'::jsonb, ARRAY['cashew nuts', 'salt', 'green beans (french beans)', 'rice', 'bay leaf (tej patta)', 'mustard seeds', 'asafoetida (hing)', 'potato (aloo)', 'cauliflower (gobi)', 'ghee', 'coconut', 'carrot', 'curd', 'onion', 'maharashtrian goda masala', 'sunflower oil']::text[], '["To prepare the Maharashtrian Masale Bhath Recipe, first clean, wash and soak the rice in enough water for 30 minutes or so.Heat oil in a saucepan\u00a0over medium heat, add the mustard seeds, allow seeds to crackle.", "Add bay leaf and fry for few seconds.Add the sliced onions and fry till they turn light brown in color.", "Next add the all the chopped vegetables - carrot, beans, cauliflower, potatoes, onions and fry for the few minutes.", "Now add the yogurt and stir to combine, saute the vegetables for next few minutes.In the meanwhile heat 2.5 cups of water and bring it to a boil in an another pan.", "Add the rice along with red chili powder, goda masala, asafoetida, salt to the sauteed vegetables.", "Stir to combine and saute for a minute or so.", "Now add the hot water to the rice mixture.Cover the pan and simmer the rice on a low flame till the grains are softened and cooked well.If you are using the pressure cooker to cook the rice, turn off the heat after one or two whistle.", "Let the steam escape naturally from the pressure cooker before opening the lid.To serve Masala Baath, in a small pan heat ghee over medium heat, roast the cashews till golden brown in colour.", "Turn off the heat.Serve Maharashtrian Masale Bhat Recipe along with\u00a0Boondi Raita Recipe Spiced With Black Salt\u00a0and\u00a0Kothimbir Vadi Recipe (Maharashtrian Coriander Fritters)\u00a0\u00a0for the flavorful weekday lunch."]'::jsonb, 65, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Monika_Manchanda/Maharashtrian_Masale_Baath_Recipe-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/923.Maharashtrian_Masale_Baath_Recipe-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aam Chunda Pickle Recipe - Gujarati Mango Chunda Recipe', 'aam-chunda-pickle-recipe-gujarati-mango-chunda-recipe', 'The Chundo also known as Chunda or Khaman is a classic Gujarati sweet and sour mango pickle that is made with raw mangoes. Raw mangoes are grated and combined with sugar syrup and some spices to make this ever delicious Gujarati Chunda pickle.', '["5 cups Mango (Raw) , peeled and grated (1 kg of peeled and grated mango)", "2 teaspoons Salt", "1 teaspoon Turmeric powder (Haldi)", "4 cups Sugar , 840 grams of sugar", "1 teaspoon Red Chilli powder , optional", "2 teaspoons Cumin seeds (Jeera) , roasted & crushed"]'::jsonb, ARRAY['salt', 'sugarof sugar', 'mango', 'red chilli powder', 'cumin seeds (jeera)', 'turmeric powder']::text[], '["To begin making the Aam Ka Chunda Recipe, wash the mangoes and dry them completely.", "Peel the skin of the mangoes and then grate them.Combine the grated mangoes, salt and turmeric powder and leave aside for 2 hours.Once the mangoes have been marinated you will find that the mango has released some water.At this point stir in the sugar little by little to the mango mixture continuously until all the sugar is nearly dissolved.", "There are two different ways you can make this pickle."]'::jsonb, 40, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Quick_Mango_Chunda_Aam_Ka_Chunda_Recipe_Sweet_Mango_Pickle_Gujarati_Chundo_Pickle_recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/924.Quick_Mango_Chunda_Aam_Ka_Chunda_Recipe_Sweet_Mango_Pickle_Gujarati_Chundo_Pickle_recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tuna Rasam Bhaji Recipe (Tuna Sabzi Flavoured With Rasam Powder)', 'tuna-rasam-bhaji-recipe-tuna-sabzi-flavoured-with-rasam-powder', 'Tuna Rasam Bhaji is one of my favourite dishes. It is an extremely simple dish and goes best with daal and rice. The earthy flavour of the tuna fish paired with crunchy vegetable is delicious.', '["110 grams Canned tuna , (drained tuna from one standard tin)", "1 Onion , finely sliced", "1 Tomato , chopped to bite-size", "1 Green Bell Pepper (Capsicum) , julienned", "1 Potato (Aloo) , chopped to bite-size", "1 Carrot (Gajjar) , julienned", "3 Green Chillies , slit", "1 inch Ginger , julienned, (save a few strands of julienned ginger to garnish later)", "2 teaspoons Rasam Powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder , (optional)", "2 teaspoon Cumin seeds (Jeera)", "1/2 Lemon , juiced", "Salt , to taste", "Coriander (Dhania) Leaves , to garnish", "Oil , to saute", "Mixed vegetables , (optional)"]'::jsonb, ARRAY['s canned tuna', 'onion', 'tomato', 'reen bell pepper', 'capsicum', 'potato', 'aloo', 'carrot', 'gajjar', 'reen chillies', 'ginger', 's rasam powder', 'turmeric powder', 'haldi', 'red chilli powder', 'cumin seeds', 'jeera', 'lemon', 'salt', 'coriander', 'dhania', 'oil', 'mixed vegetables']::text[], '["To begin making Tuna Rasam Bhaji Recipe (Tuna Sabzi Flavoured With Rasam Powder), prepare the vegetables and drain the tuna from the can.Heat 1-2 teaspoons of oil in a large pan or kadai.Once the oil is hot, add Jeera, allow them to sizzle.Immediately after they start sizzling, add julienned ginger and slit green chillies and fry for about 10 seconds.Add the onions and fry on low-medium heat until they turn translucent and soft.Add the turmeric powder, chilli powder (optional), rasam powder and saut\u00e9.Add the remaining vegetables and fry for 2-3 minutes or until the veggies are cooked about halfway through.Add the canned tuna and mix until the masala has coated the fish.Adjust the salt and cook for about 8-10 minutes with covered lid, stirring every once in a while, avoiding any charring.Once done and the tuna is cooked, squeeze in the fresh lemon juice and garnish with coriander leaves and julienned ginger.Serve\u00a0Tuna Rasam Bhaji Recipe (Tuna Sabzi Flavoured With Rasam Powder) with\u00a0Phulka Recipe, and\u00a0Smoked Dal Makhani Dhaba Style Recipe, rice\u00a0with\u00a0Salad."]'::jsonb, 30, 'Fusion', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/roopakamath1997-gmail.com/Tuna_Rasam_sabzi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/925.Tuna_Rasam_sabzi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Methi Aur Kache Kele Ki Sabzi Recipe-Fenugreek Greens & Raw Banana Stir Fry', 'methi-aur-kache-kele-ki-sabzi-recipe-fenugreek-greens-raw-banana-stir-fry', 'Methi Aur Kache Kele Ki Sabzi Recipe is a stir fry recipe made from Fenugreek Greens & Raw Banana. These main ingredients are sauteed in a tadka of onions, tomatoes, ginger garlic paste and then combined with simple spices like red chilli powder, coriander powder, turmeric powder.', '["3 Raw Banana , cut into cubes", "1 cup Methi Leaves (Fenugreek Leaves) , roughly chopped", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1 tablespoon Ginger Garlic Paste", "1 Green Chilli , finely chopped", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoons Coriander Powder (Dhania)", "2 teaspoons Oil", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'green chilli', 'methi leaves (fenugreek leaves)', 'red chilli powder', 'ginger garlic paste', 'onion', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'banana', 'sunflower oil']::text[], '["To begin making\u00a0Methi Kache Kele Ki Sabzi Recipe, peel the skin of the plantains, chop them into cubes and place them in a bowl of water until further cooking.", "This step is to avoid oxidation and the raw bananas from turning brownish.Heat oil in a kadai, add the cumin seeds and let them splutter.Once they splutter, add the onions and saute till the onions turn translucent.Add the ginger garlic paste and saute for about a minute on low medium heat or till the raw smell vanishes.Once the ginger garlic are cooked thoroughly, add the tomatoes and green chillies, saute until the tomatoes turn mushy.Now add in the fenugreek leaves, red chilli powder, coriander powder and turmeric powder (haldi) and mix well.Let the fenugreek leaves wilt a bit; once they do, drain all the water from the raw bananas and add them to the kadai/pan.", "You can add a bit of water as well, to help them cook evenly and without sticking to the kadai.Season with salt and mix everything well.", "Cover and cook the\u00a0Methi Kache Kele Ki Sabzi.", "This will take around 10 minutes on medium heat.Once the plantains are cooked, saute\u00a0Methi Kache Kele Ki Sabzi till the water dry out.", "Switch off the heat.Serve\u00a0Methi Aur Kache Kele Ki Sabzi Recipe (Fenugreek Greens & Raw Banana Stir Fry) along with\u00a0Lobia Masala,\u00a0Tawa Paratha\u00a0and\u00a0Carrot Cucumber Tomato Salad."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Methi_Kache_Kele_Ki_Sabzi_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/926.Methi_Kache_Kele_Ki_Sabzi_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ridge Gourd Pachadi Recipe - Ridge Gourd Chutney', 'ridge-gourd-pachadi-recipe-ridge-gourd-chutney', 'Ridge gourd has many nutritional benefits as it is loaded with fibers, vitamins, and minerals. From an Ayurvedic point of view, ridge gourd increases vata and kapha, but it cools down and pacifies the dosha pitta in the body. Since the ridge gourd is low in saturated fat and cholesterol, it is the ideal diet for those who are looking for weight loss.', '["1 Ridge Gourd (Turai/ Peerkangai) , peeled and finely chopped", "2 Green Chillies , sliced", "2 teaspoons Tamarind Paste", "2 cloves Garlic , chopped", "1 teaspoon Cumin seeds (Jeera)", "Salt , to taste", "1 teaspoon Oil"]'::jsonb, ARRAY['salt', 'ridge gourd (turai peerkangai)', 'cloves garlic', 'cumin seeds (jeera)', 'tamarind paste', 'green chillies', 'sunflower oil']::text[], '["To begin making the Ridge Gourd Pachadi Recipe, in a skillet heat a teaspoon of oil.Add the chopped ridge gourd, green chillies, tamarind and saut\u00e9 on a low flame for 3-4 minutes or till ridge gourd is cooked and nicely coated in tamarind.Turn off the heat and let the mixture cool down before grinding.Put the cooked ridge gourd in a grinder along with the cumin and garlic.", "Grind to a smooth consistency using little water to get the desired consistency.But the pachadi should not be watery, instead it should be grainy and coarse in texture.", "Transfer Ridge Gourd Pachadi to a bowl.", "Check the salt and spices and adjust to suit your taste.Serve Ridge Gourd Pachadi with rasam, steamed rice and mixed vegetable curry."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Chutneys/Ridge_Gourd_Pachadi_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/927.Ridge_Gourd_Pachadi_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chicken Donne Biryani Recipe - Bangalore Shivaji Military Style', 'chicken-donne-biryani-recipe-bangalore-shivaji-military-style', 'Chicken Donne Biryani Recipe, is found and sold by many vendors and restaurants in almost all over the city of Bangalore.', '["500 grams Chicken , washed and cleaned", "1/2 cup Curd (Dahi / Yogurt)", "1 1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Lemon juice", "Salt , to taste", "1/2 cup Coriander (Dhania) Leaves", "1/4 cup Mint Leaves (Pudina)", "4 Green Chillies", "Other ingredients", "1 1/2 cups Seeraga (Jeeraga) Samba rice , washed and soaked", "2 tablespoons Oil", "1 Bay leaf (tej patta)", "1 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "1 Cardamom (Elaichi) Pods/Seeds", "2 Star anise", "2 Onions , thinly sliced", "1 1/2 tablespoons Ginger , finely chopped", "1 1/2 tablespoons Garlic , finely chopped", "Salt , to taste"]'::jsonb, ARRAY['salt', 'ginger', 'coriander (dhania) leaves', 'bay leaf (tej patta)', 'cardamom (elaichi) podsseeds', 'curd', 'cinnamon stick (dalchini)', 'chicken', 'lemon', 'seeraga (jeeraga) samba rice', 'onion', 'cloves (laung)', 'mint leaves (pudina)', 'garlic', 'turmeric powder', 'green chillies', 'star anise', 'sunflower oil']::text[], '["To begin making the Chicken Donne Biryani Recipe, thoroughly clean and wash the chicken pieces.*For the marinationIn a large mixing bowl combine the chicken, yogurt, turmeric powder, salt and lemon juice.", "Nicely massage the chicken for 5 minutes and then allow it to rest for a minimum of 30 minutes.*For the green biryani masalaIn a mixer-jar combine the coriander leaves, mint leaves, and green chilies and grind to a thick fine paste along with some water.", "Transfer to a bowl and set aside.To make the Donne Biryani, in a heavy bottomed pan, heat oil on medium flame, add all the whole spices including bay leaf, cinnamon stick, cloves, cardamom and star anise, let this sizzle.Once the whole spices have sizzled add ginger and garlic paste and the sliced onions, fry until the onions turn golden brown in colour.", "This will take about 5 minutes.", "Once the ginger-garlic-onion mixture has cooked well, add in the chicken pieces along with the marinade.", "Mix and continue to cook the entire mixture for 5-7 more minutes, stirring continuously.Finally add in the freshly ground green biryani masala and washed and drained rice, 3 cups of water into the pan.", "Give the\u00a0Chicken Donne Biryani a good mix and cover the pan.", "Turn the flame to the lowest heat.In a saucepan, boil water and turn off the flame and place this hot pan on the lid of the kadai.", "This process is done in order to seal the kadai in which the Chicken Donne Biryani is cooking.", "The heat from the hot water in the saucepan provides heat from the top.After 20-25 minutes open the lid to check if the chicken and rice is done.", "If its is done, lightly fluff up the Chicken Donne Biryani with a fork.", "Transfer the Donne Biryani into a serving plate and serve piping hot.Serve this\u00a0Chicken Donne Biryani Recipe\u00a0along with\u00a0Pudina & Dhaniya Raita Recipe,\u00a0Roasted Papad\u00a0and\u00a0Satvik Carrot Sprout Salad\u00a0for a hearty Sunday lunch."]'::jsonb, 70, 'Karnataka', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sneha-archanaskitchen.com/Chicken_Donne_Biryani_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/928.Chicken_Donne_Biryani_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Raw Banana & Ajwain Paratha Recipe', 'raw-banana-ajwain-paratha-recipe', 'Raw Banana & Ajwain Paratha Recipe is a healthy way to consume raw banana in the form of stuffed Paratha. The recipes is very simple and also filling for a breakfast or Lunch. Raw banana mixed with Ajwain gives it an earthy flavor to the whole dish.', '["1 1/2 cups Whole Wheat Flour", "Salt , to taste", "2 Raw Banana , boiled and mashed", "1 teaspoon Ajwain (Carom seeds)", "2 teaspoon Garam masala powder", "2 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "2 Green Chillies , finely chopped", "1 teaspoon Sugar", "2 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['salt', 'wheat flour', 'green chillies', 'amchur (dry mango powder)', 'ajwain (carom seeds)', 'sugar', 'coriander (dhania) leaves', 'coriander powder', 'turmeric powder', 'banana', 'garam masala powder']::text[], '["We begin making the Raw Banana & Ajwain Paratha Recipe by boiling the raw banana in the pressure cooker.", "Cut the banana into three pieces, remove the edges, boil it with water and salt for about 4 whistle.Once done, release the pressure naturally, remove the skin and mash it into a fine paste.", "Into this add the remaining ingredients and mix well.In order to make the dough, knead all the ingredients well into a soft dough Now to begin making the paratha, keep some flour aside for dusting.", "Divide the dough into large lemon side balls.Dust the dough portions in flour, flatten it and roll it into a 3 inch diameter circle.", "Place the filling on half side of the circle and close the paratha by folding it with the other half.", "Yes its as simple as that.", "We will have a semi-circle oval shape.", "Press the sides of the paratha down to seal the edges and gently using the rolling pin to flatten it.", "Take care, the filling can ooze out if the dough is rolled out too thin.Now to cook the Paratha, first preheat the skillet on medium heat.", "Place the rolled paratha on top and allow it to cook on one side.", "After about 10 to 15 seconds, flip the paratha.At this stage, smear some oil or ghee to cook the paratha.", "Cook the paratha by flipping over a couple of times until you see golden brown spots on both sides.Proceed the same way with the remaining dough portions and serve the Raw Banana & Ajwain Paratha Recipe Paratha with Raita and Sweet Lime Pickle for\u00a0Breakfast meal."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Raw_Banana__Ajwain_Paratha_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/929.Raw_Banana__Ajwain_Paratha_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Stuffed Makai Paratha Recipe (Corn & Coriander Stuffed Flat Bread)', 'stuffed-makai-paratha-recipe-corn-coriander-stuffed-flat-bread', 'The Stuffed Makai Paratha Recipe is made from a stuffing made from sweet corn, fresh coriander leaves and green chilies. This paratha is packed with fiber and nutrition that comes from corn and whole wheat flour (Chakki Atta - Raita.', '["Ingredients for dough", "2 cups Whole Wheat Flour", "1/2 teaspoon Salt", "1 teaspoon Oil", "Ingredients for makai paratha stuffing", "2 cups Sweet corn , steamed", "2 Green Chillies , finely chopped", "1 tablespoon Coriander (Dhania) Leaves , finely chopped", "1 teaspoon Cumin powder (Jeera) , (roast & ground)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'wheat flour', 'coriander (dhania) leaves', 'cumin powder (jeera) (roast ground)', 'sweet corn', 'green chillies', 'sunflower oil']::text[], '["To begin making the Stuffed Makai Paratha Recipe, we will first need to make the dough for the parathas.", "In a large bowl add in 2 cups of whole wheat flour and some salt.", "Use your fingers and stir in the salt into the flour.Add water a little at a time and knead to make soft, pliable dough.", "Knead dough for a couple of minutes until the dough is smooth and elastic.", "Use the fold press and knead motion to make the dough smooth.Next we will add a teaspoon of oil to coat the dough and knead little more.", "You want a dough that will be soft smooth and not sticky.Next we will divide the dough into 8 to 10 equal portions.", "Cover the dough and allow the dough to rest until you the filling ready.While the dough is resting, we will prepare the filling for the paratha.Into a food processor, add the steamed sweet corn, chopped green chillies, chopped coriander leaves and pulse to get a coarse mixture.", "Transfer this mixture to a mixing bowl; add the salt and cumin powder and stir well to combine.", "Check the salt and spice and adjust to suit your taste.Divide the filling into 8 to 10 equal portions.", "This process of dividing and keeping the portions of dough and filling ready, helps you gauge the number of makai parathas you can make and if you need more or less of the filling.Take a dough portion dust it in flour and flatten it on the rolling board by pressing it down.", "Roll the dough out into approximately 3 inch diameter circles dusting with flour in between to prevent the dough from sticking to the surface.", "Now place the a portion of the filling onto the circle and bring the dough from the sides towards the center to cover the filling.Once the filling is sealed from the inside, flatten the dough, dust it in flour and and roll it gently to make a paratha.", "Give it a gentle roll with the pin to even it out, if you press and roll too hard, there are chances the filing will come out.", "Proceed the same way with the remaining dough and filling portions.Now we will get into the final steps of cooking a Makai paratha, preheat a skillet on medium heat and place the filled dough.Allow it to cook on medium heat for about 30 to 45 seconds and flip over.", "Add this stage add a teaspoon of ghee or oil and spread it around.Flip again, so the oiled side can cook on the skillet.", "Spread a little more ghee and keep pressing the parathas while on the skillet to cook the paratha evenly from inside out.Do the flipping over process a couple of times until both sides get cooked, browned and crisp evenly.", "Make sure you cook on medium heat as it allows the makai parathas to get a crisp on the outside and yet soft texture.Once the paratha is cooked transfer to a plate.", "Continue to the remaining dough portions the same way.The Stuffed Makai Paratha makes a perfect breakfast or even a quick weeknight dinner that you can have along with a favorite\u00a0Raita."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breads/Corn_Coriander_Stuffed_Paratha_Recipe_Vegetarian_Healthy-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/930.Corn_Coriander_Stuffed_Paratha_Recipe_Vegetarian_Healthy-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paka Kela Ki Sabzi Recipe | Paka Kela nu Shaak | Gujarati Jain Recipe', 'paka-kela-ki-sabzi-recipe-paka-kela-nu-shaak-gujarati-jain-recipe', 'Paka Kela Ki Sabzi Recipe is a Gujarati Jain dish that is made from ripe bananas, that are sautéed with turmeric, asafoetida, curry leaves and chillies. The sweet and spicy combination that arises from the bananas and chillies makes it a delectable dish.', '["3 cups Ripe Bananas , cubed", "1/4 cup Gram flour (besan)", "1/4 teaspoon Asafoetida (hing)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves , finely chopped", "2 teaspoons Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'bananas', 'asafoetida (hing)', 'mustard seeds', 'red chilli powder', 'gram flour (besan)', 'curry leaves', 'cumin seeds (jeera)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Paka Kela Nu Shaak; prepare all the ingredients and keep them ready.Heat oil in a pan on medium high; add the mustard seeds, cumin seeds and curry leaves and allow it to crackle.Add the asafoetida, turmeric powder, red chilli powder and give it a stir.Stir in the banana and the besan into the above seasoning and stir gently until the gram flour and condiments gets well coated around the ripe banana, for about 3 to 4 minutes.", "Turn off heat and transfer to a serving dish.Serve\u00a0Paka Kela Ki Sabzi along with of\u00a0Phulka,\u00a0Gujarati Dal\u00a0and a bowl of dahi.", "Note: The Paka Kela Ki Sabzi has to be prepared just a few minutes before you are ready to serve your meal.", "When it stays for a longer time, the bananas tend\u00a0 to lose their texture and the dish can get too soggy."]'::jsonb, 30, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Paka_Kela_Nu_Shaak_paka_Kela_Sabzi_Ripe_Banana_Sabzi_recipe_5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/931.Paka_Kela_Nu_Shaak_paka_Kela_Sabzi_Ripe_Banana_Sabzi_recipe_5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Turai Moong Dal Recipe - Turia Mag Ni Dal', 'turai-moong-dal-recipe-turia-mag-ni-dal', 'Turai Moong Dal, also known as Turiya Mag Ni Dal, has a subtle sweetness that it gets from the ridge gourd (turai) itself. When combined with some spices and cooked along with the lentils it imparts a soft and tender texture to the palate.', '["To Cook Dal", "1 cup Yellow Moong Dal (Split)", "2 cups Water", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Salt", "1 teaspoon Oil", "1 teaspoon Cumin seeds (Jeera)", "1 inch Ginger , finely chopped", "1 Green Chillies , slit", "1 Tomato , finely chopped", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander (Dhania) Powder", "1 Bay leaf (tej patta) , torn", "1 inch Cinnamon Stick (Dalchini) , broken", "1 Ridge Gourd (Turai/ Peerkangai) , peeled and diced", "1/2 Lemon , juice extracted", "Salt , to taste", "6 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['tomato', 'salt', 'yellow moong dal (split)', 'ginger', 'bay leaf (tej patta)', 'ridge gourd (turai peerkangai)', 'red chilli powder', 'water', 'coriander (dhania) leaves', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'coriander (dhania) powder', 'lemon', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Turai Moong Dal Recipe, first prep all the ingredients and keep them ready.Add the\u00a0 moong dal in the pressure cooker along with salt and turmeric powder.", "Cover the cooker and pressure cook the dal for 3-4 whistles and turn off the heat.", "Allow the pressure to release naturally.", "Keep this cooked dal to the side.", "You don''t have to mash the dalNext to make the Turai Masala, heat oil in a pressure cooker; add the cumin seeds, ginger and green chillies and give it a stir.Add the tomatoes, turmeric powder, red chilli powder, coriander powder and salt to taste.", "Saute the tomatoes until it slightly softens.Next add the cut ridge gourd/ turai sabzi and give it a stir.", "Add 1/4 cup of water, cover the pressure cooker and cook for 2 whistles and turn off the heat.", "Allow the pressure to release naturally.Once both the cookers have released the pressure, open and add the cooked moong dal to the turai masala.Give it a stir and taste and check if it needs more salt and adjust to taste accordingly.Give the Turai Moong Dal a brisk boil for 2 minutes and turn off the heat.Stir in the chopped coriander leaves and the lemon juice and transfer the Turai Moong Dal/ Turia Mug Ni Dal to a serving bowl and serve hot.Serve this\u00a0Turia Mug Ni Dal/ Turai Moong Dal\u00a0along with\u00a0Sukhi Aloo Sabzi\u00a0and\u00a0Thepla\u00a0that are almost necessity to be made along with this dish.Another favorite combination that we love is to pour a ladle full of Turai Moong Dal over hot bowl rice topped with melted ghee."]'::jsonb, 30, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Turai_Moong_Dal_Turia_Mug_Ni_Dal_Gujarati_Recipe_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/932.Turai_Moong_Dal_Turia_Mug_Ni_Dal_Gujarati_Recipe_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Batata nu Shaak Recipe - Aloo Tamatar Ki Sabzi', 'batata-nu-shaak-recipe-aloo-tamatar-ki-sabzi', 'Batata Nu Shaak or Aloo Tamatar Ki Sabzi is a simple and delicious recipe made with potatoes that are simmered in a tangy tomato gravy spiced with cinnamon and coriander. Potatoes are a staple food in every Gujarati home and many other regional homes of India and this Batata Nu Shaak is an absolute favorite in every gujarati home.', '["4 Potatoes (Aloo) , peeled and cut in 1 inch cubes", "2 teaspoon Oil", "1 teaspoon Kalonji (Onion Nigella Seeds)", "1 inch Ginger , grated", "1 Onion , finely chopped", "1 inch Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta)", "2 Tomatoes , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste"]'::jsonb, ARRAY['potatoes', 'aloo', 'oil', 'kalonji', 'onion nigella seeds', 'ginger', 'onion', 'cinnamon stick', 'dalchini', 'bay leaf', 'tej patta', 'tomatoes', 'turmeric powder', 'haldi', 'red chilli powder', 'garam masala powder', 'coriander powder', 'dhania', 'salt']::text[], '["To begin making the Batata Nu Shaak Recipe/ Aloo Tamatar Sabzi, heat a pressure cooker with oil\u00a0on medium heat; add the kalon, and allow the kalonji seeds and allow it to crackle.Add ginger, onion, cinnamon stick, bay leaf and saute until the onions soften.Once the onion softends, add the tomatoes, turmeric powder, red chilli powder, coriander powder, garam masala powder and salt.Saute the tomatoes until it becomes soft.Once soft, stir in the aloo/ batata and add water till it covers the potato.Cover the pressure cooker\u00a0and pressure cook the batata nu shaak/ aloo tamatar sabzi for 4 to 5 whistles.", "After 4 to 5 whistles turn off the heat and allow the pressure to release naturally.Once the pressure releases, check the taste and adjust the salt and spices accordingly.Stir in the chopped coriander leaves and transfer the\u00a0Batata Nu Shaak / Aloo Tamatar Sabzi\u00a0 to as serving bowl and serve hot.Serve\u00a0Batata nu Shaak\u00a0 / Aloo Tamatar Sabzi along with\u00a0Methi Thepla\u00a0or\u00a0Puri,\u00a0Kadhi,\u00a0Desi Chana,\u00a0and\u00a0steamed rice\u00a0for a delicious lunch or dinner."]'::jsonb, 20, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Aloo_Tamatari_Sabzi_Batata_Nu_Shaak_Aloo_Tamatar_Sabzi_5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/933.Aloo_Tamatari_Sabzi_Batata_Nu_Shaak_Aloo_Tamatar_Sabzi_5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kasuri Methi Chole Recipe', 'kasuri-methi-chole-recipe', 'Kasuri Methi Chole Recipe is a delicious chickpeas cooked in kasuri methi (dried fenugreek leaves) curry. It has no onion-garlic or dairy products added into it, making it suitable for vegans. Chickpeas are a high in proteins and insulin making it a perfect food to be included in the diets of diabetics and high blood pressure. It also aids in bone health. The addition of kasuri methi adds a strong aroma and makes the dish even more delicious.', '["400 grams Kabuli Chana (White Chickpeas) , soaked overnight and boiled", "1/2 cup Kasuri Methi (Dried Fenugreek Leaves)", "2 Tomatoes , pureed", "8 Cashew nuts", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "1 Bay leaf (tej patta)", "1 tablespoon Oil", "1 Green Chilli , finely chopped for garnish", "Salt , to taste", "1 Cinnamon Stick (Dalchini)", "3 Cloves (Laung)", "1 teaspoon Cumin seeds (Jeera)", "2 tablespoons Coriander (Dhania) Seeds"]'::jsonb, ARRAY['s kabuli chana', 'white chickpeas', 'kasuri methi', 'dried fenugreek leaves', 'tomatoes', 'cashew nuts', 'red chilli powder', 'turmeric powder', 'haldi', 'garam masala powder', 'bay leaf', 'tej patta', 'oil', 'reen chilli', 'salt', 'cinnamon stick', 'dalchini', 'laung', 'cumin seeds', 'jeera', 's coriander', 'dhania']::text[], '["To begin making the Kasuri Methi Chole Recipe, wash and soak the chickpeas overnight and pressure cook for 3 whistles using a pressure cooker and keep aside.Make a smooth puree of the tomatoes and keep aside.Take a pan, dry roast the ingredients mentioned in the spice mix table on low flame till aromatic and grind it to a coarse mix using a mixer grinder and keep aside.Add oil to the same pan, add the bayleaf, tomato puree, turmeric and red chilli powder and saute for 2 to 3 minutes until the oil separates out.Now, make a smooth paste of the cashew using a mixer grinder with little water.Add the cashew paste, garam masala and the ground spice mix to the pan and saute until everything comes together.Now, add the kasuri methi, boiled chickpeas and water to your desired consistency.Season with salt and let the gravy simmer for 10 minutes till it become thick and switch off the flame.Garnish with chopped green chillies and serve hot.Serve the Kasuri Methi Chole Recipe, along with\u00a0Phulkas\u00a0and\u00a0Palak Raita\u00a0for the weeknight dinner."]'::jsonb, 35, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Kasuri_Methi_Chole_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/934.Kasuri_Methi_Chole_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mushroom Ghee Roast Recipe', 'mushroom-ghee-roast-recipe', 'Mushroom Ghee Roast Recipe is a finger licking good recipe made of mushrooms made the South Indian way. Cooked in ghee made similar to that of a Mangalorean ghee roast.', '["400 grams Button mushrooms , cut into quarters", "4 tablespoons Curd (Dahi / Yogurt)", "1/2 teaspoon Turmeric powder (Haldi)", "1 tablespoon Lemon juice", "6 Dry Red Chillies", "1 teaspoon Whole Black Peppercorns", "2 Cloves (Laung)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Cumin seeds (Jeera)", "2 teaspoon Coriander (Dhania) Seeds", "6 cloves Garlic", "1 tablespoon Tamarind Paste", "Other Ingredients", "2 tablespoons Ghee", "2 sprig Curry leaves", "2 teaspoons Jaggery", "Salt , to taste"]'::jsonb, ARRAY['salt', 'ghee', 'jaggery', 'black peppercorns', 'cloves garlic', 'curd', 'curry leaves', 'dry red chillies', 'coriander (dhania) seeds', 'lemon', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'tamarind paste', 'button mushrooms', 'turmeric powder', 'cloves (laung)']::text[], '["To begin making the Mushroom Ghee Roast Recipe, we will first marinate the mushrooms."]'::jsonb, 35, 'Fusion', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Affiliate-Articles/Mushroom_Ghee_Roast_Recipe_6_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/935.Mushroom_Ghee_Roast_Recipe_6_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Brown Rice In Pressure Cooker Method', 'brown-rice-in-pressure-cooker-method', 'Whole Rice grains with only hull removed is called brown rice. The brown rice is unpolished and hence has all the nutrition of the bran and germ intact. Whole rice has a mild nutty flavor and this rice is particularly rich in thiamine, a B vitamin and iron.', '["1 cup Brown Rice", "Salt , if required", "2 cups Water"]'::jsonb, ARRAY['brown rice', 'salt', 's water']::text[], '["To begin making the Brown Rice Recipe in Pressure Cooker Method, rinse the rice well under running water.", "Place one cup of washed rice along with two cups of water in the pan of the pressure cooker.Keep the weight on, cover the pressure cooker.", "Cook the rice in the pressure cooker on medium high heat and after 3 to 4 whistles turn the heat to low.", "Once you turn the heat to low, simmer the rice for 5 minutes.", "After 5 minutes, turn off the heat and allow the pressure to release naturally.", "Rice takes a longer time to cook, hence wait for the pressure to release completely and then open the cooker and use as desired.Serve\u00a0Brown Rice\u00a0Recipe with\u00a0Cabbage And Carrot Thoran,\u00a0North Karnataka Style Nuggekai Harbyaali\u00a0and\u00a0Homemade Yogurt\u00a0for a comforting meal."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Brown_Rice_in_Pressure_Cooker_Method.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/936.Brown_Rice_in_Pressure_Cooker_Method.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Paratha Recipe - Healthy North Indian Breakfast', 'aloo-paratha-recipe-healthy-north-indian-breakfast', 'Aloo Paratha Recipe is a classic Spiced Indian Potato paratha made from boiled potatoes flavored with onions, green chillies, coriander. Traditionally these parathas are cooked in ghee and had with a dollop of butter. The addition of Ghee makes these parathas crispy and delicious.', '["Ingredients for the Dough", "2 cups Whole Wheat Flour", "1 teaspoon Salt , as required", "Water , to knead the dough", "Ghee , for cooking", "Ingredients for the Filling", "4 Potatoes (Aloo) , boiled and mashed", "2 Onions , finely chopped", "1 inch Ginger , finely chopped", "2 Green Chillies , finely chopped", "1/2 teaspoon Turmeric powder (Haldi) , optional", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 teaspoon Amchur (Dry Mango Powder)", "1/4 cup Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['ingredients for the dough', 's whole wheat flour', 'salt', 'water', 'ghee', 'ingredients for the filling', 'potatoes', 'aloo', 'onions', 'ginger', 'reen chillies', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'cumin powder', 'jeera', 'red chilli powder', 'garam masala powder', 'amchur', 'dry mango powder', 'coriander']::text[], '["To begin making the Aloo Paratha Recipe, first we will make the paratha dough.", "In a large bowl add in 2 cups of whole wheat flour and some salt.Use your fingers and stir in the salt into the flour.", "Add water a little at a time and knead to make soft, pliable paratha dough.", "Knead paratha dough for a couple of minutes until the dough is smooth and elastic.", "Use the fold press and knead motion to make the dough smooth.Next add a teaspoon of oil to coat the paratha dough and knead little more.", "You want a paratha dough that will be soft smooth and not sticky.", "Divide the dough into 8 to 10 equal portions.", "Cover the dough and allow the it to rest until you get the filling ready.The next step is to make the filling for the aloo parathas.Mash the potatoes into a coarse lumpy texture with your fingers or a fork.Once mashed, add in the green chillies, onions, coriander leaves, salt to taste, cumin powder, coriander powder, dry mango powder, garam masala, turmeric powder and finally if you want it extra spicy, the red chilli powder.", "Using your fingers again, mix all the ingredients into the potatoes until well combined.Divide the aloo paratha filling into 8 to 10 equal portions.", "This process of dividing and keeping the portions of aloo paratha dough and filling ready, helps you gauge the number of parathas you can make and if you need more or less of the filling.The final step is to stuff the filling into the aloo paratha dough.Dust the paratha dough in dry wheat flour, flatten it with your finger and place it on a flat surface.", "Roll them out thin to approximately 3 inches in diameter circle.Take a portion of filling and place it in the center.", "Next gather the sides of the paratha dough and bring them together.", "Remove the little excess dough which pops out when you bring the edges together.", "Press the filled aloo paratha dough down.Dust the filled aloo paratha dough in some flour and roll it gently applying very little pressure.", "Roll it to desired thickness and proceed the similar way with the remaining portions of paratha dough and filling.Preheat a skillet on medium heat and place the filled aloo paratha.", "Allow it to cook on medium heat for about 30 to 45 seconds and flip over.Add this stage add a teaspoon of ghee or oil and spread it around.", "Flip again, so the oiled side can cook on the skillet.", "Spread a little more ghee and keep pressing the parathas while on the skillet to cook the paratha evenly from inside out.Do the flipping over process a couple of times until both sides get cooked, browned and crisp evenly.", "Make sure you cook on medium heat as it allows the aloo parathas to get a crisp on the outside.Once the aloo paratha is cooked transfer to a plate and serve hot.Serve the\u00a0Aloo Paratha\u00a0along with\u00a0Aam Ka Achaar Recipe\u00a0or\u00a0\u00a0homemade curd\u00a0or\u00a0Masala Chaas\u00a0for your Breakfast."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Punjabi_North_Indian_Aloo_Paratha_Recipe_Authentic_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/937.Punjabi_North_Indian_Aloo_Paratha_Recipe_Authentic_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tisrayanche Suke Recipe (Goan Clams Dry)', 'tisrayanche-suke-recipe-goan-clams-dry', 'If you are a Goan, and love shellfish, then you will definitely like this seafood recipe. Tisreo or tisrya means clams. The recipe is very simple and it just tastes amazing. You can make this as a side dish with your meal.', '["500 grams Clams", "1/2 cup Fresh coconut , grated or dry coconut", "1 Onion , finely chopped", "2 Green Chillies , slit into halves", "4 Kokum (Malabar Tamarind)", "1 teaspoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Water , as required"]'::jsonb, ARRAY['salt', 'kokum (malabar tamarind)', 'clams', 'red chilli powder', 'water', 'onion', 'coconut dry coconut', 'turmeric powder', 'green chillies']::text[], '["To begin making the Tisrayanche Suke recipe, first we will clean the clams.", "First open them into halves using a sharp knife.Then with a knife, lift all the flesh from one shell, and drop it in the other and discard the shell with no flesh.Repeat for all the remaining clams.", "Wash them well for 3 to 4 times.Apply turmeric powder and keep it aside for 10 minutes.In a heavy bottom vessel, add these clams, and cook on medium high heat, uncovered for 5 minutes, mixing in between.If you feel the clams are too dry, then add a tablespoon of water.", "Usually you don\u2019t require water for this.Now add coconut, chopped onions, slit chillies, red chilli powder.", "Mix well.Serve Tisrayanche Suke along with\u00a0Goan Fish Curry\u00a0and Steamed Rice for a weekday meal with your friends and family."]'::jsonb, 50, 'Goan', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/Tisrayanche_Suke__Goan_Clams_Dry_recipe_edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/938.Tisrayanche_Suke__Goan_Clams_Dry_recipe_edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Golpapdi Recipe | Gur Papdi | Sukhdi recipe | Gujarati Gol Papdi', 'golpapdi-recipe-gur-papdi-sukhdi-recipe-gujarati-gol-papdi', 'Golpapdi also known as Sukhdi or Gur Papdi is a traditional Gujarati sweet dish made from whole wheat flour and jaggery which makes it a super wholesome and healthy sweet. It is typically prepared during auspicious occasions in a Gujarati household. It is perfect for those days when you have unexpected guests, or you have to whip up something sweet in a jiffy.', '["1 cup Whole Wheat Flour", "1/4 cup Ghee", "1/2 cup Jaggery , powdered/ grated", "1 teaspoon Cardamom Powder (Elaichi) , freshly ground", "1 teaspoon Dry ginger powder", "2 tablespoons Dessicated Coconut", "1/4 cup Whole Almonds (Badam) , fine sliced"]'::jsonb, ARRAY['wheat flour', 'ghee', 'coconut', 'jaggery', 'cardamom powder (elaichi) ground', 'dry ginger powder', 'badam (almond)']::text[], '["To begin making the Golpapdi Recipe (Gol Papdi/ Sukhdi), melt the ghee in a frying pan and add the wheat flour and cardamom powder and ginger stirring constantly till it turns golden brown and releases the roasted aroma.", "This process takes about 10 minutes on medium heat.", "Ensure the heat is not on high as it will burn the wheat flour too quickly.Once the wheat flour has turned a good brown color, turn off the heat and quickly add the jaggery and stir well, so the jaggery melts quickly in the heat into the wheat flour.Note: The addition of jaggery to the wheat flour mixture is a tricky procedure.", "The whole mixture can get brittle and gooey.", "So use caution, and turn off heat just before adding jaggery.As soon as the jaggery melts, and the mixture is still warm, pour the mixture into a greased baking sheet and spread it evenly with a 3/4th inch thickness.Sprinkle the sliced almonds and coconut and cut into diamond/square shapes while it is still warm.", "Set the Golpapdi / Gur Papdi / Sukhdi aside and allow it to sit untouched, you can also refrigerate it for it to set faster.", "After about an hour, once the it has cooled, you will find that the crisp Golpapdi is ready.Store the Golpapdi /\u00a0Gur Papdi / Sukhdi in airtight containers for about 2 weeks in the refrigerator for maximum freshness.Serve the\u00a0Golpapdi Recipe / Gur Papdi / Sukhdi as a delicious Tea Time Snack or After School Snacks."]'::jsonb, 30, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Gol_Papdi_Golpapdi_Gur_Papdi_Sukhdi_Recipe_Gujarati_Sweet_12_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/939.Gol_Papdi_Golpapdi_Gur_Papdi_Sukhdi_Recipe_Gujarati_Sweet_12_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ari Pathiri Recipe | Malabar Rice Flatbread Recipe', 'ari-pathiri-recipe-malabar-rice-flatbread-recipe', 'Ari Pathiri Recipe | Malabar Rice Flatbread Recipe are thin flat breads made of rice flour, and I wouldn’t say it’s exactly a breeze to prepare as you need to work with hot dough; need to knead and shape the rice dough while it’s hot or it will crack, and is not easy to roll the dough into thin sheets. But I must say – it’s worth the effort! Pathiri can be served with any gravy curries. You can serve Ari Pathiri Recipe | Malabar Rice Flatbread Recipe with Kerala Chicken Curry Recipe With Freshly Ground Spice.', '["1-1/2 cups Rice flour , roasted or pathiri podi", "1-1/2 cups Water", "Salt , to taste", "1 teaspoon Coconut Oil"]'::jsonb, ARRAY['pathiri podi', 'salt', 'coconut oil', 'water']::text[], '["To prepare Ari Pathiri Recipe | Malabar Rice Flatbread Recipe, in a wide pan, bring the water to rolling boil.", "Add the salt and oil.Now turn the heat to low and slowly add the rice flour, while continuously stirring with a wooden spoon till the dough comes together.", "Cover the pan and let the dough cook for about 10 seconds.", "Turn the heat off and continue to knead the dough with wooden spoon or spatula.Grease your palms with some coconut oil and knead the dough with your hands while it\u2019s still warm to a soft and non-sticky dough.", "Make sure you do not add more water or flour while kneading the dough.Divide the dough into equal lime sized balls and press it between your palm and on a slightly floured (rice flour) surface roll each ball into thin circle or you can use a pathiri press/roti press.Heat a griddle pan/flat pan over medium heat.", "When the pan is heated through, dust the excess flour off and cook each pathiri for 20-30 seconds on each sides while pressing gently with back of a flat ladle till it puffs up.", "Pathiri should not change the colour (off white-ish) so make sure that your pan is not over heated.Serve Ari Pathiri Recipe | Malabar Rice Flatbread Recipe with Kerala Chicken Curry Recipe With Freshly Ground Spice."]'::jsonb, 60, 'Malabar', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/rekha_v/ARI_PATHIRI__MALABAR_PATHIRI_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/940.ARI_PATHIRI__MALABAR_PATHIRI_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Meat Masala Stuffed Bharwa Baingan Recipe', 'meat-masala-stuffed-bharwa-baingan-recipe', 'Meat Masala Bharwa Baingan is my instant hack to a tasty finger licking and instant stuffed baingan masala when you have no time to make stuffing from scratch. If you are pretty much bored with usual baingan variety so I thought of this hack.', '["250 grams Brinjal (Baingan / Eggplant)", "5 tablespoons Meat masala", "Salt , to taste", "1 Onion , chopped", "1 Tomato , chopped", "1 teaspoon Ginger Garlic Paste , (optional)", "3 tablespoons Mustard oil", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Asafoetida (hing)"]'::jsonb, ARRAY['tomato', 'salt', 'mustard oil', 'asafoetida (hing)', 'brinjal (baingan eggsplant)', 'ginger garlic paste', 'onion', 'cumin seeds (jeera)', 'meat masala']::text[], '["To begin making the Meat Masala Stuffed Bharwa Baingan recipe, hold the tip and make two opposite slits.Add salt to the meat masala and mix well.", "With a teaspoon stuff baingan with meat masala.Heat mustard oil till smoking.", "Now add hing and jeera.", "Also add the onion.", "Cook till the onions are soft.Add prepared baingan and roast for one minutes.", "Add tomatoes and any remaining meat masala stuffing.Add 1/2 cup water and cook till baingan is done.Serve Meat Masala Stuffed Bharwa Baingan with\u00a0Dal Tadka\u00a0and\u00a0Tawa Parathas\u00a0for a weekday meal."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/theyellowdaal/Meat_Masala_Stuffed_Bharwa_Baingan.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/941.Meat_Masala_Stuffed_Bharwa_Baingan.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Reshmi Kofta Recipe in Rich Cashew Gravy', 'reshmi-kofta-recipe-in-rich-cashew-gravy', 'The Reshmi Kofta Recipe in Rich Cashew Gravy, is a lipsmacking gravy that is packed with the delicious kofta made from paneer, cheese and potatoes simmer in a rich tomato and cashew gravy that has a perfect blend of spices.', '["150 grams Paneer (Homemade Cottage Cheese) , grated", "50 grams Cheese , grated", "3 Potatoes (Aloo) , boiled and mashed", "1 tablespoon Gram flour (besan)", "Salt , to taste", "Red Chilli powder , to taste", "2 Onions , roughy chopped", "3 cloves Garlic", "1 inch Ginger", "1-1/2 cups Homemade tomato puree", "1/4 cup Cashew nuts , ground to smooth paste with water", "1 tablespoon Fresh cream", "1 teaspoon Kashmiri Red Chilli Powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "Coriander (Dhania) Leaves , chopped for garnish", "Salt , to taste"]'::jsonb, ARRAY['cheese', 'salt', 'tomato', 'ginger', 'kashmiri red chilli powder', 'coriander (dhania) leaves', 'paneer', 'cashew nuts ground smooth paste water', 'onion y', 'red chilli powder', 'cloves garlic', 'gram flour (besan)', 'coriander powder', 'potato (aloo)', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'garam masala powder']::text[], '["To begin making the\u00a0Reshmi Kofta Recipe in Rich Cashew Gravy, first get all the ingredients together, so we can begin making the preps to make the kofta.Make a homemade tomato puree according to this recipe and keep aside.Make a smooth paste of the cashewnuts, by grinding it along with a little water and keep aside.", "Make a paste of the onion, ginger and garlic and keep aside.To begin making the kofta, combine the cheese, paneer and potatoes in a large mixing bowl, add a tablespoon of besan, salt and chilli powder.", "Combine to make a kofta mixture.", "Divide it into lemon sized balls.", "Heat the paniyaram pan over medium heat, add a little oil in each of the cavities and pan fry the reshmi koftas until cooked through and golden brown.", "Once all the kofta balls are fried, keep them aside.Heat oil in a kadai over medium heat; add the onion ginger garlic paste and cook until the raw smell goes away and the onion is lightly browned.Once the onion is cooked, add all the masalas and stir for a few seconds.", "The process of adding the masalas into the onion also helps the raw smell go away.", "Stir in the tomato puree, the cashewnut paste and the cream.", "Give the mixture a brisk boil and simmer for 10 minutes so the kofta curry gets the right flavors and taste.Check the salt and seasoning and adjust to suit your taste.", "When you are ready to serve, add the pan fried Reshmi kofta balls, the chopped coriander leaves, the kasuri methi and simmer for 3 to 4 minutes.Serve the Reshmi Kofta Curry along with Palak Paneer, Dal Makhani, Phulka and Kadai Beans and Carrot Pulao Recipe for a perfect weekend dinner."]'::jsonb, 90, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/malanikashish-gmail.com/reshmi_kofta_image.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/942.reshmi_kofta_image.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('चीज़ी आलू पराठा - Cheesy Aloo Paratha (Recipe In Hindi)', 'cheesy-aloo-paratha-recipe-in-hindi', 'आलू पराठे उत्तर भारत में बहुत प्रसिद्द है. इससे वह नाश्ते में बहुत शौक से खाया जाता है. गेहूं के आटे को गूंदकर उसके छोटे छोटे गोले बनाये जाते है. उसमे आलू और प्याज के मसाले को भरकर, पराठा बनाया जाता है. इस डिश में हमने इस पराठे में चीज़ भी डाला है, जिससे पराठे का स्वाद और भी बढ़ जाता है. चीज़ी आलू पराठे को बूंदी का रायता, तड़का रायता या किसी और रायते के साथ गरमा गरम परोसे।', '["\u0906\u091f\u0947 \u0915\u0947 \u0932\u093f\u090f", "1 \u0915\u092a \u0917\u0947\u0939\u0942\u0902 \u0915\u093e \u0906\u091f\u093e", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0924\u0947\u0932", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0928\u092e\u0915", "\u092a\u093e\u0928\u0940 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930, \u0906\u091f\u093e \u0917\u0942\u0902\u0926\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f", "\u092d\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f", "2 \u0906\u0932\u0942 , \u0909\u092c\u093e\u0932\u0915\u0930, \u091a\u093f\u0932\u0940 \u0914\u0930 \u092e\u0948\u0936 \u0915\u0930\u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0924\u0947\u0932", "1 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a , \u0924\u094b\u095c\u0940 \u0939\u0941\u0908", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u091c\u0940\u0930\u093e", "\u0939\u0940\u0902\u0917 , \u091a\u0941\u091f\u0915\u0940 \u092d\u0930", "1 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u092c\u093e\u0930\u0940\u0915 \u0915\u091f\u0940 \u0939\u0941\u0908", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u0915\u0938\u0940 \u0939\u0941\u0908", "1 \u092a\u094d\u092f\u093e\u091c , \u092c\u093e\u0930\u0940\u0915 \u0915\u091f\u0947 \u0939\u0941\u090f", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u091a\u093e\u091f \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "1/4 \u0915\u092a \u091a\u0940\u095b , \u0915\u0938\u093e \u0939\u0941\u0906", "4 \u092a\u0924\u094d\u0924\u0947 \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u092c\u093e\u0930\u0940\u0915 \u0915\u091f\u0947 \u0939\u0941\u090f", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['आटे के लिए', 'कप गेहूं का आटा', 'छोटा चमच्च तेल', 'छोटा चमच्च नमक', 'पानी', 'भरने के लिए', 'आलू', 'सुखी लाल मिर्च', 'छोटा चमच्च जीरा', 'हींग', 'हरी मिर्च', 'इंच अदरक', 'प्याज', 'छोटा चमच्च हल्दी पाउडर', 'छोटा चमच्च धनिया पाउडर', 'छोटा चमच्च जीरा पाउडर', 'छोटा चमच्च गरम मसाला पाउडर', 'छोटा चमच्च चाट मसाला पाउडर', 'कप चीज़', 'पत्ते हरा धनिया', 'नमक']::text[], '["\u091a\u0940\u095b\u0940 \u0906\u0932\u0942 \u092a\u0930\u093e\u0920\u093e \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u092c\u095c\u093e \u092c\u093e\u0909\u0932 \u0932\u0947 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0906\u091f\u093e, \u0928\u092e\u0915, \u0924\u0947\u0932, \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0907\u0938\u0938\u0947 \u0917\u0942\u0902\u0926 \u0932\u0947. \u0907\u0938\u0938\u0947 \u090f\u0915 \u0915\u0948\u0938\u0947 \u0938\u0947 \u0922\u0915\u0947 \u0914\u0930 15-20\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u0907\u0938\u0915\u0947 \u092c\u093e\u0926 \u0939\u092e \u0907\u0938\u092e\u0947\u0902 \u092d\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092e\u0938\u093e\u0932\u093e \u0924\u0948\u092f\u093e\u0930 \u0915\u0930\u0947\u0902\u0917\u0947\u0964 \u0906\u0932\u0942 \u0915\u094b \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u092a\u093e\u0928\u0940 \u0914\u0930 \u0928\u092e\u0915 \u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947 \u0914\u0930 3\u00a0\u0938\u093f\u091f\u0940 \u092c\u091c\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e\u092f\u0947\u0964 \u0939\u094b \u091c\u093e\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0909\u0938\u0915\u093e \u091b\u093f\u0932\u0915\u093e \u0928\u093f\u0915\u0932\u0947 \u0914\u0930 \u092e\u0948\u0936 \u0915\u0930\u0932\u0947\u0964\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u0914\u0930 \u091c\u0940\u0930\u093e \u0921\u093e\u0932\u0947\u0964 10 \u0938\u0947\u0915\u0902\u0921 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0939\u0940\u0902\u0917, \u092c\u093e\u0930\u0940\u0915 \u0915\u091f\u093e \u0939\u0941\u0906 \u092a\u094d\u092f\u093e\u091c, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0905\u0926\u0930\u0915 \u0914\u0930 \u0928\u092e\u0915 \u0921\u093e\u0932\u0947\u0964 \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e\u090f\u0964\u0905\u092c \u0907\u0938 \u092e\u0938\u093e\u0932\u0947 \u092e\u0947\u0902 \u092e\u0948\u0936 \u0915\u093f\u092f\u0947 \u0939\u0941\u090f \u0906\u0932\u0942, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930, \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930, \u091a\u093e\u091f \u092e\u0938\u093e\u0932\u093e, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 3\u00a0\u0938\u0947 4 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u093e\u092f\u0947\u0964\u0905\u0902\u0924 \u092e\u0947\u0902 \u0915\u0948\u0938\u093e \u0939\u0941\u0906 \u091a\u0940\u095b, \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u092a\u0930\u093e\u0920\u0947 \u092c\u0928\u093e\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947, \u0906\u091f\u0947 \u0915\u094b \u090f\u0915 \u092c\u093e\u0930 \u0914\u0930 \u0917\u0942\u0902\u0926 \u0932\u0947. \u0914\u0930 \u0907\u0938 \u0906\u091f\u0947 \u0938\u0947 \u091b\u094b\u091f\u0940 \u092c\u0949\u0932 \u092c\u0928\u093e \u0932\u0947.\u00a0\u0925\u094b\u095c\u093e \u0938\u093e \u0906\u091f\u093e \u091b\u093f\u091f\u0915\u0947 \u0914\u0930 \u090f\u0915 \u091b\u094b\u091f\u0940 \u0938\u0940 \u0930\u094b\u091f\u0940 \u092c\u0928\u093e \u0932\u0947. \u092e\u0938\u093e\u0932\u0947 \u0915\u094b \u092c\u0940\u091a\u092e\u0947 \u0930\u0916\u0947 \u0914\u0930 \u091a\u093e\u0930\u094b \u0924\u0930\u092b \u0938\u0947 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947.\u00a0\u092c\u093f\u091a \u092e\u0947\u0902 \u0926\u092c\u093e\u090f \u0914\u0930 \u0909\u0938\u0947 \u0930\u094b\u091f\u0940 \u092e\u0947\u0902 \u092c\u0947\u0932\u0928\u093e \u091a\u093e\u0932\u0942 \u0915\u0930\u0947\u0902\u0964 \u0927\u0940\u0930\u0947 \u0927\u0940\u0930\u0947 \u092c\u0947\u0932\u0947 \u0924\u093e\u0915\u093f \u092e\u0938\u093e\u0932\u093e \u092c\u093e\u0939\u0930 \u0928\u093e \u0906\u092f\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0924\u0935\u093e \u0917\u0930\u092e \u0915\u0930\u0947\u0902 \u0914\u0930 \u0909\u0938\u092a\u0930 \u092a\u0930\u093e\u0920\u093e \u0930\u0916 \u0926\u0947. \u0918\u0940 \u092f\u093e \u0924\u0947\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930\u00a0\u0926\u094b\u0928\u094b\u0902 \u0924\u0930\u092b \u0938\u0947 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u092a\u0915\u093e \u0932\u0947 \u0914\u0930 \u0917\u0930\u092e\u093e \u0917\u0930\u092e \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u091a\u0940\u095b\u0940 \u0906\u0932\u0942 \u092a\u0930\u093e\u0920\u0947 \u0915\u094b \u092c\u0942\u0902\u0926\u0940 \u0915\u093e \u0930\u093e\u092f\u0924\u093e, \u0924\u095c\u0915\u093e \u0930\u093e\u092f\u0924\u093e \u092f\u093e \u0915\u093f\u0938\u0940 \u0914\u0930 \u0930\u093e\u092f\u0924\u0947 \u0915\u0947 \u0938\u093e\u0925 \u0917\u0930\u092e\u093e \u0917\u0930\u092e \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/6-march/Cheesy_Aloo_Stuffed_Paratha_Recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/943.Cheesy_Aloo_Stuffed_Paratha_Recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Dhokar Dalna Recipe', 'bengali-dhokar-dalna-recipe', 'Dhokar Dalna is a signature Bengali vegetarian dish. It is lentil cake made using chana dal which is traditionally fried and simmered in a satvic gravy i.e. a gravy without onion and garlic. I have learnt the recipe from my mother. She makes amazing dhokar dalna.', '["1 cups Chana dal (Bengal Gram Dal)", "1 inch Ginger , grated", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Cumin powder (Jeera)", "Salt , to taste", "Sugar , to taste", "2 Green Chillies", "1/2 teaspoon Asafoetida (hing)", "2 tablespoons Oil", "2 Potatoes (Aloo) , diced", "2 Bay leaves (tej patta)", "1 teaspoon Cumin seeds (Jeera)", "1 inch Ginger , grated", "2 Tomatoes , chopped", "2 Green Chillies", "1/2 teaspoon Cumin powder (Jeera)", "1 tablespoon Coriander Powder (Dhania)", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "Salt , to taste", "Sugar , a pinch, optional", "1/2 teaspoon Garam masala powder", "2 teaspoon Mustard oil"]'::jsonb, ARRAY['s chana dal', 'bengal gram dal', 'ginger', 'cumin seeds', 'jeera', 'cumin powder', 'salt', 'sugar', 'reen chillies', 'asafoetida', 'hing', 's oil', 'potatoes', 'aloo', 'bay leaves', 'tej patta', 'tomatoes', 'coriander powder', 'dhania', 'turmeric powder', 'haldi', 'red chilli powder', 'garam masala powder', 'mustard oil']::text[], '["To begin making Bengali Dhokar Dalna Recipe, we will first prepare dhoka i.e the lentil cake.", "Soak the chana for a few hours then grind it with ginger, chilli and little water into a paste.Take a tablespoon of oil in a non stick pan add jeera, hing, the ground mixture, salt and sugar.Stir it till the chana dal mixture dries and comes together.Take a plate and grease it with some oil, put the mixture on it and pat down to spread evenly.Let it cool down.", "You can keep in fridge it will harden fast and you can cut pieces.Cut in medium sized diamond shapes or any shape.Grease a baking dish, place the dhokas on it.", "Sprinkle little oil/brush them with oil and bake in oven at 180 degrees for 20-30 minutes.The next step is to prepare the gravy.", "Heat mustard oil in a kadai, add jeera and bay leaf.", "Add ginger paste and tomatoes.Next, add jeera powder, coriander powder, turmeric powder, red chilli powder, salt and sugar.", "Once the tomatoes turn mushy, add potatoes.", "Add water, cover and cook the potatoes.Once the potatoes are done, add the baked dhokas in the gravy.", "Let it simmer for 2-3 minutes.Sprinkle garam masala powder and a teaspoon of ghee and give it a stir.Switch of the flame, cover and keep it for sometime for flavors to blend well before serving with steamed rice, or\u00a0Serve\u00a0Bengali Dhokar Dalna Recipe with\u00a0Bengali Luchi Recipe\u00a0or\u00a0Methi Lachha Paratha Recipe\u00a0for lunch."]'::jsonb, 90, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/priyanjali/Dhokar_dalna.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/944.Dhokar_dalna.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Soya Chunks And Beetroot Biryani Recipe', 'soya-chunks-and-beetroot-biryani-recipe', 'Soya Chunks & Beetroot Biryani is a South Indian style Biryani recipe which is flavoured with freshly ground coriander powder,coconut milk and other Indian spices', '["1-1/2 cups Basmati rice , soaked in enough water for 20 minutes", "1 Beetroot , finely chopped", "15-20 Soy Chunks (Nuggets) , soaked in warm water for 20 minutes", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1 Green Chilli , chopped", "1/2 tablespoon Ginger Garlic Paste", "1 cup Mint Leaves (Pudina)", "1 cup Coriander (Dhania) Leaves , finely chopped", "1 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "2 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "1 teaspoon Lemon juice", "2 cup Coconut milk", "2 tablespoon Oil", "4 cloves Cloves (Laung)", "1/4 Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta)", "1 teaspoon Ajwain (Carom seeds)"]'::jsonb, ARRAY['tomato', 'salt', 'coconut milk', 'basmati rice enough water', 'green chilli', 'coriander (dhania) leaves', 'coriander powder', 'cloves cloves (laung)', 'bay leaf (tej patta)', 'ajwain (carom seeds)', 'soy (nuggets) water', 'red chilli powder', 'ginger garlic paste', 'onion', 'lemon', 'cinnamon stick (dalchini)', 'mint leaves (pudina)', 'beetroot', 'turmeric powder', 'sunflower oil']::text[], '["To begin making Soya Chunks And Beetroot Biryani Recipe, soak the soya chunks in warm water for 20 minutes.", "Squeeze water from the soya chunks and chop them.Next, blend mint and coriander leaves in a mixer grinder to a smooth paste by adding 2 tablespoon water.", "Keep it aside.Heat 2 tablespoon groundnut oil in a heavy bottom pan.", "Add cloves, cinnamon, bay leaf and shahi jeera and saut\u00e9 them for about 30 seconds till the aromas from the whole spices comes through.Once done add chopped onions and green chilies.", "Saute till onions turns golden brown in colour.After the onions have caramelized add tomatoes and saute till soft and mushy.Once done add chopped beetroot and soya chunks.", "Stir well.Add ground mint-coriander paste, turmeric powder, red chilli powder, coriander powder and salt to taste.", "Stir well till combined.", "Add 1 cup water, cover it with a lid and cook it for 10 minutes.Add coconut milk and 1/2 cup water.", "Once it starts boiling, add rice, lemon juice and salt to taste.", "Mix well and cook Soya Chunks And Beetroot Biryani covered on low-medium heat till the rice is cooked.", "Once done fluff the biryani and transfer the\u00a0Soya Chunks And Beetroot Biryani into a serving bowl or plate and serve.Serve Soya Chunks And Beetroot Biryani with Burani Raita, Lauki raita or any other raita of your choice."]'::jsonb, 70, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Preeti_Tamilarasan/Soya_Chunks__Beetroot_Biryani.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/945.Soya_Chunks__Beetroot_Biryani.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sakkaravalli Kizhangu Poriyal Recipe - Spicy Sweet Potato Roast', 'sakkaravalli-kizhangu-poriyal-recipe-spicy-sweet-potato-roast', 'The Spicy Sweet Potato Roast also known as Sakkaravalli Kizhangu Poriyal is a delicious preparation of the sweet potatoes cooked South Indian style. Even the Bengalis have a similar preparation with a subtle variation and call it Aloo Bhaja.', '["3 Sweet Potatoes", "1/2 teaspoon Asafoetida (hing)", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon White Urad Dal (Split)", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 sprig Curry leaves", "2 tablespoons Sesame (Gingelly) Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard seeds', 'asafoetida (hing)', 'red chilli powder', 'sesame (gingelly) oil', 'curry leaves', 'white urad dal (split)', 'turmeric powder', 'sweet potatoes']::text[], '["To begin making the Spicy Sweet Potato Roast Recipe/ Sakkaravalli Kizhangu Poriyal Recipe, first get all the ingredients ready.", "Peel and cut the sweet potatoes into 1 inch size pieces and soak in water to prevent discoloration.Heat two tablespoon of oil in a wok over medium heat.", "Add the mustard seeds, urad dal and allow them to crackle and turn golden brown and crisp.Stir in the curry leaves,\u00a0asafoetida and finally the peeled and cut sweet potatoes.Sprinkle salt and stir well to combine.", "Cover the pan and turn the heat to low and cook the sweet potatoes until they are almost cooked.Towards the end, stir in the turmeric powder and red chilli powder.", "Stir well to combine and finally cook the sweet potato roast/\u00a0Sakkaravalli Kizhangu Poriyal without the lid and allow it to roast until golden and slightly crisp.", "Roast the sweet potatoes/Sakkaravalli Kizhangu Poriyal until they have a slightly crispy texture.", "Remember the sweet potatoes drink a lot of\u00a0oil, so adding more oil will give a more roasted feel, but watch out for that excess.", "Once the Sweet potatoes/Sakkaravalli Kizhangu Poriyal are well roasted, check the salt and spice levels and adjust to suit your taste.", "Turn off the heat and transfer the\u00a0Sakkaravalli Kizhangu Poriyal into a serving dish.Serve\u00a0Sakkaravalli Kizhangu Poriyal\u00a0along with\u00a0Yeruvalli Kuzhambuand\u00a0Steamed Rice\u00a0for a weekday lunch.", "You can also pack this with\u00a0Tawa Paratha\u00a0for Lunch Box."]'::jsonb, 45, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Sakkaravalli_Kizhangu_Poriyal_Recipe_-_Spicy_Sweet_Potato_Roast_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/946.Sakkaravalli_Kizhangu_Poriyal_Recipe_-_Spicy_Sweet_Potato_Roast_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Urulai Kizhangu Roast Recipe - Spicy Potato Roast Recipe', 'urulai-kizhangu-roast-recipe-spicy-potato-roast-recipe', 'The Spicy Potato Roast also known as Urulai Kizhangu Roast is a delicious preparation of the potatoes cooked South Indian style. Even the Bengalis have a similar preparation with a subtle variation and call it Aloo Bhaja.', '["3 Potatoes (Aloo) , boiled and diced", "1/2 teaspoon Asafoetida (hing)", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 sprig Curry leaves", "2 tablespoons Sesame (Gingelly) Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard seeds', 'asafoetida (hing)', 'red chilli powder', 'sesame (gingelly) oil', 'curry leaves', 'cumin seeds (jeera)', 'potato (aloo)', 'turmeric powder']::text[], '["To begin making the Spicy Potato Roast Recipe/ Urulai Kizhangu Roast Recipe, first get all the ingredients ready.", "It good to have the potatoes firmly boiled as well.", "To cook the potatoes, cut the potatoes in half and place it in the pressure cooker.", "Add 1/4 cup of water, cover the pressure cooker, place the weight on and pressure cook until you hear a couple\u00a0of whistles.After a couple of whistles turn off the heat.", "Allow the pressure to release naturally.", "Once the pressure is released, open the cooker and peel the skin of the potatoes and allow it to cool down completely.Once the potatoes are cooled down, cut the potatoes into a desired shape and add it to a bowl.", "Heat a tablespoon of oil in a wok.", "Add the mustard seeds, cumin seeds, curry leaves,\u00a0asafoetida and allow them to crackle.Add the potatoes,\u00a0turmeric powder, salt and red chilli powder and mix well.and stir well until all the condiments get well coated.Reduce the flame to medium and cover the pan with a lid and roast the \u00a0Urulai Kizhangu Roast on low to medium heat, stirring occasionally.Roast the potatoes until they have a slightly crispy texture.", "More like the some crumbs of the potatoes turn\u00a0crispy.Remember potatoes drink a lot of\u00a0oil, so adding more oil will give a more roasted feel, but watch out for that excess.", "Once the potatoes are well roasted, check the salt and spice levels and adjust to suit your taste.", "Turn off the heat and transfer the \u00a0Urulai Kizhangu Roast into a serving dish.Serve\u00a0Spicy Potato Roast Recipe/\u00a0\u00a0Urulai Kizhangu Roast\u00a0along with\u00a0Keerai Sambar\u00a0and Steamed Rice for a weekday lunch.", "You can also pack this with\u00a0Tawa Paratha\u00a0for Lunch Box."]'::jsonb, 45, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Urulaikizhangu_Roast_Spicy_Potato_Roast_recipe-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/947.Urulaikizhangu_Roast_Spicy_Potato_Roast_recipe-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Southekayi Palya Recipe - Mangalore Cucumber Palya/ Sabzi Recipe', 'southekayi-palya-recipe-mangalore-cucumber-palya-sabzi-recipe', 'Southekayi Palya Recipe (Mangalore Cucumber Palya/ Sabzi) is an integral part in most of the coastal region of Karnataka as they use a lot of Mangalore cucumber in their cooking. The dry dish are mainly referred to as Palya in their local language. “Southekayi” refers to any cucumber family. In this recipe, the mangalore cucumber is simply tossed with some ground masala and then stir fried in onion, garlic and most importantly coconut oil.', '["1 cup Mangalorean cucumber , chopped into small size with skin", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 Onion , finely chopped", "4 cloves Garlic , finely chopped", "2 sprig Curry leaves , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "To Grind", "1/4 cup Fresh coconut", "2 Dry Red Chillies", "1 teaspoon Cumin seeds (Jeera)"]'::jsonb, ARRAY['mangalorean cucumber', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'onion', 's garlic', 'curry leaves', 'turmeric powder', 'haldi', 'salt', 'to grind', 'fresh coconut', 'dry red chillies', 'cumin seeds', 'jeera']::text[], '["To begin making the Mangalorean Southekayi Palya Recipe (Mangalore Cucumber Palya/ Sabzi Recipe), prep all the ingredients and keep them ready.Grind the coconut, cumin seeds and dry red chilli into a coarse mixture using a mixer grinder.", "Do not add any water to this.", "It needs to be a dry mixture.", "Keep this aside.Heat oil in a kadai/ wok over medium heat; add the mustard seeds, urad dal and allow the seeds to crackle and the dal to turn golden brown and crisp.Stir in the chopped garlic, onion, and curry leaves.", "Saute the onion and garlic until the onions turn soft.", "Add the cut mangalore cucumber ( southekayi), turmeric powder, salt to taste and the ground coconut mixture.", "Give it a stir.Sprinkle 2 to 3 tablespoons of water, cover the pan and allow the\u00a0Southekayi Palya to cook until it is soft and done.Once done, turn off the heat and check the salt and adjust according to taste.", "Transfer the\u00a0Southekayi Palya to a serving bowl and serve hot.Serve the\u00a0Southekayi Palya Recipe\u00a0along with\u00a0Phulka,\u00a0Thakkali Rasam\u00a0and Rice for a delicious meal."]'::jsonb, 30, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Southekayi_Palya_Recipe_Mangalore_Cucumber_Palya_Sabzi_Recipe_Udupi_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/948.Southekayi_Palya_Recipe_Mangalore_Cucumber_Palya_Sabzi_Recipe_Udupi_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bihari Karela Aloo Sabzi Recipe', 'bihari-karela-aloo-sabzi-recipe', 'Bihari Karela Aloo Sabzi Recipe is a popular  side dish which is packed with flavour and taste with simple spices used in the kitchen.', '["2 Karela (Bitter Gourd/ Pavakkai) , deseeded and cut into thin strips", "2 tablespoons Mustard oil", "1 teaspoon Cumin seeds (Jeera)", "4 cloves Garlic , finely chopped", "2 Onions , thinly sliced", "3 Potatoes (Aloo) , thickly sliced", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "1 teaspoon Coriander (Dhania) Powder", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Red Chilli powder", "Salt , to taste", "1 teaspoon Jaggery , optional"]'::jsonb, ARRAY['karela', 'bitter gourd/ pavakkai', 's mustard oil', 'cumin seeds', 'jeera', 's garlic', 'onions', 'potatoes', 'aloo', 'turmeric powder', 'haldi', 'garam masala powder', 'coriander', 'dhania', 'amchur', 'dry mango powder', 'red chilli powder', 'salt', 'jaggery']::text[], '["To begin with Bihari Karela Aloo Sabzi Recipe, prep all the ingredients and keep them aside.Into the pressure cooker, add the karela, along with a little salt to taste and 2 tablespoons water and pressure cook for 2 whistles and turn off the heat.", "Release the pressure immediately to retain the bright green color of the karela.Keep this aside.Heat oil in a kadai over medium heat; add the onion and garlic and saute until the onion is just soft.", "Add the sliced potatoes, sprinkle salt and turmeric powder and cook the potatoes until they are well roasted and cooked.You can optionally cover the pan and steam cook the potatoes so it cooks faster.Once the potatoes are roasted, add the cooked karela and all the remaining spices like red chilli powder, garam masala powder, amchur powder, salt if needed and also jaggery if you like a little bit of sweetness.Give it a good stir to combine all the ingredients.", "Stir fry the\u00a0Bihari Karela Aloo Sabzi for another 4 to 5 minutes so the flavours get well absorbed into the vegetable.", "Once done, check the salt and spices and adjust to taste accordingly.Turn off the heat and transfer the\u00a0Bihari Karela Aloo Sabzi to a serving bowl and serve hot.Serve\u00a0Bihari Karela And Aloo Ki Sabzi\u00a0along with\u00a0Palak Dal,\u00a0Phulkas\u00a0and\u00a0Jeera Rice\u00a0for an everyday meal."]'::jsonb, 65, 'Bihari', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Bihari_Karela_Aloo_Sabzi_Bhaja_recipe_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/949.Bihari_Karela_Aloo_Sabzi_Bhaja_recipe_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Besan Cheela Recipe Stuffed With Chatapa Paneer', 'besan-cheela-recipe-stuffed-with-chatapa-paneer', 'The Besan Cheela is a super simple recipe that you can make for breakfast. This recipe also has a chatpata paneer stuffing which makes it high in protein and filling as well. It is also a super simple breakfast which takes only 15 minutes to make.', '["2 cups Gram flour (besan)", "2 Onions , finely chopped", "2 Green Chillies , finely chopped", "6 sprig Coriander (Dhania) Leaves , few, finely chopped", "Salt , to taste", "1 teaspoon Cumin powder (Jeera)", "Oil , for cooking", "1 cup Paneer (Homemade Cottage Cheese) , crumbled", "2 Green Chillies , finely chopped", "1/2 teaspoon Chaat Masala Powder", "6 sprig Coriander (Dhania) Leaves , finely chopped", "Salt , to taste"]'::jsonb, ARRAY['s gram flour', 'besan', 'onions', 'reen chillies', 'coriander', 'dhania', 'salt', 'cumin powder', 'jeera', 'oil', 'paneer', 'homemade cottage cheese', 'chaat masala powder']::text[], '["To begin making the Besan Cheela Recipe, combine all the ingredients for the Besan Cheela in a large bowl.Gradually add water to make a smooth batter, add water in such a way that the cheena batter is not too watery or too thick.", "It should have a light spreading consistency.Check the salt and spice levels and adjust to suit your taste.The cheela batter will be similar to the consistency of a dosa batter, but just a little lighter.", "The batter should be able thinly coat the back of the spoon.The next step is to make the paneer stuffing.", "In a large mixing bowl - combine all the ingredients and keep them aside.", "Check the salt and adjust according to taste.The next step is to cook the Besan Cheela in a pan.Preheat a skillet on medium heat, pour a ladleful of batter on the pan and spread it in a circular motion to form a thin crepe/ dosa.Drizzle oil around the cheela and cook it until the top does not look raw and you notice the edges are getting brown.", "Flip and cook on the other side for a few seconds.Once done, spoon the paneer filling to the center and then fold the Besan cheela.Transfer the Besan Cheela to a plate and serve hot.Serve the\u00a0Besan Cheela along with a\u00a0Sweet And Spicy Tomato Chutney\u00a0and a\u00a0Dhaniya Pudina Chutney\u00a0for breakfast, a tea time snack or even weeknight dinner."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Curefit_Breakfast_Recipe_Besan_Chilla_Stuffed_Paneer_And_Green_Chutney_10_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/950.Curefit_Breakfast_Recipe_Besan_Chilla_Stuffed_Paneer_And_Green_Chutney_10_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Udupi Tomato Rasam Recipe', 'udupi-tomato-rasam-recipe', 'Udupi Tomato Rasam Recipe is traditional and very famous recipe from Udupi which belongs to Karnataka. Udupi cuisine is purely “Satvik Cuisine” where they don’t prefer onion and garlic in their dishes. This rasam consists of ripped tomatoes that is cooked in tangy tamarind water which is again boiled with cooked toor dal. The rasam’s secret ingredient is addition of the rasam powder which is blend of various roasted spices.', '["1/2 cup Arhar dal (Split Toor Dal) , cooked", "2 Tomatoes , cut into cubes", "1 cup Tamarind Water", "1 tablespoon Jaggery", "2 sprig Coriander (Dhania) Leaves , finely chopped", "Udupi Rasam Powder", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "2 tablespoons Coriander (Dhania) Seeds", "1 tablespoon Fresh coconut , grated", "4 Dry Red Chillies", "1/4 teaspoon Asafoetida (hing)", "1 sprig Curry leaves", "1 tablespoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Dry Red Chilli", "1 sprig Curry leaves"]'::jsonb, ARRAY['tomato', 'arhar dal (split toor dal)', 'tamarind water', 'mustard seeds', 'coconut', 'asafoetida (hing)', 'ghee', 'jaggery', 'dry red chilli', 'curry leaves', 'coriander (dhania) leaves', 'coriander (dhania) seeds', 'dry red chillies', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)']::text[], '["We begin making the Udupi Tomato Rasam Recipe by pressure cooking the toor dal with water in a pressure for 4 whistle.", "Allow the pressure to release naturally, and once done mash the dal using a muddler.To make the rasam powder, dry roast the\u00a0fenugreek seeds,\u00a0mustard seeds,\u00a0cumin seeds,\u00a0coriander seeds,\u00a0fresh coconut,\u00a0dry red chilies,\u00a0asafoetida,\u00a0curry leaves in a small skillet on medium-low flame.", "Then grind into a smooth powder using a Mixer.In a large sauce pan, boil the tamarind water with tomatoes, green chillies, curry leaves, rasam powder and jaggery.", "Let it boil for at least 25 minutes.", "You can add sufficient water if it reduces.Then later on add the dal, check for the seasoning and mix well.", "Boil for another 10 minutes and then add the chopped coriander leaves.Heat another pan for tempering, add ghee, crackle mustard seeds and add the\u00a0dry red chili and\u00a0curry leaves.", "Pour it over the rasam and serve.", "Serve the Udupi Tomato Rasam Recipe along with steamed rice and\u00a0Sabudana Sandige | Fryums Recipe\u00a0to enjoy your\u00a0week Night Dinner."]'::jsonb, 55, 'Udupi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Udupi_Tomato_Rasam_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/951.Udupi_Tomato_Rasam_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sweet Potato Sabzi Recipe', 'sweet-potato-sabzi-recipe', 'Sweet Potato Sabzi is a very easy sabzi to cook, also it is healthy given the nutritional benefits of sweet potatoes. It can be cooked in a jiff when you do not have much time to spare.', '["3 Sweet Potatoes , washed, peeled and cut into 1/4 inch round slices", "3 tablespoon Oil", "1 Dry Red Chilli , cut into 2 pieces", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 Green Chilli , finely chopped", "1/4 teaspoon Asafoetida (hing)", "Salt , to taste", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Cumin powder (Jeera)", "4 sprig Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['sweet potatoes', 'oil', 'dry red chilli', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'reen chilli', 'asafoetida', 'hing', 'salt', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'cumin powder', 'coriander']::text[], '["To begin the preparation of Sweet Potato Sabzi, heat Oil in a broad non stick pan.", "Add dry red chilli and mustard seeds.", "Once mustard seed crackles, then add jeera, green chilli and hing.Add sweet potato slices and mix well.", "Let it saute for 5 minutes.", "Then add salt and turmeric powder in it.", "Let it saute for 10-15 minutes or until it gets cooked.Add dhaniya powder and jeera powder and mix well.", "Remove from flame.In the end, sprinkle coriander leaves on it.Serve the Sweet Potato Sabzi with\u00a0phulka\u00a0and\u00a0buttermilk\u00a0for a light afternoon lunch."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Bela_Dholakia/Sweet_Potato_Sabzi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/952.Sweet_Potato_Sabzi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Egg Butter Masala Recipe', 'egg-butter-masala-recipe', 'Egg Butter Masala (Egg Makhani) is similar to Paneer butter masala. The butter masala is a delicious creamy curry which is mildly spiced. To the same gravy you can either add paneer or boiled eggs. Since it is mildly spiced, it can even be given to kids along with plain rice or rotis. The creaminess to this gravy is due to the addition of cashew-nuts. You can even add fresh cream instead of cashew nut paste. This dish is ideal to serve for dinner parties along with jeera rice or butter garlic naan. Eggs are rich in protein and vitamins and hence this creamy yummy curry is ideal to serve not just to kids, but to everyone in your family. Weight watchers can discard the egg yolk while eating the dish.', '["4 Whole Eggs", "3 Tomatoes , finely chopped", "2 Onions , finely chopped", "6 cloves Garlic", "1/4 inch Ginger", "6 tablespoon Butter (Salted)", "1 Bay leaf (tej patta)", "1 teaspoon Red Chilli powder", "1 tablespoon Garam masala powder", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "20 Cashew nuts", "1 tablespoon Ginger Garlic Paste", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'cashew nuts', 'salt', 'ginger', 'bay leaf (tej patta)', 'red chilli powder', 'cloves garlic', 'ginger garlic paste', 'onion', 'eggs', 'kasuri methi (dried fenugreek leaves)', 'butter', 'garam masala powder']::text[], '["To begin with Egg Butter Masala, soak cashew nuts in hot water for 30 minutes.", "After 30 minutes drain the water and retain the cashew nuts.Boil the eggs and after cooling, crack and discard the shell.", "Keep them aside.In a kadhai, add 2 tablespoon butter.", "After the butter melts, add onion and fry till onion turns pinkish.", "Add tomato and saute till tomato turns mushy.Add garlic, ginger and saute till raw smell of garlic goes away.", "Add the boiled cashew nuts and mix.Switch off the gas.", "After cooling, grind the sauteed onion tomato mixture by adding 1 cup water.Strain this gravy by passing through a strainer.", "While passing through a strainer, take a spoon and keep on pressing the contents against the strainer.", "Let the entire gravy pass through.", "Only seeds of tomato will remain on strainer as a residue which you can discard.Heat the kadai again, add 1 tablespoon butter.", "Add bayleaf and ginger garlic paste and fry for 1 minute.Add the gravy and mix everything well.", "Add 2 tablespoons butter and simmer the gravy for 10 minutes.Add chili powder, garam masala, kasuri methi and mix well.", "Finally, add the boiled eggs and simmer for 5 minutes.", "Add salt to taste.Garnish with chopped coriander leaves or fresh cream if you wish.Serve Egg Butter Masala with\u00a0Whole Wheat Lachha Paratha\u00a0and Jeera Rice."]'::jsonb, 60, 'Indian', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Egg_Butter_Masala.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/953.Egg_Butter_Masala.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Raw Jackfruit Kofta Curry Recipe - Kathal Kofta Curry Recipe', 'raw-jackfruit-kofta-curry-recipe-kathal-kofta-curry-recipe', 'Raw Jackfruit Kofta Curry recipe will surely satisfy your taste buds with its taste and flavour. This is a Bengali Curry where Koftas are made from jackfruit and then added to a delicious tomato and coconut gravy.', '["500 grams Jackfruit Raw (Kathal) , cut into pieces", "2 tablespoons All Purpose Flour (Maida)", "2 tablespoons Fresh coconut , grated", "1 Cardamom Powder (Elaichi)", "2 teaspoon Sultana Raisins , chopped", "1 Green Chilli", "1 teaspoon Cumin powder (Jeera)", "1 cup Water", "1 Cinnamon Stick (Dalchini)", "Salt , to taste", "3 teaspoon Oil , as required, or ghee", "5 Tomato , chopped", "2 Onions , optional, chopped", "1 cup Water", "1 teaspoon Ginger , paste", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Asafoetida (hing)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Garam masala powder", "4 teaspoon Oil , as required or ghee", "2 teaspoon Fresh cream , as required, for garnish", "2 teaspoons Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['tomato', 'cumin powder (jeera)', 'asafoetida (hing)', 'coriander (dhania) leaves', 'onion', 'cumin seeds (jeera)', 'cardamom powder (elaichi)', 'turmeric powder', 'sunflower oil', 'salt', 'green chilli', 'sunflower oil ghee', 'raisins', 'flour (maida)', 'garam masala powder', 'coconut', 'red chilli powder', 'water', 'jackfruit (kathal)', 'cinnamon stick (dalchini)', 'ginger paste']::text[], '["To begin making the Raw Jackfruit Kofta Curry Recipe, first clean the jackfruit pieces and then cook for up to 1-2 whistle in a cup of salted water and a cinnamon in a pressure cooker.Switch off the stove and let the pressure release naturally.Once fully cooked strain the water and keep the jackfruit aside to dry.Take a blender, add boiled jackfruit with coconut and green chilli without adding water.", "Blend it into a paste.Once it is done, add the all purpose flour, salt, cardamom and cumin powder. and mix everything well.Mix everything well and keep it aside to cool down the jackfruit kofta mixture.Now make small flat oval shaped balls with the mixture.", "Heat a paniyaram pan with oil in each cavity and fry the kathal koftas from both the sides till they turn golden brown.The next step is to make the kofta gravy.", "Heat oil in a heavy bottomed pan.", "Add cumin seeds and asafoetida and saute for about 10 seconds.After 10 seconds, add onions, salt and cook till they become soft and translucent.Next add tomatoes, ginger paste cook for about 6 to 8 minutes until the tomatoes are soft.", "Switch off the heat.Once the tomato mixture is cooled down, blend this mixture with a hand blender to smooth gravy adding a cup of water.Add this kofta gravy back in the wok and switch on the heat.", "Add turmeric powder, red chilli powder, cook on medium to low till thick gravy is forming with bubbles on top.Add garam masala powder, salt to taste and coriander leaves.", "Let this kofta gravy cook for about 6 to 8 minutes.", "Drop the jackfruit koftas in the gravy, let it soak for few minutes before serving.", "Finally garnish the\u00a0Raw Jackfruit Kofta Curry with fresh cream and chopped coriander leaves.Serve\u00a0Raw Jackfruit Kofta Curry Recipe\u00a0along with\u00a0Palak Raita,\u00a0Phulka\u00a0and\u00a0Satvik Carrot Sprout Salad\u00a0for your weekday Indian Vegetarian meal."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/ruby_pathak-yahoo.com/Raw_Jackfruit_Kofta_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/954.Raw_Jackfruit_Kofta_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gawar Phali Methi Ki Sabzi Recipe -Cluster Beans Methi Sabzi', 'gawar-phali-methi-ki-sabzi-recipe-cluster-beans-methi-sabzi', 'Gawar Phali Methi Ki Sabzi Recipe is a delicious combination of fresh fenugreek leaves that is sauteed along with crunchy and soft gawar phali in other words called as cluster beans. We have kept it simple by adding gawar phali and methi with sautéed onions, garlic and tomatoes till it is soft and mushy. Simple Indian masalas like red chilli powder, coriander powder and garam masala are added to lift up the flavour of the dish.', '["1 cup Methi Leaves (Fenugreek Leaves) , chopped", "300 grams Gawar Phali (Kothavarangai / Cluster beans) , cut small", "1 Onion , chopped", "1 Tomato , chopped", "4 cloves Garlic , chopped", "1 inch Ginger , chopped", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "Salt , to taste", "1 teaspoon Jaggery", "Oil"]'::jsonb, ARRAY['methi leaves', 'fenugreek leaves', 's gawar phali', 'kothavarangai / cluster beans', 'onion', 'tomato', 's garlic', 'ginger', 'red chilli powder', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'garam masala powder', 'salt', 'jaggery', 'oil']::text[], '["To begin making the Gawar Phali Methi Ki Sabzi Recipe, chop the cluster beans/ gawar phali and keep it ready.Add the chopped vegetables into a pressure cooker with 3 tablespoons of water along with some salt to taste.", "Pressure cook for 2 whistles and release the pressure immediately.", "Open the lid of the pressure cooker to maintain the green color of the vegetable.Heat a pan with oil, add ginger & garlic and saute till they turn soft.", "Add in onions and saute and cook till the onions turn translucent.Once the onions are soft, you can add chopped tomatoes now and add a pinch of salt and cook till the tomatoes turn mushy.Add chopped methi leaves and saute till the leaves wilt, this will take about 3 minutes.Once done, add the cooked Gawar Phali, along with red chilli powder, turmeric, coriander, garam masala powder and sugar.Mix well, saute for about a minute until all the ingredients are well combined.", "Give the\u00a0Gawar Phali Methi Ki Sabzi a taste and adjust the salt and spices accordingly.", "Turn off the heat.Transfer the\u00a0Gawar Phali Methi Ki Sabzi to a serving bowl and serve hot.Serve the\u00a0Gawar Phali Methi Ki Sabzi\u00a0Recipe along with\u00a0Lauki Chana Dal,\u00a0Palak Ragi & Oats Wheat Thepla\u00a0, and\u00a0Cauliflower & Cucumber Raita\u00a0to make your meal complete for your weekday lunch."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Gawar_Phali_Methi_Ki_Sabzi_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/955.Gawar_Phali_Methi_Ki_Sabzi_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Style Sangacho Ross Recipe-Drumstick Curry', 'goan-style-sangacho-ross-recipe-drumstick-curry', 'Sangacho Ross Recipe is a traditional Goan Drumstick Curry that is delicious, nutritious and one of the typical preparations during vegetarian days in a Goan household. This is a complex curry, made with simple ingredients. It gets its texture thanks to the coconut, extra depth and silkiness from the dal and a whole load of nutrition from the drumsticks. Kokum is usually used as the souring agent, but like in this recipe you can use tamarind which is easily available in every home.', '["5 tablespoons Arhar dal (Split Toor Dal)", "2 Drumstick", "1/2 Onion , chopped", "4 tablespoons Fresh coconut , grated", "1 teaspoon Coriander (Dhania) Seeds", "2 Dry Red Chillies , adjust according to spice threshold", "1 Tamarind , marble sized ball", "5-6 Whole Black Peppercorns", "1 teaspoon Turmeric powder (Haldi)"]'::jsonb, ARRAY['arhar dal (split toor dal)', 'coconut', 'dry red chillies spice threshold', 'black peppercorns', 'drumstick', 'tamarind marble', 'coriander (dhania) seeds', 'onion', 'turmeric powder']::text[], '["To begin making the Sangacho Ross, first soak the toor dal in water for 2 hours, then pressure cook the dal along with the chopped onion.Meanwhile, peel and cut the drumsticks into 3 inch pieces.Place them in a pot of water, over a heat and bring the water to a boil.", "Allow the drumsticks to cook for 5-6 minutes and then turn the heat off, drain the water, reserving the water and the drumsticks for later use.To prepare the masala, grind all the ingredients mentioned above under \u201cFor the gravy\u201d along with half cup water and keep aside.Next, place a saucepan on the heat, add in the cooked dal, the freshly ground gravy masala and the boiled drumsticks.", "Add water depending on how thick or thin you want the drumstick curry to be - for this you may use the water in which the drumsticks were cooked.Bring the drumstick curry to a boil and allow it to simmer until the masalas have cooked thoroughly, and no longer has the raw smell.Finally, add a teaspoon of salt or as per your taste,mix well and serve.Serve the Goan Drumstick Curry along with\u00a0Plain Rice\u00a0and traditional\u00a0Aavryachi Bhaji\u00a0or\u00a0Maskachi Bhaji\u00a0for a Goan lunch or dinner."]'::jsonb, 40, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Goan_Drumstick_Curry__Sangacho_Ross.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/956.Goan_Drumstick_Curry__Sangacho_Ross.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Broccoli & Vegetable Coconut Curry Recipe', 'broccoli-vegetable-coconut-curry-recipe', 'The Broccoli & Vegetable Curry Recipe is a twist to the traditional curry from the Mangalorean Cuisine in Karnataka. This curry is made from roasted condiments and made into a curry paste with coconut. The broccoli is cooked and simmered in a tangy and spicy coconut curry base, that brings out the best flavors of this dish. Serve the Broccoli & Vegetable Coconut Curry, along with Neer Dosa or Kerala (Lachha) Paratha or even plain steamed rice.', '["400 grams Broccoli , cut into florets", "1 Red Bell pepper (Capsicum) , thinly sliced", "1 Onion , chopped", "4 Dry Red Chilli", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 tablespoon Coriander (Dhania) Seeds", "1 teaspoon Cumin seeds (Jeera)", "1 tablespoon Whole Black Peppercorns", "Tamarind , lemon size", "2 cups Fresh coconut , grated", "3 cloves Garlic", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Oil , for cooking"]'::jsonb, ARRAY['salt', 'red bell pepper (capsicum)', 'sunflower oil', 'coconut', 'black peppercorns', 'cloves garlic', 'dry red chilli', 'coriander (dhania) seeds', 'onion', 'broccoli', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'turmeric powder', 'tamarind lemon']::text[], '["To begin making the\u00a0Broccoli & Vegetable Coconut Curry Recipe, we will first make the Broccoli Curry Masala.", "In a small pan; roast the dry red chillies, fenugreek, coriander, cumin and black pepper until you can smell the roasted aromas.", "Add these to a small blender jar, along with the coconut, tamarind and turmeric powder.", "Grind the spices adding very little water to make a smooth curry paste.", "The curry paste is now ready.", "Keep aside.In the next step; heat a teaspoon of oil in a pan; add the chopped onions, broccoli and red bell peppers and saute for a couple of minutes until the onions are soft and tender.", "Add the curry paste and saute for a couple of more minutes.", "Stir in salt and add about 1-1/2 to 2 cups of water.", "You essentially want a thick gravy for the Broccoli Curry; hence add water accordingly.", "Give all the ingredients a good stir.", "Check the salt levels and adjust to suit your taste.", "Give the mixture a quick boil only when you are ready to serve.", "Serve the Broccoli & Vegetable Coconut Curry, along with Neer Dosa or Kerala (Lachha) Paratha or even plain steamed rice."]'::jsonb, 60, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Broccoli_and_Vegetable_Curry_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/957.Broccoli_and_Vegetable_Curry_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Makki and Methi Roti Recipe', 'makki-and-methi-roti-recipe', 'Makki Roti with Sarson Saag is everyone''s favourite in winter. But this recipe comes with a twist in our normal makki Roti. It contains the goodness of fenugreek/methi which is healthy and a great way to include green leafy vegetables in our diet.', '["2 cups Makki Ka Atta (Yellow Corn Meal Flour)", "1 1/2 cups Methi Leaves (Fenugreek Leaves) , chopped", "2 Green Chillies , chopped", "1 tablespoon Ajwain (Carom seeds)", "1 tablespoon Kashmiri Red Chilli Powder", "Salt , to taste"]'::jsonb, ARRAY['salt', 'makki ka atta (yellow corn meal flour)', 'kashmiri red chilli powder', 'ajwain (carom seeds)', 'methi leaves (fenugreek leaves)', 'green chillies']::text[], '["To begin making\u00a0Makki and Methi Roti Recipe, heat some water in a pan till lukewarm.In a steel mixing bowl, add Maize flour, chopped fenugreek leaves, green chillies, carom seeds and salt.", "Mix everything well.", "Now add lukewarm water to the maize flour little by little and knead into a soft dough.", "Add some oil on top of the entire ball of dough and keep aside.", "Place a tawa on low heat and let it heat up.", "Next divide the dough into small balls.", "Roll out each ball between two sheets of plastic (cling film) into a circle or you can use your hands with the help of wet fingers to make a small round roti.", "Place roti on the the tawa and cook it on low flame from both sides until brown spots appear.", "Prepare the rest of the the rotis in a similar way and serve hot.", "Serve Makki and Methi Roti with\u00a0Sarson Ka Saag\u00a0and\u00a0Burani Raita\u00a0for a delicious weekday meal."]'::jsonb, 30, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pooja/Makki_and_Methi_Roti.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/958.Makki_and_Methi_Roti.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Warqi Paratha Recipe', 'warqi-paratha-recipe', 'Warqi Paratha Recipe is a delicious flaky paratha. Warqi means layers, the dough is flattened and folded multiple times, each times brushed generously with butter and dusted with flour to help those layers stand out beautifully.', '["4 cups All Purpose Flour (Maida)", "3/4 cup Ghee", "Salt , to taste", "2 teaspoons Sugar", "1 cup Milk", "1/3 cup Ghee , melted, for the layers", "Water , as required", "All Purpose Flour (Maida) , to dust", "Ghee , to shallow fry the parathas"]'::jsonb, ARRAY['salt', 'ghee', 'milk', 'water', 'sugar', 'flour (maida) dust', 'ghee the parathas', 'flour (maida)']::text[], '["To begin making the Warqi Paratha Recipe, we need to make the dough first.", "In a mixing bowl, combine the all purpose flour along with the salt, sugar, ghee and milk.Mix well.", "To bring the dough together use just enough water and make the warqi dough ball, kneading well.", "Once you have a nice smooth warqi dough ball, cover with a wet muslin cloth and set aside for 30 minutes.", "After 30 minutes, place the warqi dough on a work surface and flatten the entire dough with your palms, dust some flour over the dough on both sides and begin to now flatten it with the rolling pin.", "Once you have a nice big rectangular shaped flattened dough, generously spread melted brush on the surface using a pastry brush.", "Now sprinkle some flour over it.", "We need to now fold the warqi dough.", "To do this, fold one end of the dough to the centre of the dough and yet brush ghee and sprinkle flour over it.", "Now fold the other side of the dough over lapping over the first fold to get one vertical rectangle.", "Once again brush ghee and sprinkle flour and fold into a square.", "Generously, dust with flour, transfer to a plate and allow it to rest in the refrigerator for 20 minutes.", "Now repeat the process twice,\u00a0 from scratch by rolling this square dough into a rectangular dough sheet and fold like we did earlier, with layers of ghee and flour.", "Refrigerate the paratha after each folding process.", "Now roll out to medium thickness, by dusting it with flour, and cut using a cookie cutter or a cake ring.", "To cut the warqi parathas, dip the ring in the flour and\u00a0 place over the flattened dough applying pressure.", "Preheat an iron tawa on medium- high heat.", "Rest the cut warqi parathas in the fridge for about 20 minutes.", "Place the\u00a0warqi on preheated tawa.Cook the warqi for a minute on each side and then drizzle ghee generously and\u00a0you will be able to see the layers from the edges.", "Now remove the warqi paratha from the tawa and transfer it on a paper towel, hold the warqi paratha in your palms and lightly crush it to see the layers.", "Serve\u00a0Warqi Paratha along with\u00a0Shahi Paneer Recipe,\u00a0Creamy Dal Makhani Recipe,\u00a0Pudina Pyaz Kachumber Salad Recipe - Mint & Onion Salad,\u00a0Kashmiri Pulao Recipe - Pulao Spiced With Saffron, Whole Spices & Nuts,\u00a0Coriander Tadka Raita Recipe."]'::jsonb, 145, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Articles/Chakori_Warqui_Recipe_Flaky_Paratha_5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/959.Chakori_Warqui_Recipe_Flaky_Paratha_5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pyaz Wali Bhindi Recipe | Bhindi Do Pyaza - Okra Onion Stir Fry', 'pyaz-wali-bhindi-recipe-bhindi-do-pyaza-okra-onion-stir-fry', 'Pyaz Wali Bhindi Recipe/ Bhindi Do Pyaza is a delicious preparation of bhindi/ okra sauteed with caramelized onions.', '["500 grams Bhindi (Lady Finger/Okra)", "2 tablespoon Mustard oil , or Sunflower oil", "1 teaspoon Ajwain (Carom seeds)", "2 inch Cinnamon Stick (Dalchini) , broken", "1 Bay leaf (tej patta)", "3 Onions , thinly sliced", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder , (or more to taste)", "2 teaspoons Coriander (Dhania) Powder", "2 teaspoons Amchur (Dry Mango Powder)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard oil sunflower oil', 'amchur (dry mango powder)', 'bay leaf (tej patta)', 'ajwain (carom seeds)', 'red chilli powder', 'cinnamon stick (dalchini)', 'onion', 'coriander (dhania) powder', 'bhindi (lady fingerokra)', 'turmeric powder']::text[], '["To begin making\u00a0Pyaz Wali Bhindi Recipe Bhindi Do Pyaza, first wash bhindi in water.", "Pat dry with the kitchen towel.", "To cut okra first remove the stem of the bhindi and then cut into thin strips of 4 pieces.", "Keep aside until ready to use.", "Heat the oil in a heavy-bottomed\u00a0saucepan over medium heat.", "Add the ajwain seeds and allow it to crackle.", "Add the cinnamon stick, bay leaf and saute for a few seconds.", "Add the thinly sliced onions, turn the heat to low and saute the onions until they soften.At this stage add in the chopped lady''s finger, sprinkle salt, turmeric powder, red chilli powder, coriander powder and amchur powder.Stir until all the ingredients get well combined.", "Cover the pan with the lid slightly ajar.", "Keep the heat on low and let bhindi do pyaza cook until it turns soft and tender.", "This process will take about 15 minutes on medium heat.Ensure to keep stirring the bhindi do pyaza a few times in between so it gets cooked evenly and towards the end you will notice the onions have slightly caramelised as well.Once done, turn off the heat and check the salt and spices and adjust to taste accordingly.Transfer the\u00a0Pyaz Wali Bhindi/ Bhindi Do Pyaza to a serving bowl and serve hot.Serve the Pyaz Wali Bhindi/ Bhindi Do Pyaza\u00a0Recipe along with\u00a0Parathas\u00a0and\u00a0Kadhi Pakora\u00a0for a delicious lunch or dinner."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/bhindi_do_pyaza_recipe_pyaz_wali_bhindi_5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/960.bhindi_do_pyaza_recipe_pyaz_wali_bhindi_5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ragi Rava Dosa Recipe With Oats - Finger Millet & Oats Dosa Recipe', 'ragi-rava-dosa-recipe-with-oats-finger-millet-oats-dosa-recipe', 'Ragi Rava Dosa Recipe With Oats is delicious and healthy combination of Oat and Ragi made into a batter and prepared to make a crispy dosa. Ragi and Oatmeal flour are whisked together and spiced up with green chillies, coriander leaves and cumin seeds.', '["1/2 cup Ragi Flour (Finger Millet/ Nagli)", "1/4 cup Instant Oats (Oatmeal)", "1/4 cup Rice flour", "1/4 cup Sooji (Semolina/ Rava)", "3-1/2 cups Water", "2 Green Chillies , finely chopped", "1 inch Ginger , grated", "1/2 teaspoon Whole Black Peppercorns , crushed", "1 teaspoon Cumin powder (Jeera)", "2 sprig Coriander (Dhania) Leaves , chopped", "Salt , to taste", "Ghee , for cooking the dosa"]'::jsonb, ARRAY['ragi flour', 'finger millet/ nagli', 'instant oats', 'oatmeal', 'rice flour', 'sooji', 'semolina/ rava', 's water', 'reen chillies', 'ginger', 'whole black peppercorns', 'cumin powder', 'jeera', 'coriander', 'dhania', 'salt', 'ghee']::text[], '["To begin making the Ragi Rava\u00a0Dosa Recipe, in a large bowl combine the Semolina, Ragi & Rice flours and salt.", "Stir 3 cups of water to make a thick batter.", "Allow the batter to rest for about 10 minutes.Stir in the remaining ingredients into the ragi rava\u00a0dosa batter - green chillies, grated ginger, peppercorns, cumin seeds and finely chopped coriander leaves.", "Combine well.Finally add 1/2 cup more water to the batter to make it of thin pouring consistency.", "It will be thinner than the pancake/dosa batter.When the ragi rava\u00a0dosa batter is thin, it spreads wild on a heated skillet, producing holes in the dosa and making it crispHeat a iron skillet or dosa tawa on high heat.", "Make sure the skillet is very hot.", "To test the heat, sprinkle some water on the skillet, it will sizzle when its hot.", "Pour a ladle of the ragi rava dosa batter starting from the outer edges.", "The batter will sizzle and spread itself forming holes.", "Pour the batter from a height, Fill in the batter where there are gaps.", "Although allow the dosa to have a few holes.Turn the heat to medium, if you want a crisp ragi oats dosa.", "The slower it cooks, the crispier it gets.Drizzle about 1/2 teaspoon of ghee around the dosa and allow it to cook for 2-3 minutes on medium heat.Once golden and crisp on one side turn it over and allow to cook for another minute.", "At this stage the dosa will be thin and crisp, with one side golden brown in color.Remove the Ragi Rava Dosa With Oats off the skillet.", "Repeat to make the remaining dosas.Serve the Ragi Rava Dosa With Oats\u00a0with just a cup of yogurt, or with\u00a0Thakkali Vengaya Sambar\u00a0and\u00a0Tomato Chutney\u00a0or even just along with jaggery and butter."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Ragi_Oats_Rawa_Dosa_Recipe_7_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/961.Ragi_Oats_Rawa_Dosa_Recipe_7_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Khatti Meethi Palak Khichdi Recipe', 'khatti-meethi-palak-khichdi-recipe', 'Khatti Meethi Palak Khichdi Recipe is a delectable khichdi which is packed with taste, flavours and nutrition.', '["1 tablespoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 Tomato , finely chopped", "2 inch Ginger , finely chopped", "1 inch Cinnamon Stick (Dalchini) , broken", "1 Bay leaf (tej patta) , torn", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Asafoetida (hing)", "1 tablespoon Jaggery", "1 Lemon , juice extracted", "Salt , to taste", "3/4 cup Rice", "3/4 cup Arhar dal (Split Toor Dal)", "300 grams Spinach , chopped", "2 tablespoons Ghee , to be added after khichdi is cooked"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'arhar dal (split toor dal)', 'rice', 'mustard seeds', 'ghee', 'bay leaf (tej patta)', 'asafoetida (hing)', 'jaggery', 'red chilli powder', 'spinach', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'lemon', 'ghee be ed after khichdi', 'turmeric powder']::text[], '["To begin making the Khatti Meethi Palak Khichdi first prep all the ingredients and keep them ready.We will cook the palak separately and then add it to the khichdi.", "This will help retain the nutrition and the fresh green colour of the palak.Add the chopped palak into the pressure cooker, add 2 tablespoons of water, cover the pressure cooker and cook until you hear 2 whistles.After 2 whistles turn off the heat. release the heat from the pressure cooker either by rinsing it under cold water or by lifting the weight with a fork to release the pressure.", "Releasing the pressure immediately helps retain the fresh green colours of the palak.Open the pressure cooker and keep the palak aside.", "Next step is to make the\u00a0Khatti Meethi Palak Khichdi.", "Rinse the rice and toor dal in water, drain excess water and keep aside.Heat 1 tablespoon of ghee in the pressure cooker over medium heat.", "Add mustard seeds, cumin seeds and allow it to crackle.Add the cinnamon stick and bay leaves and stir for a few seconds.", "Add the ginger, tomatoes, green chillies, turmeric powder, red chilli powder, asafoetida and saute until the tomatoes become slightly soft.Add the washed rice and dal, salt, jaggery, 4 cups of water and cover the pressure cooker.Pressure cook the Khichdi for about 4 to 5 whistles and turn off the heat.", "Allow the pressure to release naturally as the khichdi will continue to cook while the pressure is present.Once the pressure is released, open the cooker and stir in the cooked palak/ spinach.", "Stir in the lemon juice and the additional ghee and give it a brisk boil for 2 minutes.Turn off the heat and check the taste and adjust the salt and seasonings accordingly.", "Once done, transfer the Khatti Meethi Palak Khichdi to a serving bowl and serve hot.Serve the Khatti Meethi Palak Khichdi topped with ghee, sliced onions and papad for a wholesome meal."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Khatti_Meethi_Palak_Khichdi_Recipe_8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/962.Khatti_Meethi_Palak_Khichdi_Recipe_8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Bhey Ki Sabzi Recipe (Potato Lotus Stem Curry)', 'aloo-bhey-ki-sabzi-recipe-potato-lotus-stem-curry', 'Aloo Bhey Ki Sabzi Recipe is a delicious North Indian dish made of Potato and Lotus stem. It’s a simple preparation, but tastes heavenly both with rotis and rice. If you like to try something different, and want to taste lotus stems, this is a easy dish to prepare. You can make it as a side dish and it will perk up a simple weeknight dinner of Phulkas and Pumpkin Dal Tadka.', '["3 Potatoes (Aloo) , peeled and diced", "1 cup Lotus Stem , sliced round", "1/2 cup Homemade tomato puree", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "2 teaspoons Coriander Powder (Dhania)", "1 teaspoons Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "Salt , to taste", "Oil , for cooking", "4 sprig Coriander (Dhania) Leaves , finely chopped", "Ingredients to be made into a paste", "2 Onions , roughly chopped", "4 Garlic", "1 inch Ginger", "4 Green Chillies"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'coriander powder', 'asafoetida (hing)', 'red chilli powder', 'coriander (dhania) leaves', 'onion', 'cumin seeds (jeera)', 'garlic', 'lotus stem', 'potato (aloo)', 'turmeric powder', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Aloo Bhey Ki Sabzi Recipe, we will first prep all the various components.First of all, place the ingredients listed under \u201cIngredients to be made into a paste\u201d into a blender and grind them down into a smooth paste.", "Pour it into a bowl and set it aside for later.Then add 3 small tomatoes into the blender and blend them to a puree.", "Pour the puree into a bowl and set that aside too.Now to make the sabzi, heat some oil in a pressure cooker.", "When it is warm enough, add asafetida and cumin seeds and let them crackle.Next add the prepared onion garlic paste and saute well for 3-4 minutes until the paste turns golden-brown and the raw smell goes away.Next add the red chilli powder, turmeric and coriander powder.", "Top with salt and continue to cook for 2 minutes more.At this stage, when the masalas are all cooked through, pour in the prepared tomato puree and cook for another 3-4 minutes, stirring continuously, until you see oil leaving the sides of the pan.", "This is an indication that the masalas are cooked through.Now add cubed potato and lotus stem rounds, stir well and cook for 2-3 minutes.Top it up with 2 cups of water and cover the pressure.", "Allow the sabzi to cook covered for 2 whistles.Turn the heat off and allow the pressure to release natural.", "When the weight can be lifted and the lid comes off with ease, open the cooked and simmer the sabzi for 5 minutes.", "This will allow some excess water to evaporate.", "At this stage you can taste for salt and spice and adjust both accordingly.When done, take the pressure cooked off the heat, pour the sabzi into a serving bowl and serve hot with\u00a0Phulkas\u00a0and\u00a0Pumpkin Dal Tadka."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Sapana_Behl/Potato_Lotus_Stem_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/963.Potato_Lotus_Stem_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Traditional Amritsari Chole Recipe | Punjabi Chole Masala', 'traditional-amritsari-chole-recipe-punjabi-chole-masala', 'Traditional Amritsari Chole is an authentic recipe which gives the Punjabi chole a rich dark colour and taste delicious from the freshly made amritsari chole masala . When you travel to Amritsar, regions around Punjab, Delhi and surroundings, this is a popular and most common staple which gets served. Walk into any dhaba on highway, you will find this delicious Amritsari Chole served along with freshly made Kulcha or Naan.', '["1 cup Kabuli Chana (White Chickpeas) , soaked overnight (8 hours)", "1 Tea bags", "3 tablespoons Ghee", "1 Onion , finely chopped", "1 Green Chilli , finely chopped", "2 inch Ginger , finely chopped", "1 Tomato , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 tablespoon Amchur (Dry Mango Powder)", "1 teaspoon Black Salt (Kala Namak)", "Salt , to taste", "Coriander (Dhania) Leaves , as required, for garnishing", "Amritsari Chole Masala Powder", "1 inch Cinnamon Stick (Dalchini)", "5 Cloves (Laung)", "1 Brown cardamom (Badi Elaichi)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1 tablespoon Cumin seeds (Jeera)", "2 tablespoons Coriander (Dhania) Seeds", "1 tablespoon Dried Anardana Seeds (Pomegranate Seeds Dried)", "5 Dry Red Chillies", "1 teaspoon Whole Black Pepper Corns"]'::jsonb, ARRAY['tomato', 'coriander (dhania) leaves', 'kabuli chana (white chickpeas)', 'coriander (dhania) seeds', 'onion', 'turmeric powder', 'salt', 'green chilli', 'dry red chillies', 'brown cardamom (badi elaichi)', 'tea bags', 'black pepper corns', 'methi seeds (fenugreek seeds)', 'dried anardana seeds (pomegranate seeds dried)', 'cumin (jeera) seeds', 'black salt', 'ginger', 'amchur (dry mango powder)', 'ghee', 'cinnamon stick (dalchini)', 'cloves (laung)']::text[], '["To begin with, the Amritsari Chole Recipe, first prep all the ingredients and keep them ready.", "Ensure the Kabuli Chana/ Chickpeas was soaked for 8 hours or overnight in water.", "Add the soaked chana into the pressure cooker, add a teaspoon of salt and the tea bag.", "Ensure the water level is at least 2 inches above the level. of chana.Note: The addition of tea bag while cooking the chana, help give the Amritsari chole a lovely deep colour.", "If you don''t have tea bags, then you can make a small potli and add dark tea leaves into it and tiet it with a cotton thread and add it to the pressure cookerPressure cook the chickpeas/ kabuli chana for about 35 to 40 minutes on medium heat.", "There will be multiple rounds of whistles from the pressure cooker.", "After the first 15 minutes, turn the heat to low and continue pressure cook for the remaining time.Turn off the heat and allow the pressure to release naturally.", "In the meanwhile,we will make the Amritsari Chole Masala Powder.Preheat a skillet over medium heat; add all the spices and ingredients mentioned in the Chole Masala Powder section - coriander seeds, cumin seeds, methi seeds, cinnamon, cloves, badi elaichi,red chillies, anardana seeds and black pepper corns.", "Roast all of them on medium high heat for about 5 minutes until you get a roasted aroma and the spices start getting a roasted colour.", "Ensure you keep stirring it while they are getting roasted - so they get roasted eventy from all sides.Once done, turn off the heat and allow it to cool a bit.", "Once cooled, add the roasted chole masala spices into a small jar of the mixer grinder and blend to make smooth powder.Keep the Amritsari chole masala powder aside.Final step is to bring all the masala together.Add 2 tablespoons of ghee to a preheated pan over medium heat; add the onion, ginger and saute until the onion softens.Once the onion softens, add the dry Amritsari chole masala, chopped tomatoes, turmeric powder and kala namak and saute the tomatoes until it becomes mushy and soft.", "Once the tomatoes are soft.", "Add the cooked kabuli chana/ chickpeas into the chole masala.", "Stir well to combine.Cover the pan and simmer the Amritsari Chole Masala for a good 15 minutes.After 15 minutes of simmering, keep the pan uncovered and cook it open until the Amritsari chole masala has a thick gravy consistency.", "Mash a few chana a little to make it a thick gravy if required.", "Check the salt at this stage and add more if required.", "Once done, add the remaining 1 tablespoon of ghee and give it a brisk boil for a minute and turn off the heat.", "Finally garnish with coriander leaves and serve hot.Serve the Amritsari Chole along with\u00a0Bhatura,\u00a0Puri, or\u00a0Kulcha\u00a0and pair it along with\u00a0lacha pyaz,\u00a0boondi raita\u00a0and some green chillies by the side for a special weekend lunch."]'::jsonb, 50, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Amritsari_Chole_Masala_Recipe_Punjabi_Chole_Masala_Chana_Masala_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/964.Amritsari_Chole_Masala_Recipe_Punjabi_Chole_Masala_Chana_Masala_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Moong Dal Sookhi Sabzi Recipe', 'moong-dal-sookhi-sabzi-recipe', 'Moong Dal Sookhi Sabzi is perfect for a weeknight dinner as this recipe is simple, quick and light on your tummy. Simple spices like turmeric powder, chilli powder and garam masala is added to the moong dal sookhi Sabzi. Lemon is added after the dal is cooked to give it slight tang. Though minimally spiced Moong Dal sookhi Sabzi is flavourful and delicious.', '["1 cup Yellow Moong Dal (Split)", "1 tablespoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "Salt , to taste", "2 tablespoon Oil", "1 Green Chilli", "1 tablespoon Lemon juice", "Coriander (Dhania) Leaves , as required to garnish"]'::jsonb, ARRAY['salt', 'yellow moong dal (split)', 'green chilli', 'coriander (dhania) leaves', 'red chilli powder', 'lemon', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making Moong Dal Sookhi Sabzi, first wash the Moong dal and set it aside.Heat oil in a deep pan and add red chilly powder, turmeric powder and salt.", "Stir it for 10-12 seconds.", "Do not let the spice powders burn.After 10-12 seconds, add the washed lentil to this and give it a good stir.Add enough water to cover the dal, reduce the heat and cover the pan with a lid.Cook the dal till the water gets evaporated.", "Check if the dal is cooked, if not add a little more water and cook till the dal is cooked properly.Make sure that you do not over cook the dal.", "Once done, open the lid, turn the heat to high, add garam masala powder and give it a good stir.Saute the Moong Dal Sookhi Sabzi till it is completely dry.", "After the dal has dried completely, turn off the heat and transfer it to the serving bowl, add chopped green chillies, coriander leaves and lemon juice on the top.Serve\u00a0Moong Dal Sookhi Sabzi Recipe with\u00a0Lauki raita,\u00a0Phulkas\u00a0and\u00a0kachumber salad\u00a0for lunch or dinner."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuri_Aggarwal/Moong_Dal_Sookhi_Sabzi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/965.Moong_Dal_Sookhi_Sabzi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Style Dhokar Dalna Recipe (Spiced Lentil Cakes in Tomato Gravy Recipe)', 'bengali-style-dhokar-dalna-recipe-spiced-lentil-cakes-in-tomato-gravy-recipe', 'Bengali Style Dhokar Dalna Recipe (Spiced Lentil Cakes in Tomato Gravy Recipe) is traditional recipe of Dalna which is made from a blend of channa dal and urad dal. Dals are spiced and then blended into a smooth batter. It is then steamed like “Dhoklas” and pan fried. These Steamed and pan fried cakes are then immersed in a thin tomato gravy. The dish is famous among the vegetarian in Bengal and it is considered as pure Satvik as there is no Garlic added to it.', '["1/2 cup Chana dal (Bengal Gram Dal)", "1/2 cup White Urad Dal (Whole)", "1/2 inch Ginger , grated", "1 Green Chilli , chopped", "2 teaspoon Cumin seeds (Jeera) , roasted", "Salt , to taste", "1 teaspoon Sugar", "1 Tomato , blanched and pureed", "1 Potato (Aloo) , cubed", "1 inch Ginger , grated", "2 Green Chillies , finely chopped", "1 teaspoon Turmeric powder (Haldi)", "2 teaspoon Red Chilli powder", "2 teaspoon Cumin powder (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "1 Bay leaf (tej patta)", "2 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "1/2 teaspoon Cumin seeds (Jeera)", "Ghee , for cooking"]'::jsonb, ARRAY['tomato', 'salt', 'green chillies', 'ginger', 'cumin powder (jeera)', 'green chilli', 'bay leaf (tej patta)', 'cardamom (elaichi) podsseeds', 'ghee', 'potato (aloo)', 'red chilli powder', 'sugar', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'chana dal (bengal gram dal)', 'white urad dal']::text[], '["We begin making the Bengali Style Dhokar Dalna Recipe (Spiced Lentil Cakes in Tomato Gravy Recipe) by soaking the dal for at least three hours.", "Then into the grinder, add all the ingredients along with the dal and little water and grind it into a smooth rice batter consistency.Pour the batter into the Dhokla Pan and steam it for about 30 minutes.", "Till it is firm and not sticky.", "Place it outside and let it cool.", "Cut into diamonds and pan fry them using a shallow frying pan till it is brown and crisp on either side.Next for the gravy blanch the tomatoes in boiling water over a sauce pan for about 2 minutes.", "Then remove the skin and blitz it in a mixer to a smooth puree.Heat a kadai with oil and add ingredient along with the ginger that are mentioned in the seasoning list.", "Let it saut\u00e9 for few minutes.", "Then add the tomato puree, along with all the spice and saut\u00e9 till the raw smell goes away.", "Add 1 cup water and let it simmer for about 20 minutes.Once done add in the cakes and can served by sprinkling chopped coriander leaves.Serve the Bengali Style Dhokar Dalna Recipe (Spiced Lentil Cakes in Tomato Gravy Recipe) along with\u00a0Hot Phulka\u00a0to enjoy your meal."]'::jsonb, 225, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Bengali_Style_Dhokar_Dalna_Recipe_Spiced_Lentil_Cakes_in_Tomato_Gravy_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/966.Bengali_Style_Dhokar_Dalna_Recipe_Spiced_Lentil_Cakes_in_Tomato_Gravy_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mooli Paratha Recipe - Indian Flat Bread with Radish', 'mooli-paratha-recipe-indian-flat-bread-with-radish', 'The Mooli Paratha Recipe is a flatbread made from whole wheat flour and grated radish, flavored with cumin, coriander and green chillies. In this recipe of Mooli Paratha Recipe I have added the radish into the dough that makes the cooking process of the paratha easier and you get a delicious tasting thin soft bread.', '["2 cups Whole Wheat Flour", "3 Mooli/ Mullangi (Radish) , grated (approximately 2 cups)", "2 Green Chillies , finely chopped", "2 teaspoons Cumin powder (Jeera)", "1 teaspoon Turmeric powder (Haldi)", "2 sprig Coriander (Dhania) Leaves", "Salt , salt to taste", "Oil , oil for cooking"]'::jsonb, ARRAY['s whole wheat flour', 'mooli/ mullangi', 'radish', 'reen chillies', 's cumin powder', 'jeera', 'turmeric powder', 'haldi', 'coriander', 'dhania', 'salt', 'oil']::text[], '["To begin making the Mooli Paratha (Thepla) Recipe, we will first cook the mooli.", "Heat a teaspoon of oil in a stir fry pan; add in the grated mooli, sprinkle some salt and saute on medium heat until the mooli is soft.", "Turn off the heat and allow the mooli to cool completely.Once the mooli is cooled, in a large bowl combine, the mooli,\u00a0whole wheat flour,\u00a0green chillies,\u00a0cumin powder, turmeric powder,\u00a0coriander leaves and\u00a0salt to taste.", "The mooli will already have a lot of moisture in it, so when you knead the ingredients into a mooli paratha dough, add the water a little at a time.Knead to make a smooth and soft mooli paratha dough.", "Add a teaspoon of oil once you have kneaded the mooli paratha dough, so that the dough feels non sticky to touch.", "If you kneaded the paratha dough well for at least 3 to 4 minutes, then you can start making the Mooli Paratha right away.Preheat the iron skillet on medium heat.", "Divide the mooli paratha dough into 15 portions.Roll the portions into balls; flatten them with the palm of your hand.", "Toss the mooli paratha dough on flour and roll them out into thin circles to approximately 6 inches in diameter.As you roll them out, you can keep tossing the mooli paratha dough in dry flour to prevent sticking when rolling them out.Continue the same process of rolling the mooli paratha dough out with the remaining balls.", "It is ideal when you can roll out the all portions of mooli paratha dough before you can start cooking them."]'::jsonb, 45, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breads/Mooli_Paratha_Thepla_Radish_Flat_Bread_Indian_Recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/967.Mooli_Paratha_Thepla_Radish_Flat_Bread_Indian_Recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mughlai Style Chicken Changezi Recipe', 'mughlai-style-chicken-changezi-recipe', 'Mughlai Style Chicken Changezi Recipe is one of the gems of Mughlai Cuisine,', '["2 tablespoon Curd (Dahi / Yogurt)", "1 teaspoon Ginger Garlic Paste", "1 tablespoon Coriander Powder (Dhania)", "3/4 teaspoon Cumin powder (Jeera)", "Salt , to taste", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "1-1/2 teaspoon Kashmiri Red Chilli Powder", "2 tablespoons Oil", "750 grams Chicken , cleaned", "4 tablespoons Oil", "1 tablespoon Ginger , finely chopped", "1 tablespoon Garlic , finely chopped", "1 cup Homemade tomato puree", "2 Onions , chopped, roasted till soft and ground to paste", "Salt , to taste", "Red Chilli powder , Red chili powder to taste", "2 tablespoon Fresh cream"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'kashmiri red chilli powder', 'ginger', 'red chilli powder red chilli powder', 'ginger garlic paste', 'curd', 'garlic', 'chicken', 'onion', 'coriander powder', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'sunflower oil']::text[], '["To begin making the Chicken Changezi recipe, pat dry the chicken well after cleaning and prick it with a fork.", "This helps in getting the marinade deep inside chicken.To marinate the chicken , in a mixing bowl, combine the chicken along with\u00a0dahi,\u00a0ginger garlic paste, coriander powder,\u00a0cumin powder, salt,\u00a0turmeric powder, kasturi methi, kashmiri red chili powder, and marinade for 3-4 hours.Now bake chicken at 180\u00b0C for 30-40 minutes according to the size of the chicken pieces.", "Burn a small piece of charcoal on the direct flame.Place your chicken in a dish, once it is cooked.", "In the middle place a katori.", "Put the blazing charcoal in that katori and pour ghee over it.", "Cover and let it rest till all the smoke is infused in the chicken.", "This will give you a smoky flavor to chicken.", "Now, for the gravy, heat oil in a heavy bottomed pan.", "Add the ginger garlic and cook for about 30 seconds or till the raw smell disappears.Add tomato puree and masala gravy of onions.", "Cook until all comes together (about 2-3 minutes).", "Add salt, red chilli powder and baked chicken.Now cook for 5-7 minutes so that gravy is well absorbed by chicken.", "In the end simply add the cream, mix and serve.", "Garnish with coriander leaves.Serve\u00a0Chicken Changezi along with\u00a0Garlic Naan\u00a0or\u00a0Jeera Rice\u00a0and\u00a0Pickled Onions\u00a0\u00a0for a soulful meal followed by a dessert of\u00a0Malpua With Rose And Saffron Syrup Recipe."]'::jsonb, 60, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/theyellowdaal/Chicken_Changezi_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/968.Chicken_Changezi_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Homemade Mysore Pak Recipe | Traditional Recipe Made With Ghee', 'homemade-mysore-pak-recipe-traditional-recipe-made-with-ghee', 'Mysore Pak is a delectable Indian sweet made from roasted gram flour and pure homemade ghee. A very traditional south Indian sweet is rich and makes a perfect sweet to be made for special occasions and festivals like Diwali.', '["1 cup Gram flour (besan)", "1-1/4 cups Ghee", "1-1/4 cups Sugar", "1 cup Water"]'::jsonb, ARRAY['sugar', 'ghee', 'water', 'gram flour (besan)']::text[], '["To begin making Homemade Mysore Pak Recipe, prep all the ingredients and keep them handy.", "Every step comes one after another and hence you need to keep them all ready and handy.Also grease a small rectangular or a square pan which can give you a decent height to be shaped into a Mysore Pak.", "Approximately 10 x 6 inches\u00a0(outer edge) is the size of the pan (inner edge is\u00a0 9 x 4 inches)In a heavy bottomed preheated over medium heat, roast the besan/ gram flour for about 2 to 3 minutes until you get a roasted aroma from the gram flour.", "This will help the raw smell go away from the besan.", "Ensure you take care not to allow it to brown or burn.", "Once roasted remove it into a bowl and keep aside.In a heavy bottomed non stick pan; add the sugar and water and bring the water to a boil ensuring the sugar dissolves completely in the water.", "Keep stirring so that the sugar dissolves well.", "Continue to allow the sugar water to boil - after about 4 minutes you will notice that the sugar water is getting bubbly and sticky as well.", "It will form a foamy texture.At this stage the consistency of the sugar water will be of a sticky and one string consistency.At this stage, turn the heat to low and add the gram flour into the sugar syrup and keep stirring it continuously so it combines well without any lumps and gets a smooth consistency.", "The heat needs to be on low from now on till the end of the making of Mysore Pak.Once the gram flour is combined well, add ghee little at a time and repeat the addition of ghee after 3-4 minutes of stirring.", "The 1-1/2 cups of ghee needs to be added in small batches with a space of 3 minutes between each turn.As you keep adding ghee and waiting for the next batch of ghee to be added, ensure that you keep stirring the Mysore Pak.Once the entire mass comes together and looks smooth, add the last portion of ghee and continue to stir till the whole masses rises up like froth and you will notice that the Mysore pak gets a very porous texture where you see the eye holes while stirring.Once it comes to this consistency, remove from the heat and pour the mysore pak mixture into the greased tray.", "Bang the tray lightly to allow the mass to spread all over and looks evenly spread.Dip a flat spatula with ghee and spread over the Mysore Pak to level it down and make it smooth from the top.", "Continue this light press and spread until the top of the Mysore Pak looks smooth.At this stage, using a knife, cut the Mysore Pak into rectangle or diamond shapes and allow the Mysore Pak to cool down completely.Once completely cooled, gently lift the Mysore Pak pieces out of the pan and serve.Store the Mysore Pak in airtight container for 1 week or in the refrigerator for 2 weeks.Serve Homemade Mysore Pak Recipe as a dessert after Onion Tomato Podi Masala Dosa Recipe and Chutney for breakfast or after lunch."]'::jsonb, 35, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Homemade_Mysore_Pak_Recipe_Traditional_Recipe_Made_With_Ghee_15_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/969.Homemade_Mysore_Pak_Recipe_Traditional_Recipe_Made_With_Ghee_15_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Methi Matar Pulao Recipe - Fenugreek Green Peas Pulao', 'methi-matar-pulao-recipe-fenugreek-green-peas-pulao', 'The Methi Matar Pulao Recipe is a simple, healthy preparation of cooked rice, mixed and spiced up with methi leaves and spices. I often like to use fresh whole spices as the main ingredients to make the methi rice, but you can use a combination of spices and experiment to suit your taste.', '["1 cup Green peas (Matar) , steamed", "1 cup Rice", "200 grams Methi Leaves (Fenugreek Leaves) , rinsed and chopped", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Ginger , grated", "2 Green Chillies , slit", "1 cup Coconut milk", "1/2 teaspoon Turmeric powder (Haldi)", "2 Cloves (Laung)", "2 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta) , torn", "2 tablespoons Ghee , or Sesame oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'ginger', 'ghee sesame oil', 'rice', 'cardamom (elaichi) podsseeds', 'bay leaf (tej patta)', 'methi leaves (fenugreek leaves)', 'green peas (matar)', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'cloves (laung)', 'coconut milk', 'turmeric powder', 'green chillies']::text[], '["To begin making the Methi Matar Pulao Recipe, we will be cooking the pulao in a single pot.", "Keep the steamed green peas aside, we will add it towards the end when the entire pulao is cooked.Begin by heating oil in a\u00a0heavy bottomed pan\u00a0over medium heat.", "Add cumin seeds, grated ginger and saut\u00e9 for a few seconds.Stir in the fenugreek leaves, turmeric powder and saute until the leaves have softened.", "Add in the whole spices, salt, green chilies and the rice,Add in 1 cup of coconut milk and 1 cup of water.", "Check the salt and adjust to suit your taste.Bring the methi rice to a quick boil.", "Once the rice comes to a boil, turn the heat to low, cover the pan and allow the rice to cook along with the spices and methi leaves until all the water is completely absorbed.Once you notice all the water is completely absorbed, turn off the heat and allow the Methi Matar Pulao to rest for about 5 minutes.", "After 5 minutes open the pan, add the steamed peas and a tablespoon of ghee.", "Stir in to combine well into the rice and the Methi Matar Pulao is now ready to be served warm.The\u00a0Methi Matar Pulao\u00a0makes a great lunch box meal filled with nutrition of methi and rice, when served along with\u00a0Tomato Onion Raita\u00a0and a roasted\u00a0Papad."]'::jsonb, 65, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Methi_Matar_Pulao_Recipe_Fenugreek_leaf_rice-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/970.Methi_Matar_Pulao_Recipe_Fenugreek_leaf_rice-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kothamalli Rava Upma Recipe - Coriander Semolina Pudding', 'kothamalli-rava-upma-recipe-coriander-semolina-pudding', 'Kothamalli Rava Upma Recipe is a twist to the usual upma recipes that South Indians prepare for breakfast. Fresh coriander leaves are ground to a smooth paste and then cooked along with sautéed onions to create a delicious and rich flavor. You can also add some roasted cashew nuts for the added texture. The recipe will give you a wonderful start when it is had with ground coconut chutney.', '["1 cup Sooji (Semolina/ Rava)", "1 Onion , finely chopped", "1 Green Chilli , finely chopped", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Black Urad Dal (Split)", "1 sprig Curry leaves", "Salt , as required", "1 teaspoon Sugar", "3 cups Hot water", "1 teaspoon Lemon juice", "To Grind", "6 sprig Coriander (Dhania) Leaves , finely chopped", "1 inch Ginger , chopped", "Green Chilli , chopped"]'::jsonb, ARRAY['salt', 'ginger', 'green chilli', 'mustard seeds', 'water', 'black urad dal (split)', 'curry leaves', 'sugar', 'coriander (dhania) leaves', 'onion', 'lemon', 'sooji (semolina rava)']::text[], '["To begin making the Kothamalli Rava Upma recipe, first grind the coriander leaves for the upma.Into the mixer add coriander leaves, green chillies, ginger and grind into a smooth paste.", "Add a little water to grind to a smooth paste.", "Set aside.", "This is the kothamalli paste.", "In a pan heat 3 cups of water in a saucepan along with salt and sugar.", "Bring it to a boil and stir until the sugar dissolves.", "Turn the heat to low and keep the water simmering.Heat oil in a heavy bottomed pan.", "Add the mustard seeds, urad dal and allow it to roast until the urad dal is browned.", "Add in the curry leaves, onions, green chillies and cook till the onions become soft and translucent.Once the onions have softened, add the sooji and roast for 3 to 4 minutes until you get a lightly roasted aroma.", "Stir in kothamalli paste.", "Gradually add the hot water and keep stirring the kothamalli upma until all the water is absorbed.", "Stir in the lemon juice, cover and cook for a few minutes and turn off the heat.Once done, check the taste and adjust the salt accordingly.Serve the Kothamalli Rava Upma Recipe along with\u00a0South Indian Coconut Chutney\u00a0and\u00a0Banana Date Smoothie Recipe\u00a0for a wholesome breakfast."]'::jsonb, 40, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/jan-5/Kothamali_Upma_South_Indian_Style_Coriander_Savoury_Pudding_Recipe-0918.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/971.Kothamali_Upma_South_Indian_Style_Coriander_Savoury_Pudding_Recipe-0918.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Cauliflower Kurma Recipe', 'kerala-style-cauliflower-kurma-recipe', 'Kurma in Kerala is a typical curry made with different vegetables, yellowish in colour with slightly mashed veggies and a vibrant flavour of coconut milk. Cauliflower Kurma is one such kind of curry that is teemed up with small chopped carrots and green peas and is particularly served with Idiyappam or Rice.', '["1 cup Cauliflower (gobi) , florets", "1/2 cup Carrots (Gajjar) , diced", "2 to 3 tablespoons Green peas (Matar) , fresh or frozen", "1 Onion , finely chopped", "2 tablespoons Ginger Garlic Paste", "2 Green Chillies , slit", "1 Tomato , pureed", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "2 teaspoons Coriander Powder (Dhania)", "1/2 teaspoon Cumin powder (Jeera)", "1 inch Cinnamon Stick (Dalchini)", "2 sprig Curry leaves", "1 cup Coconut milk , thin", "1/2 cup Coconut milk , thick", "Salt , as required", "4 to 5 Cashew nuts , broken", "Oil , as required", "2 tablespoons Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['tomato', 'coconut milk', 'cumin powder (jeera)', 'salt', 'cashew nuts', 'coriander (dhania) leaves', 'green peas (matar)', 'red chilli powder', 'carrot', 'ginger garlic paste', 'curry leaves', 'onion', 'cinnamon stick (dalchini)', 'coriander powder', 'turmeric powder', 'green chillies', 'cauliflower (gobi) florets', 'sunflower oil']::text[], '["To begin making the Kerala Style Cauliflower Kurma recipe, firstly heat sufficient water in a saucepan and add chopped vegetables and boil them.Drain water and collect the vegetables in a mixing bowl. (Do not over cook the veggies)Heat some oil in a heavy bottomed pan and add cinnamon stick and curry leaves.Now add finely chopped onion and saute till they turn translucent.Add ginger garlic paste, green chilies and fry till golden.Now add pureed tomato along with red chilli powder, turmeric powder, cumin powder and coriander powder and fry till the oil starts leaving the sides.Pour in the thin coconut milk, cooked veggies and adjust salt.", "Cook for 5 to 6 minutes on low flame.Once the curry is done, add thick coconut milk, some chopped cashews and turn off the gas.Garnish with fresh chopped coriander and some grated coconut.Serve Kerala Style Cauliflower Kurma with steamed rice and Elai Vadam for a comfort meal.", "Cauliflower Kurma also goes well with\u00a0Whole Wheat Lachha Parathas."]'::jsonb, 50, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shaheen_Ali/KERALA_STYLE_CAULIFLOWER_KURMA.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/972.KERALA_STYLE_CAULIFLOWER_KURMA.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Punjabi Toor Dal Tadka Recipe Using Preethi Electric Pressure Cooker', 'punjabi-toor-dal-tadka-recipe-using-preethi-electric-pressure-cooker', 'Punjabi Toor Dal Tadka and rice is the ultimate comfort food and it is made with basic ingredients found in every Indian home. Dal tadka is found on most restaurant menus and every Indian loves a home cooked dal. Punjabi Toor Dal Tadka Recipe  is a very nutritious high protein lentil dish that is simple to prepare.', '["1 cup Arhar dal (Split Toor Dal) , washed and soaked for 15 minutes", "1 tablespoon Ghee", "1 Onion , finely chopped", "1 inch Ginger , finely chopped", "6 cloves Garlic , finely chopped", "2 Green Chillies , slit", "1 Tomato , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "Salt , to taste", "1 tablespoon Lemon juice", "Coriander (Dhania) Leaves , a small bunch, finely chopped", "Ingredients for tadka", "1 tablespoon Ghee", "1/2 teaspoon Cumin seeds (Jeera)", "1 inch Cinnamon Stick (Dalchini)", "4 cloves Garlic , thinly sliced", "1/4 teaspoon Red Chilli powder"]'::jsonb, ARRAY['arhar dal', 'split toor dal', 'ghee', 'onion', 'ginger', 's garlic', 'reen chillies', 'tomato', 'turmeric powder', 'haldi', 'red chilli powder', 'coriander powder', 'dhania', 'garam masala powder', 'salt', 'lemon juice', 'coriander', 'ingredients for tadka', 'cumin seeds', 'jeera', 'cinnamon stick', 'dalchini']::text[], '["To begin making the Punjabi Toor Dal Tadka Recipe,press the menu option of the electric pressure cooker and keep pressing the plus button till you reach P-15 which is the saute mode.", "Allow the pan to preheat for about 4 minutes.", "Once the pan is heated, add the ghee, onions, ginger, garlic, green chillies and saute until the onions are soft and slightly golden in color.", "Once done add the tomatoes, turmeric powder, red chilli powder, coriander powder, garam masala powder and salt to taste.", "Saute until the tomatoes are soft and mushy.After the tomatoes are soft add the toor dal along with two cups of water.", "Stir well to combine and cover the pressure cooker.", "Change the nozzle to the pressure mode.", "Now change the menu option to Dal Mode.", "To do this press the keep warm option and then the Menu.", "Press plus button till you reach P-4 the Dal mode.Once done the electric cooker will go into the \"\u00d6H\"mode indicating that the cooking time is completed.", "Allow the pressure to release naturally.", "Wait until the red nozzle goes down and then open the pressure cooker.", "Stir in coriander leaves and squeeze juice from one lemon.", "Keep aside."]'::jsonb, 40, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Articles/Punjabi_Toor_Dal_Tadka_Recipe_Video_Tuvar_dal_recipe_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/973.Punjabi_Toor_Dal_Tadka_Recipe_Video_Tuvar_dal_recipe_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thakkali Sadam Recipe - Spicy Tomato Rice', 'thakkali-sadam-recipe-spicy-tomato-rice', 'Tomato Rice popularly called as Thakkali Sadam in South India is a very quick to make rice dish that is packed with flavours from tomatoes, cardamom, and the sambar powder.', '["1 cup Cooked rice", "10 Pearl onions (Sambar Onions) , finely chopped", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "3 Tomatoes , finely chopped", "2 Carrots , grated (optional)", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves , finely chopped", "1 teaspoon Sambar Powder", "1 teaspoon Cardamom Powder (Elaichi)", "1/2 teaspoon Turmeric powder (Haldi)", "6 sprig Mint Leaves (Pudina)", "2 tablespoons Sesame (Gingelly) Oil", "Salt , to taste", "1 tablespoon Ghee"]'::jsonb, ARRAY['cooked rice', 'pearl onions', 'sambar onions', 'ginger', 's garlic', 'tomatoes', 'carrots', 'cumin seeds', 'jeera', 'mustard seeds', 'rai/ kadugu', 'curry leaves', 'sambar powder', 'cardamom powder', 'elaichi', 'turmeric powder', 'haldi', 'mint leaves', 'pudina', 's sesame', 'gingelly', 'salt', 'ghee']::text[], '["To begin making the Thakkali Sadam Recipe - Spicy Tomato Rice, get all the ingredients ready.", "Make sure you have cooked rice ready.Heat oil\u00a0in a heavy bottomed pan; add cumin seeds and mustard seeds; allow it to crackle.", "Then add onions, ginger and garlic and saut\u00e9 until the onions are tender and golden.Add chopped tomatoes and grated carrots; saut\u00e9 until the tomatoes and carrots are tender and the moisture has evaporated.Continue to cook until the mixture looks like a semi-thick\u00a0paste.", "Stir in the chopped curry leaves at this point.Next add in the sambar powder, turmeric powder, cardamom powder, salt and mix well.Add mint leaves and saut\u00e9 for a few more minutes.", "Gradually stir in the cooked rice to the tomato mixture and fold the thakkali sadam gently so that all ingredients are well combined.Finally add a tablespoon of ghee or sesame oil and stir it into the thakkali sadam and serve hot.Serve\u00a0Thakkali Sadam recipe / tomato rice along with\u00a0Boondi Raita\u00a0and\u00a0Kachumber Salad\u00a0for a weekday lunch or dinner."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Tomato_Rice_South_Indian_Thakkali_Sadam_Recipe_Vegetarian-1-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/974.Tomato_Rice_South_Indian_Thakkali_Sadam_Recipe_Vegetarian-1-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rajasthani Dal Bati Churma Recipe | Dhaba Style recipe', 'rajasthani-dal-bati-churma-recipe-dhaba-style-recipe', 'Rajasthani Dal Bati Churma Recipe is a very traditional recipe from Rajasthan and one if the favorites at home. The Baatis are made from whole wheat flour, sooji and ghee with the addition of ajwain that adds to the delicious flavor of the baati.', '["Ingredients for Bati and Churma", "2 cups Whole Wheat Flour , (or a combination of flours)", "1 cup Sooji (Semolina/ Rava)", "1/2 cup Ghee", "1 teaspoon Ajwain (Carom seeds)", "1 teaspoon Baking powder", "Salt , to taste", "1/4 cup Jaggery , for churma", "Ingredients for Dal", "1/4 cup Green Moong Dal (Split)", "1/4 cup Black Urad Dal (Split)", "1/4 cup Chana dal (Bengal Gram Dal)", "1 Onion , finely chopped", "1 inch Ginger , finely chopped", "1 Green Chilli , slit", "3 clove Garlic , finely chopped", "1 Tomato , finely chopped", "1 Bay leaf (tej patta)", "1 inch Cinnamon Stick (Dalchini)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "5 sprig Coriander (Dhania) Leaves , chopped", "Ingredients for Tadka", "1 teaspoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies , halved"]'::jsonb, ARRAY['tomato', 'baking powder', 'ajwain (carom seeds)', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'chana dal (bengal gram dal)', 'salt', 'green chilli', 'cloves garlic', 'dry red chillies', 'green moong dal (split)', 'garam masala powder', 'wheat flour (or combination flours)', 'sooji (semolina rava)', 'ginger', 'ghee', 'jaggery churma', 'bay leaf (tej patta)', 'black urad dal (split)', 'coriander (dhania) leaves', 'cinnamon stick (dalchini)']::text[], '["To begin making the Dal Baati Churma Recipe, we will first making the bati.Combine all the ingredients for the Bati together, except the jaggery until well combined.", "Add water to combine it well and make a smooth and yet stiff dough.", "Leave the bati dough aside for 20 minutes so it rests and becomes fluffy with the baking powder that we added.", "Once the baat dough is well rested, knead again for a few minutes.", "Divide the dough in large lemon size portions (about 12 to 15 of them).", "Preheat the oven to 180 C and bake the bati in the oven for about 20 to 30 minutes until browned on both sides.Make sure to keep turning the baatis around, until it is browned from all sides.", "The batis will tend to crack from the top while it is baking and that''s completely natural.", "Once the batis are golden brown in color from all sides, remove them from the oven.For the churma, I usually make it from the same baked bati balls.", "Take 3 to 4 of them, crush them and combine them with jaggery in a mixer to make a coarse powder.", "And that''s it, churma is ready.", "The salt from the batis does not overwhelm the taste and tastes perfectly fine.The next step is to make the dal for the dal bati.", "To make the dal, add all the ingredients into the pressure cooker, except the ingredients for the tadkaAdd 2-1-/2 cups of water and pressure-cook the dal for two to three whistles.", "After two whistles, turn the heat to low and simmer for 10 minutes and turn off the heat.Once the pressure is released completely, open the cooker and your dal is ready.", "Check the salt and spices and adjust to suit your taste.", "Transfer the dal to a serving bowl.The next step is to make the tadka.", "Heat ghee in a small pan, add the cumin seeds and red chilies.", "Allow them to roast and crackle.", "Once done, turn off the heat and pour the seasoning over the dal and serve with the hot baatis.Serving baatis are usually done in individual portions and bowls.In a small serving bowl, add 2 batis, lightly crush them, drizzle some ghee over the baked baatis.", "Pour the dal over the baked baatis and serve.", "I personally like to add the churma over the baatis as well to give it a sweet touch and a delicious taste as well.Serve the\u00a0Rajasthani Dal Bati Churma for a wholesome weekend lunch or even for parties with friends."]'::jsonb, 100, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Rajasthani_Dal_Bati_Churma_Recipe-5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/975.Rajasthani_Dal_Bati_Churma_Recipe-5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gehun Ka Halwa Recipe | Atte Ka Halwa | Kada Prasad Recipe', 'gehun-ka-halwa-recipe-atte-ka-halwa-kada-prasad-recipe', 'Gehun ka Halwa Recipe also known as Sheera | Atte Ka Halwa | Kada Prasad is a delicious whole wheat flour pudding flavored Indian spices and enhanced with nuts. The halwa is made as an offering during certain festivals and special occasions of religious significance. This recipe was taught to me by a Punjabi friend who makes it similar to the kind that is typically served in Gurdwaras known as Kada Prasad', '["1 cup Whole Wheat Flour", "1 cup Sugar", "1 cup Ghee , + 1 tablespoon", "3 cups Water", "2 teaspoons Cardamom Powder (Elaichi) , freshly ground", "1/4 cup Cashew nuts , halved"]'::jsonb, ARRAY['whole wheat flour', 'sugar', 'ghee', 's water', 's cardamom powder', 'elaichi', 'cashew nuts']::text[], '["To begin making the Gehun Ka Halwa | Atte Ka Halwa | Kada Prasad Recipe, heat the water and sugar in a saucepan, stirring continuously until the sugar dissolves.", "Turn the heat to low and continue to heat the water until you get wheat flour mixture ready by following the steps that follow.Heat a heavy bottomed pan\u00a0on medium heat; melt the one cup of ghee and stir in the wheat flour and roast the mixture on medium heat.", "Continue to roast until the mixture begins to release a roasted aroma and changes color to a roasted brown; the process will take about 5 to 8 minutes, Ensure you roast the wheat flour in medium heat to avoid the flour from burning.Keep stirring continuously while it is roasting.", "When the mixture will begin to resemble like coarse crumbles, turn the heat to low and stir the cardamom powder to the wheat flour mixture.Slowly start stirring in the prepared hot sugar water to the atte ka mixture.", "The mixture will start splitting and curdling.", "Continue stirring until the atte ka halwa / kada prasad thickens, yet feels coarse and crumbly and not like a blob of dough.Stir continuously for 10-15 minutes on medium heat after the atte ka halwa thickens.", "You will notice the atte ka halwa comes away from the sides of the pan.Turn the heat off and let the gehun ka halwa/ atte ka halwa rest covered for about 5 minutes.In another small tadka pan; heat the 1 tablespoon of ghee on medium heat; add the cashew nuts and roast them until the cashew nuts turn golden brown.", "Turn off heat and stir this into the gehun ka halwa/ atte ka halwa.", "Serve the Gehun ka Halwa/ Atte Ka Halwa/ Kada Prasad during festivals, special occasions, after a delicious weekend lunch or at a party as a dessert with friends and family."]'::jsonb, 55, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Archana_Doshi/Atta_Ka_Halwa_Gehun_Ka_Sheera_Recipe_Wheat_Flour_Halwa_Pudding-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/976.Atta_Ka_Halwa_Gehun_Ka_Sheera_Recipe_Wheat_Flour_Halwa_Pudding-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Coriander Tamarind Millet Rice Recipe', 'coriander-tamarind-millet-rice-recipe', 'Tamarind Rice is a common feature in a South Indian kitchen, but mostly loved everywhere, here is a little twist to tamarind rice with lots of coriander and goodness of millets, perfect for a working day. This is a low GI recipe suitable for diabetics. You can make it for your weekday dinners when you want to eat some healthy yet tasty.', '["1/2 cup Foxtail Millet , little", "2 Green Chillies , adjustable", "1 Dry Red Chilli", "8 Curry leaves", "3 cloves Garlic", "6 sprig Coriander (Dhania) Leaves , chopped (leave bit for garnishing)", "1/4 teaspoon Cumin powder (Jeera)", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon White Urad Dal (Split)", "1/2 teaspoon Chana dal (Bengal Gram Dal)", "2 tablespoons Raw Peanuts (Moongphali)", "Asafoetida (hing) , a pinch", "1/4 teaspoon Turmeric powder (Haldi)", "Tamarind , extracted (1/2 a lemon size)", "Oil , as needed", "Salt , to taste"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'chana dal (bengal gram dal)', 'mustard seeds', 'foxtail millet', 'asafoetida (hing)', 'coriander (dhania) leaves (leave bit )', 'cloves garlic', 'tamarind ( lemon size)', 'curry leaves', 'dry red chilli', 'white urad dal (split)', 'peanuts (moongphali)', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["In a vessel add 1/2 cup millets with one cup of water and bring this to a boil, turn the heat to simmer and cook the millets covered with a steam vent cracked open for 8-10 minutes or until the water evaporates. let it sit for 2 minutes and tranfer this to another bowl and let it cool completely.In a mixie jar add coriander, green chillies, cumin powder, garlic, tamarind extract and salt ,grind to a smooth paste.", "Set aside.In a pan heat some oil, crackle the mustard seeds, followed by urad dal, channa dal, peanuts, roast them on low heat to golden .Now add the asafoetida, turmeric, red chilli and curry leaves.Add the ground paste and saute until the raw smell disappears approximately 4 minutes.", "Add a tiny splash of water if the mixture becomes very dry.Finally add the cooked millets and gently mix so that the mixture is uniformly applied.", "Adjust the salt if required.Top with chopped coriander and serve.Serve Coriander Tamarind Millet Rice along with\u00a0Tadka Raita,\u00a0Tomato Onion Cucumber Raita\u00a0or any other raita of your choice."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/gauravi/CorianderTamarind_Millet_rice.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/977.CorianderTamarind_Millet_rice.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Muttai Paniyaram Recipe | Egg Paniyaram Recipe', 'chettinad-muttai-paniyaram-recipe-egg-paniyaram-recipe', 'Chettinad Muttai Paniyaram Recipe is a traditional dish famous in the region of Tamil Nadu. It is a variation made  from a rice batter filled in with High protein egg and some extra spice to kick start your Breakfast in a healthy way. The Paniyaram Is usually made in a Paniyaram pan by using less of oil and shallow frying till it becomes crispy from outside, soft and gooey inside.', '["3 cups Idli Dosa Batter", "3 Whole Eggs", "2 Onions , finely chopped", "4 Green Chilli , chopped", "2 sprig Curry leaves , finely chopped", "6 sprig Mint Leaves (Pudina) , finely chopped", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Whole Black Pepper Corns , coarsely pounded", "1/2 cup Fresh coconut , grated", "Salt , to taste", "Sesame (Gingelly) Oil , for cooking"]'::jsonb, ARRAY['s idli dosa batter', 'whole eggs', 'onions', 'reen chilli', 'curry leaves', 'mint leaves', 'pudina', 'mustard seeds', 'rai/ kadugu', 'turmeric powder', 'haldi', 'whole black pepper corns', 'fresh coconut', 'salt', 'sesame', 'gingelly']::text[], '["To begin making\u00a0Chettinad Muttai Paniyaram Recipe prep all the ingredients first.", "Heat a Kadai\u00a0with some oil, add mustard seeds and asafoetida and let it splutter for few seconds.Then add curry leaves, onions and green chillies.", "Saute for few minutes till the onions become translucent and soft and turn off the heat.", "Stir in the chopped curry leaves at this stage and give it a stir.In a small mixing bowl, break in the eggs and beat it till it fluffs up little.", "Pour egg into the dosa batter and also the sauteed onion mixture.Add in chopped mint leaves, turmeric powder, black peppercorns and salt to taste.", "Stir well to combine and check the salt and adjust according.Whisk the muttai paniyaram batter well until the egg and onion mixture is well combined into the dosa batter.Heat the Paniyaram\u00a0pan on a medium heat, add a teaspoon of oil into each cavities.", "Spoon in the muttai paniyaram batter into of the each cavities.Cover the paniyaram pan and let allow the muttai paniyaram to steam cook for about 3 to 4. minutes minutes on one side and flip over to cook on the other side.You can add oil if required while cooking and flipping it over to make the muttai paniyaram crisp.", "Once done, the muttai paniyaram from the pan and serve hot.Serve the Chettinad Muttai Paniyaram along Coconut Chutney and filter coffee for a wholesome snack."]'::jsonb, 40, 'Tamil Nadu', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/oct-19/Chettinad_Egg_Paniyaram_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/978.Chettinad_Egg_Paniyaram_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Whole Wheat Flour Puttu Recipe', 'whole-wheat-flour-puttu-recipe', 'Vivatta Whole Wheat Flour Puttu Recipe is a twist to Puttu recipe which is unique to Kerala. It is one of the staple dish prepared for breakfast in many households on day to day basis. Being steamed and prepared without oil puts the ''puttu'' on the list of healthy, non-fat dishes. There are many variations to this dish; some prepare it with Ragi that makes it very nutritious, diabetic friendly dish. Usually ''puttu'' is prepared with rice powder.  This 5 ingredient wheat flour puttu turns out super tasty and can be prepared in less than 30 minutes. Now doesn’t that sound interesting enough to try this recipe? Go ahead give it a try.', '["3/4 cup Whole Wheat Flour", "2 tablespoons Basmati rice , boiled, soaked for 2 hours", "1/4 cup Fresh coconut , grated", "Salt , to taste", "1 tablespoon Sugar"]'::jsonb, ARRAY['basmati rice', 'wheat flour', 'salt', 'coconut', 'sugar']::text[], '["To begin making Whole Wheat Flour Puttu Recipe, dry roast atta\u00a0on low flame until the flour releases a pleasant aroma.", "Take off the\u00a0heat before the flour starts browning.Drain all the water from steamed rice and grind it in a mixer grinder into a crumby mixture.", "Then add roasted whole wheat flour and pulse for less than half a minute.", "Do not over blend it.", "The end result of this grinding should be a\u00a0crumbly well-mixed mixture of soaked rice and whole wheat flour.Put the crumbly flour to a wide mixing bowl.", "Add little salt, sugar, and a tablespoon of grated coconut to the flour mix.Boil enough water in a pressure cooker (without the weight).", "In a puttu maker, add a thin layer of freshly grated coconut, top it with wheat-rice flour mix.", "If you are using the long cylindrical puttu maker, add 2 to 3 layers of grated coconut and flour mix.", "Cover the puttu maker with lid.Place the puttu maker on top of the cooker (sits on the hole where you put the weight).", "Steam for about 5 to 10 minutes until cooked.", "Once cooked, carefully slide Whole Wheat Flour Puttu from the puttu maker and serve hot.Serve Whole Wheat Flour Puttu with\u00a0Kerala Kadala Curry Recipe (Spicy Chickpeas in Coconut Curry)\u00a0or bananas and a dollop of ghee\u00a0for a yummy breakfast."]'::jsonb, 35, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Vivatta_Whole_Wheat_Flour_Puttu.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/979.Vivatta_Whole_Wheat_Flour_Puttu.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dahi Ma Bheeda Recipe (Dahi Bhindi - Parsi Style Okras Cooked In Yogurt Recipe)', 'dahi-ma-bheeda-recipe-dahi-bhindi-parsi-style-okras-cooked-in-yogurt-recipe', 'Dahi Ma Bheeda Recipe (Dahi Bhindi - Parsi Style Okras Cooked In Yogurt Recipe)  is a simple yogurt-based curry made without incorporating gram flour or besan to it as compared to a typical "kadhi". The consistency of the gravy is thus very thin. The shallow fried okras are then dipped into the curd and cooked in order to bring out the best flavor to the curry.', '["500 grams Bhindi (Lady Finger/Okra) , half inch slice", "2 inch Ginger", "3 cloves Garlic", "1 teaspoon Turmeric powder (Haldi)", "2 teaspoon Red Chilli powder", "3 teaspoon Cumin powder (Jeera)", "3/4 Curd (Dahi / Yogurt) , beaten till smooth", "Salt , to taste", "Oil , for cooking"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'ginger', 'curd till smooth', 'bhindi (lady fingerokra) slice', 'red chilli powder', 'cloves garlic', 'turmeric powder', 'sunflower oil']::text[], '["We begin making the Dahi Ma Bheeda Recipe (Dahi Bhindi - Parsi Style Okras Cooked In Yogurt Recipe) by washing the okra and wipe them thoroughly, cut the okra into half-inch slice and sprinkle some salt and keep it aside.Heat oil in a non-stick pan, add the cut okras and shallow fry them till it is crispy.", "Once done remove them.In the same pan add the ginger, garlic and saut\u00e9 for few minutes.", "Then add the spices and fry till the raw smell of the spice goes away.Lower the heat and gradually add the beaten curd to the pan, mix well.", "Later add the crispy okras and simmer it for 2 minutes.Serve the hot the Dahi Ma Bheeda Recipe (Dahi Bhindi - Parsi Style Okras Cooked In Yogurt Recipe) with steam rice or Khichdi\u00a0Kadhi and Batata Nu Shaak ( The Classic Comfort Food of India)."]'::jsonb, 40, 'Parsi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/oct-14/Dahi_Ma_Bheeda_Recipe_Dahi_Bhindi_Parsi_Style_Okras_Cooked_In_Yogurt-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/980.Dahi_Ma_Bheeda_Recipe_Dahi_Bhindi_Parsi_Style_Okras_Cooked_In_Yogurt-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Murungai Keerai Kollu Kuzhambu - Drumstick Leaves Horse Gram Curry', 'murungai-keerai-kollu-kuzhambu-drumstick-leaves-horse-gram-curry', 'The Murungai Keerai Kollu Kuzhambu Recipe is a wholesome tangy curry that is made from horse gram dal and drumstick leaves - both of which being super foods for a healthy diet. Serve this curry along with a bowl of hot rice for a comforting weeknight dinner.', '["1 cup Horse Gram Dal (Kollu/ Kulith) , soaked for 3 to 4 hours", "2 cups Drumstick Leaves (Moringa/Murungai Keerai) , roughly chopped", "1 cups Tamarind Water", "10 Pearl onions (Sambar Onions) , peeled and halved", "2 Tomatoes , roughly chopped", "1 teaspoon Sambar Powder", "1 teaspoon Whole Black Peppercorns , coarsely pounded", "Salt , to taste", "1 teaspoon Jaggery", "Ingredients for seasoning", "1 teaspoon Sesame (Gingelly) Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "2 sprig Curry leaves , roughly torn"]'::jsonb, ARRAY['horse gram dal', 'kollu/ kulith', 's drumstick leaves', 'moringa/murungai keerai', 's tamarind water', 'pearl onions', 'sambar onions', 'tomatoes', 'sambar powder', 'whole black peppercorns', 'salt', 'jaggery', 'ingredients for seasoning', 'sesame', 'gingelly', 'mustard seeds', 'rai/ kadugu', 'methi seeds', 'fenugreek seeds', 'curry leaves']::text[], '["To begin making the Murungai Keerai Kollu Kuzhambu Recipe, first get all the ingredients prepped and ready.", "Make the tamarind water according to the recipe - How To Make Tamarind Water.Soak the horse gram for a couple of hours.", "Soaking helps it to cook faster.Pressure cook the drumstick leaves, along with salt and 2 tablespoons of water for just 1 whistle.", "Release the pressure immediately, to prevent overcooking the greens and also to retain its fresh green colour.Once the ingredients are prepped, we will cook them all in the pressure cooker.", "Into the pressure cooker, add a teaspoon of oil - saute the onions until lightly tender.", "Once the onions are tender, add the horse gram, tomatoes, tamarind water, salt, jaggery, sambar powder, pepper and salt.", "Stir well to combine and cook for 6 to 8 whistles.", "After 8 whistles, turn of the heat and allow the pressure to release naturally.", "Once released, stir in the cooked\u00a0Murungai Keerai into the Kollu Kuzhambu.Give the Murungai Keerai Kollu Kuzhambu a brisk boil and turn off the heat.The Kuzhambu will be a little runny, if you like a thicker, then you can simmer the Kuzhambu on low heat until it thickens.Check the salt and spices and adjust to suit your taste.The final step is the seasoning.", "Heat a little oil in a small tadka pan, add the mustard seeds, fenugreek seeds and allow it to crackle.", "Once it crackles add the curry leaves and stir.", "Turn off the heat and add the seasoning to the Murungai Keerai Kollu Kuzhambu and serve.The\u00a0Murungai Keerai Kollu Kuzhambu Recipe\u00a0is a perfect dish to go along with some steaming hot rice,\u00a0Cabbage Poriyal\u00a0and Appalam.", "Serve it for lunch or dinner and you will surely enjoy this spicy curry."]'::jsonb, 40, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Murangai_Keerai_Kollu_Kuzhambu_Recipe_Drumstick_leaves_Horse_Gram_Curry-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/981.Murangai_Keerai_Kollu_Kuzhambu_Recipe_Drumstick_leaves_Horse_Gram_Curry-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rava Kesari Bhath - South Indian Sooji Halwa Recipe', 'rava-kesari-bhath-south-indian-sooji-halwa-recipe', 'Rava Kesari Bhath/Sooji Halwa Recipe is a pudding made from semolina, flavored with saffron and other spices topped with nuts. In most parts of Southern India, Kesari is served as part of an offering to God during festivities.', '["1 cup Sooji (Semolina/ Rava)", "1/2 cup Ghee", "3/4 cup Sugar", "1 cup Milk", "2 cups Water", "1 teaspoon Cardamom Powder (Elaichi)", "6 Saffron strands , strands", "1 tablespoon Ghee", "10 Cashew nuts , halved", "2 tablespoons Sultana Raisins"]'::jsonb, ARRAY['sooji', 'semolina/ rava', 'ghee', 'sugar', 'milk', 's water', 'cardamom powder', 'elaichi', 'saffron strands', 'cashew nuts', 's sultana raisins']::text[], '["To begin making the Rava Kesari Bhath (Sooji Halwa) Recipe, we will first begin by boiling the water, milk, sugar, saffron and cardamom in a\u00a0sauce pan and stirring until the sugar melts.", "Keep the liquid mixture aside on simmer in another stove.In wide heavy bottomed pan heat ghee on\u00a0medium heat; add the semolina (rava/sooji) and roast until the semolina gives out a roasted aroma and also turns light golden color.", "Take\u00a0care\u00a0not to let it over brown.Gradually begin to stir in the hot liquid mixture you prepared earlier.", "Take care to keep the heat in medium as the mixture will\u00a0splutter\u00a0around as you pour the hot liquid to the semolina.Keep stirring the mixture and the semolina will continue to thicken.", "Once it has thickened it will begin to leave the sides of the pan.", "Cover the pan and simmer the Rava Kesari Bhath for a couple of minutes stirring occasionally.You will notice the semolina is cooked and when you stir the whole Rava Kesari Bhath comes away from the sides of the pan.", "At this stage, turn off the heat, cover the pan with a lid and let the Rava Kesari Bhath to rest\u00a0for a few minutes.In another small pan; heat the ghee on medium heat; add the cashew nuts and raisins and roast them until the cashew nuts turn golden brown.Turn off heat and stir this to the Rava Kesari BhathServe the Rava Kesari\u00a0Bhath along with\u00a0Vegetable Rava Upma\u00a0for breakfast or even savor this as a sweet after a delicious meal."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Kesari_Bath_Recipe_Video_South_Indian_Sooji_Halwa_Rava_Kesari_5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/982.Kesari_Bath_Recipe_Video_South_Indian_Sooji_Halwa_Rava_Kesari_5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Naga Style Chicken With Bamboo Shoot Recipe', 'naga-style-chicken-with-bamboo-shoot-recipe', 'Chicken with Bamboo shoot recipe is an another Nagaland cuisine delicacy.  This recipe doesn''t need any oil, and the spiciness of green chilies and taste of Bamboo shoots makes it a unique recipe.', '["1 kg Chicken", "2 Tomatoes , crushed in pestle & mortar", "5 cloves Garlic , crushed", "2 inch Ginger , grated", "7/8 Green Chillies , crushed", "1/2 cup Bamboo shoots , sliced", "1/2 cup Cabbage (Patta Gobi/ Muttaikose) , sliced", "Spring Onion (Bulb & Greens) , few, chopped to garnish", "Salt , to taste"]'::jsonb, ARRAY['salt', 'ginger', 'tomato pestle mortar', 'cloves garlic', 'spring onion (bulb greens)', 'chicken', 'bamboo shoots', 'green chillies', 'cabbage (patta gobi muttaikose)']::text[], '["To prepare Naga Style Chicken With Bamboo Shoot Recipe, wash chicken pieces thoroughly and drain all the excess water.Heat a wok on medium flame, add the ginger, garlic, green chillies and saute for about 30 seconds.", "To this add the cabbage, bamboo shoots and sprinkle some salt.", "Cover and cook for about 2-3 minutes.", "Once the cabbage has wilted down add the chicken and the tomatoes.Mix it well, sprinkle some water and cook covered, on a medium flame until chicken is tender and well cooked.", "This will take about 20-25 minutes.", "Garnish with spring onions and some bamboo shoot slices, optionally.Serve Naga Style Chicken With Bamboo Shoot Recipe with hot steamed rice\u00a0and\u00a0Hmarcha Rawt\u00a0(chutney)."]'::jsonb, 40, 'North East India', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/usashis-gmail.com/Naga_style_Chicken_with_Bamboo_shoot_recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/983.Naga_style_Chicken_with_Bamboo_shoot_recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hariyali Matar Recipe', 'hariyali-matar-recipe', 'Hariyali Matar Recipe is a North Indian side dish which is made with fresh green peas in flavourful coriander base. Matar dishes are usually crowd pleaser and you will love this variation too. It is one of the nutritious vegetables available during the winter season.', '["2 cups Green peas (Matar) , steamed", "1/2 cup Paneer (Homemade Cottage Cheese) , cut into small cubes", "1 teaspoon Cumin seeds (Jeera)", "1 pinch Asafoetida (hing)", "1 tablespoon Oil", "Salt , to taste", "Ingredients for the green masala", "2 cups Coriander (Dhania) Leaves , tighly packed", "2 Green Chillies", "5 cloves Garlic", "1 inch Ginger", "1 tablespoon Lemon juice"]'::jsonb, ARRAY['salt', 'ginger', 'asafoetida (hing)', 'paneer', 'green peas (matar)', 'cloves garlic', 'cumin seeds (jeera)', 'lemon', 'coriander (dhania) leaves tighly packed', 'green chillies', 'sunflower oil']::text[], '["To begin making\u00a0the Hariyali Matar Recipe, peal the green peas, wash and steam it using a steamer and keep aside.Make a fine paste of the ingredients listed in the green masala, coriander leaves, green chillies, garlic, ginger and lemon juice, using a mixer grinder adding very little water and keep aside.Heat oil in a wide pan, add the asafoetida, cumin seeds and let the cumin seeds splutter.Add the ground green masala and saute for 2 minutes until the masala is well cooked and comes together.Add the steamed green peas, season with salt, add 1 cup water, give it a stir and let it simmer for 2 to 3 minutes.Once the gravy has thickened, add the paneer cubes and mix well.Let the mixture simmer for another 2 minutes and switch off the flame.", "Remove into a serving bowl.Serve the Hariyali Matar Recipe along with\u00a0Tawa Parathas\u00a0and\u00a0Gajar Shimla Mirch Sambharo\u00a0for the weeknight dinner or pack away for your lunch box."]'::jsonb, 20, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Hariyali_Matar_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/984.Hariyali_Matar_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Punjabi Rajma Masala Recipe - Rajma Chawal/Spiced Red Kidney Beans Curry', 'punjabi-rajma-masala-recipe-rajma-chawal-spiced-red-kidney-beans-curry', 'The Punjabi Rajma Masala also known as the North Indian Red Kidney Beans Curry is a very famous recipe from the North India. Rajma Masala popularly known as Rajma Chawal is considered as a comfort food in a Punjabi home. This makes a one dish meal, when the Rajma Masala is served along with steamed hot rice where the wonderful flavours of the rajma comes out when chewed along with rice.', '["2 cups Rajma (Large Kidney Beans) , soaked for 8 hours", "1 teaspoon Oil", "1 Onion , roughly chopped", "1 inch Ginger , finely chopped", "1 Tomato , finely chopped or pureed", "1/4 teaspoon Turmeric powder (Haldi)", "2 teaspoons Cumin powder (Jeera)", "1 teaspoon Garam masala powder", "1 Bay leaf (tej patta)", "1 inch Cinnamon Stick (Dalchini) , broken", "8 sprig Coriander (Dhania) Leaves , chopped", "Salt , to taste"]'::jsonb, ARRAY['s rajma', 'large kidney beans', 'oil', 'onion', 'ginger', 'tomato', 'turmeric powder', 'haldi', 's cumin powder', 'jeera', 'garam masala powder', 'bay leaf', 'tej patta', 'cinnamon stick', 'dalchini', 'coriander', 'dhania', 'salt']::text[], '["To begin making the Rajma Masala Recipe, we will first soak the rajma\u00a0immersed completely in water for about 8 to 10 hours.Heat a teaspoon of oil on medium heat in the pressure cooker pan; add the onion, and ginger and saute for 3 to 4 minutes until the onions soften turn light golden colour.Stir in the tomatoes, bay leaf, cinnamon stick, turmeric powder, cumin powder, garam masala powder and salt to taste.Saute for another couple of minutes until the tomatoes become soft and mushy.", "Once soft, add the soaked rajma along with its water.", "Add any additional water if required.", "There should enough water such that the water level is at least 2 inches above the rajma.Cover the pressure cooker, place the weight on and cook on medium heat for about 40 minutes.Once done, turn off the heat and allow the pressure cooker to rest and release its pressure naturally.", "The rajma\u00a0will continue to cook in the pressure cooker as long as there is pressure inside.Once the pressure has released, open the cooker.", "The rajma should be now cooked completely.", "If you press the rajma between your fingers it will get mashed easily.If you find the rajma is still firm, you need to cook it for a little longer.", "This happens when your rajma bean has aged and hence takes a longer time to cook.Once the Rajma Masala is cooked, check the salt and spice levels and adjust to suit your taste.", "Stir in the chopped coriander leaves and serve hot.Serve Rajma Masala Recipe\u00a0for Sunday Lunches, when served along with\u00a0Steamed Rice\u00a0and\u00a0Aloo Parwal Sabzi\u00a0making the meal wholesome and nutritious."]'::jsonb, 105, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Punjabi_Rajma_Masala_Recipe_-_Rajma_Chawal_Spiced_Red_Kidney_Beans_Curry_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/985.Punjabi_Rajma_Masala_Recipe_-_Rajma_Chawal_Spiced_Red_Kidney_Beans_Curry_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chatpate Aloo Recipe With Sesame Seeds', 'chatpate-aloo-recipe-with-sesame-seeds', 'Punjabi cuisine is a mother of many favourite recipes like Punjabi Dal, Aloo Paratha, Lassi and more. Tandoori Potatoes Recipe, this is a simple carb rich food that you will love every time you prepare it for side dish. In this recipe, Chatpate Aloo Recipe With Sesame Seeds, the potatoes are boiled in water, and then they are also fried in oil which enhances the flavour of this recipe.', '["500 grams Baby Potatoes", "1-1/2 tablespoons Sesame seeds (Til seeds)", "Oil , as needed", "Salt , to taste", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Cumin powder (Jeera)", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Garam masala powder", "Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'amchur (dry mango powder)', 'coriander (dhania) leaves', 'red chilli powder', 'baby potatoes', 'coriander powder', 'turmeric powder', 'sesame seeds (til seeds)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making Chatpate Aloo Recipe With Sesame Seeds, take all the baby potatoes in a saucepan with water and boil well till done.You can also choose to pressure cook them for just one whistle in sufficient water and run under cold water for immediate release of pressure.Once the potatoes are cooked al dente, peel them all and put aside.Now, in another small bowl add all the spices -salt, red chili powder, turmeric powder, jeera powder, amchur powder and garam masala powder and mix them well with a spoon, and keep aside.In a kadai, lightly roast sesame seeds and keep them aside.In the same kadai, heat 2-3 tablespoons of vegetable oil into it for frying the boiled baby potatoes.Once the oil is hot enough, add potatoes gently and fry them well.", "You need to cook them till they get a nice light brown color.Once the potatoes are cooked well, keep them aside on a plate and pat with tissue paper to absorb excess oil and let it cool down for 5 minutes.Take the fried potatoes in a bowl again and put the whole masala into the bowl and mix everything thoroughly together, taking care that the potatoes are firm and not mushy.", "Cooking the potatoes help the prepared masala to coat well which enhances the taste .Garnish it with few freshly chopped coriander leaves and Serve it like that.Serve\u00a0Chatpate Aloo Recipe With Sesame Seeds along with\u00a0Punjabi Dal Tadka,\u00a0Butter Naan Recipe\u00a0and end your meal with a\u00a0Refreshing Mint Lassi Recipe."]'::jsonb, 30, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/droolingfoodies-gmail.com/chatpate_aloo_recipe_With_sesame_seeds_edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/986.chatpate_aloo_recipe_With_sesame_seeds_edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kathirikai Sundakkai Vathal Kuzhambu Recipe', 'kathirikai-sundakkai-vathal-kuzhambu-recipe', 'The Kathirikai Sundakkai Vathal Kuzhambu Recipe is a delicious Chettinad style tangy gravy which is simmered along with tamarind, jaggery, homemade spices and along with sundakkai and brinjal.', '["2 tablespoons Sundakkai (Turkey Berries)", "2 tablespoons Sesame (Gingelly) Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "2 sprig Curry leaves", "1/4 teaspoon Asafoetida (hing)", "12 Pearl onions (Sambar Onions) , peeled and quartered", "6 Brinjal (Baingan / Eggplant) , quartered and soaked in salt water", "50 grams Tamarind , soaked in water", "2 tablespoons Sambar Powder , homemade", "1 cup Water", "1 tablespoon Jaggery", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard seeds', 'sundakkai (turkey berries)', 'asafoetida (hing)', 'jaggery', 'sesame (gingelly) oil', 'water', 'curry leaves', 'pearl onion (sambar onion)', 'methi seeds (fenugreek seeds)', 'tamarind', 'sambar powder', 'brinjal (baingan eggsplant) salt water']::text[], '["To begin making\u00a0Kathirikai Sundakkai Vathal Kuzhambu, prep all the ingredients and keep ready.Extract the tamarind water, until you get 2 cups of tamarind water from the soaked tamarind.", "Keep this aside.Heat oil in a pan over medium heat; add the sundakkai and roast until it is dark brown in colour and crisp.", "Once roasted, keep the sundakkai to the side.Preheat oil in a pan over medium heat, add the mustard seeds and fenugreek seeds.", "Allow it to crackle.Add the curry leaves, asafoetida, onion and brinjal (drain the water it was soaked in).", "Saute the onion and brinjal until the onion is roasted and brinjal is cooked and roasted.", "Cover the pan so the brinjal cooks faster.Once done, add the roasted sundakkai, tamarind water, water, homemade sambar powder, jaggery and salt.", "Simmer the\u00a0Kathirikai Sundakkai Vathal Kuzhambu for 15 to 20 minutes until the raw taste from the tamarind goes away and the vathal kuzhambu has thickened.", "Give the Kathirikai Sundakkai Vathal Kuzhambu a stir occasionally so that the gravy does not stick to the bottom.", "Once done, check the taste and adjust the salt and spices accordingly.", "Turn off the heat and transfer the\u00a0Kathirikai Sundakkai Vathal Kuzhambu to a serving bowl and serve hot.Serve this delicious\u00a0Kathirikai Sundakkai Vathal Kuzhambu along with Hot Steamed Rice, Capsicum Masala Poriyal Recipe and Elai Vadam for a delicious Tamilnadu Style lunch."]'::jsonb, 35, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Sundakkai_Kathirikai_Vathal_Kuzhambu_Recipe_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/987.Sundakkai_Kathirikai_Vathal_Kuzhambu_Recipe_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharashtrian Aloo Bhujne Recipe - Potato Stir Fry', 'maharashtrian-aloo-bhujne-recipe-potato-stir-fry', 'Maharashtrian Aloo Bhujne Recipe is a simple Maharashtrian Style Potato Stir Fry. Bhujne is a ''curry'' that is unique to the seafood-loving Pathare Prabhu community.', '["4 Potato (Aloo) , skins removed and sliced into rounds", "2 Onions , cut really small", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Green Chilli , chopped", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Ginger Garlic Paste", "Salt", "2 tablespoons Oil", "2 tablespoons Oil", "1 tablespoon Wheat Germ", "1 tablespoon Chana dal (Bengal Gram Dal)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Whole Black Peppercorns", "5 tablespoons Coriander (Dhania) Seeds", "5 Dry Red Chillies", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Turmeric powder (Haldi)", "1 pinch Asafoetida (hing)"]'::jsonb, ARRAY['potato', 'aloo', 'onions', 'mustard seeds', 'rai/ kadugu', 'reen chilli', 'turmeric powder', 'haldi', 'ginger garlic paste', 'salt', 's oil', 'wheat germ', 'chana dal', 'bengal gram dal', 'methi seeds', 'fenugreek seeds', 'whole black peppercorns', 's coriander', 'dhania', 'dry red chillies', 'cumin seeds', 'jeera', 'asafoetida', 'hing']::text[], '["To begin making the\u00a0Maharashtrian Aloo Bhujne Recipe (Potato Stir Fry), peel the potatoes and cut them into roundels and pressure cook with enough water for one whistle and leave it to rest aside.", "Proceed to make the masala, Dry roast the coriander seeds, wheat, chana dal, cumin seeds, mustard seeds, fenugreek seeds, dry red chillies, hing and turmeric powder in the order that is mentioned.", "Roast all of them together for 5 minutes.", "Cool it down and add in the mixer grinder to make a smooth powder.", "Set it aside.Heat a kadai with oil, add mustard seeds, cumin seeds and allow it splutter.", "Add the chopped onions, ginger garlic paste and saute for 10 minutes until it become translucent.", "Add green chillies, turmeric powder and the ground masala.", "Add little water so that it does not dry up.", "Add your cooked potatoes/aloo and salt.", "Saute well for 2 minutes and add chopped coriander leaves and mix well and serve.", "Serve the\u00a0Maharashtrian Aloo Bhujne\u00a0along with\u00a0Dal Tadka,\u00a0Steamed Rice\u00a0and\u00a0Phulkas\u00a0for an everyday lunch or dinner."]'::jsonb, 40, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/2-may/Maharashtrian_style_potato_stir_fry_recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/988.Maharashtrian_style_potato_stir_fry_recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Konkani Style Batata Song Recipe - Dry Red Chili Potatoes Fry', 'konkani-style-batata-song-recipe-dry-red-chili-potatoes-fry', 'Konkani Style Batata Song Recipe-Dry Red Chili Potatoes Fry is a dry dish made simply with ground dry red chillies and tamarind into a smooth paste and mixed with soft potatoes.', '["4 Potatoes (Aloo) , peeled and cut into medium sized", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "Salt , to taste", "To Grind", "5 Dry Red Chillies", "18 grams Tamarind"]'::jsonb, ARRAY['salt', 'mustard seeds', 'dry red chillies', 'potato (aloo)', 'tamarind']::text[], '["To begin making the Konkani Style Batata Song, roast the dry red chillies in a pan till it gets crip and changes its colour a bit.", "Add it into a mixer along with tamarind, a little water and grind it into a smooth paste.Heat a pan with oil, add mustard seeds and crackle it for 10 seconds.", "Add in the ground red chilli paste and fry for at least 10 minutes.In the meanwhile pressure cook the potatoes with little water and salt to one whistle till it is just cooked.", "Allow the pressure to release by itself and strain the water.Peel the potatoes and let it cool down.", "Cut the potatoes in cubes and keep them aside.Add the potatoes into the pan in which the gravy is getting saut\u00e9ed and mix well.", "Once the gravy is well coated with potatoes, switch off the stove.", "This will take about 2-3 minutes.Serve the Konkani Style Batata Song Recipe along with\u00a0Phulka/Tawa Paratha\u00a0and\u00a0Gujarati Dal by the side for a weekday meal."]'::jsonb, 30, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Konkani_Style_Batata_Song_Recipe_Dry_Red_Chili_Potatoes_Fry_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/989.Konkani_Style_Batata_Song_Recipe_Dry_Red_Chili_Potatoes_Fry_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sindhi Dal Pakwan Recipe - A Delicious Sindhi Breakfast', 'sindhi-dal-pakwan-recipe-a-delicious-sindhi-breakfast', 'Sindhi Dal Pakwan is a popular and a royal breakfast dish in Sindhi community. The crisp deep fried Maida Puris (Pakwan) are served with simple Chana dal, garnished with chutney and chopped onion.The Pakwan accompanied with dal is often served in various special occasions and even in regular days for breakfast.', '["1 cup Chana dal (Bengal Gram Dal)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "1/4 teaspoon Red Chilli powder", "1 teaspoon Amchur (Dry Mango Powder)", "1/2 teaspoon Sugar", "Salt , as needed", "1 tablespoon Ghee", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Cumin seeds (Jeera)", "2 Green Chillies , slit", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'green chillies', 'amchur (dry mango powder)', 'ghee', 'asafoetida (hing)', 'red chilli powder', 'curry leaves', 'sugar', 'cumin seeds (jeera)', 'turmeric powder', 'chana dal (bengal gram dal)', 'garam masala powder']::text[], '["To begin making the Sindhi Dal Pakwan Recipe, wash and soak chana dal in water overnight or for at least 4 hours.Once soaked, drain the water and cook the chana dal in 2 cups of water in the pressure cooker for a couple of whistles along with salt, sugar, turmeric powder, garam masala and amchur powder.After a 4 to 5 whistles, turn the heat to low and simmer for another 5 minutes and turn off the heat.", "Allow the pressure to release naturally.", "The grains of the chana dal should be soft and yet separate.Open the lid once the pressure releases completely.In a small tadka pan, heat ghee over medium heat.", "Add the cumin and green chilies.Saute for a few seconds, add the curry leaves and asafoetida and turn off the heat.Pour the seasoning over the Sindhi Chana Dal and serve hot along with Pakwan.Serve the Sindhi Dal along with Pakwan (Crisp Puris)\u00a0for breakfast, lunch or dinner."]'::jsonb, 55, 'Sindhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Sindhi_Dal_Pakwan_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/990.Sindhi_Dal_Pakwan_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mysore Masala Dosa Made With Ragi Dosa Batter', 'mysore-masala-dosa-made-with-ragi-dosa-batter', 'Mysore Masala Dosa Recipe is a famous breakfast dish among the  Southern part of India. In this recipe we have used a ragi idli dosa batter to make the Masala Dosa. Traditionally, idli boiled rice and urad dal, along with some jaggery is used to make the dosa.', '["1 cup Idli Rice , (a special rice available in the indian stores for making idli and dosas)", "1/2 cup Ragi Seeds", "1 cup White Urad Dal (Whole)", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "Water , for soaking the rice", "1 Onion , chopped", "3 tablespoon Roasted Gram Dal (Pottukadalai)", "2 Dry Red Chillies", "4 cloves Garlic", "1 inch Ginger , chopped", "Salt , to taste", "4 Potatoes (Aloo)", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves", "1 pinch Asafoetida (hing)", "1 Onion , sliced", "1 teaspoon Turmeric powder (Haldi)", "4 sprig Coriander (Dhania) Leaves , chopped", "Salt , to taste"]'::jsonb, ARRAY['idli rice', 'ragi seeds', 'white urad dal', 'whole', 'methi seeds', 'fenugreek seeds', 'water', 'onion', 'roasted gram dal', 'pottukadalai', 'dry red chillies', 's garlic', 'ginger', 'salt', 'potatoes', 'aloo', 'cumin seeds', 'jeera', 'curry leaves', 'asafoetida', 'hing', 'turmeric powder', 'haldi', 'coriander', 'dhania']::text[], '["To begin making the Mysore Masala Dosa Recipe, we will first make the Ragi (Millet) Idli Dosa Batter.Add idli rice and ragi in a big bowl together, the level of water required is an inch above the rice in the bowl.", "Let it soak for about 6 hours.Soak the urad dal and fenugreek in water such that all of the dal is completely immersed in water.", "The level of water will be 2 inches above the dal in the bowl.", "Let it soak for about 6 hours.First grind the urad dal into a fine smooth batter.", "While grinding just enough water to make it into a very very smooth batter.", "The batter will look fluffy.Grind the rice and millet mixture into a smooth batter, adding just the required amount of water to grind into an almost smooth batter.", "Adding too much water will make the mixture too watery.", "Combine the urad and rice batter, add salt to taste and set aside for at least 12 hours or overnight until the batter ferments.", "You will notice the batter would have risen in volume.Hence you should place the batter in a large container so it has enough room to increase in its volume.*Note on fermenting the Ragi Idli & Dosa BatterFermenting has to take place where the weather is warm.", "So ideally in summer, the batter ferments very well and doubles or triples its quantity.But in cold places, the batter has to be kept in an oven.", "If your oven has a light, then turn on the light for a few hours with the batter in the oven.Once the oven is warm, turn off the light and let the batter ferment.", "If your oven does not have a light, then preheat the oven to warm, turn off oven then keep the batter in the oven to ferment.", "This process can be mastered with experience.*To Make the Red ChutneySoak the dry red chilli in warm water for at least 20 minutes.Once done you can add all the ingredients - Onion, ginger, garlic, roasted gram dal, soaked dry red chillies and salt into a mixer and grind with little water to form a coarse paste.You can check for seasoning and adjust the salt or spice level if you want later on and set aside in a bowl.*To make the PalyaPressure cook the potatoes with 2 cups of water, sprinkle little salt and cook for atleast 4 whistle.Once done allow the pressure cooker to release naturally, and drain all the water and peel off the skin and mash the potatoes and set aside.Heat a flat skillet with oil, add mustard seeds and allow it to sizzle for few seconds.", "Sprinkle with hing and add curry leaves and allow it to sparkle for few seconds.Add sliced onions, ginger and garlic for few minutes and saut\u00e9 until the onions turn translucent.Add turmeric powder, salt and boiled potatoes and mix well until it is well combined.", "Check for salt and add coriander leaves at the end and stir.", "Add it into a bowl and keep it ready.*To make the Mysore Masala DosaThe next step is to assemble the dosa.", "Heat a dosa Tawa.", "Pour a small ladleful of dosa batter onto the Tawa and spread evenly with the back of the ladle to make a medium-sized dosa.Drizzle half a teaspoon of oil around the dosa and cook over low heat for few seconds.", "Spread a little red chutney all over the dosa and place some potato masala in the center of the dosa.Continue to cook the dosa over low heat till the dosa turned a little brown.", "Gently fold over one side and transfer the dosa to a serving plate.Serve\u00a0Mysore Masala Dosa Recipe along with south Indian\u00a0coconut chutney\u00a0&\u00a0Bangalore Restaurant Style Sambar\u00a0to make your breakfast complete."]'::jsonb, 60, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Mysore_Masala_Dosa_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/991.Mysore_Masala_Dosa_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Style Mangsher Jhol Recipe-Mutton Curry', 'bengali-style-mangsher-jhol-recipe-mutton-curry', '‘Mangsher Jhol’ and Sundays are synonymous in Bengali kitchen. I remember my childhood days when Sunday used to be dance classes in the morning, ‘Tekona Porota’ and ‘Aloo Chorchori’ for breakfast or ‘Luchi-Sada Aloor Chorchori’ for breakfast and Chicken Curry or Mutton Curry for lunch was a must. I still remember when Maa used to grind the masalas in ‘shil-nora’ (a traditional way of grinding spices with the help of a oblong stone piece on a large stone square piece). And the flavour or freshly ground spices were unparalleled to any branded spice powder.', '["1 kg Mutton", "3 Potato (Aloo) , peeled and cut into halves", "2 cups Onion , finely chopped", "2 tablespoon Onions , paste", "2 tablespoon Garlic , paste", "2 tablespoon Ginger , paste", "1 teaspoon Cumin powder (Jeera)", "1-1/2 teaspoon Coriander Powder (Dhania)", "1 teaspoon Turmeric powder (Haldi)", "2 teaspoons Red Chilli powder , or as per your heat tolerance", "1 tablespoon Vinegar", "2 tablespoons Mustard oil , + 1/2 cup", "150 grams Curd (Dahi / Yogurt)", "4 teaspoons Ghee", "1 teaspoon Garam masala powder", "1 teaspoon Sugar", "Salt , to taste", "2 Bay leaf (tej patta)", "2 Dry Red Chillies", "1 Black cardamom (Badi Elaichi)", "4 Cardamom (Elaichi) Pods/Seeds", "4 Cloves (Laung)", "1 Cinnamon Stick (Dalchini)"]'::jsonb, ARRAY['mutton', 'potato', 'aloo', 's onion', 'onions', 'garlic', 'ginger', 'cumin powder', 'jeera', 'coriander powder', 'dhania', 'turmeric powder', 'haldi', 's red chilli powder', 'vinegar', 's mustard oil', 's curd', 'dahi / yogurt', 's ghee', 'garam masala powder', 'sugar', 'salt', 'bay leaf', 'tej patta', 'dry red chillies', 'black cardamom', 'badi elaichi', 'cardamom', 'elaichi', 'laung', 'cinnamon stick', 'dalchini']::text[], '["To begin making the Mangsher Jhol recipe, wash the mutton pieces and drain the water.", "Marinate the mutton pieces with 2 tablespoons onion paste, 1/2 teaspoon ginger paste,1/2 teaspoon garlic paste, 1/2 teaspoon turmeric powder, 1 tablespoon vinegar and 2 tablespoons mustard oil.", "Mix well.", "Cover and keep the meat with marination in the refrigerator at least for 3-4 hours.Smear little salt and turmeric powder to the peeled and halved potatoes.", "Heat oil in a kadai or wok.", "Fry the potato pieces till golden brown.", "Keep them aside.Add 3 teaspoons ghee to the oil.", "Temper the ghee+oil with the ingredients mentioned under ''For tempering''.", "When you get the aroma, add chopped onion and cook till the onion turns soft.Once the onions are soft, add sugar.", "Sugar when caramelize with oil will give very nice red colour.Add the rest of the ginger paste and garlic paste and cook till oil separates.Now add the marinated mutton pieces with all the marinade.", "Mix very well.", "Saut\u00e9 the mutton for another 4-5 minutes.Beat the yogurt and pour it in the kadai.", "Mix very well.", "After adding the yogurt you\u2019ll see that mutton start releasing water.", "Stir continuously for another 5-6 minutes.", "Add salt.Add all the dry masalas and stir continuously till oil starts separating from the sides of the kadai.", "The process of this continuous saut\u00e9 is very important otherwise you\u2019ll not get the red, velvety, tasty mutton gravy.Add fried potato pieces and give it a final mix.", "Now add 2 to 2-1/2 cups of warm water.", "Let it come to a boil.You can cook the mutton curry in two ways.", "Either you can cook it in a pressure cooker for faster cooking (On high heat one whistle and then 20 minutes on low heat.", "Let the pressure release of its own) or you can cook it in the kadai/handi with lid on slow heat until the meat is done.When the meat is done transfer it in a serving bowl.", "Drizzle 1 teaspoon ghee and a little garam masala powder.", "Cover and let it rest for few minutes.", "Serve hot.Serve this delicious\u00a0Mangsher Jhol along with\u00a0Steamed Rice\u00a0for a weekend dinner.", "You can also serve\u00a0Chaler Payesh\u00a0as a dessert to end your scrumptious meal."]'::jsonb, 225, 'Bengali', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pal.rini1-gmail.com/Mangsher_Jhol_Bengali_Style_Mutton_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/992.Mangsher_Jhol_Bengali_Style_Mutton_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sorakaya Masala Curry Recipe - Andhra Style Sorakaya Curry', 'sorakaya-masala-curry-recipe-andhra-style-sorakaya-curry', 'Sorakaya Koora or Sorakaya Masala Curry is a simple and tasty Andhra Style curry where Bottle Gourd/Lauki is cooked with simple South Indian masalas. This recipe is simple to make and therefore its perfect to make during busy mornings to pack in your lunch box.', '["300 grams Bottle gourd (lauki) , cut into 1/2 inch cubes", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Sesame seeds (Til seeds)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "1 Dry Red Chilli", "1 teaspoon Sambar Powder", "Salt , to taste"]'::jsonb, ARRAY['s bottle gourd', 'lauki', 'oil', 'mustard seeds', 'rai/ kadugu', 'sesame seeds', 'til seeds', 'white urad dal', 'split', 'curry leaves', 'dry red chilli', 'sambar powder', 'salt']::text[], '["To begin making the Sorakaya Koora / Masala Curry recipe, firstly peel the bottle gourd and cut into 1/2 inch cubes.", "Keep it aside.Into a pressure cooker, add the cut Bottle gourd/ Sorakaya, along with a little salt,\u00a0 pinch of turmeric powder and 2 tablespoons water.", "Pressure cook on high heat for 2 whistles and turn off the heat.Release the pressure immediately, by running it under cold water.", "This will prevent the bottle gourd from getting over cooked.Heat a heavy bottomed pan, add mustard seeds, urad dal, sesame seeds, and red chillies.", "Allow it to crackle and the dal to turn golden brown.Stir in the curry leaves, the cooked\u00a0Sorakaya/ bottle gourd, sambar powder, salt to taste and stir well to combine.Cover the pan and cook the\u00a0Sorakaya Koora for 2-3 minutes until all the masala comes together.Once done, check the salt and adjust according to taste.", "Turn off the heat, transfer to a serving bowl and serve hot.Serve\u00a0Sorakaya Koora Recipe\u00a0along with\u00a0Mixed Vegetable Sambar,\u00a0Beetroot Pachadi\u00a0and\u00a0Steamed Rice\u00a0for your weekday lunch or dinner."]'::jsonb, 20, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Sorakkai_Poriyal_Recipe_Bottle_gourd_Palya_South_indian_sabzi_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/993.Sorakkai_Poriyal_Recipe_Bottle_gourd_Palya_South_indian_sabzi_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pudina Shavige Recipe - Pudina Semiya Upma Recipe', 'pudina-shavige-recipe-pudina-semiya-upma-recipe', 'The Pudina Shavige Recipe is a delicious Karnataka style Pudina Semiya Upma Recipe which is healthy packed with taste. The shavige also known as semiya is made from foxtail millet vermicelli but you can also use the normal ones or even the rice vermicelli. Usually the mint goes really well with chutneys and pulao but adding them to the shavige will create a nutritious and flavor meal. It also has few roasted peanuts and urad dal for the crunch that you can get from every bite of it.', '["2 cups Semiya (Vermicelli) , rice vermicelli or foxtail millet vermicelli will also do", "2 tablespoons Raw Peanuts (Moongphali)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "Salt , to taste", "1 tablespoon Ghee , for flavour", "1 Onion , chopped", "2 cloves Garlic", "1 inch Ginger , chopped", "1 Green Chilli , slit", "1 teaspoon Cumin seeds (Jeera)", "1/2 cup Mint Leaves (Pudina)", "1/4 cup Coriander (Dhania) Leaves", "Salt , to taste"]'::jsonb, ARRAY['salt', 'ginger', 'green chilli', 'mustard seeds', 'coriander (dhania) leaves', 'cloves garlic', 'curry leaves', 'white urad dal (split)', 'onion', 'cumin seeds (jeera)', 'peanuts (moongphali)', 'semiya (vermicelli) rice vermicelli foxtail millet vermicelli will also do', 'mint leaves (pudina)', 'ghee flavour']::text[], '["To begin making the Karnataka Style Pudina Shavige Recipe prep all the ingredients and keep it aside.Heat oil in a saucepan over medium heat, add cumin seeds and allow it to crackle for few seconds.", "Add ginger garlic and saute till it softens.", "Add onions and saute till the onions turn translucent.Finally add mint leaves, coriander leaves and green chilli and saute till the leaves wilt and turn off the heat.Grind the pudina mixture into a coarse paste by adding very little water.", "Finally to make the pudina\u00a0Pudina Shavige, heat oil in a pan over medium heat.", "Add the mustard seeds and urad dal and allow it to crackle and the dal to turn golden and crisp.", "Add the peanuts and roast on low heat until crisp and golden.Stir in the curry leaves, the semiya (vermicelli), salt to taste, pudina paste and 1-1/2 cups of water.", "Cover the pan and cook the\u00a0Pudina Shavige until all the water is absorbed and the semiya is cooked completely.Ensure you give the Pudina Shavige a stir half way through.", "Once the\u00a0Pudina Shavige\u00a0is cooked completely, add the ghee and give it a stir.Transfer the\u00a0Pudina Shavige to a serving bowl and serve hot for breakfast.Serve the\u00a0Pudina Shavige Recipe along with\u00a0coconut chutney,\u00a0raita\u00a0and fruit bowl to relish your morning breakfast."]'::jsonb, 40, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Karnataka_Style_Pudina_Shavige_Recipe_Mint_Vermicelli_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/994.Karnataka_Style_Pudina_Shavige_Recipe_Mint_Vermicelli_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Udupi Red Parboiled Rice Shavige Recipe', 'udupi-red-parboiled-rice-shavige-recipe', 'Shavige, a popular Udupi Indian breakfast recipe prepared with Red parboiled rice dough. Though it is labour intensive but the end result is all worth it. One can relish it with rasayana / sweet coconut milk / season as lemon sevai. Do try and enjoy this age old recipe.', '["4 cups Red matta rice , boiled", "1 cup Dosa rice", "1/2 cup Fresh coconut , grated", "Salt , to taste", "3 cups Water"]'::jsonb, ARRAY['salt', 'coconut', 'water', 'mattaice', 'dosa rice']::text[], '["To begin making the Udupi Red Parboiled Rice Shavige recipe, soak red parboiled rice and dosa rice in water for 8 to 10 hours.Drain water and grind it to very smooth paste adding little water along with grated coconut.", "Add salt to taste.", "Don''t make thin paste, the batter should be spoonable thick.", "To a greased container, fill the ground thick batter.", "Place it in a steamer and cook for 30 to 35 minutes.", "Check if its cooked by piercing a toothpick.", "If it is done, the toothpick will come out clean.", "Unmould from the container and place the cooked dough into the idiyappam press when it is hot.", "Press in a circular shape.", "You will see strands of\u00a0Red Parboiled Rice Shavige coming.", "Serve\u00a0Red Parboiled Rice Shavige with fresh coconut milk / season it as lemon sevai.Serve\u00a0Shavige along with\u00a0South Indian Coconut Chutney\u00a0or you can make other recipes like\u00a0Kara Sevai."]'::jsonb, 120, 'Udupi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/Udupi_Red_Parboiled_Rice_Shavige_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/995.Udupi_Red_Parboiled_Rice_Shavige_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mutton Varattiyathu Recipe - Malabar Mutton Roast', 'mutton-varattiyathu-recipe-malabar-mutton-roast', 'Mutton Varattiyathu Recipe is a Malabar style Mutton Roast, marinated along with simple spices and stir fried to give it a lovely roasted flavour.', '["600 grams Mutton", "1 Onion , thinly sliced", "1 Tomato , thinly sliced", "1 teaspoon Ginger , pounded", "1 teaspoon Garlic , pounded", "2 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 sprig Curry leaves", "Salt , Salt", "1 Onion , sliced", "3 Dry Red Chillies", "1 sprig Curry leaves", "2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1/2 teaspoon Black pepper powder", "1/4 teaspoon Garam masala powder", "1 tablespoon Coconut Oil", "Salt"]'::jsonb, ARRAY['s mutton', 'onion', 'tomato', 'ginger', 'garlic', 'red chilli powder', 'turmeric powder', 'haldi', 'curry leaves', 'salt', 'dry red chillies', 'cumin powder', 'jeera', 'methi seeds', 'fenugreek seeds', 'black pepper powder', 'garam masala powder', 'coconut oil']::text[], '["To begin making the\u00a0Mutton Varattiyathu,\u00a0thoroughly wash\u00a0and clean the mutton pieces.", "To marinate the mutton, in a mixing bowl combine sliced\u00a0onions and tomatoes,\u00a0\u00a0ginger garlic paste, chilli powder,\u00a0turmeric powder, salt to taste and a few curry leaves along with the mutton.", "Mix well and allow the mutton to marinate for 30 minutes.", "In a pressure cooker, add in the marinated mutton pieces along with the marinade and pressure cook for 4 whistles.", "Turn off the flame and allow the pressure to release naturally.", "In a heavy bottomed pan heat oil on medium flame, add curry leaves, allow them to crackle and then add dried red chillies.", "Next add the sliced onions and saute for a couple of minutes.", "Once they have slightly softened,\u00a0 add in cumin powder and fenugreek seed, black\u00a0pepper powder, garam masala powder, salt and give it a good stir.", "At this stage add in the cooked mutton to it and mix well with the masala.", "Add quarter cup of water and allow thee mutton to come to a rolling boil.", "Garnish it with curry leaves and Mutton Roast is ready to be served.Serve this\u00a0Mutton Varattiyathu\u00a0along with\u00a0Kerala Style Appam Recipe\u00a0or\u00a0Malabar Parotta Recipe\u00a0for a quick weekend lunch."]'::jsonb, 70, 'Kerala', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/naseerawazir-gmail.com/Mutton_Varattiyad__Malabar_Mutton_Roast.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/996.Mutton_Varattiyad__Malabar_Mutton_Roast.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vempampoo Rice Recipe (Dried Neem Flowers Rice)', 'vempampoo-rice-recipe-dried-neem-flowers-rice', 'Vempampoo or Dried neem flowers are generally used in various tamil cooking recipes. This is a simple but very healthy recipe of tempering of dried neem flavours with spices and finally tossing the black rice with them. I generally take these flowers from my mom’s place where we have a neem tree. The flowers would automatically fall down between march to may month. So we generally put a cloth below the tree and collect these flowers. The process does not stop here, we would then dry them up in the sun for 2 days and clean the flowers by removing the neem sticks and neem leaves which fall along with the flowers. We generally collect these flowers and store them for a year.', '["1 cup Black Rice , cooked", "Oil , or ghee as required", "1/3 teaspoon Asafoetida (hing)", "1/2 teaspoon White Urad Dal (Split)", "2 teaspoons Dried Neem Flowers", "1 Dry Red Chilli", "Few Curry leaves"]'::jsonb, ARRAY['black rice', 'sunflower oil ghee', 'asafoetida (hing)', 'dry red chilli', 'curry leaves', 'white urad dal (split)', 'dried neem flowers']::text[], '["To begin making the Vepampoo Rice recipe, we will first cook the black rice.If you are cooking in electric rice cooker there is no need to soak this rice, however if you are cooking black rice in pressure cooker,\u00a0you must soak for a minimum of 6 to 8 hours.Cook rice with the required water till the cooker releases atlas 6 whistles as black rice takes time to cook.The next step is to temper the black rice.", "Heat oil or ghee in a heavy bottomed pan.", "Once the oil is hot, add hing, red dry chilli, urad dal, dried neem flowers.", "Add all of them together at one go.Once the neem flower is cooked, add the cooked black rice.", "The indication of neem flower being cooked is urad dal becomes brownish in colour.Add salt, mix well and cook for 2 minutes and it is ready to be served.", "Serve Vepampoo Rice along with\u00a0Onion Tomato Cucumber Raita,\u00a0Tadka Raita\u00a0or any other raita of your choice."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Neeru_Srikanth/Vepampoo_Rice_Dried_Neem_Flowers_Rice.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/997.Vepampoo_Rice_Dried_Neem_Flowers_Rice.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Smoked Dal Makhani Recipe - Dhaba Style', 'smoked-dal-makhani-recipe-dhaba-style', 'The Dal Makhani Recipe is a deliciously flavoured lentil curry that is also popularly known as the Punjabi ‘dhaba’ dal. This dal makhani is made with black whole urad dal and rajma, flavoured with subtle Indian spices and simmered with cream and butter. It is said that the longer the dal simmers in the spices, the better flavors it gets.', '["3/4 cup Black Urad Dal (Whole)", "1/4 cup Rajma (Large Kidney Beans)", "1 teaspoon Cumin seeds (Jeera)", "1 Tomato , finely chopped", "1 inch Ginger , finely chopped", "2 cloves Garlic , finely chopped", "2 Green Chillies , finely chopped", "1 Bay leaves (tej patta) , torn", "1 inch Cinnamon Stick (Dalchini) , broken", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Garam masala powder", "1/4 teaspoon Cardamom Powder (Elaichi)", "1 teaspoon Ghee", "1/4 cup Fresh cream", "6 sprig Coriander (Dhania) Leaves , finely chopped", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "Salt , to taste", "1 Charcoal , for smoking"]'::jsonb, ARRAY['black urad dal', 'whole', 'rajma', 'large kidney beans', 'cumin seeds', 'jeera', 'tomato', 'ginger', 's garlic', 'reen chillies', 'bay leaves', 'tej patta', 'cinnamon stick', 'dalchini', 'turmeric powder', 'haldi', 'cumin powder', 'garam masala powder', 'cardamom powder', 'elaichi', 'ghee', 'fresh cream', 'coriander', 'dhania', 'kasuri methi', 'dried fenugreek leaves', 'salt', 'charcoal']::text[], '["To begin making the Smoked Dal Makhani Recipe Soak the black urad dal and rajma together in 4 cups of water for about 8 hours.", "Heat ghee in the pressure cooker over medium heat; add the cumin seeds and allow it to crackle.", "Add the ginger, garlic and green chillies and saute for a few seconds.Add the bay leaves, cinnamon stick, tomatoes, turmeric powder, cumin powder, garam masala powder, cardamom powder.", "Saute on medium heat until the tomatoes become soft.", "Add the soaked dal along with more water until the dal mixture has at least 2 inches of water above it.", "Add salt to taste and cover the pressure cooker.Pressure cook the Dal Makhani for about 35-40 minutes on medium heat.", "After 35-40 minutes, turn off the heat and allow the pressure to release naturally.When you open the cooker, the dal should be cooked well.", "Add additional water to make it a dal consistency if it has become a little dry.Heat butter in a heavy bottomed pan; add the cumin seeds, cooked dal makhani and cream.", "Turn the heat to low and simmer\u00a0the dal makhani for 10 to 15 minutes.", "While simmering, keep mashing the Dal Makhani to make it creamy and this will also help the flavours get deeper.Traditionally Punjabi''s have been known to simmer their dals for more than an hour or two, to get the intense richness and taste from the dal makhani.", "But make sure that when you simmer the dal it is stirred occasionally, thereby preventing the dal makhani from sticking to the bottom of the pan.Finally, during the last 10 minutes of the simmering process, add the dried fenugreek leaves and the coriander leaves into the dal makhani.", "Stir well and simmer for another 5 minutes.The final step is to smoke the Dal Makhani - heat coal on a flame for about 5 minutes until it has a few red hot spots around.Place a katori/ very small in the centre of the dal makhani pan and immediately place the hot coal inside.", "Add a few drops of ghee and you will notice it begins to smoke.", "Cover the pan so the smoke circulated and flavours the dal.", "After about 30 - 40 seconds, open the lid and remove the bowl.", "You will notice a delicious smoky flavour in the Dal Makhani.Turn off the heat and transfer the Smoked Dal Makhani to a serving bowl.", "Serve Dal Makhani along with\u00a0Garlic Naan,\u00a0Quick Paneer Masala\u00a0and\u00a0Jeera Rice\u00a0for a delicious meal."]'::jsonb, 70, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Dhaba_Style_Dal_Makhani_Recipe_-_Coal_Smoked_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/998.Dhaba_Style_Dal_Makhani_Recipe_-_Coal_Smoked_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Panchmel Dal Recipe | Rajasthani Dal | Panchkuti Dal', 'panchmel-dal-recipe-rajasthani-dal-panchkuti-dal', 'Rajasthani Panchmel Dal also known as Panchkuti is a traditional Rajasthani dal recipe. It is a staple in almost every household in Rajasthan. The Panchmel Dal is most often served along with Dal Baati, that is another popular dish from the Rajasthani Cuisine.  Panch mean five in hindu and hence the name Panchmel that is delicately blended together using various spices.', '["1/4 cup Arhar dal (Split Toor Dal)", "1/4 cup Masoor Dal (Whole)", "1/4 cup Chana dal (Bengal Gram Dal)", "1/4 cup Black Urad Dal (Whole)", "1/4 cup Green Moong Dal (Whole)", "2 tablespoons Ghee", "1 teaspoon Cumin seeds (Jeera)", "1 Onion , finely chopped", "4 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "2 Green Chillies , slit vertically", "1 Bay leaves (tej patta)", "1 inch Cinnamon Stick (Dalchini) , broken", "1 Tomato , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Asafoetida (hing)", "Salt , as required", "1 Lemon , juice extracted", "1 tablespoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies , broken"]'::jsonb, ARRAY['tomato', 'salt', 'arhar dal (split toor dal)', 'ginger', 'chana dal (bengal gram dal)', 'bay leaves (tej patta)', 'ghee', 'asafoetida (hing)', 'red chilli powder', 'cloves garlic', 'dry red chillies', 'onion', 'cumin seeds (jeera)', 'green chillies verticy', 'cinnamon stick (dalchini)', 'lemon', 'turmeric powder', 'green moong dal', 'black urad dal', 'masoor dal']::text[], '["To begin making the Rajasthani Panchmel Dal,\u00a0we will first soak the all the dals in 3 cups of water for about 3 hours.", "Heat ghee in a pressure cooker over medium heat; add the cumin seeds and allow it to crackle.", "Add the onion, green chillies, ginger and garlic and saute until the onion softends.Add the bay leaf and cinnamon stick and saute for a few seconds until you can smell the aromas coming through.Next add the tomatoes, turmeric powder, red chilli powder, hing and saute for about a minute until the tomatoes have slightly softened.Once the tomatoes have softened, add the soaked dals, salt to taste and add water if required such that the water is at least 2 inches above the level of dal.Cover the pressure cooker, and pressure cook the Rajasthani Panchmel Dal for about 5 to 6 whistles - about 20 minutes until it is completely cooked through.Turn off the heat and allow the pressure to release naturally.", "Once the pressure has released, check if the dals are cooked well to perfection.", "Once pressed between fingers it should mash easily.Stir in the juice from the lemon and the coriander leaves and transfer the Rajasthani Panchmel Dal to a serving bowl.The next is the tadka, heat ghee in a pan over medium heat.", "Add the cumin seeds and red chillies and allow it to roast for a few seconds.", "Turn off the heat and add this tadka to the Rajasthani Panchmel DalServe the Rajasthani Panchmel Dal along with\u00a0Bati\u00a0or eat it along\u00a0Spicy Paneer Pulao With Vegetables\u00a0followed by the mouth-watering\u00a0Traditional Rasmalai Recipe."]'::jsonb, 40, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Rajasthani_Dal_Panchmel_Dal_recipe_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/999.Rajasthani_Dal_Panchmel_Dal_recipe_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Egg Roast Masala Recipe', 'kerala-egg-roast-masala-recipe', 'Kerala Egg Roast Masala Recipe is a delicious spicy preparation of the eggs in a delicious onion and tomato based gravy that is delicately cooked in coconut oil adding the authentic taste. The addition of sliced onions, along with chunks of garlic, green chillies and curry leaves make this dish stand out from the crowd of egg curries.', '["6 Whole Eggs , boiled and shelled", "3 Onions , thinly sliced", "6 Tomatoes", "8 cloves Garlic , crushed whole", "2 inch Ginger , finely chopped", "3 sprig Curry leaves , torn", "4 Green Chillies , slit", "3 teaspoon Garam masala powder", "1/2 teaspoon Black pepper powder , (adjust)", "1-1/4 teaspoon Kashmiri Red Chilli Powder", "1 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 tablespoon Coconut Oil", "Salt , to taste"]'::jsonb, ARRAY['whole eggs', 'onions', 'tomatoes', 's garlic', 'ginger', 'curry leaves', 'reen chillies', 'garam masala powder', 'black pepper powder', 'kashmiri red chilli powder', 'coriander powder', 'dhania', 'turmeric powder', 'haldi', 'mustard seeds', 'rai/ kadugu', 'coconut oil', 'salt']::text[], '["To begin making the Kerala Egg Roast Curry Recipe, first boil the eggs in water for 10 to 12 minutes and turn off the heat.", "Once eggs are cooled, peel the shell and keep the boiled eggs aside.Cut the tomatoes into half and place in the pressure cooker, add just 2 tablespoons of water.", "Pressure cook for 2 to 3 whistles and turn off the heat.", "Once the pressure has released and the tomatoes have cooled, peel and discard the skin from the tomatoes.Chop the tomatoes and keep them aside.", "Keep the water that has released from cooking the tomatoes.", "This will be used for the gravy of the recipe.The next step is to make the make the egg roast masala.Heat coconut oil in a Kadai\u00a0over medium heat.", "Add the mustard seeds and allow it to crackle.Once the mustard seeds crackle, add the onions, ginger , green chillies and garlic.", "Saute the onions, until softened and lightly golden.", "Once the onions are done, add the curry leaves, tomatoes, turmeric powder, garam masala powder, coriander powder, black pepper powder, red chilli powder and salt to taste.Saute for about 5 to 6 minutes until the tomatoes absorb all the flavours of the masala.", "Add a little additional 1 tablespoon of coconut oil at this stage to heighten the taste of the egg roast masala.When you are ready to serve the egg roast masala,\u00a0 add in the boiled eggs and simmer in the tomato masala for 3 to 4 minutes and then serve hot.Serve the\u00a0Kerala Egg Roast Masala / Curry along with\u00a0Kerala Appam\u00a0or along with steamed rice for lunch or dinner and is sure to be a hit among family and friends.", "Enjoy!."]'::jsonb, 60, 'Kerala', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Kerala_egg_roast_curry_masala_Recipe_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1000.Kerala_egg_roast_curry_masala_Recipe_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false);

INSERT INTO public.recipes (
  title, slug, description, ingredients, cleaned_ingredients,
  instructions, total_time_mins, cuisine, diet, source_url,
  image_url, image_status, image_source, data_source, servings, review_count, is_featured
) VALUES
  ('Pudalangai Poriyal Recipe  - Snake Gourd Poriyal Recipe', 'pudalangai-poriyal-recipe-snake-gourd-poriyal-recipe', 'Pudalangai Poriyal Recipe is an authentic Kerala dish and a dry side prepared usually as an accompaniment to the main meal.  Snake gourd is sliced and cooked in minimal spices and tossed along with grated coconut.', '["2 Snake gourd (pudulangai) , sliced into small pieces", "1 Onion , finely chopped", "4 Green Chillies , finely chopped", "1 teaspoon Cumin powder (Jeera)", "1/4 teaspoon Turmeric powder (Haldi)", "Oil , as required", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 cup Fresh coconut , grated", "Salt , as required", "8 Curry leaves"]'::jsonb, ARRAY['snake gourd', 'pudulangai', 'onion', 'reen chillies', 'cumin powder', 'jeera', 'turmeric powder', 'haldi', 'oil', 'mustard seeds', 'rai/ kadugu', 'fresh coconut', 'salt', 'curry leaves']::text[], '["To begin making the Pudalangai Poriyal Recipe, firstly wash snake gourd and slice them into medium sized piece.", "In a heavy bottomed pan, add oil and heat over medium heat.Once the oil is hot, add mustard seeds.", "Once the seeds splutter, add curry leaves and green chillies.", "Now add the snake gourd, sprinkle some salt and turmeric powder and mix well.", "Add a few drops of water, cover and cook the poriyal.", "Simmer the flame and cook the vegetable with lid covered until they become tender and cooked well.", "This will take about 6-8 minutes.", "Open the lid and finally, add the grated coconut to the Pudalangai Poriyal and give it a stir.Simmer the Pudalangai Poriyal for about 2 minutes and then switch off the flame and serve hot.Serve\u00a0Pudalangai Poriyal Recipe along with\u00a0Matta Rice/ Chemba Rice Recipe,\u00a0Nendra Pazham Pulissery Recipe - Ayurvedic Recipe\u00a0for a simple comforting meal on a weekday."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Podalangai_Poriyal_Snake_Gourd_Porial_recipe_7_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1001.Podalangai_Poriyal_Snake_Gourd_Porial_recipe_7_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Quinoa Brown Rice and Vegetable Pulao Recipe', 'quinoa-brown-rice-and-vegetable-pulao-recipe', 'Quinoa Brown Rice Pilaf is an aromatic, flavorful pilaf made using quinoa, brown rice and fresh seasonal vegetables. On those busy days, this will be a different, high protein, high fiber, one dish meal that will come to your rescue.', '["1 cup Quinoa", "1 cup Brown Rice , soaked in water", "1/2 cup Cauliflower (gobi) , florets", "1 Potato (Aloo) , peeled and diced", "1 Carrot (Gajjar) , diced", "1/4 cup Green beans (French Beans) , finely chopped", "1/4 cup Green peas (Matar)", "1 teaspoon Garam masala powder", "1 teaspoon Black pepper powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 Onion , chopped", "1 teaspoon Fennel seeds (Saunf)", "1/2 inch Ginger , grated", "3 cloves Garlic , grated", "2 Green Chilli , finely chopped", "1/4 cup Lemon juice", "1 tablespoon Extra Virgin Olive Oil , or ghee", "Salt , to taste", "1 cup Coconut milk", "4 cups Hot water", "Coriander (Dhania) Leaves , few, freshly chopped"]'::jsonb, ARRAY['coriander (dhania) leaves', 'cloves garlic', 'carrot', 'onion', 'black pepper powder', 'turmeric powder', 'salt', 'green chilli', 'virgin olive oil ghee', 'garam masala powder', 'brown rice', 'green beans (french beans)', 'water', 'lemon', 'coconut milk', 'cauliflower (gobi) florets', 'ginger', 'fennel seeds (saunf)', 'potato (aloo)', 'green peas (matar)', 'quinoa']::text[], '["To begin making the\u00a0Quinoa Brown Rice Pilaf, place a heavy bottom pan on medium heat.", "Add a teaspoon of oil or ghee.", "Once it is medium hot, add onions, garlic, ginger, green chilies and fennel seeds.", "Saute them for a minute.", "Add the chopped vegetables - cauliflower, potato, carrot, green beans and green peas.", "Saute the vegetables on medium flame for about 5-7 minutes until they soften.", "Add garam masala powder, turmeric powder, black pepper powder and salt to taste.", "Grate ginger and garlic to it.", "After a minute add the chopped green chilli.", "Add 2 cups boiling water and coconut milk.", "Mix all the ingredients well and bring the mixture to a boil.", "Once the water comes to a boil, turn the heat to medium.At this stage, drain the soaked rice.", "Add quinoa and rice into the boiling mixture, turn the heat to low, cover the pan and cook on low heat until all the water is absorbed and  Quinoa Brown Rice Pilaf is cooked.At this stage, the quinoa and rice should be perfectly cooked.", "Once done, turn off the heat and allow it to remain covered for about 5 to 10 minutes before you can serve.Once ready, open and fluff it up with a fort and transfer the Quinoa Brown Rice Pilaf in a serving plate.", "Stir it with freshly chopped coriander and lemon juice and serve.Serve Quinoa Brown Rice Pilaf with Burani Raita Recipe (Garlic Based Yogurt) or Mint And Pomegranate Raita Recipe for a comforting weeknight dinner or lunch."]'::jsonb, 55, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Reshma_Seetharam/Quinoa_brown_rice_and_vegetable_pilaf.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1002.Quinoa_brown_rice_and_vegetable_pilaf.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Beetroot Raita Recipe', 'beetroot-raita-recipe', 'Here is a healthy combination of grated beetroot combined with yogurt and a tadka of curry leaves, mustard and urad dal. The addition of green chillies and cumin powder enhances the taste beautifulling making it a healthy side dish for paratha, pulao and even a regular meal.', '["1/2 teaspoon Oil", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "2 cups Curd (Dahi / Yogurt)", "1 Beetroot , finely grated", "2 Green Chillies , finely chopped", "1 teaspoon Cumin powder (Jeera)", "Salt , to taste"]'::jsonb, ARRAY['oil', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'curry leaves', 's curd', 'dahi / yogurt', 'beetroot', 'reen chillies', 'cumin powder', 'jeera', 'salt']::text[], '["To begin making the\u00a0Beetroot Raita Recipe, first get all the ingredients ready and finely grate the beetroot and keep aside.In a large mixing bowl, add the yogurt, salt, cumin powder, green chillies and grated beetroot.", "Whisk well to combine.", "Check the salt and spice levels and adjust to suit your taste.", "Transfer the raita to a serving bowl.The final step is the make the seasoning.Heat oil in a tadka pan; add the the mustard seeds, urad dal and allow it to crackle and the dal to turn golden brown and crisp.", "Finally stir in the curry leaves and turn off the heat.", "Pour the seasoning onto the Beetroot Raita and serve.Serve the\u00a0Beetroot Raita\u00a0along with\u00a0Paneer Stuffed Ragi Paratha Recipe\u00a0or as a side dish along with your main course meal."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Beetroot_Raita_Healthy_Low_Calorie_Meal_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1003.Beetroot_Raita_Healthy_Low_Calorie_Meal_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Methi Sabzi Recipe - Potato Fenugreek Leaves Sabzi', 'aloo-methi-sabzi-recipe-potato-fenugreek-leaves-sabzi', 'The Aloo Methi Sabzi Recipe is a quick, simple and nutritious vegetables that is packed with flavors from the sauteed methi leaves also known as fenugreek leaves. The Aloo Methi Sabzi when combined with the sauteed onions and mild spices, makes this dish simple and yet delectable to the palate.', '["500 grams Baby Potatoes , boiled, peeled", "2 cups Methi Leaves (Fenugreek Leaves) , washed and chopped", "2 tablespoons Oil", "1 teaspoon Cumin seeds (Jeera)", "2 Onions , thinly sliced", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "1 Bay leaf (tej patta) , torn", "1 inch Cinnamon Stick (Dalchini) , broken", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Red Chilli powder", "1 teaspoon Amchur (Dry Mango Powder)", "Salt , to taste"]'::jsonb, ARRAY['s baby potatoes', 's methi leaves', 'fenugreek leaves', 's oil', 'cumin seeds', 'jeera', 'onions', 'ginger', 's garlic', 'bay leaf', 'tej patta', 'cinnamon stick', 'dalchini', 'turmeric powder', 'haldi', 'garam masala powder', 'coriander powder', 'dhania', 'red chilli powder', 'amchur', 'dry mango powder', 'salt']::text[], '["To begin making the\u00a0Aloo Methi Sabzi Recipe; we will first get the potatoes boiled till firm yet cooked.", "I like to refrigerate the boiled potatoes for a couple of hours before roasting them in a pan.Making the Aloo Methi Sabzi is a three stage process. first cooking the methi leaves and then roasting the potatoes along with spices and finally tossing methi and aloo together.Heat oil in a pan over medium heat; add the chopped methi leaves and saute until the methi leaves become soft and wilt down.", "Sprinkle a little salt and keep aside.Next,\u00a0 heat oil in a pan over medium heat; add the cumin seeds and allow it to crackle.", "Add the onions, ginger and garlic and saute until the onions are soft and tender.", "Add the boiled and peeled potatoes, bay leaves, cinnamon stick, turmeric powder, red chilli powder, amchur, coriander powder, garam masala powder and salt.Stir well to combine all the ingredient and turn the heat to low to roast the potatoes along with the spices for a good 10 minutes.After 10 minutes, once the potatoes have absorbed all the masala, add the cooked methi leaves and toss for less than a minute to combine to make the delicious tasting Aloo Methi Sabzi.Give it a taste and adjust the spices accordingly.", "Once done, turn off the heat and transfer the Aloo Methi Sabzi to a serving bowl and serve hot.Serve the\u00a0Aloo Methi Sabzi\u00a0along with\u00a0Tawa Paratha\u00a0and\u00a0Kadhi\u00a0for a quick weeknight dinner with your family.", "You can also serve\u00a0Kachumber Salad\u00a0with this meal to make it more filling and nutritious."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Aloo_Methi_Sabzi_recipe_17_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1004.Aloo_Methi_Sabzi_recipe_17_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dal Kabila Recipe - Diabetic Urad Dal Tadka', 'dal-kabila-recipe-diabetic-urad-dal-tadka', 'Dal kabila is a popular Mughal dish which is made with split urad dal. You can use either white urad dal or even split black urad dal to make this dish.', '["1 teaspoon Ghee", "1 cup White Urad Dal (Split)", "1 inch Cinnamon Stick (Dalchini)", "3 Cloves (Laung)", "3 Dry Red Chillies", "1 Onion , finely chopped", "3 cloves Garlic , finely chopped", "1/2 inch Ginger , finely chopped", "1 Tomato , finely chopped", "1 Green Chilli , slit", "1/4 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Garam masala powder", "3 sprig Coriander (Dhania) Leaves , chopped", "3 cups Water", "1 tablespoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Black pepper corns , lightly crushed"]'::jsonb, ARRAY['tomato', 'ginger', 'green chilli', 'ghee', 'black pepper corns', 'cinnamon stick', 'red chilli powder', 'cloves garlic', 'water', 'white urad dal (split)', 'dry red chillies', 'onion', 'coriander (dhania) leaves', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'cloves (laung)', 'garam masala powder']::text[], '["To begin making\u00a0Dal Kabila Recipe first wash urad dal and soak it for 2 hours.", "Prep all the ingredients.Add ghee into the pressure cooker and place over medium heat.Add in the dry red chillies, cinnamon stick, cloves and saute until you can smell the aromas of the spices coming through.Add Onions and slit green chillies and saute until the onions soften and change colour.Stir in the tomatoes, red chilli powder, turmeric powder, coriander powder, and saute.", "Finally add the split urad dal, salt along with 3 cups of water and cook for 5 to 6 whistles (about 15 minutes).Once done, turn off the heat and allow the pressure to release naturally.", "Once the pressure has released, check the salt and adjust according to taste.", "Transfer the Dal Kabila/ Urad Dal Tadka to a serving bowl.The final step is the tadka.Heat the ghee in a pan over medium heat; add the cumin seeds, crushed black pepper and sauce for a few seconds until the cumin seeds crackle.", "Spoon the takda over the Dal Kabila and serve hot.Serve the Dal Kabila/ Urad Dal Tadka with\u00a0Palak Ragi & Oats Wheat Thepla\u00a0and\u00a0Kachumber Salad Recipe With Cucumber, Onion & Tomatoes\u00a0for a wholesome weeknight diabetic indian dinner or lunch."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Dal_Kabila_White_Split_Urad_Dal_Recipe-4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1005.Dal_Kabila_White_Split_Urad_Dal_Recipe-4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Muttaikose Poriyal Recipe - Cabbage Stir fry With Coconut', 'muttaikose-poriyal-recipe-cabbage-stir-fry-with-coconut', 'The Muttaikose/Cabbage Poriyal Recipe is a very traditional South Indian dry vegetable made from cabbage. Muttaikose Poriyal is made by power cooking cabbage with a very simple seasoning of mustard seeds, curry leaves, salt and freshly grated coconut. It takes very less time to make and is an  amazing side dish which can be had along with any south Indian Meal.', '["500 grams Cabbage (Patta Gobi/ Muttaikose) , roughly chopped or sliced thin", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1-1/2 teaspoons White Urad Dal (Split)", "1 sprig Curry leaves , finely chopped", "1 Green Chilli , slit", "1/4 cup Fresh coconut , grated", "Salt , to taste"]'::jsonb, ARRAY['salt', 'green chilli', 'mustard seeds', 'coconut', 'curry leaves', 'white urad dal (split)', 'cabbage (patta gobi muttaikose)']::text[], '["To begin making the Muttaikose Poriyal Recipe/ Cabbage Poriyal, get the cabbage chopped or sliced and prep the rest of the ingredients and keep them ready.Heat a teaspoon of oil a heavy-bottomed pan on medium heat.", "Add the mustard seeds and urad dal.", "Allow them to crackle.", "Roast the urad dal until it gets lightly browned.Once the dal is browned, add the curry leaves, green chillies, cabbage and salt to taste.Give the mixture a stir.", "Sprinkle some water and cover the pan.", "Simmer for about 5 minutes until the cabbage is steamed and ready to eat.", "The cabbage should still be a bit firm and not too soft to get a nice texture when you eat it.Once done, add the grated coconut, give the cabbage poriyal a mix and check the salt.", "Add more coconut if required.", "Turn off the heat and serve the Muttaikose Poriyal / Cabbage Poriyal warm.Serve the Muttaikose Poriyal Recipe/ Cabbage Poriyal along with Tomato Rasam and steamed rice topped with ghee for lunch or dinner."]'::jsonb, 45, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Cabbage_Poriyal_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1006.Cabbage_Poriyal_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Cabbage Thoran Recipe - Kerala Style Cabbage Stir Fry', 'cabbage-thoran-recipe-kerala-style-cabbage-stir-fry', 'Cabbage Thoran is a delicious dish that is a staple of authentic Kerala cuisine. This popular dish makes a great accompaniment to steamed rice and curry and is an essential part of the famous Kerala Sadya. A dry dish, Thoran is commonly prepared using many different varieties of vegetables and spices. This recipe however uses cabbage as the main and only vegetable.', '["Ingredients for the thoran", "1 Cabbage (Patta Gobi/ Muttaikose) , washed and finely chopped", "1/2 cup Green peas (Matar) , optional", "1 sprig Curry leaves", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Dry Red Chilli", "1 teaspoon White Urad Dal (Split)", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 teaspoon Oil , or as required (coconut oil can even be used here)", "Ingredients to be ground to paste", "5 tablespoons Fresh coconut , grated, add more if required", "6 Shallots , cut into halves", "3 cloves Garlic , halved", "Green Chillies , halved", "3 sprig Curry leaves"]'::jsonb, ARRAY['ingredients for the thoran', 'cabbage', 'patta gobi/ muttaikose', 'green peas', 'matar', 'curry leaves', 'mustard seeds', 'rai/ kadugu', 'dry red chilli', 'white urad dal', 'split', 'turmeric powder', 'haldi', 'salt', 'oil', 'ingredients to be ground to paste', 's fresh coconut', 'shallots', 's garlic', 'green chillies']::text[], '["To begin making the Cabbage Thoran Recipe, grind the coconut, shallots, garlic, green chillies and curry leaves together into a coarse mixture in a blender or mixer.", "Once done, keep it aside.Heat the oil in wok.", "Once the oil is hot, add urad dal and mustard seeds and saute till the urad dal turns slightly brown in colour.", "Once done add in the red chilli and saut\u00e9 for a few seconds.", "Next add in the finely chopped cabbage leaves, cover the pan and and cook it on medium heat till the vegetable reduces in quantity or becomes soft.", "This should take no more than 1-2 minutes.Next add in the coarsely ground coconut paste, salt, turmeric powder and curry leaves.", "Stir to combine the ingredients well.", "Cover the pan and cook the vegetable on high heat till it steams well, for about 3-5 minutes.Continue stirring the cabbage till it gets coated with the coconut masala evenly.", "Check again if more salt is required.", "Once done and cooked, turn off the heat and the Cabbage Thoran is ready to be served.Serve\u00a0Cabbage Thoran\u00a0along with\u00a0Mixed Vegetable Sambar,\u00a0\u00a0Steamed Rice\u00a0and\u00a0Masala Chaasfor weekday lunch."]'::jsonb, 45, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/12-jan/Cabbage_Thoran_Poriyal_Recipe_South_Indian_Style_Sabzi-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1007.Cabbage_Thoran_Poriyal_Recipe_South_Indian_Style_Sabzi-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Beans Matki Bhaji Recipe - Green Beans Moth Beans Sabzi', 'beans-matki-bhaji-recipe-green-beans-moth-beans-sabzi', 'Beans Matki Bhaji is a simple Maharashtrian style dry sabzi made using green beans and sprouted moth beans. it is made with a simple set of spices like goda masala and mad chatpata along with amchur and jaggery. Traditionally kokum is used to add to the tanginess, so if you have kokum you can use that instead of amchur powder.', '["250 grams Green beans (French Beans) , chopped", "1 cup Moth Dal (Matki) , sprouted", "1 tablespoon Ghee", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1/2 teaspoon Asafoetida (hing)", "1 tablespoon Amchur (Dry Mango Powder) , or 2 Kokum (Malabar Tamarind)", "1 tablespoon Jaggery , grated", "1/2 teaspoon Red Chilli powder", "1 teaspoon Maharashtrian Goda Masala", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1/4 cup Fresh coconut , grated"]'::jsonb, ARRAY['salt', 'green beans (french beans)', 'mustard seeds', 'ghee', 'asafoetida (hing)', 'coconut', 'jaggery', 'red chilli powder', 'moth dal (matki) sprouted', 'amchur (dry mango powder) kokum (malabar tamarind)', 'curry leaves', 'cumin seeds (jeera)', 'maharashtrian goda masala', 'turmeric powder']::text[], '["To begin making Beans Matki Bhaji Recipe, first pressure cook the sprouted moth beans with 2 cups water for 4 to 45 whistles and turn off the heat.", "Allow the pressure to release naturally.Remove the moth beans from the pressure cooker and keep aside.In the same pressure cooker, add the green beans , sprinkle salt along with 2 tablespoons of water.", "Pressure cook for 2 whistles and turn off the heat.", "Release the pressure immediately to retain the bright green colour of the green beans.", "Keep this aside.Heat ghee in a pan over medium heat.", "Add the mustard seeds and cumin seeds, allow it to crackle.Add the asafoetida, curry leaves, turmeric powder, goda masala powder, amchur powder and red chilli powder.", "Saute for a few seconds.Add the cooked green beans, cooked moth beans, jaggery, salt to taste and if required (kokum at this stage if you are using).", "Give it a stir.Cover the pan and steam cook all the ingredients over low heat for about 3 minutes and turn off the heat.Stir in the grated coconut at this stage and give it a taste.", "Adjust the salt and spices accordingly.Once done, transfer the\u00a0Beans Matki Bhaji into a serving bowl and serve hot.Serve Beans Matki Sabzi along with hot steamed rice and\u00a0Maharashtrian Kadhi\u00a0for a weekday lunch or dinner."]'::jsonb, 50, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Beans_Matki_Bhaji_Recipe_Matki_Chi_Usal__2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1008.Beans_Matki_Bhaji_Recipe_Matki_Chi_Usal__2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tamatar Pyaz Ki Sabzi Recipe -Tomato Onion Sabzi', 'tamatar-pyaz-ki-sabzi-recipe-tomato-onion-sabzi', 'Tomatoes and Onions are staple vegetables that every home cook keeps in their kitchen. Tomatoes and Onions provide the base ingredient for a gravy or even a chutney that can be whipped up in no time. Keeping that in mind, here is a simple Tomato and Onion dish that most of us make to go with Rotis or even eat along with hot rice.', '["4 Tomatoes , quartered", "1 Onion , thinly sliced", "2 Green Chillies , slit", "4 cloves Garlic", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "Salt , to taste", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1/2 teaspoon Mustard oil", "1 Bay leaves (tej patta) , torn into half", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)"]'::jsonb, ARRAY['tomatoes', 'onion', 'reen chillies', 's garlic', 'turmeric powder', 'haldi', 'red chilli powder', 'salt', 'mustard seeds', 'rai/ kadugu', 'curry leaves', 'mustard oil', 'bay leaves', 'tej patta', 'laung', 'cinnamon stick', 'dalchini']::text[], '["To begin making the Tamatar Pyaz Ki Sabzi, first prep all the ingredients and keep them ready.", "Heat oil in a pressure cooker over medium heat; add the mustard seeds and allow it to crackle.Once it crackles, add the curry leaves, bay leaves, cloves, cinnamon stick and saute for a few seconds.Add the onion, green chillies and garlic.", "Saute the onions until they become slightly soft.Once soft, add the tomatoes, turmeric powder, red chilli powder and salt to taste.Add just a little water - about 2 to 3 tablespoons and cover the pressure cooker.", "Cook for 2 whistles and turn off the heat.Once the pressure released, check the salt and spices in the\u00a0Tamatar Pyaz Ki Sabzi and adjust to suit your taste.Serve the Tamatar Pyaz Ki Sabzi along with\u00a0Aloo Bhindi Sabzi,\u00a0Phulka,\u00a0Gujarati Kadhi\u00a0for a delicious\u00a0Sunday\u00a0lunch."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Tamatar_Sabzi_Tomato_Sabzi_recipe_healthy_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1009.Tamatar_Sabzi_Tomato_Sabzi_recipe_healthy_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Khatta Meetha Tamatar Sabzi Recipe - A Chutney Style Dry Sabzi', 'khatta-meetha-tamatar-sabzi-recipe-a-chutney-style-dry-sabzi', 'The Khatta-Meetha Tamatar Sabzi is a sweet and tangy sukhi sabzi as the name suggests. The tomatoes are cooked until completely mushy and given a ''chonkh''- tadka of the five spice mix called ''panch phoran masala'' which includes mustard seeds, cumin seeds, fenugreek seeds, onion seeds and fennel seeds.  This spice mix gives the sabzi a deep flavour, making all the difference.', '["1 tablespoon Mustard oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 Fennel seeds (Saunf)", "1/2 Cumin seeds (Jeera)", "1/4 Kalonji (Onion Nigella Seeds)", "1/4 Methi Seeds (Fenugreek Seeds)", "1 inch Ginger , finely chopped", "6 cloves Garlic , finely chopped", "2 Green Chillies , finely chopped", "1 Onion , finely chopped", "4 Tomatoes , finely chopped", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Garam masala powder", "1 teaspoon Red Chilli powder", "2 teaspoons Jaggery", "1 tablespoon Coriander (Dhania) Leaves", "1 tablespoon Mint Leaves (Pudina)"]'::jsonb, ARRAY['tomato', 'cumin powder (jeera)', 'kalonji (onion nigella seeds)', 'ginger', 'mustard oil', 'mustard seeds', 'fennel seeds (saunf)', 'amchur (dry mango powder)', 'coriander (dhania) leaves', 'jaggery', 'red chilli powder', 'cloves garlic', 'onion', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'mint leaves (pudina)', 'green chillies', 'garam masala powder']::text[], '["To begin making the Khatta Meetha Tamatar Sabzi, heat the mustard oil in a kadai on high heat.Once it reaches smoking point, reduce the flame, now add the mustard seeds, fennel seeds, cumin seeds, onion seeds and fenugreek seeds.When these seeds begin to sizzle, quickly add the ginger, garlic and green chilli and give it a good stir.When the garlic turns brown in colour, add the onions and saute for a couple of minutes.Once the onions are translucent and cooked,add tomatoes, cover the pan and cook for 5-7 minutes or until the tomatoes turn soft and mushy.", "You can use a potato masher or the back of the ladle to mash the tomatoes once they turn soft.Open the lid and add all the dry masalas to the tamatar Sabzi, amchur powder, cumin powder, garam masala powder\u00a0and red chilli powder.", "Mix well to combine.", "Finally add the jaggery and sprinkle some water, add in the coriander and mint leaves and give it a good mix.Serve this\u00a0Khatta Meetha Tamatar Sabzi along with\u00a0Puri Recipe (Puffed Fried Indian Bread)\u00a0and\u00a0Palak Raita Recipe (Spinach Yogurt Salad)\u00a0for a simple weeknight dinner."]'::jsonb, 25, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sneha-archanaskitchen.com/KhattaMeetha_Tamaatar_Sabzi__Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1010.KhattaMeetha_Tamaatar_Sabzi__Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dhaba Style Dal Palak Recipe', 'dhaba-style-dal-palak-recipe', 'The Dhaba Style Dal Palak is a perfect one dish recipe that will help you cook a wholesome nutritious dish fast and easily without spending much time in the kitchen during the hot summer days. Dal palak is very famous in north Indian recipe and a speciality of the road side dhabas too.', '["1 cup Arhar dal (Split Toor Dal) , washed", "2 cups Spinach Leaves (Palak) , finely chopped", "1 tablespoon Oil", "1 Onion , finely chopped", "1 Tomato , finely chopped", "2 Green Chillies , slit", "2 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "1/2 teaspoon Garam masala powder", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 Lemon , juice extracted", "1 tablespoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "2 cloves Garlic , sliced thin", "2 Dry Red Chillies"]'::jsonb, ARRAY['tomato', 'green chillies', 'salt', 'arhar dal (split toor dal)', 'ginger', 'ghee', 'cloves garlic', 'dry red chillies', 'onion', 'lemon', 'cumin seeds (jeera)', 'turmeric powder', 'spinach leaves (palak)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Dhaba Style Dal Palak,\u00a0add the chopped spinach along with 2 tablespoon of water and pressure cook for one whistle and turn off the heat.", "Release the pressure immediately to keep the fresh green colour of spinach.", "Keep the spinach aside.Heat oil in the pressure cooker; add the cumin seeds and allow it to crackle.", "Add the onion, ginger and garlic and saute until the onions turn soft.Once the onions have softened, add the tomatoes, turmeric powder, green chillies, garam masala powder and saute until the tomatoes becomes just a little soft.At this stage add the washed toor dal, salt to taste, 2-1/2 cups of water and cover the pressure cooker.", "Pressure cook for\u00a0about 4 to 5 whistles and turn off the heat.Allow the pressure to release naturally.", "Once done, open the cooker and add the cooked spinach/ palak to the dal.", "Give it a brisk boil and turn off the heat.", "Check the salt and adjust to taste accordingly.", "Transfer the Dhaba Style Dal Palak to a serving bowl.For the tadka, heat\u00a0ghee in a tadka pan, add cumin seeds, red chillies and garlic.", "Saute until they crackle and the garlic turns golden.", "Add this tadka to the Dhaba Style Dal Palak and give it a stir.Finally squeeze in the lemon juice and serve hot.Serve Dhaba Style Dal Palak with\u00a0Steamed Rice\u00a0or\u00a0phulkas\u00a0and\u00a0Sindhi Karela Bhaji\u00a0for lunch or dinner."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Dhaba_Style_Dal_Palak_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1011.Dhaba_Style_Dal_Palak_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Appalam Vatha Kuzhambu Recipe - Papad In Tamarind Gravy', 'appalam-vatha-kuzhambu-recipe-papad-in-tamarind-gravy', 'The Appalam Vatha Kuzhambu is a classic south indian preparation which has delicate flavours from the papad and the onions along with sambar powder simmered to make a spicy and tangy curry.  You can use any papad of your choice, however the ulundu appalam or the urad dal papad tastes best in this vathal kuzhambu.', '["1 tablespoon Gingelly oil", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "Asafoetida (hing) , a pinch", "3 Dry Red Chillies", "1/2 cup Pearl onions (Sambar Onions) , halved", "1 sprig Curry leaves", "3 Urad dal papad , broken in to quarters", "1 cup Tamarind Water", "1 teaspoon Sambar Powder", "1 tablespoon Jaggery", "1/4 teaspoon Turmeric powder (Haldi)", "3 cups Water", "Salt , as needed"]'::jsonb, ARRAY['gingelly oil', 'mustard seeds', 'rai/ kadugu', 'methi seeds', 'fenugreek seeds', 'asafoetida', 'hing', 'dry red chillies', 'pearl onions', 'sambar onions', 'curry leaves', 'urad dal papad', 'tamarind water', 'sambar powder', 'jaggery', 'turmeric powder', 'haldi', 's water', 'salt']::text[], '["To begin making the Appalam Vatha Kuzhambu recipe, prepare all the ingredients and keep them ready.Heat oil in a preheated pan over medium heat.", "Add\u00a0mustard seeds, fenugreek seeds, curry leaves and dried red chilies.", "Allow it to crackle.Add the onions and saute until the onions have softened and lightly golden.", "Once the onions have softened, add the tamarind water, turmeric powder, sambar powder, jaggery and appalam.Add 3 cups of water, salt to taste and simmer the appalam vatha kuzhambu,\u00a0until the kuzhambu has thickened and the appalam has soaked and cooked through as well.", "The Appalam Vatha Kuzhambu will have a gravy like consistency with the starch from the appalam giving it this texture.", "Adjust the consistency of the kuzhambu by adding water and also check the salt and spices and adjust to taste accordinglyServe the Appalam Vatha Kuzhambu along with hot\u00a0Steamed Rice,\u00a0Bean Paruppu Usili\u00a0and\u00a0Elai Vadam\u00a0for simple and delicious weekend lunch."]'::jsonb, 25, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Appalam_Vatha_Kuzhambun_recipe_-_South_Indian_Papad_ki_Sabzi_8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1012.Appalam_Vatha_Kuzhambun_recipe_-_South_Indian_Papad_ki_Sabzi_8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Green Beans Paruppu Usili Recipe - Iyengar Style', 'green-beans-paruppu-usili-recipe-iyengar-style', 'Green Beans Paruppu Usili is a wholesome and high protein side dish which is served along with a mor kuzhambu or vatha kuzhambu. Toor Dal is soaked and ground along with red chillies, turmeric and salt and then steamed to make dal cakes also known as paruppu idli. Once the dal is steamed, it is crumbled and tossed along with asafoetida, curry leaves and steamed vegetables.', '["200 grams Green beans (French Beans) , finelt chopped", "1 tablespoon Gingelly oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "2 sprig Curry leaves", "1/2 teaspoon Asafoetida (hing)", "1 cup Arhar dal (Split Toor Dal)", "4 Dry Red Chillies", "Salt , to taste", "1/2 teaspoon Turmeric powder (Haldi)"]'::jsonb, ARRAY['s green beans', 'french beans', 'gingelly oil', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'curry leaves', 'asafoetida', 'hing', 'arhar dal', 'split toor dal', 'dry red chillies', 'salt', 'turmeric powder', 'haldi']::text[], '["To begin making the Green Beans Paruppu Usili Recipe, soak the toor dal in water for about 1 hour.Once the dal is soaked until soft; drain the excess water.Into a food processor/mixer, add in the toor dal, turmeric powder and dried red chillies and blend to make a coarse mixture.", "You want the Paruppu Usili to have a coarse texture when steamed.Grease the steamer plates or idli plates with a oil and spoon the ground paruppu usili mixture into the steamer plates.Place the filled steamer plates into the steamer and steam for 10 minutes on high heat.", "Once steamed, turn off the heat and keep aside and allow it to cool.", "Once the cooled, transfer to a large mixing bowl and crumble the steamed paruppu - this mixture is called the paruppu usili (crumbled dal).", "Keep this aside.The next step is to cook the green beans.", "In a pressure cooker, add the chopped green beans along with 2 tablespoons of water.", "Sprinkle in a little salt.", "Pressure cook the green beans for 2 whistles on high heat, turn off the heat and run the pressure cooker under water to release pressure immediately.", "The beans will be cooked perfectly without loss of colour and nutrition.", "Place a wok or kadai on medium heat and add a teaspoon of oil.", "Once the oil is hot, add mustard seeds and urad dal and allow it to crackle and the dal to turn golden brown.After the seeds have crackled, add asafoetida, the curry leaves and the steamed paruppu usili and\u00a0mix thoroughly.", "Saute the dal in the oil for a good 3 to 4 minutes until it gets a perfect crumbly texture.", "Once you have a good texture, stir in the green beans and turn off the heat.", "Check the salt and adjust to taste accordingly.Serve\u00a0Green Beans Paruppu Usili\u00a0along with\u00a0Sundakkai / Manathakkali Kai Vathal Kuzhambu Recipe\u00a0and\u00a0Steamed Rice\u00a0for a weekday meal."]'::jsonb, 50, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Beans_Paruppu_Usili_Recipe_Iyengar_Style_6-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1013.Beans_Paruppu_Usili_Recipe_Iyengar_Style_6-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pachai Payaru Payasam Recipe - Green Moong Dal Payasam', 'pachai-payaru-payasam-recipe-green-moong-dal-payasam', 'Pachai Payaru Payasam Recipe is a Green Moong Dal Payasam, where the green moong dal is boiled and dunked in creamy smooth coconut milk, then flavoured with intense cardamom powder, sweetened with rustic and earthy jaggery and finally served with cashew nuts fried in ghee !', '["1-1/2 cups Green Moong Dal (Whole)", "1/2 cup Jaggery", "1/4 cup Water", "1 teaspoon Cardamom Powder (Elaichi)", "12 Cashew nuts , broken", "1 tablespoon Ghee", "1 cup Coconut milk", "Saffron strands , a few"]'::jsonb, ARRAY['ghee', 'saffron strands', 'jaggery', 'water', 'cardamom powder (elaichi)', 'cashews', 'coconut milk', 'green moong dal']::text[], '["To begin making the Pachai Payaru Payasam Recipe wash and soak the green moong dal in 3 cups of water overnight or for a minimum of 3 - 4 hours.", "After 4 hours, transfer the green moong dal along with the water to a pressure cooker.Pressure cook for about 4-5 whistles, and turn off the heat.", "Allow the pressure to release naturally.", "Once the pressure is released naturally set the green moong dal aside.", "Heat a sauce pan on medium flame, combine the jaggery with water, allow the jaggery to melt and bring this syrup to a brisk boil.", "Reduce the flame, add the cooked green moong dal and cardamom powder.", "Turn off the flame, add the coconut milk and mix well.", "Transfer the\u00a0Pachai Payaru Payasam to a serving bowl, stir in the saffron strands and set aside.", "Heat a small tadka pan on medium flame, add ghee and fry the cashew nuts until golden brown and crisp.Turn off the flame and pour it over the\u00a0Pachai Payaru Payasam.", "Serve\u00a0Pachai Payaru Payasam Recipe along with a South Indian meal that consists of\u00a0Steamed Rice,\u00a0Chettinad Style Poondu Rasam Recipe - Garlic Rasam Recipe,\u00a0Beetroot Poriyal Recipe (Stir Fried Beetroot),\u00a0Cabbage Poricha Kootu Recipe - South Indian Cabbage Dal,\u00a0Puri Recipe."]'::jsonb, 260, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Green_Moong_Dal_Payasam_-_Pacha_Payaru_Payasam_8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1014.Green_Moong_Dal_Payasam_-_Pacha_Payaru_Payasam_8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Jowar Atta Roti Recipe - Sorghum Wheat Phulka Recipe', 'jowar-atta-roti-recipe-sorghum-wheat-phulka-recipe', 'Jowar Atta Roti Recipe is a must try Indian bread that you can serve along with Indian curries and sabzi. To make the Jowar Atta Roti equal portion of jowar flour and wheat flour is mixed together with some salt, water and oil. Adding atta helps to roll the rotis easily. These rotis are best enjoyed hot fresh out of the tawa.', '["1/2 cup Jowar Flour (Sorghum)", "1 cup Whole Wheat Flour", "Salt , to taste", "1 teaspoon Black pepper powder", "1 tablespoon Oil", "Water , to knead, as required"]'::jsonb, ARRAY['salt', 'wheat flour', 'water knead', 'jowar flour (sorghum)', 'black pepper powder', 'sunflower oil']::text[], '["To begin making the Jowar Atta Roti/ Phulka Recipe, keep all the ingredients ready.", "Into a large mixing bowl, add jowar flour, whole wheat flour and salt to taste.", "Add little water at a time to knead to make a smooth dough.", "Drizzle 1 teaspoon of oil towards the end and knead until the dough comes away from the sides of the pan and is smooth.Divide the dough into lemon size portions.", "Take a portion of the dough and dust it in wheat flour.", "Roll the dough into a 5 to 6 inch diameter circle.Place the rolled out dough on a preheated skillet and cook for a few seconds until small bubbles appear on the surface.Flip and cook the roti for a few seconds and place it over the open flame.", "Cook till Jowar roti puffs up.", "Keep flipping and cooking the Jowar Atta Roti till brown spots appear on both sides and the roti is cooked through.", "Once done transfer the Jowar Atta Roti onto a serving plate.", "Drizzle ghee around the roti and serve immediately.", "Serve the\u00a0Jowar Atta Roti Recipe\u00a0along with\u00a0Panchmel Dal,\u00a0Aloo Baingan Ki Sabzi\u00a0and\u00a0Satvik Carrot Sprout Salad\u00a0 to make it a complete meal."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Jowar_Atta_Roti_Recipe_Millet_diabetic_meal_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1015.Jowar_Atta_Roti_Recipe_Millet_diabetic_meal_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vaghareli Rotli Recipe - Roti Ka Poha', 'vaghareli-rotli-recipe-roti-ka-poha', 'Vaghareli Rotli or Roti Ka Poha is a crispy masala roti that is seasoned with asafoetida, red chillies and curry leaves, that makes a perfect breakfast or a tea time snack. If ever you have left over Phulka''s, Puris, Chapati, Tawa Paratha or even thepla, tear them all up and toss it on the pan until lightly crisp along with a tadka.', '["2 cups Leftover roti , (phulka or chapati) chopped into half inch squares approximately (about 10 Rotlis)", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves , roughly torn", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Oil", "Salt , to taste"]'::jsonb, ARRAY['s leftover roti', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'curry leaves', 'red chilli powder', 'turmeric powder', 'haldi', 'asafoetida', 'hing', 'oil', 'salt']::text[], '["To begin making the Vaghareli Rotli, in a large bowl, combine the chopped rotlis.Heat oil in a pan on medium high; add mustard seeds, cumin seeds and allow them to crackle.", "Add the turmeric powder, curry leaves, red chilli powder and asafoetida.", "Stir for a few secondsStir in the torn roti until well combined with the seasoning.", "Turn the heat to low and roast the vaghareli rotli mixture until slightly crisp, stirring occasionally.Once the desired texture is achieved turn off the heat and serve the Vaghareli Rotli immediately.Serve the Vaghareli Rotli Recipe (Roti Ka Poha)\u00a0along with a hot cup of Adrak Chai for breakfast or as a tea time snack."]'::jsonb, 30, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Vaghareli_Rotli_Recipe_-_Roti_Ka_Poha_6_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1016.Vaghareli_Rotli_Recipe_-_Roti_Ka_Poha_6_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer and Green Peas Paratha Recipe', 'paneer-and-green-peas-paratha-recipe', 'Paneer and Green Peas Paratha Recipe is a high protein rich stuffed paratha recipe. Stuffed paratha is one of the famous breakfast dishes in North India. It is very important to incorporate good nutrition into your paratha as to give you a great start to the day. Peas and paneer are sauteed in a pan with everyday Indian spices and then filled into a whole wheat flour dough to make tasty parathas.', '["1/2 cup Green peas (Matar) , ground into a paste", "1 cup Paneer (Homemade Cottage Cheese) , crumbled", "1 inch Ginger , chopped", "1 Green Chilli , chopped", "1 teaspoon Turmeric powder (Haldi)", "2 teaspoon Red Chilli powder", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "1 cup Whole Wheat Flour", "Salt , to taste", "Oil , for kneading", "Lukewarm Water , for kneading"]'::jsonb, ARRAY['salt', 'wheat flour', 'ginger', 'green chilli', 'amchur (dry mango powder)', 'paneer', 'red chilli powder', 'water', 'green peas (matar) ground paste', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making\u00a0Paneer and Green Peas Paratha prep all the\u00a0 ingredients ready and keep them handy."]'::jsonb, 65, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Paneer_and_Green_Peas_Paratha_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1017.Paneer_and_Green_Peas_Paratha_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Railway Mutton Curry Recipe', 'railway-mutton-curry-recipe', 'Railway Mutton Curry was developed by the chefs of the Indian Railways during the British Raj keeping in mind the delicate palates of the British people. It was first introduced on the Frontier Mail (Golden Temple Mail) run by the Western Railway during pre-independence era. This milder version of the classic mutton curry was not too spicy yet an amazing fusion dish blending the taste of both Indian and English spices. The Railway Mutton Curry was served with rice, bread or dinner rolls.', '["500 grams Mutton", "1 teaspoon Ginger Garlic Paste", "1 teaspoon Mustard oil", "1 tablespoon Curd (Dahi / Yogurt) , or lemon juice", "1/2 teaspoon Kashmiri Red Chilli Powder", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1/2 teaspoon Fennel seeds (Saunf)", "1/2 teaspoon Coriander (Dhania) Seeds", "1/2 teaspoon Cumin seeds (Jeera)", "5 Whole Black Peppercorns", "1 Onion , thinly sliced", "2 Potato (Aloo) , each halved", "2 Tomato , pureed", "1 teaspoon Ginger Garlic Paste", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Kashmiri Red Chilli Powder", "2 Green Chilli , slit lengthwise", "1 Black cardamom (Badi Elaichi)", "2 Cardamom (Elaichi) Pods/Seeds", "1/2 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "1 Bay leaf (tej patta)", "1 Mace (Javitri)", "1/4 Nutmeg", "Lukewarm Water", "4 tablespoons Mustard oil", "Salt , to taste", "1/4 teaspoon Garam masala powder", "1 teaspoon Ghee"]'::jsonb, ARRAY['tomato', 'kashmiri red chilli powder', 'nutmeg', 'black peppercorns', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'salt', 'black cardamom (badi elaichi)', 'green chilli', 'mustard oil', 'cardamom (elaichi) podsseeds', 'mace (javitri)', 'garam masala powder', 'water', 'curd lemon', 'bay leaf (tej patta)', 'fennel seeds (saunf)', 'ghee', 'potato (aloo)', 'ginger garlic paste', 'cinnamon stick (dalchini)', 'mutton', 'cloves (laung)']::text[], '["To begin making the Railway Mutton Curry, firstly marinate the Mutton with ginger garlic paste, yogurt, turmeric powder, mustard oil, red chilli powder, salt for minimum 3 hours or overnight in the refrigerator.Dry roast fennel seeds, black peppercorn, coriander and cumin seeds and grind them to a fine powder.Peel the potatoes and cut them into half.", "Fry the potatoes.", "Don\u2019t make them brown and fry till the color becomes light golden brown.", "Remove and keep them aside.Heat oil in the Pressure cooker and once the oil is heated, put the whole Garam masala.", "Let them fry and sizzle for couple of minutes.Now add the ginger and garlic pastes and saut\u00e9 till their raw smell is gone.Add the sliced onions along with a pinch of salt and saut\u00e9 till they turn brown.Now add the tomato puree, green chilli, turmeric powder, red chili powder, fennel, coriander, cumin, black peppercorn powder and saute till oil leaves the sides.Add the mutton pieces.", "Increase the heat to a high and stir continuously to avoid sticking to the bottom.", "Now reduce the heat to a medium and continue cooking the meat without the lid.", "The meat will release juices and you can see a thin layer of oil on top of the pieces.Once it gets to this point, add the fried potatoes and water.", "Close the lid and pressure cook for 3 to 4 whistle on high heat and then reduce the heat and cook on a low flame for 5 minutes.Once done, switch off the heat and let it sit for sometime till the pressure dies down.", "After opening the lid add the coconut milk and give everything a good stir.", "Add a spoon of ghee and 1/2 teaspoon of powdered garam masala.Close the lid and let the flours seep into the meat properly for 10 to 12 minutes and serve hot.Serve Railway Mutton Curry along with\u00a0Jeera Rice/Phulka\u00a0and\u00a0Burani Raita\u00a0for a weekday lunch or dinner."]'::jsonb, 40, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/alaka_jena/Railway_Mutton_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1018.Railway_Mutton_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Nellikai Rasam Recipe - Whole Gooseberry Rasam', 'nellikai-rasam-recipe-whole-gooseberry-rasam', 'Nellikai Rasam Recipe is a absolutely delicious rasam made from Whole Gooseberries which is packed with nutrition and taste and most essentially an immunity boosting drink.', '["6 Amla (Nellikai/ Gooseberry)", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1/4 cup Arhar dal (Split Toor Dal) , cooked", "1 tablespoon Ghee", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Asafoetida (hing) , a pinch", "1 sprig Curry leaves", "1 inch Ginger , finely chopped", "4 cloves Garlic , mashed", "1 Green Chilli , slit", "4 Tomatoes , pureed", "1/2 cup Tamarind Water", "1 tablespoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Kashmiri Red Chilli Powder", "1 teaspoon Sugar", "Salt , to taste", "6 sprig Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['amla', 'nellikai/ gooseberry', 'turmeric powder', 'haldi', 'salt', 'arhar dal', 'split toor dal', 'ghee', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing', 'curry leaves', 'ginger', 's garlic', 'reen chilli', 'tomatoes', 'tamarind water', 'coriander powder', 'dhania', 'cumin powder', 'jeera', 'kashmiri red chilli powder', 'sugar', 'coriander']::text[], '["To begin making Nellikai Rasam, into the pressure cooker, add the whole alma/ nellikai along with 1/2 cup of water, turmeric powder and salt.", "Pressure cook for 5 to 6 whistles and turn off the heat.", "Allow the pressure to release naturally.Cook the toor dal in a pressure cooker along with 1 cup of water for 4 whistles and turn off the heat.", "Allow the pressure to release naturally.", "Once done, open the cooker and mash the dal well.", "Heat ghee in a large saucepan over medium heat; add the mustard seeds and allow it to crackle.", "Add the asafoetida ginger, garlic, and curry leaves and saute for a few seconds.Add the green chillies, tomato puree, tamarind water, cooked alma, cooked toor dal, coriander powder, red chilli powder, turmeric powder, salt and sugar to taste.Add 1 cup of water and bring the rasam to a brisk boil for 4 to 5 minutes until you notice that it is frothing around the edges.", "Once boiled enough, check the taste of the Nellikai Rasam and adjust the salt and spices accordingly.Turn off the heat and transfer the Nellikai Rasam to a serving bowl and serve hot.Serve\u00a0Nellikai Rasam along with Steamed Rice and\u00a0Elai Vadam,\u00a0Kovakkai Poriyal Recipe\u00a0and\u00a0Spiced Buttermilk\u00a0for a weekday lunch."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Nellikai_Rasam_Recipe_Amla_rasam_Immunity_Booster_11_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1019.Nellikai_Rasam_Recipe_Amla_rasam_Immunity_Booster_11_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Khatti Meethi Lauki Dal Recipe - Sweet & Spicy Bottle Gourd Dal', 'khatti-meethi-lauki-dal-recipe-sweet-spicy-bottle-gourd-dal', 'Khatti Meethi Lauki Dal Recipe is a tangy and sweet Bottle Gourd curry which is packed with flavours from cinnamon and ginger and given that zing from freshly squeezed lemon juice and coriander leaves. It is a super simple one-pot recipe made in a pressure cooker and perfect for those days when you want to keep things simple.', '["1 teaspoon Oil , for cooking", "1/2 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves , finely chopped", "1 inch Cinnamon Stick (Dalchini) , broken", "1 Bay leaf (tej patta) , torn into half", "1 inch Ginger , finely chopped", "1 Tomato , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 cup Arhar dal (Split Toor Dal) , washed well in water", "2 cups Bottle gourd (lauki) , peeled and chopped", "Salt , to taste", "1 teaspoon Jaggery , crushed", "1 Lemon , juice extracted", "4 sprig Coriander (Dhania) Leaves , finely chopped", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Jaggery , powdered", "1 teaspoon Lemon juice", "Coriander (Dhania) Leaves , a small bunch finely chopped", "Oil , for cooking"]'::jsonb, ARRAY['tomato', 'salt', 'coriander (dhania)', 'ginger', 'sunflower oil', 'arhar dal (split toor dal)', 'amchur (dry mango powder)', 'bay leaf (tej patta)', 'jaggery', 'red chilli powder', 'curry leaves', 'coriander (dhania) leaves', 'cinnamon stick (dalchini)', 'bottle gourd (lauki)', 'lemon', 'turmeric powder', 'cumin (jeera) seeds']::text[], '["We begin making the Khatti Meethi Lauki Dal Recipe, prepare all the ingredients and keep them ready.Preheat oil in a pressure cooker over medium heat.", "Add the cumin seeds and allow it to crackle.Add the cinnamon stick, bay leaf, ginger, tomatoes and curry leaves.", "Saute for about minute until the tomatoes are slightly mushy.Add the turmeric powder, red chilli powder, salt, washed toor dal, chopped bottle gourd, salt to taste, jaggery and 2-1/2 cups of water.Cover the pressure cooker and cook the\u00a0Khatti Meethi Lauki Dal for 3 whistles.", "After 3 whistles, turn the heat to low and simmer for 3 minutes and turn off the heat.Allow the pressure to release naturally.", "Once the pressure releases, check the taste, add salt if required and adjust the chilli and jaggery as well accordingly.When you are ready to serve, give it a brisk boil just and squeeze in the juice from one lemon and stir in the chopped coriander leaves.Transfer the Khatti Meethi Lauki Dal to a serving bowl.", "Serve the\u00a0Khatti Meethi Lauki Dal Recipe\u00a0along with\u00a0Red Cabbage Poriyal\u00a0and\u00a0Methi Thepla\u00a0for a wholesome lunch or dinner."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Khatti_Meethi_Lauki_Dal_Recipe_-_Sweet__Spicy_Bottle_Gourd_Dal_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1020.Khatti_Meethi_Lauki_Dal_Recipe_-_Sweet__Spicy_Bottle_Gourd_Dal_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bhaat Ka Thepla Recipe - Spiced Rice Paratha', 'bhaat-ka-thepla-recipe-spiced-rice-paratha', 'Bhaat Na Thepla’s are flat breads made from leftover rice; that is combined with gram flour, asafoetida and vegetables to make a wholesome nutritious one dish dinner.', '["2 cups Cooked rice , mashed", "1/4 cup Gram flour (besan)", "1/2 teaspoon Asafoetida (hing)", "1/2 teaspoon Turmeric powder (Haldi)", "2 Green Chillies , finely chopped", "1/4 cup Carrot (Gajjar) , finely grated", "1 Onion , finely chopped", "Coriander (Dhania) Leaves , small bunch, finely chopped", "Salt , to taste", "Ghee , to cook"]'::jsonb, ARRAY['s cooked rice', 'gram flour', 'besan', 'asafoetida', 'hing', 'turmeric powder', 'haldi', 'reen chillies', 'carrot', 'gajjar', 'onion', 'coriander', 'dhania', 'salt', 'ghee']::text[], '["To begin making the bhaat ka thepla, in a large mixing bowl combine all the ingredients -\u00a0mashed rice,\u00a0gram flour,\u00a0asafoetida powder,\u00a0turmeric powder,\u00a0green chillies,\u00a0cabbage,\u00a0onion,\u00a0coriander leaves, salt.", "Combine the dough until it all comes together.", "Divide the mixture into equal portions.Preheat the skillet on medium heat.", "Keep water in a separate bowl to wet your fingers and a wet the muslin cloth dipped in water squeezing out any excess water.Spread the cloth on a smooth countertop.", "Take a portion of the mixture and pat it on the wet cloth to about 4 inches in diameter.", "Keep the thepla to medium thickness as you don''t want it to be breaking while flipping it on the tawa.", "Carefully lift the cloth along with the patted mixture and flip the patted rice thepla over on the skillet.", "Drizzle a teaspoon of oil around the patted rice and cook on medium heat.After about 3 minutes, you will be able to flip the Bhaat ka Thepla over to the other side.", "Allow each side to cook on medium heat for about 3-4 minutes, until the Theplas are slightly crisp and browned.", "Remove from heat and place on a serving platter.Continue the same procedure with the other portions.Serve the Bhaat Ka Thepla\u00a0along with freshly made\u00a0Tamatar ki Chutney."]'::jsonb, 45, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Bhaat_Ka_Thepla_Chawal_Ka_Paratha_Rice_Paratha_Recipe_10_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1021.Bhaat_Ka_Thepla_Chawal_Ka_Paratha_Rice_Paratha_Recipe_10_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('High Protein Moong Dal Cheela Recipe With Stuffed Paneer', 'high-protein-moong-dal-cheela-recipe-with-stuffed-paneer', 'The High Protein Moong Dal Cheela Recipe With Stuffed Paneer recipe makes a delicious appetizer for the parties, a breakfast or even as a school lunch box. The cheela''s are made with yellow moong dal and filled with cottage cheese/paneer is rich in proteins and vitamins making it a healthy snack or meal for both adults and kids.', '["Ingredients for the batter", "1 cup Yellow Moong Dal (Split)", "1/2 cup White Urad Dal (Whole)", "1 inch Ginger , finely chopped", "2 Green Chillies , finely chopped", "Salt , to taste", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Turmeric powder (Haldi)", "Coriander (Dhania) Leaves , finely chopped", "Ingredients for the Filling", "1 cup Paneer (Homemade Cottage Cheese) , Grated", "1/2 cup Onion , finely chopped", "1/2 cup Tomatoes , finely chopped", "1 Green Chilli , finely chopped", "1 teaspoon Chaat Masala Powder , for seasoning", "Salt , to taste", "Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['ingredients for the batter', 'yellow moong dal', 'split', 'white urad dal', 'whole', 'ginger', 'reen chillies', 'salt', 'cumin seeds', 'jeera', 'turmeric powder', 'haldi', 'coriander', 'dhania', 'ingredients for the filling', 'paneer', 'homemade cottage cheese', 'onion', 'tomatoes', 'reen chilli', 'chaat masala powder']::text[], '["To begin making the Moong Dal Cheela Recipe, soak the\u00a0 moong dal and urad dal together for at least 6 hours/overnight.Grind moong dal along with green chilies and ginger into a smooth batter adding just enough water to grind the dal.", "The consistency of the batter should be that of a pancake (do not add too much water).Combine all the ingredients for the paneer filling mixture.", "Keep aside.Heat a skillet and pour a ladle full of moong dal cheela batter in circular fashion from center going outwards making a diameter approximately 6 inch.Drizzle oil/ghee around the spread cheela batter.", "Allow the moong dal cheela to cook to medium heat.", "You will notice brown spots appearing inside and around the sides.", "Let it get crisp and then flip and cook the cheela for a about a minute.Remove from the moong dal cheela from the skillet, place it on a platter with the bottom side facing down.", "Fill about scoop of paneer filling along center diameter of cheela and fold it lengthwise tightly.", "Cut the roll diagonally into 2 or three pieces \u00a0and sprinkle more chaat masala on the top.Serve Moong Dal Cheela along with\u00a0Tomato Onion Chutney\u00a0for Indian breakfast or pack it in kids snack box."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Moong_Dal_Cheela_Stuffed_With_Paneer_Recipe-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1022.Moong_Dal_Cheela_Stuffed_With_Paneer_Recipe-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Raw Papaya Mor Kootu Recipe - Ayurvedic No Onion No Garlic Recipe', 'raw-papaya-mor-kootu-recipe-ayurvedic-no-onion-no-garlic-recipe', 'The Raw Papaya Mor Kootu Recipe is a perfect blend of yogurt and coconut, spiced along with green chillies and curry leaves. Adding curry leaves to the mor kootu is a great way to consume this healthy herb. Did you know the fiber in the raw papaya cleans the body internally of toxins and helps with skin conditions like acne blemishes and pigmentation. Raw Papaya is also rich in Vitamin C, E & A, folate, it also gives only 39 calories per a 100 gram. Presence of antioxidants in raw papaya, burns your calorie down and extra fat deposits.', '["200 grams Raw papaya , peeled and diced", "1/2 cup Fresh coconut , grated", "2 sprigs Curry leaves", "2 Green Chillies", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Rice , soaked in warm water for 5 minutes", "1 teaspoon Whole Black Peppercorns", "1/2 cup Curd (Dahi / Yogurt)", "1 teaspoon Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves"]'::jsonb, ARRAY['coconut', 'rice water', 'mustard seeds', 'black peppercorns', 'curd', 'curry leaves', 'papaya', 'cumin seeds (jeera)', 'curry leaves', 'coconut oil', 'green chillies']::text[], '["To begin making the Raw Papaya Mor Kooru recipe,\u00a0 first prep all the ingredients and keep them handy.Add the raw papaya into the pressure cooker, along with 1/4 cup of water and salt.", "Pressure cook for two whistles and turn off the heat.", "Release the pressure immediately, by placing the cooker under cold water so the papaya does not get over cooked.Blend the coconut, cumin seeds, peppercorns, green chillies, rice and curry leaves using a little bit of warm water to make a smooth paste.Add the cooked raw papaya into a sauce pan, the coconut paste and yogurt.", "Stir in the salt to taste.", "Add a little water if you want to make the consistency little thinner.", "Place the saucepan on medium and simmer the raw papaya mor kootu for about 5 minutes until it comes together and turn off the heat.Heat a tadka pan with oil; add the mustard seeds and curry leaves.", "Allow it to crackle and pour it over the raw papaya mor kuzhambu.Once done, serve warm.Serve the Raw Papaya Mor Kootu along with\u00a0Phulkas,\u00a0Beetroot Poriyal\u00a0and\u00a0Pineapple Rasam Recipe\u00a0for a wholesome lunch."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/admin/Raw_Papaya_Mor_Kootu_Recipe__Ayurvedic_No_Onion_No_Garlic_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1023.Raw_Papaya_Mor_Kootu_Recipe__Ayurvedic_No_Onion_No_Garlic_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Varutharacha Mutton Curry Recipe', 'kerala-style-varutharacha-mutton-curry-recipe', 'Kerala Varutharacha Curry is ground masala added to the curry. Mutton curry made from ground masala along with coconut is a spicy, delicious curry that goes perfectly with appam, idiyappam, and rice. It’s peppery, spicy and delicious. With added freshly grated coconut, the spice is balanced out.', '["500 grams Mutton", "1/2 cup Shallots", "1/3 cup Tomatoes", "2 sprig Curry leaves", "1 Green Chilli", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Turmeric powder (Haldi)", "1 tablespoon Red Chilli powder", "Fresh coconut , few sliced pieces", "Salt , to taste", "1 tablespoon Coconut Oil", "1 tablespoon Coriander (Dhania) Seeds", "8 Dry Red Chillies", "8 cloves Garlic", "2 inch Ginger", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Fennel seeds (Saunf)", "1-1/2 teaspoon Whole Black Peppercorns", "1 inch Cinnamon Stick (Dalchini)", "3 Cloves (Laung)", "2 Cardamom Powder (Elaichi)", "1 sprig Curry leaves", "1/2 cup Fresh coconut , grated", "1/2 cup Shallots", "1 teaspoon Coconut Oil"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'green chilli', 'coconut', 'fennel seeds (saunf)', 'red chilli powder', 'cloves garlic', 'black peppercorns', 'curry leaves', 'coriander (dhania) seeds', 'dry red chillies', 'cumin seeds (jeera)', 'mutton', 'coconut oil', 'cinnamon stick (dalchini)', 'cardamom powder (elaichi)', 'turmeric powder', 'cloves (laung)']::text[], '["To prepare Kerala Varutharacha Mutton Curry Recipe, mash mutton pieces well.", "Add the mutton pieces into pressure cooker along with cumin seeds and little shallot slices, turmeric powder and salt.", "Add \u00bd cup water and pressure cook for 1 whistle.Now in a wok add 1 teaspoon coconut oil.", "Add shallots, ginger and garlic pieces and saut\u00e9 for 2 minutes.", "Remove it from the pan and keep aside.", "Add dried red chilies, coriander seeds, cumin seeds, fennel seeds, cinnamon, cloves, cardamom seeds, and roast.After add grated coconut and saut\u00e9 till spices are roasted well and coconut turns golden brown.", "Make sure not to burn the spices.", "Remove from the pan.Transfer shallots, ginger garlic mix, roasted spice-coconut mix into a blender.", "Add little water and grind into smooth paste.In a wok add coconut oil.", "Saute sliced shallots until translucent.", "Add the coconut slices.Add the cooked mutton pieces and roast for 5 minutes.Next add tomato slices and continue to cook.After some time add red chili powder, salt to taste and mix.Add the ground masala paste and cook until oil separates from the sides of the pan.Add the water in which mutton was cooked into the wok and bring it to boil.Sprinkle curry leaves.", "Check for seasoning.Once fully cooked turn off flame and serve Kerala Varutharacha Mutton Curry Recipe hot with steamed rice.Serve\u00a0Kerala Varutharacha Mutton Curry along with appam,\u00a0idiyappam\u00a0or\u00a0rice for a weekend lunch or dinner."]'::jsonb, 45, 'Kerala', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/Kerala_Varutharacha_Mutton_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1024.Kerala_Varutharacha_Mutton_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Puliyodharai / Puliyogare Recipe (Spicy Tamarind Rice) with Pulikachal', 'puliyodharai-puliyogare-recipe-spicy-tamarind-rice-with-pulikachal', 'Puliyodharai/ Puliyogare or Tamarind Rice is a tangy-spicy South Indian Rice variety, which is known for its long shelf life and great travel food. If you are going for picnic or long journey and need food that can stay fresh without being refrigerated, then Puliyogare is the right choice. But for me, I can relish this flavorful rice anytime of the week or year.', '["Main Ingredients", "2 cups Rice , cooked", "Sesame (Gingelly) Oil , or gingely oil as required", "Ingredients for Pulikachal (Puliyodharai / Puliyogare Spice Mix)", "2 teaspoons Tamarind Paste", "1/2 teaspoon Jaggery", "1/4 cup Raw Peanuts (Moongphali) , roasted", "Salt , as needed", "Water , as needed", "Ingredients To Roast and Grind For Pulikachal", "2 tablespoons Chana dal (Bengal Gram Dal)", "4 Dry Red Chilli", "3 teaspoons Methi Seeds (Fenugreek Seeds)", "1 teaspoon Whole Black Peppercorns", "1 tablespoon Mustard seeds (Rai/ Kadugu)", "3 Dry Red Chilli", "1 tablespoon Chana dal (Bengal Gram Dal)", "1/2 teaspoon Asafoetida (hing)", "1-1/2 teaspoon Turmeric powder (Haldi)", "8 Curry leaves", "5 tablespoon Sesame (Gingelly) Oil"]'::jsonb, ARRAY['main ingredients', 's rice', 'sesame', 'gingelly', 'ingredients for pulikachal', 'puliyodharai / puliyogare spice mix', 's tamarind paste', 'jaggery', 'raw peanuts', 'moongphali', 'salt', 'water', 'ingredients to roast and grind for pulikachal', 's chana dal', 'bengal gram dal', 'dry red chilli', 's methi seeds', 'fenugreek seeds', 'whole black peppercorns', 'mustard seeds', 'rai/ kadugu', 'chana dal', 'asafoetida', 'hing', 'turmeric powder', 'haldi', 'curry leaves']::text[], '["Method for Making Pulikachal-Soak the tamarind in water for at least one hour and extract the juice.", "Keep the juice asideTake all the ingredients listed under Roast and Grind and dry roast them until it turns golden brown.", "Cool them completely and grind to a fine powder in a mixer grinder.Heat oil in a heavy bottomed pan, add the mustard seeds, red chillies and allow it to crackle and roast for a few seconds.", "Add the tamarind extract, turmeric powder, salt, curry leaves and asafoetida.", "Add enough water to make it thin and allow it to boil for at-least 20 minutes or until the volume reduces to half.Once the volume has reduced to half, add the jaggery and the ground spice powder.", "Allow this mixture to boil for another 5 minutes or until the mixtures starts to thicken.Turn off the heat and cool the pulikachal.", "Add the roasted peanuts and keep aside.", "This this the\u00a0Pulikachal\u00a0mixture\u00a0to make the Tamarind Rice.You can store this mixture in the refrigerator for about a week and use it as and when required."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Puliyodharai_Recipe-0973.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1025.Puliyodharai_Recipe-0973.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Baingan Ki Lonje Recipe - Uttar Pradesh Style Brinjal Sabzi', 'baingan-ki-lonje-recipe-uttar-pradesh-style-brinjal-sabzi', 'Baingan Ki Lonje is a traditional recipe from the state of Uttar Pradesh. Baingan or eggplants are not preferred by many, however this unique recipe will let even the eggplant hater try this yummy dish. The eggplants are coated with a spicy and aromatic onion paste and then slow cooked to impart all its flavours into the dish. The secret lies in the freshly made spice mix that is added to the onion masala which is then coated over the eggplants.', '["500 grams Brinjal (Baingan / Eggplant)", "3 Onion , thinly sliced", "5 Cloves (Laung)", "1 tablespoon Ginger , grated", "2 teaspoons Sugar", "2 tablespoons Ghee", "2 teaspoons Lemon juice", "Salt , to taste", "Ingredients for the spice mix", "4 Dry Red Chillies", "1 Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "1 teaspoon Whole Black Peppercorns , crushed", "4 Cloves (Laung)"]'::jsonb, ARRAY['salt', 'ginger', 'ghee', 'brinjal (baingan eggsplant)', 'cardamom (elaichi) podsseeds', 'black peppercorns', 'sugar', 'dry red chillies', 'onion', 'lemon', 'cinnamon stick (dalchini)', 'cloves (laung)']::text[], '["To begin making Baingan Ki Lonje Recipe, wash and cut the eggplants into half lengthwise along with the stem and keep them immersed in a bowl of water to avoid the oxidation.In a shallow frying pan, dry roast the ingredients mentioned in the spice mix table and grind them into a fine powder using a mixer grinder and keep aside.Heat a tablespoon of ghee in a pan, add the sliced onions and saute until it turns translucent.Add the sugar and let the onions caramelize to light brown colour.", "This will take around 10 minutes.Now, grind this caramelized onions along with the grated ginger, salt and the spice mix to a fine paste using a mixer grinder.Drain the eggplants, apply a layer of this onion masala over the eggplants on the inner cut side and keep aside.Now, heat the remaining 1 tablespoon of ghee in the same pan, add the cloves, gently place the eggplants on the pan and let it cook on the skin side.", "This will take 10 minutes.Gently, turn over the eggplants and let it cook over the other side as well.", "Once done, add the lemon juice, gently toss everything together and switch off the heat.Serve\u00a0Baingan Ki Lonje Recipe (Uttar Pradesh Style Brinjal Sabzi) with steamed rice,\u00a0Methi Jowar Roti Recipe\u00a0and\u00a0Awadhi Style Dal Masoor Musallam Recipe\u00a0for a weeknight dinner."]'::jsonb, 40, 'Uttar Pradesh', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Baingan_Ke_Lonje_Recipe_UP_Style_Brinjal_Sabzi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1026.Baingan_Ke_Lonje_Recipe_UP_Style_Brinjal_Sabzi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Style Empada De Camarao Recipe (Prawn Pie)', 'goan-style-empada-de-camarao-recipe-prawn-pie', 'Goan Style Empada De Camarao Recipe (Prawn Pie) is a very Portuguese influence on Goan Dish. The dish is made from a spicy flavored flaky pie pastry that is stuffed in with chopped prawns that is cooked in Recheado masala. This is one of the common masala used in most of the Goan cooking. The masala is fiery hot and has good blend of hot aromatic spices and Tamarind. The addition of onions and tomatoes to the dish adds in an extra touch to the whole pie.', '["300 grams Prawns , deveined and chopped small", "1 Onion , chopped", "1 Tomato , chopped", "10 Dry Red Chillies", "3 cloves Garlic", "1 inch Cinnamon Stick (Dalchini)", "1 teaspoon Whole Black Peppercorns", "1 Onion , chopped", "18 grams Tamarind Paste", "1 cup Whole Wheat Flour", "1/2 cup Vivatta Maida", "1 teaspoon Red Chilli powder", "1/2 teaspoon Salt", "1 tablespoon Sugar", "1/2 cup Butter (Unsalted) , cut into small pea size pieces", "3 to 4 tablespoons Chilled water"]'::jsonb, ARRAY['tomato', 'salt', 'wheat flour', 'prawns deveined', 'red chilli powder', 'cloves garlic', 'black peppercorns', 'water', 'vivatta maida', 'sugar', 'dry red chillies', 'onion', 'cinnamon stick (dalchini)', 'butter pea', 'tamarind paste']::text[], '["To begin making the Goan Style Empada De Camarao Recipe, we will make the pie crust first.", "Get all the ingredients ready and get your butter cut into small pea size pieces.The next step is to make the dough for the pie crust.", "In a large mixing bowl, combine the flour, salt, and sugar.", "Add the butter into the flour mixture.Work the butter into the flour with your fingers until the mixture resembles a coarse meal.", "When you hold the flour together, it should hold tight and when you let it loose, it will fall apart.Sprinkle ice water onto the flour and butter mixture.", "Using your hands push the dough from the sides to the middle of the bowl to form a ball that holds together.Make sure to add little water at a time, as the heat from your hands will melt the butter and help form the dough as well.You can transfer the pie dough on to a work surface and knead the dough until all the flour has come together to form a smooth dough.Once done, wrap the dough in a cling film or a plastic wrap and refrigerate it for a couple of hours.", "This refrigeration process helps to give the pie crust a flaky texture.To make the filling, grind the ingredients for Recheado masala in a mixer grinder to a smooth paste and keep it aside.Heat a kadai with oil, add chopped onions and saute till they turn translucent.", "Add in tomatoes and saute till it becomes mushy and soft.Add your ground recheado masala and keep saut\u00e9ing until the raw smell from the masala goes away.", "Add chopped prawns at the end, sprinkle with little salt and cook until the prawns curl up and switch off the flame immediately.", "Set aside the filling to cool, pre heat the oven to 180 degree Celsius to 10 minutes and leave it aside.", "Remove the dough from the refrigerator to start rolling.On a generously floured surface, Divide the dough into two equal parts, gently flatten the ball of the dough with a rolling pin.", "Starting from the center, roll the dough into a circle about an inch larger than the diameter of the pan that you plan to use.Once rolled out lift the dough into the pan.", "Fold the edges under and crimp with your fingers or a fork.Blind bake the pie crust in the oven for about 5 minutes and take it out.", "Add the filling inside and flatten it.Roll out the other half of the pie crust pastry as flat and big as possible, in order to cover the tart on top.", "Carefully lift the dough and place it on top of the pie and cut of the extras from the ends.", "By using a forst poke holes on top.Bake it in the oven at 180 degree Celsius for over 30 minutes till you get a nice crispy crust on top.", "You can also egg brush to get a nice color.Serve the Goan Style Empada De Camarao Recipe along with a\u00a0salad\u00a0and a\u00a0Orange Mocktail Recipe\u00a0to make it a complete meal."]'::jsonb, 70, 'Goan', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Goan_Style_Empada_De_Camarao_Recipe_Prawn_Pie_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1027.Goan_Style_Empada_De_Camarao_Recipe_Prawn_Pie_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pavakkai Poriyal Recipe - Karela Ki Sabzi', 'pavakkai-poriyal-recipe-karela-ki-sabzi', 'Pavakkai Poriyal Recipe is a simple delicious sweet and sour preparation of the super healthy vegetable Bitter gourd with the addition of amchur powder and jaggery. The flavours of this Pavakkai Poriyal is elevated with the addition of hing, roasted peanuts and chopped coriander leaves.', '["500 grams Karela (Bitter Gourd/ Pavakkai) , cut into small dices (remove excess seeds from inside)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1/4 teaspoon SSP Asafoetida (Hing)", "2 sprig Curry leaves , torn", "1/2 teaspoon Sambar Powder", "1/2 teaspoon Red Chilli powder", "1 teaspoon Amchur (Dry Mango Powder)", "2 tablespoons Jaggery , or more to suit your taste", "1/4 cup Roasted Peanuts (Moongphali) , coarsely pounded", "2 tablespoons Oil", "Coriander (Dhania) Leaves , small bunch,finely chopped", "Salt , to taste"]'::jsonb, ARRAY['karela (bitter gourd pavakkai) dices (remove excess seeds from inside)', 'coriander (dhania)', 'salt', 'amchur (dry mango powder)', 'asafoetida (hing)', 'mustard seeds', 'red chilli powder', 'jaggery suit', 'curry leaves', 'white urad dal (split)', 'peanuts (moongphali)', 'turmeric powder', 'sambar powder', 'sunflower oil']::text[], '["To begin making the Pavakkai Poriyal Recipe, we will first cook the diced bitter gourd (Karela/ Pavakkai) in the pressure cooker for three\u00a0 whistles along with turmeric powder, salt to taste and 2 tablespoons of water.", "You can also alternatively steam the Pavakkai using a steamer.", "See recipe of how to cook vegetables in a pressure cooker.Once the bitter gourd is cooked well; heat oil in a heavy bottomed pan on medium high; add the mustard seeds, and urad dal and saute until the dal becomes golden brown and crisp.", "Once done add the asafoetida and curry leaves and stir for a few seconds.", "Now add the cooked bitter gourd,\u00a0sambar powder, red chilli powder, dry mango powder and jaggery.", "Stir til the jaggery melts and gets well combined.Cover the pan and simmer for 3-4 minutes until the bitter gourd looks well coated with all the ingredients.After 3 to 4 minutes stir in the roasted peanuts and chopped coriander leaves.", "Check the salt and spice levels and adjust to suit your taste.", "Turn off the heat and transfer the Pavakkai Poriyal to a serving bowl and serve hot.Serve the\u00a0Pavakkai Poriyal\u00a0along with\u00a0Tomato Rasam,\u00a0Keerai Sambar\u00a0and\u00a0Steamed Rice\u00a0for a comforting weekday meal."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Pavakkai_Poriyal_Recipe_Video_11_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1028.Pavakkai_Poriyal_Recipe_Video_11_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharashtrian Chavali Chi Usal Recipe - Black Eyed Peas Curry', 'maharashtrian-chavali-chi-usal-recipe-black-eyed-peas-curry', 'Maharashtrian Chavali Chi Usal Recipe which is a Maharashtrian Style Black Eyed Peas Curry is made with Black Eyed Peas which is the most common lentil used in most of the Indian households. The curry is a homemade spice curry made with fresh coconut, fennel seeds, and coriander seeds.', '["1 cup Black Eyed Beans (Lobia) , soaked for 2 hours", "1 Onion , chopped", "1 Tomato , chopped", "1 tablespoon Garam masala powder", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "Ingredients to grind", "1 Onion , chopped", "4 tablespoon Fresh coconut", "2 tablespoon Coriander (Dhania) Seeds", "1 tablespoon Fennel seeds (Saunf)", "1 inch Ginger , chopped", "4 cloves Garlic"]'::jsonb, ARRAY['tomato', 'ginger', 'coconut', 'fennel seeds (saunf)', 'red chilli powder', 'cloves garlic', 'coriander (dhania) seeds', 'onion', 'turmeric powder', 'black eyed beans (lobia)', 'garam masala powder']::text[], '["To begin making the Maharashtrian Chavali Chi Usal soak the black eyed peas in water for 2 hours and keep it ready.Heat a flat skillet with oil, add coriander seeds and fennel seeds.", "Saute for 1 minute.", "Add chopped onions and fry till the onions become light brown.Add ginger, garlic and coconut and saute for 2 more minutes and set aside to cool.", "Grind the saut\u00e9ed ingredients to a smooth paste.Heat a pressure cooker with oil, saute the onions till it is translucent.", "Add the ground paste along with garam masala powder, turmeric powder, and red chilli powder and saute them well till the curry is cooked.Once the ground paste changes the color to a bright yellow.", "Add the chopped onions and black eyed peas and saute for 2 more minutes.Check for salt add 2 cups of water and pressure cook the peas for 3 whistle.", "Once done allow the pressure to release by itself.", "Add chopped coriander leaves as garnish.Serve the Maharashtrian Chavali Chi Usal Recipe can be had with\u00a0steamed rice,\u00a0Kokum curry\u00a0for your Sunday lunch."]'::jsonb, 160, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Maharashtrian_Chavali_Chi_Usal_Recipe_Black_eyed_peas_Curry_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1029.Maharashtrian_Chavali_Chi_Usal_Recipe_Black_eyed_peas_Curry_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lauki Ke Kofta Curry Flavoured With Kasuri Methi', 'lauki-ke-kofta-curry-flavoured-with-kasuri-methi', 'Lauki Ke Kofta Flavoured With Kasuri Methi is delicious kofta curry with healthy and spicy lauki dunked in a tomato anion based gravy flavoured with kasuri methi. This is a nice way to eat the bottle gourds that lay ignored in crisper for long time. The creamy base gels so well with bottle gourd disguised in the koftas to make it absolutely loveable.', '["250 grams Bottle gourd (lauki) , grated", "2 tablespoons Corn flour", "2 tablespoons Gram flour (besan)", "2 Green Chillies , chopped", "1/4 cup Coriander (Dhania) Leaves , chopped", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Garam masala powder", "Salt , to taste", "1 teaspoon Red Chilli powder", "To Be Ground To Paste", "2 Onions , roughly sliced", "6 cloves Garlic", "1 inch Ginger , roughly sliced", "4 Green Chillies", "Other Ingredients", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "1 teaspoon Red Chilli powder", "2 cups Homemade tomato puree", "Salt , to taste", "Oil , to shallow fry", "1/4 cup Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['s bottle gourd', 'lauki', 's corn flour', 's gram flour', 'besan', 'reen chillies', 'coriander', 'dhania', 'cumin seeds', 'jeera', 'garam masala powder', 'salt', 'red chilli powder', 'to be ground to paste', 'onions', 's garlic', 'ginger', 'other ingredients', 'kasuri methi', 'dried fenugreek leaves', 'coriander powder', 'turmeric powder', 'haldi', 's homemade tomato puree', 'oil']::text[], '["To begin making Lauki Ke Kofta Curry Flavoured With Kasuri Methi, mix all the ingredients for Koftas including bootle gourd, corn flour, gram flour, green chillies, coriander leaves, cumin seeds, garam masala powder, red chilli powder, salt in a bowl.Mix it gently without adding water (since the bottle gourd already has lot of moisture).", "Apply some oil on palms, and make small round balls of equal size to fit paniyaram pan.Heat a paniyaram pan, drizzle a few drops of oil into each cavity and fry the lauki Koftas.Once the bottom side of the kofta is browned, flip them on the other side and fry further till browned evenly.Keep medium heat through out while frying the koftas.", "Drain on paper towel and set aside.Make a paste of ingredients mentioned under \"To Be Ground To Paste\" including onions, garlic, ginger, green chillies with a little water in the food processor.Heat a little oil in a shallow fry pan or kadai.", "Add dried kasuri methi and cumin seeds.", "Saut\u00e9 for about a minute or half, on medium heat.Add the ground paste to the pan and saut\u00e9 for about 10 minutes on low heat till the gravy is golden brown in colour.Now add all the spices and salt.", "Mix well.", "Now add tomato pur\u00e9e and saut\u00e9 till the gravy comes together and looks cooked.Add about 3 cups of water and let it boil for a few minutes.", "Once done, check for salt and seasoning.", "Now add the koftas made earlier in the curry.", "Cook for few minutes.Remove from heat and add chopped coriander leaves.", "Serve\u00a0Lauki Ke Kofta Flavoured With Kasuri Methi\u00a0along with\u00a0Garlic Naan Without Yeast Recipe\u00a0and\u00a0Boondi Raita\u00a0for a weekday meal."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sapanabehl/Lauki_ke_Kofte.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1030.Lauki_ke_Kofte.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rumali Roti Recipe', 'rumali-roti-recipe', 'Rumali Roti Recipe is a type of thin Indian bread that has come from Punjabi cuisine. Which is one of the popular cuisine of India. The bread is rolled very thin, thus the name “Rumali”. As the word literally means Handkerchief in punjabi. It is an art to make this bread as you require certain technique and experience to make it so thin. But you can also roll it thin using a rolling pin. The bread is then traditionally cooked on an “Ulte Tawa or Kadai” which is nothing but a wok that is turned over.', '["1 cup All Purpose Flour (Maida)", "1/4 cup Curd (Dahi / Yogurt)", "1 tablespoon Oil", "Salt , to taste", "Lukewarm Water , to knead"]'::jsonb, ARRAY['salt', 'water knead', 'curd', 'flour (maida)', 'sunflower oil']::text[], '["To begin making the Rumali Roti Recipe, mix all the ingredients together and knead it into a soft dough.Rest the dough for around 10 minutes.", "Then knead one last time and pinch out a small portion from the dough.Toss it on the flour and roll out into thin circles to approximately 6 inches in diameter.", "As you roll them out, you can keep tossing the dough in dry flour while rolling; this will prevent it from getting sticky when rolling them out.Roll it as thin as possible.", "Tip: It is a good idea to roll out a batch of dough so it gets easier to cook the entire batch.", "Although Gujarati ladies are very quick in rolling and cooking them simultaneously; this comes with practice of rolling and understanding the heat of your skillet.Heat a dosa tawa so that you can cook the big roti well.", "Place rolled dough on the hot skillet.", "In a few seconds you will notice that small air pockets start to form.", "At this point flip the rolled dough to cook the other side on the skillet.Serve the Rumali Roti Recipe, along with\u00a0Butter chicken\u00a0or\u00a0Paneer Kadai\u00a0to enjoy your lunch."]'::jsonb, 35, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Rumali_Roti_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1031.Rumali_Roti_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bhugi Dal Paratha Recipe - Moong Dal Paratha', 'bhugi-dal-paratha-recipe-moong-dal-paratha', 'Bhugi Dal Paratha Recipe (Dal Jo Phulko) or Moong Dal Paratha, is a healthy paratha that is stuffed with protein rich yellow moong dal, with mild spices. Dal is cooked and drained, so that the dal can be used as a stuffing for the paratha.', '["1/2 cup Yellow Moong Dal (Split) , washed and soaked", "Salt , to taste", "1 teaspoon Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Turmeric powder (Haldi)", "1 1/2 cups Whole Wheat Flour", "Salt , to taste", "1 teaspoon Oil", "Ghee , to cook"]'::jsonb, ARRAY['salt', 'yellow moong dal (split)', 'cumin powder (jeera)', 'wheat flour', 'ghee', 'red chilli powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making Bhugi Dal Paratha Recipe - Moong Dal Paratha, wash and soak the dal for 30 minutes.In a pan, add the washed and soaked dal, with salt, haldi and one cup of water (use the water that the dal was soaked in)Boil this dal in the open pan on medium flame for 10-12 minutes.", "Touch the grains of the dal to check if they are cooked and soft yet whole and not mushy.Turn off the flame.", "Drain the water.", "Transfer to a bowl, combine the boiled dal, red chilli powder, cumin powder and salt and mix well and set aside."]'::jsonb, 30, 'Sindhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sneha-archanaskitchen.com/Bhugi_Dal_Paratha_Recipe__Dal_Jo_Phulko.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1032.Bhugi_Dal_Paratha_Recipe__Dal_Jo_Phulko.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dhania Chole Masala Recipe - Chickpeas In Fresh Coriander Gravy', 'dhania-chole-masala-recipe-chickpeas-in-fresh-coriander-gravy', 'Dhania Chole Masala is a delicious  chole recipe cooked in a flavourful fresh coriander and mint gravy. The fresh coriander and mint leaves ground along with ginger and green chillies renders a beautiful flavour to the dish. The addition of fresh spices adds to the delicious flavours of the dish.', '["1/2 cup Coriander (Dhania) Leaves , chopped", "4 Green Chillies", "1 inch Ginger", "Salt , to taste", "1 Lemon , juice extracted", "2 cups Kabuli Chana (White Chickpeas) , soaked overnight", "1 tablespoon Ghee", "1 Onion , finely chopped", "1 inch Ginger , finely chopped", "3 cloves Garlic , finely chopped", "1 Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta)", "1 Brown cardamom (Badi Elaichi)", "1 teaspoon Black Salt (Kala Namak)", "1/4 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Black Salt (Kala Namak)", "Salt , to taste", "Salt , to taste"]'::jsonb, ARRAY['salt', 'black salt', 'ginger', 'coriander (dhania) leaves', 'ghee', 'bay leaf (tej patta)', 'cloves garlic', 'kabuli chana (white chickpeas)', 'onion', 'lemon', 'cinnamon stick (dalchini)', 'brown cardamom (badi elaichi)', 'coriander powder', 'green chillies', 'garam masala powder']::text[], '["To begin making\u00a0Dhania Chole Masala, wash and soak the chana or chickpeas overnight.", "Drain the water in which the chickpeas/chole is soaked in.", "Pressure cook the drained chana\u00a0along with 3 cups of water and salt for 6 whistles.", "After 6 whistles reduce the heat to low and continue to cook for 20 minutes.", "Turn off the flame and allow the pressure to release naturally.", "The chana has be cooked well once you open the pressure cooker.", "Once done, when you press between your fingers to should mash easily.The next step is to make the Dhania Masala.Into a mixer grinder, add the coriander, ginger and green chillies, along with a little salt and lemon juice.", "Add 1/4 cup water and blend to make a smooth mixture like a chutney.", "Keep the Dhania Masala aside.Heat ghee in a pan over medium heat; add the onion, ginger and garlic and saute until the onion softens.", "Add the bay leaves, cinnamon stick, badi elaichi and saute for a few more seconds until you can smell the aromas.After a few seconds, add the garam masala, coriander powder, kala namak and the dhania masala.", "Give it a stir.Add the cooked chana, give it a stir.", "Add water if required to adjust the consistency of the chana masala.", "Cover the pan and simmer the Dhania Chole Masala for a good 10 minutes.After 10 minutes, you will notice that the chole is well coated with the dhania masala.", "At this stage, check the taste and adjust the salt and chilli accordingly.Once done, turn off the heat and transfer the Dhania Chole Masala to a serving bowl and serve hot.Serve the\u00a0Dhania Chole Masala, along with\u00a0Puri,\u00a0Paneer in White Gravy,\u00a0Lacha Pyaz\u00a0and\u00a0Chaas\u00a0for a delicious weekend lunch."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Dhaniya_Chole_Masala_Curry_Mint_Coriander_Chana_Masala_5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1033.Dhaniya_Chole_Masala_Curry_Mint_Coriander_Chana_Masala_5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Broken Wheat Khichdi With Vegetables Recipe', 'spicy-broken-wheat-khichdi-with-vegetables-recipe', 'Spicy Broken Wheat Khichdi with Vegetables is a healthy preparation of broken wheat, vegetables and spices, cooked together in a single pot. It is a perfect recipe when you are in no mood of cooking and still wants to eat something healthy.', '["1-1/2 cup Broken Wheat (Dalia/ Godumai Rava)", "Water , as required", "1/2 teaspoon Ginger , grated", "1/2 teaspoon Garlic , minced", "2 Cloves (Laung)", "1 Bay leaf (tej patta)", "2 Dry Red Chilli", "Ghee , as required", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "6 Curry leaves , roughly torn", "2 Green Chillies , finely chopped", "1 Onion , chopped", "1 Tomato , chopped", "1/2 cup Green peas (Matar)", "1 Carrot (Gajjar) , finely chopped", "1 Potato (Aloo) , cubed", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , as required", "Coriander (Dhania) Leaves , Few sprigs, finely chopped"]'::jsonb, ARRAY['tomato', 'wheat (dalia godumai rava)', 'carrot', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies', 'salt', 'mustard seeds', 'red chilli powder', 'water', 'dry red chilli', 'garlic', 'ginger', 'coriander (dhania) leaves', 'bay leaf (tej patta)', 'ghee', 'potato (aloo)', 'green peas (matar)', 'curry leaves', 'cloves (laung)']::text[], '["To begin making the Broken Wheat Khichdi With Vegetables recipe, firstly heat ghee in a heavy bottomed pan.", "Add mustard seeds, cumin seeds, bay leaf, curry leaves, dry red chillies and cloves.Once the mustard seeds splutter, add in the ginger garlic paste and green chillies.", "Saute it for a few seconds on low flame.Add in the onions and cook them till they turn translucent.Once it is done add in the peas, carrots and potatoes.", "Let it cook for about 5 to 8 minutes.After 5 to 8 minutes, add in the tomatoes and the broken wheat.", "Add in red chilli powder, turmeric powder and the required salt.Cook it for 2 minutes and then add the required water.", "Cover it with a lid and cook it till the broken wheat and vegetables are cooked properly.Once it is done, switch off the flame and garnish it with chopped coriander.Spicy Broken Wheat Khichdi With Vegetables can be served with\u00a0Lauki Raita, Papad and\u00a0Aam Ka Achaar\u00a0for a quick weeknight dinner."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/daliya_khichdi_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1034.daliya_khichdi_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer in White Gravy Recipe - No Onion No Garlic Recipe', 'paneer-in-white-gravy-recipe-no-onion-no-garlic-recipe', 'Paneer in White Gravy Recipe is a No onion & No Garlic curry which is a made from a cashew nut paste cooked along with spices and yogurt. The gravy is flavored with star anise, bay leaf, cinnamon and sprinkled with dried fenugreek leaves to give it that additional flavour and taste.', '["250 grams Paneer (Homemade Cottage Cheese) , cut into small cubes", "1 tablespoon Ghee", "1 Bay leaf (tej patta)", "1 Star anise", "1 Brown cardamom (Badi Elaichi)", "1 inch Cinnamon Stick (Dalchini)", "2 Green Chillies , slit", "1 teaspoon Kasuri Methi (Dried Fenugreek Leaves)", "1/4 cup Cashew nuts", "1/4 cup Milk", "1/2 cup Curd (Dahi / Yogurt)", "Salt , to taste"]'::jsonb, ARRAY['cashew nuts', 'salt', 'bay leaf (tej patta)', 'paneer', 'ghee', 'milk', 'curd', 'cinnamon stick (dalchini)', 'kasuri methi (dried fenugreek leaves)', 'brown cardamom (badi elaichi)', 'green chillies', 'star anise']::text[], '["To begin making the Paneer in White Gravy Recipe, prep all the ingredients and keep them ready.To make a paste of the cashew nuts, add it to the mixer grinder, add milk and blend to make a smooth paste.Heat ghee in a pan; add the green chillies, bay leaf, star anise, badi elaichi, cinnamon stick and saute for a few seconds.Add the kasuri methi, the cashew paste, yogurt, salt and paneer.", "Give the Paneer in white gravy a stir and give it a brisk boil.", "Once done, check the salt and adjust according to taste and turn off the heat.Transfer the Paneer In White Gravy to a serving bowl and serve hot.", "Sprinkle with more kasuri methi if desired.Serve the \u00a0Paneer in White Gravy Recipe along withDal Makhani,\u00a0Tawa Paratha\u00a0and Pyaz for a delicious dinner or lunch."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Paneer_in_White_Gravy_No_Onion_No_Garlic_Masala_Curry_North_Indian_Sabzi_Recipes_10_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1035.Paneer_in_White_Gravy_No_Onion_No_Garlic_Masala_Curry_North_Indian_Sabzi_Recipes_10_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rajasthani Papad Ki Sabzi Recipe', 'rajasthani-papad-ki-sabzi-recipe', 'Papad Ki Sabzi is very cooked in almost every home of Rajasthan. There are days when you don’t have vegetables in your house, then you can prepare this Papad Ki Sabzi. Made with a delicious blend of tomato and yogurt gravy which is deliciously cooked along with kasuri methi and a subtle hint of garlic and green chillies.', '["1 tablespoon Ghee", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "1 inch Ginger , chopped", "1 Green Chilli , chopped", "3 cloves Garlic", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "2 Tomato , pureed", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Coriander Powder (Dhania)", "1/2 cup Curd (Dahi / Yogurt) , whisked", "3 Papad", "Salt , as required", "2 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'papad', 'green chilli', 'asafoetida (hing)', 'ghee', 'red chilli powder', 'cloves garlic', 'curd', 'coriander (dhania) leaves', 'coriander powder', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'cumin (jeera) seeds']::text[], '["To begin making the Papad ki Sabzi recipe, roast the papad on the gas or in the microwave until completely roasted.", "Break the popad into small quarters and keep aside.Make a paste of the ginger, garlic and green chillies using a pestle and mortar.", "Keep aside.Heat ghee in a pan over medium heat; add the cumin seeds and allow it to crackle.", "Add the ginger, garlic green chilli paste and the kasuri methi.Saute for a few seconds.", "Add the tomato puree, turmeric powder, red chilli powder, coriander powder and give it a brisk boil.After a minute, add the curd, roasted papad and salt.", "Turn the heat to low, keep mixing the Papad ki sabzi, until all the ingredients are well combine.Simmer the mixture for about 5 minutes.", "You will notice the curd will begin to curdle a little and this process is natural.", "Allow it to simmer, until the papad is well soaked into the curry.", "Once done, check the taste of salt and spices and adjust to taste accordingly.Turn of the heat and transfer the papad ki sabzi to a serving bowl and serve hot.Serve Papad ki Sabzi with\u00a0Pindi Chole,\u00a0Jowar Atta Roti\u00a0and\u00a0Lacha Pyaz\u00a0\u00a0for a special weekend lunch or dinner."]'::jsonb, 30, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Rajasthani_Papad_Ki_Sabzi_Recipe_North_indian_Healthy_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1036.Rajasthani_Papad_Ki_Sabzi_Recipe_North_indian_Healthy_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ragi Onion Uttapam Recipe - Wholesome Breakfast Recipe', 'ragi-onion-uttapam-recipe-wholesome-breakfast-recipe', 'Carrot Onion Uttapam Recipe is a nutritious breakfast or dinner made from Ragi Idli Dosa Batter. Ragi Dosa Batter is my recent obsession and discovery that helps me incorporate the much needed millets in our diet. The addition of carrots and onions flavoured with lots of coriander makes this Uttapam healthy and makes a great kids lunch box recipe too. Serve Carrot Onion Uttapam with Sweet and Spicy Tomato Chutney Recipe.', '["Ragi Dosa Battter , as needed", "3 Carrots (Gajjar) , grated", "2 Onions , finely chopped", "2 Green Chillies , finely chopped", "Coriander (Dhania) Leaves , few, chopped", "Salt , to taste"]'::jsonb, ARRAY['salt', 'coriander (dhania) leaves', 'carrot', 'onion', 'green chillies', 'ragi dosa batter']::text[], '["To begin making the Ragi Dosa Carrot Onion Uttapam, make sure you have the fermented Ragi Idli Dosa Batter\u00a0ready.", "Next, combine the remaining ingredients and keep aside. (except the oil and dosa batter)Heat a skillet on medium high heat, season it with oil if you are using an iron skillet.Check if the skillet is hot, you will know when you sprinkle some water and it sizzles.When hot, pour a ladle full of the Ragi Idli Dosa Batter onto the skillet and just give it a lite swirl to spread it just a bit.", "It should be a like a thick pancake.Sprinkle a generous amount of the carrot onion filling over the Uttapam.", "Drizzle some oil around the Uttapam and cover if you have a lid, else you can let it cook in the open.Once you notice the top is lightly steamed and the batter is not raw, press the filling down with a flat spatula.", "Then flip the Uttapam to cook on the other side.", "Turn the heat to medium high, so the vegetables cook fast.", "After about 30 to 40 seconds flip again and the Uttapam will be ready to be served.Serve the Carrot Onion Uttapam along with Coconut Chutney for breakfast or dinner or even pack into a kids lunch box."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Ragi_Onion_Uttapam_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1037.Ragi_Onion_Uttapam_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Menthya Soppu Hesaru Kaalu Palya Recipe', 'karnataka-style-menthya-soppu-hesaru-kaalu-palya-recipe', 'Menthya Soppu Hesaru Kaalu Palya Recipe is a healthy stir fry made using fresh fenugreek leaves and Sprouted Green Gram. The hand pounded spice mix of garlic, shallots, cumin and red chillies adds a great flavour to the dish. The spiciness is balanced by adding a wee bit of jaggery.', '["2 cups Green Moong Sprouts , steamed", "1 cup Methi Leaves (Fenugreek Leaves) , roughly chopped", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Jaggery , powdered", "Coriander (Dhania) Leaves , a few sprigs, finely chopped to garnish", "2 teaspoons Oil", "Salt , to taste", "Ingredients for pounded masala", "4 Shallots , chopped", "3 cloves Garlic", "1 Dry Red Chilli", "1 teaspoon Cumin seeds (Jeera)"]'::jsonb, ARRAY['tomato', 'salt', 'coriander (dhania) leaves', 'methi leaves (fenugreek leaves)', 'green moong sprouts', 'jaggery', 'cloves garlic', 'dry red chilli', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making Menthya Soppu Hesaru Kaalu Palya Recipe, pressure cook the sprouted green gram for one whistle adding a cup of water using a pressure cooker and keep aside.Make a course mix of the shallots, garlic cloves, cumin seeds and dry red chilli using a mortar and pestle and keep aside.Heat oil in a heavy bottomed pan, once the cooking oil is hot, add the onions over medium heat and saute until they turn translucent.Add in the pounded masala mix and saute until the raw smell of the garlic and shallots disappears.Once the mixture is smelling cooked, add the chopped tomatoes and cook until it turns mushy.After the tomatoes are a bit mushy, add the fenugreek leaves, turmeric powder, season with required salt to taste and mix well by sauteing.Let the fenugreek leaves cook to 3/4th, and occasionally keep stirring the mix.", "You can ad a bit of water if you need, at this stage.Occasionally keep stirring on low medium heat, until the methi/fenugreek leaves are mostly done.", "Add in the cooked sprouted green gram, jaggery powder and mix well.Let the mix simmer for about 5 minutes or till done and let the water evaporate if any.Garnish with coriander leaves, mix well and switch off the heat.Serve\u00a0Menthya Soppu Hesaru Kaalu Palya Recipe (Karnataka Style Fenugreek Leaves and Green Gram Stir Fry) along with\u00a0Akki Rotti Recipe (Spicy Gluten Free Rice Flour Flat Breads),\u00a0Karnataka Style Badanekai Yennegai Gojju Recipe\u00a0and\u00a0Indian Vegetable Salad Recipe."]'::jsonb, 30, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Menthya_Soppu_Hesarukalu_Palya_Recipe_Karnataka_Style_Fenugreek_Leaves_and_Green_Gram_Stir_Fry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1038.Menthya_Soppu_Hesarukalu_Palya_Recipe_Karnataka_Style_Fenugreek_Leaves_and_Green_Gram_Stir_Fry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Feijoada Recipe - Spicy Goan Black Eyed Peas Stew', 'feijoada-recipe-spicy-goan-black-eyed-peas-stew', 'Feijoada is a typical Portuguese stew usually made with beans and meat. It has become a famous Goan home-comfort food and can be easily adapted to be vegetarian. In this recipe we use black-eyed peas, but you could also substitute it with any other beans you have on hand. Legumes are a low-fat, high-protein source that is rich in vitamins, minerals, antioxidant compounds and dietary fiber. Excellent source of nutrients for a diabetic-friendly diet, the Feijoada stew can be had with rotis, rice, a slice of bread, or even just as it is.', '["1/2 cup Black Eyed Beans (Lobia) , soaked for 4-6 hours or overnight", "2 Onions , sliced thinly", "5 cloves Garlic , minced", "1 inch Ginger , minced", "2 Tomatoes , blended to puree", "200 ml Coconut milk", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Cumin powder (Jeera)", "Salt", "1/2 tablespoon Jaggery , grated", "1 teaspoon Tamarind Paste", "1 teaspoon Lemon juice"]'::jsonb, ARRAY['black eyed beans', 'lobia', 'onions', 's garlic', 'ginger', 'tomatoes', 'coconut milk', 'turmeric powder', 'haldi', 'red chilli powder', 'coriander powder', 'dhania', 'cumin powder', 'jeera', 'salt', 'jaggery', 'tamarind paste', 'lemon juice']::text[], '["To begin making the Feijoada, drain the soaked black-eyed peas and wash thoroughly.", "Then immerse in sufficient water and pressure cook the beans until soft and tender.", "To puree the tomatoes, simply chop them into large chunks and run them in your blender (without adding water) till they are pureed.In a rotis , warm some oil, let it sizzle and add in the sliced onions.", "Saute them till they are delicately golden.", "Add the minced ginger and garlic and continue to saut\u00e9 for 4-5 minutes.Next, add the red chilli powder, turmeric, coriander powder and cumin powders and saut\u00e9.Pour in the tomato puree and toss the mixture together till the masalas are well cooked and oil begins to release.Next tip in the the cooked black-eyed beans and toss for a minute.", "Add salt and pour in the coconut milk, topped by a little water to bring it to the consistency you desire.Add in the grated jaggery, tamarind paste and stir well.", "Simmer the Feijoada\u00a0stew for another 5-6 minutes, taking care not to allow it to boil vigorously.Top it up with lemon juice and chopped coriander and serve hot.Serve the\u00a0Feijoada (Spicy Goan Black-eyed Peas Stew)\u00a0along with rotis or rice or even a slice of bread.", "Combine it with a hearty salad and make it as a whole meal in itself."]'::jsonb, 50, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Feijoada_Recipe_Spicy_Goan_Black-eyed_Peas_Stew-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1039.Feijoada_Recipe_Spicy_Goan_Black-eyed_Peas_Stew-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Posto Pabda (Bengali Fish Curry In Poppy Seeds Paste)', 'posto-pabda-bengali-fish-curry-in-poppy-seeds-paste', 'Posto Pabda is a very popular fish curry from Bengal, in which the fish named Pabda is cooked in poppy seeds paste making a thick curry. The fish here is cooked whole and the dish goes well with plain rice. The recipe here is adapted from my mother''s diary and trust me, it tastes amazing.', '["4 Pabda fish", "250 grams Poppy seeds", "1 teaspoon Kalonji (Onion Nigella Seeds)", "4 Green Chillies , slit", "1 cup Mustard oil", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste"]'::jsonb, ARRAY['pabda fish', 's poppy seeds', 'kalonji', 'onion nigella seeds', 'reen chillies', 'mustard oil', 'turmeric powder', 'haldi', 'salt']::text[], '["To prepare Posto Pabda Recipe, soak khus khus overnight or for minimum 2-3 hours in water.", "Prepare with all the other ingredients as well.Drain the water and collect the khus khus in a Mixer jar and grind to make a fine paste.", "Keep aside.Clean and wash the fishes well.", "Drain water nicely and coat the fishes with turmeric powder and keep aside.", "The fish is cooked whole, hence do not make pieces.Heat 1/2 cup of mustard oil in a Wok/Kadai, add kalonji and allow it to crackle for a few seconds.Now add the fishes gently and fry till golden in color.If the oil reduces, you can add more from sides.When the fishes are golden in color, add the khus khus paste in the wok and gently stir in.You may add a little water from the sides if the paste is too thick.Season the curry with salt and add green chillies as well.Allow the curry to come to boil, and then cook for 7-8 minutes on a low flame and lid closed.", "Do not stir much at this stage.Turn off the gas and pour in a tablespoon of raw mustard oil on top of Posto Pabda Curry Recipe for a rustic flavor and serve hot with plain steamed rice."]'::jsonb, 45, 'Bengali', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shaheen_Ali/Posto_Pabda.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1040.Posto_Pabda.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Broccoli And Tofu Green Curry Recipe', 'broccoli-and-tofu-green-curry-recipe', 'Fresh Broccoli florets and Tofu are cooked in a spicy green curry to make this fragrant Broccoli and Tofu green curry recipe. This is a very easy recipe and with a little advance prep work, it takes just under 20 minutes to make. You can make a stock of the green curry paste ahead of time, freeze and use as required. Broccoli and Tofu green curry recipe is served with Rice, is perfect for a busy weeknight meal.', '["1 Broccoli , washed and cut into florets", "250 grams Tofu , cut into cubes", "2 tablespoon Oil", "2 tablespoon Soy sauce , or thai fish sauce", "200 ml Coconut milk", "Vegetable stock , as required", "Salt , to taste", "Lemon wedges , to serve", "Ingredients For The Curry Paste", "1 Lemongrass , stalk, chopped", "4-5 Thai basil leaves", "1 inch Galangal , peeled and sliced (or use ginger)", "2 Kaffir lime leaves , torn (or use dried leaves)", "3-4 Shallots , chopped", "1 sprig Coriander (Dhania) Leaves , washed and chopped", "3 Garlic , minced"]'::jsonb, ARRAY['salt', 'vegetable stock', 'tofu', 'lemongrass stalk', 'galangal (or ginger)', 'thai basil leaves', 'coriander (dhania) leaves', 'garlic', 'broccoli', 'lemon', 'coconut milk', 'soy sauce thai fish sauce', 'kaffir lime leaves (or dried leaves)', 'sunflower oil']::text[], '["To begin making the Broccoli and Tofu green curry recipe, first, blend the ingredients mentioned under \u201cCurry Paste\u201d to a fine paste, using a mortar and pestle or food processor.Heat oil in a Kadai and add the curry paste.", "Saut\u00e9 for 1-2 minutes till you get a nice aroma.Add the broccoli florets, mix and stir fry for 1-2 minutes.Add the Tofu and stir for other 1-2 minutes.Add 1/2 - 1 cup of the vegetable stock, soy sauce, and coconut milk.Stir and cook for 7-8 minutes till it thickens a little.Adjust the consistency of the Broccoli and Tofu green curry as desired.Serve the green curry recipe hot with cooked Rice and lemon wedges on the side."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Broccoli_and_Tofu_green_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1041.Broccoli_and_Tofu_green_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kesar Pista Kulfi Recipe', 'kesar-pista-kulfi-recipe', 'Kesar Pista Kulfi Recipe is one of the most delicious frozen Indian desserts that can be had anytime of the year. It is very similar to western ice cream but since kulfi is not whipped it results in a solid, dense, but rich, luscious creamy indian dessert.', '["3 liters Milk , (I use 2% fat)", "1/2 cup Sugar", "1 teaspoon Saffron strands", "2 teaspoons Cardamom Powder (Elaichi) , freshly pounded", "1/2 cup Pistachios , finely chopped"]'::jsonb, ARRAY['pistachios', 'saffron strands', 'sugar', 'cardamom powder (elaichi)', 'liters milk']::text[], '["To begin making the Kesar Pista Kulfi, we will first have to condense the milk.", "For this heat milk in a heavy bottomed saucepan and bring the milk to a boil.Once the milk comes to a boil, turn the heat to low and simmer the milk with almost continuous stirring and reduce the milk to more than half its quantity.", "It is important to note that during the initial stages of milk condensation frequent stirring is important, but as it begins to start condensing and reaches less than half the quantity it is absolutely important that you stir continuously.This is because condensed milk tends to get stuck to the bottom and sides of the pan and burn; leading to a very unpleasant taste.", "Burning of milk is also toxic so you want to be extra careful.Once it is reduced to about more than half of its quantity stir in the sugar until it dissolves completely.", "Finally stir in the cardamom powder, saffron and chopped pistachios into the Kulfi milk mixture.Turn off the heat and allow the kesar pista kulfi mixture to cool completely.", "Pour the kesar pista kulfi mixture in the moulds until 3/4th full, seal them airtight and freeze them in the refrigerator.", "The Kesar Pista Kulfi takes a good fifteen hours or more to freeze.", "If you get wooden ice cream sticks in the market, you can insert them in and freeze the Kulfis.Once frozen you can run the kesar pista kulfi moulds under water to enable easy release onto the plate and serve.Serve the\u00a0Kesar Pista Kulfi\u00a0for your Holi or Diwali Party or when you have an elaborate Indian Dinner Menu planned for your parties.", "You can also serve it to your guests during festival with some delicious appetisers like\u00a0Paneer Tikka\u00a0and Chaat items."]'::jsonb, 95, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Kesar_Pista_Kulfi_Recipe_Indian_Ice_Cream-1-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1042.Kesar_Pista_Kulfi_Recipe_Indian_Ice_Cream-1-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Takkali Sadam Recipe (Chettinad Style Tomato Rice)', 'chettinad-takkali-sadam-recipe-chettinad-style-tomato-rice', 'Chettinad Takkali Sadam Recipe is a flavourful tomato rice dish from the Chettinad region of Tamil Nadu. It is simple to make yet quite flavouful. You can prepare this in no time if you have cooked rice handy. Serve Chettinad Takkali Sadam Recipe along with Cauliflower & Cucumber Raita Recipe (Cauliflower Yogurt Salad) for Kids lunch box or for a quick lunch.', '["2 cups Rice , cooked", "2 Tomatoes , finely chopped", "1 Onion , thinly sliced", "1 teaspoon Red Chilli powder", "1 Green Chilli , slit", "Mint Leaves (Pudina) , fistful, roughly chopped", "Coriander (Dhania) Leaves , small bunch, finely chopped", "1 Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "1 sprig Curry leaves", "1 tablespoon Ghee", "Salt , to taste", "To grind to a coarse mix using a mortar and pestle", "1 inch Ginger , roughly chopped", "3 to 4 cloves Garlic", "1 teaspoon Fennel seeds (Saunf)"]'::jsonb, ARRAY['s rice', 'tomatoes', 'onion', 'red chilli powder', 'reen chilli', 'mint leaves', 'pudina', 'coriander', 'dhania', 'cinnamon stick', 'dalchini', 'laung', 'curry leaves', 'ghee', 'salt', 'to grind to a coarse mix using a mortar and pestle', 'ginger', 'to 4 cloves garlic', 'fennel seeds', 'saunf']::text[], '["To begin making Chettinad Takkali Sadam Recipe, cook the rice to a fluffy texture and keep aside.Also, coarsely pound the ginger, garlic and fennel seeds using a mortar and pestle and keep aside.Heat ghee in a pan on medium flame, add the cinnamon stick and cloves and let it splutter.Add the ginger, garlic and fennel seeds mix and saute until the raw smell goes away.Add the curry leaves and sliced onions and saute until the onions turn translucent.Add the tomatoes and saute until its half cooked.Now, add the slit green chilli, red chilli powder, mint and coriander leaves and mix well.Season with salt and cook the mix until the tomatoes are well cooked and the whole mixture comes together.", "This will take around 10 minutes.Now, add the cooked rice and mix it evenly using a fork.Let it simmer for 5 minutes and switch off the flame.Serve the Chettinad Takkali Sadam Recipe along with Cauliflower & Cucumber Raita Recipe (Cauliflower Yogurt Salad) for lunch or for kids lunchbox."]'::jsonb, 20, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Chettinad_Takkali_Sadam_Recipe_Chettinad_Style_Tomato_Rice.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1043.Chettinad_Takkali_Sadam_Recipe_Chettinad_Style_Tomato_Rice.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dry Fruit Ghughra/Gujiya Recipe (Pastry Crust Pockets Filled With Dry Fruits)', 'dry-fruit-ghughra-gujiya-recipe-pastry-crust-pockets-filled-with-dry-fruits', 'Dry Fruit Ghughra or Gujiyas or Kadubu (Karnataka) Recipe are nothing but pockets of pastry crust, filled with dry fruits and deep fried to a crispy golden finish. Ghughra also called as Gujiya in Rajasthan have been a favorite of mine, ever since I was a child. These half moon shaped deep fried pockets, filled with pounded dry fruits and coconut taste super delicious when savored hot. However they also keep well for up-to a week when stored in an airtight container. They are most often made during Diwali and Holi or to celebrate a special occasion in the family.', '["Ingredients for the Gujiya Crust", "3 cups All Purpose Flour (Maida) , (all purposeflour)", "1/4 cup Ghee", "1/4 teaspoon Salt", "Ingredients for the Gujiya Filling", "1/2 cup Dessicated Coconut", "1/4 cup Whole Almonds (Badam) , coarsely powdered", "1/4 cup Pistachios , coarsely powdered", "1/4 cup Cashew nuts , coarsely powdered", "1/4 cup Dates , finely chopped", "1/4 cup Sultana Raisins", "2 teaspoons Cardamom Powder (Elaichi) , freshly powdered"]'::jsonb, ARRAY['ingredients for the gujiya crust', 's all purpose flour', 'maida', 'ghee', 'salt', 'ingredients for the gujiya filling', 'dessicated coconut', 'whole almonds', 'badam', 'pistachios', 'cashew nuts', 'dates', 'sultana raisins', 's cardamom powder', 'elaichi']::text[], '["To begin making the Dry Fruit Ghughra Recipe (Gujiya), we will first make the pastry crust.", "Combine the flour, ghee and salt, in a large bowl.", "Work the ghee into the flour with your fingers until the mixture resembles a coarse meal.Combine the flour, ghee and salt, in a large bowl.", "Work the ghee into the flour with your fingers until the mixture resembles a coarse meal.Sprinkle water onto the crumbly dough and with your hands push the dough from the sides to the middle of the bowl to form a ball that holds together and is smooth.Be careful to add only little water at a time, and not allowing the dough to become soggy.", "Knead well with your hands until the dough becomes into a firm ball of smooth dough.", "Cover the dough and allow it to rest for an hour.Our next step is to make the filling.", "A tip to crush all the nuts is to use a food processor.", "This eases the process a lot \u00a0than cutting them with a knife.Combine all the ingredients for the filling until all the ingredients hold together.", "Divide the filling mixture into 20 equal portions.", "Divide the pastry/gujiya dough into 20 equal portions as well.Keep a small bowl filled with water by the side.", "On a floured surface roll each portion of the gujiya dough into a 3 inch diameter circle.", "Place a teaspoon full of filling mixture onto one half of the circle.", "Wet your fingers into the bowl of water and spread a little water around the edges of the circle.Gently fold the circle into a semi-circle, forming a half moon shape.", "Seal the edges by pressing slightly, so that the dough sticks to each other making sure all the filling is still concealed inside.Decorate the edges of the Gujiya by twisting the dough portion carefully to form a twisted shape.", "Continue the same procedure with the remaining dough and filling portions.Preheat the oil on medium heat and you will know when the oil is preheated when you put a small dough it, it will start bubbling up.Place the shaped gujiya, one at a time into the preheated oil.", "Based on the size of your pan you can fry 4 to 5 at a time on medium heat.", "Turn the Gujiya\u2019s around in the oil once they come floating to the top.", "Do make sure to fry it on medium heat and not high, so you get crispy Gujiya\u2019sOnce the Gujiya\u2019s are fried to golden brown, drain the excess oil and proceed the same way with the remaining Gujiya\u2019s.Serve\u00a0these delicious Dry Fruit Ghughra/Gujiya Recipe (Pastry Crust Pockets Filled With Dry Fruits)\u00a0 for the festival of holi, diwali or a special occasion in the family as\u00a0Party Dessert."]'::jsonb, 90, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Holi_Recipe_Ghughra_Gujiya_With_Dry_fruits_recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1044.Holi_Recipe_Ghughra_Gujiya_With_Dry_fruits_recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Style Caldinho de Abobora Branca Recipe (Mild Curry of white Pumpkin)', 'goan-style-caldinho-de-abobora-branca-recipe-mild-curry-of-white-pumpkin', 'Goan Style Caldinho de Abobora Branca Recipe (Mild Curry of white Pumpkin) has mild flavors cooked along with white pumpkin. The Goan cuisine is famous for its seafood and spicy flavor that are ground with whole spices. The cuisine also has slight influence with Portuguese as well.', '["200 grams Vellai Poosanikai (Ash gourd/White Pumpkin) , skin peeled and chopped small", "1 Onion , chopped", "Salt , to taste", "1 Lemon juice", "2 sprig Coriander (Dhania) Leaves , chopped", "Oil", "Ingredients for Grind", "1/4 cup Fresh coconut , grated", "1 teaspoon Cumin seeds (Jeera)", "1 inch Ginger , chopped", "4 cloves Garlic , chopped", "1 teaspoon Turmeric powder (Haldi)"]'::jsonb, ARRAY['salt', 'ginger', 'coconut', 'cloves garlic', 'coriander (dhania) leaves', 'onion', 'lemon', 'cumin seeds (jeera)', 'vellai poosanikai (ash gourdwhite pumpkin) skin', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Goan Style Caldinho de Abobora Branca Recipe, pressure cook the pumpkin with water and salt for about 1 whistle till it is just done.Meanwhile grind the ingredients that are mentioned in the list like the coconut, cumin seeds, ginger, garlic and turmeric powder with little water to form a smooth paste.Once the pumpkin is cooked keep it aside.", "Heat a flat skillet with oil, add onions and saute until they turn translucent.Once done add ground paste and cook for at least 15 minutes till the masala is cooked well.", "Add cooked pumpkin along with the water and stir well.", "Check for salt.", "Sprinkle lemon juice and serve hot with chopped coriander leaves.Serve the Goan Style Caldinho de Abobora Branca Recipe along with\u00a0Steamed Rice\u00a0and\u00a0Potato Vindaloo\u00a0\u00a0to make a complete meal."]'::jsonb, 35, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Goan_Style_Caldinho_de_Abobora_Branca_Recipe_Mild_Curry_of_white_Pumpkin.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1045.Goan_Style_Caldinho_de_Abobora_Branca_Recipe_Mild_Curry_of_white_Pumpkin.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Matar Besan And Paneer Cheela Recipe -Green Peas & Paneer Crepes', 'matar-besan-and-paneer-cheela-recipe-green-peas-paneer-crepes', 'Cheelas are thin crepes or dosas which are usually made with Besan as the base ingredient. Its takes very little time to prepare as these ingredients are almost always available in Indian kitchens.', '["1 cup Green peas (Matar) , steamed", "1 cup Gram flour (besan)", "1/2 cup Paneer (Homemade Cottage Cheese) , grated", "1 teaspoon Ginger , roughly chopped", "2 Green Chillies , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Salt", "2 Oil , for cooking cheela", "1/2 teaspoon Salt", "2 teaspoons Oil , for pan roasting"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'ginger', 'sunflower oil pan roasting', 'paneer', 'green peas (matar)', 'gram flour (besan)', 'sunflower oil cheela', 'turmeric powder', 'green chillies']::text[], '["To begin making the Matar Besan And Paneer Cheela Recipe, add the Green Peas/Matar, green chillies and ginger into the mixer grinder, add water and make a thick puree.Add the matar paste in a large mixing bowl.", "Into the bowl, add besan, grated cheese, turmeric powder, cumin powder and salt.", "Stir in water and whisk well to make a thick cheela batter.Preheat a pan over medium heat.", "Take a medium scoop of matar and paneer cheela batter and drop in the center of the pan and gently spread to make cheela.", "You can adjust the thickness of the cheela to suit your taste.Drizzle oil from the sides and cook the matar besan cheela until you see golden spots on all sides.Once the bottom side is roasted well, carefully flip the matar paneer besan cheela with a spatula and roast the other side by adding few drops of oil from sides again.", "Transfer the Matar Besan And Paneer Cheela to a serving plate and serve hot.", "Serve\u00a0Matar Besan And Paneer Cheela with\u00a0Tomato Onion Chutney,\u00a0Tomato Garlic Chutney\u00a0or any other chutney of your choice and\u00a0Masala Chai\u00a0for your breakfast or as a tea time snack."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Matar_Paneer_Cheela_Recipe_Green_Peas_Paneer_Crepes-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1046.Matar_Paneer_Cheela_Recipe_Green_Peas_Paneer_Crepes-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Parsi Style Chicken Mahivalla Recipe', 'parsi-style-chicken-mahivalla-recipe', 'Parsi Style Chicken Mahivalla Recipe is a delicious Parsi bake, with layers of chicken, nuts, almonds, and caramelised onions topped off with a rich cream.', '["750 grams Chicken , cut into big pieces", "2 cups Whole Almonds (Badam) , blanch, slice and fried", "1 cup Sultana Raisins , fried", "5 Caramelized onions", "8 Green Chillies , finely chopped", "225 grams Double Cream", "Coriander (Dhania) Leaves , a bunch, chopped", "10 Whole Eggs", "1 Onion , sliced fine and fried", "2 tablespoon Oil", "2 teaspoon Ginger Garlic Paste", "1 teaspoon Red Chilli powder", "Salt , to taste"]'::jsonb, ARRAY['s chicken', 's whole almonds', 'badam', 'sultana raisins', 'caramelized onions', 'reen chillies', 's double cream', 'coriander', 'dhania', 'whole eggs', 'onion', 'oil', 'ginger garlic paste', 'red chilli powder', 'salt']::text[], '["To begin the preparation of Parsi Style Chicken Mahivalla, first wash and clean the chicken pieces.", "Rub with ginger garlic paste all over in a mixing bowl.", "Take an oven tray and add the fried onions in the tray and place the chicken pieces.", "Cover with foil and cook in a preheated oven, 350 degrees, for approx I hour or until tender.Divide all the ingredients, into two parts.", "Set the eggs aside.", "Now take an ovenproof dish\u00a0 and place a layer of chicken, sprinkle with fried almonds, raisins, chilies and coriander and lastly the fried onions.Pour half the cream all over such that it covers the chicken well and repeat to make a second layerBreak the eggs and spread them on top of the dish and bake in oven till eggs are set.Serve Parsi Style Chicken Mahivalla as a standalone meal along with\u00a0Lavender Lemonade Cooler Recipe\u00a0for a simple Sunday brunch."]'::jsonb, 75, 'Parsi', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/shaheen_ali/Parsi_Mahivalla_Baked_Chicken_In_Cream.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1047.Parsi_Mahivalla_Baked_Chicken_In_Cream.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Instant Sooji Oats Dhokla Recipe - Steamed Semolina & Oats Dhokla', 'instant-sooji-oats-dhokla-recipe-steamed-semolina-oats-dhokla', 'Instant Sooji Oats Dhokla Recipe is served as a nutritious breakfast. This recipe has a twist to the original recipe with the addition of oats making it wholesome and nutritious.', '["1 cup Sooji (Semolina/ Rava) , roasted", "1/2 cup Instant Oats (Oatmeal)", "1/2 cup Curd (Dahi / Yogurt)", "1 teaspoons Enos Fruit Salt", "Salt , to taste", "Red Chilli powder , for sprinkling", "1 tablespoons Oil , plus extra oil for greasing", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Sesame seeds (Til seeds)", "1/4 teaspoon SSP Asafoetida (Hing)", "2 Green Chillies , slit", "5 Curry leaves", "Fresh coconut , grated", "Coriander (Dhania) Leaves , a few, chopped"]'::jsonb, ARRAY['salt', 'green chillies', 'mustard seeds', 'asafoetida (hing)', 'coconut', 'coriander (dhania) leaves', 'curry leaves', 'curd', 'sesame seeds (til seeds)', 'sooji (semolina rava)', 'enos fruit salt', 'sunflower oil plus oil greasing', 'red chilli powder sprinkling', 'instant oats (oatmeal)']::text[], '["To begin making the Instant Sooji Oats Dhokla Recipe, add the roasted sooji, instant oats, yogurt, salt to taste in a bowl.", "Add little water at a time and stir to make a thick batter.Allow the batter to rest for 5 minutes and add enos salt.", "Stir well to combine.Prepare the\u00a0steamer\u00a0by pouring water and preheating it on medium heat.", "Grease the\u00a0dhokla pans\u00a0with a little oil.Pour the dhokla batter into the greased dhokla plates.", "Sprinkle some chilli powder over the dhokla and place in dhokla steamer.Cover the steamer and let it steam for about 10-15 minutes until a tester, like a butter knife, when inserted comes out clean.", "Once done turn off the heat.", "Remove the stand from the steamer and allow it to rest for a couple of minutes.Cut the\u00a0Sooji Oats Dhokla \u00a0into squares or diamonds and arrange them on a serving platter and keep aside.Into a preheated pan add oil.", "Once the oil is hot add the mustard seeds, sesame seeds and asafoetida.", "Allow the seeds to crackle.Once done add the green chillies, curry leaves.", "Stir for a few seconds and turn off the heat.", "Spread the seasoning over the Sooji Oats Dhokla.", "Garnish with a few chopped coriander leaves and grated coconut and serve.", "Serve this\u00a0Instant Sooji Oats Dhokla Recipe - Steamed Semolina & Oats Dhokla\u00a0with\u00a0Green Chutney\u00a0and\u00a0Masala Chai\u00a0for breakfast or a tea time snack."]'::jsonb, 50, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Instant_Sooji_Oats_Dhokla_Recipe_Video_For_Breakfast_Evening_Snack_15_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1048.Instant_Sooji_Oats_Dhokla_Recipe_Video_For_Breakfast_Evening_Snack_15_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Jolada Roti Recipe - Jowar Bhakri', 'jolada-roti-recipe-jowar-bhakri', 'Jolada roti or Jowar bhakri is a must in any North Karnataka house. It is an unleavened Indian bread made out of jowar (Sorghum), which is not just delicious to taste but also contains good source of nutrients. The Jolada roti is a staple diet of most of the districts of North Karnataka, where it is eaten with pulse curries such as Jhunka, Enne Gai or with assorted chutneys. It is gluten free and is diabetic friendly dish. It’s a delicious and healthy flatbread which is also very low in calories. Do try the recipe and make it a part of your everyday meal if you prefer healthy options.', '["1-1/2 cup Jowar Flour (Sorghum)", "1/2 cup Rice flour", "1 cup Water", "1 teaspoon Salt", "1 teaspoon Oil"]'::jsonb, ARRAY['salt', 'jowar flour (sorghum)', 'water', 'rice flour', 'sunflower oil']::text[], '["To begin making Jolada roti, heat water in a pan and add salt and oil to the water.", "Mix it well.", "When it starts boiling, add the rice flour and mix continuously to avoid any lumps till all the water is absorbed.Once the water is absorbed, turn off the heat and allow it cool for 5 minutes.After 5 minutes, add the jowar flour to the cooked rice flour and knead well.", "Keep adding little hot water at a time until the dough becomes soft and non-sticky .Knead properly, as we will make the roti\u2019s immediately without giving any resting time to the dough.Keep the dough covered with clean damp cloth so that it does not dry.", "The next step is to cook the rotis.", "Keep a iron tawa/griddle on medium flame.Dust your rolling surface with little whole wheat flour.Now we will start making the rotis using our hands.", "Divide the dough into 6 - 8 equal portions and roll out a portion of the dough into a round and thick roti using your hands.", "You can shape the roti by pressing out a circle with your fingers as well.Place the roti over the preheated skillet and cook it for a few seconds on one side or till a few bubbles appear on top.Turn over the roti and cook the other side for a few more seconds.", "Lift the roti with tongs and roast over the direct flame till brown spots appear on both the sides.Similarly, prepare the remaining Jolada Rotis.Serve\u00a0Jolada Roti Recipe (Jowar Bhakri) along with\u00a0Karnataka Style Badanekai Yennegai Gojju Recipe (Stuffed Brinjal Recipe),\u00a0a bowl of\u00a0Yogurt (Curd)\u00a0and\u00a0Uchellu Chutney\u00a0for North Karnataka inspired meal."]'::jsonb, 50, 'North Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Jolada_Rotti__Jowar_Bhakri.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1049.Jolada_Rotti__Jowar_Bhakri.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Murungai Keerai Sambar Recipe - Drumstick Leaves Sambar', 'murungai-keerai-sambar-recipe-drumstick-leaves-sambar', 'Murungai Keerai Sambar Recipe is a delicious sambar made from drumstick leaves also known as Moringa leaves that is cooked along with sambar onions, mooli, sambar powder in tamarind water. It is very important to use a homemade sambar powder to get the best taste from the Murungai Keerai Sambar Recipe.', '["1 cup Arhar dal (Split Toor Dal)", "1 cup Tamarind Water", "200 grams Drumstick Leaves (Moringa/Murungai Keerai)", "1 Mooli/ Mullangi (Radish) , cut into dices", "1 cup Pearl onions (Sambar Onions) , halved", "2 tablespoons Sambar Powder", "Salt , to taste", "1 tablespoon Ghee", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon SSP Asafoetida (Hing)"]'::jsonb, ARRAY['salt', 'arhar dal (split toor dal)', 'tamarind water', 'drumstick leaves (moringamurungai keerai)', 'mooli mullangi (radish) dices', 'ghee', 'mustard seeds', 'asafoetida (hing)', 'pearl onion (sambar onion)', 'sambar powder']::text[], '["To begin making the Murungai Keerai Sambar Recipe - Drumstick Leaves Sambar, first prep all the ingredients and keep them ready.Into a pressure cooker, add the tamarind water, onion, mooli,\u00a0Murungai Keerai, salt and sambar powder.", "Add 1 cup of water and pressure cook for 2 whistles.Turn off the heat and release the pressure immediately, to prevent the\u00a0Murungai Keerai from getting over cooked.", "Into a pressure cooker, add the toor dal along with 2-1/2 cups of water, turmeric powder and pressure cook for 2 whistles.", "After 2 whistles, turn the heat to low and simmer for 4 to 5 minutes and turn off the heat.Allow the pressure to release naturally.", "Once released, open the pressure cooker and mash the dal well using a potato masher.Add the cooked dal into the\u00a0Murungai Keerai Sambar masala and stir well.", "Check the salt and adjust accordingly.", "Heat ghee in a tadka pan over medium heat; add the mustard seeds and allow it to cracke.", "Add the asafoetida and curry leaves and turn off the heat.Pour this seasoning over the\u00a0Murungai Keerai Sambar and give it a brisk boil for a couple of minutes and turn off the heat.Transfer the\u00a0Murungai Keerai Sambar to a serving bowl and serve hot.Serve the\u00a0Murungai Keerai Sambar Recipe, along with steamed rice,\u00a0cabbage poriyal\u00a0and a\u00a0Carrot Cucumber Tomato Salad with Lemon and Coriander Recipe\u00a0for a classic south indian lunch or dinner.", "You can also pack the\u00a0Murungai Keerai Sambar into a lunch box by mixing it along with rice."]'::jsonb, 35, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/admin/Murungai_Keerai_Sambar_Recipe__Drumstick_Leaves_Sambar.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1050.Murungai_Keerai_Sambar_Recipe__Drumstick_Leaves_Sambar.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Corn Methi Malai Gravy Recipe', 'corn-methi-malai-gravy-recipe', 'Corn Methi Malai gravy is a rich and creamy classic Punjabi Style Gravy dish that bodes well with any kind of bread such as Phulkas, Naans or Kulchas.', '["2 cups Methi Leaves (Fenugreek Leaves)", "1/2 cup Sweet corn", "1 Onion , finely chopped", "2 Tomatoes , finely chopped", "15 Cashew nuts , soaked in warm water for 15 minutes", "1/2 cup Fresh cream", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Amchur (Dry Mango Powder)", "1/2 teaspoon Sugar", "2 teaspoons Butter (Salted)", "2 cloves Cardamom (Elaichi) Pods/Seeds", "1 teaspoon Cumin seeds (Jeera)", "1/2 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "3 Whole Black Peppercorns", "3 Whole Black Peppercorns"]'::jsonb, ARRAY['tomato', 'amchur (dry mango powder)', 'methi leaves (fenugreek leaves)', 'red chilli powder', 'black peppercorns', 'cashews water', 'sugar', 'onion', 'cumin seeds (jeera)', 'cinnamon stick (dalchini)', 'cloves cardamom (elaichi) podsseeds', 'sweet corn', 'turmeric powder', 'cloves (laung)', 'butter']::text[], '["To begin making Corn Methi Malai Recipe,\u00a0\u00a0the first step is to wash the fenugreek leaves/methi leaves thoroughly and roughly chop them.Soak the cashew nuts in warm water for a minimum of 15 minutes.", "In a pressure cook add the sweet corn along with 2 tablespoons of water and pressure cook for 1 whistle.", "Turn off the flame and allow the pressure to release naturally.", "Drain the water and keep the corn aside.", "In a pan, heat oil on medium flame.", "Once the oil is hot, add chopped onions and saute until translucent.Next add chopped tomatoes and cook until the tomatoes are soft and mushy.", "Turn off the flame and allow the mixture to cool.", "Add the cooked tomatoes and onions to a mixer along with the soaked cashews and grind everything together to form a smooth paste.", "Keep aside.In a heavy bottomed pan, heat butter on low flame.", "Once the butter becomes frothy, add the spices - cardamom, cumin seeds, cinnamon, cloves and black peppercorns.Saute in the butter until the spices turn aromatic.", "Next add the ground onion tomato mixture, required amount of salt, turmeric powder, chilli powder and dry mango powder to it.Mix and cook for a minute until raw smell of the spices go away.Now add roughly chopped methi leaves and cooked corn kernels.", "Stir and cook simmered on a medium flame until oil separates.Finally add sugar and cream to the Corn Methi mixture, stir well and cook on a completely low flame for two minutes.", "Turn off the flame.", "The delicious corn methi malai gravy is ready.", "Serve\u00a0Corn Methi Malai Gravy Recipe\u00a0along with hot\u00a0Phulkas\u00a0or\u00a0Naan\u00a0along with a\u00a0Kala Chana Salad\u00a0and\u00a0Lauki Raita\u00a0to make it a complete\u00a0Sunday night dinner."]'::jsonb, 30, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swathynandhini/Methi_Malai_Matar_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1051.Methi_Malai_Matar_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lemon Thyme Rasam Recipe', 'lemon-thyme-rasam-recipe', 'Lemon Thyme Rasam Recipe is a wonderful twist to one of the most regular side dish of South India - rasam. Rasam is a part of a traditional South Indian household, served with rice, poriyal and appalam.  Thyme is a beneficial herb added into this rasam recipe with its positive benefits of smell, flavour and digestive properties.', '["1 cup Tamarind Water", "1/4 cup Arhar dal (Split Toor Dal)", "2 teaspoons Rasam Powder", "1/4 teaspoon Turmeric powder (Haldi)", "1 Tomato , diced", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Black pepper powder", "1/4 teaspoon Asafoetida (hing)", "1 tablespoon Fresh Thyme leaves", "5 Curry leaves , chopped finely", "Salt , to taste", "Water , as needed", "1 tablespoon Lemon juice", "2 teaspoons Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "2 Curry leaves"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'arhar dal (split toor dal)', 'tme leaves', 'tamarind water', 'asafoetida (hing)', 'ghee', 'mustard seeds', 'water', 'curry leaves', 'lemon', 'rasam powder', 'cumin seeds (jeera)', 'black pepper powder', 'turmeric powder']::text[], '["To prepare\u00a0Lemon Thyme Rasam Recipe, keep the tamarind water ready.", "Into a sauce pan, add the tamarind water,\u00a0tomatoes, rasam powder, cumin powder, pepper powder, hing, a few curry leaves and salt into a pan.", "Add the thyme leaves, stir.Bring to a boil on medium-high heat and then simmer till the tomatoes are cooked.", "Clean and wash dal and pressure cook dal with enough water with 1 cup of water and turmeric powder for 3-4 whistles.", "Turn off the flame.", "Once the pressure from the cooker is released naturally. , whisk the dal and keep it aside.Add the dal to the tamarind tomato base and bring the thyme rasam to a boil and then reduce the stove to low flame.", "Let the rasam simmer for 5 minutes or more, so that the raw taste of the chilli in the rasam powder incorporates well into the rasam.Adjust salt and simmer for 3 more minutes and turn off the heat.While the rasam is cooking, in a tadka pan, heat a teaspoon of ghee and splutter mustard and cumin seeds.", "Add curry leaves, let it crackle and take it off heat.", "Pour the tadka to the Lemon Thyme rasam.Squeeze lemon to the Lemon Thyme Rasam recipe just before serving and pair it up with rice and beetroot poriyal\u00a0recipe for lunch."]'::jsonb, 25, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sujatas/Lemon_thyme_rasam_recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1052.Lemon_thyme_rasam_recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Murungai Keerai Puttu - Drumstick Leaves Puttu Recipe', 'murungai-keerai-puttu-drumstick-leaves-puttu-recipe', 'Murungai Keerai Puttu is a breakfast dish which is made with fresh drumstick leaves. It is a traditional, healthy breakfast recipe that can also be served as evening snacks.', '["1/2 cup Ragi Flour (Finger Millet/ Nagli)", "1/2 cup Bajra Flour ( Pearl Millet)", "1 cup Rice flour", "1 cup Drumstick Leaves (Moringa/Murungai Keerai)", "Salt , as required", "Water , as required", "2 teaspoons Ghee", "1 cup Fresh coconut , grated"]'::jsonb, ARRAY['salt', 'drumstick leaves (moringamurungai keerai)', 'ghee', 'coconut', 'water', 'ragi flour (finger millet nagli)', 'bajra flour ( pearl millet)', 'rice flour']::text[], '["To begin making the Murungai Keerai Puttu recipe, heat ghee in a heavy bottomed pan.Add the drumstick leaves to it and saute for a minute until it shrinks.", "Keep aside.Add ragi flour, bajra flour and rice flour in a mixing bowl.", "Add salt to it and mix well.", "Sprinkle water little by little and rub into flour to make it crumbly.It has to be in puttu consistency.", "That is, if small amount of flour is taken and pressed in palm it has to hold shape and crumble if pressed further tightly.Add water to the base vessel of puttu maker until 3/4th and place it on stove.", "Now place the disc with holes at bottom of top cylindrical vessel.Add 3 teaspoons of coconut to the cylindrical vessel, followed by 2 teaspoons of sauteed drumstick leaves and half of the prepared puttu flour.Layer it again with coconut, drumstick leaves and remaining puttu flour until it reaches top.", "Close with lid and place the cylindrical vessel on top of base vessel on stove.Steam the Murungai Keerai Puttu for 10 minutes on medium flame or until the top starts releasing steam.Once done, allow\u00a0Murungai Keerai Puttu to cool and remove the puttu from cylindrical vessel using the stick that accompanied the puttu maker.The healthy drumstick leaves puttu is ready to serve.", "Serve\u00a0Murungai Keerai Puttu\u00a0along with\u00a0Kerala Kadala Curry\u00a0for a healthy breakfast meal or you can also relish it for lunch."]'::jsonb, 20, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swathynandhini/DRUMSTICK_LEAVES_PUTTU_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1053.DRUMSTICK_LEAVES_PUTTU_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Avarekalu Usli Recipe', 'avarekalu-usli-recipe', 'Hyacinth Beans are called the Avarekalu in Kannada. Many dishes are prepared using Avarekalu during the winter months and Avarekalu Usli Recipe is one of the famous ones from the state of Karnataka.', '["2 cups Avarekai (Broad Beans)", "1 Onion , finely chopped", "1 Green Chilli", "1/2 teaspoon Turmeric powder (Haldi)", "4 tablespoons Fresh coconut", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon White Urad Dal (Split)", "2 Dry Red Chillies", "1 sprig Curry leaves", "1 tablespoon Coriander (Dhania) Leaves , finely chopped", "2 teaspoons Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'green chilli', 'coconut', 'mustard seeds', 'coriander (dhania) leaves', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'onion', 'cumin seeds (jeera)', 'avarekai (broad beans)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making\u00a0Avarekalu Usli Recipe, wash and pressure cook the avarekalu by adding 1 cup of\u00a0 water into a pressure cooker and cook it for 2 whistles and keep aside for the pressure to release naturally.Make a coarse mix of grated coconut, green chilli, cumin seeds using a mixer grinder and keep aside.Heat oil in a pan, add the mustard seeds, urad dal, red chillies and let it crackle and the dal to turn golden brown and crisp.Add the curry leaves and saute for a few seconds.", "Add the chopped onion, saute until the onions soften and turn golden in colour.Once the onions have softened, add the cooked avarekalu, season with salt and saute until it all comes together.Add the prepared coconut mix, coriander leaves, mix well and switch off the heat.Serve the\u00a0Avarekalu Usli Recipe\u00a0along with\u00a0Beetroot Poriyal,\u00a0Thakkali Vengaya Sambar, Rice, Papad for a wholesome sunday lunch."]'::jsonb, 20, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Avarekalu_Usili_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1054.Avarekalu_Usili_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ringna Batata Nu Shaak Recipe- Aloo Baingan Ki Sabzi Recipe', 'ringna-batata-nu-shaak-recipe-aloo-baingan-ki-sabzi-recipe', 'Ringna Batata Nu Shaak also known as Aloo Baingan ki Sabzi is a popular sabzi in every Gujarati household.', '["3 cups Brinjal (Baingan / Eggplant) , cubed", "1 cup Potatoes (Aloo) , peeled and cubed", "1/2 teaspoon Kalonji (Onion Nigella Seeds)", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 cup Homemade tomato puree", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Sugar", "2 tablespoons Coriander (Dhania) Leaves , chopped", "2 teaspoons Oil", "Salt , to taste", "2 teaspoons Oil", "Salt , to taste"]'::jsonb, ARRAY['s brinjal', 'baingan / eggplant', 'potatoes', 'aloo', 'kalonji', 'onion nigella seeds', 'cumin seeds', 'jeera', 'homemade tomato puree', 'turmeric powder', 'haldi', 'red chilli powder', 'coriander powder', 'dhania', 'garam masala powder', 'sugar', 's coriander', 's oil', 'salt']::text[], '["To begin making the Ringna Batata nu Shaak | Aloo Baingan ki Sabzi recipe,\u00a0\u00a0we will first heat oil in a pressure cooker on medium heat.", "Add cumin seeds, nigella seeds and allow them to crackle.", "Add the tomato puree, turmeric powder, red chilli powder, coriander powder, garam masala powder and saut\u00e9 until it comes to a single boil.", "Stir in the potatoes and brinjal adding 3/4 cup of water and sugar, salt to taste.", "Close the pressure cooker and pressure cook for 4 whistles.", "Turn off the flame.", "Allow the pressure to release naturally.", "Once the pressure has released open the lid\u00a0the whole dish will look a little mushy and have a little gravy that is formed from the tomatoes, the softened brinjal and the starch from the potatoes.Stir in the chopped coriander leaves and serve.Serve the Aloo Baingan Ki Sabzi | Ringna Batata Nu Shaak along with\u00a0Methi Thepla\u00a0or\u00a0Phulka''s\u00a0and\u00a0Boondi Raita Recipe Spiced With Black Salt\u00a0for a simple lunch."]'::jsonb, 50, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Archana_Doshi/Aloo_Baingan_Ki_Sabzi_Batata_Ringna_Nu_Shaak_Video_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1055.Aloo_Baingan_Ki_Sabzi_Batata_Ringna_Nu_Shaak_Video_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Mutton Chops Kuzhambu Recipe-Mutton Chops Curry', 'chettinad-mutton-chops-kuzhambu-recipe-mutton-chops-curry', 'Chettinad Mutton Chops Kuzhambu is a spicy and delicious mutton chops dish which has a twist of flavor packed Chettinad style curry. If you are a spice lover you should definitely try this recipe for your weekend dinners. Its a perfect dish to serve during the house parties and your family and friends will love it for sure.', '["500 grams Mutton , chops", "2 Onions , finely chopped", "3 Tomatoes", "1 tablespoon Ginger Garlic Paste", "1 Green Chilli", "1 teaspoon Cumin seeds (Jeera)", "1-1/2 teaspoon Whole Black Peppercorns", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 tablespoon Coriander (Dhania) Seeds", "2 Dry Red Chillies", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "4 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 Bay leaf (tej patta)", "Salt , to taste", "2 tablespoon Oil", "1 teaspoon Red Chilli powder", "1 teaspoon Salt", "Mutton , as required", "1 Onion , finely chopped", "1 teaspoon Cumin seeds (Jeera)", "Coriander (Dhania) Leaves , for garnish"]'::jsonb, ARRAY['mutton chops', 'tomato', 'salt', 'green chilli', 'mustard seeds', 'bay leaf (tej patta)', 'coriander (dhania) leaves', 'red chilli powder', 'black peppercorns', 'ginger garlic paste', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'dry red chillies', 'cinnamon stick (dalchini)', 'mutton', 'coriander powder', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Chettinad Mutton Chops Kuzhambu recipe, first clean and wash the mutton chops well.", "Marinate the chops with 1 teaspoon red chili powder and salt for about 2 to 4 hours.To the marinated mutton add 1 teaspoon cumin seeds and 1 finely chopped onions and 1 cup water and pressure cook for 3 to 4 whistles.Chop onions fine and puree them along with green chili.", "Chop tomatoes and puree it separately.", "Keep them aside.Heat a wide pan.", "Dry roast cumin seeds, black pepper corns, coriander seeds, dried red chilies and mustard seeds.Roast them on low flame for about a minute until it starts to splutter.", "Be careful, these whole spices can burn easily.", "So make sure you reduce the flame and roast it for about a minute.", "Remove from flame, let it cool and then grind into powder in a mixer grinder.Heat 2 tablespoons oil in a\u00a0wide pan.", "Add cloves, cinnamon stick and bay leaf.Add onion green chili paste and saut\u00e9 till raw smell of the onion paste is gone.Add ginger garlic paste and cook till the raw smell of the paste is gone.", "Now add tomato puree and cook till tomato puree thickens and oil separates from the edges of the pan.Once it is done, add spice powders including red chili powder, turmeric powder, coriander powder and the powdered spice mix along with salt.", "Cook for about 1 minute.Add cooked mutton chops along with the water in it.", "Simmer and cook for about 25 minutes.", "Add water if needed.", "Check for salt and it is ready to be served.Serve Chettinad Mutton Chops\u00a0Kuzhambu\u00a0with Steamed Rice,\u00a0Dosa\u00a0or\u00a0Phulkas\u00a0for weekend dinners."]'::jsonb, 70, 'Chettinad', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Chettinad_Mutton_Chops_Kozhumbhu__Mutton_Chops_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1056.Chettinad_Mutton_Chops_Kozhumbhu__Mutton_Chops_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Khandeshi Dal Recipe', 'khandeshi-dal-recipe', 'Khandeshi Dal is definitely a new name for almost everyone, specially who is not familiar with the typical Maharashtrian cuisine. Yes, Khandeshi Cuisine is one of the Maharashtrian Regional Cuisine. Khandeshi cuisine is quite spicy, simple and flavorful. I''m going to share, one of the simple but delicious recipe of Dal today from a unique Khandeshi Cuisine. It is a good replacement to the regular dal we cook in our kitchen. The aroma of the Pakka-Masala being roasted is truly amazing and that''s the essence of this recipe. Try it once and I am sure you would love to add this Dal more often in your daily meal.', '["2 tablespoons Green Moong Dal (Whole)", "2 tablespoons Pink Masoor Dal (Split)", "2 tablespoons Arhar dal (Split Toor Dal)", "2 tablespoons White Urad Dal (Split)", "2 tablespoons Chana dal (Bengal Gram Dal)", "1/4 teaspoon Turmeric powder (Haldi)", "Oil , as required", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies", "1 Bay leaf (tej patta)", "3 teaspoon Lemon juice", "3 tablespoon Coriander (Dhania) Leaves , chopped", "Salt , to taste", "1/4 cup Dry coconut (kopra) , grated", "1/2 cup Onions , sliced", "1-1/2 tablespoon Coriander Powder (Dhania)", "Cumin powder (Jeera)", "3 Kashmiri dry red chillies", "3 Cloves (Laung)", "2 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "3 Whole Black Peppercorns", "4 cloves Garlic"]'::jsonb, ARRAY['cumin powder (jeera)', 'coriander (dhania) leaves', 'black peppercorns', 'cloves garlic', 'white urad dal (split)', 'onion', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil', 'salt', 'arhar dal (split toor dal)', 'cardamom (elaichi) podsseeds', 'dry coconut (kopra)', 'dry red chillies', 'mustard seeds', 'pink masoor dal (split)', 'lemon', 'green moong dal', 'bay leaf (tej patta)', 'kashmiri dry red chillies', 'cinnamon stick (dalchini)', 'coriander powder', 'cloves (laung)']::text[], '["To begin making the Khandeshi Dal recipe, we will firstly begin with the pakka masala for the dal.Heat the oil in a wide pan.", "Add grated coconut and sliced onions, saut\u00e9 for 3 to 4 minutes.Add dry red chillies, coriander cumin powder, cloves, cardamom, cinnamon and black peppercorn.", "Saute for another 2 to 3 minutes on low-medium flame.Add garlic and saut\u00e9 on medium flame for few seconds.", "Turn off the stove.", "Let it cool down completely.Once cooled, blend in a mixer or in a blender to a smooth powder/paste and keep it aside.The next step is to prepare the dal.", "Clean, wash and soak the mix dals and moong in a water for atleast 30 to 40 minutes.Pressure cook dal and moong in a cooker with 2 cups of water, salt and turmeric powder.", "Boil Dal & Moong well.Add 1/2 of the prepared Pakka masala powder/paste into dal, mix well and keep it aside.For tempering, heat oil in a tadka pan and add mustard seeds.", "When the seeds crackle, add the dry red chillies and bayleaf.", "Saut\u00e9 on medium flame.Add the prepared Dal mixture, mix well and cook.", "Cook for 3 to 4 minutes, and stir continuously.Add some more Pakka masala if you want more flavors and spice.", "Add lemon juice, chopped cilantro and adjust the salt accordingly.Cook on low flame for a couple of minutes more and turn off the stove.", "Garnish with some chopped cilantro and serve it immediately.Serve Khandeshi Dal with\u00a0Boondi Raita,\u00a0Phulkas\u00a0or steamed rice for a perfect weekday lunch."]'::jsonb, 40, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Rupal_Patel/Khandeshi_Dal.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1057.Khandeshi_Dal.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Carrot Cauliflower Peas Sabzi Recipe - Gajar Gobi Matar Sabzi', 'carrot-cauliflower-peas-sabzi-recipe-gajar-gobi-matar-sabzi', 'Carrot Cauliflower Peas Sabzi Recipe is made in a minimalist way and yet is full of flavour and tastes delicious. Carrots, cauliflower and peas are sauteed and simmer in a oil flavoured with ajwain, an whole spices like pepper, bay leaves and cardamon. It''s a simple and saatvik recipe that brings in the flavours of the vegetables into the palate.', '["1 teaspoon Coconut Oil , for cooking", "1/2 teaspoon Ajwain (Carom seeds)", "2 Bay leaves (tej patta)", "2 inch Cinnamon Stick (Dalchini)", "2 Carrots , cut into 1/2 inch sticks", "2 cups Cauliflower (gobi)", "1 cup Green peas (Matar)", "1 teaspoon Black pepper powder", "Salt , to taste"]'::jsonb, ARRAY['salt', 'bay leaves (tej patta)', 'ajwain (carom seeds)', 'cauliflower (gobi)', 'green peas (matar)', 'carrot', 'cinnamon stick (dalchini)', 'black pepper powder', 'coconut oil']::text[], '["To begin making Carrot Cauliflower Peas Sabzi Recipe first\u00a0Prep all the required ingredients.Heat coconut oil in a pan and once the oil is hot add in all the whole spices, ajwain seeds, bay leaves, cinnamon sticks and saute till the whole spices release a nice aroma.Add in the carrots, cauliflower florets and green peas.", "Saute for a minute.Season with salt and sprinkle some water in the pan and stir.Cover and cook till the Gajar and Gobi are almost cooked and until all the flavours are incorporated into the Carrot Cauliflower Peas Sabzi Recipe.", "Finally once done, stir in the black pepper powder and toss well to combine.", "Once done, check the taste of the\u00a0Gajar Gobi Matar Sabzi and adjust salt accordingly.Serve this delicately flavoured Carrot Cauliflower Peas Sabzi Recipe with\u00a0Lahsuni Palak Dal,\u00a0\u00a0Ragi Wheat Phulka\u00a0and\u00a0Methi Raita Flavoured With Garlic\u00a0for a nice comforting diabetic meal."]'::jsonb, 25, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/cauliflower_peas_carrot_sabzi/Cauliflower_Peas_Carrot_Sabzi_No_onion_no_garlic_Ayurvedic_Recipe_15_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1058.Cauliflower_Peas_Carrot_Sabzi_No_onion_no_garlic_Ayurvedic_Recipe_15_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Masala Akki Roti Recipe - Spicy Rice Flour Flatbread', 'masala-akki-roti-recipe-spicy-rice-flour-flatbread', 'The Masala Akki Roti Recipe is a delicious spicy flat bread from Karnataka that is made from rice flour. The akki roti makes a great vegan and gluten free breakfast option. Made from rice flour, shredded vegetables and spices, the Akki Roti makes for an excellent tea time snack when you have sudden guests at home.', '["2 cups Rice flour", "1/4 cup Fresh coconut , grated", "1 Carrot (Gajjar) , grated", "1 Green Bell Pepper (Capsicum) , finely chopped", "1/4 cup Dill leaves , finely chopped", "1/4 cup Cabbage (Patta Gobi/ Muttaikose) , finely chopped", "1 Onion , finely chopped", "1 inch Ginger , finely chopped", "2 Green Chillies , finely chopped", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "Salt , to taste", "Oil , to cook"]'::jsonb, ARRAY['salt', 'ginger', 'dill leaves', 'coconut', 'asafoetida (hing)', 'carrot', 'onion', 'cumin seeds (jeera)', 'green bell pepper (capsicum)', 'rice flour', 'green chillies', 'cabbage (patta gobi muttaikose)', 'sunflower oil']::text[], '["To begin making the Masala Akki Roti Recipe, add rice flour, carrots,cabbage,capsicum,onion, coconut, cumin seeds, green chillies, ginger, asafoetida and salt to taste into a large mixing bowl.Mix all the ingredients well and then knead the dough adding little warm water at a time.", "The dough should be soft.", "We will require around 1 cup of water to knead the dough.Once the dough comes to shape cover and allow Masala Akki Roti dough to rest for 10-15 mins.After 15 minutes grease your palm and\u00a0 make large lemon size portions of the akki roti dough and keep aside.Pre heat a non stick tawa or roti pan.Now wet a muslin cloth with water or grease a plantain leaf.", "Grease your palm and place a portion of the dough at the center of the cloth.", "Using your fingers pat the dough to make circular discs of medium thickness.", "Make three small holes in the akki roti for even cooking of the akki roti.Preheat a skillet over medium heat and grease the skillet.", "Carefully invert the akki roti onto the preheated pan and peel out the cloth or the leaf.Cook the Masala Akki Roti on medium heat for a few seconds.", "Flip the roti and drizzle a teaspoon of oil around the roti and cook it on both sides until\u00a0brown spots appear.Once done, remove\u00a0 Masala Akki Roti from heat and serve warm.Serve the\u00a0Masala Akki Roti\u00a0along with\u00a0Coconut Chutney\u00a0and Ghee for a breakfast or an evening tea time snack along with a hot cup of\u00a0Filter Coffee\u00a0or\u00a0Masala Chai."]'::jsonb, 55, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Masala_Akki_Roti_Recipe_5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1059.Masala_Akki_Roti_Recipe_5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Jolada Ganji Recipe (Jowar Savoury Porridge)', 'jolada-ganji-recipe-jowar-savoury-porridge', '''Jolada'' means Jowar/sorghum, a gluten free grain. This traditional dish, the ''Jolada Mudde'' is a North Karnataka  breakfast special. It is tasty and can be cooked within a few minutes. Mixing the jowar flour in water or thin buttermilk without lumps and then adding it to the tempered mixture of green chillies , onions and curry leaves gives this dish a smooth texture. Though this dish is popularly called as ''Mudde'' means balls /rounds , it is often served in a semi solid consistency. When less water is added they can even be shaped into balls. A healthy dish that can included in your weekly menu.', '["1/2 cup Jowar Flour (Sorghum)", "1-1/2 cup Water , or buttermilk", "1 teaspoon Lemon juice , (skip if you are using buttermilk)", "Salt , to taste", "To temper", "1 tablespoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Black Urad Dal (Split)", "3 Green Chillies , finely chopped", "1 Onion , finely chopped", "1 sprig Curry leaves , roughly torn"]'::jsonb, ARRAY['salt', 'jowar flour (sorghum)', 'mustard seeds', 'lemon (skip you are using buttermilk', 'black urad dal (split)', 'curry leaves', 'onion', 'water buttermilk', 'green chillies', 'sunflower oil']::text[], '["To begin making the Jolada Ganji recipe, In a mixing bowl, add the jowar flour, salt and water or thin buttermilk.Mix well without any lumps.", "Heat a heavy bottomed kadai or pan with oil and temper with ingredients given under '' to temper''.Once tempered, add the jowar flour mixture and keep stirring over low flame.", "The mixture will thicken and turn glossy.", "Switch off.Serve Jolada Ganji along with\u00a0Mixed Vegetable Sambar\u00a0for a weekday dinner."]'::jsonb, 20, 'North Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/umar/Jolada_Mudde_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1060.Jolada_Mudde_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bajra Matar Ki Khichdi (Gluten Free Breakfast Recipe)', 'bajra-matar-ki-khichdi-gluten-free-breakfast-recipe', 'Bajra Matar Ki Khichdi is a common breakfast recipe prepared in the states of Haryana and Rajasthan. When one thinks of a salivating creamy dish for breakfast, Khichdi tops the list. Bajra Matar Ki Khichdi is a satiating dish which is beautifully flavored with spices and with a creamy consistency. Health benefits of Pearl Millets make it a perfect choice for diabetic persons and it is gluten free too. Bajra Khichdi is a wholesome option as Pearl millets are high in starch content, making it a high-energy food and an excellent source of fiber, protein, and phosphorus.', '["1 cup Bajra Flour ( Pearl Millet)", "1/2 cup Yellow Moong Dal (Split)", "1 tablespoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "1 Onion , chopped finely", "1 Tomato , chopped finely", "1 Potato (Aloo) , cubed", "1 Carrot (Gajjar) , cubed", "1/4 cup Green peas (Matar)", "1 teaspoon Red Chilli powder", "1 teaspoon Ginger Garlic Paste", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "1 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Salt", "2 tablespoon Coriander (Dhania) Leaves , chopped finely", "1/2 Lemon"]'::jsonb, ARRAY['bajra flour', 'pearl millet', 'yellow moong dal', 'split', 'oil', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'asafoetida', 'hing', 'onion', 'tomato', 'potato', 'aloo', 'carrot', 'gajjar', 'green peas', 'matar', 'red chilli powder', 'ginger garlic paste', 'coriander powder', 'dhania', 'garam masala powder', 'turmeric powder', 'haldi', 'salt', 'coriander', 'lemon']::text[], '["To prepare Bajra Matar Ki Khichdi, soak bajra in water for about 4 hours or overnight.", "Soak moong dal in water for about an hour.In a Pressure cooker, add soaked bajra, moong dal, green chilies and turmeric powder.", "Add 4 cups of water and cook over medium flame for 4 whistles.", "Ensure water is added more to get the creamy consistency.", "Bajra takes time to cook, hence cook for 4 -5 whistles depending on the pressure cooker.", "Set aside.Meanwhile, chop all the vegetables required for\u00a0Bajra Matar Ki Khichdi.In a Kadai, add oil and heat over medium flame.Once the oil is hot, add cumin seeds, mustard seeds, hing and cook until the seeds clutter.", "Cook until the cumin seeds become light brownish.Add onions and cook until they become translucent.Add tomatoes and cook until they become mushy.Now, stir in the chopped vegetables and combine them wellAdd red chili powder, coriander powder, garam masala, required salt and cook until the vegetables become soft and cooked.Combine the vegetable mixture with the gluten free bajra-dal mixture.Combine the until they are blended together and cook over low flame for about 3-4 minutesSwitch off the flame and garnish with coriander leaves.Add lime juice to the khichdi at the time of serving.Serve Khichdi warmly with pickle\u00a0of your choice."]'::jsonb, 290, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Bajra_Matar_Ki_Khichidi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1061.Bajra_Matar_Ki_Khichidi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Bhindi Sabzi Recipe - Potatoes Lady''s Finger Stir Fry', 'aloo-bhindi-sabzi-recipe-potatoes-lady-s-finger-stir-fry', 'Aloo Bhindi Sabzi Recipe is a combination of potatoes and lady''s finger/ Bhindi/ Okra cooked separately and combined together with spices. This sabzi makes a perfect vegetable as a side dish with phulka''s and kadhi. Different regions of India make it in many different ways, go ahead make your own modifications to the method to suit your palate.', '["500 grams Bhindi (Lady Finger/Okra) , cut into 1 inch pieces", "3 Potatoes (Aloo) , peeled and cut into wedges", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves", "1/2 teaspoon Asafoetida (hing)", "1 teaspoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "2 tablespoons Oil"]'::jsonb, ARRAY['s bhindi', 'lady finger/okra', 'potatoes', 'aloo', 'cumin seeds', 'jeera', 'curry leaves', 'asafoetida', 'hing', 'red chilli powder', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'salt', 's oil']::text[], '["To begin making the\u00a0Aloo Bhindi Sabzi Recipe, heat a tablespoon of oil in a heavy bottom pan over medium heat.Add a teaspoon of cumin seeds, allow seeds to crackle.", "Add half the curry leaves, cut potatoes along with salt, 1/2 teaspoon of turmeric powder.", "Stir to combine.Cover the pan with the lid and cook the potatoes for few minutes, stirring occasionally.Open the lid of the pan and add 1/2 teaspoon of coriander powder, red chilli powder, stir to combine.Simmer for a few more minutes and turn off the heat.", "Keep covered aside, while you cook the bhindi.*For the BhindiHeat oil in another heavy bottomed pan, add the remaining cumin seeds and allow seeds to crackle.Add the chopped bhindi, asafoetida and salt.", "Cover the pan (with lid slightly open) and allow the bhindi to simmer, stirring\u00a0occasionally.Bhindi releases moisture when cooked covered and will get\u00a0sticky.", "But after sometimes it will turn fine.Once the bhindi is slightly tender, add\u00a0 the turmeric powder, 1/2 teaspoon of coriander powder and red chilli powder.Keep the pan slightly open and cook till bhindi is done.", "The bhindi will change its color to brown.Once done, gently stir in the sauteed aloo into the bhindi and combine well.", "Cover the pan with the lid and simmer for another couple of minutes.Turn off the heat and allow the vegetable to rest in the pan, covered for another 3 to 4 minutes.", "This helps the vegetable to gain a little moisture and gather itself together.Serve this\u00a0Aloo Bhindi Sabzi\u00a0along with Phulkas or South Indian Style meal along with\u00a0Steamed Rice,\u00a0Beetroot Sambar\u00a0and a big dollop of Ghee."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Aloo_Bhindi_Sabzi_Recipe_North_indian_healthy_vegetable_recipe_25_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1062.Aloo_Bhindi_Sabzi_Recipe_North_indian_healthy_vegetable_recipe_25_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vendakkai Podi Curry Recipe - Vendakkai Poriyal', 'vendakkai-podi-curry-recipe-vendakkai-poriyal', 'Vendakkai Podi Curry also known as the Vendakkai Poriyal is a delicious South Indian dish made with the combination of fresh lady fingers spiced with sambar powder and paruppu podi. It is super simple and easy to make and absolutely delicious to eat as well.', '["1 tablespoon Gingelly oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "500 grams Bhindi/Okra/Vendaikkai , chopped small", "1 tablespoon Idli Dosa Podi (Milagai Powder)", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Sambar Powder", "Salt , to taste", "1/4 cup Fresh coconut , grated"]'::jsonb, ARRAY['gingelly oil', 'mustard seeds', 'rai/ kadugu', 'curry leaves', 's bhindi/okra/vendaikkai', 'idli dosa podi', 'milagai powder', 'turmeric powder', 'haldi', 'sambar powder', 'salt', 'fresh coconut']::text[], '["To begin with Vendakkai Podi Curry, prepare all the ingredients and keep them ready.Heat oil into a preheated pan; add the mustard seeds and allow it to crackle.", "Add curry leaves and asafoetida and saute for a few seconds.Add the cut vendakkai/ ladys finger, sprinkle some salt and give it a stir.", "Cover the pan and with the lid little ajar cook the vendakkai until done.", "Keep stirring it intermittently in between so that the vendakkai poriyal gets cooked evenly.Once 3/4 th done, stir in the sambar powder, turmeric powder and idli paruppu podi.", "Give it a stir and cover and cook the Vendakkai podi curry for another couple of minutes.Finally stir in the fresh coconut and check if more salt is needed and adjust to taste accordingly.", "Turn off the heat and transfer the Vendakkai Podi Curry to a serving bowl and serve hot.Serve\u00a0Vendakkai Podi Curry along with\u00a0Jeera rasam\u00a0and Steamed Rice for a simple and easy weeknight dinner."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Vendakkai_Podi_Curry_Recipe_Vendakkai_Poriyal_Recipe_Bhindi_Masala_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1063.Vendakkai_Podi_Curry_Recipe_Vendakkai_Poriyal_Recipe_Bhindi_Masala_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Fusion Style Paneer Malai Makhani Recipe', 'fusion-style-paneer-malai-makhani-recipe', 'Paneer Malai Makhani Recipe is a quick and simple recipe to cook for dinners or lunch boxes on weekdays. Since I love the spices of South India and Srilanka, I have fused the spices and method of cooking into this paneer malai makhani recipe.', '["200 grams Paneer (Homemade Cottage Cheese) , cubed", "1 Onion , finely sliced", "2 Tomatoes , cut in wedges", "1 teaspoon Ginger Garlic Paste", "200 ml Coconut milk", "1/4 cup Water", "1 tablespoon Coriander Powder (Dhania)", "1 teaspoon Black pepper powder", "1 teaspoon Red Chilli powder , (dajust to taste)", "1/3 teaspoon Turmeric powder (Haldi)", "1 Kokum (Malabar Tamarind) , soaked in 2 tablespoon water", "2 teaspoon Coconut Oil", "1 teaspoon Cumin seeds (Jeera)", "Curry leaves , a few", "Whole Black Peppercorns , a few, crushed", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "Coriander (Dhania) Leaves , a few sprigs for garnishing"]'::jsonb, ARRAY['tomato', 'coriander (dhania) leaves', 'coriander powder', 'paneer', 'kokum (malabar tamarind)', 'water', 'black peppercorns', 'ginger garlic paste', 'curry leaves', 'onion', 'coconut oil', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'black pepper powder', 'coconut milk', 'turmeric powder', 'red chilli powder (dajust )']::text[], '["To begin making Fusion Style Paneer Malai Makhani Recipe, prep all the ingredients needed for this recipe.In a kadai heat coconut oil, when it is hot enough, add in the cumin seeds, fenugreek seeds and peppercorns and let them sizzle.", "Wait for about 10 seconds or till sizzling, and add in the curry leaves.", "Wait till they splutter. (takes about a couple of seconds)Add the onion and saut\u00e9 for about 3-5 minutes till the onion is tender.Now add in the ginger, garlic paste, some salt and turmeric powder.", "Saut\u00e9 till the raw smell goes and appears even.Now add in the coriander powder, black pepper powder and red chilli powder, continue frying for another 2 minutes or till the spices are evenly mixed.Add the tomatoes and fry for another 2 minutes or so, till the tomatoes are softened.", "Cover the skillet and cook for 1-2 minutes till tomatoes are fully cooked.", "Add the paneer(cottage cheese) cubes and mix it well but careful not to break the cubes.Add the kokum or kokum extract, coconut milk and water.", "Adjust salt.", "Cover the pan and simmer for about 3-5 minutes on a low medium heat.", "Switch off heat and garnish Paneer Malai Makhani with fresh coriander.", "Serve\u00a0Paneer Malai Makhani Recipe with\u00a0Pudina Tawa Paratha\u00a0or\u00a0phulkas\u00a0with\u00a0Indian Style Black Chickpea Salad Recipe\u00a0for a complete meal."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/gayatrii.singh-gmail.com/paneer-malai-makhani-recipe1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1064.paneer-malai-makhani-recipe1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Gongura Pachadi Recipe - Andhra Style Sorrel Leaves Chutney', 'andhra-gongura-pachadi-recipe-andhra-style-sorrel-leaves-chutney', 'Andhra Gongura Pachadi or this Andhra style chutney made of sorrel leaves an authentic delicacy typical to Telugu cuisine. It is an important part of every festive meal or feast. Although these leaves are called different names in different regions, the nutritional properties of sorrel leaves remain constant.', '["Ingredients to roast", "10 Dry Red Chillies , adjust according to your taste", "2 tablespoons Coriander (Dhania) Seeds", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "300 grams Sorrel Leaves (Gongura)", "2 tablespoons Sesame (Gingelly) Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Black Urad Dal (Split)", "2 to 3 Dry Red Chillies", "3 to 4 cloves Garlic , crushed (optional)"]'::jsonb, ARRAY['ingredients to roast', 'dry red chillies', 's coriander', 'dhania', 'methi seeds', 'fenugreek seeds', 's sorrel leaves', 'gongura', 's sesame', 'gingelly', 'mustard seeds', 'rai/ kadugu', 'black urad dal', 'split', 'to 3 dry red chillies', 'to 4 cloves garlic']::text[], '["To begin making the Andhra Gongura Pachadi, first pick the sorrel/ gongura leaves from the stems, wash them thoroughly, dry it with a kitchen towel.", "Once dry, chop the gongura leaves and keep aside.Next, heat a pan over a medium heat and roast the dry red chillies, coriander seeds and fenugreek seeds until they are light brown, aromatic and toasted.", "Take care not to burn themTransfer them into a plate and set them aside to cool.", "Use as many or as few red chillies as you need, depending on the quality of the chillies and your desired spice levels.", "Once cooled, add them to a mixer grinder and make a smooth powder.In the same pan; heat oil until warm; add the mustard seeds, urad dal and red chillies and allow it to crackle and the dal to turn golden brown and crisp.Stir in the crushed garlic and saute for a few seconds until you can smell the aroma coming through.", "Once once, add the chopped gongura leaves, salt to taste and the ground powder.Keep stirring until the Gongura leaves become soft; it will take less than a minute.", "Check the taste and adjust the salt and chilli accordingly.You will also notice the Gongura Pachadi coming away from the sides of the pan and there will be a little oil residue.This is when the Gongura Pachadi is done, turn off heat and serve.You can store the\u00a0Gongura Pachadi in the refrigerator for a week and serve it along with Dosa, Idli, Cheela, Adai, Pesarattu or simply along with hot steamed rice and ghee."]'::jsonb, 25, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Andhra_Gongura_Pachadi_Recipe_-_Andhra_Style_Sorrel_Leaves_Chutney-10.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1065.Andhra_Gongura_Pachadi_Recipe_-_Andhra_Style_Sorrel_Leaves_Chutney-10.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lehsuni Methi Paneer Recipe - Garlic Methi Paneer Curry', 'lehsuni-methi-paneer-recipe-garlic-methi-paneer-curry', 'There are variety of delicious paneer dishes that you come across in restaurants, mainly in North Indian Restaurants. Lehsuni Methi Paneer dish is one of those dishes in which Paneer is cooked with Kasuri Methi and Garlic creamy gravy.', '["250 grams Paneer (Homemade Cottage Cheese)", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "3 tablespoons Curd (Dahi / Yogurt)", "1/2 cup Fresh cream", "1/2 teaspoon Garam masala powder", "1/4 teaspoon Cardamom Powder (Elaichi)", "Salt , to taste", "1 teaspoon Ghee , for cooking", "To Be Ground To Paste", "8 Cashew nuts", "4 cloves Garlic", "2 Green Chillies , chopped", "1 inch Ginger , chopped"]'::jsonb, ARRAY['salt', 'green chillies', 'ginger', 'ghee', 'paneer', 'cloves garlic', 'curd', 'cardamom powder (elaichi)', 'cashews', 'kasuri methi (dried fenugreek leaves)', 'garam masala powder']::text[], '["To begin making the Lehsuni Methi Paneer recipe, soak the cashews in a bowl with 1/4 cup water for about an hour.After an hour, grind cashew along with\u00a0ginger, garlic and green chillies and the soaked cashew water make a smooth paste and keep aside.In a big bowl, add cashew ginger garlic and chilli paste, fresh cream, curd, garam masala, cardamom powder salt and whisk well to form a smooth mixture.", "Heat ghee in a pan over medium heat; Add the cashew cream mixture, the chopped Paneer cubes and simmer for about 5 minutes.Add water to adjust the consistency of the mixture while it''s simmering.", "Check the salt and spices and adjust to taste accordingly.", "Finally stir in the kasuri methi, cover the pan and turn off the heat.Allow the flavours of methi to get infused into the Lehsuni Paneer Methi sabzi.", "Transfer the Lehsuni Methi Paneer\u00a0into a serving bowl and serve hot.Serve\u00a0Lehsuni Methi Paneer Recipe\u00a0along with\u00a0Smoked Makhani Dhaba Style Dal,\u00a0Jeera Rice,\u00a0Tomato Onion Tadka Raita\u00a0and\u00a0Garlic Naan\u00a0for a house party."]'::jsonb, 25, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Affiliate-Articles/Lehsuni_Methi_Paneer_Recipe-7_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1066.Lehsuni_Methi_Paneer_Recipe-7_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Goan Shepeche Polle Recipe', 'goan-shepeche-polle-recipe', 'The Goan Shepeche Polle Recipe is a traditional recipe from goa, that is very similar to a dosa but flavored with dill leaves, jaggery and coconut. Dill leaves have medicinal properties and are known to boost the immune system and protect against bone-degradation as it is a rich source of calcium. Shepeche Polle Recipe  is my personal favorite and I have been making these since many years. It has a strong, tangy taste from the Dill leaves and sweetness of jaggery and coconut.', '["1 cup Rice", "1/4 cup Black Urad Dal (Whole)", "1 cup Dill leaves , chopped", "1/2 cup Coconut , grated", "1/2 cup Jaggery , grated", "Salt , to taste", "Ghee , for cooking the pancakes"]'::jsonb, ARRAY['salt', 'dill leaves', 'rice', 'coconut', 'jaggery', 'ghee the pancakes', 'black urad dal']::text[], '["To begin making the Goan Shepeche Polle Recipe, soak rice and urad dal in water for 4 to 5 hours.", "Once soaked drain the water.", "Grind the rice and dal mixture adding little water at a time to make a smooth thick dosa batter.", "Pour the batter into a large bowl, cover and allow it to rest and ferment for about 6 to 8 hours.", "After the fermentation process, keep the batter aside and we will proceed to make the dill paste.Grind together dill leaves, grated jaggery and grated coconut by adding little water to make a paste.Stir in the dill coconut and jaggery mixture to the dosa/ pancake batter and stir well.", "Add salt to taste and stir again.The next step is to make the pancake/ dosa (Shepeche Polle).Preheat a skillet on medium heat and grease the skillet.", "Pour a ladleful of batter on the skillet and spread the batter in circular motion until it is thin.", "Drizzle ghee over the\u00a0Shepeche Polle and allow it to cook and browned.Once cooked, remove from the pan and serve.", "Proceed the same way with the remaining batter.", "Serve the\u00a0Goan Shepeche Polle Recipe along with a\u00a0Tomato Onion Chutney\u00a0for breakfast."]'::jsonb, 270, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Dill_Leaves_Pancake.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1067.Dill_Leaves_Pancake.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ghoogri Recipe - Jowar Upma', 'ghoogri-recipe-jowar-upma', 'Ghoogri is a savory pilaf or khichdi made from sorghum aka jowar along with choice of veggies. I preferred using carrot, peas and green pepper for ghoogri. This is a unique recipe which is loaded with nutrition and taste. Jowar is soaked overnight and boiled until cooked but chewy. Then it is sautéed with veggies and spices. This makes an ideal meal that can also be packed into your office lunch boxes. Ghoogri is generally eaten on its own and makes a wholesome healthy meal.', '["1 cup Jowar Seeds , soaked for 9 to 10 hours", "1 Green Bell Pepper (Capsicum) , chopped", "1 cup Green peas (Matar) , shelled", "1/2 cup Carrot (Gajjar) , chopped", "1/3 cup Onions , finely chopped", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoons Green Chillies , crushed", "1 teaspoon Garlic , crushed", "1 teaspoon Ginger , grated", "1 teaspoon Garam masala powder", "1 teaspoon Lemon juice", "1 teaspoon Sugar", "Salt , to taste", "2 tablespoons Ghee , or oil", "Water , as required", "Coriander (Dhania) Leaves , a few for garnish"]'::jsonb, ARRAY['salt', 'ginger', 'coriander (dhania) leaves', 'jowar seeds', 'water', 'carrot', 'green peas (matar) shelled', 'sugar', 'onion', 'cumin seeds (jeera)', 'garlic', 'lemon', 'green bell pepper (capsicum)', 'ghee', 'oil', 'green chillies', 'garam masala powder']::text[], '["To begin making Ghoogri Recipe, firstly boil the soaked jowar in enough water till the cooker releases 8 to 9 whistles The level of the water in the cooker should be approximately 2 inches above.The boiled jowar should be cooked well but chewy and not mushy.", "Strain out the residual water and use few tablespoons of it while cooking the spices later.In a kadhai heat ghee.", "Add cumin seeds and allow it to crackle.Add crushed green chilies, ginger and garlic, and saute for few seconds.", "Add onions and saute them until they are soft and pink.Add carrot and green peas, saute for a minute.", "Add few tablespoons of water from the boiled jowar, cover and cook for 3 to 4 minutes.", "Once the carrots and peas are cooked add chopped capsicum, garam masala powder, sugar and mix well.Add boiled jowar and toss well.", "Cover and cook for a couple of minutes.", "Lastly, add lemon juice and mix everything well.Transfer the\u00a0Ghoogri into a serving plate, garnish with green coriander leaves and serve.Serve Ghoogri with a hot cup of\u00a0Masala Chai\u00a0for breakfast."]'::jsonb, 100, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Farrukh_Aziz_Ansari/Ghoogri.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1068.Ghoogri.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharashtrian Anarsa Recipe', 'maharashtrian-anarsa-recipe', 'Anarsa is an authentic Maharashtrian sweet snack recipe prepared during the festive season. The recipe calls for common ingredients available in all households like powdered jaggery, rice, and ghee. The pastry-like snack is authentically prepared by deep frying the rice discs in a surplus amount of ghee. But I have deep fried in cooking oil. Though they look like a perfect quick fix, the authentic way of preparation is time-consuming as the rice has to be soaked in water for 3 days. If you are short of time, you can try the same with store bought rice flour.', '["1 Cup Rice , soaked for 3 days (wash & change water everyday)", "1 Cup Jaggery , powdered", "1/2 cup Milk", "1/2 Ripe Bananas , (optional) mashed", "3 tablespoons Poppy seeds", "Oil , for deep frying", "Salt , a pinch"]'::jsonb, ARRAY['salt', 'bananas', 'milk', 'jaggery', 'poppy seeds', 'rice days ( change water everyday)', 'sunflower oil']::text[], '["Drain the water from the bowl.", "Spread the drained rice in a cotton cloth and allow them to fry for 4-5 hours.", "Ensure that the rice should not lose its moisture completely.", "It has to retain the minimal amount of moisture.Grind them without adding water into a coarse powder.", "This is called Pithi.", "You could also use about 1-1/2 cups of rice flour directly to make this recipe as well.Now, in another bowl, add grounded rice, powdered jaggery and combine them together.Add milk little by little and mix them well.", "It should be in the dough consistency.The addition of banana ensures the sugar is completely dissolved.", "You can optionally add half of banana mashed, at this time and mix the dough till it comes together.Make small balls out of the dough.In a baking tray, spread poppy seeds evenly.Place the rice balls on the tray.", "Gently flattened the balls with your fingers so that one side of it is coated with poppy seeds.", "The flattened disc should retain their shape.In a Kadai, heat oil over medium heat.Once the oil is hot, place the flattened disc with Poppy seeds on the upper side and fry them in batches.", "Pour hot oil over the disc so that it is evenly cooked and puff up.Place the deep fried pastries on the tissue paper for the excess oil to drain.Deep fry the remaining anarse and serve Maharashtrian Anarsa Recipe warmly during tea time or as a part of a festive meal."]'::jsonb, 65, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/KarthikaKrishnan/Anarse.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1069.Anarse.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Avarekalu Kadubu Recipe (Hyacinth Beans Steamed Dumplings)', 'avarekalu-kadubu-recipe-hyacinth-beans-steamed-dumplings', 'Bored of your regular muesli, sandwiches, idli/dosa or poha breakfasts? Try this healthy north karnataka style Avarekalu Kadubu Recipe (Hyacinth Beans Steamed Dumplings). Avarekalu are hyacinth beans which are rich in calcium and iron. The healthy beans are boiled and mixed with the spiced cream of rice mixture, and then steamed into small balls. It is soft, spicy and the rice rava adds a nice crumbly texture to the dumpling. Serve the Avarekalu Kadubu Recipe (Hyacinth Beans Steamed Dumplings) along with South Indian Coconut Chutney  for breakfast along with South Indian Filter Coffee Recipe or as an after school snack for the kids.', '["1 cup Rice rava", "1/2 cup Avarekalu / Lilva Beans , boiled", "1 Green Chillies , finely chopped", "1 sprig Curry leaves , finely chopped", "1 teaspoon Cumin seeds (Jeera)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'rice rava', 'curry leaves', 'cumin seeds (jeera)', 'avarekalu lilva beans', 'green chillies']::text[], '["To begin making\u00a0Avarekalu Kadubu Recipe (Hyacinth Beans Steamed Dumplings), take a kadai and dry roast the rice rava on a medium heat for about 5 minutes or until fragrant and pour it out on a bowl.", "Keep aside.Boil hyacinth beans with a little salt in water until they are cooked well.", "This will take around 10 minutes.", "It is better not to use a pressure cooker; use a saucepan to cook the lilva beans since they will retain their shape and wont be mushy.Drain and keep aside on a plate to cool till handleable.", "You can reserve the drained water to use for later.Put the idli steamer on medium heat with a cup water added to it.Take a bowl, add the dry roasted rice rava, boiled hyacinth beans, chopped curry leaves, chilli, cumin seeds, season with salt and mix well.To this add 1/2 cup lukewarm water (you can use the stock of water that you cooked the avarekalu in) and mix well.", "The mixture should be crumbly but should hold the shape if pressed tightly between fingers and palm.Take a small portion of the mixture, and hold it tightly to form a ball.", "Likewise, form small balls of kadubu with the rest of the mixture.Place these kadubu into the steamer, close it with a lid and steam for about 8 minutes on medium high heat or till firm and done.Serve the\u00a0Avarekalu Kadubu Recipe (Hyacinth Beans Steamed Dumplings) along with\u00a0South Indian Coconut Chutney\u00a0for breakfast along with\u00a0South Indian Filter Coffee Recipe\u00a0or as an after school snack for the kids."]'::jsonb, 25, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Avarekalu_Kadubu_Recipe_Hyacinth_Beans_Steamed_Dumplings.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1070.Avarekalu_Kadubu_Recipe_Hyacinth_Beans_Steamed_Dumplings.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Assamese Poita Bhat With Aloo Pitika Recipe', 'assamese-poita-bhat-with-aloo-pitika-recipe', 'Assamese Poita bhat is a very humble breakfast dish. It’s a healthy body coolant for summers with poita bhat with aloo pitika is so comforting! The slightly fermented rice has lot more health benefits.  It is believed that regular consumption of this kanji can ease you from your stomach ulcers, prevents you from dehydration during summers, and is also rich is vitamins (vitamin B12 in specific).  So next time you have leftover rice from your dinner, turn it into a soothing and comforting breakfast for next morning by soaking the left over rice in water overnight.', '["1 cup Cooked rice , soaked in 2 cups water over night", "1/4 cup Curd (Dahi / Yogurt) , or \u00bd cup buttermilk", "2 tablespoon Onions , chopped", "2 Green Chillies , finely chopped", "Salt , to taste", "3 Potatoes (Aloo)", "1/2 teaspoon Turmeric powder (Haldi)", "1 tablespoon Mustard oil", "2 Green Chillies", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard oil', 'rice over night', 'curd', 'onion', 'potato (aloo)', 'turmeric powder', 'green chillies']::text[], '["To prepare Assamese Poita Bhat With Aloo Pitika Recipe, soak leftover rice rice in 2 cups water overnight.Next morning, add beaten curd or buttermilk and mix well in a mixing bowl.", "Add salt, chopped onions and green chilies.", "Keep aside.To prepare aloo pitika, boil potatoes, peel the skin and mash it well.", "Make sure no lumpy pieces are present.Heat mustard oil in a kadai and when oil turns smoking hot, add turmeric powder.Whisk it quickly and pour it into mashed potatoes.", "Mix well.Add chopped green chilies and mix again.", "Aloo pitika is ready.Serve Assamese Poita Bhat With Aloo Pitika Recipe for breakfast."]'::jsonb, 25, 'Assamese', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/Poita_Bhat_with_Aloo_Pitika_Assamese_Breakfast.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1071.Poita_Bhat_with_Aloo_Pitika_Assamese_Breakfast.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mangalore Style Southe Gatti/Southekayi kadubu Recipe (Steamed Cucumber Dumplings)', 'mangalore-style-southe-gatti-southekayi-kadubu-recipe-steamed-cucumber-dumplings', 'Mangalore Style Southe Gatti/Southekayi kadubu Recipe (Steamed Cucumber Dumplings) is a hot steamed rice and cucumber dumpling. Gatti is usually prepared using rice, coconut and finely grated squash. You can use any different type of squash like Mangalore cucumber, white or yellow pumpkin. Traditionally they are steamed using a banana leaf which also gives a nice flavor and aroma to the dumpling. You can make these as a healthy start for your breakfast or even serve it as a snack during your evening time.', '["1 cup Idli Rice , washed and dried", "1/2 cup Fresh coconut", "1 Cucumber , grated", "1 tablespoon Sugar", "Salt , a pinch, or to taste"]'::jsonb, ARRAY['salt', 'coconut', 'idli rice dried', 'sugar', 'cucumber']::text[], '["To begin making the Mangalore Style Southe Gatti, we will wash the rice thoroughly with water and place them spread over a table cloth so that it dries away faster.Grind it in a mixer to a smooth powder, keep it aside add coconut and grind that also to a coarse mixture.Mix all the rest of the ingredients into a bowl and you will have a consistency of a dropping batter.Heat a vegetable steamer, if you are using a banana leaf cut them into rectangular shape and place the batter in the center and fold it tightly and carefully place it inside the steamer.", "You can as well use a parchment paper.Steam them for at least 15 minutes and serve hot.", "Serve the Mangalore Style Southe Gatti along with\u00a0coconut chutney,\u00a0tomato onion chutney\u00a0to enjoy the breakfast."]'::jsonb, 30, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Mangalore_Style_Southe_GattiSouthekayi_kadubu_Recipe_Steamed_Cucumber_Dumplings.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1072.Mangalore_Style_Southe_GattiSouthekayi_kadubu_Recipe_Steamed_Cucumber_Dumplings.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Semolina Vegetable Chilla Recipe', 'semolina-vegetable-chilla-recipe', 'Semolina Vegetable Chila is a perfect way to feed vegetables to your kids. It is a little time consuming but it’s worth it. Not only it’s tasty but is really healthy also. And the best part is that it’s almost oil free. You can also make this chila for your breakfast and can pack it for your lunch too.', '["1-1/2 cup Sooji (Semolina/ Rava)", "1/2 cup Whole Wheat Flour", "1/2 cup Water", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1 cup Curd (Dahi / Yogurt)", "1/4 cup Carrot (Gajjar) , grated", "1/4 cup Raw papaya , grated", "1/4 cup Cabbage (Patta Gobi/ Muttaikose) , grated", "1/4 cup Green Bell Pepper (Capsicum) , grated", "2 Green Chillies , finely chopped", "Coriander (Dhania) Leaves , few (chopped)", "1/2 teaspoon Black pepper powder", "Salt , to taste", "1 teaspoon Extra Virgin Olive Oil"]'::jsonb, ARRAY['tomato', 'salt', 'wheat flour', 'coriander (dhania) leaves', 'water', 'carrot', 'virgin olive oil', 'curd', 'papaya', 'onion', 'black pepper powder', 'green bell pepper (capsicum)', 'sooji (semolina rava)', 'green chillies', 'cabbage (patta gobi muttaikose)']::text[], '["To begin making the Semolina Vegetable Chila recipe, In a bowl, make a batter of semolina, curd, and water by mixing them together.", "Add Wheat flour too.", "The consistency of the batter should not be runny, neither it should be too thick.", "Let the batter rest for at least 20-25 minutes.Now in the mixture add all the vegetables, salt and pepper.", "If after adding vegetables the batter becomes thick then add a little water or curd.Now take a non-stick pan and put it on low medium flame.Brush it with little olive oil.", "Once the pan is hot, pour a big ladle of mixture and spread it evenly on the pan.", "It should be thin like a pancake.Put the lid on and let the chila gets cooked in steam on low flame for 5-7 minutes.", "Once a while flip the chila, so that both sides get cooked evenly and yellowish golden in colour.", "Make rest of the chilas in a similar way.Serve\u00a0Semolina Vegetable Chila along with\u00a0Dhaniya Pudina Chutney,\u00a0Tomato Chutney\u00a0or any other chutney of your choice for your breakfast or as a tea time snack."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/iti.archana13-gmail.com/SEMOLINA_VEGETABLE_CHILA_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1073.SEMOLINA_VEGETABLE_CHILA_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kathirikai Urulai Kizhangu Kara Kuzhambu Recipe', 'kathirikai-urulai-kizhangu-kara-kuzhambu-recipe', 'lunch is a traditional Chettinad dish which is commonly prepared in all households of Chettinad with brinjal and potatoes. Brinjals and potatoes are cubed and cooked with spices in a tamarind – tomato base. The addition of tamarind and tomato lends sour taste to the gravy and addition of spices lends a spicy taste. The combination of sour and spicy makes it as a perfect accompaniment for rice. The gravy lasts for a couple of days due to the addition of tamarind and sour.', '["6 Brinjal (Baingan / Eggplant) , cubed", "1 Potato (Aloo) , cubed", "15 Shallots , finely chopped", "1 Tomato , finely chopped", "1 teaspoon Sambar Powder", "1 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Salt", "2 1/2 cup Water", "Tamarind , lemon sized", "To Temper", "2 tablespoon Oil", "1/8 teaspoon Asafoetida (hing)", "Curry leaves , handful", "3 Dry Red Chilli", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)"]'::jsonb, ARRAY['brinjal', 'baingan / eggplant', 'potato', 'aloo', 'shallots', 'tomato', 'sambar powder', 'red chilli powder', 'turmeric powder', 'haldi', 'salt', 'water', 'tamarind', 'to temper', 'oil', 'asafoetida', 'hing', 'curry leaves', 'dry red chilli', 'methi seeds', 'fenugreek seeds', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split']::text[], '["To begin the preparation of Kathirikai Urulaikizhanghu Kuzhambhu, in a medium sized pan, heat oil over medium heat.", "Once the oil is hot, add mustard seeds.Once the mustard seeds splutter, Add the remaining ingredients mentioned under tempering to the oilFry until the urad dal turns slightly brownishAdd chopped onions and cook until they are translucentAdd chopped tomatoes and cook until they become tenderNow, add cubed Brinjals and potato to the mixture in the panAdd sambar powder, chili powder and salt to the mixture.", "Stir them well so that the vegetables are evenly coated with the spice blend.Cook with the lid covered until brinjals and potato become tender.Heat a \u00bd cup of water and add tamarind to the hot water.", "Extract tamarind juice and set asideAdd the extracted tamarind juice to the blend in the pan.", "Add 2 cups of water to the gravyCook the curry over low heat until Brinjals and Potatoes are cooked well.Simmer the curry till the oil separates from the gravy.Serve the Kathirikai Urulaikizhanghu Kuzhambhu with hot rice and fried pappad."]'::jsonb, 70, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Kathirikai_Urulaikizhangu_Kara_Kuzhambhu.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1074.Kathirikai_Urulaikizhangu_Kara_Kuzhambhu.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('काथीरीकइ गोथ्सु रेसिपी - Kathirikai Gotsu Recipe', 'kathirikai-gotsu-recipe', 'काथीरीकइ गोथ्सु रेसिपी एक पारम्परिक रेसिपी है जिसमे बैंगन को रोज के मसालो के साथ पकाया जाता है. इसमें दूसरे मसलो के साथ सांबर पाउडर का भी प्रयोग किया जाता है जो इसे और भी स्वादिष्ट बनाता है. इसके साथ इसमें थोड़ा गुड़ का भी प्रयोग करते है जो इस करी में थोड़ी मिठास देता है.', '["1 \u092c\u0948\u0902\u0917\u0928 , \u0915\u093e\u091f \u0932\u0947", "10 \u091b\u094b\u091f\u0947 \u092a\u094d\u092f\u093e\u095b , \u0915\u093e\u091f \u0932\u0947", "2 \u091f\u092e\u093e\u091f\u0930 , \u0915\u093e\u091f \u0932\u0947", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1/2 \u0915\u092a \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u093e\u0928\u0940", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0938\u093e\u0902\u092c\u0930 \u092a\u093e\u0909\u0921\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0940\u0902\u0917", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0917\u0941\u095c", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "1 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0924\u093f\u0932 \u0915\u093e \u0924\u0947\u0932", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930, \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0947 \u0932\u093f\u090f"]'::jsonb, ARRAY['बैंगन', 'छोटे प्याज़', 'टमाटर', 'इंच अदरक', 'कप इमली का पानी', 'छोटा चम्मच सांबर पाउडर', 'छोटा चम्मच हींग', 'छोटा चम्मच हल्दी पाउडर', 'बड़ा चम्मच गुड़', 'छोटा चम्मच राइ', 'टहनी कढ़ी पत्ता', 'बड़ा चम्मच तिल का तेल', 'नमक', 'हरा धनिया']::text[], '["\u0915\u093e\u0925\u0940\u0930\u0940\u0915\u0907 \u0917\u094b\u0925\u094d\u0938\u0941 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907\u00a0\u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0939\u0940\u0902\u0917, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e, \u0938\u093e\u0902\u092c\u0930 \u092a\u094d\u092f\u093e\u091c, \u0905\u0926\u0930\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b \u091c\u093e\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092c\u0948\u0902\u0917\u0928, \u091f\u092e\u093e\u091f\u0930, \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u093e\u0928\u0940, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0939\u0940\u0902\u0917, \u0938\u093e\u0902\u092c\u0930 \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915, \u0917\u0941\u095c, \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u0915\u0941\u0915\u0930 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 3\u00a0\u0938\u0947 4 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947.\u00a0\u0915\u0941\u0915\u0930 \u0916\u094b\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u0947 \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902\u0964 \u0915\u093e\u0925\u0940\u0930\u0940\u0915\u0907 \u0917\u094b\u0925\u094d\u0938\u0941 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u0935\u0947\u0928 \u092a\u094b\u0902\u0917\u0932 \u0914\u0930 \u095e\u093f\u0932\u094d\u091f\u0930 \u0915\u0949\u095e\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0938\u0941\u092c\u0939 \u0915\u0947 \u0928\u093e\u0936\u094d\u0924\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/kathirikai_gothsu_recipe_tangy_and_spicy_brinjal_curry_7_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1075.kathirikai_gothsu_recipe_tangy_and_spicy_brinjal_curry_7_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('चकुंदर पनीर करी रेसिपी -  Beetroot Paneer Curry Recipe In Coconut Milk', 'beetroot-paneer-curry-recipe-in-coconut-milk-2', 'चकुंदर पनीर करी एक फ्लेवर से भरपूर सब्ज़ी है जिसमे पनीर और बीटरूट को नारियल के दूध में पकाया जाता है. कढ़ी पत्ता और अदरक का प्रयोग किया जाता है और इसे दक्षिण भारतीय स्टाइल में बनाया जाता है. यह बनाने में आसान है और इसे बनाने में बहुत कम समय लगता है.', '["200 \u0917\u094d\u0930\u093e\u092e \u092a\u0928\u0940\u0930 , \u0915\u093e\u091f \u0932\u0947", "2 \u091a\u0915\u0941\u0902\u0926\u0930 , \u091b\u0940\u0932\u0915\u0930 \u0915\u093e\u091f \u0932\u0947", "1 \u092a\u094d\u092f\u093e\u091c , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u0915\u0938 \u0932\u0947", "2 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0932\u094d\u0926\u0940", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "3/4 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u093e \u0926\u0942\u0927", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u091a\u094d\u091a \u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['ग्राम पनीर', 'चकुंदर', 'प्याज', 'हरी मिर्च', 'इंच अदरक', 'कली लहसुन', 'छोटा चमच्च धनिया पाउडर', 'छोटा चमच्च हल्दी', 'छोटा चमच्च गरम मसाला पाउडर', 'कप नारियल का दूध', 'छोटे चमच्च तेल', 'नमक', 'लाल मिर्च पाउडर']::text[], '["\u091a\u0915\u0941\u0902\u0926\u0930 \u092a\u0928\u0940\u0930 \u0915\u0930\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u091a\u0915\u0941\u0902\u0926\u0930, \u092a\u094d\u092f\u093e\u091c, \u0905\u0926\u0930\u0915, \u0932\u0939\u0938\u0941\u0928, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a \u0915\u094b \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 1 \u0915\u092a \u092a\u093e\u0928\u0940, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930 \u0914\u0930 \u0928\u092e\u0915\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947\u09642 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947, \u0905\u092c \u0906\u0902\u091a \u0915\u092e \u0915\u0930\u0947\u0902 \u0914\u0930 3 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0914\u0930 \u092a\u0915\u093e \u0932\u0947.\u00a0\u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u094b \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947. \u092a\u094d\u0930\u0947\u0936\u0930 \u0928\u093f\u0915\u0932\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u093e \u0926\u0942\u0927, \u092a\u0928\u0940\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0926\u0947.\u00a0\u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0907\u0938\u0947 \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0928\u093f\u0915\u093e\u0932 \u0932\u0947. \u092a\u0930\u094b\u0938\u0947\u0964\u091a\u0915\u0941\u0902\u0926\u0930 \u092a\u0928\u0940\u0930 \u0915\u0930\u0940\u00a0\u0915\u094b\u00a0\u092a\u093e\u0932\u0915 \u0930\u093e\u092f\u0924\u093e\u00a0\u0914\u0930 \u091a\u093e\u0935\u0932/\u0924\u0935\u093e \u092a\u0930\u093e\u0920\u093e \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 55, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Beetroot_and_Paneer_Curry_Recipe_in_Coconut_Milk-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1076.Beetroot_and_Paneer_Curry_Recipe_in_Coconut_Milk-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('बांदे दिन्दु कडले पाल्या रेसिपी - Banana Stem Chickpea Curry', 'banana-stem-chickpea-curry', 'बांदे दिन्दु कडले पाल्या रेसिपी एक दक्षिण भारतीय रेसिपी है जिसमे केले के स्टेम और चने का प्रयोग किया जाता है. केले का स्टेम आपके किडनी के स्टोन्स के लिए बहुत अच्छा मन जाता है और पेट के लिए भी अच्छा होता है. दूसरी तरफ चने आपको प्रोटीन देता है.', '["1 \u0915\u0947\u0932\u0947 \u0915\u093e \u0938\u094d\u091f\u0947\u092e , \u0927\u094b \u0915\u0930 \u0915\u093e\u091f \u0932\u0947", "1 \u0915\u092a \u0915\u093e\u0932\u093e \u091a\u0928\u093e , \u0930\u093e\u0924 \u092d\u0930 \u092d\u093f\u0917\u094b \u0932\u0947", "2 \u092c\u095c\u0947 \u091a\u092e\u091a\u094d\u091a \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u091a\u094d\u091a \u091c\u0940\u0930\u093e", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u091a\u094d\u091a \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c", "1-1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "2 \u092a\u094d\u092f\u093e\u091c , \u0915\u093e\u091f \u0932\u0947", "1 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928 , \u091b\u0940\u0932 \u0932\u0947", "\u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u0925\u094b\u095c\u093e", "1 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0928\u093f\u092e\u094d\u092c\u0942 \u0915\u093e \u0930\u0938"]'::jsonb, ARRAY['केले का स्टेम', 'कप काला चना', 'बड़े चमच्च नारियल', 'छोटे चमच्च जीरा', 'छोटे चमच्च धनिये के बीज', 'छोटा चमच्च लाल मिर्च पाउडर', 'प्याज', 'कली लहसुन', 'कढ़ी पत्ता', 'नमक', 'तेल', 'हरा धनिया', 'हरी मिर्च', 'छोटा चमच्च निम्बू का रस']::text[], '["\u092c\u093e\u0902\u0926\u0947 \u0926\u093f\u0928\u094d\u0926\u0941 \u0915\u0921\u0932\u0947 \u092a\u093e\u0932\u094d\u092f\u093e \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0915\u0947\u0932\u0947 \u0915\u0947 \u0938\u094d\u091f\u0947\u092e \u0915\u093e \u0905\u0927\u093f\u0915 \u0939\u093f\u0938\u094d\u0938\u093e \u0915\u093e\u091f \u0932\u0947. \u0907\u0938\u0915\u0947 \u090a\u092a\u0930 \u0914\u0930 \u0928\u093f\u091a\u0947 \u0915\u093e \u0939\u093f\u0938\u094d\u0938\u093e \u091f\u094d\u0930\u093f\u092e \u0915\u0930 \u0932\u0947 \u0914\u0930 \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947.\u0905\u092c \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0915\u093e\u0932\u093e \u091a\u0928\u093e \u0914\u0930 \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947\u0964 1\u00a0\u0938\u0947 2\u00a0\u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947.\u0915\u0941\u0915\u0930 \u0915\u094b \u0916\u094b\u0932\u0947 \u0914\u0930 \u0907\u0938\u092e\u0947\u0902 \u0915\u0947\u0932\u0947 \u0915\u0947 \u0938\u094d\u091f\u0947\u092e, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u0938\u093f\u091f\u0940 \u0915\u0947 \u0932\u093f\u090f \u0914\u0930 \u092a\u0915\u093e \u0932\u0947\u0964\u00a0 \u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947.\u00a0\u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0927\u0928\u093f\u090f \u0915\u0947 \u092c\u0940\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0938\u0947\u0915 \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u0909\u0938\u0940 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0925\u094b\u095c\u093e \u0914\u0930 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u091c\u0940\u0930\u093e, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 10 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c, \u0932\u0939\u0938\u0941\u0928 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947 \u0914\u0930 \u0925\u094b\u095c\u093e \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0926\u0947.\u00a0\u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0938\u0940\u0915\u0947 \u0939\u0941\u090f \u0927\u0928\u093f\u092f\u0947 \u0915\u0940 \u092c\u0940\u091c, \u092a\u0915\u093e \u0939\u0941\u0906 \u092a\u094d\u092f\u093e\u091c \u0932\u0939\u0938\u0941\u0928 \u0915\u093e \u092e\u093f\u0936\u094d\u0930\u0923, \u0928\u093e\u0930\u093f\u092f\u0932, \u0925\u094b\u095c\u093e \u0938\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0940\u0938 \u0932\u0947.\u00a0\u0905\u092c \u0915\u0941\u0915\u0930 \u0915\u094b \u0916\u094b\u0932\u0947 \u0914\u0930 \u0909\u0938\u0947 \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0921\u093e\u0932 \u0926\u0947. \u0907\u0938\u092e\u0947 \u092a\u093f\u0938\u093e \u0939\u0941\u0906 \u092e\u0938\u093e\u0932\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915\u00a0\u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0926\u0947. \u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902, \u0928\u093f\u092e\u094d\u092c\u0942 \u0915\u093e \u0930\u0938 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e \u0914\u0930 \u092e\u093f\u0930\u094d\u091a \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092c\u093e\u0902\u0926\u0947 \u0926\u093f\u0928\u094d\u0926\u0941 \u0915\u0921\u0932\u0947 \u092a\u093e\u0932\u094d\u092f\u093e \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0932\u091a\u094d\u091b\u093e \u092a\u0930\u093e\u0920\u093e \u0914\u0930\u00a0\u092a\u093e\u0932\u0915 \u0930\u093e\u092f\u0924\u093e\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 65, 'Coastal Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Baalekaayi_Dindina_Palya_Raw_Banana_Stem_Chana_Dal_Curry_In_Coconut-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1077.Baalekaayi_Dindina_Palya_Raw_Banana_Stem_Chana_Dal_Curry_In_Coconut-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Ulli Theeyal Recipe - Small Onions Roasted in Spicy Tamarind Coconut Gravy', 'kerala-style-ulli-theeyal-recipe-small-onions-roasted-in-spicy-tamarind-coconut-gravy', 'The Kerala Style Ulli Theeyal is a delicious preparation of the small onions that are roasted and cooked in in a spicy tamarind coconut gravy. The recipe has a simple set of ingredients used in the kerala cooking and makes a perfect dish to be made during festivals like Onam or even when you have guests. It is different from the regular sambars and rasam and goes well when served with steamed rice or Kerala parotta.', '["200 grams Shallots", "4 sprig Curry leaves", "2 cups Tamarind Water", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)", "1/4 teaspoon Turmeric powder (Haldi)", "3 tablespoons Oil", "Salt , to taste", "Ingredients To be Roasted And Ground To Paste", "1 tablespoons Coriander (Dhania) Seeds", "1/2 teaspoon Cumin seeds (Jeera)", "6 Dry Red Chillies", "1 cup Fresh coconut , grated"]'::jsonb, ARRAY['s shallots', 'curry leaves', 's tamarind water', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing', 'turmeric powder', 'haldi', 's oil', 'salt', 'ingredients to be roasted and ground to paste', 's coriander', 'dhania', 'cumin seeds', 'jeera', 'dry red chillies', 'fresh coconut']::text[], '["To prepare Kerala Style Ulli Theeyal (Kerala Vengayam Puli Kuzhambu Recipe )- (Small Onions Roasted in Spicy Tamarind Coconut Gravy), In a small pan; dry roast the ingredients - coriander seeds, cumin seeds, red chillies and coconut until the\u00a0cococut\u00a0looses some of its moisture and becomes golden brown.", "Cool and blend\u00a0into\u00a0a coarse paste adding just a little waterHeat the oil in a heavy bottomed pan; add in the mustard seeds and allow it to crackle.", "Add in the curry leaves and the halved shallots. saute on medium heat until the shallots are tender and have turned golden brown.", "This takes a good 10 minutes.Once the onions are well roasted in the oil; add in the tamarind water, asafoetida, turmeric powder, salt and the roasted coconut paste.", "Stir all the ingredients well and simmer on low heat for about 10 minutes.Turn off the heat and transfer to a serving bowl.Serve the delicious spicy Kerala Style Ulli Theeyal (Kerala Vengayam Puli Kuzhambu Recipe ) with hot steamed rice and ghee or\u00a0Kerala parotta."]'::jsonb, 35, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Kerala_Style_Ulli_Theeyal_Kerala_Vengayam_Puli_Kuzhambu_Recipe_Small_Onions_Roasted_in_Spicy_Tamarind_Coconut_Gravy-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1078.Kerala_Style_Ulli_Theeyal_Kerala_Vengayam_Puli_Kuzhambu_Recipe_Small_Onions_Roasted_in_Spicy_Tamarind_Coconut_Gravy-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Khajur Satori Recipe (Dates Flatbread)', 'khajur-satori-recipe-dates-flatbread', 'Satori is a flatbread, popular in Maharashtra. Usually it is made during festivals. There are different types of stuffing you can use to make this bread. The most common is Khoya or Mawa stuffing.', '["1 cup Dates", "2 tablespoon Dry coconut (kopra) , grated", "2 teaspoon Poppy seeds", "2 tablespoon Milk Powder", "1 teaspoon Cardamom Powder (Elaichi)", "1 cup Whole Wheat Flour , + flour for dusting", "1 tablespoon Ghee , or butter", "1/2 cup Milk", "Salt , a pinch"]'::jsonb, ARRAY['salt', 'wheat flour flour', 'milk', 'dry coconut (kopra)', 'poppy seeds', 'cardamom powder (elaichi)', 'ghee butter', 'dates', 'milk powder']::text[], '["To begin making the Khajur Satori recipe, remove seeds from the dates if you are not using seedless dates.", "Chop them roughly and add them to a grinder.", "Make a paste and keep it aside in a separate bowl.Dry roast poppy seeds and coconut in a pan separately until the raw smell goes away.", "Add it to the dates paste.", "Mix everything and keep it aside with a lid on it.Get a bowl and add whole wheat flour in it.", "Add salt and mix it.Heat a pan and add ghee/butter in it.", "Add this hot ghee over the wheat flour.", "Mix everything with your hands.", "Make a medium soft dough by adding little milk at a time.", "Cover it with a damp cloth and keep it aside for one hour.", "After one hour, knead the dough again and make equal size balls.", "Get a stuffing and make the same amount of balls.Get one flour ball and roll out in a small disk using rolling pin.", "Get a dates stuffing ball and place it in the centre of rolled flour ball.", "Gather the edges and seal them together.Flatten this ball with your hands and roll out in a small circle using very little flour for dusting.", "The ''Satori'' should not be thin.Heat tava/griddle and place this rolled flat bread and brush the sides and the centre with some ghee/butter.", "Cook from both the sides by flipping the other side.Serve hot or cold with ghee/butter.", "You can store these for a week in a airtight container.Serve Khajur Satori as a snack along with\u00a0Masala Chai\u00a0and\u00a0Carrots and Coriander fritters\u00a0for your tea time break."]'::jsonb, 80, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sanika-forknscissors.com/Khajur_Satori.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1079.Khajur_Satori.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Baked Stuffed Baati With Churma And Panchratna Dal Recipe', 'baked-stuffed-baati-with-churma-and-panchratna-dal-recipe', 'Dal Baati Churma is a traditional Rajasthani treat. The spicy dal with the sweet churma along with crunchy batis, its such a treat, which steals the heart and delights the taste buds. A platter of semi-sweet Churma, spicy Dal and  Baati, is one such traditional combination. Fresh baatis drowned in piping hot dal is a perfect accompaniment for churma.', '["1 cup Whole Wheat Flour", "1/4 cup Sooji (Semolina/ Rava)", "4 tablespoons Ghee , Melted", "1/2 cup Caster Sugar", "1 tablespoon Whole Almonds (Badam) , chopped", "1 tablespoon Pistachios , chopped", "1/4 cup Chana dal (Bengal Gram Dal)", "1/4 cup Arhar dal (Split Toor Dal)", "1/4 cup Green Moong Dal (Split)", "1/4 cup White Urad Dal (Split)", "1 cup Tomato , chopped", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoons Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "1 tablespoon Coriander (Dhania) Leaves , finely chopped", "1 tablespoon Ghee", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Cloves (Laung)", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Cinnamon Powder (Dalchini)", "Asafoetida (hing) , a pinch", "Curry leaves , as required", "1 Kashmiri dry red chilli", "1 Bay leaf (tej patta)", "1 cup Whole Wheat Flour", "1/4 cup Sooji (Semolina/ Rava)", "2 tablespoons Gram flour (besan)", "3 tablespoon Ghee , melted", "1 teaspoon Salt", "1/2 cup Milk", "1 tablespoon Oil", "1 Green Chilli , finely chopped", "1 teaspoon Fennel seeds (Saunf)", "1 teaspoon Coriander (Dhania) Seeds", "Asafoetida (hing) , a pinch", "1 cup Green peas (Matar) , frozen", "1 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "Lemon , sliced", "Green Chilli , sliced", "Papad", "Ghee , melted (as required)"]'::jsonb, ARRAY['tomato', 'pistachios', 'coriander (dhania) leaves', 'asafoetida (hing)', 'kashmiri dry red chilli', 'white urad dal (split)', 'coriander (dhania) seeds', 'cumin seeds (jeera)', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil', 'salt', 'wheat flour', 'arhar dal (split toor dal)', 'green chilli', 'lemon', 'caster sugar', 'green moong dal (split)', 'garam masala powder', 'cinnamon powder (dalchini)', 'papad', 'mustard seeds', 'red chilli powder', 'sooji (semolina rava)', 'ghee', 'bay leaf (tej patta)', 'fennel seeds (saunf)', 'milk', 'green peas (matar)', 'curry leaves', 'gram flour (besan)', 'badam (almond)', 'coriander powder', 'cloves (laung)']::text[], '["To begin making the Baked Stuffed Baati With Churma And Panchratna Dal recipe , firstly we will make the churma.", "For Churma, in a mixing bowl take wheat flour, semolina and ghee, add water to form a stiff dough.Make patties with your palms with a indentation at the center.", "Prepare all and keep them aside.The next step is to make the dal.", "Rinse the daals well and pressure cook for 5 whistles along with a pinch of turmeric powder, salt and 3 cups of water.", "Once pressure releases, mash it well with a laddle and set aside.In a pan heat ghee, add the items listed under \u2018To temper\u2018 and let it splutter.", "Then add tomatoes along with red chilli powder, turmeric powder, coriander powder and garam masala along with salt and saute for few minutes until the tomatoes becomes soft.Now add mashed dal and mix well.", "Let the dal boil for 5 minutes, add little water if its too thick.", "Finally garnish with coriander leaves.Next, we will make the Baati.", "In a mixing bowl, take all the ingredients listed under \u2018BATI\u2018, mix well and knead it together to form a stiff dough.Divide the dough into small balls and keep them aside.", "Now for stuffing, into medium sized pan, heat oil, add fennel seeds and coriander seeds.", "Add green chillies, and green peas.Add salt, remaining dry ingredients and mix it well.", "Cook for 5-7 minutes and mash the peas using spatula and mix it well.", "Cook for another 5 minutes and switch off the flame, allow them to cool down.Once it''s completely cool, divide them into equal portions.", "Now flatten the baati and stuff one portion of the stuffing we made, and again flatten them using your palms.", "Prepare all the baatis likewise.", "Make a small indentation in the centre of the baatis using your thumb.Preheat the microwave on 200 degrees.", "Place the Churma and Baatis into it and bake them first for 15 minutes.When beep sounds, turn over them and bake again for 15 more minutes.", "Let them cool down at room temperature.", "So your baatis are ready!For Churma, once it is completely cool, break churma into small pieces and grind it using a mixer.", "Grind it a little coarse.", "Collect the mixture in a bowl, add castor sugar and mix well.", "Add almonds, pistachios along with ghee and give a quick mix.", "Churma is ready!So your delicious treat is ready! Serve it with papad, green chilli, lemon slice and sudh deshi ghee!Serve\u00a0Baked Stuffed Baati With Churma And Panchratna Dal with\u00a0Masala Chaas\u00a0for a weekend lunch."]'::jsonb, 60, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Dhara/Baked_Stuffed_Baati_With_Churma_And_Panchratna_Dal.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1080.Baked_Stuffed_Baati_With_Churma_And_Panchratna_Dal.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kala Chana Masala Curry Recipe', 'kala-chana-masala-curry-recipe', 'Kala Chana Masala is a perfect combination of black chana and spicy flavours. You can also serve it on its own as a salad or can serve it as a side dish along with your meal. It makes a good lunch box recipe too. It is spicy and very easy to make.', '["2 cups Kala Chana (Brown Chickpeas) , soaked overnight", "Oil , as required", "1 Bay leaf (tej patta)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Asafoetida (hing)", "2 Green Chillies , finely chopped", "2 Tomato , chopped", "1/2 tablespoon Whole Wheat Flour", "Salt , as required", "Water , as required", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "3/4 teaspoon Lemon juice", "3 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['tomato', 'salt', 'wheat flour', 'mustard seeds', 'bay leaf (tej patta)', 'asafoetida (hing)', 'red chilli powder', 'water', 'coriander (dhania) leaves', 'cumin seeds (jeera)', 'lemon', 'coriander powder', 'turmeric powder', 'green chillies', 'kala chana (brown chickpeas)', 'sunflower oil']::text[], '["To begin making the Kala Chana Masala recipe, firstly boil the soaked black chickpeas in a pressure cooker until the cooker release at least 3 whistles.", "When they are soft, drain the water and keep them aside.Heat oil in a heavy bottomed pan.", "Add cumin seeds, mustard seeds and hing.", "Let the mustard seeds crackle.Once it is done, add the tomatoes and green chillies and let it cook for about 5 minutes.Meanwhile mix the whole wheat flour properly with 3 tablespoons water.", "Keep it aside.Add the black chickpeas in the pan.", "Next, add red chilli powder, turmeric powder, coriander powder, salt and the whole wheat flour mixture.Mix everything properly and let it cook for about 2 to 3 minutes.", "Once done add the lemon juice and garnish it with chopped coriander leaves.Serve Kalal Chana Masala along with\u00a0Phulkas\u00a0and\u00a0Gujarati Dal\u00a0for a perfect weekday meal.", "You can also pack this in your lunch box along with Pudina Tawa Parathas."]'::jsonb, 40, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/6-july/Sukha_Kala_Chana_Masala_Recipe-7675.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1081.Sukha_Kala_Chana_Masala_Recipe-7675.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('इमली चिल्ली आलू रेसिपी - Tamarind Chilli Potato Recipe', 'tamarind-chilli-potato-recipe-2', 'स्वाद से भरपूर और बनाने में आसान, इमली चिल्ली आलू रेसिपी को आप अपनी हाउस पार्टीज के लिए बना सकते है. आलू को खट्टे तीखे मसाले में मिलाया जाता है जो इसका स्वाद और फ्लेवर बढ़ा देता है. आप इसे अपने खाने के साथ साइड डिश की तरह भी बना सकते है.', '["3 \u0906\u0932\u0942 , \u0909\u092c\u093e\u0932\u0915\u0930 \u0915\u093e\u091f \u0932\u0947", "1 \u092a\u094d\u092f\u093e\u091c , \u0915\u093e\u091f \u0932\u0947", "3 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u0947\u0938\u094d\u091f", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0936\u0915\u094d\u0915\u0930", "4 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928 , \u0915\u093e\u091f \u0932\u0947", "2 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0915\u093e\u091c\u0942 , \u0915\u093e\u091f \u0932\u0947", "2 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u0915\u093e\u091f \u0932\u0947", "\u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0905\u091c\u0935\u093e\u0907\u0928", "2 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a , \u0924\u093e\u095b\u0940"]'::jsonb, ARRAY['आलू', 'प्याज', 'बड़ा चम्मच इमली का पेस्ट', 'बड़ा चम्मच शक्कर', 'कली लहसुन', 'बड़ा चम्मच काजू', 'टहनी कढ़ी पत्ता', 'नमक', 'बड़ा चम्मच हरा धनिया', 'तेल', 'बड़ा चम्मच अजवाइन', 'लाल मिर्च']::text[], '["\u0907\u092e\u0932\u0940 \u091a\u093f\u0932\u094d\u0932\u0940 \u0906\u0932\u0942 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0906\u0932\u0942 \u0915\u094b \u0909\u092c\u093e\u0932 \u0915\u0947 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947. \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0906\u0932\u0942 \u0915\u094b \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930 \u092a\u093e\u0928\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947 \u0914\u0930 5 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947, \u0906\u0932\u0942 \u0915\u094b \u091b\u093f\u0932\u0915\u093e \u0928\u093f\u0915\u093e\u0932\u0947 \u0914\u0930 \u0915\u093e\u091f \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0906\u0932\u0942 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u0928\u0915\u093e \u0938\u0941\u0928\u0939\u0930\u093e \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u0924\u0932 \u0932\u0947. \u0915\u095d\u093e\u0908 \u0938\u0947 \u0928\u093f\u0915\u093e\u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u0909\u0938\u0940 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0905\u091c\u0935\u093e\u0907\u0928 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0915\u093e\u091c\u0942 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0938\u0941\u0928\u0939\u0930\u093e \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0932\u0939\u0938\u0941\u0928, \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u0947\u0938\u094d\u091f, \u0936\u0915\u094d\u0915\u0930, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a01 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0906\u0932\u0942 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u0947 \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902\u0964 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0907\u092e\u0932\u0940 \u091a\u093f\u0932\u094d\u0932\u0940 \u0906\u0932\u0942 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u092a\u093e\u0932\u0915 \u0926\u093e\u0932,\u00a0\u092b\u0941\u0932\u094d\u0915\u093e\u00a0\u0914\u0930\u00a0\u091f\u092e\u093e\u091f\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u0915\u095c\u0940 \u0930\u093e\u092f\u0924\u0947\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Tamrind_Chilli_Potato.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1082.Tamrind_Chilli_Potato.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('बीन्स करम रेसिपी - Beans Curry (Recipe In Hindi)', 'beans-curry-recipe-in-hindi', 'बीन्स करम एक साइड डिश रेसिपी है जिसमे बीन्स को दक्षिण भारत के मसलो के साथ पकाया जाता है. यह रेसिपी आप अपने लंच बॉक्स में भी पैक कर सकते है. बीन्स करम बनाना बहुत ही आसान है और काम समय में बनाई जा सकती है.', '["500 \u0917\u094d\u0930\u093e\u092e\u094d\u0938 \u0939\u0930\u093e \u092c\u0940\u0928\u094d\u0938", "2 \u092a\u094d\u092f\u093e\u091c , \u0915\u093e\u091f \u0932\u0947", "1 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u091c\u0940\u0930\u093e", "4 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "2 \u092c\u094d\u092f\u093e\u0926\u0917\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "1 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947", "2 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u0938\u0942\u0916\u093e \u0928\u093e\u0930\u093f\u092f\u0932", "1 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u0916\u0941\u0938 \u0916\u0941\u0938", "1 \u0907\u092e\u0932\u0940 , \u090f\u0915 \u0928\u093f\u092e\u094d\u092c\u0942 \u091c\u093f\u0924\u0928\u093e", "2 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u0917\u0941\u095c", "1 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0930\u093e\u0907", "10 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0940\u0902\u0917"]'::jsonb, ARRAY['ग्राम्स हरा बीन्स', 'प्याज', 'बड़ा चमच्च धनिये के बीज', 'छोटा चमच्च जीरा', 'सुखी लाल मिर्च', 'ब्यादगी लाल मिर्च', 'कप नारियल', 'बड़ा चमच्च सूखा नारियल', 'बड़ा चमच्च खुस खुस', 'इमली', 'बड़ा चमच्च गुड़', 'बड़ा चमच्च हल्दी पाउडर', 'नमक', 'छोटा चमच्च राइ', 'कढ़ी पत्ता', 'छोटा चमच्च हींग']::text[], '["\u092c\u0940\u0928\u094d\u0938 \u0915\u0930\u092e \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902\u00a0\u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c, \u091c\u0940\u0930\u093e, \u092e\u093f\u0930\u094d\u091a, \u0938\u0942\u0916\u093e \u0928\u093e\u0930\u093f\u092f\u0932, \u0916\u0941\u0938 \u0916\u0941\u0938 \u0914\u0930 \u0928\u093e\u0930\u093f\u092f\u0932 \u0921\u093e\u0932\u0947\u0964 1 \u0938\u0947 2 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u093e\u090f \u0914\u0930 \u092b\u093f\u0930 \u0928\u093f\u0915\u093e\u0932 \u0926\u0947.\u00a0\u0907\u0938 \u092e\u093f\u0915\u094d\u0938\u091a\u0930 \u0915\u094b\u00a0\u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947\u0964 \u0907\u0938\u092e\u0947\u0902 \u0907\u092e\u0932\u0940, \u0917\u0941\u095c, 1/2 \u092a\u094d\u092f\u093e\u091c \u0914\u0930 \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0907\u0938\u0940 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092a\u0940\u0938 \u0932\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0938\u0949\u0938\u092a\u0948\u0928 \u092e\u0947\u0902 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092c\u0940\u0928\u094d\u0938 \u0915\u094b \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u0909\u0938\u0915\u0947 \u092c\u093e\u0926 \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907 \u0921\u093e\u0932\u0947 \u0914\u0930 10 \u0938\u0947\u0915\u0902\u0921 \u0924\u0915 \u092a\u0915\u093e\u090f\u0964\u00a010 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0939\u0940\u0902\u0917, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e, \u092a\u094d\u092f\u093e\u091c \u0914\u0930 \u0928\u092e\u0915 \u0921\u093e\u0932\u0947\u0964 \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e\u090f\u0964\u00a0\u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0907\u0938\u092e\u0947\u0902 \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u092c\u0940\u0928\u094d\u0938 \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u093e\u090f\u0964 \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u093f\u0938\u093e \u0939\u0941\u0906 \u092e\u0938\u093e\u0932\u093e \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 5 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u093e\u090f\u0964\u00a05 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u090f\u0915 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u092c\u0932\u0928\u0947 \u0926\u0947. \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092a\u093e\u0915 \u091c\u093e\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0917\u0930\u092e\u093e \u0917\u0930\u092e \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092c\u0940\u0928\u094d\u0938 \u0915\u0930\u092e \u0915\u094b \u092e\u093f\u0915\u094d\u0938\u094d\u0921 \u0935\u0947\u091c\u093f\u091f\u0947\u092c\u0932 \u0938\u093e\u0902\u092c\u0930, \u091a\u093e\u0935\u0932 \u0914\u0930 \u092a\u093e\u092a\u095c\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Gauravi_Vinay/Beans_Karam.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1083.Beans_Karam.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Begun Basanti Recipe - Eggplant In Mustard Yogurt Curry', 'begun-basanti-recipe-eggplant-in-mustard-yogurt-curry', 'Begun Basanti Recipe (Eggplant in Mustard Yogurt Curry) is a delicacy among the Bengali Cuisine. As it contains the two very used ingredients in most of the Bong cooking.', '["1 Brinjal (Baingan / Eggplant) , cut into long wedges", "2 teaspoon Poppy seeds", "2 teaspoon Yellow mustard seeds", "1/4 cup Curd (Dahi / Yogurt)", "1 Green Chilli , slit", "1 inch Ginger , chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Red Chilli powder", "1 pinch Sugar", "Salt , to taste", "Mustard oil , for cooking"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'ginger', 'green chilli', 'mustard oil', 'brinjal (baingan eggsplant)', 'red chilli powder', 'curd', 'sugar', 'poppy seeds', 'yellow mustard seeds', 'turmeric powder']::text[], '["To begin making the Begun Basanti Recipe, firstly chop the eggplant and marinate them with a teaspoon of turmeric powder and keep it aside.Grind the poppy seeds and mustard seeds in a grinder to a smooth powder and keep it aside.Heat a kadai with mustard oil, Add eggplant and roast them well till they soften.", "You can sprinkle little water and salt and cover it and cook.", "This will help in cooking faster.Take the brinjal out, add little more oil and add chopped ginger.", "Saute until it softens.", "Add green chilli and saut\u00e9ed brinjal.Add poppy seed, mustard seed powder and mix well.", "Add the remaining turmeric powder, red chili powder and cumin powder.", "Cook until the spices have well combined.Add curd and sprinkle and mix well.", "Cook until the gravy thickens a bit and serve hot.Serve the\u00a0Begun Basanti Recipe\u00a0along with\u00a0Cholar Dal\u00a0and\u00a0Bengali Luchi\u00a0to create a nice bengali meal for your lunch."]'::jsonb, 40, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Begun_Basanti_Recipe_Eggplant_in_Mustard_Yogurt_Curry_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1084.Begun_Basanti_Recipe_Eggplant_in_Mustard_Yogurt_Curry_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Potato And Cauliflower In Peanut Curry Recipe', 'potato-and-cauliflower-in-peanut-curry-recipe', 'Potato & Cauliflower In Peanut Curry Recipe is a vegetarian satvik side dish recipe which has no onion or garlic. Make this easy and no-fuss curry recipe for a weekday dinner. ox.', '["2 cups Cauliflower (gobi) , florets", "3 Potatoes (Aloo) , diced", "1/2 cup Raw Peanuts (Moongphali) , husked", "1 Green Chilli , chopped", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Bay leaf (tej patta)", "3 Tomatoes , pureed", "1 tablespoon Ginger , made into paste", "1/2 cup Gram flour (besan)", "2 tablespoons Curd (Dahi / Yogurt) , (optional)", "1 tablespoon Coriander Powder (Dhania)", "1 tablespoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Garam masala powder", "Salt , to taste", "2 tablespoons Coriander (Dhania) Leaves , chopped, for garnish", "Oil , as needed"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'ginger', 'garam masala powder', 'green chilli', 'mustard seeds', 'bay leaf (tej patta)', 'coriander (dhania) leaves', 'red chilli powder', 'peanuts (moongphali) husked', 'gram flour (besan)', 'curd', 'coriander powder', 'potato (aloo)', 'turmeric powder', 'cauliflower (gobi) florets', 'sunflower oil']::text[], '["To begin making the Potato & Cauliflower In Peanut Curry Recipe, dry roast the peanuts and remove the husk completely.", "If you want you can roast them again for better flavor.", "Collect the roasted peanuts in a grinder jar and grind to make a fine powder and keep aside.In a kadai/wok, heat a bit of oil and add bay leaf and mustard seeds and wait till they crackle.", "Add grated ginger and saute.Now add besan and roast it for few seconds and immediately add the tomato puree in it and stir nicely.Add coriander powder, red chilli powder, turmeric powder, cumin powder and garam masala powder and fry the masala till oil starts leaving from sides.Now add curd (you can skip this step if you want) and fry for another minute or so.Once the masala starts smelling great and flavoured, add roasted peanut powder and mix nicely.Cook for another 2-3 mins and add cauliflower and potato pieces, add water to make the curry.", "The curry is thick hence be careful while adding water.", "Adjust salt and let the curry come to a boil.Simmer the gas, and cook the curry for another 5 mins on low flame with lid closed till the vegetables are cooked.Once the Potato & Cauliflower Curry is done, turn off the gas and transfer the curry in a serving bowl and garnish with some fresh coriander.Serve Potato & Cauliflower In Peanut Curry Recipe with Butter Naan and Mooli Raita for your weeknight dinner."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/shaheen_ali/No_Onion_No_Garlic_Cauliflower_Peanut_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1085.No_Onion_No_Garlic_Cauliflower_Peanut_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pasi Paruppu Masiyal Recipe-Green Moong Dal Curry Recipe', 'pasi-paruppu-masiyal-recipe-green-moong-dal-curry-recipe', 'Pasi Paruppu Masiyal Recipe is a simple one pot meal made by pressure cooking green gram along with tamarind water, green chillies and then tempered. So simple yet very comforting. It can be served along with hot steaming rice with a dollop of ghee or even with roti or jolada rotti.', '["1 cup Green Moong Dal (Whole)", "2 Green Chillies , slit", "1/2 cup Tamarind Water", "1/2 teaspoon Turmeric powder (Haldi)", "3 cups Water", "Salt , to taste", "4 sprig Coriander (Dhania) Leaves , chopped", "2 teaspoon Ghee", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies", "1/2 teaspoon Asafoetida (hing)", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'tamarind water', 'ghee', 'mustard seeds', 'asafoetida (hing)', 'water', 'curry leaves', 'coriander (dhania) leaves', 'dry red chillies', 'green moong dal', 'turmeric powder', 'green chillies']::text[], '["To begin making Pasi Paruppu Masiyal Recipe\u00a0soak the green moong dal in 3 cups of water for at least for an hour.Into the pressure cooker, add the soaked green moong dal, salt, turmeric, slit green chillies, tamarind water.", "Cover the pressure cooker with its weight on.Cook the dal in the pressure cooker, until you here 3 to 4 whistles.", "Simmer the heat to low and continue to cook for another 10 minutes.", "After 10 minutes, turn off the heat and allow the pressure to release naturally.Open the pressure cooker and stir in the chopped coriander leaves.The next step is to give the Pasi Paruppu Masiyal Recipe a tadka.Heat the ghee in a small kadai, add mustard seeds, allow it to crackle; once it crackles add Asafoetida (hing), the red chilies and curry leaves and once the red chillies have roasted turn off the heat.", "Add this tadka to Pasi Paruppu Masiyal and give it a brisk boil.", "Check the salt and adjust to your taste and turn off the heat.Transfer the\u00a0Pasi Paruppu Masiyal Recipe to a serving bowl and serve hot.Serve Pasi Paruppu Masiyal along with\u00a0Jolada Roti\u00a0or\u00a0Steamed Rice\u00a0and\u00a0Kachumber Salad Recipe With Cucumber, Onion & Tomatoes\u00a0for a simple weekday lunch."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Pasi_Paruppu_Masiyal_recipe_Green_Moong_Dal_Curry_12_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1086.Pasi_Paruppu_Masiyal_recipe_Green_Moong_Dal_Curry_12_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('हैदराबादी खादी मसूर की दाल रेसिपी - Hyderabadi Khadi Masoor Ki Dal Recipe', 'hyderabadi-khadi-masoor-ki-dal-recipe', 'हैदराबादी खादी मसूर की दाल रेसिपी स्वादिष्ट दाल है जो आप अपने रोज के खाने के लिए बना सकते है. यह बनाने में बहुत आसान है और इसके मसालों से इसका अलग ही स्वाद आता है. यह आपके सेहत के लिए भी अच्छी है क्यूंकि इसमें प्रोटीन की मात्रा बहुत अधिक होती है.', '["1 \u0915\u092a \u092e\u0938\u0942\u0930 \u0926\u093e\u0932", "1 \u092a\u094d\u092f\u093e\u091c , \u092a\u0924\u0932\u093e \u0915\u093e\u091f \u0932\u0947", "1 \u091f\u092e\u093e\u091f\u0930 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0905\u0926\u0930\u0915 \u0932\u0939\u0938\u0941\u0928 \u0915\u093e \u092a\u0947\u0938\u094d\u091f", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u0915\u093e\u091f \u0932\u0947"]'::jsonb, ARRAY['कप मसूर दाल', 'प्याज', 'टमाटर', 'हरी मिर्च', 'छोटा चमच्च अदरक लहसुन का पेस्ट', 'छोटा चमच्च हल्दी पाउडर', 'छोटा चमच्च लाल मिर्च पाउडर', 'नमक', 'तेल', 'छोटा चमच्च हरा धनिया']::text[], '["\u0939\u0948\u0926\u0930\u093e\u092c\u093e\u0926\u0940 \u0916\u093e\u0926\u0940 \u092e\u0938\u0942\u0930 \u0915\u0940 \u0926\u093e\u0932 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947.\u00a0 \u0924\u0947\u0932 \u0915\u0947 \u0917\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u0928\u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 \u091f\u092e\u093e\u091f\u0930 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u091f\u092e\u093e\u091f\u0930 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0905\u0926\u0930\u0915 \u0932\u0939\u0938\u0941\u0928 \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a01 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092e\u0938\u0942\u0930 \u0926\u093e\u0932, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a02 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 2-1/2 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0926\u093e\u0932 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u0927\u0940\u092e\u0940 \u0906\u0902\u091a \u092a\u0930 \u092a\u0915\u0928\u0947 \u0926\u0947. \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.10 \u0938\u0947 15 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u0947 \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0939\u0948\u0926\u0930\u093e\u092c\u093e\u0926\u0940 \u0916\u093e\u0926\u0940 \u092e\u0938\u0942\u0930 \u0915\u0940 \u0926\u093e\u0932 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0932\u094c\u0915\u0940 \u092c\u095c\u0940 \u0915\u0940 \u0938\u092c\u094d\u095b\u0940,\u00a0\u092c\u0942\u0902\u0926\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u0914\u0930 \u092b\u0941\u0932\u094d\u0915\u0947 \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 25, 'Hyderabadi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Hyderabadi_Khadi_Masoor_Ki_Dal_Hyderabadi_Style_Lentil_Curry-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1087.Hyderabadi_Khadi_Masoor_Ki_Dal_Hyderabadi_Style_Lentil_Curry-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Drumstick Dal Recipe', 'drumstick-dal-recipe', 'The Drumstick Dal Recipe is a lip smacking day that is packed with flavours from the onion, lot of tomatoes, green chillies and is given a a delicious ghee tadka of curry leaves and hing.', '["1 cup Arhar dal (Split Toor Dal)", "2 Drumstick , cut into 3 inch pieces", "1 Onion , sliced", "2 Tomatoes , roughly chopped", "2 Green Chillies , slit", "1 teaspoon Kashmiri Red Chilli Powder", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "2 teaspoon Ghee", "1/4 teaspoon Asafoetida (hing)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "3 Dry Red Chillies"]'::jsonb, ARRAY['tomato', 'salt', 'arhar dal (split toor dal)', 'kashmiri red chilli powder', 'ghee', 'asafoetida (hing)', 'mustard seeds', 'drumstick', 'curry leaves', 'dry red chillies', 'onion', 'turmeric powder', 'green chillies']::text[], '["To begin making the Drumstick Dal, in a pressure cooker combine the toor dal along with onions, tomatoes, chili powder, haldi and\u00a0green chili, one and a half cups of water, close and pressure cook for three whistles and turn off the heat.", "Allow the pressure to release naturally.", "Once the pressure has released, open the cooker and give the dal a quick stir.", "Adjust the consistency to your liking.", "Pressure cook Drumsticks along with 2 tablespoons of water and a pinch of salt for two whistles and release the pressure immediately.Drumsticks should not become too soft.", "Cooking drumsticks separately retains their nutrition and color.Add the cooked drumsticks to the dal and give it a stir.", "Check the salt and seasonings and adjust according to taste.The next step is to make the tadka.", "In a tadka pan, add ghee and allow it to heat; add the mustard seeds and allow it to crackle.", "Add the asafoetida powder and curry leaves, and dry red chilies stir it in and turn off the heat.Pour this tempering over the cooked Drumstick Dal and transfer the dal to a serving bowl.Serve Drumstick Dal along with\u00a0Pavakkai Poriyal,\u00a0Rice\u00a0and a bowl of\u00a0curd\u00a0for a wholesome weeknight dinner or even a comforting lunch."]'::jsonb, 45, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Drumstick_Dal_Recipe-5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1088.Drumstick_Dal_Recipe-5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Potato Sagu Recipe for Rava Idli', 'potato-sagu-recipe-for-rava-idli', 'Potato curry or bhaji is cooked in various styles across the country. One such version is the potato sagu recipe which is very popular in Karnataka usually served alongside Rava Idlis, Set dosa and others in eateries like darshinis and restaurants.', '["3 Potatoes (Aloo) , boiled and mashed", "1 Onion , finely chopped", "2 Green Chillies , slit (adjust taste)", "1/2 inch Ginger , grated", "2 sprig Curry leaves", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 teaspoon White Urad Dal (Split)", "1 tablespoon Chana dal (Bengal Gram Dal)", "1/4 teaspoon Asafoetida (hing) , +a pinch", "1/2 teaspoon Turmeric powder (Haldi)", "1 tablespoon Coriander Powder (Dhania)", "2 tablespoons Coriander (Dhania) Leaves , chopped", "1 teaspoon Sugar", "1/2-1 tablespoon Lemon juice", "Salt , to taste", "Oil , as needed"]'::jsonb, ARRAY['salt', 'ginger', 'chana dal (bengal gram dal)', 'mustard seeds', 'asafoetida (hing)', 'coriander (dhania) leaves', 'curry leaves', 'white urad dal (split)', 'sugar', 'onion', 'lemon', 'coriander powder', 'potato (aloo)', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making Potato Sagu Recipe for Rava Idli, get prepped up with all the ingredients.", "In a kadai, heat some oil and add mustard seeds and let the seeds splutter.Once they splutter, add chana dal and urad dal and saute till they change slightly brown in colour.Once done add curry leaves, a pinch of asafoetida, green chilies, and grated ginger and saut\u00e9 it for a few seconds.After few seconds add onions, turmeric powder and a pinch of salt and cook until the onions are cooked but not browned.Once the onions are cooked add the mashed potatoes, remaining asafoetida and turmeric powder, coriander powder, chili powder, salt and sugar and stir well to combine.Add a cup of water and cook until you see a gravy consistency, continue to cook for 5-6 minutes on a low heat so that the potatoes absorb all the flavor.Once the potato sagu has reached the desired consistency add chopped coriander leaves and lemon juice.", "Stir to combine and turn off the heat.Transfer the potato sagu into a serving bowl and serve.", "Serve\u00a0Potato Sagu Recipe for Rava Idli with\u00a0Broccoli Rava Idli\u00a0and\u00a0Green Coriander Coconut Chutney\u00a0for a wholesome breakfast."]'::jsonb, 55, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Preethi_Kitchen_appliances_video_recipe_Karnataka_Style_Aloo_Sagu_recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1089.Preethi_Kitchen_appliances_video_recipe_Karnataka_Style_Aloo_Sagu_recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('आलू सागु रेसिपी - Potato Sagu Recipe', 'potato-sagu-recipe', 'आलू की सब्ज़ी को अलग अलग तरह से बनाया जाता है. यह हम आलू सागु बनाएंगे जिसे कर्नाटक में बनाया जाता है और रवा इडली, सेट डोसा के साथ दर्शिनी में परोसा जाता है. आप इससे सगु को अपने लंच बॉक्स में भी पैक कर सकते है.', '["3 \u0906\u0932\u0942 , \u0909\u092c\u093e\u0932\u0915\u0930 \u092e\u0948\u0936 \u0915\u0930 \u0932\u0947", "1 \u092a\u094d\u092f\u093e\u091c , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0915\u093e\u091f \u0932\u0947", "1/2 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u0915\u0938 \u0932\u0947", "2 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0938\u095e\u0947\u0926 \u0909\u0930\u0926 \u0926\u093e\u0932", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u091a\u0928\u093e \u0926\u093e\u0932", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0940\u0902\u0917 , \u091a\u0941\u091f\u0915\u0940 \u092d\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u0915\u093e\u091f \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0936\u0915\u094d\u0915\u0930", "1/2-1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0928\u093f\u092e\u094d\u092c\u0942 \u0915\u093e \u0930\u0938", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['आलू', 'प्याज', 'हरी मिर्च', 'इंच अदरक', 'टहनी कढ़ी पत्ता', 'छोटा चम्मच राइ', 'छोटा चम्मच सफ़ेद उरद दाल', 'बड़ा चम्मच चना दाल', 'छोटा चम्मच हींग', 'छोटा चम्मच हल्दी पाउडर', 'बड़ा चम्मच धनिया पाउडर', 'बड़े चम्मच हरा धनिया', 'छोटा चम्मच शक्कर', 'बड़ा चम्मच निम्बू का रस', 'नमक', 'तेल']::text[], '["\u0906\u0932\u0942 \u0938\u093e\u0917\u0941 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907 \u0921\u093e\u0932\u0947 \u090f\u092f\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u091a\u0928\u093e \u0926\u093e\u0932, \u0909\u0930\u0926 \u0926\u093e\u0932 \u0921\u093e\u0932\u0947 \u0915\u0930 \u0938\u0941\u092c\u0939\u093e\u0930\u093e \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e, \u0939\u0940\u0902\u0917, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0905\u0926\u0930\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 30 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f\u00a0\u092a\u0915\u093e \u0932\u0947.\u00a0\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u094b \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092e\u0948\u0936 \u0915\u093f\u092f\u0947 \u0939\u0941\u090f \u0906\u0932\u0942, \u0939\u0940\u0902\u0917, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915, \u0936\u0915\u094d\u0915\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a01 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 5 \u0938\u0947 6 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u0947 \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0906\u0932\u0942 \u0938\u093e\u0917\u0941 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0938\u092c\u094d\u095b \u0930\u0935\u093e \u0907\u0921\u0932\u0940\u00a0\u0914\u0930 \u095e\u093f\u0932\u094d\u091f\u0930 \u0915\u0949\u095e\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0938\u0941\u092c\u0939 \u0915\u0947 \u0928\u093e\u0936\u094d\u0924\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 55, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Preethi_Kitchen_appliances_video_recipe_Karnataka_Style_Aloo_Sagu_recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1090.Preethi_Kitchen_appliances_video_recipe_Karnataka_Style_Aloo_Sagu_recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('मुलांगी करी रेसिपी - Mullangi Curry (Recipe In Hindi)', 'mullangi-curry-recipe-in-hindi', 'मूली को तमिल में मुलांगी भी कहाँ जाता है. यह एक रस से भरी सब्ज़ी है जो की पोषण से भरपूर है. इसमें फाइबर की मात्रा अधिक होती है और यह वेट कम करने के लिए भी अच्छी होती है. आप इस से कई प्रकार की सब्जिआ बना सकते है लेकिन यहाँ हम इसे तमिल स्टाइल से बनाएंगे।', '["2 \u092e\u0942\u0932\u0940 , \u0927\u094b\u0915\u0930, \u091b\u0940\u0932\u0915\u0930 \u0915\u093e\u091f \u0915\u0947", "1/8 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u091a\u094d\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u091a\u0928\u093e \u0926\u093e\u0932", "1 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u0924\u093f\u0932 \u0915\u093e \u0924\u0947\u0932", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0915\u093e\u0932\u0940 \u0909\u0930\u0926 \u0926\u093e\u0932 (\u0938\u094d\u092a\u094d\u0932\u093f\u091f)", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u091c\u0940\u0930\u093e", "1 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e"]'::jsonb, ARRAY['मूली', 'छोटा चमच्च हल्दी पाउडर', 'छोटे चमच्च लाल मिर्च पाउडर', 'छोटा चमच्च धनिया पाउडर', 'नमक', 'तड़के के लिए', 'छोटा चमच्च चना दाल', 'बड़ा चमच्च तिल का तेल', 'छोटा चमच्च काली उरद दाल', 'स्प्लिट', 'छोटा चमच्च जीरा', 'टहनी कढ़ी पत्ता']::text[], '["\u092e\u0941\u0932\u093e\u0902\u0917\u0940 \u0915\u0930\u0940 \u0915\u094b \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f \u0926\u0940 \u0917\u0908 \u0938\u093e\u092e\u0917\u094d\u0930\u0940 \u0915\u094b \u090f\u0915 \u090f\u0915 \u0915\u0930 \u0915\u0947 \u0921\u093e\u0932\u0947\u0964\u00a015 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0917\u093e\u091c\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. \u0917\u093e\u091c\u0930 \u092e\u093f\u0932\u093e\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930 \u0914\u0930 \u0928\u092e\u0915 \u0921\u093e\u0932\u0947\u0964\u00a01 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u093e\u090f \u0906\u0909\u091f \u092b\u093f\u0930 1/2 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947\u0964 \u0915\u095d\u093e\u0908 \u0915\u094b \u0922\u0915\u0947 \u0914\u0930 \u092e\u0942\u0932\u0940 \u0915\u094b \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u0928\u0947 \u0926\u0947. \u092c\u093f\u091a \u092c\u093f\u091a \u092e\u0947\u0902 \u0939\u093f\u0932\u093e\u0924\u0947 \u0930\u0939\u0947.\u092a\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0915\u095c\u093e\u0939\u0940 \u0915\u094b \u0916\u094b\u0932\u0947 \u0914\u0930 20 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0924\u0947\u091c \u0906\u0902\u091a \u092a\u0930 \u092a\u0915\u093e\u090f\u0964 \u0917\u0930\u092e\u093e \u0917\u0930\u092e \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092e\u0941\u0932\u093e\u0902\u0917\u0940 \u0915\u0930\u0940 \u0915\u094b \u092e\u093f\u0915\u094d\u0938\u094d\u0921 \u0935\u0947\u091c\u093f\u091f\u0947\u092c\u0932 \u0938\u093e\u0902\u092c\u0930 \u0914\u0930 \u091a\u093e\u0935\u0932 \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 40, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Uma_Raghuraman/Mullangi_Curry__South_Indian_Style_Raddish_Stir_Fry_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1091.Mullangi_Curry__South_Indian_Style_Raddish_Stir_Fry_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('उलावा चारु रेसिपी - Horse Gram Rasam (Recipe In Hindi)', 'horse-gram-rasam-recipe-in-hindi', 'उलावा चारु कर्नाटक की रेसिपी है जिसमे कुलीथ की दाल को स्टू के जैसे पकाया जाता है. कुलीथ के पानी को प्याज टमाटर और नारियल के पेस्ट में पकाया जाता है. यह बनाने में आसान है और सेहत के लिए बहुत अच्छा माना जाता है.', '["1 \u0915\u092a \u0915\u0941\u0932\u0940\u0925 \u0926\u093e\u0932", "1/4 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932", "1 \u092a\u094d\u092f\u093e\u091c , \u0915\u093e\u091f \u0932\u0947", "1 \u091f\u092e\u093e\u091f\u0930 , \u0915\u093e\u091f \u0932\u0947", "1 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a", "3 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "\u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e , \u0925\u094b\u095c\u0947", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "1 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u0924\u0947\u0932"]'::jsonb, ARRAY['कप कुलीथ दाल', 'कप नारियल', 'प्याज', 'टमाटर', 'हरी मिर्च', 'सुखी लाल मिर्च', 'कढ़ी पत्ता', 'छोटा चमच्च हल्दी पाउडर', 'नमक', 'बड़ा चमच्च तेल']::text[], '["\u0909\u0932\u093e\u0935\u093e \u091a\u093e\u0930\u0941 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0926\u093e\u0932 \u0915\u094b \u0927\u094b\u0915\u0930 \u0930\u0924 \u092d\u0930 \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u092d\u093f\u0917\u094b \u0926\u0947. \u092d\u093f\u0917\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0926\u093e\u0932 \u0915\u094b 2 \u0915\u092a \u092a\u093e\u0928\u0940 \u0915\u0947 \u0938\u093e\u0925 15 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e\u090f\u0964 \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0926\u093e\u0932 \u0914\u0930 \u092a\u093e\u0928\u0940 \u0915\u094b \u091b\u0932\u0928\u0940 \u0915\u0940 \u092e\u0926\u0926 \u0938\u0947\u00a0\u0905\u0932\u0917 \u0915\u0930 \u0926\u0947. \u092a\u093e\u0928\u0940 \u0915\u094b \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0928\u093e\u0930\u093f\u092f\u0932, \u092a\u094d\u092f\u093e\u091c, \u091f\u092e\u093e\u091f\u0930, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a \u0914\u0930 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947\u0964 \u092a\u0940\u0938 \u0932\u0947 \u0914\u0930 \u0907\u0938\u0915\u093e \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0917\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092a\u093f\u0938\u093e \u0939\u0941\u0906 \u092e\u0938\u093e\u0932\u093e \u0921\u093e\u0932\u0947\u0964 6 \u0938\u0947 8 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u0928\u0947 \u0926\u0947. \u092c\u093f\u091a \u092c\u093f\u091a \u092e\u0947\u0902 \u0939\u093f\u0932\u093e\u0924\u0947 \u0930\u0939\u0947.\u00a06 \u0938\u0947 8 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0926\u093e\u0932 \u0915\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 5 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u0928\u0947 \u0926\u0947. 5 \u092e\u093f\u0928\u091f \u092c\u093e\u0926, \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0917\u0930\u092e\u093e \u0917\u0930\u092e \u092a\u0930\u094b\u0938\u0947\u0964\u0909\u0932\u093e\u0935\u093e \u091a\u093e\u0930\u0941 \u0915\u094b \u091a\u093e\u0935\u0932 \u0914\u0930\u00a0\u0924\u092e\u093f\u0932 \u0928\u093e\u0921\u0941 \u0938\u094d\u091f\u093e\u0907\u0932 \u092c\u094d\u0930\u094b\u0915\u0932\u0940 \u092a\u094b\u0930\u093f\u092f\u0932\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Monika_Manchanda/Ulava_Charu_Horse_Gram_Stew.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1092.Ulava_Charu_Horse_Gram_Stew.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('वाली भाजी अंबट रेसिपी - Vali Bhajji Ambat (Recipe In Hindi)', 'vali-bhajji-ambat-recipe-in-hindi', 'वाली भाजी अंबट कोंकण करी है जिसमे पालक का प्रयोग किया जाता है. इसमें मालाबार पालक का प्रयोग किया जाता है जिससे इस दाल का स्वाद और भी बढ़ जाता है. यह बनाने में आसान है इसलिए आप इसे अपने रोज के खाने के लिए भी बना सकते है. इसमें रोस्टेड नारियल का मसाला भी डाला जाता है.', '["2 \u0915\u092a \u092a\u093e\u0932\u0915 , \u092e\u093e\u0932\u093e\u092c\u093e\u0930, \u0915\u093e\u091f \u0932\u0947", "1/2 \u0915\u092a \u0905\u0930\u0939\u0930 \u0926\u093e\u0932", "1 \u092a\u094d\u092f\u093e\u091c , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u091f\u092e\u093e\u091f\u0930 , \u0915\u093e\u091f \u0932\u0947", "30 \u0917\u094d\u0930\u093e\u092e \u0907\u092e\u0932\u0940 , \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u092e\u093f\u0932\u093e\u0915\u0947 \u091c\u0942\u0938 \u0928\u093f\u0915\u093e\u0932 \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0917\u0941\u095c , \u092a\u093e\u0909\u0921\u0930 \u092c\u0928\u093e \u0932\u0947", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u092a\u0940\u0938\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f", "1/2 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947", "1 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c , \u0930\u094b\u0938\u094d\u091f \u0915\u0930 \u0932\u0947", "4-5 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0930\u093e\u0907", "4 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928 , \u0915\u0938 \u0932\u0947", "\u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['कप पालक', 'कप अरहर दाल', 'प्याज', 'टमाटर', 'ग्राम इमली', 'छोटा चमच्च हल्दी पाउडर', 'छोटा चमच्च गुड़', 'नमक', 'पीसने के लिए', 'कप नारियल', 'बड़ा चमच्च धनिये के बीज', 'सुखी लाल मिर्च', 'तड़के के लिए', 'छोटा चमच्च राइ', 'कली लहसुन', 'तेल']::text[], '["\u0935\u093e\u0932\u0940 \u092d\u093e\u091c\u0940 \u0905\u0902\u092c\u091f \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a, \u0928\u093e\u0930\u093f\u092f\u0932 \u0921\u093e\u0932\u0947\u0964 20 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0924\u0915 \u092a\u0915\u093e\u090f \u0914\u0930 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0926\u0947. \u092e\u093f\u0936\u094d\u0930\u0923 \u0915\u0947 \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u0947 \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0940\u0938 \u0932\u0947.\u00a0\u00a0\u092a\u093e\u0932\u0915 \u0915\u094b \u0927\u094b \u0932\u0947 \u0914\u0930 \u0915\u093e\u091f \u0932\u0947. \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902\u00a0\u0925\u094b\u095c\u093e \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902\u00a0\u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u093e\u0928\u0940, \u0905\u0930\u0939\u0930 \u0926\u093e\u0932, \u092a\u093e\u0932\u0915, \u091f\u092e\u093e\u091f\u0930 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 3 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947.\u00a0\u0926\u093e\u0932 \u0915\u094b \u0905\u091a\u094d\u091b\u0947 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u0905\u0917\u0930 \u0925\u094b\u095c\u093e \u0914\u0930 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0928\u093e \u0939\u0948, \u0921\u093e\u0932\u0915\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u092a\u093f\u0938\u093e \u0939\u0941\u0906 \u092e\u093f\u0936\u094d\u0930\u0923 \u0914\u0930 \u0926\u093e\u0932 \u0915\u093e \u092e\u093f\u0936\u094d\u0930\u0923 \u0921\u093e\u0932\u0947\u0964 \u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0917\u0941\u095c \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. 3 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0914\u0930 \u092a\u0915\u0928\u0947 \u0926\u0947.\u00a0\u090f\u0915 \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u0932\u0939\u0938\u0941\u0928 \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u0928\u0947 \u0926\u0947. \u0907\u0938 \u092e\u093f\u0936\u094d\u0930\u0923 \u0915\u094b \u0926\u093e\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u0935\u093e\u0932\u0940 \u092d\u093e\u091c\u0940 \u0905\u0902\u092c\u091f \u0915\u094b \u0935\u0947\u0902\u0917\u0928\u093e\u00a0\u0915\u093e\u092a \u0914\u0930 \u091a\u093e\u0935\u0932 \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 55, 'Malabar', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/oct-17/Vali_Bhajji_Ambat_Recipe_Konkan_Style_Spiced_Malabar_Spinach_Dal_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1093.Vali_Bhajji_Ambat_Recipe_Konkan_Style_Spiced_Malabar_Spinach_Dal_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('गुजराती कढ़ी रेसिपी - Gujarati Kadhi Recipe', 'gujarati-kadhi-recipe', 'गुजराती कढ़ी एक मीठी और खट्टी करी है जिसे दही से बनाया जाता है. इसमें मीठापन गुढ़ से आता है और तीखापन हरी मिर्च से. इससे चावल या खिचड़ी के साथ परोसा जाता है. इसे आप रोज के खाने के लिए सब्ज़ी और रोटी के साथ बना सकते है.', '["1 \u0915\u092a \u0926\u0939\u0940", "2 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u092c\u0947\u0938\u0928", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0940\u0902\u0917", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u0917\u0941\u0921 , \u092a\u093e\u0909\u0921\u0930 \u0915\u0930 \u0932\u0947", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u091c\u0940\u0930\u093e", "1/4 \u0930\u093e\u0907", "1 \u0907\u0902\u091a \u0926\u093e\u0932 \u091a\u0940\u0928\u0940", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0905\u0926\u0930\u0915 , \u0915\u0938 \u0932\u0947", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0915\u093e\u091f \u0932\u0947", "1 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u0918\u0940", "5 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u0915\u093e\u091f \u0932\u0947"]'::jsonb, ARRAY['कप दही', 'बड़ा चमच्च बेसन', 'छोटा चमच्च हींग', 'छोटा चमच्च हल्दी पाउडर', 'बड़ा चमच्च गुड', 'नमक', 'तड़के के लिए', 'छोटा चमच्च जीरा', 'राइ', 'इंच दाल चीनी', 'छोटा चमच्च अदरक', 'हरी मिर्च', 'बड़ा चमच्च घी', 'टहनी कढ़ी पत्ता', 'बड़ा चमच्च हरा धनिया']::text[], '["\u0917\u0941\u091c\u0930\u093e\u0924\u0940 \u0915\u095d\u0940 \u0915\u094b \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0926\u0939\u0940 \u092e\u0947\u0902 2 \u0915\u092a \u092a\u093e\u0928\u0940, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u092c\u0947\u0938\u0928, \u0939\u0940\u0902\u0917, \u0917\u0941\u095c \u0914\u0930 \u0928\u092e\u0915 \u0921\u093e\u0932\u0947. \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e\u090f \u0924\u093e\u0915\u093f \u0917\u093e\u0920 \u0928 \u092a\u095c\u0947.\u00a0\u0907\u0938 \u092e\u093f\u0936\u094d\u0930\u0923 \u0915\u094b \u090f\u0915 \u0938\u0949\u0938 \u092a\u0948\u0928 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u092c\u0932\u0928\u0947 \u0926\u0947. 8 \u0938\u0947 10 \u092e\u093f\u0928\u091f \u0924\u0915 \u0909\u092c\u0932\u0928\u0947 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u091b\u094b\u091f\u0940 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u091c\u0940\u0930\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 15 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0924\u0915 \u092a\u0915\u0928\u0947 \u0926\u0947. 15 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e, \u0926\u093e\u0932\u091a\u0940\u0928\u0940, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a \u0914\u0930 \u0905\u0926\u0930\u0915 \u0921\u093e\u0932\u0947\u0964\u00a0\u0907\u0938 \u0924\u095c\u0915\u0947 \u0915\u094b \u0915\u095d\u0940 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u0928\u0947 \u0926\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0939\u0930\u0947 \u0927\u0928\u093f\u090f \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902\u0964\u00a0\u0917\u0941\u091c\u0930\u093e\u0924\u0940 \u0915\u095d\u0940 \u0915\u094b \u091a\u093e\u0935\u0932 \u092f\u093e \u0916\u093f\u091a\u095c\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0930\u093e\u0924 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 35, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Gujarati_Kadhi_Recipe_Sweet_and_Spicy_Yogurt_Curry-1-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1094.Gujarati_Kadhi_Recipe_Sweet_and_Spicy_Yogurt_Curry-1-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Varan Bhaat Recipe - Maharashtrian Dal Recipe', 'varan-bhaat-recipe-maharashtrian-dal-recipe', 'Varan Bhaat Recipe is a simple and quick Goan/ Maharastrian staple of dal and rice that is typically made during festivals and other special occasions. It is a chief component of the traditional offering to God known as “naivedyam.” While it is common for some to add a tempering of curry leaves to this, the classic preparation is simple, without any tempering, allowing the delicious, comforting flavours of the lentils to shine through. Make Varan Bhaat along with Potato Fry and Plain Steamed Rice for a simple homely meal.', '["1/4 cup Arhar dal (Split Toor Dal)", "1 Green Chilli , finely chopped", "1/4 cup Fresh coconut , finely grated", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Ingredients for seasoning", "2 tablespoons Ghee", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Cumin seeds (Jeera)"]'::jsonb, ARRAY['arhar dal', 'split toor dal', 'reen chilli', 'fresh coconut', 'cumin seeds', 'jeera', 'turmeric powder', 'haldi', 'salt', 'ingredients for seasoning', 's ghee', 'asafoetida', 'hing']::text[], '["To begin making the Varan Bhaat Recipe we will first pressure cook the toor dal and green chilies together along with 1 cup water until you hear a couple of whistles.", "After a couple of whistles, turn the heat to low and cook for another 3 to 4 minutes and turn off the heat.Once you have turned off the heat, allow the pressure to release naturally, as the dal will continue to cook in the pressure.", "In the meanwhile, make a smooth saucy mixture by grinding the coconut, turmeric powder and cumin seeds along with water in a blender.", "Add this to the cooked dal and whisk it well together.", "Add salt to taste and transfer to a serving bowl.The final step is to season the dal for the\u00a0Varan Bhaat.", "Heat ghee in a small tadka pan, add the cumin seeds and asafoetida and allow it to crackle for a few seconds.", "Turn off the heat.", "Pour this seasoning into the dal\u00a0and serve the Varan Bhaat along with\u00a0hot steamed rice.", "Note: Some people add curry leaves while tempering.", "This is optional."]'::jsonb, 40, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Varan_Bhaat.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1095.Varan_Bhaat.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('वरन भात रेसिपी - Varan Bhaat Recipe', 'varan-bhaat-recipe', 'वरन भात एक सरल और जल्द बनने वाली गोअन रेसिपी है जिसे ज्यादातर त्यौहार या किसी भी ख़ास दिन बनाया जाता है. इसे भगवन को चढ़ाया जाता है, फिर इसका सेवन किया जाता है. इसमें आप कढ़ी पत्ते का तड़का भी डाल सकते है, लेकिन ज्यादातर इसमें तड़का नहीं डाला जाता।', '["1/4 \u0915\u092a \u0905\u0930\u0939\u0930 \u0926\u093e\u0932", "1 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1/4 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0918\u0940", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0940\u0902\u0917", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e"]'::jsonb, ARRAY['कप अरहर दाल', 'हरी मिर्च', 'कप नारियल', 'छोटा चम्मच जीरा', 'छोटा चम्मच हल्दी पाउडर', 'नमक', 'तड़के के लिए', 'बड़े चम्मच घी', 'छोटा चम्मच हींग']::text[], '["\u0935\u0930\u0928 \u092d\u093e\u0924 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0939\u092e \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0924\u0941\u0905\u0930 \u0926\u093e\u0932 \u0915\u0947 \u0938\u093e\u0925 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, 1 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947\u0902\u0917\u0947\u0964 \u0915\u0941\u0915\u0930 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 2 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0906\u0902\u091a \u0915\u094b \u0927\u0940\u092e\u093e \u0915\u0930\u0947\u0902 \u0914\u0930 5 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0926\u0947.\u00a0\u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0928\u093e\u0930\u093f\u092f\u0932, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u091c\u0940\u0930\u093e, \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0940\u0938 \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u0915\u0940 \u0939\u0941\u0908 \u0926\u093e\u0932, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f\u00a0\u0914\u0930 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0928\u093f\u0915\u093e\u0932 \u0932\u0947.\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f \u090f\u0915 \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u091c\u0940\u0930\u093e, \u0939\u0940\u0902\u0917 \u0921\u093e\u0932\u0947 \u0914\u0930 10 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0924\u095c\u0915\u0947 \u0915\u094b \u0926\u093e\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0935\u0930\u0928 \u092d\u093e\u0924 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u091a\u093e\u0935\u0932 \u0914\u0930\u00a0\u0939\u0930\u0947 \u092a\u094d\u092f\u093e\u091c \u0914\u0930 \u0906\u0932\u0942\u00a0\u0915\u0940 \u0938\u092c\u094d\u095b\u0940\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 40, 'Goan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Varan_Bhaat.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1096.Varan_Bhaat.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kollu Rasam Recipe - Healthy Horse Gram Rasam', 'kollu-rasam-recipe-healthy-horse-gram-rasam', 'Kollu Rasam Recipe is a wholesome recipe of rasam made from horse gram. It is rich in taste and at the same time rich in protein and iron apart and has high antioxidant capacities along with hemagglutinin which is a substance found in antibodies and autoimmune functions.', '["1 cup Tamarind Water", "2 Tomatoes , made into a puree", "50 grams Horse Gram Dal (Kollu/ Kulith) , soaked for 4 hours", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera) , roasted", "1 teaspoon Coriander Powder (Dhania) , roasted", "1/4 teaspoon SSP Asafoetida (Hing)", "1/2 teaspoon Black pepper powder", "Salt , to taste", "1/2 teaspoon Red Chilli powder , as required", "5 sprig Coriander (Dhania) Leaves , chopped for garnishing", "Ingredients for the Seasoning", "1 tablespoon Ghee", "3 cloves Garlic , crushed", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'tamarind water', 'asafoetida (hing)', 'ghee', 'mustard seeds', 'red chilli powder', 'cloves garlic', 'curry leaves', 'coriander (dhania) leaves', 'black pepper powder', 'horse gram dal (kollu kulith)', 'coriander powder', 'turmeric powder']::text[], '["To begin making the Kollu Rasam Recipe, first soak the Kollu (horse gram) for 4 hours or overnight.Once it is well soaked, add 1/4 cup of\u00a0 water and cook it in the pressure cooker for\u00a0 6 whistles.", "Turn the heat to low and simmer for another 15 minutes and turn of the heat.", "Allow the pressure to release naturally.Combine the tomato puree, tamarind water and the cooked kollu/horse gram in a saucepan.Add in the turmeric powder, cumin, coriander powder, asafoetida and black pepper powder.Add in the salt to taste and stir well.", "Place this mixture on high heat and boil it for 5 to 8 minutes until you smell the aromas rising.Adjust the consistency of the horse gram rasam by adding more water if required.Check the salt and seasonings at this stage and adjust to taste accordingly.While the Kollu Rasam is simmering, we will proceed to make the seasoningHeat ghee in a small pan; add in the mustard seeds and allow it to crackle.", "Next add in the crushed garlic cloves and stir for a few seconds until you smell the aromas.Finally add in the curry leaves and turn off the heat and add the seasoning to the horse gram rasam.", "Transfer the Kollu Rasam into a serving bowl and serve hot.Serve\u00a0Kollu Rasam/ Horse gram Rasam along with\u00a0Steamed Rice\u00a0and\u00a0Chena Vazhakkai Erissery\u00a0and\u00a0Elai Vadam\u00a0for a weekday meal."]'::jsonb, 70, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/SSP_Kollu_Rasam_Step_By_Step_Horse_Gram_Rasam_6-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1097.SSP_Kollu_Rasam_Step_By_Step_Horse_Gram_Rasam_6-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spiced Ghee Rice Recipe | Neychoru', 'spiced-ghee-rice-recipe-neychoru', 'Ghee Rice Recipe | Neychoru, it is such a flavorful rice usually prepared in the festival days. It is such a comfort food ,with just a large dollop of Ghee cooked along with Basmati Rice and all the whole spices bring such a nice flavour to the food.', '["1 cup Basmati rice , soaked in water for 20 minutes", "1 Onion , chopped (lengthwise preferably)", "2 Green Chilli , slit", "1 tablespoon Ginger Garlic Paste", "1 tablespoon Ghee", "1 teaspoon Fennel seeds (Saunf)", "1 Bay leaf (tej patta)", "1 Star anise", "3 Cloves (Laung)", "2 Cardamom (Elaichi) Pods/Seeds , crushed", "Salt , as needed", "4 Cashew nuts , broken", "2 Sultana Raisins", "1 Apricots , chopped", "1-1/4 cup Water , (adjust)"]'::jsonb, ARRAY['cashew nuts', 'basmati rice', 'salt', 'green chilli', 'apricots', 'ghee', 'fennel seeds (saunf)', 'bay leaf (tej patta)', 'cardamom (elaichi) podsseeds', 'raisins', 'water', 'ginger garlic paste', 'onion', 'cloves (laung)', 'star anise']::text[], '["To prepare Ghee Rice Recipe | Neychoru, in a pan/Pressure cooker add in a tbsp of ghee and fry the Raisins apricot and Cashew nuts and set aside.In the Same pan add in a quarter portion of the sliced Onions and fry till dark brown set that also aside.", "In the same pan add in another tbsp. of Ghee and then add in Fennel Seeds, Cinnamon sticks, Star Anise, Green Cardamom, Clove and Bay Leaves once they emits a nice flavour add in the Slit Green Chillies and fry for a minute.Next add in the remaining sliced onion and fry till they become golden brown.Next add in the Ginger Garlic paste and fry till the saw smell leaves and next add in the Soaked Basmati Rice.", "Fry it well for about 5 minutes in low flame.Mix well and add the measured water now you can keep the stove in a high flame add in required salt and mix well.Add in the remaining 1 tbsp of Ghee and once the water starts to boil close the cooker and cook for a whistle.", "Wait till the pressure gets released by itself and then open the cooker.Carefully fluff with a fork.", "Now top the Ghee Rice Recipe | Neychoru with the reserved onions and nuts and serve hot with\u00a0Kozhi Kuzhambu\u00a0(non-veg) or\u00a0Senai Kizhangu Ghostu\u00a0(veg)\u00a0and\u00a0Tadka Raita\u00a0for complete meal."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/happytrioexplains-gmail.com/Ghee_Rice_Recipe_Neychoru.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1098.Ghee_Rice_Recipe_Neychoru.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mughlai Aloo Lajawab Recipe - Mughlai Aloo Sabzi Recipe', 'mughlai-aloo-lajawab-recipe-mughlai-aloo-sabzi-recipe', 'Mughlai Aloo Lajawab Recipe is a rich and luscious potato gravy, which originates from the house of Nawabs. The potatoes are roasted and then simmered in a thick cashew, cream, tomato based gravy.', '["6 Potatoes (Aloo) , cut into big cubes", "1 Onion , finely chopped", "4 Tomatoes , blended into a puree", "4 tablespoons Cashew nuts", "6 cloves Garlic", "2 inch Ginger , roughly chopped", "1/4 cup Milk", "1 teaspoon Ajwain (Carom seeds)", "1 teaspoon Kashmiri Red Chilli Powder", "2 teaspoons Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "2 tablespoons Fresh cream", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves) , for garnish", "1 tablespoon Oil , for roasting potatoes", "1 tablespoon Ghee , for the mughlai gravy", "Salt , to taste"]'::jsonb, ARRAY['potatoes', 'aloo', 'onion', 'tomatoes', 's cashew nuts', 's garlic', 'ginger', 'milk', 'ajwain', 'carom seeds', 'kashmiri red chilli powder', 's coriander powder', 'dhania', 'turmeric powder', 'haldi', 'garam masala powder', 's fresh cream', 'kasuri methi', 'dried fenugreek leaves', 'oil', 'ghee', 'salt']::text[], '["To begin making\u00a0Mughlai Aloo Lajawab Recipe, soak the cashews in warm milk for 10 minutes and then blend it into a smooth paste using a mixer grinder.", "Keep aside.Similarly blend the tomatoes in a fine puree and keep aside.Heat oil in a heavy bottomed pan, add the cubed potatoes, fry until the potatoes turns golden and crisp.", "Remove it in a kitchen absorbent paper and keep aside.Heat ghee in a wok, add the ajwain, let the ghee become fragrant.Add the onion, ginger and garlic and saute until it turns soft and translucent.Once the onions are soft, add in the tomato puree, turmeric powder, coriander powder, kashmiri red chilli and garam masala powder.", "Simmer the tomatoes until it all the spices are absorbed well into the gravy.Once the tomatoes are cooked through, add\u00a0the prepared cashew mix and let it cook for about 2 to 3 minutes.", "Add the roasted potatoes, add a little water, cream, salt and stir well to combine.Check the salt and spices and adjust accordingly.", "Simmer the\u00a0Mughlai Aloo Lajawab for another 5 minutes until the potatoes absorb the gravy.", "At this stage, if you find the Mughlai Aloo Sabzi is too thick add water and seasoning as per your desired consistency.Once the Mughlai Aloo Sabzi comes together, add in the cream, mix and turn off the heat.", "Garnish it with kasuri methi and serve hot.Serve the\u00a0Mughlai Aloo Lajawab Recipe\u00a0along with\u00a0Butter Naan,\u00a0Methi Matar Pulao,\u00a0Dal Makhani,\u00a0Kurkuri Bhindi\u00a0and\u00a0Boondi Raita\u00a0for your next house party menu.", "Add a\u00a0Gulab Jamoon\u00a0into your party menu to make it special.You can also serve the\u00a0Mughlai Aloo Lajawab\u00a0for a simple weekday Lunch or pack into your office lunch box with\u00a0Tawa Paratha\u00a0and\u00a0Tadka Raita."]'::jsonb, 50, 'Mughlai', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Mughlai_Aloo_Lajawab_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1099.Mughlai_Aloo_Lajawab_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Baingan Bharta Recipe - Smoked Roasted Eggplant with Green Chillies and Ginger', 'baingan-bharta-recipe-smoked-roasted-eggplant-with-green-chillies-and-ginger', 'Baingan Bharta is a classic Punjabi Recipe that is made from smoked and chargrilled brinjals then mish-mashed and cooked along with a combination of spices. The main ingredient of the Baingan Bharta that adds to its flavours is the green chillies, ginger along with finely chopped tomatoes and coriander powder. Every region in india has their own version of Baingan Bharta and this is our family recipe for making delicious Baingan Bharta.', '["1 Brinjal (Baingan / Eggplant)", "2 inch Ginger , finely chopped", "1 Onion , finely chopped", "1 Tomato , finely chopped", "2 Green Chillies , finely chopped", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Coriander Powder (Dhania)", "2 tablespoons Ghee", "1 teaspoon Red Chilli powder", "Salt , to taste", "4 sprig Coriander (Dhania) Leaves , finely chopped for garnish"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'ghee', 'brinjal (baingan eggsplant)', 'red chilli powder', 'coriander (dhania) leaves', 'onion', 'coriander powder', 'turmeric powder', 'green chillies', 'garam masala powder']::text[], '["To begin making the Baingan\u00a0Bharta Recipe , first prep all the ingredients and keep them ready.The brinjal needs to be roasted and can be roasted in two ways; in the oven or on the gas flame."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Baingan_Bharta_Sabzi_Recipe_Smoked_Roasted_Eggplant_with_Green_Chillies_and_Ginger-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1100.Baingan_Bharta_Sabzi_Recipe_Smoked_Roasted_Eggplant_with_Green_Chillies_and_Ginger-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Poha Recipe - Batata Poha', 'aloo-poha-recipe-batata-poha', 'Aloo Poha also known as the Batata Poha brings with it delicious tastes and textures of sweetness, sourness, softness and crunchiness. It is made tangy and spicy from green chillies and lemon juice along with boiled potatoes that further enhances the texture.', '["2 cups Poha (Flattened rice)", "2 Potatoes (Aloo) , boiled, peeled & cubed", "1/4 cup Green peas (Matar) , steamed", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves , finely chopped", "2 Onion , finely chopped", "2 Green Chillies , slit lengthwise", "2 inch Ginger , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Asafoetida (hing)", "2 teaspoons Sugar", "2 Lemons , juice extracted", "2 tablespoon Roasted Peanuts (Moongphali)", "2 tablespoons Oil", "2 tablespoons Coriander (Dhania) Leaves , finely chopped", "3/4 cup Fresh Pomegranate Fruit Kernels , to serve", "Salt , to taste", "Alternative Ingredients: You can use the following ingredients in addition to the potatoes", "1/2 cup Sweet corn , steamed", "1/2 cup Green Moong Sprouts"]'::jsonb, ARRAY['s poha', 'flattened rice', 'potatoes', 'aloo', 'green peas', 'matar', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'curry leaves', 'onion', 'reen chillies', 'ginger', 'turmeric powder', 'haldi', 'asafoetida', 'hing', 's sugar', 'lemons', 'roasted peanuts', 'moongphali', 's oil', 's coriander', 'dhania', 'fresh pomegranate fruit kernels', 'salt', 'alternative ingredients: you can use the following ingredients in addition to the potatoes', 'sweet corn', 'green moong sprouts']::text[], '["To begin making the Aloo Poha Recipe-Batata Poha Recipe, we will first rinse the poha or flattened rice under cold water and drain any excess water.", "Using a large strainer for washing helps ease the rinsing process.", "Transfer the rinsed rice to a large bowl; stir in the turmeric, salt, sugar, asafoetida and keep aside.Heat oil in a pan on medium heat; add the mustard seeds, cumin seeds and allow them to crackle.Once the seeds have crackle stir in the onions, curry leaves, ginger, green chillies and saut\u00e9 until the onions are tender and become translucent.", "Now stir in the potatoes and saut\u00e9 for a couple of minutes till potatoes are cooked.Once done gradually stir in the flattened rice mixture into the onion and potato mixture.Sprinkle about 3 tablespoons of water and gently stir to combine all the ingredients.", "Turn the heat to low, cover the pan with a lid and let it simmer for 4-5 minutes.", "You will notice the flattened rice has fluffed up a little.Once the poha is done turn off heat and stir in the freshly squeezed lemon juice, steamed peas, roasted peanuts and chopped coriander leaves.", "Let the aloo poha sit covered for another minute.Serve the Aloo/Batata Poha hot sprinkled with pomegranate and a hot cup of chai made with\u00a0chai ka masala\u00a0or with\u00a0Beet Latte Recipe."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breakfast_Tiffins/Indian_Aloo_Batata_Poha_with_Pomegranates_Recipe_Archanas_Kitchen-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1101.Indian_Aloo_Batata_Poha_with_Pomegranates_Recipe_Archanas_Kitchen-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gujarati Kadhi Recipe - Sweet And Spicy Gujarati Kadhi', 'gujarati-kadhi-recipe-sweet-and-spicy-gujarati-kadhi', 'Gujarati Kadhi is a yogurt based sweet and spicy curry that is simple yet irresistible; it gets the sweetness from jaggery, the spice from cinnamon and the heat from green chillies and lends itself to a pure comfort meal.', '["1 cup Curd (Dahi / Yogurt)", "2 tablespoons Gram flour (besan)", "1/4 teaspoon Turmeric powder (Haldi) , optional", "1 tablespoon Jaggery , crushed", "Salt , to taste", "Ingredients for seasoning", "1/4 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1 inch Cinnamon Stick (Dalchini)", "1 teaspoon Ginger , grated", "2 Green Chillies , slit", "1 tablespoon Ghee", "1 sprig Curry leaves , torn", "1 tablespoon Coriander (Dhania) Leaves , chopped", "2 tablespoons Green peas (Matar) , steamed (optional)"]'::jsonb, ARRAY['curd', 'dahi / yogurt', 's gram flour', 'besan', 'turmeric powder', 'haldi', 'jaggery', 'salt', 'ingredients for seasoning', 'cumin seeds', 'jeera', 'mustard seeds', 'rai/ kadugu', 'cinnamon stick', 'dalchini', 'ginger', 'reen chillies', 'ghee', 'curry leaves', 'coriander', 'dhania', 's green peas', 'matar']::text[], '["To begin making the Gujarati Kadhi Recipe, we will first combine all the yogurt, besan, ginger, green chilli and jaggery along with 2-1/2 cups of water together in a bowl and whisk until smooth and there are no lumps.Place the Gujarati kadhi mixture in a saucepan and heat until the kadhi begins to boil.Keep whisking the Kadhi as it continues to boil, as this makes it smooth and creamy, thus giving it a perfect texture.Once the kadhi has come together into a smooth and creamy mixture while it was boiling, turn the heat to low, and simmer to kadhi while we prepare the seasoning mixture.", "Keep simmering for 5 to 10 minutes.Simmer for at least 5 minutes before you can add the seasoning mixture.", "This ensures that the raw smells go away and we get creamy and delicious Gujarati Kadhi.Heat ghee in a sauce pan on medium heat; add the mustard seeds and cumin seeds and allow them to crackle.", "Stir in the curry leaves, cinnamon, green chillies and ginger.Gradually, add the seasoning mixture to the above Gujarati Kadhi and allow the mixture to come to a boil.Turn off heat and stir in the freshly chopped coriander leaves into the Kadhi and the optionally steamed green peas and serve hot.Serve the Gujarati Kadhi along with\u00a0Khichdi\u00a0and\u00a0Aloo Shaak\u00a0together known as Khichdi Kadhi and\u00a0Batata nu Shaak Recipe."]'::jsonb, 35, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2020/Gujarati_Kadhi_Recipe_8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1102.Gujarati_Kadhi_Recipe_8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Aratikaya Vepudu Recipe - Raw Banana Dry Sabzi', 'andhra-style-aratikaya-vepudu-recipe-raw-banana-dry-sabzi', 'Aratikaya Vepudu is a Andhra Style Raw Banana Dry Sabzi. It is a simple recipe but tastes amazing as such or when paired with rice and dal/rasam. Its spicy, little crispy yet soft from inside. It is a perfect sabzi to pack in your lunch box too.', '["3 Raw Banana", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Rasam Powder", "2 tablespoon Sesame powder , roasted", "Salt , to taste", "To temper", "Oil , as required", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "3 cloves Garlic", "Curry leaves , few"]'::jsonb, ARRAY['salt', 'mustard seeds', 'red chilli powder', 'cloves garlic', 'sesame powder', 'curry leaves', 'white urad dal (split)', 'rasam powder', 'turmeric powder', 'banana', 'sunflower oil']::text[], '["To begin making the Andhra Style Aratikaya Vepudu Recipe, wash and peel the raw bananas and chop it into thin slices.", "Keep the chopped slices in a bowl filled with water until its ready to use.", "This will prevent from it turning back.Drain the water.", "To the raw banana slices add salt, turmeric powder, red chilli powder and rasam powder.", "Toss it and mix it well such that the masala gets coated well to the slices.Heat oil in a heavy bottomed pan, add mustard seeds and urad dal.", "When the mustard seeds splutter, add garlic and curry leaves.", "Saute till the garlic is done.", "Later, add the coated raw banana pieces to the pan and toss them gently.", "Keep the flame on low and stir in between.", "When the raw banana is cooked sprinkle the roasted sesame powder.Toss gently such that it gets coated well.", "Add 1-2 teaspoon of oil and let the raw banana pieces get well fried on low flame and gets crisp.", "Once done, turn off the heat, check the taste and seasonings and adjust according.", "Serve Andhra Style Aratikaya Vepudu along with\u00a0Mixed Vegetable Sambar,\u00a0Steamed Rice\u00a0and\u00a0Elai Vadam\u00a0for a weekday meal."]'::jsonb, 30, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/Andhra_Style_Aratikaya_Vepudu_Raw_Banana_Dry_Sabzi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1103.Andhra_Style_Aratikaya_Vepudu_Raw_Banana_Dry_Sabzi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ragi Rava Idli Recipe - Steamed High Protein Finger Millet Idli', 'ragi-rava-idli-recipe-steamed-high-protein-finger-millet-idli', 'The Ragi Rava Idli Recipe is a healthy preparation of the traditional Rava Idli that is made from Ragi Flour and Sooji.', '["1 cup Ragi Flour (Finger Millet/ Nagli)", "1 cup Sooji (Semolina/ Rava)", "1 cup Curd (Dahi / Yogurt)", "1 inch Ginger", "1 teaspoon Enos Fruit Salt", "1 teaspoon Sesame (Gingelly) Oil", "Seasoning for ildi", "1/2 teaspoon Sesame (Gingelly) Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves , finely chopped"]'::jsonb, ARRAY['ragi flour', 'finger millet/ nagli', 'sooji', 'semolina/ rava', 'curd', 'dahi / yogurt', 'ginger', 'enos fruit salt', 'sesame', 'gingelly', 'seasoning for ildi', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'curry leaves']::text[], '["To begin making the Ragi Rava Idli Recipe, into a mixing bowl, combine the ragi flour, sooji, yogurt, enos fruit salt, oil and salt into a large mixing bowl.", "Add a little water at a time to make a thick batter (approximately 1-1/2 cups).", "Allow the mixture to rest for 10 to 15 minutes.", "The mixture will thicken as it rests.While it is resting, make the tadka.", "Add oil into a preheated pan over medium heat.", "Add mustard seeds and urad dal and allow it to crackle and the dal to turn golden brown and crisp.Once the dal is brown and crisp, add the chopped curry leaves, ginger and green chillies and saute for a few seconds and turn off the heat.", "Allow the seasoning to cool.Add it to the idli batter once the resting period is over.Grease the idli mold with a little oil.", "Spoon the ragi batter into the molds.", "Ensure you only half fill.", "Place inside a steamed filled with water and steam on high heat for about 10 minutes until done.When you insert a knife inside, it should come out clean.", "Allow the idli to rest for 3 to 4 minutes before removing it from the pan.Dip a spoon with water and slide the idli out of the mold & serve.", "Serve the\u00a0Ragi Rava Idli Recipe\u00a0along with with\u00a0Tomato Chutney\u00a0and\u00a0Idli Milagai Podi\u00a0for a\u00a0high protein south Indian breakfast\u00a0and a\u00a0Indian diabetic breakfast or a snack."]'::jsonb, 45, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breakfast_Tiffins/Ragi_Rava_Idli_Recipe_With_tomato_chutney_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1104.Ragi_Rava_Idli_Recipe_With_tomato_chutney_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sweet & Spicy Stuffed Paneer In Kofta Curry Recipe', 'sweet-spicy-stuffed-paneer-in-kofta-curry-recipe', 'Stuffed Paneer In Kofta Curry Recipe is a unique way of preparing and presenting your paneer dish. In this recipe, paneer is  stuffed with dry fruits and spices which is placed in rich and creamy gravy.', '["200 grams Paneer (Homemade Cottage Cheese) , cut into 1-inch cubes", "2 Green Chilli , finely chopped", "1 teaspoon Ginger , finely chopped", "1 tablespoon Sultana Raisins", "6 Cashew nuts , finely chopped", "6 Whole Almonds (Badam) , finely chopped", "6 Pistachios , finely chopped", "1/4 teaspoon Turmeric powder (Haldi)", "2 teaspoons Gram flour (besan)", "Salt , to taste", "1/4 teaspoon Cardamom Powder (Elaichi)", "1 teaspoon Oil", "2 Bay leaf (tej patta)", "2-3 Cardamom (Elaichi) Pods/Seeds", "1 Cinnamon Stick (Dalchini)", "2-3 Cloves (Laung)", "1 Mace (Javitri)", "1 Star anise", "1 cup Homemade tomato puree", "1 inch Ginger", "3 cloves Garlic", "1 Onion , roughly chopped", "2 teaspoons Coriander Powder (Dhania)", "1/2 teaspoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "10 Cashew nuts , soaked and grind to a smooth paste", "2 tablespoons Curd (Dahi / Yogurt)", "Salt , to taste", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "1 tablespoon Honey", "1/2 cup Fresh cream"]'::jsonb, ARRAY['tomato', 'pistachios', 'cloves garlic', 'onion', 'cardamom powder (elaichi)', 'turmeric powder', 'sunflower oil', 'paneer cubes', 'salt', 'green chilli', 'cardamom (elaichi) podsseeds', 'raisins', 'mace (javitri)', 'star anise', 'red chilli powder', 'curd', 'kasuri methi (dried fenugreek leaves)', 'cashew nuts', 'ginger', 'bay leaf (tej patta)', 'gram flour (besan)', 'badam (almond)', 'cinnamon stick (dalchini)', 'coriander powder', 'cloves (laung)']::text[], '["To begin making Stuffed Paneer In Kofta Curry Recipe, we will begin with the stuffing for the panner.", "Scoop out or cut out little paneer from the center of each cube.", "You can use a melon scooper or with a small spoon.", "Transfer the scooped out paneer to a bowl, crumble / grate and set aside.Heat oil in a heavy bottomed pan.", "Add finely chopped green chillies and ginger, saut\u00e9 until the ginger is fragrant.Add raisins and chopped nuts, saut\u00e9 another 30 seconds.", "Add this mixture to crumbled paneer along with, turmeric powder, besan, salt and cardamom powder.", "Mix well to come.", "Adjust the salt according to taste.Stuff this paneer and nut mixture in scooped out paneer cubes and press firmly.", "Heat a teaspoon of oil in a pan over medium heat.", "Add the stuffed paneer pieces and pan fry the paneer cubes until lightly golden on both sides.", "Once done remove from the pan and keep aside.", "To begin making the kofta curry, grind the onion, ginger and garlic to a smooth paste.", "Keep aside.Grind the cashewnuts along with a little water and make a smooth paste.", "Keep aside.", "Heat oil in a pan over medium heat;\u00a0 add the whole spices and saute it for a few seconds until you can smell the aromas coming through.", "Add the ginger garlic and onion paste and saute for about a minute until the raw smell goes away.At this stage, add the turmeric powder, coriander powder, and red chilli powder.", "Adding the condiments to the onion ginger garlic paste helps further reduce the raw smell.", "Saute for a few seconds and then add the tomato puree, cashewnut puree, salt to taste and the fresh cream.", "Add a little water to adjust the consistency of the kofta gravy.", "Simmer this kofta curry for 3 to 4 minutes until the flavors combine well.", "Once done, turn off the heat, stir in the kasuri methi and check the salt and spices.", "Adjust to suit your taste.Transfer the kofta curry to a serving bowl and when you are ready to serve, place the stuffed paneer in the curry and serve warm.", "Serve your Stuffed Paneer Baskets with\u00a0Punjabi Dal Tadka,\u00a0Mixed Vegetable Pulao (Pilaf),\u00a0Butter Garlic Naan,\u00a0Kela Anar Raita\u00a0for a perfect weekend dinner with family and friends."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Sadaf_Abbasi/stuffed_paneer_curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1105.stuffed_paneer_curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Jaipuri Aloo Pyaz Ki Sabzi Recipe Using Preethi Electric Pressure Cooker', 'jaipuri-aloo-pyaz-ki-sabzi-recipe-using-preethi-electric-pressure-cooker', 'Jaipuri Aloo Pyaz Ki Sabzi Recipe is a semi dry sabzi made from baby potatoes and pearl onions in a masaledar tomato based gravy which gives it a tangy and spicy flavour. Jaipuri Aloo Pyaz Ki Sabzi is a traditional recipe from the state of Rajasthan and is usually made during festivals and for feasts.', '["2 cups Baby Potatoes , boiled & peeled", "1 cup Pearl onions (Sambar Onions)", "6 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "2 Green Chillies , slit", "1 Bay leaf (tej patta) , torn", "1/2 cup Homemade tomato puree", "1/4 cup Curd (Dahi / Yogurt)", "1/2 teaspoon Turmeric powder (Haldi)", "1 1/2 teaspoon Kashmiri Red Chilli Powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "Salt , to taste", "Coriander (Dhania) Leaves , handful,finely chopped", "1-1/2 tablespoons Mustard oil , for cooking"]'::jsonb, ARRAY['s baby potatoes', 'pearl onions', 'sambar onions', 's garlic', 'ginger', 'reen chillies', 'bay leaf', 'tej patta', 'homemade tomato puree', 'curd', 'dahi / yogurt', 'turmeric powder', 'haldi', 'kashmiri red chilli powder', 'coriander powder', 'dhania', 'garam masala powder', 'salt', 'coriander', 's mustard oil']::text[], '["To begin making the Jaipuri Aloo Pyaz Ki Sabzi, preheat the pan of the Electric pressure cooker by turning on the saute mode.", "To choose the Saute mode in the pressure cooker press the Menu Option and keep pressing the plus button till you reach P-15 which is the Saute Mode.Allow the pan to preheat for about 4 minutes.", "Once done add the mustard oil and allow the oil to get hot.Once the oil is hot add the bay leaf, garlic, ginger, green chillies, baby onions and saute the onions until lightly brown.", "After the onions have turn slightly brown add the baby potatoes and roast the potatoes for 3 to 4 minutes.", "Once done add the tomato puree, curd, turmeric powder, chili powder, coriander powder, garam masala and salt to taste.", "Stir well to combine and saute for another 2 to 3 minutes.", "Cover the pressure cooker and move\u00a0the Pressure Valve in the \"pressure position\".", "Press keep warm on the electric pressure cooker, then press menu button.", "Keep pressing the plus sign button till you reach P-12 which is the gravy mode.", "The timer would run for 15 minutes.", "After the time is up and the pressure has released naturally from the Electric pressure cooker open the pressure cooker and stir in some chopped coriander leaves.", "Transfer the\u00a0Jaipuri Aloo Pyaz Ki Sabzi into a serving bowl and serve hot.", "Serve the Jaipuri Aloo Pyaz Ki Sabzi along with\u00a0Tawa Paratha\u00a0and\u00a0Panchmel Dalfor a delicious Sunday lunch."]'::jsonb, 55, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Jaipuri_Aloo_Pyaz_Sabzi_Video_Recipe_10_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1106.Jaipuri_Aloo_Pyaz_Sabzi_Video_Recipe_10_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tomato Onion Cucumber Raita Recipe', 'tomato-onion-cucumber-raita-recipe', 'The Tomato Onion Cucumber Raita is a cooling, healthy and delicious yogurt salad that makes a perfect accompaniment to all flavoured rice and parathas. The addition of green chillies and cumin powder in the tomato onion raita gives it a zing to the palate. You can garnish the raita with some coriander or mint leaves if you like.', '["2 cups Hung Curd (Greek Yogurt) , whisked", "1 Cucumber , finely chopped", "1 Tomatoes , finely chopped", "1 Onion , finely chopped", "2 Green Chilli , finely chopped", "1/2 teaspoon Cumin powder (Jeera)", "Salt , to taste"]'::jsonb, ARRAY['s hung curd', 'greek yogurt', 'cucumber', 'tomatoes', 'onion', 'reen chilli', 'cumin powder', 'jeera', 'salt']::text[], '["To begin making the Tomato Onion Cucumber Raita Recipe, first get all the vegetables chopped and ready.Whisk the yogurt well along with salt and cumin powder and add all the chopped vegetables like the cucumber, tomatoes, onions and green chillies to it and give it stir.Transfer the Tomato Onion Cucumber Raita to a serving bowl.Serve the Tomato Onion Cucumber Raita\u00a0chilled along with\u00a0Vegetable Hyderabadi Biryani\u00a0or a\u00a0Cabbage Paneer Paratha Recipe\u00a0or pulav."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Tomato_Onion_Cucumber_Raita_Video_Recipe_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1107.Tomato_Onion_Cucumber_Raita_Video_Recipe_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('पोट्टू कडलई चटनी रेसिपी - Roasted Chickpea Chutney Recipe', 'roasted-chickpea-chutney-recipe', 'पोट्टू कडलई चटनी रेसिपी एक सरल चटनी है जिसे दक्षिण भारत के हर घर में बनाया जाता है. आप इस चटनी को इडली, डोसा, उत्तपम, पनियारम या अपने खाने के साथ साइड डिश के जैसे परोस सकते है.', '["\u091a\u091f\u0928\u0940 \u0915\u0947 \u0932\u093f\u090f", "1 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947", "1/4 \u0915\u092a \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e", "1/4 \u0915\u092a \u0930\u094b\u0938\u094d\u091f\u0947\u0921 \u091a\u0928\u093e \u0926\u093e\u0932", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u0947\u0938\u094d\u091f", "\u0936\u0915\u094d\u0915\u0930 , \u091a\u0941\u091f\u0915\u0940 \u092d\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "\u0939\u0940\u0902\u0917 , \u091a\u0941\u091f\u0915\u0940 \u092d\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0938\u095e\u0947\u0926 \u0909\u0930\u0926 \u0926\u093e\u0932", "2 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a"]'::jsonb, ARRAY['चटनी के लिए', 'कप नारियल', 'कप हरा धनिया', 'कप रोस्टेड चना दाल', 'हरी मिर्च', 'बड़ा चम्मच इमली का पेस्ट', 'शक्कर', 'नमक', 'तड़के के लिए', 'बड़ा चम्मच तेल', 'छोटा चम्मच राइ', 'हींग', 'छोटा चम्मच सफ़ेद उरद दाल', 'सुखी लाल मिर्च']::text[], '["\u092a\u094b\u091f\u094d\u091f\u0942 \u0915\u0921\u0932\u0908 \u091a\u091f\u0928\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0928\u093e\u0930\u093f\u092f\u0932, \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e, \u0930\u094b\u0938\u094d\u091f\u0947\u0921 \u0917\u094d\u0930\u093e\u092e \u0926\u093e\u0932, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u0947\u0938\u094d\u091f, \u0936\u0915\u094d\u0915\u0930, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092a\u0940\u0938 \u0932\u0947. \u0907\u0938\u0947 \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0928\u093f\u0915\u093e\u0932 \u0932\u0947.\u0905\u092c \u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f, \u090f\u0915 \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u0939\u0940\u0902\u0917 \u0921\u093e\u0932\u0947 \u0914\u0930 10 \u0938\u0947 20\u00a0\u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0909\u0930\u0926 \u0926\u093e\u0932, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 15 \u0938\u0947 20\u00a0\u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0907\u0938 \u0924\u095c\u0915\u0947 \u0915\u094b \u091a\u091f\u0928\u0940 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092a\u094b\u091f\u094d\u091f\u0942 \u0915\u0921\u0932\u0908 \u091a\u091f\u0928\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u0918\u0940 \u0930\u094b\u0938\u094d\u091f \u0921\u094b\u0938\u093e \u0914\u0930 \u095e\u093f\u0932\u094d\u091f\u0930 \u0915\u0949\u095e\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0938\u0941\u092c\u0939 \u0915\u0947 \u0928\u093e\u0936\u094d\u0924\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 20, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuri_Aggarwal/Kadale_Chutney__Fried_Gram_Chutney.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1108.Kadale_Chutney__Fried_Gram_Chutney.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gurellu Chutney Podi Recipe', 'gurellu-chutney-podi-recipe', 'Uchellu or Gurellu Chutney Podi/Karale or Khurasni Chutney powder/Kala Jeera Seeds powder, one of a family of dry chutneys that are very popular in North Karnataka and Maharashtrian homes. A scoop of this flavourful chutney can liven up even the simplest of meals. Its tasty, spicy and full of flavours.', '["1 cup Kala jeera", "1/4 cup Raw Peanuts (Moongphali)", "8 cloves Garlic , peeled", "8 Dry Red Chilli", "1 teaspoon Red Chilli powder", "10 Curry leaves", "Tamarind , lemon size", "1 teaspoon Oil"]'::jsonb, ARRAY['sunflower oil', 'red chilli powder', 'cloves garlic', 'dry red chilli', 'curry leaves', 'peanuts (moongphali)', 'tamarind lemon', 'kala jeera']::text[], '["To begin making the Gurellu Chutney Podi recipe, dry roast peanuts in a kadai or microwave, till the skin peels off or brown spots appear on them.", "Keep it aside.In a frying pan/kadai, dry roast kala jeera seeds (uchellu) on a low flame till it crackles.", "Keep it aside .Roast garlic cloves in the kadai such that its raw smell goes.", "Keep aside.Add a teaspoon of oil to the frying pan.", "Keep the flame on low and roast red chillies and tamarind.Mid way, add curry leaves, and continue to roast till red chillies, tamarind and curry leaves have turned crisp.", "Transfer to a plate .When everything has cooled to room temperature, transfer everything to a mixer jar, add some salt and grind to a medium coarse powder.", "Don\u2019t make it too smooth.", "Kala Jeera seeds chutney powder is ready.", "Store it in an air tight container.", "If handled properly can store for months together.Serve Gurellu Chutney Podi along with\u00a0Steamed Rice\u00a0and\u00a0Mixed Vegetable Sambar\u00a0for a weekday meal."]'::jsonb, 30, 'North Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha-Kalluraya/GURELLU_CHUTNEY_PUDI__NIGER_SEEDS_CHUTNEY_POWDER_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1109.GURELLU_CHUTNEY_PUDI__NIGER_SEEDS_CHUTNEY_POWDER_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Uchellu Chutney Recipe', 'uchellu-chutney-recipe', 'Uchellu Chutney Recipe made of Kala Jeera Seeds is a popular chutney accompaniment made in North Karnataka regions. Uchellu Seeds are a black thistle seed variety known for its distinct flavour and smell. This chutney is popularly made along with jowar roti, akki rotti, kadubu or chapatis. It is a great accompaniment for breakfast or tea time.', '["3 tablespoons Kala jeera", "1/4 cup Fresh coconut , grated", "2 to 3 Dry Red Chillies", "2 to 3 cloves Garlic", "1/4 cup Coriander (Dhania) Leaves , chopped", "pinch Sugar", "Salt , to taste", "1 teaspoon Sesame (Gingelly) Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "5 to 6 Curry leaves", "2 Dry Red Chillies"]'::jsonb, ARRAY['salt', 'coriander (dhania) leaves', 'coconut', 'mustard seeds', 'sesame (gingelly) oil', 'cloves garlic', 'curry leaves', 'sugar', 'dry red chillies', 'kala jeera']::text[], '["To begin making the Uchellu Chutney Recipe, first dry roast the Uchellu (kala jeera seeds) in a pan on a medium-low heat for a minute.", "Continuously toss them to avoid them from burning.Set the pan aside to cool for a while before using in the chutney.Next, all the ingredients for the chutney into a blender and blend till smooth, with just a dash of water.", "The chutney should be well ground, but with texture and thickness.", "You are not looking for a runny chutney here.Transfer the chutney from the grinder jar into a bowl.Place a Tadka Ladle on a low heat.", "Add oil into it for tempering.", "Allow the oil to warm, and then add mustard seeds to crackle.Next, add curry leaves and red chillies and let it crisp up and sputter.", "Pour the tempering over the chutney and serve the Uchellu Chutney along with\u00a0jowar roti, akki rotti, kadubu or chapatis."]'::jsonb, 20, 'North Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuri_Aggarwal/Huchellu_Chutney.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1110.Huchellu_Chutney.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Crispy and Spicy Chilli Chicken Recipe - Indian Style', 'crispy-and-spicy-chilli-chicken-recipe-indian-style', 'Crispy and Spicy Chilli Chicken Recipe is a wonderful twist to regular chilli chicken recipe. Made with Indian spices and a generous topping of fried onions and curry leaves', '["1 kg Chicken", "Salt , to taste", "1 tablespoon Turmeric powder (Haldi)", "4 tablespoons Coriander (Dhania) Leaves , chopped", "5 Green Chillies , chopped, adjust to taste", "2 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "2 tablespoon Cumin seeds (Jeera)", "1 Garlic", "2-1/2 inch Ginger , grated", "1 Onion , sliced", "15 Curry leaves", "1 cup Curd (Dahi / Yogurt)", "4 tablespoons Corn flour", "1 tablespoon All Purpose Flour (Maida)", "1 Egg white", "Oil , to deep fry"]'::jsonb, ARRAY['salt', 'ginger', 'corn flour', 'coriander (dhania) leaves', 'curry leaves', 'curd', 'eggs', 'cinnamon stick (dalchini)', 'chicken', 'cumin seeds (jeera)', 'garlic', 'onion', 'cloves (laung)', 'flour (maida)', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making Crispy and Spicy Chilli Chicken Recipe, Clean chicken and chop them to bite sized pieces.and slice the onions as well.In a kadai, heat about 2 teaspoons oil and cumin seeds and wait for a few seconds till they sizzle.", "Immediately add ginger, garlic, green chillies, cinnamon sticks, and cloves to roast well till the chillies brown a bit.Once it is done, in a mixer, add the roasted masalas and coriander leaves into it and grind them into fine thick paste.", "You can add a bit of water to make a paste.Keep this paste aside for later use.In a large mixing bowl, add chicken pieces and put in salt, curd/yogurt into it.", "Add the ground thick masala paste, turmeric powder, corn flour, maida, egg white and stir nicely until the chicken gets coated evenly with all the ingredients.Keep this chicken mixture to marinate for about 4 hours in the refrigerator.Once the chicken is marinated for 4 hours, heat enough oil to deep fry, in a deep frying pan.Once the oil is hot enough, drop the chicken pieces one by one into the deep frying pan on a low flame to allow them to crisp up.Now once the chicken pieces turn to golden brown colour, take them off from the pan onto a kitchen towel.", "Fry all the chicken in batches until they are crisp and golden brown.Once all the chicken is fried, in the same hot oil, deep fry the onion slices and curry leaves till crisp, on a medium high heat.While serving, serve crispy fried chicken and top it with some fried onions and curry leaves.Serve Crispy and Spicy Chilli Chicken Recipe as a side dish with the main meal of\u00a0steamed rice\u00a0and\u00a0Milagu Rasam (Village Style Pepper Rasam) Recipe\u00a0for dinner with friends and family."]'::jsonb, 25, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/thelifeinspire-gmail.com/Crispy_and_spicy_chilly_chicken.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1111.Crispy_and_spicy_chilly_chicken.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ragi Kuzhi Paniyaram Recipe with Ragi Dosa Batter', 'ragi-kuzhi-paniyaram-recipe-with-ragi-dosa-batter', 'Healthy Ragi Kuzhi Paniyaram Recipe is a very traditional South Indian breakfast dish, that breaks the monotony of idli and dosa.', '["2 cups Ragi Dosa Battter", "2 tablespoons Fresh coconut , grated", "1/4 cup Carrots (Gajjar) , grated, (or chopped spinach, finely minced cabbage) - optional", "1 Onion , finely chopped", "1 Green Chilli , finely chopped (adjust spice)", "1 sprig Curry leaves , finely chopped", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "Salt , to taste", "Oil , to drizzle"]'::jsonb, ARRAY['s ragi dosa battter', 's fresh coconut', 'carrots', 'gajjar', 'onion', 'reen chilli', 'curry leaves', 'mustard seeds', 'rai/ kadugu', 'salt', 'oil']::text[], '["To begin making the Healthy Ragi Kuzhi Paniyaram Recipe, in a small pan heat the oil, add the mustard seeds and curry leaves.", "Allow it to crackle.", "Add the chopped onions and saute until onions are tender.Combine all the ingredients- fresh coconut, grated carrots, green chillies, curry leaves including the prepared onion mixture into the dosa batter.Grease the paniyaram pan by adding\u00a0half a teaspoon of oil into each of the cavities of the kuzhi paniyaram pan.", "Spoon the ragi dosa\u00a0batter into the cavities of the pan.", "Place the pan on medium heat and cover with a lid.After\u00a0a 3 to 4\u00a0minutes\u00a0of steaming, you will notice the tops of the paniyaram cooked and steamed.At this point, turn over each\u00a0paniyaram\u00a0and allow it to cook the other side.", "This time around don''t cover with a lid.", "Allow it to cook on medium low heat until the bottom is browned and crisp.Once done, remove and arrange on serving trays.", "Proceed the same way with the remaining Kuzhi\u00a0Paniyaram batter.", "Serve\u00a0The Healthy Ragi Kuzhi Paniyaram Recipe with\u00a0Tomato Onion Chutney | Thakkali Vengayam Chutney\u00a0and\u00a0Adrak Chai Recipe\u00a0for a wholesome breakfast or pack into a kids school lunch box or even serve as an after school snack.Because the paniyaram is made from ragi, it makes this dish a diabetic friendly recipe that you can serve as a\u00a0diabetic snack\u00a0or a\u00a0diabetic breakfast."]'::jsonb, 45, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breakfast_Tiffins/Ragi_Batter_Kuzhipaniyaram_Recipe-6.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1112.Ragi_Batter_Kuzhipaniyaram_Recipe-6.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer Stuffed Mushroom Masala Recipe', 'paneer-stuffed-mushroom-masala-recipe', 'Paneer Stuffed Mushroom Masala Recipe is a lip smacking gravy dish with paneer and mushrooms as the star ingredients. Mushrooms are stuffed with crumbled paneer and dunked in a spicy tomato gravy. This dish can be served with both naans as well as jeera rice.', '["400 grams Button mushrooms , washed and cleaned", "Salt , to taste", "1 tablespoon Oil", "100 grams Paneer (Homemade Cottage Cheese) , crumbled", "Salt , to taste", "1 teaspoon Black pepper powder", "1 teaspoon Garam masala powder", "1 teaspoon Cumin powder (Jeera)", "1/3 cup Onions , finely chopped", "2 sprig Mint Leaves (Pudina) , finely chopped", "1 teaspoon Whole Black Peppercorns", "4 Dry Red Chillies", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Coriander (Dhania) Seeds", "1 Cardamom (Elaichi) Pods/Seeds", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 Star anise", "1 tablespoon Oil", "1/2 cup Milk", "1 cup Homemade tomato puree", "6 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "Water , as required", "Salt , to taste", "1/4 teaspoon Turmeric powder (Haldi)", "1 sprig Coriander (Dhania) Leaves , finely chopped to garnish"]'::jsonb, ARRAY['tomato', 'cumin powder (jeera)', 'black peppercorns', 'cloves garlic', 'onion', 'cumin seeds (jeera)', 'black pepper powder', 'turmeric powder', 'sunflower oil', 'salt', 'cardamom (elaichi) podsseeds', 'dry red chillies', 'coriander seeds', 'star anise', 'garam masala powder', 'mint leaves (pudina)', 'water', 'button mushrooms', 'ginger', 'paneer', 'cinnamon stick', 'milk', 'coriander (dhania) leaves', 'cloves (laung)']::text[], '["To begin making the Paneer Stuffed Mushroom Masala Recipe we will first make the filling for the stuffed mushrooms."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breakfast_Tiffins/Paneer_Stuffed_Mushrooms_in_Makhani_Gravy_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1113.Paneer_Stuffed_Mushrooms_in_Makhani_Gravy_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mushroom Masala Cheese Omelette Recipe', 'mushroom-masala-cheese-omelette-recipe', 'Mushroom Masala Cheese Omelette Recipe is a wholesome and high protein omelette that is packed with taste from mushrooms, green chillies and coriander. The addition of cheese adds to the creaminess and fluffiness.', '["2 Whole Eggs", "10 Button mushrooms , roughly chopped", "1/2 Onion , finely chopped", "1 Green Chilli , finely chopped", "1/2 Tomato , finely chopped", "4 Black olives , finely chopped", "1 tablespoon Cheese , grated", "Coriander (Dhania) Leaves , a small bunch chopped", "Salt and Pepper , to taste", "1 teaspoon Oil , for cooking"]'::jsonb, ARRAY['tomato', 'cheese', 'coriander (dhania)', 'salt', 'green chilli', 'onion', 'black olives', 'pepper', 'button mushrooms', 'eggs', 'sunflower oil']::text[], '["To begin making Mushroom Masala Omelette Recipe, first prep all the ingredients and keep them ready.In a mixing bowl, break the eggs and whisk them up well along with salt, pepper, olives, cheese and tomatoes.", "Keep this aside.Heat oil in an omelette pan over medium heat; add the mushrooms, onions and green chillies and saute until the onions and mushrooms are slightly roasted.", "Once roasted, add the egg omelette cheese mixture into the roasted onion and mushrooms.Swirl the pan to spread the omelette mixture and gently combine the onions and mushrooms and spread it around.Keep the heat on low and cook the omelette until you notice the top is getting steamed and cooked.", "You can also optionally cover the pan and cook the omelette faster.Once the top is cooked, fold the omelette into half and cook for another few minutes is required and turn off the heat.", "You can also optionally flip the omelette and cook it on both sides.Serve the Mushroom Masala Omelette along with a Toast, fruits and a cup of\u00a0Masala Chai\u00a0or\u00a0Filter Coffee."]'::jsonb, 20, 'Continental', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/admin/Mushroom_Masala_Cheese_Omelette_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1114.Mushroom_Masala_Cheese_Omelette_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Foxtail Millet Upma Recipe', 'foxtail-millet-upma-recipe', 'Foxtail Millet Upma Recipe is a wholesome breakfast or dinner dish that can be made with just a few ingredients. With a little bit of planning by having vegetables chopped the previous night, preparing this dish in the morning for the family gives me a sense of satisfaction.', '["1 teaspoon Sesame (Gingelly) Oil", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "2 sprig Curry leaves , finely chopped", "1 Green Chilli", "1 Dry Red Chilli", "1/2 cup Onion , finely chopped", "1 inch Ginger , finely chopped", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 cup Carrot (Gajjar) , finely chopped", "1/4 cup Green beans , finely chopped", "1 cup Foxtail Millet", "1 Lemon , salt to taste", "2 tablespoons Coriander (Dhania) Leaves , juice from one lemon", "1 tablespoon Ghee"]'::jsonb, ARRAY['sesame', 'gingelly', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'curry leaves', 'reen chilli', 'dry red chilli', 'onion', 'ginger', 'turmeric powder', 'haldi', 'carrot', 'gajjar', 'green beans', 'foxtail millet', 'lemon', 's coriander', 'dhania', 'ghee']::text[], '["To begin making the Foxtail Millet Upma, heat oil in a pressure cooker over medium heat; add mustard seeds and split urad dal and allow it to crackle.", "Allow the urad dal to turn golden brown and crisp.Once the dal is golden brown, add the green chilli and red chilli and saute for a few seconds.Add the onion, ginger and saute until the onions soften.", "Once the onion softens, add the curry leaves, turmeric powder, beans, carrots, foxtail millet, salt and 2-1/2\u00a0 cups of water.Cover the pressure cooker and pressure cook the millet upma for 5 to 6 whistles and simmer for 5 minutes and turn off the heat.", "Allow the pressure to release naturallyOnce the pressure releases, give it a gentle stir.", "Squeeze in the juice from one lemon and stir in the chopped coriander leaves.", "Serve\u00a0Foxtail Millet Upma Recipe\u00a0along with\u00a0Tomato Onion Chutney Recipe\u00a0or\u00a0coconut chutney\u00a0and\u00a0 South Indian Filter Coffee \u00a0for a wholesome breakfast."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Foxtail_Millet_Upma_Recipe_video_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1115.Foxtail_Millet_Upma_Recipe_video_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Nawabi Kofta Curry Recipe', 'nawabi-kofta-curry-recipe', 'The Nawabi Kofta Curry Recipe is dish from the royal kitchens. Koftas made using potatoes that are stuffed with paneer and dry fruits and simmered in spicy tomato cream gravy, iCurry to makes an absolute delight to your taste buds.', '["Ingredients for stuffed aloo kofta", "4 Potatoes (Aloo) , boiled and peeled", "1 teaspoon Black pepper powder", "250 grams Paneer (Homemade Cottage Cheese) , crumbled", "2 tablespoons Cashew nuts , chopped", "2 tablespoons Sultana Raisins , chopped", "2 Green Chillies , finely chopped", "2 sprig Coriander (Dhania) Leaves , chopped", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Garam masala powder", "Salt , to taste", "Ingredients for the kofta curry gravy", "2 cups Homemade tomato puree", "2 tablespoons Ghee", "2 Onion , chopped", "5 cloves Garlic", "1 inch Ginger", "Ingredients for dry spices", "1 teaspoon Fennel seeds (Saunf)", "1 teaspoon Coriander (Dhania) Seeds", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "2 Cardamom (Elaichi) Pods/Seeds", "Other Ingredients", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Kashmiri Red Chilli Powder", "1/4 cup Fresh cream", "Salt , to taste", "2 sprig Coriander (Dhania) Leaves , chopped to garnish"]'::jsonb, ARRAY['tomato', 'cumin powder (jeera)', 'kashmiri red chilli powder', 'cloves garlic', 'coriander (dhania) seeds', 'onion', 'black pepper powder', 'turmeric powder', 'green chillies', 'salt', 'cardamom (elaichi) podsseeds', 'raisins', 'garam masala powder', 'cashew nuts', 'ginger', 'ghee', 'paneer', 'fennel seeds (saunf)', 'coriander (dhania) leaves', 'cinnamon stick (dalchini)', 'potato (aloo)', 'cloves (laung)']::text[], '["To begin making the Nawabi Kofta Curry Recipe,\u00a0we will first make the kofta for the curry.In a large bowl, combine the mashed potatoes, along with the salt and pepper powder.", "Mix well to make a smooth mixture.", "Grease palms with oil divide them into 6-8 equal portions shaped into balls.To make the filling of the nawabi koftas, in another bowl, combine the crumbled paneer, cashew nuts, raisins, green chillies, salt, cumin powder, garam masala powder and coriander leaves.", "Mix well to combine them, grease palms with oil divide them into\u00a0 6-8 equal portions shaped into balls.Next grease your fingers and palms with oil.", "Take one portion of the potato mixture and flatten it on the palm of your hand.", "Place the paneer - dry fruit filling in the center.Then bring the edges of the flattened potato towards the center to cover the filling forming a stuffed aloo kofta.", "Proceed the similar way to make the rest of the koftas.Preheat a paniyaram pan, with a few drops of oil in each of the cavities on medium high flame.Once the oil is hot, gradually lower the koftas into each of the cavities, flip and cook until golden brown in colour.", "Drain them on an absorbent kitchen towel and set aside.\u00a0*To make the Nawabi Kofta Curry RecipeIn a small skillet, dry roast the fennel seeds, coriander seeds, cloves, cinnamon and cardamom for about 3-4 minutes on medium low flame or until the aroma of the spices wafts in the air.", "Turn off the flame, allow it to cool and transfer the spices into a mixer jar and grind the spices into a coarse powder.", "In a mixer jar, combine the onions, garlic, and ginger, grind to a smooth paste.", "Transfer to a bowl and set aside.Heat ghee in a heavy bottomed pan; add the freshly ground paste and saut\u00e9 on medium heat for about 4-6 minutes.", "Add in the freshly ground spice mixture to this and stir until you get the aroma from the spices.Add the tomato puree, turmeric powder, chilli powder, sugar and simmer for about 5 minutes until the tomato is bubbling and has combined well into the spicy forming a delicious aromatic Nawabi Kofta Curry gravy.Add in the fresh cream and a little water if required and simmer for a few more minutes.Serve the\u00a0Nawabi Kofta Curry Recipe\u00a0along with\u00a0Dal Makhani,\u00a0Tomato Onion Tadka Raita,\u00a0Butter Naan\u00a0and\u00a0Vegetable Pulav\u00a0for a delicious weekend meal."]'::jsonb, 75, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Nawabi_Kofta_Curry_Recipe_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1116.Nawabi_Kofta_Curry_Recipe_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aamras Ki Kadhi Recipe - Mango Kadhi Recipe', 'aamras-ki-kadhi-recipe-mango-kadhi-recipe', 'Aamras Ki Kadhi is a traditional spicy and sweet Gujarati recipe, a classical preparation of sweet and sour mango juice combined together with few selected ingredients. Perfect for those summer afternoon lunch or serve with rice or roti for lunch pack for any hot day in a year.', '["1 cup Aamras , (mango puree)", "1/4 cup Curd (Dahi / Yogurt)", "2 tablespoon Gram flour (besan)", "1/4 teaspoon Turmeric powder (Haldi)", "3 cups Water", "2 Dry Red Chilli", "1/4 teaspoon Asafoetida (hing)", "1/4 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Red Chilli powder", "1 inch Ginger , finely chopped", "1 sprig Curry leaves", "2 teaspoon Ghee", "Salt , to taste"]'::jsonb, ARRAY['salt', 'ginger', 'aamras (mango puree)', 'asafoetida (hing)', 'ghee', 'red chilli powder', 'water', 'gram flour (besan)', 'curd', 'dry red chilli', 'curry leaves', 'cumin seeds (jeera)', 'turmeric powder']::text[], '["To begin making the Aamras Ki Kadhi recipe, first whip up the aamras, curd, besan, turmeric powder and water in a medium bowl to a fine paste with no lumps.Pour the Aamras mixture into a saucepan, add the salt and whisk continuously until the aamras kadhi begins to thicken.", "It is important to keep whisking it until the kadhi thickens, to prevent lump formation.Bring the Aamras Kadhi into a roaring bowl for a couple of minutes.", "After that, turn the heat to low and simmer for a good 10 minutes, so all the flavors come together.Heat ghee in a tadka pan over medium heat; add cumin seeds, dry red chilli and curry leaves.", "Allow the mustard seeds to crackle.", "Once it crackles, add the chopped ginger red chilli powder, asafoetida and saute for a few seconds.Pour this tadka over the Aamras Kadhi and give it a quick stir.Check the salt to taste and adjust accordingly.", "Once done, turn off the heat and transfer the Aamras Kadhi into a serving bowl and serve hot.Serve\u00a0Aamras Ki Kadhi along with\u00a0Aloo Na Shaak,\u00a0Methi Thepla\u00a0and\u00a0Steamed Rice\u00a0for a comforting weekday lunch or dinner."]'::jsonb, 20, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/ruby_pathak-yahoo.com/Aamras_Ki_Kadhi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1117.Aamras_Ki_Kadhi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Style Tomato Vermicelli Upma Recipe', 'chettinad-style-tomato-vermicelli-upma-recipe', 'Chettinad Style Tomato Vermicelli is a spicy south indian style semiya upma that can be made for a special sunday breakfast. The Tomato Vermicelli is packed with flavors from the tomatoes along with the spices, making it rich and delicious.', '["1 cup Semiya (Vermicelli) , roasted", "1 Pearl onions (Sambar Onions) , finely chopped", "4 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "3 Tomatoes , roughly chopped", "1/4 cup Mint Leaves (Pudina) , finely chopped", "1 teaspoon Fennel seeds (Saunf) , coarsely pounded", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Whole Black Peppercorns , coarsely pounded", "1 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "1 sprig Curry leaves", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 tablespoon Lemon juice", "Oil , as required", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'mustard seeds', 'fennel seeds (saunf)', 'red chilli powder', 'cloves garlic', 'black peppercorns', 'pearl onion (sambar onion)', 'curry leaves', 'semiya (vermicelli)', 'cinnamon stick (dalchini)', 'lemon', 'mint leaves (pudina)', 'turmeric powder', 'cloves (laung)', 'sunflower oil']::text[], '["To begin making the Chettinad Style Tomato Vermicelli Recipe, heat a pan with cooking\u00a0oil on medium heat, add the mustard seeds, cinnamon stick, cloves, curry leaves and let it splutter.Stir in the onions, ginger and garlic and saute for a couple of minutes.", "Once the onions soften, add the tomatoes and saute for a few seconds.", "Add the fennel seeds, black pepper corns, turmeric powder, red chilli powder and cook until it all combined together.", "Stir in the mint leaves, semiya, salt and 1 1/2 cups of water.", "Cover the pan and allow the\u00a0Chettinad Style Tomato Vermicelli to cook on low to medium heat until all the water is absorbed and the semiya upma is cooked.", "Once done, turn off the heat, stir in the lemon juice and gently mix everything together.Serve the Chettinad Style Tomato Vermicelli along\u00a0Tomato Onion Chutney,\u00a0\u00a0Coconut Coriander Chutney\u00a0and Sliced bananas.", "End the south indian breakfast along with a hot cup of\u00a0Espresso coffee."]'::jsonb, 25, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Breakfast_Plate_Chettinad_Style_Tomato_Vermicelli_Upma_Banana_Dhaniya_Pudina_Chutney-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1118.Breakfast_Plate_Chettinad_Style_Tomato_Vermicelli_Upma_Banana_Dhaniya_Pudina_Chutney-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Himachali Bhey Recipe - Stir Fried Lotus Stem', 'himachali-bhey-recipe-stir-fried-lotus-stem', 'Himachali Bhey Recipe (Stir Fried Lotus Stem Recipe) is a recipe that hails from Himachal Pradesh. It literally means “In the Lap of Himalayas”. The food in Himachal Pradesh is simple home cooking. There are not much of spices used to make this recipe, making it very simple to make.', '["2 Lotus Stem , cut into lengthwise", "1 inch Ginger , chopped", "4 cloves Garlic , chopped", "1 Onion , sliced", "1 tablespoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "1 tablespoon Coriander Powder (Dhania)", "3 tablespoon Gram flour (besan)", "Oil"]'::jsonb, ARRAY['ginger', 'coriander powder', 'red chilli powder', 'cloves garlic', 'gram flour (besan)', 'onion', 'lotus stem', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Himachali Bhey Recipe, we will boil the lotus stem with water and salt for about 15 minutes.Once the lotus stems are cooked drain the water out and wash it over cold water to stop the cooking process.Heat a pan with oil, add ginger, garlic and onions and saute them till the onions turn translucent.", "Add the spice powders turmeric powder, red chilli powder and salt.", "Give it a toss.Add the cooked lotus stem, besan flour and give a quick mix.", "Check for salt and spices and turn off the heat.", "Remove\u00a0Himachali Bhey into a serving bowl and serve.Serve the\u00a0Himachali Bhey Recipe\u00a0along with along with\u00a0Tawa Paratha\u00a0and\u00a0Gujarati Dal\u00a0for your comforting lunch or dinner meal."]'::jsonb, 50, 'Himachal', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Himachali_Bhey_Recipe_Stir_Fried_Lotus_Stem_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1119.Himachali_Bhey_Recipe_Stir_Fried_Lotus_Stem_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Beetroot Sambar Recipe - Tangy Beetroot Lentil Curry', 'beetroot-sambar-recipe-tangy-beetroot-lentil-curry', 'Beetroot Sambar Recipe is a very traditional South Indian lentil curry made from beetroots that is cooked with tangy tamarind and flavored with homemade sambar powder.', '["1 Beetroot , peeled and diced", "10 Pearl onions (Sambar Onions) , quartered", "1 cup Arhar dal (Split Toor Dal)", "1-1/2 cups Tamarind Water", "1 tablespoon Sambar Powder", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Ingredients for Seasoning", "1 teaspoon Sesame (Gingelly) Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 pinch SSP Asafoetida (Hing)", "2 sprig Curry leaves , torn", "1 Dry Red Chilli", "4 sprig Coriander (Dhania) Leaves , chopped for garnishing"]'::jsonb, ARRAY['beetroot', 'pearl onions', 'sambar onions', 'arhar dal', 'split toor dal', 's tamarind water', 'sambar powder', 'turmeric powder', 'haldi', 'salt', 'ingredients for seasoning', 'sesame', 'gingelly', 'mustard seeds', 'rai/ kadugu', 'ssp asafoetida', 'hing', 'curry leaves', 'dry red chilli', 'coriander', 'dhania']::text[], '["To begin making the Beetroot Sambar recipe, we will first cook the toor dal with 2 cups of water, for 2 whistles and turn the heat to low.", "Simmer for 3 to 4 minutes and turn off the heat.", "Allow the pressure to release naturally.See video recipe of how to cook lentils using pressure cooker.If you find that the cooked dal is too thick and mushy, add water to it and whisk it till it becomes a thick pouring consistency.Next, cook the beetroot along with the tamarind water, onions, salt and sambar powder in a pressure cooker, until it becomes soft and tender (about 3 whistles).", "Turn off the heat after three whistles and allow the pressure to release naturally.", "Add the cooked beetroot sambar along with the toor dal into a large saucepan.", "Place it on medium heat and check the salt and spice levels.", "Adjust by adding more of the salt or sambar powder.", "Bring the beetroot sambar to a brisk boil.While the beetroot sambar is boiling, we will now get the seasoning ready.Heat oil in a tadka pan; add the mustard seeds and the red chillies, stir for a few seconds until the mustard crackles and the red chilli is roasted.", "Finally, add the curry leaves and asafoetida powder and turn off the heat.", "Pour this seasoning to the simmering beetroot sambar, add in the coriander leaves and stir.", "Turn off the heat and transfer the beetroot sambar to a serving bowl.Serve\u00a0Beetroot Sambar along with\u00a0Chow Chow Thoran,\u00a0Steamed Rice\u00a0and\u00a0Elai Vadam\u00a0for a weekday meal."]'::jsonb, 55, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Beetroot_Sambar_Recipe_7_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1120.Beetroot_Sambar_Recipe_7_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Crunchy Carrot Peanut Raita Recipe - Gajar Moongphali Raita', 'crunchy-carrot-peanut-raita-recipe-gajar-moongphali-raita', 'Crunchy Carrot Peanut Raita Recipe is a refreshing raita recipe where we have used the grated carrots and flavoured the raita with the peanuts, red chilli mixture giving it a nutty taste.', '["1-1/2 cups Carrot (Gajjar) , grated", "2 cups Curd (Dahi / Yogurt)", "1/4 cup Raw Peanuts (Moongphali)", "3 Dry Red Chillies", "1/2 teaspoon Kashmiri Red Chilli Powder", "1 Green Chilli , chopped", "Salt , to taste"]'::jsonb, ARRAY['salt', 'kashmiri red chilli powder', 'green chilli', 'carrot', 'curd', 'dry red chillies', 'peanuts (moongphali)']::text[], '["To begin making Crunchy Carrot Peanut Raita Recipe, we first need to prepare the peanut and red chilli spice mix.Heat a small pan on medium heat, add the peanuts and red chillies and roast until the peanuts turn golden.In a big bowl, add in the yogurt, whisk until you attain the creamy consistency.", "To this add in the grated carrots, prepared peanut and red chilli spice mixture, chilli powder and season with salt and mix well.If the Crunchy Carrot Peanut Raita is too thick, add a little water and adjust the consistency to your liking.", "Refrigerate the Crunchy Carrot Peanut Raita\u00a0 for an hour and garnish with chopped green chilies.", "Serve the\u00a0Carrot Peanut Raita\u00a0as an accompaniment to\u00a0Paneer Pulao With Green Peas Recipe,\u00a0Aloo Palak Sabzi\u00a0and\u00a0Phulka\u00a0for a complete\u00a0weeknight dinner."]'::jsonb, 15, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Affiliate-Articles/Crunchy_Carrot_Peanut_Raita_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1121.Crunchy_Carrot_Peanut_Raita_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Delicious Breakfast Anda Ghotala Recipe With Butter Pav', 'delicious-breakfast-anda-ghotala-recipe-with-butter-pav', 'Anda Ghotala Recipe is a lip smacking dish made with eggs cooked three ways with  prominent flavours of pav bhaji that is used to make it. They eggs added to the anda ghotala are scrambled eggs, boiled eggs and fried eggs.', '["2 tablespoons Butter (Salted)", "1/2 teaspoon Cumin seeds (Jeera)", "6 cloves Garlic , finely chopped", "1 Green Chilli , finely chopped", "2 Onions , finely chopped", "Salt , to taste", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "2 Tomatoes , finely chopped", "2 tablespoons Pav bhaji masala", "1 teaspoon Cumin powder (Jeera)", "4 Boiled egg , cut into medium sized pieces", "1 teaspoon Butter (Salted)", "4 Whole Eggs", "Salt , to sprinkle", "Pav bhaji masala , to sprinkle", "Coriander (Dhania) Leaves , finely chopped", "Pav bhaji masala , to sprinkle", "Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['tomato', 'salt', 'pav bhaji masala', 'cumin powder (jeera)', 'boiled eggs', 'green chilli', 'coriander (dhania) leaves', 'red chilli powder', 'cloves garlic', 'onion', 'cumin seeds (jeera)', 'coriander powder', 'eggs', 'turmeric powder', 'butter']::text[], '["To begin making the Anda Ghotala Recipe, melt butter in a preheated pan.To the melted butter, add the cumin seeds and once they begin to sizzle, add in the garlic and saute for a few seconds until their aroma wafts in the air.", "Next, into the pan, add the onions along with the green chillies.", "Cook the onions until they turn into a lovely golden colour.", "This will take about 4-6 minutes on medium heat, stirring occasionally.", "Once the onions have reached the desired golden colour, add the\u00a0salt,\u00a0turmeric powder, red chilli powder, coriander powder and cumin powder.", "Stir in the chopped tomatoes, sprinkle some water and cover and allow the tomatoes to become mushy.", "Cook the tomatoes for about 3-4 minutes, then open the lid and using a potato masher, mash the onion-tomato mixture well.", "To further season this mixture, add the pav bhaji masala and mix well.", "Break three eggs, in a bowl and gradually add them to the onion- tomato base on medium high heat.", "Mix vigorously to scramble the eggs in the onion tomato masala.Once the eggs are well scrambled, add the chopped boiled eggs and mix until well combined.", "Check the salt and adjust to taste accordingly.Turn off the heat and transfer the\u00a0Anda Ghotala into a serving platter and set aside."]'::jsonb, 45, 'North Indian', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Anda_Gotala_Recipe_14_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1122.Anda_Gotala_Recipe_14_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Palak (Spinach) Puri Recipe', 'palak-spinach-puri-recipe', 'Palak Puri Recipe are not regular puri recipe, they are attractive and delicious made up of whole wheat and palak or spinach. These puris turn out to be green on adding spinach pure. Spinach is rich in iron and supplies enough nutrients.Consumption of spinach regularly protects us from certain types of cancers, promotes bone and brain health, maintains blood pressure and since it is rich in vitamin A it also protects eye health.', '["1 cup Whole Wheat Flour", "20 Spinach Leaves (Palak) , chopped", "1/4 inch Ginger , peeled and chopped", "1 Green Chilli , chopped", "1 teaspoon Cumin powder (Jeera)", "1 tablespoon Water", "2 tablespoon Oil , more to deep fry"]'::jsonb, ARRAY['wheat flour', 'ginger', 'cumin powder (jeera)', 'green chilli', 'water', 'spinach leaves (palak)', 'sunflower oil']::text[], '["To begin with the Palak Puri Recipe, first chop spinach, ginger and green chilies and boil them together.After boiling strain the water and leave it aside for 15 minutes till the water is drained.After cooling, take the boiled contents from the strainer and add to a mixer and make a thin puree.", "Do not add water, just make a puree.Now in a mixing bowl add Vivatta whole wheat flour and the prepared pure, add some oil to the flour, cumin powder and salt.", "Mix them to together to make dough.Do not add excess water as palak will release water on its own.", "Now cover the dough with a muslin cloth and keep it aside for 30 minutes.After 30 minutes again, mould the dough and make small marble sized balls.Make small balls out of the dough and dust the rolling table with whole wheat flour and flatten the puris with the rolling pin.", "See to that you make small thick size round out of the dough.As you have rolled all the dough now, heat a Kadai\u00a0and add oil.", "When oil gets heated, gently add a flattened puri.Using a frying spoon or slotted spoon gently press the puri, put some hot oil on top and move in a circular way.You will notice that the puri gets puffed and rises up.", "At this point, turn it to the other side and fry till it turns golden brown.", "Do not keep the puri in oil for more than 2 Minutes else it will become brittle.Drain it on kitchen towel.Continue the deep frying process for all the other flattened puris.Serve Palak Puris with\u00a0Lahori Aloo\u00a0and any raita of your choice."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Raksha_Kamat/Palak_Puris.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1123.Palak_Puris.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Besan Ka Sheera Recipe (Natural Cold Remedy)', 'besan-ka-sheera-recipe-natural-cold-remedy', 'Besan Ka Sheera is an effective natural home remedy for cold and cough. Besan or chickpea flour is slow roasted until aromatic and then simmered with milk, turmeric and freshly cracked black peppercorns. Turmeric and Black pepper have a natural anti-inflammatory and antibacterial properties aiding in giving relief from cold. It is a popular home remedy used in Northern part of India. The drink also induces good sleep when ill. The Besan Ka Sheera is served hot and best had before the bedtime.', '["2 cups Milk", "1/4 teaspoon Whole Black Peppercorns , freshly powdered", "1/8 teaspoon Turmeric powder (Haldi)", "3 teaspoons Jaggery , (or sugar)", "1 tablespoon Ghee", "1 tablespoon Pistachios , or almonds for garnish", "1 pinch Saffron strands"]'::jsonb, ARRAY['s milk', 'whole black peppercorns', 'turmeric powder', 'haldi', 's jaggery', 'ghee', 'pistachios', 'saffron strands']::text[], '["To begin making\u00a0Besan Ka Sheera (Natural Cold Remedy), heat ghee in a sauce pan, add the besan and slow roast it until it turns golden and aromatic.Slowly add in the milk and whisk well to avoid the lumps.Add the turmeric, cracked pepper, jaggery (or sugar if using) and mix well.Add the saffron and whisking the mix for 5 minutes until it turns a little thick.", "Switch off the heat, mix in the nuts.Serve the hot\u00a0Besan Ka Sheera (Natural Cold Remedy) at bedtime to get immediate relief from cold and cough."]'::jsonb, 12, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Besan_Ka_Sheera_Natural_Cold_Remedy.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1124.Besan_Ka_Sheera_Natural_Cold_Remedy.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ujju Rotti Recipe (Indian Rice Flat Bread)', 'ujju-rotti-recipe-indian-rice-flat-bread', 'Ujju Rotti Recipe (Indian Rice Flat Bread) Bilavaliga in Telugu is a total whole Rice flour dish, wherein the flour is pre-cooked and rolled out just like rotis. Our very own gluten-free flatbread. This Dish is so versatile since it is consumed as breakfast, lunch or dinner, depending on the side dish. It is great to mop up any flavourful curry like Badanekaayi Gojju, Peas curry, Malai Kofta or any pappu (dal).', '["1 cup Rice flour", "1-1/2 cups Water", "Salt , to taste", "1 Oil"]'::jsonb, ARRAY['salt', 'rice flour', 'water', 'sunflower oil']::text[], '["To prepare Ujju Rotti Recipe (Indian Rice Flat Bread), in a medium sized vessel Bring the water to a boil with salt and oil.Lower the flame and pour the rice flour into the boiling water using a cup or a tumbler, pour it in the centre as much as possible.Let it get cooked on a low to medium flame for 8-10 minutes uncovered.Turn off the flame, take a wooden stick or a wooden spatula, run it under a tap to wet it and then mix the flour and water mixture vigorously until combined.", "This step must be done quickly to avoid lumps.", "This takes about 2 minutes.", "Cover for a couple of minutes and let it cool until you can handle the mixture.Drop it on an oiled surface and knead well for about 5-7 minutes.", "Roll the mixture into a cylinder and divide them equally.", "This should give you about 4 equal sized balls.Kneading should happen after wetting hands since the dough will stick to hands.", "Keep them covered at all times.", "Knead each ball for 15-20 seconds and roll it out just like regular rotis using rice flour.", "Just make sure you do it slow and steady since the edges might crack.Roll out all the balls and stack the rotti on top of another on a plate first and then start roasting them.", "Use a little rice flour to avoid getting sticked to one another.Heat a tawa and cook the Ujju Rotti just like a chapatti by smearing oil /ghee on both sides and serve with Badanekaayi Gojju, Peas curry, Malai Kofta or any pappu (dal)."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Gauravi_Vinay/Ujju_rotti_recipe_indian_rice_flat_bread.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1125.Ujju_rotti_recipe_indian_rice_flat_bread.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('मशरुम करी - Mushroom Curry (Recipe In Hindi)', 'mushroom-curry-recipe-in-hindi', 'मशरूम करी एक स्वादिष्ट पकवान है जिसे हम दोपहर के भोजन के लिए बना सकते हैं।मशरुम को प्याज-टमाटर ग्रेवी में पकाया जाता है और उसे फुल्के के साथ परोसा जाता है। काजू इस सब्ज़ी को मलाईदार और स्वस्थ बनाता है।', '["200 \u0917\u094d\u0930\u093e\u092e \u092c\u091f\u0928 \u092e\u0936\u0930\u0941\u092e , \u0915\u093e\u091f \u0932\u0947", "2 \u092a\u094d\u092f\u093e\u091c , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "2 \u091f\u092e\u093e\u091f\u0930 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "2 \u0932\u0949\u0928\u094d\u0917 \u0932\u0939\u0938\u0941\u0928 , \u0915\u0938 \u0932\u0947", "15 \u0915\u093e\u091c\u0942", "1/2 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u0915\u0938 \u0932\u0947", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u0924\u0947\u0932", "\u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "\u092a\u093e\u0928\u0940 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['ग्राम बटन मशरुम', 'प्याज', 'टमाटर', 'लॉन्ग लहसुन', 'काजू', 'इंच अदरक', 'छोटा चमच्च लाल मिर्च पाउडर', 'छोटा चमच्च गरम मसाला पाउडर', 'बड़ा चमच्च तेल', 'हरा धनिया', 'पानी', 'नमक']::text[], '["\u092e\u0936\u0930\u0941\u092e \u0915\u0930\u0940 \u0915\u094b \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0915\u093e\u091c\u0942 \u0915\u094b \u0917\u0930\u092e \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 5 \u0938\u0947 10 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092d\u093f\u0917\u094b \u0926\u0947. \u0915\u093e\u091c\u0942 \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947 \u0914\u0930 \u0907\u0938\u0947 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u094d\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u092e\u0936\u0930\u0941\u092e \u0921\u093e\u0932\u0947 \u0914\u0930 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u092e\u0936\u0930\u0941\u092e \u0915\u094b \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u0909\u0938 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0925\u094b\u095c\u093e \u0914\u0930 \u0924\u0947\u0932 \u0921\u093e\u0932\u0947\u0964 \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u0928\u0915\u0947 \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u0928\u0947 \u0926\u0947. \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0905\u0926\u0930\u0915,\u00a0\u0932\u0939\u0938\u0941\u0928 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e\u090f\u0964 2 \u092e\u093f\u0928\u091f \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930 \u0914\u0930 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947\u0964 \u091f\u092e\u093e\u091f\u0930 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e\u090f\u0964 \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u0907\u0938\u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0915\u093e\u091c\u0942 \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e\u090f\u0964 \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u0928\u0947 \u0926\u0947.\u00a0\u0907\u0938\u092e\u0947\u0902 \u092a\u0915\u0947 \u0939\u0941\u090f \u092e\u0936\u0930\u0941\u092e \u0914\u0930 \u0917\u0930\u094d\u092e \u092e\u0938\u093e\u0932\u093e \u0921\u093e\u0932\u0947\u0964 1 \u0938\u0947 2 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u0928\u0947 \u0926\u0947. \u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u0947 \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902 \u0914\u0930\u00a0\u0917\u0930\u092e\u093e \u0917\u0930\u092e \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092e\u0936\u0930\u0942\u092e \u0915\u0930\u0940 \u0915\u094b\u00a0\u092c\u0942\u0902\u0926\u0940 \u0930\u093e\u092f\u0924\u093e, \u0924\u0935\u093e \u092a\u0930\u093e\u0920\u093e \u0914\u0930 \u0915\u091a\u0941\u092e\u094d\u092c\u0930 \u0938\u0932\u093e\u0926 \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Asha_Venugopal_/Mushroom_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1126.Mushroom_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bisi Bele Bath Recipe - A Spicy Mixed Vegetable Sambar Rice', 'bisi-bele-bath-recipe-a-spicy-mixed-vegetable-sambar-rice', 'Bisi Bele Bath also known as the spicy mixed vegetable sambar rice is a traditional south indian dish made from cooked rice and lentils, mashed along with a spicy tamarind and vegetable curry/sambar that is simply delicious.', '["Ingredients for the Bisi Bele Bhaat Spice Powder", "1 tablespoon Chana dal (Bengal Gram Dal)", "1 tablespoon White Urad Dal (Split)", "1 inch Cinnamon Stick (Dalchini)", "3 Cloves (Laung)", "3 Cardamom (Elaichi) Pods/Seeds", "3 to 4 Dry Red Chillies", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 tablespoon Poppy seeds", "2 tablespoons Coriander (Dhania) Seeds", "1/4 cup Fresh coconut , grated", "1 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Asafoetida (hing)", "Ingredients needed to make the spicy vegetable tamarind sambar/curry", "7 to 8 Pearl onions (Sambar Onions) , peeled", "1 Green Bell Pepper (Capsicum) , diced", "2 Carrots (Gajjar) , diced", "1/4 cup Green peas (Matar)", "1/2 cup Green beans (French Beans) , diced", "1 Potato (Aloo) , peeled and diced", "1 Drumstick , cut into 1 inch pieces", "2 Tomatoes , roughly chopped", "2 cups Tamarind Water", "2 teaspoons Jaggery", "Salt , to taste", "Other Main Ingredients", "1 cup Rice", "1 cup Arhar dal (Split Toor Dal)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Ingredients For Seasoning", "1 tablespoon Ghee", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 or 2 Dry Red Chilli", "8 to 10 Curry leaves", "Ingredients for Garnishing", "Coriander (Dhania) Leaves , a small bunch", "Boondi , fried"]'::jsonb, ARRAY['tomato', 'asafoetida (hing)', 'jaggery', 'carrot', 'white urad dal (split)', 'coriander (dhania) seeds', 'cumin seeds (jeera)', 'turmeric powder', 'chana dal (bengal gram dal)', 'boondi', 'salt', 'coriander (dhania)', 'arhar dal (split toor dal)', 'cardamom (elaichi) podsseeds', 'dry red chillies', 'green beans (french beans)', 'tamarind water', 'coconut', 'rice', 'mustard seeds', 'dry red chilli', 'methi seeds (fenugreek seeds)', 'ghee', 'potato (aloo)', 'green peas (matar)', 'drumstick', 'curry leaves', 'pearl onion (sambar onion)', 'cinnamon stick (dalchini)', 'poppy seeds', 'green bell pepper (capsicum)', 'cloves (laung)']::text[], '["To begin the preparation of Bisi Bele Bath, first make the spice powder.To make the spice powder, heat a small pan on medium heat; add in the chana dal, urad dal.", "Stir continuously until they lightly brown and you get a roasted aroma.Once the lentils are roasted, we will add in the cinnamon stick, cloves, cardamom pods, dry red chillies, fenugreek seeds and the coriander seeds.", "Turn the heat to low and roast well until the chillies begin to brown and you get a roasted aroma from the spices.Next will add in the poppy seeds and coconut.", "Continue to roast along with other ingredients for about a 30 to 40 seconds until the coconut loses its moisture.", "Once it is roasted we will add in the turmeric powder and the asafoetida powder.", "Stir until it combines well into the other ingredients.", "Turn off the heat and allow the mixture to cool completely.Once cooled add the ingredients to a spice blender and make a fine powder of the mixture.", "Transfer the mixture to a bowl and keep aside.Next thing to do, is to make the spicy vegetable tamarind sambar.For this, in a large pressure cooker, we will add the tamarind water, jaggery, the drumsticks, pearl onions, beans, carrots, bell peppers, tomatoes, salt and finally the bisi bele bhaat spice powder.Stir all the ingredients well.", "Cover the pressure cooker, place the weight and allow the vegetables to cook until you hear at least 2 whistles and turn off the heat.", "Since the vegetables cook very quickly, we will release the pressure by running cold water over the pressure cooker.", "This process helps to bring the pressure down immediately.Open the pressure cooker and smell the aroma from the vegetable curry.", "You can transfer this to another bowl to reuse the pressure cooker for the next process.", "But since I have another pressure cooker, I will leave it aside as it is.Now lets get the main ingredients to make the Bisi Bele Bath and learn how to bring them all togetherTo the pressure cooked at in the washed rice, the washed lentils, the turmeric powder, salt and 5 cups of water.", "Cover the cooker and place the weight on the pressure cooker.", "Turn the heat to high and allow the rice to cook until you hear two whistles.After you hear the whistles, turn the heat to low and simmer for five minutes.", "After 5 minutes have passed, turn off the heat and allow the pressure to release naturally.", "Rice cooks in this resting period, hence wait for the pressure to release completely.While we are waiting for the pressure to release, Lets proceed to make the seasoning.For seasoning the Bisi Bele Bath, heat a small pan on medium heat.", "Add in a tablespoon of ghee and allow it to melt.", "Add in the mustard seeds, the cumin seeds.", "Allow it to crackle.", "Then add in the red chilli, curry leaves and roast them until the red chillies are browned lightly.", "Stir to roast the ingredients well.", "Once roasted keep this aside.Now we will get back to the rice and dal pressure cooker.", "Once the pressure is released , open the pressure cooker.", "Add in the spicy vegetable tamarind curry.", "Stir all the ingredients together until well combined and the mixture looks like a mish mash.", "At this stage add in the prepared seasoning and two more tablespoons of ghee.", "Once again give the mixture a good stir.Transfer the Bisi Bele Bath to a serving bowl.", "Sprinkle the chopped coriander leaves and the fried boondi on top.Serve this delicious Bisi Bele Bath dish from southern india along with a\u00a0tomato onion raita\u00a0for lunch or dinner.", "With just a little preparation you sure can get satisfied tummies."]'::jsonb, 75, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Bisi_Bele_Bhat_Recipe-1030.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1127.Bisi_Bele_Bhat_Recipe-1030.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Malabar Style Ney Pathiri Recipe (Fried Masala Rice Puri)', 'malabar-style-ney-pathiri-recipe-fried-masala-rice-puri', 'Malabar Style Ney Pathiri Recipe (Fried Masala Rice Puri) is a dish that is made from pathiri which is a bread that is popular in Kerala. Pathiri is made using rice flour and is then cooked on a griddle. But in this recipe, the pathiri is deep fried in oil thus the name “Ney Pathiri” in which “ney” means “oil”. The ground onion and cumin seeds are added to the rice flour dough and then rolled to form puris. The recipe uses rice flour but you can use soaked rice as well and then ground to smooth powder to make the pathiri.', '["1 1/2 cup Rice flour", "Salt , to taste", "Oil , for frying the pathiris", "To Grind", "1 Onion , chopped", "1 teaspoon Cumin seeds (Jeera)", "4 tablespoons Fresh coconut"]'::jsonb, ARRAY['salt', 'coconut', 'onion', 'cumin seeds (jeera)', 'rice flour', 'sunflower oil the pathiris']::text[], '["To begin making the Malabar Style Ney Pathiri Recipe, we will first grind the chopped onion, cumin seeds and coconut to a coarse paste and set aside.Take a sauce pan, add rice flour, salt to taste, ground onion paste and add about 1/2 cup of water and mix well till there are no lumps.Keep the rice mixture on medium heat and keep stirring until the rice is cooked and it comes together.Once the dough has thickened to form a dough.", "You can switch off the heat and take the dough out and spread it on a plate to cool down.Heat a kadai with oil to fry the puris.", "Take out a small ball of dough and roll it flat not too thin.Flatten it and roll it again to about 1 centimeter thickness.", "Fry the puri when the oil becomes hot.Keep flipping it over and fry it so that it evenly get browned on both the side.", "Take the puri out and strain it over a napkin.", "Do the rest for the remaining ingredients.Serve the Malabar Style Ney Pathiri Recipe (Fried Masala Rice Puri) along with\u00a0Kurma,\u00a0Kerala Style Egg Roast Curry\u00a0to make it a complete meal."]'::jsonb, 50, 'Malabar', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/jan-5/Neypathiri_Recipe_Rice_Flour_Puri-0841.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1128.Neypathiri_Recipe_Rice_Flour_Puri-0841.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Tamarind Gojju Recipe', 'karnataka-style-tamarind-gojju-recipe', 'Karnataka Style Tamarind Gojju Recipe is a simple and easy to make gravy that is made by simmering tamarind water with chopped tomatoes and jaggery. The water is left to boil till it thickens. Then a tempering of curry leaves and mustard seeds are poured over it to give a tadka. It is usually paired with Khichdi and the traditional karnataka style rice dish called as Huggi.', '["1 cup Tamarind Water", "1 Tomato , chopped", "1 Green Chilli , slit", "1 tablespoon Red Chilli powder", "1 inch Ginger , chopped", "Salt , to taste", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1 tablespoon Oil"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'green chilli', 'tamarind water', 'mustard seeds', 'red chilli powder', 'curry leaves', 'sunflower oil']::text[], '["We begin making the Karnataka Style Tamarind Gojju Recipe by boiling the tamarind water with the rest of the ingredients into a sauce pan\u00a0Boil until the tamarind thickens, then switch it off.", "Heat a kadai with oil and temper the mustard seeds and curry leaves.Pour this over the gojju and serve hot.", "Serve the Karnataka Style Tamarind Gojju Recipe along with Karnataka Style Huggi Recipe along with some\u00a0Gorikayi Palya Recipe."]'::jsonb, 30, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Karnataka_Style_Tamarind_Gojju_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1129.Karnataka_Style_Tamarind_Gojju_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sun Dried Raw Mango Raita Recipe-Ambula Rai', 'sun-dried-raw-mango-raita-recipe-ambula-rai', 'As we know tantalizing pickles are a tasty condiment to serve with any meal. Some people without any curry also finished their meal just with pickle. Winter is that time of the year, when most of Indian terrace is lined up with freshly filled pickle jars. We, odias make a variety of pickles too. Among them, ambula or dried mango pieces are the queen of our kitchen pantry.', '["6 Dry Green Mango (Vathal/ Ambula) , pieces", "1/2 cup Fresh coconut , grated", "1 cup Curd (Dahi / Yogurt)", "2 tablespoons Mustard seeds (Rai/ Kadugu)", "2 Green Chillies", "2 tablespoons Sugar", "1 tablespoon Mustard oil", "2 Dry Red Chillies", "2 sprig Curry leaves", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard oil', 'mustard seeds', 'coconut', 'dry green mango (vathal ambula)', 'curd', 'sugar', 'dry red chillies', 'curry leaves', 'green chillies']::text[], '["To begin making the Sun Dried Raw Mango Raita recipe, soak the dry mango pieces (ambula) in water for minimum 1-2 hours in a bowl and keep aside.Put 2 tablespoon of mustard seeds with green chilies in a blender jar and make a smooth paste.", "Add the\u00a0mustard green chilli paste to a big bowl and add curd, sugar, salt, grated coconut and mix well to combine..Next, add the soaked dry mango pieces (ambula).", "Mix well again.Now heat mustard oil in a pan.", "Add in mustard seeds, curry leaves and red chilies and allow to splutter.Once done turn of heat and pour this tempering on the dry mango mixture.", "Cover and leave for 1-2 hours so that all the flavours\u00a0 infuse well together.", "Serve Sun Dried Raw Mango Raita along with\u00a0Steamed Rice,\u00a0Kumror/Kaddu Posto\u00a0\u00a0and\u00a0Elai Vadam\u00a0for a weekday meal."]'::jsonb, 11, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/firsttimercook/Sundried_Raw_Mango_Raita__Ambula_Rai.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1130.Sundried_Raw_Mango_Raita__Ambula_Rai.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gujarati Lasaniya Batata Recipe - Garlic Potato Curry', 'gujarati-lasaniya-batata-recipe-garlic-potato-curry', 'Lasaniya Batata Recipe (Garlic Potato Curry) is a flavorful Gujarati potato curry with prominent garlic flavors. Gujarati lehsunia batata is a dry curry made with boiled baby potatoes and flavoured with garlic, but the consistency can be moderated as per one''s choice.', '["250 grams Baby Potatoes", "12 cloves Garlic , chopped", "1 tablespoon Oil", "1 teaspoon Cumin seeds (Jeera)", "3/4 cup Gram flour (besan)", "1 tablespoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "1 tablespoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 cup Curd (Dahi / Yogurt)", "Salt , to taste", "1 tablespoon Coriander (Dhania) Leaves , chopped, to garnish"]'::jsonb, ARRAY['salt', 'coriander (dhania) leaves', 'red chilli powder', 'cloves garlic', 'gram flour (besan)', 'curd', 'cumin seeds (jeera)', 'baby potatoes', 'coriander powder', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Gujarati Lasaniya Batata Recipe (Garlic Potato Curry), boil and peel the baby potatoes and keep aside.Heat oil in a heavy bottomed pan and fry till golden on medium heat.In the same wok heat 2 tablespoons of oil, add cumin seeds and wait till they crackle.", "Add chopped garlic and saut\u00e9 for a while.Now add gram flour and cook for another five minutes on a slow heat.Add coriander powder, garam masala powder, red chilli powder, turmeric powder and cook for another minute.Remove the wok from heat and then add whisked yogurt, a little water and place the wok on fire again and cook.", "When the curry starts to thicken add fried baby potatoes and mix well such that the masala coats well.", "Season with salt as needed and turn off the gas.", "Garnish with chopped coriander and serve hot.", "Serve\u00a0Gujarati Lasaniya Batata\u00a0along with\u00a0Palak Dal,\u00a0Lauki Raita\u00a0and\u00a0Phulka\u00a0for an everyday meal."]'::jsonb, 45, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/shaheen_ali/Lehsuniya__Lasaniya_Batata_Gujrati_Grlic_Potato_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1131.Lehsuniya__Lasaniya_Batata_Gujrati_Grlic_Potato_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Style Khichuri Aar Labra Recipe-Khichdi And Mixed Vegetables', 'bengali-style-khichuri-aar-labra-recipe-khichdi-and-mixed-vegetables', 'Khichuri Aar Labra Recipe is a moong dal Khichdi And Mixed Vegetables cooked in Bengali style. This has potatoes, cauliflower and peas, fragrant with ginger and bhaja masala . For the stir fried vegetables (Labra) we have added Spinach and is cooked with a medley of veggies in it as well.This is a comfort food that is handy when we live alone as it is a one pot meal.', '["150 grams Govind Bhog Rice", "200 grams Yellow Moong Dal (Split)", "1 Cauliflower (gobi) , cut to florets", "11 Potatoes (Aloo) , chopped to bite size", "1/2 cup Green peas (Matar)", "2 Dry Red Chillies", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1/4 teaspoon Kalonji (Onion Nigella Seeds)", "1/4 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Fennel seeds (Saunf)", "1 tablespoon Ginger , grated", "3 Green Chillies , slit", "2 teaspoons Turmeric powder (Haldi)", "2 teaspoons Bhaja masala", "2 teaspoons Mustard oil", "1 tablespoon Ghee", "Salt , to taste", "1/2 teaspoon Sugar , (or adjust to taste)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1/4 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Kalonji (Onion Nigella Seeds)", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Fennel seeds (Saunf)", "1 Potato (Aloo) , chopped to bite size", "1 Small Brinjal (Baingan / Eggplant) , chopped to bite size", "1 Mooli/ Mullangi (Radish) , chopped to bite size", "1 Sweet Potato , chopped to bite size", "100 gram Kaddu (Parangikai/ Pumpkin) , chopped to bite size", "100 gram White broad beans , halved", "2 Drumstick , chopped to bite size", "Spinach Leaves (Palak) , big bunch, roughly chopped", "2 Dry Red Chillies", "3 teaspoons Ginger , grated", "2 teaspoons Coriander Powder (Dhania)", "2 Green Chillies , slit", "2 teaspoons Bhaja masala", "Mustard oil , to cook", "Salt , to taste", "Sugar , to taste", "3 Bay leaves (tej patta)", "3 Dry Red Chillies", "1/4 Cumin seeds (Jeera)"]'::jsonb, ARRAY['brinjal (baingan eggsplant)', 'cumin seeds (jeera)', 'gram white broad beans', 'turmeric powder', 'green chillies', 'sweet potato', 'salt', 'spinach leaves (palak) bunch', 'mustard oil', 'dry red chillies', 'kalonji (onion nigella seeds)', 'mustard seeds', 'bhaja masala', 'gram parangikai pumpkin', 'sugar', 'methi seeds (fenugreek seeds)', 'mooli mullangi (radish)', 'cauliflower (gobi) florets', 'yellow moong dal (split)', 'ginger', 'bay leaves (tej patta)', 'ghee', 'fennel seeds (saunf)', 'potato (aloo)', 'green peas (matar)', 'drumstick', 'govind bhog rice', 'coriander powder', 'potato (aloo)']::text[], '["To begin making\u00a0Bengali Style Khichuri Aar Labra Recipe-Khichdi And Mixed Vegetables, in a kadai, dry\u00a0roast moong dal till it gives out a fragrant nutty aroma and takes on a tinge of light brown colour.", "Once fragrant, remove from flame, rinse the dal in water and keep aside.Now to make Bhaja masala, add the dry red chillies, cumin seeds and tej patta and roast on a very low heat till fragrant.", "Once done, put the roasted contents on a plate to cool a bit before dry grinding.Once the spices for bhaja masala is cooled, take them in a mixer and grind them to a fine powder.", "This bhaja masala can stay good for at least 2 weeks.", "This needs to be stored in a clean and dry airtight container."]'::jsonb, 85, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/maumita.paulghosh-gmail.com/Khichuri_aar_Labra_Khichadi_And_Mixed_Vegetables_Bengali_Style_recipe_1_edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1132.Khichuri_aar_Labra_Khichadi_And_Mixed_Vegetables_Bengali_Style_recipe_1_edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Amritsari Recipe', 'aloo-amritsari-recipe', 'Aloo Amritsari Recipe (Navratri Fasting/Vrat Recipe) is a one pot dish made with cubed potato and cooked with sauteed onion, tomato and flavoured with Indian spices. It is an authentic delicacy of Punjabi Cuisine.', '["4 Potatoes (Aloo) , cut into wedges", "1 teaspoon Ajwain (Carom seeds)", "2 Onion , sliced", "2 inch Ginger , grated", "2 cloves Garlic", "2 Tomatoes , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Kashmiri Red Chilli Powder", "4 sprig Coriander (Dhania) Leaves , finely chopped", "Salt , to tase", "Oil , for cooking"]'::jsonb, ARRAY['tomato', 'ginger', 'kashmiri red chilli powder', 'salt tase', 'ajwain (carom seeds)', 'cloves garlic', 'coriander (dhania) leaves', 'onion', 'coriander powder', 'potato (aloo)', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["We begin making the Aloo Amritsari by heating the pressure cooker with a little oil and temper the ajwain seeds till the aroma comes.Next add the onion, green Chillies, ginger and garlic and saute on low to medium heat until the onions are softened.Once the onions are softened, add the chopped tomatoes, saute until the tomatoes soften and mashed.", "At this point you can add salt as required which enhances the cooking of tomatoes.Next add the remaining ingredients including the aloo.", "Add 1/2 cup of water, salt and cover the pressure cooker.", "Cook until you hear a couple of whistles and turn off the heat.", "Allow the pressure to release naturally.Once done, open the pressure cooker and stir in the coriander leaves.You can serve it along with Ajwain Puri and\u00a0Phulka\u00a0to make it a complete meal."]'::jsonb, 45, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/sept-19/Aloo_Amritsari_Recipe_Aloo_Curry_in_a_Ajwain_Masala-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1133.Aloo_Amritsari_Recipe_Aloo_Curry_in_a_Ajwain_Masala-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Restaurant Style Phool Gobhi Masala Recipe', 'restaurant-style-phool-gobhi-masala-recipe', 'Phool Gobi or Cauliflower is one of our favourite vegetable for winter and for a spicy alternative you may always try to make like punjabi restaurant style preparation. Restaurant Style Phool Gobhi Masala Recipe is a semi dry popular vegetarian recipe that pairs well with rice and roti speaks enough for North Indian tasty cuisine.', '["12 Cauliflower (gobi) , cut to clorets", "1/2 teaspoon Turmeric powder (Haldi)", "2-1/2 tablespoons Mustard oil , (adjust as per need)", "1/2 teaspoon Cumin seeds (Jeera)", "1 Bay leaf (tej patta)", "1 teaspoon Ginger Garlic Paste", "2 teaspoons Water", "1 cup Onion , finely chopped", "1 cup Water", "1/4 teaspoon Garam masala powder", "1/4 teaspoon Kashmiri Red Chilli Powder", "1/4 cup Homemade tomato puree", "2 tablespoons Fresh cream", "1 teaspoon Ghee", "1 Green Chilli", "2 teaspoons Cashew nuts , broken", "Salt , to taste"]'::jsonb, ARRAY['cauliflower', 'gobi', 'turmeric powder', 'haldi', 's mustard oil', 'cumin seeds', 'jeera', 'bay leaf', 'tej patta', 'ginger garlic paste', 's water', 'onion', 'water', 'garam masala powder', 'kashmiri red chilli powder', 'homemade tomato puree', 's fresh cream', 'ghee', 'reen chilli', 's cashew nuts', 'salt']::text[], '["To begin making the Restaurant Style Phool Gobhi Masala Recipe, first clean the florets and toss it along with salt and turmeric powder.Heat a kadai with oil on a medium heat and fry the florets for about 5 minutes or till the raw smell vanishes.", "Take them out on to a plate.In the same kadai, add the onions, fry till translucent.", "Switch off the stove and let the onions cool down.Once it cools down, add the onion mixture in a mixer grinder and make it into a fine paste.Add bay leaf and cumin seeds in the leftover hot oil.", "Once the cumin seeds crackle, add ginger and garlic paste with 2 teaspoons water.", "Let it cook for about a minute or two.After a minute, add the fried florets, tomato puree and mix everything well.", "Immediately add\u00a0the fried onion paste, kashmiri red chilli powder and 1 cup water, cook for about 5 minutes.Turn to low flame.", "After 5 minutes, add the cream, garam masala powder and ghee.", "Check for salt seasoning.Garnish with cashews and serve.", "Serve\u00a0Restaurant Style Phool Gobhi Masala Recipe\u00a0along with\u00a0Tawa Tandoori Roti Recipe,\u00a0Mushroom Do Pyaza Recipe\u00a0and\u00a0Boondi Raita\u00a0for a dinner meal."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/ruby_pathak-yahoo.com/Restaurent_Style_Phool_Gobi_Masala.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1134.Restaurent_Style_Phool_Gobi_Masala.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kavuni Arisi Halwa Recipe (Black Rice Halwa)', 'kavuni-arisi-halwa-recipe-black-rice-halwa', 'Kavuni Arisi Halwa or Black Rice Halwa is a traditional halwa recipe prepared by constant stirring of black rice paste in coconut milk and made richer by adding ghee. This is also called as dhol dhol or dodol in Anglo Indian cuisine, which is prepared for Christmas.', '["1 cup Black Rice", "2 cups Fresh coconut , grated", "1 cup Jaggery , powdered", "1/4 cup Ghee"]'::jsonb, ARRAY['black rice', 's fresh coconut', 'jaggery', 'ghee']::text[], '["To begin making Kavuni Arisi Halwa, wash and soak black rice overnight.", "Add the soaked rice to mixer along with little water and grind into paste.", "You can also use black rice flour, if its available.", "In a separate mixer jar add grated coconut along with a little water and extract thick coconut milk from this pulp.", "Add the coconut back to the mixer and add some more water.", "Grind for a minute and now extract the thin coconut milk.", "Keep aside.Heat a heavy bottomed pan, add the powdered jaggery and thin coconut milk to it.", "Mix until jaggery dissolves.Once it starts boiling, reduce the flame and add black rice paste.", "Keep stirring until it thickens like a porridge.Once it thickens, add the thick coconut milk and cook on a medium flame stirring continuously until it starts coming together like halwa.", "Add ghee little by little and keep cooking until the ghee incorporates into the halwa and comes out leaving sides of the pan.", "The halwa becomes darker as it gets thicker.Once the halwa comes together like a whole mass, remove the pan from the flame and pour into greased plate.Allow it to cool and cut into squares.", "Serve Kavuni Arisi Halwa as a dessert after a Kerala style meal of\u00a0Kerala Style Kappa Ishtoo Recipe and\u00a0Kerala Style Whole Wheat Parotta Recipe."]'::jsonb, 30, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swathynandhini/BLACK_RICE_HALWA__KAVUNI_ARISI_HALWA__DODOL_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1135.BLACK_RICE_HALWA__KAVUNI_ARISI_HALWA__DODOL_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Avial Recipe - Onam Sadya Recipe', 'kerala-style-avial-recipe-onam-sadya-recipe', 'The Avial Recipe is a traditional dish of the Kerala Cuisine that is made with a combination of root vegetables along with ash gourd and coconut. The flavors of the Avial comes from the use of coconut oil and curry leaves that make an important addition to this dish. The recipe is healthy and quick to make and at home.', '["1 cup Vellai Poosanikai (Ash gourd/White Pumpkin) , cut lengthwise", "2 Drumstick , cut lengthwise", "2 Carrots (Gajjar) , cut lengthwise", "10 Green beans (French Beans) , cut lengthwise", "1 Raw Banana , peeled and cut lengthwise", "2 Potatoes (Aloo) , peeled and cut lengthwise", "1 cup Elephant yam (Suran/Senai/Ratalu) , peeled and cut lengthwise", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Ingredients for Coconut Gravy", "1-1/2 cups Fresh coconut , grated", "3 Green Chillies", "1 sprig Curry leaves", "1 teaspoon Cumin seeds (Jeera)", "1 tablespoons Coconut Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'green beans (french beans)', 'elephant yam (suransenairatalu)', 'green chillies', 'coconut', 'vellai poosanikai (ash gourdwhite pumpkin)', 'drumstick', 'carrot', 'curry leaves', 'cumin seeds (jeera)', 'coconut oil', 'potato (aloo)', 'turmeric powder', 'banana']::text[], '["To begin making the Kerala Style Avial Recipe, we will first steam all the vegetables along with salt.I like to cook the vegetables together in a pressure cooker.To do this, place all the cut vegetables into the pressure cooker, sprinkle some salt, add 1/4 cup of water and cover the pressure cooker.", "Place the weight on and allow the vegetables to pressure cook for about 2 two whistles.", "After two whistles, turn the heat to low and simmer for about 3 to 4 minutes and turn off the heat.Release the pressure immediately, by placing the pressure cooker under running water.", "Once the pressure is released, open the cooker.", "Transfer the steamed vegetables to a serving bowl.Our next step, we will make the Coconut Base for the Kerala Avial.", "To do this, place the coconut, green chillies, cumin seeds into the mixer.", "Add a little warm water and blend to make an almost smooth paste.Add the coconut mixture to the steamed vegetables, add a tablespoon of coconut oil, torn curry leaves and give the Kerala Avial a stir.", "Adjust the salt to suit your taste.When you are ready to serve, warm the Kerala Avial in the microwave and serve along with steamed rice and Vathal Kuzhambu."]'::jsonb, 75, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Kerala_Avial_recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1136.Kerala_Avial_recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gojju Avalakki Recipe - Puli Aval', 'gojju-avalakki-recipe-puli-aval', 'Avalakki (Poha) is a favourite ingredient in every Kannadiga household and Gojju Avalakki has a special place. Relish this easy to make and yet so very flavourful Gojju Avalakki for breakfast or even as a snack. Avalakki or Aval is also prepared during fasting time like Maha Shivarathri.', '["3 cups Poha (Flattened rice)", "2 Onions , finely diced", "1 Green Bell Pepper (Capsicum) , finely diced (optional)", "1/4 cup Tamarind Paste , thick", "3 tablespoons Jaggery , (reserve 1 tablespoon)", "2 tablespoons Sambar Powder", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoons Mustard seeds (Rai/ Kadugu)", "2 tablespoons Chana dal (Bengal Gram Dal)", "2 teaspoons White Urad Dal (Split)", "1/4 cup Roasted Peanuts (Moongphali)", "10 Curry leaves", "2 Green Chillies , slit (optional)", "Asafoetida (hing) , a pinch", "3 tablespoons Coriander (Dhania) Leaves , finely chopped", "3 tablespoons Fresh coconut , grated", "3 tablespoons Oil", "Salt , to taste"]'::jsonb, ARRAY['green chillies', 'salt', 'chana dal (bengal gram dal)', 'mustard seeds', 'poha (flattened rice)', 'asafoetida (hing)', 'coriander (dhania) leaves', 'jaggery', 'coconut', 'curry leaves', 'white urad dal (split)', 'onion', 'peanuts (moongphali)', 'tamarind paste', 'green bell pepper (capsicum)', 'turmeric powder', 'sambar powder', 'sunflower oil']::text[], '["To begin with the Gojju Avalakki Recipe, firstly combine tamarind extract, jaggery, salt, sambar powder in a mixing bowl and mix everything properly.To this, add the Avalakki and mix to coat everything well, now sprinkle some water (too much water can make it mushy) on top of the Avalakki and let it soak for 20-30 minutes and absorb the tamarind liquid.After 20 to 30 minutes, heat required oil in a wide pan.", "Add mustard seeds and let it splutter.", "Add the urad dal, chana dal, groundnuts and cook on low flame for 2 minutes stirring in between so that they get an even colour.To this add the asafoetida, green chillies, curry leaves and give it a stir.Add in the chopped onions, turmeric powder and some salt.", "This quickens the cooking process of onions, once they start to shrink, add the capsicum and give it a nice mix.", "This whole step should take about 5-6 minute on a medium flame.Add the dry tamarind powder and the reserved jaggery.", "This enhances the taste of the onions when combined with the poha. (The Avalakki is like a sponge it soaks in everything and turns bland very soon) This steps helps its stay flavourful longer.", "Now add the Avalakki into the tadka and gently mix it all around.", "Adjust salt according to your taste.", "Garnish it with coriander leaves and grated coconut.Serve\u00a0Gojju Avalakki Recipe\u00a0along with hot\u00a0Masala Chai\u00a0and\u00a0Peanut Butter Banana Sandwich\u00a0for a delicious weekday breakfast."]'::jsonb, 40, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Gauravi_Vinay/Gojju_Avalakki.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1137.Gojju_Avalakki.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Banarasi Chooda Matar/Chura Matar Recipe', 'banarasi-chooda-matar-chura-matar-recipe', 'If you are bored of making Poha the usual way, try this simple yet delectable Poha prepared in a royal way. Also known as Chura Matar, is a Banarasi twist on the usual Poha. It is a winter delicacy of the place though, when the markets are flooded with the winter produce - Green Peas/Matar. It is loaded with desi ghee, milk/cream and garam masala, making it very flavorful and very different from its Maharashtrian cousin Kanda/Batata Pohe. It is a street snack available in Banaras during winters.', '["1 cup Poha (Flattened rice)", "1/2 cup Milk", "1/2 cup Fresh cream", "1 Green Chilli , finely chopped", "3/4 cup Green peas (Matar) , shelled", "1 teaspoon Cumin seeds (Jeera)", "1 inch Ginger , grated", "1 teaspoon Garam masala powder", "1/4 teaspoon Black pepper powder", "1/2 cup Coriander (Dhania) Leaves , finely chopped", "1 teaspoon Lemon juice", "2 teaspoon Ghee , or clarified butter", "Salt , to taste"]'::jsonb, ARRAY['poha', 'flattened rice', 'milk', 'fresh cream', 'reen chilli', 'green peas', 'matar', 'cumin seeds', 'jeera', 'ginger', 'garam masala powder', 'black pepper powder', 'coriander', 'dhania', 'lemon juice', 'ghee', 'salt']::text[], '["To begin with Banarasi Chooda Matar, wash the poha in the running tap water and soak it in the mix of cream and milk for 10 minutes and keep it aside.Take a wok, pour the ghee into it and let it heat.", "Now add the cumin seeds and let it crackle.", "Add finely chopped green chilli & ginger and saute for a while, add the washed shelled green peas.", "Toss the peas and now add the garam masala and black pepper powder.", "Cover and let the peas cook.Once the peas is cooked, season with salt, add the finely chopped coriander leaves and give it a good stir.Add the soaked poha to this mix and give it a gentle stir and cover with a lid to cook for a few minutes.Finish off with the lemon juice, give one last stir and serve hot with a cup of ginger tea.", "Serve Banarasi Chooda Matar/Chura Matar with hot\u00a0masala chai\u00a0for a royal breakfast."]'::jsonb, 30, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Banarasi_Chooda_Mattar__Chura_Matar_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1138.Banarasi_Chooda_Mattar__Chura_Matar_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pasi Paruppu Kosumalli Recipe (Spiced Lentil Salad Recipe)', 'pasi-paruppu-kosumalli-recipe-spiced-lentil-salad-recipe', 'Pasi Paruppu Kosumalli Recipe (Spiced Lentil Salad Recipe) is a simple salad made using soaked moong dal lentil mixed with an assortment of cucumber, carrot, and coconut and tempered with Indian spices.', '["1/2 cup Yellow Moong Dal (Split)", "1 Cucumber , finely chopped", "1 Carrot (Gajjar) , grated", "1/4 cup Fresh coconut , grated", "2 tablespoon Lemon juice", "Salt , to taste", "1 teaspoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Green Chillies , slit", "1/2 teaspoon Asafoetida (hing)", "1 sprig Curry leaves , roughly torn", "Coriander (Dhania) Leaves , chopped, for garnish"]'::jsonb, ARRAY['salt', 'yellow moong dal (split)', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'coriander (dhania) leaves', 'carrot', 'curry leaves', 'lemon', 'cucumber', 'green chillies', 'sunflower oil']::text[], '["We begin making Pasi Parupu Kosumalli Recipe (Spiced Lentil Salad Recipe) by washing and soaking the dal for half an hour.", "Drain the water.Keep all the vegetables prepped and set it aside.Heat the skillet with oil and temper it with mustard seeds, asafoetida, green chillies, and curry leaves.", "Add it to the mixed vegetables.Drain the dal and add it to the mixture with salt to taste\u00a0and mix it thoroughly till the dal is evenly coated.Serve your fresh\u00a0Pasi Paruppu Kosumalli Recipe (Spiced Lentil Salad Recipe) during lunch or relish it as a quick snack."]'::jsonb, 45, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/sept-23/Moong_Dal_Cucumber_Salad_Pasi_Paruppu_Kosumalli_Recipe_Navratri_Gollu_Moong_Dal_Cucumber_Salad-Pasi_Paruppu_Kosumalli_Recipe__-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1139.Moong_Dal_Cucumber_Salad_Pasi_Paruppu_Kosumalli_Recipe_Navratri_Gollu_Moong_Dal_Cucumber_Salad-Pasi_Paruppu_Kosumalli_Recipe__-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sweet Potato And Bitter Gourd Kulambu Recipe', 'sweet-potato-and-bitter-gourd-kulambu-recipe', 'We love purple sweet potatoes, as they are denser in taste than the regular orange sweet potatoes. I try a lot of dishes using them and I recently wanted to try something that has tangy, sweet, spicy and bitter taste. So I made this dish “Bitter Gourd & Sweet Potato Kulambu”. Bitter Gourd, Sweet Potato & Onion are cooked in tamarind along with sambar powder & other spices, condiments from the kitchen.', '["1/2 cup Sweet Potatoes", "1/4 cup Onion , thinly sliced", "1 tablespoon Dry coconut (kopra)", "1 cup Karela (Bitter Gourd/ Pavakkai) , chopped", "1 Tamarind , lemon sized", "4 Dry Red Chillies", "Sesame (Gingelly) Oil , as required", "1 tablespoon Raw Peanuts (Moongphali)", "1 teaspoon Turmeric powder (Haldi)", "1-1/2 tablespoon Sambar Powder", "1 teaspoon Coriander Powder (Dhania)", "Salt , as needed", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 teaspoons Methi Seeds (Fenugreek Seeds)", "2 teaspoons Chana dal (Bengal Gram Dal)", "1/4 teaspoon Asafoetida (hing)", "Curry leaves , few", "Water , as required"]'::jsonb, ARRAY['salt', 'chana dal (bengal gram dal)', 'karela (bitter gourd pavakkai)', 'mustard seeds', 'asafoetida (hing)', 'sesame (gingelly) oil', 'dry coconut (kopra)', 'water', 'curry leaves', 'dry red chillies', 'onion', 'methi seeds (fenugreek seeds)', 'peanuts (moongphali)', 'coriander powder', 'turmeric powder', 'sambar powder', 'sweet potatoes', 'tamarind lemon']::text[], '["To begin making the Sweet Potato And Bitter Gourd Kulambu recipe, soak tamarind in water and squeeze the juice.Take a wok/kadai or a clay pot and add oil.", "Temper with mustard seeds, bengal gram, methi seeds, peanuts, red chilli and dry coconut.", "Add onions and fry them until translucent.", "Add sweet potato and fry until they are half cooked.At this stage add bitter gourd pieces and cook for 2 minutes.", "Add curry leaves, salt, turmeric powder, sambar powder & coriander powder.", "Mix them well.After 2 minutes, add tamarind water and cook until the mix thickens.", "Once it is done, switch off the heat.Sweet Potato Bitter Gourd Kulambu is ready to serve.", "Serve\u00a0Sweet Potato And Bitter Gourd Kulambu\u00a0along with\u00a0Steamed Rice,\u00a0Chow Chow Thoran\u00a0and\u00a0Elai Vadam\u00a0for a weekday meal."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Neeru_Srikanth/Sweet_Potato__Bitter_Guard_Kulambu.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1140.Sweet_Potato__Bitter_Guard_Kulambu.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Himachal Pahari Style Teliah Mah Recipe (Brown Horse Gram Curry)', 'himachal-pahari-style-teliah-mah-recipe-brown-horse-gram-curry', 'Himachal Pahari Style Teliah Mah Recipe (Brown Horse Gram Curry) is a simple lentil preparation that uses horse gram, it is cooked in a spicy yogurt curry. The masala used in this recipe are very simple as the pahari cuisine is all about simple cooking with whatever ingredients they have in their house. The cuisine hails from the snow Cap Mountains of himachal where cooking exotic food is very minimal. Their main dish would be a simple dal with firewood cooked rotis.', '["1/2 cup Horse Gram Dal (Kollu/ Kulith)", "1 Bay leaf (tej patta)", "1 Cardamom (Elaichi) Pods/Seeds", "1 Black cardamom (Badi Elaichi)", "1 inch Cinnamon Stick (Dalchini)", "1 teaspoon Cumin seeds (Jeera)", "1 pinch Asafoetida (hing)", "1 inch Ginger , chopped", "1 teaspoon Black pepper powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 cup Curd (Dahi / Yogurt)", "1 tablespoon Fresh cream", "Ghee , for cooking", "Salt , to taste"]'::jsonb, ARRAY['black cardamom (badi elaichi)', 'salt', 'ginger', 'cardamom (elaichi) podsseeds', 'bay leaf (tej patta)', 'asafoetida (hing)', 'ghee', 'red chilli powder', 'curd', 'cinnamon stick (dalchini)', 'cumin seeds (jeera)', 'black pepper powder', 'horse gram dal (kollu kulith)', 'coriander powder', 'turmeric powder']::text[], '["To begin making the Himachal Pahari Style Teliah Mah Recipe, we will soak the lentil for about 2 hours or overnight with water.Pressure cook the lentil with some water and salt in the pressure cooker for about 4 whistle till it is done.Heat a kadai with ghee, add all the whole spice one by one and let the aroma fill the kitchen for few seconds.Add chopped ginger and saute until it softens.", "Add in the cooked lentils along with spice powders.Give it a stir, once it start to boil, reduce the heat to medium and slowly add in the curd and whisk it continuously.Simmer the curry and add cream check for salt and serve hot.Serve the Himachal Pahari Style Teliah Mah Recipe along with\u00a0kulcha\u00a0or\u00a0phulka\u00a0and a\u00a0Carrot and Beans Thoran\u00a0along with a glass of\u00a0buttermilk."]'::jsonb, 145, 'Himachal', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Himachal_Pahari_Style_Teliah_Mah_Recipe_Brown_Horse_Gram_Curry_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1141.Himachal_Pahari_Style_Teliah_Mah_Recipe_Brown_Horse_Gram_Curry_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Special Mambazha Puliserry Recipe', 'kerala-special-mambazha-puliserry-recipe', 'Mambazha Puliserry is an unique and special dish of Kerala. This dish is specially prepared on the auspicious day of Onam. However, the best time to prepare this dish is when mangoes are in season. Whole ripe mangoes are cooked in a coconut- sour curd spicy gravy.', '["4 Mango (Ripe)", "2 Green Chillies , sliced lengthwise", "1 cup Curd (Dahi / Yogurt) , whisked", "Salt , to taste", "1 cup Fresh coconut , grated", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "2 teaspoon Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "2 Dry Red Chilli , cut into halves", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'coconut', 'mango (ripe)', 'mustard seeds', 'red chilli powder', 'dry red chilli', 'curd', 'curry leaves', 'cumin seeds (jeera)', 'coconut oil', 'methi seeds (fenugreek seeds)', 'turmeric powder', 'green chillies']::text[], '["To begin making the Kerala Special Mambazha Puliserry recipe, first heat a heavy bottomed pan with 2 cups of water.Add the mangoes, green chillies and cook covered for 10 to 15 minutes over low flame.", "You can optionally squeeze out some pulp to make a gravy.When the mangoes are simmering, prepare the masala paste by grinding coconut,\u00a0cumin seeds,\u00a0turmeric powder,\u00a0chilli powder in a mixer jar using 1/4 cup of warm water to a smooth paste.Once the mangoes are cooked, add the ground masala paste and cook the\u00a0Mambazha Puliserry over low flame for 5 to 7 minutes in the same pan.Now add the whisked curd and give the\u00a0Mambazha Puliserry a brisk boil and turn off the heat.", "Check the salt and spices and adjust accordingly.", "Heat a\u00a0tadka pan with coconut oil over medium heat; add the mustard seeds, methi seeds and allow them to crackle.", "Add the dry red chillies and the curry leaves and stir fry for a few seconds.Pour the tempering over the Mambazha Puliserry and transfer to a serving bowl and serve hot.Serve Kerala Special Mambazha Puliserry with\u00a0hot Steamed Rice\u00a0and\u00a0Elai Vadam\u00a0for a delicious weekday meal."]'::jsonb, 50, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Uma_Raghuraman/Kerala_Special_Mambazha_Puliserry__Onam_Sadya_Special.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1142.Kerala_Special_Mambazha_Puliserry__Onam_Sadya_Special.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thelivu Rasam Recipe', 'thelivu-rasam-recipe', 'Rasam is an common recipe prepared everyday in most South Indian households. \', '["1/4 cup Arhar dal (Split Toor Dal) , cooked", "18 grams Tamarind , soaked in warm water for 110 minutes", "2 Tomatoes", "2 cloves Garlic", "1 Green Chilli", "2 teaspoons Rasam Powder", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 pinch Asafoetida (hing)", "1 sprig Curry leaves", "2 sprig Coriander (Dhania) Leaves , finely chopped", "1 teaspoon Ghee", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'arhar dal (split toor dal)', 'green chilli', 'tamarind water', 'mustard seeds', 'asafoetida (hing)', 'ghee', 'cloves garlic', 'curry leaves', 'coriander (dhania) leaves', 'rasam powder']::text[], '["To begin making\u00a0Thelivu Rasam Recipe, wash and pressure cook the toor dal for 2 whistles and keep aside till the pressure releases naturally.Make a smooth paste of the tomatoes, garlic cloves and green chilli using a blender and keep aside.Heat ghee in a pan.", "Once heated, add the mustard seeds on a low heat and let them crackle.Add the asafoetida, curry leaves and let them splutter for a few seconds.Add the ground tomato paste, tamarind pulp, rasam powder and enough water to your desired consistency and bring it to a rolling boil.Now, mash the cooked dal and add it to the pan, season with salt and simmer for about 2 minutes on medium heat.Garnish with coriander leaves and switch off the heat.Serve the\u00a0Thelivu Rasam Recipe along with Steamed Rice,\u00a0Elai Vadam Recipe (A Traditional South Indian Rice Papad),\u00a0Bajri Ki Roti Recipe\u00a0and\u00a0Mulakootal (Vegetables In Coconut Gravy) Recipe\u00a0for a complete weeknight dinner."]'::jsonb, 25, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Thelivu_Rasam_reci0pe_edited_new.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1143.Thelivu_Rasam_reci0pe_edited_new.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karnataka Style Mangrasa Recipe - Raw Mango Chutney Recipe', 'karnataka-style-mangrasa-recipe-raw-mango-chutney-recipe', 'Karnataka Style Mango Rasa Recipe also known as Mangrasa is a deliciously tangy, sweet and spicy chutney made with the last of the mangoes available in market - the Gini Moothi cultivar or Totapuri Mangoes that are available almost towards the ending of Mango season.', '["2 Mango (Raw) , (half ripen Totapuri cultivar)", "1/2 cup Jaggery , grated", "1 tablespoon Red Chilli powder", "2 teaspoons Methi Seeds (Fenugreek Seeds)", "2 teaspoons Cumin seeds (Jeera)", "1/2 teaspoon Asafoetida (hing)", "1/2 cup Water , (adjust)", "1/2 cup Coconut Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mango ( ripen totapuri cultivar)', 'asafoetida (hing)', 'jaggery', 'red chilli powder', 'water', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'coconut oil']::text[], '["To begin making the Karnataka Style Mango Rasa Recipe | Mangrasa, remove the skin of mangoes and cut the mango into small thin slices.", "Keep this aside for further use.In a tadka pan,\u00a0 add fenugreek seeds and dry roast until you get nice aroma.", "Keep this aside to cool.To the same pan, add cumin saut\u00e9 well on medium heat for a minute or till fragrant.", "Switch off the heat and keep aside.Once the fenugreek and cumin seeds cool down, transfer them into a mixer jar and grind it into a fine powder.In a pan, add oil and heat for a minute on medium flame.", "Now add the ground masala powder and saut\u00e9 for a minute.", "Now add hing and fry for about 30 seconds.Next, add mango slices and cook on medium flame for 5 minutes.", "Now add grated jaggery, red chilli powder and salt to the cooked mango rasa.Add water to this mango rasa and cook for 5 minutes until the jaggery melts.Cook the Mango Rasa on medium flame for 5 more minutes until it thickens to jam type consistency.", "Switch off the flame.Cool the mango rasa or mangrasa and store in airtight container.", "This can stay good for 5-7 days under refrigeration when kept in an airtight container.Serve Karnataka Style Mango Rasa Recipe | Mangrasa along with Udupi Style Pelakai Teepee Dosa Recipe and South Indian Coconut Chutney for breakfast."]'::jsonb, 25, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pavithrahr-gmail.com/Karnataka_style_Mango_Rasa_or_Mangrasa.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1144.Karnataka_style_Mango_Rasa_or_Mangrasa.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Zucchini Paratha Recipe', 'zucchini-paratha-recipe', 'Zucchini Paratha Recipe is a healthy option of including zucchini in your breakfast. Zucchini stuffed paratha is a comforting dish to start a busy day. Make this easy zucchini paratha and serve it with instant red chilli pickle recipe.', '["1 cup Green zucchini , grated", "1 teaspoon Ajwain (Carom seeds)", "2 teaspoons Red Chilli powder", "1/4 teaspoon Amchur (Dry Mango Powder)", "1/4 teaspoon Cumin powder (Jeera)", "1/4 teaspoon Turmeric powder (Haldi)", "2-1/2 cups Whole Wheat Flour", "Water , for kneading", "Ghee , for roasting", "Salt , to taste"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'wheat flour', 'amchur (dry mango powder)', 'ajwain (carom seeds)', 'red chilli powder', 'water', 'ghee roasting', 'green zucchini', 'turmeric powder']::text[], '["To prepare Zucchini Paratha Recipe, squeeze out the water from grated zucchini and reserve the water to knead the dough later.To wheat flour, add ajwain, turmeric, chilli powder, amchur, jeera powder, and salt.", "Mix well.Add the grated zucchini.Bring together the dough by kneading with the reserved zucchini water.", "Add additional water only if required, and make a pliable dough.Let it rest for 20 minutes.", "Heat a tawa.Pinch out a small ball of the dough.", "Heat a\u00a0Flat bottomed pan.Roll the ball of dough into a circular shape\u00a0and add the rolled paratha with some ghee and cook it on both the sides for about 2 minutes.Serve zucchini paratha with instant\u00a0red\u00a0chilli\u00a0pickle recipe."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Yeleena/zucchini-paratha-recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1145.zucchini-paratha-recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dry Fruit Barfi Recipe - A Healthy Dry Fruit Halwa', 'dry-fruit-barfi-recipe-a-healthy-dry-fruit-halwa', 'The Dry Fruit Barfi is a delicious quick sweet made from figs, dates, pistachios, almonds, cashew nuts and walnuts. The recipe to make the dry fruit barfi is quick and easy and makes it a perfect sweet for Diwali or even as a healthy snack for kids. These are also high energy and nutritious squares that can be enjoyed by each and everyone in the family.', '["1 cup Dates , seedless, finely chopped", "1 cup Dried Figs , dried, finely chopped", "1/4 cup Pistachios , finely chopped", "1/4 cup Cashew nuts , finely chopped", "1/4 cup Whole Almonds (Badam) , finely chopped", "1/4 cup Walnuts , finely chopped", "1 tablespoon Milk", "1 tablespoon Ghee"]'::jsonb, ARRAY['dates', 'dried figs', 'pistachios', 'cashew nuts', 'whole almonds', 'badam', 'walnuts', 'milk', 'ghee']::text[], '["To begin making the Dry Fruit Barfi Recipe, we will first roast pistachios, cashew nuts, almonds and walnuts in ghee until lightly golden and releases a roasted aroma.", "Keep aside the roasted nuts aside.Layer an 8 inch square pan with aluminum foil and keep aside.Blend the finely chopped dates and figs with 1 tablespoon of milk until smooth.Now saut\u00e9 the blend paste in a nonstick wok for 5 minutes till it changes its color to golden brown and well cooked.", "Keep stirring every couple of minutes until the mixture comes away from the sides of the pan.", "Add the roasted dry fruits and mix well into the date fig mixture.Pour and layer this dry fruit barfi mixture into the pan and smoothen it well.", "Allow it to rest until the mixture is cooled completely and firmed a little.Cut the Dry Fruit Barfi into equal squares and store in an air-tight container. it\u00a0during festivals or as a snack for children.Serve the Dry Fruit Barfi Recipe for any festivals or as a \u00a0Tea Time snack for children."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Dry_Fruit_Barfi_Halwa_Recipe_shutterstock_128021267.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1146.Dry_Fruit_Barfi_Halwa_Recipe_shutterstock_128021267.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chironji And Makhane Ki Kheer Recipe', 'chironji-and-makhane-ki-kheer-recipe', 'The Chironji and Makhane Ki Kheer Recipe is a delicious kheer that is rich and yet delicious, packed with flavors from the saffron and nutmeg. If you love Phool Makhana and Chironji then this recipe is just for you.', '["1 cup Phool Makhana (Lotus Seeds)", "1 teaspoon Ghee", "1 liter Milk", "1/4 cup Jaggery", "1/2 teaspoon Cardamom Powder (Elaichi)", "1/2 inch Cinnamon Stick (Dalchini)", "Saffron strands , a few", "Ingredients for Roasted Nuts", "1 tablespoon Whole Almonds (Badam) , sliced", "1/4 cup Sultana Raisins", "1 tablespoon Chironji", "1 teaspoon Ghee"]'::jsonb, ARRAY['phool makhana', 'lotus seeds', 'ghee', 'liter milk', 'jaggery', 'cardamom powder', 'elaichi', 'cinnamon stick', 'dalchini', 'saffron strands', 'ingredients for roasted nuts', 'whole almonds', 'badam', 'sultana raisins', 'chironji']::text[], '["To begin making the Chironji & Makhane Ki Kheer Recipe, we will first roast the phool makhana in ghee until crisp and aromatic.Heat a teaspoon of ghee in a heavy bottomed pan and roast makhana while continuous stirring until they become light brown and crisp.", "Once done, remove from kadai and set aside to cool.Coarsely grind half of the roasted makhana in a mixer grinder and keep aside.", "We will use the remaining roasted makhana as a whole into the kheer.Boil the milk in a heavy bottomed pan and condense the milk until it becomes just close to half.", "Keep stirring occasionally to prevent the milk from settling into the bottom of the pan.Once the milk is condensed, add the jaggery, the roasted Makhana (whole) and coarsely ground Makhana.", "Mix well and cook on a medium flame for 5 to 10 minutes, while stirring occasionally until the kheer becomes thick and the makhana has absorbed and cooked through.", "Add the saffron and nutmeg powder into the kheer, mix well and cook on a medium flame for another 3 to 4 minutes, while stirring occasionally.While the kheer is cooking, heat a teaspoon of ghee into another small pan and roast all the dry fruits in it till lightly brown and you get a roasted aroma.Add the half of the roasted dry fruits to the Makhane Ki Kheer and simmer for 3-4 minutes and turn off the heat.Serve\u00a0Chironji And Makhane Ki Kheer\u00a0after your delicious festive meal of\u00a0Jodhpuri Aloo,\u00a0Ajwain Puri,\u00a0Satvik Carrot Sprout Salad\u00a0and\u00a0Mirchi Ka Chunda."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Makhane_Ki_Kheer_Recipe_The_Hub_Video_Recipe_Festival_Archanas_Kitchen_Vegetarian-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1147.Makhane_Ki_Kheer_Recipe_The_Hub_Video_Recipe_Festival_Archanas_Kitchen_Vegetarian-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Banana Sheera Recipe - Sweet Banana Halwa/ Pudding', 'banana-sheera-recipe-sweet-banana-halwa-pudding', 'Banana Sheera Recipe (Sweet Banana Pudding Recipe) is a rich sweet pudding made with semolina and chopped banana. The pudding is then enriched roasted cashew nuts and raisins in ghee. In Maharashtra it is usually called as “Sheera” but in various other languages it is referred to as “sajjige”, “sooji halwa”, etc., The common ingredients in most of their dish is semolina, sugar, ghee and milk while the flavor changes accordingly.', '["2 Ripe Bananas , chopped", "1 Cardamom (Elaichi) Pods/Seeds", "1 cup Sooji (Semolina/ Rava)", "2 cups Milk", "1/2 cup Hot water", "1/4 cup Jaggery", "1/4 cup Ghee , for toasting", "10 Cashew nuts", "10 Sultana Raisins", "4 Saffron strands"]'::jsonb, ARRAY['cashew nuts', 'bananas', 'cardamom (elaichi) podsseeds', 'milk', 'jaggery', 'raisins', 'water', 'saffron strands', 'ghee toasting', 'sooji (semolina rava)']::text[], '["To begin making the Banana Sheera Recipe toast the semolina on a flat tawa over a medium heat.", "Toast till it becomes light brown.Heat a sauce pan with milk, jaggery, water, cardamom, chopped bananas.", "Allow it boil and add the toasted semolina and keep mixing to create no lumps.", "Switch off the heat and keep it covered.In another pan add the ghee and once it heated add the cashew nuts and raisins and roast them till the raisins bulge.Add this hot ghee with nuts and raisins into the semolina mixture and mix well.Serve the Banana Sheera Recipe can be serve along with a\u00a0spicy upma\u00a0which goes as a great combination for your morning breakfast."]'::jsonb, 25, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Banana_Sheera_Recipe_Sweet_Banana_Pudding_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1148.Banana_Sheera_Recipe_Sweet_Banana_Pudding_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Badam Ki Kheer Recipe - Spiced Almond Milk', 'badam-ki-kheer-recipe-spiced-almond-milk', 'The Badam Ki Kheer recipe is a very simple dessert that is perfect to serve it cold for a summer lunch party or hot during the winters. Its refreshing, nourishing and delicious as well. Almonds are high in protein, therefore its good to include them in your daily meals.', '["1 cup Whole Almonds (Badam) , soaked in warm-hot water for about 30 mts.", "1/4 cup Jaggery , (adjust)", "2-1/2 cups Milk", "3 Cardamom (Elaichi) Pods/Seeds", "Whole Almonds (Badam) , finely chopped, as required", "Cashew nuts , finely chopped, as required", "Pistachios , finely chopped, as required", "1 Saffron strands , a few"]'::jsonb, ARRAY['whole almonds', 'badam', 'jaggery', 's milk', 'cardamom', 'elaichi', 'cashew nuts', 'pistachios', 'saffron strands']::text[], '["To begin making the Badam Ki Kheer recipe, soak the almonds in warm to hot water for about 30 minutes.", "Peel the skin and grind the soaked almonds and the cardamom with a little milk into a fine, smooth paste.", "Mix the saffron in 2 tablespoons of milk and keep aside.Meanwhile, boil the remaining milk along the sugar.", "Make sure the jaggery dissolves completely.", "To the boiled milk, add the ground almond paste.Continue to boil in a low flame once the almond paste is added.", "Keep stirring very frequently else it would get burnt very easily.", "Allow it to boil for a few minutes, and top it with the chopped almonds, cashews, pistachios and saffron strands.Serve\u00a0Badam Ki Kheer\u00a0as a dessert after your delicious meal of\u00a0Dal Makhani,\u00a0Paneer Butter Masala,\u00a0Phulka,\u00a0Jeera Rice\u00a0and\u00a0Satvik Carrot Sprout Salad."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/World_Beverages/Badam_Kheer_Recipe_Indian_Spiced_Almond_Milk-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1149.Badam_Kheer_Recipe_Indian_Spiced_Almond_Milk-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Akhrot Ka Sheera/Halwa Recipe - Walnut Pudding/Fudge Recipe', 'akhrot-ka-sheera-halwa-recipe-walnut-pudding-fudge-recipe', 'Akhrot Ka Sheera or Walnut Halwa is often prepared during the winter months, as it is believed to keep the body warm and protect it from the bitter cold. It is considered to be auspicious for Holi and Diwali and it even features on wedding menus.', '["2 cups Walnuts , coarsely powdered", "1/4 cup Walnuts , chopped", "3/4 cup Milk", "3/4 cup Jaggery", "1/4 cup Ghee", "1 teaspoon Cardamom Powder (Elaichi)"]'::jsonb, ARRAY['s walnuts', 'walnuts', 'milk', 'jaggery', 'ghee', 'cardamom powder', 'elaichi']::text[], '["To begin making the Akhrot Ka Halwa/Sheera Recipe, into a pan add the chopped walnuts and roast until fragrant and\u00a0 slightly brown in colour.", "Once done turn off the heat and keep it aside.Next in a saucepan bring the milk, saffron, cardamom and jaggery to a boil.", "Once it comes to a boil reduce the heat and keep it simmering while we roast the walnut powder.Heat the ghee in a heavy bottomed pan, add the coarsely ground walnut powder.", "Roast the powdered walnuts on medium heat until you get a roasted aroma and the walnuts get a good brown colour.", "Once roasted, add the milk to the walnuts and while adding milk mixture, keep stirring the walnut halwa.", "You will notice that the halwa will start spitting and sputtering all over.", "Keep stirring continuously at this stage until all the milk has been absorbed and the Akhrot Ka Halwa\u00a0leaves the sides of the pan.", "At this stage add the chopped walnuts, stir well to combine and turn off the heat.The final halwa consistency should not be too thick.", "The Akhrot Ka Halwa\u00a0tends to thicken and gets the right texture and consistency once it cools.You can shape the Akhrot Ka Halwa\u00a0by placing it in a square dish and cutting into shapes or serve it as it is.Serve\u00a0Akhrot Ka Sheera\u00a0as a dessert after a party meal of\u00a0Dal Tadka,\u00a0Phulka\u00a0and\u00a0Kadai Paneer."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Akhrot_Ka_Sheera_Recipe_Walnut_Halwa_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1150.Akhrot_Ka_Sheera_Recipe_Walnut_Halwa_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Broccoli Capsicum Pulao Recipe', 'broccoli-capsicum-pulao-recipe', 'Broccoli Capsicum Pulao Recipe is a simple healthy and nutritious rice recipe that is has roasted Raisins and Cashew Nuts making it delicious. Since rice is a constant staple in the Indian diet, adding in different types of vegetables gives it a flavour, crunchiness and ups the health quotient like no other dish does.', '["1 cup Basmati rice", "1/2 cup Broccoli , cut into small florets", "1 Green Bell Pepper (Capsicum) , finely chopped", "1 Red Bell pepper (Capsicum) , finely chopped", "1 Onion , finely chopped", "2 Green Chillies , finely chopped", "4 cloves Garlic , finely chopped", "Coriander (Dhania) Leaves , small bunch, finely chopped", "Salt , to taste", "1 tablespoon Ghee"]'::jsonb, ARRAY['basmati rice', 'red bell pepper (capsicum)', 'coriander (dhania)', 'salt', 'ghee', 'cloves garlic', 'onion', 'broccoli', 'green bell pepper (capsicum)', 'green chillies']::text[], '["To begin making the Broccoli Capsicum Pulao Recipe, we will first cook the rice.", "If you already have the rice cooked, then you can skip this step.In a heavy bottom pan, cook the rice along with 2 cups of water, some salt and 1 teaspoon of ghee.", "Cook until all the water in absorbed and the rice is cooked and separated.", "Keep it a covered side and allow it to cool.", "In a heavy bottomed pan, heat the remaining ghee over medium heat.", "Add in the onions, chili''s, garlic and bell peppers and saut\u00e9 them well until softened.Keep the pan covered so that the bell peppers get softened and cooked.Once done, add in the broccoli and saut\u00e9 them together with the onion mixture until lightly softened.", "Finally, add the cooked rice, black pepper powder, salt to taste and coriander leaves.", "Stir all the ingredients together until well combined.Check the salt and spice levels and adjust to suit your taste.", "Turn off the heat and serve the Broccoli Capsicum Pulao Recipe warm for a delicious weeknight dinner."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Broccoli_Pepper_Rice_Recipe_Pulao-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1151.Broccoli_Pepper_Rice_Recipe_Pulao-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dry Fruits Meetha Paneer Paratha Recipe', 'dry-fruits-meetha-paneer-paratha-recipe', 'The Dry Fruits Meetha Paneer Paratha Recipe is a wholesome and delicious recipe that is packed with dry fruits like almonds and cashew nuts and raisins and flavored with spices. Meetha paratha always takes me to my childhood when my mother used to make it for me so here sharing my recipe.', '["2 cups Whole Wheat Flour", "Water , to knead dough", "Ghee , for cooking", "Ingredients for the filling", "1/2 cup Whole Almonds (Badam) , coarsely powdered", "1/2 cup Cashew nuts , coarsely powdered", "1/2 cup Paneer (Homemade Cottage Cheese) , crumbled", "1/4 cup Sultana Raisins", "1/4 cup Jaggery", "1 teaspoon Ajwain (Carom seeds)", "1 teaspoon Cardamom Powder (Elaichi)", "1 teaspoon Cinnamon Powder (Dalchini)"]'::jsonb, ARRAY['cashew nuts', 'wheat flour', 'ghee', 'paneer', 'ajwain (carom seeds)', 'jaggery', 'raisins', 'water knead dough', 'badam (almond)', 'cardamom powder (elaichi)', 'cinnamon powder (dalchini)']::text[], '["To begin making the\u00a0Dry Fruits Meetha Paneer Paratha Recipe, first get all the ingredients ready - like powdering the nuts and keep them aside.In a large mixing bowl, combine all the ingredients for the filling to form a dough that resembles the bread crumbs and keep aside.In another mixing bowl, add the wheat flour and a pinch of salt.", "Add water little at a time and knead to make a smooth dough.", "Keep this aside.For making parathas - divide the dough into 6 to 8 portions.Roll each portion into a 3 inch circle, dust it in flour to prevent to from sticking to the surface.", "Place a large spoon of the dry-fruit paneer mixture in the center.", "Bring the edges of the dough towards the center to seal the filling.Flatten the paratha, dust in flour and roll it out to make a meetha paneer paratha.", "Roll it as much as your are comfortable to make a paratha that is not very thick.", "Preheat a skillet over medium heat and cook the dry fruit meetha paneer paratha on both sides with ghee until cooked and browned on both sides.Proceed the same way with the remaining parathas and serve hot or cold.Serve\u00a0Dry Fruits Meetha Paneer Paratha along with\u00a0Aam Chunda Pickle\u00a0and\u00a0\u00a0Rose Lassi\u00a0for a tasty breakfast."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Meenakshi_Kapur/dry-fruits-meetha-poori-recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1152.dry-fruits-meetha-poori-recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Whole Wheat Naan Recipe', 'whole-wheat-naan-recipe', 'The Whole Wheat Naan Recipe is a simple and quick recipe and all you need is a whole wheat flour and yeast. There is no maida and no tandoor required to make this naan. Whole wheat naans stays soft as it is made of Vivatta whole wheat flour which is a pure chakki atta.', '["2 cups Whole Wheat Flour", "1-1/2 teaspoons Active dry yeast", "3/4 cup Lukewarm Water", "1 teaspoon Sugar", "2 tablespoon Curd (Dahi / Yogurt)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'wheat flour', 'water', 'dry yeast', 'curd', 'sugar']::text[], '["To begin making the Whole Wheat Naan Recipe, in a large mixing bowl, combine the flour, sugar, salt and yeast.", "Add yogurt and a little lukewarm water at a time and knead to make a smooth dough.", "Knead well for at least 4 to 5 minutes so the dough gets a good texture once it gets cooked.Cover the dough and allow it to rest in a warm place for at least 2 hours until it doubles in size.Once the dough has doubled in size, punch the dough down and knead for a couple of more minutes.", "Make 6 to 8 portions of this dough and allow this to rest for another 10 minutes.", "The portions of dough will rise again a bit.Dust flour on a working surface and roll them into ovals or circles and take care not to roll them too thin.Heat a skillet on medium heat, place the rolled whole wheat naan over the heated skillet and cook on both sides.", "You will notice brown spots come on the top and the naans will puff up with air pockets.", "If you have a gas flame, you can optionally cook it directly over the flame once it is partially done on the skillet.Once done, remove from skillet, smear some butter and serve warm.Serve the healthy and delicious Whole Wheat Naan along with your\u00a0Paneer Butter Masala\u00a0or\u00a0Kadai Paneer\u00a0along with a salad and raita for a weeknight dinner or for parties."]'::jsonb, 170, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breads/Whole_Wheat_Naan_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1153.Whole_Wheat_Naan_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Egg Korma Recipe', 'egg-korma-recipe', 'Egg Korma an easy recipe and it gives a twist to our normal egg curry with coconut milk, and spiced with garam masala, ginger garlic, cumin powder, coriander powder and more. Serve Egg Korma Recipe in lunch or dinner with Butter Naan Recipe or Methi Lachha Paratha Recipe and another side dish like Fansi Muthia Nu Shaak Recipe.', '["4 Whole Eggs , hard boiled", "2 tablespoon Oil", "1 tablespoon Cumin seeds (Jeera)", "2 Onions , chopped", "2-3 Green Chilli , chopped", "2 Tomatoes , chopped", "1 tablespoon Ginger Garlic Paste", "1 tablespoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 tablespoon Coriander Powder (Dhania)", "1/2 tablespoon Garam masala powder", "1/2 cup Coconut milk", "Salt , to taste", "Coriander (Dhania) Leaves , small bunch, finely chopped"]'::jsonb, ARRAY['tomato', 'coconut milk', 'salt', 'coriander (dhania)', 'green chilli', 'red chilli powder', 'ginger garlic paste', 'onion', 'cumin seeds (jeera)', 'coriander powder', 'eggs', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making Egg Korma Recipe, hard boil the eggs firstly.", "Keep all the ingredients ready.Heat oil in a pan, once the oil is hot, on low medium heat, add cumin seeds, and let them splutter.Once they splutter, add chopped onion and green chillies and saute on medium heat until onions are light brown in colour and starting to caramelize.Immediately add ginger garlic paste and saute on low medium heat until the raw aroma of ginger and garlic goes away.Now add the chopped tomatoes and saute till the tomatoes become soft and get cooked properly.Turn off the flame and let the mixture cool down a bit.Grind it to a corse paste in a mixer grinder.Heat same pan again, and add the ground paste in it.Add red chilli powder, turmeric powder, coriander powder, cumin powder, garam masala and salt to taste.Mix well and add about half cup water and bring the mixture to a boil.Add coconut milk to the mixture and let it cook for 5 minutes on medium heat.Now add boiled eggs and cook for 2 minutes more.Egg korma is ready,garnish it with chopped coriander and serve hot.Serve\u00a0Egg Korma Recipe\u00a0in lunch or dinner with\u00a0Butter Naan Recipe\u00a0or\u00a0Methi Lachha Paratha Recipe\u00a0and another side dish like\u00a0Fansi Muthia Nu Shaak Recipe."]'::jsonb, 30, 'Indian', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pooja/Egg_Korma_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1154.Egg_Korma_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Egg And Ridge Gourd Burji - Peerkangai Muttai Poriyal Recipe', 'egg-and-ridge-gourd-burji-peerkangai-muttai-poriyal-recipe', 'Peerkangai Muttai Poriyal is an easy delicious poriyal prepared with peerkangai and egg. This is a great way to make your kids eat this veggie. Not only this, it is popular among us but also in China and Vietnam. It is referred as Luffa by Chinese. In Vietnam, Peerkangai is a common ingredient in soups and stir-fried dishes. They are quite lower in saturated fats as well as calories, hence, there is no limitation to your taste buds. Ridge gourd is recognised for conditioning defense mechanisms and hence acts a protector.', '["1 Ridge Gourd (Turai/ Peerkangai)", "3 Whole Eggs", "1 Onion", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon White Urad Dal (Split)", "1/4 teaspoon Black pepper powder", "1 tablespoon Oil", "Salt , Salt", "6 Curry leaves"]'::jsonb, ARRAY['ridge gourd', 'turai/ peerkangai', 'whole eggs', 'onion', 'cumin seeds', 'jeera', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'black pepper powder', 'oil', 'salt', 'curry leaves']::text[], '["To begin making the Egg And Ridge Gourd Burji, wash and clean the ridge gourd.", "Remove the outer skin and chop them into small pieces.", "Set it aside.Heat oil in a kadai.", "Add mustard seeds, urad dhal and curry leaves.Once mustard seeds clutter, add onion and cook until they become transparent.Add ridge gourd and cook for about 6-8 minutes over medium heat.", "No need to water as the vegetable leaves water.Add eggs and stir well.", "Cook until the eggs are cooked and blended well with the vegetable.Add required amount of salt and pepper according to your spice level.", "Garnish with curry leaves and it is ready to be served.Prepare Egg And Ridge Gourd Burji with healthy ridge gourd and egg and enjoy it with hot steamed rice and\u00a0Mixed vegetable sambar."]'::jsonb, 35, 'South Indian', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Egg__Ridge_Gourd_Burji_Peerkangai_Muttai_Poriyal.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1155.Egg__Ridge_Gourd_Burji_Peerkangai_Muttai_Poriyal.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chettinad Muttai Masala Recipe - Chettinad Style Egg Curry', 'chettinad-muttai-masala-recipe-chettinad-style-egg-curry', 'Chettinad Muttai Masala Recipe is a flavourful egg curry which is very different from the other egg masala recipes. The use of the freshly dry roasted and ground chettinad masala makes it very aromatic giving it a nutty taste and texture.', '["4 Whole Eggs , hard boiled & halved", "1 cup Onion , thinly sliced", "1 Tomato , thinly sliced", "2 teaspoons Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "1/2 teaspoon Red Chilli powder", "1 Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "2 tablespoons Oil", "Salt , to taste", "Chettinad Masala Paste", "2 tablespoons Coriander (Dhania) Seeds", "4 cloves Garlic", "2 inch Ginger", "3 tablespoons Fresh coconut , grated", "2 teaspoon Fennel seeds (Saunf)", "1 teaspoon Whole Black Peppercorns", "2 teaspoons Poppy seeds", "1 teaspoon Cumin seeds (Jeera)", "1 Dry Red Chilli"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'coconut', 'fennel seeds (saunf)', 'red chilli powder', 'cloves garlic', 'black peppercorns', 'dry red chilli', 'coriander (dhania) seeds', 'onion', 'cinnamon stick (dalchini)', 'poppy seeds', 'cumin seeds (jeera)', 'coriander powder', 'eggs', 'cloves (laung)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making Chettinad Muttai Masala Recipe, hard boil the eggs in boiling water for 12 minutes.", "Once cooled, remove the shells and keep aside.Now, dry roast the ingredients listed under the Chettinad masala paste like the coriander seeds, garlic, ginger, coconut, fennel seeds, peppercorns, poppy seeds, cumin seeds and red chill in a Shallow fry pan\u00a0till the coconut starts to turn brown.", "Turn off the heat and let the masala cool down.Once cool grind the roasted masala into a smooth paste in a Mixer grinder with a\u00a0little water and keep aside.Heat oil in a Kadai on medium flame, add the cinnamon stick and cloves and let the spices release its aroma into the oil.Now, add the sliced onions and saut\u00e9 until it turns translucent.", "Add the tomatoes and cook until it is well cooked, soft and mushy.Now, add the ground Chettinad masala mix and mix well.", "Simmer for 5 minutes until the mix is cooked well.Add the coriander powder, red chilli powder, garam masala powder and saut\u00e9 until the oil separates.Add half a cup of water, season with salt and let it simmer for another 3 minutes.Now, add the halved boiled eggs and turn off the heat.", "Transfer the\u00a0Chettinad Muttai Masala into a serving bowl and serve.Garnish with coriander leaves and serve the Chettinad Muttai Masala along with Kerala Parotta\u00a0and\u00a0Tomato Onion Cucumber Raita\u00a0for dinner."]'::jsonb, 50, 'Chettinad', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/25-jan/Chettinad_Muttai_Masala_Recipe_Chettinad_Style_Egg_Curry-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1156.Chettinad_Muttai_Masala_Recipe_Chettinad_Style_Egg_Curry-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kothamalli Kozhukattai (Coriander Rice) Recipe', 'kothamalli-kozhukattai-coriander-rice-recipe', 'Kothamalli Kozhukattai is a traditional recipe from South India which we have tweaked a little to add a twist of coriander flavour. A nutritious, healthy steamed recipe made with rice & dals and is perfect to be served during breakfast and tea time.', '["1 cup Rice", "1/4 cup Arhar dal (Split Toor Dal)", "1/4 cup Chana dal (Bengal Gram Dal)", "2-1/2 Water", "1 teaspoon Coconut Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "5 teaspoons Fresh coconut , grated", "Grind to paste", "2 Green Chillies", "1/4 teaspoon Asafoetida (hing)", "1/2 teaspoon Black pepper powder", "1 teaspoon Cumin seeds (Jeera)", "15 Curry leaves", "Salt , as per required", "4 sprig Coriander (Dhania) Leaves"]'::jsonb, ARRAY['green chillies', 'arhar dal (split toor dal)', 'salt per', 'rice', 'mustard seeds', 'coconut', 'asafoetida (hing)', 'water', 'curry leaves', 'coriander (dhania) leaves', 'cumin seeds (jeera)', 'black pepper powder', 'coconut oil', 'chana dal (bengal gram dal)']::text[], '["To begin with Kothamalli Kozhukattai, grind the rice in the mixer grinder to make rice rawa.", "Grind the dals too to make dal rawa.Heat coconut oil in a non-stick Tawa.", "Add mustard seeds & allow it to splutter.", "Once it splutters, add water & ground paste.When this comes to a boil, add rice rava, dal rava & grated coconut.", "Mix everything well & boil it till the water is absorbed.Keep it aside & let it cool down for a few minutes.", "Once cooled, make Kozakattai (elliptical balls) of the mixture.Arrange in idli plates and steam it for 10 to 15 minutes.Serve Kothamalli Kozhukattai with\u00a0South Indian Coconut Chutney\u00a0and\u00a0Ginger Cardamom Chai."]'::jsonb, 45, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Sowpernica/Kothamalli_Corriander_Rice_Kozhukattai.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1157.Kothamalli_Corriander_Rice_Kozhukattai.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lal Bhoplyacha Bharit Recipe (Red Pumpkin Raita)', 'lal-bhoplyacha-bharit-recipe-red-pumpkin-raita', 'Lal Bhoplyache Bharit is a Maharashtrian side dish made by mixing steamed red pumpkin, curd, crushed groundnuts and is then tempered with flavourful spices. The recipe is very quick and uses simple day-to-day ingredients. This appetising raita is a great side dish even if you are fasting and is sure to win over even those who do not like pumpkin.', '["250 grams Kaddu (Parangikai/ Pumpkin) , peeled and chopped", "3/4 cup Hung Curd (Greek Yogurt) , whisked (adjust)", "1 tablespoon Oil , (or ghee)", "1 teaspoon Cumin seeds (Jeera)", "2 to 3 Green Chillies , chopped", "2 tablespoons Groundnut powder , roasted", "1/4 teaspoon Asafoetida (hing)", "1 teaspoon Sugar", "Salt , Salt to taste", "Coriander (Dhania) Leaves , few, chopped for garnish (optional)"]'::jsonb, ARRAY['salt', 'hung curd (greek yogurt)', 'parangikai pumpkin', 'asafoetida (hing)', 'coriander (dhania) leaves', 'sugar', 'sunflower oil (or ghee)', 'cumin seeds (jeera)', 'groundnut powder', 'green chillies']::text[], '["To begin making the Lal Bhoplyacha Bharit, steam or microwave the pumpkin till soft.", "Drain any excess water from it.Roughly mash the pumpkin pieces, leaving some chunks.", "Cool it down.Add curd, salt, sugar, groundnut powder and mix everything well.In a tadka pan, heat ghee.", "Add the cumin seeds, hing and green chillies.", "Pour this tempering over the raita, mix and serve.Serve Lal Bhoplyacha Bharit with roti for a light weekday lunch or with Bhagar or Sabudana Khichdi for a fasting feast or serve it with Kala Vatana Amti and Phulkas."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Lal_Bhoplyacha_Bharit__Red_pumpkin_raita.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1158.Lal_Bhoplyacha_Bharit__Red_pumpkin_raita.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('North Kanara Sweet And Sour Raw Mango Chutney Recipe', 'north-kanara-sweet-and-sour-raw-mango-chutney-recipe', 'North Kanara Sweet And Sour Raw Mango Chutney Recipe is a very flavoursome raw mango chutney from the Goud Saraswat Brahmin (GSB) Cuisine of North Kanara. The basic cooking of the Karwari GSBs of Karnataka includes a lot of coconut, red chillies and jaggery.', '["3 Mango (Raw) , peeled and cut to 1 inch", "3 Byadagi Dried Chillies", "1 cup Fresh coconut , grated", "1/4 teaspoon Asafoetida (hing) , or Irani Asafoetida", "3 tablespoons Jaggery", "1 teaspoon Kashmiri Red Chilli Powder", "Salt , to taste", "Oil , for roasting"]'::jsonb, ARRAY['salt', 'kashmiri red chilli powder', 'coconut', 'jaggery', 'mango', 'byadagi dried chillies', 'sunflower oil roasting', 'asafoetida (hing) irani asafoetida']::text[], '["To begin making North Kanara Sweet And Sour Raw Mango Chutney Recipe, prep all the ingredients first.In a small pan, heat a half a teaspoon of oil over medium heat and add the raw mango pieces.", "Saute for a few minutes until the raw mango changes color and gets cooked slightly.The mango when exposed to heat will soften a bit.", "Once it does, remove from heat, transfer to a bowl and keep aside.In the same pan, heat 1/2 teaspoon of oil and add the asafoetida and allow it to roast for a few seconds over low heat.", "Add the grated coconut and roast for a few minutes until you can smell the roasted aroma of the coconut and it changes color slightly to a little golden.", "Once done, transfer to the bowl which mangoes were kept and keep aside.In the same pan, add little more oil and roast the byadgi chillies over medium heat for about a minute and turn off the heat.Once done, blend all the roasted ingredients, along with jaggery, mango and salt without adding water to make a sticky sweet and sour mango chutney.Check the spice levels and adjust the chilli and salt accordingly.", "Once done, transfer to the Raw Mango Chutney to bowl and serve.Serve\u00a0North Kanara Sweet And Sour Raw Mango Chutney Recipe along with\u00a0Tawa Paratha Recipe (Plain Paratha), Steamed rice\u00a0and\u00a0Vali Bhajji Ambat Recipe (Konkan Style Spiced Malabar Spinach Dal Recipe)."]'::jsonb, 30, 'Coastal Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/panditp253-gmail.com/SWEET_AND_SOUR_RAW_MANGO_CHUTNEY_recipe_edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1159.SWEET_AND_SOUR_RAW_MANGO_CHUTNEY_recipe_edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karela Besan Sabzi Recipe', 'karela-besan-sabzi-recipe', 'The Karela Besan Sabzi is an absolutely simple, healthy and delicious recipe to make. Rajasthani food uses besan extensively along with vegetables and this karela sabzi is one such dish which is packed with flavours. From sauteed onions, to garlic along with amchur powder and other masalas which add to the deliciousness of this tasty sabzi.', '["300 grams Karela (Bitter Gourd/ Pavakkai)", "2 Onions , thinly sliced", "6 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "3 tablespoons Gram flour (besan)", "1 teaspoon Turmeric powder (Haldi)", "1 tablespoon Coriander (Dhania) Powder", "1 teaspoon Garam masala powder", "1 teaspoon Red Chilli powder", "1 teaspoon Amchur (Dry Mango Powder)", "1/2 teaspoon Ajwain (Carom seeds)", "1 teaspoon Mustard oil", "Salt , to taste"]'::jsonb, ARRAY['s karela', 'bitter gourd/ pavakkai', 'onions', 's garlic', 'ginger', 's gram flour', 'besan', 'turmeric powder', 'haldi', 'coriander', 'dhania', 'garam masala powder', 'red chilli powder', 'amchur', 'dry mango powder', 'ajwain', 'carom seeds', 'mustard oil', 'salt']::text[], '["To begin making the Karela Besan Sabzi, first prep all the ingredients and keep them ready.", "It always helps in making the dish in a more organized way.Karela skin does not have to be peeled, it''s important to cut it along with its green skin for maximum benefits.", "Also avoid soaking the karela in water to remove the bitterness.", "The bitterness is exactly what that adds to the nutrition.", "Only discard the hard seeds if the pulp is not tender.Into a pressure cooker, add the cut roundels of karela, along with turmeric powder, salt and two tablespoons of water.", "Cover the pressure cooker and cook for 2 to 3 whistles and turn off the heat.Once done, release the pressure immediately by running it under cold water or by releasing it with a fork placed under the whistle.The next step is to make the Karela Besan Sabzi masala.Heat oi in a wok or a kadai over medium heat; add the ajwain and allow it to crackle for a few seconds.Add the onion, garlic and ginger and saute until the onions become soft and golden.", "This will take about 3 to 4 minutes in medium heat.Once the onions are golden, add the cooked karela, besan, amchur powder, red chilli powder, coriander powder and garam masala powder.", "Stir to combine all the ingredients well.", "Check the salt and add more if required.Cover the pan, turn the heat to low and simmer the Karela Besan Sabzi for about 3 to 4 minutes and turn off the heat.Check the seasonings and spices and adjust to suit your taste accordingly.You can optionally add jaggery to give it additional taste.", "If you are diabetic you can avoid the jaggery.Once done, transfer the Karela Besan Sabzi to a serving bowl and serve hot.Serve the Karela Besan Sabzi along with\u00a0Rajasthani Kadhi\u00a0and\u00a0Methi And Palak Paratha\u00a0for a wholesome weeknight or weekend dinner."]'::jsonb, 30, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Karela_besan_sabzi_Recipe_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1160.Karela_besan_sabzi_Recipe_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Sarva Pindi/Gine Pindi Recipe (Rice Flour and Chana Dal Flatbread Recipe)', 'andhra-style-sarva-pindi-gine-pindi-recipe-rice-flour-and-chana-dal-flatbread-recipe', 'Andhra Style Sarva Pindi/Gine Pindi Recipe (Rice Flour and Chana Dal Flatbread Recipe) is a delicacy of Telangana which is one of the cuisine of Andhra Pradesh. The dish is similar to the “Akki Rotti” made in Karnataka but the only difference it has few spices added and Channa dal mixed. Traditionally the flatbread is made on a Kadai and patted flat so that once it is cooked it shapes up like a bowl. But we have used a flat griddle to make the rotti. By using different vessel also will make a difference to the taste and texture of the rotti.', '["1 cup Rice flour", "2 tablespoon Chana dal (Bengal Gram Dal) , soaked for 2 hours", "1 sprig Curry leaves , chopped", "1 tablespoon Sesame seeds (Til seeds)", "1 Onion , chopped", "1 Green Chilli , chopped", "1 teaspoon Ginger Garlic Paste", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "Salt , to taste"]'::jsonb, ARRAY['salt', 'chana dal (bengal gram dal)', 'green chilli', 'red chilli powder', 'ginger garlic paste', 'curry leaves', 'onion', 'rice flour', 'turmeric powder', 'sesame seeds (til seeds)']::text[], '["To begin making the Andhra Style Sarva Pindi, add all the ingredients into a bowl and add little water and knead into a soft and malleable dough.Now to prepare the roti, place a nonstick tawa/skillet on the heat.", "Spread out a large piece of plastic, or parchment paper on your work surface.Grease your palms with oil.", "Pinch a big ball of dough place it in the centre of the parchment or plastic.", "Then gently flatten it out to form a hand-patted disc, similar to Thalipeeth.Lift the paper, along with the rotti on it and turning it over, place it on the skillet with the rotti down on the hot skillet.Carefully supporting the rotti peel off the paper.", "Drizzle a little bit of oil along the edges of the roti and in the centre, into the hole made on the roti and allow it to sizzle and crisp up.When it seems half cooked, flip the roti over with a spatula to cook the other side.Cook well till you have brown patches on both sides.", "Then, take the roti off the skillet, add a dollop of butter or ghee, and serve immediately.Serve the Andhra Style Sarva Pindi along with\u00a0Sweet and Spicy Raw Mango Chutney\u00a0or\u00a0Ridge Gourd Pachadi Recipe\u00a0to create a delicious breakfast."]'::jsonb, 40, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Andhra_Style_Sarva_PindiGine_Pindi_Recipe_Rice_Flour_and_Chana_Dal_Flatbread_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1161.Andhra_Style_Sarva_PindiGine_Pindi_Recipe_Rice_Flour_and_Chana_Dal_Flatbread_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('सिंधी करेला भाजी रेसिपी - Sindhi Karela Bhaji Recipe', 'sindhi-karela-bhaji-recipe', 'सिंधी करेला भाजी रेसिपी एक स्वाद से भरपूर सिंधी डिश है जिसमे करेले को प्याज, टमाटर और दही के मसाले के साथ पकाया जाता है. अगर आप करेले से कुछ नया बनाना चाहते है, तो आप यह भी बना सकते है. आप इसे अपने लंच बॉक्स में भी पैक कर सकते है.', '["2 \u0915\u0930\u0947\u0932\u093e , \u0917\u094b\u0932 \u0917\u094b\u0932 \u0915\u093e\u091f \u0932\u0947", "2 \u092a\u094d\u092f\u093e\u091c , \u092a\u0924\u0932\u093e \u0914\u0930 \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "2 \u091f\u092e\u093e\u091f\u0930 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1/4 \u0915\u092a \u0926\u0939\u0940", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "5 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0915\u0936\u094d\u092e\u0940\u0930\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0907\u0932\u093e\u0907\u091a\u0940 \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0905\u0928\u093e\u0930\u0926\u093e\u0928\u093e \u092a\u093e\u0909\u0921\u0930", "\u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947, \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0947 \u0932\u093f\u090f", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932"]'::jsonb, ARRAY['करेला', 'प्याज', 'टमाटर', 'कप दही', 'हरी मिर्च', 'इंच अदरक', 'कली लहसुन', 'छोटा चम्मच जीरा', 'छोटा चम्मच कश्मीरी लाल मिर्च पाउडर', 'छोटे चम्मच धनिया पाउडर', 'छोटा चम्मच इलाइची पाउडर', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच अनारदाना पाउडर', 'धनिया पाउडर', 'नमक', 'बड़ा चम्मच तेल']::text[], '["\u0938\u093f\u0902\u0927\u0940 \u0915\u0930\u0947\u0932\u093e \u092d\u093e\u091c\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0915\u0930\u0947\u0932\u093e \u0915\u0947 \u0938\u093e\u0925 2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u092a\u093e\u0928\u0940, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. \u0915\u0941\u0915\u0930 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947 \u0914\u0930 2 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947.\u00a0\u092a\u094d\u0930\u0947\u0936\u0930 \u0928\u093f\u0915\u093e\u0932 \u0932\u0947. \u0915\u0941\u0915\u0930 \u0915\u094b \u0920\u0928\u094d\u0921\u0947 \u092a\u093e\u0928\u0940 \u0915\u0947 \u0928\u093f\u091a\u0947 \u0930\u0916\u0947\u0902 \u091c\u093f\u0938\u0938\u0947 \u0907\u0938\u0915\u0940 \u0938\u093e\u0930\u0940 \u092a\u094d\u0930\u0947\u0936\u0930 \u0928\u093f\u0915\u0932 \u091c\u093e\u090f\u0917\u0940\u0964 \u0915\u0941\u0915\u0930 \u0916\u094b\u0932\u0947 \u0914\u0930 \u0915\u0930\u0947\u0932\u093e \u0915\u094b \u0928\u093f\u0915\u093e\u0932 \u0915\u0947 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095c\u093e\u0939\u0940 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u091c\u0940\u0930\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947. \u091c\u0940\u0930\u093e \u0915\u0947 \u0924\u095c\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0932\u0939\u0938\u0941\u0928, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 30 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u0928\u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u091f\u092e\u093e\u091f\u0930 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0915\u0936\u094d\u092e\u0940\u0930\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0907\u0932\u093e\u0907\u091a\u0940 \u092a\u093e\u0909\u0921\u0930, \u0905\u0928\u093e\u0930\u0926\u093e\u0928\u093e, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0926\u0939\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e\u0924\u0947 \u0930\u0939\u0947. 2 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0915\u0930\u0947\u0932\u093e \u0921\u093e\u0932\u0947, \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947, \u0915\u095d\u093e\u0908 \u0915\u094b \u0922\u0915\u0947 \u0914\u0930 5 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u0928\u0947 \u0926\u0947. 5 \u092e\u093f\u0928\u091f \u092c\u093e\u0926 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u0947 \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902\u0964 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0938\u093f\u0902\u0927\u0940 \u0915\u0930\u0947\u0932\u093e \u092d\u093e\u091c\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0926\u093e\u0932 \u092a\u093e\u0932\u0915,\u00a0\u092b\u0941\u0932\u094d\u0915\u093e\u00a0\u0914\u0930 \u0916\u092e\u0902\u0917 \u0915\u0915\u095c\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 40, 'Sindhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Sindhi_Karela_Bhaji_Recipe_27_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1162.Sindhi_Karela_Bhaji_Recipe_27_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Raw Papaya, Apple & Carrot Salad Recipe', 'raw-papaya-apple-carrot-salad-recipe', 'Raw Papaya, Apple & Carrot Salad Recipe is a healthy Salad that can be had along with your meals. Salad is a good option to fit in as many vegetables as possible into your everyday diet. Having freshly cut vegetables gives you the entire nutrients and benefits, as cooking takes some of the nutrients away.', '["1 cup Raw papaya , grated", "2 Carrot (Gajjar) , grated", "1 Apple , sliced to julienne", "3 tablespoon Raw Peanuts (Moongphali) , pound", "1 Green Chilli , chopped", "2 sprig Mint Leaves (Pudina) , chopped", "1 Lemon juice", "1 teaspoon Black pepper powder", "Salt , to taste"]'::jsonb, ARRAY['salt', 'green chilli', 'mint leaves (pudina)', 'peanuts (moongphali) pound', 'carrot', 'apple julienne', 'papaya', 'lemon', 'black pepper powder']::text[], '["To begin making the Raw Papaya, Apple & Carrot Salad Recipe, keep all the vegetables and fruit ready for the salad.In a mixing bowl,\u00a0add the grated carrot, papaya, apples, and green chilies.", "Mix well.", "Add the lemon juice, salt and pepper.Toss well, check for salt, finally add pounded peanuts and mint leaves and toss for one last time and serve.Serve the\u00a0Raw Papaya, Apple & Carrot Salad\u00a0Recipe along with\u00a0Horsegram Dal Recipe\u00a0and\u00a0Ragi Tawa Paratha\u00a0for a Diabetic Friendly meal."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Raw_Papaya_Apple__Carrot_Salad_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1163.Raw_Papaya_Apple__Carrot_Salad_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mughlai Zafrani Murg Recipe', 'mughlai-zafrani-murg-recipe', 'Mughlai Zafrani Murg Recipe is a delicious recipe made with chicken in yogurt gravy, flavoured with saffron. Chicken is marinated with lot of yogurt, fresh cream and handy spices and spice powders like cumin powder, coriander powder and lemon juice. This a quick method of preparing the dish since I have used microwave oven to cook the dish. You can also make it in kadai which will take about 40-50 minutes. Make sure you prepare this dish in a non stick pan since there is absolutely no oil used in the recipe. You can pair this recipe along with Naans or side it with biryanis or pulao.', '["500 grams Chicken , chopped to bite size", "100 grams Curd (Dahi / Yogurt)", "3 tablespoons Fresh cream", "2 teaspoons Lemon juice", "1/4 teaspoon Saffron strands", "1 teaspoon Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "1/4 teaspoon Garam masala powder , to spinkle", "1 tablespoon Coriander (Dhania) Leaves , chopped, to garnish"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'garam masala powder spinkle', 'coriander (dhania) leaves', 'saffron strands', 'red chilli powder', 'curd', 'chicken', 'lemon', 'coriander powder']::text[], '["To begin making\u00a0Mughlai Zafrani Murg Recipe, wash the chicken and pat them dry.In a small bowl, to the saffron strands, add a teaspoon of water and let it sit for about 5 minutes to soak.In a mixing bowl, whisk together lemon juice, cream and yogurt with a fork till combined.", "Save a tablespoon of cream for garnishing finally.Also add cumin powder, coriander powder, chilli powder, salt and bay leaf to the bowl.Now add the chicken pieces to the yogurt and spices mixture, mix well with fingers such that all the chicken pieces are coated well.", "Also add the soaked saffron with its water and give a mix.", "You can save a few strands for garnish at the end.Keep the chicken to marinate in the freezer for at least 1-2 hours.After marination, transfer the marinated chicken to a big microwave safe deep bowl.Microwave for 10-15 minutes on high power or till the chicken is cooked.", "Keep checking every minute after 5 minutes since the cooking in microwave completely depends on the power of the waves, which differ with every brand and model of the oven."]'::jsonb, 35, 'Mughlai', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Non_Veg_Recipes/Mughlai_zafrani_murg_recipe.JPG', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1164.Mughlai_zafrani_murg_recipe.JPG', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('South Indian Style Vegetable Kurma Recipe', 'south-indian-style-vegetable-kurma-recipe', 'South Indian Style Vegetable Kurma is a delicious mild flavored mixed vegetable curry that is usually paired with chapathi or poori. Wonderful aromatic spices are subdued with thick coconut paste and cashew paste to give it a rich creamy texture. Poppy seeds are must that goes into the kurma. Grind it with cashews to get a nice thick creamy paste. The flavor of poppy seeds in the kurma makes a lot of difference. Add any vegetables of your choice to this kurma, but the best options are carrots, beans, green peas, potatoes and cauliflower.', '["2 cups Mixed vegetables , use carrots, beans, green peas, potatoes and cauliflower", "2 Onions", "2 Tomatoes , pureed", "2 Green Chillies", "1 tablespoon Red Chilli powder", "1-1/2 tablespoon Coriander Powder (Dhania)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Black pepper powder", "Salt , to taste", "2 inch Cinnamon Stick (Dalchini)", "3 Cardamom (Elaichi) Pods/Seeds", "4 Cloves (Laung)", "1 tablespoon Ginger Garlic Paste", "4 tablespoon Fresh coconut , grated", "2 tablespoon Poppy seeds", "15 to 20 Cashew nuts", "2 tablespoon Oil", "Salt , to taste", "Coriander (Dhania) Leaves , for garnish"]'::jsonb, ARRAY['tomato', 'salt', 'cashew nuts', 'mixed vegetables carrot', 'cardamom (elaichi) podsseeds', 'coconut', 'coriander (dhania) leaves', 'red chilli powder', 'ginger garlic paste', 'onion', 'cinnamon stick (dalchini)', 'poppy seeds', 'black pepper powder', 'cloves (laung)', 'coriander powder', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin with South Indian Style Vegetable Kurma, clean, wash and chop all the vegetables into small pieces.", "Cook them either in a pressure cooker or open pot.", "Do not overcook the vegetables; they have to be cooked Al dente.", "Keep them aside.Finely chop onions and puree the tomatoes without adding water.Soak cashews in enough water for about 30 minutes.", "Grind soaked cashews and poppy seeds with little water into fine paste.Grind grated coconut into thick smooth paste.", "Keep it aside.Heat oil in a deep bottom pan.", "Add cinnamon sticks, cardamom and clove.", "Next add finely chopped onions and green chilies, saut\u00e9 till onions turn translucent.Add ginger garlic paste and cook till raw smell of the paste is gone.", "Add tomato puree and cook till oil separates from the sides of the pan.Add the spice powders and mix well.", "Next, add cooked vegetables alone with water in it and bring it to boilAdd salt to taste and cook for another 5 minutes.", "Now add coconut paste and cashew-poppy seed paste, simmer.", "Mix well and turn off the flame.", "Do not let it boil again; else coconut paste will split the kurma.Remove from flame immediately and South Indian Style Vegetable Kurma is ready to be served."]'::jsonb, 60, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/South_Indian_Style_Vegetable_Kurma.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1165.South_Indian_Style_Vegetable_Kurma.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vaalachi Rassa Bhaaji Recipe - Maharashtrian Style Aloo And Vaal Sabzi', 'vaalachi-rassa-bhaaji-recipe-maharashtrian-style-aloo-and-vaal-sabzi', 'Vaalachi Rassa Bhaaji Recipe is a Maharashtrian dish made using ‘Kadve Vaal’ and coconuts. Kadve vaal are referred to as ‘field beans’ in English. We get different types of vaal in India, like Kadve Vaal (bitter field beans), Goade Vaal (dalimbi / sweet field beans), Surati Vaal, Pavta, etc.', '["1 1/2 cups Vaal Beans , sprouted and peeled", "1 Potato (Aloo)", "1 Onion , finely chopped", "1/2 Tomato , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Kashmiri Red Chilli Powder , bedgi chilli powder", "1 teaspoon Garam masala powder", "To be roasted", "2 teaspoon Oil", "1/2 Onion , thinly sliced", "3/4 cup Fresh coconut , grated", "2 cloves Garlic", "1/4 inch Ginger", "2 tablespoons Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)", "1 sprig Curry leaves"]'::jsonb, ARRAY['s vaal beans', 'potato', 'aloo', 'onion', 'tomato', 'turmeric powder', 'haldi', 'red chilli powder', 'kashmiri red chilli powder', 'garam masala powder', 'to be roasted', 'oil', 'fresh coconut', 's garlic', 'ginger', 's oil', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing', 'curry leaves']::text[], '["To begin making the Vaalachi Rassa Bhaaji Recipe, we need to start the process two night previous to the time of making it.", "First, soak the dried vaal overnight in sufficient water.The next morning, drain out all the water and wash them again in some clear water.", "Drain out all of this water too and keep them covered in a vessel till nightfall or tie them up in a clean cotton or muslin cloth and place in a covered vessel till nightfall.Try placing the vessel in a warm place.", "This will help them sprout well.Remove the sprouted vaal from the cloth and now soak them again in sufficient water, overnight.", "This will help in the loosening of the vaal peels easily the next morning.Next morning, peel all the vaal and set aside.First heat oil in a heavy bottomed pan.", "When it heats up, add the sliced onions and saute till they turn soft and translucent.Add the grated coconut and roast till a little browned.", "Now add the garlic and ginger and roast with the coconut for just a minute or two.", "Remove the mixture from heat and set aside to cool.", "Grind it using sufficient water to get a smooth paste.Chop the onion, tomato finely and set aside.", "Peel and cube the potatoes and immerse in clean water till further use.In the meantime, heat a saucepan and add the oil for tempering to it.When the oil heats up, add the mustard seeds.", "As soon as they splutter add the asafoetida and the curry leaves and mix.Add the chopped onions and saute till they turn translucent.", "Now add the turmeric powder, red chilli powder and saute.", "Cook for about a minute.Add the cubed potatoes and mix well.", "Add sufficient water to immerse the potato cubes and cook covered for 5-7 minutes.Now add the peeled sprouted vaal.", "Mix well and add some more water if required, to cook the potatoes and vaal.", "Keep stirring occasionally.When the potatoes are half cooked, add the chopped tomato and mix well.", "Cook covered stirring occasionally.When the potatoes and vaal are well cooked, add the garam masala powder, ground paste of coconut and salt to taste.Here care should be taken to see that neither are the vaal half cooked, nor over cooked.Add some water if required to get a gravy of medium consistency.", "Bring to a boil and then simmer on low heat for few more minutes.Check seasoning and switch off the heat and transfer to a serving bowl.Serve\u00a0Vaalachi Rassa Bhaaji Recipe\u00a0along with\u00a0Steamed Rice\u00a0and\u00a0Lauki Raita\u00a0for your everyday meal.", "You can also serve it with\u00a0Bhakri\u00a0and\u00a0Lehsuni Dal."]'::jsonb, 70, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/panditp253-gmail.com/Vaalachi_Rassa_Bhaaji_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1166.Vaalachi_Rassa_Bhaaji_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kadai Vegetable Sabzi Recipe (Mixed Vegetable Saute with Spices)', 'kadai-vegetable-sabzi-recipe-mixed-vegetable-saute-with-spices', 'The Kadai Vegetable Sabzi Recipe is a quick and easy sabzi to make that has the goodness of a variety of vegetables adding colour, taste and nutrition to your weeknight dinner. This recipe I have steamed the vegetables a little but before tossing them on the kadai to make the sabzi. By doing this, we preserve nutrition and also helps in the faster cooking process.', '["200 grams Cauliflower (gobi) , small florets steamed", "2 Carrots (Gajjar) , diced or sliced, steamed", "100 grams Green beans (French Beans) , cut into 1 inch pieces, steamed", "1 Onion , diced", "1 Green Bell Pepper (Capsicum) , diced", "3 cloves Garlic , grated", "1 inch Ginger , grated", "1/2 cup Homemade tomato puree , or 2 large tomatoes diced", "1 teaspoon Cardamom Powder (Elaichi)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "1 teaspoon Red Chilli powder", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "Oil , for cooking", "1 tablespoon Butter (Salted)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'green beans (french beans)', 'ginger', 'garam masala powder', 'red chilli powder', 'cloves garlic', 'carrot', 'tomato large tomato', 'onion', 'cardamom powder (elaichi)', 'green bell pepper (capsicum)', 'coriander powder', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'butter', 'cauliflower (gobi) florets', 'sunflower oil']::text[], '["To begin making the Kadai Vegetable Sabzi, we will first steam all the vegetables (carrots, beans and cauliflower).", "You can use a steamer or a pressure cooker to steam your vegetables.", "See the video recipe of how to steam vegetables in a pressure cooker.", "If using a pressure cooker, you just have to add 3 tablespoons of water and not more.", "Next once the vegetables are steamed, keep them aside.Next in a large kadai or a wok or a heavy bottomed pan; add in a tablespoon of oil.", "Add in the grated ginger, garlic, onions and capsicum.", "Stir fry on medium high heat until the onions and capsicum have become lightly lender but are still a little crisp.Once the onions and capsicum have reached the texture that you desire; add in the tomato puree and the masalas (coriander, turmeric, cardamom, garam masala and red chilli powder)Saute all the ingredient and wait for the tomatoes to come to a quick boil.", "After which add in the steamed vegetables, check the salt and spice levels and give all the ingredients a stir.Finally add in the dried fenugreek leaves (kasuri methi).", "Cover the pan, turn the heat to low and simmer the Kadai Vegetable Sabzi for about 3 to 5 minutes.Turn off the heat and trasfter the kadai sabzi to a serving platter."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Mixed_Kadai_Vegetable_Sabzi_North_Indian_Recipe-20.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1167.Mixed_Kadai_Vegetable_Sabzi_North_Indian_Recipe-20.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Homemade Soft Idli Recipe - Steamed Rice and Lentil Cake', 'homemade-soft-idli-recipe-steamed-rice-and-lentil-cake', 'The Homemade Soft Idli recipe is a simple wholesome dish that you can make with ease. This idli recipe also has a video of how to make the Idli Dosa Batter and how to make soft Idli. Idli is all time South Indian breakfast dish that is savoured all over India and the World . It is made from fermented rice and lentil batter and steamed into Idli moulds to get the round shape.', '["3 cups Idli Rice", "1-1/4 cups White Urad Dal (Whole)", "2 teaspoons Methi Seeds (Fenugreek Seeds)", "3 teaspoons Salt", "Water , as required"]'::jsonb, ARRAY['salt', 'idli rice', 'water', 'methi seeds (fenugreek seeds)', 'white urad dal']::text[], '["To begin making soft homemade idli, we will first make the idli batter.", "Soak the rice in water, such that the all the rice is completely immersed in water.", "Let it soak for about 6 hours.Soak the urad dal and fenugreek in water such that all of the dal is completely immersed in water.", "Let it soak for about 6 hours.First grind the urad dal into a fine smooth batter.", "While grinding add just enough water to make it into a very very smooth batter.", "The batter will look fluffy.", "Pour this batter into a large container.Grind the rice into a smooth paste, adding just the required amount of water to grind into a almost smooth batter.", "Adding too much water will make the dosa batter too watery.", "If required grind a little at a time to get a almost smooth batter .The rice batter is a little coarser, but the urad dal batter is super smooth.Combine the urad and rice batter, add salt to taste and set aside for at least 12 hours or overnight until the batter ferments.", "You will notice the batter would have risen in volume.Hence you should place the batter in a large container so it has enough room to increase in its volume."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Classic_Homemade_Soft_Idli_Recipe_Video_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1168.Classic_Homemade_Soft_Idli_Recipe_Video_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pita Saga Bati Basa Recipe', 'pita-saga-bati-basa-recipe', 'Pita saga (glinus oppositifolius) bati basa - Pita saga (glinus oppositifolius) is cooked in a coarsely pounded mustard-garlic green chilli paste along with chopped eggplant, tomato and potato.', '["2 cup Pita saga , (glinus oppositifolius), roughly chopped", "1 Potato (Aloo)", "1 Tomato", "1 Onion", "1 Brinjal (Baingan / Eggplant)", "4 cloves Garlic", "2 Green Chillies", "4 Badi (wadi) , (sun dried lentil dumpling)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Turmeric powder (Haldi)", "Salt , as needed", "2 tablespoons Mustard oil"]'::jsonb, ARRAY['tomato', 'salt', 'mustard oil', 'mustard seeds', 'brinjal (baingan eggsplant)', 'potato (aloo)', 'cloves garlic', 'pita saga (glinus oppositifolius)', 'onion', 'cumin seeds (jeera)', 'badi (wadi) (sun dried lentil dumpling)', 'turmeric powder', 'green chillies']::text[], '["To begin making the Pita Saga Bati Basa recipe, take a deep frying pan or wok.", "Roast the badis (sun-dried lentil dumpling) and crush roughly into small pieces.Now chop onion finely and keep aside.", "Next cut eggplant, potato and tomato into smaller cubes and keep aside.Put mustard seeds, cumin seeds, garlic cloves and green chilies in a blender jar and make a smooth paste.", "But authentically, all the things are put in a mortar-pestle made of stone and then crush and grind to the smooth paste.Take the same deep frying pan or wok.", "Add in chopped pita saga (glinus oppositifolius), paste, chopped onion, cubed eggplant, cubed potato and tomato, salt, turmeric and mustard oil.Mix everything very well preferably by hand.", "Cover with a lid and cook for 10-12 minutes on low flame stirring in between.After some time, all the veggies''ll become a bit mushy.", "Add roughly crushed badis and give a quick mix.Cover the lid and switch of the flame.", "Let it be covered for 2 to 3 minutes, so that the flavours infused with badis.Serve Pita Saga Bati Basa along with\u00a0Steamed Rice\u00a0and\u00a0Kachumber salad\u00a0for a weekday lunch."]'::jsonb, 25, 'Oriya', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/firsttimercook/Pita_Saga_Glinus_Oppositifolius_Bati_Basa.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1169.Pita_Saga_Glinus_Oppositifolius_Bati_Basa.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('South Indian Style Sorakkai Kootu Recipe - Bottle Gourd Cooked with Lentils', 'south-indian-style-sorakkai-kootu-recipe-bottle-gourd-cooked-with-lentils', 'South Indian Style Sorakkai Kootu Recipe -Bottle Gourd Cooked with Lentils Recipe is a delicious combination of lentil and vegetables. The flavors used in this recipe are typically used in day to day cooking in the South Indian Style Kitchen. Coconut is one of the key ingredient present for all of their dry vegetable side dishes.', '["2 cups Bottle gourd (lauki) , diced small", "1/4 cup Yellow Moong Dal (Split)", "1/2 teaspoon Turmeric powder (Haldi)", "To be ground to paste", "1/4 cup Fresh coconut", "1 teaspoon Cumin seeds (Jeera)", "2 Red Chilli powder", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 Dry Red Chilli , broken into half", "1 pinch Asafoetida (hing)", "2 sprig Curry leaves"]'::jsonb, ARRAY['yellow moong dal (split)', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'red chilli powder', 'dry red chilli', 'curry leaves', 'white urad dal (split)', 'bottle gourd (lauki)', 'cumin seeds (jeera)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the South Indian Style Sorakkai Kootu Recipe\u00a0-Bottle Gourd Cooked with Lentils Recipe add moong dal and the chopped bottle gourd in a pressure cooker with little water.Close the cooker with a lid and cook till the cooker releases 4 whistles.", "Once it is done, switch off the heat and release the pressure naturally.Add the ingredients mentioned in the list to be ground into a coarse paste, which is fresh coconut, cumin seeds and red chilli powder.Once the pressure is released, add this paste into the cooked mixture and give it a stir.", "Cook it for 2 minutes and switch off the stove.For the Tadka, heat a skillet with oil and crackle the mustard seeds and urad dal, add the rest of the ingredients and then pour this over the Sorakkai Kootu and serve.Serve the\u00a0South Indian Style Sorakkai Kootu Recipe\u00a0(Bottle Gourd Cooked with Lentils Recipe) along with\u00a0Steamed Rice\u00a0and\u00a0Parappu Rasam\u00a0to enjoy a comforting meal."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/South_Indian_Style_Sorakkai_Kootu_Recipe_Bottle_Gourd_Cooked_with_Lentils_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1170.South_Indian_Style_Sorakkai_Kootu_Recipe_Bottle_Gourd_Cooked_with_Lentils_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Besan Methi Paratha Recipe', 'besan-methi-paratha-recipe', 'Besan Methi Paratha Recipe is a filling paratha, where the dough is stuffed with methi leaves combined with besan that is roasted along with spices, that gives the paratha a punch.', '["2 tablespoons Oil", "1/2 cup Gram flour (besan)", "1/4 teaspoon Asafoetida (hing)", "1/2 teaspoon Ajwain (Carom seeds)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Garam masala powder", "Salt , to taste", "1-1/2 cups Methi Leaves (Fenugreek Leaves) , finely chopped", "2 cups Whole Wheat Flour", "Water , to bind the dough", "Salt , to taste", "Ghee , to cook the parathas"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'wheat flour', 'amchur (dry mango powder)', 'asafoetida (hing)', 'ajwain (carom seeds)', 'methi leaves (fenugreek leaves)', 'red chilli powder', 'gram flour (besan)', 'cumin seeds (jeera)', 'ghee the parathas', 'coriander powder', 'water bind the dough', 'garam masala powder', 'sunflower oil']::text[], '["''To begin making the Besan Methi Paratha Recipe, we will first make the filling for the paratha.", "Heat a pan with oil on medium heat, add in the cumin seeds, ajwain and asafoetida and allow it to sizzle.", "To this add the besan and allowing it to roast on medium-high heat stirring continuously.", "Once the besan has turned into a light brown colour, add in the dry spices -\u00a0red chilli powder,\u00a0coriander powder,\u00a0cumin powder,\u00a0amchur powder,\u00a0garam masala and\u00a0salt to taste.", "Mix well, and add the chopped methi leaves into the pan.", "Mix well and allow the methi leaves to wilt and combine well with the besan mix.", "Turn off the flame, transfer the besan methi stuffing mixture to a bowl and allow it to cool down to room temperature."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Stuffed_Besan_Methi_Paratha_Recipe-8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1171.Stuffed_Besan_Methi_Paratha_Recipe-8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mughlai Keema Paratha Recipe', 'mughlai-keema-paratha-recipe', 'Mughlai Keema Paratha is a classic recipe of street food found on the streets of Bengal of a stuffed paratha with a layer of egg and spicy mutton keema wrapped to make a lifafa-envelope style flaky parathas', '["3 Whole Eggs", "1 cup All Purpose Flour (Maida)", "1 cup Whole Wheat Flour", "2 tablespoons Rice flour , to make it crisp", "1 tablespoon Ghee , or oil", "1 teaspoon Salt", "Water , as required to knead", "500 grams Mutton , minced", "1 Onion , finely chopped", "5 cloves Garlic , garlic, minced", "1 inch Ginger , minced", "2 Green Chillies , finely chopped", "3 Mint Leaves (Pudina) , finely chopped", "5 sprig Coriander (Dhania) Leaves , finely chopped", "4 tablespoon Curd (Dahi / Yogurt) , whisked", "Oil , as required", "1 tablespoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "2 Cardamom (Elaichi) Pods/Seeds", "3 Cloves (Laung)", "4 Whole Black Peppercorns", "4 Dry Red Chillies", "1 inch Cinnamon Stick (Dalchini)", "1 Black cardamom (Badi Elaichi)", "1 teaspoon Mace powder", "1/2 teaspoon Ajwain (Carom seeds)"]'::jsonb, ARRAY['ajwain (carom seeds)', 'black peppercorns', 'onion', 'cloves garlic garlic', 'turmeric powder', 'green chillies', 'sunflower oil', 'salt', 'wheat flour', 'water knead', 'black cardamom (badi elaichi)', 'cardamom (elaichi) podsseeds', 'mace powder', 'dry red chillies', 'mint leaves (pudina)', 'flour (maida)', 'curd', 'eggs', 'rice flour make crisp', 'ginger', 'coriander (dhania) leaves', 'cinnamon stick (dalchini)', 'mutton', 'ghee', 'oil', 'coriander powder', 'cloves (laung)']::text[], '["To begin making the Mughlai Keema Paratha recipe, we will first make the dough.", "To make the dough into a mixing bowl, add the\u00a0all purpose flour,\u00a0wheat flour,\u00a0rice flour, ghee, salt and mix this well.", "Now gradually add required amount of water to make a smooth and soft dough.", "Knead well and bring the dough together.", "Add a teaspoon of oil over the dough completely smoothen it out and place it in a bowl.", "Cover and set side."]'::jsonb, 35, 'Mughlai', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/shaheen_ali/Mughlai_Kheema_Paratha_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1172.Mughlai_Kheema_Paratha_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Angoor Raita Recipe', 'angoor-raita-recipe', 'Summers give us enough reasons to enjoy our favourite fruits as much as we can. One such summer fruit that happens to be my most favourite is Grapes. All those who have tasted fruit raita shall agree with me that grape raita is another variant that tastes amazing as a side dish with veg biryani or Kashmiri Pulao. Well this raita can be made both with green or the black ones. Thick curd whisked and folded with grape slices has mild sweet flavours along with some cumin powder. The red chilli powder gives a lick to your palate initially and then the sweetness soothes it all.', '["2 cups Curd (Dahi / Yogurt)", "1 cup Green Grapes , cut into two halves", "1-1/2 teaspoon Sugar", "Salt , as needed", "1/4 teaspoon Cumin powder (Jeera) , roasted", "1/4 teaspoon Red Chilli powder", "Mint Leaves (Pudina) , few leaves for garnish"]'::jsonb, ARRAY['s curd', 'dahi / yogurt', 'green grapes', 'sugar', 'salt', 'cumin powder', 'jeera', 'red chilli powder', 'mint leaves', 'pudina']::text[], '["To begin making the Take yogurt/thick curd in a large mixing bowl and whisk to make it smooth and creamy.Add salt and sweet as needed and whisk again till sugar dissolves.Add chopped grapes and fold such that the grapes gets along with the curd nicely.Season with roasted cumin powder and red chili powder and garnish with mint leaves and few sliced grape pieces.Serve Chilled with Kashmiri Pulao or Veg Biryani."]'::jsonb, 10, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/shaheen_ali/Angoor_Raita_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1173.Angoor_Raita_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharashtrian Green Chilli Thecha Recipe', 'maharashtrian-green-chilli-thecha-recipe', 'Maharashtrian Green Chilli Thecha Recipe is an exciting side dish had along with many of the Maharashtrian thalipeeth. The spicy green chilli and the pungent garlic is coarsely ground and tempered with mustard seeds, hing to give it a spicy chatpata taste. You can make this in small batch and store it in your refrigerator for later use as well. The Thecha might be quiet fiery to taste but it goes very well with a nice hot Bajra Roti or Jowar Bhakri.', '["15 Green Chillies , chopped", "10 cloves Garlic , chopped", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Asafoetida (hing)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard seeds', 'asafoetida (hing)', 'cloves garlic', 'green chillies', 'sunflower oil']::text[], '["To begin making the Green Chilli Thecha recipe, first grind together the green chillies, garlic and salt to a coarse paste in a mortar and pestle or a blender.Place the ground chillies in a bowl or a bottle.In a tadka pan heat the oil over medium heat.", "Add the mustard seeds and once they splutter add the asafoetida and turn off the heat.", "Pour this tempering over the green chilli thecha and mix well.Serve the Maharashtrian Green Chilli Thecha Recipe along with\u00a0Methi Thalipeeth\u00a0or\u00a0Bhakri\u00a0along with nice cup of\u00a0Gulkand chai."]'::jsonb, 15, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/_Maharashtra_Green_Chilli_Thecha_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1174._Maharashtra_Green_Chilli_Thecha_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mooli Gobhi Aur Methi Sabzi Recipe', 'mooli-gobhi-aur-methi-sabzi-recipe', 'Mooli Gobhi Aur Methi Sabzi Recipe is a simple stir fry of winter vegetables. We have added very little spices to bring out the flavours of the winter produce. Fresh fenugreek leaves are a great source of iron and antioxidants, hence it is good to include in our diets regularly. Serve the Mooli Gobhi Aur Methi Sabzi Recipe along with Phulkas and Tomato Onion Cucumber Raita for a simple weeknight dinner along with Carrot Cucumber Tomato Salad.', '["2 cups Cauliflower (gobi) , cut into florets", "2 Mooli/ Mullangi (Radish) , cut into thick slices", "1 cup Methi Leaves (Fenugreek Leaves) , tighly packed", "5 cloves Garlic , finely chopped", "2 Green Chillies , slit", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 tablespoon Mustard oil", "Salt , to taste"]'::jsonb, ARRAY['methi leaves (fenugreek leaves) tighly packed', 'salt', 'mustard oil', 'cauliflower (gobi)', 'red chilli powder', 'cloves garlic', 'turmeric powder', 'mooli mullangi (radish)', 'green chillies']::text[], '["To begin making\u00a0Mooli Gobhi Aur Methi Sabzi Recipe, cut cauliflower into small florets, soak it in hot water with turmeric and salt for 10 minutes to deworm it before use.Heat mustard oil in a pan on medium heat, and let it smoke.Add the garlic and saute until it turns golden.Add the green chillies and saute for 30 seconds.Now, add the cauliflower florets, sliced radishes, fenugreek leaves and mix well.Add the turmeric, red chilli powder, season with salt the saute for a minute.Let the vegetables cook in its own juices, occasionally stirring in between.Once the vegetables are cooked well, switch off the flame.Serve the\u00a0Mooli Gobhi Aur Methi Sabzi Recipe along with Phulkas\u00a0and\u00a0Tomato Onion Cucumber Raita\u00a0for a simple weeknight dinner along with\u00a0Carrot Cucumber Tomato Salad."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/4-may/Mooli_Gobhi_Aur_Methi_Sabzi_Recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1175.Mooli_Gobhi_Aur_Methi_Sabzi_Recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Onion Raita Recipe - Pyaz Ka Raita Recipe', 'onion-raita-recipe-pyaz-ka-raita-recipe', 'Crunchy onions thinly sliced, dunked in smooth yogurt along with green chilies, mint and coriander leaves and simple Indian masalas, makes this refreshing Onion Raita. It can be served with absolutely anything, be it dal-roti or biryani.', '["1 cup Curd (Dahi / Yogurt)", "1/4 cup Water", "1 Onion , thinly sliced", "1 Green Chilli , finely chopped", "2 sprig Coriander (Dhania) Leaves , finely chopped", "2 sprig Mint Leaves (Pudina) , finely chopped", "1/2 teaspoon Cumin powder (Jeera)", "Salt , to taste"]'::jsonb, ARRAY['curd', 'dahi / yogurt', 'water', 'onion', 'reen chilli', 'coriander', 'dhania', 'mint leaves', 'pudina', 'cumin powder', 'jeera', 'salt']::text[], '["To begin making the Onion Raita Recipe, slice the onions and chop the green chilli, mint and coriander leaves.", "In a mixing bowl, add yogurt, salt, and jeera powder and whisk well until smooth.", "Next add water to adjust the consistency and add the onions, green chilies, mint and coriander leaves.", "Mix well to combine.", "Transfer into a serving bowl and serve.Serve this\u00a0Onion Raita Recipe\u00a0along with\u00a0Ambur Star Chicken Biryani Recipe\u00a0or\u00a0Chettinad Mint Potato Biryani Recipe\u00a0and\u00a0Mirchi Ka Salan Recipe\u00a0for a simple Sunday lunch."]'::jsonb, 10, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sneha-archanaskitchen.com/Onion_Raita_Recipe__1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1176.Onion_Raita_Recipe__1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Instant Cucumber Pickle Recipe', 'instant-cucumber-pickle-recipe', 'Instant Cucumber Pickle is a perfect recipe when you want to try something spicy and tangy with cucumber. It tastes amazing and can be prepared in less than 15 minutes without oil.', '["2 Cucumber , sliced", "2 tablespoons Red Chilli powder", "1/4 tablespoon Asafoetida (hing)", "1/4 tablespoon Turmeric powder (Haldi)", "1/4 tablespoon Methi Seeds (Fenugreek Seeds) , powdered", "1/2 tablespoon Sugar", "1 Lemon , juiced"]'::jsonb, ARRAY['asafoetida (hing)', 'red chilli powder', 'lemon', 'sugar', 'methi seeds (fenugreek seeds)', 'cucumber', 'turmeric powder']::text[], '["To begin making the Instant Cucumber Pickle recipe, put sliced cucumber in a bowl.Add all the remaining ingredients like chilli powder, asafoetida, turmeric powder, methi seeds powder, sugar and lemon juice to the cucumbers and mix till well combined.Keep it aside for an hour so that the flavours are mixed properly with the cucumber and serve.", "Serve Instant Cucumber Pickle as a accompaniment with\u00a0Panchmel Dal\u00a0and\u00a0Phulkas\u00a0for a delicious meal."]'::jsonb, 10, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Instant_Cucumber_Pickle.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1177.Instant_Cucumber_Pickle.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Style Chicken Rezala Recipe - Chicken Korma Recipe', 'bengali-style-chicken-rezala-recipe-chicken-korma-recipe', 'Bengali Style Chicken Rezala Recipe - Chicken Korma is an authentic white coloured gravy dish that has got its roots from Bengal. The chicken thighs and drumsticks are usually used in this curry to lift up the flavour well and make it quite rich.', '["1 Onion , ground to paste", "10 Cashew nuts , ground to paste", "2 tablespoon Sesame seeds (Til seeds) , ground to paste", "2 Bay leaf (tej patta)", "4 Cloves (Laung)", "2 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "4 Dry Red Chillies", "1 tablespoon Garam masala powder", "1 teaspoon Black pepper powder", "Salt , to taste", "2 tablespoon Mustard oil , for cooking", "1 kg Chicken , drumstick and thighs", "1 cup Curd (Dahi / Yogurt)", "1 teaspoon Sugar", "10 Saffron strands , for garnish"]'::jsonb, ARRAY['salt', 'mustard oil', 'sesame seeds (til seeds) ground paste', 'bay leaf (tej patta)', 'cardamom (elaichi) podsseeds', 'saffron strands', 'cashew nuts ground paste', 'curd', 'sugar', 'dry red chillies', 'onion', 'cinnamon stick (dalchini)', 'black pepper powder', 'chicken drumstick thighs', 'cloves (laung)', 'garam masala powder']::text[], '["To begin making the Bengali Style Chicken Rezala Recipe - Chicken Korma, grind the onion, half of ginger and half of garlic in a mixer to a smooth paste.Once the paste is made, remove and transfer it into a bowl.", "Wash the mixer and add cashew nuts and poppy seeds and add about 1/4 cup water and grind it into a smooth paste and set aside in a bowl.Wash the chicken pieces well and place it in a bowl.", "Add half of the ground onion paste, half of cashew-nut and poppy seed paste, and 1 cup of yogurt, salt and 1 teaspoon pepper powder and give it a mix.Marinate the chicken for at least 1 hour in the refrigerator, this will help to tenderise the chicken pieces.Heat a kadai with mustard oil, once it is heated up, add all the whole spice like cloves, cinnamon, cardamom, bay leaf and dry red chillies and saute until the spice are roasted well.", "This will just take a minute.Add the remaining chopped onion, ginger and garlic into the pan and saute for a couple of minutes.Add in the remaining poppy seed and cashew nut paste and give it a stir.Finally add in the marinated chicken pieces along with all the curd mixture into the pan, sprinkle 2 teaspoon garam masala powder, salt to taste and give it a slight mix.Close it with the lid and allow the Chicken Rezala to cook on medium heat for 25 minutes until the chicken is tender and cooked.Make sure you turn the chicken pieces in the middle and give the curry a stir so the chicken gets evenly cooked.Open the lid and sprinkle a teaspoon of sugar and give it a stir and turn off the heat.", "Check the salt and adjust according to taste.Transfer the Chicken Rezala onto a serving plate and sprinkle with few strands of saffron and serve hot.Serve the\u00a0Bengali Style Chicken Rezala Recipe\u00a0along with\u00a0Whole Wheat Onion Stuffed Kulcha\u00a0and\u00a0Begun Bhaja Recipe,\u00a0Pickled Onions Recipe\u00a0by the side to make your meal complete."]'::jsonb, 45, 'Bengali', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Bengali_Style_Chicken_Rezala_Recipe__Chicken_Korma_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1178.Bengali_Style_Chicken_Rezala_Recipe__Chicken_Korma_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Konkani Style Dangar Recipe-Cabbage Fritters', 'konkani-style-dangar-recipe-cabbage-fritters', 'Dangar is basically a spicy, crispy fritter that is prepared by making a coarse rice and lentil based batter, which is then mixed with cabbage, onions and some dry spices, then finally, deep-fried.', '["1/2 cup Rice", "1/2 cup Arhar dal (Split Toor Dal)", "1 Onion , finely chopped", "1 cup Cabbage (Patta Gobi/ Muttaikose) , finely chopped", "1 Dry Red Chilli", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "Asafoetida (hing) , a pinch", "1 tablespoon Rice flour", "1 sprig Coriander (Dhania) Leaves , finely chopped", "Salt , to taste", "Oil , for frying"]'::jsonb, ARRAY['rice', 'arhar dal', 'split toor dal', 'onion', 'cabbage', 'patta gobi/ muttaikose', 'dry red chilli', 'red chilli powder', 'turmeric powder', 'haldi', 'asafoetida', 'hing', 'rice flour', 'coriander', 'dhania', 'salt', 'oil']::text[], '["To begin making\u00a0 Konkani Style\u00a0Dangar, first wash rice and\u00a0toor dal well.", "Soak them together in water for at least 30 minutes.Once both the things seem to be soaked well, drain and make sure there\u2019s no water remaining in the rice and dal.Into a blender, add in the soaked rice and dal, along with a dried red chilly.", "Grind into a coarse paste without adding any\u00a0water.", "It\u2019s okay if you are left with tiny pieces of rice and toor dal as they add a nice crunch after the deep-frying.Transfer the batter into a bowl and add finely chopped onions, cabbage and coriander, along with the dry spices and salt.", "Finally, mix in your rice flour.", "This is mainly to absorb the excess moisture in the mixture.Once the oil is hot enough for deep-frying, grease your palm with some oil\u00a0and taking some mixture into your hand, make a round ball.", "Place carefully into the oil.Repeat until the oil has enough patties for one batch.", "Do not overcrowd!\u00a0Fry on medium heat until\u00a0they are well-cooked uniformly, on the inside and out.Serve Konkani Style Dangar along with\u00a0Dhaniya Pudina Chutney\u00a0and\u00a0masala chai\u00a0as a delicious evening snack."]'::jsonb, 75, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/mallikabhandary-gmail.com/Dangar_Recipe_Konkani_style_cabbage_and_onion_fritters.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1179.Dangar_Recipe_Konkani_style_cabbage_and_onion_fritters.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thengai Poli Recipe - Coconut Poli Recipe', 'thengai-poli-recipe-coconut-poli-recipe', 'Thengai Poli is a classic sweet Indian flatbread stuffed with a filling of coconut and jaggery. Also known as Obbattu or holige in Karnataka,  puran polis in Maharashtra.', '["3 cup Whole Wheat Flour", "Salt , to taste", "2 tablespoons Ghee", "Water , as needed, for kneading", "250 grams Fresh coconut , grated", "160 grams Palm jaggery , powdered", "1 teaspoon Cardamom Powder (Elaichi)", "1 teaspoon Ghee"]'::jsonb, ARRAY['salt', 'wheat flour', 'coconut', 'ghee', 'palm jaggery', 'water', 'cardamom powder (elaichi)']::text[], '["To begin making the Thengai Poli Recipe first sieve the wheat flour and salt together in a large mixing bowl.", "Add\u00a0 water\u00a0a little at a time to knead to make a soft dough.", "Adding enough water is critical, so the dough is soft and pliable.", "Add ghee and knead again.", "Knead the dough well\u00a0 to form a smooth dough.", "Once done make a smooth ball of the dough, cover the bowl and keep aside for 2 hours.In the meanwhile, prepare the sweet coconut filling.", "To do this, first heat a pan and add 1 teaspoon ghee.", "Next add the grated coconut, cardamom powder and palm jaggery to it.Stir well on a low flame for 5-8 mins till all the moisture is absorbed and the coconut mix comes together with the jaggery.", "Once the poli filling mixture has come together, turn off the heat and allow the mixture to cool.When it has cooled, divide it into equal sized portions and form balls the size of medium lemons.Now, take the dough that\u2019s been resting and divide it into equal sized portions.Keeping a little flour for dusting handy on a plate; roll out the dough into 3 inch diameter circles.", "Place a portion of the filling (puran) mixture into the center of the circle.", "Bring edges of the circle towards the center and fold over to cover the entire filling; making sure the edges are all sealed well by pinching them together if there is any opening.Flatten the stuffed poli; dust the dough in a little flour and roll gently into a 5 to 6 inch diameter circle taking care not to put too much pressure as the filling can come out of the dough.", "The Thengai Poli should be thin and not thick.", "Once done, we will proceed to cook the poli.Preheat an iron skillet on medium high; place the rolled poli\u2019s onto the skillet to cook until golden brown on both sides.", "You can cook the poli''s with ghee to give it a richer taste and flavor.Repeat the above process for all the remaining dough and puran portions and serve hot.You may store the Thengai Poli in an airtight container, in the refrigerator, once they have cooled.", "They will keep well for a week at least.", "However, if you are serving them on the same day, allow them to remain at room temperature.Thengai Poli if refrigerated is served by bringing it back to room temperature, slightly warming them in the microwave and served with a dollop of homemade ghee.Serve Thengai Poli for festivals such as Diwali, Navratri or even Janmashtami."]'::jsonb, 150, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Thengai_Poli_Recipe_Coconut_Filled_Sweet_Flatbread-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1180.Thengai_Poli_Recipe_Coconut_Filled_Sweet_Flatbread-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Avarakkai Poricha Kootu Recipe - Broad Beans Kootu Recipe', 'avarakkai-poricha-kootu-recipe-broad-beans-kootu-recipe', 'Avarakkai Poricha Kootu Recipe is a comforting side dish from south India. Avarakkai in other words called as broad beans is a wonderful legume which is rich in proteins and fibre. It is also a good source of minerals like potassium, iron and zinc.', '["200 grams Avarekai (Broad Beans) , chopped", "1/2 cup Yellow Moong Dal (Split) , cooked", "1/4 teaspoon Turmeric powder (Haldi)", "Ingredients to be ground", "1/2 cup Fresh coconut", "4 Dry Red Chillies", "1 teaspoon Cumin seeds (Jeera)", "Curry leaves", "Salt , to taste", "Ingredients for seasoning", "1 sprig Curry leaves", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Coconut Oil", "1 teaspoon White Urad Dal (Split)"]'::jsonb, ARRAY['salt', 'yellow moong dal (split)', 'coconut', 'mustard seeds', 'curry leaves', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'cumin seeds (jeera)', 'coconut oil', 'avarekai (broad beans)', 'turmeric powder']::text[], '["To begin making the\u00a0Avarakkai Poricha Kootu Recipe ; we will first cook the moong dal lentils with about 1 cup of water in a pressure cooker, along with a 1/4 teaspoon of turmeric powder and salt to taste.Pressure cook for at least 4 whistles and turn off the heat.", "Allow the pressure to release naturally and keep the cooked dal aside.Place the\u00a0Avarakkai in the pressure cooker, add a pinch of salt and 2 tablespoons water and pressure cook for one whistle.", "Once done, turn off the heat and release the pressure immediately.", "Releasing the pressure immediately will help, retaining the bright green color of\u00a0Avarakkai.Add the cooked\u00a0Avarakkai to the cooked moong dal and give it a stir.The next step is to grind the Avarakkai\u00a0Kootu masala.Into the mixer grinder, add the grated coconut, cumin seeds, curry leaves and the red chilli into a smooth paste.", "Add couple of tablespoons of water for grinding, this will help the coconut to blend well with the chillies.Add the kootu masala to the\u00a0Avarakkai and the dal.", "Stir well to combine.", "Check the salt and adjust according to taste.Heat oil in a tadka pan; add the mustard seeds, halved white urad dal and allow them to crackle.", "Allow the dal to roast well until lightly browned and crisp on medium heat.", "Stir in the curry leaves and turn off the heat.Once done, add this seasoning to the mixed Avarakkai\u00a0Kootu and give it a stir.When you are ready to serve, give it a brisk boil.", "You can adjust the consistency of the Avarakkai\u00a0Kootu by adding a little water - keep in mind that Kootu as a dish is typically on a thicker side.", "Transfer the\u00a0Avarakkai\u00a0Kootu to a serving bowl and serve hot.Serve the\u00a0Avarakkai Poricha Kootu Recipe\u00a0along with\u00a0Thakkali Rasam Recipe,\u00a0Keerai Masiyal,\u00a0Steamed rice\u00a0and papad for a wholesome Indian lunch or Indian dinner."]'::jsonb, 35, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Avarakkai_Poricha_Kootu_Recipe_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1181.Avarakkai_Poricha_Kootu_Recipe_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dahi Baingan Recipe - Brinjal In Curd Based Gravy', 'dahi-baingan-recipe-brinjal-in-curd-based-gravy', 'Dahi Baingan Recipe (Brinjal In Curd Based Gravy) is a famous North indian dish. The combination of brinjal and yogurt with spices gives a unique taste and goes very well as a side dish with the main meal.', '["5 Brinjal (Baingan / Eggplant) , chopped to bite size", "1 Onion , finely sliced", "2 Tomatoes , finely sliced", "1 cup Curd (Dahi / Yogurt)", "2 tablespoon Gram flour (besan)", "2 teaspoon Coriander Powder (Dhania)", "2 teaspoons Red Chilli powder , (adjust to taste)", "1-1/2 teaspoons Garam masala powder", "1 teaspoon Fennel Powder", "1 pinch Turmeric powder (Haldi)", "Salt , to taste", "3 Dry Red Chillies , (adjust to taste)", "2 tablespoons Sesame seeds (Til seeds)", "Coriander (Dhania) Leaves , a small bunch, to garnish", "Oil , as needed", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Black Urad Dal (Split)", "2 Cloves (Laung)", "2 Cardamom (Elaichi) Pods/Seeds", "1 Bay leaf (tej patta)", "1 inch Cinnamon Stick (Dalchini)", "Curry leaves , a few", "1/2 tablespoon Ginger Garlic Paste"]'::jsonb, ARRAY['tomato', 'brinjal (baingan eggsplant)', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'sunflower oil', 'salt', 'coriander (dhania)', 'cardamom (elaichi) podsseeds', 'dry red chillies', 'garam masala powder', 'mustard seeds', 'red chilli powder', 'curd', 'fennel powder', 'sesame seeds (til seeds)', 'bay leaf (tej patta)', 'black urad dal (split)', 'gram flour (besan)', 'curry leaves', 'ginger garlic paste', 'cinnamon stick (dalchini)', 'coriander powder', 'cloves (laung)']::text[], '["To begin making the Dahi Baingan Recipe (Brinjal In Curd Based Gravy), prepare all the ingredients, with chopping veggies and keeping all the other ingredients handy.In a shallow frying pan, heat about 2 teaspoons of cooking oil, and saute all the brinjal cubes lightly without making them mushy, on a medium flame till the brinjals are browned.", "Switch off and keep aside.In a mixing bowl, mix curd (yogurt) and besan until there are no lumps.", "Now add coriander powder, red chilli powder, fennel powder, garam masala, turmeric powder to the bowl and mix well.Take a kadai and dry roast sesame seeds and dry red chillies.", "Once they cool down to room temperature, blend them in a mixer to a fine powder.Now take little oil in the same kadai, heat.", "Once it is heated, add mustard seeds and cumin seeds.", "Let it splutter.Add split urad dal, cloves, cinnamon, cardamom, bay leaf and wait for it to change color.", "When color changes add curry leaves, allow them to splutter and add ginger garlic paste immediately and fry for a few seconds till the raw smell disappears.Add finely sliced onions and fry on medium heat until onion i brownish.Add sliced tomatoes and cook until they turn soft and mushy.", "Once the tomatoes are cooked, add curd besan and spice powder mix from the bowl and fold till everything gets mixed well.Now add the brinjal cubes which were previously sauteed and continue cooking for some more time till the masala gets seeped into the brinjal, by cooking covered and sauteing occasionally.Add salt, mix, do a taste check and garnish the Dahi Baingan with coriander leaves and switch off heat.You can serve\u00a0Dahi Baingan Recipe (Brinjal In Curd Based Gravy) with\u00a0Phulka Recipe\u00a0or\u00a0Pudina Tawa Paratha.", "You can also serve it with mild\u00a0Saffron Pilaf Recipe (Kesar Pulao)."]'::jsonb, 51, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/neetha2687-gmail.com/Dahi_baingan.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1182.Dahi_baingan.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Punjabi Kadhi Pakora Recipe - Delicious Punjabi Kadhi', 'punjabi-kadhi-pakora-recipe-delicious-punjabi-kadhi', 'Punjabi Kadhi Pakora is Creamy Yogurt Kadhi that is simmered in Potato Pakora and given a delicious ghee tadka.', '["1 cup Gram flour (besan)", "2 Green Chillies , finely chopped", "1 Onion , finely chopped", "1 Potato (Aloo) , grated", "1/2 teaspoon Ajwain (Carom seeds)", "1/2 teaspoon Cooking soda", "Salt , to taste", "Water , to combine the ingredients", "Oil , for deep frying", "Ingredients for the curry", "500 grams Curd (Dahi / Yogurt) , whisked", "3 tablespoon Gram flour (besan)", "1/2 teaspoon Turmeric powder (Haldi)", "2 Green Chillies , chopped", "1/2 inch Ginger , peeled and grated", "2 cups Water", "Salt , to taste", "Ingredients for tempering the Kadhi", "1 tablespoon Ghee", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "5 Curry leaves", "1/2 teaspoon Red Chilli powder", "2 Dry Red Chillies", "1/4 teaspoon Asafoetida (hing)", "Ingredients to garnish", "4 sprig Coriander (Dhania) Leaves"]'::jsonb, ARRAY['salt', 'ginger', 'water combine the ingredients', 'ghee', 'mustard seeds', 'ajwain (carom seeds)', 'potato (aloo)', 'red chilli powder', 'water', 'asafoetida (hing)', 'gram flour (besan)', 'curd', 'soda', 'curry leaves', 'onion', 'dry red chillies', 'coriander (dhania) leaves', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Punjabi\u00a0Kadhi Pakoras\u00a0lets begin to make pakora mixture in a bowl by combining all the ingredients of pakora together except water.", "Add a little water at a time to the dry ingredients and mix well until all the ingredients come together to make a thick batter.Heat a Kuzhi paniyaram Pan, drizzle some oil in each cavities.", "Once the oil is heated, take a small portion of batter in spoon or finger\u00a0 and drop them into each cavities.Fry the pakoras on medium heat until pakoras turn golden brown from outside.", "Flip it on the other side as well.", "Once done transfer to a plate lined with a paper napkin.", "Set the pakoras aside while you prepare Kadhi.To prepare Kadhi, whisk the yogurt along with the gram flour until well combined.", "Add 2 cups of water and whisk again.", "Whisk thoroughly to ensure there are no lumps.", "Add in the spices, salt, chopped green chili, grated ginger to this gram flour mixture.", "Stir once again to combine the ingredients.Pour the kadhi mixture in a heavy bottomed saucepan and heat it over medium heat.", "Once punjabi Kadhi starts simmering stir to avoid lump formation.Once it has begun to boil, turn the heat to low and simmer for about 20 minutes, stirring occasionally.", "Now add fried pakoras to it and simmer the punjabi kadhi pakora further for 5 minutes.", "Turn off the heat.", "For tempering the punjabi kadhi pakora, add a tablespoon of ghee into a saucepan on medium heat.Add the mustard seeds, once seeds crackle add the curry leaves, red chilies and fry for 1 minute until roasted.", "Now add asafoetida, red chili powder and stir to combine.", "Turn off the heat.Pour this seasoning over the Punjabi Kadhi Pakora.", "Garnish with coriander leaves and serve.Serve the\u00a0Punjabi Kadhi Pakora\u00a0along with\u00a0Phulka Recipe (Roti/Chapati),\u00a0Carrot Cucumber Tomato Salad\u00a0and\u00a0Kaddu Simla Mirch Sabzi."]'::jsonb, 50, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/April-18/Punjabi_Kadhi_Aloo_Pakora_Recipe-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1183.Punjabi_Kadhi_Aloo_Pakora_Recipe-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Indian Tea Masala Powder', 'indian-tea-masala-powder', 'Indian Chai masala powder is an aromatic spice powder used for making masala tea. Indian tea is a common beverage for us. We start our day with a hot ginger-cardamom tea. If you make the masala tea powder, then you don''t have to add any spices to the tea while making it.', '["4 Cardamom (Elaichi) Pods/Seeds", "20 grams Dry ginger powder", "2 inch Cinnamon Stick (Dalchini)", "1 teaspoon Whole Black Peppercorns", "1 teaspoon Nutmeg powder", "1 teaspoon Cloves (Laung)", "2 tablespoons Dried basil leaves"]'::jsonb, ARRAY['cardamom', 'elaichi', 's dry ginger powder', 'cinnamon stick', 'dalchini', 'whole black peppercorns', 'nutmeg powder', 'cloves', 'laung', 's dried basil leaves']::text[], '["To begin making the Indian Chai masala powder, use the mixer grinder to powder the dried ginger, green cardamom, cinnamon and black pepper.", "Now add the remaining spices into mixture jar and make smooth powder of it.Indian Chai masala powder is ready to use.", "Store it in container in room temperature, it can be used for many months.Use this Indian Chai masala powder in your regular tea and make it even more flavourful."]'::jsonb, 10, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Roop/Indian_Tea_ChaiMasala_Powder.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1184.Indian_Tea_ChaiMasala_Powder.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Poha Buttermilk Idli Recipe', 'poha-buttermilk-idli-recipe', 'Poha Buttermilk Idlis are a tasty and simple idli recipe. There is no need for grinding  any rice or dals to make these soft and tasty idlis. Poha or flattened rice, suji and rice flour are all mixed along with a tempered buttermilk and left to ferment for about 4 hours. Then the batter is poured in an idli steamer and steamed to make delicious and soft idlis.', '["4 cups Buttermilk", "2 cups Poha (Flattened rice)", "4 tablespoons Sooji (Semolina/ Rava)", "1 tablespoon Rice flour", "2 tablespoons Coriander (Dhania) Leaves , chopped", "2 Green Chillies , chopped", "1/2 teaspoon Ginger , grated", "1/2 teaspoon Garlic , minced", "1 sprig Curry leaves", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "Salt , as required", "1 tablespoon Oil"]'::jsonb, ARRAY['salt', 'ginger', 'coriander (dhania) leaves', 'poha (flattened rice)', 'mustard seeds', 'curry leaves', 'garlic', 'buttermilk', 'sooji (semolina rava)', 'rice flour', 'green chillies', 'sunflower oil']::text[], '["To begin making Poha Buttermilk Idli, whisk the buttermilk in a mixing bowl and keep it aside.The next step is to temper the buttermilk.", "Heat 1 tablespoon oil in a pan and add mustard seeds and curry leaves.", "As soon as the mustard seeds splutters turn off the heat and\u00a0 temper the buttermilk.Now add poha, suji, rice atta and salt to the buttermilk.", "Mix well to combine.", "The batter may look thin but it will get thick after few hours.Add chopped coriander, green chillies and grated ginger garlic to the poha idli batter and mix well.Cover the bowl with a lid and let it rest overnight or minimum 4 hours.", "Once the batter is done, stir and mix it vigorously with a ladle or spatula.Grease the idli molds and put batter generously in each cavity.", "Steam the idlis in a steamer till it turns fluffy and properly cooked. the poha idlis will take about 8-10 minutes to steam.", "Allow to rest for a few minutes and then unmould the poha idli into a serving plate and serve hot.", "Serve\u00a0Poha\u00a0Buttermilk Idli with\u00a0South Indian Coconut Chutney\u00a0and\u00a0Red Chilli Coconut Chutney\u00a0for a wholesome breakfast."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shaheen_Ali/Poha_Buttermilk_Idli.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1185.Poha_Buttermilk_Idli.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Till Wale Aloo Recipe - Sesame Potato Sabzi', 'till-wale-aloo-recipe-sesame-potato-sabzi', 'Till Wale Aloo Recipe is an easy recipe and gives our routine potato veggie a twist. It can be served in lunch or dinner. You can also stuff the leftover sabzi into paratha and give a twist to your aloo paratha. Pack this sabzi for you and your kids lunch box or serve it as a side dish along with your meal.', '["1 tablespoon Oil", "3 Potato (Aloo) , boiled, peeled and cut into cubes", "1 tablespoon Ginger , paste", "1 Green Chilli , chopped", "1-1/12 tablespoons Sesame seeds (Til seeds)", "1 teaspoon Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Coriander Powder (Dhania)", "Salt , to taste", "1/2 teaspoon Garam masala powder", "2 tablespoons Sweet Chutney (Date & Tamarind)", "Coriander (Dhania) Leaves , chopped (few)"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'green chilli', 'coriander powder', 'coriander (dhania) leaves', 'potato (aloo)', 'red chilli powder', 'sweet chutney (date tamarind)', 'ginger paste', 'sesame seeds (til seeds)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Till Wale Aloo Recipe, heat oil in a heavy bottomed pan.", "Once the oil is hot, add ginger and green chillies.", "Make sure you don''t burn them.", "After a minute, add sesame seeds and saute for a while.", "Add potatoes and toss it for about 2 minutes.After 2 minutes, add red chilli powder, cumin powder, coriander powder, garam masala and salt to taste.", "Saute for 3-4 minutes on low flame.After 3 to 4 minutes, add tamarind chutney, mix it well and cook for one more minute.", "Garnish with chopped coriander leaves and serve hot.Serve Till Wale Aloo along with\u00a0Gujarati Dal,\u00a0Roti\u00a0and\u00a0Kachumber Salad\u00a0for a weekday meal."]'::jsonb, 20, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pooja/Till_wale_aloo.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1186.Till_wale_aloo.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Cheesy Paneer Masala Curry Recipe', 'cheesy-paneer-masala-curry-recipe', 'I always prefer dhaba style cooking might be for their rustic charm or for their earthy flavors. Paneer butter masala is one of famous delicacies of North Indian cuisine. Cheesy Paneer Masala Curry Recipe definitely stands out in comparison to its regular counterpart.', '["200 grams Paneer (Homemade Cottage Cheese) , cubed", "2 cups Tomato , puree", "2 tablespoons Britannia Cheese Spread - Classic", "2 Onions , finely chopped", "1 inch Ginger", "6 cloves Garlic", "2 Black cardamom (Badi Elaichi)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 tablespoon Honey", "Salt , to taste", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "1 tablespoon Oil"]'::jsonb, ARRAY['tomato', 'black cardamom (badi elaichi)', 'salt', 'ginger', 'paneer', 'red chilli powder', 'cloves garlic', 'britannia cheese classic', 'onion', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Cheesy Paneer Masala Curry Recipe, into a mixer grinder add tomato puree and Britannia classic cheese spread.", "Blend to make a smooth puree and keep aside.", "Next into a preheated pan add oil, onions, ginger, garlic, badi elaichi and saute until the onions soften and turn golden brown in color.", "Once done add the tomato cheese puree, turmeric powder, garam masala powder, red chilli powder, honey and salt to taste.Stir well to combine and give the tomato mixture a brisk boil.After the gravy has come to a boil add the paneer and kasuri methi.", "Simmer for 3 to 4 minutes and turn off the heat.", "Serve\u00a0Cheesy Paneer Masala Curry Recipe\u00a0along with\u00a0Homemade Butter Naan Recipe,\u00a0Dhaba Style Dal Palak Recipe\u00a0and\u00a0Lacha Pyaz\u00a0for a complete meal."]'::jsonb, 65, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Cheesy_Paneer_Masala_Gravy_Recipe_Britannia_Cheesy_Kitchen_Video_Recipe_17_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1187.Cheesy_Paneer_Masala_Gravy_Recipe_Britannia_Cheesy_Kitchen_Video_Recipe_17_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mini Rava Idli With Tomato Chutney Recipe', 'mini-rava-idli-with-tomato-chutney-recipe', 'Mini Rava Idli with Tomato Chutney recipe is delicious and you get spongy soft and so flavorful idlis. For this yummy rava idli, i also made tomato chutney which will go hand in hand with the dish. You can add few cashew nut to the batter to give a nice crunch to the dish.', '["1 cup Sooji (Semolina/ Rava)", "3 tablespoon Hung Curd (Greek Yogurt)", "Lukewarm Water , for the batter", "1 teaspoon Coriander (Dhania) Leaves , chopped", "Oil , to grease the mould", "1 Tomato , chopped", "2 cloves Garlic , chopped", "1/2 inch Ginger , chopped", "Salt , to taste", "1/2 teaspoon Black pepper powder", "1 teaspoon Oil"]'::jsonb, ARRAY['tomato', 'salt', 'hung curd (greek yogurt)', 'ginger', 'coriander (dhania) leaves', 'water the batter', 'cloves garlic', 'black pepper powder', 'sooji (semolina rava)', 'sunflower oil']::text[], '["To begin with, the mini rava idli with tomato chutney recipe, Start by preparing the rava idli batter which is one part rava, curd, and two parts water add salt to season and keep it aside.Now for the tomato chutney in a blender add tomatoes, garlic, and ginger, grind them to a fine puree and keep them aside.Pulse together tomatoes,ginger,garlic to form a smooth pur\u00e9e.Take a small pan and heat oil to a medium high and add the tomato puree to it and saute\u00a0it for few minutes until it''s cooked and oil oozes from outside.Now let''s start making the mini idli, grease the mould generously with oil and pour in the batter(as a measure about a teaspoon of batter went to make one idli)Place the idli\u00a0mould inside a cooker or an idli cooker and steam it for 10 minutes and check if a toothpick dipped in comes out clean.Serve the Mini Rava Idli with Tomato Chutney for breakfast with a cup of filter coffee and other chutneys like\u00a0Kadale Chutney (Fried Gram Chutney) Recipe\u00a0or\u00a0Chammanthi Chutney Recipe (Coconut And Onion Chutney)."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Akansha_Bansal/Rava_Idli_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1188.Rava_Idli_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Broccoli Malai Kofta Recipe', 'broccoli-malai-kofta-recipe', 'The Broccoli Malai Kofta Recipe, is a wholesome and nutritious way to combine the broccoli and paneer into a Kofta.', '["1 Broccoli , grated", "100 grams Paneer (Homemade Cottage Cheese) , crumbled", "2 tablespoons Gram flour (besan)", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 inch Ginger , grated", "2 cups Homemade tomato puree", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "1 teaspoon Red Chilli powder", "1/4 teaspoon Cardamom Powder (Elaichi)", "1 teaspoon Garam masala powder", "1/2 cup Hung Curd (Greek Yogurt)", "1 teaspoon Honey", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "Oil , for cooking", "Salt , to taste"]'::jsonb, ARRAY['broccoli', 's paneer', 'homemade cottage cheese', 's gram flour', 'besan', 'cumin powder', 'jeera', 'turmeric powder', 'haldi', 'salt', 'ginger', 's homemade tomato puree', 'coriander powder', 'dhania', 'red chilli powder', 'cardamom powder', 'elaichi', 'garam masala powder', 'hung curd', 'greek yogurt', 'honey', 'kasuri methi', 'dried fenugreek leaves', 'oil']::text[], '["To begin making the\u00a0Broccoli Malai Kofta Recipe, combine all the ingredients for the kofta in a large bowl.", "Adjust the salt to suit your taste.", "Make bite-size broccoli malai kofta balls and keep aside.There are two ways we can cook these koftas without deep frying them.One is the Oven Method.", "If you plan to bake the kofta''s; then place the kofta balls on a greased baking sheet.", "Brush the kofta balls with some oil and bake in a preheated oven (200 C) until the koftas turn golden brown in colour.", "Remove the kofta''s from the oven once baked and keep them aside.The Second is the Kuzhi Paniyaram Pan\u00a0Method.", "If you plan to use the Kuzhi Paniyaram Pan; then place the kofta balls in the pan''s cavities; drizzle the kofta''s with a little oil and pan fry them until golden brown on both sides.", "You will have to flip the kofta balls so they fry on all sides evenly.", "The next step is to make the Kofta Curry Base.Heat oil in a heavy bottomed pan; add the grated ginger, and honey and saute for about a minute until the honey begins to bubble.", "Add the tomato puree, turmeric powder, garam masala powder, chilli powder, coriander powder and simmer the kofta gravy for about 5 minutes until the raw smell from the tomatoes goes away.Add in the hung yogurt, 1 cup of water, salt to taste, the pan fried kofta''s and simmer for another 5 minutes and serve.Serve the Broccoli Malai Kofta\u00a0with a soft\u00a0Phulka''s\u00a0and a\u00a0Paneer Pulav\u00a0for a weeknight dinner or for your parties when you call friends over."]'::jsonb, 60, 'Lucknowi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Broccoli_Malai_Kofta_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1189.Broccoli_Malai_Kofta_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Patra Ni Machi Recipe - Fish Cooked In Banana Leaf', 'patra-ni-machi-recipe-fish-cooked-in-banana-leaf', 'Anything wrapped in banana leaf and cooked to perfection is the most amazing food to eat in the whole world! I love food cooked in banana leaf. The flavour which the leaf imparts to the dish is just amazing. This kind of food is rustic, homely and lip smacking delicious!', '["3 Pomfret fish", "1 teaspoon Salt", "Banana leaf , to wrap the fish", "1 cup Coriander (Dhania) Leaves", "1 cup Mint Leaves (Pudina)", "5 Green Chillies", "8 cloves Garlic", "1-1/2 teaspoon Cumin seeds (Jeera)", "1/2 cup Fresh coconut , grated", "1 teaspoon Salt", "1 teaspoon Sugar", "1 teaspoon Lemon juice"]'::jsonb, ARRAY['salt', 'pomfret fish', 'coriander (dhania) leaves', 'coconut', 'cloves garlic', 'sugar', 'banana leaf wrap the fish', 'cumin seeds (jeera)', 'lemon', 'mint leaves (pudina)', 'green chillies']::text[], '["To begin making the Patra Ni Machi Recipe, Into a blender add all the ingredients mentioned under the list \u2018For the chutney\u2019 like the coconut, coriander leaves, mint leaves, green chillies, cumin seeds, salt, sugar and lemon juice and blend into fine thick paste.", "You need not add any water, make sure your paste is fine and thick.Clean the fish.", "Make small slits on the fish on both sides.", "Smear good amount of green chutney on both the sides of the fish.Place a steamer with little little water on heat.Now take a pieces of banana leaf and place it on steamer which is boiling.", "This helps the banana leaf to become soft and easy to fold without breaking or tearing.", "Place the banana leaf on steamer for about a minute on each side.", "Then remove it off.Place the fish on the banana leaf now and then fold it on all four sides to make a parcel.Place the wrapped banana leaf on steamer and steam for about 10 to 14 minutes until the fish is cooked through.Once done remove the fish from the steamer, carefully unwrap the banana leaf and transfer the steamed fish onto a serving plate and serve immediately.Serve Patra Ni Machi on its own along with some\u00a0Steamed Rice\u00a0and\u00a0Vegetable Dhansak\u00a0or a perfect Parsi meal."]'::jsonb, 30, 'Parsi', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/Patra_ni_Machi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1190.Patra_ni_Machi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chilka Roti Recipe (Jharkhand Style Rice and Lentil Roti)', 'chilka-roti-recipe-jharkhand-style-rice-and-lentil-roti', 'Chilka Roti Recipe is famous dish from the state of Jharkhand made using Rice and Chana dal. It is fairly a simple recipe which requires minimal preparation. The rice and chana dal is soaked overnight, and ground in the morning to make thin crepes. It is a nutritious breakfast recipe loaded with the right amount of carbs and proteins. Serve the Chilka Roti Recipe (Jharkhand Style Rice and Lentil Roti) along with Lahsun ki Chutney | A Spicy Garlic Chutney and Baingan Ka Chokha Recipe for weekday breakfast.', '["1-1/2 cups Rice , soaked overnight", "3/4 cup Chana dal (Bengal Gram Dal) , soaked overnight", "Oil , for making the rotis", "Salt , to taste"]'::jsonb, ARRAY['salt', 'sunflower oil making the rotis', 'chana dal (bengal gram dal)', 'rice']::text[], '["To begin making\u00a0Chilka Roti Recipe (Jharkhand Style Rice and Lentil Roti), wash and soak the rice and chana dal in water overnight.In the morning, rinse it in water and grind it to a smooth paste using a mixer grinder with very little water.The consistency should be thicker than the normal dosa batter.Take the ground mix in a bowl, season with salt and whisk well to incorporate air into the mix.", "This will make the mixture airy and light to make softer crepes/rotis.Heat a skillet on medium heat, grease it with a little bit of oil.Pour a ladle full of the prepared rice and chana dal mix, spread it like a dosa, by making outward swirls with teh ladle.Pour a teaspoon of oil around and let it cook for about 2 minutes on medium heat or till done.Once the bottom is cooked, flip over and cook the other side for another 1-2 minutes or till done and take it out on a plate.Likewise, prepare the rest of the chilka rotis with the remaining batter.Serve the\u00a0Chilka Roti Recipe (Jharkhand Style Rice and Lentil Roti) along with\u00a0Lahsun ki Chutney | A Spicy Garlic Chutney\u00a0and\u00a0Baingan Ka Chokha Recipe\u00a0for weekday breakfast."]'::jsonb, 20, 'Jharkhand', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Chilka_Roti_Recipe_Jharkhand_Style_Rice_and_Lentil_Roti.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1191.Chilka_Roti_Recipe_Jharkhand_Style_Rice_and_Lentil_Roti.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Parsi Style Sekta Ni Sing Recipe-Sweet & Spicy Drumsticks Cooked In Coconut Water/Toddy Recipe)', 'parsi-style-sekta-ni-sing-recipe-sweet-spicy-drumsticks-cooked-in-coconut-water-toddy-recipe', 'Sekta Ni Sing Recipe - Sweet & Spicy Drumsticks Cooked In Coconut Water/Toddy is an interesting recipe made from tender coconut water which is combined with the drumstick. The curry gives a sweet and rich taste from the coconut that is being used. The other ingredients such as green chilies , coriander, and ginger compliment really well with the tender coconut that is being used in this recipe.', '["1 Drumstick , cut into 3 inches", "300 ml Tender coconut water , or toddy", "To grind", "3 Green Chillies", "1/2 cup Coriander (Dhania) Leaves , a small bunch finely chopped", "1 inch Ginger", "4 Cloves (Laung)", "3 tablespoons Fresh coconut", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "Ghee , for cooking"]'::jsonb, ARRAY['coriander (dhania)', 'salt', 'ginger', 'coconut', 'ghee', 'drumstick', 'tender coconut water toddy', 'cloves (laung)', 'turmeric powder', 'green chillies']::text[], '["We begin making the Parsi Style Sekta Ni Sing-Sweet & Spicy Drumsticks Cooked In Coconut Water/Toddy by cleaning the drumsticks and peeling out the outside skin.Cut them into one-inch length pieces.Heat a pan, fry all the spices that are supposed to be ground, once done, let it cool down and then grind it into a smooth paste.", "Heat ghee in a kadai and saute the drumsticks for few minutes till it becomes soft.", "Then add the ground spice.", "Add the tender coconut water or toddy and simmer it for 20 minutes.", "Serve the Parsi Style Sekta Ni Sing - Sweet & Spicy Drumsticks Cooked In Coconut Water/Toddy with\u00a0Sama Khichdi Recipe (Barnyard Millet/ Navratri Fasting/Vrat Recipe)."]'::jsonb, 50, 'Parsi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/oct-14/Sekta_Ni_Sing_Parsi_Style_Sweet_and_Spicy_Drumsticks_Cooked_In_Coconut_Water_Toddy-5.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1192.Sekta_Ni_Sing_Parsi_Style_Sweet_and_Spicy_Drumsticks_Cooked_In_Coconut_Water_Toddy-5.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('हैदराबादी वेजिटेबल बिरयानी रेसिपी - Hyderabadi Vegetable Biryani Recipe', 'hyderabadi-vegetable-biryani-recipe', 'हैदराबादी वेजिटेबल बिरयानी रेसिपी एक बहुत ही प्रसिद्ध रेसिपी है जिसमे चावल, मीट और रोज के मसालो का प्रयोग किया जाता है. यह एक बहुत ही स्वादिष्ट रेसिपी है जिसे आप किसी भी ख़ास अवसर पर बना सकते है. फ्लेवर से भरपूर और बनाने में आसान, आप इस बिरयानी को हाउस पार्टीज के लिए भी बना सकते है.', '["1/2 \u0915\u092a \u0939\u0930\u093e \u092c\u0940\u0928\u094d\u0938 , \u0915\u093e\u091f \u0915\u0947 \u092d\u093e\u092a \u0932\u0947", "1/2 \u0915\u092a \u0917\u093e\u091c\u0930 , \u0915\u093e\u091f \u0915\u0947 \u092d\u093e\u092a \u0932\u0947", "1 \u0915\u092a \u0917\u094b\u092d\u0940 , \u0915\u093e\u091f \u0915\u0947 \u092d\u093e\u092a \u0932\u0947", "1 \u0915\u092a \u0906\u0932\u0942 , \u0909\u092c\u093e\u0932\u0915\u0930, \u091b\u0940\u0932 \u0932\u0947 \u0914\u0930 \u0915\u093e\u091f \u0932\u0947", "\u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f", "6 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928", "2 \u0907\u0902\u091a \u0905\u0926\u0930\u0915", "1 \u092a\u094d\u092f\u093e\u091c , \u0915\u093e\u091f \u0932\u0947", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a", "\u092c\u093f\u0930\u092f\u093e\u0928\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0940 \u0938\u093e\u092e\u0917\u094d\u0930\u0940", "2 \u0915\u092a \u091a\u093e\u0935\u0932 , \u0927\u094b \u0932\u0947", "1 \u0915\u092a \u091f\u092e\u093e\u091f\u0930 , \u092a\u094d\u092f\u0942\u0930\u0940 \u092c\u0928\u093e \u0932\u0947", "1 \u0915\u092a \u0926\u0939\u0940", "1 \u0907\u0902\u091a \u0926\u093e\u0932\u091a\u0940\u0928\u0940", "4 \u0907\u0932\u093e\u0907\u091a\u0940", "2 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0947 \u0932\u093f\u090f", "3 \u091f\u0939\u0928\u0940 \u092a\u0941\u0926\u0940\u0928\u093e , \u0915\u093e\u091f \u0932\u0947", "1/2 \u0915\u092a \u092a\u094d\u092f\u093e\u091c , \u092a\u0924\u0932\u093e \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947 \u0914\u0930 \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947"]'::jsonb, ARRAY['कप हरा बीन्स', 'कप गाजर', 'कप गोभी', 'कप आलू', 'पेस्ट बनाने के लिए', 'कली लहसुन', 'इंच अदरक', 'प्याज', 'हरी मिर्च', 'बिरयानी बनाने की सामग्री', 'कप चावल', 'कप टमाटर', 'कप दही', 'इंच दालचीनी', 'इलाइची', 'तेज पत्ता', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच लाल मिर्च पाउडर', 'छोटा चम्मच धनिया पाउडर', 'नमक', 'तेल', 'गार्निश के लिए', 'टहनी पुदीना', 'कप प्याज']::text[], '["\u0939\u0948\u0926\u0930\u093e\u092c\u093e\u0926\u0940 \u0935\u0947\u091c\u093f\u091f\u0947\u092c\u0932 \u092c\u093f\u0930\u092f\u093e\u0928\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u091a\u093e\u0935\u0932 \u0915\u094b 2 \u0915\u092a \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u0928\u092e\u0915 \u0914\u0930 \u0924\u0947\u0932 \u0915\u0947 \u0938\u093e\u0925 \u0938\u0949\u0938\u092a\u0948\u0928 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u091a\u093e\u0935\u0932 \u0915\u0947 \u0906\u0927\u093e \u092a\u0915\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947\u0964\u00a0\u00a0\u0905\u092c \u090f\u0915 \u0938\u094d\u091f\u0940\u092e\u0930 \u092e\u0947\u0902 \u0917\u093e\u091c\u0930, \u0939\u0930\u093e \u092c\u0940\u0928\u094d\u0938, \u0906\u0932\u0942, \u0917\u094b\u092d\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u0932\u0917 \u0907\u0938 \u0930\u0916 \u0932\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0939\u092e\u0928\u0926\u0938\u094d\u0924\u0947 \u092e\u0947\u0902 \u0907\u0932\u093e\u0907\u091a\u0940, \u0926\u093e\u0932\u091a\u0940\u0928\u0940, \u0932\u0949\u0928\u094d\u0917 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0940\u0938 \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u092c\u095c\u0947 \u0938\u0949\u0938\u092a\u0948\u0928 \u092e\u0947\u0902 2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902. \u0907\u0938\u092e\u0947\u0902 \u0932\u0939\u0941\u0938\u0928 \u092a\u094d\u092f\u093e\u091c \u0905\u0926\u0930\u0915 \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u092a\u093f\u0938\u093e \u0939\u0941\u0906 \u0926\u093e\u0932\u091a\u0940\u0928\u0940\u00a0\u092a\u093e\u0909\u0921\u0930, \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930 \u092a\u094d\u092f\u0942\u0930\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 5 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0926\u0939\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u0928\u0947 \u0926\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u0941\u0926\u0940\u0928\u093e \u0915\u0947 \u092a\u0924\u094d\u0924\u0947, \u0906\u0932\u0942, \u092a\u093e\u0915\u0940 \u0939\u0941\u0908 \u0938\u092c\u094d\u091c\u093f\u0906, \u0906\u0927\u093e \u092a\u0915\u0947 \u0939\u0941\u090f \u091a\u093e\u0935\u0932, \u092a\u0941\u0926\u0940\u0928\u093e \u0915\u0947 \u092a\u0924\u094d\u0924\u0947, \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930 \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u0915\u0940 \u0906\u0902\u091a \u0915\u092e \u0915\u0930\u0947\u0902, \u0938\u0949\u0938\u092a\u0948\u0928\u00a0\u0915\u094b \u0922\u0915\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092a\u0915\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0907\u0938\u0947 5 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0922\u0915\u0947 \u0930\u0939\u0928\u0947 \u0926\u0947.\u00a0\u0924\u0932\u0947 \u0939\u0941\u090f \u092a\u094d\u092f\u093e\u091c \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947.\u00a0\u0939\u0948\u0926\u0930\u093e\u092c\u093e\u0926\u0940 \u0935\u0947\u091c\u093f\u091f\u0947\u092c\u0932 \u092c\u093f\u0930\u092f\u093e\u0928\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u092c\u0941\u0930\u093e\u0928\u0940 \u0930\u093e\u092f\u0924\u093e \u0914\u0930 \u092e\u093f\u0930\u094d\u091a\u0940 \u0915\u0947\u00a0\u0938\u093e\u0932\u0928 \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 80, 'Hyderabadi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Vegetable_Hyderabadi_Biryani_Recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1193.Vegetable_Hyderabadi_Biryani_Recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Godhuma Rava Payasam - Dalia/Broken Wheat Payasam', 'godhuma-rava-payasam-dalia-broken-wheat-payasam', 'Godhuma Rava Payasam is a Dalia/Broken Wheat Payasam that is a Tamilian speciality prepared during festivals and celebrations. This particular payasam uses Broken Wheat and is a healthy alternative to the usual Rice Kheer. Instead of sugar, it also uses jaggery which is pumped with iron. This wholesome, satisfying kheer can be prepared in little time, making it a good option when your guests show up unexpectedly.', '["1/2 cup Broken Wheat (Dalia/ Godumai Rava)", "1 cup Jaggery , powdered", "1 tablespoon Yellow Moong Dal (Split)", "1 cup Milk , room temperature", "1/4 teaspoon Cardamom Powder (Elaichi)", "1/2 cup Water", "2 teaspoons Fresh coconut , grated (optional)", "1 teaspoon Ghee", "5-6 Cashew nuts"]'::jsonb, ARRAY['broken wheat', 'dalia/ godumai rava', 'jaggery', 'yellow moong dal', 'split', 'milk', 'cardamom powder', 'elaichi', 'water', 's fresh coconut', 'ghee', 'cashew nuts']::text[], '["To begin making the Godhuma Rava Payasam, place a wide pan on medium-low heat, dry roast the dalia until it is hot to touch.", "Do not over roast.", "This will take about 3-4 minutes approximately.", "Transfer it to a bowl and set aside.In the same pan, dry roast the moong dal till fragrant, for about 3-4 minutes.", "Mix the dalia and dal together, add it to a pressure cooker.", "Top it up with one cup of water and pressure cook it on a low to medium heat for up to 4 whistles.", "When the 4 whistles are done, turn the cooker off and allow the cooker to release all its pressure naturally.", "When you are able to open the lid easily, you will know the pressure has released.Add half cup of water to the powdered jaggery, in a mixing bowl.", "Dissolve it completely, then sieve the mixture to remove impurities.Place a wide pan on medium heat and add the jaggery water to it.", "Allow it to boil on a low heat for about 5 minutes.Add the cardamom powder and the cooked dalia and dal mixture, and pour it into the jaggery mix.Mix well to combine and allow them simmer for 3-4 minutes.Add the grated coconut at this stage, mix well and switch off.Then add milk and stir it in gradually.", "Heat a tadka pan with a teaspoon of ghee, add the broken cashews and saute till lightly brown and pour them over the prepared payasam.Mix well and serve the Godhuma Rava Payasam hot or chilled on any festive occasion.Serve\u00a0Godhuma Rava Payasam\u00a0along with a festive meal.", "You can also serve it\u00a0as dessert after a simple meal of\u00a0South Indian One Pot Sambar Rice Recipe\u00a0and\u00a0Palak Bhajia Recipe."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Uma_Raghuraman/Broken_Wheat_Kheer.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1194.Broken_Wheat_Kheer.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sprouted Green Gram Kosambari Recipe- With Pomegranates', 'sprouted-green-gram-kosambari-recipe-with-pomegranates', 'Sprouted Green Gram Kosambari is one of our favourite healthy salads, with the addition of sweet pomegranate pearls.', '["1 cup Green Moong Sprouts", "1/2 cup Carrots (Gajjar) , grated", "1/2 cup Fresh Pomegranate Fruit Kernels", "2 to 4 Green Chillies , chopped", "1 to 2 tablespoons Fresh coconut , grated (optional)", "2 sprig Coriander (Dhania) Leaves , chopped", "Lemon juice , as required", "Salt , to taste", "Oil , as required", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 pinch Asafoetida (hing)", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'green moong sprouts', 'carrot', 'curry leaves', 'coriander (dhania) leaves', 'lemon', 'pomegranate fruit kernels', 'green chillies', 'sunflower oil']::text[], '["To begin making the Sprouted Green Gram Kosambari recipe, we need to keep the green moong sprouts ready.", "We can either use store bought Sprouts or learn\u00a0How to make Sprouts at Home.", "In a big bowl, combine the\u00a0 sprouted moong, grated carrot, pomegranate, green chillies, grated coconut, coriander leaves, salt and lime.In a tadka pan heat\u00a0oil on medium flame and once it''s hot add mustard seeds.", "When they splutter, add in the asafoetida.", "Turn off the flame.", "Pour the tempering on the Sprouted Green Gram Kosambari.", "Healthy, nutritious and delicious Sprouted moong salad is ready to serve.Serve\u00a0Sprouted Green Gram Kosambari\u00a0along with\u00a0Tomato Onion Sambar\u00a0and\u00a0Steamed Rice\u00a0and Raw Papaya Thoran Recipe\u00a0for a weekday meal."]'::jsonb, 25, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Smitha_Kalluraya/SPROUTED_GREEN_GRAM_KOSAMBARI_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1195.SPROUTED_GREEN_GRAM_KOSAMBARI_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ridge Gourd Peel Chutney Recipe', 'ridge-gourd-peel-chutney-recipe', 'The nutritive peels of the humble Ridge gourd (Dodka) can be used to make a quick, lip smacking chutney. Sesame can be added along with the ridge gourd for an extra crunch, and to increase the health quotient of the chutney. Flax seeds can be another addition to increase the nutritive value of the chutney.', '["6 Ridge Gourd Skin (Turai/ Peerkangai)", "1 tablespoon Sesame seeds (Til seeds) , roasted", "1 teaspoon Red Chilli powder", "1 teaspoon Sugar", "1/2 teaspoon Cumin seeds (Jeera)", "2 teaspoon Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'ridge gourd skin (turai peerkangai)', 'red chilli powder', 'sugar', 'cumin seeds (jeera)', 'sesame seeds (til seeds)', 'sunflower oil']::text[], '["To begin making the Ridge Gourd Peel chutney, roughly chop the peels of the ridge gourd.Heat 1 teaspoon oil in a pan, stir and roast the peels in the oil till the moisture evaporates and they become crisp.", "Alternatively, you can also microwave the peels with oil for about 1-1/2 minutes.Let the roasted ridge gourd peels cool down and then coarsely grind them in a mixer grinder.Heat the remaining oil in the pan and add cumin seeds, and once they start to sizzle, add the roasted sesame seed and allow it to crackle.Add the ground Ridge gourd peels and red chilli powder to the oil and stir for a minute, turn off the heat, add salt and sugar, and mix well and serve warm.Serve the Ridge Gourd Peel chutney as a side dish along with\u00a0Phulka\u00a0or\u00a0Steamed rice,\u00a0Maharashtrian Aloo Bhujne and\u00a0Pumpkin Dal with Garlic Tadka \u00a0."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Ridge_Gourd_Peel_chutney.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1196.Ridge_Gourd_Peel_chutney.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('मेथी मूंग दाल रेसिपी - Methi Moong Dal Recipe', 'methi-moong-dal-recipe', 'मेथी मूंग दाल रेसिपी एक स्वाद से भरपूर दाल है जिसमे दाल के साथ मेथी का प्रयोग किया गया है. मेथी में आयरन की मात्रा बहुत अधिक होती है इसलिए इसे अपने रोज के खाने में शामिल करना चाइये। यह एक सरल दाल है जिसे आप अपने रोज के खाने के लिए बना सकते है.', '["1 \u0915\u092a \u092a\u093f\u0932\u0940 \u092e\u0942\u0902\u0917 \u0926\u093e\u0932 , \u0938\u094d\u092a\u094d\u0932\u093f\u091f", "\u092e\u0947\u0925\u0940 , \u0925\u094b\u095c\u093e, \u0915\u093e\u091f \u0932\u0947", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0940\u0902\u0917", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1 \u092a\u094d\u092f\u093e\u091c , \u092a\u0924\u0932\u093e \u0914\u0930 \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "1 \u091f\u092e\u093e\u091f\u0930 , \u0915\u093e\u091f \u0932\u0947", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932"]'::jsonb, ARRAY['कप पिली मूंग दाल', 'मेथी', 'छोटा चम्मच हींग', 'छोटा चम्मच जीरा', 'प्याज', 'टमाटर', 'छोटे चम्मच धनिया पाउडर', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच लाल मिर्च पाउडर', 'नमक', 'छोटे चम्मच तेल']::text[], '["\u092e\u0947\u0925\u0940 \u092e\u0942\u0902\u0917 \u0926\u093e\u0932 \u0930\u0947\u0938\u093f\u092a\u0940 \u0915\u094b \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092e\u0942\u0902\u0917 \u0926\u093e\u0932 \u0915\u094b 3 \u0915\u092a \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 30 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0938\u094b\u0916 \u0932\u0947. \u0905\u092c \u092e\u0947\u0925\u0940 \u0915\u094b \u092d\u0940 \u0927\u094b \u0915\u0930 \u0938\u0942\u0916\u093e \u0932\u0947. \u092e\u0947\u0925\u0940 \u0915\u094b \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u092e\u0947\u0925\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u0947\u0925\u0940 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u092e\u0947\u0925\u0940 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0939\u0940\u0902\u0917, \u091c\u0940\u0930\u093e \u0921\u093e\u0932\u0947\u00a0\u0914\u0930\u00a0\u091c\u0940\u0930\u093e \u0915\u0947 \u0924\u095c\u0915\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092e\u0942\u0902\u0917 \u0926\u093e\u0932 \u0914\u0930 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0915\u0941\u0915\u0930 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947. 2 \u0938\u0947 3 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0917\u0948\u0938 \u0915\u0940 \u0906\u0902\u091a \u0927\u0940\u092e\u0940 \u0915\u0930\u0947\u0902 \u0914\u0930 5 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u094d\u0930\u0947\u0936\u0930 \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947. \u0915\u0941\u0915\u0930 \u0916\u094b\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u092a\u0930\u094b\u0938\u0947.\u00a0\u092e\u0947\u0925\u0940 \u092e\u0942\u0902\u0917 \u0926\u093e\u0932 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0905\u091c\u0935\u093e\u0907\u0928 \u091f\u092e\u093e\u091f\u0930 \u092d\u093f\u0902\u0921\u0940,\u00a0\u092b\u0941\u0932\u094d\u0915\u093e\u00a0\u0914\u0930\u00a0\u0932\u094c\u0915\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Methi_Moong_Dal_Palak_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1197.Methi_Moong_Dal_Palak_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Achari Masala Puri Recipe', 'achari-masala-puri-recipe', 'The Achari Masala Puri Recipe is a delicious recipe of the Indian Puri that is spiced with achar masala or even a pickle masala. All you have to do is combine the pickle into the wheat flour and make a dough and fry it. It makes a great snack as it is and even adds a twist to the regular Puri.', '["2 cups Whole Wheat Flour", "3 tablespoons Achari masala", "1 teaspoon Ajwain (Carom seeds)", "1 teaspoon Red Chilli powder", "1 teaspoon Black pepper powder", "Salt , to taste", "Oil , for deep frying"]'::jsonb, ARRAY['salt', 'achari masala', 'wheat flour', 'ajwain (carom seeds)', 'red chilli powder', 'black pepper powder', 'sunflower oil']::text[], '["To begin making the Achari Masala Puri Recipe, first get all the ingredients ready.", "If you don''t have achar masala you can also use a few tablespoons of the ready mango pickle to make the puris, it will give a great taste.In a large mixing now, add all the ingredients except the oil.", "Combine all the ingredients well, add a tablespoon of oil and add little water at a time to make a smooth firm puri dough.", "Add a little oil on the top and knead more to make a smooth dough.Preheat the oil for deep frying the puris in a deep frying pan.", "Divide the puris into 20 small portions and roll the puri dough on an oiled surface into a 3 inch diameter circle.Deep fry the Achari Masala Puri until it puffs up and gets golden brown in color.", "Once done, drain from the oil and serve.", "Proceed the same way to make the remaining puris.Serve the Achari Masala Puri along with a Urulai Kizhangu Masiyal Recipe (Lemony Potato Curry) and Paka Kela Raita for a weekend breakfast, lunch or a weeknight dinner."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breads/Achari_Masala_Puri_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1198.Achari_Masala_Puri_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Karela Kadhi Recipe', 'karela-kadhi-recipe', 'Kadhi is a comfort food for all seasons. Kadhi chawal is one of its best combinations and Karela Kadhi Recipe is a kadhi made with bitter gourd.', '["1 cup Curd (Dahi / Yogurt)", "1 teaspoon Gram flour (besan)", "1-1/2 cups Water", "Salt , to taste", "2 Karela (Bitter Gourd/ Pavakkai) , de skinned, sliced", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1/2 Onion , finely chopped", "3 Green Chillies , crushed to paste", "1/2 inch Ginger , crushed to paste"]'::jsonb, ARRAY['salt', 'mustard seeds', 'water', 'gram flour (besan)', 'curd', 'curry leaves', 'onion', 'cumin seeds (jeera)', 'green chillies paste', 'ginger paste', 'karela (bitter gourd pavakkai) de skinned']::text[], '["To prepare Karela Kadhi Recipe, whisk together curd, water and besan well making sure no lumps are formed.", "Keep it aside.Slice bitter gourd, soak them in salted water until use, this will remove some of the bitterness from the gourd.Heat oil in a heavy bottomed pan.", "Add mustard seeds, cumin seeds and let it splutter.", "Add onions and saut\u00e9 until translucent.", "Once the onions are soft and translucent, add curry leaves, green chilli, garlic paste and saut\u00e9 until there is no raw smell of ginger left.Add sliced bitter gourd and saut\u00e9 for about 5 to 7 minutes.", "Add salt to taste.Finally, add besan yogurt mix and stir.", "Simmer and let it cook until you it begins to boil.", "Once done, switch off the heat and serve.Serve\u00a0Karela Kadhi Recipe\u00a0along with\u00a0Jeera Rice,\u00a0Phulka,\u00a0Bharwa Besan Mirch\u00a0and\u00a0Kachumber Salad\u00a0for a weekday meal."]'::jsonb, 30, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/Karela_Kadhi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1199.Karela_Kadhi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Jeera Milagu Rasam Recipe  - South Indian Pepper Cumin Rasam', 'jeera-milagu-rasam-recipe-south-indian-pepper-cumin-rasam', 'The Jeera Milagu Rasam Recipe also known as the Pepper Rasam is a very classic dish of the South Indian Cuisine. This rasam is simmered with tamarind water along with freshly pounded pepper, cumin and a tempering with ghee. A lot of times this rasam is given when one is suffering from a cold or sore throat making it very soothing because of the black pepper.', '["30 grams Tamarind , soaked in hot water", "1 teaspoon Whole Black Peppercorns , coarsely pounded", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Black pepper powder", "1/4 teaspoon Turmeric powder (Haldi) , optional", "Salt , to taste", "1 teaspoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'ghee', 'mustard seeds', 'black peppercorns', 'curry leaves', 'cumin seeds (jeera)', 'black pepper powder', 'tamarind', 'turmeric powder']::text[], '["To begin making the Jeera Milagu Rasam - Pepper Rasam Recipe, first extract the pulp from the tamarind and combine it with 3 to 3-1/2 cups of water to give diluted tamarind water.Heat ghee in a saucepan over medium heat; add the mustard seeds, cumin seeds and allow it to crackle.", "Add the curry leaves, pounded black peppercorns, cumin powder, black pepper powder, turmeric powder, tamarind water and salt.Stir the mixture and give it a brisk boil for 3 to 4 minutes until the raw taste from the tamarind water goes away.You can add more water, pepper and cumin if you find the water too tangy.Once done, turn off the heat and serve Jeera Milagu Rasam hot.", "Serve the Jeera Milagu Rasam along with\u00a0Cabbage Poriyal (Muttaikose)\u00a0and\u00a0Steamed Rice\u00a0for a quick weeknight dinner."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/admin/Jeera_Milagu_Rasam_Recipe___South_Indian_Pepper_Cumin_Rasam.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1200.Jeera_Milagu_Rasam_Recipe___South_Indian_Pepper_Cumin_Rasam.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false);

INSERT INTO public.recipes (
  title, slug, description, ingredients, cleaned_ingredients,
  instructions, total_time_mins, cuisine, diet, source_url,
  image_url, image_status, image_source, data_source, servings, review_count, is_featured
) VALUES
  ('Banana Stem Poriyal Recipe With Curry Powder', 'banana-stem-poriyal-recipe-with-curry-powder', 'Banana Stem Sabzi Recipe With Curry Powder is a semi dry sabzi that is made by stir frying the banana stem. A touch of yogurt to add in a tinge of sourness, South Indian curry powder, cumin powder and chilli powder are added to make it flavourful.', '["1 Banana Stem , outer layer removed and chopped", "1 Onion , chopped", "1-1/2 teaspoons Red Chilli powder", "1-1/2 teaspoons Curry powder", "1 pinch Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera)", "2 teaspoons Curd (Dahi / Yogurt)", "Salt , to taste", "2 teaspoons Gram flour (besan)", "2 teaspoons Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "2 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'mustard seeds', 'red chilli powder', 'gram flour (besan)', 'curd', 'curry leaves', 'onion', 'curry powder', 'banana stem outer layer', 'cumin seeds (jeera)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making\u00a0Banana Stem Sabzi Recipe With Curry Powder, prep all the ingredients first.", "Then make cuts on the layer of banana stem and then discard the outer covering.Slice the banana stem and as you do, you will find the fibre coming out every time you slice into stem, keep taking them out while proceeding.", "Once sliced, take each slice and chop them to about 1 cm pieces.Take a kadai and heat cooking oil in it.", "Once the oil is hot, add the mustard seeds and allow them to splutter.", "Once they do splutter, add in the cumin seeds and allow to sizzle.Add curry leaves immediately and saute for a bit on medium heat till the curry leaves crisp up a bit.Add the chopped onions, and keep sauteing on medium heat until they turn translucent.Add in the chopped banana stem pieces and cook with a bit of water.", "Cook covered till the banana stem is softened and cooked.", "You can opt to undercook the banana stem as well, depending on your preference.", "The sabzi will be crunchier if the stem is undercooked.Once done, add the spices, cumin powder, curry powder or sambar powder, red chilli powder, besan (adding besan is optional.", "I used it to soak the extra water added), salt and give a nice stir till combined.Keep on medium heat for 1-2 minutes, check for seasoning and adjust.", "Switch off heat.Serve\u00a0Banana Stem Sabzi Recipe With Curry Powder along with\u00a0Lobia Masala Recipe (Black Eyed Bean Curry),\u00a0Phulka\u00a0and\u00a0Indian Vegetable Salad Recipe\u00a0for lunch or dinner."]'::jsonb, 30, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Banana_Stem_Palya_Bale_Thindina_Subzi_Dry_Recipe-8598.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1201.Banana_Stem_Palya_Bale_Thindina_Subzi_Dry_Recipe-8598.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Tomato Rice - Tomato Pulihora Recipe', 'spicy-tomato-rice-tomato-pulihora-recipe', 'The Tomato Pulihora Recipe is an authentic andhra recipe where plain rice is flavoured with spices and tangy ingredients and spiced along with bisi bele bath powder.', '["2-1/2 cups Cooked rice", "3 Tomatoes", "3 teaspoons Bisi Bele Bhat Spice Powder", "Salt , to taste", "1 teaspoon Chana dal (Bengal Gram Dal)", "1 teaspoon White Urad Dal (Split)", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 Green Chilli", "1 Dry Red Chilli", "2 teaspoons Cashew nuts , or peanuts", "1-1/2 tablespoons Oil , or as needed", "1/2 teaspoon Asafoetida (hing)"]'::jsonb, ARRAY['tomato', 'salt', 'green chilli', 'rice', 'mustard seeds', 'asafoetida (hing)', 'dry red chilli', 'cashew nuts peanuts', 'white urad dal (split)', 'cumin seeds (jeera)', 'chana dal (bengal gram dal)', 'bisi bele bhat spice powder', 'sunflower oil']::text[], '["To begin making the Spicy Tomato Rice | Tomato Pulihora Recipe, chop the tomatoes roughly.", "In a mixer grinder, blend them into a smooth puree.Incase, the bisibele bhath masala.powder isn''t ready, preparing Bisi Bele Bath Spice Powder takes roughly 10-15 min additionally.", "To a large wok or kadai heat the cooking oil.", "Once the oil is hot, add the chana dal, urad dal, cashewnuts (or peanuts if using) and roast for 10-20 seconds or till they are a bit browned and appears done.Next, add in the cumin, mustard , green chilly and red chilli, asafoetida and the curry leavesNow that the tadka is done, add in the tomato puree to the kadai carefully avoiding any possible splutter on your hands.Add in bisibele bhath masala powder, salt and mix well.Let this mixture cook for about 7-8 minutes until you notice oil leaving the sides of the pan or until you notice the tomato pulp reduces slightly and thickens up.", "It is then time to turn off the heat.Transfer this to a wide bowl, add the cooked rice and mix gently until all the ingredients are well combined.", "Adjust the salt levels if needed.Serve\u00a0Spicy Tomato Rice | Tomato Pulihora Recipe with a bowl of\u00a0Yogurt (Curd),\u00a0Andhra Style Paruppu Podi Recipe (Dal Podi),\u00a0Indian Vegetable Salad Recipe\u00a0for a complete meal."]'::jsonb, 15, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/b.yojana-gmail.com/Spicy_Thakkali_Rice_Tomato_Pulihora-1_edited.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1202.Spicy_Thakkali_Rice_Tomato_Pulihora-1_edited.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Methi And Palak Paratha Recipe', 'methi-and-palak-paratha-recipe', 'Methi and Palak Paratha Recipe is a wholesome Indian Flat bread that is made by kneading the dough with the spinach and methi leaves. Adding greens to the paratha is a great way to incorporate an additional green vegetable into your daily meal. It is also a great way to use leftover vegetables from the previous meal by binding dough to make parathas. Serve Methi and Palak Paratha for breakfast along with curd and pickle. These parathas can be packed for the kids school lunch box as well.', '["2 cups Whole Wheat Flour", "Methi Leaves (Fenugreek Leaves) , a bunch, roughly chopped", "Spinach Leaves (Palak) , roughly chopped", "1 Onion , finely chopped", "4 cloves Garlic , grated", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1/2 teaspoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Chaat Masala Powder", "2 tablespoons Oil", "Salt , to taste", "Water , to bind the dough"]'::jsonb, ARRAY['salt', 'wheat flour', 'cumin powder (jeera)', 'sunflower oil', 'chaat masala powder', 'red chilli powder', 'cloves garlic', 'water bind the dough', 'onion', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'spinach leaves (palak)', 'methi leaves (fenugreek leaves) bunch']::text[], '["To begin making the Methi and Palak Paratha Recipe, in a pan heat oil over medium heat.", "Add the cumin seeds and allow them to sputter.", "Next add the chopped onions and grated garlic, fry until fragrant.When the onions turn light brown in color, add the turmeric powder and red chilli powder.", "Saut\u00e9 for a minute or so.", "Then add the cumin powder, coriander powder and saut\u00e9 again for few seconds.Add the chopped spinach and methi along with salt and chaat masala.", "Stir to combine and cook the greens over medium flame.", "The greens will immediately release water, so keep stirring until they are fully cooked and the water evaporates completely.", "Turn off the heat, transfer spinach and methi leaves to a bowl and set aside to cool completely.In a large bowl, add the whole wheat flour along with cooked spinach and methi mixture.", "Gently rub the greens and flour with your fingers.Using little water at a time knead it together to make a firm and smooth dough.", "Drizzle a teaspoon oil on the top and knead until the dough is smooth but not sticky.To make the parathas, divide the dough into 8-10 portions of equal size.", "Roll each portion out into a flat paratha about 6-7 inches in diameterOur next step is to cook the paratha; for this preheat a skillet (Roti Tawa).", "When the tawa is hot; place the rolled out paratha in the skillet and cook for a minute on both sides until you notice a few brown spots appear on both sides."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breads/Methi_and_Palak_Parathas_Recipe_Spinach_Fenugreek_Leaves.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1203.Methi_and_Palak_Parathas_Recipe_Spinach_Fenugreek_Leaves.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('परवल मसाला रेसिपी - Parwal Masala Recipe', 'parwal-masala-recipe', 'परवल एक ऐसी सब्ज़ी है जिसे रोज के खाने के लिए बनाया जाता है. परवल मसाला एक ग्रेवी रेसिपी है जिसमे परवल को पैन फ्राई करके टमाटर, अदरक,  तरबूज़ और दूसरे मसालो के साथ पकाया जाता है.', '["300 \u0917\u094d\u0930\u093e\u092e \u092a\u0930\u0935\u0932 , \u091b\u0940\u0932\u0915\u0930 \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "2 \u091f\u092e\u093e\u091f\u0930 , \u0915\u093e\u091f \u0932\u0947", "3 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u0930\u092c\u0942\u095b", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932"]'::jsonb, ARRAY['ग्राम परवल', 'टमाटर', 'छोटे चम्मच तरबूज़', 'इंच अदरक', 'छोटा चम्मच लाल मिर्च पाउडर', 'छोटा चम्मच धनिया पाउडर', 'छोटा चम्मच जीरा पाउडर', 'छोटा चम्मच गरम मसाला पाउडर', 'तेज पत्ता', 'नमक', 'छोटा चम्मच तेल']::text[], '["\u092a\u0930\u0935\u0932 \u092e\u0938\u093e\u0932\u093e \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u092a\u0930\u0935\u0932 \u0915\u094b \u0927\u094b \u0915\u0930 \u091b\u0940\u0932 \u0932\u0947. \u0906\u0927\u093e \u0915\u093e\u091f \u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u0905\u092c \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0905\u0926\u0930\u0915, \u091f\u092e\u093e\u091f\u0930, \u0924\u0930\u092c\u0942\u095b \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u092a\u0930\u0935\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u0909\u0938\u0940 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e, \u091f\u092e\u093e\u091f\u0930 \u0905\u0926\u0930\u0915 \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 3 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a04 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930, \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. 3 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u0928\u0947 \u0926\u0947 \u0914\u0930 \u0907\u0938\u0915\u0947 \u092c\u093e\u0926 \u092a\u0930\u0935\u0932, \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0915\u0928\u0947 \u0926\u0947. 5 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u093e\u090f, \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947.\u00a0\u092a\u0930\u0935\u0932 \u092e\u0938\u093e\u0932\u093e \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0924\u0935\u093e \u092a\u0930\u093e\u0920\u093e\u00a0\u0914\u0930\u00a0\u0932\u094c\u0915\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/basic_recipes/No_onion_no_gralic_Parwal_Masala_recipe_6_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1204.No_onion_no_gralic_Parwal_Masala_recipe_6_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ragi & Whole Wheat Halwa Recipe - Finger Millet Pudding', 'ragi-whole-wheat-halwa-recipe-finger-millet-pudding', 'Ragi Halwa or Finger Millet Pudding is a delicious alternative to the Wheat Flour Pudding / Gehun Ka Halwa that we make at home. The distinct taste of the finger millet along with the ghee and almonds make it nutritious and wholesome too.', '["1/2 cup Whole Wheat Flour", "1/2 cup Ragi Flour (Finger Millet/ Nagli)", "1 cup Ghee", "1 cup Sugar", "1/4 teaspoon Cardamom Powder (Elaichi)", "1/4 cup Whole Almonds (Badam) , blanched, peeled and slivered", "1 1/2 cups Water"]'::jsonb, ARRAY['whole wheat flour', 'ragi flour', 'finger millet/ nagli', 'ghee', 'sugar', 'cardamom powder', 'elaichi', 'whole almonds', 'badam', 's water']::text[], '["To make the Ragi Halwa Recipe, melt the ghee in a heavy bottomed pan on medium heat; add both the ragi and wheat flours into the ghee.Stir them along with the ghee on low heat until you get a roasted aroma.This takes about 10 minutes and sometimes more.", "Please avoid turning the heat to high to fasten the process.", "The slow process helps in gradual cooking of the halwa.In the mean while, in another sauce pan; dissolve the water and sugar.", "Stir in the cardamom powder to this.", "After about 10 minutes and the roasted aromas come out, add in the hot sugar water mixture to the four mix and stir continuously for about 2 minutes or till the water is all absorbed into the flour.Once absorbed, add a tablespoon of more ghee and keep stirring for another 5 minutes until you get the flavors and the right texture.The texture of the halwa is a little course and not gooey.", "Turn off the heat, transfer to a serving bowl and serve the Ragi Halwa with the almondsServe the\u00a0Ragi Halwa or Finger Millet Pudding as a dessert for any festival or also as a\u00a0Party dessert.Note\u00a0Take care to ensure that the flour does not get burnt, hence keep the flame low and stir constantly."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Ragi_Halwa_Finger_Millet_Pudding-2838.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1205.Ragi_Halwa_Finger_Millet_Pudding-2838.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Idli Dosa Milagai Podi Recipe - South Indian Chilli Chutney Powder', 'idli-dosa-milagai-podi-recipe-south-indian-chilli-chutney-powder', 'Idli Dosa Milagai Podi or Chilli Chutney Powder is traditionally used in south indian homes and served along with Idlis and Dosas. It is used as a substitute to chutneys or sambar to accompany breakfast dishes like idli or dosai. This powder can be stored in airtight container for days and can be used for multiple purposes. This Podi can be used instead of chilly powder while making other vegetable curry also.', '["1 cup White Urad Dal (Whole)", "1 cup Chana dal (Bengal Gram Dal)", "1/2 cup Sesame seeds (Til seeds)", "2 tablespoons Coriander (Dhania) Seeds", "2 tablespoons Red Chilli powder", "1 tablespoon Asafoetida (hing)", "2 tablespoons Salt"]'::jsonb, ARRAY['white urad dal', 'whole', 'chana dal', 'bengal gram dal', 'sesame seeds', 'til seeds', 's coriander', 'dhania', 's red chilli powder', 'asafoetida', 'hing', 's salt']::text[], '["To begin making the Idli Dosa Chutney Powder Recipe, in a heavy bottomed pan; roast the urad dal and chana dal separately on medium to low heat until lightly browned and crisp.", "When you take a bite, the dals should have a crunch.", "Transfer onto a plate to cool and keep aside.In the same pan, roast the sesame seeds and coriander seeds until the sesame seeds sputters and transfer to a plate to cool and keep aside.If you are adding the dry red chillies, roast the red chillies until browned and keep aside.Once all the ingredients are cooled in a food processor grind all the ingredients in batches or together to form a coarse powder.Finally stir in the asafoetida, salt and red chilli powder .if you used dry red chillies this would have been ground with the lentils.Store the Idli Dosa Chutney Powder - Milagai Podi air tight containers and use as and when required.Serve\u00a0Idli Dosa Milagai Podi\u00a0with\u00a0Homemade Soft Idli Recipe\u00a0or\u00a0Ghee Roast Dosa Recipe\u00a0for breakfast."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/1-Archana/Homemade_Idli_Milagai_Podi_Powder_Video_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1206.Homemade_Idli_Milagai_Podi_Powder_Video_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Peanut Chutney Recipe With Tomatoes', 'andhra-style-peanut-chutney-recipe-with-tomatoes', 'Andhra Pradesh is famous for its spicy powders and chutneys. This Andhra Style Peanut Chutney also known as Palli Pachadi  is high in protein chutney and makes for a healthy side dish with idli, dosa and even paranthas.', '["1 cup Roasted Peanuts (Moongphali) , with skin removed", "3 cloves Garlic", "2 Tomatoes , finely chopped", "5 Dry Red Chillies", "1 teaspoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "Salt , to taste"]'::jsonb, ARRAY['peanuts (moongphali) skin', 'tomato', 'salt', 'mustard seeds', 'cloves garlic', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'sunflower oil']::text[], '["To begin making the Andhra Style Peanut Chutney Recipe, on a low heat, dry roast the peanuts and red chillies together till the peanuts are fragrant and browned.", "Keep stirring so that they don''t burn.Also always split your chilies in half before roasting or frying to prevent the sudden sputtering.Once the peanuts and chilies are roasted, keep aside to cool.In about a cup of boiling water, blanch the tomatoes for about 5 minutes, slit the tomatoes slightly at the end so that it''s easier to peel.", "Peel the blanched tomatoes and keep aside to cool.Once peanuts and tomatoes are cool, Add them to a mixer grinder along with garlic and salt and blend well to make the chutney.", "Add a little water if required.", "Check the salt and adjust to suit your taste.", "Transfer the Peanut Chutney to a bowl.The final step is to make the Tadka.In a small pan, heat oil and add mustard seeds and allow them to splutter.", "Once they splutter, add the urad dal and curry leaves.", "Saute for about 1-2 minutes till the dal is browned and crunchy.Add the Tadka to the Peanut Chutney and serve.Serve the Andhra Style Peanut Chutney with Ragi Idli  or Ghee Masala Dosa Recipe\u00a0for a wholesome breakfast."]'::jsonb, 30, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Monika_Manchanda/Peanut_Chutney.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1207.Peanut_Chutney.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('बंगाली आलू दम रेसिपी - Bengali Aloo Dum Recipe', 'bengali-aloo-dum-recipe-2', 'बंगाली आलू दम रेसिपी एक स्वाद से भरपूर रेसिपी है जिसमे आलू को टमाटर, प्याज और लहसुन के साथ पकाया जाता है. इसमें आलू को करी में 30 मिनट के लिए पकाया जाता है ताकि आलू अच्छी तरह से ग्रेवी सोख ले.', '["200 \u0917\u094d\u0930\u093e\u092e \u091b\u094b\u091f\u0947 \u0906\u0932\u0942 , \u0909\u092c\u093e\u0932\u0915\u0930 \u091b\u093f\u0932\u094d\u0915\u093e \u0928\u093f\u0915\u093e\u0932 \u0932\u0947", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "2 \u0907\u0932\u093e\u0907\u091a\u0940", "1 \u0907\u0902\u091a \u0926\u093e\u0932\u091a\u0940\u0928\u0940", "2 \u0932\u0949\u0928\u094d\u0917", "1 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e", "1/2 \u0915\u092a \u091f\u092e\u093e\u091f\u0930 \u092a\u094d\u092f\u0942\u0930\u0940", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "1/2 \u0915\u092a \u0926\u0939\u0940", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0936\u0915\u094d\u0915\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "1 \u0938\u094d\u091f\u0949\u0915 \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "\u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f", "1 \u092a\u094d\u092f\u093e\u091c , \u0915\u093e\u091f \u0932\u0947", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u0915\u093e\u091f \u0932\u0947", "3 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0915\u093e\u091f \u0932\u0947"]'::jsonb, ARRAY['ग्राम छोटे आलू', 'छोटे चम्मच हल्दी पाउडर', 'इलाइची', 'इंच दालचीनी', 'लॉन्ग', 'तेज पत्ता', 'कप टमाटर प्यूरी', 'छोटा चम्मच गरम मसाला पाउडर', 'कप दही', 'छोटा चम्मच लाल मिर्च पाउडर', 'छोटा चम्मच धनिया पाउडर', 'छोटा चम्मच शक्कर', 'नमक', 'तेल', 'स्टॉक हरा धनिया', 'पेस्ट बनाने के लिए', 'प्याज', 'इंच अदरक', 'कली लहसुन', 'हरी मिर्च']::text[], '["\u092c\u0902\u0917\u093e\u0932\u0940 \u0906\u0932\u0942 \u0926\u092e \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u092c\u094d\u0932\u0947\u0902\u0921\u0930 \u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c, \u0905\u0926\u0930\u0915, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0932\u0939\u0938\u0941\u0928 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0909\u092c\u0932\u0947 \u0939\u0941\u090f \u0906\u0932\u0942, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0938\u0941\u0928\u0939\u0930\u093e \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0909\u0938\u0940 \u0924\u0947\u0932 \u092e\u0947\u0902 \u0925\u094b\u095c\u093e \u0914\u0930 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c, \u0905\u0926\u0930\u0915, \u0932\u0939\u0938\u0941\u0928 \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0947\u0938\u094d\u091f \u0915\u094b 4\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0926\u093e\u0932\u091a\u0940\u0928\u0940, \u0932\u0949\u0928\u094d\u0917, \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u091f\u092e\u093e\u091f\u0930 \u0915\u0940 \u092a\u094d\u092f\u0942\u0930\u0940, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0926\u0939\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.1 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0906\u0932\u0942, \u0936\u0915\u094d\u0915\u0930, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u0915\u095d\u093e\u0908 \u0915\u094b \u0922\u0915 \u0932\u0947. 20 \u092e\u093f\u0928\u091f \u0924\u0915 \u0927\u0940\u092e\u0940 \u0906\u0902\u091a \u092a\u0930\u00a0\u092a\u0915\u0928\u0947 \u0926\u0947. \u092c\u093f\u091a \u092c\u093f\u091a \u092e\u0947\u0902 \u092e\u093f\u0932\u0924\u0947 \u0930\u0939\u0947 \u0924\u093e\u0915\u093f \u092e\u0938\u093e\u0932\u093e \u0928\u093f\u091a\u0947 \u091a\u093f\u092a\u0915\u0947 \u0928\u0939\u0940\u0902\u096420 \u092e\u093f\u0928\u091f \u092c\u093e\u0926 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902, \u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u0947 \u0938\u0947 \u0917\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092c\u0902\u0917\u093e\u0932\u0940 \u0906\u0932\u0942 \u0926\u092e \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u092c\u0902\u0917\u093e\u0932\u0940 \u0932\u0941\u091a\u094d\u091a\u0940,\u00a0\u091b\u094b\u0932\u093e\u0930 \u0926\u093e\u0932\u00a0\u0914\u0930\u00a0\u0932\u094c\u0915\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 70, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Bengali_Aloo_Dum_Recipe-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1208.Bengali_Aloo_Dum_Recipe-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chow Chow Poricha Kootu Recipe', 'chow-chow-poricha-kootu-recipe', 'Chow Chow Kootu is made from a white squash called chow chow. It is combined with moong lentils, ground coconut, cumin, yogurt and curry leaves to form its delicious gravy base. The taste is fantastic and goes well with hot phulkas or Spicy Potato Roast Recipe (Urulaikizhangu Poriyal) and steamed hot rice. So enjoy cooking this delicate preparation of a chow chow kotu, which is simple and delicious and makes a one dish healthy meal. Alternate vegetables that can be used are chayote squash, bottle gourd, white pumpkin.', '["300 grams Chayote , diced", "1/2 cup Yellow Moong Dal (Split) , cooked", "1/4 teaspoon Turmeric powder (Haldi)", "Ingredients to be ground", "1/2 cup Fresh coconut", "4 Dry Red Chillies", "1 teaspoon Cumin seeds (Jeera)", "Curry leaves", "Salt , to taste", "Ingredients for seasoning", "1 sprig Curry leaves", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Oil", "1 teaspoon White Urad Dal (Split)", "1 teaspoon Chana dal (Bengal Gram Dal)"]'::jsonb, ARRAY['s chayote', 'yellow moong dal', 'split', 'turmeric powder', 'haldi', 'ingredients to be ground', 'fresh coconut', 'dry red chillies', 'cumin seeds', 'jeera', 'curry leaves', 'salt', 'ingredients for seasoning', 'mustard seeds', 'rai/ kadugu', 'oil', 'white urad dal', 'chana dal', 'bengal gram dal']::text[], '["To begin making the Chow Chow Poricha Kootu Recipe; we will first cook the moong dal lentils with about 2 cups of water in a saucepan or a pressure cooker, along with a 1/4 teaspoon of turmeric powder.Once cooked completely, whisk it using a fork.", "See Video recipe of of to cook lentils in a pressure cookerSteam the chow-chow, by adding just a little salt, until tender and cooked.Grind together the grated coconut, cumin seeds, curry leaves and the red chilli into a smooth paste.", "Use warm water for grinding, this will help the coconut blend well with the chillies.Heat oil in a\u00a0heavy bottomed pan; add the mustard seeds, bengal gram and halved white urad dal and allow them to crackle.", "Allow the dal to roast well until lightly browned.Stir in the cooked lentils, the cooked vegetables and curry leaves and saut\u00e9 for a few minutes.", "Add a little water to adjust the consistency of the chow chow Poricha Kootu.", "Check the salt levels and adjust to suit your taste.Serve the\u00a0Chow Chow Poricha Kootu Recipe along with steamed rice and\u00a0Vathal Kozhambu\u00a0or\u00a0with hot\u00a0phulkas\u00a0or\u00a0Spicy Potato Roast Recipe (Urulaikizhangu Poriyal)."]'::jsonb, 45, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/3-april/Chow_Chow_Poricha_Kootu_Recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1209.Chow_Chow_Poricha_Kootu_Recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('मिनी इडली उपमा रेसिपी - Mini Idli Upma Recipe', 'mini-idli-upma-recipe', 'इडली उपमा बहुत ही आसान है. इसमें इडली को काटकर रोज के मसलो के साथ पकाया जाता है और यह एक अच्छा तरीका है बची हुई इडली का प्रयोग करने के लिए. यहाँ हमने छोटी इडली का प्रयोग किया जाता है लेकिन आप बड़ी इडली को काटकर भी यह उपमा बना सकते है. इसमें हरी मिर्च और प्याज का भी प्रयोग किया जाता है, जो इसे और भी स्वादिष्ट बनाता है.', '["20 \u0907\u0921\u0932\u0940 , \u092e\u093f\u0928\u0940 \u0907\u0921\u0932\u0940", "10 \u092a\u094d\u092f\u093e\u091c , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0938\u095e\u0947\u0926 \u0909\u0930\u0926 \u0926\u093e\u0932", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0915\u093e\u091f \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0905\u0926\u0930\u0915 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "5 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0924\u093f\u0932 \u0915\u093e \u0924\u0947\u0932 , \u092f\u093e \u0915\u094b\u0908 \u092d\u0940 \u0924\u0947\u0932", "\u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u0925\u094b\u095c\u093e, \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['इडली', 'प्याज', 'छोटा चम्मच राइ', 'छोटा चम्मच सफ़ेद उरद दाल', 'छोटा चम्मच हरी मिर्च', 'छोटा चम्मच अदरक', 'कढ़ी पत्ता', 'छोटा चम्मच हल्दी पाउडर', 'बड़ा चम्मच तिल का तेल', 'हरा धनिया', 'नमक']::text[], '["\u092e\u093f\u0928\u0940 \u0907\u0921\u0932\u0940 \u0909\u092a\u092e\u093e \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u091c\u0940\u0930\u093e, \u0909\u0930\u0926 \u0926\u093e\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0926\u093e\u0932 \u0915\u0947 \u0938\u0941\u0928\u0939\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0905\u0926\u0930\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 30 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u092e\u093f\u0928\u0940 \u0907\u0921\u0932\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u0917\u0948\u0938 \u0915\u0940 \u0906\u0902\u091a \u0915\u092e \u0915\u0930\u0947\u0902, \u0915\u095d\u093e\u0908 \u0915\u094b \u0922\u0915\u0947 \u0914\u0930 3\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0927\u0940\u092e\u0940 \u0906\u0902\u091a \u092a\u0930 \u092a\u0915\u0928\u0947 \u0926\u0947.\u00a0\u00a0 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902,\u00a0\u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u0947 \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964 \u092e\u093f\u0928\u0940 \u0907\u0921\u0932\u0940 \u0909\u092a\u092e\u093e \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u0938\u0941\u092c\u0939 \u0915\u0947 \u0928\u093e\u0936\u094d\u0924\u0947 \u0915\u0947 \u0932\u093f\u090f\u00a0\u092e\u0938\u093e\u0932\u093e \u091a\u093e\u092f\u00a0\u092f\u093e\u00a0\u0905\u0926\u0930\u0915 \u091a\u093e\u092f\u00a0\u0915\u0947 \u0938\u093e\u0925 \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 25, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breakfast_Tiffins/Mini_Idli_Upma_Recipe_Steamed_Rice_Cake_Stir_Fry-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1210.Mini_Idli_Upma_Recipe_Steamed_Rice_Cake_Stir_Fry-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('गाजर गोभी मटर सब्ज़ी रेसिपी - Carrot Cauliflower Peas Sabzi Recipe', 'carrot-cauliflower-peas-sabzi-recipe', 'गाजर गोभी मटर सब्ज़ी रेसिपी एक सरल सब्ज़ी है जिसे आप अपने रोज के खाने के लिए बना सकते है. इसमें अजवाइन, काली मिर्च, तेज पत्ता और इलाइची का प्रयोग किया जाता है जो इसे और भी स्वादिष्ट बनाता है. यह एक सात्विक रेसिपी है जिसमे प्याज और लहसुन का प्रयोग नहीं किया गया है.', '["2 \u0917\u093e\u091c\u0930 , cut into 1/2 inch sticks", "2 \u0915\u092a \u0917\u094b\u092d\u0940", "1 \u0915\u092a \u0939\u0930\u0947 \u092e\u091f\u0930", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , slit", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0905\u091c\u0935\u093e\u0907\u0928", "2 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e", "2 \u0926\u093e\u0932\u091a\u0940\u0928\u0940", "2 \u0907\u0932\u093e\u0907\u091a\u0940", "7 \u092a\u0942\u0930\u0940 \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a", "\u0938\u0930\u0938\u094b\u0902 \u0915\u093e \u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['गाजर', 'कप गोभी', 'कप हरे मटर', 'हरी मिर्च', 'छोटा चम्मच अजवाइन', 'तेज पत्ता', 'दालचीनी', 'इलाइची', 'पूरी काली मिर्च', 'सरसों का तेल']::text[], '["\u0917\u093e\u091c\u0930 \u0917\u094b\u092d\u0940 \u092e\u091f\u0930 \u0938\u092c\u094d\u095b\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0938\u093e\u0930\u0940\u00a0\u0938\u093e\u092e\u0917\u094d\u0930\u0940 \u0924\u0948\u092f\u093e\u0930 \u0915\u0930 \u0932\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0938\u0930\u0938\u094b\u0902 \u0915\u093e \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0905\u091c\u0935\u093e\u0907\u0928, \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e, \u0926\u093e\u0932\u091a\u0940\u0928\u0940, \u0907\u0932\u093e\u0907\u091a\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 10 \u0938\u0947 20 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0917\u093e\u091c\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0917\u094b\u092d\u0940, \u0928\u092e\u0915, \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947, \u0915\u095d\u093e\u0908 \u0915\u094b \u0922\u0915\u0947 \u0914\u0930 \u0917\u094b\u092d\u0940 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u0917\u094b\u092d\u0940 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b \u091c\u093e\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092e\u091f\u0930 \u0921\u093e\u0932\u0947, \u0922\u0915\u0947 \u0914\u0930 3 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0917\u093e\u091c\u0930 \u0917\u094b\u092d\u0940 \u092e\u091f\u0930 \u0938\u092c\u094d\u095b\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0926\u093e\u0932 \u092b\u094d\u0930\u093e\u0908\u00a0\u0914\u0930\u00a0\u092b\u0941\u0932\u094d\u0915\u0947\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 25, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/cauliflower_peas_carrot_sabzi/Cauliflower_Peas_Carrot_Sabzi_No_onion_no_garlic_Ayurvedic_Recipe_15_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1211.Cauliflower_Peas_Carrot_Sabzi_No_onion_no_garlic_Ayurvedic_Recipe_15_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chocolate Cheese Gujiya Recipe', 'chocolate-cheese-gujiya-recipe', 'Chocolate Cheese Gujiya Recipe is made up with the 2 evergreen ingredients - chocolate & cheese and when it comes together, it gives you a delectable treat. Gujiyas are pastry crusts filled with different savoury or sweet ingredients and deep fried. Gujiyas are served during family occasions or festival seasons such as Holi or Diwali.', '["2 cups All Purpose Flour (Maida)", "Salt , to taste", "2 tablespoons Ghee", "Water , as required", "1 cup Britannia Cheese Block , grated", "1 cup Dessicated Coconut", "1/2 cup Chocolate chips", "1 teaspoon Red Chilli powder", "Oil , to deep fry"]'::jsonb, ARRAY['salt', 'ghee', 'coconut', 'red chilli powder', 'water', 'chocolate chips', 'britannia cheese block', 'flour (maida)', 'sunflower oil']::text[], '["To begin making the\u00a0Chocolate Cheese Gujiya Recipe,\u00a0we will first make the make the filling.In a large mixing bowl combine the coconut, chocolate chips, red chilli powder, and stir well to combine.", "Keep aside.The next step is to make the dough for\u00a0pastry crust for the Gujiya.Combine the maida, ghee and salt, in a large bowl.", "Work the ghee into the flour with your fingers until the mixture resembles a coarse crumble texture.When you bring the flour together, it should hold and when you let go it should fall apart.", "Add a little water at a time and knead to make a smooth and firm dough.Knead well for a good 3 to 4 minutes for the perfect gujiya crust.Shape them into small round balls.", "Dust them in flour, roll them into small 3 inch circles.Place it in the gujiya mold, spoon in the chocolate cheese filling.", "Gently fold into a semi circle, forming a half moon shape.", "Seal the edges by pressing slightly, so that the dough sticks to each other making sure all the filling is concealed inside.Prepare the gujiyas and arrange them on a plate or a tray.", "Cover the gujiyas with a moist napkin so that the dough does not dry out.", "Preheat the oil for deep frying the gujiyas.The way to test if the oil has the right heat, is to drop in a little dough inside the oil and if it sizzles and comes up immediately, then you know you can start frying the\u00a0Chocolate Cheese Gujiya.Add in a few gujiya at a time and deep fry on medium heat until they have a beautiful golden crust.Notice after a few minutes of frying they have a golden crust - give it a light tap and if they feel firm and crusty then they are done.", "Drain out the excess oil and fry the remaining th\u00a0Chocolate Cheese Gujiya in similar way.Serve Chocolate Cheese Gujiya Recipe with hot\u00a0Masala Chai\u00a0during tea time or you can also have it as a sweet dish during special occasions."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Cheesy_Chocolate_Chilli_Gujiya_Recipe_Video_Britannia_Cheesy_Kitchen_8_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1212.Cheesy_Chocolate_Chilli_Gujiya_Recipe_Video_Britannia_Cheesy_Kitchen_8_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('केसर पिलाफ रेसिपी - Saffron Pilaf Recipe', 'saffron-pilaf-recipe', 'केसर पिलाफ रेसिपी, एक फ्लेवर से भरपूर रेसिपी है जिसमे चावल को केसर के साथ पकाया जाता है जो इस पुलाव को बहुत ही अच्छा रंग देता है. यह बहुत ही आसान है बनाने में और आपको हाउस पार्टीज के लिए भी पर्याप्त है अगर आप उत्तर भारतीय खाना बना रहे है.', '["2 cups \u092a\u093e\u0928\u0940", "1-1/2 \u0915\u092a \u091a\u093e\u0935\u0932", "1 \u092a\u094d\u092f\u093e\u091c , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u092e\u0915\u094d\u0916\u0928", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0915\u0947\u0938\u0930", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0926\u0942\u0927 , \u0917\u0930\u092e", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['s पानी', 'कप चावल', 'प्याज', 'बड़े चम्मच मक्खन', 'छोटा चम्मच केसर', 'बड़े चम्मच दूध', 'नमक']::text[], '["\u0915\u0947\u0938\u0930 \u092a\u093f\u0932\u093e\u092b \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u091b\u094b\u091f\u0947 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0917\u0930\u092e \u0926\u0942\u0927 \u0914\u0930 \u0915\u0947\u0938\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947. \u0905\u092c \u090f\u0915 \u0938\u0949\u0938\u092a\u0948\u0928 \u092e\u0947\u0902 \u092e\u0915\u094d\u0916\u0928 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u0938\u0941\u0928\u0939\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u092a\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092a\u093e\u0928\u0940, \u0915\u0947\u0938\u0930 \u0935\u093e\u0932\u093e \u0926\u0942\u0927, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u092c\u0932\u0928\u0947 \u0926\u0947.\u00a0\u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u091a\u093e\u0935\u0932 \u0921\u093e\u0932\u0947, \u0922\u0915\u0947 \u0914\u0930 25 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0927\u0940\u092e\u0940 \u0906\u0902\u091a \u092a\u0930 \u092a\u0915\u0928\u0947 \u0926\u0947. \u091a\u093e\u0935\u0932 \u0915\u0947 \u092a\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0941\u0932\u093e\u0935 \u0915\u094b 10 \u0938\u0947 15 \u092e\u093f\u0928\u091f \u0924\u0915 \u0922\u0915\u0947 \u0930\u0939\u0928\u0947 \u0926\u0947.\u00a010 \u0938\u0947 15 \u092e\u093f\u0928\u091f \u092c\u093e\u0926 \u0922\u0915\u094d\u0915\u0928 \u0939\u091f\u093e\u090f, \u092a\u0941\u0932\u093e\u0935 \u0915\u094b\u00a0\u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0915\u0947\u0938\u0930 \u092a\u093f\u0932\u093e\u092b \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u092a\u0928\u0940\u0930 \u092c\u091f\u0930 \u092e\u0938\u093e\u0932\u093e,\u00a0\u0926\u093e\u0932 \u092b\u094d\u0930\u093e\u0908\u00a0\u0914\u0930\u00a0\u092b\u0941\u0932\u094d\u0915\u0947\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f\u00a0\u092a\u0930\u094b\u0938\u0947."]'::jsonb, 25, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/1-Archana/Saffron_Pulao_Pilaf_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1213.Saffron_Pulao_Pilaf_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Achari Aloo Sabzi Recipe - Potatoes In Spicy Pickle Masala', 'achari-aloo-sabzi-recipe-potatoes-in-spicy-pickle-masala', 'Here is a lip smacking Achari Aloo Sabzi Recipe that is packed with flavours from a Punjabi Mango Pickle and cooked in an electric pressure cooker. The addition of jaggery lends to a balance of a delicious sweet and spicy taste that makes this dish stand out.', '["4 Potatoes (Aloo) , peeled and diced", "1/2 teaspoon Asafoetida (hing)", "1 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies", "4 tablespoons Punjabi style mango pickle", "1/2 teaspoon Jaggery", "2 teaspoons Mustard oil", "1 Onion , chopped", "3 cloves Garlic , chopped", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "2 teaspoons Coriander (Dhania) Leaves , chopped", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard oil', 'asafoetida (hing)', 'punjabi style mango pickle', 'coriander (dhania) leaves', 'jaggery', 'red chilli powder', 'cloves garlic', 'dry red chillies', 'onion', 'cumin seeds (jeera)', 'potato (aloo)', 'turmeric powder', 'garam masala powder']::text[], '["To begin making the Achari Aloo Sabzi Recipe, first step is to prepare all the ingredients.", "We are going to make this sabzi in a single pot in the electric pressure cooker.Turn the electric pressure cooker on and change the mode to Saute Mode and allow the pressure cooker to preheat for 2 to 3 minutes.Once the pan is preheated, add the oil, cumin seeds, asafoetida, red chillies and allow them to crackle.", "Add the garlic and onions and saute until the onions soften.Now that the onions are soft, add the dry masalas - red chili powder,\u00a0turmeric powder,\u00a0garam masala powder and salt.", "Mix well.", "Once the raw smell of maslas go away, add the pickle, jaggery and give it a good stir.", "At this stage, add the potatoes and saute until everything is mixed well.", "Sprinkle a tablespoon of water into the electric pressure cooker.Cover the electric pressure cooker and change the mode to manual and set the cooking time to 25 minutes.Allow the Achari Aloo Sabzi to cook until the electric pressure cooker gets into the keep warm mode.Once done and the pressure has released, open the pressure cooker, stir in the coriander leaves and give it a stir.", "Check the taste and adjust accordingly.Serve Achari Aloo Sabzi Recipe along with\u00a0Phulka,\u00a0Punjabi Dal Tadka\u00a0and\u00a0Kachumber Salad\u00a0for a simple weeknight dinner or a comforting weekend lunch."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Achari_Aloo_Sabzi_in_Electric_Pressure_Cooker-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1214.Achari_Aloo_Sabzi_in_Electric_Pressure_Cooker-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rava Upma Recipe With Peanuts, Peas & Corn', 'rava-upma-recipe-with-peanuts-peas-corn', 'Rava Upma Recipe With Peanuts, Peas & Corn is a healthy, tasty and colorful dish. It is equally great for both breakfast or snack. It is nutritious, tasty and very easy to make.  In this recipe roasted rava or semolina is cooked with sauteed mix of vegetables, peanuts, curry leaves and lentils.', '["1 Cup Sooji (Semolina/ Rava)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 tablespoon Ghee", "2 tablespoons Raw Peanuts (Moongphali)", "1/2 teaspoon Cumin seeds (Jeera)", "1 Onion , chopped", "1 inch Ginger , finely chopped", "1 Pinch Asafoetida (hing)", "1 teaspoon White Urad Dal (Split)", "2 Green Chillies , chopped", "2 sprig Curry leaves", "1 Carrot (Gajjar) , chopped", "1/2 Green Bell Pepper (Capsicum) , chopped", "1 Tomato , chopped", "2 tablespoons Green peas (Matar) , (fresh or frozen)", "2 tablespoons Sweet corn", "1 teaspoon Coriander (Dhania) Leaves , chopped", "1 tablespoon Lemon juice , (adjust)", "Salt , to taste", "Red Chilli powder , a pinch (optional)", "Coriander Powder (Dhania) , a pinch (optional)", "Anardana Powder (Pomegranate Seed Powder) , a few (for garnish)"]'::jsonb, ARRAY['tomato', 'asafoetida (hing)', 'coriander (dhania) leaves', 'green peas (matar) ( )', 'carrot', 'curry leaves', 'white urad dal (split)', 'onion', 'cumin seeds (jeera)', 'green chillies', 'anardana powder (pomegranate seed powder) a', 'salt', 'peanuts (moongphali)', 'mustard seeds', 'red chilli powder', 'lemon', 'sooji (semolina rava)', 'ginger', 'ghee', 'sweet corn', 'green bell pepper (capsicum)', 'coriander powder']::text[], '["To begin making the\u00a0 Rava Upma Recipe With Peanuts, Peas & Corn Recipe,\u00a0\u00a0heat a non stick pan and dry roast the semolina on medium flame until it turns into a light brown in color and aromatic.", "Turn off the heat and keep aside in a bowl to cool.In the same pan add 1/2 teaspoon of ghee and peanuts, roast peanuts on medium heat until they becomes crunchy and golden brown.", "Once done turn off the heat and transfer them into a bowl.In a saucepan, add 3 cups of water and let it come to rolling boil.", "While the water is heating, heat the remaining ghee in a non stick pan and add mustard seeds into it.", "When mustard crackles, add cumin and urad dal in it.", "Saute them until they become light brown in color.Now add onions, curry leaves, green chilli, ginger and half quantity of peanuts and saute them for a minute till the onions become translucent.", "Once done,\u00a0add tomato and cook them for about 2 minutes or more until soft and cooked.Then add all chopped vegetables, carrots, capsicum, peas, corn.", "Add the red chilli powder and coriander powder if you are using it.", "Mix well to combine,cover and cook them about 3 minutes or until cooked.Once the vegetables are cooked add semolina mix it well and add hot water.Stir continuously on low heat, after 2 or 3 minutes to ensure that there are no lumps.", "Add remaining peanuts to the rava upma.", "Cover and cook until semolina is cooked well and turn off the heat.Now add lemon juice and mix well and transfer the\u00a0\u00a0Rava Upma Recipe With Peanuts, Peas & Corn Recipe into a serving plate and serve hot.", "Serve Rava Upma along with\u00a0Spicy Lime Pickle Recipe\u00a0or\u00a0Coconut Chutney\u00a0\u00a0and finish off this breakfast with a hot cup of\u00a0\u00a0South Indian Filter Coffee Recipe With Filter Coffee Powder."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Roop/Traditional_Rava_Upma.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1215.Traditional_Rava_Upma.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Oats and Besan Cheela Recipe (High Protein Spiced Crepes)', 'oats-and-besan-cheela-recipe-high-protein-spiced-crepes', 'The Oats Besan Cheela recipe is a very traditional snack of northern India. The cheela is made from gram flour and spiced up with green chillies. In this recipe I have added additional healthy diabetic friendly ingredients like oats, making the chilla fiber rich, nutritious and gluten free.', '["250 grams Gram flour (besan)", "80 grams Rolled Oats Or Instant Oats , powdered", "2 Onions , thinly sliced", "2 Green Chillies , finely chopped", "2 cloves Garlic , grated", "1 teaspoon Fennel seeds (Saunf) , pounded", "Coriander (Dhania) Leaves , few, finely chopped", "Salt , to taste", "Red Chilli powder , to taste", "Oil , for cooking"]'::jsonb, ARRAY['salt', 'coriander (dhania) leaves', 'fennel seeds (saunf)', 'red chilli powder', 'cloves garlic', 'gram flour (besan)', 'onion', 'rolled oats instant oats', 'green chillies', 'sunflower oil']::text[], '["To begin making the Oats Besan Cheela Recipe, combine all the ingredients for the Besan Chilla in a large bowl.Gradually add water to make a thick batter.Check the salt and spice levels and adjust to suit your taste.The cheela batter will be similar to the consistency of a dosa batter or pancake batter.", "The batter should be able coat the back of the spoon.The next step is to cook the Oats Besan Cheela in a panPreheat a skillet on medium heat, pour a ladleful of batter on the pan and spread it in a circular motion to form a thin crepe/ dosa.Drizzle some oil around the cheela and cook it until the top does not look raw and you notice the edges are getting brown.", "Flip and cook on the other side for a few seconds.Once done, transfer to a plate and proceed to make the chillas with the remaining batter.Serve the\u00a0Oats Besan Cheela along with a\u00a0Sweet And Spicy Tomato Chutney\u00a0and a\u00a0Dhaniya Pudina Chutney\u00a0for breakfast, a tea time snack or even weeknight dinner."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breakfast_Tiffins/Oats_and_Besan_Chilla_Fit_Foodie-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1216.Oats_and_Besan_Chilla_Fit_Foodie-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('चाउ चाउ पोरिचा कूटू रेसिपी - Chow Chow Poricha Kootu Recipe', 'chow-chow-poricha-kootu-recipe-2', 'चाउ चाउ पोरिचा कूटू एक सरल दक्षिण भारतीय डिश है जिसमे चाउ चाउ का प्रयोग किया जाता है. इस रेसिपी को बनाने के लिए चाउ चाउ को मूंग दाल, नारियल, जीरा, दही और कढ़ी पत्ता के साथ पकाया जाता है. यह एक स्वादिष्ट रेसिपी है जिसे आप पराठा, फुल्का या चावल के साथ परोस सकते है.', '["300 \u0917\u094d\u0930\u093e\u092e \u091a\u093e\u0909 \u091a\u093e\u0909 , \u0915\u093e\u091f \u0932\u0947", "1/2 \u0915\u092a \u092a\u093f\u0932\u0940 \u092e\u0942\u0902\u0917 \u0926\u093e\u0932 , \u092a\u0915\u0940 \u0939\u0941\u0908", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "\u092a\u0940\u0938\u0928\u0947 \u0915\u0940 \u0938\u093e\u092e\u0917\u094d\u0930\u0940", "1/2 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932", "4 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "\u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u095c\u0915\u0947 \u0915\u0940 \u0938\u093e\u092e\u0917\u094d\u0930\u0940", "1 sprig \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0938\u095e\u0947\u0926 \u0909\u0930\u0926 \u0926\u093e\u0932", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091a\u0928\u093e \u0926\u093e\u0932"]'::jsonb, ARRAY['ग्राम चाउ चाउ', 'कप पिली मूंग दाल', 'छोटा चम्मच हल्दी पाउडर', 'पीसने की सामग्री', 'कप नारियल', 'सुखी लाल मिर्च', 'छोटा चम्मच जीरा', 'कढ़ी पत्ता', 'नमक', 'तड़के की सामग्री', 'छोटा चम्मच राइ', 'छोटा चम्मच तेल', 'छोटा चम्मच सफ़ेद उरद दाल', 'छोटा चम्मच चना दाल']::text[], '["\u091a\u093e\u0909 \u091a\u093e\u0909\u00a0\u092a\u094b\u0930\u093f\u091a\u093e \u0915\u0942\u091f\u0942 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u092e\u0942\u0902\u0917 \u0926\u093e\u0932 \u0915\u094b 2 \u0915\u092a \u092a\u093e\u0928\u0940 \u0914\u0930 1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930 \u0915\u0947 \u0938\u093e\u0925 \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 3 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947.\u092a\u094d\u0930\u0947\u0936\u0930 \u0928\u093f\u0915\u0932\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0915\u0941\u0915\u0930 \u0916\u0947\u0932 \u0914\u0930 \u0926\u093e\u0932 \u0915\u094b \u092b\u0947\u091f \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u0905\u092c \u091a\u093e\u0909 \u091a\u093e\u0909 \u0915\u094b \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092d\u093e\u092a \u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0928\u093e\u0930\u093f\u092f\u0932, \u091c\u0940\u0930\u093e, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947. \u0925\u094b\u095c\u093e \u0917\u0930\u092e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092b\u093f\u0930 \u0938\u0947 \u092a\u0940\u0938 \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u091a\u0928\u093e \u0926\u093e\u0932, \u0938\u095e\u0947\u0926 \u0909\u0930\u0926 \u0926\u093e\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947. \u0926\u093e\u0932 \u0915\u0947 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0930\u094b\u0938\u094d\u091f \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092a\u0915\u0940 \u0939\u0941\u0908 \u0926\u093e\u0932, \u091a\u093e\u0909 \u091a\u093e\u0909, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e, \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 3 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u092a\u0930\u094b\u0938\u0947.\u00a0\u00a0\u091a\u093e\u0909 \u091a\u093e\u0909 \u092a\u094b\u0930\u093f\u091a\u093e \u0915\u0942\u091f\u0942 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u091f\u092e\u093e\u091f\u0930 \u0930\u0938\u092e, \u091a\u093e\u0935\u0932 \u0914\u0930 \u0907\u0932\u093e\u0908\u00a0\u0935\u0921\u092e \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 45, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/3-april/Chow_Chow_Poricha_Kootu_Recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1217.Chow_Chow_Poricha_Kootu_Recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy And Tangy Bread Upma Recipe', 'spicy-and-tangy-bread-upma-recipe', 'Bread Upma recipe is simple recipe to make and delicious to eat. At the end of a week, if you have very few ingredients left in your pantry and fridge, Bread Upma is the way to go. You can whip this up in less than 30 minutes and tastes great as it has the spicy flavour from the green chillies and ginger garlic paste and tanginess from the dash of lime that you add in the end.', '["1 Onion , finely chopped", "3 Green Chillies , finely chopped", "1 tablespoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon White Urad Dal (Split)", "1 Tomato , big, finely chopped", "1 Green Bell Pepper (Capsicum) , finely chopped", "1 tablespoon Ginger Garlic Paste", "1 tablespoon Garam masala powder", "1/2 teaspoon Chaat Masala Powder", "1 teaspoon Sugar", "Salt , as required", "6 sprig Coriander (Dhania) Leaves , finely chopped", "1/2 cup Water", "10 Whole Wheat Brown Bread , cut into squares or roughly torn"]'::jsonb, ARRAY['tomato', 'salt', 'wheat brown bread', 'mustard seeds', 'chaat masala powder', 'water', 'ginger garlic paste', 'white urad dal (split)', 'sugar', 'onion', 'coriander (dhania) leaves', 'green bell pepper (capsicum)', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To begin making Spicy and Tangy Bread Upma Recipe, heat a tablespoon of oil in a heavy bottomed pan.Once the oil is hot, lower the flame and add the mustard seeds, allow them to splutter, next add urad dal and allow it to roast until the urad dal is browned.Add the ginger garlic paste, green chillies, chopped onions, chopped capsicum and saute for about a minute and a half.", "Once the onions are softened, add the tomatoes, and cook until the tomatoes turn mushy.", "Now add in the garam masala powder and chaat masala powder and saute until all the flavours combine.Now add half a cup of\u00a0 water and keep stirring until the water is absorbed.", "Add in the sugar and salt to taste and stir in the lemon juice keeping the flame on low all the while.Stir fry until the\u00a0Bread Upma mixture comes together.Once done finally stir in the cut bread pieces and toss gently.", "Saute until the bread pieces are coated well with the masalas.", "Check the taste and spices and adjust accordinglyTurn off the heat and garnish the bread upma with coriander leaves.Serve this Spicy And Tangy Bread Upma as a quick and easy breakfast along with a\u00a0Carrot Cashew Smoothie Recipe\u00a0or a\u00a0Adrak Chai."]'::jsonb, 15, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/jan-30/Bread_Upma_Recipe-1344.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1218.Bread_Upma_Recipe-1344.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gulab Sandesh Recipe - Cottage Cheese Flavored with Rose Water', 'gulab-sandesh-recipe-cottage-cheese-flavored-with-rose-water', 'The Gulab Sandesh Recipe also known as the Shondesh is traditional sweet in every Bengali home. Sandesh is made from fresh homemade chenna, combined with sugar and flavors. In this recipe, the Sandesh is flavored with gulab jal or rose water, giving it a delectable earthly flavor and taste.', '["350 grams Chenna (Homemade Cottage Cheese)", "1/4 cup Sugar , powdered", "1 teaspoon Rose water", "1/4 cup Pistachios , sliced", "Fresh rose petals , for garnishing (optional)"]'::jsonb, ARRAY['pistachios', 'rose water', 'sugar', 'rose', 'chenna']::text[], '["To begin making the Gulab Sandesh Recipe, make the homemade paneer/ chenna according to the instructions.Once all the water from the chenna is drained, place the chenna in a large mixing bowl.", "Add the sugar and gulab jal (rose water).", "Using the heel of your hands, knead the chenna to make a very soft and smooth mixture.This process takes at least 10 minutes to get a really soft and smooth chenna sandesh mixture.Once you notice you have a smooth ball of sandesh dough, divide the sandesh into equal portions and shape them into tiny bite size balls.Roll them between the palms of your hand and shape them into smooth balls.", "Using your thumb make an impression in the center.", "Place a sliced pistachio or a fresh rose petal in the center and the Gulab Sandesh is ready to be served.Serve the Gulab Sandesh with a warm cup of Tetley Cinnamon and Honey Green Tea that compliments and balances out the sweetness of the sandesh."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Gulab_Sandesh_Recipe_Cottage_Cheese_Flavored_with_Rose_Water-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1219.Gulab_Sandesh_Recipe_Cottage_Cheese_Flavored_with_Rose_Water-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vegetable Ragi & Oats Uttapam Recipe', 'vegetable-ragi-oats-uttapam-recipe', 'The Vegetable Ragi & Oats Uttapam Recipe is a twist to the original recipe of a traditional Uttapam. The addition of oats and lots of vegetables makes this Uttapam wholesome making it a great tiffin dish. It is a diabetic friendly recipe as it uses wholesome oats and brown rice instead of white rice.', '["Ingredients for Dosa Batter", "1/2 cup White Urad Dal (Whole)", "80 grams Rolled Oats Or Instant Oats", "1 cup Brown Rice", "1/2 cup Ragi Seeds", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "Ingredients for Vegetable Ragi & Oats Uttapam Recipe", "1 cup Oats dosa batter", "1 Red Bell pepper (Capsicum) , finely chopped", "2 Carrots (Gajjar) , grated", "1 Tomato , finely chopped", "1 Green Chilli , finely chopped", "Oil , as required"]'::jsonb, ARRAY['tomato', 'brown rice', 'ragi seeds', 'red bell pepper (capsicum)', 'green chilli', 'sunflower oil', 'oats dosa batter', 'carrot', 'methi seeds (fenugreek seeds)', 'rolled oats instant oats', 'white urad dal']::text[], '["To begin making the\u00a0Vegetable Ragi & Oats Uttapam Recipe we will first make the oats dosa batter."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breakfast_Tiffins/Vegetable_Oats_Uttapam_Fit_Foodie_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1220.Vegetable_Oats_Uttapam_Fit_Foodie_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('थक्काली रसम रेसिपी - Thakkali Rasam Recipe', 'thakkali-rasam-recipe', 'थक्काली रसम रेसिपी एक ट्रेडिशनल रेसिपी जिसे दक्षिण भारत के हर घर में बनाया जाता है. यह टमाटर रसम बनाने में बहुत आसान है और  आप इसे सूप की तरह भी सर्दियों में पी सकते है. इसमें टमाटर के साथ इमली का प्रयोग होता है जो इसमें खट्टापन देता है.', '["25 \u0917\u094d\u0930\u093e\u092e \u0905\u0930\u0939\u0930 \u0926\u093e\u0932", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1/2 \u0915\u092a \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u093e\u0928\u0940", "5 \u091f\u092e\u093e\u091f\u0930 , \u0915\u093e\u091f \u0932\u0947", "2 \u0932\u0949\u0928\u094d\u0917 \u0932\u0939\u0938\u0941\u0928", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930 , \u0938\u0947\u0915 \u0932\u0947", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930 , \u0938\u0947\u0915 \u0932\u0947", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "4 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0918\u0940", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0940\u0902\u0917", "2 \u091f\u0939\u0928\u0940 \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947"]'::jsonb, ARRAY['ग्राम अरहर दाल', 'छोटा चम्मच हल्दी पाउडर', 'कप इमली का पानी', 'टमाटर', 'लॉन्ग लहसुन', 'छोटा चम्मच जीरा पाउडर', 'छोटा चम्मच धनिया पाउडर', 'छोटा चम्मच काली मिर्च पाउडर', 'छोटा चम्मच लाल मिर्च पाउडर', 'नमक', 'तड़के के लिए', 'कढ़ी पत्ता', 'छोटा चम्मच राइ', 'छोटा चम्मच जीरा', 'बड़ा चम्मच घी', 'छोटा चम्मच हींग', 'टहनी हरा धनिया']::text[], '["\u0925\u0915\u094d\u0915\u093e\u0932\u0940 \u0930\u0938\u092e \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0924\u0941\u0905\u0930 \u0926\u093e\u0932 \u0915\u094b 1 \u0915\u092a \u092a\u093e\u0928\u0940 \u0915\u0947 \u0938\u093e\u0925 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 3 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947. \u0915\u0941\u0915\u0930 \u0916\u094b\u0932\u0947, \u0926\u093e\u0932 \u0915\u094b \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092b\u0947\u091f \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u091f\u092e\u093e\u091f\u0930 \u0915\u094b \u090f\u0915 \u092c\u094d\u0932\u0947\u0902\u0921\u0930 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u0942\u0930\u0940 \u092c\u0928\u093e \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u091c\u0940\u0930\u093e, \u0932\u0939\u0938\u0941\u0928, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u091c\u0940\u0930\u093e \u0924\u095c\u0915\u0928\u0947 \u0924\u0915\u00a0\u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930 \u0915\u0940 \u092a\u094d\u092f\u0942\u0930\u0940, \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u093e\u0928\u0940, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930, \u0939\u0940\u0902\u0917, \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u0915\u0941\u0915\u0930 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 1 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0926\u0947. \u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947\u0964\u00a0\u00a0\u092a\u094d\u0930\u0947\u0936\u0930 \u0928\u093f\u0915\u0932\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0915\u0941\u0915\u0930 \u0916\u094b\u0932\u0947 \u0914\u0930 \u0907\u0938\u092e\u0947\u0902 \u0924\u0941\u0905\u0930\u00a0\u0926\u093e\u0932 \u0921\u093e\u0932\u0947\u0964 1 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0926\u0947. \u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0927\u0940\u092e\u0940 \u0906\u0902\u091a \u092a\u0930 10 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e\u090f\u0964 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u0947 \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902\u0964 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0925\u0915\u094d\u0915\u093e\u0932\u0940 \u0930\u0938\u092e \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u091a\u093e\u0935\u0932, \u091f\u092e\u093e\u091f\u0930 \u092a\u094d\u092f\u093e\u091c \u0938\u093e\u0902\u092c\u0930 \u0914\u0930\u00a0\u092c\u0940\u091f\u0930\u0942\u091f \u0925\u094b\u0930\u0928\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 40, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Thakkali_Rasam_Recipe_Tomato_Rasam-6_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1221.Thakkali_Rasam_Recipe_Tomato_Rasam-6_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer Kalimirch Recipe (Paneer in Black Pepper flavored Gravy)', 'paneer-kalimirch-recipe-paneer-in-black-pepper-flavored-gravy', 'Paneer Kalimirch Recipe is delicious, creamy paneer dish flavored with black pepper and lots of garlic. Instead of the frying paneer it has been grilled in the pan and then tossed in mild flavored gravy. Serve Paneer Kalimirch with Paratha for the weeknight dinner. Pepper lends a pungent but not harsh touch of spiciness to the dish, making it seem quite different from the usual. This recipe adds great variety to the vegetarian dinner menu for the parties as well.', '["250 gram Paneer (Homemade Cottage Cheese)", "1/4 cup Fresh cream", "2 tablespoon Milk", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "2 teaspoons Whole Black Peppercorns , pounded coarsely", "Salt , to taste", "Oil , for cooking", "Ingredients to be ground into a smooth paste", "1 Onion , roughly chopped", "1/4 cup Cashew nuts", "4 cloves Garlic", "1 inch Ginger , peeled and chopped", "Ingredients for the garnish", "4 cloves Garlic , finely chopped", "2 tablespoon Oil", "1 pinch Black pepper powder"]'::jsonb, ARRAY['cashew nuts', 'salt', 'ginger', 'milk', 'black peppercorns', 'gram paneer', 'cloves garlic', 'onion', 'black pepper powder', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To prepare Paneer Kalimirch, we will first make a paste of the onion, cashew nut, garlic and ginger using a mixer.", "Transfer the paste to a bowl and keep aside until required.", "Cut paneer into equal size square pieces.", "Now heat one tablespoon of oil in the griddle pan over medium heat.", "Arrange paneer pieces over the griddle pan and grill until charred marks appear on one side.Brush the upper side of paneer pieces with oil and turn them upside down.", "Grill paneer until charred marks appear on both sides.", "This takes about 5 minutes on each side.", "Turn off the heat.", "Arrange paneer pieces in a plate and keep aside.", "While paneer is grilling we will start preparing gravy.Heat two tablespoons oil in a saucepan over medium heat.", "Add the onion paste made above and fry the paste stirring continuously.", "Once the oil gets separated from the masala add cream and milk.", "Stir to combine.", "Add the salt, turmeric powder, garam masala, stir and let the gravy simmer for sometime.", "Adjust the consistency of gravy using little water.", "After adding water simmer the gravy for some time for the flavors to develop.", "Now add crushed pepper and grilled paneer to the gravy.", "Stir to combine.", "Now cook gravy for 3 - 4 minutes more over medium heat.", "Turn off the heat.", "Transfer Paneer Kalimirch to a serving bowl.For garnish, heat oil in a small pan over medium heat.", "Once the oil is heated add chopped garlic.", "Fry garlic until it turns golden.", "With a spoon pour fried garlic and oil over the Paneer Kalimirch.", "Sprinkle a pinch of black pepper on top.", "Serve hot.", "Serve the\u00a0Paneer Kalimirch (Paneer in Black Pepper flavored Gravy) as a weeknight dinner or on parties along with\u00a0Paratha."]'::jsonb, 55, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Hina_Gujral/Paneer_Kalimirch_Recipe_Black_Pepper_Gravy.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1222.Paneer_Kalimirch_Recipe_Black_Pepper_Gravy.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thengai Poornam Kozhukattai / Ukadiche Modak Recipe With Rice Flour', 'thengai-poornam-kozhukattai-ukadiche-modak-recipe-with-rice-flour', 'Thengai Poornam Kozhukattai / Ukadiche Modak Recipe is a very festive sweet that is made for Lord Ganesha''s Birthday also known as Vinayaka or Ganesh Chaturthi that is observed in the month of August - September.', '["1 cup Rice flour", "1 cup Water", "1 teaspoon Oil", "1/4 teaspoon Salt", "1-1/2 cups Fresh coconut , grated", "1/2 cup Jaggery", "1 teaspoon Cardamom Powder (Elaichi)"]'::jsonb, ARRAY['salt', 'coconut', 'jaggery', 'water', 'cardamom powder (elaichi)', 'rice flour', 'sunflower oil']::text[], '["In a heavy bottomed saucepan; combine all the ingredients for the filling and place it on high heat until the jaggery is dissolved completely.Once the jaggery dissolves, turn the heat to medium and keep stirring until the mixture thickens and the water begins to evaporate.It takes about 7-10 minutes for the water to evaporate.", "Towards the end you will notice the mixtures comes together, with all the water evaporated.", "The coconut filling will now look like sticky mixture.At this stage, turn off the heat and transfer the mixture to another bowl to cool.", "Once cool divide the mixture into 10-15 equal portions.", "This will be the sweet filling for the modak wrapper."]'::jsonb, 40, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Thenga_Poornam_Kuzhakattai_Preethi_Electric_Pressure_Cooker-6.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1223.Thenga_Poornam_Kuzhakattai_Preethi_Electric_Pressure_Cooker-6.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ande Ka Salan Recipe - Tangy Egg Masala in Peanut Gravy', 'ande-ka-salan-recipe-tangy-egg-masala-in-peanut-gravy', 'Whenever you are in dilemma what to cook for dinner, eggs always come handy! Therefore, we have a delicious Egg Curry Recipe that is especially served with Biryani. Ande Ka Salan Recipe is a tangy, spicy curry prepared using coconut based gravy and hard boiled eggs.', '["6 Whole Eggs , hardboiled", "1/4 Cup Fresh coconut , freshly grated", "2 tablespoons Roasted Peanuts (Moongphali) , roasted", "2 tablespoons Sesame seeds (Til seeds)", "1/2 cup Water , lukewarm", "Other ingredients", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1 sprig Curry leaves", "2 Onions , finely chopped", "1 inch Ginger , finely chopped", "6 cloves Garlic , finely chopped", "2 Green Chillies , slit", "1 cup Homemade tomato puree", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 1/2 teaspoon Coriander (Dhania) Powder", "1 cup Tamarind Water", "1 tablespoon Oil", "2 tablespoons Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['tomato', 'green chillies', 'ginger', 'tamarind water', 'coconut', 'mustard seeds', 'coriander (dhania) leaves', 'red chilli powder', 'water', 'peanuts', 'cloves garlic', 'curry leaves', 'onion', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'coriander (dhania) powder', 'eggs', 'turmeric powder', 'sesame seeds (til seeds)', 'sunflower oil']::text[], '["To begin making the\u00a0Ande Ka Salan Recipe, into a preheated pan, add the roasted peanuts, sesame seeds and roast for a minute till the sesame seeds start to pop.", "Once done turn off the heat and let it cool.Add the roasted peanuts and the sesame seeds into a mixer grinder along with coconut, warm water and grind into a smooth paste.", "Keep aside.Next we will proceed to make the gravy.", "Into a preheated pan, add oil, once the oil is hot, add the mustard seeds, cumin seeds, methi seeds and allow the seeds to crackle.Once the seeds crackle, add the curry leaves, onions, garlic, ginger, green chillies and saute until the onions turn golden brown in color.Once done, add in the tomato puree, turmeric powder, red chilli powder, coriander powder, coconut peanut sesame mixture, tamarind water and salt to taste.", "Stir the Ande ka Salan gravy well to combine.Simmer the gravy for Ande ka Salan on medium heat for about 5 to 7 minutes.", "After 5 to 7 minutes, stir in chopped coriander leaves, add slit hard boiled eggs to the gravy, give a brisk boil and turn off the heat.Transfer Ande Ka salan to a serving dish and serve hot.Serve\u00a0Ande Ka Salan Recipe along with\u00a0Chicken Biryani\u00a0or\u00a0Tawa Paratha\u00a0and\u00a0Burani Raita\u00a0for your weekend dinner."]'::jsonb, 45, 'North Indian', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Ande_ka_Salan_Video_Recipe_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1224.Ande_ka_Salan_Video_Recipe_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Egg Kothu Paratha Recipe', 'egg-kothu-paratha-recipe', 'Egg Kothu Paratha is a popular South Indian delicacy made with shredded chapatis or parathas. Muttai Parotta as it is called in Tamil Nadu is a dish based on a the Sri Lankan version, where it originated as Kothu Roti. It is made using paratha , eggs, some meat, and a spicy curry or gravy that are tossed together in a hot cast-iron griddle with sufficient oil.', '["2 cups Leftover roti , torn into 1 inch bits", "1 tablespoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon SSP Asafoetida (Hing)", "2 Onions , finely chopped", "6 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "2 Green Chillies , slit", "2 sprig Curry leaves , torn", "2 Tomatoes , finely chopped", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Black pepper powder", "1/2 teaspoon Garam masala powder , or egg curry masala", "3 Whole Eggs", "1/4 cup Coriander (Dhania) Leaves , chopped", "Salt , to taste", "1 Lemon , juiced"]'::jsonb, ARRAY['tomato', 'garam masala powder eggs curry masala', 'salt', 'ginger', 'mustard seeds', 'asafoetida (hing)', 'coriander (dhania) leaves', 'leftover roti', 'red chilli powder', 'cloves garlic', 'curry leaves', 'lemon', 'onion', 'black pepper powder', 'eggs', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Egg Kothu Paratha Recipe, into a preheated pan add oil and mustard seeds and allow the seeds to crackle.Once done add the asafoetida,onions, garlic, ginger, green chillies, curry leaves and saute until the onions soften and turn golden brown in colour.After the onions have become golden brown add the tomatoes, turmeric powder, red chilli powder and saute until the tomatoes soften.Once done crack three eggs and add to the onion tomato masala.", "Stir well until the eggs becomes a scramble.After the eggs are done add the torn leftover roti.", "Sprinkle salt to taste and stir well for three to four minutes.Once all the ingredients are well combined add juice from one lemon and chopped coriander leaves.", "Stir well to combine and turn off the heat.Transfer the\u00a0Egg Kothu Paratha\u00a0 into a serving plate and serve hot.", "Serve\u00a0Egg Kothu Paratha Recipe\u00a0for breakfast or a quick dinner with\u00a0Tomato Onion Cucumber Raita Recipe."]'::jsonb, 40, 'Indian', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Egg_Kothu_Paratha_Recipe_Video_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1225.Egg_Kothu_Paratha_Recipe_Video_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gawar Phali Masala Sabzi Recipe - Cluster Beans Gravy Sabzi', 'gawar-phali-masala-sabzi-recipe-cluster-beans-gravy-sabzi', 'The  Gawar Phali Masala Sabzi is a simple gravy sabzi that is cooked in a light tomato onion gravy along with peanuts. The addition of ginger, garlic and the peanuts makes this simple gawar phali vegetable stand out in taste and flavors. Addition of ajwain also adds to the taste of the gawar phali Sabzi.', '["250 grams Gawar Phali (Kothavarangai / Cluster beans) , washed and cut into 1-1.5 inch pieces", "1/2 teaspoon Ajwain (Carom seeds)", "1/4 teaspoon SSP Asafoetida (Hing)", "1 Onion , chopped", "4 Tomatoes , finely chopped", "6 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1 tablespoon Jaggery", "1/2 cup Raw Peanuts (Moongphali)", "Salt , to taste", "1/2 cup Water", "1 teaspoon Mustard oil", "Coriander (Dhania) Leaves , for garnish, chopped as required"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'mustard oil', 'asafoetida (hing)', 'coriander (dhania) leaves', 'ajwain (carom seeds)', 'jaggery', 'red chilli powder', 'cloves garlic', 'water', 'gawar phali (kothavarangai cluster beans)', 'onion', 'peanuts (moongphali)', 'coriander powder', 'turmeric powder']::text[], '["To begin making the Gawar Phali Masala Sabzi Recipe, into a preheated pressure cooker add oil.", "Once the oil is hot add the ajwain, asafoetida, onion, garlic, ginger and saute until the onions soften and turn golden brown in colour.", "Once done add the tomatoes, turmeric powder, red chili powder, coriander powder and jaggery.", "Saute until the tomatoes become soft and mushy.", "Once the tomatoes have turned soft add the gawar phali, raw peanuts, salt to taste and water.Close the pressure cooker with its lid and pressure cook the gawar phali masala sabzi for 2 whistles.After two whistles turn off the heat and release the pressure immediately.Stir in coriander leaves and transfer the\u00a0Gawar Phali Masala Sabzi into a serving bowl and serve hot.Serve the\u00a0Gawar Phali Masala Sabzi\u00a0along with\u00a0\u00a0Phulka,\u00a0Jeera Rice\u00a0&\u00a0Kachumber Salad\u00a0for a weekday meal."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Gawar_Phali_Masala_Sabzi_Recipe_-_Cluster_Beans_Gravy_Sabzi__4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1226.Gawar_Phali_Masala_Sabzi_Recipe_-_Cluster_Beans_Gravy_Sabzi__4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bharwa Parwal Sabzi Recipe -Stuffed Pointed Gourd Dry Vegetable', 'bharwa-parwal-sabzi-recipe-stuffed-pointed-gourd-dry-vegetable', 'Parwal also known as potol, parbal, parval or pointed gourd .Bharwa Parwal Sabzi Recipe -Stuffed Pointed Gourd Dry Vegetable is a dry vegetable prepared by stuffing parwal with a dry masala that mainly consists of besan and crushed peanuts and  basic spices. The flavours of this stuffed parwal sabzi is amazing and it makes a tasty side dish with any meal.', '["1/2 cup Gram flour (besan)", "1/4 teaspoon SSP Asafoetida (Hing)", "1/2 cup Roasted Peanuts (Moongphali)", "1/4 teaspoon Turmeric powder (Haldi)", "2 teaspoons Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Garam masala powder", "1/4 teaspoon Red Chilli powder", "1 teaspoon Sugar", "2 teaspoons Amchur (Dry Mango Powder)", "2 tablespoons Kasuri Methi (Dried Fenugreek Leaves)", "Salt , to taste", "1 tablespoons Mustard oil", "Other Ingredients", "500 grams Pointed gourd (Parval)", "2 tablespoons Mustard oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "To Garnish", "Coriander (Dhania) Leaves , few sprigs, finely chopped", "2 tablespoons Fresh coconut , grated"]'::jsonb, ARRAY['gram flour', 'besan', 'ssp asafoetida', 'hing', 'roasted peanuts', 'moongphali', 'turmeric powder', 'haldi', 's coriander powder', 'dhania', 'cumin powder', 'jeera', 'garam masala powder', 'red chilli powder', 'sugar', 's amchur', 'dry mango powder', 's kasuri methi', 'dried fenugreek leaves', 'salt', 's mustard oil', 'other ingredients', 's pointed gourd', 'parval', 'mustard seeds', 'rai/ kadugu', 'to garnish', 'coriander', 's fresh coconut']::text[], '["To begin making Bharwa Parwal Sabzi Recipe -Stuffed Pointed Gourd Dry Vegetable, wash and peel parwal.", "Remove stalk from both the ends and make a slit in the center lengthwise.Do not cut the whole parwal.", "We need the parwal intact to fill in the stuffing.", "With help of a small spoon or scoop, scoop out any large seeds from the parwal.", "Set them aside.Next add the roasted peanuts into a mixer grinder and grind into a powder."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Articles/Bharwa_Parwal_Sabzi_Recipe_Video_Stuffed_Gourd_Masala_4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1227.Bharwa_Parwal_Sabzi_Recipe_Video_Stuffed_Gourd_Masala_4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sukhi Urad Dal Sabzi Recipe', 'sukhi-urad-dal-sabzi-recipe', 'Sukhi Urad Dal Sabzi Recipe is a North Indian Style lentil dish made with split white urad dal. Sukhi in Hindi means ''dry'' as this lentil dish is served dry. The soaked Split urad dal is steamed in the pressure cooker to retain its texture.', '["1 cup White Urad Dal (Whole)", "1/4 cup Water", "1 Onion , chopped", "1 inch Ginger , finely chopped", "1 Green Chilli , finely chopped", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon SSP Asafoetida (Hing)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "Salt , to taste", "1 teaspoon Ghee", "1 Lemon , juice", "Coriander (Dhania) Leaves , a few, roughly chopped to garnish"]'::jsonb, ARRAY['salt', 'ginger', 'cumin', 'green chilli', 'ghee', 'asafoetida', 'spoon turmeric powder', 'water', 'coriander', 'onion', 'coriander powder', 'lemon take out the juice', 'garam masala powder', 'white urad dal']::text[], '["To begin making the Sukhi Urad Dal Sabzi Recipe, first clean the urad dal and thoroughly rinse it with water.", "Let the dal soak in enough water for at least 4-5 hours.", "Once soaked, drain the water.Keep a pressure cooker with little water in it on heat.", "Place the drained Urad Dal into the steamer pan of the pressure cooker.", "Add water to the urad dal and pressure cook for three whistles.", "Turn off the heat.", "Let the pressure release naturally.", "After the pressure has released we will make the\u00a0Sukhi Urad Dal Sabzi RecipeInto a preheat pan add ghee.", "Once the ghee is hot add the cumin seeds and asafoetida and let the cumin seeds crackle.Once done add the onion, ginger and green chilli and saute till onions turn soft and translucent.", "After the onions are soft add the cooked urad dal, turmeric powder, salt to taste, garam masala powder, coriander powder and stir well to combine.", "Taste and adjust the seasoning accordingly.", "Cover and cook for 3 to 4 minutes until the dal fluffs up a little bit more.", "Once done turn off the heat and mix in the juice of one lemon.", "Stir in the coriander leaves and transfer the Sukhi Urad Dal Recipe into a serving bowl and serve hot.Serve Sukhi Urad Dal Recipe with\u00a0Phulkas,\u00a0No Onion And No Garlic Aloo Gajar Matar Ki Sabzi Recipe\u00a0and\u00a0Lauki Raita Recipe\u00a0for\u00a0 lunch or dinner."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Sukhi_Urad_Dal_Sabzi_Recipe_8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1228.Sukhi_Urad_Dal_Sabzi_Recipe_8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('मटर पुलाव रेसिपी - Peas Pulao Recipe', 'peas-pulao-recipe', 'मटर पुलाव रेसिपी एक स्वादिष्ट चावल की रेसिपी है जिसमे चावल को मटर और खड़े मसाले के साथ पकाया जाता है. इसमें खड़े मसाले में तेज पत्ता, जीरा, इलाइची, लॉन्ग, स्टार अनीस का प्रयोग किया जाता है. आप इसे किसी भी दाल या करी के साथ परोस सकते है.', '["1-1/2 \u0915\u092a \u091a\u093e\u0935\u0932", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0918\u0940", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e", "1 \u0938\u094d\u091f\u093e\u0930 \u0905\u0928\u0940\u0938", "2 \u0907\u0932\u093e\u0907\u091a\u0940", "2 \u0932\u0949\u0928\u094d\u0917", "1 \u0907\u0902\u091a \u0926\u093e\u0932\u091a\u0940\u0928\u0940", "1 \u092a\u094d\u092f\u093e\u091c , \u092a\u0924\u0932\u093e \u0914\u0930 \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "1/2 \u0915\u092a \u0939\u0930\u0947 \u092e\u091f\u0930"]'::jsonb, ARRAY['कप चावल', 'बड़ा चम्मच घी', 'छोटा चम्मच जीरा', 'तेज पत्ता', 'स्टार अनीस', 'इलाइची', 'लॉन्ग', 'इंच दालचीनी', 'प्याज', 'नमक', 'कप हरे मटर']::text[], '["\u092e\u091f\u0930 \u092a\u0941\u0932\u093e\u0935 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u091a\u093e\u0935\u0932 \u0915\u094b \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 20 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092d\u093f\u0917\u094b \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e, \u091c\u0940\u0930\u093e, \u0938\u094d\u091f\u093e\u0930 \u0905\u0928\u0940\u0938, \u0907\u0932\u093e\u0907\u091a\u0940, \u0932\u0949\u0928\u094d\u0917 \u0914\u0930 \u0926\u093e\u0932\u091a\u0940\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u091c\u0940\u0930\u093e \u0915\u0947 \u0924\u095c\u0915\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u091c\u0940\u0930\u093e \u0915\u0947 \u0924\u095c\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092e\u091f\u0930 \u0914\u0930 \u091a\u093e\u0935\u0932 \u0921\u093e\u0932\u0947\u0964\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0915\u0941\u0915\u0930 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947. 3 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947 \u0914\u0930 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0926\u0947. \u0915\u0941\u0915\u0930 \u0916\u094b\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0928\u093f\u0915\u093e\u0932\u0947 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092e\u091f\u0930 \u092a\u0941\u0932\u093e\u0935 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u092a\u0928\u0940\u0930 \u092c\u091f\u0930 \u092e\u0938\u093e\u0932\u093e,\u00a0\u0926\u093e\u0932 \u092e\u0916\u0928\u0940\u00a0\u0914\u0930\u00a0\u092b\u0941\u0932\u094d\u0915\u093e\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0905\u092a\u0928\u0947 \u0938\u092a\u094d\u0924\u093e\u0939 \u0905\u0902\u0924 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Donna_George/Matar_Pulao_Peas_Pulao_Recipe-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1229.Matar_Pulao_Peas_Pulao_Recipe-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('कढ़ाई छोले रेसिपी - Kadai Chole Recipe', 'kadai-chole-recipe', 'कढ़ाई छोले एक स्वादिष्ट रेसिपी है जिसमे छोले या काबुली चना को उबाल कर प्याज, शिमला मिर्च और रोज के मसालो के साथ पकाया जाता है.आप इसे अपने या अपने बच्चो के लंच बॉक्स में भी पैक कर सकते है. यह एक सरल रेसिपी है, इसलिए आपके रोज के खाने के लिए पर्याप्त है.', '["1 \u0915\u092a \u0915\u093e\u092c\u0941\u0932\u0940 \u091a\u0928\u093e \u092f\u093e \u091b\u094b\u0932\u093e , \u0930\u093e\u0924 \u092d\u0930 \u092d\u093f\u0917\u094b \u0932\u0947", "2 \u092a\u094d\u092f\u093e\u091c , \u0915\u093e\u091f \u0932\u0947", "1 \u0936\u093f\u092e\u0932\u093e \u092e\u093f\u0930\u094d\u091a (\u0939\u0930\u0940) , \u0915\u093e\u091f \u0932\u0947", "4 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "1 \u091f\u092e\u093e\u091f\u0930 , \u092a\u094d\u092f\u0942\u0930\u0940 \u092c\u0928\u093e \u0932\u0947", "1 \u0926\u093e\u0932\u091a\u0940\u0928\u0940", "3 \u0932\u0949\u0928\u094d\u0917", "1 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e", "1 \u092c\u095c\u0940 \u0907\u0932\u093e\u0907\u091a\u0940", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0915\u0936\u094d\u092e\u0940\u0930\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0905\u092e\u091a\u0942\u0930 \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0905\u091c\u0935\u093e\u0907\u0928", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0918\u0940", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['कप काबुली चना या छोला', 'प्याज', 'शिमला मिर्च', 'हरी', 'कली लहसुन', 'इंच अदरक', 'हरी मिर्च', 'टमाटर', 'दालचीनी', 'लॉन्ग', 'तेज पत्ता', 'बड़ी इलाइची', 'छोटा चम्मच धनिया पाउडर', 'छोटा चम्मच जीरा पाउडर', 'छोटा चम्मच कश्मीरी लाल मिर्च पाउडर', 'छोटा चम्मच अमचूर पाउडर', 'छोटा चम्मच गरम मसाला पाउडर', 'छोटा चम्मच अजवाइन', 'बड़े चम्मच घी', 'नमक']::text[], '["\u0915\u095d\u093e\u0908 \u091b\u094b\u0932\u0947 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u091b\u094b\u0932\u0947 \u0915\u094b \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930 \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 6 \u0918\u0902\u091f\u0947 \u0915\u0947 \u0932\u093f\u090f \u092d\u093f\u0917\u094b \u0926\u0947.6 \u0918\u0902\u091f\u0947 \u0915\u0947 \u092c\u093e\u0926 \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0928\u092e\u0915 \u0914\u0930 3 \u0938\u0941\u092a \u092a\u093e\u0928\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947 \u0914\u0930 30 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092e\u0927\u094d\u092f\u092e \u0906\u0902\u091a \u092a\u0930 \u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0905\u091c\u0935\u093e\u0907\u0928, \u092a\u094d\u092f\u093e\u091c, \u0905\u0926\u0930\u0915, \u0932\u0939\u0938\u0941\u0928, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0926\u093e\u0932\u091a\u0940\u0928\u0940, \u0932\u0949\u0928\u094d\u0917, \u0907\u0932\u093e\u0907\u091a\u0940, \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0936\u093f\u092e\u0932\u093e \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 \u0936\u093f\u092e\u0932\u093e \u092e\u093f\u0930\u094d\u091a \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930, \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930, \u0905\u092e\u091a\u0942\u0930 \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0915\u093e\u092c\u0941\u0932\u0940 \u091a\u0928\u093e, \u0925\u094b\u095c\u093e \u0918\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 5\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0915\u095d\u093e\u0908 \u091b\u094b\u0932\u0947\u00a0\u0915\u094b\u00a0\u0924\u0935\u093e \u092a\u0930\u093e\u0920\u093e\u00a0\u0914\u0930\u00a0\u092c\u0942\u0902\u0926\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 55, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Kadai_Chole_Recipe_Kadai_Chana_Masala-14_1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1230.Kadai_Chole_Recipe_Kadai_Chana_Masala-14_1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kesar Peda Recipe', 'kesar-peda-recipe', 'Kesar Peda Recipe is one of the easiest Indian sweets to make and doesn''t require too much time or effort. It''s a traditional Indian dessert made by combining sweetened khoya with other flavors such as saffron and cardamom and formed into small balls or other shapes. A favorite with kids and adults alike, Indian festivals are usually incomplete without this delicious sweet.', '["300 grams Khoya (Mawa) , store bought or home made", "4 tablespoons Sugar", "1 teaspoon Saffron strands", "2 tablespoons Milk", "1/4 teaspoon Cardamom Powder (Elaichi)", "1 tablespoon Pistachios , sliced", "1/2 teaspoon Ghee , optional"]'::jsonb, ARRAY['s khoya', 'mawa', 's sugar', 'saffron strands', 's milk', 'cardamom powder', 'elaichi', 'pistachios', 'ghee']::text[], '["To begin making the Kesar Peda Recipe, gently warm the milk without boiling it and soak the saffron in it.", "Keep this aside for 10 minutes.In a pan or kadai, add crumbled khoya and sugar.", "Cook this on a low heat for 4-5 minutes stirring continuously until the sugar is completely dissolved.", "The khoya will first melt and then thicken again.", "Stir continuously till the khoya thickens and be careful not to burn the khoya.", "Once the khoya has thickened, add saffron milk and powdered cardamom to it.", "Cook for a few more minutes till the khoya thickens up considerably and resembles a sticky dough like consistency and stars leaving the sides of the pan.At this stage, turn off the heat and allow the peda mixture to cool.Once the mixture is cool enough to touch, knead it lightly to get rid of any lumps so you have a smooth mixture.", "You can add a little ghee at this stage to give it a good shine.Roll the kesar peda mixture into a log and cut 12 equal pieces.Roll each of peda portions into small balls, make a small dent in the center and add the pista slices.", "Or you could use a peda mould if you have one, like shown in the image.", "Once shaped the Kesar Peda is ready to be served.Serve the\u00a0Kesar Peda\u00a0as a dessert along with a festive meal of\u00a0Tandoori Gobi Tikka Recipe,\u00a0Hariyali Paneer Tikka Masala Gravy Recipe\u00a0and\u00a0Modur Pulao With Pomegranate Recipe."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Kesar_Peda_Recipe_14_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1231.Kesar_Peda_Recipe_14_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Baklava Rolls Recipe - Turkish Sweet Rolls', 'baklava-rolls-recipe-turkish-sweet-rolls', 'Baklava is a Middle Eastern sweet/dessert made from phyllo sheets and nuts that are soaked in syrup. If you have the readily available phyllo sheets, you can make these Baklava Rolls in about 30 minutes and have an exquisite dessert for the festive season.', '["Ingredients for the filling", "1/2 cup Whole Almonds (Badam) , coarsely powdered", "1/2 cup Walnuts , coarsely powdered", "1/2 cup Pistachios , coarsely powdered", "1/2 cup Caster Sugar", "1/2 cup Butter (Salted) , melted", "1/4 teaspoon Cinnamon Powder (Dalchini)", "Ingredients for the syrup", "3/4 cup Sugar", "3/4 cup Water", "1 teaspoon Lemon juice", "Other Ingredients", "2 Phyllo Sheets , or strudel sheets", "Pistachios , finely chopped for garnishing"]'::jsonb, ARRAY['cinnamon powder (dalchini)', 'pistachios', 'water', 'sugar', 'badam (almond)', 'lemon', 'caster sugar', 'butter', 'pllo sheets strudel sheets', 'walnuts']::text[], '["To begin making the\u00a0Baklava Rolls Recipe, the first step is to prep all the ingredients and keep them ready.Into a mixing bowl, combine all the filling ingredients - almond powder, walnut powder, pistachio powder, sugar, cinnamon powder and butter.", "Mix them well to combine.Take the phyllo sheets and fold it into half and butter the side which is facing up.", "Note: Phyllo sheets should be thawed completely before use.", "Place the rolls\u00a0seam-side\u00a0down on the baking sheet for best results.", "Do not crowd the rolls in the baking pan else they will lose shape.Spoon about 2\u00a0tablespoons\u00a0of the filling mixture at the short end in one line and roll the sheet.", "As you roll, keep applying butter on the rolled side up.Don''t\u00a0roll completely till the end as yet.", "We will fill the dry fruit filling mixture again halfway through before rolling it\u00a0to the end.Once halfway through rolling add about 2 tablespoons of the filling mix along the same short side.", "Now roll the sheet completely till the end.Repeat the same procedure for the remaining sheet.", "Cut each roll into 3 pieces.", "Arrange the Baklava rolls into a baking sheet.", "Brush the rolls again lightly with butter.Preheat the oven at 180 degree C; place the Baklava rolls in the oven and bake for about 15-20 minutes or until it turns golden brown."]'::jsonb, 70, 'Middle Eastern', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Dessert_Gourmet_Favorites/baklava_rolls_recipe_shutterstock_126929408.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1232.baklava_rolls_recipe_shutterstock_126929408.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ghee Roast Dosa Recipe - Crispy Paper Dosa Recipe', 'ghee-roast-dosa-recipe-crispy-paper-dosa-recipe', 'The Ghee Roast Dosa Recipe is an easy and quick paper dosa recipe if you have the dosa batter ready in the refrigerator. The Homemade Idli Dosa Batter Recipe, gives a delicious taste to these Ghee Roast Dosa.', '["3 cups Idli Rice", "1-1/4 cups White Urad Dal (Whole)", "2 teaspoon Methi Seeds (Fenugreek Seeds)", "3 teaspoon Salt", "Ghee , to make dosas as needed"]'::jsonb, ARRAY['s idli rice', 's white urad dal', 'whole', 'methi seeds', 'fenugreek seeds', 'salt', 'ghee']::text[], '["To begin making the Ghee Roast Dosa Recipe, we need to make sure we have Idli Dosa batter.Here is how you can make the\u00a0Homemade Idli Dosa Batter Recipe.Heat the skillet on medium heat and pour a ladleful of dosa batter over the skillet and spread the batter evenly using a spiral motion from inside out.Pour a teaspoon of ghee around the edges and increase the heat and cook the ghee roast dosa for couple of minutes until the bottom of the dosa starts to turn golden brown.Turn the ghee roast dosa over carefully and cook the other side for a few seconds.Turn over again and then fold them into half or roll them into a cylinder.", "Once done, serve the ghee roast dosa hot.Serve\u00a0the Ghee Roast Dosa Recipe/ Paper Dosa along with\u00a0Thakkali Vengaya Sambar,\u00a0Tomato Onion Chutney\u00a0and\u00a0Coconut Chutney, it tastes absolutely delectable."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Classic_Ghee_Roast_Dosa_Recipe_Paper_Dosa_Video_14_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1233.Classic_Ghee_Roast_Dosa_Recipe_Paper_Dosa_Video_14_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharashtrian Kulith Shengole Recipe - Spicy Horse Gram Flour Dumplings', 'maharashtrian-kulith-shengole-recipe-spicy-horse-gram-flour-dumplings', 'Kulith Shengole is a rustic Maharashtrian dish made using Horse gram flour. The recipe is simple and easy to make. Use freshly milled horse gram flour for best results. You could also make this for lunch when you have unexpected guests at home if you have horse gram flour handy, since the recipe gets done under 15 minutes.', '["1 cup Horse Gram Flour", "5-6 cloves Garlic , finely chopped", "2-3 Green Chillies , finely chopped", "2 tablespoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "Salt , to taste", "Lukewarm Water , as required"]'::jsonb, ARRAY['horse gram flour', 'salt', 'mustard seeds', 'cloves garlic', 'water', 'cumin seeds (jeera)', 'green chillies', 'sunflower oil']::text[], '["To begin making Kulith Shengole, get prep with all the ingredients and mix together the flour, half of the garlic, half of the chillies, a tablespoon oil, and salt in a Mixing bowl.Add warm water to make a stiff, pliable dough.", "Knead the dough well.Make log shaped dumplings from the dough.", "Cover and keep them.In a Pan/Kadai, heat the remaining oil.Add the mustard seeds.", "Once they splutter, add the cumin seeds.Add the rest of the garlic and green chillies.", "Add about 1-1/2 cups water and bring it to a rolling boil.Drop the dumplings one by one in the boiling water.Cook covered till the dumplings are cooked through (about 7-8 minutes).Serve Kulith Shengole alone, or with\u00a0Roti,\u00a0Bhakri, or\u00a0Hot Steamed Rice\u00a0for lunch."]'::jsonb, 30, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuli_Ajay/Shengole_spicy_Horse_gram_flour_dumplings.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1234.Shengole_spicy_Horse_gram_flour_dumplings.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ragi Idli Recipe - Learn How To Make A Healthy Ragi Idli', 'ragi-idli-recipe-learn-how-to-make-a-healthy-ragi-idli', 'The Ragi Idli recipe is a simple wholesome dish that you can make with ease. It is made from ragi seeds soaked along with idli rice and ground along with soaked urad dal. The idli dosa batter made from fresh ragi seeds, makes it absolutely delicious and can be used to make both idli''s and dosas. This recipe is a great way to include ragi and other millets in your diet.', '["To make the ragi idli & dosa batter", "1 cup Idli Rice", "2 cups Ragi Seeds", "2 cups White Urad Dal (Whole)", "3 teaspoons Methi Seeds (Fenugreek Seeds)", "4 teaspoons Salt", "Water , for soaking"]'::jsonb, ARRAY['to make the ragi idli & dosa batter', 'idli rice', 's ragi seeds', 's white urad dal', 'whole', 's methi seeds', 'fenugreek seeds', 's salt', 'water']::text[], '["To begin making the Homemade Soft Ragi\u00a0Idli, soak the ragi and rice together in a single bowl and the urad dal along with methi seeds in another bowl.", "Soak them for a minimum of 5 hours.Once soaked, grind the rice and ragi in a mixer grinder until you get a smooth batter.", "Grind the urad dal to make a smooth batter.", "Ensure when you are grinding you add just enough water to bring them together.", "The batter should be thick, especially the rice and ragi batter.Combine the ragi batter and urad dal batter, add salt and then mix well.", "Cover and set in a warm place to ferment.", "About 8 to 10 hours or overnight.Read this detailed recipe of how to make the\u00a0Ragi Idli Dosa Batter\u00a0in different weather conditions.Once you have the fermented\u00a0Ragi Idli batter, grease the Idli Steamer Plates\u00a0with a little sesame oil.", "This process is purely optional.", "I like to do this as it adds to the flavor of the idli\u2019s.", "Pour spoonfuls of the ragi idli batter into these moulds.", "Also making mini idli''s makes the ragi idli softer, fluffier and easier to eat as well.Do make sure you fill the ragi idli batter only half way through as they will rise up to the top when steamed.", "Once all the plates are filled, place the filled idli racks one above the other making sure the holes are facing the filled portion.Prepare the idli steamer with a little water in the bottom.", "Place the filled ragi idli racks in the steamer.", "Place the steamer on high heat and steam the idli\u2019s for 10 minutes.After 10 minutes of steaming, turn off the heat.", "Open the steamer and insert a knife or a pick to test whether the idli''s are cooked.", "If nothing sticks then the idlis are perfectly steamed.Now you can remove the ragi idli from the steamer.", "Have a small bowl filled with water.", "Dip a spoon in the water and then scoop the ragi idli out starting from the edges.", "Dipping the spoon in water helps in the easy removal of idli from the plates.The wholesome homemade soft ragi idli are now ready to be served for breakfast, lunch or dinner.Serve the\u00a0Ragi Idli Recipe along with\u00a0Coconut Chutney,\u00a0Red Capsicum Chutney,\u00a0Thakkali Vengaya Sambar\u00a0and\u00a0Idli Milagai Podi\u00a0for a wholesome\u00a0indian diabetic breakfast\u00a0or even for a light and healthy\u00a0indian dinner."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Healthy_Ragi_Idli_Recipe_Video_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1235.Healthy_Ragi_Idli_Recipe_Video_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Red Capsicum Chutney Recipe - Red Bell Pepper Chutney', 'red-capsicum-chutney-recipe-red-bell-pepper-chutney', 'Red Capsicum Chutney Recipe is a lip smacking chutney that is packed with flavors from the roasted bell pepper and baby onions. The addition of the tadka with the crunchy urad dal makes this chutney absolutely delectable.  Did you know Red Capsicum is loaded with antioxidants and high in Vitamin C and Vitamin A. Compared to green bell peppers, the red ones have almost 11 times more beta-carotene and 1.5 times more vitamin C.', '["4 Red Bell pepper (Capsicum) , roughly chopped", "1/2 cup Pearl onions (Sambar Onions) , quartered", "1 Tomato , roughly chopped", "4 Dry Red Chillies", "4 cloves Garlic , chopped", "1 tablespoon Oil", "Salt , to taste", "Ingredients for seasoning", "1 tablespoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "2 Dry Red Chillies , broken"]'::jsonb, ARRAY['tomato', 'salt', 'red bell pepper (capsicum)', 'mustard seeds', 'cloves garlic', 'pearl onion (sambar onion)', 'white urad dal (split)', 'dry red chillies', 'curry leaves', 'sunflower oil']::text[], '["To begin making the Red\u00a0Capsicum Chutney Recipe , fist prep all the ingredients and keep them ready.Heat oil over medium heat in a saute pan;\u00a0add the red chillies, onion, garlic and capsicum and saute until onions are transparent and the bell peppers have softened.", "You can sprinkle some salt and cover the pan, so the bell peppers sweat a little and cook faster.", "Once done, turn off the heat and allow the red capsicum chutney mixture to cool.Once cooled add the red capsicum chutney mixture to a mixer grinder and grind to a make smooth paste.", "Check the salt level and adjust to suit your taste.", "Transfer the red capsicum chutney into a bowl and keep aside.", "Our next step is to make the seasoning for the Red\u00a0Capsicum Chutney.Heat a tablespoon of oil in a pan, add mustard seeds and urad dal and allow the mustard seeds to crackle and the dal to turn golden brown.", "Once the dal has turned golden brown, add the red chilli and the curry leaves, stir for a few seconds and turn off the heat.Add the seasoning to Red\u00a0Capsicum Chutney and serve.", "Serve the Red Capsicum Chutney with\u00a0Ragi Idli\u00a0and\u00a0Mixed Vegetable Sambar\u00a0for a wholesome breakfast."]'::jsonb, 25, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Red_Capsicum_Chutney_Recipe_Video_3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1236.Red_Capsicum_Chutney_Recipe_Video_3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Date and Tamarind Chutney Recipe - Khajur Imli Chutney', 'date-and-tamarind-chutney-recipe-khajur-imli-chutney', 'Khajur Imli Ki Chutney or the Date Tamarind Chutney is a sweet and sour tangy chutney made from dates tamarind and jaggery.It is an essential component in Chaats like Pani Puri, Bhel Puri, Samosa and more. Topping this chutney for chaats is an absolute must to have the best chaat experience.', '["1 cup Dates , pitted", "1/4 cup Tamarind , deeseeded", "1/2 cup Jaggery", "1 cup Water", "1 teaspoon Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Dry ginger powder", "1 teaspoon Black Salt (Kala Namak)", "Salt , to taste"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'black salt', 'jaggery', 'red chilli powder', 'water', 'dry ginger powder', 'dates', 'tamarind deeseeded']::text[], '["To begin making the Date and Tamarind Chutney Recipe, into a pressure cooker add dates, jaggery, tamarind, and water.", "Pressure cook for 3 to 4 whistles.", "Turn off the heat and allow the pressure to release naturally.", "Once the pressure has released open the pressure cooker and with the help of a hand blender blend the tamarind and dates to make a coarse mixture.", "Place the pressure cooker back on heat and add the chilli powder, cumin powder, dry ginger powder, black salt and salt to taste.", "Add little water to adjust the consistency of the\u00a0\u00a0Date and Tamarind Chutney and simmer for 3 to 4 minutes.", "Turn off the heat and cool the Date and Tamarind Chutney.", "Refrigerate and store the Date and Tamarind Chutney \u00a0in an airtight container until ready to serve.Serve\u00a0Date and Tamarind Chutney Recipe - Khajur Imli Chutney\u00a0along with\u00a0Samosa\u00a0or\u00a0Bread Pakora Recipe\u00a0or add it to\u00a0Dahi Batata Puri Chaat\u00a0and enjoy."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Articles/Date_Tamarind_Chutney_Video_Recipe_Kajur_Imli_Chutney_2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1237.Date_Tamarind_Chutney_Video_Recipe_Kajur_Imli_Chutney_2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('मटर की तेहरी रेसिपी - Matar Ki Tehri Recipe', 'matar-ki-tehri-recipe', 'मटर की तेहरी रेसिपी एक पारम्परिक रेसिपी है जिसे उत्तर प्रदेश के घरो में बनाया जाता है. इस डिश को बनाने के लिए चावल को खड़े मसाले और हरे मटर के साथ पकाया जाता है. तेहरी पुलाव से थोड़ी अलग होती है. तेहरी थोड़ी गीली और स्टिकी होती है. आप इसमें ताज़ा हरे मटर का प्रयोग करें, अगर ताज़ा मटर नहीं है तो आप फ्रोजेन का भी प्रयोग कर सकते है. इसे अपने रोज के खाने के लिए बनाए या फिर अपने लंच बॉक्स में पैक करें।', '["1 \u0915\u092a \u091a\u093e\u0935\u0932", "4-5 \u0932\u0949\u0928\u094d\u0917", "1 \u0907\u0902\u091a \u0926\u093e\u0932\u091a\u0940\u0928\u0940", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u092a\u0942\u0930\u0940 \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a", "2 \u092c\u095c\u0940 \u0907\u0932\u093e\u0907\u091a\u0940", "1 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "3 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0918\u0940", "1/4 \u0915\u092a \u092a\u094d\u092f\u093e\u091c , \u092a\u0924\u0932\u093e \u0914\u0930 \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "1/4 \u0915\u092a \u091f\u092e\u093e\u091f\u0930 , \u092a\u0924\u0932\u093e \u0914\u0930 \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "1/4 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u0915\u0938 \u0932\u0947", "1 \u0915\u092a \u0939\u0930\u0947 \u092e\u091f\u0930", "1/4 \u0915\u092a \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['कप चावल', 'लॉन्ग', 'इंच दालचीनी', 'बड़ा चम्मच पूरी काली मिर्च', 'बड़ी इलाइची', 'सुखी लाल मिर्च', 'बड़े चम्मच घी', 'कप प्याज', 'कप टमाटर', 'इंच अदरक', 'कप हरे मटर', 'कप हरा धनिया', 'तेज पत्ता', 'नमक']::text[], '["\u092e\u091f\u0930 \u0915\u0940 \u0924\u0947\u0939\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u091a\u093e\u0935\u0932 \u0915\u094b \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 1 \u0918\u0902\u091f\u0947 \u0915\u0947 \u0932\u093f\u090f \u092d\u093f\u0917\u094b \u0932\u0947. \u092d\u0940\u0917 \u091c\u093e\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u092a\u093e\u0928\u0940 \u0928\u093f\u0915\u093e\u0932 \u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u00a0\u0905\u092c \u090f\u0915 \u0915\u092a \u0917\u0930\u092e \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u092e\u091f\u0930 \u0915\u094b \u092d\u093f\u0917\u094b \u0926\u0947.\u00a0\u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0932\u0949\u0928\u094d\u0917, \u0926\u093e\u0932\u091a\u0940\u0928\u0940, \u092a\u0942\u0930\u0940 \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a, \u092c\u095c\u0940 \u0907\u0932\u093e\u0907\u091a\u0940, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u0938\u0947 2 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0927\u0940\u092e\u0940 \u0906\u0902\u091a \u092a\u0930 \u092a\u0915\u093e \u0932\u0947.\u00a02 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c, \u0905\u0926\u0930\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u091c\u092c \u092a\u094d\u092f\u093e\u091c \u092d\u0942\u0930\u0947 \u0939\u094b\u0928\u0947 \u0932\u0917\u0947 \u0924\u092c \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930, \u0939\u0930\u0947 \u092e\u091f\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a02 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e, \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e, \u091a\u093e\u0935\u0932, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0938\u092c\u0915\u094b \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u0915\u0941\u0915\u0930 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947. 1 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947, \u0917\u0948\u0938 \u0915\u0940 \u0906\u0902\u091a \u0927\u0940\u092e\u0940 \u0915\u0930\u0947\u0902 \u0914\u0930 3 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u0928\u0947 \u0926\u0947.\u00a0\u092a\u0915 \u091c\u093e\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947. \u092a\u094d\u0930\u0947\u0936\u0930 \u0928\u093f\u0915\u0932\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0915\u0941\u0915\u0930 \u0916\u094b\u0932\u0947, \u091a\u092e\u094d\u092e\u091a \u0938\u0947 \u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092e\u091f\u0930 \u0915\u0940 \u0924\u0947\u0939\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u092c\u0942\u0902\u0926\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u0914\u0930 \u092a\u093e\u092a\u095c \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 50, 'Awadhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/6-sep/Matar_Ki_Tehri_recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1238.Matar_Ki_Tehri_recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mushroom Methi Brown Rice Recipe', 'mushroom-methi-brown-rice-recipe', 'This is the first time I am using brown rice in my recipe. The texture of brown rice is amazing. Once cooked it didn’t resemble rice at all, it looks more like moong. Brown rice is not a boon for just for diabetic people, but for all rice eaters. Rich in fibre, this amazing rice makes a superfood if you can toss in some nutritious vegetables and greens. That is exactly what I did with brown rice. I made it for my kids lunch box, tossed in some button mushrooms and fresh fenugreek leaves.', '["1 cup Brown Rice", "1 cup Button mushrooms , sliced thin", "1 cup Methi Leaves (Fenugreek Leaves) , chopped", "2 Onions , finely chopped", "2 Tomatoes , finely chopped", "3 Green Chillies , slit", "5 cloves Garlic , chopped", "1 teaspoon Red Chilli powder", "2 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "2 tablespoons Oil"]'::jsonb, ARRAY['tomato', 'salt', 'brown rice', 'coriander powder', 'methi leaves (fenugreek leaves)', 'red chilli powder', 'cloves garlic', 'onion', 'button mushrooms', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Mushroom Methi Brown Rice, rinse brown rice twice.", "Soak in water for about 30 minutes.Drain the rice from water and add 2-1/2 cup clean water to soaked rice in a pressure cooker.", "Pressure cook for 2 whistles.In a heavy bottomed pan, heat oil.", "Add garlic and onions and green chilies, saut\u00e9 until onions turn translucent.Once the onions have turned translucent add the\u00a0 finely chopped tomatoes and cook till tomatoes turn mushy.After the tomatoes have turned mushy add the red chilli powder, turmeric powder, coriander powder and salt.", "Mix well to combine.", "Now add button mushroom and cook for about 2 to 3 minutes.", "Mushrooms will release moisture, cook it in it\u2019s own moisture.After the moisture from the mushrooms has evaporated add finely chopped fresh fenugreek leaves and cook for another 3 minutes.When mushrooms and fenugreek leaves are fully cooked, add cooked brown rice and gently mix it.", "Check for salt and adjust accordingly.", "Transfer the Mushroom Methi Brown Rice into a serving plate and serve hot.Serve Mushroom Methi Brown Rice along with\u00a0Tomato Onion Cucumber Raita,\u00a0Beetroot Raita\u00a0or any other Raita of your choice."]'::jsonb, 55, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Mushroom_Methi_Brown_Rice.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1239.Mushroom_Methi_Brown_Rice.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Jeera Rice Recipe - Cumin And Ghee Flavored Rice', 'jeera-rice-recipe-cumin-and-ghee-flavored-rice', 'The Jeera Rice (Pulao) Recipe is simple rice recipe that you can make in less than 20 minutes. The fresh roasted cumin along with ghee when combined with steamed rice, brings out a fantastic nutty flavor that goes well with a variety of Dals & Kadhi''s to make a great weeknight dinner.', '["1 cup Rice", "2 teaspoons Cumin seeds (Jeera)", "2 tablespoons Ghee", "Salt , to taste"]'::jsonb, ARRAY['salt', 'cumin seeds (jeera)', 'rice', 'ghee']::text[], '["To begin making the\u00a0Jeera Rice Recipe, we will first cook the rice in a saucepan/handi.", "First, rinse the rice well in water.", "Place the washed rice in the saucepan, add salt, 1 tablespoon ghee and two cups of water.Bring the rice to a brisk boil.Once the rice comes to a brisk boil, cover the pan, turn the heat to low and cook the rice until all the water is completely absorbed.", "Once all the water is absorbed, turn off the heat.Allow the rice to rest for 10 minutes before you can mix the roasted cumin into it.", "The rice will fluff up as it rests.After 10 minutes, heat a tablespoon of ghee in a small pan.", "Add the cumin seeds and allow it to crackle.", "Once it crackles and you can smell the roasted aromas, turn off the heat.Pour the roasted cumin (jeera) into the cooked rice and using a slotted spoon, stir the rice gently and fluff it up.The Jeera Rice\u00a0 is now ready to be served along with\u00a0Dals & Kadhi''s\u00a0\u00a0to make a great weeknight dinner.Serve\u00a0Jeera Rice\u00a0along with\u00a0Tadka Dal,\u00a0Paneer Butter Masala\u00a0and\u00a0Garlic Naan\u00a0for a weekend lunch with your family."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Jeera_Pulao_Pilaf_Pulav_Recipe_Cumin_Ghee_Rice-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1240.Jeera_Pulao_Pilaf_Pulav_Recipe_Cumin_Ghee_Rice-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dal Fry Recipe', 'dal-fry-recipe', 'Dal Fry is a delicious and lip smacking bowl of health that is a daily dish in most of the Indian homes. This dal fry recipe is made of chana dal or split bengal grams and is usually thicker than the daily dal. The tempering or tadka takes it to another level altogether. You can use other dals like tur dal or masoor dal as well if you like.', '["1 cup Chana dal (Bengal Gram Dal)", "Water , as required", "1 Onion , finely chopped", "2 Tomatoes , finely chopped", "2 Green Chillies , finely chopped", "2 inch Ginger", "5 cloves Garlic", "2 tablespoons Kasuri Methi (Dried Fenugreek Leaves)", "1/2 teaspoon Turmeric powder (Haldi)", "Salt , as per taste", "Lemon wedges , as required, for garnishing", "Coriander (Dhania) Leaves , chopped for garnishing", "1 teaspoon Kashmiri Red Chilli Powder", "1/2 teaspoon Asafoetida (hing)", "1 tablespoon Mustard seeds (Rai/ Kadugu)", "1 tablespoon Fennel seeds (Saunf)", "1 tablespoon Cumin seeds (Jeera)", "2 Dry Red Chillies", "Ghee , as required"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'kashmiri red chilli powder', 'chana dal (bengal gram dal)', 'coriander (dhania) leaves', 'asafoetida (hing)', 'mustard seeds', 'fennel seeds (saunf)', 'ghee', 'water', 'cloves garlic', 'dry red chillies', 'onion', 'kasuri methi (dried fenugreek leaves)', 'lemon', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies']::text[], '["To begin making the Dal Fry Recipe, wash the dal and soak it in the water for about 20 to 30 minutes.Pressure cook the dal for 5-6 whistles with water, salt and turmeric powder.", "Wait for the pressure to release naturally.", "Once done, open the lid and set it aside.", "Drain and reserve the water.Heat oil and ghee in a kadhai.", "Once hot, add the grated ginger, garlic and green chillies to it.Saute for a few seconds and add the chopped onion.", "Saute for another 3-4 minutes till onions are soft and golden brown in colour.Once done add the tomatoes to it and let it cook for 2 minutes till the tomatoes are soft and mushy.After the tomatoes are soft add the cooked lentils to the masala and give it a good mix.Add 1 cup of the reserved lentil water to it, adjust salt accordingly.Let the dal come to a boil, then simmer for 10 mins till it reaches the desired consistency.", "Add water as and when needed to reach the consistency you prefer.", "I prefer it a little thicker.The next step is to temper the dal.", "Heat ghee/clarified butter in a small tadka pan.", "Once hot, add the cumin seeds, fennel seeds and mustard seeds and dry red chillies, followed by the hing and red chilli powder.", "Fry for 15 secs till everything has popped and is fragrant.", "Make sure that you do not burn them.", "Pour the tadka on the dal.", "Rest the dal fry for 10 mins before giving it a stir and serve.", "Serve hot, garnished with coriander leaves and a squeeze of lemon juice.Serve Dal Fry Recipe with\u00a0Steamed Rice Recipe\u00a0or\u00a0jeera rice\u00a0or\u00a0Phulka\u00a0and\u00a0Aloo Methi Masala Recipe\u00a0for a delicious meal."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Swayampurna_Mishra/Dal_fry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1241.Dal_fry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Gajar Matar Sabzi Recipe', 'aloo-gajar-matar-sabzi-recipe', 'Aloo Gajar Matar Sabzi Recipe is an one pot delight that can be made or your everyday meals. This quick recipe is made in a pressure cooker. It is ideal to make for weeknight dinner and can be packed into yours and yours kids lunch boxes.', '["3 Potatoes (Aloo) , peeled and diced", "2 Carrots , peeled and diced", "1/2 cup Green peas (Matar) , steamed", "5 Tomatoes , chopped into chunks", "1 Onion , finely chopped", "1 inch Ginger , chopped", "4 cloves Garlic , chopped", "1/2 teaspoon Ajwain (Carom seeds)", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/2 tablespoon Coriander (Dhania) Powder", "1/2 teaspoon Garam masala powder", "Salt , to taste", "1 tablespoons Mustard oil", "Coriander (Dhania) Leaves , for garnish"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'mustard oil', 'coriander (dhania) leaves', 'ajwain (carom seeds)', 'green peas (matar)', 'cloves garlic', 'carrot', 'red chilli powder', 'onion', 'coriander (dhania) powder', 'potato (aloo)', 'turmeric powder', 'garam masala powder']::text[], '["To begin making the Aloo Gajar Matar Sabzi Recipe, add the tomatoes into the tall jar of the Zodiac Mixer Grinder.", "Use the puree option and blend to make a smooth puree.", "Keep aside.Into a preheated pressure cooker, add mustard oil and let it get hot.", "Once the oil is hot, add the ajwain and allow it splutter for few seconds.Once the cumin seeds splutter, add onions, ginger and green chillies and saute them till the onions soften.Add tomato puree and all the spice powders like the turmeric powder, red chilli powder, coriander powder and the garam masala.", "Saute to combine well.Once combined add the diced carrot, potatoes and salt to taste.Add about 1 cup of water and pressure cook the curry for about 3-4 whistle.", "Once done, leave the cooker to rest and let the pressure release naturally.Once the pressure has released remove the lid and stir in the steamed peas.", "Brisk boil for 2-3 minutes.", "Turn off the heat and transfer\u00a0Aloo Gajar Matar Sabzi into a serving bowl.", "Garnish with coriander leaves and serve hot.Serve the Aloo Gajar Matar Sabzi Recipe\u00a0along with a\u00a0Tawa Paratha,\u00a0Gujarati Dal\u00a0and\u00a0with a\u00a0Tomato Onion Cucumber Raita\u00a0by the side."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Aloo_Gajar_Matar_Sabzi_Video_Recipe_14_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1242.Aloo_Gajar_Matar_Sabzi_Video_Recipe_14_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Whole Masala Gobhi Recipe - Spiced Whole Roasted Cauliflower Masala', 'whole-masala-gobhi-recipe-spiced-whole-roasted-cauliflower-masala', 'Whole Masala Gobi Recipe or Whole Roasted Cauliflower is a sure shot way to impress your dinner guests. Intensely flavourful, and healthy too, this cauliflower dish is a wonderful way to present this humble vegetable. Combined with a burst of spices, onions and potatoes, the Whole Masala Gobi makes for a fantastic dinner option.', '["1 Cauliflower (gobi)", "2 Onions , diced", "2 Potatoes (Aloo) , diced", "3 tablespoons Oil", "1 cup Hung Curd (Greek Yogurt)", "2 teaspoon Red Chilli powder", "2 teaspoons Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "2 cloves Garlic , grated", "1 inch Ginger , grated", "Salt , to taste", "Coriander (Dhania) Leaves , a bunch, finely chopped"]'::jsonb, ARRAY['salt', 'coriander (dhania)', 'hung curd (greek yogurt)', 'ginger', 'cauliflower (gobi)', 'red chilli powder', 'cloves garlic', 'onion', 'coriander powder', 'potato (aloo)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Poori Masala Gobhi Recipe, wash the cauliflower and remove the stem and leaves, while keeping the cauliflower as a whole.", "Boil the whole cauliflower in a large pot filled with water for 10 minutes until it is just about cooked through.", "The color of the\u00a0cauliflower to a greenish color.", "Once done, remove the\u00a0cauliflower from the water and allow it to cool a bit.Preheat the oven to 200 C.In a small bowl, mix together yogurt, a tablespoon of oil, red chili powder, coriander powder, garam masala powder, ginger garlic paste and salt.Once the cauliflower is cool, rub the yogurt mixture all over the cauliflower, potatoes and onions.Brush an oven proof skillet or roasting pan\u00a0with oil.", "The pan should be\u00a0large enough to fit the cauliflower, potatoes and onions.Place the poori gobi (cauliflower) along with the along with onions and potatoes in the roasting pan.Drizzle with the remaining oil over the poori gobi masala.", "Bake the poori gobi masala\u00a0in a preheated oven for 20 -25 minutes till the top is golden brown and the cauliflower is cooked through.", "Since the\u00a0cauliflower is already partially cooked, this process will not take time.Once you notice it is cooked, remove the Poori Masala Gobi from the oven and serve.Optionally sprinkle some chaat masala over the\u00a0Poori Masala Gobhi Recipe and serve it as a side dish for dinner or for parties along with\u00a0Lachha Parathas\u00a0and\u00a0Punjabi Dal Tadka\u00a0and\u00a0Paneer Butter Masala."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Richa_Gupta/Poori_Masala_Gobhi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1243.Poori_Masala_Gobhi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('पापड़ एर डालना रेसिपी - Bengali Papad Curry Recipe', 'bengali-papad-curry-recipe', 'पापड़ एर डालना रेसिपी, एक स्वादिष्ट बंगाली रेसिपी है जिसे हर बंगाली घर में रोज के खाने के लिए बनाया जाता है. इसे ज़्यदातर दुर्गा पूजा के समय बनाया जाता है. यह बहुत ही सरल रेसिपी है जो बहुत कम समय में बन जाती है.', '["4 \u092a\u093e\u092a\u095c , \u0915\u094b\u0908 \u092d\u0940 \u0906\u092a\u0915\u0940 \u092a\u0938\u0902\u0926 \u0915\u093e \u0932\u0947\u0932\u0947", "4 \u0906\u0932\u0942", "1 \u091f\u092e\u093e\u091f\u0930", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u0915\u0938 \u0932\u0947", "1 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e", "1 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "1/1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0936\u0915\u094d\u0915\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0918\u0940"]'::jsonb, ARRAY['पापड़', 'आलू', 'टमाटर', 'इंच अदरक', 'तेज पत्ता', 'सुखी लाल मिर्च', 'छोटा चम्मच जीरा', 'छोटा चम्मच जीरा पाउडर', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच लाल मिर्च पाउडर', 'छोटा चम्मच शक्कर', 'छोटा चम्मच गरम मसाला पाउडर', 'नमक', 'छोटा चम्मच तेल', 'छोटा चम्मच घी']::text[], '["\u092a\u093e\u092a\u095c \u090f\u0930 \u0921\u093e\u0932\u0928\u093e \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0906\u0932\u0942 \u0915\u094b \u0927\u094b \u0915\u0930 \u091b\u0940\u0932 \u0932\u0947. \u0905\u092c \u0907\u0938 \u0906\u0927\u093e \u0915\u093e\u091f \u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u0938\u0915\u0940 \u092a\u094d\u092f\u0942\u0930\u0940 \u092c\u0928\u093e \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0906\u0932\u0942 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0938\u0941\u0928\u0939\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u092a\u093e\u092a\u095c \u0915\u0947 4 \u0939\u093f\u0938\u094d\u0938\u0947 \u0915\u0930 \u0932\u0947 \u0914\u0930 \u0909\u0928\u094d\u0939\u0947\u0902 \u092c\u091a\u0947 \u0939\u0941\u090f \u0924\u0947\u0932 \u092e\u0947\u0902 \u0924\u0932 \u0932\u0947. \u092a\u093e\u092a\u095c \u0928\u093f\u0915\u093e\u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u0909\u0938\u0940 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u092c\u091a\u0947 \u0939\u0941\u090f \u0924\u0947\u0932 \u092e\u0947\u0902 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a, \u091c\u0940\u0930\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u091c\u0940\u0930\u093e \u0915\u0947 \u0924\u095c\u0915\u0928\u0947 \u0924\u0915\u00a0\u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930 \u0915\u0940 \u092a\u094d\u092f\u0942\u0930\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 3 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0905\u0926\u0930\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930 \u0914\u0930 1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 3 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0936\u0915\u094d\u0915\u0930, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0924\u0932\u0947 \u0939\u0941\u090f \u0906\u0932\u0942, 1-1/2 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u0915\u095d\u093e\u0908 \u0915\u094b \u0922\u0915 \u0932\u0947. \u0906\u0932\u0942 \u0915\u0947 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092a\u093e\u0915 \u091c\u093e\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0924\u0932\u0947 \u0939\u0941\u090f \u092a\u093e\u092a\u095c \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 3 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0915\u095d\u093e\u0908 \u0938\u0947 \u0922\u0915\u094d\u0915\u0928 \u0939\u0947\u091f, \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e, \u0918\u0940 \u0921\u093e\u0932\u0947, 2 \u092e\u093f\u0928\u091f \u0914\u0930 \u092a\u0915\u093e\u090f \u0914\u0930 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947. \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092a\u093e\u092a\u095c \u090f\u0930 \u0921\u093e\u0932\u0928\u093e \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u091a\u093e\u0935\u0932 \u0914\u0930 \u092c\u0948\u0917\u0928 \u092d\u093e\u091c\u093e \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 65, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/19-Jan/Papad_er_Dalna_bengali_style_papad_curry_Recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1244.Papad_er_Dalna_bengali_style_papad_curry_Recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lehsun ki Chutney - Spicy Garlic Chutney', 'lehsun-ki-chutney-spicy-garlic-chutney', 'Garlic Chutney also known as Lehsun Ki Chutney is popularly used in Chaats, like Vada Pav, Chillas etc. Lehsun Ki Chutney recipe is also a staple among the villages of Rajasthan and Gujarat where they have it along with bajra ka rotla. The pungent aroma along with the lemon and red chillies brings out the flavor of this chutney.', '["1/2 cup Garlic , peeled", "8-10 Dry Red Chillies", "1 teaspoon Cumin seeds (Jeera)", "1 Lemon , juiced", "1/4 cup Water", "Salt , to taste"]'::jsonb, ARRAY['salt', 'water', 'lemon', 'dry red chillies', 'garlic', 'cumin seeds (jeera)']::text[], '["To begin making the Lehsun ki Chutney - Spicy Garlic Chutney,combine the\u00a0garlic,\u00a0chillies,\u00a0cumin seeds,\u00a0lemon juice, water and salt to taste\u00a0in a blender and blend to make a smooth chutney.Transfer the Lehsun Ki Chutney into a bowl and serve.", "You can store the Lehsun ki Chutney -Spicy Garlic Chutney in a glass jar and serve as desired.You can also add a little water before serving to make the Lehsun ki Chutney have\u00a0a little saucy consistency.", "Store refrigerated for about two weeks.Serve the\u00a0Lehsun ki Chutney recipe along with\u00a0Vada Pav\u00a0for a tea time snack.", "You can even serve it with hot\u00a0Gujarati Style Bhakri\u00a0and\u00a0\u00a0 Homemade Curd\u00a0for brunch."]'::jsonb, 20, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Articles/Lehsun_Chutney_Garlic_Chutney_Video_Recipe_7_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1245.Lehsun_Chutney_Garlic_Chutney_Video_Recipe_7_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mushroom Corn Masala Dosa Recipe Using Ragi Idli Dosa Batter', 'mushroom-corn-masala-dosa-recipe-using-ragi-idli-dosa-batter', 'Mushroom Corn Masala Dosa Recipe Using Ragi Idli Dosa Batter is a fusion recipe, where a crispy South Indian Ragi dosa is stuffed with chatpata pav bhaji Corn & Mushroom masala.', '["To make the Ragi Dosa Batter", "2 cups White Urad Dal (Whole) , soaked overnight", "3 teaspoon Methi Seeds (Fenugreek Seeds) , soaked overnight", "1 cup Idli Rice , soaked overnight", "2 cups Ragi Seeds , soaked overnight", "Ghee , to make the dosas", "2 Onions , finely chopped", "1 Green Bell Pepper (Capsicum) , finely chopped", "6 cloves Garlic , finely chopped", "400 grams Button mushrooms , sliced", "1 cup Sweet corn , steamed", "1/4 cup Homemade tomato puree", "1 tablespoon Pav bhaji masala", "1/2 teaspoon Red Chilli powder", "1 tablespoon Tomato Ketchup , sweet and spicy", "Salt , to taste", "1/4 cup Mint Leaves (Pudina) , chopped"]'::jsonb, ARRAY['tomato', 'ghee make', 'ragi seeds', 'pav bhaji masala', 'salt', 'mint leaves (pudina)', 'idli rice', 'red chilli powder', 'cloves garlic', 'onion', 'methi seeds (fenugreek seeds)', 'sweet corn', 'green bell pepper (capsicum)', 'button mushrooms', 'tomato ketchup sweet spicy', 'white urad dal']::text[], '["To begin making the Mushroom Corn Masala Dosa Recipe Using Ragi Idli Dosa Batter, we will first make the Ragi dosa Idli Batter."]'::jsonb, 35, 'Fusion', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Mushroom_Corn_Masala_Dosa_Using_Ragi_Idli_Dosa_Batter_Video__8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1246.Mushroom_Corn_Masala_Dosa_Using_Ragi_Idli_Dosa_Batter_Video__8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Peanut Chutney Podi Recipe', 'peanut-chutney-podi-recipe', 'Peanut Chutney Podi recipe is a perfect blend of roasted peanuts, garlic cloves, cumin seeds, coriander seeds, tamarind, curry leaves and chillies. It is a very easy recipe to prepare and can be stored for days without getting spoilt. Given its longevity, it makes for a great travel food without the fear of leakage like with pickles that we normally take along when travelling.', '["2 cups Roasted Peanuts (Moongphali) , deskinned", "6 Dry Red Chillies", "4 cloves Garlic", "1 teaspoon Cumin seeds (Jeera)", "2 teaspoons Coriander (Dhania) Seeds", "1 sprig Curry leaves", "15 grams Tamarind", "Salt , to taste"]'::jsonb, ARRAY['salt', 'peanuts (moongphali) deskinned', 'cloves garlic', 'curry leaves', 'dry red chillies', 'coriander (dhania) seeds', 'cumin seeds (jeera)', 'tamarind']::text[], '["To begin making the Peanut Chutney Podi Recipe, into a preheated pan add the dry red chillies, cumin seeds,coriander seeds and roast for about two minutes on medium heat till the cumin seeds start to turn brown in colour.", "Add the garlic pods and curry leaves to the pan and saute till the curry leaves become crisp.", "Keep aside to cool.Once the roasted ingredients are cooled add them to a chopper or blender along with the tamarind, roasted peanuts and salt to taste.", "Blend to make a coarse powder.", "If you over blend then the podi becomes a paste and becomes sticky with all the oils released from the peanuts.", "So while blending stop in between and pulse a couple of times.Transfer\u00a0Peanut Chutney Podi Recipe into an airtight jar.", "Serve\u00a0Peanut Chutney Podi Recipe\u00a0with\u00a0Jolada Roti Recipe (Jowar Bhakri)\u00a0or\u00a0Homemade Soft Idli\u00a0and\u00a0Tomato Garlic Chutney Recipe."]'::jsonb, 10, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Peanut_Chutney_Podi_Video_Recipe_16_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1247.Peanut_Chutney_Podi_Video_Recipe_16_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kanchipuram Masala Dosa Recipe With Soya Dosa Batter', 'kanchipuram-masala-dosa-recipe-with-soya-dosa-batter', 'Kanchipuram Masala Dosa is a breakfast recipe that is stuffed with beetroot, carrot, onion and regular potato masala. This is available in many local restaurants in Kerala and Tamil Nadu. Dosa is a favorite breakfast recipe, try to make variations by adding some vegetables which ends up making it a healthy start for your day. Kanchipuram Masala Dosa is a healthy way to treat your kids with some vegetables along with the dosa.', '["2 cups Idli Rice", "1 cup Soybeans (Whole Soya dal)", "1-1/4 cups White Urad Dal (Whole)", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Chana dal (Bengal Gram Dal)", "4 teaspoons Salt", "Water , as needed", "1 Onion , thinly sliced", "1 Carrot (Gajjar) , grated", "1 Beetroot , grated", "1 Green Chilli , finely chopped", "1 teaspoon Oil", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 teaspoon Chana dal (Bengal Gram Dal)", "2 Onions , thinly sliced", "1 inch Ginger , finely chopped", "2 Green Chillies , slit", "1 sprig Curry leaves", "3 Potatoes (Aloo) , boiled, coarsely mashed", "Salt , to taste", "1/4 teaspoon Turmeric powder (Haldi)", "Other Ingredients", "2 tablespoons Idli Dosa Podi (Milagai Powder)", "Ghee , for cooking dosa"]'::jsonb, ARRAY['carrot', 'curry leaves', 'white urad dal (split)', 'onion', 'idli dosa podi (milagai powder)', 'turmeric powder', 'green chillies', 'chana dal (bengal gram dal)', 'sunflower oil', 'white urad dal', 'salt', 'green chilli', 'beetroot', 'soybeans (whole soya dal)', 'mustard seeds', 'idli rice', 'water', 'methi seeds (fenugreek seeds)', 'ginger', 'potato (aloo)']::text[], '["To begin making Kanchipuram Masala Dosa, first prepare the soya dosa batter.", "You can also use a regular dosa batter as well, if you have it handy.To begin making the High Protein Soya Idli & Dosa Batter, first we will soak all the ingredients.", "Soak the soy bean separately in a bowl.", "In a bowl soak the urad dal, methi seeds and chana dal together.", "In another bowl, soak the rice.", "Soak them for at least 6 hours or overnight.Once soaked, you can grind them.", "Into a mixer grinder, add the soaked urad dal and methi seeds.", "Add little water at a time and grind to make a thick flowing batter.Transfer the ground urad dal into a large bowl.", "In the same mixer grinder, add the rice and add just little water at a time and make thick batter.", "Transfer the rice into the same bowl as the urad dal.", "Similarly, grind the soaked soya bean adding little water at a time to make a thick batter and add it to the same bowl as the rice and dal.Add the salt and stir well to combine.", "Cover the bowl and\u00a0ferment the High Protein Soya Idli & Dosa Batter for 8 hours/ overnight.", "Once fermented, give it a stir gently.", "You can make idli the first day when batter is fresh with air pockets.", "Refrigerate the High Protein Soya Idli & Dosa Batter in an airtight container for 4 to 5 days and use it as required.The next step is to cook the Potato Masala for the\u00a0Kanchipuram masala dosa.Preheat the oil in a pan over medium heat.", "Add mustard, urad dal and chana dal and allow the dals to roast on low to medium heat until it becomes golden and crisp.Once the dals are well roasted, add the onions, green chillies, ginger and curry leaves.", "Saute until the onions soften and turn golden in color.Once the onions have softened, add the cooked and coarsely mashed potatoes, salt, turmeric powder and stir to combine.", "Cover the pan and allow the flavours to get induced into the potato masala.Check the salt and spices and adjust to suit your taste.", "Turn off the heat and keep the potato masala aside.The next step is to cook the\u00a0Vegetable Masala\u00a0for the\u00a0Kanchipuram masala dosa.In another pan add preheat some oil over medium heat.", "Add chopped onion and green chillies and saute until the onions soften.Once the onions soften, add the grated beetroot, carrot and sprinkle some salt to taste.", "Saute and cook until the vegetables soften and become tender.", "Cover and cook to fasten the cooking process.Once the vegetables are cooked, turn off the heat and keep aside.The final step is to make the\u00a0Kanchipuram masala dosa.Preheat the dosa skillet over medium heat.", "Pour a ladleful of dosa batter, spread the batter in a circular motion from the inside to the out, to make a thin crepe.", "Drizzle ghee around the dosa and allow the dosa to cook through.You will notice that it starts to turn brown from the bottom.Once dosa is cooked, spread a tablespoon of\u00a0Idli dosa milagai podi, the potato masala on one half and top it with sauteed beetroot & carrots.", "Fold the crisp Kanchipuram dosa and serve.Serve the Kanchipuram Masala Dosa immediately along with onion sambar and coconut chutney\u00a0for a wholesome breakfast."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Kachipuram_Dosa_Recipe_Video_With_Soya_Dosa_Batter_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1248.Kachipuram_Dosa_Recipe_Video_With_Soya_Dosa_Batter_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Avocado Raita Recipe', 'avocado-raita-recipe', 'Avocado Raita Recipe is a simple yogurt based salad made with pureed avocado, roasted peanuts and chillies. The Avocado raita is quick to make and is wholesome and nutritious too. Serve the Avocado raita along with Parathas for breakfast to make a wholesome meal.', '["1 Avocado , peeled and pureed", "1 Green Chilli", "1-1/2 cup Curd (Dahi / Yogurt)", "1 tablespoon Roasted Peanuts (Moongphali) , crushed", "Coriander (Dhania) Leaves , a bunch, finely chopped", "1 teaspoon Cumin powder (Jeera) , roasted", "1/2 teaspoon Chaat Masala Powder", "Salt , to taste", "Red Chilli powder , to taste"]'::jsonb, ARRAY['avocado', 'reen chilli', 'curd', 'dahi / yogurt', 'roasted peanuts', 'moongphali', 'coriander', 'dhania', 'cumin powder', 'jeera', 'chaat masala powder', 'salt', 'red chilli powder']::text[], '["To prepare the Avocado Raita, take the peeled avocado, scoop out the flesh and roughly chop it up into small bits.Put the chopped avocado bits into the blender.", "Add the 2-3 tablespoons of yogurt, salt, coriander leaves, chat masala, cumin powder and green chilli and blend them together to form a smooth paste.In another bowl, pour in the remainder of the yogurt beat it gently, adding in the avocado mixture at this stage.", "Check the salt and adjust to suit your taste.Finally, add the roasted peanuts and sprinkle red chilli powder into the Avocado Raita just before serving.", "Serve the Avocado raita along with\u00a0Parathas\u00a0for breakfast to make a wholesome meal."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Raitas/Avocado_Raita_Recipe_Avocado_Yogurt_Cold_Soup_Salad-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1249.Avocado_Raita_Recipe_Avocado_Yogurt_Cold_Soup_Salad-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kuruku Kaalan Recipe - Raw Bananas in Coconut Curry', 'kuruku-kaalan-recipe-raw-bananas-in-coconut-curry', 'Kuruku Kaalan Recipe is a delicious dish made from ripe bananas and cooked in a yogurt and coconut curry. It is a delectable traditional dish in Kerala cuisine, that is eaten almost every other day and is also a part of the famous Onam sadya.', '["2 Raw Banana , peeled and diced", "1 teaspoon Turmeric powder (Haldi)", "1 cup Curd (Dahi / Yogurt)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "Salt , to taste", "Ingredients to be ground", "2 Green Chillies", "1 teaspoon Cumin seeds (Jeera)", "1 cup Fresh coconut , freshly grated", "Ingredients for the seasoning", "1 teaspoon Coconut Oil", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/8 teaspoon Methi Seeds (Fenugreek Seeds)", "2 Dry Red Chillies , slit into two", "2 sprig Curry leaves"]'::jsonb, ARRAY['raw banana', 'turmeric powder', 'haldi', 'curd', 'dahi / yogurt', 'red chilli powder', 'salt', 'ingredients to be ground', 'reen chillies', 'cumin seeds', 'jeera', 'fresh coconut', 'ingredients for the seasoning', 'coconut oil', 'mustard seeds', 'rai/ kadugu', 'methi seeds', 'fenugreek seeds', 'dry red chillies', 'curry leaves']::text[], '["To prepare Kuruku Kaalan Recipe (Raw Bananas in Coconut Curry), in a saucepan or a pressure cooker, cook the banana pieces, turmeric powder, a few curry leaves and salt along with 1/4 cup of water until the bananas are soft.Once done, open the cooker and stir in the yogurt and chili powder and keep this aside.Next, grind the grated coconut along with green chillies and cumin seeds into a fine paste.Add the ground coconut mixture to the raw banana and yogurt curry and bring the mixture to a boil in the saucepan or pressure cooker you cooked the raw bananas in.While the Kaalan is coming to a boil, we will prepare the seasoning for the Kaalan.Heat coconut oil in a small pan; add in the mustard seeds, cumin seeds, fenugreek seeds, curry leaves and red chilies.", "Allow them to roast and crackle on medium heat.Once roasted pour the seasoning into the Kurukku Kaalan and stir till everything blends together well.Turn off the heat and transfer the Kurruku Kaalan to a serving bowl and serving warm.Serve the Kuruku Kaalan (Raw Bananas in Coconut Curry)\u00a0along with steamed rice for a dinner or family sunday lunch."]'::jsonb, 55, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Kuruku_Kaalan_Recipe_Raw_Bananas_in_Coconut_Curry-7.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1250.Kuruku_Kaalan_Recipe_Raw_Bananas_in_Coconut_Curry-7.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chai Ka Masala Recipe - Homemade Spice Powder for Tea', 'chai-ka-masala-recipe-homemade-spice-powder-for-tea', 'On cold winter days and in wet monsoons, a hot steaming cup of Masala tea is what you need to give that instant energy and warmth. Addition of spices make the tea healthier.The secret behind a perfect cup of Masala tea is the Chai ka Masala or Masala Tea Powder.You can store it for 4-6 months in an air-tight container.', '["1/4 cup Cardamom (Elaichi) Pods/Seeds", "1/4 cup Cloves (Laung)", "1/4 cup Dry ginger powder", "1 tablespoon Whole Black Peppercorns", "2 inch Cinnamon Stick (Dalchini)", "1 teaspoon Nutmeg powder"]'::jsonb, ARRAY['nutmeg powder', 'cardamom (elaichi) podsseeds', 'black peppercorns', 'dry ginger powder', 'cinnamon stick (dalchini)', 'cloves (laung)']::text[], '["To begin making Chai ka Masala, place a pan on medium heat.", "Add cloves, cardamom, black peppercorns and cinnamon, one by one, in no particular order.Dry roast the spices on medium heat for a couple of minutes until they release a roasted aroma.", "Turn off the heat and transfer the spices to a plate and allow them to cool.Once the spices have cooled, add the dried ginger powder, nutmeg powder and blend the roasted spice mixture in a blender to a smooth powder.Your Chai ka Masala is ready.", "Transfer the masala to an airtight container and store it for 4 to 6 months in a glass jar in the freezer and use and when required.Add 1/4 teaspoon Chai Masala powder to make 2 cups of Chai (Tea).", "Adjust the masala to suit your taste.", "If you like black tea, then add a pinch and if you are making tea along with milk then 1/4 teaspoon for two cups would give you a mild flavor.", "Every Chai lover has a preference in their ways the tea has to be made, so go ahead and experiment and enjoy this delicious Chai Masala."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/BasicRecipes_Spice_Powders/Tea_Masala_Powder_Recipe_Archanas_Kitchen.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1251.Tea_Masala_Powder_Recipe_Archanas_Kitchen.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Oats Mor Kali Recipe - Oats & Buttermilk Breakfast Porridge', 'oats-mor-kali-recipe-oats-buttermilk-breakfast-porridge', 'Oats Mor Kali or Oats Buttermilk Porridge is a traditional South Indian dish that originates from Tamil Nadu, which is generally prepared using buttermilk, with rice flour as the base. Tasty, nutritious and easy to digest, the dish resembles sooji and makes for a very healthy breakfast option. In this recipe, instead of the rice flour, oats has been used as the base which takes the nutrient quotient up a notch. Learn how to make tangy and tasty Oats Mor Kali by following the recipe below.', '["7 Green Chillies , (milagai-bhajji variety)", "3 cups Instant Oats (Oatmeal)", "3 cups Buttermilk", "1/4 teaspoon Asafoetida (hing)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "2 Green Chillies , finely chopped", "5 Curry leaves , roughly chopped", "Salt , to taste", "Ghee , for serving", "Oil , to cook"]'::jsonb, ARRAY['reen chillies', 's instant oats', 'oatmeal', 's buttermilk', 'asafoetida', 'hing', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'curry leaves', 'salt', 'ghee', 'oil']::text[], '["To begin making the Oats Mor Kali Recipe,\u00a0heat 2 tablespoons cooking oil in a small fry pan on low flame.", "Next, add the sun-dried green chillies to the oil in the vessel and deep fry them, stirring continuously.", "Once done, remove from the pan and keep aside.Next to prepare the seasoning; add a teaspoon of oil into a small pan.", "Add\u00a0in the mustard seeds and urad and allow it to crackle.", "Allow the urad to roast and turn lightly brown.", "Once they begin to crackle, add the green chilli and asafoetida and saute them for a few seconds and keep aside.In the next step we will cook the oats mor kazhi.Add 3 cups of the oats in another heavy bottomed pan, and roast them for 3 minutes on medium heat, stirring continuously.", "Next stir in the 3 cups of the buttermilk and the seasoning into oats and buttermilk mixture together with the curry leaves and mix all the ingredients in the pan.Add salt to taste and mix again, stirring the mixture continuously on medium heat until all the water is completely absorbed.", "The final outcome should be of a thick pudding consistency.", "Garnish the Oats Mor Kali with coriander leaves and the fried dried chillies (mor milagai).Serve the Oats Mor Kali for quick breakfast or even a light lunch."]'::jsonb, 30, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breakfast_Tiffins/Oats_Mor_Kali_Recipe_Breakfast_South_indian_Oatmeal-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1252.Oats_Mor_Kali_Recipe_Breakfast_South_indian_Oatmeal-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vendakkai Puli Kuzhambu', 'vendakkai-puli-kuzhambu', 'The Kerala Bhindi Curry also known as the Vendakkai Puli Kuzhambu is a tangy and spicy curry made from okras also known as lady''s fingers. The curry is cooked in a tamarind and tomato curry base and flavored with baby onions, fenugreek seeds, coriander powder and curry leaves.', '["1 cup Tamarind Water", "1 tablespoon Coconut Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 sprig Curry leaves", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "2 Dry Red Chillies", "10 Shallots , quartered", "4 cloves Garlic , roughly chopped", "200 grams Bhindi (Lady Finger/Okra)", "3 Homemade tomato puree", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "2 teaspoons Coriander Powder (Dhania)", "Salt , to taste", "Oil , as required"]'::jsonb, ARRAY['tamarind water', 'coconut oil', 'mustard seeds', 'rai/ kadugu', 'curry leaves', 'methi seeds', 'fenugreek seeds', 'dry red chillies', 'shallots', 's garlic', 's bhindi', 'lady finger/okra', 'homemade tomato puree', 'turmeric powder', 'haldi', 'red chilli powder', 's coriander powder', 'dhania', 'salt', 'oil']::text[], '["To begin making the Vendakkai Puli Kuzhambu (Kerala Style Bhindi Curry) first get all the ingredients ready and keep aside.", "Make the tamarind water according to instructions and keep aside.To begin, heat oil in a saucepan on medium heat.", "Add the mustard seeds and allow them to crackle.", "Add the fenugreek seeds, red chillies and curry leaves and roast them for a few seconds.", "Add the onions and garlic and saute them until the onions have turned translucent.Finally add the chopped vendakkai (okra) and stir fry until it becomes slightly soft and cooked.Once the vendakkai is cooked a little, add the tomato puree, turmeric powder, red chili powder, coriander powder and the tamarind water.", "Add a little more water is required to adjust the consistency of the Kuzhambu.Add salt to taste and give the mixture a stir.", "Bring the Vendakkai Puli Kuzhambu to a brisk boil.Once it comes to a boil, turn the heat to low, cover the pan with the lid slightly ajar and simmer for about 10 minutes until the curry thickens and the vendakkai is cooked through.Once done, turn off the heat and serve the Vendakkai Puli Kuzhambu along with a hot bowl of steamed rice and ghee for\u00a0a delicious\u00a0Sunday lunch meal."]'::jsonb, 45, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Vengayam_Puli_Kuzhambu_Recipe_Small_Onion_Tangy_Spicy_Curry-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1253.Vengayam_Puli_Kuzhambu_Recipe_Small_Onion_Tangy_Spicy_Curry-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Style Pomfret Shorshe Recipe - Pomfret In Mustard Gravy', 'bengali-style-pomfret-shorshe-recipe-pomfret-in-mustard-gravy', 'Pomfret Shorshe (Pomfret in mustard gravy) is an authentic Bengali recipe which is made with pomfret fish. This is one of easiest recipe with minimal ingredients. Mustard sauce gravy can be used to cook other fishes like hilsa, rohu, catla, catfish and various other river fishes.', '["2 Pomfret fish", "2 tablespoon Mustard oil , for frying", "2 tablespoon Mustard oil , for cooking", "4 clove Garlic , chopped", "3 Green Chillies , slitted", "1 teaspoon Kalonji (Onion Nigella Seeds)", "1-1/2 tablespoon Mustard seeds (Rai/ Kadugu) , ground into paste", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , as per taste"]'::jsonb, ARRAY['salt', 'kalonji (onion nigella seeds)', 'pomfret fish', 'mustard oil', 'green chillies ted', 'cloves garlic', 'turmeric powder', 'mustard seeds ground paste']::text[], '["To begin making the Pomfret Shorshe recipe, firstly marinate the fish with salt and turmeric for about an hour.Grind and make a paste with mustard seeds in a grinder.", "Add a pinch of salt and turmeric, keep for 15 minutes.To the kadai/wok, add mustard oil and fry the fishes lightly from both sides until cooked through.", "Keep them aside.To the same kadai add more oil if required, add nigella seeds, garlic and green chillies.Once the aroma of garlic comes add the mustard paste.Cook for a minutes with constant stirring on medium flame.Add water as per gravy requirement, cook it for 2-3 minutes.", "Add the fishes and cook for another 3-4 minutes.Switch off the heat, drizzle a little mustard oil and keep it covered for 10 minutes before serving with white rice.The usage of mustard oil and mustard paste is what makes Pomfret Shorshe heavenly when had with hot white rice."]'::jsonb, 45, 'Bengali', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Non_Veg_Recipes/Bengali_Style_Pomfret_Shorshe_Recipe_Pomfret_In_Mustard_Gravy-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1254.Bengali_Style_Pomfret_Shorshe_Recipe_Pomfret_In_Mustard_Gravy-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Chama Dumpa Pulusu Recipe - Arbi With Sesame Tamarind Sauce Recipe', 'andhra-style-chama-dumpa-pulusu-recipe-arbi-with-sesame-tamarind-sauce-recipe', 'Andhra Style Chama Dumpa Pulusu Recipe (Arbi With Sesame Tamarind Sauce Recipe) is a traditional dish that we have inherited from our ancestors, made using boiled arbi that is simmered in sesame tamarind sauce. It is a perfect to make during weekdays lunch or dinner.', '["250 grams Colocasia root (Arbi)", "2 teaspoons Tamarind Paste", "4 Green Chillies , slit", "3 tablespoons Sesame seeds (Til seeds)", "Salt , to taste", "Oil , as required", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Turmeric powder (Haldi)", "Curry leaves , few", "Coriander (Dhania) Leaves , Few sprigs, chopped"]'::jsonb, ARRAY['green chillies', 'salt', 'coriander (dhania) leaves', 'mustard seeds', 'curry leaves', 'colocasia root (arbi)', 'cumin seeds (jeera)', 'tamarind paste', 'turmeric powder', 'sesame seeds (til seeds)', 'sunflower oil']::text[], '["To begin making the Arbi With Sesame Tamarind Sauce recipe, Peel the arbi, cube them into bite size pieces and boil until tender.Soak the tamarind in enough water for 10 minutes and extract the pulp.Dry roast the sesame seeds until golden and set aside to cool down.", "Once cooled down, grind into powder.In a deep pan add the oil, once it''s hot add the mustard, cumin seeds and allow them to pop.Next stir in the turmeric, green chillies and curry leaves.", "Saute for few seconds.Now add the arbi pieces and fry for couple of minutes.Later add in the tamarind extract and salt.", "Give it a good stir and simmer for couple of minutes.Now add the sesame powder and cook for couple more minutes.Lastly sprinkle some chopped coriander and serve hot.", "Serve Arbi With Sesame Tamarind Sauce along with\u00a0Phulkas\u00a0and\u00a0Kachumber Salad\u00a0for a weekday lunch or dinner."]'::jsonb, 40, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/5-jan/Arbi_With_Sesame_Tamarind_Sauce_Recipe_Chama_Dumpa_Pulusu-1-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1255.Arbi_With_Sesame_Tamarind_Sauce_Recipe_Chama_Dumpa_Pulusu-1-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kobbari Charu Recipe - Coconut Milk & Dal Sambar Recipe', 'kobbari-charu-recipe-coconut-milk-dal-sambar-recipe', 'Kobbari chaaru is an authentic sambar/rasam that is made in Telangana region using coconut milk and roasted chana dal. This Coconut Milk & Dal Sambar is silky smooth in texture with subtle sweetness of coconut milk and mildly spicy with ground green chillies, overall making this a perfect lunch combo with hot steamed rice and fryum (Akki Peni sandige) or just with Phulka Recipe (Roti/Chapati) - Puffed Indian Bread.', '["2-1/2 cups Coconut milk", "1 cup Water", "1/4 cup Roasted Gram Dal (Pottukadalai)", "8 Green Chillies , adjustable", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Turmeric powder (Haldi)", "Curry leaves , few", "Salt , to taste", "Coriander (Dhania) Leaves , few sprigs, chopped (optional)"]'::jsonb, ARRAY['salt', 'coriander (dhania) leaves', 'mustard seeds', 'gram dal (pottukadalai)', 'water', 'curry leaves', 'cumin seeds (jeera)', 'coconut milk', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["Start preparing Kobbari Chaaru Recipe (Coconut Milk & Dal Sambar) by preparing coconut milk.", "Scrape the white flesh of half of the freshly opened coconut and grind in a blender using around 2 cups of water.Strain with a sieve to extract coconut milk.Grind the roasted chana dal along with green chillies into a fine paste in a Mixer adding water as required and set aside until required.Now heat a Kadai with oil.", "Add mustard, cumin seeds and curry leaves.", "Let them splutter for few seconds.Add turmeric, water, coconut milk, salt and bring this to boil.As soon as it starts boiling, stir in the ground dal paste and mix well.", "Make sure that there are no lumps, by stirring while you add the paste.Bring the mixture to boil and at this stage, it resembles kadhi.Lastly, sprinkle with coriander leaves and turn off the heat.Scrumptious Kobbari Chaaru Recipe (Coconut Milk & Dal Sambar) is ready to be served for lunch with steamed rice\u00a0and\u00a0fryum\u00a0(Akki Peni sandige)\u00a0or just\u00a0Phulka Recipe (Roti/Chapati) - Puffed Indian Bread."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/5-jan/Kobbari_Chaaru_Recipe_Coconut_Milk_and_Dal_Sambar_Existing_Recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1256.Kobbari_Chaaru_Recipe_Coconut_Milk_and_Dal_Sambar_Existing_Recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sadya Parippu Recipe - Kerala Style Lentils', 'sadya-parippu-recipe-kerala-style-lentils', 'Parippu or Lentil Curry is a very simple dish that is also a part of the Onam sadyaa. Served with piping hot rice, the dish is a delicate and simple balance of flavours that prepares the palate to the explosion of flavours in the dishes that follow thereafter. The parippu can be prepared in a variety of ways using different kinds of lentils. Using Green Gram lentils (Moong Dal) or Split Pigeon Dal, one can prepare a nutritious and beautiful dish that is delectable in its simplicity.', '["1/2 cup Arhar dal (Split Toor Dal)", "6 Shallots , finley sliced", "2 cloves Garlic , finely chopped", "1 inch Ginger , finely chopped", "2 Green Chillies , slit lengthwise", "1/2 tablespoon Coconut Oil", "2 sprig Curry leaves , crushed between the palms to enhance flavour"]'::jsonb, ARRAY['arhar dal', 'split toor dal', 'shallots', 's garlic', 'ginger', 'reen chillies', 'coconut oil', 'curry leaves']::text[], '["To begin making the Sadya Parippu recipe, pressure cook the split pigeon pea or toor dal in two cups of water along with the pearl onions, garlic, ginger, green chillies, a few curry leaves, a pinch of salt.", "See video recipe of how to cook lentils in a pressure cookerOnce the pressure is released in the cooker, and mash the lentils lightly with a masher.", "Check the salt levels and add more if required.", "Now, add in the fresh coconut oil or ghee and the curry leaves to the dal.", "Cover this and simmer on low heat for about 5 minutes.Serve the steaming hot Sadya Parippu\u00a0with rice, a drop of ghee and crispy pappadams.Note:This dish uses split pigeon peas, which do not require much water for cooking.", "On the other hand, if you are using green gram lentils or moong dal, make sure you add at least 1 and 1/2 cups of water for 1/2 cup of the lentils, to ensure the lentils are cooked well and are also the right consistency.Adding garlic and pearl onions is important but not mandatory.", "Parippu prepared for sadya can make do without these ingredients.The dish needs to be of semi-thick consistency.", "Therefore adjust the cooking accordingly.Winter melon, ash gourd or yellow cucumber cubes can also be added to the cooked dal or placed in the dal before cooking.", "These vegetables make the dish nutritious and healthy.Serve\u00a0Sadya Parippu along with\u00a0Steamed Rice\u00a0and\u00a0Elai Vadam\u00a0for a weekday meal."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Sadya_Parippu_Recipe_Kerala_Style_Lentils_Onam_Festival_-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1257.Sadya_Parippu_Recipe_Kerala_Style_Lentils_Onam_Festival_-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Papad er Dalna Recipe - Bengali Papad Curry', 'papad-er-dalna-recipe-bengali-papad-curry', 'Papad er Dalna is a Bengali recipe that is prepared specially during Durga Puja. It provides the "pujo pujo aroma " (the essence of Durga Puja). This recipe is quick and easy for the days you are too lazy to cook up an extravagant meal.', '["4 Papad , (Masala papad)", "4 Potato (Aloo)", "1 Tomato", "1 inch Ginger , grated", "1 Bay leaf (tej patta)", "1 Dry Red Chilli", "1/1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Sugar", "1 teaspoon Garam masala powder", "Salt , to taste", "2 teaspoon Oil", "1 teaspoon Ghee"]'::jsonb, ARRAY['papad (masala papad)', 'tomato', 'cumin powder (jeera)', 'ginger', 'salt', 'bay leaf (tej patta)', 'ghee', 'potato (aloo)', 'red chilli powder', 'dry red chilli', 'sugar', 'cumin seeds (jeera)', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin preparing the Papad er Dalna, wash and peel the potatoes and then cut them into half.", "Cut each potato in half and into 3 pieces (dalna style).Puree the tomatoes in a mixer.Heat oil in a pan and fry potato pieces till they turn golden brown and keep them aside.Break each papad into 4 pieces and fry them in the remaining oil.", "It takes approximately 20-30 seconds to fry 4 pieces of papad in high flame.Strain the fried papad from oil.Temper the remaining oil with bay leaf; dry red chilli and whole cumin seeds and wait till the tempering starts to crackle.Now add tomato puree to the tempering and start cooking in medium flame till the aroma of raw tomato goes, and then add ginger paste to the mixture and cook on medium flame till the oil separates from the mixture.Now, mix turmeric powder; red chilli powder and cumin powder with 1 tsp of water and make a thick paste and add this paste to the tomato puree and mix properly.Add sugar and salt in the mixture and then add a teaspoon of water and cook till the oil separates.Add fried potatoes to this mixture and coat properly with spices and add 1.5 cup of water.Cover the pan with a lid and cook till the potatoes are cooked properlyAfter the potatoes are done adjust the water and place fried papad on the top of potato and again cover the pan with a lid and cook for 3-4 minutes.Open the lid and mix the gravy carefully as the papad will be completely soft by now.Add garam masala powder and ghee to the curry and cook for 2 more minutes and turn off the gas once done.Papad er Dalna is now ready to be served with\u00a0phulka,\u00a0paratha\u00a0or steamed rice."]'::jsonb, 65, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/19-Jan/Papad_er_Dalna_bengali_style_papad_curry_Recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1258.Papad_er_Dalna_bengali_style_papad_curry_Recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pori Urundai Recipe - Healthy Puffed Rice Balls With Jaggery', 'pori-urundai-recipe-healthy-puffed-rice-balls-with-jaggery', 'Pori Urundai or Puffed Rice Balls is a traditional sweet preparation made using puffed rice mixed with jaggery. The crunchiness of the rice and the sweetness of it, makes this dish tasty and one that is easy to prepare.', '["4 cups Puffed rice , cleaned sifted", "1/2 cup Jaggery", "1/4 cup Water", "1/4 teaspoon Cardamom Powder (Elaichi) , or edible camphor powder"]'::jsonb, ARRAY['s puffed rice', 'jaggery', 'water', 'cardamom powder', 'elaichi']::text[], '["To begin this Pori Urundai Recipe (Healthy Puffed Rice Balls with Jaggery), heat a heavy bottom pan on medium heat.", "Add jaggery and water to the pan and bring them to a boil, continuing to do so until the jaggery melts completely.Once it is done, use a strainer to remove any coarse particles from the jaggery.Next, pour the strained jaggery back into the pan and heat it on medium heat, bringing it to a boil.Once the jaggery is thickened sufficiently (enough to get a pearl-like consistency when dropped in a little water), add the puffed rice and the camphor/ cardamom powder to the pan and mix them together evenly.", "Turn off the heat when done, and set aside for a few minutes to cool.", "Take a small portion of the mixture between oiled hands and shape it into a medium or large lemon sized balls.", "Do this as soon as possible because the mixture will take its shape and firm up when it cools down completely.", "Repeat this process for all the remaining mixture.Finally, allow the Pori Urundai to dry a bit till it comes down to room temperature.", "Store the Pori Urundai\u00a0or the Puffed Rice Balls in an airtight container."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Puffed_Rice_Balls_Pori_Urandai_shutterstock_171188534.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1259.Puffed_Rice_Balls_Pori_Urandai_shutterstock_171188534.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Menthya Matvadi Palya Recipe - Madhwa Brahmin Style Methi-Chana Dal Sabzi', 'menthya-matvadi-palya-recipe-madhwa-brahmin-style-methi-chana-dal-sabzi', 'Matwadi Palya Recipe is essentially a Madhwa Brahmin Style Methi-Chana Dal Sabzi which uses ground masala which is steamed and then mixed with the other sauteed ingredients like fenugreek leaves. This side dish is great for high protein vegetarian diet since methi and dal are rich in proteins. In addition, methi is a source of ample iron.', '["50 grams Methi Leaves (Fenugreek Leaves)", "1 tablespoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "2 Dry Red Chillies", "Salt , to taste", "To Grind", "1/2 cup Chana dal (Bengal Gram Dal) , soaked for 2 hours", "1/2 cup Fresh coconut , grated", "6 Dry Red Chillies", "1 teaspoon Coriander (Dhania) Seeds", "Curry leaves , few", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Asafoetida (hing)"]'::jsonb, ARRAY['salt', 'mustard seeds', 'coconut', 'asafoetida (hing)', 'methi leaves (fenugreek leaves)', 'curry leaves', 'curry leaves', 'dry red chillies', 'coriander (dhania) seeds', 'cumin seeds (jeera)', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To prepare Matwadi Palya Recipe (Madhwa Brahmin Style Methi-Chana Dal Sabzi); drain the water from the soaked channa dal and grind all the ingredients mentioned under \"to grind\" adding very little water to make a coarse paste.In a steamer, steam the ground masala till soft, for about 10 minutes on high heat using Idli molds.Meanwhile, wash and chop the methi leaves finely.In a kadai, heat oil and mustard seeds and allow it to splutter, add the red chillies and curry leaves and roast for a few seconds.Add finely chopped methi leaves and salt and allow it to wilt down.", "Once the methi leaves are cooked, add the ground chana dal mixture and mix them and allow it to cook on low flame till everything combines well.", "Turn off heat.", "Check the salt and adjust accordingly to taste.Serve Matwadi Palya Recipe (Madhwa Brahmin Style Methi-Chana Dal Sabzi) along with\u00a0Tawa paratha, Karnataka Special Huli Tovve Recipe\u00a0and steamed rice for lunch or dinner."]'::jsonb, 135, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/19-Jan/Menthya_Matvadi_Palya_Recipe_Madhwa_Brahmin_Style_Methi-Chana_Dal_Sabzi-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1260.Menthya_Matvadi_Palya_Recipe_Madhwa_Brahmin_Style_Methi-Chana_Dal_Sabzi-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lasun Batata Poori Recipe - Spiced Coriander Fried Bread Recipe', 'lasun-batata-poori-recipe-spiced-coriander-fried-bread-recipe', 'Lasun Batata Poori Recipe (Spiced Coriander Fried Bread Recipe) is a deep fried Indian bread flavoured with some indian spice and fresh herb like coriander leaves to bring out the flavour to the dish. These pooris are quite soft as it contains potato in the dough. You can also add any starchy vegetables like colocasia or tapioca to the bread.', '["1 cup Potatoes (Aloo) , boiled and mashed", "1 1/2 cup Whole Wheat Flour", "4 cloves Garlic , minced", "2 sprig Coriander (Dhania) Leaves", "1 tablespoon Amchur (Dry Mango Powder)", "1 tablespoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin seeds (Jeera)", "Salt , to taste", "1 teaspoon Baking soda", "Oil , for deep frying"]'::jsonb, ARRAY['potatoes', 'aloo', 'whole wheat flour', 's garlic', 'coriander', 'dhania', 'amchur', 'dry mango powder', 'red chilli powder', 'turmeric powder', 'haldi', 'cumin seeds', 'jeera', 'salt', 'baking soda', 'oil']::text[], '["We begin making the Lasun Batata Poori Recipe (Spiced Coriander Fried Bread Recipe) by boiling the potato in a pressure cooker without skin and mash it completely and keep it ready.", "Combine the rest of the ingredients \u00a0in a bowl.", "Now add mashed potato and knead the flour into a dough.", "Keep it aside for 10 minutes.Take a deep bottom vessel. add oil and let it heat.Now divide the dough into equal parts and flatten into circles like poori.", "Once the oil is hot, start frying the poori till it is golden brown on either side.", "Serve the\u00a0Lasun Batata Poori Recipe (Spiced Coriander Fried Bread Recipe) along with Chutney to enjoy your Lunch meal."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/5-jan/_lasun_batata_poori_recipe_garlic_potato_puri-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1261._lasun_batata_poori_recipe_garlic_potato_puri-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kaju Pista Roll Recipe - Cashew Nut Pistachio Fudge', 'kaju-pista-roll-recipe-cashew-nut-pistachio-fudge', 'The Kaju Pista Roll Recipe is a delectable recipe that is packed with flavors from cashew Nut Pistachios and made into a fudge. The Kaju Pista Roll is most often made during festivals like diwali or on special occasions like weddings or as a gift for someone you love.', '["1 cup Cashew nuts", "1 cup Pistachios", "3/4 cup Condensed Milk , sweetened", "2 teaspoon Ghee", "2 tablespoons Milk Powder", "1/2 cup Sugar , powdered", "1 teaspoon Rose water", "1 teaspoon Cardamom Powder (Elaichi)"]'::jsonb, ARRAY['cashew nuts', 'ghee', 'pistachios', 'rose water', 'sugar', 'cardamom powder (elaichi)', 'condensed milk sweetened', 'milk powder']::text[], '["To begin making the Kaju Pista Roll Recipe (Cashew Nut Pistachio Fudge), first grind the cashews and pistachios separately into fine powder.In a thick n heavy bottomed pan add the ghee, condensed milk and powdered cashews.", "Stir well to combine.Add milk powder, rose water & start cooking this mixture on a medium heat until it starts to leave the sides of the pan & forms soft dough.", "Keep stirring continuously to avoid any burning at the bottom of the pan.", "This might take 10 to 12 minutes.", "Now turn off the heat and transfer this on to a plate to cool.Meanwhile in a bowl take the powdered pistachios and combined it along with powdered sugar, cardamom powder and make it into a soft dough by adding little water at a time.", "Knead to make a soft dough, just enough for it to come together.", "Try not to over knead, as it will get softer and will release oils.The final step to make the Kaju Pista Roll is to shape it.Take a rolling board and spread a parchment over it.", "Place the kaju dough over the parchment paper and place another parchment paper over it.", "Using a rolling pin roll the kaju into a rectangular sheet.Remove the parchment paper covering the kaju and spread the pista mixture over the rolled kaju.Cut the whole sheet into 2 inch wide strips enough to make a Kaju pista roll.", "Roll each strip into a log.", "Proceed the same way to make the kaju pista rolls."]'::jsonb, 55, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Swapna/kaju_pita_roll_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1262.kaju_pita_roll_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mooli Palak Sabji Recipe - Radish Spinach Sabzi', 'mooli-palak-sabji-recipe-radish-spinach-sabzi', 'Mooli Palak Sabji is a simple and easy recipe that is delicious and super healthy too given the health benefits of radish and spinach. Radish and spinach are powerhouses of essential minerals and vitamins like vitamin B6, A, C, K, folate, fiber, potassium et al. This is a diabetic friendly dish as radish and spinach help in maintaining blood sugar levels.', '["4 Mooli/ Mullangi (Radish) , cut into rounds", "100 grams Spinach Leaves (Palak) , roughly chopped", "2 Green Chillies , slit", "4 clove Garlic , finely chopped", "Salt , as per taste", "1/2 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Oil"]'::jsonb, ARRAY['mooli/ mullangi', 'radish', 's spinach leaves', 'palak', 'reen chillies', 'garlic', 'salt', 'coriander powder', 'dhania', 'red chilli powder', 'turmeric powder', 'haldi', 'cumin seeds', 'jeera', 'oil']::text[], '["To begin the preparation of Mooli Palak Sabji, cut the mooli into medium sized pieces and also the palak.", "Prepare the remaining ingredients and keep them ready.Keep the cooker on low flame, add little oil, once the oil is heated then add the cumin seeds, green chillies and garlic.", "Then add the mooli and stir well.", "Add salt as per taste, red chilli powder, dhaniya powder and turmeric powder.", "Close the lid of the cooker, and wait for 4 whistles and then turn off the flame of the Mooli Palak Sabzi.", "Open the cooker and add the chopped spinach and cook until the spinach wilts down.Check the taste and adjust the spices accordingly.Serve Mooli Palak Sabji with\u00a0Phulka\u00a0and\u00a0Burani Raita\u00a0for a simple weekday lunch."]'::jsonb, 25, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/0-Archana/Mooli_Palak_Sabji_Recipe_Radish_Spinach_Sabzi-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1263.Mooli_Palak_Sabji_Recipe_Radish_Spinach_Sabzi-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Raw Banana Thoran Recipe', 'raw-banana-thoran-recipe', 'Raw Banana Thoran is a common dish in Kerala and is widely served as a side dish. One cannot think of vegetarian food from God''s own country and miss mentioning the thoran. This lightly spiced stir-fry is made with many vegetables and makes the taste of the vegetable taste yummy. In this Thoran we are using raw banana which is the much-loved vegetable in Kerala. The vegetable is combined with mild spices and freshly grated coconut.', '["2 Raw Banana , boiled and diced", "1 teaspoon Coconut Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies", "8 Curry leaves", "10 Pearl onions (Sambar Onions) , finely chopped", "2 cloves Garlic , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "To Be Ground To Coarse Mixture", "1/4 cup Fresh coconut , grated", "2 Green Chillies", "1/4 cup Coriander (Dhania) Leaves , roughly chopped", "Salt , to taste"]'::jsonb, ARRAY['green chillies', 'salt', 'mustard seeds', 'coconut', 'coriander (dhania) leaves', 'cloves garlic', 'curry leaves', 'pearl onion (sambar onion)', 'dry red chillies', 'turmeric powder', 'coconut oil', 'banana']::text[], '["To begin with, the Raw banana Thoran first, cut the raw banana into half and boil it in the pressure cooker for 3 to 4 whistles and turn off the heat.", "Once cooked, through, peel the skin and cut into dices.Blend all the ingredients \"to be ground\" into a coarse paste and keep aside.In a heavy bottom pan, add mustard seeds and allow it to cracke.", "When they crackle add dry red chillies, curry leaves, onions and garlic.", "Saut\u00e9 until the onions soften.", "Add the cooked banana, the ground coconut mixture and give it a stir.Add the salt to taste and stir fry for about 3 to 4 minutes until the raw banana thoran is well incorporated.", "Once done, serve warm.Serve the Raw Banana Thoran along with Steamed Rice,\u00a0Beetroot Sambar\u00a0and Yogurt for a comforting meal."]'::jsonb, 25, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/0-Archana/Raw_Banana_Thoran_Recipe-1-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1264.Raw_Banana_Thoran_Recipe-1-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Vendakka Uppadan Recipe', 'kerala-style-vendakka-uppadan-recipe', 'Vendakkai Uppadan is a traditional spicy recipe from the state of Kerala. Unlike, other dishes from this region, this one does not use coconut in it. The simplest of the spices are freshly dry roasted, ground and added to the recipe making it very aromatic. It is spicy and tart making it a perfect accompaniment with Rice. Serve Vendakkai Uppadan Recipe (Kerala Style Okra Curry) with Steamed rice, Snake Gourd Thoran Recipe (Turai Thoran) and Paruppu Podi for a weeknight dinner.', '["200 grams Bhindi (Lady Finger/Okra) , cut into 1 inch pieces", "Tamarind , small lemon sized", "1/4 teaspoon Turmeric powder (Haldi)", "1 tablespoon Coconut Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing) , powder", "1 sprig Curry leaves", "Salt , to taste", "Ingredients to dry roast and ground to a course mix", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "2 tablespoons Rice , raw", "2-3 Dry Red Chillies"]'::jsonb, ARRAY['salt', 'rice', 'mustard seeds', 'curry leaves', 'asafoetida (hing) powder', 'dry red chillies', 'coconut oil', 'methi seeds (fenugreek seeds)', 'bhindi (lady fingerokra)', 'turmeric powder', 'tamarind lemon']::text[], '["To begin making Vendakkai Uppadan Recipe (Kerala Style Okra Curry Without Coconut), soak the lemon sized tamarind in luke warm water in a bowl for 10 minutes and extract the juice out of it and keep aside.In the meantime, heat a Shallow Fry Pan, and dry roast the ingredients listed under \u201cdry roast and ground to a course mix\u201d till fragrant.Grind them to a course mix using a Mixer grinder, and keep aside.Now, heat oil in the shallow fry pan on a medium flame, add the mustard seeds and let it crackle.Add the asafoetida and curry leaves and allow it to crackle.Now, add the cut okra and saut\u00e9 for a few minutes until the sliminess disappears.Add the tamarind extract and a cup of water, turmeric powder, salt and let the okras cook with the lid closed.", "This will take around 3-4 minutes.Now, add the spice mix and let it simmer for other 2-3 minutes.", "Cook until the curry turns thick\u00a0considerably.Switch off the flame and serve the Vendakkai Uppadan Recipe (Kerala Style Okra Curry) \u00a0with\u00a0Steamed rice,\u00a0Snake Gourd Thoran Recipe (Turai Thoran)\u00a0and\u00a0Paruppu Podi\u00a0for a weeknight dinner."]'::jsonb, 35, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/23-feb/Uppadan_Kerala_Style_Recipe-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1265.Uppadan_Kerala_Style_Recipe-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Iyengar Vendakkai Mor kuzhambu Recipe', 'iyengar-vendakkai-mor-kuzhambu-recipe', 'Iyengar Style Vendakkai Mor kuzhambu  Recipe is a variant to the regular Pooshanikai More Kuzhambu  .This type of preparation is something very commonly seen in many Iyengars (a sect of Tambrahms Community) households. In other words it is also called as a south Indian version of “Bhindi Kadhi”. In the south Indian version of mor kuzhambu, It does not require Garam masala or garlic. The specialty in our cuisine is without these ingredients we can prepare an equally flavorful dish. Vendakkai Mor kuzhambu , is typically crispy okra that is cooked in a thick , spicy yogurt based sauce.', '["8 Bhindi (Lady Finger/Okra)", "2 tablespoons Coconut Oil", "1 tablespoon Ghee", "Salt , to taste", "3 tablespoons Arhar dal (Split Toor Dal)", "1 pinch Turmeric powder (Haldi)", "2 teaspoon Methi Seeds (Fenugreek Seeds)", "2 teaspoon Cumin seeds (Jeera)", "2 tablespoons Fresh coconut", "1/2 inch Ginger , chopped", "2 Green Chillies , chopped", "2 Dry Red Chillies", "2 sprig Coriander (Dhania) Leaves , chopped", "Water , as required", "250 ml Curd (Dahi / Yogurt)", "100 ml Water", "Salt , to taste", "1 teaspoon Ghee", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 pinch Asafoetida (hing)", "3 Dry Red Chillies"]'::jsonb, ARRAY['bhindi', 'lady finger/okra', 's coconut oil', 'ghee', 'salt', 's arhar dal', 'split toor dal', 'turmeric powder', 'haldi', 'methi seeds', 'fenugreek seeds', 'cumin seeds', 'jeera', 's fresh coconut', 'ginger', 'reen chillies', 'dry red chillies', 'coriander', 'dhania', 'water', 'curd', 'dahi / yogurt', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing']::text[], '["We begin Making the Iyengar Style Vendakkai Mor kuzhambu Recipe by soaking the toor dal in 1/2 cup luke warm water and add a little turmeric powder \u00a0and leave it\u00a0in a blender jar for about 30 minutes.Meanwhile take a wok , on medium heat , add oil and saute fenugreek seeds, green chillies\u00a0,ginger piece\u00a0and dry red chillies until aromatic .Transfer this roasted mixture to the soaking toor dal and add coconut scrapings ,\u00a0coriander\u00a0leaves and cumin seed.", "Grind this to a fine\u00a0paste.", "In the same wok , on medium heat , add 2 tablespoon of coconut oil and 1 tablespoon of ghee , fry the chopped okra until crispy.", "You can sprinkle little salt over it and saute until the outer skin of the okra turns light brown.In a medium sized vessel , add the ground paste and whisk in 250 ml of sour curd and 100 ml of water without any lumps.", "Keep this on medium heat and stir continuously , do not leave this on heat without stirring , it will burn at the bottom and give smoky taste.Care must be taken.", "As you stir this , it will start boiling and the liquid will start to thicken.", "The liquid will froth in the sides.Now add the fried okra to this and stir.", "Switch off the heat and keep it aside.", "Take a tempering pan or use the same wok that you used to fry the grinding ingredients and the okra , add a teaspoon of ghee, temper mustard seeds , asafoetida and break the dry red chillies and then add it.", "Saute this and add it to the Mor kuzhambu.Serve the\u00a0Iyengar Style Vendakkai Mor kuzhambu with hot steaming Rice and\u00a0Raw Banana Thoran\u00a0as a side dish to enjoy your perfect meal."]'::jsonb, 45, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/14-feb/Iyengar_Style_Vendakkayi_MoreKuzhambu_Recipe-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1266.Iyengar_Style_Vendakkayi_MoreKuzhambu_Recipe-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Atte Ka Halwa Recipe - Whole Wheat Flour Halwa with Khoya', 'atte-ka-halwa-recipe-whole-wheat-flour-halwa-with-khoya', 'The Atte Ka Halwa Recipe is a delicious and traditional Indian sweet that is made from Whole Wheat Flour. This recipe uses sooji and khoya to add to the richness of the halwa. The Atte Ka Halwa is a tricky halwa to make - the most important process is the roasting of the wheat flour on low to medium heat until it turn a good brown color.', '["1 cup Whole Wheat Flour", "1/2 cup Sooji (Semolina/ Rava)", "1/2 cup Khoya (Mawa)", "1 tablespoon Cardamom Powder (Elaichi)", "1 tablespoon Whole Almonds (Badam)", "1 tablespoon Cashew nuts , to garnish", "1/4 cup Ghee", "1 cup Sugar"]'::jsonb, ARRAY['cashew nuts', 'wheat flour', 'khoya (mawa)', 'ghee', 'sugar', 'badam (almond)', 'cardamom powder (elaichi)', 'sooji (semolina rava)']::text[], '["To begin making the\u00a0Atte Ka Halwa Recipe (Whole Wheat Flour Halwa with Khoya), first get all the ingredients ready.Heat a tablespoon of ghee in skillet on medium heat.", "Add the almonds and cashew nuts and roast until browned and crisp.", "Turn off the heat and keep aside.Heat 1/2 cup of water and sugar in a saucepan and allow the sugar the melt completely and keep the hot sugar water aside.Heat 1/4 cup of ghee in a heavy bottomed pan or a kadai.", "Add the wheat flour and sooji and roast on medium heat in the ghee for a good 5 to 6 minutes until you get a roasted aroma from the flour and the flour resembles coarse crumbs and has changed to a little darker brown color.Add the\u00a0cardamom powder, khoya and again mix it well.", "Cook the Atte Ka Halwa along with a khoya for another 5 minutes.", "Keep stirring continuously and when the halwa begins to thicken add the sugar water and keep stirring continuously.", "You will notice the halwa will splutter and start thickening.", "Keep stirring for another 5 minutes till you notice the halwa leaves the sides of the pan.", "Once it does turn off the heat and transfer the Atte Ka Halwa to a serving bowl.", "Garnish with the roasted almonds and cashew nuts and serve.Serve the Atte Ka Halwa along with a traditional Indian meal or simply make it as a dessert for festivals when you have friends and family over."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Atte_Ka_Halwa_Whole_Wheat_Flour_Halwa_with_Khoya-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1267.Atte_Ka_Halwa_Whole_Wheat_Flour_Halwa_with_Khoya-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mizoram Style Hmarcha Rawt - Roasted Green Chilli Chutney', 'mizoram-style-hmarcha-rawt-roasted-green-chilli-chutney', 'Mizoram Style Hmarcha Rawt (Roasted Green Chilli Chutney) is a recipe from North East India. It is a tangy and spicy chilli chutney locals of Mizoram prefer having with main dishes. The recipe is also quite easy to prepare and just take 10 to 15 minutes. Serve with Spicy Chicken Curry Recipe In Naga Style or Thekera Tenga Recipe (veg) and steamed rice.', '["10 Green Chillies", "10 Fresh Red chillies", "1 Onion , finely chopped", "1 inch Ginger , grated", "Salt , to taste"]'::jsonb, ARRAY['reen chillies', 'fresh red chillies', 'onion', 'ginger', 'salt']::text[], '["To begin making this easy Mizoram Style Hmarcha Rawt (Roasted Green Chilli Chutney), roast chillies over a tawa.With a pestle and mortar, crush the green and red chillies, along with salt to taste.", "You can also optionally grind it in a mixer.Then add finely onions and grated ginger and mix well.", "Adjust salt.", "If you like, you can add a dash of sugar.Serve\u00a0Mizoram Style Hmarcha Rawt (Roasted Green Chilli Chutney) with\u00a0Spicy Chicken Curry Recipe In Naga Style\u00a0or\u00a0Thekera Tenga Recipe\u00a0(veg) and\u00a0steamed rice."]'::jsonb, 15, 'North East India', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Deboshruti.ghosh/Mizoram_Style_Hmarcha_rawt_Recipe_Roasted_Green_Chilli_Chutney-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1268.Mizoram_Style_Hmarcha_rawt_Recipe_Roasted_Green_Chilli_Chutney-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Oriya Special Dalma Recipe - Lentils Cooked With Vegetables & Raw Papaya', 'oriya-special-dalma-recipe-lentils-cooked-with-vegetables-raw-papaya', 'Dalma is a Chickpea Dal Cooked With Vegetables and Raw Papaya, a delicacy from the state of Orissa. It can be made using toor (arhar) dal, and an assortment of vegetables typically raw banana, eggplant, green papaya and pumpkins, simmered in a special spice blend.', '["1 cup Arhar dal (Split Toor Dal)", "2 Potatoes (Aloo) , cubed", "1 Carrot (Gajjar) , cubed", "1/2 cup Kaddu (Parangikai/ Pumpkin) , chopped", "1/2 cup Brinjal (Baingan / Eggplant) , chopped", "1/2 cup Papaya , green one, chopped", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1 inch Ginger", "1 Bay leaf (tej patta)", "1 tablespoon Ghee", "4 cloves Garlic", "2 Green Chillies", "1 Dry Red Chilli", "1 teaspoon Panch Phoran Masala", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin powder (Jeera)", "1 teaspoon Red Chilli powder", "Salt , to taste", "2 tablespoons Fresh coconut , thinly shaved coconut slices", "Coriander (Dhania) Leaves , a small bunch, finely chopped"]'::jsonb, ARRAY['tomato', 'cumin powder (jeera)', 'parangikai pumpkin', 'brinjal (baingan eggsplant)', 'cloves garlic', 'carrot', 'onion', 'turmeric powder', 'green chillies', 'salt', 'coriander (dhania)', 'arhar dal (split toor dal)', 'papaya green', 'garam masala powder', 'coconut shaved coconut', 'red chilli powder', 'dry red chilli', 'ginger', 'bay leaf (tej patta)', 'ghee', 'panch phoran masala', 'potato (aloo)']::text[], '["To begin making the\u00a0Oriya Special Dalma Recipe, we will first get all the vegetables chopped and ready.", "We will be cooking the Oriya Dalma in one single pot - the pressure cooker.", "Add the vegetables, dal, turmeric powder, green chillies, onions, bay leaf, salt and 3 cups of water into the pressure cooker.", "Pressure cook until you heat couple of whistles.", "After a couple of whistles, turn the heat to low and simmer for 3 minutes, then turn off the heat.The dal will continue to cook in the pressure cooker as long as there is pressure.", "Once the pressure releases completely, you can open the cooker and keep the dal aside.", "The next step is to spice up the Dalma with flavors.Using a mortar and pestle\u00a0pound the ginger and garlic until you get a rough paste.", "Heat the ghee in a heavy bottomed pan\u00a0on medium heat.", "Add the red chiles, panch phoran, the red chili powder, the garam masala powder and the pounded ginger garlic.", "Stir fry for a few seconds until you can smell the roasted aromas.Take care to keep the heat on low, else the spices can burn and smoke.Add this masala to the cooked dal and give it a good stir.", "Check for salt and spices and adjust to suit your taste.", "You can add some water to adjust the consistency of the dal.Give the Oriya Style Dalma a quick boil and turn off the heat.", "Transfer to a serving bowl, garnish with shaved coconut and the coriander leaves and serve.Serve the Oriya Special Dalma as a delicious one-pot dal along with\u00a0steamed rice\u00a0or\u00a0jeera pulao."]'::jsonb, 73, 'Oriya', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Swayampurna_Mishra/Dalma_Recipe_Oriya_Chickpea_Dal_Cooked_With_Vegetables_Raw_Papaya.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1269.Dalma_Recipe_Oriya_Chickpea_Dal_Cooked_With_Vegetables_Raw_Papaya.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('केला बेसनी सब्ज़ी विधि रेसिपी - Kela Besani Sabzi Recipe', 'kela-besani-sabzi-recipe', 'यह केला बेसनी सब्ज़ी एक बहुत ही आसान सी सब्ज़ी है. यह सब्ज़ी कच्चे केले को मसालेदार बेसन के घोल में डूबा कर तलकर, दही की ग्रेवी में पकाई हुई एक स्वादिष्ट सब्ज़ी है। आप इससे आसानी से बना सकते है और गर्म फुल्का या तवा पराठा के साथ परोस सकते है.', '["1 \u0915\u091a\u094d\u091a\u0947 \u0915\u0947\u0932\u0947", "1 \u0915\u092a \u091a\u092e\u091a\u094d\u091a \u092c\u0947\u0938\u0928", "\u0939\u0940\u0902\u0917 , \u091a\u0941\u091f\u0915\u0940 \u092d\u0930", "1 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u091c\u0940\u0930\u093e", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u0915\u092a \u0926\u0939\u0940", "1/2 \u0915\u092a \u092a\u093e\u0928\u0940", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "1 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u0924\u0947\u0932", "\u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u0915\u093e\u091f\u093e \u0939\u0941\u0906", "\u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0915\u091f\u0940 \u0939\u0941\u0908", "\u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930, \u0924\u0932\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f"]'::jsonb, ARRAY['कच्चे केले', 'कप चमच्च बेसन', 'हींग', 'बड़ा चमच्च जीरा', 'छोटा चमच्च हल्दी पाउडर', 'छोटा चमच्च लाल मिर्च पाउडर', 'छोटा चमच्च धनिया पाउडर', 'छोटा चमच्च गरम मसाला पाउडर', 'कप दही', 'कप पानी', 'नमक', 'बड़ा चमच्च तेल', 'हरा धनिया', 'हरी मिर्च', 'तेल']::text[], '["\u0915\u0947\u0932\u094b\u0902 \u0915\u094b \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0927\u094b \u0915\u0930 \u0922\u0940\u0932\u093e \u0915\u0930 \u0932\u0947\u0902. \u0917\u094b\u0932 \u091f\u0941\u0915\u095c\u0947 \u0915\u093e\u091f \u0915\u0930 \u0925\u094b\u095c\u0940 \u0926\u0947\u0930 \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u0909\u092c\u093e\u0932 \u0932\u0947\u0964\u0906\u092c \u092c\u0947\u0938\u0928 \u0915\u0947 \u0918\u094b\u0932 \u0915\u0940 \u0924\u0948\u092f\u093e\u0930\u0940 \u0915\u0930\u0932\u0947\u0964 \u092c\u0947\u0938\u0928 \u0915\u0947 \u0918\u094b\u0932 \u0915\u0947 \u0932\u093f\u090f \u092c\u0947\u0938\u0928 \u092e\u0947\u0902 \u0925\u094b\u095c\u093e \u0928\u092e\u0915, \u091a\u0941\u091f\u0915\u0940 \u092d\u0930 \u0939\u0932\u094d\u0926\u0940 \u0914\u0930 \u092a\u093e\u0928\u0940 \u092e\u093f\u0932\u093e\u0915\u0930 \u0918\u094b\u0932 \u092c\u0928\u093e \u0932\u0947\u0964 \u00a0\u0905\u092c \u0909\u092c\u0932\u0947 \u0939\u0941\u090f \u0915\u0947\u0932\u0947 \u0915\u094b \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u0938\u0947 \u0928\u093f\u0915\u0932 \u0915\u0930 \u092c\u0947\u0938\u0928 \u0918\u094b\u0932 \u092e\u0947\u0902 \u0938\u093e\u0928 \u0915\u0930 \u0917\u0930\u092e \u0924\u0947\u0932 \u092e\u0947\u0902 \u0924\u0932 \u0932\u0947\u0902\u0964\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u090f\u0915 \u092c\u095c\u093e \u091a\u092e\u091a \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0964 \u0909\u0938\u092e\u0947 \u0939\u0940\u0902\u0917 \u0935 \u091c\u0940\u0930\u093e \u0921\u093e\u0932\u0947\u0902\u0964 \u0938\u0930\u0947 \u092e\u0938\u093e\u0932\u0947, \u092f\u093e\u0928\u093f \u0939\u0932\u094d\u0926\u0940, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a, \u0914\u0930 \u0927\u0928\u093f\u092f\u093e \u0926\u093e\u0932 \u0915\u0930 \u092d\u0942\u0928\u0947\u0964\u0906\u092c \u0926\u0939\u0940 \u0935 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932 \u0915\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u092e\u093f\u0932\u093e\u090f\u0902\u0964 \u0924\u0947\u0932 \u092e\u0947\u0902 \u0924\u0932\u0947 \u0939\u0941\u090f \u0915\u0947\u0932\u0947 \u0935 \u0928\u092e\u0915 \u0921\u093e\u0932 \u0915\u0930 \u091a\u0932\u093e\u090f\u0902 \u0914\u0930 \u0922\u0915\u0915\u0930 \u0927\u0940\u092e\u0940 \u0906\u0902\u091a \u092a\u0930 \u092a\u0915\u093e\u090f\u0902\u0964\u0967\u096b-\u0968\u0966 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u091c\u092c \u0926\u0939\u0940,\u092e\u0938\u093e\u0932\u0947 \u0935 \u0915\u0947\u0932\u0947 \u00a0\u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u092e\u093f\u0932 \u091c\u093e\u090f\u0902 \u0924\u094b\u0939 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0926\u0947\u0902\u0964 \u0915\u0924\u0930\u0947 \u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u093e \u0914\u0930 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a \u0935 \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u0947 \u0938\u0947 \u0938\u091c\u093e\u0915\u0930 \u0917\u0930\u092e- \u0917\u0930\u092e \u092a\u0930\u093e\u0902\u0920\u094b \u092f\u093e \u092b\u0942\u0932\u0915\u094b \u0915\u0947 \u0938\u093e\u0925 \u092a\u0930\u0938\u094b\u0902\u0964."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/30-march/Besan_Kela_Ki_Subzi_Recipe_Raw_banana_in_Yogurt_Dry_Stir_Fry-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1270.Besan_Kela_Ki_Subzi_Recipe_Raw_banana_in_Yogurt_Dry_Stir_Fry-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('मैंगलोर फिश करी रेसिपी - Mangalore Fish Curry Recipe', 'mangalore-fish-curry-recipe', 'मैंगलोर फिश करी रेसिपी एक स्वादिष्ट डिश है जो दक्षिण भारत के मैंगलोर में बहुत बनाई जाती है. इस करी में नारियल और इमली का प्रयोग किया जाता है. इसके साथ इसमें हरी मिर्च का भी प्रयोग किया जाता है जो इसे बहुत ही स्वादिष्ट बनाता है.', '["500 \u0917\u094d\u0930\u093e\u092e \u0915\u093f\u0902\u0917 \u092b\u093f\u0936 , \u0915\u093e\u091f \u0932\u0947", "1 \u092a\u094d\u092f\u093e\u091c , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "4 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0938\u0940\u0927\u093e \u0914\u0930 \u092a\u0924\u0932\u093e \u0915\u093e\u091f \u0932\u0947", "3/4 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u093e \u0926\u0942\u0927", "\u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "25 \u0917\u094d\u0930\u093e\u092e \u0907\u092e\u0932\u0940", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "\u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e , \u0925\u094b\u095c\u0947", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['ग्राम किंग फिश', 'प्याज', 'हरी मिर्च', 'कप नारियल का दूध', 'तेल', 'बड़े चम्मच धनिया पाउडर', 'बड़ा चम्मच लाल मिर्च पाउडर', 'ग्राम इमली', 'बड़ा चम्मच हल्दी पाउडर', 'कढ़ी पत्ता', 'नमक']::text[], '["\u092e\u0948\u0902\u0917\u0932\u094b\u0930 \u092b\u093f\u0936 \u0915\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u092e\u091b\u0932\u0940 \u0915\u094b \u092a\u093e\u0928\u0940 \u0938\u0947 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u0927\u094b \u0932\u0947. \u0905\u092c \u0907\u0938 \u092a\u0930 \u0928\u092e\u0915, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930 \u0932\u0917\u093e\u090f \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0917\u0930\u092e \u092a\u093e\u0928\u0940 \u0932\u0947 \u0914\u0930 \u0907\u0938\u092e\u0947\u0902 \u0907\u092e\u0932\u0940 \u0921\u093e\u0932\u0947\u0964 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947 \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0938\u0941\u0928\u0939\u0930\u093e\u00a0\u092d\u0942\u0930\u093e\u00a0\u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0907\u092e\u0932\u0940 \u0915\u093e \u0930\u0938 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 3/4 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 4 \u0938\u0947 5 \u092e\u093f\u0928\u091f \u0924\u0915 \u0909\u092c\u093e\u0932 \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092e\u0948\u0930\u093f\u0928\u0947\u091f\u0947\u0921 \u092e\u091b\u0932\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 3 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u0917\u0948\u0938 \u0915\u0940 \u0906\u0902\u091a \u0915\u092e \u0915\u0930\u0947\u0902, \u0907\u0938\u092e\u0947\u0902 \u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u093e \u0926\u0942\u0927, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u090f\u0915 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902, \u0938\u0930\u094d\u0935\u093f\u0902\u0917 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092e\u0948\u0902\u0917\u0932\u094b\u0930 \u092b\u093f\u0936 \u0915\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u091a\u093e\u0935\u0932 \u0914\u0930\u00a0\u092a\u0941\u0926\u0940\u0928\u093e \u092a\u094d\u092f\u093e\u091c \u0915\u091a\u0941\u092e\u094d\u092c\u0930 \u0938\u0932\u093e\u0926 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 40, 'Mangalorean', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Monika_Manchanda/Mangalore_Fish_Curry.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1271.Mangalore_Fish_Curry.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharashtrian Kanda Poha Recipe', 'maharashtrian-kanda-poha-recipe', 'Maharashtrian Kanda Poha/Pohe is a very popular Maharashtrian breakfast or tea time snack. It is made from flattened/ beaten rice and tossed in caramelized onions, green chillies and peanuts. If you prefer to eat a light meal first thing in the morning, this super quick dish is just right for you. You can always spice it up or down depending on your taste. Serve Maharashtrian Kanda Poha Recipe with Samosa Recipe and Ginger Cardamom Chai.', '["300 grams Poha (Flattened rice)", "1 Onion , chopped finely", "1 Green Chillies , split in half", "6 Curry leaves , (optional)", "1 tablespoon Cumin seeds (Jeera)", "2 tablespoons Oil", "1 teaspoon Sugar", "1 tablespoon Roasted Peanuts (Moongphali)", "Salt , to taste", "2 tablespoons Coriander (Dhania) Leaves , chopped fine, for the garnish", "1 Lemon , juiced"]'::jsonb, ARRAY['s poha', 'flattened rice', 'onion', 'reen chillies', 'curry leaves', 'cumin seeds', 'jeera', 's oil', 'sugar', 'roasted peanuts', 'moongphali', 'salt', 's coriander', 'dhania', 'lemon']::text[], '["To begin making the Maharashtrian Kanda Poha Recipe, heat the oil in a large shallow pan.", "When the oil is hot, throw in the cumin seeds.", "When they splutter, add the chilli, peanuts and the curry leaves.Add the onions and cook till light pink or brown on a medium flame.In the meanwhile, wash the pohe and leave them to drain in a sieve. (The trick is to ensure they are still damp but not dripping when they are added into the pan)Once the onions are cooked, add in the pohe, season with salt, add the sugar, chopped coriander leaves and juice from one lemon.", "Stir all the ingredients well, turn the heat to low, cover the pan and simmer for about 2 to 3 minutes.After about 3 to 4 minutes, turn off the heat and serve the Maharashtrian Kanda Poha for breakfast or as a tea time snack, along with\u00a0Samosa Recipe\u00a0and\u00a0Ginger Cardamom Chai."]'::jsonb, 30, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breakfast_Tiffins/Maharashtrian_Kanda_Poha_Recipe_shutterstock_222063475.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1272.Maharashtrian_Kanda_Poha_Recipe_shutterstock_222063475.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Cabbage Pachadi Recipe', 'cabbage-pachadi-recipe', 'Cabbage pachadi or tempered chutney recipe is very easy dish prepared with cabbage. It is also healthy and delicious in taste that goes well with South Indian Recipes like Ghee Roast Dosas, idli or Carrot Onion Uttapam. Serve Cabbage Pachadi Recipe as a side dish with South Indian breakfasts.', '["2 tablespoons Sesame (Gingelly) Oil", "1 tablespoon White Urad Dal (Split)", "1 tablespoon Roasted Gram Dal (Pottukadalai)", "2 cups Cabbage (Patta Gobi/ Muttaikose) , roughly chopped", "3 Green Chillies , chopped (adjust)", "10 Curry leaves", "Salt , to taste", "1/2 tablespoon Tamarind Paste", "1/2 cup Water", "1/2 tablespoon Mustard seeds (Rai/ Kadugu)", "1 pinch Asafoetida (hing)", "2 Dry Red Chillies , (adjust)", "2 teaspoon Oil"]'::jsonb, ARRAY['salt', 'white urad dal', 'water', 'curry leaves', 'mustard', 'chana dal', 'dry red chillies', 'oil', 'asafetida', 'tamarind paste', 'green chillies', 'til oil', 'cabbage']::text[], '["To prepare cabbage pachadi recipe, heat oil in a pan, add urad dal and chana dal and saute it on low flame till golden brown in colour.Add green chillies and curry leaves. stir and mix well.", "Now add chopped cabbage.Add some salt as per your taste and let it cook for next 8-9 minutes, make sure that cabbage is half cooked, there should be a slight crunch in them.Let the mixture cool down.Now add the cabbage mixture in a grinder jar.", "Add tamarind and some water.", "Grind the cabbage mixture to a smooth chutney.Transfer the chutney in a bowl .Now heat a tadka pan with a teaspoon of oil.Add mustard seeds and let them crackle.Add asafoetida, mix well.Add the tempting to the cabbage chutney and give it a stir.Serve Cabbage Pachadi Recipe with South Indian breakfast recipes like Ghee Roast Dosas, idli or Carrot Onion Uttapam."]'::jsonb, 35, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/6-april/cabbage_pachadi_recipe_thogayal-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1273.cabbage_pachadi_recipe_thogayal-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chow Chow and Carrot Kootu Recipe', 'chow-chow-and-carrot-kootu-recipe', 'Chow Chow And Carrot Kootu is a classic kootu recipe which perfectly goes well with rotis as well as steamed rice. The mild sweetness from the carrots, spiciness from the green chillies balances out the whole dish.', '["2 Chayote , cut into cubes", "1 Carrot (Gajjar) , cut into cubes", "pinch Turmeric powder (Haldi)", "Salt , to taste", "To grind into a smooth paste", "1 teaspoon Rice , raw, soaked", "1 teaspoon Chana dal (Bengal Gram Dal) , soaked", "2-3 tablespoons Fresh coconut , grated", "1 teaspoon Cumin seeds (Jeera)", "1 Green Chilli", "To temper", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "1 Dry Red Chilli"]'::jsonb, ARRAY['salt', 'green chilli', 'rice', 'coconut', 'chayote', 'mustard seeds', 'carrot', 'dry red chilli', 'curry leaves', 'white urad dal (split)', 'cumin seeds (jeera)', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making Chow Chow And Carrot Kootu Recipe, grind the ingredients mentioned in the to grind table to a smooth paste using a mixer or hand blender and keep aside.Heat a wide , add the bite sized cut cubes of chowchow, carrot, a pinch of turmeric powder, salt and 2 cups of water and cook until the vegetables are firmly cooked.Once the vegetables are cooked, add the ground spice paste to the pan and simmer for 2-3 minutes till the kootu thickens.Add water at this stage, if the kootu is too thick. bring it to a boil and switch off the flame.In another tadka pan, heat oil, add the mustard seeds and urad dal and let it splutter.Add the curry leaves and dry red chilli saute for a minute and add this tempering to the kootu prepared.Serve the Chow Chow And Carrot Kootu \u00a0Recipe with rotis or with Steamed Rice,\u00a0Vengayam Thakali Kuzhambu,\u00a0Beans Poriyal\u00a0and Rice crackers to make an elaborate Tamil Saapad lunch menu on a weekend."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/26-april/chow_chow_and_carrot_kootu_with_coconut_recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1274.chow_chow_and_carrot_kootu_with_coconut_recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Coconut Peanut Stuffed Baby Brinjal Recipe', 'spicy-coconut-peanut-stuffed-baby-brinjal-recipe', 'Spicy Coconut Peanut Stuffed Baby Brinjal takes inspiration from the eastern ghats of India and makes for a delicious side dish. The eggplants are stuffed with a spicy, tangy coconut peanut filling making this dish really flavourful and delicious. This dish tastes like a gravy dish but it is dry, making it tiffin friendly. The recipe uses very less oil, making it a healthy choice for weight watchers and diabetic patients.', '["10 Small Brinjal (Baingan / Eggplant)", "1 tablespoon Mustard oil , or vegetable oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "3 cloves Garlic , thinly sliced", "1/2 teaspoon Salt", "1/2 cup Raw Peanuts (Moongphali)", "1 tablespoon Homemade tomato puree", "1/4 Dry coconut (kopra) , grated", "1 teaspoon Cumin seeds (Jeera)", "2 teaspoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "1/2 teaspoon Salt", "1/2 teaspoon Red Chilli powder", "2 teaspoon Sesame seeds (Til seeds)", "3 sprig Coriander (Dhania) Leaves , finely chopped"]'::jsonb, ARRAY['tomato', 'salt', 'mustard seeds', 'brinjal (baingan eggsplant)', 'mustard oil vegetable oil', 'red chilli powder', 'cloves garlic', 'dry coconut (kopra)', 'coriander (dhania) leaves', 'cumin seeds (jeera)', 'peanuts (moongphali)', 'coriander powder', 'sesame seeds (til seeds)', 'garam masala powder']::text[], '["To begin making the Spicy Coconut Peanut Stuffed Baby Brinjal recipe, make 2 way slit in the eggplants (2 vertical slit perpendicular to each other.", "Do not make the slit through till the end) and keep aside.Let us prepare the stuffing for the eggplants now.", "For this, dry roast peanuts and dried coconut to a light golden brown.", "Let it cool down.Now, using a food processor/chopper, grind these along with cumin seeds, coriander powder, garam masala, salt and red chili powder into a homogeneous mix.", "Add in the tomato paste and chopped coriander.", "Combine.Stuff the eggplants with the stuffing well and keep them in the fridge for 10 minutes so that the stuffing gets a little solid and does not ooze out when stir fried.Now, take a non stick pan and in it add in the mustard/vegetable oil.Heat it up and add in the mustard seeds.", "Let the seeds splutter.Now add in the sliced garlic and roast till lightly golden.Now, add in the stuffed eggplants and toss around the tempering.", "Add in the required amount of salt.Let it cook on medium high for the next 15 to 20 minutes till the eggplants start to cook and get tender.Now, place a lid on the pan and cook on simmer for another 5 to 7 minutes.", "After 5 to 7 minutes, they are done and ready to serve.Spicy Coconut Peanut Stuffed Baby Brinjal tastes best when served along with flatbreads likeWhole Wheat Palak Naan Recipe,\u00a0rotis, parathas or steamed rice."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/4-may/_Spicy_Coconut_Peanut_Stuffed_Baby_Brinjal_Recipe-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1275._Spicy_Coconut_Peanut_Stuffed_Baby_Brinjal_Recipe-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Brinjal Capsicum Sabji Recipe', 'brinjal-capsicum-sabji-recipe', 'Brinjal Capsicum Sabji Recipe is an easy side dish recipe which accentuates the flavors of capsicum with eggplant or brinjal and tomatoes. This sabzi can be had with phulka orchapati for a nutritious lunch at school or work. This Brinjal Capsicum Sabji Recipe comes handy when you need to fix nutrition is less available time at hand.', '["2 Brinjal (Baingan / Eggplant) , diced (long variety)", "1 Green Bell Pepper (Capsicum) , diced", "5 Garlic , chopped finely", "1/2 tablespoon Asafoetida (hing)", "2 Green Chillies , chopped", "1 Tomato , chopped", "1 tablespoon Turmeric powder (Haldi)", "1 tablespoon Red Chilli powder", "1/2 tablespoon Coriander Powder (Dhania)", "1/2 tablespoon Garam masala powder", "Salt , to taste", "Coriander (Dhania) Leaves , chopped", "Oil , as required"]'::jsonb, ARRAY['tomato', 'salt', 'asafoetida (hing)', 'coriander (dhania) leaves', 'red chilli powder', 'brinjal (baingan eggsplant) ( variety)', 'garlic', 'green bell pepper (capsicum)', 'coriander powder', 'turmeric powder', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To prepare the simple Brinjal Capsicum Sabji Recipe, heat a pan with enough oil.Add chopped garlic and hing, saut\u00e9 it for few seconds.Add brinjal and capsicum.Add all the dry spices, saut\u00e9 and cover the lid.", "Let it semi cook by saut\u00e9ing every few minutes once.Add chopped tomato and let it cook for 5-7 minutes (or until the veggies are desirable cooked).Add salt to taste, saut\u00e9 and add chopped fresh coriander.Pack this Brinjal Capsicum Sabji Recipe with phulka/ chapati for a light lunch at office or school."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/23-may/Brinjal_Capsicum_Sabji_Recipe-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1276.Brinjal_Capsicum_Sabji_Recipe-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Matar Masala Recipe', 'spicy-matar-masala-recipe', 'Spicy Matar Masala is a simple and easy dish which can be prepared in a short time. When you are out of vegetables these frozen matar come to your help. The Spicy Matar Masala is cooked in a gravy form where the matar is cooked in an onion and tomato base gravy.', '["1 cup Green peas (Matar) , boiled", "1/2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "3 to 4 Curry leaves", "2 Green Chillies , finely chopped", "1 Bay leaf (tej patta) , broken into two piece", "2 to 3 Cloves (Laung)", "Cardamom (Elaichi) Pods/Seeds", "1 tablespoon Ginger Garlic Paste", "1 Onion , finely chopped", "1/2 cup Onion , paste", "3/4 cup Homemade tomato puree", "1 teaspoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "1-1/2 teaspoon Coriander Powder (Dhania)", "Salt , as required"]'::jsonb, ARRAY['tomato', 'salt', 'mustard seeds', 'cardamom (elaichi) podsseeds', 'green peas (matar)', 'red chilli powder', 'curry leaves', 'ginger garlic paste', 'onion paste', 'onion', 'cumin seeds (jeera)', 'bay leaf (tej patta) two piece', 'cloves (laung)', 'coriander powder', 'turmeric powder', 'green chillies']::text[], '["To begin with the Spicy Matar Masala,Firstly heat oil in a heavy bottomed pan and add cumin seeds and mustard seeds.Once it splutters, add curry leaves, bay leaf, cloves and badi\u00a0elaichi.After a minute, add green chillies and garlic ginger paste.", "Cook it for about a minute.Next add the chopped onions and cook them till they become soft and translucent.Next, add the onion paste and cook for about 3 to 5 minutes.", "Then add the tomato puree and add all the masalas and salt.Cook for about 5 to 8 minutes or till the oil starts separating.Now add the green peas and allow it to cook for another 2 minutes.Check for salt and spice, adjust according to your taste and switch off the flame''Serve your Spicy Matar masala with roti and dal."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/20-june/Spicy_matar_curry_Recipe-7018.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1277.Spicy_matar_curry_Recipe-7018.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Jain Style Corn Palak Recipe', 'jain-style-corn-palak-recipe', 'Jain Style Corn Palak is a delicious combination of corn, spinach, and spices. This dish is made without onion and garlic and serves as a great side dish with phulka or pulav. The freshness of spinach makes this dish even more tasty and flavourful.', '["1 cup Spinach Leaves (Palak) , packed", "1/2 cup Sweet corn , boiled", "Salt , to taste", "1 tablespoon Sugar", "1/2 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "1 teaspoon Lemon juice", "1 tablespoon Garam masala powder", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Cumin powder (Jeera)", "Oil , as required", "To grind", "2 Tomatoes", "2 Green Chillies", "8 to 10 Cashew nuts", "Oil , as required", "1/2 teaspoon Cumin seeds (Jeera)", "Asafoetida (hing)", "1/2 teaspoon Red Chilli powder"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'green chillies', 'cashew nuts', 'asafoetida (hing)', 'red chilli powder', 'spinach leaves (palak) packed', 'sugar', 'lemon', 'cumin seeds (jeera)', 'sweet corn', 'kasuri methi (dried fenugreek leaves)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Jain Style Corn Palak recipe, blanch the spinach leaves and reserve in ice cold water.", "Drain and puree into a paste in a mixer grinder.Saute the ingredients mentioned under \"To grind\" in 1 teaspoon oil till tomato shrivels a bit and grind to a smooth paste once cooled using some water.In a heavy bottomed pan, temper with the tempering ingredients, add the turmeric, pureed spinach, salt.", "Mix well and let the spinach paste cook for 3 to 4 minutes till it dries up a bit.Now add the pureed tomato masala, dry spice powders and corn.", "Mix well and let it simmer lightly for 8-10 mins.Adjust water to desired thickness, adding a tablespoon or two at a time.", "Finish with crushed kasuri methi, salt and lemon juice.Mix everything well and it is ready to be served.", "Serve Jain Style Corn Palak along with\u00a0Phulka,\u00a0Pudina Tawa Paratha\u00a0or Steamed Rice for a weekday lunch or dinner."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/27-june/Jain_Style_no_onion_and_no_garlic_Palak_and_corn_curry-7222.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1278.Jain_Style_no_onion_and_no_garlic_Palak_and_corn_curry-7222.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Potato Stuffed Dal Dhokli Recipe', 'potato-stuffed-dal-dhokli-recipe', 'Potato Stuffed Dal Dhokli Recipe can be translated as Mashed potato dumplings steamed in Lentil Curry. There are a variety of Indian curry recipes for mashed potatoes but this recipe is quite different. Here I have slightly modified dal dhokli recipe which is a traditional Gujarati dish.', '["1 cup Whole Wheat Flour", "Salt , to taste", "1 tablespoon Oil", "Whole Wheat Flour , for rolling", "3 Potato (Aloo) , boiled and mashed", "1 tablespoon Red Chilli powder", "1/2 tablespoon Garam masala powder", "2 tablespoon Coriander (Dhania) Leaves , chopped", "1 tablespoon Sugar , optional", "1/2 tablespoon Lemon juice", "1 cup Arhar dal (Split Toor Dal) , boiled and ground", "1/4 tablespoon Turmeric powder (Haldi)", "1/3 cup Raw Peanuts (Moongphali) , boiled", "Salt , to taste", "1 Tomato , finely chopped", "1 Green Chilli , finely chopped", "1 inch Ginger , grated", "1/2 tablespoon Lemon juice", "3 tablespoon Jaggery , chopped", "1 tablespoon Oil", "1/2 tablespoon Mustard seeds (Rai/ Kadugu)", "1/2 tablespoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "10 Curry leaves", "2 Dry Red Chillies", "1 Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "1 Bay leaf (tej patta)", "4 tablespoon Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['tomato', 'coriander (dhania) leaves', 'asafoetida (hing)', 'jaggery', 'cumin seeds (jeera)', 'wheat flour rolling', 'turmeric powder', 'sunflower oil', 'salt', 'wheat flour', 'green chilli', 'dry red chillies', 'peanuts (moongphali)', 'garam masala powder', 'mustard seeds', 'red chilli powder', 'sugar', 'lemon', 'ginger', 'bay leaf (tej patta)', 'potato (aloo)', 'curry leaves', 'cinnamon stick (dalchini)', 'arhar dal (split toor dal) ground', 'cloves (laung)']::text[], '["To prepare Potato Stuffed Dal Dhokli Recipe, get prep with all the ingredients mentioned and proceed with making the dumplings.", "Start with sieving the flour with salt and knead into a semi-stiff dough with enough water.Cover the dough with a lid and keep aside for 10-15 minutes.", "Meanwhile prepare filling for dumplings.", "Take boiled and mashed potato in one bowl, add salt to taste, chilli powder, turmeric powder, chopped coriander, Garam masala, lemon juice and sugar(optional).Mix all spices well into potato.", "Make medium sized balls from the potato mixture.Make about 10-15 equal small sized balls from the dough.Roll out into 3-4 inches diameter roti base with a rolling pin, place the potato ball in center of roti.", "This rolled out roti dough should be thinner, like the thickness of regular chapati.Bring together all the edges in the center and join them.", "Cover whole potato roll with roti, remove the excess dough if necessary.", "Try to avoid thick covering around the stuffing.Similarly, prepare 10-15 dumplings till all the filling is used up and cover with a plate."]'::jsonb, 100, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/20-jan/Potato_Stuffed_Dal_Dhokli_Recipe_Potato_Stuffed_Dal_Dhokli_Recipe_Potato_Stuffed_Dal_Dhokli_Recipe_-5.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1279.Potato_Stuffed_Dal_Dhokli_Recipe_Potato_Stuffed_Dal_Dhokli_Recipe_Potato_Stuffed_Dal_Dhokli_Recipe_-5.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Authentic Godumai Dosai Recipe - Whole Wheat Flour Crepes', 'authentic-godumai-dosai-recipe-whole-wheat-flour-crepes', 'Godumai Dosai is an instant dosa recipe that is commonly prepared in most Tamil homes. As the dosa is prepared with whole wheat flour and requires no overnight fermentation, it is a handy recipe. Whole Wheat Flour is rich in fibre making this a high fibre dosa recipe. It is popular among the Karnataka cuisine as well and is called as the "Ghodi Dosa".', '["2 cups Whole Wheat Flour", "1/2 cup Curd (Dahi / Yogurt)", "2 Onions , finely chopped", "1 Green Chilli , finely chopped", "Coriander (Dhania) Leaves , Few, finely chopped", "1 sprig Curry leaves , torn roughly", "Salt , to taste", "2 teaspoons Sesame (Gingelly) Oil"]'::jsonb, ARRAY['salt', 'wheat flour', 'green chilli', 'coriander (dhania) leaves', 'sesame (gingelly) oil', 'curd', 'curry leaves', 'onion']::text[], '["To begin with Godumai Dosai, mix the wheat flour, yogurt and 2 cups of water properly and make sure that no lumps are formed.Add salt and allow the batter to rest for 1-2 hours.After 1-2 hours, add the finely chopped onions, chillies, cilantro and curry leaves.", "Mix the batter and adjust the water quantity until you have smooth flowing batter that is not too thin.", "The batter should have a thickness so you can spread as well - similar to a dosa or a crepe batter.Heat a little oil in the cast iron pan and when it is hot, pour one ladle of batter in the centre.Spread the batter in a circular motion just like regular dosa or pancake.", "Pour a little oil on the sides of the dosa.Cover the dosa with a lid and cook for a minute.", "Open, flip and cook the other side of the dosa as well.Remove the dosa and continue the same process for the rest of the batter.", "Cook the dosa in low flame for best texture and colour.Serve Godumai Dosai with\u00a0South Indian Coconut Chutney,\u00a0Red Chilli Coconut Chutney\u00a0or any other chutney of your choice."]'::jsonb, 90, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/18-april/karnataka_Style_Ghodi_Dosa_recipe_wheat_pancakes-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1280.karnataka_Style_Ghodi_Dosa_recipe_wheat_pancakes-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Arunachal Pradesh Zan Recipe - Finger Millet Porridge with Vegetables Recipe', 'arunachal-pradesh-zan-recipe-finger-millet-porridge-with-vegetables-recipe', 'Arunachal pradesh "The land of rising sun" is one of the largest among North eastern states. They prefer to use different methods of cooking.This region is occupied by tribal people and they use fresh herbs,vegetables in their everyday cooking. They don''t use oil much or packed spice products and they prefer steaming,boiling and smoked food methods of cooking.', '["4 tablespoons Ragi Flour (Finger Millet/ Nagli)", "1 1/2 cup Water", "1 Carrot (Gajjar) , sliced diagonally", "1 cup Spinach", "1/4 cup Soybeans (Whole Soya dal) , boiled", "1/4 cup Green peas (Matar) , optional", "Salt , as per taste", "1 teaspoon Black pepper powder", "1 sprig Coriander (Dhania) Leaves , chopped", "1 tablespoon Ghee"]'::jsonb, ARRAY['salt', 'soybeans (whole soya dal)', 'spinach', 'ghee', 'green peas (matar)', 'water', 'carrot', 'ragi flour (finger millet nagli)', 'coriander (dhania) leaves', 'black pepper powder']::text[], '["We begin making the Arunachal Pradesh Zan Recipe (Finger Millet Porridge with Vegetables Recipe) roast the millet flour with a tablespoon of ghee in a kadai and set aside.", "Dissolve millet flour in little water and cook until it becomes semi thick paste.Saute the vegetable separately in a flat tawa with little oil, saute the carrot first so that it get cooked and then add in the spinach.", "Keep it aside.", "You can also blanch the vegetables in water with salt till it becomes tender and then add it to the ragi porridge.", "Take about one and half cup of water in vessel and bring it to a boil.", "Add this millet flour paste and mix it.", "At this point add the vegetables and seasoning like salt, pepper and herbs.", "Keep whisking it till you get your desired consistency.", "Serve it hot with by sprinkling some fermented cheese or just plain as well.", "Serve the\u00a0Arunachal Pradesh Zan Recipe (Finger Millet Porridge with Vegetables Recipe) as a healthy breakfast with\u00a0Cantaloupe (Melon) Juice Recipe\u00a0to have a satisfying breakfast.-."]'::jsonb, 20, 'North East India', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/20-march/Arunacha_pradesh_style_Zan_and_Rongpu_Takeng_recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1281.Arunacha_pradesh_style_Zan_and_Rongpu_Takeng_recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Besan Katli Ki Sabzi Recipe', 'besan-katli-ki-sabzi-recipe', 'Besan Katli Ki Sabzi is a recipe that hails from Uttar Pradesh, and is often prepared during monsoon season. Couple of decades ago, during monsoon, fresh vegetables were seldomly available hence "Besan Ke Paneer" was the go to option for home cooks. Nowadays since monsoons doesn''t affect the availability of other veggies and seeing how busy people have gotten with their lives, this recipe is scarcely prepared.', '["1 cup Gram flour (besan)", "1 Green Chilli , finely chopped", "1 teaspoon Garlic , paste", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , as required", "Water , as required", "Ghee , as required", "1/2 cup Onion , finely chopped", "2 teaspoon Ginger Garlic Paste", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "4 sprig Coriander (Dhania) Leaves , chopped for garnishing", "1/2 teaspoon Garam masala powder", "1/2 cup Homemade tomato puree", "1 teaspoon Cumin seeds (Jeera)"]'::jsonb, ARRAY['tomato', 'salt', 'green chilli', 'ghee', 'red chilli powder', 'water', 'gram flour (besan)', 'ginger garlic paste', 'coriander (dhania) leaves', 'onion', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'garam masala powder', 'garlic paste']::text[], '["To begin making the Besan Katli Ki Sabzi recipe, add gram flour, ginger, green chillies, salt and turmeric powder in a bowl and mix everything till it forms a dough.Cut it into cubes and then boil it in a saucepan with the required water.", "Keep them aside.Heat ghee in a wok.", "Add cumin seeds and onions.", "Saute till the onions turns translucent.Add ginger garlic paste and let it cook for another 2 minutes.Add the tomato puree and all the masalas including salt, turmeric powder, coriander powder, red chilli powder and garam masala powder.Cook for another 3 to 5 minutes and then add the required water.", "Cook for another 5 minutes.Now add the steamed gram flour dumplings and cook it for 5 minutes.", "Once done, switch off the stove and garnish with coriander leaves."]'::jsonb, 50, 'Uttar Pradesh', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/0-Archana/Besan_Katli_Ki_Sabzi_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1282.Besan_Katli_Ki_Sabzi_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Beetroot Carrot Halwa Recipe', 'beetroot-carrot-halwa-recipe', 'Beetroot and Carrot Halwa is a perfect sweet to be served hot or chilled after a perfect Indian meal. Traditionally carrot halwa or beetroot halwa are made separately. Adding Beetroot to carrot halwa not only gave beautiful color to halwa but also made it more delicious.', '["1 cup Beetroot , grated", "1 cup Carrot (Gajjar) , grated", "4 tablespoon Ghee , or butter", "2 cup Milk , (full cream milk)", "1/2 cup Fresh cream , (or khoya/mawa)", "3/4 cup Sugar , (add it accordingly)", "1 tablespoon Cardamom Powder (Elaichi)", "6 Saffron strands", "1 tablespoon Whole Almonds (Badam) , blanched", "1 tablespoon Cashew nuts , broken", "20 Sultana Raisins"]'::jsonb, ARRAY['beetroot', 'carrot', 'gajjar', 'ghee', 'milk', 'fresh cream', 'sugar', 'cardamom powder', 'elaichi', 'saffron strands', 'whole almonds', 'badam', 'cashew nuts', 'sultana raisins']::text[], '["We begin making Beetroot and Carrot Halwa Recipe by heating 2 tablespoon of ghee or butter in a heavy bottom pan, add broken cashew nuts, fry it to golden brown and keep aside.In the same remaining ghee, add grated carrot and beetroot and saut\u00e9 them for 2-3 minutes on medium heat.", "Add milk and cook on medium heat until the milk condenses and evaporates making it thick.At this stage, add heavy cream/khoya and sugar.", "Stir well and simmer until it thickens again about 5 minutes.Stir in the saffron, cardamom powder, fried cashew nuts and raisins.", "Finally add in the remaining 2 tablespoons of ghee and stir to combine well.", "Garnish it with Blanched almonds.Serve the Beetroot and Carrot Halwa Recipe\u00a0 hot or chilled.", "Eat the way you love it, Enjoy!Serve the\u00a0Beetroot and Carrot Halwa as a healthy\u00a0dessert\u00a0after your Delicious Sunday lunch or just have it as a snack during the evening."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Beetroot_and_Carrot_Halwa_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1283.Beetroot_and_Carrot_Halwa_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Papaya and Carrot Halwa Recipe', 'papaya-and-carrot-halwa-recipe', 'The Papaya & Carrot Halwa Recipe is a simple, quick and delicious sweet dish that is made  from papaya and carrots giving it a rich flavor and taste. You will be surprised how well the papaya goes into the halwa and gives it a creamy texture.', '["4 cups Papaya , peeled and grated", "1 cup Carrot (Gajjar) , grated", "1/2 cup Sugar", "3/4 cup Milk", "1/2 teaspoon Cardamom Powder (Elaichi)", "2 Saffron strands", "2 tablespoons Whole Almonds (Badam) , sliced", "1/4 cup Ghee"]'::jsonb, ARRAY['ghee', 'milk', 'saffron strands', 'carrot', 'sugar', 'papaya', 'badam (almond)', 'cardamom powder (elaichi)']::text[], '["To begin making the Papaya and Carrot Halwa Recipe, first get the ingredients ready by grating the papaya and carrots.In a heavy bottomed pan\u00a0add the ghee, the grated\u00a0papaya and carrots.", "Saute for a few minutes until you get a good aroma.", "Stir in the milk, sugar and simmer with the papaya carrot halwa mixture until all the milk condenses to form a thick halwa.You will notice the halwa would become thick and become sticky leaving the sides of the pan.", "The milk and water content should be completely evaporated and the Papaya Carrot Halwa will look glossy.At this stage add a tablespoon of ghee and mix well and finally stir in the cardamom powder, saffron and sliced almonds to the halwa.", "Turn off the heat and serve.Serve the\u00a0Papaya & Carrot Halwa along with vanillas ice cream as a\u00a0Dessert\u00a0for parties or as a special sweet for the festivals like Diwali, Navratri, Raksha Bandhan and Holi."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Papaya_Halwa_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1284.Papaya_Halwa_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Prawns & Shrimp Biryani  -Chemmeen Biryani Recipe', 'kerala-style-prawns-shrimp-biryani-chemmeen-biryani-recipe', 'Kerala Style Prawns & Shrimp Biryani (Chemmeen Biryani Recipe) is a robust flavored seafood biryani made from prawns and shrimps. This is a perfect monsoon and winter season food with wonderful coastal flavors within and aroma spreading from this hot Prawns and Shrimp pilaf.', '["Ingredients For The Rice", "3 cups Basmati rice , soaked for 25-35 minutes", "6 Cardamom (Elaichi) Pods/Seeds", "6 Cloves (Laung)", "1 Cinnamon Stick (Dalchini)", "1 teaspoon Coriander (Dhania) Leaves , finely chopped", "1 teaspoon Mint Leaves (Pudina) , finely chopped", "3 tablespoons Ghee", "3-4 tablespoons Lemon juice", "Salt , to taste", "Ingredients For Marinating Prawns", "1/2 kg Prawns , cleaned and deveined", "1 tablespoon Ginger Garlic Paste", "1/2 tablespoon Red Chilli powder", "1/2 teaspoon Whole Black Peppercorns , ground", "Salt , to taste", "Other Ingredients", "3 Onions , finely chopped", "1/2 tablespoon Ginger , paste", "1/2 tablespoon Garlic , paste", "5 - 6 Green Chillies", "2 - 3 Tomatoes , finely chopped", "1 Fresh coconut , handful, grated", "1 Coriander (Dhania) Leaves , handful", "1/4 cup Mint Leaves (Pudina) , finely chopped", "1/2 cup Curd (Dahi / Yogurt)", "6 - 8 Cashew nuts , soaked in 2 tablespoons water", "1 teaspoon Garam masala powder", "Oil , vegetable oil", "1 Salt , to taste", "Ingredients For Garnish", "1 Cashew nuts , handful", "1 Sultana Raisins , handful", "1 Onion , finely sliced", "1 teaspoon Coriander (Dhania) Leaves , finely chopped", "1 teaspoon Mint Leaves (Pudina) , finely chopped", "1 teaspoon Mint Leaves (Pudina) , finely chopped"]'::jsonb, ARRAY['tomato', 'basmati rice', 'coriander (dhania) leaves', 'black peppercorns ground', 'onion', 'green chillies', 'salt', 'cardamom (elaichi) podsseeds', 'raisins', 'mint leaves (pudina)', 'garam masala powder', 'coconut', 'sunflower oil vegetable oil', 'prawns deveined', 'red chilli powder', 'curd', 'lemon', 'garlic paste', 'cashew nuts', 'ghee', 'ginger garlic paste', 'cinnamon stick (dalchini)', 'ginger paste', 'cloves (laung)']::text[], '["Start making Kerala Style Prawns & Shrimp Biryani (Chemmeen Biryani Recipe) by mixing prawns with ingredients mentioned under marinating prawns, and refrigerate for 2-3 hours.", "Meanwhile you can prepare basmati rice for biryani.Meanwhile, grind grated coconut and coriander leaves into a smooth paste.Also grind soaked cashews and keep aside.Heat oil in a Stir-fry pan and shallow fry marinated prawns and keep aside.In the same pan, heat oil and add onions, 1 tablespoon ginger-garlic paste and green chillies, saut\u00e9 till done.Once the onions are soft, add chopped tomatoes and saut\u00e9 till cooked.Now add curd, ground paste of coconut-coriander and stir well.Once it comes to boil and the raw smell disappears, add shallow fried prawns and cook on low flame and saut\u00e9 for 5-6 minutes till the prawns are well-coated with masala.Add the cashew paste and garam masala.", "Combine well and cook for another 2 to 3 minutes till the mixture thickens slightly.", "Switch off flame and allow the pan to cool."]'::jsonb, 220, 'Kerala', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/26-sep/Kerala_Style_Prawn_Biriyani_Recipe-8695.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1285.Kerala_Style_Prawn_Biriyani_Recipe-8695.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ellu Sadam Recipe - Sesame Rice', 'ellu-sadam-recipe-sesame-rice', 'Ellu Sadam is made with sesame seeds and is ground with spices to give a good flavour. This sesame powder is added to the cooked rice and is served hot. Usually, ellu Sadam is given as Saturday prasadam in most of the temples in Tamilnadu.', '["1-1/2 cup Basmati rice", "Salt , as per your taste", "3 tablespoon Oil", "50 grams Sesame seeds (Til seeds)", "50 Dry coconut (kopra)", "6 Dry Red Chillies", "1 cup White Urad Dal (Split)", "4 tablespoon Cashew nuts", "1/2 tablespoon Mustard seeds (Rai/ Kadugu)", "4 Curry leaves", "3/4 tablespoon Asafoetida (hing)", "3/4 \u092c\u095c\u0947 \u091a\u092e\u091a\u094d\u091a \u0939\u0940\u0902\u0917"]'::jsonb, ARRAY['cashew nuts', 'basmati rice', 'salt', 'mustard seeds', 'asafoetida (hing)', 'dry coconut (kopra)', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'sesame seeds (til seeds)', 'sunflower oil']::text[], '["To begin with the Ellu Sadam first heat a pan and roast sesame seeds and transfer it into a plate and in the same pan dry roast the grated coconut and keep it aside.", "After this add one spoon oil in same heated pan and roast 4-5 dry red chillies.Cool these ingredients and grind them into a coarse powder.Now mix this powder with cooked rice and add salt according to your taste.", "And now for the seasoning, in a tadka pan add oil and allow it to get heated up.Add mustard seeds and once they splutter add curry leaves,soaked urad dal,cashew nuts,dry red chillies and asafoetida .Mix this seasoning with rice and mix everything together.Serve the Ellu Sadam for lunch with\u00a0Mor Kuzhambu\u00a0so that it makes a satisfying meal for your family."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/26-april/Ellu_sadam_stir_fried_rice_with_sesame_seeds_and_coconut_recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1286.Ellu_sadam_stir_fried_rice_with_sesame_seeds_and_coconut_recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Saunf Wale Aloo Baingan Recipe - Fennel Spiced Potato And Eggplant', 'saunf-wale-aloo-baingan-recipe-fennel-spiced-potato-and-eggplant', 'Saunf Wale Aloo Baingan Recipe is a tasty dish that is spiced with fennel seeds powder. Potatoes and brinjals are a classic combination and are preferred the most. The saunf has a strong flavor and aroma that is handled very carefully. Not all vegetables go well with the flavour of fennel seeds but this Saunf Wale Aloo Baingan Recipe is an exemption.', '["1 cup Brinjal (Baingan / Eggplant) , cut in cubes", "1/2 cup Potatoes (Aloo) , boiled and cut in cubes", "1 Onion , sliced", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Ginger Garlic Paste", "1 teaspoon Red Chilli powder", "1 teaspoon Turmeric powder (Haldi)", "2 teaspoons Oil", "Coriander (Dhania) Leaves , Few sprigs, finely chopped for garnish", "Salt , to taste", "1 tablespoon Coriander (Dhania) Seeds", "1 tablespoon Fennel seeds (Saunf)"]'::jsonb, ARRAY['salt', 'coriander (dhania) leaves', 'brinjal (baingan eggsplant)', 'fennel seeds (saunf)', 'red chilli powder', 'ginger garlic paste', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'potato (aloo)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making Saunf Wale Aloo Baingan, heat a wok in medium flame.", "Pour oil and add the cumin seeds, let them fry.Now add the sliced onions, and saut\u00e9 till the onions become translucent.Add the ginger garlic paste and cook for two more minutes.Now add the brinjal cubes and saut\u00e9, once the brinjals are half cooked add the boiled potatoes cubes.Stir them and leave them to fry for 2 to 3 minutes.", "It''s time to add the spices, add chili powders, turmeric powder, and some salt.", "Give it a stir and cook them by closing it with a lid.Wait until the vegetables are cooked well.In the mean, take another small pan and dry roast the coriander and fennel seeds in low flame till aromatic.", "Grind it using a mixer to a coarse powder.Now, transfer the aromatic fennel and coriander powder to the vegetables and stir it in open for few minutes.Garnish with finely chopped coriander leaves and switch off the flame.Serve Saunf Wale Aloo Baingan with roti''s and dal tadka to make it a weeknight dinner."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/30-aug/Brinjal_and_Aloo_Subzi_Poriyal_Recipe-8589.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1287.Brinjal_and_Aloo_Subzi_Poriyal_Recipe-8589.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vegetable Biryani Recipe With Chatpata Aloo', 'vegetable-biryani-recipe-with-chatpata-aloo', 'We Indians love biryani’s. Biryani originates originally in Persia and was introduced in India by the Arabs. Biryani is a rice dish with lots of flavours and textures, made with quite a few variants of rice. The key to a good biryani lies in good quality rice, fresh spices and ingredients and style of cooking. Vegetable Biryani Recipe With Chatpata Aloo is a way to spice up your biryani with shallow fried aloo.', '["2 cups Basmati rice", "Water", "2 Onions", "1/2 inch Ginger", "3 to 5 Green Chillies , (adjust)", "2 cloves Garlic", "Oil", "3 Red Yellow or Green Bell Pepper (Capsicum)", "1 Carrot (Gajjar) , cut into julienne", "Ghee , to garnish", "1 Star anise", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 Dry Red Chilli", "1 Bay leaves (tej patta)", "1/4 teaspoon Whole Black Peppercorns", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Black pepper powder", "1/2 teaspoon Red Chilli powder", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Coriander (Dhania) Seeds", "1/2 teaspoon Amchur (Dry Mango Powder)", "Salt , to taste", "2 Potatoes (Aloo) , chopped into cubes", "1/4 teaspoon Chaat Masala Powder", "Lemon juice , from 1 lemon", "1/4 teaspoon Black pepper powder", "Salt , to taste"]'::jsonb, ARRAY['lemon', 'basmati rice', 'chaat masala powder', 'cloves garlic', 'carrot', 'black peppercorns', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'black pepper powder', 'turmeric powder', 'green chillies', 'sunflower oil', 'salt', 'red yellow green bell pepper (capsicum)', 'star anise', 'red chilli powder', 'water', 'dry red chilli', 'ginger', 'bay leaves (tej patta)', 'ghee', 'amchur (dry mango powder)', 'cinnamon stick (dalchini)', 'potato (aloo)', 'cloves (laung)']::text[], '["To begin making the Vegetable Biryani with Chatpata Aloo recipe, firstly soak the rice in water for 15 to 30 minutes.", "Temper all the spices mentioned under \u2018For spices\u2019 on dry heat for 2 to 3 minutes till the aroma starts to come, make sure to do this on low flame.You can coarse ground the spices or leave them as it is.Cut potatoes in chunks and dunk in cold water or freeze for 10 minutes (this makes them crispy).Next take about a tablespoon of oil and bring it to high heat in a heavy bottomed pan\u00a0or biryani handi.Add potato chunks and pan sear till light golden.", "Take out on a kitchen paper towel to soak excess oilSeason with chat masala, salt, freshly ground pepper and lemon.", "Keep them aside.Next in a heavy bottomed pan, add 2 tablespoon oil and bring to medium heat.Add onions, chilli, ginger and garlic and saut\u00e9 till onions become translucent.Add bell peppers, carrots and saut\u00e9 for a couple of minutes.", "Add the tempered spices and cook for a minute or so.Then add soaked rice along with water (1. 5inch height of water with good quality basmati is enough) in the same wok.", "Cover the wok and let it cook in steam.Once completely cooked top it with chahtpatay aloo, lemon slice and slit chilli.", "Add ghee and fresh onion while serving.Serve Vegetable Biryani Recipe With Chatpata Aloo with\u00a0Lauki Raita,\u00a0Raw Mango Raita\u00a0or any other Raita of your choice."]'::jsonb, 50, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Akansha_Bansal/vegetable_biryani_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1288.vegetable_biryani_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Matar Ki Tehri Recipe - Fragrant rice cooked with spices and fresh peas', 'matar-ki-tehri-recipe-fragrant-rice-cooked-with-spices-and-fresh-peas', 'Matar Ki Tehri Recipe is a traditional dish from Eastern UP, where rice is cooked with whole spices and fresh peas. Tehri is different from pulav as it is moist and a little sticky. There are two types of tehri, one with potato, cauliflower and carrot, and the other one with just peas. With the goodness of fresh peas, the aroma of desi ghee, luscious tomatoes and fresh coriander, this recipe has been handed down from generation to generation in UP.', '["1 cup Basmati rice", "4-5 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 tablespoon Whole Black Peppercorns", "2 Black cardamom (Badi Elaichi)", "1 Dry Red Chilli", "3 tablespoons Ghee", "1/4 cup Onions , sliced", "1/4 cup Tomatoes , sliced", "1/4 inch Ginger , finely grated", "1 cup Green peas (Matar)", "1/4 cup Coriander (Dhania) Leaves , finely chopped", "1 Bay leaf (tej patta)", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'black cardamom (badi elaichi)', 'basmati rice', 'ginger', 'salt', 'ghee', 'coriander (dhania) leaves', 'bay leaf (tej patta)', 'green peas (matar)', 'black peppercorns', 'dry red chilli', 'cinnamon stick (dalchini)', 'onion', 'cloves (laung)']::text[], '["To begin making Matar Ki Tehri, wash and soak the rice in enough water for 1 hour before cooking.", "Once it is soaked, drain the water and keep it aside.Soak the peas in a cup of water, so that it cooks faster and retain some of that ''plump'' look.Heat ghee in the pressure cooker\u00a0and add all the whole spices and red chilli and saut\u00e9 it for 2 minutes on low flame.After 2 minutes, add the sliced onions and ginger and saut\u00e9 it on low flame for 2-3 minutes till they begin to brown.", "Now add the tomatoes and peas and saut\u00e9 it for another 2 minutes.After 2 minutes, add coriander leaves, bay leaf and the rice.", "Add salt according to your taste and mix it well.Add water and cook on high flame till the pressure cooker releases 1 whistle.", "Then simmer it down on low flame and let it cook for more 3-4 minutes.Once it is done, turn off the stove and let the cooker release steam and open on its own so that the Tehari is nicely cooked.Serve it hot, either on its own as a one pot meal or else with Lauki Raita, Beetroot Raita or any raita of your choice."]'::jsonb, 50, 'Awadhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/6-sep/Matar_Ki_Tehri_recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1289.Matar_Ki_Tehri_recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kaju Katli Recipe (Kaju Barfi)', 'kaju-katli-recipe-kaju-barfi', 'Kaju Katli or Kaju Barfi is a traditional Indian sweet made with cashew nuts and is most often made for festivals, gifting and weddings. The subtle sweetness of the barfi together with its melt in the mouth quality from the cashew nuts, make it the most desired sweet for any occasion, religious or otherwise. Serve Kaju Katli Recipe (Kaju Barfi) as a party dessert or along with Crispy Masala Peanuts Recipe (Gujarati Sing Bhujia) or Baked Chevdo Recipe (Chivda Mixture -Tea Time Snack) during tea time.', '["2 cups Cashew nuts", "2 cups Sugar", "2 teaspoons Corn flour", "2 teaspoons Ghee", "1 cup Water", "Edible Silver Foil/Leaf (Chandi Ka Vark) , (optional)", "Mixed nuts , crushed (pistachio) for stuffing (optional)"]'::jsonb, ARRAY['s cashew nuts', 's sugar', 's corn flour', 's ghee', 'water', 'edible silver foil/leaf', 'chandi ka vark', 'mixed nuts']::text[], '["To begin making the Kaju Katli Recipe (Kaju Barfi), take a large heavy bottomed pan, and pour in the sugar and water.", "Mix them well and boil for about 10 minutes, until the sugar syrup thickens up to a two string consistency.Grind all the cashew nuts together along with corn flour to a fine powder.Once the sugar syrup has arrived at a two string consistency, add the cashew nuts and corn flour powder to it.Continue stirring the Kaju Katli (burfi) mixture together till no lumps remain.", "Add a teaspoon of ghee and cook for another 7 to 10 minutes, until the Kaju Katli (burfi) mixture contents thickens up and begins to leave the sides of the pan.The final consistency of the Kaju Katli (burfi) mixture should be of dough consistency.Once it reaches the dough like consistency, turn off the heat and spread it evenly in a tray keeping about 1/2 inch thickness.", "Spread the silver varak at this stage and allow it to set.Once cooled, cut the Kaju Katli (burfi)\u00a0into desired shapes.", "You can also optionally make a sandwich of two the Kaju Katli (Burfi) with crushed pistachios and serve.The delicious Kaju Katli (Burfi)\u00a0is ready to be eaten, or it can even be refrigerated for future use.", "Hope you get to make the delicious\u00a0Kaju Katli Recipe this Diwali and share with friends and family.", "Serve\u00a0Kaju Katli Recipe (Kaju Barfi) as a party dessert or along with\u00a0Crispy Masala Peanuts Recipe (Gujarati Sing Bhujia)\u00a0or\u00a0Baked Chevdo Recipe (Chivda Mixture -Tea Time Snack)\u00a0during tea time."]'::jsonb, 100, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Kaju_Katli_Recipe_Kaju_Barfi_Indian_Sweet_Mithai_Archanas_Kitchen-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1290.Kaju_Katli_Recipe_Kaju_Barfi_Indian_Sweet_Mithai_Archanas_Kitchen-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kharbyaali Masale Khara Recipe - North Karnataka Sambar Powder', 'kharbyaali-masale-khara-recipe-north-karnataka-sambar-powder', 'The Kharbyaali Masale Khara is a very traditional North Karnataka Spice Powder that is used in making the Kharbyaali Nuggekai Saaru and even certain vegetable dishes. It is made with a combination of the various spices and smoked dry coconut that brings out the special flavor of the North Karnataka Kharbyaali Masala.', '["50 grams Garlic", "50 grams Dry ginger powder", "200 grams Dry coconut (kopra) , cut into thin long pieces", "200 grams Byadagi Dried Chillies", "100 grams Coriander (Dhania) Seeds", "50 grams Cumin seeds (Jeera)", "20 grams Methi Seeds (Fenugreek Seeds)", "20 grams Ajwain (Carom seeds)", "20 grams Cloves (Laung)", "30 grams Whole Black Peppercorns", "20 grams Cinnamon Stick (Dalchini)", "30 grams Sesame seeds (Til seeds)", "20 grams Poppy seeds", "10 grams Dagad phool (/pathar phool/black stone flower)", "50 grams Salt", "Oil , for frying"]'::jsonb, ARRAY['s garlic', 's dry ginger powder', 's dry coconut', 'kopra', 's byadagi dried chillies', 's coriander', 'dhania', 's cumin seeds', 'jeera', 's methi seeds', 'fenugreek seeds', 's ajwain', 'carom seeds', 's cloves', 'laung', 's whole black peppercorns', 's cinnamon stick', 'dalchini', 's sesame seeds', 'til seeds', 's poppy seeds', 's dagad phool', '/pathar phool/black stone flower', 's salt', 'oil']::text[], '["To begin making the Kharbyaali Masale Khara Recipe, preheat 1 cup of oil in a deep frying pan; deep fry the dry coconut pieces until lightly browned.", "Once browned drain the coconut, place them on a paper towels and keep aside to coolNext, in the same oil, we will deep fry the ginger and garlic until they turn brown.", "Drain completely, place them on a paper towels and keep aside to cool.Next is the process of dry roasting the remaining ingredientsIn another frying pan; roast the red chillies, curry leaves the the remaining ingredients on low heat.", "Roast them until you get a roasted aroma and the red chillies are browned as well.", "Once well roasted, allow the spices and chillies to cool completely.Once cooled, we will first grind all the dry roasted chillies and spices together until you get a fine powder.", "Keep this aside.In the same spice grinder, grind in the roasted garlic, ginger and coconut, till you get a smooth mixture.Combine all the ground ingredients along with the salt.", "Make sure it is well combined and mixed well.", "Store this mixture in a glass jar and refrigerate for six months.The Kharbyaali Masale Khara Recipe is now ready.", "You can use this Masale Khara in many dishes like Kharbyaali Nuggekai Sambar, Brinjal Vegetables and many more vegetable dishes."]'::jsonb, 35, 'North Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/1-Archana/Kharbyaali_Masale_Khara_recipe_A_North_Karnataka_Spice_Powder-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1291.Kharbyaali_Masale_Khara_recipe_A_North_Karnataka_Spice_Powder-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aloo Subz Dum Biryani Recipe', 'aloo-subz-dum-biryani-recipe', 'Aloo Subz Dum Biryani is a delicious one pot meal that makes a good lunch box recipe or a perfect week-night dinner. You can always include more vegetables other than potatoes in this recipe.', '["2 Potatoes (Aloo) , peeled and cubed", "1 Onion , sliced", "1 Carrot (Gajjar) , peeled and chopped", "1/2 cup Green beans (French Beans) , chopped", "Del Monte Whole Corn Kernels , washed and boiled", "1 Tomato , sliced", "2 Cloves (Laung)", "1/2 inch Cinnamon Stick (Dalchini)", "1 tablespoon Red Chilli powder", "1/2 tablespoon Turmeric powder (Haldi)", "1 Green Chilli , slit length wise", "2 tablespoon Curd (Dahi / Yogurt) , whisked", "1 tablespoon Garam masala powder", "1 tablespoon Ginger Garlic Paste", "Salt , to taste", "1 tablespoon Ghee", "2 cups Basmati rice , washed and soaked in water for 30 min", "2 Cloves (Laung)", "2 Cardamom (Elaichi) Pods/Seeds", "1/2 inch Cinnamon Stick (Dalchini)", "1 tablespoon Ginger Garlic Paste", "Salt , to taste", "2 tablespoon Coriander (Dhania) Leaves , finely chopped", "2 tablespoon Lemon juice", "1/2 tablespoon Garam masala powder", "Saffron strands , a few dissolved in milk", "2 tablespoon Caramelized onions", "2 tablespoon Ghee"]'::jsonb, ARRAY['tomato', 'del monte corn kernels', 'coriander (dhania) leaves', 'carrot', 'onion', 'turmeric powder', 'salt', 'green chilli', 'cardamom (elaichi) podsseeds', 'saffron strands dissolved milk', 'garam masala powder', 'green beans (french beans)', 'basmati rice min', 'red chilli powder', 'curd', 'lemon', 'ghee', 'ginger garlic paste', 'cinnamon stick (dalchini)', 'potato (aloo)', 'cloves (laung)']::text[], '["To begin with Aloo Dum Biryani, firstly add oil in a heavy bottom cooking vessel.After this, add clove and cinnamon in the same pan.", "Add sliced onions and fry till translucent.Once it is done, add the ginger-garlic paste and fry for about 1 minute till the raw smell disappears.Add carrot, beans and let it cook till is cooked half.", "Next,\u00a0add potato pieces, red chilli powder, turmeric powder and garam masala in the pan.", "Fry for about a minute and add 1/2 cup of water.", "Cook till potato pieces turn soft not mushy.Now add whisked curd and cook on low flame till the gravy becomes thick.For the rice layer, boil rice in enough water along with cardamoms, cinnamon, cloves, salt and ginger-garlic paste.", "Cook rice until just done.", "Check by pressing a grain in between your forefinger and thumb.", "If it is soft, then drain off the excess water from the rice using a sieve.Once the rice is cooked, now everything is ready to layer.", "Add ghee to the bottom of a heavy cooking vessel (the one we use to cook rice).", "Add a layer of rice and spread evenly.Now add a potato layer on the rice and spread evenly.", "Add half of fried onions, chopped coriander leaves, 1 tablespoon lemon juice, garam masala and 1 tablespoon of saffron milk.Cover this with another layer of rice and add remaining fried onions, chopped coriander leaves, 1 tablespoon lemon juice, garam masala and 1 tablespoon saffron milk.Now add 1 tablespoon ghee and leave the vessel on low flame by sealing the edges of vessel and lid with an aluminium foil.keep something heavy on the top of the lid to seal the aroma of biryani.Leave it on low flame for nearly 15-20 minutes.", "When you sprinkle 1 tablespoon of water on cooking vessel it has to sizzle.", "Turn off the flame and let it sit on stove for another 10-15 minutes before you start to serve.Remove the foil slowly and then open the lid.", "Start by mixing from the sides using wooden spatula very gently.", "Add fresh minced coriander and fried onions on the top before serving.Serve Aloo Sabzi Dum Biryani with Lauki raita, Raw mango raita or any raita of your choice."]'::jsonb, 70, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Affiliate-Articles/Aloo_Sabz_Dum_Biryani_Recipe_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1292.Aloo_Sabz_Dum_Biryani_Recipe_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Holud Mishti Pulao Recipe - Saffron Flavored Rice With Nuts', 'bengali-holud-mishti-pulao-recipe-saffron-flavored-rice-with-nuts', 'Bengali Holud Mishti Pulao Recipe (Saffron Flavored Rice With Nuts Recipe) is a Bengali flavored rice tossed with toasted nuts like cashew nuts, almonds, pistachio and raisins and flavored with saffron.', '["1 cup Basmati rice , (gobindo bhog)", "1/4 cup Green peas (Matar) , steamed (optional)", "11 inch Ginger , grated", "2 tablespoons Sugar", "1/4 teaspoon Nutmeg powder", "1/4 teaspoon Cumin powder (Jeera)", "14 teaspoon Turmeric powder (Haldi)", "2 Bay leaves (tej patta) , roughly torn", "1 inch Cinnamon Stick (Dalchini)", "3 Cardamom (Elaichi) Pods/Seeds", "3 Cloves (Laung)", "1/2 teaspoon Mace powder", "Saffron strands , few", "3 tablespoon Ghee", "2 tablespoons Cashew nuts , halved", "2 tablespoons Sultana Raisins", "2 tablespoon Pistachios , roughly chopped"]'::jsonb, ARRAY['cashew nuts', 'cumin powder (jeera)', 'ginger', 'nutmeg powder', 'bay leaves (tej patta)', 'cardamom (elaichi) podsseeds', 'ghee', 'saffron strands', 'pistachios', 'green peas (matar)', 'raisins', 'mace powder', 'sugar', 'cinnamon stick (dalchini)', 'turmeric powder', 'basmati rice (gobindo bhog)', 'cloves (laung)']::text[], '["To begin making Bengali Holud Mishti Pulao Recipe (Saffron Flavored Rice With Nuts), firstly we will cook the rice in a pressure cooker along with 1 tablespoon ghee, ginger and 2 cups of water until done.Once done, allow it to rest.", "In a small pan, heat a little ghee.", "Add bay leaves, cinnamom stick, cardamom pods, elaichi and cloves.", "Cook it for 10 to 15 seconds.After 10 to 15 seconds, add cashews, raisins, pistachios, cumin powder, turmeric powder, nutmeg powder, mace powder, saffron strands.After 1 minute, add in the cooked rice, green peas and sugar and give it a mix.", "Let it cook for 2 more minutes and serve hot.Serve your flavored\u00a0Bengali Holud Mishti Pulao\u00a0(Saffron Flavored Rice With Nuts) with\u00a0Shorshe Ilish (Hilsa in Mustard Sauce) or\u00a0Bengali Doi Maach recipe\u00a0for a weekday meal."]'::jsonb, 50, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2016/sept-26/Bengali_Mishti_Pulao_Recipe_Sweet_Rice_with_Dry_fruits-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1293.Bengali_Mishti_Pulao_Recipe_Sweet_Rice_with_Dry_fruits-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharashtrian Karanji Recipe (Gujiya) - A Delicious Diwali Sweet', 'maharashtrian-karanji-recipe-gujiya-a-delicious-diwali-sweet', 'Maharashtrian Karanji also known as Gujiya or Ghugra is a traditional sweet, commonly prepared by Maharashtrians during the festival of Diwali. The Karanji is a must have crunchy delicacy that is filled with oodles of delicious soft goodness of coconut, jaggery, semolina and spices.  Learn how to make Karanji the way it is prepared in most households of Maharashtra, by following the recipe below. Karanji or Gujiyas are typical dishes that are served during Holi.  Holi, the festival of colours in India is also a festival of great food. Holi food traditions involves people going to their neighbours and friends houses and enjoy this spring festival with a lot of snacks being passed around. The most popular savoury snacks during Holi snacks are Gujiyas, Kachoris, Samosas, Dahi Vada etc. Among the sweet snacks are sweet Gujiyas, Kulfis, Thandais and Malpuas.', '["Ingredients for the filling", "2 cups Jaggery , grated fine", "1 cup Whole Wheat Flour", "1 cup Dessicated Coconut , (either grated or flakes)", "1/2 cup Sooji (Semolina/ Rava)", "1/2 cup Sesame seeds (Til seeds)", "1/4 cup Poppy seeds", "3 tablespoon Oil , (I used edible almond oil)", "1 teaspoon Cardamom Powder (Elaichi)", "1 pinch Nutmeg powder", "Ingredients for the outer crust", "1/2 cup Sooji (Semolina/ Rava)", "1/2 cup All Purpose Flour (Maida)", "1 teaspoon Salt", "1 tablespoon Sugar", "3 tablespoon Ghee , or cooking oil", "1 cup Milk , (or half milk and water) or as required", "Oil , for deep frying"]'::jsonb, ARRAY['ingredients for the filling', 's jaggery', 'whole wheat flour', 'dessicated coconut', 'sooji', 'semolina/ rava', 'sesame seeds', 'til seeds', 'poppy seeds', 'oil', 'cardamom powder', 'elaichi', 'nutmeg powder', 'ingredients for the outer crust', 'all purpose flour', 'maida', 'salt', 'sugar', 'ghee', 'milk']::text[], '["To begin making the Maharashtrian Karanji Recipe (Gujiya), we will first make the make the filling.Begin by dry-roasting the coconut, sesame seeds and poppy seeds in a pan separately, until they turn golden brown.Make sure that they are roasted and kept separately, and never together once done.", "After they cool down, grind them separately in a mixer (poppy seeds, sesame seeds and coconut- in that order) till you get a coarse texture.Next, roast the semolina on medium heat in a shallow bottom pan with 1 tablespoon ghee or oil till it turns golden brown.", "Set this aside as well once done.Roast the whole wheat flour with the remaining ghee/oil in the same pan, until golden brown and keep aside.Now, put all the filling ingredients including the flour, semolina, coarse powders, jaggery, cardamom and nutmeg in a food processor, and blend them well for 2-3 minutes till they form a fine powder.", "The delicious coconut filling for the Karanji is now ready and can be set aside to be used later.", "The next step is to prepare the crust for the Karanji.", "Heat 3 tablespoons of ghee or in a small pan.", "Once ghee is melted or when the oil is hot, turn off the heat and keep aside.Add in\u00a0the all-purpose flour, rava, sugar and salt into a large deep bowl.", "Make a depression in the centre of the flours and pour the hot ghee into it mixing it into the flour thoroughly with your fingers.", "Knead the flour and other ingredients slowly by pouring the water and milk mixture a little at a time.Once the dough is pliable yet firm, cover it with a damp cloth and set it aside to rest for at least an hour or two.Once the dough is well rested, divide it into 4 equal sized balls.", "Roll each of these balls into a flat circular shape, apply a thin layer of oil evenly and mould them into tight elongated rolls.Once done, cut each of these 4 elongated rolls into 10 one inch pieces each, having about 40 pieces in total once all the rolling is done.", "Cover all these pieces with a damp cloth to keep the dough softened until they are ready to be made into the Karanji.Take one of the small dough pieces and with the help of a rolling pin, shape it into a small circular poori, 3-4 inch in diameter.", "Divide the poori into half, pour in 1-2 tablespoon of the filling on one side, and carefully fold the other half, closing the poori-shaped dough completely.In order to shape these pooris, press them on the cutting board, and carefully remove the extra dough using a karanji cutter.", "Once done, keep it aside to be fried.Repeat the same procedure for the remaining dough balls and cover the prepared karanjis with cloth when done.Finally, deep-fry all the prepared karanjis in hot oil, turning them continuously till they turn golden brown.Your lip-smacking, hot and crunchy Maharastrian Karanjis are now ready to be served for the festival of Dilwai.Serve\u00a0Maharashtrian Karanji Recipe (Gujiya) - A Delicious Diwali Sweet along with\u00a0Masala Chai Recipe\u00a0and\u00a0Omapodi Diwali Mixture Recipe\u00a0during evenings when there are guests and family at home or as a delicious snack during Holi."]'::jsonb, 90, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Maharashtrian_Karanji_Recipe_Gujiya_Archanas_Kitchen_A_Delicious_Diwali_Sweet-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1294.Maharashtrian_Karanji_Recipe_Gujiya_Archanas_Kitchen_A_Delicious_Diwali_Sweet-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('South Indian One Pot Sambar Rice Recipe', 'south-indian-one-pot-sambar-rice-recipe', 'Combine simple ingredients into one dish for a complete meal that doesn''t require extra work. These quick and easy one dish recipes are simple enough for any meal of the day. Sambar Rice Recipe is a one dish recipe that South Indians love as a comforting soul food for lunch and dinner.', '["1 teaspoon Ghee", "2 tablespoons Chana dal (Bengal Gram Dal)", "1 tablespoon White Urad Dal (Split)", "1 tablespoon Coriander (Dhania) Seeds", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "4 Dry Red Chillies", "1/4 cup Fresh coconut , Roughly chopped", "1 cup Rice , (Sona Masuri Variety)", "1/2 cup Pink Masoor Dal (Split)", "1/4 cup Potato (Aloo) , cubed", "1/4 cup Green beans (French Beans) , chopped", "1/4 cup Bottle gourd (lauki) , chopped", "1/2 cup Onion , sliced", "2 teaspoons Ghee", "2 teaspoons Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "2 Dry Red Chillies", "1 Green Chilli , slit", "1/8 teaspoon Asafoetida (hing)", "1/2 teaspoon Turmeric powder (Haldi)", "1/3 cup Tamarind Water", "1 tablespoon Jaggery", "4 cups Water", "Salt , to taste", "2 tablespoons Coriander (Dhania) Leaves , chopped"]'::jsonb, ARRAY['asafoetida (hing)', 'coriander (dhania) leaves', 'jaggery', 'white urad dal (split)', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil', 'salt', 'green chilli', 'dry red chillies', 'green beans (french beans)', 'tamarind water', 'mustard seeds', 'coconut', 'water', 'pink masoor dal (split)', 'rice (sona masuri variety)', 'methi seeds (fenugreek seeds)', 'ghee', 'potato (aloo)', 'bottle gourd (lauki)']::text[], '["To begin making South Indian One Pot Sambar Rice Recipe, heat a small saucepan with a teaspoon of ghee.Once the ghee is hot, add chana dal, urad dal and Fenugreek seeds.", "Fry them on a low to medium heat until golden and aromatic.Later stir in the coriander and Mustard seeds.", "Saute them for a minute or so until fragrant.Lastly, stir in the red chillies and coconut pieces.Saute well, transfer on to a plate and cool them to room temperature.", "Add enough water and grind into a thick paste.", "Set this aside until required."]'::jsonb, 65, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Mixed_Vegetable_Sambar_Rice-5.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1295.Mixed_Vegetable_Sambar_Rice-5.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Makhane Ki Phirni Recipe - Lotus Seed Milk Pudding', 'makhane-ki-phirni-recipe-lotus-seed-milk-pudding', 'Makhane Ki Phirni is beautiful combination of 2 classic dishes, Makhane Ki Kheer and Rice Phirni. The fusion of both these dishes is a delicious recipe that tastes divine and is perfect for a traditional festival like Navratri and Diwali.', '["1 liter Milk", "1 cup Phool Makhana (Lotus Seeds)", "1 cup Sugar", "1 tablespoon Ghee", "Ingredients For flavoring", "2 tablespoon Pistachios , (unsalted)", "1 teaspoon Saffron strands", "2 tablespoons Whole Almonds (Badam)", "6 Cardamom (Elaichi) Pods/Seeds , powdered", "2 tablespoons Cashew nuts", "1 Mace (Javitri)", "1 teaspoon Nutmeg powder", "Ingredients For Garnishing", "5 Rose Petals", "1 tablespoon Dry Fruits , (Raisins, Almonds, Cashew, Pistachio)"]'::jsonb, ARRAY['liter milk', 'phool makhana', 'lotus seeds', 'sugar', 'ghee', 'ingredients for flavoring', 'pistachios', 'saffron strands', 's whole almonds', 'badam', 'cardamom', 'elaichi', 's cashew nuts', 'mace', 'javitri', 'nutmeg powder', 'ingredients for garnishing', 'rose petals', 'dry fruits']::text[], '["Begin Makhane Ki Phirni Recipe (Lotus Seed Milk Pudding)\u00a0by heating the ghee on a skillet and roasting the makhana for about 5 minutes.", "Once roasted, pulse it in a blender for just a minute till it is reduced to a coarse powder.", "Set this aside to use later.Next, mix together all the ingredients to be used for flavoring, and lightly crush them with a rolling pin or pulse them just once in a grinder.", "Set these aside in a bowl as well.In a heavy bottomed pan, pour in the milk and add in the flavoring mixture and sugar, and boil them on low flame for about 10 minutes.", "Stir continuously to avoid the formation of any lumps.Add in the crushed makhana to the milk mixture and allow the milk simmer on low flame for another 10 minutes, stirring occasionally.", "Once done, switch off the gas and keep aside to allow the phirni to cool down.Pour the phirni into small serving bowls equally, garnishing it with rose petals and spoonful\u2019s of mixed dry fruit powderCover each serving bowl with cling film and keep them in the fridge for 2 - 3 hours.Serve\u00a0Makhane Ki Phirni Recipe (Lotus Seed Milk Pudding) chilled with a snack plate of\u00a0Methi Corn Dal Vada Recipe,\u00a0Moong Dal Mini Samosas (Delicious Tea Time Snack)\u00a0or serve it as a dessert after traditional lunch."]'::jsonb, 65, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Makhane_Ki_Phirni_Recipe_Lotus_Seed_Milk_Pudding-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1296.Makhane_Ki_Phirni_Recipe_Lotus_Seed_Milk_Pudding-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kumbakonam Kadappa Recipe - South Indian Style Lentil and Potato Stew', 'kumbakonam-kadappa-recipe-south-indian-style-lentil-and-potato-stew', 'Kumbakonam Kadappa Recipe is a very famous side dish for idlis and dosa from the Kumbakonam/Tanjore region of Tamil Nadu. It is a stew made using moong dal and potatoes with the addition of coconut in it. The simplicity of the dish makes it pretty flavourful and a brilliant side dish for any south indian breakfast recipes.', '["1/2 cup Green Moong Dal (Split) , boiled", "2 Potatoes (Aloo) , boiled", "1 Onion , sliced", "1 Tomato , finely chopped", "2 Green Chillies , finely chopped", "2 tablespoons Lemon juice", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 Bay leaf (tej patta)", "1 inch Cinnamon Stick (Dalchini)", "1 sprig Curry leaves", "2 tablespoons Oil", "Salt , to taste", "4 tablespoons Fresh coconut , grated", "2 cloves Garlic", "1 teaspoon Fennel seeds (Saunf)", "1 Green Chilli"]'::jsonb, ARRAY['tomato', 'salt', 'green chilli', 'mustard seeds', 'bay leaf (tej patta)', 'coconut', 'fennel seeds (saunf)', 'cloves garlic', 'curry leaves', 'onion', 'lemon', 'cumin seeds (jeera)', 'green moong dal (split)', 'cinnamon stick (dalchini)', 'potato (aloo)', 'green chillies', 'sunflower oil']::text[], '["To begin making the Kumbakonam Kadappa Recipe, wash and pressure cook the moong dal with enough water for 2 whistles using a pressure cooker.", "Once its cooked, mash it well and keep aside.Similarly, cook the potatoes using a pressure cooker for 2 whistles.", "Once it is cooled, peel the skin and mash it to a coarse texture.Heat a tablespoon of oil in a wok on medium heat, add the sliced onion and saute until it turns translucent.Add the tomatoes and green chillies and saute until the tomatoes are half cooked.Add the cooked mashed dal and the potatoes.", "Simmer for 5 minutes.Now make a smooth paste of grated coconut, garlic cloves, fennel seeds and green chilli adding little water using a mixer grinder.Add this coconut spice paste to the simmering moong dal and potato curry.", "Mix well and simmer for 2 more minutes and switch off the flame.Now heat oil in a tadka pan, add the cinnamon stick and bay leaf and it release its flavours into the oil.Add the mustard and cumin seeds and let it crackle.", "Add the curry leaves and let it splutter as well.Pour this tadka over the prepared stew, add the lemon juice and mix well.Serve the Kumbakonam Kadappa Recipe along with\u00a0steaming hot idlis\u00a0and crispy dosa''s for the weekend breakfast."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/9-feb/Kumbakonam_Kadappa_Recipe_South_Indian_Style_Lentil_and_Potato_Stew-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1297.Kumbakonam_Kadappa_Recipe_South_Indian_Style_Lentil_and_Potato_Stew-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kanda Kairichi Chutney Recipe - Onion & Raw Mango Chutney', 'kanda-kairichi-chutney-recipe-onion-raw-mango-chutney', 'Kanda Kairichi Chutney Recipe (Maharashtrian Onions & Raw Mango Chutney) is a quick side dish that can jazz up a meal. Tart unripe mangoes team up with sharp pungent onions to make this tangy,sweet & spicy condiment.', '["1 cup Mango (Raw) , peeled and chopped", "1 Onion , chopped", "2 tablespoons Jaggery , (powdered)", "3 tablespoons Roasted Peanuts (Moongphali)", "2 teaspoons Red Chilli powder , (adjust to taste)", "Salt , to taste", "1 tablespoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)"]'::jsonb, ARRAY['salt', 'mustard seeds', 'asafoetida (hing)', 'jaggery', 'red chilli powder', 'mango', 'onion', 'cumin seeds (jeera)', 'peanuts (moongphali)', 'sunflower oil']::text[], '["To begin making Kanda Kairichi Chutney Recipe (Maharashtrian Onions & Raw Mango Chutney) first get all the ingredients handy.In a mixer-jar combine, mangoes, onion, jaggery, groundnuts, salt and chilli powder, grind to a fine paste along with a little water.", "In a tadka pan, heat a little oil on medium flame.", "Add the mustard seeds and once they crackle, add the cumin seeds and allow to sizzle.Take the tadka pan off the heat after cumin seeds sizzle and add hing and stir.Pour this tempering over the Kanda Kairichi Chutney Recipe and mix well.", "Serve Kanda Kairichi Chutney Recipe (Maharashtrian Onions & Raw Mango Chutney) with\u00a0Sabudana Thalipeeth Recipe (Tapioca Pearl Spicy Flat Bread)\u00a0or\u00a0Maharashtrian Vegetable Amboli Recipe\u00a0for a delicious meal."]'::jsonb, 20, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/madhulia/Kanda_Kairichi_Chutney_Recipe_Maharashtrian_Onions_and_Raw_Mango_Chutney-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1298.Kanda_Kairichi_Chutney_Recipe_Maharashtrian_Onions_and_Raw_Mango_Chutney-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Indian Style Kala Chana Salad Recipe', 'indian-style-kala-chana-salad-recipe', 'Indian Style Black Chickpea Salad is the right salad for the days when you want to eat something healthy and tasty. It is very easy to make and can be eaten at anytime of the day. It also makes a good breakfast for the busy days when you want to eat healthy.', '["2 cups Kala Chana (Brown Chickpeas) , soaked overnight and boiled", "1 Onion , finely chopped", "1 Tomato , finely chopped", "2 Green Chillies , finely chopped (adjustable)", "Coriander (Dhania) Leaves , , finely chopped", "Salt , as required", "1/2 teaspoon Black pepper powder", "1 Lemon juice", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Black pepper powder", "1 Lemon juice"]'::jsonb, ARRAY['tomato', 'salt', 'coriander (dhania) leaves', 'red chilli powder', 'onion', 'lemon', 'black pepper powder', 'green chillies()', 'kala chana (brown chickpeas)']::text[], '["To begin making the Indian Style Black Chickpea Salad recipe, wash and soak the chana in water,and leave it overnight.", "In a pressure cooker, add the chana and water and pressure cook for 6 whistles on high flame, reduce the flame and continue to cook for 15 more minutes.", "Turn off the flame.", "Allow the pressure to release naturally, drain the water and transfer the chana into a bowl and set aside.", "In a mixing bowl, combine the kala chana,\u00a0onion, tomato and green chilliesMix everything properly and add black pepper powder, salt, lemon juice and coriander leaves.Mix everything well and serve it immediately.", "Serve Indian Style Black Chickpea Salad along with\u00a0Gujarati Dal,\u00a0Roti\u00a0and Bhindi Masala Recipe (Bhindi Tamatar Ki Sabzi)\u00a0Rice for a weekday meal."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Kala_Chana_Salad_With_Cucumber_Tomatoes_Onions_Green_Chillies-6.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1299.Kala_Chana_Salad_With_Cucumber_Tomatoes_Onions_Green_Chillies-6.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mango Payasam Recipe-Mambazha Payasam - Onam Special', 'mango-payasam-recipe-mambazha-payasam-onam-special', 'Mango Payasam also known as the Mambazha Payasam is a very festive recipe that is made during the Onam Festival in Kerala. The payasam recipe is healthy and nutritious made from ripe mangoes, jaggery, ginger, spices and of course the goodness of milk and dry fruits and nuts. Try the delicious Mango Payasam this Onam and you and your family are sure you love it.', '["1 Mango (Ripe) , peeled and cut", "1/2 cup Jaggery", "1/2 teaspoon Dry ginger powder", "1 teaspoon Cardamom Powder (Elaichi)", "2 liter Milk", "1/4 cup Broken Raw Rice , washed", "10 Cashew nuts , roughly broken", "10 Sultana Raisins", "1 tablespoon Ghee"]'::jsonb, ARRAY['mango', 'ripe', 'jaggery', 'dry ginger powder', 'cardamom powder', 'elaichi', 'liter milk', 'broken raw rice', 'cashew nuts', 'sultana raisins', 'ghee']::text[], '["To begin making the Mango Payasam Recipe, in a mixer-jar blend 1 cup of milk along with the ripe mangoes, jaggery, cardamom powder, ginger powder to make a smooth puree.", "Keep aside.In a heavy bottom saucepan, add in the remaining milk and the washed, and drained rice and give it a brisk boil.", "Once it comes to a boil, turn the heat to low and simmer the mixture stirring frequently until the rice is cooked and soft.", "This process will take a good 25-30 minutes.", "Once the rice is cooked, add in the mago mixture and stir to combine the ingredients well.", "Simmer the payasam for another 10 minutes until you get the flavors from the condensing milk.", "Check for sweetness, add more jaggery if required.Finally heat a tablespoon of ghee in a small pan, on low heat roast the cashew nuts until lightly browned.", "Once browned, add in the raisins and roast for a few more seconds.", "Add this to the above Mango Payasam.", "Transfer the Mango Payasam to a serving bowl.", "You can serve this hot or cold for the Onam festival along with your Onam sadya meal.Serve the\u00a0Mango Payasam Recipe (Mambazha Payasam - Onam Festival Special) as an\u00a0onam dessert\u00a0and relish it along with your family members.You could also serve it as a dessert after a simple kerala style meal of\u00a0Kerala Avial Recipe\u00a0and\u00a0Steamed Rice."]'::jsonb, 40, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Mango_Payasam_Recipe_Mambazha_Payasam_Onam_Festival_Special-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1300.Mango_Payasam_Recipe_Mambazha_Payasam_Onam_Festival_Special-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gajar Amla Raita Recipe - Carrot Gooseberry Raita Recipe', 'gajar-amla-raita-recipe-carrot-gooseberry-raita-recipe', 'Raitas are whipped curd/ yogurt with cooked or raw vegetables in them that are served as a side dish for Biryani or Pulao and even parathas. In this recipe of Gajar Nariyal Amla Raita Recipe, grated carrot, grated coconut and cut amla is added to a bowl of whipped curd/yogurt and tempered with mustard seeds and jeera.', '["1 cup Curd (Dahi / Yogurt)", "1 Carrot (Gajjar) , grated", "4 Amla (Nellikai/ Gooseberry) , cut and deseeded", "1/4 teaspoon Split Mustard Seeds (Rai Kuria)", "1/4 teaspoon Red Chilli powder", "2 tablespoons Fresh coconut , grated", "1 Green Chilli , finely chopped", "Salt , to taste", "1/4 teaspoon Oil", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves"]'::jsonb, ARRAY['salt', 'sunflower oil', 'green chilli', 'coconut', 'mustard seeds', 'amla (nellikai gooseberry)', 'red chilli powder', 'carrot', 'curd', 'curry leaves', 'cumin seeds (jeera)', 'split mustard seeds (rai kuria)']::text[], '["To begin making Carrot Amla Raita Recipe With Coconut, in a bowl, add yogurt, salt and beat it with a whisk for a few minutes until it is smooth without lumps.", "Keep aside.", "Cut the amla/gooseberries and discard the seeds.", "Toss the amla in the rai kuria, red chilli powder and salt.", "Allow it ti rest for 15 minutes.Stir in the grated carrot, green chilli, cut amla and grated coconut into the dahi.", "Stir well to combine the\u00a0Carrot Amla Raita Recipe.", "Check salt and adjust according to taste.To temper the Carrot Amla Raita Recipe With Coconut, place a tadka pan ober medium heat with one 1/4 teaspoon oil.Once the oil is hot, add the mustard seeds and jeera seeds dal.", "Let the mustard seeds crackle.", "Stir in the curry leaves and turn off the heat.Pour this tempering over the Gajar Amla Raita and mix well.", "Serve Gajar Nariyal Amla Raita Recipe along with Hyderabadi Vegetable Biryani Recipe and Mirchi Ka Salan Recipe\u00a0for a wonderful weeknight dinner."]'::jsonb, 18, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Gajar_Amla_Raita_Recipe_-_Carrot_Gooseberry_Raita-5.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1301.Gajar_Amla_Raita_Recipe_-_Carrot_Gooseberry_Raita-5.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mango Kesari Recipe | Mango Sooji Halwa | Mango Sheera', 'mango-kesari-recipe-mango-sooji-halwa-mango-sheera', 'Mango Kesari or Mango Sheera is a halwa recipe inspired by the king of fruits - mango – that is not only luscious and decadent, but also packs a nutritious punch. Mango Kesari is an Indian sweet pudding prepared using semolina or broken wheat.', '["1 cup Sooji (Semolina/ Rava)", "1/4 cup Ghee", "2-1/2 cups Water , depending on the consistency you desire", "1/2 cup Sugar", "1 Mango (Ripe) , peeled and pureed", "1/2 teaspoon Cardamom Powder (Elaichi)", "Ingredients for garnish", "1 tablespoons Ghee", "10 Cashew nuts , halved", "10 Cashew nuts , chopped"]'::jsonb, ARRAY['sooji', 'semolina/ rava', 'ghee', 's water', 'sugar', 'mango', 'ripe', 'cardamom powder', 'elaichi', 'ingredients for garnish', 's ghee', 'cashew nuts']::text[], '["To begin making the Mango Kesari or Mango Sheera Recipe, we will first prepare the mango pulp.Wash the mango well and peel it.", "Roughly chop the fruit into pieces and discard the seed/stone.Blend the chopped mango in a mixer until smooth.", "Put the pulp in a bowl and set it aside for later use.In a small tadka pan melt a teaspoon of ghee.", "Add the chopped cashew nuts to it and gently toast them, over a low heat until golden brown and crisp, taking care not to burn them.", "Turn off the heat, and set the pan aside for later use.Heat the 1/4 cup of ghee in a heavy bottomed pan over medium heat and dry roast the semolina (rava) gently, until it gets lightly toasted and aromatic.", "Meanwhile, put 2-1/2 cups of water in a saucepan and set it over a medium heat.", "Add the sugar and bring it to a boil.", "Allow it to boil for a minute.At this stage, add it to the roasted semolina slowly, in a steady stream while continuously stirring the semolina.", "Lower the flame at this stage, and ensure that you are stirring the mixture, to prevent the formation of lumps.The semolina will combine with the water and slowly coagulate into a halwa-like consistency.", "If there are any lumps, break them with the back of the spoon and continue to stir gently.Next, add the mango pulp to the sooji sheera (halwa) and mix gently.", "Cook the sheera (halwa) for about 5 to 7 minutes, stirring occasionally until the halwa comes away from the sides of the pan.Turn off the heat and garnish with cardamom powder and the toasted cashews.", "Give it a last stir and serve.Serve the\u00a0Mango Kesari (Sheera) as a dessert for lunch parties or make it for breakfast as an accompaniment along with Sooji (Rava) Upma or make it as a special sweet for the festival season."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Mango_Sooji_Halwa_Recipe_Aam_Ka_Sheera_Mango_Kesari-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1302.Mango_Sooji_Halwa_Recipe_Aam_Ka_Sheera_Mango_Kesari-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Dalia Pulao Recipe - Broken Wheat Pulao', 'spicy-dalia-pulao-recipe-broken-wheat-pulao', 'Spicy Dalia Pulao Recipe is a healthy twist to Pulao which we normally make at home. Instead of using Basmati rice or normal rice, we have used Dalia. Dalia or broken wheat is a healthy substitute in a Pulao that is nutritious, high in iron and fiber.', '["1 cup Broken Wheat (Dalia/ Godumai Rava)", "Water , as required", "2 Onion , finely chopped", "1 Carrot (Gajjar) , finely chopped", "5 Green beans (French Beans) , finely chopped", "2 Green Chillies , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Cumin seeds (Jeera)", "Salt , to taste", "1/2 teaspoon Garam masala powder", "1 teaspoon Red Chilli powder", "2 Tomatoes , chopped", "1 teaspoon Ginger Garlic Paste", "1 Bay leaf (tej patta)", "1 teaspoon Red Chilli powder", "2 Tomatoes , chopped", "1 teaspoon Ginger Garlic Paste", "Coriander (Dhania) Leaves , finely chopped for garnish"]'::jsonb, ARRAY['tomato', 'salt', 'green beans (french beans)', 'wheat (dalia godumai rava)', 'bay leaf (tej patta)', 'coriander (dhania) leaves', 'red chilli powder', 'water', 'carrot', 'ginger garlic paste', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies', 'garam masala powder']::text[], '["To begin making the Spicy Dalia Pulao Recipe, first we have to dry roast Dalia or broken wheat till it gets a nice aroma.For this, in a skillet heat 1 teaspoon of ghee on low flame, add the dalia and roast till it gets a deep brown colour.", "This will take 5 minutes.", "Now turn off the flame ans set aside.", "In a pressure cooker, add 1 teaspoon oil, and heat on medium flame, now add a bay leaf and cumin seeds and allow it to sizzle.", "Next add chopped onion and saute it till it is translucent.", "Add ginger garlic paste, green chillies, carrots, beans and chopped tomatoes, saut\u00e9 it for two minutes.Continue to saute for 3 \u2013 4 minutes.", "Add salt, spices- turmeric powder, garam masala powder and red chilli powder and mix them.Now add dry roasted broken wheat and mix well.", "Add 2 cups of water and close the pressure cooker.", "Pressure cook the pulao for 4 whistles and turn off the flame.", "Allow the pressure to release naturally.", "Serve hot.Spicy Dalia Pulao\u00a0can be served with\u00a0Burani Raita\u00a0and finish off this simple meal with\u00a0Double Ka Meetha Recipe With Mixed Nuts Rabri."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Roop/Dalia_Khichdi_Recipe_Broken_Wheat_Khichdi-1_preview.jpeg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1303.Dalia_Khichdi_Recipe_Broken_Wheat_Khichdi-1_preview.jpeg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Egg Biryani Recipe With Coconut Milk', 'egg-biryani-recipe-with-coconut-milk', 'The Egg Biryani Recipe is a simple and wholesome biryani that you can make in a jiffy for a weeknight dinner.', '["2 cups Rice", "6 Whole Eggs , boiled", "1 Bay leaf (tej patta)", "2 Cardamom (Elaichi) Pods/Seeds", "2 Cloves (Laung)", "1 Green Chilli , slit down the middle", "1/4 teaspoon Whole Black Peppercorns", "2 Onions , thinly sliced", "3 Tomatoes , diced small", "6 cloves Garlic , minced or grated", "1 inch Ginger , minced or grated", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Coriander Powder (Dhania)", "1 teaspoon Garam masala powder", "2 cups Coconut milk", "1 1/2 cups Water", "Salt , to taste", "Coriander (Dhania) Leaves , small bunch, finely chopped", "Mint Leaves (Pudina) , small bunch, finely chopped"]'::jsonb, ARRAY['tomato', 'cumin powder (jeera)', 'black peppercorns', 'cloves garlic', 'onion', 'green chilli down the middle', 'turmeric powder', 'salt', 'coriander (dhania)', 'cardamom (elaichi) podsseeds', 'mint leaves (pudina)', 'garam masala powder', 'rice', 'red chilli powder', 'water', 'coconut milk', 'eggs', 'ginger', 'bay leaf (tej patta)', 'coriander powder', 'cloves (laung)']::text[], '["To begin making the Egg Biryani Recipe, we will first set the eggs to boil so they are cooked and kept ready."]'::jsonb, 120, 'Indian', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Egg_Biryani_Recipe_With_Coconut_Milk-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1304.Egg_Biryani_Recipe_With_Coconut_Milk-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Hurali Saaru Recipe - Healthy Horse Gram and Coconut Curry', 'hurali-saaru-recipe-healthy-horse-gram-and-coconut-curry', 'The Hurali Saaru Recipe is a delicious lentil curry that is made from horse gram also known as Kollu in Tamil or Kulith in Hindi. In this recipe the horse gram is cooked with aromatic spices ground into a masala with coconut and finally seasoned with ghee and onions making it a perfect curry to go along with rice.', '["1/2 cup Horse Gram Dal (Kollu/ Kulith) , soaked for at least 4-5 hours or overnight", "1 Onion , roughly chopped", "1 Tomato , roughly chopped", "1 Potato (Aloo) , chopped into chunks (optional)", "1/4 Cup Tamarind Water", "Ingredients for the Curry Masala", "1 Onion", "1 Tomato", "1/4 cup Fresh coconut , grated", "2 Cloves (Laung)", "1 inch Cinnamon Stick (Dalchini)", "1 inch Ginger", "4 cloves Garlic", "2 teaspoons Sambar Powder", "Ingredients for the seasoning", "1 Onion , chopped finely", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Dry Red Chillies", "2 sprig Curry leaves", "1/4 teaspoon Asafoetida (hing)", "2 teaspoon Ghee"]'::jsonb, ARRAY['tomato', 'horse gram dal (kollu kulith) least', 'ginger', 'tamarind water', 'coconut', 'sambar powder', 'mustard seeds', 'potato (aloo)', 'asafoetida (hing)', 'ghee', 'cloves garlic', 'curry leaves', 'dry red chillies', 'onion', 'cinnamon stick (dalchini)', 'cloves (laung)']::text[], '["To begin, pressure cook the soaked horse-gram for two whistles over medium heat, along with the chopped onion, tomato and potato.", "Turn off the heat after two whistles and let the steam release naturally from the pressure cooker.Meanwhile, in a mixer grind all the curry ingredients to make the smooth paste using little water.", "Transfer to a bowl and set aside.Open the lid of the pressure cooker, add the curry masala, close the lid once again and pressure cook the horse-gram for two more whistles.", "Open the pressure cooker, add the tamarind extract and salt to taste, and let the curry simmer for few minutes till all the flavours are combined well.For the tempering, in a tadka pan\u00a0heat the ghee over medium heat.", "Add the mustard seeds and onions and saut\u00e9 gently on a low heat till the onions become golden in colour.", "Next add the curry leaves, asafoetida and red chillies.", "When it all sputter, pour it over the curry and stir to combine.", "Serve\u00a0Hurali Saaru\u00a0with steamed rice or Phulka for the wholesome lunch."]'::jsonb, 40, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Huruli_Saaru_Recipe_Healthy_Horse_Gram_and_Coconut_Curry-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1305.Huruli_Saaru_Recipe_Healthy_Horse_Gram_and_Coconut_Curry-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('मसूर दाल गस्सि रेसिपी - Masoor Dal Gassi Recipe', 'masoor-dal-gassi-recipe', 'मसूर दाल गस्सि रेसिपी एक तीखी, खट्टी रेसिपी है जिसमे मसूर दाल का प्रयोग किया जाता है. इसे मैंगलोर के हर घर में बनाया जाता है. इसमें ताज़े मसालो को नारियल के साथ पीसकर डाला जाता है. अपने रोज के खाने के लिए इसे बनाए और हमे भरोसा है की आपके घर वालो को यह जरूर पसंद आएगी।', '["3/4 \u0915\u092a \u092e\u0938\u0942\u0930 \u0926\u093e\u0932", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f", "1/3 \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947", "20 \u0917\u094d\u0930\u093e\u092e \u0907\u092e\u0932\u0940", "3 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u091a\u094d\u091a \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "\u0918\u0940 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0930\u093e\u0907", "3 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928", "5 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "2 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a"]'::jsonb, ARRAY['कप मसूर दाल', 'छोटा चमच्च हल्दी पाउडर', 'नमक', 'पेस्ट बनाने के लिए', 'नारियल', 'ग्राम इमली', 'सुखी लाल मिर्च', 'छोटे चमच्च धनिये के बीज', 'तड़के के लिए', 'घी', 'छोटा चमच्च राइ', 'कली लहसुन', 'कढ़ी पत्ता']::text[], '["\u092e\u0938\u0942\u0930 \u0926\u093e\u0932 \u0917\u0938\u094d\u0938\u093f \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0926\u093e\u0932 \u0915\u094b \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u092a\u0915\u093e \u0932\u0947. \u0926\u093e\u0932 \u0915\u094b \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0928\u092e\u0915, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930 \u0914\u0930 2-1/2 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947\u0964 \u0915\u0941\u0915\u0930 \u0915\u094b \u0922\u0915\u0947 \u0914\u0930 2 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.2 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0906\u0902\u091a \u0927\u0940\u092e\u0940 \u0915\u0930\u0947\u0902 \u0914\u0930 4 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947 \u0914\u0930 \u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u0939\u092e \u0917\u0938\u094d\u0938\u093f \u0915\u0947 \u0932\u093f\u090f \u092e\u0938\u093e\u0932\u093e \u092c\u0928\u093e\u090f\u0901\u0917\u0947\u0964 \u090f\u0915 \u091b\u094b\u091f\u0947 \u092a\u0948\u0928 \u092e\u0947\u0902 \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c \u0914\u0930 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947\u0964 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0938\u0947\u0915 \u0932\u0947. \u0938\u093f\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0930\u0916 \u0926\u0947.\u00a0\u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a, \u0928\u093e\u0930\u093f\u092f\u0932, \u0907\u092e\u0932\u0940 \u0914\u0930 \u0932\u0939\u0938\u0941\u0928 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947\u0964 \u0925\u094b\u095c\u093e \u0917\u0930\u092e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947, \u092a\u093f\u0938\u0947\u00a0\u0914\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947.\u00a0\u0907\u0938 \u092e\u0938\u093e\u0932\u0947 \u0915\u094b \u0926\u093e\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u092c\u0932\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0930\u0916 \u0932\u0947. \u0926\u093e\u0932 \u0915\u094b 3 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0909\u092c\u0932\u0928\u0947 \u0926\u0947. \u0905\u092a\u0928\u0947 \u0939\u093f\u0938\u093e\u092c \u0938\u0947 \u0925\u094b\u095c\u093e \u0914\u0930 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. \u0907\u0938\u0947 \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0928\u093f\u0915\u093e\u0932 \u0932\u0947\u00a0\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f \u090f\u0915 \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947. \u0907\u0938\u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0932\u0939\u0938\u0941\u0928, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u0914\u0930 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947\u0964\u00a015 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0924\u0915 \u092a\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u0947 \u0926\u093e\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u092e\u0938\u0942\u0930 \u0926\u093e\u0932 \u0917\u0938\u094d\u0938\u093f\u00a0\u0930\u0947\u0938\u093f\u092a\u0940 \u0915\u094b \u091a\u093e\u0935\u0932,\u00a0\u091a\u093e\u0909 \u091a\u093e\u0909 \u0925\u094b\u0930\u0928\u00a0\u0914\u0930 \u092a\u091a\u095c\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 50, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Masoor_Dal_Ghassi_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1306.Masoor_Dal_Ghassi_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('केरला स्टाइल उल्ली थियल रेसिपी - Kerala Style Ulli Theeyal Recipe', 'kerala-style-ulli-theeyal-recipe', 'केरला स्टाइल उल्ली थियल केरला की रेसिपी है जिसमे छोटे प्याज का प्रयोग किया जाता है. इस रेसिपी में छोटे प्याज को पकाकर इमली और नारियल की ग्रेवी में डाला जाता है. यह एक आसान रेसिपी है जिसे आप ओनम या किसी भी दूसरे त्यौहार के लिए बना सकते है.', '["200 \u0917\u094d\u0930\u093e\u092e \u091b\u094b\u091f\u0947 \u092a\u094d\u092f\u093e\u091c", "2 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "2 \u0915\u092a \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u093e\u0928\u0940", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0930\u093e\u0907", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0940\u0902\u0917", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "3 \u092c\u095c\u0947 \u091a\u092e\u091a\u094d\u091a \u0924\u0947\u0932", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e\u0928\u0947 \u0915\u0940 \u0938\u093e\u092e\u0917\u094d\u0930\u0940", "1 \u092c\u095c\u0947 \u091a\u092e\u091a\u094d\u091a \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u091c\u0940\u0930\u093e", "6 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "1 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947"]'::jsonb, ARRAY['ग्राम छोटे प्याज', 'टहनी कढ़ी पत्ता', 'कप इमली का पानी', 'छोटा चमच्च राइ', 'छोटा चमच्च हींग', 'छोटा चमच्च हल्दी पाउडर', 'बड़े चमच्च तेल', 'नमक', 'पेस्ट बनाने की सामग्री', 'बड़े चमच्च धनिये के बीज', 'छोटा चमच्च जीरा', 'सुखी लाल मिर्च', 'कप नारियल']::text[], '["\u0915\u0947\u0930\u0932\u093e \u0938\u094d\u091f\u093e\u0907\u0932 \u0909\u0932\u094d\u0932\u0940 \u0925\u093f\u092f\u0932 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u091b\u094b\u091f\u0940 \u0915\u095d\u093e\u0908 \u0915\u094b \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c, \u091c\u0940\u0930\u093e, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a, \u0928\u093e\u0930\u093f\u092f\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u0947 \u0938\u0941\u0928\u0939\u0930\u093e\u00a0\u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u0920\u0902\u0921\u093e \u0915\u0930\u0947\u0902 \u0914\u0930 \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0915\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947.\u00a0\u00a0\u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947. \u0924\u095c\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0914\u0930 \u091b\u094b\u091f\u0947 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947. \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0925\u094b\u095c\u093e \u0928\u0930\u092e \u0914\u0930 \u0938\u0941\u0928\u0939\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0915\u092e \u0938\u0947 \u0915\u092e 10 \u092e\u093f\u0928\u091f \u0932\u0917\u0947\u0902\u0917\u0947\u0964\u00a0\u00a0\u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u092a\u0915 \u091c\u093e\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u093e\u0928\u0940, \u0939\u0940\u0902\u0917, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915 \u0914\u0930 \u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947\u0964 \u0938\u092c\u0915\u094b \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947 \u0914\u0930 \u0927\u0940\u092e\u0940 \u0906\u0902\u091a \u092a\u0930 10 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u0928\u0947 \u0926\u0947.\u00a010 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926\u00a0\u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0928\u093f\u0915\u093e\u0932 \u0926\u0947.\u0915\u0947\u0930\u0932\u093e \u0938\u094d\u091f\u093e\u0907\u0932 \u0909\u0932\u094d\u0932\u0940 \u0925\u093f\u092f\u0932\u00a0\u0915\u094b \u091a\u093e\u0935\u0932,\u00a0\u091a\u093e\u0909 \u091a\u093e\u0909 \u0925\u094b\u0930\u0928\u00a0\u0914\u0930 \u092a\u093e\u092a\u095c \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 35, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Kerala_Style_Ulli_Theeyal_Kerala_Vengayam_Puli_Kuzhambu_Recipe_Small_Onions_Roasted_in_Spicy_Tamarind_Coconut_Gravy-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1307.Kerala_Style_Ulli_Theeyal_Kerala_Vengayam_Puli_Kuzhambu_Recipe_Small_Onions_Roasted_in_Spicy_Tamarind_Coconut_Gravy-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('कुरुकु कालन रेसिपी - Kurukku Kaalan Recipe', 'kurukku-kaalan-recipe', 'कुरुकु कालन रेसिपी एक स्वादिष्ट डिश है जिसमे केले को दही और नारियल की करी में पकाया जाता है. यह केरला के हर घर में बनाई जाती है और इस करी को ओनम पर भी बनाया जाता है.', '["2 \u0915\u091a\u094d\u091a\u093e \u0915\u0947\u0932\u093e , \u091b\u0940\u0932\u0915\u0930 \u0915\u093e\u091f \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u0915\u092a \u0926\u0939\u0940", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u092a\u0940\u0938\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u093e\u092e\u0917\u094d\u0930\u0940", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u091c\u0940\u0930\u093e", "1 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u093e\u092e\u0917\u094d\u0930\u0940", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u093e \u0924\u0947\u0932", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u091c\u0940\u0930\u093e", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0930\u093e\u0907", "1/8 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u092e\u0947\u0925\u0940 \u0915\u0947 \u0926\u093e\u0928\u0947", "2 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a , \u092c\u093f\u091a \u092e\u0947\u0902 \u0938\u0947 \u0924\u094b\u095c \u0932\u0947", "2 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e"]'::jsonb, ARRAY['कच्चा केला', 'छोटा चमच्च हल्दी पाउडर', 'कप दही', 'छोटा चमच्च लाल मिर्च पाउडर', 'नमक', 'पीसने के लिए सामग्री', 'हरी मिर्च', 'छोटा चमच्च जीरा', 'कप नारियल', 'तड़के के लिए सामग्री', 'छोटा चमच्च नारियल का तेल', 'छोटा चमच्च राइ', 'छोटा चमच्च मेथी के दाने', 'सुखी लाल मिर्च', 'टहनी कढ़ी पत्ता']::text[], '["\u0915\u0941\u0930\u0941\u0915\u0941 \u0915\u093e\u0932\u0928 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0915\u091a\u094d\u091a\u093e \u0915\u0947\u0932\u093e, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e, \u0928\u092e\u0915, 1/4 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947.\u0915\u0941\u0915\u0930 \u0915\u094b \u0916\u094b\u0932\u0947, \u0907\u0938\u092e\u0947\u0902 \u0926\u0939\u0940 \u0914\u0930 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u0947 \u0938\u093e\u0925 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u091c\u0940\u0930\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947.\u00a0\u0907\u0938 \u092a\u093f\u0938\u0947 \u0939\u0941\u090f \u092e\u0938\u093e\u0932\u0947 \u0915\u094b \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947, \u0917\u0948\u0938 \u091a\u093e\u0932\u0942 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0909\u092c\u0932\u0928\u0947 \u0926\u0947.\u00a0\u091c\u092c \u0924\u0915 \u0915\u093e\u0932\u0928 \u0909\u092c\u093e\u0932 \u0930\u0939\u093e \u0939\u0948, \u0939\u092e \u0907\u0938\u0915\u0947 \u0932\u093f\u090f \u0924\u095c\u0915\u093e \u092c\u0928\u093e\u090f\u0901\u0917\u0947\u0964 \u090f\u0915 \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u093e \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907 , \u091c\u0940\u0930\u093e, \u092e\u0947\u0925\u0940 \u0915\u0947 \u0926\u093e\u0928\u0947, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0914\u0930 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947\u0964\u00a015 \u0938\u0947 20 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u092c\u093e\u0926, \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0926\u0947. \u0915\u093e\u0932\u0928 \u0915\u0947 \u0909\u092c\u093e\u0932\u093e \u0906 \u091c\u093e\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938 \u0924\u095c\u0915\u0947 \u0915\u094b \u0917\u094d\u0930\u0947\u0935\u0940 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0917\u0930\u092e\u093e \u0917\u0930\u092e \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0915\u0941\u0930\u0941\u0915\u0941 \u0915\u093e\u0932\u0928\u00a0\u0915\u094b \u091a\u093e\u0935\u0932, \u092c\u0940\u091f\u0930\u0942\u091f \u0925\u094b\u0930\u0928, \u092a\u091a\u095c\u0940 \u0914\u0930 \u092a\u093e\u092a\u095c \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 55, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Kuruku_Kaalan_Recipe_Raw_Bananas_in_Coconut_Curry-7.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1308.Kuruku_Kaalan_Recipe_Raw_Bananas_in_Coconut_Curry-7.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('केरला स्टाइल एग रोस्ट करी रेसिपी - Kerala Style Egg Roast Curry Recipe', 'kerala-style-egg-roast-curry-recipe', 'केरला स्टाइल एग रोस्ट करी रेसिपी एक स्वादिष्ट एग करी है जिसमे टमाटर और प्याज की ग्रेवी बनाई जाती है. केरला में इसे अप्पम के साथ सुबह के नाश्ते के लिए परोसा जाता है. आप इस करी को तब भी बना सकते है जब आपके घर पर खाने के लिए मेहमान आ रहे हो.', '["2 \u0905\u0902\u0921\u0947 , \u0909\u092c\u093e\u0932\u0915\u0930 \u092c\u093f\u091a \u092e\u0947\u0902 \u0938\u0947 \u0915\u093e\u091f \u0932\u0947", "2 \u092a\u094d\u092f\u093e\u091c , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "2 \u091f\u092e\u093e\u091f\u0930 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "2 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u0905\u0926\u0930\u0915 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "3/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0915\u0936\u094d\u092e\u0940\u0930\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "\u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947, \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "1/4 \u0915\u092a \u092a\u093e\u0928\u0940", "2 \u092c\u095c\u0947 \u091a\u092e\u091a\u094d\u091a \u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u093e \u0924\u0947\u0932", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['अंडे', 'प्याज', 'टमाटर', 'कली लहसुन', 'अदरक', 'टहनी कढ़ी पत्ता', 'छोटा चमच्च गरम मसाला पाउडर', 'छोटा चमच्च काली मिर्च पाउडर', 'छोटा चमच्च कश्मीरी लाल मिर्च पाउडर', 'छोटा चमच्च धनिया पाउडर', 'छोटा चमच्च हल्दी पाउडर', 'हरा धनिया', 'कप पानी', 'बड़े चमच्च नारियल का तेल', 'नमक']::text[], '["\u0915\u0947\u0930\u0932\u093e \u0938\u094d\u091f\u093e\u0907\u0932 \u090f\u0917 \u0930\u094b\u0938\u094d\u091f \u0915\u0930\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0905\u0926\u0930\u0915, \u0932\u0939\u0938\u0941\u0928, \u092a\u094d\u092f\u093e\u091c \u0914\u0930 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947\u0964 \u0906\u0902\u091a \u0915\u094b \u092e\u0927\u094d\u092f\u092e \u092a\u0930 \u0930\u0916\u0947\u0902 \u0914\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0914\u0930 \u0939\u0932\u094d\u0915\u093e \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930, \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. 2 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u0928\u0947 \u0926\u0947.\u00a02 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930 \u0914\u0930 \u0928\u092e\u0915 \u0921\u093e\u0932\u0947\u0964 3 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u0928\u0947 \u0926\u0947.\u00a0\u00a03 \u0938\u0947 4 \u092e\u093f\u0928\u091f\u00a0\u0915\u0947 \u092c\u093e\u0926 1/4 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u092c\u0932\u0928\u0947 \u0926\u0947. \u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0906\u0902\u091a \u0915\u094b \u0927\u0940\u092e\u093e \u0915\u0930\u0947\u0902 \u0914\u0930 \u0907\u0938\u092e\u0947\u0902 \u0909\u092c\u0932\u0947 \u0939\u0941\u090f \u0905\u0902\u0921\u0947 \u0921\u093e\u0932\u0947\u0964\u00a0\u0915\u095d\u093e\u0908 \u0915\u094b \u0922\u0915\u0947 \u0914\u0930 \u0927\u0940\u092e\u0940 \u0906\u0902\u091a \u092a\u0930 10 \u0938\u0947 15 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u0928\u0947 \u0926\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u0947 \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902\u0964\u00a0\u0915\u0947\u0930\u0932\u093e \u0938\u094d\u091f\u093e\u0907\u0932 \u090f\u0917 \u0930\u094b\u0938\u094d\u091f \u0915\u0930\u0940\u00a0\u0930\u0947\u0938\u093f\u092a\u0940 \u0915\u094b \u0924\u0935\u093e \u092a\u0930\u093e\u0920\u093e \u092f\u093e \u0905\u092a\u094d\u092a\u092e \u0915\u0947 \u0938\u093e\u0925 \u0938\u0941\u092c\u0939 \u0915\u0947 \u0928\u093e\u0936\u094d\u0924\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964 \u0906\u092a \u0907\u0938 \u0915\u0930\u0940 \u0915\u094b \u091a\u093e\u0935\u0932 \u0914\u0930 \u0938\u0932\u093e\u0926 \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092d\u0940 \u092a\u0930\u094b\u0938 \u0938\u0915\u0924\u0947 \u0939\u0948."]'::jsonb, 60, 'Kerala', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/kerela_style_egg_roast_curry_recipe_shutterstock_180151727.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1309.kerela_style_egg_roast_curry_recipe_shutterstock_180151727.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Methi Moong Dal Recipe - Healthy Diabetic Friendly Recipe', 'methi-moong-dal-recipe-healthy-diabetic-friendly-recipe', 'The Methi Moong Dal Recipe is a delicious dal that is packed with taste and nutrition from methi and moong dal. It is very simple to make which you can serve along with phulka and achari pickle by the side to make it a complete meal.', '["1 cup Methi Leaves (Fenugreek Leaves) , finely chopped", "1/2 cup Yellow Moong Dal (Split)", "1 tablespoon Ghee", "4 cloves Garlic , finely chopped", "1/2 Cumin seeds (Jeera)", "1/4 tablespoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "Salt , to taste", "1 tablespoon Lemon juice", "1 teaspoon Sugar , optional"]'::jsonb, ARRAY['salt', 'yellow moong dal (split)', 'ghee', 'methi leaves (fenugreek leaves)', 'red chilli powder', 'cloves garlic', 'sugar', 'cumin seeds (jeera)', 'lemon', 'turmeric powder']::text[], '["To begin making the Methi Moong Dal Recipe,\u00a0Pressure cook the moong dal along with salt, turmeric powder, 1 cup of water for 3 to 4 whistles and turn off the heat.", "Allow the pressure to release naturally.", "Wash chopped fenugreek leaves, drain and keep aside.Heat oil in a pan over medium flame.", "Add minced garlic and let them turn into golden brown.", "After that add cumin seed and saut\u00e9 them pop.Now add methi leaves and saute for about a minute and the leaves will wilt down.", "Stir in the cooked moong dal, salt and sugar and add a little water to adjust the consistency of the Methi Moong dal.", "Check salt and spices and give it a brisk boil.", "Heat ghee in a pan; add the cumin seeds and red chilli powder.", "Pour this tadka over the\u00a0Methi Moong Dal Recipe and stir.", "Transfer the\u00a0Methi Moong Dal Recipe to a serving bowl and serve hot.Serve\u00a0Methi Moong Dal Recipe\u00a0along with\u00a0Khooba Roti\u00a0and\u00a0Tomato Onion Cucumber Raita\u00a0for a weekday meal."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/April-09/Methi_Masala_Curry_Recipe-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1310.Methi_Masala_Curry_Recipe-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Chickpeas Aloo Salad Chaat Recipe', 'spicy-chickpeas-aloo-salad-chaat-recipe', 'Spicy Chickpeas Aloo Salad Chaat Recipe is a delicious and chatpata salad recipe that addresses nutrition as well as delightfully good for taste buds too. The tangy taste that is imparted due to lemon dressing is delectable and appetizing.', '["1 Cup Kabuli Chana (White Chickpeas) , soaked overnight", "1 Onion , finely chopped", "1 Tomato , finely chopped", "1 Green Chilli , finely chopped", "1 Potato (Aloo) , boiled & cubed", "50 gram Coriander (Dhania) Leaves , finely chopped", "1/2 teaspoon Black Salt (Kala Namak)", "1/4 teaspoon Black pepper powder", "1/2 teaspoon Chaat Masala Powder", "2 teaspoon Lemon juice", "1/2 teaspoon Chaat Masala Powder", "2 teaspoon Lemon juice"]'::jsonb, ARRAY['tomato', 'black salt', 'green chilli', 'potato (aloo)', 'chaat masala powder', 'kabuli chana (white chickpeas)', 'onion', 'lemon', 'black pepper powder', 'gram coriander (dhania) leaves']::text[], '["To prepare Spicy Chickpeas Aloo Salad Chaat Recipe, we need soak the chickpeas overnight and keep it ready.", "In a pressure cooker, add the chana and water and pressure cook for 6 whistles on medium flame, reduce the flame and continue to cook for 15 more minutes.", "Turn off the flame.", "Allow the pressure to release naturally, drain the water and transfer the chana into a bowl and set aside.", "In the same pressure cooker boil the Aloo for at least 3 whistle, once doen peel the skin off and cut them into cubes.", "In a mixing bowl, combine the kala chana, onion, tomato, green chilli, aloo, black salt, pepper powder, chaat masala and lemon juice.", "Garnish it with fresh coriander leaves and serve immediately.Serve\u00a0Spicy Chickpeas Aloo Salad Chaat Recipe\u00a0with\u00a0Indian Style Beetroot Soup Recipe\u00a0and\u00a0Masala Cheese Bread Loaf Recipe With Garam Masala & Herbs\u00a0for a hearty dinner.You can also serve this salad recipe with\u00a0Masala Chai Recipe - Indian Spiced Tea\u00a0or a\u00a0Carrot Amla Pomegranate Juice Recipe\u00a0during evening."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/April-18/Kabuli_Chana_Aloo_Salad_Recipe_Potato_Chickpea_Salad-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1311.Kabuli_Chana_Aloo_Salad_Recipe_Potato_Chickpea_Salad-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Satvik Carrot Sprouts Salad Recipe - No Onion No Garlic', 'satvik-carrot-sprouts-salad-recipe-no-onion-no-garlic', 'This Satvik Carrot Sprouts Salad Recipe is a No Onion No Garlic salad which is made from freshly grated carrots and sprouts, with a hint of lemon. This recipe can be made with simple and ingredients easily available in your kitchen.', '["4 Carrots (Gajjar) , finely grated", "1/2 cup Green Moong Sprouts", "1/4 cup Green Bell Pepper (Capsicum) , finely chopped", "1/4 cup Fresh coconut , freshly grated", "1/4 cup Raw Peanuts (Moongphali) , soaked in water for 3-4 hours", "1-1/2 tablespoon Lemon juice", "Black pepper powder , to taste", "Salt , to taste", "Salt , to taste"]'::jsonb, ARRAY['salt', 'coconut', 'green moong sprouts', 'carrot', 'lemon', 'peanuts (moongphali)', 'black pepper powder', 'green bell pepper (capsicum)']::text[], '["To begin making the Satvik Carrot Sprouts Salad recipe, grate the carrots and keep it ready.", "In a mixing bowl, add all the ingredients- carrot, green moong sprouts, capsicum, coconut, peanuts, lime juice and season it with salt and pepper.Mix the\u00a0Carrot Sprouts Salad well and serve fresh.Serve\u00a0Satvik Carrot Sprouts Salad as a side dish along with\u00a0Panchmel Dal,\u00a0Bhindi Masala\u00a0and\u00a0Phulkas."]'::jsonb, 15, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/April-18/Sattvik_Carrot_Sprouts_Salad_recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1312.Sattvik_Carrot_Sprouts_Salad_recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Homemade Doodh Peda Recipe - Milk Peda', 'homemade-doodh-peda-recipe-milk-peda', 'Doodh Peda is an easy Indian sweet recipe made with condensed milk and milk powder and flavored with cardamom and pistachios. The traditional recipe requires you to condense the milk at home, but this recipe of Doodh Peda makes the process easier by using the ready condensed milk.', '["1-1/2 cups Milk Powder", "400 grams Condensed Milk", "1/2 teaspoon Cardamom Powder (Elaichi)", "1/4 cup Butter (Salted) , or ghee melted", "Pistachios , a few, sliced"]'::jsonb, ARRAY['s milk powder', 's condensed milk', 'cardamom powder', 'elaichi', 'butter', 'salted', 'pistachios']::text[], '["To begin making the Homemade Doodh Peda Recipe, in a wide non stick pan, combine the condensed milk and milk powder and mix it into a smooth paste without any lumps.", "Add in the cardamom powder, ghee or butter into the mixture and stir to combine well.Place the pan on medium heat and stir continuously until it becomes a thick batter.", "Turn off the heat as soon as the mixture thickens and you see it leaving the sides of the pan.Be careful, as the mixture will thicken up quickly.", "The mixture will thicken further when it is cooling down.Once it becomes thick and leaves the sides of the pan turn off the heat and transfer the peda dough to another bowl and allow it to cool to a temperature such that you can use your hands to knead them.Once cooled, knead the peda dough until smooth and fluffy.You can add a little ghee to knead if the peda dough.", "Divide the dough into small lemon sized balls.", "Make an impression with the thumb in the center and place a piece of pistachio in the center and serve.Serve the delicious Doodh Pedas as a snack or make them during festivals like Diwali or\u00a0as a dessert after a festive meal like\u00a0Vegetable Oatmeal Poha with Peanuts, Coriander & Ginger Recipe."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Dhood_Peda_Recipe_shutterstock_219336592.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1313.Dhood_Peda_Recipe_shutterstock_219336592.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Andhra Style Vankaya Kothimeera Karam Recipe - Brinjal Cooked With Spicy Coriander Mix Recipe', 'andhra-style-vankaya-kothimeera-karam-recipe-brinjal-cooked-with-spicy-coriander-mix-recipe', 'Vankaya Kothimeera Karam recipe is a classic Andhra style brinjal cooked in a very aromatic spicy coriander masala.', '["400 grams Brinjal (Baingan / Eggplant) , cut into long strips", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "2 Dry Red Chillies", "1 tablespoon Oil", "Salt , to taste", "Ingredients to make the coriander masala", "Coriander (Dhania) Leaves , as required and roughly chopped", "2 Green Chillies", "2 inch Ginger , roughly chopped", "1/2 teaspoon Cumin seeds (Jeera)"]'::jsonb, ARRAY['salt', 'ginger', 'mustard seeds', 'brinjal (baingan eggsplant)', 'coriander (dhania) leaves', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'cumin seeds (jeera)', 'green chillies', 'sunflower oil']::text[], '["To begin making the Vankaya Kothimeera Karam recipe, wash and cut the brinjals in long strips and keep it immersed in salt water.", "This helps in avoiding the brinjals to turn black.Now, add all the ingredients mentioned in the coriander masala table into a blender and make a smooth paste and keep aside.Heat oil in a heavy bottomed pan on medium flame, add the mustard seeds, urad dal and let it splutter.Add the dried red chillies and curry leaves and let it crackle.Now, add the slit brinjals and saut\u00e9 until it wilts a little.Cook the brinjal until it is half done.", "This will take 10 minutes.Now, add the spicy coriander masala mix to the brinjals, season with salt, toss well, and let it simmer for 10 minutes.Once the brinjals are well cooked, turn off the heat.", "Transfer Vankaya Kothimeera Karam into a serving bowl and serve hot.", "Serve Vankaya Kothimeera Karam along with\u00a0Tomato Onion Sambar\u00a0and steamed rice with a dollop of ghee doe a weeknight dinner."]'::jsonb, 30, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/25-jan/Vankaya_Kothimeera_Karam_Recipe_Andhra_Style_Brinjals_Cooked_With_Spicy_Coriander_Mix-5.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1314.Vankaya_Kothimeera_Karam_Recipe_Andhra_Style_Brinjals_Cooked_With_Spicy_Coriander_Mix-5.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('आंध्रा स्टाइल वांकाया कोथिमीरा करम रेसिपी - Andhra Style Vankaya Kothimeera Karam Recipe', 'andhra-style-vankaya-kothimeera-karam-recipe', 'आंध्रा स्टाइल वांकाया कोथिमीरा करम रेसिपी एक आंध्रा स्टाइल बैंगन की सब्ज़ी है जिसमे धनिया मसाला का प्रयोग किया जाता है. वो एक फ़्लवेरफुल सब्ज़ी है जिसे आप रसम चावल या पराठे के साथ परोस सकते है.', '["400 \u0917\u094d\u0930\u093e\u092e\u094d\u0938 \u092c\u0948\u0902\u0917\u0928 , \u092a\u0924\u0932\u093e \u0914\u0930 \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0930\u093e\u0907", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0938\u095e\u0947\u0926 \u0909\u0930\u0926 \u0926\u093e\u0932", "1 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "2 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "1 \u092c\u095c\u093e \u091a\u092e\u091a\u094d\u091a \u0924\u0947\u0932", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0927\u0928\u093f\u092f\u093e \u092e\u0938\u093e\u0932\u093e \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f", "\u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930, \u0915\u093e\u091f \u0932\u0947", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a", "2 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u0915\u093e\u091f \u0932\u0947", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u091c\u0940\u0930\u093e"]'::jsonb, ARRAY['ग्राम्स बैंगन', 'छोटा चमच्च राइ', 'छोटा चमच्च सफ़ेद उरद दाल', 'टहनी कढ़ी पत्ता', 'सुखी लाल मिर्च', 'बड़ा चमच्च तेल', 'नमक', 'धनिया मसाला बनाने के लिए', 'हरा धनिया', 'हरी मिर्च', 'इंच अदरक', 'छोटा चमच्च जीरा']::text[], '["\u0906\u0902\u0927\u094d\u0930\u093e \u0938\u094d\u091f\u093e\u0907\u0932 \u0935\u093e\u0902\u0915\u093e\u092f\u093e \u0915\u094b\u0925\u093f\u092e\u0940\u0930\u093e \u0915\u0930\u092e \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u092c\u0948\u0902\u0917\u0928 \u0915\u094b \u0927\u094b \u0915\u0930 \u0915\u093e\u091f \u0932\u0947. \u0907\u0938\u0947 \u0928\u092e\u0915 \u0935\u093e\u0932\u0947 \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u092d\u093f\u0917\u094b \u0926\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0905\u0926\u0930\u0915, \u091c\u0940\u0930\u093e \u0921\u093e\u0932\u0947, \u092a\u0940\u0938 \u0932\u0947 \u0914\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u0909\u0930\u0926 \u0926\u093e\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947. \u0924\u095c\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 10 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092c\u0948\u0902\u0917\u0928 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0906\u0927\u093e \u092a\u0915 \u091c\u093e\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 8 \u0938\u0947 10 \u092e\u093f\u0928\u091f \u0932\u0917 \u0938\u0915\u0924\u0947 \u0939\u0948.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u093f\u0938\u093e \u0939\u0941\u0906 \u0927\u0928\u093f\u092f\u093e \u092e\u0938\u093e\u0932\u093e, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 10 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u092a\u0915 \u091c\u093e\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0906\u0902\u0927\u094d\u0930\u093e \u0938\u094d\u091f\u093e\u0907\u0932 \u0935\u093e\u0902\u0915\u093e\u092f\u093e \u0915\u094b\u0925\u093f\u092e\u0940\u0930\u093e \u0915\u0930\u092e\u00a0\u0915\u094b \u091c\u0940\u0930\u093e \u0930\u0938\u092e, \u091a\u093e\u0935\u0932 \u0914\u0930 \u092a\u093e\u092a\u095c \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 30, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/25-jan/Vankaya_Kothimeera_Karam_Recipe_Andhra_Style_Brinjals_Cooked_With_Spicy_Coriander_Mix-5.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1315.Vankaya_Kothimeera_Karam_Recipe_Andhra_Style_Brinjals_Cooked_With_Spicy_Coriander_Mix-5.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thandai Flavoured Rice Kheer Recipe', 'thandai-flavoured-rice-kheer-recipe', 'Rice Kheer is an Indian desert which is made from rice, milk and sugar flavoured with cardamom powder and saffron. You can even use rose water or kewra water in this recipe.', '["1-1/2 cup Thandai Powder", "Saffron strands , few", "2 tablespoons Basmati rice", "2 liter Milk", "Sugar , as required", "4 tablespoons Condensed Milk", "1 tablespoon Whole Almonds (Badam) , chopped", "1 tablespoon Pistachios , chopped", "1 tablespoon Cashew nuts , chopped", "Rose Petals , for garnishing", "1 teaspoon Cardamom Powder (Elaichi)", "Mixed nuts , for garnishing, chopped", "4 tablespoons Milk", "Ingredients for Thandai Powder", "1 tablespoon Whole Almonds (Badam) , blanched and peeled", "1 tablespoon Cashew nuts", "1 tablespoon Pistachios", "1 teaspoon Poppy seeds", "1 teaspoon Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "1/2 teaspoon Whole Black Peppercorns"]'::jsonb, ARRAY['thandai powder', 'basmati rice', 'cashew nuts', 'pistachios', 'cardamom (elaichi) podsseeds', 'saffron strands', 'milk', 'black peppercorns', 'sugar', 'badam (almond)', 'poppy seeds', 'cardamom powder (elaichi)', 'cinnamon stick (dalchini)', 'condensed milk', 'rose', 'mixed nuts']::text[], '["To begin with Thandai Flavored Rice Kheer, wash and soak the rice for 30 minutes.", "After 30 minutes, drain the water and keep the rice aside.Soak the saffron and thandai powder separately in lukewarm milk.", "Powder the Thandai Powder ingredients\u00a0- Almonds, Cashew nuts, Pistachios, poppy seeds, cardamom, cinnamon and whole black peppercorns into a coarse powder and keep aside.The next step is to boil the milk.", "When it comes to a boil, reduce the flame and add the rice in the saucepan.Keep stirring the kheer until it reduces to one-third of the original quantity.", "Once done, add sugar, milk-made, cardamom powder, chopped nuts, thandai milk and saffron.", "Mix everything well and cook the Thandai Kheer for 5 minutes more.After 5 minutes, turn off the flame and garnish it with chopped nuts and rose petals.Serve\u00a0Thandai Flavored Rice Kheer\u00a0as a dessert after your delicious meal of\u00a0Dal Makhani,\u00a0Sev Tamatar Ki Sabzi,\u00a0Phulka\u00a0and\u00a0Palak Raita."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Thandai_Flavored_Rice_Kheer_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1316.Thandai_Flavored_Rice_Kheer_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sing Paak Recipe - Spiced Peanut Burfi', 'sing-paak-recipe-spiced-peanut-burfi', 'Sing Paak or Peanut Burfi is a delectable Gujarati sweet that is quick and easy to put together and has a subtle flavour. ‘Singha’ is the name for peanuts in Gujarat, and the Sing Paak Barfi is a nutritious twist to the normal barfi.', '["250 grams Roasted Peanuts (Moongphali) , powdered", "150 grams Sugar", "10 Saffron strands", "1 cup Water", "1 tablespoon Ghee", "1/2 cup Pistachios"]'::jsonb, ARRAY['s roasted peanuts', 'moongphali', 's sugar', 'saffron strands', 'water', 'ghee', 'pistachios']::text[], '["To begin making the Sing Paak Recipe (Spiced Peanut Fudge), we will start by heating the sugar and water in a small pan over medium, till the sugar melts completely and the syrup becomes stringy of two thread consistency.Once the sugar has reached a string like consistency, add the saffron to it and stir.", "To this mixture\u00a0add in the powdered peanuts and mix them together until well combined while still on the heat.", "Once well combined, turn off the gas and then stir in the ghee, followed by the dry fruits.", "Keep stirring until the peanut burfi mixture comes away from the sides of the pan.", "Turn off the heat.Spread the mixture evenly on a large tray greased with ghee.", "Try to get a tray that has a rim and and just right enough to fit the burfi mixture.", "Allow the peanut burfi to rest in the tray and cool completely.", "It takes a good 5 to 6 hours to cool and firm.", "Once firm, cut it into small square or diamond pieces.Serve this delicious Sing Paak or the Peanut Burfi as an after-dinner dessert or during the festivals like Diwali and Holi\u00a0or as a snack with\u00a0Banana And Mango Smoothie Recipe\u00a0or along with\u00a0Baked Chevdo Recipe (Chivda Mixture -Tea Time Snack)."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Sing_Paak_Recipe_Spiced_Peanut_Burfi_Diwali_indian_Sweets_Archanas_Kitchen-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1317.Sing_Paak_Recipe_Spiced_Peanut_Burfi_Diwali_indian_Sweets_Archanas_Kitchen-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gluten Free Rajgira Burfi Recipe', 'gluten-free-rajgira-burfi-recipe', 'Diwali is just around the corner! I''m sure most of you have planned family get togethers, festive lunches and dinners. Festivals are such a wonderful time for family to get together and spend some quality time. But this barfi is a healthy one!', '["1/2 cup Rajgira Flour (Amaranth Flour)", "1/2 cup Jaggery", "1/2 cup Ghee , melted", "1/2 teaspoon Cardamom Powder (Elaichi)", "1/4 cup Cashew nuts , halved"]'::jsonb, ARRAY['rajgira flour', 'amaranth flour', 'jaggery', 'ghee', 'cardamom powder', 'elaichi', 'cashew nuts']::text[], '["To begin making the Gluten Free Rajgira Burfi Recipe, dry roast the rajgira/amaranth flour in a heavy bottomed pan till the color changes to a light golden brown.", "Remove from the flame and set aside.Grease a flat plate with ghee and keep aside.Roast the halved cashewnuts in a little ghee until crisp and golden brown.", "Take care to do it on low heat to roast it evenly.Next combine the jaggery and 1/4 cup water in a heavy bottomed pan and place over low heat. (the amount of water should be just enough to soak the jaggery or sugar).", "Make a syrup of half thread consistency.To the jaggery syrup, add the roasted flour and powdered cardamom and mix well.Keep stirring continuously.", "Add the melted ghee little at a time while stirring the mixture. (if you find that the mixture is sticking to the pan, add more ghee than mentioned in the recipe)When the Rajgira Burfi \u00a0mixture starts leaving the sides and bottom of the pan, turn off the heat.", "Pour this mixture immediately on to the greased tray and spread it evenly for it to set.Sprinkle the roasted cashewnuts on top and press gently while the\u00a0Rajgira Burfi mixture is still hot.Allow the\u00a0Rajgira Burfi to cool and then cut into desired sizes and shapes.", "Store the\u00a0Rajgira Burfi in an airtight box for a week.Serve Gluten-Free Rajgira Burfi for Diwali, Raksha Bandhan or any other special occasion in the family.", "Serve\u00a0Gluten Free Rajgira Burfi Recipe\u00a0after your everyday meal of\u00a0Palak Dal,\u00a0Bharwa Bhindi,\u00a0Phulka\u00a0and\u00a0Lauki Raita."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Gluten_Free_Rajgira_Burfi_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1318.Gluten_Free_Rajgira_Burfi_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dry Fruit Burfi Recipe With Gulkand', 'dry-fruit-burfi-recipe-with-gulkand', 'The Dry Fruit Burfi Recipe With Gulkand is a super healthy and delicious sweet that you must make either for a quick energy booster or for festivals. This recipe has a slight twist to it with the addition of Gulkand. Gulkand is a flavored jam made from rose petals and when added to sweets like this Dry fruit Burfi, brings out great flavors and taste.', '["1 1/2 cups Dried Figs , chopped", "1 cup Dates , chopped", "1/3 cup Whole Almonds (Badam)", "1/3 cup Cashew nuts", "1/3 cup Walnuts", "1/3 cup Pistachios", "1/3 cup Sultana Raisins", "2 tablespoons Gulkand", "1/4 teaspoon Nutmeg powder", "1 tablespoon Ghee", "1 Edible Silver Foil/Leaf (Chandi Ka Vark) , optional"]'::jsonb, ARRAY['cashew nuts', 'nutmeg powder', 'pistachios', 'ghee', 'dried figs', 'raisins', 'gulkand', 'badam (almond)', 'edible silver foilleaf (chandi ka vark)', 'dates', 'walnuts']::text[], '["To begin making the Dry Fruit Burfi With Gulkand Recipe, soak the chopped anjeer/dried figs in warm water for 15 minutes, strain water and pat dry well.", "Grind anjeer/figs along with the dates and raisins to smooth paste without adding any water.", "Keep it aside.Meanwhile finely chop almonds, cashewnuts, walnut and pista.", "You can also use a food processor or a mini chopped to fasten the process.Heat oil or ghee in a heavy bottomed pan, add anjeer dates paste mix well and saute for a minute.Next add chopped date and nut mixture, nutmeg powder, gulkand mixture and stir to combine well.Cook for a couple of minutes until you notice the burfi mixture coming away from the sides of the pan.", "Once you notice the burfi mixture comes away from the sides of the pan turn off the heat.", "Grease a tray with ghee and pour burfi mixture into the tray.", "Level it well with a spatula and allow mixture to cook completely and set itself into a firm burfi.Optionally add the silver varq if you are using and keep burfi in refrigerator for 20 to 30 minutes.", "Cut the Dry Fruit Burfi into desired shapes.Serve\u00a0Dry Fruit Burfi With Gulkand\u00a0as a festival dessert along with\u00a0Jalebi\u00a0and\u00a0Samosas\u00a0to your guests when they come to visit you."]'::jsonb, 70, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Dry_Fruit_Burfi_The_Hub_Video_Diwali_Festival_Recipes_Dates_Fig_Nuts-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1319.Dry_Fruit_Burfi_The_Hub_Video_Diwali_Festival_Recipes_Dates_Fig_Nuts-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Konkani Style Mande/Mandige/Chavde Recipe-Thin fried pancakes stuffed with sweet coconut Recipe', 'konkani-style-mande-mandige-chavde-recipe-thin-fried-pancakes-stuffed-with-sweet-coconut-recipe', 'Chavde also known as Mande or Mandige is traditional Maharashtrian and Konkani specially that is made from fried bread made from flour that is stuffed with a delicious blend of grated and roasted coconut, cardamom powder, sugar and sesame seeds. The Chavde is also a popular sweet that is made for Ganesh Chaturthi festival.', '["Ingredients for the Fried Bread (Puri)", "250 grams All Purpose Flour (Maida)", "2 tablespoon Ghee , melted", "Salt , to taste", "Milk , or water to make dough", "Ingredients for stuffing", "1 Dessicated Coconut , or copra peeled and finely grated", "Caster Sugar , according to your taste", "2 tablespoon Sesame seeds (Til seeds) , roasted", "2 teaspoons Cardamom Powder (Elaichi)", "Oil , for deep frying"]'::jsonb, ARRAY['ingredients for the fried bread', 'puri', 's all purpose flour', 'maida', 'ghee', 'salt', 'milk', 'ingredients for stuffing', 'dessicated coconut', 'caster sugar', 'sesame seeds', 'til seeds', 's cardamom powder', 'elaichi', 'oil']::text[], '["To begin making the Konkani Style Mange or Mandige\u00a0 or Chavde."]'::jsonb, 45, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/17-april/Mande_Mandige_Chavde_Recipe-_A_Delicious_Konkani_Sweet-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1320.Mande_Mandige_Chavde_Recipe-_A_Delicious_Konkani_Sweet-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Tamil Nadu Style Arachuvitta Rasam Recipe', 'tamil-nadu-style-arachuvitta-rasam-recipe', 'Arachuvitta Rasam Recipe, is an aromatic and flavourful recipe. It is also known as the Kalyana Rasam, prepared during the weddings with the freshly available ingredients. It is prepared with the freshly ground rasam spice mix, which makes all the difference.', '["20 grams Tamarind , soaked in warm water", "1 Tomato , finely chopped", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Whole Black Peppercorns", "1 Green Chilli , slit", "1 sprig Curry leaves", "2 sprig Coriander (Dhania) Leaves , roughly torn for garnish", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "Asafoetida (hing) , A pinch", "1 teaspoon Ghee", "Salt , to taste", "To be ground to a fine paste", "2-3 teaspoons Arhar dal (Split Toor Dal)", "1 teaspoon Cumin seeds (Jeera)", "1 Dry Red Chilli"]'::jsonb, ARRAY['s tamarind', 'tomato', 'turmeric powder', 'haldi', 'cumin seeds', 'jeera', 'whole black peppercorns', 'reen chilli', 'curry leaves', 'coriander', 'dhania', 'mustard seeds', 'rai/ kadugu', 'asafoetida', 'hing', 'ghee', 'salt', 'to be ground to a fine paste', 's arhar dal', 'split toor dal', 'dry red chilli']::text[], '["To begin making Arachuvitta Rasam Recipe, soak the lemon sized tamarind in warm water for 10 minutes and squeeze out the tamarind pulp.", "Keep this extract aside.Also, soak the toor dal for 30 minutes and grind it along with the cumin seeds and red chilli to a fine paste using a hand mixer.Now, take a wok/kadai add the tamarind extract, chopped tomatoes, slit green chilli and turmeric powder, enough water and boil until the tomatoes are well cooked and the raw smell of the tamarind goes away.Add the ground toor dal mix, season with salt and simmer for another 10 minutes.If the mixture becomes too thick, add water at this stage to your desired consistency and let the mix comes to a rolling boil.", "Switch off the flame.Heat ghee in a small tadka pan, add the mustard seeds and let it crackle.Roughly hand pound the cumin and pepper corns using a mortar and pestle and add it to the tadka along with the curry leaves and asafoetida.Once the curry leaves crackle, switch off the flame and transfer this tadka to the pan in which you have cooked the rasam.Garnish with roughly torn coriander leaves and serve the Arachuvitta Rasam Recipe with steamed rice and beans carrot poriyal for a weeknight dinner.Serve the Arachuvitta Rasam Recipe along with Steamed rice and\u00a0Carrot Poriyal\u00a0accompanied by\u00a0Medu Vada Recipe in Sambar (Non Fried Fritters in Tangy Lentil Curry)\u00a0for a delicious simple weeknight dinner."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/4-april/Tamil_Nadu_pepper_rasam_Ground_Pepper_Rasam_Recipe-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1321.Tamil_Nadu_pepper_rasam_Ground_Pepper_Rasam_Recipe-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lemon Rasam Recipe - Nimbe Saaru Recipe', 'lemon-rasam-recipe-nimbe-saaru-recipe', 'The Lemon Rasam Recipe, is a delicious spicy and tangy rasam that is made very simple using dal and tomatoes and flavored with ginger, green chillies and lemon.', '["1/4 cup Arhar dal (Split Toor Dal) , boiled", "2 Tomatoes , roughly chopped", "1 Green Chilli , slit", "1 inch Ginger , roughly chopped", "1 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Turmeric powder (Haldi) , roughly pounded", "1 teaspoon Coriander Powder (Dhania) , roughly pounded", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Black pepper powder", "Coriander (Dhania) Leaves , few sprigs, roughly chopped", "Salt , to taste", "1 Lemon , juice extracted", "Ingredients for Seasoning", "1 tablespoon Ghee , or sesame oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves", "1/4 teaspoon Asafoetida (hing)"]'::jsonb, ARRAY['arhar dal', 'split toor dal', 'tomatoes', 'reen chilli', 'ginger', 'turmeric powder', 'haldi', 'coriander powder', 'dhania', 'cumin powder', 'jeera', 'black pepper powder', 'coriander', 'salt', 'lemon', 'ingredients for seasoning', 'ghee', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'curry leaves', 'asafoetida', 'hing']::text[], '["To begin making Lemon Recipe - Nimbe Saaru, first pressure cook\u00a0toor dal along with turmeric and 2 cups of water for 3 whistles or until cooked.", "Allow the pressure to release naturally.Once the dal is cooked, whisk it well until dal is smooth and keep aside.Into a pressure cooker, add the\u00a0chopped tomatoes, slit green chilli, ginger, coriander powder, cumin powder, turmeric powder, black pepper powder, salt, 2 cups of water and pressure cook for 1 whistle and turn off the heat.", "Allow the pressure to release naturally.Add the cooked dal, to the cooked tomato rasam, squeeze the lemon juice and stir in the coriander leaves.", "Check the salt and spices and adjust to taste.In a tadka pan over medium heat, add 1 tablespoon ghee.", "Once the oil is heated up, add the mustard seeds, cumin seeds and allow it to crackle.", "Add the asafoetida powder and curry leaves, stir it in and turn off the heat.Pour this tempering over the cooked Lemon Rasam and bring the rasam to a brisk boil.", "Boil for 2 to 3 minutes until you see the rasam frothing on the top.Adjust the consistency of the Lemon Rasam, by adding extra water if required.", "Check the salt and spices and lemon taste and adjust accordingly.Once done, turn off the heat, transfer the Lemon Rasam to a serving bowl and serve hot.Serve the Lemon Rasam along with hot steamed rice and a poriyal like\u00a0Carrot and Beans Poriyal, Potato Roast and Beetroot Curry/Poriyal to make a sumptuous weeknight dinner or lunch."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Lemon_Rasam_Recipe_Yelumcha_Rasam_Saaru-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1322.Lemon_Rasam_Recipe_Yelumcha_Rasam_Saaru-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('North Karnataka Style Nuggekai Kharbyaali Recipe-Spiced Drumstick Sambar', 'north-karnataka-style-nuggekai-kharbyaali-recipe-spiced-drumstick-sambar', 'North Karnataka Spiced Drumstick Sambar also known as Nuggekai Kharbyaali is a traditional sambar curry made with a special spice powder - bhakri/ jowar/phulkas.', '["1 cup Arhar dal (Split Toor Dal)", "1 cup Tamarind Water", "1 tablespoon Jaggery , (optional)", "2 Drumstick , cut into 2\u201d pieces, cooked", "1 Onion , roughly chopped", "3 cloves Garlic , roughly chopped", "2 tablespoons All spice powder , Kharbyaali Masala Khara Spice Powder", "1 tablespoon Oil", "Salt , to taste", "Ingredients for seasoning", "1 tablespoon Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon Asafoetida (hing)", "5 Curry leaves", "4 sprig Coriander (Dhania) Leaves , finely chopped for garnish"]'::jsonb, ARRAY['arhar dal', 'split toor dal', 'tamarind water', 'jaggery', 'drumstick', 'onion', 's garlic', 's all spice powder', 'oil', 'salt', 'ingredients for seasoning', 'mustard seeds', 'rai/ kadugu', 'cumin seeds', 'jeera', 'asafoetida', 'hing', 'curry leaves', 'coriander', 'dhania']::text[], '["To begin making the Nuggekai Kharbyaali recipe, firstly wash and soak dal in water for few minutes.", "Then cook dal and drumstick in the pressure cooker.", "Add 2 cups of water along with dal, drumstick, turmeric powder and salt and cook for 4 whistle.", "Allow the pressure to release naturally.", "Once dal is cooked, keep aside till required.Now heat a tablespoon of oil in a heavy bottomed pan over medium heat, add the chopped garlic and onion to the pan.", "Fry onion and garlic till they turn golden brown in color.Add in the\u00a0Kharbyaali\u00a0Masala\u00a0Khara Spice Powder,\u00a0the cooked lentils, jaggery, tamarind water and cooked drumsticks.", "Stir to combine and bring the sambar to the boil once.", "Turn the heat to low and continue to simmer the curry for few more minutes.Meanwhile sambar is simmering, heat a tablespoon of oil in a small pan; add the\u00a0mustard seeds, cumin seeds and allow them to crackle.", "Then add asafoetida and curry leaves, fry for few seconds then turn off the heat.", "Pour this seasoning over the simmering curry.", "Stir to combine.", "Turn off the heat and transfer the sambar to a bowl for serving.", "Garnish with chopped coriander leaves.", "Serve\u00a0Nuggekai Kharbyaali along with\u00a0Steamed Rice\u00a0and\u00a0Murungai Keerai Poriyal\u00a0for a weekday meal."]'::jsonb, 40, 'North Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Nuggekai_Kharbyaali_North_Karnataka_Spiced_Drumstick_Sambar_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1323.Nuggekai_Kharbyaali_North_Karnataka_Spiced_Drumstick_Sambar_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Coriander Tadka Raita Recipe', 'coriander-tadka-raita-recipe', 'Coriander Tadka Raita is a refreshing raita made with fresh coriander leaves and smooth yogurt, with a lovely jeera-garlic tadka for added flavour.', '["1 cup Curd (Dahi / Yogurt) , whisked", "1/4 cup Water", "2 tablespoons Coriander (Dhania) Leaves , finely chopped", "1 Green Chilli , finely chopped", "1/4 teaspoon Oil", "1/2 teaspoon Cumin seeds (Jeera)", "pinch Mint Leaves (Pudina) , crushed", "2 cloves Garlic , finely chopped", "Salt , to taste", "1/2 teaspoon Cumin powder (Jeera)"]'::jsonb, ARRAY['curd', 'dahi / yogurt', 'water', 's coriander', 'dhania', 'reen chilli', 'oil', 'cumin seeds', 'jeera', 'pinch mint leaves', 'pudina', 's garlic', 'salt', 'cumin powder']::text[], '["To begin making the Coriander Tadka Raita, in a bowl combine the water and curd and whisk well.", "To the bowl, add the coriander leaves, mint leaves, green chillies, salt, cumin powder and mix everything well.", "Heat oil in a tadka pan\u00a0on medium flame,\u00a0add the cumin seeds and garlic and fry until it turns into a lovely brown colour.", "Turn off the flame.", "Add this tadka into the curd and serve.Serve\u00a0Coriander Tadka Raita\u00a0along with\u00a0Chettinad Vegetable Biryani Recipe\u00a0and\u00a0Mirchi Bajji Recipe\u00a0for a simple weekday meal."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Sweet_and_Spicy_Coriander_Raita_Recipe-6.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1324.Sweet_and_Spicy_Coriander_Raita_Recipe-6.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Homemade Lemon Sevai Recipe - Lemon Idiyappam Recipe', 'homemade-lemon-sevai-recipe-lemon-idiyappam-recipe', 'The Homemade Lemon Sevai Recipe, is a traditional south indian recipe that is made from from freshly ground rice using a traditional sevai maker.', '["2 cups Idli Rice", "Lemon juice , from 2 lemons", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1/4 cup Roasted Peanuts (Moongphali)", "2 Green Chillies , finely chopped", "2 sprig Curry leaves", "2 inch Ginger , finely chopped", "2 tablespoons Sesame (Gingelly) Oil"]'::jsonb, ARRAY['ginger', 'mustard seeds', 'idli rice', 'sesame (gingelly) oil', 'curry leaves', 'white urad dal (split)', 'lemon', 'peanuts (moongphali)', 'turmeric powder', 'green chillies']::text[], '["To begin making Lemon Sevai/ Idiyappam Recipe, first wash and soak the rice in water, such that the rice is completely immersed in water.Let it soak for about 2 hours.", "Transfer to a mixer and grind to get a smooth paste.", "It must be of semi-thick pouring consistency and not of a liquid consistency.The next step is to make the steamed dumplings/ idli and then the make the idiyappam / sevai in the sevai maker.Place the sevai/ idiyappam batter in greased idli molds and steam for 10 minutes.", "Once the rice idlis are steamed we will make the sevai.The batter will begin to leave the sides of the pan and will form a thick shiny big ball of dough.", "This process will take about 15 to 20 minutes.The next step is the press the hot idlis in the sevai/ idiyappam maker or the sevai maker or a press, also called as\u00a0sevai nazhi.This is the most crucial stage.", "The idlis should be hot when you press to make the noodles.", "If it turns cold you will not be able to press the dumplings to get the noodles.Proceed to hot press one at a time by turns the wheels of the sevai nazhi to get the uber soft noodles.Continue till you are done with all the sevai idli.", "Transfer the sevai to a large bowl as and when you finish.", "You sevai is now ready to be flavoured or eaten.The final step is to make the Lemon Sevai Recipe.Heat a kadai and add the oil.", "Add the mustard and allow it to crackle.", "Add the green chillies, ginger, peanuts, curry leaves and saute for a few seconds.Now add the turmeric powder and the steamed rice sevai/idiyappam and give the Lemon Sevai a quick stir.", "Now add the lemon juice and stir until combined well.Check the salt and spice levels and adjust to suit your taste for the Lemon Sevai/ Idiyappam.Serve the Lemon Sevai for breakfast, a teatime snack or even for dinner along with Coconut Chutney or Mor Kuzhambu."]'::jsonb, 160, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breakfast_Tiffins/Homemade_Lemon_Yelumcha_Sevai_Recipe_Idiyappam_Ottu_Shavige-5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1325.Homemade_Lemon_Yelumcha_Sevai_Recipe_Idiyappam_Ottu_Shavige-5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('ऑरेंज रसम रेसिपी - Orange Rasam Recipe', 'orange-rasam-recipe-2', 'ऑरेंज रसम एक स्वादिष्ट रसम है जिसमे रसम बनाकर उसमे ऑरेंज(संतरे) का रस मिलाया जाता है. ऑरेंज को रसम में मिलाने से रसम में खट्टा मीठा स्वाद आता है. इस रेसिपी को बनाए और हमे जरूर बताए की यह आपको कैसी लगी?', '["1/2 \u0915\u092a \u0905\u0930\u0939\u0930 \u0926\u093e\u0932 , \u092a\u0915\u093e \u0932\u0947", "2 \u091f\u092e\u093e\u091f\u0930 , \u0915\u093e\u091f \u0932\u0947", "1/2 \u0915\u092a \u0938\u0902\u0924\u0930\u0947 \u0915\u093e \u0930\u0938 , (\u0911\u0930\u0947\u0902\u091c \u0915\u093e \u0930\u0938)", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0928\u093f\u092e\u094d\u092c\u0942 \u0915\u093e \u0930\u0938", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u0915\u093e\u091f \u0932\u0947, \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0939\u0940\u0902\u0917", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0911\u0930\u0947\u0902\u091c \u095b\u0947\u0938\u094d\u091f", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0918\u0940", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0930\u093e\u0907", "\u0930\u0938\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u092a\u0942\u0930\u0940 \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a", "2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u091c\u0940\u0930\u093e", "5 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "1 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "2 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0905\u0930\u0939\u0930 \u0926\u093e\u0932"]'::jsonb, ARRAY['कप अरहर दाल', 'टमाटर', 'कप संतरे का रस', 'छोटा चमच्च निम्बू का रस', 'छोटा चमच्च हल्दी पाउडर', 'नमक', 'हरा धनिया', 'छोटा चमच्च हींग', 'छोटा चमच्च ऑरेंज ज़ेस्ट', 'तड़के के लिए', 'छोटा चमच्च घी', 'छोटा चमच्च राइ', 'रसम मसाला पाउडर बनाने के लिए', 'छोटा चमच्च पूरी काली मिर्च', 'छोटा चमच्च जीरा', 'कढ़ी पत्ता', 'लाल मिर्च पाउडर', 'छोटा चमच्च अरहर दाल']::text[], '["\u0911\u0930\u0947\u0902\u091c \u0930\u0938\u092e \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0938\u0949\u0938\u092a\u0948\u0928 \u092e\u0947\u0902 2 \u0917\u093f\u0932\u093e\u0938 \u092a\u093e\u0928\u0940, \u091f\u092e\u093e\u091f\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0939\u0940\u0902\u0917, \u0928\u092e\u0915 \u0914\u0930 \u0911\u0930\u0947\u0902\u091c \u095b\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947\u0964 \u0917\u0948\u0938 \u091a\u093e\u0932\u0942 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0907\u0938 \u092e\u093f\u0936\u094d\u0930\u0923\u00a010 \u0938\u0947 15 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0909\u092c\u0932\u0928\u0947 \u0926\u0947. \u0930\u0938\u092e \u092a\u093e\u0909\u0921\u0930 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f\u00a0\u090f\u0915 \u0915\u095d\u093e\u0908 \u0915\u094b \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a, \u091c\u0940\u0930\u093e, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0905\u0930\u0939\u0930 \u0926\u093e\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u0938\u0947 2 \u092e\u093f\u0928\u091f\u00a0\u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u092a\u0940\u0938 \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a010 \u0938\u0947 15 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092a\u0915\u0940 \u0939\u0941\u0908 \u0924\u0941\u0905\u0930 \u0926\u093e\u0932 \u0921\u093e\u0932\u0947\u0964 \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u093f\u0938\u093e \u0939\u0941\u0906 \u0930\u0938\u092e \u092a\u093e\u0909\u0921\u0930 \u0915\u093e \u092e\u0938\u093e\u0932\u093e \u0921\u093e\u0932\u0947\u0964 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u092e\u093f\u0932\u093e\u090f \u0914\u0930 4 \u0938\u0947 5 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u0928\u0947 \u0926\u0947.\u00a04 \u0938\u0947 5 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926, \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0938\u0902\u0924\u0930\u0947 \u0915\u093e \u0930\u0938, \u0928\u093f\u092e\u094d\u092c\u0942 \u0915\u093e\u00a0\u0930\u0938 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u0905\u092c \u0939\u092e \u0907\u0938\u0915\u0947 \u0932\u093f\u090f \u0924\u095c\u0915\u093e \u092c\u0928\u093e\u090f\u0901\u0917\u0947\u0964 \u090f\u0915 \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947.\u00a0\u0907\u0938 \u0924\u095c\u0915\u0947 \u0915\u094b \u0930\u0938\u092e \u092e\u0947\u0902 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u0947 \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902\u0964\u00a0\u0911\u0930\u0947\u0902\u091c \u0930\u0938\u092e \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u091a\u093e\u0935\u0932,\u00a0\u092c\u0940\u091f\u0930\u0942\u091f \u0925\u094b\u0930\u0928\u00a0\u0914\u0930 \u092a\u093e\u092a\u095c \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 35, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Orange_Rasam_Recipe-7.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1326.Orange_Rasam_Recipe-7.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharashtrian Style Kala Chana Cooked In Koli Masala Recipe', 'maharashtrian-style-kala-chana-cooked-in-koli-masala-recipe', 'Maharashtra has varied cuisines associated with it, and Koli cuisine is one of them. Koli is the the fishermen community and are the inhabitants of Mumbai. Though seafood forms an integral part of their Cuisine, there are few interesting vegetarian recipes too. The secret lies in the freshly prepared koli masala, which is robust in flavours. Kala Chana Cooked in Koli Masala has a vibrant amalgamation of flavourful spices. It is simple yet quite delectable on the palate.', '["1-1/2 cup Kala Chana (Brown Chickpeas) , boiled", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves", "1 tablespoon Oil", "2 teaspoons Coriander (Dhania) Leaves , finely chopped for garnish", "Salt , to taste", "To dry roast and to be ground to a paste", "2 Onions , thinly sliced", "4 tablespoons Fresh coconut , grated", "1 teaspoon Cumin seeds (Jeera)", "3 sprig Coriander (Dhania) Leaves", "2 Green Chillies", "1 teaspoon Red Chilli powder", "1/2 teaspoon Garam masala powder", "1 teaspoon Koli masala", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoons Coriander Powder (Dhania)", "2 Kokum (Malabar Tamarind)"]'::jsonb, ARRAY['salt', 'koli masala', 'garam masala powder', 'coconut', 'kokum (malabar tamarind)', 'coriander (dhania) leaves', 'red chilli powder', 'curry leaves', 'coriander (dhania) leaves', 'onion', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'green chillies', 'kala chana (brown chickpeas)', 'sunflower oil']::text[], '["To begin making Kala Chana Cooked in Koli Masala, soak the kala chana overnight and pressure cook with 2 cups of water for 3 whistles and keep aside.Heat a pan and dry roast onions and grated coconut till it turns golden in colour.To this add rest of the ingredients listed in the masala table and dry roast for 5 minutes till the spices become fragrant.Once cool, grind the ingredients to a smooth paste using a mixer grinder adding a little water and keep aside.Heat oil in the same pan, add cumin seeds and let it crackle.Add the curry leaves and let it splutter.To this add the ground masala paste and saute for a few minutes until the oil separates.Add the boiled kala chana, season with salt and water to your desired consistency and simmer for 5 minutes.Once, the gravy thickens, switch off the flame and garnish with chopped coriander leaves.Serve the Kala Chana Cooked in Koli Masala with hot\u00a0Phulkas\u00a0or steamed rice and\u00a0Papad Raita\u00a0with Aloo Gobi Ki Sabzi Recipe (Spicy Potato and Cauliflower Vegetable)\u00a0for dinner."]'::jsonb, 30, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/22-march/Kala_Chana_Cooked_In_Koli_Masala_Recipe_Maharashtrian_Koli_Style_Kala_Chana_Masala-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1327.Kala_Chana_Cooked_In_Koli_Masala_Recipe_Maharashtrian_Koli_Style_Kala_Chana_Masala-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Konkani Style Solkadhi Recipe - Kokum Drink', 'konkani-style-solkadhi-recipe-kokum-drink', 'Solkadhi or a digestive kadhi made of kokum (a plant of the mangosteen family) is very refreshing and tasty drink, a speciality of Konkan region that extends from Goa through Maharashtra.', '["12 Kokum (Malabar Tamarind)", "1 cup Fresh coconut , grated", "1 Green Chilli", "2 cloves Garlic", "2 tablespoon Coriander (Dhania) Leaves", "1/2 teaspoon Cumin powder (Jeera)", "Salt , to taste", "Mint Leaves (Pudina) , for garnish"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'green chilli', 'coriander (dhania) leaves', 'kokum (malabar tamarind)', 'coconut', 'cloves garlic', 'mint leaves (pudina)']::text[], '["To begin making the Solkadhi Recipe, first soak kokum pods in 1/2 cup warm water for 30 to 45 minutes.Squeeze the pods to extract the juices, drain the pods and retain the warm water with the extract in it.In a mortar and pestle, smash together the green chilli, cumin seeds, garlic cloves, coriander leaves and salt.", "Crush them roughly till they come together.In a mixer-grinder, blend together the freshly grated coconut with enough water to make a smooth paste.", "Strain the paste through a fine sieve to extract fresh coconut milk from it.This process can be repeated a couple of times, but bear in mind that the milk gets thinner with every consecutive extraction.In a bowl, add the extracted milk, kokum concentrate, crushed garlic and chilli spice paste and stir well to combine.Taste it and adjust seasoning as required.", "Garnish the Solkadhi with mint leaves or chopped coriander and serve chilled.Serve this\u00a0Solkadhi along with a Goan style meal of\u00a0Amlechi Uddamethi\u00a0or\u00a0Sangacho Ross\u00a0and\u00a0Steamed Rice."]'::jsonb, 45, 'Konkan', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/June-22/Sol_kadhi_recipe-3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1328.Sol_kadhi_recipe-3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ulava Charu Recipe - Spicy Andhra Horse Gram Rasam', 'ulava-charu-recipe-spicy-andhra-horse-gram-rasam', 'Ulava Charu Recipe is a authentic Andhra recipe where you cook the horse gram in a rasam form.  The Horse gram is cooked by itself in a pressure cooker and then immersed in a flavourful onion, tomato and coconut base not to forget the red chillies that lend the apt amount of heat into this dish.', '["1 cup Horse Gram Dal (Kollu/ Kulith) , uncooked", "To make the Charu Masala", "1 Onion , chopped", "1 Tomato , chopped", "1 Green Chillies", "3 Dry Red Chillies", "1/3 cup Fresh coconut , grated", "Curry leaves , handful", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "1 tablespoon Oil", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 sprig Curry leaves", "1/2 teaspoon White Urad Dal (Split)", "1 Dry Red Chilli"]'::jsonb, ARRAY['horse gram dal', 'kollu/ kulith', 'to make the charu masala', 'onion', 'tomato', 'reen chillies', 'dry red chillies', 'fresh coconut', 'curry leaves', 'turmeric powder', 'haldi', 'salt', 'oil', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'dry red chilli']::text[], '["To begin with the Ulava Charu Recipe, wash and soak the horse gram overnight.The next morning, transfer the soaked and drained horse gram into a pressure cooker with 1 cup of water, for 4-5 whistles.", "Ensure the horse gram is boiled well.Turn off the heat and allow the pressure to release naturally.", "Open the pressure cooker and set the boiled horse gram aside."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Monika_Manchanda/Horsegram_Saaru_Ulava_Charu_Recipe-15_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1329.Horsegram_Saaru_Ulava_Charu_Recipe-15_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('कुम्भ पुलाव रेसिपी - Spiced Kumbh Pulao Recipe', 'spiced-kumbh-pulao-recipe', 'कुम्भ पुलाव सरल पुलाव है जिसमे मशरुम का प्रयोग किया जाता है. अगर आपको मशरुम पसंद है तो, इस रेसिपी को जरूर बनाए। इसे बनाने में  कम समय लगता है इसलिए आप इसे अपने लंच बॉक्स में भी पैक कर सकते हो.', '["1 \u0915\u092a \u091a\u093e\u0935\u0932", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u091a\u094d\u091a \u0905\u0926\u0930\u0915 \u0932\u0939\u0938\u0941\u0928 \u0915\u093e \u092a\u0947\u0938\u094d\u091f", "1/2 \u0915\u092a \u0939\u0930\u0947 \u092e\u091f\u0930", "8 \u092c\u091f\u0928 \u092e\u0936\u0930\u0941\u092e , \u0927\u094b \u0915\u0930 \u0915\u093e\u091f \u0932\u0947", "1 \u092a\u094d\u092f\u093e\u091c , \u0915\u093e\u091f \u0915\u0930 \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u0924\u0932 \u0932\u0947", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u0902\u0926\u0942\u0930\u0940 \u092e\u0938\u093e\u0932\u093e , \u0917\u093f\u0932\u093e \u092e\u0938\u093e\u0932\u093e", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0936\u093f\u092e\u0932\u093e \u092e\u093f\u0930\u094d\u091a (\u0939\u0930\u0940) , \u0915\u093e\u091f \u0932\u0947", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0918\u0940", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "\u0939\u0940\u0902\u0917 , \u091a\u0941\u091f\u0915\u0940 \u092d\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['कप चावल', 'छोटा चमच्च अदरक लहसुन का पेस्ट', 'कप हरे मटर', 'बटन मशरुम', 'प्याज', 'बड़े चम्मच तंदूरी मसाला', 'छोटे चम्मच शिमला मिर्च', 'हरी', 'बड़े चम्मच घी', 'छोटा चम्मच जीरा', 'हींग', 'नमक']::text[], '["\u0915\u0941\u092e\u094d\u092d \u092a\u0941\u0932\u093e\u0935 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0924\u0902\u0926\u0942\u0930\u0940 \u092e\u0938\u093e\u0932\u0947 \u0915\u094b \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947\u0964 \u0907\u0938\u092e\u0947\u0902 \u092e\u0936\u0930\u0941\u092e \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0915\u094b\u091f \u0915\u0930 \u0932\u0947 \u0922\u0915\u0947 \u0914\u0930 \u092b\u094d\u0930\u0940\u091c\u0930 \u092e\u0947\u0902 1/2 \u0918\u0902\u091f\u0947 \u0915\u0947 \u0932\u093f\u090f \u0930\u0916 \u0926\u0947.\u00a0\u091a\u093e\u0935\u0932 \u0915\u094b 1 \u0918\u0902\u091f\u0947 \u0915\u0947 \u0932\u093f\u090f \u092d\u093f\u0917\u094b \u0932\u0947. \u092d\u093f\u0917\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u0947 \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u092a\u093e\u0928\u0940, \u0928\u092e\u0915\u00a0\u0914\u0930 \u0939\u0930\u0947 \u092e\u091f\u0930\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947\u0964\u00a085% \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u0917\u0930 \u092a\u093e\u0928\u0940 \u092c\u091a\u093e \u0939\u0948 \u0924\u094b \u0928\u093f\u0915\u093e\u0932 \u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947. \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0930\u0916\u0947\u0902\u0964\u00a0\u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u091c\u0940\u0930\u093e, \u0939\u0940\u0902\u0917 \u0921\u093e\u0932\u0947 \u0914\u0930 \u091c\u0940\u0930\u093e \u0915\u0947 \u0924\u095c\u0915\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0905\u0926\u0930\u0915 \u0932\u0939\u0938\u0941\u0928 \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. 2 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092e\u0930\u093f\u0928\u0947\u091f \u0915\u093f\u092f\u0947 \u0939\u0941\u090f \u092e\u0936\u0930\u0941\u092e, \u0936\u093f\u092e\u0932\u093e \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a01 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u091a\u093e\u0935\u0932, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. \u0915\u095d\u093e\u0908 \u0938\u0947 \u0922\u0915\u0947 \u0914\u0930 3 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u090f\u0915 \u092a\u094d\u0932\u0947\u091f \u092e\u0947\u0902 \u0928\u093f\u0915\u093e\u0932 \u0932\u0947.\u00a0\u0909\u0938\u0940 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0925\u094b\u095c\u093e \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902 \u0914\u0930 \u092c\u091a\u0947 \u0939\u0941\u090f \u092e\u0936\u0930\u0941\u092e \u0921\u093e\u0932\u0947\u0964 \u0925\u094b\u095c\u0947 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902\u0964\u00a0\u092a\u0941\u0932\u093e\u0935 \u0915\u094b \u092e\u0936\u0930\u0941\u092e, \u0924\u0932\u0947 \u0941\u090f \u092a\u094d\u092f\u093e\u091c \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0915\u0941\u092e\u094d\u092d \u092a\u0941\u0932\u093e\u0935\u00a0\u0915\u094b\u00a0\u092a\u093e\u0932\u0915 \u0930\u093e\u092f\u0924\u093e,\u00a0\u0932\u094c\u0915\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u092f\u093e \u0915\u093f\u0938\u0940 \u0914\u0930 \u0930\u093e\u092f\u0924\u0947 \u0915\u0947 \u0938\u093e\u0925 \u0930\u093e\u0924 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947 \u092f\u093e \u0905\u092a\u0928\u0947 \u0932\u0902\u091a \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 100, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Spiced_Kumbh_Pulao_Recipe_Spiced_Mushroom_Rice-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1330.Spiced_Kumbh_Pulao_Recipe_Spiced_Mushroom_Rice-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('केरला स्टाइल कच्चा केला और सुरन कोटु करी रेसिपी - Kerala Style Plantain & Yam Thoran Recipe', 'kerala-style-plantain-yam-thoran-recipe', 'केरला स्टाइल कच्चा केला और सुरन कोटु करी रेसिपी एक केरला स्टाइल डिश है जिसमे येम, प्लान्टेन और नारियल का प्रयोग किया जाता है. नारियल डालने से इस सब्ज़ी में ग्रैनी टेक्सचर आता है. यह रेसिपी को ओणम सध्या पर बनाया जाता है.', '["1/2 \u0915\u092a \u0915\u091a\u094d\u091a\u093e \u0915\u0947\u0932\u093e , \u0915\u093e\u091f \u0932\u0947", "1/2 \u0915\u092a \u0938\u0941\u0930\u0928 , \u0915\u093e\u091f \u0932\u0947", "1/2 \u0915\u092a \u0915\u093e\u0932\u093e \u091a\u0928\u093e", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u092a\u0940\u0938\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u092a\u0942\u0930\u0940 \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a", "3 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928", "1 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "1 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "1 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e"]'::jsonb, ARRAY['कप कच्चा केला', 'कप सुरन', 'कप काला चना', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच लाल मिर्च पाउडर', 'नमक', 'पीसने के लिए', 'छोटा चम्मच जीरा', 'कप नारियल', 'छोटा चम्मच पूरी काली मिर्च', 'कली लहसुन', 'हरी मिर्च', 'तड़के के लिए', 'छोटा चम्मच तेल', 'छोटा चम्मच राइ', 'सुखी लाल मिर्च', 'टहनी कढ़ी पत्ता']::text[], '["\u0915\u0947\u0930\u0932\u093e \u0938\u094d\u091f\u093e\u0907\u0932 \u0915\u091a\u094d\u091a\u093e \u0915\u0947\u0932\u093e \u0914\u0930 \u0938\u0941\u0930\u0928 \u0915\u094b\u091f\u0941 \u0915\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0915\u091a\u094d\u091a\u0947 \u0915\u0947\u0932\u0947 \u0914\u0930 \u0938\u0941\u0930\u0928\u00a0\u0915\u093e \u091b\u093f\u0932\u0915\u093e \u0928\u093f\u0915\u093e\u0932\u0947 \u0914\u0930 \u091b\u094b\u091f\u093e \u091b\u094b\u091f\u093e \u0915\u093e\u091f \u0932\u0947.\u090f\u0915 \u0938\u0949\u0938\u092a\u0948\u0928 \u092e\u0947\u0902 \u0907\u0928 \u0926\u094b\u0928\u094b\u0902 \u0915\u094b\u00a01/4 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915 \u0914\u0930 \u092a\u093e\u0928\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0915\u093e\u0932\u0947 \u091a\u0928\u0947 \u0915\u094b \u090f\u0915 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930 \u092a\u093e\u0928\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947 \u0914\u0930 30 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947 \u0914\u0930 \u0915\u0941\u0915\u0930 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947.\u00a0\u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0928\u093e\u0930\u093f\u092f\u0932, \u091c\u0940\u0930\u093e, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a, \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947\u00a0\u0914\u0930 \u092a\u0940\u0938 \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u092a\u0948\u0928 \u092e\u0947\u0902 \u0938\u0941\u0930\u0928, \u0915\u091a\u094d\u091a\u093e \u0915\u0947\u0932\u093e, \u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u093e \u092a\u0947\u0938\u094d\u091f, \u0928\u092e\u0915 , \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0928\u093e\u0930\u093f\u092f\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u090f\u0915 \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u0930\u093e\u0907 \u0915\u0947 \u0924\u095c\u0915\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u092f\u0939 \u0924\u095c\u0915\u093e \u0914\u0930 \u092d\u0942\u0930\u093e \u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u0930\u0940 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. \u090f\u0915 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0915\u0947\u0930\u0932\u093e \u0938\u094d\u091f\u093e\u0907\u0932 \u0915\u091a\u094d\u091a\u093e \u0915\u0947\u0932\u093e \u0914\u0930 \u0938\u0941\u0930\u0928 \u0915\u094b\u091f\u0941 \u0915\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u0915\u0947\u0930\u0932\u093e \u092a\u0930\u094b\u091f\u093e \u0914\u0930 \u092c\u0940\u091f\u0930\u0942\u091f \u092a\u091b\u0921\u093f \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 30, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/23-feb/Raw_banana_and_Yam_Kerala_Style_Thoran_Recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1331.Raw_banana_and_Yam_Kerala_Style_Thoran_Recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('पुली कुज़ह रेसिपी - Puli Koozh Recipe', 'puli-koozh-recipe', 'पुली कुज़ह रेसिपी एक पारम्परिक दक्षिण भारतीय रेसिपी है जिसे सुबह के नाश्ते के लिए बनाया जाता है. इस रेसिपी में चावल के आटे को इमली के पानी में पकाया जाता है. इसे अपने किचन में जरूर बनाए और हमे बताए की आपको यह कैसी लगी?', '["1 \u0915\u092a \u0907\u0921\u0932\u0940 \u091a\u093e\u0935\u0932", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0907\u092e\u0932\u0940", "3 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u093f\u0932 \u0915\u093e \u0924\u0947\u0932", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u091a\u0928\u093e \u0926\u093e\u0932", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0938\u095e\u0947\u0926 \u0909\u0930\u0926 \u0926\u093e\u0932", "\u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e , \u0925\u094b\u095c\u0947", "3 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "1 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0939\u0940\u0902\u0917", "1 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "3-1/2 \u0915\u092a \u092a\u093e\u0928\u0940"]'::jsonb, ARRAY['कप इडली चावल', 'बड़ा चम्मच इमली', 'बड़े चम्मच तिल का तेल', 'छोटा चम्मच राइ', 'बड़े चम्मच चना दाल', 'बड़े चम्मच सफ़ेद उरद दाल', 'कढ़ी पत्ता', 'सुखी लाल मिर्च', 'बड़े चम्मच हींग', 'बड़े चम्मच हल्दी पाउडर', 'कप पानी']::text[], '["\u092a\u0941\u0932\u0940 \u0915\u0941\u095b\u0939 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u091a\u093e\u0935\u0932 \u0915\u094b \u0927\u094b \u0915\u0930 5 \u0938\u0947 6 \u0918\u0902\u091f\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u092d\u093f\u0917\u094b \u0926\u0947. \u092a\u093e\u0928\u0940 \u0928\u093f\u0915\u093e\u0932\u00a0\u0932\u0947 \u0914\u0930 \u091a\u093e\u0935\u0932 \u0915\u094b \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u091a\u093e\u0935\u0932 \u0915\u0947 \u0938\u093e\u0925 \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947. 3 \u0938\u0947 4 \u0918\u0902\u091f\u0947 \u0915\u0947 \u0932\u093f\u090f \u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u090f\u0915 \u0915\u091f\u094b\u0930\u0940 \u092e\u0947\u0902 \u0907\u092e\u0932\u0940 \u0915\u0947 \u0938\u093e\u0925 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u0938\u0915\u093e \u0930\u0938 \u0928\u093f\u0915\u093e\u0932 \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947.\u00a0\u0924\u095c\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 15 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u091a\u0928\u093e \u0926\u093e\u0932, \u0909\u0930\u0926 \u0926\u093e\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0938\u0941\u0928\u0939\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u0947 \u0915\u0947 \u0915\u0941\u0930\u0915\u0941\u0930\u0947 \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u093e\u0928\u0940 \u0914\u0930 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947\u0964 \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u092a\u093e\u0928\u0940 \u0915\u0947 \u0909\u092c\u0932\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0917\u0948\u0938 \u0915\u0940 \u0906\u0902\u091a \u0915\u092e \u0915\u0930\u0947\u0902, \u091a\u093e\u0935\u0932 \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u092e\u093f\u0932\u093e\u0924\u0947 \u0930\u0939\u0947 \u0924\u093e\u0915\u093f \u0917\u093e\u0920\u0947 \u0928 \u092a\u095c\u0947.\u00a0\u00a08 \u0938\u0947 10 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926, \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092a\u0941\u0932\u0940 \u0915\u0941\u095b\u0939 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u0938\u0941\u092c\u0939 \u0915\u0947 \u0928\u093e\u0936\u094d\u0924\u0947 \u0915\u0947 \u0932\u093f\u090f\u00a0\u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u0940 \u091a\u091f\u0928\u0940\u00a0\u0914\u0930 \u095e\u093f\u0932\u094d\u091f\u0930 \u0915\u0949\u095e\u0940 \u0915\u0947 \u0938\u093e\u0925 \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 25, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/20-jan/Puli_Koozh_Recipe_Rice_Flour_Porridge_In_Tamarind-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1332.Puli_Koozh_Recipe_Rice_Flour_Porridge_In_Tamarind-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('गुट्टी वांकाया रेसिपी - Gutti Vankaya Recipe', 'gutti-vankaya-recipe', 'गुट्टी वांकाया रेसिपी, आंध्रा की एक प्रसिद्ध रेसिपी है जिसमे बैंगन को मसाले से भरा जाता है. आप इसे अपने रोज के खाने के लिए बना सकते है या फिर अपने मेहमानो के लिए भी परोस सकते है. यह एक स्वादिष्ट रेसिपी है जो फ्लेवर और स्वाद से भरपूर है.', '["8-10 \u092c\u0948\u0902\u0917\u0928", "1 \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u0947\u0938\u094d\u091f , \u0928\u093f\u092e\u094d\u092c\u0942 \u091c\u093f\u0924\u0928\u0940", "1 \u0915\u092a \u092a\u094d\u092f\u093e\u091c , \u092a\u0924\u0932\u093e \u0915\u093e\u091f \u0932\u0947 + 1/2 \u0915\u092a \u092c\u093e\u0930\u0940\u0915 \u0915\u091f\u093e \u0939\u0941\u0906", "\u0930\u094b\u0938\u094d\u091f \u0914\u0930 \u092a\u0940\u0938\u0928\u0947 \u0915\u0940 \u0938\u093e\u092e\u0917\u094d\u0930\u0940", "4-5 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "4 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u092e\u0942\u0902\u0917\u092b\u0932\u0940", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u093f\u0932 (\u0938\u095e\u0947\u0926)", "3 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0928\u093e\u0930\u093f\u092f\u0932", "1-1/2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u0915\u0947 \u092c\u0940\u091c", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "2 \u0907\u0932\u093e\u0907\u091a\u0940", "6 \u0932\u0939\u0938\u0941\u0928", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u091a\u0928\u093e \u0926\u093e\u0932", "\u0924\u095c\u0915\u0947 \u0915\u0940 \u0938\u093e\u092e\u0917\u094d\u0930\u0940", "\u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "2 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e"]'::jsonb, ARRAY['बैंगन', 'इमली का पेस्ट', 'कप प्याज', 'रोस्ट और पीसने की सामग्री', 'लाल मिर्च', 'बड़े चम्मच मूंगफली', 'बड़े चम्मच तिल', 'सफ़ेद', 'बड़े चम्मच नारियल', 'बड़े चम्मच धनिया के बीज', 'छोटा चम्मच जीरा', 'इलाइची', 'लहसुन', 'बड़ा चम्मच चना दाल', 'तड़के की सामग्री', 'तेल', 'तेज पत्ता', 'टहनी कढ़ी पत्ता']::text[], '["\u0917\u0941\u091f\u094d\u091f\u0940 \u0935\u093e\u0902\u0915\u093e\u092f\u093e \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u092c\u0948\u0902\u0917\u0928 \u092e\u0947\u0902 \u0926\u094b \u091a\u0940\u0930\u0947 \u090f\u0915 \u0926\u0942\u0938\u0930\u0947 \u0915\u094b \u0915\u093e\u091f\u0924\u0947 \u0939\u0941\u090f \u0932\u0917\u093e \u0932\u0947. \u0927\u094d\u092f\u093e\u0928 \u0930\u0916\u0947\u0902 \u0906\u0927\u093e \u0939\u0940 \u0915\u093e\u091f\u0947, \u0928\u093f\u091a\u0947 \u0915\u093e \u0939\u093f\u0938\u094d\u0938\u093e \u0938\u094d\u0925\u093f\u0930 \u0930\u0939\u0928\u093e \u091a\u093e\u0939\u093f\u090f\u0964\u00a0\u090f\u0915 \u0938\u0949\u0938 \u092a\u0948\u0928 \u092e\u0947\u0902 \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u0947\u0938\u094d\u091f, \u0928\u092e\u0915, \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u092c\u0932\u0928\u0947 \u0926\u0947. \u0909\u092c\u0932\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092c\u0948\u0902\u0917\u0928 \u0921\u093e\u0932\u0947, \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0922\u0915 \u0932\u0947. 10 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u0924\u092c \u0924\u0915 \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u0947 \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0925\u094b\u095c\u0947 \u0907\u092e\u0932\u0940 \u0928\u092e\u0915 \u092a\u093e\u0928\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0940\u0938 \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u090f\u0915 \u0915\u095d\u093e\u0908 \u0915\u094b \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a, \u092e\u0942\u0902\u0917\u092b\u0932\u0940, \u0924\u093f\u0932, \u0928\u093e\u0930\u093f\u092f\u0932, \u0927\u0928\u093f\u092f\u093e \u0915\u0947 \u092c\u0940\u091c, \u091c\u0940\u0930\u093e, \u0907\u0932\u093e\u0907\u091a\u0940, \u0932\u0939\u0938\u0941\u0928, \u091a\u0928\u093e \u0926\u093e\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0930\u0916 \u0926\u0947.\u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0940\u0938 \u0932\u0947. \u0907\u0938 \u092a\u093e\u0909\u0921\u0930 \u092e\u0947\u0902 \u0928\u092e\u0915, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u0907\u0938 \u092a\u093e\u0909\u0921\u0930 \u0915\u094b \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u092a\u0947\u0938\u094d\u091f \u092e\u0947\u0902 \u0921\u093e\u0932\u0947\u0964 \u0925\u094b\u095c\u093e \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u0907\u0938 \u092a\u0947\u0938\u094d\u091f \u0915\u094b \u092c\u0948\u0902\u0917\u0928 \u0915\u0947 \u0905\u0902\u0926\u0930 \u090f\u0915 \u090f\u0915 \u0915\u0930 \u0915\u0947 \u092d\u0930 \u0926\u0947.\u00a0\u090f\u0915 \u0915\u095d\u093e\u0908\u00a0\u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0909\u0938\u092e\u0947 \u091c\u0940\u0930\u093e, \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u091c\u0940\u0930\u093e \u0915\u0947 \u0924\u095c\u0915\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0924\u095c\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092d\u0930\u0947 \u0939\u0941\u090f \u092c\u0948\u0902\u0917\u0928 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u092c\u091a\u093e \u0939\u0941\u0906 \u092e\u0938\u093e\u0932\u093e \u0914\u0930 \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947\u0964 \u092c\u0948\u0902\u0917\u0928 \u0915\u094b \u0907\u0938 \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u092a\u0915\u0928\u0947 \u0926\u0947. \u092c\u0948\u0902\u0917\u0928 \u0915\u0947 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092a\u0915 \u091c\u093e\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0917\u0941\u091f\u094d\u091f\u0940 \u0935\u093e\u0902\u0915\u093e\u092f\u093e\u00a0\u0915\u094b \u0915\u0940\u0930\u0908 \u0938\u093e\u0902\u092c\u0930, \u091a\u093e\u0935\u0932 \u0914\u0930 \u092a\u093e\u092a\u095c \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 55, 'Andhra', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/uma_ganguly/gutti_vankaya_stuffed_eggplant_recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1333.gutti_vankaya_stuffed_eggplant_recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Carrot Beans Thoran Recipe - Kerala Thoran For Onam Sadya', 'carrot-beans-thoran-recipe-kerala-thoran-for-onam-sadya', 'Carrot And Beans Thoran is a classic recipe from the Kerala Cuisine, which is packed with flavors from coconut and green chillies. The addition of small pearl onions along with curry leaves, makes this thoran really delicious. It can be prepared with various vegetables like cabbage, ladies finger, drumstick, spinach/ palak and many more vegetables.', '["Thoran Masala To Be Ground", "1/2 cup Fresh coconut , grated", "2 Green Chillies , roughly chopped", "1 teaspoon Cumin seeds (Jeera)", "Thoran Vegetables", "3 Carrots (Gajjar) , chopped", "1 cup Green beans (French Beans) , chopped", "Seasoning Ingredients", "1 teaspoon Coconut Oil , or regular oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1/4 cup Pearl onions (Sambar Onions) , finely chopped", "2 sprig Curry leaves", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Salt , adjust as per your taste"]'::jsonb, ARRAY['salt', 'green beans (french beans)', 'coconut', 'mustard seeds', 'carrot', 'pearl onion (sambar onion)', 'white urad dal (split)', 'curry leaves', 'cumin seeds (jeera)', 'turmeric powder', 'coconut oil regular oil', 'green chillies']::text[], '["To prepare Carrot And Beans Thoran (Sabzi Recipe), wash carrot and beans thoroughly with water and chop all them finely.Into a pressure cooker, add the carrot and beans, along with a little salt and 3 tablespoons water and pressure cooker for 2 whistles and turn off the heat.", "Release the pressure immediately, to avoid discoloration of the vegetables.", "Keep the vegetables for the thoran aside.Into a mixer grinder, add the fresh coconut, green chillies and cumin seeds and blend without any water to make a coarse mixture.", "Keep this thoran masala aside.Heat oil in a kadai over medium heat; add the mustard seeds and urad dal and allow it to crackle.Once the urad dal turns light golden brown, add the chopped pearl onions and curry leaves.Saute the onions, until they turn soft and translucent over medium heat.", "Once done, add the turmeric powder and the ground thoran masala.", "Saute for a few seconds.Stir in the steamed carrot and beans into the above thoran mixture.", "Check the salt and add more if required.Stir the Carrot And Beans Thoran for about minute and turn off the heat.", "Transfer to a serving bowl and serve hot.", "Try our\u00a0Carrot Beans Thoran Recipe, it''s the best!\u00a0\u00a0Serve the\u00a0Carrot Beans Thoran Recipe\u00a0along with\u00a0Arachuvitta Sambar\u00a0and Steamed Rice for a traditional south indian lunch.", "Thoran\u00a0can be packed into kids lunch box as well, along with\u00a0Phulka\u00a0and Dahi."]'::jsonb, 50, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Carrot_Beans_Thoran_Kerala_Recipe_Vegetables_Healthy_Food-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1334.Carrot_Beans_Thoran_Kerala_Recipe_Vegetables_Healthy_Food-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sindhi Toor Dal Recipe With Aam Papad - Aam Papad Dal Recipe', 'sindhi-toor-dal-recipe-with-aam-papad-aam-papad-dal-recipe', 'Dal is quintessential part of the Indian Cuisine and every region and household has its own variation of preparing the same. This Sindhi Toor Dal Recipe is a simple dal cooked everyday in a Sindhi household. Though the process of making a simple dal tadka remains the same, what makes it different from the other arhar or toor dal recipe is the use of the dry mango in this recipe.', '["1 cup Arhar dal (Split Toor Dal)", "1 Tomato , finely chopped", "2 Green Chillies , slit", "1 teaspoon Ginger , finely chopped", "4 Aam Papad (Sun Dried Mango) , pieces", "1/2 teaspoon Turmeric powder (Haldi)", "2 teaspoons Coriander (Dhania) Leaves , finely chopped", "Salt , to taste", "Ingredients for the tadka", "1 teaspoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "4 cloves Garlic , finely chopped", "1/2 teaspoon Red Chilli powder"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'arhar dal (split toor dal)', 'coriander (dhania) leaves', 'ghee', 'red chilli powder', 'cloves garlic', 'aam papad (sun dried mango)', 'cumin seeds (jeera)', 'methi seeds (fenugreek seeds)', 'turmeric powder', 'green chillies']::text[], '["To begin making\u00a0Sindhi Toor Dal Recipe With Aam Papad, wash and soak the toor dal for 30 minutes.Pressure cook the soaked toor dal along with chopped tomato, ginger, turmeric, salt, 2 cups of water for 3 to 4 whistles.Allow the pressure from the pressure cooker release naturally.Once the pressure releases naturally, open the cooker and mash the dal well until dal forms a smooth consistency.", "You can use a potato masher to do this.In a heavy bottomed pan, add the cooked toor dal on low heat and to this add the slit green chillies, sun dried mango pieces\u00a0(Aam Papad), 1 cup water and let it simmer for 10 minutes till the mango tartness (katta) gets infused into the dal.Switch off the heat.", "Heat ghee in a small tadka pan over medium heat; add cumin seeds, fenugreek seeds and let it splutter.", "Add the chopped garlic and saute till it turns a bit brown.", "Finally add the red chilli powder and turn off the heat.Pour this tadka over the prepared Sindhi Toor Dal Recipe With Aam Papad and garnish with coriander leaves.", "Check the salt and adjust to taste accordingly.Serve the Sindhi Toor Dal Recipe With Aam Papad\u00a0along with\u00a0Steamed Rice\u00a0and\u00a0Tuk Patata\u00a0for a simple Sindhi inspired weeknight dinner."]'::jsonb, 30, 'Sindhi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Sindhi_Toor_Dal_Recipe-6.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1335.Sindhi_Toor_Dal_Recipe-6.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bharwa Besan Mirch Sabzi Recipe - Chillies Stuffed With Spiced Gram Flour', 'bharwa-besan-mirch-sabzi-recipe-chillies-stuffed-with-spiced-gram-flour', 'Bharwa Besan Mirch Sabzi Recipe is made by stuffing spiced sautéed besan in the badi hari mirch or bajji chillies.', '["6 Badi hari mirch (Large Green Chilli) , (non spicy) stalk removed, slit and deseeded", "1/2 cup Gram flour (besan)", "1 tablespoon Oil", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon SSP Asafoetida (Hing)", "1 teaspoon Amchur (Dry Mango Powder)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Coriander Powder (Dhania)", "Salt , salt as required", "Coriander (Dhania) Leaves , as required, finely chopped", "Oil , as required", "Water , as required"]'::jsonb, ARRAY['salt', 'amchur (dry mango powder)', 'asafoetida (hing)', 'coriander (dhania) leaves', 'water', 'gram flour (besan)', 'cumin seeds (jeera)', 'badi hari mirch (large green chilli) (non spicy) stalk', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To prepare this easy Bharwa Besan Mirch Sabzi Recipe (Chillies Stuffed With Spiced Gram Flour), Firstly make the stuffing.Heat oil in a wok/kadai and add cumin seeds and hing.", "Saut\u00e9 for about 30 seconds.Add besan into it and cook for about 10 to 15 minutes on low flame, such that the mixture doesn\u2019t get burnt.Once it is cooked, add the masalas including amchur powder, haldi powder, dhaniya powder, coriander leaves and the required salt.Saut\u00e9 well and cook for 3 - 4 minutes on low flame.", "Keep it aside.Fill the besan stuffing inside all the deseeded and slit chilies.Heat a little oil in a wide pan and add the stuffed chilies.", "Sprinkle some water on them and cover the pan with a lid.Cook it for 10 to 15 minutes or till the Bharwa Besan Mirch Sabzi become soft and appear cooked.", "Once done transfer the Mirchi ki Sabzi to a serving bowl and serve hot.Serve Bharwa Besan Mirch Sabzi as a side with dal fry\u00a0and\u00a0chapatis\u00a0for a lunch or dinner."]'::jsonb, 55, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Bharwa_Besan_Mirch_Sabzi_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1336.Bharwa_Besan_Mirch_Sabzi_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('खमंग ककड़ी रेसिपी - Khamang Kakdi Recipe', 'khamang-kakdi-recipe', 'खमंग ककड़ी एक स्वादिष्ट और सरल महाराष्ट्रियन सलाद है जिसमे ककड़ी को दही के साथ मिलकर उसमे तड़का दिया जाता है. तड़के के लिए कढ़ी पत्ता, हरी मिर्च और राइ का इस्तेमाल किया जाता है. ककड़ी गर्मियों के मौसम के लिए पर्याप्त है इसलिए आप इसे अपने रोज के खाने के साथ बना सकते है.', '["2 \u0915\u0915\u095c\u0940 , \u091b\u0940\u0932\u0915\u0930 \u0915\u093e\u091f \u0932\u0947", "1/2 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947", "\u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930, \u0915\u093e\u091f \u0932\u0947", "3 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u092e\u0942\u0902\u0917\u092b\u0932\u0940 , \u0930\u094b\u0938\u094d\u091f \u0915\u0930\u0915\u0947 \u091b\u093f\u0932\u0915\u093e \u0928\u093f\u0915\u093e\u0932 \u0932\u0947", "3 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0926\u0939\u0940", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u090f", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "1 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0940\u0902\u0917", "1 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e , \u0915\u093e\u091f \u0932\u0947"]'::jsonb, ARRAY['ककड़ी', 'कप नारियल', 'हरा धनिया', 'बड़े चम्मच मूंगफली', 'बड़े चम्मच दही', 'नमक', 'तड़के के लिए', 'छोटा चम्मच तेल', 'छोटा चम्मच राइ', 'हरी मिर्च', 'छोटा चम्मच हींग', 'टहनी कढ़ी पत्ता']::text[], '["\u0916\u092e\u0902\u0917 \u0915\u0915\u095c\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u092c\u095c\u093e \u092c\u093e\u0909\u0932 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0915\u0915\u095c\u0940, \u0928\u093e\u0930\u093f\u092f\u0932, \u0927\u0928\u093f\u092f\u093e, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0926\u0939\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092b\u093f\u0930 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f \u090f\u0915 \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u0939\u0940\u0902\u0917 \u0921\u093e\u0932\u0947 \u0914\u0930 10 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 10 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938 \u0924\u095c\u0915\u0947 \u0915\u094b \u0916\u092e\u0902\u0917 \u0915\u0915\u095c\u0940 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u0905\u0902\u0924 \u092e\u0947\u0902 \u090a\u092a\u0930 \u0938\u0947 \u092e\u0942\u0902\u0917\u092b\u0932\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. \u092a\u0930\u094b\u0938\u0947.\u00a0\u0916\u092e\u0902\u0917 \u0915\u0915\u095c\u0940\u00a0\u0915\u094b\u00a0\u0916\u0902\u0926\u0947\u0936\u0940\u00a0\u0926\u093e\u0932, \u092d\u0930\u0932\u0940 \u092d\u0947\u0902\u0921\u0940 \u0914\u0930 \u092b\u0941\u0932\u094d\u0915\u0947 \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 12, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pooja/khamang_Kakdi_an_Ayurvedic_Recipe_Maharastrian_Cucumber_Salad_20_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1337.khamang_Kakdi_an_Ayurvedic_Recipe_Maharastrian_Cucumber_Salad_20_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vazhaithandu Lemon Rasam Recipe - Banana Stem Lemon Rasam', 'vazhaithandu-lemon-rasam-recipe-banana-stem-lemon-rasam', 'The Vazhaithandu Lemon Rasam Recipe also known as the Banana Stem Lemon Rasam Plantain stem  The Vazhaithandu rasam consumes very less time when compared to other dishes. We do not remove the thin string fiber from the banana stem for this recipe.', '["1/2 cup Plantain Stem , peeled and chopped", "2 tablespoons Curd (Dahi / Yogurt)", "1 cup Water", "Salt , a pinch", "1 Tomato , roughly chopped", "4 cloves Garlic , sliced", "1 inch Ginger , chopped", "1 tablespoon Coriander Powder (Dhania)", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Black pepper powder", "1 tablespoon Lemon juice", "1/4 cup Arhar dal (Split Toor Dal) , cooked until soft", "1 sprig Curry leaves", "1 tablespoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1/4 teaspoon SSP Asafoetida (Hing)", "Coriander (Dhania) Leaves , small bunch finely chopped to garnish"]'::jsonb, ARRAY['tomato', 'salt', 'cumin powder (jeera)', 'ginger', 'arhar dal (split toor dal)', 'coriander (dhania)', 'ghee', 'mustard seeds', 'asafoetida (hing)', 'plantain stem', 'water', 'cloves garlic', 'red chilli powder', 'curd', 'curry leaves', 'lemon', 'cumin seeds (jeera)', 'black pepper powder', 'coriander powder', 'turmeric powder']::text[], '["To begin making the Vazhaithandu Lemon Rasam Recipe, whisk the yogurt salt and water in a bowl.", "Peel the outer skin of plantain stem/Vazhaithandu and discard it.", "Place the cut banana stem in the yogurt.", "This prevents it from getting discoloured.Preheat the pressure cooker over medium heat; once heated, add the mustard seeds, cumin seeds and allow it to crackle.", "Add the ginger, garlic, asafoetida, curry leaves and stir for a few seconds.Finally add the banana stem along with the yogurt water, the tomatoes and all the powders - coriander, cumin, turmeric, red chilli and salt.Stir, cover the pressure cooker & cook for about 3 whistles and turn off the heat.Release the pressure immediately, either by lifting the weight with a fork or by placing the cooker under cold water.Once done, open the cooker and stir in the cooker dal and squeeze in the lemon juice.", "Add a little water and salt and chilli if required according to your taste.", "Bring the\u00a0Vazhaithandu Lemon Rasam Recipe to a brisk boil and allow it to froth up - this will take about 4 to 5 minutes.", "Once done, turn off the heat and stir in the chopped coriander leaves and stir.Serve the\u00a0Vazhaithandu\u00a0Lemon Rasam along with a bowl of steamed rice and a\u00a0Andhra Style Beetroot Vepudu Recipe (Stir Fried Beetroot)\u00a0for a lunch or a quick and wholesome weeknight dinner."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Vazhaithandu_Lemon_Rasam_Recipe_-_Plantain_Stem_Lemon_Rasam-3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1338.Vazhaithandu_Lemon_Rasam_Recipe_-_Plantain_Stem_Lemon_Rasam-3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lehsun Methi Raita Recipe', 'lehsun-methi-raita-recipe', 'Methi Raita with Garlic is perfect recipe to serve as side dish with your lunch or dinner. It is easy to make and good for health. It’s a smart way to add green vegetable in your food. It can be served with parathas or theplas for a simple meal.', '["1 cup Methi Leaves (Fenugreek Leaves) , fresh and finely chopped", "1 cup Curd (Dahi / Yogurt) , whisked", "1 teaspoon Oil", "4 Garlic , chopped", "Salt , to taste", "1/2 tablespoon Cumin powder (Jeera)", "1/2 tablespoon Chaat Masala Powder", "Black Salt (Kala Namak) , to taste", "Water , as required", "1/2 tablespoon Chaat Masala Powder", "Black Salt (Kala Namak) , to taste", "Water , as required", "1 tablespoon Oil", "2 Garlic , chopped", "1/4 tablespoon Kashmiri Red Chilli Powder"]'::jsonb, ARRAY['methi leaves', 'fenugreek leaves', 'curd', 'dahi / yogurt', 'oil', 'arlic', 'salt', 'cumin powder', 'jeera', 'chaat masala powder', 'black salt', 'kala namak', 'water', 'kashmiri red chilli powder']::text[], '["To begin making the Methi Raita With Garlic recipe, heat oil in a pan on medium flame, add the cumin seeds and let it sizzle.To this add chopped garlic and saute till they turn golden in colour and the raw smell of the garlic goes away.Add chopped methi and saute it on high flame.Now add salt to taste, and cook until the methi leaves wilt down.Once methi is cooked, turn off the heat and keep it aside to cool it down.In a mixing bowl, combine the yogurt\u00a0 along with\u00a0cumin powder, chaat masala, black salt and cooked and cooled methi mixture.Add some water if you would like to adjust the\u00a0Methi Raita consistency.Serve Methi Raita With Garlic along with\u00a0Rajasthani Gatte Ki Sabzi\u00a0and\u00a0Phulkas\u00a0for a weekday meal."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pooja/Methi_raita_recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1339.Methi_raita_recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Maharashtrian Tindora Sabzi With Peanuts Recipe', 'maharashtrian-tindora-sabzi-with-peanuts-recipe', 'Tindora or Tendli, as Ivy gourds are popularly known, is an iron rich vegetable. It has numerous health benefits including, keeping the nervous systems healthy, increasing the metabolism, and keeping the digestive tract healthy. It is also known to be super food producing natural insulin, making it very favourable for people suffering from high blood sugar.', '["500 grams Tindora (Dondakaya/ Kovakkai) , sliced spherically", "4 cloves Garlic , finely chopped", "1 Green Chilli , finely chopped", "3 tablespoons Coriander (Dhania) Leaves , finely chopped", "1/4 cup Roasted Peanuts (Moongphali) , roughly crushed", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 teaspoons Oil", "1 teaspoon Lemon juice", "Salt , to taste"]'::jsonb, ARRAY['salt', 'green chilli', 'coriander (dhania) leaves', 'mustard seeds', 'cloves garlic', 'tindora (dondakaya kovakkai) sphericy', 'peanuts (moongphali)', 'lemon', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Maharashtrian Tindora Sabzi With Peanuts Recipe, wash, dry and thinly slice the tindoras into spheres and keep aside.Dry roast the peanuts in a pan on slow flame until it turns golden and once cool roughly crush it using a mortar and pestle and keep aside.Heat oil in the same pan, add the mustard seeds and let it splutter.Add the finely chopped garlic, green chillies and saute until it becomes crisp.Add the sliced tindoras, turmeric, season with salt and mix well.Close it with a lid and let it cook for 4 to 5 minutes, occassionaly stirring in between.Once the tindoras are cooked to a crunchy texture, add the crushed peanuts, coriander and mix well.Switch off the flame, add the lemon juice and mix well.Serve\u00a0Maharashtrian Tindora Sabzi With Peanuts along with Jowar Bhakri, Amti (Maharashtrian Dal), Steamed Rice and Chickpea and Peanut Salad as a part of the simple Maharashtrian inspired weekend lunch at home."]'::jsonb, 25, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Maharashtrian_Tindora_Sabzi_With_Peanuts_Recipe_-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1340.Maharashtrian_Tindora_Sabzi_With_Peanuts_Recipe_-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Poppy Seeds Pulao Recipe - Gasa Gasala Saddi', 'spicy-poppy-seeds-pulao-recipe-gasa-gasala-saddi', 'The Spicy Poppy Seed Pulao or the Gasa Gasala Saddi (Saddi meaning leftover rice) is delicious poppy seed flavoured rice that is a staple in most South Indian kitchens. The poppy seed rice recipe is easy to prepare made with a delicious blend of spices.', '["3 cups Cooked rice , (leftover rice)", "Salt , to taste", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Cumin powder (Jeera)", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 cup Khuskhus", "1 teaspoon Black Urad Dal (Split)", "3 cloves Garlic , finely chopped", "3 Green Chillies , slit vertically", "5 Cashew nuts , halved", "5 Sultana Raisins", "Ghee , or oil for cooking"]'::jsonb, ARRAY['s cooked rice', 'salt', 'red chilli powder', 'cumin powder', 'jeera', 'turmeric powder', 'haldi', 'mustard seeds', 'rai/ kadugu', 'khuskhus', 'black urad dal', 'split', 's garlic', 'reen chillies', 'cashew nuts', 'sultana raisins', 'ghee']::text[], '["To begin making the\u00a0Spicy Poppy Seeds Pulao Recipe, heat a tablespoon of oil in a heavy bottomed pan; add the mustard seeds, urad dal and allow it to crackle and roast.When the dal starts to brown, add the curry leaves, chopped garlic and slit green chillies.", "Stir fry for a few seconds.When the chillies start to splutter, add the\u00a0poppy seeds and stir for a few more seconds.", "Finally, add the rice, cumin powder, red chilli powder, turmeric powder and the salt as per taste.Stir well to combine all the ingredients.", "Cover the pan and allow the rice to simmer\u00a0in\u00a0the poppy seed mixture for about 5-7 minutes.", "This helps the rice to\u00a0absord\u00a0all the flavors.", "Turn off the heat and give the rice a stir and check the salt.", "Adjust to suit your taste.Heat a teaspoon of ghee in a\u00a0Tadka pan; add the cashew nuts and roast until brown and crisp.", "Once the nuts are roasted add the raisins and allow it to puff up in the ghee.", "Turn off the heat and pour this over the Poppy Seed Pulao and stir.Serve\u00a0Spicy Poppy Seeds Pulao\u00a0along with\u00a0Hyderabadi Bagara Baingan\u00a0and\u00a0Phulka\u00a0to complete your everyday meal."]'::jsonb, 65, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Spicy_Poppy_Seed_Pulao_Gasa_Gasala_Saddi_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1341.Spicy_Poppy_Seed_Pulao_Gasa_Gasala_Saddi_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kathirikai Poondu Pirattal Recipe - South Indian Style Brinjal Stir Fry With Garlic', 'kathirikai-poondu-pirattal-recipe-south-indian-style-brinjal-stir-fry-with-garlic', 'Kathirikai Poondu Pirattal Recipe is an aromatic brinjal stir fry dish with the dominant flavour of garlic . The homemade roasted sambar powder renders a beautiful flavor to the regular brinjal. This recipe is a specialty of the Chettinad region of Tamil Nadu.', '["500 grams Long Green Brinjal , cut into long strips", "1 Onion , finely chopped", "12 cloves Garlic , cut lengthwise into half", "1 Tomato , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 tablespoon Sambar Powder", "Salt , to taste", "2 tablespoons Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 pinch SSP Asafoetida (Hing)", "1 sprig Curry leaves", "1 Dry Red Chilli"]'::jsonb, ARRAY['tomato', 'salt', 'mustard seeds', 'asafoetida (hing)', 'cloves garlic', 'dry red chilli', 'curry leaves', 'white urad dal (split)', 'onion', 'green brinjal', 'turmeric powder', 'sambar powder', 'sunflower oil']::text[], '["To begin making Kathirikai Poondu Pirattal Recipe , chop the brinjals vertically and place them in a bowl filled with salt water to avoid oxidation.", "Heat oil in a Heavy bottomed pan over medium heat, add mustard seeds and urad dal and let it splutter and the dal to turn golden brown.To this add the hing, curry leaves and dried red chilli and allow it to roast for a few seconds.Next add the garlic and onions and fry until it turns into a light brown colour.", "This will take about a minute or so.", "Once done, add the tomatoes and cook until soft.Once the tomatoes are soft, add the brinjals and season with salt.", "Sprinkle with some water and cook the brinjals on a low heat with the pan covered with a lid.", "It will take around 10 minutes.Once the brinjals are cooked, add the turmeric powder and sambar powder and stir well.", "Let the Kathirikai Poondu Pirattal cook for another 3-4 minutes, occasionally keep stirring in between and switch off the flame.", "Check the salt and seasonings and adjust according to taste.Once done, transfer the\u00a0Kathirikai Poondu Pirattal to a serving bowl and serve hot.Serve the Kathirikai Poondu Pirattal Recipe along with\u00a0Steamed Rice,\u00a0Chow Chow Kootu\u00a0and\u00a0Village Style Pepper Rasam\u00a0along with\u00a0Sabudana fryums\u00a0to make an interesting Chettinad cuisine influenced Sunday lunch."]'::jsonb, 45, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nithya_Anantham/Kathirikai_Poondu_Pirattal_Recipe_Bengaluru_Kathrikai_Poriyal-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1342.Kathirikai_Poondu_Pirattal_Recipe_Bengaluru_Kathrikai_Poriyal-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rose Flavoured Shahi Tukda Recipe', 'rose-flavoured-shahi-tukda-recipe', 'Shahi Tukda is an Indian dessert which is basically a variant of a  bread pudding made of fried bread slices served with rabri. This version of Rose Flavoured Shahi Tukda Recipe includes rose water which gives it a distinctive sweetish flavour and aroma.', '["4 Whole Wheat Brown Bread", "Ghee , for shallow frying", "2 tablespoons Sugar", "1 tablespoon Water", "1 teaspoon Rose water", "2 liter Milk", "3/4 cup Sugar", "1 pinch Cardamom Powder (Elaichi)", "Rose Essence , few drops", "Rose Petals , to garnish", "Pistachios , finely chopped, for garnish"]'::jsonb, ARRAY['wheat brown bread', 'ghee', 'pistachios', 'milk', 'rose water', 'water', 'sugar', 'cardamom powder (elaichi)', 'rose essence drops', 'rose']::text[], '["To begin making Rose Flavoured Shahi Tukda Recipe, we will first make the rabri for this dish.*For the Basundi/Rabri\u00a0To begin making the Basundi Recipe, we will first have to condense the milk.", "To do this, place the milk on high heat over a heavy bottomed saucepan and bring it boil.Add the sugar and stir continuously until the sugar dissolves.", "Once the sugar has dissolved and the milk is boiling vigorously for a few minutes reduce the heat to low and simmer the milk mixture stirring continuously until it is reduced to three fourths of its original quantity.The condensation will cause the cream from the milk to settle on the sides and bottom of the pan.", "Its important to keep scraping down the cream and adding it back to the condensing milk.The mixture will begin to thicken and get a creamy texture.", "It is important to make sure towards the end of the condensing process to be close to the stove monitoring the milk and stirring it continuously.The last stages are when the condensed milk can get burned at the bottom of the pan and completely alter the taste of the basundi.Note Again: During the process of condensation of the milk, keep stirring the cream that keep forms, as it will stick to the sides and bottom of of them pan, while stirring keep scrapping down the sides and bottom to prevent burning of the cream.Once the milk has reduced to half of its original quantity, turn off the heat.", "Add the rose essence and mix.Transfer the Basundi (Rabri) to a serving dish and allow it to cool before you can refrigerate for 3-4 hours.\u00a0*For the Shahi TukdaCut each bread slice into 4 triangles.", "Heat a saucepan on medium flame, add ghee, and place the bread triangles.", "Shallow fry on both sides till you get a deep golden colour.", "Remove from the pan and set aside.In another pan, combine sugar, water and rose water and bring to a single boil.", "Turn off the flame.", "Dip the fried bread slices in the sugar syrup, drain and set aside.To serve, in a platter, pour the thick rabri and place the shahi tukda bread slices over it, garnish with pistachios and fresh or dried rose petals.", "Serve\u00a0Rose Flavoured Shahi Tukda Recipe after a scrumptious meal of\u00a0Hyderabadi Khatti Dal Recipe (Hyderabadi Tangy Lentil Curry),\u00a0Homemade Butter Naan Recipe, and\u00a0Hyderabadi Bagara Baingan Recipe."]'::jsonb, 30, 'Hyderabadi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/garimasgautam-gmail.com/Rose_Shahi_Tukda_Recipe-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1343.Rose_Shahi_Tukda_Recipe-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Moru Kachiyathu Recipe - Kerala Style Seasoned Buttermilk', 'moru-kachiyathu-recipe-kerala-style-seasoned-buttermilk', 'Moru Kachiyathu Recipe is a simple and delicious Kerala style seasoned buttermilk which is prepared every day in a Malayalee household. Moru means buttermilk in Malayalam, and no south indian meal is complete without the last course of rice had with curd or buttermilk.', '["2 cups Curd (Dahi / Yogurt)", "1-1/2 cups Water", "5 Shallots , (pearl onions), finely sliced", "1 inch Ginger , finely chopped", "3 Garlic , cloves, finely chopped", "1 Green Chilli , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1 sprig Curry leaves", "2 Dry Red Chillies", "2 teaspoons Coconut Oil", "Salt , to taste"]'::jsonb, ARRAY['garlic cloves', 'salt', 'ginger', 'green chilli', 'mustard seeds', 'water', 'curd', 'curry leaves', 'dry red chillies', 'onion', 'methi seeds (fenugreek seeds)', 'coconut oil', 'turmeric powder']::text[], '["To begin making the Moru Kachiyathu Recipe (Kerala Style Seasoned Buttermilk), add the curd into a big bowl and whisk it to a silky texture.To this add water and whisk it to get to a semi thick buttermilk consistency.", "Heat coconut oil in a wok, add the mustard seeds and let it crackle.Add the methi seeds, curry leaves, red chillies and let it splutter.To this add the finely sliced shallots, garlic and saute until the onions turn translucent.Add the chopped ginger, green chillies, turmeric powder and flash fry it.Keep the heat to low, and slowly add the buttermilk into the wok.Keep stirring, until the buttermilk get just warm and starts to bubble.", "Make sure you don''t bring it to a boil to avoid curdling.Switch off the flame, season with salt and mix well.", "Serve the\u00a0Moru Kachiyathu Recipe\u00a0(Kerala Style Seasoned Buttermilk) along with\u00a0Mixed Vegetable Sambar,\u00a0Steamed Rice\u00a0and\u00a0Beetroot Thoran\u00a0to make it a perfect simple meal for a weekday lunch."]'::jsonb, 20, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Moru_Kachiyathu_Recipe_Mor_Kuzhambu_with_onions-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1344.Moru_Kachiyathu_Recipe_Mor_Kuzhambu_with_onions-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('स्मोक्ड ढाबा दाल रेसिपी - Smoked Dhaba Dal Recipe', 'smoked-dhaba-dal-recipe-2', 'स्मोक्ड ढाबा दाल रेसिपी एक क्लासिक रेसिपी है जिसमे बहुत सारी डालो का प्रयोग किया जाता है. इसमें डाल को स्मोक करने के लिए कोयले का प्रयोग किया जाता है जिससे इस दाल का स्वाद और भी बढ़ जाता है. यह दाल आपको हर ढाबे पर मिलेगी और इसका स्वाद आपको बार बार वहा ले जायेगा।', '["1/2 \u0915\u092a \u0905\u0930\u0939\u0930 \u0926\u093e\u0932", "1/2 \u0915\u092a \u0939\u0930\u0940 \u092e\u0942\u0902\u0917 \u0926\u093e\u0932", "1 \u092a\u094d\u092f\u093e\u091c , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "2 \u091f\u092e\u093e\u091f\u0930 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "2 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0915\u093e\u0932\u093e \u0928\u092e\u0915 \u092f\u093e \u0938\u0947\u0902\u0927\u093e \u0928\u092e\u0915", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0918\u0940", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "2 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928 , \u092a\u0924\u0932\u093e \u0914\u0930 \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "4 \u091f\u0939\u0928\u0940 \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "2 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a , \u0924\u094b\u095c \u0932\u0947", "1 \u0915\u094b\u092f\u0932\u093e"]'::jsonb, ARRAY['कप अरहर दाल', 'कप हरी मूंग दाल', 'प्याज', 'टमाटर', 'कली लहसुन', 'इंच अदरक', 'हरी मिर्च', 'छोटा चम्मच जीरा पाउडर', 'छोटा चम्मच धनिया पाउडर', 'छोटा चम्मच लाल मिर्च पाउडर', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच काला नमक या सेंधा नमक', 'नमक', 'तेल', 'तड़के के लिए', 'बड़ा चम्मच घी', 'छोटा चम्मच जीरा', 'टहनी हरा धनिया', 'सुखी लाल मिर्च', 'कोयला']::text[], '["\u0938\u094d\u092e\u094b\u0915\u094d\u0921 \u0922\u093e\u092c\u093e \u0926\u093e\u0932 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0924\u0941\u0905\u0930 \u0926\u093e\u0932, \u0939\u0930\u0940 \u092e\u0942\u0902\u0917 \u0926\u093e\u0932 \u0915\u094b 1 \u0918\u0923\u094d\u091f\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u0938\u094b\u0916\u00a0\u0932\u0947.\u0905\u092c \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c, \u0905\u0926\u0930\u0915, \u0932\u0939\u0938\u0941\u0928, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930, \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915, \u0915\u093e\u0932\u093e \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.2 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092d\u093f\u0917\u094b\u0908 \u0939\u0941\u0908 \u0926\u093e\u0932, 3 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u0915\u0941\u0915\u0930 \u0915\u094b \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947. 2 \u0938\u0947 3 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. 3 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0917\u0948\u0938 \u0915\u0940 \u0906\u0902\u091a \u0915\u092e \u0915\u0930\u0947\u0902 \u0914\u0930 5 \u0938\u0947 8 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u092a\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947. \u0915\u0941\u0915\u0930 \u0916\u094b\u0932\u0947, \u0926\u093e\u0932 \u0915\u094b \u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u0947 \u0921\u093e\u0932 \u0915\u0930 \u092b\u093f\u0930 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u0905\u092c \u0915\u094b\u092f\u0932\u0947 \u0915\u094b \u0938\u0940\u0927\u093e \u0917\u0948\u0938 \u0915\u0940 \u0906\u0902\u091a \u092a\u0930 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0915\u094b\u092f\u0932\u0947 \u0915\u0947 \u0932\u093e\u0932 \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u090f\u0915 \u0939\u0940\u091f\u092a\u094d\u0930\u0942\u095e \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947\u0964 \u0907\u0938 \u092c\u093e\u0909\u0932 \u0915\u094b \u0926\u093e\u0932 \u0915\u0947 \u090a\u092a\u0930 \u0930\u0916\u0947\u0902 \u0914\u0930 \u0915\u094b\u092f\u0932\u0947 \u092a\u0930 \u0925\u094b\u095c\u093e \u0918\u0940 \u0921\u093e\u0932\u0947\u0964 \u0926\u093e\u0932 \u0915\u094b 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0922\u0915 \u0926\u0947.\u00a0\u092c\u093e\u0909\u0932 \u0928\u093f\u0915\u093e\u0932\u0947 \u0914\u0930 \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932 \u0926\u0947. \u0905\u092c \u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f \u090f\u0915 \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964\u00a0\u0907\u0938\u092e\u0947\u0902 \u091c\u0940\u0930\u093e, \u0932\u0939\u0938\u0941\u0928, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 15 \u0938\u0947 20 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0907\u0938 \u0924\u095c\u0915\u0947 \u0915\u094b \u0926\u093e\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0938\u094d\u092e\u094b\u0915\u094d\u0921 \u0922\u093e\u092c\u093e \u0926\u093e\u0932 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0938\u0947\u0935 \u091f\u092e\u093e\u091f\u0930 \u0915\u0940 \u0938\u092c\u094d\u095b\u0940\u00a0\u0914\u0930 \u0924\u0902\u0926\u0941\u0930\u0940 \u0930\u094b\u091f\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 50, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shyma_Menon/Smoked_Dhaba_Dal_Recipe_Green_moong_and_toor_dal-4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1345.Smoked_Dhaba_Dal_Recipe_Green_moong_and_toor_dal-4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('लहसुन की चटनी रेसिपी - Lahsun ki Chutney Recipe', 'lahsun-ki-chutney-recipe', 'लहसुन की चटनी रेसिपी जिसे गार्लिक चटनी भी कहा जाता है एक स्वादिष्ट चटनी है जिसे वड़ा पाव, चाट या किसी और डिश में इस्तेमाल किया जा सकता है. यह चटनी ज़्यदातर गुजरात और राजस्थान में बनाई जाती है. इसमें निम्बू और हरी मिर्च का भी प्रयोग किया जाता है जो इस चटनी को और भी स्वादिष्ट भी बनाता है.', '["20 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928 , \u091b\u0940\u0932 \u0932\u0947", "1-1/2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930 , \u0938\u0947\u0915 \u0932\u0947", "1 \u0928\u093f\u092e\u094d\u092c\u0942 \u0915\u093e \u0930\u0938", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['कली लहसुन', 'छोटे चम्मच लाल मिर्च पाउडर', 'छोटा चम्मच जीरा पाउडर', 'निम्बू का रस', 'नमक']::text[], '["\u0932\u0939\u0938\u0941\u0928 \u0915\u0940 \u091a\u091f\u0928\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0932\u0939\u0938\u0941\u0928, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930 \u0914\u0930 \u0928\u093f\u092e\u094d\u092c\u0942 \u0915\u0947 \u0930\u0938 \u0915\u094b \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0921\u093e\u0932 \u0926\u0947.\u0907\u0938\u092e\u0947\u0902 \u0928\u092e\u0915, \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947. \u0906\u092a\u0915\u0940 \u091a\u091f\u0928\u0940 \u0924\u0948\u092f\u093e\u0930 \u0939\u0948. \u0907\u0938 \u091a\u091f\u0928\u0940 \u0915\u094b \u0906\u092a \u092b\u094d\u0930\u093f\u091c \u092e\u0947\u0902 3 \u0938\u0947 4 \u0926\u093f\u0928 \u0915\u0947 \u0932\u093f\u090f \u0930\u0916 \u0938\u0915\u0924\u0947 \u0939\u0948.\u0932\u0939\u0938\u0941\u0928 \u0915\u0940 \u091a\u091f\u0928\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u0930\u093e\u091c\u0938\u094d\u0925\u093e\u0928\u0940 \u0926\u093e\u0932 \u092c\u093e\u091f\u0940 \u091a\u0942\u0930\u092e\u093e \u0914\u0930 \u092e\u0938\u093e\u0932\u093e \u091b\u093e\u0938\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 20, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Articles/Lehsun_Chutney_Garlic_Chutney_Video_Recipe_7_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1346.Lehsun_Chutney_Garlic_Chutney_Video_Recipe_7_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('चना मेथी दाल रेसिपी - Chana Methi Dal Recipe', 'chana-methi-dal-recipe', 'चना मेथी दाल एक स्वादिष्ट दाल है जिसमे चने की दाल को मेथी के साथ पकाया जाता है. यह बहुत ही सेहतमंद रेसिपी है क्यूंकि इसमें प्रोटीन के साथ साथ आयरन भी होता है. आप इस दाल को अपने रोज के खाने के लिए बनाए और इसका आनंद ले. यह बनाने में बहुत आसान है और इसमें बहुत कम सामग्री की आवश्यकता होती है.', '["1 \u0915\u092a \u091a\u0928\u093e \u0926\u093e\u0932", "1 \u0915\u092a \u092e\u0947\u0925\u0940 , \u0938\u093e\u095e \u0915\u0930\u0915\u0947 \u0915\u093e\u091f \u0932\u0947", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0940\u0902\u0917", "1 \u092a\u094d\u092f\u093e\u091c , \u092a\u0924\u0932\u093e \u0915\u093e\u091f \u0932\u0947", "1 \u091f\u092e\u093e\u091f\u0930 , \u0915\u093e\u091f \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0918\u0940", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "2 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a"]'::jsonb, ARRAY['कप चना दाल', 'कप मेथी', 'छोटा चम्मच हींग', 'प्याज', 'टमाटर', 'छोटा चम्मच हरा धनिया', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच लाल मिर्च पाउडर', 'नमक', 'तड़के के लिए', 'बड़ा चम्मच घी', 'छोटा चम्मच जीरा', 'सुखी लाल मिर्च']::text[], '["\u091a\u0928\u093e \u092e\u0947\u0925\u0940 \u0926\u093e\u0932 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u091a\u0928\u093e \u0926\u093e\u0932 \u0915\u094b 3 \u0915\u092a \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 30 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092d\u093f\u0917\u094b \u0926\u0947. \u0905\u092c \u092e\u0947\u0925\u0940 \u0915\u094b \u092a\u093e\u0928\u0940 \u0938\u0947 \u0927\u094b\u0915\u0930 \u0915\u093e\u091f \u0932\u0947.\u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u092e\u0947\u0925\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u0947\u0925\u0940 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u092e\u0947\u0925\u0940 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0939\u0940\u0902\u0917 \u0921\u093e\u0932\u0947 \u0914\u0930 10 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. 10 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u0928\u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930 \u0915\u0947 \u0938\u093e\u0925 \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0915\u0928\u0947 \u0926\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u091a\u0928\u093e \u0926\u093e\u0932 \u092a\u093e\u0928\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947\u0964 \u0915\u0941\u0915\u0930 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 6 \u0938\u0947 8 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947.\u00a0\u0915\u0941\u0915\u0930 \u0915\u094b \u0916\u094b\u0932\u0947, \u0926\u093e\u0932 \u0915\u094b \u092e\u0948\u0936 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0907\u0938\u092e\u0947\u0902 \u092e\u0947\u0925\u0940 \u0921\u093e\u0932\u0947\u0964 \u092e\u093f\u0932\u093e \u0932\u0947 \u0914\u0930 \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0928\u093f\u0915\u093e\u0932 \u0932\u0947.\u00a0\u0905\u092c \u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f, \u090f\u0915 \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u091c\u0940\u0930\u093e, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 15 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0924\u0915 \u092a\u0915\u0928\u0947 \u0926\u0947. \u0924\u095c\u0915\u093e \u0915\u094b \u0926\u093e\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u091a\u0928\u093e \u092e\u0947\u0925\u0940 \u0926\u093e\u0932 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u091f\u092e\u093e\u091f\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u0915\u095c\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0,\u00a0\u091f\u092e\u093e\u091f\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u0915\u095c\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u0914\u0930 \u092b\u0941\u0932\u094d\u0915\u0947 \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Methi_Chana_Dal_Recipe-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1347.Methi_Chana_Dal_Recipe-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Palak Pappu Recipe - Andhra Style Palakura Pappu - Dal Palak', 'palak-pappu-recipe-andhra-style-palakura-pappu-dal-palak', 'Palak pappu also known as Palakura Pappu is a nutrition dense and protein rich dal palak recipe is very famous down south of india.', '["1 cup Arhar dal (Split Toor Dal)", "1 Onion , roughly chopped", "1 Green Chilli , slit", "1 inch Ginger , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "2 cups Water", "Salt , to taste", "1 cup Spinach Leaves (Palak) , chopped", "Palak Pappu Tadka", "1 tablespoon Ghee", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon White Urad Dal (Split)", "4 cloves Garlic", "2 Dry Red Chillies , broken", "2 sprig Curry leaves , roughly torn"]'::jsonb, ARRAY['salt', 'ginger', 'arhar dal (split toor dal)', 'green chilli', 'ghee', 'mustard seeds', 'water', 'cloves garlic', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'spinach leaves (palak)']::text[], '["To begin with the Palak pappu , first pressure cook the\u00a0spinach/palak along with 2 tablespoons water and a pinch of salt for 1 whistle.After the first whistle turn off the heat and release the pressure immediately and open the cooker.", "This will ensure the palak has a rich green color.Heat oil into a pressure cooker over medium heat; add the onions, green chillies, ginger and saute until the onions soften.", "Once it softens, add the turmeric powder, salt and 2 cups of water.", "Pressure cook the pappu/ dal for 3 to 4 whistles and turn off the heat.", "Allow the pressure to release naturally, as the dal will continue to cook, as long as there is pressure inside the cooker.Once done, open and lightly mash the dal.", "Stir in the cooked palak into the pappu and give it a taste and adjust the salt accordingly.", "Bring the palak pappu to a brisk boil and turn off the heat.", "Once done, transfer the palak pappu to as serving bowl.The lastly, heat ghee in a tadka pan over medium heat; add the mustard seeds, urad dal and allow it to crackle and the dal to turn golden brown.Once the dal turns brown, add the garlic, red chillies and curry leaves and saute for a few seconds until you can smell the aroma of the garlic coming through.Pour this seasoning over the Palak Pappu and serve hot.Your Palak pappu (Spinach Dal) Recipe is ready, transfer it into a serving bowl and garnish with coriander leaves.Serve the\u00a0Palak Pappu Recipe\u00a0along with hot bowl of rice, topped with ghee and a\u00a0Potato Roast\u00a0for a lunch or dinner.If you are looking to make a healthy diabetic friendly lunch then serve the\u00a0Palak Pappu Recipe\u00a0along with\u00a0Bajre Ki Roti Recipe\u00a0or\u00a0Jowar Roti\u00a0with raita."]'::jsonb, 50, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Andhra_Palakura_Pappu_Recipe_Dal_palk_south_indian_andhra_recipe_lunch_dinner-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1348.Andhra_Palakura_Pappu_Recipe_Dal_palk_south_indian_andhra_recipe_lunch_dinner-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Rajasthani Pyaaz Ki Kadhi Recipe - Onion Kadhi Recipe', 'rajasthani-pyaaz-ki-kadhi-recipe-onion-kadhi-recipe', 'Rajasthani Pyaaz Ki Kadhi Recipe is a simple to make warm and comforting dish. It makes use of very few ingredients, making it an idle dish to prepare when you run out of ingredients in your kitchen pantry.', '["1 cup Curd (Dahi / Yogurt) , beaten to a smooth texture", "2 tablespoons Gram flour (besan)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 cup Water", "1 Onion , thinly sliced", "1 tablespoon Ginger , finely chopped", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Methi Seeds (Fenugreek Seeds)", "1 pinch SSP Asafoetida (Hing)", "1 tablespoon Ghee", "Ingredients for the second tadka", "1 tablespoon Ghee", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Coriander (Dhania) Seeds", "1 Dry Red Chilli", "1 sprig Curry leaves"]'::jsonb, ARRAY['ginger', 'curd smooth texture', 'mustard seeds', 'asafoetida (hing)', 'ghee', 'red chilli powder', 'water', 'gram flour (besan)', 'dry red chilli', 'curry leaves', 'coriander (dhania) seeds', 'onion', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'turmeric powder']::text[], '["To begin making Rajasthani Pyaaz Ki Kadhi Recipe, take a big bowl, add curd, chickpeas flour (besan), turmeric powder and red chilli powder and whisk it to a smooth consistency.", "Add water and mix well to a thin consistency until it smooth.Heat ghee in a heavy bottomed pan on medium flame, add mustard seeds, fenugreek seeds and let it splutter.Add a pinch of asafoetida, sliced onion and saute until the onion turns translucent.Once the onions are soft, add the kadhi mixture that you prepared earlier, enough water and bring it to a rolling boil keeping the flame on high.Lower the heat, season with salt and let the kadhi simmer for 10 minutes until kadhi cooks well.", "The more you simmer, the more flavours come from the pyaz and the besan mixture to make a delicious tasting pyaz ki kadhi.Turn off the heat and prepare the second tadka.Heat ghee in a small tadka pan on medium heat, add the cumin and whole coriander seeds and let it splutter.Add the curry leaves, dried red chilli, mix and switch off the heat.", "Add the red chilli powder, mix and pout it over the prepared kadhi.Serve the\u00a0Rajasthani Pyaz Ki Kadhi\u00a0Recipe along with\u00a0Bajri Ki Roti\u00a0with a dollop of ghee.", "You can also serve\u00a0Masala Khichia\u00a0on the side.", "This Kadhi tastes great with\u00a0Steamed Rice\u00a0or\u00a0Jeera Rice\u00a0too."]'::jsonb, 25, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Pyaz_Ki_Kadhi_Recipe-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1349.Pyaz_Ki_Kadhi_Recipe-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('राजस्थानी प्याज की कढ़ी रेसिपी - Rajasthani Pyaaz Ki Kadhi Recipe', 'rajasthani-pyaaz-ki-kadhi-recipe', 'राजस्थानी प्याज की कढ़ी रेसिपी एक सरल रेसिपी है जिसे आप सर्दियों के रात के खाने के लिए बना सकते है. इसमें बहुत कम सामग्री की आवश्यकता होती है और बहुत कम समय में बन भी जाती है. इसमें दो बार तड़का दिया जाता है जो इसके स्वाद और फ्लेवर को और भी बढ़ा देता है.', '["1 \u0915\u092a \u0926\u0939\u0940 , \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092b\u0947\u091f \u0932\u0947", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u092c\u0947\u0938\u0928", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1 \u0915\u092a \u092a\u093e\u0928\u0940", "1 \u092a\u094d\u092f\u093e\u091c , \u092a\u0924\u0932\u093e \u0914\u0930 \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0905\u0926\u0930\u0915 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u092e\u0947\u0925\u0940 \u0915\u0947 \u0926\u093e\u0928\u0947", "\u0939\u0940\u0902\u0917 , \u091a\u0941\u091f\u0915\u0940 \u092d\u0930", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0918\u0940", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0918\u0940", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c", "1 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "1 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e"]'::jsonb, ARRAY['कप दही', 'बड़े चम्मच बेसन', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच लाल मिर्च पाउडर', 'कप पानी', 'प्याज', 'बड़ा चम्मच अदरक', 'छोटा चम्मच राइ', 'छोटा चम्मच मेथी के दाने', 'हींग', 'बड़ा चम्मच घी', 'तड़के के लिए', 'छोटा चम्मच जीरा', 'छोटा चम्मच धनिये के बीज', 'सुखी लाल मिर्च', 'टहनी कढ़ी पत्ता']::text[], '["\u0930\u093e\u091c\u0938\u094d\u0925\u093e\u0928\u0940 \u092a\u094d\u092f\u093e\u091c \u0915\u0940 \u0915\u095d\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0926\u0939\u0940, \u092c\u0947\u0938\u0928, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u0927\u094d\u092f\u093e\u0928 \u0930\u0916\u0947\u0902 \u0917\u093e\u0920\u0947\u0902 \u0928 \u092a\u095c\u0947.\u00a0\u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u092e\u0947\u0925\u0940 \u0915\u0947 \u0926\u093e\u0928\u0947 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0930\u093e\u0907\u00a0\u0915\u094b \u0924\u095c\u0915\u0928\u0947 \u0926\u0947.\u00a0 \u0939\u0940\u0902\u0917, \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947\u00a0\u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0915\u095d\u0940 \u0915\u093e \u092e\u093f\u0936\u094d\u0930\u0923, \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u092c\u0932\u0928\u0947 \u0926\u0947.\u00a0\u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926\u00a0\u0917\u0948\u0938 \u0915\u0940 \u0906\u0902\u091a \u0915\u092e \u0915\u0930\u0947\u0902, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0915\u095d\u0940 \u0915\u094b \u0927\u0940\u092e\u0940 \u0906\u0902\u091a \u092a\u0930 10 \u0938\u0947 15 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u0928\u0947 \u0926\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0928\u093f\u0915\u093e\u0932 \u0932\u0947.\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f, \u090f\u0915 \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u091c\u0940\u0930\u093e, \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 15 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 10 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u092c\u093e\u0926 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947. \u0915\u095d\u0940 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u092a\u0930\u094b\u0938\u0947.\u00a0\u0930\u093e\u091c\u0938\u094d\u0925\u093e\u0928\u0940 \u092a\u094d\u092f\u093e\u091c \u0915\u0940 \u0915\u095d\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u092e\u0915\u094d\u0915\u0940 \u0915\u0940 \u0930\u094b\u091f\u0940 \u0914\u0930\u00a0\u0938\u0930\u0938\u094b \u0915\u0947 \u0938\u093e\u0917\u00a0\u0915\u0947 \u0938\u093e\u0925 \u092a\u0930\u094b\u0938\u0947\u0964 \u0906\u092a \u0907\u0938\u0947 \u091a\u093e\u0935\u0932 \u0914\u0930\u00a0\u0915\u091a\u0941\u092e\u094d\u092c\u0930 \u0938\u0932\u093e\u0926\u00a0\u0915\u0947 \u0938\u093e\u0925 \u092d\u0940 \u092a\u0930\u094b\u0938 \u0938\u0915\u0924\u0947 \u0939\u0948."]'::jsonb, 25, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Pyaz_Ki_Kadhi_Recipe-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1350.Pyaz_Ki_Kadhi_Recipe-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Green Beans Poriyal Recipe With Peanuts & Sesame Recipe', 'green-beans-poriyal-recipe-with-peanuts-sesame-recipe', 'Green Beans Poriyal With Peanuts & Sesame Recipe is a simple stir fry recipe with stir fried green beans/ haricot beans cooked with a spice mix of sesame seeds and peanuts. Green Beans provide a wealth of nutrients in addition to being a versatile and delicious element in many culinary preparations.', '["2 cups Green beans (French Beans) , chopped into 1 inch sizes", "Salt , as per taste", "1/2 teaspoon Red Chilli powder", "1 teaspoon Oil", "2 tablespoons Water", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 Dry Red Chilli", "1 teaspoon Sesame seeds (Til seeds)", "2 tablespoons Raw Peanuts (Moongphali)"]'::jsonb, ARRAY['salt', 'mustard seeds', 'red chilli powder', 'water', 'green beans (french beans) sizes', 'dry red chilli', 'cumin seeds (jeera)', 'peanuts (moongphali)', 'sesame seeds (til seeds)', 'sunflower oil']::text[], '["To begin making Beans Poriyal With Peanuts & Sesame Recipe, in a pressure cooker, add the chopped beans, salt, 2 tablespoons water, mix well and cook for 1 whistle.", "After the first whistle, release the pressure immediately by running it under cold water and keep aside.Place a pan on medium flame and dry roast sesame seeds and peanuts separately until they turn aromatic.", "Cool completely and grind into a coarse powder in a mixer.In the same pan, add one teaspoon oil on medium flame and add the mustard seeds, cumin seeds and dry red chilli.", "Once the mustard seeds crackle, add the cooked beans and saute for about a minute.Add red chilli powder and the prepared sesame peanut spice mix and give a quick stir.", "Since the Beans Poriyal\u00a0has already been cooked with salt, there is no need for extra salt.", "But if you prefer, add a little more.", "Once done, turn off the heat.Serve\u00a0Green\u00a0Beans Poriyal With Peanuts & Sesame Recipe\u00a0with\u00a0Thakkali Rasam Recipe\u00a0and\u00a0Mixed Vegetable Sambar Recipe\u00a0for a wholesome Tamil Nadu style meal.", "This Poriyal is also an excellent recipe for an\u00a0Indian diabetic lunch or dinner."]'::jsonb, 25, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/anu.mallajosyula-gmail.com/Green_Beans_Poriyal_recipe_south_indian_sabzi-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1351.Green_Beans_Poriyal_recipe_south_indian_sabzi-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('आलुची भाजी रेसिपी - Aluchi Bhaji Recipe', 'aluchi-bhaji-recipe', 'आलुची भाजी रेसिपी एक महाराष्ट्रियन करी है जिसमे अरबी के पत्तो का इस्तेमाल किया जाता है. इसमें प्याज और लहसुन का प्रयोग नहीं किया जाता, इसलिए आप इसे अपने त्यौहार के खाने के लिए भी बना सकते है. आप इसे किसी ख़ास अवसर के लिए पूरी और रायते के साथ भी बना सकते है.', '["50 \u0917\u094d\u0930\u093e\u092e \u0905\u0930\u092c\u0940 , \u092a\u0924\u094d\u0924\u093f\u092f\u093e\u0902, \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1/4 \u0915\u092a \u092e\u0942\u0902\u0917\u092b\u0932\u0940 , 30 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0917\u0930\u092e \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u092d\u093f\u0917\u094b \u0932\u0947", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u091a\u0928\u093e \u0926\u093e\u0932 , 30 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0917\u0930\u092e \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u092d\u093f\u0917\u094b \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0940\u0902\u0917", "7 \u0938\u0942\u0916\u093e \u0928\u093e\u0930\u093f\u092f\u0932 , \u092a\u0924\u0932\u093e \u0915\u093e\u091f \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0905\u092e\u091a\u0942\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0917\u0941\u095c , \u0915\u0938 \u0932\u0947", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0938\u0940\u0927\u093e \u0914\u0930 \u092a\u0924\u0932\u093e \u0915\u093e\u091f \u0932\u0947", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['ग्राम अरबी', 'कप मूंगफली', 'बड़े चम्मच चना दाल', 'छोटा चम्मच तेल', 'छोटा चम्मच जीरा', 'छोटा चम्मच राइ', 'छोटा चम्मच हींग', 'सूखा नारियल', 'छोटा चम्मच अमचूर', 'छोटा चम्मच हल्दी पाउडर', 'छोटे चम्मच गुड़', 'हरी मिर्च', 'नमक']::text[], '["\u0906\u0932\u0941\u091a\u0940 \u092d\u093e\u091c\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0938\u093e\u0930\u0940\u00a0\u0938\u093e\u092e\u0917\u094d\u0930\u0940 \u0924\u0948\u092f\u093e\u0930 \u0915\u0930 \u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u091a\u0928\u093e \u0926\u093e\u0932 \u0915\u094b 1 \u0918\u0902\u091f\u0947 \u0915\u0947 \u0932\u093f\u090f \u092d\u093f\u0917\u094b \u0926\u0947. \u0905\u092c \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u091a\u0928\u093e \u0926\u093e\u0932, \u092e\u0942\u0902\u0917\u092b\u0932\u0940, \u0928\u092e\u0915, 1/4 \u0915\u092a \u092a\u093e\u0928\u0940 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 3 \u0938\u0947 4 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930\u00a0\u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947\u0964\u00a0\u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u091c\u0940\u0930\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0939\u0940\u0902\u0917, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0905\u0930\u092c\u0940 \u0915\u0947 \u092a\u0924\u094d\u0924\u0947 \\, \u0905\u092e\u091a\u0942\u0930, \u0917\u0941\u095c, \u0928\u092e\u0915, \u0928\u093e\u0930\u093f\u092f\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u0905\u0930\u092c\u0940 \u0915\u0947 \u092a\u0924\u094d\u0924\u094b \u0915\u0947 \u092a\u0915\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u091a\u0928\u093e \u0926\u093e\u0932, \u092a\u0940\u0928\u091f \u0915\u093e \u092e\u093f\u0936\u094d\u0930\u0923 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0926\u0947. \u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947.\u00a0\u0906\u0932\u0941\u091a\u0940 \u092d\u093e\u091c\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0905\u091c\u0935\u093e\u0907\u0928 \u092a\u0942\u0930\u0940,\u00a0\u092c\u0942\u0902\u0926\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u0914\u0930 \u0906\u091f\u0947 \u0915\u0947 \u0939\u0932\u0935\u0947 \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f\u00a0\u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 30, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/9-feb/Aluchi_Bhaji_Maharastrian_Colacasia_leaves_curry_with_peanuts-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1352.Aluchi_Bhaji_Maharastrian_Colacasia_leaves_curry_with_peanuts-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Soya Keema Matar Masala Recipe', 'soya-keema-matar-masala-recipe', 'Soya Keema masala is a delicious vegetarian keema that can be prepared quickly and easily. In this recipe, you just need to soak soya granules in water, pulse it in the mixer and then cook it in masala along with the peas.', '["1 cup Soy Chunks (Nuggets) , soaked in hot water for 30 min", "1 Onion , finely chopped", "1 Green Chillies , finely chopped", "1/4 cup Green peas (Matar)", "1 tablespoon Oil", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "1 teaspoon Coriander Powder (Dhania)", "1/2 tablespoon Red Chilli powder , adjust as per your spice preference", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Garam masala powder", "4 sprig Coriander (Dhania) Leaves , for garnish", "Salt , to taste", "1 teaspoon Sugar"]'::jsonb, ARRAY['salt', 'ginger', 'soy (nuggets) min', 'red chilli powder per spice preference', 'green peas (matar)', 'cloves garlic', 'coriander (dhania) leaves', 'sugar', 'onion', 'coriander powder', 'turmeric powder', 'green chillies', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Soya Keema Matar masala, soak soya granules or if you are using chunks in hot water for half an hour.Once soaked, drain soya granules, squeeze the water out slightly from the soya granules and pulse in a mixer grinder once or twice to get a coarse keema texture of the soya granules.If using fresh green peas, blanch them in hot water until they get cooked.", "Drain and keep aside.Heat a tablespoon of oil in a wok.", "Add finely chopped onions, ginger, garlic and green chilies and cook till onions turn soft.Add in the turmeric powder, red chilli powder, coriander powder, garam masala sugar, and salt, mix well cook for about 15 seconds.Add soya granules mix well, simmer and let it cook for 10 minutes in its own juices.", "Check the salt and spices and adjust according to taste.Turn off heat, garnish the Soya Keema Matar masala with coriander leaves and transfer to as serving bowl and serve hot.Serve Soya Keema Matar Masala with\u00a0Whole Wheat Lachha Paratha,\u00a0Palak Tovve or Palak Dal\u00a0\u00a0and\u00a0Boondi Raita Recipe Spiced With Black Salt\u00a0for a perfect meal."]'::jsonb, 55, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Soya_Keema_Matar_Recipe_12.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1353.Soya_Keema_Matar_Recipe_12.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Ellu Chutney Recipe - Sesame Seeds Chutney Recipe', 'ellu-chutney-recipe-sesame-seeds-chutney-recipe', 'Ellu Chutney also known as the Sesame Seeds Chutney Recipe is one of the popular accompaniment recipes from South India. It is usually made using black sesame. Sesame with its nutty taste and flavor gives a unique taste to this til ki chutney. Serve Ellu Chutney (Sesame Seeds Chutney Recipe) as a side dish to your favorite idli / dosa recipe.', '["1/4 cup Black sesame seeds", "1 tablespoon White Urad Dal (Split)", "1/4 cup Fresh coconut , grated", "5 Dry Red Chillies", "Curry leaves , a few", "20 grams Tamarind , soaked in water", "Salt , to taste", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "Curry leaves , a few"]'::jsonb, ARRAY['salt', 'coconut', 'black sesame seeds', 'mustard seeds', 'curry leaves', 'white urad dal (split)', 'dry red chillies', 'tamarind', 'sunflower oil']::text[], '["To begin making Ellu Chutney (Sesame Seeds Chutney Recipe), soak tamarind in a very little water.Dry roast urad dal until lightly roasted and browned.", "Stir in the black sesame seeds, dry chillies, fresh grated coconutRoast for a few minutes.In a mixer grinder, add sesame seeds, tamarind with water, red chillies, urad dal & salt to taste.", "Grind it to a smooth, thick paste.", "Transfer the chutney to a serving bowl.In a tadka pan, heat oil on low flame and add mustard seeds and allow to splutter.", "Immediately add curry leaves and allow to crackle for 5 seconds or more.", "Pour this tempering on the chutney mix lightly and serve Ellu Chutney (Sesame Seeds Chutney Recipe) with your favorite idli / dosa recipe."]'::jsonb, 20, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Preethi_Kitchen_Appliances_Ellu_Sesame_Seed_Chutney_Thogayal_Video_recipe_5_Delicious_Chutneys_You_Can_Make_With_Turbo_Chop-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1354.Preethi_Kitchen_Appliances_Ellu_Sesame_Seed_Chutney_Thogayal_Video_recipe_5_Delicious_Chutneys_You_Can_Make_With_Turbo_Chop-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('एल्लु चटनी रेसिपी - Ellu Chutney Recipe', 'ellu-chutney-recipe', 'एल्लु चटनी रेसिपी एक बहुत ही प्रसिद्ध रेसिपी है जिसे दक्षिण भारत के घरो में बनाया जाता है. इसमें काले तिल का प्रयोग किया जाता है. यह एक आसान रेसिपी है और इसे आप अपने सुबह के नाश्ते के साथ भी परोस सकते है.', '["1/4 \u0915\u092a \u0915\u093e\u0932\u0947 \u0924\u093f\u0932", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0938\u095e\u0947\u0926 \u0909\u0930\u0926 \u0926\u093e\u0932", "1/4 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947", "5 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "\u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e , \u0925\u094b\u095c\u093e", "20 \u0917\u094d\u0930\u093e\u092e \u0907\u092e\u0932\u0940 , \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u092d\u093f\u0917\u094b \u0932\u0947", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "\u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e , \u0925\u094b\u095c\u0947"]'::jsonb, ARRAY['कप काले तिल', 'बड़ा चम्मच सफ़ेद उरद दाल', 'कप नारियल', 'सुखी लाल मिर्च', 'कढ़ी पत्ता', 'ग्राम इमली', 'नमक', 'तड़के के लिए', 'छोटा चम्मच तेल', 'छोटा चम्मच राइ']::text[], '["\u090f\u0932\u094d\u0932\u0941 \u091a\u091f\u0928\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0907\u092e\u0932\u0940 \u0915\u094b \u0925\u094b\u095c\u0947 \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u092d\u093f\u0917\u094b \u0932\u0947.\u0905\u092c \u0909\u0930\u0926 \u0926\u093e\u0932 \u0915\u094b \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u0938\u0947\u0915 \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0915\u093e\u0932\u0947 \u0924\u093f\u0932, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a, \u0915\u0938\u093e \u0939\u0941\u0906 \u0928\u093e\u0930\u093f\u092f\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 2\u00a0\u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0930\u094b\u0938\u094d\u091f \u0915\u0930 \u0932\u0947.\u00a0\u00a0\u0905\u092c \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0924\u093f\u0932, \u0907\u092e\u0932\u0940 \u092a\u093e\u0928\u0940 \u0915\u0947 \u0938\u093e\u0925, \u0909\u0930\u0926 \u0926\u093e\u0932, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947. \u0907\u0938 \u092a\u0947\u0938\u094d\u091f \u0915\u094b \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0928\u093f\u0915\u093e\u0932 \u0932\u0947.\u0905\u092c \u090f\u0915 \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907 \u0921\u093e\u0932\u0947\u00a0\u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947. \u0907\u0938\u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 5\u00a0\u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0907\u0938 \u0924\u095c\u0915\u0947 \u0915\u094b \u091a\u091f\u0928\u0940 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u090f\u0932\u094d\u0932\u0941 \u091a\u091f\u0928\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u0918\u0940 \u0930\u094b\u0938\u094d\u091f \u0921\u094b\u0938\u093e \u0914\u0930 \u091f\u092e\u093e\u091f\u0930 \u092a\u094d\u092f\u093e\u091c \u0938\u093e\u0902\u092c\u0930 \u0915\u0947 \u0938\u093e\u0925 \u0938\u0941\u092c\u0939 \u0915\u0947 \u0928\u093e\u0936\u094d\u0924\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 20, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Preethi_Kitchen_Appliances_Ellu_Sesame_Seed_Chutney_Thogayal_Video_recipe_5_Delicious_Chutneys_You_Can_Make_With_Turbo_Chop-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1355.Preethi_Kitchen_Appliances_Ellu_Sesame_Seed_Chutney_Thogayal_Video_recipe_5_Delicious_Chutneys_You_Can_Make_With_Turbo_Chop-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gorikayi Palya Recipe - Karnataka Style Gawar Phali Sabzi', 'gorikayi-palya-recipe-karnataka-style-gawar-phali-sabzi', 'Gorikayi Palya is a dry sabzi recipe prepared with cluster beans or gawar phali. This is an easy recipe with scraped fresh coconut and spices. This makes a great recipe for lunch box as well.', '["250 grams Gawar Phali (Kothavarangai / Cluster beans) , snapped to bite size", "1 teaspoon Coconut Oil", "1/4 teaspoon Mustard seeds (Rai/ Kadugu)", "2 sprig Curry leaves", "2 Dry Red Chillies", "1/4 cup Fresh coconut", "2 tablespoon Sesame seeds (Til seeds)", "4 cloves Garlic , peeled", "3 Dry Red Chillies", "10 grams Tamarind", "1 tablespoon Jaggery", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard seeds', 'coconut', 'jaggery', 'cloves garlic', 'curry leaves', 'dry red chillies', 'tamarind', 'coconut oil', 'sesame seeds (til seeds)', 'gawar phali (kothavarangai cluster beans) snapped']::text[], '["To begin making the\u00a0Gorikayi Palya Recipe (Karnataka Style Cluster Beans Sabzi), steam gawar phali or cluster beans (Gorikayi) in a vegetable steamer or in a pressure cooked, adding 1 tablespoon water and cook for two whistles.Once cooked, turn off the heat and release the pressure immediately, so the Gorikayi remains green.Blend all the ingredients mentioned in the \"To Grind\" section to a coarse paste including fresh coconut, sesame seeds, garlic, dry red chillies, tamarind, jaggery and salt without adding any water.Heat oil in a kadai with a little oil.", "Add mustard seeds and allow it to crackle.", "Add curry leaves and red chillies saute till crisp.", "Stir in the ground coconut mixture and the steamed Gorikayi and give it a stir to combine well.Check the salt and adjust accordingly.", "Once done, turn off the heat and serve.Make this\u00a0Gorikayi Palya\u00a0for lunch or dinner and serve along with\u00a0Thandu Keerai Sambar,\u00a0Steamed Rice\u00a0and\u00a0Elai Vadam."]'::jsonb, 35, 'Karnataka', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/19-Jan/Gorikayi_Palya_Recipe_Karnataka_Style_Cluster_Beans_sabzi-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1356.Gorikayi_Palya_Recipe_Karnataka_Style_Cluster_Beans_sabzi-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer Pyaz Paratha Recipe', 'paneer-pyaz-paratha-recipe', 'Paneer Pyaz Paratha Recipe is a favourite of every North Indian household.', '["3 cup Whole Wheat Flour", "2 cup Water , to knead", "1 tablespoon Oil", "Whole Wheat Flour , for dusting", "Salt , to taste", "1 cup Paneer (Homemade Cottage Cheese) , grated", "1/2 cup Onion , finely chopped", "2 Green Chillies , finely chopped", "Coriander (Dhania) Leaves , few, finely chopped", "1/2 tablespoon Coriander Powder (Dhania)", "1/2 tablespoon Red Chilli powder", "1/4 tablespoon Garam masala powder", "1/2 tablespoon Chaat Masala Powder", "Salt , to taste", "Ghee , for roasting"]'::jsonb, ARRAY['whole wheat flour', 'water', 'oil', 'salt', 'paneer', 'homemade cottage cheese', 'onion', 'reen chillies', 'coriander', 'dhania', 'coriander powder', 'red chilli powder', 'garam masala powder', 'chaat masala powder', 'ghee']::text[], '["To begin making the Paneer Pyaz Paratha Recipe, we will first make the dough.", "In a bowl, mix together wheat flour, salt and oil.", "Add water little at a time and prepare a soft dough just as we make the dough for chapatis.", "Grease your hands with oil and knead it well.", "Cover it and let it rest for some time.To make the stuffing for the Paneer Pyaz Paratha Recipe; in a mixing bowl, combine the grated paneer, chopped onions, finely chopped green chillies and fresh coriander.Now add all dry spices - salt, red chilli powder, garam masala, coriander powder, chaat masala and mix everything well.Now make even size ball out of paratha dough and roll out the ball into a small circle dusting wheat flour.Add some stuffing in the centre and gather all the corners and seal it well and press it lightly.Dust some wheat flour and roll out the sealed dough into a circle as we do for chapati dough.", "Don\u2019t apply too much pressure.", "Heat a tawa, on medium - high flame and put the rolled out Paneer Pyaz Paratha on it.", "Let it cook a little bit on one side.Flip the Paneer Pyaz Paratha\u00a0over to the other side and spread some ghee over the paratha which is half cooked.Flip it again, when the second side is half cooked and spread some ghee.Flip it again, do it couple of times till the Paneer Pyaz Paratha turns brown and is cooked well.Finally topped the Paneer Pyaz Paratha with butter and serve hot.Serve Paneer Pyaz Paratha Recipe along with\u00a0Aam Ka Achaar Recipe, and\u00a0Tomato Onion Tadka Raita Recipe\u00a0for a quick weekday breakfast."]'::jsonb, 45, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Paneer_Pyaz_Paratha_Recipe_24_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1357.Paneer_Pyaz_Paratha_Recipe_24_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Khamang Kakdi Recipe - Maharashtrian Cucumber Salad', 'khamang-kakdi-recipe-maharashtrian-cucumber-salad', 'Khamang Kakdi is a delicious Maharashtrian style side dish recipe where cucumber and yogurt is mixed and is tempered with curry leaves, green chillies and mustard seeds.', '["2 Cucumber , peeled and chopped", "1/2 cup Fresh coconut , grated", "Coriander (Dhania) Leaves , as required, chopped", "3 tablespoons Roasted Peanuts (Moongphali) , skin removed", "3 tablespoons Curd (Dahi / Yogurt)", "Salt , to taste", "1/4 teaspoon Oil , as required", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)", "1 Green Chilli , finely chopped", "1 sprig Curry leaves , roughly chopped"]'::jsonb, ARRAY['peanuts (moongphali) skin', 'salt', 'green chilli', 'coriander (dhania) leaves', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'curd', 'curry leaves', 'cucumber', 'sunflower oil']::text[], '["To begin making the Khamang Kakdi Recipe, firstly take a big bowl to mix the salad.Add cucumber, coconut, coriander leaves, salt to taste and mix everything well.", "Now add in the yogurt and mix it again so that the cucumber is well coated with the yogurt.", "Keep it aside.The next step is to temper the Khamang Kakdi.", "Heat oil in a tadka pan and add mustard seeds and asafoetida.", "Let it crackle for about 10 seconds.After 10 seconds, add green chillies, curry leaves and saute for another 15 seconds.", "Once done, add this tempering to the Khamang Kakdi and mix it well.At the end, sprinkle roasted peanuts over the Khamang Kakdi and give it a mix.", "The\u00a0Khamang Kakdi is ready to be served.Enjoy\u00a0Khamang Kakdi Recipe\u00a0along with\u00a0Maharashtrian Chawli Chi Usal\u00a0and\u00a0Steamed Rice\u00a0for a weekday meal."]'::jsonb, 12, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/pooja/khamang_Kakdi_an_Ayurvedic_Recipe_Maharastrian_Cucumber_Salad_20_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1358.khamang_Kakdi_an_Ayurvedic_Recipe_Maharastrian_Cucumber_Salad_20_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Malvani Anda Curry Recipe - Egg Curry With Spicy Malvani Masala', 'malvani-anda-curry-recipe-egg-curry-with-spicy-malvani-masala', 'Malvani Anda Curry Recipe is an Egg curry flavoured with added Spicy Malvani Masala. Malvani cuisine is known for its spicy, tart non vegetarian delicacies. Malvani masala is almost a core ingredient that is used in most recipes from that region of Maharashtra.', '["4 Whole Eggs , hard boiled", "1 Onion , thinly sliced", "1/2 cup Homemade tomato puree", "1 Green Chilli , slit", "1 tablespoon Ginger Garlic Paste", "1/4 cup Cashew nuts , soaked in warm water", "1/4 cup Fresh coconut , grated", "1 teaspoon Red Chilli powder", "2 teaspoons Coriander Powder (Dhania)", "2 teaspoons Malwani masala", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Cumin seeds (Jeera)", "1 Kokum (Malabar Tamarind)", "1 sprig Curry leaves", "1 tablespoon Oil", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'green chilli', 'coconut', 'kokum (malabar tamarind)', 'red chilli powder', 'ginger garlic paste', 'curry leaves', 'onion', 'cashew nuts water', 'cumin seeds (jeera)', 'malwani masala', 'coriander powder', 'eggs', 'turmeric powder', 'sunflower oil']::text[], '["To begin making Malvani Anda Curry Recipe, boil the eggs in a saucepan for 10-12 minutes, drain water, peel the eggs, halve them and keep the eggs aside.", "Heat a little oil in a kadai, add the sliced onions.", "On a medium heat, saute till the onions are caramelized.Once the onions are caramelized, grind it to a smooth paste along with soaked cashew nuts and fresh grated coconut using a mixer grinder and keep aside.Heat a tablespoon of oil in the same pan on a medium heat, add the cumin seeds and let it sizzle.Add the curry leaves and slit green chilli and let it splutter.Add the ginger garlic paste and cook until the raw smell goes away.", "This will take 2 to 3 minutes.Add the ground onion, cashew and coconut mix and cook for a minute.Now add the red chilli powder, coriander powder, turmeric powder, malvani masala and cook until the curry gravy leaves the sides of the pan and deep in color.Add the tomato puree and cook until the gravy is cooked well.Add a cup of water, kokum, season with salt and let the gravy simmer for about 10 minutes on low heat.Now, add the slit boiled eggs into the gravy, check for salt and spices, adjust if required.", "Simmer for another 5 minutes and switch off the heat.Serve Malvani Anda Curry Recipe (Egg Curry With Spicy Malvani Masala) along with Cauliflower & Cucumber Raita Recipe and Phulkas or Sweet Potato Thepla for a hearty weeknight dinner."]'::jsonb, 30, 'Malvani', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Malvani_Anda_Curry_Recipe_Egg_Curry_With_Spicy_Malvani_Masala-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1359.Malvani_Anda_Curry_Recipe_Egg_Curry_With_Spicy_Malvani_Masala-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('मालवानी अंडा करी रेसिपी - Malvani Anda Curry Recipe', 'malvani-anda-curry-recipe', 'मालवानी अंडा करी रेसिपी, बनाने में आसान और स्वाद से भरपूर, यह अंडा करी हर मालवणी घर में बनाई जाती है. इसमें मालवानी मसाले का प्रयोग किया जाता है जो इस करी को अलग बनाता है.', '["4 \u0905\u0902\u0921\u0947 , \u0909\u092c\u093e\u0932 \u0932\u0947", "1 \u092a\u094d\u092f\u093e\u091c , \u092a\u0924\u0932\u093e \u0914\u0930 \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "1/2 \u0915\u092a \u091f\u092e\u093e\u091f\u0930 \u092a\u094d\u092f\u0942\u0930\u0940", "1 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0915\u093e\u091f \u0932\u0947", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0905\u0926\u0930\u0915 \u0932\u0939\u0938\u0941\u0928 \u0915\u093e \u092a\u0947\u0938\u094d\u091f", "1/4 \u0915\u092a \u0915\u093e\u091c\u0942 , \u0917\u0930\u092e \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u092d\u093f\u0917\u094b \u0926\u0947", "1/4 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u092e\u093e\u0932\u0935\u093e\u0928\u0940 \u092e\u0938\u093e\u0932\u093e", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1 \u0915\u094b\u0915\u092e", "1 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['अंडे', 'प्याज', 'कप टमाटर प्यूरी', 'हरी मिर्च', 'बड़ा चम्मच अदरक लहसुन का पेस्ट', 'कप काजू', 'कप नारियल', 'छोटा चम्मच लाल मिर्च पाउडर', 'छोटे चम्मच धनिया पाउडर', 'छोटे चम्मच मालवानी मसाला', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच जीरा', 'कोकम', 'टहनी कढ़ी पत्ता', 'बड़ा चम्मच तेल', 'नमक']::text[], '["\u092e\u093e\u0932\u0935\u093e\u0928\u0940 \u0905\u0902\u0921\u093e \u0915\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u0915\u094b \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0938\u0949\u0938\u092a\u0948\u0928 \u092e\u0947\u0902 \u092a\u093e\u0928\u0940 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0905\u0902\u0921\u0947 \u0921\u093e\u0932\u0947 \u0914\u0930 15\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u091c\u092c \u092c\u093e\u0939\u0930 \u0915\u0947 \u091b\u093f\u0932\u0915\u0947 \u092a\u0930 \u0915\u094d\u0930\u0948\u0915 \u0906\u0928\u0947 \u0932\u0917\u0947 \u0924\u094b \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947.\u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0926\u0947 \u0914\u0930 \u092b\u093f\u0930 \u0909\u0938\u0915\u093e \u091b\u093f\u0932\u0915\u093e \u0928\u093f\u0915\u093e\u0932 \u0932\u0947. \u091b\u093f\u0932\u0915\u093e \u0928\u093f\u0915\u0932\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0906\u0927\u093e \u0915\u0930\u0947\u0902 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u092d\u0942\u0930\u0947 \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947.\u00a0\u0905\u092c \u092d\u093f\u0917\u094b\u092f\u0947 \u0939\u0941\u090f \u0915\u093e\u091c\u0942, \u0928\u093e\u0930\u093f\u092f\u0932 \u0914\u0930 \u092a\u094d\u092f\u093e\u091c\u00a0\u0915\u094b \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u091c\u0940\u0930\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 10\u00a0\u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0905\u0926\u0930\u0915 \u0932\u0939\u0938\u0941 \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 2\u00a0\u092e\u093f\u0928\u091f \u0915\u0947\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0 \u0907\u0938\u0915\u0947 \u092c\u093e\u0926 \u0915\u093e\u091c\u0942 \u092a\u094d\u092f\u093e\u091c \u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 1\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.1 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u092e\u093e\u0932\u0935\u093e\u0928\u0940 \u092e\u0938\u093e\u0932\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 4\u00a0\u0938\u0947 5\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930 \u092a\u094d\u092f\u0942\u0930\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 4\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 1 \u0915\u092a \u092a\u093e\u0928\u0940, \u0915\u094b\u0915\u092e, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 10\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a010 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0905\u0902\u0921\u0947 \u0921\u093e\u0932\u0947 \u0914\u0930 5\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u092e\u093e\u0932\u0935\u093e\u0928\u0940 \u0905\u0902\u0921\u093e \u0915\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u0915\u0947\u0930\u0932\u093e \u092a\u0930\u094b\u091f\u093e \u0914\u0930\u00a0\u092c\u0942\u0902\u0926\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 30, 'Malvani', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Malvani_Anda_Curry_Recipe_Egg_Curry_With_Spicy_Malvani_Masala-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1360.Malvani_Anda_Curry_Recipe_Egg_Curry_With_Spicy_Malvani_Masala-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dhaba Style Egg Curry Recipe in Electric Pressure Cooker', 'dhaba-style-egg-curry-recipe-in-electric-pressure-cooker', 'The taste of Dhaba food is phenomenal and we usually find these dhabas on highways. They cook some amazing dishes in traditional style which enhances the flavour of the dish. Dhaba Style Egg Curry is one such recipe which is spicy, tasty and full of flavours.', '["4 Whole Eggs , hard boiled", "1 tablespoon Ghee", "1/2 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon Asafoetida (hing)", "3 Cloves (Laung)", "1 Bay leaf (tej patta)", "1 Black cardamom (Badi Elaichi)", "2 Cardamom (Elaichi) Pods/Seeds", "4 Dry Red Chillies", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "1 Onion , finely chopped", "1 cup Homemade tomato puree", "2 tablespoons Curd (Dahi / Yogurt)", "1 teaspoon Kashmiri Red Chilli Powder", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "Salt , as needed", "Water , as needed", "Coriander (Dhania) Leaves , few sprigs, finely chopped"]'::jsonb, ARRAY['tomato', 'kashmiri red chilli powder', 'asafoetida (hing)', 'cloves garlic', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'black cardamom (badi elaichi)', 'salt', 'cardamom (elaichi) podsseeds', 'dry red chillies', 'mustard seeds', 'water', 'curd', 'eggs', 'ginger', 'coriander (dhania) leaves', 'ghee', 'bay leaf (tej patta)', 'coriander powder', 'cloves (laung)']::text[], '["To begin making the Dhaba Style Egg Curry, prep all the ingredients and keep them ready.Boil the eggs and keep them ready as well.Place the mode of the pressure cooker into the saute mode.Heat ghee into the electric pressure cooker; add cumin seeds, mustard seeds, hing, bay leaf, red chilli, black cardamom, green cardamom, cloves until you can smell the aromas coming through.Add the finely chopped onion, ginger, garlic and cook them till they turn soft and translucent.", "After a minute, add all the dry masalas including kashmiri red chilli powder, turmeric powder, coriander powder and the required salt.", "Let it cook for about 3 to 4 minutes.Next, add the tomato puree and cook for about 5 to 6 minutes.", "After 5 to 6 minutes, add the curd and the required water.Mix properly, cover the electric pressure cooker.Set the mode to gravy mode and allow the pressure cooker to do cook until turns itself on to the keep warm mode.Once done, stir in the coriander leaves, check the salt and adjust according to taste.Once done, transfer the Dhaba Egg Curry into a serving bowl and serve hot.Dhaba Style Egg Curry is usually served on the road side dhabas in North Indian with\u00a0Bajra Ki Roti\u00a0or\u00a0Makki Ki Roti."]'::jsonb, 90, 'North Indian', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Dhaba_Style_Egg_Curry_Recipe-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1361.Dhaba_Style_Egg_Curry_Recipe-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('ढाबा स्टाइल एग करी रेसिपी - Dhaba Style Egg Curry Recipe', 'dhaba-style-egg-curry-recipe', 'ढाबे के खाने की कुछ अलग ही बात होती है. तीखा, मसालेदार और देसी घी में बना हुआ, यह खाना सबको पसंद आता है. इसलिए आज हम यहाँ ढाबा स्टाइल एग करी की रेसिपी लेकर आए है जिसे आप अपने घर पर भी बना सकते है. यह स्वादिष्ट होने के साथ साथ बाहर सरल भी है.', '["4 \u0905\u0902\u0921\u0947 , \u0909\u092c\u093e\u0932 \u0932\u0947", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0918\u0940", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0940\u0902\u0917", "3 \u0932\u0949\u0928\u094d\u0917", "1 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e", "1 \u092c\u095c\u0940 \u0907\u0932\u093e\u0907\u091a\u0940", "2 \u0907\u0932\u093e\u0907\u091a\u0940", "4 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "4 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u092a\u094d\u092f\u093e\u091c , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u0915\u092a \u091f\u092e\u093e\u091f\u0930 \u092a\u094d\u092f\u0942\u0930\u0940", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0926\u0939\u0940", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0915\u0936\u094d\u092e\u0940\u0930\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "\u092a\u093e\u0928\u0940 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u0925\u094b\u095c\u093e, \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f\u093e \u0939\u0941\u0906"]'::jsonb, ARRAY['अंडे', 'बड़ा चम्मच घी', 'छोटा चम्मच जीरा', 'छोटा चम्मच राइ', 'छोटा चम्मच हींग', 'लॉन्ग', 'तेज पत्ता', 'बड़ी इलाइची', 'इलाइची', 'सुखी लाल मिर्च', 'इंच अदरक', 'कली लहसुन', 'प्याज', 'कप टमाटर प्यूरी', 'बड़े चम्मच दही', 'छोटा चम्मच कश्मीरी लाल मिर्च पाउडर', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच धनिया पाउडर', 'नमक', 'पानी', 'हरा धनिया']::text[], '["\u0922\u093e\u092c\u093e \u0938\u094d\u091f\u093e\u0907\u0932 \u090f\u0917 \u0915\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0938\u093e\u0930\u0940\u00a0\u0938\u093e\u092e\u0917\u094d\u0930\u0940 \u0924\u0948\u092f\u093e\u0930 \u0915\u0930 \u0932\u0947. \u0905\u0902\u0921\u094b \u0915\u094b \u0909\u092c\u093e\u0932 \u0915\u0947 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u0905\u092c \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u091c\u0940\u0930\u093e, \u0930\u093e\u0907, \u0939\u0940\u0902\u0917, \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a, \u092c\u095c\u0940 \u0907\u0932\u093e\u0907\u091a\u0940, \u0907\u0932\u093e\u0907\u091a\u0940, \u0932\u0949\u0928\u094d\u0917 \u0921\u093e\u0932\u0947 \u0914\u0930 30 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c, \u0905\u0926\u0930\u0915, \u0932\u0939\u0938\u0941\u0928 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0915\u0936\u094d\u092e\u0940\u0930\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 3 \u0938\u0947 4\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a04 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930 \u0915\u0940 \u092a\u094d\u092f\u0942\u0930\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 5\u00a0\u0938\u0947 6 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0907\u0938\u0915\u0947 \u092c\u093e\u0926 \u0926\u0939\u0940, \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0927\u0940\u092e\u0940 \u0906\u0902\u091a \u092a\u0930 \u092a\u0915\u093e \u0932\u0947.\u0915\u0941\u0915\u0930 \u0915\u094b \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 2 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0915\u0941\u0915\u0930 \u0915\u093e \u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947. \u0915\u0941\u0915\u0930 \u0916\u094b\u0932\u0947, \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u0905\u0902\u0921\u094b \u0915\u094b \u0906\u0927\u093e \u0915\u0930\u0947\u0902 \u0914\u0930 \u0915\u0930\u0940 \u092e\u0947\u0902 \u0921\u093e\u0932\u0915\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0922\u093e\u092c\u093e \u0938\u094d\u091f\u093e\u0907\u0932 \u090f\u0917 \u0915\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u092c\u0942\u0902\u0926\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u0914\u0930\u00a0\u0924\u0935\u093e \u092a\u0930\u093e\u0920\u093e\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 90, 'North Indian', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Dhaba_Style_Egg_Curry_Recipe-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1362.Dhaba_Style_Egg_Curry_Recipe-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Jhinge Narkol Chenchki Recipe - Stir Fried Ridge Gourd With Coconut', 'bengali-jhinge-narkol-chenchki-recipe-stir-fried-ridge-gourd-with-coconut', 'The Bengali Jhinge Narkol Chenchki Recipe is a traditional Bengali dry vegetable sabzi made from ridge gourd that is tossed in a delicious blend of roasted masalas, mustard paste and coconut. Jhinge (Ridge gourd) is very common among Bengalis. Jhinge is used in fish curries and in dals as well.', '["2 Ridge Gourd (Turai/ Peerkangai) , cut into dices", "1/4 cup Fresh coconut , grated", "4 Green Chillies , spit lengthwise", "1 teaspoon Kala jeera", "1 Dry Red Chilli", "1 Bay leaf (tej patta)", "2 teaspoon Sugar", "2 tablespoon Mustard oil", "2 tablespoon Mustard seeds (Rai/ Kadugu) , ground into a smooth paste", "2 teaspoon Cumin powder (Jeera)", "1 teaspoon Turmeric powder (Haldi)", "Salt , to taste"]'::jsonb, ARRAY['ridge gourd', 'turai/ peerkangai', 'fresh coconut', 'reen chillies', 'kala jeera', 'dry red chilli', 'bay leaf', 'tej patta', 'sugar', 'mustard oil', 'mustard seeds', 'rai/ kadugu', 'cumin powder', 'jeera', 'turmeric powder', 'haldi', 'salt']::text[], '["To begin making the Bengali Jhinge Narkol Chenchki Recipe, first prepare all the ingredients and keep them ready to cook.Heat oil in a kadai over medium heat; add grated coconut and roast until lightly browned.", "Keep aside.Make a paste of the mustard by grinding it with a little water.", "Pestle and Mortar works well for grinding in small quantities.", "In the heat mustard oil to smoking point, add kala jeera, bay leaf and dried red chilli.", "After chilli is well roasted, add in jhinge pieces.", "Stir fry jhinge pieces in low flame until it is soft and cooked through, \u00a0Once it is soft stir in the salt, turmeric powder, sugar, green chilies and cumin powder.Stir fry all ingredients in low flame, jhinge will release water and hence there is no need to add any additional water.", "After jhinge is well cooked add roasted coconut, the mustard seed paste and stir to cook for another 3 to 4 minutes.Once done, check the salt and seasonings and adjust to suit your taste.Serve the Bengali Jhinge Narkol Chenchki along with hot\u00a0Steamed Rice,\u00a0Cholar Dal\u00a0and\u00a0Aloo Bhaja\u00a0for a warm comforting weekend lunch."]'::jsonb, 45, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/10-may/Bengali_Jhinge_Narkol_Chenchki_Stir_fried_Ridge_Gourd_with_Coconut-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1363.Bengali_Jhinge_Narkol_Chenchki_Stir_fried_Ridge_Gourd_with_Coconut-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spicy Mullangi Thogayal Recipe (Radish Chutney)', 'spicy-mullangi-thogayal-recipe-radish-chutney', 'Radish is a high fibre root vegetable. Regular intake of radish help one remain younger and healthier. It protects us from seasonal cold and cough that is prevalent in this monsoon season. The Mullangi Thogayal is a spicy chutney that tastes great when mixed with rice and ghee. It can be a great side dish for rotis or phulkas. Radish is grated and is sautéed along with ginger, tamarind and chillies. They are then coarsely ground along with roasted lentils. The pachadi is a quick gluten free and vegan recipe.', '["1 cup Mooli/ Mullangi (Radish) , grated", "2 teaspoons Black Urad Dal (Split)", "1/4 cup Fresh coconut", "20 grams Tamarind , soaked in water", "1/4 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Asafoetida (hing)", "Salt , to taste", "2 teaspoons Sesame (Gingelly) Oil", "1 teaspoon Black Urad Dal (Split)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 cup Curry leaves"]'::jsonb, ARRAY['salt', 'coconut', 'asafoetida (hing)', 'mustard seeds', 'sesame (gingelly) oil', 'black urad dal (split)', 'curry leaves', 'mooli mullangi (radish)', 'tamarind', 'turmeric powder']::text[], '["To begin making the Mullangi Thogayal recipe, heat a pan over medium heat.", "Add the Urad dal and red chillies and roast until dal is lightly browned.", "Once roasted, add the grated radish, salt, coconut, turmeric powder and asafoetida.", "Saute until the radish (mullangi) is softened.", "Once softened, add the cooked mullangi thogayal ingredients into the turbo chop along with the soaked tamarind and make smooth paste.Add a little water if required while grinding.", "Once done, transfer to a serving bowl.For the tadka, heat oil over medium heat; add the mustard seeds and urad dal and allow the dal to roast and turn golden brown.", "Stir in the curry leaves and pour the tadka over the Mullangi Thogayal.", "Serve Mullangi Thogayal along with\u00a0Tomato Onion Sambar,\u00a0Elai Vadam\u00a0and Steamed Rice for a wholesome weekday meal."]'::jsonb, 54, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Preethi_Kitchen_Appliances_Mulangi_Mooli_Radish_Chutney_Thogayal_Video_recipe_5_Delicious_Chutneys_You_Can_Make_With_Turbo_Chop-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1364.Preethi_Kitchen_Appliances_Mulangi_Mooli_Radish_Chutney_Thogayal_Video_recipe_5_Delicious_Chutneys_You_Can_Make_With_Turbo_Chop-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('मुलांगी थोगयल रेसिपी -  Mullangi Thogayal Recipe', 'mullangi-thogayal-recipe', 'मूली उन सब्ज़िओ में से एक है जिसमे फाइबर की मात्रा अधिक होती है, इसलिए यह आपकी सेहत के लिए अच्छी भी मानी जाती है. इसलिए यहाँ हमने मूली से चटनी बनाई है जिसे दक्षिण भारत में मुलांगी थोगयल कहा जाता है. यह एक तीखी चटनी है जिसे दक्षिण भारत में चावल और घी के साथ कहाया जाता है.', '["1 \u0915\u092a \u092e\u0942\u0932\u0940 , \u0915\u0938 \u0932\u0947", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0915\u093e\u0932\u0940 \u0909\u0930\u0926 \u0926\u093e\u0932 (\u0938\u094d\u092a\u094d\u0932\u093f\u091f)", "1/4 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932", "20 \u0917\u094d\u0930\u093e\u092e \u0907\u092e\u0932\u0940 , \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u092d\u093f\u0917\u094b \u0926\u0947", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0940\u0902\u0917", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u093f\u0932 \u0915\u093e \u0924\u0947\u0932", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0915\u093e\u0932\u0940 \u0909\u0930\u0926 \u0926\u093e\u0932 (\u0938\u094d\u092a\u094d\u0932\u093f\u091f)", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "1/4 \u0915\u092a \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e"]'::jsonb, ARRAY['कप मूली', 'छोटे चम्मच काली उरद दाल', 'स्प्लिट', 'कप नारियल', 'ग्राम इमली', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच हींग', 'नमक', 'तड़के के लिए', 'छोटे चम्मच तिल का तेल', 'छोटा चम्मच काली उरद दाल', 'छोटा चम्मच राइ', 'कप कढ़ी पत्ता']::text[], '["\u092e\u0941\u0932\u093e\u0902\u0917\u0940 \u0925\u094b\u0917\u092f\u0932 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0915\u095d\u093e\u0908 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0909\u0930\u0926 \u0926\u093e\u0932, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 \u0939\u0932\u094d\u0915\u093e \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0915\u0938\u0940 \u0939\u0941\u0908 \u092e\u0942\u0932\u0940, \u0928\u093e\u0930\u093f\u092f\u0932, \u0928\u092e\u0915, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930 \u0914\u0930 \u0939\u0940\u0902\u0917 \u0921\u093e\u0932\u0947\u0964 \u092e\u0942\u0932\u0940 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0926\u0947.\u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u092e\u0942\u0932\u0940 \u0915\u0947 \u092e\u093f\u0936\u094d\u0930\u0923 \u0915\u094b \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0907\u092e\u0932\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0940\u0938 \u0932\u0947. \u0905\u0917\u0930 \u091c\u0930\u0941\u0930\u0924 \u0939\u094b \u0924\u094b \u092a\u093f\u0938\u094d\u091f\u0947 \u0938\u092e\u092f \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932 \u0938\u0915\u0924\u0947 \u0939\u0948. \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0928\u093f\u0915\u093e\u0932 \u0932\u0947.\u0905\u092c \u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u0909\u0930\u0926 \u0926\u093e\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0926\u093e\u0932 \u0915\u094b \u0938\u0941\u0928\u0939\u0930 \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 10\u00a0\u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0907\u0938 \u0924\u095c\u0915\u0947 \u0915\u094b \u091a\u091f\u0928\u0940 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092e\u0941\u0932\u093e\u0902\u0917\u0940 \u0925\u094b\u0917\u092f\u0932 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u091a\u093e\u0909 \u091a\u093e\u0909\u00a0\u0938\u093e\u0902\u092c\u0930,\u00a0\u091a\u093e\u0935\u0932\u00a0\u0914\u0930 \u092a\u093e\u092a\u095c \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 54, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Preethi_Kitchen_Appliances_Mulangi_Mooli_Radish_Chutney_Thogayal_Video_recipe_5_Delicious_Chutneys_You_Can_Make_With_Turbo_Chop-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1365.Preethi_Kitchen_Appliances_Mulangi_Mooli_Radish_Chutney_Thogayal_Video_recipe_5_Delicious_Chutneys_You_Can_Make_With_Turbo_Chop-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sobji Diye Bhaja Muger Dal Recipe - Bengali Style Moong Dal with Winter Vegetables', 'sobji-diye-bhaja-muger-dal-recipe-bengali-style-moong-dal-with-winter-vegetables', 'The Sobji Diye Bhaja Muger Dal is delicately flavored with ghee and cumin to let the aroma of dry roasted yellow mung shine through. In winter vegetables are added to make it more nutritious. Dal or lentil is the second important protein for Bengalis after fish. They need to have a ladleful of any lightly flavored lentil dish for their meal everyday. In a Bengali style of eating, Dal is eaten as a second or third course with some fritter or stir fries.', '["3/4 cup Yellow Moong Dal (Split)", "1 teaspoon Turmeric powder (Haldi)", "1 cup Cauliflower (gobi) , cut into florets", "2 tablespoons Green peas (Matar) , steamed", "1/4 Green beans (French Beans) , cut in 1", "1/4 cup Kaddu (Parangikai/ Pumpkin) , diced", "1 inch Ginger , grated", "1/2 teaspoon Cumin seeds (Jeera)", "1 Bay leaf (tej patta)", "1/2 inch Cinnamon Stick (Dalchini)", "2 Cloves (Laung)", "2 Cardamom (Elaichi) Pods/Seeds", "2 Dry Red Chillies", "1 teaspoon Sugar", "1 tablespoon Ghee", "Salt , to taste"]'::jsonb, ARRAY['yellow moong dal', 'split', 'turmeric powder', 'haldi', 'cauliflower', 'gobi', 's green peas', 'matar', 'reen beans', 'french beans', 'kaddu', 'parangikai/ pumpkin', 'ginger', 'cumin seeds', 'jeera', 'bay leaf', 'tej patta', 'cinnamon stick', 'dalchini', 'laung', 'cardamom', 'elaichi', 'dry red chillies', 'sugar', 'ghee', 'salt']::text[], '["To begin making the Sobji Diye Bhaja Muger Dal Recipe, we will first make the spice powder.In a pestle and mortar, make a powder of the cinnamon, cloves and cardamom and keep aside.Next dry roast the moong dal in a heavy bottomed pan.", "It will take almost 8-10 minutes for them to roast beautifully.", "Keep stirring at regular interval.", "Once this is done wash the dal 2-3 times and then add 2-1/2 cups of water a pinch of turmeric.", "Cover and let it cook on medium till the grains are almost cooked.While this the dal is getting cooked, we will proceed to cook the vegetables.In a wok or a kadai, heat a teaspoon of oil lightly stir fry the cauliflower florets and beans with a pinch of salt and turmeric until it is just about cooked.", "Take care not to cook it too soft.", "Once done, stir in the spice powder mix and turn off the heat.Once the dal is almost cooked add the stir fried vegetables along with pumpkin and green peas to the dal.", "Add salt as per taste.", "Let all the vegetables get cooked along with the dal.", "Once done turn off the heat.", "Adjust the consistency of the dal by adding a little water if required.The final step is to make the seasoning for the dal.", "Heat ghee in a small tadka pan;\u00a0add cumin, bay leaves, dry red chilli once they start to splutter add the the ginger.", "Saute on medium for a few seconds and then pour the seasoning over the vegetable dal.", "Stir in the sugar, check the salt and cover the pan for the flavours to mingle and simmer the dal for a couple of more minutes.Once done, turn off the heat and serve.Serve the\u00a0Sobji Diye Bhaja Muger Dal along with warm Steamed Rice, Papad and\u00a0Aloo Parval\u00a0for lunch or dinner."]'::jsonb, 50, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/19-Jan/Sobji_Diye_Bhaja_Muger_Dal_Recipe_Bengali_Style_Moong_Dal_with_Winter_Vegetables-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1366.Sobji_Diye_Bhaja_Muger_Dal_Recipe_Bengali_Style_Moong_Dal_with_Winter_Vegetables-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('सोबजी दीए भाजा मुगेर दाल रेसिपी - Sobji Diye Bhaja Muger Dal Recipe', 'sobji-diye-bhaja-muger-dal-recipe', 'दाल एक ऐसी डिश है जिसे भारत के हर घर में बनाया जाता है और इसे रोज के खाने में भी मिलाया जाता है क्यूंकि इसमें प्रोटीन की मात्रा बहुत अधिक होती है. आज हम यहाँ बंगाली स्टाइल दाल बना रहे है जिसे आप किसी भी सब्ज़ी और फुल्के के साथ परोस सकते है.', '["3/4 \u0915\u092a \u092a\u093f\u0932\u0940 \u092e\u0942\u0902\u0917 \u0926\u093e\u0932", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u0915\u092a \u0917\u094b\u092d\u0940 , \u0915\u093e\u091f \u0932\u0947", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0939\u0930\u0947 \u092e\u091f\u0930 , \u092d\u093e\u092a \u0932\u0947", "1/4 \u0939\u0930\u093e \u092c\u0940\u0928\u094d\u0938 , \u0915\u093e\u091f \u0932\u0947", "1/4 \u0915\u092a \u0915\u0926\u094d\u0926\u0942 , \u091b\u0940\u0932 \u0915\u0930 \u0915\u093e\u091f \u0932\u0947", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u0915\u0938 \u0932\u0947", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e", "1/2 \u0907\u0902\u091a \u0926\u093e\u0932\u091a\u0940\u0928\u0940", "2 \u0932\u0949\u0928\u094d\u0917", "2 \u0907\u0932\u093e\u0907\u091a\u0940", "2 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0936\u0915\u094d\u0915\u0930", "1 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0918\u0940", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['कप पिली मूंग दाल', 'छोटा चम्मच हल्दी पाउडर', 'कप गोभी', 'बड़े चम्मच हरे मटर', 'हरा बीन्स', 'कप कद्दू', 'इंच अदरक', 'छोटा चम्मच जीरा', 'तेज पत्ता', 'इंच दालचीनी', 'लॉन्ग', 'इलाइची', 'सुखी लाल मिर्च', 'छोटा चम्मच शक्कर', 'बड़े चम्मच घी', 'नमक']::text[], '["\u0938\u094b\u092c\u091c\u0940 \u0926\u0940\u090f \u092d\u093e\u091c\u093e \u092e\u0941\u0917\u0947\u0930 \u0926\u093e\u0932 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0939\u092e \u0938\u094d\u092a\u093e\u0907\u0938 \u092a\u093e\u0909\u0921\u0930 \u092c\u0928\u093e \u0932\u0947\u0902\u0917\u0947\u0964\u00a0\u090f\u0915 \u0939\u092e\u0928\u0926\u0938\u094d\u0924\u0947 \u092e\u0947\u0902 \u0926\u093e\u0932\u091a\u0940\u0928\u0940, \u0932\u0949\u0928\u094d\u0917, \u0907\u0932\u093e\u0907\u091a\u0940 \u0915\u094b \u092a\u0940\u0938 \u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u092e\u0942\u0902\u0917 \u0926\u093e\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 8\u00a0\u0938\u0947 10 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0930\u094b\u0938\u094d\u091f \u0915\u0930 \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0926\u093e\u0932 \u0915\u094b \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0926\u0947.\u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0926\u093e\u0932 \u0915\u094b \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u0927\u094b \u0932\u0947. \u0905\u092c \u0907\u0938\u0947 \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930 \u092a\u093e\u0928\u0940 \u0914\u0930 \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930 \u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947 \u0914\u0930 2\u00a0\u0938\u0947 3\u00a0\u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947 \u0914\u0930 \u0915\u0941\u0915\u0930 \u0916\u094b\u0932 \u0932\u0947.\u00a0\u0915\u095d\u093e\u0908 \u0915\u094b \u0932\u0947 \u0914\u0930 \u0909\u0938\u092e\u0947 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0917\u094b\u092d\u0940, \u0939\u0930\u093e \u092c\u0940\u0928\u094d\u0938,\u00a0\u0925\u094b\u095c\u093e \u0928\u092e\u0915, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0938\u092c\u094d\u095b\u093f\u0913\u00a0\u0915\u0947 \u0928\u0930\u092e \u0939\u094b \u091c\u093e\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u092a\u093f\u0938\u093e \u0939\u0941\u0906 \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947.\u00a0\u092f\u0939 \u0917\u094b\u092d\u0940 \u0915\u093e \u092e\u093f\u0936\u094d\u0930\u0923 \u0915\u0926\u094d\u0926\u0942 \u0914\u0930 \u0939\u0930\u0947 \u092e\u091f\u0930 \u0915\u0947 \u0938\u093e\u0925 \u0926\u093e\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 3 \u0938\u0947 4\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f \u090f\u0915 \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u091c\u0940\u0930\u093e, \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 \u091c\u0940\u0930\u0947 \u0915\u094b \u0924\u095c\u0915\u0928\u0947 \u0926\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0905\u0926\u0930\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 20\u00a0\u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0907\u0938 \u0924\u095c\u0915\u0947 \u0915\u094b \u0926\u093e\u0932 \u092e\u0947\u0902 \u0936\u0915\u094d\u0915\u0930 \u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u0926\u093e\u0932 \u0915\u094b 2\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0914\u0930 \u092a\u0915\u093e \u0932\u0947.\u00a0 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0938\u094b\u092c\u091c\u0940 \u0926\u0940\u090f \u092d\u093e\u091c\u093e \u092e\u0941\u0917\u0947\u0930 \u0926\u093e\u0932 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0906\u0932\u0942 \u092a\u0930\u0935\u0932 \u0938\u092c\u094d\u095b\u0940,\u00a0\u092b\u0941\u0932\u094d\u0915\u093e\u00a0\u0914\u0930\u00a0\u091a\u093e\u0935\u0932\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 50, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/19-Jan/Sobji_Diye_Bhaja_Muger_Dal_Recipe_Bengali_Style_Moong_Dal_with_Winter_Vegetables-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1367.Sobji_Diye_Bhaja_Muger_Dal_Recipe_Bengali_Style_Moong_Dal_with_Winter_Vegetables-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('करेला कढ़ी रेसिपी - Karela Kadhi Recipe', 'karela-kadhi-recipe-2', 'कढ़ी, उत्तर भारतीय डिश है जिसे हर घर में बनाया जाता है. यह गर्मी और सर्दी दोनों में बनाई जाती है. ज्यादातर लोग साधारण कढ़ी बनाते है लेकिन यहाँ हमने इस कढ़ी में करेले का भी प्रयोग किया है. अलग अलग राज्यों में इसे अलग तरह से बनाया जाता है. कढ़ी को बनाने के लिए बेसन और दही को मिलकर इसमें तड़का दिया जाता है.', '["1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u092c\u0947\u0938\u0928", "1 \u0915\u092a \u0926\u0939\u0940", "1-1/2 \u0915\u092a \u092a\u093e\u0928\u0940", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "2 \u0915\u0930\u0947\u0932\u093e , \u091b\u093f\u0932\u0915\u093e \u0928\u093f\u0915\u093e\u0932 \u0915\u0947 \u0915\u093e\u091f \u0932\u0947", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "1 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "1/2 \u092a\u094d\u092f\u093e\u091c , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "3 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947", "1/2 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u0939\u0938\u0941\u0928 , \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947"]'::jsonb, ARRAY['छोटा चम्मच बेसन', 'कप दही', 'कप पानी', 'नमक', 'करेला', 'छोटा चम्मच जीरा', 'छोटा चम्मच राइ', 'टहनी कढ़ी पत्ता', 'प्याज', 'हरी मिर्च', 'इंच अदरक', 'छोटा चम्मच लहसुन']::text[], '["\u0915\u0930\u0947\u0932\u093e \u0915\u095d\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0926\u0939\u0940, \u092a\u093e\u0928\u0940 , \u092c\u0947\u0938\u0928 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u0938\u0947 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092b\u0947\u091f \u0932\u0947. \u0927\u094d\u092f\u093e\u0928 \u0930\u0939\u0947 \u0915\u094b\u0908 \u0917\u093e\u0920\u0947 \u0928 \u0930\u0939 \u091c\u093e\u090f. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0915\u0930\u0947\u0932\u093e \u0915\u094b \u0915\u093e\u091f \u0915\u0930 \u0909\u0938\u0947 \u0928\u092e\u0915 \u0935\u093e\u0932\u0947 \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u092d\u093f\u0917\u094b \u0926\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u091c\u0940\u0930\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u0921\u0915\u0928\u0947 \u0926\u0947. \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u092a\u094d\u092f\u093e\u095b \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947\u00a0\u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0932\u0939\u0938\u0941\u0928, \u0905\u0926\u0930\u0915 \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0915\u0930\u0947\u0932\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 5 \u0938\u0947 7 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0928\u092e\u0915 \u0914\u0930 \u092c\u0947\u0938\u0928 \u0926\u0939\u0940 \u0915\u093e \u092e\u093f\u0936\u094d\u0930\u0923 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u0927\u0940\u092e\u0940 \u0906\u0902\u091a \u092a\u0930 10\u00a0\u0938\u0947 12 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0909\u092c\u0932\u0928\u0947 \u0926\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0915\u0930\u0947\u0932\u093e \u0915\u095d\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u091c\u0940\u0930\u093e \u0930\u093e\u0907\u0938,\u00a0\u092b\u0941\u0932\u094d\u0915\u093e\u00a0\u0914\u0930\u00a0\u092d\u0930\u0935\u093e \u092c\u0947\u0938\u0928 \u092e\u093f\u0930\u094d\u091a\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 30, 'Rajasthani', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/jyothir/Karela_Kadhi.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1368.Karela_Kadhi.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pudina Lehsun Laccha Paratha Recipe - Mint Garlic Layered Paratha', 'pudina-lehsun-laccha-paratha-recipe-mint-garlic-layered-paratha', 'Pudina Lehsun Laccha Paratha is a wonderful twist to the classic Laccha paratha recipe where the flour is combined along with fresh mint leaves chopped garlic and green chillies adding to the the twist of taste.', '["2 cups Whole Wheat Flour", "1/2 cup Milk", "Salt , to taste", "2 tablespoons Oil", "10 cloves Garlic , finely chopped", "2 Green Chillies , finely chopped", "1/4 cup Mint Leaves (Pudina) , finely chopped", "Oil , as required for making paratha"]'::jsonb, ARRAY['s whole wheat flour', 'milk', 'salt', 's oil', 's garlic', 'reen chillies', 'mint leaves', 'pudina', 'oil']::text[], '["To prepare Pudina Lehsun Laccha Paratha in a large mixing bowl, combine the whole wheat flour, garlic, and mint leaves.", "Add milk, oil, salt and water little at a time and knead to make a smooth firm dough.", "Drizzle some oil on the dough and knead to make the dough smooth.Divide the dough into large lemon size balls.Preheat a skillet over medium heat.", "If you are using a cast iron skillet, then grease the skillet well and allow it to preheat.Keep some flour aside for dusting while rolling the dough.", "Shape each dough portion into a round ball, press it between the palm of your hands.Dust the dough with flour and roll it into a 6-inch diameter circle.", "Smear some ghee or oil on this rolled out the dough.", "Dust some flour over the ghee.", "This flour and ghee will help the Pudina Lehsun Laccha split itself into layers.Begin folding the Pudina Lehsun Laccha dough like an accordion, similar to a saree pleat.", "Start from one end of the dough and reach the end.", "The dough is essentially made into a pleat.", "Once you have stacked up all the pleats one over the other, roll the dough into a swiss roll.Flatten the pleated swiss roll between the palm of your hands, dust in flour and roll into a 4 to 5-inch diameter circle.", "You will be able to see the layers very clearly.Place the rolled layered Pudina Lehsun Laccha on the preheated skillet.", "Cook on medium heat on both sides for a few seconds, then smear ghee and cook until golden brown and cooked through completely.Proceed the same way with the remaining portions of the paratha dough.Serve Pudina Lehsun Laccha Paratha along with\u00a0Punjabi Kadhi Pakora Recipe\u00a0&\u00a0Achari Paneer\u00a0for a perfect weekend lunch or dinner."]'::jsonb, 90, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Pudina_Laccha_Paratha_recipe_17_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1369.Pudina_Laccha_Paratha_recipe_17_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kesar Paneer Ki Kheer Recipe - Cottage Cheese Milk Pudding', 'kesar-paneer-ki-kheer-recipe-cottage-cheese-milk-pudding', 'Kesar Paneer Ki Kheer Recipe is a quick and simple dessert that you can make when you have unexpected guests at home. The taste and flavors and texture of this kheer is similar to that of rasmalai. The only difference between the Rasmalai and the Paneer ki Kheer is that the paneer is added as a crumble into the condensed milk, making this dish, really simple to make.', '["1 liter Milk", "1 cup Paneer (Homemade Cottage Cheese) , crumbled", "15 Saffron strands", "1/4 cup Sugar", "1/2 teaspoon Cardamom Powder (Elaichi)", "4 Whole Almonds (Badam) , pound", "4 Pistachios , pound", "1 Edible Silver Foil/Leaf (Chandi Ka Vark) , for garnishing"]'::jsonb, ARRAY['paneer', 'milk', 'saffron strands', 'sugar', 'edible silver foilleaf (chandi ka vark)', 'cardamom powder (elaichi)', 'pistachios pound', 'badam (almond) pound']::text[], '["To begin making the Paneer Ki Kheer Recipe, heat the milk in a heavy bottomed pan and bring the milk to a boil.", "Once the milk comes to a boil, turn the heat to low and start condensing the milk until it becomes half its quality.This process of condensing the milk will take about 25 to 30 minutes on medium heat.After about 25 to 30 minutes, when the milk has condensed to half its quantity, add the saffron strands, sugar, cardamom and the crumbled chenna.Simmer Paneer Ki Kheer until it has thickened to a desired consistency, about 5 minutes.", "Once done, turn off the heat.Transfer the Paneer Ki Kheer in the serving bowl, garnish with almond and pistachio and silver leaf.Serve\u00a0Kesar Paneer Ki Kheer\u00a0as a dessert after your everyday meal of\u00a0Jodhpuri Aloo,\u00a0Ajwain Puri,\u00a0Boondi Raita\u00a0and\u00a0Satvik Carrot Sprout Salad."]'::jsonb, 60, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Paneer_Chena_Ki_Kheer_Payasam_Recipe_Video_Hub_Archanas_Kitchen_Vegetarian-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1370.Paneer_Chena_Ki_Kheer_Payasam_Recipe_Video_Hub_Archanas_Kitchen_Vegetarian-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('हरियाली अंडे की करी रेसिपी - Hariyali Egg Curry Recipe In Coriander and Mint Gravy', 'hariyali-egg-curry-recipe-in-coriander-and-mint-gravy', 'हरियाली अंडे की करी रेसिपी, स्वाद से भरपूर करी है जिसमे ग्रेवी बनाने के लिए धनिये और पुदीना का प्रयोग किया जाता है. इसके साथ इसमें रोज के मसालो का प्रयोग किया जाता है. धनिया और पुदीना का प्रयोग इस करी को ताज़ा और फ्लेवर से भरपूर बनाता है. आप इसे अपने रोज के होने के लिए बना सकते है.', '["4 \u0905\u0902\u0921\u0947 , \u0909\u092c\u093e\u0932 \u0932\u0947", "1 \u0926\u093e\u0932\u091a\u0940\u0928\u0940 , \u091b\u094b\u091f\u0940", "1 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e", "2 \u0932\u0949\u0928\u094d\u0917", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0915\u094d\u0930\u0940\u092e", "\u0939\u0930\u093f\u092f\u093e\u0932\u0940 \u092e\u0938\u093e\u0932\u093e \u0915\u0947 \u0932\u093f\u090f", "2 \u0915\u092a \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u0915\u093e\u091f \u0932\u0947", "1 \u0915\u092a \u092a\u0941\u0926\u0940\u0928\u093e , \u0915\u093e\u091f \u0932\u0947", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0915\u093e\u091f \u0932\u0947", "\u092a\u094d\u092f\u093e\u091c \u092e\u0938\u093e\u0932\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f", "1 \u092a\u094d\u092f\u093e\u091c , \u0915\u093e\u091f \u0932\u0947", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u0915\u093e\u091f \u0932\u0947", "4 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928"]'::jsonb, ARRAY['अंडे', 'दालचीनी', 'तेज पत्ता', 'लॉन्ग', 'छोटे चम्मच धनिया पाउडर', 'छोटा चम्मच गरम मसाला पाउडर', 'बड़ा चम्मच तेल', 'बड़े चम्मच क्रीम', 'हरियाली मसाला के लिए', 'कप हरा धनिया', 'कप पुदीना', 'हरी मिर्च', 'प्याज मसालों के लिए', 'प्याज', 'इंच अदरक', 'कली लहसुन']::text[], '["\u0939\u0930\u093f\u092f\u093e\u0932\u0940 \u0905\u0902\u0921\u0947 \u0915\u0940 \u0915\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0939\u092e \u0939\u0930\u093f\u092f\u093e\u0932\u0940 \u092e\u0938\u093e\u0932\u093e \u092c\u0928\u093e\u090f\u0902\u0917\u0947\u0964\u0905\u092c \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e, \u092a\u0941\u0926\u0940\u0928\u093e, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, 1/2 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u092a\u0940\u0938 \u0915\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947\u00a0\u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e, \u0932\u0949\u0928\u094d\u0917, \u0926\u093e\u0932\u091a\u0940\u0928\u0940 \u0921\u093e\u0932\u0947 \u0915\u0930 10\u00a0\u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u0930\u094b\u0938\u094d\u091f \u0915\u0930 \u0932\u0947.\u00a010 \u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u092c\u093e\u0926 \u092a\u094d\u092f\u093e\u091c, \u0905\u0926\u0930\u0915, \u0932\u0939\u0938\u0941\u0928 \u0921\u093e\u0932\u0947 \u0914\u0930 4\u00a0\u0938\u0947 5 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u092a\u0915 \u091c\u093e\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 1\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.1 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0939\u0930\u093f\u092f\u093e\u0932\u0940 \u092e\u0938\u093e\u0932\u093e, \u0924\u093e\u095b\u093e \u0915\u094d\u0930\u0940\u092e, \u0909\u092c\u0932\u0947 \u0939\u0941\u090f \u0905\u0902\u0921\u0947 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947, \u0915\u095d\u093e\u0908 \u0915\u094b \u0922\u0915\u0947 \u0914\u0930 5\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0939\u0930\u093f\u092f\u093e\u0932\u0940 \u0905\u0902\u0921\u0947 \u0915\u0940 \u0915\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0924\u0935\u093e \u092a\u0930\u093e\u0920\u093e\u00a0\u0914\u0930\u00a0\u092c\u0942\u0902\u0926\u0940 \u0930\u093e\u092f\u0924\u0947\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0930\u093e\u0924 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 35, 'Indian', 'egg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Hariyali_Egg_Curry_Recipe_Creamy_Coriander_and_Mint_Curry-5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1371.Hariyali_Egg_Curry_Recipe_Creamy_Coriander_and_Mint_Curry-5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Jeera Hing Aloo Recipe - No Onion No Garlic Recipe', 'jeera-hing-aloo-recipe-no-onion-no-garlic-recipe', 'Potato is one of the most popular vegetables that is loved by everyone, all over the world. This humble vegetable tastes delicious in all forms. Fry them, mash them, boil them, add them in curry, it’s all simply delicious. It would be hard to find someone who doesn’t love this vegetable.', '["500 grams Baby Potatoes", "1-1/2 tablespoon Cumin seeds (Jeera)", "1/2 teaspoon SSP Asafoetida (Hing)", "Salt", "1 teaspoon Red Chilli powder", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Coriander Powder (Dhania)", "1 teaspoon Ginger , finely chopped", "1/2 teaspoon Amchur (Dry Mango Powder)", "Oil , as required", "Coriander (Dhania) Leaves , as required, chopped for garnish"]'::jsonb, ARRAY['salt', 'ginger', 'amchur (dry mango powder)', 'asafoetida (hing)', 'coriander (dhania) leaves', 'red chilli powder', 'cumin seeds (jeera)', 'baby potatoes', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Jeera Hing Aloo recipe, wash and clean the potatoes.", "In a pressure cooker add the potatoes along with some water and salt.", "Close the pressure cooker and pressure cook for 2 whistles.", "Turn off the flame and allow the pressure to release naturally.", "Once the pressure has released naturally, open the pressure cooker and drain off all the excess water.", "Peel the baby potatoes and set aside.", "In a wide pan heat oil.", "Add cumin seeds and hing.", "After it crackles, add the ginger and mix well.Add red chilli powder, turmeric powder, coriander powder, salt and give it a quick mix and then add potatoes immediately.Mix gently so all the spices are coated all over the potatoes.", "Saut\u00e9 for 5 minutes on low flame until the potatoes get a lightly roasted texture and a good outer crust.Add amchur powder, give the Jeera Hing Aloo a good mix.Turn off the heat and garnish the Jeera Hing Aloo Sabzi with coriander leaves and serve hot.Serve\u00a0Jeera Hing Aloo Sabzi\u00a0as an appetizer or as side dish with\u00a0Phulka\u00a0or\u00a0Whole Wheat Lachha Paratha\u00a0and\u00a0Gujarati Kadhi\u00a0for an everyday meal."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Jyothi_Rajesh/Chatpatta_Jeera_Aloo_Recipe_27_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1372.Chatpatta_Jeera_Aloo_Recipe_27_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Sweet Corn And Raw Mango Salad Recipe', 'sweet-corn-and-raw-mango-salad-recipe', 'The Sweet Corn And Raw Mango Salad Recipe is a lip smacking combination of grated mangoes that is tossed in sweet corn, green chillies and coriander. The addition of mustard sauce makes this salad absolutely delicious.', '["3 Mango (Raw) , peeled and grated", "1 cup Sweet corn", "1 Green Chilli , minced", "1 teaspoon Kasundi mustard sauce", "1 tablespoon Honey", "Coriander (Dhania) Leaves , to garnish", "1/2 teaspoon Black Salt (Kala Namak)"]'::jsonb, ARRAY['kasundi mustard sauce', 'black salt', 'green chilli', 'coriander (dhania) leaves', 'mango', 'sweet corn']::text[], '["To begin making the Sweet Corn And Raw Mango Salad Recipe, first peel off the skin of Mangoes and grate in a medium sized bowl.", "Wash and add the corn to the bowl containing the grated Raw Mangoes and mix well.Drizzle the Kasundi mustard sauce and honey and toss chopped green chilies on top of the Sweet Corn And Raw Mango Salad Mixture as a dressing.", "Sprinkle half a teaspoon of black salt and mix well.", "Finally garnish the\u00a0Sweet Corn And Raw Mango Salad with finely chopped coriander leaves on top.", "Serve\u00a0Sweet Corn And Raw Mango Salad Recipe as a salad with\u00a0Fish Molee Recipe\u00a0and\u00a0Steamed Rice\u00a0for a wonderful Sunday afternoon lunch."]'::jsonb, 15, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/May-2/Sweet_Corn_And_Raw_Mango_Salad_Recipe-6.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1373.Sweet_Corn_And_Raw_Mango_Salad_Recipe-6.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bhindi Masala Gravy Recipe - Ladies Finger In Tomato Onion Gravy', 'bhindi-masala-gravy-recipe-ladies-finger-in-tomato-onion-gravy', 'Bhindi Masala is a simple gravy recipe in which okra/bhindi is cooked in a tomato onion based gravy. Full of flavour and taste, this masala gravy is specially served with Biryanis. But, you can also serve it for your everyday meal along with Phulka/ Paratha and your choice of raita.', '["250 grams Bhindi (Lady Finger/Okra) , thinly sliced", "Bhindi Masala Gravy Paste", "1 Onion , roughly chopped", "1 inch Ginger", "5 cloves Garlic", "2 Green Chillies , chopped", "2 Cloves (Laung)", "1 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "1 Mace (Javitri)", "Other ingredients for flavoring", "3 Tomatoes , roughly chopped", "2 tablespoons Curd (Dahi / Yogurt)", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "1 Bay leaf (tej patta)", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "Oil", "Salt , to taste", "Oil", "Salt , to taste"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'cardamom (elaichi) podsseeds', 'bay leaf (tej patta)', 'red chilli powder', 'cloves garlic', 'curd', 'onion', 'cinnamon stick (dalchini)', 'mace (javitri)', 'bhindi (lady fingerokra)', 'kasuri methi (dried fenugreek leaves)', 'cloves (laung)', 'coriander powder', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Bhindi\u00a0Masala Gravy\u00a0Recipe, make sure to first rinse and dry each Bhindi.", "This process is done in order to ensure that the bhindi doesn''t get sticky while cooking it.", "After wiping the bhindis dry, slit the bhindi vertically till about half an inch from the tail (thinly sliced), so that each bhindi is slit but held together by the tail.", "Heat oil for cooking into a pan; add the bhindi, sprinkle some salt and saute the bhindi until cooked.Cover the pan of the bhindi partially while it is cooking.", "This will help the bhindi steam cook, at the same time roast a bit.", "Keeping the lip ajar, helps the steam at the same time, trap a little steam.", "It will take a good 10 minutes to cook the bhindi.", "Keep stirring to ensure it gets roasted well on all sides.Next step is to make the gravy for the Bhindi Masala.Add the tomatoes, into a mixer grinder and make a puree.", "Keep aside.In a mixer grinder, add garlic, onions, ginger, chillies, cloves, cardamom, cinnamon stick and made and grind it to a smooth paste.", "Keep aside.", "Heat oil in a pan on medium heat; add in the bay leaf and saute for about 10 seconds.After 10 seconds, add in the\u00a0 onions garlic and spice paste and saute for 2 to 3 minutes.Add the turmeric powder, red chilli powder, coriander powder and mix everything well.", "Cook for about a minute until the raw smell goes away.", "Next, add the tomato puree, curd and salt.", "It will take about 2 to 3 minutes over medium heat for the tomato to cook.", "Check the salt and allow the masala to be thick.Once done, add the roasted bhindi into the masala gravy.", "Check the salt and turn the heat to high and cook for another minute so that the bhindi gets coated well with the masala.After a couple of minutes, add the crushed kasuri methi and turn off the heat.Garnish the Bhindi Masala Gravy with chopped coriander leaves and serve hot.Serve\u00a0Bhindi Masala Gravy along with\u00a0Paneer Biryani,\u00a0Jackfruit Biryani\u00a0or any Biryani of your choice for a vegetarian lunch or dinner.", "If can also serve the along with\u00a0Tawa Paratha\u00a0and\u00a0Boondi Raita\u00a0for an Indian lunch or dinner."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/vidzworld-gmail.com/Bhindi_Masala_Recipe_-_Ladies_Finger_In_Tomato_Onion_Gravy_-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1374.Bhindi_Masala_Recipe_-_Ladies_Finger_In_Tomato_Onion_Gravy_-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('भिंडी मसाला ग्रेवी रेसिपी - Bhindi Masala Gravy Recipe', 'bhindi-masala-gravy-recipe', 'भिंडी मसाला एक सरल ग्रेवी रेसिपी है जिसमे भिंडी या ओकरा को टमाटर और प्याज की ग्रेवी में बनाया जाता है. फ्लेवर से भरपूर, इस सब्ज़ी को बिरयानी के साथ परोसा जाता है. लेकिन आप इसे अपने पराठा और फुल्का के साथ भी परोस सकते है.', '["250 \u0917\u094d\u0930\u093e\u092e \u092d\u093f\u0902\u0921\u0940 , \u092a\u0924\u0932\u093e \u0914\u0930 \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "\u092d\u093f\u0902\u0921\u0940 \u092e\u0938\u093e\u0932\u093e \u0917\u094d\u0930\u0947\u0935\u0940 \u0915\u0947 \u0932\u093f\u090f", "1 \u092a\u094d\u092f\u093e\u091c , \u0915\u093e\u091f \u0932\u0947", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915", "5 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0915\u093e\u091f \u0932\u0947", "2 \u0932\u0949\u0928\u094d\u0917", "1 \u0907\u0932\u093e\u0907\u091a\u0940", "1 \u0907\u0902\u091a \u0926\u093e\u0932\u091a\u0940\u0928\u0940", "1 \u091c\u093e\u0935\u093f\u0924\u094d\u0930\u0940", "\u0926\u0942\u0938\u0930\u0940 \u0938\u093e\u092e\u0917\u094d\u0930\u0940", "3 \u091f\u092e\u093e\u091f\u0930 , \u0915\u093e\u091f \u0932\u0947", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0926\u0939\u0940", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0915\u0938\u0942\u0930\u0940 \u092e\u0947\u0925\u0940", "1 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "\u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['ग्राम भिंडी', 'भिंडी मसाला ग्रेवी के लिए', 'प्याज', 'इंच अदरक', 'कली लहसुन', 'हरी मिर्च', 'लॉन्ग', 'इलाइची', 'इंच दालचीनी', 'जावित्री', 'दूसरी सामग्री', 'टमाटर', 'बड़े चम्मच दही', 'बड़ा चम्मच कसूरी मेथी', 'तेज पत्ता', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच लाल मिर्च पाउडर', 'छोटा चम्मच धनिया पाउडर', 'तेल', 'नमक']::text[], '["\u092d\u093f\u0902\u0921\u0940 \u092e\u0938\u093e\u0932\u093e \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u092d\u093f\u0902\u0921\u0940 \u0915\u094b \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u0927\u094b \u0915\u0930 \u0938\u093e\u095e \u0915\u0930 \u0932\u0947.\u00a0\u092d\u093f\u0902\u0921\u0940 \u0915\u094b \u0938\u0941\u0916\u093e\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u092d\u093f\u0902\u0921\u0940 \u0915\u0947 \u090a\u092a\u0930 \u0915\u0947 \u0939\u093f\u0938\u094d\u0938\u0947 \u0915\u094b \u0915\u093e\u091f \u0915\u0947 \u0928\u093f\u091a\u0947 \u0924\u0915 \u091a\u093e\u0930 \u091a\u0940\u0930\u0947 \u0932\u0917\u093e \u0932\u0947. \u0927\u094d\u092f\u093e\u0928 \u0930\u0916\u0947\u0902 \u092a\u0942\u0930\u093e \u0928 \u0915\u093e\u091f\u0947\u0902\u0964\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u092d\u093f\u0902\u0921\u0940, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092d\u093f\u0902\u0921\u0940 \u0915\u0947 \u092a\u0915\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0915\u095d\u093e\u0908 \u0915\u094b \u0922\u0915 \u0932\u0947 \u0914\u0930 \u092d\u093f\u0902\u0921\u0940 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u0917\u094d\u0930\u0947\u0935\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f, \u092a\u0939\u0932\u0947 \u090f\u0915 \u091f\u092e\u093e\u091f\u0930 \u0915\u094b \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0925\u094b\u095c\u0947 \u092a\u093e\u0928\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u0942\u0930\u0940 \u092c\u0928\u093e \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0932\u0939\u0938\u0941\u0928, \u092a\u094d\u092f\u093e\u091c, \u0905\u0926\u0930\u0915, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0932\u0949\u0928\u094d\u0917, \u0907\u0932\u093e\u0907\u091a\u0940, \u0926\u093e\u0932\u091a\u0940\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 10\u00a0\u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. 10\u00a0\u0938\u0947\u0915\u0923\u094d\u0921\u094d\u0938 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c \u0905\u0926\u0930\u0915 \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.3 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092d\u093f\u0902\u0921\u0940 \u0921\u093e\u0932\u0947, \u0906\u0902\u091a \u0924\u0947\u091c \u0915\u0930\u0947\u0902 \u0914\u0930 1\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0914\u0930 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0915\u0938\u0942\u0930\u0940 \u092e\u0947\u0925\u0940 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947. \u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u0947 \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092d\u093f\u0902\u0921\u0940 \u092e\u0938\u093e\u0932\u093e \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0926\u093e\u0932 \u092e\u0916\u0928\u0940,\u00a0\u092c\u0942\u0902\u0926\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u0914\u0930\u00a0\u092b\u0941\u0932\u094d\u0915\u0947\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/vidzworld-gmail.com/Bhindi_Masala_Recipe_-_Ladies_Finger_In_Tomato_Onion_Gravy_-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1375.Bhindi_Masala_Recipe_-_Ladies_Finger_In_Tomato_Onion_Gravy_-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Chichinda Ki Sabzi Recipe -Uttar Pradesh Style Snake Gourd Stir Fry', 'chichinda-ki-sabzi-recipe-uttar-pradesh-style-snake-gourd-stir-fry', 'Chichinda Ki Sabzi Recipe (Uttar Pradesh Style Snake Gourd Stir Fry) is an easy and quick to make during weeknights and can also be packed for lunch boxes. The snake gourds are cooked in minimal spices and roasted chickpea flour that imparts a nutty flavour.', '["500 grams Snake gourd (pudulangai) , chopped (preferably lengthwise)", "4 tablespoons Gram flour (besan) , roasted", "1 Onion , finely chopped", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "1 teaspoon Amchur (Dry Mango Powder)", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Chana dal (Bengal Gram Dal)", "2 Dry Red Chillies", "2 teaspoons Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'amchur (dry mango powder)', 'mustard seeds', 'red chilli powder', 'gram flour (besan)', 'dry red chillies', 'onion', 'snake gourd (pudulangai) (preferably lengthwise)', 'turmeric powder', 'chana dal (bengal gram dal)', 'sunflower oil']::text[], '["To begin making Chichinda Ki Sabzi Recipe (Uttar Pradesh Style Snake Gourd Stir Fry), scrape the outer layer off the snake gourd, cut into into two and scoop out the inner seeds using a spoon.", "Cut it into thin slices and keep aside.In a preheated pan dry roast the besan in a pan on medium heat till it imparts a nutty flavour and keep aside.Heat oil in the same pan, add the mustard seeds, chana dal, red chillies and let it splutter.Add the chopped onions and saute until translucent.Once the onions have turned translucent add the sliced snake gourd pieces, and mix well.Add the turmeric powder, red chilli powder, season with salt and let the snake gourd cook with the lid on.", "This will take around 10 minutes.Once the snake gourds are cooked well, and the water is completely dried out, add in the roasted besan and stir well.Saute the mix on medium heat until the besan incorporates well with the cooked snake gourd.", "This will take 10 minutes.Add in the amchoor powder to the\u00a0Chichinda Ki Sabzi and mix to combine, turn off the heat.Serve the Chichinda Ki Sabzi Recipe, along with Kaddu Palak Roti Recipe (Pumpkin Spinach Flat Bread), Cauliflower Moong Dal Recipe, and Boondi Raita Recipe Spiced With Black Salt on sides."]'::jsonb, 30, 'Uttar Pradesh', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/0-Archana/Chichinda_Ki_Sabzi_Recipe_Uttar_Pradesh_Style_Snake_Gourd_Stir_Fry-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1376.Chichinda_Ki_Sabzi_Recipe_Uttar_Pradesh_Style_Snake_Gourd_Stir_Fry-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Punjabi Style Boondi Kadhi Recipe', 'punjabi-style-boondi-kadhi-recipe', 'Punjabi Style Boondi Kadhi Recipe is a popular kadhi in Rajasthan and Punjab. Methi seeds are rich in iron and lentils are rich in proteins. It is a soothing side dish that is apt to have during hot days.', '["1-1/2 cups Curd (Dahi / Yogurt) , (Sour)", "4 tablespoons Gram flour (besan)", "1 teaspoon Green Chilli Paste", "1 teaspoon Ginger Garlic Paste", "1/2 tablespoon Red Chilli powder", "1/4 teaspoon Turmeric powder (Haldi)", "Salt , to taste", "2 tablespoons Ghee", "5 Cloves (Laung)", "5 Whole Black Peppercorns , pounded", "1 teaspoon Cumin seeds (Jeera)", "1 tablespoon Methi Seeds (Fenugreek Seeds) , soaked overnight", "1 pinch Asafoetida (hing)", "1 cup Boondi", "5 Cloves (Laung)", "5 Whole Black Peppercorns , pounded", "1 teaspoon Cumin seeds (Jeera)", "1 tablespoon Methi Seeds (Fenugreek Seeds) , soaked overnight", "1 pinch Asafoetida (hing)", "1 cup Boondi"]'::jsonb, ARRAY['s curd', 'dahi / yogurt', 's gram flour', 'besan', 'green chilli paste', 'ginger garlic paste', 'red chilli powder', 'turmeric powder', 'haldi', 'salt', 's ghee', 'laung', 'whole black peppercorns', 'cumin seeds', 'jeera', 'methi seeds', 'fenugreek seeds', 'asafoetida', 'hing', 'boondi']::text[], '["To begin making the Punjabi Style Boondi Kadhi Recipe, firstly combine yogurt, gram flour, red chilli powder, turmeric powder and salt in a bowl.", "Add 500 ml water and whisk well.", "Make sure that no lumps are formed.Heat ghee in a deep non-stick pan, add cloves, peppercorns, cumin seeds, fenugreek seeds and saut\u00e9 for a minute.After a minute, add asafoetida, chopped ginger and red chillies, mix and saut\u00e9 for about a minute.Now, add methi seeds (soaked in the night) and stir for few mintues.Now, add the gram flour and yogurt mixture and stir continouly until the bubbles form in the kadai.", "As the mixture gets thick while boiling, add 500 ml water and keep the flame low and allow to cook for 15 to 20 minutes.After 15 to 20 minutes, switch off the gas, add boondi and and garnish with coriander leaves.Make this easy and nutritional\u00a0Punjabi Style Boondi Kadhi Recipe\u00a0and pair it along with\u00a0Bajri-Til Bhakri Recipe, a piece of gur and a dollop of ghee smeared on roti.", "You can also serve\u00a0Kachumber Salad\u00a0on the side."]'::jsonb, 40, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/31-march/Boondi_Kadhi_Recipe_Spicy_yogurt_with_boondi_-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1377.Boondi_Kadhi_Recipe_Spicy_yogurt_with_boondi_-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('पंजाबी स्टाइल बूंदी कढ़ी रेसिपी - Punjabi Style Boondi Kadhi Recipe', 'punjabi-style-boondi-kadhi-recipe-2', 'पंजाबी स्टाइल बूंदी कढ़ी रेसिपी एक प्रसिद्ध कढ़ी है जिसे राजस्थान और पंजाब में बनाया जाता है. इसमें मेथी के दाने भी डाले जाते है जो इसका स्वाद और भी बढ़ाते है. यह एक ताज़ा डिश है जिसे आप गर्मियों के दिनों में बना सकते है.', '["\u0915\u095d\u0940 \u0915\u0947 \u0932\u093f\u090f", "1-1/2 \u0915\u092a \u0926\u0939\u0940", "4 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u092c\u0947\u0938\u0928", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u092a\u0947\u0938\u094d\u091f", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0905\u0926\u0930\u0915 \u0932\u0939\u0938\u0941\u0928 \u0915\u093e \u092a\u0947\u0938\u094d\u091f", "1/2 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0918\u0940", "5 \u0932\u0949\u0928\u094d\u0917", "5 \u092a\u0942\u0930\u0940 \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a , \u092a\u0940\u0938 \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u092e\u0947\u0925\u0940 \u0915\u0947 \u0926\u093e\u0928\u0947 , \u0930\u093e\u0924 \u092d\u0930 \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u092d\u093f\u0917\u094b \u0932\u0947", "\u0939\u0940\u0902\u0917 , \u091a\u0941\u091f\u0915\u0940 \u092d\u0930", "1 \u0915\u092a \u092c\u0942\u0902\u0926\u0940"]'::jsonb, ARRAY['कढ़ी के लिए', 'कप दही', 'बड़े चम्मच बेसन', 'छोटा चम्मच हरी मिर्च', 'छोटा चम्मच अदरक लहसुन का पेस्ट', 'बड़ा चम्मच लाल मिर्च पाउडर', 'छोटा चम्मच हल्दी पाउडर', 'नमक', 'बड़े चम्मच घी', 'लॉन्ग', 'पूरी काली मिर्च', 'छोटा चम्मच जीरा', 'बड़ा चम्मच मेथी के दाने', 'हींग', 'कप बूंदी']::text[], '["\u092a\u0902\u091c\u093e\u092c\u0940 \u0938\u094d\u091f\u093e\u0907\u0932 \u092c\u0942\u0902\u0926\u0940 \u0915\u095d\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0926\u0939\u0940, \u092c\u0947\u0938\u0928, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e\u090f \u0924\u093e\u0915\u093f \u0915\u094b\u0908 \u0917\u093e\u0920\u0947 \u0928 \u0930\u0939\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0932\u0949\u0928\u094d\u0917, \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a, \u091c\u0940\u0930\u093e, \u092e\u0947\u0925\u0940 \u0915\u0947 \u0926\u093e\u0928\u0947 \u0921\u093e\u0932\u0947 \u0914\u0930 1\u00a0\u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092e\u0947\u0925\u0940 \u0915\u0947 \u0926\u093e\u0928\u0947 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0926\u0939\u0940 \u092c\u0947\u0938\u0928 \u0915\u093e \u092e\u093f\u0936\u094d\u0930\u0923 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 15\u00a0\u0938\u0947 20 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u0928\u0947 \u0926\u0947.\u00a0\u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902, \u092c\u0942\u0902\u0926\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u0947 \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902\u0964 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u00a0\u092a\u0902\u091c\u093e\u092c\u0940 \u0938\u094d\u091f\u093e\u0907\u0932 \u092c\u0942\u0902\u0926\u0940 \u0915\u095d\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u092d\u093f\u0902\u0921\u0940 \u092e\u0938\u093e\u0932\u093e,\u00a0\u092b\u0941\u0932\u094d\u0915\u093e\u00a0\u0914\u0930\u00a0\u091c\u0940\u0930\u093e \u0930\u093e\u0907\u0938\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 40, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/31-march/Boondi_Kadhi_Recipe_Spicy_yogurt_with_boondi_-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1378.Boondi_Kadhi_Recipe_Spicy_yogurt_with_boondi_-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('मटर बेसन और पनीर चीला रेसिपी - Matar Besan And Paneer Cheela Recipe', 'matar-besan-and-paneer-cheela-recipe', 'चीला एक डोसा जैसी रेसिपी है जिसमे बेसन का प्रयोग किया जाता है. इसे हर उत्तर भारत के घर में सुबह के नाश्ते के लिए बनाया जाता है. इसे बनाने में बहुत कम समय लगता है और आप इसे अपनी पसंद की चटनी के साथ परोस सकते है.', '["1 \u0915\u092a \u0939\u0930\u0947 \u092e\u091f\u0930 , \u0909\u092c\u093e\u0932 \u0932\u0947", "1 \u0915\u092a \u092c\u0947\u0938\u0928", "1/2 \u0915\u092a \u092a\u0928\u0940\u0930 , \u0915\u0938 \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0905\u0926\u0930\u0915 , \u0915\u093e\u091f \u0932\u0947", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0928\u092e\u0915", "2 \u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['कप हरे मटर', 'कप बेसन', 'कप पनीर', 'छोटा चम्मच अदरक', 'हरी मिर्च', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच जीरा पाउडर', 'छोटा चम्मच नमक', 'तेल']::text[], '["\u092e\u091f\u0930 \u092c\u0947\u0938\u0928 \u0914\u0930 \u092a\u0928\u0940\u0930 \u091a\u0940\u0932\u093e \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930\u00a0\u092e\u0947\u0902 \u0939\u0930\u0947 \u092e\u091f\u0930, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0905\u0926\u0930\u0915, \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0940\u0938 \u0915\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938 \u092a\u0947\u0938\u094d\u091f \u0915\u094b \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947\u0964 \u0907\u0938\u092e\u0947\u0902 \u092c\u0947\u0938\u0928, \u091a\u0940\u095b, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915, \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0924\u0935\u0947 \u0915\u094b \u092a\u0939\u0932\u0947 \u0938\u0947 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092a\u0930 \u0925\u094b\u095c\u093e \u092e\u093f\u0936\u094d\u0930\u0923 \u092c\u093f\u091a \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0917\u094b\u0932 \u0906\u0915\u0930 \u092e\u0947\u0902 \u092b\u0948\u0932\u093e \u0932\u0947.\u00a0\u0925\u094b\u095c\u093e \u0924\u0947\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0926\u094b\u0928\u094b\u0902 \u0924\u0930\u092b \u0938\u0947 \u092d\u0942\u0930\u093e \u0938\u0941\u0928\u0939\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u092a\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u090f\u0915 \u092a\u094d\u0932\u0947\u091f \u092e\u0947\u0902 \u0928\u093f\u0915\u093e\u0932\u0947 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092e\u091f\u0930 \u092c\u0947\u0938\u0928 \u0914\u0930 \u092a\u0928\u0940\u0930 \u091a\u0940\u0932\u093e \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0927\u0928\u093f\u092f\u093e \u092a\u0941\u0926\u0940\u0928\u093e \u091a\u091f\u0928\u0940\u00a0\u0914\u0930\u00a0\u092e\u0938\u093e\u0932\u093e \u091a\u093e\u092f\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0938\u0941\u092c\u0939 \u0915\u0947 \u0928\u093e\u0936\u094d\u0924\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Matar_Paneer_Cheela_Recipe_Green_Peas_Paneer_Crepes-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1379.Matar_Paneer_Cheela_Recipe_Green_Peas_Paneer_Crepes-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Spiced Kumbh Pulao Recipe - Spicy Mushroom Rice', 'spiced-kumbh-pulao-recipe-spicy-mushroom-rice', 'Spiced Kumbh Pulao Recipe is basically marinated rice with mushrooms. If you love mushrooms, you can''t resist yourself adding this ''Tandoori'' dish in your North-Indian menu. This makes for a great weekday dinner. It is a quick and easy recipe and does not take up too much time to prepare.', '["1 cup Basmati rice", "1 teaspoon Ginger Garlic Paste", "1/2 cup Green peas (Matar)", "8 Button mushrooms , washed and cut into quarters", "1 Onion", "2 tablespoons Tandoori Marinade", "2 teaspoon Green Bell Pepper (Capsicum) , chopped", "2 tablespoon Ghee", "1/2 teaspoon Cumin seeds (Jeera)", "pinch Asafoetida (hing)", "Salt , to taste"]'::jsonb, ARRAY['basmati rice', 'ginger garlic paste', 'green peas', 'matar', 'button mushrooms', 'onion', 's tandoori marinade', 'green bell pepper', 'capsicum', 'ghee', 'cumin seeds', 'jeera', 'pinch asafoetida', 'hing', 'salt']::text[], '["To begin making the\u00a0Spiced Kumbh Pulao Recipe, take tandoori marinade in a bowl and add the mushrooms\u00a0 into it.", "Coat them well, cover with a lid and keep in\u00a0freeze\u00a0for half hour.Soak basmati rice in water for around an hour and boil them along with green peas in salted water.", "Drain and rinse with cold water and keep aside.Heat ghee in heavy-bottomed pan and add cumin seeds,\u00a0hing.Once it crackles, add ginger-garlic paste and saute it well.", "Then, add marinated mushrooms along with capsicum and saute them for a minute.After a minute, add cooked basmati rice, salt and mix well.", "Cover with a lid and cook it for around 3-4 minutes.Turn off the heat and transfer it to a serving plate.Serve\u00a0Spiced Kumbh Pulao Recipe\u00a0along with\u00a0Tomato Onion Cucumber Raita,\u00a0Palak Raita\u00a0or any other Raita of your choice and a roasted papad.Notes:Caramelized Onions: Cut onions\u00a0in\u00a0thin strips.", "Heat 1/2 tsp of oil in\u00a0pan\u00a0and add onions.", "Sprinkle a little salt over it to make it crispy.", "Roast it till dark brown in color.", "Transfer it to some bowl and keep aside.Mushrooms will release its juice which will make liquidize marinade a little.", "But add left-over thinner marinade along with mushrooms to make this \"Kumbhi\u00a0Pulao\" more flavorful."]'::jsonb, 100, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Spiced_Kumbh_Pulao_Recipe_Spiced_Mushroom_Rice-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1380.Spiced_Kumbh_Pulao_Recipe_Spiced_Mushroom_Rice-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kadai Broccoli Masala Recipe - Broccoli Cooked With Indian Spices', 'kadai-broccoli-masala-recipe-broccoli-cooked-with-indian-spices', 'A lip smacking dish, the Kadai Broccoli Masala Recipe is a delicious gravy made using freshly ground kadai masala with the goodness of Broccoli. A twist of Broccoli to the North Indian classic, Kadai gravy. This is a simple recipe and gets ready in very less time, therefore you can make it for your everyday lunch.', '["500 grams Broccoli , cut into little florets", "1 Red Bell pepper (Capsicum) , diced", "1 Onion , roughly chopped", "2 Tomatoes , pureed", "1 inch Ginger , finely chopped", "4 cloves Garlic , finely chopped", "1 teaspoon Red Chilli powder", "1 teaspoon Garam masala powder", "1 Black cardamom (Badi Elaichi)", "1/4 Water", "Salt , to taste", "2 tablespoons Oil", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "1 tablespoon Coriander (Dhania) Seeds", "1 teaspoon Cumin seeds (Jeera)", "1/2 teaspoon Fennel seeds (Saunf)"]'::jsonb, ARRAY['tomato', 'black cardamom (badi elaichi)', 'red bell pepper (capsicum)', 'ginger', 'salt', 'fennel seeds (saunf)', 'red chilli powder', 'cloves garlic', 'water', 'coriander (dhania) seeds', 'onion', 'cumin seeds (jeera)', 'broccoli florets', 'kasuri methi (dried fenugreek leaves)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making Kadai Broccoli Masala\u00a0Recipe,\u00a0let us begin by cooking the Broccoli.Heat\u00a0a heavy bottomed pan on medium flame, add a teaspoon of oil, add broccoli florets and 5 tablespoons of water.Add salt, and mix well.", "Cover and cook, until it is al dente. (70% cooked) Do not over cook.The broccoli florets have to be cook yet remain crunchy.", "Keep aside.", "Do not drain the water, if any left.", "In another pan, add ingredients for the kadai masala powder\u00a0which includes coriander seeds, cumin seeds, fennel seeds except kasuri methi and dry roast for 5 minutes on medium flame until the aroma rises.", "Switch off heat, add crushed kasuri methi and give a quick stir and cool completely.", "Transfer into a mixer jar and grind into a coarse powder in a mixer grinder and keep aside.Add remaining oil to a heavy bottomed pan on medium heat.", "Once the oil is hot, add onions, ginger and garlic and saute until they turn soft and transparent.", "This will take about 3-4 minutes.", "Once the onions and ginger garlic is well cooked, add the capsicum, salt and cook till the capsicum becomes soft for about 2 minutes.", "Next, add tomatoes and bai elaichi and mix well.Cook for about 3 to 4 minutes until the tomato becomes thick.", "At this stage, add the prepared kadai masala powder, garam masala, red chilli powder and mix everything well.", "Stir in the\u00a0Once it boils, add broccoli florets, give it a quick stir and cover and cook for about 3 minutes and turn off the heat.", "Check the salt and spices and adjust to suit your taste.Serve Kadai Broccoli Masala Recipe along with\u00a0Tawa Paratha\u00a0and\u00a0Boondi Raita\u00a0for a weekday meal with your family."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Kadai_Broccoli_Masala_Recipe_-_Broccoli_Cooked_With_Indian_Spices-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1381.Kadai_Broccoli_Masala_Recipe_-_Broccoli_Cooked_With_Indian_Spices-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mixed Vegetable Jalfrezi Recipe', 'mixed-vegetable-jalfrezi-recipe', 'Mixed Vegetable Jalfrezi is a popular North Indian side dish that you can make for your everyday meals. It is dry stir fry prepared by sauteing vegetables of your choice with select spices.', '["1 cup Carrot (Gajjar) , diced vetically", "1 cup Green beans (French Beans) , chopped", "1 Green Bell Pepper (Capsicum) , chopped", "1/2 cup Sweet corn", "1 cup Green peas (Matar)", "1 Onion", "2 Tomatoes", "1 teaspoon Ginger Garlic Paste", "1/4 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "1 teaspoon Coriander Powder (Dhania)", "1/2 teaspoon Garam masala powder", "1 tablespoon Kasuri Methi (Dried Fenugreek Leaves)", "Coriander (Dhania) Leaves , for garnishing", "Salt , as required", "1/2 teaspoon Sugar", "1 teaspoon Cumin seeds (Jeera)", "2 teaspoon Oil"]'::jsonb, ARRAY['tomato', 'salt', 'green beans (french beans)', 'carrot veticy', 'coriander (dhania) leaves', 'green peas (matar)', 'red chilli powder', 'ginger garlic paste', 'sugar', 'onion', 'cumin seeds (jeera)', 'sweet corn', 'green bell pepper (capsicum)', 'coriander powder', 'turmeric powder', 'kasuri methi (dried fenugreek leaves)', 'garam masala powder', 'sunflower oil']::text[], '["To begin making Mixed Vegetable Jalfrezi Recipe, wash all the vegetables and cut into thin strips.", "Chop onion lengthwise and prepare the tomato puree.", "In a kadai, add some oil.", "Once the oil is warm, add the ginger garlic paste and saute for a minute.", "The paste will splutter when added to oil, so place the stove on low-medium heat.Next, add chopped onions and saute until translucent.Once done add in the tomato puree and cook until the tomatoes turn mushy.After the tomatoes have turned soft add the turmeric powder, red chilli powder, coriander powder and garam masala powder to it.", "Saute until oil separates.Now add the chopped veggies and fresh green peas to it and saute for a minute.", "After a minute add salt and required water for cooking vegetables.", "Stir and cook covered until vegetables gets cooked well but not mushy.", "It has to retain its crunchiness.Switch off the flame.", "Add sugar and crushed kasuri methi to Mixed Vegetable Jalfrezi, and mix well.", "Transfer Mixed Vegetable Jalfrezi\u00a0 into a serving bowl and garnish with coriander leaves.", "Serve\u00a0Mixed\u00a0Vegetable Jalfrezi\u00a0along with Phulkas and Palak Raita for a weeknight dinner."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swathynandhini/vegetable_jalfrezi_recipe-6.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1382.vegetable_jalfrezi_recipe-6.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kathirikai Podi Curry Recipe (Roasted Brinjal with Spices)', 'kathirikai-podi-curry-recipe-roasted-brinjal-with-spices', 'Kathirikai Podi Curry Recipe is a very traditional South Indian style vegetable made from roasted brinjals also known as aubergine or eggplant. The spice powder varies from home to home and most often the sambar powder is used along with a little cinnamon powder. The Brinjal Podi Curry recipe is a quick and easy vegetable for a weeknight dinner.', '["10 Brinjal (Baingan / Eggplant) , washed and cut into wedges", "2 tablespoon Sesame (Gingelly) Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves , roughly torn", "1/2 teaspoon Turmeric powder (Haldi)", "1/4 teaspoon Asafoetida (hing)", "2 teaspoons Sambar Powder", "Salt , to taste"]'::jsonb, ARRAY['brinjal', 'baingan / eggplant', 'sesame', 'gingelly', 'mustard seeds', 'rai/ kadugu', 'curry leaves', 'turmeric powder', 'haldi', 'asafoetida', 'hing', 's sambar powder', 'salt']::text[], '["To begin making\u00a0 Kathirikai Podi Curry, heat 2 tablespoons of sesame oil in a heavy-bottomed pan over medium heat.", "Add the mustard seeds and curry leaves.", "Allow them to crackle.", "Once it crackles\u00a0add\u00a0the sliced brinjals and salt, stir to combine.Cover the pan with the lid and cook the brinjals on low heat, until they are soft and well cooked, stirring them occasionally.Now add the sambar powder, turmeric powder, asafoetida and saut\u00e9 all the ingredients together on low flame for few minutes or until the brinjal is cooked through.Once cooked, turn off the heat.", "Transfer the Kathirikai Podi Curry in a serving bowl.", "Serve Kathirikai Podi Curry\u00a0hot accompanied by steamed rice, smeared with a spoonful of ghee."]'::jsonb, 35, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Podi_Kathirikai_Curry_Poriyal_South_Indian_Brinjal_Eggplant_Recipe_Archanas_Kitchen_Vegetarian_-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1383.Podi_Kathirikai_Curry_Poriyal_South_Indian_Brinjal_Eggplant_Recipe_Archanas_Kitchen_Vegetarian_-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('कथीरिकै पौड़ी करी रेसिपी - Kathirikai Podi Curry Recipe', 'kathirikai-podi-curry-recipe', 'कथीरिकै पौड़ी करी रेसिपी, एक पारम्परिक दक्षिण भारतीय रेसिपी है जिसमे बैंगन का प्रयोग किया जाता है. इसमें सांबर पाउडर और दालचीनी पाउडर का भी इस्तेमाल किया जाता है जो इसे और भी स्वादिष्ट बनाता है. आप इसे अपने रोज के खाने के लिए बना सकते है या फिर अपने लंच बॉक्स में भी पैक कर सकते है.', '["10 \u092c\u0948\u0902\u0917\u0928 , \u0927\u094b \u0915\u093e\u0930 \u0915\u093e\u091f \u0932\u0947", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u093f\u0932 \u0915\u093e \u0924\u0947\u0932", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "1 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e , \u0924\u094b\u095c \u0932\u0947", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0940\u0902\u0917", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0938\u093e\u0902\u092c\u0930 \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['बैंगन', 'बड़े चम्मच तिल का तेल', 'छोटा चम्मच राइ', 'टहनी कढ़ी पत्ता', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच हींग', 'छोटे चम्मच सांबर पाउडर', 'नमक']::text[], '["\u0915\u0925\u0940\u0930\u093f\u0915\u0948 \u092a\u094c\u095c\u0940 \u0915\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0915\u095c\u093e\u0939\u0940 \u092e\u0947\u0902 2\u00a0\u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0915\u094b \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u0930\u093e\u092f \u0915\u0947 \u0924\u095c\u0915\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092c\u0948\u0902\u0917\u0928, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u0915\u095d\u093e\u0908 \u0915\u094b \u0922\u0915\u0947 \u0914\u0930 \u092c\u0948\u0902\u0917\u0928 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0938\u093e\u0902\u092c\u0930 \u092a\u093e\u0909\u0921\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0939\u0940\u0902\u0917 \u0921\u093e\u0932\u0947 \u0914\u0930 2\u00a0\u092e\u093f\u0928\u091f \u0924\u0915 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092a\u0915\u093e \u0932\u0947. \u092c\u0948\u0902\u0917\u0928 \u0915\u0947 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u092a\u0915 \u091c\u093e\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947.\u00a0\u0915\u0925\u0940\u0930\u093f\u0915\u0948 \u092a\u094c\u095c\u0940 \u0915\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0915\u0940\u0930\u0908 \u0938\u093e\u0902\u092c\u0930, \u091a\u093e\u0935\u0932 \u0914\u0930 \u092a\u093e\u092a\u095c \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 35, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Podi_Kathirikai_Curry_Poriyal_South_Indian_Brinjal_Eggplant_Recipe_Archanas_Kitchen_Vegetarian_-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1384.Podi_Kathirikai_Curry_Poriyal_South_Indian_Brinjal_Eggplant_Recipe_Archanas_Kitchen_Vegetarian_-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('केरला वेंडकई थोरन रेसिपी - Kerala Vendakkai Thoran Recipe', 'kerala-vendakkai-thoran-recipe', 'केरला वेंडकई थोरन रेसिपी, एक सरल दक्षिण भारतीय रेसिपी है जिसमे भिंडी को प्याज, हरी मिर्च और नारियल के साथ पकाया जाता है. आप इसे अपने रोज के खाने के लिए बनाए या फिर अपने लंच बॉक्स में पैक करें।', '["350 \u0917\u094d\u0930\u093e\u092e \u092d\u093f\u0902\u0921\u0940 , \u0938\u094d\u091f\u0947\u092e \u0928\u093f\u0915\u093e\u0932 \u0915\u0947 \u092c\u093f\u091a \u092e\u0947\u0902 \u0938\u0947 \u0915\u093e\u091f \u0932\u0947", "1/2 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "10 \u091b\u094b\u091f\u0947 \u092a\u094d\u092f\u093e\u091c , \u0915\u093e\u091f \u0932\u0947", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u091b\u0940\u0932\u0915\u0930 \u0915\u0938 \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0938\u095e\u0947\u0926 \u0909\u0930\u0926 \u0926\u093e\u0932", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "6 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932"]'::jsonb, ARRAY['ग्राम भिंडी', 'कप नारियल', 'हरी मिर्च', 'छोटे प्याज', 'इंच अदरक', 'छोटा चम्मच राइ', 'छोटा चम्मच सफ़ेद उरद दाल', 'नमक', 'कढ़ी पत्ता', 'बड़े चम्मच तेल']::text[], '["\u0915\u0947\u0930\u0932\u093e \u0935\u0947\u0902\u0921\u0915\u0908 \u0925\u094b\u0930\u0928 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0928\u093e\u0930\u093f\u092f\u0932, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0940\u0938 \u0932\u0947. \u0907\u0938 \u092a\u0947\u0938\u094d\u091f \u0915\u094b \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u0909\u0930\u0926 \u0926\u093e\u0932, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947. \u0924\u095c\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c, \u0905\u0926\u0930\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092d\u093f\u0902\u0921\u0940, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947\u0964 \u0915\u095d\u093e\u0908 \u0915\u094b \u0922\u0915\u0947 \u0914\u0930 \u092d\u093f\u0902\u0921\u0940 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u092d\u093f\u0902\u0921\u0940 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0928\u093e\u0930\u093f\u092f\u0932 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947\u0964 \u0938\u092c\u094d\u095b\u0940 \u0915\u094b \u092e\u093f\u0932\u093e \u0932\u0947 \u0914\u0930 5\u00a0\u0938\u0947 10 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u0928\u0947 \u0926\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0915\u0947\u0930\u0932\u093e \u0935\u0947\u0902\u0921\u0915\u0908 \u0925\u094b\u0930\u0928 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u091a\u093e\u0909 \u091a\u093e\u0909 \u0938\u093e\u0902\u092c\u0930, \u091a\u093e\u0935\u0932 \u0914\u0930 \u092a\u093e\u092a\u095c \u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 40, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Vendakkai_Thoran_Kerala_Style_Recipe_Okra_Stir_Fry_with_Coconut-8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1385.Vendakkai_Thoran_Kerala_Style_Recipe_Okra_Stir_Fry_with_Coconut-8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Manipuri Style Karotkhabi Kanghou Recipe - Bitter Gourd & Potato Stir Fry', 'manipuri-style-karotkhabi-kanghou-recipe-bitter-gourd-potato-stir-fry', 'Karotkhabi Kanghou is a Manipuri style vegetable dish prepared with bitter gourd and potato. Like every Northeastern state Manipur also has its own style of cooking. Generally Bitter gourd dishes are always served first in meal. This dish is good when it is serve warm with hot steamed rice.', '["1 Karela (Bitter Gourd/ Pavakkai) , sliced", "1 Potato (Aloo) , pealed and diced", "1 Onion , chopped", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Red Chilli powder", "2 Green Chillies , chopped", "Salt , for seasoning", "Oil"]'::jsonb, ARRAY['salt', 'karela (bitter gourd pavakkai)', 'potato (aloo) pealed', 'red chilli powder', 'onion', 'cumin seeds (jeera)', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making the Karotkhabi Kanghou Recipe, heat oil in a heavy bottomed pan.", "Add cumin seeds, when it starts crackling add chopped onion.", "Cook onion until soft and tender.Once the onions are soft and tender, add chopped green chilies, karela and potato.", "Let it cook for about 2 to 3 minutes.After 2 to 3 minutes, add salt, turmeric powder and red chili powder.", "Mix everything well.Switch the heat to medium, cover and let it cook till the vegetables are cooked properly.", "Once it is done, switch off the heat.Serve\u00a0Karotkhabi Kanghou\u00a0along with\u00a0Tomato Onion Sambar\u00a0and\u00a0Steamed Rice\u00a0with a dollop of ghee for your everyday meal."]'::jsonb, 30, 'North East India', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/10-may/Karotkhabi_Kanghou_Recipe_Manipuri_style_Bitter_Gourd__Potato_Stir_Fry-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1386.Karotkhabi_Kanghou_Recipe_Manipuri_style_Bitter_Gourd__Potato_Stir_Fry-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Vazhakkai Varuval Recipe- Raw Banana Roast Recipe', 'vazhakkai-varuval-recipe-raw-banana-roast-recipe', 'Vazhakkai Varuval is a simple South Indian Style dry preparation. Vazhakkai, also known as Plantain or Raw Banana and is used extensively in the South Indian Cuisine. Vazhakkai Varuval can be made in different ways with different masalas according to you taste. We have made a flavourful, tasty Vazhakkai Varuval with everyday spices which are easily available in your pantry.', '["2 Raw Banana , sliced", "1 teaspoon Red Chilli powder", "2 teaspoon Coriander Powder (Dhania)", "1 teaspoon Turmeric powder (Haldi)", "Oil , as required", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Asafoetida (hing)", "2 sprig Curry leaves", "2 Dry Red Chillies", "Salt , to taste"]'::jsonb, ARRAY['salt', 'mustard seeds', 'asafoetida (hing)', 'red chilli powder', 'curry leaves', 'dry red chillies', 'coriander powder', 'turmeric powder', 'banana', 'sunflower oil']::text[], '["To begin making Vazhakkai Varuval or the raw banana roast recipe, peel the skin of the plantains and slice them into thick slices and place them in a bowl of water to prevent oxidation.Heat oil in a skillet over medium heat.", "Add the mustard seeds and allow them to crackle.Once the mustard seeds crackle, add the dry red chillies, curry leaves and asafoetida.", "Drain the water from the sliced bananas and add this to the skillet.Add the red chilli powder, turmeric powder, coriander powder and salt to taste.Toss the Raw bananas well in all the masala and stir fry on medium high heat to make the\u00a0Vazhakkai Varuval.You can optionally cover the pan and cook the raw bananas, or cook on open until the raw bananas are cooked and have crisp golden outer.When you notice the raw bananas have a crisp golden outer and is cooked through then the\u00a0Vazhakkai Varuval is ready.", "Check the salt and adjust to suit your taste.Once done, turn off the heat and transfer the Vazhakkai Varuval/ Raw Banana Roast to a serving bowl and serve hot.", "Serve the\u00a0Vazhakkai Varuval/ Raw Banana Roast Steamed Rice,\u00a0Tomato Rasam,\u00a0Vendhaya Keerai Sambar Recipe, appalam, ghee and lemon pickle\u00a0for a perfect south indian lunch."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Vazhakkai_Varuval_Recipe-_Raw_Banana_Roast_Recipe_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1387.Vazhakkai_Varuval_Recipe-_Raw_Banana_Roast_Recipe_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Style Varutharacha Sambar Recipe - Tangy Coconut Sambar Recipe', 'kerala-style-varutharacha-sambar-recipe-tangy-coconut-sambar-recipe', 'Varutharacha Sambar is a delicious Kerala Style Sambar Recipe that is made from roasted coconut homemade sambar powder that adds to the authenticity and flavor of the sambar. The aromas from the ground spices when combined along with tamarind water and cooked lentils, make this sambar very delicious and festive. An Onam sadya is incomplete without the freshly prepared spicy Varutharacha Sambar. It gives the whole meal a definition and lifts the Sadya to a new dimension.', '["Ingredients for the Sambar Curry", "1/2 cup Arhar dal (Split Toor Dal)", "2 Potato (Aloo) , peel the skin and cut into large cubes", "1 Drumstick , cut into 2 inch pieces", "2 cups Vellai Poosanikai (Ash gourd/White Pumpkin) , cut into medium sized cubes", "2 Carrots (Gajjar) , cubed", "6 Bhindi (Lady Finger/Okra) , cut into 1 and \u00bd inch pieces", "1 Tomato , diced", "10 Shallots , whole or cut into half", "1-1/2 cup Tamarind Water", "1 teaspoon Turmeric powder (Haldi)", "2 Green Chillies , slit lengthwise", "1 sprig Curry leaves", "5 sprig Coriander (Dhania) Leaves , freshly chopped", "Salt , to taste", "Ingredients for Homemade Roasted Coconut Sambar Powder", "1/2 cup Fresh coconut , grated", "3 teaspoon Coriander (Dhania) Seeds", "4 Dry Red Chillies", "1 teaspoon Black Urad Dal (Split)", "1 teaspoon Chana dal (Bengal Gram Dal)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1/4 teaspoon Asafoetida (hing)", "1 Curry leaves , few", "1 teaspoon Coconut Oil", "Ingredients for Seasoning", "2 teaspoons Coconut Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "2 Shallots , finely sliced (optional)", "2 Dry Red Chillies", "1 sprig Curry leaves"]'::jsonb, ARRAY['tomato', 'asafoetida (hing)', 'carrot', 'curry leaves', 'coriander (dhania) seeds', 'bhindi (lady fingerokra)', 'turmeric powder', 'chana dal (bengal gram dal)', 'green chillies', 'coconut oil', 'salt', 'arhar dal (split toor dal)', 'dry red chillies', 'tamarind water', 'coconut', 'mustard seeds', 'methi seeds (fenugreek seeds)', 'potato (aloo) the skin large cubes', 'vellai poosanikai (ash gourdwhite pumpkin)', 'drumstick', 'black urad dal (split)', 'curry leaves', 'coriander (dhania) leaves']::text[], '["To begin making the Kerala Style Varutharacha Sambar recipe, we will first prepare the Homemade Roasted Coconut Sambar Powder.Heat oil in a heavy bottomed pan and add fenugreek seeds.", "Roast till lightly browned.", "Add in the split urad dal and chana dal.", "Roast until they turn golden brown.Once the dals turn brown add the asafoetida and fry for a few seconds till aroma comes through.", "Transfer this to a bowl and leave to cool.In the same pan, roast the coriander seeds and dry red chillies.", "Roast until till they give out a nice aroma and\u00a0 and the red chillies are lightly browned and roasted.", "Now add in the curry leaves and grated coconut and fry till the coconut turns brown (take care not to burn the coconut).", "Keep aside to cool.Once cooled grind all the ingredients in a spice grinder until all the dals and spices are ground into a coarse powder like texture.", "You can optionally add some water to grind to a fine paste.", "Once the powder is ready, the next step is to prepare the Varutharacha Sambar.In a pressure cooker add in the tamarind water, turmeric powder, salt and all the vegetables.", "Add a cup of water and cook until you hear two whistles.", "Turn off the heat and allow the pressure to release naturally.In a large sauce pan, combine the lentils, the cooked vegetables in tamarind water and the sambar powder.", "Stir to combine all the ingredients well.", "Check for the salt and spice levels and adjust according to taste.", "You can also adjust the consistency of the sambar by adding water if you like it thinner.", "Turn the heat on medium and begin to simmer the Varutharacha Sambar for about 5 to 6 minutes.", "While the sambar is simmering, we will now get the seasoning ready.", "Heat coconut oil in a small pan; add in the mustard seeds and allow it to crackle.Add finely sliced pearl onions and saute until they turn soft and light brown in colour.Add the dry red chillies and curry leaves and fry for a few seconds until the red chillies are roasted.", "This will take about 20 seconds.Pour the seasoning over the simmering Varutharacha Sambar and garnish with chopped coriander leaves.Turn off the heat and keep the sambar covered for about 10 to 15 minutes before you serve.Serve\u00a0Varutharacha Sambar along with\u00a0Carrot and Beans Thoran,\u00a0Steamed Rice\u00a0and\u00a0Elai Vadam\u00a0for a weekday meal.Note:1.", "Coconut oil enhances the flavour of the curry and lifts it to a whole new level.", "For health benefits, I tend to use a lesser quantity of coconut oil in my cooking.", "I avoided using coconut oil while frying the spices and grated coconut for the ground mixture.", "I only added it while preparing the seasoning/tempering.", "Please feel free to add more if you like the flavor.2.", "Don\u2019t limit your use of veggies to those I have mentioned in the recipe.", "You can add whichever vegetables are available in your refrigerator."]'::jsonb, 40, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Dal_Khadi_Curry/Kerala_Style_Varutharachu_Sambar__Lentils_Cooked_in_Tamarind_Spices_and_Roasted_Coconut-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1388.Kerala_Style_Varutharachu_Sambar__Lentils_Cooked_in_Tamarind_Spices_and_Roasted_Coconut-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Aam Ki Launji Pickle Recipe - Sweet & Spicy Mango Pickle', 'aam-ki-launji-pickle-recipe-sweet-spicy-mango-pickle', 'The Aam Ki Launji Pickle Recipe is a simple finger licking pickle made from fresh raw mangoes. The addition of methi seeds along with the hing, jaggery and other spices makes this dish stand out with perfection.', '["500 grams Mango (Raw) , peeled and chopped", "1/4 cup Jaggery", "1/2 teaspoon Red Chilli powder", "Salt , to taste", "1 tablespoon Oil", "1/2 teaspoon SSP Asafoetida (Hing)", "1/4 teaspoon Methi Seeds (Fenugreek Seeds)", "1 teaspoon Cumin seeds (Jeera)", "1 teaspoon Fennel seeds (Saunf)", "1/2 teaspoon Turmeric powder (Haldi)", "Black Salt (Kala Namak) , to taste", "1/2 teaspoon Garam masala powder"]'::jsonb, ARRAY['salt', 'black salt', 'asafoetida (hing)', 'fennel seeds (saunf)', 'jaggery', 'red chilli powder', 'mango', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'turmeric powder', 'garam masala powder', 'sunflower oil']::text[], '["To begin making Aam Ki Launji Pickle Recipe, wash and wipe\u00a0the mango, cut into wedges and set aside.", "Heat a pan with oil on medium heat, to this add the cumin seeds, fenugreek seeds, fennel seeds and allow them to sizzle.", "To this add hing and turmeric powder.", "Now add the freshly cut raw mango wedges and give it a good stir.", "To this mango mixture, add about three fourth cup of water, salt, black salt and red chilli powder.", "Mix thoroughly until the mixture is well combined.", "Cover and cook the mangoes for about 10 minutes on medium flame until it has softened.", "Sometimes it will take a little longer based on how raw the mangoes are.Open the lid, add the jaggery and garam masala.", "Stir to combine.", "Cook the Aam Ki Launji until the jaggery has completely melted and the mixture has thickened.", "Switch off the flame and allow the Aam Ki Launji Pickle to come to room temperature.Refrigerate the Aam Ki Launji Pickle Recipe in a glass bottle for about 2 to 3 weeks and use as required.Serve the Aam Ki Launji Pickle Recipe with\u00a0Tawa Paratha Recipe - Plain Paratha\u00a0and a cup of\u00a0Adrak Chai Recipe - Indian Style Ginger Tea\u00a0for a complete weekday breakfast."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/Aam_Ki_Launji_SSP_Step_By_Step_30_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1389.Aam_Ki_Launji_SSP_Step_By_Step_30_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('आम की लौंजी रेसिपी - Aam Ki Launji Recipe', 'aam-ki-launji-recipe', 'आम की लौंजी रेसिपी एक स्वाद से भरपूर साइड डिश है जिसमे आम का प्रयोग किया जाता है. इसमें मेथी के दाने के साथ साथ हींग, गुड़ और दूसरे मसालों का प्रयोग किया जाता है. आप इसे अपने खाने के साथ भी परोस सकते है या नाश्ते में पराठे के साथ परोस सकते है. आम की लौंजी को बनाकर आप स्टोर भी कर सकते है. इसे ज्यादातर उत्तर भारत के घर में बनाया जाता है.', '["500 \u0917\u094d\u0930\u093e\u092e \u0915\u091a\u094d\u091a\u093e \u0906\u092e , \u091b\u0940\u0932\u0915\u0930 \u0915\u093e\u091f \u0932\u0947", "1/4 \u0915\u092a \u0917\u0941\u095c", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0940\u0902\u0917", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u092e\u0947\u0925\u0940 \u0915\u0947 \u0926\u093e\u0928\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0938\u094c\u0902\u092b", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "\u0915\u093e\u0932\u093e \u0928\u092e\u0915 \u092f\u093e \u0938\u0947\u0902\u0927\u093e \u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930"]'::jsonb, ARRAY['ग्राम कच्चा आम', 'कप गुड़', 'छोटा चम्मच लाल मिर्च पाउडर', 'नमक', 'बड़ा चम्मच तेल', 'छोटा चम्मच हींग', 'छोटा चम्मच मेथी के दाने', 'छोटा चम्मच जीरा', 'छोटा चम्मच सौंफ', 'छोटा चम्मच हल्दी पाउडर', 'काला नमक या सेंधा नमक', 'छोटा चम्मच गरम मसाला पाउडर']::text[], '["\u0906\u092e \u0915\u0940 \u0932\u094c\u0902\u091c\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0906\u092e \u0915\u094b \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u0927\u094b \u0915\u0930 \u0938\u093e\u095e \u0915\u0930 \u0932\u0947. \u0905\u092c \u0907\u0928\u094d\u0939\u0947 \u0935\u0947\u0921\u094d\u091c\u0947\u0938 \u092e\u0947\u0902 \u0915\u093e\u091f \u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947. \u0907\u0938\u092e\u0947\u0902 \u091c\u0940\u0930\u093e, \u092e\u0947\u0925\u0940 \u0915\u0947 \u0926\u093e\u0928\u0947, \u0938\u094c\u0902\u092b\u00a0\u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0939\u0940\u0902\u0917, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0906\u092e \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 3/4 \u0915\u092a \u092a\u093e\u0928\u0940, \u0928\u092e\u0915, \u0915\u093e\u0932\u093e \u0928\u092e\u0915, \u0932\u093e\u0932 \u092e\u093f\u0930\u0939 \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0938\u092c\u0915\u094b \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947.\u0915\u095d\u093e\u0908 \u0915\u094b \u0922\u0915\u0947 \u0914\u0930 \u0906\u092e \u0915\u094b 10 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u0928\u0947 \u0926\u0947. 10 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0915\u095d\u093e\u0908 \u0916\u094b\u0932\u0947, \u0917\u0941\u0921, \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u0917\u093e\u095d\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e\u090f \u0914\u0930 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947. \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0926\u0947 \u0914\u0930 \u0917\u093f\u0932\u093e\u0938 \u0915\u0940 \u092c\u094b\u091f\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0938\u094d\u091f\u094b\u0930 \u0915\u0930\u0947\u0902\u0964\u00a0\u0906\u092e \u0915\u0940 \u0932\u094c\u0902\u091c\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0906\u0932\u0942 \u092a\u094d\u092f\u093e\u091c \u0915\u0940 \u0938\u092c\u094d\u095b\u0940\u00a0\u0914\u0930\u00a0\u0905\u091c\u0935\u093e\u0907\u0928 \u092a\u0942\u0930\u0940\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/poojanadkarni/Aam_Ki_Launji_SSP_Step_By_Step_30_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1390.Aam_Ki_Launji_SSP_Step_By_Step_30_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Bengali Luchi Recipe - Bengali Softa Maida Puffed Puri', 'bengali-luchi-recipe-bengali-softa-maida-puffed-puri', 'Bengali Luchi Recipe is the first thing that pops up in one''s mind when thinking about Bengali food. These fried puffed breads are made from all purpose flour gently deep fried and to be eaten with comforting aloo curries.', '["3 cups All Purpose Flour (Maida)", "2 tablespoons Ghee", "1/2 teaspoon Salt", "Oil , for deep frying", "Lukewarm Water , for kneading"]'::jsonb, ARRAY['salt', 'ghee', 'water', 'flour (maida)', 'sunflower oil']::text[], '["To begin making Bengali Style Luchi, first sift the flour with salt once into a large mixing bowl.Add oil or ghee to the same bowl and mix till incorporated.Make a well in the middle and add 1/2 cup of warm water.", "Gently mix the water and flour and start kneading with your fingers.Gradually add more warm water as needed will the dough becomes easy to knead into a dry ball that is firm to touch, but soft and pliable when rolled.Knead the luchi dough for about 3-4 minutes till you have a smooth dough, like you will need when making poori.Cover with the luchi dough with a wet muslin cloth and let it rest for 15-20 minutes.When you already to make the Luchis, divide the dough in to about 20 small round balls of equal size.Roll out each portion into a perfect ball, and using a rolling pin, roll out each dough ball to 1/4 inch thickness and about 3 inches in diameter.Proceed to roll them all out.", "Meanwhile, warm the oil in a kadai placed on medium heat, to begin deep frying the luchi.When the oil is hot, gently slide the rolled out luchi, one by one, into the kadai.", "Fry for a minute on either sides, till they are puffy and cooked.", "Do not brown the luchis.", "The traditional luchi looks like a white puffed poori.Remove from the oil with a slotted spoon and drain briefly on kitchen paper.Serve Luchi with\u00a0Bengali Cholar Dal\u00a0or with\u00a0Bengali Style Aloo Dum\u00a0for a comfort Sunday brunch."]'::jsonb, 50, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Bengali_Luchi_Recipe_Maida_Puri-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1391.Bengali_Luchi_Recipe_Maida_Puri-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Malabar Parotta Recipe - Kerala Parotta Recipe', 'malabar-parotta-recipe-kerala-parotta-recipe', 'Malabar Parotta or Kerala Parotta is a layered flatbread made from refined flour (maida). This is a traditional recipe from Kerala. At some places it is also served at weddings, religious festivals and feasts.', '["2 cups All Purpose Flour (Maida)", "2 tablespoons Ghee", "1/2 cup Milk", "1/2 teaspoon Sugar", "1 teaspoon Salt , to taste", "Lukewarm Water , as required"]'::jsonb, ARRAY['s all purpose flour', 'maida', 's ghee', 'milk', 'sugar', 'salt', 'lukewarm water']::text[], '["To begin making the Malabar/Kerala Parotta recipe, in a mixing bowl or a food processor, add the maida, ghee, milk, sugar, salt and sufficient lukewarm water and make a firm dough.Cover the malabar parotta dough and allow it to rest 15 to 20 minutes.Divide the malabar parotta dough into equal portions and roll them into balls.Place a ball on a worktop and roll the malabar/kerala parotta with the help of a rolling pin into thin sheet.Now apply some ghee on the rolled malabar parotta and dust it with the little maida.Make small pleats like an accordian and then bring the pleats together.", "Start to roll the malabar parotta into a round pinwheel from one end.", "Dust in flour and roll into a circular shape.Do the same with the remaining portion of the malabar parotta dough.", "Heat the tawa over medium heat; add the rolled out malabar/ kerala parotta and cook without ghee for a few seconds until the raw look goes away.", "Drizzle little ghee and cook the malabar parotta from both sides until lightly brown and crisp.Serve Malabar Parotta with\u00a0Vegetable Kurma\u00a0and\u00a0Kerala Style Egg Roast Curry Recipe\u00a0as a weeknight dinner or as a paratha for and indian party menu with friends and family."]'::jsonb, 55, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Malabar_Parotta_Recipe_Kerala_Parotta_Layered_Flaky_Recipes-3_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1392.Malabar_Parotta_Recipe_Kerala_Parotta_Layered_Flaky_Recipes-3_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('कीमा भिंडी रेसिपी - Keema Bhindi Recipe', 'keema-bhindi-recipe', 'कीमा एक ऐसी रेसिपी है जिसे सब पसंद करते है, जिसे आप रोटी, पराठा और चावल के साथ परोस सकते है. लेकिन यह हमने कीमा के साथ भिंडी को भी मिलाया है, जो इस डिश को क्रंच देता है. यह बनाने में बहुत आसान है और आप इसे अपने रोज के खाने के लिए बना सकते है.', '["500 \u0917\u094d\u0930\u093e\u092e \u091a\u093f\u0915\u0928 , \u092a\u0940\u0938 \u0932\u0947, \u0906\u092a \u092e\u091f\u0928 \u0915\u093e \u092d\u0940 \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948", "250 \u0917\u094d\u0930\u093e\u092e \u092d\u093f\u0902\u0921\u0940", "2 \u092a\u094d\u092f\u093e\u091c , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "2 \u091f\u092e\u093e\u091f\u0930 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0905\u0926\u0930\u0915 \u0932\u0939\u0938\u0941\u0928 \u0915\u093e \u092a\u0947\u0938\u094d\u091f", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0915\u0936\u094d\u092e\u0940\u0930\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930 , \u0938\u0947\u0915 \u0932\u0947", "1-1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932 , + 2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932 \u0924\u0932\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f", "\u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u0915\u093e\u091f \u0932\u0947, \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0947 \u0932\u093f\u090f", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0915\u0938\u0942\u0930\u0940 \u092e\u0947\u0925\u0940"]'::jsonb, ARRAY['ग्राम चिकन', 'ग्राम भिंडी', 'प्याज', 'टमाटर', 'बड़ा चम्मच अदरक लहसुन का पेस्ट', 'बड़ा चम्मच कश्मीरी लाल मिर्च पाउडर', 'छोटे चम्मच धनिया पाउडर', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच जीरा पाउडर', 'छोटा चम्मच गरम मसाला पाउडर', 'छोटे चम्मच तेल', 'हरा धनिया', 'छोटा चम्मच कसूरी मेथी']::text[], '["\u0915\u0940\u092e\u093e \u092d\u093f\u0902\u0921\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0938\u093e\u0930 \u0938\u093e\u092e\u0917\u094d\u0930\u0940 \u0924\u0948\u092f\u093e\u0930 \u0915\u0930\u0915\u0947 \u0930\u0916 \u0932\u0947. \u092d\u093f\u0902\u0921\u0940 \u0915\u094b \u0927\u094b \u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0942\u0916\u093e \u0915\u0947 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947. \u092d\u093f\u0902\u0921\u0940 \u0915\u0947 \u0915\u094b\u0928\u0947 \u0915\u093e\u091f \u0932\u0947 \u0914\u0930 \u092b\u093f\u0930 \u0915\u093e\u091f \u0915\u0947 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947\u0964\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u092d\u093f\u0902\u0921\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 4 \u0938\u0947 5 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u090f\u0915 \u0915\u093f\u091a\u0928 \u091f\u0949\u0935\u0932 \u092a\u0930 \u0928\u093f\u0915\u093e\u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u0905\u092c \u0909\u0938\u0940 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0905\u0926\u0930\u0915 \u0932\u0939\u0938\u0941\u0928 \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u0947\u00a03 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u091f\u092e\u093e\u091f\u0930 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u091f\u092e\u093e\u091f\u0930 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0915\u0936\u094d\u092e\u0940\u0930\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u091a\u093f\u0915\u0928 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940\u00a0\u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u091a\u093f\u0915\u0928 \u0915\u0947 \u092a\u0915\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947\u00a0\u0914\u0930 2 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u092d\u093f\u0902\u0921\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. 5 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947.\u00a0\u0915\u0940\u092e\u093e \u092d\u093f\u0902\u0921\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u092b\u0941\u0932\u094d\u0915\u093e\u00a0\u0914\u0930 \u092c\u0941\u0930\u093e\u0928\u0940 \u0930\u093e\u092f\u0924\u0947 \u0915\u0947 \u0938\u093e\u0925 \u0930\u093e\u0924 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 50, 'North Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Articles/Keema_Bhindi_Masala_Recipe_Video_8_1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1393.Keema_Bhindi_Masala_Recipe_Video_8_1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Traditional Bengali Rasgulla Recipe - Cottage Cheese Balls In Sweetened Syrup', 'traditional-bengali-rasgulla-recipe-cottage-cheese-balls-in-sweetened-syrup', 'Bengali rasgulla recipe is an excellent recipe for this regional classic from the state of West Bengal. Delicate cottage cheese dumplings, soaked in sugar syrup, they’re also called Rosogolla. The process has multiple steps, but yields a super soft rasgulla that is steamed and then soaked in a flavoured sugar syrup.', '["6 cups Milk", "3 tablespoons Lemon juice", "2 tablespoons Curd (Dahi / Yogurt)", "2 cups Sugar", "4-1/2 cups Water", "1/4 teaspoon Cardamom Powder (Elaichi)", "1 Cloves (Laung)"]'::jsonb, ARRAY['s milk', 's lemon juice', 's curd', 'dahi / yogurt', 's sugar', 's water', 'cardamom powder', 'elaichi', 'laung']::text[], '["To begin making the Bengali Rasgulla, first mix curd and lemon juice together in a bowl.", "Bring the milk to a roaring boil; when it starts to foam and rise, reduce the flame to medium and add curd-lemon juice mix and give it a stir.", "The milk will begin to curdle and get separated from the whey.", "When all the milk is curdled and only a clear whey remains, turn off the heat.The curdled milk is the cottage cheese, allow the milk to rest in the whey water for a few minutes.", "Spread a muslin cloth/cheese cloth (Make sure its big enough to get tied up) and drain the curdled milk.Now bring the edges of the cloth together and immerse it (up and down process) in a bowl filled with ice cubes and cold water.", "Slightly rub the bag so that it releases the lemon juice flavor and bring the curdled milk together to a ball.", "Squeeze water well and tie the bag.Now on a flat plate, first place the sack, then a tawa or plate and finally some heavy weight.", "This helps to squeeze all excess water.", "Let it sit for 1 hour without any disturbance, until you see a lot of whey is released.Remove the paneer from the muslin cloth and place it on a flat surface.", "Scramble and knead using your palm for 10 minutes.", "You can feel the paneer getting soft.", "Make them to equal-sized balls by rolling in your hand, making sure there are no cracks on the ball surface.In a pressure cooker (wide enough) boil sugar and water.", "When bubbles starts to form, add Cardamom powder, clove and paneer balls (one by one) slowly.", "Cover the cooker and pressure cook for 1 whistle.After a whistle, reduce the flame to low and let it simmer for another 5 minutes.", "Turn off the heat and allow the pressure come down.Once the pressure is completely released, open the cooker.", "You will notice the Rosogolla are doubled in their size.", "Replace the rasgullas carefully to another bowl, cool down completely.", "Refrigerate for 2 hours minimum before serving.NotesWash the paneer well to avoid lemon taste in rasgullas.Squeeze the maximum to drain the water and then place a weight.You can use the whey water for making chapati batter.Kneading the dough is a very important step to get the rasgullas soft.My friend''s mother suggested to add a teaspoon of maida and stir after kneading the paneer.", "This helps rasgullas to be a bit firm and withstands its round shape.If you feel the paneer is very much drained or is not binding while making balls, then drizzle some drops of water alone and knead again.Please make sure to use a wide cooker or pan as rasgulla expand after cooking.Do replace rasgullas to another bowl after cooking to avoid overheating.We can also prepare them in a large pan by simply closing them for 10 to 15 minutes after paneer balls are added.When rasgullas are cooked they are extremely soft but will get firm after refrigerating."]'::jsonb, 75, 'Bengali', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Traditional_Bengali_Rasgulla_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1394.Traditional_Bengali_Rasgulla_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Manipuri Style Alu Kangmet Recipe - Mashed Potato In Dry Red Chillies', 'manipuri-style-alu-kangmet-recipe-mashed-potato-in-dry-red-chillies', 'Manipuri Style Alu Kangmet Recipe is simply tossed mashed potatoes in roasted dry red chillies and salt. This dish has only three ingredients and is one of the everyday dishes of manipuris.', '["4 Potatoes (Aloo) , boiled", "4 Dry Red Chillies", "Salt , to taste", "Mustard oil , for cooking"]'::jsonb, ARRAY['dry red chillies', 'salt', 'potato (aloo)', 'mustard oil']::text[], '["To begin making the Manipuri Style Alu Kangmet Recipe, first pressure cook the potatoes with little water and salt for about 3 whistle.", "Release the pressure naturally and then peel off the skin.", "Mash the potatoes to a coarse mixture.Next\u00a0 into a preheated skillet add oil.", "Once the oil is hot add the dry red chillies and\u00a0roast them till they are crisp.", "Turn off the heat and remove the red chillies into a bowl and allow them to cool.Once the red chillies are cooled add them to a mixer grinder and\u00a0 grind the dry red chillies to a coarse mixture.Finally heat the same skillet with oil, then add in the ground chilli and potato, season it with salt and mix well to combine.Saute for another minute or two and turn off the heat.", "Transfer the\u00a0Manipuri Style Alu Kangmet into a serving bowl and serve.Serve the\u00a0Manipuri Style Alu Kangmet Recipe\u00a0along\u00a0with\u00a0Tan Ngang\u00a0which is the Manipuri Style Indian Puri or you can as well serve it with\u00a0Puri Recipe (Puffed Fried Indian Bread)\u00a0and your choice of Dal."]'::jsonb, 20, 'North East India', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Manipuri_Style_Alu_Kangmet_Recipe_Mashed_Potato_in_dry_red_chillies_Recipe.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1395.Manipuri_Style_Alu_Kangmet_Recipe_Mashed_Potato_in_dry_red_chillies_Recipe.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Manipuri Style Chak Angouba Recipe - Vegetable Pulao Recipe', 'manipuri-style-chak-angouba-recipe-vegetable-pulao-recipe', 'Rice is a staple food in Manipur. To make Manipuri Style Chak Angouba Recipe - Vegetable Pulao Recipe black rice is preferred  more than the normal white rice. Using black rice changes the flavour profile of Manipuri Style Chak Angouba completely. Fresh homegrown vegetables are added to make this delicious fried rice.', '["2 cups Cooked rice", "2 Carrots (Gajjar) , chopped", "300 grams Green beans (French Beans) , chopped", "1 Onion , chopped", "1 teaspoon Cumin seeds (Jeera)", "2 Green Chillies , chopped", "1 teaspoon Turmeric powder (Haldi)", "2 tablespoon Coriander Powder (Dhania)", "Salt , to taste", "4 sprig Chives , or spring onions,chopped (optional)", "Mustard oil , for cooking"]'::jsonb, ARRAY['salt', 'green beans (french beans)', 'rice', 'mustard oil', 'carrot', 'onion', 'cumin seeds (jeera)', 'chives spring onion', 'coriander powder', 'turmeric powder', 'green chillies']::text[], '["To begin making the Manipuri Style Chak Angouba Recipe\u00a0- Vegetable Pulao Recipe Into a preheated kadai add oil.", "Once the oil is hot add in the cumin seeds and let them crackle.Once the cumin seeds have crackled add the onions and green chillies and saute them till the onion turns translucent.Once done add in the carrot, green beans , salt and saute well till the vegetables are cooked.After the vegetables have cooked add the turmeric powder, coriander powder and mix well to combine.Add your cooked rice and season with salt, mix well and coat the vegetables and spice evenly with the rice.", "Once done turn off the heat and transfer the\u00a0Manipuri Style Chak Angouba into a serving dish.You can garnish with chopped chives or spring onions if you like and serve.", "Serve the Manipuri Style Chak Angouba Recipe\u00a0 along with\u00a0Smoked Tandoori Paneer Tikka Recipe\u00a0and\u00a0Lauki Raita Recipe\u00a0to finish your Sunday meal."]'::jsonb, 35, 'North East India', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Manipuri_Style_Chak_Angouba_Recipe_Vegetable_Pulao_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1396.Manipuri_Style_Chak_Angouba_Recipe_Vegetable_Pulao_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Vendakkai Thoran Recipe - Okra Stir Fry with Coconut', 'kerala-vendakkai-thoran-recipe-okra-stir-fry-with-coconut', 'Kerala Vendakkai Thoran is a simple and delicious preparation of Okra or Bhindi flavored with pearl onions, green chilies, and coconut. This style of making vegetable is very typical to South India especially Kerala.', '["350 grams Bhindi (Lady Finger/Okra) , cut into half with stem removed", "1/2 cup Fresh coconut , grated", "2 Green Chillies , finely chopped", "10 Pearl onions (Sambar Onions) , roughly chopped", "1 inch Ginger , peeled and grated", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "Salt , to taste", "6 Curry leaves", "2 tablespoons Oil"]'::jsonb, ARRAY['s bhindi', 'lady finger/okra', 'fresh coconut', 'reen chillies', 'pearl onions', 'sambar onions', 'ginger', 'mustard seeds', 'rai/ kadugu', 'white urad dal', 'split', 'salt', 'curry leaves', 's oil']::text[], '["To begin making the\u00a0Kerala Vendakkai Thoran, first grind the grated coconut along with the green\u00a0chilies\u00a0in mixer and grinder using little water to make a coarse paste.", "Transfer the paste to a bowl and keep aside until required.", "Next, heat 2 tablespoons of oil in a heavy-bottomed pan over medium heat.", "Add the mustard seeds, urad dal, curry leaves and allow them to crackle.", "Once they crackle, add the chopped onions and grated ginger.", "Saute till the onions become tender and translucent.", "Now add the Vendakkai\u00a0 and curry leaves, stir to combine.", "Add the salt to taste, cover the pan with the lid, turn the heat to low.", "Cook Vendakkai \u00a0for about 4 minutes or till the\u00a0vegetable is partially cooked through.", "Once the vegetable is partially cooked through, keep the lid of the pan slightly ajar, so some of the steam escapes out through the opening.", "We do this process, so the Vendakkai does not become soggy, but at the same time gets cooked well.Onced the\u00a0Vendakkai\u00a0 is cooked well,\u00a0add the grated coconut paste.", "Stir fry on medium heat for 5-10 minutes or till the aroma of roasted coconut is released.", "Turn off the heat.", "Transfer\u00a0Kerala Vendakka Thoran to the serving bowl.Serve the Kerala Vendakkai Thoran\u00a0along with Steamed Rice  and\u00a0sambar\u00a0for a wholesome lunch."]'::jsonb, 40, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Vendakkai_Thoran_Kerala_Style_Recipe_Okra_Stir_Fry_with_Coconut-8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1397.Vendakkai_Thoran_Kerala_Style_Recipe_Okra_Stir_Fry_with_Coconut-8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Boondi Raita Recipe Spiced With Black Salt', 'boondi-raita-recipe-spiced-with-black-salt', 'Boondi Raita Recipe is a simple and popular yogurt based dish served as an accompaniment to biryani, pulav or tehari.', '["1/2 cup Boondi", "1 cup Curd (Dahi / Yogurt) , Chilled", "1/2 teaspoon Chaat Masala Powder", "1/4 teaspoon Black Salt (Kala Namak)", "1/4 teaspoon Cumin powder (Jeera) , roasted", "Salt , to taste", "Red Chilli powder , to taste"]'::jsonb, ARRAY['boondi', 'curd', 'dahi / yogurt', 'chaat masala powder', 'black salt', 'kala namak', 'cumin powder', 'jeera', 'salt', 'red chilli powder']::text[], '["To begin making the boondi raita recipe, keep all the ingredients ready and keep aside.In a bowl, whisk yogurt, red chilli powder, chat masala powder, black salt, cumin powder and salt until well combined.Gently fold the boondi to the whisked yogurt.", "Transfer boondi raita to a serving dish and garnish with chopped coriander leaves.", "If the raita thickens up a bit after sometime, then you can add little water and whisk it well to get the desired consistency.Serve the Boondi Raita along with\u00a0Plain Paratha\u00a0and\u00a0Aloo Simla Mirch Ki Sabzi Recipe - Aloo & Capsicum Sabzifor lunch or dinner."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Raitas/Boondi_Raita_Recipe_Archanas_Kitchen_Yogurt_Dip_Vegetarian-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1398.Boondi_Raita_Recipe_Archanas_Kitchen_Yogurt_Dip_Vegetarian-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('हरा धनिया पराठा रेसिपी - Hara Dhania Paratha Recipe', 'hara-dhania-paratha-recipe', 'हरा धनिया पराठा रेसिपी एक सरल पराठा रेसिपी है जिसमे धनिये का प्रयोग किया जाता है. अगर आप अपनी सब्ज़ी के साथ रोटी नहीं बनाना चाहते, तो आप यह पराठा बना सकते है.', '["1-1/2 \u0915\u092a \u0917\u0947\u0939\u0942\u0902 \u0915\u093e \u0906\u091f\u093e", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "\u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u0925\u094b\u095c\u093e, \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u0915\u0938 \u0932\u0947", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "\u0924\u0947\u0932 , \u092f\u093e \u0918\u0940, \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['कप गेहूं का आटा', 'छोटा चम्मच जीरा पाउडर', 'छोटा चम्मच हल्दी पाउडर', 'हरा धनिया', 'हरी मिर्च', 'इंच अदरक', 'नमक', 'काली मिर्च पाउडर', 'तेल']::text[], '["\u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e \u092a\u0930\u093e\u0920\u093e \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0917\u0947\u0939\u0942\u0902 \u0915\u093e \u0906\u091f\u093e, \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0905\u0926\u0930\u0915, \u0928\u092e\u0915, \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0905\u092f\u094d\u092f\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947.\u0905\u092c \u0927\u0940\u0930\u0947 \u0927\u0940\u0930\u0947 \u0907\u0938\u092e\u0947\u0902 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0906\u091f\u0947 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u0917\u0941\u0902\u0926 \u0932\u0947. \u0907\u0938 \u092a\u0930 \u0925\u094b\u095c\u093e \u0924\u0947\u0932\u00a0\u0932\u0917\u093e\u090f \u0914\u0930 \u0922\u0915 \u0915\u0930 10 \u092e\u093f\u0928\u091f\u00a0\u0915\u0947 \u0932\u093f\u090f \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u0905\u092c \u0917\u0941\u0902\u0926\u0947 \u0939\u0941\u090f \u0906\u091f\u0947 \u092e\u0947\u0902 \u0938\u0947 \u0925\u094b\u095c\u093e \u0906\u091f\u093e \u0932\u0947 \u0914\u0930 \u0917\u094b\u0932 \u0917\u094b\u0932 \u0932\u094b\u0908 \u092c\u0928\u093e \u0932\u0947. \u0938\u0942\u0916\u0947 \u0906\u091f\u0947 \u092e\u0947\u0902 \u0921\u0938\u094d\u091f \u0915\u0930 \u0932\u0947 \u0914\u0930 \u0917\u094b\u0932 \u0917\u094b\u0932 \u092c\u0947\u0932 \u0932\u0947.\u090f\u0915 \u0924\u0935\u093e \u0917\u0930\u092e \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0930\u0916 \u0926\u0947. \u0905\u092c \u0907\u0938\u092a\u0930 \u092a\u0930\u093e\u0920\u093e \u0930\u0916\u0947\u0902, \u0925\u094b\u095c\u093e \u0918\u0940\u00a0\u0932\u0917\u093e\u090f \u0914\u0930 \u0938\u0947\u0915 \u0932\u0947. \u092a\u0932\u091f\u0947\u00a0\u0925\u094b\u095c\u093e \u0918\u0940 \u0914\u0930 \u0932\u0917\u093e\u090f \u0914\u0930 \u0926\u0942\u0938\u0930\u0940 \u0924\u0930\u092b \u0938\u0947 \u092d\u0940 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u0938\u0947\u0915 \u0932\u0947. \u092a\u0930\u094b\u0938\u0947\u0964 \u0910\u0938\u0947 \u0939\u0940 \u092c\u093e\u0915\u0940 \u0915\u0947 \u092c\u091a\u0947 \u0939\u0941\u090f \u092a\u0930\u093e\u0920\u0947 \u092d\u0940 \u092c\u0928\u093e \u0932\u0947."]'::jsonb, 40, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breads/Coriander_Paratha_Dhania_Roti_Chapati_Recipe-7.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1399.Coriander_Paratha_Dhania_Roti_Chapati_Recipe-7.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('अंकुरित हरे मूंग और कच्चे आम का सलाद रेसिपी - Green Moong Sprouts, Raw Mango Salad Recipe', 'green-moong-sprouts-raw-mango-salad-recipe', 'अंकुरित हरे मूंग और कच्चे आम का सलाद रेसिपी, एक दक्षिण भारतीय सलाद है जो बनाने में बहुत आसान है और आप इसे अपने खाने के साथ या स्नैक के लिए परोस सकते है. इसमें निम्बू का भी प्रयोग किया जाता है, जो इसका स्वाद और भी बढ़ाता है.', '["1/2 \u0915\u092a \u0905\u0902\u0915\u0941\u0930\u093f\u0924 \u092e\u0942\u0902\u0917", "1/2 \u0915\u092a \u0915\u091a\u094d\u091a\u093e \u0906\u092e , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1/2 \u0915\u092a \u0917\u093e\u091c\u0930 , \u0915\u0938 \u0932\u0947", "1/2 \u0915\u092a \u0915\u0915\u095c\u0940 , \u0915\u093e\u091f \u0932\u0947", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0915\u093e\u091f \u0932\u0947", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0928\u093f\u092e\u094d\u092c\u0942 \u0915\u093e \u0930\u0938", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u093e \u0924\u0947\u0932", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0940\u0902\u0917"]'::jsonb, ARRAY['कप अंकुरित मूंग', 'कप कच्चा आम', 'कप गाजर', 'कप ककड़ी', 'बड़े चम्मच हरा धनिया', 'हरी मिर्च', 'बड़ा चम्मच नारियल', 'छोटे चम्मच निम्बू का रस', 'नमक', 'छोटे चम्मच नारियल', 'तड़के के लिए', 'बड़ा चम्मच नारियल का तेल', 'छोटा चम्मच राइ', 'छोटा चम्मच हींग']::text[], '["\u0905\u0902\u0915\u0941\u0930\u093f\u0924 \u0939\u0930\u0947 \u092e\u0942\u0902\u0917 \u0914\u0930 \u0915\u091a\u094d\u091a\u0947 \u0906\u092e \u0915\u093e \u0938\u0932\u093e\u0926 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0939\u092e \u092e\u0942\u0928 \u0915\u094b \u0905\u0902\u0915\u0941\u0930\u093f\u0924 \u0915\u0930 \u0932\u0947\u0902\u0917\u0947\u0964 \u0906\u092a \u092c\u093e\u091c\u093e\u0930 \u0938\u0947 \u092d\u0940 \u0905\u0902\u0915\u0941\u0930\u093f\u0924 \u092e\u0942\u0902\u0917 \u0916\u0930\u0940\u0926 \u0938\u0915\u0924\u0947 \u0939\u0948.\u0905\u092c \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0915\u091a\u094d\u091a\u093e \u0906\u092e,\u00a0\u0917\u093e\u091c\u0930, \u0905\u0902\u0915\u0941\u0930\u093f\u0924 \u092e\u0942\u0902\u0917, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0928\u092e\u0915, \u0928\u093f\u092e\u094d\u092c\u0942 \u0915\u093e \u0930\u0938, \u0928\u093e\u0930\u093f\u092f\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092b\u093f\u0930 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947.\u0905\u092c \u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f \u090f\u0915 \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u093e \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0939\u0940\u0902\u0917 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0926\u0947.\u00a0\u0907\u0938 \u0924\u095c\u0915\u0947 \u0915\u094b \u0938\u0932\u093e\u0926 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u092a\u0930\u094b\u0938\u0947.\u00a0\u0905\u0902\u0915\u0941\u0930\u093f\u0924 \u0939\u0930\u0947 \u092e\u0942\u0902\u0917 \u0914\u0930 \u0915\u091a\u094d\u091a\u0947 \u0906\u092e \u0915\u093e \u0938\u0932\u093e\u0926 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u092a\u0902\u091a\u092e\u0947\u0932 \u0926\u093e\u0932,\u00a0\u092d\u093f\u0902\u0921\u0940 \u092e\u0938\u093e\u0932\u093e\u00a0\u0914\u0930\u00a0\u092b\u0941\u0932\u094d\u0915\u0947\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 10, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/April-26/Raw_Mango_Sprouts_Salad_Recipe-9.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1400.Raw_Mango_Sprouts_Salad_Recipe-9.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false);

