0\u0905\u092c \u090f\u0915 \u0938\u0949\u0938\u092a\u0948\u0928 \u092e\u0947\u0902 \u092a\u093e\u0928\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0917\u0948\u0938 \u0915\u0940 \u0906\u0902\u091a \u0927\u0940\u092e\u0940 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0907\u0938\u092e\u0947\u0902 \u0915\u0936\u094d\u092e\u0940\u0930\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a, \u091c\u0940\u0930\u093e, \u092c\u095c\u0940 \u0907\u0932\u093e\u0907\u091a\u0940, \u0907\u0932\u093e\u0907\u091a\u0940, \u0926\u093e\u0932\u091a\u0940\u0928\u0940, \u0932\u0949\u0928\u094d\u0917 \u0914\u0930 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947\u09645 \u0938\u0947 7 \u092e\u093f\u0928\u091f \u0924\u0915 \u0909\u092c\u0932\u0928\u0947 \u0926\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u093e\u0928\u0940 \u0915\u094b \u0928\u093f\u0915\u093e\u0932 \u0915\u0930 \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0930\u0916 \u0926\u0947. \u0916\u095c\u0947 \u092e\u0938\u093e\u0932\u094b \u0915\u094b \u0924\u0939\u0902\u0926\u093e \u0939\u094b\u0928\u0947 \u0926\u0947. \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0925\u094b\u095c\u0947 \u092a\u093e\u0928\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0940\u0938 \u0915\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947. \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0928\u093f\u0915\u093e\u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u092e\u0947\u0930\u093f\u0928\u0947\u091f \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093e\u0907\u091f \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u093f\u0902\u0917 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u092e\u091f\u0928, \u0926\u0939\u0940, \u092a\u093f\u0938\u093e \u0939\u0941\u0906 \u092e\u0938\u093e\u0932\u093e, \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915, \u0905\u0926\u0930\u0915 \u0932\u0939\u0938\u0941\u0928 \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. 30 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0* \u0915\u0930\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f\u00a0:\u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0915\u092e \u0938\u0947 \u0915\u092e 10 \u092e\u093f\u0928\u091f \u0932\u0917\u0947\u0902\u0917\u0947\u0964\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0905\u0926\u0930\u0915 \u0932\u0939\u0938\u0941\u0928 \u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u0917\u0932\u0947 1 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092e\u0947\u0930\u093f\u0928\u0947\u091f \u0915\u093f\u0906 \u0939\u0941\u0906 \u092e\u091f\u0928 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u0928\u092e\u0915, 1/2 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 25 \u092e\u093f\u0928\u091f \u0924\u0915 \u092f\u093e \u092e\u091f\u0928 \u0915\u0947 85 % \u092a\u0915\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u092c\u093f\u091a \u092e\u0947\u0902 \u090f\u0915 \u0915\u091f\u094b\u0930\u0940 \u092e\u0947\u0902 \u0917\u0930\u092e \u0915\u093f\u0906 \u0939\u0941\u0906 \u0915\u094b\u092f\u0932\u093e \u0930\u0916 \u0932\u0947. \u0907\u0938 \u092a\u0930 \u0918\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0915\u095d\u093e\u0908 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947.\u00a03 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0915\u095d\u093e\u0908 \u0916\u094b\u0932\u0947 \u0914\u0930 \u0915\u094b\u092f\u0932\u093e \u0915\u094b \u0928\u093f\u0915\u093e\u0932 \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0* \u0905\u092c \u0932\u093e\u0932 \u092e\u0949\u0938 \u092c\u093f\u0930\u092f\u093e\u0928\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f :\u0905\u092c \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0924\u0947\u091c \u092a\u0924\u094d\u0924\u093e, \u0915\u0936\u094d\u092e\u0940\u0930\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a, \u0907\u0932\u093e\u0907\u091a\u0940, \u092c\u095c\u0940 \u0907\u0932\u093e\u0907\u091a\u0940, \u0932\u0949\u0928\u094d\u0917, \u0926\u093e\u0932\u091a\u0940\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u0939\u0932\u094d\u0915\u093e \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0905\u0926\u0930\u0915 \u0932\u0939\u0938\u0941\u0928 \u0915\u093e \u092a\u0947\u0938\u094d\u091f, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u0938\u0947 2 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0915\u0936\u094d\u092e\u0940\u0930\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0932\u093e\u0932 \u092e\u0949\u0938 \u0915\u0930\u0940, \u091a\u093e\u0935\u0932, 4 \u0915\u092a \u092a\u093e\u0928\u0940, \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930\u00a0\u0928\u092e\u0915,\u00a0\u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e, \u092a\u0941\u0926\u0940\u0928\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u0915\u0941\u0915\u0930 \u0915\u094b \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 2 \u0938\u0947 3 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u094d\u0930\u0947\u0936\u0930 \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947. \u0915\u0941\u0915\u0930 \u0916\u094b\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u0932\u093e\u0932 \u092e\u093e\u0938 \u092c\u093f\u0930\u092f\u093e\u0928\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0927\u0928\u093f\u092f\u0947 \u0935\u093e\u0932\u093e \u0924\u095c\u0915\u093e \u0930\u093e\u092f\u0924\u093e,\u00a0\u092a\u0941\u0926\u0940\u0928\u093e \u092a\u094d\u092f\u093e\u091c \u0915\u091a\u0941\u092e\u094d\u092c\u0930 \u0938\u0932\u093e\u0926\u00a0\u0914\u0930 \u092a\u093e\u092a\u095c \u0915\u0947 \u0938\u093e\u0925 \u0938\u092a\u094d\u0924\u093e\u0939 \u0905\u0902\u0924 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 90, 'Rajasthani', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Affiliate-Articles/Rajasthani_Lal_Maas_Biryani_Recipe__75-2_N_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1651.Rajasthani_Lal_Maas_Biryani_Recipe__75-2_N_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('कॉर्न और मटर की करी रेसिपी - Corn And Peas Curry Recipe', 'corn-and-peas-curry-recipe', 'कॉर्न और मटर की करी रेसिपी एक सरल रेसिपी है जिसे आप अपने रोज के खाने के लिए बना सकते है. इस ग्रेवी में खड़े मसालो को रोस्ट करके पिसा जाता है. इसमें अदरक, प्याज और लहसुन का भी प्रयोग किया जाता है जोइसे और भी स्वादिष्ट बनाता है.', '["\u0915\u0949\u0930\u094d\u0928 \u0915\u094b \u092a\u0915\u093e \u0932\u0947", "2 \u0915\u0949\u0930\u094d\u0928 \u0915\u094b\u092c , 1 \u0907\u0902\u091a \u0915\u0947 \u091f\u0941\u0915\u095c\u094b \u092e\u0947\u0902 \u0917\u094b\u0932 \u0915\u093e\u091f \u0932\u0947", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u092a\u093e\u0928\u0940 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0917\u094d\u0930\u0947\u0935\u0940 \u0915\u0947 \u0932\u093f\u090f", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c", "5 \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932", "6 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915", "2 \u092a\u094d\u092f\u093e\u091c , \u092a\u0924\u0932\u093e \u0914\u0930 \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "2 \u091f\u0939\u0928\u0940 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "1/2 \u0915\u092a \u091f\u092e\u093e\u091f\u0930 \u092a\u094d\u092f\u0942\u0930\u0940", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0915\u0936\u094d\u092e\u0940\u0930\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1/4 \u0915\u092a \u0939\u0930\u0947 \u092e\u091f\u0930"]'::jsonb, ARRAY['कॉर्न को पका ले', 'कॉर्न कोब', 'नमक', 'पानी', 'ग्रेवी के लिए', 'छोटे चम्मच जीरा', 'छोटा चम्मच धनिये के बीज', 'सुखी लाल मिर्च', 'छोटे चम्मच तेल', 'कली लहसुन', 'इंच अदरक', 'प्याज', 'बड़े चम्मच नारियल', 'छोटा चम्मच राइ', 'टहनी कढ़ी पत्ता', 'कप टमाटर प्यूरी', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच गरम मसाला पाउडर', 'छोटा चम्मच कश्मीरी लाल मिर्च पाउडर', 'कप हरे मटर']::text[], '["\u0915\u0949\u0930\u094d\u0928 \u0914\u0930 \u092e\u091f\u0930 \u0915\u0940 \u0915\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u0939\u092e \u0915\u0949\u0930\u094d\u0928 \u0915\u094b \u092a\u0915\u093e \u0932\u0947\u0902\u0917\u0947\u0964\u00a0\u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0915\u0949\u0930\u094d\u0928 \u0915\u094b \u0928\u092e\u0915, \u092a\u093e\u0928\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u094b \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947.\u092a\u094d\u0930\u0947\u0936\u0930 \u0928\u093f\u0915\u0932\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0915\u0941\u0915\u0930 \u0916\u094b\u0932\u0947, \u092a\u093e\u0928\u0940 \u0928\u093f\u0915\u093e\u0932 \u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947. \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u092c\u093f\u091a \u092e\u0947\u0902 \u0938\u0947 \u0917\u094b\u0932 \u0915\u093e\u091f \u0932\u0947.\u00a0\u0905\u092c \u0917\u094d\u0930\u0947\u0935\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u090f\u0915 \u0915\u095d\u093e\u0908 \u0915\u094b \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u091c\u0940\u0930\u093e, \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c, \u0938\u0941\u0916\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 3 \u0938\u0947 5 \u092e\u093f\u0928\u091f \u0924\u0915 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u0938\u0947\u0915 \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0907\u0938 \u092e\u093f\u0936\u094d\u0930\u0923 \u0915\u094b \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0926\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u0905\u092c \u090f\u0915 \u0926\u0942\u0938\u0930\u0940 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0932\u0939\u0938\u0941\u0928, \u0905\u0926\u0930\u0915, \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0914\u0930 \u092d\u0942\u0930\u0947 \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0928\u093e\u0930\u093f\u092f\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0926\u0947 \u0914\u0930 \u0907\u0938 \u092e\u093f\u0936\u094d\u0930\u0923 \u0915\u094b \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0930\u094b\u0938\u094d\u091f \u0915\u093f\u092f\u0947 \u0939\u0941\u090f \u092e\u0938\u093e\u0932\u0947, \u0932\u0939\u0938\u0941\u0928 \u092a\u094d\u092f\u093e\u091c \u0905\u0926\u0930\u0915 \u0915\u093e \u092e\u093f\u0936\u094d\u0930\u0923, \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0940\u0938 \u0915\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947. \u0924\u095c\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930 \u0915\u0940 \u092a\u094d\u092f\u0942\u0930\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u092c\u0932\u0928\u0947 \u0926\u0947. \u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u092a\u093f\u0938\u093e \u0939\u0941\u0906 \u092a\u094d\u092f\u093e\u091c \u0915\u093e \u092e\u0938\u093e\u0932\u093e \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930, \u0915\u0936\u094d\u092e\u0940\u0930\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a02 \u092e\u093f\u0928\u091f \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0909\u092c\u0932\u0947 \u0939\u0941\u090f \u0915\u0949\u0930\u094d\u0928, \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930 \u092a\u093e\u0928\u0940, \u092e\u091f\u0930 \u0921\u093e\u0932\u0947, \u0915\u095d\u093e\u0908 \u0915\u094b \u0922\u0915\u0947 \u0914\u0930 3 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947.\u00a0\u0915\u0949\u0930\u094d\u0928 \u0914\u0930 \u092e\u091f\u0930 \u0915\u0940 \u0915\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u0932\u091a\u094d\u091b\u093e \u092a\u0930\u093e\u0920\u093e \u0914\u0930\u00a0\u0932\u094c\u0915\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 55, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Sweet_On_The_Cob_Corn_Peas_Curry_Recipe_Bhutte_Matar_Ki_Sabzi_8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1652.Sweet_On_The_Cob_Corn_Peas_Curry_Recipe_Bhutte_Matar_Ki_Sabzi_8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('पुदीना किनुआ रेसिपी - Pudina Quinoa Recipe', 'pudina-quinoa-recipe-2', 'पुदीना किनुआ रेसिपी एक सरल रेसिपी है जिसमे रोज के मसालों और पुदीना का प्रयोग किया जाता है. इसमें हमने राइस की जगह किनुआ का प्रयोग किया गया है जो इस डिश को और भी सेहतमंद बनाता है.', '["1 \u0915\u092a \u0915\u093f\u0928\u0941\u0906", "1 \u092a\u094d\u092f\u093e\u091c , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "6 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u0907\u0902\u091a \u0926\u093e\u0932\u091a\u0940\u0928\u0940", "2 \u0932\u0949\u0928\u094d\u0917", "2 \u0907\u0932\u093e\u0907\u091a\u0940", "1/4 \u092a\u0941\u0926\u0940\u0928\u093e , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "\u0928\u092e\u0915", "1 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0915\u093e\u091f \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0918\u0940"]'::jsonb, ARRAY['कप किनुआ', 'प्याज', 'कली लहसुन', 'इंच दालचीनी', 'लॉन्ग', 'इलाइची', 'पुदीना', 'नमक', 'हरी मिर्च', 'छोटा चम्मच घी']::text[], '["\u092a\u0941\u0926\u0940\u0928\u093e \u0915\u093f\u0928\u0941\u0906 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 1 \u0915\u092a \u0915\u093f\u0928\u0941\u0906 \u0915\u094b \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u0927\u094b \u0932\u0947 \u0914\u0930 2 \u0918\u0902\u091f\u0947 \u0915\u0947 \u0932\u093f\u090f \u092d\u093f\u0917\u094b \u0926\u0947.\u00a0\u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u0918\u0940 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0918\u0940 \u0917\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0932\u0939\u0938\u0941\u0928, \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u093e\u091c \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a, \u0915\u093f\u0928\u0941\u0906, \u0926\u093e\u0932\u091a\u0940\u0928\u0940, \u0932\u0949\u0928\u094d\u0917, \u0907\u0932\u093e\u0907\u091a\u0940, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0938\u092c\u0915\u094b \u0924\u0947\u095b \u0906\u0902\u091a \u092a\u0930 2 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a02 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947, \u0915\u0941\u0915\u0930 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 2 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. 2 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0906\u0902\u091a \u0927\u0940\u092e\u0940 \u0915\u0930\u0947\u0902 \u0914\u0930 15 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947. \u092a\u094d\u0930\u0947\u0936\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947.\u00a0\u092a\u094d\u0930\u0947\u0936\u0930 \u0928\u093f\u0915\u0932\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0915\u0941\u0915\u0930 \u0916\u094b\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u090f\u0915 \u0938\u0930\u094d\u0935\u093f\u0902\u0917 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947\u0964\u00a0\u092a\u0941\u0926\u0940\u0928\u093e \u0915\u093f\u0928\u0941\u0906 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u0922\u0940\u0902\u0917\u0930\u0940 \u092e\u091f\u0930 \u0914\u0930\u00a0\u091f\u092e\u093e\u091f\u0930 \u0915\u0915\u095c\u0940 \u092a\u094d\u092f\u093e\u091c \u0930\u093e\u092f\u0924\u093e\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0930\u093e\u0924 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 30, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Pudina_Quinoa_Pulao_Recipe_6_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1653.Pudina_Quinoa_Pulao_Recipe_6_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Green Moong Dal Pulao With Vegetables Recipe', 'green-moong-dal-pulao-with-vegetables-recipe', 'The Green Moong Dal Biryani With Vegetables, is a combination that is wholesome and yet packed with spices, flavours, and taste. I came up with this Biryani Recipe when I was packing the kids lunch boxes and then I realised that I wanted to include more protein in their diet.', '["1 tablespoon Ghee", "1/2 teaspoon Cumin seeds (Jeera)", "1 Onion , roughly chopped", "2 cloves Garlic", "1 inch Ginger , finely chopped", "2 Green Chillies , slit", "2 Cardamom (Elaichi) Pods/Seeds", "1 inch Cinnamon Stick (Dalchini)", "2 Tomatoes , finely chopped or pureed", "1/2 cup Green beans , finely chopped", "2 Carrots , finely chopped", "1/2 teaspoon Turmeric powder (Haldi)", "1 cup Green Moong Dal (Whole) , soaked for 5 to 6 hours", "1 cup Rice", "Salt , to taste", "2-1/2 cups Water"]'::jsonb, ARRAY['ghee', 'cumin seeds', 'jeera', 'onion', 's garlic', 'ginger', 'reen chillies', 'cardamom', 'elaichi', 'cinnamon stick', 'dalchini', 'tomatoes', 'green beans', 'carrots', 'turmeric powder', 'haldi', 'green moong dal', 'whole', 'rice', 'salt', 's water']::text[], '["To begin making\u00a0Green Moong Dal Biryani With Vegetables, soak the green moong beans for 5 to 6 hours or overnight.", "Wash and soak the rice in 2 cups of water for about an hour.", "Drain the water and keep it aside.Heat ghee in the pressure cooker\u00a0on\u00a0medium heat; add the cumin seeds and allow them to crackle.", "Add in cinnamon and cardamom pods, allow them to release their aroma.Stir in the ginger, garlic, green chillies and onion and saute on medium heat until the onion turns translucent and soft and begin to get a sweet smell.Stir in the tomato puree or chopped tomatoes and turmeric powder.", "Saut\u00e9 the above mixture until the tomatoes have cooked through.", "Stir in the rice, soaked green moong, vegetables and salt along with 2-1/2 cups of water.Cover the pressure cooker and cook the Green Moong Biryani for 3 to 4 whistles and turn off the heat.", "Allow the pressure to release naturally.", "Once the pressure releases, open the pressure cooker, stir in the chopped coriander leaves and transfer the\u00a0Green Moong Dal Biryani to a serving bowl and serve hot.Green Moong Dal Biryani With Vegetables\u00a0makes a great wholesome one dish meal along with\u00a0Tomato Onion Cucumber Raita.", "Serve it for your everyday meals along with a Papad."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Green_Moong_Dal_Pulao_Recipe_With_Tomato_Onion_Raita_5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1654.Green_Moong_Dal_Pulao_Recipe_With_Tomato_Onion_Raita_5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paruppu Thogayal Recipe -Toor & Bengal Gram Chutney', 'paruppu-thogayal-recipe-toor-bengal-gram-chutney', 'Paruppu Thuvaiyal a speciality of Andhra Pradesh. It is a coarse chutney made using lentils. In this chutney, a paste is formed using Toor dal and Bengal Gram and is tempered with the south Indian tempering.', '["1/4 cup Arhar dal (Split Toor Dal)", "1/8 cup Roasted Gram Dal (Pottukadalai)", "1/2 tablespoon Whole Black Peppercorns", "5 Dry Red Chillies", "1 Onion , finely chopped", "2 tablespoons Fresh coconut , grated", "Salt , to taste", "1 pinch Jaggery", "1 teaspoon Tamarind Paste", "1 teaspoon Oil", "1/4 teaspoon Asafoetida (hing)", "Salt , as needed"]'::jsonb, ARRAY['arhar dal', 'split toor dal', 'roasted gram dal', 'pottukadalai', 'whole black peppercorns', 'dry red chillies', 'onion', 's fresh coconut', 'salt', 'jaggery', 'tamarind paste', 'oil', 'asafoetida', 'hing']::text[], '["To begin making the Paruppu Thuvaiyal recipe, dry roast toor dal, bengal gram, peppercorns, red chillies till the lentils turn golden colour.", "Set it aside.In the same pan, while it is still hot add the coconut and saute till it dries out.Add just enough water, salt, sugar, coconut, tamarind paste and the dal into the blender jar and blend it into a coarse chutney.Thuvaiyal is usually thick and not runny like chutney.Heat oil in a small tadka pan.", "Add hing and mustard seeds.", "Let it crackle.Add the tadka to the thuvaiyal and serve hot.", "Serve Paruppu\u00a0Thuvaiyal with hot Steamed Rice  and ghee for lunch or with\u00a0Ragi and Oats Dosa\u00a0for breakfast."]'::jsonb, 35, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Madhuri_Aggarwal/Parupu_Thuvaiyal.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1655.Parupu_Thuvaiyal.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Creamy Phirni Recipe - North Indian Rice Pudding', 'creamy-phirni-recipe-north-indian-rice-pudding', 'Phirni is creamy milk based sweet dish popular in North Indian cuisine and even in Pakistani cuisine. The method of preparation of phirni is quite easy and its presentation makes the dish quite palatable. Phirni recipe can be prepared with various common and exotic ingredients.', '["250 grams Milk , full cream", "1/2 cup Rice , soaked in water for at least 3 hours", "2 Cardamom (Elaichi) Pods/Seeds , crushed", "1 cup Sugar , adjustable", "2 tablespoons Whole Almonds (Badam) , thinly sliced"]'::jsonb, ARRAY['rice', 'cardamom (elaichi) podsseeds', 'sugar', 'badam (almond)', 'milk full']::text[], '["To begin making the Creamy Phirni recipe, drain the soaked\u00a0rice and add it to a mixer grinder.", "Grind the rice coarsely in a\u00a0grinder\u00a0by adding a little water or milk.", "The texture should be of fine grains and should not become a paste.Boil milk in a heavy bottomed pan.Once it starts boiling, add green cardamom into the milk.", "Add sugar in the boiling milk and then add rice into it.", "Stir continuously it for at-least 20 minutes or till the rice gets cooked and the mixture turns slighlty thick.When it starts getting thick, turn off the heat and let the phirni cool properly.Pour the creamy phirni in kullads (earthen pots), top with pistachios and cover the pots.", "Keep it in fridge for 2 to 3 hours.", "Now take it out, garnish it with sliced almonds or pistachios and serve it chilled.Serve Creamy Phirni as a dessert after your scrumptious meal or make it during Ramadan to celebrate the festival.Serve Creamy Phirni with delicious meal of\u00a0Aloo Gobi Ki Sabzi,\u00a0Ajwain Puri\u00a0and\u00a0Boondi Raita\u00a0on a weekend for brunch or a meal."]'::jsonb, 90, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Creamy_Phirni_Recipe_North_Indian_Rice_Pudding-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1656.Creamy_Phirni_Recipe_North_Indian_Rice_Pudding-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Paneer Carrot Stuffed Paratha Recipe', 'paneer-carrot-stuffed-paratha-recipe', 'Paneer Carrot Stuffed Paratha is a simple and nutritious Indian flat bread that is made from grated carrots and whole wheat flour. The paratha is delicately flavoured with roasted cumin powder and lots of chopped mint leaves. There are many additions that you can make to pep up the taste, by adding onions or even chopped cabbage or grated cheese for kids. I most often pack this paratha for kids lunch box along with a sweet lime pickle and some yogurt.', '["2 cups Whole Wheat Flour", "1/2 teaspoon Salt", "1 teaspoon Oil", "Water , as required", "1 cup Paneer (Homemade Cottage Cheese)", "1 cup Carrot (Gajjar) , grated", "1 Onion , finely chopped", "2 Green Chillies , finely chopped", "1 teaspoon Cumin powder (Jeera)", "1/4 cup Mint Leaves (Pudina) , small bunch,finely chopped", "Salt , to taste", "Ghee , or oil for cooking"]'::jsonb, ARRAY['salt', 'wheat flour', 'cumin powder (jeera)', 'paneer', 'water', 'carrot', 'onion', 'ghee', 'oil', 'mint leaves (pudina)', 'green chillies', 'sunflower oil']::text[], '["To begin making the Paneer Carrot Stuffed Paratha, we will first make the dough.Add in the flour and a pinch of salt into a large bowl.", "Add a little water at a time and knead to make a firm yet smooth dough.", "Knead well for about 3 to 4 minutes, this will make the parathas soft.Drizzle a teaspoon of oil over the dough and knead for another couple of minutes.", "Cover and keep aside till we make the Paneer Carrot filling for the paratha.Next, we will combine the paneer, grated carrots,onions, green chillies, mint leaves, cumin powder and salt.", "Stir to combine the ingredients well.", "We fill be using raw carrots as a stuffing as they will get cooked while cooking the parathas.Now to begin making the Paneer Carrot Stuffed Paratha, keep some flour aside for dusting.", "Divide the dough into large lemon side balls.Dust the dough portions in flour, flatten it and roll it into a 3 inch diameter circle.", "Place the Paneer Carrot filling on half side of the circle and close the paratha by folding it with the other half.", "Yes its as simple as that.", "We will have a semi-circle oval shape.", "Press the sides of the paratha down to seal the edges and gently using the rolling pin\u00a0 flatten it.", "Take care, the filling can ooze out if the dough is rolled out too thin.Now to cook the Paneer Carrot Stuffed Paratha, first preheat the skillet on medium heat.", "Place the rolled paneer carrot paratha on top and allow it to cook on one side.", "After about 10 to 15 seconds, flip the paratha.At this stage, smear some oil or ghee to cook the paratha.", "Cook the paratha by flipping over a couple of times until you see golden brown spots on both sides.Proceed the same way with the remaining dough portions.Serve the Paneer Carrot Stuffed Paratha Recipe with\u00a0sweet lime pickle\u00a0or\u00a0Tomato Onion Cucumber Raita."]'::jsonb, 55, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/Paneer_Carrot_Stuffed_Paratha_Raita_10_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1657.Paneer_Carrot_Stuffed_Paratha_Raita_10_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('पूरी रेसिपी - Puri Recipe', 'puri-recipe', 'पूरी रेसिपी एक भारतीय ब्रेड है जिसे हर घर में बनाया जाता है. इस डिश को आप हर भारतीय ग्रेवी या सुखी सब्ज़ी के साथ परोस। इसे गेहूं के आटे से बनाया जाता है. इसमें हम कलोंजी के बीज, सौंफ या अजवाइन का प्रयोग करते है जो इसे और भी फ्लेवर से भरपूर बनाता है.', '["2 \u0915\u092a \u0917\u0947\u0939\u0942\u0902 \u0915\u093e \u0906\u091f\u093e", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0915\u0932\u094b\u0902\u091c\u0940 \u0915\u0947 \u092c\u0940\u091c , \u092f\u093e \u0938\u094c\u0902\u092b \u092f\u093e \u0905\u091c\u0935\u093e\u0907\u0928", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['कप गेहूं का आटा', 'छोटे चम्मच तेल', 'छोटा चम्मच कलोंजी के बीज', 'नमक']::text[], '["\u092a\u0942\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u093f\u0902\u0917 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0917\u0947\u0939\u0942\u0902 \u0915\u093e \u0906\u091f\u093e, \u0915\u0932\u094b\u0902\u091c\u0940 \u0915\u0947 \u092c\u0940\u091c, \u0928\u092e\u0915, 2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u0905\u092c \u0925\u094b\u095c\u093e \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0915\u0930 \u0906\u091f\u0947 \u0915\u094b \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u0928\u0930\u092e \u0917\u0941\u0902\u0926 \u0932\u0947.1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932 \u0914\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092b\u093f\u0930 \u0938\u0947 \u0917\u0941\u0902\u0926 \u0932\u0947. \u0906\u091f\u0947 \u0915\u094b \u0922\u0915 \u0932\u0947 \u0914\u0930 15 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a015 \u092e\u093f\u0928\u091f \u092c\u093e\u0926 \u090f\u0915 \u092c\u093e\u0930 \u0914\u0930 \u0917\u0941\u0902\u0926 \u0932\u0947. \u0917\u0941\u0902\u0926\u0947 \u0939\u0941\u090f \u0906\u091f\u0947 \u092e\u0947\u0902 \u0938\u0947\u00a0\u091b\u094b\u091f\u0947 \u091b\u094b\u091f\u0947 \u091f\u0941\u0915\u095c\u0947 \u0932\u0947, \u092c\u0947\u0932 \u0915\u0930 \u091b\u094b\u091f\u0940 \u091b\u094b\u091f\u0940 \u092a\u0924\u0932\u0940 \u092a\u0942\u0930\u0940 \u092c\u0928\u093e \u0932\u0947.\u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0927\u0940\u092e\u0940 \u0906\u0902\u091a \u092a\u0930 \u0930\u0916\u0947\u0902\u0964\u00a0\u0924\u0947\u0932 \u0915\u0947 \u0917\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092a\u0942\u0930\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0938\u0941\u0928\u0939\u0930\u093e \u092d\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0906\u092a \u0926\u0947\u0916\u0947\u0902\u0917\u0947 \u0915\u0940 \u0906\u092a\u0915\u0940 \u092a\u0942\u0930\u0940 \u092b\u0942\u0932 \u0930\u0939\u0940 \u0939\u0948. \u091c\u094d\u092f\u093e\u0926\u093e \u0924\u0947\u0932 \u0938\u094b\u0916 \u0932\u0947\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u093f\u091a\u0928 \u091f\u0949\u0935\u0932 \u092a\u0930 \u0928\u093f\u0915\u093e\u0932\u0947\u0964 \u0917\u0930\u092e \u0917\u0930\u092e \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092a\u0942\u0930\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0915\u0932\u094b\u0902\u091c\u0940 \u0935\u093e\u0932\u0940 \u0906\u0932\u0942 \u0917\u094b\u092d\u0940 \u0915\u0940 \u0938\u092c\u094d\u095b\u0940\u00a0\u0914\u0930\u00a0\u092c\u0942\u0902\u0926\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0938\u0941\u092c\u0939 \u0915\u0947 \u0928\u093e\u0936\u094d\u0924\u0947 \u092f\u093e \u0905\u092a\u0928\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 35, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2018/Puri_Recipe_Traditional_Homemade-2.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1658.Puri_Recipe_Traditional_Homemade-2.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('बैंगलोर रेस्टोरेंट स्टाइल सांबर रेसिपी - Bangalore Restaurant Style Sambar Recipe', 'bangalore-restaurant-style-sambar-recipe', 'बैंगलोर रेस्टोरेंट स्टाइल सांबर एक स्वादिष्ट रेसिपी है जिसे आप इडली या वडा के साथ परोस सकते है. यह सांबर पतला होता है और इसे गूढ़ से मीठा किया गया है. आप इसमें आप पसंद की सब्ज़िओ का प्रयोग कर सकता है.', '["1/2 \u091c\u0940\u0930\u093e", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c", "4 \u092c\u094d\u092f\u093e\u0926\u0917\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "3 \u0917\u0941\u0902\u091f\u0942\u0930 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a", "1/3 \u0915\u092a \u0928\u093e\u0930\u093f\u092f\u0932 , \u0915\u0938 \u0932\u0947", "1/2 \u0915\u092a \u0905\u0930\u0939\u0930 \u0926\u093e\u0932 , \u0927\u094b \u0932\u0947", "150 \u0917\u094d\u0930\u093e\u092e \u091b\u094b\u091f\u0947 \u092a\u094d\u092f\u093e\u091c , \u0915\u093e\u091f \u0932\u0947", "1 \u092a\u094d\u092f\u093e\u091c , \u0915\u093e\u091f \u0932\u0947", "2 \u091f\u092e\u093e\u091f\u0930 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "8 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0940\u0902\u0917", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c", "1 \u0915\u092a \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u093e\u0928\u0940", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0917\u0941\u095c , \u0915\u0938 \u0932\u0947", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0924\u0947\u0932 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "4 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0939\u0930\u093e \u0927\u0928\u093f\u092f\u093e , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947"]'::jsonb, ARRAY['जीरा', 'छोटे चम्मच धनिये के बीज', 'ब्यादगी लाल मिर्च', 'गुंटूर लाल मिर्च', 'कप नारियल', 'कप अरहर दाल', 'ग्राम छोटे प्याज', 'प्याज', 'टमाटर', 'कढ़ी पत्ता', 'छोटा चम्मच राइ', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच हींग', 'कप इमली का पानी', 'बड़ा चम्मच गुड़', 'नमक', 'तेल', 'बड़े चम्मच हरा धनिया']::text[], '["\u092c\u0948\u0902\u0917\u0932\u094b\u0930 \u0930\u0947\u0938\u094d\u091f\u094b\u0930\u0947\u0902\u091f \u0938\u094d\u091f\u093e\u0907\u0932 \u0938\u093e\u0902\u092c\u0930 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0926\u093e\u0932 \u0915\u094b \u0927\u094b \u0932\u0947 \u0914\u0930 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, 1 \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932, \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930 \u092a\u093e\u0928\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915 \u0915\u0930 \u0932\u0947.\u00a0\u0905\u092c \u090f\u0915 \u092e\u0947\u0936\u0930 \u0915\u0940 \u092e\u0926\u0926 \u0938\u0947 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u0948\u0936 \u0915\u0930 \u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u091c\u0940\u0930\u093e, \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c, \u0917\u0941\u0902\u091f\u0942\u0930 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a, \u092c\u094d\u092f\u093e\u0926\u0917\u0940 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u0927\u0940\u092e\u0940 \u0906\u0902\u091a \u092a\u0930 \u0938\u0947\u0915 \u0932\u0947. 2 \u092e\u093f\u0928\u091f \u092c\u093e\u0926, \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947 \u0914\u0930 \u0907\u0938 \u092e\u093f\u0936\u094d\u0930\u0923 \u0915\u094b \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0926\u0947.\u00a0\u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0928\u093e\u0930\u093f\u092f\u0932, \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0940\u0938 \u0915\u0930 \u092a\u0947\u0938\u094d\u091f \u092c\u0928\u093e \u0932\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u092b\u093f\u0930 \u0938\u0947 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u0930\u093e\u0907 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0924\u095c\u0915\u0928\u0947 \u0926\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0939\u0940\u0902\u0917, \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e, \u091b\u094b\u091f\u0947 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u0925\u094b\u095c\u093e \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u092a\u093f\u0938\u093e \u0939\u0941\u0906 \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0907\u0938\u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u092a\u0915\u0940 \u0939\u0941\u0908 \u0926\u093e\u0932 \u0915\u093e \u092e\u093f\u0936\u094d\u0930\u0923, \u0928\u092e\u0915, \u0907\u092e\u0932\u0940 \u0915\u093e \u092a\u093e\u0928\u0940, 1-2 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0926\u0947.\u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902, \u0939\u0930\u0947 \u0927\u0928\u093f\u092f\u0947 \u0938\u0947 \u0917\u093e\u0930\u094d\u0928\u093f\u0936 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092c\u0948\u0902\u0917\u0932\u094b\u0930 \u0930\u0947\u0938\u094d\u091f\u094b\u0930\u0947\u0902\u091f \u0938\u094d\u091f\u093e\u0907\u0932 \u0938\u093e\u0902\u092c\u0930 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b \u0939\u094b\u092e\u092e\u0947\u0921 \u0938\u0949\u092b\u094d\u091f \u0907\u0921\u0932\u0940,\u00a0\u0928\u093e\u0930\u093f\u092f\u0932 \u0915\u0940 \u091a\u091f\u0928\u0940\u00a0\u0914\u0930 \u095e\u093f\u0932\u094d\u091f\u0930 \u0915\u0949\u092b\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0938\u0941\u092c\u0939 \u0915\u0947 \u0928\u093e\u0936\u094d\u0924\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 40, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/gauravi/Bangalore_Hotel_style_Sambhar.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1659.Bangalore_Hotel_style_Sambhar.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Prawns Biryani Recipe', 'prawns-biryani-recipe', 'No one can deny their love for Biryani. Biryanis are versatile and can be prepared with either chicken, meat, prawns, fish or even with vegetables.Biryani weather veg or non veg is  must in a royal feast. The type and preparation for Biryani vary from region to region. The ingredients used also varies according to the culture and people. Biryanis can be prepared spicy in Hyderabadi style or can be made sweet like Kashmiri ones.', '["1 tablespoon Ajwain (Carom seeds)", "1 tablespoon Fennel seeds (Saunf)", "5 Cardamom (Elaichi) Pods/Seeds", "5 Clove powder (Laung)", "4 Cinnamon Stick (Dalchini)", "Oil , as required", "2 Onions , finely sliced", "2 Bay leaves (tej patta)", "1 Cinnamon Stick (Dalchini)", "4 Cloves (Laung)", "3 Cardamom (Elaichi) Pods/Seeds", "1 Star anise", "2 cups Basmati rice", "1-1/2 cups Prawns , cleaned and deveined", "1 tablespoon Red Chilli powder", "1/4 tablespoon Turmeric powder (Haldi)", "1/2 Lemon", "1/2 cup Curd (Dahi / Yogurt)", "1 cup Mint Leaves (Pudina) , chopped", "Salt , to taste"]'::jsonb, ARRAY['clove powder (laung)', 'basmati rice', 'salt', 'bay leaves (tej patta)', 'cardamom (elaichi) podsseeds', 'fennel seeds (saunf)', 'ajwain (carom seeds)', 'prawns deveined', 'red chilli powder', 'curd', 'cinnamon stick (dalchini)', 'onion', 'lemon', 'mint leaves (pudina)', 'turmeric powder', 'cloves (laung)', 'star anise', 'sunflower oil']::text[], '["To begin making the Prawns Biryani recipe, firstly dry roast the ingredients mentioned under Biryani Masala like the ajwain seeds, fennel seeds, cinnamon, cardamom and cloves and grind them into a fine powder.Add oil in a wok/kadhai\u00a0and saute the onions on medium heat till the onions are brownish and crispy.Soak basmati rice in water for about 30 minutes.In a mixing bowl, add cleaned and deveined prawns, turmeric powder, 1 tablespoon of biryani masala, red chilli powder, half lemon juice, 1/2 teaspoon of salt, 1/2 cup of chopped mint leaves, 1/2 of the fried onions and curd.Combine everything well with the prawns and set aside for about an hour.In a medium sized saucepan, add 5 cups of water, 1 tablespoon of biryani masala, cloves, cinnamon, bay leaves, 1/4 cup of mint leaves, 1 tablespoon of oil and remaining salt.Boil water over high flame.To the boiling water, add the soaked rice and cook on high flame for about 4 to 5 minutes.Do not overcook the rice.", "Overcooking rice may make them mushy and rice might break.Drain the water from the rice immediately and set aside.Meanwhile, in another medium wide saucepan, spread the remaining half tablespoon of oil on the bottom of the panSpread the marinated prawns as the bottom layer of the pan.Add half of the remaining fried onions and spread them evenly above the prawns.", "Sprinkle the mint leaves evenly.", "Layer the rice over the prawn masalas and spread them evenly.Garnish with the leftover fried onions.", "Dissolve a pinch of saffron in hot water and pour them on top of the layered rice.Cover the pot with the lid and cook the layered rice on high flame for about 10 minutes.", "Do not open the lid while cooking.Reduce the flame and cook the biryani for about 20 minutes.Turn off the heat and remove the lid after 15 minutes of resting time.Combine the biryani well such that the masalas and rice is well combined.", "Do not stir hard as rice might break.Garnish with cilantro and it is ready to be served.", "Prepare this spicy Prawn Biryani and serve it with\u00a0Tadka Raita,\u00a0Tomato Onion Cucumber raita\u00a0or any other raita of your choice for a perfect weekday lunch or dinner."]'::jsonb, 60, 'Indian', 'non-veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Karthika_Gopalakrishnan/Prawns_Biryani.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1660.Prawns_Biryani.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Indori Poha Recipe', 'indori-poha-recipe', 'Indori Poha is a delicious and light breakfast recipe which is very popular in Indore. Poha is generally made in every household as a breakfast dish but the Indori Poha has a twist in it. It is a great way to make your regular poha in a different way. An addition of fennel seeds makes this Poha even more delicious! Pomegranate kernels added to the poha adds freshness and nutrition.', '["2-1/2 cup Poha (Flattened rice)", "2 tablespoons Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1/2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Fennel seeds (Saunf)", "1 tablespoon Raw Peanuts (Moongphali)", "1 Onion , chopped", "1/2 teaspoon Ginger , grated", "2 Green Chillies , finely chopped", "7-8 Curry leaves", "1/2 teaspoon Turmeric powder (Haldi)", "1/2 teaspoon Red Chilli powder", "Salt , to taste", "1 tablespoon Sugar", "2 tablespoons Coriander (Dhania) Leaves , finely chopped", "1 Onion , chopped", "1/4 cup Fresh Pomegranate Fruit Kernels"]'::jsonb, ARRAY['salt', 'ginger', 'mustard seeds', 'poha (flattened rice)', 'fennel seeds (saunf)', 'coriander (dhania) leaves', 'red chilli powder', 'curry leaves', 'sugar', 'onion', 'cumin seeds (jeera)', 'peanuts (moongphali)', 'pomegranate fruit kernels', 'turmeric powder', 'green chillies', 'sunflower oil']::text[], '["To begin making Indori Poha, wash poha 3 times, drain the water completely and set it aside.", "Once the water is completely drained off, add sugar and salt to the poha and mix it properly. be gentle so as to not to break the soaked poha.Heat oil in a kadhai, add mustard seeds and once they start to splutter add peanuts and saute them for a minute until peanuts start to brown.Once done add onions, green chilies and curry leaves and cook it until the onions turns a little brown.Next add fennel seeds, grated ginger, turmeric powder, red chilli Powder and saute it for few seconds.Add the poha and mix everything well.", "Cover the Kadai with a lid and cook on low heat for 5 minutes.After 5 minutes turn off the heat and garnish the poha with chopped coriander leaves, onions and pomegranates and serve hot.Serve Indori Poha with some fruits and\u00a0Masala Chai\u00a0for your breakfast."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Waagmi_Soni/Indori_Poha.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1661.Indori_Poha.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pudina & Dhaniya Raita Recipe', 'pudina-dhaniya-raita-recipe', 'Pudina & Dhania Raita Recipe is so refreshing to be had along with Indian Main courses. The two most widely used Indian herbs are the coriander and mint leaves, these two have two distinct flavor and beneficial for the body in many ways. Coriander leaves are rich in Vitamin C, potassium, dietary fibers and they are really good for diabetic patients. Pudina on the other hand is a very good herb for aiding with digestive problems.', '["1 cup Curd (Dahi / Yogurt)", "4 sprig Coriander (Dhania) Leaves , washed and chopped", "4 sprig Mint Leaves (Pudina) , washed and chopped", "Salt , to taste", "To Temper", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon Cumin seeds (Jeera)", "1 sprig Curry leaves", "1 pinch Asafoetida (hing)", "Oil"]'::jsonb, ARRAY['salt', 'mustard seeds', 'asafoetida (hing)', 'mint leaves (pudina)', 'curd', 'coriander (dhania) leaves', 'curry leaves', 'cumin seeds (jeera)', 'sunflower oil']::text[], '["To begin making the Pudina & Coriander Raita Recipe, we will whip the curd with chopped coriander leaves, pudina leaves, and salt to taste.", "Mix well until combined.Heat a tempering pan with oil, add mustard seeds and cumin seeds and allow it to sizzle for few seconds.Once done, add curry leaves and hing and leave it to crackle.", "Pour the tempering oil over the raita as the tadka and serve.", "Serve the Pudian & Dhania Raita Recipe along with\u00a0Spiced Cabbage Rice\u00a0or\u00a0Paneer Pulao With Green Peas\u00a0with\u00a0Aloo Parwal Sabzi\u00a0by the side to pack it for your everyday lunch."]'::jsonb, 15, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Pudian__Coriander_Raita_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1662.Pudian__Coriander_Raita_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kinnathappam Recipe', 'kinnathappam-recipe', 'Kinnathappam or steamed plate cake is a traditional Kerala dessert prepared by Muslims during Ramadan. This plate cake is soft, wiggly and tasty. You can also make it for usual days to enjoy it after your meal. It gets ready in no time, therefore you can also make it when you invite guests at home for lunch or dinner.', '["1/2 cup Basmati rice", "1/2 cup Sugar", "cup Fresh coconut , grated", "3/4 cup Water", "1/2 teaspoon Cumin seeds (Jeera)", "1 teaspoon Cardamom Powder (Elaichi)", "1 Whole Egg", "1 teaspoon Oil , for greasing"]'::jsonb, ARRAY['basmati rice', 'sugar', 'cup fresh coconut', 'water', 'cumin seeds', 'jeera', 'cardamom powder', 'elaichi', 'whole egg', 'oil']::text[], '["To begin making the Kinnathappam recipe, wash and soak basmati rice in water for 3 hours.", "After it is soaked, drain the rice and add to mixer along with grated coconut and water.Grind everything into smooth batter.", "Pour into bowl and keep aside.Add sugar, cardamom powder and egg to the mixer grinder and blend everything until combined.", "Pour this into the rice batter bowl.Mix together and the batter should not be too thick or too thin.", "Strain to remove any coarse particles and pour the batter into greased steel bowl that fits inside the steamer.Sprinkle cumin seeds on top and place the bowl inside a\u00a0 steamer.", "Steam for 20-25 minutes or until it turns firm.Once done, allow it to cool.", "Run knife through the sides and invert to a plate.", "Slice, serve and enjoy this traditional sweet.Serve\u00a0Kinnathappam along with snacks like\u00a0Mahunada Khaja\u00a0and\u00a0Thotakura Undalu\u00a0when you have sudden guests at home."]'::jsonb, 210, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swathynandhini/KINNATHAPPAM_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1663.KINNATHAPPAM_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('पुदीना मूंग दाल रेसिपी - Mint Moong Dal Recipe', 'mint-moong-dal-recipe', 'पुदीना के बहुत सारे फायदे होते है. यह आपको गर्मी से राहत देता है और आपको डाईजेशन में भी मादा करता है. यहाँ हमनेपुदीना का प्रयोग दाल में किया है, जो इस दाल को फ्लेवर से भरपूर और स्वादिष्ट बनाता है.', '["1/2 \u0915\u092a \u092a\u093f\u0932\u0940 \u092e\u0942\u0902\u0917 \u0926\u093e\u0932", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930", "\u0939\u0940\u0902\u0917 , \u091a\u0941\u091f\u0915\u0940 \u092d\u0930", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0918\u0940", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u092a\u0941\u0926\u0940\u0928\u093e , \u0915\u093e\u091f \u0932\u0947", "\u092a\u093e\u0928\u0940 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930", "\u0928\u092e\u0915 , \u092a\u094d\u0930\u092f\u094b\u0917 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['कप पिली मूंग दाल', 'छोटा चम्मच लाल मिर्च पाउडर', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच जीरा पाउडर', 'हींग', 'बड़ा चम्मच घी', 'बड़े चम्मच पुदीना', 'पानी', 'नमक']::text[], '["\u092a\u0941\u0926\u0940\u0928\u093e \u092e\u0942\u0902\u0917 \u0926\u093e\u0932 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u092a\u094d\u0930\u0947\u0936\u0930 \u0915\u0941\u0915\u0930 \u092e\u0947\u0902 \u092e\u0942\u0902\u0917 \u0926\u093e\u0932, 1 \u0915\u092a \u092a\u093e\u0928\u0940, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0915\u0941\u0915\u0930 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947. 2 \u0938\u093f\u091f\u0940 \u0906\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947 \u0914\u0930 \u092b\u093f\u0930 \u092a\u094d\u0930\u0947\u0936\u0930 \u0928\u093f\u0915\u0932\u0928\u0947 \u0926\u0947.\u00a0\u0915\u0941\u0915\u0930 \u0916\u094b\u0932\u0947, \u0907\u0938\u092e\u0947\u0902 \u0928\u092e\u0915 \u0914\u0930 1-1/2 \u0915\u092a \u092a\u093e\u0928\u0940 \u0914\u0930 \u0928\u092e\u0915 \u0921\u093e\u0932\u0947\u0964 \u0917\u0948\u0938 \u091a\u093e\u0932\u0942 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0909\u092c\u0932\u0928\u0947 \u0926\u0947.\u00a0\u0905\u092c \u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f \u090f\u0915 \u0924\u095c\u0915\u093e \u092a\u0948\u0928 \u092e\u0947\u0902 \u0918\u0940 \u092f\u093e \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u091c\u0940\u0930\u093e, \u0939\u0940\u0902\u0917 \u0921\u093e\u0932\u0947 \u0914\u0930 \u091c\u0940\u0930\u093e \u0915\u094b \u0924\u095c\u0915\u0928\u0947 \u0926\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u0941\u0926\u0940\u0928\u093e, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0915\u0928\u0947 \u0926\u0947. \u0907\u0938 \u0924\u095c\u0915\u0947 \u0915\u094b \u0926\u093e\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u0915\u0928\u0947 \u0926\u0947.\u00a0\u092a\u0941\u0926\u0940\u0928\u093e \u092e\u0942\u0902\u0917 \u0926\u093e\u0932 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u092d\u093f\u0902\u0921\u0940 \u092e\u0938\u093e\u0932\u093e,\u00a0\u0932\u094c\u0915\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u0914\u0930\u00a0\u092b\u0941\u0932\u094d\u0915\u0947\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Sasmita/Pudina_Moong_Dal__Mint_Moong_Dal__Mint_Dal__Pudina_Dal.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1664.Pudina_Moong_Dal__Mint_Moong_Dal__Mint_Dal__Pudina_Dal.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Thalicha Thayir Sadam Recipe - Spicy Seasoned Curd Rice', 'thalicha-thayir-sadam-recipe-spicy-seasoned-curd-rice', 'Thalicha Thayir Sadam Recipe also known Seasoned Curd Rice is a staple food of South India. Every family will have their secret ingredient, but overall it''s an all time favorite and a meal finisher. If there is not curd rice, then the meal does not get complete for a South Indian family. You could choose to have your curd rice a multiple ways. You can also pair it up with Bisi Bele Bath.', '["1-1/2 cups Cooked rice", "3 cups Curd (Dahi / Yogurt)", "1/4 cup Anardana Powder (Pomegranate Seed Powder)", "1 Green Chillies , finely chopped", "Salt , to taste", "Ingredients for Seasoning", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1 teaspoon White Urad Dal (Split)", "1 sprig Curry leaves", "1 teaspoon Oil"]'::jsonb, ARRAY['salt', 'rice', 'mustard seeds', 'anardana powder (pomegranate seed powder)', 'curd', 'white urad dal (split)', 'curry leaves', 'green chillies', 'sunflower oil']::text[], '["To begin making the Thalicha Thayir Sadam Recipe (Spicy Seasoned Curd Rice), make sure you have some cooked rice ready.", "The rice should be cooked very soft, such that if you place it between your fingers it will mash very easily.Place the rice in a large mixing bowl.", "If the rice is a little war, it will help in mashing the rice to a more soft consistency.", "Add a ladle of yogurt to the rice and using your hands or the Potato Masher mash the rice well to combine it with the yogurt.Once the rice is mashed well, add the remaining yogurt, green chilies, pomegranates and salt.", "Stir to combine well and check the salt and adjust to suit your taste.The next step is to make the seasoning for the Curd Rice.", "Heat a small Tadka Pan with a teaspoon of oil.", "Once the oil heats up, add the mustard seeds, the urad dal and allow it to crackle.", "Once it crackles and the urad dal turns golden, add the curry leaves.", "Turn off the heat.Pour the seasoning over the prepared Curd Rice (Thayir Sadam) and give it a stir.The Thalicha Thayir Sadam Recipe (Spicy Seasoned Curd Rice) is ready to be served chilled for an afternoon lunch.Serve Thalicha Thayir Sadam Recipe with\u00a0Andhra Avakaya\u00a0and\u00a0Elai Vadam\u00a0for a comforting lunch."]'::jsonb, 50, 'Chettinad', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Rice/Thalicha_Curd_Rice_Thayir_Sadam_Recipe_-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1665.Thalicha_Curd_Rice_Thayir_Sadam_Recipe_-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Mangalorean Style Masala Pundi Recipe - Steamed rice dumpling in Onion Gravy', 'mangalorean-style-masala-pundi-recipe-steamed-rice-dumpling-in-onion-gravy', 'Mangalorean style Masala Pundi Recipe - Steamed rice dumpling in Onion Gravy is a simple hearty breakfast dish that has coconut rice dumpling immersed in a flavorful onion coconut gravy.', '["1 cup Dosa rice , washed and dried completely", "1/2 cup Fresh coconut , grated", "1 tablespoon Salt", "1 Onion , chopped", "2 cloves Garlic , chopped", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1 cup Tamarind Water", "Salt , to taste", "1 pinch Asafoetida (hing)", "1 sprig Coriander (Dhania) Leaves , chopped", "Ingredients for roasting and grinding", "2 tablespoon Coriander (Dhania) Seeds", "1 teaspoon Methi Seeds (Fenugreek Seeds)", "1 tablespoon Cumin seeds (Jeera)", "1 tablespoon White Urad Dal (Split)", "2 Dry Red Chillies", "4 tablespoon Fresh coconut"]'::jsonb, ARRAY['salt', 'tamarind water', 'coconut', 'mustard seeds', 'asafoetida (hing)', 'cloves garlic', 'curry leaves', 'dosa rice dried completely', 'coriander (dhania) leaves', 'onion', 'coriander (dhania) seeds', 'methi seeds (fenugreek seeds)', 'cumin seeds (jeera)', 'white urad dal (split)', 'dry red chillies']::text[], '["To begin making the Mangalorean style Masala Pundi Recipe - Steamed rice dumpling in Onion Gravy we will make the pundi, wash the dosa rice and dry them completely.Grind the rice in a mixer to a coarse mixture, add the grated coconut and blitz it one more time and keep it aside.Heat a sauce pan with 1 cup water, add salt and leave it to boil.", "Add the ground rice mixture and start whisking continuously so that no lumps are formed.Keep whisking till the mixture thickens and does not stick to the sides of the saucepan.Once done turn off the heat and allow it to cool.Meanwhile keep a vegetable steamer ready with enough water to steam the dumplings.Make lemon sized balls from the cooked rice mixture and place them on the plate of the steamer.", "Steam the dumplings for about 20 minutes.We will move ahead to make the curry, heat a small skillet with a teaspoon of oil.", "Add coriander seeds, fenugreek seeds and roast them for 10 seconds.", "Later add the dry red chillies, cumin seeds, urad dal and roast them well too for another 10 seconds.Take these roasted spices and grind it along with coconut in a mixer grinder to a fine paste.", "Add little water to grind it smoothly.Heat a kadai with oil, add the mustard seeds and splutter for few seconds and add the curry leaves and hing.", "Once that crackles add the chopped onions and garlic and saute till the onions becomes translucent.Add turmeric powder, the ground paste, tamarind water and give it a stir.", "Check for salt.", "You can add 1 more cup of water and allow it to boil.Once the dumplings are steamed, transfer them to a serving plate, pour a ladle of the gravy on the steamed dumplings, garnish with coriander leaves and serve.Serve the Mangalorean style Masala Pundi Recipe - Steamed rice dumpling in Onion Gravy as it is with a glass of\u00a0Masala Chai Recipe - Indian Spiced Tea\u00a0by the side for your morning breakfast."]'::jsonb, 60, 'Mangalorean', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Mangalorean_style_Basale_Pundi_Recipe_Steamed_rice_dumpling_in_Onion_Gravy.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1666.Mangalorean_style_Basale_Pundi_Recipe_Steamed_rice_dumpling_in_Onion_Gravy.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Semiya Kesari Recipe', 'semiya-kesari-recipe', 'Semiya Kesari Recipe is a sweet pudding made without milk. The pudding is made with roasted vermicelli cooked until it is soft and sweetened with sugar. It is then topped with roasted cashew nuts and raisins. It is a variation to the semiya payasam.', '["2 cups Hot water", "1 cup Semiya (Vermicelli)", "1/4 cup Sugar", "3 tablespoons Cashew nuts , halved", "3 tablespoons Sultana Raisins", "1/4 teaspoon Cardamom Powder (Elaichi)", "2 Saffron strands", "2 teaspoon Ghee , + 1/4 cup"]'::jsonb, ARRAY['cashew nuts', 'ghee', 'saffron strands', 'raisins', 'water', 'sugar', 'semiya (vermicelli)', 'cardamom powder (elaichi)']::text[], '["To begin making the Semiya Kesari Recipe, in a heavy bottomed saucepan; add a teaspoon of ghee roast the vermicelli on low heat until you get a roasted aroma.", "Meanwhile boil water in a saucepan.", "Add\u00a0in the sugar, cardamom powder, saffron and stir until the sugar dissolves completely.When it comes to a boil, add in the roasted vermicelli, turn the heat to low and simmer and cook until the semiya is cooked completely.Once done, add in 1/4 cup ghee and mix it properly and let it cook for another 2 minutes.", "While the Semiya is simmering, we will roast the cashew nuts.", "In a small pan, add a teaspoon of ghee on low heat; add in the cashew nuts and roast until crisp and golden.", "Add in the raisins, stir for a few seconds and keep aside.Turn off the heat and finally garnish the Semiya Kesari with the roasted cashew nuts and serve the Semiya hot or cold as desired.Serve the Semiya Kesari Recipe after a meal of\u00a0Hyderabadi Biryani\u00a0and\u00a0Tomato Onion Cucumber Raita\u00a0for your Sunday lunch."]'::jsonb, 30, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2017/10-oct/Kesari_semiya_Recipe-9472.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1667.Kesari_semiya_Recipe-9472.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kaccha Kela Aur Bhindi Ki Sabzi Recipe - Raw Banana & Ladies Finger Stir Fry', 'kaccha-kela-aur-bhindi-ki-sabzi-recipe-raw-banana-ladies-finger-stir-fry', 'Kaccha Kela Aur Bhindi Ki Sabzi Recipe is an ayurvedic friendly recipe without onion and garlic. The raw banana and ladies finger are separately roasted well till it crisp up and then tossed with basic spices like turmeric powder, hing, pepper powder and salt.', '["300 grams Bhindi (Lady Finger/Okra) , chopped", "2 Raw Banana", "1 teaspoon Turmeric powder (Haldi)", "1 teaspoon Black pepper powder", "1/2 teaspoon SSP Asafoetida (Hing)", "1 teaspoon Amchur (Dry Mango Powder)", "Salt , to taste", "Oil", "1/4 teaspoon Red Chilli powder", "1/2 teaspoon Garam masala powder", "1/2 teaspoon Coriander (Dhania) Powder"]'::jsonb, ARRAY['s bhindi', 'lady finger/okra', 'raw banana', 'turmeric powder', 'haldi', 'black pepper powder', 'ssp asafoetida', 'hing', 'amchur', 'dry mango powder', 'salt', 'oil', 'red chilli powder', 'garam masala powder', 'coriander', 'dhania']::text[], '["To begin making the Kaccha Kela Aur Bhindi Ki Sabzi Recipe, we will pre cook the raw banana.Firstly, peel and cut the raw banana and keep it aside.", "In a pressure cooker combine, add the chopped raw banana with half cup of water, turmeric powder and salt.", "Cover and pressure cook for 3 whistles and turn off the heat.Once done, open the pressure cooker and allow the banana to cool and keep it aside.Heat oil in a heavy bottomed pan.", "Add cumin seeds, asafoetida and let the cumin seeds crackle.", "Once it crackles, add in the ladies finger, sprinkle little salt and saute till they soften and get cooked through.", "You can cover it and cook as it will cook faster.This will take about 10 minutes.", "Once the bhindi is cooked, add in the cooked raw banana, amchur powder, pepper powder, red chilli powder, coriander powder, garam masala powder and saute till the masala is well coated with the masala - about 4 to 5 minutes and turn off the heat.After 4 to 5 minutes, transfer the\u00a0Kaccha Kela Aur Bhindi Ki Sabzi to a serving bowl and garnish it with coriander leaves.Serve the\u00a0Kaccha Kela Aur Bhindi Ki Sabzi Recipe\u00a0along with\u00a0Gujarati Dal,\u00a0Lauki Raita\u00a0and\u00a0Phulka\u00a0to enjoy a good weekday meal."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl_sunitha/Raw_Banana_Bhindi_Sabzi_Recipe_SSP_Step_by_Step_31_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1668.Raw_Banana_Bhindi_Sabzi_Recipe_SSP_Step_by_Step_31_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lehsun Amla Chutney Recipe - Garlic Gooseberry Chutney', 'lehsun-amla-chutney-recipe-garlic-gooseberry-chutney', 'Lehsun Amla Chutney Recipe is a delicious and tangy chutney recipe that is prepared with garlic, pearl onions, gooseberries or amla, coriander leaves and mint leaves. This chutney is a powerhouse of superfood ingredients.', '["8 Amla (Nellikai/ Gooseberry)", "6 Pearl onions (Sambar Onions)", "10 cloves Garlic", "2 Green Chillies", "1/2 cup Mint Leaves (Pudina)", "1/2 cup Coriander (Dhania) Leaves", "Salt , as per your taste", "1 teaspoon Oil", "1 teaspoon Oil", "1/2 teaspoon Mustard seeds (Rai/ Kadugu)", "1/4 teaspoon White Urad Dal (Split)", "1/4 teaspoon Chana dal (Bengal Gram Dal)", "1 sprig Curry leaves", "10 Cashew nuts"]'::jsonb, ARRAY['cashew nuts', 'salt', 'chana dal (bengal gram dal)', 'coriander (dhania) leaves', 'mustard seeds', 'amla (nellikai gooseberry)', 'cloves garlic', 'pearl onion (sambar onion)', 'white urad dal (split)', 'curry leaves', 'mint leaves (pudina)', 'green chillies', 'sunflower oil']::text[], '["To begin making Garlic Amla Chutney Recipe, first wash the gooseberry, cut into pieces and remove the seed.", "Wash mint leaves, coriander leaves and keep aside.", "Place a heavy bottomed pan on heat and add a teaspoon cooking oil.Once the oil is hot, add pearl onions and garlic.", "Saute them until the onions are translucent.Next add gooseberry (amla), mint leaves and coriander leaves.", "Saute well for 2 minutes until the leaves wilt.", "Turn off the the heat.", "Allow the amla, garlic and onion mixture to cool.Once cooled, transfer the\u00a0Garlic Amla Chutney mixture into mixer along with required amount of salt.", "Blend everything into thick paste adding very little water.", "Keep the\u00a0Garlic Amla Chutney aside.", "To prepare the tempering, heat 1 teaspoon of oil in a tadka pan.", "Once the oil is hot, add mustard seeds, chana dal and urad dal.", "Once the mustard seeds sputters, add curry leaves and cashews.", "Fry the cashew nuts until they are\u00a0 brown.", "Add the prepared tempering to the Garlic Amla Chutney.", "Mix well and your\u00a0Garlic Amla Chutney is ready to be served.", "Serve Garlic Amla Chutney as a side dish for Dosa or Idli for breakfast.You can even serve Garlic Amla Chutney with hot steamed rice and ghee along with Beetroot Poriyal for a simple lunch."]'::jsonb, 15, 'Tamil Nadu', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/swathynandhini/Garlic_Amla_Chutney_Recipe_-_Garlic_And_Gooseberry_Chutney.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1669.Garlic_Amla_Chutney_Recipe_-_Garlic_And_Gooseberry_Chutney.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Saunf Wali Hari Gobi Sabzi Recipe - Cauliflower Spiced with Fennel and Green Chutney', 'saunf-wali-hari-gobi-sabzi-recipe-cauliflower-spiced-with-fennel-and-green-chutney', 'The Saunf Wali Hari Gobi Sabzi Recipe is a quick and easy to make dish when you have a set of basic ingredients to make your sabzi. Green chutney made with coriander and mint leaves is added to this cauliflower sabzi which adds amazing flavour .', '["1 Cauliflower (gobi) , cut into florets", "1 teaspoon Fennel seeds (Saunf)", "1 Ginger", "2 Tomatoes , finely chopped", "2 Bay leaves (tej patta)", "1/2 cup Green Chutney (Coriander & Mint)", "1/2 cup Curd (Dahi / Yogurt)", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Coriander Powder (Dhania)", "Salt", "Red Chilli powder", "Oil , for cooking"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'bay leaves (tej patta)', 'fennel seeds (saunf)', 'cauliflower (gobi)', 'red chilli powder', 'curd', 'coriander powder', 'turmeric powder', 'green chutney (coriander mint)', 'sunflower oil']::text[], '["To begin making the\u00a0Saunf Wali Hari Gobi Sabzi Recipe, get all the ingredients and keep them ready.", "If you don''t have Green Chutney, click here to get the recipe.Heat a teaspoon of oil in a heavy bottomed pan; add the fennel seeds, ginger and bay leaves.", "Stir fry for a few seconds.", "Add the tomatoes, turmeric powder, coriander powder, chili powder and give it a stir.", "Next add the yogurt, green chutney and salt.", "Give it a stir.Add the Cauliflower into the Chutney Masala and stir well to combine into the masala.", "Once combined, cover the pan and cook until the cauliflower is well cooked.", "This will take about 5 to 8 minutes on medium heat.Make sure you keep stirring it intermittently until done.", "Once done, turn off the heat and serve.Serve the\u00a0Saunf\u00a0Wali Hari Gobi Sabzi Recipe along with\u00a0Tawa Paratha\u00a0and\u00a0Boondi Raita Recipe Spiced With Black Salt\u00a0for lunch or dinner."]'::jsonb, 50, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Saunf_Wali_Hari_Gobi_Sabzi_Cauliflower_Curry_with_Fennel_Mint_Chutney-4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1670.Saunf_Wali_Hari_Gobi_Sabzi_Cauliflower_Curry_with_Fennel_Mint_Chutney-4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Passion Fruit- Shrikhand Shots Recipe', 'passion-fruit-shrikhand-shots-recipe', 'Passion Fruit- Shrikhand Shots Recipe is a yummy and delectable combination of traditional shrikhand with passion fruit pulp, presented in shot glasses and topped with chocolate chips.', '["1 cup Curd (Dahi / Yogurt)", "1 Passion fruit , (pulp needed)", "1 tablespoon Caster Sugar", "1/4 teaspoon Cardamom Powder (Elaichi)", "1 pinch Saffron strands , mixed with 1 tablespoon warm milk", "1-2 tablespoon Chocolate chips", "1 Passion fruit , (pulp needed)"]'::jsonb, ARRAY['saffron strands mixed milk', 'passion fruit (pulp needed)', 'curd', 'cardamom powder (elaichi)', 'caster sugar', 'chocolate chips']::text[], '["To begin making Passion Fruit- Shrikhand Shots Recipe, put a strainer on a bowl and arrange a thin muslin cloth over it.", "Pour curd in the strainer and tie the edges.", "Refrigerate the bowl for at least 3-4 hours.Cut the passion fruit into two halves and scoop out the flesh using a spoon.", "We would be adding pulp of 1 passion fruit to our thick curd and will be using the pulp extracted from another passion fruit while assembling our shrikhand shots.After 3-4 hours, all the excess water from the curd would have collected in the bowl.", "Squeeze out all the remaining excess water and transfer the curd to a wide bowl. (Read here to know how you can use the leftover water/whey)Whisk the curd well with the help of a beater.", "Add powdered sugar, cardamom powder, kesar mixed with milk and passion fruit pulp.", "Whisk well to combine."]'::jsonb, 255, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Drashti/Passion_Fruit_Shrikhand_Shots.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1671.Passion_Fruit_Shrikhand_Shots.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Kerala Thenga Chammanthi Recipe- Coconut Onion Chutney', 'kerala-thenga-chammanthi-recipe-coconut-onion-chutney', 'Chammanthi is very common in Kerala households and this Kerala Thenga Chammanthi Recipe is a traditional variant.Each and every household in Kerala have their own version of the chammanthi. Some do not add ginger or curry leaves to the chamanthi. Some skip out on the onions. This recipe has all the great flavours of chamanthi. It is super flavourful with the addition of ginger, shallots, curry leaves and tamarind to fresh grated coconut.', '["1 cup Fresh coconut , grated", "3 Shallots", "20 grams Tamarind", "3 Dry Red Chilli", "1/2 inch Ginger", "3 Dry Red Chillies", "1 sprig Curry leaves", "Salt , to taste"]'::jsonb, ARRAY['salt', 'ginger', 'coconut', 'dry red chilli', 'curry leaves', 'dry red chillies', 'tamarind']::text[], '["To begin making Kerala Thenga Chammanthi Recipe, prep up all the ingredients first.In a mixer grinder add coconut, shallots, tamarind, dry red chillies, ginger, curry leaves and salt to taste.", "Add about 2-4 tablespoons of water and grind the chammanthi to get a coarse mixture.", "Once done transfer the\u00a0Thenga Chammanthi into a serving bowl and serve.Serve Kerala Thenga Chammanthi Recipe with\u00a0Steamed rice\u00a0or\u00a0Kerala Style Kanji Payar Recipe,\u00a0\u00a0Egg White Omelette Recipe With Spinach\u00a0and\u00a0curd\u00a0for lunch or dinner.", "You can also serve it with\u00a0Ragi and Oats Dosa\u00a0or\u00a0Homemade Soft Idli\u00a0for healthy breakfast."]'::jsonb, 5, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/2019/kerala_chammanthi_video_recipe_coconut_chutney_with_tamarind_and_shallots_5_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1672.kerala_chammanthi_video_recipe_coconut_chutney_with_tamarind_and_shallots_5_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('मुघलाई भिंडी रेसिपी - Mughlai Bhindi Recipe', 'mughlai-bhindi-recipe', 'मुघलाई खाना मुघल जमाने से प्रसिद्ध हुआ है. यह खाना शाही रसोई में बनाया जाता था और इसमें कई तरह के ड्राई फ्रूट्स और मेवों का प्रयोग किया जाता था. आप भी इसे किसी ख़ास अवसर पर अपने खाने के लिए बना सकते है. अगर आप अपनी रोज की भिंडी की सब्ज़ी नहीं बनाना चाहते, तो आप यह रेसिपी जरूर बनाए।', '["150 \u0917\u094d\u0930\u093e\u092e \u092d\u093f\u0902\u0921\u0940", "110 \u0917\u094d\u0930\u093e\u092e \u092a\u094d\u092f\u093e\u091c", "1 \u091f\u092e\u093e\u091f\u0930", "1/2 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0905\u0926\u0930\u0915 \u0932\u0939\u0938\u0941\u0928 \u0915\u093e \u092a\u0947\u0938\u094d\u091f", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "4 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932", "\u092a\u0940\u0938\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "3/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u0947\u0921 \u091a\u093f\u0932\u094d\u0932\u0940 \u092b\u0932\u0948\u0915\u094d\u0938", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0938\u094c\u0902\u092b", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u092a\u0942\u0930\u0940 \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a", "10 \u092c\u093e\u0926\u093e\u092e"]'::jsonb, ARRAY['ग्राम भिंडी', 'ग्राम प्याज', 'टमाटर', 'बड़ा चम्मच अदरक लहसुन का पेस्ट', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच गरम मसाला पाउडर', 'नमक', 'बड़े चम्मच तेल', 'पीसने के लिए', 'बड़े चम्मच धनिये के बीज', 'छोटा चम्मच जीरा', 'छोटा चम्मच रेड चिल्ली फलैक्स', 'छोटा चम्मच सौंफ', 'छोटा चम्मच पूरी काली मिर्च', 'बादाम']::text[], '["\u092e\u0941\u0918\u0932\u093e\u0908 \u092d\u093f\u0902\u0921\u0940 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0915\u095d\u093e\u0908 \u0915\u094b \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0927\u0928\u093f\u092f\u0947 \u0915\u0947 \u092c\u0940\u091c, \u091c\u0940\u0930\u093e, \u0930\u0947\u0921 \u091a\u093f\u0932\u094d\u0932\u0940 \u092b\u0932\u0948\u0915\u094d\u0938, \u0938\u094c\u0902\u092b, \u092a\u0942\u0930\u0940 \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a, \u092c\u093e\u0926\u093e\u092e \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u0938\u0947\u0915 \u0932\u0947.\u0938\u0947\u0915\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0940\u0938 \u0915\u0930 \u092a\u093e\u0909\u0921\u0930 \u092c\u0928\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u0940 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0925\u094b\u095c\u093e \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930, \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u091f\u092e\u093e\u091f\u0930 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u0947 \u092d\u0940 \u092e\u0938\u093e\u0932\u0947 \u0935\u093e\u0932\u0947 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0940\u0938 \u0932\u0947\u0964\u00a0\u00a0\u092d\u093f\u0902\u0921\u0940 \u0915\u094b 2 \u0907\u0902\u091a \u0915\u0947 \u0938\u093e\u0907\u091c \u092e\u0947\u0902 \u0915\u093e\u091f\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947. \u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u092d\u093f\u0902\u0921\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0938\u0941\u0928\u0939\u0930\u093e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947.\u00a0\u092d\u093f\u0902\u0921\u0940 \u0915\u094b \u092a\u0948\u0928 \u0938\u0947 \u0928\u093f\u0915\u093e\u0932 \u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947. \u0905\u092c \u0907\u0938\u0940 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0925\u094b\u095c\u093e \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0905\u0926\u0930\u0915 \u0932\u0939\u0938\u0941\u0928\u00a0\u0915\u093e \u092a\u0947\u0938\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u00a0\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092a\u093f\u0938\u093e \u0939\u0941\u0906 \u091f\u092e\u093e\u091f\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u093e \u092a\u0938\u0930\u0947 \u0921\u093e\u0932\u0947 \u0914\u0930 4 \u0938\u0947 5 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092d\u093f\u0902\u0921\u0940, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930, \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 3 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.\u0905\u092c \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u092e\u0941\u0918\u0932\u093e\u0908 \u092d\u093f\u0902\u0921\u0940 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0926\u093e\u0932 \u092e\u0916\u0928\u0940,\u00a0\u092c\u0942\u0902\u0926\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u0914\u0930 \u0932\u091a\u094d\u091b\u093e \u092a\u0930\u093e\u0920\u093e \u0915\u0947 \u0938\u093e\u0925 \u0905\u092a\u0928\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947."]'::jsonb, 45, 'Mughlai', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Nusrath_Jahan/Mughlai_bhindi_recipe_okra_curry_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1673.Mughlai_bhindi_recipe_okra_curry_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('भिंडी मसाला रेसिपी - Bhindi Masala Recipe', 'bhindi-masala-recipe', 'भिंडी मसाला एक सरल और जल्द बनने वाली रेसिपी है जिसे आप अपने रोज के खाने के लिए बना सकते है. इसमें प्याज और टमाटर के साथ रोज के मसालों का प्रयोग किया जाता है.', '["350 \u0917\u094d\u0930\u093e\u092e \u092d\u093f\u0902\u0921\u0940", "1 \u092a\u094d\u092f\u093e\u091c , \u092a\u0924\u0932\u093e \u0914\u0930 \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "2 \u091f\u092e\u093e\u091f\u0930 , \u092c\u093e\u0930\u0940\u0915 \u0915\u093e\u091f \u0932\u0947", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['ग्राम भिंडी', 'प्याज', 'टमाटर', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच धनिया पाउडर', 'छोटा चम्मच लाल मिर्च पाउडर', 'नमक']::text[], '["\u092d\u093f\u0902\u0921\u0940 \u092e\u0938\u093e\u0932\u093e \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u092d\u093f\u0902\u0921\u0940 \u0915\u0947 \u0915\u094b\u0928\u0947 \u0915\u093e\u091f\u00a0\u0932\u0947 \u0914\u0930 \u0909\u0928\u094d\u0939\u0947\u0902 \u092a\u0924\u0932\u093e 1 \u0907\u0902\u091a \u0915\u0947 \u0938\u094d\u0932\u093e\u0907\u0938 \u092e\u0947\u0902 \u0915\u093e\u091f \u0932\u0947.\u0905\u092c \u090f\u0915 \u0915\u095d\u093e\u0908 \u092e\u0947\u0902 \u0924\u0947\u0932 \u0917\u0930\u092e \u0915\u0930 \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u092a\u094d\u092f\u093e\u091c \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u093e\u091c \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u092d\u093f\u0902\u0921\u0940, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092d\u093f\u0902\u0921\u0940 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0924\u0915 \u092a\u0915\u093e \u0932\u0947. \u0907\u0938\u092e\u0947\u0902 \u0915\u092e \u0938\u0947 \u0915\u092e 10 \u092e\u093f\u0928\u091f \u0932\u0917\u0947\u0902\u0917\u0947\u0964\u00a010 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 \u091f\u092e\u093e\u091f\u0930 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u091f\u092e\u093e\u091f\u0930 \u0915\u0947 \u0928\u0930\u092e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930, \u0932\u093e\u0932 \u092e\u093f\u0930\u094d\u091a \u092a\u093e\u0909\u0921\u0930, \u0927\u0928\u093f\u092f\u093e \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947.\u00a0\u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947 \u0914\u0930 3 \u0938\u0947 4 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947.\u00a0\u092d\u093f\u0902\u0921\u0940 \u092e\u0938\u093e\u0932\u093e \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u092a\u0902\u091a\u092e\u0947\u0932 \u0926\u093e\u0932,\u00a0\u0932\u094c\u0915\u0940 \u0930\u093e\u092f\u0924\u093e\u00a0\u0914\u0930\u00a0\u092b\u0941\u0932\u094d\u0915\u093e\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0926\u093f\u0928 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 35, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Dry/Bhindi_Masala_Recipe_Bhindi_Tamatar_Ki_Sabzi_-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1674.Bhindi_Masala_Recipe_Bhindi_Tamatar_Ki_Sabzi_-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('पालक पनीर रेसिपी - Palak Paneer Recipe', 'palak-paneer-recipe', 'पालक पनीर रेसिपी एक सरल और पोषण से भरपूर रेसिपी है जिसे हर घर में बनाया जाता है. यह आपको हर दक्षिण भारतीय रेस्टोरेंट में भी मिल जाती है. इसमें पालक से आयरन और पनीर से प्रोटीन मिलता है. आप इस सब्ज़ी को अपने लंच बॉक्स में भी पैक कर सकते है.', '["250 \u0917\u094d\u0930\u093e\u092e \u092a\u0928\u0940\u0930 , \u0915\u093e\u091f \u0932\u0947", "500 \u0917\u094d\u0930\u093e\u092e \u092a\u093e\u0932\u0915 , \u0927\u094b\u0915\u0930 \u0915\u093e\u091f \u0932\u0947", "1 \u091f\u092e\u093e\u091f\u0930 , \u092a\u094d\u092f\u0942\u0930\u0940", "2 \u0915\u0932\u0940 \u0932\u0939\u0938\u0941\u0928 , \u0915\u0938 \u0932\u0947", "2 \u0907\u0902\u091a \u0905\u0926\u0930\u0915 , \u0915\u0938 \u0932\u0947", "2 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a , \u0938\u0940\u0927\u093e \u0915\u093e\u091f \u0932\u0947", "1/2 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0926\u093e\u0932\u091a\u0940\u0928\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0915\u094d\u0930\u0940\u092e", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u092e\u0915\u094d\u0916\u0928", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930"]'::jsonb, ARRAY['ग्राम पनीर', 'ग्राम पालक', 'टमाटर', 'कली लहसुन', 'इंच अदरक', 'हरी मिर्च', 'छोटा चम्मच जीरा', 'छोटा चम्मच दालचीनी पाउडर', 'छोटा चम्मच जीरा पाउडर', 'छोटा चम्मच हल्दी पाउडर', 'छोटा चम्मच गरम मसाला पाउडर', 'बड़े चम्मच क्रीम', 'बड़ा चम्मच मक्खन', 'नमक']::text[], '["\u092a\u093e\u0932\u0915 \u092a\u0928\u0940\u0930 \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u092a\u093e\u0932\u0915 \u0915\u094b \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u0927\u094b \u0932\u0947. \u0927\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0915\u093e\u091f \u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0932\u0947.\u00a0\u090f\u0915 \u0938\u0949\u0938 \u092a\u0948\u0928 \u092e\u0947\u0902 \u092a\u093e\u0928\u0940 \u0917\u0930\u092e \u0915\u0930\u0932\u0947\u0964 \u0909\u092c\u093e\u0932\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092a\u093e\u0932\u0915 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930 \u0932\u0947. 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0924\u0915 \u092a\u093e\u0932\u0915 \u0915\u094b \u0917\u0930\u092e \u092a\u093e\u0928\u0940 \u092e\u0947\u0902 \u0930\u0939\u0928\u0947 \u0926\u0947.\u00a0\u092a\u093e\u0932\u0915 \u0915\u094b \u0928\u093f\u0915\u093e\u0932\u0947 \u0914\u0930 \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0926\u0947. \u0905\u092c \u0907\u0938\u0947 \u090f\u0915 \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u0940\u0938 \u0915\u0930 \u092a\u094d\u092f\u0942\u0930\u0940 \u092c\u0928\u093e \u0932\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0915\u095c\u093e\u0939\u0940 \u092e\u0947\u0902 \u092e\u0915\u094d\u0916\u0928 \u0917\u0930\u092e \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u092e\u0947\u0902 \u091c\u0940\u0930\u093e, \u0905\u0926\u0930\u0915, \u0932\u0939\u0938\u0941\u0928, \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a \u0921\u093e\u0932\u0947 \u0914\u0930 1 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947. \u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u091f\u092e\u093e\u091f\u0930 \u0915\u0940 \u092a\u094d\u092f\u0942\u0930\u0940, \u0939\u0932\u094d\u0926\u0940 \u092a\u093e\u0909\u0921\u0930 \u0921\u093e\u0932\u0947 \u0914\u0930 2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0915\u093e \u0932\u0947.2 \u0938\u0947 3 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u092a\u093f\u0938\u093e \u0939\u0941\u0906 \u092a\u093e\u0932\u0915, \u091c\u0940\u0930\u093e \u092a\u093e\u0909\u0921\u0930, \u0917\u0930\u092e \u092e\u0938\u093e\u0932\u093e \u092a\u093e\u0909\u0921\u0930, \u0926\u093e\u0932\u091a\u0940\u0928\u0940 \u092a\u093e\u0909\u0921\u0930, \u0928\u092e\u0915 \u0921\u093e\u0932\u0947, \u092e\u093f\u0932\u093e\u090f \u0914\u0930 5 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u092a\u0932\u093e \u0932\u0947.5 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0907\u0938\u092e\u0947\u0902 \u0915\u094d\u0930\u0940\u092e, \u092a\u0928\u0940\u0930 \u0915\u0947 \u091f\u0941\u0915\u095c\u0947 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0909\u092c\u0932\u0928\u0947 \u0926\u0947. \u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926, \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u0930\u094b\u0938\u0947\u0964\u00a0\u00a0\u092a\u093e\u0932\u0915 \u092a\u0928\u0940\u0930 \u0930\u0947\u0938\u093f\u092a\u0940\u00a0\u0915\u094b\u00a0\u0926\u093e\u0932 \u0924\u095c\u0915\u093e,\u00a0\u092c\u0942\u0902\u0926\u0940 \u0930\u093e\u092f\u0924\u093e,\u00a0\u091c\u0940\u0930\u093e \u0930\u093e\u0907\u0938\u00a0\u0914\u0930\u00a0\u092b\u0941\u0932\u094d\u0915\u0947\u00a0\u0915\u0947 \u0938\u093e\u0925 \u0905\u092a\u0928\u0947 \u0930\u093e\u0924 \u0915\u0947 \u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u094b\u0938\u0947\u0964."]'::jsonb, 60, 'Punjabi', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Vegetables_Gravy/Palak_Paneer_Recipe_North_Indian_Punjabi-3.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1675.Palak_Paneer_Recipe_North_Indian_Punjabi-3.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Pudina Idli Recipe - Mint Flavoured Idli', 'pudina-idli-recipe-mint-flavoured-idli', 'Pudina Idli Recipe is a lovely flavour idli recipe. Idli batter is flavoured with the popular green chutney made with coriander and mint leaves. The chutney lends great fresh flavours to the idli.', '["3 cups Idli Dosa Batter", "1/2 cup Green Chutney (Coriander & Mint)"]'::jsonb, ARRAY['s idli dosa batter', 'green chutney', 'coriander & mint']::text[], '["To begin making the Pudina Idli Recipe, our two main elements need to be kept ready.", "Firstly, the idli batter. you can use the store bought batter, besides there''s nothing better than using homemade idli batter.", "Follow this\u00a0Homemade Idli Dosa Batter Recipe\u00a0to make the idli batter at home.", "Secondly for the freshly made green chutney follow this recipe -\u00a0Green Chutney Recipe - Coriander Mint Chutney Recipe.", "Getting ahead to make the\u00a0Pudina Idli, in a mixing bowl, combine the idli batter along with the green chutney vigorously, until the entire batter looks completely green in colour.", "Preheat an idli steamer with water, grease the idli plates generously with oil or ghee.", "Pour a ladle full of batter into each of the cavities, place the plates in the steamer and steam for 10-12 minutes.", "Insert a greased knife after 12 minutes to check if the idlis are steamed.", "If the knife comes out clean, turn off the flame and remove the idli plates from the steamer.", "Now wait for a couple of minutes, before you demould them.Drizzle with some ghee and serve piping hot.", "Serve\u00a0Pudina Idli Recipe along with\u00a0Medu Vada Recipe,\u00a0South Indian Coconut Chutney Recipe With Coconut Water,\u00a0\u00a0Pandu Mirapakaya Pachadi - Andhra Red Chilli Chutney Recipe\u00a0and wash down this flavorful breakfast with\u00a0Kumbakonam Filter Coffee Recipe."]'::jsonb, 30, 'South Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Shyma_Menon/Healthy_Homemade_Pudina_Idli_Recipe_Mint_Idli_Recipe-2_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1676.Healthy_Homemade_Pudina_Idli_Recipe_Mint_Idli_Recipe-2_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Dry Fruit Halwa Recipe', 'dry-fruit-halwa-recipe', 'The Dry Fruit Halwa is a delicious quick sweet made from figs, dates, pistachios, almonds, cashew nuts and walnuts. There is no added sugar in this recipe and hence makes it more healthy. The recipe to make the dry fruit barfi is quick and easy and makes it a perfect sweet for Diwali or even as a healthy snack for kids. These are also high energy and nutritious squares that can be enjoyed by each and everyone in the family.', '["1 cup Dates , seedless, finely chopped", "1 cup Dried Figs , dried, finely chopped", "1/4 cup Pistachios , finely chopped", "1/4 cup Cashew nuts , finely chopped", "1/4 cup Whole Almonds (Badam) , finely chopped", "1/4 cup Walnuts , finely chopped", "1 tablespoon Milk", "2 tablespoons Ghee"]'::jsonb, ARRAY['cashew nuts', 'dates seedless', 'pistachios', 'ghee', 'milk', 'badam (almond)', 'dried figs dried', 'walnuts']::text[], '["To begin making the Dry Fruit Halwa Recipe,pulse\u00a0the nuts in the chopper to get roughly chopped mixture.", "Keep the nuts aside.", "Blend the finely chopped dates and figs with 1 tablespoon of milk and ghee until smooth.Add ghee to a preheated pan and add the nuts and the dates and figs blend to the pan.", "Saute the dry fruit halwa until it gets well combined for 4 to 5 minutes.", "Keep stirring the halwa every couple of minutes until the mixture comes away from the sides of the pan.", "Turn off the heat.You can serve the dry fruit halwa as it is or along with vanilla ice cream, or even set into a pan and cut into slices once chilled.To set into a pan, pour and layer this dry fruit halwa mixture into the pan and smoothen it well.", "Allow it to rest until the mixture is cooled completely and set.", "Refrigeration will help it set faster.Cut the Dry Fruit halwa into equal squares and store in an airtight container.", "Serve the Dry Fruit Barfi Recipe for any festivals along with other festival recipes like\u00a0Dahi Vada,\u00a0Sukha Kala Chana Masala\u00a0\u00a0and\u00a0Puri\u00a0 or as a \u00a0Tea Time snack\u00a0for children."]'::jsonb, 60, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Sweets_Mithai/Dry_fruit_Halwa_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1677.Dry_fruit_Halwa_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Lachedar Kakdi Pyaz Kachumber Recipe - Onion Cucumber Salad', 'lachedar-kakdi-pyaz-kachumber-recipe-onion-cucumber-salad', 'Lachedar Kakdi Pyaz Kachumber Recipe is a super fresh Indian salad. Thin strips of onions and cucumbers are dressed in fresh lemon juice and some spices like cumin powder, chaat masala, red chilli powder and salt.', '["2 Onions , thin roun dels", "2 Cucumber , peel & cut into thin strips", "1 tablespoon Lemon juice", "Salt , to taste", "1/2 teaspoon Red Chilli powder", "1/2 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Chaat Masala Powder"]'::jsonb, ARRAY['salt', 'cumin powder (jeera)', 'chaat masala powder', 'red chilli powder', 'lemon', 'cucumber', 'onion roun dels']::text[], '["To begin making the Lachedar Kakdi Pyaz Kachumber Recipe, first peel and cut the onions into thin roundels.", "Separate the onions rings from each other.Next peel the cucumbers and slice vertically, and then cut into thin strips to appear like noodles.", "In a mixing bowl, toss the cucumber strips and the onions together.", "In a small bowl, make the dressing by combining the freshly squeezed lemon juice, cumin powder, salt, chaat masala and red chilli powder.", "Pour this dressing over the cucumber and onions and toss well and the\u00a0Lachedar Kakdi Pyaz Kachumber is ready.Serve\u00a0Lachedar Kakdi Pyaz Kachumber alongside a meal of\u00a0Pudina Tawa Paratha,\u00a0Tadkewali Masoor Dal,\u00a0Achari Aloo Sabzi\u00a0and\u00a0Methi Raita Flavoured With Garlic Recipe\u00a0for a complete meal."]'::jsonb, 15, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/0-Archanas-Kitchen-Recipes/Articles/lacchedar_kakdi_aur_pyaaz_recipe_pickled_onions_and_cucumber_4.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1678.lacchedar_kakdi_aur_pyaaz_recipe_pickled_onions_and_cucumber_4.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Corn And Peas Curry Recipe', 'corn-and-peas-curry-recipe-2', 'Corn and Peas Curry Recipe is a unique recipe of a corn on the cob curry.', '["To cook the corn", "2 Corn Cob , cut into 1 inch pieces", "Salt , to taste", "Water , as required", "2 teaspoons Cumin seeds (Jeera)", "1 teaspoon Coriander (Dhania) Seeds", "5 Dry Red Chillies", "2 teaspoons Oil", "6 cloves Garlic", "1 inch Ginger", "2 Onions , sliced", "2 tablespoons Fresh coconut , grated", "2 teaspoons Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 sprig Curry leaves", "1/2 cup Homemade tomato puree", "Salt , to taste", "1/4 teaspoon Turmeric powder (Haldi)", "1 teaspoon Garam masala powder", "1 teaspoon Kashmiri Red Chilli Powder", "1/4 cup Green peas (Matar)"]'::jsonb, ARRAY['tomato', 'salt', 'ginger', 'kashmiri red chilli powder', 'coconut', 'mustard seeds', 'green peas (matar)', 'water', 'cloves garlic', 'curry leaves', 'dry red chillies', 'onion', 'cumin seeds (jeera)', 'corn cob', 'turmeric powder', 'coriander seeds', 'garam masala powder', 'sunflower oil']::text[], '["To begin making the Corn and Peas Curry Recipe, we will first cook the corn on the cob.", "Into a pressure cooker, add the cut corn along with salt and water, pressure cook for 2 whistles.", "Turn off the heat and allow the pressure to release naturally.", "Once done open the cooker, drain off the excess water and keep the corn aside.", "The next step is to make the gravy for the\u00a0Corn and Peas Curry.Heat a skillet on medium flame, dry roast the cumin seeds, coriander seeds and dry red chillies until fragrant this will take about 3-5 minutes.", "Transfer the dry roasted whole spices into a mixer jar.", "Next in the same pan, add some oil and heat on medium flame, to this add the garlic cloves, ginger and onions.", "Saute these for about 5-7 minutes until the onions turns soft and lightly brown.", "Once done,stir in the grated coconut and saute for a minute.Mix well and turn off the heat.", "Allow the mixture to cool and add it to the mixer jar that has the whole spices.", "Grind everything into a smooth paste using some water and set aside.", "Heat a kadai with oil on medium flame, to this add mustard seeds, and curry leaves and allow it to crackle.", "Next add the tomato puree and bring it to a single boil.", "Once it comes to a boil, add the freshly ground spice-onion paste mixture, and mix well to combine.", "Now add the turmeric powder, garam masala and\u00a0kashmiri red chilli powder and mix well.", "At this stage add the boiled corn, into the gravy, adjust the consistency of the Corn and Peas Curry by adding the required amount of water.", "Add the peas, cover and bring the Corn and Peas Curry to a brisk boil.", "Check the salt and spices at this stage and adjust the taste accordingly.", "Once done, turn off the heat, transfer the\u00a0Corn and Peas Curry Recipe to a bowl and serve hot.", "Serve\u00a0Corn and Peas Curry Recipe along with\u00a0Jeera Rice Recipe,\u00a0Lachedar Kakdi Pyaz Kachumber Recipe - Onion Cucumber Salad\u00a0and finish the meal with\u00a0Paan Matka Kulfi Recipe\u00a0as dessert."]'::jsonb, 55, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sibyl-archanaskitchen.com/Sweet_On_The_Cob_Corn_Peas_Curry_Recipe_Bhutte_Matar_Ki_Sabzi_8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1679.Sweet_On_The_Cob_Corn_Peas_Curry_Recipe_Bhutte_Matar_Ki_Sabzi_8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Beans Mezhukkupuratti Recipe - Kerala Style Stir Fried Beans', 'beans-mezhukkupuratti-recipe-kerala-style-stir-fried-beans', 'The Beans Mezhukkupuratti Recipe is a delicious dish where the beans are tempered with mustard seeds and curry leaves, cooked with onion slices and finished with turmeric powder, pepper powder which adds a beautiful mild flavours to the beans.', '["300 grams Green beans (French Beans) , cut into inch long pieces", "2 Onion , thinly sliced", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "1 sprig Curry leaves", "1/2 teaspoon Turmeric powder (Haldi)", "1 teaspoon Black pepper powder", "1 teaspoon Coconut Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'green beans (french beans)', 'mustard seeds', 'curry leaves', 'onion', 'coconut oil', 'black pepper powder', 'turmeric powder']::text[], '["To begin making the\u00a0Beans Mezhukkupuratti Recipe (Kerala Poriyal), wash and discard the ends of the french beans.", "Cut them into inch long pieces and keep aside.Place the beans in a pressure cooker, add two tablespoon of water and sprinkle some salt.", "Pressure cook the beans for just one whistle and turn off the heat.Release the pressure immediately from the pressure cooker by running it under cold water, to prevent the beans from getting over cooked and losing its green color.Heat oil in a heavy bottomed pan, add the mustard seeds and let it crackle.", "Add the curry leaves and let it splutter.", "Once the curry leaves have spluttered, add the onions and saute the onions until they are tender.Add the steamed beans, turmeric powder, pepper powder, season with salt, mix well and stir fry the Beans Mezhukkupuratti for a couple of minutes.", "Check the salt to taste and adjust accordingly.", "Once done, turn off the heat and transfer the Beans Mezhukkupuratti to a serving bowl.", "Serve the\u00a0Beans Mezhukkupuratti Recipe (Kerala Beans Poriyal) along with Kerala Red or White Rice, Arachuvitta Sambar Recipe, and Elai Vadam for a simple yet delicious Kerala inspired weeknight dinner."]'::jsonb, 25, 'Kerala', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/nithya.anantham/Beans_Mezhukkupuratti_Recipe_-_Kerala_Style_Stir_Fried_Beans_8_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1680.Beans_Mezhukkupuratti_Recipe_-_Kerala_Style_Stir_Fried_Beans_8_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Beetroot Carrot Raita Recipe', 'beetroot-carrot-raita-recipe', 'Beetroot Carrot Raita Recipe is healthy, delicious and beautiful in colour. It can be served with roti, biryani or dal and rice. It is very healthy and is a best recipe to make something new with beetroot and carrot.', '["1/2 cup Carrot (Gajjar) , grated", "1 Beetroot , grated", "2 cups Curd (Dahi / Yogurt)", "1 tablespoon Cumin powder (Jeera) , lightly roasted", "1 tablespoon Red Chilli powder", "Salt , to taste", "1/2 tablespoon Chaat Masala Powder", "Mint Leaves (Pudina) , few for garnishing"]'::jsonb, ARRAY['salt', 'yogurt', 'cumin powder', 'chaat masala powder', 'red chilli powder', 'carrot', 'spoon boil', 'peppermint']::text[], '["To begin making the Beetroot Carrot Raita Recipe, grate the carrots and beetroots and set aside.Meanwhile, whisk yogurt in a bowl, add roasted cumin powder, red chilli powder, chaat masala and salt to taste.Now add grated carrot and beetroot.", "Mix everything well and garnish it with mint leaves.", "Serve cold.Serve Beetroot Carrot Raita Recipe along with\u00a0Peshawari Chole\u00a0and\u00a0Phulkas\u00a0for a weekday lunch or dinner."]'::jsonb, 25, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Beetroot_Pachadi_Recipe-1.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1681.Beetroot_Pachadi_Recipe-1.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Stuffed Yellow Moong Dal And Onion Paratha Recipe', 'stuffed-yellow-moong-dal-and-onion-paratha-recipe', 'Stuffed Yellow Moong Dal And Onion Paratha Recipe is a delicious paratha stuffed with yellow moong dal and crunchy onions and capsicum seasoned with simple dry spices. It can be packed for lunch in the tiffin box, or served for breakfast, lunch or even dinner.', '["1-1/2 Whole Wheat Flour", "Salt , to taste", "1 teaspoon Oil", "Ghee , to cook", "1/2 teaspoon Oil", "1/2 cup Yellow Moong Dal (Split) , washed and soaked", "1/2 cup Green Bell Pepper (Capsicum) , finely chopped", "1 Onion , finely chopped", "1 inch Ginger , finely chopped", "3 cloves Garlic , finely chopped", "1 Green Chilli , finely chopped", "Salt , to taste", "1 teaspoon Red Chilli powder", "1 teaspoon Cumin powder (Jeera)", "1/2 teaspoon Turmeric powder (Haldi)"]'::jsonb, ARRAY['salt', 'wheat flour', 'yellow moong dal (split)', 'ginger', 'green chilli', 'cumin powder (jeera)', 'ghee', 'red chilli powder', 'cloves garlic', 'onion', 'green bell pepper (capsicum)', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the Stuffed Yellow Moong Dal And Onion Paratha Recipe\u00a0, we will first make the dough.\u00a0*For the doughIn a large mixing bowl, combine the wheat flour, and salt and make the paratha dough with the water that the dal was cooked in.Make a firm yet smooth dough.", "Knead well for about 3 to 4 minutes, this will make the parathas soft.", "Drizzle a teaspoon of oil over the dough and knead for another couple of minutes.Set aside and allow it to rest.\u00a0*For the Yellow Moong Dal With Roasted Capsicum & Onion fillingFirstly wash and soak the Moong Dal for 30 minutes.", "Drain the soaked water.In a pan, add the washed and soaked dal, with salt, haldi and 1/2 cup of water into the pressure cooker.", "Pressure cook the dal for 2 whistles and turn off the heat.Allow the pressure to release naturally and allow the dal to cool.", "If there is any excess water, drain the water from the dal and keep the cooked yellow moong dal aside.Heat a small pan with oil on medium flame, add the ginger, garlic green chilli and saute for 30 seconds.", "Next add the onions and the capsicum and cook for 3-4 minutes until soft.At this stage add the boiled dal, red chilli powder, cumin powder, turmeric powder, salt and mix well and set aside.\u00a0*To make the Stuffed Yellow Moong Dal And Onion Paratha RecipeKeep some flour aside for dusting.", "Divide the dough into large lemon sized balls.Dust the dough portions in flour, flatten it and roll it into a 3 inch diameter circle.Place about 2 tablespoons of the yellow moong dal stuffing in the center, gather the edge and seal it.", "Carefully roll it out the paratha into a circle about 6-7 inches in diameter.Heat a skillet over medium heat and cook the Stuffed Yellow Moong Dal And Onion Paratha in ghee until cooked through, and has golden brown spots on both sides.Repeat with the remaining portions of the dough and the Yellow Moong Dal With Roasted Capsicum & Onion filling.Serve this\u00a0Stuffed Yellow Moong Dal And Onion Paratha Recipe\u00a0with\u00a0Coriander Tadka Raita\u00a0and\u00a0Green Chilli Pickle\u00a0for a simple and wholesome meal."]'::jsonb, 40, 'North Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/sneha-archanaskitchen.com/Yellow_Moong_Dal_With_Roasted_Capsicum__Onion_Paratha_Recipe_.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1682.Yellow_Moong_Dal_With_Roasted_Capsicum__Onion_Paratha_Recipe_.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Masala Karela Recipe', 'masala-karela-recipe', 'Tangy Masala Karela Recipe combines karela with everyday indian spices and amchur powder. This easy-to-prepare healthy Karela recipe combines flavours to make it taste good without adding jaggery to reduce the acridity of the bitter gourd. It is a great diabetic friendly recipe and this dry sabzi pairs well with Tawa Paratha, roti, naan or any paratha of your choice.', '["6 Karela (Bitter Gourd/ Pavakkai) , deseeded, sliced", "Salt , to taste", "1 Onion , thinly sliced", "3 tablespoon Gram flour (besan)", "2 teaspoons Turmeric powder (Haldi)", "1 tablespoon Red Chilli powder", "2 teaspoons Cumin seeds (Jeera)", "1 tablespoon Coriander Powder (Dhania)", "1 tablespoon Amchur (Dry Mango Powder)", "Oil , as required"]'::jsonb, ARRAY['salt', 'amchur (dry mango powder)', 'karela (bitter gourd pavakkai)', 'red chilli powder', 'gram flour (besan)', 'onion', 'cumin seeds (jeera)', 'coriander powder', 'turmeric powder', 'sunflower oil']::text[], '["To begin making the\u00a0Masala Karela Recipe,de-seed the karela and slice.", "Do not remove the skin as the skin has all the nutrients.", "Add the karela to the pressure cooker with 3 tablespoon of water, salt and turmeric powder and pressure cook for three whistles.", "Release the pressure immediately and open the lids.", "Keep aside.Heat oil in a heavy bottomed pan or a kadhai.", "Add cumin seeds and let it sizzle.Once the cumin seeds have sizzled, add onions and saute them till it turns golden brown in color.Add the karela,\u00a0red chilli powder, amchur powder, coriander powder and besan.", "Stir to combine the masalas into the karela.Drizzle a little extra oil on the top and mix again.", "Cover the pan and simmer\u00a0Masala Karela stirring occasionally until everything comes together well.", "Turn off the heat.Transfer\u00a0Masala Karela into a serving bowl and serve.Serve\u00a0Masala Karela\u00a0along with\u00a0Panchmel Dal\u00a0and\u00a0Phulka\u00a0for a weekday meal with your family."]'::jsonb, 45, 'Indian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/Pooja_Thakur/Karela_Masala_Recipe-4_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1683.Karela_Masala_Recipe-4_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Masala Jowar Bhakri Recipe', 'masala-jowar-bhakri-recipe', 'Masala Jowar Bhakri Recipe is made from Jowar, a millet variety that is gluten free. Jowar Bhakri is a traditional breakfast that is popular in Maharashtra and parts of Karnataka. It is popularly called farmer''s breakfast. The Bhakri dough is shaped using hand which requires little skill and practice. Instead of shaping the bhakri directly on the tava, you can grease a banana leaf or parchment paper and shape them. Invert the dough side on to the hot tawa and slowly remove the banana leaf/parchment paper.', '["1 cup Jowar Flour (Sorghum)", "1 Onion , finely chopped", "1 Green Chilli , finely chopped", "Coriander (Dhania) Leaves , a handful, finely chopped", "1 sprig Curry leaves , finely chopped", "1 teaspoon Sesame seeds (Til seeds)", "1/2 teaspoon Ajwain (Carom seeds)", "2 teaspoons Oil", "Salt , to taste"]'::jsonb, ARRAY['salt', 'green chilli', 'coriander (dhania) leaves', 'jowar flour (sorghum)', 'ajwain (carom seeds)', 'curry leaves', 'onion', 'sesame seeds (til seeds)', 'sunflower oil']::text[], '["To begin making Masala Jowar Bhakri Recipe, in a large mixing bowl, add the jowar flour, salt and mix well.Add the chopped onions, green chillies, coriander leaves, and curry leaves to the bowl and mix well.Pour warm water little by little to make a smooth and soft dough.", "Divide the dough into equal size balls.Grease a tava with oil and heat.Take one ball and place it on the greased tava.Wet your fingers and spread the dough to make a bhakri.Place the tawa on medium heat and drizzle oil on the sides of the bhakri.Once the bhakri starts to brown on the sides, flip them.You can cover and cook the other side for another 2-3 minutes.Remove the bhakri from the tawa and hold the back of the tawa under running water to cool it down.Once the tava is cool, grease and repeat the above process for the remaining dough.Healthy, nutritious and wholesome Masala Jowar Bhakri is ready to be served.Serve with Hurali Kalu Chutney Recipe, Paruppu Thogayal Recipe or a tangy gravy like Senai Kizhangu Ghostu Recipe."]'::jsonb, 35, 'Maharashtrian', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/1-Author/umar/Masala_Jowar_Bhakri.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1684.Masala_Jowar_Bhakri.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('Gujarati Palak Dhokla Recipe - Steamed Spinach Lentil Cakes', 'gujarati-palak-dhokla-recipe-steamed-spinach-lentil-cakes', 'The Gujarati Palak Dhokla is a delicious steamed lentil cake recipe made with spinach puree is an all time Gujarati favorite snack. You can make this recipe using fresh lentils like bengal gram dal or even a mixture of dals or you could alternatively make it really quick using gram flour that tastes just as delicious.', '["1 cup Gram flour (besan)", "Spinach Leaves (Palak) , 2 bunches", "1/4 cup Hung Curd (Greek Yogurt) , whisked well", "1 inch Ginger", "3 Green Chillies", "2 tablespoons Oil", "1 tablespoon Lemon juice", "1 tablespoon Sugar , (optional)", "Salt , to taste", "1 teaspoon Enos Fruit Salt", "Ingredients for the Seasoning", "2 teaspoons Oil", "1 teaspoon Mustard seeds (Rai/ Kadugu)", "2 teaspoons Sesame seeds (Til seeds)", "5 Curry leaves", "1/4 teaspoon Asafoetida (hing)", "3 tablespoons Water"]'::jsonb, ARRAY['gram flour', 'besan', 'spinach leaves', 'palak', 'hung curd', 'greek yogurt', 'ginger', 'reen chillies', 's oil', 'lemon juice', 'sugar', 'salt', 'enos fruit salt', 'ingredients for the seasoning', 'mustard seeds', 'rai/ kadugu', 's sesame seeds', 'til seeds', 'curry leaves', 'asafoetida', 'hing', 's water']::text[], '["To begin making the Gujarati Palak Dhokla Recipe, blanch or steam the spinach leaves along with stalk.", "Allow it to cool.", "Once cooled puree it along with ginger and green chilies in a mixer grinder.", "Puree should be around 1 cup.", "Do add in the spinach stalks as they add more fiber.In a wide bowl, add in the gram flour, spinach puree, curd and oil.", "Mix well.", "Add a little water at a time to make a batter.", "The batter should be of dropping consistency, neither too thin nor too thick.Now add in salt, sugar (if using) and lemon juice and mix well so that there are no lumps in the batter.", "Let the batter rest for about 5 to 10 minutes.Meanwhile grease a steamer plates and keep it ready.", "Prepare the steamer with water and keep aside.Once the batter has rested, stir in the fruit salt and mix well without beating it too much.", "Just mix until the fruit salt is combined well into the batter.", "Immediately pour the batter in the greased plates and place it into the steamer for for steaming.Steam on high in the steamer for around 15-20 minutes until when a tester inserted inside comes out clean.Remove the steamed palak dhokla''s from the steamer and allow it cool for 10 minutes.", "Heat oil in a small pan; add asafoetida, mustard seeds, sesame seeds, curry leaves and allow them to crackle.", "Turn off the heat and gradually add the 3 tablespoons of water to the seasoning.", "Take care as the \u00a0oil will start spluttering.", "Adding water is necessary as it helps in keeping the dhokla soft and moist.Drizzle this seasoning on top of the Gujarati Palak Dhokla.", "Cut the dhokla into square pieces and serve warm.Serve\u00a0Gujarati Palak Dhokla with\u00a0Green Chutney Recipe - Coriander Mint Chutney Recipe\u00a0for breakfast or an evening snack."]'::jsonb, 50, 'Gujarati', 'veg', 'https://www.archanaskitchen.com/images/archanaskitchen/Indian_Breakfast_Tiffins/Gujarati_Palak_Dhokla_Recipe_Steamed_Spinach_Lentil_Cakes-1_1600.jpg', 'https://mbhceqllbamrwlsiimgu.supabase.co/storage/v1/object/public/recipe-images/1685.Gujarati_Palak_Dhokla_Recipe_Steamed_Spinach_Lentil_Cakes-1_1600.jpg', 'verified', 'supabase-storage', 'cuisines-csv', 4, 0, false),
  ('गुजराती पालक ढोकला रेसिपी - Gujarati Palak Dhokla Recipe', 'gujarati-palak-dhokla-recipe', 'ढोकला एक बहुत ही प्रसिद्ध रेसिपी है जिसे गुजरात के हर घर में बनाया जाता है. इसे या तो खाने के साथ साइड डिश के लिए परोसा जाता है या नाश्ते में परोसा जाता है. गुजरात के हर फरसान दूकान पर आपको ढोकला जरूर मिलेगा। यहाँ हम गुजराती पालक ढोकला रेसिपी बनाएंगे जिसे बेसन से बनाया गया है और इसमें पालक की प्यूरी भी मिलाई गई है, जिससे ढोकले में स्वाद और पोषण बढ़ता है.', '["1 \u0915\u092a \u092c\u0947\u0938\u0928", "300 \u0917\u094d\u0930\u093e\u092e \u092a\u093e\u0932\u0915", "1/4 \u0915\u092a \u0939\u0902\u0917 \u0926\u0939\u0940 , \u092b\u0947\u091f \u0932\u0947", "1 \u0907\u0902\u091a \u0905\u0926\u0930\u0915", "3 \u0939\u0930\u0940 \u092e\u093f\u0930\u094d\u091a", "2 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0928\u093f\u092e\u094d\u092c\u0942 \u0915\u093e \u0930\u0938", "1 \u092c\u095c\u093e \u091a\u092e\u094d\u092e\u091a \u0936\u0915\u094d\u0915\u0930 , \u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915", "\u0928\u092e\u0915 , \u0938\u094d\u0935\u093e\u0926 \u0905\u0928\u0941\u0938\u093e\u0930", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0907\u0928\u094b \u092b\u094d\u0930\u0942\u091f \u0938\u093e\u0932\u094d\u091f", "\u0924\u095c\u0915\u0947 \u0915\u0947 \u0932\u093f\u090f", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u0947\u0932", "1 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0930\u093e\u0907", "2 \u091b\u094b\u091f\u0947 \u091a\u092e\u094d\u092e\u091a \u0924\u093f\u0932 (\u0938\u095e\u0947\u0926)", "5 \u0915\u095d\u0940 \u092a\u0924\u094d\u0924\u093e", "1/4 \u091b\u094b\u091f\u093e \u091a\u092e\u094d\u092e\u091a \u0939\u0940\u0902\u0917", "3 \u092c\u095c\u0947 \u091a\u092e\u094d\u092e\u091a \u092a\u093e\u0928\u0940"]'::jsonb, ARRAY['कप बेसन', 'ग्राम पालक', 'कप हंग दही', 'इंच अदरक', 'हरी मिर्च', 'बड़े चम्मच तेल', 'बड़ा चम्मच निम्बू का रस', 'बड़ा चम्मच शक्कर', 'नमक', 'छोटा चम्मच इनो फ्रूट साल्ट', 'तड़के के लिए', 'छोटे चम्मच तेल', 'छोटा चम्मच राइ', 'छोटे चम्मच तिल', 'सफ़ेद', 'कढ़ी पत्ता', 'छोटा चम्मच हींग', 'बड़े चम्मच पानी']::text[], '["\u0917\u0941\u091c\u0930\u093e\u0924\u0940 \u092a\u093e\u0932\u0915 \u0922\u094b\u0915\u0932\u093e \u0930\u0947\u0938\u093f\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0938\u0949\u0938\u092a\u0948\u0928 \u092e\u0947\u0902 \u092a\u093e\u0928\u0940 \u0909\u092c\u093e\u0932 \u0932\u0947. \u0909\u092c\u093e\u0932\u093e \u0906\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0917\u0948\u0938 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0909\u0938\u092e\u0947 \u092a\u093e\u0932\u0915 \u0921\u093e\u0932 \u0932\u0947 \u0914\u0930 4 \u0938\u0947 5 \u092e\u093f\u0928\u091f \u0924\u0915 \u0930\u0939\u0928\u0947 \u0926\u0947.\u00a0\u0928\u093f\u0915\u093e\u0932\u0947 \u0914\u0930 \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0926\u0947. \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u090f\u0915 \u092e\u093f\u0915\u094d\u0938\u0930 \u0917\u094d\u0930\u093e\u0907\u0902\u0921\u0930 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092a\u094d\u092f\u0942\u0930\u0940 \u092c\u0928\u093e \u0932\u0947. \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u092c\u0947\u0938\u0928, \u092a\u093e\u0932\u0915 \u0915\u0940 \u092a\u094d\u092f\u0942\u0930\u0940, \u0926\u0939\u0940, \u0924\u0947\u0932, \u0925\u094b\u095c\u093e \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u092c\u0948\u091f\u0930 \u092c\u0928\u093e \u0932\u0947. \u0927\u094d\u092f\u093e\u0928 \u0930\u0916\u0947\u0902 \u091c\u094d\u092f\u093e\u0926\u093e \u092a\u0924\u0932\u093e \u0928 \u092c\u0928\u093e\u090f\u0964\u0905\u092c \u0907\u0938\u092e\u0947\u0902 \u0928\u092e\u0915, \u0936\u0915\u094d\u0915\u0930, \u0928\u093f\u092e\u094d\u092c\u0942 \u0915\u093e \u0930\u0938 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u092e\u093f\u0932\u093e \u0932\u0947. \u0927\u094d\u092f\u093e\u0928 \u0930\u0916\u0947\u0902 \u0907\u0938 \u092e\u093f\u0936\u094d\u0930\u0923 \u092e\u0947\u0902 \u0917\u093e\u0920\u0947\u0902 \u0928 \u0939\u094b. 5 \u0938\u0947 10 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u0905\u092c \u090f\u0915 \u0938\u094d\u091f\u0940\u092e\u0930 \u0932\u0947 \u0914\u0930 \u0909\u0938\u0915\u0940 \u092a\u094d\u0932\u0947\u091f \u0915\u094b \u0918\u0940 \u092f\u093e \u0924\u0947\u0932 \u0938\u0947 \u0917\u094d\u0930\u0940\u0938 \u0915\u0930 \u0932\u0947. \u0938\u094d\u091f\u0940\u092e\u0930 \u092e\u0947\u0902 \u0928\u093f\u091a\u0947 \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0947 \u0914\u0930 \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a010 \u092e\u093f\u0928\u091f \u0915\u0947 \u092c\u093e\u0926 \u0922\u094b\u0915\u0932\u0947 \u0915\u0947 \u092e\u093f\u0936\u094d\u0930\u0923 \u092e\u0947\u0902 \u0907\u0928\u094b \u092b\u094d\u0930\u0942\u091f \u0938\u093e\u0932\u094d\u091f \u0921\u093e\u0932\u0947 \u0914\u0930 \u092e\u093f\u0932\u093e \u0932\u0947. \u0907\u0938 \u092e\u093f\u0936\u094d\u0930\u0923 \u0915\u094b \u0938\u094d\u091f\u0940\u092e\u0930 \u092a\u094d\u0932\u0947\u091f \u092e\u0947\u0902 \u0921\u093e\u0932\u0947 \u0914\u0930 15 \u0938\u0947 20 \u092e\u093f\u0928\u091f \u0915\u0947 \u0932\u093f\u090f \u0938\u094d\u091f\u0940\u092e \u0915\u0930 \u0932\u0947. \u0905\u091a\u094d\u091b\u0940 \u0924\u0930\u0939 \u0938\u0947 \u0938\u094d\u091f\u0940\u092e \u0939\u094b \u091c\u093e\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 10 \u092e\u093f\u0928\u091f \u0920\u0902\u0921\u093e \u0939\u094b\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0905\u0932\u0917 \u0938\u0947 \u0930\u0916 \u0926\u0947.\u00a0\u09